import { Injectable } from "@angular/core";
import { StatusResolverBase, StatusLabel, FOR_TRANSLATION_STATUS_NAME, NEWER_THAN_PUBLISHED, SCHEDULED, PUBLISHED, UNPUBLISHED, AWAITING_APPROVAL, AWAITING_PUBLISHING, REJECTED, REJECTED_FOR_PUBLISHING, DRAFT } from "./base-status.resolver";
import { RelativeDatePipe } from "../../src/app/modules/shared/pipes/relative-date.pipe";
import { ENTITY_SET } from "../../src/app/modules/shared/services/metadata/meta-data-constants";

const NON_DEFAULT_SETS = [
    ENTITY_SET.CLASSIFICATIONS,
    ENTITY_SET.ALBUMS,
    ENTITY_SET.IMAGES,
    ENTITY_SET.DOCUMENT_LIBRARIES,
    ENTITY_SET.DOCUMENTS,
    ENTITY_SET.VIDEO_LIBRARIES,
    ENTITY_SET.VIDEOS,
    ENTITY_SET.CONTENT_ITEMS
];

@Injectable()
export class StatusResolver extends StatusResolverBase {
    // TODO: localize strings in this class

    getLabel(item: any): StatusLabel {
        const statusInfo = this.getStatusInfo(item);
        const mainStatus = statusInfo.main;
        const secondaryStatus = statusInfo.secondary;
        if (!mainStatus)
            return null;

        let statusName = mainStatus.Name;
        let label = this.getStatusLabel(mainStatus);

        if (secondaryStatus) {
            label = `${label} | ${this.getStatusLabel(secondaryStatus)}`;
        }

        if (item.LockedStatus) {
            label = this.getLockedByLabel(item.LockedStatus.User, label);
        }

        const isForTranslation: boolean = this.isForTranslation(item);
        statusName = isForTranslation ? FOR_TRANSLATION_STATUS_NAME : statusName;

        return {
            StatusName: statusName,
            Label: label
        };
    }

    canProcess(setName: string): boolean {
        return NON_DEFAULT_SETS.indexOf(setName) === -1;
    }

    getDetailedLabel(item: any): any {
        let firstDateData = null;
        let secondDateData = null;
        let statusTextWithDate = null;

        // TODO: dates are served as strings, but from a specific version of the SDK, they are served as Date objects
        const statusInfo = this.getStatusInfo(item);
        const mainStatus = statusInfo.main;

        if (mainStatus) {
            statusTextWithDate = this.getDetailedStatus(mainStatus.DetailedLabel, mainStatus.Date);

            switch (mainStatus.Name) {
                case PUBLISHED:
                    firstDateData = this.getLastModifiedData(item);
                    secondDateData = this.getFirstPublishedData(item);
                    break;
                case UNPUBLISHED:
                    firstDateData = this.getStatusData(mainStatus);
                    secondDateData = this.getFirstPublishedData(item);
                    break;
                case AWAITING_APPROVAL:
                case AWAITING_PUBLISHING:
                case REJECTED:
                case REJECTED_FOR_PUBLISHING:
                    firstDateData = this.getStatusData(mainStatus);
                    secondDateData = this.getCreatedData(item);
                    break;
                case DRAFT:
                default:
                    firstDateData = this.getLastModifiedData(item);
                    secondDateData = this.getCreatedData(item);
                    break;
            }
        } else {
            statusTextWithDate = this.getDetailedStatus("Last modified", item.LastModified);
            firstDateData = this.getLastModifiedData(item);
            secondDateData = this.getCreatedData(item);
        }

        return {
            StatusText: statusTextWithDate,
            FirstDate: firstDateData,
            SecondDate: secondDateData,
            LockedText: null
        };
    }

    getDetailedStatusText(item: any) {
        const mainStatus = this.getStatusInfo(item).main;

        return this.getDetailedStatus(mainStatus.DetailedLabel, mainStatus.Date);
    }

    protected getDetailedStatus(statusText: string, date: string) {
        const formattedDate = this.formatDate(date, RelativeDatePipe.AUTO_DETAILED);

        const ret = `${statusText} ${formattedDate}`;

        return ret;
    }

    protected getStatusInfo(item: any): { main: any, secondary: any } {
        const result = {
            main: null,
            secondary: null
        };

        const statuses = item.DisplayStatus;
        if (statuses && statuses.length > 0) {
            result.main = statuses[0];

            if (statuses.length > 1) {
                result.secondary = statuses[1];
            }
        }

        return result;
    }

    private getStatusLabel(status: any): string {
        const statusName = status.Name;
        let label = status.Label;

        if (statusName === SCHEDULED) {
            let pubDateFormatted = null;
            let expDateFormatted = null;

            if (status.PublicationDate) {
                pubDateFormatted = this.formatDate(status.PublicationDate, RelativeDatePipe.FULL_DATE);
            }

            if (status.ExpirationDate) {
                expDateFormatted = this.formatDate(status.ExpirationDate, RelativeDatePipe.FULL_DATE);
            }

            if (label && label.endsWith(NEWER_THAN_PUBLISHED)) {
                label = `${this.getScheduledLabel(pubDateFormatted, expDateFormatted)}, ${NEWER_THAN_PUBLISHED}`;
            } else {
                label = this.getScheduledLabel(pubDateFormatted, expDateFormatted);
            }
        }

        return label;
    }

    private getLastModifiedData(item: any): any {
        return {
            Name: "Last modified",
            Date: this.formatToFullDate(item.LastModified),
            User: item.LastModifiedBy
        };
    }

    private getCreatedData(item: any): any {
        return {
            Name: "Created",
            Date: this.formatToFullDate(item.DateCreated),
            User: item.CreatedBy
        };
    }

    private getFirstPublishedData(item: any): any {
        if (!item.FirstPublished)
            return null;

        return {
            Name: "First published",
            Date: this.formatToFullDate(item.FirstPublished.Date),
            User: item.FirstPublished.User
        };
    }

    private getStatusData(mainStatus: any): any {
        return {
            Name: mainStatus.DetailedLabel,
            Date: this.formatToFullDate(mainStatus.Date),
            User: mainStatus.User
        };
    }

    private formatToFullDate(date: string): string {
        return this.formatDate(date, RelativeDatePipe.FULL_DATE);
    }

    private formatDate(date: string, dateFormat: string = null): string {
        if (date) {
            let ret = this.datePipe.transform(date, dateFormat);
            ret = this.lowerFirstLetterPipe.transform(ret);
            return ret;
        }

        return date;
    }

    private getLockedByLabel(lockedBy: string, uiStatus: string): string {
        return `Locked by ${lockedBy} | ${uiStatus}`;
    }

    private getScheduledLabel(pubDate: string, expDate: string): string {
        if (pubDate && !expDate) {
            return `Scheduled publish ${pubDate}`;
        } else if (expDate && !pubDate) {
            return `Scheduled unpublish ${expDate}`;
        } else if (expDate && pubDate)
            return `Scheduled publish ${pubDate}, unpublish ${expDate}`;

        return null;
    }

    private isForTranslation(item: any) {
        if (item && item.DisplayStatus) {
            return item.DisplayStatus.some(status => status.Name.toLowerCase().indexOf(FOR_TRANSLATION_STATUS_NAME.toLowerCase()) > -1);
        }

        return false;
    }
}
