import { Component, Input, OnInit } from "@angular/core";
import { DataItem } from "../../../../api";
import { DataContext, DataContextComponent } from "../../models/data-context-component";

const ICON_LOOK: string = "size-m sf-mr-4xs";

@Component({
    selector: "sf-error-status",
    templateUrl: "./error-status.component.html"
})
export class ErrorStatusComponent implements OnInit, DataContextComponent  {
    @Input() public context: DataContext;
    @Input() public errorLabel: string;
    @Input() public successStatus: string;

    public status: string;
    public iconName: string = "times-circle";
    public iconLook: string = `${ICON_LOOK} negative`;
    public result: string;

    ngOnInit(): void {
        const dataItem = this.context.dataItem;
        this.setStatus(dataItem);
        this.result = dataItem.data.Result;

        this.setIconLook();
    }

    private setIconLook() {
        if (this.status === this.successStatus) {
            this.iconName = "check-circle";
            this.iconLook = `${ICON_LOOK} positive`;
        }
    }

    private setStatus(dataItem: DataItem) {
        if (dataItem.data && dataItem.data.Status) {
            this.status = dataItem.data.Status;
        } else {
            const model = this.context.model;
            this.status = dataItem.data[model.name];
        }
    }
}
