import { Component, EmbeddedViewRef, Inject, Input, OnChanges, OnDestroy, SimpleChanges } from "@angular/core";
import { ViewChild } from "@angular/core";
import { ViewContainerRef } from "@angular/core";
import { WINDOW_TOKEN } from "../../src/app/window.provider";

const DROPDOWN_MARGIN_VERTICAL = 20;
const DROPDOWN_MARGIN_HORIZONTAL = 10;

@Component({
    selector: "sf-insert-body",
    template:
        `
            <ng-template #contentRef>
                <div [attr.data-container]="containerName" [ngStyle]="{ 'transform': dropdownTransition }"
                     class="sf-insert-body"
                     sfRespondToVisibility
                     (elementIsVisible)="onElementIsVisible($event)">
                    <ng-content></ng-content>
                </div>
            </ng-template>
        `
})
export class InsertBodyComponent implements OnChanges, OnDestroy {

    @Input() referenceNodeBoundingRect: DOMRect;
    @Input() leftAligned: boolean;
    @Input() containerName: string;
    @ViewChild("contentRef", { static: true }) contentRef;

    dropdownTransition: string;
    private viewContainerRef: ViewContainerRef;
    private embeddedViewRef: EmbeddedViewRef<any>;
    private dropdownTransitionX: number = 0;
    private dropdownTransitionY: number = 0;

    constructor( viewContainerRef: ViewContainerRef, @Inject(WINDOW_TOKEN) private window: Window ) {
        this.viewContainerRef = viewContainerRef;
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes && changes.referenceNodeBoundingRect && changes.referenceNodeBoundingRect.currentValue) {
            this.embedNodeInDom();
        }
    }

    ngOnDestroy() {
        for (const node of this.embeddedViewRef.rootNodes) {
            node.remove();
        }
    }

    calculateDropdownPosition(node: HTMLElement) {
        const dropdownBoundingRect = node.getBoundingClientRect();
        if (this.leftAligned) {
            this.dropdownTransitionX = this.referenceNodeBoundingRect.left;
        } else {
            this.dropdownTransitionX = this.referenceNodeBoundingRect.right - dropdownBoundingRect.width;
        }

        const freeSpaceBelowTheButton = this.window.document.documentElement.clientHeight - this.referenceNodeBoundingRect.bottom;

        //// If there is no space below the button, the menu should be positioned at its right side.
        if (freeSpaceBelowTheButton > dropdownBoundingRect.height) {
            this.dropdownTransitionY = this.referenceNodeBoundingRect.bottom + window.scrollY;
        } else {
            this.dropdownTransitionY = (this.referenceNodeBoundingRect.bottom - (dropdownBoundingRect.height - freeSpaceBelowTheButton)) + window.scrollY - DROPDOWN_MARGIN_VERTICAL;
            this.dropdownTransitionX = this.referenceNodeBoundingRect.left - dropdownBoundingRect.width - DROPDOWN_MARGIN_HORIZONTAL;
        }
        this.setDropdownTransition();
    }

    setDropdownTransition() {
        this.dropdownTransition = "translate(" + this.dropdownTransitionX + "px," + this.dropdownTransitionY  + "px)";

    }

    onElementIsVisible(target: HTMLElement) {
        //adjust dropdown if it gets outside the viewport
        const dropdownBoundingRect = target.getBoundingClientRect();

        //// If there is no size do not show the content as it will cause twiches
        if (dropdownBoundingRect.width === 0 && dropdownBoundingRect.height === 0) {
            return;

        }

        this.calculateDropdownPosition(target);
        target.style.visibility = "visible";
    }

    embedNodeInDom() {
        // Render the TemplateRef as a SIBLING to THIS component.
        this.embeddedViewRef = this.viewContainerRef.createEmbeddedView(this.contentRef);
        this.embeddedViewRef.detectChanges();

        for (const node of this.embeddedViewRef.rootNodes) {
           const wrapper = this.window.document.body.querySelector("sf-app") || this.window.document.body;
           wrapper.appendChild(node);
           this.calculateDropdownPosition(node);
        }
    }
}
