import { Component, Input, OnInit, EventEmitter, Output } from "@angular/core";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { DataContext } from "../../../../shared/models/data-context-component";
import { COMMAND_NAMES } from "../commands";

@Component({
    selector: "sf-create-child",
    templateUrl: "./create-child.component.html"
})
export class CreateChildComponent implements OnInit {

    @Input() public context: DataContext;
    public childTypeName: string;

    // TODO: remove
    @Output() public onClick = new EventEmitter<string>();

    private childSetName: string;

    constructor(private metadata: MetadataStore) { }

    public ngOnInit(): void {
        const dataItem = this.context.dataItem;
        const entityName = dataItem.metadata.setName;

        this.metadata.initialize().subscribe(metaContainer => {
            const entity = metaContainer.entities[entityName];
            if (!entity)
               return;

            if (!entity.hasChildren)
                return;

            if (entity.children.length !== 1)
                return;

            this.childSetName = entity.children[0];

            this.childTypeName = metaContainer.entities[this.childSetName].singularName;
        });
    }

    public onCreateClick(): void {
        this.onClick.emit(this.childSetName);

        const invoker = this.context.invoker;
        invoker.invoke({
            name: COMMAND_NAMES.createChild,
            data: {
                childSetName: this.childSetName,
                dataItem: this.context.dataItem
            }
        });
    }
}
