import { Input, Component, OnChanges, SimpleChanges, Output, EventEmitter, Inject, OnInit, ElementRef, ViewChild } from "@angular/core";
import { SafeUrl } from "@angular/platform-browser";
import { MediaRecognizerService } from "./media/media-recognizer.service";
import { FileInfo } from "../shared/services/metadata/files/file-info.service";
import { MediaHandler } from "./media-handlers/media-handler.provider";
import { ActivatedRoute } from "@angular/router";
import { EntityData, DataItem } from "../content/dynamic-modules/interfaces";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { createFileWithBase64 } from "../../utils";
import { ContentCultureData } from "../shared/services/metadata/site-data.store";
import { SfDynamicComponentLoaderComponent, SfRxBase } from "@progress/sitefinity-component-framework";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { EXTENSIONS, MIME_TYPES } from "./services/media.helpers";

@Component({
    selector: "sf-file-preview",
    templateUrl: "./file-preview.component.html"
})
export class FilePreviewComponent extends SfRxBase implements OnChanges, OnInit {
    @ViewChild("fileInput") input: ElementRef;
    @ViewChild("loader", { static: false }) loader: SfDynamicComponentLoaderComponent;

    @Input() multiple: boolean;
    @Input() mediaEntityData: EntityData;
    @Input() item: any;
    @Input() editable: boolean = false;
    @Input() mediaDataItem: DataItem;
    @Input() showMediaDetails = true;
    @Output() onFilesSelected = new EventEmitter();

    src: SafeUrl;
    previewerData: ComponentData;
    propertiesButtonTitle: string;
    editOperations: string[];

    private currentMediaHandler: MediaHandler;
    private siteLanguages: Array<ContentCultureData>;

    constructor(private mediaRecognizerService: MediaRecognizerService,
                @Inject(MediaHandler) private mediaHandlers: MediaHandler[],
                private route: ActivatedRoute) {
        super();
    }

    @Input()
    set dataURL(dataURL: string) {
        this.initPreviewerData(dataURL);
    }

    ngOnInit(): void {
        this.siteLanguages = this.route.parent ? this.route.parent.snapshot.data.siteDataStore.ContentCultures : [];
        this.currentMediaHandler = this.mediaHandlers.find(h => h.canHandle(this.mediaEntityData));
        this.editOperations = this.currentMediaHandler.getEditOperations(this.item, undefined, this.siteLanguages, this.isDamMedia());
        this.propertiesButtonTitle = `${this.mediaEntityData.metadata.singularName} settings`;
        this.previewerData.properties.multiple = this.multiple;
        if (this.isVideo && this.editable) {
            this.previewerData.properties.look = "play-detached";
        } else if (this.isImage && this.editable) {
            this.previewerData.properties.look = "view-in-edit";
        }
    }

    get isVideo(): boolean {
        return this.mediaEntityData.metadata.setName === ENTITY_SET.VIDEOS;
    }

    get isImage(): boolean {
        return this.mediaEntityData.metadata.setName === ENTITY_SET.IMAGES;
    }

    get isSvg() {
        return this.item && (this.item.contentType === MIME_TYPES.SVG || this.item.extension === EXTENSIONS.SVG);
    }

    get hideImageBackground() {
        return this.mediaDataItem?.data?.hideBackground || this.route.parent?.snapshot?.data?.dynamicTypeName === ENTITY_SET.PRESETS;
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes) {
            const itemChange = changes["item"];
            if (itemChange && !itemChange.isFirstChange()) {
                this.editOperations = this.currentMediaHandler.getEditOperations(this.item, undefined, this.siteLanguages, this.isDamMedia());
                this.initPreviewerData(itemChange.currentValue.dataUrl);
            }
        }
    }

    onEditOperationClick(operation: string, event): void {
        event.stopPropagation();
        if (this.isVideo) {
            this.loader.currentInstance.isLoaded = false;
        }
        this.currentMediaHandler.executeOperation({
            operationName: operation,
            item: this.item,
            route: this.route,
            mediaDataItem: this.mediaDataItem,
            input: this.input.nativeElement
        }).subscribe(data => {
            if (data === null) {
                if (this.isVideo) {
                    this.loader.currentInstance.isLoaded = true;
                }
            } else {
                if (data.dataUrl) {
                    const dataUrl = data.dataUrl;
                    const fileExtension = this.item.extension[0] === "." ? this.item.extension : `.${this.item.extension}`;
                    const file = createFileWithBase64(dataUrl, `${this.item.title}${fileExtension}`);
                    const fileList: any = [file];

                    this.onFilesSelected.emit({files: fileList});
                    this.initPreviewerData(dataUrl);
                }

                if (data.files) {
                    this.onFilesSelected.emit({files: data.files, preserveFileName: data.preserveFileName, originalFileNames: data.originalFileNames});
                }
            }
        });
    }

    private initPreviewerData(dataURL: string): void {
        const componentProperties = {
            item: this.item,
            src: dataURL,
            multiple: this.multiple,
            isMultimedia: this.mediaEntityData.metadata.isMultimedia,
            type: this.item.contentType,
            isVideo: this.isVideo
        };
        if (this.isVideo && this.editable) {
            componentProperties["look"] = "play-detached";
        } else if (this.isImage && this.editable) {
            componentProperties["look"] = "view-in-edit";
        }
        this.previewerData = this.mediaRecognizerService.getComponentData(componentProperties);
        this.previewerData.updatePropertiesOnChange = true;
        this.previewerData.afterComponentInit = (component) => {
            if (component.error) {
                const errorSubscription = component.error.subscribe(() => {
                    this.editOperations = this.currentMediaHandler.getEditOperations(this.item, true, this.siteLanguages, this.isDamMedia());
                });

                this.registerSubscription(errorSubscription);
            }
        };
    }

    private isDamMedia(): boolean {
        if (this.mediaDataItem && this.mediaDataItem.data) {
            return this.mediaDataItem.data.IsDamMedia;
        }

        return false;
    }
}

export interface ViewModel {
    mediaDataItem: DataItem;
    file: FileInfo;
}
