import { Component, ViewChild } from "@angular/core";
import { CompositeThemeProvider } from "./composite-theme-provider";
import { ThemeItem } from "./theme-item";
import { TreeWrapperComponent, TreeConfig } from "../../../fields";
import { TreeNode } from "@circlon/angular-tree-component";
import { ConfirmButton } from "../modules/shared/services/modal-window.service";
import { BLUR_EFFECT_TIMEOUT, LOADING_TIME } from "../modules/content/constants";

 const BUTTON_LOADER_LOOK = "transparent";
const BUTTON_TITLE = "Use selected";

@Component({
    templateUrl: "./theme.component.html"
})
export class ThemeComponent {
    @ViewChild("tree", { static: true }) tree: TreeWrapperComponent;

    public treeConfig: TreeConfig = {
        treeProperties: {
            idField: "id"
        }
    };
    public selectButton: any;

    private selectedTheme: ThemeItem;

    constructor(public themeProvider: CompositeThemeProvider) {
        this.selectButton = new ConfirmButton(BUTTON_TITLE);
    }

    onTreeInitialized() {
        this.tree.selectAndActivateNodeById(this.themeProvider.appliedTheme.id.toString());
    }

    onTreeNodeClicked(selectedItem: TreeNode): void {
        this.selectedTheme = selectedItem.data as ThemeItem;
    }

    useSelected() {
        if (this.selectedTheme && this.themeProvider.appliedTheme.id !== this.selectedTheme.id) {
            const selectedTheme = this.selectedTheme;
            this.selectButton.disabled.next(true);
            this.selectButton.loader.next(BUTTON_LOADER_LOOK);

            setTimeout(() => {
                this.selectButton.loader.next(null);
                this.selectButton.checked.next(true);

                setTimeout(() => {
                    this.themeProvider.applyTheme(selectedTheme);
                    this.selectButton.checked.next(false);
                    this.selectButton.disabled.next(false);
                }, BLUR_EFFECT_TIMEOUT);
            }, LOADING_TIME);
        }
    }
}
