import { QueryParamsExtender, QUERY_PARAMS_EXTENDER_TOKEN } from "../../shared/services/query-params-extender";
import { ClassProvider, Injectable } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { FILTER_PARAMS, FILTER_TYPES, QUERY_PARAMS } from "../../content/constants";
import { Entity } from "../../shared/services/metadata/meta-data.store";

@Injectable()
export class TaxonomyQueryParamsExtender implements QueryParamsExtender {
    constructor(private route: ActivatedRoute) {
    }

    getAdditionalQueryParams(entity: Entity = null, data: any = null): { [key: string]: string; } {
        const additionalQueryParams: any = {};
        if (this.route.snapshot.queryParams[FILTER_PARAMS.FILTER] === FILTER_TYPES.NOT_USED ||
            this.route.snapshot.queryParams[QUERY_PARAMS.IGNORE_SITE_CONTEXT] === "true") {
                additionalQueryParams[QUERY_PARAMS.IGNORE_SITE_CONTEXT] = "true";
        }

        return additionalQueryParams;
    }
}

export const TAXONOMY_QUERY_PARAMS_EXTENDER: ClassProvider = {
    multi: true,
    provide: QUERY_PARAMS_EXTENDER_TOKEN,
    useClass: TaxonomyQueryParamsExtender
};
