import { ClassProvider, Injectable } from "@angular/core";
import { map, Observable } from "rxjs";
import { DataItem, EntityData } from "../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../content/dynamic-modules/services/dynamic-item.store";
import { DELETE_COMMAND_EXTENDER_TOKEN } from "../content/dynamic-modules/services/operations/commands/composite-delete-command-extender";
import { DeleteCommandExtenderBase } from "../content/dynamic-modules/services/operations/commands/delete-command-extender-base";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { MetadataStore } from "../shared/services/metadata/meta-data.store";
import { FormHelpers } from "./form.helpers";


@Injectable()
export class FormResponsesDeleteCommandExtender extends DeleteCommandExtenderBase {
    constructor(public dynamicItemStore: DynamicItemStore, private metadataStore: MetadataStore) {
        super(dynamicItemStore);
    }

    isSupportedType(entityData: EntityData): boolean {
        return FormHelpers.isFormResponseItem(entityData.metadata);
    }

    executeDelete(dataItem: DataItem, deleteAllTranslations: boolean, skipItemStateUpdate?: boolean): Observable<DataItem> {
        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: dataItem.culture,
            provider: dataItem.provider,
        });

        const formName = dataItem.metadata.setName.replace(`${ENTITY_SET.FORM_RESPONSES}-`, "");
        const data = {
            formName: formName,
            id: dataItem.key,
        };

        return this.dynamicItemStore.service.executeBoundAction(formDataItem, `Default.DeleteFormEntry()`, data).pipe(map(() => dataItem));
    }

    showMultilingualButtons(data): boolean {
        return false;
    }
}

export const FORM_RESPONSES_DELETE_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: DELETE_COMMAND_EXTENDER_TOKEN,
    useClass: FormResponsesDeleteCommandExtender
};
