import { Component, OnInit, ViewChild } from "@angular/core";
import { DataContext } from "../../shared/models/data-context-component";
import { DialogData, ModalWindowService } from "../../shared/services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { ModalListComponent } from "../../shared/components/modal-list/modal-list.component";
import { BehaviorSubject } from "rxjs";
import { ComponentData } from "@progress/sitefinity-component-framework";

/**
 * This component is  used in the classifications grid for the cells under 'Used in' column. It shows in which sites that classification is used.
 */
@Component({
    templateUrl: "./usage-in-sites.component.html"
})
export class UsageInSitesComponent implements OnInit {
    sitesCount: number;
    context: DataContext;
    @ViewChild("itemTemplate", { static: true }) template: any;

    constructor(private route: ActivatedRoute, private modalService: ModalWindowService) {
    }

    ngOnInit(): void {
        this.sitesCount = this.context.dataItem.data.TaxonomySharedWith;
    }

    onDetailsClick() {
        const count = new BehaviorSubject<number>(this.sitesCount);

        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                action: `Default.GetRelatedSites()`,
                dataItem: this.context.dataItem,
                actionTitle: "Used in sites",
                count,
                showDataItemTitle: false,
                treeConfig: {
                    noSelection: true,
                    dataProperties: {
                        descriptionField: "Url"
                    },
                    description: true,
                    treeProperties: {
                        displayField: "Name"
                    }
                },
                openItemEdit: false,
                template: null,
                contentLook: "medium sf-mt-l",
                listLook: "no-hover"
            }
        };

        const dialogData = new DialogData(componentData);
        this.modalService.setMapping(dialogData, "usedInSites");
        this.modalService.open(this.route, "usedInSites");
    }
}
