import { Injectable, ClassProvider } from "@angular/core";
import { BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN, DefaultTaskNotificationBuilder } from "./background-task-notification-builder";
import { stringConstants } from "../../../../../common-constants";
import { BackgroundTaskType, ExtendedBackgroundTask, BackgroundTask, TaskStatus, TaskActionButton, TaskAction } from "../../services/background-task.types";

@Injectable()
export class TaxaNotificationBuilder extends DefaultTaskNotificationBuilder {
    private supportedTaskTypes: string[] = [
        BackgroundTaskType.TaxonMove,
        BackgroundTaskType.FlatTaxonMerge
    ];

    get isDefault() {
        return false;
    }

    isTaskSupported(taskName: string): boolean {
        return this.supportedTaskTypes.indexOf(taskName) > -1;
    }

    filterTasksCallback(task: ExtendedBackgroundTask, propertyMap: {[key: string]: string}): boolean {
        return task.ConcurrentTaskKey === propertyMap["ConcurrentTaskKey"];
    }

    buildNotification(task: BackgroundTask): string {
        if (!this.isTaskSupported(task.TaskName)) {
            return stringConstants.EMPTY_STRING;
        }

        const taskData: TaxonTaskState = JSON.parse(task.TaskData);
        const taskName = task.TaskName;

        task.Description = this.buildDescription(taskName, taskData);

        switch (TaskStatus[task.Status.toString()]) {
            case TaskStatus.Failed:
                const statusMessage: TaxonStatus[] = JSON.parse(task.StatusMessage);
                return this.buildFailedNotification(taskName, taskData, statusMessage);
            case TaskStatus.Pending:
            case TaskStatus.Started:
                return this.buildPendingNotification(taskName, taskData);
            default:
                return this.buildDoneNotification(taskName, taskData);
        }
    }

    buildButtons(task: BackgroundTask): TaskActionButton[] {
        const buttons = [];
        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (status === TaskStatus.Failed && task.IsManageable) {
            buttons.push({
                action: TaskAction.Delete,
                title: "Close"
            });
        }

        return buttons;
    }

    private getTaxonomyDisplayName(count: number, taskData: any) {
        return count === 1 ? taskData.TaxonomySingularName : taskData.TaxonomyPluralName;
    }

    private buildFailedNotification(taskName: string, taskData: TaxonTaskState, statusMessage: TaxonStatus[]): string {
        const deletedTaxons = statusMessage.filter(x => TaxonStatusType[x.TaxonStatusType.toString()] === TaxonStatusType.NotFoundError);
        const taxonomyName = this.getTaxonomyDisplayName(deletedTaxons.length, taskData);
        const isTargetDeleted = deletedTaxons.some(x => TaxonType[x.TaxonType.toString()] === TaxonType.Target);
        const targetDeletedMessage = isTargetDeleted ? `${taskData.TaxonomySingularName} ${taskData.TargetTaxon.Name.bold()} has been deleted.` : stringConstants.EMPTY_STRING;

        let start = stringConstants.EMPTY_STRING;
        let reason = stringConstants.EMPTY_STRING;

        switch (taskName) {
            case BackgroundTaskType.TaxonMove:
                start = "Failed to move items";
                reason = isTargetDeleted ? `. ` : ` from ${taxonomyName.toLowerCase()} ${this.formatTaxaNames(deletedTaxons.map(x => x.Name))}. ${taxonomyName} ${deletedTaxons.length === 1 ? "has" : "have"} been deleted. Items from other ${taskData.TaxonomyPluralName.toLowerCase()} were moved successfully.`;
                break;
            case BackgroundTaskType.FlatTaxonMerge:
                start = "Failed to merge";
                reason = isTargetDeleted ? ` ${this.getTaxonomyDisplayName(taskData.SourceTaxa.length, taskData).toLowerCase()} ${this.formatTaxaNames(taskData.SourceTaxa.map(x => x.Name))} to ${taskData.TargetTaxon.Name.bold()}. `
            : ` ${taxonomyName.toLowerCase()} ${this.formatTaxaNames(deletedTaxons.map(x => x.Name))}. ${taxonomyName} ${deletedTaxons.length === 1 ? "has" : "have"} been deleted. Other ${taskData.TaxonomyPluralName.toLowerCase()} were merged successfully.`;
                break;
        }

        return `${start}${reason}${targetDeletedMessage}`;
    }

    private buildPendingNotification(taskName: string, taskData: TaxonTaskState): string {
        const taxonomyName = this.getTaxonomyDisplayName(taskData.SourceTaxa.length, taskData);
        const start = `${taxonomyName} ${this.formatTaxaNames(taskData.SourceTaxa.map(x => x.Name))} will be `;
        let action = stringConstants.EMPTY_STRING;

        switch (taskName) {
            case BackgroundTaskType.TaxonMove:
                action = `removed from the content items and a new ${taskData.TaxonomySingularName.toLowerCase()} ${taskData.TargetTaxon.Name.bold()} will be assigned.`;
                break;
            case BackgroundTaskType.FlatTaxonMerge:
                action = `merged to ${taskData.TaxonomySingularName.toLowerCase()} ${taskData.TargetTaxon.Name.bold()}.`;
                break;
        }

        return `${start}${action} This operation may take few minutes.`;
    }

    private buildDoneNotification(taskName: string, taskData: TaxonTaskState): string {
        const taxonomyName = this.getTaxonomyDisplayName(taskData.SourceTaxa.length, taskData);
        const start = `${taxonomyName} ${this.formatTaxaNames(taskData.SourceTaxa.map(x => x.Name))} ${taskData.SourceTaxa.length === 1 ? "was" : "were"} `;
        let action = stringConstants.EMPTY_STRING;

        switch (taskName) {
            case BackgroundTaskType.TaxonMove:
                action = `removed from the content items and a new ${taskData.TaxonomySingularName.toLowerCase()} ${taskData.TargetTaxon.Name.bold()} was assigned.`;
                break;
            case BackgroundTaskType.FlatTaxonMerge:
                action = `merged to ${taskData.TaxonomySingularName.toLowerCase()} ${taskData.TargetTaxon.Name.bold()}.`;
                break;
        }

        return `${start}${action}`;
    }

    private formatTaxaNames(taxaNames: string[], separator: string = ", ") {
        switch (taxaNames.length) {
            case 0:
                return stringConstants.EMPTY_STRING;
            case 1:
                return taxaNames[0].bold();
            default:
                const lastName = taxaNames.splice(-1)[0].bold();
                const names = taxaNames.map(x => x.bold()).join(separator);

                return `${names} and ${lastName}`;
        }
    }

    private buildDescription(taskName: string, taskData: TaxonTaskState): string {
        const sourceTaxaCount = taskData.SourceTaxa.length;
        const taxonomyName = this.getTaxonomyDisplayName(sourceTaxaCount, taskData).toLowerCase();

        let start = stringConstants.EMPTY_STRING;
        switch (taskName) {
            case BackgroundTaskType.TaxonMove:
                start = "Moving items from";
                break;
            case BackgroundTaskType.FlatTaxonMerge:
                start = "Merging";
                break;
            default:
                return stringConstants.EMPTY_STRING;
        }

        return `${start} ${sourceTaxaCount} ${taxonomyName} to ${taskData.TargetTaxon.Name}`;
    }
}

export const TAXA_NOTIFICATION_BUILDER: ClassProvider = {
    multi: true,
    provide: BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN,
    useClass: TaxaNotificationBuilder
};

interface TaxonStatus {
    Id: string;
    Name: string;
    ErrorMessage: string;
    TaxonType: TaxonType;
    TaxonStatusType: TaxonStatusType;
}

enum TaxonType {
    Source,
    Target
}

enum TaxonStatusType {
    Ok,
    NotStarted,
    NotFoundError,
    PropertyNotFoundError,
    UnknownError
}

interface TaxonTaskState {
    SourceTaxa: TaxonTaskStateItem[];
    TargetTaxon: TaxonTaskStateItem;
    TaxonomySingularName: string;
    TaxonomyPluralName: string;
}

interface TaxonTaskStateItem {
    Id: string;
    Name: string;
}
