import { Directive, ElementRef, Input, AfterViewInit } from "@angular/core";
import { LOCALE } from "../common-constants";
import { isCurrency } from "../utils";
import { isNullOrEmpty } from "../../../src/app/utils";

@Directive({
    selector: "[sfLocalizedNum]",
    exportAs: "sfLocalizedNum"
})

export class LocalizedNumDirective implements AfterViewInit {
    isCurrency: boolean = false;
    @Input() unit: string;
    @Input() locale: string = LOCALE;
    @Input() value: any;
    private element: ElementRef;

    constructor(element: ElementRef) {
        this.element = element;
    }

    ngAfterViewInit() {
        let validNumber;
        let localizedNumber;

        if (!isNullOrEmpty(this.value)) {
            validNumber = +this.value;

            if (!isNaN(validNumber)) {
                if (this.unit && isCurrency(this.unit)) {
                    localizedNumber = validNumber.toLocaleString(this.locale, { style: "currency", currency: this.unit });
                    this.isCurrency = true;
                } else {
                    localizedNumber = validNumber.toLocaleString(this.locale);
                }

                this.element.nativeElement.innerText = localizedNumber;
            }
        }
    }
}
