import { EntityData } from "../../content/dynamic-modules/interfaces";
import { ENTITY_SET, ALBUM_ITEM_FULL_NAME, FOLDER_ITEM_FULL_NAME, DOCUMENT_LIBRARY_ITEM_FULL_NAME, VIDEO_LIBRARY_ITEM_FULL_NAME } from "../../shared/services/metadata/meta-data-constants";
import { CommunicationEvent } from "../../shared/events/component-events";
import { MediaLabels } from "./media.status-resolver";
