import { MEDIA_CONTENT_TYPES } from "../media-content.types";

const CHILDREN_COUNT_PROP_NAME = "ChildrenCount";

export const MEDIA_FORM_CLASS = " -medium";
export const LIBRARY_SET_NAMES = [ENTITY_SET.ALBUMS, ENTITY_SET.FOLDERS, ENTITY_SET.DOCUMENT_LIBRARIES, ENTITY_SET.VIDEO_LIBRARIES];
export const LIBRARY_TYPE_FULL_NAMES = [ALBUM_ITEM_FULL_NAME, FOLDER_ITEM_FULL_NAME, DOCUMENT_LIBRARY_ITEM_FULL_NAME, VIDEO_LIBRARY_ITEM_FULL_NAME];
export const MIME_TYPES = {
    SVG: "image/svg+xml",
    JPEG: "image/jpeg",
    MP4: "video/mp4",
    OGV: "video/ogg",
    WEBM: "video/webm"
};

export const EXTENSIONS = {
    SVG: "svg",
    MP4: "mp4"
};

export const MEDIA_PROPERTIES = {
    CHILDREN_COUNT: "ChildrenCount",
    FOLDERS_COUNT: "FoldersCount"
};

const mediaEntities: string[] = [
    ENTITY_SET.IMAGES,
    ENTITY_SET.DOCUMENTS,
    ENTITY_SET.VIDEOS
];

const allMediaEntities: string[] = [...mediaEntities, ...LIBRARY_SET_NAMES];

export class MediaHelpers {
    static isLibrary(setName: string) {
        return LIBRARY_SET_NAMES.some(x => x === setName);
    }

    static isFolderItem(itemData: any) {
        return CHILDREN_COUNT_PROP_NAME in itemData;
    }

    static isLibraryType(typeFullName: string) {
        return LIBRARY_TYPE_FULL_NAMES.some(x => x === typeFullName);
    }

    static isAlbumEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.ALBUMS;
    }

    static isFolderEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.FOLDERS;
    }

    static isImageEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.IMAGES;
    }

    static isDocumentEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.DOCUMENTS;
    }

    static isVideoEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.VIDEOS;
    }

    static isImageSet(setName: string) {
        return setName === ENTITY_SET.IMAGES;
    }

    static getChildSetName(entityData: EntityData) {
        if (entityData.metadata.children.length === 1) {
            return entityData.metadata.children[0];
        }

        return entityData.metadata.setName;
    }

    static getParentSetName(entityData: EntityData) {
        if (entityData.metadata.hasChildren) {
            return entityData.metadata.setName;
        }

        return entityData.metadata.parent;
    }

    static isChildNavigate(dataItem: EntityData) {
        return dataItem && this.isLibrary(dataItem.metadata.setName);
    }

    static isDocumentLibraryEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.DOCUMENT_LIBRARIES;
    }

    static isVideosLibraryEntity(entityData: EntityData) {
        return entityData.metadata.setName === ENTITY_SET.VIDEO_LIBRARIES;
    }

    static isMediaEntity(entityData: EntityData) {
        return mediaEntities.some(x => x === entityData.metadata.setName);
    }

    static isLibraryOrMedia(setName: string) {
        return allMediaEntities.some(x => x === setName);
    }

    static resolveMediaLabels(setName: string): MediaLabels {
        let mediaLabels: MediaLabels = null;

        switch (setName) {
            case ENTITY_SET.DOCUMENTS:
            case ENTITY_SET.DOCUMENT_LIBRARIES:
                mediaLabels = {
                    singular: MEDIA_CONTENT_TYPES.document.single,
                    plural: MEDIA_CONTENT_TYPES.document.plural
                };
                break;
            case ENTITY_SET.VIDEOS:
            case ENTITY_SET.VIDEO_LIBRARIES:
                mediaLabels =  {
                    singular: MEDIA_CONTENT_TYPES.video.single,
                    plural: MEDIA_CONTENT_TYPES.video.plural
                };
                break;
            default:
                mediaLabels = {
                    singular: MEDIA_CONTENT_TYPES.image.single,
                    plural: MEDIA_CONTENT_TYPES.image.plural
                };
                break;
        }

        return mediaLabels;
    }

    static resolveLibrarySetName(setName: string) {
        switch (setName) {
            case ENTITY_SET.DOCUMENTS:
            case ENTITY_SET.DOCUMENT_LIBRARIES:
                return ENTITY_SET.DOCUMENT_LIBRARIES;
            case ENTITY_SET.VIDEOS:
            case ENTITY_SET.VIDEO_LIBRARIES:
                return ENTITY_SET.VIDEO_LIBRARIES;
            default:
                return ENTITY_SET.ALBUMS;
        }
    }

    static resolveMediaSetName(setName: string) {
        switch (setName) {
            case ENTITY_SET.DOCUMENTS:
            case ENTITY_SET.DOCUMENT_LIBRARIES:
                return ENTITY_SET.DOCUMENTS;
            case ENTITY_SET.VIDEOS:
            case ENTITY_SET.VIDEO_LIBRARIES:
                return ENTITY_SET.VIDEOS;
            default:
                return ENTITY_SET.IMAGES;
        }
    }

    static resolveLibraryDisplayName(setName: string) {
        switch (setName) {
            case ENTITY_SET.DOCUMENT_LIBRARIES:
                return "Document libraries";
            case ENTITY_SET.VIDEO_LIBRARIES:
                return "Video libraries";
            case ENTITY_SET.ALBUMS:
                return "Albums";
            default:
                return "Libraries";
        }
    }

    static getDocumentThumbnailIcon(extension: string): string {
        if (extension) {
            if (extension.lastIndexOf(stringConstants.DOT) === 0) {
                // remove the dot "."
               extension = extension.substr(1).toLocaleLowerCase();
            }

            for (const ext in EXTENSIONS_ICON_LOOK) {
                if (ext === extension) {
                    return EXTENSIONS_ICON_LOOK[ext];
                }
            }
        }

        return DEFAULT_ICON_LOOK;
    }
}

