import { Injectable } from "@angular/core";

@Injectable()
export class EventDatesService {
    getEventEndForAllDayEvent(eventStart: string, eventEnd: string): Date {
        if (eventEnd) {
            const endDate = new Date(eventEnd);
            endDate.setDate(endDate.getDate() - 1);
            return endDate;
        } else {
            return new Date(eventStart);
        }
    }

    getDateWithoutBrowserOffset(date: string | Date): Date {
        if (!date) {
            return null;
        }

        let dateObj: Date;
        if (date instanceof Date)
            dateObj = date;
        else
            dateObj = new Date(date);

        // The date that is passed from the server should be displayed as is, without the browser offset that is added
        // We calculate the browser offset from the date that is passed, instead of new Date(), in order to account for DST
        const browserOffset = dateObj.getTimezoneOffset();
        dateObj.setMinutes(dateObj.getMinutes() + browserOffset);

        return dateObj;
    }

    resetTime(date: Date) {
        if (date) {
            date.setHours(0, 0, 0, 0);
        }

        return date;
    }
}
