import { Component, OnInit, ViewChild } from "@angular/core";

import { FieldSectionModel, FieldSectionSettings } from "../../../../services/fieldSection.model";
import { FieldModel } from "../../../../services/field.model";
import { NEW_TAB_TARGET, stringConstants } from "../../../../common-constants";
import { createFieldModel } from "../../../shared/fields.constants";
import { EditableFieldsComponent, ValueChange } from "../../../shared/fields-builder/components/editable-fields/editable-fields.component";
import { FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { FIELD_TOOLTIP } from "../../../../../../fields/common/common-constants";
import { LINK_CONSTANTS } from "../../selector-constants";
import { CompositeFieldsProvider } from "../../../shared/fields-builder/providers/fields-provider";
import { ActivatedRoute } from "@angular/router";
import { ROUTE_PARAMS } from "../../../content/constants";
import { SHORT_TEXT_PLACEHOLDER, SHORT_TEXT_UNIT, SHORT_TEXT_UNIT_LOOK, SHORT_TEXT_UNIT_POSITION } from "../../../../../../fields/short-text/short-text.constants";
import { CREATE_LINK_MODEL_PROPERTIES, CREATE_LINK_TITLE_CONSTANTS } from "./helpers/create-link-constants";
import { ContentLinkInputModel } from "./link-insert-field/helpers/content-link-input-model";
import { LinkModel } from "../../../../../../fields/link-selector/link-model";
import { ShortTextSettings } from "../../../../../../fields/short-text/short-text-settings";
import { ExternalAppConfigService, StyleData } from "../../../../app-config/external-app-config.service";
import { getMatchingLinkStyle } from "../../../../utils";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { ComplexSettings } from "../../../widget-editor/providers/fields/complex/complex.settings";

const MORE_OPTIONS_SECTION_NAME: string = "moreOptionsSection";
const MORE_OPTIONS_SECTION_TITLE: string = "More options";
const BASE_FIELDS_SECTION_NAME: string = "baseFieldsSection";

@Component({
    templateUrl: "./create-link.component.html"
})
export class CreateLinkComponent implements OnInit {
    showTextToDisplay: boolean;
    isInEditMode: boolean;
    fieldsSections: FieldSectionModel[];
    linkModel: LinkModel;
    fieldsToSkip: string[] = [];
    @ViewChild(EditableFieldsComponent, { static: true }) editableFieldsComponent: EditableFieldsComponent;

    private entity;

    constructor(private fieldsProvider: CompositeFieldsProvider,
                private route: ActivatedRoute,
                private configService: ExternalAppConfigService) {
        this.entity = {
            properties: {
                [CREATE_LINK_MODEL_PROPERTIES.LINK_TO]: {
                    [SHORT_TEXT_PLACEHOLDER]: CREATE_LINK_TITLE_CONSTANTS.LINK_TO_PLACEHOLDER
                },
                [CREATE_LINK_MODEL_PROPERTIES.TEXT]: {},
                [CREATE_LINK_MODEL_PROPERTIES.SHOULD_OPEN_IN_NEW_WINDOW]: {},
                [CREATE_LINK_MODEL_PROPERTIES.ANCHOR]: {
                    [FIELD_TOOLTIP]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_TOOLTIP,
                    [SHORT_TEXT_PLACEHOLDER]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_PLACEHOLDER,
                    [SHORT_TEXT_UNIT]: stringConstants.HASH,
                    [SHORT_TEXT_UNIT_LOOK]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_UNIT_LOOK,
                    [SHORT_TEXT_UNIT_POSITION]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_UNIT_POSITION
                },
                [CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS]: {
                    [FIELD_TOOLTIP]: CREATE_LINK_TITLE_CONSTANTS.QUERY_PARAMS_TOOLTIP,
                    [SHORT_TEXT_PLACEHOLDER]: CREATE_LINK_TITLE_CONSTANTS.QUERY_PARAMS_PLACEHOLDER,
                    [SHORT_TEXT_UNIT]: stringConstants.QUESTION_MARK,
                    [SHORT_TEXT_UNIT_LOOK]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_UNIT_LOOK,
                    [SHORT_TEXT_UNIT_POSITION]: CREATE_LINK_TITLE_CONSTANTS.ANCHOR_UNIT_POSITION
                },
                [CREATE_LINK_MODEL_PROPERTIES.TOOLTIP]: {
                    [FIELD_TOOLTIP]: CREATE_LINK_TITLE_CONSTANTS.TOOLTIP_TOOLTIP
                },
                [CREATE_LINK_MODEL_PROPERTIES.CSS_CLASS]: {},
                [CREATE_LINK_MODEL_PROPERTIES.ATTRIBUTES]: {}
            }
        };
    }

    get title(): string {
        return this.isInEditMode ? LINK_CONSTANTS.EDIT_LINK_TITLE : LINK_CONSTANTS.CREATE_LINK_TITLE;
    }

    get isValid(): boolean {
        return this.editableFieldsComponent.valid();
    }

    get link(): LinkModel {
            const linkData: CreateLinkModel = <CreateLinkModel>((<any>this.editableFieldsComponent).form.value);
            const link: LinkModel = {
                href: linkData.linkModel.hrefWithProtocol,
                sfref: linkData.linkModel.contentItemModel?.sfLink.sfref,
                text: linkData.text,
                target: linkData[CREATE_LINK_MODEL_PROPERTIES.SHOULD_OPEN_IN_NEW_WINDOW] ? NEW_TAB_TARGET : undefined,
                queryParams: linkData.queryParams,
                anchor: linkData.anchor,
                tooltip: linkData.tooltip,
                type: linkData.linkModel.contentItemModel?.entityName || linkData.linkModel.linkTypeName,
                classList: linkData.cssClass != null && linkData.cssClass !== stringConstants.EMPTY_STRING ? linkData.cssClass.split(stringConstants.INTERVAL) : []
            };

            linkData.attributes?.filter(x => x.key).forEach(x => link.attributes = Object.assign({}, link.attributes, { [x.key]: x.value }));
            return link;
    }

    ngOnInit(): void {
        const typeName: string = this.route.snapshot.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
        const baseFieldsSection = this.initBaseFieldsSection(this.linkModel);
        const moreOptionsFieldsSection = this.initMoreOptionsFieldsSection(typeName, this.linkModel);
        this.fieldsSections = [baseFieldsSection, moreOptionsFieldsSection];
    }

    onFieldChange(valueChange: ValueChange) {
        if (valueChange.key === CREATE_LINK_MODEL_PROPERTIES.LINK_TO) {
            const textFieldModel = this.editableFieldsComponent.fieldSections[0].fields.find(x => x.key === CREATE_LINK_MODEL_PROPERTIES.TEXT);
            if (textFieldModel) {
                if ((valueChange.value as ContentLinkInputModel).contentItemModel) {
                    if ((textFieldModel.settings as ShortTextSettings).mirroredFieldProperty !== "contentItemModel.itemName") {
                        (textFieldModel.settings as ShortTextSettings).mirroredFieldProperty = "contentItemModel.itemName";
                        this.editableFieldsComponent.updateValues({ [valueChange.key]: valueChange.value });
                    }
                } else if ((textFieldModel.settings as ShortTextSettings).mirroredFieldProperty !== "href") {
                    (textFieldModel.settings as ShortTextSettings).mirroredFieldProperty = "href";
                    this.editableFieldsComponent.updateValues({ [valueChange.key]: valueChange.value });
                }
            }
        }
    }

    private initBaseFieldsSection(linkData: LinkModel): FieldSectionModel {
        const fields: FieldModel[] = this.getBaseFields(linkData);
        const sectionOptions: FieldSectionSettings = {
            isMain: true,
            isExpanded: false,
            insertHorizontalRule: true,
            title: stringConstants.EMPTY_STRING,
            name: BASE_FIELDS_SECTION_NAME
        };

        const baseFieldsSection = new FieldSectionModel(sectionOptions);
        baseFieldsSection.fields = fields;

        return baseFieldsSection;
    }

    private initMoreOptionsFieldsSection(typeName: string, linkData: LinkModel): FieldSectionModel {
        const fields: FieldModel[] = this.getMoreOptionsFields(typeName, linkData);
        const sectionOptions: FieldSectionSettings = {
            isMain: false,
            isExpanded: false,
            insertHorizontalRule: true,
            title: MORE_OPTIONS_SECTION_TITLE,
            name: MORE_OPTIONS_SECTION_NAME
        };

        const moreOptionsFieldsSection = new FieldSectionModel(sectionOptions);
        moreOptionsFieldsSection.fields = fields;

        return moreOptionsFieldsSection;
    }

    private getBaseFields(linkData: LinkModel): FieldModel[] {
        const linkInputModel = new ContentLinkInputModel(linkData);

        if (linkData?.anchor && !linkData?.queryParams) {
            linkInputModel.isUrlRequired = false;
        }

        const displayTextValue = linkData?.text;
        const openInNewWindowValue = linkData?.target === NEW_TAB_TARGET;
        const typeName: string = this.route.snapshot.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
        const textField = this.createField(FieldTypes.shortText, typeName, CREATE_LINK_MODEL_PROPERTIES.TEXT, displayTextValue, this.entity, CREATE_LINK_TITLE_CONSTANTS.TEXT);
        (textField.settings as ShortTextSettings).mirroredFieldName = CREATE_LINK_MODEL_PROPERTIES.LINK_TO;
        (textField.settings as ShortTextSettings).enableMirroring = true;
        (textField.settings as ShortTextSettings).mirroredFieldProperty = linkData?.sfref ? "contentItemModel.itemName" : "href";

        const fields: FieldModel[] = [
            this.createField(FieldTypes.linkInsert, typeName, CREATE_LINK_MODEL_PROPERTIES.LINK_TO, linkInputModel, this.entity, CREATE_LINK_TITLE_CONSTANTS.LINK_TO),
            textField,
            this.createField(FieldTypes.choiceYesNo, typeName, CREATE_LINK_MODEL_PROPERTIES.SHOULD_OPEN_IN_NEW_WINDOW, openInNewWindowValue, this.entity, CREATE_LINK_TITLE_CONSTANTS.SHOULD_OPEN_IN_NEW_WINDOW)
        ];

        if (!this.showTextToDisplay) {
            const textToDisplayFieldIndex = fields.findIndex(x => x.key === CREATE_LINK_MODEL_PROPERTIES.TEXT);
            fields.splice(textToDisplayFieldIndex, 1);
        }

        fields[fields.length - 1].settings.showTitle = false;
        return fields;
    }

    private getMoreOptionsFields(typeName: string, linkAttrData: LinkModel): FieldModel[] {
        // TODO: #226601
        // keep in mind to which site the anchor is pointing
        // if (this.selectedElement && LINK_CONSTANTS.ANCHOR_PATTERN.test(this.selectedElement.href)) {
        //     anchorValue = this.selectedElement.href.match(LINK_CONSTANTS.ANCHOR_PATTERN)[0].substr(1);
        // }

        const fields: {[key: string]: FieldModel} = {
            [CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS]: this.createField(FieldTypes.shortText, typeName, CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS, linkAttrData?.queryParams, this.entity, CREATE_LINK_TITLE_CONSTANTS.QUERY_PARAMS),
            [CREATE_LINK_MODEL_PROPERTIES.ANCHOR]: this.createField(FieldTypes.shortText, typeName, CREATE_LINK_MODEL_PROPERTIES.ANCHOR, linkAttrData?.anchor, this.entity, CREATE_LINK_TITLE_CONSTANTS.ANCHOR),
            [CREATE_LINK_MODEL_PROPERTIES.TOOLTIP]: this.createField(FieldTypes.shortText, typeName, CREATE_LINK_MODEL_PROPERTIES.TOOLTIP, linkAttrData?.tooltip, this.entity, CREATE_LINK_TITLE_CONSTANTS.TOOLTIP),
            [CREATE_LINK_MODEL_PROPERTIES.STYLES]: this.createLinkStylesField(typeName, this.linkModel),
            [CREATE_LINK_MODEL_PROPERTIES.ATTRIBUTES]: this.createAttributesField(typeName, this.linkModel)
        };

        return Object.keys(fields).filter(x => !this.fieldsToSkip || this.fieldsToSkip.indexOf(x) === -1).map(x => fields[x]);
    }

    private createField(fieldType: string, typeName: string, propName: string, value: any, metadata: any = {}, propTitle?: string): FieldModel {
        return createFieldModel(this.fieldsProvider, typeName, fieldType, propName, value, metadata, propTitle);
    }

    private createLinkStylesField(typeName: string, linkModel: LinkModel) {
        const linkStylesFromConfig: StyleData[] = this.configService.externalConfig?.linkStyles || [];
        const noStyle: StyleData = { Name: "No style", Value: [] };
        const allStyles: StyleData[] = [noStyle].concat(linkStylesFromConfig);
        const initialStyle: StyleData = getMatchingLinkStyle(allStyles, linkModel?.classList || []);

        const field = this.createField(FieldTypes.choiceDropDown, typeName, CREATE_LINK_MODEL_PROPERTIES.CSS_CLASS, initialStyle.Value.join(stringConstants.INTERVAL), this.entity, CREATE_LINK_TITLE_CONSTANTS.CSS_CLASS);
        (field.settings as ChoiceSettings).choices = allStyles.map(s => <ChoiceItem>{ Name: s.Name, Value: s.Value.join(stringConstants.INTERVAL)});

        return field;
    }

    private createAttributesField(typeName: string, linkModel: LinkModel) {
        // do magic so that the field looks like table
        const value = linkModel?.attributes ? Object.keys(linkModel.attributes).map(x => { return { key: x, value: linkModel.attributes[x] }}) : undefined;
        const field = this.createField(FieldTypes.complex, typeName, CREATE_LINK_MODEL_PROPERTIES.ATTRIBUTES, value, this.entity, CREATE_LINK_TITLE_CONSTANTS.ATTRIBUTES);
        const settings = field.settings as ComplexSettings;
        settings.isMultiple = true;
        settings.type = "enumerable";
        settings.typeChildProperties = [{
            Name: "key",
            Title: "Key",
            Type: null,
            DefaultValue: null,
            Properties: []
        }, {
            Name: "value",
            Title: "Value",
            Type: null,
            DefaultValue: null,
            Properties: []
        }];

        return field;
    }
}

class CreateLinkModel {
    linkModel: ContentLinkInputModel;
    text: string;
    taget: string;
    shouldOpenInNewWindow: boolean;
    anchor: string;
    queryParams: string;
    tooltip: string;
    cssClass: string;
    attributes: {key: string, value: string}[];
}
