import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Inject, Injectable } from "@angular/core";
import { HierarchicalFacetsService, HIERARCHICAL_FACETS_SERVICE } from "../../../libraries/services/hierarchical-facets.service";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { PencilButtonSettings } from "../../../../../../fields/pencil-button/pencil-button-field.component";
import { cloneObject } from "../../../../utils";

const FACET_WIDGET_TABLE_FIELD = {
    FACETABLE_FIELD_NAME: "FacetableFieldNames",
    FACETABLE_FIELD_SETTINGS: "FacetFieldSettings",
    FACETABLE_FIELD_LABEL: "FacetableFieldLabels"
}

const DATE_AND_TIME_TYPE = "DateAndTime";
const NUMBER_WHOLE_TYPE = "NumberWhole";
const NUMBER_DECIMAL_TYPE = "NumberDecimal";
const FACET_TABLE_NAME = "SelectedFacets";

const FACET_FIELD_WITH_SETTINGS = [DATE_AND_TIME_TYPE, NUMBER_WHOLE_TYPE, NUMBER_DECIMAL_TYPE];

@Injectable()
export class FacetTableChangeService implements FieldChangeService {

    constructor(@Inject(HIERARCHICAL_FACETS_SERVICE) private facetService: HierarchicalFacetsService) {
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === FACET_TABLE_NAME;
    }

    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
            const tableRowInfoRegex = /SelectedFacets(\d+)(\w+)/;
            const match = changedFieldName.match(tableRowInfoRegex);
            if (match.length < 3) {
                return;
            }
            const currentRowIndex = match[1];

            if (changedFieldName.includes(FACET_WIDGET_TABLE_FIELD.FACETABLE_FIELD_NAME)) {
                const currentRowFacetTaxaComponentName = `${currentRowIndex}${FACET_WIDGET_TABLE_FIELD.FACETABLE_FIELD_NAME}`;
                const facetNameFieldRef = fields.find(f => f.labelId.includes(currentRowFacetTaxaComponentName));

                if (facetNameFieldRef) {
                    const facetTaxaComponentValue = facetNameFieldRef.getValue();
                    const currentRowFacetName = facetTaxaComponentValue?.length ? facetTaxaComponentValue[0] : stringConstants.EMPTY_STRING;

                    const facetSettingsFieldName = `${FACET_TABLE_NAME}${currentRowIndex}${FACET_WIDGET_TABLE_FIELD.FACETABLE_FIELD_SETTINGS}`;
                    const facetSettingFieldRef = fields.find(f => f.labelId === facetSettingsFieldName)?.currentInstance;

                    if (currentRowFacetName === stringConstants.EMPTY_STRING) {
                        // new row added
                        facetSettingFieldRef.setHidden(true)
                        return;
                    }

                    // change the label of the facet
                    this.setFacetLabelField(currentRowIndex, currentRowFacetName, fields);

                    this.handleSettingsFieldChange(facetSettingFieldRef, currentRowFacetName);
                }
            }
    }

    private setFacetLabelField(currentRowIndex: string, currentRowFacetName: string, fields: FormFieldWrapperComponent[]) {
        const facetElementStoredData = this.getStoredFacetInfo(currentRowFacetName);
        if (facetElementStoredData) {
            const currentRowLabelComponentName = `${currentRowIndex}${FACET_WIDGET_TABLE_FIELD.FACETABLE_FIELD_LABEL}`;
            const labelFacetFieldRef = fields.find(f => f.labelId.includes(currentRowLabelComponentName));

            // we don't check for falsy value since that when it's empty string we don't want to write the value
            if (labelFacetFieldRef.getValue() === null || labelFacetFieldRef.getValue() === undefined ) {
                labelFacetFieldRef.writeValue(facetElementStoredData.FacetableFieldLabels);
            }
        }
    }

    private handleSettingsFieldChange(facetSettingFieldRef: any, currentRowFacetName: string) {
        const storedFacetInfo = this.getStoredFacetInfo(currentRowFacetName);

        if (facetSettingFieldRef) {
            let settingsFieldValue = facetSettingFieldRef.getValue();
            const facetType = storedFacetInfo?.FacetableFieldType ?? settingsFieldValue?.FacetType;
            if (!facetType) {
                return
            }

            const dateAndNumberFacetSettingsFieldSettingsClone = cloneObject(facetSettingFieldRef.settings) as PencilButtonSettings;
            const dialogTitle = this.getDialogTitle(facetType);
            dateAndNumberFacetSettingsFieldSettingsClone.dialogData.header = dialogTitle;
            const shouldResetValueToDefault = dateAndNumberFacetSettingsFieldSettingsClone.dialogData.subTitle !== undefined &&
                dateAndNumberFacetSettingsFieldSettingsClone.dialogData.subTitle !== currentRowFacetName;
            dateAndNumberFacetSettingsFieldSettingsClone.dialogData.subTitle = currentRowFacetName;

            if (!settingsFieldValue || shouldResetValueToDefault) {
                settingsFieldValue = {
                    FacetType: facetType,
                    NumberStep: null,
                    RangeType: 0,
                    DateRanges: null,
                    DateStep: null,
                    NumberRanges: null,
                    NumberRangesDecimal: null,
                    DisplayCustomRange: false,
                    Prefix: null,
                    Suffix: null,
                };
            }

            const isHidden = !FACET_FIELD_WITH_SETTINGS.includes(facetType);
            facetSettingFieldRef.setHidden(isHidden)
            facetSettingFieldRef.writeValue(settingsFieldValue);
            facetSettingFieldRef.settings = dateAndNumberFacetSettingsFieldSettingsClone;
        }
    }

    private getStoredFacetInfo(currentRowFacetName) {
        const facetElementStoredData = this.facetService.findFacetByFieldName(currentRowFacetName);
        return facetElementStoredData?.data;
    }

    private getDialogTitle(facetFieldType: string): string {
        if (facetFieldType) {
            if (facetFieldType.includes("Number")) {
                return "Number facet"
            } else if (facetFieldType === DATE_AND_TIME_TYPE) {
                return "Date facet"
            }
        }

        return stringConstants.EMPTY_STRING;
    }
}

export const FACET_TABLE_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: FacetTableChangeService,
    multi: true
};


