import { throwError as observableThrowError, Observable } from "rxjs";
import { map } from "rxjs/operators";

import { finalize, tap, catchError } from "rxjs/operators";
import { Subject } from "rxjs";
import { ResponseError } from "../../../shared/services/errors/response-error";
import { Injectable } from "@angular/core";

import { Action } from "./entity/action";
import { DynamicItemService, LoadItem, CreateItem, UpdateItem, DeleteItem, LoadItemsData, LoadItemsByKeysData, ItemPosition, LoadItemsResponse, ItemWithOperationResult } from "./dynamic-item.service";
import { DataItem, EntityData, OperationResult, HierarchicalDataItem } from "../interfaces";
import { Logger } from "../../../shared/services/logger-source/logger";
import { ChildrenCountStore } from "./children-count.store";
import { DynamicItemStoreState, ItemsState } from "./dynamic-item-store-state";
import { NotFoundError } from "../../../shared/services/errors/not-found-error";
import { Properties } from "../../../shared/fields.constants";
import { ActionEvent } from "./entity/action-buttons";
import { LAST_MODIFIED_ASC_SORT_ORDER, LAST_MODIFIED_DESC_SORT_ORDER } from "../../../shared/services/sort.service";
import { GenericError } from "../../../shared/services/errors/generic-error";
import { ExternalAppConfigService } from "../../../../app-config/external-app-config.service";

@Injectable({ providedIn: "root" })
export class DynamicItemStore {
    private stateCache = new Map<string, DynamicItemStoreState>();
    private itemChanges$ = new Subject<ItemChange>();

    constructor(private logger: Logger,
        private dynamicItemService: DynamicItemService,
        private childrenCountStore: ChildrenCountStore,
        private externalAppConfigService: ExternalAppConfigService) {
    }

    get service() {
        return this.dynamicItemService;
    }

    // TODO: remove
    getLeftItemsCount(entityData: EntityData) {
        const leftItemsCount = this.getTotalCount(entityData) - this.getLoadedItemsCount(entityData);

        if (leftItemsCount > this.externalAppConfigService.externalConfig.contentItemsPerPage) {
            return this.externalAppConfigService.externalConfig.contentItemsPerPage;
        } else {
            return leftItemsCount;
        }
    }

    // TODO: remove
    getTotalCount(entityData: EntityData) {
        const totalCount = this.getState(entityData).itemsCount;
        return totalCount;
    }

    // TODO: remove
    getLoadedItemsCount(entityData: EntityData): number {
        return this.getState(entityData).getValue().dataItems.length;
    }

    getItems(entityData: EntityData): Observable<ItemsState> {
        return this.getState(entityData).getDynamicItems();
    }

    executeOperation(dataItem: DataItem, actionName: string): Observable<OperationResult> {
        return this.dynamicItemService.executeOperation(dataItem, actionName).pipe(tap(() => {
            this.notifyItemChange(dataItem.key, dataItem, actionName);
        }));
    }

    executeEntityOperation(entityData: EntityData, actionName: string, data: any): Observable<any> {
        return this.dynamicItemService.executeEntityOperation(entityData, actionName, data).pipe(tap(() => {
            this.notifyItemChange(null, entityData, actionName);
        }));
    }

    restoreItem(dataItem: DataItem): Observable<OperationResult> {
        return this.dynamicItemService.restoreItem(dataItem).pipe(tap(() => {
            this.notifyItemChange(dataItem.key, dataItem, ActionEvent.Restore);
        }));
    }

    getItem(loadItemData: LoadItem): Observable<DataItem> {
        const getItem$ = this.dynamicItemService.getItem(loadItemData).pipe(
            tap((item: DataItem) => {
                this.refreshItem(item, ItemPosition.Current);
            }), catchError((error: GenericError) => {
                if (error instanceof NotFoundError) {
                    this.deleteItemFromMemory(loadItemData.itemKey, loadItemData.entityData);
                }

                return observableThrowError(error);
            }));

        return getItem$;
    }

    getItemList(loadItems: LoadItemsData): Observable<LoadItemsResponse> {
        return this.dynamicItemService
            .getItemList(loadItems).pipe(
                catchError(error => {
                    this.logger.error({
                        message: `An error was encountered retrieving dynamic items of type: '${loadItems.entityData.metadata.setName}'`,
                        code: "getItemList"
                    });

                    return observableThrowError(error);
                }));
    }

    deleteItem(deleteItemArgs: DeleteItem): Observable<DataItem> {
        const item = deleteItemArgs.dataItem;
        const deleteItem$ = this.dynamicItemService.deleteItem(deleteItemArgs);
        deleteItem$.subscribe(() => {
            this.notifyItemChange(item.key, item, ActionEvent.Delete);
            if (!deleteItemArgs.skipItemStateUpdate) {
                this.deleteItemFromMemory(item.key, item, deleteItemArgs.deleteAllTranslations, deleteItemArgs.itemPosition);
                this.childrenCountStore.invalidateCachedChidrenCountByChildItem(item);
            }
        }, (error: ResponseError) => {
            const notFound = error instanceof NotFoundError;

            if (notFound && !deleteItemArgs.skipItemStateUpdate) {
                this.deleteItemFromMemory(item.key, item, deleteItemArgs.deleteAllTranslations, deleteItemArgs.itemPosition);
            }
        });

        return deleteItem$;
    }

    saveItemWithOperationResult(itemValue: DataItem, updatedFields: any, action: Action, fallbackPropertyNames?: Array<string>, dataFieldNames?: Array<string>, itemPosition: ItemPosition = ItemPosition.Default, skipUpdate = false, doNotRefreshItem = false, additionalQueryParams?: { [key: string]: string }): Observable<ItemWithOperationResult> {
        let result: Observable<ItemWithOperationResult> = null;

        if (itemValue.isEmpty) {
            result = this.createItem({
                data: updatedFields,
                operation: action.operation,
                entityData: itemValue,
                fallbackProperties: fallbackPropertyNames,
                itemPosition: itemPosition,
                doNotRefreshItem,
                additionalQueryParams
            });
        } else {
            result = this.updateItem({
                dataItem: itemValue,
                data: updatedFields,
                operation: action ? action.operation : null,
                fallbackProperties: fallbackPropertyNames,
                dataFieldNames,
                itemPosition: itemPosition,
                skipUpdate,
                doNotRefreshItem,
                additionalQueryParams
            });
        }

        result = result.pipe(tap(() => {
            this.notifyItemChange(itemValue.key, itemValue, action ? action.name : null);
        }));

        return result;
    }

    saveItem(itemValue: DataItem, updatedFields: any, action: Action, fallbackPropertyNames?: Array<string>, dataFieldNames?: Array<string>, itemPosition: ItemPosition = ItemPosition.Default): Observable<DataItem> {
        return this.saveItemWithOperationResult(itemValue, updatedFields, action, fallbackPropertyNames, dataFieldNames, itemPosition).pipe(map(x => x.dataItem));
    }

    unlockItem(item: DataItem, checkIfOwnerIsCurrentUser: boolean = false): Observable<DataItem> {
        const unlock$ = this.dynamicItemService.unlockItem(item, checkIfOwnerIsCurrentUser);

        unlock$.subscribe(unlockedItem => {
            this.refreshItem(unlockedItem);
        }, (error: ResponseError) => {
            if (error instanceof NotFoundError) {
                this.deleteItemFromMemory(item.key, item);
            }
        });

        return unlock$;
    }

    loadItems(loadItems: LoadItemsData): void {
        const state = this.getState(loadItems.entityData);
        const currentState = state.getValue();

        loadItems.order = loadItems.order || LAST_MODIFIED_DESC_SORT_ORDER;

        loadItems.take = loadItems.take || this.externalAppConfigService.externalConfig.contentItemsPerPage;

        loadItems.skip = loadItems.skip || 0;

        const loadItems$ = this.getItemList(loadItems);

        const loadingState: ItemsState = {
            dataItems: currentState.dataItems,
            loadingItemsCount: loadItems.take,
            query: loadItems.query,
            skip: loadItems.skip,
            take: loadItems.take,
            order: loadItems.order,
            action: loadItems.action,
            totalCount: currentState.totalCount
        };

        // TODO: cache
        if (loadItems.skip === 0) {
            loadingState.dataItems = [];
        }

        state.next(loadingState);

        loadItems$.subscribe(args => {
            state.itemsCount = args.totalCount;
            const currentStateValue = state.getValue();
            const currentlyLoadedItems = currentStateValue.dataItems;
            let allItems = args.dataItems;

            // if there is skip we know loadMoreItems is called
            if (loadItems.skip !== 0) {
                allItems = currentlyLoadedItems.concat(allItems);
            }

            state.next(this.getNewState(allItems, args.totalCount, currentStateValue));
        }, error => {
            this.logger.error({ message: `An error was encountered retrieving dynamic items of type: '${loadItems.entityData.metadata.setName}'`, code: "loadItems" });
        });
    }

    getItemChanges(): Observable<ItemChange> {
        return this.itemChanges$;
    }

    notifyItemChange(key: string, entityData: EntityData, action: string): void {
        this.itemChanges$.next({
            key: key,
            entityData: entityData,
            action: action
        });
    }

    // TODO: instead of the complex logic bellow, we should get the item after the delete and see if the item has changed
    private deleteItemFromMemory(itemKey: string, entityData: EntityData, deleteAllTranslations: boolean = false, itemPosition: ItemPosition = ItemPosition.Default) {
        const currentStoreState = this.getState(entityData);
        const currentStateValue = currentStoreState.getValue();
        const dynamicItems: DataItem[] = currentStateValue.dataItems;

        const updatedDynamicItems: DataItem[] = [];
        let itemToRemove: DataItem;
        let itemOriginalIndex: number;
        let itemTranslations: string[] = [];

        dynamicItems.forEach((dynamicItem, index) => {
            if (dynamicItem.key === itemKey) {
                itemOriginalIndex = index;
                itemToRemove = dynamicItem;
                itemTranslations = dynamicItem.data[Properties.AvailableLanguages];
            } else {
                updatedDynamicItems.push(dynamicItem);
            }
        });

        // if itemToRemove is null, then itemTranslations will remain an empty array
        if (itemTranslations.length > 1 && !deleteAllTranslations) {
            const loadItemsByKeys: LoadItemsByKeysData = {
                keys: [itemToRemove.key],
                entityData: entityData,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                keyProperty: entityData.metadata.key
            };

            // This fix is for a fallback of the Title
            // getItem is now using "getSingle" insted of "get" from the sdk
            // "getSingle" does not support fallbackProperties
            this.dynamicItemService.getItemsByKeys(loadItemsByKeys).pipe(
                finalize(() => {
                    currentStoreState.next(this.getNewState(updatedDynamicItems, currentStoreState.itemsCount, currentStateValue));
                }))
                .subscribe(data => {
                    const dataItems = data.dataItems;
                    if (dataItems && dataItems.length) {
                        if (itemPosition === ItemPosition.Default) {
                            itemPosition = this.getItemPosition(currentStateValue);
                        }

                        if (itemPosition === ItemPosition.Bottom && currentStateValue.totalCount > updatedDynamicItems.length + 1) {
                            this.reloadState(currentStateValue, entityData);
                        } else {
                            this.insertItem(dataItems[0], updatedDynamicItems, itemPosition, itemOriginalIndex);
                        }
                    }
                });
        } else {
            currentStoreState.itemsCount -= 1;
            currentStoreState.next(this.getNewState(updatedDynamicItems, currentStoreState.itemsCount, currentStateValue));
        }
    }

    private createItem(createItemArgs: CreateItem): Observable<ItemWithOperationResult> {

        const create$ = this.dynamicItemService.createItemWithOperationResult(createItemArgs);
        create$.subscribe(result => {
            const state = this.getState(createItemArgs.entityData);
            state.itemsCount += 1;
            const currentStateValue = state.getValue();
            const dynamicItems = currentStateValue.dataItems;

            this.insertItem(result.dataItem, dynamicItems, createItemArgs.itemPosition);

            const exceedsItemLimit = dynamicItems.length > this.externalAppConfigService.externalConfig.contentItemsPerPage;
            const isNewPage = (dynamicItems.length - 1) % this.externalAppConfigService.externalConfig.contentItemsPerPage === 0;

            if (exceedsItemLimit && isNewPage) {
                dynamicItems.pop();
            }

            this.childrenCountStore.invalidateCachedChidrenCountByChildItem(result.dataItem);

            state.next(this.getNewState(dynamicItems, state.itemsCount, currentStateValue));
        }, (err) => {
            // remove this once RXJS have fixed this issue https://github.com/ReactiveX/rxjs/issues/3128
        });

        return create$;
    }

    private insertItem(dataItem: DataItem, dataItemsCollection: DataItem[], itemPosition: ItemPosition, index?: number): void {
        if (itemPosition === ItemPosition.Current && index >= 0) {
            dataItemsCollection.splice(index, 0, dataItem);
        } else if (itemPosition === ItemPosition.Bottom) {
            dataItemsCollection.push(dataItem);
        } else {
            dataItemsCollection.unshift(dataItem);
        }
    }

    private updateItem(updateItemArgs: UpdateItem): Observable<ItemWithOperationResult> {
        const update$ = this.dynamicItemService.updateItemWithOperationResult(updateItemArgs);

        update$.subscribe((result) => {
            this.refreshItem(result.dataItem, updateItemArgs.itemPosition);
        }, (error: GenericError) => {
            if (error instanceof NotFoundError) {
                this.deleteItemFromMemory(updateItemArgs.dataItem.key, updateItemArgs.dataItem);
            }
        });

        return update$;
    }

    refreshItem(item: DataItem, itemPosition: ItemPosition = ItemPosition.Default): void {
        const state = this.getState(item);
        const currentStateValue = this.getState(item).getValue();
        const dynamicItems = currentStateValue.dataItems;
        const itemIndex = dynamicItems.findIndex((element) => element.key === item.key);

        if (item instanceof HierarchicalDataItem) {
            return this.refreshHierarchicalItem(item, state);
        }

        if (itemIndex === -1)
            return;

        if (itemPosition === ItemPosition.Default) {
            itemPosition = this.getItemPosition(currentStateValue);
        }

        if (itemPosition === ItemPosition.Current) {
            dynamicItems[itemIndex] = item;
        } else {
            dynamicItems.splice(itemIndex, 1);
            if (itemPosition === ItemPosition.Top) {
                dynamicItems.unshift(item);
            } else if (itemPosition === ItemPosition.Bottom) {
                if (currentStateValue.totalCount > dynamicItems.length + 1) {
                    this.reloadState(currentStateValue, item);
                } else {
                    dynamicItems.push(item);
                }
            } else {
                dynamicItems.unshift(item);
            }
        }

        state.next(this.getNewState(dynamicItems, currentStateValue.totalCount, currentStateValue));
    }

    private refreshHierarchicalItem(item: HierarchicalDataItem, state: DynamicItemStoreState) {
        const itemState = state.getValue();

        for (const rootItem of itemState.dataItems) {
            this.findAndReplaceHierarchicalItem(rootItem, item, itemState.dataItems);
        }

        state.next(itemState);
    }

    private findAndReplaceHierarchicalItem(currentItem: DataItem, newItem: HierarchicalDataItem, siblings: DataItem[]) {
        if (currentItem.key === newItem.key) {
            const index = siblings.findIndex(x => x.key === newItem.key);

            // Replace the found child item with the updated one
            siblings.splice(index, 1, newItem);
            return;
        }

        if (currentItem instanceof HierarchicalDataItem && currentItem.children && currentItem.children.length) {
            for (const child of currentItem.children) {
                this.findAndReplaceHierarchicalItem(child, newItem, currentItem.children);
            }
        }
    }

    private reloadState(currentStateValue: ItemsState, entityData: EntityData): void {
        this.loadItems({
            entityData: entityData,
            fallbackProperties: [entityData.metadata.defaultFieldName],
            action: currentStateValue.action,
            query: currentStateValue.query,
            skip: 0,
            take: currentStateValue.take,
            order: currentStateValue.order
        });
    }

    private getItemPosition(itemsState: ItemsState): ItemPosition {
        if (itemsState.order === LAST_MODIFIED_DESC_SORT_ORDER) {
            return ItemPosition.Top;
        }

        if (itemsState.order === LAST_MODIFIED_ASC_SORT_ORDER) {
            return ItemPosition.Bottom;
        }

        return ItemPosition.Current;
    }

    private getNewState(newDataItems: DataItem[], newTotalCount: number, currentStateValue: ItemsState): ItemsState {
        return {
            dataItems: newDataItems,
            totalCount: newTotalCount || 0,
            query: currentStateValue.query,
            order: currentStateValue.order,
            skip: currentStateValue.skip,
            take: currentStateValue.take,
            action: currentStateValue.action
        };
    }

    private getState(entity: EntityData) {
        // TODO: cache
        // const key = `${entity.metadata.setName}_${entity.provider}_${entity.culture}`;
        const key = "default";
        if (!this.stateCache.has(key)) {
            this.stateCache.set(key, new DynamicItemStoreState());
        }

        return this.stateCache.get(key);
    }
}

export interface FilterCriteria {
    propertyName: string;
    value: any;
}

export enum FilterTypes {
    Custom,
    Search,
    SingleProperty
}

export interface FilterValue {
    key: string;
    values: string[];
}

export interface Filter {
    values: FilterValue[];
    type: FilterTypes;
}

export interface ItemChange {
    key: string;
    entityData: EntityData;
    action: string;
}
