import { ClassProvider, Inject, Injectable, Optional } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { Observable, of, never, ReplaySubject } from "rxjs";
import TAXONOMY_CONSTANTS from "../taxonomy.constants";
import { createQuery } from "../../../services/query";
import { FILTER_PARAMS, ROUTE_PARAMS, RESOLVE_NAMES, QUERY_PARAMS, FILTER_TYPES } from "../../content/constants";
import { DYNAMIC_ITEMS_DATA_NAME } from "../../content/dynamic-modules/components/dynamic-item-index.constants";
import { EMPTY_SCREEN_ICONS } from "../../content/dynamic-modules/dynamic-item.constants";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { LoadItemsData, LoadItemsResponse, ItemWithOperationResult, DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { GRID_EXTENDER_TOKEN, ItemsDataContext, TitleArgs, ExpandedNodeIdsSet, ExpandedNodeIdsGet, GridExtenderBase } from "../../shared/services/grid/grid-extender-base";
import { HierarchicalService, HIERARCHICAL_SERVICE_TOKEN, PARENT_KEY } from "../../shared/services/hierarchical-service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { DisabledFilterLoaders } from "../../content/dynamic-modules/components/sidebar/list-item-filter-interfaces";
import { SiteData } from "../../shared/services/metadata/site-data.store";
import { HierarchicalTaxonExpandService } from "./hierarchical-taxon-expand-service";
import { mergeMap, map } from "rxjs/operators";
import { ActionExecutorService, ExecuteServerAction } from "../../shared/services/action-executor.service";
import { ModalWindowService, CancelButton, ModalComponentSettings, Button } from "../../shared/services/modal-window.service";
import { stringConstants } from "../../../common-constants";
import { ActionIcon } from "../../content/dynamic-modules/services/entity/action-buttons";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { Settings } from "../../shared/services/settings.service";
import { TaxonomyService } from "./taxonomy.service";
import { CLASSIFICATIONS_NAME } from "../../content/modules.provider";
import { QuickNavigationSidebarSection } from "../../content/dynamic-modules/components/sidebar/quick-navigation-sidebar.component";
import { NavigateCommand } from "../../content/dynamic-modules/services/operations/commands/navigate-command";
import { StateWrapper } from "../../content/dynamic-modules/services/dynamic-item-store-state";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { SortService, DEFAULT_ORDINAL_EXPRESSION } from "../../shared/services/sort.service";
import { BackendTweaksStore } from "../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { ContentFilterService } from "../../shared/services/content-filter.service";
import { ColumnModel } from "../../shared/models/column-model";
import { GridReloadService } from "../../content/dynamic-modules/services/grid-reload.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { ExternalAppConfigService } from "../../../app-config/external-app-config.service";
import { CompositeOperationsProvider } from "../../content/dynamic-modules/services/operations/operations-provider";

@Injectable()
export class TaxonomyGridExtender extends GridExtenderBase {
    constructor(
        dynamicItemStore: DynamicItemStore,
        private metadataStore: MetadataStore,
        private taxonomyService: TaxonomyService,
        private hierarchicalTaxonExpandService: HierarchicalTaxonExpandService,
        @Optional() @Inject(HIERARCHICAL_SERVICE_TOKEN) private hierarchicalServices: HierarchicalService[],
        contentFilterService: ContentFilterService,
        modalWindowService: ModalWindowService,
        private itemService: DynamicItemService,
        settings: Settings,
        sortService: SortService,
        backendTweaksStore: BackendTweaksStore,
        reloadService: GridReloadService,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        externalAppConfigService: ExternalAppConfigService,
        operationsProvider: CompositeOperationsProvider) {
        super(contentFilterService, dynamicItemStore, settings, sortService, backendTweaksStore, reloadService, modalWindowService, notificationService, externalAppConfigService, operationsProvider);
    }

    getExpandedNodeIds(args: ExpandedNodeIdsGet): Observable<string[]> {
        return this.hierarchicalTaxonExpandService.getExpandedNodeIds();
    }

    setExpandedNodeIds(args: ExpandedNodeIdsSet): void {
        this.hierarchicalTaxonExpandService.setExpandedNodeIds(args.expandedIds);
    }

    isHierarchical(route: ActivatedRoute): boolean {
        const entityData = route.snapshot.data[DYNAMIC_ITEMS_DATA_NAME];
        const setName = entityData.metadata.setName;
        const hierarchicalService = this.getHierarchicalService(entityData);
        if (hierarchicalService && hierarchicalService.isHierarchical(setName)) {
            return !route.snapshot.queryParams[FILTER_PARAMS.FILTER] &&
                !route.snapshot.queryParams[FILTER_PARAMS.SEARCH] &&
                (!route.snapshot.queryParams[FILTER_PARAMS.SORT] || route.snapshot.queryParams[FILTER_PARAMS.SORT] === DEFAULT_ORDINAL_EXPRESSION);
        }

        return false;
    }

    getTotalItemsCountWithChildren(currentStateTotalCount: number, route: ActivatedRoute): Observable<number> {
        if (this.isHierarchical(route)) {
            const entityData = route.snapshot.data["dynamicItems"];
            const parentId = route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
            const query = createQuery()
                .where()
                .eq(entityData.metadata.parentIdProperty, parentId)
                .done();

            const loadData: LoadItemsData = {
                entityData: entityData,
                query: query,
                dataFieldNames: [entityData.metadata.defaultFieldName],
                order: null,
                skip: null,
                take: 0,
                action: null,
                fallbackProperties: [entityData.metadata.defaultFieldName]
            };

            return this.itemService.getItemList(loadData).pipe(map(r => r.totalCount));
        }

        return of(currentStateTotalCount);
    }

    getChildren(entityData: EntityData, parentId: string, serviceInfo: ServiceInfo, columns: ColumnModel[]): Promise<LoadItemsResponse> {
        const hierarchicalService = this.getHierarchicalService(entityData);
        if (hierarchicalService) {
            return hierarchicalService.expandChildren(serviceInfo, entityData, parentId).toPromise();
        }

        return new Promise(resolve => resolve(null));
    }

    getDisabledFilterLoaders(route: ActivatedRoute): DisabledFilterLoaders {
        const entityData = route.snapshot.data["dynamicItems"];
        if (entityData.metadata.setName === TAXONOMY_CONSTANTS.FLAT_TAXA ||
            entityData.metadata.setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA) {
            let siteData = route.snapshot.parent.data[RESOLVE_NAMES.siteDataStore] as SiteData;
            if (!siteData) {
                siteData = route.snapshot.data[RESOLVE_NAMES.siteDataStore] as SiteData;
            }

            if (siteData) {
                const disableContentFilterLoaders = siteData.ContentCultures && siteData.ContentCultures.length === 1;
                return { disableContentFilterLoaders };
            }
        }

        return null;
    }

    reloadItems(queryParams: { [key: string]: string }, parentId: string, entityData: EntityData, sortParam: string, dataFieldNames: string[]): Observable<StateWrapper> {
        const loadItemsArg = this.contentFilterService.getLoadArguments(queryParams, parentId, entityData, sortParam, dataFieldNames);
        this.dynamicItemStore.loadItems(loadItemsArg);
        return never();
    }

    getItemsData(route: ActivatedRoute, dataFieldNames: string[], args?: ItemsDataContext): LoadItemsData {
        const entityData = route.snapshot.data["dynamicItems"];
        const parentId = route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
        const query = createQuery()
            .where()
            .and()
            .eq(entityData.metadata.parentIdProperty, parentId)
            .eq(PARENT_KEY, null)
            .done()
            .done();

        // add data field name "HasChildren" for hierarchical taxa only
        const hierarchicalService = this.getHierarchicalService(entityData);
        if (hierarchicalService && hierarchicalService.isHierarchical(entityData.metadata.setName)) {
            if (!dataFieldNames[entityData.metadata.hasChildrenProperty]) {
                dataFieldNames.push(entityData.metadata.hasChildrenProperty);
            }
        }

        return {
            entityData: entityData,
            query: query,
            dataFieldNames: dataFieldNames,
            order: args ? args.order : null,
            skip: args ? args.skip : null,
            take: args ? args.take : null,
            action: args ? args.action : null,
            fallbackProperties: [entityData.metadata.defaultFieldName]
        };
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === TAXONOMY_CONSTANTS.TAXONOMIES_SET_NAME ||
            entityData.metadata.setName === TAXONOMY_CONSTANTS.FLAT_TAXA ||
            entityData.metadata.setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA;
    }

    getTitle(args: TitleArgs): Observable<string> {
        if (args.parentItem && args.parentItem.data && args.parentItem.data.DefaultTitle) {
            return of(`${args.parentItem.data.DefaultTitle}`);
        } else {
            return super.getTitle(args);
        }
    }

    getSingleItemName(titleArgs: TitleArgs): Observable<{ primary: string, secondary: string }> {
        if (titleArgs.parentItem && titleArgs.parentItem.data && titleArgs.parentItem.data.DefaultTaxonName) {
            const title = `${titleArgs.parentItem.data.DefaultTaxonName}`;
            return of({ primary: title, secondary: title });
        } else {
            return super.getSingleItemName(titleArgs);
        }
    }

    getPluralItemName(titleArgs: TitleArgs): Observable<{ primary: string, secondary: string }> {
        if (titleArgs.parentItem && titleArgs.parentItem.data && titleArgs.parentItem.data.DefaultTitle) {
            const title = `${titleArgs.parentItem.data.DefaultTitle}`;
            return of({ primary: title, secondary: title });
        } else {
            return super.getPluralItemName(titleArgs);
        }
    }

    getEmptyScreenIcon(itemType: string): string {
        return EMPTY_SCREEN_ICONS[itemType];
    }

    getDefaultSort(entityData: EntityData): string {
        if (entityData.metadata.setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA) {
            return DEFAULT_ORDINAL_EXPRESSION;
        }

        return TAXONOMY_CONSTANTS.TAXONOMY_DEFAULT_SORT;
    }

    executeNavigateCommand(router: Router, route: ActivatedRoute, dataItem: DataItem, entityData: EntityData, childSetName: string = null): Observable<any> {
        const additionalQueryParams: any = {};
        if (route.snapshot.queryParams[FILTER_PARAMS.FILTER] === FILTER_TYPES.NOT_USED &&
            entityData.metadata.setName === TAXONOMY_CONSTANTS.TAXONOMIES_SET_NAME) {
                additionalQueryParams[QUERY_PARAMS.IGNORE_SITE_CONTEXT] = true;
        }

        return new NavigateCommand(router)
            .execute({
                currentRoute: route,
                data: {
                    dataItem: dataItem,
                    metadata: entityData,
                    parentSetName: this.getParentSetName(entityData),
                    childSetName: childSetName,
                    navigateToGrid: dataItem && this.shouldNavigateToChildGrid(dataItem),
                    isChildNavigate: dataItem && dataItem.metadata.setName === entityData.metadata.setName && Object.keys(dataItem.data).length > 1,
                    additionalQueryParams: additionalQueryParams
                },
                model: null
            });
    }

    executeServerAction(executorService: ActionExecutorService, context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        if (context.updateItem.dataItem.metadata.setName === TAXONOMY_CONSTANTS.TAXONOMIES_SET_NAME &&
            context.actionButton.sourceOperation.Name === OPERATION_NAMES.delete) {
            return this.handleDeleteTaxonomyCommand(executorService, context);
        }

        return executorService.execute(context);
    }

    getSidebarDisplayName(entityData: EntityData, parentItem: DataItem): string {
        if (parentItem && parentItem.data && parentItem.data.DefaultTitle) {
            return `${parentItem.data.DefaultTitle}`;
        } else {
            return entityData.metadata.displayName;
        }
    }

    getQuickNavigationSidebarSections(entityData: EntityData, parentItem: DataItem): Observable<QuickNavigationSidebarSection[]> {
        const quickNavSidebarComponentData = new ReplaySubject<QuickNavigationSidebarSection[]>(1);
        if (parentItem === null) {
            return of([]);
        }

        this.taxonomyService.getTaxonomies([]).then(taxonomies => {
            const flatList = taxonomies.filter(t => t.TaxaUrl === TAXONOMY_CONSTANTS.FLAT_TAXA);
            const hierarhicalList = taxonomies.filter(t => t.TaxaUrl === TAXONOMY_CONSTANTS.HIERARCHY_TAXA);

            // add section for back to all classifications link
            const classificationMetadata = this.metadataStore.getEntity(TAXONOMY_CONSTANTS.TAXONOMIES_SET_NAME);
            const entityDataClassifications: EntityData = {
                metadata: classificationMetadata,
                culture: entityData.culture,
                provider: entityData.provider
            };
            const allClassifications: QuickNavigationSidebarSection = {
                dataItems: [DataItem.fromEntityData({Title: `All ${CLASSIFICATIONS_NAME.toLowerCase()}`}, entityDataClassifications)],
                sourceEntityData: entityData,
                title: null
            };

            const hierarchicalSection = this.getQuickNavigationSidebarSection(hierarhicalList, entityDataClassifications);
            const flatSection = this.getQuickNavigationSidebarSection(flatList, entityDataClassifications);

            quickNavSidebarComponentData.next([
                hierarchicalSection,
                flatSection,
                allClassifications
            ]);
        });

        return quickNavSidebarComponentData.asObservable();
    }

    getQuickNavigationSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        return `Browse ${CLASSIFICATIONS_NAME.toLowerCase()}`;
    }

    hasLongRunningTasks(entityData: EntityData): boolean {
        if (entityData.metadata.setName === TAXONOMY_CONSTANTS.FLAT_TAXA || entityData.metadata.setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA) {
            return true;
        }

        return super.hasLongRunningTasks(entityData);
    }

    getParentSetName(entityData: EntityData) {
        return TAXONOMY_CONSTANTS.TAXONOMIES_SET_NAME;
    }

    protected isPagingPersistenceEnabled(): boolean {
        return true;
    }

    protected clearTemporaryData() {
        super.clearTemporaryData();
        this.hierarchicalTaxonExpandService.clearExpandedNodeIds();
    }

    private getQuickNavigationSidebarSection(taxonomies: any[], entityData: EntityData): QuickNavigationSidebarSection {
        const dataItems: DataItem[] = [];
        taxonomies.forEach(taxonomy => {
            dataItems.push(DataItem.fromEntityData(taxonomy, entityData));
        });

        return {
            dataItems: dataItems,
            sourceEntityData: entityData,
            title: taxonomies[0].Type
        };
    }

    private handleDeleteTaxonomyCommand(executorService: ActionExecutorService, context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        const action = "Default.GetItemTypesUsingTaxonomy()";
        const loadItemsFunction = this.itemService.executeBoundFunction<any>(context.updateItem.dataItem, action.toLowerCase());
        let contentTypesUsingTaxonomy = stringConstants.EMPTY_STRING;

        const result = loadItemsFunction.pipe(mergeMap((result): Observable<ItemWithOperationResult> => {
            if (result.value.length) {
                contentTypesUsingTaxonomy = result.value.map((i: { DisplayName: string; }) => i.DisplayName).join(", ");

                const modalTitle = "Classification cannot be deleted";
                const modalDescription = `Classification ${context.updateItem.dataItem.data.Title} is used in content types: ${contentTypesUsingTaxonomy}. Remove it from any content types first and then delete the classification.`;
                const modalButtons = [new CancelButton("Close")];
                const settings = this.generateModalWarningSettings(modalTitle, modalDescription, modalButtons);

                this.modalWindowService.openModalConfirmation(context.route.parent, settings, context.updateItem.dataItem);

                return of();
            } else {
                return executorService.execute(context);
            }
        }));

        return result;
    }

    private generateModalWarningSettings(title: string, description: string, buttons: Button[]): ModalComponentSettings {
        const settings: ModalComponentSettings = {
            title: title,
            description: description,
            icon: ActionIcon.Delete,
            action: stringConstants.EMPTY_STRING,
            hideItemTitle: true,
            buttons: buttons
        };

        return settings;
    }

    private getHierarchicalService(entityData: EntityData): HierarchicalService {
        const service = this.hierarchicalServices.find(x => entityData && x.isTypeSupported(entityData));

        return service;
    }
}

export const TAXONOMY_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: TaxonomyGridExtender
};
