import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../../fields";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";

@Component({
    selector: "sf-taxonomy-type-choice",
    templateUrl: "./taxonomy-type-choice.component.html"
})
export class TaxonomyTypeChoiceComponent extends FieldBase<ChoiceSettings> implements OnInit {
    ngOnInit() {
        this.settings.choiceShowFriendlyName = true;
        const preselected = this.settings.choices.find(x => x.Value === this.settings.defaultValue);
        if (preselected) {
            this.writeValue(preselected.Value);
        }
    }

    onSelectionChange(val: string) {
        this.writeValue(val);
    }
}
