import { Injectable, Inject } from "@angular/core";
import { LoggerSource, LogCategory, Log } from "./logger-source";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { GenericError } from "../errors/generic-error";

const LOG_PROCESS_DELAY = 1000;

/**
 * Logger that creates logs of several types.
 * Depending on the source, the logger can write
 * the logs to the console, send them to some
 * endpoint, write them to file etc.
 *
 * @export
 * @class Logger
 */
@Injectable()
export class Logger {
    private logs: Log[] = [];
    private loggingProcessTimer: number;

    constructor(@Inject(LoggerSource) private readonly sources: LoggerSource[],
                @Inject(WINDOW_TOKEN) private readonly window: Window) { }

    /**
     * Creates a log of type any (informational).
     *
     * @param {string} data The data that will be logged.
     * @memberof Logger
     */
    log(data: string) {
        const log: Log = {
            category: LogCategory.Any,
            data: { message: data }
        };

        this.logInternal(log);
    }

    /**
     * Creates a log of type warning.
     *
     * @param {string} data The data that will be logged.
     * @memberof Logger
     */
    warn(data: string) {
        const log: Log = {
            category: LogCategory.Warn,
            data: { message: data }
        };

        this.logInternal(log);
    }

    /**
     * Creates a log of type error.
     *
     * @param {Error} data The data that will be logged.
     * @memberof Logger
     */
    error(data: GenericError) {
        const log: Log = {
            category: LogCategory.Error,
            data: { message: data.message, stackTrace: data.stack }
        };

        this.logInternal(log);
    }

    /**
     * Delegates the provided data to the sources, so they can handle
     * different logging logics.
     * @param category The category of the error, eg "Error", "Warn", "Any".
     * @param data The data that will be logged.
     */
    private logInternal(log: Log) {
        const isDuplicatedLog = this.isDuplicatedLog(log);

        if (!isDuplicatedLog) {
            this.logs.push(log);
        }

        /**
         * Logging operations should be delayed. If there is already a running
         * timer, a new one wont be started. After the timer elapses, all the
         * logs from the logs queue will be processed.
         */
        if (!this.loggingProcessTimer) {
            this.loggingProcessTimer = this.window.setTimeout(() => {
                this.loggingProcessTimer = 0;
                this.sources.forEach(source => source.process(this.logs));
                this.logs = [];
            }, LOG_PROCESS_DELAY);
        }
    }

    /**
     * Log is considered duplicated when it has
     * the same message as the last added log to
     * the queue and if both logs have stacktrace,
     * the length of the stacktraces should be
     * the same.
     *
     * @private
     * @param {Log} log Newly comming log.
     * @returns {boolean} Flag that indicates if the log is duplicated with the last one.
     * @memberof Logger
     */
    private isDuplicatedLog(log: Log): boolean {
        if (!this.logs.length) {
            return false;
        }

        const lastLog = this.logs[this.logs.length - 1];
        const currentLogStackTrace = log.data.stackTrace;
        const lastLogStackTrace = lastLog.data.stackTrace;
        let logsHaveEqualLength = false;

        if (currentLogStackTrace && lastLogStackTrace && currentLogStackTrace.length === lastLogStackTrace.length) {
            logsHaveEqualLength = true;
        }

        const logsHaveEqualMessages = log.data.message === lastLog.data.message;
        const isDuplicatedLog = logsHaveEqualMessages && logsHaveEqualLength;

        return isDuplicatedLog;
    }
}
