import { Entity } from "./meta-data.store";
import { FieldModel } from "../../../../services/field.model";
import { FormData } from "../../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { CompositeFieldSettings, InnerFieldsData } from "../composite-field.settings";
import { DEFAULT_PROPERTY_VALUE } from "../../../../../../fields/common/common-constants";
import { createFieldModel } from "../../fields.constants";
import { CompositeFieldsProvider } from "../../fields-builder/providers/fields-provider";
import { stringConstants } from "../../../../common-constants";

export abstract class MetadataHandler {
    abstract fieldGroups: any[];

    constructor(protected fieldsProvider: CompositeFieldsProvider) { }

    abstract getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string;

    abstract canProcess(typeFullName: string): boolean;

    updateFieldSettings(fields: FieldModel[], metadata: Entity, tweaks: any[]) { }

    updateInnerFieldsSettings(innerFields, tweaks: FormData[], readonly: boolean) { }

    updateAdditionalSettings(propertyName: string, tweaks: FormData[], compositeFieldModel: FieldModel) { }

    processFieldGroup(propertyName: string, fields: FieldModel[], metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean, tweaks: FormData[]): string[] {
        const group = this.fieldGroups.find(gr => gr.fields.some(x => x === propertyName));
        if (group) {
            const isReadOnly = readonly || tweaks.every(x => x.readonly);
            const compositeFieldModel = createFieldModel(this.fieldsProvider, null, group.fieldType, group.fields[0], null, null, null, null, isReadOnly);

            compositeFieldModel.key = group.fields[0];
            fields.push(compositeFieldModel);
            this.updateCompositeField(compositeFieldModel, group, metadata, fieldTypesMap, dataItem, isReadOnly);
            this.updateInnerFieldsSettings((compositeFieldModel.settings as CompositeFieldSettings).innerFields, tweaks, readonly);
            this.updateAdditionalSettings(propertyName, tweaks, compositeFieldModel);

            return group.fields;
        }

        return [];
    }

    private updateCompositeField(compositeFieldModel: FieldModel, group: any, metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean) {
        const innerFieldsData: InnerFieldsData = this.getInnerFieldsData(group, metadata, fieldTypesMap, dataItem, readonly);
        const compositeSettings = compositeFieldModel.settings as CompositeFieldSettings;

        compositeSettings.itemId = dataItem ? dataItem.Id : stringConstants.DEFAULT_GUID;
        compositeSettings.innerFields = innerFieldsData;
        compositeFieldModel.settings.showForAllTranslationsLabel = false;
        compositeFieldModel.settings.readOnlyMode = readonly;
        compositeSettings.showTitle = false;

        let compositeFieldInitialValue = null;
        Object.keys(innerFieldsData).forEach(innerFieldName => {
            const innerFieldValue = innerFieldsData[innerFieldName].value;

            if (innerFieldValue !== null && innerFieldValue !== undefined) {
                if (compositeFieldInitialValue === null) {
                    compositeFieldInitialValue = {};
                }

                compositeFieldInitialValue[innerFieldName] = innerFieldValue;
            }
        });

        compositeFieldModel.value = compositeFieldInitialValue;
    }

    private getInnerFieldsData(group: any, metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean): InnerFieldsData {
        const innerFieldsData: InnerFieldsData = {};
        group.fields.forEach(fieldName => {
            const fieldType = fieldTypesMap.get(fieldName);
            let value = dataItem ? dataItem[fieldName] : null;
            const hasNoValue = value === null || value === undefined;
            if (hasNoValue && metadata.properties[fieldName] && metadata.properties[fieldName].hasOwnProperty(DEFAULT_PROPERTY_VALUE)) {
                value = metadata.properties[fieldName][DEFAULT_PROPERTY_VALUE];
            }

            const innerFieldModel = createFieldModel(this.fieldsProvider, metadata.setName, fieldType, fieldName, value, metadata.properties[fieldName], group.titles[fieldName], null, readonly);

            innerFieldsData[fieldName] = innerFieldModel;
        });

        return innerFieldsData;
    }
}
