import { Component, Input, OnInit } from "@angular/core";
import { DataContext } from "../../../shared/models/data-context-component";
import { stringConstants } from "../../../../common-constants";

@Component({
    templateUrl: "./file-grid-size.component.html"
})
export class FileSizeComponent implements OnInit {
    @Input() public context: DataContext;
    fileExtension: string = stringConstants.EMPTY_STRING;
    fileSizeInKb: number = 0;

    ngOnInit() {
        const item = this.context.dataItem.data;
        if (item.Extension) {
            this.fileExtension = item.Extension.replace(".", stringConstants.EMPTY_STRING).toUpperCase();
        }

        if (item.TotalSize) {
            this.fileSizeInKb = Math.round(item.TotalSize / 1024);
        }
    }
}
