import { Component, Inject, OnInit, OnDestroy } from "@angular/core";
import { select } from "@ngrx/store";
import { first } from "rxjs/operators";
import { Subscription, fromEvent as observableFromEvent } from "rxjs";
import { MOBILE_PREVIEW_ACTIONS } from "../../../../services/store/actions/actions.mobile-preview";
import { AppStore } from "../../../../services/store/app-store";
import { DOCUMENT_TOKEN } from "../../../../document.provider";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const BREAKPOINTS: MobilePreviewBreakPoint[] = [
    { width: 360, iconName: "mobile", iconLook: "black size-2xl" },
    { width: 480, iconName: "mobile", iconLook: "black size-2xl" },
    { width: 640, iconName: "mobile", iconLook: "black size-2xl sf-rotate--90" },
    { width: 768, iconName: "tablet", iconLook: "black size-2xl" },
    { width: 1024, iconName: "tablet", iconLook: "black size-2xl sf-rotate--90" }
];

@Component({
    selector: "sf-mobile-preview-resizer",
    templateUrl: "./mobile-preview-resizer.component.html",
    styleUrls: ["./mobile-preview-resizer.component.scss"]
})
export class MobilePreviewResizerComponent extends SfRxBase implements OnInit, OnDestroy {
    initialPreviewWidth: number;
    sliderValue: number;
    maxZIndex: number = 100000;
    breakpoints: MobilePreviewBreakPoint[] = BREAKPOINTS.sort((l, r) => l.width - r.width);
    iconName: string = this.breakpoints[0].iconName;
    iconLook: string = this.breakpoints[0].iconLook;
    minSliderValue: number = this.breakpoints[0].width;
    maxSliderValue: number = this.breakpoints[this.breakpoints.length - 1].width;
    dragArrowColor: string = "light";
    isDragging: boolean;
    isDraggingLeftArrow: boolean;
    mouseMoveSubscription: Subscription;
    mouseUpSubscription: Subscription;

    constructor(private store: AppStore,
                @Inject(DOCUMENT_TOKEN) private documentProvider: Document) {
        super();
    }

    ngOnInit(): void {
        this.registerSubscription(this.store.pipe(first(), select(state => {
            const width = state.mobilePreview.width;
            this.initialPreviewWidth = width;
            this.sliderValue = width;
            this.changeIconBasedOnWidth(width);
        })).subscribe());
        this.mouseMoveSubscription = observableFromEvent(this.documentProvider, "mousemove")
            .subscribe((e: MouseEvent) => {
                if (this.isDragging) {
                    this.onArrowDrag(e, this.isDraggingLeftArrow);
                }
            });
        this.mouseUpSubscription = observableFromEvent(this.documentProvider, "mouseup")
            .subscribe((e: MouseEvent) => {
                if (this.isDragging) {
                    this.onArrowDragEnd(e);
                }
            });

        this.registerSubscription(this.mouseMoveSubscription);
        this.registerSubscription(this.mouseUpSubscription);
    }

    ngOnDestroy() {
        this.mouseMoveSubscription.unsubscribe();
        this.mouseUpSubscription.unsubscribe();
    }

    onResize(width: number) {
        this.sliderValue = width;
        this.changeIconBasedOnWidth(width);
        this.store.dispatch(MOBILE_PREVIEW_ACTIONS.changeWidth({ width }));
    }

    onArrowDragStart ($event, isLeftArrow) {
        this.isDragging = true;
        this.dragArrowColor = "black";
        this.isDraggingLeftArrow = isLeftArrow;

    }

    onArrowDragEnd ($event) {
        this.isDragging = false;
        this.dragArrowColor = "light";
    }

    focusDragArrow($event, isHover) {
        this.dragArrowColor = isHover ? "black" : "light";
    }

    onArrowDrag($event, isLeftArrow: boolean): void {
        if ($event.clientX > 0) {
            const viewportWidth = this.documentProvider.documentElement.clientWidth;
            const customClientX = (isLeftArrow) ? $event.clientX : viewportWidth - $event.clientX;
            let newSliderValue = (viewportWidth / 2 - customClientX) * 2;

            if (newSliderValue >= this.maxSliderValue) {
                newSliderValue = this.maxSliderValue;
            } else if (newSliderValue <= this.minSliderValue) {
                newSliderValue = this.minSliderValue;
            }
            this.onResize(newSliderValue);
        }
    }

    private changeIconBasedOnWidth(width: number) {
        const foundBreakpoint = this.breakpoints.find(bp => bp.width >= width);
        if (foundBreakpoint) {
            this.iconName = foundBreakpoint.iconName;
            this.iconLook = foundBreakpoint.iconLook;
        }
    }
}

export interface MobilePreviewBreakPoint {
    width: number,
    iconName: string,
    iconLook: string
}
