import { never, Observable } from "rxjs";

import { map, filter } from "rxjs/operators";
import { Injectable, InjectionToken } from "@angular/core";

import { Settings } from "./settings.service";
import { RequestWrapper } from "./request.wrapper";
import { LoadingContentState, toLoadingState } from "../rxjs-extensions/toLoadingState";
import { QUERY_PARAMS } from "../../content/constants";
import { AuthService } from "../../auth/auth.service";
import { HttpClient, HttpHeaders, HttpParams } from "@angular/common/http";

export const HTTP_ODATA_REQUEST_WRAPPER = new InjectionToken("HttpODataRequestWrapper");

@Injectable()
export class HttpODataRequestWrapper implements RequestWrapper {

    constructor(
        private authService: AuthService,
        private http: HttpClient,
        private settings: Settings) { }

    /**
     * @deprecated Use get$ instead
     */
    get(relativeUrl: string, options?: any): Promise<any> {
        const promiseExecutor = (resolve, reject) => {
            this.get$(relativeUrl, options).pipe(filter(x => !x.isLoading), map(x => x.content)).subscribe(resolve, reject);
        };

        return new Promise(promiseExecutor);
    }

    get$(relativeUrl: string, options?: any): Observable<LoadingContentState<any>> {
        if (!relativeUrl) {
            return never();
        }

        const headers = this.getRequestHeaders();
        const requestOptions: {
            headers?: HttpHeaders;
            observe?: "body";
            params?: HttpParams | {
                [param: string]: string | string[];
            };
            reportProgress?: boolean;
            responseType?: "json";
            withCredentials?: boolean;
        } = { headers };

        const url = `${this.settings.webServiceUrl}${relativeUrl}`;
        requestOptions.params = { [QUERY_PARAMS.SITE]: this.settings.siteId };

        if (options && options.params) {
            Object.assign(requestOptions.params, options.params);
        }

        if (options && options.responseType) {
            requestOptions.responseType = options.responseType;
        }

        return this.http.get(url, requestOptions).pipe(
            toLoadingState()
        );
    }

    post$(relativeUrl: string, body: any, options?: any) {
        const headers = this.getRequestHeaders();

        if (!relativeUrl) {
            return never();
        }

        const url = `${this.settings.webServiceUrl}${relativeUrl}`;
        return this.http.post(url, body, { headers: headers, params: options }).pipe(
            toLoadingState()
        );
    }

    private getRequestHeaders(): HttpHeaders {
        let headers = new HttpHeaders();
        const authHeader = this.authService.getAuthHeader();
        if (authHeader) {
            headers = headers.append("Authorization", authHeader);
        }

        headers = headers.append("X-SF-Service-Request", "true");

        return headers;
    }
}
