import { StatusResolver } from "../../../../../fields/resolvers/status.resolver";
import { Injectable } from "@angular/core";
import { StatusLabel } from "../../../../../fields/resolvers/base-status.resolver";
import { MEDIA_PROPERTIES, MediaHelpers } from "./media.helpers";
import { ActivatedRouteSnapshot } from "@angular/router";
import { ROUTE_PARAMS } from "../../content/constants";

@Injectable()
export class MediaStatusResolver extends StatusResolver {

    canProcess(setName: string) {
        return MediaHelpers.isLibraryOrMedia(setName);
    }

    getLabel(item: any, setName?: string, routeSnapshot?: ActivatedRouteSnapshot): StatusLabel {
        const isFolder = MEDIA_PROPERTIES.FOLDERS_COUNT in item;

        if (isFolder) {
            if (!setName)
                throw new Error("Parameter 'setName' cannot be empty.");

            setName = this.getEntitySetNameFromRoute(routeSnapshot, item);

            const childMediaLabels: MediaLabels = MediaHelpers.resolveMediaLabels(setName);
            const childMediaLabel = item.ChildrenCount === 1 ? childMediaLabels.singular : childMediaLabels.plural;
            const libraryLabel = item.FoldersCount === 1 ? "library" : "libraries";

            const label = [];
            if (item.ChildrenCount > 0) {
                label.push(`${item.ChildrenCount} ${childMediaLabel}`);
            }

            if (item.FoldersCount > 0) {
                label.push(`${item.FoldersCount} ${libraryLabel}`);
            }

            return {
                Label: label.length > 0 ? label.join(" | ") : `No ${childMediaLabels.plural}`,
                StatusName: "Hierarchical"
            };
        }

        return super.getLabel(item);
    }

    private getEntitySetNameFromRoute(routeSnapshot: ActivatedRouteSnapshot, item: any) {
        // Try to get the set name from the main route, for example if this component is hosted in the main router outlet
        let setName = routeSnapshot.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT];

        // If this component is hosted in aux route, we have to get the set name from the parent route
        if (!setName) {
            setName = routeSnapshot?.parent?.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
        }

        return setName;
    }
}

export interface MediaLabels {
    singular: string;
    plural: string;
}
