import { RestoreCommand } from "./../services/operations/commands/restore-command";
import { Component, Input, EventEmitter, Output } from "@angular/core";
import { EntityData, DataItem } from "../interfaces";
import { ActivatedRoute } from "@angular/router";
import { CommandEmitter, COMMAND_NAMES } from "./commands";
import { BulkCommand } from "../services/operations/commands/bulk-command";
import { ExecutionContext } from "../../../shared/commands/execution-context";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    templateUrl: "./undo-delete.component.html"
})
export class UndoDeleteComponent extends SfRxBase implements CommandEmitter {
    @Input() entityData: EntityData;
    @Input() restorableItemIds: string[];
    @Output() onCommand: EventEmitter<string> = new EventEmitter<string>();

    isRestoringItems: boolean = false;

    constructor(protected route: ActivatedRoute,
                private restoreCommand: RestoreCommand) {
        super();
    }

    public restoreItems() {
        this.isRestoringItems = true;

        const context: ExecutionContext = {
            data: {
                selectedItems: this.restorableItemIds.map(x => DataItem.fromEntityData({ [this.entityData.metadata.key]: x }, this.entityData)),
                entityData: this.entityData,
                bulk: true
            },
            currentRoute: this.route,
            model: null
        };

        new BulkCommand(this.restoreCommand)
            .execute(context)
            .subscribe(item => {
                this.onCommand.emit(COMMAND_NAMES.refresh);
                this.onCommand.emit(COMMAND_NAMES.close);
                this.isRestoringItems = false;
                this.restorableItemIds = [];
            });
    }

    getNotificaitonMessage(): string {
        if (this.restorableItemIds && this.restorableItemIds.length > 0) {
            if (this.restorableItemIds.length === 1) {
                return "1 item has been moved to the Recycle Bin.";
            } else {
                return `${this.restorableItemIds.length} items have been moved to the Recycle Bin.`;
            }
        }

        return "";
    }
}
