import { Injectable } from "@angular/core";
import { Observable, Subject } from "rxjs";
import { ProviderService, Provider } from "./provider-service";
import { CacheStore } from "./cache-store";

@Injectable()
export class ProviderStore extends CacheStore<string, Provider[]> {
    public providerChanged: Subject<string> = new Subject<string>();

    private _currentProvider: string;

    // TODO: This is a hack and used as a quick workaround
    public get currentProvider(): string {
        return this._currentProvider;
    }

    public set currentProvider(value: string) {
        const cache = this._currentProvider;
        this._currentProvider = value;
        if (value !== cache) {
            this.providerChanged.next(value);
        }
    }

    protected getCacheKey(key: string): string {
        return key;
    }

    protected requestItem(key: string): Observable<Provider[]> {
        return this.service.getProviders(key);
    }

    constructor(private service: ProviderService) {
        super();
    }

    public getProviders(key: string): Observable<Provider[]> {
        return this.getItemInternal(key);
    }
}
