import { DataItem } from "../interfaces";
import { Observable, BehaviorSubject } from "rxjs";
import { LoadingState } from "../../../shared/rxjs-extensions/delayEmission";

export class DynamicItemStoreState {
    // totalCount
    // TODO: remove
    itemsCount: number;

    private dynamicItemsInternal = new BehaviorSubject<ItemsState>(StateWrapper.empty());

    getValue(): ItemsState {
        const value = this.dynamicItemsInternal.getValue();
        return value;
    }

    next(value: ItemsState): void {
        const wrapper = StateWrapper.wrap(value);
        this.dynamicItemsInternal.next(wrapper);
    }

    getDynamicItems(): Observable<ItemsState> {
        const dynamicItems = this.dynamicItemsInternal.asObservable();
        return dynamicItems;
    }
}

export class StateWrapper implements ItemsState, LoadingState {

    get isLoading(): boolean {
        return this.isLoadingItems;
    }

    get hasLoadedItems(): boolean {
        return this.dataItems.length > 0;
    }

    get isLoadingItems(): boolean {
        return this.loadingItemsCount > 0;
    }

    get hasItems(): boolean {
        return this.totalCount > 0;
    }

    get leftItemsCount(): number {
        const leftItemsCount = this.totalCount - this.dataItems.length;
        return leftItemsCount;
    }

    get loadedItemsCount(): number {
        return this.dataItems.length;
    }

    getNextBatchCount(take: number): number {
        const leftItemsCount = this.leftItemsCount;

        if (leftItemsCount > take) {
            return take;
        } else {
            return leftItemsCount;
        }
    }

    getCurrentPage(take: number): number {
        return Math.ceil(this.loadedItemsCount / take);
    }

    static wrap(itemsState: ItemsState): StateWrapper {
        // we need a new instance of dataItems to force the grid to rebind
        const copy = new StateWrapper(itemsState.dataItems.slice(), itemsState.totalCount, itemsState.loadingItemsCount, itemsState.query, itemsState.skip, itemsState.take, itemsState.order, itemsState.action);
        const frozen = Object.freeze(copy);

        return frozen;
    }

    static empty(isLoadingMore: boolean = false): StateWrapper {
        return StateWrapper.wrap({
            dataItems: [],
            totalCount: 0
        });
    }

    private constructor(public dataItems: DataItem[], public totalCount: number, public loadingItemsCount: number, public query: any, public skip: number, public take: number, public order: string, public action: string) {
        this.loadingItemsCount = loadingItemsCount || 0;
        this.query = query;
        this.skip = skip || 0;
        this.take = take || 0;
        this.order = order;
        this.action = action;
    }
}

export interface ItemsState {
    dataItems: DataItem[];
    totalCount: number;
    loadingItemsCount?: number;
    query?: any;
    skip?: number;
    take?: number;
    order?: string;
    action?: string;
}
