import { Component, OnInit } from "@angular/core";
import { DialogData } from "../../src/app/modules/shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ItemListComponent } from "../../src/app/modules/content/dynamic-modules/components/bulk-operations/item-list.component";
import { RelatedDataReadonlyComponent } from "./related-data-readonly.component";

@Component({
    selector: "sf-related-data-grid",
    templateUrl: "./related-data-grid.component.html"
})
export class RelatedDataGridComponent extends RelatedDataReadonlyComponent implements OnInit {
    showCount: boolean;

    ngOnInit(): void {
        this.retrieveItems = false;
        this.settings.culture = this.context.dataItem.culture;
        super.ngOnInit();
        this.showCount = this.settings.allowMultiple;

        this.settings.allowAdd = false;
        this.settings.allowRemove = false;
    }

    onShowAllRelatedData(): void {
        const componentData: ComponentData = {
            type: ItemListComponent,
            properties: {
                dataItemsIds: (this.value as Array<any>).map(item => item.Id),
                dataItems: this.value,
                componentTitle: this.settings.title,
                componentSubtitle: this.context.dataItem.title,
                showCount: true,
                treeConfig: {
                    status: true,
                    noSelection: true,
                    description: true,
                    treeProperties: {
                        displayField: this._defaultFieldName
                    },
                    dataProperties: {
                        breadcrumbField: "Breadcrumb"
                    },
                    isHierarchical: false,
                    showBreadcrumb: this.showBreadcrumb
                }
            }
        };

        const dialogData = new DialogData(componentData, null, [], null, "-bottom");
        this.modalService.setMapping(dialogData);
        this.modalService.open(this.route);
    }
}
