import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject } from "rxjs";
import { EntityData, DataItem } from "../../../interfaces";
import { ModalWindowService, ConfirmButton, DialogData, Button, ClickResult, CancelButton, ClosingContext } from "../../../../../shared/services/modal-window.service";
import { DynamicItemStore } from "../../dynamic-item.store";
import { stringConstants } from "../../../../../../common-constants";
import { Injectable } from "@angular/core";
import { BulkComponent } from "../../../../../shared/components/bulk/bulk.component";
import { CompositeOperationsProvider } from "../operations-provider";
import { FormGroup, FormControl } from "@angular/forms";
import { FieldModel } from "../../../../../../services/field.model";
import { FieldTypes } from "../../../../../shared/fields-builder/services/fields-registry";
import { SHORT_TEXT_REGISTRY } from "../../../../../../../../fields";
import { UrlNameSettings } from "../../../../../urlName/urlName-settings";
import { TEXT_AREA_REGISTRY } from "../../../../../../../../fields/text-area";
import { SfBreadcrumbPipe, SfHtmlEscapePipe } from "@progress/sitefinity-component-framework";
import { TextAreaSettings } from "../../../../../../../../fields/text-area/text-area-settings";
import { BulkItemSelectionInfo } from "../../../components/bulk-operations/bulk-operations.component";
import { ROUTE_PARAMS, QUERY_PARAMS } from "../../../../constants";
import { createQuery } from "../../../../../../services/query";
import { LoadItemsData, UpdateItem } from "../../dynamic-item.service";
import { ActivatedRoute } from "@angular/router";
import { BulkOperationResult } from "./bulk-command";
import { ResponseError } from "../../../../../shared/services/errors/response-error";
import { map } from "rxjs/operators";
import { ShortTextSettings } from "../../../../../../../../fields/short-text/short-text-settings";
import { OPERATION_TITLES } from "../../../../../shared/components/action-menu/operation.model";
import { Properties } from "../../../../../shared/fields.constants";

const KEY = "Id";
const NAME = "Name";
const TITLE = "Title";
const SYNONYMS = "Synonyms";
const DATA_FIELD_NAMES = [KEY, TITLE, Properties.URL_NAME, SYNONYMS];
const TEXT_FIELD_LOOK: string = "inline";
const NAME_TEXT_FIELD_LOOK: string = TEXT_FIELD_LOOK + " large";
const TEXTAREA_FIELD_LOOK: string = TEXT_FIELD_LOOK + " short";

export const BULK_EDIT_TAXON_MODAL_MAPPING = "bulkEditTaxon";

@Injectable()
export class BulkEditTaxonCommand implements ExecuteOnceInBulkCommand {
    executeOnceInBulk: boolean = true;
    itemSelectionInfo: BulkItemSelectionInfo;
    items: any = [];
    isLoading: boolean;
    private result: ReplaySubject<BulkOperationResult> = new ReplaySubject<BulkOperationResult>(1);
    private route: ActivatedRoute;
    constructor(private modalWindowService: ModalWindowService,
                private dynamicItemStore: DynamicItemStore) { }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        this.route = context.currentRoute;
        const entityData: EntityData = context.data.entityData;

        const title = CompositeOperationsProvider.getOperationPluralName(context.data.entityData.metadata, context.data.action.contextParameters).toLowerCase();
        if (this.itemSelectionInfo.allItemsSelected) {
            this.getItems(entityData).subscribe((result) => {
                this.getComponentData(result.dataItems, entityData, title);
            });
        } else {
            const sortedItems = this.sortSelectedItems();
            this.getComponentData(sortedItems, entityData, title);
        }

        return this.result.asObservable();
    }

    onSaveClicked(component: BulkComponent, selectedItems: DataItem[], entityData: EntityData): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        const updateItems: UpdateItem[] = [];
        component.items.forEach(item => {
            const dirtyFields = this.getDirtyFields(item.form);
            if (dirtyFields.length > 0) {
                const data: TaxonData = {
                    Id: item.key
                };

                dirtyFields.forEach((property) => {
                    if (property === NAME) {
                        data.Title = item.form.controls[property].value;
                    } else {
                        data[property] = item.form.controls[property].value;
                    }
                });

                const updateItem: UpdateItem = {
                    dataItem: selectedItems.find(x => x.key === item.key),
                    data: data,
                    doNotRefreshItem: true
                };
                updateItems.push(updateItem);
            }
        });

        let bulkResult: BulkOperationResult;
        const subscription = this.dynamicItemStore.service.updateItemsWithBulkOperationResult(updateItems, entityData).pipe(map((result: BulkOperationResult) => {
            bulkResult = result;
        }));

        if (subscription) {
            subscription.subscribe(
                null,
                (error: ResponseError) => {
                    this.result.error("An error occured while trying to update items.");
                },
                () => {
                    clickResult.next(new ClickResult(bulkResult, true));
                });

        } else {
            clickResult.next(new ClickResult(false, true));
        }

        return clickResult;
    }

    private sortSelectedItems():  DataItem[] {
        const selected =  Array.from(this.itemSelectionInfo.selectedItems);
        if (this.itemSelectionInfo.nodesPositions.size === 0) {
            return selected.map(entry => entry[1]);
        }

        return selected.sort((x, y) => {
            const position1 = this.itemSelectionInfo.nodesPositions.get(x[0]);
            const position2 = this.itemSelectionInfo.nodesPositions.get(y[0]);
            if (position1 === undefined) {
                return -1;
            }

            if (position2 === undefined) {
                return 1;
            }

            return position1 - position2;
        }).map(entry => entry[1]);
    }

    private getDirtyFields(form: FormGroup): string[] {
        const dirtyFields = [];
        Object.keys(form.controls).forEach((property) => {
            const isDirty = form.controls[property].dirty;
            if (isDirty) {
                dirtyFields.push(property);
            }
        });

        return dirtyFields;
    }

    private getComponentData(items: any[], entityData: EntityData, title: string): void {
        const breadcrumbPipe = new SfBreadcrumbPipe(new SfHtmlEscapePipe());
        const bulkItems: any[] = [];
        items.forEach(element => {
            if (!element.isTranslated) {
                return;
            }

            const fields = this.generateFields(entityData);
            const nameField = fields.find(f => f.key === NAME);
            nameField.value = element.data.Title;
            nameField.settings.instructionalText = breadcrumbPipe.transform(element.data.Breadcrumb, false, true);

            const urlField = fields.find(f => f.key === Properties.URL_NAME);
            urlField.value = element.data.UrlName;

            const synonymsField = fields.find(f => f.key === SYNONYMS);
            synonymsField.value = element.data.Synonyms;

            const itemRow = {
                form: new FormGroup({}),
                fields: fields,
                key: element.key
            };

            itemRow.form.controls[NAME] = new FormControl(element.data.Title);
            itemRow.form.controls[Properties.URL_NAME] = new FormControl(element.data.UrlName);
            itemRow.form.controls[SYNONYMS] = new FormControl(element.data.Synonyms);

            bulkItems.push(itemRow);
        });

        const componentData = {
            type: BulkComponent,
            properties: {
                type: title,
                entityData: entityData,
                items: bulkItems,
                parentComponent: this
            }
        };

        const buttons: Button[] = [];

        if (bulkItems.length > 0) {
            buttons.push(new ConfirmButton(OPERATION_TITLES.saveChanges, (data) => this.onSaveClicked(data.component, items, entityData)));
            buttons.push(new CancelButton());
        }

        const dialogData = new DialogData(componentData, (closingContext: ClosingContext) => {
            const contextData = closingContext.data;
            if (contextData && contextData.data && (contextData.data.failedItemsIds.length > 0 || contextData.data.succeededItemsIds.length > 0)) {
                this.result.next(contextData.data);
            } else {
                this.result.next({ success: false });
            }
        }, buttons, null, "-bottom");
        this.modalWindowService.setMapping(dialogData, BULK_EDIT_TAXON_MODAL_MAPPING);
        this.modalWindowService.open(this.route, BULK_EDIT_TAXON_MODAL_MAPPING);
    }

    private generateFields(entityData: EntityData): FieldModel[] {
        const nameShortTextSettings = new ShortTextSettings(stringConstants.EMPTY_STRING, false);
        nameShortTextSettings.init(entityData.metadata);
        nameShortTextSettings.look = NAME_TEXT_FIELD_LOOK;
        nameShortTextSettings.required = true;
        const nameField = new FieldModel({
            key: NAME,
            selector: FieldTypes.shortText,
            settings: nameShortTextSettings,
            registration: SHORT_TEXT_REGISTRY
        });

        const urlNameSettings = new UrlNameSettings(stringConstants.EMPTY_STRING, false);
        urlNameSettings.init(entityData.metadata);
        urlNameSettings.title = stringConstants.EMPTY_STRING;
        urlNameSettings.required = true;
        urlNameSettings.look = TEXT_FIELD_LOOK;
        const urlField = new FieldModel({
            key: Properties.URL_NAME,
            selector: FieldTypes.shortText,
            settings: urlNameSettings,
            registration: SHORT_TEXT_REGISTRY
        });

        const synonymsTextAreaSettings = new TextAreaSettings(stringConstants.EMPTY_STRING, false);
        synonymsTextAreaSettings.init(entityData.metadata);
        synonymsTextAreaSettings.look = TEXTAREA_FIELD_LOOK;
        synonymsTextAreaSettings.required = false;
        synonymsTextAreaSettings.placeholder = "add synonyms...";
        const synonymsField = new FieldModel({
            key: SYNONYMS,
            selector: FieldTypes.textArea,
            settings: synonymsTextAreaSettings,
            registration: TEXT_AREA_REGISTRY
        });

        return [nameField, urlField, synonymsField];
    }

    private getItems(entityData: EntityData): Observable<any> {
        const sort = this.route.snapshot.queryParams[QUERY_PARAMS.SORT];
        const parentId = this.route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
        const query = createQuery()
            .where()
            .eq(entityData.metadata.parentIdProperty, parentId)
            .done();

        const loadData: LoadItemsData = {
            entityData: entityData,
            query: query,
            dataFieldNames: DATA_FIELD_NAMES,
            order: sort,
            skip: null,
            take: 0,
            action: null,
            fallbackProperties: [entityData.metadata.defaultFieldName]
        };

        return this.dynamicItemStore.getItemList(loadData);
    }
}

interface TaxonData {
    Id: string;
    Title?: string;
    UrlName?: string;
    Synonyms?: string;
}
