import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject, of } from "rxjs";
import { Button, ConfirmButton, CancelButton, DialogData, ModalWindowService, ClosingContext } from "../../../../../shared/services/modal-window.service";
import { SelectorConstants } from "../../../../../html/selector-constants";
import { OPERATION_TITLES, OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { BulkComponent } from "../../../../../shared/components/bulk/bulk.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { BulkOperationResult } from "./bulk-command";
import { FieldsGeneratorService } from "../../../../../shared/services/fields-generator.service";
import { BackendTweaksStore } from "../../backend-tweaks/backend-tweaks.store";
import { DataItem, OperationResult, EntityData } from "../../../interfaces";
import { FormGroup, FormControl } from "@angular/forms";
import { FieldModel } from "../../../../../../services/field.model";
import { Properties } from "../../../../../shared/fields.constants";
import { SettingsBase } from "../../../../../../../../fields/field-settings-base";
import { SimpleMediaComponent } from "../../../../../libraries/media/simple-media.component";
import { deepClone } from "../../../../../../utils";
import { DynamicItemService, UpdateItem } from "../../dynamic-item.service";
import { MEDIA_CONTENT_TYPES } from "../../../../../libraries/media-content.types";
import { MediaHelpers, MIME_TYPES } from "../../../../../libraries/services/media.helpers";
import { NeedsAdditionalFieldsCommand } from "../../../../../shared/commands/needs-addtional-fields-command";
import { VIEW_NAME } from "../../../../constants";
import { FieldTypes } from "../../../../../shared/fields-builder/services/fields-registry";

const EXCLUDED_FIELDS = [Properties.URL_NAME, Properties.MEDIA_FILE_URL_NAME];
const DEFAULT_FIELDS = [Properties.TITLE, Properties.DESCRIPTION, Properties.ALTERNATIVE_TEXT];
const BULK_EDIT_MEDIA = "bulkEditMedia";
const THUMBNAIL_COLUMN_NAME = "Thumbnail";

export class BulkEditMediaPropertiesCommand implements ExecuteOnceInBulkCommand, NeedsAdditionalFieldsCommand {
    executeOnceInBulk: boolean = true;
    skipNotification?: boolean = false;

    private entityData: EntityData;
    private lockedItems: { [id: string]: BulkEditMediaItemModel } = {};

    constructor(private modalWindowService: ModalWindowService,
                private fieldsGeneratorService: FieldsGeneratorService,
                private backendTweaksStore: BackendTweaksStore,
                private dynamicItemService: DynamicItemService) {
    }

    execute(context: ExecutionContext): Observable<any> {
        // sometimes the entityData can be pointing to albums/videolibraries/documentlibraries (Timeline view) but we would want
        // to bulk edit media items images/videos/documents and in order for this.entityData variable to be correct we should get
        // it from the first selected item from the collection of items that are passed to be bulk edited
        this.entityData = context.data.selectedItems[0];
        const result$ = new ReplaySubject<BulkOperationResult>(1);
        this.getMediaItems(context).subscribe(items => {
            const buttons: Button[] = [];

            if (items.length > 0) {
                buttons.push(new ConfirmButton(OPERATION_TITLES.saveChanges));
                buttons.push(new CancelButton(SelectorConstants.CANCEL));
            }

            const libraryTreeData: ComponentData = {
                type: BulkComponent,
                properties: {
                    type: this.entityData.metadata.singularName.toLowerCase(),
                    items: items
                },
                afterComponentInit: (component: BulkComponent) => {
                    component.onFieldChange.subscribe(item => {
                        this.lockItem(item);
                    });
                }
            };

            const dialogData = new DialogData(libraryTreeData, (closingContext) => this.onDone(closingContext, result$), buttons, null, "-bottom");

            this.modalWindowService.setMapping(dialogData, BULK_EDIT_MEDIA);
            this.modalWindowService.open(context.currentRoute, BULK_EDIT_MEDIA);
        });

        return result$;
    }

    getAdditionalFieldsNames(entityData: EntityData): string[] {
        const additionalFieldNames = [
            entityData.metadata.defaultFieldName,
            Properties.EXTENSION,
            Properties.MIME_TYPE,
            Properties.DESCRIPTION
        ];

        if (MediaHelpers.isImageEntity(entityData)) {
            additionalFieldNames.push(Properties.THUMBNAIL_URL);
            additionalFieldNames.push(Properties.ALTERNATIVE_TEXT);
        } else if (MediaHelpers.isVideoEntity(entityData)) {
            additionalFieldNames.push(Properties.THUMBNAIL_URL);
        }

        return additionalFieldNames;
    }

    private getMediaItems(context: ExecutionContext): Observable<BulkEditMediaItemModel[]> {
        const items$: ReplaySubject<BulkEditMediaItemModel[]> = new ReplaySubject<BulkEditMediaItemModel[]>(1);
        const items: BulkEditMediaItemModel[] = [];

        this.backendTweaksStore.initializeForm(this.entityData.metadata.setName, VIEW_NAME.INSERT, null, this.entityData.culture, this.entityData.provider).then(x => {
            const fields = this.getFields();

            const requiredFieldNames = fields.filter(x => x.settings.required && !DEFAULT_FIELDS.includes(x.key)).map(x => x.key);
            const dataFieldNames = [
                this.entityData.metadata.key,
                ...this.getAdditionalFieldsNames(this.entityData),
                ...requiredFieldNames
            ];

            const updateItemArgs: UpdateItem[] = context.data.selectedItems
                .filter((di: DataItem) => di.isTranslated)
                .map((dataItem: DataItem) => {
                    return<UpdateItem> {
                        dataItem: dataItem,
                        operation: {
                            action: OPERATION_NAMES.edit
                        },
                        doNotRefreshItem: false,
                        dataFieldNames
                    };
                });

            this.dynamicItemService.updateItemsWithBulkOperationResult(updateItemArgs, this.entityData).subscribe(x => {
                const editableDataItems = x.succeededItemsIds.map(id => {
                    return {
                        dataItem: x.items.find(i => i.key === id),
                        isEditable: true
                    };
                });

                const nonEditableDataItems = x.failedItemsIds.map(id => {
                    return {
                        dataItem: x.items.find(i => i.key === id),
                        isEditable: false
                    };
                });

                const allDataItems = editableDataItems.concat(nonEditableDataItems);
                allDataItems.forEach(x => {
                    const dataItem = x.dataItem;
                    const item: BulkEditMediaItemModel = {
                        fields: [],
                        form: new FormGroup({ ["Title"]: new FormControl(dataItem.title) }),
                        dataItem: dataItem
                    };
                    this.populateItemFieldsAndForm(item, dataItem, fields, x.isEditable);
                    items.push(item);
                });

                items$.next(items);
            });
        });

        return items$.asObservable();
    }

    private getFields(): FieldModel[] {
        const allFieldsExceptExcluded = this.fieldsGeneratorService
            .generateFieldModels(this.entityData.metadata, this.entityData.metadata.setName, this.backendTweaksStore, null)
            .filter(x => EXCLUDED_FIELDS.indexOf(x.key) < 0).map(x => {
                x.settings.showTitle = false;
                return x;
            });

        const mediaField = this.createMediaFieldModel();
        const linkFields = allFieldsExceptExcluded.filter(x => x.selector === FieldTypes.linkSelector);
        linkFields.forEach(item => item.cssClass = "-col-size-xl");

        const titleField = allFieldsExceptExcluded.find(x => x.key === Properties.TITLE);
        titleField.settings.type = "textarea";

        const altTextField = allFieldsExceptExcluded.find(x => x.key === Properties.ALTERNATIVE_TEXT);
        if (altTextField) {
            altTextField.cssClass = "-col-size-xl";
            altTextField.settings.placeholder = "add alt text...";
            altTextField.settings.type = "textarea";
            altTextField.settings.title = "Alternative text";
        }

        const descriptionField = allFieldsExceptExcluded.find(x => x.key === Properties.DESCRIPTION);
        if (MediaHelpers.isImageEntity(this.entityData)) {
            descriptionField.cssClass = "-col-size-xl";
        } else {
            descriptionField.cssClass = "-col-stretched";
            titleField.cssClass = "-col-stretched";
        }
        descriptionField.settings.placeholder = "add description...";
        descriptionField.settings.type = "textarea";

        const requiredFields = allFieldsExceptExcluded.filter(x => x.settings.required && !DEFAULT_FIELDS.includes(x.key));

        // order is important
        let fieldsResult = [];
        if (MediaHelpers.isImageEntity(this.entityData)) {
            fieldsResult = [mediaField, titleField, altTextField, descriptionField];
        } else if (MediaHelpers.isVideoEntity(this.entityData)) {
            fieldsResult  = [mediaField, titleField, descriptionField];
        } else {
            fieldsResult = [titleField, descriptionField];
        }

        return fieldsResult.concat(requiredFields);
    }

    private populateItemFieldsAndForm(mediaItem: BulkEditMediaItemModel, dataItem: DataItem, fields: FieldModel[], isEditable: boolean): void {
        fields.forEach(field => {
            const clonedField: any = deepClone(field);
            let fieldValidators = field.settings.validators;
            if (field.key === MEDIA_CONTENT_TYPES.image.single) {
                clonedField.value = {
                    isMultimedia: dataItem.metadata.isMultimedia,
                    contentType: dataItem.data.MimeType,
                    src: dataItem.data.ThumbnailUrl,
                    showErrorMessage: false
                };
            } else if (field.key === MEDIA_CONTENT_TYPES.video.single) {
                clonedField.value = {
                    isMultimedia: dataItem.metadata.isMultimedia,
                    contentType: MIME_TYPES.JPEG,
                    src: dataItem.data.ThumbnailUrl,
                    showErrorMessage: false,
                    errorIcon: "film",
                    errorIconLook: "lighter size-3xl sf-mr-zer",
                    look: dataItem.data.ThumbnailUrl ? "" : "video"
                };
            } else {
                clonedField.value = dataItem.data[field.key];
                const disabled = !isEditable;
                clonedField.settings.disabled = disabled;

                if (disabled) {
                    fieldValidators = null;
                }
            }

            clonedField.settings.key += dataItem.key;
            clonedField.settings.culture = dataItem.culture;
            clonedField.settings.look = "inline short";

            mediaItem.fields.push(clonedField);
            mediaItem.form.setControl(field.key, new FormControl(clonedField.value, fieldValidators));
        });
    }

    private createMediaFieldModel(): FieldModel {
        const key = MediaHelpers.resolveMediaLabels(this.entityData.metadata.setName).singular;

        const settings = new SettingsBase(key, false);
        settings.showTitle = false;

        if (key === MEDIA_CONTENT_TYPES.video.single) {
            settings.title = THUMBNAIL_COLUMN_NAME;
        }

        const mediaModel = new FieldModel({
            key: key,
            selector: "sf-simple-media",
            settings: settings,
            registration: {
                writeComponent: SimpleMediaComponent
            }
        });

        return mediaModel;
    }

    private onDone(context: ClosingContext, return$: ReplaySubject<BulkOperationResult>) {
        if (context.data && context.data.data) {
            const itemsForUpdate: BulkEditMediaItemUpdateModel[] = this.getItemsForUpdate();
            if (itemsForUpdate.length === 0) {
                return$.next(<OperationResult>{ success: false });
                return$.complete();
                return;
            }

            const updateItemArgs: UpdateItem[] = [];
            itemsForUpdate.forEach(item => {
                updateItemArgs.push({
                    dataItem: item.dataItem,
                    data: item.data,
                    operation: {
                        action: OPERATION_NAMES.defaultWorkflowOperation
                    }
                });
            });

            this.dynamicItemService.updateItemsWithBulkOperationResult(updateItemArgs, this.entityData).subscribe(result => {
                // filter out undefined or null values
                const succeededItemsIds = result.succeededItemsIds.filter(x => x);
                const failedItemIds = result.failedItemsIds.filter(x => x);
                return$.next({
                    success: true,
                    succeededItemsIds: succeededItemsIds,
                    failedItemsIds: failedItemIds
                });
                return$.complete();
            }, error => {
                return$.next(<OperationResult>{ success: false, error });
            });
        } else {
            this.unlockLockedItems().subscribe(() => {
                return$.next(<OperationResult>{ success: false });
                return$.complete();
            });
        }
    }

    private getItemsForUpdate(): BulkEditMediaItemUpdateModel[] {
        const itemsForUpdate: BulkEditMediaItemUpdateModel[] = [];
        Object.keys(this.lockedItems).forEach(itemKey => {
            const lockedItem = this.lockedItems[itemKey];
            const data = {};
            let shouldUpdateItem = false;
            Object.keys(lockedItem.form.controls).forEach(property => {
                if (lockedItem.form.controls[property].dirty) {
                    data[property] = lockedItem.form.controls[property].value;
                    shouldUpdateItem = true;
                }
            });

            if (shouldUpdateItem) {
                itemsForUpdate.push({
                    dataItem: lockedItem.dataItem,
                    data: data
                });
            }
        });

        return itemsForUpdate;
    }

    private lockItem(item: BulkEditMediaItemModel) {
        const dataItem = item.dataItem;
        if (this.lockedItems[dataItem.key]) {
            return;
        }

        this.lockedItems[dataItem.key] = item;

        const updateItemArgs: UpdateItem = {
            dataItem: dataItem,
            data: {}
        };
        this.dynamicItemService.updateItemWithOperationResult(updateItemArgs).subscribe({
            error: err => {
                if (this.lockedItems[dataItem.key]) {
                    delete this.lockedItems[dataItem.key];
                }

                item.fields = item.fields.map(x => {
                    x.settings.disabled = true;
                    return x;
                });
            }
        });
    }

    private unlockLockedItems(): Observable<BulkOperationResult> {
        const updateItemArgs: UpdateItem[] = [];
        Object.keys(this.lockedItems).forEach(lockedItemKey => {
            const lockedItem = this.lockedItems[lockedItemKey];
            updateItemArgs.push({
                dataItem: lockedItem.dataItem,
                operation: {
                    action: OPERATION_NAMES.unlock
                }
            });
        });

        if (updateItemArgs.length === 0) {
            return of({ success: true });
        }

        return this.dynamicItemService.updateItemsWithBulkOperationResult(updateItemArgs, this.entityData);
    }
}

class BulkEditMediaItemModel {
    form: FormGroup;
    fields: FieldModel[];
    dataItem: DataItem;
}

class BulkEditMediaItemUpdateModel {
    dataItem: DataItem;
    data: any;
}
