import { catchError } from "rxjs/operators";
import { Component, Input, EventEmitter, Output, OnChanges, SimpleChanges, OnInit } from "@angular/core";
import { Subscription } from "rxjs";
import { TreeConfig } from "../../../../../../../../fields/index";
import { FilterData, FilterValue, FilterValuesOptions, CustomFilterProperties, FilterComponent } from "./filter-interfaces";
import { FilterStore } from "./filter.store";
import { ChipsConfig } from "../../../../../../../../fields/common/chips/chips.component";
import { stringConstants } from "../../../../../../common-constants";
import { TotalCountResult } from "../../../interfaces";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const VALUES_TAKE_COUNT = 10;
export const SEARCH_PLACEHOLDER = "type to search";

@Component({
    selector: "sf-custom-filter",
    templateUrl: "./custom-filter.component.html"
})
export class CustomFilterComponent extends SfRxBase implements OnInit, OnChanges, FilterComponent {
    @Input() properties: CustomFilterProperties;
    @Input() filterParams: string[];
    @Output() filterValueSelected = new EventEmitter<FilterData>();
    @Output() valuesLoaded = new EventEmitter<string>();

    treeConfig: TreeConfig = { description: true, noSelection: true, clickable: true };
    selectedValues: FilterValue[] = [];
    dropdownValues: FilterValue[] = [];
    displayField: string = "title";
    chipsConfig: ChipsConfig = {
        showRecentLabel: false,
        showNoResultsLabel: true
    };

    private valuesSubscription: Subscription;
    private selectedValuesSubsription: Subscription;

    constructor(private filterStore: FilterStore) {
        super();
    }

    ngOnInit(): void {
        let searchPlaceholderEnd = stringConstants.ELLIPSIS;
        if (this.properties && this.properties.parameters && this.properties.parameters.contentSingularName) {
            const contentSingularName: string = this.properties.parameters.contentSingularName;
            searchPlaceholderEnd = ` ${contentSingularName.toLowerCase()}${stringConstants.ELLIPSIS}`;
        }

        this.chipsConfig.searchPlaceholder = `${SEARCH_PLACEHOLDER}${searchPlaceholderEnd}`;
    }

    ngOnChanges(changes: SimpleChanges): void {
        const filterParamsChange = changes["filterParams"];

        if (filterParamsChange) {
            let filterParams = filterParamsChange.currentValue as string[];
            if (filterParams && filterParams.length && this.properties.entityData) {
                filterParams = Array.from(new Set(filterParams));

                if (this.selectedValuesSubsription) {
                    this.selectedValuesSubsription.unsubscribe();
                }

                this.selectedValuesSubsription = this.filterStore.getFilterValues(this.properties.entityData, this.properties.filterName, { keys: filterParams }).pipe(
                    catchError(e => {
                        return []; // to emit valuesLoaded and prevent infinite loading of custom filters
                    }))
                    .subscribe((filterValues: TotalCountResult<FilterValue[]>) => {
                        this.selectedValues = this.orderFilterValues(filterParams, filterValues.dataItems);
                        this.valuesLoaded.emit(this.properties.filterName);
                    });

                this.registerSubscription(this.selectedValuesSubsription);
            } else {
                this.selectedValues = [];
            }
        }
    }

    onSelect(value: FilterValue) {
        if (this.selectedValues.findIndex(x => x.key === value.key) < 0) {
            this.selectedValues.push(value);
            this.onFilterChanged(this.properties.filterName, this.selectedValues);
        }
    }

    onSearch(search: string) {
        this.dropdownValues = [];
        const takeCount: number = VALUES_TAKE_COUNT + this.selectedValues.length;

        if (this.valuesSubscription) {
            this.valuesSubscription.unsubscribe();
        }

        const options: FilterValuesOptions = {
            take: takeCount,
            search: search ? search.trim() : search
        };

        this.valuesSubscription = this.filterStore.getFilterValues(this.properties.entityData, this.properties.filterName, options)
            .subscribe(filterResult => {
                // filter only values that are not currently selected
                this.dropdownValues = filterResult.dataItems.filter(f => this.selectedValues.findIndex(v => v.key === f.key) < 0).slice(0, VALUES_TAKE_COUNT);

                const withAvatar = filterResult.dataItems.find(x => !!x.userAvatar);
                if (withAvatar) {
                    this.treeConfig.avatar = true;
                }
            });

        this.registerSubscription(this.valuesSubscription);
    }

    onRemove(value: FilterValue) {
        const index = this.selectedValues.findIndex(x => x.key === value.key);
        if (index > -1) {
            this.selectedValues.splice(index, 1);
            this.onFilterChanged(this.properties.filterName, this.selectedValues);
        }
    }

    private onFilterChanged(filterName: string, values: FilterValue[]) {
        const filterData: FilterData = {
            name: filterName,
            keys: values.map(x => x.key)
        };

        this.filterValueSelected.emit(filterData);
    }

    private orderFilterValues(keys: string[], values: FilterValue[]): FilterValue[] {
        const orderedValues: FilterValue[] = [];
        keys.forEach(key => {
            if (key) {
                const value = values.find(v => v.key.toLowerCase() === key.toLowerCase());
                if (value) {
                    orderedValues.push(value);
                }
            }
        });

        return orderedValues;
    }
}
