import { Injectable, Inject } from "@angular/core";
import { UpdateItem, ItemWithOperationResult } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ActionButton, ButtonState } from "../components/action-menu/action-menu-model";
import { ActivatedRoute } from "@angular/router";
import { OPERATION_NAMES, CONTEXT_PARAMETERS, OperationActionType, OPERATION_PARAMETERS } from "../components/action-menu/operation.model";
import { ModalComponentSettings, ModalWindowService, ClickResult, ConfirmButton, CancelButton, ClosingContext, DialogData } from "./modal-window.service";
import { Subject, Observable, of, ReplaySubject } from "rxjs";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { Action } from "../../content/dynamic-modules/services/entity/action";
import { ActionIcon } from "../../content/dynamic-modules/services/entity/action-buttons";
import { OPERATION_VALIDATOR_MAP } from "../../content/dynamic-modules/components/dynamic-item.base";
import { ModalConfirmationComponent } from "../components/modal-confirmation/modal-confirmation.component";
import { ActionButtonsStateService } from "./action-buttons-state.service";
import { SAME_TAB_TARGET, NEW_TAB_TARGET, stringConstants } from "../../../common-constants";
import { WINDOW_TOKEN } from "../../../window.provider";
import { ModalListComponent } from "../components/modal-list/modal-list.component";
import { UrlService } from "../../../services/url.service";
import { NoPreviewComponent } from "../components/no-preview/no-preview.component";
import { OperationFailedError } from "./errors/operation-failed-error";
import { ChildrenCountStore } from "../../content/dynamic-modules/services/children-count.store";
import { ModalMainFormSize } from "./modal-main-form-size";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ChunkUploadInfoDTO } from "@progress/sitefinity-webservices-sdk/dist/src/chunk-upload/chunk-upload.sdk";
import { MediaService } from "../../libraries/services/media.service";

@Injectable()
export class ActionExecutorService {

    constructor(
        private childrenCountStore: ChildrenCountStore,
        private urlService: UrlService,
        @Inject(WINDOW_TOKEN) private window: Window,
        private dynamicItemStore: DynamicItemStore,
        private modalWindowService: ModalWindowService,
        private mediaService: MediaService
    ) {

    }

    public execute(context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        if (context.actionButton.link) {
            const openInNewTab = this.getOperationParameterValue(context, OPERATION_PARAMETERS.openLinkInNewTab) === "true";
            const skipReload = this.getOperationParameterValue(context, OPERATION_PARAMETERS.skipReload) === "true";
            this.openUrl(context.actionButton.link, openInNewTab);
            return of(<ItemWithOperationResult>{
                dataItem: context.updateItem.dataItem,
                operationData: {
                    skipReload: skipReload
                },
                operationMessage: null
            });
        }

        if (context.actionButton.context && context.actionButton.context.count) {
            this.actionWithCountHandler(context);
            return of(<ItemWithOperationResult>{
                dataItem: context.updateItem.dataItem,
                operationData: null,
                operationMessage: null
            });
        }

        if (!context.actionButton.sourceOperation.ExecuteOnServer) {
            return of(<ItemWithOperationResult>{
                dataItem: context.updateItem.dataItem,
                operationData: null,
                operationMessage: null
            });
        }

        if (context.actionButton.sourceOperation.RequiresConfirmation) {
            return this.actionConfirmForDataItemHandler(context);
        }

        return this.updateItemWithOperationResult(context);
    }

    public shouldStayAfterPublish(action: ActionButton): boolean {
        const hasContextParameters = action.sourceOperation && action.sourceOperation.ContextParameters && action.sourceOperation.ContextParameters.length;

        if (hasContextParameters) {
            const stayAfterPublish = action.sourceOperation.ContextParameters.find(x => x.Name === CONTEXT_PARAMETERS.stayAfterPublish);
            if (stayAfterPublish) {
                if (stayAfterPublish.Value.toString().toLowerCase() === "true") {
                    return true;
                } else {
                    return false;
                }
            }
        }

        return true;
    }

    public actionConfirmHandler(context: ConfirmHandler): Observable<ConfirmHandlerResult> {
        const ret = new Subject<ConfirmHandlerResult>();

        const settings: ModalComponentSettings = this.getSettings(context, ret);
        this.modalWindowService.openModalConfirmation(context.route.parent, settings, null, undefined, context.window);

        return ret.asObservable();
    }

    private getOperationParameterValue(context: ExecuteServerAction, parameterName: string): string {
        if (context.actionButton.sourceOperation && context.actionButton.sourceOperation.ContextParameters) {
            const parameter = context.actionButton.sourceOperation.ContextParameters.find(x => x.Name === parameterName);
            if (parameter) {
                return parameter.Value;
            }

            return null;
        }
    }

    private actionConfirmForDataItemHandler(context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        if (context.actionButtonStateService) {
            context.actionButtonStateService.updateActionButtonsState(null, ButtonState.Default);
        }

        if (context.updateItem.data) {
            let contextParams = context.actionButton.contextParameters;
            contextParams = contextParams || {};
            contextParams[CONTEXT_PARAMETERS.currentTitle] = context.updateItem.data[context.updateItem.dataItem.metadata.defaultFieldName];
        }

        const modalRet = new Subject<ConfirmHandlerResult>();
        const settings: ModalComponentSettings = this.getSettings(context, modalRet);
        this.modalWindowService.openModalConfirmation(context.route.parent, settings, context.updateItem.dataItem);

        const ret = new Subject<ItemWithOperationResult>();
        modalRet.subscribe(x => {
            const castedContext = x.confirmContext as ExecuteServerAction;
            if (castedContext.actionParameters) {
                this.updateItemWithOperationResult(castedContext).subscribe((innerResult) => {
                    ret.next(innerResult);
                }, (error) => {
                    ret.error(error);
                });
            } else {
                ret.next(null);
            }
        });

        return ret.asObservable();
    }

    private updateItemWithOperationResult(context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        const updateItem = context.updateItem;
        const actionButton = context.actionButton;

        const data: any = {
            dataItem: updateItem.dataItem,
            operation: { action: actionButton.name, actionParameters: context.actionParameters || {} },
            skipUpdate: !!context.updateItem.skipUpdate
        };

        if (actionButton.sourceOperation.RequiresItemUpdate) {
            data.fallbackProperties = updateItem.fallbackProperties;
            data.skipUpdate = context.updateItem.skipUpdate || false;
        }

        if (actionButton.sourceOperation.PerformsDelete) {
            data.skipUpdate = true;
        }

        if (context.actionButtonStateService) {
            context.actionButtonStateService.updateActionButtonsState({ name: actionButton.name, state: ButtonState.Loading }, ButtonState.Disabled);
        }

        if (typeof updateItem.doNotRefreshItem === "undefined") {
            updateItem.doNotRefreshItem = context.actionButton.sourceOperation.PerformsDelete;
        }

        let result: Observable<ItemWithOperationResult> = new ReplaySubject<ItemWithOperationResult>(1);

        if (updateItem.data?.SfMediaData?.file) {
            this.mediaService.getChunkUploadInfo(updateItem.dataItem, updateItem.dataItem.data.ParentId, (x: ChunkUploadInfoDTO) => {
                if (x.ProviderSupportsChunkUpload) {

                    const fieldValues = this.dynamicItemStore.service.getFieldValues(updateItem.dataItem.metadata, updateItem.data)
                    const primitiveValues = fieldValues.primitives || updateItem.data

                    this.mediaService.uploadChunkedWithOperationResult(result as Subject<ItemWithOperationResult>, updateItem.dataItem, x, fieldValues.blob, primitiveValues, fieldValues.relational, actionButton.sourceOperation);

                    this.handleSaveItemSubscription(result, context, actionButton);
                } else {
                    this.saveItemWithOperationResultInBatchRequest(updateItem, actionButton, data)
                        .subscribe(x => {
                            (result as Subject<ItemWithOperationResult>).next(x);
                            this.handleSaveItemResult(x, context, actionButton);
                        }, err => this.handleSaveItemResultError(err, context, actionButton));
                }
            })
        } else {
            result = this.saveItemWithOperationResultInBatchRequest(updateItem, actionButton, data);
            this.handleSaveItemSubscription(result, context, actionButton);
        }

        return result;
    }

    private saveItemWithOperationResultInBatchRequest(updateItem: UpdateItem, actionButton: ActionButton, data: any): Observable<ItemWithOperationResult> {
        return this.dynamicItemStore.saveItemWithOperationResult(
            updateItem.dataItem,
            updateItem.data,
            new Action(actionButton.name, data.operation),
            updateItem.fallbackProperties,
            updateItem.dataFieldNames,
            undefined,
            data.skipUpdate,
            updateItem.doNotRefreshItem,
            updateItem.additionalQueryParams
        );
    }

    private handleSaveItemSubscription(result: Observable<ItemWithOperationResult>, context: ExecuteServerAction, actionButton: ActionButton) {
        result.subscribe((resultData) => {
            this.handleSaveItemResult(resultData, context, actionButton);
        }, (err) => {
            this.handleSaveItemResultError(err, context, actionButton);
        });
    }

    private handleSaveItemResult(itemWithOperationResult: ItemWithOperationResult, context: ExecuteServerAction, actionButton: ActionButton) {
        if (actionButton.sourceOperation.PerformsDelete) {
            this.childrenCountStore.invalidateCachedChidrenCountByChildItem(itemWithOperationResult.dataItem);
        }

        if (actionButton.sourceOperation.HasLinkResult) {
            if (!context.window) {
                context.window = this.window.open(stringConstants.EMPTY_STRING, SAME_TAB_TARGET);
            }
            const operationResult = itemWithOperationResult.operationData;
            const location = context.window.location;
            if (operationResult.Success && operationResult.Link) {
                location.href = operationResult.Link;
            }
        }

        if (context.actionButtonStateService) {
            context.actionButtonStateService.updateActionButtonsState({ name: actionButton.name, state: ButtonState.Checked }, ButtonState.Disabled);
        }

        const skipReload = this.getOperationParameterValue(context, OPERATION_PARAMETERS.skipReload) === "true";
        if (itemWithOperationResult.operationData) {
            itemWithOperationResult.operationData.skipReload = skipReload;
        } else {
            itemWithOperationResult.operationData = {
                skipReload
            };
        }
    }

    private handleSaveItemResultError(err: any, context: ExecuteServerAction, actionButton: ActionButton) {
        if (context.actionButtonStateService) {
            context.actionButtonStateService.updateActionButtonsState(null, ButtonState.Default);
        }

        if (err instanceof OperationFailedError && actionButton.sourceOperation.HasLinkResult) {
            if (!err.result.success) {
                const noPreviewUrl = NoPreviewComponent.getPreviewUrl(this.urlService, context.updateItem.dataItem);
                context.window.location.href = noPreviewUrl;
            }
        }
    }

    private getDialogEnteredParameters(context: ClosingContext) {
        if (context.data && context.data.data && context.component) {
            return context.data.data;
        }
    }

    private getSettings(context: ConfirmHandler, ret: Subject<ConfirmHandlerResult>): ModalComponentSettings {
        const actionButton = context.actionButton;
        const settings: ModalComponentSettings = {
            title: actionButton.title,
            descriptionAllowHtml: true,
            detailedTitle: actionButton.detailedTitle,
            icon: ActionIcon[actionButton.name] || "info",
            parameters: actionButton.parameters,
            contextParameters: actionButton.contextParameters,
            description: actionButton.sourceOperation.Description,
            warning: actionButton.sourceOperation.Warning,
            formValidators: OPERATION_VALIDATOR_MAP[actionButton.name],
            action: actionButton.name,
            buttons: this.getButtons(actionButton),
            doneCallback: this.getDoneCallback(context, ret)
        };

        if (context.actionButton.name === OPERATION_NAMES.stopSyncing ||
            context.actionButton.name === OPERATION_NAMES.delete) {
            settings.hideItemTitle = true;
        }

        if (context.actionButton.name === OPERATION_NAMES.shareTaxonomyWithSite) {
            settings.hideItemTitle = true;
            settings.innerFormLook = "medium sf-pt-zero sf-pb-zero sf-txt-align-left sf-centered-box";
        }

        if (context.actionButton.name === OPERATION_NAMES.createPersonalizedVersion) {
            settings.hideItemTitle = true;
            settings.title = "Add personalized page";
        }

        if (context.actionButton.name.startsWith(OPERATION_NAMES.deletePersonalizedVersion)) {
            settings.hideItemTitle = true;
            settings.icon = "trash";
            settings.mainFormSize = ModalMainFormSize.Small;
        }

        if (context.actionButton.name === OPERATION_NAMES.unpublish && this.isHomePage(context.actionButton)) {
            settings.hideItemTitle = true;
        }

        return settings;
    }

    private getButtons(actionButton: ActionButton) {
        if (actionButton.sourceOperation.Actions && actionButton.sourceOperation.Actions.length > 0) {
            const mapped = actionButton.sourceOperation.Actions.map(x => {
                let css: string = "large";
                if (x.Type === OperationActionType.Success) {
                    css = "action large";
                } else if (x.Type === OperationActionType.Error) {
                    css = "delete large";
                }

                const clickResultHandler = (data) => {
                    let isSuccessFul = true;
                    const component: ModalConfirmationComponent = data.component;

                    let actionParameters = null;
                    if (component instanceof ModalConfirmationComponent && component.parameters && component.editableFields) {
                        isSuccessFul = component.editableFields.valid();
                        if (isSuccessFul) {
                            if (actionButton.sourceOperation.Name === OPERATION_NAMES.schedule) {
                                const hasDirtyFields = component.editableFields.getFields() !== null;
                                actionParameters = hasDirtyFields ? component.editableFields.getFields(false) : null;
                            } else if (actionButton.sourceOperation.Name === OPERATION_NAMES.createPersonalizedVersion) {
                                actionParameters = component.editableFields.getFields(false);
                            } else {
                                actionParameters = component.editableFields.getFields();
                            }
                        }
                    }

                    if (actionButton.sourceOperation.Name !== OPERATION_NAMES.schedule) {
                        if (!actionParameters)
                            actionParameters = {};

                        actionParameters.actionName = x.Name;
                    }

                    const clickHandler = new ClickResult(actionParameters, isSuccessFul);

                    return clickHandler;
                };

                return new ConfirmButton(x.Title, clickResultHandler, css);
            });

            mapped.push(new CancelButton());
            return mapped;
        } else {
            return [new CancelButton("Close")];
        }
    }

    private getDoneCallback(actionContext: ConfirmHandler, ret: Subject<ConfirmHandlerResult>): DoneCallback {
        return (context: ClosingContext) => {
            const fields = this.getDialogEnteredParameters(context);
            actionContext.actionParameters = fields;
            ret.next({ dialogResult: context, confirmContext: actionContext });
        };
    }

    private openUrl(url: string, openInNewTab: boolean = false) {
        let target = SAME_TAB_TARGET;
        if (openInNewTab) {
            target = NEW_TAB_TARGET;
        }

        try {
            this.window.open(url, target);
        } catch (ex) {
            // Workaround for an issue in IE and Edge.
            // If the item has dirty fields and you try to
            // execute an operation that navigates (e.g. 'Send for translation' or 'Revision history')
            // there is an alert that prompts you whether to stay on the page or continue with the navigation
            // If you select 'Stay on this page' there is this error thrown in the console.
            if (ex.message !== "Unspecified error.") {
                throw ex;
            }
        }
    }

    private actionWithCountHandler(context: ExecuteServerAction): void {
        const count = context.actionButton.context ? context.actionButton.context.count : null;
        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                contentLook: "medium",
                actionTitle: context.actionButton.title,
                action: context.actionButton.name,
                count,
                dataItem: context.updateItem.dataItem,
                showDataItemTitle: true
            }
        };

        const dialogData = new DialogData(componentData);

        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.open(context.route);
    }

    private isHomePage(actionButton: ActionButton): boolean {
        const param = actionButton.contextParameters?.find(x => x.Name === "isHomePage");

        if (param && param.Value?.toLowerCase() === "true") {
            return true;
        }

        return false;
    }
}

export interface ExecuteServerAction extends ConfirmHandler {
    updateItem: UpdateItem,
}

interface ConfirmHandler {
    route: ActivatedRoute,
    actionButton: ActionButton,
    actionButtonStateService: ActionButtonsStateService,
    actionParameters?: any;

    window?: Window;
}

interface ConfirmHandlerResult {
    dialogResult: ClosingContext,
    confirmContext: ConfirmHandler
}
