import { Command } from "../../../../../shared/commands/command";
import { from, Observable } from "rxjs";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Router } from "@angular/router";
import { Injectable } from "@angular/core";

@Injectable()
export class ParentNavigateCommand implements Command {
    constructor(private router: Router) {

    }

    execute(context: ExecutionContext): Observable<any> {
        const navigate = this.router.navigate(context.data.route);

        return from(navigate);
    }

}
