import { Inject, Injectable } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { Command } from "../../shared/commands/command";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { Observable, ReplaySubject } from "rxjs";
import { ModalWindowService, Button, ConfirmButton, CancelButton, DialogData, ClosingContext } from "../../shared/services/modal-window.service";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { PageSelectorComponent } from "../components/page-selecotr-component/page-selector.component";
import { BUTTON_POSSITIONS, NOTIFICATION_DURATION_INFINITE, QUERY_PARAMS } from "../../content/constants";
import { GridReloadService } from "../../content/dynamic-modules/services/grid-reload.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { NOTIFICATION_LOOKS } from "../../shared/services/notification/notification-data";

@Injectable()
export class SaveAsHomePageCommand implements Command {
    constructor(
        private modalWindowService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        private reloadService: GridReloadService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService
    ) {
    }

    execute(context: ExecutionContext): Observable<boolean> {
        const result = new ReplaySubject<boolean>(1);
        const componentData: ComponentData = {
            type: PageSelectorComponent,
            properties: {
                culture: this.getCulture(context.currentRoute),
                formattedTypeName: "homepage",
                shouldSelectHomePage: true
            }
        };

        const buttons: Button[] = [
            new ConfirmButton("Use selected"),
            new CancelButton()
        ];

        const dialogData = new DialogData(componentData, (context) => this.onDone(context), buttons, null, BUTTON_POSSITIONS.BOTTOM);
        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.open(context.currentRoute);

        return result.asObservable();
    }

    private onDone(context: ClosingContext) {
        if (context.data && context.data.data) {
            const pageSelectorComponent = context.component as PageSelectorComponent;
            const selectedItem = pageSelectorComponent.selected[0];
            if (selectedItem) {
                this.dynamicItemStore.executeEntityOperation(pageSelectorComponent.entityData, "Default.SetHomePage()", { pageId: `${selectedItem.Id}`})
                    .subscribe(() => {
                        this.reloadService.requestReload();
                    }, err => {
                        this.notificationService.publishBasicNotification({
                            message: err.message,
                            look: NOTIFICATION_LOOKS.ERROR,
                            filterParam: pageSelectorComponent.entityData.metadata.typeFullName,
                            duration: NOTIFICATION_DURATION_INFINITE
                        });
                    });
            }
        }
    }

    private getCulture(route: ActivatedRoute): string {
        return route.snapshot.queryParams[QUERY_PARAMS.CULTURE] || route.snapshot.data.siteDataStore.DefaultContentCulture;
    }
}
