import { map, switchMap } from "rxjs/operators";
import { DataItem } from "./../../interfaces";
import { Component, OnInit, ViewChild } from "@angular/core";
import { EntityData } from "../../interfaces";
import { ROUTE_PARAMS, FILTER_PARAMS } from "../../../constants";
import { ActivatedRoute } from "@angular/router";
import { TreeWrapperComponent } from "../../../../../../../fields";
import { TreeConfig } from "../../../../../../../fields";
import { ScrollService } from "../../../../../services/scroll.service";
import { DynamicItemService, LoadItemsResponse, LoadItemsData } from "../../services/dynamic-item.service";
import { createQuery } from "../../../../../services/query";
import { Subscription, Subject, Observable } from "rxjs";
import { cloneObject } from "../../../../../utils";
import { toLoadingState, delayEmission } from "../../../../shared/rxjs-extensions";
import { CompositeGridExtender } from "../../../../shared/services/grid/composite-grid-extender";
import { TreeNode } from "@circlon/angular-tree-component";
import { LIST_ITEM_FULL_NAME } from "../../../../shared/services/metadata/meta-data-constants";
import taxonomyConstants from "../../../../taxonomy/taxonomy.constants";
import { ServiceInfo } from "../../../../../../../fields/selector/selector.component";
import { Properties } from "../../../../shared/fields.constants";
import { ActionItem } from "../../../../../../../fields/types/types";
import { COMMAND_NAMES } from "../commands";
import { DEFAULT_ORDINAL_EXPRESSION } from "../../../../shared/services/sort.service";
import { MediaService } from "../../../../libraries/services/media.service";
import { MediaHelpers } from "../../../../libraries/services/media.helpers";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ExternalAppConfigService } from "../../../../../app-config/external-app-config.service";

const BLUR_EFFECT_TIMEOUT = 600;

@Component({
    templateUrl: "./reorder.component.html"
})
export class ReorderComponent extends SfRxBase implements OnInit {
    @ViewChild("tree", { static: false }) tree: TreeWrapperComponent;
    treeConfig: TreeConfig = {
        drag: true,
        status: true,
        statusText: true,
        noSelection: true,
        multiSelection: false,
        hideExtensions: true
    };
    entityData: EntityData;
    itemsSubscription: Subscription;
    parentItem: DataItem;
    parentTitle: string;
    scrollService: ScrollService;
    treeItems: any[] = [];
    totalItemsCount: number;
    isInitialLoading = true;
    displayField: string;
    reorderActions: ReorderAction[] = [];
    headingText: string;
    dirty = false;
    private loadItems$: Subject<Observable<LoadItemsResponse>> = new Subject<Observable<LoadItemsResponse>>();

    constructor(private _scrollService: ScrollService,
                private dynamicItemService: DynamicItemService,
                private gridExtender: CompositeGridExtender,
                protected route: ActivatedRoute,
                private mediaService: MediaService,
                private externalAppConfigService: ExternalAppConfigService) {
        super();
        this.scrollService = this._scrollService;
    }

    get parentId(): string {
        return this.route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
    }

    ngOnInit() {
        this.displayField = this.entityData.metadata.defaultFieldName;
        this.initPluralName();

        if (this.parentItem != null) {
            this.initParentTitle();
        }

        const loadSubscription = this.loadItems$.pipe(switchMap(o => o)).subscribe((state) => {
            if (state) {
                const newItems = state.dataItems.map(item => {
                    const result = cloneObject(item.data);
                    result.isTranslated = item.isTranslated;
                    if (this.isMedia() && result.Extension) {
                        result.icon = MediaHelpers.getDocumentThumbnailIcon(result.Extension);
                        result.iconLook = `size-3xl ${result.isTranslated === false ? "lighter" : "light"}`;
                    }

                    return result;
                });

                this.treeItems = this.treeItems.concat(newItems);
                this.totalItemsCount = state.totalCount;

                this.loadAdditionalItems();
                this.isInitialLoading = false;
            }
        });

        this.registerSubscription(loadSubscription);

        this.loadItems(0);
    }

    onMoveNode(event) {
        this.dirty = true;
        let position: ReorderPosition;
        let targetId: string;

        if (event.from.parent.children.length === 0) {
            event.from.parent.HasChildren = false;
        }

        if (event.to.parent.children.length === 1) {
            position = ReorderPosition.Under;
            targetId = event.to.parent[this.entityData.metadata.key];
        } else {
            let targetIndex;

            if (event.to.index === 0) {
                position = ReorderPosition.Before;
                targetIndex = 1;
            } else {
                position = ReorderPosition.After;
                targetIndex = event.to.index - 1;
            }

            targetId = event.to.parent.children[targetIndex][this.entityData.metadata.key];
        }

        const movingToNode = event.treeModel?.getNodeById(event.to.parent.Id);
        const movingFromNode = event.treeModel?.getNodeById(event.from.parent.Id);
        //// When moving items from the tree we need to update the totalitems in order to know and fetch them properly.
        //// If we do not update that we can endup in situation where we can miss to fetch some of the items.
        if (movingToNode !== movingFromNode) {
            if (!movingFromNode) {
                this.totalItemsCount--;
            } else if (!movingToNode) {
                this.totalItemsCount++;
            }
        }

        const action: ReorderAction = {
            Id: event.node[this.entityData.metadata.key],
            Position: position,
            TargetId: targetId
        };

        this.reorderActions.push(action);
    }

    treeNodeClicked(event) {
        if (event.data.isLink) {
            this.loadMoreChildren(event);
        }
    }

    checkShouldLoadMore(): boolean {
        return this.treeItems.length > 0 && this.treeItems.length < this.totalItemsCount;
    }

    requestMoreItems() {
        if (!this.checkShouldLoadMore() || this.tree.isLoadingMore) {
            return;
        }

        this.tree.isLoadingMore = true;
        this.loadItems(this.treeItems.length);
    }

    protected loadMoreChildren(item: any) {
        this.loadChildNodes(item.parent, false);
    }

    private isMedia(): boolean {
        return MediaHelpers.isLibraryOrMedia(this.entityData.metadata.setName);
    }

    private initPluralName() {
        const includeChildSet = this.entityData.metadata.typeFullName !== LIST_ITEM_FULL_NAME &&
            this.entityData.metadata.typeFullName !== taxonomyConstants.HIERARCHICAL_TAXON_FULL_NAME;

        this.gridExtender.getPluralItemName({
            entityData: this.entityData,
            parentItem: this.parentItem,
            includeChildSet: includeChildSet,
            route: this.route
        }).subscribe((name: { primary: string, secondary: string }) => {
            if (this.isMedia()) {
                this.headingText = `Reorder ${name.primary.toLowerCase()} in library`;
            } else {
                this.headingText = `Reorder ${name.primary.toLowerCase()}`;
            }
        });
    }

    private initParentTitle() {
        if (this.entityData.metadata.typeFullName !== taxonomyConstants.HIERARCHICAL_TAXON_FULL_NAME) {
            this.gridExtender.getTitle({
                entityData: this.entityData,
                parentItem: this.parentItem,
                includeChildSet: false
            }).subscribe((title: string) => {
                this.parentTitle = title;
            });
        }
    }

    private loadAdditionalItems() {
        if (this.isInitialLoading) {
            this.requestMoreItems();
        }

        if (this.tree) {
            this.tree.isLoadingMore = false;
        }
    }

    private loadItems(skip: number) {

        this.treeConfig.isHierarchical = this.gridExtender.isHierarchical(this.route.parent.firstChild);
        let loadItems: Observable<LoadItemsResponse>;
        if (this.treeConfig.isHierarchical) {
            this.treeConfig.treeProperties = {
                hasChildrenField: "HasChildren"
            };
            this.treeConfig.drop = () => true;
            this.treeConfig.treeProperties["getChildren"] = (node: TreeNode) => {
                return this.loadChildNodes(node);
            };

            this.gridExtender.getExpandedNodeIds({ entityData: this.entityData }).subscribe((expandedNodeIds: string[]) => {
                this.treeConfig.expandedNodeIds = expandedNodeIds;
                const dataFieldNames = [this.entityData.metadata.key, this.entityData.metadata.defaultFieldName];
                if (this.entityData.metadata.properties.hasOwnProperty(Properties.AvailableLanguages)) {
                    dataFieldNames.push(Properties.AvailableLanguages);
                }

                const loadItemsArg: LoadItemsData = this.gridExtender.getItemsData(this.route.parent.firstChild, dataFieldNames, { expandedNodeIds: expandedNodeIds });
                loadItemsArg.order = DEFAULT_ORDINAL_EXPRESSION;
                loadItemsArg.skip = skip;
                loadItemsArg.take = this.externalAppConfigService.externalConfig.contentItemsPerPage;

                loadItems = this.dynamicItemService.getItemList(loadItemsArg)
                    .pipe(
                        toLoadingState<LoadItemsResponse>(),
                        delayEmission(BLUR_EFFECT_TIMEOUT),
                        map(x => x.content)
                    );
            });
        } else if (this.isMedia()) {
            loadItems = this.mediaService.getMediaForLibrary(DataItem.fromEntityData(null, this.entityData), this.parentItem.data.Id, skip, null, null, null, { [FILTER_PARAMS.SORT]: DEFAULT_ORDINAL_EXPRESSION });
        } else {
            const query = createQuery().where().and().eq(this.entityData.metadata.parentIdProperty, this.parentId).done().done();
            loadItems = this.dynamicItemService.getItemList({
                entityData: this.entityData,
                skip: skip,
                take: this.externalAppConfigService.externalConfig.contentItemsPerPage,
                order: DEFAULT_ORDINAL_EXPRESSION,
                query: query,
                fallbackProperties: [this.displayField]
            }).pipe(
                toLoadingState<LoadItemsResponse>(),
                delayEmission(BLUR_EFFECT_TIMEOUT),
                map(x => x.content)
            );
        }

        if (loadItems) {
            this.loadItems$.next(loadItems);
        }
    }

    private loadChildNodes(node: any, isLoadingForFirstTime: boolean = true): Promise<any> {
        if (Array.isArray(node.data.children)) {
            this.removeLoadMoreLink(node.data.children);
        }
        const skip = node.data.children ? node.data.children.length : 0;
        const serviceInfo: ServiceInfo = { parentId: node.data.Id, skip };
        return this.gridExtender.getChildren(this.entityData, this.route.snapshot.parent.firstChild.params.parentId, serviceInfo)
            .then((result: any) => {
                return this.loadMoreChildNodes(result, node, isLoadingForFirstTime);
            });
    }

    private loadMoreChildNodes(items: LoadItemsResponse, node: any, isLoadingForFirstTime): any[] {
        let nodes = [];
        if (Array.isArray(node.data.children)) {
            nodes = node.data.children;
        }

        nodes = nodes.concat(items.dataItems.map(x => Object.assign({}, x.data)));
        node.data.hasChildren = nodes.length !== 0;
        node.data.children = nodes;

        this.addLoadMoreLink(node.data.children, node.data.Id, items.totalCount, items.entityData);
        if (!isLoadingForFirstTime) {
            this.tree.updateTreeModel();
        }

        return nodes;
    }

    private addLoadMoreLink(array: any[], key: string, totalCount: number, entityData: EntityData) {
        if (array.length > 0 && totalCount > array.length) {

            const loadMoreModel: ActionItem = { Title: "Load more", Id: `${key}_loadMore`, action: COMMAND_NAMES.loadMoreChildren, isSelectionDisabled: true, isLink: true, icon: "repeat", iconLook: "size-xs color-inherit" };
            array.push(loadMoreModel);
        }
    }

    private removeLoadMoreLink(array: any[]) {
        const loadMoreItemsIndex = array.findIndex(item => {
            if (item) {
                const i = item as ActionItem;
                return i && !!i.action;
            }
        });

        if (loadMoreItemsIndex >= 0) {
            array.splice(loadMoreItemsIndex, 1);
        }
    }
}

interface ReorderAction {
    Id: string;
    Position: ReorderPosition;
    TargetId: string;
}

enum ReorderPosition {
    Before = "0",
    After = "1",
    Under = "2"
}
