import { DynamicItemStore } from "./../../dynamic-item.store";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable } from "rxjs";
import { OperationResult } from "../../../interfaces";

export class OperationCommand {
    constructor(protected dynamicItemStore: DynamicItemStore) {
    }

    execute(context: ExecutionContext): Observable<OperationResult> {
        const data = context.data;
        const dataItem = data.dataItem;
        return this.dynamicItemStore.executeOperation(dataItem, data.action.name);
    }
}
