import { Directive, Input, OnInit } from "@angular/core";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const NOT_FOUND_MESSAGE: string = "Not found";
export const NO_PRVIEW_MESSAGE: string = "No preview available";

@Directive()
export class MediaBaseComponent extends SfRxBase implements OnInit {
    @Input() src: any;
    @Input() look: string;
    @Input() errorIcon: string = "ban";
    @Input() errorIconLook: string = "size-3xl light sf-mt-3xs";
    @Input() alt: string;
    hasError: boolean = false;
    doesNotSupportPreview: boolean = false;
    errorText: string;
    cssClass: string = "";

    ngOnInit(): void {
        if (this.doesNotSupportPreview) {
            this.hasError = true;
            this.errorText = NO_PRVIEW_MESSAGE;
        }
    }

    onError() {
        this.hasError = true;
        this.errorText = NOT_FOUND_MESSAGE;
    }

    protected generateCssClassList() {
        const cls = "";

        return cls;
    }
}
