import { Component, ViewChild, OnInit, AfterViewInit, OnDestroy } from "@angular/core";
import { FieldTypes } from "../../fields-builder/services/fields-registry";
import { FieldBase } from "../../../../../../fields/field-base";
import { FieldSectionModel, FieldSectionSettings } from "../../../../services/fieldSection.model";
import { CompositeFieldsProvider } from "../../fields-builder/providers/fields-provider";
import { FieldModel } from "../../../../services/field.model";
import { createFieldModel } from "../../fields.constants";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { CHOICE_DROPDOWN_REGISTRY } from "../../../../../../fields/choice";
import { EditableFieldsComponent } from "../../fields-builder/components/editable-fields/editable-fields.component";
import { CountryProvider } from "./country.provider";
import { AddressSettings } from "./address.settings";
import { AddressFieldMode, ADDRESS_FIELDS } from "./address.constants";
import { StatusType } from "../../../../../../fields/field-status";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { Country } from ".";
import { stringConstants } from "../../../../common-constants";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-address",
    templateUrl: "./address.component.html"
})
export class AddressComponent extends FieldBase implements OnInit, AfterViewInit, OnDestroy {
    @ViewChild("editableFields", { static: true }) editableFields: EditableFieldsComponent;
    fieldSections: FieldSectionModel[];

    private countries: Country[];

    constructor(
        private fieldsProvider: CompositeFieldsProvider,
        private countryProvider: CountryProvider
    ) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.registerSubscription(this.countryProvider.getCountries().subscribe(countries => {
            countries.unshift({ name: "- Select country -", isoCode: null, hasStates: false, states: null });
            this.countries = countries;
            const fieldSection = this.initFieldSection();
            this.fieldSections = [fieldSection];
        }));
    }

    ngAfterViewInit() {
        this.registerSubscription(this.editableFields.fieldChange.subscribe(change => {
            // Empty string which is the default empty value of the ShortText is not valid for address field.
            if (change.value === stringConstants.EMPTY_STRING) {
                change.value = null;
            }

            this.updateFieldSettings(change);

            const newValue = Object.assign({}, this.value);
            newValue[change.key] = change.value;

            // Hack in order for the status to be always done and error only after validate method
            this.emitStatus({ type: StatusType.Done });

            this.writeValue(newValue);
        }));
    }

    isAllFieldsValid(value): boolean {
        let isValid = true;
        if (this.settings.required) {
            if (value) {
                this.fieldSections[0].fields.forEach(field => {
                    if (field.settings.isVisible && !value[field.key]) {
                        isValid = false;
                    }
                });
            } else {
                isValid = false;
            }
        }

        return isValid;
    }

    validate() {
        this.editableFields.enableRequiredErrorCheck();
        this.editableFields.triggerErrors();

        return this.updateStatus(this.value);
    }

    private updateFieldSettings(data) {
        if (data.key !== ADDRESS_FIELDS.COUNTRY_CODE) {
            return;
        }

        const [addressFieldSection] = this.fieldSections;
        const addressStateField = addressFieldSection.fields.find(f => f.key === ADDRESS_FIELDS.STATE_CODE);

        const choiceSettings = addressStateField.settings as ChoiceSettings;
        const selectedCountryStatesDropOptions = this.getCountryStatesDropOptions(data.value);

        if (selectedCountryStatesDropOptions.length) {
            choiceSettings.choices = selectedCountryStatesDropOptions;
            choiceSettings.isVisible = true;
        } else {
            choiceSettings.choices = [];
            choiceSettings.isVisible = false;
        }

        if (this.value) {
            this.value[addressStateField.key] = null;
        }
    }

    private initFieldSection(): FieldSectionModel {
        const fields: FieldModel[] = this.getFields();
        const sectionOptions: FieldSectionSettings = {
            isMain: true,
            isExpanded: false,
            insertHorizontalRule: false
        };

        const section = new FieldSectionModel(sectionOptions);
        section.fields = fields;

        return section;
    }

    private getFields(): FieldModel[] {
        const fields: FieldModel[] = new Array<FieldModel>();
        const addressSettings = this.settings as AddressSettings;

        if (addressSettings.mapMode === AddressFieldMode.FormOnly || addressSettings.mapMode === AddressFieldMode.Hybrid) {
            const countriesDropDownValues = this.countries.map(coutry =>
                ({ Name: coutry.name, Value: coutry.isoCode }));

            fields.push(this.createDropDownField(ADDRESS_FIELDS.COUNTRY, ADDRESS_FIELDS.COUNTRY_CODE, countriesDropDownValues));

            const selectedCountryCode = this.getFieldValue(ADDRESS_FIELDS.COUNTRY_CODE);
            const selectedCountryStatesDropOptions = this.getCountryStatesDropOptions(selectedCountryCode);

            const stateDropdownField = this.createDropDownField(ADDRESS_FIELDS.STATE, ADDRESS_FIELDS.STATE_CODE, selectedCountryStatesDropOptions);
            stateDropdownField.settings.isVisible = selectedCountryStatesDropOptions.length > 0;

            fields.push(stateDropdownField);

            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.CITY, this.getFieldValue(ADDRESS_FIELDS.CITY)));
            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.ZIP, this.getFieldValue(ADDRESS_FIELDS.ZIP)));
            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.STREET, this.getFieldValue(ADDRESS_FIELDS.STREET)));
        }

        if (addressSettings.mapMode === AddressFieldMode.MapOnly || addressSettings.mapMode === AddressFieldMode.Hybrid) {
            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.LATITUDE, this.getFieldValue(ADDRESS_FIELDS.LATITUDE)));
            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.LONGITUDE, this.getFieldValue(ADDRESS_FIELDS.LONGITUDE)));
            fields.push(this.createField(FieldTypes.shortText, ADDRESS_FIELDS.MAP_ZOOM_LEVEL, this.getFieldValue(ADDRESS_FIELDS.MAP_ZOOM_LEVEL)));
        }

        return fields;
    }

    private updateStatus(value): boolean {
        if (this.isAllFieldsValid(value)) {
            this.emitStatus({ type: StatusType.Done });
            return true;
        } else {
            this.emitStatus({ type: StatusType.Error });
            return false;
        }
    }

    private createDropDownField(title: string, key: string, choices: Array<ChoiceItem> = []): FieldModel {
        const dropdownSettings = ChoiceDropdownComponent.createFieldSettings(choices);

        dropdownSettings.title = title;
        dropdownSettings.validators = this.settings.validators;
        dropdownSettings.readOnlyMode = this.settings.readOnlyMode;

        const dropdownModel = new FieldModel({
            key: key,
            value: this.getFieldValue(key),
            settings: dropdownSettings,
            selector: FieldTypes.choiceDropDown,
            registration: CHOICE_DROPDOWN_REGISTRY
        });

        if (this.settings.status) {
            dropdownSettings.status = this.settings.status;
        }

        if (this.settings.statusMessage) {
            dropdownSettings.statusMessage = this.settings.statusMessage;
        }

        return dropdownModel;
    }

    private createField(fieldType: string, propName: string, fieldValue: string): FieldModel {
        const fieldModel = createFieldModel(this.fieldsProvider, this.settings.type, fieldType, propName, fieldValue, {}, null, null, this.settings.readOnlyMode);
        fieldModel.settings.validators = this.settings.validators;

        if (this.settings.status) {
            fieldModel.settings.status = this.settings.status;
        }

        if (this.settings.statusMessage) {
            fieldModel.settings.statusMessage = this.settings.statusMessage;
        }

        return fieldModel;
    }

    private getFieldValue(fieldName: string): any {
        return this.value ? this.value[fieldName] : null;
    }

    private getCountryStatesDropOptions(countryCode: string): Array<ChoiceItem> {
        if (!countryCode) {
            return [];
        }

        const selectedCountryStates = this.countries.find(x => x.isoCode === countryCode).states;
        const countryStatesDropOptions = selectedCountryStates.map(state => {
            return { Name: state.stateProvinceName, Value: state.abbreviation };
        });

        if (countryStatesDropOptions.length > 0) {
            countryStatesDropOptions.unshift({ Name: "- Select state -", Value: null });
        }

        return countryStatesDropOptions;
    }
}
