import { SettingsBase } from "../../../../fields/field-settings-base";
import { RegexHelper } from "./../../utils";
import { VALIDATORS as CustomValidators, VALIDATOR_NAMES } from "../../../../fields/common/validators";
import { VALIDATION_REGEX } from "../../../../fields/common/common-constants";

export class AdditionalUrlsSettings extends SettingsBase {

    public readonly allowMultiple: boolean = true;
    public addButtonTitle: string;

    public init(metadata: any): void {
        super.init(metadata);
        this.title = "Additional URLs";
        this.addButtonTitle = "Add additional URL";
        this.defaultValue = [];
        this.changeOnFocus = true;
    }

    public getValidators(metadata: any) {
        const baseValidators = super.getValidators(metadata);

        if (metadata.hasOwnProperty(VALIDATION_REGEX)) {
            const regularExpression = RegexHelper.buildRegex(metadata[VALIDATION_REGEX], "g");
            const pattern = regularExpression.toString().slice(1, -2);
            const validator = CustomValidators[VALIDATOR_NAMES.URL_PATTERN](pattern);

            baseValidators.push(validator);
        }

        return baseValidators;
    }
}
