
import { Component, OnInit } from "@angular/core";
import { ChoiceListComponent } from "./choice-list.component";
import { createValueAccessor } from "../../field-base";

@Component({
    selector: "sf-choice-list-multiple",
    templateUrl: "./choice-list-multiple.component.html",
    providers: [createValueAccessor(ChoiceListMultipleComponent)]
})
export class ChoiceListMultipleComponent extends ChoiceListComponent implements OnInit {
    private selectedChoices: string[] = [];

    ngOnInit(): void {
        super.ngOnInit();
        this.choiceSettings.hasFieldset = true;
    }

    onSelectionChange(value) {
        const index = this.selectedChoices.indexOf(value);
        if (index !== -1) {
            this.selectedChoices.splice(index, 1);
        } else {
            this.selectedChoices.push(value);
        }

        this.writeValue(this.selectedChoices.join());
    }
}
