import { FilterStrategyBase } from "./filter-strategy-base";
import { Filter } from "../dynamic-item.store";

export class CustomFilterStrategy extends FilterStrategyBase {
    constructor (protected filter: Filter) {
        super(filter);
    }

    buildQuery(query: any) {
        for (const filterValue of this.filter.values) {
            query = query.or().any();

            for (let i = 0; i <  filterValue.values.length; i += 1) {
                const value = filterValue.values[i];

                query = query.eq(filterValue.key, value);
            }

            query = query.done().done();
        }

        return query;
    }
}
