import { InjectionToken, Injectable, Optional, Inject } from "@angular/core";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";

export const DATA_EXTENDER_TOKEN = new InjectionToken("data-extender");

export abstract class DataExtenderBase {
    abstract isSupportedType(entityType: EntityData): boolean;

    abstract enhanceDataItems(dataItems: DataItem[], properties: {[key: string]: any}, data?: any): DataItem[];
}

@Injectable()
export class CompositeDataExtender {
    constructor(@Optional() @Inject(DATA_EXTENDER_TOKEN) private dataExtenders: DataExtenderBase[]) { }

    enhanceDataItems(entityData: EntityData, dataItems: DataItem[], properties: {[key: string]: any}, data?: {tasks?: any[], whiteListedTasks?: string[] }): DataItem[] {
        const extender = this.getExtender(entityData);
        if (extender) {
            return extender.enhanceDataItems(dataItems, properties, data);
        }

        return dataItems;
    }

    private getExtender(entityData: EntityData): DataExtenderBase {
        const extender = this.dataExtenders.find(x => entityData && x.isSupportedType(entityData));
        return extender;
    }
}
