import { Directive, Output, EventEmitter, OnDestroy, ElementRef } from "@angular/core";
import { SCROLL_EVENT, SCROLL_TO_BOTTOM_OFFSET, REPORT_SCROLL_TIME } from "./infiniteScrolling.directive";

// In order for this directive to work the element must have oveflow: scroll or overflow: auto
// Class -sf-overflow-auto can be used for this purpose.
@Directive({
    selector: "[sfInfiniteScrollOnElement]"
})
export class InfiniteScrollerOnElementDirective implements OnDestroy {
    @Output() scrolledToBottom = new EventEmitter();
    private scrollEventListener: EventListener;
    private previousScrollPosition = 0;

    constructor(private el: ElementRef) {
        this.scrollEventListener = evt => this.onWindowScroll(evt);

        this.el.nativeElement.addEventListener(SCROLL_EVENT, this.scrollEventListener);
    }

    ngOnDestroy() {
        this.el.nativeElement.removeEventListener(SCROLL_EVENT, this.scrollEventListener);
    }

    private onWindowScroll(event: any) {
        const currentPosition = this.el.nativeElement.scrollTop + this.el.nativeElement.clientHeight;
        if (currentPosition >= (this.el.nativeElement.scrollHeight - SCROLL_TO_BOTTOM_OFFSET) &&
            this.previousScrollPosition + REPORT_SCROLL_TIME < event.timeStamp) {
            this.scrolledToBottom.emit();
            this.previousScrollPosition = event.timeStamp;
        }
    }
}
