import { ElementRef, ViewChild, Input, EventEmitter, Component, Output, HostListener, OnInit } from "@angular/core";

import { LayoutService, DEFAULT_BOX_HEIGHT, DEFAULT_BOX_SPACING, DOCUMENT_ROW_HEIGHT } from "./services/layout.service";
import { MediaRecognizerService } from "./media/media-recognizer.service";
import { EntityData, DataItem } from "../content/dynamic-modules/interfaces";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";
import { cloneObject } from "../../utils";

@Component({
    selector: "sf-selected-file-list",
    templateUrl: "./selected-file-list.component.html"
})
export class SelectedFileListComponent implements OnInit {
    // TODO: Find a way (might be similar) to make the thumbnail work w/ all media types.
    readonly DEFAULT_THUMBNAIL_WIDTH = 50;
    readonly DEFAULT_THUMBNAIL_HEIGHT = 50;
    readonly DEFAULT_THUMBNAIL_SRC = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
    @ViewChild("wrapper", { static: true }) wrapper: ElementRef;
    @Input() mediaEntityData: EntityData;

    @Input()
    set files(files: DataItem[]) {
        this._files = files;
        this.recalculateLayouts();
    }

    get files() {
        return this._files;
    }

    layout: any;
    previewUrl: string;

    @Output() remove = new EventEmitter();

    private _files: DataItem[];

    constructor(private layoutService: LayoutService, private mediaRecognizerService: MediaRecognizerService) {
    }

    ngOnInit() {
        if (this.mediaEntityData && this.mediaEntityData.metadata.setName) {
            this.previewUrl = this.mediaRecognizerService.getPreviewUrlProperty(this.mediaEntityData.metadata.setName);
        }
        this.recalculateLayouts();
    }

    onFileRemoveClick(file) {
        this.remove.next(file);
        this.recalculateLayouts();
    }

    @HostListener("window:resize")
    private recalculateLayouts() {
        let boxHeight: number = DEFAULT_BOX_HEIGHT;

        if (!this.mediaEntityData?.metadata.isMultimedia) {
            boxHeight = DOCUMENT_ROW_HEIGHT;
        }

        const containerWidth = this.wrapper.nativeElement.offsetWidth;
        this.layout = this.layoutService.layout(this.files.map(x => cloneObject(x.data)), containerWidth, boxHeight, DEFAULT_BOX_SPACING, Number.POSITIVE_INFINITY, this.mediaEntityData?.metadata as MediaEntity);
    }
}
