import { Component, ViewChild, Input, AfterViewInit, Inject } from "@angular/core";
import { SelectorConstants, NOT_SUPPORTED_MESSAGE, PLACEHOLDER_MESSAGE } from "../../selector-constants";
import { Media, MediaType } from "../../immutables-facade/media";
import { stringConstants, contentTypeConstants } from "../../../../common-constants";
import { ensureTrailingBreaks } from "../immutable.helpers";
import { IFrameMediaParser, TwitterMediaParser, YoutubeMediaParser, DefaultMediaParser } from "../../immutables-facade";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { CompositeMediaParser as CompositeMediaParser } from "../../immutables-facade/composite-media.parser";

export const EMBED_MEDIA_PARSERS = [TwitterMediaParser, YoutubeMediaParser, IFrameMediaParser, DefaultMediaParser];
export const PROCESS_EMBED_MEDIA_VALUE_TIMEOUT = 1000;

@Component({
    selector: "sf-embed-media",
    templateUrl: "./embed-media.component.html"
})
export class EmbedMediaComponent implements AfterViewInit {
    @Input() selectedImmutable: HTMLElement;
    @ViewChild("preview", { static: true }) preview;
    autofocus: boolean = false;

    private media: Media;
    private valueInstance: string;
    private css: string;
    private timeoutId: number = -1;
    private hasLoaded: boolean = false;

    set width(val: any) {
        this.updateMediaHost("width", val);
    }

    get width() {
        return this.media.width;
    }

    set height(val: any) {
        this.updateMediaHost("height", val);
    }

    get height() {
        return this.media.height;
    }

    set value(val: string) {
        this.window.clearTimeout(this.timeoutId);
        this.timeoutId = this.window.setTimeout(() => {
            while (this.preview.nativeElement.firstChild) {
                this.preview.nativeElement.removeChild(this.preview.nativeElement.firstChild);
            }

            const trimmedValue = val.trim();
            this.trySetEmbedMedia(trimmedValue, false)
                .then(isValid => {
                    if (isValid) {
                        this.valueInstance = trimmedValue;
                    } else {
                        this.valueInstance = trimmedValue === stringConstants.EMPTY_STRING ? null : val;
                        this.preview.nativeElement.innerHTML = stringConstants.EMPTY_STRING;
                    }
                });
        }, PROCESS_EMBED_MEDIA_VALUE_TIMEOUT);
    }

    get value() {
        return this.valueInstance;
    }

    get isValid(): boolean {
        return this.media.isValid;
    }

    get placeholder(): string {
        return PLACEHOLDER_MESSAGE;
    }

    get errorMessages(): Array<string> {
        if (!this.isValid && this.value && this.hasLoaded) {
            return new Array<string>(NOT_SUPPORTED_MESSAGE);
        }
    }

    get title() {
        return this.media.title;
    }

    set title(val: any) {
        this.updateMediaHost("title", val);
    }

    constructor(private readonly compositeEmbedMediaParser: CompositeMediaParser,
                @Inject(WINDOW_TOKEN) private readonly window: Window) {
        this.media = new Media();
    }

    ngAfterViewInit() {
        if (this.selectedImmutable)
            this.trySetEmbedMedia(this.selectedImmutable.outerHTML)
                .then(() =>  this.autofocus = true);
    }

    getEmbedMediaHtml(): string {
        const displayWidth: number = this.media.width.value;
        const displayHeight: number = this.media.height.value;
        const embedMediaHtml: string = this.compositeEmbedMediaParser.getMediaHtml(this.media, displayWidth, displayHeight, this.css);

        return embedMediaHtml;
    }

    wrapEmbedMedia(html: string, addTrailBreaks: boolean = true): string {
        const domParser = new DOMParser();
        const virtualDom = domParser.parseFromString(html, <DOMParserSupportedType>contentTypeConstants.HTML);
        const element = <HTMLElement>virtualDom.querySelector(`[${SelectorConstants.SF_IMMUTABLE}]`);

        if (addTrailBreaks) {
            return ensureTrailingBreaks(element.outerHTML);
        } else {
            return element.outerHTML;
        }

    }

    trySetEmbedMedia(html: string, immutableIsSelected: boolean = true): Promise<boolean> {
        return this.parseEmbedMedia(html, immutableIsSelected)
            .then(media => {
                if (media.isValid) {
                    this.loadMedia();
                }

                this.media = media;
                this.hasLoaded = true;
                return media.isValid;
            });
    }

    parseEmbedMedia(html: string, immutableIsSelected = true): Promise<Media> {
        this.css = this.getCssText(html) || this.css;

        return this.compositeEmbedMediaParser.parse(html).then(media => {
            if (!media.isValid) {
                return media;
            }

            this.preview.nativeElement.innerHTML = stringConstants.EMPTY_STRING;

            if (media.type !== MediaType.Tweet) {
                media.height.hasValue = media.height.hasValue || immutableIsSelected;
                media.width.hasValue = media.width.hasValue || immutableIsSelected;
            }

            if (media.html) {
                this.preview.nativeElement.innerHTML = media.html;
                if (immutableIsSelected) {
                    this.valueInstance = this.compositeEmbedMediaParser.getValue(media.html);
                }
            }

            return media;
        });
    }

    getCssText(html: string) {
        const domParser = new DOMParser();
        const virtualDom = domParser.parseFromString(html, <DOMParserSupportedType>contentTypeConstants.HTML);
        const element = <HTMLElement>virtualDom.querySelector(`[${SelectorConstants.SF_IMMUTABLE}]`);
        if (element) {
            element.style.removeProperty("width");
            element.style.removeProperty("height");
            element.style.removeProperty("position");
            element.style.removeProperty("z-index");
            return element.style.cssText;
        }
    }

    loadMedia() {
        this.compositeEmbedMediaParser.initEmbeddedData();
    }

    private updateMediaHost(propName: string, val: any) {
        const element = this.compositeEmbedMediaParser.getMediaFromElement(this.preview.nativeElement);
        if (element) {
            this.compositeEmbedMediaParser.updateMediaElement(element, propName, val);

            if (this.media.type !== MediaType.Tweet) {
                this.valueInstance = this.compositeEmbedMediaParser.getValue(element.outerHTML);
                this.media.html = element.outerHTML;
            }

            this.media[propName].value = val;
        }
    }
}
