import { mergeMap } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { HttpClient, HttpHeaders } from "@angular/common/http";
import { ConnectorService } from "./connector.service";
import { SitefinityInsightConfiguration } from "../interfaces/sitefinity-insight-configuration";
import { SitefinityInsightHeaders } from "../interfaces/sitefinity-insight-headers";
import { INSIGHT_REQUEST_HEADERS } from "../insight.constants";

@Injectable()
export class SitefinityInsightHttpRequester {

    constructor(
        private sitefinityInsightConnectorService: ConnectorService,
        private http: HttpClient ) {
    }

    public get<T>(url: string, headers: SitefinityInsightHeaders): Observable<T> {

        return this.sitefinityInsightConnectorService.getConnectorDetails().pipe(
            mergeMap( (sitefinityInsightConfiguration: SitefinityInsightConfiguration) => {

                const httpOptions = {
                    headers: new HttpHeaders(this.getHeaders(headers, sitefinityInsightConfiguration))
                };

                return this.http.get<T>(`${sitefinityInsightConfiguration.ApiServerUrl}/${url}`, httpOptions);
            }));
    }

    public post<T>(url: string, requestPayload: any, headers: SitefinityInsightHeaders) {
        return this.sitefinityInsightConnectorService.getConnectorDetails().pipe(
            mergeMap( (sitefinityInsightConfiguration: SitefinityInsightConfiguration) => {

                const httpOptions = {
                    headers: new HttpHeaders(this.getHeaders(headers, sitefinityInsightConfiguration))
                };

                return this.http.post<T>(`${sitefinityInsightConfiguration.ApiServerUrl}/${url}`, requestPayload, httpOptions);
            }));

    }

    private getHeaders(clientSpecifiedHeaders: any, sitefinityInsightConfiguration: SitefinityInsightConfiguration) {
        const commonHeaders = {
            "x-dataintelligence-datacenterkey":  sitefinityInsightConfiguration.DataCenterApiKey,
            "Authorization": sitefinityInsightConfiguration.AuthorizationHeader
        };

        if (clientSpecifiedHeaders.filter)
            commonHeaders[INSIGHT_REQUEST_HEADERS.FILTER] = JSON.stringify(clientSpecifiedHeaders.filter);

        if (clientSpecifiedHeaders.fromDate)
            commonHeaders[INSIGHT_REQUEST_HEADERS.FROM_DATE] = clientSpecifiedHeaders.fromDate;

        if (clientSpecifiedHeaders.toDate)
            commonHeaders[INSIGHT_REQUEST_HEADERS.TO_DATE] = clientSpecifiedHeaders.toDate;

        if (clientSpecifiedHeaders.scale)
            commonHeaders[INSIGHT_REQUEST_HEADERS.SCALE] = clientSpecifiedHeaders.scale;

        if (clientSpecifiedHeaders.period)
            commonHeaders[INSIGHT_REQUEST_HEADERS.PERIOD] = clientSpecifiedHeaders.period;

        if (clientSpecifiedHeaders.sort)
            commonHeaders[INSIGHT_REQUEST_HEADERS.SORT] = JSON.stringify(clientSpecifiedHeaders.sort);

        if (clientSpecifiedHeaders.take)
            commonHeaders[INSIGHT_REQUEST_HEADERS.TAKE] = `${clientSpecifiedHeaders.take}`;

        if (clientSpecifiedHeaders.ids)
            commonHeaders[INSIGHT_REQUEST_HEADERS.IDS] = `${clientSpecifiedHeaders.ids}`;

        return commonHeaders;
    }
}
