import { AbstractControl, ValidatorFn, Validators } from "@angular/forms";
import { validationConstants } from "../../../src/app/common-constants";

export const MULTILINE_EMAILS_NAME = "multilineEmails";

export class MultilineEmailsValidator {
    static validate(): ValidatorFn {
        return (control: AbstractControl) => {
            let hasErrors = false;
            if (!control.value) {
                return null;
            }

            const arrayValue: Array<string> = control.value.split(/\n/);
            arrayValue.forEach(email => {
                const dummyControl: any = { value: email.trim() };
                const result = Validators.pattern(validationConstants.EMAIL_PATTERN)(dummyControl);

                if (result) {
                    hasErrors = true;
                }
            });

            if (hasErrors) {
                return { [MULTILINE_EMAILS_NAME]: false };
            } else {
                return null;
            }
        };
    }
}
