import { map, takeUntil, filter } from "rxjs/operators";
import { Component, OnDestroy, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { BehaviorSubject ,  Observable ,  Subject } from "rxjs";

import { createValueAccessor } from "../../../../../../../fields/field-base";
import { FieldBase } from "../../../../../../../fields/index";
import { stringConstants } from "../../../../../common-constants";
import { BLUR_EFFECT_TIMEOUT, RESOLVE_NAMES, QUERY_PARAMS } from "../../../../content/constants";
import {
    DynamicLinkResponse,
    LocatableDynamicItemService,
    UNKNOWN_ERROR_MESSAGE
} from "../../../../content/dynamic-modules/services/locatable-dynamic-item.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { MetadataContainer } from "../../../../shared/services/metadata/meta-data.store";
import { SiteData } from "../../../../shared/services/metadata/site-data.store";
import {
    Button,
    CancelButton,
    ClosingContext,
    ConfirmButton,
    DialogData,
    ModalWindowService
} from "../../../../shared/services/modal-window.service";
import { VALIDATOR_NAMES } from "../../../../../../../fields/common/validators/index";
import { SelectorConstants } from "./../../../selector-constants";
import { ContentItemModel } from "./helpers/content-item-model";
import { ContentLinkInputModel } from "./helpers/content-link-input-model";
import { ValidationError } from "./helpers/validation-error";
import { SelectorContext } from "./link-insert-selector/helpers/selector-context";
import { LinkInsertSelectorComponent } from "./link-insert-selector/link-insert-selector.component";
import { delayEmission } from "../../../../shared/rxjs-extensions";
import { ItemData } from "../../../../content/dynamic-modules/services/entity/dynamic-item.resolver";

/**
 * The url input field and the insert link selector are part of the create link functionality. The create link functionality is part of the
 * rich text editor activated in a long text field of a content item (like News items, or dynamic items with LongText fields etc.).
 * The create link functioanlity allows for easier generation of standard html anchor tags and inserting them in the editor.
 * The create link has several fields that allow setting the html properties of the anchor tag that it generates. The url input field (LinkInsertField) that allows setting
 * manually the actual href value. Under it there`s also a button that opens a content selector (LinkInsertSelector) where any content item that can be accessed via link (news,
 * blog posts, pages etc) is listed. This is convinient if the end user wants to insert a link to a content item in Sitefinity.
 */
@Component({
    selector: "sf-link-insert",
    templateUrl: "./link-insert-field.component.html",
    providers: [createValueAccessor(LinkInsertFieldComponent)]

})
export class LinkInsertFieldComponent extends FieldBase implements OnInit, OnDestroy {
    inputModel$ = new BehaviorSubject<ContentLinkInputModel>(new ContentLinkInputModel());
    hasErrors: boolean = false;
    isLoading: boolean = false;
    justAdded: boolean = false;

    private inputModel: ContentLinkInputModel = new ContentLinkInputModel();
    private linkInsertItemSelectorDialogData: DialogData;
    private meta: MetadataContainer;
    private siteData: SiteData;
    private initialCulture: string;
    private subscriptionsHolder$ = new Subject<any>();
    private get isContentLink(): boolean {
        return !!this.inputModel.contentItemModel;
    }

    constructor(
        private locatableItemsService: LocatableDynamicItemService,
        private modalService: ModalWindowService,
        private route: ActivatedRoute
    ) {
        super();
    }

    ngOnInit(): void {
        this.meta = this.route.parent.snapshot.data.metaStore;
        this.siteData = this.route.parent.snapshot.data.siteDataStore;
        const itemData = this.route.parent.firstChild.snapshot.data[RESOLVE_NAMES.itemData] as ItemData;
        this.initialCulture = itemData?.item.culture || this.route.snapshot.queryParams[QUERY_PARAMS.CULTURE] || this.siteData?.DefaultContentCulture;
        const initialValue = <ContentLinkInputModel>this.getValue();
        this.inputModel = initialValue || new ContentLinkInputModel();
        if (this.isContentLink) {
            this.initContentLink();
        }

        this.writeValue(this.inputModel);
        this.inputModel$.next(this.inputModel);
    }

    ngOnDestroy(): void {
        this.subscriptionsHolder$.next({});
        this.subscriptionsHolder$.complete();
    }

    openContentSelectorDialog() {
        const dialogData = this.getContentSelectorDialogData();
        const urlKey = "selectPageOrContent";
        this.modalService.setMapping(dialogData, urlKey);
        this.modalService.show(urlKey, this.route.parent);
    }

    onLinkInputUrlBlur() {
        if (this.isContentLink) {
            if (this.inputModel.contentItemModel.sfLink.href !== this.inputModel.href) {
                // content item url was changed
                this.inputModel.contentItemModel = null;
            } else {
                this.inputModel.contentItemModel.isEditContentLinkMode = false;
            }
        }

        this.writeValue(this.inputModel);
        super.onBlur();
    }

    onContentLinkEditClick() {
        if (!this.isLoading && this.inputModel.getErrors().length > 0) {
            this.hasErrors = true;
            this.onLinkInputUrlBlur();
            return;
        }

        this.inputModel.contentItemModel.isEditContentLinkMode = true;
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }

    onInput() {
        if (this.isContentLink) {
            if (this.inputModel.contentItemModel.sfLink.href !== this.inputModel.href) {
                // content item url was changed
                this.inputModel.contentItemModel = null;
            } else {
                this.inputModel.contentItemModel.isEditContentLinkMode = false;
            }
        }

        this.writeValue(this.inputModel);
    }

    private initContentLink() {
        this.isLoading = true;
        this.inputModel$.next(this.inputModel);
        this.subscriptionsHolder$.next({});
        this.locatableItemsService
            .getItemFromDynamicLink(this.inputModel.contentItemModel.sfLink.sfref)
            .pipe(
                delayEmission(BLUR_EFFECT_TIMEOUT),
                takeUntil(this.subscriptionsHolder$)
            )
            .subscribe((itemResponse) => {
                if (itemResponse.isLoading) {
                    return;
                }

                this.inputModel.contentItemModel.itemName = itemResponse.content.title;
                this.inputModel.contentItemModel.entityName = this.meta.entities[itemResponse.content.entitySet].displayName;
                this.isLoading = false;
                this.inputModel$.next(this.inputModel);
            }, e => {
                this.isLoading = false;
                this.setInputModelErrorState(e);
                this.inputModel.contentItemModel.sfLink.href = stringConstants.EMPTY_STRING;
                this.onBlur(); // called to trigger field validation
                this.inputModel$.next(this.inputModel);
            });
    }

    private setInputModelErrorState(e) {
        const errorMessage = e.message ? e.message : e;
        this.inputModel.contentItemModel.validationErrors.push(<ValidationError>{
            errorType: VALIDATOR_NAMES.CUSTOM,
            error: errorMessage === UNKNOWN_ERROR_MESSAGE ? { message: "Error occured. Could not get the item." } : { message: errorMessage }
        });

        const errors = this.inputModel.getErrors();
        if (errors.length > 0) {
            this.hasErrors = true;
        }
    }

    private getContentSelectorDialogData() {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton()
        ];
        const componentData: ComponentData = {
            type: LinkInsertSelectorComponent,
            afterComponentInit: c => {
                const linkInsertComponent = <LinkInsertSelectorComponent>c;
                linkInsertComponent.meta = this.meta;
                linkInsertComponent.siteData = this.siteData;
                linkInsertComponent.initialCulture = this.initialCulture;
            }
        };

        this.linkInsertItemSelectorDialogData = new DialogData(componentData, this.onContentSelectorDialogDone, buttons, null, "-bottom");
        return this.linkInsertItemSelectorDialogData;
    }

    private onContentSelectorDialogDone = (result: ClosingContext) => {
        const selector = <LinkInsertSelectorComponent>result.component;
        if (result.data && result.data.data === true) {
            const context = selector.contentSelector.context;
            if (!context || !context.selectedContentItem) {
                return;
            }

            this.initContentLinkInput(context);
        }
    }

    private initContentLinkInput(context: SelectorContext) {
        this.resetHasErrors();
        this.inputModel.contentItemModel = new ContentItemModel();
        this.inputModel.contentItemModel.entityName = context.selectedContentItem.dataItem.metadata.displayName;
        this.inputModel.contentItemModel.itemName = context.selectedContentItem.Title;
        this.inputModel.href = stringConstants.EMPTY_STRING;
        this.isLoading = true;
        this.inputModel$.next(this.inputModel);
        this.subscriptionsHolder$.next({});
        this.generateInputModelDynamicLink(context).pipe(
            takeUntil(this.subscriptionsHolder$))
            .subscribe(dynamicLinkResponse => {
                this.inputModel.contentItemModel.sfLink.href = dynamicLinkResponse.link;
                this.inputModel.href = dynamicLinkResponse.link;
                this.inputModel.contentItemModel.sfLink.sfref = dynamicLinkResponse.dynamicLink;
                this.isLoading = false;
                this.triggerJustAdded();
                this.inputModel$.next(this.inputModel);
                this.writeValue(this.inputModel);
            }, e => {
                this.isLoading = false;
                this.setInputModelErrorState(e);
                this.inputModel$.next(this.inputModel);
                this.writeValue(this.inputModel);
                this.onBlur(); // called to trigger field validation
            });
    }
    private resetHasErrors() {
        this.hasErrors = false;
    }

    private triggerJustAdded(): void {
        this.justAdded = true;

        setTimeout(() => {
            this.justAdded = false;
        }, 1000);
    }

    private generateInputModelDynamicLink(context: SelectorContext): Observable<DynamicLinkResponse> {
        return this.getSelectedContentDynamicLink(context)
            .pipe(
                delayEmission(BLUR_EFFECT_TIMEOUT),
                filter(x => !x.isLoading)
            );
    }

    private getSelectedContentDynamicLink(context: SelectorContext): Observable<DynamicLinkResponse> {
        return this.locatableItemsService
            .getDynamicLink(
                context.selectedEntitySet.value,
                context.selectedContentItem.Id,
                context.selectedProvider.value,
                this.initialCulture,
                context.selectedSite.value,
                context.selectedCulture.value === this.initialCulture ? stringConstants.EMPTY_STRING : context.selectedCulture.value
                ).pipe(
            filter(x => !x.isLoading),
            map(x => x.content));
    }
}
