import { Injectable } from "@angular/core";
import { GetWidgetMetadataArgs } from "./renderer.types";
import { ZoneEditorContract } from "./zone-editor.contract";
import { RendererService } from "./renderer.service";
import { ComponentMetadata, PropertyMetadata } from "../../widget-editor/interfaces/widget-editor";
import { forkJoin, Observable, ReplaySubject } from "rxjs";

@Injectable()
export class WidgetMetadataMergerService {
    constructor(private zoneEditorContract: ZoneEditorContract, private renderer: RendererService) {

    }

    getWidgetMetadata(args: GetWidgetMetadataArgs): Observable<ComponentMetadata> {
        const resultSubject = new ReplaySubject<ComponentMetadata>();

        const metadataFromRenderer = this.renderer.getWidgetMetadata(args);
        const metadataFromSitefinity = this.zoneEditorContract.getWidgetMetadata(args);

        forkJoin([metadataFromRenderer, metadataFromSitefinity]).subscribe((data) => {
            const rendererMeta = data[0];
            const sfMeta = data[1];

            if (!rendererMeta.PropertyMetadataFlat) {
                this.fillPropertyMetadataFlat(rendererMeta);
            }

            if (sfMeta && !sfMeta.PropertyMetadataFlat) {
                this.fillPropertyMetadataFlat(sfMeta);
            }

            if (sfMeta) {
                if (rendererMeta.PropertyMetadata.length === 0) {
                    resultSubject.next(sfMeta);
                    return;
                }

                rendererMeta.PropertyMetadata.forEach((entry) => {
                    const correspondingSfMeta = sfMeta.PropertyMetadata.find(x => x.Name === entry.Name);
                    if (correspondingSfMeta) {
                        entry.Sections.forEach((section) => {
                            const correspondingSfMetaSection = correspondingSfMeta.Sections.find(x => x.Name === section.Name);
                            if (correspondingSfMetaSection) {
                                section.Properties.push(...correspondingSfMetaSection.Properties);
                            }
                        });
                    }
                });

                sfMeta.PropertyMetadata.forEach((entry) => {
                    const correspondingRendererMeta = rendererMeta.PropertyMetadata.find(x => x.Name === entry.Name);
                    if (!correspondingRendererMeta)
                        rendererMeta.PropertyMetadata.push(entry);
                });

                rendererMeta.PropertyMetadataFlat.push(...sfMeta.PropertyMetadataFlat);
            }

            this.ensurePropertiesObject(rendererMeta);
            resultSubject.next(rendererMeta);
        });

        return resultSubject.asObservable();
    }

    private fillPropertyMetadataFlat(metadata: ComponentMetadata) {
        if (!metadata.PropertyMetadataFlat) {
            let metadataFlat = [];
            metadata.PropertyMetadata.forEach((category) => {
                category.Sections.forEach((section) => {
                    metadataFlat = metadataFlat.concat(section.Properties);
                });
            });

            metadata.PropertyMetadataFlat = metadataFlat;
        }
    }

    private ensurePropertiesObject(rendererMeta: ComponentMetadata) {
        this.ensurePropertiesObjectForList(rendererMeta.PropertyMetadataFlat);

        rendererMeta.PropertyMetadata.forEach((category) => {
            category.Sections.forEach((section) => {
                section.Properties.forEach((prop) => {
                    if (!prop.Properties)
                        prop.Properties = {};

                    if (!prop.TypeChildProperties)
                        prop.TypeChildProperties = [];

                    this.ensurePropertiesObjectForList(prop.TypeChildProperties);
                })
            });
        });
    }

    private ensurePropertiesObjectForList(rendererMeta: PropertyMetadata[]) {
        rendererMeta.forEach((prop) => {
            if (!prop.Properties)
                prop.Properties = {};

            if (!prop.TypeChildProperties)
                prop.TypeChildProperties = [];

            this.ensurePropertiesObjectForList(prop.TypeChildProperties);
        });
    }
}
