import { Input, Component, OnInit } from "@angular/core";
import { DataContext } from "../../shared/models/data-context-component";
import { CompositeGridExtender } from "../../shared/services/grid/composite-grid-extender";
import { stringConstants } from "../../../common-constants";

@Component({
    templateUrl: "./grid-thumbnail.component.html"
})
export class GridThumbnailComponent implements OnInit {
    @Input() public context: DataContext;
    isWide: boolean;
    isDimmed: boolean;
    thumbnailIcon: string;

    constructor(public gridExtender: CompositeGridExtender) {}

    ngOnInit() {
        const item = this.context.dataItem.data;
        const isTranslated = this.context.dataItem.isTranslated;

        if (item) {
            this.isDimmed = item.inactive || !isTranslated;
            const shouldHideIcon = item.ThumbnailUrl || this.context.dataItem.parentKey === stringConstants.DEFAULT_GUID;
            this.thumbnailIcon = shouldHideIcon ? null : this.gridExtender.getEmptyScreenIcon(this.context.dataItem);
        }
    }

    onImageLoaded(event: Event) {
        const image = event.target as HTMLImageElement;

        if (image && image.naturalWidth > image.naturalHeight) {
            this.isWide = true;
        }
    }
}
