import { LibraryTasksBaseCommand } from "./library-tasks-base.command";
import { ClickResult, ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { ServiceInfo } from "../../../../../../../../fields/selector/selector.component";
import { MetadataStore } from "../../../../../shared/services/metadata/meta-data.store";
import { ActivatedRoute } from "@angular/router";
import { MediaService } from "../../../../../libraries/services/media.service";
import { map } from "rxjs/operators";
import { QUERY_PARAMS, NOTIFICATION_DURATION_INFINITE } from "../../../../constants";
import { DynamicItemService } from "../../dynamic-item.service";
import { Observable, ReplaySubject } from "rxjs";
import { DataItem, OperationResult } from "../../../interfaces";
import { BulkOperationResult } from "./bulk-command";
import { CommandNotificationArgs, HasNotificationCommand } from "../../../../../shared/commands/has-notification-command";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { stringConstants } from "../../../../../../common-constants";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { DATE_CREATED_DESC_SORT_ORDER, SortService } from "../../../../../shared/services/sort.service";
import { CompositeDataExtender } from "../../../../../shared/services/data-extensions/data.extender";
import { NotificationService } from "../../../../../shared/services/notification/notification.service";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../../../../../shared/components/modal-window/modal-window.component";
import { BackgroundTaskType } from "../../background-task.types";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { Item } from "../../../../../../../../fields/types/types";
import { LongRunningTasksService } from "../../long-running-tasks.service";
import { OPERATION_TITLES } from "../../../../../shared/components/action-menu/operation.model";

export class MoveToLibraryCommand extends LibraryTasksBaseCommand implements HasNotificationCommand {
    skipNotification: boolean = true;

    protected isHierarchical = true;
    protected dialogMapping = "moveToLibrary";
    protected dialogTitle = OPERATION_TITLES.moveToAnotherLibrary;
    protected confirmButtonText = "Move";
    protected whiteListedTasks: string[] = [ BackgroundTaskType.RegenerateThumbnails ];

    constructor(modalWindowService: ModalWindowService,
                metadataStore: MetadataStore,
                compositeDataExtender: CompositeDataExtender,
                route: ActivatedRoute,
                private longRunningTasksService: LongRunningTasksService,
                private mediaService: MediaService,
                protected service: DynamicItemService,
                protected notificationService: NotificationService,
                protected sortService: SortService) {
                    super(modalWindowService, metadataStore, compositeDataExtender, route, service, notificationService, sortService);
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        return null;
    }

    protected getEntityData() {
        return this.entityData;
    }

    protected serviceLoadMore(info: ServiceInfo): Observable<{ totalCount: number, dataItems: any[] }> {
        const excludedItems = this.targetItems.filter(d => MediaHelpers.isLibrary(d.metadata.setName)).map(x => x.data.Id).filter(x => x);
        return this.mediaService
            .getFolders(this.entityData, null, false, false, info.skip, info.take || 20, null, info.searchText, { [QUERY_PARAMS.SORT]: DATE_CREATED_DESC_SORT_ORDER }, false, excludedItems.length ? excludedItems : null)
            .pipe<{ totalCount: number, dataItems: any[] }>(
                map(ret => {
                    return {
                        totalCount: ret.totalCount,
                        dataItems: this.mapNodes(ret.dataItems)
                    };
                })
            );
    }

    protected serviceExpand(info: ServiceInfo): Observable<{ totalCount: number, dataItems: any[] }> {
        const parentId = this.isHierarchical ? info.parentId : null;
        const excludedItems = this.targetItems.filter(d => MediaHelpers.isLibrary(d.metadata.setName)).map(x => x.data.Id).filter(x => x);
        return this.mediaService
            .getFolders(this.entityData, parentId, false, false, info.skip, info.take || 20, null, info.searchText, { [QUERY_PARAMS.SORT]: DATE_CREATED_DESC_SORT_ORDER }, false, excludedItems.length ? excludedItems : null)
            .pipe<{ totalCount: number, dataItems: any[] }>(
                map(ret => {
                    return {
                        totalCount: ret.totalCount,
                        dataItems: this.mapNodes(ret.dataItems)
                    };
                })
            );
    }

    protected executeConfirmAction(selectedItems: DataItem[], clickResult: ReplaySubject<ClickResult>) {
        const targetItemIds = this.targetItems.map(x => x.data.Id);
        const bulkResult: BulkOperationResult = {
            success: true,
            succeededItemsIds: targetItemIds
        };

        if (targetItemIds.length === 0) {
            clickResult.next(new ClickResult(bulkResult, true));
            return clickResult;
        }

        const data = {
            target: selectedItems[0].key,
            items: targetItemIds
        };

        this.service.executeBoundAction(this.entityData, "Default.Move()", data).subscribe(ret => {
            clickResult.next(new ClickResult(bulkResult, true));
        }, error => {
            this.notificationService.publishBasicNotification({
                message: error.message,
                look: NOTIFICATION_LOOKS.ERROR,
                duration: NOTIFICATION_DURATION_INFINITE,
                filterParam: MODAL_WINDOW_NOTIFICATION_FILTER
            });
            clickResult.next(new ClickResult(false, false, true));
        });
    }

    protected filterTargetItems(selectedItem: Item): DataItem[] {
        return this.targetItems.filter(x => {
            const parentId = x.data.FolderId || x.data.ParentId || x.data.RootId;
            return parentId !== selectedItem.Id;
        });
    }

    protected generateDescription(componentData: ComponentData) {
        componentData.properties.description = `Select a library where to move the item${this.targetItems.length > 1 ? "s" : stringConstants.EMPTY_STRING}`;
        componentData.properties.headingLook = "sf-mb--m";
    }

    protected onDone(context: ClosingContext, return$: ReplaySubject<OperationResult>) {
        const result = context.data as ClickResult;
        if (result && result.data && result.data.success) {
            this.longRunningTasksService.refresh();
        }

        super.onDone(context, return$);
    }
}
