import { Component, OnInit } from "@angular/core";
import { TimeZonesComponent } from "./timezones.component";
import { TimeZonesProvider } from "./timezones.provider";

@Component({
    templateUrl: "./timezones.readonly.component.html",
    providers: [TimeZonesProvider]
})
export class TimeZonesReadonlyComponent extends TimeZonesComponent implements OnInit {
    selectedTimeZone: string;

    ngOnInit() {
        this.registerSubscription(
            this.initializeComponent().subscribe(currentSelection => {
                if (currentSelection.isLoading) {
                    return;
                }

                const timeZone = this.options.find(x => x.Value === currentSelection.content);
                this.selectedTimeZone = timeZone.Name;
                this.isLoaded = true;
            })
        );
    }
}
