import { pluck } from "rxjs/operators";
import { Subscription } from "rxjs";
import { stringConstants } from "./../../common-constants";
import { Component, OnInit, OnDestroy } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { Router } from "@angular/router";

import { Settings } from "../../modules/shared/services/settings.service";
import { ROUTE_PATHS } from "../../constants/route-paths";

const DEFAULT_URL_SCHEMA = "https://";
const QUERY_PARAM_URL = "url";

@Component({
    selector: "sf-config",
    templateUrl: "./config.component.html"
})
export class ConfigComponent implements OnInit, OnDestroy {
    isFormVisible: boolean = true;

    private routeSubscription: Subscription;

    constructor(private route: ActivatedRoute, private settings: Settings, private router: Router) {
    }

    get currentUrl(): string {
        return this.settings.url;
    }

    set currentUrl(value: string) {
        this.settings.url = value;
    }

    ngOnInit() {
        // Using pluck for queryParam observable ensures, param changes are handled when component is NOT re-initialized
        this.routeSubscription = this.route.queryParams.pipe(
            pluck(QUERY_PARAM_URL))
            .subscribe((url: string) => {
                    if (url) {
                        this.isFormVisible = false;
                        this.currentUrl = this.parseSitefinityUrlInput(url);
                        this.logout();
                    }
                }
            );
    }

    ngOnDestroy() {
        if (this.routeSubscription) {
            this.routeSubscription.unsubscribe();
        }
    }

    onSave() {
        this.currentUrl = this.parseSitefinityUrlInput(this.currentUrl);
        // hiding the form as logout from previous instance may take some time
        this.isFormVisible = false;
        this.logout();
    }

    logout() {
        this.router.navigate([ROUTE_PATHS.HOME]);
    }

    private parseSitefinityUrlInput(str: string): string {
        // trim whitespaces
        str = str.trim();

        // strip end slashes
        while (str.endsWith(stringConstants.FORWARD_SLASH)) {
            str = str.substring(0, str.length - 1);
        }

        // add protocol scheme (https://) if missing
        if (!str.match(/^\w+:\/\//)) {
            str = DEFAULT_URL_SCHEMA + str;
        }

        return str;
    }
}
