import { Component, HostListener, Inject, OnDestroy, OnInit, TemplateRef, ViewChild } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { BehaviorSubject, Observable, ReplaySubject, Subscription } from "rxjs";
import { Subject } from "rxjs/internal/Subject";
import { ScrollService } from "../../../../services/scroll.service";
import { FILTER_PARAMS, NOTIFICATION_DURATION_INFINITE, RESOLVE_NAMES, ROUTE_PARAMS } from "../../../content/constants";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { StateWrapper } from "../../../content/dynamic-modules/services/dynamic-item-store-state";
import { BasicEditorViewComponent } from "../../../widget-editor/basic-editor.component";
import { ValidationResult } from "../../../widget-editor/interfaces/widget-editor";
import { ValidationError } from "../../services/errors/validation-error";
import { ListIndexModel, ListIndexContract, GetListDetailsModelArgs, LIST_INDEX_DETAILS_MODES, GetListItemsArgs, ListDetailsModel } from "../../services/list/list-index.contract";
import { ListIndexContractProvider } from "../../services/list/list-index-contract.provider";
import { Button, CancelButton, ClickData, ClickResult, ConfirmButton, DialogData, ModalWindowService } from "../../services/modal-window.service";
import { NOTIFICATION_LOOKS } from "../../services/notification/notification-data";
import { NotificationService, NOTIFICATION_SERVICE } from "../../services/notification/notification.service";
import { ActionButton } from "../action-menu/action-menu-model";
import { ListDetailComponent } from "./list-detail.component";
import { ComponentData } from "../../../../api/v1/widget-editor/component-data";
import { COMMAND_NAMES, ItemCommand } from "../../../content/dynamic-modules/components/commands";
import { ActionData } from "../../../content/dynamic-modules/components/grid-cells/grid-action-menu/grid-action-menu.component";
import { Operation, OPERATION_TITLES } from "../action-menu/operation.model";
import { DynamicItemService, ItemWithOperationResult } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ActionButtonsStateService } from "../../services/action-buttons-state.service";
import { ActionExecutorService } from "../../services/action-executor.service";
import { BasicNotificationComponent } from "../notifications/basic-notification/basic-notification.component";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../modal-window/modal-window.component";
import { TreeConfig } from "../../../../../../fields";
import { LeftNavbarButtonMode, NavbarConfiguration, NavbarModes } from "../navigation/navigation-menu/navigation-menu.component";
import { first } from "rxjs/operators";
import { ContentFilterService } from "../../services/content-filter.service";
import { delayEmission, toLoadingState } from "../../rxjs-extensions";
import { MINIMUM_LOADER_TIME } from "../../../../../../fields/loader-wrapper/loader-wrapper.component";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { getRunningTasksAndMap, LongRunningTasksService, LONG_RUNNING_TASK_COMPLETED } from "../../../content/dynamic-modules/services/long-running-tasks.service";
import { SiteData } from "../../services/metadata/site-data.store";
import { BackgroundTaskType, ExtendedBackgroundTask, TaskStatus, TaskType } from "../../../content/dynamic-modules/services/background-task.types";
import { cloneObject } from "../../../../utils";
import { stringConstants } from "../../../../common-constants";
import { ExternalAppConfigService } from "../../../../app-config/external-app-config.service";

@Component({
    selector: "sf-list-index",
    templateUrl: "./list-index.component.html",
    providers: [
        ActionButtonsStateService
    ]
})
export class ListIndexComponent extends SfRxBase implements OnInit, OnDestroy {
    listIndexModel: ListIndexModel;
    itemsState$: Subject<StateWrapper> = new ReplaySubject<StateWrapper>(1);
    isInitialLoadFinished: boolean = false;
    treeConfig: TreeConfig = { noSelection: true };
    listLook: string;
    navbarConfiguration: NavbarConfiguration;
    selectedFilters: any[] = [];
    notificationFilter: string;
    searchParameter: string = null;
    activeSearchValue: BehaviorSubject<string> = new BehaviorSubject<string>(null);
    entityData: EntityData;
    isEmpty: boolean = false;
    isScrolled: boolean;

    operations: BehaviorSubject<Operation[]> = new BehaviorSubject<Operation[]>([]);
    private serverOperationPending: boolean = false;
    private listIndexContract: ListIndexContract;
    private dataItem: DataItem;
    private filter: string = null;
    private queryParamsSubscription: Subscription;
    private filterParam: string = FILTER_PARAMS.FILTER;
    private searchParam: string = FILTER_PARAMS.SEARCH;
    private lastItemsState: StateWrapper;

    @ViewChild("navigationMenuTemplate", { static: true })
    private navigationMenuTemplate: TemplateRef<any>;

    @ViewChild("navigationMenuSearch")
    private navigationMenuSearchTemplate: TemplateRef<any>;

    @ViewChild("navigationMenuSpacer")
    private navigationMenuSpacerTemplate: TemplateRef<any>;

    constructor(
        protected buttonStateService: ActionButtonsStateService,
        protected serverOperationExecutor: ActionExecutorService,
        private listIndexContractProvider: ListIndexContractProvider,
        public scrollService: ScrollService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        private route: ActivatedRoute,
        private dynamicItemService: DynamicItemService,
        private router: Router,
        private activatedRoute: ActivatedRoute,
        private contentFilterService: ContentFilterService,
        private modalWindowService: ModalWindowService,
        private longRunningTasksService: LongRunningTasksService,
        private externalAppConfigService: ExternalAppConfigService) {
        super();
    }

    ngOnInit(): void {
        const routeSubscrtiption = this.route.params.subscribe(s => {
            this.entityData = this.route.snapshot.data[RESOLVE_NAMES.entityData];
            this.notificationFilter = this.entityData.metadata.typeFullName;

            const itemId = this.route.snapshot.params[ROUTE_PARAMS.ITEM_ID];
            if (itemId) {
                this.dynamicItemService.getItem({
                    itemKey: itemId,
                    entityData: this.entityData
                }).subscribe(dataItem => {
                    this.dataItem = dataItem;
                    this.initContract();
                });
            } else {
                this.initContract();
            }

        });

        this.registerSubscription(routeSubscrtiption);

        this.registerSubscription(this.itemsState$.subscribe(itemState => {
            this.isEmpty = itemState && !itemState.isLoadingItems && !itemState.hasItems;
            if (this.navbarConfiguration) {
                this.navbarConfiguration.isScrollEnabled = itemState.hasLoadedItems || (!itemState.hasLoadedItems && itemState.isLoadingItems);
            }
        }));
    }

    ngOnDestroy(): void {
        super.ngOnDestroy();
        this.notificationService.close(this.notificationFilter);
    }

    onCommand(command: ItemCommand): void {
        if (!command) {
            return;
        }

        switch (command.name) {
            case COMMAND_NAMES.itemActionClicked: {
                const data: ActionData = command.data;
                this.onActionButtonClicked(data.button, data.dataItem);
                break;
            }
        }
    }

    onActionButtonClicked(button: ActionButton, dataItem: DataItem): void {
        this.notificationService.close();

        switch (button.name) {
            case OPERATION_TITLES.properties: {
                this.openCreateEditScreen(dataItem);
                break;
            }
            case OPERATION_TITLES.create: {
                this.openCreateEditScreen();
                break;
            }
            case OPERATION_TITLES.reindex: {
                this.longRunningTasksService.start(dataItem.key, TaskType.Reindex).subscribe();
                break;
            }
            default: {
                this.listIndexContract.tryExecuteOperation(dataItem, button, this.activatedRoute).pipe(first()).subscribe(operationResult => {
                    if (operationResult.isExecuted) {
                        if (operationResult.requiresReload) {
                            this.loadItems();
                        }
                    } else {
                        this.handleServerOperation(button, dataItem).subscribe();
                    }
                });

                break;
            }
        }
    }

    @HostListener(`window:${LONG_RUNNING_TASK_COMPLETED}`, ["$event"])
    reload(event): void {
        if (!!event.detail) {
            if ((event.detail.taskStatus === TaskStatus[TaskStatus.Done] || event.detail.taskStatus === TaskStatus[TaskStatus.Failed]) && event.detail.taskName === BackgroundTaskType.Reindex) {
                this.loadItems();
            }
        }
    }

    handleServerOperation(button: ActionButton, dataItem: DataItem): Observable<ItemWithOperationResult> {
        const ret$ = new ReplaySubject<ItemWithOperationResult>(1);
        if (this.serverOperationPending) {
            return ret$.asObservable();
        }

        const serverExecute$ = this.serverOperationExecutor.execute({
            actionButton: button,
            actionButtonStateService: this.buttonStateService,
            route: this.route,
            updateItem: {
                dataItem: dataItem
            }
        });

        serverExecute$.subscribe((itemResult) => {
            this.loadItems();
            ret$.next(itemResult);
        }, () => {
            this.serverOperationPending = false;
            this.handleSaveError(button.name);
        });

        return ret$.asObservable();
    }

    onFilterUpdate(event: any) {
        this.selectedFilters[0] = event;
        this.router.navigate([], {
            relativeTo: this.activatedRoute,
            queryParams: { [this.filterParam]: event.value },
            queryParamsHandling: "merge"
        });
    }

    onNavigationScroll(isScrolled: boolean) {
        this.isScrolled = isScrolled;
    }

    private initContract(): void {
        this.listIndexContract = this.listIndexContractProvider.getContract({ entityData: this.entityData, route: this.route });
        this.listIndexModel = this.listIndexContract.getListIndexModel({ typeFullName: this.entityData.metadata.typeFullName, dataItem: this.dataItem });
        this.notificationFilter = this.listIndexModel.notificationFilter || this.notificationFilter;
        this.notificationService.close(this.notificationFilter);

        this.registerLongRunningSubscription();
        this.registerOperationsSubscription();

        if (this.listIndexModel.navigationVisible) {
            this.navbarConfiguration = {
                mode: NavbarModes.TwoColumns,
                leftNavbarButtonData: {
                    show: true,
                    look: "toggle",
                    icon: "angle-left",
                    iconLook: "size-2xl",
                    mode: LeftNavbarButtonMode.Back,
                    title: this.listIndexModel.navigationButtonTitle
                },
                isScrollEnabled: true,
                templates: [this.navigationMenuTemplate],
                scrollTemplates: [this.navigationMenuSearchTemplate, this.navigationMenuSpacerTemplate]
            };
        }

        if (!this.listIndexModel.filterArgs) {
            this.loadItems();
            return;
        }

        if (this.listIndexModel.filterArgs || this.listIndexModel.searchArgs) {
            if (this.listIndexModel.filterArgs) {
                this.selectedFilters[0] = this.listIndexModel.filterArgs.filterValues[0];
            }

            this.queryParamsSubscription = this.activatedRoute.queryParamMap.subscribe(parameterMap => {
                const filterParameter = parameterMap.get(this.filterParam);

                if (this.filter !== filterParameter) {
                    this.filter = filterParameter;
                    const selectedFilter = this.listIndexModel.filterArgs.filterValues.find(b => b.value === this.filter);
                    if (selectedFilter) {
                        this.selectedFilters[0] = selectedFilter;
                    }
                }

                const searchParameter = parameterMap.get(this.searchParam);
                let deserializedSearchParameter = null;

                if (searchParameter != null) {
                    deserializedSearchParameter = this.contentFilterService.deserializeQueryParams(searchParameter);
                }

                if (!this.searchParameter && deserializedSearchParameter && deserializedSearchParameter.length > 0) {
                    this.searchParameter = deserializedSearchParameter[0].value[0];
                }

                if (this.searchParameter !== this.activeSearchValue.value) {
                    if (deserializedSearchParameter) {
                        this.activeSearchValue.next(deserializedSearchParameter[0].value[0]);
                        this.searchParameter = deserializedSearchParameter[0].value[0];
                    } else {
                        this.searchParameter = null;
                        this.activeSearchValue.next(this.searchParameter);
                    }
                }

                this.loadItems();
            });

            super.registerSubscription(this.queryParamsSubscription);
        }
    }

    private registerOperationsSubscription() {
        this.registerSubscription(this.listIndexModel.operations.subscribe(o => {
            this.operations.next(o);
        }));
    }

    private registerLongRunningSubscription() {
        if (this.listIndexModel.hasLongRunningTasks) {
            this.registerSubscription(this.longRunningTasksService.progress.subscribe(tasks => {
                if (this.lastItemsState) {
                    const dataItems = this.disableDataItemsWithRunningTasks(this.lastItemsState.dataItems, tasks);
                    const loadingState = StateWrapper.wrap({
                        dataItems: dataItems,
                        totalCount: this.lastItemsState.totalCount
                    });
                    this.itemsState$.next(loadingState);
                }
            }));
        }
    }

    private handleSaveError(action: string) {
        const message = `An error occurred while trying to ${action} this item.`;

        this.notificationService.publishNotification({
            type: BasicNotificationComponent,
            properties: {
                message: message
            },
            look: NOTIFICATION_LOOKS.ERROR,
            closeButton: true,
            filterParam: this.notificationFilter,
            duration: NOTIFICATION_DURATION_INFINITE
        });
    }

    onItemSelected(dataItem: DataItem): void {
        this.notificationService.close();
        this.openCreateEditScreen(dataItem);
    }

    public onNavigateBack() {
        this.router.navigate([this.listIndexModel.navigationBackUrl]);
    }

    onSearch(searchValue: string) {
        if (!searchValue) {
            return;
        }

        this.searchParameter = searchValue;
        this.scrollService.scrollToTop(false);
        const currentQueryParams = Object.assign({}, this.route.snapshot.queryParams);
        delete currentQueryParams[this.filterParam];
        this.filter = null;

        const searchParams = {};
        this.contentFilterService
            .getSearchFields(this.entityData)
            .forEach(f => searchParams[f.fieldName] = [this.searchParameter]);

        const searchQueryParam = this.contentFilterService.serializeQueryParams(searchParams);
        currentQueryParams[this.searchParam] = searchQueryParam;

        this.router.navigate([], {
            relativeTo: this.activatedRoute,
            queryParams: currentQueryParams
        });
    }

    onClearSearch() {
        this.searchParameter = null;

        const currentQueryParams = Object.assign({}, this.route.snapshot.queryParams);
        delete currentQueryParams[this.searchParam];
        currentQueryParams[this.filterParam] = "all";

        this.router.navigate([], {
            relativeTo: this.activatedRoute,
            queryParams: currentQueryParams
        });
    }

    loadItems(initialLoad: boolean = true) {
        const listItemArgs: GetListItemsArgs = {
            loadData: {
                entityData: this.entityData,
                action: this.route.snapshot.params[ROUTE_PARAMS.OPERATION_NAME_SEGMENT]
            },
            dataItem: this.dataItem
        };

        let itemsToPrepend: DataItem[] = [];
        let totalCount = 0;
        if (initialLoad) {
            listItemArgs.loadData.take = this.listIndexModel.pageSize;
            listItemArgs.loadData.order = this.listIndexModel.order;
        } else if (this.lastItemsState) {
            listItemArgs.loadData.take = this.lastItemsState.getNextBatchCount(this.listIndexModel.pageSize);
            listItemArgs.loadData.skip = this.lastItemsState.loadedItemsCount;
            listItemArgs.loadData.order = this.listIndexModel.order;
            itemsToPrepend = [...this.lastItemsState.dataItems];
            totalCount = this.lastItemsState.totalCount;
        }

        if (this.listIndexModel.filterArgs && this.filter) {
            listItemArgs.loadData.additionalQueryParams = {
                [this.filterParam]: this.filter
            };
        }

        if (this.listIndexModel.searchArgs && this.searchParameter) {
            listItemArgs.loadData.additionalQueryParams = {
                [this.searchParam]: this.searchParameter
            };
        }

        if (this.listIndexModel.dataFieldNames && this.listIndexModel.dataFieldNames.length) {
            listItemArgs.loadData.dataFieldNames = this.listIndexModel.dataFieldNames;
        }

        if (this.listIndexModel.isSiteSpecific) {
            const siteData = this.route.snapshot.parent.data[RESOLVE_NAMES.siteDataStore] as SiteData;
            if (siteData) {
                listItemArgs.loadData.siteId = siteData.Id;
            }
        }

        const loadingState = StateWrapper.wrap({
            dataItems: itemsToPrepend,
            loadingItemsCount: listItemArgs.loadData.take || this.externalAppConfigService.externalConfig.contentItemsPerPage,
            totalCount: totalCount
        });
        this.itemsState$.next(loadingState);
        this.listIndexContract.getListItems(listItemArgs).pipe(
            toLoadingState(),
            delayEmission(MINIMUM_LOADER_TIME)
        ).subscribe((r) => {
            if (!r.isLoading) {
                const itemState = r.content;
                if (!initialLoad && Array.isArray(itemsToPrepend)) {
                    itemState.dataItems.unshift(...itemsToPrepend);
                } else {
                    this.isInitialLoadFinished = true;
                }

                if (this.listIndexModel.hasLongRunningTasks) {
                    const tasks = this.longRunningTasksService.progress.getValue();
                    const dataItems = this.disableDataItemsWithRunningTasks(itemState.dataItems, tasks);
                    itemState.dataItems = dataItems;
                }

                this.lastItemsState = StateWrapper.wrap(itemState);
                this.itemsState$.next(this.lastItemsState);
            }
        });
    }

    private disableDataItemsWithRunningTasks(dataItems: DataItem[], tasks: ExtendedBackgroundTask[]) {
        const tasksMap = getRunningTasksAndMap(tasks);
        dataItems.map((dataItem) => {
            const itemWithTask = tasksMap[dataItem.key];
            if (itemWithTask) {
                const indexOfItemToDisable = dataItems.findIndex(i => i.key === dataItem.key);
                const disabledItem = cloneObject(dataItem);
                disabledItem.data["inactive"] = true;
                const itemToAdd = DataItem.from(disabledItem.data, dataItem.metadata, dataItem.provider, dataItem.culture);
                dataItems[indexOfItemToDisable] = itemToAdd;
            }
        });

        return dataItems;
    }

    private openCreateEditScreen(dataItem?: DataItem) {
        const getListDetailsModelArgs: GetListDetailsModelArgs = {
            typeFullName: this.entityData.metadata.typeFullName,
            detailsMode: dataItem ? LIST_INDEX_DETAILS_MODES.EDIT : LIST_INDEX_DETAILS_MODES.CREATE,
            dataItem: dataItem,
            sites: this.route.snapshot.data ? this.route.snapshot.data.sites.dataItems : [],
            searchService: this.route.snapshot.data ? this.route.snapshot.data.searchService : stringConstants.EMPTY_STRING
        };

        const listDetailsModel = this.listIndexContract.getListDetailsModel(getListDetailsModelArgs);
        if (dataItem && listDetailsModel.loadDataFromServer) {
            this.listIndexContract.getItem({
                itemKey: dataItem.data.Id,
                entityData: this.entityData
            }).pipe(
                toLoadingState(),
                delayEmission(MINIMUM_LOADER_TIME)
            ).subscribe((result) => {
                if (!result.isLoading) {
                    dataItem = result.content;
                    this.CreateDialogData(listDetailsModel, dataItem);
                }
            });
        } else {
            this.CreateDialogData(listDetailsModel, dataItem);
        }
    }

    private saveItem(context: ClickData, dataItem?: DataItem): ReplaySubject<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);
        clickResult.next(new ClickResult(true, false));
        const editorComponent = context.component.editorComponent as BasicEditorViewComponent;
        editorComponent.validate().subscribe((result: ValidationResult) => {
            if (result && result.isValid) {
                const properties = editorComponent.getModifiedProperties();
                if (!dataItem) {
                    dataItem = DataItem.emptyItem(this.entityData);
                }

                this.listIndexContract.setPropertyValues(dataItem, properties).subscribe(() => {
                    this.loadItems();
                    clickResult.next(new ClickResult(true, true));
                }, error => {
                    clickResult.next(new ClickResult(true, false, true));
                    if (error instanceof ValidationError) {
                        editorComponent.showValidationErrors(error);
                    } else {
                        this.notificationService.publishBasicNotification({
                            message: error.message,
                            look: NOTIFICATION_LOOKS.ERROR,
                            duration: NOTIFICATION_DURATION_INFINITE,
                            filterParam: MODAL_WINDOW_NOTIFICATION_FILTER
                        });
                        this.scrollService.scrollToTop();
                    }
                });
            } else {
                clickResult.next(new ClickResult(false, false, true, false));
            }
        });

        return clickResult;
    }

    private CreateScreenButtons(listDetailsModel: ListDetailsModel, dataItem?: DataItem) {
        const buttons: Button[] = [];
        if (listDetailsModel.hasSaveButton) {
            const saveButton = new ConfirmButton(listDetailsModel.saveButtonText, (context: ClickData) => this.saveItem(context, dataItem));
            buttons.push(saveButton);
        }

        buttons.push(new CancelButton(listDetailsModel.cancelButtonText));

        return buttons;
    }

    private CreateDialogData(listDetailsModel: ListDetailsModel, dataItem?: DataItem) {
        const componentData: ComponentData = {
            type: ListDetailComponent,
            afterComponentInit: () => {
            },
            properties: {
                editorMetadata: {
                    propertyValues: dataItem && dataItem.data ? dataItem.data : {},
                    propertyMetadata: listDetailsModel.propertyMetadata,
                    propertyMetadataFlat: [],
                    propertyLocalizationMode: null,
                    name: listDetailsModel.name,
                    caption: listDetailsModel.title
                }
            }
        };

        const buttons = this.CreateScreenButtons(listDetailsModel, dataItem);
        const dialogData = new DialogData(componentData, () => { }, buttons, null);

        this.modalWindowService.setMapping(dialogData, "edit");
        this.modalWindowService.show("edit", this.route.parent);
    }
}
