import { Component, OnInit } from "@angular/core";
import { COMMAND_NAMES } from "../../../content/dynamic-modules/components/commands";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { Properties } from "../../../shared/fields.constants";
import { DataContext, DataContextComponent } from "../../../shared/models/data-context-component";

@Component({
    selector: "sf-based-on",
    templateUrl: "./based-on.component.html"
})
export class BasedOnComponent implements DataContextComponent, OnInit {
    context: DataContext;
    link: { title: string, id: string };
    text: string;

    ngOnInit() {
        if (this.context && this.context.dataItem) {
            const parentTempalte = this.context.dataItem.data[Properties.PARENT_TEMPLATE];

            if (parentTempalte) {
                if (parentTempalte.Id) {
                    this.link = {
                        id: parentTempalte.Id,
                        title: parentTempalte.Title
                    };
                } else {
                    this.text = parentTempalte.Title;
                }
            } else {
                this.text = "Not based on other template";
            }
        }
    }

    onClickHandler() {
        const invoker = this.context.invoker;
        const originalTemplate = this.context.dataItem;
        const parentTemplate = this.context.dataItem.data[Properties.PARENT_TEMPLATE];

        const data = {
            Id: parentTemplate.Id,
            Title: parentTemplate.Title,
            Renderer: parentTemplate.Renderer
        };

        const navigateToTemplate = DataItem.from(data, originalTemplate.metadata, originalTemplate.provider, originalTemplate.culture);

        invoker.invoke({
            name: COMMAND_NAMES.selectionChanged,
            data: navigateToTemplate
        });
    }
}
