import { Directive, Input, OnInit } from "@angular/core";
import { FormRuleAction, FormDefinition, FormsConstants, FormStep } from "../forms.constants";
import { FormFieldTypesParserService } from "../services/form-field-types-parser.service";
import { stringConstants } from "../../../common-constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { DynamicItemService, LoadItem } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../../content/dynamic-modules/interfaces";

interface FormActionColumnModel {
    title: string;
    cssClassList?: string;
}

const ERROR_CSS_CLASS = "-sf-txt-failure";

@Directive({
    selector: "[sfFormActionColumn]",
    exportAs: "sfFormActionColumn"
})
export class FormActionColumnDirective implements OnInit {
    @Input() formRuleAction: FormRuleAction;
    @Input() formDefinition: FormDefinition;
    @Input() isFormField: boolean = true;

    actionColumnData: FormActionColumnModel = {
        title: stringConstants.EMPTY_STRING
    };

    constructor(
        private typeParserService: FormFieldTypesParserService,
        private metadataStore: MetadataStore,
        private dynamicItemsService: DynamicItemService) {}

    ngOnInit() {
        this.setFieldActionData();
    }

    private setFieldActionData() {
        if (this.isFormField) {
            this.getActionFieldData();
        } else {
            this.getActionData();
        }
    }

    private getActionData(): void {
        const availableAction = this.formDefinition.AvailableActions.find(a => a.Key === this.formRuleAction.Action);
        this.actionColumnData.title = this.formRuleAction.Action;

        if (availableAction) {
            this.actionColumnData.title = availableAction.Value;
        }
    }

    private getActionFieldData(): void {
        switch (this.formRuleAction.Action) {
            case FormsConstants.FORM_ACTION_TYPE.SHOW:
            case FormsConstants.FORM_ACTION_TYPE.HIDE:
                const formField = this.typeParserService.getField(this.formDefinition, this.formRuleAction.Target);

                if (formField) {
                    this.actionColumnData.title = formField.Title;
                }

                break;
            case FormsConstants.FORM_ACTION_TYPE.SKIP:
                const step: FormStep = this.formDefinition.Steps ? this.formDefinition.Steps.find(s => s.Key.toString() === this.formRuleAction.Target) : null;

                if (step) {
                    this.actionColumnData.title = step.Value;
                }

                break;
            case FormsConstants.FORM_ACTION_TYPE.GOTO:
                const pageId = this.formRuleAction.Target;
                if (pageId) {
                    const pageEntity = this.metadataStore.getEntity(ENTITY_SET.PAGES);
                    const formLoadData = <LoadItem>{
                        itemKey: pageId,
                        entityData: <EntityData>{
                            metadata: pageEntity,
                            culture: this.formDefinition.Culture
                        }
                    };

                    this.dynamicItemsService.getItem(formLoadData).subscribe(
                        result => {
                            this.actionColumnData.title = result.data.Title;
                        },
                        error => {
                            this.actionColumnData = {
                                title: FormsConstants.PAGE_DOES_NOT_EXIST,
                                cssClassList: ERROR_CSS_CLASS
                            };
                        }
                    );
                }

                break;
            case FormsConstants.FORM_ACTION_TYPE.SEND_NOTIFICATION:
                this.actionColumnData.title = this.formRuleAction.Target
                    .trim()
                    .split(",")
                    .filter(s => s !== stringConstants.EMPTY_STRING)
                    .map(s => s.trim())
                    .join(`${stringConstants.COMMA}${stringConstants.INTERVAL}`);

                break;
            default:
                this.actionColumnData.title = this.formRuleAction.Target;

                break;
        }
    }
}
