import { Injectable } from "@angular/core";
import { RegexHelper } from "../utils";
import { stringConstants } from "../common-constants";

// TODO: #227311 move to shared module
@Injectable()
export class SanitizeService {
    sanitizeValue(value: string, regex: string, replaceChar = "-"): string {
        if (value && regex) {
            let sanitizedValue;
            const beginningOfStringDashRegex = RegexHelper.buildRegex("^[\-]");
            const endOfStringDashRegex = RegexHelper.buildRegex("[\-]$");
            const sanitizeRegex = RegexHelper.buildRegex(regex, "g");
            let currentSanitizedValue = value.toLowerCase();

            do {
                sanitizedValue = currentSanitizedValue;
                currentSanitizedValue = RegexHelper.replace(sanitizedValue, sanitizeRegex, replaceChar);

                if (!beginningOfStringDashRegex.test(value) && beginningOfStringDashRegex.test(currentSanitizedValue))
                    currentSanitizedValue = RegexHelper.replace(currentSanitizedValue, beginningOfStringDashRegex, "");

                if (!endOfStringDashRegex.test(value) && endOfStringDashRegex.test(currentSanitizedValue))
                    currentSanitizedValue = RegexHelper.replace(currentSanitizedValue, endOfStringDashRegex, "");
            }
            while (currentSanitizedValue !== sanitizedValue);

            return sanitizedValue;
        }

        return value;
    }

    getReplaceCharacter(fieldSettings: any) {
        return fieldSettings.sanitizeRegexReplaceCharacter || stringConstants.DASH;
    }
}
