import { FieldBase, createValueAccessor } from "../../../../../../../fields";
import { Component, EventEmitter, OnInit, Output } from "@angular/core";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { ContentSettings } from "./content.settings";
import { MetadataStore, Entity, MediaEntity } from "../../../../shared/services/metadata/meta-data.store";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { SearchMode } from "../../../../shared/services/content-filter.service";
import { EntityData, DataItem } from "../../../../content/dynamic-modules/interfaces";
import { FieldRegistration, FieldTypes } from "../../../../shared/fields-builder/services/fields-registry";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { ExtendedKeyValuePair } from "../../../../../../../fields/services/base.service";

import taxaConstants from "../../../../taxonomy/taxonomy.constants";
import { Taxonomy } from "../../../../taxonomy/intefaces";
import { createFieldModel } from "../../../../shared/fields.constants";
import { CompositeFieldsProvider } from "../../../../shared/fields-builder/providers/fields-provider";
import { PropertyEditorWidgets } from "../../../property-editor.constants";
import { FieldSectionModel, FieldSectionSettings } from "../../../../../services/fieldSection.model";
import { ValueChange } from "../../../../shared/fields-builder/components/editable-fields/editable-fields.component";
import { stringConstants, ANY_SITE_SOURCE_PROVIDER, CONTENT_SOURCE_NOT_AVAILABLE_WARNING } from "../../../../../common-constants";
import { VALIDATION_ALLOWMULTIPLE, RELATE_DATA_PROVIDER, ACCEPTABLE_MEDIA_TYPES, ALLOWED_FILE_EXTENSIONS } from "../../../../../../../fields/common/common-constants";
import { FieldModel } from "../../../../../services/field.model";
import { RelatedDataSettings } from "../../../../../../../fields/related-data/related-data.settings";
import { cloneObject } from "../../../../../utils";
import { combineLatest, of } from "rxjs";
import { Settings } from "../../../../shared/services/settings.service";
import { FIELD_MEDIA_TYPE_MAPPER } from "../field-properties-mapper";
import { MediaSettings } from "../../../../libraries/media/media.settings";
import { StatusType } from "../../../../../../../fields/field-status";
import { QUERY_PARAMS } from "../../../../content/constants";
import { ActivatedRoute } from "@angular/router";
import { TaxonomySettings } from "../../../../taxonomy";
import { SiteDataStore } from "../../../../shared/services/metadata/site-data.store";
import { first } from "rxjs/operators";

const taxonomyKeyType = "Taxonomy_";
const chipsTemplateName = "chips";
const pageNodeEntityFullName = "Telerik.Sitefinity.Pages.Model.PageNode";
const siteEntityFullName = "Telerik.Sitefinity.Multisite.Model.Site";

@Component({
    selector: "sf-content-selector",
    templateUrl: "./content-selector.component.html",
    providers: [createValueAccessor(ContentSelectorComponent)]
})
export class ContentSelectorComponent extends FieldBase<ContentSettings, MixedContentValue> implements OnInit {
    @Output() onSelectionChange: EventEmitter<MixedContentValue> = new EventEmitter<MixedContentValue>();
    fieldSections: FieldSectionModel[];
    private entity: Entity;
    private isInvalidContentType;
    private fallbackProperties: Array<string>;
    private currentSiteId: string;

    constructor(
        private settingsService: Settings,
        private route: ActivatedRoute,
        private fieldsProvider: CompositeFieldsProvider,
        private service: DynamicItemService,
        private store: MetadataStore,
        private siteDataStore: SiteDataStore) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        if (!this.value && this.settings.useDefaultValue) {
            this.value = this.settings.defaultValue;
        }

        this.siteDataStore.getValue().pipe(first()).subscribe(siteData => {
            this.currentSiteId = siteData.Id;
        });

        const contentType = this.settings.contentType;
        if (this.getModeOfOperation() === ModeOfOperation.Taxonomy || this.getShowChipSelector()) {
            this.initTaxonomy(contentType);
        } else if (this.getModeOfOperation() === ModeOfOperation.Content) {
            this.initContent(contentType);
        } else {
            this.emitStatus({ type: StatusType.Warning });
            this.isInvalidContentType = true;
        }
    }

    onChange(args: ValueChange) {
        if (Array.isArray(args.value) && args.value.length > 0) {
            let valueObject = null;
            switch (this.getModeOfOperation()) {
                case ModeOfOperation.Taxonomy:
                    valueObject = {
                        ItemIdsOrdered: args.value,
                        Content: [{
                            Variations: [{
                                Filter: {
                                    Key: "Ids",
                                    Value: args.value.join(",")
                                }
                            }]
                        }
                        ]
                    };
                    break;
                case ModeOfOperation.Content:
                    if (this.getShowChipSelector()) {
                        valueObject = {
                            ItemIdsOrdered: args.value,
                            Content: [{
                                Variations: [{
                                    Filter: {
                                        Key: "Ids",
                                        Value: args.value.join(",")
                                    }
                                }]
                            }
                            ]
                        };
                    } else if (this.settings.actAsWrappingMediaField) {
                        valueObject = <any> {
                            Id: (args.value[0] as any).Id,
                            Title: (args.value[0] as any).Title,
                            AlternativeText: (args.value[0] as any).AlternativeText,
                            Provider: (args.value[0] as any).provider || (args.value[0] as any).Provider,
                            Url: (args.value[0] as any).Url
                        };
                    } else {
                        const groupsByProvider = {};
                        args.value.forEach((value) => {
                            const provider = value.provider || value.Provider
                            if (!groupsByProvider[provider])
                                groupsByProvider[provider] = [];

                            groupsByProvider[provider].push(value[this.entity.key]);
                        });
                        valueObject = {
                            ItemIdsOrdered: args.value.map(x => x[this.entity.key]),
                            Content: [{
                                    Variations: []
                                }
                            ]
                        };
                        Object.keys(groupsByProvider).forEach((key) => {
                            valueObject.Content[0].Variations.push({
                                Source: key,
                                Filter: {
                                    Key: "Ids",
                                    Value: groupsByProvider[key].join(",")
                                }
                            });
                        });
                    }
                    break;
            }

            // The value needs to be asigned with single assign. Further modifications are not
            // captured by the form.
            this.value = valueObject;
        } else {
            this.value = null;
        }

        this.onSelectionChange.emit(this.value);
    }

    getWarnings(): Array<string> {
        if (this.isInvalidContentType) {
            return [CONTENT_SOURCE_NOT_AVAILABLE_WARNING];
        }

        return super.getWarnings();
    }

    private getModeOfOperation(): ModeOfOperation {
        const contentType = this.settings.contentType;
        if (contentType) {
            if (contentType.startsWith(taxonomyKeyType)) {
                return ModeOfOperation.Taxonomy;
            }

            const entity = this.store.getEntityByFullTypeName(contentType);
            if (entity)
                return ModeOfOperation.Content;
        }

        return null;
    }

    private getSingleContext(): ContentValue {
        if (this.value && this.value.Content && this.value.Content.length > 0) {
            return this.value.Content[0];
        }

        return null;
    }

    private initContent(typeFullName: string) {
        this.entity = this.store.getEntityByFullTypeName(typeFullName);
        this.fallbackProperties = this.settings.contentDisplayFieldName ? [this.settings.contentDisplayFieldName] : [this.entity.defaultFieldName];
        const context = this.getSingleContext();

        if (this.entity) {
            const metadata: { [key: string]: any } = {
                [VALIDATION_ALLOWMULTIPLE]: this.settings.contentAllowMultipleItemsSelection,
                [RELATE_DATA_PROVIDER]: this.settings.contentProvider || ANY_SITE_SOURCE_PROVIDER
            };

            let fieldType: string;
            if (!this.entity.isMedia) {
                fieldType = FieldTypes.relatedData;
            } else {
                fieldType = FieldTypes.media;
                const mediaEntity = this.entity as MediaEntity;
                if (!mediaEntity.mediaFilterEnabled) {
                    metadata[ALLOWED_FILE_EXTENSIONS] = ["*"];
                } else {
                    metadata[ACCEPTABLE_MEDIA_TYPES] = mediaEntity.acceptableMediaTypes;
                    metadata[ALLOWED_FILE_EXTENSIONS] = mediaEntity.acceptableFileTypes;
                }
            }

            const fieldModel = createFieldModel(this.fieldsProvider, PropertyEditorWidgets.FIELD_TYPE_KEY + "Content", fieldType, this.settings.key, null, metadata, null, null, false, "-sf-p-zero -sf-m-zero");
            const relatedSettings = fieldModel.settings as (RelatedDataSettings | MediaSettings);
            relatedSettings.useLiveData = this.settings.contentLiveData;
            relatedSettings.provider = metadata[RELATE_DATA_PROVIDER];
            (<RelatedDataSettings>relatedSettings).skipInputSelection = this.settings.contentOpenMultipleItemsSelection;
            (<RelatedDataSettings>relatedSettings).disableInteraction = this.settings.contentDisableInteraction;
            (<RelatedDataSettings>relatedSettings).displayFieldName = this.settings.contentDisplayFieldName;
            (<RelatedDataSettings>relatedSettings).readOnlyMode = this.settings.readOnlyMode;

            let additionalQueryParams = null;
            if (this.settings.contentShowSiteSelector) {
                (<RelatedDataSettings>relatedSettings).showSiteSelector = true;
                additionalQueryParams = {
                    [QUERY_PARAMS.GET_ALL_ITEMS]: true
                };
            }

            if (this.entity.setName === ENTITY_SET.PIPE_SETTINGS) {
                if (this.route.snapshot.data.itemData) {
                    additionalQueryParams = {
                        [QUERY_PARAMS.SEARCHINDEXID]: this.route.snapshot.data.itemData.entityData.Id
                    };
                }
            }

            if (this.settings.filter) {
                (<RelatedDataSettings>relatedSettings).filter = this.settings.filter;
            }

            if (this.entity.isMedia) {
                const mediaSettings = relatedSettings as MediaSettings;
                mediaSettings.name = mediaSettings.key;
                relatedSettings.type = FIELD_MEDIA_TYPE_MAPPER.get(this.entity.setName);
                relatedSettings.useLiveData = true;

                if (this.settings.actAsWrappingMediaField) {
                    mediaSettings.look = "inline";
                    mediaSettings.openPickerWhenEmpty = this.settings.openPickerWhenEmpty;
                    mediaSettings.chipLike = !this.settings.openPickerWhenEmpty;
                    mediaSettings.provider = ANY_SITE_SOURCE_PROVIDER;
                    mediaSettings.canRelateDamAssets = true;
                    mediaSettings.hidePropertiesLabel = true;
                }
            } else {
                relatedSettings.type = this.entity.setName;
                relatedSettings.isNestedInParentControl = true;
            }

            if (!this.entity.hasLifecycle && this.entity.setName !== ENTITY_SET.FORMS) {
                (<RelatedDataSettings>relatedSettings).hideStatus = true;
            }

            if (fieldType === FieldTypes.media && metadata[RELATE_DATA_PROVIDER] === ANY_SITE_SOURCE_PROVIDER) {
                (<MediaSettings>fieldModel.settings).canRelateDamAssets = true;
            }

            if (context) {
                const requestsForItems = context.Variations.map((variation) => {
                    const entityData: EntityData = {
                        metadata: this.entity,
                        provider: variation.Source,
                        culture: this.settings.culture
                    };

                    if (!variation.Filter.Value) {
                        return of({
                            totalCount: 0,
                            entityData: entityData,
                            dataItems: []
                        });
                    }

                    return this.service.getItemsByKeys({
                        entityData,
                        serviceUrl: this.settings.contentLiveData ? this.settingsService.webServiceLiveUrl : undefined,
                        keyProperty: this.entity.key,
                        keys: variation.Filter.Value.split(","),
                        fallbackProperties: this.fallbackProperties,
                        additionalQueryParams
                    });
                });

                combineLatest(requestsForItems).subscribe((responses) => {
                    const allItems: DataItem[] = [];
                    responses.forEach((response) => {
                        allItems.push(...response.dataItems);
                    });

                    const itemIds = this.value.ItemIdsOrdered;
                    if (itemIds != null && itemIds.length > 0) {
                        allItems.sort((a, b) => {
                            const aIndexInArray = itemIds.findIndex(x => x === a.key);
                            const bIndexInArray = itemIds.findIndex(x => x === b.key);

                            return aIndexInArray - bIndexInArray;
                        });
                    }

                    fieldModel.value = allItems.map(x => cloneObject(x.data));
                    this.wrapInSection(fieldModel);
                    this.onChange({ value: fieldModel.value } as any);
                });
            } else {
                this.wrapInSection(fieldModel);
            }
        }
    }

    private initTaxonomy(typeFullName: string) {
        if (this.getModeOfOperation() === ModeOfOperation.Taxonomy) {
            this.entity = this.store.getEntity(ENTITY_SET.CLASSIFICATIONS);
            const taxonomyName = typeFullName.replace(taxonomyKeyType, stringConstants.EMPTY_STRING);
            const entityData: EntityData = {
                metadata: this.entity,
                provider: null,
                culture: this.settings.culture
            };

            const filter: ExtendedKeyValuePair[] = [{
                key: "Name",
                value: [taxonomyName],
                searchMode: SearchMode.equals
            }];

            this.service.getItemList({
                entityData: entityData,
                filter
            }).subscribe((items) => {
                const dataItems = items.dataItems;
                if (dataItems.length === 1) {
                    const taxonomy = dataItems[0].data as Taxonomy;
                    const taxonomyMeta = {
                        [taxaConstants.TAXONOMY_NAME]: taxonomy.Name,
                        [taxaConstants.TAXONOMY_ID]: taxonomy.Id,
                        [taxaConstants.TAXONOMY_TYPE]: taxonomy.TaxaUrl,
                        [VALIDATION_ALLOWMULTIPLE]: this.settings.contentAllowMultipleItemsSelection
                    };
                    const fieldModel = createFieldModel(this.fieldsProvider, PropertyEditorWidgets.FIELD_TYPE_KEY + "Content", FieldTypes.taxa, this.settings.key, null, taxonomyMeta, null, null, false, "-sf-p-zero -sf-m-zero");
                    fieldModel.settings.isNestedInParentControl = true;

                    const value = this.getSingleContext();
                    if (value) {
                        fieldModel.value = this.getFilterVariation(value);
                    }

                    this.wrapInSection(fieldModel);
                } else {
                    this.isInvalidContentType = true;
                    this.emitStatus({ type: StatusType.Warning });
                }
            });
        } else {
            this.entity = this.store.getEntityByFullTypeName(typeFullName);
            this.fallbackProperties = this.settings.contentDisplayFieldName ? [this.settings.contentDisplayFieldName] : [this.entity.defaultFieldName];

            if (this.entity) {
                const metadata: { [key: string]: any } = {
                    [taxaConstants.TAXONOMY_TYPE]: this.entity.setName,
                    [VALIDATION_ALLOWMULTIPLE]: this.settings.contentAllowMultipleItemsSelection
                };

                const fieldModel = createFieldModel(this.fieldsProvider, PropertyEditorWidgets.FIELD_TYPE_KEY + "Content", FieldTypes.taxa, this.settings.key, null, metadata, null, null, false, "-sf-p-zero -sf-m-zero");
                const taxonomySettings = fieldModel.settings as (TaxonomySettings);
                taxonomySettings.isNestedInParentControl = true;
                taxonomySettings.forceShouldShowAll = this.settings.contentForceShouldShowAll;
                (<TaxonomySettings>taxonomySettings).skipInputSelection = this.settings.contentOpenMultipleItemsSelection;
                const value = this.getSingleContext();
                if (value) {
                    fieldModel.value = this.getFilterVariation(value);
                }

                this.setImmutableItemIds(fieldModel, taxonomySettings);

                this.wrapInSection(fieldModel);
            } else {
                this.isInvalidContentType = true;
                this.emitStatus({ type: StatusType.Warning });
            }
        }
    }

    private setImmutableItemIds(fieldModel: FieldModel, taxonomySettings: TaxonomySettings) {
        if (this.settings.contentHasPreSelectedImmutableItems) {
            if (fieldModel.value) {
                (<TaxonomySettings>taxonomySettings).immutableitemIds = fieldModel.value.filter(itemId => itemId === this.currentSiteId);
            } else {
                if (this.entity.setName === ENTITY_SET.SITES) {
                    fieldModel.value = [this.currentSiteId];
                    (<TaxonomySettings>taxonomySettings).immutableitemIds = [this.currentSiteId];
                }
            }
        }
    }

    private wrapInSection(fieldModel: FieldModel) {
        const sectionOptions: FieldSectionSettings = {
            isMain: true,
            isExpanded: true,
            insertHorizontalRule: false,
            hideTitle: true,
            name: this.settings.key
        };
        const section = new FieldSectionModel(sectionOptions);
        fieldModel.settings.showTitle = false;
        fieldModel.settings.culture = this.settings.culture;
        fieldModel.settings.allowCreate = this.settings.allowCreate;
        fieldModel.settings.allowView = this.settings.allowView;
        section.fields.push(fieldModel);
        this.fieldSections = [section];
    }

    private getShowChipSelector(): boolean {
        return (this.settings.contentType === pageNodeEntityFullName &&
            !this.settings.contentAllowMultipleItemsSelection) ||
            (this.settings.contentTemplate === chipsTemplateName) ||
            this.settings.contentType === siteEntityFullName;
    }

    private getFilterVariation(value): string[] {
        return value && value.Variations ? value.Variations[0].Filter.Value?.split(",") : null;
    }
}

enum ModeOfOperation {
    Taxonomy,
    Content
}

export interface MixedContentValue {
    ItemIdsOrdered?: string[],
    Content: Array<ContentValue>,
}

interface ContentValue {
    Type?: string,
    Variations: Array<{
        Filter?: {
            Key: string,
            Value: string
        },
        Source?: string,
        DynamicFilterByParent?: boolean
    }>
}

export const CONTENT_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: ContentSelectorComponent,
    readComponent: ContentSelectorComponent,
    settingsType: SettingsBase
};
