import {
    Component,
    ViewChild,
    Input,
    Output,
    EventEmitter,
    TemplateRef,
    ElementRef,
    OnInit,
    AfterViewInit
} from "@angular/core";

import { DataItem, HierarchicalDataItem } from "../../src/app/modules/content/dynamic-modules/interfaces";
import { ExpandedNodesChangedEvent, SfTreeComponent, TreeConfigBase, TreeNodeModel, DataProperties, ComponentData } from "@progress/sitefinity-component-framework";
import { TreeNodeComponentCompositeProvider, TreeNodeComponentFeatures } from "./tree-node-component.provider";
import { MetadataStore } from "../../src/app/modules/shared/services/metadata/meta-data.store";
import { ActivatedRoute } from "@angular/router";
import { QUERY_PARAMS } from "../../src/app/modules/content/constants";
import { TreeNode } from "@circlon/angular-tree-component";
import { Properties } from "../../src/app/modules/shared/fields.constants";
import { IDTypeDictionary } from "@circlon/angular-tree-component/lib/defs/api";
import { from as observableFrom, Observable } from "rxjs";
import { delay, first, map } from "rxjs/operators";
import { addPrefix } from "../../src/app/utils";
import { delayEmission, toLoadingState } from "../../src/app/modules/shared/rxjs-extensions";

const CACHED_ITEMS_NAME = "sfCachedItems";

export const DEFAULT_DATA_FIELDS = {
    BREADCRUMB: "Breadcrumb",
    DESCRIPTION: "description"
};

const LOADING_TIME = {
    LOAD_CHILDREN: 100
};

export const JUST_ADDED_PROPERTY: string = addPrefix("justAdded");

@Component({
    selector: "sf-tree-wrapper",
    templateUrl: "./tree-wrapper.component.html"
})
export class TreeWrapperComponent implements OnInit, AfterViewInit {

    @ViewChild(SfTreeComponent, { static: false }) private innerTree: SfTreeComponent;
    @ViewChild("virtualizationWrapper", { static: false }) wrapper: ElementRef;
    @ViewChild("defaultTemplate", { static: true }) defaultTemplate: TemplateRef<any>;

    @Input() focusFirstNode: boolean = false;
    @Input() isLoadingMore: boolean = false;
    @Input() config: TreeConfig = {};

    @Input() itemTemplate: TemplateRef<any>;
    @Input() textToMatch: string;
    @Input() look: string;

    @Input()
    set nodes(nodes: any[]) {
        this._nodes = nodes;

        this.syncNodesToDisplay();
    }
    get nodes() {
        return this._nodes;
    }

    @Input() set loadChildren(callback: (node: any) => Promise<any>) {
        const delayedCallback = (node: any): Promise<any> => {
            const callback$ = observableFrom(callback(node))
                .pipe(
                    toLoadingState(),
                    delayEmission(LOADING_TIME.LOAD_CHILDREN),
                    first(r => !r.isLoading),
                    map(r => r.content)
                );

            return callback$.toPromise();
        };

        this._loadChildren =  delayedCallback;
    }

    get loadChildren(): (node: any) => Promise<any> {
        return this._loadChildren;
    }

    @Input() displayField: string;

    @Output() treeNodePressEnter: EventEmitter<TreeNode> = new EventEmitter<TreeNode>();
    @Output() treeNodeClicked: EventEmitter<TreeNode> = new EventEmitter<TreeNode>();
    @Output() removeNode: EventEmitter<TreeNode> = new EventEmitter<TreeNode>();
    @Output() onViewNode: EventEmitter<TreeNode> = new EventEmitter<TreeNode>();
    @Output() dataUpdate: EventEmitter<void> = new EventEmitter<void>();
    @Output() reorderNodes: EventEmitter<any> = new EventEmitter<any>();
    @Output() moveNode: EventEmitter<any> = new EventEmitter<any>();
    @Output() initialized: EventEmitter<void> = new EventEmitter<void>();
    @Output() checkBoxClicked: EventEmitter<TreeNode> = new EventEmitter<TreeNode>();
    @Output() expandedNodesChanged: EventEmitter<string[]> = new EventEmitter<string[]>();
    @Output() visibleNodesCountChanged: EventEmitter<number> = new EventEmitter<number>();

    justAddedProperty: string = JUST_ADDED_PROPERTY;
    treeTemplate: TemplateRef<any>;
    nodesToDisplay: any[] = [];
    getChildrenOverrideFunc: (node: TreeNode) => Promise<any>;
    nodeHeight: (node: TreeNode) => number;
    dataProperties: DataProperties = {
        breadcrumbField: DEFAULT_DATA_FIELDS.BREADCRUMB,
        descriptionField: DEFAULT_DATA_FIELDS.DESCRIPTION
    };

    private _nodes: any[];
    private _loadChildren: (node: any) => Promise<any>;
    private allowDrop: (element: any, { parent, index }) => boolean = (element: any, { parent, index }): boolean => {
    // we should allow drop only when drop between items (parent.parent === null)
    // and when drop inside of the same tree - tree model contains the element that is being dragged
    return parent.parent === null && parent.treeModel.nodes.indexOf(element.data) > -1;
}

    constructor(
        private treeNodeComponentCompositeProvider: TreeNodeComponentCompositeProvider,
        private metaDataStore: MetadataStore,
        private route: ActivatedRoute) {
    }

    ngAfterViewInit() {
        this.syncNodesToDisplay();
    }

    ngOnInit() {
        if (this.config) {
            if (!this.config.drop) {
                this.config.drop = this.allowDrop;
            }

            if (this.config.skipNodeMappingToDefaultModel === undefined) {
                this.config.skipNodeMappingToDefaultModel =  !(!!this.itemTemplate);
            }

            if (this.nodes) {
                this.mapCustomComponentData();
            }
        } else {
            this.config = { drop: this.allowDrop };
        }

        this.treeTemplate = this.itemTemplate ? this.itemTemplate : this.defaultTemplate;
        this.setExpandChildrenOverride();
        this.setVirtualizationNodeHeight();
    }

    private setExpandChildrenOverride(): void {

        if (this.config.treeProperties?.getChildren) {
            const currentCallback = this.config.treeProperties.getChildren as Function;

            this.getChildrenOverrideFunc = (node: TreeNode) => {
                if (node[CACHED_ITEMS_NAME]) {
                    return new Observable(o => { o.next(node[CACHED_ITEMS_NAME]); return o.complete(); }).pipe(delay(0)).toPromise();
                }

                const promise = currentCallback(node) as Promise<any[]>;
                const promiseExecutor = (resolve, reject) => {
                    promise.then((data: any[]) => {
                        const remapped = data.map((item) => {
                            if (item instanceof DataItem && item.data) {
                                const wrapper: TreeItem = {
                                    id: item.key,
                                    dataItem: item,
                                    hasChildren: item.data.hasOwnProperty(Properties.HAS_CHILDREN) && item.data[Properties.HAS_CHILDREN]
                                };

                                return wrapper;
                            } else {
                                return item;
                            }
                        });

                        resolve(remapped);
                    }).catch(data => {
                        reject(data);
                    });
                };

                return new Promise(promiseExecutor);
            };
        }
    }

    private setVirtualizationNodeHeight(): void {
        this.nodeHeight = (node: TreeNode) => {

            // when we have the new editor label the height of the main component is 76px
            if (node.data.dataItem && node.data.dataItem.data.Renderer) {
                return Math.max(this.config.virtualizationOptions.nodeHeight, 76);
            }

            return this.config.virtualizationOptions.nodeHeight;
        };
    }

    private hasChildById(key, nodes, nodeFound = false): boolean {
        if (nodeFound) {
            return true;
        }
        nodes.forEach(x => {
            if (x.key === key && x.hasChildren) {
                nodeFound = true;
                return nodeFound;
            }
            if (x._children) {
                nodeFound = this.hasChildById(key, x._children, nodeFound);
            }
        });
        return nodeFound;
    }

    private syncNodesToDisplay(): void {
        if (this.itemTemplate && this.nodes && !this.config.skipNodeMappingToDefaultModel) {
            this.mapNodes(this.nodes);
        } else {
            this.nodesToDisplay = this.nodes;
        }

        if (this.nodesToDisplay) {
            this.nodesToDisplay.forEach(item => {
                if (!item.hasOwnProperty("showViewUrl")) {
                    item.showViewUrl = true;
                }
            });
        }

        if (this.config.expandedNodeIds && this.config.isHierarchical) {
            this.config.expandedNodeIds.forEach((x) => {
                if (this.hasChildById(x, this.nodes)) {
                    this.innerTree.setExpandedNode(x, true);
                }
            });
        }

        if (this.config.selectedNodeIds) {
            this.config.selectedNodeIds.forEach((x) => {
                this.innerTree.setSelectedLeafNodeId(x);
                this.innerTree.setActiveNodeId(x);
            });
            this.clearFocusedNode();
            this.updateTreeModel();
        }
    }

    private mapNodes(items: DataItem[]) {
        const newItems: any[] = [];
        items.forEach(item => {
            // We are comparing the entire data as we might change for instance
            // the status of the object and we need to recreate it.
            const existingItem = this.nodesToDisplay.find(x => {
                if (x.dataItem.data) {
                    return x.dataItem.data === item.data;
                } else if (x.dataItem) {
                    return x.dataItem === item;
                } else {
                    return x === item;
                }

            });
            if (existingItem) {
                newItems.push(existingItem);
            } else {
                if (item instanceof HierarchicalDataItem) {
                    const wrapper = this.constructHierarchy(item);
                    newItems.push(wrapper);
                } else {
                    const wrapper: TreeItem = {
                        dataItem: item,
                        hasChildren: item.data && item.data.hasOwnProperty(Properties.HAS_CHILDREN) && item.data[Properties.HAS_CHILDREN]
                    };
                    newItems.push(wrapper);
                }
            }
        });
        this.nodesToDisplay = newItems;
    }

    private constructHierarchy(item: HierarchicalDataItem): TreeItem {
        const wrapper: TreeItem = {
            id: item.key,
            dataItem: item,
            hasChildren: item.hasChildren
        };

        if (item.children.length > 0) {
            wrapper.children = item.children.map((child) => {
                return this.constructHierarchy(child);
            });
        }

        return wrapper;
    }

    onTreeNodePressEnter(node: TreeNode) {
        this.treeNodePressEnter.emit(node);
    }

    onTreeNodeClicked(node: TreeNode) {
        this.treeNodeClicked.emit(node);
    }

    onRemoveNode(node: TreeNode) {
        this.removeNode.emit(node);
    }

    handleViewNode(node: TreeNode) {
        this.onViewNode.emit(node);
    }

    onDataUpdate(): void {
        this.dataUpdate.emit();
    }

    onReorderNodes(nodes: any): void {
        this.reorderNodes.emit(nodes);
    }

    onMoveNode(event): void {
        this.moveNode.emit(event);
    }

    onInitialized(): void {
        this.initialized.emit();
    }

    onCheckBoxClicked(node: TreeNode): void {
        this.checkBoxClicked.emit(node);
    }

    onExpandedNodesChanged(ev: ExpandedNodesChangedEvent): void {
        const event = ev.event;

        if (this.config.treeProperties && this.config.treeProperties.getChildren &&
            !event.isExpanded && event.node.children) {
            event.node[CACHED_ITEMS_NAME] = event.node.children.map(x => x.data);
            event.node.children = null;
        }

        this.expandedNodesChanged.emit(ev.expandedNodeIds);
    }

    onVisibleNodesCountChanged(visibleNodesCount: number): void {
        this.visibleNodesCountChanged.emit(visibleNodesCount);
    }

    updateTreeModel(): void {
        this.innerTree.updateTreeModel();
    }

    selectAndActivateNodeById(id: string) {
        this.innerTree.selectAndActivateNodeById(id);
    }

    showHiddenNodes(): void {
     this.innerTree.showHiddenNodes();
    }

    onTreeNodeRemoveClicked(node: TreeNode, event: Event) {
        this.innerTree.onTreeNodeRemoveClicked(node, event);
    }

    onViewDataClicked(node: TreeNode, event: Event): void {
        this.innerTree.onViewDataClicked(node, event);
    }

    generateUserInitials(node: TreeNode): string {
        let initials = "";
        if (node.displayField) {
            initials = node.displayField.split(" ", 3).map((s) => { return s.charAt(0); }).join("");
        }
        return initials;
    }

    getFocusNodeValue(): any {
        return this.innerTree.getFocusNodeValue();
    }

    getSelectedNodeIds(): string[] {
        return this.innerTree.getSelectedNodeIds();
    }

    selectAllNodes(excludedNodeIds?: string[]) {
        return this.innerTree.selectAllNodes(excludedNodeIds);
    }

    clearAllSelectedNodes() {
        this.innerTree.clearAllSelectedNodes();
    }

    clearFocusedNode(): void {
        this.innerTree.clearFocusedNode();
    }

    focusTree(): void {
        this.innerTree.focusTree();
    }

    focusOutTree(): void {
        this.innerTree.focusOutTree();
    }

    focusNextNode(): void {
        this.innerTree.focusNextNode();
    }

    focusPreviousNode(): void {
        this.innerTree.focusPreviousNode();
    }

    selectCurrentNode(): void {
        this.innerTree.selectCurrentNode();
    }

    expandAndSelect(nodeModel: TreeNodeModel, pathProperty: string) {
        this.innerTree.expandAndSelect(nodeModel, pathProperty);
    }

    expandAllNodes() {
        this.innerTree.expandAllNodes();
    }

    getCustomComponentData(node): ComponentData {
        const componentData = this.treeNodeComponentCompositeProvider.getComponentData(this.config.customComponentOriginatingFeature, this.config.customComponentEntitySet);
        if (!componentData) {
            return null;
        }

        const data = node;

        componentData.properties = {
            item : DataItem.from(data, this.metaDataStore.getEntity(this.config.customComponentEntitySet), data.provider, this.route.snapshot.parent.queryParams[QUERY_PARAMS.CULTURE])
        };

        return componentData;
    }

    getNodeById(id: string): any {
        return this.innerTree.getNodeById(id);
    }

    getNodeBy(predicate: any, startNode?: any): any {
        return this.innerTree.getNodeBy(predicate, startNode);
    }

    getIsNodeExpandedById(id: string): boolean {
        return this.innerTree.getIsNodeExpandedById(id);
    }

    getIsNodeActiveById(id: string): boolean {
        return this.innerTree.getIsNodeActiveById(id);
    }

    getActiveNodeIds(): IDTypeDictionary {
        return this.innerTree.getActiveNodeIds();
    }

    getIsSelectedById(id: string): boolean {
        return this.innerTree.getIsSelectedById(id);
    }

    setExpandedNode(id: string, expanded = true) {
        this.innerTree.setExpandedNode(id, expanded);
    }

    getExpandedNodes(): IDTypeDictionary {
        return this.innerTree.getExpandedNodes();
    }

    setHiddenNodeById(id: string, hide: boolean) {
        this.innerTree.setHiddenNodeById(id, hide);
    }

    setExpandedNodes(ids: IDTypeDictionary) {
        this.innerTree.setExpandedNodes(ids);
    }

    private mapCustomComponentData(): void {
        this.nodes.forEach((node) => {
            const customData = this.getCustomComponentData(node);

            if (customData) {
                node.customComponentData = customData;
            }
        });
    }
}

export interface TreeItem {
    id?: string;
    hasChildren?: boolean;
    isHeading?: boolean;
    children?: TreeItem[];
    dataItem?: DataItem;
}

export interface TreeConfig extends TreeConfigBase {
    statusText?: boolean;
    previewUrl?: boolean;
    hideExtensions?: boolean;
    customComponentOriginatingFeature?: TreeNodeComponentFeatures;
    customComponentEntitySet?: string;
}
