export const DEFAULT_URL_KEY = "default";

@Injectable()
export class ModalWindowService extends AuxServiceBase<DialogData> {
    private states: DialogState[] = [];

    constructor(router: Router, @Inject(WINDOW_TOKEN) private windowProvider: Window, private scrollService: ScrollService) {
        super(router);
    }

    get isDialogOpened() {
        return this.active;
    }

    /**
     * @deprecated Use show instead
     */
    open(route: ActivatedRoute, urlKey: string = DEFAULT_URL_KEY): void {
        this.show(urlKey, route.parent);
    }

    show(routeKey: string, auxParentRoute: ActivatedRoute, queryParams?: Params, previousWindow: Window = this.windowProvider): void {
        this.states.push({
            window: previousWindow,
            topOffsetPosition: this.getDocumentOffsetPosition(previousWindow)
        });

        this.scrollService.scrollToTop(false);
        super.show(routeKey, auxParentRoute, queryParams);
    }

    /**
     * @deprecated Use hide instead
     */
    close(route: ActivatedRoute = null): Promise<boolean> {
        return this.hide(route);
    }

    hide(auxParentRoute: ActivatedRoute = null, closeAll: boolean = false): Promise<boolean> {
        return super.hide(auxParentRoute, closeAll).then((data) => {
            const state = this.states.pop();
            if (state && state.topOffsetPosition >= 0) {
                this.scroll(state.topOffsetPosition, state.window);
            }
            return data;
        });
    }

    setMapping(data: DialogData, urlKey: string = DEFAULT_URL_KEY): void {
        super.setData(urlKey, data);
    }

    getMapping(urlKey: string = DEFAULT_URL_KEY): DialogData {
        return super.getData(urlKey);
    }

    /**
     * Opens a modal confirmation window.
     *
     * @param {ActivatedRoute} route The route to navigate to.
     *
     * @memberof {ModalWindowService}
     */
    openModalConfirmation(route: ActivatedRoute, properties: ModalComponentSettings, dataItem: DataItem, routeKey: string = SIDEBAR_ROUTES.DEFAULT, previousWindow?: Window) {
        const componentData: ComponentData = {
            type: ModalConfirmationComponent,
            properties: {
                icon: properties.icon,
                title: properties.detailedTitle || properties.title,
                description: properties.description,
                descriptionAllowHtml: properties.descriptionAllowHtml,
                warning: properties.warning,
                parameters: properties.parameters,
                contextParameters: properties.contextParameters,
                action: properties.action,
                entitySet: dataItem ? dataItem.metadata.setName : null,
                itemTitle: this.getTitle(properties, dataItem),
                formValidators: properties.formValidators,
                hideItemTitle: properties.hideItemTitle,
                mainFormSize: properties.mainFormSize,
                innerFormLook: properties.innerFormLook,
                dataItem,
                counter: properties.counter
            }
        };

        const dialogData = new DialogData(componentData, properties.doneCallback, properties.buttons, "-prompt");
        dialogData.disableUserInteractionOnLoading = properties.disableUserInteractionOnLoading;

        this.setMapping(dialogData, routeKey);
        this.show(routeKey, route, undefined, previousWindow);
    }

    openModalSelector<T>(route: ActivatedRoute, settings: ModalSelectorSettings<T>, routeKey: string = SIDEBAR_ROUTES.DEFAULT) {
        const componentData: ComponentData = {
            type: ModalSelectorComponent,
            properties: {
                settings: settings
            }
        };

        const dialogData = new DialogData(componentData, settings.doneCallback);
        dialogData.heading = settings.heading;
        this.setMapping(dialogData, routeKey);
        this.show(routeKey, route.parent, undefined, settings.window);
    }

    ensureRouteState(url: string): void {
        const index = this.routeStack.findIndex((stackData) => stackData.key === url);
        if (index < 0 || index === this.routeStack.length - 1) return;

        const toHide = this.routeStack.length - index - 1;
        for (let cnt = 0; cnt < toHide; cnt++) {
            this.hide();
        }
    }

    protected getSettings(): AuxSettings {
        return {
            outletName: "dialog",
            prefix: "confirm"
        };
    }

    private scroll(position: number, window: Window): void {
        if (position >= 0) {
            this.scrollService.scrollTo(position, undefined, undefined, window);
        }
    }

    private getDocumentOffsetPosition(window: Window): number {
        const doc = window.document.documentElement;
        // we need Top position for now, but in the future left position may be included
        const topPosition = (window.pageYOffset || doc.scrollTop) - (doc.clientTop || 0);
        // let scrollPositionLeft = (this.windowProvider.pageXOffset || doc.scrollLeft) - (doc.clientLeft || 0);

        return topPosition;
    }

    private getTitle(properties: ModalComponentSettings, dataItem: DataItem): string {
        let title = null;
        if (!properties.hideItemTitle) {
            if (properties.contextParameters) {
                const titleParam = properties.contextParameters[CONTEXT_PARAMETERS.currentTitle];
                if (titleParam) {
                    title = titleParam;
                }
            }

            if (!title && dataItem) {
                title = dataItem.title;
            }
        }

        return title;
    }
}

/**
 * @ExposedInApi {DialogDataBase} DialogData v1/selectors/dialog-data.d.ts
 */
export interface DialogDataBase {
    componentData: ComponentData,
    commands: CommandModelBase[]
}

export interface ModalHeading {
    title: string,
    description?: {
        text: string;
        warning?: boolean;
    },
    subTitle?: string;
    superScript?: string;
}

export class DialogData {
    public heading?: ModalHeading = { title: null };
    public hasTopToolbar?: boolean = false;
    public headComponentData: ComponentData;
    public key?: string;
    constructor(
        public componentData: ComponentData,
        public doneCallback: DoneCallback = null,
        public buttons: Array<Button> = [],
        public contentClass: string = null,
        public buttonClass: string = null,
        public showButtonsOnInit: boolean = true,
        public toolbarData: ComponentData = null,
        public headButtons: (Button | ButtonGroup)[] = null,
        public hideStickyContent: boolean = false,
        public disableUserInteractionOnLoading: boolean = false,
        public hideCloseButton: boolean = false,
        public isModalClosable: boolean = true,
        public stickWithDelay: boolean = true,
        public stickyDisabled: boolean = false,
        public alwaysSticky: boolean = false,
        public hideBackToTopButton: boolean = false) {
    }
}

export class Button extends LoadingButton {
    constructor(
        public handlers: ButtonHandlers,
        public content: string,
        public css: string,
        public name: string = stringConstants.EMPTY_STRING,
        public loadIcon: string = stringConstants.EMPTY_STRING) {
            super();
            if (this.handlers == null) {
                this.handlers = {
                    click: () => null
                };
            }

            this.loader = new ReplaySubject<string>(1);
            this.disabled = new ReplaySubject<boolean>(1);
            this.checked = new ReplaySubject<boolean>(1);
        }

        loader: ReplaySubject<string>;
        disabled: ReplaySubject<boolean>;
        checked: ReplaySubject<boolean>;
    }

interface ButtonHandlers {
    click: (data: ClickData) => ClickResult | Observable<ClickResult>;
}

export interface ClickData {
    event: Event;
    component: any;
}

export class ClickResult {
    constructor(public data: any = null, public isSuccessful: boolean, public hasErrors: boolean = false, public load: boolean = true) { }
}

export class ConfirmButton extends Button {
    constructor(public content: string = "Done", clickHandler?: (data: ClickData) => ClickResult | Observable<ClickResult>, css: string = "action large", name: string = stringConstants.EMPTY_STRING, loadIcon: string = "transparent") {
        super(null, content, css, name, loadIcon);
        if (clickHandler) {
            this.handlers.click = clickHandler;
        } else {
            this.handlers.click = () => new ClickResult(true, true);
        }
    }
}

export class CancelButton extends Button {
    constructor(public content: string = "Cancel", clickHandler?: (data: ClickData) => ClickResult | Observable<ClickResult>) {
        super(null, content, "large");

        if (clickHandler) {
            this.handlers.click = clickHandler;
        } else {
            this.handlers.click = () => new ClickResult(false, true);
        }
    }
}

export class DeleteButton extends Button {
    constructor(public content: string = "Delete", clickResultData: any = true, css: string = "delete large") {
        super({ click: () => new ClickResult(clickResultData, true) }, content, css);
    }
}

export interface ClosingContext {
    type: ClosingContextType;
    component: any;
    data?: any;
}

export enum ClosingContextType {
    ButtonClicked,
    CloseClicked,
    DoneCalled,
    InitFailure
}

/**
 * Components that implement the interface have additional functionality relevant only when
 * they are created in the ModalWindowService
*/
export interface CloseModalCallback {
    /**
     * Passes the done callback from the ModalWindowsService when the component is initialized. When doneCallback is called it
     * will close the modal window component that hosts this component.
     * The data parameter can be used to pass any data to the modal component that is hosting
    */
    setCloseModalCallback (closeModalCallback: (data: any) => void): void;
}

export interface CanCloseModal {
    canCloseCallback: (context: ClosingContext) => boolean | Observable<boolean>;
}

export interface ModalComponentSettings {
    title: string;
    detailedTitle?: string;
    icon: string;
    description: string;
    descriptionAllowHtml?: boolean;
    warning?: string;
    buttons: Array<Button>;
    doneCallback?: DoneCallback;
    parameters?: Array<any>;
    contextParameters?: Array<any>;
    action: string;
    formValidators?: ValidatorFn | ValidatorFn[];
    hideItemTitle?: boolean;
    disableUserInteractionOnLoading?: boolean;
    mainFormSize?: ModalMainFormSize;
    innerFormLook?: string;
    counter?: number;
}

interface DialogState {
    window: Window,
    topOffsetPosition: number
}
