import { of as observableOf,  Observable } from "rxjs";
import { SelectorBase } from "../selector-base";
import { SelectorItem } from "../selector-item";
import { LoadingState } from "../../../../../../../shared/rxjs-extensions/delayEmission";
import { toLoadingState } from "../../../../../../../shared/rxjs-extensions";
import { Logger } from "../../../../../../../shared/services/logger-source/logger";

export class LanguageSelector extends SelectorBase<SelectorItem> {
    constructor(
        logger: Logger,
        private initialCulture: string) {
        super(logger);
    }

    protected setSelectedItem(value: SelectorItem) {
        this.context.selectedCulture = value;
        super.setSelectedItem(value);
    }

    onInit(): Observable<LoadingState> {
        const selectedSite = this.context.selectedSite;
        this.items = selectedSite.cultures;
        const selectedCulture = this.initialCulture || this.context.selectedCulture?.value;
        // after the first execution of OnInit, the intial culture should no longer be valid
        this.initialCulture = null;

        // it's possible that the site does not have the selected culture, in the case the site is changed
        const siteCulture = selectedCulture ? this.items.find(i => i.value === selectedCulture) : null;
        const selectedItem = siteCulture || selectedSite.defaultCulture || selectedSite.cultures[0];
        this.setSelectedItem(selectedItem);
        return observableOf({})
            .pipe(toLoadingState());
    }
}
