import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, EventEmitter, Inject, Input, OnInit, Output, QueryList, ViewChildren, ViewEncapsulation } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData, MarkupSection } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../../../../common-constants";
import { FieldSectionModel } from "../../../../../services/fieldSection.model";
import { cloneObject } from "../../../../../utils";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { SelectorConstants } from "../../../../html/selector-constants";
import { Button, CancelButton, ConfirmButton, DialogData, ModalWindowService, ClosingContext } from "../../../services/modal-window.service";
import { LOCAL_STORAGE, StorageService } from "../../../services/storage.service";
import { FIELDS_CHANGE_SERVICE_TOKEN, FieldChangeService } from "../../services/field-change/field-change.service";
import { FieldTypes } from "../../services/fields-registry";
import { MirrorService } from "../../services/mirror.service";
import { EditableFieldsComponent, ValueChange } from "../editable-fields/editable-fields.component";
import { AddManyComponent } from "./add-many.component";
import { FieldModel } from "../../../../../services/field.model";
import { getTooltip } from "../../../../../utils";
import { PencilButtonSettings } from "../../../../../../../fields/pencil-button/pencil-button-field.component";
import { ContentLinkInputModel } from "../../../../html/tools/create-link/link-insert-field/helpers/content-link-input-model";

const DRAGGED_ROW_CLASS = "-dragged";

@Component({
    selector: "sf-editable-table",
    templateUrl: "./editable-table.component.html",
    encapsulation: ViewEncapsulation.None
})
export class EditableTableComponent extends EditableFieldsComponent implements OnInit, AfterViewInit {
    @Input() allowModify: boolean;
    @Input() allowAddRow: boolean;
    @Input() allowRemoveRow: boolean;
    @Input() reorderable: boolean;
    @Input() selectable: boolean;
    @Input() multipleSelect: boolean;
    @Input() predefinedLists: { [key: string]: string[] };
    @Input() defaultSection: FieldSectionModel;
    @Input() defaultValue: any;
    @Input() allowAddSubRow: boolean;
    @Input() look: string;
    @Input() multilineTitle: boolean;
    @Input() allowEmptyState: boolean;
    @Input() hideRowsIfEmpty: boolean;

    @Output() private nodesReordered: EventEmitter<any> = new EventEmitter<any>();
    @ViewChildren("checkbox") private checkboxes: QueryList<ElementRef>;
    private defaultSectionName: string;
    private lastSectionIndex: number = -1;
    private selectedRadioName: string;
    private draggedSection: FieldSectionModel;
    tableClass: string;

    constructor(
        @Inject(WINDOW_TOKEN) protected window: Window,
        protected mirrorService: MirrorService,
        protected detector: ChangeDetectorRef,
        @Inject(LOCAL_STORAGE) protected storage: StorageService,
        @Inject(FIELDS_CHANGE_SERVICE_TOKEN) protected fieldChangeHandlers: FieldChangeService[],
        private modalService: ModalWindowService,
        private route: ActivatedRoute) {
        super(window, mirrorService, detector, storage, fieldChangeHandlers);
    }

    ngOnInit() {
        this.generateTableLook();
        this.defaultSectionName = this.defaultSection ? this.defaultSection.settings.name : "";
        if (this.defaultValue && Object.values(this.defaultValue).length > 0) {
            if (Array.isArray(this.defaultValue)) {
                this.defaultValue.forEach((sectionObject, index) => {
                    this.addSection(index.toString(), sectionObject);
                });
            } else {
                const sectionNames = Object.getOwnPropertyNames(this.defaultValue);
                sectionNames.forEach(name => {
                    const sectionObject = this.defaultValue[name];
                    this.addSection(name.toString(), sectionObject);
                });
            }
        } else if (this.defaultSection && !this.hideRowsIfEmpty) {
            this.addSection("0", null, false, true);
        }

        this.ngOnChanges({ fieldSections: { currentValue: this.fieldSections } });
    }

    ngAfterViewInit() {
        super.ngAfterViewInit();
        this.updateCheckboxesDefaultValues();
    }

    addRow() {
        this.addSection((this.lastSectionIndex + 1).toString(), {}, true, true);
        this.ngOnChanges({ fieldSections: { currentValue: this.fieldSections } });
    }

    removeRow(sectionIndex) {
        const section = this.fieldSections[sectionIndex];
        const sectionTitle = section.settings.title;
        const sectionName = section.settings.name;

        // remove from value
        const changeObj: ValueChange = {
            key: null,
            value: null,
            sectionTitle: sectionTitle,
            sectionName: sectionName,
            isSectionRemoved: true
        };
        this.fieldChange.emit(changeObj);

        // remove from form
        const keys = section.fields.map(f => f.key);
        this.removeFormControls(keys);

        // remove from UI
        if (sectionIndex > -1) {
            this.fieldSections.splice(sectionIndex, 1);
        }
    }

    generateTableLook() {
        this.tableClass = "sf-field__table -sf-mt-3xs";

        if (this.look) {
            this.tableClass += " -" + this.look.split(" ").join(" -");
        }
    }

    getHeaderTooltip(field: FieldModel): MarkupSection[] {
        return getTooltip(field, field.value);
    }

    addSubRow(section: FieldSectionModel, sectionIndex: number) {
        // remove the horizontal line for the current row
        section.settings.insertHorizontalRule = false;

        // create new row based on the current one and set the horizontal line for it
        let newSection = new FieldSectionModel();
        newSection = Object.assign({}, section);
        newSection.settings = Object.assign({}, section.settings);
        newSection.settings.name = section.settings.name;
        newSection.settings.insertHorizontalRule = true;
        newSection.settings.title = stringConstants.EMPTY_STRING;
        newSection.fields = [];
        section.fields.forEach(f => {
            const field = Object.assign({}, f);
            field.settings = Object.assign({}, f.settings);
            field.value = null;

            const propIndex = f.key.replace(f.settings.friendlyTitle, "");
            field.key = field.settings.friendlyTitle + (Number(propIndex) + 1);
            field.settings.key = field.key;

            newSection.fields.push(field);
        });

        // add new row just after the current one
        this.fieldSections.splice(sectionIndex + 1, 0, newSection);
        this.ngOnChanges({ fieldSections: { currentValue: this.fieldSections } });
    }

    removeSubRow(section: FieldSectionModel, sectionIndex: number) {
        const nextSection = this.fieldSections[sectionIndex + 1];
        nextSection.settings.title = section.settings.title;

        this.removeRow(sectionIndex);
    }

    onChange(value, key, section) {
        super.onChange(value, key, section);
        section.fields.find(f => f.key === key).value = value;
    }

    onSelectionChange(checked: boolean, fieldKey: string, section: FieldSectionModel) {
        if (this.multipleSelect || !checked) {
            super.onChange(checked, fieldKey, section);
        } else if (!this.multipleSelect && this.selectedRadioName === fieldKey) {
            this.resetRadioInput(fieldKey, section);
            this.selectedRadioName = null;
        } else {
            this.fieldSections.forEach(s => {
                if (s.settings.name === section.settings.name) {
                    super.onChange(checked, fieldKey, section);
                    this.selectedRadioName = fieldKey;
                } else {
                    this.resetRadioInput(fieldKey.replace(section.settings.name, s.settings.name), s);
                }
            });
        }
    }

    dragstart(ev: DragEvent, section: FieldSectionModel) {
        (ev.target as HTMLElement).classList.add(DRAGGED_ROW_CLASS);

        this.draggedSection = section;
        ev.stopPropagation();
    }

    dragend(ev: DragEvent) {
        (ev.target as HTMLElement).classList.remove(DRAGGED_ROW_CLASS);
    }

    dragover(ev: Event, section: FieldSectionModel) {
        ev.preventDefault();

        const draggedSectionIndex = this.fieldSections.indexOf(this.draggedSection);
        const targetSectionIndex = this.fieldSections.indexOf(section);
        if (targetSectionIndex !== draggedSectionIndex) {
            this.fieldSections.splice(draggedSectionIndex, 1);
            this.fieldSections.splice(targetSectionIndex, 0, this.draggedSection);
            this.nodesReordered.emit(this.fieldSections);
        }
    }

    addMany() {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.DONE),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const componentData: ComponentData = {
            type: AddManyComponent,
            properties: {
                predefinedLists: this.predefinedLists
            }
        };

        const dialogData = new DialogData(componentData, (context: ClosingContext) => {
            const value = (context.component as AddManyComponent).value;
            if (value) {
                const newChoices = value.split(stringConstants.NEWLINE);
                newChoices.forEach(x => {
                    const value = {};
                    this.defaultSection.fields.forEach(f => {
                        const propName = f.key.replace(this.defaultSectionName, "");
                        value[propName] = x;
                    });
                    this.addSection((this.lastSectionIndex + 1).toString(), value, false, true);
                });
                this.ngOnChanges({ fieldSections: { currentValue: this.fieldSections } });
            }
        }, buttons, null);
        dialogData.heading = { title: "Add many options" };

        this.modalService.setMapping(dialogData, "addMany");
        this.modalService.open(this.route, "addMany");
    }

    private resetRadioInput(fieldKey: string, section: FieldSectionModel) {
        super.onChange(false, fieldKey, section);
        this.checkboxes.find(element => element.nativeElement.attributes["data-sf-section-name"].value === section.settings.name)
            .nativeElement.checked = false;
    }

    private addSection(sectionNameSufix: string, sectionObject?: any, isNewRow: boolean = false, triggerChanges: boolean = false) {
        let newSection = new FieldSectionModel();
        newSection = Object.assign({}, this.defaultSection);
        newSection.settings = Object.assign({}, this.defaultSection.settings);
        newSection.settings.name = this.defaultSectionName + sectionNameSufix;
        newSection.fields = [];
        this.defaultSection.fields.forEach(f => {
            const field = Object.assign({}, f);
            const propName = f.key.replace(this.defaultSectionName, "");
            field.settings = Object.assign({}, f.settings);
            const defaultValue = field.settings.defaultValue;
            const actualValue = sectionObject ? sectionObject[propName] : null;

            // UX requirement: When adding a new section with dropdown we want to populate the default value if exists.
            // For the other fields if they have a default value we don't want to populate it just to be empty.
            if (field.selector === FieldTypes.choiceDropDown || field.selector === FieldTypes.choiceChip) {
                field.value = actualValue || field.settings.defaultValue;
            } else if (field.selector === FieldTypes.pencilButton && isNewRow) {
                const pencilSettings = field.settings as PencilButtonSettings;
                field.value = pencilSettings.initialValue;
            } else if ((field.selector === FieldTypes.contentTypeSelector || field.selector === FieldTypes.fieldSelector) && isNewRow) {
                field.value = [];
            } 
            else {
                field.settings.defaultValue = isNewRow ? null : defaultValue;
                field.value = this.computeFieldValue(isNewRow, actualValue, field);
            }

            if (field.settings.conditionalRule) {
                this.adjustConditionsFieldNames(field, sectionNameSufix);
            }

            field.key = newSection.settings.name + propName;
            field.settings.key = newSection.settings.name + propName;

            if (triggerChanges) {
                super.onChange(field.value, field.key, newSection);
            }

            newSection.fields.push(field);
        });
        this.fieldSections.push(newSection);
        this.lastSectionIndex++;
    }

    private computeFieldValue(isNewRow: boolean, actualValue: any, field: FieldModel) {
        if (isNewRow) {
            if (field.selector == FieldTypes.linkInsert) {
                const emptyValue = new ContentLinkInputModel();
                emptyValue.isUrlRequired = field.settings.required;                
                return emptyValue;
            } else {
                return null;
            }
        }

        if (field.selector == FieldTypes.linkInsert && (actualValue === null || !(actualValue instanceof ContentLinkInputModel))) {
            const emptyValue = new ContentLinkInputModel();
            emptyValue.isUrlRequired = field.settings.required;
            return emptyValue;
        }

        if (field.settings.emptyValues && field.settings.emptyValues.includes(actualValue)) {
            return field.settings.defaultValue;
        }

        else if (field.selector === FieldTypes.date) {
            return new Date(actualValue);
        }

        return actualValue;
    }

    private adjustConditionsFieldNames(field: FieldModel, sectionNameSufix: string) {
        field.settings.conditionalRule = cloneObject(field.settings.conditionalRule);
        field.settings.conditionalRule.conditions.forEach(x => {
            x.fieldName = x.fieldName.replace(this.defaultSectionName, this.defaultSectionName + sectionNameSufix);
        });
    }

    private updateCheckboxesDefaultValues() {
        this.checkboxes.forEach(element => {
            let sectionName = element.nativeElement.attributes["data-sf-section-name"].value;
            sectionName = sectionName.replace(this.defaultSectionName, "");
            element.nativeElement.checked = this.defaultValue[sectionName]?.Selected;
        });
    }

    protected getFieldChangeId(): string {
        return this.defaultSection?.settings?.name;
    }
}
