import { Component, OnInit, QueryList, ViewChildren } from "@angular/core";
import { FormGroup, FormControl } from "@angular/forms";
import { ActivatedRoute } from "@angular/router";
import { FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { CompositeFieldSettings } from "../../../shared/services/composite-field.settings";
import { FormFieldWrapperComponent } from "../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Button, ConfirmButton, CancelButton, DialogData, ModalWindowService } from "../../../shared/services/modal-window.service";
import { SelectorConstants } from "../../../html/selector-constants";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { FieldModel } from "../../../../services/field.model";
import { stringConstants } from "../../../../common-constants";
import { PageSelectorComponent, WEB_ADDRESS_TAB_TITLE } from "../page-selecotr-component/page-selector.component";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { PAGES } from "../../services/hierarchical-pages.service";
import { EntityData } from "../../../content/dynamic-modules/interfaces";
import { cloneObject } from "../../../../utils";
import { StatusType } from "../../../../../../fields/field-status";
import { DEFAULT_MARKUP_KEY, MarkupSection, TextSection, SectionTypes } from "@progress/sitefinity-component-framework";
import { FieldBase } from "../../../../../../fields/field-base";

export const NAVIGATION_OPTIONS_PROPERTIES = {
    SHOW_IN_NAVIGATION: "ShowInNavigation",
    PAGE_TYPE: "PageType",
    REDIRECT_PAGE: "RedirectPage"
};

export const PAGE_COMPUTED_PROPERTIES = {
    MARKETING: "Marketing"
};

export const PAGE_TYPE_OPTIONS = {
    STANDARD: "Standard",
    GROUP: "Group",
    REDIRECT: "Redirect"
};

const PAGE_TYPE_FIELDS = {
    IS_GROUP: "isGroup",
    IS_REDIRECT: "isRedirect"
};

export const REDIRECT_PAGE_VALIDATION = "Select a redirect page";

@Component({
    selector: "sf-navigation-options-composite-field",
    templateUrl: "./navigation-options.composite.component.html"
})
export class NavigationOptionsCompositeComponent extends FieldBase<CompositeFieldSettings> implements OnInit {
    form: FormGroup = new FormGroup({});

    @ViewChildren(FormFieldWrapperComponent) protected fields: QueryList<FormFieldWrapperComponent>;

    public showPageSelector: boolean;
    public groupFieldData: FieldModel;
    public redirectFieldData: FieldModel;
    public selectedRedirectPage: string = stringConstants.EMPTY_STRING;
    public isRedirectPageSelected: boolean = false;
    public errorMessages: string[] = [];

    private selectedUrl: string = stringConstants.EMPTY_STRING;
    private selectedItem: any;
    private shouldOpenInNewWindow: boolean = false;

    constructor(private modalService: ModalWindowService,
                private route: ActivatedRoute,
                private dynamicItemService: DynamicItemService) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.initialize();
        this.initializeForm();
    }

    writeValue(updatedValues: NavigationOptionsData | any) {
        if (!updatedValues) {
            return;
        }

        // we do not want to change the value
        let compositeValue = cloneObject(this.getValue());
        if (compositeValue === null || !Object.keys(compositeValue).length) {
            compositeValue = {};
        }

        const result = Object.assign({}, compositeValue, updatedValues);

        if (result.hasOwnProperty(PAGE_TYPE_FIELDS.IS_GROUP)) {
            let value = result[PAGE_TYPE_FIELDS.IS_GROUP];
            if (value) {
                this.groupFieldData.value = true;
                value = PAGE_TYPE_OPTIONS.GROUP;
            } else {
                this.groupFieldData.value = false;
                value = this.redirectFieldData.value === true ? PAGE_TYPE_OPTIONS.REDIRECT : PAGE_TYPE_OPTIONS.STANDARD;
            }

            result[NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE] = value;
            delete result[PAGE_TYPE_FIELDS.IS_GROUP];
        }

        if (result.hasOwnProperty(PAGE_TYPE_FIELDS.IS_REDIRECT)) {
            this.showPageSelector = result[PAGE_TYPE_FIELDS.IS_REDIRECT];

            let value = result[PAGE_TYPE_FIELDS.IS_REDIRECT];
            if (value) {
                this.redirectFieldData.value = true;
                value = PAGE_TYPE_OPTIONS.REDIRECT;
            } else {
                this.redirectFieldData.value = false;
                this.selectedRedirectPage = stringConstants.EMPTY_STRING;
                this.isRedirectPageSelected = false;
                value = this.groupFieldData.value === true ? PAGE_TYPE_OPTIONS.GROUP : PAGE_TYPE_OPTIONS.STANDARD;
            }

            result[NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE] = value;
            delete result[PAGE_TYPE_FIELDS.IS_REDIRECT];
        }

        super.writeValue(result);
    }

    openPageSelection() {
        const componentData: ComponentData = {
            type: PageSelectorComponent,
            properties: {
                culture: this.settings.culture,
                selected: this.selectedItem ? [this.selectedItem] : [],
                parentId: this.settings.itemId,
                selectedUrl: this.selectedUrl,
                shouldOpenInNewWindow: this.shouldOpenInNewWindow,
                overrideSelectorConfig: true
            }
        };

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.DONE),
            new CancelButton(SelectorConstants.CANCEL)
        ];
        const dialogData = new DialogData(componentData, (context) => this.onDone(context), buttons, null);

        this.modalService.setMapping(dialogData);
        this.modalService.open(this.route);
    }

    validate() {
        if (this.redirectFieldData.value === true && this.selectedRedirectPage === stringConstants.EMPTY_STRING) {
            this.errorMessages.push(REDIRECT_PAGE_VALIDATION);
            this.emitStatus({type: StatusType.Error});
            return false;
        } else {
            this.errorMessages.length = 0;
            this.emitStatus({type: StatusType.ErrorCleared});
            return true;
        }
    }

    private onDone(context: any) {
        if (!context.data || !context.data.data) {
            return;
        }

        let redirectPageData: RedirectPageData;

        if (context.component.selectedTab && context.component.selectedTab === WEB_ADDRESS_TAB_TITLE) {
            if (context.component.selectedUrl) {
                redirectPageData = {
                    NodeId: stringConstants.DEFAULT_GUID,
                    OpenInNewWindow: context.component.shouldOpenInNewWindow,
                    ProviderName: null,
                    RedirectUrl: context.component.selectedUrl
                };

                this.selectedRedirectPage = context.component.selectedUrl;
                this.selectedUrl = context.component.selectedUrl;
                this.shouldOpenInNewWindow = context.component.shouldOpenInNewWindow;

                this.isRedirectPageSelected = true;
                this.validate();
            }
        } else {
            if (context.component.selected[0]) {
                redirectPageData = {
                    NodeId: context.component.selected[0].Id,
                    OpenInNewWindow: false,
                    ProviderName: null,
                    RedirectUrl: stringConstants.EMPTY_STRING
                };

                this.selectedRedirectPage = context.component.selected[0].Title;
                this.selectedUrl = stringConstants.EMPTY_STRING;
                this.shouldOpenInNewWindow = false;

                this.isRedirectPageSelected = true;
                this.validate();
            }
        }

        const redirectData: NavigationOptionsData = {
            RedirectPage: redirectPageData
        };

        this.writeValue(redirectData);
    }

    private initializeForm() {
        Object.keys(this.settings.innerFields).forEach((fieldName) => {
            const fieldData = this.settings.innerFields[fieldName];
            if (fieldData !== null) {
                const value = fieldData.value;
                const formControl = new FormControl(value);
                this.form.setControl(fieldData.key, formControl);

                if (fieldName === NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE) {
                    fieldData.settings.tooltipModels = this.getTooltip("This page doesn't have content and redirects to the first subpage.");

                    this.groupFieldData = new FieldModel({
                        key: PAGE_TYPE_FIELDS.IS_GROUP,
                        settings: fieldData.settings,
                        selector: FieldTypes.choiceYesNo,
                        registration: fieldData.registration,
                        value: value === PAGE_TYPE_OPTIONS.GROUP
                    });

                    const groupFormControl = new FormControl(this.groupFieldData.value);
                    this.form.setControl(this.groupFieldData.key, groupFormControl);
                }

                if (fieldName === NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE) {
                    fieldData.settings.tooltipModels = this.getTooltip("This page doesn't have content and redirects to another page in the website or to an external URL.");

                    this.redirectFieldData = new FieldModel({
                        key: PAGE_TYPE_FIELDS.IS_REDIRECT,
                        settings: fieldData.settings,
                        selector: FieldTypes.choiceYesNo,
                        registration: fieldData.registration,
                        value: this.settings.innerFields[NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE].value === PAGE_TYPE_OPTIONS.REDIRECT
                    });

                    const redirectFormControl = new FormControl(this.redirectFieldData.value);
                    this.form.setControl(this.redirectFieldData.key, redirectFormControl);
                    this.showPageSelector = this.redirectFieldData.value;
                }
            }
        });
    }

    private getTooltip(tooltipText: string) {
        const section: TextSection = { Type: SectionTypes.Text, Chunks: [{ Value: tooltipText, Presentation: [] }] };
        return new Map<string, MarkupSection[]>([[DEFAULT_MARKUP_KEY, [section]]]);
    }

    private initialize() {
        const redirectValue = this.settings.innerFields[NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE].value;
        if (redirectValue && (redirectValue["NodeId"] !== stringConstants.DEFAULT_GUID || redirectValue["RedirectUrl"] !== stringConstants.EMPTY_STRING)) {
            const entity = this.route.parent.snapshot.data.metaStore.entities[PAGES];
            const entityData: EntityData = {
                culture: this.settings.culture,
                provider: undefined,
                metadata: entity
            };

            if (redirectValue["NodeId"] !== stringConstants.DEFAULT_GUID) {
                this.dynamicItemService.getItem({
                    itemKey: redirectValue["NodeId"],
                    entityData: entityData,
                    fallbackProperties: [this.route.parent.snapshot.data.metaStore.entities[PAGES].defaultFieldName]
                }).subscribe(data => {
                    if (redirectValue["NodeId"] !== stringConstants.DEFAULT_GUID) {
                        this.selectedRedirectPage = data.title;
                        this.isRedirectPageSelected = this.selectedRedirectPage !== stringConstants.EMPTY_STRING;
                        this.selectedItem = data.data;
                    }
                });
            } else if (redirectValue["RedirectUrl"] !== stringConstants.EMPTY_STRING) {
                this.selectedRedirectPage = redirectValue["RedirectUrl"];
                this.isRedirectPageSelected = this.selectedRedirectPage !== stringConstants.EMPTY_STRING;
                this.selectedUrl = redirectValue["RedirectUrl"];
                this.shouldOpenInNewWindow = redirectValue["OpenInNewWindow"];
            }
        }
    }
}

export interface NavigationOptionsData {
    ShowInNavigation?: boolean;
    PageType?: boolean;
    RedirectPage?: RedirectPageData;
}

export interface RedirectPageData {
    NodeId: string;
    OpenInNewWindow: boolean;
    ProviderName: string;
    RedirectUrl: string;
}
