import { ClassProvider, Injectable } from "@angular/core";
import { ConfigExtender } from "./config-extender";
import { CONFIG_EXTENDER_TOKEN } from "./config-extender";

const FORM_CLASS = "";
const SCRIPT_MAP_TYPE = "scriptmanagerconfig";

@Injectable()
export class ScriptMapConfigExtender extends ConfigExtender {

    getFormClasses(): string {
        return FORM_CLASS;
    }

    isSupportedType(queryParam): boolean {
        return queryParam === SCRIPT_MAP_TYPE;
    }
}

export const SCRIPT_MAP_CONFIG_EXTENDER: ClassProvider = {
    multi: true,
    provide: CONFIG_EXTENDER_TOKEN,
    useClass: ScriptMapConfigExtender
};
