import { Component, Input, forwardRef, ViewChild, OnDestroy, HostBinding, OnChanges, SimpleChanges, EventEmitter, Output, QueryList } from "@angular/core";
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from "@angular/forms";
import { FormControl } from "@angular/forms";
import { Type, OnInit, AfterViewInit, ChangeDetectorRef, ViewEncapsulation } from "@angular/core";
import { trigger, style, transition, animate } from "@angular/animations";
import { FieldModel } from "../../../../../services/field.model";
import { ComponentData, SfFieldWrapperComponent, SfRxBase } from "@progress/sitefinity-component-framework";
import { FieldBase, Status } from "../../../../../../../fields/field-base";
import { ScrollService } from "../../../../../services/scroll.service";
import { Observable, ReplaySubject } from "rxjs";
import { ErrorFilter } from "./error-filter";
import { StatusType } from "../../../../../../../fields/field-status";
import { FieldRegistration, FieldTypes } from "../../services/fields-registry";
import { ReadComponent } from "../read/read.component";
import { CompositeFieldSettings } from "../../../services/composite-field.settings";
import { AsyncFieldValue } from "../../../../../../../fields/async-field-value";
import { DynamicTemplateDirective } from "../editable-fields/dynamic-template.directive";
import { SfDynamicComponentLoaderComponent } from "@progress/sitefinity-component-framework";
import { MarkupSection } from "@progress/sitefinity-component-framework";
import { getTooltip } from "../../../../../utils";
import { ActivatedRoute } from "@angular/router";
import { ComplexSettings } from "../../../../widget-editor/providers/fields/complex/complex.settings";

export const FORM_FIELD_VALUE_ACCESSOR = {
    provide: NG_VALUE_ACCESSOR,
    useExisting: forwardRef(() => FormFieldWrapperComponent),
    multi: true
};

// TODO: Fields should inherit from FieldBase
@Component({
    selector: "sf-form-field-wrapper",
    templateUrl: "./form-field-wrapper.component.html",
    providers: [FORM_FIELD_VALUE_ACCESSOR],
    encapsulation: ViewEncapsulation.None,
    animations: [
        trigger("enterAnimation", [
            transition("* => fadeIn", [
                style({ opacity: 0 }),
                animate("500ms ease-out", style({ opacity: 1 }))
            ])
        ])
    ]
})
export class FormFieldWrapperComponent extends SfRxBase implements ControlValueAccessor, FieldWrapper, OnDestroy, AfterViewInit, OnInit, OnChanges {
    @Input() fieldModel: FieldModel;
    @Input() formControl: FormControl;
    @Input() look: string;
    @Input() showTooltip: boolean = true;
    @Output() markAsDirty: EventEmitter<boolean> = new EventEmitter<boolean>();

    @ViewChild("loader", { static: false }) loader: SfDynamicComponentLoaderComponent;
    @ViewChild("fieldWrapper", { static: false }) fieldWrapper: SfFieldWrapperComponent;

    @HostBinding("@enterAnimation") get enterAnimation() {
        return this.enterAnimationState;
    }

    componentData: ComponentData;
    errorMessages: Array<string> = null;
    errorMessagesOnValueChange: Array<string> = null;
    showErrors: boolean = false;
    warningMessages: Array<string> = null;
    enableRequiredErrorCheck: boolean = false;
    hidden: boolean;
    labelId;
    shouldShowTooltip;
    shouldAddMarginTop;

    fieldClassName: string;

    private enterAnimationState: string;
    private wrappedField: FieldBase;
    private value: any;
    private onTouchedCallback: () => void;
    private onChangeCallback: (value: any) => void;
    private onOuterChangeCallback: (value: any) => void;
    private _onFieldVisibilityChange$ = new ReplaySubject<{ isHidden: boolean, key: string }>();

    constructor(
        private detector: ChangeDetectorRef,
        private scrollService: ScrollService,
        private filter: ErrorFilter,
        private route: ActivatedRoute) {
        super();
    }

    get status(): Observable<Status> {
        return this.wrappedField.status$;
    }

    get focus(): Observable<boolean> {
        if (this.wrappedField)
            return this.wrappedField.focus$;
    }

    get currentInstance() {
        if (!this.loader) {
            return null;
        }

        return this.loader.currentInstance;
    }

    get hasValue(): boolean {
        const value = this.wrappedField ? this.wrappedField.value || this.value : this.value;

        return this.fieldModel.settings.emptyValues ? (!!value && this.fieldModel.settings.emptyValues.indexOf(value) === -1) : !!value;
    }

    get onFieldVisibilityChange$(): Observable<{ isHidden: boolean, key: string }> {
        return this._onFieldVisibilityChange$.asObservable();
    }

    ngOnInit() {
        const registration = this.guardRegistration(this.fieldModel.selector, this.fieldModel.registration);
        if (!registration) {
            throw new Error(`No component registered to handle selector ${this.fieldModel.selector}`);
        }

        this.writeValue(this.fieldModel.value);

        let fieldType: Type<any> = null;
        if (this.fieldModel.settings.readOnlyMode) {
            fieldType = registration.readComponent;
        } else {
            fieldType = registration.writeComponent;

            if (this.formControl) {
                this.formControl.setValue(this.value);
            }
        }

        this.componentData = {
            type: fieldType,
            properties: {
                settings: this.fieldModel.settings,
                // TODO: value is obsolete and we should think about removing it
                // when removing value the whole application stops working in edit/create mode
                value: this.getValue()
            }
        };
        this.showTooltip = this.showTooltip && this.fieldModel.selector !== FieldTypes.shortTextDefault;
        this.fieldClassName = this.generateCssClassList();

        this._onFieldVisibilityChange$.next({ isHidden: !this.fieldModel.settings.isVisible, key: this.fieldModel.settings.key });

        this.labelId = this.fieldModel.settings.key ? this.fieldModel.settings.key : null;
        this.shouldShowTooltip = this.fieldModel.settings.tooltipModels && !!this.fieldModel.settings.tooltipModels.size && this.showTooltip;
        this.shouldAddMarginTop = !this.fieldModel.settings.showTitle && !this.fieldModel.settings.isNestedInParentControl;
    }

    onCustomLinkClicked(callback: any) {
        if (callback) {
            callback(this, this.route)
        }
    }

    ngOnChanges(changes: SimpleChanges) {
        const fieldModelChangeName = "fieldModel";
        const fieldModelChange = changes[fieldModelChangeName];
        if (fieldModelChange && !fieldModelChange.isFirstChange()) {
            this.writeValue(this.fieldModel.value);
        }
    }

    generateCssClassList() {
        let cls = "";
        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.fieldModel.cssClass) {
            cls += " " + this.fieldModel.cssClass.split(" ").join(" ");
        }

        if (this.showErrors && this.errorMessages && this.errorMessages.length > 0 && !(this.fieldModel.settings instanceof ComplexSettings)) {
            cls += " -has-errors";
        }
        return cls;
    }

    getTooltip(): MarkupSection[] {
        return getTooltip(this.fieldModel, this.getValue());
    }

    ngAfterViewInit() {
        this.wrappedField = <FieldBase>this.currentInstance;
        this.wrappedField.registerOnTouched(this.onTouchedCallback);
        const focusSubscription = this.wrappedField.focus$.subscribe((focused) => {
            if (focused && this.fieldModel.settings.changeOnFocus && !this.formControl.dirty) {
                const currentVal = this.getValue();
                const hasMultiple = this.fieldModel.settings.hasOwnProperty("multiple") && this.fieldModel.settings["multiple"] === true;
                const hasAllowMultiple = this.fieldModel.settings.hasOwnProperty("allowMultiple") && this.fieldModel.settings["allowMultiple"] === true;
                if (hasMultiple || hasAllowMultiple) {
                    this.wrappedField.writeValue([].concat(currentVal));
                } else if (typeof currentVal === "string") {

                    // this is needed in order to mark the field as dirty, when it gains focus
                    this.wrappedField.writeValue("temp");
                    this.wrappedField.writeValue(currentVal);
                }
            }
        });

        this.registerSubscription(focusSubscription);

        this.writeValue(this.value);

        if (!(this.currentInstance instanceof FieldBase)) {
            // TODO: Fields
            // throw new Error("Field component must inherit from FieldBase class")
            // HTML Wrapper component terror
        }

        if (this.fieldModel.settings.readOnlyMode) {
            if (this.wrappedField.hasEmptyValue()) {
                this.loader.destroy();
                this.componentData = null;
            }
        } else {
            this.handleWarnings();

            this.wrappedField.registerOnChange(this.onChangeCallback);
            this.initErrorHandling();
        }

        // this.enterAnimationState = "fadeIn";
        // ngAfterContentInit is called during change detection. we need to run the change detector again
        // https://github.com/angular/angular/issues/6005
        // https://github.com/angular/angular/issues/10131

        this.showErrors = !(this.fieldModel.settings instanceof CompositeFieldSettings);
        this.detector.detectChanges();
    }

    ngOnDestroy() {
        super.ngOnDestroy();

        // setting the wrapped field to null disables all the writeValue calls to it after the field has been destroyed
        this.wrappedField = null;
    }

    writeValue(value: any) {
        const normalizedValue: NormalizedValue = FormFieldWrapperComponent.normalizeValue(this.fieldModel, value);
        const newValue = normalizedValue.value;
        this.value = newValue;

        if (normalizedValue.markAsDirty) {
            this.markAsDirty.emit(true);
        }

        if (this.wrappedField) {
            this.wrappedField.writeValue(newValue);
        }
    }

    getValue(): any {
        if (this.wrappedField)
            return this.wrappedField.value;

        return this.value;
    }

    postProcessValue(value: any): any {
        if (this.wrappedField) {
            return this.wrappedField.postProcessValue(value);
        }

        return value;
    }

    registerOnChange(fn: any) {
        this.onOuterChangeCallback = fn;
        this.onChangeCallback = (value) => {
            // When setting a control in the form registerOnChange() is called twice. The first time the fn function
            // throws an error because the control is removed from the form. The second time the control
            // is already added to the form and the fn function is correct. That is why we use try-catch in order not to
            // throw an error the first time it is called.
            try {
                if (value instanceof AsyncFieldValue) {
                    this.formControl.setValue(value.asyncValue, { emitEvent: false, emitModelToViewChange: false, emitViewToModelChange: false });
                    // TODO: Fields. Figure out a way to communicate through the fields
                    this.markAsDirty.emit(true);
                    value = value.asyncValue;
                } else {
                    this.onOuterChangeCallback(value);
                }

                // we keep the form field value in sync with the field value when changes are coming from the field itself
                // and not from outside (writeValue method)
                this.value = value;
            } catch (error) {
                if (error.message.indexOf("There is no FormControl instance attached to form control element") !== 0)
                    throw error;
            }
        };

        if (this.wrappedField) {
            this.wrappedField.registerOnChange(this.onChangeCallback);
        }
    }

    registerOnTouched(fn: any) {
        this.onTouchedCallback = fn;
    }

    registerAllowDialogOpenCallback(allowDialogOpenCallback: () => Observable<boolean>) {
        if (this.wrappedField)
            this.wrappedField.registerAllowDialogOpenCallback(allowDialogOpenCallback);
    }

    invokeOutputTemplateCallback(templates: QueryList<DynamicTemplateDirective>) {
        if (this.wrappedField)
            this.wrappedField.invokeOutputTemplateCallback(templates);
    }

    scrollToField() {
        if (this.fieldWrapper && this.fieldWrapper.wrapper) {
            this.scrollService.scrollTo(this.fieldWrapper.wrapper);
        }
    }

    hasErrors(): boolean {
        const isValid = this.validate();
        this.processErrors(this.formControl.errors);

        const hasErrors = isValid === false || !!this.errorMessages && this.errorMessages.length !== 0;
        return hasErrors;
    }

    validate(): boolean {
        if (this.wrappedField)
            return this.wrappedField.validate();

        return true;
    }

    onFocus() {
        if (this.wrappedField)
            this.wrappedField.onFocus();
    }

    hasEmptyValue(): boolean {
        if (this.wrappedField) {
            return this.wrappedField.hasEmptyValue();
        }

        return false;
    }

    public commitValue() {
        this.wrappedField.commitValue();
        const filteredErrors = this.filter.getAllowedErrors(this.formControl.errors, true);
        this.processErrors(filteredErrors);
        this.errorMessagesOnValueChange = this.errorMessages;
    }

    static normalizeValue(fieldModel: FieldModel, initialValue: any): NormalizedValue {
        let markAsDirty: boolean = false;
        let isEmpty;
        if (fieldModel.settings.emptyValues) {
            isEmpty = fieldModel.settings.emptyValues.indexOf(initialValue) >= 0;
        } else {
            isEmpty = initialValue === null || initialValue === undefined;
        }

        // Null/Undefined is considered for default value that is why if the field model has a different value we should consider using it.
        if (isEmpty && fieldModel.settings.useDefaultValue) {
            initialValue = fieldModel.settings.defaultValue;

            // single choice fields should have a selected value by default even if the user has not edited the field
            if (fieldModel.settings.markAsDirty) {
                markAsDirty = true;
            }
        }

        const result = { value: initialValue, markAsDirty };

        if (Array.isArray(fieldModel.settings.defaultValue) && !Array.isArray(initialValue)) {
            result.value = [initialValue];
        }

        return result;
    }

    private handleWarnings(): void {
        const warnings: Array<string> = this.getWarnings();
        if (warnings && warnings.length > 0) {
            this.warningMessages = warnings;
        }
    }

    private initErrorHandling(): void {
        if (!this.formControl) {
            return;
        }

        this.handleFocusChanges();
        this.handleStatusChanges();
        this.handleValueChanges();
        this.handleChangesToHidden();
    }

    private handleValueChanges() {
        const valueChangesSubscription = this.formControl.valueChanges.subscribe((value) => {
            if (!this.showErrors) {
                // some errors need to be shown when typing, we do not set them to the form, but instead manipulate the
                // show errors flag to only show them during typing
                const filteredErrors = this.filter.getAllowedErrors(this.formControl.errors, this.enableRequiredErrorCheck);
                if (!!filteredErrors) {
                    this.errorMessagesOnValueChange = this.wrappedField.processErrors(filteredErrors);
                } else {
                    this.errorMessagesOnValueChange = null;
                }
            } else {
                // If this.showErrors flag is up, it means that we are editing the field without having focus on it (mirror)
                // In this case we should update the fields error messages
                const filteredErrors = this.filter.getAllowedErrors(this.formControl.errors, this.enableRequiredErrorCheck, null);
                this.processErrors(filteredErrors);
            }
        });

        this.registerSubscription(valueChangesSubscription);
    }

    private handleFocusChanges(): void {
        const focusSubscription = this.wrappedField.focus$.subscribe((isFocused) => {
            // always show all errors present when the field is focused out
            this.showErrors = !isFocused;
            this.errorMessagesOnValueChange = null;

            const filteredErrors = this.filter.getAllowedErrors(this.formControl.errors, this.enableRequiredErrorCheck, null);
            this.processErrors(filteredErrors);
        });

        this.registerSubscription(focusSubscription);
    }

    private handleChangesToHidden(): void {
        const hiddenSubscription = this.wrappedField.hidden$.subscribe((hidden) => {
            this.hidden = hidden;
            this._onFieldVisibilityChange$.next({ isHidden: hidden, key: this.fieldModel.key });
        });

        this.registerSubscription(hiddenSubscription);
    }

    private handleStatusChanges(): void {
        const statusSubscription = this.wrappedField.status$.subscribe((status) => {
            // custom errors are propagated through the $status field, we set them to the form
            const currentErrors = this.formControl.errors;
            if (status.type === StatusType.Error) {
                // keep the current errors for this control and set the new ones
                const errors = Object.assign({}, currentErrors, status.data);
                this.formControl.setErrors(errors);
                this.processErrors(errors);
                this.detector.detectChanges();
                this.scrollToField();
            } else if (status.type === StatusType.ErrorCleared && status.data && currentErrors) {
                const clearedErrorKeys = Object.keys(status.data);
                let errorsClone = Object.assign({}, currentErrors);

                clearedErrorKeys.forEach((key) => {
                    if (errorsClone.hasOwnProperty(key)) {
                        delete errorsClone[key];
                    }
                });

                const objectWithoutKeys = Object.keys(errorsClone);
                if (objectWithoutKeys.length === 0) {
                    errorsClone = null;
                }

                this.formControl.setErrors(errorsClone);
            } else if (status.type === StatusType.Warning) {
                this.handleWarnings();
            }
        });

        this.registerSubscription(statusSubscription);
    }

    private processErrors(errors: any): void {
        if (errors) {
            this.errorMessages = this.wrappedField.processErrors(errors);
        } else {
            this.errorMessages = null;
        }

        this.fieldClassName = this.generateCssClassList();
    }

    private getWarnings(): Array<string> {
        if (this.wrappedField) {
            return this.wrappedField.getWarnings();
        }

        return [];
    }

    private guardRegistration(selector: string, registration: FieldRegistration): FieldRegistration {
        // TODO: we should think about a default value for the write component

        if (!registration) {
            throw new Error(`No field registration found for selector ${this.fieldModel.selector}`);
        }

        if (!registration.writeComponent) {
            throw new Error(`No write component registered to handle selector ${this.fieldModel.selector}`);
        }

        const copy: FieldRegistration = {
            writeComponent: registration.writeComponent,
            readComponent: registration.readComponent,
            settingsType: registration.settingsType
        };

        if (!copy.readComponent) {
            copy.readComponent = ReadComponent;
        }

        // TODO: This should be lazy initialized here
        // if (!copy.settingsType) {
        //     copy.settingsType = SettingsBase;
        // }

        return copy;
    }
}

/**
 * @ExposedInApi {FieldWrapper} FieldWrapper v1/fields-behaviour/field-wrapper.d.ts
 */
export interface FieldWrapper {
    fieldModel: FieldModel;
    focus: Observable<boolean>;
    writeValue(value: any);
    getValue(): any;
}

interface NormalizedValue {
    value: any,
    markAsDirty: boolean;
}
