import { Injectable, Inject } from "@angular/core";
import { DOCUMENT_TOKEN } from "../document.provider";
import { KeyValue } from "@angular/common";
import { NODE_NAMES } from "../modules/html/selector-constants";
import { Observable, Subject } from "rxjs";

@Injectable()
export class StyleSheetService {
    constructor(@Inject(DOCUMENT_TOKEN) private documentProvider: Document) { }

    insertLinkTag(url: string, documentElement: Document = this.documentProvider, attributes: KeyValue<string, string>[] = null): Observable<boolean> {
        const loadedStyle$ = new Subject<boolean>();
        const linkElement = documentElement.createElement(NODE_NAMES.LINK_ELEMENT) as HTMLLinkElement;

        linkElement.rel = "stylesheet";
        linkElement.href = url;
        linkElement.onload = () => {
            loadedStyle$.next(true);

            loadedStyle$.complete();
        };
        linkElement.onerror = () => {
            loadedStyle$.next(false);

            loadedStyle$.complete();
        };

        if (attributes) {
            this.setAttributes(linkElement, attributes);
        }

        documentElement.head.appendChild(linkElement);

        return loadedStyle$.asObservable();
    }

    insertStyleTag(content: string, documentElement: Document = this.documentProvider, attributes: KeyValue<string, string>[] = null) {
        const styleTag = document.createElement(NODE_NAMES.STYLE_ELEMENT) as HTMLStyleElement;
        styleTag.type = "text/css";

        if (attributes) {
            this.setAttributes(styleTag, attributes);
        }

        styleTag.appendChild(document.createTextNode(content));
        documentElement.head.appendChild(styleTag);
    }

    private setAttributes(element: HTMLElement, attributes: KeyValue<string, string>[]) {
        attributes.forEach(attr => {
            element.setAttribute(attr.key, attr.value);
        });
    }
}
