import { BehaviorSubject } from "rxjs";
import { Component, Input, Inject, HostListener, ViewEncapsulation, OnInit, OnDestroy } from "@angular/core";
import { DOCUMENT_TOKEN } from "../../../../document.provider";
import { MONACO_CUSTOM_THEME, MONACO_FORMAT_OPTIONS, MONACO_SETTINGS, MONACO_CUSTOM_THEME_NAME } from "./view-code-constants";
import { html_beautify } from "js-beautify";
import { ANIMATION_FADE_IN, ANIMATION_VISIBLE_STATE, ANIMATION_HIDDEN_STATE } from "../../../../animations/animation-utilities";
import * as monaco from "monaco-editor";
import "monaco-editor/esm/vs/base/browser/ui/codicons/codicon/codicon.ttf";

const EDITOR_TOP_OFFSET: number = 46 + 10; // Top toolbar height + padding

@Component({
    selector: "sf-view-code",
    templateUrl: "./view-code.component.html",
    styleUrls: ["./view-code.component.scss"],
    encapsulation: ViewEncapsulation.None,
    animations: [ANIMATION_FADE_IN]
})
export class ViewCodeComponent implements OnInit, OnDestroy {
    @Input() source: string;

    isLoading$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
    animationState: string = ANIMATION_HIDDEN_STATE;

    private monacoEditor: any;
    private bodyOverflowStyleInitialValue: string;

    constructor(@Inject(DOCUMENT_TOKEN) private documentProvider: Document) { }

    /**
     * Gets the current value of the code view editor as string.
     *
     * @memberof {ViewCodeComponent}
     */
    get value(): string {
        return this.monacoEditor.getValue();
    }

    ngOnInit() {
        this.initMonacoEditor(monaco);

        this.bodyOverflowStyleInitialValue = this.documentProvider.body.style.overflowY;

        this.toggleBodyOverflow();
    }

    ngOnDestroy() {
        this.toggleBodyOverflow();
    }

    @HostListener("window:resize")
    onResize() {
        this.recalculateLayout();
    }


    /**
     * This method fixes a visual bug where two scrollbars appear when the html content of
     * the monaco editor is very long
     *
     * @private
     * @memberof ViewCodeComponent
     */
    private toggleBodyOverflow() {
        const hidden = "hidden";

        if (this.documentProvider.body.style.overflowY === hidden) {
            this.documentProvider.body.style.overflowY = this.bodyOverflowStyleInitialValue;
        } else {
            this.documentProvider.body.style.overflowY = hidden;
        }
    }

    /**
     * Initialize Monaco editor.
     * Applies a custom theme and sets options.
     *
     * @memberof {ViewCodeComponent}
     */
    private initMonacoEditor(monaco: any) {
        if (monaco) {
            monaco.editor.defineTheme(MONACO_CUSTOM_THEME_NAME, MONACO_CUSTOM_THEME);
            monaco.languages.html.htmlDefaults.setOptions(MONACO_FORMAT_OPTIONS);

            this.source = html_beautify(this.source, MONACO_FORMAT_OPTIONS.format);
            MONACO_SETTINGS.value = this.source;
            this.monacoEditor = monaco.editor.create(this.documentProvider.getElementById("monaco-editor"), MONACO_SETTINGS);

            this.recalculateLayout();
            this.isLoading$.next(false);
            this.animationState = ANIMATION_VISIBLE_STATE;
        }
    }

    /**
     * Recalculate Monaco editor container on resize.
     *
     * @memberof {ViewCodeComponent}
     */
    private recalculateLayout() {
        const dimensions = {
            width: this.documentProvider.body.clientWidth,
            height: window.innerHeight - EDITOR_TOP_OFFSET
        };

        if (this.monacoEditor) {
            this.monacoEditor.layout(dimensions);
        }
    }
}
