import { Injectable } from "@angular/core";
import { EntityData, DataItem } from "../interfaces";
import { Entity, MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { DynamicItemService } from "./dynamic-item.service";
import { Observable, of } from "rxjs";
import { LibraryStore } from "../../../libraries/services/library.store";
import { stringConstants } from "../../../../common-constants";
import { SiteDataStore } from "../../../shared/services/metadata/site-data.store";
import { first } from "rxjs/operators";

@Injectable()
export class ParentService {
    constructor(
        private metadataStore: MetadataStore,
        private dynamicItemService: DynamicItemService,
        private libraryStore: LibraryStore,
        private siteDataStore: SiteDataStore) { }

    getParentItem(entityData: EntityData, parentId: string): Observable<DataItem> {
        let getItem$ = of<DataItem>(null);
        if (parentId && parentId !== stringConstants.DEFAULT_GUID && (entityData.metadata.hasParent || entityData.metadata.ignoreParentChildRelationship)) {
            const parentEntity = this.getParentEntity(entityData);

            this.siteDataStore.getValue().pipe(first()).subscribe(siteData => {
                if (!entityData.metadata.ignoreParentChildRelationship && parentId !== siteData.SiteMapRootNodeId) {
                    getItem$ = this.dynamicItemService.getItem({
                        itemKey: parentId,
                        entityData: {
                            metadata: parentEntity,
                            provider: entityData.provider,
                            culture: entityData.culture
                        },
                        fallbackProperties: [entityData.metadata.defaultFieldName]
                    });
                } else if (entityData.metadata.isMedia && !entityData.metadata.isSelfReferencing) {
                    getItem$ = this.libraryStore.getFolderById(entityData, parentId);
                }
            });
        }

        return getItem$;
    }

    getParentEntity(entityData: EntityData): Entity {
        if (entityData.metadata.ignoreParentChildRelationship) {
            if (entityData.metadata.hasParent) {
                return this.metadataStore.getValue().entities[entityData.metadata.parent];
            }

            // Handle cycles where parent-child relationships is ignored and
            // you can navigate from Calendars -> Events and Events -> Calendars
            return this.metadataStore.getValue().entities[entityData.metadata.children[0]];
        }

        return this.metadataStore.getValue().entities[entityData.metadata.parent];
    }
}
