import { combineLatest as observableCombineLatest, timer as observableTimer, ReplaySubject, Observable, forkJoin } from "rxjs";
import { Component, Input, OnInit } from "@angular/core";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { ChildrenCountStore } from "../../services/children-count.store";
import { DataContext } from "../../../../shared/models/data-context-component";
import { COMMAND_NAMES } from "../commands";
import { SiteDataStore } from "../../../../shared/services/metadata/site-data.store";
import { DataItem } from "../../interfaces";
import { map } from "rxjs/operators";
import { ReorderModuleChildrenProvider } from "../../../../../app-config/reorder-module-children.provider";

/**
 * Component used to display the count of children if a hierarchical item
 */
@Component({
    selector: "sf-list-children",
    templateUrl: "./list-children-count.component.html"
})
export class ListChildrenCountComponent implements OnInit {

    /**
     * Indicates if the component is currently in the process of loading the items.
     */
    public isLoading = false;

    /**
     * The item data that is required to get the children's count
     */
    @Input() public context: DataContext;

    /**
     * The minimum loading time of the component to avoid "twitching".
     */
    @Input() public minimumLoadingTime = 1000;

    private children$ = new ReplaySubject<ChildCount[]>(1);

    /**
     * Initializes a new instance of the {@link ListChildrenCountComponent} class
     * @param metadata The metadata from which to fetch the child item's types
     * @param store The store from which to retrieve the count of the children.
     */
    constructor(
        private metadata: MetadataStore,
        private store: ChildrenCountStore,
        private siteDataStore: SiteDataStore,
        private reorderModuleChildrenProvider: ReorderModuleChildrenProvider
        ) {
    }

    public ngOnInit(): void {
        this.isLoading = true;
        const dataItem = this.context.dataItem;

        this.metadata.initialize().subscribe(metaContainer => {
            const miniumLoaderTimer$ = observableTimer(this.minimumLoadingTime);
            const getChildren$ = this.store.getChildrenCount(dataItem, metaContainer);
            const isChildAvailable$ = this.isChildAvailable(dataItem);

            observableCombineLatest(miniumLoaderTimer$, getChildren$, isChildAvailable$).subscribe((data) => {
                const children: ChildCount[] = [];
                const childCountData = data[1];
                const isChildAvailable = data[2];

                dataItem.childTypes.forEach((child) => {
                    if (isChildAvailable[child]) {
                        const childEntity = metaContainer.entities[child];
                        const count = childCountData[child];
                        let displayName = null;
                        if (count === 1) {
                            displayName = childEntity.singularName;
                        } else {
                            displayName = childEntity.displayName;
                        }

                        children.push({
                            setName: child,
                            displayName: displayName,
                            count: count
                        });
                    }
                });

                this.reorderModuleChildrenProvider.reorderChildren(dataItem.metadata.setName, children);

                this.children$.next(children);
                this.isLoading = false;
            });
        });
    }

    /**
     * Gets an observable that emits when the children are loaded or new values are present.
     */
    public get children() {
        return this.children$.asObservable();
    }

    /**
     * Handles the click event on a child item label and emits an event that fires which child item exactly was clicked.
     * @param child The child item that was clicked.
     */
    public onClick(child: ChildCount): void {
        const invoker = this.context.invoker;
        invoker.invoke({
            name: COMMAND_NAMES.childNavigate,
            data: {
                childSetName: child.setName,
                dataItem: this.context.dataItem
            }
        });
    }

    private isChildAvailable(item: DataItem): Observable<any> {
        return forkJoin(item.childTypes.map((child) => {
            return this.siteDataStore.isEntitySetAccessible(child).pipe(
                map(isAccessible => {
                    return { set: child, isAccessible};
                })
            );
        })).pipe(
            map(x => {
                return x.reduce((result, item: any) => {
                    result[item.set] = item.isAccessible;
                    return result;
                }, {});
            })
        );
    }
}

export interface ChildCount {
    setName: string;

    displayName: string;

    count: number;
}
