import { Component, Input, OnInit, DoCheck } from "@angular/core";

import { LockedItemStatusResolver } from "../../../../services/status.resolver";
import { indefiniteArticle } from "../../../../utils";
import { BehaviorSubject } from "rxjs";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { Properties } from "../../fields.constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const HEADING_STATUS_UPDATE_INTERVAL = 15000;

@Component({
    selector: "sf-heading-status",
    templateUrl: "./heading-status.component.html"
})
export class HeadingStatusComponent extends SfRxBase implements OnInit, DoCheck {
    @Input() item: BehaviorSubject<DataItem>;

    dataContextItem: any;
    protected isEditMode: boolean;

    private dataItem: DataItem = null;

    constructor(private statusResolver: LockedItemStatusResolver) {
        super();
    }

    // We are updating the status here in order not use Observable.timer or
    // setInterval() because they are hard to mock
    ngDoCheck() {
        if (this.isEditMode && this.dataItem && this.dataItem.data) {
            this.dataContextItem.StatusText = this.statusResolver.getDetailedStatusText(this.dataItem.data);
        }
    }

    ngOnInit() {
        if (!this.item) {
            return;
        }

        const subscription = this.item.subscribe(value => {
            this.dataItem = value;
            this.isEditMode = false;

            if (!value.data) {
                // when creating an item
                this.dataContextItem = {
                    StatusText: `Creating ${this.getName(value)}`
                };
            } else {
                // when translating an item
                const availableLangs: Array<string> = value.data[Properties.AvailableLanguages];
                if (availableLangs && availableLangs.indexOf(value.culture) === -1) {
                    this.dataContextItem = {
                        StatusText: `Translating ${this.getName(value)}`
                    };
                } else {
                    // when editing an item
                    this.updateStatus(value);
                    this.isEditMode = true;
                }
            }
        });

        this.registerSubscription(subscription);
    }

    private getName(entityData: EntityData): string {
        return `${indefiniteArticle(entityData.metadata.singularName)} ${entityData.metadata.singularName.toLowerCase()}...`;
    }

    private updateStatus(value: DataItem) {
        const newStatus = this.statusResolver.getDetailedLabel(value.data);
        if (JSON.stringify(newStatus) !== JSON.stringify(this.dataContextItem)) {
            this.dataContextItem = newStatus;
        }
    }
}
