import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Injectable } from "@angular/core";
import { FieldBase } from "../../../../../fields/field-base";
import { ChoiceComponent } from "../../../../../fields/choice/choice.component";

@Injectable()
export class NativeChatWidgetFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === "BotId") {
            NativeChatWidgetFieldsChangeService.processSelectedItemsFieldChange(changedValue, fields.map(x => x.currentInstance));
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === "NativeChat" || typeFullName === "SitefinityNativeChat";
    }

    static processSelectedItemsFieldChange(changedValue: any, fields: FieldBase[]): boolean {
        const conversationField = this.getConversationField(fields);
        const choiceServiceCallParameters = conversationField?.settings.choiceServiceCallParameters ? JSON.parse(conversationField.settings.choiceServiceCallParameters) : null;
        if (changedValue && conversationField != null && choiceServiceCallParameters != null && choiceServiceCallParameters.length > 0) {
            const serviceUrl = conversationField.settings.choiceServiceUrl;
            choiceServiceCallParameters.forEach(param => {
                const key = Object.keys(param)[0];
                const regexValue = new RegExp("\\(" + key + "=(.+?)\\)");
                const newServiceUrl = serviceUrl.replace(regexValue, `(${key}='${changedValue}')`);
                conversationField.settings.choiceServiceUrl = newServiceUrl;
                conversationField.reloadChoices();
                return true;
            });
        }

        return false;
    }

    private static getConversationField(fields: FieldBase[]): ChoiceComponent {
        const field = fields.find(x => x.settings.key === "ConversationId");
        if (field && field instanceof ChoiceComponent) {
            return field;
        }

        return null;
    }
}

export const NC_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: NativeChatWidgetFieldsChangeService,
    multi: true
};
