import { Injectable } from "@angular/core";
import { Subject, Observable } from "rxjs";

@Injectable()
export class ContextualHelpService {
    get onLoad(): Observable<void> {
        return this._onLoad.asObservable();
    }

    private _onLoad: Subject<any> = new Subject();

    triggerLoad() {
        this._onLoad.next({});
    }
}
