import { Input, Component, OnInit, OnChanges, SimpleChanges, Output, EventEmitter } from "@angular/core";
import { MediaRecognizerService } from "../../src/app/modules/libraries/media/media-recognizer.service";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../src/app/common-constants";
import { FailedMediaValidation } from "../../src/app/modules/content/dynamic-modules/interfaces";

const THUMBNAIL_HEIGHT = 60;
const AVAILABLE_LANGUAGES_DEFAULT_TOOLTIP_LOOK: string = "down-right";
const AVAILABLE_LANGUAGES_MOVED_TOOLTIP_LOOK: string = "down-left";

@Component({
    selector: "sf-thumbnail",
    templateUrl: "./thumbnail.component.html"
})
export class ThumbnailComponent extends SfRxBase implements OnInit, OnChanges {
    @Input() customThumbnailUrl: string;
    @Input() title: string;
    @Input() size: string;
    @Input() src: string;
    @Input() alt: string;
    @Input() width: number;
    @Input() height: number;
    @Input() selected: boolean;
    @Input() library: string;
    @Input() lockedStatus: string;
    @Input() status: any;
    @Input() selectable: boolean;
    @Input() extension: string;
    @Input() type: string;
    @Input() hasTooltip: boolean = true;
    @Input() isMultimedia: boolean;
    @Input() isVideo: boolean;
    @Input() isPlaceholder: boolean = true;
    @Input() isTranslated: boolean;
    @Input() dimNotTranslated: boolean = false;
    @Input() showNotTranslatedLabel: boolean = true;
    @Input() showPropertiesLabel: boolean;
    @Input() isSmallThumbnail: boolean = false;
    @Input() playable: boolean = false;
    @Input() look: string;
    @Input() failedValidation: FailedMediaValidation;
    @Input() removeButtonAreaLabel: string;
    @Input() showRemoveButton: boolean;
    @Input() showRemoveButtonAlways: boolean;
    @Input() badgesList: string[] = [];
    @Output() removeButtonClicked: EventEmitter<Event> = new EventEmitter<Event>();
    @Output() onClick: EventEmitter<Event> = new EventEmitter<Event>();
    @Output() onSelect: EventEmitter<Event> = new EventEmitter<Event>();
    mediaData: ComponentData;
    isWidePhoto: boolean;
    imageWrapperClass: string = "";
    cssClass: string;
    showTooltip: boolean;
    showAvailableTranslations: boolean;
    //Minimum offset from the bottom of the viewport, so that tooltip doesn't appear under selector buttons
    tooltipMinOffsetFromBottom: number = 67;
    availableLanguageTranslationLook: string = AVAILABLE_LANGUAGES_DEFAULT_TOOLTIP_LOOK;

    constructor(private mediaRecognizerService: MediaRecognizerService) {
        super();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.src || changes.alt) {
            this.setComponentData();
            this.cssClass = this.generateCssClassList();
        }

        if (changes.isTranslated || changes.dimNotTranslated) {
            this.cssClass = this.generateCssClassList();
        }
    }

    ngOnInit(): void {
        this.setComponentData();
        this.cssClass = this.generateCssClassList();
    }

    onFileRemoveClick(event: Event) {
        this.removeButtonClicked.emit(event);
    }

    onClicked() {
        //(keyup.enter) as well
        this.onClick.emit();
    }

    onSelected(event: Event) {
        event.preventDefault();
        event.stopImmediatePropagation();
        //(keyup.space) as well
        this.onSelect.emit();
    }

    onMovingDirections (directions) {
        if (directions.movedLeft !== undefined) {
            this.availableLanguageTranslationLook = AVAILABLE_LANGUAGES_MOVED_TOOLTIP_LOOK;
        }
    }

    private setComponentData() {
        const componentProperies = this.generateComponentProperties();
        this.mediaData = this.mediaRecognizerService.getComponentData(componentProperies);
        this.mediaData.updatePropertiesOnChange = true;
        this.mediaData.removePreviousView = true;
    }

    private generateComponentProperties() {
        this.isWidePhoto = this.width > this.height;
        const commonProperties: any = {
            name: this.title,
            src: this.src,
            alt: this.alt,
            size: this.size,
            type: this.type,
            extension: this.extension ? this.extension.split(".").pop() : null,
            LockedStatus: this.lockedStatus,
            DisplayStatus: this.status,
            isTranslated: this.isTranslated,
            isAbsoluteImage: true,
            isVideo: this.isVideo
        };
        let generatedProperties = {
            isMultimedia: this.isMultimedia
        };

        if (!this.isMultimedia) {
            generatedProperties = Object.assign(generatedProperties, { item: commonProperties });
        } else {
            commonProperties.playable = this.playable;
            commonProperties.customThumbnailUrl = this.customThumbnailUrl;
            commonProperties.src = this.src;

            generatedProperties = Object.assign(generatedProperties, commonProperties);
        }

        return generatedProperties;
    }

    private generateCssClassList() {
        const classList: Array<string> = [];

        if (this.height < 145) {
            classList.push("-centered");
        }
        if (this.look) {
            const classes = this.look.split(" ").map(cls => "-" + cls);
            classList.push(...classes);
        }
        if (this.showRemoveButtonAlways) {
            classList.push("-remove-button-visible");
        }
        if (this.selected) {
            classList.push("-selected");
        }
        if (this.selectable) {
            classList.push("-selectable");
        }

        if (this.isPlaceholder) {
            classList.push("sf-placeholder");
        }

        if (this.isMultimedia) {
            classList.push("sf-media");
            this.imageWrapperClass = "sf-thumbnail";
        } else {
            classList.push("-document");
            classList.push("sf-media");
        }

        if (this.isSmallThumbnail) {
            classList.push("sf-media -cropped -smaller -no-zindex");

            if (this.height > THUMBNAIL_HEIGHT) {
                this.imageWrapperClass += " -sf-full-height";
            }

            if (this.isWidePhoto) {
                classList.push("-wide");
            }
        }

        if (this.isVideo) {
            classList.push("-video");
        }
        if (this.failedValidation || this.dimNotTranslated) {
            classList.push("-dimmed");
        }

        if (this.showPropertiesLabel) {
            classList.push("-dimmed-hover");
        }

        return classList.join(stringConstants.INTERVAL);
    }
}
