import { SelectorConstants } from "./../selector-constants";
import { Media } from "./media";
import { stringConstants } from "../../../common-constants";

/**
 * Base parser for handling embed media content.
 * @ExposedInApi {EmbedMediaParser} EmbedMediaParser v1/embed-media/embed-media.parser.d.ts
 */
export abstract class EmbedMediaParser {
    getMediaHtml(media: Media, width: any, height: any, css: string): string {
        if (!media.isValid)
            return;

        let style = stringConstants.EMPTY_STRING;
        if (width) {
            style += `width: ${width}px; `;
        }

        if (height) {
            style += `height: ${height}px; `;
        }

        if (css) {
            style += css;
        }

        return `<div ${SelectorConstants.SF_IMMUTABLE} contenteditable="false" style="${style}"><div ${SelectorConstants.SF_DISABLE_LINK_EVENT}>${media.html}</div></div>`;
    }

    getValue(html: string): string {
        return html;
    }

    isExactMatch(inputText: string): boolean {
        return false;
    }

    initEmbeddedData() {}
    abstract canProcess(inputText: string): boolean;
    abstract parse(inputText: string): Promise<Media>;
    abstract getMediaFromElement(element: HTMLElement): HTMLElement;
    abstract updateMediaElement(element: HTMLElement, propName: string, value: any);

    protected insertScript(src: string) {
        if (this.scriptExists(src)) {
            return;
        }

        const widgetScript = document.createElement("script");

        widgetScript.type = "text/javascript";
        widgetScript.src = src;
        widgetScript.async = true;

        document.body.appendChild(widgetScript);
    }

    protected getNullableInteger(value: Number | string): { hasValue: boolean, value: number } {
        const numberAsString = value.toString().replace("px", stringConstants.EMPTY_STRING);
        const num = Number(numberAsString);
        const result = {
            hasValue: numberAsString !== stringConstants.EMPTY_STRING && !isNaN(num),
            value: null
        };

        if (result.hasValue)
            result.value = num;

        return result;
    }

    private scriptExists(src: string) {
        const scripts = document.querySelectorAll("script");

        for (let i = 0; i < scripts.length; i++) {
            if (scripts[i].src === src) {
                return true;
            }
        }

        return false;
    }
}
