import { Pipe, PipeTransform } from "@angular/core";
import { stringConstants } from "../../../common-constants";

@Pipe({
    name: "sfTrimTextLength"
})
export class TrimTextLengthPipe implements PipeTransform {

    transform(value: string, ...args: any[]): string {
        if (!value) {
            return stringConstants.EMPTY_STRING;
        }

        let result = value.toString();
        const trimLength = args[0]  || 10;

        if (result && result.length > trimLength) {
            result = result.substring(0, trimLength) + "...";
        }

        return result;
    }
}
