import { Component, Input, ViewChild, OnInit, ViewEncapsulation, ChangeDetectorRef, OnDestroy } from "@angular/core";
import { CropService, RotateResult, CropResult } from "./crop.service";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { ResizeService, SizeChangeData, ResizeResult } from "./resize.service";
import { assignMatchingProperties as assignMatchingProperties, getCssVariableValueAsNumber, extractSafeUrl } from "../../../../utils";
import { HttpODataRequestWrapper } from "../../../shared/services/http-odata-request.wrapper";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { ActivatedRoute } from "@angular/router";
import { QUERY_PARAMS, DEFAULT_STORAGE_PROVIDERS } from "../../../content/constants";
import { EnvironmentService } from "../../../shared/services/environment.service";
import { environmentTypes } from "../../../../environment";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const ASPECT_RATIO_OPTIONS = {
    ORIGINAL: "Original",
    SQUARE: "Square",
    SIXTEEN_TO_NINE: "16:9",
    FOUR_TO_THREE: "4:3"
};

const ASPECT_RATIO_KEY = "aspect-ratio";
const LOAD_EVENT = "load";

@Component({
    templateUrl: "./edit-crop-rotate.component.html",
    styleUrls: ["./edit-crop-rotate.component.scss"],
    providers: [CropService, ResizeService],
    encapsulation: ViewEncapsulation.None
})
export class EditCropRotateComponent extends SfRxBase implements OnInit, OnDestroy {
    @ViewChild("aspectration", { static: false }) aspectration: any;
    @Input() item: any;
    @Input() dataItem: DataItem;
    containerData: ContainerData;
    aspectRationSettings: ChoiceSettings;
    resizeData: ResizeData;
    placeholderSideSize: number;
    private _image: HTMLImageElement;
    private _canvas: HTMLCanvasElement;
    private imageLoadEventListener: EventListener;

    private get canvas(): HTMLCanvasElement {
        this._canvas.getContext("2d").clearRect(0, 0, this._canvas.width, this._canvas.height);
        return this._canvas;
    }

    @ViewChild("croppedImage", { static: true })
    set image(elementRef) {
        this._image = (<any>elementRef).nativeElement;
    }

    get image() {
        return this._image;
    }

    constructor(private readonly cropService: CropService,
                private readonly resizeService: ResizeService,
                private readonly detector: ChangeDetectorRef,
                private http: HttpODataRequestWrapper,
                private route: ActivatedRoute,
                private envService: EnvironmentService) {
                    super();
                }

    ngOnInit() {
        const storageProvider = this.dataItem.data.Parent.BlobStorageProvider;
        const isExternalStorageProvider = !(storageProvider === DEFAULT_STORAGE_PROVIDERS.DATABASE || storageProvider === DEFAULT_STORAGE_PROVIDERS.FILE_SYSTEM);

        if (this.item.dataUrl !== this.dataItem.data.Url) {
            // the image is just replaced
            this.image.src = extractSafeUrl(this.item.dataUrl);
        } else {
            if (this.dataItem.key && (this.envService.getEnvironment() !== environmentTypes.integration || isExternalStorageProvider)) {
                const snapshot = this.route.snapshot;
                const queryParams = snapshot.queryParamMap;
                const params = {
                    [QUERY_PARAMS.PROVIDER]: this.dataItem.provider,
                    [QUERY_PARAMS.CULTURE]: this.dataItem.culture
                };

                if (queryParams.keys.indexOf(QUERY_PARAMS.VERSION) > -1) {
                    params[QUERY_PARAMS.VERSION] = queryParams.get(QUERY_PARAMS.VERSION);
                }

                // this will get the image content
                this.registerSubscription(this.http.get$(`${ENTITY_SET.IMAGES}(${this.dataItem.key})/$value`, { responseType: "blob", params })
                    .subscribe((x => {
                        if (!x.isLoading) {
                            const url = URL.createObjectURL(x.content);
                            this.image.src = url;
                        }
                    })));
            } else {
                this.image.src = this.dataItem.data.Url;
            }
        }

        this.imageLoadEventListener = evt => this.initializeCropService();
        this._canvas = document.createElement("canvas");
        this.resizeData = {
            enabled: false,
            constrained: true,
            width: this.item.width,
            height: this.item.height
        };

        this.aspectRationSettings = new ChoiceSettings(ASPECT_RATIO_KEY, false);
        this.aspectRationSettings.title = "Aspect ratio";
        this.aspectRationSettings.choices = Object.values(ASPECT_RATIO_OPTIONS).map(option => {
            return {
                Name: option,
                Value: option
            };
        });

        // will initialize crop service once the image is loaded.
        // when used in ngAfterViewInit there's times that the image is not loaded and the initialization is done with wrong values.
        this.image.addEventListener(LOAD_EVENT, this.imageLoadEventListener);
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.image.removeEventListener(LOAD_EVENT, this.imageLoadEventListener);
        this.cropService.removeEventListeners();
    }

    getCroppedImageDataUrl(): string {
        const dataUrl = this.cropService.getCroppedImageDataUrl();
        return dataUrl;
    }

    onAspectRationChange(selection: string): void {
        this.cropService.centerCropWindow();

        switch (selection) {
            case ASPECT_RATIO_OPTIONS.ORIGINAL:
                this.cropService.resetCropWindow();
                break;
            case ASPECT_RATIO_OPTIONS.SQUARE:
                this.cropService.setAspectRatio(1 / 1);
                break;
            case ASPECT_RATIO_OPTIONS.SIXTEEN_TO_NINE:
                this.cropService.setAspectRatio(16 / 9);
                break;
            case ASPECT_RATIO_OPTIONS.FOUR_TO_THREE:
                this.cropService.setAspectRatio(4 / 3);
                break;
        }
    }

    onResizeClick() {
        this.resizeData.enabled = !this.resizeData.enabled;
    }

    onRotateClick() {
        const result = this.cropService.rotate();
        assignMatchingProperties(this.resizeData, result);
    }

    onResizeValueChanged(data: { key: string, value: string }) {
        const changedValue = Number(data.value);

        if (changedValue < 1 || changedValue >= this.image[data.key]) {
            return;
        }

        const aspectRatio = this.resizeData.width / this.resizeData.height;

        this.resizeData[data.key] = changedValue;

        const sizeChangeData: SizeChangeData = {
            changedDimensionName: data.key,
            changedDimensionValue: changedValue,
            constrainedProportions: this.resizeData.constrained,
            width: this.resizeData.width,
            height: this.resizeData.height,
            aspectRatio
        };

        const resizeResult = this.resizeService.resize(sizeChangeData, this.image, this.canvas);
        this.applyNewChanges(resizeResult);

        // update the aspect ration dropdown value
        this.aspectration.writeValue(ASPECT_RATIO_OPTIONS.ORIGINAL);
    }

    onConstrainProportionsClick() {
        this.resizeData.constrained = !this.resizeData.constrained;
    }

    private initializeCropService(containerData?: ContainerData): void {
        this.removeSubscriptions();
        this.containerData = containerData || {
            width: this.image.width,
            height: this.image.height
        };

        // 630 is the default value defined in the css
        const maxWidth = getCssVariableValueAsNumber("--form-width-medium", "sf-app") || 630;
        let longest = this.image.width > this.image.height ? this.image.width : this.image.height;
        if (longest > maxWidth) {
            longest = maxWidth;
        }

        // size the placeholder to be square, otherwise the image will be cropped on rotate
        const ratio = this.image.width / this.image.height;
        if (this.image.width > this.image.height) {
            this.image.width = longest;
        } else {
            this.image.width = longest * ratio;
        }

        this.placeholderSideSize = longest;

        this.cropService.init(this.image, this.item.contentType);
        const dimensionsChangedSubscription = this.cropService.dimensionsChanged.subscribe((x: CropResult) => {
            this.resizeData.width = x.width;
            this.resizeData.height = x.height;
        });
        this.registerSubscription(dimensionsChangedSubscription);
        this.onAspectRationChange(ASPECT_RATIO_OPTIONS.ORIGINAL);
        this.detector.detectChanges();
    }

    private applyNewChanges(data: ResizeResult | RotateResult): void {
        this.image.src = data.dataUrl;

        assignMatchingProperties(this.resizeData, data);
    }
}

interface ResizeData {
    enabled: boolean;
    constrained: boolean;
    width?: number;
    height?: number;
}

interface ContainerData {
    width: number;
    height: number;
}
