import { SelectorItem } from "../selector-item";
import { DataItem } from "../../../../../../../content/dynamic-modules/interfaces";
import { SiteData } from "../../../../../../../shared/services/metadata/site-data.store";

export class SiteSelectorItem extends SelectorItem {
    cultures: SelectorItem[];
    defaultCulture: SelectorItem;
    sitemapRootNodeId: string;
    additionalInfo: string;
    static fromDataItem = (dataItem: DataItem) => {
        const chipItem = new SiteSelectorItem();
        chipItem.Title = dataItem.title;
        chipItem.value = dataItem.key;
        if (dataItem.data["CulturesMap"]) {
            chipItem.cultures = dataItem.data["CulturesMap"].map(c => <SelectorItem>{ Title: c.DisplayName, value: c.Name });
            const defaultCulture = chipItem.cultures.find(x => x.value === dataItem.data["DefaultCultureKey"]);
            chipItem.defaultCulture = defaultCulture;
        } else {
            chipItem.cultures = dataItem.data["CultureKeys"].map(l => SelectorItem.fromString(l));
            chipItem.defaultCulture = SelectorItem.fromString(dataItem.data["DefaultCultureKey"]);
        }

        chipItem.sitemapRootNodeId = dataItem.data["SiteMapRootNodeId"];
        return chipItem;
    }

    static fromSiteData = (siteData: SiteData): SiteSelectorItem => {
        const siteModel = new SiteSelectorItem();
        siteModel.Title = siteData.Name;
        siteModel.value = siteData.Id;
        siteModel.defaultCulture = <SiteSelectorItem>{
            Title: siteData.DefaultContentCulture,
            value: siteData.DefaultContentCulture
        };
        siteModel.cultures = siteData.ContentCultures.map(c => <SelectorItem>{ Title: c.DisplayName, value: c.Name });
        siteModel.sitemapRootNodeId = siteData.SiteMapRootNodeId;
        return siteModel;
    }
}
