import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Injectable } from "@angular/core";
import { FieldBase } from "../../../../../fields/field-base";
import { ChoiceYesNoComponent } from "../../../../../fields/choice/choice-yesno.component";

@Injectable()
export class MultipleChoiceWidgetFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === "Choices") {
            this.processSelectedChoiceFieldChange(changedValue, fields.map(x => x.currentInstance));
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === "MultipleChoice";
    }

    private processSelectedChoiceFieldChange(changedValue: any, fields: FieldBase[]) {
        const requiredField = this.getRequiredField(fields);
        if (requiredField) {
            const hasSelectedChoice = Object.values<any>(changedValue).find(x => x.Selected === true);
            if (hasSelectedChoice) {
                requiredField.settings.readOnlyMode = true;
                if (requiredField.getValue() === true) {
                    requiredField.onSelectionChange(undefined);
                }
            } else {
                requiredField.settings.readOnlyMode = false;
            }
        }
    }

    private getRequiredField(fields: FieldBase[]): ChoiceYesNoComponent {
        const field = fields.find(x => x.settings.key === "Required");
        if (field && field instanceof ChoiceYesNoComponent) {
            return field;
        }

        return null;
    }
}

export const MULTIPLE_CHOICE_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: MultipleChoiceWidgetFieldsChangeService,
    multi: true
};
