import { createAction, props } from "@ngrx/store";
import { SidebarData, SidebarConfig } from "../../../modules/shared/components/sidebar/sidebar.common";
import { StoredComponentsDataCache } from "../cache/dynamic-loader-components-cache";

const SidebarConfigureAction = createAction(
    "[Sidebar] Change config",
    props<{ sidebarData: SidebarData }>()
);

const SidebarChangedAction = createAction(
    "[Sidebar] Change sidebar",
    props<{ activeConfig: SidebarConfig }>()
);

const SidebarOpenAction = createAction(
    "[Sidebar] Open"
);

const SidebarCloseAction = createAction(
    "[Sidebar] Close",
    props<{ shouldAnimate: boolean, shouldClearLocalStorageForSidebar: boolean }>()
);

const SidebarLoadingAction = createAction(
    "[Sidebar] Loading"
);

const SidebarChangeAndOpenAction = createAction(
    "[Sidebar] Change and open",
    props<{ activeConfig: SidebarConfig, shouldAnimate: boolean }>()
);

const SidebarSetShouldAnimateAction = createAction(
    "[Sidebar] Change Sidebar ShouldAnimate",
    props<{ shouldAnimate: boolean }>()
);

/**
 * Internal action for clearing the full sidebar state, intended for testing scenarios
 */
export const SidebarClearAllDataAction = createAction(
    "[Sidebar] Clear full state"
);

/**
 * Internal aciton when active config is changed
 */
// eslint-disable-next-line @typescript-eslint/naming-convention,no-underscore-dangle,id-blacklist,id-match
export const __SidebarChangeInternalAction__ = createAction(
    "[Sidebar]  Change sidebar internal",
    props<{ activeConfig: SidebarConfig }>()
);

/**
 * Internal action when the sidebar data is changed
 */
// eslint-disable-next-line @typescript-eslint/naming-convention, no-underscore-dangle, id-blacklist, id-match
export const __SidebarConfigInternalAction__ = createAction(
    "[Sidebar] Change config internal",
    props<{ sidebarData: SidebarData }>()
);

/**
 * !For use only in the store module
 * Full map of available sidebarActions
 */
export const SIDEBAR_ACTIONS = {
    configure: SidebarConfigureAction,
    change: SidebarChangedAction,
    open: SidebarOpenAction,
    close: SidebarCloseAction,
    loading: SidebarLoadingAction,
    changeAndOpen: SidebarChangeAndOpenAction,
    setShouldAnimate: SidebarSetShouldAnimateAction
};

/**
 * Full TYPED map for dispatching sidebar feature actions
 */
export const SIDEBAR_DISPATCH_ACTION = {
    /**
     * Dispatch sidebar data change action
     * @param sidebarData: SidebarData
     */
    configure: (sidebarData: SidebarData) => {
        const newData = Object.assign({}, sidebarData);
        const newButtons = newData.buttons.map(button => {
            const newButton = Object.assign({}, button);
            StoredComponentsDataCache.set(newButton.name, newButton.data);
            newButton.data = null;
            return newButton;
        });
        newData.buttons = newButtons;
        return SIDEBAR_ACTIONS.configure({ sidebarData: newData });
    },
    /**
     * Dispatch current activeConfig change
     * @param activeConfig: SidebarConfig
     */
    change: (activeConfig: SidebarConfig) => {
        const newConfig = Object.assign({}, activeConfig);
        StoredComponentsDataCache.set(newConfig.name, newConfig.data);
        newConfig.data = null;
        return SIDEBAR_ACTIONS.change({ activeConfig: newConfig });
    },
    /**
     * Dispatch close sidebar action specifying whether to animate and/or clear the data for the opened sidebar from the local storage
     */
    close: (shouldAnimate: boolean = true, shouldClearLocalStorageForSidebar: boolean = true) => SIDEBAR_ACTIONS.close({ shouldAnimate, shouldClearLocalStorageForSidebar }),
    /**
     * Dispatch setting isLoading = true when executing external operation from the sidebar
     */
    loading: () => SIDEBAR_ACTIONS.loading(),
    /**
     * Dispatch combined open and change activeConfig action
     * @param activeConfig: SidebarConfig
     */
    changeAndOpen: (activeConfig: SidebarConfig, shouldAnimate: boolean) => {
        const newConfig = Object.assign({}, activeConfig);
        StoredComponentsDataCache.set(newConfig.name, newConfig.data);
        newConfig.data = null;
        return SIDEBAR_ACTIONS.changeAndOpen({ activeConfig: newConfig, shouldAnimate: shouldAnimate });
    }
};
