import { Command } from "../../../../../shared/commands/command";
import { Injectable } from "@angular/core";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { throwError as observableThrowError, Observable, of, empty } from "rxjs";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DialogData, ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { DynamicItemService } from "../../dynamic-item.service";
import { ViewAllImageSizesComponent } from "../../../../../libraries/images/view-all-sizes/view-all-image-sizes.component";
import { ToolbarComponent } from "../../../components/dialog/toolbar.component";
import { Router } from "@angular/router";
import { ROUTE_PATHS } from "../../../../../../constants/route-paths";
import * as HTTP_STATUS_CODES from "http-status-codes";
import { catchError } from "rxjs/operators";

@Injectable()
export class ViewAllImageSizesCommand implements Command {
    constructor(
        private modalWindowService: ModalWindowService,
        private dynamicItemService: DynamicItemService,
        private router: Router) {
    }

    execute(context: ExecutionContext): Observable<any> {
        this.dynamicItemService.executeBoundFunction(context.data.dataItem, "Default.GetThumbnails()")
        .pipe(catchError((error: any) => {
            if (error.statusCode === HTTP_STATUS_CODES.FORBIDDEN) {
                this.router.navigate([ROUTE_PATHS.ACCESS_DENIED]);
                return empty();
            }

            return observableThrowError(error);
        }))
        .subscribe((data: any) => {
            const componentData: ComponentData = {
                type: ViewAllImageSizesComponent,
                properties: {
                    thumbnails: data.value,
                    imageTitle: context.data.dataItem.title
                }
            };

            const dialogData = new DialogData(componentData, null, []);
            dialogData.toolbarData = {
                type: ToolbarComponent,
                properties: {
                    header: `All image sizes`
                }
            };
            this.modalWindowService.setMapping(dialogData, "viewallimagesizes");
            this.modalWindowService.show("viewallimagesizes", context.currentRoute.parent);
        });

        return of(true);
    }
}
