import { ComponentData } from "@progress/sitefinity-component-framework";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

export interface FormRule {
    Operator: FormRuleOperatorCRUD,
    Conditions: FormRuleCondition[],
    Actions: FormRuleAction[]
}

export interface FormRuleCondition {
    Id: string,
    Operator: string,
    Value: string
}

export interface FormRuleAction {
    Target: string,
    Action: string
}

export interface FormField {
    Id: string,
    Title: string,
    Type: string,
    InputType: string,
    Operators: Operator[],
    Values: ChoiceItem[],
    Hideable: boolean
}

export interface FormDefinition {
    Id: string,
    Name: string,
    Fields: FormField[],
    Rules: FormRule[],
    AvailableActions: AvailableAction[],
    Steps: FormStep[],
    Culture: string,
    Hideable: boolean,
    Renderer: string
}

export interface AvailableAction {
    Key: string,
    Value: string
}

export interface FormStep {
    Key: string,
    Value: string
}

export interface Operator {
    Key: string,
    Value: string
}

export interface FormFieldTypeData {
    component: ComponentData;
    tooltip?: TooltipContent;
    cssClassList?: string;
}

export interface TooltipContent {
    title?: string;
    message: string;
}

export enum FormRuleOperatorList {
    Or = "or",
    And = "and"
}

export enum FormRuleOperatorCRUD {
    Any = "Or",
    All = "And"
}

