import { map } from "rxjs/operators";
import { Component, OnInit, Output, Input, EventEmitter, SimpleChanges, OnChanges, Inject, HostListener } from "@angular/core";
import { Observable, ReplaySubject, Subscription } from "rxjs";
import { LOADING_TIME } from "../../../../constants";
import { FilterStore } from "./filter.store";
import { EntityData } from "../../../interfaces";
import { FiltersResult, ComplexFilter } from "./filter-interfaces";
import { delayEmission } from "../../../../../shared/rxjs-extensions";
import { toKebabCase } from "../../../../../../utils";
import { CustomFilterRenderer } from "./filter-renderers/custom-filter.renderer";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";

export const ON_RELOAD_CONTENT_FILTER_EVENT_NAME = "onReloadContentFilters";

@Component({
    selector: "sf-content-filter",
    templateUrl: "./content-filter.component.html"
})
export class ContentFilterComponent extends SfRxBase implements OnInit, OnChanges {
    @Input() entityData: EntityData;
    @Input() displayName: string;
    @Input() disableLoader: boolean;
    @Input() loadFiltersCount: Observable<void>;

    @Input() set filterValue(value: string) {
        this._filterValue = value || null;
    }

    get filterValue(): string {
        return this._filterValue;
    }

    @Output() filterSelect = new EventEmitter<string>();

    contentFiltersResult$: Observable<FiltersResult>;
    complexFiltersComponents: ComponentData[] = [];
    loadComplexFiltersSubscription: Subscription;

    private dynamicFiltersCountByCategory: { [key: string]: number } = {};
    private dynamicFiltersTotalCount: number = 0;
    private filterResult$ = new ReplaySubject<FiltersResult>();
    private getFiltersSubscription: Subscription;
    private _filterValue: string;

    constructor(
        @Inject(CustomFilterRenderer) private customFilterRenderers: CustomFilterRenderer[],
        private filterStore: FilterStore) {
        super();
        this.contentFiltersResult$ = this.filterResult$
            .pipe(
                delayEmission(LOADING_TIME),
                map(r => this.manageFilterList(r))
            );
    }

    ngOnInit(): void {
        this.loadFilters(this.entityData);
    }

    ngOnChanges(changes: SimpleChanges): void {
        const entityDataChange = changes["entityData"];

        if (entityDataChange && !entityDataChange.isFirstChange()) {
            this.loadFilters(entityDataChange.currentValue);
        }
    }

    showFilters(contentFiltersResult: FiltersResult) {
        return contentFiltersResult.filters.length > 1 || this.dynamicFiltersTotalCount > 0;
    }

    onFilterSelect(filter: string): void {
        this.filterValue = filter;
        this.filterSelect.emit(this.filterValue);
    }

    generateFilterWrapperCssClassList(category): string {
        if (category) {
            return " -" + toKebabCase(category);
        }
        return "";
    }

    loaderInit(event: ComplexFilter) {
        const applyComplexFilterSubscription: Subscription = event.filterSelect.subscribe((filterTitle: string) => {
            this.onFilterSelect(filterTitle);
        });

        this.registerSubscription(applyComplexFilterSubscription);

        const filtersChangesSubscription: Subscription = event.filtersChanged.subscribe(filters => {
            const filterCategory = event.category;
            this.dynamicFiltersCountByCategory[filterCategory] = filters ? filters.length : 0;
            this.dynamicFiltersTotalCount = Object.values(this.dynamicFiltersCountByCategory).reduce((a, b) => b ? a + b : a, 0);
        });

        this.registerSubscription(filtersChangesSubscription);
    }

    @HostListener(`window:${ON_RELOAD_CONTENT_FILTER_EVENT_NAME}`, ["$event.detail"])
    loadFilters(entityData: EntityData): void {
        if (this.getFiltersSubscription) {
            this.getFiltersSubscription.unsubscribe();
        }

        this.getFiltersSubscription = this.filterStore
            .getPredefinedFilters(entityData)
            .subscribe((r) => this.filterResult$.next(r));

        this.registerSubscription(this.getFiltersSubscription);
    }

    private manageFilterList(contentFiltersResult: FiltersResult): FiltersResult {
        const { isLoading, filters } = contentFiltersResult;
        const hasFilters = filters && filters.length;

        if (!isLoading && hasFilters) {
            let filtersCopy = filters.slice();

            filtersCopy = filtersCopy.map(filter => {
                const returnObj = {
                    title: filter.title,
                    name: filter.name,
                    cssClass: this.generateFilterWrapperCssClassList(filter.category),
                    parameters: filter.parameters,
                    category: filter.category,
                    isDynamicFilter: filter.isDynamicFilter
                };

                return returnObj;
            });

            const displayName = this.displayName ? this.displayName : this.entityData.metadata.displayName;
            if (this.entityData.metadata.hasAllItemsFilterEnabledProperty) {
                filtersCopy.unshift({
                    title: `All ${displayName.toLocaleLowerCase()}`,
                    name: null
                });
            }

            const simpleFilters = filtersCopy.filter(f => !f.isDynamicFilter);
            const dynamicFilters = filtersCopy.filter(f => f.isDynamicFilter);

            if (dynamicFilters.length) {
                const filtersByCategory = dynamicFilters.reduce((r, a) => {
                    r[a.category] = [...r[a.category] || [], a];
                    return r;
                }, {});

                this.initDynamicFilters(filtersByCategory);
            }

            return {
                isLoading: isLoading,
                filters: simpleFilters
            };
        }

        return contentFiltersResult;
    }

    private initDynamicFilters(filters: object): void {
        this.complexFiltersComponents = [];
        for (const renderer of this.customFilterRenderers) {
            const rendererCategory = renderer.getCategory();

            for (const key of Object.keys(filters)) {
                if (rendererCategory === key) {
                    this.complexFiltersComponents.push(renderer.initComponentData(filters[key], this.entityData, this.loadFiltersCount));
                }
            }
        }
    }
}
