import { FormGroup, AbstractControl } from "@angular/forms";
import { EVENT_PROPERTIES } from "../events.constants";

export const INVALID_EVENT_END_DATE = "invalidEventEnd";

export class EventsDateTimeValidator {
    static validate(control: FormGroup): any {
        const eventStartField: AbstractControl = control.controls[EVENT_PROPERTIES.EVENT_START];
        const eventEndField: AbstractControl = control.controls[EVENT_PROPERTIES.EVENT_END];

        if (eventStartField && eventEndField) {
            const startDate = eventStartField.value;
            const endDate = eventEndField.value;
            if (startDate && endDate) {
                const startDateObj = new Date(startDate);
                const endDateObj = new Date(endDate);

                const allDayField = control.controls[EVENT_PROPERTIES.ALL_DAY_EVENT];
                if (allDayField && allDayField.value) {
                    startDateObj.setHours(0, 0, 0, 0);
                    endDateObj.setHours(0, 0, 0, 0);
                }

                if (endDateObj.getTime() < startDateObj.getTime()) {
                    return {
                        [INVALID_EVENT_END_DATE]: true
                    };
                }
            }
        }

        return null;
    }
}
