import { Component, Inject, OnDestroy, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { Observable } from "rxjs";
import { ComponentData } from "../../../../api/v1/index-component/component-data";
import { ITEM_EDIT_NOTIFICATION_FILTER_STATIC, RESOLVE_NAMES } from "../../../content/constants";
import { BasicEditorViewComponent } from "../../../widget-editor/basic-editor.component";
import { WidgetMetadata } from "../../../widget-editor/interfaces/widget-editor";
import { CanCloseModal, ClosingContext } from "../../services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../services/notification/notification.service";

@Component({
    selector: "sf-list-detail",
    templateUrl: "./list-detail.component.html"
})
export class ListDetailComponent implements OnInit, CanCloseModal, OnDestroy {

    editorComponent: BasicEditorViewComponent;
    editorComponentData: ComponentData;
    editorMetadata: WidgetMetadata;

    constructor(@Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService, private route: ActivatedRoute) { }

    ngOnInit(): void {
        if (this.editorMetadata) {
            const entityData = this.route.parent.snapshot.data[RESOLVE_NAMES.entityData];
            this.route.snapshot.data[RESOLVE_NAMES.itemData] = { entityData: this.editorMetadata.propertyValues };
            this.editorComponentData = {
                type: BasicEditorViewComponent,
                afterComponentInit: (component: BasicEditorViewComponent) => {
                    component.initialize(this.editorMetadata);
                    this.editorComponent = component;
                },
                properties: {
                    shouldHaveTopPadding: false,
                    context: {
                        isQuickEdit: false,
                        widgetName: entityData?.metadata?.setName
                    }
                }
            };
        }
    }

    canCloseCallback(context: ClosingContext): boolean | Observable<boolean> {
        return true;
    }

    ngOnDestroy(): void {
        this.notificationService.close(ITEM_EDIT_NOTIFICATION_FILTER_STATIC);
    }
}
