import { FactoryProvider } from "@angular/core";
import { ConsoleLoggerSource } from "./console-logger-source";
import { BackendLoggerSource } from "./backend-logger-source";
import { LoggerSource } from "./logger-source";
import { HttpWebRequestWrapper } from "../http-web-request.wrapper";
import { environmentTypes } from "../../../../environment";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { environment } from "../../../../../environments/environment";

export const LOGGER_SOURCE_PROVIDERS: FactoryProvider = {
    provide: LoggerSource,
    useFactory: loggerFactory,
    deps: [HttpWebRequestWrapper, WINDOW_TOKEN]
};

export function loggerFactory(http: HttpWebRequestWrapper, wndw: typeof window)  {
    const consoleLoggerSource = new ConsoleLoggerSource(wndw);
    const sources: Array<LoggerSource> = [consoleLoggerSource];

    if (environment.env === environmentTypes.integration) {
        const backendLoggerSource = new BackendLoggerSource(http);
        sources.push(backendLoggerSource);
    }

    return sources;
}
