import { Directive, ElementRef, Input, OnInit, OnChanges, OnDestroy, Inject, HostListener, Renderer2, SimpleChanges } from "@angular/core";
import { WINDOW_TOKEN } from "../../../src/app/window.provider";

export const STICKY_MIN_SCROLL_VALUE = 150;
const STICKY_CLASS_NAME = "sf-sticky";
const TIMEOUT_INTERVAL = 200;
const STICKY_BODY_CLASS = "-" + STICKY_CLASS_NAME;

@Directive({
    selector: "[sfSticky]",
    exportAs: "sfSticky"
})
export class StickyDirective implements OnInit, OnDestroy, OnChanges {
    @Input() stickyDisabled: boolean = false;
    @Input() stickWithDelay: boolean = true;
    @Input() alwaysSticky: boolean = false;
    @Input("stickyPosition") set stickyPosition(position: any) {
        this.position = position || this.position;
    }
    @Input("stickyScrollMin") set stickyScrollMin(min: number) {
        this.scrollMin = min || this.scrollMin;
    }

    isSticky: boolean = false;
    readonly className: string = STICKY_CLASS_NAME;
    private scrollMin: number = STICKY_MIN_SCROLL_VALUE;
    private position: string = "top";
    private typeClass: string;
    private timeoutId: number = null;

    constructor(private element: ElementRef,
                @Inject(WINDOW_TOKEN) private window: Window,
                private renderer: Renderer2) {
    }

    ngOnInit() {
        this.typeClass = `-${this.position}`;
    }

    ngOnChanges(changes: SimpleChanges) {
        const stickyDisabledChange = changes["stickyDisabled"];
        const alwaysStickyChange = changes["alwaysSticky"];

        if (alwaysStickyChange && this.alwaysSticky) {
            this.isSticky = true;
        }

        if (stickyDisabledChange && !stickyDisabledChange.previousValue !== !stickyDisabledChange.currentValue) {
            this.updateSticky(false);
        }
    }

    ngOnDestroy () {
        this.renderer.removeStyle(this.window.document.body, "min-height");
        this.renderer.removeClass(this.window.document.body, STICKY_BODY_CLASS);
    }

    @HostListener("window:scroll", [])
    onWindowScroll() {
        if (!this.stickyDisabled && !this.alwaysSticky) {
            if (this.stickWithDelay) {
                if (this.timeoutId !== null)
                    return;
                this.timeoutId = this.window.setTimeout(() => {
                    this.calculateScrollAndUpdateSticky();
                    this.timeoutId = null;
                }, TIMEOUT_INTERVAL);
            } else {
                this.calculateScrollAndUpdateSticky();
            }
        }
    }

    private calculateScrollAndUpdateSticky () {
        const scrollElementHeight = this.window.document.documentElement.clientHeight;
        const scrollElementScrollHeight = this.window.document.documentElement.scrollHeight;
        const pageYOffset = this.window.pageYOffset;
        const oldIsSticky = this.isSticky;
        const newIsSticky = (this.position === "top" && (pageYOffset > this.scrollMin)) || (this.position === "bottom" && (scrollElementScrollHeight > scrollElementHeight));

        if (oldIsSticky !== newIsSticky) {
            this.updateSticky(newIsSticky);
        }
    }

    private updateSticky (isSticky: boolean) {
        this.isSticky = isSticky;
        const bodyElement = this.window.document.body;

        if (isSticky) {
            this.stick(bodyElement);
        } else {
            this.unstick(bodyElement);
        }
    }

    private stick(bodyElement: HTMLElement) {
        this.element.nativeElement.classList.add(this.className, this.typeClass);
        this.renderer.addClass(this.window.document.body, STICKY_BODY_CLASS);
        this.renderer.setStyle(bodyElement, "min-height", `calc(100vh + ${this.scrollMin + 1}px)`);
        if (this.window.pageYOffset <= this.scrollMin) {
            this.window.scrollTo(0, this.scrollMin + 1);
        }
    }

    private unstick(bodyElement: HTMLElement) {
        this.element.nativeElement.classList.remove(this.className, this.typeClass);
        this.renderer.removeClass(this.window.document.body, STICKY_BODY_CLASS);
        this.renderer.removeStyle(bodyElement, "min-height");
        if (this.window.pageYOffset >= this.scrollMin) {
            this.window.scrollTo(0, this.scrollMin - 1);
        }
    }

}
