export interface ColumnState {
    /**
     * @description Stores data for columns expanded per item, the first key
     * is the entity set, the second one is the column, the third one the item id and
     * the value is a value indicating whether the column is expanded/collapsed
     * @type {Map<string, Map<string, Map<string, boolean>>>}
     */
    expandedColumnsPerItem: { [key: string]: { [key: string]: { [key: string]: boolean } } }


    /**
     * @description Stores data indicating whether a column is expanded
     * per entity set, the key is the entitySet and the value is a list of expanded columns
     * @type {Map<string, string>}
     */
    expandedColumnsPerEntity: { [key: string]: string[] }
}

export const columnsInitialState: ColumnState = {
    expandedColumnsPerItem: {},
    expandedColumnsPerEntity: {}
};
