import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Router } from "@angular/router";
import { BaseResolver } from "../../components/dynamic-items-base.resolver";
import { Settings } from "../../../../shared/services/settings.service";
import { EntityData } from "../../interfaces";
import { VIEW_NAME, ROUTE_PARAMS } from "../../../constants";
import { ProviderStore } from "../provider-store";
import { BackendTweaksStore } from "./backend-tweaks.store";
import { CompositeEntityDataResolver } from "./entity-data.resolver";

@Injectable()
export class BackendTweaksFormResolver extends BaseResolver {

    constructor(
        private tweaksStore: BackendTweaksStore,
        service: ProviderStore,
        router: Router,
        settings: Settings,
        entityDataResolver: CompositeEntityDataResolver) {
        super(service, router, settings, entityDataResolver);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Promise<Array<any>> {
        const entityData = super.resolve(route, state) as EntityData;
        let viewName = VIEW_NAME.EDIT;
        if (!route.params.id) {
            viewName = VIEW_NAME.INSERT;
        } else if (route.url.length === 2 && route.url[1].path === VIEW_NAME.DUPLICATE) {
            viewName = VIEW_NAME.DUPLICATE;
        }

        return this.tweaksStore.initializeForm(entityData.metadata.setName, viewName, route.params[ROUTE_PARAMS.ITEM_ID], entityData.provider, entityData.culture)
            .then(() => this.tweaksStore.getFormByType(entityData.metadata.setName, viewName));
    }
}
