import { Component, ViewChild, Input, Inject, ElementRef } from "@angular/core";
import { TreeWrapperComponent } from "../../../../../../../fields";
import { Observable, Subscription, timer } from "rxjs";
import { KEYS, TreeNode } from "@circlon/angular-tree-component";
import { ComponentModel, ContainerModel } from "../model/component-model";
import { SfRxBase, stringConstants, TreeConfigBase } from "@progress/sitefinity-component-framework";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { DOCUMENT_TOKEN } from "../../../../../document.provider";
import { PropertyEditorWidgets } from "../../../../widget-editor/property-editor.constants";
import { IDTypeDictionary } from "@circlon/angular-tree-component/lib/defs/api";

export const CONTENT_EDITABLE_ATTRIBUTE = "contentEditable";
const EDITABLE_CLASS = "-editable";
const NODE_WRAPPER_SELECTOR = ".node-wrapper";
const TREE_SIDEBAR_ITEM_SELECTOR = ".sf-tree__item-title";
const BLOCK_CLASS = "-sf-block";
const NOT_DRAGGABLE_CLASS = "-not-draggable";
const IS_DRAGGING_PROPERTY = "__sf__isDragging"
const EXPANDABLE_CLASS = "-expandable";

@Component({
    templateUrl: "./tree-sidebar.component.html"
})
export class TreeSidebarComponent extends SfRxBase {
    @ViewChild(TreeWrapperComponent, { static: false }) tree: TreeWrapperComponent;
    @ViewChild("tree", { read: ElementRef, static: false }) private treeWrapper: ElementRef;
    @Input() public selectComponent: (widgetId: string) => void;
    @Input() public editWidgetLabel: (widgetId: string, label: string) => void;
    @Input() public addWidget: (parentWidgetId: string) => void;
    @Input() public moveWidget: (widgetId: string, parentWidgetId: string, index: number) => void;
    @Input() activeComponent: Observable<string>;
    @Input() treeModelChange: Observable<ComponentModel[]>;
    @Input() emptyMessageLabel: string;

    nodes: SidebarTreeNodeModel[] = [];
    selectedNode: string;
    treeConfig: TreeConfigBase = {
        noSelection: false,
        multiSelection: false,
        isHierarchical: false,
        status: true,
        drag: (node: TreeNode) => {
            return node.data.moveAllowed;
        },
        drop: (element: TreeNode, to: { parent: TreeNode, index: number }): boolean => {
            this.handleExpandOnDragover(to.parent);

            const isRootDropAllowed = to.parent.parent === null && this.rootLevelDropAllowed;
            const isColumn = to.parent.data.name === PropertyEditorWidgets.SECTION_COLUMN;
            const isSection = to.parent.data.name === PropertyEditorWidgets.SECTION || to.parent.data.name === PropertyEditorWidgets.FORM_SECTION;
            const hasMoreThanOneColumn = to.parent.hasChildren && to.parent.children[0].data.name === PropertyEditorWidgets.SECTION_COLUMN;
            const addAllowed = to.parent.data.addAllowed;
            return isRootDropAllowed || ((isColumn || (isSection && !hasMoreThanOneColumn)) && addAllowed);
        },
        skipNodeMappingToDefaultModel: true,
        clickable: true,
        treeProperties: {
            idField: "id",
            displayField: "title",
            actionMapping: <any>{
                mouse: {
                    click: (tree, node, $event) => {
                        this.onTreeNodeClicked(node);
                        $event.stopImmediatePropagation();
                        $event.stopPropagation();
                    },
                    dragStart: (tree, node) => {
                        node.data[IS_DRAGGING_PROPERTY] = true;
                    },
                    dragEnd: (tree, node) => {
                        node.data[IS_DRAGGING_PROPERTY] = false;
                    }
                },
                keys: {
                    [KEYS.LEFT]: null,
                    [KEYS.RIGHT]: null,
                    [KEYS.UP]: null,
                    [KEYS.DOWN]: null,
                    [KEYS.ENTER]: null,
                    [KEYS.SPACE]: null,
                }
            }
        }
    } as any;
    showEmptyMessageLabel: boolean = false;
    saveButtonVisible = false;
    revertButtonVisible = false;
    hoveredWidgetId: string;

    private isInitialized: boolean;
    private alwaysExpandedNodesIds: IDTypeDictionary;
    private previousLabel: string;
    private previousMoveEvent;
    private hideRevertButtonSubscription: Subscription;
    private dragTimeoutId;
    private previousDropParent: TreeNode;
    private rootLevelDropAllowed = true;
    private isMoveLastOperation: boolean;

    constructor(@Inject(WINDOW_TOKEN) private window: Window,
                @Inject(DOCUMENT_TOKEN) private document: Document) {
        super();
    }

    onInitialized() {
        const activeComponentSubscription = this.activeComponent.subscribe((id) => {
            this.selectNode(id);
        });

        this.registerSubscription(activeComponentSubscription);

        const treeModifiedSubscription = this.treeModelChange.subscribe((change) => {
            this.nodes.splice(0, this.nodes.length);
            this.alwaysExpandedNodesIds = {};
            change.forEach((x) => this.buildNodesCollection(null, x));
            this.showEmptyMessageLabel = this.nodes.length === 0;

            this.tree.updateTreeModel();
            if (!this.isInitialized) {
                this.tree.expandAllNodes();
                this.isInitialized = true;
            } else {
                const newExpandedNodes = Object.assign({}, this.tree.getExpandedNodes(), this.alwaysExpandedNodesIds);
                this.tree.setExpandedNodes(newExpandedNodes);
            }

            this.selectNode(this.selectedNode);
            this.showExpanders();
        });

        this.registerSubscription(treeModifiedSubscription);
    }

    onTreeNodeClicked(node: TreeNode) {
        this.selectNode(node.data.id);
        this.selectComponent(node.data.id);
        this.hideRevertButton();
    }

    onDoubleClick(event: Event, node: TreeNode) {
        if (node.data.editAllowed) {
            this.selectComponent(node.id);
            this.saveButtonVisible = true;
            this.hideRevertButton();
            const currentTarget = event.currentTarget as HTMLElement;
            const element: HTMLElement = currentTarget.querySelector(TREE_SIDEBAR_ITEM_SELECTOR);
            this.toggleEditableClass(currentTarget);
            this.previousLabel = element.innerText;
            element.setAttribute(CONTENT_EDITABLE_ATTRIBUTE, stringConstants.EMPTY_STRING);
            element.focus();
            this.setCaretAtEnd(element);
        }
    }

    toggleEditableClass(referenceElement: HTMLElement, add = true) {
        const nodeWrapper: HTMLElement = referenceElement.closest(NODE_WRAPPER_SELECTOR);

        if (nodeWrapper) {

            if (add) {
                nodeWrapper.classList.add(EDITABLE_CLASS);
            } else {
                nodeWrapper.classList.remove(EDITABLE_CLASS);
            }
        }
    }

    onMouseEnterOrLeave(widgetId: string) {
        this.hoveredWidgetId = widgetId;
    }

    onBlur(event: Event, widgetId: string) {
        this.saveButtonVisible = false;

        const element: HTMLElement = event.target as HTMLElement;
        element.removeAttribute(CONTENT_EDITABLE_ATTRIBUTE);
        this.toggleEditableClass(element, false);
        this.updateNode(widgetId, this.previousLabel);
    }

    onSave(event: Event, widgetId: string) {
        let newLabel: string;
        if (event.type === "mousedown") {
            const button: HTMLElement = event.currentTarget as HTMLElement;
            newLabel = (button.parentElement.previousElementSibling as HTMLElement).innerText.replace(/&nbsp;/g, " ").replace(/\u00A0/g, " ");
        } else {
            event.preventDefault();
            newLabel = (event.target as HTMLElement).innerText.replace(/&nbsp;/g, " ").replace(/\u00A0/g, " ");
        }

        this.saveButtonVisible = false;

        if (newLabel !== stringConstants.EMPTY_STRING && newLabel !== this.previousLabel) {
            this.editWidgetLabel(widgetId, newLabel);
            this.showRevertButton();
            this.updateNode(widgetId, newLabel);
        }
    }

    onRevert(widgetId: string) {
        if (this.isMoveLastOperation) {
            let index: number = this.previousMoveEvent.from.index;
            if (this.previousMoveEvent.to.parent.id === this.previousMoveEvent.from.parent.id && this.previousMoveEvent.to.index < this.previousMoveEvent.from.index) {
                index++;
            }

            this.moveWidget(this.previousMoveEvent.node.id, this.previousMoveEvent.from.parent.virtual ? null : this.previousMoveEvent.from.parent.id, index);
        } else {
            this.editWidgetLabel(widgetId, this.previousLabel);
            this.updateNode(widgetId, this.previousLabel);
        }

        this.hideRevertButton();
    }

    onMoveNode(event) {
        let index: number = event.to.index;
        if (event.from.parent.id === event.to.parent.id && event.from.index < event.to.index) {
            index++;
        }

        this.previousMoveEvent = event;
        this.moveWidget(event.node.id, event.to.parent.virtual ? null : event.to.parent.id, index);
        this.tree.setExpandedNode(event.to.parent.id);
        this.selectNode(event.node.id);
        this.showRevertButton(true);
    }

    onAddWidget(nodeId: string) {
        this.addWidget(nodeId);
        console.log(nodeId);
        this.tree.setExpandedNode(nodeId);
    }

    isAddButtonVisible(node) {
        const isSectionOrColumn = node.data.name === PropertyEditorWidgets.SECTION_COLUMN ||
                                node.data.name === PropertyEditorWidgets.SECTION ||
                                node.data.name === PropertyEditorWidgets.FORM_SECTION;
        const nodeIsFocusedOrHovered = node.isFocused || node.id === this.hoveredWidgetId;
        const nodeIsEditable = node.isFocused && (this.saveButtonVisible || this.revertButtonVisible);
        const canAdd = node.data.addAllowed;

        return isSectionOrColumn && nodeIsFocusedOrHovered && !nodeIsEditable && canAdd;
    }

    isDragHandleVisible(node: TreeNode) {
        const isNodeFocusedOrHovered = node.isFocused || node.id === this.hoveredWidgetId;
        const nodeIsBeingEdited = node.isFocused && this.saveButtonVisible;

        return isNodeFocusedOrHovered && !nodeIsBeingEdited && (this.treeConfig as any).drag(node);
    }

    showExpanders() {
        // we are using an interval because nodes are not rendered on initialized
        // increased interval to 10ms, because some does aren't rendered when we add classes to them
        if (this.nodes.length > 0) {
            const intervalId = setInterval(() => {
                const treeNodeWrappers = this.treeWrapper.nativeElement.querySelectorAll("tree-node-wrapper");
                if (treeNodeWrappers.length > 0) {
                    clearInterval(intervalId);

                    treeNodeWrappers.forEach(nodeWrapper => {
                        const expander = nodeWrapper.querySelector("tree-node-expander");

                        if (nodeWrapper.querySelector("div[role='treeitem'][data-expandable='true']")) {
                            expander.classList.add(BLOCK_CLASS);
                            nodeWrapper.classList.add(EXPANDABLE_CLASS);
                        } else {
                            if (nodeWrapper.classList.contains(EXPANDABLE_CLASS)) {
                                nodeWrapper.classList.remove(EXPANDABLE_CLASS);
                            }

                            if (expander.classList.contains(BLOCK_CLASS)) {
                                expander.classList.remove(BLOCK_CLASS);
                            }

                        }
                        const nodeRow = nodeWrapper.querySelector("div[role='treeitem'].sf-tree__row");                        
                        if (nodeRow && nodeRow.dataset.moveAllowed && (nodeRow.dataset.moveAllowed === false || nodeRow.dataset.moveAllowed === 'false')) {
                            nodeWrapper.classList.add(NOT_DRAGGABLE_CLASS);
                        } else if (nodeWrapper.classList.contains(NOT_DRAGGABLE_CLASS)) {
                            nodeWrapper.classList.remove(NOT_DRAGGABLE_CLASS);
                        }
                        
                        if (nodeWrapper.querySelector("div[role='treeitem'][data-move-allowed='false']")) {
                            nodeWrapper.classList.add(NOT_DRAGGABLE_CLASS);
                        }
                    });
                }
            }, 10);
        }
    }

    private updateNode(nodeId: string, label: string) {
        const predicate = function (node) { return node.data.id.toString() === nodeId; };
        const treeNode = this.tree.getNodeBy(predicate);
        treeNode.hide();
        treeNode.data.title = label;
        treeNode.show();
        this.showExpanders();
    }

    private setCaretAtEnd(node: Node) {
        const range = this.document.createRange();
        range.selectNodeContents(node);
        range.collapse(false);
        const sel = this.window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
    }

    private selectNode(id: string) {
        if (id) {
            this.selectedNode = id;
            //TODO: Remove when this is in: https://prgs-sitefinity.visualstudio.com/sitefinity/_git/iris/pullrequest/3634
            const predicate = function (node) { return node.data.id.toString() === id; };
            const treeNode = this.tree.getNodeBy(predicate);
            if (treeNode) {
                this.tree.selectAndActivateNodeById(treeNode.id);
            }
        } else {
            this.selectedNode = id;
            this.tree.clearAllSelectedNodes();
        }
    }

    private showRevertButton(isMoveExecuted: boolean = false) {
        this.isMoveLastOperation = isMoveExecuted;
        this.hideRevertButtonSubscription = timer(6000).subscribe(() => this.revertButtonVisible = false );
        this.registerSubscription(this.hideRevertButtonSubscription);
        this.revertButtonVisible = true;
    }

    private hideRevertButton() {
        this.hideRevertButtonSubscription?.unsubscribe();
        this.revertButtonVisible = false;
    }

    private buildNodesCollection(parentNode: SidebarTreeNodeModel, childNode: ComponentModel | ContainerModel) {
        let nodeToAdd: SidebarTreeNodeModel;
        if(childNode instanceof ComponentModel) {
            nodeToAdd = {
                id: childNode.id,
                title: childNode.title,
                name: childNode.name,
                expandable: false,
                children: [],
                addAllowed: childNode.addAllowed,
                editAllowed: childNode.editAllowed && childNode.name !== PropertyEditorWidgets.FORM_SECTION,
                moveAllowed: childNode.moveAllowed
            };
        } else {
            nodeToAdd = {
                id: `${parentNode.id}_${childNode.placeholdername}`,
                title: childNode.placeholderlabel || childNode.placeholdername,
                name: PropertyEditorWidgets.SECTION_COLUMN,
                expandable: false,
                children: [],
                addAllowed: childNode.parentComponent.addAllowed,
                editAllowed: childNode.parentComponent.editAllowed && childNode.parentComponent.name !== PropertyEditorWidgets.FORM_SECTION,
                moveAllowed: false
            };

            this.alwaysExpandedNodesIds[nodeToAdd.id] = true;
        }

        if (childNode.childContainers.length > 0) {
            if (childNode.childContainers.length === 1) {
                childNode.childContainers[0].children.forEach(x => this.buildNodesCollection(nodeToAdd, x));
            } else {
                childNode.childContainers.forEach(x => this.buildNodesCollection(nodeToAdd, x));
            }
        } else {
            childNode.children.forEach(x => this.buildNodesCollection(nodeToAdd, x));
        }

        if (!parentNode) {
            this.nodes.push(nodeToAdd);
            this.rootLevelDropAllowed = (childNode as ComponentModel).parentContainer?.addAllowed;
        } else {
            parentNode.children.push(nodeToAdd);
            parentNode.expandable = parentNode.name === PropertyEditorWidgets.SECTION || parentNode.name === PropertyEditorWidgets.FORM_SECTION;
        }
    }

    private handleExpandOnDragover(currentParent: TreeNode) {
        // clear timeout if parent is different
        if (this.dragTimeoutId && this.previousDropParent && this.previousDropParent !== currentParent) {
            clearTimeout(this.dragTimeoutId);
            this.dragTimeoutId = undefined;
            this.previousDropParent = undefined;
        }

        // set expand timeout if section is collapsed
        if (!currentParent.isExpanded && currentParent.data.expandable && !this.dragTimeoutId) {
            this.previousDropParent = currentParent;
            this.dragTimeoutId = setTimeout(() => {
                this.dragTimeoutId = undefined;
                this.previousDropParent = undefined;
                currentParent.expand();
            }, 1000);
        }
    }
}

interface SidebarTreeNodeModel {
    id: string,
    name: string,
    title: string,
    expandable: boolean,
    children: SidebarTreeNodeModel[],
    addAllowed: boolean,
    editAllowed: boolean,
    moveAllowed: boolean,
}
