import { Injectable } from "@angular/core";
import { MetadataHandler } from "../../services/metadata/metadata.handler";
import { Entity } from "../../services/metadata/meta-data.store";
import { FieldTypes } from "../../fields-builder/services/fields-registry";
import { CompositeFieldsProvider } from "../../fields-builder/providers/fields-provider";
import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { EVENT_PROPERTIES, CALENDAR_PROPERTIES, NON_DEFAULT_PROPERTY_MAPPINGS, FIELD_GROUPS } from "./events.constants";
import { FormData } from "../../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { CALENDAR_ITEM_FULL_NAME, EVENT_ITEM_FULL_NAME } from "../../services/metadata/meta-data-constants";
import { FieldModel } from "../../../../services/field.model";

@Injectable()
export class EventsMetadataHandler extends MetadataHandler {
    fieldGroups: any[] = FIELD_GROUPS;

    constructor(protected fieldsProvider: CompositeFieldsProvider) {
        super(fieldsProvider);
    }

    getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string {
        if (this.isCalendarDropdown(propertyName, metadata)) {
            return FieldTypes.parentDropdownSelector;
        }

        if (propertyName === EVENT_PROPERTIES.RECURRENCE_EXPRESSION) {
            return FieldTypes.recurringEvent;
        }

        if (propertyName === CALENDAR_PROPERTIES.COLOR) {
            return FieldTypes.color;
        }

        const nonDefaultPropertyType = NON_DEFAULT_PROPERTY_MAPPINGS[propertyName];
        if (nonDefaultPropertyType) {
            return nonDefaultPropertyType;
        }

        return null;
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === EVENT_ITEM_FULL_NAME || typeFullName === CALENDAR_ITEM_FULL_NAME;
    }

    updateInnerFieldsSettings(innerFields, tweaks: FormData[], readonly: boolean) {
        Object.keys(innerFields).forEach(prop => {
            const settings = innerFields[prop].settings as SettingsBase;

            if (prop === EVENT_PROPERTIES.ALL_DAY_EVENT) {
                settings.showTitle = false;
                settings.showForAllTranslationsLabel = false;
            } else {
                settings.showForAllTranslationsLabel = true;
            }

            const readonlyTweakVal = tweaks.find(x => x.name === prop).readonly;
            settings.readOnlyMode = readonly || readonlyTweakVal;
        });
    }

    updateAdditionalSettings(propertyName: string, tweaks: FormData[], compositeFieldModel: FieldModel) {
        // the composite field event-time.composite.component holds a specific logic for the EventStart
        // and EventEnd dates and how they are parsed. Setting the value of the composite field model in
        // the base MetadataHandler will interfere with this logic and this leads to bugs. Therefore, it
        // is set to null here
        if (propertyName === EVENT_PROPERTIES.EVENT_START) {
            compositeFieldModel.value = null;
        }
    }

    private isCalendarDropdown(propertyName: string, metadata: Entity): boolean {
        if (!this.hasIgnoreParentChildRelationship(metadata)) {
            return false;
        }

        if (propertyName !== EVENT_PROPERTIES.PARENT_ID) {
            return false;
        }

        return true;
    }

    private hasIgnoreParentChildRelationship(metadata: Entity) {
        return metadata.ignoreParentChildRelationship;
    }
}

export const EVENTS_METADATA_HANDLER = { provide: MetadataHandler, useClass: EventsMetadataHandler, multi: true };
