import { ColumnModel } from "../../../../shared/models/column-model";

import { Entity } from "../../../../shared/services/metadata/meta-data.store";

import { GridData } from "./backend-tweaks.store";

import { Properties } from "../../../../shared/fields.constants";

import { PAGES_ENTITY_SET_NAME } from "../../../../pages/services/page.resolver";

import { COLUMN_NAMES, RESERVED_COLUMN_NAMES } from "../../components/columns-provider";
import { SORT_ORDER } from "../../../constants";
import { ENTITY_SET, ALBUM_ITEM_FULL_NAME, PAGE_ITEM_FULL_NAME, PAGE_PRESET_ITEM_FULL_NAME } from "../../../../shared/services/metadata/meta-data-constants";
import { TAXONOMY_COLUMN_NAMES } from "../../../../taxonomy";
import { MainFieldComponent } from "../../components/grid-cells/main-field/main-field.component";
import { MediaHelpers } from "../../../../libraries/services/media.helpers";
import { SfRxBase, TextMatchType } from "@progress/sitefinity-component-framework";
import { ChildrenCountComponent } from "../../../../shared/components/fields/children-count-component";
import { stringConstants } from "../../../../../common-constants";
import { COLUMN_ACTIONS } from "../../../../../services/store/actions/actions.columns";
import { AppStore } from "../../../../../services/store/app-store";
import { TRANSLATIONS_COLUMN_BADGES_COUNT } from "../../components/grid-cells/list-languages.component";
import { CLICKABLE_ELEMENT_CSS_CLASS } from "../../../../shared/components/list/list.component";
import { COLUMN_SELECTORS } from "../../../../../services/store/selectors/selectors.columns";

export const STATUS_CSS_CLASS = "-status";
export const TOGGLE_CSS_CLASS = "-toggle";
export const THUMBNAIL_CSS_CLASS = "-thumbnail";
export const TITLE_CSS_CLASS = "-title -col-size-m";
const PLUS_ICON = "plus-square-o";
const MINUS_ICON = "minus-square-o"

export class ColInitializer extends SfRxBase {
    constructor(protected col: ColumnModel) {
        super();
     }

    init(entity: Entity, tweak: GridData) {
        this.col.title = tweak.title;
        this.col.tooltip = tweak.title;
        return this.col;
    }
}


export class TranslationsColumnInitializer extends ColInitializer {
    private entity: Entity;
    private expandedColumnsPerEntity: { [key: string]: string[] };

    constructor(protected col: ColumnModel, private appStore: AppStore) {
        super(col);

        this.registerSubscription(this.appStore.pipe(COLUMN_SELECTORS.expandedColumnsPerEntity).subscribe(data => {
            this.expandedColumnsPerEntity = data;
        }));
    }

    init(entity: Entity, tweak: GridData): ColumnModel {
        super.init(entity, tweak);
        this.entity = entity;

        this.col.onColumnHeaderClicked = this.onToggleExpandedOrCollapsed.bind(this);
        this.col.setCustomCss = this.setCustomCss.bind(this);
        return this.col;
    }

    private setCustomCss(data: any): any {
        if (data &&
            data.cellModel &&
            data.result &&
            !data.isVirtualized &&
            data.siteCultures.length > TRANSLATIONS_COLUMN_BADGES_COUNT) {

            const cellModel = data.cellModel;
            const result = data.result;
            result.push(CLICKABLE_ELEMENT_CSS_CLASS);

            if (this.expandedColumnsPerEntity &&
                this.expandedColumnsPerEntity[this.entity?.setName] &&
                this.expandedColumnsPerEntity[this.entity.setName].indexOf(COLUMN_NAMES.TRANSLATIONS) > -1) {

                this.col.tooltip = "Less translations";
                cellModel.fieldIcon = MINUS_ICON;
            } else {
                this.col.tooltip = "All translations";
                cellModel.fieldIcon = PLUS_ICON;
            }

            return { result, cellModel }
        }

        return null;
    }

    private onToggleExpandedOrCollapsed(data: any) {
        if (data?.siteCultures.length > TRANSLATIONS_COLUMN_BADGES_COUNT) {
            this.appStore.dispatch(COLUMN_ACTIONS.toggleExpandedPerEntity({ entitySet: data.entitySet, columnName: COLUMN_NAMES.TRANSLATIONS }));
        }
    }
}

export class GroupingColInitializer extends ColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);

        this.col.isGrouping = tweak.isGrouping;

        return this.col;
    }
}

export class ClickableColInitializer extends ColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);
        this.col.clickable = true;

        return this.col;
    }
}

export class MainColInitializer extends ClickableColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);
        const hasStatusIcon = (!entity.hasChildren && entity.hasLifecycle && entity.setName !== ENTITY_SET.CONTENT_ITEMS) || entity.isSelfReferencing;

        this.col.sortableFieldName = entity.isSortingAllowed(entity.defaultFieldName) ? entity.defaultFieldName : null;
        this.col.css = TITLE_CSS_CLASS;
        this.col.componentData.properties = { hasStatusIcon: hasStatusIcon };

        const initialValues = Array.isArray(this.col.dataFieldNames) ? this.col.dataFieldNames : [];

        this.col.dataFieldNames = [entity.defaultFieldName, ...initialValues];

        if (hasStatusIcon) {
            this.col.css += ` ${STATUS_CSS_CLASS}`;
        }

        if (entity.hasLifecycle) {
            this.col.dataFieldNames.push(Properties.DISPLAY_STATUS, Properties.LOCKED_STATUS);
        }

        if (entity.isSelfReferencing) {
            this.col.dataFieldNames.push(Properties.HAS_CHILDREN, Properties.BREADCRUMB);
            this.col.css += ` ${TOGGLE_CSS_CLASS}`;

            if (entity.setName === PAGES_ENTITY_SET_NAME) {
                this.col.title = RESERVED_COLUMN_NAMES.Page;
                this.col.dataFieldNames.push("IsHomePage");
                this.col.dataFieldNames.push("Renderer");

                this.col.componentData.afterComponentInit = (mainFieldComponent: MainFieldComponent) => {
                    if (mainFieldComponent.context.dataItem.data && mainFieldComponent.context.dataItem.data.IsHomePage) {
                        mainFieldComponent.iconProperties = {
                            name: "home",
                            look: "black sf-mr-4xs",
                            inner: true
                        };
                    }
                };
            }
        }

        return this.col;
    }
}

export class TemplatesMainInitializer extends MainColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);

        this.col.css += ` ${STATUS_CSS_CLASS} ${THUMBNAIL_CSS_CLASS}`;
        this.col.componentData.properties.hasStatusIcon = true;
        this.col.componentData.properties.thumbnailLabelProperty = "Framework";

        return this.col;
    }
}

export class TaxaMainInitializer extends MainColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);
        this.col.dataFieldNames.push(Properties.TAXA_URL);
        this.col.dataFieldNames.push(Properties.DISPLAY_STATUS);

        if (entity.setName === ENTITY_SET.CLASSIFICATIONS) {
            this.col.css += ` ${STATUS_CSS_CLASS}`;
            this.col.title = "CLASSIFICATION TYPE";
            this.col.dataFieldNames.push("Type");
            this.col.componentData.properties.hasStatusIcon = true;
        }

        if (entity.setName === ENTITY_SET.FLAT_TAXA || entity.setName === ENTITY_SET.HIERARCHY_TAXA) {
            this.col.title = TAXONOMY_COLUMN_NAMES.TAXA_TITLE;
            this.col.dataFieldNames.push("Synonyms");
            this.col.dataFieldNames.push("Breadcrumb");
        }

        if (entity.setName === ENTITY_SET.HIERARCHY_TAXA) {
            this.col.css += ` ${TOGGLE_CSS_CLASS}`;
        }

        return this.col;
    }
}

export class MediaMainInitializer extends MainColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);

        this.col.componentData.properties.textMatchType = TextMatchType.Contains;
        if (MediaHelpers.isLibrary(entity.setName)) {
            this.col.css += ` ${STATUS_CSS_CLASS}`;
            this.col.title = tweak.title;
            this.col.componentData.properties.hasStatusIcon = true;
        }

        if (entity.setName === ENTITY_SET.DOCUMENTS) {
            this.col.componentData.afterComponentInit = (mainFieldComponent: MainFieldComponent) => {
                if (mainFieldComponent.context.dataItem.data && mainFieldComponent.context.dataItem.metadata.setName === ENTITY_SET.DOCUMENTS) {
                    mainFieldComponent.iconProperties = {
                        name: MediaHelpers.getDocumentThumbnailIcon(mainFieldComponent.context.dataItem.data.Extension),
                        look: `size-3xl ${mainFieldComponent.context.dataItem.isTranslated === false ? "lighter" : "light"}`,
                        inner: false
                    };
                }
            };
        }

        return this.col;
    }
}

export class DateAndUserInitializer extends ColInitializer {
    init(entity: Entity, tweak: GridData) {
        super.init(entity, tweak);

        if (entity.typeFullName === ALBUM_ITEM_FULL_NAME) {
            this.col.css = "-col-size-l";
        } else if (entity.typeFullName === PAGE_ITEM_FULL_NAME) {
            this.col.css = "-col-size-m";
        } else if (entity.typeFullName === PAGE_PRESET_ITEM_FULL_NAME) {
            this.col.css = "-col-size-sm -top-align";
        } else {
            this.col.css = "-col-size-sm";
        }
        this.col.sortableFieldName = entity.isSortingAllowed(this.col.name) ? this.col.name : null;
        this.col.defaultSortOrder = SORT_ORDER.DESCENDING;

        return this.col;
    }
}

export class FormResponsesColInitializer extends ColInitializer {
    init(entity: Entity, tweak: GridData): ColumnModel {
        super.init(entity, tweak);

        this.col.componentData.afterComponentInit = (childrenCountComponent: ChildrenCountComponent) => {
            const dataItem = childrenCountComponent.context.dataItem;
            if (dataItem && dataItem.data) {
                const look = childrenCountComponent.look ? [childrenCountComponent.look] : [];
                if (dataItem.data[Properties.FORM_RESPONSES] > 0) {
                    look.push("positive");
                }

                if (dataItem.data[Properties.AvailableLanguages].indexOf(dataItem.culture) < 0 || dataItem.data[Properties.FORM_RESPONSES] < 0) {
                    look.push("sf-hidden");
                }

                childrenCountComponent.look = look.join(stringConstants.INTERVAL);
            }
        };

        return this.col;
    }
}
