import { AbstractControl, ValidatorFn } from "@angular/forms";
import { MAX_INTEGER } from "../../../src/app/common-constants";

export const SAFE_INTEGER_VALIDATOR_NAME = "safeInteger";

export class MaxInteger {
    static validate(): ValidatorFn {
        return (control: AbstractControl) => {
            if (!control.value) {
                return null;
            }

            const inputValueNumber = +control.value;
            if (inputValueNumber >= MAX_INTEGER) {
                const errorObj = {};
                errorObj[SAFE_INTEGER_VALIDATOR_NAME] = {
                    maxIntegerValue: MAX_INTEGER
                };

                return errorObj;
            }

            if (inputValueNumber <= -MAX_INTEGER) {
                const errorObj = {};
                errorObj[SAFE_INTEGER_VALIDATOR_NAME] = {
                    minIntegerValue: -MAX_INTEGER
                };

                return errorObj;
            }

            return null;
        };
    }
}
