import { of as observableOf,  Observable, BehaviorSubject } from "rxjs";

import { map } from "rxjs/operators";
import { Injectable, ClassProvider, Inject } from "@angular/core";
import { AuthProvider, AUTH_PROVDER_TOKEN, Token } from "../auth.provider";
import { LOCAL_STORAGE, StorageService } from "../../shared/services/storage.service";
import { TokenProvider } from "../token.provider";

export const TOKEN_KEY = "token";

@Injectable()
export class ExternalTokenProvider extends TokenProvider implements AuthProvider {
    constructor(@Inject(LOCAL_STORAGE) private storage: StorageService) {
        super();
    }

    init(): Observable<void> {
        return new BehaviorSubject<void>(null);
    }

    signIn(returnUrl: string): Observable<void> {
        return observableOf();
    }

    signOut(): Observable<void> {
        return observableOf();
    }

    isLoggedIn(): Observable<boolean> {
        return this.getToken().pipe(map(x => !!x));
    }

    getToken(): Observable<Token> {
        return observableOf<Token>(this.getTokenFromStorage(this.storage, TOKEN_KEY));
    }

    getName(): string {
        return "external";
    }

    isAvailable(): Observable<boolean> {
        return observableOf(!!this.getTokenFromStorage(this.storage, TOKEN_KEY));
    }

    getPriority(): number {
        return 1;
    }
}

export const EXTERNAL_PROVIDER: ClassProvider = {
    multi: true,
    provide: AUTH_PROVDER_TOKEN,
    useClass: ExternalTokenProvider
};
