import { Component, Input, OnInit } from "@angular/core";
import { DataContext, DataContextComponent } from "../../models/data-context-component";

@Component({
    selector: "sf-duration",
    templateUrl: "./duration.component.html"
})
export class DurationComponent implements OnInit, DataContextComponent {
    @Input() public context: DataContext;
    public duration: string;
    public durationTooltip: string;

    ngOnInit(): void {
        const dataItem = this.context.dataItem;
        const model = this.context.model;
        const durationInMilliseconds = dataItem.data[model.name];

        if (durationInMilliseconds != null && durationInMilliseconds > 0) {
            const date = new Date(durationInMilliseconds);
            const utcMinutes = date.getUTCMinutes();
            const utcSeconds = durationInMilliseconds < 1000 ? 1 : date.getUTCSeconds();
            const utcHours = date.getUTCHours();
            const initialDate = new Date(null);
            const days = date.getUTCDay() - initialDate.getUTCDay();

            // get last two symbols from formatted string
            const formattedMinutes = `0${utcMinutes}`.slice(-2);
            const formattedSeconds = `0${utcSeconds}`.slice(-2);

            if (utcHours > 0 || days > 0) {
                const hours = days > 0 ? days * 24 : utcHours;
                const hoursLabel = hours > 1 ? "hrs" : "hr";

                this.duration = `Over ${hours}h`;
                this.durationTooltip = `${days * 24 + utcHours} ${hoursLabel} ${formattedMinutes} min ${formattedSeconds} sec`;
            } else {
                this.duration = `${formattedMinutes}:${formattedSeconds}`;
                if (utcMinutes > 0) {
                    this.durationTooltip = `${formattedMinutes} min ${formattedSeconds} sec`;
                } else {
                    this.durationTooltip = `${utcSeconds < 10 ? utcSeconds : formattedSeconds} sec`;
                }
            }
        }
    }
}
