import { createSelector, select } from "@ngrx/store";
import { AppState } from "../store-schema";
import { pipe } from "rxjs";
import { map } from "rxjs/operators";
import { cloneObject } from "../../../utils";
import { SidebarConfig, SidebarData } from "../../../modules/shared/components/sidebar/sidebar.common";
import { StoredComponentsDataCache } from "../cache/dynamic-loader-components-cache";

/**
 * Observable OperatorFunction selectors for the sidebar feature
 * used in the manner:
 * this.store.pipe([selector]).subscribe(....)
 */
export const SIDEBAR_SELECTORS = {
    isOpen: select(createSelector((state: AppState) => state.sidebar, state => state.isOpen)),
    isLoading: select(createSelector((state: AppState) => state.sidebar, state => state.isLoading)),
    activeConfig: pipe(select(createSelector((state: AppState) => state.sidebar, state => state.activeConfig)),
        map(activeConfig => {
            let config: SidebarConfig = activeConfig;
            if (config) {
                config = cloneObject(activeConfig);
                if (config) {
                    config.data = StoredComponentsDataCache.get(activeConfig.name);
                }
            }

            return config;
        })),
    sidebarData: pipe(select(createSelector((state: AppState) => state.sidebar, state => state.sidebarData)),
        map(sidebarData => {
            const newData: SidebarData = cloneObject(sidebarData);
            newData.buttons.map(button => {
                button.data = StoredComponentsDataCache.get(button.name);
                return button;
            });

            return newData;
        })),
    shouldAnimate: pipe(select(createSelector((state: AppState) => state.sidebar, state => state.shouldAnimate)))
};
