import { Component, OnInit, QueryList, ViewChildren, AfterViewInit, Input } from "@angular/core";
import { CompositeFieldSettings } from "../../../services/composite-field.settings";
import { DateTimePickerComponent } from "../../../../../../../fields/date-time/date-time-picker.component";
import { FormGroup, FormControl } from "@angular/forms";
import { FormFieldWrapperComponent } from "../../../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { EVENT_PROPERTIES } from "../events.constants";
import { EventsDateTimeValidator } from "../validators/events-date-time.validator";
import { FieldValidation } from "../../../../../../../fields/field-validation";
import { FieldBase } from "../../../../../../../fields";
import { EventDatesService } from "../services/event-dates.service";
import { ChoiceYesNoComponent } from "../../../../../../../fields/choice/choice-yesno.component";
import { TimeZonesComponent } from "../timezones/timezones.component";
import { StatusType } from "../../../../../../../fields/field-status";
import { DateTimePickerSettings } from "../../../../../../../fields/date-time/date-time-settings";
import { RecurrentRule, RecurrenceFrequency } from "../recurring-event/recurrent-rule";
import { convertHourMinuteSecStringToSeconds, convertDateToIsoDateTime } from "../../../../../utils";
import { ActivatedRoute } from "@angular/router";
import { ROUTE_PARAMS, QUERY_PARAMS } from "../../../../content/constants";

@Component({
    selector: "sf-event-time-composite-field",
    templateUrl: "./event-time.composite.component.html"
})
export class EventTimeCompositeComponent extends FieldBase implements OnInit, AfterViewInit {
    @Input() get compositeFieldSettings() {
        return this.settings as CompositeFieldSettings;
    }
    @ViewChildren(FormFieldWrapperComponent) protected fields: QueryList<FormFieldWrapperComponent>;

    showEventEndField: boolean = true;
    isAllDayEvent: boolean = false;
    errorMessages: string[] = [];
    form: FormGroup = new FormGroup({});

    protected showTime: boolean = true;
    protected propertyFieldMap = new Map<string, FormFieldWrapperComponent>();

    private endDatePicker: DateTimePickerComponent;
    private recurrenceRule: RecurrentRule;
    private isInCopyMode: boolean = false;

    constructor(private eventsDateService: EventDatesService, private route: ActivatedRoute) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        this.initializeRecurrenceRule();
        this.initializeSettings();
        this.initializeForm();
        this.resolveCopyMode();
    }

    ngAfterViewInit() {
        this.initializePropertyFieldMap();
        const endDateWrapper = this.propertyFieldMap.get(EVENT_PROPERTIES.EVENT_END);
        if (endDateWrapper) {
            this.endDatePicker = endDateWrapper.currentInstance;
        }

        const allDayEventField = this.fields.find(x => x.fieldModel.key === EVENT_PROPERTIES.ALL_DAY_EVENT);
        if (allDayEventField) {
            this.onAllDayEventClick(allDayEventField.getValue());
        }

        if (this.compositeFieldSettings.dataItem && this.compositeFieldSettings.dataItem.data) {
            this.handleEndDateInitialVisibility();
        }

        const timeZoneControl = this.propertyFieldMap.get(EVENT_PROPERTIES.TIME_ZONE_ID);
        if (timeZoneControl) {
            this.compositeFieldSettings.defaultValue = this.compositeFieldSettings.defaultValue || {};
            this.compositeFieldSettings.defaultValue[EVENT_PROPERTIES.TIME_ZONE_ID] = timeZoneControl.fieldModel.settings.defaultValue;
        }
    }

    getValue(allValues: boolean = false): EventData {
        if (!this.fields) {
            return null;
        }

        let fields;

        if (!allValues && !this.isInCopyMode) {
            fields = this.fields.filter(f => f.formControl && f.formControl.dirty);
        } else {
            fields = this.fields;
        }

        const result = {};
        fields.forEach(f => result[f.fieldModel.key] = f.getValue());

        return result;
    }

    writeValue(updatedValues: EventData) {
        if (!updatedValues) {
            return;
        }

        const result = Object.assign({}, updatedValues);

        if (result.AllDayEvent !== undefined) {
            if (updatedValues !== this.compositeFieldSettings.defaultValue) {
                this.onAllDayEventClick(result.AllDayEvent);
            }
        }

        // handle event start change
        if (result.EventStart) {
            const settings = <DateTimePickerSettings>this.endDatePicker.settings;
            settings.minValue = new Date(result.EventStart);
        }

        if ((result.EventStart || result.EventEnd) && (this.endDatePicker && !this.endDatePicker.showDate)) {
            // user cannot choose end date, only time
            const startDate = this.propertyFieldMap.get(EVENT_PROPERTIES.EVENT_START).getValue();
            const currentEndDate = this.endDatePicker.getValue();
            const newEndDate = new Date(startDate);
            if (currentEndDate) {

                // keep the time, use the start date year, month, day
                newEndDate.setHours(currentEndDate.getHours());
                newEndDate.setMinutes(currentEndDate.getMinutes());
                newEndDate.setSeconds(currentEndDate.getSeconds());

                if (newEndDate.toUTCString() !== currentEndDate.toUTCString()) {
                    result.EventEnd = newEndDate;
                }
            }
        }

        Object.keys(result).forEach(key => {
            const value = result[key];
            const fieldWrapper = this.propertyFieldMap.get(key);
            if (fieldWrapper) {
                const currentValue = fieldWrapper.getValue();
                const isCurrentValueDefined = currentValue !== undefined && currentValue !== null;
                if (!isCurrentValueDefined || (currentValue !== value && updatedValues !== this.compositeFieldSettings.defaultValue)) {
                    fieldWrapper.writeValue(value);
                }

                // if (isCurrentValueDefined) {
                //     if (key === EVENT_PROPERTIES.EVENT_START || key === EVENT_PROPERTIES.EVENT_END) {
                //         value = new Date(convertDateToIsoDateTime(value));
                //     }
                // }
            }
        });

        if (result.EventStart || result.EventEnd) {
            this.validate();
        }

        const dirtyValue = this.getValue();
        if (dirtyValue !== null && Object.keys(dirtyValue).length) {
            // trigger value changed handlers
            super.writeValue(dirtyValue);
        }
    }

    resetEndDate() {
        const startDate = new Date(this.propertyFieldMap.get(EVENT_PROPERTIES.EVENT_START).getValue());
        const endDate = new Date(this.endDatePicker.getValue());

        endDate.setDate(startDate.getDate());
        endDate.setMonth(startDate.getMonth());
        endDate.setFullYear(startDate.getFullYear());

        this.endDatePicker.writeValue(endDate);
    }

    validate() {
        this.fields.forEach(f => f.hasErrors());
        this.form.updateValueAndValidity();

        if (this.form.errors) {
            const newErrors = new FieldValidation(this).getErrorMessage(this.form.errors);
            if (newErrors.length) {
                this.addErrorMessages(newErrors);
                if (this.status$.value.type !== StatusType.Error) {
                    this.emitStatus({ type: StatusType.Error });
                    return false;
                }
            }
        } else if (!this.form.valid) {
            if (this.status$.value.type !== StatusType.Error) {
                this.emitStatus({ type: StatusType.Error });
                return false;
            }
        } else {
            this.clearErrorMessages();
            this.emitStatus({ type: StatusType.ErrorCleared });
            return true;
        }
    }

    postProcessValue(value: EventData) {
        if (this.isAllDayEvent) {
            if (value[EVENT_PROPERTIES.EVENT_START]) {
                value[EVENT_PROPERTIES.EVENT_START] = this.eventsDateService.resetTime(new Date(value[EVENT_PROPERTIES.EVENT_START]));
            }

            if (value[EVENT_PROPERTIES.EVENT_END]) {
                const endDate = this.eventsDateService.resetTime(new Date(value[EVENT_PROPERTIES.EVENT_END]));
                value[EVENT_PROPERTIES.EVENT_END] = endDate;
            }
        }

        if (value[EVENT_PROPERTIES.EVENT_END] && this.recurrenceRule) {
            // Sitefinity does not use or send event end date when creating recurrences
            // but the field value is marked as dirty and pollutes objects sent to SF
            delete value[EVENT_PROPERTIES.EVENT_END];
        }

        const isoDate = this.convertObjToIsoDateTime(value);
        return isoDate;
    }

    hasEmptyValue() {
        return this.fields.toArray().every(x => !x.getValue());
    }

    handleRecurrenceChange(hasRecurrence: boolean) {
        this.handleEndDateVisibility(!hasRecurrence);

        if (!hasRecurrence) {
            // recurrenceRule should be cleared when the dropdown is set to none
            this.recurrenceRule = null;
        }

        // trigger value change to update the current event dates
        // in case end date is different than start date (should keep only hours)
        this.writeValue({
            [EVENT_PROPERTIES.EVENT_END]: this.endDatePicker.getValue()
        });
    }

    handleEndDateVisibility(show: boolean): void {
        const wrapper = this.fields.filter(x => x.currentInstance instanceof DateTimePickerComponent)[1];
        const picker = wrapper.currentInstance as DateTimePickerComponent;

        // Show the label when already both time and date are hidden because of selected all day event and recurring value
        const shouldShowEndField = show && !picker.showDate && !picker.showTime;

        if (shouldShowEndField) {
            this.toggleLabelVisibility(wrapper, true);
            this.showEventEndField = true;
        }

        // Hide the label when the time is already hidden because of AllDayEvent and date will be hidden because recurring value is selected
        const shouldHideEndField = !show && !picker.showTime;

        if (shouldHideEndField) {
            this.toggleLabelVisibility(wrapper, false);
            this.showEventEndField = false;
        }

        picker.showDate = show;
    }

    protected getDatePickers(): DateTimePickerComponent[] {
        return Array.from(this.propertyFieldMap.values())
            .filter(x => !!x)
            .map(x => x.currentInstance)
            .filter(x => x instanceof DateTimePickerComponent);
    }

    protected toggleLabelVisibility(wrapper: FormFieldWrapperComponent, show: boolean) {
        wrapper.fieldModel.settings.showTitle = show;
        wrapper.fieldModel.settings.showForAllTranslationsLabel = show;
    }

    protected initializePropertyFieldMap() {
        const dateTimePickers = this.fields.filter(x => x.currentInstance instanceof DateTimePickerComponent);
        const startDatePicker = dateTimePickers[0];
        const endDatePicker = dateTimePickers[1];
        const allDayEvent = this.fields.find(x => x.currentInstance instanceof ChoiceYesNoComponent);
        const timezoneId = this.fields.find(x => x.currentInstance instanceof TimeZonesComponent);

        this.propertyFieldMap.set(EVENT_PROPERTIES.EVENT_START, startDatePicker);
        this.propertyFieldMap.set(EVENT_PROPERTIES.EVENT_END, endDatePicker);
        this.propertyFieldMap.set(EVENT_PROPERTIES.ALL_DAY_EVENT, allDayEvent);
        this.propertyFieldMap.set(EVENT_PROPERTIES.TIME_ZONE_ID, timezoneId);
    }

    private initializeSettings() {
        this.isAllDayEvent = this.compositeFieldSettings.innerFields[EVENT_PROPERTIES.ALL_DAY_EVENT].value;

        const eventStartField = this.compositeFieldSettings.innerFields[EVENT_PROPERTIES.EVENT_START];
        const eventEndField = this.compositeFieldSettings.innerFields[EVENT_PROPERTIES.EVENT_END];

        if (this.compositeFieldSettings.dataItem && this.compositeFieldSettings.dataItem.data) {
            const eventStartWithServerOffset = this.compositeFieldSettings.dataItem.data[EVENT_PROPERTIES.EVENT_START_WITH_OFFSET];
            let eventEndWithServerOffset = this.compositeFieldSettings.dataItem.data[EVENT_PROPERTIES.EVENT_END_WITH_OFFSET];

            if (this.isAllDayEvent) {
                eventEndWithServerOffset = this.eventsDateService.getEventEndForAllDayEvent(eventStartWithServerOffset, eventEndWithServerOffset);
            }

            // The server returns the start/end dates with the server offset included so there is no need to pass it
            eventStartField.value = this.eventsDateService.getDateWithoutBrowserOffset(eventStartWithServerOffset);
            eventEndField.value = this.eventsDateService.getDateWithoutBrowserOffset(eventEndWithServerOffset);
        }

        // use the default values to mark the field dirty
        this.compositeFieldSettings.markAsDirty = true;
        this.compositeFieldSettings.useDefaultValue = true;

        // if start date is defined but no end date
        // this means the default values should NOT
        // be considered dirty
        if (eventStartField.value && !eventEndField.value) {
            this.compositeFieldSettings.markAsDirty = false;
        }

        // initialize default values
        // if start date is defined, use it
        const now = Date.now();
        let startDate = eventStartField.value;
        if (!startDate) {
            startDate = this.roundHour(new Date(now));
        }

        // if end date is defined, use it
        let endDate = eventEndField.value;
        if (!endDate) {
            endDate = this.populateDefaultEndTime(endDate, startDate, eventStartField.value);

            if (this.compositeFieldSettings.readOnlyMode) {
                this.compositeFieldSettings.innerFields[EVENT_PROPERTIES.EVENT_END].value = endDate;
            }
        }

        this.compositeFieldSettings.defaultValue = {
            [EVENT_PROPERTIES.EVENT_START]: startDate,
            [EVENT_PROPERTIES.EVENT_END]: endDate,
            [EVENT_PROPERTIES.ALL_DAY_EVENT]: false,
            [EVENT_PROPERTIES.TIME_ZONE_ID]: null
        };
    }

    private initializeForm() {
        Object.keys(this.compositeFieldSettings.innerFields).forEach((fieldName) => {
            const fieldData = this.compositeFieldSettings.innerFields[fieldName];
            const formControl = new FormControl(fieldData.value);

            formControl.setValidators(fieldData.settings.validators);
            this.form.setControl(fieldData.key, formControl);
        });

        this.form.setValidators(EventsDateTimeValidator.validate);
    }

    private initializeRecurrenceRule() {
        if (!this.compositeFieldSettings.dataItem || !this.compositeFieldSettings.dataItem.data) {
            return;
        }

        const data = this.compositeFieldSettings.dataItem.data;
        if (!data) {
            this.recurrenceRule = null;
            return;
        }

        const expression = data[EVENT_PROPERTIES.RECURRENCE_EXPRESSION] || null;
        this.recurrenceRule = JSON.parse(expression);
    }

    private resolveCopyMode() {
        const snapshot = this.route.snapshot;
        const queryParams = snapshot.queryParamMap;
        const action = snapshot.url[1];

        this.isInCopyMode = (action && action.path === ROUTE_PARAMS.DUPLICATE_SEGMENT) || queryParams.keys.indexOf(QUERY_PARAMS.VERSION) > -1;
    }

    private populateDefaultEndTime(endDate, startDate, isSetExplicitly) {
        if (this.recurrenceRule && this.recurrenceRule.duration) {
            // if the recurrence has duration, use it
            const duration = convertHourMinuteSecStringToSeconds(this.recurrenceRule.duration);
            endDate = new Date(startDate);
            endDate.setSeconds(endDate.getSeconds() + duration);
        } else if (!isSetExplicitly) {
            endDate = this.roundHour(new Date(startDate));
            endDate.setHours(endDate.getHours() + 1);
        }

        return endDate;
    }

    private handleEndDateInitialVisibility() {
        if (!this.endDatePicker) {
            return;
        }

        const recurrentRule: RecurrentRule = JSON.parse(this.compositeFieldSettings.dataItem.data[EVENT_PROPERTIES.RECURRENCE_EXPRESSION]);
        if (!recurrentRule) {
            this.endDatePicker.showDate = true;
            return;
        }

        if (recurrentRule.frequency === RecurrenceFrequency.None) {
            this.endDatePicker.showDate = true;
            return;
        }

        this.endDatePicker.showDate = false;

        if (!this.endDatePicker.showDate && !this.endDatePicker.showTime) {
            this.showEventEndField = false;
            this.toggleLabelVisibility(this.propertyFieldMap.get(EVENT_PROPERTIES.EVENT_END), false);
        }
    }

    private addErrorMessages(newErrors: string[]) {
        newErrors.forEach(m => this.errorMessages.push(m));
    }

    private clearErrorMessages() {
        this.errorMessages.length = 0;
    }

    private onAllDayEventClick(checked: boolean) {
        const pickers = this.getDatePickers();

        pickers.forEach((x: DateTimePickerComponent) => x.showTime = !checked);

        const startDatePicker = pickers[0];
        const endDatePicker = pickers[1];
        const willrestoreTime = this.isAllDayEvent && !checked;

        this.isAllDayEvent = checked;

        const initialStartDate = pickers[0].getValue();
        const initialEndDate = pickers[1].getValue();

        const startDate = new Date(initialStartDate);
        const endDate = new Date(initialEndDate);

        if (this.isAllDayEvent) {
            // Change dates only if there are differences in values
            if (startDate.getUTCMinutes() !== 0 || endDate.getUTCMinutes() !== 0) {
                startDatePicker.writeValue(startDate);
                endDatePicker.writeValue(endDate);
            }

            const startDateObj = this.eventsDateService.resetTime(new Date(startDate));
            const endDateObj = this.eventsDateService.resetTime(new Date(endDate));

            // Hide error message when all day is clicked and end date becomes after start date
            if (startDateObj.getTime() <= endDateObj.getTime()) {
                this.clearErrorMessages();
            }
        } else if (willrestoreTime) {
            const currentHourRounded = this.roundHour(new Date(Date.now())).getHours();
            startDate.setHours(currentHourRounded);
            const endDateHourRounded = this.populateDefaultEndTime(endDate, startDate, false).getHours();
            endDate.setHours(endDateHourRounded);
            startDatePicker.writeValue(startDate);
            endDatePicker.writeValue(endDate);
        }

        const endDateWrapper = this.propertyFieldMap.get(EVENT_PROPERTIES.EVENT_END);
        if (this.isAllDayEvent && !this.endDatePicker.showDate) {
            this.showEventEndField = false;
            this.toggleLabelVisibility(endDateWrapper, false);
        }

        if (!this.isAllDayEvent && !this.endDatePicker.showDate) {
            this.showEventEndField = true;
            this.toggleLabelVisibility(endDateWrapper, true);
        }

        // validate the dates, because all day event compares only the date objects and not the hours
        this.validate();
    }

    private roundHour(date: Date): Date {
        if (date.getMinutes() > 0 || date.getSeconds() > 0) {
            date.setHours(date.getHours() + 1);
            date.setMinutes(0);
            date.setSeconds(0);
        }

        return date;
    }

    private convertObjToIsoDateTime(value: any) {
        if (value instanceof Date) {
            return convertDateToIsoDateTime(value);
        } else if (value instanceof Object) {
            const ret = {};
            for (const key in value) {
                if (value.hasOwnProperty(key)) {
                    ret[key] = this.convertObjToIsoDateTime(value[key]);
                }
            }

            return ret;
        }

        return value;
    }
}

export interface EventData {
    EventStart?: Date;
    EventEnd?: Date;
    AllDayEvent?: boolean;
    TimeZoneId?: string;
}
