import { Component, OnInit } from "@angular/core";
import { DEFAULT_SHORTCUTS, KeyboardShortcut, KeyboardActionShortcut, KeyboardActionType, MAC_OS_NAME, KEYBOARD_KEY_CODES } from "../../../services/keyboard-shortcuts.constants";

@Component({
    selector: "sf-keyboard-shortcuts",
    templateUrl: "./keyboard-shortcuts.component.html"
})
export class KeyboardShortcutsComponent implements OnInit {
    title: string = "Keyboard shortcuts";
    mappedShortcuts: Map<string, string> = new Map<string, string>();
    listItemsShortcuts: Array<KeyboardShortcut>;
    editContentShortcuts: Array<KeyboardShortcut>;
    keyboardShortcutsType: typeof KeyboardActionType = KeyboardActionType;
    kendoKeyboardShortcuts: Array<KeyboardShortcut> = [
        { keyCombination: `${this.ctrlKey}+Z`, description: "Undo" },
        { keyCombination: `${this.ctrlKey}+Y`, description: "Redo" },
        { keyCombination: `${this.ctrlKey}+C`, description: "Copy" },
        { keyCombination: `${this.ctrlKey}+X`, description: "Cut" },
        { keyCombination: `${this.ctrlKey}+V`, description: "Paste" },
        { keyCombination: `${this.ctrlKey}+K`, description: "Insert link" },
        { keyCombination: `${this.ctrlKey}+J`, description: "Insert image" },
        { keyCombination: `${this.ctrlKey}+L`, description: "Insert document" },
        { keyCombination: `${this.ctrlKey}+B`, description: "Apply bold formatting" },
        { keyCombination: `${this.ctrlKey}+I`, description: "Apply italic formatting" },
        { keyCombination: `${this.ctrlKey}+U`, description: "Apply underline formatting" }
    ];
    private defaultShortcuts: Array<KeyboardActionShortcut> = DEFAULT_SHORTCUTS;
    private get ctrlKey(): string {
        return navigator.appVersion.indexOf(MAC_OS_NAME) !== -1 ? "CMD" : "CTRL";
    }

    ngOnInit() {
        this.defaultShortcuts.forEach((keyboardAction) => {
            let keyCombination = "";
            const keyString = "Key";

            if (keyboardAction.ShortcutSettings.ctrlKey) {
                keyCombination += `${this.ctrlKey}+`;
            }

            if (keyboardAction.ShortcutSettings.shiftKey) {
                keyCombination += "SHIFT+";
            }

            if (keyboardAction.ShortcutSettings.altKey) {
                keyCombination += "ALT+";
            }

            let keyCode = keyboardAction.ShortcutSettings.code;

            const keyCodeFriendlyNames = new Map<string, string>([
                [KEYBOARD_KEY_CODES.DELETE, "DEL"],
                [KEYBOARD_KEY_CODES.ESCAPE, "ESC"],
                [KEYBOARD_KEY_CODES.ENTER, "ENTER"]
            ]);

            const friendlyName = keyCodeFriendlyNames.get(keyCode);

            if (friendlyName) {
                keyCode = friendlyName;
            }

            if (keyCode.substring(0, keyString.length) === keyString) {
                keyCombination += keyCode.substring(keyString.length, keyCode.length);
            } else {
                keyCombination += keyCode;
            }

            const keyboardActionType = this.keyboardShortcutsType[keyboardAction.ActionType].toString();
            if (this.mappedShortcuts.get(keyboardActionType)) {
                this.mappedShortcuts.set(`${keyboardActionType}Alias`, keyCombination);
            } else {
                this.mappedShortcuts.set(keyboardActionType, keyCombination);
            }
        });
        this.listItemsShortcuts = [
            { description: "Create new item", keyCombination: this.mappedShortcuts.get("Create")},
            { description: "Close dialog", keyCombination: this.mappedShortcuts.get("Escape")} ,
            { description: "Confirm action in dialog", keyCombination: this.mappedShortcuts.get("CommonConfirm")},
            { description: "Select all items on current page", keyCombination: this.mappedShortcuts.get("SelectAll")},
            { description: "Clear selection", keyCombination: this.mappedShortcuts.get("Escape")},
            { description: "Publish selected items", keyCombination: this.mappedShortcuts.get("Publish")},
            { description: "Unpublish selected items", keyCombination: this.mappedShortcuts.get("Unpublish")},
            { description: "Schedule selected items", keyCombination: this.mappedShortcuts.get("Schedule")},
            { description: "Delete selected items", keyCombination: this.mappedShortcuts.get("Delete")}
        ];
        this.editContentShortcuts = [
            { description: "Preview", keyCombination: this.mappedShortcuts.get("Preview")},
            { description: "Close dialog", keyCombination: this.mappedShortcuts.get("Escape")},
            { description: "Confirm action in dialog", keyCombination: this.mappedShortcuts.get("CommonConfirm")},
            { description: "Publish", keyCombination: this.mappedShortcuts.get("Publish")},
            { description: "Save as draft", keyCombination: `${this.mappedShortcuts.get("SaveAlias")} or ${this.mappedShortcuts.get("Save")}`},
            { description: "Unpublish", keyCombination: this.mappedShortcuts.get("Unpublish")},
            { description: "Schedule", keyCombination: this.mappedShortcuts.get("Schedule")},
            { description: "Delete", keyCombination: this.mappedShortcuts.get("Delete")},
            { description: "Create new item", keyCombination: this.mappedShortcuts.get("Create")}
        ];
    }
}
