import { Component, OnInit } from "@angular/core";
import { FieldRegistration } from "../../fields-builder/services/fields-registry";
import { ModalListComponent } from "../modal-list/modal-list.component";
import { ModalWindowService, DialogData, Button, ConfirmButton, CancelButton, ClosingContext } from "../../services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { BehaviorSubject, Observable, of } from "rxjs";
import { SelectorConstants } from "../../../html/selector-constants";
import { ChoiceItem, ComponentData } from "@progress/sitefinity-component-framework";
import { ChoiceComponent } from "../../../../../../fields/choice/choice.component";
import { HttpODataRequestWrapper } from "../../services/http-odata-request.wrapper";
import { Logger } from "../../services/logger-source/logger";
import { tap } from "rxjs/operators";
import { MultipleChoiceChipSettings } from "./multiple-choice-chip.settings";
import { SelectorComponent, ServiceContract, ServiceInfo } from "../../../../../../fields/selector/selector.component";
import { ChipsConfig } from "../../../../../../fields/common/chips/chips.component";
import { pluralize } from "../../../../utils";

@Component({
    selector: "sf-multiple-choice-chip",
    templateUrl: "./multiple-choice-chip.component.html"
})
export class MultipleChoiceChipComponent extends ChoiceComponent implements OnInit {
    selectedChips: Chip[] = [];
    actionTitle: string;
    buttonTitle: string;
    recentChoices: any[] = [];
    choiceChipsConfig: ChipsConfig = {};
    private showSelectedTab: boolean;
    private showRecentItems: boolean;
    private serviceAware: ServiceContract;
    private itemTypeName: string;
    private displayFieldName: string = "Value";
    private idFieldName: string = "Name";

    constructor(
        private route: ActivatedRoute,
        private modalService: ModalWindowService,
        httpRequestWrapper: HttpODataRequestWrapper,
        logger: Logger) {
        super(httpRequestWrapper, logger);
    }

    ngOnInit() {
        super.ngOnInit();
        this.actionTitle = (this.settings as MultipleChoiceChipSettings).choiceActionTitle;
        this.buttonTitle = (this.settings as MultipleChoiceChipSettings).choiceButtonTitle;
        this.showSelectedTab = (this.settings as MultipleChoiceChipSettings).choiceShowSelectedTab;
        this.showRecentItems = (this.settings as MultipleChoiceChipSettings).choiceShowRecentItems;
        this.itemTypeName = (this.settings as MultipleChoiceChipSettings).choiceItemTypeName ?? this.settings.title;

        if (this.showSelectedTab) {
            this.serviceAware = new ServiceContract(
                (info: ServiceInfo) => {
                    let result = this.settings.choices;
                    if (info.searchText) {
                        result = result.filter(choice => choice.Value.toLowerCase().startsWith(info.searchText.toLowerCase()));
                    }

                    return of(result);
                }
            );
        }

        if (this.showRecentItems) {
            this.choiceChipsConfig = {
                showSelectedItemAsActive: true,
                showRecentLabel: true,
                actions: [{
                    action: this.openDialog.bind(this),
                    label: `Show all ${pluralize(this.itemTypeName ?? this.settings.title)}`
                }]
            };
        }
    }

    protected loadChoices(): Observable<void> {
        return super.loadChoices().pipe(tap(() => {
            const fieldVal = this.getValue();
            if (fieldVal) {
                this.selectedChips = this.settings.choices
                    .filter(x => fieldVal.indexOf(x.Name) > -1)
                    .map(x => { return { Title: x.Value }; });
            }
        }));
    }

    openDialog() {
        let componentData: ComponentData;
        if (!this.showSelectedTab) {
            const items = this.settings.choices.slice().map(x => {
                (<any>x).isSelected = this.isChoiceSelected(x);
                return x;
            });

            componentData = {
                type: ModalListComponent,
                properties: {
                    actionTitle: this.actionTitle ?? this.settings.title,
                    treeConfig: {
                        multiSelection: true,
                        treeProperties: {
                            displayField: this.displayFieldName,
                            idField: this.idFieldName
                        }
                    },
                    count: new BehaviorSubject<number>(this.settings.choices.length),
                    template: null,
                    openItemEdit: false,
                    isLoading: false,
                    ignoreDelay: true,
                    showCounter: false,
                    dataItem: this.settings.dataItem,
                    isSearchVisible: items.length > 20,
                    items: items
                }
            };
        } else {
            const items = this.settings.choices.slice();
            componentData = {
                type: SelectorComponent,
                properties: {
                    value: items,
                    value$: of(items),
                    totalItemsCount: this.settings.choices.length,
                    selected: items.filter(x => this.isChoiceSelected(x)),
                    treeConfig: {
                        multiSelection: true,
                        isHierarchical: false,
                        treeProperties: {
                            displayField: this.displayFieldName,
                            idField: this.idFieldName
                        }
                    },
                    serviceAware: this.serviceAware,
                    typeNames: {
                        singular: this.itemTypeName ?? this.settings.title,
                        plural: pluralize(this.itemTypeName ?? this.settings.title)
                    },
                    defaultField: this.displayFieldName,
                    keyField: this.idFieldName,
                    isParentSelection: false,
                    loading: false,
                }
            };
        }

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton(SelectorConstants.CANCEL)
        ];
        const dialogData = new DialogData(componentData, (context) => this.onDone(context), buttons, null, "-bottom");

        this.modalService.setMapping(dialogData, "multiple-choice-chip");
        this.modalService.open(this.route, "multiple-choice-chip");
    }

    onDone(context: ClosingContext) {
        if (!context.data || !context.data.data) {
            return;
        }

        if (context.component.selected) {
            const selectedValues = context.component.selected.map(i => i[this.idFieldName]);
            this.writeValue(selectedValues);
        } else if (context.component.tree){
            let selectedValues = Object.keys(context.component.tree.getActiveNodeIds());
            selectedValues = selectedValues.filter(x => context.component.tree.getIsNodeActiveById(x));
            this.writeValue(selectedValues);
        } 
    }

    writeValue(value) {
        super.writeValue(value);
        if (value && this.settings) {
            this.selectedChips = this.settings.choices.filter(x => this.isChoiceSelected(x)).map(x => { return { Title: x.Value }; });
            this.setRecentChoices();
        }
    }

    onRemove(removedChip: Chip) {
        const currentValue = this.getValue();
        const removedChipValue = this.settings.choices.find(x => x.Value === removedChip.Title);
        this.writeValue(currentValue.filter(x => x !== removedChipValue.Name));
    }

    onSelectChip(selectedChip: Chip) {
        if (selectedChip.action && typeof selectedChip.action === "function") {
            selectedChip.action();
        } else if (selectedChip.Title) {
            const currentValue = this.getValue();
            const addedChipValue = this.settings.choices.find(x => x.Value === selectedChip.Title);
            this.writeValue([addedChipValue.Name, ...currentValue]);
        }
    }

    onChipsFocus(shouldOpen: boolean) {
        if (shouldOpen && (!this.recentChoices || this.recentChoices.length === 0)) {
            this.openDialog();
        }
    }

    private setRecentChoices() {
        if (this.showRecentItems) {
            this.recentChoices = this.settings.choices
                .filter(x => !this.isChoiceSelected(x))
                .map(x => { return { Title: x.Value }; })
                .slice(0, 5);
        }
    }

    private isChoiceSelected(choice: ChoiceItem): boolean {
        const currentValue = this.getValue();
        return currentValue && currentValue.indexOf(choice.Name) > -1
    }
}

interface Chip {
    Title: string;
    action?: Function;
}

export const MULTIPLE_CHOICE_CHIP_REGISTRY: FieldRegistration = {
    writeComponent: MultipleChoiceChipComponent,
    readComponent: MultipleChoiceChipComponent,
    settingsType: MultipleChoiceChipSettings
};
