import { NgModule } from "@angular/core";
import { RouterModule, Routes } from "@angular/router";
import { stringConstants } from "../../common-constants";
import { RESOLVE_NAMES, ROUTE_PARAMS } from "../content/constants";
import { ContentTypeGuard } from "../content/content-type.guard";
import { SEARCH_NOTIFICATION_BUILDER } from "../content/dynamic-modules/components/long-running-services/search-background-task-notification-builder";
import { DynamicItemRouterComponent } from "../content/dynamic-modules/components/router/dynamic-item-router.component";
import { ListIndexComponent } from "../shared/components/list/list-index.component";
import { ModalWindowComponent } from "../shared/components/modal-window/modal-window.component";
import { NotFoundComponent } from "../shared/components/not-found/not-found.component";
import { ListIndexContractProvider } from "../shared/services/list/list-index-contract.provider";
import { MetadataStoreResolver } from "../shared/services/metadata/meta-data-store.resolver";
import { SiteDataStoreResolver } from "../shared/services/metadata/site-data-store.resolver";
import { SearchServiceResolver } from "../shared/services/search-service.resolver";
import { SiteTitleDynamicResolver } from "../shared/services/site-title.dynamic.resolver";
import { SitesResolver } from "../shared/services/sites-resolver";
import { SharedModule } from "../shared/shared.module";
import { IntegrationsResolver } from "./integrations.entity-data.resolver";

const INTEGRATIONS_ROUTES: Routes = [{
    path: stringConstants.EMPTY_STRING,
    component: NotFoundComponent
}, {
    path: `:${ROUTE_PARAMS.TYPE_NAME_SEGMENT}`,
    component: DynamicItemRouterComponent,
    resolve: {
        [`${RESOLVE_NAMES.entityData}`]: IntegrationsResolver,
        metaStore: MetadataStoreResolver,
        siteDataStore: SiteDataStoreResolver,
        sites: SitesResolver,
        searchService: SearchServiceResolver
    },
    canActivate: [ContentTypeGuard],
    children: [{
        path: stringConstants.EMPTY_STRING,
        component: ListIndexComponent,
        resolve: {
            siteTitle: SiteTitleDynamicResolver
        }
    }, {
        path: "confirm/:name",
        component: ModalWindowComponent,
        outlet: "dialog"
    }]
}, {
    path: `:${ROUTE_PARAMS.TYPE_NAME_SEGMENT}/:${ROUTE_PARAMS.ITEM_ID}/:${ROUTE_PARAMS.OPERATION_NAME_SEGMENT}`,
    component: DynamicItemRouterComponent,
    resolve: {
        [`${RESOLVE_NAMES.entityData}`]: IntegrationsResolver
    },
    canActivate: [ContentTypeGuard],
    children: [{
        path: stringConstants.EMPTY_STRING,
        component: ListIndexComponent,
        resolve: {
            siteTitle: SiteTitleDynamicResolver
        }
    }, {
        path: "confirm/:name",
        component: ModalWindowComponent,
        outlet: "dialog"
    }]
}];

@NgModule({
    declarations: [],
    imports: [
        RouterModule.forChild(INTEGRATIONS_ROUTES),
        SharedModule
    ],
    providers: [
        IntegrationsResolver,
        ListIndexContractProvider,
        SEARCH_NOTIFICATION_BUILDER,
        SitesResolver,
        SearchServiceResolver
    ],
    exports: [RouterModule]
})
export class IntegrationsModule {
}
