import { Injectable } from "@angular/core";
import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ModalWindowService, Button, ConfirmButton, CancelButton, ModalComponentSettings, ClickResult } from "../../../../../shared/services/modal-window.service";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, Subject, ReplaySubject } from "rxjs";
import { OPERATION_NAMES, CONTEXT_PARAMETERS, OPERATION_CATEGORIES } from "../../../../../shared/components/action-menu/operation.model";
import { ActionButton } from "../../../../../shared/components/action-menu/action-menu-model";
import { ActionIcon } from "../../entity/action-buttons";
import { OPERATION_VALIDATOR_MAP } from "../../../components/dynamic-item.base";
import { DynamicItemStore } from "../../dynamic-item.store";
import { Action } from "../../entity/action";
import { ActivatedRoute } from "@angular/router";
import { switchMap } from "rxjs/operators";
import { ItemPosition, ItemWithOperationResult } from "../../dynamic-item.service";
import { DataItem } from "../../../interfaces";
import { NOTIFICATION_LOOKS, NotificationData } from "../../../../../shared/services/notification/notification-data";
import { SiteSyncItemInfoComponent } from "../../../../../shared/components/site-sync/site-sync-item-info.component";
import { stringConstants } from "../../../../../../common-constants";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { BasicNotificationComponent } from "../../../../../shared/components/notifications/basic-notification/basic-notification.component";

const SYNC_TEMPLATE_ERROR: string = "syncTemplateError";
const SYNC_NOTIFICATION_DURATION: number = 10000;

enum NOTIFICATION_TYPE {
    None = 0,
    Success = 1,
    Error = 2,
    Warning = 3
}

@Injectable()
export class SiteSyncCommand implements ExecuteOnceInBulkCommand {
    private commandResult: SyncCommandResult;
    private publishParams: PublishParams;
    private syncOperationResult: SyncOperationResult;
    private currentRoute: ActivatedRoute;
    private hasTemplateError: boolean = false;
    private isPublished: boolean = false;
    executeOnceInBulk: boolean = true;

    constructor(
        protected dynamicItemStore: DynamicItemStore,
        private modalWindowService: ModalWindowService) {
    }

    execute(context: ExecutionContext): Observable<SyncCommandResult> {
        const args = context.data;
        this.currentRoute = context.currentRoute;
        const doneCallback = new Subject<SyncCommandResult>();
        const actionButton: ActionButton = context.data.action;
        this.publishParams = args.publishParams;
        const changedTitle = this.publishParams && this.publishParams.fields ? this.publishParams.fields[context.data.entityData.metadata.defaultFieldName] : false;

        if (changedTitle) {
            actionButton.contextParameters[CONTEXT_PARAMETERS.currentTitle] = changedTitle;
        }

        const settings = this.generateConfirmationSettings(actionButton, args, doneCallback);
        this.modalWindowService.openModalConfirmation(this.currentRoute, settings, args.dataItem);

        return doneCallback.asObservable();
    }

    getNotification(route: ActivatedRoute): NotificationData {
        const notificationData: NotificationData = {
            look: NOTIFICATION_LOOKS.SUCCESS,
            type: BasicNotificationComponent,
            properties: {
                message: stringConstants.EMPTY_STRING,
                route: route ?? this.currentRoute
            },
            closeButton: true,
            duration: SYNC_NOTIFICATION_DURATION,
            updatePropertiesOnChange: true,
            id: "syncNotification"
        };

        if (this.hasTemplateError) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            return notificationData;
        }

        if (this.syncOperationResult) {
            if (this.syncOperationResult.isSuccessfull) {
                notificationData.closeButton = false;
            }

            notificationData.look = this.getNotificationLook(NOTIFICATION_TYPE[this.syncOperationResult.notificationType]);
            notificationData.properties.message = this.syncOperationResult.message;
            return notificationData;
        }

        return null;
    }

    private getNotificationLook(notificationType: number): string {
        switch (notificationType) {
            case NOTIFICATION_TYPE.Success:
                return NOTIFICATION_LOOKS.SUCCESS;
            case NOTIFICATION_TYPE.Error:
                return NOTIFICATION_LOOKS.ERROR;
            case NOTIFICATION_TYPE.Warning:
            case NOTIFICATION_TYPE.None:
                return NOTIFICATION_LOOKS.WARNING;
            default:
                return NOTIFICATION_LOOKS.WARNING;
        }
    }

    private generateConfirmationSettings(actionButton: ActionButton, arg: any, done: Subject<SyncCommandResult>): ModalComponentSettings {
        let confirmationButtonTitle = actionButton.title;
        const publishAndSyncOperation = actionButton.sourceOperation?.Actions?.find(o => o.Name === OPERATION_NAMES.siteSync);

        if (publishAndSyncOperation) {
            confirmationButtonTitle = publishAndSyncOperation.Title;
        }
        const confirmButton = arg.bulk ?
            new ConfirmButton(actionButton.title, data => this.startBulkSync(arg, data)) :
            new ConfirmButton(confirmationButtonTitle, data => this.startSiteSync(data));

        const settings: ModalComponentSettings = {
            title: actionButton.title,
            detailedTitle: actionButton.detailedTitle,
            icon: ActionIcon[actionButton.name],
            parameters: actionButton.parameters,
            contextParameters: actionButton.contextParameters,
            description: actionButton.description,
            formValidators: OPERATION_VALIDATOR_MAP[actionButton.name],
            action: actionButton.name,
            descriptionAllowHtml: true,
            buttons: new Array<Button>(confirmButton, new CancelButton()),
            disableUserInteractionOnLoading: true, // user should not be able to leave the dialog or do any actions while the sync is in progress
            innerFormLook: "sf-pb-zero sf-pt-zero",
            doneCallback: (context) => {
                if (context.data && context.data.data) {
                    if (this.commandResult && this.commandResult.error) {
                        const commandError = this.commandResult.error;
                        this.hasTemplateError = this.isTemplateSyncError(commandError);
                        if (this.hasTemplateError) {
                            this.commandResult.hasTemplateErrors = this.hasTemplateError;
                            const settings = this.generateTemplateErrorSettings(commandError.result.Title, commandError.result.Message);
                            this.modalWindowService.openModalConfirmation(this.currentRoute, settings, context.component.dataItem);
                        }
                    }

                    done.next(this.commandResult);
                } else {
                    done.next({ isPublished: false, dataItem: null, operationMessage: null, success: false });
                }
            }
        };

        return settings;
    }

    private startSiteSync(context): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (context && context.component && context.component.dataItem) {
            // Trigger loading in the confirm button
            clickResult.next(new ClickResult(true, false));

            const singleSyncComponent = context.component.editableFields?.wrapperComponents[0].currentInstance as SiteSyncItemInfoComponent;
            let shouldPublish = false;
            if (context.component.contextParameters) {
                const shouldPublishParam = context.component.contextParameters.find(param => param.Name === "ShouldPublish");
                if (shouldPublishParam) {
                    shouldPublish = shouldPublishParam.Value === "True";
                }
            }

            const targetSiteActionParameter = context.component.editableFields?.getFields(false);
            if (targetSiteActionParameter) {
                targetSiteActionParameter["SiteSync"] = singleSyncComponent != null ? singleSyncComponent.targetSiteId : null;
                targetSiteActionParameter["ShouldPublish"] = shouldPublish;
            }

            const singleSyncAction = new Action(OPERATION_NAMES.siteSync, { action: OPERATION_NAMES.siteSync, actionParameters: targetSiteActionParameter });

            let item: DataItem = context.component.dataItem;
            this.isPublished = false;

            // Items that do not have workflow, should not be saved, because Save with no changed properties won't log them for sync
            let itemObservable;
            if (shouldPublish) {
                // By design the item has to be published before it is synced. Sync operation is only available to users who can publish.
                const publishAction = new Action(OPERATION_NAMES.publish, { action: OPERATION_NAMES.publish });
                itemObservable = this.dynamicItemStore.saveItemWithOperationResult(
                    context.component.dataItem,
                    this.publishParams.fields,
                    publishAction,
                    this.publishParams.fallbackPropertyNames,
                    this.publishParams.dataFieldNames,
                    this.publishParams.itemPosition,
                    this.publishParams.skipUpdate || false)
                    .pipe(switchMap((result: ItemWithOperationResult) => {
                        item = result.dataItem;
                        this.isPublished = true;

                        // Proceed with sync action only when the item is successfully published or synced
                        return this.dynamicItemStore.saveItemWithOperationResult(result.dataItem, null, singleSyncAction);
                    }));
            } else {
                itemObservable = this.dynamicItemStore.saveItemWithOperationResult(context.component.dataItem, null, singleSyncAction);
            }

            // Operation data should be passed to the final result, in order to pass validations in handle save operation logic in edit item screen
            let operationData: any = {};
            itemObservable.subscribe((result) => {
                operationData = result.operationData;

                this.syncOperationResult = {
                    isSuccessfull: operationData.Success,
                    message: operationData.Message,
                    notificationType: NOTIFICATION_TYPE[operationData.Type]
                };
                // published and synced
                this.commandResult = { isPublished: true, dataItem: item, operationMessage: null, operationData: operationData };
                clickResult.next(new ClickResult(true, true, false, false));

            }, (err) => {
                this.syncOperationResult = {
                    isSuccessfull: false,
                    generalErrors: err.message,
                    message: `Content failed to be sent for syncing. ${err.message}`,
                    notificationType: NOTIFICATION_TYPE[NOTIFICATION_TYPE.Error]
                };
                this.commandResult = { isPublished: this.isPublished, error: err, dataItem: item, operationMessage: null, operationData: err.result || {} };
                clickResult.next(new ClickResult(true, true, false, false));
            });

            return clickResult;
        }
    }

    private startBulkSync(args: any, context: any): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (context && context.component) {
            // Trigger loading in the confirm button
            clickResult.next(new ClickResult(true, false));
            const operation: string = `${OPERATION_CATEGORIES.default}${stringConstants.DOT}BulkSync`;
            const singleSyncComponent = context.component.editableFields?.wrapperComponents[0].currentInstance as SiteSyncItemInfoComponent;

            let containsFoldersItems: boolean = false;
            if (MediaHelpers.isMediaEntity(args.entityData)) {
                args.selectedItems.forEach(dataItem => {
                    if (MediaHelpers.isFolderItem(dataItem.data)) {
                        containsFoldersItems = true;
                        return;
                    }
                });
            }

            const payLoad = {
                data: {
                    SelectedItemsIds: args.selectedItems.map(item => { return item.data.Id; }),
                    TargetServerId: singleSyncComponent != null ? singleSyncComponent.targetSiteId : null,
                    ContainsFoldersItems: containsFoldersItems,
                    AllItemsSelected: args.allItemsSelected,
                    Culture: args.entityData.culture
                }
            };

            const entityOperationResult$ = this.dynamicItemStore.executeEntityOperation(args.entityData, operation, payLoad);

            let operationData = {};
            entityOperationResult$.subscribe((result) => {
                operationData = result;
                this.syncOperationResult = {
                    isSuccessfull: result.Success,
                    message: result.Message,
                    notificationType: result.Type
                };

                if (result.Success) {
                    this.commandResult = { isPublished: false, dataItem: null, operationMessage: null, operationData: operationData, success: true };
                    clickResult.next(new ClickResult(true, true, false, false));
                } else {
                    const error = {
                        result: result
                    };
                    this.commandResult = { isPublished: false, error, dataItem: null, operationMessage: null, operationData: operationData, success: false };
                    clickResult.next(new ClickResult(true, true, false, false));
                }
            },
                (error) => {
                    this.syncOperationResult = {
                        isSuccessfull: false,
                        message: `Items failed to to be sent for syncing. ${error.message}`,
                        notificationType: NOTIFICATION_TYPE[NOTIFICATION_TYPE.Error]
                    };
                    this.commandResult = { isPublished: false, error, dataItem: null, operationMessage: null, operationData: operationData, success: true };
                    clickResult.next(new ClickResult(true, true, false, false));
                });
        }

        return clickResult;
    }

    private generateTemplateErrorSettings(title: string, message: string): ModalComponentSettings {
        const templateErrorSettings: ModalComponentSettings = {
            title: title,
            action: OPERATION_NAMES.siteSync,
            icon: ActionIcon[OPERATION_NAMES.siteSync],
            descriptionAllowHtml: true,
            description: message,
            buttons: new Array<Button>(new CancelButton("Close"))
        };

        return templateErrorSettings;
    }

    private isTemplateSyncError(error): boolean {
        return error && error.result && error.result.AvailableActions && error.result.AvailableActions.indexOf(SYNC_TEMPLATE_ERROR) >= 0;
    }
}

export interface SyncCommandResult extends ItemWithOperationResult {
    isPublished: boolean;
    error?: any;
    success?: boolean;
    hasTemplateErrors?: boolean;
}

export interface PublishParams {
    fields: any;
    fallbackPropertyNames: string[];
    dataFieldNames: string[];
    itemPosition: ItemPosition;
    skipUpdate?: boolean;
}

interface SyncOperationResult {
    generalErrors?: string;
    message: string;
    isSuccessfull: boolean;
    notificationType: string;
}
