import { Component } from "@angular/core";
import { createValueAccessor } from "../../../../../../../fields";
import { ContentListSettings, ListSettingsComponent } from "./list-settings.component";
import { FieldRegistration, SettingsBase } from "../../../../../api";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-extended-list-settings",
    templateUrl: "./list-settings.component.html",
    providers: [createValueAccessor(ExtendedListSettingsComponent)]
})
export class ExtendedListSettingsComponent extends ListSettingsComponent {
    public choices: Array<ChoiceItem> = [
        { Value: "Paging", Name: "Use paging -" },
        { Value: "Limit", Name: "Show limited number -" },
        { Value: "All", Name: "Show all published items at once" }
    ];

    protected initializeEmptyValue() {
        this.writeValue(new ExtendedContentListSettings());
    }
}

class ExtendedContentListSettings extends ContentListSettings {
    ShowAll: boolean = false;
}

export const EXTENDED_LIST_SETTINGS_REGISTRY: FieldRegistration = {
    writeComponent: ExtendedListSettingsComponent,
    readComponent: ExtendedListSettingsComponent,
    settingsType: SettingsBase
};
