import { Command } from "../../shared/commands/command";
import { Injectable } from "@angular/core";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { Observable, of } from "rxjs";
import { ModalWindowService, DialogData } from "../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { EmbedMediaContentComponent } from "../media/embed-media/embed-media-content.component";

@Injectable()
export class EmbedMediaCommand implements Command {
    constructor(private modalWindowService: ModalWindowService) { }

    execute(context: ExecutionContext): Observable<any> {
        const componentData: ComponentData = {
            type: EmbedMediaContentComponent,
            properties: {
                dataItem: context.data.dataItem
            }
        };

        const dialogData = new DialogData(componentData, null, []);
        this.modalWindowService.setMapping(dialogData, "embedmedia");
        this.modalWindowService.show("embedmedia", context.currentRoute.parent);

        return of(true);
    }
}
