import { Input, OnInit, Component, ViewChild, ChangeDetectorRef, Inject } from "@angular/core";
import { ComponentCommunicationService } from "../../services/component-communication.service";
import { CompositeOperationsProvider } from "../../../content/dynamic-modules/services/operations/operations-provider";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { OperationsTarget, OperationsData } from "../../../content/dynamic-modules/services/operations/interfaces";
import { Operation, OPERATION_CATEGORIES } from "../action-menu/operation.model";
import { Observable, ReplaySubject } from "rxjs";
import { map } from "rxjs/operators";
import { ActionButton, ActionMenuOptions } from "../action-menu/action-menu-model";
import { ButtonsState } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { WorkflowOperationClickedEvent, ActionButtonsStateChanged } from "../../events/component-events";
import { ActionMenuComponent, DROPDOWN_DEFAULT_LOADER_STYLE } from "../action-menu/action-menu.component";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-wrokflow-operations-menu",
    templateUrl: "./workflow-operations-menu.component.html"
})
export class WorkflowOperationsMenuComponent extends SfRxBase implements OnInit {
    @Input() dataItem: DataItem;
    @Input() operationsTarget: OperationsTarget;
    @Input() iconTitle: string;
    @Input() ariaLabel: string;
    @Input() dropdownButtonIconName: string;
    @Input() options: ActionMenuOptions;
    @Input() buttonsLook: string;

    operations$: Observable<Operation[]>;
    buttonState$ = new ReplaySubject<ButtonsState>();
    @ViewChild(ActionMenuComponent, { static: true }) actionMenu: ActionMenuComponent;

    constructor(private communicationService: ComponentCommunicationService,
                private operationsProvider: CompositeOperationsProvider,
                private changeDetector: ChangeDetectorRef,
                @Inject(WINDOW_TOKEN) private window: Window) {
                    super();
                }

    ngOnInit() {
        const data = new OperationsData(this.dataItem, this.operationsTarget, undefined, { origin: this.window.location.href });

        this.operations$ = this.operationsProvider.getOperations(data)
            .pipe(map((ops: Operation[]) => {
                return ops.filter(op => op.Category.Name === OPERATION_CATEGORIES.workflow);
            }));

        const subscription = this.communicationService.subscribe(ActionButtonsStateChanged, ev => {
            if (ev.data) {
                this.actionMenu.loader = ev.data.primary ? DROPDOWN_DEFAULT_LOADER_STYLE : null;
                this.buttonState$.next(ev.data);
                this.changeDetector.detectChanges();
            }
        });

        this.registerSubscription(subscription);
    }

    onActionButtonClicked(actionButton: ActionButton) {
        this.communicationService.next(new WorkflowOperationClickedEvent({ button: actionButton, itemType: this.dataItem.metadata.typeFullName }), false);
    }
}
