import constants from "./taxonomy.constants";
import { SettingsBase } from "../../../../fields/field-settings-base";
import { DISPLAY_MODE } from "../../../../fields/fields-constants";
import { ComponentData } from "@progress/sitefinity-component-framework";

export const CHIP_ADD_BTN_LOOK = "circle small sf-mb-4xs";

export class TaxonomySettings extends SettingsBase {
    public name: string;
    public type: string;
    public id: string;
    public displayMode: string;
    public urlNameSanitizeRegex: string;
    public allowMultiple: boolean;
    public showMenuItems: boolean = true;
    public isParentSelection: boolean = false;
    public excludeParent: boolean = true;
    public skipInputSelection: boolean = false;
    public immutableitemIds: [string];
    public rootTaxonId: string;
    public customShowAllTaxaFunction: (componentData: ComponentData) => void;
    public removable: boolean = true;
    public forceShouldShowAll: boolean = false;
    public addButtonLook: string;

    public init(metadata: any): void {
        super.init(metadata);
        this.name = metadata[constants.TAXONOMY_NAME];
        this.title = this.title ? this.title : this.name;
        this.id = metadata[constants.TAXONOMY_ID];
        this.type = metadata[constants.TAXONOMY_TYPE];
        this.defaultValue = [];
        this.displayMode = DISPLAY_MODE.NORMAL;
        this.changeOnFocus = true;
        this.addButtonLook = CHIP_ADD_BTN_LOOK;
    }
}
