import { Component, Input, Output, EventEmitter, ViewChildren, AfterViewInit, ViewContainerRef, QueryList, ViewChild, ChangeDetectorRef, TemplateRef } from "@angular/core";

import { TreeWrapperComponent, TreeConfig } from "./../../../fields";
import { DISPLAY_MODE } from "../../fields-constants";
import { BehaviorSubject } from "rxjs";
import { CHIP_ADD_BTN_LOOK } from "../../../src/app/modules/taxonomy";

@Component({
    selector: "sf-chips",
    templateUrl: "./chips.component.html"
})
export class ChipsComponent implements AfterViewInit {
    @ViewChild("tree", { static: false }) tree: TreeWrapperComponent;
    @ViewChildren("editableElement") queryContents: QueryList<ViewContainerRef>;
    @Input() selectedChips: any[];
    @Input() isLoading: boolean;
    @Input() isReadOnly: boolean;
    @Input() isSingleSelection: boolean;
    @Input() isRemovable: boolean;
    @Input() look: string;
    @Output() newChipAdded = new EventEmitter<any>();
    @Output() focus = new EventEmitter<boolean>();
    @Output() moreButtonClicked = new EventEmitter<Event>();
    @Output() selectChip = new EventEmitter<any>();
    @Output() removeChip = new EventEmitter<any>();
    @Output() searchChips = new EventEmitter<any>();
    @Output() showAllData = new EventEmitter<void>();
    @Input() isSearchPending: boolean;
    @Input() displayMode: string = DISPLAY_MODE.NORMAL;
    @Input() chipAddButtonTitle: string;
    @Input() chipContentName: any;
    @Input() isHierarchical: boolean = false;
    @Input() displayField: string = "Title";
    @Input() treeConfig: TreeConfig = { showBreadcrumb: true, noSelection: false };
    @Input() selectedChipTemplate: TemplateRef<any>;
    @Input() closeOnContentSelect: boolean = false;
    @Input() showMoreButton: boolean = false;
    @Input() moreButtonText: string;
    @Input() set chipAddButtonLook(look: string) {
            this.chipAddBtnLook = look || CHIP_ADD_BTN_LOOK;
        }
    @Input() config: ChipsConfig = {
        showRecentLabel: true,
        searchPlaceholder: "type to search"
    };

    @Input() set dropdownChips(value) {
        if (value) {
            this.hasDropDownItems = value.filter(x => x.isSeparator || x.isLink).length !== value.length;

            const chips = value.slice();
            if (this.config.actions && this.config.actions.length) {
                this.config.actions.forEach(action => {
                    chips.push({ isSeparator: true });
                    chips.push({
                        isLink: true,
                        [this.displayField]: action.label,
                        action: action.action
                    });
                });
            }

            if (this.treeConfig?.dataProperties?.alternativeTitleField) {
                const synonymIndex = chips.findIndex(x => x[this.treeConfig.dataProperties.alternativeTitleField.toString()]);
                if (synonymIndex > -1) {
                    chips.splice(synonymIndex, 0,
                        { isSeparator: true },
                        {
                            isSelectionDisabled: true,
                            isHeading: true,
                            [this.displayField]: this.treeConfig.dataProperties.alternativeTitleField
                        });
                    }
            }

            this._dropdownChips = chips;
        } else {
            this._dropdownChips = value;
        }
    }

    get dropdownChips() {
        return this._dropdownChips;
    }

    chipAddBtnLook: string = CHIP_ADD_BTN_LOOK;
    closeOnEscape: boolean = true;
    hasDropDownItems = false;
    isEditing: boolean = false;
    showEditableField: boolean = false;

    private editableElement: any;
    private searchText: string;
    private _dropdownChips: any[];
    private triggeringSubscription = new BehaviorSubject(false);

    constructor(private changeDetectorRef: ChangeDetectorRef) {
    }

    onNewInputValue(event: Event) {
        this.triggeringSubscription.next(true);
        const target: any = event.target || event.srcElement;
        // textContent for normal (chip) mode and value for input mode
        this.searchText = target.textContent || target.value;
        this.searchChips.emit(this.searchText);
        this.tree.clearFocusedNode();
    }

    OnMoreButtonClicked(event: Event) {
        this.moreButtonClicked.emit(event);
    }

    onShowAllData() {
        this.showAllData.emit();
    }

    ngAfterViewInit() {
        this.queryContents.changes.subscribe((values: QueryList<any>) => {
            this.editableElement = values.first;
            if (!this.tryFocus()) {
                this.resetValue();
                this.changeDetectorRef.detectChanges();
            }
        });
    }

    toggleEditableField() {
        this.showEditableField = !this.showEditableField;
        if (this.showEditableField) {
            this.searchChips.emit(this.searchText);
        }

        this.focus.emit(this.showEditableField);
    }

    initEditableField() {
        this.triggeringSubscription.next(true);

        if (this.searchText) {
            this.showEditableField = true;
            this.searchChips.emit(this.searchText);
            this.selectChip.emit(null);
        } else if (this.selectedChips !== null && this.selectedChips.length > 0) {
            this.showEditableField = false;
            this.searchChips.emit(null);
            const firstChip = this.selectedChips[0];
            if (firstChip) {
                const chipItem = this.dropdownChips.find((x) => x.Id === firstChip.Id);

                if (chipItem && (!chipItem.isLink || !chipItem.isSeparator)) {
                    this.selectChip.emit(chipItem);
                } else if (!firstChip.isLink || !firstChip.isSeparator) {
                    this.selectChip.emit(firstChip);
                }
            }
        } else if (this.selectedChips === null || this.selectedChips.length === 0) {
            this.searchChips.emit(null);
            this.showEditableField = true;
        }
    }

    onContentFocusOut(shouldAddChip: boolean = false) {
        if (!this.isHierarchical && shouldAddChip) {
            this.onNewChipAdded(this.searchText);
        }

        this.showEditableField = false;
        this.isEditing = false;
        this.focus.emit(this.showEditableField);
    }

    onNewChipAdded(title: string) {
        if (title) {
            title = title.trim();
            this.newChipAdded.emit(title);
            this.searchChips.emit(null);
        }

        this.tryFocus();
        this.resetValue();
    }

    onNewChipSelected(item: any) {
        if (item) {
            const chipItem = this.dropdownChips.find((x) => x.Id === item.id);
            this.selectChip.emit(chipItem);
            this.searchChips.emit(null);
        }

        //shouldn't focus chip when opening a dialog - this is when isLink is true
        if (this.closeOnContentSelect || (item.data && item.data.isLink)) {
            this.toggleEditableField();
        } else {
            this.tryFocus();
            this.resetValue();
        }
    }

    onEditClick() {
        this.triggeringSubscription.next(false);
        this.showEditableField = true;
        this.isEditing = true;
        this.searchChips.emit(this.searchText);
    }

    onInitialized() {
        if (this.isSingleSelection && this.selectedChips && this.selectedChips.length > 0 && this.config.showSelectedItemAsActive) {
            const selectedChip = this.selectedChips[0];
            this.tree.selectAndActivateNodeById(selectedChip.Id);
        }
    }

    onEnterKey() {
        const focusedElement = this.tree.getFocusNodeValue();
        if (focusedElement) {
            if (this.displayMode === DISPLAY_MODE.INPUT) {
                this.selectChip.emit(focusedElement);
                this.resetValue();
                if (this.closeOnContentSelect) {
                    this.toggleEditableField();
                }
            }

            return;
        }

        this.onNewChipAdded(this.searchText);
    }

    onEscapeKey(event: Event) {
        this.onContentFocusOut();
        event.stopPropagation();
    }

    onFocusTree() {
        this.tree.focusTree();
    }

    onFocusNextNode(): void {
        this.tree.focusNextNode();
    }

    onFocusPreviousNode(): void {
        this.tree.focusPreviousNode();
    }

    onRemoveChip(chip: any) {
        this.removeChip.emit(chip);
        this.focus.emit(this.showEditableField);
    }

    shouldShowAddButton() {
        const singleSelectionVisibility = !this.showEditableField && !this.isSingleSelection;
        const multipleSelectionVisibility = !this.showEditableField && this.isSingleSelection && this.selectedChips && this.selectedChips.length === 0;
        return singleSelectionVisibility || multipleSelectionVisibility;
    }

    generateCssClassListFromLook() {
        let cls = "";
        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.isSingleSelection) {
            cls += " -no-wrap";
        }

        return cls;
    }

    generateCssClassForChip(chip: any) {
        let cls = "-sf-max-width-100";
        if(chip.ShouldGrayOutText) {
            cls += " -sf-txt-hint";
        }

        if(this.shouldShowAddButton() || (!this.showEditableField && this.isSingleSelection && this.selectedChips && this.selectedChips.length > 0 && !this.config.hideEditButton)){
            cls += " -sf-min-width-zero";
        }
        return cls;
    }

    private tryFocus(): boolean {
        if (this.editableElement) {
            this.editableElement.focus();

            return true;
        }
        return false;
    }

    private resetValue() {
        this.searchText = null;
        if (this.editableElement) {
            if (this.displayMode === DISPLAY_MODE.NORMAL) {
                this.editableElement.contentArea.nativeElement.textContent = null;
            } else if (this.displayMode === DISPLAY_MODE.INPUT) {
                this.editableElement.value = null;
            }
        }
    }
}

export interface ChipsConfig {
    showRecentLabel?: boolean;
    showNoResultsLabel?: boolean;
    showSelectedItemAsActive?: boolean;
    focusFirstNode?: boolean;
    searchPlaceholder?: string;
    hideEditButton?: boolean;
    actions?: ChipsAction[];
    skipInputSelection?: boolean;
}

interface ChipsAction {
    label: string;
    action: void;
}
