import { StorageService } from "../shared/services/storage.service";
import { Token } from "./auth.provider";

export abstract class TokenProvider {

    protected getTokenFromStorage(storage: StorageService, tokenName: string): ExternalToken {
        const tokenFromStorage = storage.getItem(tokenName);
        if (!tokenFromStorage) {
            return null;
        }

        let token: ExternalToken;
        try {
            token = JSON.parse(tokenFromStorage);
        } catch (e) {
            return null;
        }
        if (token) {
            const today = new Date().getTime();
            if (isNaN(token.expireDate) || today > token.expireDate) {
                storage.removeItem(tokenName);
                token = null;
            }
        }
        return token;
    }
}

export interface ExternalToken extends Token {
    expireDate: number,
    lifetime: number
}
