import { from as observableFrom, of as observableOf, Observable } from "rxjs";

import { first, mergeMap } from "rxjs/operators";
import { Command, instanceOfExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ReplaySubject } from "rxjs";
import { OperationResult, DataItem } from "../../../interfaces";
import { RequiresConfirmationCommand } from "../../../../../shared/commands/requires-confirmation-command";
import { CommandNotificationArgs } from "../../../../../shared/commands/has-notification-command";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { BulkOperationsNotificationComponent } from "../../../components/bulk-operations/bulk-operations-notification.component";
import { ResponseError } from "../../../../../shared/services/errors/response-error";

const PARALLEL_REQUESTS_COUNT = 5;

export const SUCCESSFUL_NOTIFFICATION_TIME: number = 5000;
export const BULK_BATCH_COUNT: number = 5;

export class BulkCommand implements Command, RequiresConfirmationCommand {
    constructor(private innerCommand: Command) { }

    confirm(context: ExecutionContext): Observable<ExecutionContext> {
        const confirmCommand = <RequiresConfirmationCommand>this.innerCommand;
        if (!confirmCommand.confirm) {
            context.data.confirmed = true;
            return observableOf(context);
        }

        return confirmCommand.confirm(context);
    }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        if (!context.data.bulk || instanceOfExecuteOnceInBulkCommand(this.innerCommand)) {
            return this.innerCommand.execute(context);
        }

        const selectedItems$ = observableFrom(context.data.selectedItems);
        const handled = new ReplaySubject<BulkOperationResult>(1);

        const result: BulkOperationResult = {
            success: true,
            failedItemsIds: [],
            succeededItemsIds: [],
            failedItemsErrors: {}
        };

        selectedItems$.pipe(
            mergeMap((item: DataItem) => this.getOperationExecutionResult(item, context), null, PARALLEL_REQUESTS_COUNT))
            .subscribe((item: OperationResult) => {
                if (!item.success) {
                    result.failedItemsIds.push(item.key);
                    result.failedItemsErrors[item.key] = item.error;
                } else {
                    result.succeededItemsIds.push(item.key);
                }
            }, err => {
                throw err;
            }, () => {
                handled.next(result);
            });

        return handled;
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!succeededItems && !failedItems) {
            return null;
        }

        const operationPartiallySucceeded: boolean = succeededItems && succeededItems.length > 0 && failedItems && failedItems.length > 0;
        const operationFailed: boolean = !operationPartiallySucceeded && failedItems && failedItems.length > 0;
        const operationSucceeded: boolean = !operationPartiallySucceeded && succeededItems && succeededItems.length > 0;

        const notificationData: NotificationData = {
            type: BulkOperationsNotificationComponent,
            properties: {
                succeededItemsIds: succeededItems,
                failedItemsIds: failedItems,
                entityData: args.entityData,
                operationName: args.action.name.toLowerCase()
            },
            id: "bulkOperationsNotification",
            look: NOTIFICATION_LOOKS.SUCCESS
        };

        if (operationSucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            notificationData.duration = SUCCESSFUL_NOTIFFICATION_TIME;
        } else if (operationFailed) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            notificationData.closeButton = true;
        } else if (operationPartiallySucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.WARNING;
            notificationData.closeButton = true;
        }

        return notificationData;
    }

    private getOperationExecutionResult(dateItem: DataItem, context: ExecutionContext): Observable<OperationResult> {
        const operationResult$ = new ReplaySubject<OperationResult>(1);
        const newContext: ExecutionContext = Object.assign({}, context);

        newContext.data = Object.assign({}, context.data);
        newContext.data.dataItem = dateItem;

        this.innerCommand
            .execute(newContext)
            .subscribe(
                r => operationResult$.next(r),
                (error) => operationResult$.next({ key: dateItem.key, success: false, error })
            );

        return operationResult$.pipe(first());
    }
}

/**
 * @ExposedInApi {BulkOperationResult} BulkOperationResult v1/commands/command.d.ts
 */
export interface BulkOperationResult {
    success: boolean;
    failedItemsIds?: Array<string>;
    succeededItemsIds?: Array<string>;
    failedItemsErrors?: { [key: string]: ResponseError };
    items?: Array<DataItem>;
    reload?: boolean;
}

export interface BulkResult {
    Message: string;
    Type: BulkResultType;
    SucceededItemsIds: string[];
    FailedItemsIds: string[];
}

export enum BulkResultType {
    Success = "Success",
    Warning = "Warning",
    Error = "Error"
}
