import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { SiteDataStore } from "./metadata/site-data.store";
import { Title } from "@angular/platform-browser";
import { ROUTE_PATHS_NO_PREFIX } from "../../../constants/route-paths";
import { Subscription } from "rxjs";

@Injectable()
export class SiteTitleResolver implements Resolve<any> {
    protected map: { [path: string]: string; } = { };
    protected titlePatternPage: string = "{1} - {0}";
    protected titlePatternEmpty: string = "{0}";

    constructor(protected siteDataStore: SiteDataStore, protected title: Title) {
        this.map[ROUTE_PATHS_NO_PREFIX.HOME] = "Home";
        this.map[ROUTE_PATHS_NO_PREFIX.MENU_HOME] = "Home";
        this.map[ROUTE_PATHS_NO_PREFIX.CONTENT] = "Content";
        this.map[ROUTE_PATHS_NO_PREFIX.PAGES] = "Pages";
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Subscription {
        return this.siteDataStore.getValue().subscribe(siteData => {
            this.updateBrowserTitle(route, siteData.Name);
        });
    }

    public updateBrowserTitle(route: ActivatedRouteSnapshot, siteName: string): void {
        const titlePattern: string = this.getTitlePattern(route);
        const siteTitle: string = titlePattern.replace("{0}", siteName);

        this.title.setTitle(siteTitle);
    }

    public updateBrowserTitleByText(browserTitle: string): void {
        this.siteDataStore.getValue().subscribe(siteData => {
            const siteTitle: string = this.titlePatternPage.replace("{0}", siteData.Name).replace("{1}", browserTitle);
            this.title.setTitle(siteTitle);
        });
    }

    protected getTitlePattern(route: ActivatedRouteSnapshot): string {
        let path: string = "";

        if (route && route.url.length > 0) {
            path = route.url[0].path;
        }

        const pathTitle: string = this.map[path];
        if (pathTitle) {
            return this.titlePatternPage.replace("{1}", pathTitle);
        }

        return this.titlePatternEmpty;
    }
}
