import { Component, Input, OnInit, TemplateRef, ViewChild } from "@angular/core";
import { DataItem, EntityData } from "../../../../content/dynamic-modules/interfaces";
import { FieldBase } from "../../../../../../../fields";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { ChoiceItem, ChoiceSettingsBase } from "@progress/sitefinity-component-framework/lib/common/models/choice.model";

const DEFAULT_CUSTOM_EXPIRATION_DAYS_VALUE = 90;
const CUSTOM_CHOICE_VALUE = "Custom";

@Component({
    templateUrl: "./set-custom-expiration.component.html",
})
export class SetCustomExpirationComponent extends FieldBase implements OnInit {
    @Input() entityData: EntityData;
    @Input() selectedItems: DataItem[];
    @ViewChild("customDays", { static: true }) private customDaysTmpl: TemplateRef<any>;
    itemTitle: string = null;
    count: number;
    isLoading: boolean = true;
    choices: Array<ChoiceItem>;
    inputEnabled: boolean = false;
    customDaysValue: number = DEFAULT_CUSTOM_EXPIRATION_DAYS_VALUE;
    choiceSettings: ChoiceSettingsBase = {
        wrapperCssClass: "-list-style-none sf-field__content",
        choiceCssClass: "sf-row -align-items-center -no-wrap",
        textCssClass: "sf-row -align-items-center",
        labelCssClass: "-inline sf-row__col -no-flex",
        readOnlyMode: false,
        showExpandedTemplateAlways: true,
        key: "expirationChoices"
    };


    constructor(private dynamicItemService: DynamicItemService) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.init();
    }

    onSelectionChange(index: number) {
        if (this.choices[index].Value === CUSTOM_CHOICE_VALUE) {
            this.inputEnabled = true;
            this.writeValue(this.customDaysValue);
        }
        else {
            this.inputEnabled = false;
            const value = typeof this.choices[index].Value === "string" ? +this.choices[index].Value : this.choices[index].Value
            this.writeValue(value);
        }
    }

    protected onCustomDaysChoiceChanged(customDaysValue: string) {
        this.customDaysValue = +customDaysValue;
        this.writeValue(this.customDaysValue);
    }

    private init() {
        if (this.selectedItems.length === 1){
            this.itemTitle = this.selectedItems[0].title;
        }

        this.dynamicItemService.executeBoundFunction(DataItem.fromKey(this.selectedItems[0].key, this.entityData), `Default.GetPageExpiration()`).subscribe((response: any) => {

            const configuredExpiration = response.ConfiguredExpirationInDays;
            const customExpiration = response.CustomExpirationInDays;

            this.choices = [
                {
                    Name: `As set for all pages (${configuredExpiration} days)`,
                    Value: null
                },
                {
                    Name: "After",
                    Value: CUSTOM_CHOICE_VALUE,
                    ExpandedTemplate: this.customDaysTmpl
                },
                {
                    Name: "Never",
                    Value: "0",
                }
            ];

            let selectedIndex = 0;
            this.count = this.selectedItems.length;
            if (this.count == 1) {
                if (customExpiration === 0) {
                    selectedIndex = 2;
                }
                else if (customExpiration > 0) {
                    selectedIndex = 1;
                    this.inputEnabled = true;
                    this.customDaysValue = customExpiration;
                }
            }

            this.choices[selectedIndex].Selected = true;
            this.onSelectionChange(selectedIndex);
            this.isLoading = false;
        });
    }
}
