import { BackgroundTask, BackgroundTaskType } from "../../services/background-task.types";

export class BackgroundTaskDataParser {
    static parse(task: BackgroundTask): TaskDataParsedBase | string {

        if (task.TaskName === BackgroundTaskType.RegenerateThumbnails) {
            const dataArray = task.TaskData.split(";");
            const data = {
                libraryId: dataArray[0],
                provider: dataArray[1],
                thumbnailProfiles: dataArray.slice(2, dataArray.length - 2),
                siteId: dataArray[dataArray.length - 1]
            };

            return data;
        } else if (task.TaskName === BackgroundTaskType.MoveLibraryAlternative) {
            const taskData = JSON.parse(task.TaskData);

            const data: MoveToLibraryTaskDataParsed = {
                itemId: taskData.ItemId,
                itemIds: taskData.ItemIDs,
                libraryId: taskData.ParentId,
                provider: taskData.LibraryProvider,
                newItemId: taskData.NewItemId,
                libraryTitle: taskData.LibraryTitle,
                siteId: null
            };

            return data;
        } else if (task.TaskName === BackgroundTaskType.StorageRelocationAlternative) {
            const dataArray = task.TaskData.split(";");

            return <ChangeProviderTaskDataParsed>{
                libraryId: dataArray[0],
                provider: dataArray[1],
                libraryTitle: dataArray[2]
            };
        } else if (task.TaskName === BackgroundTaskType.DamMigrationTask) {
            const taskData = JSON.parse(task.TaskData);

            return <TaskDataParsedBase>{
                libraryId: taskData.LibraryId,
                provider: taskData.ProviderName
            };
        }

        return task.TaskData;
    }
}

export interface TaskDataParsedBase {
    libraryId: string;
    provider: string;
    siteId?: string;
}

export interface RegenerateTaskDataParsed extends TaskDataParsedBase {
    thumbnailProfiles: string[];
}

export interface MoveToLibraryTaskDataParsed extends TaskDataParsedBase {
    itemIds: string[],
    newItemId: string,
    itemId: string;
    libraryTitle: string;
}

export interface ChangeProviderTaskDataParsed extends TaskDataParsedBase {
    libraryTitle: string;
}
