import { Injectable } from "@angular/core";
import { Store, ActionReducerMap } from "@ngrx/store";
import { AppState } from "./store-schema";
import { sidebarReducer, sidebarMetaReducer } from "./reducers/reducers.sidebar";
import { mobilePreviewReducer } from "./reducers/reducers.mobile-preview";
import { fieldsReducer } from "./reducers/reducers.fields";
import { mediaReducer } from "./reducers/reducers.media";
import { columnExpandCollapseReducer } from "./reducers/reducer.columns";

@Injectable()
export class AppStore extends Store<AppState> {
    static readonly componentsMap = {};
}

export const actionReducersMap: ActionReducerMap<AppState> = {
    sidebar: sidebarReducer,
    mobilePreview: mobilePreviewReducer,
    fields: fieldsReducer,
    media: mediaReducer,
    columns: columnExpandCollapseReducer
};

export const metaReducersMap = [
    sidebarMetaReducer
];
