import { ActivatedRoute } from "@angular/router";
import { Observable, ReplaySubject } from "rxjs";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ContentCultureData } from "../../shared/services/metadata/site-data.store";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { FilePickerComponent, FILE_PICKER } from "../file-picker.component";
import { FilePickerViewMode } from "../file-picker-view-mode";
import { Injectable } from "@angular/core";
import { DialogData, ModalWindowService } from "../../shared/services/modal-window.service";
import { HttpODataRequestWrapper } from "../../shared/services/http-odata-request.wrapper";
import { QUERY_PARAMS } from "../../content/constants";
import { ComponentCommunicationService } from "../../shared/services/component-communication.service";
import { ChangeButtonStateInItemEdit } from "../../shared/events/component-events";
import { ButtonState } from "../../shared/components/action-menu/action-menu-model";
import { DamAsset } from "../dam/dam-provider-base";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../../shared/components/modal-window/modal-window.component";

export interface MediaOperationData {
    operationName: string;
    item: any;
    route?: ActivatedRoute;
    mediaDataItem: DataItem;
    input: HTMLInputElement
}

const OPERATIONS = {
    REPLACE_FILE: "Replace file",
    REPLACE_FILE_FOR_CURRENT_TRANSLATION: "Replace file for current translation"
};

@Injectable()
export class MediaHandler {
    private replaceFile$: ReplaySubject<any>;

    constructor(protected readonly modalWindowService: ModalWindowService,
        protected http: HttpODataRequestWrapper,
        protected communicationService: ComponentCommunicationService) {
    }

    canHandle(entityData: EntityData): boolean {
        return true;
    }

    executeOperation(data: MediaOperationData): Observable<any> {
        switch (data.operationName) {
            case OPERATIONS.REPLACE_FILE:
            case OPERATIONS.REPLACE_FILE_FOR_CURRENT_TRANSLATION:
                return this.handleReplaceFile(data);
        }
    }

    getEditOperations(item: any, hasPreviewError: boolean = false, siteLanguages: Array<ContentCultureData> = [], isDamMedia: boolean = false): string[] {
        if (siteLanguages.length > 1) {
            return Object.values(OPERATIONS);
        }

        return [OPERATIONS.REPLACE_FILE];
    }

    private handleReplaceFile(data: MediaOperationData): Observable<any> {
        this.replaceFile$ = new ReplaySubject<any>();
        const currentTranslationOnly: boolean = data.operationName === OPERATIONS.REPLACE_FILE_FOR_CURRENT_TRANSLATION;

        const isDamMedia = data.mediaDataItem.data.IsDamMedia;
        const componentData: ComponentData = {
            type: FilePickerComponent,
            properties: {
                multiple: false,
                allowCreate: true,
                skipUpload: true,
                mediaEntityData: data.mediaDataItem,
                initialViewMode: FilePickerViewMode.Select,
                showTranslations: currentTranslationOnly,
                enableDamPicker: isDamMedia,
                damNotificationFilter: MODAL_WINDOW_NOTIFICATION_FILTER,
                isReplaceFile: true,
                importAssetsOnSelect: false
            }
        };

        const dialogData = new DialogData(componentData, (result) => {
            if (result && result.data) {
                if (result.data.data && result.component.fromUpload === false) {
                    // select from existing files
                    const resultDataItem = result.data;
                    const data = resultDataItem.data;
                    let culture = resultDataItem.culture;
                    const fileId = resultDataItem.data.FileId ? resultDataItem.data.FileId : null;
                    // If the item is selected from already uploaded images for other translations of the item
                    // then the id is fileId instead of mediaContentId because mediaContentId is the same
                    const mediaContentId = resultDataItem.data.MediaContentId ? resultDataItem.data.MediaContentId : resultDataItem.key;

                    if (resultDataItem.data.Cultures && resultDataItem.data.Cultures.length > 0) {
                        culture = resultDataItem.data.Cultures[0];
                    }

                    const params = {
                        [QUERY_PARAMS.CULTURE]: culture,
                        [QUERY_PARAMS.PROVIDER]: resultDataItem.provider
                    };

                    this.communicationService.next(new ChangeButtonStateInItemEdit(ButtonState.Loading));
                    this.http.get(`${resultDataItem.metadata.setName}(${mediaContentId})/$value`, { responseType: "blob", params })
                        .then(blob => {
                            // If data has FileId property then the selection is from already uploaded images for other translations of the item
                            // In this case the name of the file should be like sf-fileId:<guid>.<extension>
                            // so on the server it could be mapped to the media link of the image from selected culture instead of uploaded as a new one
                            const fileName = fileId ? `sf-fileId:${fileId}${data.Extension}` : data.Title + data.Extension;
                            const file = new File([blob], fileName, { type: data.MimeType });
                            const originalFileName = (data.MediaFileUrlName ? data.MediaFileUrlName : data.Title) + data.Extension;
                            const fileResult = { files: [file], preserveFileName: currentTranslationOnly, originalFileNames: [originalFileName] };
                            this.replaceFile$.next(fileResult);
                            this.communicationService.next(new ChangeButtonStateInItemEdit(ButtonState.Default));
                        });
                } else if (result.data instanceof File && result.component.fromUpload) {
                    // upload a new file
                    const file = result.data;
                    const fileResult = { files: [file], preserveFileName: currentTranslationOnly };
                    this.replaceFile$.next(fileResult);
                } else if (result.data instanceof FileWrapper && isDamMedia) {
                    const file = result.data;
                    const fileResult = { files: [file], preserveFileName: currentTranslationOnly };
                    this.replaceFile$.next(fileResult);
                }
            } else {
                this.replaceFile$.next(null);
            }
        }, [], "-prompt");

        this.modalWindowService.setMapping(dialogData, FILE_PICKER);
        this.modalWindowService.open(data.route, FILE_PICKER);

        return this.replaceFile$.asObservable();
    }
}

export const MEDIA_HANDLER = {
    provide: MediaHandler,
    useClass: MediaHandler,
    multi: true
};

export class FileWrapper implements File {
    constructor(fileBits: BlobPart[], fileName: string, options?: FilePropertyBag, asset?: DamAsset, preserveFileName?: boolean) {
        this.file = new File(fileBits, fileName, options);
        this.asset = asset;
        this.size = this.file.size;
        this.type = this.file.type;
        this.lastModified = this.file.lastModified;
        this.name = this.file.name;
        this.preserveFileName = preserveFileName;
    }

    lastModified: number;
    name: string;
    webkitRelativePath: string;
    size: number;
    type: string;
    file: File;
    preserveFileName: boolean;
    asset: DamAsset;

    arrayBuffer(): Promise<ArrayBuffer>;
    arrayBuffer(): Promise<ArrayBuffer>;
    arrayBuffer(): Promise<ArrayBuffer> {
        return this.file.arrayBuffer();
    }
    slice(start?: number, end?: number, contentType?: string): Blob;
    slice(start?: number, end?: number, contentType?: string): Blob;
    slice(start?: any, end?: any, contentType?: any): Blob {
        return this.file.slice(start, end, contentType);
    }
    stream(): ReadableStream<any>;
    stream(): NodeJS.ReadableStream;
    stream(): ReadableStream<any> | NodeJS.ReadableStream {
        return this.file.stream();
    }
    text(): Promise<string>;
    text(): Promise<string>;
    text(): Promise<string> {
        return this.file.text();
    }

}
