import { ActionButton } from "../../../shared/components/action-menu/action-menu-model";

import { DataItem } from "../interfaces";

import { ModalComponentSettings, Button, ConfirmButton, ClickResult, CancelButton } from "../../../shared/services/modal-window.service";

import { ActionIcon, ActionEventsConfirmationDialogButtons } from "../services/entity/action-buttons";

import { ModalConfirmationComponent } from "../../../shared/components/modal-confirmation/modal-confirmation.component";
import { OPERATION_NAMES } from "../../../shared/components/action-menu/operation.model";
import { OPERATION_VALIDATOR_MAP } from "./dynamic-item.base";

export class WorkflowOperationSettingsProvider {
    static getConfirmationSettings(actionButton: ActionButton, dataItem: DataItem, editedFields: any, onDone: Function) {
        const settings: ModalComponentSettings = {
            title: actionButton.title,
            detailedTitle: actionButton.detailedTitle,
            icon: ActionIcon[actionButton.name] || "info",
            parameters: actionButton.parameters,
            contextParameters: actionButton.contextParameters,
            description: null,
            formValidators: OPERATION_VALIDATOR_MAP[actionButton.name],
            action: actionButton.name,
            buttons: WorkflowOperationSettingsProvider.getButtons(actionButton),
            doneCallback: (context) => onDone(context, actionButton, dataItem, editedFields)
        };

        return settings;
    }

    static getFields(context) {
        if (context.data && context.data.data && context.component) {
            if (context.component instanceof ModalConfirmationComponent) {
                const component = <ModalConfirmationComponent>context.component;
                if (!component.editableFields) {
                    return null;
                }

                // if the operation is schedule and there are dirty fields we want to get all fields
                // because PublicationDate is required
                // otherwise we do not want to return fields in order not to update the item
                const hasDirtyFields = component.editableFields.getFields() !== null;
                if (component.action === OPERATION_NAMES.schedule && !hasDirtyFields) {
                    return null;
                }

                const fields = component.editableFields.getFields(false);
                return fields;
            }
        }

        return null;
    }

    private static getButtons(actionButton: ActionButton) {
        return new Array<Button>(new ConfirmButton(ActionEventsConfirmationDialogButtons[actionButton.name] || "Save changes", (data => {
            if (data.component instanceof ModalConfirmationComponent && data.component.parameters && data.component.editableFields) {
                const component: ModalConfirmationComponent = data.component;
                return new ClickResult(true, component.editableFields.valid());
            }

            return new ClickResult(true, true);
        })), new CancelButton());
    }
}
