import { Injectable } from "@angular/core";
import { ContainerModel, ComponentModel } from "../components/zone-editor/model/component-model";
import { ATTR_CONTAINER, NODE_TYPE_COMMENT, ATTR_COMPONENT_NAME, ATTR_IS_EMPTY, NODE_TYPE_ELEMENT, NODE_TYPE_TEXT, ATTR_IS_CONTENT, ATTR_ERROR, ATTR_PREFIX } from "./document-enhancer.constants";

const NODE_NAMES_EXCLUDED = ["VIDEO", "IMG", "IFRAME", "AUDIO", "FIGURE", "OBJECT", "MAP", "EMBED", "CANVAS", "INPUT", "OUTPUT", "METER", "TEXTAREA"];
@Injectable()
export class DocumentEnhancerService {

    public buildModel(element: Element, parentElement: Element, parent: ComponentModel): ComponentModel | ContainerModel {
        this.enhance(parentElement);

        if (element.hasAttribute(ATTR_COMPONENT_NAME)) {
            return this.buildModelFromWidget(element, parent);
        }

        if (element.hasAttribute(ATTR_CONTAINER)) {
            return this.buildModelFromContainer(element, parent);
        }

        return null;
    }

    public enhance(el: Element): void {
        for (let i = 0; i < el.childNodes.length; i++) {
            const node = el.childNodes[i] as Element;
            if (node.nodeType === NODE_TYPE_COMMENT) {
                if (node.nodeValue.startsWith("Start") || node.nodeValue.startsWith("ContainerStart")) {
                    const wrapperElement = this.fixWrapperElement(el, i, node.nodeValue);
                    this.addWidgetMeta(wrapperElement, node.nodeValue);
                    node.nodeValue = node.nodeValue.replace("Start", "Enhanced");
                }
            } else {
                if (node.nodeType === NODE_TYPE_ELEMENT && (node.hasAttribute(ATTR_COMPONENT_NAME) || node.hasAttribute(ATTR_CONTAINER))) {
                    this.addEmptyContentAttr(node as HTMLElement);
                }

                this.enhance(node);
            }
        }
    }

    private buildModelFromWidget(element: Element, parentComponent: ComponentModel): ComponentModel {
        const componentModel = new ComponentModel(element);
        componentModel.parentComponent = parentComponent;

        if (element.hasAttribute(ATTR_CONTAINER)) {
            const childContainer = this.buildModelFromContainer(element, parentComponent);
            childContainer.parentComponent = componentModel;
            componentModel.container = childContainer;
        } else {
            const children = this.getDirectChildrenWithAttribute(element, ATTR_COMPONENT_NAME, ATTR_CONTAINER, true);

            children.forEach(childEl => {
                const childContainer = this.buildModelFromContainer(childEl, componentModel);
                childContainer.parentComponent = componentModel;
                componentModel.childContainers.push(childContainer);
            });
        }

        return componentModel;
    }

    private buildModelFromContainer(element: Element, parentComponent: ComponentModel): ContainerModel {
        const containerModel = new ContainerModel(element);

        // nested child containers are supported, but we cannot mix both containers and widgets on the same level
        const childContainers = this.getDirectChildrenWithAttribute(element, ATTR_COMPONENT_NAME, ATTR_CONTAINER, false);
        childContainers.forEach(container => {
            const childContainer = this.buildModelFromContainer(container, null);
            containerModel.childContainers.push(childContainer);
        });

        const children = this.getDirectChildrenWithAttribute(element, ATTR_CONTAINER, ATTR_COMPONENT_NAME, true);
        children.forEach(childEl => {
            const childComponent = this.buildModelFromWidget(childEl, parentComponent);
            childComponent.parentContainer = containerModel;
            containerModel.children.push(childComponent);
        });

        return containerModel;
    }

    private getDirectChildrenWithAttribute(element: Element, stopAttrName: string, attrName: string, allowBothAttributes: boolean): Element[] {
        let widgets: Element[] = [];
        for (let i = 0; i < element.children.length; i++) {
            const childElement = element.children[i] as Element;
            const hasStopAttr = childElement.hasAttribute(stopAttrName);
            const hasAttr = childElement.hasAttribute(attrName);
            if (!allowBothAttributes && hasStopAttr && hasAttr) {
                continue;
            }

            if (hasAttr) {
                widgets.push(childElement);
            } else if (!hasStopAttr) {
                const children = this.getDirectChildrenWithAttribute(childElement, stopAttrName, attrName, allowBothAttributes);
                widgets = widgets.concat(children);
            }
        }

        return widgets;
    }

    private fixWrapperElement(parentElement: Element, startCommentIndex: number, startCommentValue: string): HTMLElement {
        const elementsInsideCommentTags: Node[] = [];
        for (let j = startCommentIndex; j < parentElement.childNodes.length; j++) {
            const currentElement = parentElement.childNodes[j];
            elementsInsideCommentTags.push(currentElement);

            if (currentElement.nodeType === NODE_TYPE_COMMENT && currentElement.nodeValue === startCommentValue.replace("Start", "End")) {
                break;
            }
        }

        let wrapperElement: HTMLElement = this.findExistingWrapperElement(elementsInsideCommentTags);
        if (!wrapperElement) {
            wrapperElement = document.createElement("div");

            // insert the newly added wrapper right after the start comment
            const referenceElement = elementsInsideCommentTags[0];
            referenceElement.parentNode.insertBefore(wrapperElement, referenceElement.nextSibling);

            // important to append the elements after the item is attached to the dom
            // otherwise if there are <img> tags inside them, they will be attempted to be loaded
            // and then cancelled, which stalls the request
            // first and last element are the comments, so we skip them
            for (let i = 1; i < elementsInsideCommentTags.length - 1; i++) {
                wrapperElement.appendChild(elementsInsideCommentTags[i]);
            }
        }

        return wrapperElement;
    }

    private addWidgetMeta(wrapper: HTMLElement, commentValue: string): void {
        if (!wrapper.setAttribute) {
            throw `Invalid widget content: ${commentValue}`;
        } else {
            const regex = /\({(.*)}\)/g;
            const attributes = commentValue.match(regex);
            if (!attributes || attributes.length < 1 ) {
                throw `The provided widget metadata was not correct: ${commentValue}`;
            } else {
                const metaString = attributes[0].slice(1, attributes[0].length - 1);
                let meta: any;
                try {
                    meta = JSON.parse(metaString) as WidgetPlaceholderMeta;
                } catch (e) {
                    throw `The provided widget metadata was not correct: ${commentValue}. Actual error: ${e}`;
                }

                if (meta) {
                    Object.keys(meta).forEach((key) => {
                        const attrName = `${ATTR_PREFIX}${key}`;
                        const attrValue = meta[key];
                        if (attrValue !== null) {
                            wrapper.setAttribute(attrName, meta[key].toString());
                        }
                    });

                    this.addEmptyContentAttr(wrapper);
                } else {
                    throw `The provided widget metadata was not correct: ${commentValue}`;
                }
            }
        }
    }

    private addEmptyContentAttr(wrapper: HTMLElement) {
        if (wrapper.getAttribute(ATTR_IS_CONTENT) === "true") {
            let hasEmptyContent = false;
            if (!wrapper.getAttribute(ATTR_ERROR)) {
                hasEmptyContent = !wrapper.innerText.trim() && !this.checkForElementsWithoutText(wrapper);
            }

            wrapper.setAttribute(ATTR_IS_EMPTY, hasEmptyContent.toString());
        }
    }

    private findExistingWrapperElement(elements: Node[]): HTMLElement {
        const allElementNodes = [];
        for (let i = 1; i < elements.length - 1; i++) {
            const currentElement = elements[i];
            if (currentElement.nodeType === NODE_TYPE_ELEMENT && !NODE_NAMES_EXCLUDED.some(x => x === currentElement.nodeName)) {
                allElementNodes.push(currentElement);
            } else if (currentElement.nodeType === NODE_TYPE_TEXT) {
                const containsNonEmptyTextNodes = !!currentElement.nodeValue.trim();
                if (containsNonEmptyTextNodes) {
                    return null;
                }
            }
        }

        if (allElementNodes.length === 1) {
            return allElementNodes[0];
        }

        return null;
    }

    private checkForElementsWithoutText(rootElement: Element): boolean {
        if (NODE_NAMES_EXCLUDED.find(x => x === rootElement.nodeName))
            return true;

        for (let i = 0; i < rootElement.children.length; i++) {
            const childResult = this.checkForElementsWithoutText(rootElement.children[i]);
            if (childResult)
                return true;
        }

        return false;
    }
}

interface WidgetPlaceholderMeta {
    id: string;
    name: string;
    title: string;
    isContentWidget: boolean;
    isEmpty: boolean;
    isOrphaned: boolean;
    error: string;
    warning: string;
    container: string;
    placeholderLabel: string;
    hasOrphans: string;
}
