import { Injectable, ClassProvider } from "@angular/core";
import { DELETE_COMMAND_EXTENDER_TOKEN } from "../../content/dynamic-modules/services/operations/commands/composite-delete-command-extender";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "./media.helpers";
import { DeleteCommandExtenderBase } from "../../content/dynamic-modules/services/operations/commands/delete-command-extender-base";
import { stringConstants } from "../../../common-constants";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";

@Injectable()
export class MediaDeleteCommandExtender extends DeleteCommandExtenderBase {
    constructor(dynamicItemStore: DynamicItemStore) {
        super(dynamicItemStore);
    }
    
    isSupportedType(entityData: EntityData): boolean {
        return MediaHelpers.isLibraryOrMedia(entityData.metadata.setName);
    }

    showMultilingualButtons(data): boolean {
        const showMultilingual = super.showMultilingualButtons(data);
        return showMultilingual && data.selectedItems.every(item => MediaHelpers.isMediaEntity(item));
    }

    permanentDelete(data: any): boolean {
        const permanentDelete = super.permanentDelete(data);
        return permanentDelete || data.selectedItems.some(item => !MediaHelpers.isMediaEntity(item));
    }

    getTitle(data: any): string {
        const hasLibrary = data.selectedItems.some(item => !MediaHelpers.isMediaEntity(item));
        const hasMediaContent = data.selectedItems.some(item => MediaHelpers.isMediaEntity(item));
        const itemsLabel = MediaHelpers.resolveMediaSetName(data.entityData.metadata.setName);

        if (hasMediaContent && hasLibrary) {
            return data.bulk ? `Delete selected libraries and ${itemsLabel} permanently?` : super.getTitle(data);
        }

        if (hasMediaContent && !hasLibrary) {
            let deletePermanentlyText = stringConstants.EMPTY_STRING;
            if (this.permanentDelete(data)) {
                deletePermanentlyText = " permanently";
            }

            return data.bulk ? `Delete selected ${itemsLabel}${deletePermanentlyText}?` : super.getTitle(data);
        }

        if (!hasMediaContent && hasLibrary) {
            return data.bulk ? "Delete selected libraries permanently?" : super.getTitle(data);
        }

        return super.getTitle(data);
    }

    getDisplayName(data: any): string {
        const hasLibrary = data.selectedItems.some(item => !MediaHelpers.isMediaEntity(item));
        const hasMediaContent = data.selectedItems.some(item => MediaHelpers.isMediaEntity(item));
        const itemsLabel = MediaHelpers.resolveMediaSetName(data.entityData.metadata.setName);

        if (hasMediaContent && hasLibrary) {
            return data.bulk ? `libraries and ${itemsLabel}` : super.getDisplayName(data);
        }

        if (hasMediaContent && !hasLibrary) {
            return data.bulk ? itemsLabel : super.getDisplayName(data);
        }

        if (!hasMediaContent && hasLibrary) {
            return data.bulk ? "libraries" : super.getDisplayName(data);
        }

        return super.getDisplayName(data);
    }
}

export const MEDIA_DELETE_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: DELETE_COMMAND_EXTENDER_TOKEN,
    useClass: MediaDeleteCommandExtender
};
