import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "../../content/dynamic-modules/services/operations/operations-filter";
import { OperationsData, OperationsTarget } from "../../content/dynamic-modules/services/operations/interfaces";
import { OPERATION_NAMES, Operation, OPERATION_TITLES, OPERATION_CATEGORIES } from "../../shared/components/action-menu/operation.model";
import { Injectable, ClassProvider } from "@angular/core";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { SaveAsHomePageCommand } from "../commands/saveAsHomePage.command";
import { PAGE_TYPE_OPTIONS } from "../components/navigation-options-composite-component/navigation-options.composite.component";
import { OUTSIDE_MENU_MAX_ORDINAL } from "../../content/dynamic-modules/components/action-buttons.resolver";
import { NavigateToMenuSectionCommand } from "../commands/navigate-to-menu-section.command";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { VIEW_NAME } from "../../content/constants";

@Injectable()
export class PagesOperationsFilter implements OperationsFilter {
    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (data.dataItem.metadata.setName === ENTITY_SET.TEMPLATES) {
            return this.handleTemplates(operations, data);
        }

        if (data.dataItem.metadata.setName === ENTITY_SET.PAGES) {

            if (!data.contextData.isEditingPageContent) {
                operations = this.filterPersonalizationOperations(operations);
            }

            if (data.target === OperationsTarget.Create && data.contextData.viewName !== VIEW_NAME.DUPLICATE) {
                const createOperation = operations.find(x => x.Name === OPERATION_NAMES.create);
                if (createOperation) {
                    createOperation.Title = OPERATION_TITLES.continue;
                }
            }

            if (data.target === OperationsTarget.Edit || data.target === OperationsTarget.Create) {
                if (data.contextData.isEditingPageContent) {
                    this.handleEditOperations(operations);
                    this.handleStopSyncing(operations);
                }

                return operations.filter(x =>
                    x.Name !== OPERATION_NAMES.template &&
                    x.Name !== OPERATION_NAMES.sharePreviewLink &&
                    x.Name !== OPERATION_NAMES.createChild &&

                    // TODO: remove after fixing duplicate in edit
                    x.Name !== OPERATION_NAMES.duplicate);
            }

            if (data.dataItem.data) {
                const pageType = data.dataItem.data.PageType;
                if (data.target === OperationsTarget.List && (pageType === PAGE_TYPE_OPTIONS.GROUP || pageType === PAGE_TYPE_OPTIONS.REDIRECT)) {
                    operations = operations.filter(x => x.Name !== OPERATION_NAMES.editContent);
                }
            }

            if (data.target === OperationsTarget.List && !data.contextData.isHierarchicalView) {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.reorder);
            }

            if (data.target === OperationsTarget.List) {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.mobilePreview && x.Name !== OPERATION_NAMES.stopSyncingWarning);
                if (data.dataItem.isEmpty) {
                    const manageReferentTypeOperation = operations.find(x => x.Name === OPERATION_NAMES.manageReferentType);
                    if (manageReferentTypeOperation) {
                        manageReferentTypeOperation.token = {
                            type: NavigateToMenuSectionCommand,
                            properties: {
                                route: [ROUTE_PATHS.TEMPLATES]
                            }
                        };
                    }

                    this.managePresetsOperation(operations);
                }
            }

            if (data.target === OperationsTarget.List) {
                return operations.map(x => this.mapOperation(x));
            }
        }

        return operations;
    }

    private handleTemplates(operations: Operation[], data: OperationsData) {
        if (!data.contextData.isEditingPageContent) {
            operations = this.filterPersonalizationOperations(operations);
        }

        if (data.target === OperationsTarget.Edit || data.target === OperationsTarget.Create) {
            if (data.contextData.isEditingPageContent) {
                this.handleEditOperations(operations);
            }

            if (data.target === OperationsTarget.Create && data.contextData.viewName !== VIEW_NAME.DUPLICATE) {
                const createOperation = operations.find(x => x.Name === OPERATION_NAMES.create);
                if (createOperation) {
                    createOperation.Title = OPERATION_TITLES.continue;
                }
            }

            return operations.filter(x =>
                // TODO: remove after fixing duplicate in edit
                x.Name !== OPERATION_NAMES.duplicate);
        } else if (data.target === OperationsTarget.List && data.dataItem.isEmpty) {
            const manageReferentTypeOperation = operations.find(x => x.Name === OPERATION_NAMES.manageReferentType);
            if (manageReferentTypeOperation) {
                manageReferentTypeOperation.token = {
                    type: NavigateToMenuSectionCommand,
                    properties: {
                        route: [ROUTE_PATHS.PAGES]
                    }
                };
            }

            this.managePresetsOperation(operations);
        }

        return operations;
    }

    private managePresetsOperation(operations: Operation[]) {
        const managePresetsOperation = operations.find(x => x.Name === OPERATION_NAMES.managePresets);
        if (managePresetsOperation) {
            managePresetsOperation.token = {
                type: NavigateToMenuSectionCommand,
                properties: {
                    route: [ROUTE_PATHS.PRESETS]
                }
            };
        }
    }

    private filterPersonalizationOperations(operations: Operation[]): Operation[] {
        return  operations.filter(x =>
            x.Category.Name !== OPERATION_CATEGORIES.personalization &&
            x.Category.Name !== OPERATION_CATEGORIES.personalized &&
            x.Category.Name !== OPERATION_CATEGORIES.personalizedWidgets
        );
    }

    private handleEditOperations(operations: Operation[]) {
        const editOperationIndex = operations.findIndex(o => o.Name === OPERATION_NAMES.edit);
        if (editOperationIndex > -1) {
            const editOperation = operations.splice(editOperationIndex, 1)[0];
            editOperation.Title = OPERATION_TITLES.titleAndProperties;
            editOperation.Ordinal = OUTSIDE_MENU_MAX_ORDINAL + 1;
            operations.splice(0, 0, editOperation);
        }
    }

    private mapOperation(operation: Operation): Operation {
        if (operation.Name === "SetAsHomepage") {
            operation.token = {
                type: SaveAsHomePageCommand
            };
        }

        return operation;
    }

    private handleStopSyncing(operations: Operation[]) {
        const operation = operations.find(x => x.Name === OPERATION_NAMES.stopSyncing);
        if (operation) {
            operation.Category.HideSeparator = true;
        }
    }
}

export const PAGES_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: PagesOperationsFilter
};
