import { Component, Input, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { map } from "rxjs/operators";
import { HierarchicalPagesService } from "../../services/hierarchical-pages.service";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";
import { TypeNames, Item } from "../../../../../../fields/types/types";
import { ServiceContract, ServiceInfo, SelectorConfig } from "../../../../../../fields/selector/selector.component";
import { DEFAULT_CHILDREN_LOAD } from "../../../content/constants";
import { TreeConfig } from "../../../../../../fields";
import { cloneObject } from "../../../../utils";
import { stringConstants } from "../../../../common-constants";
import { ClosingContext, CanCloseModal } from "../../../shared/services/modal-window.service";
import { WebAddressComponent, INVALID_URL } from "../web-address-component/web-address.component";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { Observable } from "rxjs";

const WEB_ADDRESS_TAB_NAME = "webaddress";
export const WEB_ADDRESS_TAB_TITLE = "Web address";
const SELECT_REDIRECTING_PAGE_STRING = "Select page to redirect to";
const REDIRECTING_PAGE_TAB_TITLE = "Pages from this site";

@Component({
    selector: "sf-page-selector",
    templateUrl: "./page-selector.component.html"
})
export class PageSelectorComponent implements OnInit, CanCloseModal {
    @Input() culture: string;
    @Input() selected: Item[] = [];
    @Input() formattedTypeName: string;
    @Input() selectedUrl: string = stringConstants.EMPTY_STRING;
    @Input() shouldOpenInNewWindow: boolean = false;
    @Input() overrideSelectorConfig: boolean = false;

    public selectorConfig: SelectorConfig = null;
    public entityData: EntityData;
    public selectedTab: string = stringConstants.EMPTY_STRING;
    public shouldSelectHomePage: boolean = false;
    public expandPathPair: { key: string, value: string } = { key: "Breadcrumb", value: "Title" };
    public parentId: string = stringConstants.DEFAULT_GUID;
    public items: any[] = [];
    public totalCount: number;
    public serviceAware: ServiceContract;
    public defaultFieldName: string;
    public names: TypeNames;
    public treeConfig: TreeConfig;
    public isLoading: boolean;
    private itemId: string = stringConstants.DEFAULT_GUID;

    constructor(private route: ActivatedRoute,
                private hierarchicalPagesService: HierarchicalPagesService) {
    }

    ngOnInit() {
        this.initialize();
    }

    get initialTab() {
        if (this.selectedUrl && this.selectedUrl !== INVALID_URL) {
            return WEB_ADDRESS_TAB_NAME;
        }

        return null;
    }

    webAddressChange(event: any) {
        if (event.key === "selectedUrl") {
            this.selectedUrl = event.value;
        } else if (event.key === "shouldOpenInNewWindow") {
            this.shouldOpenInNewWindow = event.value;
        }
    }

    tabChange(event: any) {
        this.selectedTab = event;
    }

    canCloseCallback(context: ClosingContext): boolean {
        if (!context.data || !context.data.data) {
            return true;
        } else if (this.selectedTab === WEB_ADDRESS_TAB_TITLE && this.selectedUrl === INVALID_URL) {
            return false;
        }

        return true;
    }

    private initialize() {
        this.treeConfig = {
            multiSelection: false,
            isHierarchical: true,
            status: true
        };

        this.entityData = this.getEntityData(ENTITY_SET.PAGES);
        this.defaultFieldName = this.entityData.metadata.defaultFieldName;
        this.getItems();

        this.names = {
            plural: this.entityData.metadata.displayName.toLowerCase(),
            singular: this.entityData.metadata.singularName.toLowerCase()
        };

        this.serviceAware = new ServiceContract(
            (info: ServiceInfo) => this.loadMore(info),
            (info: ServiceInfo) => this.expandChildren(info));

        if (this.selectedUrl && this.selectedUrl !== INVALID_URL) {
            this.selectedTab = WEB_ADDRESS_TAB_TITLE;
        }

        if (this.overrideSelectorConfig) {
            this.selectorConfig = {
                selectionText: SELECT_REDIRECTING_PAGE_STRING,
                formattedTypeName: stringConstants.EMPTY_STRING,
                mainTabConfig: {
                    title: REDIRECTING_PAGE_TAB_TITLE
                },
                customTabConfig: {
                    name: WEB_ADDRESS_TAB_NAME,
                    title: WEB_ADDRESS_TAB_TITLE,
                    componentData: {
                        type: WebAddressComponent,
                        properties: {
                            selectedUrl: this.selectedUrl,
                            shouldOpenInNewWindow: this.shouldOpenInNewWindow
                        },
                        afterComponentInit: (component: WebAddressComponent) => {
                            component.fieldChange.subscribe((data) => {
                                this.webAddressChange(data);
                            });
                        }
                    }
                }
            };
        }
    }

    private getItems(): void {
        this.isLoading = true;

        this.hierarchicalPagesService.getModalItems(this.entityData, this.itemId)
            .subscribe(result => {
                this.totalCount = result.totalCount;
                this.items = result.dataItems
                    .map(dataItem => {
                        const item = this.addFieldsToDataItem(dataItem);
                        return item;
                    });

                this.isLoading = false;
            });
    }

    private getEntityData(setName: string): EntityData {
        const entity = this.route.parent.snapshot.data.metaStore.entities[setName];
        const entityData: EntityData = {
            culture: this.culture,
            provider: undefined,
            metadata: entity
        };

        return entityData;
    }

    private expandChildren(info: ServiceInfo): Observable<any> {
        if (info.take === undefined) {
            info.take = DEFAULT_CHILDREN_LOAD;
        }
        info.excludeLevel = 1;
        return this.hierarchicalPagesService.expandChildren(info, this.entityData, this.itemId).pipe(
            map(data => {
                return { dataItems: data.dataItems.map(item => this.addFieldsToDataItem(item)), totalCount: data.totalCount };
            }));
    }

    private loadMore(info: ServiceInfo): Observable<any> {
        info.excludeLevel = 1;
        info.parentId = this.itemId;
        return this.hierarchicalPagesService.loadMore(info, this.entityData, undefined).pipe(
            map(data => {
                return { dataItems: data.dataItems.map(item => this.addFieldsToDataItem(item)), totalCount: data.totalCount };
            }));
    }

    private addFieldsToDataItem(dataItem: DataItem): any {
        const item = cloneObject(dataItem.data);
        item.hasChildren = item.HasChildren;
        item.isTranslated = dataItem.isTranslated;

        if (this.shouldSelectHomePage && item.IsHomePage) {
            this.selected = [item];
        }
        if (this.parentId === item.Id) {
            item.isSelectionDisabled = true;
        }

        return item;
    }
}
