import { Component, Input, Output, EventEmitter, OnInit, OnChanges } from "@angular/core";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

const wrapperClass: string = "sf-split-button";

@Component({
    selector: "sf-split-button",
    templateUrl: "./split-button.component.html"
})

export class SplitButtonComponent implements OnInit, OnChanges {
    @Input() data: Array<ChoiceItem>;
    @Input() title: string;
    @Input() look: string;
    @Output() dropdownClicked = new EventEmitter<string>();
    @Output() selectionChanged = new EventEmitter<string>();

    public wrapperClassName: string;

    ngOnInit() {
        this.generateCssClasses();
    }

    ngOnChanges(changes: any) {
        this.generateCssClasses();
    }

    handleOnDropdownClick(event: any) {
        this.dropdownClicked.emit(event);
    }

    handleItemSelect(item: ChoiceItem) {
        this.title = item.Name;
        this.selectionChanged.emit(item.Value);
    }

    private generateCssClasses() {
        this.wrapperClassName = this.generateWrapperCssClassList();
    }

    private generateWrapperCssClassList() {
        let cls = wrapperClass;

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        return cls;
    }
}
