import { debounceTime } from "rxjs/operators";
import { Subject, Observable } from "rxjs";
import { Injectable } from "@angular/core";
import { FieldSectionModel } from "../../src/app/services/fieldSection.model";

@Injectable()
export class ContentSectionMenuService {
    requestBringIntoView$: Observable<any>;
    fieldViewPortChanges$: Observable<FieldViewPortChanges>;
    requestFieldSectionPositionCalculation$: Observable<any>;

    private requestBringIntoViewSource: Subject<any>;
    private fieldViewPortChangesSource: Subject<FieldViewPortChanges>;
    private requestFieldSectionPositionCalculationSource: Subject<void>;

    constructor() {
        this.requestBringIntoViewSource = new Subject<any>();
        this.fieldViewPortChangesSource = new Subject<FieldViewPortChanges>();
        this.requestFieldSectionPositionCalculationSource = new Subject<void>();
        this.requestBringIntoView$ = this.requestBringIntoViewSource.asObservable();
        this.fieldViewPortChanges$ = this.fieldViewPortChangesSource.asObservable();
        this.requestFieldSectionPositionCalculation$ = this.requestFieldSectionPositionCalculationSource.asObservable().pipe(debounceTime(80));
    }

    requestBringIntoView(model: FieldSectionModel) {
        this.requestBringIntoViewSource.next(model);
    }

    fieldViewPortChanges(args: FieldViewPortChanges) {
        this.fieldViewPortChangesSource.next(args);
    }

    requestFieldSectionPositionCalculation() {
        this.requestFieldSectionPositionCalculationSource.next();
    }
}
export interface FieldViewPortChanges {
    isInViewPort: boolean;
    model: FieldSectionModel;
}
