import { BackgroundTask, BackgroundTaskType } from "../../services/background-task.types";

export class SearchBackgroundTaskDataParser {
    static parse(task: BackgroundTask): ReindexTaskDataParsed {

        let data: ReindexTaskDataParsed = { };

        if (task.TaskName === BackgroundTaskType.Reindex) {
            const taskData = JSON.parse(task.TaskData);

            data = {
                indexId: taskData.PublishingPointId,
                siteIds: taskData.SiteIds
            };
        }

        return data;
    }
}

export interface ReindexTaskDataParsed {
    indexId?: string;
    siteIds?: [string]
}
