import { AbstractControl, ValidatorFn, Validators } from "@angular/forms";
import { CUSTOM_ERROR_PREFIX, VALIDATOR_MESSAGES } from "./validators.constants";

export const URL_PATTERN_VALIDATOR_NAME = "urlPattern";
export class MultipleUrlsPatternValidator {
    static validate(regexPattern: any): ValidatorFn {
        return (control: AbstractControl) => {
            const errorsCollection = [];
            let hasErrors = false;

            if (!control.value) {
                return null;
            }

            const arrayValue = <Array<string>>control.value;
            arrayValue.forEach(url => {
                const dummyControl: any = { value: url };
                const result = Validators.pattern(regexPattern)(dummyControl);

                if (result) {
                    errorsCollection[url] = "pattern";
                    hasErrors = true;
                }
            });

            if (hasErrors) {
                return { [CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.CUSTOM_ERRORS]: errorsCollection };
            } else {
                return null;
            }
        };
    }
}
