import { createAction, props } from "@ngrx/store";
import { DataItem } from "../../../modules/content/dynamic-modules/interfaces";
import { UploadFieldState, UploadInfo } from "../../../modules/libraries/services/media.service";
import { cloneObject } from "../../../utils";

const MediaSetFolders = createAction(
    "[Media] Set folders",
    props<{ folders: DataItem[], totalFolders: number }>()
);

const MediaSetFiles = createAction(
    "[Media] Set files",
    props<{ files: DataItem[], totalFiles: number }>()
);

const MediaSetUploads = createAction(
    "[Media] Set uploads",
    props<{ items: any[], updatedItem?: any, uploadFieldState: UploadFieldState }>()
);

export const MEDIA_ACTIONS = {
    setFolders: MediaSetFolders,
    setFiles: MediaSetFiles,
    setUploads: MediaSetUploads
};

export const MEDIA_DISPATCH_ACTIONS = {
    setUploads: (uploadInfo: UploadInfo) => {
        const uploadInfoClone = cloneObject(uploadInfo);
        const newItems = uploadInfo.items.map(item => {
            const newItem = cloneObject(item);
            newItem.upload = Object.assign({}, item.upload);

            return newItem;
        });

        uploadInfoClone.items = newItems;

        if (uploadInfo.updatedItem) {
            const newUpdatedItem = cloneObject(uploadInfo.updatedItem);
            newUpdatedItem.content = uploadInfo.updatedItem.content;
            uploadInfoClone.updatedItem = newUpdatedItem;
        }

        return MEDIA_ACTIONS.setUploads(uploadInfoClone);
    }
};
