import { Inject } from "@angular/core";
import { Observable, ReplaySubject } from "rxjs";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { BulkOperationResult } from "../../content/dynamic-modules/services/operations/commands/bulk-command";
import { Command } from "../../shared/commands/command";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { NOTIFICATION_LOOKS } from "../../shared/services/notification/notification-data";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";

export class LockLayoutCommand implements Command {
    private entityData: DataItem;

    constructor(private dynamicItemService: DynamicItemService, @Inject(NOTIFICATION_SERVICE) private readonly notificationService: NotificationService) { }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        this.entityData = context.data.entityData;

        const result = new ReplaySubject<BulkOperationResult>(1);

        this.dynamicItemService.executeEntityOperationForDataItemKey(this.entityData.data.Id, this.entityData, `Default.LockLayout(lockLayout=${context.data.lock})`, {
        }).subscribe((res) => {
            if (!res.Success) {
                result.next({ success: res.Success });

                this.notificationService.publishBasicNotification({
                    message: res.Message,
                    look: NOTIFICATION_LOOKS.ERROR
                });
            } else {
                result.next({ success: res.Success });

                this.notificationService.publishBasicNotification({
                    message: res.Message,
                    look: NOTIFICATION_LOOKS.SUCCESS
                });
            }
        });

        return result.asObservable();
    }
}
