import { combineLatest as observableCombineLatest, from as observableFrom,  Observable ,  ReplaySubject } from "rxjs";

import { skip } from "rxjs/operators";
import { Component, Input, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { DataItem } from "../../../interfaces";
import { ChoiceDropdownComponent } from "../../../../../../../../fields/choice/choice-dropdown.component";
import { FieldModel } from "../../../../../../services/field.model";
import { FieldTypes } from "../../../../../shared/fields-builder/services/fields-registry";
import { CHOICE_DROPDOWN_REGISTRY } from "../../../../../../../../fields/choice/index";
import { FieldsGeneratorService } from "../../../../../shared/services/fields-generator.service";
import { BackendTweaksStore } from "../../../services/backend-tweaks/backend-tweaks.store";
import { DynamicItemService } from "../../../services/dynamic-item.service";
import { FieldSectionModel } from "../../../../../../services/fieldSection.model";
import { LANGUAGE_DROPDOWN_NAME, DROPDOWN_LOOK } from "../list-item-filter-sidebar.component";
import { ContentCultureData } from "../../../../../shared/services/metadata/site-data.store";
import { LoadingState } from "../../../../../shared/rxjs-extensions/delayEmission";
import { VIEW_NAME } from "../../../../constants";
import { CompositeFieldSettings } from "../../../../../shared/services/composite-field.settings";
import { RelatedDataSettings } from "../../../../../../../../fields/related-data/related-data.settings";
import { ANY_SITE_SOURCE_PROVIDER, stringConstants } from "../../../../../../common-constants";
import { FilePreviewEditSettings } from "../../../../../libraries/file-preview-edit/file-preview-edit-settings";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const COMPARE_LANGUAGES_DOPDOWN_TITLE = "Translate from";

@Component({
    templateUrl: "./compare-translations.component.html"
})
export class CompareTranslationsComponent extends SfRxBase implements OnInit {
    @Input() itemChanged$: Observable<DataItem>;
    @Input() dataItem: DataItem;

    model$ = new ReplaySubject<LoadingModel>();

    protected fieldModel: FieldModel;
    protected currentLanguage: string;

    constructor(private route: ActivatedRoute,
                private fieldsGeneratorService: FieldsGeneratorService,
                private backendTweaksStore: BackendTweaksStore,
                private dynamicItemService: DynamicItemService) {
                    super();
    }

    /**
     * Initializes the component. Sets the initial language
     * in the select language dropdown and loads the item in
     * readonly mode.
     *
     * @memberof CompareTranslationsComponent
     */
    ngOnInit(): void {
        const data = this.route.parent.snapshot.data;
        const sitedataStore = data.siteDataStore;
        const cultures: ContentCultureData[] = sitedataStore.ContentCultures;
        const currentCulture = this.dataItem.culture;

        this.currentLanguage = this.determineInitialLanguage(sitedataStore.DefaultContentCulture, currentCulture, this.dataItem);
        this.fieldModel = this.initLanguagesDropdown(cultures, this.currentLanguage, this.dataItem);
        this.loadItem(this.currentLanguage);

        const reloadItemSubscription = this.itemChanged$.pipe(skip(1)).subscribe(() => {
            this.loadItem(this.currentLanguage);
        });

        this.registerSubscription(reloadItemSubscription);
    }

    /**
     * Loads the item for the newly selected culture.
     *
     * @param {string} value
     * @memberof CompareTranslationsComponent
     */
    onLanguageSelectionChange(value: string) {
        this.loadItem(value);
    }

    /**
     * Fetches the item for the given culture and
     * displays it in readonly mode.
     *
     * @param {string} culture The culture for which the item will be retrieved.
     * @returns {void}
     * @memberof CompareTranslationsComponent
     */
    loadItem(culture: string): void {
        if (!culture) {
            return;
        }

        this.model$.next({
            isLoading: true
        });

        this.handleLoadingItem(culture);
    }

    /**
     * Determines the initial language for the languages dropdown, based
     * on the language in which the original item is displayed and on the
     * site culture.
     *
     * @private
     * @param {string} defaultCulture Site's default culture.
     * @param {string} currentCulture Item's current culture.
     * @param {DataItem} dataItem The data item.
     * @returns {string} The culture which will be set to the languages dropdown.
     * @memberof CompareTranslationsComponent
     */
    private determineInitialLanguage(defaultCulture: string, currentCulture: string, dataItem: DataItem): string {
        const availableLanguages = dataItem.data.AvailableLanguages;
        const isCreatedOnDefaultCulture = availableLanguages.some(cul => cul === defaultCulture);

        // should use the first available language when the current language is the default one and there are other available languages
        if (currentCulture === defaultCulture && availableLanguages.length > 1) {
            return availableLanguages.find(cul => { return cul !== defaultCulture; });
        }

        // should use the default language when the item is created in it
        if (isCreatedOnDefaultCulture) {
            return defaultCulture;
        }

        // should use the first available language different than the current one when there is no default language created
        if (availableLanguages.length > 1) {
            return availableLanguages.find(cul => { return cul !== currentCulture; });
        }

        // should use the only available language when the default is not available and there is only one available language
        return availableLanguages[0];
    }

    /**
     * For the loaded item, generates fields and stops
     * the loading.
     *
     * @private
     * @param {Observable<DataItem>} getItem$ Load item observable.
     * @param {string} culture
     * @memberof CompareTranslationsComponent
     */
    private handleLoadingItem(culture: string) {
        const getItem$ = this.getItem$(culture);
        const initForm$ = observableFrom(this.backendTweaksStore.initializeForm(this.dataItem.metadata.setName, VIEW_NAME.EDIT, this.dataItem.key, this.dataItem.provider, this.dataItem.culture));

        observableCombineLatest(getItem$, initForm$).subscribe(data => {
            const dataItem = data[0];
            const fieldSections = this.fieldsGeneratorService
                .generateFields(dataItem.metadata, this.backendTweaksStore, dataItem.data, true)
                .map(section => this.configureSection(section, dataItem));

            this.model$.next({
                isLoading: false,
                fieldSections
            });
        });
    }

    private configureSection(section: FieldSectionModel, dataItem: DataItem) {
        section.fields.forEach((field) => {
            const isCompositeField = field.settings instanceof CompositeFieldSettings;
            const filePreviewEditSettings = field.settings instanceof FilePreviewEditSettings;

            field.settings.showForAllTranslationsLabel = !isCompositeField && !filePreviewEditSettings;
            field.settings.culture = dataItem.culture;
            field.settings.entityData = dataItem;
            field.settings.dataItem = dataItem;

            if (field.selector === FieldTypes.relatedData) {
                const settings = field.settings as RelatedDataSettings;
                const hasAnySiteSourceProvider = settings.provider === ANY_SITE_SOURCE_PROVIDER;
                if (hasAnySiteSourceProvider) {
                    // any site provider is a 'special' type of provider meant for usage in related data fields
                    // in that case the field should show a provider selector when relating items and use the default provider initially
                    // setting the provider to empty string in the field settings instructs it to use the default provider for the items that will be related
                    settings.provider = stringConstants.EMPTY_STRING;
                }
            }
        });

        section.settings.isExpanded = true;
        section.settings.hideTitle = true;
        return section;
    }

    private getItem$(culture: string) {
        return this.dynamicItemService
                   .getItem({
                       entityData: {
                           culture,
                           metadata: this.dataItem.metadata,
                           provider: this.dataItem.provider
                       },
                       itemKey: this.dataItem.key,
                       fallbackProperties: this.route.snapshot.data.itemData.fallbackProperties
                   });
    }

    private initLanguagesDropdown(cultures: ContentCultureData[], initialCulture: string, dataItem: DataItem): FieldModel {
        // TODO: revise fields
        const dropdownOptions = dataItem.data.AvailableLanguages.map(itemCulture => {
            const culture = cultures.find(x => x.Name === itemCulture);
            return {
                Name: culture.DisplayName,
                Value: culture.Name
            };
        });
        const dropdownSettings = ChoiceDropdownComponent.createFieldSettings(dropdownOptions, null, LANGUAGE_DROPDOWN_NAME, DROPDOWN_LOOK);
        const dropdownModel = new FieldModel({
            key: LANGUAGE_DROPDOWN_NAME,
            settings: dropdownSettings,
            selector: FieldTypes.choiceDropDown,
            registration: CHOICE_DROPDOWN_REGISTRY
        });

        const name = cultures.find(x => x.Name === initialCulture).Name;
        dropdownModel.settings.title = COMPARE_LANGUAGES_DOPDOWN_TITLE;
        dropdownModel.settings.defaultValue = name;
        dropdownModel.settings.translatable = false;

        return dropdownModel;
    }
}

interface LoadingModel extends LoadingState {
    isLoading: boolean;
    fieldSections?: FieldSectionModel[];
}
