import { Observable, of } from "rxjs";
import { Injectable } from "@angular/core";
import { Command } from "../shared/commands/command";
import { ExecutionContext } from "../shared/commands/execution-context";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DialogData, FieldModel, FieldRegistration, FieldTypes } from "../../api";
import { ModalWindowService } from "../shared/services/modal-window.service";
import { EditableFieldsComponent } from "../shared/fields-builder/components/editable-fields/editable-fields.component";
import { FieldSectionModel } from "../../services/fieldSection.model";
import { ShortTextSettings } from "../../../../fields/short-text/short-text-settings";
import { SHORT_TEXT_REGISTRY } from "../../../../fields";
import { Properties } from "../shared/fields.constants";
import { RelativeDatePipe } from "../shared/pipes/relative-date.pipe";
import { DateService } from "../shared/services/date.service";
import { Router } from "@angular/router";
import { BackendTweaksStore } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { ShortTextComponent } from "../../../../fields/short-text/short-text.component";
import { ShortTextGridComponent } from "../../../../fields/short-text/short-text.grid.component";
import { ReadHtmlComponent } from "../shared/fields-builder/components/read/read-html.component";

const PREVIEW_RESPONSE_MAPPING = "previewResponse";
const HIDDEN_COLUMNS: string[] = [
    "Language",
    "SourceSiteName",
    "ReferralCode"
];

const FIELD_CSS_CLASS: string = "-sf-txt-align-left -sf-mb-m";

const CIRCLE_DIVIDER = '<span class="sf-icon sf-fa sf-fa-circle -sf-pl-3xs -sf-pr-3xs -black -size-7xs -sf-txt-vertical-align-middle"><!----></span>';

const SHORT_TEXT_HTML_REGISTRY: FieldRegistration = {
    writeComponent: ShortTextComponent,
    gridComponent: ShortTextGridComponent,
    settingsType: ShortTextSettings,
    // We use this ReadHtmlComponent in order to show the CIRCLE_DIVIDER HTML in the header of the preview
    // Otherwise the ReadComponent is used, which by default escapes HTML characters
    readComponent: ReadHtmlComponent
};

@Injectable()
export class FormResponsePreviewCommand implements Command {
    protected datePipe = new RelativeDatePipe(new DateService());
    constructor(private modalWindowService: ModalWindowService, private router: Router, private backendTweaksStore: BackendTweaksStore) { }

    execute(context: ExecutionContext): Observable<any> {
        const fields: FieldModel[] = [];
        const fieldSection = new FieldSectionModel({
            isExpanded: true,
            isMain: true,
            insertHorizontalRule: true
        })

        const gridData = this.backendTweaksStore.getGridByType(context.data.setName);
        for (const prop in context.data.dataItem) {
            let fieldCssClass = FIELD_CSS_CLASS;
            const currentColumn = gridData.find(c => c.name === prop);
            if (!currentColumn || HIDDEN_COLUMNS.includes(prop))
                continue;

            let value = context.data.dataItem[prop];
            const settingsKey = currentColumn.name;
            const shortTextSettings = new ShortTextSettings(settingsKey, true);
            shortTextSettings.title = currentColumn.title;
            const emptyText = prop.includes("FileField") ? "no file" : "not answered";
            shortTextSettings.emptyValueText = emptyText;
            const field = new FieldModel({
                key: settingsKey,
                selector: FieldTypes.shortText,
                settings: shortTextSettings,
                registration: SHORT_TEXT_REGISTRY,
                value: value,
                cssClass: fieldCssClass
            });

            if (currentColumn.name === Properties.SUBMITTED_ON) {
                const fullDate = new Date(value);
                const date = this.datePipe.transform(fullDate, RelativeDatePipe.MONTH_DATE_AND_YEAR);
                const hour = this.datePipe.transform(fullDate, RelativeDatePipe.TIME);
                value = context.data.dataItem["Username"]
                    ? `${date} ${CIRCLE_DIVIDER} ${hour} ${CIRCLE_DIVIDER} by ${context.data.dataItem["Username"]} ${CIRCLE_DIVIDER} ${context.data.dataItem["IpAddress"]} `
                    : `${date} ${CIRCLE_DIVIDER} ${hour} ${CIRCLE_DIVIDER} ${context.data.dataItem["IpAddress"]} `;
                fieldCssClass += " -sf-bg-primary-variant -sf-border -sf-border-lightest -sf-border-radius-5 -sf-pl-xs -sf-pr-xs -sf-pt-m -sf-pb-m -sf-ml--xs -sf-mr--xs -sf-mt-5xl";
                field.value = value;
                field.cssClass = fieldCssClass;
                field.registration = SHORT_TEXT_HTML_REGISTRY;
            }

            fields.push(field)
            fieldSection.fields = fields;
        }

        const componentData: ComponentData = {
            type: EditableFieldsComponent,
            properties: {
                fieldSections: [fieldSection]
            },
            afterComponentInit: (component: EditableFieldsComponent) => {
                component.ngOnChanges({ fieldSections: { currentValue: [fieldSection] } });
            }
        };

        const dialogData = new DialogData(componentData, null, [], "-narrower");
        dialogData.heading = { title: `Preview response ${context.data.dataItem.ReferralCode}`, subTitle: `${context.data.parentItem.title}` };
        this.modalWindowService.setMapping(dialogData, PREVIEW_RESPONSE_MAPPING);
        this.modalWindowService.show(PREVIEW_RESPONSE_MAPPING, context.currentRoute.parent);
        dialogData.doneCallback = () => this.router.navigate([], {});

        return of(true);
    }
}
