import { Component, OnInit, Input } from "@angular/core";
import { Router } from "@angular/router";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const ROOT_BREADCRUMB_ITEM: BreadcrumbItem = {
    Title: "All items",
    FolderId: null
};

@Component({
    templateUrl: "./breadcrumb-navigation.component.html",
    selector: "sf-breadcrumb-navigation"
})
export class BreadcrumbNavigationComponent extends SfRxBase implements OnInit {
    @Input() entityData: EntityData;
    @Input() parentItem: DataItem;
    breadcrumbItems: BreadcrumbItem[] = [];

    constructor(private router: Router) {
        super();
    }

    ngOnInit() {
        const isRoot = this.entityData.metadata.hasChildren || this.parentItem === null;
        if (isRoot) {
            return;
        }

        ROOT_BREADCRUMB_ITEM.Title = `All ${this.entityData.metadata.setName}`;
        this.breadcrumbItems = [ROOT_BREADCRUMB_ITEM];

        const currentFolder: BreadcrumbItem = {
            Title: this.parentItem.data.Title,
            FolderId: this.parentItem.data.FolderId
        };

        if (this.parentItem.data.Breadcrumb) {
            const breadcrumb = this.parentItem.data.Breadcrumb;
            this.breadcrumbItems.push(...breadcrumb);
        }

        this.breadcrumbItems.push(currentFolder);
    }

    onItemClick(item: BreadcrumbItem) {
        if (item.Title === ROOT_BREADCRUMB_ITEM.Title) {
            this.router.navigate([ROUTE_PATHS.CONTENT, this.entityData.metadata.setName], { queryParams: { sortKey: undefined, sf_filter: undefined },  queryParamsHandling: "merge" });
        } else {
            this.router.navigate([ROUTE_PATHS.CONTENT, this.entityData.metadata.setName, item.FolderId, this.entityData.metadata.setName], { queryParams: { sortKey: undefined },  queryParamsHandling: "merge" });
        }
    }
}

interface BreadcrumbItem {
    Title: string;
    FolderId: string;
}
