import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Resolve } from "@angular/router";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { Observable, ReplaySubject } from "rxjs";
import { DEFAULT_FIELD_NAME, DISPLAY_NAME, Entity, MetadataContainer, SINGULAR_NAME } from "../shared/services/metadata/meta-data.store";
import { FIELD_SORT_RESTRICTIONS, SITEFINITY_NAMESPACE } from "../../../../fields/common/common-constants";
import { HttpODataRequestWrapper } from "../shared/services/http-odata-request.wrapper";
import { RESOLVE_NAMES } from "../content/constants";
import { getRouteDataRecursively } from "../content/dynamic-modules/components/helpers";
import { toggleIrisIntegratedStyles } from "../../utils";

@Injectable()
export class FormResponsesResolver implements Resolve<any> {
    constructor(
        private http: HttpODataRequestWrapper) {
    }
    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<MetadataContainer> {
        return this.getMetadataContainer(route);
    }

    private getMetadataContainer(route: ActivatedRouteSnapshot) {
        toggleIrisIntegratedStyles(true);
        const formResponsesContainer = new ReplaySubject<MetadataContainer>(1);
        this.http.get(`${ENTITY_SET.FORM_DRAFTS}/Default.GetFormMetadata()`).then((response: { value: FormMetadata[] }) => {

            const container = getRouteDataRecursively(route, RESOLVE_NAMES.metadata);
            response.value.forEach((form) => {
                const propertiesObject: { [key: string]: any } = {
                    [DISPLAY_NAME]: "responses",
                    [SINGULAR_NAME]: "response",
                    [DEFAULT_FIELD_NAME]: "all",
                    [FIELD_SORT_RESTRICTIONS]: []
                };

                form.Fields.forEach((field) => {
                    propertiesObject[field.Name] = {
                        type: [
                            "string",
                            "null"
                        ],
                        [`${SITEFINITY_NAMESPACE}.FieldType`]: "ShortText",
                    };
                    propertiesObject[FIELD_SORT_RESTRICTIONS].push(field.Name);
                });
                const entity = new Entity(form.FormEntriesType, {
                    keys: ["Id"],
                    properties: propertiesObject,
                });

                entity.setName = `${ENTITY_SET.FORM_RESPONSES}-${form.Name}`;
                entity.relations = [];
                entity.primitives = form.Fields.map(x => x.Name);
                entity.parent = ENTITY_SET.FORMS;
                container.entities[entity.setName] = entity;
                container.entitiesByFullTypeName[form.FormEntriesType] = entity;
            });

            formResponsesContainer.next(container);
        });

        return formResponsesContainer;
    }
}

interface FormMetadata {
    Name: string,
    FormEntriesType: string,
    Fields: [{ Name: string }]
}
