import { Component, EventEmitter, OnInit, Output, ViewChild } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { stringConstants } from "../../common-constants";
import { RESOLVE_NAMES, ROUTE_PARAMS } from "../content/constants";
import { ChoiceSettings } from "../../../../fields/choice/choice.settings";
import { FieldBase } from "../../../../fields/field-base";
import { ChoiceOption, ParentSelectorSettings } from "./parent-selector-settings";
import { ChoiceComponent } from "../../../../fields/choice/choice.component";
import { DISPLAY_MODE } from "../../../../fields/fields-constants";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { StatusType } from "../../../../fields/field-status";
import { EntityData } from "../content/dynamic-modules/interfaces";
import { TaxaComponent } from "../taxonomy/taxa/taxa.component";
import { TaxonomySettings } from "../taxonomy/taxonomy.settings";

export const TOP_LEVEL_OPTION = "On top level";
const enum PageHierarchyOptions {
    OnTopLevel = 1
}

@Component({
    selector: "sf-dropdown-selector",
    templateUrl: "./parent-selector.component.html"
})
export class ParentSelectorComponent extends FieldBase implements OnInit {
    public expandPathPair: { key: string, value: string } = { key: "Breadcrumb", value: "Title" };
    public hasParent: boolean = false;
    public showAddToTopLevel: boolean;
    public hierarchicalTaxaEntityData: EntityData;

    @ViewChild("parentSelector", { static: true }) private parentSelector: ChoiceComponent;
    @ViewChild("hierarchicalTaxa", { static: true }) private hierarchicalTaxa: TaxaComponent;
    @Output() onHierarchicalTaxaSelected: EventEmitter<SelectedTaxaModel> = new EventEmitter<SelectedTaxaModel>();
    private options: Array<ChoiceOption> = [];
    private isPage: boolean = false;
    private friendlyTitle: string;

    constructor(private route: ActivatedRoute) {
        super();
    }

    ngOnInit() {
        const componentSettings = (this.settings as ParentSelectorSettings);
        this.initChoicesOptions(componentSettings);
        this.showAddToTopLevel = componentSettings.showAddToTopLevel;
        this.initChoiceField(this.showAddToTopLevel);

        this.friendlyTitle = `parent ${componentSettings.selectorNames.singular.toLowerCase()}`;
        this.settings.title = this.showAddToTopLevel ? `Put this ${componentSettings.selectorNames.singular.toLowerCase()}...` : componentSettings.selectorNames.singular;
        this.settings.friendlyTitle = this.friendlyTitle;

        const hierarchicalTaxaSettings = componentSettings.hierarchicalTaxaSettings;
        if (!hierarchicalTaxaSettings.culture) {
            hierarchicalTaxaSettings.culture = componentSettings.culture;
        }

        if (this.route && hierarchicalTaxaSettings.type === ENTITY_SET.PAGES) {
            const siteDataStore = this.route.parent.snapshot.data[RESOLVE_NAMES.siteDataStore];
            if (siteDataStore) {
                this.settings.defaultValue = siteDataStore.SiteMapRootNodeId;
                hierarchicalTaxaSettings.id = this.settings.dataItem.data ? this.settings.dataItem.data.Id : stringConstants.DEFAULT_GUID;
                this.isPage = true;
            }
        }

        if ((this.value && this.value !== this.settings.defaultValue && this.value !== stringConstants.DEFAULT_GUID) || !this.showAddToTopLevel) {
            this.hasParent = true;
            this.parentSelector.settings.defaultValue = this.options[PageHierarchyOptions.OnTopLevel].Value;
        }

        const metaStore = this.route && (this.route.parent?.snapshot.data.metaStore || this.route.snapshot.data.metaStore);
        this.hierarchicalTaxaEntityData = {
            culture: componentSettings.culture,
            provider: componentSettings.dataItem ? componentSettings.dataItem.provider : null,
            metadata: metaStore?.entities[hierarchicalTaxaSettings.type]
        };
        this.initHierarchicalTaxaField(hierarchicalTaxaSettings);
    }

    onParentSelectionChange(parentOption: string) {
        this.hasParent = !!parentOption;

        if (this.hasParent) {
            this.writeValue(null);
            this.hierarchicalTaxa.focusChips();
        } else {
            this.onHierarchicalTaxaSelected.emit(null);
            this.writeValue(this.settings.defaultValue);
        }
    }

    onHierarchicalTaxaSelect(hierarchicalTaxaId: string, hierarchicalTaxaName?: string) {
        if (this.hasParent) {
            this.writeValue(hierarchicalTaxaId);
            this.hierarchicalTaxa.focusOutChips();
        }

        const selectedTaxa: SelectedTaxaModel = {
            id: hierarchicalTaxaId,
            name: hierarchicalTaxaName || this.getTaxaNameById(hierarchicalTaxaId)
        }

        this.onHierarchicalTaxaSelected.emit(selectedTaxa);
    }

    onTaxaErrorOccured(errorMessage: string) {
        this.emitStatus({ type: StatusType.Error, data: { error: errorMessage } });
    }

    postProcessValue(value: any): string {
        if (this.isPage && value) {
            if (value === stringConstants.DEFAULT_GUID) {
                value = this.settings.defaultValue;
            }
        }

        return value;
    }

    validate() {
        if (!this.isPage && (this.value === null || this.value === stringConstants.DEFAULT_GUID) && this.hasParent) {
            const errors = {
                required: true
            };
            this.emitStatus({ type: StatusType.Error, data: errors });
            return false;
        } else {
            this.emitStatus({ type: StatusType.Done });
            return true;
        }
    }

    processErrors(errors: any): Array<string> {
        const errorMessages: Array<string> = super.processErrors(errors);

        if (errors.required === true) {
            errorMessages.forEach((msg, i) => {
                if (msg === `Enter ${this.friendlyTitle}`) {
                    errorMessages[i] = `Select a ${this.friendlyTitle}`;
                }
            });
        }

        return errorMessages;
    }

    setSiteId(siteId: string) {
        this.hasParent = false;
        this.hierarchicalTaxa.setSiteId(siteId);
        this.parentSelector.writeValue(this.options[0].Value);
    }

    setCulture(culture: string) {
        this.hierarchicalTaxa.setCulture(culture);
    }

    private getTaxaNameById(id: string): any {
        const foundTaxa = this.hierarchicalTaxa.taxa.find((x: any) => x.Id === id);
        if (foundTaxa) {
            return foundTaxa["Name"];
        }

        return null;
    }

    private initChoicesOptions(componentSettings: ParentSelectorSettings) {
        if (!componentSettings.choiceOptions) {
            this.options.push({
                Name: "On top level",
                Value: ""
            });
            this.options.push({
                Name: `Under parent ${componentSettings.selectorNames.singular.toLowerCase()}...`,
                Value: "parent"
            });
        } else {
            this.options = componentSettings.choiceOptions;
        }
    }

    private initChoiceField(showAddToTopLevel: boolean) {
        const settings = new ChoiceSettings("selector", false);
        settings.choices = this.options;
        settings.defaultValue = showAddToTopLevel ? this.options[0].Value : this.options[1].Value;

        this.parentSelector.settings = settings;
    }

    private initHierarchicalTaxaField(hierarchicalTaxaSettings: TaxonomySettings) {
        const settings = Object.assign({}, hierarchicalTaxaSettings);

        settings.displayMode = DISPLAY_MODE.NORMAL;
        settings.allowCreate = false;
        settings.allowMultiple = false;
        settings.showTitle = false;
        settings.showMenuItems = true;
        settings.isParentSelection = (this.settings as ParentSelectorSettings).isParentSelection;
        settings.excludeParent = (this.settings as ParentSelectorSettings).excludeParent;

        if (!settings.id && this.route) {
            const routeParams = this.route.parent?.snapshot.params;
            settings.id = routeParams ? routeParams[ROUTE_PARAMS.PARENT_ID_SEGMENT] : null;
        }

        this.hierarchicalTaxa.settings = settings;
    }
}

export interface SelectedTaxaModel {
    id: string,
    name: string
}
