import { Injectable, Inject } from "@angular/core";
import { Location } from "@angular/common";
import { Router, ActivatedRoute } from "@angular/router";

import { Observable, ReplaySubject, Subject } from "rxjs";

import { Command } from "../commands/command";
import { ExecutionContext } from "../commands/execution-context";
import { NavigateToEditArguments, DataItem, FieldWithLimitations } from "../../content/dynamic-modules/interfaces";
import { EditInDialogOperationResult, EditInDialogCommand } from "../../content/dynamic-modules/services/operations/commands/edit-in-dialog-command";
import { EditCommand } from "../../content/dynamic-modules/services/operations/commands/edit-command";
import { OPERATION_NAMES } from "../components/action-menu/operation.model";
import { ConfirmationCommand, ChainedOperationResult } from "../../content/dynamic-modules/services/operations/commands/confirmation-command";
import { DynamicUpdateItemComponent } from "../../content/dynamic-modules/components/dialog/dynamic-update-item.component";
import { FILTER_PARAMS } from "../../content/constants";

import { ModalWindowService } from "./modal-window.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { MediaHelpers } from "../../libraries/services/media.helpers";
import { MediaEditInDialogCommand } from "../../content/dynamic-modules/services/operations/commands/edit-in-dialog-media-command";
import { UrlService } from "../../../services/url.service";
import { environment } from "../../../../environments/environment";
import { environmentTypes } from "../../../environment";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { filter, first } from "rxjs/operators";
import { cloneObject } from "../../../utils";
import { ComponentData } from "@progress/sitefinity-component-framework";

export const OPEN_MEDIA_CONTENT_MODAL = "openIrisContent";
const ADMINAPP_EDIT_DIALOG_CLOSED = "adminAppEditDialogClosed";

@Injectable()
export class EditNavigationService {
    constructor(
        private router: Router,
        private location: Location,
        private dynamicItemStore: DynamicItemStore,
        private urlService: UrlService,
        @Inject(WINDOW_TOKEN) private window: Window,
        private modalWindowService: ModalWindowService) {
    }

    public openDialogForRelatedData(dataItem: DataItem, route: ActivatedRoute, fieldLimitations: FieldWithLimitations, navigateToChildrenAfterCreate: boolean, headComponentData: ComponentData, commandName?: string): Observable<EditInDialogOperationResult> {
        const args = new NavigateToEditArguments({ dataItem, route, parentId: dataItem.parentKey, openDialog: true, mediaFieldLimitationsConstraints: fieldLimitations, navigateToChildrenAfterCreate, headComponentData, commandName });
        return this.navigateToEdit(args).pipe(filter(x => x.success));
    }

    public openDialogForRelatedDataAndLoadFieldData(ids: string[], dataItem: DataItem, route: ActivatedRoute, fieldLimitations: FieldWithLimitations, navigateToChildrenAfterCreate: boolean, headComponentData: ComponentData): Observable<any[]> {
        const items$ = new ReplaySubject<any[]>();
        this.openDialogForRelatedData(dataItem, route, fieldLimitations, navigateToChildrenAfterCreate, headComponentData, OPERATION_NAMES.edit).subscribe(() => {
            this.loadFieldData(ids, dataItem, items$);
        });

        return items$;
    }

    public navigateToEditOfRelatedData(item: DataItem, route: ActivatedRoute, siteId?: string): Observable<EditInDialogOperationResult> {
        let baseUrl = this.router.createUrlTree([ROUTE_PATHS.CONTENT]).toString();

        if (environment.env === environmentTypes.integration) {
            baseUrl = this.urlService.getAbsoluteUrl(baseUrl);
        }

        const openInNewWindowArgs = {
            baseUrl,
            openInNewTab: true
        };

        const args = new NavigateToEditArguments({ dataItem: item, parentId: item.parentKey, openInNewWindowArgs, siteId: siteId });
        args.route = route;
        return this.navigateToEdit(args);
    }

    public navigateToEdit(args: NavigateToEditArguments): Observable<EditInDialogOperationResult> {
        let editCommand: Command;
        const executionContext = this.getContext(args);

        if (args.dataItem.metadata.hasLifecycle && !args.openDialog && !args.dataItem.metadata.isSelfReferencing) {
            editCommand = new EditCommand(this.router, this.location, this.window);
        } else {
            editCommand = new EditInDialogCommand(this.modalWindowService, this.router);

            if (MediaHelpers.isMediaEntity(args.dataItem) && args.dataItem.isEmpty) {
                editCommand = new MediaEditInDialogCommand(this.modalWindowService, this.router, this.dynamicItemStore.service, this.window);
                executionContext.data.parentItem = args.parentItem;
            }

            executionContext.data.headComponentData = args.headComponentData;
        }

        const result = new Subject<EditInDialogOperationResult>();
        if (!executionContext.data.duplicate && !args.dataItem.isEmpty) {
            this.confirm(args).subscribe((confirmResult) => {
                if (confirmResult.success) {
                    editCommand.execute(executionContext).subscribe((editResult) => {
                        result.next(editResult);
                    });
                } else {
                    result.next({
                        dataItem: null,
                        forceReload: false,
                        isLoading: confirmResult.isLoading,
                        success: confirmResult.success
                    });
                }
            });
        } else {
            editCommand.execute(executionContext).subscribe((editResult) => {
                result.next(editResult);
            });
        }

        return result;
    }

    public confirm(args: NavigateToEditArguments): Observable<ChainedOperationResult> {
        const lockedCommand = new ConfirmationCommand(this.dynamicItemStore.service, this.modalWindowService, this.window);
        return lockedCommand.execute(this.getContext(args));
    }

    public handleEditAllPropertiesFromMVCWidgets(route: ActivatedRoute) {
        this.window.document.removeEventListener(OPEN_MEDIA_CONTENT_MODAL, e => this.openMediaDialogEventHandler(e, route));
        this.window.document.addEventListener(OPEN_MEDIA_CONTENT_MODAL, e => this.openMediaDialogEventHandler(e, route));
    }

    private loadFieldData(ids: string[], dataItem: DataItem, items$: Subject<any[]>) {
        this.dynamicItemStore.service.getItemsByKeys({
            keyProperty: dataItem.metadata.key,
            keys: ids,
            entityData: dataItem,
            fallbackProperties: [dataItem.metadata.defaultFieldName]
        }).subscribe((data) => {
            const items = data.dataItems.map(x => cloneObject(x.data));
            items$.next(items);
        });
    }

    private getContext(args: NavigateToEditArguments): ExecutionContext {
        const relativeRoute = args.route.parent.parent;
        const executionContext: ExecutionContext = {
            currentRoute: relativeRoute,
            model: null,
            data: {
                dataItem: args.dataItem,
                siteData: args.route.parent.snapshot.data.siteDataStore,
                replaceUrl: args.replaceUrl,
                wasInCreate: args.wasInCreate,
                reload: args.reload,
                dialogType: DynamicUpdateItemComponent,
                openInNewWindowArgs: args.openInNewWindowArgs,
                mediaFieldLimitationsConstraints: args.mediaFieldLimitationsConstraints,
                navigateToChildrenAfterCreate: args.navigateToChildrenAfterCreate,
                prepopulatedFields: args.prepopulatedFields,
                commandName: args.commandName,
                translationCultureSource: args.translationCultureSource,
                siteId: args.siteId
            }
        };

        let parentIdParsed = args.parentId;
        let filterValue = args.route.snapshot.queryParams[FILTER_PARAMS.FILTER];
        if (args.dataItem.metadata.ignoreParentChildRelationship && filterValue && filterValue.indexOf("Parent,") > -1) {
            filterValue = filterValue.replace("Parent,", "");
            parentIdParsed = filterValue;
        }

        const duplicate = args.commandName === OPERATION_NAMES.duplicate;
        executionContext.data.duplicate = duplicate;
        executionContext.data.parentId = parentIdParsed;
        executionContext.data.singularName = args.singularName;

        return executionContext;
    }

    private openMediaDialogEventHandler(e: any, route: ActivatedRoute) {
        const props: EditAllPropertiesDTO = e.detail;

        e.preventDefault();

        const metadata = route.parent.snapshot.data.metaStore.entities[props.mediaType];

        const entityData = {
            metadata,
            provider: props.provider,
            culture: props.culture
        };

        this.dynamicItemStore.getItem({ entityData: entityData, itemKey: props.itemId }).pipe(first()).subscribe((dataItem: any) => {
            const navigateToEditArguments = new NavigateToEditArguments({
                dataItem,
                route,
                parentId: props.parentId,
                openDialog: true,
                replaceUrl: false,
                wasInCreate: false,
                reload: false
            });

            this.navigateToEdit(navigateToEditArguments).subscribe(() => {
                const adminappEditDialogClosed = new CustomEvent(ADMINAPP_EDIT_DIALOG_CLOSED);
                this.window.document.dispatchEvent(adminappEditDialogClosed);
            });
        });
    }
}

interface EditAllPropertiesDTO {
    parentId: string,
    itemId: string,
    mediaType: string,
    provider: string,
    culture: string
}
