import { Route } from "@angular/router";

import { DynamicItemIndexComponent } from "./components/dynamic-item-index.component";
import { DynamicItemComponent } from "./components/entity/dynamic-item.component";
import { DynamicItemGuard } from "./services/entity/dynamic-item.guard";
import { HomeComponent } from "../../shared/components/navigation/home/home.component";
import { ContentComponent } from "../content.component";
import { BackendTweaksGridResolver } from "./services/backend-tweaks/backend-tweaks-grid.resolver";
import { BackendTweaksFormResolver } from "./services/backend-tweaks/backend-tweaks-form.resolver";
import { SidebarHostComponent } from "../../shared/components/sidebar/sidebar-host.component";
import { ModalWindowComponent } from "../../shared/components/modal-window/modal-window.component";
import { DynamicItemResolver } from "./services/entity/dynamic-item.resolver";
import { DynamicItemsResolver } from "./components/dynamic-items.resolver";
import { SiteTitleResolver } from "../../shared/services/site-title.resolver";
import { SiteTitleDynamicResolver } from "../../shared/services/site-title.dynamic.resolver";
import { ROUTE_PATHS_NO_PREFIX } from "../../../constants/route-paths";
import { RESOLVE_NAMES, ROUTE_PARAMS } from "../constants";
import { stringConstants } from "../../../common-constants";
import { ItemMetaResolver } from "./services/entity/item-meta-resolver";
import { UnlockRedirectComponent } from "../../shared/components/unlock-redirect/unlock-redirect.component";
import { ProviderRouteGuard } from "../../../provider.route-guard";
import { DynamicItemEditResolver } from "./services/entity/dynamic-item-edit.resolver";

const SIDEBAR_OUTLET: string = "sidebar";

export const resolvers = {
    /*[RESOLVE_NAMES.itemData] */"itemData": DynamicItemResolver,
    /*[RESOLVE_NAMES.formResolved]*/ "formResolved" : BackendTweaksFormResolver,
    /*[RESOLVE_NAMES.itemmeta]*/"itemmeta": ItemMetaResolver
};

export const EDIT_ROUTE: Route = {
    path: `:${ROUTE_PARAMS.ITEM_ID}/${ROUTE_PARAMS.EDIT_SEGMENT}`,
    component: DynamicItemComponent,
    canDeactivate: [DynamicItemGuard],
    canActivate: [DynamicItemGuard, DynamicItemEditResolver],
    resolve: resolvers,
    runGuardsAndResolvers: "paramsOrQueryParamsChange"
};

export const DUPLICATE_ROUTE: Route = {
    path: `:${ROUTE_PARAMS.ITEM_ID}/${ROUTE_PARAMS.DUPLICATE_SEGMENT}`,
    component: DynamicItemComponent,
    canDeactivate: [DynamicItemGuard],
    canActivate: [DynamicItemGuard, DynamicItemResolver],
    resolve: resolvers,
    runGuardsAndResolvers: "paramsOrQueryParamsChange"
};

export const dynamicModulesRoutes: Route[] = [
    {
        path: stringConstants.EMPTY_STRING,
        component: DynamicItemIndexComponent,
        resolve: {
            gridResolved: BackendTweaksGridResolver,
            dynamicItems: DynamicItemsResolver,
            siteTitle: SiteTitleDynamicResolver
        },
        canActivate: [ProviderRouteGuard, DynamicItemsResolver],
        runGuardsAndResolvers: "paramsOrQueryParamsChange"
    },
    {
        path: "confirm/insight",
        outlet: "dialog",
        loadChildren: () => import("../../insight/insight.module").then(m => m.InsightModule)
    },
    {
        path: ROUTE_PARAMS.CREATE_SEGMENT,
        component: DynamicItemComponent,
        canActivate: [DynamicItemResolver],
        canDeactivate: [DynamicItemGuard],
        resolve: resolvers,
        runGuardsAndResolvers: "paramsOrQueryParamsChange"
    },
    EDIT_ROUTE,
    {
        path: `:${ROUTE_PARAMS.ITEM_ID}/${ROUTE_PARAMS.UNLOCK_SEGMENT}`,
        component: UnlockRedirectComponent,
        canActivate: [DynamicItemResolver],
        resolve: resolvers
    },
    DUPLICATE_ROUTE,
    {
        path: "host/:name",
        component: SidebarHostComponent,
        outlet: SIDEBAR_OUTLET, // TODO: pass item
        resolve: {
            itemData: resolvers[RESOLVE_NAMES.itemData]
        }
    },
    {
        path: "confirm/:name",
        component: ModalWindowComponent,
        outlet: "dialog"
    },
    {
        path: ROUTE_PATHS_NO_PREFIX.MENU_HOME,
        component: HomeComponent,
        outlet: ROUTE_PATHS_NO_PREFIX.MENU_OUTLET,
        resolve: {
            siteTitle: SiteTitleResolver
        },
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.MENU_HOME
            }
        }
    },
    {
        path: ROUTE_PATHS_NO_PREFIX.CONTENT,
        component: ContentComponent,
        outlet: ROUTE_PATHS_NO_PREFIX.MENU_OUTLET,
        resolve: {
            siteTitle: SiteTitleResolver
        },
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.CONTENT
            }
        }
    }
];
