import { ClassProvider, Inject, Injectable } from "@angular/core";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { Observable, of, ReplaySubject } from "rxjs";
import { first } from "rxjs/operators";
import { ServiceInfo } from "../../../../../../fields/selector/selector.component";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { DynamicItemService, LoadItemsData, LoadItemsResponse } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { HierarchicalService, HIERARCHICAL_SERVICE_TOKEN, RESULT_COUNT } from "../hierarchical-service";
import { ENTITY_SET } from "../metadata/meta-data-constants";
import { Entity, MetadataStore, MODULE_NAME } from "../metadata/meta-data.store";
import { TaxonomySettings } from "../../../taxonomy/taxonomy.settings";
import { CONTENT_TYPE_SELECTOR_SINGULAR_NAME } from "../../../widget-editor/providers/fields/content-type-selector/content-type-selector.component";
import { MediaHelpers } from "../../../libraries/services/media.helpers";
import { LOCAL_STORAGE, StorageService } from "../storage.service";
import { HttpODataRequestWrapper } from "../http-odata-request.wrapper";
import { CURRENT_SITE_SERVICE_PATH, SiteData } from "../metadata/site-data.store";
import { QUERY_PARAMS } from "../../../content/constants";

const INACTIVE_FOR_THIS_SITE_TOOLTIP = "Inactive for this site";

@Injectable()
export class HierarchicalBackendInterfaceSettingsService extends HierarchicalService {
    private siteDataPerSiteId: { [siteId: string]: SiteData } = {};

    constructor(
        protected dynamicItemService: DynamicItemService,
        protected metadataStore: MetadataStore,
        @Inject(LOCAL_STORAGE) protected storage: StorageService,
        private http: HttpODataRequestWrapper
    ) {
        super(dynamicItemService);
    }

    showStatusIcons(): boolean {
        return false;
    }

    isHierarchical(type: string): boolean {
        return false;
    }

    getSetName(): string {
        // we resolve it to flat taxa in order to render the chip like component (content-type-selector.component.ts)
        return ENTITY_SET.FLAT_TAXA;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return CONTENT_TYPE_SELECTOR_SINGULAR_NAME === entityData.metadata.singularName;
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return of(<LoadItemsResponse>({
            totalCount: 0,
            dataItems: [],
            entityData: entityData
        }));
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string, isCreate: boolean): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        if (value) {
            this.getEntitiesDataItems(entityData).subscribe(dataItems => {
                const resultDataItems = dataItems.filter(x => value.includes(x.metadata.setName));

                result$.next({
                    totalCount: 0,
                    dataItems: resultDataItems,
                    entityData: entityData
                });
            });
        } else {
            result$.next({
                entityData: entityData,
                totalCount: 0,
                dataItems: []
            });
        }

        return result$;
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[], editItemId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        this.getEntitiesDataItems(entityData).subscribe(allDataItems => {
            if (value && value.length > 0) {
                allDataItems = allDataItems.filter(x => !value.includes(x.data.Id));
            }

            const totalCount = allDataItems.length;
            const filteredDataItems = allDataItems.slice(0, RESULT_COUNT);
            const itemsResponse = <LoadItemsResponse>({
                totalCount: totalCount,
                dataItems: filteredDataItems,
                entityData: entityData
            });
            result$.next(itemsResponse);
        });

        return result$.pipe(first());
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string, taxonId?: string): Observable<LoadItemsResponse> {
        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings, taxonId?: string, isCreate?: boolean): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        this.getEntitiesDataItems(entityData).subscribe(allDataItems => {
            const searchText = info.searchText.toLowerCase();
            const filteredDataItems = allDataItems.filter(x => x.data.Title.toLocaleLowerCase().startsWith(searchText));

            const itemsResponse = <LoadItemsResponse>({
                totalCount: filteredDataItems.length,
                dataItems: filteredDataItems,
                entityData: entityData
            });

            result$.next(itemsResponse);
        });

        return result$.pipe(first());
    }

    getModalItems(entityData: EntityData, taxaId: string, taxonId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        this.getEntitiesDataItems(entityData).subscribe(allDataItems => {
            const itemsResponse = <LoadItemsResponse>({
                totalCount: allDataItems.length,
                dataItems: allDataItems,
                entityData: entityData
            });
            result$.next(itemsResponse);
        });

        return result$.pipe(first());
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        this.getEntitiesDataItems(loadingData.entityData).subscribe(allDataItems => {
            const searchText = info.searchText.toLowerCase();
            let filteredDataItems = allDataItems.filter(x => x.data.Title.toLocaleLowerCase().startsWith(searchText));
            if (info.idsToExclude) {
                filteredDataItems = filteredDataItems.filter(x => !info.idsToExclude.includes(x.data.Title.toLocaleLowerCase()));
            }

            const resultDataItems = filteredDataItems.slice(0, loadingData.take || RESULT_COUNT);

            const itemsResponse = <LoadItemsResponse>({
                totalCount: filteredDataItems.length,
                dataItems: resultDataItems,
                entityData: loadingData.entityData
            });

            result$.next(itemsResponse);
        });

        return result$.pipe(first());
    }

    private getEntitiesDataItems(entityData: EntityData): Observable<DataItem[]> {
        const entitesDataItems$ = new ReplaySubject<DataItem[]>();
        const siteId = this.storage.getItem("sf_config_settings_site_id");
        if (!this.siteDataPerSiteId.hasOwnProperty(siteId)) {
            this.http
                .get(CURRENT_SITE_SERVICE_PATH, { params: { [QUERY_PARAMS.SITE]: siteId } })
                .then(data => {
                    const siteData: SiteData = data.value;
                    this.siteDataPerSiteId[siteId] = siteData;
                    entitesDataItems$.next(this.createEntitySetDataItems(siteId, entityData));
                });
        } else {
            entitesDataItems$.next(this.createEntitySetDataItems(siteId, entityData));
        }

        return entitesDataItems$.pipe(first());
    }

    private createEntitySetDataItems(siteId: string, entityData: EntityData): DataItem[] {
        const modules = this.siteDataPerSiteId[siteId].Modules;
        const moduleNames = Object.keys(modules);
        const accessibleEntitySets = moduleNames
            .map(name => modules[name].AccessibleTypes)
            .reduce((previous, current) => previous.concat(current));

        let allEntitySets = [];
        if (entityData.metadata.setName === ENTITY_SET.HIERARCHY_TAXA) {
            allEntitySets = this.metadataStore.getDynamicParentEntities();
        } else if (entityData.metadata.setName === ENTITY_SET.FLAT_TAXA) {
            allEntitySets = this.metadataStore.getAllContentTypeEntities();
        } else {
            allEntitySets = this.metadataStore.getAllContentTypeEntities().filter(x => x.parent === entityData.metadata.setName);
        }

        const entitySetDataItems = allEntitySets.map((entity: Entity) => {
            // displayName metadata for document, video, image libraries is always "Libraries" so we need to convert it here to a more user friendly name
            const displayName = MediaHelpers.isLibrary(entity.setName) ? MediaHelpers.resolveLibraryDisplayName(entity.setName) : entity.displayName;
            
            // media libraries like "albums", "documentlibraries", "videolibraries" are not included in the site's Accessible Types property only their respective media type is
            const resolvedEntitySetName = MediaHelpers.isLibrary(entity.setName) ? MediaHelpers.resolveMediaSetName(entity.setName) : entity.setName;

            let tooltip = stringConstants.EMPTY_STRING;
            let shouldGrayOutText = false;
            if (!accessibleEntitySets.includes(resolvedEntitySetName) && siteId !== stringConstants.DEFAULT_GUID) {
                tooltip = INACTIVE_FOR_THIS_SITE_TOOLTIP;
                shouldGrayOutText = true;
            }

            const additionalInfo = this.getAdditionalInfo(entity);

            return DataItem.from({ ShouldGrayOutText: shouldGrayOutText, Tooltip: tooltip, Title: displayName, TaxonName: displayName, Id: entity.setName, additionalInfo: additionalInfo }, entity, stringConstants.EMPTY_STRING, null);
        });

        return entitySetDataItems;
    }

    private getAdditionalInfo(entity: Entity) {
        if (entity?.hasParent) {
            return `under ${entity.properties[MODULE_NAME]}`;
        }

        return stringConstants.EMPTY_STRING;
    }
}

export const HIERARCHICAL_BACKEND_INTERFACE_SETTINGS_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalBackendInterfaceSettingsService
};
