import { Injectable } from "@angular/core";
import { SitefinitySdk } from "./sitefinitySdk.service";
import { EntityData, DataItem } from "../modules/content/dynamic-modules/interfaces";
import { BehaviorSubject } from "rxjs";
import { ErrorParserService } from "../modules/shared/services/errors/error-parser.service";

export const BUNDLE_DATA_OPERATIONS = {
    ANALYTICS: "Default.Analytics",
    SHARED_IN_COUNT: "Default.SharedInCount"
};

export const BATCH_SIZE = 50;

@Injectable()
export class BundleDataService {
    responses: BehaviorSubject<{ cleanRequest: boolean }> =
                new BehaviorSubject<{ cleanRequest: boolean }>(null);

    get data(): ResponseData {
        // we need the original data immutable
        return Object.assign({}, this._data);
    }

    private _data: ResponseData = {};

    constructor(private sitefinitySdk: SitefinitySdk, private errorParserService: ErrorParserService) { }

    requestBatch(contexts: ExecutionContext[], entityData: EntityData, siteId: string, cleanRequest: boolean = true) {
        if (cleanRequest) {
            const actions = contexts.map(x => x.action).reduce((x, y) => {
                if (x.indexOf(y) === -1) {
                    x.push(y);
                }
                return x;
            }, []);
            actions.forEach(action => {
                this._data[action] = {};
            });
        } else {
            contexts = contexts.filter(x => !this.data[x.action] || !this.data[x.action][x.id]);
        }

        const parts = [];

        for (let i = 0; i < contexts.length; i += BATCH_SIZE) {
            parts.push(contexts.slice(i, i + BATCH_SIZE));
        }

        if (parts.length === 0) {
            this.responses.next({ cleanRequest });
        }

        parts.forEach(partContexts => {
            const batch = this.sitefinitySdk.instance.batch(
                result => {
                    partContexts.forEach((context, index) => {
                        if (!this._data[context.action]) {
                            this._data[context.action] = {};
                        }
                        this._data[context.action][context.id] = { data: result.data[index].response.data };
                    });
                    this.responses.next({ cleanRequest });
                },
                error => {
                    throw this.errorParserService.parseError(error);
                },
                undefined,
                {
                    provider: entityData.provider,
                    culture: entityData.culture,
                    siteId: siteId
                }
            );

            partContexts.forEach(c => {
                batch.getSingle({
                    entitySet: c.entityData.metadata.setName,
                    key: c.id,
                    action: c.action
                });
            });

            batch.execute();
        });
    }

    requestSingle(dataItems: DataItem[], entityData: EntityData, actionName: string, siteId: string, clearCache: boolean = true) {
        let filteredDataItems = dataItems;

        if (clearCache) {
            this._data[actionName] = {};
        } else {
            // do not get data for items that are already in the cache
            filteredDataItems = filteredDataItems.filter(dataItem => !this.data[actionName][dataItem.key]);
        }

        if (filteredDataItems.length > 0) {
            const action = `${actionName}(keys=[${filteredDataItems.map(x => `'${x.key}'`).join(",")}])`;

            // wrapping the request in a batch to avoid browser/server limitation for url length
            const batch = this.sitefinitySdk.instance.batch(
                result => {
                    if (!this._data[actionName]) {
                        this._data[actionName] = {};
                    }

                    result.data[0]?.response.data.value?.forEach(itemResult => {
                        this._data[actionName][itemResult.Id] = { data: itemResult };
                    });

                    this.responses.next({ cleanRequest: clearCache });
                },
                error => {
                    throw this.errorParserService.parseError(error);
                },
                undefined,
                {
                    provider: entityData.provider,
                    culture: entityData.culture,
                    siteId: siteId
                }
            );

            batch.get({
                entitySet: entityData.metadata.setName,
                action
            });

            batch.execute();
        }
    }
}

export interface ExecutionContext {
    action: string;
    entityData: EntityData;
    id: string;
}

interface ResponseData {
    [action: string]: {
        [id: string]: {
            data: any
        }
    }
}
