import { Injectable, ClassProvider, Inject } from "@angular/core";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../shared/services/edit/edit-extender";
import { FIELD_SECTION_NAMES } from "../../../services/fieldSection.model";
import { EntityData, DataItem, Operation } from "../../content/dynamic-modules/interfaces";
import { NAVIGATION_OPTIONS_PROPERTIES, PAGE_TYPE_OPTIONS } from "../components/navigation-options-composite-component/navigation-options.composite.component";
import { PAGES_ENTITY_SET_NAME } from "./page.resolver";
import { ModifyFieldsArgs, EditActionContext, ActionResult } from "../../shared/services/edit/composite-edit-extender";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { Subject, Observable, of } from "rxjs";
import { environmentTypes } from "../../../environment";
import { stringConstants, SAME_TAB_TARGET } from "../../../common-constants";
import { DUPLICATE_LANG_PROP_NAME } from "../components/site-and-language-selector/site-and-language-selector.component";
import { TARGET_SITE_ID } from "../providers/page-fields.provider";
import { NOTIFICATION_SOURCE, QUERY_PARAMS } from "../../content/constants";
import { Router } from "@angular/router";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { cloneObject } from "../../../utils";
import { EnvironmentService } from "../../shared/services/environment.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { PagesActionHandler } from "./pages-action-handler.service";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { LONG_RUNNING_TASK_CREATED } from "../../content/dynamic-modules/components/long-running-services/long-running-progress.component";

@Injectable()
export class PagesEditExtender extends EditExtender {
    constructor(
        private pagesCommonHandler: PagesActionHandler,
        private environmentService: EnvironmentService,
        private modalWindowService: ModalWindowService,
        private router: Router,
        private service: DynamicItemService,
        @Inject(WINDOW_TOKEN) private window: Window) {
            super();
    }

    handleAction(context: EditActionContext, @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService): ActionResult {
        let newSite: string;
        let language: string;

        if (context.changedFields) {
            newSite = context.changedFields[TARGET_SITE_ID];
            language = context.changedFields[DUPLICATE_LANG_PROP_NAME];
        }

        const oldSite = context.siteData;

        if (language && !newSite) {
            const closeHandler = new Subject<void>();
            closeHandler.subscribe(() => {
                this.modalWindowService.hide(context.route).then(() => {
                    const queryParams = cloneObject(context.route.snapshot.queryParams);
                    queryParams[QUERY_PARAMS.CULTURE] = language;
                    this.router.navigate([ROUTE_PATHS.PAGES], { queryParams } );
                });
            });

            return {
                handled: of(true),
                result: this.updateItem(context, oldSite.Id, false),
                closeHandler
            };
        } else if (newSite && newSite !== oldSite.Id) {
            delete context.changedFields[TARGET_SITE_ID];

            let closeHandler: Subject<void>;
            if (environmentTypes.integration === this.environmentService.getEnvironment()) {
                closeHandler = new Subject<void>();
                closeHandler.subscribe(() => {
                    let currentUrl = this.window.location.href;
                    const urlStartToStrip = currentUrl.indexOf("/(dialog:confirm");
                    const urlEndToStrip = currentUrl.indexOf(")");

                    const subStringToRemove = currentUrl.substring(urlStartToStrip, urlEndToStrip + 1);
                    currentUrl = currentUrl.replace(subStringToRemove, stringConstants.EMPTY_STRING);

                    currentUrl = this.replaceQueryParam(currentUrl, "sf_site", newSite);

                    if (language) {
                        currentUrl = this.replaceQueryParam(currentUrl, QUERY_PARAMS.CULTURE, language);
                    }

                    this.window.open(currentUrl, SAME_TAB_TARGET);
                });
            }

            return {
                handled: of(true),
                result: this.updateItem(context, oldSite.Id, true),
                closeHandler
            };
        } else if (this.isDuplicate(context)) {
            const result = this.updateItem(context, undefined, undefined);

            result.subscribe(_ => {
                if (context.changedFields["DuplicateChildren"]) {
                    const event = new CustomEvent(LONG_RUNNING_TASK_CREATED);
                    this.window.dispatchEvent(event);
                }
            }, () => { /* prevent error from bubbling up */ });

            return {
                result,
                handled: of(true)
            };
        }

        const result = this.pagesCommonHandler.tryHandleAction(context);

        return {
            handled: result
        };
    }

    modify(args: ModifyFieldsArgs): Observable<void> {
        const dataItem = args.dataItem;
        const sections = args.sections;
        if (dataItem.metadata.setName === ENTITY_SET.PAGES) {

            // When we select group or redirect page we have to hide advanced options and seo sections
            if (dataItem.data && dataItem.data[NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE] && dataItem.data[NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE] !== PAGE_TYPE_OPTIONS.STANDARD) {
                // hide non required fields only
                sections.filter(x => x.settings.name === FIELD_SECTION_NAMES.advancedOptions ||
                    x.settings.name === FIELD_SECTION_NAMES.seo ||
                    x.settings.name === FIELD_SECTION_NAMES.socialMedia).forEach(section => {
                        let shouldHideSection = true;

                        section.fields.forEach(field => {
                            if (field.settings.required) {
                                field.settings.isVisible = true;
                                shouldHideSection = false;
                            } else {
                                field.settings.isVisible = false;
                            }
                        });

                        section.settings.isHidden = shouldHideSection;
                    });
            } else {
                sections.filter(x => x.settings.name === FIELD_SECTION_NAMES.advancedOptions ||
                    x.settings.name === FIELD_SECTION_NAMES.seo ||
                    x.settings.name === FIELD_SECTION_NAMES.socialMedia).forEach(section => {
                        section.fields.forEach(field => {
                            field.settings.isVisible = true;
                        });

                        section.settings.isHidden = false;
                    });
            }

            const mainSection = sections.find(x => x.settings.name === "MainSection");
            if (mainSection) {
                const field = mainSection.fields.find(x => x.settings.key === "DuplicateChildren");
                if (field) {
                    field.settings.showTitle = false;
                }
            }

        }

        return of(undefined);
    }

    showHeader(entityData: EntityData): boolean {
        return true;
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === PAGES_ENTITY_SET_NAME;
    }

    getStatusToDisplay(dataItem: DataItem): any {
        const statusToDisplay = super.getStatusToDisplay(dataItem);
        const hasWorkflowNotesNotification = statusToDisplay?.Source === NOTIFICATION_SOURCE.WORKFLOW && dataItem.metadata.setName === ENTITY_SET.PAGES;

        if (!hasWorkflowNotesNotification) {
            return statusToDisplay;
        } else {
            return null;
        }
    }

    private isDuplicate(context: EditActionContext): boolean {
        if (context.actionName === OPERATION_NAMES.create && context.changedFields && context.changedFields["Duplicate"]) {
            return true;
        }

        return false;
    }

    private updateItem(context: EditActionContext, siteId: string, doNotRefreshItem: boolean, operation: Operation = null): Observable<DataItem> {
        const result = this.service.upsert({
            data: context.changedFields,
            dataItem: context.item,
            siteId: siteId,
            doNotRefreshItem: doNotRefreshItem,
            operation: operation,
            skipSaveTemp: Object.keys(context.changedFields).length === 0
        });

        return result;
    }

    private replaceQueryParam(currentUrl: string, queryParamName: string, newVal: string): string {
        const asUrl = new URL(currentUrl);

        if (asUrl.search.includes(`${queryParamName}`)) {
            const index = asUrl.search.indexOf(`${queryParamName}=`) + `${queryParamName}=`.length;
            const nextParamIndex = asUrl.search.indexOf("&", index);
            let subString: string = null;
            if (nextParamIndex === -1) {
                subString = asUrl.search.substr(index);
            } else {
                subString = asUrl.search.substring(index, nextParamIndex);
            }

            asUrl.search = asUrl.search.replace(subString, newVal);
        } else {
            let queryParam = "?";
            if (asUrl.search.includes(queryParam))
                queryParam = "&";

            asUrl.search += `${queryParam}${queryParamName}=${newVal}`;
        }

        return asUrl.toString();
    }
}

export const PAGES_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: PagesEditExtender
};
