import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { Operation } from "../../shared/components/action-menu/operation.model";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { DataItem, TotalCountResult } from "../../content/dynamic-modules/interfaces";
import { map } from "rxjs/operators";
import { PropertyValueGroup, PropertyData, PropertyMetadata, ComponentMetadata } from "../../widget-editor/interfaces/widget-editor";
import { QUERY_PARAMS } from "../../content/constants";
import { GetWidgetMetadataArgs, GetWidgetsArgs, WidgetSection } from "./renderer.types";

@Injectable()
export class ZoneEditorContract {
    constructor(private service: DynamicItemService) {

    }

    addWidget(addWidget: AddWidgetRequest): Observable<WidgetModelWithState> {
        const payLoad = {
            widget: {
                Id: addWidget.widgetId,
                Name: addWidget.widgetName,
                PlaceholderName: addWidget.placeholderName,
                ParentPlaceholderKey: addWidget.parentPlaceholderKey,
                SiblingKey: addWidget.siblingKey,
                Properties: addWidget.properties
            }
        };
        return this.service.executeBoundAction<WidgetModelWithState>(addWidget.dataItem, `Default.AddWidget()`, payLoad, this.addQueryParams(addWidget.segmentId));
    }

    moveWidget(addWidget: AddWidgetRequest): Observable<void> {
        const payLoad = {
            widget: {
                Id: addWidget.widgetId,
                PlaceholderName: addWidget.placeholderName,
                ParentPlaceholderKey: addWidget.parentPlaceholderKey,
                SiblingKey: addWidget.siblingKey
            }
        };
        return this.service.executeBoundAction<void>(addWidget.dataItem, `Default.MoveWidget()`, payLoad, this.addQueryParams(addWidget.segmentId));
    }

    lock(request: LockRequest): Observable<EditorStateResponse> {
        const payload = {
            state: {
                Version: request.state.Version
            }
        };
        return this.service.executeBoundAction(request.dataItem, `Default.Lock()`, payload, this.addQueryParams(request.state.SegmentId));
    }

    unlock(dataItem: DataItem): Observable<void> {
        return this.service.executeBoundAction(dataItem, `Default.Unlock()`, null);
    }

    discard(dataItem: DataItem): Observable<void> {
        return this.service.executeBoundAction(dataItem, `Default.Discard()`, null);
    }

    getWidgetOperations(dataItem: DataItem, widgetKey: string, segmentId: string, widgetSegmentId: string): Observable<Operation[]> {
        return this.service.executeBoundFunction(dataItem, `Default.GetWidgetOperations(widgetKey='${widgetKey}')`, [], this.addQueryParams(segmentId, widgetSegmentId)).pipe(map((x: any) => x.value as Operation[]));
    }

    executeWidgetOperation(dataItem: DataItem, widgetKey: string, operation: Operation, parameters?: PropertyData[], metadata?: PropertyMetadata[], segmentId?: string, widgetSegmentId?: string): Observable<WidgetOperationResult> {
        const payload: ExecuteWidgetOperationRequest = {
            operation: {
                WidgetKey: widgetKey,
                Name: operation.Name,
                Parameters: parameters,
                PropertyMetadata: metadata
            }
        };

        return this.service.executeBoundAction(dataItem, `Default.ExecuteWidgetOperation()`, payload, this.addQueryParams(segmentId, widgetSegmentId)).pipe(map((x: any) => {
            const operationResult = x as WidgetOperationResult;
            operationResult.SourceOperation = operation;
            return operationResult;
        }));
    }

    getState(dataItem: DataItem, segmentId: string): Observable<EditorStateResponse> {
        return this.service.executeBoundFunction(dataItem, `Default.GetState()`, [], this.addQueryParams(segmentId));
    }

    setWidgetPropertyValues(dataItem: DataItem, propertyValueGroup: PropertyValueGroup, segmentId: string, widgetSegmentId: string): Observable<void> {
        return this.service.executeBoundAction(dataItem, `Default.SetProperties()`, { propertyValueGroup }, this.addQueryParams(segmentId, widgetSegmentId));
    }

    getHierarchicalWidgetModel(dataItem: DataItem, widgetKey: string, segmentId: string, widgetSegmentId: string): Observable<WidgetModelWithState> {
        return this.service.executeBoundFunction(dataItem, `Default.HierarchicalWidgetModel(componentId='${widgetKey}')`, [], this.addQueryParams(segmentId, widgetSegmentId));
    }

    getWidgetPropertyValues(dataItem: DataItem, widgetKey: string, segmentId: string, widgetSegmentId: string): Observable<PropertyValueGroup> {
        const properties$: Observable<PropertyValueGroup> = this.service.executeBoundFunction(dataItem, `Default.GetPropertyValues(componentId='${widgetKey}')`, [], this.addQueryParams(segmentId, widgetSegmentId))
        .pipe(map((response: PropertyValueGroup) => {
            return response;
        }));

        return properties$;
    }

    getWidgets(args: GetWidgetsArgs): Observable<TotalCountResult<Array<WidgetSection>>> {
        const ret: { [key: string]: string } = {};
        if (args.category)
            ret["category"] = args.category;

        if (args.search)
            ret["search"] = args.search;

        if (args.skip)
            ret["skip"] = args.skip.toString();

        if (args.take)
            ret["take"] = args.take.toString();

        const widgets$: Observable<TotalCountResult<Array<WidgetSection>>> = this.service.executeBoundFunction(args.dataItem, `Default.GetWidgets()`, undefined, ret).pipe(map((x: any) => {
            return {
                dataItems: x.Sections.map((y => {
                    return <WidgetSection>{
                        title: y.Title,
                        widgets: y.Widgets.map(z => {
                            return {
                                name: z.Name,
                                title: z.Title,
                                order: z.Order,
                                section: z.Section,
                                thumbnailUrl: z.Thumbnail
                            };
                        })
                    };
                })),
                totalCount: x.TotalCount
            };
        }));

        return widgets$;
    }

    getWidgetMetadata(args: GetWidgetMetadataArgs): Observable<ComponentMetadata> {
        return this.service.executeBoundFunction<ComponentMetadata>(args.dataItem, `Default.GetComponentMetadata(componentId='${args.widgetKey}')`);
    }

    getLazyComponents(dataItem: DataItem, segmentId: string, widgetSegmentId: string): Observable<LazyComponetsResponse> {
        return this.service.executeBoundFunction<LazyComponetsResponse>(dataItem, `Default.LazyComponents()`, undefined, this.addQueryParams(segmentId, widgetSegmentId));
    }

    private addQueryParams(segmentId?: string, widgetSegmentId?: string): { [key: string]: string } {
        const ret: { [key: string]: string } = {};
        if (segmentId) {
            ret[QUERY_PARAMS.SEGMENT] = segmentId;
        }

        if (widgetSegmentId)
            ret[QUERY_PARAMS.WIDGET_SEGMENT_ID] = widgetSegmentId;

        return ret;
    }
}

export interface LazyComponetsResponse {
    Components: WidgetModel[]
    WidgetState: WidgetState[]
}

export interface EditorStateResponse {
    Version: number;
    HasChanged: boolean;
    EditAllowed: boolean;
    AddAllowed: boolean;
    WidgetState: WidgetState[];
    SegmentId: string;
    Toolbox: string;
    EmptyMessageLabel: string;
    AddMessageLabel: string;
    AddMessageForEmptyScreenLabel: string;
    LockedByCurrentUser: boolean;
}

export interface WidgetState {
    Key: string;
    Name: string,
    AddAllowed: boolean;
    DeleteAllowed: boolean;
    EditAllowed: boolean;
    MoveAllowed: boolean;
    LabelTooltip: string;
    IsPersonalized: boolean;
    WidgetSegmentId: string;
}

export interface WidgetModel {
    Id: string;
    Name: string;
    Properties: any;
    Children: WidgetModel[]
}

export interface WidgetModelWithState extends WidgetModel {
    WidgetState: WidgetState[];
}

export interface AddWidgetRequest {
    widgetId: string;
    dataItem: DataItem;
    widgetName: string;
    placeholderName: string;
    parentPlaceholderKey: string;
    siblingKey: string;
    properties: Array<PropertyData>;
    segmentId?: string;
}
export interface ExecuteWidgetOperationRequest {
    operation: {
        WidgetKey: string;
        Name: string,
        Parameters: PropertyData[],
        PropertyMetadata: PropertyMetadata[]
    }
}

export interface LockRequest {
    state: EditorStateResponse,
    dataItem: DataItem
}

export interface WidgetOperationResult  {
    Properties?: Array<PropertyData>,
    State?: WidgetState,
    SkipRerender?: boolean,
    Success: boolean,
    Message?: string,
    Type?: string,
    Link?: string,
    SourceOperation?: Operation
    AvailableActions?: string[]
}
