import { FieldModel } from "../services/field.model";

export class FieldSectionModel {
    fields: FieldModel[];
    settings: FieldSectionSettings;

    constructor(settings?: FieldSectionSettings) {
        this.settings = settings;
        this.fields = [];
    }

     /**
     * Compares deeply the model to another model of the same class.
     * @param obj another FieldSectionModel to compare to
     */
    public equals (obj: FieldSectionModel): boolean {
        if (this.objEqual(obj, this)) {
            return this.objEqual(obj.settings, this.settings);
        }
        return false;
    }

    private objEqual(obj, obj2): boolean {
        for (const property in obj2) {
            if (!Object.is(obj[property], obj2[property]))
                return false;
        }
        return true;
    }
}

export interface FieldSectionSettings {
    isExpanded: boolean;
    isMain: boolean;
    insertHorizontalRule: boolean;
    title?: string;
    hideTitle?: boolean;
    name?: string;
    isHidden?: boolean;
    cssClass?: string;
    hideExpander?: boolean;
    warning?: string;
}

export const FIELD_SECTION_NAMES = Object.freeze({
    advancedOptions: "AdvancedOptionsSection",
    advancedSection: "AdvancedSection",
    seo: "SeoSection",
    socialMedia: "SocialMedia",
    mainSection: "MainSection"
});
