import { tap } from "rxjs/operators";
import { SelectorBase } from "../selector-base";
import { ProviderSelectorItem } from "./provider-selector-item";
import { ProviderService } from "../../../../../../../content/dynamic-modules/services/provider-service";
import { Observable } from "rxjs";
import { LoadingState } from "../../../../../../../shared/rxjs-extensions/delayEmission";
import { DYNAMIC_ITEMS_DEFINITIONS } from "../../../../../../../shared/services/metadata/meta-data-parser.service";
import { stringConstants } from "../../../../../../../../common-constants";
import { Logger } from "../../../../../../../shared/services/logger-source/logger";
import { QUERY_PARAMS } from "../../../../../../../content/constants";
import { toLoadingState } from "../../../../../../../shared/rxjs-extensions";
import { LoadingContentState } from "../../../../../../../shared/rxjs-extensions/toLoadingState";
import { Provider } from "../../../../../../../content/dynamic-modules/components/provider-selector/provider-selector-base.component";

export class ProviderSelector extends SelectorBase<ProviderSelectorItem> {
    shouldHide: boolean = true;
    constructor(logger: Logger, private providersService: ProviderService) {
        super(logger);
    }

    protected setSelectedItem(value: ProviderSelectorItem) {
        this.context.selectedProvider = value;
        super.setSelectedItem(value);
    }

    onInit(): Observable<LoadingState> {
        const selectedSet = this.context.selectedEntitySet;
        return this.providersService.getProviders(selectedSet.value,
            {
                params: {
                    [QUERY_PARAMS.SITE]: this.context.selectedSite.value
                }
            })
            .pipe( // no time to refactor the service to include the loading state in the response
            toLoadingState(),
            tap((providersData: LoadingContentState<Provider[]>) => {
                if (!providersData.isLoading) {
                    const mappedProviders = providersData.content.map(p => ProviderSelectorItem.fromProvider(p));
                    const defaultProvider = mappedProviders.find(p => p.isDefault);
                    this.items = mappedProviders;
                    this.determineVisibility();
                    this.setSelectedItem(defaultProvider);
                }
            }));
    }

    determineVisibility(): any {
        this.shouldHide = this.items.length <= 1 ||
            this.context.selectedEntitySet.entity.typeFullName === DYNAMIC_ITEMS_DEFINITIONS.PAGE_NODE.replace("#/definitions/", stringConstants.EMPTY_STRING);
    }
}

export interface ProvidersResponse extends LoadingState {
    providers: Provider[];
}
