import { Injectable, InjectionToken } from "@angular/core";
import { Settings } from "./settings.service";
import { RequestWrapper } from "./request.wrapper";
import { QUERY_PARAMS } from "../../content/constants";
import { HttpClient } from "@angular/common/http";
import { stringConstants } from "../../../../../cypress/e2e/helpers/constants";

export const HTTP_WEB_REQUEST_WRAPPER = new InjectionToken("HttpWebRequestWrapper");

@Injectable()
export class HttpWebRequestWrapper implements RequestWrapper {
    constructor(
        private http: HttpClient,
        private settings: Settings) {
    }

    get(relativeUrl: string): Promise<any> {
        const promiseExecutor = (resolve, reject) => {
            if (relativeUrl) {
                if (relativeUrl.startsWith(stringConstants.FORWARD_SLASH))
                    relativeUrl = relativeUrl.substring(0, relativeUrl.length - 1);
                const url = `${this.settings.url}${relativeUrl}`;
                const params = { [QUERY_PARAMS.SITE]: this.settings.siteId };
                this.http.get(url, { params }).subscribe(resolve, reject);
            }
        };

        return new Promise(promiseExecutor);
    }

    post(relativeUrl: string, body: any = {}): Promise<any> {
        const promiseExecutor = (resolve, reject) => {
            if (relativeUrl) {
                if (relativeUrl.startsWith(stringConstants.FORWARD_SLASH))
                    relativeUrl = relativeUrl.substring(0, relativeUrl.length - 1);
                const url = `${this.settings.url}${relativeUrl}`;
                const params = { [QUERY_PARAMS.SITE]: this.settings.siteId };
                this.http.post(url, body, { params }).subscribe(resolve, reject);
            }
        };

        return new Promise(promiseExecutor);
    }
}
