@Component({
    selector: "sf-enhanced-page",
    templateUrl: "./enhanced-page.component.html"
})
export class EnhancedPageComponent extends SfRxBase implements OnDestroy, OnChanges {
    @ViewChild("iframe", { static: false }) iframe: ElementRef<HTMLIFrameElement>;
    @Input() iFrameUrl: string;
    @Input() isFullWidth: string;
    @Input() dataItem: DataItem;
    @Input() state: EditorStateResponse;
    @Input() emptyRootCssClasses: string[];
    @Input() useNarrowLook: boolean;
    @Input() initialWidgetSelectorTabName: string;
    @Input() preserveNotifications: boolean;

    @Output() frameLoaded: EventEmitter<void> = new EventEmitter();
    @Output() layoutChanged: EventEmitter<ContainerModel> = new EventEmitter();
    @Output() addWidgetClicked: EventEmitter<AddWidgetArgs> = new EventEmitter();
    @Output() editWidgetClicked: EventEmitter<AddWidgetArgs> = new EventEmitter();
    @Output() onClearWidget: EventEmitter<string> = new EventEmitter();
    @Output() onComponentClicked = new EventEmitter<LoadWidgetOperations>();
    @Output() onComponentOperationExecuted = new EventEmitter<{ component: ComponentModel, result: WidgetOperationResult }>();

    isInitialized: boolean = false;
    notificationFilter = ZONE_EDITOR_NOTIFICATION_FILTER;

    private rootContainer: ContainerModel;

    private currentlyDraggedId: string;
    private currentlyDraggedElementTitle: ReplaySubject<string> = new ReplaySubject(1);
    private dragImagesMap: Map <string, HTMLImageElement> = new Map<string, HTMLImageElement>();
    private dragImagesSrcList = DRAG_IMAGES_SRC_LIST;
    private activatedAddWidgetPosition: ActivatedAddWidgetPosition;
    private waitForInsert: boolean = false;
    private widgetWithOpenedQuickEditMenu: ComponentModel;
    private documentInsideIframeMouseClickListener: (event: MouseEvent) => void;
    private outsideWindowMouseClickListener: (event: MouseEvent) => void;
    private contractReadyListener: (event: CustomEvent) => void;

    private get documentProvider(): Document {
        return this.windowProvider.document;
    }

    private get documentIFrameElement(): Document {
        return this.iframe?.nativeElement.contentWindow.document;
    }

    private get commonToolbarOptions() {
            return {
                widget: null,
                dataItem: this.dataItem,
                iframe: this.iframe,
                route: this.route,
                windowElement: this.iframe.nativeElement.contentWindow,
                segmentId: this.state.SegmentId
            };
    }

    constructor(
        private siteDataStore: SiteDataStore,
        private modalWindowService: ModalWindowService,
        private route: ActivatedRoute,
        private zoneEditorContract: ZoneEditorContract,
        private renderer: RendererService,
        public treeService: ZoneEditorTreeService,
        private styleSheetService: StyleSheetService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private scrollService: ScrollService) {
        super();
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes["iFrameUrl"]) {
            this.isInitialized = false;
        }
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.removeListeners();
    }

    onContentLoaded(): void {
        if (this.iframe) {
            this.frameLoaded.emit();
            if (!this.state.EditAllowed)
                return;

            const documentTitle = this.documentIFrameElement.title.toLowerCase();
            if (documentTitle.includes("404") || documentTitle.includes("cannot process page")) {
                this.removeListeners();
                const noRendererMessage = "<div class=\"-sf-txt-align-center\">Page cannot be displayed. Enable .NET Core renderer or contact your administrator.<br/><a href=\"https://www.progress.com/documentation/sitefinity-cms/setup-the-asp.net-core-renderer?ref=sf-renderer\" target=\"_blank\">How to set up .NET Core renderer?</a><br/><a href=\"https://www.progress.com/sitefinity-cms/net-core\" target=\"_blank\">What is .NET Core renderer?</a></div>";
                this.showNotificationMessage(noRendererMessage, NOTIFICATION_LOOKS.WARNING, true, true);
                return;
            }

            // if we encounter an internal server error we do nothing, just let the error be visible
            if (documentTitle.includes("internal server error")) {
                this.removeListeners();
                this.isInitialized = true;
                return;
            }

            let contract = this.iframe.nativeElement.contentWindow["rendererContract"] as RendererContract;
            if (!contract) {
                this.contractReadyListener = () => {
                    contract = this.iframe.nativeElement.contentWindow["rendererContract"] as RendererContract;
                    this.initialize(contract);
                };

                this.iframe.nativeElement.contentWindow.addEventListener(CONTRACT_READY_EVENT_NAME,  this.contractReadyListener);
                this.windowProvider.setTimeout(() => {
                    if (!this.isInitialized) {
                        this.showErrorMessage("No contract for communication with the zone editor was found on the rendered page.", true);
                    }

                    this.removeListeners();
                }, 5000);
            } else {
                this.initialize(contract);
            }
        }
    }

    initialize(contract: RendererContract) {
        try {

            this.renderer.initialize(contract);
            super.removeSubscriptions();
            this.subscribeEmptyLinks();
            this.loadResources();
            this.mirrorMainBodyClasses();
            this.subscribeToDocumentEvents();
            this.treeService.commonToolbarOptions = this.commonToolbarOptions;
            this.treeService.emptyMessageLabel = this.state.EmptyMessageLabel;
            this.treeService.addMessageLabel = this.state.AddMessageLabel;
            this.treeService.addMessageForEmptyScreenLabel = this.state.AddMessageForEmptyScreenLabel;
            this.treeService.emptyRootClasses = this.emptyRootCssClasses;

            const bodyElement = this.documentIFrameElement.body;
            this.rootContainer = this.treeService.initializeTree(bodyElement, bodyElement.parentElement, this.state);

            this.enhance(this.rootContainer);
            this.onLayoutChanged(!this.preserveNotifications);

            this.isInitialized = true;
        } catch (error) {
            const err = error || "Unhandled error occured";
            this.showErrorMessage(err.toString());
            this.removeListeners();
            return;
        }

        const page = this.documentIFrameElement.querySelector("body") as Element;
        const hasOrphans = page.hasAttribute(ATTR_ORPHANS);
        if (hasOrphans) {
            this.showNotificationMessage("Some of the widgets are placed outside the page template and will not be displayed on the public site.", NOTIFICATION_LOOKS.WARNING, false, true);
        }

        this.addSplitterEvents();
        this.prepareDragImages();
    }

    addSplitterEvents() {
        //remove old listeners
        SPLITTER_EVENTS.forEach(eventName => {
            this.iframe.nativeElement.contentDocument.removeEventListener(eventName, this, false);
        });

        //add new listeners
        SPLITTER_EVENTS.forEach(eventName => {
            this.iframe.nativeElement.contentDocument.addEventListener(eventName, this, false);
        });
    }

    handleEvent(event: PointerEvent) {
        const cloned = new PointerEvent(event.type, event);
        document.dispatchEvent(cloned);
    }

    prepareDragImages() {
        Object.keys(this.dragImagesSrcList).forEach((key) => {
            const img = this.documentProvider.createElement(NODE_NAMES.IMAGE_ELEMENT) as HTMLImageElement;
            img.src = "data:image/gif;base64," + this.dragImagesSrcList[key];
            this.dragImagesMap.set(key, img);
        });
    }

    focusWidget(componentId: string): void {
        const component = this.treeService.findComponent(this.rootContainer, componentId);
        if (component) {
            const iframeWindowScroll = this.iframe.nativeElement.contentWindow.pageYOffset;
            const topOffset = (iframeWindowScroll + component.domElement.getBoundingClientRect().top) - LABEL_OFFSET;

            this.scrollService.scrollToPoint(topOffset, undefined, this.iframe.nativeElement.contentWindow);
        }

        this.onWidgetClicked(null, component);
        component?.domElement.dispatchEvent(new Event("focus"));
    }

    reloadPersonalizedWidgets(segmentId: string, widgetSegmentId: string) {
        this.zoneEditorContract.getLazyComponents(this.dataItem, segmentId, widgetSegmentId).subscribe((response) => {
            this.siteDataStore.getValue().subscribe((siteData) => {
                const renderResults$ = response.Components.map((x) => {
                    return this.renderer.renderWidget({ siteId: siteData.Id, dataItem: this.dataItem, model: x }).pipe((map(y => {
                        return {
                            model: x,
                            renderResult: y
                        };
                    })));
                });

                forkJoin(renderResults$).subscribe((results) => {
                    results.forEach((result) => {
                        const component: ComponentModel = this.treeService.findComponent(this.rootContainer, result.model.Id);

                        const newComponent = this.treeService.refreshNode(component, response.WidgetState, result.renderResult, true);
                        this.enhance(newComponent);

                        this.loadScriptsAndDispatchEvent(result.renderResult, result.model, newComponent.domElement);
                    });
                });
            });
        });
    }

    editWidgetLabel(widgetId: string, label: string): void {
        const widgetIds = widgetId.split('_');
        const componentId = widgetIds[0];
        const containerId = widgetIds.length > 1 ? widgetIds[1] : undefined;
        const component = this.treeService.findComponent(this.rootContainer, componentId);

        if (component instanceof ComponentModel) {
            const itemData = this.route.snapshot.data[ITEM_DATA_KEY] as ItemData;
            const propertyLocalizationMode = itemData.entityData.culture ? component.iscontentwidget ? PropertyLocalizationType.CurrentTranslationOnly : PropertyLocalizationType.AllTranslations : PropertyLocalizationType.Default;
            const propertyValueGroup: PropertyValueGroup = {
                ComponentId: componentId,
                Properties: [],
                PropertyMetadata: [],
                PropertyLocalizationMode: propertyLocalizationMode.toString(),
                Caption: containerId ? component.title : label
            };

            if (component.name === PropertyEditorWidgets.SECTION) {
                const labelPropValue = {
                    Section: {
                        Label: containerId ? component.title : label
                    }
                };

                component.childContainers.forEach(column => {
                    if (containerId && containerId === column.placeholdername) {
                        labelPropValue[column.placeholdername] = {
                            Label: label
                        }
                    } else if (column.placeholderlabel) {
                        labelPropValue[column.placeholdername] = {
                            Label: column.placeholderlabel
                        }
                    }
                });

                propertyValueGroup.Properties.push({
                    Name: "Labels",
                    Value: JSON.stringify(labelPropValue)
                });
            }

            this.zoneEditorContract.setWidgetPropertyValues(itemData ? itemData.item : null, propertyValueGroup, this.state.SegmentId, component.widgetSegmentId).subscribe(() => {
                this.handleWidgetOperationExecution(component, {
                    Success: true,
                    SourceOperation: { Name:  EDIT_LABEL }
                });
            });
        }
    }

    addWidgetFromSidebar(parentWidgetId: string) {
        const widgetIds = parentWidgetId.split('_');
        const sectionId = widgetIds[0];
        const columnId = widgetIds.length > 1 ? widgetIds[1] : undefined;
        const section = this.treeService.findComponent(this.rootContainer, sectionId);
        let columnToAddInto: ContainerModel;
        if (columnId) {
            columnToAddInto = section.childContainers.find(x => x.placeholdername === columnId);
        } else {
            columnToAddInto = section.childContainers[0];
        }

        if (columnToAddInto.emptyWidget) {
            columnToAddInto.emptyWidget.instance.onAddButtonClick(new Event("click"));
        } else {
            const lastComponentInColumn = columnToAddInto.children[columnToAddInto.children.length - 1];
            const lastAddWidgetInColumn = this.treeService.getSibligAddWidgetElement(lastComponentInColumn, true);

            for (let index = 0; index < columnToAddInto.children.length; index++) {
                const widget = columnToAddInto.children[index];
                this.treeService.initAddWidgets(widget);

                const lastAddWidgetForCurrentWidget = widget.addWidgetComponents[widget.addWidgetComponents.length - 1];
                if (lastAddWidgetForCurrentWidget.location.nativeElement.isSameNode(lastAddWidgetInColumn)) {
                    (lastAddWidgetForCurrentWidget.instance as AddWidgetComponent).onAddButtonClick();
                    break;
                }
            }
        }
    }

    moveWidget(widgetId: string, parentWidgetId: string, index: number) {
        const component: ComponentModel = this.treeService.findComponent(this.rootContainer, widgetId);
        if (!component)
            return;

        let containerToAddInto: ContainerModel;
        if (parentWidgetId) {
            const widgetIds = parentWidgetId.split('_');
            const sectionId = widgetIds[0];
            const columnId = widgetIds.length > 1 ? widgetIds[1] : undefined;
            const section = this.treeService.findComponent(this.rootContainer, sectionId);
            if (columnId) {
                containerToAddInto = section.childContainers.find(x => x.placeholdername === columnId);
            } else {
                containerToAddInto = section.childContainers[0];
            }
        } else {
            containerToAddInto = this.rootContainer;
        }

        let siblingKey: string = null;
        let currentTarget: Element = null;


        if (containerToAddInto.children.length > 0) {
            if (index < containerToAddInto.children.length) {
                const nextComponent = containerToAddInto.children[index];
                currentTarget = this.treeService.getSibligAddWidgetElement(nextComponent);
                siblingKey = this.treeService.getPreviousSibling(currentTarget);
            } else {
                // add widget on last place in container
                const lastChildComponent = containerToAddInto.children[containerToAddInto.children.length - 1];
                currentTarget = this.treeService.getSibligAddWidgetElement(lastChildComponent, true);
                siblingKey = this.treeService.getPreviousSibling(currentTarget);
            }
        }

        this.zoneEditorContract.moveWidget(
            {
                dataItem: this.dataItem,
                widgetId,
                placeholderName: containerToAddInto.placeholdername,
                parentPlaceholderKey: containerToAddInto.parentComponent ? containerToAddInto.parentComponent.id : null,
                siblingKey,
                segmentId: this.state.SegmentId,
                properties: [],
                widgetName: null,
            }).pipe(this.catchErrorAndShowNotification()).subscribe(
                () => {
                    this.treeService.moveNode(component, containerToAddInto, currentTarget);
                    component.enhanced = false;
                    this.enhance(component);
                    this.onLayoutChanged();
                });
    }

    private enhance(parent: ContainerModel | ComponentModel) {
        this.treeService.iterateTree(parent, this.enhanceWidget.bind(this), this.enhanceContainer.bind(this));
    }

    private enhanceContainer(container: ContainerModel) {
        if (!container.enhanced) {
            if (!container.parentComponent) {
                //add class to distinguish static placegolders from section widgets
                container.domElement.classList.add(CLASS_STATIC_CONTAINER);
                //add hover to static placeholders
                container.addEventListener("mouseover", (ev: MouseEvent) => this.onMouseOver(ev, container));
                container.addEventListener("mouseout", (ev: MouseEvent) => this.onMouseOver(ev, container, false));
                container.addEventListener("mousemove", (ev: MouseEvent) => this.onMouseMove(ev, container));

                // Add narrow look. E.g. used in Forms, the content area should look smaller then in Page edit
                if (container.isRoot && this.useNarrowLook) {
                    container.domElement.classList.add(CLASS_MODIFIER_NARROWED, CLASS_MODIFIER_CENTER_HORIZONTAL);
                }
            }
            this.enhanceWithDrop(container, container, false);
        }
    }

    private enhanceWidget(component: ComponentModel): void {
        if (!component.enhanced) {
            component.removeListeners();
            component.domElement.setAttribute(ATTR_DRAGGABLE, component.moveAllowed.toString());
            if (component.moveAllowed) {
                component.addEventListener("dragstart", (ev: DragEvent) => this.drag(ev, component));
                component.addEventListener("dragend", (ev: DragEvent) => this.dragEnd(ev, component));
            }

            component.addEventListener("mousedown", (ev: MouseEvent)  => {
                if (!component.moveAllowed) {
                    ev.preventDefault();
                } else {
                    ev.stopImmediatePropagation();
                    ev.stopPropagation();
                }
            });

            component.addEventListener("mouseover", (ev: MouseEvent) => this.onMouseOver(ev, component));
            component.addEventListener("mouseout", (ev: MouseEvent) => this.onMouseOver(ev, component, false));
            component.addEventListener("mousemove", (ev: MouseEvent) => this.onMouseMove(ev, component));

            if (component.iscontentwidget) {
                this.setCssPositionAndDisplay(component);
            }

            component.addEventListener("click", (event) => this.onWidgetClicked(event, component));
            if (component.editAllowed) {
                if (component.quickEditMenu) {
                    component.quickEditMenu.instance.setCloseModalCallback((closingContext) => {
                        this.handleQuickEditOperation(component, closingContext);
                    });
                }
            }

            if (component.iscontentwidget) {
                this.enhanceWithDrop(component, component.parentContainer, component.iscontentwidget);
            }

            component.enhanced = true;
        }
    }

    private setCssPositionAndDisplay(component: ComponentModel) {
        const element = component.domElement;
        const computedStyle = this.windowProvider.getComputedStyle(element);
        if (computedStyle["position"] === "static") {
            element.classList.add(POSITION_RELATIVE_CLASS);
        }

        if (computedStyle["display"] === "inline" || computedStyle["display"] === "inline-block") {
            element.classList.add(CLASS_INLINE_BLOCK);

            // Handle SVG image representation as we wrap the inline elements inside inline-block
            // in that case if the SVG does not have width and height we need to set it's container width to 100%
            // in order to scale the SVG to parent width
            this.handleSvgImageStyles(component.domElement as HTMLElement);
        }
    }

    private handleSvgImageStyles(element: HTMLElement) {
        const images = element.nodeName === NODE_NAMES.IMAGE_ELEMENT ? [element] : element.querySelectorAll(NODE_NAMES.IMAGE_ELEMENT);

        if (!images) {
            return;
        }

        let modifiedWrapper: boolean = false;
        let count: number = 0;

        while (!modifiedWrapper && count < images.length) {
            const currentImage = images[count] as HTMLImageElement;

            let imgSource = currentImage.src;
            const queryIndex = imgSource.indexOf("?");
            const base64Svg = imgSource.indexOf(MIME_TYPES.SVG);
            const params = new URL(imgSource).searchParams;
            const formatValue = params.get(QUERY_PARAMS_EXTERNAL.Format);

            if (queryIndex > -1) {
                imgSource = imgSource.replace(imgSource.slice(queryIndex, imgSource.length), "");
            }

            // Check if it is standard link or it is base64 embedded file or checking if format query param exist with svg value
            const isSvg = imgSource.endsWith(".svg") || base64Svg > -1 || formatValue === EXTENSIONS.SVG;
            const shouldScale = currentImage.clientWidth === 0 && currentImage.clientHeight === 0;

            if (isSvg && shouldScale) {
                currentImage.closest(`[${ATTR_COMPONENT_ID}]`).classList.add(FULL_WIDTH_CLASS);
                modifiedWrapper = true;
            }

            count++;
        }
    }

    private enhanceWithDrop(parent: ComponentModel | ContainerModel, container: ContainerModel, isContentWidget: boolean) {
        parent.addEventListener("drop", (ev: DragEvent) => this.drop(ev, container, isContentWidget, isContentWidget));
        parent.addEventListener("dragover", (ev: DragEvent) => this.dragOver(ev, parent, isContentWidget));
        parent.addEventListener("dragleave", (ev) => this.dragLeave(ev, isContentWidget));
    }

    private handleQuickEditOperation(component: ComponentModel, closingContext: OperationItemResult) {
        if (closingContext.SourceOperation.Name !== PropertyEditorOperations.CANCEL) {
            this.handleWidgetOperationExecution(component, {
                Success: true,
                SourceOperation: { Name:  QUICK_EDIT }
            });
        } else {
            this.treeService.removeQuickEditMenu(component);
        }
    }

    private handleWidgetOperationExecution(component: ComponentModel, result: WidgetOperationResult) {
        const personalizationAction = this.handlePersonlalizationChange(component, result);
        if (!personalizationAction.handleAction)
            return;

        // if the command perfoms a delete, then special handling is in order
        if (result.SourceOperation.PerformsDelete && result.Success && !personalizationAction.isDeletingPersonalization) {
            this.treeService.removeNode(component);
            this.onLayoutChanged();
        } else if (result.Link) {
            this.windowProvider.open(result.Link, "_self");
        } else {
            // if we execute any other operation than delete, then we need to rerender the widget
            // as we do not know if the state of the widget will not change after the operation is executed

            this.siteDataStore.getValue().subscribe((siteData) => {
                let hideNotification = true;
                if (result.Message) {
                    this.notificationService.publishBasicNotification({
                        message: result.Message,
                        look: result.Type.toLowerCase(),
                        filterParam: ZONE_EDITOR_NOTIFICATION_FILTER
                    });

                    hideNotification = false;
                }

                // do not rerender on copy settings
                if (result.SkipRerender) {
                    return;
                }

                if (result.SourceOperation.Name === WIDGET_OPERATION_NAME_DUPLICATE) {
                    this.getModelAndRender(siteData, this.dataItem, result.State.Key, personalizationAction.widgetSegmentId).subscribe((modelAndRenderResult) => {
                        const duplicatedComponent = this.treeService.addNodeFromHtml(component.parentContainer, modelAndRenderResult.model.WidgetState, modelAndRenderResult.renderResult, component.addWidgetComponents[component.addWidgetComponents.length - 1].location.nativeElement);
                        this.enhance(duplicatedComponent);
                        this.onLayoutChanged(hideNotification);
                        this.loadScriptsAndDispatchEvent(modelAndRenderResult.renderResult, modelAndRenderResult.model, duplicatedComponent.domElement);
                    });
                    return;
                }

                this.getModelAndRender(siteData, this.dataItem, component.id, personalizationAction.widgetSegmentId).subscribe((modelAndRenderResult) => {
                    const newComponent = this.treeService.refreshNode(component, modelAndRenderResult.model.WidgetState, modelAndRenderResult.renderResult, true);
                    this.enhance(newComponent);
                    if (result.SourceOperation.KeepFocus) {
                        this.onWidgetClicked(null, newComponent);
                    } else {
                        this.onClearWidget.emit();
                    }

                    if (result.SourceOperation.Name !== EDIT_LABEL) {
                        // During quick edit the edit menu is inline and we see blinking in the sidebar if updated.
                        // For now there is no case where the sidebar structure can be changed from quick edit menu.
                        this.onLayoutChanged(hideNotification);
                    }

                    this.loadScriptsAndDispatchEvent(modelAndRenderResult.renderResult, modelAndRenderResult.model, newComponent.domElement);
                });
            });
        }
    }

    private handlePersonlalizationChange(component: ComponentModel, result: WidgetOperationResult): { widgetSegmentId: string, handleAction: boolean, isDeletingPersonalization: boolean } {
        let widgetSegmentId: string = null;
        let handleAction = true;
        let isDeletingPersonalization = false;
        let widgetSegmentParameter = null;
        if (result.SourceOperation.ContextParameters) {
            widgetSegmentParameter = result.SourceOperation.ContextParameters.find(x => x.Name === QUERY_PARAMS.WIDGET_SEGMENT_ID);
            if (widgetSegmentParameter) {
                if (result.SourceOperation.PerformsDelete) {
                    isDeletingPersonalization = true;
                    widgetSegmentId = null;
                    widgetSegmentParameter = null;
                } else {
                    widgetSegmentId = widgetSegmentParameter.Value;
                }
            }
        }

        // when parameter is entered through the form
        if (!widgetSegmentParameter && result.AvailableActions && result.AvailableActions.length === 1)
            widgetSegmentId = result.AvailableActions[0];

        if (component.widgetSegmentId && widgetSegmentId && component.widgetSegmentId === widgetSegmentId && !isDeletingPersonalization) {
            handleAction = false;
        }

        if (!widgetSegmentId)
            widgetSegmentId = component.widgetSegmentId;

        return {
            widgetSegmentId,
            handleAction,
            isDeletingPersonalization
        };
    }

    private getModelAndRender(siteData: SiteData, dataItem: DataItem, componentId: string, componentSegmentId: string): Observable<{ renderResult: RenderResult, model: WidgetModelWithState }> {
        const ret$ = new Subject<{ renderResult: RenderResult, model: WidgetModelWithState }>();
        this.zoneEditorContract.getHierarchicalWidgetModel(dataItem, componentId, this.state.SegmentId, componentSegmentId).pipe(this.catchErrorAndShowNotification()).subscribe((model) => {
            this.renderer.renderWidget({ siteId: siteData.Id, dataItem: dataItem, model }).pipe(this.catchErrorAndShowNotification()).subscribe((renderResult) => {
                ret$.next({renderResult: renderResult, model});
            });
        });

        return ret$.asObservable();
    }

    private onLayoutChanged(hideNotification: boolean = true) {
        if (!this.rootContainer.hasAnyOrphans() && hideNotification) {
            this.hideNotificationMessage();
        }

        this.layoutChanged.next(this.rootContainer);
    }

    private onMouseOver(event: MouseEvent, component: ComponentModel | ContainerModel, isMouseIn: boolean = true) {
        event.stopPropagation();

        let focusedClassTarget = component.domElement;

        if (this.treeService.isInlineElement(focusedClassTarget) && this.treeService.isFakeOrAddWidget(event.target as Element)) {
            focusedClassTarget = focusedClassTarget.parentElement.closest(".sf-zone-widget") || focusedClassTarget.parentElement;
        }

        isMouseIn ? focusedClassTarget.classList.add(CLASS_HOVERED_WIDGET) : focusedClassTarget.classList.remove(CLASS_HOVERED_WIDGET);

        if (component instanceof ComponentModel) {
            this.initComponent(component);
        }

        if (!isMouseIn) {
            this.deactivateAddWidget(null, CLASS_VISIBLE_MODIFIER, `${NODE_NAME_ADD_WIDGET}.${CLASS_VISIBLE_MODIFIER}`);
        }
    }

    private onMouseMove(event: MouseEvent, component: ContainerModel | ComponentModel) {
        event.stopPropagation();
        const element = event.target as HTMLElement;
        const widget = (event.target as HTMLElement).closest(`.${CLASS_ZONE_WIDGET}`);

        if (this.canShowAddWidget(element, component)) {
            this.activatePreviousOrNextAddWidget(widget, event.clientY, false, component);
        }
    }

    private initComponent(component: ComponentModel) {
        this.treeService.initAddWidgets(component);
        this.treeService.addLabelElement(component);
    }

    private initComponentForEditing(component: ComponentModel): Subject<Operation[]> {
        let loadOperations: Subject<Operation[]>;
        this.initComponent(component);
        if (component.editAllowed) {
            loadOperations = this.initOperations(component);
            this.initToolbarSubscriptions(component);
        }

        return loadOperations;
    }

    private initOperations(component: ComponentModel) {
        let loadOperations: Subject<Operation[]>;

        if (!component.operationsInitialized) {
            this.treeService.addInlineToolbar(component);
            loadOperations = new ReplaySubject<Operation[]>(1);
            loadOperations.pipe(catchError((err) => {
                component.operationsInitialized = false;
                return throwError(err);
            }),
            this.catchErrorAndShowNotification()).subscribe((operations) => {
                component.inlineToolbarComponent.instance.loadOperations(operations);
                component.operationsInitialized = true;
            });

        } else {
            component.inlineToolbarComponent.instance.refreshOperations();
        }

        return loadOperations;
    }

    private initToolbarSubscriptions(component: ComponentModel) {
        if (component.inlineToolbarComponent) {
            const onOperationExecuted = component.inlineToolbarComponent.instance.onOperationExecuted;
            if (!component.toolbarSubscription) {
                component.toolbarSubscription = onOperationExecuted.subscribe((result: WidgetOperationResult) => {
                    this.handleWidgetOperationExecution(component, result);
                    this.onComponentOperationExecuted.emit({ component, result });
                });
            }

            if (!component.focusToolbarSubscription) {
                component.focusToolbarSubscription = component.inlineToolbarComponent.instance.onFocusOut.subscribe(() => {
                    if (component.quickEditMenu) {
                        this.widgetWithOpenedQuickEditMenu = component;
                    } else {
                        component.domElement.classList.remove(CLASS_FOCUSED_WIDGET);
                        this.onClearWidget.emit();
                    }

                    component.domElement.classList.remove(CLASS_VISIBLE_TOOLBAR);
                });
            }
        }
    }

    private onWidgetClicked(event: Event, component?: ComponentModel): void {
        if (event) {
            event.stopPropagation();
            event.preventDefault();
            this.dispatchClickToRootDocument(event);
        }

        this.treeService.removeQuickEditMenu(this.widgetWithOpenedQuickEditMenu);

        const selectedElements = this.documentIFrameElement.querySelectorAll(`.${CLASS_FOCUSED_WIDGET}`);
        selectedElements.forEach(element => {
            element.classList.remove(CLASS_FOCUSED_WIDGET);
            element.classList.remove(CLASS_VISIBLE_TOOLBAR);
        });

        let loadOperations: Subject<Operation[]>;
        if (component) {
            component?.domElement.classList.add(CLASS_FOCUSED_WIDGET);
            component?.domElement.classList.add(CLASS_VISIBLE_TOOLBAR);
            loadOperations = this.initComponentForEditing(component);
        }

        this.onComponentClicked.emit({
            widgetId: component?.id,
            segmentId: this.state.SegmentId,
            widgetSegmentId: component?.widgetSegmentId,
            dataItem: this.dataItem,
            ready: loadOperations
        });
    }

    private drag(ev: DragEvent, component: ComponentModel): void {
        ev.stopPropagation();

        // do not allow dragging if currently editing through the quick menu
        if (component.quickEditMenu) {
            ev.preventDefault();
            ev.stopImmediatePropagation();
            return;
        }

        if (this.currentlyDraggedId !== component.id) {
            this.currentlyDraggedId = component.id;
            this.currentlyDraggedElementTitle.next(component.title);
        }

        const ready = new Subject<void>();
        ready.pipe(catchError(err => {
            ev.preventDefault();
            return throwError(err);
        }), this.catchErrorAndShowNotification()).subscribe();

        this.editWidgetClicked.emit({ ready });
        const dragImage = this.dragImagesMap.get(component.name) ? this.dragImagesMap.get(component.name) : this.dragImagesMap.get("SitefinityCustom");
        ev.dataTransfer.effectAllowed = "move";
        ev.dataTransfer.setDragImage(dragImage, 0, 0);
        setTimeout(() => component.domElement.classList.add(CLASS_HIDDEN), 0);

        const parentContainer = component.parentContainer;
        //Add empty widget to container during drag if the widget is the only child of its parent
        if (parentContainer.children.length === 1 &&
            parentContainer.childContainers.length === 0 &&
            !parentContainer.emptyWidget) {
                this.treeService.addEmptyWidget(component.parentContainer);
        }
    }

    private dragEnd(ev: DragEvent, component: ComponentModel) {
        //remove dragged class
        if (!this.waitForInsert) {
            //remove empty component from parent
            if (component.parentContainer.emptyWidget) {
                this.treeService.removeEmptyWidget(component.parentContainer);
            }
            //remove class for hiding currently dragged widget
            setTimeout(() => {
                component.domElement.classList.remove(CLASS_HIDDEN);
            }, 0);
            //deactivate any active addWidget
            this.deactivateAddWidget();
            //we don't need to preserve the activated add widget position after drag end
            this.activatedAddWidgetPosition = null;
            this.currentlyDraggedId = null;
        }
    }

    private dragOver(ev: DragEvent, parent: ComponentModel | ContainerModel, isContentWidget: boolean): void {
        ev.preventDefault();
        ev.stopPropagation();

        if (!this.currentlyDraggedId)
            return;

        const currentTarget = ev.currentTarget as Element;

        if (isContentWidget) {
            const previousInlineComponent = this.treeService.getPreviousInlineComponent(parent);
            this.initComponent(parent as ComponentModel);

            // Handle the scenario where there are 2 inline elements one after another and we try to drop the dragged element between them
            // By design when hovered the second inline element at the top we need to show the drop area on the first inline element and so we need to init its add widgets to do so
            if (previousInlineComponent) {
                this.treeService.initAddWidgets(previousInlineComponent);
            }
            this.activatePreviousOrNextAddWidget(currentTarget, ev.clientY);
        } else {
            currentTarget.classList.add(CLASS_DRAG_OVER);
        }
    }

    private dragLeave(ev: Event, isContentWidget: boolean): void {
        ev.preventDefault();
        ev.stopPropagation();
        const currentTarget = ev.currentTarget as Element;

        if (currentTarget && currentTarget.classList.contains(CLASS_DRAG_OVER)) {
            currentTarget.classList.remove(CLASS_DRAG_OVER);
        }

        // Deactivate add widget when moving from one container to another (for dragging over content widgets)
        if (!isContentWidget) {
            this.deactivateAddWidget();
        }

        //shouldn't preserve activatedAddWidgetPosition for this widget  after leaving it
        this.activatedAddWidgetPosition = null;
    }

    private activatePreviousOrNextAddWidget(element: Element, dragPosition: number, isDrag: boolean = true, component?: ContainerModel | ComponentModel) {
        const elementCoordinates = element.getBoundingClientRect();
        // Adding 10% offset in the middle of the element in order not to flicker the elements when cursor is just at the middle of narrowed element
        const percentageOffset = ((elementCoordinates.height / 100) * 10);
        const beforeElementPosition = elementCoordinates.top + Math.round((elementCoordinates.height / 2) - percentageOffset);
        const afterElementPosition = elementCoordinates.top + Math.round((elementCoordinates.height / 2) + percentageOffset);

        let addWidgetPosition = null;
        if (dragPosition <= beforeElementPosition) {
            addWidgetPosition = ActivatedAddWidgetPosition.Before;
        } else if (dragPosition >= afterElementPosition) {
            addWidgetPosition = ActivatedAddWidgetPosition.After;
        }
        if (addWidgetPosition !== null) {
            this.togglePreviousOrNextAddWidget(element as HTMLElement, addWidgetPosition, isDrag, component);
        }
    }

    private canShowAddWidget(element: HTMLElement, component: ContainerModel | ComponentModel): boolean {
        let canShow = false;
        const widget = element.closest(`.${CLASS_ZONE_WIDGET}`);

        if (widget &&
            !this.treeService.isInlineToolbar(element) &&
            !this.treeService.isAddWidget(element) &&
            !this.treeService.isEmtpyWidget(element) &&
            this.treeService.isZoneWidget(component.domElement as HTMLElement)) {
                canShow = true;
        }

        return canShow;
    }

    private togglePreviousOrNextAddWidget(element: HTMLElement, activatedAddWidgetPosition: ActivatedAddWidgetPosition, isDrag: boolean = true, component?: ContainerModel | ComponentModel) {
        //check if add widget to activate has changed
        if (this.activatedAddWidgetPosition === activatedAddWidgetPosition) {
            return;
        }

        let addWidgetToActivate;
        let classToAdd;

        if (!isDrag) {
            this.deactivateAddWidget(null, CLASS_VISIBLE_MODIFIER, `${NODE_NAME_ADD_WIDGET}.${CLASS_VISIBLE_MODIFIER}`);
            addWidgetToActivate = this.treeService.getSibligAddWidgetElement(component, !!activatedAddWidgetPosition);
            classToAdd = CLASS_VISIBLE_MODIFIER;
        } else {
            this.deactivateAddWidget();
            //get the add widget to activate
            addWidgetToActivate = activatedAddWidgetPosition === ActivatedAddWidgetPosition.Before ?
            this.getActiveAddWidgetDrop(element, true) : this.getActiveAddWidgetDrop(element, false);
            //change last active add widget position
            this.activatedAddWidgetPosition = activatedAddWidgetPosition;
        }

        //activate add widget
        this.activateAddWidget(addWidgetToActivate, classToAdd);
    }

    private getActiveAddWidgetDrop(element: HTMLElement, previous: boolean): HTMLElement {
        let currentElement;

        if (previous) {
            // When we start to drag an inline element it is not removed from the DOM and if tried to place it before the next siblig we need to skip the currently dragged one
            const isDraggingInlineElement = this.treeService.isInlineElement(element.previousElementSibling) && element.previousElementSibling.classList.contains(CLASS_HIDDEN);
            const previousElement = isDraggingInlineElement ? element.previousElementSibling.previousElementSibling : element.previousElementSibling;
            currentElement = previousElement && this.treeService.isInlineElement(previousElement) ? previousElement.lastElementChild : previousElement;
        } else {
            currentElement = this.treeService.isInlineElement(element) ? element.lastElementChild : element.nextElementSibling;
        }

        return currentElement as HTMLElement;
    }

    private activateAddWidget(element: HTMLElement, classToAdd: string = CLASS_DRAG_OVER) {
        if (element) {
            element.classList.add(classToAdd);
        }
    }

    private deactivateAddWidget(element?: HTMLElement, classToRemove?: string, selector?: string) {
        classToRemove = classToRemove || CLASS_DRAG_OVER;
        selector = selector || `.${classToRemove}`;
        // if the visible add widget is not this add widget, remove CLASS_DRAG_OVER
        if (element) {
            element.classList.remove(classToRemove);
        } else {
            this.documentIFrameElement?.querySelectorAll(selector).forEach(el => {
                el.classList.remove(classToRemove);
            });
        }
    }

    private drop(ev: DragEvent, newParentContainer: ContainerModel, isAddWidgetElement: boolean, isDroppingOnContentWidget: boolean = false): void {

        this.waitForInsert = true;
        ev.preventDefault();
        ev.stopPropagation();
        let currentTarget: Element;

        //If we're dropping over a content widget, currentTarget is the previous or the next add widget of the content widget
        if (isDroppingOnContentWidget) {
            currentTarget = this.activatedAddWidgetPosition === ActivatedAddWidgetPosition.Before ? (ev.currentTarget as HTMLElement).previousElementSibling
                : (ev.currentTarget as HTMLElement).nextElementSibling;
        } else {
            currentTarget = ev.currentTarget as Element;
        }

        if (currentTarget && currentTarget.classList.contains(CLASS_DRAG_OVER)) {
            currentTarget.classList.remove(CLASS_DRAG_OVER);

            //remove -sf-dragged-over from parent container
            if (currentTarget && currentTarget.nodeName === NODE_NAME_ADD_WIDGET && currentTarget.parentElement && currentTarget.parentElement.classList.contains(CLASS_DRAG_OVER)) {
                currentTarget.parentElement.classList.remove(CLASS_DRAG_OVER);
            }
        }

        const dragEndFunc = () => {
            this.waitForInsert = false;
            this.dragEnd(ev, component);
        };

        const component: ComponentModel = this.treeService.findComponent(this.rootContainer, this.currentlyDraggedId);
        if (!component)
            return;

        if (component.domElement.contains(currentTarget)) {
            dragEndFunc();
            return;
        }

        const siblingKey = isAddWidgetElement ? this.treeService.getPreviousSibling(currentTarget) : null;

        this.zoneEditorContract.moveWidget(
            {
                dataItem: this.dataItem,
                widgetId: component.id,
                widgetName: null,
                placeholderName: newParentContainer.placeholdername,
                parentPlaceholderKey: newParentContainer.parentComponent ? newParentContainer.parentComponent.id : null,
                siblingKey: siblingKey,
                properties: [],
                segmentId: this.state.SegmentId
            }).pipe(this.catchErrorAndShowNotification(null, dragEndFunc)).subscribe(
                () => {
                    const addWidgetElement = isAddWidgetElement ? currentTarget : null;

                    this.treeService.moveNode(component, newParentContainer, addWidgetElement);

                    component.enhanced = false;
                    this.enhance(component);
                    dragEndFunc();

                    this.onLayoutChanged();
            });
    }

    private subscribeEmptyLinks() {
        const emptyAddedSubscription = this.treeService.emptyContainerAdded.subscribe((args: EmptyContainerAddedArgs) => {
            args.container.emptyWidget.instance.onAddClick.subscribe(() => {
                const initialTabName = this.getInitialTabName(args.container.parentComponent);
                this.openWidgetSelector(args.container, initialTabName, args.container.emptyWidget);
            });
        });
        this.registerSubscription(emptyAddedSubscription);

        const widgetAddedSubscription = this.treeService.widgetAdded.subscribe((args: WidgetAddedArgs) => {
            const emptyWidgetElement = args.component.domElement.querySelector(NODE_NAME_EMPTY_WIDGET);
            const emptyLink = emptyWidgetElement ? emptyWidgetElement.querySelector(`[${ATTR_EMPTY_LINK}='true']`) : null;
            if (emptyLink && args.component.emptyiconaction !== EMPTY_WIDGET_ACTION.NONE && !args.component.isContainer) {
                emptyLink.addEventListener("click", (emptyLinkEvent: Event) => {
                    if (args.component.hasChildren) {
                        return;
                    }

                    emptyLinkEvent.preventDefault();
                    emptyLinkEvent.stopPropagation();

                    this.initComponentForEditing(args.component);
                    const ready = new ReplaySubject<void>(1);
                    this.editWidgetClicked.emit({ ready });

                    ready.pipe(this.catchErrorAndShowNotification()).subscribe(() => {
                        const fakeActionButton = new ActionButton("Edit", "edit");
                        fakeActionButton.sourceOperation = { Name: "edit", Category: { Name: "General" } };
                        this.treeService.addInlineToolbar(args.component);
                        args.component.inlineToolbarComponent.instance.onActionButtonClicked(fakeActionButton);
                    });
                });
            }
        });
        this.registerSubscription(widgetAddedSubscription);

        const addWidgetSubscription = this.treeService.addWidgetAdded.subscribe((addWidgetArgs: AddWidgetAddedArgs) => {
            const addWidget = addWidgetArgs.addWidget;
            const component = addWidgetArgs.component;
            addWidget.instance.addWidgetDraggedOverLabel = this.currentlyDraggedElementTitle.asObservable();
            addWidget.location.nativeElement.addEventListener("drop", (ev: DragEvent) => this.drop(ev, component.parentContainer, true));

            addWidget.location.nativeElement.addEventListener("dragover", (ev: DragEvent) => this.onAddWidgetDragOver(ev));

            addWidget.location.nativeElement.addEventListener("dragleave", (ev: DragEvent) => this.onAddWidgetDragLeave(ev));
            addWidget.instance.onAddClick.subscribe(() => {
                const initialTabName = this.getInitialTabName(component.parentComponent);
                this.openWidgetSelector(component.parentContainer, initialTabName, addWidget);
            });
        });
        this.registerSubscription(addWidgetSubscription);
    }

    private loadResources() {
        const zoneEditorStyleAttribute: KeyValue<string, string>[] = [{
            key: "data-sfstyles",
            value: "zone-edit"
        }];

        // Check if there are already inserted files
        const insertedFiles = this.documentIFrameElement.querySelector(`[data-sfstyles='zone-edit']`);

        if (!insertedFiles) {
            this.styleSheetService.insertStyleTag(ZONE_EDITOR_STYLESHEET, this.documentIFrameElement, zoneEditorStyleAttribute);
        }
    }

    private mirrorMainBodyClasses() {
        const activeContrast = document.body.classList.contains(CLASS_CONTRAST);

        this.documentIFrameElement.body.classList.toggle(CLASS_CONTRAST, activeContrast);
    }

    private onAddWidgetDragOver(ev: DragEvent) {
        const currentAddWidget = ev.currentTarget as HTMLElement;

        if (!this.currentlyDraggedId)
            return;

        if (!currentAddWidget.classList.contains(CLASS_DRAG_OVER)) {
            //if the visible add widget is not this add widget, remove CLASS_DRAG_OVER
            this.deactivateAddWidget();
            //activate current add widget
            this.activateAddWidget(currentAddWidget);
        }
    }

    private onAddWidgetDragLeave(ev: DragEvent) {
        const currentAddWidget = ev.currentTarget as HTMLElement;
        if (currentAddWidget && currentAddWidget.classList.contains(CLASS_DRAG_OVER)) {
            this.deactivateAddWidget(currentAddWidget);
        }
    }

    private openWidgetSelector(parentContainer: ContainerModel, initialTabName: string, openElement: ComponentRef<EmptyWidgetComponent | AddWidgetComponent>) {
        const ready = new ReplaySubject<void>(1);
        ready.pipe(this.catchErrorAndShowNotification()).subscribe(() => {
            this.renderer.getCategories({ toolbox: this.state.Toolbox }).pipe(this.catchErrorAndShowNotification()).subscribe((categoriesResponse) => {
                const settings: ModalSelectorSettings<WidgetItem> = {
                    heading: {
                        title: "Select widget"
                    },
                    tabsConfig: {
                        initialTabName: initialTabName,
                        tabs: categoriesResponse.map(c => {return {name: c}; })
                    },
                    doneCallback: (result => {
                        if (result.data) {
                            const widgetItem = result.data as WidgetItem;
                            this.insertSingleRendererWidget(openElement, parentContainer, widgetItem);
                        }
                    }),
                    data: {
                        singleSelectionText: "Select widget",
                        load: (context: LoadContext) => {
                            return this.getAndMapWidgetResponse(context);
                        }
                    },
                    window: this.iframe.nativeElement.contentWindow
                };

                this.modalWindowService.openModalSelector(this.route, settings);
            });
        });

        this.addWidgetClicked.emit({ ready });
    }

    private getAndMapWidgetResponse(context: LoadContext): Observable<LoadDataResult<WidgetItem>> {
        const sitefinityWidgets$ = this.zoneEditorContract.getWidgets({ dataItem: this.dataItem, category: context.tab.name, search: context.searchVal, skip: context.skip, take: DEFAULT_TAKE, toolbox: this.state.Toolbox });
        const rendererWidgets$ = this.renderer.getWidgets({ dataItem: this.dataItem, category: context.tab.name, search: context.searchVal, skip: context.skip, take: DEFAULT_TAKE, toolbox: this.state.Toolbox });

        const mapperFunc = (items: TotalCountResult<Array<WidgetSection>>) => {
            const mappedItems = items.dataItems.map(section => {
                const mappedWidgets = section.widgets.map(x => {
                    return <SelectorItem<WidgetItem>>{
                        dataItem: x,
                        selectButtonText: (x.name === PropertyEditorWidgets.SECTION || x.section === PropertyEditorSections.PRESETS) ? "Select section" : "Select widget",
                        componentData: {
                            type: WidgetPreviewComponent,
                            properties: {
                                text: x.title,
                                name: x.name,
                                thumbnailUrl: x.thumbnailUrl,
                                addWidgetTitle: x.addWidgetTitle,
                                addWidgetName: x.addWidgetName,
                                initialProperties: x.initialProperties
                            }
                        }
                    };
                });
                return <SelectorGroup<WidgetItem>> {
                    title: section.title,
                    items: mappedWidgets
                };
            });

            return <LoadDataResult<WidgetItem>> {
                dataItems: mappedItems,
                totalCount: items.totalCount
            };
        };

        return combineLatest([sitefinityWidgets$, rendererWidgets$]).pipe(this.catchErrorAndShowNotification(), map((data) => {
            const sitefinityWidgets = mapperFunc(data[0]);
            const rendererWidgets = mapperFunc(data[1]);

            rendererWidgets.dataItems.push(...sitefinityWidgets.dataItems);
            rendererWidgets.dataItems = rendererWidgets.dataItems.filter(x => x.items.length > 0);

            rendererWidgets.totalCount += sitefinityWidgets.totalCount;

            return rendererWidgets;
        }));
    }

    private insertSingleRendererWidget(openElement: ComponentRef<AddWidgetComponent | EmptyWidgetComponent>, parentContainer: ContainerModel, widgetItem: WidgetItem) {
        const placeholderName = parentContainer.placeholdername;
        const parentPlaceholderKey = parentContainer.parentComponent ? parentContainer.parentComponent.id : null;
        const siblingKey = this.treeService.getPreviousSibling(openElement.location.nativeElement);
        const properties = (widgetItem.initialProperties || []).map(x => <PropertyData>{ Name: x.name, Value: x.value });

        this.zoneEditorContract.addWidget({
            widgetId: null,
            dataItem: this.dataItem,
            widgetName: widgetItem.name,
            placeholderName,
            parentPlaceholderKey,
            siblingKey,
            properties,
            segmentId: this.state.SegmentId
        }).pipe(this.catchErrorAndShowNotification()).subscribe((addWidgetResponse: WidgetModelWithState) => {
            this.siteDataStore.getValue().subscribe((siteData) => {
                properties.forEach((prop) => {
                    if (addWidgetResponse.Properties && !addWidgetResponse.Properties.hasOwnProperty(prop.Name))
                        addWidgetResponse.Properties[prop.Name] = prop.Value;
                });

                this.renderer.renderWidget({ siteId: siteData.Id, dataItem: this.dataItem, model: addWidgetResponse }).pipe(this.catchErrorAndShowNotification()).subscribe((renderResult) => {
                    const component = this.treeService.addNodeFromHtml(parentContainer, addWidgetResponse.WidgetState, renderResult, openElement.location.nativeElement);

                    this.onLayoutChanged();
                    this.loadScriptsAndDispatchEvent(renderResult, addWidgetResponse, component.domElement);
                    this.enhance(component);
                });
            });
        });
    }

    private catchErrorAndShowNotification<T, O>(showGenericError = false, callBack: () => void = null): OperatorFunction<T, T | ObservedValueOf<O>> {
        const filter = showGenericError ? null : ZONE_EDITOR_NOTIFICATION_FILTER;
        if (callBack) {
            callBack();
        }
        return this.notificationService.catchErrorAndShowNotification(filter);
    }

    private showErrorMessage(message: string, messageAlwaysVisible = false) {
        this.showNotificationMessage(message, NOTIFICATION_LOOKS.ERROR, false, messageAlwaysVisible);
    }

    private showNotificationMessage(message: string, look: string, hideContent: boolean = true, messageAlwaysVisible = false) {
        const basicNotificationInfo: BasicNotificationInfo = {
            message,
            look,
            filterParam: ZONE_EDITOR_NOTIFICATION_FILTER
        };

        if (messageAlwaysVisible) {
            basicNotificationInfo.duration = null;
        }

        this.notificationService.publishBasicNotification(basicNotificationInfo);

        if (hideContent) {
            this.iframe.nativeElement.contentDocument.body.innerHTML = "";
        }
    }

    private hideNotificationMessage() {
        this.notificationService.close();
    }

    private subscribeToDocumentEvents() {
        // When events are cloned container document will be notified when event is triggered inside the iframe document.
        // For example click is fired from inside the iframe.

        this.removeListeners();

        this.documentInsideIframeMouseClickListener = ((event: MouseEvent) => {
            this.dispatchClickToRootDocument(event);
        }).bind(this);

        this.documentIFrameElement.addEventListener("click", this.documentInsideIframeMouseClickListener);

        this.outsideWindowMouseClickListener = ((event: MouseEvent) => {
            this.treeService.iterateTree(this.rootContainer, (model) => {
                if (model.inlineToolbarComponent)
                    model.inlineToolbarComponent.instance.focusOut();
            }, null);
        }).bind(this);

        this.iframe.nativeElement.contentWindow.parent.addEventListener("click", this.outsideWindowMouseClickListener);
    }

    private removeListeners() {
        if (this.iframe && this.iframe.nativeElement.contentWindow) {
            if (this.documentInsideIframeMouseClickListener)
                this.iframe.nativeElement.contentWindow.document.removeEventListener("click", this.documentInsideIframeMouseClickListener);

            if (this.outsideWindowMouseClickListener)
                this.iframe.nativeElement.contentWindow.parent.removeEventListener("click", this.outsideWindowMouseClickListener);

            if (this.contractReadyListener)
                this.iframe.nativeElement.contentWindow.removeEventListener(CONTRACT_READY_EVENT_NAME, this.contractReadyListener);
        }
    }

    private dispatchClickToRootDocument(event: Event) {
        let filter = false;
        let htmlElement = event.target as HTMLElement;
        while (htmlElement && htmlElement.parentElement) {
            if (htmlElement.nodeName === NODE_NAME_INLINE_TOOLBAR) {
                filter = true;
                break;
            }

            htmlElement = htmlElement.parentElement;
        }

        if (filter)
            return;

        const cloned = new MouseEvent(event.type, event);
        this.documentProvider.dispatchEvent(cloned);
    }

    private loadScriptsAndDispatchEvent(renderResult: RenderResult, model: WidgetModel, newlyInsertedElement: Element) {
        let counter = renderResult.scripts.length;
        const fireEvent = () => {
            if (--counter === 0) {
                const event = new CustomEvent("widgetLoaded", {
                    detail: <WidgetLoadedArgs> {
                        element: newlyInsertedElement,
                        model
                    }
                });
                this.documentIFrameElement.dispatchEvent(event);
            }
        };

        if (renderResult.scripts.length > 0) {
            renderResult.scripts.forEach((script) => {
                let scriptElement = this.documentIFrameElement.getElementById(script.id) as HTMLScriptElement;
                if (scriptElement) {
                    fireEvent();
                    return;
                }

                scriptElement = this.documentIFrameElement.createElement("script");
                scriptElement.src = script.src;
                scriptElement.id = script.id;
                scriptElement.onload = fireEvent;
                scriptElement.onerror = fireEvent;

                this.documentIFrameElement.body.appendChild(scriptElement);
            });
        } else {
            counter = 1;
            fireEvent();
        }
    }

    private getInitialTabName(parentComponent: ComponentModel): string {
        const initialTabName = !parentComponent ? this.initialWidgetSelectorTabName : stringConstants.EMPTY_STRING;

        return initialTabName;
    }
}

export interface WidgetLoadedArgs {
    element: HTMLElement,
    model: WidgetModel
}

export interface AddWidgetArgs {
    ready: Subject<void>;
}

export class NotificationInfo {
    type: string;
    message: string;
    get look(): string {
        return this.type + " fixed";
    }
}
