import { ModalWindowService, DialogData, DEFAULT_URL_KEY, ClosingContext, ClosingContextType } from "../../../../shared/services/modal-window.service";
import { ExecuteOnceInBulkCommand } from "../../../../shared/commands/command";
import { Observable, ReplaySubject } from "rxjs";
import { ExecutionContext } from "../../../../shared/commands/execution-context";
import { ChangeTemplateComponent, ChangeMode } from "../change-template/change-template.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../shared/services/notification/notification.service";
import { NOTIFICATION_LOOKS, NotificationData } from "../../../../shared/services/notification/notification-data";
import { first } from "rxjs/operators";
import { BulkOperationResult, BulkResult } from "../../../../content/dynamic-modules/services/operations/commands/bulk-command";
import { HasNotificationCommand, CommandNotificationArgs } from "../../../../shared/commands/has-notification-command";
import { BulkChangeTemplateNotificationComponent } from "../../../../content/dynamic-modules/components/bulk-operations/bulk-change-template-notification.component";
import { Inject } from "@angular/core";

const NOTIFICATION_DURATION = 5000;

export class ChangeTemplateCommand implements ExecuteOnceInBulkCommand, HasNotificationCommand {
    public executeOnceInBulk: boolean = true;

    private resultMessage: string;

    constructor(private readonly modalWindowService: ModalWindowService,
                private readonly dynamicItemStore: DynamicItemStore,
                @Inject(NOTIFICATION_SERVICE) private readonly notificationService: NotificationService) {
    }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        const handled = new ReplaySubject<BulkOperationResult>(1);

        const changeTemplateComponentData = this.getChangeTemplateComponentData(context, handled);
        const dialogData = new DialogData(changeTemplateComponentData, (closingContext: ClosingContext) => {
            if (closingContext.type === ClosingContextType.CloseClicked) {
                handled.next({ success: false, reload: false });
            } else if (closingContext.type === ClosingContextType.DoneCalled && closingContext.data.changeMode === ChangeMode.Create) {
                context.data.onTemplateSelection(closingContext.data.templateId, closingContext.data.templateName);
                handled.next({ success: true, reload: true });
                this.modalWindowService.hide(context.currentRoute, true);
            }
        });

        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.show(DEFAULT_URL_KEY, context.currentRoute.parent);

        return handled.pipe(first());
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!succeededItems && !failedItems) {
            return null;
        }
        
        const operationPartiallySucceeded: boolean = succeededItems && succeededItems.length > 0 && failedItems && failedItems.length > 0;
        const operationFailed: boolean = !operationPartiallySucceeded && failedItems && failedItems.length > 0;
        const operationSucceeded: boolean = !operationPartiallySucceeded && succeededItems && succeededItems.length > 0;

        const notificationData: NotificationData = {
            type: BulkChangeTemplateNotificationComponent,
            properties: {
                succeededItemsIds: succeededItems,
                failedItemsIds: failedItems,
                entityData: args.entityData,
                operationName: args.action.name.toLowerCase(),
                message: this.resultMessage
            },
            id: "bulkChangeTemplateNotification",
            look: NOTIFICATION_LOOKS.SUCCESS
        };

        if (operationSucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            notificationData.duration = NOTIFICATION_DURATION;
        } else if (operationFailed) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            notificationData.closeButton = true;
        } else if (operationPartiallySucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.WARNING;
            notificationData.closeButton = true;
        }

        return notificationData;
    }

    private getChangeTemplateComponentData(context: ExecutionContext, handled: ReplaySubject<BulkOperationResult>): ComponentData {
        return {
            type: ChangeTemplateComponent,
            properties: {
                selectedPagesIds: context.data.selectedItems.map(x => x.key),
                entityData: context.data.entityData,
                onTemplateSelectionCallback: (tmplId: string, mode: ChangeMode, templateName: string) => this.handleSelectedTemplate(tmplId, templateName, mode, context, handled)
            }
        };
    }

    private handleSelectedTemplate(templateId: string, templateName: string, mode: ChangeMode, context: ExecutionContext, handled: ReplaySubject<BulkOperationResult>) {
        const selectedPages = context.data.selectedItems.map(x => x.key);
        const data = {
            templateId,
            selectedPages,
            templateName
        };

        if (mode !== ChangeMode.Create) {
            this.dynamicItemStore.executeEntityOperation(context.data.entityData, "Default.ChangePageTemplate", data)
                .subscribe((result: BulkResult) => {
                    this.resultMessage = result.Message;
                    const bulkResult: BulkOperationResult = {
                        success: true,
                        failedItemsIds: result.FailedItemsIds,
                        succeededItemsIds: result.SucceededItemsIds,
                        failedItemsErrors: {},
                        reload: true
                    };
                    handled.next(bulkResult);

                    if (mode === ChangeMode.Single) {
                        this.notificationService.publishBasicNotification({
                            message: result.Message,
                            look: NOTIFICATION_LOOKS[result.Type.toUpperCase()]
                        });
                    }
                });
        }
    }
}
