import { InjectionToken } from "@angular/core";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";
import { ModifyFieldsArgs, ActionResult, EditActionContext } from "./composite-edit-extender";
import { Observable, of } from "rxjs";
import { NotificationService } from "../notification/notification.service";
import { NavbarConfiguration } from "../../components/navigation/navigation-menu/navigation-menu.component";
import { SidebarComponentData } from "../../components/sidebar/sidebar-component.repo";
import { stringConstants } from "../../../../common-constants";
import { CSS_CLASSES } from "../../../content/constants";
import { COMPARE_TRANSLATIONS_TITLE } from "../../../content/dynamic-modules/components/dynamic-item.constants";

export const EDIT_EXTENDER_TOKEN = new InjectionToken("edit_extender_token");
export const COMPARE_TRANSLATIONS_NAME = "cmp-translations";
export const BROWSE_BUTTON_NAME = "siblings";

/**
 * Provider logic for modifying field sections based on some criteria.
 *
 * @class EditExtender
 */
export class EditExtender {
    /**
     * Modifies given field sections.
     *
     * @param {FieldSectionModel[]} sections The sections that will be modified.
     * @param {DataItem} dataItem The item that is to be edited.
     */
    modify(args: ModifyFieldsArgs): Observable<void> {
        this.handleFewerFields(args);
        return of(null);
    }

    handleAction(context: EditActionContext, notificationService: NotificationService): ActionResult {
        return { handled: of(false) };
    }

    isSupportedType(entityData: EntityData): boolean {
        return false;
    }

    overrideNavigationMenuOptions(dataItem: DataItem, options: NavbarConfiguration): void {
    }

    getFormClasses(): string {
        return stringConstants.EMPTY_STRING;
    }

    getActionMenuClasses(): string {
        return stringConstants.EMPTY_STRING;
    }

    showHeader(entityData: EntityData): boolean {
        return false;
    }

    getHeader(dataItem: DataItem): string {
        return null;
    }

    getSidebarButtons(entityData: EntityData, compDatas: SidebarButtonComponentData) {
        const browseButton = {
            title: `Browse other ${entityData.metadata.displayName.toLowerCase()}`,
            icon: "th-list",
            name: BROWSE_BUTTON_NAME,
            data: compDatas.browse
        };

        const translationsButton = {
            title: COMPARE_TRANSLATIONS_TITLE,
            data: compDatas.compareTranslations,
            name: COMPARE_TRANSLATIONS_NAME,
            icon: null
        };

        return [browseButton, translationsButton];
    }

    handleFewerFields(args: ModifyFieldsArgs): void {
        const sections = args.sections;
        if (!!args.viewName && sections.length === 1 && sections[0].fields.length <= 3) {
            sections[0].fields[0].settings.look += " " + CSS_CLASSES.MARGIN_BOTTOM_SHORT_FORM;
        }
    }

    includedProperties(entityData: EntityData): string[] {
        return [];
    }

    excludedProperties(entityData: EntityData): string[] {
        return [];
    }

    hasCreateActionFromEdit(): boolean {
        return false;
    }

    forceUpdateFieldModel(selector: string, updatedDataItem: DataItem, dataItem: DataItem): boolean {
        return false;
    }

    getStatusToDisplay(dataItem: DataItem): any {
        return dataItem.data.DisplayStatus.find(s => s.Message.Description);
    }
}

export interface SidebarButtonComponentData {
    browse: SidebarComponentData;

    compareTranslations: SidebarComponentData;
}
