import { ShortTextSettings } from "../../../../fields/short-text/short-text-settings";
import { VALIDATION_REQUIRED } from "../../../../fields/common/common-constants";

const REQUIRED_VALIDATION_PATTERN = /\S+/mi;

export class HtmlSettings extends ShortTextSettings {
    public showTitle: boolean;
    public disableLinkParser: boolean;
    public editorCssClass?: string;

    constructor(public key: string, public readOnlyMode: boolean) {
        super(key, readOnlyMode);
        this.underlineErrors = true;
        this.shortTextValidatorMap.set(VALIDATION_REQUIRED, () => this.createPatternValidator(REQUIRED_VALIDATION_PATTERN));
    }
}
