import { Pipe, PipeTransform } from "@angular/core";
import { stringConstants } from "../../../src/app/common-constants";

export const TIME_PARTS = {
    day: 86400,
    hour: 3600,
    minute: 60,
    second: 1
};
const IS_DIGIT_CEIL_CHECK = 10;
const ZERO_STRING = String(0);
const SEPARATOR_STRING = stringConstants.COLON;

@Pipe({
    name: "sfSecondsToTime"
})
export class SecondsToTimePipe implements PipeTransform {

    transform(seconds: any) {
        if (seconds === Infinity || isNaN(seconds)) {
            return stringConstants.EMPTY_STRING;
        }

        let timeString: string = stringConstants.EMPTY_STRING;
        const timeArray: Array<string> = [];
        let calc: any = 0;

        Object.keys(TIME_PARTS).forEach(key => {
            calc = Math.floor(seconds / TIME_PARTS[key]);
            if (calc !== 0 || timeArray.length !== 0) {
                const leadingZero = calc < IS_DIGIT_CEIL_CHECK && (timeArray.length > 0 || key === "second") ? ZERO_STRING : stringConstants.EMPTY_STRING;
                timeArray.push(leadingZero + calc.toString());
                seconds = seconds - TIME_PARTS[key] * calc;
            }
        });

        if (timeArray.length === 1) {
            timeArray.unshift(ZERO_STRING);
        }

        timeString = timeArray.join(SEPARATOR_STRING);
        return timeString;
    }
}
