import { ActivatedRoute } from "@angular/router";

import { AuxServiceBase } from "./aux-service.base";
import { Directive, OnInit } from "@angular/core";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const AUX_ROUTE_PARAM_NAME = "name";

@Directive()
export abstract class AuxHostComponent<TService extends AuxServiceBase<any>> extends SfRxBase implements OnInit {
    protected service: TService;

    constructor(protected route: ActivatedRoute) {
        super();
    }

    ngOnInit() {
        const routeSubscription = this.route.params.subscribe(paramsData => {
            const key = paramsData[AUX_ROUTE_PARAM_NAME];
            const data = this.service.getData(key);
            const isDirectNavigation = !this.service.currentActivityStatus;

            if (data) {
                this.onMappingChanged(data, key);
                if (isDirectNavigation) {
                    this.onClose();
                }
            } else {
                this.onClose();
            }
        });

        this.registerSubscription(routeSubscription);
    }

    protected abstract onMappingChanged(mapping: any, url: string);

    protected onClose(): Promise<boolean> {
        return this.service.hide(this.route.parent);
    }
}
