import { Component, OnInit, ChangeDetectorRef, Inject } from "@angular/core";
import { MediaReadonlyComponent } from "./media.component.readonly";
import { MediaSettings } from "./media.settings";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DialogData, ModalWindowService } from "../../shared/services/modal-window.service";
import { FileListComponent } from "../file-list.component";
import { MEDIA_TYPES, ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { MediaDataFactory } from "./media-data/media-data.factory";
import { ActivatedRoute } from "@angular/router";
import { LayoutService } from "../services/layout.service";
import { DomSanitizer } from "@angular/platform-browser";
import { MediaRecognizerService } from "./media-recognizer.service";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ScrollService } from "../../../services/scroll.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { EditNavigationService } from "../../shared/services/edit-navigation.service";
import { SiteDataStore } from "../../shared/services/metadata/site-data.store";
import { AppStore } from "../../../services/store/app-store";
import { MediaService } from "../services/media.service";

@Component({
    templateUrl: "./media.component.grid.html",
    selector: "sf-media-component-grid"
})
export class MediaGridComponent extends MediaReadonlyComponent implements OnInit {
    showCount: boolean;

    constructor(mediaDataFactory: MediaDataFactory,
                modalService: ModalWindowService,
                route: ActivatedRoute,
                layoutService: LayoutService,
                sanitizer: DomSanitizer,
                mediaRecognizerService: MediaRecognizerService,
                changeDetector: ChangeDetectorRef,
                private metadataStore: MetadataStore,
                scrollService: ScrollService,
                @Inject(WINDOW_TOKEN) window: Window,
                editNavigationService: EditNavigationService,
                siteDataStore: SiteDataStore,
                appStore: AppStore,
                mediaService: MediaService) {
        super(mediaDataFactory, modalService, route, layoutService, sanitizer, mediaRecognizerService, changeDetector, scrollService, window, editNavigationService, siteDataStore, appStore, mediaService);
    }

    ngOnInit(): void {
        super.ngOnInit();
        this.showCount = (this.settings as MediaSettings).allowMultiple;

        this.settings.allowAdd = false;
        this.settings.allowRemove = false;
    }

    public onShowAllRelatedMedia(): void {
        const mediaEntityData = this.getMediaEntityData(this.settings.type);
        const componentData: ComponentData = {
            type: FileListComponent,
            properties: {
                multiple: false,
                value: [],
                mediaEntityData,
                mediaItems: this.value.map(x => DataItem.fromEntityData(x, mediaEntityData)),
                showTitleAndCount: true,
                title: this.settings.title,
                isSelectable: false,
                dimNotTranslated: true
            }
        };

        const dialogData = new DialogData(componentData, null, [], "-narrow -sf-centered-box", "-bottom");

        this.modalService.setMapping(dialogData);
        this.modalService.open(this.route);
    }

    private getMediaEntityData(mediaType: any): EntityData {
        let mediaEntity = null;
        switch (mediaType) {
            case MEDIA_TYPES.IMAGE:
                mediaEntity = this.metadataStore.getEntity(ENTITY_SET.IMAGES);
                break;
            case MEDIA_TYPES.VIDEO:
                mediaEntity = this.metadataStore.getEntity(ENTITY_SET.VIDEOS);
                break;
            case MEDIA_TYPES.DOCUMENT:
                mediaEntity = this.metadataStore.getEntity(ENTITY_SET.DOCUMENTS);
                break;
        }

        return {
            metadata: mediaEntity,
            provider: null,
            culture: null
        };
    }
}
