import { Injectable, ClassProvider } from "@angular/core";
import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "./operations-filter";
import { Operation, OPERATION_CATEGORIES, OPERATION_NAMES } from "../../../../shared/components/action-menu/operation.model";
import { OperationsData, OperationsTarget } from "./interfaces";
import { TAXONOMY_ITEM_FULL_NAME } from "../../../../shared/services/metadata/meta-data-constants";
import { PUBLISHED } from "../../../../../../../fields/resolvers/base-status.resolver";
import { Properties } from "../../../../shared/fields.constants";

export const WORKFLOW_DROPDOWN_OPERATIONS = [
    OPERATION_NAMES.publish,
    OPERATION_NAMES.schedule,
    OPERATION_NAMES.unpublish,
    OPERATION_NAMES.siteSync,
    OPERATION_NAMES.subscribe,
    OPERATION_NAMES.unsubscribe
];

@Injectable()
export class BaseOperationsFilter implements OperationsFilter {
    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (data.target === OperationsTarget.List) {
            operations = this.filterWorkflowOperations(operations);
            operations = this.filterPreviewOperation(operations);
            operations = this.filterPublishOperaionForAlreadyPublishedItem(operations, data);
            operations = this.filterSetCustomExpirationOperation(operations, data);
            operations = this.filterLayoutOperations(operations);
        } else if (data.target === OperationsTarget.Bulk) {
            operations = this.filterBulkOperations(operations, data);
            operations = this.placeBulkEditOperationFirst(operations);
        } else if (data.target === OperationsTarget.Edit) {
            operations = this.filterUnlockOperation(operations);
            operations = this.filterEditContentOperation(operations);
            operations = this.filterStopScheduleOperations(operations, data);
            operations = this.filterReorderOperation(operations);
        } else {
            operations = this.filterStopScheduleOperations(operations, data);
            operations = this.filterReorderOperation(operations);
        }

        return this.filterOperations(operations, data);
    }

    private filterWorkflowOperations(operations: Operation[]) {
        return operations.filter(operation => operation.Category.Name !== OPERATION_CATEGORIES.workflow ||
            WORKFLOW_DROPDOWN_OPERATIONS.indexOf(operation.Name) > -1);
    }

    private filterPreviewOperation(operations: Operation[]) {
        return operations.filter(x => x.Name !== OPERATION_NAMES.preview);
    }

    private filterPublishOperaionForAlreadyPublishedItem(operations: Operation[], data: OperationsData) {
        const isItemPublished = data.dataItem.data &&
                                data.dataItem.data.DisplayStatus &&
                                data.dataItem.data.DisplayStatus.length > 0 &&
                                data.dataItem.data.DisplayStatus[0].Name === PUBLISHED;

        if (isItemPublished) {
            return operations.filter(x => x.Name !== OPERATION_NAMES.publish);
        }

        return operations;
    }

    private filterUnlockOperation(operations: Operation[]) {
        // if the user can edit, this means that unlock should be excluded
        const hasEditOperation = operations.some(o => o.Name === OPERATION_NAMES.edit ||
                                                      o.Name === OPERATION_NAMES.editContent ||
            (o.ParentOperation != null && o.ParentOperation.Name === OPERATION_NAMES.edit));

        if (hasEditOperation) {
            return operations.filter(x => x.Name !== OPERATION_NAMES.unlock);
        }

        return operations;
    }

    private filterEditContentOperation(operations: Operation[]) {
        return operations.filter(x => x.Name !== OPERATION_NAMES.editContent);
    }

    private filterLayoutOperations(operations: Operation[]) {
        return operations.filter(x => x.Name !== OPERATION_NAMES.lockLayout && x.Name !== OPERATION_NAMES.unlockLayout);
    }

    private filterStopScheduleOperations(operations: Operation[], data: OperationsData) {
        if (!data.dataItem.metadata.isSelfReferencing) {
            return operations.filter(x => x.Name !== OPERATION_NAMES.stopSchedule &&
                x.Name !== OPERATION_NAMES.stopScheduleUnpublish);
        }

        return operations;
    }

    private filterReorderOperation(operations: Operation[]) {
        return operations.filter(x => x.Name !== OPERATION_NAMES.reorder);
    }

    private filterSetCustomExpirationOperation(operations: Operation[], data: OperationsData) {
        return data.dataItem.isEmpty ? operations.filter(x => x.Name !== OPERATION_NAMES.setCustomExpiration) : operations;
    }

    private filterBulkOperations(operations: Operation[], data: OperationsData): Operation[] {
        if (data.dataItem.metadata.typeFullName === TAXONOMY_ITEM_FULL_NAME) {
            return [];
        }

        const allowedOperations = [
            OPERATION_NAMES.publish,
            OPERATION_NAMES.unpublish,
            OPERATION_NAMES.sendForTranslation,
            OPERATION_NAMES.schedule,
            OPERATION_NAMES.delete,
            OPERATION_NAMES.template,
            OPERATION_NAMES.changeOwner,
            OPERATION_NAMES.moveTaxon,
            OPERATION_NAMES.mergeTaxon,
            OPERATION_NAMES.bulkEditProperties,
            OPERATION_NAMES.move,
            OPERATION_NAMES.assignTaxons,
            OPERATION_NAMES.siteSync,
            OPERATION_NAMES.setCustomExpiration
        ];

        operations = operations.filter(o => allowedOperations.indexOf(o.Name) > -1);
        return operations;
    }

    private placeBulkEditOperationFirst(operations: Operation[]) {
        const bulkEditOperation = operations.find(x => x.Name === OPERATION_NAMES.bulkEditProperties);
        if (bulkEditOperation) {
            operations = operations.filter(x => x.Name !== OPERATION_NAMES.bulkEditProperties);
            operations.unshift(bulkEditOperation);
        }

        return operations;
    }

    private filterOperations(operations: Operation[], data: OperationsData) {
        // TODO filter personalization
        const allowedOperationNames = [
            OPERATION_NAMES.permissions,
            OPERATION_NAMES.sendForTranslation,
            OPERATION_NAMES.sharePreviewLink,
            OPERATION_NAMES.createChild,
            OPERATION_NAMES.mobilePreview,
            OPERATION_NAMES.createChildCategory,
            OPERATION_NAMES.createMedia,
            OPERATION_NAMES.moveTaxon,
            OPERATION_NAMES.move,
            OPERATION_NAMES.reorder,
            OPERATION_NAMES.template,
            OPERATION_NAMES.shareWith,
            OPERATION_NAMES.siteSync,
            OPERATION_NAMES.setCustomExpiration,
            OPERATION_NAMES.lockLayout,
            OPERATION_NAMES.unlockLayout
        ];

        // when we are not translating an item
        const availableLangs: Array<string> = data.dataItem.isEmpty ? null : data.dataItem.data[Properties.AvailableLanguages];
        if (!availableLangs || availableLangs.indexOf(data.dataItem.culture) !== -1) {
            allowedOperationNames.push(OPERATION_NAMES.duplicate);
        }

        const isOperationToRemove = (p: Operation) =>
            (p.Category.Name === OPERATION_CATEGORIES.settings &&
                allowedOperationNames.indexOf(p.Name) === -1);

        if (data.target === OperationsTarget.List && !data.dataItem.isEmpty) {
            const filteredOperations = operations
                .filter(p => !isOperationToRemove(p))
                .filter(x => x.Name !== OPERATION_NAMES.unlock)
                .filter(x => x.Category.Name !== OPERATION_CATEGORIES.contentLocations);

            return filteredOperations;
        }

        if (data.target === OperationsTarget.Edit || data.target === OperationsTarget.Create) {
            let filteredOperations = operations
                .filter(p => !isOperationToRemove(p))
                .filter(x => x.Name !== OPERATION_NAMES.view
                    && x.Name !== OPERATION_NAMES.changeOwner
                    && x.Name !== OPERATION_NAMES.move);

            if (data.dataItem.isEmpty) {
                filteredOperations = filteredOperations.filter(o => allowedOperationNames.indexOf(o.Name) === -1);
            }

            if (data.target === OperationsTarget.Create) {
                filteredOperations = filteredOperations.filter(x => x.Name !== OPERATION_NAMES.delete && x.Name !== OPERATION_NAMES.duplicate && x.Name !== OPERATION_NAMES.bulkEditProperties);
            }

            return filteredOperations;
        }

        return operations;
    }
}

export const BASE_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: BaseOperationsFilter
};
