import { Component, ViewChild, Output, EventEmitter, Input, OnInit, SimpleChanges, OnChanges, QueryList } from "@angular/core";
import { FieldBase, createValueAccessor } from "../field-base";
import { CheckBoxStates } from "./checkbox-states";
import { stringConstants } from "../../src/app/common-constants";
import { ChoiceSettings } from "./choice.settings";
import { DynamicTemplateDirective } from "../../src/app/modules/shared/fields-builder/components/editable-fields/dynamic-template.directive";
import { HttpODataRequestWrapper } from "../../src/app/modules/shared/services/http-odata-request.wrapper";
import { Observable, of, ReplaySubject } from "rxjs";
import { catchError, first, switchMap } from "rxjs/operators";
import { Logger } from "../../src/app/modules/shared/services/logger-source/logger";
import { ChoiceItem, ChoiceSettingsBase } from "@progress/sitefinity-component-framework";
import { StatusType } from "../field-status";

@Component({
    selector: "sf-choice",
    templateUrl: "./choice.component.html",
    providers: [createValueAccessor(ChoiceComponent)]
})
export class ChoiceComponent extends FieldBase<ChoiceSettings> implements OnInit, OnChanges {
    @ViewChild("choiceWrapper", { static: true }) protected choiceWrapper;
    @Input() look: string;
    @Input() isChip: boolean;
    @Input() wrapperCssClass: string;
    @Output() selectionChange: EventEmitter<string> = new EventEmitter<string>();
    @Output() choicesLoaded: ReplaySubject<void> = new ReplaySubject<void>(1);

    cssClassList: string;
    protected choicesData: string[] = [];
    protected warnings: string[] = [];
    choiceSettings: ChoiceSettingsBase = {};
    choices: Array<ChoiceItem> = [];

    constructor(protected httpRequestWrapper: HttpODataRequestWrapper, protected logger: Logger) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.initChoicesData();
        this.cssClassList = this.generateCssClassList();

        if (this.settings) {
            this.choiceSettings = {
                key: this.settings.key,
                choiceCssClass: this.cssClassList,
                wrapperCssClass: this.wrapperCssClass,
                isChip: this.isChip
            };
        }

        this.registerSubscription(this.outputTemplateCallback.subscribe((templates: QueryList<DynamicTemplateDirective>) => {
            if (templates) {
                this.choices.forEach(c => {
                    const template = templates.find(x => {
                        const conditionIndex = x.conditionalFieldRule.conditions.findIndex(cond => cond.fieldName === this.settings.key && cond.value === c.Value);
                        return conditionIndex > -1;
                    });
                    if (template) {
                        c.ExpandedTemplate = template.templateRef;
                    }
                });
            }
        }));

        this.reloadChoices();
    }

    getWarnings() {
        return this.warnings;
    }

    reloadChoices() {
        this.registerSubscription(this.loadChoices().subscribe(() => {
            // calling code does not know that ngOnInit has asynchronous operation
            // so we need to rewrite the value that was written to the base class
            // because it was written before this class has loaded its choices
            // and the logic in the overriden writeValue method here was not executed
            if (this.choices && this.choices.length === 0 && this.settings.choiceServiceUrl) {
                if (this.settings.choiceServiceWarningMessage) {
                    this.warnings = [this.settings.choiceServiceWarningMessage];
                    this.emitStatus({ type: StatusType.Warning });
                } else {
                    this.setHidden(true);
                }
                this.writeValue(null);
            } else {
                const currentValue = super.getValue();
                this.warnings = [];
                this.setHidden(false);
                if (currentValue !== null) {
                    this.writeValue(currentValue);
                }
            }
        }));
    }

    clearChoices(fullClean: boolean) {
        const choices = [];

        if (this.settings.placeholder && !fullClean) {
            choices.unshift({ Name: this.settings.placeholder, Value: null });
        }

        if (fullClean) {
            this.setHidden(true);
        }

        this.settings.choices = choices;
        this.mapChoiceItems();
        this.choicesLoaded.next();
        this.writeValue(null);
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes && changes.settings) {
            this.initChoicesData();
        }
    }

    isChecked(index): boolean {
        return this.choicesData[index] === CheckBoxStates.Checked;
    }

    onSelectionChange(index) {
        this.updateChoicesData(index);
        this.setSelected();
        this.updateValueOnSelectionChange(index);

        const selection = this.choices[index];

        if (selection) {
            this.selectionChange.emit(selection.Value);
        }
    }

    generateCssClassList(): string {
        let cls = "";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.settings && this.settings.look) {
            cls += " -" + this.settings.look.split(" ").join(" -");
        }
        return cls;
    }

    writeValue(val) {
        // const settings = this.settings as ChoiceSettings;
        let isBinaryChoiceValue = false;
        if (val !== null) {
            const isAllZerosAndOnes = val && /^[0-1]{2,}$/.test(val.toString());
            isBinaryChoiceValue = isAllZerosAndOnes && this.choices.findIndex(x => x.Value === val || +x.Value === val) < 0;
        }

        if (this.settings && !this.settings.hasFieldset && this.choices && !isBinaryChoiceValue) {
            // value could be a number but choices values are always represented as strings
            const checkedIndex = this.choices.findIndex(x => x.Value === val || +x.Value === val);

            this.choicesData = new Array(this.choices.length).fill("0");
            if (checkedIndex >= 0) {
                this.choicesData[checkedIndex] = CheckBoxStates.Checked;
            }
        } else if (isBinaryChoiceValue) {
            this.choicesData = val.split(stringConstants.EMPTY_STRING);
        }

        this.setSelected();
        super.writeValue(val);
    }

    protected updateChoicesData(index) {
        const oldIndex = this.choicesData.indexOf(CheckBoxStates.Checked);

        if (oldIndex >= 0) {
            this.choicesData[oldIndex] = CheckBoxStates.Unchecked;
        }

        this.choicesData[index] = CheckBoxStates.Checked;
    }

    protected loadChoices(): Observable<void> {
        let serviceCallParams: { [key: string]: string }[];
        let skipInitialCall = false;

        if (this.settings.choiceServiceCallParameters) {
            serviceCallParams = JSON.parse(this.settings.choiceServiceCallParameters);
            serviceCallParams.forEach(p => {
                const key = Object.keys(p)[0];
                if (this.settings.choiceServiceUrl.indexOf(p[key]) > -1) {
                    skipInitialCall = true;
                }
            });
        }

        if (this.settings.choiceServiceUrl && !skipInitialCall) {
            return this.httpRequestWrapper.get$(this.settings.choiceServiceUrl).pipe(
                first(x => !x.isLoading),
                switchMap(x => {
                    const choices = JSON.parse(JSON.stringify(x.content.value));
                    if (this.settings.placeholder && choices.length) {
                        choices.unshift({ Name: this.settings.placeholder, Value: null });
                    }

                    this.settings.choices = choices;
                    this.mapChoiceItems();
                    this.settings.assignEmptyChoiceValues(choices);
                    this.choicesLoaded.next();
                    return of(null);
                }),
                catchError(err => {
                    this.settings.choices = [];
                    this.choices = [];
                    this.logger.error(err);
                    this.choicesLoaded.next();
                    return of(null);
                }));
        } else {
            this.choicesLoaded.next();
            return of(null);
        }
    }

    protected mapChoiceItems() {
        this.choices = this.settings.choices.map(choice => {
            const choiceItem: ChoiceItem = {
                Name: this.settings.choiceShowFriendlyName ? choice.Title || choice.Name : choice.Name,
                Value: choice.Value !== undefined ? choice.Value : (choice as any).Id,
                Selected: choice.Selected,
                Title: choice.Title || choice.Name,
                Description: choice.Description,
                ExpandedTemplate: choice.ExpandedTemplate,
                Icon: choice.Icon
            };

            return choiceItem;
        });
    }

    protected setSelected() {
        for (let i = 0; i < this.choices.length; i++) {
            this.choices[i].Selected = this.isChecked(i);
        }
    }

    private updateValueOnSelectionChange(index) {
        // When the choice is field, the value should be persisted as 101010
        if (this.settings.hasFieldset) {
            this.writeValue(this.choicesData.join(stringConstants.EMPTY_STRING));
        } else {
            // When the choice is not field, for example languages dropdown, the value should be the selected one
            // because a lot of logic depends on registering a change callback through form field wrapper.
            const settings = this.settings as ChoiceSettings;
            const valueToWrite = settings.choices[index]?.Value !== undefined ? settings.choices[index].Value : this.choices[index].Value;
            this.writeValue(valueToWrite);
        }
    }

    private initChoicesData() {
        const settings = this.settings as ChoiceSettings;
        if (!settings || !settings.choices || !settings.choices.length) {
            return;
        }
        const val = super.getValue() as string;

        if (!val || val.length < settings.choices.length || !settings.hasFieldset) {
            this.choicesData = new Array(settings.choices.length).fill("0");

            const defaultValueIndex = settings.choices.findIndex(x => x.Value === settings.defaultValue);
            if (settings.useDefaultValue && defaultValueIndex >= 0) {
                this.choicesData[defaultValueIndex] = CheckBoxStates.Checked;
            }
        } else {
            this.choicesData = val.split(stringConstants.EMPTY_STRING);
        }

        this.mapChoiceItems();
        this.setSelected();
    }
}
