import { Injectable } from "@angular/core";
import { FieldModel } from "../../services/field.model";
import { CompositeFieldsProvider } from "../shared/fields-builder/providers/fields-provider";
import { PAGE_PRESET_ITEM_FULL_NAME, RESTRICTIONS_FOR_RELATED_MEDIA } from "../shared/services/metadata/meta-data-constants";
import { Entity } from "../shared/services/metadata/meta-data.store";
import { MetadataHandler } from "../shared/services/metadata/metadata.handler";
import { FormData } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { DEFAULT_FIELD } from "../../../../fields/common/common-constants";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { FilePreviewEditSettings } from "../libraries/file-preview-edit/file-preview-edit-settings";
import { Properties } from "../shared/fields.constants";

@Injectable()
export class PresetsMetadataHandler extends MetadataHandler {
    fieldGroups: any[] = [];

    constructor(protected fieldsProvider: CompositeFieldsProvider) {
        super(fieldsProvider);
    }

    getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string {
        const defaultProperty = metadata.properties[DEFAULT_FIELD];
        if (propertyName === defaultProperty) {
            return FieldTypes.shortText;
        }

        if (propertyName === Properties.THUMBNAIL) {
            return FieldTypes.mediaData;
        }
    }

    processFieldGroup(propertyName: string, fields: FieldModel[], metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean, tweaks: FormData[]): string[] {
        return [];
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === PAGE_PRESET_ITEM_FULL_NAME;
    }

    updateFieldSettings(fields: FieldModel[], metadata: Entity, tweaks: any[]) {
        fields.forEach(field => {
            field.settings.showForAllTranslationsLabel = false;
        });

        const imageFiled = fields.find(f => f.key === Properties.THUMBNAIL);
        const imageSettings = imageFiled.settings as FilePreviewEditSettings;
        imageSettings.allowEditFile = false;
        imageSettings.showMediaDetails = false;

        const imageTweak = tweaks.find(t => t.name === Properties.THUMBNAIL);
        if (imageTweak) {
            imageSettings.provider = imageTweak.metadata.Provider;
            imageSettings.targetLibraryId = imageTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.TARGET_LIBRARY_ID_KEY];
        }
    }
}

export const PRESETS_METADATA_HANDLER = { provide: MetadataHandler, useClass: PresetsMetadataHandler, multi: true };
