import { Component, Inject, OnDestroy, Renderer2, ViewChild, ViewEncapsulation } from "@angular/core";
import { HtmlWrapperComponent } from "../../../../components/html-wrapper";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";
import { ActivatedRoute } from "@angular/router";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { Observable, of, Subject, ReplaySubject } from "rxjs";
import { stringConstants } from "../../../../common-constants";
import { ContentBlockConstants } from "../content-block.constants";
import { WidgetContext } from "../../models/widget-context";
import { WidgetEditor, WidgetMetadata, PropertyData, ActionContext, ValidationResult } from "../../interfaces/widget-editor";
import { FeedbackInfo } from "../../models/feedback-info";
import { NotifyStatusChange } from "../../interfaces/notify-status-change";
import { ShortTextDefaultSettings } from "../../../../../../fields/short-text/short-text-settings";
import { CustomActions, FooterActionMenu } from "../../interfaces/custom-actions";
import { OPERATION_NAMES } from "../../../shared/components/action-menu/operation.model";
import { HtmlSettings } from "../../../html";
import { DOCUMENT_TOKEN } from "../../../../document.provider";
import { Dictionary } from "../../property-editor.constants";
import { StatusType } from "../../../../../../fields/field-status";
import { map } from "rxjs/operators";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";

const CONTENT_BLOCK_CLASS = "-sf-content-block-open";

@Component({
    selector: "sf-content-editor",
    templateUrl: "./content-block-basic.component.html",
    styleUrls: ["./content-block-basic.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class ContentBlockBasicComponent extends SfRxBase implements WidgetEditor, NotifyStatusChange, CustomActions, OnDestroy {
    @ViewChild("htmlWrapper", { static: true }) htmlWrapperComponent: HtmlWrapperComponent;

    notifyStatusChange$ = new Subject<FeedbackInfo>();
    isShared: boolean;
    context: WidgetContext;
    headingCssClass: string;
    contentBlockHeader = ContentBlockConstants.CONTENT_BLOCK;
    initializationFailed: boolean = false;
    contentItem$: ReplaySubject<DataItem> = new ReplaySubject<DataItem>(1);

    protected set contentItem(data: DataItem) {
        this._contentItem = data;
        this.contentItem$.next(data);
    }
    protected get contentItem(): DataItem {
        return this._contentItem;
    }

    private _contentItem: DataItem;
    private html: string;
    private sharedContentID: string;
    private providerName: string;
    private isLocked = false;
    private headerShortTextSettings = new ShortTextDefaultSettings("headingKey", true);
    private footerButtonsClass = "-bottom";
    private htmlWrapperKey = "htmlWrapper";

    constructor(protected dynamicItemService: DynamicItemService,
                private route: ActivatedRoute,
                @Inject(DOCUMENT_TOKEN) private document,
                private renderer: Renderer2) {
                super();
    }

    initialize(widgetMetadata: WidgetMetadata): Observable<void> {
        this.providerName = widgetMetadata.propertyValues[ContentBlockConstants.PROVIER_NAME];
        this.renderer.addClass(this.document.body, CONTENT_BLOCK_CLASS);
        const htmlSettings = new HtmlSettings(this.htmlWrapperKey, <any>[]);
        htmlSettings.culture = this.context.culture;
        this.htmlWrapperComponent.sfHtml.settings = htmlSettings;
        this.headerShortTextSettings.look = "small";

        const cbData = widgetMetadata.propertyValues;
        this.html = cbData[ContentBlockConstants.CONTENT];
        this.sharedContentID = cbData[ContentBlockConstants.SHARED_CONTENT_ID];

        this.htmlWrapperComponent.sfHtml.editor.editorComponentConfig = { collapsible: false, alwaysShowToolbar: true };
        this.htmlWrapperComponent.sfHtml.editor.entitySetName = ENTITY_SET.CONTENT_ITEMS;
        return this.updateContentValue();
    }

    public setValues(propValues: Dictionary): void {
        this.providerName = propValues[ContentBlockConstants.PROVIER_NAME];
        this.html = propValues[ContentBlockConstants.CONTENT];
        this.sharedContentID = propValues[ContentBlockConstants.SHARED_CONTENT_ID];
        this.updateContentValue();
    }

    public validate(): Observable<ValidationResult> {
        return this.htmlWrapperComponent.status$.asObservable().pipe(map(status => {
            return {isValid: status.type !== StatusType.Pending, message: "Waiting for media upload."};
        }));
    }

    public getModifiedProperties(): Array<PropertyData> {
        const modifiedProperties = [];

        if (this.sharedContentID) {
            modifiedProperties.push({Name: ContentBlockConstants.SHARED_CONTENT_ID, Value: this.sharedContentID});
        }
        modifiedProperties.push({Name: ContentBlockConstants.CONTENT, Value: this.htmlWrapperComponent.sfHtml.value});

        return modifiedProperties;
    }

    public actionExecuting(context: ActionContext): Observable<any> {
        if (context.processChanges)
            return this.updateContentItem();
        else
            return this.unlockContentItem();
    }

    public getActions(): FooterActionMenu {
        if (this.initializationFailed)
            return { operations: [], cssClass: this.footerButtonsClass };

        return {operations: null, cssClass: this.footerButtonsClass};
    }

    ngOnDestroy() {
        this.renderer.removeClass(this.document.body, CONTENT_BLOCK_CLASS);
    }

    private updateContentValue(): Observable<void> {
        const update$ = new ReplaySubject<void>(1);
        this.isShared = this.sharedContentID && this.sharedContentID !== stringConstants.DEFAULT_GUID;
        this.headingCssClass = this.isShared ? "-sf-txt-align-center -sf-pt-3xs" : "-sf-txt-align-center -sf-pt-3xl";
        if (this.isShared && !this.contentItem) {
            // Provider should NOT be sent with this request. It's ignored on the server.
            const entityData: EntityData = { ...this.getEntityData(), provider: null };
            if (entityData.metadata) {
                const getItemSubscription = this.dynamicItemService
                    .executeBoundFunction(DataItem.fromEntityData(null, entityData), `Default.GetItemById(itemId=${this.sharedContentID})`, ["Title", "Content"])
                    .subscribe((item) => {
                        this.contentItem = DataItem.fromEntityData(item, this.getEntityData());
                        if (this.contentItem) {
                            this.html = this.contentItem.data.Content;
                            this.updateEditorValue();
                            this.htmlWrapperComponent.registerOnChange(() => this.lockContentItem());
                        }
                        update$.next();
                    },
                    () => {
                        this.html = stringConstants.EMPTY_STRING;
                        this.sharedContentID = stringConstants.DEFAULT_GUID;
                        this.updateEditorValue();
                        update$.next();
                    });
                this.registerSubscription(getItemSubscription);
            } else {
                this.initializationFailed = true;
                update$.next();
            }
        } else {
            this.updateEditorValue();
            update$.next();
        }

        return update$.asObservable();
    }

    private updateEditorValue() {
        this.isShared = this.sharedContentID && this.sharedContentID !== stringConstants.DEFAULT_GUID;
        this.htmlWrapperComponent.value = this.html;
        this.focus();
    }

    private lockContentItem() {
        if (!this.isLocked && this.contentItem) {
            const feedback = new FeedbackInfo();
            feedback.showLoadingIndicator = true;
            this.notifyStatusChange$.next(feedback);
            const lockSubscription = this.dynamicItemService.updateItem({
                dataItem: this.contentItem,
                data: {}
            }).subscribe(() => {
                this.isLocked = true;
                feedback.reset();
                this.notifyStatusChange$.next(feedback);
            },
            (err) => {
                feedback.setError(err);
                this.notifyStatusChange$.next(feedback);
            });
            this.registerSubscription(lockSubscription);
        }
    }

    private unlockContentItem() {
        if (this.isLocked && this.contentItem) {
            return this.dynamicItemService.unlockItem(this.contentItem);
        } else {
            return of(undefined);
        }
    }

    private updateContentItem(): Observable<any> {
        if (this.isLocked && this.contentItem) {
            const currentTranslations: string[] = this.contentItem?.data?.AvailableLanguages || [];
            const isCreatingTranslation = !currentTranslations.includes(this.contentItem.culture) && !!this.sharedContentID;
            const data = {
                "Content": this.htmlWrapperComponent.sfHtml.value
            };

            // Copy the main field from other translation, when the content block is shared and we are
            // creating translation, so the new translation has populated main field.
            if (isCreatingTranslation) {
                const defFieldName = this.contentItem.metadata.defaultFieldName;
                data[defFieldName] = this.contentItem.data[defFieldName];
            }

            return this.dynamicItemService.updateItem({
                dataItem: this.contentItem,
                data,
                operation: {
                    action: OPERATION_NAMES.publish
                }
            });
        } else {
            return of([]);
        }
    }

    private getEntityData(): EntityData {
        const entity = this.route.parent.snapshot.data.metaStore.entities[ContentBlockConstants.ENTITY_NAME];
        const entityData: EntityData = {
            culture: this.context.culture,
            provider: this.providerName,
            metadata: entity
        };
        return entityData;
    }

    private focus() {
        const readySubscription = this.htmlWrapperComponent.sfHtml.editor.isReady$
        .subscribe((isReady) => {
            if (isReady)
                this.htmlWrapperComponent.onFocus();
        });

        this.registerSubscription(readySubscription);
    }
}
