import { Injectable } from "@angular/core";
import { UserDataStore } from "../modules/shared/services/metadata/user-data.store";
import { StatusResolver } from "../../../fields/resolvers/status.resolver";

@Injectable()
export class LockedItemStatusResolver extends StatusResolver {
    constructor(private userDataStore: UserDataStore) {
        super();
    }

    getDetailedLabel(item: any): any {
        const ret = super.getDetailedLabel(item);

        // show the locked text only if the user that locked the item is the same as the current user
        if (item.LockedStatus && item.LockedStatus.Id !== this.userDataStore.getValue().Id) {
            ret.LockedText = this.getDetailedStatus(`Locked by ${item.LockedStatus.User}`, item.LockedStatus.Date);
        }

        return ret;
    }
}
