
import { FieldSectionModel } from "../../../services/fieldSection.model";
import { FieldModel } from "../../../services/field.model";
import { CustomTweaksHandler } from "./custom-tweaks-handler.service";

export abstract class CommonTweaksHandler extends CustomTweaksHandler {
    abstract getTweakInfoMap(): TweakInfo[];

    abstract canProcess(typeFullName: string): boolean;

    handleFormTweak(fieldSections: FieldSectionModel[], tweak: string, fields: FieldModel[]): string[] {
        const mapping = this.getTweakInfoMap().find(t => !!t.fields.find(x => x === tweak));
        if (mapping) {
            const section = fieldSections.find(s => s.settings.name === mapping.sectionName);
            const field = fields.find(f => f.selector === mapping.fieldType);

            if (field) {
                section.fields.push(field);
            }

            return mapping.fields;
        }

        return [];
    }
}

export interface TweakInfo {
    sectionName: string,
    fields: string[],
    fieldType: string
}
