import { ClassProvider, Injectable } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData, stringConstants } from "@progress/sitefinity-component-framework";
import { TextAreaComponent } from "../../../../../../fields/text-area/text-area.component";
import { ADMIN_APP_CONFIG_KEY } from "../../../../app-config/external-app-config.service";
import { HtmlWrapperComponent } from "../../../../components/html-wrapper";
import { HtmlSettings } from "../../../html";
import { PropertyData } from "../../../widget-editor/interfaces/widget-editor";
import { OPERATION_NAMES } from "../../components/action-menu/operation.model";
import { FormFieldWrapperComponent } from "../../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { CancelButton, DeleteButton, DialogData, ModalComponentSettings, ModalWindowService } from "../modal-window.service";
import { ConfigValidationError } from "../../config/config-settings.component";
import { ConfigExtender, CONFIG_EXTENDER_TOKEN } from "./config-extender";

export const EDITOR_SETTINGS_TEXT_AREA_ROWS_COUNT = 17;

export const ADMIN_APP_CONFIG_FIELDS_NAMES = {
    LINK_STYLES: "LinkStyles",
    CUSTOM_EDITOR_SETTINGS: "CustomEditorSettings",
    EDITOR_SETTINGS: "EditorSettings",
    DYNAMIC_MODULE_CHILD_LIST_ORDER: "DynamicModuleChildListOrder",
    SEARCH_SETTINGS: "SearchSettings"
}

const EMPTY_FIELD_VALUES: any[] = ["[]", "{}", null, undefined];

@Injectable()
export class BackendInterfaceSettingsConfigExtender extends ConfigExtender {

    constructor(private modalService: ModalWindowService) {
        super();
    }

    isSupportedType(queryParam: string): boolean {
        return queryParam === ADMIN_APP_CONFIG_KEY;
    }

    modifyPropertyValuesBeforeSave(properties: PropertyData[]): void {
        this.modifyLinkStylesBeforeSave(properties);
        this.modifyCustomEditorSettingsBeforeSave(properties);
        this.modifyDynamicModuleChildListOrderBeforeSave(properties);
        this.modifySearchSettingsBeforeSave(properties);

        // send empty string to reset the value of the field and not persist it as "[]", for example, because that still counts as an actual value
        properties = properties.map(x => {
            if (Array.isArray(x.Value) && x.Value.length === 0) {
                x.Value = stringConstants.EMPTY_STRING;
            } else {
                EMPTY_FIELD_VALUES.forEach(emptyValue => {
                    if (x.Value === emptyValue) {
                        x.Value = stringConstants.EMPTY_STRING;
                    }
                });
            }

            return x;
        });
    }

    getModifiedValuesForVisualization(configValues: { [key: string]: any }): { [key: string]: any } {
        const customEditorSettingsString = configValues[ADMIN_APP_CONFIG_FIELDS_NAMES.CUSTOM_EDITOR_SETTINGS];
        const result = Object.assign({}, configValues);
        if (customEditorSettingsString) {
            const customEditorSettings = JSON.parse(customEditorSettingsString);
            const newCustomEditorSettingsObject = [];
            for (let i = 0; i < customEditorSettings.length; i++) {
                const currentConfiguration = customEditorSettings[i];
                const newConfiguration = {
                    Configuration: { Configuration: currentConfiguration.configuration },
                    ContentTypes: currentConfiguration.contentTypes,
                    Name: currentConfiguration.name
                }
                newCustomEditorSettingsObject.push(newConfiguration);
            }

            result[ADMIN_APP_CONFIG_FIELDS_NAMES.CUSTOM_EDITOR_SETTINGS] = JSON.stringify(newCustomEditorSettingsObject);
        } else {
            result[ADMIN_APP_CONFIG_FIELDS_NAMES.CUSTOM_EDITOR_SETTINGS] = "[]";
        }

        const linkStyles = result[ADMIN_APP_CONFIG_FIELDS_NAMES.LINK_STYLES];
        if (!linkStyles) {
            result[ADMIN_APP_CONFIG_FIELDS_NAMES.LINK_STYLES] = "[]";
        }

        const dynamicChildModuleListListOrderString = result[ADMIN_APP_CONFIG_FIELDS_NAMES.DYNAMIC_MODULE_CHILD_LIST_ORDER];
        if (dynamicChildModuleListListOrderString) {
            const dynamicChildModuleListListOrder = JSON.parse(dynamicChildModuleListListOrderString);
            const newDynamicChildModuleListListOrderArray = [];
            for (let i = 0; i < dynamicChildModuleListListOrder.length; i++) {
                const current = dynamicChildModuleListListOrder[i];
                const newDynamicModuleChildListOrder = {
                    ParentContentType: [current.parentEntitySet],
                    ChildContentTypes: current.childEntitySets
                }

                newDynamicChildModuleListListOrderArray.push(newDynamicModuleChildListOrder);
            }

            result[ADMIN_APP_CONFIG_FIELDS_NAMES.DYNAMIC_MODULE_CHILD_LIST_ORDER] = JSON.stringify(newDynamicChildModuleListListOrderArray);
        } else {
            result[ADMIN_APP_CONFIG_FIELDS_NAMES.DYNAMIC_MODULE_CHILD_LIST_ORDER] = "[]";
        }

        const searchSettingsString = result[ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS];
        if (searchSettingsString) {
            const searchSettings = JSON.parse(searchSettingsString);
            const newSearchSettingsArray = [];
            Object.keys(searchSettings).forEach(parentEntitySetName => {
                const newSearchSettings = {
                    ContentType: [parentEntitySetName],
                    Fields: searchSettings[parentEntitySetName]
                }
                newSearchSettingsArray.push(newSearchSettings);
            });

            result[ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS] = JSON.stringify(newSearchSettingsArray);
        } else {
            result[ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS] = "[]";
        }

        return result;
    }

    getSettingsForSpecificFields(configValues: { [key: string]: any }): any {
        const settingsForSpecificFields: any = {
            EditorSettings: {
                rows: EDITOR_SETTINGS_TEXT_AREA_ROWS_COUNT,
                customLinks: [
                    {
                        linkTitle: "Preview",
                        buttonClickedCallback: this.previewRteToolSetClicked.bind(this),
                        htmlId: "rte-preview",
                        cssClass: "-sf-txt-align-right -sf-txt-base -sf-mt-3xs -sf-mr-xs",
                        icon: "external-link"
                    },
                    {
                        linkTitle: "Restore to default",
                        buttonClickedCallback: this.restoreToDefaultClicked.bind(this),
                        htmlId: "restore-to-default-link",
                        cssClass: "-sf-txt-align-right -sf-txt-base -sf-mt-3xs",
                        icon: "rotate-left"
                    }
                ]
            },
            SectionsMenuMinColumnsNumber: {
                look: "sf-width-2"
            },
            ContentItemsPerPage: {
                look: "sf-width-2"
            },
            MediaItemsPerPage: {
                look: "sf-width-2"
            },
            CustomEditorSettings: {
                itemDefaultValue: { Configuration: configValues[ADMIN_APP_CONFIG_FIELDS_NAMES.EDITOR_SETTINGS] },
                hideRowsIfEmpty: true
            },
            LinkStyles: {
                hideRowsIfEmpty: true
            },
            DynamicModuleChildListOrder: {
                hideRowsIfEmpty: true,
                moduleName: ADMIN_APP_CONFIG_KEY
            },
            SearchSettings: {
                hideRowsIfEmpty: true,
                moduleName: ADMIN_APP_CONFIG_KEY
            }
        }

        return settingsForSpecificFields;
    }

    private previewRteToolSetClicked(formFieldWrapperComponent: FormFieldWrapperComponent, route: ActivatedRoute) {
        if (!formFieldWrapperComponent.hasErrors() && formFieldWrapperComponent.currentInstance as TextAreaComponent) {

            const cast = formFieldWrapperComponent.currentInstance as TextAreaComponent;
            let rteSettings = "";

            try {
                rteSettings = JSON.parse(cast.getValue());
            } catch (error) {
                formFieldWrapperComponent.formControl.setErrors({ error: "Invalid JSON format." });
                // triggers error visibility
                formFieldWrapperComponent.hasErrors();
                return;
            }

            const previewRoute = "rte_preview";

            const htmlSettings = new HtmlSettings("Content", <any>[]);
            htmlSettings.culture = "en";
            htmlSettings.readOnlyMode = false;
            htmlSettings.showTitle = true;
            htmlSettings.visibleTitle = false;
            htmlSettings.allowView = false;
            htmlSettings.title = "Add content...";
            htmlSettings.kind = "mirrorFieldSettingsKind";
            htmlSettings.shouldBeFocusedByDefault = true;
            htmlSettings.shortTextValidatorMap = {};
            htmlSettings.editorCssClass = "-sf-mt-5xl -sf-txt-large -no-focus";

            const componentData: ComponentData = {
                type: HtmlWrapperComponent,
                properties: {
                    editorSettings: rteSettings,
                },
                afterComponentInit(component) {
                    const cast = component as HtmlWrapperComponent;
                    cast.sfHtml.settings = htmlSettings;
                    cast.sfHtml.isMainHtmlField = true;

                    // the setTimeout is needed because the editor of the sfHtml is not ready at the moment of afterComponentInit
                    setTimeout(() => {
                        cast.sfHtml.editor.editorComponentConfig = { collapsible: false, alwaysShowToolbar: true };
                        cast.sfHtml.editor.onFocus();
                    }, 0);
                },
            }

            const dialogData: DialogData = new DialogData(componentData);
            dialogData.heading = { title: "Preview of rich-text editor toolset" };
            dialogData.alwaysSticky = true;
            dialogData.hideBackToTopButton = true;
            dialogData.contentClass = "-sf-txt-align-left";

            const routeInternal = route.snapshot.outlet === "dialog" ? route.parent : route;
            this.modalService.setMapping(dialogData, previewRoute);
            this.modalService.show(previewRoute, routeInternal);
        }
    }

    private restoreToDefaultClicked(formFieldWrapperComponent: FormFieldWrapperComponent, route: ActivatedRoute) {
        const settings: ModalComponentSettings = {
            title: `Restore toolset to default and remove all changes?`,
            icon: "history",
            description: stringConstants.EMPTY_STRING,
            parameters: [],
            contextParameters: null,
            action: OPERATION_NAMES.delete,
            buttons: [new DeleteButton("Restore to default"), new CancelButton()],
            doneCallback: (context: ClosingContext) => {
                if (context.data && context.data.data) {
                    formFieldWrapperComponent.writeValue(formFieldWrapperComponent.fieldModel.settings.defaultValue);
                }
            }
        };

        const routeInternal = route.snapshot.outlet === "dialog" ? route.parent : route;
        this.modalService.openModalConfirmation(routeInternal, settings, null);
    }

    private modifyLinkStylesBeforeSave(properties: any[]): void {
        const linkStyles = properties.find(x => x.Name == ADMIN_APP_CONFIG_FIELDS_NAMES.LINK_STYLES);
        if (linkStyles && linkStyles.Value) {
            linkStyles.Value.forEach(value => {
                if (typeof value.Value === 'string') {
                    value.Value = value.Value.split(',').map(x => x.trim());
                }
            });

            linkStyles.Value = JSON.stringify(linkStyles.Value);
        } else {
            properties = properties.filter(x => x.Name !== ADMIN_APP_CONFIG_FIELDS_NAMES.LINK_STYLES);
        }
    }

    private modifyCustomEditorSettingsBeforeSave(properties: any[]): void {
        const customEditorSettingsProperty = properties.find(x => x.Name === ADMIN_APP_CONFIG_FIELDS_NAMES.CUSTOM_EDITOR_SETTINGS);
        if (customEditorSettingsProperty && customEditorSettingsProperty.Value) {
            const customEditorSettings = customEditorSettingsProperty.Value;
            const newCustomEditorSettingsArray = [];
            for (let i = 0; i < customEditorSettings.length; i++) {
                const currentConfiguration = customEditorSettings[i];
                const newConfiguration = {
                    configuration: currentConfiguration.Configuration.Configuration,
                    contentTypes: currentConfiguration.ContentTypes,
                    name: currentConfiguration.Name
                }
                newCustomEditorSettingsArray.push(newConfiguration);
            }

            customEditorSettingsProperty.Value = newCustomEditorSettingsArray;
        }
    }

    private modifyDynamicModuleChildListOrderBeforeSave(properties: any[]): void {
        const dynamicModuleChildListOrderProperty = properties.find(x => x.Name === ADMIN_APP_CONFIG_FIELDS_NAMES.DYNAMIC_MODULE_CHILD_LIST_ORDER);
        if (dynamicModuleChildListOrderProperty && dynamicModuleChildListOrderProperty.Value) {
            const newDynamicModuleChildListOrderArray = [];
            for (let i = 0; i < dynamicModuleChildListOrderProperty.Value.length; i++) {
                const currentDynamicModuleChildListOrder = dynamicModuleChildListOrderProperty.Value[i];
                const newDynamicModuleChildListOrder = {
                    parentEntitySet: currentDynamicModuleChildListOrder.ParentContentType[0],
                    childEntitySets: currentDynamicModuleChildListOrder.ChildContentTypes
                }

                newDynamicModuleChildListOrderArray.push(newDynamicModuleChildListOrder);
            }

            dynamicModuleChildListOrderProperty.Value = JSON.stringify(newDynamicModuleChildListOrderArray);
        }
    }

    private modifySearchSettingsBeforeSave(properties: any[]): void {
        const searchSettingsProperty = properties.find(x => x.Name === ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS);
        if (searchSettingsProperty && searchSettingsProperty.Value && searchSettingsProperty.Value.length > 0) {
            const newSearchSettingsObject = {};
            for (let i = 0; i < searchSettingsProperty.Value.length; i++) {
                // the content type comes as an array with 1 value
                const parentEntitySetName = searchSettingsProperty.Value[i].ContentType[0];
                if (newSearchSettingsObject.hasOwnProperty(parentEntitySetName)) {
                    throw new ConfigValidationError(ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS, "Duplicate content types are not allowed");
                }

                const fields = searchSettingsProperty.Value[i].Fields;
                newSearchSettingsObject[parentEntitySetName] = fields;
            }

            searchSettingsProperty.Value = JSON.stringify(newSearchSettingsObject);
        }
    }
}

export const BACKEND_INTERFACE_SETTINGS_CONFIG_EXTENDER: ClassProvider = {
    multi: true,
    provide: CONFIG_EXTENDER_TOKEN,
    useClass: BackendInterfaceSettingsConfigExtender
};
