import { ODataError } from "./odata-error";
import { GenericError } from "./generic-error";

/**
 * Contains information regarding the error from a response to a failed HTTP request.
 *
 * @export
 * @class ResponseError
 */
export class ResponseError extends GenericError {
    public readonly statusCode: number;

    /**
     * Creates an instance of ResponseError.
     * @param {string} code - The error code.
     * @param {string} message - The error message.
     * @param {*} [data] - The full error data.
     *
     * @memberOf ResponseError
     */
    constructor(error: ODataError) {
        super(error.message, error.code);
        this.statusCode = error.status || 0;
    }
}
