import { Inject, Injectable, OnDestroy } from "@angular/core";
import { BehaviorSubject, Observable, Subject } from "rxjs";
import { WINDOW_TOKEN } from "../../../window.provider";
import { KeyboardShortcutsComponent } from "../keyboard-shortcuts/keyboard-shortcuts.component";
import { UserPreferencesComponent } from "../user-preferences/user-preferences.component";
import { Button, DialogData } from "./modal-window.service";
import { NotificationsComponent } from "../notifications/notifications.component";
import { NotificationsService, NOTIFY_ME_FOR_UPDATES_FOR } from "../notifications/notifications.service";
import { NotificationsPreferencesComponent } from "../notifications/preferences/notifications-preferences.component";
import { NOTIFICATIONS_PREFERENCES_EVENT, NOTIFICATIONS_EVENT, USER_PREFERENCES_EVENT, KEYBOARD_SHORTCUTS_EVENT, NOTIFICATIONS_SITE_SYNC_EVENT } from "../../../constants/integrated-mode-constants";
import { SiteSyncNotificationComponent } from "../components/site-sync/site-sync.notification.component";
import { SiteSyncResultMapper } from "../components/site-sync/mappers/site-sync-result-mapper";
import { ComponentData } from "@progress/sitefinity-component-framework";

@Injectable()
export class HeaderMenuService implements OnDestroy {
    public get onUserDialogOpen(): Observable<DialogData> {
        return this._onUserDialogOpen.asObservable();
    }

    private _onUserDialogOpen: Subject<DialogData> = new Subject<DialogData>();
    private userPreferencesListener: EventListener;
    private keyboardShortcutsListener: EventListener;
    private notificationsListener: EventListener;
    private notificationsPreferencesListener: EventListener;
    private siteSyncNotificationsListener: EventListener;
    private actionList: HeaderMenuAction[] = [];

    constructor(@Inject(WINDOW_TOKEN) private windowProvider: Window, private notificationsService: NotificationsService) {
        this.attachListeners();
    }

    ngOnDestroy() {
        this.actionList.forEach(actionItem => this.windowProvider.removeEventListener(actionItem.customEventName, actionItem.customEventListener));
    }

    private attachListeners() {
        this.userPreferencesListener = () => this._onUserDialogOpen.next(this.setDialogData(UserPreferencesComponent, "User preferences", "user-preferences"));
        this.keyboardShortcutsListener = () => this._onUserDialogOpen.next(this.setDialogData(KeyboardShortcutsComponent, "Keyboard shortcuts", "keyboard-shortcuts"));
        this.notificationsListener = () => this._onUserDialogOpen.next(this.notificationsService.createNotificationsDialogData(NotificationsComponent, null, "notifications"));
        this.notificationsPreferencesListener = () => this._onUserDialogOpen.next(this.notificationsService.getDialogData(NotificationsPreferencesComponent, NOTIFY_ME_FOR_UPDATES_FOR, "notifications-preferences"));
        this.siteSyncNotificationsListener = (event: CustomEvent) => this._onUserDialogOpen.next(this.getSiteSyncDialogData(event.detail.syncSummaryId, event.detail.count, "site-sync-notification"));

        this.actionList.push({ customEventName: NOTIFICATIONS_SITE_SYNC_EVENT, customEventListener: this.siteSyncNotificationsListener });
        this.actionList.push({ customEventName: NOTIFICATIONS_PREFERENCES_EVENT, customEventListener: this.notificationsPreferencesListener });
        this.actionList.push({ customEventName: NOTIFICATIONS_EVENT, customEventListener: this.notificationsListener });
        this.actionList.push({ customEventName: USER_PREFERENCES_EVENT, customEventListener: this.userPreferencesListener });
        this.actionList.push({ customEventName: KEYBOARD_SHORTCUTS_EVENT, customEventListener: this.keyboardShortcutsListener });
        this.actionList.forEach(actionItem => this.windowProvider.addEventListener(actionItem.customEventName, actionItem.customEventListener));
    }

    private setDialogData(componentType: any, title: string, key: string, buttons: Button[] = [], properties: any = {}): DialogData {
        const componentData: ComponentData = {
            type: componentType,
            properties: properties
        };
        const dialogData = new DialogData(componentData, null, buttons);
        dialogData.heading = { title: title };
        dialogData.key = key;
        return dialogData;
    }

    // Temporary workaround. If we inject the SiteSyncNotificationResolver in the header menu service the int tests don't execute correctly. They fail at around  1800 - 2000 with a timeout
    private getSiteSyncDialogData(syncSummaryId: string, count: number, key: string): DialogData {
        const count$ = new BehaviorSubject<number>(count);
        const componentData = this.getSiteSyncDialogComponentData(syncSummaryId, count$);
        const dialogData = new DialogData(componentData, (context: ClosingContext) => { }, [], null, "-bottom");
        dialogData.key = key;

        return dialogData;
    }

    private getSiteSyncDialogComponentData(syncSummaryId: any, count: BehaviorSubject<number>) {
        return {
            type: SiteSyncNotificationComponent,
            properties: {
                contentLook: "medium",
                actionTitle: "Synced items",
                action: `GetItemsSendForSync(summaryId=${syncSummaryId})`,
                count,
                treeConfig: {
                    description: true,
                    noSelection: true
                },
                openItemEdit: false,
                modalListMapper: new SiteSyncResultMapper()
            }
        };
    }
}

interface HeaderMenuAction {
    customEventName: string;
    customEventListener: EventListener;
}
