import { Injectable } from "@angular/core";
import { LoggerSource, Log } from "./logger-source";
import { HttpWebRequestWrapper } from "../http-web-request.wrapper";
import { REST_API_ENDPOINT, REINVENTION_SERVICE_ENDPOINT } from "../../../../common-constants";
import { LOG_WEB_CLIENT_ERROR_PATH } from "../../../../constants/integrated-mode-constants";

export const BACKEND_LOG_URL: string =  `${REST_API_ENDPOINT}${REINVENTION_SERVICE_ENDPOINT}${LOG_WEB_CLIENT_ERROR_PATH}`;

/**
 * Source that is used by the logger.
 * The logs are send to the backend endpoint.
 *
 * @export
 * @class BackendLoggerSource
 * @extends {LoggerSource}
 */
@Injectable()
export class BackendLoggerSource extends LoggerSource {
    constructor(private http: HttpWebRequestWrapper) {
        super();
    }

    /**
     * Sends the passed logs to backend.
     *
     * @template T
     * @param {T[]} logData Collection of logs that will be send to the backend.
     * @memberof BackendLoggerSource
     */
    public process(logs: Log[]) {
        const logsPayload = logs.filter(log => !!log.data.stackTrace)
                                .map(log => {
                                    return { message: log.data.message, stackTrace: log.data.stackTrace };
                                });

        if (logsPayload.length) {
            this.http.post(BACKEND_LOG_URL, logsPayload);
        }
    }
}
