import { FieldBase } from "../../../../../fields";
import { ScrollService } from "../../../services/scroll.service";
import { Directive, HostListener, Inject } from "@angular/core";
import { WINDOW_TOKEN } from "../../../window.provider";
import { Subject } from "rxjs";
import { SettingsBase } from "../../../../../fields/field-settings-base";

/**
 * Base component for components with reorderable thumbs e.g. MediaComponent, FileListComponent.
 */
@Directive()
export class ReorderableThumbsComponent<TSettings = SettingsBase> extends FieldBase<TSettings> {
    public dragIndex;
    public dropIndex;
    public dragName;
    public direction;
    public uploads = [];
    public reorderable: boolean = true;
    public dragZoneVisible: boolean;
    public hasChanges: boolean = false;

    protected verticalPosition: number = 0;
    protected skipDragScrollZones: boolean = false;

    private scrollDispatch = new Subject<number>();
    private lastScrollDispatchDate: number = Date.now();
    private _mediaItems: any[] = [];

    get mediaItems() {
        return this._mediaItems;
    }

    set mediaItems(val) {
        this._mediaItems = val;
    }

    constructor(private scrollService: ScrollService,
                @Inject(WINDOW_TOKEN) protected window: Window) {
        super();
        const scrollSubscribtion = this.scrollDispatch.subscribe((n) => {
            if (!this.skipDragScrollZones) {
                this.scrollRequested(n);
            }
        });

        this.registerSubscription(scrollSubscribtion);
    }

    onWindowScroll(event) {
        if (this.reorderable) {
            this.verticalPosition = event.currentTarget.pageYOffset;
        }

        const yOffset = this.window.pageYOffset || this.window.document.documentElement.scrollTop || this.window.document.body.scrollTop || 0;

        this.scrollDispatched(yOffset);
    }

    @HostListener("document:dragleave", ["$event"]) onLeave( e: MouseEvent ) {
        if (this.reorderable && e.target &&
            ((e.target as HTMLElement).tagName === "HTML" ||
            (e.target as HTMLElement).classList.contains("sf-modal-window__content"))) {
            this.clearDrag();
        }
    }

    onDragStart(dragIndex: number, name: string, event: any): void {
        if (!this.reorderable) {
            return;
        }

        if (!this.dragZoneVisible) {
            this.dragZoneVisible = true;
        }

        this.dragIndex = dragIndex;
        this.dropIndex = -1;
        this.dragName = name;

        const img = document.createElement("img");
        img.src = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";

        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setDragImage(img, 0, 0);
    }

    onDragOver(dropIndex: number, name: string, width: number, event): void {
        if (!this.reorderable) {
            return;
        }

        if (this.dragName === name) {
            if (event.layerX > width / 2) {
                this.direction = "after";
            } else {
                this.direction = "before";
            }

            this.dropIndex = dropIndex;

            event.dataTransfer.dropEffect = "move";
            event.preventDefault();
        }
    }

    onDragEnd(event): void {
        if (!this.reorderable) {
            return;
        }

        if (this.dragZoneVisible) {
            this.dragZoneVisible = false;
        }

        const dropIndex = this.dropIndex - this.uploads.length;
        const dragIndex = this.dragIndex - this.uploads.length;

        if (dragIndex !== dropIndex && this.dropIndex !== -1) {
            const src = this.mediaItems[dragIndex];
            const dest = this.mediaItems[dropIndex];

            this.mediaItems.splice(dragIndex, 1);

            let index = this.mediaItems.indexOf(dest);

            if (this.direction === "after") {
                index = Math.min(index + 1, this.mediaItems.length);
            }

            this.mediaItems.splice(index, 0, src);

            if (dragIndex !== index) {
                this.recalculateLayout();
            }

            // mark field as dirty
            this.writeValue(Object.assign([], this.mediaItems));
            this.hasChanges = true;
        }

        this.dragIndex = -1;
        this.dropIndex = -1;
        this.dragName = null;
        event.preventDefault();
    }

    dragOverScrollZone(pos: "top" | "bottom", event) {
        if (this.skipDragScrollZones) {
            return;
        }

        const scrollTo = this.verticalPosition + (200 * (pos === "top" ? -1 : 1));
        const currentDate = Date.now();

        if (currentDate - this.lastScrollDispatchDate > 250) {
            this.lastScrollDispatchDate = Date.now();
            if (this.verticalPosition >= 0) {
                this.verticalPosition = scrollTo;
                this.scrollDispatch.next(scrollTo);
            } else {
                this.verticalPosition = 0;
            }
        }

        event.preventDefault();
    }

    clearDrag() {
        this.dragIndex = -1;
        this.dropIndex = -1;
        this.dragName = null;
        this.dragZoneVisible = false;
    }

    /**
     * called from base in onDragEnd
     */
    protected recalculateLayout() { }

    /**
     * use for renewing the paremeters for virutalization
     */
    protected scrollDispatched(yOffset: number = 0) { }

    private scrollRequested(change: number) {
        this.scrollService.scrollToPoint(change, 0);
    }
}
