import { Injectable, Inject, Optional } from "@angular/core";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";
import { EDIT_EXTENDER_TOKEN, EditExtender, SidebarButtonComponentData } from "./edit-extender";
import { FieldSectionModel } from "../../../../services/fieldSection.model";
import { Observable, Subject, of } from "rxjs";
import { SiteData } from "../metadata/site-data.store";
import { NotificationService } from "../notification/notification.service";
import { CommonActionContext } from "../grid/grid-extender-base";
import { NavbarConfiguration } from "../../components/navigation/navigation-menu/navigation-menu.component";
import { stringConstants } from "../../../../common-constants";

@Injectable()
export class CompositeEditExtender {
    constructor(@Optional() @Inject(EDIT_EXTENDER_TOKEN) private extenders: EditExtender[]) {
    }

    overrideNavigationMenuOptions(dataItem: DataItem, options: NavbarConfiguration) {
        const extender = this.getExtender(dataItem);
        if (extender) {
            extender.overrideNavigationMenuOptions(dataItem, options);
        }
    }

    getSidebarButtons(entityData: EntityData, compDatas: SidebarButtonComponentData) {
        const extender = this.getExtender(entityData);
        if (extender) {
            return extender.getSidebarButtons(entityData, compDatas);
        }

        return null;
    }

    modify(args: ModifyFieldsArgs): Observable<void> {
        const extender = this.getExtender(args.dataItem);
        if (extender) {
            return this.getExtender(args.dataItem).modify(args);
        } else {
            return of(undefined);
        }
    }

    handleAction(context: EditActionContext, notificationService: NotificationService): ActionResult {
        const extender = this.getExtender(context.item);
        if (extender)
            return extender.handleAction(context, notificationService);

        return { handled: of(false) };
    }

    getFormClasses(entityData: EntityData) {
        const extender = this.getExtender(entityData);

        if (extender) {
            return extender.getFormClasses();
        }

        return stringConstants.EMPTY_STRING;
    }

    getActionMenuClasses(entityData: EntityData) {
        const extender = this.getExtender(entityData);

        if (extender) {
            return extender.getActionMenuClasses();
        }

        return stringConstants.EMPTY_STRING;
    }

    showHeader(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        if (extender) {
            return extender.showHeader(entityData);
        } else {
            return true;
        }
    }

    getHeader(dataItem: DataItem): string {
        return this.getExtender(dataItem)?.getHeader(dataItem);
    }

    includedProperties(entityData: EntityData): string[] {
        const extender = this.getExtender(entityData);
        if (extender) {
            return extender.includedProperties(entityData);
        } else {
            return [];
        }
    }

    excludedProperties(entityData: EntityData): string[] {
        const extender = this.getExtender(entityData);
        if (extender) {
            return extender.excludedProperties(entityData);
        } else {
            return [];
        }
    }

    hasCreateActionFromEdit(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);

        if (extender) {
            return extender.hasCreateActionFromEdit();
        }

        return null;
    }

    forceUpdateFieldModel(entityData: EntityData, selector: string, updatedDataItem: DataItem, dataItem: DataItem): boolean {
        const extender = this.getExtender(entityData);

        if (extender) {
            return extender.forceUpdateFieldModel(selector, updatedDataItem, dataItem);
        }

        return null;
    }

    getStatusToDisplay(dataItem: DataItem): any {
        const extender = this.getExtender(dataItem);

        if (extender) {
            return extender.getStatusToDisplay(dataItem);
        }

        return null;
    }

    private getExtender(entityData: EntityData): EditExtender {
        const extender = this.extenders.find(x => entityData && x.isSupportedType(entityData));
        return extender;
    }
}

export interface ModifyFieldsArgs {
    sections: FieldSectionModel[];
    dataItem: DataItem;
    parentId: string;
    isInit: boolean;
    viewName: string;
    setName: string;
}

export interface EditActionContext extends CommonActionContext {
    changedFields: any;
    siteData: SiteData;
}

export interface ActionResult {
    handled: Observable<boolean>;
    result?: Observable<DataItem>;
    closeHandler?: Subject<void>;
}
