import { SettingsBase } from "./../field-settings-base";
import { RegexHelper } from "./../../src/app/utils";
import { Validators, ValidatorFn } from "@angular/forms";
import { VALIDATORS as CustomValidators, VALIDATOR_NAMES } from "../common/validators";
import { VALIDATION_REGEX } from "../common/common-constants";
import { SHORT_TEXT_PLACEHOLDER, SHORT_TEXT_UNIT, SHORT_TEXT_UNIT_LOOK, SHORT_TEXT_UNIT_POSITION } from "./short-text.constants";
import {
    FIELD_VALIDATION_PREFIX, VALIDATION_MAX_VALUE, VALIDATION_MIN_VALUE,
    VALIDATION_REQUIRED
} from "../common/common-constants";

const EMPTY_SPACE_REGEX = ".*\\S.*";
export const MIRROR_FIELD_SETTING_KIND = "mirrorFieldSettingsKind";

export class ShortTextSettings extends SettingsBase implements MirrorFieldSettings {

    /**
     * Retrieves an array of angular validators per field, depending on set validation rules in metadata, if any
     *
     * @param {Object} metadata - field's metadata
     * @returns {ValidatorFn} - array of Validators, presented in ValidatorFn
     */

    public shortTextValidatorMap;
    public placeholder: string;
    public unitLook: string;
    public unitPosition: string;
    public mirroredFieldName: string;
    public mirroredFieldProperty: string;
    public enableMirroring: boolean;
    public kind: string = MIRROR_FIELD_SETTING_KIND;
    public shouldBeFocusedByDefault: boolean = true;

    public init(metadata: any): void {
        super.init(metadata);
        this.placeholder = metadata[SHORT_TEXT_PLACEHOLDER];
        this.unit = metadata[SHORT_TEXT_UNIT];
        this.unitLook = metadata[SHORT_TEXT_UNIT_LOOK];
        this.unitPosition = metadata[SHORT_TEXT_UNIT_POSITION];
    }

    constructor(public key: string, public readOnlyMode: boolean) {
        super(key, readOnlyMode);
        this.shortTextValidatorMap = new Map<string, ValidatorFn>();
        this.shortTextValidatorMap.set(VALIDATION_REQUIRED, () => this.createPatternValidator(EMPTY_SPACE_REGEX));
        this.shortTextValidatorMap.set(VALIDATION_REGEX, (value: any) => this.createPatternValidator(value));
        this.shortTextValidatorMap.set(VALIDATION_MAX_VALUE, (value: any) => Validators.maxLength(value));
        this.shortTextValidatorMap.set(VALIDATION_MIN_VALUE, (value: any) => CustomValidators[VALIDATOR_NAMES.MIN_LENGTH](value));
    }

    public getValidators(metadata: any) {
        const baseValidators = super.getValidators(metadata);
        const validatorDictionary = this.getValidatorDictionary(metadata);

        for (const key in validatorDictionary) {
            if (validatorDictionary.hasOwnProperty(key)) {
                baseValidators.push(validatorDictionary[key]);
            }
        }

        return baseValidators;
    }

    public getValidatorDictionary(metadata: any): { [key: string]: ValidatorFn } {
        const dictionary = {};
        for (const key in metadata) {
            if (metadata.hasOwnProperty(key)) {
                if (key.includes(FIELD_VALIDATION_PREFIX)) {
                    if (this.shortTextValidatorMap.has(key)) {
                        const value = metadata[key];
                        dictionary[key] = this.shortTextValidatorMap.get(key)(value);
                    }
                }
            }
        }

        return dictionary;
    }

    protected createPatternValidator(regex: string | RegExp) {
        if (typeof regex === "string") {
            regex = RegexHelper.buildRegex(regex);
        }

        const validator = Validators.pattern(regex);
        return validator;
    }
}

export interface MirrorFieldSettings {
    kind: string;
    mirroredFieldName: string;
    mirroredFieldProperty?: string;
    enableMirroring: boolean;
    prefix?: string;
}

export function isMirrorFieldSettings(settings: any): settings is MirrorFieldSettings {
    return settings.kind === MIRROR_FIELD_SETTING_KIND;
}

export class ShortTextDefaultSettings extends ShortTextSettings {
    constructor(public key: string, public readOnlyMode: boolean) {
        super(key, readOnlyMode);
        this.underlineErrors = true;
    }
}
