import { Injectable } from "@angular/core";
import { ContentItemInfo } from "../interfaces/content-item-info";
import { HttpODataRequestWrapper } from "../../services/http-odata-request.wrapper";
import { from, Observable } from "rxjs";

@Injectable()
export class SitefinityRequesterService {

    constructor(private http: HttpODataRequestWrapper) {
    }

    getContentItemsDetails(culture: string, itemInfo: ContentItemInfo): Observable<any> {
        const url = `${itemInfo.SfSetName}(${itemInfo.Id})?sf_culture=${culture}&sf_provider=${itemInfo.Provider}`;
        return from(this.http.get(url));
    }
}
