import { combineLatest, of as observableOf, of } from "rxjs";

import { InjectionToken, Inject, Injectable, Optional } from "@angular/core";
import { ColumnModel } from "../../../shared/models/column-model";
import { Observable } from "rxjs";
import { EntityData } from "../interfaces";
import { Logger } from "../../../shared/services/logger-source/logger";
import { flatDeep } from "../../../../utils";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { MainFieldComponent } from "./grid-cells/main-field/main-field.component";
import { map } from "rxjs/operators";

export const COLUMNS_TOKEN = new InjectionToken("columns_token");

/**
 * A columns provider to provide columns for the list view of the content screen.
 * @ExposedInApi {ColumnsProvider} ColumnsProvider v1/index-component/columns-provider.d.ts
 * @ExposedInApi {ColumnsProvider} ListColumnsProvider v1/index-component/columns-provider.d.ts
 */
export interface ColumnsProvider {
    /**
     * Gets an observable collection of columns.
     */
    getColumns(entityData: EntityData): Observable<ColumnModel[]>;

    /**
     * Gets an obaservable collection of columns to be removed.
     */
    getColumnsToRemove(entityData: EntityData): Observable<string[]>;
}

export const RESERVED_COLUMN_NAMES = Object.freeze({
    Page: "Page"
});

export const MAIN_COLUMN_NAME = "Main";
export const TRANSLATIONS_COLUMN_NAME = "Translations";

export const COLUMN_ORDINALS = {
    // The Main (Title) column must always be the left most column (UX requirement)
    MAIN_COL_ORDINAL: Number.MIN_SAFE_INTEGER,
    // The Actions column must always be the right most column (UX requirement)
    ACTIONS_COL_ORDINAL: Number.MAX_SAFE_INTEGER,
    // The Sitefinity Insigth (DEC) column must must always be to the left ot the Analytics column, hence the -2 (UX requirement)
    INSIGHT_COL_ORDINAL: Number.MAX_SAFE_INTEGER - 2
};

export const COLUMN_NAMES = {
    INSIGHTS_COL_NAME: "Insight",
    ACTIONS_COL_NAME: "Actions",
    LETTER_COL_NAME: "Letter",
    MAIN_COL_NAME: "Main",
    TAXA_MAIN_COL_NAME: "TaxaMain",
    TITLE_STATUS_COL_NAME: "TitleStatus",
    ALBUMS_MAIN_COL_NAME: "AlbumsMain",
    MEDIA_TITLE_STATUS_COL_NAME: "MediaTitleStatus",
    DOCUMENTS_LIBRARY_MAIN_COL_NAME: "DocumentsLibraryMain",
    VIDEOS_LIBRARY_MAIN_COL_NAME: "VideosLibraryMain",
    PAGE_TEMPLATES_MAIN_COL_NAME: "PageTemplatesMain",
    RESPONSES_COLUMN_COL_NAME: "ResponsesColumn",
    TRANSLATIONS: "Translations"
};

/**
 * The CompositeColumnsProvider class works with all of the columns providers and combines their columns into a single
 * column array.
 */
@Injectable()
export class CompositeColumnsProvider implements ColumnsProvider {

    /**
     * Initializes a new instance of the CompositeColumnsProvider class.
     * @param columnProviders The injected column providers.
     */
    constructor(@Optional() @Inject(COLUMNS_TOKEN) private columnProviders: Array<ColumnsProvider>, private logger: Logger) { }

    /**
     * Gets the columns from all of the providers.
     * @param type The type for which to get the columns for.
     */
    getColumns(entityData: EntityData): Observable<ColumnModel[]> {
        if (this.columnProviders) {
            // TODO: cache
            return this.initColumns(entityData);
        }

        return observableOf([]);
    }

    getColumnsToRemove(entityData: EntityData): Observable<string[]> {
        return observableOf([]);
    }

    private initColumns(entityData: EntityData): Observable<ColumnModel[]> {
        const columnsArr$ = this.columnProviders.map(x => x.getColumns(entityData));

        const columnsToRemoveArr$ = this.columnProviders.map(x => x.getColumnsToRemove ? x.getColumnsToRemove(entityData) : of([]));

        const columnsToRemove$ = combineLatest<string[][]>(columnsToRemoveArr$);
        const columns$ = combineLatest<ColumnModel[][]>(columnsArr$);

        return combineLatest([columns$, columnsToRemove$])
            .pipe(map((resolvedColumnArrays) => {
                const columns = this.mergeColumns(resolvedColumnArrays, entityData.metadata.setName);
                return columns;
            }));
    }

    private mergeColumns(columnArrayPairs: [ColumnModel[][], string[][]], setName: string): ColumnModel[] {
        const columnsToAdd = flatDeep<ColumnModel>(columnArrayPairs[0]);
        const columnsToRemove = flatDeep<string>(columnArrayPairs[1]);
        let columns: ColumnModel[] = [];
        columnsToAdd.forEach((column, index) => {
            if (this.isColumnValid(column, columns) && !this.shouldRemoveColumn(columnsToRemove, column)) {
                column.ordinal = this.handleColumnOrdinal(column, setName, index);
                columns.push(column);
            }
        });

        columns = columns.sort((left, right) => left.ordinal - right.ordinal);

        return columns;
    }

    private shouldRemoveColumn(columnsToRemove: string[], currentColumn: ColumnModel): boolean {
        const nonRemovableColumns = [
            COLUMN_NAMES.ACTIONS_COL_NAME,
            COLUMN_NAMES.LETTER_COL_NAME,
            COLUMN_NAMES.MAIN_COL_NAME,
            COLUMN_NAMES.TAXA_MAIN_COL_NAME,
            COLUMN_NAMES.TITLE_STATUS_COL_NAME,
            COLUMN_NAMES.ALBUMS_MAIN_COL_NAME,
            COLUMN_NAMES.MEDIA_TITLE_STATUS_COL_NAME,
            COLUMN_NAMES.DOCUMENTS_LIBRARY_MAIN_COL_NAME,
            COLUMN_NAMES.VIDEOS_LIBRARY_MAIN_COL_NAME,
            COLUMN_NAMES.PAGE_TEMPLATES_MAIN_COL_NAME
        ];

        const isCurrentColSetToBeRemoved = columnsToRemove.some(c => c === currentColumn.name);
        const isCurrentColRemovable = !nonRemovableColumns.includes(currentColumn.name);

        if (!isCurrentColRemovable && isCurrentColSetToBeRemoved) {
            this.logger.warn(`Column with name ${currentColumn.name} cannot be removed.`);
        }

        return isCurrentColRemovable && isCurrentColSetToBeRemoved;
    }

    private isColumnValid(column: ColumnModel, existingColumns: ColumnModel[]): boolean {
        const hasReservedColumnName = RESERVED_COLUMN_NAMES.hasOwnProperty(column.name);
        if (hasReservedColumnName) {
            this.logger.warn(`Custom column with name ${column.name} is reserved. Please choose another.`);
            return false;
        }

        if (existingColumns.find(x => x.name === column.name)) {
            this.logger.warn(`Custom column with name ${column.name} is already taken. Please choose another.`);
            return false;
        }

        return true;
    }

    private handleColumnOrdinal(column: ColumnModel, setName: string, placeInQueue: number): number {
        const columnRules: ColumnRule[] = [new FlatTaxaColumnRules(), new UxColumnRules(), new DefaultColumnRules()];

        for (const rule of columnRules) {
            if (rule.handle(column, setName)) {
                break;
            }
        }

        return column.ordinal;
    }
}

class FlatTaxaColumnRules implements ColumnRule {
    // By UX design, in the flat taxa, the leftmost column is the "Letter" column, therefore the title column becomes second
    handle(column: ColumnModel, entitySet?: string): boolean {
        if (entitySet === ENTITY_SET.FLAT_TAXA) {

            if (column.name === COLUMN_NAMES.LETTER_COL_NAME) {
                column.ordinal = COLUMN_ORDINALS.MAIN_COL_ORDINAL;
                return true;
            }

            const isMainColumn = column.componentData?.type && column.componentData?.type === MainFieldComponent;
            if (isMainColumn) {
                column.ordinal = COLUMN_ORDINALS.MAIN_COL_ORDINAL + 1;
                return true;
            }

            return false;
        }
    }

}

class UxColumnRules implements ColumnRule {
    handle(column: ColumnModel): boolean {
        const isMainColumn = column.componentData?.type && column.componentData?.type === MainFieldComponent;
        if (isMainColumn) {
            column.ordinal = COLUMN_ORDINALS.MAIN_COL_ORDINAL;
            return true;
        } else if (column.name === COLUMN_NAMES.INSIGHTS_COL_NAME) {
            column.ordinal = COLUMN_ORDINALS.INSIGHT_COL_ORDINAL;
            return true;
        } else if (column.name === COLUMN_NAMES.ACTIONS_COL_NAME) {
            column.ordinal = COLUMN_ORDINALS.ACTIONS_COL_ORDINAL;
            return true;
        }
        return false;
    }
}

class DefaultColumnRules implements ColumnRule {
    handle(column: ColumnModel): boolean {
        if (column.ordinal) {
            // must ensure that the numbers are whole so noone can insert a column between the
            // Sitefinity insight > Analitics > Actions columns
            const rightMostColumns = [COLUMN_NAMES.INSIGHTS_COL_NAME, COLUMN_NAMES.ACTIONS_COL_NAME];
            column.ordinal = Math.trunc(column.ordinal);
            const isMainColumn = column.componentData?.type && column.componentData?.type === MainFieldComponent;

            if (column.ordinal >= COLUMN_ORDINALS.INSIGHT_COL_ORDINAL && !rightMostColumns.includes(column.name)) {
                // The '-1' comes from the UX reqirement for column arrangement; The right most colomn must be the Actions column;
                // before the Actions column comes the Analytics column and before it comes the Sitefinity Insights column
                column.ordinal = COLUMN_ORDINALS.INSIGHT_COL_ORDINAL - 1;
                return true;
            } else if (column.ordinal <= COLUMN_ORDINALS.MAIN_COL_ORDINAL && !isMainColumn) {
                // The '+1' comes from the UX reqirement for column arrangement; The left most colomn must be the Main column;
                column.ordinal = COLUMN_ORDINALS.MAIN_COL_ORDINAL + 1;
                return true;
            }
        }

        return false;
    }

}

abstract class ColumnRule {
    abstract handle(column: ColumnModel, entitySet?: string): boolean;
}
