import { ClassProvider, Inject, Injectable } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { Observable, of } from "rxjs";
import { map } from "rxjs/operators";
import { DataItem, OperationResult } from "../../../../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { BulkOperationResult } from "../../../../content/dynamic-modules/services/operations/commands/bulk-command";
import { ExecutionContext } from "../../../../shared/commands/execution-context";
import { ActionButton } from "../../../../shared/components/action-menu/action-menu-model";
import { OPERATION_NAMES } from "../../../../shared/components/action-menu/operation.model";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { ModalWindowService } from "../../../../shared/services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../shared/services/notification/notification.service";
import { LockLayoutCommand } from "../../../commands/lock-layout.command";
import { TemplateShareWithCommand } from "../../../commands/template-share-with.command";
import { CLASS_MODIFIER_NO_BORDER, CLASS_MODIFIER_NO_OUTLINE, CLASS_MODIFIER_ROOT } from "../../../services/document-enhancer.constants";
import { ChangeTemplateCommand } from "../../edit-page/commands/change-template.command";
import { ZoneEditorBaseExtender, ZONE_EDITOR_EXTENDER_TOKEN } from "./zone-editor-base-extender";

@Injectable()
export class ZoneEditorTemplatesExtender extends ZoneEditorBaseExtender {
    constructor(private modalWindowService: ModalWindowService,
                private dynamicItemStore: DynamicItemStore,
                @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService) {
        super();
    }
    canHandle(typeSetName: string): boolean {
        return typeSetName === ENTITY_SET.TEMPLATES;
    }

    handleAction(action: ActionButton, dataItem: DataItem, route: ActivatedRoute): Observable<BulkOperationResult> {
        switch (action.name) {
            case OPERATION_NAMES.template:
                return this.handelChangeTemplate(dataItem, route);
            case OPERATION_NAMES.shareWith:
                return this.shareWith(dataItem, route);
            case OPERATION_NAMES.lockLayout:
                return this.lockLayout(dataItem, true);
            case OPERATION_NAMES.unlockLayout:
                return this.lockLayout(dataItem, false);
        }

        return of(null);
    }

    getEmptyRootCssClasses(): string[] {
        return [CLASS_MODIFIER_ROOT, CLASS_MODIFIER_NO_OUTLINE, CLASS_MODIFIER_NO_BORDER];
    }

    private handelChangeTemplate(dataItem: DataItem, route: ActivatedRoute):  Observable<BulkOperationResult> {
        const ctx: ExecutionContext = {
            currentRoute: route,
            data: {
                selectedItems: [dataItem],
                entityData: dataItem
            },
            model: null
        };
        const command = new ChangeTemplateCommand(this.modalWindowService, this.dynamicItemStore, this.notificationService);
        return command.execute(ctx);
    }

    private shareWith(dataItem: DataItem, route: ActivatedRoute): Observable<BulkOperationResult> {
        const ctx: ExecutionContext = {
            currentRoute: route,
            data: {
                entityData: dataItem
            },
            model: null
        };

        const command = new TemplateShareWithCommand(this.dynamicItemStore.service, this.modalWindowService);
        return command.execute(ctx).pipe(map(x => {
            x.reload = false;
            return x;
        }));
    }

    private lockLayout(dataItem: DataItem, lockLayout: boolean): Observable<OperationResult> {
        const ctx: ExecutionContext = {
            currentRoute: null,
            data: {
                entityData: dataItem,
                lock: lockLayout
            },
            model: null
        };

        const command = new LockLayoutCommand(this.dynamicItemStore.service, this.notificationService);
        return command.execute(ctx);
    }
}

export const ZONE_EDITOR_TEMPLATES_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: ZONE_EDITOR_EXTENDER_TOKEN,
    useClass: ZoneEditorTemplatesExtender
};
