import { EntityData } from "../../content/dynamic-modules/interfaces";
import { Injectable } from "@angular/core";
import { KeyValuePair, ExtendedKeyValuePair } from "../../../../../fields/services/base.service";
import { CHARACTERS, QUERY_PARAMS, FILTER_PARAMS, ACTIONS } from "../../content/constants";
import { stringConstants, STARTS_WITH_CHARS } from "../../../common-constants";
import { MetadataStore } from "./metadata/meta-data.store";
import { createQuery } from "../../../services/query";
import { LoadItemsData } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ExternalAppConfigService } from "../../../app-config/external-app-config.service";
import { Properties } from "../fields.constants";
import { MetadataParserService } from "./metadata/meta-data-parser.service";
import { FieldTypes } from "../fields-builder/services/fields-registry";
import { ENTITY_SET } from "./metadata/meta-data-constants";

@Injectable()
export class ContentFilterService {
    constructor(
        private metaStore: MetadataStore,
        private configService: ExternalAppConfigService,
        private metadataParserService: MetadataParserService) { }

    buildSearchFilter(entityData: EntityData, searchTerm: string): ExtendedKeyValuePair[] {
        const searchFields = this.getSearchFields(entityData);
        return searchFields.map(searchField => ({
            key: searchField.fieldName,
            value: [searchTerm],
            searchMode: ContentFilterService.getSearchMode(searchField, entityData),
            caseSensitive: ContentFilterService.getIsSearchCaseSensitive(entityData)
        }));
    }

    getSearchFields(entityData: EntityData): SearchField[] {
        const setname = entityData.metadata.setName;

        const searchSettings = this.configService.externalConfig?.searchSettings;
        const searchFields = searchSettings && searchSettings[setname] ? searchSettings[setname] : [];
        const filteredFields = this.filterSearchFields(searchFields, entityData);

        return filteredFields.length > 0 ? filteredFields : [{ fieldName: entityData.metadata.defaultFieldName, fieldType: FieldTypes.shortTextDefault }];
    }

    getSearchFieldsAsString(entityData: EntityData): string {
        return this.getSearchFields(entityData).map(x => x.fieldName).join(",");
    }

    applySearch(searchTerm: string, entityData: EntityData, query) {
        const searchFields = this.getSearchFields(entityData);

        query = query.or();

        searchFields.forEach(field => {
            const searchMode = ContentFilterService.getSearchMode(field, entityData);
            query = ContentFilterService.applySearchForField(searchTerm, field.fieldName, query, searchMode);
        });

        query = query.done();

        return query;
    }

    // caseSensitive is used to tell the SDK if tolower should be added to the odata query.
    // Currently we don't add it by default but the search is case insensitive nevertheless. This is because of the SQL collation we use.
    // However if the object is in memory the OData filtration won't be case insensitive so we need to use the paramater
    static applySearchForField(searchTerm: string, searchField: string, query, searchMode: SearchMode = SearchMode.startsWith, caseSensitive: boolean = true) {
        let applyFn: (expressionParam: KeyValuePair, query, caseSensitive: boolean) => any;

        switch (searchMode) {
            case SearchMode.startsWith:
                applyFn = this.applyStartsWith;
                break;
            case SearchMode.equals:
                applyFn = this.applyEquals;
                break;
            case SearchMode.contains:
                applyFn = this.applyContains;
                break;
        }

        query = applyFn({ key: searchField, value: [searchTerm] }, query, caseSensitive);

        return query;
    }

    deserializeQueryParams(filterParam): KeyValuePair[] {
        const pairs: KeyValuePair[] = [];
        if (filterParam) {
            const filters = filterParam.split(CHARACTERS.SEMICOLON).filter(x => x !== stringConstants.EMPTY_STRING);
            for (const filter of filters) {
                const segments: string[] = filter.split(CHARACTERS.COMMA);

                const key = segments[0];
                const value = segments.slice(1);

                pairs.push({ key, value });
            }
        }

        return pairs;
    }

    serializeQueryParams(filterData) {
        const keys: string[] = Object.keys(filterData);
        const segments: string[] = [];
        for (const key of keys) {
            if (filterData[key] && filterData[key].length) {
                const segment = `${key}${CHARACTERS.COMMA}${filterData[key].join(CHARACTERS.COMMA)}`;
                segments.push(segment);
            }
        }

        return segments.join(CHARACTERS.SEMICOLON);
    }

    getLoadArguments(queryParams: any, parentId: string, entityData: EntityData, order?: string, dataFieldNames: string[] = null, additionalQueryParams: { [k: string]: string } = null): LoadItemsData {
        const sortParameter = order || queryParams[QUERY_PARAMS.SORT];
        const searchParameter = { type: FILTER_PARAMS.SEARCH, value: queryParams[FILTER_PARAMS.SEARCH] };
        const filterParameter = { type: FILTER_PARAMS.FILTER, value: queryParams[FILTER_PARAMS.FILTER] };

        const filters = [searchParameter, filterParameter].filter(f => f.value);

        const filterParams = { filters, parentId, parentIdPropery: entityData.metadata.parentIdProperty };
        return this.applyFilter(sortParameter, filterParams, entityData, dataFieldNames, additionalQueryParams);
    }

    private static getSearchMode(searchField: SearchField, entityData: EntityData): SearchMode {
        // The search should be contains only for the title field of media items
        if (entityData.metadata.isMedia && searchField.fieldName === Properties.TITLE) {
            return SearchMode.contains;
        }

        // The search should be contains for all long text fields, because otherwise the markup breaks the search.
        // If you search "some word" and the long text field contains <p>some word</p>, without contains no results will be found.
        // Url fields should be with contains because the content in those fields is one string with delimiters and doesn't contain spaces.
        if (searchField.fieldType === FieldTypes.longText ||
            searchField.fieldType === FieldTypes.textArea ||
            searchField.fieldType === FieldTypes.html ||
            searchField.fieldType === FieldTypes.urlName) {
            return SearchMode.contains;
        }

        return SearchMode.startsWith;
    }

    private static getIsSearchCaseSensitive(entityData: EntityData): boolean {
        return entityData.metadata.setName !== ENTITY_SET.PIPE_SETTINGS;
    }

    private filterSearchFields(searchFields: string[], entityData: EntityData): SearchField[] {
        const result: SearchField[] = [];

        searchFields.forEach(searchField => {
            // The field is removed from the content type but is still presented in the search config
            // or the config contains invalid field
            if (!entityData.metadata.properties[searchField]) {
                return false;
            }

            // Currently only text fields are supported for search
            const fieldType = this.metadataParserService.getPropertyFieldType(entityData.metadata, entityData.metadata.properties[searchField], null, searchField, null);
            if ((fieldType === FieldTypes.shortText ||
                fieldType === FieldTypes.shortTextDefault ||
                fieldType === FieldTypes.longText ||
                fieldType === FieldTypes.textArea ||
                fieldType === FieldTypes.html ||
                fieldType === FieldTypes.urlName) &&
                entityData.metadata.isFilteringAllowed(searchField)) {
                result.push({ fieldName: searchField, fieldType });
            }
        });

        return result;
    }

    private applyFilter(order: string, filterParams: FilterParams, entityData: EntityData, dataFieldNames: string[] = null, additionalQueryParams: { [k: string]: string } = null): LoadItemsData {
        let isFilterApplied = false;
        let query: any = createQuery();
        let action: string;

        if (filterParams && (filterParams.filters.length || filterParams.parentId)) {
            query = query.where().and();
            isFilterApplied = true;
        }

        if (filterParams && filterParams.parentId) {
            query = query.eq(filterParams.parentIdPropery, filterParams.parentId);
        }

        if (filterParams && filterParams.filters.length) {
            filterParams.filters.forEach(singleFilter => {
                switch (singleFilter.type) {
                    case FILTER_PARAMS.FILTER:
                        action = ACTIONS.FILTER(singleFilter.value);
                        break;
                    case FILTER_PARAMS.SEARCH: {
                        const pairs = this.deserializeQueryParams(singleFilter.value);
                        const search = pairs[0].value[0];
                        query = this.applySearch(search, entityData, query);

                        break;
                    }
                }
            });
        }

        if (isFilterApplied) {
            query = query.done().done();
        }

        const loadItemsArg: LoadItemsData = {
            entityData,
            action,
            order,
            fallbackProperties: [entityData.metadata.defaultFieldName],
            query,
            dataFieldNames,
            additionalQueryParams
        };

        if (dataFieldNames) {
            entityData.metadata.relations.forEach(x => {
                const relatedItem = this.metaStore.getValue().entities[x.setName];
                if (dataFieldNames.indexOf(x.propName) > -1) {
                    loadItemsArg.fallbackProperties.push(`${x.propName}.${relatedItem.defaultFieldName}`);
                }
            });
        }

        return loadItemsArg;
    }

    private static applyEquals(expressionParam: KeyValuePair, query) {
        if (expressionParam.value[0]) {
            const searchParameter = expressionParam.value[0].trim();
            query = query.eq(expressionParam.key, searchParameter);
        }

        return query;
    }

    private static applyContains(expressionParam: KeyValuePair, query, caseSensitive: boolean = true) {
        if (expressionParam.value[0]) {
            const searchParameter = expressionParam.value[0].trim();
            query = query.contains(expressionParam.key, searchParameter, caseSensitive);
        }

        return query;
    }

    private static applyStartsWith(expressionParam: KeyValuePair, query, caseSensitive: boolean = true) {
        if (expressionParam.value[0]) {
            const searchParameter = expressionParam.value[0].trim();
            query = query.startsWith(expressionParam.key, searchParameter, caseSensitive);

            STARTS_WITH_CHARS.forEach(char => {
                const containsParameter = `${char}${searchParameter}`;
                query = query.contains(expressionParam.key, containsParameter, caseSensitive);
            });
        }

        return query;
    }
}

export enum SearchMode {
    startsWith,
    contains,
    equals
}

interface FilterParams {
    parentId: string;
    parentIdPropery: string;
    filters: {
        type: string,
        value: string
    }[];
}

interface SearchField {
    fieldName: string;
    fieldType: string;
}
