// TODO: we should return some sort of indicator wheter a field is persistent - not identifier and not auto-populated on the server as well
// maybe we can use the Permissions enumeration`
const EXCLUDE_FORM_FIELDS_MAP = new Set<string>()
    .add(Properties.ID)
    .add(Properties.LAST_MODIFIED)
    .add(Properties.PUBLICATION_DATE)
    .add(Properties.EXPIRATION_DATE)
    .add(Properties.DATE_CREATED)
    .add(Properties.LOCKED_STATUS)
    .add(Properties.LAST_MODIFIED_BY)
    .add(Properties.CREATED_BY)
    .add(Properties.FIRST_PUBLISHED);

export const DYNAMIC_ITEMS_DEFINITIONS = {
    DYNAMIC_TYPES_MODEL: "#/definitions/Telerik.Sitefinity.DynamicTypes.Model",
    NEWS_ITEM: "#/definitions/Telerik.Sitefinity.News.Model.NewsItem",
    EVENT: "#/definitions/Telerik.Sitefinity.Events.Model.Event",
    BLOG_POST: "#/definitions/Telerik.Sitefinity.Blogs.Model.BlogPost",
    PAGE_NODE: "#/definitions/Telerik.Sitefinity.Pages.Model.PageNode"
};

interface MirrorRegistration {
    dynamicallyResolved?: boolean;
    key: string;
    type: string;
    fallback?: string;
    prefix?: string
}
// this constant is used as a key in the MIRROR_MAP dictionary to mark fields
// that should be mirrored from the first text field in the UI.
// This string value is later replaced with the real field name that should be mirrored.
const FIRST_TEXT_FIELD = "FTF";
const SEO_TITLE = "SeoTitle";
const SEO_DESCRIPTION = "SeoDescription";

const MIRROR_MAP: { [key: string]: MirrorRegistration } = {
    [Properties.URL_NAME]: { key: DEFAULT_FIELD, dynamicallyResolved: true, type: FieldTypes.urlName },
    "Name": { key: DEFAULT_FIELD, dynamicallyResolved: true, type: FieldTypes.urlName },
    "MetaTitle": { key: DEFAULT_FIELD, dynamicallyResolved: true, type: FieldTypes.shortText },
    "HtmlTitle": { key: DEFAULT_FIELD, dynamicallyResolved: true, type: FieldTypes.shortText },
    "OpenGraphTitle": { key: SEO_TITLE, dynamicallyResolved: false, type: FieldTypes.shortText, fallback: DEFAULT_FIELD },
    "MetaDescription": { key: FIRST_TEXT_FIELD, dynamicallyResolved: false, type: FieldTypes.textArea },
    "OpenGraphDescription": { key: SEO_DESCRIPTION, dynamicallyResolved: false, type: FieldTypes.textArea, fallback: FIRST_TEXT_FIELD }
};
const NAVIGATE_TO_URL = "NavigateToUrl";

@Injectable()
export class MetadataParserService {
    private mirrorMap: { [key: string]: MirrorRegistration } = JSON.parse(JSON.stringify(MIRROR_MAP));

    constructor(private sdk: SitefinitySdk,
                private store: MetadataStore,
                private fieldsProvider: CompositeFieldsProvider,
                @Inject(MetadataHandler) private metadataHandlers: MetadataHandler[]) { }

    getFieldsDefinition(metadata: Entity, tweaks: FormData[], dataItem: any = null, readonlyField: boolean = false, onlyLocalizable: boolean = false): FieldModel[] {
        this.resetMirrorMap(metadata);
        const fields: FieldModel[] = [];

        const defaultProperty = metadata.properties[DEFAULT_FIELD];

        this.updateMediaFields(fields, metadata, tweaks, readonlyField);

        const properties = Object.keys(metadata.properties);
        const fieldTypesMap = this.getFieldTypesMap(properties, tweaks, metadata, defaultProperty);
        const processedProperties = [];

        properties.forEach(property => {

            // no need to add properties that are not present in the data item
            // but if an empty item is passed, get all the properties
            let readOnlyServiceFields = EXCLUDE_FORM_FIELDS_MAP.has(property);
            let propertyMetadata = metadata.properties[property];
            let propertyTweakTitle = null;
            const propertyTweak = tweaks.find((x) => {
                return x.name === property && !x.isSection;
            });

            if (propertyTweak != null) {
                const fieldGroupProcessed = this.processFieldGroups(processedProperties, property, fields, metadata, fieldTypesMap, dataItem, readonlyField, tweaks);
                if (fieldGroupProcessed) {
                    return;
                }

                if (propertyTweak.hidden) {
                    return;
                }

                propertyTweakTitle = propertyTweak.title;
            }

            this.populateMirrorMap(metadata.properties, tweaks, property);

            if (propertyMetadata && !readOnlyServiceFields) {
                const permission = propertyMetadata[FIELD_PERMISSION_PROP_NAME];
                readOnlyServiceFields = permission === FIELD_PERMISSION_READ;
            }

            if (!readOnlyServiceFields) {
                // TODO: remove these hacks
                let propertyValue = null;
                if (dataItem && dataItem[property] !== null) {
                    propertyValue = dataItem[property];
                } else if (propertyMetadata.hasOwnProperty(DEFAULT_PROPERTY_VALUE)) {
                    propertyValue = propertyMetadata[DEFAULT_PROPERTY_VALUE];
                }

                propertyMetadata = this.override(propertyTweak, propertyMetadata);

                const fieldType = this.getPropertyFieldType(metadata, propertyMetadata, propertyTweak, property, defaultProperty);
                const field = createFieldModel(this.fieldsProvider, metadata.setName, fieldType, property, propertyValue, propertyMetadata, propertyTweakTitle);

                if (field) {
                    // skip not required fields when only translatable or required that do not yet have a value
                    const skip = this.shouldSkipField(onlyLocalizable, field, propertyValue);
                    if (skip) {
                        return;
                    }

                    this.updateFieldSettings(field.settings, fieldType, propertyMetadata, property, metadata, propertyTweak, propertyValue);
                    this.overrideSettings(readonlyField, field, propertyTweak, dataItem, propertyMetadata);

                    fields.push(field);
                }
            }
        });

        tweaks.forEach(tweak => {
            const tweakName = tweak.name;
            if (fields.findIndex(m => m.key === tweakName) > -1) {
                return;
            }

            const field = createFieldModel(this.fieldsProvider, metadata.setName, null, tweakName, null, null);

            if (field) {
                this.overrideSettings(readonlyField, field, tweak, dataItem, null);
                fields.push(field);
            }
        });

        this.tryUpdateHandlersValue(fields, metadata, tweaks);
        return fields;
    }

    getPropertyFieldType(metadata: Entity, propertyMetadata: any, propertyTweak: any, propertyName: string, defaultPropertyName: string): string {
        for (const handler of this.metadataHandlers) {
            if (!handler.canProcess(metadata.typeFullName)) {
                continue;
            }

            const fieldType = handler.getFieldType(metadata, propertyName, propertyTweak);
            if (fieldType) {
                return fieldType;
            }
        }

        if (propertyMetadata) {
            const ref = this.getRef(propertyMetadata);
            if (ref && (ref === MEDIA_TYPES.IMAGE || ref === MEDIA_TYPES.VIDEO || ref === MEDIA_TYPES.DOCUMENT)) {
                return FieldTypes.media;
            }

            if (ref && ref === CHOICE_TYPES.TAXONOMY) {
                return FieldTypes.taxonomyTypeChoice;
            }

            if (propertyMetadata.$ref === ADDRESS_TYPES.ADRESS) {
                return FieldTypes.address;
            }

            if (propertyMetadata.relationship && ref) {
                if (ref.startsWith(DYNAMIC_ITEMS_DEFINITIONS.DYNAMIC_TYPES_MODEL)) {
                    return FieldTypes.relatedData;
                }
                switch (ref) {
                    case DYNAMIC_ITEMS_DEFINITIONS.NEWS_ITEM:
                    case DYNAMIC_ITEMS_DEFINITIONS.EVENT:
                    case DYNAMIC_ITEMS_DEFINITIONS.BLOG_POST:
                    case DYNAMIC_ITEMS_DEFINITIONS.PAGE_NODE: {
                        return FieldTypes.relatedData;
                    }
                }
            }

            if (this.mirrorMap && this.mirrorMap[propertyName]) {
                return this.mirrorMap[propertyName].type;
            }

            const propertyType = this.getPropertyType(propertyMetadata);
            if (propertyType === "boolean") {
                return FieldTypes.choiceYesNo;
            }

            if (propertyType === "number") {
                return FieldTypes.number;
            }

            if (propertyType === "string" && !propertyMetadata.format) {
                return this.getFieldTypeForString(metadata, propertyMetadata, propertyName, defaultPropertyName, propertyTweak);
            }

            if (propertyMetadata[TAXONOMY_CONSTANTS.default.TAXONOMY_ID]) {
                return FieldTypes.taxa;
            }

            if (propertyMetadata.format === "date-time") {
                return FieldTypes.dateTime;
            }

            if (propertyMetadata.format === "uuid") {
                if (propertyName === Properties.PARENT_ID) {
                    return FieldTypes.dropdownSelector;
                } else {
                    return FieldTypes.shortText;
                }
            }

            if (propertyName === stringConstants.URLS) {
                // ToDo: Check with metadata when we have one for this object
                return FieldTypes.additionalUrls;
            }

            if (propertyMetadata.type === "array" && propertyMetadata.items && propertyMetadata.items.format === "uuid") {
                return FieldTypes.arrayOfGUIDs;
            }

            const choiceTypes = this.tryGetChoiceTypes(propertyMetadata, propertyTweak);
            if (choiceTypes) {
                return choiceTypes;
            }
        }

        return null;
    }

    // TODO: move to dynamic item store
    classifyFields(entitySet: string | Entity, data: any) {
        const primitiveFields = {};
        const relationFields = {};
        let entity: Entity;
        if (entitySet instanceof Entity) {
            entity = entitySet;
        } else {
            entity = this.store.getEntity(entitySet);
        }

        Object.keys(data).forEach(key => {
            const propValue = data[key];

            const wrapper = this.modifyValue(entity, key, propValue);
            let collection = null;
            if (wrapper.isRelation)
                collection = relationFields;
            else
                collection = primitiveFields;

            collection[key] = wrapper.value;
        });

        return {
            primitiveFields,
            relationFields
        };
    }

    updateFieldSettings(settings: SettingsBase, fieldType: string, propertyMetadata: any, property: string, metadata: Entity, propertyTweak?: any, propertyValue?: string | number) {
        this.updateBaseSettings(settings, propertyTweak);
        this.updateTaxaFieldSettings(fieldType, settings, propertyTweak);
        this.updateTextFieldSettings(fieldType, settings, propertyTweak);
        this.updateRelatedMediaFieldSettings(fieldType, settings, propertyTweak, propertyMetadata, metadata);
        this.updateRelatedDataField(fieldType, settings, propertyMetadata, metadata, propertyTweak);
        this.updateChoiceFieldSettings(fieldType, settings, propertyMetadata, propertyTweak, propertyValue);
        this.updateGuidFieldSettings(fieldType, settings, propertyMetadata);
        this.updateYesNoFieldSettings(fieldType, settings, propertyTweak);
        this.updateStructureUrlNameSettings(settings, fieldType, metadata);
        this.updateLinkSelectorFieldSettings(fieldType, settings, propertyTweak);
        this.updateNavigateToUrlSettings(fieldType, settings, propertyTweak);

        if (this.shouldHaveLargeTitle(metadata, propertyMetadata, property)) {
            settings.look = "large";
        } else if (property === Properties.PARENT_ID && fieldType === FieldTypes.dropdownSelector) {
            this.updateParentSelectorSettings(settings, metadata, propertyTweak);
        }

        const mirrorMapProperty = this.mirrorMap ? this.mirrorMap[property] : null;

        if (mirrorMapProperty) {
            this.mirrorMapSettings(mirrorMapProperty, settings, metadata);
        }
    }

    private updateStructureUrlNameSettings(settings: SettingsBase, fieldType: string, metadata: Entity) {
        if (settings instanceof StructureUrlNameSettings) {
            settings.isStructureEditable = !metadata.isMedia;
            settings.hasExtension = metadata.isMedia;
        }
    }

    private getFieldTypeForString(metadata: Entity, propertyMetadata: any, propertyName: string, defaultPropertyName: string, propertyTweak: FormData) {
        if (propertyMetadata[FIELD_TYPE] && propertyMetadata[FIELD_TYPE] === SHORT_TEXT_FIELD_TYPE) {
            if (propertyName === defaultPropertyName && !metadata.isMedia) {
                return FieldTypes.shortTextDefault;
            }

            if (propertyMetadata[IMMUTABLE_FIELD]) {
                return FieldTypes.read;
            }

            if (propertyName === Properties.NAME &&
                (metadata.setName === TAXONOMY_CONSTANTS.default.FLAT_TAXA ||
                    metadata.setName === TAXONOMY_CONSTANTS.default.HIERARCHY_TAXA ||
                    metadata.setName === ENTITY_SET.FORMS)) {
                return FieldTypes.urlName;
            }

            return FieldTypes.shortText;
        }

        if (propertyMetadata[FIELD_TYPE] === LONG_TEXT_FIELD_TYPE && propertyMetadata[IS_HTML_PROPERTY]) {
            return FieldTypes.html;
        }

        if (propertyMetadata[FIELD_TYPE] === LINK_FIELD_TYPE) {
            return FieldTypes.linkSelector;
        }

        if (propertyTweak && propertyTweak.metadata && propertyTweak.metadata.hasOwnProperty(NAVIGATE_TO_URL)) {
            return FieldTypes.navigateToUrl;
        }

        return FieldTypes.textArea;
    }

    private updateMediaFields(fields: FieldModel[], metadata: Entity, tweaks: any[], readonlyField: boolean) {
        if (metadata.isMedia) {
            const mediaDataField = createFieldModel(this.fieldsProvider, metadata.setName, FieldTypes.mediaData, MEDIA_DATA_FIELD_NAME, null, {});
            const tweak = tweaks.find(x => x.name === mediaDataField.key);
            if (tweak) {
                mediaDataField.settings.readOnlyMode = tweak.readonly;
                const castSettings = mediaDataField.settings as MediaSettings;
                if (castSettings && tweak.allowedFileExtensions && tweak.acceptableMediaTypes && tweak.maximumAllowedSize != null) {
                    (mediaDataField.settings as MediaSettings).acceptableFileTypes = tweak.allowedFileExtensions;
                    (mediaDataField.settings as MediaSettings).acceptableMediaTypes = tweak.acceptableMediaTypes;
                    (mediaDataField.settings as MediaSettings).maxSize = tweak.maximumAllowedSize;
                }
            }

            if (readonlyField !== undefined) {
                mediaDataField.settings.readOnlyMode = readonlyField;
            }

            fields.push(mediaDataField);
        }
    }

    private tryUpdateHandlersValue(fields: FieldModel[], metadata: Entity, tweaks: any[]) {
        for (const handler of this.metadataHandlers) {
            if (!handler.canProcess(metadata.typeFullName)) {
                continue;
            }
            handler.updateFieldSettings(fields, metadata, tweaks);
        }
    }

    private updateTextFieldSettings(fieldType: string, settings: SettingsBase, propertyTweak: any) {
        if ((fieldType === FieldTypes.shortText || fieldType === FieldTypes.shortTextDefault || fieldType === FieldTypes.textArea || fieldType === FieldTypes.number) && propertyTweak && propertyTweak.metadata) {
            settings.placeholder = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.FIELD_PLACEHOLDER];
            settings.unit = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.UNIT];
            const type = fieldType === FieldTypes.number ? "number" : "text";
            settings.type = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.ROWS] > 1 ? "textarea" : type;
            settings.type = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.IS_PASSWORD_MODE] ? "password" : settings.type;
            settings.rows = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.ROWS];
            settings.showCharCounter = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.SHOW_CHAR_COUNTER];

            if (propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.RECOMMENDED_CHAR_COUNTER]) {
                settings.recommendedCharacters = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.RECOMMENDED_CHAR_COUNTER];
            }

            const cssClass = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.CSS_CLASS] || stringConstants.EMPTY_STRING;
            if (settings.look) {
                settings.look += cssClass;
            } else {
                settings.look = cssClass;
            }
        }
    }

    private updateRelatedMediaFieldSettings(fieldType: string, settings: SettingsBase, propertyTweak: any, propertyMetadata: any, metadata: Entity) {
        if (fieldType === FieldTypes.media || fieldType === FieldTypes.templateThumbnail) {
            const provider = propertyMetadata[RELATE_DATA_PROVIDER];
            const mediaSettings = settings as MediaSettings;
            mediaSettings.provider = provider;
            mediaSettings.type = this.getRef(propertyMetadata);
            settings.hintPositionTop = true;

            if (propertyTweak) {
                mediaSettings.allowMultiple = this.getIsMultiple(propertyTweak, mediaSettings.allowMultiple);
            }

            this.overrideRelatedMediaSettingsFromTweaks(mediaSettings, propertyTweak);
        }
    }

    private getIsMultiple(propertyTweak: any, isMultiple: boolean): boolean {
        const meta = propertyTweak.metadata || propertyTweak.fieldMeta;
        if (meta) {
            return meta[TWEAKS_METADATA_PROPERTIES.ALLOW_MULTIPLE_SELECTION] !== undefined ?
                meta[TWEAKS_METADATA_PROPERTIES.ALLOW_MULTIPLE_SELECTION] : isMultiple;
        }

        return isMultiple;
    }

    private updateBaseSettings(settings: SettingsBase, propertyTweak: any) {
        if (propertyTweak && propertyTweak.metadata) {
            const displayMode = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.DISPLAY_MODE];
            if (displayMode !== undefined && displayMode !== null) {
                settings.readOnlyMode = !propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.DISPLAY_MODE];
            }

            const defaultValue = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.PREDEFINED_VALUE];
            if (defaultValue !== undefined && defaultValue !== null) {
                settings.defaultValue = defaultValue;
                settings.useDefaultValue = true;
                // mark the field as dirty if it has predefined value
                // in this case the predefined value will be send and persisted on the server
                settings.markAsDirty = true;
            }

            if (settings && propertyTweak.metadata[SHORT_TEXT_PATTERN_VALIDATION_ERROR_MSG]) {
                settings.patternValidationErrorMessage = propertyTweak.metadata[SHORT_TEXT_PATTERN_VALIDATION_ERROR_MSG];
            }
        }
    }

    private updateTaxaFieldSettings(fieldType: string, settings: SettingsBase, propertyTweak: any) {
        if (fieldType === FieldTypes.taxa && propertyTweak) {
            const taxonomySettings: TaxonomySettings = settings as TaxonomySettings;
            const urlNameMetadata = this.store.getPropertyMetadata(taxonomySettings.type, Properties.URL_NAME);
            taxonomySettings.urlNameSanitizeRegex = urlNameMetadata[FIELD_SANITIZE_REGEX];

            if (propertyTweak) {
                taxonomySettings.allowMultiple = this.getIsMultiple(propertyTweak, taxonomySettings.allowMultiple);

                if (propertyTweak.metadata) {
                    taxonomySettings.id = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.TAXONOMY_ID] !== undefined ?
                        propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.TAXONOMY_ID] : taxonomySettings.id;
                    taxonomySettings.allowCreate = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.ALLOW_CREATING] !== undefined ?
                        propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.ALLOW_CREATING] : taxonomySettings.allowCreate;

                    const rootTaxonId = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.ROOT_TAXON_ID];
                    if (rootTaxonId !== undefined) {
                        taxonomySettings.rootTaxonId = rootTaxonId;
                    }
                }
            }
        }
    }

    private updateChoiceFieldSettings(fieldType: string, settings: SettingsBase, propertyMetadata: any, propertyTweak?: any, propertyValue?: string | number) {
        if (fieldType === FieldTypes.choice || fieldType === FieldTypes.choiceDropDown || fieldType === FieldTypes.choiceMultiple || fieldType === FieldTypes.taxonomyTypeChoice) {
            const settingsCast: ChoiceSettings = settings as ChoiceSettings;
            settingsCast.choices = [];
            if (propertyMetadata.anyOf && propertyMetadata.anyOf.length && propertyMetadata.anyOf[0].$ref) {
                const fullName: string = propertyMetadata.anyOf[0].$ref.replace("#/definitions/", "");
                const definition: any = this.store.getDefinitionMetadata(fullName);
                if (definition && definition.hasOwnProperty("enum")) {
                    settingsCast.choices = definition.enum.map(function (e) {
                        if (e.hasOwnProperty(FIELD_DESCRIPTION)) {
                            e.Description = e[FIELD_DESCRIPTION];
                        }

                        if (e.hasOwnProperty(FIELD_FRIENDLY_NAME)) {
                            e.Title = e[FIELD_FRIENDLY_NAME];
                        }

                        return e;
                    });

                    settingsCast.emptyValues.push("0".repeat(settingsCast.choices.length));
                }

                // Override enum values with friendly titles
                this.overrideOptionNames(settingsCast, propertyTweak);

                if (propertyTweak && propertyTweak.metadata) {
                    settingsCast.showTitle = !propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.HIDE_TITLE];
                }

                if (fieldType === FieldTypes.choice) {
                    settingsCast.useDefaultValue = true;
                }
            }

            settingsCast.type = fieldType;

            settingsCast.updateHasFieldset(propertyValue);
        }
    }

    private updateGuidFieldSettings(fieldType: string, settings: SettingsBase, propertyMetadata: any) {
        if (fieldType === FieldTypes.shortText && propertyMetadata.format === "uuid") {
            settings.emptyValues.push(stringConstants.DEFAULT_GUID);
            settings.defaultValue = propertyMetadata[DEFAULT_PROPERTY_VALUE];
            settings.markAsDirty = true;
            settings.useDefaultValue = true;
        }
    }

    private updateYesNoFieldSettings(fieldType: string, settings: SettingsBase, propertyTweak?: any) {
        const settingsCast: ChoiceSettings = settings as ChoiceSettings;
        if (fieldType === FieldTypes.choiceYesNo) {
            if (propertyTweak && propertyTweak.metadata && propertyTweak.metadata.hasOwnProperty("OptionName")) {
                const optionName = propertyTweak.metadata["OptionName"];
                settingsCast.showTitle = true;
                settingsCast.optionName = optionName;
            } else {
                settingsCast.showTitle = false;
            }
            if (propertyTweak && propertyTweak.metadata && propertyTweak.metadata.hasOwnProperty("InvertedValue")) {
                const isInverted = propertyTweak.metadata["InvertedValue"];
                settingsCast.isInverted = isInverted;
            }
        }
    }

    private updateParentSelectorSettings(settings: SettingsBase, metadata: Entity, propertyTweak?: any) {
        const parentSelectorSettings = settings as ParentSelectorSettings;
        let fieldMetaData: Entity = metadata;
        if (metadata.properties.Parent) {
            parentSelectorSettings.showAddToTopLevel = false;
            const parentPropertyMetadata = metadata.properties.Parent;
            fieldMetaData = this.store.getEntity(this.getEntityName(parentPropertyMetadata));
        }

        let pluralName = fieldMetaData.displayName;
        let singularName = fieldMetaData.singularName;
        if (propertyTweak) {
            if (propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.SINGULAR_NAME]) {
                singularName = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.SINGULAR_NAME];
            }

            if (propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.PLURAL_NAME]) {
                pluralName = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.PLURAL_NAME];
            }
        }

        parentSelectorSettings.selectorNames.plural = pluralName;
        parentSelectorSettings.selectorNames.singular = singularName;
        parentSelectorSettings.hierarchicalTaxaSettings = new TaxonomySettings(fieldMetaData.singularName, false);
        parentSelectorSettings.hierarchicalTaxaSettings.type = fieldMetaData.setName;
    }

    private shouldHaveLargeTitle(metadata: Entity, propertyMetadata: any, property: string) {
        if (!metadata || !propertyMetadata) {
            return false;
        }

        // UX requirement only create page form and in no workflow forms such as create/edit Blog, List, Category must have larger heading title field
        const isTitleField = metadata.properties[DEFAULT_FIELD] === property;
        const isShortTextField = propertyMetadata[FIELD_TYPE] === SHORT_TEXT_FIELD_TYPE;
        const isPageOrNoWorkflowForm = !metadata.hasLifecycle || metadata.setName === ENTITY_SET.PAGES;
        return isTitleField && isShortTextField && isPageOrNoWorkflowForm;
    }

    private processFieldGroups(processedProperties: string[], property: string, fields: FieldModel[], metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean, tweaks: any[]): boolean {
        for (const handler of this.metadataHandlers) {
            if (processedProperties.some(x => x === property)) {
                return true;
            }

            if (!handler.canProcess(metadata.typeFullName)) {
                continue;
            }

            const groupFields = handler.processFieldGroup(property, fields, metadata, fieldTypesMap, dataItem, readonly, tweaks);
            groupFields.forEach(f => processedProperties.push(f));

            if (groupFields.length) {
                return true;
            }
        }

        return false;
    }

    private getFieldTypesMap(properties: string[], tweaks: any, metadata: Entity, defaultProperty: string): Map<string, string> {
        const fieldTypesMap = new Map<string, string>();

        properties.forEach(property => {
            const propTweak = tweaks.find((x) => {
                return x.name === property;
            });
            const fieldType = this.getPropertyFieldType(metadata, metadata.properties[property], propTweak, property, defaultProperty);

            fieldTypesMap.set(property, fieldType);
        });

        return fieldTypesMap;
    }

    private resetMirrorMap(metadata: Entity): void {
        this.mirrorMap = JSON.parse(JSON.stringify(MIRROR_MAP));
        if (metadata.setName !== TAXONOMY_CONSTANTS.default.TAXONOMIES_SET_NAME &&
            metadata.setName !== ENTITY_SET.FORMS &&
            metadata.setName !== TAXONOMY_CONSTANTS.default.HIERARCHY_TAXA &&
            metadata.setName !== TAXONOMY_CONSTANTS.default.FLAT_TAXA) {
            delete this.mirrorMap[Properties.NAME];
        }

        if (metadata.setName === ENTITY_SET.FORMS) {
            this.mirrorMap[Properties.NAME].prefix = "sf_";
        }

        if (metadata.setName === ENTITY_SET.IMAGES) {
            delete this.mirrorMap[Properties.URL_NAME];
            this.mirrorMap[Properties.URL_NAME] = { key: Properties.TITLE, dynamicallyResolved: false, type: FieldTypes.urlName };
        }
    }

    private mirrorMapSettings(mirrorMapProperty: MirrorRegistration, settings: SettingsBase, metadata: Entity) {
        let mirroredFieldName = mirrorMapProperty.key;
        if (mirrorMapProperty.dynamicallyResolved)
            mirroredFieldName = metadata.properties[mirrorMapProperty.key];

        if (isMirrorFieldSettings(settings)) {
            const mirrorFieldSettings = <any>settings as MirrorFieldSettings;
            mirrorFieldSettings.mirroredFieldName = mirroredFieldName;
            mirrorFieldSettings.prefix = mirrorMapProperty.prefix;
        }
    }

    private populateMirrorMap(properties: any, tweaks: any[], property: string): void {
        const mirrorMapProperty = this.mirrorMap[property];

        if (mirrorMapProperty) {
            let mirroredFieldName = mirrorMapProperty.key;

            if (mirroredFieldName === SEO_TITLE) {
                let mirroredProperty = "MetaTitle";
                let propertyMetadata = properties[mirroredProperty];

                if (propertyMetadata == null && properties[DISPLAY_NAME].toLowerCase() === ENTITY_SET.PAGES) {
                    mirroredProperty = "HtmlTitle";
                    propertyMetadata = properties[mirroredProperty];
                }

                if (propertyMetadata == null) {
                    mirroredProperty = mirrorMapProperty.fallback;
                }

                mirroredFieldName = mirroredProperty;

                if (mirroredFieldName !== FIRST_TEXT_FIELD) {
                    if (mirroredFieldName === DEFAULT_FIELD) {
                        mirrorMapProperty.key = mirroredProperty;
                        mirrorMapProperty.dynamicallyResolved = true;
                    } else {
                        const propertyType = this.getPropertyType(propertyMetadata);

                        if (propertyType === "string" && !propertyMetadata.format) {
                            mirrorMapProperty.key = mirroredProperty;
                        }
                    }
                }
            }

            if (mirroredFieldName === SEO_DESCRIPTION) {
                const mirroredProperty = "MetaDescription";
                const propertyMetadata = properties[mirroredProperty];

                if (propertyMetadata == null) {
                    mirroredFieldName = mirrorMapProperty.fallback;
                }

                if (mirroredFieldName !== FIRST_TEXT_FIELD) {
                    const propertyType = this.getPropertyType(propertyMetadata);

                    if (propertyType === "string" && !propertyMetadata.format) {
                        mirrorMapProperty.key = mirroredProperty;

                        if (mirroredFieldName === DEFAULT_FIELD) {
                            mirrorMapProperty.dynamicallyResolved = true;
                        }
                    }
                }
            }

            if (mirroredFieldName === FIRST_TEXT_FIELD) {
                const firstTextProperty = this.getFirstTextPropertyToMirror(properties, tweaks, property);

                if (firstTextProperty) {
                    mirrorMapProperty.key = firstTextProperty;
                } else {
                    delete this.mirrorMap[property];
                }
            }
        }
    }
    /**
     * Gets the first text property to be mirrored
     * Excludes: Default property, UrlName, SEO properties
     */
    private getFirstTextPropertyToMirror(properties: any, tweaks: any[], property: string): string {
        for (let i = 0; i < tweaks.length; i++) {
            const tweak = tweaks[i];
            if (!tweak.isSection) {
                // if we reach the current property return null, because it will be odd to mirror from a field
                // that is placed below in the UI
                if (tweak.name === property)
                    return;

                const mirroredProperty = Object.keys(properties)
                    .find(key => key === tweak.name && key !== properties[DEFAULT_FIELD] && !MIRROR_MAP[key]);

                if (mirroredProperty) {
                    const propertyMetadata = properties[mirroredProperty];
                    const propertyType = this.getPropertyType(propertyMetadata);
                    if (propertyType === "string" && !propertyMetadata.format) {
                        return mirroredProperty;
                    }
                }
            }
        }

        return null;
    }

    private setTooltip(field: FieldModel, propertyTweak: FormData): void {
        if (propertyTweak) {
            field.settings.tooltipModels = propertyTweak.tooltipModels;
        }
    }

    private overrideSettings(readonlyField: boolean, field: FieldModel, propertyTweak: FormData, dataItem: any, propertyMetadata: any) {
        if (!!readonlyField) {
            field.settings.readOnlyMode = readonlyField;
        }

        if (propertyTweak) {
            // override from server settings
            this.overridePropertyTweakSettings(field, propertyTweak);
        }

        if (propertyMetadata) {
            // override from metadata
            if (dataItem && propertyMetadata[IMMUTABLE_FIELD] === true) {
                field.settings.readOnlyMode = true;
            }

            this.setTooltip(field, propertyTweak);
        }
    }

    private overridePropertyTweakSettings(field: FieldModel, propertyTweak: FormData) {
        if (!!propertyTweak.readonly) {
            field.settings.readOnlyMode = propertyTweak.readonly;
        }
        if (propertyTweak.allowCreate !== undefined) {
            field.settings.allowCreate = propertyTweak.allowCreate && field.settings.allowCreate;
        }
        if (propertyTweak.allowAdd !== undefined) {
            field.settings.allowAdd = propertyTweak.allowAdd;
        }
        if (propertyTweak.allowRemove !== undefined) {
            field.settings.allowRemove = propertyTweak.allowRemove;
        }
        if (propertyTweak.allowView !== undefined) {
            field.settings.allowView = propertyTweak.allowView;
        }
        if (!!propertyTweak.status) {
            field.settings.status = propertyTweak.status;
        }
        if (!!propertyTweak.statusMessage) {
            field.settings.statusMessage = propertyTweak.statusMessage;
        }
        if (!!propertyTweak.predefinedValue) {
            field.settings.defaultValue = propertyTweak.predefinedValue;
            field.settings.markAsDirty = true;
        }
    }

    private shouldSkipField(onlyLocalizable: boolean, field: FieldModel, propertyValue: any): boolean {
        if (onlyLocalizable) {
            // if the field has a required field, but it is not populated
            if (field.settings.required) {
                return false;
            }

            // if the field is not translatable
            if (!field.settings.translatable) {
                return true;
            }
        }

        return false;
    }

    private override(propertyTweak: any, propertyMetadata: any): any {
        if (propertyTweak) {
            propertyMetadata = cloneObject(propertyMetadata);
            if (propertyTweak.isHtml !== undefined && propertyTweak.isHtml !== null) {
                propertyMetadata[IS_HTML_PROPERTY] = propertyTweak.isHtml;
                propertyMetadata[FIELD_TYPE] = LONG_TEXT_FIELD_TYPE;
            }

            if (propertyTweak.maximumAllowedSize !== undefined && propertyTweak.maximumAllowedSize != null) {
                propertyMetadata[MAXIMUM_ALLOWED_SIZE] = propertyTweak.maximumAllowedSize;
            }

            if (propertyTweak.allowedFileExtensions !== undefined && propertyTweak.allowedFileExtensions != null) {
                propertyMetadata[ALLOWED_FILE_EXTENSIONS] = propertyTweak.allowedFileExtensions;
            }

            if (propertyTweak.acceptableMediaTypes !== undefined && propertyTweak.acceptableMediaTypes != null) {
                propertyMetadata[ACCEPTABLE_MEDIA_TYPES] = propertyTweak.acceptableMediaTypes;
            }

            if (propertyTweak.metadata && propertyTweak.metadata[VALIDATION_REGEX]) {
                propertyMetadata[VALIDATION_REGEX] = propertyTweak.metadata[VALIDATION_REGEX];
            }
        }

        return propertyMetadata;
    }

    private updateRelatedDataField(fieldType: string, settings: SettingsBase, propertyMetadata: any, metadata: Entity, propertyTweak: any) {
        if (fieldType === FieldTypes.relatedData) {
            const relatedDataSettings = settings as RelatedDataSettings;
            if (!relatedDataSettings.key) {
                relatedDataSettings.key = propertyMetadata.relationship.partner;
            }

            relatedDataSettings.provider = propertyMetadata[RELATE_DATA_PROVIDER];
            relatedDataSettings.type = this.getEntityName(propertyMetadata);
            if (propertyTweak) {
                relatedDataSettings.allowMultiple = this.getIsMultiple(propertyTweak, relatedDataSettings.allowMultiple);
            }
        }
    }

    private updateLinkSelectorFieldSettings(fieldType: string, settings: SettingsBase, propertyTweak: any) {
        if (fieldType === FieldTypes.linkSelector) {
            const linkSelectorSettings = settings as LinkSelectorSettings;

            if (propertyTweak) {
                linkSelectorSettings.allowMultiple = this.getIsMultiple(propertyTweak, linkSelectorSettings.allowMultiple);
            }
        }
    }

    private modifyValue(entity: Entity, name: string, value: any): any {
        let modified = value;
        const relation = entity.relations.find(x => x.propName === name);

        if (relation) {
            let provider: string = relation?.provider;
            const isAnySiteProvider: boolean = relation?.provider === ANY_SITE_SOURCE_PROVIDER;

            const isArray = Array.isArray(value);
            const arrayValue = isArray ? value : [value];
            const result = [];

            for (let entry of arrayValue) {
                if (isAnySiteProvider) {
                    // use the selected provider from the UI
                    provider = entry.provider;
                }
                entry = entry.Id || entry; // TODO: should be removed, when image component starts to return Id's only
                const link = this.sdk.link(relation.setName, entry, provider);
                result.push(link);
            }
            modified = result;
        }

        return {
            value: modified,
            isRelation: !!relation
        };
    }

    private getPropertyType(propertyMetadata: any): any {
        let propertyType = propertyMetadata.type;

        if (propertyType instanceof Array && propertyType.length > 0) {
            propertyType = propertyType[0];
        }

        return propertyType;
    }

    private tryGetChoiceTypes(propertyMetadata: any, propertyTweak: any) {
        if (propertyTweak) {
            if (propertyTweak.renderChoicesAs === RenderChoicesAs.dropDown) {
                return FieldTypes.choiceDropDown;
            } else if (propertyTweak.renderChoicesAs === RenderChoicesAs.radioButtons) {
                return FieldTypes.choice;
            } else if (propertyTweak.renderChoicesAs === RenderChoicesAs.checkBoxes) {
                return FieldTypes.choiceMultiple;
            }
        }

        if (propertyMetadata[FIELD_TYPE]) {
            if (propertyMetadata[FIELD_TYPE].toLowerCase() === CHOICE_FIELD_TYPE_LOWERCASE) {
                return FieldTypes.choice;
            } else if (propertyMetadata[FIELD_TYPE].toLowerCase() === MULTIPLE_CHOICE_FIELD_TYPE_LOWERCASE) {
                return FieldTypes.choiceMultiple;
            }
        }
    }

    private getRef(propertyMetadata: any): string {
        const ref = propertyMetadata.items ? propertyMetadata.items.$ref :
            propertyMetadata.anyOf ?
                propertyMetadata.anyOf[0].$ref :
                null;
        return ref;
    }

    private getEntityName(propertyMetadata: any): string {
        const ref: string = this.getRef(propertyMetadata);
        if (!ref) {
            return null;
        }

        const partnerFullName = ref.replace("#/definitions/", stringConstants.EMPTY_STRING);
        const entityName = this.store.getEntitySetName(partnerFullName);
        return entityName;
    }

    private overrideRelatedMediaSettingsFromTweaks(settings: MediaSettings, propertyTweak?: any) {
        if (propertyTweak && propertyTweak.metadata) {
            settings.sourceLibraryId = propertyTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.SOURCE_LIBRARY_ID_KEY];
            settings.targetLibraryId = propertyTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.TARGET_LIBRARY_ID_KEY];
            settings.useOnlyUploadMode = propertyTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.USE_ONLY_UPLOAD_MODE_KEY];
            settings.useOnlySelectMode = propertyTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.USE_ONLY_SELECT_MODE_KEY];
            settings.selectButtonText = propertyTweak.metadata[TWEAKS_METADATA_PROPERTIES.SELECT_BUTTON_TEXT];
            settings.canRelateDamAssets = propertyTweak.metadata[RESTRICTIONS_FOR_RELATED_MEDIA.CAN_RELATE_DAM_ASSETS_KEY];
        }

        if (settings.useOnlyUploadMode && (!settings.allowCreate || settings.useOnlySelectMode)) {
            settings.readOnlyMode = true;
        }
    }

    overrideOptionNames(settings: ChoiceSettings, propertyTweak?: any) {
        if (propertyTweak && propertyTweak.metadata && propertyTweak.metadata.hasOwnProperty(OVERRIDEN_OPTION_NAMES_FIELD_NAME)) {
            const friendlyTitles = propertyTweak.metadata[OVERRIDEN_OPTION_NAMES_FIELD_NAME];
            settings.choices.forEach(choice => {
                const friendlyTitle = friendlyTitles.find(x => x.Name === choice["Name"]);
                if (friendlyTitle) {
                    choice["Name"] = friendlyTitle.Title;
                }
            });
        }
    }

    private updateNavigateToUrlSettings(fieldType: string, settings: SettingsBase, propertyTweak: FormData): void {
        if (fieldType === FieldTypes.navigateToUrl && propertyTweak && propertyTweak.metadata) {
            const settingsCast: NavigateToUrlSettings = settings as NavigateToUrlSettings;
            if (settingsCast) {
                settingsCast.url = propertyTweak.metadata[NAVIGATE_TO_URL];
            }
        }
    }
}
