import { ViewEncapsulation, TemplateRef, ViewChild, ViewChildren, Component, ChangeDetectorRef, OnInit, QueryList, ViewContainerRef } from "@angular/core";
import { FieldBase } from "../../../../../../../fields";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { DateTimePickerComponent } from "../../../../../../../fields/date-time/date-time-picker.component";
import { SfInputComponent } from "@progress/sitefinity-component-framework";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { RecuringEventData } from ".";
import { EventsHelper } from "../event.helpers";
import { RecurrentRuleService } from "./recurrent-rule.service";
import { RecurrentRule, RecurrenceFrequency, EndRecurrenceType } from "./recurrent-rule";
import { REPEAT_EVENT_OPTIONS, EndOccurrence, RecurringEventDropdownOptions, AFTER_END_OCCURRENCE_DEFAULT_COUNT, NEVER_END_OCCURRENCE_NAME, ON_END_OCCURRENCE_NAME, AFTER_END_OCCURRENCE_NAME, RECURRING_EVENT_KEYS } from "./recurring-event.constants";
import { EVENT_PROPERTIES } from "../events.constants";
import { convertSecondsToHourMinuteSecString, convertDateToIsoDateTime } from "../../../../../utils";
import { EventDatesService } from "../services/event-dates.service";
import { ChoiceReadOnlyComponent } from "../../../../../../../fields/choice/choice-readOnly.component";
import { TimeZonesProvider } from "../timezones/timezones.provider";
import { toLoadingState, delayEmission } from "../../../rxjs-extensions";
import { MINIMUM_LOADER_TIME } from "../../../../../../../fields/loader-wrapper/loader-wrapper.component";
import { ChoiceItem, ChoiceSettingsBase } from "@progress/sitefinity-component-framework";

export const DAY_TIMESPAN_STRING = "1.00:00:00";

@Component({
    selector: "sf-recurring-event",
    templateUrl: "./recurring-event.component.html",
    encapsulation: ViewEncapsulation.None,
    providers: [RecurrentRuleService, TimeZonesProvider]
})
export class RecurringEventComponent extends FieldBase implements OnInit {
    isLoaded: boolean;
    repeatEventDropdownSettings: ChoiceSettings = ChoiceDropdownComponent.createFieldSettings(REPEAT_EVENT_OPTIONS);
    choiceSettings: ChoiceSettingsBase;
    protected hasEndOccurrence: boolean = false;
    protected endOccurrences = new Array<EndOccurrence>();
    private endOccurancesChoices: Array<ChoiceItem>;
    protected timezoneId: string;

    @ViewChild("repeatEventDropdown", { static: false }) private repeatEventDropdown: ChoiceDropdownComponent;
    @ViewChild("repeatEventDropdownReadonly", { static: false }) private repeatEventDropdownReadonly: ChoiceReadOnlyComponent;

    @ViewChild("onEndOccurrence", { static: true }) private onEndOccurrenceTmpl: TemplateRef<any>;
    @ViewChild("afterEndOccurrence", { static: true }) private afterEndOccurrenceTmpl: TemplateRef<any>;

    @ViewChildren("endOnDateField") private endOnDateFieldRef: QueryList<ViewContainerRef>;
    @ViewChildren("afterEndOccurrenceField") private afterEndOccurrenceFieldRef: QueryList<ViewContainerRef>;

    private _allDayEvent: boolean;

    private set endOnDateField(endOnDateField: any) {
        this.initializeOnField(endOnDateField);
    }

    private get endOnDateField() {
        return this._endOnDateField;
    }

    private set afterEndOccurrenceField(afterEndOccurrenceField: any) {
        this.initializeAfterField(afterEndOccurrenceField);
    }

    private get afterEndOccurrenceField() {
        return this._afterEndOccurrenceField;
    }

    private get recurrentRule(): RecurrentRule {
        return JSON.parse(this.getValue());
    }

    private _endOnDateField: DateTimePickerComponent;
    private _afterEndOccurrenceField: SfInputComponent;
    private recurringEventValue: RecuringEventData = {};
    private eventStartDate: Date = new Date();

    get timeZoneId() {
        return this.timezoneId;
    }

    set timeZoneId(val: string) {
        this.timezoneId = val;
    }

    get allDayEvent() {
        return this._allDayEvent;
    }

    set allDayEvent(allDayEvent: boolean) {
        this._allDayEvent = allDayEvent;

        const recurrentRule = this.recurrentRule;
        if (!recurrentRule) {
            return;
        }

        if (this.allDayEvent && !!recurrentRule.duration) {
            recurrentRule.duration = DAY_TIMESPAN_STRING;
            super.writeValue(JSON.stringify(recurrentRule));
        }

        const recalculateRecurres = recurrentRule.frequency !== RecurrenceFrequency.None && !!recurrentRule.recursUntil;
        if (!recalculateRecurres) {
            return;
        }

        recurrentRule.recursUntil = new Date(recurrentRule.recursUntil);
        // When the event is all day the time should be cleared, but when it's not, the time should equals
        // the time of the StartDate.
        if (this.allDayEvent) {
            recurrentRule.recursUntil = this.eventDatesService.resetTime(recurrentRule.recursUntil);
            recurrentRule.recursUntil = new Date(convertDateToIsoDateTime(recurrentRule.recursUntil));
        } else {
            this.setRecurrsUntilTime(recurrentRule.recursUntil);
        }

        super.writeValue(JSON.stringify(recurrentRule));
    }

    set startDate(value) {
        this.eventStartDate = value;
        this.updateOccurenceDropdown(value);
    }

    get startDate(): Date {
        return this.eventStartDate;
    }

    constructor(private readonly detector: ChangeDetectorRef,
                private readonly recurrentRuleService: RecurrentRuleService,
                private readonly eventsHelper: EventsHelper,
                private readonly eventDatesService: EventDatesService,
                private readonly timeZonesProvider: TimeZonesProvider) {
        super();
    }

    ngOnInit() {

        this.choiceSettings = {
            wrapperCssClass: "-list-style-none sf-field__content",
            choiceCssClass: "sf-row -align-items-center -no-wrap",
            textCssClass: "sf-row -align-items-center",
            labelCssClass: "-inline sf-row__col -no-flex",
            readOnlyMode: this.settings && this.settings.readOnlyMode,
            showExpandedTemplateAlways: true,
            key: "endOcurrenceOption"
        };

        this.endOnDateFieldRef.changes.subscribe((values: QueryList<any>) => {
            const value: any = values.first;
            if (value) {
                this.endOnDateField = value;
            }
        });

        this.afterEndOccurrenceFieldRef.changes.subscribe((values: QueryList<any>) => {
            const value: any = values.first;
            if (value) {
                this.afterEndOccurrenceField = value;
            }
        });

        this.allDayEvent = false;

        const dataItem = this.settings.dataItem;

        if (dataItem && dataItem.data) {
            this.eventStartDate = new Date(dataItem.data[EVENT_PROPERTIES.EVENT_START_WITH_OFFSET]);
            this.eventStartDate.setMinutes(this.eventStartDate.getMinutes() + this.eventStartDate.getTimezoneOffset());
            this.allDayEvent = dataItem.data[EVENT_PROPERTIES.ALL_DAY_EVENT];
            this.timeZoneId = dataItem.data[EVENT_PROPERTIES.TIME_ZONE_ID];
            this.isLoaded = true;
        } else {
            this.registerSubscription(
                this.timeZonesProvider.getDefaultTimeZone().pipe(
                    toLoadingState(),
                    delayEmission(MINIMUM_LOADER_TIME)
                ).subscribe(x => {
                    if (x.isLoading) {
                        return;
                    }

                    this.timeZoneId = x.content.timeZoneId;
                    this.isLoaded = true;
                })
            );
        }
    }

    postProcessValue(value: RecuringEventData | string): any {
        const recurrentRule: RecurrentRule = this.getRecurrentRule(value);
        if (recurrentRule.recursUntil) {
            recurrentRule.recursUntil = new Date(convertDateToIsoDateTime(recurrentRule.recursUntil));
        }
        return JSON.stringify(recurrentRule);
    }

    writeValue(value: RecuringEventData | string | null) {
        const recurrentRule: RecurrentRule = this.getRecurrentRule(value);
        super.writeValue(JSON.stringify(recurrentRule));
        this.populateFields(recurrentRule);
        this.detector.detectChanges();
    }

    handleEndDateChange(endDate: Date) {
        const currentValue = this.recurrentRule;
        if (!currentValue || currentValue.frequency === RecurrenceFrequency.None) {
            return;
        }

        // duration should be in ms
        const duration = (endDate.getTime() - this.startDate.getTime()) / 1000;
        let convertedDuration = duration < 0 ? "00:00:00" : convertSecondsToHourMinuteSecString(duration);
        if (this.allDayEvent) {
            convertedDuration = DAY_TIMESPAN_STRING;
        }

        currentValue.duration = convertedDuration;
        this.writeValue(JSON.stringify(currentValue));
    }

    protected onRepeatEventChange(value: string) {
        const selectedRepeatOption = REPEAT_EVENT_OPTIONS.find(eventOption => eventOption.Value === value);
        const selectedEndOccurrence = this.endOccurrences.find(occurrence => occurrence.isSelected);

        this.hasEndOccurrence = selectedRepeatOption.HasEndOccurrence;
        this.setRecurringEventValue(selectedRepeatOption, selectedEndOccurrence);
    }

    protected onEndOccurrenceChange(index: number) {
        const selectedOccurrence = this.endOccurrences[index];
        this.setOccurenceCondition(index, selectedOccurrence);

        this.updateEndOccurence(selectedOccurrence);
    }

    protected onEndOccurrenceChoiceChanced(choice: ChoiceItem) {
        const selectedOccurrence =  this.endOccurrences.find( item => item.name === choice.Name);
        this.updateEndOccurence(selectedOccurrence);
    }

    protected updateEndOccurence(selectedOccurence: EndOccurrence) {
        this.setEndOccurrenceValue(selectedOccurence);
        this.writeValue(this.recurringEventValue);
    }

    private populateFields(recurrentRule: RecurrentRule): void {
        this.initDropdownOptions(recurrentRule);
        this.initEndOccurence(recurrentRule);
    }

    private initDropdownOptions(recurrentRule: RecurrentRule): void {
        this.updateOccurenceDropdown(this.startDate);

        let initialSelectedOption: RecurringEventDropdownOptions = REPEAT_EVENT_OPTIONS.find(f => f.Frequency === recurrentRule.frequency);
        if (recurrentRule.frequency === RecurrenceFrequency.Daily) {
            initialSelectedOption = REPEAT_EVENT_OPTIONS.find(f => f.DaysOfWeek === recurrentRule.daysOfWeek);
        }

        if (!this.settings.readOnlyMode && this.repeatEventDropdown) {
            this.repeatEventDropdown.writeValue(initialSelectedOption.Value);
        } else if (this.repeatEventDropdownReadonly) {
            this.repeatEventDropdownReadonly.writeValue(initialSelectedOption.Value);
        }

        this.repeatEventDropdownSettings.defaultValue = initialSelectedOption.Value;
        this.setRepeatEventValue(initialSelectedOption);
    }

    private initEndOccurence(recurrentRule: RecurrentRule) {
        this.initializeEndOccurrences();

        this.hasEndOccurrence = recurrentRule.frequency !== RecurrenceFrequency.None;

        const endOccurrenceType = recurrentRule.endRecurrenceType !== undefined && recurrentRule.endRecurrenceType !== null ? recurrentRule.endRecurrenceType : EndRecurrenceType.Never;
        const endOccurenceCondition = a => a.endRecurrenceType === endOccurrenceType;
        this.endOccurrences
            .find(endOccurenceCondition)
            .isSelected = true;
        const selectedOccurenceIndex = this.endOccurrences.findIndex(endOccurenceCondition);
        this.endOccurancesChoices[selectedOccurenceIndex].Selected = true;
    }

    private setOccurenceCondition(index: number, selectedOccurrence?: EndOccurrence) {
        this.endOccurancesChoices.forEach((item: ChoiceItem, i: number) => {
            item.Selected = i === index;
        });
        this.endOccurrences.forEach((occurrence: EndOccurrence) => {
            occurrence.isSelected = occurrence.endRecurrenceType === selectedOccurrence.endRecurrenceType;
        });
    }

    private updateOccurenceDropdown(selectedDate: Date): void {
        if (!selectedDate) {
            return;
        }

        const weeklyOption = REPEAT_EVENT_OPTIONS[3];
        const day = this.eventsHelper.getWeekDayName(selectedDate.getDay());
        weeklyOption.Name = `${RECURRING_EVENT_KEYS.WEEKLY_ON} ${day}`;

        const monthlyOption = REPEAT_EVENT_OPTIONS[4];
        const date = selectedDate.getDate();
        const daySuffix = this.eventsHelper.getDayOfMonthSuffix(date);
        monthlyOption.Name = `${RECURRING_EVENT_KEYS.MONTHLY_ON} ${date}${daySuffix}`;

        const yearlyOption = REPEAT_EVENT_OPTIONS[5];
        const month = this.eventsHelper.getMonthName(selectedDate.getMonth());
        yearlyOption.Name = `${RECURRING_EVENT_KEYS.YEARLY_ON} ${month} ${date}${daySuffix}`;
        this.repeatEventDropdownSettings = ChoiceDropdownComponent.createFieldSettings(REPEAT_EVENT_OPTIONS);
    }

    private setRecurringEventValue(selectedRepeatOption: RecurringEventDropdownOptions, selectedOccurrence: EndOccurrence) {
        this.setRepeatEventValue(selectedRepeatOption);
        this.setEndOccurrenceValue(selectedOccurrence);

        if (selectedRepeatOption.Name === RECURRING_EVENT_KEYS.DONT_REPEAT) {
            this.writeValue(null);
        } else {
            this.writeValue(this.recurringEventValue);
        }
    }

    private setRepeatEventValue(selectedRepeatOption: RecurringEventDropdownOptions) {
        this.recurringEventValue.repeatEvent = {
            key: selectedRepeatOption.Name,
            value: selectedRepeatOption.Data
        };
    }

    private setEndOccurrenceValue(selectedOccurrence: EndOccurrence) {
        if (!selectedOccurrence) {
            return;
        }

        switch (selectedOccurrence.endRecurrenceType) {
            case EndRecurrenceType.Never:
                selectedOccurrence.value = null;
                break;
            case EndRecurrenceType.By:
                selectedOccurrence.value = new Date(this.endOnDateField.dateValue);
                this.setRecurrsUntilTime(selectedOccurrence.value);
                break;
            case EndRecurrenceType.After:
                selectedOccurrence.value = this.afterEndOccurrenceField.value;
                break;
        }

        this.recurringEventValue.endOccurrence = {
            key: selectedOccurrence.name,
            value: selectedOccurrence.value
        };
    }

    private initializeEndOccurrences(): void {
        if (!this.endOccurrences.length) {
            const neverEndOccurrence = new EndOccurrence(NEVER_END_OCCURRENCE_NAME, EndRecurrenceType.Never);
            const onEndOccurrence = new EndOccurrence(ON_END_OCCURRENCE_NAME, EndRecurrenceType.By);
            const afterEndOccurrence = new EndOccurrence(AFTER_END_OCCURRENCE_NAME, EndRecurrenceType.After);

            onEndOccurrence.template = this.onEndOccurrenceTmpl;
            afterEndOccurrence.template = this.afterEndOccurrenceTmpl;

            this.endOccurrences = [neverEndOccurrence, onEndOccurrence, afterEndOccurrence];
            this.endOccurancesChoices = this.endOccurrences.map( (item) => {
                const choiceItem: ChoiceItem = {
                    Value: item.value,
                    Name: item.name,
                    Selected: item.isSelected,
                    ExpandedTemplate: item.template
                };

                return choiceItem;
            });
        }
    }

    private initializeAfterField(field: SfInputComponent) {
        let value = AFTER_END_OCCURRENCE_DEFAULT_COUNT;

        if (this.recurrentRule && this.recurrentRule.endRecurrenceType === EndRecurrenceType.After) {
            value = this.recurrentRule.maxOccurrences.toString();
        }

        this.writeValueToField(field, value);
        this._afterEndOccurrenceField = field;
    }

    private initializeOnField(field: DateTimePickerComponent) {
        let date = this.getTomorrowsDate();

        if (this.recurrentRule && this.recurrentRule.endRecurrenceType === EndRecurrenceType.By) {
            date = this.recurrentRule.recursUntil;
        }

        this.writeValueToField(field, date);
        this._endOnDateField = field;
    }

    private writeValueToField(field: SfInputComponent | FieldBase, value: any) {
        if (field) {
            field.writeValue(value);
        }
    }

    private getTomorrowsDate(): Date {
        const date = new Date(Date.now());
        date.setDate(date.getDate() + 1);

        return date;
    }

    private setRecurrsUntilTime(recurrstUntil: Date) {
        recurrstUntil.setHours(
            this.startDate.getHours(),
            this.startDate.getMinutes(),
            this.startDate.getSeconds(),
            this.startDate.getMilliseconds()
        );

        return recurrstUntil;
    }

    private getRecurrentRule(value: RecuringEventData | string | null): RecurrentRule {
        let recurrentRule: RecurrentRule = null;

        if (!value) {
            recurrentRule = { frequency: RecurrenceFrequency.None };
        } else if (typeof value === "string") {
            recurrentRule = JSON.parse(value as string);
        } else {
            recurrentRule = this.recurrentRuleService.construct(value as RecuringEventData, this.allDayEvent, this.startDate);
        }

        recurrentRule.timeZoneId = this.timeZoneId;
        return recurrentRule;
    }
}
