import { Component, Input, SimpleChanges, OnChanges, OnInit, Output, EventEmitter } from "@angular/core";
import { ChoiceDropdownListComponent } from "../../../../../../../fields/choice/choice-dropdown-list.component";
import { EntityData } from "../../interfaces";
import { ProviderSelectorBaseComponent, Provider } from "./provider-selector-base.component";
import { ProviderStore } from "../../services/provider-store";
import { stringConstants } from "../../../../../common-constants";
import { ChipsConfig } from "../../../../../../../fields/common/chips/chips.component";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { SelectorEventArgs } from "@progress/sitefinity-component-framework";

// TODO: tests
@Component({
    selector: "sf-provider-selector",
    templateUrl: "./provider-selector.component.html"
})
export class ProviderSelectorComponent extends ProviderSelectorBaseComponent implements OnInit, OnChanges {
    @Input() entityData: EntityData;
    @Input() providersCollection: Provider[];
    @Input() displayMode: string = stringConstants.EMPTY_STRING;
    @Output() onChange = new EventEmitter<SelectorEventArgs>();
    @Output() onInit = new EventEmitter<SelectorEventArgs>();

    dropdownSettings: SettingsBase;
    chipsProviders: any;
    filteredChipsProviders: any;
    selectedChips: any[] = [];
    chipConfig: ChipsConfig = {
        showRecentLabel: false,
        showSelectedItemAsActive: true,
        showNoResultsLabel: true
    };

    constructor(store: ProviderStore) {
        super(store);
    }

    ngOnInit(): void {
        if (this.providersCollection) {
            this.providers = this.providersCollection;
        }

        if (this.entityData) {
            this.entitySetName = this.entityData.metadata.setName;
            this.initializeProviders(this.entityData.metadata.selectedProvider || this.entityData.provider);
        } else {
            this.initializeProviders();
        }
    }

    ngOnChanges(changes: SimpleChanges) {
        const entityDataChange = changes["entityData"];
        if (entityDataChange) {
            this.entityData = entityDataChange.currentValue;
            if (this.entityData) {
                this.entitySetName = this.entityData.metadata.setName;
                this.initializeProviders(this.entityData.metadata.selectedProvider || this.entityData.provider);
            }
        }
    }

    onSearchChips(searchTerm: string): void {
        if (searchTerm) {
            this.filteredChipsProviders = this.chipsProviders.filter(p => p.Title.includes(searchTerm.trim()));
        } else {
            this.filteredChipsProviders = null;
        }
    }

    public onProviderChipChange(provider: any) {
        this.onChange.emit(<SelectorEventArgs>{ tabValue: provider.Name });
        this.selectedChips = [{ Title: provider.Title, Id: provider.Name }];
    }

    protected onInitializedProviders(providers: Provider[]) {
        this.dropdownSettings = this.getDropdownSettings();

        if (this.displayMode === "chips") {
            this.initChips(providers, this.initialActiveProvider.name);
        }
    }

    private getDropdownSettings(): SettingsBase {
        if (this.dropdownOptions.length > 0) {
            return ChoiceDropdownListComponent.createFieldSettings(this.dropdownOptions, this.initialActiveProvider.name);
        } else {
            return null;
        }
    }

    private initChips(providers: Provider[], selectedProvider: string) {
        this.chipsProviders = providers.map(p => ({ Name: p.name, Title: p.title, Id: p.name }));

        const currentProvider = providers.find(x => x.name === selectedProvider);
        this.selectedChips = [{ Title: currentProvider.title, Id: currentProvider.name }];
    }
}
