import { AbstractControl, ValidatorFn } from "@angular/forms";

import { ContentLinkInputModel } from "./helpers/content-link-input-model";

export class LinkInsertFieldValidator {
    static validator: ValidatorFn = (control: AbstractControl): { [key: string]: any; } => {
        if (!control || !control.value) {
            return null;
        }

        const val: ContentLinkInputModel = control.value;
        const modelErrors = val.getErrors();
        if (modelErrors.length > 0) {
            const errors: { [key: string]: any; } = {};
            modelErrors.forEach(modelError => {
                errors[modelError.errorType] = modelError.error;
            });
            return errors;
        } else {
            return null;
        }
    }

    static getValidator(): ValidatorFn {
        return LinkInsertFieldValidator.validator;
    }
}
