import { Injectable, Inject } from "@angular/core";
import { Actions, createEffect, ofType } from "@ngrx/effects";
import { SIDEBAR_KEY } from "../../../modules/shared/components/sidebar/sidebar-component.repo";
import { mergeMap, delay, withLatestFrom, tap } from "rxjs/operators";
import { of } from "rxjs";
import { SIDEBAR_ACTIONS, __SidebarChangeInternalAction__, __SidebarConfigInternalAction__ } from "../actions/actions.sidebar";
import { LOCAL_STORAGE, StorageService } from "../../../modules/shared/services/storage.service";
import { SidebarData, SidebarConfig } from "../../../modules/shared/components/sidebar/sidebar.common";
import { AppStore } from "../app-store";
import { SIDEBAR_SELECTORS } from "../selectors/selectors.sidebar";

/**
 * Effects for the sidebar feature. Used to process actions and their data and to execute external calls and get data
 */
@Injectable()
export class SidebarEffects {
    /**
     * Effect for getting the stored sidebar data when the main config is changed
     */
    public readonly openedSidebars$ = createEffect(() => {
        return this.actions$.pipe(
            ofType(SIDEBAR_ACTIONS.configure),
            delay(0),
            mergeMap((configureAction: { type: any, sidebarData: SidebarData }) => of(this.initFromConfig(configureAction.sidebarData))
            )
        );
    });

    /**
     * Effect for processing internally the current active sidebar config
     */
    public readonly activeConfigChanged$ = createEffect(() => {
        return this.actions$.pipe(
            ofType(SIDEBAR_ACTIONS.change, SIDEBAR_ACTIONS.changeAndOpen),
            withLatestFrom(this.store.pipe(SIDEBAR_SELECTORS.sidebarData)),
            mergeMap(data => {
                const changeAction = data[0];
                const sidebarData = data[1];
                const modifiedConfig = Object.assign({}, changeAction.activeConfig);

                this.setOpenedSidebar(sidebarData, modifiedConfig);

                return of(__SidebarChangeInternalAction__({ activeConfig: modifiedConfig }));
            }));
    });

    public readonly setAnimateFalse$ = createEffect(() => {
        return this.actions$.pipe(
            ofType(SIDEBAR_ACTIONS.open, SIDEBAR_ACTIONS.close, SIDEBAR_ACTIONS.changeAndOpen),
            delay(1200), //// This is based on the animation duration set in sidebar.css -animate class
            mergeMap(data => {
                return of(SIDEBAR_ACTIONS.setShouldAnimate({ shouldAnimate: false }));
            })
        );
    });

    /**
     * Effect for processing internally the full sidebar data and preventing multiple firings with the same sidebar data
     */
    public readonly configChanged$ = createEffect(() => {
        return this.actions$.pipe(
            ofType(SIDEBAR_ACTIONS.configure),
            mergeMap((configAction: { type: any, sidebarData: SidebarData }) => {
                const newConfig = Object.assign({}, configAction.sidebarData);
                return of(__SidebarConfigInternalAction__({ sidebarData: newConfig }));
            })
        );
    });

    /**
     * Effect for processing the closing of the sidebar action
     */
    public readonly close$ = createEffect(() =>
        this.actions$.pipe(
            ofType(SIDEBAR_ACTIONS.close),
            withLatestFrom(this.store.pipe(SIDEBAR_SELECTORS.sidebarData)),
            tap(x => {
                const shouldClearLocalStorageForSidebar = x[0].shouldClearLocalStorageForSidebar;
                const sidebarData = x[1];

                if (shouldClearLocalStorageForSidebar) {
                    this.getSidebarExternalKeys(sidebarData)
                        .forEach(externalKey => {
                            if (externalKey) {
                                const openedSidebars = this.getOpenedSidebars();
                                if (openedSidebars[externalKey]) {
                                    delete openedSidebars[externalKey];
                                    this.storage.setItem(SIDEBAR_KEY, JSON.stringify(openedSidebars));
                                }
                            }
                        });
                }
            })
        ), { dispatch: false });

    constructor(
        private actions$: Actions,
        @Inject(LOCAL_STORAGE) private storage: StorageService,
        private store: AppStore
    ) { }

    /**
     * Checks the localStorage and finds appropriate saved sidebars
     * @param sidebarData the whole sidebar config
     */
    private initFromConfig(sidebarData: SidebarData) {
        if (sidebarData.externalKey) {
            const externalKeys = this.getSidebarExternalKeys(sidebarData);
            const openedSidebar = this.getOpenedSidebars()[externalKeys[0]];
            if (openedSidebar) {
                const storedConfig = sidebarData.buttons.find(x => x.name === openedSidebar);
                const clonedStored = Object.assign({}, storedConfig);
                return SIDEBAR_ACTIONS.changeAndOpen({ activeConfig: clonedStored, shouldAnimate: false });
            }

            return SIDEBAR_ACTIONS.close({ shouldAnimate: false, shouldClearLocalStorageForSidebar: true });
        }

        return { type: "noop" };
    }

    private setOpenedSidebar(sidebarData: SidebarData, config: SidebarConfig) {
        const sidebarName = config.name;
        if (sidebarData && sidebarData.externalKey && sidebarData.buttons.find(x => x.name === sidebarName)) {
            const openedSidebars = this.getOpenedSidebars();
            const externalKeys = this.getSidebarExternalKeys(sidebarData);
            const currentValue = openedSidebars[externalKeys[0]];
            if (currentValue !== sidebarName) {
                externalKeys.forEach(k => openedSidebars[k] = sidebarName);
                this.storage.setItem(SIDEBAR_KEY, JSON.stringify(openedSidebars));
            }
        }
    }

    private getSidebarExternalKeys(sidebarData): string[] {
        if (Array.isArray(sidebarData.externalKey)) {
            return sidebarData.externalKey;
        }

        return [sidebarData.externalKey];
    }

    private getOpenedSidebars(): Object {
        let openedSidebars = this.storage.getItem(SIDEBAR_KEY);
        openedSidebars = openedSidebars ? JSON.parse(openedSidebars) : {};
        return openedSidebars;
    }
}
