const OPERATIONS_TO_FILTER_ACCORDING_TO_BULK_LIMIT = [
    OPERATION_NAMES.moveTaxon,
    OPERATION_NAMES.mergeTaxon,
    OPERATION_NAMES.bulkEditProperties,
    OPERATION_NAMES.assignTaxons
];
import { ExecutionContext } from "../../commands/execution-context";
import { ChangeOwnerCommand } from "../../../pages/components/edit-page/commands/change-owner.command";
import { DynamicItemStore } from "../../../content/dynamic-modules/services/dynamic-item.store";
import { ContentFilterService } from "../content-filter.service";
import { createQuery } from "../../../../services/query";
import { GridReloadService } from "../../../content/dynamic-modules/services/grid-reload.service";
import { ModalWindowService } from "../modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../notification/notification.service";
import { ExternalAppConfigService } from "../../../../app-config/external-app-config.service";
import { SortersResult } from "../../../content/dynamic-modules/components/sidebar/sorter/SortingStore";
import { ActionButton } from "../../components/action-menu/action-menu-model";
import { CompositeOperationsProvider } from "../../../content/dynamic-modules/services/operations/operations-provider";
import { OperationsData } from "../../../content/dynamic-modules/services/operations/interfaces";

export interface GridOperationResult {
    modifiedItemIds: string[];
    operationName: string;
}

export const GRID_EXTENDER_TOKEN = new InjectionToken("grid-extender");

@Injectable()
export abstract class GridExtenderBase {
    private previousUrl: string;

    constructor(
                protected contentFilterService: ContentFilterService,
                protected dynamicItemStore: DynamicItemStore,
                protected settings: Settings,
                protected sortService: SortService,
                protected backendTweaksStore: BackendTweaksStore,
                protected reloadService: GridReloadService,
                protected modalWindowService: ModalWindowService,
                @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService,
                protected externalAppConfigService: ExternalAppConfigService,
                protected operationsProvider: CompositeOperationsProvider) {
    }

    abstract isSupportedType(entityData: EntityData): boolean;

    getSidebarsExternalKeys(entityData: EntityData): string[] {
        return [entityData.metadata.setName];
    }

    getCustomSidebars(ctx: CustomSidebarContext): Observable<SidebarConfig[]> {
        return of([]);
    }

    getSettingsSidebarSections(operations: Observable<Operation[]>, entityData: EntityData): Observable<SettingsSidebarSection[]> {
        const settings = new ReplaySubject<SettingsSidebarSection[]>(1);

        // Subscribing here in order to process the settings operations
        // at this stage and not when the sidebar is opened (route will be changed
        // and will include disallowed URL characters for integrated mode (colons ":");
        // this will also be unnecessary since in standalone mode we are already
        // closing any opened sidebar on direct navigation)
        operations
            .pipe(
                first()
            )
            .subscribe(o => {
                // TODO: This is a hack - change these operations category to not be settings
                const settingsOperations = o.filter(p => p.Category.Name === OPERATION_CATEGORIES.settings &&
                    p.Name !== OPERATION_NAMES.sendForTranslation &&
                    p.Name !== OPERATION_NAMES.move &&
                    p.Name !== OPERATION_NAMES.assignTaxons);

                if (Array.isArray(settingsOperations) && settingsOperations.length > 0) {
                    let sectionTitle = "Manage settings";
                    if (entityData.metadata.setName === ENTITY_SET.PAGES
                        || entityData.metadata.setName === ENTITY_SET.IMAGES
                        || entityData.metadata.setName === ENTITY_SET.ALBUMS) {
                        sectionTitle = "More options";
                    }

                    settings.next([
                        {
                            operations: settingsOperations,
                            ordinal: 100,
                            title: sectionTitle
                        }
                    ]);
                } else {
                    settings.next([]);
                }
                settings.complete();
            });

        return settings.asObservable();
    }

    getSidebarOperations(entityData: EntityData, data: OperationsData): Observable<Operation[]> {
        return this.operationsProvider.getOperations(data);
    }

    getListMainOperations(entityData: EntityData, parent: DataItem, isHierarchicalView: boolean): Observable<Operation[]> {
        return this.operationsProvider.getListMainOperations(entityData, parent, isHierarchicalView);
    }

    getBulkOperations(entityData: EntityData, modifiedEntityData: EntityData, parent: DataItem): Observable<Operation[]> {
        return this.operationsProvider.getBulkOperations(modifiedEntityData, parent);
    }

    getListItemOperations(entityData: DataItem, parent: DataItem): Observable<Operation[]> {
        return this.operationsProvider.getListItemOperations(entityData, parent);
    }

    getQuickNavigationSidebarSections(entityData: EntityData, parentItem): Observable<QuickNavigationSidebarSection[]> {
        return of([]);
    }

    initialize(router: Router): void {
        const currentUrl = router ? router.url.split("?")[0] : null;
        if (currentUrl !== this.previousUrl) {
            this.clearTemporaryData();
            this.previousUrl = currentUrl;
        }
    }

    getNavigationComponentData(entityData: EntityData, gridNavProps: GridNavigationProperties): ComponentData {
        const metadata = gridNavProps.entityData.metadata;
        if (!metadata.hasParent && !metadata.ignoreParentChildRelationship) {
            return null;
        }

        const data: ComponentData = {
            type: GridNavigationComponent,
            properties: { ...gridNavProps },
            updatePropertiesOnChange: true,
            removePreviousView: true
        };

        return data;
    }

    openEditItemInDialog(entityData: EntityData): boolean {
        return false;
    }

    getParentSetName(entityData: EntityData) {
        return null;
    }

    modifySingleItemOperations(entityData: EntityData, operations: Operation[], modifyOperationsInfo: ModifyOperationsInfo): Operation[] {
        return operations;
    }

    modifyOperations(entityData: EntityData, operations: Operation[], modifyOperationsInfo: ModifyOperationsInfo): Operation[] {
        operations = this.filterOperationsAccordingToBulkLimit(operations, modifyOperationsInfo);

        return operations;
    }

    shouldNavigateToChildGrid(dataItem: DataItem): boolean {
        return dataItem.metadata.hasChildren && !dataItem.metadata.isSelfReferencing;
    }

    shouldReloadItemsAfterEdit(args: NavigateToEditArguments, operationResult: EditInDialogOperationResult): ReloadGridContext {
        const isNewItemCreated = args.dataItem.isEmpty && operationResult.success && operationResult.dataItem && !operationResult.dataItem.isEmpty;
        const dataItem = args.dataItem;

        const reloadGrid = !dataItem.metadata.hasLifecycle && (!dataItem.isEmpty || dataItem.metadata.ignoreParentChildRelationship) || isNewItemCreated;

        return { reloadGrid };
    }

    shouldReloadItemsOnViewModeChanged(oldPresenterTemplate: string, entityData: EntityData) {
        return false;
    }

    getTitle(titleArgs: TitleArgs): Observable<string> {
        return of(`${titleArgs.entityData.metadata.displayName}`);
    }

    tryHandleAction(context: CommonActionContext): Observable<boolean> {
        if (context.actionName === OPERATION_NAMES.changeOwner) {
            return of(this.tryHandleChangeOwnerAction(context));
        }

        return of(false);
    }

    getItemsData(route: ActivatedRoute, dataFieldNames: string[], args?: ItemsDataContext): LoadItemsData {
        return null;
    }

    getChildren(entityData: EntityData, parentId: string, serviceInfo: ServiceInfo, columns: ColumnModel[]): Promise<LoadItemsResponse> {
        return new Promise(resolve => resolve(null));
    }

    isHierarchical(route: ActivatedRoute): boolean {
        return false;
    }

    getVirtualizationOptions(route: ActivatedRoute): VirtualizationOptions {
        return {
            isVirtualized: false
        };
    }

    getTotalItemsCountWithChildren(currentStateTotalCount: number, route: ActivatedRoute): Observable<number> {
        return of(currentStateTotalCount);
    }

    showFilters(entityData: EntityData): boolean {
        return true;
    }

    disableSelectAll(route: ActivatedRoute, entityData: EntityData): boolean {
        return this.isHierarchical(route);
    }

    getExpandedNodeIds(args: ExpandedNodeIdsGet): Observable<string[]> {
        return of([]);
    }

    setExpandedNodeIds(args: ExpandedNodeIdsSet): void {
    }

    syncExpandedNodeIds(args: ExpandedNodeIdsSync): void {
    }

    getCurrentPaging(args: GridArgsBase): ItemPaging {
        if (this.isPagingPersistenceEnabled()) {
            const key = args.entityData.metadata.typeFullName + args.entityData.provider;
            return this.settings.getPaging(key);
        }

        return null;
    }

    setCurrentPaging(args: CurrentPagingSet) {
        if (this.isPagingPersistenceEnabled()) {
            const key = args.entityData.metadata.typeFullName + args.entityData.provider;
            this.settings.setPaging(key, args.itemPaging);
        }
    }

    getSingleItemName(titleArgs: TitleArgs): Observable<{primary: string, secondary: string}> {
        const title = titleArgs.entityData.metadata.singularName;

        return of({
            primary: title,
            secondary: title
        });
    }

    getPluralItemName(titleArgs: TitleArgs): Observable<{primary: string, secondary: string}> {
        const title = titleArgs.entityData.metadata.displayName;
        return of({
            primary: title,
            secondary: title
        });
    }

    getEmptyScreenIcon(itemType: string): string {
        return DEFAULT_EMPTY_SCREEN_ICON;
    }

    getDefaultSort(entityData: EntityData): string {
        return  this.backendTweaksStore.getGridSortExpression(entityData.metadata.setName) || this.sortService.getDefaultSort(entityData);
    }

    showSorters(entityData: EntityData): boolean {
        return true;
    }

    getSorters(entityData: EntityData): Observable<SortersResult> {
        return null;
    }

    getDisabledFilterLoaders(route: ActivatedRoute): DisabledFilterLoaders {
        return null;
    }

    executeNavigateCommand(router: Router, route: ActivatedRoute, dataItem: DataItem, entityData: EntityData, childSetName: string = null): Observable<any> {
        return new NavigateCommand(router)
            .execute({
                currentRoute: route,
                data: {
                    dataItem: dataItem,
                    metadata: entityData,
                    parentSetName: this.getParentSetName(entityData),
                    childSetName: childSetName,
                    navigateToGrid: dataItem && this.shouldNavigateToChildGrid(dataItem),
                    isChildNavigate: dataItem && dataItem.metadata.setName === entityData.metadata.setName
                },
                model: null
            });
    }

    modifyActionContext(actionContext: CommonActionContext, routeEntityData: EntityData): Observable<CommonActionContext> {
        return of(actionContext);
    }

    modifyEntityDataForBulkOperations(entityData: EntityData, presenterTemplate: string): EntityData {
        return entityData;
    }

    getPresenterTemplate(entityData: EntityData): "List" | "Thumbs" | "Timeline" {
        return "List";
    }

    hideLoadMore(route: ActivatedRoute, entityData: EntityData): boolean {
        return false;
    }

    processEntityData(entityData: EntityData): EntityData {
        return entityData;
    }

    executeServerAction(executorService: ActionExecutorService, context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        return executorService.execute(context);
    }

    getEmptyScreenText(entityData: EntityData, pluralName$: Observable<{primary: string, secondary: string}>): Observable<string> {
        return pluralName$.pipe(map(x => `No ${new LowerCasePipe().transform(x ? x.primary : "items")} have been created`));
    }

    getFilterSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        return `Filter ${this.getSidebarDisplayName(entityData, parentItem).toLowerCase()}`;
    }

    getSortDropdownTitle(entityData: EntityData, displayName: string): string {
        const name = displayName ? displayName : this.getSidebarDisplayName(entityData, null);
        return `Sort ${name.toLowerCase()}`;
    }

    getSettingsSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        return `Settings for ${this.getSidebarDisplayName(entityData, parentItem).toLowerCase()}`;
    }

    getQuickNavigationSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        return `Browse ${this.getSidebarDisplayName(entityData, parentItem).toLowerCase()}`;
    }

    getSidebarDisplayName(entityData: EntityData, parentItem: DataItem): string {
        return entityData.metadata.displayName;
    }

    hasLongRunningTasks(entityData: EntityData): boolean {
        return false;
    }

    getNotificationServiceFilter(entityData: EntityData) {
        return entityData.metadata.typeFullName;
    }

    getTakeItemsCount(entityData: EntityData) {
        return this.externalAppConfigService.externalConfig.contentItemsPerPage;
    }

    getDataFieldNames(columns: ColumnModel[], entityData: EntityData): string[] {
        const dataFieldNames = [entityData.metadata.key];
        columns.filter(x => x.dataFieldNames).forEach((column) => {
            column.dataFieldNames.forEach(x => {
                if (entityData.metadata.properties.hasOwnProperty(x) && dataFieldNames.indexOf(x) < 0) {
                    dataFieldNames.push(x);
                }
            });
        });

        if (entityData.metadata.hasParent) {
            dataFieldNames.push(entityData.metadata.parentIdProperty);
        }

        return dataFieldNames;
    }

    getAsyncColumnsValues(columns: ColumnModel[], entityData: EntityData, itemsState: ItemsState, siteId: string, bundleDataService: BundleDataService) {
        if (columns.find(c => c.name === Properties.USED_ON)) {
            // if there is a skip then we are loading more. In this scenario we do not want to clear the cache
            bundleDataService.requestBatch(itemsState.dataItems.map(x => <ActionExecutionContext>{
                id: x.key,
                action: BUNDLE_DATA_OPERATIONS.SHARED_IN_COUNT,
                entityData
            }), entityData, siteId, !itemsState.skip);
        }
    }

    reloadItems(queryParams: { [key: string]: string }, parentId: string, entityData: EntityData, sortParam: string, dataFieldNames: string[]): Observable<StateWrapper> {
        const loadItemsArg = this.contentFilterService.getLoadArguments(queryParams, parentId, entityData, sortParam, dataFieldNames);
        this.dynamicItemStore.loadItems(loadItemsArg);
        return NEVER;
    }

    loadMore(ctx: GridLoadMoreContext): Observable<StateWrapper> {
        let query = null;
        const skip = this.dynamicItemStore.getLoadedItemsCount(ctx.entityData);
        const take = this.dynamicItemStore.getLeftItemsCount(ctx.entityData);

        if (ctx.treeConfig.isHierarchical) {
            // TODO: Add search parameter to extender
            this.getExpandedNodeIds({ entityData: ctx.entityData }).subscribe((expandedNodeIds: string[]) => {
                ctx.treeConfig.expandedNodeIds = expandedNodeIds;
                const loadItemsArg: LoadItemsData = this.getItemsData(ctx.route, ctx.dataFieldNames, {
                    expandedNodeIds: expandedNodeIds,
                    action: ctx.action,
                    skip: skip,
                    take: take,
                    order: ctx.order
                });

                this.dynamicItemStore.loadItems(loadItemsArg);
            });
        } else {
            if (ctx.executedSearchParameter || (ctx.parentId && ctx.entityData.metadata.hasParent)) {
                query = createQuery()
                    .where()
                    .and();

                if (ctx.parentId && ctx.entityData.metadata.hasParent) {
                    query = query.eq(ctx.entityData.metadata.parentIdProperty, ctx.parentId);
                }

                if (ctx.executedSearchParameter) {
                    query = this.contentFilterService.applySearch(ctx.executedSearchParameter, ctx.entityData, query);
                }

                query = query.done().done();
            }

            this.dynamicItemStore
                .loadItems({
                    entityData: ctx.entityData,
                    query,
                    action: ctx.action,
                    order: ctx.order,
                    skip: skip,
                    take: take,
                    fallbackProperties: [ctx.entityData.metadata.defaultFieldName],
                    dataFieldNames: ctx.dataFieldNames
                });
        }

        return NEVER;
    }

    hideSidebarLanguagesDropdown(entityData: EntityData): boolean {
        return false;
    }

    modifyColumns(columns: ColumnModel[]): ColumnModel[] {
        return columns;
    }

    protected isPagingPersistenceEnabled(): boolean {
        return false;
    }

    protected clearTemporaryData() {
        this.settings.clearPaging();
    }

    protected filterOperationsAccordingToBulkLimit(operations: Operation[], modifyOperationsInfo: ModifyOperationsInfo): Operation[] {
        if (this.areCurrentSelectedItemsMoreThanBulkLimit(modifyOperationsInfo)) {
            operations = operations.filter(op => !OPERATIONS_TO_FILTER_ACCORDING_TO_BULK_LIMIT.includes(op.Name));
        }

        return operations;
    }

    private areCurrentSelectedItemsMoreThanBulkLimit(modifyOperationsInfo: ModifyOperationsInfo): boolean {
        let currentSelectedItems = modifyOperationsInfo.currentItemSelectionInfo.selectedItems.size;
        if (modifyOperationsInfo.previousItemSelectionInfo.allItemsSelected) {
            if (modifyOperationsInfo.currentItemSelectionInfo.deselectedItems.size > 0) {
                // after selecting all items(total) the user decides to deselect some
                currentSelectedItems = modifyOperationsInfo.itemsState.totalCount - modifyOperationsInfo.currentItemSelectionInfo.deselectedItems.size;
            } else {
                currentSelectedItems = modifyOperationsInfo.itemsState.totalCount;
            }
        }

        if (currentSelectedItems > BULK_ITEMS_LIMIT) {
            return true;
        }

        return false;
    }

    private getExpandedChildItems (dataItem: DataItem): DataItem[] {
        const allItems = [];

        if (dataItem.data.Children) {
            dataItem.data.Children.forEach(child => {
                const childDataItem = DataItem.from(child, dataItem.metadata, dataItem.provider, dataItem.culture);
                if (childDataItem.isTranslated) {
                    allItems.push(childDataItem);
                }

                allItems.push(...this.getExpandedChildItems(childDataItem));
            });
        }

        return allItems;
    }

    private tryHandleChangeOwnerAction(context: CommonActionContext): boolean {
        const ctx: ExecutionContext = {
            currentRoute: context.route,
            data: {
                selectedItems: context.item.data ? [context.item] : [],
                entityData: context.item
            },
            model: null
        };
        const command = new ChangeOwnerCommand(this.modalWindowService, this.dynamicItemStore, this.notificationService);

        command.execute(ctx).subscribe(() => {
            this.reloadService.requestReload();
        });

        return true;
    }
}

export interface Breadcrumb {
    hasBreadcrumb: boolean;
    tokens?: string[]
}

export interface ItemsDataContext {
    expandedNodeIds?: string[]
    action?: string;
    skip?: number;
    take?: number;
    order?: string;
}

export interface CommonActionContext {
    actionName: string;
    item: DataItem;
    route: ActivatedRoute;
    data?: any;
    additionalQueryParams?: any[];
}

export interface LoadingActionContext extends CommonActionContext {
    loadingHolder: { loading: boolean };
}

export interface GridActionContext extends CommonActionContext {
    grid: DynamicItemIndexComponent;
    action?: ActionButton,
}

export interface TitleArgs extends GridArgsBase {
    parentItem: DataItem;
    includeChildSet: boolean;
    route?: ActivatedRoute;
}

export interface ExpandedNodeIdsGet extends GridArgsBase {
}

export interface ExpandedNodeIdsSet extends ExpandedNodeIdsGet {
    expandedIds: string[]
}

export interface CurrentPagingSet extends GridArgsBase {
    itemPaging: ItemPaging
}

export interface ItemPaging {
    [key: string]: number
}

export interface ExpandedNodeIdsSync extends ExpandedNodeIdsSet {
    dataItems: DataItem[];
}

export interface GridArgsBase {
    entityData: EntityData;
}

export interface GridLoadMoreContext {
    executedSearchParameter: string;
    parentId: string;
    entityData: EntityData;
    action: string;
    order: string
    treeConfig: TreeConfig;
    route: ActivatedRoute;
    dataFieldNames: string[];
    currentState?: ItemsState;
}

export interface CustomSidebarContext {
    entityData: EntityData;
    currentRoot: DataItem;
    parent$: Observable<DataItem>;
    route: ActivatedRoute;
    operationCompleted$: Observable<GridOperationResult>;
}

export interface ReloadGridContext {
    reloadGrid: boolean;
    reloadTasks?: boolean;
}
