import { BehaviorSubject, Observable, of } from "rxjs";
import { Component, Input, OnInit, OnDestroy, ViewChild, Inject } from "@angular/core";
import { DataContextComponent, DataContext } from "../../models/data-context-component";
import { TaxaInfoStore } from "../../../content/dynamic-modules/services/taxa-info-store";
import { ModalWindowService, DialogData, ClosingContext } from "../../services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ModalListComponent } from "../modal-list/modal-list.component";
import { RESOLVE_NAMES } from "../../../content/constants";
import TAXONOMY_CONSTANTS from "../../../taxonomy/taxonomy.constants";
import { MainFieldComponent } from "../../../content/dynamic-modules/components/grid-cells/main-field/main-field.component";
import { Properties } from "../../fields.constants";
import { DateAndUserComponent } from "./date-and-user.component";
import { RemoveComponent } from "./remove.component";
import { TypeInfoComponent } from "./type-info.component";
import { Entity, DEFAULT_FIELD_NAME } from "../../services/metadata/meta-data.store";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { COMMAND_NAMES } from "../../../content/dynamic-modules/components/commands";
import { CompositeOperationsProvider } from "../../../content/dynamic-modules/services/operations/operations-provider";
import { OperationsData, OperationsTarget } from "../../../content/dynamic-modules/services/operations/interfaces";
import { Operation, OPERATION_NAMES } from "../action-menu/operation.model";
import { tap } from "rxjs/operators";
import { ColumnModel } from "../../models/column-model";
import { WINDOW_TOKEN } from "../../../../window.provider";

const MARKED_ITEM_TYPE_FULL_NAME = "Telerik.Sitefinity.Web.Api.OData.Operations.Taxonomies.Models.MarkedItem";

@Component({
    selector: "sf-applied-to",
    templateUrl: "./applied-to-component.html"
})
export class AppliedToComponent implements OnInit, OnDestroy, DataContextComponent {
    @Input() public context: DataContext;
    public itemCount: number = 0;
    public badgeLook: string = "ellipse";
    @ViewChild("itemTemplate", { static: true }) template: any;
    private operations: Operation[];

    constructor(private route: ActivatedRoute, private store: TaxaInfoStore, private modalService: ModalWindowService, private operationsProvider: CompositeOperationsProvider, @Inject(WINDOW_TOKEN) private window: Window) { }

    ngOnInit() {
        this.itemCount = this.context.dataItem.data.AppliedTo;
        if (this.itemCount) {
            this.badgeLook += " positive";
        }
    }

    ngOnDestroy() {
        this.store.invalidateCache(this.context.dataItem);
    }

    public onDetailsSelected(): void {
        this.getOperations().subscribe((operations: Operation[]) => {
            const metadataContainer = this.route.parent.snapshot.data[RESOLVE_NAMES.metadata];
            const count = new BehaviorSubject<number>(this.itemCount);

            const metadata = new Entity(
                MARKED_ITEM_TYPE_FULL_NAME,
                {
                    keys: ["Id"],
                    properties: {
                        [DEFAULT_FIELD_NAME]: "Title"
                    }
                });

            const componentData: ComponentData = {
                type: ModalListComponent,
                properties: {
                    contentLook: "large",
                    listLook: "read-only",
                    actionTitle: this.getModalTitle(this.context.dataItem.metadata.setName, this.context.dataItem.title),
                    action: `Default.GetMarkedItems()`,
                    hideItemTitle: true,
                    metadataContainer,
                    dataItem: this.context.dataItem,
                    count,
                    treeConfig: {
                        multiSelection: false,
                        isHierarchical: false,
                        showBreadcrumb: false,
                        status: true,
                        clickable: true,
                        noSelection: true
                    },
                    template: this.template,
                    openItemEdit: false,
                    showDataItemTitle: false,
                    columns: this.getModalColumns(this.context.dataItem, operations),
                    metadata: metadata
                }
            };

            const dialogData = new DialogData(componentData, (context: ClosingContext) => {
                if (context.component && context.component.itemsModified && this.context.invoker) {
                    this.context.invoker.invoke({
                        name: COMMAND_NAMES.refresh
                    });
                }
            }, [], null, "-bottom");
            this.modalService.setMapping(dialogData);
            this.modalService.open(this.route);
        });
    }

    private getOperations(): Observable<Operation[]> {
        if (this.operations) {
            return of(this.operations);
        }

        const data = new OperationsData(this.context.dataItem, OperationsTarget.List, undefined, { origin: this.window.location.href });
        return this.operationsProvider.getOperations(data).pipe(tap(operations => this.operations = operations));
    }

    private getModalTitle(setName: string, itemTitle: string): string {
        let title = `Items tagged with "${itemTitle}"`;

        if (setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA) {
            title = `Items categorized with "${itemTitle}"`;
        }

        return title;
    }

    private getModalColumns(dataItem: DataItem, operations: Operation[]): ColumnModel[] {
        const columns: ColumnModel[] = [
            {
                name: "ITEM TITLE",
                title: "ITEM TITLE",
                css: "-title -status",
                componentData: {
                    type: MainFieldComponent,
                    properties: {
                        hasStatusIcon: true,
                        showStatusText: false
                    }
                }
            },
            {
                name: Properties.PUBLICATION_DATE,
                title: "CREATED ON",
                css: "-col-size-s",
                componentData: {
                    type: DateAndUserComponent
                }
            },
            {
                name: "ContentTypeInfo",
                title: "CONTENT TYPE",
                css: "-col-size-s",
                componentData: {
                    type: TypeInfoComponent
                }
            }
        ];

        const deleteOperation = operations.find(o => o.Name === OPERATION_NAMES.delete);
        if (deleteOperation) {
            columns.push({
                name: "REMOVE",
                title: "REMOVE",
                css: "-col-size-2xs -action -sf-mr-xs",
                componentData: {
                    type: RemoveComponent,
                    properties: {
                        itemToRemove: dataItem,
                        action: "Default.RemoveItemFromTaxon()"
                    }
                }
            });
        }

        return columns;
    }
}
