import { Component, OnInit } from "@angular/core";
import { NEVER, Observable } from "rxjs";
import { FieldRegistration } from "../../src/app/api";
import { HttpODataRequestWrapper } from "../../src/app/modules/shared/services/http-odata-request.wrapper";
import { ContentListWidgetFieldsChangeService } from "../../src/app/modules/widget-editor/services/content-list-widget-field-change.service";
import { Logger } from "../../src/app/modules/shared/services/logger-source/logger";
import { AppStore } from "../../src/app/services/store/app-store";
import { FIELDS_SELECTORS } from "../../src/app/services/store/selectors/selectors.fields";
import { createValueAccessor } from "../field-base";
import { ChoiceComponent } from "./choice.component";
import { ChoiceSettings } from "./choice.settings";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-choice-service-url",
    templateUrl: "./choice-service-url.component.html",
    providers: [createValueAccessor(ChoiceServiceUrlComponent)]
})
export class ChoiceServiceUrlComponent extends ChoiceComponent implements OnInit {
    initialChoices: ChoiceItem[];

    constructor(
        httpRequestWrapper: HttpODataRequestWrapper,
        private store: AppStore,
        logger: Logger) {
        super(httpRequestWrapper, logger);
    }

    ngOnInit() {
        super.ngOnInit();
        const serviceUrl = this.settings.choiceServiceUrl;
        if (serviceUrl) {
            this.registerSubscription(this.store.pipe(FIELDS_SELECTORS.changeItemType)
                .subscribe(value => {
                    if (value && value.itemType) {
                        this.setHidden(false);
                        this.httpRequestWrapper.get$(value.itemType + serviceUrl).subscribe(x => {
                            if (!x.isLoading) {
                                if (this.initialChoices) {
                                    this.writeValue(x.content.value[0].Value);
                                }

                                this.initialChoices = x.content.value;

                                const processed = ContentListWidgetFieldsChangeService.processSelectedItemsFieldChange(value.value, [this]);
                                if (!processed) {
                                    this.setChoices(this.initialChoices);
                                }
                            }
                        }, () => {
                            this.settings.choices = [];
                            this.choices = [];
                            super.ngOnInit();
                        });
                    } else {
                        this.setHidden(true);
                    }
                })
            );
        }
    }

    protected loadChoices(): Observable<void> {
        // loading of choices is customized and handled in the AppStore subsription callback in ngOnInit
        return NEVER;
    }

    setChoices(choices: ChoiceItem[]) {
        this.settings.choices = choices;
        this.mapChoiceItems();
        const currentValue = this.getValue();
        super.ngOnInit();

        const choicesContainCurrentValue = this.choices.findIndex(x => x.Value === currentValue) > -1;
        if (!choicesContainCurrentValue) {
            this.writeValue(this.choices[0].Value);
        } else {
            this.writeValue(currentValue);
        }

        this.choiceSettings = {
            key: this.settings.key,
            wrapperCssClass: this.settings.look
        };
    }
}

export const CHOICE_SERVICE_URL_SETTINGS_REGISTRY: FieldRegistration = {
    writeComponent: ChoiceServiceUrlComponent,
    readComponent: ChoiceServiceUrlComponent,
    settingsType: ChoiceSettings
};
