import { tap } from "rxjs/operators";
import { Observable } from "rxjs";

import { LocatableDynamicItemService, LocatabaleEntitySetNamesResponse } from "../../../../../../../content/dynamic-modules/services/locatable-dynamic-item.service";
import { LoadingState } from "../../../../../../../shared/rxjs-extensions/delayEmission";
import { Logger } from "../../../../../../../shared/services/logger-source/logger";
import { ENTITY_SET } from "../../../../../../../shared/services/metadata/meta-data-constants";
import { MetadataContainer } from "../../../../../../../shared/services/metadata/meta-data.store";
import { SelectorBase } from "../selector-base";
import { EntitySelectorItem } from "./entity-selector-item";
import { LoadingContentState } from "../../../../../../../shared/rxjs-extensions/toLoadingState";

export class EntitySelector extends SelectorBase<EntitySelectorItem> {
    constructor(
        logger: Logger,
        private locatableItemsService: LocatableDynamicItemService,
        private meta: MetadataContainer) {
        super(logger);
    }

    protected setSelectedItem(value: EntitySelectorItem) {
        this.context.selectedEntitySet = value;
        super.setSelectedItem(value);
    }

    onInit(): Observable<LoadingState> {
        return this.locatableItemsService.getLocatableEntitySetNames(this.context.selectedSite.value).pipe(
            tap((sets: LoadingContentState<LocatabaleEntitySetNamesResponse>) => {
                if (!sets.isLoading) {
                    const locatableSets = sets.content.value
                        .filter(setName => this.meta.entities[setName])
                        .map(setName => <EntitySelectorItem>{ Title: this.meta.entities[setName].displayName, value: setName, entity: this.meta.entities[setName] });
                    this.items = locatableSets;
                    this.preSelectPagesAndMoveToTop();
                }
            }));
    }

    private preSelectPagesAndMoveToTop() {
        const pagesSetIndex = this.items.findIndex(x => x.value === ENTITY_SET.PAGES);
        if (pagesSetIndex < 0) {
            this.setSelectedItem(this.items[0]);
            return;
        }

        const pagesSet = this.items[pagesSetIndex];
        this.items.splice(pagesSetIndex, 1);
        this.items.unshift(pagesSet);
        const selectedEntitySet = this.items[0];
        this.setSelectedItem(selectedEntitySet);
    }
}
