import { SelectorConstants, TAG_NAMES, NODE_NAMES } from "../selector-constants";

const TRAILING_BREAK = "<br class='k-br'>";
export const KENDO_TRAILING_BREAK = "k-br";

export const ensureTrailingBreaks = (html: string): string => {
    return `${TRAILING_BREAK}${html}${TRAILING_BREAK}`;
};

export const removeTrailingBreaks = (element: HTMLElement): void => {
    if (element.previousElementSibling
        && element.nextElementSibling
        && element.previousElementSibling.classList.contains(KENDO_TRAILING_BREAK)
        && element.nextElementSibling.classList.contains(KENDO_TRAILING_BREAK)) {
        element.nextElementSibling.remove();
        element.previousElementSibling.remove();
    }
};

export const isImageHyperlink = (element: HTMLElement): boolean => {
    if (!element) {
        return;
    }

    const isHyperlink = element.parentElement && element instanceof HTMLImageElement && element.parentElement instanceof HTMLAnchorElement;

    return isHyperlink;
};

export const isImageImmutableSelected = (element: HTMLElement): boolean => {
    if (!element) {
        return;
    }

    const isImageImmutable = element instanceof HTMLImageElement || (element instanceof HTMLAnchorElement && element.querySelector(NODE_NAMES.IMAGE_ELEMENT));

    return !!isImageImmutable;
};

export const isEmbedImmutableSelected = (element: HTMLElement): boolean => {
    if (!element) {
        return;
    }

    const isEmbedImmutable = element.attributes[SelectorConstants.SF_IMMUTABLE] && element.querySelector(TAG_NAMES.IFRAME);

    return !!isEmbedImmutable;
};
