import { Injectable } from "@angular/core";
import { isFileTypeAllowed, getExtensionFromFileName, getValidateExtensionsErrorMessage } from "../../utils";
import { FileSizePipe } from "../../../../fields/common/pipes/file-size.pipe";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";

@Injectable()
export class MediaValidationHelper {

    private mediaEntity: MediaEntity;
    private files: File[];
    private errorMessages: string[];
    private validFiles: File[];
    private fileSizePipe = new FileSizePipe();

    validate(mediaEntity: MediaEntity, files: File[], fullCheck: boolean = true): boolean {
        this.mediaEntity = mediaEntity;
        this.files = files;
        this.errorMessages = [];
        let isValid = true;
        this.validFiles = [];

        if (this.files.length === 0) {
            return false;
        }

        for (let index = 0; index < this.files.length; index++) {
            const file = this.files[index];

            const validatesFileExtension = this.validateFileExtension(file);
            const validatesFileMediaType = this.validateFileMediaType(file);
            if (!validatesFileExtension) {
                this.errorMessages.push(this.getValidateExtensionsErrorMessage());
            } else {
                if (!validatesFileMediaType) {
                    this.errorMessages.push(this.getValidateMediaTypeErrorMessage(file));
                }
            }

            const validatesFileSize = this.validateFileSize(file);
            if (!validatesFileSize) {
                this.errorMessages.push(this.getValidateFileSizeErrorMessage());
            }

            if (validatesFileExtension && validatesFileSize && validatesFileMediaType) {
                this.validFiles.push(file);
            }
        }

        if ((fullCheck && this.validFiles.length !== this.files.length) || (!this.validFiles || this.validFiles.length === 0)) {
            isValid = false;
        }

        this.errorMessages = Array.from(new Set(this.errorMessages));

        return isValid;
    }

    validateLibrarySizeExceeded(currentlySelectedFilesSizeInKb: number, totalLibrarySizeInKb: number, maxLibrarySizeInKb: number): boolean {
        if (maxLibrarySizeInKb <= 0) {
            return false;
        }

        const isLibraryExceeded = currentlySelectedFilesSizeInKb + totalLibrarySizeInKb >= maxLibrarySizeInKb;
        return isLibraryExceeded;
    }

    getValidFiles(): File[] {
        return this.validFiles;
    }

    getErrorMessages(): string[] {
        return this.errorMessages;
    }

    getAcceptableFileTypes(acceptableFileTypes: string[]): string {
        if (acceptableFileTypes.length === 1 && acceptableFileTypes[0] === "*") {
            // for some reason an html input with accept=".*" makes the file select window
            // on a macOS device display the files as inactive
            return "*";
        } else {
            return acceptableFileTypes.map(x => `.${x}`).join(", ");
        }
    }

    private getValidateExtensionsErrorMessage(): string {
        return getValidateExtensionsErrorMessage(this.mediaEntity.acceptableFileTypes);
    }

    private getValidateMediaTypeErrorMessage(file: File): string {
        let fileTypeMessage = "Invalid file type";
        if (file.type) {
            fileTypeMessage += ` ${file.type}`;
        }

        if (this.mediaEntity.acceptableMediaTypes && this.mediaEntity.acceptableMediaTypes.length > 0) {
            fileTypeMessage += `. Allowed file types: ${this.mediaEntity.acceptableMediaTypes.join(", ")}`;
        }

        return `${fileTypeMessage}.`;
    }

    private getValidateFileSizeErrorMessage(): string {
        return "Invalid file size. Max size: " + this.fileSizePipe.transform(this.mediaEntity.maxSize);
    }

    private validateFileMediaType(file: File): boolean {
        let valid = true;
        if (this.mediaEntity.mediaFilterEnabled) {
            // in Firefox some videos' type include the codec parameter (video/mp4;codecs=avc1) and we only want to validate against "video/mp4"
            const mimeType = file.type && file.type.length ? file.type.split(";").shift() : file.type;
            valid = isFileTypeAllowed(mimeType, this.mediaEntity.acceptableMediaTypes);
        }

        return valid;
    }

    private validateFileExtension(file: File): boolean {
        let valid = true;
        if (this.mediaEntity.mediaFilterEnabled) {
            valid = file.name ? isFileTypeAllowed(getExtensionFromFileName(file.name), this.mediaEntity.acceptableFileTypes) : true;
        }

        return valid;
    }

    private validateFileSize(file: File): boolean {
        return this.mediaEntity.maxSize === 0 || file.size <= this.mediaEntity.maxSize;
    }
}
