import { ClassProvider, Injectable } from "@angular/core";
import { TAB_NAME_CONTENT } from "../../../../pages/components/zone-editor/enhanced-page.component";
import { ZoneEditorBaseExtender, ZONE_EDITOR_EXTENDER_TOKEN } from "../../../../pages/components/zone-editor/extenders/zone-editor-base-extender";
import { CLASS_MODIFIER_NO_OUTLINE, CLASS_MODIFIER_ROOT } from "../../../../pages/services/document-enhancer.constants";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";

@Injectable()
export class ZoneEditorFormsExtender extends ZoneEditorBaseExtender {
    canHandle(typeSetName: string): boolean {
        return typeSetName === ENTITY_SET.FORMS;
    }

    getEmptyRootCssClasses(): string [] {
       return [CLASS_MODIFIER_ROOT, CLASS_MODIFIER_NO_OUTLINE];
    }

    useNarrowLook(): boolean {
        return true;
    }

    getInitialWidgetSelectorTabName(): string {
        return TAB_NAME_CONTENT;
    }
}

export const ZONE_EDITOR_FORMS_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: ZONE_EDITOR_EXTENDER_TOKEN,
    useClass: ZoneEditorFormsExtender
};
