import { Component, OnInit, Output, EventEmitter } from "@angular/core";
import { FieldRegistration } from "../../fields-builder/services/fields-registry";
import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { FieldBase } from "../../../../../../fields";
import { stringConstants } from "../../../../common-constants";

export const DEFAULT_SELECTED_COLOR = "#DCECF5";
const MAX_HEX_SYMBOLS = 7; // first symbol is always # and then we can have 3 or 6 symbols more in total of 7

@Component({
    selector: "sf-color-picker",
    templateUrl: "./color-picker.component.html",
    styleUrls: ["./color-picker.component.scss"]
})
export class ColorPickerComponent extends FieldBase<ColorPickerSettings> implements OnInit {
    @Output() selectionChange: EventEmitter<string> = new EventEmitter<string>();
    public selectedColor: string;
    public palette: Array<string> = DEFAULT_COLORS_PALETTE;
    public inputSelectedColor: string;

    ngOnInit() {
        super.ngOnInit();
        this.selectedColor = this.value || this.settings.defaultValue || DEFAULT_SELECTED_COLOR;
        this.inputSelectedColor = this.selectedColor;

        if (this.settings.colorPaletteColors) {
            const colors = this.settings.colorPaletteColors.split(",");
            this.palette = colors;
        }
    }

    onColorClick(color: string) {
        this.selectedColor = color;

        this.emitSelectedColor();
    }

    onInputFocus(event: Event) {
        // Prevent closing the dropdown when input is focused
        event.stopImmediatePropagation();
    }

    onInputFocusout() {
        this.emitSelectedColor();
    }

    onInputChange() {
        const selectedColor = this.prependHexSymbol(this.inputSelectedColor);
        this.inputSelectedColor = selectedColor;

        this.setSelectedColor(selectedColor);
    }

    onButtonClick(dropped: boolean) {
        this.inputSelectedColor = this.selectedColor;
    }

    private emitSelectedColor() {
        this.writeValue(this.selectedColor);
        this.selectionChange.emit(this.selectedColor);
    }

    private prependHexSymbol(color: string): string {
        let modifiedColor = color;
        // Set # symbol as first value
        if (color[0] !== stringConstants.HASH) {
            modifiedColor = `${stringConstants.HASH}${color}`;
        }

        return modifiedColor;
    }

    private setSelectedColor(color: string) {
        const isValidHex = color.match(/^#?([0-9a-fA-F]{3})([0-9a-fA-F]{3})?$/) !== null;

        if (isValidHex) {
            this.selectedColor = this.convertHex(color);
        }
    }

    private convertHex(color: string): string {
        let modifiedColor = color;

        if (color.length < MAX_HEX_SYMBOLS) {
            // Duplicate every value different then # in order the color to be 6 symbols
            modifiedColor = stringConstants.HASH + modifiedColor.split(stringConstants.EMPTY_STRING).map((hex) => {
                if (hex !== stringConstants.HASH) {
                    return hex + hex;
                }
            }).join(stringConstants.EMPTY_STRING);
        }

        return modifiedColor.toUpperCase();
    }
}

export class ColorPickerSettings extends SettingsBase {
    markAsDirty = true;
    defaultValue = DEFAULT_SELECTED_COLOR;
    useDefaultValue = true;
    colorPaletteColors: string;
}

export const COLOR_PICKER_REGISTRY: FieldRegistration = {
    writeComponent: ColorPickerComponent,
    readComponent: ColorPickerComponent,
    settingsType: ColorPickerSettings
};

