import { Component, AfterViewChecked, Inject } from "@angular/core";
import { trigger, transition } from "@angular/animations";
import { ANIMATION_LEFT_TO_RIGHT, isAnimationTypeRightToLeft, isAnimationTypeLeftToRight, ANIMATION_RIGHT_TO_LEFT, ANIMATION_TO_TOP, isAnimationTypeToTop } from "../../animations/animation-utilities";
import { ContextualHelpService } from "../../modules/contextual-help/contextual-help.service";
import { CompositeThemeProvider } from "../../theme/composite-theme-provider";
import { UserPreferencesService } from "../../modules/shared/user-preferences/user-preferences.service";
import { AuthService } from "../../modules/auth/auth.service";
import { Router, NavigationEnd, NavigationStart } from "@angular/router";
import { DOCUMENT_TOKEN } from "../../document.provider";
import { toggleIrisIntegratedStyles } from "../../utils";
import { filter } from "rxjs/operators";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "./../../constants/route-paths";
import { EnvironmentService } from "../../modules/shared/services/environment.service";
import { environmentTypes } from "../../environment";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const SITEFINITY_EDIT_PAGE_URL = "/Action/Edit";
const SITEFINITY_EDIT_TEMPLATE_URL = "/templates/Template/";
const INITIAL_LOADING_CLASS = "sfInitialAdminAppLoading";

@Component({
    selector: "sf-app",
    templateUrl: "./app.component.html",
    animations: [
        trigger("routerAnimations", [
            // right to left
            transition(isAnimationTypeRightToLeft, ANIMATION_RIGHT_TO_LEFT),
            // left to right
            transition(isAnimationTypeLeftToRight, ANIMATION_LEFT_TO_RIGHT),
            // to Top
            transition(isAnimationTypeToTop, ANIMATION_TO_TOP)
        ])
    ]
})
export class AppComponent extends SfRxBase implements AfterViewChecked {
    public isAnimating: boolean;

    constructor(
        private contextualHelpService: ContextualHelpService,
        private compositeThemeProvider: CompositeThemeProvider,
        private authService: AuthService,
        private userPreferencesService: UserPreferencesService,
        private router: Router,
        @Inject(DOCUMENT_TOKEN) private document: Document,
        private envService: EnvironmentService) {

        super();

        // Apply new application theme if such is provided.
        this.compositeThemeProvider.applyTheme();

        this.initializePreferences();

        // we want to remove the default ASP.NET form submit action when we are on an Iris page
        // since hitting an Enter in an input that is outside of a form (e.g. Search in item grid)
        // sends a Submit action and refreshes Siefinity along with Iris
        // we check either for events exist since testbed mocks do not always stub it
        if (this.router.events) {
            const subsctiption = this.router.events.pipe(filter(ev => (ev instanceof NavigationEnd || ev instanceof NavigationStart)))
                                                    .subscribe((ev: NavigationEnd) => {
                if (ev instanceof NavigationEnd ) {
                    this.showSitefinityHeader();
                }
                if (ev instanceof NavigationEnd
                    && ev.urlAfterRedirects.includes(`${ROUTE_PATHS.ROOT_PREFIX}/`)
                    && !(ev.urlAfterRedirects.includes(`${ROUTE_PATHS.PAGES}/`) && ev.urlAfterRedirects.includes(SITEFINITY_EDIT_PAGE_URL))
                    && !(ev.urlAfterRedirects.includes(`${ROUTE_PATHS.TEMPLATES}/`) && ev.urlAfterRedirects.includes(SITEFINITY_EDIT_TEMPLATE_URL))
                    && !ev.urlAfterRedirects.includes(`${ROUTE_PATHS.CONTENT}/${ROUTE_PATHS_NO_PREFIX.FORMS}/`)) {
                    toggleIrisIntegratedStyles(true);
                    const form = this.document.querySelector("form#aspnetForm") as HTMLFormElement;

                    if (form) {
                        form.onsubmit = () => { return false; };
                    }
                }

                //Add -sf-integrated-app if in Iris stand alone
                const env =  this.envService.getEnvironment();
                if (env !== environmentTypes.integration) {
                    toggleIrisIntegratedStyles(true);
                }
            });

            this.registerSubscription(subsctiption);
        }
    }

    showSitefinityHeader() {
        // shows Sitefinity navigation after the AdminApp is loaded
        const aspForm = this.document.querySelector(`.${INITIAL_LOADING_CLASS}`);

        if (aspForm && aspForm.classList && aspForm.classList.contains(INITIAL_LOADING_CLASS)) {
            aspForm.classList.remove(INITIAL_LOADING_CLASS);
        }
    }

    prepareRouteTransition(outlet) {
        const animation = outlet.activatedRouteData["animation"] || {};
        return animation["value"] || null;
    }

    ngAfterViewChecked() {
        this.contextualHelpService.triggerLoad();
    }

    animationStarted() {
        this.isAnimating = true;
    }

    animationDone() {
        this.isAnimating = false;
    }

    private initializePreferences() {
        this.authService.loggedIn.subscribe((data) => {
            if (data) {
                this.userPreferencesService.checkAccessibility();
            }
        });
    }
}
