import { ClassProvider, Injectable } from "@angular/core";
import { FieldRegistration, FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { FIELDS_PROVIDER_TOKEN, FieldRegistryKey, DefaultFieldsProvider } from "../../../shared/fields-builder/providers/fields-registration-provider";
import { ChoiceComponent } from "../../../../../../fields/choice/choice.component";
import { FieldConstants, PropertyEditorWidgets } from "../../property-editor.constants";

@Injectable()
export class YesNoFieldProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.fieldType === FieldTypes.choiceList && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ChoiceComponent,
                settingsType: YesNoChoiceSettings
            };
    }
}

export class YesNoChoiceSettings extends ChoiceSettings {
    public init(metadata: any) {
        super.init(metadata);
        this.choices = [{ Name: FieldConstants.YES_LABEL, Value: "True" }, { Name: FieldConstants.NO_LABEL, Value: "False" }];
        this.look = "inline";
    }
}

export const YES_NO_FIELD_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: YesNoFieldProvider,
    multi: true
};
