import { Component, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ModalWindowService, DialogData, ClosingContext } from "../../services/modal-window.service";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ModalListComponent } from "../modal-list/modal-list.component";
import { toLoadingState, delayEmission } from "../../rxjs-extensions";
import { FieldRegistration } from "../../fields-builder/services/fields-registry";
import { FieldBase } from "../../../../../../fields/field-base";
import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { BehaviorSubject, ReplaySubject, Subscription } from "rxjs";
import { startWith } from "rxjs/operators";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { stringConstants } from "../../../../common-constants";
import { UrlHelper } from "../../../../services/url.helper";
import { ComponentData } from "@progress/sitefinity-component-framework";

@Component({
    templateUrl: "./site-sync-item-info.components.html",
    selector: "sf-site-sync-item-info"
})
export class SiteSyncItemInfoComponent extends FieldBase implements OnInit {
    public targetSiteId$ = new ReplaySubject<string>(1);
    public isLoading: boolean = false;
    public dependenciesTotalCount = 0;
    public targetServersDropDownSettings;
    public targetServers = [];
    public additionalDescription;
    public targetSiteId = stringConstants.EMPTY_STRING;
    protected dependenciesCountText = stringConstants.EMPTY_STRING;
    protected itemTypeName;
    private syncDependenciesCountSubscription: Subscription;

    constructor(protected modalService: ModalWindowService, protected route: ActivatedRoute, private itemService: DynamicItemService) {
        super();
    }

    ngOnInit(): void {
        const fieldValue = this.tryParseJSON(this.getValue());
        if (fieldValue) {
            this.targetServers = fieldValue.TargetServers.map(el => {
                const name = UrlHelper.removeProtocol(el.ServerAddress);
                const value = el.ServerId;
                return {
                    Name: el.ServerUserFriendlyName || name,
                    Address: el.ServerAddress,
                    Value: value
                };
            });

            this.targetServersDropDownSettings = ChoiceDropdownComponent.createFieldSettings(this.targetServers, null, null, "inline sf-mt-4xs");
            this.targetSiteId = this.targetServers[0].Value;
            this.additionalDescription = fieldValue.AdditionalDescription;
            this.itemTypeName = fieldValue.TypeNameTitle;

            this.syncDependenciesCountSubscription = this.targetSiteId$.pipe(startWith(this.targetSiteId)).subscribe(changedTargetSiteId => {
                this.targetSiteId = changedTargetSiteId;

                if (this.settings.dataItem) {
                    this.getDependantItemsCount(changedTargetSiteId);
                }
            });

            this.registerSubscription(this.syncDependenciesCountSubscription);
        }
    }

    onDialogOpen() {
        const count = new BehaviorSubject<number>(this.dependenciesTotalCount);

        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                contentLook: "medium",
                actionTitle: "Related items that will be synced",
                action: `Default.GetSyncDependencies(targetSiteId='${this.targetSiteId}')`,
                dataItem: this.settings.dataItem,
                count,
                treeConfig: {
                    description: true,
                    noSelection: true
                },
                template: null,
                openItemEdit: false
            }
        };

        const dialogData = new DialogData(componentData, (context: ClosingContext) => { }, [], null, "-bottom");

        this.modalService.setMapping(dialogData, "syncDependencies");
        this.modalService.open(this.route, "syncDependencies");
    }

    getDependantItemsCount(targetServer = stringConstants.EMPTY_STRING) {
        this.isLoading = true;
        const dependenciesCouuntSubscription = this.itemService.executeBoundFunction<SyncDependencies>(this.settings.dataItem, `Default.GetSyncDependencies(targetSiteId='${targetServer}')`)
            .pipe(
                toLoadingState(),
                delayEmission(700))
            .subscribe((state) => {
                if (state) {
                    if (state.content) {
                        this.dependenciesTotalCount = state.content.value.length;
                        this.dependenciesCountText = this.computeDependenciesCountText(this.dependenciesTotalCount);
                        this.isLoading = false;
                    }
                }
            });

        this.registerSubscription(dependenciesCouuntSubscription);
    }

    onTargetServerChange(changedTargetServerId) {
        if (changedTargetServerId) {
            this.targetSiteId$.next(changedTargetServerId);
        }
    }

    private computeDependenciesCountText(dependenciesCount: number): string {
        if (dependenciesCount === 1) {
            return `${dependenciesCount} updated item`;
        } else if (dependenciesCount > 1) {
            return `${dependenciesCount} updated items`;
        }

        return stringConstants.EMPTY_STRING;
    }

    private tryParseJSON(str): any {
        let result = false;
        try {
            result = JSON.parse(str);
        } catch (e) {
            return false;
        }

        return result;
    }
}

export interface SyncDependencies {
    value: Array<SyncDependency>;
}

export interface SyncDependency {
    Id: string;
    ContentType: string;
    Title: string;
    Provider: string;
}

export class SiteSyncSettings extends SettingsBase {
    public dataItem: any;
    public allowHtml: boolean;

    public init(metadata: any): void {
        super.init(metadata);
        this.dataItem = metadata.dataItem;
        this.allowHtml = true;
    }
}

export const SITE_SYNC_FIELDREGISTRATION: FieldRegistration = {
    writeComponent: SiteSyncItemInfoComponent,
    readComponent: SiteSyncItemInfoComponent,
    settingsType: SiteSyncSettings
};
