import { RelativeDatePipe } from "./../../src/app/modules/shared/pipes/relative-date.pipe";
import { LowerFirstLetterPipe } from "../../src/app/modules/shared/pipes/lower-first-letter.pipe";
import { ActivatedRouteSnapshot } from "@angular/router";
import { DateService } from "../../src/app/modules/shared/services/date.service";

export const SCHEDULED = "Scheduled";
export const AWAITING_APPROVAL = "AwaitingApproval";
export const AWAITING_PUBLISHING = "AwaitingPublishing";
export const PUBLISHED = "Published";
export const UNPUBLISHED = "Unpublished";
export const DRAFT = "Draft";
export const REJECTED = "Rejected";
export const REJECTED_FOR_PUBLISHING = "RejectedForPublishing";
export const NEWER_THAN_PUBLISHED = "newer than published";
export const FOR_TRANSLATION_STATUS_NAME = "For translation";
export const DELETED = "Deleted";

export abstract class StatusResolverBase {
    private dateService = new DateService();
    protected datePipe = new RelativeDatePipe(this.dateService);
    protected lowerFirstLetterPipe = new LowerFirstLetterPipe();
    // TODO: localize strings in this class

    abstract getLabel(item: any, setName?: string, routeSnapshot?: ActivatedRouteSnapshot): StatusLabel;

    abstract canProcess(setName: string): boolean;
}

export interface StatusLabel {
    StatusName: string,
    Label: string,
    HideIcon?: boolean
}
