import { AfterViewInit, Component, OnInit, TemplateRef, ViewChild } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { of } from "rxjs";
import { delay } from "rxjs/operators";
import { createValueAccessor } from "../../../../../../../fields";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { ChipsConfig } from "../../../../../../../fields/common/chips/chips.component";
import { StatusType } from "../../../../../../../fields/field-status";
import { SelectorComponent, SELECTOR_MAPPING_KEY, ServiceContract, ServiceInfo } from "../../../../../../../fields/selector/selector.component";
import { FieldBase, EntityData, DataItem, FieldRegistration } from "../../../../../api";
import { pluralize } from "../../../../../utils";
import { BLUR_EFFECT_TIMEOUT, RESOLVE_NAMES, ROUTE_PARAMS } from "../../../../content/constants";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { SelectorConstants } from "../../../../html/selector-constants";
import { ValidationError } from "../../../../shared/services/errors/validation-error";
import { Button, CancelButton, ConfirmButton, DialogData, ModalWindowService } from "../../../../shared/services/modal-window.service";
import { BasicEditorViewComponent } from "../../../basic-editor.component";
import { SectionData, WidgetMetadata } from "../../../interfaces/widget-editor";
import { PropertyValueParserService } from "../../../services/property-value-parser.service";
import { ParameterizedChoiceSelectorSettings } from "./parameterized-choice-selector.settings";

export interface ParameterizedValue {
    Name: string;
    Value: string;
    Parameters: { [key: string]: string };
}

const CSS_CLASS = "sf-parameterized-choice-selector";

@Component({
    selector: "sf-parameterized-choice-selector",
    templateUrl: "./parameterized-choice-selector.component.html",
    styleUrls: ["./parameterized-choice-selector.component.scss"],
    providers: [createValueAccessor(ParameterizedChoiceSelectorComponent)]
})
export class ParameterizedChoiceSelectorComponent extends FieldBase<ParameterizedChoiceSelectorSettings> implements OnInit, AfterViewInit {
    @ViewChild("defaultTemplate", {}) defaultTemplate: TemplateRef<HTMLElement>;
    @ViewChild("chipsTemplate", {}) chipsTemplate: TemplateRef<HTMLElement>;

    editorComponentDataList: ComponentData[];
    choiceSettings: ChoiceSettings;
    selectedChoice: any;
    selectedChoices: any[] = [];
    choiceChipsConfig: ChipsConfig;
    template: TemplateRef<HTMLElement>;
    displayField: string = "Name";
    recentChoices: any[];
    loaderHeight: number = 3;
    classList: string;
    nestedFieldClassList: string = "-sf-block -sf-mb-xs";

    private editorComponent: BasicEditorViewComponent;
    private entityData: EntityData;
    private parameterValues: any;
    private parametersMetadata: { [key: string]: Array<SectionData> };
    private choices: any[];
    private serviceAware: ServiceContract;
    private filterItems: any[];

    constructor(
        private dynamicItemService: DynamicItemService,
        private route: ActivatedRoute,
        private propertyValueParserService: PropertyValueParserService,
        private modalService: ModalWindowService) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        this.entityData = (this.route.parent.snapshot.data[RESOLVE_NAMES.entityData] || this.route.parent.snapshot.data[ROUTE_PARAMS.TYPE_NAME_SEGMENT]) ?? this.settings.entityData;
        if (this.settings.choices) {
            this.initChoices(this.settings.choices)
        } else {
            this.loadOptions();
        }

        this.classList = this.generateCssClass();
    }

    ngAfterViewInit(): void {
        this.template = this.settings.template === "chips" ? this.chipsTemplate : this.defaultTemplate;
    }

    reloadComponent(choices: any[] = null): void {
        this.classList = this.generateCssClass();

        if (choices) {
            this.settings.choices = choices;
            this.initChoices(this.settings.choices);
        }
    }

    writeValue(value: ParameterizedValue | string) {
        if (this.settings.valueType === "string") {
            this.selectedChoice = value;
        } else {
            const parameterizedValue: ParameterizedValue = value as ParameterizedValue;
            if (parameterizedValue) {
                this.selectedChoice = parameterizedValue.Value;
                this.parameterValues = parameterizedValue.Parameters;
            } else {
                this.selectedChoice = null;
                this.parameterValues = {};
            }
        }

        this.setSelectedChoices();
        super.writeValue(value);
    }

    validate() {
        if (this.editorComponent) {
            this.editorComponent.validate().subscribe(r => {
                if (r.isValid) {
                    this.emitStatus({ type: StatusType.Done });
                } else {
                    this.emitStatus({ type: StatusType.Error });
                }
            });
        } else {
            this.emitStatus({ type: StatusType.Done });
        }

        return true;
    }

    processErrors(errors: any): Array<string> {
        if (this.settings.template && this.settings.template !== "default" && !this.selectedChoice) {
            return super.processErrors(errors);
        }

        if (errors instanceof ValidationError) {
            this.editorComponent.showValidationErrors(errors);
        }

        // Return null in order to show errors only for child fields
        return null;
    }

    onSelectionChange(choice: string) {
        this.initializeParameters(choice);
        this.updateValue();
    }

    onSelectChip(chipItem: any) {
        if (chipItem.action && typeof chipItem.action === "function") {
            chipItem.action();
        } else if (chipItem.Value) {
            this.selectedChoice = chipItem.Value;
            this.onSelectionChange(this.selectedChoice);
        }
    }

    onRemoveChip(chipItem: any) {
        this.selectedChoice = null;
        this.updateValue();
    }

    private loadOptions() {
        this.dynamicItemService
            .executeBoundFunction(DataItem.emptyItem(this.entityData), `Default.GetChoiceOptions(fieldName='${this.settings.key}')`)
            .pipe(delay(BLUR_EFFECT_TIMEOUT))
            .subscribe((choices: any) => {
                this.initChoices(choices.value);
            });
    }

    private initChoices(choices: any[]) {
        this.choices = choices;

        const dropdownOptions: ChoiceItem[] = this.choices.map(c => <ChoiceItem>{
            Name: c.Name,
            Value: c.Value
        });

        this.choiceSettings = ChoiceDropdownComponent.createFieldSettings(dropdownOptions);

        this.parametersMetadata = {};
        this.choices.forEach(c => {
            this.parametersMetadata[c.Value] = c.ParametersMetadata;
        });

        if (this.selectedChoice) {
            this.initializeParameters(this.selectedChoice, this.parameterValues);
            this.setSelectedChoices();
        } else {
            if (!this.settings.template || this.settings.template === "default") {
                this.selectedChoice = dropdownOptions[0].Value;
                this.initializeParameters(this.selectedChoice);
            }
        }

        if (this.settings.template && this.settings.template !== "default") {
            this.choiceChipsConfig = {
                showSelectedItemAsActive: true,
                showRecentLabel: this.settings.showRecentLabel
            };

            this.serviceAware = new ServiceContract(
                (info: ServiceInfo) => {
                    let result = this.choices;
                    if (info.searchText) {
                        result = result.filter(choice => choice.Name.toLowerCase().startsWith(info.searchText.toLowerCase()));
                    }

                    const filter = info.filterValue;
                    if (filter && filter.Value) {
                        result = result.filter(choice => choice[this.settings.selectorFilterProperty] === filter.Value);
                    }

                    return of(result);
                }
            );

            this.initializeRecentChoices();
            this.initializeFilterItems();
        }
    }

    private initializeParameters(choice: string, setDefaultValues: boolean = false) {
        const currentParametersMetadata = this.parametersMetadata[choice];

        if (currentParametersMetadata && currentParametersMetadata.length) {
            const editorMetadata: WidgetMetadata = {
                propertyValues: setDefaultValues ? this.parameterValues : {},
                propertyMetadata: currentParametersMetadata,
                propertyMetadataFlat: [],
                propertyLocalizationMode: null,
                name: null,
                caption: null
            };

            if (currentParametersMetadata.length > 1) {
                this.classList += " -multiple-sections";
            }

            this.editorComponentDataList = [{
                type: BasicEditorViewComponent,
                afterComponentInit: (component: BasicEditorViewComponent) => {
                    component.initialize(editorMetadata).subscribe(() => {
                        setTimeout(() => {
                            this.updateValue();
                        }, 0);
                    });

                    this.editorComponent = component;
                },
                properties: {
                    context: {
                        isQuickEdit: true,
                        sectionName: this.settings.key,
                        widgetName: this.entityData?.metadata?.setName
                    },
                    fieldChange: () => {
                        setTimeout(() => {
                            // Call updateValue() in setTimeout to make sure all conditional fields visibility has been acounted for
                            // before getting the value
                            this.updateValue();
                        }, 0);
                    },
                    cssClass: "",
                    shouldHaveTopPadding: false,
                    shouldHideBottomBorder: this.settings.shouldHideBottomBorder
                },
                updatePropertiesOnChange: true
            }];
        } else {
            this.editorComponentDataList = [];
            this.editorComponent = null;
        }
    }

    private updateValue() {
        const parameters = {};
        if (this.editorComponent) {
            const properties = this.settings.onlyDirty ? this.editorComponent.getModifiedProperties() : this.editorComponent.getAllProperties();
            properties.forEach(prop => {
                const anyValue = prop.Value;
                const metaProp = this.getMetadata(prop.Name);
                if (metaProp) {
                    if ((typeof anyValue !== "number") && ((anyValue && typeof anyValue !== "string") || typeof prop.Value === "boolean" || (metaProp && metaProp.Type === "multipleChoices"))) {
                        prop.Value = this.propertyValueParserService.parseFieldValueToProperty(anyValue, metaProp.Type, metaProp);
                    }

                    parameters[prop.Name] = prop.Value;
                }
            });
        }

        if (this.settings.valueType === "string") {
            this.writeValue(this.selectedChoice);
        } else {
            this.writeValue({
                Name: this.getChoice()?.Name,
                Value: this.selectedChoice,
                Parameters: parameters
            });
        }
    }

    private getMetadata(propName: string) {
        const metaProp = this.parametersMetadata[this.selectedChoice].flatMap(p => p.Properties).filter(p => p.Name === propName)[0];
        return metaProp;
    }

    private setSelectedChoices() {
        const choice = this.getChoice();
        this.selectedChoices = choice ? [choice] : [];
    }

    private initializeRecentChoices() {
        this.recentChoices = this.choices.slice();

        const recentProperty = this.settings.recentProperty;
        if (recentProperty) {
            this.recentChoices.sort((choice1, choice2) => { return choice2[recentProperty] - choice1[recentProperty]; });
        }

        const recentCount = this.settings.recentCount;
        if (recentCount && this.recentChoices.length > recentCount) {
            this.recentChoices = this.recentChoices.slice(0, recentCount);
        }

        if (this.recentChoices.length < this.choices.length) {
            this.choiceChipsConfig.actions = [{
                action: this.showAll.bind(this),
                label: `Show all ${pluralize(this.settings.keyLabel || this.settings.key).toLowerCase()}`
            }];
        } else {
            this.choiceChipsConfig.actions = [];
        }
    }

    private initializeFilterItems() {
        // TODO: make call to get module names
        const selectorFilterProperty = this.settings.selectorFilterProperty;
        if (selectorFilterProperty) {
            this.filterItems = [{ Name: `All ${pluralize(selectorFilterProperty.toLocaleLowerCase())}`, Value: null }];

            const filtersArray = this.choices.map(c => c[selectorFilterProperty]);
            const filtersArrayDistinct = filtersArray.filter((n, i) => filtersArray.indexOf(n) === i);

            this.filterItems.push(...filtersArrayDistinct.map(filter => <ChoiceItem>{ Name: filter, Value: filter }));
        }
    }

    private showAll(): void {
        let selectorFilterConfig = null;
        if (this.filterItems && this.filterItems.length) {
            selectorFilterConfig = {
                filterChipsConfig: {
                    showSelectedItemAsActive: true
                },
                selectedFilterItems: [this.filterItems[0]],
                filterItems: this.filterItems,
                filterLabel: this.settings.selectorFilterProperty,
                defaultField: this.displayField
            }
        }

        const componentData: ComponentData = {
            type: SelectorComponent,
            properties: {
                value: this.choices,
                value$: of(this.choices),
                totalItemsCount: this.choices.length,
                selected: this.selectedChoices.map(x => x),
                treeConfig: {
                    multiSelection: false,
                    isHierarchical: false
                },
                serviceAware: this.serviceAware,
                typeNames: {
                    singular: (this.settings.keyLabel || this.settings.key).toLowerCase(),
                    plural: pluralize(this.settings.keyLabel || this.settings.key).toLowerCase()
                },
                defaultField: this.displayField,
                isParentSelection: false,
                loading: false,
                selectorFilterConfig
            }
        };

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton(SelectorConstants.CANCEL)
        ];
        const dialogData = new DialogData(componentData, (context) => this.onDone(context), buttons, null, "-bottom");

        this.modalService.setMapping(dialogData, SELECTOR_MAPPING_KEY);
        this.modalService.open(this.route, SELECTOR_MAPPING_KEY);
    }

    private onDone(context: any) {
        if (!context.data || !context.data.data) {
            return;
        }

        if (context.component.selected && context.component.selected.length) {
            this.onSelectChip(context.component.selected[0]);
        }
    }

    private getChoice() {
        if (this.selectedChoice && this.choices) {
            return this.choices.find(ch => ch.Value === this.selectedChoice);
        }

        return null;
    }

    private generateCssClass(): string {
        let cssClass = CSS_CLASS;
        if (this.settings.look) {
            cssClass += " -" + this.settings.look.split(" ").join(" -");
        }

        if (this.settings.selectionEnabled === false && this.settings.selectionDisabledMessageLook) {
            cssClass += " -" + this.settings.selectionDisabledMessageLook.split(" ").join(" -");
        }

        return cssClass;
    }
}

export const PARAMETERIZED_CHOICE_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: ParameterizedChoiceSelectorComponent,
    settingsType: ParameterizedChoiceSelectorSettings
};
