import { Component, ViewChild, OnInit, Inject } from "@angular/core";
import { FieldBase } from "../../../../../../fields/index";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { CUSTOM_THUMBNAIL_KEY, ImageHelper } from "../../../html/tools/insert-image/image-helper";
import { SfInputComponent } from "@progress/sitefinity-component-framework";
import { createValueAccessor } from "../../../../../../fields/field-base";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ChoiceYesNoComponent } from "../../../../../../fields/choice/choice-yesno.component";

@Component({
    selector: "sf-edit-image-thumbnail",
    templateUrl: "./edit-image-thumbnail.component.html",
    providers: [createValueAccessor(EditImageThumbnailComponent), ImageHelper]
})
export class EditImageThumbnailComponent extends FieldBase<any> implements OnInit {
    showCustomSizeFields: boolean = false;
    widthPropertyName = "width";
    heightPropertyName = "height";
    constrainProportionsPropertyName = "constrainProportions";

    @ViewChild(ChoiceDropdownComponent, { static: true }) private choiceComponent: ChoiceDropdownComponent;
    @ViewChild(ChoiceYesNoComponent, { static: true }) private constrainProportionsCheckbox: ChoiceYesNoComponent;
    @ViewChild("widthField", { static: true }) private widthField: SfInputComponent;
    @ViewChild("heightField", { static: true }) private heightField: SfInputComponent;

    constructor(@Inject(WINDOW_TOKEN) private windowProvider: Window, private imageHelper: ImageHelper) {
        super();
    }

    ngOnInit() {
        if (!this.value) {
            super.writeValue({});
        }

        if (this.settings.key) {
            this.settings.dropDownSettings.key = this.settings.key;
        }

        this.widthPropertyName = this.settings.widthPropertyName || this.widthPropertyName;
        this.heightPropertyName = this.settings.heightPropertyName || this.heightPropertyName;
        this.constrainProportionsPropertyName = this.settings.constrainProportionsPropertyName || this.constrainProportionsPropertyName;

        if (this.value.thumbnailValue === CUSTOM_THUMBNAIL_KEY || this.settings.customSizeOnly) {
            if (typeof this.value[this.constrainProportionsPropertyName] === "undefined") {
                this.value[this.constrainProportionsPropertyName] = true;
            }
            this.showCustomSizeFields = true;
            this.setWidthHeight(this.value[this.widthPropertyName], this.value[this.heightPropertyName], this.value[this.constrainProportionsPropertyName], false);
        }
    }

    onSelectionChange(selectedValue: string) {
        const value = this.getValue();
        value.thumbnailValue = selectedValue;
        this.showCustomSizeFields = selectedValue === CUSTOM_THUMBNAIL_KEY;
        if (this.showCustomSizeFields) {
            this.setWidthHeight(this.value[this.widthPropertyName], this.value[this.heightPropertyName], this.value[this.constrainProportionsPropertyName]);
        }

        this.writeValue(value);
        this.onBlur();
    }

    onConstrainProportionsChange(selectedValue: boolean) {
        const value = this.getValue();
        value[this.constrainProportionsPropertyName] = selectedValue;

        this.scaleDimensions(value, this.widthPropertyName, value[this.widthPropertyName], this.heightPropertyName);
        this.writeValue(value);
    }

    onInput(event: any, property: string, otherDimensionProperty: string) {
        this.value["OriginalWidth"] = this.value["OriginalWidth"] || this.value[this.widthPropertyName];
        this.value["OriginalHeight"] = this.value["OriginalHeight"] || this.value[this.heightPropertyName];

        const value = this.getValue();
        value[property] = event.target.value;

        this.scaleDimensions(value, property, event.target.value, otherDimensionProperty);
        this.writeValue(value);
    }

    writeValue(value: any) {
        if (value) {
            super.writeValue(Object.assign({}, value));
            if (this.choiceComponent) {
                this.choiceComponent.writeValue(this.value.thumbnailValue);
            }
        }
    }

    private scaleDimensions(value: any, property: string, propertyValue: number, otherDimensionProperty: string) {
        if (this.settings.customSizeOnly && typeof this.value[this.constrainProportionsPropertyName] === "undefined") {
            this.value[this.constrainProportionsPropertyName] = true;
        }

        if (this.value[this.constrainProportionsPropertyName]) {
            const firstDimensionNaturalValue = this.settings[`${property}Settings`] ? this.settings[`${property}Settings`].naturalValue : (value[`Original${property}`] || value[property]);
            const otherDimensionNaturalValue = this.settings[`${otherDimensionProperty}Settings`] ? this.settings[`${otherDimensionProperty}Settings`].naturalValue : (value[`Original${otherDimensionProperty}`] || value[otherDimensionProperty]);
            value[otherDimensionProperty] = this.imageHelper.determineScaledValue(
                propertyValue,
                firstDimensionNaturalValue,
                otherDimensionNaturalValue);
            this[`${otherDimensionProperty.toLocaleLowerCase()}Field`].writeValue(value[otherDimensionProperty]);
        }
    }

    private setWidthHeight(width, height, constrainProportions: boolean, focusFirstField = true) {
        this.constrainProportionsCheckbox.writeValue(constrainProportions);
        if (constrainProportions) {
            const value = this.getValue();

            if (width) {
                this.widthField.writeValue(width);
                this.scaleDimensions(value, this.widthPropertyName, value[this.widthPropertyName], this.heightPropertyName);
            }

            if (height) {
                this.heightField.writeValue(height);
                this.scaleDimensions(value, this.heightPropertyName, value[this.heightPropertyName], this.widthPropertyName);
            }
        } else {
            this.widthField.writeValue(width);
            this.heightField.writeValue(height);
        }

        if (focusFirstField) {
            // the settimeout is needed because otherwise the field is still hidden and cannot be focused
            this.windowProvider.setTimeout(() => {
                this.widthField.focus();
            }, 0);
        }
    }
}
