import { Injectable } from "@angular/core";
import { BehaviorSubject } from "rxjs";

@Injectable()
export class FeatureToggleService {
    protected staticConfig = {
        sidebar: false
    };
    private featureConfigField: BehaviorSubject<Array<Feature>>;

    // possibly pass userdata as well
    public isEnabled(featureName: string) {
        const features = this.featureConfig.getValue();
        const feature: Feature = features.find(feature => feature.name === featureName);
        if (feature) {
            return feature.enabled;
        }

        return true;
    }

    public setFeatureState(name: string, value: boolean) {
        const features = this.featureConfig.getValue();

        features
            .filter(feature => feature.name === name)
            .map(feature => feature.enabled = value);

        this.featureConfigField.next(features);
    }

    public get featureConfig(): BehaviorSubject<Array<Feature>> {
        if (this.featureConfigField == null) {
            const features = this.initConfig(this.staticConfig);
            this.featureConfigField = new BehaviorSubject<Array<Feature>>(features);
        }

        return this.featureConfigField;
    }

    private initConfig(config: any): Array<Feature> {
        const features: Array<Feature> = [];
        Object.keys(config).forEach(prop => {
            features.push({
                name: prop,
                enabled: config[prop]
            });
        });

        return features;
    }
}

export interface Feature {
    name: string;
    enabled: boolean;
}
