import { Injectable } from "@angular/core";
import { CanActivate, Router } from "@angular/router";

import { ROUTE_PATHS } from "../../constants/route-paths";
import { environmentTypes } from "../../environment";
import { EnvironmentService } from "../../modules/shared/services/environment.service";

@Injectable()
export class IntegratedEmptyComponentGuard implements CanActivate {
    constructor(private router: Router, private envService: EnvironmentService) { }

    canActivate() {
        if (this.envService.getEnvironment() === environmentTypes.integration) {
            return true;
        } else {
            this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
            return false;
        }
    }
}
