import { Component, OnInit, TemplateRef, ViewChild } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { createValueAccessor } from "../../../../../../../fields";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { FieldBase, FieldRegistration, SettingsBase } from "../../../../../api";
import { stringConstants } from "../../../../../common-constants";
import { QUERY_PARAMS, RESOLVE_NAMES } from "../../../../content/constants";
import { LocatableDynamicItemService } from "../../../../content/dynamic-modules/services/locatable-dynamic-item.service";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { SiteData } from "../../../../shared/services/metadata/site-data.store";
import { TaxonomyService, TaxonomySettings } from "../../../../taxonomy";
import { Taxonomy } from "../../../../taxonomy/intefaces";
import { EntityData } from "../../../../../modules/content/dynamic-modules/interfaces";

@Component({
    selector: "sf-taxon-selector",
    templateUrl: "./taxon-selector.component.html",
    providers: [createValueAccessor(TaxonSelectorComponent)]
})
export class TaxonSelectorComponent extends FieldBase<SettingsBase, TaxonSelectorValue> implements OnInit {
    @ViewChild("selectedTaxon", { read: TemplateRef }) selectedTaxonTemplate: TemplateRef<any>;
    @ViewChild("byContentType", { read: TemplateRef }) byContentTypeTemplate: TemplateRef<any>;

    private taxonomies: Taxonomy[] = [];
    private siteData: SiteData;
    private isSelectedTaxonomyFlat: boolean;
    private currentTaxonomy: Taxonomy;

    selectedTaxonomyId: string;
    taxonomySettings: ChoiceSettings;
    locatableItemSettings: ChoiceSettings;
    radioSettings: ChoiceSettings;
    taxaComponentSettings: TaxonomySettings;
    taxaComponentEntity: EntityData;
    selectedTaxaIds: Array<string>;

    constructor(
        private taxonomyService: TaxonomyService,
        private metaDataStore: MetadataStore,
        private locatableDynamicItemService: LocatableDynamicItemService,
        private route: ActivatedRoute
    ) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        this.siteData = this.route.parent.snapshot.data[RESOLVE_NAMES.siteDataStore];

        this.taxonomyService.getTaxonomies([]).then(taxonomies => {
            this.taxonomies = taxonomies;
            this.selectedTaxonomyId = this.getValue().selectedTaxonomyId;
            this.selectedTaxaIds = this.getValue().selectedTaxaIds;

            this.initializeTaxonomySettings(this.selectedTaxonomyId);

            if (this.selectedTaxonomyId) {
                this.currentTaxonomy = this.taxonomies.find(x => x.Id === this.selectedTaxonomyId);

                if (this.currentTaxonomy) {
                    this.isSelectedTaxonomyFlat = this.currentTaxonomy.Type.toLocaleLowerCase() === "flat";
                    this.initializeTaxaComponentSettings(this.getValue().selectionMode === TaxonSelectionMode.Selected, this.selectedTaxonomyId, this.currentTaxonomy);
                }
            }

            this.initializeRadioSettings(this.getValue().selectionMode);

            this.initializeLocatableItemSetting(this.getValue().byContentType);
        });
    }

    onTaxonomyDropdownSelectionChanged($event) {
        this.selectedTaxonomyId = $event;

        if ($event == null) {
            this.writeValue(null);
            return;
        }

        this.currentTaxonomy = this.taxonomies.find(x => x.Id === this.selectedTaxonomyId);
        this.isSelectedTaxonomyFlat = this.currentTaxonomy.Type.toLocaleLowerCase() === "flat";
        this.selectedTaxaIds = [];

        this.initializeRadioSettings(TaxonSelectionMode.All);

        const value = this.getValue();
        value.selectedTaxonomyId = this.selectedTaxonomyId;
        value.selectedTaxonomyUrl = this.currentTaxonomy.TaxaUrl;
        value.selectedTaxonomyName = this.currentTaxonomy.Name;
        value.selectedTaxonomyTitle = this.currentTaxonomy.Title;
        value.selectionMode = TaxonSelectionMode.All;
        value.byContentType = stringConstants.EMPTY_STRING;
        value.selectedTaxaIds = this.selectedTaxaIds;
        this.writeValue(value);
    }

    onRadioSelectionChange($event) {
        this.selectedTaxaIds = [];

        if ($event === TaxonSelectionMode.Selected) {
            this.initializeTaxaComponentSettings(true, this.selectedTaxonomyId, this.currentTaxonomy);
        } else if ($event === TaxonSelectionMode.UnderParent) {
            this.initializeTaxaComponentSettings(false, this.selectedTaxonomyId, this.currentTaxonomy);
        }

        const value = this.getValue();
        value.selectedTaxaIds = this.selectedTaxaIds;
        value.selectionMode = TaxonSelectionMode[$event];
        value.byContentType = stringConstants.EMPTY_STRING;
        
        if ($event === TaxonSelectionMode.ByContentType) {
            value.byContentType = this.locatableItemSettings.defaultValue;
        }

        this.writeValue(value);
    }

    onTaxaComponentSelectionChange() {
        // this.selectedTaxaIds: is updated by the binding in the template
        const value = this.getValue();
        value.byContentType = stringConstants.EMPTY_STRING;
        value.selectedTaxaIds = this.selectedTaxaIds;
        this.writeValue(value);
    }

    onLocatableItemDropdownSelectionChanged($event) {
        this.selectedTaxaIds = [];

        const value = this.getValue();
        value.selectedTaxaIds = this.selectedTaxaIds;
        value.byContentType = $event;
        this.writeValue(value);
    }

    getValue(): TaxonSelectorValue {
        return super.getValue() || new TaxonSelectorValue();
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }

    private initializeTaxonomySettings(selectedTaxonomyId: string) {
        const taxonomiesAsChoices = this.taxonomies.map(t => <ChoiceItem>{ Name: t.Title, Value: t.Id })
        const notSelectedOption = { Name: "Select classification", Value: null };
        const taxonomyChoices = [notSelectedOption].concat(taxonomiesAsChoices);
        this.taxonomySettings = ChoiceDropdownComponent.createFieldSettings(taxonomyChoices, selectedTaxonomyId, "taxonomies");
    }

    private initializeRadioSettings(currentSelectionMode: TaxonSelectionMode) {
        this.radioSettings = new ChoiceSettings("radioSelector", false);
        this.radioSettings.choices = [];
        this.radioSettings.defaultValue = currentSelectionMode;

        if (this.currentTaxonomy) {
            const currentTaxonomyTitle = this.currentTaxonomy.Title.toLocaleLowerCase();
            const currentTaxonName = this.currentTaxonomy.TaxonName.toLocaleLowerCase();

            this.radioSettings.choices.push({ Name: `All ${currentTaxonomyTitle}`, Value: TaxonSelectionMode.All });
            if (!this.isSelectedTaxonomyFlat) {
                this.radioSettings.choices.push({ Name: `Top level ${currentTaxonomyTitle} only`, Value: TaxonSelectionMode.TopLevel, });
                this.radioSettings.choices.push({ Name: `All ${currentTaxonomyTitle} under particular ${currentTaxonName}...`, Value: TaxonSelectionMode.UnderParent, ExpandedTemplate: this.selectedTaxonTemplate });
            }
            this.radioSettings.choices.push({ Name: `Selected ${currentTaxonomyTitle}`, Value: TaxonSelectionMode.Selected, ExpandedTemplate: this.selectedTaxonTemplate });
            this.radioSettings.choices.push({ Name: `Only ${currentTaxonomyTitle} used by content type...`, Value: TaxonSelectionMode.ByContentType, ExpandedTemplate: this.byContentTypeTemplate });
        }
    }

    private initializeTaxaComponentSettings(allowMultipleSelection: boolean, selectedTaxonomyId: string, currentTaxonomy: Taxonomy) {
        const entity = this.metaDataStore.getEntity(currentTaxonomy.TaxaUrl);

        this.taxaComponentEntity = {
            metadata: entity,
            provider: entity.selectedProvider,
            culture: this.route.parent.snapshot.queryParams[QUERY_PARAMS.CULTURE] || this.siteData.DefaultContentCulture
        };

        this.taxaComponentSettings = new TaxonomySettings("Classifications", false);
        this.taxaComponentSettings.init(this.taxaComponentEntity);
        this.taxaComponentSettings.id = selectedTaxonomyId;
        this.taxaComponentSettings.name = currentTaxonomy.Name;
        this.taxaComponentSettings.type = currentTaxonomy.TaxaUrl;
        this.taxaComponentSettings.allowMultiple = allowMultipleSelection;
        this.taxaComponentSettings.skipInputSelection = false;
        this.taxaComponentSettings.defaultValue = this.selectedTaxaIds;
    }

    private initializeLocatableItemSetting(currentContentType: string) {
        const subscription = this.locatableDynamicItemService.getLocatableEntitySetNames(this.siteData.Id).subscribe(sets => {
            if (!sets.isLoading) {
                const locatableSetsAsChoices: ChoiceItem[] = sets.content.value
                    .filter(setName => this.metaDataStore.getValue().entities[setName])
                    .map(setName => <ChoiceItem>{
                        Name: this.metaDataStore.getValue().entities[setName].displayName,
                        Value: this.metaDataStore.getValue().entities[setName].typeFullName
                    });

                const settings = ChoiceDropdownComponent.createFieldSettings(locatableSetsAsChoices, currentContentType || locatableSetsAsChoices[0]?.Value, "locatableItems");
                settings.look = "-sf-ml-xs -sf-mt-4xs";
                this.locatableItemSettings = settings;
            }
        });

        this.registerSubscription(subscription);
    }
}

export class TaxonSelectorValue {
    selectedTaxonomyId: string;
    selectedTaxonomyUrl: string;
    selectedTaxonomyName: string;
    selectedTaxonomyTitle: string;
    selectionMode: TaxonSelectionMode;
    selectedTaxaIds: string[];
    byContentType: string;
}

export const TAXON_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: TaxonSelectorComponent,
    readComponent: TaxonSelectorComponent,
    settingsType: SettingsBase
};

export enum TaxonSelectionMode {
    All = "All",
    TopLevel = "TopLevel",
    UnderParent = "UnderParent",
    Selected = "Selected",
    ByContentType = "ByContentType"
}
