import { Injectable, Inject } from "@angular/core";
import { ActivatedRouteSnapshot } from "@angular/router";
import { DynamicItemStrategyBase } from "../../components/strategies/dynamic-item.strategy";
import { MetadataContainer } from "../../../../shared/services/metadata/meta-data.store";
import { EntityData } from "../../interfaces";

export abstract class EntityDataResolver {
    abstract resolve(route: ActivatedRouteSnapshot, container: MetadataContainer, culture: string, provider: string): EntityData;

    abstract canResolve(entitySet: string): boolean;
}

@Injectable({ providedIn: "root" })
export class CompositeEntityDataResolver {
    constructor(@Inject(EntityDataResolver) private resolvers: EntityDataResolver[]) { }

    resolveEntityData(route: ActivatedRouteSnapshot, container: MetadataContainer, culture: string, provider: string): EntityData {
        const entitySet = this.getEntitySet(route);
        const resolver = this.resolvers.find(r => r.canResolve(entitySet));

        if (resolver) {
            return resolver.resolve(route, container, culture, provider);
        }

        const metadata = container.entities[entitySet];
        if (!metadata) {
            return null;
        }

        return {
            metadata: metadata,
            provider,
            culture
        };
    }

    protected getEntitySet(route: ActivatedRouteSnapshot) {
        return DynamicItemStrategyBase.getSet(route.parent);
    }
}
