import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from "@angular/router";
import { Observable, of } from "rxjs";
import { first } from "rxjs/operators";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { LoadItemsResponse } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ENTITY_SET } from "./metadata/meta-data-constants";
import { MetadataStore } from "./metadata/meta-data.store";
import { SiteDataStore } from "./metadata/site-data.store";

@Injectable()
export class SitesResolver implements Resolve<any>  {
    constructor(private siteDataStore: SiteDataStore, private metadataStore: MetadataStore) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<LoadItemsResponse> {
        const sitesEntity = this.metadataStore.getEntity(ENTITY_SET.SITES);

        if (!sitesEntity) {
            return of<LoadItemsResponse>({
                entityData: null,
                totalCount: 0,
                dataItems: []
            });
        }

        return this.siteDataStore.getAllSites(<EntityData>{
            metadata: sitesEntity
        }).pipe(first());
    }
}
