import { DataItem } from "../../../content/dynamic-modules/interfaces";

export class ContentItemInfo  {
    public Title: string;
    public Id: string;
    public ContentType: string;
    public Provider: string;
    public CurrentCulture: string;
    public HasChildren: boolean;

    public SfSetName: string;
    public AvailableLanguages: string[];

    public DefaultFieldName: string;

    constructor(dataItem: DataItem) {
        this.DefaultFieldName = dataItem.metadata.defaultFieldName;
        this.Title = dataItem.data[this.DefaultFieldName];
        this.Id = dataItem.data.Id;
        this.Provider = dataItem.provider;
        this.HasChildren = dataItem.childTypes.length > 0;
        this.CurrentCulture = dataItem.culture;

        this.ContentType = ContentItemInfo.getContentTypeFromFullTypeName(dataItem.metadata.typeFullName);

        this.SfSetName = dataItem.metadata.setName;
        this.AvailableLanguages = dataItem.data.AvailableLanguages || [];
    }

    static getContentTypeFromFullTypeName(contentType: string) {
        const indexAfterLastDot = contentType.lastIndexOf(".") + 1;

        return contentType.substring(indexAfterLastDot);
    }
}
