import { Component, OnInit, Inject, Optional } from "@angular/core";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { ServiceContract, ServiceInfo } from "../../../../../fields/selector/selector.component";
import { TreeConfig } from "../../../../../fields";
import { TypeNames } from "../../../../../fields/types/types";
import { ActivatedRoute } from "@angular/router";
import { stringConstants } from "../../../common-constants";
import { HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { HierarchicalDynamicItemService } from "../../content/dynamic-modules/services/hierarchical-dynamic-item-service";
import { CompositeOperationsProvider } from "../../content/dynamic-modules/services/operations/operations-provider";
import { TaxonomySettings } from "..";
import { BulkItemSelectionInfo } from "../../content/dynamic-modules/components/bulk-operations/bulk-operations.component";
import { Observable, of } from "rxjs";
import { map } from "rxjs/operators";

@Component({
    templateUrl: "./merge-taxon.component.html"
})

export class MergeTaxonComponent implements OnInit {
    taxons: TreeItem[] = [];
    dataItems: DataItem[];
    treeConfig: TreeConfig;
    totalCount: number = 0;
    selected: any[] = [];
    isLoading: boolean;
    serviceAware: ServiceContract;
    taxaNames: TypeNames = { plural: stringConstants.EMPTY_STRING, singular: stringConstants.EMPTY_STRING};
    defaultFieldName: string;
    itemTypeText: string;
    description: string;
    formattedTypeName: string;
    selectionText: string = "Merge";

    private contextParameters: any[];
    private parentId: string;
    private entityData: EntityData;
    private hierarchicalService: HierarchicalDynamicItemService;
    private defaultLoad: number = 20;
    private pagingLoad: number = 20;
    private itemSelectionInfo: BulkItemSelectionInfo;

    constructor(protected route: ActivatedRoute,
                @Optional() @Inject(HIERARCHICAL_SERVICE_TOKEN) private hierarchicalServices: Array<HierarchicalDynamicItemService>) { }

    ngOnInit() {
        if (this.hierarchicalServices) {
            this.hierarchicalServices.forEach(service => {
                if (service.isTypeSupported(this.entityData)) {
                    this.hierarchicalService = service as HierarchicalDynamicItemService;
                }
            });
        }

        if (!this.hierarchicalService && this.entityData.metadata.setName && this.entityData.metadata.singularName) {
            this.hierarchicalService = this.hierarchicalServices.find(service => service instanceof HierarchicalDynamicItemService);
            this.hierarchicalService.setName = this.entityData.metadata.setName;
            this.hierarchicalService.singularName = this.entityData.metadata.singularName;
        } else if (!this.hierarchicalService) {
           return;
        }

        const pluralName = CompositeOperationsProvider.getOperationPluralName(this.entityData.metadata, this.contextParameters).toLowerCase();
        const singularName = CompositeOperationsProvider.getOperationSingularName(this.entityData.metadata, this.contextParameters).toLowerCase();

        this.taxaNames = {
            plural: pluralName,
            singular: singularName
        };

        this.defaultFieldName = this.entityData.metadata.defaultFieldName;

        this.treeConfig =  {
            multiSelection: false,
            isHierarchical: false
        };

        this.formattedTypeName = pluralName;
        this.description = `Select ${singularName} to merge others into`;

        this.getItems();

        this.serviceAware = new ServiceContract((info: ServiceInfo) => this.loadMore(info));
    }

    private getItems(): void {
        this.isLoading = true;

        if (this.itemSelectionInfo && this.itemSelectionInfo.allItemsSelected) {
            this.hierarchicalService.getModalItems(this.entityData, this.parentId)
            .pipe(
                map(data => {
                    return {
                        dataItems: data.dataItems.filter(item => !this.itemSelectionInfo.deselectedItems.has(item.key)),
                        totalCount: data.totalCount
                    };
                }))
            .subscribe(result => {
                this.totalCount = result.totalCount;
                this.taxons = this.getTaxonCollection(result.dataItems);
                this.isLoading = false;
            });
        } else {
            this.dataItems = this.dataItems.sort((a, b) => a.title.localeCompare(b.title));
            this.totalCount = this.dataItems.length;
            this.taxons = this.getTaxonCollection(this.dataItems.slice(0, this.defaultLoad));
            this.isLoading = false;
        }
    }

    private loadMore(serviceInfo: ServiceInfo): Observable<any> {
        if (this.itemSelectionInfo && this.itemSelectionInfo.allItemsSelected) {
            const settings = new TaxonomySettings(this.parentId, true);
            settings.id = this.parentId;
            settings.type = this.entityData.metadata.setName;
            serviceInfo.parentId = this.parentId;

            return this.hierarchicalService.loadMore(serviceInfo, this.entityData, settings).pipe(
                map(data => {
                    return {
                        dataItems: this.getTaxonCollection(data.dataItems.filter(item => !this.itemSelectionInfo.deselectedItems.has(item.key))),
                        totalCount: data.totalCount
                    };
                }));
        } else {
            let filteredItems = this.dataItems;

            if (serviceInfo.searchText && serviceInfo.searchText !== stringConstants.EMPTY_STRING) {
                filteredItems = filteredItems.filter(p => p.title.toLowerCase().search(serviceInfo.searchText.toLowerCase()) !== -1);
            }

            filteredItems = filteredItems.slice(serviceInfo.skip, serviceInfo.skip + this.pagingLoad);

            return of({
                dataItems: this.getTaxonCollection(filteredItems),
                totalCount: this.dataItems.length
            });
        }
    }

    private getTaxonCollection(dataItems: DataItem[]): TreeItem[] {
        const results: TreeItem[] = [];

        dataItems.forEach(dataItem => {
            results.push(this.cloneAndAddFieldsToDataItem(dataItem));
        });

        return results;
    }

    private cloneAndAddFieldsToDataItem(dataItem: DataItem): TreeItem {
        const item = JSON.parse(JSON.stringify(dataItem.data));
        const taxon: TreeItem = {
                Id: item.Id,
                Title: item.Title,
                isTranslated: dataItem.isTranslated
        };

        return taxon;
    }
}

interface TreeItem {
    Id?: string
    Title: string;
    isTranslated?: boolean;
}
