import { Injectable, ClassProvider } from "@angular/core";
import { Observable, of } from "rxjs";
import { WIDGET_VIEW_TOKEN } from "../../providers/view-registration.provider";
import { ShareComponent } from "../views/share.component";
import { UnshareComponent } from "../views/unshare.component";
import { UseSharedComponent } from "../views/use-shared.component";
import { ContentBlockBasicComponent } from "../views/content-block-basic.component";
import { WidgetEditorViewProvider, EditorComponentContext, EditorViewComponent, WidgetEditorViewRgistrationProvider, EditorViewModel } from "../../interfaces/widget-editor-view-provider";
import { PropertyEditorWidgets, PropertyEditorViewModes } from "../../property-editor.constants";
import { NotShareableComponent } from "../views/not-shareable.component";

/**
 * The ViewRegistrationProvider class works with all of the edior view providers and combines their views into a single
 * views array.
 */
@Injectable()
export class ContentEditorViewProvider implements WidgetEditorViewProvider, WidgetEditorViewRgistrationProvider {
    /**
     * Gets the views from all of the providers.
     */
    getViews(): Observable<EditorViewModel[]> {
        const viewMappings = [];
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK, viewName: PropertyEditorViewModes.SHARE }, componentData: { type: ShareComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK, viewName: PropertyEditorViewModes.UNSHARE }, componentData: { type: UnshareComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK, viewName: PropertyEditorViewModes.USE_SHARED }, componentData: { type: UseSharedComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK, viewName: PropertyEditorViewModes.NOT_SHAREABLE }, componentData: { type: NotShareableComponent }});

        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK_MVC, viewName: PropertyEditorViewModes.SHARE }, componentData: { type: ShareComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK_MVC, viewName: PropertyEditorViewModes.UNSHARE }, componentData: { type: UnshareComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK_MVC, viewName: PropertyEditorViewModes.USE_SHARED }, componentData: { type: UseSharedComponent }});
        viewMappings.push({ key: { widgetName: PropertyEditorWidgets.CONTENT_BLOCK_MVC, viewName: PropertyEditorViewModes.NOT_SHAREABLE }, componentData: { type: NotShareableComponent }});
        return of(viewMappings);
    }

    overrideView(context: EditorComponentContext): EditorViewComponent {
        if (context.widgetName === PropertyEditorWidgets.CONTENT_BLOCK || context.widgetName === PropertyEditorWidgets.FORM_CONTENT_BLOCK || context.widgetName === PropertyEditorWidgets.CONTENT_BLOCK_MVC) {
            return {
                componentData: { type: ContentBlockBasicComponent }
            };
        }
    }
}

/**
 * Export a 'multi' class provider so that multiple instances of the same provider can coexist.
 * This allows for more than one provider to be registered within one or more bundles.
 */
export const CONTENT_BLOCK_WIDGET_VIEW_TOKEN: ClassProvider = {
    useClass: ContentEditorViewProvider,
    multi: true,
    provide: WIDGET_VIEW_TOKEN
};
