import { takeUntil } from "rxjs/operators";
import { SelectorItem } from "./selector-item";
import { Subject ,  BehaviorSubject ,  Observable } from "rxjs";
import { SelectorContext } from "./selector-context";
import { LoadingState, delayEmission } from "../../../../../../shared/rxjs-extensions/delayEmission";
import { Directive, OnDestroy } from "@angular/core";
import { Logger } from "../../../../../../shared/services/logger-source/logger";
import { BLUR_EFFECT_TIMEOUT } from "../../../../../../content/constants";
import { ChipsConfig } from "../../../../../../../../../fields/common/chips/chips.component";

@Directive()
// eslint-disable-next-line @angular-eslint/component-class-suffix
export abstract class SelectorBase<T extends SelectorItem> implements OnDestroy {
    error$ = new Subject<string>();
    context: SelectorContext;
    children: SelectorBase<SelectorItem>[] = [];
    parents: SelectorBase<SelectorItem>[] = [];
    items: T[];
    get selectedItem(): T { return this._selectedItem; }
    isReady: boolean = false;
    change$: BehaviorSubject<SelectorBase<T>> = new BehaviorSubject<SelectorBase<T>>(this);
    chipsConfig: ChipsConfig = { showRecentLabel: false};
    private _selectedItem: T;
    private subscriptionsHolder$ = new Subject<any>();
    constructor(private logger: Logger) { }

    ngOnDestroy(): void {
        this.subscriptionsHolder$.next({});
    }

    init(context: SelectorContext) {
        if (this.areAllParentsReady()) {
            this.isReady = false;
            this.resetChildren();
            this.context = context;
            this.subscriptionsHolder$.next({});
            this.onInit()
                .pipe(
                    delayEmission(BLUR_EFFECT_TIMEOUT),
                    takeUntil(this.subscriptionsHolder$)
                )
                .subscribe(initResult => {
                    if (initResult.isLoading) {
                        this.isReady = false;
                        this.resetChildren();
                    } else {
                        this.isReady = true;
                        this.initChildren();
                    }
                }, e => {
                    this.logger.error(e);
                    const error = "Error occured. Items' list cannot be generated.";
                    this.error$.next(error);
                });
        }
    }

    onSelectedItemChanged(item: T) {
        this.resetChildren();
        this.setSelectedItem(item);
        this.initChildren();
    }

    addParent(parent: SelectorBase<SelectorItem>) {
        this.parents.push(parent);
        parent.children.push(this);
    }

    addChild(item: SelectorBase<SelectorItem>) {
        this.children.push(item);
        item.parents.push(this);
    }

    resetChildren() {
        this.children.forEach(c => {
            c.isReady = false;
            c.resetChildren();
        });
    }

    protected abstract onInit(): Observable<LoadingState>;

    protected setSelectedItem(value: T) {
        this._selectedItem = value;
        this.change$.next(this);
    }

    private initChildren() {
        this.children.forEach(x => {
            x.init(this.context);
        });
    }

    private areAllParentsReady(): boolean {
        let areReady = true;
        if (this.parents.length > 0) {
            this.parents.forEach(parent => {
                if (!parent.isReady) {
                    areReady = false;
                } else if (!parent.areAllParentsReady()) {
                    areReady = false;
                }
            });
        }

        return areReady;
    }
}
