import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { AddressFieldMode, MAP_MODE_PATH } from "./address.constants";

export class AddressSettings extends SettingsBase {
    public mapMode: AddressFieldMode;

    constructor(public key: string, public readOnlyMode: boolean) {
        super(key, readOnlyMode);
        this.showForAllTranslationsLabel = false;
        this.isGroup = true;
    }

    public init(metadata: any): void {
        this.mapMode = this.parseAddressMode(metadata[MAP_MODE_PATH]);
        super.init(metadata);
    }

    private parseAddressMode(value: string): AddressFieldMode {
        let mode: AddressFieldMode;
        switch (value) {
            case "FormOnly":
                mode = AddressFieldMode.FormOnly;
            break;
            case "MapOnly":
                mode = AddressFieldMode.MapOnly;
            break;
            case "Hybrid":
                mode = AddressFieldMode.Hybrid;
            break;
        }

        return mode;
    }
}
