import { ClassProvider, Injectable } from "@angular/core";
import { DataExtenderBase, DATA_EXTENDER_TOKEN } from "../../../shared/services/data-extensions/data.extender";
import { EntityData, DataItem } from "../../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "../media.helpers";
import { LongRunningTasksService, getRunningTasksAndMap, generateRunningTaskError } from "../../../content/dynamic-modules/services/long-running-tasks.service";
import { cloneObject } from "../../../../utils";
import { BackgroundTask, TaskStatus } from "../../../content/dynamic-modules/services/background-task.types";
import { stringConstants } from "./../../../../common-constants";

@Injectable()
export class MediaDataExtender extends DataExtenderBase {
    constructor(private longRunningTasksSerivce: LongRunningTasksService) {
        super();
    }

    isSupportedType(entityType: EntityData): boolean {
        return MediaHelpers.isLibraryOrMedia(entityType.metadata.setName);
    }

    enhanceDataItems(dataItems: DataItem[], properties: {[key: string]: any}, data?: any): DataItem[] {
        return this.mapLongRunningTasks(dataItems, properties, data);
    }

    private mapLongRunningTasks(dataItems: DataItem[], properties: {[key: string]: any}, data: any): DataItem[] {
        let tasks = [];
        const whiteListedTasks = data && Array.isArray(data.whiteListedTasks) ? data.whiteListedTasks : [];

        if (data && data.tasks) {
            tasks = data.tasks;
        } else {
            tasks = this.longRunningTasksSerivce.progress.getValue();
        }
        const tasksMap = getRunningTasksAndMap(tasks);

        return dataItems.map(dataItem => {
            const foundTask = tasksMap[dataItem.data.ParentId] || tasksMap[dataItem.data.Id];
            const status: TaskStatus = TaskStatus[foundTask?.Status.toString()];
            if (dataItem.metadata.isImage && dataItem.parentKey !== stringConstants.DEFAULT_GUID && !!foundTask
                && whiteListedTasks.indexOf(foundTask.TaskName) !== -1 && (status === TaskStatus.Started || status === TaskStatus.Pending)) {
                return this.setLock(dataItem, properties, foundTask);
            } else if (!dataItem.metadata.isImage && !!foundTask
                && whiteListedTasks.indexOf(foundTask.TaskName) !== -1 && (status === TaskStatus.Started || status === TaskStatus.Pending)) {
                return this.disableSelection(dataItem, properties, foundTask);
            } else if (!!foundTask && whiteListedTasks.indexOf(foundTask.TaskName) === -1) {
                return this.setLock(dataItem, properties, foundTask);
            } else {
                return dataItem;
            }
        });
    }

    private disableSelection(dataItem: DataItem, properties: {[key: string]: any}, foundTask: BackgroundTask): DataItem {
        const data = cloneObject(dataItem.data);
        data["disableCheckbox"] = true;

        return DataItem.from(data, dataItem.metadata, dataItem.provider, dataItem.culture);
    }

    private setLock(dataItem: DataItem, properties: {[key: string]: any}, foundTask: BackgroundTask): DataItem {
        const data = cloneObject(dataItem.data);
        const errorMessage = generateRunningTaskError(foundTask, data.Id);

        for (const key in properties) {
            if (properties.hasOwnProperty(key)) {
                const value = properties[key];
                if (typeof(value) === "function") {
                    data[key] = value(errorMessage);
                } else {
                    data[key] = value;
                }
            }
        }

        return DataItem.from(data, dataItem.metadata, dataItem.provider, dataItem.culture);
    }
}

export const MEDIA_DATA_EXTENDER: ClassProvider = {
    multi: true,
    provide: DATA_EXTENDER_TOKEN,
    useClass: MediaDataExtender
};
