import { map } from "rxjs/operators";
import { Component, Input, Output, EventEmitter, Inject, OnInit, ContentChild, TemplateRef, OnChanges, SimpleChanges, Injector, ViewChild, ChangeDetectorRef } from "@angular/core";
import { Observable } from "rxjs";

import { ActionButton, ActionSection, ActionMenuOptions } from "./action-menu-model";
import { OUTSIDE_MENU_MAX_ORDINAL, ActionButtonsResolver, ACTION_BUTTON_LOOK, ButtonsState } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { WINDOW_TOKEN } from "./../../../../window.provider";
import { Operation, OperationCategory } from "./operation.model";
import { SfRxBase, TemplateData } from "@progress/sitefinity-component-framework";
import { Command } from "../../commands/command";
import { ExecutionContext } from "../../commands/execution-context";

export const DROPDOWN_DEFAULT_LOADER_STYLE = "color mini";
export const ACTIVE_BUTTON_LOOK = "active";

@Component({
    selector: "sf-action-menu",
    templateUrl: "./action-menu.component.html",
    providers: [ActionButtonsResolver]
})
export class ActionMenuComponent extends SfRxBase implements OnInit, OnChanges {
    @ContentChild("insideMenuButtonTemplate", { static: true }) insideMenuButtonTemplateRef: TemplateRef<any>;
    @ContentChild("dropDownButtonTemplate", { static: true }) dropDownButtonTemplateRef: TemplateRef<any>;
    @ViewChild("actionsButton", { static: false }) set dropdownButton(actionButton: any) {
        // no need for recalculations before the menu is opened
        if (actionButton && this.isDropdownOpened) {
            this.dropdownButtonBoundingRect = actionButton.dropdownButton.nativeElement.getBoundingClientRect();
            this.detector.detectChanges();
        }
    }
    dropdownButtonTemplateData: TemplateData = null;
    dropdownButtonBoundingRect: DOMRect;
    isDropdownOpened: boolean = false;

    @Input() isToolset: boolean;
    @Input() iconTitle: string;
    @Input() ariaLabel: string;
    @Input() buttonsLook: string;
    @Input() operations: Observable<Array<Operation>>;
    @Input() categories?: Array<OperationCategory>;
    @Input() selectedOperationName: string;
    @Input() options: ActionMenuOptions;
    @Input() dropdownButtonText: string;
    @Input() dropdownButtonIconLook: string;
    @Input() dropdownButtonIconName: string;
    @Input() dropdownItemHeadingText: string;
    @Input() executeCommandOnClick: boolean = true;
    @Input() moveInViewportTolerance: number;
    @Input() renderContentWhenNoOperations: boolean;
    @Input() renderDropdownInBody: boolean;

    @Input() lazy: boolean;
    @Input() buttonsState: ButtonsState;

    @Output() buttonClicked = new EventEmitter<ActionButton>();

    public loader: string = null;
    isDropdownDropped: boolean = false;

    public outsideMenuButtons: Array<ActionButton> = [];
    public buttonGroups: Array<ButtonGroup> = [];
    public insideMenuButtons: Array<ActionButton | ActionSection> = [];

    private hasPendingInitialization = false;
    private areOperationsInitialized = false;

    constructor(
        private actionButtonsResolver: ActionButtonsResolver,
        @Inject(WINDOW_TOKEN) private window: Window,
        private injector: Injector,
        private detector: ChangeDetectorRef) {
        super();
    }

    ngOnInit(): void {
        if (!this.lazy) {
            this.initOperations();
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        const buttonsStateChange = changes["buttonsState"];
        const buttonsLookStateChange = changes["buttonsLook"];
        const selectedOperationStateChange = changes["selectedOperationName"];

        if (buttonsStateChange && buttonsStateChange.currentValue) {
            this.actionButtonsResolver.updateButtonState(buttonsStateChange.currentValue);
        }

        if (buttonsLookStateChange && !buttonsLookStateChange.isFirstChange()) {
            this.outsideMenuButtons
                .map((actionButton: ActionButton) => actionButton as MenuButton)
                .forEach(menuButton => {
                    menuButton.enhancedLook = this.generateButtonsLook(menuButton.look);
                });
        }

        if (selectedOperationStateChange && selectedOperationStateChange.currentValue) {
            this.handleSelectedOperation(this.insideMenuButtons);
        }
    }

    reinitialize() {
        this.areOperationsInitialized = false;
        this.hasPendingInitialization = false;
        if (!this.lazy) {
            this.initOperations();
        }
    }

    handleOnDropdownClick(event: any) {
        this.isDropdownOpened = true;

        const isDropped = event.isDropped;
        this.isDropdownDropped = isDropped;
        if (!this.areOperationsInitialized && isDropped) {
            this.loader = DROPDOWN_DEFAULT_LOADER_STYLE;
        }
    }

    onButtonClick(button: ActionButton, event: MouseEvent) {
        // if the button pressed is not the left mouse button do nothing
        if (event) {
            if (event.which !== 1)
                return;

            if (button.isSubAction)
                event.stopPropagation();
        }

        const token = button.token;
        if (token && this.executeCommandOnClick) {
            const instance = this.injector.get(token.type) as Command;
            const context: ExecutionContext = {
                model: null,
                data: token.properties,
                currentRoute: null
            };

            instance.execute(context).subscribe();
            return;
        }

        // Without the timeout, the click event of a button (e.g. publish or save)
        // is triggered before the focusOut event of a field (e.g. create or edit an additional URL).
        // The 0 in the setTimeout is essential, do not remove it
        this.window.setTimeout(() => { this.buttonClicked.emit(button); }, 0);
    }

    isSection(button) {
        return button instanceof ActionSection;
    }

    generateButtonsLook(buttonLook: string): string {
        const look = [];
        if (buttonLook) {
            look.push(buttonLook);
        }

        if (this.isToolset) {
            look.push("no-hover no-active no-focus-visible no-border");
        }

        if (this.buttonsLook)
            look.push(this.buttonsLook);
        return look.length > 0 ? look.join(" ") : null;
    }

    public initOperations(): void {
        if (this.areOperationsInitialized || this.hasPendingInitialization) {
            return;
        }

        this.hasPendingInitialization = true;

        const operationsSubscription = this.operations.subscribe((operations: Operation[]) => {
            this.insideMenuButtons.length = 0;
            this.outsideMenuButtons.length = 0;
            this.buttonGroups.length = 0;
            const groupNames = new Set(operations.filter(x => x.GroupName).map(x => x.GroupName));

            groupNames.forEach((groupName) => {
                const group: ButtonGroup = {
                    ariaLabel: groupName,
                    iconTitle: groupName,
                    insideButtons: [],
                    dropdownButtonIconName: this.dropdownButtonIconName,
                    dropdownButtonIconLook: this.dropdownButtonIconLook,
                    dropdownButtonText: this.dropdownButtonText,
                    dropdownItemHeadingText: this.dropdownItemHeadingText
                };

                this.buttonGroups.push(group);

                const operationsForThisGroup = operations.filter(x => x.GroupName === groupName);
                const actionButtons = this.actionButtonsResolver.getActionButtons(operationsForThisGroup, this.categories, !this.isToolset);
                this.handleSelectedOperation(actionButtons);
                const buttonsCollection = this.processButtons(actionButtons);
                const allButtons = [].concat(...buttonsCollection.insideButtons).concat(...buttonsCollection.outsideButtons);
                group.insideButtons = allButtons.filter(x => !x.sourceOperation || !x.sourceOperation.IsGroup);
                const groupButton = allButtons.filter(x => x.sourceOperation && x.sourceOperation.IsGroup)[0];
                group.iconTitle = groupButton.title;
                group.ariaLabel = groupButton.title;
                group.dropdownButtonIconName = groupButton.context.icon || group.dropdownButtonIconName;
                group.dropdownButtonIconLook = groupButton.context.iconLook || group.dropdownButtonIconLook;
            });

            const operationsForThisGroup = operations.filter(x => !x.GroupName);
            const actionButtons = this.actionButtonsResolver.getActionButtons(operationsForThisGroup, this.categories, !this.isToolset);
            const buttonsCollection = this.processButtons(actionButtons);
            this.outsideMenuButtons.push(...buttonsCollection.outsideButtons);
            this.outsideMenuButtons.forEach((outsideButton) => {
                if (this.isToolset) {
                    if (outsideButton.context) {
                        if (outsideButton.context.icon && outsideButton.context.icon !== "Section") {
                            outsideButton.icon = outsideButton.context.icon;
                        }

                        outsideButton.iconLook = outsideButton.context.iconLook || "size-xs color-inherit";
                    }
                } else {
                    outsideButton.icon = null;
                    outsideButton.iconLook = "size-xs";
                }

            });
            this.insideMenuButtons.push(...buttonsCollection.insideButtons);
            this.trimSections(this.insideMenuButtons);

            this.handleSelectedOperation(actionButtons);

            this.areOperationsInitialized = true;
            this.loader = null;
            this.buttonGroups = [].concat(this.buttonGroups);
        });

        this.registerSubscription(operationsSubscription);
    }

    private handleSelectedOperation(actionButtons: Array<ActionButton | ActionSection>) {
        if (this.selectedOperationName) {
            const activeButton = actionButtons.find(button => button.name === this.selectedOperationName);

            if (activeButton && (activeButton instanceof ActionButton)) {
                actionButtons.filter(x => x instanceof ActionButton).forEach((x => {
                    (x as ActionButton).look = null;
                }));

                activeButton.look = ACTIVE_BUTTON_LOOK;
                if (this.dropDownButtonTemplateRef)
                    this.dropdownButtonTemplateData = { template: this.dropDownButtonTemplateRef, context: activeButton };
            }
        } else {
            this.dropdownButtonTemplateData = null;
        }
    }

    private processButtons(actionButtons: Array<ActionButton | ActionSection>): ButtonsCollection {
        const insideButtons: (ActionButton | ActionSection)[] = [];
        const outsideButtons: ActionButton[] = [];

        actionButtons.forEach((button: ActionButton) => {
            if (button instanceof ActionSection) {
                insideButtons.push(button);
                return;
            }

            const menuButton = button as MenuButton;

            if (button.loading) {
                menuButton.loader = button.loading.pipe(map(loading => {
                    if (!loading)
                        return null;

                    if (button.look && button.look.includes(ACTION_BUTTON_LOOK))
                        return "transparent";

                    return "color";
                }));
            }

            menuButton.enhancedLook = this.generateButtonsLook(button.look);

            if (this.isWithinBoundries(button)) {
                if (button.ordinal > OUTSIDE_MENU_MAX_ORDINAL || (this.options && this.options.showAllAsDropdown)) {
                    insideButtons.push(button);
                } else if (!(this.options && this.options.showAllAsDropdown)) {
                    outsideButtons.push(button);
                }
            }
        });

        return {
            insideButtons: insideButtons,
            outsideButtons: outsideButtons
        };
    }

    // TODO: revise
    private trimSections(insideMenuButtons: Array<ActionButton | ActionSection>) {
        const newArr = [];
        for (let i = 0; i < insideMenuButtons.length; i++) {
           if (insideMenuButtons[i] !== insideMenuButtons[i + 1]) {
                newArr.push(insideMenuButtons[i]);
           }
        }

        insideMenuButtons.splice(0, insideMenuButtons.length, ...newArr);

        for (let i = 0; i < insideMenuButtons.length; i++) {
            if (this.isSection(insideMenuButtons[i]) && (<ActionSection>insideMenuButtons[i]).hidden) {
                insideMenuButtons.shift();
                --i;
            } else {
                break;
            }
        }

        for (let i = insideMenuButtons.length - 1; i >= 0; i--) {
            if (this.isSection(insideMenuButtons[i])) {
                insideMenuButtons.pop();
            } else {
                break;
            }
        }
    }

    // TODO: revise
    private isWithinBoundries(button: ActionButton): boolean {
        return !this.options ||
            this.options.showAllAsDropdown ||
            (button.ordinal >= this.options.minOrdinal && button.ordinal <= this.options.maxOrdinal);
    }
}
export interface ButtonsCollection {
    insideButtons: (ActionButton | ActionSection)[];
    outsideButtons: (ActionButton)[];
}

export interface ButtonGroup {
    iconTitle: string;
    ariaLabel: string;
    dropdownButtonIconName: string;
    dropdownButtonIconLook: string;
    dropdownButtonText: string;
    dropdownItemHeadingText: string;
    button?: ActionButton,
    insideButtons: (ActionButton | ActionSection)[],
    operations?: Observable<Operation[]>,
    buttonsLook?: string
}

export interface MenuButton extends ActionButton {
    enhancedLook: string;
}
