import { TokenData } from "@progress/sitefinity-component-framework";
import { BulkItemSelectionInfo } from "../../../content/dynamic-modules/components/bulk-operations/bulk-operations.component";
import { ItemsState } from "../../../content/dynamic-modules/services/dynamic-item-store-state";
import { ActionButtonContext } from "./action-menu-model";

export interface Operation {
    Title?: string;
    DetailedTitle?: string;
    Category?: OperationCategory;
    Name: string;
    Ordinal?: number;
    Warning?: string;
    Description?: string;
    Link?: string;
    Parameters?: [{ [key: string]: any }];
    ContextParameters?: [{ [key: string]: any }];
    ParentOperation?: ParentOperationInfo;
    RequiresConfirmation?: boolean;
    RequiresItemUpdate?: boolean
    ExecuteOnServer?: boolean;
    PerformsDelete?: boolean;
    HasLinkResult?: boolean;
    Actions?: OperationAction[],
    GroupName?: string;
    IsGroup?: boolean;
    KeepFocus?: boolean;
    SubOperation?: OperationAction;
    SubText?: string;
    context?: OperationContext;
    token?: TokenData;
    icon?: string;
}

export interface ParameterArgument {
    Label: string;
    Value: string;
    Warning: string;
    AdditionalValue: string;
    AdditionalValueLabel: string;
}

export interface OperationContext extends ActionButtonContext {
    look?: string
}

export interface OperationItemResult {
    Success: boolean,
    Message?: string,
    UndoOperation?: Operation,
    MultipleItemsMessage?: string,
    Type?: OperationActionType,
    Link?: string,
    SourceOperation?: Operation,
    AvailableActions?: string[],
    Title?: string
}

export interface OperationResultNotification {
    SingleItemMessage: string,
    MultipleItemMessage: string,
    Type: OperationActionType
}

export interface OperationAction {
    Name: string,
    Title: string,
    Type: OperationActionType
}

export enum OperationActionType {
    None = 0,
    Success = 1,
    Error = 2,
    Warning = 3
}

export interface ModifyOperationsInfo {
    currentItemSelectionInfo: BulkItemSelectionInfo,
    previousItemSelectionInfo: BulkItemSelectionInfo,
    itemsState: ItemsState
}

/**
 * @ExposedInApi {OperationCategory} CommandCategory v1/commands/command-category.d.ts
 */
export interface OperationCategory {
    Name: string;
    Title?: string;
    HideSeparator?: boolean;
}

export interface ParentOperationInfo {
    Name: string;
    Required: boolean;
}

