import { interval, Observable, of, ReplaySubject, Subject } from "rxjs";
import { catchError, takeUntil } from "rxjs/operators";
import { LOCALE } from "../../../../../../fields/common/common-constants";
import { convertIsoStringToUTCDate } from "../../../../../../fields/common/utils";
import { DataItem, ExecutionContext } from "../../../../api";
import { NOTIFICATION_DURATION_INFINITE, SERVICE_HOOK_ACTIVITY_STATUS } from "../../../content/constants";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ActionIcon } from "../../../content/dynamic-modules/services/entity/action-buttons";
import { ExecuteOnceInBulkCommand } from "../../../shared/commands/command";
import { ActionButton } from "../../../shared/components/action-menu/action-menu-model";
import { CONTEXT_PARAMETERS, OPERATION_TITLES } from "../../../shared/components/action-menu/operation.model";
import { Button, CancelButton, ClickResult, ConfirmButton, ModalComponentSettings, ModalWindowService } from "../../../shared/services/modal-window.service";
import { NOTIFICATION_LOOKS } from "../../../shared/services/notification/notification-data";
import { BasicNotificationInfo } from "../../../shared/services/notification/notification-info";

const POLL_ACTIVITY_INTERVAL: number = 1000;
export class RunAgainCommand implements ExecuteOnceInBulkCommand {
    executeOnceInBulk: boolean = true;

    constructor(private modalWindowService: ModalWindowService, private dynamicItemService: DynamicItemService) {
    }

    execute(context: ExecutionContext): Observable<boolean> {
        const doneCallback = new Subject<boolean>();
        const actionButton: ActionButton = context.data.action;
        const dataItem = context.data.dataItem;

        const itemTitle = dataItem.data.ServiceHookTitle;
        if (actionButton.contextParameters) {
            actionButton.contextParameters[CONTEXT_PARAMETERS.currentTitle] = itemTitle;
        } else {
            actionButton.contextParameters = {
                [CONTEXT_PARAMETERS.currentTitle]: itemTitle
            };
        }

        const settings = this.generateConfirmationSettings(actionButton, dataItem, doneCallback);
        this.modalWindowService.openModalConfirmation(context.currentRoute, settings, dataItem);

        return doneCallback.asObservable();
    }

    getNotification(error: Error, showSuccess: boolean): BasicNotificationInfo {
        if (error) {
            const message = error.message ? error.message : `Service hook failed to run.`;
            return {
                message: message,
                look: NOTIFICATION_LOOKS.ERROR,
                duration: NOTIFICATION_DURATION_INFINITE
            };
        }

        if (showSuccess) {
            return {
                message: "Service hook has been successfully run.",
                look: NOTIFICATION_LOOKS.SUCCESS,
                closeButton: false
            };
        }

        return null;
    }

    private generateConfirmationSettings(actionButton: ActionButton, dataItem: DataItem, done: Subject<boolean>): ModalComponentSettings {
        const confirmButton = new ConfirmButton(OPERATION_TITLES.run, data => this.executeRunAgain(data));

        const settings: ModalComponentSettings = {
            title: actionButton.title,
            detailedTitle: `Run this ${dataItem.metadata.singularName.toLocaleLowerCase()} again?`,
            icon: ActionIcon[actionButton.name],
            contextParameters: actionButton.contextParameters,
            description: this.generateDescription(dataItem),
            action: actionButton.name,
            descriptionAllowHtml: true,
            buttons: new Array<Button>(confirmButton, new CancelButton()),
            disableUserInteractionOnLoading: true, // user should not be able to leave the dialog or do any actions while the run again is in progress
            innerFormLook: "sf-pb-zero sf-pt-zero",
            doneCallback: (context: ClosingContext) => {
                if (context && context.data && context.data.data) {
                    if (context.data.data.error) {
                        done.error(context.data.data.error);
                    } else {
                        done.next(true);
                    }
                } else {
                    done.next(false);
                }
            }
        };

        return settings;
    }

    private executeRunAgain(context): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (context && context.component && context.component.dataItem) {
            // Trigger loading in the confirm button
            clickResult.next(new ClickResult(true, false));

            const dataItem = context.component.dataItem;
            this.dynamicItemService.executeBoundFunction(DataItem.emptyItem(dataItem), `Default.RunAgain(activityId=${dataItem.key})`).subscribe(() => {
                this.waitActivityToComplete(dataItem).subscribe(() => {
                    clickResult.next(new ClickResult({ error: null }, true, false, false));
                }, error => {
                    clickResult.next(new ClickResult({ error: error }, true, false, false));
                });
            }, error => {
                clickResult.next(new ClickResult({ error: error }, true, false, false));
            });
        }

        return clickResult;
    }

    private waitActivityToComplete(dataItem: DataItem): Observable<void> {
        const activityCompleted = new Subject<void>();

        interval(POLL_ACTIVITY_INTERVAL)
            .pipe(takeUntil(activityCompleted), catchError(() => of()))
            .subscribe(() => {
                this.dynamicItemService.executeBoundFunction<{ Status: string }>(DataItem.emptyItem(dataItem), `Default.GetActivity(activityId=${dataItem.key})`)
                    .subscribe(activity => {
                        if (activity.Status === SERVICE_HOOK_ACTIVITY_STATUS.SUCCESSFUL) {
                            activityCompleted.next();
                        } else if (activity.Status === SERVICE_HOOK_ACTIVITY_STATUS.FAILED) {
                            activityCompleted.error({ activityStatus: SERVICE_HOOK_ACTIVITY_STATUS.FAILED });
                        }
                    }, error => {
                        activityCompleted.error(error);
                    });
            });

        return activityCompleted;
    }

    private generateDescription(dataItem: DataItem): string {
        const date = convertIsoStringToUTCDate(dataItem.data.StartTime);
        const dateValue = date.toLocaleDateString(LOCALE, { year: "numeric", month: "short", day: "numeric" });

        let description = `This service hook will be run again with the original data from ${dateValue}.`;

        if (dataItem.data.TriggeredByContentItem) {
            description = `This service hook will be run again with the original version of <br> “${dataItem.data.Title}” from ${dateValue}.`;
        }

        description += " <a href='https://www.progress.com/documentation/sitefinity-cms/service-hooks-history' target='_blank'>Learn more</a>";

        return description;
    }
}
