import { Component, OnInit, Inject, AfterViewInit, ViewEncapsulation, OnDestroy, HostListener } from "@angular/core";
import { EnvironmentService } from "../../../shared/services/environment.service";
import { environmentTypes } from "../../../../environment";
import { ActivatedRoute, Router, NavigationExtras } from "@angular/router";
import { RESOLVE_NAMES, QUERY_PARAMS, UNSAVED_CHANGES_MESSAGE, COMPONENT_NAMES, STAY_AFTER_PUBLISH_TIMEOUT } from "../../../content/constants";
import { PageData } from "../../services/page.resolver";
import { NavigateToEditArguments, DataItem } from "../../../content/dynamic-modules/interfaces";
import { of, Observable, timer } from "rxjs";
import { OPERATION_NAMES } from "../../../shared/components/action-menu/operation.model";
import { CompositeOperationsProvider } from "../../../content/dynamic-modules/services/operations/operations-provider";
import { ActionButton, ButtonState } from "../../../shared/components/action-menu/action-menu-model";
import { DOCUMENT_TOKEN } from "../../../../document.provider";
import { Settings } from "../../../shared/services/settings.service";
import { SiteData } from "../../../shared/services/metadata/site-data.store";
import { DynamicItemStore } from "../../../content/dynamic-modules/services/dynamic-item.store";
import { ModalWindowService } from "../../../shared/services/modal-window.service";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { Location } from "@angular/common";
import { DynamicItemComponent, UNSAVED_CHANGES_DIALOG_MESSAGE } from "../../../content/dynamic-modules/components/entity/dynamic-item.component";
import { FieldsGeneratorService } from "../../../shared/services/fields-generator.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../shared/services/notification/notification.service";
import { tap, distinctUntilChanged, skip } from "rxjs/operators";
import { WidgetPropertyEditorService } from "../../../widget-editor/services/widget-property-editor.service";
import { ZoneEditor } from "../../services/zone-editor";
import { ActionButtonsStateService } from "../../../shared/services/action-buttons-state.service";
import { SAME_TAB_TARGET, stringConstants } from "../../../../common-constants";
import { EditInDialogOperationResult } from "../../../content/dynamic-modules/services/operations/commands/edit-in-dialog-command";
import { ROUTE_PATHS } from "../../../../constants/route-paths";
import { toggleIrisIntegratedStyles } from "../../../../utils";
import { NavbarConfiguration } from "../../../shared/components/navigation/navigation-menu/navigation-menu.component";
import { OperationsDataContext } from "../../../content/dynamic-modules/services/operations/interfaces";
import { CompositeEditExtender } from "../../../shared/services/edit/composite-edit-extender";
import { EditNavigationService } from "../../../shared/services/edit-navigation.service";
import { ActionExecutorService } from "../../../shared/services/action-executor.service";
import { ItemWithOperationResult } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { NOTIFICATION_LOOKS } from "../../../shared/services/notification/notification-data";
import { SortService } from "../../../shared/services/sort.service";
import { KeyboardShortcutsService, KeyboardAction } from "../../../../services/keyboard-shortcuts.service";
import { BasicNotificationInfo } from "../../../shared/services/notification/notification-info";
import { PagesActionHandler } from "../../services/pages-action-handler.service";
import { CommonActionContext } from "../../../shared/services/grid/grid-extender-base";
import { ParentService } from "../../../content/dynamic-modules/services/parent.service";
import { KeyboardActionType } from "../../../../services/keyboard-shortcuts.constants";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../services/store/actions/actions.sidebar";
import { AppStore } from "../../../../services/store/app-store";
import { SIDEBAR_SELECTORS } from "../../../../services/store/selectors/selectors.sidebar";
import { ActionButtonsResolver } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { CompositeItemHooksProvider } from "../../../content/dynamic-modules/services/entity/item-hooks-provider";
import { ComponentCommunicationService } from "../../../shared/services/component-communication.service";
import { SelectorService, SELECTOR_SERVICE } from "../../../libraries/selectors";

export const EDIT_PAGE_BACK_BUTTON_LABEL = "All pages";
export const NAVBAR_PAGE_EDITOR_LOOK = "page-editor";

export const TOGGLE_EVENT_NAME = "toggleToolbar";

@Component({
    selector: "sf-edit-page-component",
    templateUrl: "./edit-page.component.html",
    styleUrls: ["./edit-page.component.scss"],
    encapsulation: ViewEncapsulation.None,
    providers: [
        ActionButtonsStateService,
        KeyboardShortcutsService,
        ActionButtonsResolver
    ]
})
export class EditPageComponent extends DynamicItemComponent implements OnInit, AfterViewInit, OnDestroy {
    get isEditMode() {
        return true;
    }

    navbarConfiguration: NavbarConfiguration;

    private siteData: SiteData;
    private isInIntegratedMode: boolean;
    private showBeforeUnloadWarning: boolean;

    @HostListener("window:onABTestingSegmentCLick", ["$event"]) onABTestingSegmentCLick(event) {
        this.showBeforeUnloadWarning = event.detail.raiseOnBeforeUnload;
    }

    @HostListener("window:beforeunload", ["$event"]) onBeforeUnload(event: BeforeUnloadEvent) {
        if (this.zoneEditor.getHasChanges() && this.showBeforeUnloadWarning) {
            event.returnValue = UNSAVED_CHANGES_DIALOG_MESSAGE;
        }
    }

    constructor(
        dynamicItemStore: DynamicItemStore,
        modalWindowService: ModalWindowService,
        route: ActivatedRoute,
        fieldsGeneratorService: FieldsGeneratorService,
        router: Router,
        operationsProvider: CompositeOperationsProvider,
        editExtender: CompositeEditExtender,
        @Inject(WINDOW_TOKEN) windowProvider: Window,
        location: Location,
        envService: EnvironmentService,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        settings: Settings,
        widgetPropertyEditorService: WidgetPropertyEditorService,
        buttonStateService: ActionButtonsStateService,
        @Inject(DOCUMENT_TOKEN) private document: Document,
        private readonly zoneEditor: ZoneEditor,
        editNavigationService: EditNavigationService,
        serverOperationsExecutor: ActionExecutorService,
        protected keyboardShortcutsService: KeyboardShortcutsService,
        sortService: SortService,
        private pagesCommonHandler: PagesActionHandler,
        protected parentService: ParentService,
        protected store: AppStore,
        itemHooksProvider: CompositeItemHooksProvider,
        protected communicationService: ComponentCommunicationService,
        @Inject(SELECTOR_SERVICE) private selectorService: SelectorService) {
        super(
            dynamicItemStore,
            modalWindowService,
            route,
            fieldsGeneratorService,
            router,
            operationsProvider,
            editExtender,
            windowProvider,
            location,
            notificationService,
            settings,
            buttonStateService,
            editNavigationService,
            serverOperationsExecutor,
            sortService,
            keyboardShortcutsService,
            parentService,
            store,
            itemHooksProvider,
            communicationService
        );

        this.isInIntegratedMode = envService.getEnvironment() === environmentTypes.integration;

        widgetPropertyEditorService.initialize(this.route.parent);

        this.fieldSections$ = of([]);
    }

    ngOnInit() {
        this.registerSubscription(this.configureNavbar().subscribe());
        super.handleItemChanges();
        super.resetActionButtons();
        super.handleButtons();
        this.handleKeyboardShortcuts();
        this.editNavigationService.handleEditAllPropertiesFromMVCWidgets(this.route);

        const pageData = <PageData>this.route.snapshot.data[RESOLVE_NAMES.itemData];
        this.entityData = pageData.entityData;
        this.siteData = this.route.parent.snapshot.data[RESOLVE_NAMES.siteDataStore];
        this.showBeforeUnloadWarning = true;

        this.item.next({ content: pageData.item, isLoading: false });

        toggleIrisIntegratedStyles(true);

        const config = {
            title: `Show Content and Layout`,
            icon: "th-large",
            name: "siblings",
            look: "toggle"
        };

        this.sidebarData = {
            entityType: this.entityData.metadata.typeFullName,
            externalKey: null,
            buttons: [config]
        };

        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.configure(this.sidebarData));
        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.changeAndOpen(config, false));

        // skips the first firing of null
        const activeConfigSubscription = this.store.pipe(SIDEBAR_SELECTORS.isOpen, skip(1), distinctUntilChanged()).subscribe(() => {
            this.onButtonClickHandler();
        });
        this.registerSubscription(activeConfigSubscription);

        this.selectorService.attachFilePickerEvents();
    }

    ngOnDestroy() {
        this.keyboardShortcutsService.removeListener(COMPONENT_NAMES.EDIT_PAGE);
        this.selectorService.removeFilePickerEvents();
    }

    // eslint-disable-next-line @angular-eslint/no-empty-lifecycle-method
    ngAfterViewInit() {
        // override base class implementation
    }

    onButtonClickHandler() {
        window.dispatchEvent(new Event(TOGGLE_EVENT_NAME));
    }

    onNavigateBack() {
        if (this.isInIntegratedMode) {
            const workflowMenuWrapper = this.document.querySelector("div.sfWorkflowMenuWrp");
            if (workflowMenuWrapper) {
                const backToLink = <HTMLAnchorElement>workflowMenuWrapper.querySelector("a.sfCancel");
                if (backToLink) {
                    backToLink.click();
                    return;
                }
            }

            const url = `${this.settings.url}Sitefinity/Pages`;
            this.window.open(url, SAME_TAB_TARGET);

            return;
        }

        const queryParams = {
            [QUERY_PARAMS.CULTURE]: this.settings.getSiteCulture(this.siteData.Id)
        };

        const navigationExtras: NavigationExtras = {
            queryParams: queryParams
        };

        this.router.navigate([ROUTE_PATHS.PAGES], navigationExtras);
    }

    onActionButtonClicked(button: ActionButton) {
        const actionName = button.name.split("_")[0];
        if (button.name === OPERATION_NAMES.stopSyncing || actionName === OPERATION_NAMES.changeCulture) {
            this.invokeWithPromptForUnsavedChanges(() => {
                super.onActionButtonClicked(button);
            });

            return;
        }

        if (button.link) {
            this.invokeWithPromptForUnsavedChanges(() => {
                this.isLoading = true;
                super.onActionButtonClicked(button);
            });

            return;
        }

        if (button.name === OPERATION_NAMES.preview) {
            const previewLink = <HTMLAnchorElement>this.document.querySelector(`a[rel="${OPERATION_NAMES.preview}"]`);
            if (previewLink) {
                previewLink.click();
            } else {
                super.onActionButtonClicked(button);
            }
        } else if (button.name === OPERATION_NAMES.edit) {
            this.registerSubscription(this.navigateToEdit(new NavigateToEditArguments({ dataItem: this.currentItem, parentId: this.parentId, commandName: OPERATION_NAMES.edit }))
                .subscribe(result => {
                    if (result.success) {
                        this.item.next({
                            content: result.dataItem,
                            isLoading: false
                        });
                    }
                }));
        } else {
            super.onActionButtonClicked(button);
        }
    }

    navigateToEdit(args: NavigateToEditArguments): Observable<EditInDialogOperationResult> {
        const result$ = super.navigateToEdit(args);

        this.registerSubscription(result$.subscribe(res => {
            this.isLoading = res.isLoading;
        }));

        return result$;
    }

    handleServerOperation(button: ActionButton): Observable<ItemWithOperationResult> {
        const superResult$ = super.handleServerOperation(button);
        this.registerSubscription(superResult$.subscribe(() => {
            if (button.sourceOperation && button.sourceOperation.ParentOperation && button.sourceOperation.ParentOperation.Name === OPERATION_NAMES.edit) {
                const shouldStayAfterPublish = this.serverOperationExecutor.shouldStayAfterPublish(button);

                if (!shouldStayAfterPublish) {
                    this.registerSubscription(timer(STAY_AFTER_PUBLISH_TIMEOUT).subscribe(() => {
                        this.onNavigateBack();
                    }));
                }
            } else if (button.sourceOperation.Name === OPERATION_NAMES.stopSyncing) {
                this.isLoading = true;
                // we must reload as the behaviour for stop syncing was to reload the page unitl now
                // not reloading might result with inconsistent data in the zone editor

                // Dirty hack because of a bug in Angular:
                // https://github.com/angular/angular/issues/24656
                let url = this.window.location.href;
                const matches = this.window.location.href.match(/adminapp\/pages\/(\(.*\))/);
                if (matches && matches.length > 1) {
                    url = url.replace(matches[1], matches[1].substring(1, matches[1].length - 1));
                }

                this.window.open(url, SAME_TAB_TARGET);
            }
        }, error => {
            let msg = stringConstants.EMPTY_STRING;
            if (error && error.innerErrors && error.innerErrors[0] && error.innerErrors[0].message) {
                msg = error.innerErrors[0].message;
            }

            if (!msg && error && error.message) {
                msg = error.message;
            }

            if (!msg) {
                msg = "An error occurred while trying to update the page.";
            }

            const notificationData: BasicNotificationInfo = {
                message: msg,
                look: NOTIFICATION_LOOKS.ERROR
            };

            this.notificationService.publishBasicNotification(notificationData);
        }));

        return superResult$;
    }

    protected getOperationsDataContext(): OperationsDataContext {
        return {
            isEditingPageContent: true
        };
    }

    protected handleSaveOperationSuccess(result: ItemWithOperationResult, button: ActionButton, wasItemInCreate: boolean, saveOperationName: string = null): void {
        if (result) {
            const operationName = saveOperationName || button.sourceOperation.Name;
            this.zoneEditor.handleCompletedWorkflowOperation(operationName);
        }

        super.handleSaveOperationSuccess(result, button, wasItemInCreate, saveOperationName);
    }

    protected configureNavbar() {
        return super.configureNavbar()
            .pipe(tap(() => {
                this.navbarConfiguration.look = `toggle ${NAVBAR_PAGE_EDITOR_LOOK}`;
                this.navbarConfiguration.leftNavbarButtonData.title = EDIT_PAGE_BACK_BUTTON_LABEL;
                this.navbarConfiguration.leftNavbarButtonData.autoNavigateBack = false;
            }));
    }

    protected handleKeyboardShortcuts() {
        this.keyboardShortcutsService.init();
        const keyboardShortcutsSubscription = this.keyboardShortcutsService.addListener(this.operations, COMPONENT_NAMES.EDIT_PAGE, false).subscribe((action: KeyboardAction) => {
            if (!action) {
                return;
            }

            switch (action.type) {
                case KeyboardActionType.Delete:
                case KeyboardActionType.Publish:
                case KeyboardActionType.Save:
                case KeyboardActionType.Unpublish:
                case KeyboardActionType.Schedule:
                case KeyboardActionType.Preview:
                    this.triggerKeyboardShortcutAction(action);
                    break;
                case KeyboardActionType.Create:
                    this.navigateToCreatePage();
                    break;
            }
        });

        this.registerSubscription(keyboardShortcutsSubscription);
    }

    protected triggerKeyboardShortcutAction(action: KeyboardAction) {
        if (this.modalWindowService.isDialogOpened || !action.action) {
            return;
        }

        action.event.preventDefault();

        if (!this.editableFields.triggerValidCheck()) {
            return;
        }

        // Prevent multiple update (Publish, SaveAsDraft) operations
        if (this.buttonsState && this.buttonsState.primary && this.buttonsState.primary.state !== ButtonState.Default) {
            return;
        }

        this.onActionButtonClicked(action.action as ActionButton);
    }

    private navigateToCreatePage() {
        const emptyDataItem = DataItem.emptyItem(this.entityData);
        const commonContext: CommonActionContext = {
            actionName: OPERATION_NAMES.create,
            item: emptyDataItem,
            route: this.route
        };

        this.pagesCommonHandler.navigateToEdit(commonContext);
    }

    private invokeWithPromptForUnsavedChanges(callback: () => void) {
        if (this.zoneEditor.getHasChanges()) {
            if (this.window.confirm(UNSAVED_CHANGES_MESSAGE)) {
                callback();
            }
        } else {
            callback();
        }
    }
}
