import { Observable, ReplaySubject } from "rxjs";
import { Injectable } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { ExecuteOnceInBulkCommand } from "../shared/commands/command";
import { ExecutionContext } from "../shared/commands/execution-context";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { DataItem, OperationResult } from "../content/dynamic-modules/interfaces";


// TODO: delete command is not used in the ActionExecutorService, we should revise the implementation to provide a single way of deleting items
@Injectable()
export class ExportToExcelCommand implements ExecuteOnceInBulkCommand {
    executeOnceInBulk: boolean = true;

    constructor(private httpClient: HttpClient) {
    }


    execute(context: ExecutionContext): Observable<OperationResult> {
        const result = new ReplaySubject<OperationResult>(1);
        const dataItems: [DataItem] = context.data.dataItem ? [context.data.dataItem] : context.data.selectedItems;

        const formName = context.data.entityData.metadata.setName.replace(`${ENTITY_SET.FORM_RESPONSES}-`, "");
        const formData = new FormData();

        const entriesIds = dataItems.map(x => x.key).join(",");
        formData.set("entriesIds", entriesIds);
        const url = `/Sitefinity/Content/FormEntries/Export?exportAs=xlsx&formName=${formName}&itemType=${context.data.entityData.metadata.typeFullName}`;

        this.httpClient.post<Blob>(url, formData, {
            responseType: 'blob' as 'json'
        }).subscribe((response) => {
            const link = document.createElement('a');
            link.href = window.URL.createObjectURL(response);
            link.download = `${formName}-responses.xlsx`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            result.next({
                success: true,
            });
        });

        return result.asObservable();
    }
}
