import { Component, OnInit } from "@angular/core";

import { ChoiceYesNoComponent } from "./choice-yesno.component";
import { createValueAccessor } from "../field-base";
import { ChoiceSettings } from "./choice.settings";
import { Observable } from "rxjs";
import { tap } from "rxjs/operators";

const ICON_NAME_FALSE_VALUE: string = "ban";
const ICON_NAME_TRUE_VALUE: string = "check";

@Component({
    // tslint:disable-next-line:component-selector
    selector: "sf-yes-no-choice-readOnly",
    templateUrl: "./choice-yesno-readOnly.component.html",
    providers: [createValueAccessor(ChoiceYesNoReadOnlyComponent)]
})
export class ChoiceYesNoReadOnlyComponent extends ChoiceYesNoComponent implements OnInit {
    iconName: string = ICON_NAME_FALSE_VALUE;
    isIconVisible: boolean = true;

    protected loadChoices(): Observable<void> {
        return super.loadChoices().pipe(tap(() => {
            if (this.context != null) {
                // TODO: The default value should probably be constructed in the settigs for this control and be retreived from there.
                const yesNoText = !!this.value ? "Yes" : "No";
                this.settings = new ChoiceSettings(yesNoText, true);
                this.isIconVisible = false;
            } else if (this.value) {
                this.iconName = ICON_NAME_TRUE_VALUE;
            }
        }));
    }

    hasEmptyValue(): boolean {
        return false;
    }
}