import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Injectable } from "@angular/core";
import { Properties } from "../../shared/fields.constants";
import { SiteAndLanguage, SiteAndLanguageSelectorComponent } from "../components/site-and-language-selector/site-and-language-selector.component";
import { ParentSelectorComponent } from "../../parent-selector/parent-selector.component";
import { CUSTOM_ERROR_PREFIX } from "../../../../../fields/common/validators/validators.constants";
import { cloneObject } from "../../../utils";
import { TARGET_SITE_ID } from "../providers/page-fields.provider";
import { PAGE_ITEM_FULL_NAME } from "../../shared/services/metadata/meta-data-constants";
import { StructureUrlNameComponent } from "../../shared/components/urlNameStructure/structure-urlName.component";

@Injectable()
export class PagesFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === Properties.PARENT_ID) {
            const urlNameField = fields.find(x => x.fieldModel.key === "UrlName");
            if (urlNameField) {
                const fieldInstance = urlNameField.currentInstance as StructureUrlNameComponent;
                if (fieldInstance instanceof StructureUrlNameComponent) {
                    if (fieldInstance.handleParentChange) {
                        fieldInstance.handleParentChange(changedValue);
                    }
                }
            }
        } else if (changedFieldName === TARGET_SITE_ID) {
            const siteAndLangVal: SiteAndLanguage = changedValue;
            if (siteAndLangVal) {

                if (siteAndLangVal.RootId) {
                    const parentField = fields.find(x => x.fieldModel.key === "ParentId");
                    const fieldInstance = parentField.currentInstance as ParentSelectorComponent;

                    const targetSiteIdField = fields.find(x => x.fieldModel.key === TARGET_SITE_ID);
                    const targetSiteIdFieldInstance = targetSiteIdField.currentInstance as SiteAndLanguageSelectorComponent;
                    fieldInstance.setCulture(targetSiteIdFieldInstance.selectedLanguage);
                    fieldInstance.setSiteId(targetSiteIdFieldInstance.selectedSiteId);
                    fieldInstance.writeValue(siteAndLangVal.RootId);
                }

                const urlNameField = fields.find(x => x.fieldModel.key === "UrlName");
                const errors = urlNameField.formControl.errors;
                if (errors) {
                    const errorNames = Object.keys(errors).filter(x => x.startsWith(CUSTOM_ERROR_PREFIX));
                    const objectClone = cloneObject(errors);
                    errorNames.forEach(name => {
                        delete objectClone[name];
                    });

                    urlNameField.formControl.setErrors(objectClone);
                    urlNameField.formControl.updateValueAndValidity();
                }
            }
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === PAGE_ITEM_FULL_NAME;
    }
}

export const PAGES_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: PagesFieldsChangeService,
    multi: true
};
