import { Injectable } from "@angular/core";
import { TotalCountResult } from "../../content/dynamic-modules/interfaces";
import { ComponentMetadata } from "../../widget-editor/interfaces/widget-editor";
import { from, Observable } from "rxjs";
import { WebFormsAndMvcRendererContract } from "./webforms-and-mvc.renderer.contract";
import { AuthService } from "../../auth/auth.service";
import { RendererContract, GetWidgetMetadataArgs, RenderWidgetArgs, GetWidgetsArgs, GetCategoriesArgs, WidgetSection, RenderResult } from "./renderer.types";
import { cloneObject } from "../../../utils";
import { map } from "rxjs/operators";

@Injectable()
export class RendererService {
    private contract: RendererContract;
    constructor(private legacyContract: WebFormsAndMvcRendererContract, private authService: AuthService) {

    }

    initialize(contract: RendererContract) {
        this.contract = contract;
    }

    getWidgetMetadata(args: GetWidgetMetadataArgs): Observable<ComponentMetadata> {
        args.token = this.authService.getToken();
        return from(this.getContract().getWidgetMetadata(args)).pipe(map(x => cloneObject(x)));

    }

    getCategories(args: GetCategoriesArgs): Observable<Array<string>> {
        args.token = this.authService.getToken();
        return from(this.getContract().getCategories(args));
    }

    renderWidget(args: RenderWidgetArgs): Observable<RenderResult> {
        args.token = this.authService.getToken();
        return from(this.getContract().renderWidget(args));
    }

    getWidgets(args: GetWidgetsArgs): Observable<TotalCountResult<Array<WidgetSection>>> {
        args.token = this.authService.getToken();
        return from(this.getContract().getWidgets(args));
    }

    private getContract(): RendererContract {
        return this.contract || this.legacyContract;
    }
}
