import { Injectable, Inject } from "@angular/core";

import { StorageService, LOCAL_STORAGE } from "../services/storage.service";
import { KEYS } from "../services/settings-keys";
import { stringConstants } from "../../../common-constants";
import { ItemPaging } from "./grid/grid-extender-base";

export const WEB_SERVICE_ENDPOINT = "sf/system/";
export const WEB_SERVICE_LIVE_ENDPOINT = "sf/system-live/";

@Injectable()
export class Settings {
    constructor(@Inject(LOCAL_STORAGE) private storage: StorageService) {
    }

    get url(): string {
        const item: string = this.storage.getItem(KEYS.SERVICE_URL) || stringConstants.EMPTY_STRING;
        const result = Settings.formatUrl(item);
        if (item !== result) {
            this.url = result;
        }

        return result;
    }

    set url(value: string) {
        const url = Settings.formatUrl(value);
        this.storage.setItem(KEYS.SERVICE_URL, url);
    }

    get webServiceUrl(): string {
        return `${this.url}${WEB_SERVICE_ENDPOINT}`;
    }

    get webServiceLiveUrl(): string {
        return `${this.url}${WEB_SERVICE_LIVE_ENDPOINT}`;
    }

    get resourcePath(): string {
        return this.storage.getItem(KEYS.RESOURCE_PATH);
    }

    get siteId(): string {
        const siteId: string = this.storage.getItem(KEYS.SITE_ID);
        return siteId;
    }

    get authenticationProtocol(): string {
        const protocol: string = this.storage.getItem(KEYS.AUTH_PROTOCOL);
        return protocol;
    }

    setExpandedNodeIds(key: string, expandedNodes: string[]) {
        let jsonData = this.storage.getItem(KEYS.EXPANDED_NODE_IDS);
        if (!jsonData) {
            jsonData = {};
        } else {
            jsonData = JSON.parse(jsonData);
        }

        jsonData[key] = expandedNodes;

        this.storage.setItem(KEYS.EXPANDED_NODE_IDS, JSON.stringify(jsonData));
    }

    getExpandedNodeIds(key: string): string[] {
        const jsonData = this.storage.getItem(KEYS.EXPANDED_NODE_IDS);
        if (jsonData) {
            const expandedNodesPerSite = JSON.parse(jsonData);
            if (expandedNodesPerSite.hasOwnProperty(key)) {
                return expandedNodesPerSite[key];
            }
        }

        return null;
    }

    clearPaging() {
        this.storage.setItem(KEYS.PAGING, JSON.stringify({}));
    }

    setPaging(key: string, paging: ItemPaging, reset: boolean = false) {
        let jsonData = this.storage.getItem(KEYS.PAGING);
        if (!jsonData) {
            jsonData = {};
        } else {
            jsonData = JSON.parse(jsonData);
        }

        if (!jsonData[key] || reset)
            jsonData[key] = {};

        if (paging) {
            for (const itemKey in paging) {
                if (paging.hasOwnProperty(itemKey)) {
                    jsonData[key][itemKey] = paging[itemKey];
                }
            }
        }

        this.storage.setItem(KEYS.PAGING, JSON.stringify(jsonData));
    }

    getPaging(key: string): ItemPaging {
        const jsonData = this.storage.getItem(KEYS.PAGING);
        if (jsonData) {
            const paging = JSON.parse(jsonData);
            if (paging.hasOwnProperty(key)) {
                return paging[key];
            }
        }

        return null;
    }

    setSiteCulture(siteId: string, culture: string): void {
        const siteCultures = JSON.parse(this.storage.getItem(KEYS.SITE_CULTURE)) || {};
        if (siteCultures[siteId] !== culture) {
            siteCultures[siteId] = culture;
            this.storage.setItem(KEYS.SITE_CULTURE, JSON.stringify(siteCultures));
        }
    }

    getSiteCulture(siteId: string): string {
        const siteCultures = JSON.parse(this.storage.getItem(KEYS.SITE_CULTURE));
        if (!siteCultures || !siteCultures[siteId]) {
            return null;
        }

        const currentSiteCulture = siteCultures[siteId];
        return currentSiteCulture;
    }

    clearCultureForSite(siteId: string): void {
        const culturesObj = this.storage.getItem(KEYS.SITE_CULTURE);
        if (!culturesObj) {
            return;
        }

        const siteCultures = JSON.parse(culturesObj);
        delete siteCultures[siteId];
        this.storage.setItem(KEYS.SITE_CULTURE, JSON.stringify(siteCultures));
    }

    getMobillePreviewBreakPoint(): number {
        const result = this.storage.getItem(KEYS.MOBILE_PREVIEW_WIDTH);
        const parsed = JSON.parse(result);

        if (parsed && parsed.width) {
            return parsed.width;
        }

        return null;
    }

    setMobillePreviewBreakPoint(width: number): void {
        if (width) {
            const data = JSON.stringify({ width: width });
            this.storage.setItem(KEYS.MOBILE_PREVIEW_WIDTH, data);
        }
    }

    static formatUrl(input: string): string {
        if (input) {
            let result = input.trim();

            while (result.endsWith(stringConstants.FORWARD_SLASH)) {
                result = result.substring(0, result.length - stringConstants.FORWARD_SLASH.length);
            }

            return result.trim() + stringConstants.FORWARD_SLASH;
        }

        return input;
    }
}
