import { InjectionToken, Injectable, Optional, Inject } from "@angular/core";
import { combineLatest, Observable, of, ReplaySubject } from "rxjs";
import { first, map, switchMap } from "rxjs/operators";
import { DataItem } from "../../interfaces";
import { EditLifecycleHookParam } from "./hook-types/edit.hook-types";
import { ListLifecycleHookParam } from "./hook-types/list.hook-types";

export const ITEM_HOOKS_PROVIDER_TOKEN = new InjectionToken("item_hooks_token");

const EMPTY_VALUE = {};

@Injectable()
export class CompositeItemHooksProvider implements ItemHooksProvider {

    constructor(@Optional() @Inject(ITEM_HOOKS_PROVIDER_TOKEN) private itemHooksProviders: Array<ItemHooksProvider>) {
    }

    onItemLoaded(item: DataItem): void {
        this.executeHooks(item, "onItemLoaded").pipe(first()).subscribe();
    }

    executeObservableHook<TSource, TParam>(eventSource: Observable<TSource>, hookName: keyof ItemHooksProvider, paramsProjection?: (source: TSource) => TParam) {
        return eventSource.pipe(
            switchMap(s => {
                const params = paramsProjection ? paramsProjection(s) : s;
                return this.executeHooks(params, hookName).pipe(map(() => s));
            })
        );
    }

    private executeHooks(param: any, hookName: keyof ItemHooksProvider): Observable<any> {
        if (this.itemHooksProviders === null) {
            return of(EMPTY_VALUE);
        }

        const res$: Observable<any>[] = this.itemHooksProviders
            .map(p => {
                const hookResult = p[hookName] && p[hookName](param);
                const result$ = new ReplaySubject<any>();

                // Emitting some value is required, because operators like combineLatest, switchMap etc. doesn't work on void observables.
                if (hookResult) {
                    hookResult.pipe(first()).subscribe(() => result$.next(EMPTY_VALUE));
                } else {
                    result$.next(EMPTY_VALUE);
                }

                return result$;
            });

        return combineLatest(res$);
    }
}

/**
 * A provider used for configuring the editor.
 * @ExposedInApi {ItemHooksProvider} ItemHooksProvider v1/item/item-hooks-provider.d.ts
 */
export interface ItemHooksProvider {
    onItemLoaded?(item: DataItem): void;

    onEditItemInitializing?(data: EditLifecycleHookParam): Observable<void>;

    onEditItemUnloading?(data: EditLifecycleHookParam): Observable<void>;

    onEditItemChanged?(data: EditLifecycleHookParam): Observable<void>;

    afterEditItemInit?(data: EditLifecycleHookParam): Observable<void>;

    onGridItemsInitializing?(data: ListLifecycleHookParam): Observable<void>;

    onGridItemsUnloading?(data: ListLifecycleHookParam): Observable<void>;

    onGridItemsChanged?(data: ListLifecycleHookParam): Observable<void>;

    afterGridInit?(data: ListLifecycleHookParam): Observable<void>;
}
