import { timer as observableTimer, Observable, ReplaySubject, Subscription } from "rxjs";

import { filter, skip } from "rxjs/operators";
import { Component, OnInit, Input } from "@angular/core";
import { FilterStore } from "./filter.store";
import { EntityData } from "../../../interfaces";
import { FiltersCountResult, Filter } from "./filter-interfaces";
import { LoadingContentState } from "../../../../../shared/rxjs-extensions/toLoadingState";
import { LOADING_TIME, DEBOUNCE_TIME, ROUTE_PARAMS } from "../../../../constants";
import { DynamicItemStore } from "../../../services/dynamic-item.store";
import { ActionEvent } from "../../../services/entity/action-buttons";
import { BULK_BATCH_COUNT } from "../../../services/operations/commands/bulk-command";
import { ActivatedRoute } from "@angular/router";
import { delayEmission } from "../../../../../shared/rxjs-extensions";
import { OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const MAX_DEBOUNCE_TIME: number = 5000;

@Component({
    selector: "sf-content-filter-count",
    templateUrl: "./content-filter-count.component.html"
})
export class ContentFilterCountComponent extends SfRxBase implements OnInit {

    @Input() entityData: EntityData;
    @Input() filter: Filter;
    @Input() loadFiltersCount: Observable<void>;
    filtersCountResult$: Observable<LoadingContentState<FiltersCountResult>>;

    private filterResult$ = new ReplaySubject<LoadingContentState<FiltersCountResult>>();
    private getFiltersSubscription: Subscription;

    constructor(private filterStore: FilterStore, private dynamicItemStore: DynamicItemStore, protected route: ActivatedRoute) {
        super();
        this.filtersCountResult$ = this.filterResult$.pipe(delayEmission(LOADING_TIME));
    }

    ngOnInit(): void {
        let timerSubscription: Subscription;
        let debounceTime = 0;
        let eventCount = 0;

        this.loadFilterCount(this.filter.name, this.entityData);
        const subscription = this.dynamicItemStore
            // we filter out the changes that are related to workflow operations only
            // edit takes place in a dialog or a separate route, so there is no need to refresh the items
            // they only need to be refreshed once the item changes state like publis, but then the operation
            // name will be publish and the items will refresh
            .getItemChanges().pipe(
                filter(change => change.action !== null && change.action !== ActionEvent.ReorderItems && change.action !== OPERATION_NAMES.edit))
            .subscribe(change => {
                if (timerSubscription)
                    timerSubscription.unsubscribe();

                eventCount++;

                // Increase debounce time at the end of every batch to avoid reload on every batch.
                if (eventCount !== 0 && eventCount % BULK_BATCH_COUNT === 0) {
                    debounceTime = MAX_DEBOUNCE_TIME;
                } else {
                    debounceTime = DEBOUNCE_TIME;
                }

                timerSubscription = observableTimer(debounceTime).subscribe(() => {
                    eventCount = 0;
                    this.loadFilterCount(this.filter.name, this.entityData);
                });
            });

        this.registerSubscription(subscription);

        const loadSubscription = this.loadFiltersCount.pipe(skip(1)).subscribe(x => this.loadFilterCount(this.filter.name, this.entityData));
        this.registerSubscription(loadSubscription);
    }

    get parentId(): string {
        return this.route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
    }

    private loadFilterCount(filterName: string, entityData: EntityData): void {
        if (this.getFiltersSubscription) {
            this.getFiltersSubscription.unsubscribe();
        }

        let parentIdPair: KeyValuePair = null;
        if (this.parentId) {
            parentIdPair = {
                key: entityData.metadata.parentIdProperty,
                value: this.parentId
            };
        }

        this.getFiltersSubscription = this.filterStore
            .getFiltersCount(entityData, this.filter.name, parentIdPair)
            .subscribe((r) => this.filterResult$.next(r));

        this.registerSubscription(this.getFiltersSubscription);
    }
}

export interface KeyValuePair {
    key: string;
    value: string;
}
