import { actionReducersMap, metaReducersMap } from "./app-store";
import { environment } from "../../../environments/environment";
import { environmentTypes } from "../../environment";
import { StoreDevtoolsModule } from "@ngrx/store-devtools";
import { StoreModule } from "@ngrx/store";
import { EffectsModule } from "@ngrx/effects";
import { SidebarEffects } from "./effects/effects.sidebar";
import { MobilePreviewEffects } from "./effects/effects.mobile-preview";
import { ColumnEffects } from "./effects/effects.columns";

/*
    for debugging and development services the second parameter here can be set to:
        {
            runtimeChecks: {
                strictStateImmutability: false,
                strictActionImmutability: false
            }
        }
    which removes the immutability of the store
    HOWEVER, in production the store should ALWAYS be IMMUTABLE
*/
const storeModule = StoreModule.forRoot(actionReducersMap, {metaReducers: metaReducersMap});

const effectsModule = EffectsModule.forRoot([SidebarEffects, MobilePreviewEffects, ColumnEffects]);

const modules = [
    storeModule,
    effectsModule
];

// React dev tools are only for developlent
// https://chrome.google.com/webstore/detail/redux-devtools/lmhkpmbekcpmknklioeibfkpmmfibljd
if (environment.env !== environmentTypes.integration && environment.env !== environmentTypes.production) {
    modules.push(StoreDevtoolsModule.instrument({ maxAge: 25, logOnly: false }));
}

export const STORE_MODULES = modules;
