import { Component, Input, OnInit, ViewChild } from "@angular/core";
import { select } from "@ngrx/store";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { first } from "rxjs/operators";
import { stringConstants } from "../../../../common-constants";
import { AppStore } from "../../../../services/store/app-store";
import { MOBILE_PREVIEW_SELECTORS } from "../../../../services/store/selectors/selectors.mobile-preview";

const STICKY_HEADER_HEIGHT: number = 46;

@Component({
    selector: "sf-mobile-preview",
    templateUrl: "./mobile-preview.component.html"
})
export class MobilePreviewComponent extends SfRxBase implements OnInit {
    @ViewChild("frame") frame: any;
    @Input() pagePreviewUrl: string;

    frameWidth: number;
    frameHeight: number = 0;
    showLoading = true;

    constructor(private store: AppStore) {
        super();
    }

    ngOnInit(): void {
        this.registerSubscription(this.store.pipe(first(), select(state => {
            this.frameWidth = state.mobilePreview.width;
        })).subscribe());

        this.registerSubscription(this.store.pipe(MOBILE_PREVIEW_SELECTORS.changeWidth)
            .subscribe(width => {
                this.frameWidth = width;

                if (this.isFrameReady()) {
                    this.frame.nativeElement.contentWindow.document.body.style.overflow = "hidden";
                }
            }));
    }

    onLoad() {
        this.calculateFrameHeight();

        if (this.frame && this.frame.nativeElement.contentWindow.document.head) {
            this.addRequiredStylesInsideFrame(this.frame.nativeElement.contentWindow.document.head);

            this.showLoading = false;
        }
    }

    onResize() {
        this.calculateFrameHeight();
    }

    private calculateFrameHeight() {
        if (this.isFrameReady()) {
            this.frameHeight = this.frame.nativeElement.contentWindow.document.body.scrollHeight + STICKY_HEADER_HEIGHT;
        }
    }

    private isFrameReady(): boolean {
        if (this.frame && this.frame.nativeElement.contentWindow.document.body) {
            return true;
        }

        return false;
    }

    private addRequiredStylesInsideFrame(head: HTMLHeadElement) {
        const styleTag: HTMLStyleElement = document.createElement("style");
        styleTag.appendChild(document.createTextNode(stringConstants.EMPTY_STRING));
        head.appendChild(styleTag);

        // if this is removed, the scrolbars in the iframe appear, when scaling down the
        // resizer, will cause a nasty flicker.
        styleTag.sheet.insertRule(`body { overflow: "hidden" }`);
        // this prevents a nasty bug where if a user navigates to a image, the iframe becomes
        // progressively bigger infinitely
        styleTag.sheet.insertRule(`img { pointer-events: none }`);
    }
}
