import { Component } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData, stringConstants } from "@progress/sitefinity-component-framework";
import { ReplaySubject } from "rxjs";
import { FieldRegistration } from "../../src/app/api";
import { EDITOR_SETTINGS_TEXT_AREA_ROWS_COUNT } from "../../src/app/modules/shared/services/config/backend-interface-settings-config-extender";
import { CompositeConfigExtender } from "../../src/app/modules/shared/services/config/composite-config-extender";
import { Button, CancelButton, ClickData, ClickResult, ConfirmButton, DEFAULT_URL_KEY, DeleteButton, DialogData, ModalWindowService } from "../../src/app/modules/shared/services/modal-window.service";
import { BasicEditorViewComponent } from "../../src/app/modules/widget-editor/basic-editor.component";
import { PropertyMetadata, SectionData, WidgetMetadata } from "../../src/app/modules/widget-editor/interfaces/widget-editor";
import { DIALOG_PROPERTIES_FOR_SPECIFIC_FIELD } from "../../src/app/modules/widget-editor/providers/fields/field-type-mapper";
import { cloneObject } from "../../src/app/utils";
import { VALIDATOR_NAMES } from "../common/validators";
import { FieldBase } from "../field-base";
import { SettingsBase } from "../field-settings-base";
import { StatusType } from "../field-status";

export const EDITOR_CUSTOM_SETTINGS_TEXT_AREA_ROWS_COUNT = 25;
// the command will be responsible for opening the dialog
@Component({
    selector: "sf-pencil-button",
    templateUrl: "./pencil-button-field.component.html"
})
export class PencilButtonComponent extends FieldBase {
    private editorComponent: BasicEditorViewComponent;
    private sections: SectionData[] = [];

    get dialogSettings() {
        return this.settings as PencilButtonSettings;
    }

    constructor(
        private modalService: ModalWindowService,
        private route: ActivatedRoute,
        private compositeConfigExtender: CompositeConfigExtender) {
        super();
    }

    onEditClick() {
        const componentData = this.initEditorComponent();
        this.showDialog(componentData);
    }

    private showDialog(componentData: ComponentData) {
        let buttons: Button[] = [];

        if (this.dialogSettings.dialogData && this.dialogSettings.dialogData.buttons.length) {
            this.dialogSettings.dialogData.buttons.forEach(button => {
                switch (button.type) {
                    case "delete":
                        buttons.push(new DeleteButton(button.title))
                        break;
                    case "confirm":
                        buttons.push(new ConfirmButton(button.title, (context: ClickData) => {
                            return this.onSaveClicked();
                        }))
                        break;
                    case "cancel":
                        buttons.push(new CancelButton(button.title))
                        break;
                }
            });
        } else {
            buttons = [
                new ConfirmButton("Save changes", (context: ClickData) => {
                    return this.onSaveClicked();
                }),
                new CancelButton("Cancel")
            ];
        }

        const dialogData = new DialogData(componentData, (context: ClosingContext) => { }, buttons, null);
        dialogData.heading = {
            title: this.dialogSettings.dialogData?.header ?? stringConstants.EMPTY_STRING,
            subTitle: this.dialogSettings.dialogData?.subTitle ?? stringConstants.EMPTY_STRING
        };

        const urlKey = this.dialogSettings.dialogData?.urlKey ?? DEFAULT_URL_KEY
        this.modalService.setMapping(dialogData, urlKey);

        const routeToOpen = this.route.outlet.includes("dialog") ? this.route.parent : this.route;
        this.modalService.show(urlKey, routeToOpen);
    }

    validate() {
        if (this.dialogSettings.required) {
            const currentValue = this.getValue();
            let hasValue = false;
            for (const key in currentValue) {
                if (Object.prototype.hasOwnProperty.call(currentValue, key)) {
                    const propValue = currentValue[key];
                    if (propValue) {
                        hasValue = true;
                        break;
                    }
                }
            }

            if (!hasValue) {
                const errors = {
                    [VALIDATOR_NAMES.REQUIRED]: true
                };

                this.emitStatus({ type: StatusType.Error, data: errors });
                return false;
            }
        }

        this.emitStatus({ type: StatusType.ErrorCleared });
        return true;
    }

    private initEditorComponent(): ComponentData {
        this.sections = [];
        this.sections.push({ Name: "", Title: null, Properties: (this.settings as PencilButtonSettings).typeChildProperties });

        const value = this.getValue() || this.getDialogDefaultValues(this.sections);
        const editorMetadata: WidgetMetadata = {
            propertyValues: value,
            propertyMetadata: this.sections,
            propertyMetadataFlat: [],
            propertyLocalizationMode: null,
            name: null,
            caption: null
        };

        const settingsForSpecificFields = this.compositeConfigExtender.getSettingsForSpecificFields(value);
        const customLinks = settingsForSpecificFields?.EditorSettings?.customLinks || {};

        const editorComponentData = {
            type: BasicEditorViewComponent,
            afterComponentInit: (component: BasicEditorViewComponent) => {
                component.initialize(editorMetadata);
                this.editorComponent = component;
            },
            properties: {
                context: {
                    heading: this.dialogSettings.dialogData.header,
                    isQuickEdit: true
                },
                shouldHaveTopPadding: false,
                shouldTextAreasBeResizable: true,
                settingsForSpecificFields: {
                    Configuration: {
                        rows: EDITOR_SETTINGS_TEXT_AREA_ROWS_COUNT,
                        showTitle: false,
                        customLinks
                    }
                }
            }
        };
        this.setDialogPropertiesForSpecificFields(editorComponentData);

        return editorComponentData;
    }

    private getDialogDefaultValues(sections: SectionData[]) {
        const defaultValues = {};
        sections.forEach((value: SectionData) => {
            value.Properties.forEach((property: PropertyMetadata) => {
                defaultValues[property.Name] = property.DefaultValue;
            });
        });
        return defaultValues;
    }

    private onSaveClicked(): ReplaySubject<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(0);
        const modifiedProperties = this.editorComponent.getModifiedProperties();
        const value = cloneObject(this.getValue() || this.getDialogDefaultValues(this.sections));
        modifiedProperties.forEach(property => {
            if (value && value.hasOwnProperty(property.Name)) {
                value[property.Name] = property.Value;
            }
        });

        this.editorComponent.editableFieldsComponent.validateAsync().subscribe((isValid: boolean) => {
            if (isValid) {
                this.writeValue(value);
                this.onChangeCallback(value);
                clickResult.next(new ClickResult(null, true, false, false));
            } else {
                clickResult.next(new ClickResult(null, false, false, false));
            }
        });

        return clickResult;
    }

    private setDialogPropertiesForSpecificFields(componentData: ComponentData) {
        const specificProperties = DIALOG_PROPERTIES_FOR_SPECIFIC_FIELD;
        const specificProperty = ((this.settings as PencilButtonSettings).typeChildProperties)[0].Name;
        const property = specificProperties.get(specificProperty);

        if (property && this.settings.key.startsWith(property["keyPrefix"])) {
            componentData.properties[property["prop"]] = property["value"];
        }
    }
}

export class PencilButtonSettings extends SettingsBase {
    public typeChildProperties: PropertyMetadata[];
    public dialogData: DialogMetadata;
    public initialValue: any;

    public init(metadata: any) {
        super.init(metadata);
        this.typeChildProperties = metadata['typeChildProperties'];
        this.look = "inline";
    }
}

export interface DialogMetadata {
    buttons: ButtonMetadata[];
    header: string;
    urlKey: string;
    subTitle: string;
}

export interface ButtonMetadata {
    type: string;
    title: string;
}

export const PENCIL_BUTTON_REGISTRY: FieldRegistration = {
    writeComponent: PencilButtonComponent,
    settingsType: PencilButtonSettings
};
