import { Inject, Injectable, Optional} from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { QUERY_PARAMS } from "../../../content/constants";
import { PropertyData } from "../../../widget-editor/interfaces/widget-editor";
import { ConfigExtender, CONFIG_EXTENDER_TOKEN } from "./config-extender";

const FORM_CLASSES = "-medium";

@Injectable()
export class CompositeConfigExtender {

    constructor(@Optional() @Inject(CONFIG_EXTENDER_TOKEN) private extenders: ConfigExtender[], private route: ActivatedRoute) {
    }

    getFormClasses(): string {
        const extender = this.getExtender();

        if (extender) {
            return extender.getFormClasses();
        }

        return FORM_CLASSES ;
    }

    modifyPropertyValuesBeforeSave(properties: PropertyData[]): void {
        const extender = this.getExtender();

        if (extender) {
            extender.modifyPropertyValuesBeforeSave(properties);
        }
    }

    getModifiedValuesForVisualization(configValues: { [key: string]: any }): { [key: string]: any } {
        const extender = this.getExtender();

        if (extender) {
           return extender.getModifiedValuesForVisualization(configValues);
        }
        
        return configValues;
    }

    getSettingsForSpecificFields(configValues: { [key: string]: any }) {
        const extender = this.getExtender();

        if (extender) {
            return extender.getSettingsForSpecificFields(configValues);
        }

        return {};
    }

    private getExtender(): ConfigExtender {
        const typeQueryParam = this.route.snapshot.queryParams[QUERY_PARAMS.TYPE];
        const extender = this.extenders.find(x => x.isSupportedType(typeQueryParam));
        return extender;
    }
}
