import { ClassProvider, Injectable } from "@angular/core";
import { CommandsData } from "../../../api";
import { OUTSIDE_MENU_MAX_ORDINAL } from "../../content/dynamic-modules/components/action-buttons.resolver";
import { OperationsTarget } from "../../content/dynamic-modules/services/operations/interfaces";
import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "../../content/dynamic-modules/services/operations/operations-filter";
import { Operation, OPERATION_NAMES, OPERATION_TITLES } from "../../shared/components/action-menu/operation.model";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";

const OPERATIONS_NOT_SUPPORTED_ON_EDIT: string[] = [OPERATION_NAMES.subscribe, OPERATION_NAMES.unsubscribe, OPERATION_NAMES.shareWith];
@Injectable()
export class FormsOperationsFilter implements OperationsFilter {
    filter(operations: Operation[], data: CommandsData): Operation[] {
        if (data.dataItem.metadata.setName === ENTITY_SET.FORMS) {
            const isEditOrCreate = data.target === OperationsTarget.Edit || data.target === OperationsTarget.Create;
            const isEditingPageContent = data.contextData.isEditingPageContent;
            if (isEditOrCreate && isEditingPageContent) {
                const editOperationIndex = operations.findIndex(o => o.Name === OPERATION_NAMES.edit);
                if (editOperationIndex > -1) {
                    const editOperation = operations[editOperationIndex];
                    editOperation.Title = OPERATION_TITLES.titleAndProperties;
                    editOperation.Ordinal = OUTSIDE_MENU_MAX_ORDINAL + 1;
                }

                return operations.filter(operation => OPERATIONS_NOT_SUPPORTED_ON_EDIT.indexOf(operation.Name) === -1);
            }

            if (data.target === OperationsTarget.List) {
                return operations.filter(operation => operation.Name !== OPERATION_NAMES.rules);
            }
        }

        return operations;
    }
}

export const FORMS_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: FormsOperationsFilter
};
