import { Component, OnInit, Input, Output, EventEmitter, ViewChild } from "@angular/core";
import { FieldSectionModel, FieldSectionSettings } from "../../../../services/fieldSection.model";
import { stringConstants, validationConstants } from "../../../../common-constants";
import { FieldModel } from "../../../../services/field.model";
import { CompositeFieldsProvider } from "../../../shared/fields-builder/providers/fields-provider";
import { createFieldModel } from "../../../shared/fields.constants";
import { FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { VALIDATION_REGEX, INSTRUCTIONAL_TEXT } from "../../../../../../fields/common/common-constants";
import { SHORT_TEXT_PLACEHOLDER } from "../../../../../../fields/short-text/short-text.constants";
import { PAGES_ENTITY_SET_NAME } from "../../services/page.resolver";
import { EditableFieldsComponent } from "../../../shared/fields-builder/components/editable-fields/editable-fields.component";

const WEB_ADDRESS_FIELDS_SECTION_NAME: string = "webAddressFieldsSection";
const WEB_ADDRESS_MODEL_PROPERTIES = {
    SELECTED_URL: "selectedUrl",
    OPEN_IN_NEW_WINDOW: "shouldOpenInNewWindow"
};
const WEB_ADDRESS_FIELD_TITLES = {
    SELECTED_URL: "URL",
    OPEN_IN_NEW_WINDOW: "Open this link in a new window"
};
const SELECTED_URL_EXAMPLE = "Example: http://weather.com";
const SELECTED_URL_PLACEHOLDER = "http://";
export const INVALID_URL = "invalidURL";

@Component({
    selector: "sf-web-address",
    templateUrl: "./web-address.component.html"
})
export class WebAddressComponent implements OnInit  {
    fieldsSections: FieldSectionModel[];

    @ViewChild("webAdressFields", { static: true }) webAdressFields: EditableFieldsComponent;

    @Output() fieldChange = new EventEmitter<any>();
    @Input() selectedUrl: string = stringConstants.EMPTY_STRING;
    @Input() shouldOpenInNewWindow: boolean = false;

    public selectedUrlModel: FieldModel;
    public shouldOpenInNewWindowModel: FieldModel;

    private entity;

    constructor(private fieldsProvider: CompositeFieldsProvider) {
        this.entity = {
            properties: {
                [WEB_ADDRESS_MODEL_PROPERTIES.SELECTED_URL]: {
                    [INSTRUCTIONAL_TEXT]: SELECTED_URL_EXAMPLE,
                    [SHORT_TEXT_PLACEHOLDER]: SELECTED_URL_PLACEHOLDER,
                    [VALIDATION_REGEX]: validationConstants.VALID_URL_PATTERN_MANDATORY_PROTOCOL
                },
                [WEB_ADDRESS_MODEL_PROPERTIES.OPEN_IN_NEW_WINDOW]: {}
            }
        };
    }

    ngOnInit(): void {
        const baseFieldsSection = this.initBaseFieldsSection();
        this.fieldsSections = [baseFieldsSection];
    }

    onFieldChange(event: any) {
        if (event.key === WEB_ADDRESS_MODEL_PROPERTIES.SELECTED_URL) {
            this.selectedUrl = event.value;
        } else if (event.key === WEB_ADDRESS_MODEL_PROPERTIES.OPEN_IN_NEW_WINDOW) {
            this.shouldOpenInNewWindow = event.value;
        }

        if (this.webAdressFields.valid()) {
            this.fieldChange.emit(event);
        } else {
            event.value = INVALID_URL;
            this.fieldChange.emit(event);
        }
    }

    private initBaseFieldsSection(): FieldSectionModel {
        const fields: FieldModel[] = this.getBaseFields();
        const sectionOptions: FieldSectionSettings = {
            isMain: true,
            isExpanded: false,
            insertHorizontalRule: true,
            title: stringConstants.EMPTY_STRING,
            name: WEB_ADDRESS_FIELDS_SECTION_NAME
        };

        const baseFieldsSection = new FieldSectionModel(sectionOptions);
        baseFieldsSection.fields = fields;

        return baseFieldsSection;
    }

    private getBaseFields(): FieldModel[] {
        this.selectedUrlModel = this.createField(FieldTypes.shortText, PAGES_ENTITY_SET_NAME, WEB_ADDRESS_MODEL_PROPERTIES.SELECTED_URL, this.selectedUrl, this.entity, WEB_ADDRESS_FIELD_TITLES.SELECTED_URL);
        this.shouldOpenInNewWindowModel = this.createField(FieldTypes.choiceYesNo, PAGES_ENTITY_SET_NAME, WEB_ADDRESS_MODEL_PROPERTIES.OPEN_IN_NEW_WINDOW, this.shouldOpenInNewWindow, this.entity, WEB_ADDRESS_FIELD_TITLES.OPEN_IN_NEW_WINDOW);
        this.shouldOpenInNewWindowModel.settings.showTitle = false;

        const fields: FieldModel[] = [this.selectedUrlModel, this.shouldOpenInNewWindowModel];

        return fields;
    }

    private createField(fieldType: string, typeName: string, propName: string, value: any, metadata: any = {}, propTitle?: string): FieldModel {
        return createFieldModel(this.fieldsProvider, typeName, fieldType, propName, value, metadata, propTitle);
    }
}

export class WebAddresModel {
    selectedUrl: string;
    shouldOpenInNewWindow: boolean;
}
