import { Injectable } from "@angular/core";
import { FieldTypes } from "../../fields-builder/services/fields-registry";
import { EVENT_PROPERTIES } from "./events.constants";
import { EVENT_ITEM_FULL_NAME } from "../../services/metadata/meta-data-constants";
import { CommonTweaksHandler, TweakInfo } from "../../services/common-tweaks-handler.service";
import { CustomTweaksHandler } from "../../services/custom-tweaks-handler.service";

@Injectable()
export class EventsTweaksHandler extends CommonTweaksHandler {
    canProcess(typeFullName: string): boolean {
        return typeFullName === EVENT_ITEM_FULL_NAME;
    }

    getTweakInfoMap(): TweakInfo[] {
        return  [
            {
                sectionName: "MainSection",
                fields: [EVENT_PROPERTIES.EVENT_START, EVENT_PROPERTIES.EVENT_END, EVENT_PROPERTIES.ALL_DAY_EVENT],
                fieldType: FieldTypes.eventTimeCompositeField
            }
        ];
    }
}

export const EVENTS_TWEAKS_HANDLER = { provide: CustomTweaksHandler, useClass: EventsTweaksHandler, multi: true };
