import { Component, Input, OnInit } from "@angular/core";
import { DataContextComponent, DataContext } from "../../models/data-context-component";

@Component({
    selector: "sf-text-field",
    template: "{{value}}"
})
// Since those components are designed to be shown in the dynamic (or static) lists I would revise their name.
export class TextFieldComponent implements OnInit, DataContextComponent {
    @Input() public context: DataContext;
    @Input() public propertyPath: string;

    public value: any;
    ngOnInit() {
        const dataItem = this.context.dataItem;
        const model = this.context.model;

        let evaledValue: string = dataItem.data[model.name];
        if (this.propertyPath) {
            evaledValue = this.getPropertyValue(evaledValue, this.propertyPath);
        }

        this.setCurrentValue(evaledValue);
    }

    protected getPropertyValue(data: any, propertyPath: string) {
        let propertyValue = data;
        if (propertyPath) {
            const propertyNames = propertyPath.split(".").filter(p => !!p);
            propertyNames.forEach(propertyName => {
                if (propertyValue) {
                    propertyValue = propertyValue[propertyName];
                }
            });
        }

        if (propertyValue instanceof Object) {
            return JSON.stringify(propertyValue);
        }

        return propertyValue;
    }

    private setCurrentValue(value: any) {
        if (value instanceof Object) {
            this.value = JSON.stringify(value);
        } else {
            this.value = value;
        }
    }
}
