import { Component, Inject, OnInit, ViewChild, ViewEncapsulation } from "@angular/core";
import { WINDOW_TOKEN } from "../../window.provider";
import { deepClone, hideSitefinityContent, showSitefinityContent } from "../../utils";
import { ComponentData, SfDynamicComponentLoaderComponent, SfRxBase } from "@progress/sitefinity-component-framework";
import { AuthService } from "../../modules/auth/auth.service";
import { Router } from "@angular/router";
import { HeaderMenuService } from "../../modules/shared/services/header-menu.service";
import { CanCloseModal, ClosingContextType, DialogData } from "../../modules/shared/services/modal-window.service";
import { ActionMenuOptions } from "../../modules/shared/components/action-menu/action-menu-model";

@Component({
    selector: "sf-empty",
    templateUrl: "./integrated-empty.component.html",
    styleUrls: ["./../../modules/shared/components/modal-window/modal-window.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class IntegratedEmptyComponent extends SfRxBase implements OnInit {
    componentData: ComponentData;
    title: string;
    dialogData: DialogData;
    states: DialogData[] = [];
    areHeadingButtonsVisible: boolean = false;
    @ViewChild("mainContentLoader", { static: false }) componentLoader: SfDynamicComponentLoaderComponent;

    public dropDownMenuOptions: ActionMenuOptions;
    public areUserDialogsShown = false;

    constructor(@Inject(WINDOW_TOKEN) private windowProvider: Window,
                private service: AuthService,
                private router: Router,
                private headerMenuService: HeaderMenuService) {
        super();
        this.dropDownMenuOptions = new ActionMenuOptions(undefined, undefined, true);
    }

    ngOnInit() {
        const userMenuServiceSubscription = this.headerMenuService.onUserDialogOpen.subscribe((dialogData: DialogData) => this.showDialogContent(dialogData));
        this.registerSubscription(userMenuServiceSubscription);
        // This login is intentionally left here. When we are in integrated mode
        // and there is an angular 1.x app on the page, the angular 1.x routing
        // logic conflicts with the routing logic in the AdminApp

        // The scenario:
        // User navigates to /Adminstration/Translations
        // Angular 2.x (AdminApp) runs the guards which return an observable that is awaited ('log in' in this case)
        // Angular 1.x navigates to /Administration/Translations/#marked
        // Angular 2.x resolves the guards from before a little bit after Angular 1.x does the navigation
        // Angular 2.x navigates back to /Adminstration/Translations as it does not enjoy random hashes appended

        // So in summary the routing logic of the Angular 2.x app must resolve before the Angular 1.x app
        // and thus Angular 2.x will not attempt to navigate
        this.service.tryLogIn(this.router.routerState.snapshot.url).subscribe();
    }

    onCloseClicked() {
        const canCloseModal = this.componentLoader.currentInstance as CanCloseModal;
        if (canCloseModal && canCloseModal.canCloseCallback && !canCloseModal.canCloseCallback(null)) {
            return;
        }

        this.destroyCurrentComponentData();
        this.onDialogClosed();

        if (this.states.length > 1) {
            this.states.pop();
            this.showDialogContent(this.states.pop());
            return;
        }

        this.states = [];
        showSitefinityContent(this.windowProvider.document);
        this.areUserDialogsShown = false;
    }

    showDialogContent(dialogData: DialogData) {
        this.destroyCurrentComponentData();
        this.states.push(deepClone(dialogData));
        this.dialogData = dialogData;
        this.componentData = dialogData.componentData;

        if (dialogData.heading) {
            this.title = dialogData.heading.title;
        }

        if (dialogData.showButtonsOnInit === true) {
            this.areHeadingButtonsVisible = true;
        }

        //// We are not opening a modal window with the preference component due to a not supported case of the Angular Routing
        //// Wild cards routes with AUX routes is not supported combination.
        hideSitefinityContent(this.windowProvider.document);
        this.areUserDialogsShown = true;
    }

    private destroyCurrentComponentData(): void {
        if (this.componentLoader && this.componentData) {
            this.componentLoader.destroy(this.componentData);
        }
    }

    private onDialogClosed() {
        if (this.dialogData && this.dialogData.doneCallback) {
            const context = {
                type: ClosingContextType.CloseClicked,
                data: null,
                component: null
            };
            this.dialogData.doneCallback(context);
        }
    }
}
