import { Component, HostBinding, Input, OnInit, ViewEncapsulation } from "@angular/core";
import { CLASS_ZONE_LABEL } from "../../../services/document-enhancer.constants";

const WIDGET_LABEL_DEFAULT_CLASS = "sf-widget-label";

@Component({
    selector: "sf-widget-label",
    templateUrl: "./widget-label.component.html",
    styleUrls: ["./widget-label.component.scss"],
    encapsulation: ViewEncapsulation.ShadowDom
})
export class WidgetLabelComponent implements OnInit {
    @Input() label: string;
    @Input() tooltip: string;
    @Input() hideDraggableIcon: boolean;
    @Input() look: string;
    @HostBinding("class") classes = CLASS_ZONE_LABEL;

    cssClasses: string;

    ngOnInit() {
        this.cssClasses = this.generateCssClassList();
    }

    private generateCssClassList(): string {
        let cls = WIDGET_LABEL_DEFAULT_CLASS;

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (!this.hideDraggableIcon) {
            cls += " -draggable";
        }

        return cls;
    }
}
