import { EditPageComponent } from "./components/edit-page/edit-page.component";
import { Route, ResolveData } from "@angular/router";
import { MetadataStoreResolver } from "../shared/services/metadata/meta-data-store.resolver";
import { UserDataStoreResolver } from "../shared/services/metadata/user-data-store.resolver";
import { SiteDataStoreResolver } from "../shared/services/metadata/site-data-store.resolver";
import { SiteTitleResolver } from "../shared/services/site-title.resolver";
import { ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { stringConstants } from "../../common-constants";
import { DynamicItemIndexComponent } from "../content/dynamic-modules/components/dynamic-item-index.component";
import { BackendTweaksGridResolver } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks-grid.resolver";
import { DynamicItemsResolver } from "../content/dynamic-modules/components/dynamic-items.resolver";
import { SiteTitleDynamicResolver } from "../shared/services/site-title.dynamic.resolver";
import { HomeComponent } from "../shared/components/navigation/home/home.component";
import { DynamicItemRouterComponent } from "../content/dynamic-modules/components/router/dynamic-item-router.component";
import { ContentComponent } from "../content/content.component";
import { PageResolver } from "./services/page.resolver";
import { ModalWindowComponent } from "../shared/components/modal-window/modal-window.component";
import { ProviderRouteGuard } from "../../provider.route-guard";
import { ZoneEditorComponent } from "./components/zone-editor/zone-editor.component";
import { DynamicItemResolver } from "../content/dynamic-modules/services/entity/dynamic-item.resolver";
import { ZoneEditorCanDeactivate } from "./components/zone-editor/guards/can-deactivate.guard";
import { EditPageTemplateComponent } from "./components/edit-page/edit-page-template";
import { ContentTypeGuard } from "../content/content-type.guard";

const RESOLVERS: ResolveData = {
    metaStore: MetadataStoreResolver,
    userDataStore: UserDataStoreResolver,
    siteDataStore: SiteDataStoreResolver,
    siteTitle: SiteTitleResolver
};

const MENU_OUTLET_ROUTES: Route[] = [
    {
        path: ROUTE_PATHS_NO_PREFIX.MENU_HOME,
        component: HomeComponent,
        outlet: ROUTE_PATHS_NO_PREFIX.MENU_OUTLET,
        resolve: {
            siteTitle: SiteTitleResolver
        },
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.MENU_HOME
            }
        }
    },
    {
        path: ROUTE_PATHS_NO_PREFIX.CONTENT,
        component: ContentComponent,
        outlet: ROUTE_PATHS_NO_PREFIX.MENU_OUTLET,
        resolve: {
            siteTitle: SiteTitleResolver
        },
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.CONTENT
            }
        }
    },
    {
        path: "confirm/:name",
        component: ModalWindowComponent,
        outlet: "dialog"
    }
];

const BASE_ROUTE: Route[] = [{
        path: stringConstants.EMPTY_STRING,
        component: DynamicItemIndexComponent,
        resolve: {
            gridResolved: BackendTweaksGridResolver,
            dynamicItems: DynamicItemsResolver,
            siteTitle: SiteTitleDynamicResolver
        },
        canActivate: [ProviderRouteGuard],
        runGuardsAndResolvers: "paramsOrQueryParamsChange"
    },
    ...MENU_OUTLET_ROUTES
];

export const PAGES_ROUTES: Route[] = [{
    path: ROUTE_PATHS_NO_PREFIX.PAGES,
    component: DynamicItemRouterComponent,
    children: [
        ...BASE_ROUTE,
        {
            path: "sfedit/:id",
            component: ZoneEditorComponent,
            canActivate: [DynamicItemResolver],
            canDeactivate: [ZoneEditorCanDeactivate],
            resolve: {
                itemData: DynamicItemResolver
            },
            runGuardsAndResolvers: "paramsOrQueryParamsChange",
            children: [
                {
                    path: "confirm/:name",
                    component: ModalWindowComponent,
                    outlet: "dialog"
                }
            ]
        },
        {
            // pages can have multipart URL like '/my/test/page' hence '/my/test/page/Action/Edit/en'
            // guard is used to serve only action edit route
            path: "**",
            component: EditPageComponent,
            canActivate: [
                PageResolver
            ],
            resolve: {
                itemData: PageResolver
             }
        },
        {
            path: "confirm/:name",
            component: ModalWindowComponent,
            outlet: "dialog"
        }
    ],
    resolve: RESOLVERS,
    canActivate: [ContentTypeGuard],
    data: {
        animation: {
            value: ROUTE_PATHS_NO_PREFIX.PAGES
        },
        dynamicTypeName: ROUTE_PATHS_NO_PREFIX.PAGES
    }
}];

export const TEMPLATES_ROUTES: Route[] = [
    {
        path: ROUTE_PATHS_NO_PREFIX.TEMPLATES,
        component: DynamicItemRouterComponent,
        children: [
            ...BASE_ROUTE,
            {
                path: "sfedit/:id",
                component: ZoneEditorComponent,
                canActivate: [DynamicItemResolver],
                canDeactivate: [ZoneEditorCanDeactivate],
                resolve: {
                    itemData: DynamicItemResolver
                },
                runGuardsAndResolvers: "paramsOrQueryParamsChange"
            },
            {
                path: `${ROUTE_PATHS_NO_PREFIX.TEMPLATE}/:id`,
                component: EditPageTemplateComponent,
                resolve: {
                    itemData: DynamicItemResolver
                }
            },
            {
                path: `${ROUTE_PATHS_NO_PREFIX.TEMPLATE}/:id/:culture`,
                component: EditPageTemplateComponent,
                resolve: {
                    itemData: DynamicItemResolver
                }
            }
        ],
        resolve: RESOLVERS,
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.PAGES
            },
            dynamicTypeName: ROUTE_PATHS_NO_PREFIX.TEMPLATES
        }
    }
];

export const PRESETS_ROUTES: Route[] = [
    {
        path: ROUTE_PATHS_NO_PREFIX.PRESETS,
        component: DynamicItemRouterComponent,
        children: [
            ...BASE_ROUTE,
            {
                path: "confirm/:name",
                component: ModalWindowComponent,
                outlet: "dialog"
            }
        ],
        resolve: RESOLVERS,
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.PAGES
            },
            dynamicTypeName: ROUTE_PATHS_NO_PREFIX.PRESETS
        }
    }
];

