import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Injectable } from "@angular/core";
import { Properties } from "../../shared/fields.constants";
import { FieldBase } from "../../../../../fields/field-base";
import { ChoiceComponent } from "../../../../../fields/choice/choice.component";
import { ComplexComponent } from "../providers/fields/complex/complex.component";

@Injectable()
export class SearchWidgetFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === Properties.SEARCH_INDEX) {
            SearchWidgetFieldsChangeService.processSelectedItemsFieldChange(changedValue, fields.map(x => x.currentInstance));
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === "SitefinitySearchBox";
    }

    static processSelectedItemsFieldChange(changedValue: any, fields: FieldBase[]): boolean {
        const scoringProfileField = this.getScoringProfileField(fields);
        
        if (scoringProfileField) {
            const scoringParametersField = this.getScoringParametersField(fields);
            if (scoringParametersField) {
                scoringParametersField.writeValue(null);
            }

            if (changedValue) {
                const serviceUrl = scoringProfileField.settings.choiceServiceUrl;
                const choiceServiceCallParameters = scoringProfileField.settings.choiceServiceCallParameters ? JSON.parse(scoringProfileField.settings.choiceServiceCallParameters) : null;
                if (choiceServiceCallParameters) {
                    const key = Object.keys(choiceServiceCallParameters[0])[0];
                    const regexValue = new RegExp("\\(" + key + "=(.+?)\\)");
                    const newServiceUrl = serviceUrl.replace(choiceServiceCallParameters[0][key], changedValue).replace(regexValue, `(${key}='${changedValue}')`);
                    scoringProfileField.settings.choiceServiceUrl = newServiceUrl;
                    scoringProfileField.reloadChoices();
                    return true;
                }

                return false;
            } else if (!changedValue) {
                scoringProfileField.clearChoices(true);
                scoringProfileField.writeValue(null);

                return false;
            }
            
        }

        return false;
    }

    private static getScoringProfileField(fields: FieldBase[]): ChoiceComponent {
        const field = fields.find(x => x.settings.key === Properties.SCORING_PROFILE);
        if (field && field instanceof ChoiceComponent) {
            return field;
        }

        return null;
    }

    private static getScoringParametersField(fields: FieldBase[]): ComplexComponent {
        const field = fields.find(x => x.settings.key === Properties.SCORING_PARAMETERS);
        if (field && field instanceof ComplexComponent) {
            return field;
        }

        return null;
    }
}

export const SEARCH_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: SearchWidgetFieldsChangeService,
    multi: true
};
