import { MetadataStore, MediaEntity } from "./../../shared/services/metadata/meta-data.store";
import { TreeNode } from "@circlon/angular-tree-component";
import { ActivatedRoute } from "@angular/router";
import { Component, OnInit, AfterViewInit, EventEmitter, Output, Input, Renderer2, ElementRef, Inject } from "@angular/core";
import { RelatedDataComponent } from "./../../../../../fields/related-data/related-data.component";
import { BaseServiceInfo } from "../../../../../fields/services/base.service";
import { ModalWindowService, DialogData } from "../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { FilePickerComponent, FILE_PICKER } from "../file-picker.component";
import { MEDIA_CONTENT_TYPES } from "../media-content.types";
import { getFormattedTypeName, cloneObject } from "../../../utils";
import { FilePickerViewMode } from "../file-picker-view-mode";
import { ACTIONS, FILTER_TYPES } from "../../content/constants";
import { stringConstants } from "../../../common-constants";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { map } from "rxjs/operators";
import { DataItem, EntityData, FieldWithLimitations } from "../../content/dynamic-modules/interfaces";
import { ContentFilterService } from "../../shared/services/content-filter.service";
import { SiteDataStore } from "../../shared/services/metadata/site-data.store";
import { RelatedDataSettings } from "../../../../../fields/related-data/related-data.settings";
import { EditNavigationService } from "../../shared/services/edit-navigation.service";
import { UrlService } from "../../../services/url.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { MediaSettings } from "../media/media.settings";
import { Settings } from "../../shared/services/settings.service";

export const FILE_SELECT = "fileSelect";

const RECENT_ITEMS_COUNT: number = 5;

@Component({
    selector: "sf-file-tree",
    templateUrl: "./../../../../../fields/related-data/related-data.component.html"
})
export class FileTreeComponent extends RelatedDataComponent implements OnInit, AfterViewInit {
    get items() {
        return this.value;
    }

    @Input() set items(val) {
        this.value = val;
    }
    @Input() mediaEntityData: EntityData;
    @Input() fieldName: string;
    @Input() multiple: boolean = false;
    @Input() useOnlyUploadMode?: boolean;
    @Input() useOnlySelectMode?: boolean;
    @Input() targetLibraryId?: string;
    @Input() sourceLibraryId?: string;
    @Input() canRelateDamAssets: boolean = false;

    @Output() onItemsAdd: EventEmitter<any> = new EventEmitter<any>();
    @Output() onItemsRemove: EventEmitter<any> = new EventEmitter<any>();
    @Output() onItemsChange: EventEmitter<any> = new EventEmitter<any>();
    @Output() onFileUploadRetry: EventEmitter<any> = new EventEmitter<any>();
    @Output() reorderNodes: EventEmitter<any> = new EventEmitter<any>();

    private mediaEntity: MediaEntity;
    private originalSettings: MediaSettings;
    private enableDamPicker: boolean = false;

    constructor(dynamicService: DynamicItemService,
                modalService: ModalWindowService,
                route: ActivatedRoute,
                siteDataStore: SiteDataStore,
                metadataStore: MetadataStore,
                renderer: Renderer2,
                element: ElementRef,
                contentFilterService: ContentFilterService,
                @Inject(WINDOW_TOKEN) window: Window,
                urlService: UrlService,
                editNavigationService: EditNavigationService,
                settingsService: Settings
                ) {
        super(dynamicService, modalService, route, siteDataStore, metadataStore, renderer, element, contentFilterService, window, urlService, editNavigationService, settingsService);
    }

    protected getActionLinks() {
        const result = [];

        if (!this.useOnlyUploadMode) {
            result.push({
                isLink: true,
                Title: `Show all ${this.displayNames.plural}`,
                action: "openFilePicker"
            });
        }

        if (this.settings.allowCreate && !this.useOnlySelectMode) {
            result.push({
                isLink: true,
                Title: `Upload ${getFormattedTypeName(this.displayNames, this.settings.allowMultiple, true)}`,
                action: "openFileUpload"
            });
        }

        return result;
    }

    ngOnInit() {
        this.mediaEntity = this.mediaEntityData.metadata as MediaEntity;
        this.initializeTree();

        super.ngOnInit();
        this.enableDamPicker = this.canRelateDamAssets && this.mediaEntityData.metadata.isDamEnabled;
    }

    ngAfterViewInit() {
        this.update();
    }

    onToggleAddControl(isAddingItem: boolean = false, isFocusOut: boolean = false) {
        if (this.enableDamPicker && isAddingItem) {
            this.openFilePicker();
        } else if (this.useOnlyUploadMode) {
            this.openFileUpload();
        } else {
            super.onToggleAddControl(isAddingItem, isFocusOut);
        }
    }

    onNewItemSelected(item: any): any {
        const data = super.onNewItemSelected(item);
        if (data) {
            this.onItemsAdd.emit([data]);
        }

        return data;
    }

    onRemove(item?: TreeNode): any {
        const data = super.onRemove(item);
        if (data) {
            this.onItemsRemove.emit([data]);
        }

        return data;
    }

    openFilePicker() {
        this.openDialog(FilePickerViewMode.Select);
    }

    openFileUpload() {
        this.openDialog(null);
    }

    onReorderNodes(reorderedNodes: any) {
        this.reorderNodes.emit(reorderedNodes);
    }

    protected getRecentRelatedData(value: any[]): void {
        if (this.sourceLibraryId) {
            const fallbackProperties = this.fallbackProperties.join(",");
            const action = `documents/Default.DocumentsRecursiveSearch(rootLibraryId=${this.sourceLibraryId})?$top=${RECENT_ITEMS_COUNT}&$search=${this.searchTerm || ""}&sf_culture=${this.mediaEntityData.culture}&sf_fallback_prop_names=${fallbackProperties}`;
            this.dynamicService.executeUnboundFunction<any>(action).pipe(
                map(result => {
                    const dataItems = result.value.map((item) => {
                        return DataItem.from(item, this.relatedEntityData.metadata, this.settings.provider, this.settings.culture);
                    });

                    const actionLinks = this.getActionLinks();
                    const items = dataItems.map(item => this.cloneAndAddFieldsToDataItem(item)).concat(actionLinks);
                    this.addItemsToRecentItems(items);
                })
            ).subscribe();
        } else {
            super.getRecentRelatedData(value);
        }
    }

    protected createBaseServiceInfo(): BaseServiceInfo {
        const info: BaseServiceInfo = super.createBaseServiceInfo();

        if (this.mediaEntity && this.mediaEntity.mediaFilterEnabled) {
            const extensions = this.mediaEntity.acceptableFileTypes.map(fileType => `${stringConstants.DOT}${fileType}`);
            info.action = ACTIONS.FILTER(`${FILTER_TYPES.EXTENSIONS}${stringConstants.COMMA}${extensions.join(stringConstants.COMMA)}`);
            info.culture = this.mediaEntityData.culture;
        }

        return info;
    }

    protected addItemsToRecentItems(items: any[]) {
        if (this.mediaEntity && (this.mediaEntity.maxSize || this.mediaEntity.acceptableFileTypes?.length > 0)) {
            items.map(item => {
                this.configureItemSelection(item);
           });
        }

        super.addItemsToRecentItems(items);
    }

    onViewNodeFunk(node: TreeNode): void {
        const dataItem = DataItem.from(node.data, this._relatedDataEntity, this.settings.provider, this.settings.culture);
        const limitations: FieldWithLimitations = {
            filedName: this.settings.key,
            settings: {
                allowedFileExtensions: this.originalSettings.acceptableFileTypes,
                maximumAllowedSize: this.originalSettings.maxSize,
                acceptableMediaTypes: this.originalSettings.acceptableMediaTypes
            }
        };

        this.editNavigationService.openDialogForRelatedDataAndLoadFieldData(this.value.map(x => x.Id), dataItem, this.route, limitations, false, null).subscribe((data) => {
            this.writeValue(data);
            this.onItemsChange.emit(data);
        });
    }

    private configureItemSelection(item: any) {
        if (!this.mediaEntity) {
            return;
        }

        item.isSelectionDisabled = false;

        if (this.mediaEntity.maxSize) {
            const isOverSizeLimit = item.TotalSize > this.mediaEntity.maxSize;
            if (isOverSizeLimit) {
                item.isSelectionDisabled = true;
                return;
            }
        }

        if (this.mediaEntity.acceptableFileTypes?.length > 0 && item.Extension) {
            const isDisallowedType =  this.mediaEntity.acceptableFileTypes.indexOf(item.Extension.replace(stringConstants.DOT, stringConstants.EMPTY_STRING)) < 0;
            if (isDisallowedType) {
                item.isSelectionDisabled = true;
                return;
            }
        }
    }

    private openDialog(initialViewMode: FilePickerViewMode) {
        const componentData: ComponentData = {
            type: FilePickerComponent,
            afterComponentInit: (component: FilePickerComponent) => {
                component.multiple = this.multiple;
                component.value = this.value ? this.value.slice(0).map(x => DataItem.fromEntityData(x, this.mediaEntityData)) : [];
                component.name = this.fieldName;
                component.mediaEntityData = { metadata: this.mediaEntityData.metadata.clone(), provider: this.mediaEntityData.provider, culture: this.mediaEntityData.culture };
                component.allowCreate = this.settings.allowCreate;
                component.initialViewMode = this.getFilePickerComponentInitialViewMode(initialViewMode);
                component.useOnlySelectMode = this.useOnlySelectMode;
                component.sourceLibraryId = this.sourceLibraryId;
                component.targetLibraryId = this.targetLibraryId;
            },
            properties: {
                enableDamPicker: this.enableDamPicker
            }
        };

        componentData.properties.showProviderSelector = !!this.allItemsTabType;
        const dialogData = new DialogData(componentData, (result) => {
            if (result && result.data) {
                const data = Array.isArray(result.data) ? result.data.map(x => cloneObject(x.data)) : [cloneObject(result.data.data)];
                if (!this.multiple) {
                    this.value.length = 0;
                }
                this.value = this.value.concat(data);
                if (initialViewMode === FilePickerViewMode.Select) {
                    this.onItemsChange.emit(data);
                } else {
                    this.onItemsAdd.emit(data);
                }
            }
        }, [], "-prompt");

        this.modalService.setMapping(dialogData, FILE_PICKER);
        this.modalService.open(this.route, FILE_PICKER);
    }

    private update() {
        this.isAddButtonVisible = true;

        this.tree.updateTreeModel();
    }

    private initializeTree() {
        this.originalSettings = this.settings as any;
        let settings = new RelatedDataSettings(MEDIA_CONTENT_TYPES.document.single.toLowerCase(), false);
        settings = Object.assign(settings, this.settings);
        settings.type = MEDIA_CONTENT_TYPES.document.plural;
        settings.allowMultiple = this.multiple;
        this.displayNames = {
            plural: MEDIA_CONTENT_TYPES.document.plural.toLowerCase(),
            singular: MEDIA_CONTENT_TYPES.document.single.toLowerCase()
        };
        settings.provider = this.settings.provider;
        settings.allowCreate = this.settings.allowCreate;
        settings.culture = this.settings.culture;
        this.settings = settings;

        this.treeConfig = this.treeConfig || {
            drag: this.multiple,
            status: true,
            deletion: this.settings.allowRemove,
            noSelection: true,
            clickable: true
        };
    }

    private getFilePickerComponentInitialViewMode(initialDesiredViewMode: FilePickerViewMode): FilePickerViewMode {
        let result: FilePickerViewMode = initialDesiredViewMode;
        const isSelectMode = !this.settings.allowCreate || this.useOnlySelectMode;
        const isUploadMode = this.settings.allowCreate && this.useOnlyUploadMode;

        if (isSelectMode) {
            result = FilePickerViewMode.Select;
        } else if (isUploadMode) {
            result = FilePickerViewMode.Upload;
        }

        return result;
    }
}
