import { Component, OnInit } from "@angular/core";
import { FieldRegistration } from "../../src/app/modules/shared/fields-builder/services/fields-registry";
import { VALIDATOR_MESSAGES } from "../common/validators/validators.constants";
import { createValueAccessor, FieldBase } from "../field-base";
import { StatusType } from "../field-status";
import { RangeSettings } from "./range-settings";

export const INVALID_RANGE_ERROR = "Invalid range";
@Component({
    selector: "sf-range",
    templateUrl: "./range.component.html",
    providers: [createValueAccessor(RangeComponent)]
})

export class RangeComponent extends FieldBase<RangeSettings, RangeValue> implements OnInit {
    minFieldValue?: number;
    maxFieldValue?: number;
    suffix: string;

    ngOnInit(): void {
        this.suffix = this.settings.suffixValue;
    }

    onMinInput(value: string) {
        const currentValue = this.getValue();
        const valueToSet: number = parseInt(value);
        this.writeValue({
            Min: valueToSet,
            Max: currentValue ? currentValue.Max : null
        });
    }

    onMaxInput(value: string) {
        const currentValue = this.getValue();
        const valueToSet: number = parseInt(value);
        this.writeValue({
            Min: currentValue ? currentValue.Min : null,
            Max: valueToSet
        });
    }

    writeValue(value) {
        if (value) {
            this.minFieldValue = value.Min;
            this.maxFieldValue = value.Max;
        }

        super.writeValue(value);
    }

    validate() {
        const currentValue = this.getValue();
        const hasMinAndMax = currentValue && currentValue.Min !== null && currentValue.Max !== null;
        if (hasMinAndMax && currentValue.Max < currentValue.Min) {
            const errors = {
                [VALIDATOR_MESSAGES.CUSTOM_ERRORS]: INVALID_RANGE_ERROR
            };

            this.emitStatus({ type: StatusType.Error, data: errors });
            return false;
        }

        this.emitStatus({ type: StatusType.ErrorCleared });
        return true;
    }
}

export class RangeValue {
    Min: number;
    Max: number;
}

export const RANGE_REGISTRY: FieldRegistration = {
    writeComponent: RangeComponent,
    readComponent: RangeComponent,
    settingsType: RangeSettings
};
