import { Component } from "@angular/core";
import { Settings } from "../../services/settings.service";
import { ROUTE_PATHS } from "../../../../constants/route-paths";
import { ActivatedRoute } from "@angular/router";
import { MetadataStore } from "../../services/metadata/meta-data.store";
import { ReplaySubject, Subject } from "rxjs";
import { DataItem } from "../../../../api";
import { UrlService } from "../../../../services/url.service";

export const NO_PREVIEW_URL = `${ROUTE_PATHS.ROOT_PREFIX}/no-preview`;
export const CONTENT_TYPE_QUERY_PARAM = "contentType";
@Component({
    selector: "sf-no-preview",
    templateUrl: "./no-preview.component.html",
    styleUrls: ["./no-preview.component.scss"]
})
export class NoPreviewComponent {
    pagesUrl: string;
    messages: Subject<Messages> = new ReplaySubject();

    constructor(settings: Settings, route: ActivatedRoute, metadataStore: MetadataStore) {
        this.pagesUrl = `${settings.url}Sitefinity/Pages`;
        const genericContentTypeText = "content type";
        const contentType = route.snapshot.queryParams["contentType"];
        if (contentType) {
            metadataStore.initialize().subscribe((container) => {
                const entity = container.entitiesByFullTypeName[contentType];
                if (entity) {
                    this.messages.next(this.getMessages(entity.singularName.toLowerCase()));
                } else {
                    this.messages.next(this.getMessages(genericContentTypeText));
                }
            });
        } else {
            this.messages.next(this.getMessages(genericContentTypeText));
        }
    }

    public static getPreviewUrl(urlService: UrlService, dataItem?: DataItem) {
        let noPreviewUrl = urlService.getAbsoluteUrl(NO_PREVIEW_URL);
        if (dataItem) {
            noPreviewUrl += `?${CONTENT_TYPE_QUERY_PARAM}=${dataItem.metadata.typeFullName}`;
        }

        return noPreviewUrl;
    }

    private getMessages(contentType: string): Messages {
        return {
            description: `There are no pages set to display this ${contentType}. To enable preview:`,
            secondStep: `On a page, drop a widget displaying this ${contentType}`
        };
    }
}

interface Messages {
    description: string;
    secondStep: string;
}
