import { Injectable } from "@angular/core";
import { MediaData } from "./media-data";
import { MEDIA_TYPES, ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { ImageData } from "./image-data";
import { VideoData } from "./video-data";
import { DocumentData } from "./document-data";
import { MetadataStore, MediaEntity } from "../../../shared/services/metadata/meta-data.store";
import { EntityData } from "../../../content/dynamic-modules/interfaces";

@Injectable()
export class MediaDataFactory {
    constructor(private metadataStore: MetadataStore) {
    }

    create(type: string, provider: string,
           culture: string,
           acceptableMediaTypes: Array<string>,
           acceptableFileTypes: Array<string>,
           mediaFilterEnabled: boolean,
           maxSize: number): MediaData {
        let ret: MediaData = null;
        let mediaEntityData: EntityData = null;
        switch (type) {
            case MEDIA_TYPES.IMAGE:
                mediaEntityData = {
                    metadata: this.metadataStore.getEntity(ENTITY_SET.IMAGES).clone(),
                    provider,
                    culture
                };

                ret = new ImageData(mediaEntityData);
                break;
            case MEDIA_TYPES.VIDEO:
                mediaEntityData = {
                    metadata: this.metadataStore.getEntity(ENTITY_SET.VIDEOS).clone(),
                    provider,
                    culture
                };
                ret = new VideoData(mediaEntityData);
                break;
            case MEDIA_TYPES.DOCUMENT:
                mediaEntityData = {
                    metadata: this.metadataStore.getEntity(ENTITY_SET.DOCUMENTS).clone(),
                    provider,
                    culture
                };
                ret = new DocumentData(mediaEntityData);
                break;
        }

        (ret.mediaEntityData.metadata as MediaEntity).mediaFilterEnabled = mediaFilterEnabled;
        (ret.mediaEntityData.metadata as MediaEntity).acceptableMediaTypes = acceptableMediaTypes || [];
        (ret.mediaEntityData.metadata as MediaEntity).acceptableFileTypes = acceptableFileTypes || [];
        (ret.mediaEntityData.metadata as MediaEntity).maxSize = maxSize;

        return ret;
    }
}
