import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from "@angular/router";
import { Observable } from "rxjs";
import { first, map } from "rxjs/operators";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";

@Injectable()
export class SearchServiceResolver implements Resolve<any>{

    constructor(private readonly dynamicItemService: DynamicItemService) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> {
        return this.getSearchService().pipe(first());
    }
    getSearchService() {
        return this.dynamicItemService.executeUnboundFunction<any>(`Default.GetSearchService()`).pipe(map(providersResult => {
            return providersResult.value
        }));
    }
}