import { Component, Input, OnInit } from "@angular/core";
import { MediaHelpers } from "../../services/media.helpers";
import { DataItem } from "../../../content/dynamic-modules/interfaces";

@Component({
    selector: "sf-embed-media-content",
    templateUrl: "./embed-media-content.component.html"
})
export class EmbedMediaContentComponent implements OnInit {
    @Input() dataItem: DataItem;

    embedCode: string;
    title: string;
    linkUrl: string;

    ngOnInit(): void {
        if (this.dataItem && this.dataItem.data) {
            this.title = `Embed ${this.dataItem.metadata.singularName.toLowerCase()}`;
            this.linkUrl = this.dataItem.data.Url;
            if (MediaHelpers.isImageEntity(this.dataItem)) {
                const alternativeText = this.dataItem.data.AlternativeText || this.dataItem.title;
                this.embedCode = `<img width="${this.dataItem.data.Width}" height="${this.dataItem.data.Height}" src="${this.dataItem.data.Url}" alt="${alternativeText}"/>`;
            } else if (MediaHelpers.isDocumentEntity(this.dataItem)) {
                this.embedCode = `<a href="${this.dataItem.data.Url}">${this.dataItem.data[this.dataItem.metadata.defaultFieldName]}</a>`;
            } else if (MediaHelpers.isVideoEntity(this.dataItem)) {
                this.embedCode = `<video controls src="${this.dataItem.data.Url}">Your browser does not support the video tag.</video>`;
            }
        }
    }
}
