import { stringConstants } from "../../../common-constants";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { Router, UrlTree, ActivatedRoute } from "@angular/router";
import { PropertyEditorViewModes } from "../property-editor.constants";
import { EditorViewKey } from "../interfaces/widget-editor-view-provider";
import { RESOLVE_NAMES } from "../../content/constants";
import { SiteData } from "../../shared/services/metadata/site-data.store";
import { ComponentModel } from "../../pages/components/zone-editor/model/component-model";

export class WidgetContext {
    widgetId: string;
    entityId: string;
    culture: string;
    segmentId: string;
    widgetSegmentId: string;
    webServiceUrl: string;
    localizationMode: WidgetLocalizationMode = WidgetLocalizationMode.Both;
    widgetName: string;
    viewName: string;
    viewKey: EditorViewKey;
    sectionName: string = PropertyEditorViewModes.BASIC;
    entityData: DataItem;
    isQuickEdit: boolean = false;
    component: ComponentModel;
    window: Window;
    private urlTree: UrlTree;

    static fromSitefinityContext(sfContext, router: Router, route: ActivatedRoute): WidgetContext {
        const context = new WidgetContext();
        context.urlTree = router.parseUrl(sfContext.url);
        context.widgetId = sfContext.Id;
        context.entityId = sfContext.PageId;
        context.culture = sfContext.PropertyValueCulture || context.getCultureFromRoute(route);
        context.webServiceUrl = sfContext.PropertyServiceUrl;
        context.widgetName = context.getWidgetName();
        context.viewName = context.getWidgetView();
        context.viewKey = context.getViewKey();
        return context;
    }

    private getCultureFromRoute(route: ActivatedRoute): string {
        const siteData = route.snapshot.data[RESOLVE_NAMES.siteDataStore] as SiteData;

        return siteData ? siteData.DefaultContentCulture : null;
    }

    private getWidgetName(): string {
        const segmentsCount = this.urlTree.root.children.primary.segments.length;
        const lastSegmentPath = this.urlTree.root.children.primary.segments[segmentsCount - 1].path;
        return lastSegmentPath;
    }

    private getWidgetView(): string {
        const viewParam = this.urlTree.queryParams["view"];
        if (viewParam) {
            return viewParam;
        }

        return stringConstants.EMPTY_STRING;
    }

    private getViewKey(): EditorViewKey {
        const viewName = this.getWidgetView();
        const viewNameToLower = viewName === stringConstants.EMPTY_STRING ? PropertyEditorViewModes.BASIC : viewName;
        const widgetName = this.getWidgetName();

        return {widgetName: widgetName, viewName: viewNameToLower};
    }
}

export enum WidgetLocalizationMode {
    AlwaysSaveCurrentTranslation,
    AlwaysSaveAllTranslations,
    Both
}
