import { Component, OnInit, Input } from "@angular/core";
import { DynamicItemService, LoadItemsResponse } from "../../services/dynamic-item.service";
import { EntityData, DataItem } from "../../interfaces";
import { ReplaySubject, Subscription } from "rxjs";
import { cloneObject } from "../../../../../utils";
import { BLUR_EFFECT_TIMEOUT } from "../../../constants";
import { toLoadingState, delayEmission } from "../../../../shared/rxjs-extensions";
import { SfBreadcrumbPipe, SfHtmlEscapePipe } from "@progress/sitefinity-component-framework";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { ItemListSettings } from "./item-list-settings";
import { FieldBase } from "../../../../../../../fields/field-base";
import { TreeConfig } from "../../../../../../../fields";

/**
 * Component used to display data items
 */
@Component({
    selector: "sf-item-list",
    templateUrl: "./item-list.component.html"
})

export class ItemListComponent extends FieldBase implements OnInit {
    @Input() dataItemsIds: Array<string> = [];
    @Input() entityData: EntityData;
    @Input() componentTitle: string;
    @Input() componentSubtitle: string;
    @Input() listAdditionalLook: string;

    showCount: boolean;
    shouldFetchItems: boolean = true;
    showTitle: boolean = true;

    dataItems$: ReplaySubject<DataItemsLoadingData> = new ReplaySubject(1);
    dataItemsCount$: ReplaySubject<string>;

    protected dataItems: Array<DataItem> = [];
    protected treeConfig: TreeConfig = {
        status: true,
        noSelection: true,
        description: true,
        treeProperties: {
            displayField: "Title"
        }
    };
    protected displayField: string;

    /**
     * Initializes a new instance of the {@link ItemListComponent} class
     */
    constructor(private dynamicItemService: DynamicItemService) {
        super();
    }

    public ngOnInit(): void {
        this.configurePropertiesFromSettings();

        if (this.entityData) {
            this.displayField = this.entityData.metadata.defaultFieldName;
            this.treeConfig.treeProperties.displayField = this.displayField;
        }

        // Do not try to fetch items if there are no itemId's provided
        if (this.dataItems.length) {
            this.dataItems$.next({ dataItems: this.dataItems, isLoading: false });
            this.shouldFetchItems = false;
        }

        if (this.shouldFetchItems) {
            const itemIds = this.dataItemsIds.slice(0, 50);
            const itemsSubscription = this.loadDataItems(itemIds);
            this.registerSubscription(itemsSubscription);
        }
    }

    writeValue(newValue) {
        if (Array.isArray(newValue)) {
            const newDataItems = newValue.map(x => cloneObject(x.data));
            this.dataItems$.next({ dataItems: newDataItems, isLoading: false });
            this.entityData = newValue[0];
            this.shouldFetchItems = false;
        }

        super.writeValue(newValue);
    }

    onRemoveNode(item) {
        const newValue = this.getValue().filter(x => x.data.Id !== item.data.Id);
        this.writeValue(newValue);

        if (this.dataItemsCount$) {
            this.dataItemsCount$.next(this.getValue().length.toString());
        }
    }

    requestMoreItems() {
        if (this.dataItems.length >= this.dataItemsIds.length) {
            return;
        }

        const skip = this.dataItems.length;
        this.loadItems(skip);
    }

    loadItems(skip) {
        const itemIds = this.dataItemsIds.slice(skip, skip + 50);
        const itemsSubscription = this.loadDataItems(itemIds);

        this.registerSubscription(itemsSubscription);
    }

    private configurePropertiesFromSettings() {
        const itemListSettings = this.settings as ItemListSettings;
        if (itemListSettings) {
            this.treeConfig.deletion = itemListSettings.showRemoveButton;
            this.showTitle = itemListSettings.showTitle;
            this.treeConfig.status = itemListSettings.showStatus;
            this.dataItemsCount$ = itemListSettings.itemsCount;
        }
    }

    private loadDataItems(itemIds: string[]): Subscription {
        const breadcrumbPipe = new SfBreadcrumbPipe(new SfHtmlEscapePipe());
        return this.dynamicItemService
            .getItemsByKeys({
                entityData: this.entityData,
                fallbackProperties: [this.entityData.metadata.defaultFieldName],
                keyProperty: this.entityData.metadata.key,
                keys: itemIds
            })
            .pipe(
                toLoadingState<LoadItemsResponse>(),
                delayEmission(BLUR_EFFECT_TIMEOUT)
            )
            .subscribe(state => {
                if (state) {
                    if (state.content) {
                        const items = state.content.dataItems.map(dataItem => {
                            const description = this.entityData.metadata.isSelfReferencing && dataItem.data && dataItem.data.Breadcrumb ? breadcrumbPipe.transform(dataItem.data.Breadcrumb, false, true) : dataItem.metadata.singularName;
                            const res = cloneObject(dataItem.data);
                            res["description"] = description;
                            res.isTranslated = dataItem.isTranslated;
                            return res;
                        });
                        this.dataItems = this.dataItems.concat(items);
                    }
                    this.dataItems$.next({ dataItems: this.dataItems, isLoading: state.isLoading });
                }
            });
    }
}

export interface DataItemsLoadingData {
    dataItems: Array<DataItem>;
    isLoading: boolean;
}

export const ITEM_LIST_REGISTRY: FieldRegistration = {
    writeComponent: ItemListComponent,
    readComponent: ItemListComponent,
    settingsType: ItemListSettings
};
