import {
    Button,
    CancelButton,
    ConfirmButton,
    DialogData,
    ModalWindowService,
    CanCloseModal,
    CloseModalCallback,
    ClosingContext,
    ClickResult
} from "../shared/services/modal-window.service";
import { MESSAGES } from "./file-picker.messages";
import { MediaValidationHelper } from "./media-validation-helper";
import { MediaRecognizerService } from "./media/media-recognizer.service";
