import { NOTIFICATION_LOOKS } from "../shared/services/notification/notification-data";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../shared/components/modal-window/modal-window.component";
import { NotificationService, NOTIFICATION_SERVICE } from "../shared/services/notification/notification.service";
import { WINDOW_TOKEN } from "../../window.provider";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { LibraryStore } from "./services/library.store";
import { SelectorEventArgs } from "@progress/sitefinity-component-framework";
import { ServiceContract, SelectorComponent, ServiceInfo } from "../../../../fields/selector/selector.component";
import { HierarchicalService, HIERARCHICAL_SERVICE_TOKEN } from "../shared/services/hierarchical-service";
import { SiteData } from "../shared/services/metadata/site-data.store";
import { LoadItemsResponse } from "../content/dynamic-modules/services/dynamic-item.service";
import { UploadDTO } from "./services/media.service";

const LIBRARY_SELECT = "librarySelect";
const BULK_EDIT_REQUIRED = "bulkEditRequired";
const SHOW_ALL_MESSAGE = "Show all libraries";
const CREATE_LIBRARY_MESSAGE = "Create a library";
const ALTERNATIVE_TEXT_LABEL = "Alternative text";
const ALT_TEXT_LABEL = "Alt text";
const EXCLUDED_FIELDS = [Properties.URL_NAME, Properties.TITLE, Properties.ALTERNATIVE_TEXT, Properties.MEDIA_FILE_URL_NAME];
const ALTERNATIVE_TEXT_LOOK = "inline sf-mt-4xs";
const TEXT_FIELD_LOOK = "inline";
const LIBRARY_CHIP_CONTENT_NAME = "library";
const INVALID_FILE_MESSAGE = "Invalid file.";

@Component({
    selector: "sf-file-upload",
    templateUrl: "./file-upload.component.html"
})
export class FileUploadComponent extends FileLayoutBaseComponent implements OnInit, CanCloseModal, CloseModalCallback, AfterViewInit, OnDestroy {

    @ViewChild("wrapper", { static: true }) wrapper: ElementRef;

    @Output() search = new EventEmitter<string>();
    @Output() selectedProvider = new EventEmitter<string>();

    chipsConfig: ChipsConfig = {
        showRecentLabel: false,
        showSelectedItemAsActive: true,
        focusFirstNode: false,
        showNoResultsLabel: true,
        actions: []
    };
    libraryChipContentName = LIBRARY_CHIP_CONTENT_NAME;
    isSingleSelection = true;
    parentId = null;
    folderId = null;

    acceptFileTypes: string;
    selectedLibraries: any[];
    selectedFiles: File[];
    fields: FieldModel[];
    folders: any[];
    defaultFieldName: string;
    libraries: Observable<DataItem[]>;
    justAddedFiles: any[];
    messages: any;
    folder: any;
    formattedTypeName: string;
    fileUploadErrorMessages: string[];
    dropdownChips: any[];
    showProviderSelector: boolean;
    targetLibraryId: string = null;
    centerLibraryLabel: boolean = true;
    allowCreate: boolean = false;
    initializeLibraries: boolean;
    errorMessage: string;
    mediaEntity: MediaEntity;
    uniqueInputId: string;

    @ViewChildren(FormFieldWrapperComponent) private formwrapperComponentsQuery: QueryList<FormFieldWrapperComponent>;

    private static lastUsedLibraryCache: { [contentType: string]: any } = {};

    private areDropdownChipsFiltered = false;

    private _selectedLibrary: any;
    private wrapperComponents: Array<FormFieldWrapperComponent>;
    private _closeModalCallback: (data: any) => void;
    private isAllFieldsValid: boolean = false;
    private bulkFiles: FileInfo[] = [];
    private _files: FileInfo[];
    private wrapperSubscriptions: Subscription;

    private modalItems$ = new ReplaySubject<TotalCountResult<any[]>>(1);
    private serviceAware: ServiceContract;
    private hierarchicalService: HierarchicalService;
    private isInCreate: boolean = false;
    private showAllLibrariesLoading: boolean = true;

    get files(): FileInfo[] {
        return this._files;
    }

    set files(value) {
        this._files = value;
        this.bulkFiles = this.cloneArray(value);
    }

    get selectedLibrary(): any {
        return this._selectedLibrary;
    }
    set selectedLibrary(selectedLibrary: any) {
        if (selectedLibrary && !selectedLibrary.isSeparator && !selectedLibrary.isLink) {
            this.errorMessage = null;
            this._selectedLibrary = selectedLibrary;

            // This is needed for the sf-chips component in the template which binds to Array.
            // We want to select only one library at a time.
            selectedLibrary.isTranslated = true;
            this.selectedLibraries = [selectedLibrary];

            this.parentId = selectedLibrary.RootId ? selectedLibrary.RootId : selectedLibrary.Id;
            this.folderId = selectedLibrary.RootId ? selectedLibrary.Id : null;
        }
    }

    get displayedLibraries(): any[] {
        return this.dropdownChips.slice(0, -2);
    }
    set displayedLibraries(value: any[]) {
        this.dropdownChips = value.slice().filter(x => !x.inactive);
    }

    private get lastUsedLibrary(): any {
        return FileUploadComponent.lastUsedLibraryCache[this.mediaEntity.singularName.toLowerCase()];
    }
    private set lastUsedLibrary(lib: any) {
        FileUploadComponent.lastUsedLibraryCache[this.mediaEntity.singularName.toLowerCase()] = lib;
    }

    constructor(
        public mediaRecognizerService: MediaRecognizerService,
        private fileInfoService: FileInfoService,
        protected layoutService: LayoutService,
        private modalService: ModalWindowService,
        private route: ActivatedRoute,
        private mediaValidationHelper: MediaValidationHelper,
        private router: Router,
        private communicationService: ComponentCommunicationService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        @Inject(WINDOW_TOKEN) private window: Window,
        private store: LibraryStore,
        @Optional() @Inject(HIERARCHICAL_SERVICE_TOKEN) private hierarchicalServices: Array<HierarchicalService>
    ) {
        super(layoutService);
    }

    ngOnInit(): any {
        this.mediaEntity = this.mediaEntityData.metadata as MediaEntity;
        this.messages = this.multiple ? MESSAGES.multiple : MESSAGES.single;
        this.formattedTypeName = getFormattedTypeName({ plural: this.mediaEntity.setName, singular: this.mediaEntity.singularName.toLowerCase() }, this.multiple, true);
        this.acceptFileTypes = this.mediaValidationHelper.getAcceptableFileTypes(this.mediaEntity.acceptableFileTypes);
        this.initializeLibraries = this.initializeLibraries && (this.selectedLibrary ? false : true);
        if (!this.initializeLibraries && !this.selectedLibrary) {
            this.selectedLibraries = [];
        }

        this.registerSubscription(this.libraries
            .subscribe((result) => {
                if (this.initializeLibraries) {
                    this.initLibraries(result);
                    this.initializeLibraries = false;
                }

                if (this.areDropdownChipsFiltered) {
                    this.chipsConfig.focusFirstNode = result && result.length > 0;
                } else {
                    this.chipsConfig.focusFirstNode = false;
                }

                this.displayedLibraries = result ? result.map(x => cloneObject(x.data)) : [];

                if (result && result.length === 1 && this.targetLibraryId) {
                    this.chipsConfig.hideEditButton = true;
                }

                if (result && result.length === 0 || this.chipsConfig.hideEditButton) {
                    this.centerLibraryLabel = false;
                }

                this.chipsConfig.actions = [];
                if (this.allowCreate) {
                    this.chipsConfig.actions.push({ label: CREATE_LIBRARY_MESSAGE, action: this.onCreateLibraries.bind(this) });
                }

                this.chipsConfig.actions.push({ label: SHOW_ALL_MESSAGE, action: this.onShowAllLibraries.bind(this) });
            })
        );

        this.uniqueInputId = guid();
        this.files = [];
        this.onSelectedForUpload(this.selectedFiles);
    }

    initLibraries(result: DataItem[]) {
        if (!result || !result.length) {
            this.selectedLibraries = [];
            return;
        }
        const filteredResult = result.slice().filter(x => !x.data.inactive);

        if (!filteredResult.length) {
            this.selectedLibraries = [];
            return;
        }

        /**
         * Selecting the default library if no library has been used yet.
         * Since libraries have no "default" flag the first created is used.
         * This is the same behavior as in old Sitefinity backend.
         */
        if (this.lastUsedLibrary && filteredResult.some(x => x.data.Id === this.lastUsedLibrary.Id)) {
            this.selectedLibrary = this.lastUsedLibrary;
        } else {
            // we need a clone of the original array as sort mutates it, hence slice() is used
            this.selectedLibrary = cloneObject(filteredResult[0].data);
        }
    }

    ngAfterViewInit() {
        this.wrapperComponents = this.formwrapperComponentsQuery.toArray();
        this.wrapperSubscriptions = this.formwrapperComponentsQuery.changes.subscribe((values: QueryList<FormFieldWrapperComponent>) => {
            this.wrapperComponents = values.toArray();
        });
    }

    ngOnDestroy() {
        if (this.wrapperSubscriptions) {
            this.wrapperSubscriptions.unsubscribe();
        }
        this.notificationService.close(MODAL_WINDOW_NOTIFICATION_FILTER);
    }

    canCloseCallback(context: ClosingContext): boolean {
        let isValid = true;

        if (context.data && context.data.data) {
            this.wrapperComponents.forEach(x => {
                const isFieldValid = !x.hasErrors();
                if (isValid) {
                    isValid = isFieldValid;
                }
            });

            if (!!this.files.length && this.multiple && !this.isAllFieldsValid) {
                isValid = false;
                this.openRequiredFieldsBulkEdit(context.data.data);
            }
        }

        return isValid;
    }

    setCloseModalCallback(closeModalCallback: (data: any) => void): void {
        this._closeModalCallback = closeModalCallback;
    }

    onSelectedForUpload(files: File[]): Promise<void> {
        return new Promise((resolve, reject) => {
            this.libraries.pipe(first()).subscribe(libs => {
                const currentLib = libs.find(x => x.key === this.parentId);
                this.mediaValidationHelper.validate(this.mediaEntity, Array.from(files), true);
                const uploadedFiles = this.mediaValidationHelper.getValidFiles();
                this.justAddedFiles = uploadedFiles;
                this.fileUploadErrorMessages = this.mediaValidationHelper.getErrorMessages();
                this.recalculateLayout(this.files.concat(this.justAddedFiles), this.wrapper);
                const promises = uploadedFiles.map((file: File) => this.fileInfoService.createFileInfo(file, this.mediaEntity));

                return Promise.all(promises)
                    .then(fileInfos => {
                        const newFiles = [];

                        fileInfos.forEach((fileInfo) => {
                            if (!fileInfo.isCorrupted) {
                                newFiles.push(fileInfo);
                            } else {
                                this.fileUploadErrorMessages.push(INVALID_FILE_MESSAGE);
                            }
                        });

                        this.files = this.files.concat(newFiles);
                        this.fileUploadErrorMessages = Array.from(new Set(this.fileUploadErrorMessages));

                        this.initFields();
                        this.justAddedFiles = [];
                        this.recalculateLayout(this.files, this.wrapper);

                        this.validateLibrarySize(this.files, currentLib);
                        resolve();
                    })
                    .catch(reject);
            });
        });
    }

    onTitleBlur(file: any) {
        this.resetWhenEmpty(file.form, Properties.TITLE, file.data[Properties.TITLE]);
    }

    @HostListener("window:resize")
    onResize() {
        // When uploading videos and trying to view the video in full screen we do not want to recalculate the layout
        // because this leads to instant closing of the full screen of the video. There is no need to recalculate the layout
        // when the window is in full screen
        if (!this.window.document.fullscreenElement) {
            this.recalculateLayout(this.files.concat(this.justAddedFiles), this.wrapper);
        }
    }

    onRemoveClick(file: any) {

        this.libraries.pipe(first()).subscribe(libs => {
            const currentLib = libs.find(x => x.key === this.parentId);

            const index = this.files.findIndex(img => img === file);
            this.files.splice(index, 1);
            this.bulkFiles.splice(index, 1);
            this.selectedFiles.splice(index, 1);
            this.fileUploadErrorMessages = [];

            this.validateLibrarySize(this.files, currentLib);

            this.recalculateLayout(this.files, this.wrapper);
        });
    }

    getFilesForUpload(): UploadDTO[] {
        if (!this.files) {
            return;
        }

        this.lastUsedLibrary = this.selectedLibrary;
        const files = this.files.map(file => {
            const data = Object.keys(file.form.value).reduce((data, key) => {
                const value = file.form.value[key];

                if (value !== null && this.mediaEntity.singularName.toLowerCase() !== key) {
                    data[key] = value;
                }

                return data;
            }, {});

            return {
                name: file.name,
                title: file.title,
                content: file.content,
                contentType: file.contentType,
                width: file.width,
                height: file.height,
                total: file.size,
                data: data,
                dataUrl: file.dataUrl,
                extension: file.extension,
                size: file.size
            };
        });

        return files;
    }

    onSelectLibrary(event: any) {
        if (event.action && typeof event.action === "function") {
            event.action();
        } else {
            this.selectedLibrary = cloneObject(event);
        }

        this.validateLibrarySize(this.files, this.selectedLibrary);
    }

    onSearchChips(searchTerm: any): void {
        this.areDropdownChipsFiltered = !!searchTerm;
        this.search.emit(searchTerm);
    }

    onShowAllLibraries() {
        this.defaultFieldName = this.mediaEntityData.metadata.defaultFieldName;
        this.isInCreate = this.route.snapshot.data.itemData && this.route.snapshot.data.itemData.entityData.isEmpty;

        const metadataStore = this.route.parent.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const parentEntityName = MediaHelpers.getParentSetName(this.mediaEntityData);
        const metadata = metadataStore.entities[parentEntityName];

        this.serviceAware = new ServiceContract(
            (info: ServiceInfo) => this.loadMore(info, this.mediaEntityData, this.isInCreate),
            (info: ServiceInfo) => this.expandChildren(info, this.mediaEntityData));

        if (this.hierarchicalServices) {
            this.hierarchicalServices.forEach(service => {
                if (service.isTypeSupported(this.mediaEntityData)) {
                    this.hierarchicalService = service;
                }
            });
        }

        const siteData = this.route.snapshot.parent.data[RESOLVE_NAMES.siteDataStore] as SiteData;
        this.hierarchicalService.siteId = siteData.Id;

        this.getModalItems(this.mediaEntityData);

        const componentData: ComponentData = {
            type: SelectorComponent,
            properties: {
                value$: this.modalItems$,
                treeConfig: {
                    multiSelection: false,
                    isHierarchical: true,
                    dataProperties: {
                        toolTipField: "tooltip"
                    }
                },
                serviceAware: this.serviceAware,
                typeNames: {
                    plural: metadata.displayName,
                    singular: metadata.singularName
                },
                defaultField: metadata.defaultFieldName,
                loading: this.showAllLibrariesLoading
            },
            removePreviousView: false
        };

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton(SelectorConstants.CANCEL)
        ];
        const dialogData = new DialogData(componentData, (result) => {
            if (result.data && result.data.data) {
                const component: any = result.component;

                if (component && component.selected && component.selected.length === 1) {
                    this.onSelectLibrary(component.selected[0]);
                }
            }
        }, buttons, null, "-bottom");

        this.modalService.setMapping(dialogData, LIBRARY_SELECT);
        this.modalService.open(this.route, LIBRARY_SELECT);
    }

    onCreateLibraries() {
        const metadataStore = this.route.parent.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const parentEntityName = MediaHelpers.getParentSetName(this.mediaEntityData);
        const metadata = metadataStore.entities[parentEntityName] as Entity;
        const dataItem = DataItem.emptyItem({
            metadata,
            provider: this.mediaEntityData.metadata.selectedProvider || this.mediaEntityData.provider,
            culture: this.mediaEntityData.culture
        });

        const command = new EditInDialogCommand(this.modalService, this.router);
        const siteData = this.route.parent.snapshot.data.siteDataStore;

        const data = {
            dataItem,
            siteData,
            dialogType: DynamicUpdateItemComponent
        };

        this.communicationService.next(new CreateLibraryFromFileUploadClickEvent({ hideStorageProvider: true }));

        command.execute({
            currentRoute: this.route.parent.parent,
            data,
            model: null
        }).subscribe(r => {
            if (r.success) {
                this.selectedLibrary = cloneObject(r.dataItem.data);
                this.store.getFolderById(this.mediaEntityData, this.selectedLibrary.Id).subscribe(result => {
                    this.validateLibrarySize(this.files, result.data);
                });
            }

            this.communicationService.next(new CreateLibraryFromFileUploadClickEvent({ hideStorageProvider: false }));
        });
    }

    onProviderSelectionChange(event: SelectorEventArgs) {
        this.initializeLibraries = true;
        this.selectedProvider.emit(event.tabValue);
    }

    private resetWhenEmpty(form: FormGroup, property: string, defaultValue: string): void {
        const rawValue = form.getRawValue();

        const value = rawValue[property] || stringConstants.EMPTY_STRING;

        if (!value.trim().length) {
            form.setValue(Object.assign(rawValue, { [property]: defaultValue || stringConstants.EMPTY_STRING }));
        }
    }

    private initFields() {
        const altText = this.fields.find(field => field.key === Properties.ALTERNATIVE_TEXT);

        // Pick required fields except: UrlName, Title and AlternativeText that have special handling
        const filteredFields: FieldModel[] = this.fields
            .filter((field: FieldModel) => EXCLUDED_FIELDS.indexOf(field.key) < 0 && (!this.multiple && field.settings.required));

        const allFields = this.fields
            .filter((field: FieldModel) => EXCLUDED_FIELDS.indexOf(field.key) < 0 && field.settings.required);

        this.isAllFieldsValid = filteredFields.length === allFields.length;

        // Fix title and put Alternative text on top
        if (altText) {
            const shortTextSettings = (altText.settings as ShortTextSettings);
            altText.settings.title = ALTERNATIVE_TEXT_LABEL;
            if (this.multiple) {
                shortTextSettings.placeholder = ALT_TEXT_LABEL;
                shortTextSettings.look = ALTERNATIVE_TEXT_LOOK;
            }
            filteredFields.unshift(altText);
            allFields.unshift(altText);
        }

        if (this.multiple) {
            allFields.unshift(this.createMediaModel());
            allFields.forEach(field => {
                if (field.selector === FieldTypes.shortText || field.selector === FieldTypes.textArea) {
                    (field.settings as ShortTextSettings).placeholder = "Add " + field.settings.title.toLowerCase();
                    field.settings.look = TEXT_FIELD_LOOK;
                }
                field.settings.showTitle = false;
            });
        }

        if (this.files.length > 0) {
            this.assignFields(this.files, filteredFields);
            this.assignFields(this.bulkFiles, allFields);
        }
    }

    private assignFields(files: FileInfo[], fields: FieldsModule[]): void {
        for (const file of files) {
            file.fields = [];
            fields.forEach((field: FieldModel) => {
                const clonedField: any = deepClone(field);
                if (field.key === this.mediaEntity.singularName.toLowerCase()) {
                    file["src"] = file.dataUrl;
                    file["item"] = file;
                    file["playable"] = false;
                    file["inGridView"] = true;
                    clonedField.value = file;
                }
                clonedField.settings.key = file.title;
                clonedField.settings.culture = this.mediaEntityData.culture;

                file.fields.push(clonedField);
                file.form.setControl(field.key, new FormControl(clonedField.value, field.settings.validators));
            });
        }
    }

    private openRequiredFieldsBulkEdit(workflowOperationName: string) {
        this.updateBulkFields();

        const buttons: Button[] = [
            new ConfirmButton(MESSAGES.multiple.use.select(null)),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const libraryTreeData: ComponentData = {
            type: BulkComponent,
            properties: {
                type: this.mediaEntity.singularName.toLowerCase(),
                items: this.bulkFiles,
                parentComponent: this
            }
        };

        const dialogData = new DialogData(libraryTreeData, (result) => {
            if (result.data && result.data.data) {
                this.isAllFieldsValid = true;

                const data: ClickResult = { ...result.data, data: workflowOperationName };
                this._closeModalCallback({ component: this, data });
            }
        }, buttons, null, null);

        this.modalService.setMapping(dialogData, BULK_EDIT_REQUIRED);
        this.modalService.open(this.route, BULK_EDIT_REQUIRED);
    }

    private updateBulkFields() {
        this.files.forEach(file => {
            const bulkItem = this.bulkFiles.find(x => x.content === file.content);
            if (bulkItem) {
                Object.keys(file.form.controls).forEach(key => {
                    const field = file.form.controls[key];
                    const bulkField = bulkItem.fields.find(x => x.key === key);
                    if (bulkField) {
                        bulkField.value = field.value;
                    }
                });
            }
        });
    }

    private createMediaModel(): FieldModel {
        const settings = new SettingsBase(this.mediaEntity.singularName.toLowerCase(), false);
        const dropdownModel = new FieldModel({
            key: this.mediaEntity.singularName.toLowerCase(),
            selector: "sf-simple-media",
            settings: settings,
            registration: {
                writeComponent: SimpleMediaComponent
            }
        });
        return dropdownModel;
    }

    private cloneArray(value: any[]): any[] {
        if (!value) {
            return value;
        }

        const clonedArray = [];

        value.forEach(x => {
            const copiedValue = {};
            Object.assign(copiedValue, x);
            clonedArray.push(copiedValue);
        });

        return clonedArray;
    }

    private validateLibrarySize(allFiles: any[], library: any) {
        if (!library) {
            return;
        }

        let currentlySelectedFilesSizeInKB = 0;
        allFiles.forEach(f => currentlySelectedFilesSizeInKB += f.size);
        currentlySelectedFilesSizeInKB /= 1024;

        let data: { TotalLibrarySizeInKb: number; MaxLibrarySizeInKb: number; };
        if (library.data) {
            data = library.data;
        } else {
            data = library;
        }

        const isExceeded = this.mediaValidationHelper
            .validateLibrarySizeExceeded(currentlySelectedFilesSizeInKB, data.TotalLibrarySizeInKb, data.MaxLibrarySizeInKb);

        const maxLibrarySizeInMB = data.MaxLibrarySizeInKb / 1024;

        const errorMessage = `The selected ${this.formattedTypeName} exceed the maximum allowed size of`;
        const error = `${errorMessage} ${maxLibrarySizeInMB} MB.`;

        if (isExceeded) {

            this.notificationService.publishBasicNotification({
                message: error,
                look: NOTIFICATION_LOOKS.ERROR,
                duration: NOTIFICATION_DURATION_INFINITE,
                filterParam: MODAL_WINDOW_NOTIFICATION_FILTER,
                closeButton: true
            });

            this.files.forEach(f => {
                if (Array.isArray(f.errors)) {
                    if (!f.errors.some(e => e.includes(error))) {
                        f.errors.push(error);
                    }
                } else {
                    f.errors = [error];
                }
            });
        } else {
            this.notificationService.close(MODAL_WINDOW_NOTIFICATION_FILTER);

            this.files.forEach(f => {
                if (Array.isArray(f.errors)) {
                    const indexOfError = f.errors.findIndex(x => x.includes(errorMessage));
                    f.errors.splice(indexOfError, 1);
                }
            });
        }
    }

    private loadMore(info: ServiceInfo, entityData: EntityData, isCreate: boolean = false): Observable<any> {
        info.parentId = this.targetLibraryId;

        this.showAllLibrariesLoading = true;

        return this.hierarchicalService.loadMore(info, entityData, null, null, isCreate).pipe(first(), map(result => {
            return this.mapAndUnlockItems(result);
        }));
    }

    private expandChildren(info: ServiceInfo, entityData: EntityData): Observable<any> {
        this.showAllLibrariesLoading = true;

        return this.hierarchicalService.expandChildren(info, entityData, null).pipe(first(), map(result => {
            return this.mapAndUnlockItems(result);
        }));
    }

    private getModalItems(entityData: EntityData): void {
        this.showAllLibrariesLoading = true;

        const modalItems$ = this.hierarchicalService.getModalItems(entityData, null);

        modalItems$.pipe(first()).subscribe((result) => {
            this.modalItems$.next(this.mapAndUnlockItems(result));
        });
    }

    private mapAndUnlockItems(result: LoadItemsResponse): TotalCountResult<any[]> {
        return deepClone({ dataItems: result.dataItems.map(x => x.data), totalCount: result.totalCount });
    }
}
