import { Injectable } from "@angular/core";
import { VALIDATOR_NAMES } from "../../../../../../../fields/common/validators/index";
import { CUSTOM_ERROR_PREFIX } from "../../../../../../../fields/common/validators/validators.constants";

/**
 * Filters the provided errors to contain only required, digits limit or max length errors.
 */
@Injectable()
export class ErrorFilter {
    /**
     * The allowed error names - required, digitLimit and maxlenght
     */
    public static readonly allowedErrorsNames = [VALIDATOR_NAMES.REQUIRED, VALIDATOR_NAMES.DIGITS_LIMIT, VALIDATOR_NAMES.MAX_LENGTH];
    public static readonly allowedErrorsPrefixes = [CUSTOM_ERROR_PREFIX];

    /**
     * Using the provided errors, returns a filtered error object.
     * @param errors The errors to be filtered.
     * @param enableRequired If filtering by required is enabled.
     * @param invert Whether to invert the logic and return the errors that are not allowed
     */
    public getAllowedErrors(errors: any, enableRequired: boolean, allowedErrorsNames: string[] = ErrorFilter.allowedErrorsNames): any {
        let result: any = null;
        if (errors) {
            Object.keys(errors).forEach((errorName) => {
                if (errorName === VALIDATOR_NAMES.REQUIRED && !enableRequired)
                    return;

                // check if some allowed custom error should be processed
                const hasAllowedCustomError = ErrorFilter.allowedErrorsPrefixes.some(x => errorName.startsWith(x));

                // if null is passed as an allowed parameter, then we assume that we do not want the errors to be filtered, with the
                // exception for the required check
                const match = (allowedErrorsNames === null) || ErrorFilter.allowedErrorsNames.some(x => x === errorName) || hasAllowedCustomError;
                if (match) {
                    result = result || {};
                    result[errorName] = errors[errorName];
                }
            });
        }

        return result;
    }
}
