import { ClassProvider, Injectable } from "@angular/core";
import { EntityData } from "../../../../content/dynamic-modules/interfaces";
import { GridExtenderBase, GRID_EXTENDER_TOKEN } from "../../../services/grid/grid-extender-base";
import { EVENT_ITEM_FULL_NAME, CALENDAR_ITEM_FULL_NAME } from "../../../services/metadata/meta-data-constants";

@Injectable()
export class EventsGridExtender extends GridExtenderBase {

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.typeFullName === EVENT_ITEM_FULL_NAME || entityData.metadata.typeFullName === CALENDAR_ITEM_FULL_NAME;
    }
}

export const EVENTS_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: EventsGridExtender
};
