import { ENTITY_SET, EVENTS_NAMESPACE, PAGES_NAMESPACE, IMAGE_ITEM_FULL_NAME, TAXONOMY_ITEM_FULL_NAME, BLOGS_NAMESPACE, LISTS_NAMESPACE, NEWS_NAMESPACE, DYNAMIC_TYPE_NAMESPACE, DOCUMENT_ITEM_FULL_NAME, VIDEO_ITEM_FULL_NAME, CONTENT_ITEM_FULL_NAME, LIBRARIES_NAMESPACE, FORMS_DESCRIPTION_FULL_NAME } from "./meta-data-constants";
import { ModuleInfo } from "./site-data.store";
import { HttpODataRequestWrapper } from "../http-odata-request.wrapper";
import { validateExtensionsVersusSitefinityVersions, cloneObject } from "../../../../utils";
import { stringConstants } from "../../../../common-constants";
