import { ALLOWED_FILE_EXTENSIONS, ACCEPTABLE_MEDIA_TYPES, RELATE_DATA_PROVIDER, MAXIMUM_ALLOWED_SIZE } from "../../../../../../fields/common/common-constants";
import { INSIGHT } from "../../insight/insight.constants";
import { MediaHelpers } from "../../../libraries/services/media.helpers";

const SUPPORTED_TYPES_NAMESPACES = [
    DYNAMIC_TYPE_NAMESPACE,
    NEWS_NAMESPACE,
    BLOGS_NAMESPACE,
    TAXONOMY_ITEM_FULL_NAME,
    LISTS_NAMESPACE,
    EVENTS_NAMESPACE,
    PAGES_NAMESPACE,
    IMAGE_ITEM_FULL_NAME,
    DOCUMENT_ITEM_FULL_NAME,
    VIDEO_ITEM_FULL_NAME,
    CONTENT_ITEM_FULL_NAME,
    FORMS_DESCRIPTION_FULL_NAME
];

const SUPPORTED_CONTENT_TYPES_NAMESPACES = [
    DYNAMIC_TYPE_NAMESPACE,
    NEWS_NAMESPACE,
    BLOGS_NAMESPACE,
    LISTS_NAMESPACE,
    EVENTS_NAMESPACE,
    LIBRARIES_NAMESPACE,
    CONTENT_ITEM_FULL_NAME
];

export const DEFAULT_FIELD_NAME: string = "Telerik.Sitefinity.V1.DefaultField";
export const SINGULAR_NAME: string = "Telerik.Sitefinity.V1.SingularName";
export const DISPLAY_NAME: string = "Telerik.Sitefinity.V1.DisplayName";
export const IGNORE_PARENT_CHILD_RELATIONSHIP: string = "Telerik.Sitefinity.V1.IgnoreParentChildRelationship";
export const SORT_RESTRICTIONS: string = "Org.OData.Core.V1.SortRestrictions";
export const FILTER_RESTRICTIONS: string = "Org.OData.Core.V1.FilterRestrictions";

const CHILD_TYPES: string = "Telerik.Sitefinity.V1.ChildTypes";
const PARENT_ID_PROPERTY_NAME: string = "Telerik.Sitefinity.V1.ParentIdPropertyName";
export const MODULE_NAME: string = "Telerik.Sitefinity.V1.ModuleName";
export const IS_ORDERABLE_PROPERTY_NAME: string = "Telerik.Sitefinity.V1.IsOrderable";
export const IS_CUSTOM_FILTER_ENABLED: string = "Telerik.Sitefinity.V1.IsCustomFilterEnabled";
export const IS_ALL_ITEMS_FILTER_ENABLED: string = "Telerik.Sitefinity.V1.IsAllItemsFilterEnabled";
export const IS_MULTILINGUAL: string = "Telerik.Sitefinity.V1.IsMultilingual";
export const IS_DAM_ENABLED: string = "Telerik.Sitefinity.V1.IsDamEnabled";

const UPDATABLE_PROPERTY = `Telerik.Sitefinity.V1.Validation.Updatable`;

export const META_SERVICE_PATH = "sfmeta";
export interface Relation {
    propName: string;
    setName: string;
    provider?: string;
    typeFullName?: string;
}

/**
 * Represents the currently edited type
 * @ExposedInApi {Entity} Entity v1/metadata/entity.d.ts
 */
export class Entity {
    public properties: any;
    public key: string;
    public enabled: boolean;

    // indicates if the item is a file (supports stream content)
    public isMedia: boolean;
    public isOpen: boolean;

    public children: Array<string>;
    public parent: string;
    public setName: string;
    public relations: Array<Relation>;
    public primitives: Array<string>;
    public selectedProvider: string;
    private static readonly keyIndex: number = 0;

    constructor(public readonly typeFullName: string, typeDefinition: any) {
        const typeClone = JSON.parse(JSON.stringify(typeDefinition));
        this.key = typeClone.keys && typeClone.keys[Entity.keyIndex];
        this.properties = Object.freeze(typeClone.properties);
        this.children = [];
    }

    isSortingAllowed(fieldName: string): boolean {
        const propertyExists: boolean = !!this.properties[fieldName];
        const sortingRestricted: boolean = this.sortRestrictions && this.sortRestrictions.indexOf(fieldName) >= 0;

        return propertyExists && !sortingRestricted;
    }

    isFilteringAllowed(fieldName: string): boolean {
        const propertyExists: boolean = !!this.properties[fieldName];
        const filteringRestricted: boolean = this.filterRestrictions && this.filterRestrictions.indexOf(fieldName) >= 0;

        return propertyExists && !filteringRestricted;
    }

    isPropertyUpdatable(propName: string) {
        const prop = this.properties[propName];

        if (prop && UPDATABLE_PROPERTY in prop) {
            return prop[UPDATABLE_PROPERTY];
        }

        return true;
    }

    get ignoreParentChildRelationship(): boolean {
        return !!this.properties[IGNORE_PARENT_CHILD_RELATIONSHIP];
    }

    get defaultFieldName(): string {
        return this.properties[DEFAULT_FIELD_NAME];
    }

    get displayName(): string {
        return this.properties[DISPLAY_NAME];
    }

    get singularName(): string {
        return this.properties[SINGULAR_NAME];
    }

    get hasChildren(): boolean {
        return this.children.length > 0;
    }

    get hasParent(): boolean {
        return this.parent != null;
    }

    get childTypeNames(): string[] {
        return this.properties[CHILD_TYPES] || [];
    }

    get isOrderable(): boolean {
        return !!this.properties[IS_ORDERABLE_PROPERTY_NAME];
    }

    get hasChildrenProperty(): string {
        return Properties.HAS_CHILDREN;
    }

    get parentIdProperty(): string {
        return this.properties[PARENT_ID_PROPERTY_NAME] || Properties.PARENT_ID;
    }

    /**
     * TODO: this method is a hack and should be avoided.
     */
    get hasLifecycle(): boolean {
        return this.properties[Properties.FIRST_PUBLISHED] !== undefined;
    }

    /**
     * If the item is a media item, but has preview of its content
     */
    get isMultimedia(): boolean {
        if (this.isMedia) {
            return this.setName !== ENTITY_SET.DOCUMENTS;
        }

        return false;
    }

    get isImage(): boolean {
        return this.isMedia && this.setName === ENTITY_SET.IMAGES;
    }

    get isVideo(): boolean {
        return this.isMedia && this.setName === ENTITY_SET.VIDEOS;
    }

    get isSelfReferencing(): boolean {
        return this.hasParent && this.hasChildren && this.childTypeNames[0] === this.typeFullName;
    }

    private get sortRestrictions(): string[] {
        return this.properties[SORT_RESTRICTIONS];
    }

    private get filterRestrictions(): string[] {
        return this.properties[FILTER_RESTRICTIONS];
    }

    get isCustomFilterEnabled(): boolean {
        return !!this.properties[IS_CUSTOM_FILTER_ENABLED];
    }

    get hasCustomFilterEnabledProperty(): boolean {
        return this.properties[IS_CUSTOM_FILTER_ENABLED] !== undefined;
    }

    get hasAllItemsFilterEnabledProperty(): boolean {
        return this.properties[IS_ALL_ITEMS_FILTER_ENABLED];
    }

    get isTranslatable(): boolean {
        return !MediaHelpers.isLibrary(this.setName);
    }

    get isMultilingual(): boolean {
        if (this.properties[IS_MULTILINGUAL] !== undefined) {
            return !!this.properties[IS_MULTILINGUAL];
        }

        return true;
    }

    get isDamEnabled(): boolean {
        return !!this.properties[IS_DAM_ENABLED];
    }

    get hasContent(): boolean {
        return this.setName === ENTITY_SET.PAGES || this.setName === ENTITY_SET.TEMPLATES || this.setName === ENTITY_SET.FORMS;
    }

    clone() {
        const clonedEntity = new Entity(this.typeFullName, {});
        Object.getOwnPropertyNames(this).forEach(p => {
            const desc = Object.getOwnPropertyDescriptor(this, p);
            if (desc.writable) {
                if (typeof (this[p]) === "object") {
                    clonedEntity[p] = cloneObject(this[p]);
                } else {
                    clonedEntity[p] = this[p];
                }
            }
        });

        return clonedEntity;
    }
}

export class MediaEntity extends Entity {
    public acceptableMediaTypes: Array<string>;
    public acceptableFileTypes: Array<string>;
    public mediaFilterEnabled: boolean;
    public provider: string;
    public maxSize: number;
    public originalAcceptableTypes: string[];

    constructor(public readonly typeFullName: string, typeDefinition: any) {
        super(typeFullName, typeDefinition);

        const acceptableFileTypesMetadata = this.properties[ALLOWED_FILE_EXTENSIONS] || [];
        this.originalAcceptableTypes = acceptableFileTypesMetadata;

        if (acceptableFileTypesMetadata) {
            if (acceptableFileTypesMetadata.length === 1 && acceptableFileTypesMetadata[0] === "*") {
                this.mediaFilterEnabled = false;
                this.acceptableMediaTypes = [];
                this.acceptableFileTypes = [];
            } else {
                this.acceptableFileTypes = acceptableFileTypesMetadata
                    .map(ext => {
                        if (ext.startsWith(".")) {
                            return ext.substring(1);
                        }

                        return ext;
                    });
                this.mediaFilterEnabled = true;
                this.acceptableMediaTypes = this.properties[ACCEPTABLE_MEDIA_TYPES] || [];
            }
        }

        this.provider = this.properties[RELATE_DATA_PROVIDER] || null;

        const fileSizeValue = this.properties[MAXIMUM_ALLOWED_SIZE] || 0;
        this.maxSize = Number(fileSizeValue);
    }

    get name(): string {
        const relationship = this.properties.relationship;
        if (!relationship) {
            return stringConstants.EMPTY_STRING;
        }

        const partner = relationship.partner;
        if (!partner) {
            return stringConstants.EMPTY_STRING;
        }

        return partner;
    }

    get allowedExtensionsRegEx(): RegExp {
        const regexbase = this.acceptableFileTypes.join("|");
        return new RegExp(`\\.(${regexbase})`);
    }

    get isVideo(): boolean {
        return this.setName === ENTITY_SET.VIDEOS;
    }
}

export class MetadataContainer {
    public modules: ModuleInfo = {};
    public entities: { [entitySetName: string]: Entity } = {};
    public entitiesByFullTypeName: { [fullTypeName: string]: Entity } = {};
    public propertyDefinitions: { [propertyType: string]: any } = {};
    public modulesAvailability: { [propertyType: string]: boolean } = {};
    public sitefinityVersion: string = stringConstants.EMPTY_STRING;
}

@Injectable()
export class MetadataStore {
    private storeSubject = new ReplaySubject<MetadataContainer>(1);
    private isInitialized = false;

    constructor(private http: HttpODataRequestWrapper) { }

    /**
     * @deprecated Avoid using this method since returned value may not be correct
     */
    getValue(): MetadataContainer {
        const wrapper = new BehaviorSubject(new MetadataContainer());
        this.storeSubject.subscribe((metadata) => {
            wrapper.next(metadata);
        });

        return wrapper.getValue();
    }

    initialize(): Observable<MetadataContainer> {
        if (!this.isInitialized) {
            this.isInitialized = true;

            this.http.get(META_SERVICE_PATH)
                .then(data => {
                    const storeBag = this.convertToContainer(data);

                    validateExtensionsVersusSitefinityVersions(storeBag.sitefinityVersion, EXTENSIONS_COMPATIBLE_SF_VERSIONS);

                    this.storeSubject.next(storeBag);
                    this.storeSubject.complete();
                });
        }

        return this.storeSubject.asObservable();
    }

    // TODO: should be precalculated and cached
    getEntitySetName(partnerFullName: string, container?: MetadataContainer): string {
        // TODO: this should be optimized
        const sets = (container || this.getValue()).entities;
        for (const entry in sets) {
            if (sets.hasOwnProperty(entry)) {
                const current = sets[entry];
                if (current.typeFullName === partnerFullName)
                    return entry;
            }
        }

        return null;
    }

    getRelationshipProviderName(entity: Entity, fieldName: string): string {
        const propMeta = entity.properties[fieldName];

        if (this.isRelationField(entity, fieldName)) {
            return propMeta[RELATE_DATA_PROVIDER];
        }

        return null;
    }

    // TODO: should be precalculated and cached
    getRelationshipPartnerTypeName(entity: Entity, fieldName: string): string {
        const propMeta = entity.properties[fieldName];

        if (this.isRelationField(entity, fieldName)) {
            let definitionPath = null;
            if (this.isMultipleField(entity, fieldName))
                definitionPath = propMeta.items.$ref;
            else
                definitionPath = propMeta.anyOf[0].$ref;
            const typeName = definitionPath.replace("#/definitions/", "");
            return typeName;
        }

        return null;
    }

    getDefaultFieldName(entitySetName: string): string {
        let defaultFieldName = null;

        this.initialize()
            .subscribe((metadataContainer: MetadataContainer) => {
                const entityMetadata = metadataContainer.entities[entitySetName];

                if (entityMetadata && entityMetadata.defaultFieldName) {
                    defaultFieldName = entityMetadata.defaultFieldName;
                }
            });

        return defaultFieldName;
    }

    isRelationField(entity: Entity, fieldName: string): boolean {
        const prop = entity.properties[fieldName];
        return prop.relationship !== undefined;
    }

    isMultipleField(entity: Entity, fieldName: string): boolean {
        const prop = entity.properties[fieldName].type;
        return prop === "array";
    }

    getPropertyMetadata(entitySetName: string, propName: string): any {
        const properties = this.getEntitiySetProperties(entitySetName);
        return properties[propName];
    }

    getDefinitionMetadata(fullDefinitionName: string): any {
        const container = this.getValue();
        return container.propertyDefinitions[fullDefinitionName];
    }

    convertToContainer(data): MetadataContainer {
        const metadataContainer = new MetadataContainer();
        metadataContainer.sitefinityVersion = data["sitefinity-version"];

        if (data.modules) {
            metadataContainer.modulesAvailability[INSIGHT] = data.modules[INSIGHT];
        }

        this.setEntities(data, metadataContainer);
        this.setPropertyDefinitions(data, metadataContainer);

        return Object.freeze(metadataContainer);
    }

    getEntity(setName: string): Entity {
        return this.getValue().entities[setName];
    }

    getAllContentTypeEntities(): Entity[] {
        const entities = this.getValue().entities;
        const entitiesResult: Entity[] = Object.values(entities).filter(currentEntity => SUPPORTED_CONTENT_TYPES_NAMESPACES.find(supportedEntity => currentEntity.typeFullName.startsWith(supportedEntity)));

        return entitiesResult;
    }

    getDynamicParentEntities(): Entity[] {
        const entities = this.getValue().entities;
        const parentEntities: Entity[] = Object.values(entities).filter(currentEntity => currentEntity.hasChildren && currentEntity.typeFullName.startsWith(DYNAMIC_TYPE_NAMESPACE));

        return parentEntities;
    }

    getEntityByFullTypeName(fullTypeName: string): Entity {
        return this.getValue().entitiesByFullTypeName[fullTypeName];
    }

    private getFields(entity: Entity, container: MetadataContainer): Array<Relation> {
        const fields: Array<Relation> = [];
        Object.keys(entity.properties).forEach(key => {
            if (this.isRelationField(entity, key)) {
                const typeFullName = this.getRelationshipPartnerTypeName(entity, key);
                const setName = this.getEntitySetName(typeFullName, container);
                const provider = this.getRelationshipProviderName(entity, key);
                fields.push({
                    propName: key,
                    setName: setName,
                    provider: provider,
                    typeFullName: typeFullName
                });
            } else {
                fields.push({
                    propName: key,
                    setName: null
                });
            }
        });

        return fields;
    }

    // TODO: remove
    private getEntitiySetProperties(entitySetName: string): any {
        const container = this.getValue();
        const currentSet = container.entities[entitySetName];

        return currentSet.properties;
    }

    private setEntities(data: any, metadataContainer: MetadataContainer) {
        const entitySetKeys = Object.keys(data.entityContainer.entitySets);
        const entityDict = new Map<string, string>();
        const entityCollection: Entity[] = [];

        entitySetKeys.forEach(entitySetName => {
            const entitySetDefinition = data.entityContainer.entitySets[entitySetName];
            const itemTypeFullName = entitySetDefinition.entityType.$ref.replace("#/definitions/", "");

            const typeDefinition = data.definitions[itemTypeFullName];

            // Add sort restrictions to Entity properties
            typeDefinition.properties[SORT_RESTRICTIONS] = entitySetDefinition[SORT_RESTRICTIONS];
            typeDefinition.properties[FILTER_RESTRICTIONS] = entitySetDefinition[FILTER_RESTRICTIONS];

            // types without modules
            const moduleName = typeDefinition.properties[MODULE_NAME];
            if (!moduleName) {
                return;
            }

            let module = metadataContainer.modules[moduleName];
            if (!module)
                module = metadataContainer.modules[moduleName] = { AccessibleTypes: [], Providers: [], ModuleTypes: [] };

            module.AccessibleTypes.push(entitySetName);

            let entity = metadataContainer.entities[entitySetName];
            if (!entity) {
                const isMedia = typeDefinition.hasOwnProperty("mediaEntity") && typeDefinition["mediaEntity"] === true;
                entity = isMedia ? new MediaEntity(itemTypeFullName, typeDefinition) : new Entity(itemTypeFullName, typeDefinition);
                entity.enabled = this.isSupportedModule(itemTypeFullName);
                entity.isMedia = isMedia;
                entity.isOpen = typeDefinition.hasOwnProperty("openType") && typeDefinition["openType"] === true;
                metadataContainer.entities[entitySetName] = entity;
                metadataContainer.entitiesByFullTypeName[itemTypeFullName] = entity;
                entityDict.set(entity.typeFullName, entitySetName);
                entityCollection.push(entity);
            }

            entity.setName = entitySetName;
        });

        for (const entity of entityCollection) {
            entity.childTypeNames.forEach(childType => {
                const childEntitySetName = entityDict.get(childType);
                const childEntity: Entity = metadataContainer.entities[childEntitySetName];

                if (childEntity) {
                    entity.children.push(childEntity.setName);
                    childEntity.parent = entity.setName;
                }
            });

            const fields = this.getFields(entity, metadataContainer);
            entity.relations = fields.filter(x => x.setName !== null);
            entity.primitives = fields.filter(x => x.setName === null).map(x => x.propName);
        }
    }

    private setPropertyDefinitions(data: any, metadataContainer: MetadataContainer) {
        Object.keys(data.definitions).forEach(definition => {
            const definitionObj = data.definitions[definition];
            if (definitionObj) {
                if (!definitionObj.hasOwnProperty("keys")) {
                    metadataContainer.propertyDefinitions[definition] = definitionObj;
                }
            }
        });
    }

    private isSupportedModule(itemTypeFullName: string): boolean {
        return SUPPORTED_TYPES_NAMESPACES.some(ns => itemTypeFullName.includes(ns));
    }
}
