import { finalize } from "rxjs/operators";
import { of } from "rxjs";
import { Component, OnInit } from "@angular/core";
import { SitefinityInsightTouchpointRequesterService } from "../../services/sitefinity-insight-touchpoints-requester.service";
import { Touchpoint } from "../../../../insight/entities/touchpoint";
import { ContentItemInfo } from "../../interfaces/content-item-info";
import { DataContext, DataContextComponent } from "../../../models/data-context-component";
import { ActivatedRoute } from "@angular/router";
import { DialogData, ModalWindowService } from "../../../services/modal-window.service";
import { InsightLostConnectionComponent } from "../insight-lost-connection/insight-lost-connection.component";
import { ConnectorService } from "../../services/connector.service";
import { SitefinityBaseUrl } from "../../services/sitefinity-base-url";
import { DEFAULT_INSIGHT_ADMIN_BACKEND_PAGE_URL, INSIGHT_ROUTES } from "../../insight.constants";

@Component({
    templateUrl: "./insight-cell.component.html",
    selector: "sf-insight-cell"
})
export class InsightCellComponent implements OnInit, DataContextComponent {
    context: DataContext;

    contentItemInfo: ContentItemInfo;

    loadingData = true;
    touchpoint: Touchpoint;
    httpError: any;
    insightSetupInSitefinityUrl: string;

    constructor(
        private decServerService: SitefinityInsightTouchpointRequesterService,
        private readonly connectorService: ConnectorService,
        private modalWindowService: ModalWindowService,
        private route: ActivatedRoute) {
        this.connectorService.getConnectorDetails().subscribe((sitefinityInsightConfiguration) => {
            this.insightSetupInSitefinityUrl = `${SitefinityBaseUrl.getUrl()}${sitefinityInsightConfiguration.DecAdminBackendPageUrl}`;
        }, error => {
           this.insightSetupInSitefinityUrl = `${SitefinityBaseUrl.getUrl()}${DEFAULT_INSIGHT_ADMIN_BACKEND_PAGE_URL}`;
        });
    }

    setCloseModalCallback(): void {
    }

    ngOnInit() {
        this.contentItemInfo = new ContentItemInfo(this.context.dataItem);

        this.loadingData = true;
        this.decServerService.getTouchpointByContent(this.contentItemInfo).pipe(
            finalize(() => this.loadingData = false))
            .subscribe((touchpoint: Touchpoint) => {
                this.touchpoint = touchpoint;
            }, (error) => {
                this.httpError = error;
            });
    }

    onClick() {
        const dialogData = new DialogData(
            {
                        type: null,
                        properties: {
                            externalTouchpointLoad$: of(this.touchpoint),
                            contentItemInfo: this.contentItemInfo,
                            notifyGridCellForNewTouchpointFunc: this.onTouchpointCreated.bind(this)
                        }
                    }
        );

        this.modalWindowService.setMapping(dialogData, INSIGHT_ROUTES.routeKey);
        this.modalWindowService.show(INSIGHT_ROUTES.routeKey, this.route.parent);
    }

    onErrorClick() {
        const dialogData = new DialogData(
            {
                type: InsightLostConnectionComponent,
                properties: {
                    insightSetupInSitefinityUrl: this.insightSetupInSitefinityUrl
                }
            }
        );
        this.modalWindowService.setMapping(dialogData, "custom");
        this.modalWindowService.show("custom", this.route.parent);
    }

    onTouchpointCreated(touchpoint: Touchpoint) {
        this.touchpoint = touchpoint;
    }
}
