import { MEDIA_TYPES, ENTITY_SET } from "./../../shared/services/metadata/meta-data-constants";
import { Component, OnInit, HostListener, AfterContentChecked, ElementRef, ViewChild, OnDestroy, ChangeDetectorRef, Inject } from "@angular/core";
import { MediaData } from "./media-data/media-data";
import { MediaSettings } from "./media.settings";
import { MediaDataFactory } from "./media-data/media-data.factory";
import { ModalWindowService, DialogData } from "../../shared/services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { LayoutService, DEFAULT_BOX_HEIGHT, DEFAULT_SMALL_BOX_HEIGHT } from "../services/layout.service";
import { DomSanitizer, SafeUrl } from "@angular/platform-browser";
import { MediaService, UploadFieldState } from "../services/media.service";
import { StatusType } from "../../../../../fields/field-status";
import { FilePickerComponent, FILE_PICKER } from "../file-picker.component";
import { MediaRecognizerService } from "./media-recognizer.service";
import { FilePickerViewMode } from "../file-picker-view-mode";
import { SelectorConstants } from "../../html/selector-constants";
import { CONTENT_SOURCE_NOT_AVAILABLE_WARNING, ANY_SITE_SOURCE_PROVIDER, DEFAULT_SITE_SOURCE_PROVIDER, stringConstants } from "../../../common-constants";
import { VALIDATOR_MESSAGES } from "../../../../../fields/common/validators/validators.constants";
import { Subscription } from "rxjs";
import { cloneObject, guid } from "../../../utils";
import { MediaEntity } from "../../shared/services/metadata/meta-data.store";
import { DataItem, FieldWithLimitations } from "../../content/dynamic-modules/interfaces";
import { ReorderableThumbsComponent } from "./reorderable-thumbs.component";
import { ScrollService } from "../../../services/scroll.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { EditNavigationService } from "../../shared/services/edit-navigation.service";
import { SiteDataStore } from "../../shared/services/metadata/site-data.store";
import { first } from "rxjs/operators";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { AppStore } from "../../../services/store/app-store";
import { MEDIA_SELECTORS } from "../../../services/store/selectors/selectors.media";

export const INITIAL_VIDEO_ROWS: number = 1;
export const INITIAL_IMAGE_ROWS: number = 2;

const BOX_SPACING: number = 5;
const STRETCHED_LOOK = "stretched";

@Component({
    selector: "sf-media",
    templateUrl: "./media.component.html"
})
export class MediaComponent extends ReorderableThumbsComponent<MediaSettings> implements OnInit, OnDestroy, AfterContentChecked {
    @ViewChild("wrapper", { static: true }) wrapper: ElementRef;
    allItems = [];
    mediaLayout = { boxes: [] };
    uploadLayout = { boxes: [] };
    mediaData: MediaData;
    isMultimedia: boolean;
    isVideo: boolean;
    previewUrl: string;
    thumbnailLook: string;
    thumbnailWrapperClass: string;
    allowedProviders: string[] = [];
    uniqueName: string;
    shouldImagesHaveMinWidth = true;

    errors = {
        [VALIDATOR_MESSAGES.UPLOAD_FAILED]: true
    };

    uploadErrors: string[] = [];

    protected skipDragScrollZones = true;

    private processedPendingItemsCount: number;
    private showAllMediaItems = false;
    private componentDataCache = new Map<number, ComponentData>();
    private openWindowSubscription: Subscription;

    constructor(private mediaDataFactory: MediaDataFactory,
                protected modalService: ModalWindowService,
                protected route: ActivatedRoute,
                private layoutService: LayoutService,
                private sanitizer: DomSanitizer,
                private mediaRecognizerService: MediaRecognizerService,
                private changeDetector: ChangeDetectorRef,
                scrollService: ScrollService,
                @Inject(WINDOW_TOKEN) window: Window,
                private editNavigationService: EditNavigationService,
                private siteDataStore: SiteDataStore,
                private appStore: AppStore,
                private mediaService: MediaService) {
        super(scrollService, window);
        this.processedPendingItemsCount = 0;
    }

    get multiple(): boolean {
        return this.settings ? !!this.settings.allowMultiple : false;
    }

    get hiddenMediaItems(): number {
        return this.mediaItems.length - this.mediaLayout.boxes.length;
    }

    @HostListener("window:scroll", ["$event"])
    onWindowScroll(event) {
        super.onWindowScroll(event);
    }

    ngOnInit(): void {
        super.ngOnInit();
        this.mediaData = this.mediaDataFactory.create(
            this.settings.type,
            this.settings.provider,
            this.settings.culture,
            this.settings.acceptableMediaTypes,
            this.settings.acceptableFileTypes,
            this.settings.mediaFilterEnabled,
            this.settings.maxSize
        );

        // this.mediaService.clearUploads();
        const uploadSubscription = this.appStore.pipe(MEDIA_SELECTORS.uploadsData).subscribe(jobs => {
            this.onUpload(jobs.items, jobs.uploadFieldState);
        });

        this.registerSubscription(uploadSubscription);

        this.recalculateLayout();

        this.isMultimedia = this.settings.type !== MEDIA_TYPES.DOCUMENT;
        this.isVideo = this.settings.type === MEDIA_TYPES.VIDEO;

        if (this.settings && this.settings.type && this.mediaData) {
            this.previewUrl = this.settings.openPickerWhenEmpty ? "Url" : this.mediaRecognizerService.getPreviewUrlProperty(this.mediaData.mediaEntityData.metadata.setName);
        }

        if (this.isMultimedia) {
            if (this.settings.openPickerWhenEmpty) {
                this.thumbnailLook = "svg";
            } else {
                this.thumbnailWrapperClass = "sf-media__stretched";
            }
        }

        this.uniqueName = `${this.settings.name}${(this.settings.dataItem && this.settings.dataItem.key) ? this.settings.dataItem.key : guid()}`;

        this.siteDataStore.getAllowedProviders(this.mediaData.mediaEntityData.metadata.setName).subscribe((providers) => {
            this.allowedProviders = providers;
        });

        if (this.settings && this.settings.openPickerWhenEmpty && (!this.value || this.value.length === 0)) {
            this.onChangeClick(null);
        }
    }

    ngAfterContentChecked(): void {
        if (this.mediaLayout.boxes.length === 0 && this.mediaItems.length > 0) {
            this.recalculateLayout();
        }
    }

    ngOnDestroy(): void {
        super.ngOnDestroy();
        if (this.openWindowSubscription) {
            this.openWindowSubscription.unsubscribe();
        }

        this.focus$.pipe(first()).subscribe((isFocused) => {
            if (isFocused) {
                this.modalService.close(this.route);
            }
        });
    }

    sanitize(url: string): SafeUrl {
        return this.sanitizer.bypassSecurityTrustUrl(url);
    }

    writeValue(value: any): void {
        if (!value) {
            value = [];
        }

        const isArray = Array.isArray(value);
        if (isArray) {
            value.forEach(item => {
                this.markTranslated(item);
                this.setProviderFromServer(item);
            });
        } else {
            this.markTranslated(value);
            this.setProviderFromServer(value);
        }

        super.writeValue(value);
        this.mediaItems = Array.isArray(value) ? value : [value];
        this.updateAllItems();

        setTimeout(() => {
            this.recalculateLayout();
        });
    }

    getRequiredErrorMessage(): Array<string> {
        if (this.status$.getValue().type === StatusType.Pending) {
            return [];
        }

        return [`${SelectorConstants.SELECT_BUTTON} ${this.mediaData.typeNameSingleCapitalized}`];
    }

    onUpload(jobs: any[], uploadFieldState: UploadFieldState): void {
        const uploads = [];
        jobs.filter(job => job.key === this.uniqueName).forEach((job, jobIndex) => {
            this.emitStatus({ type: StatusType.Pending });

            const { success, result } = job.upload;
            if (job.upload.success || job.upload.failure) {
                this.processedPendingItemsCount += 1;
            }

            if (success) {
                const index = this.mediaItems.findIndex(mediaItem => mediaItem.Id === result.Id);

                if (index < 0) {
                    const resultClone = cloneObject(result);
                    // To avoid index being serialized to JSON
                    Object.defineProperty(resultClone, "index", {
                        value: jobIndex,
                        enumerable: false
                    });

                    const mediaItems = this.mediaItems.concat(resultClone);

                    // Sort to preserve the order of uploaded files
                    mediaItems.sort((x, y) => {
                        if (x.index !== undefined) {
                            if (y.index !== undefined) {
                                return x.index - y.index;
                            } else {
                                return -1;
                            }
                        } else if (y.index !== undefined) {
                            return 1;
                        } else {
                            return 0;
                        }
                    });

                    this.writeValue(mediaItems);

                    this.mediaService.removeUploadById(job.upload.id);
                }
            } else {
                uploads.push(job.upload);
                if (job.upload.failure) {
                    this.emitStatus({ type: StatusType.Error, data: this.errors });
                }
            }
        });

        this.uploads = uploads;
        this.uploadErrors = this.getUploadErrors();
        if (!this.multiple && this.uploads.length && this.mediaItems.length) {
            this.writeValue([]);
        }

        this.updateAllItems();
        this.recalculateLayout();
        this.handleFocus(false);

        if (uploadFieldState.fieldName === this.uniqueName && this.processedPendingItemsCount === uploadFieldState.uploadedItemsCount) {
            this.emitStatus({ type: StatusType.Done });

            this.resetProcessedPendingItemsCount();
        }
    }

    onRemoveMediaClick(event: Event, removedMedia: any): void {
        event.preventDefault();
        event.stopImmediatePropagation();

        const mediaItems = this.mediaItems.filter(mediaItem => mediaItem.Id !== removedMedia.Id);
        this.writeValue(mediaItems);
        this.handleFocus(false);
    }

    onRemoveUploadClick(upload: any): void {
        this.mediaService.removeUploadById(upload.id);
        this.handleFocus(false);
        this.uploadErrors = this.getUploadErrors();

        if (upload.failure && !this.uploadErrors.length) {
            this.emitStatus({ type: StatusType.ErrorCleared, data: this.errors });
        }
    }

    onChangeClick(event: Event): void {
        if (event) {
            event.preventDefault();
        }

        this.onTouchedCallback();
        if (this.isEmptyMultimedia && !this.settings.allowAdd) {
            return;
        }

        let mediaItem;

        if (!this.multiple) {
            mediaItem = this.uploads[0] || this.mediaItems[0];
        }

        const componentData: ComponentData = {
            type: FilePickerComponent,
            properties: {
                multiple: this.multiple,
                value: this.mediaItems ? this.mediaItems.slice(0).map(x => DataItem.from(x, this.mediaData.mediaEntityData.metadata, x.provider, this.mediaData.mediaEntityData.culture)) : [],
                name: this.uniqueName,
                useLiveData: this.settings.useLiveData,
                allowCreate: this.settings.allowCreate,
                mediaEntityData: { metadata: this.mediaData.mediaEntityData.metadata.clone(), provider: this.mediaData.mediaEntityData.provider, culture: this.mediaData.mediaEntityData.culture },
                initialViewMode: this.getFilePickerComponentInitialViewMode(),
                sourceLibraryId: this.settings.sourceLibraryId,
                targetLibraryId: this.settings.targetLibraryId,
                useOnlySelectMode: this.settings.useOnlySelectMode,
                enableDamPicker: this.settings.canRelateDamAssets
            }
        };

        const providersCount = this.allowedProviders.filter(p => p !== ANY_SITE_SOURCE_PROVIDER && p !== DEFAULT_SITE_SOURCE_PROVIDER).length;
        if (this.settings.provider === ANY_SITE_SOURCE_PROVIDER && (providersCount > 1 || this.allowedProviders[0] === stringConstants.ASTERISK)) {
            componentData.properties.showProviderSelector = true;
        }

        const dialogData = new DialogData(componentData, (result) => {
            if (result && result.data) {
                if (mediaItem) {
                    this.uploads.pop();
                    this.mediaItems.pop();
                    this.mediaService.removeUploadById(mediaItem.id);
                }

                let data = [];
                if (Array.isArray(result.data)) {
                    data = result.data.map(x => {
                        const item = cloneObject(x.data);
                        item.provider = x.provider;
                        return item;
                    });
                } else {
                    const item = cloneObject(result.data.data);
                    item.provider = result.data.provider;
                    data = [item];
                }

                this.mediaItems = data;
                this.writeValue(data);
            } else if (this.settings.openPickerWhenEmpty
                && (!this.value || this.value.length === 0) //no previously selected
                && (!this.uploads || this.uploads.length === 0)) {// no uploads pending
                this.modalService.close(this.route);
            }
            // should unfocus field regardless of return results
            this.handleFocus(false);
        }, [], "-prompt");

        this.modalService.setMapping(dialogData, FILE_PICKER);
        this.modalService.open(this.route, FILE_PICKER);

        // TODO
        // this.openWindowSubscription = Observable.timer(100).subscribe(() => {

        // });

        this.handleFocus(true);
    }

    onRetryClick(): void {
        this.uploads.forEach(upload => {
            if (upload.failure) {
                this.retry(upload);
            }
        });
    }

    onShowAllMediaItemsClick(): void {
        this.showAllMediaItems = true;
        this.recalculateLayout();
    }

    retry(upload: any): void {
        this.mediaService.retryUpload(this.mediaData.mediaEntityData, upload);
    }

    uploadFailed(): boolean {
        const failure = this.uploads && this.uploads.some(mediaItem => mediaItem.failure);
        return failure;
    }

    getThumbnailLook(mediaItem: any) {
        let thumbnailLooks = null;

        if (this.thumbnailLook) {
            thumbnailLooks = this.thumbnailLook;
        }

        if (((mediaItem.Width > mediaItem.Height) && this.shouldImagesHaveMinWidth) || !this.shouldImagesHaveMinWidth) {
            thumbnailLooks = thumbnailLooks ? thumbnailLooks + " `${STRETCHED_LOOK}`" : STRETCHED_LOOK;
        }

        return thumbnailLooks;
    }

    onThumbnailClick(item: any) {
        const provider = item.provider;

        const dataItem = DataItem.from(item, this.mediaData.mediaEntityData.metadata, provider, this.settings.culture);
        const limitations: FieldWithLimitations = {
            filedName: this.settings.key,
            settings: {
                allowedFileExtensions: this.settings.acceptableFileTypes,
                maximumAllowedSize: this.settings.maxSize,
                acceptableMediaTypes: this.settings.acceptableMediaTypes
            }
        };

        this.editNavigationService.openDialogForRelatedDataAndLoadFieldData(this.mediaItems.map(x => x.Id), dataItem, this.route, limitations, false, null).subscribe((data) => {
            const index = data.findIndex(item => item.Id === dataItem.data.Id);
            const newItem = data[index];

            const copyItem = {};
            const value = this.getValue();
            const indexInValue = value.findIndex(item => item.Id === dataItem.data.Id);
            Object.assign(copyItem, value[indexInValue], newItem);

            const copy = cloneObject(value);
            copy.splice(indexInValue, 1, copyItem);
            this.writeValue(copy);
        });
    }

    onItemsAdd(data: any[]) {
        const newItems = data.filter(item => !this.mediaItems.find(x => x.Id === item.Id));
        if (!this.multiple) {
            this.mediaItems.length = 0;
        }
        const mediaItems = this.mediaItems.concat(newItems);
        this.writeValue(mediaItems);
    }

    onItemsChange(data: any[]) {
        this.writeValue(data);
    }

    onItemsRemove(items: any[]) {
        const newItems = this.mediaItems.slice(0);

        for (const item of items) {
            const index = newItems.indexOf(item);
            if (index > -1) {
                newItems.splice(index, 1);
            } else {
                this.onRemoveUploadClick(item.Upload);
            }
        }

        this.writeValue(newItems);
    }

    boxIdentity(index): number {
        return index;
    }

    getMediaComponentData(uploadsIndex: number) {
        const upload = this.uploads[uploadsIndex];
        if (!this.componentDataCache.has(upload.id)) {
            const properties = {
                src: upload.dataUrl,
                alt: upload.AlternativeText,
                type: upload.contentType,
                name: upload.name,
                size: upload.total,
                isMultimedia: this.isMultimedia,
                isVideo: this.isVideo
            };

            const mediaComponentData = this.mediaRecognizerService.getComponentData(properties);
            this.componentDataCache.set(upload.id, mediaComponentData);
        }

        return this.componentDataCache.get(upload.id);
    }

    getWarnings(): Array<string> {
        if (this.settings.mediaFilterEnabled && this.settings.acceptableMediaTypes.length === 0) {
            return ["File types allowed for this field do not match the ones set for Libraries in Advanced settings."];
        }

        if (!this.settings.allowView) {
            return [this.getNoPermissionMessage(this.settings.type)];
        }

        const areAnyProvidersEnabled = this.allowedProviders.length > 0;

        if (!areAnyProvidersEnabled || this.isCurrentProviderDisabled()) {
            return [CONTENT_SOURCE_NOT_AVAILABLE_WARNING];
        }

        return super.getWarnings();
    }

    handleReorderedNodes(data: any[]): void {
        this.writeValue(data);
    }

    @HostListener("window:resize")
    protected recalculateLayout(): void {
        const containerWidth = this.wrapper.nativeElement.offsetWidth;

        if (containerWidth > 0) {
            const images = this.uploads.concat(this.mediaItems);
            const targetRowHeight = this.multiple && !this.isVideo ? DEFAULT_SMALL_BOX_HEIGHT : DEFAULT_BOX_HEIGHT;
            const uploadLayout = this.layoutService.layout(this.uploads, containerWidth, targetRowHeight, BOX_SPACING, Number.POSITIVE_INFINITY, this.mediaData.mediaEntityData.metadata as MediaEntity);
            const uploadRows = Math.max(0, Math.floor(uploadLayout.containerHeight / targetRowHeight));

            const initialRowsToShow = (this.mediaData.mediaEntityData.metadata.setName === ENTITY_SET.VIDEOS ? INITIAL_VIDEO_ROWS : INITIAL_IMAGE_ROWS) + uploadRows;
            const actualRowsToShow = this.showAllMediaItems ? Infinity : initialRowsToShow;

            this.mediaLayout = this.layoutService.layout(images, containerWidth, targetRowHeight, BOX_SPACING, actualRowsToShow, this.mediaData.mediaEntityData.metadata as MediaEntity, 0, true);
            this.changeDetector.detectChanges();
        }
    }

    private setProviderFromServer(item: any) {
        if (item.Provider) {
            item.provider = item.Provider;
            delete item.Provider;
        }
    }

    private isCurrentProviderDisabled() {
        return (this.settings.provider
            && this.allowedProviders.indexOf(this.settings.provider) === -1
            && this.settings.provider !== ANY_SITE_SOURCE_PROVIDER);
    }

    get isEmptyMultimedia() {
        return this.isMultimedia && (!this.allItems.length || !this.mediaItems.length) && !this.uploads.length;
    }

    private getUploadErrors(): string[] {
        const errors: string[] = Array<string>();
        if (this.uploads) {
            this.uploads.forEach(upload => {
                if (upload.failure && !errors.find(x => x === upload.errorMessage)) {
                    errors.push(upload.errorMessage);
                }
            });
        }
        return errors;
    }

    private resetProcessedPendingItemsCount(): void {
        this.processedPendingItemsCount = 0;
    }

    private mapUpload(upload: any): any {
        const map: any = {
            Title: upload.data.Title,
            Failure: upload.failure,
            Loaded: 0,
            Upload: upload
        };

        if (upload.total !== 0) {
            map.Loaded = (100 * upload.loaded / upload.total).toFixed(0);
        }

        return map;
    }

    private updateAllItems() {
        this.allItems = this.mediaItems.concat(this.uploads.map(this.mapUpload)).map(item => this.markTranslated(item));
    }

    private markTranslated(item: any): void {
        const culture = this.settings.culture || (this.route.snapshot.data.itemData && this.route.snapshot.data.itemData.entityData.culture) || this.route.snapshot.data.dynamicItems.culture;
        const isTranslated = item.AvailableLanguages ? item.AvailableLanguages.some(lang => lang === culture) : true;
        item.isTranslated = isTranslated;
        return item;
    }

    private handleFocus(isFocused: boolean) {
        if (isFocused) {
            this.onFocus();
        } else {
            this.onBlur();
        }
    }

    private getFilePickerComponentInitialViewMode(): FilePickerViewMode {
        let result: FilePickerViewMode = null;
        const notAllowCreateAndMediaItems = !this.settings.allowCreate || (this.mediaItems && this.mediaItems.length > 0);

        if (this.settings.useOnlyUploadMode) {
            result = FilePickerViewMode.Upload;
        } else if (notAllowCreateAndMediaItems || this.settings.useOnlySelectMode) {
            result = FilePickerViewMode.Select;
        } else {
            result = null;
        }

        return result;
    }
}
