import { ClassProvider, Injectable, Inject } from "@angular/core";
import { DataItem, EntityData } from "../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../content/dynamic-modules/services/dynamic-item.store";
import { GridReloadService } from "../content/dynamic-modules/services/grid-reload.service";
import { GRID_EXTENDER_TOKEN, GridExtenderBase, TitleArgs, GridLoadMoreContext, GridActionContext } from "../shared/services/grid/grid-extender-base";
import { ModalWindowService } from "../shared/services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../shared/services/notification/notification.service";
import { Settings } from "../shared/services/settings.service";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { BackendTweaksStore } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { SortService } from "../shared/services/sort.service";
import { ContentFilterService } from "../shared/services/content-filter.service";
import { map, Observable } from "rxjs";
import { of } from "rxjs/internal/observable/of";
import { ExternalAppConfigService } from "../../app-config/external-app-config.service";
import { ItemsState, StateWrapper } from "../content/dynamic-modules/services/dynamic-item-store-state";
import { MetadataStore } from "../shared/services/metadata/meta-data.store";
import { ODataResult } from "../shared/services/errors/odata-result";
import { SortersResult } from "../content/dynamic-modules/components/sidebar/sorter/SortingStore";
import { Operation, OPERATION_NAMES } from "../shared/components/action-menu/operation.model";
import { DeleteCommand } from "../content/dynamic-modules/services/operations/commands/delete-command";
import { CompositeDeleteCommandExtender } from "../content/dynamic-modules/services/operations/commands/composite-delete-command-extender";
import { RESOLVE_NAMES } from "../content/constants";
import { ExecutionContext } from "../shared/commands/execution-context";
import { HttpClient } from "@angular/common/http";
import { ExportToExcelCommand } from "./export-to-excel-command";
import { getRouteDataRecursively } from "../content/dynamic-modules/components/helpers";
import { NavigateCommand } from "../content/dynamic-modules/services/operations/commands/navigate-command";
import { ActivatedRoute, Router } from "@angular/router";
import { FormResponsePreviewCommand } from "./form-response-preview.command";
import { COMMAND_NAMES } from "../content/dynamic-modules/components/commands";
import { CompositeOperationsProvider } from "../content/dynamic-modules/services/operations/operations-provider";
import { ColumnModel, Command } from "../../api";
import { SettingsSidebarSection } from "../content/dynamic-modules/components/sidebar/list-item-settings-sidebar.component";
import { GridNavigationProperties } from "../content/dynamic-modules/components/grid-navigation/grid-navigation-properties";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { GridNavigationComponent } from "../content/dynamic-modules/components/grid-navigation/grid-navigation.component";
import { capitalizeFirstLetter } from "../../utils";
import { FormHelpers } from "./form.helpers";
import { COLUMN_NAMES } from "../../constants/tests-constants.testHelpers";

const RESPONSES_ORDER = "SubmittedOn desc";

@Injectable()
export class FormResponsesGridExtender extends GridExtenderBase {
    constructor(
        private http: HttpClient,
        private metadataStore: MetadataStore,
        private compositeDeleteExtender: CompositeDeleteCommandExtender,
        private router: Router,
        settings: Settings,
        modalWindowService: ModalWindowService,
        dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        reloadService: GridReloadService,
        contentFilterService: ContentFilterService,
        sortService: SortService,
        backendTweaksStore: BackendTweaksStore,
        externalAppConfigService: ExternalAppConfigService,
        operationsProvider: CompositeOperationsProvider) {
        super(contentFilterService, dynamicItemStore, settings, sortService, backendTweaksStore, reloadService, modalWindowService, notificationService, externalAppConfigService, operationsProvider);
    }

    isSupportedType(entityData: EntityData): boolean {
        return FormHelpers.isFormResponseItem(entityData.metadata);
    }

    showFilters(entityData: EntityData): boolean {
        return false;
    }

    getTitle(args: TitleArgs): Observable<string> {
        return of(`${args.parentItem.data.Title} responses`);
    }

    getSidebarsExternalKeys(entityData: EntityData): string[] {
        return [entityData.metadata.typeFullName];
    }

    getSettingsSidebarSections(operations: Observable<Operation[]>, entityData: EntityData): Observable<SettingsSidebarSection[]> {
        return of([]);
    }

    hideSidebarLanguagesDropdown(entityData: EntityData): boolean {
        return true;
    }

    getSorters(entityData: EntityData): Observable<SortersResult> {
        return of(<SortersResult>{
            isLoading: false,
            sorters: [
                {
                    Name: "Last submitted on top",
                    Value: "SubmittedOn DESC"
                },
                {
                    Name: "First submitted on top",
                    Value: "SubmittedOn ASC"
                }]
        });
    }

    getNavigationComponentData(entityData: EntityData, gridNavProps: GridNavigationProperties): ComponentData {
        const data: ComponentData = {
            type: GridNavigationComponent,
            properties: { ...gridNavProps, title: `Back to ${capitalizeFirstLetter(entityData.metadata.parent)}` },
            updatePropertiesOnChange: true,
            removePreviousView: true
        };

        return data;
    }

    reloadItems(queryParams: { [key: string]: string }, parentId: string, entityData: EntityData, sortParam: string, dataFieldNames: string[]): Observable<StateWrapper> {
        const loadItemsArg = this.contentFilterService.getLoadArguments(queryParams, parentId, entityData, sortParam, dataFieldNames);
        loadItemsArg.order = RESPONSES_ORDER;

        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: entityData.culture,
            provider: entityData.provider,
        });

        const additionalQueryParams: { [key: string]: string } = {};
        if (sortParam)
            additionalQueryParams["order"] = sortParam;

        if (queryParams.search)
            additionalQueryParams["search"] = queryParams.search.replace("all,", "");

        const formName = entityData.metadata.setName.replace(`${ENTITY_SET.FORM_RESPONSES}-`, "");
        return this.dynamicItemStore.service.executeBoundFunction<ODataResult<FormEntryDto>>(formDataItem, `Default.GetFormEntries(formName='${formName}')`, undefined, additionalQueryParams).pipe((map(x => {
            const itemsState: ItemsState = {
                dataItems: x.value.map((y) => {
                    return DataItem.fromEntityData(y, entityData)
                }),
                totalCount: x["@odata.count"],
            };

            return StateWrapper.wrap(itemsState);
        })));
    }

    loadMore(ctx: GridLoadMoreContext): Observable<StateWrapper> {
        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: ctx.entityData.culture,
            provider: ctx.entityData.provider,
        });

        const formName = ctx.entityData.metadata.setName.replace(`${ENTITY_SET.FORM_RESPONSES}-`, "");
        const additionalQueryParams: { [key: string]: string } = {
            "skip": ctx.currentState.dataItems.length.toString(),
            "take": this.getTakeItemsCount(ctx.entityData).toString(),
            "search": ctx.executedSearchParameter,
            "order": ctx.order
        };

        return this.dynamicItemStore.service.executeBoundFunction<ODataResult<FormEntryDto>>(formDataItem, `Default.GetFormEntries(formName='${formName}')`, undefined, additionalQueryParams).pipe((map(x => {
            const itemsState: ItemsState = {
                dataItems: x.value.map((y) => {
                    return DataItem.fromEntityData(y, ctx.entityData)
                }),
                totalCount: x["@odata.count"],
            };

            itemsState.dataItems.splice(0, 0, ...ctx.currentState.dataItems);

            return StateWrapper.wrap(itemsState);
        })));
    }

    getDefaultSort(entityData: EntityData): string {
        return "SubmittedOn DESC";
    }

    getSidebarOperations(entityData: EntityData): Observable<Operation[]> {
        return of([]);
    }

    getListMainOperations(entityData: EntityData): Observable<Operation[]> {
        return of([]);
    }

    tryHandleAction(context: GridActionContext): Observable<boolean> {
        if (context.actionName == OPERATION_NAMES.delete) {
            const command = new DeleteCommand(this.dynamicItemStore, this.modalWindowService, this.compositeDeleteExtender);
            const data = {
                action: context.action,
                dataItem: context.item,
                entityData: context.item,
                siteData: getRouteDataRecursively(context.route.snapshot, RESOLVE_NAMES.siteDataStore)
            };

            const executionContext: ExecutionContext = {
                currentRoute: context.route,
                data: data,
                model: null
            }

            command.confirm(executionContext).subscribe(() => {
                command.execute(executionContext).subscribe(() => {
                    context.grid.reload();
                });
            });

            return of(true);
        } else if (context.actionName == OPERATION_NAMES.exportToExcel) {
            const data = {
                dataItem: context.item,
                entityData: context.item,
            };

            const executionContext: ExecutionContext = {
                currentRoute: context.route,
                data: data,
                model: null
            }

            new ExportToExcelCommand(this.http).execute(executionContext).subscribe();
            return of(true);
        } else if (context.actionName === OPERATION_NAMES.previewResponse || context.actionName === COMMAND_NAMES.selectionChanged) {
            const command = new FormResponsePreviewCommand(this.modalWindowService, this.router, this.backendTweaksStore);
            const route = context.route;
            const formEntryId = context.data?.entryId;
            const dataItem = context.item.data;
            let setName = context.item.metadata.setName;
            const commandData = { dataItem: dataItem, setName: setName, parentItem: context.data.parentItem }
            if (formEntryId) {
                const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
                const formDataItem = DataItem.emptyItem({
                    metadata: formDraftsEntity,
                    culture: context.data.entityData.culture,
                    provider: context.data.entityData.provider,
                });
                setName = context.data.entityData.metadata.setName;
                const formName = setName.replace(`${ENTITY_SET.FORM_RESPONSES}-`, "");
                return this.dynamicItemStore.service.executeBoundAction<FormEntryDto>(formDataItem, `${formEntryId}/Default.GetFormEntry(formName='${formName}')`, {}).pipe((map(entry => {
                    commandData.dataItem = entry;
                    commandData.setName = setName;
                    return this.executeCommand(command, route, commandData);
                }))) as any;
            } else {
                return this.executeCommand(command, route, commandData);
            }
        }

        return super.tryHandleAction(context);
    }

    getBulkOperations(entityData: EntityData, modifiedEntityData: EntityData, parent: DataItem): Observable<Operation[]> {
        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: entityData.culture,
            provider: entityData.provider,
        });

        return this.dynamicItemStore.service.executeBoundFunction<ODataResult<Operation>>(formDataItem, `Default.GetOperaitonsForBulk(parentId='${parent.data.Id}')`).pipe((map(x => {
            return x.value;
        })));
    }

    getListItemOperations(dataItem: DataItem, parent: DataItem): Observable<Operation[]> {
        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: dataItem.culture,
            provider: dataItem.provider,
        });

        return this.dynamicItemStore.service.executeBoundFunction<ODataResult<Operation>>(formDataItem, `Default.GetOperaitonsForItem(parentId='${parent.data.Id}')`).pipe((map(x => {
            return x.value;
        })));
    }

    executeNavigateCommand(router: Router, route: ActivatedRoute, dataItem: DataItem, entityData: EntityData, childSetName: string = null): Observable<any> {
        return new NavigateCommand(router)
            .execute({
                currentRoute: route,
                data: {
                    relativeTo: route.parent.parent.parent,
                    dataItem: dataItem,
                    metadata: entityData,
                    parentSetName: this.getParentSetName(entityData),
                    childSetName: childSetName,
                    navigateToGrid: dataItem && this.shouldNavigateToChildGrid(dataItem),
                    isChildNavigate: dataItem && dataItem.metadata.setName === entityData.metadata.setName
                },
                model: null
            });
    }

    modifyColumns(columns: ColumnModel[]): ColumnModel[] {
        columns.forEach(column => {
            if (column.name != COLUMN_NAMES.ACTIONS) {
                column.clickable = true;
                column.css += " -top-align";
            }
        });

        return columns;
    }

    private executeCommand(command: Command, route: ActivatedRoute, data: any) {
        return command.execute({
            currentRoute: route,
            data: {
                setName: data.setName,
                dataItem: data.dataItem,
                parentItem: data.parentItem
            },
            model: null
        });
    }
}

interface FormEntryDto {
    SubmittedOn: string;
    SourceSiteName: string;
    ReferralCode: string;
    Language: string;
    IpAddress: string;
}

export const FORM_RESPONSES_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: FormResponsesGridExtender
};
