import { Component, ViewChild, OnChanges, Input, Output, EventEmitter, ChangeDetectorRef, OnInit } from "@angular/core";
import { DateTimePickerSettings } from "../../../../../../../../fields/date-time/date-time-settings";
import { DateTimePickerComponent } from "../../../../../../../../fields/date-time/date-time-picker.component";
import { CustomFilterProperties, FilterData, FilterComponent } from "./filter-interfaces";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const START_DATE_FIELD: string = "startDateField";
const END_DATE_FIELD: string = "endDateField";
const SECONDS_UNTIL_DAY_END: number = 24 * 60 * 60 - 1;

@Component({
    selector: "sf-filter-date-range",
    templateUrl: "./filter-date-range.component.html"
})
export class FilterDateRangeComponent extends SfRxBase implements OnInit, OnChanges, FilterComponent {
    @Input() properties: CustomFilterProperties;
    @Input() filterParams: string[];
    @Output() filterValueSelected = new EventEmitter<FilterData>();
    @Output() valuesLoaded = new EventEmitter<string>();

    @ViewChild(START_DATE_FIELD, { static: false }) set startDateField(startDateField: DateTimePickerComponent) {
        this.initializeField(START_DATE_FIELD, startDateField);
        this.startProperties.currentField = startDateField;
    }

    @ViewChild(END_DATE_FIELD, { static: false }) set endDateField(endDateField: DateTimePickerComponent) {
        this.initializeField(END_DATE_FIELD, endDateField);
        this.endProperties.currentField = endDateField;
    }

    selecting: boolean = false;

    private endDate: Date = null;
    private startDate: Date = null;
    private startProperties: DateProperties;
    private endProperties: DateProperties;
    private changedInternal: boolean = false;
    private minDate: Date = new Date(1900, 0, 1);
    private maxDate: Date = new Date(2099, 11, 31);
    private datesSet: boolean = false;

    constructor(private detector: ChangeDetectorRef) {
        super();
    }

    ngOnInit(): void {
        this.startProperties = new DateProperties();
        this.endProperties = new DateProperties();

        this.endProperties.defaultValue = new Date();
        this.endProperties.defaultValue.setHours(0, 0, 0, 0);

        this.startProperties.defaultValue = new Date(this.endProperties.defaultValue);
        this.startProperties.defaultValue.setMonth(this.endProperties.defaultValue.getMonth() - 1);

        this.startProperties.settings = this.getSettings();
        this.endProperties.settings = this.getSettings();
    }

    ngOnChanges(): void {
        this.populateDates();
        this.selecting = false;
    }

    get hasDates(): boolean {
        return !!this.startDate && !!this.endDate;
    }

    get hasValidRange(): boolean {
        if (this.hasDates && this.isDateValid(this.startDate) && this.isDateValid(this.endDate) && this.startDate <= this.endDate) {
            return true;
        }

        return false;
    }

    toggleSelecting() {
        this.selecting = !this.selecting;
    }

    onClearFilter(skipEmit?: boolean) {
        this.startDate = null;
        this.endDate = null;
        this.datesSet = false;
        this.updateSettings();
        this.selecting = false;

        if (!skipEmit) {
            this.filterValueSelected.emit({
                name: this.properties.filterName,
                keys: []
            });
        }
    }

    onSelectFilter() {
        if (this.hasValidRange) {
            this.onFilterChanged(this.properties.filterName, this.startDate, this.endDate);
            this.toggleSelecting();
            this.datesSet = true;
        }
    }

    onOutsideClick(event) {
        if (this.startProperties.currentField && !this.startProperties.currentField.isOpen && this.endProperties.currentField && !this.endProperties.currentField.isOpen) {
            if (!this.datesSet) {
                this.onClearFilter(true);
            } else {
                this.populateDates();
                this.selecting = false;
            }
        }
    }

    private updateSettings(): void {
        this.startProperties.settings.minValue = this.minDate;
        this.startProperties.settings.maxValue = this.isDateValid(this.endDate) ? this.endDate : this.maxDate;

        this.endProperties.settings.minValue = this.isDateValid(this.startDate) ? this.startDate : this.minDate;
        this.endProperties.settings.maxValue = this.maxDate;
    }

    private getSettings(): DateTimePickerSettings {
        const fieldSettings = new DateTimePickerSettings(this.properties.filterName, false);
        fieldSettings.showTitle = false;

        return fieldSettings;
    }

    private populateDates(): void {
        this.startDate = null;
        this.endDate = null;

        const value: string[] = this.filterParams;
        if (value && value.length) {
            this.datesSet = true;
            this.startDate = new Date(value[0]);
            this.endDate = new Date(value[1]);

            if (this.endDate) {
                this.endDate.setSeconds(this.endDate.getSeconds() - SECONDS_UNTIL_DAY_END);
            }

            if (!this.hasValidRange) {
                this.startDate = null;
                this.endDate = null;
                this.datesSet = false;
            }

            this.valuesLoaded.emit(this.properties.filterName);
        }
    }

    private initializeField(key: string, field: DateTimePickerComponent): void {
        if (!field)
            return;

        const date = this.getDateOrDefault(key);
        field.writeValue(date);
        this.updateSettings();

        field.registerOnChange((date: Date) => {
            this.updateDate(key, date);
        });

        this.detector.detectChanges();
    }

    private onFilterChanged(filterName: string, start: Date, end: Date): void {
        const endDateIncluding = new Date(end);
        endDateIncluding.setSeconds(endDateIncluding.getSeconds() + SECONDS_UNTIL_DAY_END);

        this.filterValueSelected.emit({
            name: filterName,
            keys: [start.toISOString(), endDateIncluding.toISOString()]
        });
    }

    private updateDate(key: string, date: Date): void {
        if (this.changedInternal) {
            this.changedInternal = false;
            return;
        }

        if (key === START_DATE_FIELD) {
            this.startDate = date;
            this.endProperties.settings.minValue = this.isDateValid(date) ? date : this.minDate;

            // triggers validation for the other field - the object has to be different
            if (this.hasValidRange) {
                this.changedInternal = true;
                this.endProperties.currentField.writeValue(new Date(this.endDate));
            }
        } else {
            this.endDate = date;
            this.startProperties.settings.maxValue = this.isDateValid(date) ? date : this.maxDate;

            if (this.hasValidRange) {
                this.changedInternal = true;
                this.startProperties.currentField.writeValue(new Date(this.startDate));
            }
        }
    }

    private getDateOrDefault(key: string): Date {
        if (key === START_DATE_FIELD) {
            if (!this.startDate) {
                this.startDate = this.startProperties.defaultValue;
            }

            return this.startDate;
        }

        if (!this.endDate) {
            this.endDate = this.endProperties.defaultValue;
        }

        return this.endDate;
    }

    private isDateValid(date: Date) {
        return date && this.minDate <= date && date <= this.maxDate;
    }
}

class DateProperties {
    defaultValue: Date;
    settings: DateTimePickerSettings;
    currentField: DateTimePickerComponent;
}
