import { Injectable, ClassProvider } from "@angular/core";
import { Observable, of, ReplaySubject } from "rxjs";
import { HierarchicalService, HIERARCHICAL_SERVICE_TOKEN, RESULT_COUNT } from "../../shared/services/hierarchical-service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { createQuery } from "../../../services/query";
import { LoadItemsResponse, LoadItemsData, DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { TaxonomySettings } from "../../taxonomy/taxonomy.settings";
import { stringConstants } from "../../../common-constants";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { FACET_SINGULAR_NAME } from "../../taxonomy/facet-search-taxa/facet-taxa.component";


@Injectable()
export class HierarchicalFacetsService extends HierarchicalService {
    constructor(
        protected dynamicItemService: DynamicItemService
    ) {
        super(dynamicItemService);
    }

    private dataItems: DataItem[] = [];
    private dataItems$: ReplaySubject<DataItem[]> = new ReplaySubject(1);

    findFacetByFieldName(fieldName: string) {
        const dataItem = this.dataItems.find(i => i.data.FieldName === fieldName);

        return dataItem;
    }

    showStatusIcons(): boolean {
        return false;
    }

    isHierarchical(type: string): boolean {
        return false;
    }

    getSetName(): string {
        // we resolve it to flat taxa in order to render the chip like component (facet-taxa.component.ts)
        return ENTITY_SET.FLAT_TAXA;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return FACET_SINGULAR_NAME === entityData.metadata.singularName;
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return of();
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string, isCreate: boolean): Observable<LoadItemsResponse> {
        if (value) {
            const result = value.map(i => DataItem.from({ FieldName: i, Id: i }, null, stringConstants.EMPTY_STRING, null))

            return of(<LoadItemsResponse>({
                totalCount: 1,
                dataItems: result,
                entityData: entityData
            }));
        }

        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[], editItemId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();

        this.dataItems$.subscribe(dataItems => {
            const slicedDataItems = dataItems.slice(0, RESULT_COUNT);

            const itemsResponse = <LoadItemsResponse>({
                totalCount: slicedDataItems.length,
                dataItems: slicedDataItems,
                entityData: entityData
            });

            result$.next(itemsResponse);
        })

        return result$;
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string, taxonId?: string): Observable<LoadItemsResponse> {
        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings, taxonId?: string, isCreate?: boolean): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();

        const searchText = info.searchText.toLowerCase();
        const filterDataItems = this.dataItems.filter(items => items.data.FieldName.toLowerCase().startsWith(searchText) || items.data.FieldName.toLowerCase().includes(searchText));

        const itemsResponse = <LoadItemsResponse>({
            totalCount: filterDataItems.length,
            dataItems: filterDataItems,
            entityData: entityData
        });

        result$.next(itemsResponse);

        return result$;
    }

    getModalItems(entityData: EntityData, taxaId: string, taxonId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();

        this.dataItems$.subscribe(dataItems => {

            const itemsResponse = <LoadItemsResponse>({
                totalCount: dataItems.length,
                dataItems: dataItems,
                entityData: entityData
            })

            result$.next(itemsResponse);
        })

        return result$;
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();
        let query = createQuery();

        if (info.searchText) {
            query = query.search(info.searchText);
        }

        const searchText = info.searchText.toLowerCase();
        const filterDataItems = this.dataItems.filter(items => items.data.FieldName.toLowerCase().startsWith(searchText) || items.data.FieldName.toLowerCase().includes(searchText)).slice(0, loadingData.take);

        const itemsResponse = <LoadItemsResponse>({
            totalCount: filterDataItems.length,
            dataItems: filterDataItems,
            entityData: loadingData.entityData
        });

        result$.next(itemsResponse);

        return result$;
    }

    setDataItems(newDataItems: any): void {
        this.dataItems = [];
        const dataItemsToAdd = []

        newDataItems.forEach(i => {
            const facetName = i.FacetableFieldNames[0];
            if (this.dataItems.filter(d => d.data.FieldName === facetName).length === 0) {
                dataItemsToAdd.push(DataItem.from({ FieldName: facetName, Id: facetName, FacetableFieldType: i.FacetableFieldType, FacetableFieldLabels: i.FacetableFieldLabels }, null, stringConstants.EMPTY_STRING, null));
            }
        });

        if (dataItemsToAdd.length > 0) {
            this.dataItems.push(...dataItemsToAdd)
            this.dataItems$.next(this.dataItems);
        }
    }
}

export const HIERARCHICAL_FACETS_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalFacetsService
};
