import { Input, EventEmitter, Component, Output } from "@angular/core";
import { EntityData, DataItem } from "../content/dynamic-modules/interfaces";

@Component({
    selector: "sf-library-select",
    templateUrl: "./library-select.component.html"
})
export class LibrarySelectComponent {
    @Input() libraries: DataItem[];
    @Input() mediaEntityData: EntityData;
    @Input() selectable: boolean = true;
    @Input() value: DataItem[] = [];
    @Output() clickLibrary = new EventEmitter();
    @Output() selectLibrary = new EventEmitter();

    onClickLibrary(library) {
        this.clickLibrary.next(library);
    }

    onSelectLibrary(library: DataItem) {
        this.selectLibrary.next(library);
    }

    isSelected(library: DataItem) {
        return this.value.findIndex(d => d.data.Id === library.data.Id) >= 0;
    }
}
