import { AfterViewInit, Directive, ElementRef, EventEmitter, OnDestroy, Output } from "@angular/core";

@Directive({
    selector: "[sfRespondToVisibility]",
    exportAs: "sfRespondToVisibility"
})
export class RespondToVisibility implements AfterViewInit, OnDestroy {
    @Output() elementIsVisible: EventEmitter<HTMLElement> = new EventEmitter();
    @Output() elementIsHidden: EventEmitter<HTMLElement> = new EventEmitter();
    private observer: IntersectionObserver;

    constructor(private el: ElementRef) {
    }

    ngAfterViewInit(): void {
        this.respondToVisibility(this.el.nativeElement, this.onChangeVisibility);
    }

    respondToVisibility(element, callback): void {
        this.observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.intersectionRatio > 0) {
                    callback(element, this.elementIsVisible);
                } else {
                    callback(element, this.elementIsHidden);
                }
            });
        });

        this.observer.observe(element);
    }

    onChangeVisibility(element, emitter): void {
        emitter.next(element);
    }

    ngOnDestroy(): void {
        this.observer.disconnect();
    }
}
