import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../../fields";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";
import { FIELD_FRIENDLY_NAME } from "../../../../../fields/common/common-constants";

@Component({
    selector: "sf-taxonomy-type-choice-readonly",
    templateUrl: "./taxonomy-type-choice-readonly.component.html"
})
export class TaxonomyTypeChoiceReadonlyComponent extends FieldBase implements OnInit {
    selectionTitle: string;
    ngOnInit() {
        const choiceSettings = this.settings as ChoiceSettings;
        const selectedValue = this.getValue();
        const selection = (choiceSettings.choices).find(x => x.Name === selectedValue);
        if (selection) {
            this.selectionTitle = selection[FIELD_FRIENDLY_NAME] ? selection[FIELD_FRIENDLY_NAME] : selection.Name;
        }
    }
}
