import { Component, Inject, Input, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { BehaviorSubject } from "rxjs";
import { TreeConfig } from "../../../../../../fields";
import { DELETED } from "../../../../../../fields/resolvers/base-status.resolver";
import { stringConstants } from "../../../../common-constants";
import { BundleDataService, BUNDLE_DATA_OPERATIONS } from "../../../../services/bundle-data.service";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";
import { Properties } from "../../fields.constants";
import { DataContextComponent, DataContext } from "../../models/data-context-component";
import { ENTITY_SET } from "../../services/metadata/meta-data-constants";
import { DialogData, ModalWindowService } from "../../services/modal-window.service";
import { ModalListComponent } from "../modal-list/modal-list.component";
@Component({
    selector: "sf-shared-in",
    templateUrl: "./shared-in.component.html"
})
export class SharedInComponent extends SfRxBase implements OnInit, DataContextComponent {
    @Input() context: DataContext;
    @Input() showBadge: boolean = true;
    get count(): number {
        return this.countInternal;
    }
    @Input() set count(count: number) {
        if (count) {
            this.badgeLook += " positive";
        }

        this.countInternal = count;
    }
    @Input() isLoading = true;
    @Input() showNotUsedLabel = false;
    @Input() useParentRouteForNavigation: boolean;
    public badgeLook: string = "ellipse";
    public tooltip: string;
    private sources: {Name: string, Value: string}[];
    private countInternal: number = 0;

    constructor(private route: ActivatedRoute,
                private bundleDataService: BundleDataService,
                private modalService: ModalWindowService,
                @Inject(WINDOW_TOKEN) private windowProvider: Window) {
        super();
    }

    ngOnInit() {
        if (this.context) {
            if (this.isContentType()) {
                this.getResponseFromService();
            } else if (this.isTemplatesType()) {
                this.getDataFromItem();
            }
        }
    }

    public onClick(): void {
        const count = new BehaviorSubject<number>(this.count);
        const treeConfig = {
            status: true,
            showBreadcrumb: true,
            noSelection: true,
            clickable: true,
            previewUrl: true
        };

        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                contentLook: "medium",
                action: this.isContentType() ? "Default.SharedIn()" : "Default.UsedOnPages()",
                actionTitle: this.getTitle(),
                dataItem: this.context.dataItem,
                count,
                showDataItemTitle: true,
                template: null,
                listLook: "actions-on-hover",
                tabsConfig: this.generateTabs(treeConfig),
                onViewNodeFunc: this.viewNodeCliked.bind(this),
                sourceSelector: this.generateSourceSelector()
            }
        };

        const dialogData = new DialogData(componentData);
        this.modalService.setMapping(dialogData, "sharedIn");
        this.modalService.show("sharedIn", this.modalService.currentActivityStatus.active || this.useParentRouteForNavigation ? this.route.parent : this.route);
    }

    private generateTabs(treeConfig: TreeConfig) {
        let tabs = [];

        if (this.isContentType()) {
            tabs = [
                {
                    title: "Pages",
                    noItemsLabel: "Pages sharing content block will appear here",
                    treeConfig,
                    itemsFilter: x => x.IsPage,
                    itemsModifier: x => {
                        x.isTranslated = true;
                        x.showViewUrl = x.DisplayStatus[0].Name !== DELETED;
                        x.isSelectionDisabled = x.DisplayStatus[0].Name === DELETED;
                        x.removeBreadcrumbPrefix = x.DisplayStatus[0].Name === DELETED;
                    }
                },
                {
                    title: "Templates",
                    noItemsLabel: "Templates sharing content block will appear here",
                    treeConfig: Object.assign({}, treeConfig, { showBreadcrumb: false }),
                    itemsFilter: x => !x.IsPage,
                    itemsModifier: x => x.isTranslated = true
                }];
        } else {
            this.sources.forEach(site => {
                tabs.push({
                    title: null,
                    treeConfig,
                    noItemsLabel: "Pages using this template will appear here",
                    itemsFilter: x => x.IsPage && x.SiteId === site.Value,
                    itemsModifier:  x => {
                        x.isTranslated = true;
                        x.showViewUrl = x.DisplayStatus[0].Name !== DELETED;
                        x.isSelectionDisabled = x.DisplayStatus[0].Name === DELETED;
                        x.removeBreadcrumbPrefix = x.DisplayStatus[0].Name === DELETED;
                    }
                });
            });
        }

        return tabs;
    }

    private viewNodeCliked(clickedItem) {
        const itemData = clickedItem.data ? clickedItem.data.dataItem || clickedItem.data : clickedItem;

        if (itemData.Url) {
            const redirect = this.windowProvider.open(stringConstants.EMPTY_STRING, itemData.Url);
            redirect.location.href = itemData.Url;
        }
    }

    private getResponseFromService() {
        const serviceSubscription = this.bundleDataService.responses.pipe().subscribe(res => {
            if (!res) {
                return;
            }

            if (res.cleanRequest) {
                this.isLoading = true;
            }

            const sharedInStoreData = this.bundleDataService.data[BUNDLE_DATA_OPERATIONS.SHARED_IN_COUNT];
            if (sharedInStoreData && sharedInStoreData[this.context.dataItem.key] && sharedInStoreData[this.context.dataItem.key].data) {
                    const responseData = sharedInStoreData[this.context.dataItem.key].data;
                    this.count = responseData ? responseData.value : 0;
                    this.isLoading = false;
            }
        });

        this.registerSubscription(serviceSubscription);
    }

    private getDataFromItem() {
        const data: {Count: number, Tooltip: string, Sites: {Id: string, Title: string}[]} = this.context.dataItem.data[Properties.PAGES_COUNT];
        this.count = data.Count;
        this.tooltip = data.Tooltip;
        this.sources = data.Sites.map(x => {return {Name: x.Title, Value: x.Id}; });
        this.isLoading = false;
    }

    private generateSourceSelector() {
        return !this.isContentType() ? {
            label: "Sites",
            settings: { choices: this.sources }
        } : null;
    }

    private getTitle() {
        return this.isContentType() ? "Pages sharing content block" : "Pages using template";
    }

    private isContentType() {
        return this.context.dataItem.metadata.setName === ENTITY_SET.CONTENT_ITEMS;
    }

    private isTemplatesType() {
        return this.context.dataItem.metadata.setName === ENTITY_SET.TEMPLATES;
    }
}
