import { ClassProvider, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { HierarchicalService, ID_KEY, LAST_MODIFIED_KEY, RESULT_COUNT, TITLE_KEY, HIERARCHICAL_SERVICE_TOKEN } from "../../../shared/services/hierarchical-service";

import { LoadItemsResponse, LoadItemsByKeysData, LoadItemsData, DynamicItemService } from "./dynamic-item.service";
import { EntityData } from "../interfaces";
import { createQuery } from "../../../../services/query";
import { TaxonomySettings } from "../../../taxonomy";
import { ServiceInfo } from "../../../../../../fields/selector/selector.component";
import { SORT_ORDER } from "../../constants";
import { ContentFilterService } from "../../../shared/services/content-filter.service";
@Injectable()
export class HierarchicalDynamicItemService extends HierarchicalService {
    public setName: string;
    public singularName: string;
    constructor(protected dynamicItemService: DynamicItemService, private contentFilterService: ContentFilterService) {
        super(dynamicItemService);
    }

    showStatusIcons(): boolean {
        return false;
    }

    isHierarchical(type: string): boolean {
        return true;
    }

    getSetName(): string {
        return this.setName;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return this.singularName === entityData.metadata.singularName;
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        let query = createQuery().where().and().or();

        if (value) {
            value.forEach(id => query = query.eq(ID_KEY, id));
        }

        query = query.done().done().done() as any;

        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                take: value ? value.length : null,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                query,
                siteId: this.siteId
            });
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[]): Observable<LoadItemsResponse> {
        const query = createQuery();
        const orderByProperty = entityData.metadata.properties.hasOwnProperty(LAST_MODIFIED_KEY) ? LAST_MODIFIED_KEY : entityData.metadata.defaultFieldName;

        const data: LoadItemsData = {
            entityData: entityData,
            fallbackProperties: [entityData.metadata.defaultFieldName],
            query,
            order: `${orderByProperty} ${SORT_ORDER.DESCENDING}`,
            take: RESULT_COUNT
        };

        if (settings.allowMultiple && value) {
            data.itemsToExclude = { key: ID_KEY, value: value.map(x => x) };
        }

        return this.dynamicItemService.getItemList(data);
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        const query = createQuery()
            .where()
            .and()
            .eq(ID_KEY, taxaId)
            .done()
            .done();

        return this.dynamicItemService
            .getItemListBatch({
                entityData: entityData,
                query,
                order: `${TITLE_KEY} ${SORT_ORDER.ASCENDING}`,
                take: info.take,
                skip: info.skip,
                fallbackProperties: [entityData.metadata.defaultFieldName]
            });
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings): Observable<LoadItemsResponse> {
        let query = createQuery().where();
        const orderByProperty = entityData.metadata.properties.hasOwnProperty(TITLE_KEY) ? TITLE_KEY : entityData.metadata.defaultFieldName;

        if (info.searchText) {
            query = this.contentFilterService.applySearch(info.searchText, entityData, query);
        }

        query = query.done() as any;

        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                query,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                order: `${orderByProperty} ${SORT_ORDER.ASCENDING}`,
                take: info.take,
                skip: info.skip
            });
    }

    getModalItems(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        const orderByProperty = entityData.metadata.properties.hasOwnProperty(LAST_MODIFIED_KEY) ? LAST_MODIFIED_KEY : entityData.metadata.defaultFieldName;

        const loadItemsByKeysData: LoadItemsByKeysData = {
            entityData: entityData,
            fallbackProperties: [entityData.metadata.defaultFieldName],
            keys: [taxaId],
            keyProperty: ID_KEY,
            order: `${orderByProperty} ${SORT_ORDER.ASCENDING}`
        };

        let query: any = createQuery();
        if (taxaId) {
            query = query.where()
                .and()
                .eq(ID_KEY, taxaId)
                .done()
                .done();
        }

        loadItemsByKeysData.query = query;

        return this.dynamicItemService
            .getItemsByKeys(loadItemsByKeysData);
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData): Observable<LoadItemsResponse> {
        let searchQuery = this.getSearchQuery(info.searchText, info.taxaId, loadingData.entityData);
        if (info.idsToExclude) {
            info.idsToExclude.forEach(id => {
                searchQuery = searchQuery.ne(ID_KEY, id);
            });
        }
        searchQuery = searchQuery.done().done() as any;

        loadingData.query = searchQuery;
        loadingData.order = `${loadingData.entityData.metadata.defaultFieldName} ${SORT_ORDER.ASCENDING}`;

        return this.dynamicItemService.getItemList(loadingData);
    }

    private getSearchQuery(searchParameter: string, taxaId: string, entityData: EntityData) {
        let query = createQuery().where()
            .and();

        if (taxaId) {
            query
                .eq(ID_KEY, taxaId);
        }

        if (searchParameter) {
            query = this.contentFilterService.applySearch(searchParameter, entityData, query);
        }

        return query;
    }
}

export const HIERARCHICAL_DYNAMIC_ITEM_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalDynamicItemService
};
