import { SelectorConstants, NODE_NAMES } from "./../../selector-constants";
import { Injectable } from "@angular/core";
import { ensureTrailingBreaks, removeTrailingBreaks, isImageHyperlink } from "../immutable.helpers";
import { stringConstants } from "../../../../common-constants";
import { extractSafeUrl } from "../../../../utils";

const SF_IMAGE_UPLOAD_IN_PROGRESS = "-upload-progress";
export const SF_IAMGE_UPLOAD_FAILED = "-sf-txt-failure";
const SF_IAMGE_UPLOAD_FAILED_PROGRESSBAR = "-failure";
const SF_IMAGE_CLASS = "sf-media";
const CONTENTEDITABLE_STATE = "false";
const SF_PROGRESSBAR_CLASS = "sf-media__progress";
const WRAPPER_PREFIX = "Wrapper";
const PROGRESSBAR_MIN_VALUE = 0o000;
const PROGRESSBAR_MAX_VALUE = 100;
const CANCEL_UPLOAD_BUTTON_CLASS = "sf-media__remove sf-button -small -circle -icon";
const CANCEL_UPLOAD_ICON_CLASS = "sf-icon sf-fa sf-fa-times -normal -size-m sf-button__icon -left -sf-disabled";
const ATTRIBUTE_DATA = "data";

@Injectable()
export class ImageHelper {
    private _selectedImage: HTMLImageElement;

    get selectedImage(): HTMLImageElement {
        return this._selectedImage;
    }

    createImage(img: any, isLoading: boolean = false, progressBarId: any = null) {
        const image = document.createElement(NODE_NAMES.IMAGE_ELEMENT) as HTMLImageElement;
        image.src = img.Url || extractSafeUrl(img.dataUrl) || img.content;

        image.setAttribute(SIZE_ATTRIBUTE, img.TotalSize || img.total);
        image.setAttribute(SelectorConstants.SF_IMMUTABLE, stringConstants.EMPTY_STRING);
        const alternativeText = img.AlternativeText || (img.data ? img.data.AlternativeText : null);

        image.alt = alternativeText ? alternativeText : stringConstants.EMPTY_STRING;

        if (isLoading) {
            const wrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
            const innerWrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
            const progress = document.createElement(NODE_NAMES.PROGRESS_ELEMENT) as HTMLProgressElement;
            const cancelUploadButton = document.createElement(NODE_NAMES.BUTTON_ELEMENT);
            const closeUploadIcon = document.createElement(NODE_NAMES.ICON_ELEMENT);

            wrapper.id = WRAPPER_PREFIX + progressBarId;
            wrapper.contentEditable = CONTENTEDITABLE_STATE;

            innerWrapper.classList.add(SF_IMAGE_CLASS, SF_IMAGE_UPLOAD_IN_PROGRESS);

            progress.classList.add(SF_PROGRESSBAR_CLASS);
            progress.id = progressBarId;
            progress.max = PROGRESSBAR_MAX_VALUE;
            progress.value = PROGRESSBAR_MIN_VALUE;

            cancelUploadButton.className = CANCEL_UPLOAD_BUTTON_CLASS;
            cancelUploadButton.setAttribute(ATTRIBUTE_DATA, WRAPPER_PREFIX + progressBarId);
            closeUploadIcon.className = CANCEL_UPLOAD_ICON_CLASS;
            cancelUploadButton.appendChild(closeUploadIcon);

            innerWrapper.appendChild(image);
            innerWrapper.appendChild(progress);
            innerWrapper.appendChild(cancelUploadButton);

            wrapper.appendChild(innerWrapper);
            return ensureTrailingBreaks(wrapper.outerHTML);
        } else {
            return image.outerHTML;
        }
    }

    handleImageFailedUpload(image: any) {
        const failedMessage = document.createElement(NODE_NAMES.DIV_ELEMENT);

        failedMessage.innerText = image.errorMessage;
        failedMessage.classList.add(SF_IAMGE_UPLOAD_FAILED);

        const progressBar = document.getElementById(image.imageId);
        progressBar.classList.add(SF_IAMGE_UPLOAD_FAILED_PROGRESSBAR);

        const wrapper = progressBar.parentElement.parentElement;

        wrapper.appendChild(failedMessage);
    }

    handleImageSuccessUpload(element: any) {
        const innerWrapper = element.parentElement;
        const wrapper = innerWrapper.parentElement;
        const removeButton = innerWrapper.querySelector(NODE_NAMES.BUTTON_ELEMENT);
        const progressbar = innerWrapper.querySelector(NODE_NAMES.PROGRESS_ELEMENT);

        innerWrapper.removeChild(removeButton);
        innerWrapper.removeChild(progressbar);
        removeTrailingBreaks(wrapper);

        this.unwrap(wrapper);
        this.unwrap(innerWrapper);
    }

    unwrap(wrapper: HTMLElement) {
        const docFrag = document.createDocumentFragment();

        while (wrapper.firstChild) {
            const child = wrapper.removeChild(wrapper.firstChild);
            docFrag.appendChild(child);
        }

        wrapper.parentNode.replaceChild(docFrag, wrapper);
    }

    getRandomStringId(id?: any): string {
        let randomId = Math.random();

        if (id) {
            randomId = id + randomId;
        }

        return randomId.toString().replace(".", "").replace(" ", "");
    }

    onSelectionChange(selectedItem: HTMLElement) {
        if (selectedItem instanceof HTMLImageElement) {
            this._selectedImage = selectedItem;
        }
    }

    onEditDone(editedImageData: [{ [key: string]: any }], thumbnails: any) {
        const altTextPair = editedImageData.find(x => x.key === ALTERNATIVE_TEXT_KEY);
        const thumbnailPair = editedImageData.find(x => x.key === IMAGE_THUMBNAIL_TEXT_KEY);
        const marginsPair = editedImageData.find(x => x.key === IMAGE_MARGINS_KEY);
        this.selectedImage.alt = altTextPair.value;
        let url = this.getThumbnailUrl(this.selectedImage.src, ORIGINAL_IMAGE_KEY, thumbnails);

        if (thumbnailPair.value.thumbnailValue === CUSTOM_THUMBNAIL_KEY) {
            this.handleImageSizeAttributeAddition("width", thumbnailPair.value.width);
            if (thumbnailPair.value.constrainProportions) {
                this.handleImageSizeAttributeRemoval("height");
            } else {
                this.handleImageSizeAttributeAddition("height", thumbnailPair.value.height);
            }

            const customThumbnailAttr = document.createAttribute(CUSTOM_THUMBNAIL_ATTRIBUTE);
            customThumbnailAttr.value = "true";
            this.selectedImage.attributes.setNamedItem(customThumbnailAttr);

            const constrainProportionsAttr = document.createAttribute(CONSTRAIN_PROPORTIONS_ATTRIBUTE);
            constrainProportionsAttr.value = thumbnailPair.value.constrainProportions;
            this.selectedImage.attributes.setNamedItem(constrainProportionsAttr);
        } else {
            this.handleImageSizeAttributeRemoval(CUSTOM_THUMBNAIL_ATTRIBUTE);
            this.handleImageSizeAttributeRemoval(CONSTRAIN_PROPORTIONS_ATTRIBUTE);
            this.handleImageSizeAttributeRemoval("width");
            this.handleImageSizeAttributeRemoval("height");

            url = this.getThumbnailUrl(this.selectedImage.src, thumbnailPair.value.thumbnailValue, thumbnails);
        }

        if (marginsPair && marginsPair.value) {
            const marginsContainer = isImageHyperlink(this.selectedImage) ? this.selectedImage.parentElement : this.selectedImage;

            Object.keys(marginsPair.value).forEach(property => {
                marginsContainer.style[property] = marginsPair.value[property];
            });
        }

        this.selectedImage.src = url;
    }

    determineConstrainProportions(selectedImage: HTMLImageElement): boolean {
        const attr = selectedImage.attributes.getNamedItem(CONSTRAIN_PROPORTIONS_ATTRIBUTE);
        if (attr) {
            return attr.value === "true";
        }

        return true;
    }

    determineThumbnailId(selectedImage: HTMLImageElement, thumbnailsData: any): string {
        if (selectedImage.attributes.getNamedItem(CUSTOM_THUMBNAIL_ATTRIBUTE)) {
            return CUSTOM_THUMBNAIL_KEY;
        }

        const selectedThumbnail = thumbnailsData.find(item => item.Selected === true);
        return selectedThumbnail ? selectedThumbnail.Name : ORIGINAL_IMAGE_KEY;
    }

    determineScaledValue(value: number, naturalValue: number, otherDimensionNaturalValue: number): number {
        if (value) {
            const factor = value / naturalValue;
            return Math.round(otherDimensionNaturalValue * factor);
        }

        return null;
    }

    transformThumbnailsToChoices(thumbnails: any[]): any[] {
        const result = [];

        thumbnails.forEach(element => {
            result.push({
                Name: element.Title,
                Value: element.Name
            });
        });

        result.push({ Name: CUSTOM_SIZE_CHOICE_NAME, Value: CUSTOM_THUMBNAIL_KEY });
        return result;
    }

    private getThumbnailUrl(imageUrl: string, thumbnailId: string, thumbnails: any): string {
        let thumbnail = thumbnails.find(item => item.Name === thumbnailId);
        if (!thumbnail) {
            thumbnail = thumbnails.find(item => item.Name === ORIGINAL_IMAGE_KEY);
        }

        return thumbnail.Url;
    }

    private handleImageSizeAttributeAddition(attrName: string, attrValue: any) {
        if (attrValue) {
            this.selectedImage[attrName] = attrValue;
        } else if (this.selectedImage.attributes.getNamedItem(attrName)) {
            this.selectedImage.attributes.removeNamedItem(attrName);
        }
    }

    private handleImageSizeAttributeRemoval(attrName: string) {
        if (this.selectedImage.attributes.getNamedItem(attrName)) {
            this.selectedImage.attributes.removeNamedItem(attrName);
        }
    }
}

export const ALTERNATIVE_TEXT_KEY: string = "AlternativeText";
export const IMAGE_THUMBNAIL_TEXT_KEY: string = "ImageThumbnail";
export const IMAGE_MARGINS_KEY: string = "ImageMargins";
export const SIZE_ATTRIBUTE = "sf-size";
export const CUSTOM_THUMBNAIL_KEY = "custom";
export const CUSTOM_THUMBNAIL_ATTRIBUTE = "sf-custom-thumbnail";
export const CONSTRAIN_PROPORTIONS_ATTRIBUTE = "sf-constrain-proportions";
export const ORIGINAL_IMAGE_KEY = "original";
export const WIDTH_FIELD_NAME: string = "Width";
export const HEIGHT_FIELD_NAME: string = "Height";
export const PIXELS_NAME: string = "px";
export const CUSTOM_SIZE_CHOICE_NAME: string = "Custom size...";
export const MARGIN_TOP_NAME: string = "marginTop";
export const MARGIN_RIGHT_NAME: string = "marginRight";
export const MARGIN_BOTTOM_NAME: string = "marginBottom";
export const MARGIN_LEFT_NAME: string = "marginLeft";
