import { Component, Input, OnInit, Output, EventEmitter } from "@angular/core";
import { Filter, ComplexFilter } from "./filter-interfaces";
import { FilterStore } from "./filter.store";
import { EntityData } from "../../../interfaces";
import { ActivatedRoute } from "@angular/router";
import { ROUTE_PARAMS, LOADING_TIME, FILTER_PARAMS } from "../../../../constants";
import { Observable } from "rxjs";
import { delay } from "rxjs/operators";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const ALPHABET_FILTER_DEFAULT_ROWS: number = 100;

@Component({
    selector: "sf-filter-flat-taxa-first-letter",
    templateUrl: "./filter-flat-taxa-first-letter.component.html"
})
export class FilterFlatTaxaFirstLetterComponent extends SfRxBase implements OnInit, ComplexFilter {
    @Input() entityData: EntityData;
    @Input() category: string;
    @Input() reload: Observable<void>;
    @Output() filterSelect = new EventEmitter<string>();
    @Output() filtersChanged = new EventEmitter<Filter[]>();

    isLoading: boolean;
    isInitialLoad: boolean;
    filters: Filter[] = [];
    filterRows: number = ALPHABET_FILTER_DEFAULT_ROWS;
    filterValue: string;

    constructor(private filterStore: FilterStore, private route: ActivatedRoute) {
        super();
    }

    ngOnInit(): void {
        this.loadFilters();
        this.isInitialLoad = true;

        const loadComplexFiltersSubscription = this.reload.subscribe(() => {
            this.loadFilters();
        });
        this.registerSubscription(loadComplexFiltersSubscription);

        const queryParamsSubscription = this.route.queryParams.subscribe(queryParams => {
            this.filterValue = queryParams[FILTER_PARAMS.FILTER];
        });
        this.registerSubscription(queryParamsSubscription);
    }

    onFilterSelect(filter: string): void {
        this.filterSelect.emit(filter);
    }

    private loadFilters(): void {
        this.isLoading = true;

        const taxonomyId = this.route.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT];
        const filtersCountSubscription = this.filterStore.getDynamicFilters(this.entityData, taxonomyId)
            .pipe(delay(LOADING_TIME))
            .subscribe(result => {
                this.isLoading = false;
                this.isInitialLoad = false;
                this.filters = Object.assign([], result.filter(f => f.category === this.category));
                this.filterRows = Math.ceil(this.filters.length / 2);
                this.filtersChanged.emit(this.filters);
            });

        this.registerSubscription(filtersCountSubscription);
    }
}
