import { Observable, of } from "rxjs";
import { Injectable } from "@angular/core";
import { Command } from "../../commands/command";
import { ExecutionContext } from "../../commands/execution-context";
import { DialogData, ModalWindowService } from "../../services/modal-window.service";
import { ContentItemInfo } from "../interfaces/content-item-info";
import { INSIGHT_ROUTES } from "../insight.constants";

@Injectable()
export class SitefinityInsightMenuCommand implements Command {
    constructor(private modalWindowService: ModalWindowService) {
    }

    execute(context: ExecutionContext): Observable<any> {
        const contentItemInfo = new ContentItemInfo(context.data.dataItem);
        const dialogData = new DialogData(
            {
                type: null,
                properties: {
                    externalTouchpointLoad$: null,
                    contentItemInfo: contentItemInfo,
                    notifyGridCellForNewTouchpointFunc: () => {}
                }
            }
        );

        this.modalWindowService.setMapping(dialogData, INSIGHT_ROUTES.routeKey);
        this.modalWindowService.show(INSIGHT_ROUTES.routeKey, context.currentRoute);
        return of(true);
    }
}
