import { Component, Input, Output, EventEmitter, Inject, OnChanges, SimpleChanges } from "@angular/core";
import { StorageService, LOCAL_STORAGE } from "../../services/storage.service";
import { LoadMoreComponent } from "../../../../../../fields/load-more/load-more.component";

const SHOW_TOOLTIP_CLICK_COUNT = 2;
const HIDE_TOOLTIP_CLICK_COUNT = 3;
const LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_VALUE = "true";

export const LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_KEY = "tooltips.loadMoreSearchTooltip";

@Component({
    selector: "sf-load-more-search",
    templateUrl: "./load-more-search.component.html"
})
export class LoadMoreSearchComponent extends LoadMoreComponent implements OnChanges {
    @Input() searchValue: string;
    @Input() singularTitle: string;
    @Input() pluralTitle: string;
    @Input() isSearchEnabled: boolean = true;
    @Input() isFilterEnabled: boolean = true;
    @Output() onFilterSelected = new EventEmitter();
    @Output() onSearch = new EventEmitter();
    loadMoreButtonText: string;

    public isTooltipVisible: boolean = false;
    public isSearchVisible: boolean = false;
    private clickedCounter: number = 0;
    private wasTooltipShown: boolean = false;

    constructor(@Inject(LOCAL_STORAGE) private storage: StorageService) {
        super();

        this.wasTooltipShown = this.storage.getItem(LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_KEY) === LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_VALUE;
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.loadCount || changes.allItemsCount) {
            this.updateLoadButtonVisibility();
        }

        if (changes.loadCount) {
            this.updateLoadButtonText(changes.loadCount.currentValue);
        } else if (changes.singularTitle || changes.pluralTitle) {
            this.updateLoadButtonText();
        }
    }

    onFilterClicked() {
        this.hideNotification();
        this.onFilterSelected.emit();
    }

    onSearchClicked() {
        this.hideNotification();
        this.isSearchVisible = true;
    }

    search(searchKey: string) {
        this.onSearch.emit(searchKey);
    }

    loadMore() {
        this.clickedCounter++;

        this.updateLoadButtonVisibility(true);

        this.onLoadMore.emit();
    }

    hideNotification() {
        // TODO: Tooltip is hiding slowly because of sfTrackFocus directive - document click listener
        if (!this.wasTooltipShown) {
            this.isTooltipVisible = false;
            this.wasTooltipShown = true;
            this.storage.setItem(LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_KEY, LOAD_MORE_SEARCH_TOOLTIP_LOCALSTORAGE_VALUE);
        }
    }

    getType(loadCount: number): string {
        if (loadCount === 1) {
            return this.singularTitle;
        }

        return this.pluralTitle;
    }

    private updateHintVisibility() {
        if (this.clickedCounter === SHOW_TOOLTIP_CLICK_COUNT) {
            this.showHint();
            return;
        }

        if (this.clickedCounter === HIDE_TOOLTIP_CLICK_COUNT) {
            this.hideNotification();
            return;
        }
    }

    private showHint() {
        if (this.wasTooltipShown) {
            this.isSearchVisible = true;
        } else {
            this.isTooltipVisible = true;
        }
    }

    private updateLoadButtonVisibility(isLoadButtonClicked: boolean = false) {
        this.isLoadButtonVisible = this.getLoadButtonVisibility(isLoadButtonClicked);

        if (this.isLoadButtonVisible && this.isSearchEnabled) {
            this.updateHintVisibility();
        } else {
            this.isSearchVisible = false;
        }
    }

    private updateLoadButtonText(loadCount = this.loadCount) {
        const type = this.getType(loadCount);
        this.loadMoreButtonText = `Load ${loadCount} more ${type ? type.toLocaleLowerCase() : type}`;
    }
}
