import { Component, ViewChild } from "@angular/core";

import { FieldBase, createValueAccessor } from "../field-base";
import { SfInputComponent } from "@progress/sitefinity-component-framework";
import { ShortTextSettings } from "./short-text-settings";

@Component({
    selector: "sf-short-text",
    templateUrl: "./short-text.component.html",
    providers: [createValueAccessor(ShortTextComponent)]
})
export class ShortTextComponent extends FieldBase {
    @ViewChild("inputField", { static: false }) protected inputField: SfInputComponent;

    get shortTextSettings(): ShortTextSettings {
        return this.settings as ShortTextSettings;
    }

    onFocus() {
        super.onFocus();
        if (this.inputField)
            this.inputField.focus();
    }
}
