import { Injectable } from "@angular/core";
import { Observable, of, Subject } from "rxjs";
import { ButtonGroup } from "../components/action-menu/action-menu.component";
import { Operation } from "../components/action-menu/operation.model";
import { DialogData } from "../services/modal-window.service";
import { MarkAllNotificationsAsReadCommand } from "./commands/mark-all-notifications-as-read.command";
import { OpenNotificationsPreferencesCommand } from "./commands/open-notifications-preferences.command";

export const MARK_ALL_AS_READ = "Mark all as read";
export const EDIT_PREFERENCES = "Edit preferences";
export const NOTIFICATION_PREFERENCES = "Notification preferences";
export const NOTIFY_ME_FOR_UPDATES_FOR = "Notify me for...";
export const ITEMS_SENT_FOR_SYNC = "Items sent for sync";
export const NOTIFICATIONS_DIALOG_CLOSE_EVENT = "notifications-dialog-close-event";

@Injectable()
export class NotificationsService {
    constructor() { }

    onUpdate: Subject<boolean> = new Subject<boolean>();

    createNotificationsDialogData(componentType: any, title: string, key: string): DialogData {
        const dialogData = this.getDialogData(componentType, title, key);
        dialogData.headButtons = this.createHeadButtons();
        dialogData.showButtonsOnInit = true;
        dialogData.doneCallback = () => window.dispatchEvent(new Event(NOTIFICATIONS_DIALOG_CLOSE_EVENT));
        return dialogData;
    }

    getDialogData(componentType: any, title: string, key: string) {
        const properties: any = {};
        const dialogData = new DialogData({ type: componentType, properties }, null, []);
        dialogData.heading = { title: title };
        dialogData.key = key;
        return dialogData;
    }

    private createHeadButtons(): ButtonGroup[] {
        const group: ButtonGroup = {
            ariaLabel: NOTIFICATION_PREFERENCES,
            iconTitle: NOTIFICATION_PREFERENCES,
            insideButtons: [],
            dropdownButtonIconName: "cog",
            dropdownButtonIconLook: "size-m",
            dropdownButtonText: "",
            dropdownItemHeadingText: "",
            operations: this.prepareOperations(),
            buttonsLook: "circle"
        };
        const headButtons = [];
        headButtons.push(group);
        return headButtons;
    }

    prepareOperations(): Observable<Operation[]> {
        const categoryName = NOTIFICATION_PREFERENCES;
        const markAllAsRead: Operation = { Name: MARK_ALL_AS_READ, Category: { Name: categoryName }};
        const editPreferences: Operation = { Name: EDIT_PREFERENCES, Category: { Name: categoryName }};

        editPreferences.token = {
            type: OpenNotificationsPreferencesCommand
        };

        markAllAsRead.token = {
            type: MarkAllNotificationsAsReadCommand
        };

        const operations = of([markAllAsRead, editPreferences]);
        return operations;
    }
}
