import { LowerCasePipe } from "@angular/common";
import { ClassProvider, Inject, Injectable } from "@angular/core";
import { map, Observable } from "rxjs";
import { ExternalAppConfigService } from "../../../app-config/external-app-config.service";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { BackendTweaksStore } from "../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { GridReloadService } from "../../content/dynamic-modules/services/grid-reload.service";
import { CompositeOperationsProvider } from "../../content/dynamic-modules/services/operations/operations-provider";
import { ContentFilterService } from "../../shared/services/content-filter.service";
import { GridExtenderBase, GRID_EXTENDER_TOKEN } from "../../shared/services/grid/grid-extender-base";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { Settings } from "../../shared/services/settings.service";
import { SortService } from "../../shared/services/sort.service";

@Injectable()
export class PresetsGridExtender extends GridExtenderBase {
    constructor(
        settings: Settings,
        modalWindowService: ModalWindowService,
        dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        reloadService: GridReloadService,
        contentFilterService: ContentFilterService,
        sortService: SortService,
        backendTweaksStore: BackendTweaksStore,
        externalAppConfigService: ExternalAppConfigService,
        operationsProvider: CompositeOperationsProvider) {
        super(contentFilterService, dynamicItemStore, settings, sortService, backendTweaksStore, reloadService, modalWindowService, notificationService, externalAppConfigService, operationsProvider);
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.PRESETS;
    }

    getEmptyScreenText(entityData: EntityData, pluralName$: Observable<{primary: string, secondary: string}>): Observable<string> {
        return pluralName$.pipe(map(x => `No ${new LowerCasePipe().transform(x ? x.primary : "items")} have been created yet. \n You can create section presets while editing pages with the new editor.`));
    }

    hideSidebarLanguagesDropdown(entityData: EntityData): boolean {
        return true;
    }
}

export const PRESETS_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: PresetsGridExtender
};