import { of as observableOf,  Observable ,  ReplaySubject ,  Subject } from "rxjs";

import { map, mergeMap, filter } from "rxjs/operators";
import { AuthProvider, AUTH_PROVDER_TOKEN, Token } from "./auth.provider";
import { Inject, Injectable } from "@angular/core";
import { SitefinitySdk } from "../../services/sitefinitySdk.service";
import { stringConstants } from "../../common-constants";
import { AppStore } from "../../services/store/app-store";
import { SidebarClearAllDataAction } from "../../services/store/actions/actions.sidebar";

@Injectable()
export class AuthService {
    private loggedInPrivate = new ReplaySubject<boolean>();
    private provider: AuthProvider = null;
    private currentToken: Token = null;

    constructor(
        @Inject(AUTH_PROVDER_TOKEN) private providers: AuthProvider[],
        private sdk: SitefinitySdk,
        private store: AppStore) {

    }

    get loggedIn(): Observable<boolean> {
        return this.loggedInPrivate.asObservable();
    }

    init(): Observable<any> {
        if (this.provider) {
            return observableOf(this.provider);
        }

        return this.getProvider();
    }

    signIn(returnUrl: string): Observable<void> {
        return this.provider.signIn(returnUrl);
    }

    signOut(returnUrl?: string): Observable<void> {
        // clear sidebar feature store on logout
        this.store.dispatch(SidebarClearAllDataAction());
        return this.provider.signOut(returnUrl);
    }

    isLoggedIn(): Observable<boolean> {
        if (!this.provider) {
            return observableOf(false);
        }

        return this.provider.isLoggedIn();
    }

    tryLogIn(url: string): Observable<boolean> {
        const loggedIn = new ReplaySubject<boolean>(1);
        this.init().subscribe(x => {
            this.isLoggedIn().subscribe((isLoggedIn) => {
                if (!isLoggedIn) {
                    this.signIn(url).subscribe(() => {}, () => {

                        // In case we are unable to signIn (ex. session has expired) -> signOut to clear cookies and token and be redirected to login screen
                        this.signOut(url);
                    });
                }

                loggedIn.next(isLoggedIn);
                this.loggedInPrivate.next(isLoggedIn);
                loggedIn.complete();
            });
        });

        return loggedIn.asObservable();
    }

    getAuthHeader(): string {
        if (!this.currentToken) {
            return stringConstants.EMPTY_STRING;
        }

        return `${this.currentToken.type} ${this.currentToken.value}`;
    }

    getToken(): Token {
        return this.currentToken;
    }

    private getProvider(): Observable<AuthProvider> {

        // the provider is an observable as we do not know which provider we have to work with - swt, oidc, or extenral
        const ready$ = new ReplaySubject<AuthProvider>(1);

        const sortedProviders = this.providers.sort((a, b) => {
            if (a.getPriority() > b.getPriority()) {
                return 1;
            } else if (a.getPriority() < b.getPriority()) {
                return -1;
            }

            return 0;
        });

        let availableProv$ = observableOf({ provider: null, value: false });

        for (let i = 0; i < sortedProviders.length; i++) {
            availableProv$ = availableProv$.pipe(mergeMap((result) => {
                if (result.value === false) {
                    return sortedProviders[i].isAvailable().pipe(map(x => {
                        return {
                            provider: sortedProviders[i],
                            value: x
                        };
                    }));
                }

                return observableOf(result);
            }));
        }

        availableProv$.pipe(map(x => x.provider)).subscribe((provider) => {
            this.initProvider(ready$, provider);
        });

        return ready$.asObservable();
    }

    private initProvider(ready$: Subject<AuthProvider>, provider: AuthProvider) {
        provider.getToken().pipe(filter(x => !!x)).subscribe((token) => {
            this.currentToken = token;
            this.sdk.token = {
                type: token.type,
                value: token.value
            };
        });

        provider.init().subscribe(() => {
            this.provider = provider;
            ready$.next(this.provider);
            ready$.complete();
        });
    }
}
