import { Component, OnInit } from "@angular/core";
import { TimeZonesProvider } from "./timezones.provider";
import { FieldBase } from "../../../../../../../fields/field-base";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { toLoadingState, delayEmission } from "../../../rxjs-extensions";
import { MINIMUM_LOADER_TIME } from "../../../../../../../fields/loader-wrapper/loader-wrapper.component";
import { map, mergeMap, tap } from "rxjs/operators";
import { Observable, of } from "rxjs";
import { LoadingContentState } from "../../../rxjs-extensions/toLoadingState";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-timezones",
    templateUrl: "./timezones.component.html",
    providers: [TimeZonesProvider]
})
export class TimeZonesComponent extends FieldBase implements OnInit {
    isLoaded: boolean;
    choicesSettings: ChoiceSettings;
    options: ChoiceItem[];
    private firstValue: string;

    constructor(protected timeZonesProvider: TimeZonesProvider) {
        super();
    }

    ngOnInit(): void {
        this.registerSubscription(
            this.initializeComponent().subscribe(currentSelection => {
                if (currentSelection.isLoading) {
                    return;
                }

                const selectedTimeZoneId = currentSelection.content;
                this.choicesSettings = ChoiceDropdownComponent.createFieldSettings(this.options, selectedTimeZoneId, TIMEZONES_DROPDOWN_NAME);
                this.isLoaded = true;
            })
        );
    }

    writeValue(value: any) {
        if (this.firstValue === undefined) {
            this.firstValue = value;
        }

        const action = () => super.writeValue(value);
        const currentValue = this.getValue();

        // if first value is null then the default value will be used
        if (currentValue === null && this.firstValue === null) {
            // add a new message to the event queue to make sure
            // all change handlers are attached before setting the default value
            // the default value should trigger all change handlers in this case
            // and mark the field dirty
            setTimeout(action);
        } else if (currentValue !== value) {
            action();
        }
    }

    protected initializeComponent(): Observable<LoadingContentState<string>> {
        return this.timeZonesProvider.getTimeZones().pipe(
            mergeMap(timeZonesResult => {
                this.options = timeZonesResult.map(
                    tz => {
                        const option: ChoiceItem = {
                            Name: tz.name,
                            Value: tz.timeZoneId
                        };

                        return option;
                    });

                const selectedTimeZoneId = this.getValue();
                if (!selectedTimeZoneId) {
                    return this.timeZonesProvider.getDefaultTimeZone().pipe(
                        map(tz => tz.timeZoneId),
                        tap(defaultTimeZoneId => this.writeValue(defaultTimeZoneId))
                    );
                } else {
                    return of(selectedTimeZoneId);
                }
            }),
            toLoadingState(),
            delayEmission(MINIMUM_LOADER_TIME)
        );
    }
}

export const TIMEZONES_DROPDOWN_NAME = "TIMEZONES_DROPDOWN";
