import { ClosingContext, ClickResult, ModalWindowService, Button, ConfirmButton, CancelButton, ClickData, DialogData } from "../../../../../shared/services/modal-window.service";
import { SelectorComponent, ServiceContract, ServiceInfo } from "../../../../../../../../fields/selector/selector.component";
import { first, map } from "rxjs/operators";
import { DynamicItemService, LoadItemsData } from "../../dynamic-item.service";
import { ReplaySubject, Observable, of } from "rxjs";
import { DataItem, OperationResult, TotalCountResult } from "../../../interfaces";
import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { BulkOperationResult } from "./bulk-command";
import { NotificationService } from "../../../../../shared/services/notification/notification.service";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ToolbarComponent } from "../../../components/dialog/toolbar.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { cloneObject } from "../../../../../../utils";
import { SortService } from "../../../../../shared/services/sort.service";

export abstract class SelectorBaseCommand implements ExecuteOnceInBulkCommand {
    executeOnceInBulk: boolean = true;
    entityData: DataItem;
    dialogBadgeItemsCount: ReplaySubject<string> = new ReplaySubject<string>(1);

    protected targetItems: DataItem[];
    protected isHierarchical: boolean = false;
    protected abstract dialogMapping;
    protected abstract dialogTitle;
    protected abstract confirmButtonText;

    constructor(protected modalWindowService: ModalWindowService,
                protected service: DynamicItemService,
                protected notificationService: NotificationService,
                protected sortService: SortService) {
    }

    execute(context: ExecutionContext): Observable<any> {
        const dataItems = context.data.dataItem ? [context.data.dataItem] : [];
        this.targetItems = context.data.selectedItems || dataItems;
        this.getEntityData();
        this.setDialogTitle();

        const selectorItems$ = new ReplaySubject<TotalCountResult<any[]>>(1);
        this.serviceLoadMore({}).pipe(first()).subscribe(selectorItems => {
            selectorItems$.next(selectorItems);
            selectorItems$.complete();
        });

        const componentData: ComponentData = {
            type: SelectorComponent,
            properties: {
                value$: selectorItems$,
                loading: true,
                defaultField: this.entityData.metadata.defaultFieldName,
                entityData: this.entityData,
                title: this.dialogTitle,
                hideSticky: true,
                serviceAware: this.getServiceAware(),
                superScript: this.dialogBadgeItemsCount,
                treeConfig: {
                    isHierarchical: this.isHierarchical,
                    treeProperties: {
                        idField: this.entityData.key,
                        displayField: this.entityData.metadata.defaultFieldName
                    }
                },
                config: {
                    // removes the default title
                    formattedTypeName: null
                }
            }
        };

        this.generateDescription(componentData);
        this.modifyComponentData(componentData);

        const buttons: Button[] = [
            new ConfirmButton(this.confirmButtonText, (data: ClickData) => this.confirmButtonClickHandler(data.component)),
            new CancelButton()
        ];
        const return$ = new ReplaySubject<OperationResult>(1);
        const dialogData = new DialogData(componentData, (context: ClosingContext) => this.onDone(context, return$), buttons, null, "-bottom");

        const superScript = this.targetItems.length > 1 ? this.targetItems.length.toString() : null;
        dialogData.toolbarData = {
            type: ToolbarComponent,
            properties: {
                header: this.dialogTitle,
                superScript
            }
        };

        dialogData.heading = { title: this.dialogTitle };
        this.dialogBadgeItemsCount.next(superScript);

        this.modalWindowService.setMapping(dialogData, this.dialogMapping);
        this.modalWindowService.show(this.dialogMapping, context.currentRoute.parent);

        return return$;
    }

    protected abstract getEntityData();

    protected serviceLoadMore(info: ServiceInfo): Observable<{ totalCount: number, dataItems: any[] }> {
        const requestData: LoadItemsData = {
            entityData: this.entityData,
            order: this.sortService.getDefaultSort(this.entityData),
            skip: info.skip,
            take: info.take || 20,
            fallbackProperties: [this.entityData.metadata.defaultFieldName]
        };

        if (info.searchText) {
            requestData.filter = [{ key: this.entityData.metadata.defaultFieldName, value: [info.searchText]}];
        }

        return this.service.getItemList(requestData).pipe(
            map(res => {
                return {
                    totalCount: res.totalCount,
                    dataItems: this.mapNodes(res.dataItems)
                };
            }));
    }

    protected serviceExpand(info: ServiceInfo): Observable<{ totalCount: number, dataItems: any[] }> {
        return of({totalCount: 0, dataItems: []});
    }

    protected mapNodes(dataItems: DataItem[]) {
        const value = dataItems.map(dataItem => {
            const data = cloneObject(dataItem.data);
            data.isTranslated = true;

            return data;
        });

        return value;
    }

    private confirmButtonClickHandler(component: any): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);
        const selectedItems = (component as SelectorComponent).selected;
        const bulkResult: BulkOperationResult = {
            success: true,
            succeededItemsIds: []
        };

        // start loading animation
        clickResult.next(new ClickResult({}, false, false, true));

        if (selectedItems && selectedItems.length && selectedItems[0]) {
            this.executeConfirmAction(selectedItems.map(x => DataItem.fromEntityData(x, this.entityData)), clickResult);
        } else {
            clickResult.next(new ClickResult(bulkResult, true));
        }

        return clickResult.asObservable();
    }

    protected abstract executeConfirmAction(selectedItems: DataItem[], clickResult: ReplaySubject<ClickResult>);

    protected onDone(context: ClosingContext, return$: ReplaySubject<OperationResult>) {
        this.notificationService.close();
        const result = context.data as ClickResult;
        if (result && result.data && result.data.success) {
            return$.next(<BulkOperationResult>{ success: true, succeededItemsIds: result.data.succeededItemsIds });
            return$.complete();
        } else {
            return$.next(<OperationResult>{ success: false });
            return$.complete();
        }
    }

    protected abstract generateDescription(componentData: ComponentData);

    protected setDialogTitle() {
    }

    private getServiceAware() {
        return new ServiceContract(this.serviceLoadMore.bind(this), this.serviceExpand.bind(this));
    }

    protected modifyComponentData(componentData: ComponentData) {
    }
}
