import { ClassProvider, Injectable } from "@angular/core";
import { NavbarConfiguration } from "../../components/navigation/navigation-menu/navigation-menu.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../services/edit/edit-extender";
import { CONTENT_ITEM_FULL_NAME } from "../../services/metadata/meta-data-constants";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { ContentBlocksNotificationComponent } from "../components/content-blocks-notification.component";

@Injectable()
export class ContentBlocksEditExtender extends EditExtender {

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.typeFullName === CONTENT_ITEM_FULL_NAME;
    }

    overrideNavigationMenuOptions(dataItem: DataItem, options: NavbarConfiguration): void {
        options.title = null;
        options.hideAdditionalActionsMenu = true;

        const contentBlocksNotificationComponent: ComponentData = {
            type: ContentBlocksNotificationComponent,
            properties: {
                isFromEditScreen: true,
                item$: options.item$
            }
        };
        options.additionalActionsComponentData = contentBlocksNotificationComponent;
    }
}

export const CONTENT_BLOCKS_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: ContentBlocksEditExtender
};
