import { Component, OnInit } from "@angular/core";
import { createValueAccessor, FieldBase } from "../field-base";
import { SwitchSettings } from "./switch.settings";

@Component({
    selector: "sf-switch-wrapper",
    templateUrl: "./switch.wrapper.component.html",
    providers: [createValueAccessor(SwitchWrapperComponent)]
})
export class SwitchWrapperComponent extends FieldBase implements OnInit {
    id: string;
    onText: string;
    offText: string;
    isOn: boolean;
    isLoading: boolean;
    disabled: boolean;

    ngOnInit() {
        super.ngOnInit();
        const switchSettings = this.settings as SwitchSettings;
        this.id = switchSettings.key;
        this.onText = switchSettings.onText;
        this.offText = switchSettings.offText;
        this.disabled = switchSettings.readOnlyMode;
        this.isOn = super.getValue();
    }

    onSelectionChange(): void {
        this.isLoading = true;

        // call super.writeValue and not this.writeValue because this.writeValue will set the isLoading to false but
        // we want to simulate a loading behavior and show a loading bar for several milliseconds that is why when the
        // component that is using this one will control the time when isLoading is set to false and hide the loading bar
        super.writeValue(!this.isOn);
    }

    writeValue(value: any): void {
        if (this.isLoading) {
            super.writeValue(value);
        }

        this.isLoading = false;
        this.isOn = value;
    }

    hasEmptyValue() {
        return this.isOn === null || this.isOn === undefined;
    }
}
