import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, EventEmitter, Output, ViewChild, Input } from "@angular/core";
import { BehaviorSubject } from "rxjs";
import { guid } from "@progress/kendo-angular-common";

const TITLE_ATTRIBUTE = "title";

@Component({
    selector: "sf-zone-splitter",
    templateUrl: "./zone-splitter.component.html"
})
export class ZoneSplitterComponent implements AfterViewInit {
    @Input() panesCount: string = "2";
    @Input() gridColumnSize: number[];
    @Input() gridSize: number = 12;
    @Output() gridColumnsSizeChange: EventEmitter<number[]> = new EventEmitter<number[]>();
    @ViewChild("splitter", { static: false }) public splitterElement;
    panesList: BehaviorSubject<Pane[]> = <BehaviorSubject<Pane[]>>new BehaviorSubject([]);
    showSplitter: boolean = true;
    inputUniqueId: string = `input-${guid()}`;
    showError: boolean = false;
    private paneList: Pane[];
    private numberOfColsPerPane: number;
    private sizeOfOneGridColumnPercent: number;

    constructor(private changeDetectorRef: ChangeDetectorRef) {}

    ngAfterViewInit() {
        const paneNumber = parseInt(this.panesCount);
        if (paneNumber <= 1) {
            this.showSplitter = false;
        }

        if (this.gridColumnSize &&  this.gridColumnSize.length > 0 && this.gridColumnSize.length === paneNumber) {
            this.initializePanes();
        } else {
            this.configurePanes(paneNumber);
        }
        this.changeDetectorRef.detectChanges();
    }

    onColumnNumberChanged(event) {
        if (event && !Number.isNaN(parseInt(event.value))) {
            this.panesCount = event.value;

            //recalculate splitter pane sizes
            this.configurePanes(parseInt(this.panesCount));
        }
    }

    handleSizeChange(size: string, pane: SplitterPane, indexInPaneList: number): void {
        const paneElement = pane.element;
        const parsedSize = parseFloat(size);

        //splitter panes should increase/decrease size by step, each step equals 1 css grid column
        const roundBy = 100 / this.gridSize;
        const newPaneGridColumnNumber = Math.round(parsedSize / roundBy);
        const roundedSize = newPaneGridColumnNumber * roundBy;
        pane.size = `${roundedSize}%`;
        const sizeInPercent =  Math.round(roundedSize);

        //set title/tooltip and label of pane after size change
        this.setPaneAttributes(paneElement, sizeInPercent, newPaneGridColumnNumber);

        //get the index of current pane in the kendo splitter panes array
        const indexInSplitterPanesArray =  pane.order / 2;

        //get the previous pane
        const previousPane: SplitterPane = (indexInSplitterPanesArray - 1) >= 0 ?  this.splitterElement.splitterService.pane(indexInSplitterPanesArray - 1) : null;

        //get the next pane
        const nextPane: SplitterPane = (indexInSplitterPanesArray + 1) < this.splitterElement.panes.length ? this.splitterElement.splitterService.pane(indexInSplitterPanesArray + 1) : null;
        let notFixedPane;

        //check if previous or next pane has no fixed size. This means that the 'sizeChange' event won't be triggered;
        //for this pane, we need to resize is ourselves
        if (previousPane && !previousPane.fixedSize) {
            notFixedPane = previousPane;
        } else if (nextPane && !nextPane.fixedSize) {
            notFixedPane = nextPane;
        }

        //emit array with section sizes only when there has been a change in the size of the panes
        let shouldEmitNewRows = false;

        //if one of the panes doesn't have a fixed size, calculate its size
        if (notFixedPane) {
            let newSizeOfPane = 100;
            this.splitterElement.panes.forEach((pane) => {
                if (pane.size) {
                    newSizeOfPane -= parseFloat(pane.size);
                }
            });

            const newSizeOfPaneCols = Math.round(newSizeOfPane / this.sizeOfOneGridColumnPercent);
            const newSizeOfPanePercent = Math.round(newSizeOfPane);

            if (this.gridColumnSize[this.gridColumnSize.length - 1] !== newSizeOfPaneCols ) {
                this.gridColumnSize[this.gridColumnSize.length - 1] = newSizeOfPaneCols;
                shouldEmitNewRows = true;
                const notFixedPaneElement = notFixedPane.element;
                this.setPaneAttributes(notFixedPaneElement, newSizeOfPanePercent, newSizeOfPaneCols);
            }
        }

        if (this.gridColumnSize[indexInPaneList] !== newPaneGridColumnNumber) {
            this.gridColumnSize[indexInPaneList] = newPaneGridColumnNumber;
            shouldEmitNewRows = true;
        }

        if (shouldEmitNewRows) {
            this.gridColumnsSizeChange.emit(this.gridColumnSize);
        }
    }

    private configurePanes(paneNumber: number): void {
        this.showSplitter = paneNumber > 1;

        //calculate number of css grid columns per a section column
        this.numberOfColsPerPane = Math.floor(this.gridSize / paneNumber);

        //calculate remainder of css grid columns in case the grid size can't be divided by the number of section columns
        //for example: grid size is 12, we want 7 section columns, we create 6 equal columns
        //with 1 css grid column in each, and the 7th column's size is 1 + remainder(5) = 6

        const remainderFromDivision = this.gridSize % paneNumber;

        //size of grid column in percent (for visualization purposes)
        this.sizeOfOneGridColumnPercent = 100 / this.gridSize;

        //size of a regular section column - the width of the splitter handler
        const sizeOfRegularColumnPercent = this.sizeOfOneGridColumnPercent * this.numberOfColsPerPane;

        //number of css grid columns contained in the last column, that isn't equal to the others
        const numberOfColsPerPaneIrregularColumn = remainderFromDivision ? this.numberOfColsPerPane + remainderFromDivision : this.numberOfColsPerPane;

        //size in percent of the unequal column - the width of the splitter handler
        const irregularColumnsSizeInPercent = numberOfColsPerPaneIrregularColumn * this.sizeOfOneGridColumnPercent;
        const paneList: Pane[] = [];

        //we push all equal columns to the list
        for (let i = 0; i < paneNumber - 1; i++) {

        //size: used by the kendo splitter to calculate each splitter pane width
        //sizeInPercent: used for the labels
        //gridColumnsCount: number of css grid columns per a section column (used for the section css classes, handled by the renderer)
            paneList.push({size: `${this.roundToTwoDecimalPlaces(sizeOfRegularColumnPercent)}%`, sizeInPercent: Math.round(sizeOfRegularColumnPercent), gridColumnsCount: this.numberOfColsPerPane});
        }
        paneList.push({ sizeInPercent: Math.round(irregularColumnsSizeInPercent), gridColumnsCount: numberOfColsPerPaneIrregularColumn });
        this.paneList = paneList;

        //needed by the renderer to place corresponding section classes
        this.gridColumnSize = this.paneList.map( (item) => { return  item.gridColumnsCount; });
        this.panesList.next(this.paneList);

        //event, emitted when the section columns get resized
        this.gridColumnsSizeChange.emit(this.gridColumnSize);
    }

    private initializePanes(): void {
        this.sizeOfOneGridColumnPercent = 100 / this.gridSize;

        const paneList: Pane[] = [];

        const paneNumber = this.gridColumnSize.length;
        //we push all equal columns to the list
        for (let i = 0; i < paneNumber - 1; i++) {
            //size of a regular section column - the width of the splitter handler
            const sizeOfRegularColumnPercent = this.sizeOfOneGridColumnPercent * this.gridColumnSize[i];
            paneList.push({size: `${this.roundToTwoDecimalPlaces(sizeOfRegularColumnPercent)}%`, sizeInPercent: Math.round(sizeOfRegularColumnPercent), gridColumnsCount: this.gridColumnSize[i]});
        }

        const irregularColumnsSizeInPercent = this.sizeOfOneGridColumnPercent * this.gridColumnSize[paneNumber - 1];
        paneList.push({ sizeInPercent: Math.round(irregularColumnsSizeInPercent), gridColumnsCount: this.gridColumnSize[paneNumber - 1] });

        this.paneList = paneList;
        this.panesList.next(this.paneList);
    }

    private setPaneAttributes(element: ElementRef, sizeInPercent: number, sizeInGridCols: number) {
        const title = `${sizeInPercent} or ${sizeInGridCols} css columns`;
        element.nativeElement.setAttribute(TITLE_ATTRIBUTE, title);
        element.nativeElement.innerText = sizeInPercent;
    }

    private roundToTwoDecimalPlaces(num: number) {
       return Math.round((num + Number.EPSILON) * 100) / 100;
    }
}

export interface Pane {
    size?: string;
    sizeInPercent?: number;
    gridColumnsCount?: number;
}

export interface SplitterPane {
    size: string;
    order: number;
    element: ElementRef;
    fixedSize: boolean;
}
