import { Directive, ElementRef, AfterViewInit, Input } from "@angular/core";
import { stringConstants } from "../../../src/app/common-constants";
import { isCurrency, textEndsWithNumber } from "../utils";

export const TRIM_LENGTH = 10;
export const TOOLTIP_ATTRIBUTE_NAME = "title";
const ELLIPSIS_SYMBOL = "&#8230;";
const ELLIPSIS_SYMBOL_LENGTH = 1;

@Directive({
    selector: "[sfNumberOverflow]"
})
export class NumberOverflowDirective implements AfterViewInit {
    @Input() trimLength: number = TRIM_LENGTH;
    @Input() unit: string;

    constructor(private element: ElementRef) { }

    ngAfterViewInit() {
        // This directive has to execute its logic last of all the other directives set for an HTML element because we want to
        // trim the excess symbols of an already set value for an HTML element. For example, if we have a number, it needs to go
        // through the localizedNum.directive first and then be trimmed if needed. The function setTimeout is used to ensure that
        setTimeout(() => {
            const longValue = this.element.nativeElement.innerText;
            if (longValue.length > this.trimLength) {
                let shortText = longValue.substr(0, this.getTrimLength()).trim();
                if (!textEndsWithNumber(shortText)) {
                    shortText = shortText.substring(0, shortText.length - 1);
                }

                this.setShortTextAndTooltip(shortText);
            }
        }, 0);
    }

    private setShortTextAndTooltip(text: string) {
        const tooltipAttribute = document.createAttribute(TOOLTIP_ATTRIBUTE_NAME);
        tooltipAttribute.value = this.createTooltip();
        this.element.nativeElement.setAttributeNode(tooltipAttribute);
        this.element.nativeElement.innerHTML = `${text}${ELLIPSIS_SYMBOL}`;
    }

    private getTrimLength(): number {
        let trimLength = this.trimLength;

        if (!isCurrency(this.unit) && this.unit) {
            trimLength -= (this.unit.length + ELLIPSIS_SYMBOL_LENGTH);
        }

        return trimLength;
    }

    private createTooltip(): string {
        let value = this.element.nativeElement.innerText;

        if (!isCurrency(this.unit)) {
            value += this.unit || stringConstants.EMPTY_STRING;
        }

        return value;
    }
}
