import { BulkCommandExtenderBase } from "../../content/dynamic-modules/services/operations/commands/bulk-command-extender-base";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "./media.helpers";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { ClassProvider, Inject, Injectable } from "@angular/core";
import { BULK_COMMAND_EXTENDER_TOKEN } from "../../content/dynamic-modules/services/operations/commands/composite-bulk-command-extender";
import { ActionButton } from "../../shared/components/action-menu/action-menu-model";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { Command } from "../../shared/commands/command";
import { MoveToLibraryCommand } from "../../content/dynamic-modules/services/operations/commands/move-to-library.command";
import { MediaService } from "./media.service";
import { ActivatedRoute } from "@angular/router";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { GridViewModes, getGridViewMode } from "../../../utils";
import { UserDataStore } from "../../shared/services/metadata/user-data.store";
import { StorageService, LOCAL_STORAGE, LIBRARIES_GRID_VIEW_KEY } from "../../shared/services/storage.service";
import { Properties } from "../../shared/fields.constants";
import { CompositeDataExtender } from "../../shared/services/data-extensions/data.extender";
import { BulkEditMediaPropertiesCommand } from "../../content/dynamic-modules/services/operations/commands/bulk-edit-media-properties.command";
import { FieldsGeneratorService } from "../../shared/services/fields-generator.service";
import { BackendTweaksStore } from "../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { BulkItemSelectionInfo } from "../../content/dynamic-modules/components/bulk-operations/bulk-operations.component";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { SortService } from "../../shared/services/sort.service";
import { LongRunningTasksService } from "../../content/dynamic-modules/services/long-running-tasks.service";
import { Query, WhereQuery } from "@progress/sitefinity-webservices-sdk/dist/sitefinity-webservices-sdk";

@Injectable()
export class MediaBulkCommandExtender extends BulkCommandExtenderBase {
    constructor(private metadataStore: MetadataStore,
                private mediaService: MediaService,
                private route: ActivatedRoute,
                private taskService: LongRunningTasksService,
                private dynamicItemStore: DynamicItemStore,
                private modalService: ModalWindowService,
                @Inject(LOCAL_STORAGE) private storageService: StorageService,
                private userStore: UserDataStore,
                private fieldsGeneratorService: FieldsGeneratorService,
                private backendTweaksStore: BackendTweaksStore,
                @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
                private compositeDataExtender: CompositeDataExtender,
                private sortService: SortService) {
        super();
    }

    isSupportedType(entityData: EntityData): boolean {
        return MediaHelpers.isLibraryOrMedia(entityData.metadata.setName);
    }

    getEntityDatasForBulkOperation(entityData: EntityData, filter: string = null): EntityData[] {
        const result = [entityData];
        if (!filter && MediaHelpers.isMediaEntity(entityData)) {
            result.push({
                metadata: this.metadataStore.getEntity(ENTITY_SET.FOLDERS),
                culture: entityData.culture,
                provider: entityData.provider
            });
        }

        return  result;
    }

    getFilterByParentQuery(entityData: EntityData, query: WhereQuery<Query>, parentId: string) {
        if (MediaHelpers.isLibrary(entityData.metadata.setName)) {
            query = query.or()
                .and()
                    .eq(Properties.ROOT_ID, parentId)
                    .eq(Properties.PARENT_ID, null)
                .done()
                    .eq(Properties.PARENT_ID, parentId)
                .done();
        } else if (MediaHelpers.isMediaEntity(entityData)) {
            query = query.or()
                .and()
                    .eq(Properties.PARENT_ID, parentId)
                    .eq(Properties.FOLDER_ID, null)
                .done()
                    .eq(Properties.FOLDER_ID, parentId)
                .done();
        }

        return query;
    }

    tryHandleCommand(action: ActionButton, data: {dataItems: DataItem[], entityData: EntityData, notificationFilter: string, bulkItemSelectionInfo: BulkItemSelectionInfo}): Command {
        if (action.name === OPERATION_NAMES.move) {
            let entityData = data.entityData;

            if (this.getPresenterTemplate() === GridViewModes.Timeline) {
                entityData = {
                metadata: this.metadataStore.getEntity(ENTITY_SET.IMAGES),
                culture: entityData.culture,
                provider: entityData.provider
                };
            }

            const command = new MoveToLibraryCommand(this.modalService, this.metadataStore, this.compositeDataExtender, this.route, this.taskService, this.mediaService, this.dynamicItemStore.service, this.notificationService, this.sortService);
            command.entityData = DataItem.emptyItem(entityData);
            return command;
        } else if (action.name === OPERATION_NAMES.bulkEditProperties) {
            const command = new BulkEditMediaPropertiesCommand(this.modalService, this.fieldsGeneratorService, this.backendTweaksStore, this.dynamicItemStore.service);
            return command;
        }

        return null;
    }

    private getPresenterTemplate(): "Thumbs" | "List" | "Timeline" {
        const gridMode = this.storageService.getItem(LIBRARIES_GRID_VIEW_KEY);
        const userId = this.userStore.userId;
        return getGridViewMode(gridMode, userId);
    }
}

export const MEDIA_BULK_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: BULK_COMMAND_EXTENDER_TOKEN,
    useClass: MediaBulkCommandExtender
};
