import { Component, ViewEncapsulation, Output, EventEmitter, Input, HostBinding, ElementRef } from "@angular/core";
import { IChipIconConfig } from "@progress/sitefinity-component-framework";
import { Observable } from "rxjs";

@Component({
    selector: "sf-add-widget",
    templateUrl: "./add-widget.component.html",
    styleUrls: ["./add-widget.component.scss"],
    encapsulation: ViewEncapsulation.ShadowDom
})
export class AddWidgetComponent {
    @Output() onAddClick = new EventEmitter<void>();
    @Input() addWidgetLabel: string = "Add widget";
    @Input() addWidgetDraggedOverLabel: Observable<string>;
    @HostBinding("class.-sf-flex-child") get flex() {
        const parent = this.elRef.nativeElement.parentElement;
        let parentDisplay;
        let parentDirection;

        if (parent) {
            const parentStyles = window.getComputedStyle(parent);
            parentDisplay = parentStyles.getPropertyValue("display");
            parentDirection = parentStyles.getPropertyValue("flex-direction");
        }

        return parent && parentDirection === "row" && (parentDisplay === "flex" || parentDisplay === "inline-flex");
    }

    iconConfig: IChipIconConfig = {
        name: "plus",
        look: "white size-xs sf-mr--4xs",
        wrapperLook: "transparent"
    };

    constructor(private elRef: ElementRef) {}

    onAddButtonClick() {
        this.onAddClick.emit();
    }
}
