import { NotificationData, NOTIFICAITON_LOOK_MAP, NOTIFICATION_LOOKS, NOTIFICATION_FILTER_EMPTY, NOTIFICATION_FILTER_ALL } from "./notification-data";
import { Injectable, Inject, InjectionToken } from "@angular/core";
import { ReplaySubject, Observable, OperatorFunction, ObservedValueOf, EMPTY } from "rxjs";
import { catchError } from "rxjs/operators";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ItemWithOperationResult } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { BasicNotificationComponent } from "../../components/notifications/basic-notification/basic-notification.component";
import { NOTIFICATION_DURATION_DEFAULT, NOTIFICATION_DURATION_INFINITE } from "../../../content/constants";
import { BasicNotificationInfo } from "./notification-info";

export const NOTIFICATION_SERVICE = new InjectionToken("NotificationService");
/**
 * @ExposedInApi {NotificationService} NotificationService v1/notifications/notification.service.d.ts
 */
@Injectable({
    providedIn: "root"
})
export class NotificationService {
    private notificationMap: Map<string, NotificationData> = new Map();
    private notificationHandlesMap: Map<string, number> = new Map();

    private notification$ = new ReplaySubject<NotificationData>(1);
    private notificationClose$ = new ReplaySubject<NotificationData>(1);

    constructor(@Inject(WINDOW_TOKEN) private windowProvider: Window) {
    }

    getNotification(): Observable<NotificationData> {
        return this.notification$.asObservable();
    }

    getCloseNotification(): Observable<NotificationData> {
        return this.notificationClose$.asObservable();
    }

    publishNotificationFromOperationResult(value: ItemWithOperationResult, filter: string) {
        let notificationData: NotificationData;
        if (value.notificationData) {
            notificationData = value.notificationData;
        } else if (value.operationResult && value.operationResult.Message) {
            notificationData = {
                type: BasicNotificationComponent,
                duration: NOTIFICATION_DURATION_DEFAULT,
                filterParam: filter,
                properties: {
                    message: value.operationResult.Message,
                    operation: value.operationResult.UndoOperation,
                    dataItem: value.dataItem
                },
                look: NOTIFICAITON_LOOK_MAP[value.operationResult.Type]
            };

            if (notificationData.look === undefined && value.operationResult.Success) {
                notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            }
        }
        if (notificationData)
            this.publishNotification(notificationData);
    }

    publishNotification(notification: NotificationData) {
        if (!notification)
            return;

        if (notification.removePreviousView === undefined)
            notification.removePreviousView = true;

        if (notification.updatePropertiesOnChange === undefined)
            notification.updatePropertiesOnChange = true;

        const notificationFilter = this.getNotificationFilter(notification);
        this.closeNotificationByFilter(notificationFilter);
        this.notificationMap.set(notificationFilter, notification);

        if (notification.duration && notification.duration > 0) {
            this.setTimeout(notification);
        }

        this.notification$.next(notification);
    }

    publishBasicNotification(notificationInfo: BasicNotificationInfo) {
        const notificationData = {
            id: notificationInfo.id || "notification",
            type: BasicNotificationComponent,
            properties: {
                message: notificationInfo.message
            },
            look: notificationInfo.look,
            duration: notificationInfo.duration,
            closeButton: notificationInfo.closeButton,
            filterParam: notificationInfo.filterParam,
            removePreviousView: true,
            updatePropertiesOnChange: true
        };

        if (notificationData.duration === undefined)
            notificationData.duration = NOTIFICATION_DURATION_DEFAULT;

        if (notificationData.closeButton === undefined)
            notificationData.closeButton = true;

        this.publishNotification(notificationData);
    }

    publishInfiniteError(errorMessage: string, notificationFilter: string = null) {
        this.publishBasicNotification({
            message: errorMessage,
            look: NOTIFICATION_LOOKS.ERROR,
            duration: NOTIFICATION_DURATION_INFINITE,
            filterParam: notificationFilter
        });
    }

    public catchErrorAndShowNotification<T, O>(filter: string): OperatorFunction<T, T | ObservedValueOf<O>> {
        return catchError((err) => {
            this.publishBasicNotification({
                message: err.message,
                look: NOTIFICATION_LOOKS.ERROR,
                filterParam: filter
            });
            return EMPTY;
        });
    }

    closeMultiple(filters: string[]) {
        filters.forEach(filter => {
            this.closeNotificationByFilter(filter);
        });
    }

    close(filter: string = NOTIFICATION_FILTER_ALL) {
        if (filter === NOTIFICATION_FILTER_ALL) {
            const keyIterator = this.notificationMap.keys();

            // eslint-disable-next-line no-constant-condition
            while (true) {
                const nextItem = keyIterator.next();
                if (nextItem.done)
                    break;

                this.closeNotificationByFilter(nextItem.value);
            }
        } else {
            this.closeNotificationByFilter(filter);
        }
    }

    private closeNotificationByFilter(filter: string) {
        const notification = this.notificationMap.get(filter || NOTIFICATION_FILTER_EMPTY);
        if (notification)
            this.closeSpecificNotification(notification);
    }

    private closeSpecificNotification(notification: NotificationData) {
        this.notificationClose$.next(notification);
        this.notificationMap.delete((this.getNotificationFilter(notification)));

        const timeoutKey = this.notificationHandlesMap.get((this.getNotificationFilter(notification)));
        this.windowProvider.clearTimeout(timeoutKey);
        this.notificationHandlesMap.delete((this.getNotificationFilter(notification)));
        this.notification$.next(null);
    }

    private setTimeout(notification: NotificationData): void {
        const timeoutKey = this.windowProvider.setTimeout(() => {
            this.close(this.getNotificationFilter(notification));
        }, notification.duration);

        this.notificationHandlesMap.set(this.getNotificationFilter(notification), timeoutKey);
    }

    private getNotificationFilter(notification: NotificationData): string {
        return notification.filterParam || NOTIFICATION_FILTER_EMPTY;
    }
}
