import { Injectable } from "@angular/core";
import { Entity } from "../../../../shared/services/metadata/meta-data.store";
import { GridData } from "./backend-tweaks.store";
import { ColumnModel } from "../../../../shared/models/column-model";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ListLanguagesComponent } from "../../components/grid-cells/list-languages.component";
import { Properties } from "../../../../shared/fields.constants";
import { MarketingCellComponent } from "../../../../pages/components/columns/marketing/marketing-cell.component";
import { PAGE_COMPUTED_PROPERTIES } from "../../../../pages/components/navigation-options-composite-component/navigation-options.composite.component";
import { CalendarGridCellComponent } from "../../../../shared/components/events/calendar-grid-cell/calendar-grid-cell.component";
import { EventTimeGridCellComponent } from "../../../../shared/components/events/event-time-grid-cell/event-time.grid-cell.base.component";
import { EVENT_PROPERTIES } from "../../../../shared/components/events/events.constants";
import { UsageInSitesComponent } from "../../../../taxonomy/usage-in-sites/usage-in-sites.component";
import { ListChildrenCountComponent } from "../../components/grid-cells/list-children-count.component";
import { AppliedToComponent } from "../../../../shared/components/fields/applied-to-component";
import { PageViewComponent } from "../../../../pages/components/columns/page-view.component";
import { GridActionMenuComponent } from "../../components/grid-cells/grid-action-menu/grid-action-menu.component";
import { CreateChildComponent } from "../../components/grid-cells/create-child.component";
import { ColInitializer, MainColInitializer, DateAndUserInitializer, TaxaMainInitializer, ClickableColInitializer, MediaMainInitializer, GroupingColInitializer, TemplatesMainInitializer, FormResponsesColInitializer, TranslationsColumnInitializer } from "./col-initializers";
import { stringConstants } from "../../../../../common-constants";
import { MainFieldComponent } from "../../components/grid-cells/main-field/main-field.component";
import { ListChildrenItemsComponent } from "../../components/grid-cells/list-children-items.component";
import { DateAndUserComponent, LAST_UPLOADED_ON } from "../../../../shared/components/fields/date-and-user.component";
import { LetterMarkComponent } from "../../components/grid-cells/letter-mark.component";
import { FileDimSizeComponent } from "../../../../libraries/images/file-dim-size-grid/file-grid-size.component";
import { GridThumbnailComponent } from "../../../../libraries/thumbnail/grid-thumbnail.component";
import { TextFieldComponent } from "../../../../shared/components/fields/text-field.component";
import { FileSizeComponent } from "../../../../libraries/documents/file-size-grid/file-grid-size.component";
import { PersonalizedCellComponent } from "../../../../pages/components/columns/marketing/personalized-cell.component";
import { BasedOnComponent } from "../../../../pages/components/columns/based-on.component";
import { SharedInComponent } from "../../../../shared/components/fields/shared-in.component";
import { COLUMN_NAMES } from "../../components/columns-provider";
import { ChildrenCountComponent } from "../../../../shared/components/fields/children-count-component";
import { AppStore } from "../../../../../services/store/app-store";

@Injectable()
export class ColumnsMap {
    private colMap = new Map<string, ColInitializer>();

    constructor(private appStore: AppStore) {
        this.initColMap();
    }

    tryGetColumnMapping(entity: Entity, tweak: GridData) {
        const initializer = this.colMap.get(tweak.name);
        if (initializer) {
            return initializer.init(entity, tweak);
        }

        return null;
    }

    private initColMap() {
        this.colMap.set(COLUMN_NAMES.TRANSLATIONS, this.createTranslationsInitializer(COLUMN_NAMES.TRANSLATIONS, { type: ListLanguagesComponent }, "-col-size-m -translation", [Properties.AvailableLanguages]));
        this.colMap.set("Marketing", this.createInitializer("Marketing", { type: MarketingCellComponent }, "-col-size-m", [PAGE_COMPUTED_PROPERTIES.MARKETING]));
        this.colMap.set("Calendar", this.createInitializer("Calendar", { type: CalendarGridCellComponent }, "-col-size-m", ["ParentId"]));
        this.colMap.set("Start", this.createInitializer("Start", { type: EventTimeGridCellComponent }, "-col-size-m", [
            EVENT_PROPERTIES.EVENT_START,
            EVENT_PROPERTIES.EVENT_START_UTC_OFFSET,
            EVENT_PROPERTIES.ALL_DAY_EVENT,
            EVENT_PROPERTIES.EVENT_START_WITH_OFFSET
        ]));
        this.colMap.set("End", this.createInitializer("End", { type: EventTimeGridCellComponent }, "-col-size-m", [
            EVENT_PROPERTIES.EVENT_END,
            EVENT_PROPERTIES.EVENT_END_UTC_OFFSET,
            EVENT_PROPERTIES.ALL_DAY_EVENT,
            EVENT_PROPERTIES.RECURRENCE_EXPRESSION,
            EVENT_PROPERTIES.EVENT_END_WITH_OFFSET
        ]));
        this.colMap.set("SharedWith", this.createInitializer("SharedWith", { type: UsageInSitesComponent }, "-col-size-m", [Properties.SHARED_WITH]));
        this.colMap.set("Contains", this.createInitializer("Contains", { type: ListChildrenItemsComponent }, "-col-size-3xl", []));
        this.colMap.set("AppliedTo", this.createInitializer("AppliedTo", { type: AppliedToComponent }, "-col-size-m", [Properties.APPLIED_TO]));
        this.colMap.set("View", this.createInitializer("View", { type: PageViewComponent }, "-col-size-2xs", ["ViewUrl", "PageType"]));
        this.colMap.set("Children", this.createInitializer("Children", { type: ListChildrenCountComponent }, "-col-size-l", []));
        this.colMap.set("Actions", this.createInitializer("Actions", { type: GridActionMenuComponent }, "-action -col-size-3xs", [Properties.AvailableLanguages]));
        this.colMap.set("CreateChild", this.createInitializer("CreateChild", { type: CreateChildComponent }, "-col-size-l", []));
        this.colMap.set(COLUMN_NAMES.MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MainColInitializer));
        this.colMap.set(Properties.PUBLICATION_DATE, this.createInitializer(Properties.PUBLICATION_DATE, { type: DateAndUserComponent }, "", [Properties.LAST_PUBLISHED], DateAndUserInitializer));
        this.colMap.set(Properties.DATE_CREATED, this.createInitializer(Properties.DATE_CREATED, { type: DateAndUserComponent }, "", [Properties.DATE_CREATED, Properties.CREATED_BY], DateAndUserInitializer));
        this.colMap.set(Properties.LAST_MODIFIED, this.createInitializer(Properties.LAST_MODIFIED, { type: DateAndUserComponent }, "", [Properties.LAST_MODIFIED, Properties.LAST_MODIFIED_BY], DateAndUserInitializer));
        this.colMap.set(COLUMN_NAMES.TAXA_MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.TAXA_MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], TaxaMainInitializer));
        this.colMap.set(COLUMN_NAMES.LETTER_COL_NAME, this.createInitializer(COLUMN_NAMES.LETTER_COL_NAME, { type: LetterMarkComponent }, "-group h3", [Properties.TITLE], GroupingColInitializer));
        this.colMap.set(COLUMN_NAMES.TITLE_STATUS_COL_NAME, this.createInitializer(COLUMN_NAMES.TITLE_STATUS_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MainColInitializer));
        this.colMap.set(COLUMN_NAMES.ALBUMS_MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.ALBUMS_MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MediaMainInitializer));
        this.colMap.set(COLUMN_NAMES.MEDIA_TITLE_STATUS_COL_NAME, this.createInitializer(COLUMN_NAMES.MEDIA_TITLE_STATUS_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MediaMainInitializer));
        this.colMap.set(LAST_UPLOADED_ON, this.createInitializer(LAST_UPLOADED_ON, { type: DateAndUserComponent }, "", [Properties.LAST_UPLOADED, Properties.LAST_UPLOADED_BY], DateAndUserInitializer));
        this.colMap.set("FileDimSize", this.createInitializer("FileDimSize", { type: FileDimSizeComponent }, "", [Properties.TOTAL_SIZE, Properties.EXTENSION, Properties.WIDTH, Properties.HEIGHT, Properties.MIME_TYPE]));
        this.colMap.set("Thumbnail", this.createInitializer("Thumbnail", { type: GridThumbnailComponent }, "-col-size-2xs", [Properties.THUMBNAIL_URL, Properties.DATE_CREATED, Properties.URL, Properties.ORDINAL], ClickableColInitializer));
        this.colMap.set("Storage", this.createInitializer("Storage", { type: TextFieldComponent }, "-col-size-l", []));
        this.colMap.set(COLUMN_NAMES.DOCUMENTS_LIBRARY_MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.DOCUMENTS_LIBRARY_MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MediaMainInitializer));
        this.colMap.set("FileSize", this.createInitializer("FileSize", { type: FileSizeComponent }, "", [Properties.TOTAL_SIZE, Properties.EXTENSION]));
        this.colMap.set("Personalization", this.createInitializer("Personalization", { type: PersonalizedCellComponent }, stringConstants.EMPTY_STRING, [Properties.IS_PERSONALIZED]));
        this.colMap.set("BasedOn", this.createInitializer("BasedOn", { type: BasedOnComponent }, "-col-size-xl", [Properties.PARENT_TEMPLATE]));
        this.colMap.set(COLUMN_NAMES.PAGE_TEMPLATES_MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.PAGE_TEMPLATES_MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [Properties.TITLE, Properties.DISPLAY_STATUS, Properties.FRAMEWORK, Properties.THUMBNAIL_URL, Properties.RENDERER], TemplatesMainInitializer));
        this.colMap.set(Properties.PAGES_COUNT, this.createInitializer(Properties.PAGES_COUNT, { type: SharedInComponent }, "-col-size-2xs", [Properties.PAGES_COUNT]));
        this.colMap.set(Properties.USED_ON, this.createInitializer(Properties.USED_ON, { type: SharedInComponent }, "-col-size-m", []));
        this.colMap.set(COLUMN_NAMES.VIDEOS_LIBRARY_MAIN_COL_NAME, this.createInitializer(COLUMN_NAMES.VIDEOS_LIBRARY_MAIN_COL_NAME, { type: MainFieldComponent }, stringConstants.EMPTY_STRING, [], MediaMainInitializer));
        this.colMap.set(Properties.AUTHOR, this.createInitializer(Properties.CREATED_BY, { type: TextFieldComponent }, "", [Properties.CREATED_BY]));
        this.colMap.set(COLUMN_NAMES.RESPONSES_COLUMN_COL_NAME, this.createInitializer(Properties.FORM_RESPONSES, { type: ChildrenCountComponent, properties: { showBadgeForZeroCount: true, childRouteName: "form-responses", dynamicSuffixProp: "Name" } }, "-col-size-m", [Properties.FORM_RESPONSES], FormResponsesColInitializer));
        this.colMap.set(Properties.SUBMITTED_ON, this.createInitializer(Properties.SUBMITTED_ON, { type: DateAndUserComponent }, "", [Properties.SUBMITTED_ON], DateAndUserInitializer));
        this.colMap.set(Properties.SOURCE_SITE_NAME, this.createInitializer(Properties.SOURCE_SITE_NAME, { type: TextFieldComponent }, "", [Properties.SOURCE_SITE_NAME]));
        this.colMap.set(Properties.REFERRAL_CODE, this.createInitializer(Properties.REFERRAL_CODE, { type: TextFieldComponent }, "", [Properties.REFERRAL_CODE]));
        this.colMap.set("Language", this.createInitializer("Language", {
            type: ListLanguagesComponent, properties: {
                readonly: true
            }
        }, "", ["Language"]));
    }

    private createInitializer(name: string, componentData: ComponentData, css: string, dataFieldNames: string[], initializer = ColInitializer): ColInitializer {
        const col: ColumnModel = {
            name,
            componentData,
            css,
            dataFieldNames
        };

        return new initializer(col);
    }

    private createTranslationsInitializer(name: string, componentData: ComponentData, css: string, dataFieldNames: string[]): ColInitializer {
        const col: ColumnModel = {
            name,
            componentData,
            css,
            dataFieldNames
        };

        return new TranslationsColumnInitializer(col, this.appStore);
    }
}
