import { ClassProvider, Injectable } from "@angular/core";
import { FieldRegistryKey, FIELDS_PROVIDER_TOKEN, DefaultFieldsProvider } from "../../../shared/fields-builder/providers/fields-registration-provider";
import { PropertyEditorWidgets } from "../../property-editor.constants";
import { FieldRegistration, FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { EditImageThumbnailComponent } from "../../../libraries/images/edit-image/edit-image-thumbnail.component";
import { PIXELS_NAME } from "../../../html/tools/insert-image/image-helper";
import { MirrorFieldSettings, MIRROR_FIELD_SETTING_KIND } from "../../../../../../fields/short-text/short-text-settings";

@Injectable()
export class CustomSizeFieldProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.fieldType === FieldTypes.customSize && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: EditImageThumbnailComponent,
                settingsType: CustomSizeFieldSettings
            };
    }
}

export class CustomSizeFieldSettings extends SettingsBase implements MirrorFieldSettings {
    public heightSettings: any;
    public widthSettings: any;
    public constrainProportionsSettings: any;
    public dropDownSettings: any = {};
    public customSizeOnly: boolean = true;
    public mirroredFieldName: string;
    public mirroredFieldProperty: string;
    public enableMirroring: boolean;
    public kind: string = MIRROR_FIELD_SETTING_KIND;
    public widthPropertyName;
    public heightPropertyName;
    public constrainProportionsPropertyName;

    public init(metadata: any) {
        super.init(metadata);
        this.widthPropertyName = "Width";
        this.heightPropertyName = "Height";
        this.constrainProportionsPropertyName = "ConstrainProportions";
        this.markAsDirty = true;

        this.constrainProportionsSettings = {
            title: "Constrain proportions",
            key: "ImageThumbnail_constrain_proportions"
        };
        this.widthSettings = {
            title: "Width",
            value: 100,
            unit: PIXELS_NAME
        };
        this.heightSettings = {
            title: "Height",
            value: 100,
            unit: PIXELS_NAME
        };
        //this.defaultValue = {};
    }
}

export const CUSTOM_SIZE_FIELD_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: CustomSizeFieldProvider,
    multi: true
};
