import { Component, OnInit } from "@angular/core";
import { VALIDATOR_MESSAGES } from "../../../../../fields/common/validators/validators.constants";
import { StatusType } from "../../../../../fields/field-status";
import { EntityData } from "../../../api/v1/metadata/entity-data";
import { cloneObject } from "../../../utils";
import { RESOLVE_NAMES } from "../../content/constants";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { MetadataContainer } from "../../shared/services/metadata/meta-data.store";
import { TaxaComponent } from "../taxa/taxa.component";

export const FACET_SINGULAR_NAME = "facetable field";
const FACET_PLURAL_NAME = "facetable fields";
const FACET_DEFAULT_FIELD_NAME = "FieldName";

@Component({
    selector: "sf-facet-taxa",
    templateUrl: "../taxa/taxa.component.html",
})

export class FacetTaxaComponent extends TaxaComponent implements OnInit {
    public ngOnInit(): void {
        this.settings.allowCreate = false;
        this.settings.forceShouldShowAll = true;

        const container = this.route.parent.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const entity = container.entities[ENTITY_SET.FLAT_TAXA];

        const cloneEntity = cloneObject(entity);
        cloneEntity.singularName = FACET_SINGULAR_NAME;

        this.defaultFieldName = FACET_DEFAULT_FIELD_NAME;
        const data: EntityData = {
            metadata: cloneEntity,
            culture: null,
            provider: null
        };

        this.dropdownChipsTreeConfig.treeProperties = {
            displayField: FACET_DEFAULT_FIELD_NAME
        }

        this.entityData = data;

        super.ngOnInit();
    }

    onTaxaEntered(title: string): void {
        if (!this.settings.allowCreate) {
            return;
        }

        super.onTaxaEntered(title);
    }

    validate() {
        if (!this.getValue() || this.getValue().length === 0) {
            const errors = {
                [VALIDATOR_MESSAGES.CUSTOM_ERRORS]: "Select a field"
            };

            this.emitStatus({ type: StatusType.Error, data: errors });
            return false;
        } else {
            return true;
        }
    }

    protected getTaxaName() {
        this.taxaNames = {
            plural: FACET_PLURAL_NAME,
            singular: FACET_SINGULAR_NAME
        };

        this.addButtonTitle = `Select ${this.taxaNames.plural}`;
    }

    protected orderTaxasById(newTaxa: any[], existingTaxa: any[]): any[] {
        const orderedTaxas: any[] = [];

        for (const fieldName of this.value) {
            const taxa: any = newTaxa.find(t => t.FieldName.toLowerCase() === fieldName.toLowerCase());
            if (taxa) {
                orderedTaxas.push(taxa);
            }
        }

        return orderedTaxas;
    }
}
