import { Injectable, Inject, NgZone } from "@angular/core";
import { WINDOW_TOKEN } from "../window.provider";
import { Subject } from "rxjs";

// the offset is used in order not to stick the field to the very top of the viewport
const SCROLL_DURATION = 250;
const TOP_OFFSET = 0.25;
const SCROLL_STEP_DELAY = 25;
const SCROLL_DISTANCE = {
    START: 0,
    END: 1
};

// TODO: browsers have now API for this. The whole service seems obsolete
// TODO: #227311 should be in shared
@Injectable()
export class ScrollService {
    scrollCompleted: Subject<void> = new Subject<void>();

    constructor(@Inject(WINDOW_TOKEN) private window: Window,
                private zone: NgZone) { }

    scrollTo(element: any, shouldAnimate: boolean = false, durationMS: number = SCROLL_DURATION, windowElement: Window = window) {
        let scrollToY = null;
        if (element && element.nativeElement) {
            const calculatedOffset = this.calculateOffset();
            if (element.nativeElement.offsetHeight + calculatedOffset < windowElement.innerHeight) {
                scrollToY = element.nativeElement.offsetTop - calculatedOffset;
            } else {
                scrollToY = element.nativeElement.offsetTop + element.nativeElement.offsetHeight + calculatedOffset - windowElement.innerHeight;
            }
        } else {
            const parsedNumber = Number.parseInt(element);
            if (!isNaN(parsedNumber))
                scrollToY = parsedNumber;
        }

        if (scrollToY !== null) {
            if (!shouldAnimate) {
                windowElement.setTimeout(() => {
                    windowElement.scroll(0, scrollToY);
                    this.scrollCompleted.next();
                }, 0);
            } else {
                this.scrollToPoint(scrollToY, durationMS, windowElement);
            }
        }
    }

    scrollToTop(shouldAnimate: boolean = true, durationMS: number = SCROLL_DURATION, windowElement: Window = window) {
        if (shouldAnimate) {
            this.zone.runOutsideAngular(() => {
                this.scrollToPoint(0, durationMS, windowElement);
            });
        } else if (windowElement.pageYOffset > 0) {
            windowElement.scrollTo(0, 0);
            this.scrollCompleted.next();
        }
    }

    scrollToPoint(point: number, durationMS: number = SCROLL_DURATION, windowElement: Window = this.window) {
        // If start scroll distance is 0 and end scroll distance is 1 => the scroll speed is the end scroll distance devided by the scroll duration.
        const scrollSpeed = SCROLL_DISTANCE.END / durationMS;
        const documentElement = windowElement.document.documentElement;
        const documentElementScrollTop = documentElement.scrollTop || documentElement.scrollTop === 0 ? documentElement : windowElement.document.body;

        this.scrollElementToPoint(documentElementScrollTop, documentElement.scrollTop, point, scrollSpeed, SCROLL_DISTANCE.START, windowElement);
    }

    calculateOffset() {
        return this.window.innerHeight * TOP_OFFSET;
    }

    private scrollElementToPoint(element: HTMLElement, from: number, to: number, speed: number, distance: number = SCROLL_DISTANCE.START, windowElement: Window) {
        if (distance < 0 || distance > 1) {
            element.scrollTop = to;
            this.scrollCompleted.next();
            return;
        }
        element.scrollTop = from - (from - to) * this.easeOutMotion(distance);
        distance += speed * SCROLL_STEP_DELAY;

        windowElement.setTimeout(() => {
            this.scrollElementToPoint(element, from, to, speed, distance, windowElement);
        }, SCROLL_STEP_DELAY);
    }

    // Ease-out scrolling motion. This is easing function to slow down scrolling at the end. Decelerating to zero velocity.
    private easeOutMotion(distance: number): number {
        distance--;
        return distance * distance * distance + 1;
    }
}
