import { Injectable } from "@angular/core";

declare const YT: any;

@Injectable()
export class YouTubePlayerService {
    /**
     * Initializes YouTube player amd returns event object
     * that contains the iframe with the video.
     *
     * @param {PlayerInitData} initData Initialization data needed by the YouTube player.
     * @returns {Promise<any>} Promise with the event object.
     * @memberof YouTubePlayerService
     */
    init(initData: PlayerInitData): Promise<any> {
        return new Promise(resolve => {
            const player = new YT.Player(initData.domElementId, {
                ...initData,
                events: {
                    onReady(event) {
                        resolve(event);
                    }
                }
            });

            return player;
        });
    }
}

/**
 * Contains initialization data needed by the YouTube player.
 *
 * @interface PlayerInitData
 */
export interface PlayerInitData {
    /**
     * The DOM element's ID where the iframe with video will be inserted.
     *
     * @type {string}
     * @memberof PlayerInitData
     */
    domElementId: string;

    /**
     * The ID of the YouTube video which will be retrieved.
     *
     * @type {string}
     * @memberof PlayerInitData
     */
    videoId?: string;

    /**
     * The URL of the video.
     *
     * @type {string}
     * @memberof PlayerInitData
     */
    videoUrl: string;

    /**
     * Parameters for the player.
     * For example: autoplay, startAt etc.
     *
     * @type {object}
     * @memberof PlayerInitData
     */
    playerVars: object;

    /**
     * The width of the video.
     *
     * @type {number}
     * @memberof PlayerInitData
     */
    width?: string;

    /**
     * The height of the video.
     *
     * @type {number}
     * @memberof PlayerInitData
     */
    height?: string;

    /**
     * The title of the video
     *
     * @type {string}
     * @memberof PlayerInitData
     */
    title?: string;
}
