import { Injectable, ClassProvider } from "@angular/core";
import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "./operations-filter";
import { Operation, OPERATION_NAMES } from "../../../../shared/components/action-menu/operation.model";
import { OperationsData } from "./interfaces";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { ExternalAppConfigService } from "../../../../../app-config/external-app-config.service";

/**
 * Filters operations based on the setting in the external configuration file (config.json)
 */
@Injectable()
export class ConfigOperationsFilter implements OperationsFilter {

    constructor(private configService: ExternalAppConfigService) { }

    filter(operations: Operation[], data: OperationsData): Operation[] {
        const changeOwnerOperationAllowedTypes: string[] = this.configService.externalConfig?.changeOwnerAllowedTypes ?? [];
        const isAllowedForCurrentType = changeOwnerOperationAllowedTypes.indexOf(data.dataItem.metadata.setName) > -1;
        // Pages should always have the operation
        if (data.dataItem.metadata.setName !== ENTITY_SET.PAGES && !isAllowedForCurrentType) {
            return operations.filter(o => o.Name !== OPERATION_NAMES.changeOwner);
        }

        return operations;
    }
}

export const CONFIG_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: ConfigOperationsFilter
};
