import { HttpClient } from "@angular/common/http";
import { Injectable, ClassProvider } from "@angular/core";
import { BulkItemSelectionInfo } from "../content/dynamic-modules/components/bulk-operations/bulk-operations.component";
import { DataItem, EntityData } from "../content/dynamic-modules/interfaces";
import { BulkCommandExtenderBase } from "../content/dynamic-modules/services/operations/commands/bulk-command-extender-base";
import { BULK_COMMAND_EXTENDER_TOKEN } from "../content/dynamic-modules/services/operations/commands/composite-bulk-command-extender";
import { Command } from "../shared/commands/command";
import { ActionButton } from "../shared/components/action-menu/action-menu-model";
import { ExportToExcelCommand } from "./export-to-excel-command";
import { FormHelpers } from "./form.helpers";

@Injectable()
export class FormResponsesBulkCommandExtender extends BulkCommandExtenderBase {
    constructor(private httpClient: HttpClient) {
        super();
    }

    isSupportedType(entityData: EntityData): boolean {
        return FormHelpers.isFormResponseItem(entityData.metadata);
    }

    tryHandleCommand(action: ActionButton, data: {dataItems: DataItem[], entityData: EntityData, notificationFilter: string, bulkItemSelectionInfo: BulkItemSelectionInfo}): Command {
        if (action.name === "ExportToExcel") {
            return new ExportToExcelCommand(this.httpClient);
        }

        return super.tryHandleCommand(action, data);
    }
}

export const FORM_RESPONSES_BULK_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: BULK_COMMAND_EXTENDER_TOKEN,
    useClass: FormResponsesBulkCommandExtender
};
