import { createReducer, on, combineReducers } from "@ngrx/store";
import { UploadInfo } from "../../../modules/libraries/services/media.service";
import { MEDIA_ACTIONS } from "../actions/actions.media";
import { MediaState, MediaWithTotalCount } from "../schemas/schema.media";
import { initialState } from "../store-schema";

const foldersDataReducer = createReducer<MediaWithTotalCount>(initialState.media.foldersData,
    on(MEDIA_ACTIONS.setFolders, (state, { folders, totalFolders }) => {
        return {
            items: folders,
            totalCount: totalFolders
        };
    })
);

const filesDataReducer = createReducer<MediaWithTotalCount>(initialState.media.filesData,
    on(MEDIA_ACTIONS.setFiles, (state, { files, totalFiles }) => {
        return {
            items: files,
            totalCount: totalFiles
        };
    })
);

const uploadsDataReducer = createReducer<UploadInfo>(initialState.media.uploadsData,
    on(MEDIA_ACTIONS.setUploads, (state, { items, updatedItem, uploadFieldState }) => {
        return {
            items: items,
            updatedItem: updatedItem,
            uploadFieldState: uploadFieldState
        };
    })
);

export const mediaReducer = combineReducers<MediaState>({
    foldersData: foldersDataReducer,
    filesData: filesDataReducer,
    uploadsData: uploadsDataReducer
});
