import { Component, OnInit } from "@angular/core";
import { FeatureToggleService, Feature } from "../../modules/shared/feature-toggle/feature-toggle.service";

@Component({
    selector: "sf-feature",
    templateUrl: "./feature.component.html"
})
export class FeatureComponent implements OnInit {
    public items;

    constructor(private featureService: FeatureToggleService) { }

    ngOnInit(): void {
        this.items = this.featureService.featureConfig;
    }

    onCheckBoxCheck(item: Feature) {
        this.featureService.setFeatureState(item.name, !item.enabled);
    }

    onItemSelectionChanged (item: Feature) {
        item.enabled = !item.enabled;
    }
}
