import { Injectable, ClassProvider } from "@angular/core";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../shared/services/edit/edit-extender";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../../content/dynamic-modules/interfaces";

const TAXONOMY_FORM_CLASS = "-medium";

@Injectable()
export class TaxonomyEditExtender extends EditExtender {

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.CLASSIFICATIONS ||
            entityData.metadata.setName === ENTITY_SET.FLAT_TAXA ||
            entityData.metadata.setName === ENTITY_SET.HIERARCHY_TAXA;
    }

    getFormClasses(): string {
        return TAXONOMY_FORM_CLASS;
    }

    showHeader(entityData: EntityData): boolean {
        return true;
    }
}

export const TAXONOMY_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: TaxonomyEditExtender
};
