import { Injectable } from "@angular/core";
import { Settings } from "../../shared/services/settings.service";
import { SiteDataStore } from "../../shared/services/metadata/site-data.store";
import { Observable } from "rxjs";
import { map } from "rxjs/operators";
import TAXONOMY_CONSTANTS from "../taxonomy.constants";

@Injectable()
export class HierarchicalTaxonExpandService {
    constructor(private settings: Settings, private siteDataStore: SiteDataStore) {
    }

    getExpandedNodeIds(): Observable<string[]> {
        return this.siteDataStore.getValue().pipe(map(x => {
            const key = x.SiteMapRootNodeId + TAXONOMY_CONSTANTS.HIERARCHICAL_TAXON_FULL_NAME;
            return this.settings.getExpandedNodeIds(key);
        }));
    }

    setExpandedNodeIds(expandedIds: string[]): void {
        this.siteDataStore.getValue().pipe(map(x => {
            const key = x.SiteMapRootNodeId + TAXONOMY_CONSTANTS.HIERARCHICAL_TAXON_FULL_NAME;
            return this.settings.setExpandedNodeIds(key, expandedIds);
        })).subscribe();
    }

    clearExpandedNodeIds() {
        this.siteDataStore.getValue().subscribe(x => {
            const key = x.SiteMapRootNodeId + TAXONOMY_CONSTANTS.HIERARCHICAL_TAXON_FULL_NAME;
            return this.settings.setExpandedNodeIds(key, []);
        });
    }
}
