import { Component, Input, OnInit } from "@angular/core";
import { BehaviorSubject } from "rxjs";
import { DataItem } from "../../src/app/modules/content/dynamic-modules/interfaces";
import { Properties } from "../../src/app/modules/shared/fields.constants";
import { SCHEDULED } from "../resolvers/base-status.resolver";
import { SfRxBase, TooltipConfig } from "@progress/sitefinity-component-framework";

const REJECTED_TEXT = "Rejected";
const SEE_WHY_TEXT = "See why?";
const VIEW_NOTES_TEXT = "View notes";

@Component({
    selector: "sf-click-notification",
    templateUrl: "./click-notification.component.html"
})
export class ClickNotificationComponent extends SfRxBase implements OnInit {
    @Input() item: BehaviorSubject<DataItem>;
    @Input() tooltipContext: TooltipConfig = {
        isVisible: false,
        isLink: true,
        look: "tooltip down-left"
    };

    ngOnInit() {
        if (!this.item) {
            return;
        }

        const subscription = this.item.subscribe(value => {
            if (value.isEmpty) {
                return;
            }

            const statuses = value.data[Properties.DISPLAY_STATUS];
            if (!statuses) {
                return;
            }

            const statusWithDescription = statuses.find(status => status.Message?.Description && status.Name !== SCHEDULED);

            if (statusWithDescription) {
                if (statusWithDescription.Name.indexOf(REJECTED_TEXT) !== -1) {
                    this.tooltipContext.linkText = SEE_WHY_TEXT;
                } else {
                    this.tooltipContext.linkText = VIEW_NOTES_TEXT;
                }

                this.tooltipContext.isVisible = true;
                this.tooltipContext.caption = statusWithDescription.Message.Title;
                this.tooltipContext.description = statusWithDescription.Message.Description;
            } else {
                this.tooltipContext.isVisible = false;
            }
        });

        this.registerSubscription(subscription);
    }
}
