import { createAction, props } from "@ngrx/store";
import { ContentSelectorData } from "../schemas/schema.fields";

const FieldsChangeTypeAction = createAction(
    "[Fields] Change item type",
    props<ContentSelectorData>()
);

const FieldsChangeViewNameAction = createAction(
    "[Fields] Change view name",
    props<{ viewName: string }>()
);

export const FIELDS_ACTIONS = {
    changeItemType: FieldsChangeTypeAction,
    changeViewName: FieldsChangeViewNameAction
};
