import { Component, ViewChild, TemplateRef, Inject, OnInit, OnDestroy } from "@angular/core";
import { StateWrapper } from "../../content/dynamic-modules/services/dynamic-item-store-state";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { FormsService } from "../services/forms.service";
import { LeftNavbarButtonMode, NavbarModes, NavbarConfiguration } from "../../shared/components/navigation/navigation-menu/navigation-menu.component";
import { stringConstants } from "../../../common-constants";
import { ConfirmButton, Button, CancelButton, DialogData, ModalWindowService, ClosingContext, ClickResult, ClickData } from "../../shared/services/modal-window.service";
import { FormRuleCreateComponent } from "./form-rule-create.component";
import { ActivatedRoute, Router } from "@angular/router";
import { FormDefinition, FormRule, FormRuleCondition, FormRuleAction, FormsConstants } from "../forms.constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { DOCUMENT_TOKEN } from "../../../document.provider";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { cloneObject, toggleIrisIntegratedStyles } from "../../../utils";
import { SiteDataStore, SiteData } from "../../shared/services/metadata/site-data.store";
import { toLoadingState, delayEmission } from "../../shared/rxjs-extensions";
import { MINIMUM_LOADER_TIME } from "../../../../../fields/loader-wrapper/loader-wrapper.component";
import { TreeConfig } from "../../../../../fields";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../../constants/route-paths";
import { ReplaySubject } from "rxjs";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";
import { mergeMap } from "rxjs/operators";

@Component({
    templateUrl: "./form-rules-list.component.html"
})
export class FormRulesListComponent extends SfRxBase implements OnInit, OnDestroy {
    public shouldHideHeader: boolean = true;
    public stateWrapper: StateWrapper = StateWrapper.empty();
    public navbarConfiguration: NavbarConfiguration;
    public treeConfig: TreeConfig;
    public formDefinition: FormDefinition;
    public formId: string;
    public canUpdate: boolean = true;
    public formPath: string;
    public isInitialRulesLoadComplete = false;
    public hasFields: boolean = false;

    private culture: string;
    @ViewChild("navigationMenuTemplate", { static: true })
    private navigationMenuTemplate: TemplateRef<any>;

    constructor(
        private formsService: FormsService,
        private metadataStore: MetadataStore,
        private modalService: ModalWindowService,
        private route: ActivatedRoute,
        private router: Router,
        @Inject(DOCUMENT_TOKEN) private document: Document,
        private siteData: SiteDataStore) {
        super();
    }

    ngOnInit() {
        this.toggleEditFormControlCssClass();
        this.route.queryParamMap.pipe(
            mergeMap(map => {
                this.formId = map.get("id");
                this.culture = map.get("culture") || stringConstants.EMPTY_STRING;
                this.formPath = map.get("path");
                return this.siteData.getValue();
            }),
            mergeMap((x: SiteData) => {
                this.culture = this.culture || x.DefaultContentCulture;
                return this.formsService.getFormDefinition(this.formId, this.culture);
            }),
            toLoadingState(),
            delayEmission(MINIMUM_LOADER_TIME)
        )
            .subscribe(itemResponse => {
                if (itemResponse.isLoading) {
                    return;
                }

                try {
                    const form = itemResponse.content;
                    this.formDefinition = cloneObject(form.data);
                    this.formDefinition.Rules = this.getFormRules();
                    this.formDefinition.Culture = this.culture;
                    this.propagateRules(false);
                    this.hasFields = this.formDefinition.Fields && this.formDefinition.Fields.length > 0;
                    this.isInitialRulesLoadComplete = true;
                } catch (err) {
                    this.handleFormRuleFetchError(err);
                }
            }, err => {
                this.handleFormRuleFetchError(err);
            });

        this.navbarConfiguration = {
            mode: NavbarModes.OneColumn,
            leftNavbarButtonData: {
                show: true,
                look: "toggle",
                icon: "angle-left",
                iconLook: "size-2xl",
                mode: LeftNavbarButtonMode.Back,
                title: FormsConstants.BACK_TO_FORMS
            },
            isScrollEnabled: false,
            look: stringConstants.EMPTY_STRING,
            templates: [this.navigationMenuTemplate]
        };

        this.treeConfig = {
            noSelection: true
        };
    }

    ngOnDestroy() {
        this.toggleEditFormControlCssClass(false);
    }

    public createRule(dataItem: DataItem) {
        const formRuleOriginal = dataItem ? dataItem.data : null;
        const formRuleIndex = dataItem ? this.stateWrapper.dataItems.indexOf(dataItem) : -1;
        const formRule = dataItem ? cloneObject(formRuleOriginal) : null;
        const componentData: ComponentData = {
            type: FormRuleCreateComponent,
            afterComponentInit: (component: FormRuleCreateComponent) => {
                component.title = dataItem ? FormsConstants.EDIT_A_RULE : FormsConstants.CREATE_A_RULE;
                component.formDefinition = this.formDefinition;
                component.formRule = formRule;
            }
        };

        let buttons: Button[] = [
            new ConfirmButton(FormsConstants.CREATE_THIS_RULE, (context: ClickData) => this.saveFormRulehandler(context, formRuleIndex)),
            new CancelButton(FormsConstants.CANCEL)
        ];
        if (dataItem) {
            buttons = [
                new ConfirmButton(FormsConstants.SAVE_THIS_RULE, (context: ClickData) => this.saveFormRulehandler(context, formRuleIndex)),
                new CancelButton(FormsConstants.CANCEL)
            ];
        }
        const dialogData = new DialogData(componentData, (context: ClosingContext) => { }, buttons, null);

        this.modalService.setMapping(dialogData, FormsConstants.ROUTES.CREATE_FORM_RULE_DIALOG);
        this.modalService.show(FormsConstants.ROUTES.CREATE_FORM_RULE_DIALOG, this.route);
    }

    saveFormRulehandler(context: ClickData, formRuleIndex: number): ReplaySubject<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);
        clickResult.next(new ClickResult(true, false));
        const formRule: FormRule = (context.component as FormRuleCreateComponent).formRule;
        if (formRule) {
            formRule.Actions.forEach(formRuleAction => {
                if (formRuleAction.Action === FormsConstants.FORM_ACTION_TYPE.SEND_NOTIFICATION) {
                    formRuleAction.Target = formRuleAction.Target
                        .trim()
                        .split("\n")
                        .filter(s => s !== stringConstants.EMPTY_STRING)
                        .map(s => s.trim())
                        .join(",");
                }
            });

            if (formRuleIndex >= 0) {
                this.formDefinition.Rules.splice(formRuleIndex, 1, formRule);
            } else {
                this.formDefinition.Rules.push(formRule);
            }

            // we don't want the save to be done in the propagate rules method because we need to next the subject responsible for the loading of the button after the save is done
            this.propagateRules(false);

            this.canUpdate = false;
            this.formsService.updateRules(this.formDefinition).subscribe(result => {
                this.canUpdate = true;
                clickResult.next(new ClickResult(true, true, false, false));
            });
        }

        return clickResult;
    }

    public getFormRules(): FormRule[] {
        const formRules: FormRule[] = [];
        this.formDefinition.Rules.forEach(formRule => {
            const conditions: FormRuleCondition[] = [];
            formRule.Conditions.forEach(condition => {
                if (this.findFormField(condition.Id)) {
                    conditions.push(condition);
                }
            });

            const actions: FormRuleAction[] = [];
            formRule.Actions.forEach(action => {
                switch (action.Action) {
                    case FormsConstants.FORM_ACTION_TYPE.SHOW:
                    case FormsConstants.FORM_ACTION_TYPE.HIDE:
                        if (this.findFormField(action.Target)) {
                            actions.push(action);
                        }
                        break;
                    case FormsConstants.FORM_ACTION_TYPE.SKIP:
                        if (this.findFormStep(action.Target)) {
                            actions.push(action);
                        }
                        break;
                    default:
                        actions.push(action);
                }
            });

            if (conditions.length > 0 && actions.length > 0) {
                formRule.Conditions = conditions;
                formRule.Actions = actions;
                formRules.push(formRule);
            }
        });

        return formRules;
    }

    public findFormField(id: string) {
        return this.formDefinition.Fields.find(c => c.Id === id);
    }

    public findFormStep(stepNumber: string) {
        return this.formDefinition.Steps.find(s => s.Key === stepNumber);
    }

    public onNavigateBack() {
        if (this.formDefinition.Renderer) {
            this.router.navigate([ROUTE_PATHS.FORMS, ROUTE_PATHS_NO_PREFIX.SF_EDIT, this.formId], {
                queryParams: {
                    sfaction: "Edit"
                }
            });
        } else {
            this.document.dispatchEvent(new Event(FormsConstants.ROUTES.SITEFINITY_OLD_BACKEND_REFRESH_RULES_EVENT_NAME));
            const currentFormPath = this.formPath ?? FormsConstants.ROUTES.INTEGRATED;
            this.router.navigate([ROUTE_PATHS.CONTENT, ROUTE_PATHS_NO_PREFIX.FORMS, currentFormPath, this.formDefinition.Name]);
        }
    }

    public propagateRules(save: boolean) {
        const _relatedDataEntity = this.metadataStore.getEntity(ENTITY_SET.FORM_DRAFTS);
        const dataItems: DataItem[] = [];
        this.formDefinition.Rules.forEach(rule => {
            dataItems.push(DataItem.from(rule, _relatedDataEntity, null, null));
        });

        this.stateWrapper = StateWrapper.wrap({
            dataItems: dataItems,
            totalCount: dataItems.length
        });

        if (save) {
            this.canUpdate = false;
            this.formsService.updateRules(this.formDefinition).subscribe(result => {
                this.canUpdate = true;
            });
        }
    }

    public deleteRule(dataItem) {
        const index = this.stateWrapper.dataItems.indexOf(dataItem);
        if (index >= 0) {
            this.formDefinition.Rules.splice(index, 1);
        }

        this.propagateRules(true);
    }

    private toggleEditFormControlCssClass(addClass: boolean = true) {
        if (addClass) {
            toggleIrisIntegratedStyles(true);
            this.document.body.classList.add(FormsConstants.ROUTES.ADMIN_APP_CONTROL_CLASS);
        } else {
            toggleIrisIntegratedStyles(false);
            this.document.body.classList.remove(FormsConstants.ROUTES.ADMIN_APP_CONTROL_CLASS);
        }
    }

    private handleFormRuleFetchError(err: any) {
        // TODO: this should be handled in a better way or kept as is depending on the resolution of Product Backlog Item 321976: Iris: Global error notification view
        throw new Error(`An error occurred during fetching the form rules. ${err}`);
    }
}
