import { Media, MediaType } from "./media";
import { Injectable } from "@angular/core";
import { EmbedMediaParser } from "./embed-media.parser";
import { contentTypeConstants } from "../../../common-constants";
import { TWEET_URL_ATTRIBUTE_NAME, NODE_NAMES, TWEET_URL_NAME } from "../selector-constants";
import { HttpClient } from "@angular/common/http";

declare const twttr: any;

@Injectable()
export class TwitterMediaParser extends EmbedMediaParser {
    private static tweetUrlRegex: RegExp;
    private static tweetUrlRegexExact: RegExp;
    constructor(private http: HttpClient) {
        super();
        TwitterMediaParser.tweetUrlRegex = new RegExp("(https?:\\/\\/twitter.com\\/(\\w+)\\/status\\/(\\d+))");
        TwitterMediaParser.tweetUrlRegexExact = new RegExp("(^https?:\\/\\/twitter.com\\/(\\w+)\\/status\\/(\\d+))");
    }

    isExactMatch(inputText: string): boolean {
        if (!inputText) {
            return false;
        }

        inputText = inputText.trim();

        if (TwitterMediaParser.tweetUrlRegexExact.test(inputText)) {
            return true;
        }
        return false;
    }

    canProcess(html: string): boolean {
        const isTweetUrl = TwitterMediaParser.tweetUrlRegex.test(html);
        if (isTweetUrl) {
            return true;
        }

        const canLoadTweetFromHtml = this.canLoadTweetFromHtml(html);
        return canLoadTweetFromHtml;
    }

    initEmbeddedData() {
        // if (twttr) { } is not enough for a check. When the twitter script is loaded in the DOM, twttr is not defined and the check throws `twttr is not defined`
        try {
            if (twttr) {
                twttr.widgets.load();
            }
        } catch (e) {
            if (!e.message.includes("twttr is not defined")) {
                throw e;
            }
        }
    }

    parse(html: string): Promise<Media> {
        let tweetUrl = html;

        const isTweetUrl = TwitterMediaParser.tweetUrlRegexExact.test(html);
        if (!isTweetUrl) {
            tweetUrl = this.getTweetUrlFromHtml(html);
        }

        return this.getTweetDataByUrl(tweetUrl)
            .then(data => {
                const isValid = !!data && data.url === tweetUrl;
                const media = new Media();

                media.type = MediaType.Tweet;
                media.isValid = isValid;

                if (isValid) {
                    const tweetWrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
                    const quoteElement = document.createElement(NODE_NAMES.DIV_ELEMENT);

                    media.data = data;

                    tweetWrapper.appendChild(quoteElement);
                    tweetWrapper.setAttribute(TWEET_URL_NAME, media.data.url);
                    quoteElement.outerHTML = data.html;

                    media.html = tweetWrapper.outerHTML;
                }

                return media;
            });
    }

    getMediaFromElement(element: HTMLElement): HTMLElement {
        if (!element) {
            return null;
        }

        const twitterWidget = <HTMLElement>element.querySelector("twitterwidget");
        return twitterWidget;
    }

    updateMediaElement(element: HTMLElement, propName: string, value: any) {
        element.style[propName] = value;
    }

    private getTweetDataByUrl(url: string): Promise<any> {
        return new Promise<any>((resolve) => {
            const requestUrl = `https://publish.twitter.com/oembed?url=${url}&omit_script=true&callback=JSONP_CALLBACK`;

            this.http.get(requestUrl)
                .toPromise()
                .then(data => resolve(data))
                .catch(() => resolve(null));
        });
    }

    private getTweetUrlFromHtml(tweetHtml: string): string {
        if (tweetHtml) {
            const match = tweetHtml.match(TwitterMediaParser.tweetUrlRegex);
            if (match) {
                return match[0];
            }
        }

        const domParser = new DOMParser();
        const document = domParser.parseFromString(tweetHtml, <DOMParserSupportedType>contentTypeConstants.HTML);
        const tweetBlockquote = document.body.querySelector("blockquote.twitter-tweet");
        if (tweetBlockquote) {
            const allAnchorTags = tweetBlockquote.querySelectorAll("a");
            for (let i = 0; i < allAnchorTags.length; i += 1) {
                const url = (<HTMLAnchorElement>allAnchorTags[i]).href;
                if (TwitterMediaParser.tweetUrlRegex.test(url)) {
                    return url.match(TwitterMediaParser.tweetUrlRegex)[0];
                }
            }
        }

        const twitterWidget = document.body.querySelector("twitterwidget.twitter-tweet");

        if (twitterWidget) {
            return twitterWidget.getAttribute(TWEET_URL_ATTRIBUTE_NAME);
        }

        return null;
    }

    private canLoadTweetFromHtml(tweetHtml: string): boolean {
        return this.getTweetUrlFromHtml(tweetHtml) !== null;
    }
}
