import {
    Injectable,
    Injector,
    ComponentFactoryResolver,
    EmbeddedViewRef,
    ApplicationRef,
    ComponentRef,
    Type
} from "@angular/core";

@Injectable()
export class ZoneEditorDomService {

    constructor(
        private componentFactoryResolver: ComponentFactoryResolver,
        private appRef: ApplicationRef,
        private injector: Injector
    ) { }

    createComponent(component: Type<any>, componentProps?: object) {
        const componentRef = this.componentFactoryResolver
            .resolveComponentFactory(component)
            .create(this.injector);

        if (componentProps && typeof componentRef.instance === "object") {
            Object.assign(componentRef.instance as object, componentProps);
        }

        return componentRef;
    }

    attachComponentAsLastChild(componentRef: ComponentRef<unknown>, referenceElement: Element, componentClass?: string, attribute?: {}) {
        const domElem = this.prepareElement(componentRef, componentClass, attribute);

        referenceElement.append(domElem);
        return domElem;
    }

    attachComponentBeforeElement(componentRef: ComponentRef<unknown>, referenceElement: Node, componentClass?: string, attribute?: {}) {
        const domElem = this.prepareElement(componentRef, componentClass, attribute);
        referenceElement.parentElement.insertBefore(domElem, referenceElement);
        return domElem;
    }

    attachComponentAfterElement(componentRef: ComponentRef<unknown>, referenceElement: Node, componentClass?: string, attribute?: {}) {
        const domElem = this.prepareElement(componentRef, componentClass, attribute);

        if (referenceElement.nextSibling) {
            referenceElement.parentElement.insertBefore(domElem, referenceElement.nextSibling);
        } else {
            referenceElement.parentElement.append(domElem);
        }
        return domElem;
    }

    attachComponentAsFirstChild(componentRef: ComponentRef<unknown>, referenceElement: Element, componentClass?: string, attribute?: {}) {
        const domElem = this.prepareElement(componentRef, componentClass, attribute);
        referenceElement.prepend(domElem);
        return domElem;
    }

    removeComponent(componentRef: ComponentRef<unknown>) {
        const domElem = this.prepareElement(componentRef);
        domElem.parentNode?.removeChild(domElem);
    }

    hasDirectChildrenWithNodeType(element: Element | Document, tagName: string): boolean {
        for (let i = 0; i < element.childNodes.length; i++) {
            const node = element.childNodes[i] as Element;
            if (node.tagName && node.tagName.toLowerCase() === tagName.toLowerCase()) {
               return true;
            }
        }

        return false;
    }

    hasDirectChildrenWithClass(element: Element | Document, className: string): boolean {
        for (let i = 0; i < element.childNodes.length; i++) {
            const node = element.childNodes[i] as Element;
            if (node.classList && node.classList.contains(className)) {
               return true;
            }
        }

        return false;
    }

    handleMultipleInsertBefore(elements: any[], beforeElement: Element) {
        elements.forEach(el => {
            beforeElement.parentElement.insertBefore(el, beforeElement);
        });
    }

    handleMultipleAppend(elements: any[], parent: Element) {
        elements.forEach(el => {
            parent.append(el);
        });
    }

    private prepareElement(componentRef: ComponentRef<unknown>, componentClass?: string, attribute?: {}): HTMLElement {
        this.appRef.attachView(componentRef.hostView);
        const domElem = (componentRef.hostView as EmbeddedViewRef<any>)
            .rootNodes[0] as HTMLElement;

        if (componentClass) {
            const componentClassArray = componentClass.split(" ");
            domElem.classList.add(...componentClassArray);
        }

        if (attribute) {
            const attributeKey = Object.keys(attribute)[0];
            domElem.setAttribute(attributeKey, attribute[attributeKey]);
        }

        return domElem;
    }
}
