import { Component, Input, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { FILTER_PARAMS } from "../../../../constants";
import { DataContext, DataContextComponent } from "../../../../../shared/models/data-context-component";
import { Properties } from "../../../../../shared/fields.constants";
import { stringConstants } from "../../../../../../common-constants";
import { ContentFilterService } from "../../../../../shared/services/content-filter.service";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { SfRxBase, TextMatchType } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-main-field",
    templateUrl: "./main-field.component.html"
})
export class MainFieldComponent extends SfRxBase implements OnInit, DataContextComponent {
    @Input() public context: DataContext;
    @Input() public breakTitleWords: boolean = true;
    @Input() public hasStatusIcon: boolean = true;
    @Input() public showStatusText: boolean = true;

    public searchParameter: string;
    public statusLook: string;
    public textMatchType = TextMatchType.StartsWith;
    public showBreadcrumbInStatus: boolean = false;
    public iconProperties: IconProperties;
    public hasThumbnail: boolean = false;
    public thumbnailLabelProperty: string;
    public thumbnailLabel: string;

    rowCssClass: string = "sf-row -no-wrap";
    titleWrapperCssClass: string = "sf-row__col";
    titleCssClass: string = "-sf-mt-zero -sf-mb-zero";
    protected statusCssClass: string = "sf-row__col -no-flex";

    constructor(private route: ActivatedRoute, private filterService: ContentFilterService) {
        super();
    }

    ngOnInit() {
        this.statusLook = this.calculateStatusLook();

        if (this.context.dataItem.metadata.isSelfReferencing && this.context.dataItem.data[Properties.BREADCRUMB]) {
            this.showBreadcrumbInStatus = true;
        }

        if (this.context.dataItem.data[Properties.THUMBNAIL_URL] && !MediaHelpers.isMediaEntity(this.context.dataItem)) {
            this.hasThumbnail = true;
        }

        if (this.thumbnailLabelProperty && !this.context.dataItem.data[Properties.RENDERER]) {
            this.thumbnailLabel = this.context.dataItem.data[this.thumbnailLabelProperty];
        }

        // TODO: maybe the list should know about searches and pass this information to it's child components
        const queryParamsSubscription = this.route.queryParams.subscribe((params) => {
            const searchParam: string = params[FILTER_PARAMS.SEARCH];
            if (searchParam) {
                const searchQueryParamsPairs = this.filterService.deserializeQueryParams(searchParam);
                searchQueryParamsPairs.forEach(pair => {
                    if (pair.value.length) {
                        this.searchParameter = pair.value[0].toString();
                    }
                });
            }

            const isSearchActive = !!params[FILTER_PARAMS.SEARCH];
            const isFilterActive = !!params[FILTER_PARAMS.FILTER];
            const isSortActive = !!params[FILTER_PARAMS.SORT];

            // show detailed breadcrumb in status ONLY in flat structure of the grid
            if (this.showBreadcrumbInStatus && (isSearchActive || isFilterActive || isSortActive)) {
                this.showBreadcrumbInStatus = true;
            } else {
                this.showBreadcrumbInStatus = false;
            }
        });

        this.registerSubscription(queryParamsSubscription);

        this.generateCssClassList();
    }

    generateCssClassList() {
        if (this.breakTitleWords) {
            this.titleCssClass += " -sf-word-break-word";
            if (this.context.dataItem.metadata.hasChildren && !this.context.dataItem.metadata.isSelfReferencing) {
                this.titleCssClass += " h3";
            } else {
                this.titleCssClass += " -sf-txt-large";
                this.statusCssClass += " -sf-mt-4xs";
            }
        } else {
            this.rowCssClass += " -align-items-center";
            this.titleWrapperCssClass += " -sf-overflow-hidden";
            this.titleCssClass += " -sf-overflow-ellipsis -sf-block";
        }

        if (!this.context.dataItem.isTranslated) {
            this.titleWrapperCssClass += " -sf-txt-dimmed";
        }
    }

    private calculateStatusLook(): string {
        const lookList = ["sf-mr-xs"];
        if (!this.context.dataItem.isTranslated || this.context.dataItem.data.inactive) {
            lookList.push("dimmed");
        }
        if (this.breakTitleWords) {
            lookList.push("sf-mt-6xs");
        }
        return lookList.join(stringConstants.INTERVAL);
    }
}

interface IconProperties {
    name: string;
    look: string;
    inner: boolean;
}
