import { Injectable } from "@angular/core";
import { AsyncSubject, Observable, of } from "rxjs";
import { SitefinityInsightConfiguration } from "../interfaces/sitefinity-insight-configuration";
import { DateTimeUtilsService } from "./date-time-utils.service";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { MetadataStore } from "../../services/metadata/meta-data.store";
import { flatMap, map } from "rxjs/operators";

@Injectable()
export class ConnectorService {

    private lastAccessInTimeTicks: number;
    private lastConfigValue$: AsyncSubject<SitefinityInsightConfiguration> = null;
    public static readonly INSIGHT_SETTINGS_ACTION_NAME = "Default.InsightSettings()";
    private configResolved = false;

    constructor(
        private dateTimeUtils: DateTimeUtilsService,
        private dynamicItemService: DynamicItemService,
        private metadataStore: MetadataStore
    ) {
        this.lastAccessInTimeTicks = 0;
    }

    getConnectorDetails(): Observable<SitefinityInsightConfiguration> {
        const nowInTicks = this.dateTimeUtils.getNow().getTime();
        const expired = nowInTicks - this.lastAccessInTimeTicks > 10000;
        if (this.lastConfigValue$ == null || !this.configResolved || expired) {
            this.lastAccessInTimeTicks = nowInTicks;
            this.lastConfigValue$ = new AsyncSubject<SitefinityInsightConfiguration>();
            const settings$ = this.dynamicItemService.executeUnboundFunction<any>(ConnectorService.INSIGHT_SETTINGS_ACTION_NAME);
            settings$.subscribe((result) => {
                const config = JSON.parse(result.value);
                this.lastConfigValue$.next(config);
                this.lastConfigValue$.complete();
                this.configResolved = true;
            }, (error) => {
                this.lastConfigValue$.error(error);
                this.lastConfigValue$.complete();
                this.configResolved = false;
            });
        }

        return this.lastConfigValue$;
    }

    isSitefinityInsightEnabled(): Observable<boolean> {
        return this.metadataStore.initialize().pipe(flatMap(container => {
            if (container.modulesAvailability && container.modulesAvailability.insight) {
                return this.getConnectorDetails().pipe(
                    map((config) => config !== null && config.IsDecEnabled && config.DataCenterApiKey != null));
            } else {
                return of(false);
            }
        }));
    }
}
