import { Component, OnInit, Input, ViewChild, AfterViewInit } from "@angular/core";
import { ModalTab, ModalSelectorSettings, LoadDataResult } from "./modal-selector-interfaces";
import { SfRxBase, SfSearchComponent, SfTabsComponent } from "@progress/sitefinity-component-framework";
import { Subject } from "rxjs";
import { CloseModalCallback } from "../../services/modal-window.service";
import { WidgetItem } from "../../../pages/services/renderer.types";
import { NgxMasonryOptions } from 'ngx-masonry';
import { DEFAULT_TAKE } from "../../../pages/components/zone-editor/enhanced-page.component";
import { PropertyEditorSections } from "../../../widget-editor/property-editor.constants";

@Component({
    selector: "sf-modal-selector",
    templateUrl: "./modal-selector.component.html"
})
export class ModalSelectorComponent extends SfRxBase implements OnInit, AfterViewInit, CloseModalCallback {
    @Input() settings: ModalSelectorSettings<WidgetItem>;
    @ViewChild(SfTabsComponent, { static: true }) tabsComponent: SfTabsComponent;
    @ViewChild(SfSearchComponent, { static: true }) searchComponent: SfSearchComponent;
    dataContext$ = new Subject<LoadDataResult<WidgetItem>>();
    masonryOptions: NgxMasonryOptions = {
      gutter: ".sf-masonry__gutter"
    };
    isLoading = false;

    private closeModalCallback: (data: any) => void;
    private lastDataContext: LoadDataResult<WidgetItem>;
    private pageNumber = 0;
    private itemsRendered = 0;

    ngOnInit(): void {
        this.settings.data.searchPlaceholderText = this.settings.data.searchPlaceholderText || "Search...";
    }

    ngAfterViewInit(): void {
        this.loadData(null, null);
    }

    onTabClick(tab: ModalTab) {
        this.loadData(tab, null);
    }

    onSearch(searchVal: string) {
        this.loadData(null, searchVal);
    }

    onWidgetSelection(item: WidgetItem) {
        this.closeModalCallback(item);
    }

    setCloseModalCallback(closeModalCallback: (data: any) => void): void {
        this.closeModalCallback = closeModalCallback;
    }

    loadMore() {
        if (this.lastDataContext.dataItems.flatMap(x => x.items).length < this.lastDataContext.totalCount) {
            this.loadData(null, null, ++this.pageNumber * DEFAULT_TAKE);
        }
    }

    // this is called once for every item and twice for every first item in a grid
    layoutComplete() {
        // remove loader when all items are rendered
        if (this.lastDataContext.dataItems.flatMap(x => x.items).length + this.lastDataContext.dataItems.length === ++this.itemsRendered) {
            this.isLoading = false;
        }
    }

    getCardLook(item: WidgetItem) {
        let look = "full-width full-height dashed darker tooltip";
        if (item.section !== PropertyEditorSections.PRESETS) {
            look += " sf-p-xs";
        }

        return look;
    }

    private loadData(tab: ModalTab, searchVal: string, skip: number = 0) {
        this.isLoading = true;
        tab = tab || this.settings.tabsConfig.tabs.find(x => x.name === this.tabsComponent.currentTab.name);
        searchVal = searchVal || this.searchComponent.searchValue;

        this.registerSubscription(this.settings.data.load({
            tab,
            searchVal,
            skip
        }).subscribe((loadResult) => {
            // hide loader if no items because layoutComplete is not called in this scenario
            if (loadResult.dataItems.length === 0) {
                this.isLoading = false;
            }

            if (skip) {
                if (this.lastDataContext) {
                    loadResult.dataItems.forEach(group => {
                        const correspondingGroupInLastContext = this.lastDataContext.dataItems.find(x => x.title === group.title);
                        if (correspondingGroupInLastContext) {
                            group.items.forEach(item => {
                                if (!correspondingGroupInLastContext.items.find(x => x.dataItem.name === item.dataItem.name)) {
                                    correspondingGroupInLastContext.items.push(item);
                                }
                            });
                        }
                    });
                }
            } else {
                this.itemsRendered = 0;
                this.pageNumber = 0;
                this.lastDataContext = loadResult;
            }

            this.dataContext$.next(this.lastDataContext);
        }));
    }
}
