import { Component, Inject, Optional, Input, OnDestroy, OnInit, HostListener, OnChanges, SimpleChanges, Output, EventEmitter, ChangeDetectorRef } from "@angular/core";
import { LongRunningTasksService } from "../../services/long-running-tasks.service";
import { BackgroundTaskNotificationBuilder, BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN } from "./background-task-notification-builder";
import { EntityData, DataItem } from "../../interfaces";
import { LONG_TASKS_STATUS, QUERY_PARAMS, RESOLVE_NAMES } from "../../../constants";
import { ActivatedRoute } from "@angular/router";
import { ProviderStore } from "../../services/provider-store";
import { ExtendedBackgroundTask, BackgroundTask, TaskStatus, TaskActionButton, TaskAction } from "../../services/background-task.types";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { SiteData } from "../../../../shared/services/metadata/site-data.store";

// This (64) is the supposed height of each task's HTML element. The height is taken like so, because
// the rendition of the actual task progress elements happens too late which makes taking the ElmementRef
// of the div that holds the title, buttons and task progress bars usless as it has incorrect heigh
export const PROGRESS_TASK_HTML_ELEMENT_HEIGHT = 64;
export const LONG_RUNNING_TASK_CREATED = "longRunningTaskCreated";

@Component({
    selector: "sf-long-running-progress",
    templateUrl: "./long-running-progress.component.html"
})
export class LongRunningProgressComponent extends SfRxBase implements OnInit, OnChanges, OnDestroy {
    @Input() entityData: EntityData;
    @Input() parentItem: DataItem;
    @Input() showLoaders: boolean;
    @Input() concurrentKey: string;

    @Output() totalProgressTaskHtmlElementsHeigth = new EventEmitter();

    public tasks: ExtendedBackgroundTask[] = [];

    constructor(private service: LongRunningTasksService,
                @Optional() @Inject(BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN) private notificationBuilders: Array<BackgroundTaskNotificationBuilder>,
                private route: ActivatedRoute,
                private providerStore: ProviderStore,
                private ref: ChangeDetectorRef) {
        super();
    }

    @HostListener(`window:${LONG_RUNNING_TASK_CREATED}`)
    onTaskCreated() {
        this.refresh(null);
    }

    ngOnInit() {
        this.service.init(this.entityData);
        const progressSubscription = this.service.progress.subscribe(progress => {
            this.regenerateTasks(progress);
        });

        this.registerSubscription(progressSubscription);

        const providerSubscription = this.providerStore.providerChanged.subscribe(provider => {
            const progress = this.service.progress.getValue();
            this.regenerateTasks(progress, provider);
        });

        this.registerSubscription(providerSubscription);
    }

    ngOnChanges(changes: SimpleChanges): void {
        const entityDataChange = changes["entityData"];
        const concurrentKeyChange = changes["concurrentKey"];
        const parentItemChange = changes["parentItem"];
        if ((entityDataChange && !entityDataChange.isFirstChange()) ||
            (concurrentKeyChange && !concurrentKeyChange.isFirstChange()) ||
            (parentItemChange && !parentItemChange.isFirstChange())) {
            this.service.init(this.entityData);
        }
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.service.stopService();
    }

    processStatus(task: BackgroundTask): string | TaskStatus {
        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (task.Status === TaskStatus.Done) {
            return LONG_TASKS_STATUS.DONE;
        }

        if (status === TaskStatus.Started) {
            return LONG_TASKS_STATUS.STARTED;
        }

        // this is actually string
        return task.Status;
    }

    handleButton(button: TaskActionButton, task: BackgroundTask): void {
        switch (button.action) {
            case TaskAction.Stop:
                return this.service.stop(task.Id);
            case TaskAction.Restart:
                return this.service.retry(task.Id);
            case TaskAction.Resume:
                return this.service.resume(task.Id);
            case TaskAction.Delete:
            default:
                return this.service.delete(task.Id);
        }
    }

    refresh(tasks: ExtendedBackgroundTask[]) {
        if (tasks) {
            this.tasks = tasks;
        }
        this.service.refresh();
    }

    private regenerateTasks(progress: ExtendedBackgroundTask[], forcedProvider?: string) {
        const filtered = progress
            .map(task => {
                this.processTask(task);
                return task;
            }).filter(task => {
                const builder = this.resolveBuilder(task);
                const filterCallback = builder.filterTasksCallback.bind(builder);

                const propertyMap = {};
                if (this.parentItem) {
                    propertyMap["provider"] = this.parentItem.provider;
                }

                if (!propertyMap["provider"]) {
                    propertyMap["provider"] = forcedProvider || this.route.snapshot.queryParams[QUERY_PARAMS.PROVIDER] || this.providerStore.currentProvider;
                }

                propertyMap["ConcurrentTaskKey"] = this.concurrentKey;

                const siteData = this.route.snapshot.parent.data[RESOLVE_NAMES.siteDataStore] as SiteData;
                if (siteData) {
                    propertyMap[FILTERCALLBACK_PROPERTY_MAP.CURRENT_SITE_ID] = siteData.Id;
                }

                // used to update the progress bar in the UI
                this.ref.detectChanges();

                return filterCallback(task, propertyMap);
            });

        this.tasks.splice(0, this.tasks.length, ...filtered);
        this.service.initTimer(this.tasks);

        this.totalProgressTaskHtmlElementsHeigth.emit(this.tasks.length * PROGRESS_TASK_HTML_ELEMENT_HEIGHT);
    }

    private processTask(task: ExtendedBackgroundTask) {
        const builder = this.resolveBuilder(task);
        builder.processTask(task);
    }

    private resolveBuilder(task: BackgroundTask): BackgroundTaskNotificationBuilder {
        let builder = this.notificationBuilders.find(notificationBuilder => notificationBuilder.isTaskSupported(task.TaskName));

        if (!builder) {
            builder = this.notificationBuilders.find(notificationBuilder => notificationBuilder.isDefault);
        }

        return builder;
    }
}

export const FILTERCALLBACK_PROPERTY_MAP = {
    CURRENT_SITE_ID: "currentSiteId"
};
