declare const jQuery: any;

/**
 * @ExposedInApi {groupToolbarButtons} groupToolbarButtons v1/editor/editor-group-toolbar-buttons.d.ts
 */
export const groupToolbarButtons = (toolbar: HTMLElement, insertingToolSelector: string, destinationToolSelector: string, isAtTheEnd: boolean = true) => {
    const destinationElement = jQuery(toolbar).find(destinationToolSelector).parent();
    const insertingElement = jQuery(toolbar).find(insertingToolSelector).parent();
    const insertingElementWrapper = insertingElement.closest(".k-button-group");

    if (isAtTheEnd) {
        destinationElement.closest(".k-button-group").find(".k-group-end").removeClass("k-group-end");
        insertingElement.removeClass("k-group-start");
    } else {
        insertingElement.removeClass("k-group-start k-group-end");
    }

    insertingElement.insertAfter(destinationElement);
    insertingElementWrapper.remove();
};
