
import { Observable, BehaviorSubject } from "rxjs";

import { DynamicItemStore } from "../services/dynamic-item.store";
import { DataItem, EntityData, NavigateToEditArguments } from "../interfaces";
import { ModalWindowService } from "./../../../shared/services/modal-window.service";
import { ActivatedRoute, Router, NavigationExtras } from "@angular/router";
import { OPERATION_NAMES, Operation } from "../../../shared/components/action-menu/operation.model";
import { ROUTE_PARAMS } from "../../constants";
import { environmentTypes } from "../../../../environment";
import { ScheduleValidator } from "../../../../../../fields/common/validators/schedule.validator";
import { ValidatorFn } from "@angular/forms";
import { CompositeOperationsProvider } from "../services/operations/operations-provider";
import { EditInDialogOperationResult } from "../services/operations/commands/edit-in-dialog-command";
import { Location } from "@angular/common";
import { ItemPosition } from "../services/dynamic-item.service";
import { EditNavigationService } from "../../../shared/services/edit-navigation.service";
import { environment } from "../../../../../environments/environment";
import { ParentService } from "../services/parent.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export class DynamicItemBase extends SfRxBase {
    isNavigationEmbedded: boolean;
    entityData: EntityData;
    singularName: string;

    isLoading: boolean;
    autoTriggerLoading: boolean = true;
    protected readonly contentRoute: ActivatedRoute;
    operations: BehaviorSubject<Operation[]>;

    get parentId(): string {
        return this.route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
    }

    get notificationFilter(): string {
        return this.entityData.metadata.typeFullName;
    }

    constructor(
        protected dynamicItemStore: DynamicItemStore,
        protected modalWindowService: ModalWindowService,
        protected route: ActivatedRoute,
        protected window: Window,
        protected router: Router,
        protected operationsProvider: CompositeOperationsProvider,
        protected location: Location,
        protected editNavigationService: EditNavigationService,
        protected parentService: ParentService) {
        super();

        this.operations = new BehaviorSubject<Operation[]>([]);
        this.contentRoute = this.route.parent.parent;
        this.isNavigationEmbedded = environment.env === environmentTypes.integration;
    }

    protected handleNonExistentItem(item: DataItem) {
        this.window.confirm("The item you are trying to edit does not exist anymore");
    }

    protected getItemPosition(): ItemPosition {
        return ItemPosition.Default;
    }

    protected navigate(commands: any[], extras: NavigationExtras = {}): Promise<boolean> {
        return this.router.navigate(commands, extras);
    }

    protected navigateToEdit(args: NavigateToEditArguments): Observable<EditInDialogOperationResult> {
        args.parentId = args.parentId || this.parentId;
        args.route = this.route;
        args.singularName = this.singularName;
        return this.editNavigationService.navigateToEdit(args);
    }
}

export const OPERATION_VALIDATOR_MAP: { [operation: string]: ValidatorFn | ValidatorFn[] } = Object.freeze({
    [OPERATION_NAMES.schedule]: ScheduleValidator.validate
});
