import { Component, Input, Output, EventEmitter } from "@angular/core";
import { ItemsState } from "../../../../content/dynamic-modules/services/dynamic-item-store-state";

@Component({
    selector: "sf-search-notification",
    templateUrl: "./search-notification.component.html"
})
export class SearchNotificationComponent {

    @Input() searchValue: string;
    @Input() itemsState: ItemsState;
    @Output() clearSearch = new EventEmitter<void>();

    onClearSearch(): void {
        this.clearSearch.emit();
    }
}
