import { Injectable } from "@angular/core";
import { Settings } from "../modules/shared/services/settings.service";
import { EnvironmentService } from "../modules/shared/services/environment.service";

import { Data, Query, Sitefinity, Transaction } from "@progress/sitefinity-webservices-sdk/dist/sitefinity-webservices-sdk";
import { environmentTypes } from "../environment";
import { stringConstants } from "../../../cypress/e2e/helpers/constants";

// TODO: Remove this class at all
@Injectable()
export class SitefinitySdk {
    private sitefinity: Sitefinity;
    private queryInstance: Query;

    constructor(private settings: Settings, private envService: EnvironmentService) {
        this.createInstance();
    }

    get instance() {
        return this.sitefinity;
    }

    get query() {
        return this.queryInstance;
    }

    set token(value: any) {
        this.instance.setToken(value);
    }

    link(entitySet: string, id: string, provider?: string): string {
        let link = `${this.settings.webServiceUrl}${entitySet}(${id})`;

        // the domain does not patter to the server, just the path, but the protocol
        // requires an absolute url ..
        if (link.startsWith(stringConstants.FORWARD_SLASH))
            link = "http://localhost" + link;

        return provider ? `${link}?sf_provider=${provider}` : link;
    }

    recreateInstance() {
        this.createInstance();
    }

    static associateRelationFields(entitySet: string, id: any, relationFields: any, transaction: Transaction) {
        Object.keys(relationFields).forEach(key => {
            transaction.destroyRelated({
                entitySet: entitySet,
                key: id,
                property: key
            });

            const relationArray: Array<any> = relationFields[key];

            if (relationArray) {
                relationArray.forEach(relation => {
                    transaction.createRelated({
                        entitySet: entitySet,
                        key: id,
                        property: key,
                        link: relation
                    });
                });
            }
        });
    }

    static associateRelationFieldsSfData(id: any, relationFields: any, data: Data) {
        Object.keys(relationFields).forEach(key => {
            data.destroyRelated({
                key: id,
                property: key
            });

            const relationArray: Array<any> = relationFields[key];

            if (relationArray) {
                relationArray.forEach(relation => {
                    data.createRelated({
                        key: id,
                        property: key,
                        link: relation
                    });
                });
            }
        });
    }

    private createInstance() {
        const env = this.envService.getEnvironment();
        const integrationMode = env === environmentTypes.integration;

        this.sitefinity = new Sitefinity({
            baseUrl: this.settings.webServiceUrl,
            siteId: this.settings.siteId,
            enableUnlimitedChoices: true,
            integrationMode: integrationMode
        });

        this.queryInstance = new Sitefinity.Query();
    }
}
