import { AbstractControl, ValidatorFn } from "@angular/forms";
import { LOCALE } from "../common-constants";

export const DATE_RANGE_VALIDATOR_NAME = "dateRange";

export class DateRangeValidator {
    static validate(config: ValueRange): ValidatorFn {
        return (control: AbstractControl) => {
            if (control.value) {
                const dateToTest = control.value as Date;
                if (config.min && config.min > dateToTest) {
                    return config.customErrorObject || {
                        minValue: {
                            requiredMinValue: config.min.toLocaleString(LOCALE)
                        }
                    };
                }

                if (config.max && config.max <= dateToTest) {
                    return config.customErrorObject || {
                        maxValue: {
                            requiredMaxValue: config.max.toLocaleString(LOCALE)
                        }
                    };
                }
            }

            return null;
        };
    }
}

export interface ValueRange {
    min?: Date | number;
    max?: Date | number;
    customErrorObject?: { [x: string]: string }
}
