import { FieldBase, createValueAccessor } from "../../../../../../../fields";
import { ChangeDetectorRef, Component, OnDestroy, OnInit, QueryList, ViewChild, ViewChildren } from "@angular/core";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { ContentSelectorComponent, MixedContentValue } from "../content/content-selector.component";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { LocatabaleEntitySetNamesResponse, LocatableDynamicItemService } from "../../../../content/dynamic-modules/services/locatable-dynamic-item.service";
import { LoadingContentState } from "../../../../shared/rxjs-extensions/toLoadingState";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { ActivatedRoute } from "@angular/router";
import { SiteData } from "../../../../shared/services/metadata/site-data.store";
import { EntityData } from "../../../../../api";
import { ContentSettings } from "../content/content.settings";
import { ReplaySubject, Subscription } from "rxjs";
import { CustomFilterProperties, Filter, FiltersResult } from "../../../../content/dynamic-modules/components/sidebar/filter/filter-interfaces";
import { FilterStore } from "../../../../content/dynamic-modules/components/sidebar/filter/filter.store";
import { StatusType } from "../../../../../../../fields/field-status";
import { ProviderStore } from "../../../../content/dynamic-modules/services/provider-store";
import { DateTimeFilterValue, DateTimeSelectorComponent } from "../date-time/date-time-selector.component";
import { DateTimeFilterParser } from "../date-time/datetime-filter-parser.service";
import { AppStore } from "../../../../../services/store/app-store";
import { FIELDS_ACTIONS } from "../../../../../services/store/actions/actions.fields";
import { SelectorEventArgs } from "@progress/sitefinity-component-framework";
import { CombinedFilter, FilterClause } from "./combined-filter";
import { ChoiceComponent } from "../../../../../../../fields/choice/choice.component";
import { cloneObject } from "../../../../../utils";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-filtercontent-selector",
    templateUrl: "./filter-content-selector.component.html",
    providers: [createValueAccessor(FilterContentSelectorComponent)]
})
export class FilterContentSelectorComponent extends FieldBase<FilterContentSelectorSettings, MixedContentValue> implements OnInit, OnDestroy {
    @ViewChild("selectedItemsComponent", { static: false }) set selectedItemsComponent(selectedItemsComponent: ContentSelectorComponent) {

        if (selectedItemsComponent) {
            selectedItemsComponent.registerOnChange((val) => {
                const currentVal = this.getValue();
                if (val && val.Content) {
                    val.Content[0].Type = currentVal.Content[0].Type;
                    this.writeValue(val);
                } else { // if slected items are cleared
                    currentVal.ItemIdsOrdered = [];
                    currentVal.Content[0].Variations[0].Filter = {Key: COMPLEX_KEY, Value: ""};
                    this.writeValue(currentVal);
                }
            });
        }
    }
    @ViewChild("dateTimeComponent", { static: false }) set dateTimeComponent(dateTimeComponent: DateTimeSelectorComponent) {

        if (dateTimeComponent) {
            dateTimeComponent.registerOnChange((val) => {
                this.onDateTimeFilterChanged(val, dateTimeComponent);
            });
        }
    }

    @ViewChild("contentFilterRadio", { static: false }) contentFilterRadio: ChoiceComponent;

    @ViewChildren(ContentSelectorComponent) contentSelectors!: QueryList<ContentSelectorComponent>;
    dateFieldName = "PublicationDate";
    contentSettings: ChoiceSettings;
    dateTimeSettings: SettingsBase;
    entityData: EntityData;
    showProvidersDropdown: boolean;
    radioSettings: ChoiceSettings;
    contentItemsSettings: ContentSettings;
    showContentSelector: boolean;

    excludedContentTypes: string[] = ["contentitems", "pages", "images", "documents", "videos"];
    excludedFilterTypes: string[] = ["date-range", "User", "predefined", "last-modified", "extensions", "Last_Modified_By_Filter_Key"];
    filterProperties$ = new ReplaySubject<CustomFilterProperties[]>(1);

    private filtersSubscription: Subscription;
    public selectedContentType: string;
    currentFilters = {};
    private currentComplexFilterValue = {Key: COMPLEX_KEY, Value: ""};
    private currentSelectedItemsIds = [];
    private currentSelectedItemsFilterValue;

    constructor(
        private store: MetadataStore,
        private locatableItemsService: LocatableDynamicItemService,
        private route: ActivatedRoute,
        private providerStore: ProviderStore,
        private filterStore: FilterStore,
        private appStore: AppStore,
        private ref: ChangeDetectorRef) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        const siteData: SiteData = this.route.parent.snapshot.data.siteDataStore;
        this.emitStatus({ type: StatusType.Pending });
        const locatableItemsSubscription = this.locatableItemsService.getLocatableEntitySetNames(siteData.Id).subscribe(
            (sets: LoadingContentState<LocatabaleEntitySetNamesResponse>) => {
                if (!sets.isLoading) {
                    const entities = this.store.getValue().entities;
                    const locatableSets = sets.content.value
                        .filter(setName => {
                            return this.excludedContentTypes.findIndex(t => t === setName) === -1;
                        })
                        .filter(setName => entities[setName])
                        .map(setName => <ChoiceItem>{ Name: entities[setName].displayName, Value: entities[setName].typeFullName });

                    if (!this.value || !this.value.Content || this.value.Content.length === 0) {
                        this.clearFilters(null);
                    }

                    const notSelectedOption = {Name: "Select content type", Value: null};
                    const contentTypeChoices = [notSelectedOption].concat(locatableSets);
                    this.initializeContentSettings(contentTypeChoices);
                    if (this.selectedContentType) {
                        this.initializeEntityData();
                        this.initializeRadioSettings();
                        this.loadFilters();
                    }
                }
            });

        this.registerSubscription(locatableItemsSubscription);
    }

    ngOnDestroy() {
        this.appStore.dispatch(FIELDS_ACTIONS.changeItemType({itemType: null, value: null}));
    }

    onContentSelectionChange(entry: string) {
        this.clearSelectedFilters();
        this.clearFilters(entry);
        if (entry) {
            this.initializeEntityData();
            this.initializeRadioSettings();
            this.loadFilters();
        } else {
            this.appStore.dispatch(FIELDS_ACTIONS.changeItemType({itemType: null, value: null}));
        }
    }

    onProviderSelectionChange(entry: SelectorEventArgs) {
        this.clearSelectedFilters();

        if (this.getValue().Content[0].Variations[0].Source !== entry.tabValue) {
            this.contentItemsSettings = null;
            this.ref.detectChanges();
            this.entityData.metadata.selectedProvider = entry.tabValue;
            const currentVal = this.getValue();
            currentVal.Content[0].Variations[0].Source = entry.tabValue;
            const hasSelectedItems = this.getValue().ItemIdsOrdered && this.getValue().ItemIdsOrdered.length > 0;
            if (hasSelectedItems) {
                currentVal.ItemIdsOrdered = [];
            }

            currentVal.Content[0].Variations[0].Filter = { Key: COMPLEX_KEY, Value: "" };
            this.writeValue(currentVal);
            this.initializeSelectedContentItems(entry.tabValue);
            this.initializeFilterByParentField(entry.tabValue);
        }
    }

    onRadioSelectionChange(entry: string) {
        this.showContentSelector = entry === "Selected";
        const currentVal = this.getValue();

        currentVal.Content[0].Variations[0].DynamicFilterByParent = false;

        if (entry === "Selected") {
            this.currentComplexFilterValue = currentVal.Content[0].Variations[0].Filter;
            currentVal.ItemIdsOrdered = this.currentSelectedItemsIds;
            currentVal.Content[0].Variations[0].Filter = this.currentSelectedItemsFilterValue;
            const hasSelectedItems = this.getValue().ItemIdsOrdered && this.getValue().ItemIdsOrdered.length > 0;
            this.contentItemsSettings.defaultValue = hasSelectedItems ? this.getValue() : null;
        }

        if (entry === "All" || entry === "CurrentParent") {
            this.currentSelectedItemsIds = currentVal.ItemIdsOrdered;
            currentVal.ItemIdsOrdered = [];
            this.currentSelectedItemsFilterValue = currentVal.Content[0].Variations[0].Filter;
            currentVal.Content[0].Variations[0].Filter = this.currentComplexFilterValue;

            if (entry === "CurrentParent") {
                currentVal.Content[0].Variations[0].DynamicFilterByParent = true;
            }

            this.ref.detectChanges();
            this.initializeFilterByParentField(this.contentItemsSettings.contentProvider);
        }

        this.writeValue(currentVal);
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }

    private loadFilters() {
        if (this.filtersSubscription) {
            this.filtersSubscription.unsubscribe();
        }
        this.emitStatus({ type: StatusType.Pending });

        this.dateTimeSettings = this.createDateTimeComponentSettings();

        this.filtersSubscription = this.filterStore.getCustomFilters(this.entityData)
            .subscribe((filterResult: FiltersResult) => {
                let filterProperties = [];
                if (!filterResult.isLoading) {
                    const resultFilters: Filter[] = [];
                    if (filterResult.filters) {
                        const filtersWithoutExcluded = filterResult.filters.filter(f => {
                            return this.excludedFilterTypes.findIndex(t => t === f.name) === -1;
                        });

                        resultFilters.push(...filtersWithoutExcluded);
                    }

                    this.addFilterByParent(resultFilters);

                    filterProperties = resultFilters.map(f => {
                        const settings = this.createFilterComponentSettings(f);

                        return {
                            title: f.title.toLowerCase(),
                            settings: settings
                        };
                    });
                }

                this.filterProperties$.next(filterProperties);
                this.emitStatus({ type: StatusType.Done });
            });

        this.registerSubscription(this.filtersSubscription);
    }

    private addFilterByParent(filters: Filter[]): void {
        let hasParentFilter = false;
        const parentFilterIndex = filters.findIndex(x => x.name === "Parent");
        if (parentFilterIndex >= 0) {
            hasParentFilter = true;
            const parentFilter = filters.splice(parentFilterIndex, 1)[0];
            filters.unshift(parentFilter);
        }

        if (this.entityData.metadata.hasParent && !hasParentFilter) {
            const parentEntity = this.store.getEntity(this.entityData.metadata.parent);
            const parentFilter: Filter = {
                name: "Parent",
                title: `By ${parentEntity.setName}`,
                parameters: {
                    type: "call",
                    contentPluralName: parentEntity.setName,
                    contentSingularName: parentEntity.singularName
                }
            };
            filters.unshift(parentFilter);
        }
    }

    private clearFilters(newContentType: string) {
        this.value = {
            ItemIdsOrdered: [],
            Content: [{
                    Type: newContentType,
                    Variations: [{Source: null, Filter: {Key: COMPLEX_KEY, Value: ""}}]
                }
            ]
        };

        this.selectedContentType = newContentType;
        this.showContentSelector = false;
    }

    private createFilterComponentSettings(filter: Filter): ContentSettings {
        const settings = new ContentSettings(filter.name, false);
        const filterContentPluralName = filter.parameters.contentPluralName;
        if (filter.name === "Parent") {
            settings.contentType = this.store.getEntity(filterContentPluralName.toLocaleLowerCase()).typeFullName;
            settings.key = "ParentId";
            settings.contentDisableInteraction = true;
            settings.contentProvider = this.contentItemsSettings.contentProvider;
        } else {
            settings.contentType = "Taxonomy_" + filter.parameters.contentPluralName;
        }
        settings.contentAllowMultipleItemsSelection = true;
        settings.contentLiveData = this.settings.contentLiveData;
        settings.culture = this.settings.culture;
        const variations = this.value.Content[0].Variations;
        if (variations && variations.length > 0) {
            const variationFilter = variations[0].Filter;
            if (variationFilter && variationFilter.Key === COMPLEX_KEY) {
                const complexFilterValue = variationFilter.Value;
                const combinedFilter: CombinedFilter = complexFilterValue ? JSON.parse(complexFilterValue) : new CombinedFilter();
                const singleFilterArray = combinedFilter.ChildFilters ?? [];
                const filterValues: any = singleFilterArray.find(f => (<FilterClause>f).FieldName === settings.key);
                const ids = filterValues ? filterValues.FieldValue : null;

                if (ids && ids.length > 0) {
                    settings.defaultValue = {
                        ItemIdsOrdered: ids,
                        Content: [{
                                Variations: [{
                                    Filter: {
                                        Key: "Ids",
                                        Value: ids.join(",")
                                    },
                                    Source: settings.contentProvider
                                }]
                            }
                        ]
                    };
                }
            }
        }

        return settings;
    }

    private clearSelectedFilters() {
        this.currentSelectedItemsIds = [];
        this.currentSelectedItemsFilterValue = null;
        this.currentComplexFilterValue = {Key: COMPLEX_KEY, Value: ""};
    }

    private createDateTimeComponentSettings(): SettingsBase {
        const settings = new SettingsBase("datePublished", false);
        settings.title = "Date published";
        const variations = this.value.Content[0].Variations;
        if (variations && variations.length > 0) {
            const variationFilter = variations[0].Filter;
            if (variationFilter && variationFilter.Key === COMPLEX_KEY) {
                const complexFilterValue = variationFilter.Value;
                settings.defaultValue = DateTimeFilterParser.parseToDateTimeInterval(complexFilterValue, this.dateFieldName);
            }
        }

        return settings;
    }

    onFilterChanged(newVal: MixedContentValue, settings: ContentSettings) {
        const currentVal = this.getValue();
        const fieldTypeName = settings.key;
        const currentValVariations = currentVal.Content[0].Variations[0];
        const currentValFilter = currentValVariations.Filter;

        if (currentValFilter && currentValFilter.Key === COMPLEX_KEY) {
            const emptyFilter: CombinedFilter = {Operator: "And", ChildFilters: []};
            const complexFilter: CombinedFilter = currentValFilter.Value ? JSON.parse(currentValFilter.Value) : emptyFilter;
            const singleFilterArray = complexFilter.ChildFilters ?? [];
            const filterValuesIndex = singleFilterArray.findIndex(f => (<FilterClause>f).FieldName === fieldTypeName);

            const newValIdsArray = newVal ? newVal.ItemIdsOrdered : [];
            if (filterValuesIndex > -1) {
                if (newValIdsArray.length === 0) {
                    singleFilterArray.splice(filterValuesIndex, 1);
                } else {
                    (<FilterClause>singleFilterArray[filterValuesIndex]).FieldValue = newValIdsArray;
                }
            } else if (newValIdsArray && newValIdsArray.length > 0) {
                const childFilter = new FilterClause();
                childFilter.FieldName = fieldTypeName;
                childFilter.Operator = "any+or";
                childFilter.FieldValue = newValIdsArray;
                singleFilterArray.push(childFilter);
            }
            currentVal.Content[0].Variations[0].Filter.Value = JSON.stringify(complexFilter);
        }
        this.writeValue(currentVal);
    }

    private onDateTimeFilterChanged(newVal: DateTimeFilterValue, dts: DateTimeSelectorComponent) {
        const currentVal = this.getValue();
        const currentValVariations = currentVal.Content[0].Variations[0];
        const currentValFilter = currentValVariations.Filter;

        if (currentValFilter && currentValFilter.Key === COMPLEX_KEY) {
            const emptyFilter: CombinedFilter = {Operator: "And", ChildFilters: []};
            const complexFilter: CombinedFilter = currentValFilter.Value ? JSON.parse(currentValFilter.Value) : emptyFilter;
            const singleFilterArray = complexFilter.ChildFilters ?? [];
            const filteredArray = singleFilterArray.filter(f => !DateTimeFilterParser.isDateFilter(f, this.dateFieldName));
            complexFilter.ChildFilters = filteredArray;

            if (newVal && newVal.PeriodType !== "anyTime") {
                const dateCombinedFilter = DateTimeFilterParser.parseDateTimeIntervalToFilter(newVal, this.dateFieldName);
                if (dateCombinedFilter)
                    complexFilter.ChildFilters.push(dateCombinedFilter);
            }
            currentVal.Content[0].Variations[0].Filter.Value = JSON.stringify(complexFilter);
        }
        this.writeValue(currentVal);
    }

    private initializeContentSettings(choices: ChoiceItem[]) {
        this.selectedContentType = this.getValue().Content[0].Type;
        const defaultValue = this.selectedContentType;
        this.contentSettings = ChoiceDropdownComponent.createFieldSettings(choices, defaultValue);
    }

    private initializeEntityData() {
        const variations = this.getValue().Content[0].Variations;
        const provider = variations && variations.length > 0 ? variations[0].Source : null;
        const entity = this.store.getEntityByFullTypeName(this.selectedContentType);
        this.entityData = {
            culture: this.settings.culture,
            provider: provider,
            metadata: entity
        };
        this.appStore.dispatch(FIELDS_ACTIONS.changeItemType({itemType: this.entityData.metadata.setName, value: cloneObject(this.getValue())}));
        const providerSubscription = this.providerStore.getProviders(this.entityData.metadata.setName).subscribe((providers: any[]) => {
            this.showProvidersDropdown = providers.length > 1;
        });
        this.registerSubscription(providerSubscription);

        this.initializeSelectedContentItems(provider);
    }

    private initializeSelectedContentItems(provider: string) {
        this.contentItemsSettings = null;
        this.contentItemsSettings = new ContentSettings(this.selectedContentType, false);
        this.contentItemsSettings.contentType = this.selectedContentType;
        this.contentItemsSettings.contentAllowMultipleItemsSelection = true;
        this.contentItemsSettings.culture = this.settings.culture;
        this.contentItemsSettings.contentLiveData = this.settings.contentLiveData;
        this.contentItemsSettings.contentProvider = provider;
        this.contentItemsSettings.useDefaultValue = true;
        const hasSelectedItems = this.getValue().ItemIdsOrdered && this.getValue().ItemIdsOrdered.length > 0;
        this.contentItemsSettings.defaultValue = hasSelectedItems ? this.getValue() : null;
    }

    private initializeRadioSettings() {
        this.radioSettings = new ChoiceSettings("radioSelector", false);
        this.radioSettings.choices = [];
        this.radioSettings.choices.push({Name: "All published items", Value: "All"});
        if (this.entityData.metadata.hasParent) {
            this.radioSettings.choices.push({Name: "From currently opened parent", Value: "CurrentParent"});
        }

        this.radioSettings.choices.push({Name: "Selected items", Value: "Selected"});
        const dynamicFilterByParent = this.getValue().Content[0].Variations[0].DynamicFilterByParent;
        if (dynamicFilterByParent) {
            this.radioSettings.defaultValue = "CurrentParent";
        } else {
            const hasSelectedItems = this.getValue().ItemIdsOrdered && this.getValue().ItemIdsOrdered.length > 0;
            this.radioSettings.defaultValue = hasSelectedItems ? "Selected" : "All";
            this.showContentSelector = hasSelectedItems;
        }
    }

    private initializeFilterByParentField(provider: string): void {
        const contentSelectorsArray = this.contentSelectors.toArray();
        const parentFilter = contentSelectorsArray.find(x => x.settings.key === "ParentId");
        if (parentFilter) {
            parentFilter.settings.contentProvider = provider;
            if (parentFilter.value) {
                parentFilter.value.Content[0].Variations[0].Filter = { Key: COMPLEX_KEY, Value: "" };
            }

            parentFilter.ngOnInit();
        }
    }
}

export class FilterContentSelectorSettings extends SettingsBase {
    public contentLiveData: boolean;
}

const COMPLEX_KEY = "Complex";

export const CONTENT_FILTER_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: FilterContentSelectorComponent,
    readComponent: FilterContentSelectorComponent,
    settingsType: FilterContentSelectorSettings
};
