import { Component, OnInit } from "@angular/core";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { ActivatedRoute } from "@angular/router";
import { FieldBase } from "../../../../../../fields/field-base";
import { Entity } from "../../services/metadata/meta-data.store";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { SORT_ORDER } from "../../../content/constants";
import { AsyncFieldValue } from "../../../../../../fields/async-field-value";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-parent-dropdown-selector",
    templateUrl: "./dropdown-selector.component.html"
})
export class DropdownSelectorComponent extends FieldBase implements OnInit {
    selectedParentTitle: string;
    choicesSettings: ChoiceSettings = ChoiceDropdownComponent.createFieldSettings([], null, PARENTS_DROPDOWN_NAME);

    constructor(private readonly dynamicItemService: DynamicItemService,
                private readonly route: ActivatedRoute) {
                    super();
    }

    ngOnInit(): void {
        if (!this.route.snapshot.data.itemData) {
            return;
        }

        const childMetadata: Entity = this.route.snapshot.data.itemData.entityData.metadata;
        const parentMetadata: Entity = this.route.parent.snapshot.data.metaStore.entities[childMetadata.parent];

        this.dynamicItemService
            .getItemList({
                entityData: {
                    metadata: parentMetadata,
                    culture: this.settings.entityData.culture,
                    provider: this.settings.entityData.provider
                },
                fallbackProperties: [parentMetadata.defaultFieldName],
                order: `${parentMetadata.defaultFieldName} ${SORT_ORDER.ASCENDING}`
            })
            .subscribe(data => {
                const childItem = this.settings.dataItem;
                const parents = data.dataItems;
                let selectedValue = null;

                let parentKey = childItem.parentKey;
                if (!parentKey) {
                    if (!this.settings.defaultValue) {
                        parentKey = parents.length > 0 ? parents[0].key : null;
                    } else {
                        parentKey = this.settings.defaultValue;
                    }
                }

                const parentItem = parents.find(x => x.key === parentKey);
                if (parentItem) {
                    this.selectedParentTitle = parentItem.title;
                    selectedValue = parentItem.key;
                }

                const options: ChoiceItem[] = parents.map(x => {
                    const option: ChoiceItem = {
                        Name: x.data[parentMetadata.defaultFieldName],
                        Value: x.key
                    };

                    return option;
                });

                this.choicesSettings = ChoiceDropdownComponent.createFieldSettings(options, selectedValue, PARENTS_DROPDOWN_NAME);
                this.writeValue(new AsyncFieldValue(selectedValue));
            });
    }
}

const PARENTS_DROPDOWN_NAME = "PARENTS_DROPDOWN";
