import { ResolveData, Route } from "@angular/router";
import { ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { DynamicItemRouterComponent } from "../content/dynamic-modules/components/router/dynamic-item-router.component";
import { DynamicItemResolver } from "../content/dynamic-modules/services/entity/dynamic-item.resolver";
import { MetadataStoreResolver } from "../shared/services/metadata/meta-data-store.resolver";
import { UserDataStoreResolver } from "../shared/services/metadata/user-data-store.resolver";
import { SiteDataStoreResolver } from "../shared/services/metadata/site-data-store.resolver";
import { SiteTitleResolver } from "../shared/services/site-title.resolver";
import { ZoneEditorComponent } from "../pages/components/zone-editor/zone-editor.component";
import { ZoneEditorCanDeactivate } from "../pages/components/zone-editor/guards/can-deactivate.guard";
import { ModalWindowComponent } from "../shared/components/modal-window/modal-window.component";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { DynamicItemIndexComponent } from "../content/dynamic-modules/components/dynamic-item-index.component";
import { BackendTweaksGridResolver } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks-grid.resolver";
import { DynamicItemsResolver } from "../content/dynamic-modules/components/dynamic-items.resolver";
import { SiteTitleDynamicResolver } from "../shared/services/site-title.dynamic.resolver";
import { ProviderRouteGuard } from "../../provider.route-guard";
import { FormsConstants } from "./forms.constants";
import { FormRulesListComponent } from "./form-rules/form-rules-list.component";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { EditFormComponent } from "./components/edit-form/edit-form.component";
import { FormResolver } from "./form.resolver";
import { FormsEditIntegratedComponent } from "./forms-edit-integrated.component";
import { ROUTE_PARAMS } from "../content/constants";
import { FormResponsesResolver } from "./form-responses.resolver";
import { FormResponsesGuard } from "./form-responses.route-guard";
import { ContentTypeGuard } from "../content/content-type.guard";

const RESOLVERS: ResolveData = {
    metaStore: MetadataStoreResolver,
    userDataStore: UserDataStoreResolver,
    siteDataStore: SiteDataStoreResolver,
    siteTitle: SiteTitleResolver
};

const BASE_ROUTE: Route[] = [{
    path: stringConstants.EMPTY_STRING,
    component: DynamicItemIndexComponent,
    resolve: {
        gridResolved: BackendTweaksGridResolver,
        dynamicItems: DynamicItemsResolver,
        siteTitle: SiteTitleDynamicResolver
    },
    canActivate: [ProviderRouteGuard, DynamicItemResolver],
    runGuardsAndResolvers: "paramsOrQueryParamsChange"
}];

const ROUTES_DATA = {
    animation: {
        value: ROUTE_PATHS_NO_PREFIX.PAGES
    },
    dynamicTypeName: ROUTE_PATHS_NO_PREFIX.FORMS
};

// routes under adminapp/content/forms - forms grid, etc.
export const FORMS_ROUTES: Route[] = [{
    path: ROUTE_PATHS_NO_PREFIX.FORMS,
    component: DynamicItemRouterComponent,
    children: [
        ...BASE_ROUTE,
        {
            path: FormsConstants.ROUTES.INTEGRATED,
            children: [
                {
                    path: "**",
                    component: FormsEditIntegratedComponent
                }
            ]
        },
        {
            path: `${FormsConstants.ROUTES.EDIT}/:id`,
            component: EditFormComponent,
            canActivate: [
                FormResolver
            ],
            resolve: {
                itemData: FormResolver
            },
            data: {
                dynamicTypeName: ROUTE_PATHS_NO_PREFIX.FORMS
            }
        },
        {
            path: `${FormsConstants.ROUTES.EDIT}/:id/:culture`,
            component: EditFormComponent,
            canActivate: [
                FormResolver
            ],
            resolve: {
                itemData: FormResolver
            },
            data: {
                dynamicTypeName: ROUTE_PATHS_NO_PREFIX.FORMS
            }
        },
        {
            path: `:${ROUTE_PARAMS.PARENT_ID_SEGMENT}/:${ROUTE_PARAMS.CHILD_SET_SEGMENT}`,
            component: DynamicItemRouterComponent,
            children: [{
                path: stringConstants.EMPTY_STRING,
                component: DynamicItemIndexComponent,
                resolve: {
                    dynamicItems: DynamicItemsResolver,
                    siteTitle: SiteTitleDynamicResolver,
                    // Used to check if the form entry can be accessed
                    // we placed this check here, because we need the form entity to be resolved,
                    // so this logic must be executed after the resolver
                    formResponsesGuard: FormResponsesGuard
                },
                canActivate: [ProviderRouteGuard, DynamicItemsResolver],
                runGuardsAndResolvers: "paramsOrQueryParamsChange"
            },
            {
                path: "confirm/:name",
                component: ModalWindowComponent,
                outlet: "dialog"
            }],
            data: { animation: { value: ROUTE_PATHS_NO_PREFIX.ITEMS_GRID } },
            resolve: {
                metaStore: FormResponsesResolver,
            }
        },
        {
            path: FormsConstants.ROUTES.RULES,
            component: FormRulesListComponent,
            children: [
                {
                    path: "confirm/:name",
                    component: ModalWindowComponent,
                    outlet: "dialog"
                }
            ],
            resolve: {
                metaStore: MetadataStoreResolver
            },
            data: {
                dynamicTypeName: ENTITY_SET.FORM_DRAFTS
            }
        },
        {
            path: "confirm/:name",
            component: ModalWindowComponent,
            outlet: "dialog"
        }
    ],
    resolve: RESOLVERS,
    data: ROUTES_DATA,
    canActivate: [ContentTypeGuard]
}];

// routes under adminapp/sfedit for .net core forms
export const FORMS_EDIT_ROUTES: Route[] = [{
    path: ROUTE_PATHS_NO_PREFIX.FORMS,
    component: DynamicItemRouterComponent,
    children: [
        {
            path: "sfedit/:id",
            component: ZoneEditorComponent,
            canActivate: [DynamicItemResolver],
            canDeactivate: [ZoneEditorCanDeactivate],
            resolve: {
                itemData: DynamicItemResolver
            },
            runGuardsAndResolvers: "paramsOrQueryParamsChange"
        },
        {
            path: "confirm/:name",
            component: ModalWindowComponent,
            outlet: "dialog"
        }
    ],
    resolve: RESOLVERS,
    data: ROUTES_DATA
}];
