import { of as observableOf, never as observableNever, Observable } from "rxjs";

import { catchError, map, mergeMap } from "rxjs/operators";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Router } from "@angular/router";
import { Injectable, Inject } from "@angular/core";

import { DataItem, EntityData } from "../../interfaces";
import { ROUTE_PATHS } from "../../../../../constants/route-paths";
import { WINDOW_TOKEN } from "../../../../../window.provider";

import { ROUTE_PARAMS, RESOLVE_NAMES, QUERY_PARAMS, FILTER_PARAMS } from "../../../constants";
import { BaseResolver } from "../../components/dynamic-items-base.resolver";
import { ProviderStore } from "../provider-store";
import { Settings } from "../../../../shared/services/settings.service";
import { MetadataContainer } from "../../../../shared/services/metadata/meta-data.store";
import { NotFoundError } from "../../../../shared/services/errors/not-found-error";
import { DynamicItemService } from "../dynamic-item.service";
import { FilterStore } from "../../components/sidebar/filter/filter.store";
import { CompositeItemHooksProvider } from "./item-hooks-provider";
import { CompositeEntityDataResolver } from "../backend-tweaks/entity-data.resolver";

@Injectable()
export class DynamicItemResolver extends BaseResolver {

    constructor(
        private service: DynamicItemService,
        store: ProviderStore,
        router: Router,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        settings: Settings,
        private filterStore: FilterStore,
        private itemHooksProvider: CompositeItemHooksProvider,
        entityDataResolver: CompositeEntityDataResolver) {
        super(store, router, settings, entityDataResolver);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<ItemData> {
        const entityData = super.resolve(route, state) as EntityData;
        if (!entityData) {
            return observableNever();
        }

        const currentFilter = route.parent.queryParams[FILTER_PARAMS.FILTER];
        const parentId = route.parent.params[ROUTE_PARAMS.PARENT_ID_SEGMENT];
        return this.filterStore.filterValid(entityData, currentFilter, parentId).pipe(mergeMap(valid => {
            if (!valid) {
                this.clearFilter(route, state);
                return observableOf<ItemData>(null);
            } else {
                let getItem: Observable<DataItem> = null;
                const itemId = route.params[ROUTE_PARAMS.ITEM_ID];
                const itemVersion = route.parent.queryParams[QUERY_PARAMS.VERSION];
                const fallbackProperties = DynamicItemResolver.getFallbackProperties(entityData, route);

                if (itemId) {

                    let versionAction: string = null;
                    if (itemVersion) {
                        versionAction = `version(id='${itemVersion}')`;
                    }

                    const segmentId = route.parent.queryParams[QUERY_PARAMS.SEGMENT];
                    let segmentQueryParam = null;
                    if (segmentId) {
                        segmentQueryParam = {[QUERY_PARAMS.SEGMENT]: segmentId};
                    }

                    getItem = this.service.getItem({
                        itemKey: itemId,
                        entityData: entityData,
                        action: versionAction,
                        fallbackProperties,
                        additionalQueryParams: segmentQueryParam
                    });
                } else {
                    getItem = observableOf(DataItem.emptyItem(entityData));
                }

                const result$ = getItem.pipe(map(
                    item => {
                        const itemData: ItemData = {
                            item: item,
                            entityData: entityData,
                            fallbackProperties: fallbackProperties
                        };

                        this.itemHooksProvider.onItemLoaded(item);

                        return itemData;
                    }),
                    catchError((error) => {
                        if (error instanceof NotFoundError) {
                            this.windowProvider.alert("The item you are trying to access does not exist");
                            this.router.navigate([ROUTE_PATHS.CONTENT, entityData.metadata.setName]);
                        }

                        // HACK: result is never used as we redirect but still need to satisfy
                        return observableOf<ItemData>(null);
                    }));

                return result$;
            }
        }));
    }

    static getFallbackProperties(entityData: EntityData, route: ActivatedRouteSnapshot) {
        const relations = entityData.metadata.relations;
        const container = route.parent != null && route.parent.data != null ? route.parent.data[RESOLVE_NAMES.metadata] as MetadataContainer : null;
        let fallbackProperties = [];

        if (container) {
            fallbackProperties = relations.map((relation) => {
                const defaultFieldName = container.entities[relation.setName].defaultFieldName;
                return `${relation.propName}.${defaultFieldName}`;
            });
        }

        return fallbackProperties;
    }
}

export interface ItemData {
    item: DataItem;
    entityData: EntityData;
    fallbackProperties: Array<string>;
}
