import { Component, Input, HostListener, OnInit, ViewChild, ElementRef, Inject } from "@angular/core";
import { ContentSectionMenuService, FieldViewPortChanges } from "../services/content-section-menu.service";
import { FieldSectionModel } from "../../src/app/services/fieldSection.model";
import { ScrollService } from "../../src/app/services/scroll.service";
import { ExternalAppConfigService } from "../../src/app/app-config/external-app-config.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { WINDOW_TOKEN } from "../../src/app/window.provider";

const TOP_MARGIN = 160;

@Component({
    selector: "sf-content-section-menu",
    templateUrl: "./content-section-menu.component.html"
})
export class ContentSectionMenuComponent extends SfRxBase implements OnInit {
    @Input() look;
    @Input()
    get sections(): FieldSectionModel[] {
        return this._sections;
    }
    set sections(value) {
        if (value !== this._sections) {
            this._sections = value;
            this.items = this.processFieldSectionModels(value);
            this.calculateContentSectionMenuVisibility(value);
        }
    }

    @Input() useConfigSettings: boolean = true;
    @ViewChild("wrapper", { static: false }) menuWrapper: ElementRef;

    isVisible: boolean = false;
    items: ContentSectionMenuItemModel[] = [];
    sectionMenuClasses: string;
    protected activeItemIndex: number;

    private visibleFieldSectionsIndexes: number[] = [];
    private _sections: FieldSectionModel[];
    private isScrollingFromItemClick: boolean = false;

    constructor(
        private scrollService: ScrollService,
        private contentSectionMenuService: ContentSectionMenuService,
        private configService: ExternalAppConfigService,
        @Inject(WINDOW_TOKEN) private window: Window) {
            super();
            const subscription = contentSectionMenuService.fieldViewPortChanges$.subscribe((args: FieldViewPortChanges) => {
                this.onFieldViewPortChanges(args);
            });
            this.registerSubscription(subscription);

            const scrollSubscription = this.scrollService.scrollCompleted.subscribe(() => {
                this.onScrollCompleted();
            });
            this.registerSubscription(scrollSubscription);
    }

    ngOnInit() {
        this.sectionMenuClasses = this.getSectionMenuClasses();
    }

    private setTopPosition() {
        this.menuWrapper.nativeElement.style.top = `${this.window.scrollY + TOP_MARGIN}px`;
    }

    getSectionMenuClasses(): string {
        let cls = "sf-section-nav ";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -")
        }

        return cls;
    }

    handleMenuItemClick(model: ContentSectionMenuItemModel) {
        this.isScrollingFromItemClick = true;

        this.items.forEach((model: ContentSectionMenuItemModel) => {
            model.isActive = false;
        });

        model.isActive = true;
        this.contentSectionMenuService.requestBringIntoView(model.originalModel);
    }

    scrollToTop() {
        this.scrollService.scrollToTop(true);
    }

    @HostListener("window:scroll") requestFieldSectionsCalculations() {
        if (this.isVisible) {
            this.contentSectionMenuService.requestFieldSectionPositionCalculation();

            if (this.look && this.look.includes("in-form")) {
                this.setTopPosition();
            }
        }
    }

    private calculateContentSectionMenuVisibility(sections: FieldSectionModel[]) {
        let minNumberOfSections = 5;
        if (this.useConfigSettings) {
            minNumberOfSections = this.configService.externalConfig.sectionsMenuMinColumnsNumber || minNumberOfSections;
        }

        if (sections && sections.filter(s => !s.settings.isMain && s.fields.length > 0).length >= minNumberOfSections) {
            this.isVisible = true;
        } else {
            this.isVisible = false;
        }
    }

    private onScrollCompleted() {
        this.isScrollingFromItemClick = false;
    }

    private onFieldViewPortChanges(args: FieldViewPortChanges) {
        const foundItemModel = this.items.find((model: ContentSectionMenuItemModel) => {
            return model.originalModel.equals(args.model);
        });

        if (!foundItemModel) {
            if (!this.isScrollingFromItemClick) {
                this.updateHighlightedItemIndex();
            }
            return;
        }

        const foundIndex = this.visibleFieldSectionsIndexes.findIndex((n: number) => {return n === foundItemModel.index; });
        if (!args.isInViewPort) {
            if (foundIndex > -1) {
                this.visibleFieldSectionsIndexes.splice(foundIndex, 1);
            }
        } else {
            if (foundIndex === -1) {
                this.visibleFieldSectionsIndexes.push(foundItemModel.index);
            }
        }

        if (this.isScrollingFromItemClick) {
            return;
        }

        this.updateHighlightedItemIndex();
    }

    private updateHighlightedItemIndex() {
        this.items.forEach((model: ContentSectionMenuItemModel) => {
            model.isActive = false;
        });

        if (this.visibleFieldSectionsIndexes.length > 0) {
            const topIndex = this.visibleFieldSectionsIndexes.sort()[0];

            for (const itemModel of this.items) {
                if (itemModel.index === topIndex) {
                    itemModel.isActive = true;
                    break;
                }
            }
        }
    }

    private processFieldSectionModels(models: FieldSectionModel[]): ContentSectionMenuItemModel[] {
        const finalModels: ContentSectionMenuItemModel[] = [];
        if (!models) {
            return finalModels;
        }

        models.forEach((model: FieldSectionModel, i: number) => {
            const newModel = new ContentSectionMenuItemModel();
            newModel.originalModel = model;
            newModel.index = i;
            if (!model.settings.isMain && model.fields.length > 0) {
                finalModels.push(newModel);
            }
        });
        return finalModels;
    }
}

class ContentSectionMenuItemModel extends FieldSectionModel {
    originalModel: FieldSectionModel;
    isActive: boolean = false;
    index: number;
}
