import { zip as observableZip } from "rxjs";

import { map, delay, mergeMap } from "rxjs/operators";
import { Observable } from "rxjs";
import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Router, CanActivate } from "@angular/router";

import { MetadataStore, MetadataContainer } from "../shared/services/metadata/meta-data.store";
import { SiteDataStore } from "../shared/services/metadata/site-data.store";
import { ROUTE_PATHS } from "../../constants/route-paths";
import { DynamicItemStrategyBase } from "./dynamic-modules/components/strategies/dynamic-item.strategy";

@Injectable()
export class ContentTypeGuard implements CanActivate {
    constructor(private metadataStore: MetadataStore, private siteDataStore: SiteDataStore, private router: Router) {
    }

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean> {
        const currentEntitySet = DynamicItemStrategyBase.getSet(route);

        const entityResult$ = this.resolveEntity(currentEntitySet);
        const isAccessible$ = this.siteDataStore.isEntitySetAccessible(currentEntitySet);
        const isAvailable$ = this.getCurrentModuleName(currentEntitySet).pipe(mergeMap(moduleName => {
            return this.siteDataStore.isModuleAvailable(moduleName);
        }));

        return observableZip(entityResult$, isAccessible$, isAvailable$).pipe(
            delay(0),
            map(result => {
                const entityResult = result[0];
                const isAccessible = result[1];
                const isAvailable = result[2];

                if (!entityResult.exists || !isAvailable) {
                    this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
                    return false;
                } else if (!isAccessible) {
                    this.router.navigate([ROUTE_PATHS.ACCESS_DENIED]);
                    return false;
                }

                return true;
            }));
    }

    private resolveEntity(entitySet: string): Observable<EntityResult> {
        return this.metadataStore.initialize().pipe(
            map((metadataContainer: MetadataContainer) => {
                const set = metadataContainer.entities[entitySet];
                const exists = Boolean(set);

                return {
                    exists: exists,
                    typeName: exists ? set.typeFullName : null
                };
            }));
    }

    private getCurrentModuleName(entitySet: string): Observable<string> {
        let currentModuleName: string;

        return this.metadataStore.initialize().pipe(
            map((metadataContainer: MetadataContainer) => {
                const moduleNames = Object.keys(metadataContainer.modules);
                currentModuleName = moduleNames
                    .find(name => metadataContainer.modules[name].AccessibleTypes.indexOf(entitySet) > -1);
                return currentModuleName;
            }));
    }
}

interface EntityResult {
    exists: boolean;
    typeName: string;
}
