import { Injectable } from "@angular/core";
import { ReplaySubject, Observable } from "rxjs";
import { DataItem } from "../interfaces";
import { DynamicItemService } from "./dynamic-item.service";
import { MetadataContainer } from "../../../shared/services/metadata/meta-data.store";

@Injectable()
export class ChildrenCountStore {
    private cache: { [key: string]: ReplaySubject<CacheItem> } = {};

    constructor(private service: DynamicItemService) { }

    public getChildrenCount(item: DataItem, metaContainer: MetadataContainer): Observable<CacheItem> {
        const cacheKey = this.getCacheKey(item);
        let cachedItem = this.cache[cacheKey];

        if (!cachedItem) {
            const cacheItem = new ReplaySubject<CacheItem>(1);

            this.service.getItemsChildrenCount(item, metaContainer).subscribe((data) => {
                cacheItem.next(data);
            });

            cachedItem = this.cache[cacheKey] = cacheItem;
        }

        return cachedItem.asObservable();
    }

    public invalidateCachedChidrenCountByChildItem(item: DataItem) {
        this.invalidateCachedChidrenCount(item.provider, item.parentKey);
    }

    public invalidateCachedChidrenCountByParentItem(item: DataItem) {
        this.invalidateCachedChidrenCount(item.provider, item.key);
    }

    private invalidateCachedChidrenCount(provider: string, key: string) {
        const cacheKeys = Object.keys(this.cache);

        // There is a script in integrated mode that overrides startsWith and endsWith with some buggy implementation
        // Therefore we need to do null checks on our own :(
        const cacheKey = cacheKeys.find(k => provider && k.startsWith(provider) && key && k.endsWith(key));
        delete this.cache[cacheKey];
    }

    private getCacheKey(item: DataItem): string {
        return `${item.provider}_${item.key}`;
    }
}

interface CacheItem {
    [setName: string]: number;
}
