import { Route, RouterModule } from "@angular/router";
import { OauthSignInRedirectComponent } from "./oauth/oauth-sign-in-redirect.component";

export const APP_ROUTE_PATHS = {
    SIGN_IN_REDIRECT: "sign-in",
    SIGN_OUT_REDIRECT: "sign-out"
};

export const AUTH_ROUTES: Route[] = [
    {
        path: "auth", children: [
            {
                path: "oauth", children: [
                    {
                        path: APP_ROUTE_PATHS.SIGN_IN_REDIRECT, component: OauthSignInRedirectComponent
                    }
                ]
            }
        ]
    }
];

export const authRouting = RouterModule.forChild(AUTH_ROUTES);
