import { DataItem, EntityData } from "../../../interfaces";
import { ContentCultureData } from "../../../../../shared/services/metadata/site-data.store";
import { PERMANENT_DELETE_PARAM_NAME } from "./delete-command";
import { CompositeOperationsProvider } from "../operations-provider";
import { Observable } from "rxjs-compat";
import { DynamicItemStore } from "../../dynamic-item.store";

export abstract class DeleteCommandExtenderBase {
    constructor(protected dynamicItemStore: DynamicItemStore) { }

    abstract isSupportedType(entityData: EntityData): boolean;

    showMultilingualButtons(data): boolean {
        const sitedataStore = data.siteData;
        const cultures: ContentCultureData[] = sitedataStore.ContentCultures;
        return data.entityData.metadata.isMultilingual && cultures.length > 1 &&
            (data.bulk || (data.dataItem && data.dataItem.data.AvailableLanguages && data.dataItem.data.AvailableLanguages.length > 1));
    }

    permanentDelete(data: any): boolean {
        let permanentDelete: boolean = true;
        if (data.action.contextParameters) {
            const permanentDeleteParam = data.action.contextParameters.find(p => p.Name === PERMANENT_DELETE_PARAM_NAME);
            if (permanentDeleteParam) {
                permanentDelete = permanentDeleteParam.Value.toLowerCase() !== "false";
            }
        }

        return permanentDelete;
    }

    getTitle(data: any): string {
        return data.action.detailedTitle || data.action.title;
    }

    getDisplayName(data: any): string {
        return data.bulk ?
            CompositeOperationsProvider.getOperationPluralName(data.dataItem ? data.dataItem.metadata : data.entityData.metadata, data.action.contextParameters) :
            CompositeOperationsProvider.getOperationSingularName(data.dataItem ? data.dataItem.metadata : data.entityData.metadata, data.action.contextParameters);
    }

    executeDelete(dataItem: DataItem, deleteAllTranslations: boolean, skipItemStateUpdate?: boolean): Observable<DataItem> {
        return this.dynamicItemStore.deleteItem({
            dataItem: dataItem,
            deleteAllTranslations: deleteAllTranslations,
            skipItemStateUpdate: skipItemStateUpdate
        });
    }
}
