import { Injectable } from "@angular/core";
import { DataItem } from "../interfaces";
import { SitefinitySdk } from "../../../../services/sitefinitySdk.service";
import { Observable, ReplaySubject } from "rxjs";
import { CacheStore } from "./cache-store";
import { ErrorParserService } from "../../../shared/services/errors/error-parser.service";

@Injectable()
export class TaxaInfoStore extends CacheStore<DataItem, AppliedToInfo> {

    constructor(private sitefinitySdk: SitefinitySdk, private errorParserService: ErrorParserService) {
        super();
    }

    protected getCacheKey(dataItem: DataItem): string {
        const cacheId = dataItem.metadata.setName + dataItem.data.Id;
        return cacheId;
    }

    protected requestItem(item: DataItem): Observable<AppliedToInfo> {
        const subject = new ReplaySubject<AppliedToInfo>(1);
        this.sitefinitySdk.instance.data({
            entitySet: item.metadata.setName,
            culture: item.culture
        }).getProperty({
            key: item.data.Id,
            property: "appliedTo",
            successCb: data => subject.next(data),
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.asObservable();
    }

    public getAppliedToCount(item: DataItem): Observable<AppliedToInfo> {
        return this.getItemInternal(item);
    }

    public getMarkedItems(item: DataItem): Observable<AppliedToInfo> {
        return this.getItemInternal(item);
    }
}

export interface AppliedToInfo {
    AppliedTo: number;
    Title: string;
    ContentType: string;
}
