import { combineLatest as observableCombineLatest } from "rxjs";

import { map } from "rxjs/operators";
import { environmentTypes } from "./../../environment";
import { MetadataStore, MetadataContainer } from "../shared/services/metadata/meta-data.store";
import { SiteDataStore, ModuleInfo } from "../shared/services/metadata/site-data.store";
import { Observable } from "rxjs";
import { Injectable } from "@angular/core";
import { environment } from "../../../environments/environment";

export const TYPES_OF_CONTENT_NAME = "Types of Content";
export const CLASSIFICATIONS_NAME = "Classifications";
export const MEDIA_NAME = "Media";
export const FORMS_NAME = "Forms";
export const FORMS_RESPONSES_NAME = "responses";
export const TAXONOMY_MODULE_NAME = "Taxonomy";
export const MEDIA_TYPES_MODULE_NAME = "Libraries";

const INTEGRATED_MODE_DISABLED_MODULES = [];

@Injectable()
export class ModulesProvider {
    constructor(private metadata: MetadataStore, private site: SiteDataStore) { }

    getModules(filterBySite: boolean = true): Observable<Array<ModuleData>> {
        let moduleInfo$: Observable<ModuleInfo> = null;
        if (filterBySite) {
            moduleInfo$ = this.site.getValue().pipe(map(x => x.Modules));
        } else {
            moduleInfo$ = this.metadata.initialize().pipe(map(container => {
                return container.modules;
            }));
        }

        return observableCombineLatest(this.metadata.initialize(), moduleInfo$).pipe(map((resolved) => {
            const container = resolved[0];
            const moduleInfo = resolved[1];

            return this.initialize(container, moduleInfo);
        }));
    }

    private getGroup(moduleName: string, nonChildEntityCount: number) {
        if (moduleName === MEDIA_TYPES_MODULE_NAME) {
            return MEDIA_NAME;
        } else if (moduleName === TAXONOMY_MODULE_NAME) {
            return CLASSIFICATIONS_NAME;
        } else if (nonChildEntityCount === 1) {
            return TYPES_OF_CONTENT_NAME;
        } else {
            return moduleName;
        }
    }

    private initialize(container: MetadataContainer, moduleInfo: ModuleInfo): Array<ModuleData> {
        const result: Array<ModuleData> = [];

        for (const moduleName of Object.keys(moduleInfo)) {
            if (environment.env === environmentTypes.integration) {
                if (INTEGRATED_MODE_DISABLED_MODULES.indexOf(moduleName) > -1) {
                    continue;
                }
            }

            // Get non child entities defined into the module
            const nonChildEntities = moduleInfo[moduleName].AccessibleTypes
                .filter((entitySetName) => {
                    const entity = container.entities[entitySetName];

                    if (!entity || !entity.enabled) {
                        return false;
                    }

                    // Should not show the module if it has IgnoreParentChildRelationShip and
                    // has children, for example: Calendars
                    if (entity.ignoreParentChildRelationship && entity.hasChildren) {
                        return false;
                    }

                    // Should not show the module if it has parent and doesn't have IgnoreParentChildRelationShip
                    // for example: ListItems, BlogPosts
                    if (entity.hasParent && !entity.ignoreParentChildRelationship) {
                        return false;
                    }

                    return true;
                })
                .map((entitySetName) => {
                    return container.entities[entitySetName];
                });

            if (nonChildEntities.length === 0) {
                continue;
            }

            // Find or create group for current module entites
            const group = this.getGroup(moduleName, nonChildEntities.length);
            let resultItem = result.find(item => item.title === group);

            if (!resultItem) {
                resultItem = {
                    title: group,
                    types: new Array<ModuleEntityData>()
                };

                result.push(resultItem);
            }

            // Add module entities to the group
            nonChildEntities.forEach((entity) => {
                resultItem.types.push({
                    url: entity.setName,
                    displayName: entity.displayName
                });
            });
        }

        return result;
    }
}

export interface ModuleData {
    title: string;
    types: Array<ModuleEntityData>;
}

export interface ModuleEntityData {
    url: string;
    displayName: string;
}
