import { Component } from "@angular/core";
import { Observable, of, throwError } from "rxjs";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { PropertyEditorConstants, Dictionary, PropertyEditorViewModes } from "../../property-editor.constants";
import { MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { ContentBlockConstants } from "../content-block.constants";
import { stringConstants } from "../../../../common-constants";
import { WidgetContext } from "../../models/widget-context";
import { WidgetMetadata, PropertyData, WidgetEditor, ActionContext, ValidationResult } from "../../interfaces/widget-editor";
import { CustomActions } from "../../interfaces/custom-actions";
import { tap, map } from "rxjs/operators";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-share-view",
    templateUrl: "./share.component.html"
})
export class ShareComponent extends SfRxBase implements WidgetEditor, CustomActions {
    context: WidgetContext;
    shareContentName = PropertyEditorConstants.SHARE_CONTENT;
    sharedName = stringConstants.EMPTY_STRING;

    private allProperties: Dictionary;
    private contentItem: any;

    constructor(protected dynamicItemService: DynamicItemService,
                protected metadataStore: MetadataStore) {
        super();
    }

    public initialize(propertiesData: WidgetMetadata): Observable<void> {
        this.allProperties = propertiesData.propertyValues;
        return of(undefined);
    }

    public setValues(propValues: Dictionary): void {
        this.allProperties = propValues;
    }

    public validate(): Observable<ValidationResult> {
        if (this.sharedName && this.sharedName.length > 0) {
            return of({ isValid: true });
        } else {
            return throwError({message: "Title cannot be empty!"});
        }
    }

    public getModifiedProperties(): Array<PropertyData> {
        const modifiedProps: Array<PropertyData> = [];
        if (this.contentItem) {
            modifiedProps.push({Name: ContentBlockConstants.SHARED_CONTENT_ID, Value: this.contentItem.data.Id});
        }

        return modifiedProps;
    }

    public actionExecuting(context: ActionContext): Observable<void> {
        if (context.processChanges) {
            const content = this.allProperties[ContentBlockConstants.CONTENT];
            const provider = this.allProperties[ContentBlockConstants.PROVIER_NAME];

            return this.createItem(content, provider).pipe(tap((contentItem) => {this.contentItem = contentItem; }), map(x => undefined));
        } else {
            return of(undefined);
        }
    }

    public getActions() {
        return {
            operations: [{
                Title: PropertyEditorConstants.SHARE_CONTENT,
                Category: {
                    Name: "default"
                },
                Name: PropertyEditorViewModes.SHARE,
                Ordinal: -1,
                Description: stringConstants.EMPTY_STRING,
                Link: stringConstants.EMPTY_STRING,
                Parameters: null,
                RequiresConfirmation: false
            }],
            cssClass: stringConstants.EMPTY_STRING
        };
    }

    private createItem(content, provider) {
        const contentItemEntity = this.metadataStore.getEntity(ContentBlockConstants.ENTITY_NAME);
        const contentItemEntityData = {
            culture: this.context.culture,
            provider: provider,
            metadata: contentItemEntity
        };

        return this.dynamicItemService.createItem({
            data: {
                Title: this.sharedName,
                Content: content
            },
            entityData: contentItemEntityData
        });
    }
}
