import { Injectable, Renderer2, Inject, RendererFactory2 } from "@angular/core";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { WINDOW_TOKEN } from "../../../window.provider";
import { KeyboardShortcutsService } from "../../../services/keyboard-shortcuts.service";

const OUTLINE: string = "outline";
const CONTRAST: string = "contrast";
const SHORTCUTS: string = "shortcuts";
const OUTLINE_CLASS: string = "-sf-outline";
const CONTRAST_CLASS: string = "-sf-contrast";

@Injectable()
export class UserPreferencesService {
    private renderer: Renderer2;

    constructor(
        private dynamicItemStore: DynamicItemStore,
        rendererFactory: RendererFactory2,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private keyboardShortcutsService: KeyboardShortcutsService) {
            this.renderer = rendererFactory.createRenderer(null, null);
    }

    checkAccessibility() {
        this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetPreference(keys=['${OUTLINE}','${CONTRAST}'])`).subscribe((preferences) => {
            const settings = JSON.parse(preferences.value);
            const outline = (settings[OUTLINE].toLowerCase() === "true");
            const contrast = (settings[CONTRAST].toLowerCase() === "true");
            // TODO: This is just a feature toggle if in some point keyboard shortcuts should be controlled per user
            const shortcuts = SHORTCUTS === "shortcuts";

            if (outline) {
                this.renderer.addClass(this.windowProvider.document.body, OUTLINE_CLASS);
            } else {
                if (this.windowProvider.document.body.classList.contains(OUTLINE_CLASS)) {
                    this.renderer.removeClass(this.windowProvider.document.body, OUTLINE_CLASS);
                }
            }

            if (contrast) {
                this.renderer.addClass(this.windowProvider.document.body, CONTRAST_CLASS);
            } else {
                if (this.windowProvider.document.body.classList.contains(CONTRAST_CLASS)) {
                    this.renderer.removeClass(this.windowProvider.document.body, CONTRAST_CLASS);
                }
            }

            if (shortcuts) {
                this.keyboardShortcutsService.init();
            }
        });
    }
}
