import { ModalWindowService, DialogData, DEFAULT_URL_KEY, ClosingContext, ClosingContextType, Button, ConfirmButton, CancelButton, ClickResult } from "../../../../shared/services/modal-window.service";
import { Observable, ReplaySubject } from "rxjs";
import { first } from "rxjs/operators";
import { ExecuteOnceInBulkCommand } from "../../../../shared/commands/command";
import { ExecutionContext } from "../../../../shared/commands/execution-context";
import { BulkOperationResult, BulkResult, BulkResultType, SUCCESSFUL_NOTIFFICATION_TIME } from "../../../../content/dynamic-modules/services/operations/commands/bulk-command";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../shared/services/notification/notification-data";
import { NotificationService } from "../../../../shared/services/notification/notification.service";
import { CommandNotificationArgs, HasNotificationCommand } from "../../../../shared/commands/has-notification-command";
import { SetCustomExpirationComponent } from "../set-custom-expiration/set-custom-expiration.component";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { BasicNotificationComponent } from "../../../../shared/components/notifications/basic-notification/basic-notification.component";
import { OPERATION_TITLES } from "../../../../shared/components/action-menu/operation.model";

const CUSTOM_EXPIRATION_SUCCESS_MESSAGE = "Expiration period was updated successfully.";
const CUSTOM_EXPIRATION_ERROR_MESSAGE = "Failed to update expiration period."
const CUSTOM_EXPIRATION_PARTIAL_ERROR_MESSAGE = "Failed to update expiration period for {0} out of {1} items."

export class SetCustomExpirationCommand implements ExecuteOnceInBulkCommand, HasNotificationCommand {
    public executeOnceInBulk: boolean = true;

    constructor(
        private readonly modalWindowService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        private notificationFilter: string,
        private readonly notificationService: NotificationService) {
    }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        const handled = new ReplaySubject<BulkOperationResult>(1);

        const setCustomExpirationComponentData = this.getComponentData(context, handled);
        const buttons: Button[] = [
            new ConfirmButton(OPERATION_TITLES.saveChanges, (data) => this.onDoneClicked(context, data.component, handled)),
            new CancelButton()
        ];
        const dialogData = new DialogData(setCustomExpirationComponentData, (closingContext: ClosingContext) => {
            if (closingContext.type === ClosingContextType.ButtonClicked && closingContext.data && closingContext.data.data) {
                handled.next(closingContext.data.data);
            } else {
                handled.next({ success: false });
            }
        }, buttons);

        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.show(DEFAULT_URL_KEY, context.currentRoute.parent);

        return handled.pipe(first());
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!succeededItems && !failedItems) {
            return null;
        }

        const operationFailed: boolean = failedItems && failedItems.length > 0;

        const notificationData = {
            id: "bulkOperationsNotification",
            type: BasicNotificationComponent,
            properties: {
                message: CUSTOM_EXPIRATION_SUCCESS_MESSAGE
            },
            look: NOTIFICATION_LOOKS.SUCCESS,
            filterParam: this.notificationFilter,
            closeButton: false,
            duration: SUCCESSFUL_NOTIFFICATION_TIME,
            removePreviousView: true,
            updatePropertiesOnChange: true
        };

        if (operationFailed) {
            notificationData.closeButton = true;
            notificationData.duration = null;

            if (succeededItems.length === 0){
                notificationData.look = NOTIFICATION_LOOKS.ERROR;
                notificationData.properties.message = CUSTOM_EXPIRATION_ERROR_MESSAGE;
            } else {
                notificationData.look = NOTIFICATION_LOOKS.WARNING;
                notificationData.properties.message = CUSTOM_EXPIRATION_PARTIAL_ERROR_MESSAGE
                                                        .replace("{0}", `${failedItems.length}`)
                                                        .replace("{1}", `${failedItems.length + succeededItems.length}`);
            }
        }

        return notificationData;
    }

    private getComponentData(context: ExecutionContext, handled: ReplaySubject<BulkOperationResult>): ComponentData {
        return {
            type: SetCustomExpirationComponent,
            properties: {
                entityData: context.data.entityData,
                selectedItems: context.data.selectedItems
            }
        };
    }

    private onDoneClicked(context: ExecutionContext, component: SetCustomExpirationComponent, handled: ReplaySubject<BulkOperationResult>): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (component.selectedItems.length > 0) {
            const itemIds = component.selectedItems.map(x => x.key);
            const value: string = component.getValue();

            const changeCustomPageExpirationParameters = {
                PageNodeIds: itemIds,
                ExpirationInDays: value,
            };

            const functionData: any = {
                changeCustomPageExpirationParameters
            };

            clickResult.next(new ClickResult({}, false, false, true));
            this.dynamicItemStore.service.executeEntityOperation(context.data.entityData, "Default.ChangeCustomExpirationDays()", functionData)
                .subscribe({
                    next: (result: BulkResult) => {
                        const bulkResult: BulkOperationResult = {
                            success: result.Type === BulkResultType.Success,
                            succeededItemsIds: result.SucceededItemsIds,
                            failedItemsIds: result.FailedItemsIds
                        };

                        if (itemIds.length === 1) {
                            const notification = this.getNotification(result.SucceededItemsIds, result.FailedItemsIds, null);
                            this.notificationService.publishNotification(notification);
                        }

                        clickResult.next(new ClickResult(bulkResult, true));
                    },
                    error: () => {
                        const bulkResult: BulkOperationResult = {
                            success: false,
                            failedItemsIds: itemIds
                        };

                        if (itemIds.length === 1) {
                            const notification = this.getNotification([], itemIds, null);
                            this.notificationService.publishNotification(notification);
                        }

                        clickResult.next(new ClickResult(bulkResult, true));
                    }
                });
        }

        return clickResult;
    }
}
