import { Component, OnInit } from "@angular/core";

import { ShortTextComponent } from "../../../../fields/short-text/short-text.component";
import { createValueAccessor } from "../../../../fields/field-base";

@Component({
    selector: "sf-url-name",
    templateUrl: "./urlName.component.html",
    providers: [createValueAccessor(UrlNameComponent)]
})
export class UrlNameComponent extends ShortTextComponent implements OnInit {
    showEditableField: boolean = false;
    showCreateButton: boolean = true;
    showReadOnlyField: boolean = false;

    constructor() {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.showCreateButton = !this.settings.readOnlyMode && this.value == null;
        this.showReadOnlyField = !this.showCreateButton;
    }

    writeValue(value: string) {
        if (!value && !this.showEditableField) {
            this.showReadOnlyField = false;
            this.showCreateButton = true;
        } else if (!this.showEditableField) {
            this.showReadOnlyField = true;
            this.showCreateButton = false;
        }

        super.writeValue(value);
    }

    toggleEditableField() {
        this.onFocus();
    }

    onFocus() {
        super.onFocus();
        if (this.settings.readOnlyMode) {
            return;
        }

        this.showEditableField = true;
        this.showCreateButton = this.showReadOnlyField = false;
    }

    onBlur() {
        super.onBlur();
        if (!this.value) {
            this.showCreateButton = true;
            this.showReadOnlyField = false;
        } else {
            this.showCreateButton = false;
            this.showReadOnlyField = true;
        }

        this.showEditableField = false;
    }
}
