import { FeedbackInfo } from "../../models/feedback-info";
import { Component } from "@angular/core";
import { of, Observable, Subject } from "rxjs";
import { ServiceContract, ServiceInfo } from "../../../../../../fields/selector/selector.component";
import { BaseServiceInfo } from "../../../../../../fields/services/base.service";
import { LoadItemsData, DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { first, map } from "rxjs/operators";
import { MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { SelectorConstants } from "../../../html/selector-constants";
import { SettingsBase } from "../../../../../../fields/field-settings-base";
import { ChoiceDropdownListComponent } from "../../../../../../fields/choice/choice-dropdown-list.component";
import { ProviderStore } from "../../../content/dynamic-modules/services/provider-store";
import { PropertyEditorConstants, PropertyEditorViewModes, Dictionary } from "../../property-editor.constants";
import { ContentBlockConstants } from "../content-block.constants";
import { stringConstants } from "../../../../common-constants";
import { WidgetContext } from "../../models/widget-context";
import { WidgetMetadata, PropertyData, WidgetEditor, ActionContext, ValidationResult } from "../../interfaces/widget-editor";
import { NotifyStatusChange } from "../../interfaces/notify-status-change";
import { CustomActions } from "../../interfaces/custom-actions";
import { Settings } from "../../../shared/services/settings.service";
import { BundleDataService, BUNDLE_DATA_OPERATIONS, ExecutionContext } from "../../../../services/bundle-data.service";
import { ActivatedRoute } from "@angular/router";
import { SiteData } from "../../../shared/services/metadata/site-data.store";
import { TreeItem } from "../../../../../../fields";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-useshared-view",
    templateUrl: "./use-shared.component.html"
})
export class UseSharedComponent extends SfRxBase implements WidgetEditor, NotifyStatusChange, CustomActions {
    context: WidgetContext;
    notifyStatusChange$ = new Subject<FeedbackInfo>();

    selectedItem: TreeItem[] = [];
    treeConfig = {
        multiSelection: false,
        status: false,
        description: true,
        skipNodeMappingToDefaultModel: true
    };
    value: TreeItem[];
    providerName: string;
    typeNames = { plural: "shared content"};
    serviceAware: ServiceContract;
    providerSettings: SettingsBase;
    selectSharedTitle = PropertyEditorConstants.SELECT_SHARED_TITLE;

    private footerButtonsClass = "-bottom";
    private selectedItemId = stringConstants.EMPTY_STRING;
    private cbData: any;
    private entityData: EntityData;

    constructor(protected dynamicService: DynamicItemService,
                protected metadataStore: MetadataStore,
                private store: ProviderStore,
                private settings: Settings,
                private bundleDataService: BundleDataService,
                private route: ActivatedRoute) {
            super();
        }

    public initialize(propertiesData: WidgetMetadata): Observable<void> {

        this.cbData = propertiesData.propertyValues;

        this.loadInitialModalItems(this.cbData).pipe(first()).subscribe(initialItems => {
            this.value = initialItems || [];

            if (this.selectedItemId) {
                const item = initialItems.find(item => item.dataItem.key === this.selectedItemId);
                this.selectedItem =  item ? [item] : [];
            } else if (initialItems && initialItems.length > 0) {
                const item = initialItems[0];
                this.selectedItem =  item ? [item] : [];
            }

            return this.value;
        });

        this.serviceAware = new ServiceContract(
            (info: ServiceInfo) => this.loadMoreModalItems(info, this.cbData),
            (info: ServiceInfo) => this.loadMoreModalItems(info, this.cbData));
        return of(undefined);
    }

    public setValues(propValues: Dictionary): void {
        this.cbData = propValues;
        this.loadInitialModalItems(this.cbData).pipe(first()).subscribe(initialItems => {
            this.value = initialItems || [];

            if (this.selectedItemId) {
                const item = initialItems.find(item => item.dataItem.key === this.selectedItemId);
                this.selectedItem =  item ? [item] : [];
            } else if (initialItems && initialItems.length > 0) {
                const item = initialItems[0];
                this.selectedItem =  item ? [item] : [];
            }

            return this.value;
        });
    }

    public validate(): Observable<ValidationResult> {
        return of({ isValid: true });
    }

    public getModifiedProperties(): Array<PropertyData> {
        const modifiedProps: Array<PropertyData> = [];
        if (this.selectedItem && this.selectedItem.length === 1) {
            this.cbData[ContentBlockConstants.SHARED_CONTENT_ID] = this.selectedItem[0].dataItem.key;
            this.cbData[ContentBlockConstants.PROVIER_NAME] = this.selectedItem[0].dataItem.provider;
            this.cbData[ContentBlockConstants.CONTENT] = this.selectedItem[0].dataItem.data.Content;
            modifiedProps.push({Name: ContentBlockConstants.SHARED_CONTENT_ID, Value: this.cbData[ContentBlockConstants.SHARED_CONTENT_ID]});
            modifiedProps.push({Name: ContentBlockConstants.PROVIER_NAME, Value: this.cbData[ContentBlockConstants.PROVIER_NAME]});
            modifiedProps.push({Name: ContentBlockConstants.CONTENT, Value: this.cbData[ContentBlockConstants.CONTENT]});
        }

        return modifiedProps;
    }

    public actionExecuting(context: ActionContext): Observable<void> {
        return of(undefined);
    }

    public getActions() {
        return {
            operations: [{
                Title: SelectorConstants.USE_SELECTED,
                Category: {
                    Name: "default"
                },
                Name: PropertyEditorViewModes.USE_SHARED,
                Ordinal: -1,
                Description: stringConstants.EMPTY_STRING,
                Link: stringConstants.EMPTY_STRING,
                Parameters: null,
                RequiresConfirmation: false
            }],
            cssClass: this.footerButtonsClass
        };
    }

    public onSelectedItemChanged(item: TreeItem) {
        if (item.dataItem.key !== this.selectedItemId) {
            this.cbData[ContentBlockConstants.SHARED_CONTENT_ID] = item.dataItem.key;
            this.selectedItemId = item.dataItem.key;
            this.selectedItem = [item];
        } else {
            this.selectedItemId = stringConstants.DEFAULT_GUID;
            this.selectedItem = [];
        }
    }

    public onProviderSelectionChange(providerName: string) {
        const feedback = new FeedbackInfo();
        feedback.showLoadingIndicator = true;
        this.notifyStatusChange$.next(feedback);
        this.providerName = providerName;
        this.cbData[ContentBlockConstants.PROVIER_NAME] = providerName;
        this.loadInitialModalItems(this.cbData).pipe(first()).subscribe(initialItems => {
            this.value = initialItems;
            feedback.reset();
            this.notifyStatusChange$.next(feedback);
        });
    }

    private createBaseServiceInfo(properties: any[]): BaseServiceInfo {

        this.providerName = properties[ContentBlockConstants.PROVIER_NAME];
        this.selectedItemId = properties[ContentBlockConstants.SHARED_CONTENT_ID];

        const info: BaseServiceInfo = {
            type: ContentBlockConstants.ENTITY_NAME,
            provider: this.providerName,
            culture: this.context.culture
        };

        return info;
    }

    private getSettings(providers: any[], activeProviderName: string): SettingsBase {
        const dropdownOptions: Array<ChoiceItem> = providers.map(provider => {
            return {
                Name: provider.title,
                Value: provider.name
            };
        });

        const settings = ChoiceDropdownListComponent.createFieldSettings(dropdownOptions, activeProviderName);

        return settings;
    }

    private loadInitialModalItems(properties): Observable<TreeItem[]> {
        const info = this.createBaseServiceInfo(properties);
        return this.loadMoreModalItems(info, properties);
    }

    private loadMoreModalItems(serviceInfo: ServiceInfo, properties: any[]): Observable<TreeItem[]> {
        const baseInfo = this.createBaseServiceInfo(properties);

        const relatedDataEntity = this.metadataStore.getEntity(ContentBlockConstants.ENTITY_NAME);
        this.entityData = {
            culture: this.context.culture,
            provider: this.providerName,
            metadata: relatedDataEntity
        };

        const providerSubscription = this.store.getProviders(this.entityData.metadata.setName).subscribe((providers: any[]) => {
            if (providers.length > 1) {
                const activeProviderName = this.entityData.provider ? this.entityData.provider : providers.find(p => p.isDefault).name;
                this.providerSettings = this.getSettings(providers, activeProviderName);
            } else {
                this.providerSettings = null;
            }
        });
        this.registerSubscription(providerSubscription);

        const args: LoadItemsData = {
            entityData: this.entityData,
            skip: serviceInfo.skip,
            take: serviceInfo.take,
            order: `Title desc`,
            filter: [],
            action: baseInfo.action,
            serviceUrl: this.settings.webServiceLiveUrl
        };

        if (serviceInfo.searchText) {
            args.filter.push({ key: this.entityData.metadata.defaultFieldName, value: [serviceInfo.searchText] });
        }

        return this.dynamicService.getItemList(args).pipe(map(data => {
            const treeItems = data.dataItems.map(item => this.cloneAndAddFieldsToDataItem(item));

            const siteData: SiteData = this.route.parent.snapshot.data.siteDataStore;
            this.bundleDataService.requestBatch(data.dataItems.map(x => <ExecutionContext>{
                id: x.key,
                action: BUNDLE_DATA_OPERATIONS.SHARED_IN_COUNT,
                entityData: this.entityData
            }), this.entityData, siteData.Id, !serviceInfo.skip);

            return treeItems;
        }));
    }

    private cloneAndAddFieldsToDataItem(dataItem: DataItem): TreeItem {
        return {
            hasChildren: dataItem.data.HasChildren,
            id: dataItem.key,
            dataItem
        };
    }
}
