import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot } from "@angular/router";
import { SiteDataStore } from "./metadata/site-data.store";
import { Title } from "@angular/platform-browser";
import { SiteTitleResolver } from "./site-title.resolver";
import { RESOLVE_NAMES } from "../../content/constants";
import { MetadataStore } from "./metadata/meta-data.store";
import { ENTITY_SET } from "./metadata/meta-data-constants";
import { getRouteDynamicTypeNameRecursively } from "../../content/dynamic-modules/components/helpers";

const SPECIFIC_ROUTES = {
    SEARCH_INDEXES: "searchindexes"
};

@Injectable()
export class SiteTitleDynamicResolver extends SiteTitleResolver implements Resolve<any> {

    private specificTitlesMap: { [path: string]: string; } = {};

    constructor(protected siteDataStore: SiteDataStore, protected title: Title, protected metadataStore: MetadataStore) {
        super(siteDataStore, title);
        this.specificTitlesMap[SPECIFIC_ROUTES.SEARCH_INDEXES] = "Search indexes";
    }

    protected getTitlePattern(route: ActivatedRouteSnapshot): string {
        const parentRoute = route.parent;
        const dynamicTypeName = getRouteDynamicTypeNameRecursively(parentRoute);

        const specificTitle = this.specificTitlesMap[dynamicTypeName];
        if (specificTitle != null) {
            return this.titlePatternPage.replace("{1}", specificTitle);
        }

        const typeInfo = this.metadataStore.getValue().entities[dynamicTypeName];
        if (typeInfo != null) {
            if (typeInfo.isSelfReferencing || dynamicTypeName === ENTITY_SET.FORMS) {

                const itemData = route.data[RESOLVE_NAMES.itemData];
                if (itemData) {
                    return itemData.item.data[typeInfo.defaultFieldName];
                }
            }

            return this.titlePatternPage.replace("{1}", typeInfo.displayName);
        }

        return this.titlePatternEmpty;
    }
}
