import { of as observableOf, defer as observableDefer, combineLatest } from "rxjs";

import { withLatestFrom, map } from "rxjs/operators";
import { OPERATION_CATEGORIES, OperationCategory } from "./../../../../shared/components/action-menu/operation.model";
import { Entity } from "./../../../../shared/services/metadata/meta-data.store";
import { Observable } from "rxjs";
import { Optional, Inject, Injectable, InjectionToken } from "@angular/core";
import { Operation, OPERATION_NAMES, OPERATION_TITLES } from "../../../../shared/components/action-menu/operation.model";
import { OperationsProvider, OperationsData, OperationsTarget, OperationsDataContext } from "./interfaces";
import { DataItem, EntityData } from "../../interfaces";
import { CommandModelBase } from "../../../../shared/commands/command-model-base";
import { OPERATIONS_FILTER_TOKEN, OperationsFilter } from "./operations-filter";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { LANGUAGE_BADGE_EDIT_LOOK } from "../../../../shared/components/languages-dropdown/languages-dropdown.component";

export const OPERATIONS_TOKEN = new InjectionToken("operations_token");

const SINGULAR_NAME_PARAM_NAME = "SingularName";
const PLURAL_NAME_PARAM_NAME = "PluralName";

@Injectable()
export class CompositeOperationsProvider implements OperationsProvider {

    constructor(
        @Optional() @Inject(OPERATIONS_TOKEN) private operationProviders: Array<OperationsProvider>,
        @Optional() @Inject(OPERATIONS_FILTER_TOKEN) private operationFilters: Array<OperationsFilter>,
        @Inject(WINDOW_TOKEN) private window: Window) {
    }

    public static getOperationSingularName(entity: Entity, operationContextParameters?: any[]): string {
        let singularName: string = entity.singularName;
        if (operationContextParameters) {
            const singularNameParam = operationContextParameters.find(p => p.Name === SINGULAR_NAME_PARAM_NAME);
            if (singularNameParam) {
                singularName = singularNameParam.Value;
            }
        }

        return singularName;
    }

    public static getOperationPluralName(entity: Entity, operationContextParameters?: any[]): string {
        let pluralName: string = entity.displayName;
        if (operationContextParameters) {
            const pluralNameParam = operationContextParameters.find(p => p.Name === PLURAL_NAME_PARAM_NAME);
            if (pluralNameParam) {
                pluralName = pluralNameParam.Value;
            }
        }

        return pluralName;
    }

    getOperations(data: OperationsData): Observable<Operation[]> {
        return combineLatest([this.loadOperations(data), this.processCommands(data)]).pipe(
            map(([d1, d2]) => {
                const allCommands = d1.concat(d2);
                return allCommands;
            }));
    }

    getCommands(data: OperationsData): Observable<CommandModelBase[]> {
        return null;
    }

    getCategories(data: OperationsData): Observable<OperationCategory[]> {
        return null;
    }

    getListMainOperations(entityData: EntityData, parentItem: DataItem, isHierarchicalView: boolean): Observable<Operation[]> {
        const data = new OperationsData(DataItem.emptyItem(entityData), OperationsTarget.List, parentItem, { origin: this.window.location.href, isHierarchicalView });
        return this.getOperations(data).pipe(
            map(operations => operations.filter(p => p.Category && p.Category.Name === OPERATION_CATEGORIES.default)));
    }

    getListItemOperations(item: DataItem, parentItem: DataItem): Observable<Operation[]> {
        const data = new OperationsData(item, OperationsTarget.List, parentItem, { origin: this.window.location.href });
        return this.getOperations(data);
    }

    getBulkOperations(entityData: EntityData, parentItem: DataItem): Observable<Operation[]> {
        const data = new OperationsData(DataItem.emptyItem(entityData), OperationsTarget.Bulk, parentItem, { origin: this.window.location.href });
        return this.getOperations(data);
    }

    getCreateItemOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        const data = new OperationsData(DataItem.emptyItem(entityData), OperationsTarget.Create, parentItem, Object.assign(operationsDataContext, { origin: this.window.location.href }));
        return this.getOperations(data);
    }

    getEditItemOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}, additionalQueryParams: { [key: string]: string } = null): Observable<Operation[]> {
        const data = new OperationsData(item, OperationsTarget.Edit, parentItem, Object.assign(operationsDataContext, { origin: this.window.location.href }), additionalQueryParams);
        return this.getOperations(data);
    }

    getCreateItemMainOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditMainOperations(this.getCreateItemOperations(entityData, parentItem, operationsDataContext));
    }

    getEditItemMainOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}, additionalQueryParams: { [key: string]: string } = null): Observable<Operation[]> {
        return this.filterCreateEditMainOperations(this.getEditItemOperations(item, parentItem, operationsDataContext, additionalQueryParams));
    }

    private filterCreateEditMainOperations(operations: Observable<Operation[]>): Observable<Operation[]> {
        return operations.pipe(map(o => o.filter(p => p.Name !== OPERATION_NAMES.preview &&
            p.Name !== OPERATION_NAMES.stopSyncing &&
            p.Name !== OPERATION_NAMES.stopSyncingWarning &&
            p.Category.Name !== OPERATION_CATEGORIES.personalizedWidgets &&
            p.Category.Name !== OPERATION_CATEGORIES.personalization &&
            p.Category.Name !== OPERATION_CATEGORIES.personalized)));
    }

    getEditItemCustomOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}, additionalQueryParams: { [key: string]: string } = null): Observable<Operation[]> {
        return this.filterCreateEditCustomOperations(this.getEditItemOperations(item, parentItem, operationsDataContext, additionalQueryParams));
    }

    getCreateItemCustomOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditCustomOperations(this.getCreateItemOperations(entityData, parentItem, operationsDataContext));
    }

    private filterCreateEditCustomOperations(operations: Observable<Operation[]>): Observable<Operation[]> {
        return operations.pipe(map(o => {
            const result = [];
            const stopSyncingOperation = o.find(p => p.Name === OPERATION_NAMES.stopSyncing);
            const stopSyncingOperationWarning = o.find(p => p.Name === OPERATION_NAMES.stopSyncingWarning);

            if (stopSyncingOperationWarning) {
                result.push(stopSyncingOperationWarning);
            }

            if (stopSyncingOperation) {
                stopSyncingOperation.context = {
                    additionalText: null,
                    look: LANGUAGE_BADGE_EDIT_LOOK
                };

                result.push(stopSyncingOperation);
            }

            return result;
        }));
    }

    getCreateItemDialogOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditDialogOperations(this.getCreateItemOperations(entityData, parentItem, operationsDataContext), DataItem.emptyItem(entityData));
    }

    getEditItemDialogOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditDialogOperations(this.getEditItemOperations(item, parentItem, operationsDataContext), item);
    }

    private filterCreateEditDialogOperations(operations: Observable<Operation[]>, item: DataItem): Observable<Operation[]> {
        return operations.pipe(map((operations) => {
            const cancelOperation: Operation = {
                Title: OPERATION_TITLES.cancel,
                Category: { Name: OPERATION_CATEGORIES.default },
                Name: OPERATION_NAMES.cancel,
                Ordinal: 0,
                Description: null,
                Link: null,
                Parameters: null,
                RequiresConfirmation: false
            };

            if (!item.isEmpty) {

                // the cancel button should not be visible if the user cannot unlock or edit the item
                // UX requirement
                const hasUnlock = operations.find(x => x.Name === OPERATION_NAMES.unlock);
                const hasEdit = operations.find(x => x.Name === OPERATION_NAMES.edit || (x.ParentOperation != null && x.ParentOperation.Name === OPERATION_NAMES.edit));

                if (hasEdit || hasUnlock) {
                    operations.push(cancelOperation);
                }
            }

            operations = operations.filter(x => x.Name !== OPERATION_NAMES.preview && x.Name !== OPERATION_NAMES.shareTaxonomyWithSite);

            if (item.metadata.hasContent) {
                operations = operations.filter(x => x.Category.Name !== OPERATION_CATEGORIES.workflow && x.Category.Name !== OPERATION_CATEGORIES.settings);
            }

            return operations;
        }));
    }

    getEditItemAdditionalOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}, additionalQueryParams: { [key: string]: string } = null): Observable<Operation[]> {
        return this.filterCreateEditAdditionalOperations(this.getEditItemOperations(item, parentItem, operationsDataContext, additionalQueryParams));
    }

    getCreateItemAdditionalOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditAdditionalOperations(this.getCreateItemOperations(entityData, parentItem, operationsDataContext));
    }

    private filterCreateEditAdditionalOperations(operations: Observable<Operation[]>): Observable<Operation[]> {
        return operations.pipe(map(o => o.filter(p => p.Name === OPERATION_NAMES.preview)));
    }

    getEditItemPersonalizationOperations(item: DataItem, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}, additionalQueryParams: { [key: string]: string } = null): Observable<Operation[]> {
        return this.filterCreateEditPersonalizationOperations(this.getEditItemOperations(item, parentItem, operationsDataContext, additionalQueryParams));
    }

    getCreateItemPersonalizationOperations(entityData: EntityData, parentItem: DataItem, operationsDataContext: OperationsDataContext = {}): Observable<Operation[]> {
        return this.filterCreateEditPersonalizationOperations(this.getCreateItemOperations(entityData, parentItem, operationsDataContext));
    }

    private filterCreateEditPersonalizationOperations(operations: Observable<Operation[]>): Observable<Operation[]> {
        return operations.pipe(map(o => o.filter(x => x.Category.Name === OPERATION_CATEGORIES.personalization || x.Category.Name === OPERATION_CATEGORIES.personalized || x.Category.Name === OPERATION_CATEGORIES.personalizedWidgets)));
    }

    private processCommands(data: OperationsData): Observable<Operation[]> {
        const commandsArr$ = this.operationProviders.map(x => x.getCommands(data));
        const commands$ = combineLatest([...commandsArr$]).pipe(
            map(o => {
                const allCommands = o.reduce((previous, current) => previous.concat(current));
                return allCommands;
            }));

        return commands$.pipe(withLatestFrom(this.loadCategories(data), (commands, categories) => {
            return commands.map(command => {
                const operation: any = {
                    Name: command.name,
                    Title: command.title,
                    Ordinal: command.ordinal,
                    token: command.token
                };

                operation.Category = {
                    Name: command.category
                };

                // We are casting to any because the categories registered from the extensions use the
                // CommandCategory interface which properties are the same as the OperationsCategory props
                // but with lowercase
                const commandCategory = categories.find(x => (<any>x).name === command.category);
                if (commandCategory) {
                    operation.Category.Title = (<any>commandCategory).title;
                }

                return operation as Operation;
            });
        }));
    }

    private loadCategories(data: OperationsData): Observable<OperationCategory[]> {
        const categoriesArr$ = this.operationProviders.map(x => x.getCategories(data));
        const categories$ = combineLatest([...categoriesArr$]).pipe(
            map(o => {
                const allCategories = o.reduce((previous, current) => previous.concat(current));
                return allCategories;
            }));

        return categories$;
    }

    private loadOperations(data: OperationsData): Observable<Operation[]> {
        return observableDefer(() => {
            const operationsArr$ = this.operationProviders.map(x => x.getOperations ? x.getOperations(data) : observableOf([]));
            const operations$ = combineLatest([...operationsArr$]).pipe(
                map(o => {
                    const allOperations = o.reduce((previous, current) => previous.concat(current));
                    return allOperations;
                }));

            return operations$.pipe(
                map(operations => {
                    // TODO: remove when the operations are returned in cammel case from the server.
                    // Needed by extension, so we can expose interface with cammel case properties.
                    // If we expose pascal case props, they will be broken in future.
                    operations.forEach(op => this.propNamesToCammelCase(op));

                    const filtered = this.applyFilters(operations, data);
                    return filtered;
                }));
        });
    }

    private propNamesToCammelCase(operation: Operation) {
        Object.keys(operation).forEach(prop => {
            const newPropName = prop.charAt(0).toLowerCase() + prop.slice(1);
            operation[newPropName] = operation[prop];
        });
    }

    private applyFilters(operations: Operation[], data: OperationsData): Operation[] {
        if (this.operationFilters) {
            this.operationFilters.forEach(operationFilter => {
                operations = operationFilter.filter(operations, data);
            });
        }

        return operations;
    }

    invalidateCachedItemOperations(itemId: string): void {
        if (this.operationProviders) {
            this.operationProviders.forEach(operationProvider => operationProvider.invalidateCachedItemOperations(itemId));
        }
    }
}
