import { Output, EventEmitter, Input, OnInit, OnDestroy, Directive } from "@angular/core";
import { ProviderStore } from "../../services/provider-store";
import { Selector, SelectorEventArgs, SfRxBase } from "@progress/sitefinity-component-framework";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

const MIN_PROVIDER_COUNT = 1;

@Directive()
export class ProviderSelectorBaseComponent extends SfRxBase implements OnInit, Selector, OnDestroy {
    @Output() onChange = new EventEmitter<SelectorEventArgs>();
    @Output() onInit = new EventEmitter<SelectorEventArgs>();
    @Input() entitySetName: string;
    @Input() providers: Provider[];
    initialActiveProvider: Provider;
    dropdownOptions: Array<ChoiceItem>;
    private lastUsedProviderSet: string;

    constructor(protected store: ProviderStore) {
        super();
    }

    ngOnInit(): void {
        this.initializeProviders();
    }

    ngOnDestroy() {
        this.store.invalidateCache(this.lastUsedProviderSet);
        super.ngOnDestroy();
    }

    protected initializeProviders(preselectedProviderName?: string) {
        if (!this.entitySetName && !this.providers) {
            return;
        }

        if (this.entitySetName) {
            const subscription = this.store.getProviders(this.entitySetName)
                .subscribe((providers: Provider[]) => {
                    this.initialActiveProvider = this.getDefaultProvider(providers, preselectedProviderName);
                    if (providers.length > MIN_PROVIDER_COUNT) {
                        this.dropdownOptions = this.getDropDownOptions(providers);
                    } else {
                        this.dropdownOptions = [];
                    }

                    this.onInitializedProviders(providers);
                    this.onInit.emit(<SelectorEventArgs>{ tabValue: this.initialActiveProvider.name, triggerTabSelection: false });
                });

            this.registerSubscription(subscription);
            this.store.invalidateCache(this.lastUsedProviderSet);
            this.lastUsedProviderSet = this.entitySetName;
        } else {
            this.initialActiveProvider = this.getDefaultProvider(this.providers, preselectedProviderName);
            if (this.providers.length > MIN_PROVIDER_COUNT) {
                this.dropdownOptions = this.getDropDownOptions(this.providers);
            } else {
                this.dropdownOptions = [];
            }

            this.onInitializedProviders(this.providers);
            this.onInit.emit(<SelectorEventArgs>{ tabValue: this.initialActiveProvider.name, triggerTabSelection: false });
        }
    }

    onProviderSelectionChange(provider: string) {
        this.onChange.emit(<SelectorEventArgs>{ tabValue: provider, triggerTabSelection: true });
    }

    protected onInitializedProviders(providers: Provider[]) { }

    protected getDefaultProvider(providers: Provider[], preselectedProviderName: string): Provider {
        let defaultProvider = providers.find(x => x.isDefault);
        if (preselectedProviderName) {
            defaultProvider = providers.find(x => x.name === preselectedProviderName);
        }

        if (defaultProvider) {
            return defaultProvider;
        }

        return providers[0];
    }

    private getDropDownOptions(providers: Provider[]): Array<ChoiceItem> {
        const dropdownOptions: Array<ChoiceItem> = providers.map(provider => {
            return {
                Name: provider.title,
                Value: provider.name
            };
        });

        return dropdownOptions;
    }
}

export interface Provider {
    name: string;
    title: string;
    isDefault: boolean;
}
