import { DateTimeFilterValue } from "./date-time-selector.component";
import { CombinedFilter, DateInterval, FilterClause } from "../filter-content/combined-filter";

export class DateTimeFilterParser {

    public static parseToDateTimeInterval(complexFilterValue: string, dateFieldName: string): DateTimeFilterValue {

        if (!complexFilterValue) {
            return new DateTimeFilterValue();
        }

        const combinedFilter: CombinedFilter = complexFilterValue ? JSON.parse(complexFilterValue) : new CombinedFilter();
        const childFilterArray = combinedFilter.ChildFilters ?? [];
        const filterClause: any = childFilterArray.find(f => this.isDateFilter(f, dateFieldName));

        if (filterClause && filterClause.DateFieldName) {
            const dateFilter: DateInterval = filterClause;
            const dateTimeFilterValue = new DateTimeFilterValue();
            dateTimeFilterValue.PeriodType = "last";
            dateTimeFilterValue.TimeSpanInterval = dateFilter.OffsetType;
            dateTimeFilterValue.TimeSpanValue = dateFilter.OffsetValue as string ? Number.parseInt(dateFilter.OffsetValue.toString()) : dateFilter.OffsetValue as number;
            return dateTimeFilterValue;
        } else {
            const dateTimeFilterValue = new DateTimeFilterValue();
            const childFilters = filterClause ? (<CombinedFilter>filterClause).ChildFilters.map<FilterClause>(f => {return <FilterClause>f; }) : [];
            if (childFilters.length === 1 && childFilters[0].Operator === "lt") {
                dateTimeFilterValue.PeriodType = "period";
                const filterDate = new Date(childFilters[0].FieldValue);
                dateTimeFilterValue.ToDate = filterDate;
            } else if (childFilters.length === 1 && (childFilters[0]).Operator === "gt") {
                dateTimeFilterValue.PeriodType = "period";
                const filterDate = new Date(childFilters[0].FieldValue);
                dateTimeFilterValue.FromDate = filterDate;
            } else if (childFilters.length === 2) {
                dateTimeFilterValue.PeriodType = "period";
                dateTimeFilterValue.FromDate = new Date(childFilters[0].FieldValue);
                dateTimeFilterValue.ToDate = new Date(childFilters[1].FieldValue);
            }

            return dateTimeFilterValue;
        }
    }

    public static parseDateTimeIntervalToFilter(dateTimeInterval: DateTimeFilterValue, dateFieldName: string): any {

        if (dateTimeInterval && dateTimeInterval.PeriodType === "last") {
            const dateFilter = new DateInterval();
            dateFilter.DateFieldName = dateFieldName;
            dateFilter.OffsetType = dateTimeInterval.TimeSpanInterval;
            dateFilter.OffsetValue = dateTimeInterval.TimeSpanValue;
            return dateFilter;
        } else if (dateTimeInterval && dateTimeInterval.PeriodType === "period") {
            const dateCombinedFilter = new CombinedFilter();
            dateCombinedFilter.Operator = "and";
            dateCombinedFilter.ChildFilters = [];
            if (dateTimeInterval.FromDate) {
                const childFilter = new FilterClause();
                childFilter.FieldName = dateFieldName;
                childFilter.Operator = "gt";
                childFilter.FieldValue = dateTimeInterval.FromDate;
                dateCombinedFilter.ChildFilters.push(childFilter);
            }
            if (dateTimeInterval.ToDate) {
                const childFilter = new FilterClause();
                childFilter.FieldName = dateFieldName;
                childFilter.Operator = "lt";
                childFilter.FieldValue = dateTimeInterval.ToDate;
                dateCombinedFilter.ChildFilters.push(childFilter);
            }
            if (dateCombinedFilter.ChildFilters.length > 0)
                return dateCombinedFilter;
        }

        return null;
    }

    public static isDateFilter(filter: any, dateFieldName: string): boolean {
        if (filter.DateFieldName) {
            return true;
        }
        if (!filter.ChildFilters) {
            return false;
        }
        const dateExistingFilter = filter as CombinedFilter;
        const dateFilterIndex = dateExistingFilter.ChildFilters.findIndex(chF => (<FilterClause>chF).FieldName === dateFieldName);

        return dateFilterIndex > -1;
    }
}
