import { of as observableOf,  Observable } from "rxjs";

import { filter, map, mergeMap } from "rxjs/operators";
import { DynamicItemService, LoadItemsData, LoadItem } from "../../../../../../../../content/dynamic-modules/services/dynamic-item.service";
import { SelectorContext } from "../../selector-context";
import { Entity } from "../../../../../../../../shared/services/metadata/meta-data.store";
import { ExtendedKeyValuePair, Operation } from "../../../../../../../../../../../fields/services/base.service";
import { ContentSelectorStrategy, CHILD_LOAD_COUNT } from "./content-selector-strategy";
import { DYNAMIC_ITEMS_DEFINITIONS } from "../../../../../../../../shared/services/metadata/meta-data-parser.service";
import { stringConstants } from "../../../../../../../../../common-constants";
import { ServiceInfo } from "../../../../../../../../../../../fields/selector/selector.component";
import { LoadingContentState, toLoadingState } from "../../../../../../../../shared/rxjs-extensions/toLoadingState";
import { DataItem, TotalCountResult } from "../../../../../../../../content/dynamic-modules/interfaces";
import { SortService } from "../../../../../../../../shared/services/sort.service";

export class GenericContentSelectorStrategy implements ContentSelectorStrategy {
    constructor(private dynamicItemsService: DynamicItemService, private context: SelectorContext, private entity: Entity, private sortService: SortService) {
    }

    getItems(info: ServiceInfo): Observable<LoadingContentState<TotalCountResult<DataItem[]>>> {
        if (!info.parentId) {

            // Pages are not split by providers for different Sitefinity sites, but by their SiteMapRoot
            if (this.entity.typeFullName === DYNAMIC_ITEMS_DEFINITIONS.PAGE_NODE.replace("#/definitions/", stringConstants.EMPTY_STRING)) {
                info.parentId = this.context.selectedSite.sitemapRootNodeId;
            }

            return this.getItemsFromService(info);
        } else {
            return this.getChildItemsFromService(info);
        }
    }

    getParent(item: DataItem): Observable<LoadingContentState<DataItem>> {
        const requestData = this.getItemRequestData();
        requestData.itemKey = item.parentKey;
        return this.dynamicItemsService.getItem(requestData).pipe(toLoadingState());
    }

    /**UX requirement first 100 children should be loaded until new better UX*/
    private getChildItemsFromService(info: ServiceInfo, previousResponse: LoadingContentState<TotalCountResult<DataItem[]>> = null): Observable<LoadingContentState<TotalCountResult<DataItem[]>>> {
        info.take = CHILD_LOAD_COUNT;
        return this.getItemsFromService(info).pipe(filter(x => !x.isLoading), mergeMap(response => {
            if (response.content.dataItems.length > 0) {
                if (previousResponse) {
                    previousResponse.content.dataItems = previousResponse.content.dataItems.concat(response.content.dataItems);
                    previousResponse.content.totalCount = response.content.totalCount;
                } else {
                    previousResponse = response;
                }

                if (previousResponse.content.dataItems.length < CHILD_LOAD_COUNT && info.skip + previousResponse.content.dataItems.length < previousResponse.content.totalCount) {
                    info.skip = previousResponse.content.dataItems.length;

                    // by default ODATA have limit on the items that are returned per
                    // request so we need to make recursive calls to the service
                    return this.getChildItemsFromService(info, previousResponse);
                } else {
                    return observableOf(previousResponse);
                }
            } else {
                return previousResponse ? observableOf(previousResponse) : observableOf(response);
            }
        }));
    }

    private getItemsFromService(info: ServiceInfo): Observable<LoadingContentState<TotalCountResult<DataItem[]>>> {
        const requestData = this.getAllItemsRequestData();
        const filter = this.getFilter(info.searchText, info.parentId);
        requestData.filter = filter;
        requestData.skip = info.skip;
        requestData.take = info.take;
        return this.dynamicItemsService
            .getItemList(requestData).pipe(
                map(response => {
                    return <TotalCountResult<DataItem[]>>{ dataItems: response.dataItems, totalCount: response.totalCount };
                }),
                toLoadingState<TotalCountResult<DataItem[]>>()
            );
    }

    private getFilter(searchText: string, parentId: string): ExtendedKeyValuePair[] {
        if (searchText) {
            return [{ key: this.entity.defaultFieldName, value: [searchText] }];
        } else if (parentId) {
            return [{ key: this.entity.parentIdProperty, value: [parentId], operation: Operation.eq }];
        } else {
            return null;
        }
    }

    private getAllItemsRequestData(): LoadItemsData {
        const entityData = {
            metadata: this.entity,
            culture: this.context.selectedCulture.value,
            provider: this.context.selectedProvider.value
        };

        return <LoadItemsData>{
            entityData,
            fallbackProperties: [this.entity.defaultFieldName],
            order: this.sortService.getDefaultSort(entityData),
            siteId: this.context.selectedSite.value // required for pages as they have the same provider for all sites, Sitefinity filters them based on the current site context
        };
    }

    private getItemRequestData(): LoadItem {
        return <LoadItem>{
            entityData: {
                metadata: this.entity,
                culture: this.context.selectedCulture.value,
                provider: this.context.selectedProvider.value
            }
        };
    }
}
