import { combineLatest as observableCombineLatest,  timer } from "rxjs";
import { Component, Input, OnInit } from "@angular/core";
import { EntityData } from "../../interfaces";
import { ActivatedRoute } from "@angular/router";
import { FILTER_PARAMS, LOADING_TIME } from "../../../constants";
import { FilterStore } from "./filter/filter.store";
import { FilterData, FiltersResult, CustomFilterProperties } from "./filter/filter-interfaces";
import { ReplaySubject, Observable, Subscription } from "rxjs";
import { ContentFilterService } from "../../../../shared/services/content-filter.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    templateUrl: "./custom-filter-sidebar.component.html"
})
export class CustomFilterSidebarComponent extends SfRxBase implements OnInit {
    @Input() entityData$: Observable<EntityData>;
    @Input() onFilterSelect: (name: string) => void;

    dateRangeType: string = "date-range";
    isLoading: boolean = true;
    filterProperties$ = new ReplaySubject<CustomFilterProperties[]>(1);

    private entityData: EntityData;
    private currentFilters = {};
    private readyFilters = {};
    private readyFilters$ = new ReplaySubject<boolean>(1);
    private loadingSubscription: Subscription;
    private currentQueryString: string;
    private filtersSubscription: Subscription;
    private paramsSubsription: Subscription;

    constructor(private filterStore: FilterStore,
                private filterService: ContentFilterService,
                private route: ActivatedRoute) {
        super();
    }

    ngOnInit(): void {
        const subscription = this.entityData$.subscribe(entityData => {
            const isInitialize = !this.entityData;
            if (isInitialize || this.entityData.provider !== entityData.provider || this.entityData.culture !== entityData.culture) {
                this.isLoading = true;
                this.entityData = entityData;
                this.parseQueryParameters();
                this.loadFilters();
            }
        });

        this.registerSubscription(subscription);
    }

    onFilter(filterData: FilterData) {
        if (filterData.name) {
            this.currentFilters[filterData.name] = filterData.keys;
            this.currentQueryString = this.filterService.serializeQueryParams(this.currentFilters);

            if (this.onFilterSelect) {
                this.onFilterSelect(this.currentQueryString);
            }
        }
    }

    onFilterReady(filterName: string) {
        this.readyFilters[filterName] = true;
        if (Object.keys(this.readyFilters).length === Object.keys(this.currentFilters).length) {
            this.readyFilters$.next(true);
        }
    }

    private loadFilters() {
        if (this.filtersSubscription) {
            this.filtersSubscription.unsubscribe();
        }

        this.filtersSubscription = this.filterStore.getCustomFilters(this.entityData)
            .subscribe((filterResult: FiltersResult) => {
                let filterProperties: CustomFilterProperties[] = null;
                if (!filterResult.isLoading && filterResult.filters) {
                    filterProperties = filterResult.filters.map(f => ({
                        filterName: f.name,
                        filterTitle: f.title,
                        entityData: this.entityData,
                        parameters: f.parameters
                    }));
                }

                this.filterProperties$.next(filterProperties);
            });

        this.registerSubscription(this.filtersSubscription);
    }

    private parseQueryParameters() {
        if (this.paramsSubsription) {
            this.paramsSubsription.unsubscribe();
        }

        this.paramsSubsription = this.route.queryParams.subscribe(queryParams => {
            const filterParam = queryParams[FILTER_PARAMS.FILTER];
            if (this.currentQueryString && filterParam && filterParam === this.currentQueryString) {
                return;
            }

            this.currentQueryString = filterParam;

            this.currentFilters = {};
            this.readyFilters = {};
            if (filterParam) {
                this.isLoading = true;
                const pairs = this.filterService.deserializeQueryParams(filterParam);
                pairs.forEach(pair => {
                    if (pair.value && pair.value.length) {
                        this.currentFilters[pair.key] = pair.value;
                    }
                });
            }

            this.initLoadingSubscription();

            if (Object.keys(this.currentFilters).length === 0) {
                this.readyFilters$.next(true);
            }
        });

        this.registerSubscription(this.paramsSubsription);
    }

    private initLoadingSubscription() {
        if (this.loadingSubscription) {
            this.loadingSubscription.unsubscribe();
        }

        this.readyFilters$.next(false);
        this.loadingSubscription = observableCombineLatest(this.readyFilters$, this.filterProperties$, timer(LOADING_TIME)).subscribe(data => {
            if (data[0] && data[1]) {
                this.isLoading = false;
            }
        });

        this.registerSubscription(this.loadingSubscription);
    }
}
