import { Observable, BehaviorSubject, Subject, ReplaySubject, of } from "rxjs";

import { map, first } from "rxjs/operators";
import { Injectable } from "@angular/core";

import { MediaService } from "./media.service";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { FILTER_PARAMS } from "../../content/constants";
import { MEDIA_PROPERTIES } from "./media.helpers";

const DEFAULT_RECENT_LIBRARIES_COUNT = 5;
const PAGE_SIZE = 50;
const PREVIEW_ITEMS_PROPERTY = "PreviewItems";

@Injectable()
export class LibraryStore {
    libraries = new BehaviorSubject<DataItem[]>([]);
    recentFiles = new ReplaySubject<DataItem[]>(1);
    files = new ReplaySubject<DataItem[]>(1);
    folders = new BehaviorSubject<DataItem[]>([]);

    totalFolders = Infinity;
    totalFiles = Infinity;
    totalRecentFiles = Infinity;
    totalLibraries = Infinity;

    private libraryId: string;
    private isLoadMorePending = false;

    constructor(private mediaService: MediaService) {
    }

    getFoldersAndContent(mediaEntityData: EntityData, folderId: string, take: number, dataFieldNames?: string[], queryParams?: { [key: string]: string }, recursive?: boolean, skip?: number, searchTerm?: string, skipFoldersOnFilter?: boolean, getMediaItems?: boolean, skipFolders?: boolean, useLiveData?: boolean): Observable<[DataItem[], DataItem[]]> {
        this.isLoadMorePending = false;
        this.libraryId = folderId;
        this.files.next([]);
        const result: Subject<[DataItem[], DataItem[]]> = new Subject<[DataItem[], DataItem[]]>();

        if (this.libraryId !== null) {
            if (skip > 0 && skip >= this.totalFolders) {
                if (skip < this.totalFiles || this.totalFiles === undefined) {
                    this.getLibraryFiles(mediaEntityData, skip, take, dataFieldNames, folderId, queryParams, recursive, false, searchTerm, useLiveData).subscribe(filesData => {
                        this.files.next(filesData);
                        result.next([[], filesData]);
                        result.complete();
                    });
                }
            } else {
                this.getLibraryFolders(mediaEntityData, 0, take, searchTerm, undefined, undefined, undefined, queryParams, skipFoldersOnFilter, undefined, getMediaItems, skipFolders).subscribe(foldersData => {
                    this.folders.next(foldersData);

                    const filesToTake = foldersData.length === take ? 0 : take - foldersData.length;
                    const forceNoTake = (filesToTake === 0 && !recursive) ? true : false;
                    const files$ = searchTerm ?
                        this.searchForFiles(mediaEntityData, searchTerm, skip, filesToTake, useLiveData) :
                        this.getLibraryFiles(mediaEntityData, skip, filesToTake, dataFieldNames, folderId, queryParams, recursive, forceNoTake, undefined, useLiveData);

                    // Call should be made always to update totalFilesCount
                    files$.subscribe(filesData => {
                        this.files.next(filesData);
                        result.next([foldersData, filesData]);
                        result.complete();
                    });
                });
            }
        }

        return result;
    }

    loadRecentFiles(mediaEntityData: EntityData, searchTerm: string, take: number, queryParams?: { [key: string]: string }, skip?: number, useLiveData?: boolean): Observable<DataItem[]> {
        const observable = searchTerm
            ? this.searchForRecentFiles(mediaEntityData, searchTerm, skip, take, useLiveData)
            : this.getRecentFiles(mediaEntityData, skip, take, queryParams, useLiveData);

        return observable.pipe(map(data => {
            this.recentFiles.next(data);
            return data;
        }));
    }

    loadLibraries(mediaEntityData: EntityData, searchTerm: string, take: number, libraryId: string = this.libraryId, queryParams?: { [key: string]: string }, getMediaItems?: boolean, useLiveData?: boolean) {
        if (!libraryId && !searchTerm) {
            this.libraryId = libraryId;
            this.libraries.next([]);
            this.isLoadMorePending = false;
            // Load the libraries unless browsing a library or searching
            this.loadLibrariesAndSiblingPhotos(mediaEntityData, take, searchTerm, queryParams, getMediaItems, useLiveData);
        }
    }

    loadMore(mediaEntityData: EntityData, searchTerm: string, take: number, recursive: boolean = false, includeParent: boolean = false, libId = this.libraryId, queryParams: { [key: string]: string } = null, getMediaItems: boolean = false, dataFieldNames: string[] = []) {
        this.libraryId = libId;

        const folders = this.folders.getValue();
        let skip: number = 0;
        if (this.isLoadMorePending) {
            return;
        }
        this.isLoadMorePending = true;
        if (!this.libraryId) {
            if (searchTerm) {
                return this.loadLibrariesAndSiblingPhotos(mediaEntityData, take, searchTerm, queryParams, getMediaItems);
            }

            const libraries = this.libraries.getValue();
            const skip = libraries.length;
            if (skip >= this.totalFolders) {
                return;
            }

            return this.getLibraryFolders(mediaEntityData, skip, take, searchTerm, undefined, undefined, undefined, queryParams, undefined, undefined, getMediaItems).pipe(first()).subscribe(data => {
                const newFolders = libraries.concat(data);
                this.libraries.next(newFolders);
            });
        }

        if (this.libraryId) {
            skip = folders.length;

            if (skip >= this.totalFolders) {
                return this.loadFiles(mediaEntityData, searchTerm, take, queryParams, dataFieldNames);
            }

            return this.getLibraryFolders(mediaEntityData, skip, take, searchTerm, this.libraryId, recursive, includeParent, queryParams, undefined, undefined, getMediaItems).pipe(first()).subscribe(data => {
                const newFolders = folders.concat(data);
                if (folders.length !== newFolders.length) {
                    this.folders.next(newFolders);
                }
                this.isLoadMorePending = false;
                const filesToTake = data.length === take ? 0 : take - data.length;
                if (this.totalFolders <= newFolders.length && filesToTake > 0) {
                    this.loadFiles(mediaEntityData, searchTerm, filesToTake, queryParams, dataFieldNames);
                } else {
                    this.files.next([]);
                }
            });
        }
    }

    loadMoreRecent(mediaEntityData: EntityData, searchTerm: string, take: number, queryParams: { [key: string]: string } = null, skipValidation: boolean = false): Observable<DataItem[]> {
        let oldData = [];
        const subscription = this.recentFiles.subscribe(x => {
            oldData = x;
        });
        subscription.unsubscribe();
        //// TODO: investigate why we need this oldData.length % PAGE_SIZE === 0
        if (oldData.length % PAGE_SIZE === 0 || skipValidation) {
            const filesObservable = this.getLibraryFiles(mediaEntityData, oldData.length, take, undefined, null, queryParams, false, false, searchTerm);
            filesObservable.subscribe(data => {
                this.recentFiles.next(oldData.concat(data));
            });
            return filesObservable;
        }
    }

    search(mediaEntityData: EntityData, searchTerm: string, take: number, getMediaItems: boolean = false, includeParent: boolean = true, libraryId?: string) {
        this.folders.next([]);
        this.files.next([]);
        this.libraries.next([]);

        this.totalFolders = Infinity;
        this.totalFiles = Infinity;
        this.totalRecentFiles = Infinity;
        this.totalLibraries = Infinity;
        this.loadMore(mediaEntityData, searchTerm, take, true, includeParent, libraryId, undefined, getMediaItems);
    }

    searchRecent(mediaEntityData: EntityData, searchTerm: string, take: number, useliveData?: boolean, libraryId?: string) {
        this.searchForRecentFiles(mediaEntityData, searchTerm, undefined, take, useliveData, libraryId).pipe(first()).subscribe(data => this.recentFiles.next(data));
    }

    uploadFiles(mediaEntityData: EntityData, field: string, files: any[], parentId: string, folderId: string, directUpload: boolean = false, operationName: string = OPERATION_NAMES.publish, getItemAfterUpload: boolean = true) {
        const dataItem = DataItem.emptyItem(mediaEntityData);
        this.mediaService.upload(dataItem, field, files, parentId, folderId, directUpload, operationName, getItemAfterUpload);
    }

    getThumbnails(mediaEntityData: EntityData, fileSrc: string): Observable<any> {
        return this.mediaService.getThumbnails(mediaEntityData, fileSrc);
    }

    getFoldersByParentId(mediaEntityData: EntityData, parentId: string, take: number = DEFAULT_RECENT_LIBRARIES_COUNT, recursive: boolean = false, includeParent: boolean = false, searchTerm: string = null, queryParams: { [key: string]: string } = null, filterByCreateChildPermissions = false, getMediaItems: boolean = false): Observable<DataItem[]> {
        return this.getLibraryFolders(mediaEntityData, 0, take, searchTerm, parentId, recursive, includeParent, queryParams, undefined, filterByCreateChildPermissions, getMediaItems).pipe(
            map(result => {
                this.libraries.next(result);
                return result;
            })
        );
    }

    getFolderById(mediaEntityData: EntityData, folderId: string): Observable<DataItem> {
        return this.mediaService.getFolderById(mediaEntityData, folderId, mediaEntityData.metadata.selectedProvider || mediaEntityData.provider, null).pipe(
            map(result => {
                this.totalFolders = result.data.error ? 0 : 1;

                return result;
            })
        );
    }

    getLibraryFolders(mediaEntityData: EntityData, skip?: number, take?: number, searchTerm?: string, libraryId: string = this.libraryId, recursive?: boolean, includeParent?: boolean, queryParams?: { [key: string]: string }, skipFoldersOnFilter?: boolean, filterByCreateChildPermissions?, getMediaItems?: boolean, skipFolders?: boolean, useLiveData?: boolean): Observable<DataItem[]> {
        if ((queryParams && queryParams[FILTER_PARAMS.FILTER] && skipFoldersOnFilter) || skipFolders) {
            this.totalFolders = 0;
            return of([]);
        }

        const entityData: EntityData = {
            metadata: mediaEntityData.metadata,
            culture: mediaEntityData.culture,
            provider: mediaEntityData.metadata.selectedProvider || mediaEntityData.provider
        };

        return this.mediaService.getFolders(entityData, libraryId, recursive, includeParent, skip, take, null, searchTerm, queryParams, filterByCreateChildPermissions, undefined, getMediaItems, useLiveData).pipe(
            map(result => {
                this.totalFolders = result.totalCount;
                this.isLoadMorePending = false;

                return result.dataItems.map(item => {
                    const element = {
                        Items: item.data[PREVIEW_ITEMS_PROPERTY],
                        TotalItems: item.data[MEDIA_PROPERTIES.CHILDREN_COUNT],
                        TotalFolders: item.data[MEDIA_PROPERTIES.FOLDERS_COUNT]
                    };

                    return DataItem.fromEntityData({ ...item.data, ...element }, item);
                });
            })
        );
    }

    getMediaFileLinks(dataItem: DataItem, getForCurrentFile: boolean = false): Observable<any> {
        return this.mediaService.getMediaFileLinks(dataItem, getForCurrentFile);
    }

    private loadLibrariesAndSiblingPhotos(mediaEntityData: EntityData, take: number, searchTerm?: string, queryParams?: { [key: string]: string }, getMediaItems?: boolean, useLiveData?: boolean) {
        const libraries = this.libraries.getValue();
        const skip = libraries.length;

        return this.getLibraryFolders(mediaEntityData, skip, take, searchTerm, undefined, undefined, undefined, queryParams, undefined, undefined, getMediaItems, undefined, useLiveData).pipe(first()).subscribe(data => {
            const newFolders = libraries.concat(data);
            this.libraries.next(newFolders);
            if (this.totalFolders <= newFolders.length) {
                this.loadFiles(mediaEntityData, searchTerm, 50, queryParams);
            } else {
                this.files.next([]);
            }
        });
    }

    private loadFiles(mediaEntityData: EntityData, searchTerm: string, take: number, queryParams: { [key: string]: string } = null, dataFieldNames: string[] = []) {
        let oldData: DataItem[] = [];
        this.files.subscribe(x => {
            oldData = x;
        }).unsubscribe();

        const skip = oldData.length;

        if (!this.totalFiles || skip < this.totalFiles) {
            const observable = searchTerm ? this.searchForFiles(mediaEntityData, searchTerm, skip, take) : this.getLibraryFiles(mediaEntityData, skip, take, dataFieldNames, undefined, queryParams);

            observable.pipe(first()).subscribe(data => {
                this.files.next(oldData.concat(data));
                this.isLoadMorePending = false;
            });
        }
    }

    private searchForFiles(mediaEntityData: EntityData, searchTerm: string, skip?: number, take?: number, useLiveData?: boolean): Observable<DataItem[]> {
        const dataItem = DataItem.emptyItem(mediaEntityData);

        return this.mediaService.search(dataItem, searchTerm, skip, take, this.libraryId, useLiveData).pipe(
            map(result => {
                this.totalFiles = result.totalCount;
                this.totalRecentFiles = result.totalCount;
                this.isLoadMorePending = false;
                return result.dataItems;
            }));
    }

    private searchForRecentFiles(mediaEntityData: EntityData, searchTerm: string, skip?: number, take?: number, useLiveData?: boolean, libraryId?: string): Observable<DataItem[]> {
        const dataItem = DataItem.emptyItem(mediaEntityData);

        return this.mediaService.search(dataItem, searchTerm, skip, take, libraryId, useLiveData).pipe(
            map(result => {
                this.totalRecentFiles = result.totalCount;
                this.isLoadMorePending = false;
                return result.dataItems;
            }));
    }

    private getLibraryFiles(mediaEntityData: EntityData, skip?: number, take?: number, dataFieldNames?: string[], libraryId: string = this.libraryId, queryParams?: { [key: string]: string }, recursive?: boolean, forceNoTake?: boolean, searchTerm?: string, useLiveData?: boolean): Observable<DataItem[]> {
        const dataItem = DataItem.emptyItem(mediaEntityData);

        return this.mediaService.getMediaForLibrary(dataItem, libraryId, skip, take, null, dataFieldNames, queryParams, recursive, forceNoTake, searchTerm, useLiveData).pipe(
            map(result => {
                this.totalFiles = result.totalCount;
                this.totalRecentFiles = this.totalFiles;
                this.isLoadMorePending = false;
                return result.dataItems;
            }));
    }

    private getRecentFiles(mediaEntityData: EntityData, skip?: number, take?: number, queryParams?: { [key: string]: string }, useLiveData?: boolean): Observable<DataItem[]> {
        const dataItem = DataItem.emptyItem(mediaEntityData);
        return this.mediaService.getRecentMedia(dataItem, skip, take, queryParams, useLiveData).pipe(
            map(result => {
                this.totalRecentFiles = result.totalCount;

                return result.dataItems;
            }));
    }
}
