import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject, OperatorFunction, ObservedValueOf, throwError } from "rxjs";
import { DataItem, EntityData } from "../../../interfaces";
import { ModalWindowService, DialogData, ClosingContext, Button, ClickResult, ConfirmButton, CancelButton } from "../../../../../shared/services/modal-window.service";
import { DynamicItemStore } from "../../dynamic-item.store";
import { OPERATION_NAMES, OPERATION_TITLES } from "../../../../../shared/components/action-menu/operation.model";
import { ActivatedRoute } from "@angular/router";
import { BulkOperationResult, SUCCESSFUL_NOTIFFICATION_TIME } from "./bulk-command";
import { AssignTaxonsComponent, ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME } from "../../../components/bulk-operations/assign-taxons.component";
import { createQuery } from "../../../../../../services/query";
import { UpdateItem } from "../../dynamic-item.service";
import { CommandNotificationArgs, HasNotificationCommand } from "../../../../../shared/commands/has-notification-command";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { BulkOperationsNotificationComponent } from "../../../components/bulk-operations/bulk-operations-notification.component";
import { NotificationService } from "../../../../../shared/services/notification/notification.service";
import { filterDuplicates } from "../../../../../../utils";
import { catchError } from "rxjs/operators";
import { NeedsAdditionalFieldsCommand } from "../../../../../shared/commands/needs-addtional-fields-command";
import { Properties } from "../../../../../shared/fields.constants";
import { FieldTypes } from "../../../../../shared/fields-builder/services/fields-registry";
import { MetadataParserService } from "../../../../../shared/services/metadata/meta-data-parser.service";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { ResponseError } from "../../../../../shared/services/errors/response-error";
import { ENTITY_SET } from "../../../../../shared/services/metadata/meta-data-constants";

export class AssignTaxonsCommand implements ExecuteOnceInBulkCommand, HasNotificationCommand, NeedsAdditionalFieldsCommand {
    executeOnceInBulk: boolean = true;
    private result: ReplaySubject<BulkOperationResult> = new ReplaySubject<BulkOperationResult>(1);
    private dialogBadgeItemsCount: ReplaySubject<string> = new ReplaySubject<string>(1);

    constructor(private modalWindowService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        private notificationService: NotificationService,
        private notificationFilter: string,
        private metadataParserService: MetadataParserService
    ) { }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        const entityData = context.data.selectedItems[0];
        if (!context.data.allItemsSelected) {
            let query: any = createQuery();

            if (entityData.metadata.hasParent) {
                query = query.expand("Parent($select=Title)");
            }

            query = query.where().or();

            context.data.selectedItems.forEach((selectedItem: DataItem) => {
                query = query.eq(entityData.metadata.key, selectedItem.key);
            });

            query = query.done().done();

            this.dynamicItemStore.getItemList({
                entityData: entityData,
                query,
                dataFieldNames: [entityData.metadata.key].concat(this.getAdditionalFieldsNames(entityData))
            })
                .pipe(this.addErrorToResultAndRethrow(this.result), this.catchErrorAndShowNotification())
                .subscribe(response => {
                    this.openDialog(this.filterNotTranslatedItems(response.dataItems), context.data.action.detailedTitle, context.currentRoute, entityData);
                });
        } else {
            this.openDialog(this.filterNotTranslatedItems(context.data.selectedItems), context.data.action.detailedTitle, context.currentRoute, entityData);
        }

        return this.result.asObservable();
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!succeededItems && !failedItems) {
            return null;
        }

        const operationPartiallySucceeded: boolean = succeededItems && succeededItems.length > 0 && failedItems && failedItems.length > 0;
        const operationFailed: boolean = !operationPartiallySucceeded && failedItems && failedItems.length > 0;
        const operationSucceeded: boolean = !operationPartiallySucceeded && succeededItems && succeededItems.length > 0;

        const notificationData: NotificationData = {
            type: BulkOperationsNotificationComponent,
            properties: {
                succeededItemsIds: succeededItems,
                failedItemsIds: failedItems,
                entityData: args.entityData,
                operationName: "update"
            },
            id: "bulkOperationsNotification",
            look: NOTIFICATION_LOOKS.SUCCESS
        };

        if (operationSucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            notificationData.duration = SUCCESSFUL_NOTIFFICATION_TIME;
        } else if (operationFailed) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            notificationData.closeButton = true;
        } else if (operationPartiallySucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.WARNING;
            notificationData.closeButton = true;
        }

        return notificationData;
    }

    getAdditionalFieldsNames(entityData: EntityData): string[] {
        const additionalFieldNames = [
            Properties.AvailableLanguages,
            Properties.TITLE
        ];

        if (this.canSetDisplayStatus(entityData)) {
            additionalFieldNames.push(Properties.DISPLAY_STATUS);
        }

        if (MediaHelpers.isMediaEntity(entityData)) {
            additionalFieldNames.push(Properties.THUMBNAIL_URL);
            additionalFieldNames.push(Properties.EXTENSION);
            additionalFieldNames.push(Properties.MIME_TYPE);
        }

        if (MediaHelpers.isImageEntity(entityData)) {
            additionalFieldNames.push(Properties.WIDTH);
            additionalFieldNames.push(Properties.HEIGHT);
        }

        if (MediaHelpers.isDocumentEntity(entityData)) {
            additionalFieldNames.push(Properties.TOTAL_SIZE);
            additionalFieldNames.push(Properties.LOCKED_STATUS);
        }

        if (MediaHelpers.isVideoEntity(entityData)) {
            additionalFieldNames.push(Properties.URL);
            additionalFieldNames.push(Properties.WIDTH);
            additionalFieldNames.push(Properties.HEIGHT);
        }

        Object.keys(entityData.metadata.properties).forEach(key => {
            const fieldType = this.metadataParserService.getPropertyFieldType(entityData.metadata, entityData.metadata.properties[key], null, key, null);
            if (fieldType === FieldTypes.taxa) {
                additionalFieldNames.push(key);
            }
        });

        return additionalFieldNames;
    }

    private filterNotTranslatedItems(items: DataItem[]) {
        return items.filter(x => x.isTranslated);
    }

    private openDialog(items: DataItem[], title: string, route: ActivatedRoute, entityData: EntityData): void {
        const componentData = {
            type: AssignTaxonsComponent,
            properties: {
                items,
                fieldNames: this.getAdditionalFieldsNames(entityData),
                superScript: this.dialogBadgeItemsCount
            }
        };

        let buttons: Button[] = [];
        if (items.length > 0) {

            if (!entityData.metadata.hasLifecycle || entityData.metadata.setName === ENTITY_SET.CONTENT_ITEMS) {
                buttons = this.getButtonsForNonLifecycleType(items, entityData);
            } else {
                buttons = this.getButtonsForLifecycleType(items, entityData);
            }
        }

        const dialogData = new DialogData(componentData, (closingContext: ClosingContext) => {
            const contextData = closingContext.data;
            if (contextData && contextData.data) {
                this.result.next({ success: true });
            } else {
                this.result.next({ success: false });
            }
        }, buttons, null, "-bottom");

        dialogData.heading = { title };
        this.dialogBadgeItemsCount.next(items.length.toString());

        this.modalWindowService.setMapping(dialogData, OPERATION_NAMES.assignTaxons);
        this.modalWindowService.open(route, OPERATION_NAMES.assignTaxons);
    }

    private catchErrorAndShowNotification<T, O>(): OperatorFunction<T, T | ObservedValueOf<O>> {
        return this.notificationService.catchErrorAndShowNotification(this.notificationFilter);
    }

    private addErrorToResultAndRethrow<T, O>(result: ReplaySubject<BulkOperationResult>): OperatorFunction<T, T | ObservedValueOf<O>> {
        return catchError((err) => {
            result.next({ success: false });
            return throwError(err);
        });
    }

    onSaveClicked(component: AssignTaxonsComponent, items: DataItem[], entityData: EntityData, operation?: string): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        const fields = component.editableFieldsComponent.getFields();
        const taxaFields = fields ? Object.keys(fields).filter(x => x !== ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME) : [];

        if (taxaFields.length > 0) {

            let itemsToUpdate = items;
            if (fields[ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME]) {
                itemsToUpdate = fields[ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME];
            }

            if (itemsToUpdate.length > 0) {
                // Trigger loading in the confirm button
                clickResult.next(new ClickResult(true, false));

                const updateItems: UpdateItem[] = [];
                const lockItems: UpdateItem[] = [];
                itemsToUpdate.forEach(item => {
                    const data = {};
                    taxaFields.forEach(key => {
                        data[key] = filterDuplicates(item.data[key].concat(fields[key]));
                    });

                    const updateItem: UpdateItem = {
                        dataItem: item,
                        doNotRefreshItem: true,
                        data,
                        operation: { action: operation }
                    };

                    const lockItem: UpdateItem = {
                        dataItem: item,
                        doNotRefreshItem: true,
                        data: {}
                    };

                    updateItems.push(updateItem);
                    lockItems.push(lockItem);
                });

                // lock the items first
                this.dynamicItemStore.service.updateItemsWithBulkOperationResult(lockItems, entityData)
                    .pipe(this.addErrorToResultAndRethrow(this.result), this.catchErrorAndShowNotification())
                    .subscribe(result => {
                        this.dynamicItemStore.service.updateItemsWithBulkOperationResult(updateItems, entityData)
                            .pipe(this.addErrorToResultAndRethrow(this.result), this.catchErrorAndShowNotification())
                            .subscribe((operationResult: BulkOperationResult) => {
                                this.result.next(operationResult);
                                clickResult.next(new ClickResult(operationResult, true, false));
                            }, (error: ResponseError) => {
                                this.result.error("An error occured while trying to update items.");
                                clickResult.next(new ClickResult(error, false, true));
                            });
                    });
            }
        }

        return clickResult;
    }

    private getButtonsForLifecycleType(items: DataItem[], entityData: EntityData): Button[] {
        let lifecycleTypeButtons: Button[] = [];
        lifecycleTypeButtons = [
            new ConfirmButton(OPERATION_TITLES.publish,
                (data) => this.onSaveClicked(data.component, items, entityData, OPERATION_TITLES.publish), "action large"),
            new ConfirmButton(OPERATION_TITLES.saveDraft,
                (data) => this.onSaveClicked(data.component, items, entityData, OPERATION_NAMES.defaultWorkflowOperation),
                "large",
                null,
                "color"),
            new CancelButton()
        ];

        return lifecycleTypeButtons;
    }

    private getButtonsForNonLifecycleType(items: DataItem[], entityData: EntityData): Button[] {
        let nonLifecycleTypeButtons: Button[] = [];
        const operation = entityData.metadata.setName === ENTITY_SET.CONTENT_ITEMS ? OPERATION_NAMES.defaultWorkflowOperation : OPERATION_NAMES.edit;
        nonLifecycleTypeButtons = [
            new ConfirmButton(OPERATION_TITLES.saveChanges,
                (data) => this.onSaveClicked(data.component, items, entityData, operation), "action large"),
            new CancelButton()
        ];

        return nonLifecycleTypeButtons;
    }

    private canSetDisplayStatus(entityData: EntityData) {
        const canSetDisplayStatus = entityData.metadata.setName !== ENTITY_SET.CONTENT_ITEMS && entityData.metadata.setName !== ENTITY_SET.BLOGS && entityData.metadata.setName !== ENTITY_SET.LISTS;
        return canSetDisplayStatus;
    }
}
