import { Component, Input, OnInit } from "@angular/core";
import { EntityData } from "../../../../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { map } from "rxjs/operators";
import { Observable, ReplaySubject } from "rxjs";
import { CloseModalCallback } from "../../../../shared/services/modal-window.service";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";

@Component({
    templateUrl: "./change-template.component.html"
})
export class ChangeTemplateComponent implements OnInit, CloseModalCallback {
    @Input() entityData: EntityData;
    @Input() selectedPagesIds: string[] = [];
    @Input() onTemplateSelectionCallback: (templateId: string, mode: ChangeMode, templateName: string) => void;

    viewModel: ViewModel;
    changeMode: ChangeMode;
    templateCategories: Observable<TemplateCategory[]>;
    count: ReplaySubject<string> = new ReplaySubject<string>(1);

    private _closeModalCallback: (data: any) => void;

    constructor(private readonly dynamicItemStore: DynamicItemStore) {}

    public showTemplateCounter(template: Template): boolean {
        return template.Id !== "00000000-0000-0000-0000-000000000000" || template.Name ? true : false;
    }

    ngOnInit() {
        const isPages = this.entityData.metadata.setName === ENTITY_SET.PAGES;

        this.changeMode = this.determineChangeMode();
        this.viewModel = {
            Title: this.changeMode === ChangeMode.Create ? `Select a ${isPages ? "" : "base "}template` : `Change ${isPages ? "page" : "base"} template`,
            ShowNotification: this.changeMode === ChangeMode.Create ? false : true,
            NotificationMessage: isPages ?
                "Changing the template may break the layout of the page." :
                "Changing the base template may break the layout of this template and pages using it",
            ShowCounter: this.changeMode === ChangeMode.Bulk ? true : false,
            ShowItemTitle: this.changeMode === ChangeMode.Single ? true : false
        };

        this.loadTemplates();
    }

    setCloseModalCallback(closeModalCallback: (data: any) => void): void {
        this._closeModalCallback = closeModalCallback;
    }

    onTemplateSelection(templateId: string, templateName: string = ""): void {
        this.onTemplateSelectionCallback(templateId, this.changeMode, templateName);
        this._closeModalCallback({ templateId, changeMode: this.changeMode, templateName: templateName});
    }

    private loadTemplates() {
        const ids = this.selectedPagesIds.map(x => `'${x.toString()}'`).join(", ");

        if (this.viewModel.ShowCounter) {
            this.count.next(this.selectedPagesIds.length.toString());
        }

        // TODO: should be wrapped in a batch to avoid url length limitations. Currently this will not work for more than 7-8 items
        this.templateCategories = this.dynamicItemStore.getItemList({
            action: `Default.GetPageTemplates(selectedPages=[${ids}])`,
            entityData: this.entityData,
            dataFieldNames: []
        }).pipe(map(x => {
            const dataItems = x.dataItems;
            const templateCategories: TemplateCategory[] = dataItems.length > 0 ? dataItems.map(x => x.data) : [];

            this.handleSpecialCategories(templateCategories);

            return templateCategories.filter(x => x.Visible);
        }));
    }

    private handleSpecialCategories(templateCategories: TemplateCategory[]) {
        // coming from the .net core proxy, the category is a number rather than a string
        if (templateCategories.length > 0 && (templateCategories[0].Type === TemplateCategoryType.CurrentlyUsed || templateCategories[0].Type === 1)) {
            templateCategories[0].Templates[0].isSelected = true;
        }
    }

    private determineChangeMode() {
        switch (this.selectedPagesIds.length) {
            case 0:
                return ChangeMode.Create;
            case 1:
                return ChangeMode.Single;
            default:
                return ChangeMode.Bulk;
        }
    }
}

export enum ChangeMode {
    Single = "single",
    Bulk = "bulk",
    Create = "create"
}

interface Template {
    Id: string;
    Title: string;
    Name: string;
    ThumbnailUrl: string;
    UsedByNumberOfPages: number;
    isSelected?: boolean;
}

enum TemplateCategoryType {
    CurrentlyUsed = "CurrentlyUsed"
}

interface TemplateCategory {
    Title: string;
    Subtitle: string;
    Type: TemplateCategoryType;
    Templates: Template[];
    Visible: boolean;
}

interface ViewModel {
    Title: string;
    ShowNotification: boolean;
    NotificationMessage: string;
    ShowCounter: boolean;
    ShowItemTitle: boolean;
}
