import { map } from "rxjs/operators";
import { Observable } from "rxjs";
import { ColumnModel } from "../../../shared/models/column-model";
import { Injectable } from "@angular/core";
import { SiteData } from "../../../shared/services/metadata/site-data.store";
import { EntityData } from "../interfaces";
import { CompositeColumnsProvider } from "./columns-provider";

export enum ColumnOrdinals {
    main = Number.MIN_SAFE_INTEGER,
    marketing = ColumnOrdinals.main + 1,
    translations = ColumnOrdinals.marketing + 1
}

export const ACTIONS_COLUMN_NAME = "Actions";

/**
 * The purpose of this class is to add the columns that are not to be edited by the user. These 'system' columns will always be at specific positions
 * regarding of the custom columns the user has provided.
 */
@Injectable()
export class ColumnsGenerator {

    private sortingDisabledColumnNames: string[] = ["PublicationDate"];

    /**
     * Initializes a new instance of the ColumnsGenerator class.
     * @param columnsProvider The columns provider that will provide the columns to be displayed.
     */
    constructor(private columnsProvider: CompositeColumnsProvider) {

    }

    /**
     * Generates the columns and orders them appropriately.
     * @param entityName The entity for which to generate the columns.
     */
    generateColumns(entityData: EntityData, siteData: SiteData): Observable<Array<ColumnModel>> {
        const entity = entityData.metadata;

        return this.columnsProvider.getColumns(entityData).pipe(map((providerColumns) => {
            const columnsCopy: Array<ColumnModel> = [...providerColumns];
            const actionsColIndex = columnsCopy.findIndex(x => x.name === ACTIONS_COLUMN_NAME);

            if (actionsColIndex > -1 && actionsColIndex !== columnsCopy.length - 1) {
                const actionsCol = columnsCopy[actionsColIndex];

                columnsCopy.splice(actionsColIndex, 1);
                columnsCopy.push(actionsCol);
            }

            // TODO gabo: try handle on server.
            columnsCopy.forEach((column) => {
                if (!this.sortingDisabledColumnNames.find(x => x === column.name)) {
                    if (!column.sortableFieldName) {
                        column.sortableFieldName = entity.isSortingAllowed(column.name) ? column.name : null;
                    }
                } else {
                    column.sortableFieldName = null;
                }
            });

            return columnsCopy;
        }));
    }
}
