import { Router } from "@angular/router";
import { Settings } from "../../services/settings.service";
import { environmentTypes } from "../../../../environment";
import { SAME_TAB_TARGET } from "../../../../common-constants";
import { ROUTE_PATHS } from "../../../../constants/route-paths";
import { environment } from "../../../../../environments/environment";

export class ErrorPageBase {
    private settingsUrl: string;

    constructor(
        settings: Settings,
        private router: Router,
        private window: Window) {
            this.settingsUrl = settings.url;
    }

    onNavigateToHome() {
        const IRIS = this.getEnvironmentVariables();
        if (IRIS.ENV === environmentTypes.integration) {
            const url = `${this.settingsUrl}Sitefinity`;
            this.window.open(url, SAME_TAB_TARGET);
        } else {
            this.router.navigate([ROUTE_PATHS.HOME]);
        }
    }

    private getEnvironmentVariables(): any {
        return {
            ENV: environment.env
        };
    }
}
