
import { Directive, OnInit, Output, EventEmitter, ElementRef, OnDestroy, Input } from "@angular/core";
import { ResizeObserver, ResizeObserver as ResizePolyfill, ResizeObserverEntry } from "@juggle/resize-observer";
import { BehaviorSubject } from "rxjs";
import { debounceTime } from "rxjs/operators";

@Directive({
    selector: "[sfResize]"
})
export class ResizeDirective implements OnInit, OnDestroy {
    @Input() delay: number = 33;
    @Output() resize: EventEmitter<any> = new EventEmitter<any>();

    private resizeObserver;

    constructor(private element: ElementRef) {
    }

    ngOnInit() {
        // Uses native or polyfill, depending on browser support.
        const ResizeObserver = (window as any).ResizeObserver || ResizePolyfill;
        const subject = new BehaviorSubject<ResizeObserverResult>({entries: [], observer: null});

        this.resizeObserver = new ResizeObserver((entries: ResizeObserverEntry[], observer) => {
            const result: ResizeObserverResult = { entries, observer };
            subject.next(result);
        });

        this.resizeObserver.observe(this.element.nativeElement);
        subject.pipe(
            debounceTime(this.delay)
        ).subscribe(x => {
            const result = x.entries[0];
            if (result && result.contentRect.width > 0 && result.contentRect.height > 0) {
                this.resize.emit(result);
            }
        });
    }

    ngOnDestroy() {
        this.resizeObserver.unobserve(this.element.nativeElement);
    }
}

interface ResizeObserverResult {
    entries: Array<ResizeObserverEntry>;
    observer: ResizeObserver;
}
