import { fromEvent as observableFromEvent } from "rxjs";
import { Directive, OnInit, Output, EventEmitter, ElementRef, Inject } from "@angular/core";
import { DOCUMENT_TOKEN } from "../../../src/app/document.provider";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Directive({
    selector: "[sfClickOutside]"
})
export class ClickOutsideDirective extends SfRxBase implements OnInit {
    @Output() clickOutside: EventEmitter<MouseEvent> = new EventEmitter<MouseEvent>();

    constructor(private element: ElementRef, @Inject(DOCUMENT_TOKEN) private documentProvider: Document) {
        super();
    }

    ngOnInit() {
        const clickSubscription = observableFromEvent(this.documentProvider, "mousedown")
            .subscribe((event: MouseEvent) => {
                if (!this.element.nativeElement.contains(event.target)) {
                    this.clickOutside.emit(event);
                }
            });

        this.registerSubscription(clickSubscription);
    }
}
