import { Input, Component } from "@angular/core";
import { TreeConfig } from "../../../../../../fields";
import { BehaviorSubject } from "rxjs";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { ResultMapperBase } from "../modal-list/mappers/modal-list-mapper-base";

@Component({
    templateUrl: "./site-sync-notification.component.html"
})
export class SiteSyncNotificationComponent {
    @Input() action: string;
    @Input() count: BehaviorSubject<number>;
    @Input() treeConfig: TreeConfig = { noSelection: true };
    @Input() actionTitle: string;
    @Input() contentLook: string;
    @Input() modalListMapper: ResultMapperBase;

    public errorLabel = "Why?";

    onItemsLoaded(data) {
        if (data && data.GeneralErrors) {
            this.errorLabel = stringConstants.EMPTY_STRING;
        }
    }
}
