import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { SidebarConfig } from "../../shared/components/sidebar/sidebar.common";
import { of, ReplaySubject, combineLatest } from "rxjs";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { LoadItemsData } from "../../content/dynamic-modules/services/dynamic-item.service";
import { HierarchicalService } from "../../shared/services/hierarchical-service";
import { first, map } from "rxjs/operators";
import { Router } from "@angular/router";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { LibrariesNavigationSidebarComponent, LibrariesNavigationSidebarComponentProps } from "../sidebars/libraries-navigation/libraries-navigation-sidebar.component";
import { stringConstants } from "../../../common-constants";
import { hasValue } from "../../../utils";
import { SidebarSliderComponent, SidebarSliderAnimationData, SliderDirection } from "../../shared/components/sidebar/sidebar-slider/sidebar-slider.component";
import { SidebarComponentData } from "../../shared/components/sidebar/sidebar-component.repo";
import { SortService } from "../../shared/services/sort.service";
import { FILTER_PARAMS } from "../../content/constants";
import { ExternalAppConfigService } from "../../../app-config/external-app-config.service";

const ALL_LIBRARIES_TITLE = "All libraries";
export const LIBRARIES_NAVIGATION_SIDEBAR = "browseImageLibraries";
const CLEAR_ALL_ITEMS_LOADING_TIMEOUT = 700;
export interface LibraryMetadata {
    libraryMetadata: EntityData;

    mediaMetadata: EntityData;
}

export class LibrariresNavigationSidebarHelpers {
    totalCount: number;

    constructor(private sidebarConfig: SidebarConfig,
                private hierarchicalService: HierarchicalService,
                public libraryEntityData: EntityData,
                public mediaEntityData: EntityData,
                private router: Router,
                private slider$: ReplaySubject<SidebarSliderComponent>,
                private sortService: SortService,
                private externalAppConfigService: ExternalAppConfigService) { }

    getId(item: DataItem) {
        if (!item) {
            return null;
        }

        return item.key;
    }

    getParentId(item: DataItem) {
        if (!item || item.parentKey === stringConstants.DEFAULT_GUID) {
            return null;
        }

        return item.parentKey;
    }

    getSidebarBackButtonTitle(currentParent: DataItem, grandParent: DataItem) {
        if (!currentParent) {
            return `Browse ${this.mediaEntityData.metadata.singularName.toLowerCase()} libraries`;
        } else {
            return this.getParentTitle(grandParent);
        }
    }

    getGrandparent(parent: DataItem) {
        if (!parent || parent.parentKey === stringConstants.DEFAULT_GUID) {
            return of(null);
        }

        return this.getParent(parent.parentKey);
    }

    hasChildren(dataItem: DataItem) {
        return dataItem.data && dataItem.data.FoldersCount > 0;
    }

    getParentTitle(item: DataItem) {
        if (!item) {
            return ALL_LIBRARIES_TITLE;
        }

        return item.title;
    }

    hasBackNavigation(currentParent: DataItem) {
        if (hasValue(currentParent)) {
            return true;
        }

        return false;
    }

    loadItems(parentId: string, includeParent: boolean = false, skip?: number, take?: number) {
        const info: ServiceInfo = {
            parentId: parentId,
            includeParent
        };
        const entityData = parentId ? this.mediaEntityData : this.libraryEntityData;

        // metadata should be different for root and child level, so we can filter folders by permission
        const loadingData: LoadItemsData = {
            entityData,
            order: this.sortService.getDefaultSort(entityData)
        };

        if (hasValue(skip)) {
            loadingData.skip = skip;
        }

        if (hasValue(take)) {
            loadingData.take = take;
        }

        loadingData.payload = { skipFilterByCreateChildPermissions : true };

        return this.hierarchicalService.getSearchedItems(info, loadingData).pipe(
            first(),
            map(x => {
                this.totalCount = x.totalCount;
                return x.dataItems;
            })
        );
    }

    getParent(parentId: string) {
        if (!parentId || parentId === stringConstants.DEFAULT_GUID) {
            return of(null);
        }

        return this.hierarchicalService.getItemTaxa([parentId], this.libraryEntityData, null, false).pipe(map(x => x.dataItems[0]));
    }

    navigateToItem(item: DataItem, comp: LibrariesNavigationSidebarComponent) {
        const setName = this.mediaEntityData.metadata.setName;
        const url = [ROUTE_PATHS.CONTENT, setName, item.key, setName].join(stringConstants.FORWARD_SLASH);
        if (this.router.url.indexOf(url) !== -1) {
            this.onOpenChildItems(comp, item);
            return;
        }

        const queryParams = {
            [FILTER_PARAMS.SORT]: null
        };

        this.router.navigate([url], { queryParams, queryParamsHandling: "merge" });
    }

    loadMore() {
        this.slider$.pipe(first()).subscribe(slider => {
            const props = slider.getVisibleWindowComponentDataProps();
            props.currentLevelItems$.pipe(first()).subscribe(currentItems => {
                const skip = currentItems.length;
                if (skip >= this.totalCount) {
                    return;
                }

                let take = this.externalAppConfigService.externalConfig.mediaItemsPerPage;
                const notRetrievedItems = this.totalCount - currentItems.length;
                if (notRetrievedItems < take) {
                    take = notRetrievedItems;
                }

                props.currentRoot$.pipe(first()).subscribe(p => {
                    const parentId = this.getId(p);
                    this.loadItems(parentId, false, skip, take).pipe(first()).subscribe(i => {
                        props.currentLevelItems$.next([...currentItems, ...i]);
                    });
                });
            });
        });
    }

    onBackButtonClicked(comp: LibrariesNavigationSidebarComponent) {
        const allItemsLoading$ = this.getAllItemsLoading$();

        comp.currentRoot$.pipe(first()).subscribe(p => {
            const newParentId = this.getParentId(p);

            this.loadItems(newParentId, newParentId !== null).pipe(map(dataItems => {
                const newItems: DataItem[] = [];

                let newParent = null;
                for (const item of dataItems) {
                    if (item.key === newParentId) {
                        newParent = item;
                    } else {
                        newItems.push(item);
                    }
                }

                return { newItems, newParent };
            }))
                .subscribe(result => {
                    const { newParent, newItems } = result;

                    this.getGrandparent(newParent).subscribe(gp => {
                        this.slider$.pipe(first()).subscribe(sl => {
                            allItemsLoading$.next(false);
                            const sidebarTitle = this.getSidebarBackButtonTitle(newParent, gp);
                            const newCompData = this.getSliderAnimationData(newItems, newParent, this.getParentTitle(newParent), sidebarTitle, allItemsLoading$);
                            const sliderDirection = sl.sliderDirection === SliderDirection.left ? SliderDirection.leftInner : SliderDirection.left;
                            const animData: SidebarSliderAnimationData = {
                                slideDirection: sliderDirection,
                                componentData: newCompData
                            };

                            sl.animationData$.next(animData);
                        });
                    });
                });
        });
    }

    onOpenChildItems(comp: LibrariesNavigationSidebarComponent, item: DataItem) {
        comp.singleItemLoading = { itemId: item.key, loading: true };
        comp.currentRoot$.pipe(first()).subscribe(oldParent => {
            this.loadItems(item.key, false).subscribe(x => {
                combineLatest(
                    this.slider$.pipe(first()),
                    this.getGrandparent(item)
                )
                    .subscribe(([slider, grandParent]) => {
                        const sidebarTitle = this.getSidebarBackButtonTitle(item, grandParent);
                        const newCompData = this.getSliderAnimationData(x, item, this.getParentTitle(item), sidebarTitle, this.getAllItemsLoading$(false));
                        const sliderDirection = slider.sliderDirection === SliderDirection.right ? SliderDirection.rightInner : SliderDirection.right;

                        const animData: SidebarSliderAnimationData = {
                            slideDirection: sliderDirection,
                            componentData: newCompData
                        };

                        slider.animationData$.next(animData);
                    });
            });
        });
    }

    clearAllItemsLoading(allItemsLoading$: ReplaySubject<boolean>) {
        setTimeout(() => {
            allItemsLoading$.next(false);
        }, CLEAR_ALL_ITEMS_LOADING_TIMEOUT);
    }

    getSliderAnimationData(currentLevelItems: DataItem[], currentRoot: DataItem, title: string, backButtonTitle: string, allItemsLoading$: ReplaySubject<boolean>) {
        const newSidebarData: SidebarComponentData = {
            type: this.sidebarConfig.data.type,
            title: backButtonTitle,
            updatePropertiesOnChange: true,
            properties: {}
        };

        const currentLevelItems$ = new ReplaySubject<DataItem[]>(1);
        currentLevelItems$.next(currentLevelItems);

        const currentRoot$ = new ReplaySubject<DataItem>(1);
        currentRoot$.next(currentRoot);

        const currentRootTitle$ = new ReplaySubject<string>(1);
        currentRootTitle$.next(title);

        const hasBackNavigation$ = new ReplaySubject<boolean>(1);
        hasBackNavigation$.next(this.hasBackNavigation(currentRoot));

        const backButtonTitle$ = new ReplaySubject<string>(1);
        backButtonTitle$.next(backButtonTitle);

        const newProps: LibrariesNavigationSidebarComponentProps = {
            currentLevelItems$,
            currentRoot$,
            currentRootTitle$,
            sidebarHelpers: this,
            hasBackNavigation$,
            backButtonTitle$,
            allItemsLoading$
        };

        Object.assign(newSidebarData.properties, newProps);
        return newSidebarData;
    }

    private getAllItemsLoading$(isLoading = true) {
        const allItemsLoading$ = new ReplaySubject<boolean>(1);
        allItemsLoading$.next(isLoading);

        return allItemsLoading$;
    }
}
