import { MinLengthValidator, MIN_LENGTH_VALIDATOR_NAME } from "./min-length.validator";
import { ValueRangeValidator, VALUE_RANGE_VALIDATOR_NAME } from "./value-range.validator";
import { MultipleUrlsPatternValidator, URL_PATTERN_VALIDATOR_NAME } from "./url-pattern.validator";
import { DigitsLimit, DIGITS_LIMIT_VALIDATOR_NAME } from "./digits-limit.validator";
import { MaxInteger, SAFE_INTEGER_VALIDATOR_NAME } from "./max-integer.validator";
import { ValidatorFn } from "@angular/forms";
import { DATE_RANGE_VALIDATOR_NAME, DateRangeValidator } from "./date-range.validator";
import { SCHEDULE_VALIDATOR_NAME } from "./schedule.validator";
import { MULTILINE_EMAILS_NAME, MultilineEmailsValidator } from "./multiline-emails.validator";
import { JsonValidator, JSON_VALIDATOR_NAME } from "./json.validator";

export const VALIDATOR_NAMES = Object.freeze({
    MIN_LENGTH: MIN_LENGTH_VALIDATOR_NAME,
    VALUE_RANGE: VALUE_RANGE_VALIDATOR_NAME,
    URL_PATTERN: URL_PATTERN_VALIDATOR_NAME,
    DIGITS_LIMIT: DIGITS_LIMIT_VALIDATOR_NAME,
    MAX_INTEGER: SAFE_INTEGER_VALIDATOR_NAME,
    SCHEDULE: SCHEDULE_VALIDATOR_NAME,
    MULTILINE_EMAILS: MULTILINE_EMAILS_NAME,
    JSON: JSON_VALIDATOR_NAME,
    // angular default validators
    REQUIRED: "required",
    MAX_LENGTH: "maxlength",
    DATE_RANGE: DATE_RANGE_VALIDATOR_NAME,
    PATTERN: "pattern",
    MAX_VALUE: "maxValue",
    MIN_VALUE: "minValue",
    CUSTOM: "custom"
});

const validatorsCollection: { [key: string]: (value?: any) => ValidatorFn } = { };
validatorsCollection[VALIDATOR_NAMES.MIN_LENGTH] = MinLengthValidator.validate;
validatorsCollection[VALIDATOR_NAMES.VALUE_RANGE] = ValueRangeValidator.validate;
validatorsCollection[VALIDATOR_NAMES.URL_PATTERN] = MultipleUrlsPatternValidator.validate;
validatorsCollection[VALIDATOR_NAMES.DIGITS_LIMIT] = DigitsLimit.validate;
validatorsCollection[VALIDATOR_NAMES.MAX_INTEGER] = MaxInteger.validate;
validatorsCollection[VALIDATOR_NAMES.DATE_RANGE] = DateRangeValidator.validate;
validatorsCollection[VALIDATOR_NAMES.MULTILINE_EMAILS] = MultilineEmailsValidator.validate;
validatorsCollection[VALIDATOR_NAMES.JSON] = JsonValidator.validate;
export const VALIDATORS = Object.freeze(validatorsCollection);
