import { Injectable, Inject } from "@angular/core";

import { FormData, BackendTweaksStore } from "../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { Entity } from "./metadata/meta-data.store";
import { MetadataParserService } from "./metadata/meta-data-parser.service";
import { FieldModel } from "../../../services/field.model";
import { FieldSectionModel } from "../../../services/fieldSection.model";
import { stringConstants } from "./../../../common-constants";
import { FieldTypes, FieldRegistration } from "../fields-builder/services/fields-registry";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { VIEW_NAME } from "../../content/constants";
import { CustomTweaksHandler } from "./custom-tweaks-handler.service";
import { ENTITY_SET } from "./metadata/meta-data-constants";

@Injectable()
export class FieldsGeneratorService {
    constructor(private metadataParser: MetadataParserService,
                @Inject(CustomTweaksHandler) private tweaksHandlers: CustomTweaksHandler[]) { }

    public generateFields(metadata: Entity, tweaksStore: BackendTweaksStore, item: any = {}, readonly: boolean = false, onlyLocalizable: boolean = false): FieldSectionModel[] {
        const fields = this.generateFieldModels(metadata, metadata.setName, tweaksStore, item, readonly, onlyLocalizable);
        const viewName = item && !item.isEmpty ? VIEW_NAME.EDIT : VIEW_NAME.INSERT;
        const sections = this.groupFields(metadata, fields, tweaksStore.getFormByType(metadata.setName, viewName), readonly);
        return sections;
    }

    public generateFieldsFromTweaks(metadata: Entity, tweaks: FormData[], item: any = {}, readonly: boolean = false, onlyLocalizable: boolean = false): FieldSectionModel[] {
        const fields = this.metadataParser.getFieldsDefinition(metadata, tweaks, item, readonly, onlyLocalizable);
        const sections = this.groupFields(metadata, fields, tweaks, readonly);
        return sections;
    }

    public generateFieldModels(metadata: Entity, typeName: string, tweaksStore: BackendTweaksStore, dataItem: DataItem = null, readonly: boolean = false, onlyLocalizable: boolean = false): FieldModel[] {
        const viewName = dataItem && !dataItem.isEmpty ? VIEW_NAME.EDIT : VIEW_NAME.INSERT;
        const tweaks = tweaksStore.getFormByType(typeName, viewName);
        const fields = this.metadataParser.getFieldsDefinition(metadata, tweaks, dataItem, readonly, onlyLocalizable);
        return fields;
    }

    // TODO: all createFieldModel functions must be unified under a single function
    public createFieldModel(options: { key: string, value?: string, settings?: any, selector?: string, registration: FieldRegistration }): FieldModel {
        const fieldModel = new FieldModel({
            key: options.key,
            selector: options.selector || FieldTypes.shortText,
            settings: options.settings || {},
            value: options.value || stringConstants.EMPTY_STRING,
            registration: options.registration
        });

        return fieldModel;
    }

    private configureTitle(field: FieldModel, section: FieldSectionModel, defaultFieldName: string) {
        let showTitle: boolean = field.settings.showTitle;
        switch (field.selector) {
            case FieldTypes.html:
                if (section.settings.isMain) {
                    if (section.fields.length === 0 || (section.fields.length === 1 && section.fields[0].settings.key === defaultFieldName)) {
                        field.settings.showTitle = true;
                        field.settings.visibleTitle = false;
                    }
                }
                break;
            case FieldTypes.shortTextDefault:
            case FieldTypes.address:
            case FieldTypes.mediaData:
                showTitle = false;
                break;
        }

        field.settings.showTitle = showTitle;
    }

    private groupFields(metadata: Entity, fields: FieldModel[], tweaks: FormData[], readonly: boolean): FieldSectionModel[] {
        // no need to order if the field is only one;
        if (fields.length < 1)
            return [];

        const fieldSections: FieldSectionModel[] = [];
        let section: FieldSectionModel;
        const processedTweaks = new Set<string>();

        tweaks.forEach(tweak => {
            if (processedTweaks.has(tweak.name)) {
                return;
            }

            if (tweak.isSection) {
                const warning = tweak.metadata ? tweak.metadata["Warning"] || null : null;
                section = new FieldSectionModel({
                    title: tweak.title,
                    hideTitle: !tweak.title && tweak.isExpandedByDefault,
                    name: tweak.name,
                    isExpanded: tweak.isExpandedByDefault,
                    isMain: fieldSections.length === 0,
                    insertHorizontalRule: true,
                    warning
                });

                fieldSections.push(section);
                return;
            }

            for (const handler of this.tweaksHandlers) {
                if (!handler.canProcess(metadata.typeFullName)) {
                    continue;
                }

                const resultTweaks = handler.handleFormTweak(fieldSections, tweak.name, fields);
                resultTweaks.forEach(x => processedTweaks.add(x));

                if (resultTweaks.length)
                    return;
            }

            // the main section is the first one, it's name can be changed so we cannot find it by name
            const mainSection = fieldSections[0];

            for (const field of fields) {
                // skipping fields that do not match the current tweak
                if (tweak.name !== field.key) {
                    continue;
                }

                const defaultFieldName = metadata.defaultFieldName;
                field.settings.title = tweak.title;
                this.configureTitle(field, section, defaultFieldName);
                if (field.key === defaultFieldName && !metadata.isMedia && metadata.setName !== ENTITY_SET.PRESETS) {
                    mainSection.fields.unshift(field);
                } else {
                    section.fields.push(field);
                }

                break;
            }
        });

        return fieldSections;
    }
}
