import { Injectable } from "@angular/core";
import { SfInputComponent } from "@progress/sitefinity-component-framework";
import { ChoiceDropdownComponent } from "../../../../../fields/choice/choice-dropdown.component";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";
import { FormDefinition, FormField, FormsConstants, FormFieldTypeData } from "../forms.constants";
import { DateTimePickerComponent } from "../../../../../fields/date-time/date-time-picker.component";
import { DateTimePickerSettings } from "../../../../../fields/date-time/date-time-settings";
import { HiddenComponent } from "../../../../../fields/hidden/hidden.component";
import { TextAreaSettings } from "../../../../../fields/text-area/text-area-settings";
import { TextAreaComponent } from "../../../../../fields/text-area/text-area.component";
import { RelatedDataSettings } from "../../../../../fields/related-data/related-data.settings";
import { RelatedDataComponent } from "../../../../../fields/related-data/related-data.component";
import { DISPLAY_MODE } from "../../../../../fields/fields-constants";
import { SettingsBase } from "../../../../../fields/field-settings-base";
import { DateTimePickerConstants } from "../../../../../fields/date-time/date-time-picker.constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { DynamicItemService, LoadItem } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { Observable, of } from "rxjs";
import { stringConstants } from "../../../common-constants";
import { cloneObject } from "../../../utils";
import { TextAreaMultilineEmailSettings } from "../../../../../fields/text-area/text-area-multiline-email-settings";
import { ValidatorFn, Validators } from "@angular/forms";
import { VALIDATOR_NAMES, VALIDATORS } from "../../../../../fields/common/validators";

const ROW_COL_CSS_CLASS = "sf-row__col";
const ONE_COL_CSS_CLASS = "-col-1";

@Injectable()
export class FormFieldTypesParserService {

    constructor(protected metadataStore: MetadataStore,
                protected dynamicItemsService: DynamicItemService) { }

    getConditionComponentType(formField: FormField, defaultValue: any): FormFieldTypeData {
        const dateTimeSettings = new DateTimePickerSettings("dateTimePicker", false);
        dateTimeSettings.readOnlyMode = false;

        switch (formField.Type) {
            case FormsConstants.FORM_FIELD_TYPE.TEXTBOX:
            case FormsConstants.FORM_FIELD_TYPE.PARAGRAPH:
                switch (formField.InputType) {
                    case FormsConstants.TEXT_INPUT_TYPE.DATE:
                        return {
                            component: {
                                type: DateTimePickerComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    timeZoneOffset: FormsConstants.TIMEZONE_OFFSET,
                                    hideSelectIcon: true,
                                    showTime: false,
                                    settings: dateTimeSettings,
                                    value: defaultValue
                                }
                            }
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.MONTH:
                        return {
                            component: {
                                type: DateTimePickerComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    timeZoneOffset: FormsConstants.TIMEZONE_OFFSET,
                                    hideSelectIcon: true,
                                    dateBottomView: DateTimePickerConstants.VIEW.YEAR,
                                    dateTopView: DateTimePickerConstants.VIEW.DECADE,
                                    dateFormat: DateTimePickerConstants.MONTH_FORMAT,
                                    showTime: false,
                                    settings: dateTimeSettings,
                                    value: defaultValue
                                }
                            }
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.TIME:
                        return {
                            component: {
                                type: DateTimePickerComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    timeZoneOffset: FormsConstants.TIMEZONE_OFFSET,
                                    hideSelectIcon: true,
                                    showDate: false,
                                    settings: dateTimeSettings,
                                    value: defaultValue
                                }
                            }
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.DATE_TIME:
                    case FormsConstants.TEXT_INPUT_TYPE.DATE_TIME_LOCAL:
                        return {
                            component: {
                                type: DateTimePickerComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    timeZoneOffset: FormsConstants.TIMEZONE_OFFSET,
                                    hideSelectIcon: true,
                                    showDate: true,
                                    showTime: true,
                                    settings: dateTimeSettings,
                                    value: defaultValue
                                }
                            }
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.RANGE:
                        return {
                            component: {
                                type: SfInputComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    value: defaultValue,
                                    type: FormsConstants.TEXT_INPUT_TYPE.NUMBER,
                                    placeholder: FormsConstants.INPUT_PLACEHOLDER
                                }
                            },
                            cssClassList: ROW_COL_CSS_CLASS
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.COLOR:
                        return {
                            component: {
                                type: SfInputComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    value: defaultValue,
                                    type: FormsConstants.TEXT_INPUT_TYPE.COLOR,
                                    placeholder: FormsConstants.INPUT_PLACEHOLDER
                                }
                            },
                            cssClassList: `${ROW_COL_CSS_CLASS} ${ONE_COL_CSS_CLASS}`
                        };
                    case FormsConstants.TEXT_INPUT_TYPE.WEEK:
                        return {
                            component: {
                                type: SfInputComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    value: defaultValue,
                                    type: FormsConstants.TEXT_INPUT_TYPE.WEEK,
                                    placeholder: FormsConstants.INPUT_PLACEHOLDER
                                }
                            }
                        };
                    default:
                        return {
                            component: {
                                type: SfInputComponent,
                                updatePropertiesOnChange: true,
                                properties: {
                                    value: defaultValue,
                                    type: formField.InputType,
                                    placeholder: FormsConstants.INPUT_PLACEHOLDER
                                }
                            },
                            cssClassList: ROW_COL_CSS_CLASS
                        };
                }
            case FormsConstants.FORM_FIELD_TYPE.MULTIPLE_CHOICE:
            case FormsConstants.FORM_FIELD_TYPE.CHECKBOX:
            case FormsConstants.FORM_FIELD_TYPE.DROPDOWN:
                const componentSettings = new ChoiceSettings("choiceDropdownComponent", false);
                formField.Values.forEach(item => {
                    componentSettings.choices.push(item);
                });

                if (defaultValue) {
                    componentSettings.defaultValue = defaultValue;
                } else if (formField.Values.length > 0) {
                    componentSettings.defaultValue = formField.Values[0].Value;
                }

                return {
                    component: {
                        type: ChoiceDropdownComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: componentSettings
                        }
                    },
                    cssClassList: ROW_COL_CSS_CLASS
                };
            default:
                const hiddenSettings = new SettingsBase("hiddenComponent", false);
                return {
                    component: {
                        type: HiddenComponent,
                        properties: {
                            settings: hiddenSettings
                        }
                    },
                    cssClassList: ROW_COL_CSS_CLASS
                };
        }
    }

    getActionComponentType(action: string, formDefinition: FormDefinition, defaultValue: any): Observable<FormFieldTypeData> {
        let formFieldData: FormFieldTypeData;

        switch (action) {
            case FormsConstants.FORM_ACTION_TYPE.SHOW:
            case FormsConstants.FORM_ACTION_TYPE.HIDE:
                const visibilityComponentSettings = new ChoiceSettings("formTargetDropdown", false);
                this.getActionFields(formDefinition).forEach(formField => {
                    visibilityComponentSettings.choices.push({
                        Value: formField.Id,
                        Name: formField.Title
                    });
                });

                if (defaultValue) {
                    visibilityComponentSettings.defaultValue = defaultValue;
                } else if (formDefinition.Fields.length > 0) {
                    visibilityComponentSettings.defaultValue = formDefinition.Fields[0].Id;
                }

                formFieldData = {
                    component: {
                        type: ChoiceDropdownComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: visibilityComponentSettings
                        }
                    },
                    tooltip: {
                        title: FormsConstants.SHOW_HIDE_TOOLTIP_TITLE,
                        message: FormsConstants.SHOW_HIDE_TOOLTIP_MESSAGE
                    }
                };

                return of(formFieldData);
            case FormsConstants.FORM_ACTION_TYPE.SKIP:
                const skipComponentSettings = new ChoiceSettings("formActionsDropdown", false);
                formDefinition.Steps.forEach(s => {
                    skipComponentSettings.choices.push({
                        Value: s.Key,
                        Name: s.Value
                    });
                });

                if (defaultValue) {
                    skipComponentSettings.defaultValue = defaultValue;
                } else if (formDefinition.Steps.length > 0) {
                    skipComponentSettings.defaultValue = formDefinition.Steps[0].Key;
                }

                formFieldData = {
                    component: {
                        type: ChoiceDropdownComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: skipComponentSettings
                        }
                    }
                };

                return of(formFieldData);
            case FormsConstants.FORM_ACTION_TYPE.SHOW_MESSAGE:
                let value: string;
                const textAreaSettings = new TextAreaSettings("editorComponent", false);
                textAreaSettings.required = true;
                textAreaSettings.friendlyTitle = FormsConstants.MESSAGE;

                const validators: Array<ValidatorFn> = [];
                validators.push(Validators.required);
                textAreaSettings.validators = Validators.compose(validators);

                if (defaultValue) {
                    value = defaultValue;
                } else {
                    textAreaSettings.defaultValue = stringConstants.EMPTY_STRING;
                }

                formFieldData = {
                    component: {
                        type: TextAreaComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: textAreaSettings,
                            value: value
                        }
                    },
                    cssClassList: ROW_COL_CSS_CLASS
                };

                return of(formFieldData);
            case FormsConstants.FORM_ACTION_TYPE.SEND_NOTIFICATION:
                let emailValue: string;

                const textAreaMultilineEmailSettings = new TextAreaMultilineEmailSettings("editorComponent", false);
                textAreaMultilineEmailSettings.required = true;
                textAreaMultilineEmailSettings.friendlyTitle = FormsConstants.EMAIL_ADDRESS;
                textAreaMultilineEmailSettings.instructionalText = FormsConstants.SEND_NOTIFICATION.TEXT_AREA.INSTRUCTIONAL_TEXT;
                textAreaMultilineEmailSettings.placeholder = FormsConstants.SEND_NOTIFICATION.TEXT_AREA.PLACEHOLDER;

                const sendNotificationValidators: Array<ValidatorFn> = [];
                sendNotificationValidators.push(Validators.required);
                sendNotificationValidators.push(VALIDATORS[VALIDATOR_NAMES.MULTILINE_EMAILS]());
                textAreaMultilineEmailSettings.validators = Validators.compose(sendNotificationValidators);

                if (defaultValue) {
                    emailValue = defaultValue
                        .split(",")
                        .join("\n");
                } else {
                    textAreaMultilineEmailSettings.defaultValue = stringConstants.EMPTY_STRING;
                }

                formFieldData = {
                    component: {
                        type: TextAreaComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: textAreaMultilineEmailSettings,
                            value: emailValue
                        }
                    },
                    cssClassList: ROW_COL_CSS_CLASS
                };

                return of(formFieldData);
            case FormsConstants.FORM_ACTION_TYPE.GOTO:
                const relatedDataSettings = new RelatedDataSettings("relatedDataComponent", false);
                relatedDataSettings.type = ENTITY_SET.PAGES;
                relatedDataSettings.culture = formDefinition.Culture;
                relatedDataSettings.allowMultiple = false;
                relatedDataSettings.displayMode = DISPLAY_MODE.INPUT;
                relatedDataSettings.required = true;
                relatedDataSettings.title = FormsConstants.PAGE;

                const relatedDataValidators: Array<ValidatorFn> = [];
                relatedDataValidators.push(Validators.required);
                relatedDataSettings.validators = Validators.compose(relatedDataValidators);

                if (defaultValue) {
                    const pageEntity = this.metadataStore.getEntity(ENTITY_SET.PAGES);
                    const pageLoadData = <LoadItem>{
                        itemKey: defaultValue,
                        entityData: <EntityData>{
                            metadata: pageEntity,
                            culture: formDefinition.Culture
                        }
                    };

                    return new Observable(obs => {
                        this.dynamicItemsService.getItem(pageLoadData).subscribe(
                            result => {
                                obs.next(formFieldData = {
                                    component: {
                                        type: RelatedDataComponent,
                                        updatePropertiesOnChange: true,
                                        properties: {
                                            settings: relatedDataSettings,
                                            value: [cloneObject(result.data)]
                                        }
                                    },
                                    cssClassList: ROW_COL_CSS_CLASS
                                });
                            },
                            error => {
                                obs.next(formFieldData = {
                                    component: {
                                        type: RelatedDataComponent,
                                        updatePropertiesOnChange: true,
                                        properties: {
                                            settings: relatedDataSettings,
                                            value: [cloneObject({
                                                Title: FormsConstants.SELECTED_PAGE_DOES_NOT_EXIST,
                                                NotFound: true,
                                                icon: "ban",
                                                iconLook: "darker",
                                                inactive: true
                                            })]
                                        }
                                    },
                                    cssClassList: ROW_COL_CSS_CLASS
                                });
                            });
                    });
                }

                formFieldData = {
                    component: {
                        type: RelatedDataComponent,
                        updatePropertiesOnChange: true,
                        properties: {
                            settings: relatedDataSettings,
                            value: []
                        }
                    },
                    cssClassList: ROW_COL_CSS_CLASS
                };

                return of(formFieldData);
            default:
                formFieldData = {
                    component: {
                        type: SfInputComponent
                    }
                };

                return of(formFieldData);
        }
    }

    getField(formDefinition: FormDefinition, id: string): FormField {
        return formDefinition.Fields.find(f => f.Id === id);
    }

    getConditionFields(formDefinition: FormDefinition): FormField[] {
        const conditionFields: FormField[] = [];

        formDefinition.Fields.forEach(formField => {
            if (formField.Type &&
                formField.Operators &&
                formField.Operators.length > 0 &&
                FormsConstants.STATIC_FORM_FIELDS.indexOf(formField.Type) === -1) {
                conditionFields.push(formField);
            }
        });

        return conditionFields;
    }

    getActionFields(formDefinition: FormDefinition): FormField[] {
        const actionFields: FormField[] = [];

        formDefinition.Fields.forEach(formField => {
            if (formField.Hideable) {
                actionFields.push(formField);
            }
        });

        return actionFields;
    }
}
