import { Pipe, PipeTransform } from "@angular/core";
import { stringConstants } from "../../../common-constants";

const SEPARATOR = "-W";
const WEEK = "Week";

@Pipe({
    name: "sfIsoWeekDates"
})
export class IsoWeekDatesPipe implements PipeTransform {

    transform(value: string): string {
        if (value) {
            const parts = value.split(SEPARATOR);
            if (parts.length === 2) {
                const year = parts[0];
                const week = parts[1];
                value = `${WEEK}${stringConstants.INTERVAL}${week}${stringConstants.COMMA}${stringConstants.INTERVAL}${year}`;
            }
        }

        return value;
    }
}
