import { Injectable, InjectionToken } from "@angular/core";
import { Observable } from "rxjs";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { LoadItemsResponse, LoadItemsData, DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { TaxonomySettings } from "../../taxonomy/taxonomy.settings";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";

export const HIERARCHICAL_SERVICE_TOKEN = new InjectionToken("hierarchical_service");

export const TITLE_KEY = "Title";
export const PARENT_KEY = "ParentId";
export const ID_KEY = "Id";
export const LAST_MODIFIED_KEY = "LastModified";
export const RESULT_COUNT = 5;

@Injectable()
export abstract class HierarchicalService {
    public siteId: string;

    constructor(protected dynamicItemService: DynamicItemService) { }

    abstract showStatusIcons(): boolean;

    abstract isHierarchical(type: string): boolean;

    abstract getSetName(): string;

    abstract isTypeSupported(entityData: EntityData): boolean;

    abstract getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse>;

    abstract getItemTaxa(value: string[], entityData: EntityData, taxaId: string, isCreate: boolean): Observable<LoadItemsResponse>;

    abstract getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[], editItemId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse>;

    abstract expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string, editItemId?: string): Observable<LoadItemsResponse>;

    abstract loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings, editItemId?: string, isCreate?: boolean): Observable<LoadItemsResponse>;

    abstract getModalItems(modalItemsEntityData: EntityData, taxaId: string, editItemId?: string, targetDataItem?: DataItem, rootId?: string): Observable<LoadItemsResponse>;

    abstract getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData, editItemId?: string, useSynonyms?: boolean): Observable<LoadItemsResponse>;
}
