import { Injectable } from "@angular/core";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { CREATE_LINK_MODEL_PROPERTIES } from "../helpers/create-link-constants";
import { ContentLinkInputModel } from "../link-insert-field/helpers/content-link-input-model";
import { stringConstants } from "../../../../../common-constants";
import { CreateLinkHelper } from "../create-link-helper";

@Injectable()
export class CreateLinkFieldChangeService implements FieldChangeService {
    constructor(
        private createLinkHelper: CreateLinkHelper
    ) { }

    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === CREATE_LINK_MODEL_PROPERTIES.ANCHOR || changedFieldName === CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS) {
            const queryParamsField = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS);
            const hasQueryParams = queryParamsField && queryParamsField.getValue();

            const anchorField = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.ANCHOR);
            const hasAnchorField = anchorField && anchorField.getValue();

            const isUrlRequired = hasQueryParams || !hasAnchorField;
            this.changeIsUrlFieldRequired(!!isUrlRequired, fields);
            this.updateLinkValue(changedFieldName, hasAnchorField, hasQueryParams, fields);
        }

        if (changedFieldName === CREATE_LINK_MODEL_PROPERTIES.LINK_TO) {
            this.updateAnchorAndQueryParams(fields);
        }
    }

    canProcess(typeFullName: string): boolean {
        if (!typeFullName) {
            return true;
        }

        return false;
    }

    private changeIsUrlFieldRequired(isUrlRequired: boolean, fields: FormFieldWrapperComponent[]) {
        const fieldWrapper = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.LINK_TO);
        if (fieldWrapper) {
            const value = fieldWrapper.getValue() as ContentLinkInputModel;
            if (value.isUrlRequired !== isUrlRequired) {
                value.isUrlRequired = isUrlRequired;
                fieldWrapper.writeValue(value);
            }
        }
    }

    private updateLinkValue(changedFieldName: string, anchorField: string, queryParamsField: string, fields: FormFieldWrapperComponent[]) {
        const linkToFieldWrapper = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.LINK_TO);
            if (linkToFieldWrapper) {
                const linkValue = linkToFieldWrapper.getValue() as ContentLinkInputModel;
                const linkModel = this.createLinkHelper.desctructureLink(linkValue.href);

                if (linkModel.elementLink) {
                    if (changedFieldName === CREATE_LINK_MODEL_PROPERTIES.ANCHOR && anchorField !== linkModel.elementAnchor) {
                        this.updateLinkParam(anchorField, linkModel.elementAnchor, linkModel.elementLink, stringConstants.HASH, linkValue, linkToFieldWrapper);
                    } else if (changedFieldName === CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS && queryParamsField !== linkModel.elementQueryParams) {
                        this.updateLinkParam(queryParamsField, linkModel.elementQueryParams, linkModel.elementLink, stringConstants.QUESTION_MARK, linkValue, linkToFieldWrapper);
                    }
                }
            }
    }

    private updateLinkParam(fieldValue: string, linkElementParam: string, linkElement: string, paramSymbol: string, linkValue: ContentLinkInputModel, fieldWrapper: FormFieldWrapperComponent) {
        if (fieldValue === stringConstants.EMPTY_STRING) {
            if (linkElementParam !== stringConstants.EMPTY_STRING) {
                linkValue.href = linkElement.replace(paramSymbol + linkElementParam, stringConstants.EMPTY_STRING);
                fieldWrapper.writeValue(linkValue);
            }
        } else {
            if (linkElementParam === stringConstants.EMPTY_STRING) {
                const hashIndex = linkElement.indexOf(stringConstants.HASH)
                if (hashIndex !== -1)
                {
                    linkValue.href = linkElement.substring(0, hashIndex - 1) + paramSymbol + fieldValue + linkElement.substring(hashIndex);
                }
                else
                {
                    linkValue.href = linkElement + paramSymbol + fieldValue;
                }
            } else {
                linkValue.href = linkElement.replace(paramSymbol + linkElementParam, paramSymbol + fieldValue);
            }

            fieldWrapper.writeValue(linkValue);
        }
    }

    private updateAnchorAndQueryParams(fields: FormFieldWrapperComponent[]) {
        const linkToField = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.LINK_TO);
            const linkValue = linkToField && linkToField.getValue() as ContentLinkInputModel;

            if (linkValue.href) {
                const linkModel = this.createLinkHelper.desctructureLink(linkValue.href);
                const anchorFieldWrapper = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.ANCHOR);

                if (anchorFieldWrapper) {
                    const value = anchorFieldWrapper.getValue();
                    if (value !== linkModel.elementAnchor) {
                        anchorFieldWrapper.writeValue(linkModel.elementAnchor);
                    }
                }
                const queryParamsFieldWrapper = fields.find(x => x.fieldModel.key === CREATE_LINK_MODEL_PROPERTIES.QUERY_PARAMS);

                if (queryParamsFieldWrapper) {
                    const value = queryParamsFieldWrapper.getValue();
                    if (value !== linkModel.elementQueryParams) {
                        queryParamsFieldWrapper.writeValue(linkModel.elementQueryParams);
                    }
                }
            }
    }
}

export const CREATE_LINK_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: CreateLinkFieldChangeService,
    multi: true
};
