import { Component, Input, OnInit, OnChanges, SimpleChanges, ViewChild } from "@angular/core";
import { SfButtonComponent } from "@progress/sitefinity-component-framework";
import { createValueAccessor } from "../field-base";
import { ChoiceDropdownComponent } from "./choice-dropdown.component";

const SETTINGS_CHOICES_ARRAY_STRING = "choices";
const CHOICE_DROPDOWN_LIST_WRAPPER_CSS_CLASS: string = "sf-button -no-border -left -icon";

@Component({
    selector: "sf-dropdown-list-choice",
    templateUrl: "./choice-dropdown-list.component.html",
    providers: [createValueAccessor(ChoiceDropdownListComponent)]
})
export class ChoiceDropdownListComponent extends ChoiceDropdownComponent implements OnInit, OnChanges {
    @ViewChild("choiceDropdownButton", { static: true }) choiceDropdownButton: SfButtonComponent;
    @Input() optgroup: string;
    @Input() ariaLabel: string;

    dropped: boolean = false;
    displayName: string;
    cssClass: string = CHOICE_DROPDOWN_LIST_WRAPPER_CSS_CLASS;

    ngOnInit() {
        this.mapChoiceItems();

        if (this.look) {
            this.cssClass += this.generateCssClassList();
        }
    }

    ngOnChanges (changes: SimpleChanges) {
        super.ngOnChanges(changes);
        if (changes && changes.settings) {
            this.generateDisplayName();
        }
    }

    onSelectionChangeMimic(event: Event, data) {
        if (this.value === data.Value) {
            return;
        }

        this.value = data.Value;
        this.displayName = data.Name;
        if (event instanceof KeyboardEvent) {
            this.dropped = false;
        }

        this.selectionChange.emit(this.value);
    }

    onArrowUpDown(event: Event, directionDown: boolean) {
        event.preventDefault();
        if (!this.dropped) {
            const choices = this.choices;
            let index = this.getIndex(choices);
            if (directionDown) {
                if (index !== choices.length - 1) {
                    index++;
                } else {
                    index = 0;
                }
            } else {
                if (index !== 0) {
                    index--;
                } else {
                    index = choices.length - 1;
                }
            }
            if (choices[index] && choices[index].Value) {
                this.value = choices[index].Value;
                this.displayName = choices[index].Name;
            }

            this.selectionChange.emit(this.value);
        }
    }

    onFocusSibling(event: Event, directionDown: boolean) {
        const activeEl = <HTMLElement> document.activeElement;
        if (activeEl) {
            const elementToFocus = <HTMLElement> (directionDown ? activeEl.nextElementSibling : activeEl.previousElementSibling);
            if (elementToFocus) {
                elementToFocus.focus();
            }
        }
    }

    onExpandDropdown(event: Event) {
        event.preventDefault();
        if (!this.dropped) {
            this.choiceDropdownButton.dropped = true;
            this.dropped = true;
        }
    }

    writeValue(value: any) {
        super.writeValue(value);
        this.generateDisplayName();
    }

    private getNameByValue(choices: Array<any>, value: string): string {
        if (choices && value) {
            const choice = choices.find((choice) => choice.Value === value);
            return choice.Name;
        }
        return null;
    }

    private getIndex(choices: Array<any>) {
        return choices.indexOf(choices.filter(x => x.Value === this.value)[0]);
    }

    private generateDisplayName() {
        if (this.settings && this.settings[SETTINGS_CHOICES_ARRAY_STRING]) {
            if (this.value && !this.settings[SETTINGS_CHOICES_ARRAY_STRING].some(x => x.Value === this.value)) {
                this.value = null;
            }

            if (this.value) {
                this.displayName = this.getNameByValue(this.settings[SETTINGS_CHOICES_ARRAY_STRING], this.value);
            } else if (this.settings.defaultValue) {
                this.value = this.settings.defaultValue;
                this.displayName = this.getNameByValue(this.settings[SETTINGS_CHOICES_ARRAY_STRING], this.settings.defaultValue);
            } else if (this.settings[SETTINGS_CHOICES_ARRAY_STRING].length > 0) {
                this.value = this.settings[SETTINGS_CHOICES_ARRAY_STRING][0].Value;
                this.displayName = this.settings[SETTINGS_CHOICES_ARRAY_STRING][0].Name;
            }
        }
    }
}
