import { Component, Input, OnInit, ViewChild } from "@angular/core";
import { ActivatedRoute } from "@angular/router";

import { SidebarComponentRepo, SidebarComponentData } from "./sidebar-component.repo";
import { AuxHostComponent } from "../../auxiliary/aux-host.component";
import { SidebarConfig, SidebarData } from "./sidebar.common";
import { SidebarSliderComponent } from "./sidebar-slider/sidebar-slider.component";
import { AppStore } from "../../../../services/store/app-store";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../services/store/actions/actions.sidebar";
import { SIDEBAR_SELECTORS } from "../../../../services/store/selectors/selectors.sidebar";
import { SfDynamicComponentLoaderComponent } from "@progress/sitefinity-component-framework";

export const SIDEBAR_CSS_CLASS: string = "sf-sidebar";

@Component({
    selector: "sf-sidebar-host",
    templateUrl: "./sidebar-host.component.html"
})
export class SidebarHostComponent extends AuxHostComponent<SidebarComponentRepo> implements OnInit {
    @Input() public title: string = "Sidebar";
    @Input() public look: string;
    @Input() public enabled: boolean = true;
    @Input() public hasBackNavigation: boolean = false;
    @Input() public hideCloseButton: boolean;
    @Input() public hasToggle: boolean;

    @ViewChild(SfDynamicComponentLoaderComponent, { static: false }) loader: SfDynamicComponentLoaderComponent;
    @ViewChild(SidebarSliderComponent, { static: false }) slider: SidebarSliderComponent;

    componentMapping: SidebarComponentData;
    sidebarCssClass: string = SIDEBAR_CSS_CLASS + " -hidden";
    isProgressLoading: boolean;
    isConfigChanging: boolean;
    currentConfig: SidebarConfig;
    notInitialLoad: boolean;
    isOpen: boolean;

    private sidebarData: SidebarData;
    private sidebars: Array<SidebarConfig> = [];
    private shouldAnimate: boolean;

    constructor(
        sidebarRepo: SidebarComponentRepo,
        route: ActivatedRoute,
        private store: AppStore) {
        super(route);
        this.service = sidebarRepo;
    }

    ngOnInit() {
        this.sidebarCssClass = this.generateCssClassList();

        if (this.hasToggle) {
            this.hideCloseButton = true;
        }
        this.registerSubscription(
            this.store.pipe(SIDEBAR_SELECTORS.sidebarData).subscribe(fullSidebarConfig => {
                if (fullSidebarConfig) {
                    this.sidebarData = fullSidebarConfig;
                }
            }));

        this.registerSubscription(
            this.store.pipe(SIDEBAR_SELECTORS.isLoading).subscribe(isLoading => {
                this.isProgressLoading = isLoading;
            }));

        this.registerSubscription(
            this.store.pipe(SIDEBAR_SELECTORS.isOpen).subscribe(isOpen => {
                this.isOpen = isOpen;
                this.sidebarCssClass = this.generateCssClassList();
            }));
        this.registerSubscription(
            this.store.pipe(SIDEBAR_SELECTORS.shouldAnimate).subscribe(shouldAnimate => {
                this.shouldAnimate = shouldAnimate;
                this.sidebarCssClass = this.generateCssClassList();
            }));

        this.registerSubscription(
            this.store.pipe(SIDEBAR_SELECTORS.activeConfig).subscribe(config => {
                this.isConfigChanging = false;
                this.currentConfig = config;

                if (config && config.data) {
                    this.sidebars.push(config);
                    this.title = config.title;
                    this.hasBackNavigation = config.data.hasBackNavigation;
                    this.componentMapping = null;
                    this.componentMapping = config.data;

                    this.notInitialLoad = true;
                } else {
                    this.componentMapping = null;
                    this.isConfigChanging = true;
                    this.sidebars = [];
                }

                this.sidebarCssClass = this.generateCssClassList();
            }));

        super.ngOnInit();
    }

    backToSidebar() {
        if (this.sidebars.length > 1) {
            this.sidebars.pop(); // current
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.change(this.sidebars.pop()));
        }
    }

    onClose() {
        if (!this.sidebarData) {
            return super.onClose();
        }

        return Promise.resolve(true);
    }

    public close() {
        if (this.sidebarData) {
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.close());
        }
    }

    public toggleVisibility() {
        //sidebar is closed and has one button
        if (!this.isOpen && this.sidebarData.buttons.length === 1) {
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.changeAndOpen(this.sidebarData.buttons[0], true));
        } else {
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.close());
        }
    }

    protected onMappingChanged(mapping: SidebarComponentData) {
        this.title = mapping.title;
        this.look = mapping.look;
        this.hasBackNavigation = mapping.hasBackNavigation;
        this.componentMapping = mapping;

        this.sidebarCssClass = this.generateCssClassList();
    }

    private generateCssClassList() {
        let cls = SIDEBAR_CSS_CLASS;
        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.hasToggle) {
            cls += " -toggle";
        }

        if (this.shouldAnimate) {
            cls += " -animate";
        }

        if (!this.isOpen) {
            cls += " -hidden";
        }

        if (this.isOpen && this.componentMapping && this.componentMapping.wide) {
            cls += " -wide";
        }

        return cls;
    }
}
