import { Component } from "@angular/core";
import { of, Observable } from "rxjs";
import { WidgetContext } from "../../models/widget-context";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { PropertyEditorConstants, Dictionary, PropertyEditorViewModes } from "../../property-editor.constants";
import { stringConstants } from "../../../../common-constants";
import { MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { ContentBlockConstants } from "../content-block.constants";
import { WidgetMetadata, PropertyData, WidgetEditor, ActionContext, ValidationResult } from "../../interfaces/widget-editor";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { CustomActions } from "../../interfaces/custom-actions";
import { map } from "rxjs/operators";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-unshare-view",
    templateUrl: "./unshare.component.html"
})
export class UnshareComponent extends SfRxBase implements WidgetEditor, CustomActions {
    context: WidgetContext;
    unshareContentName = PropertyEditorConstants.STOP_SHARING;
    private allProperties: Dictionary;

    private contentItem: DataItem;

    constructor(protected dynamicItemService: DynamicItemService,
                protected metadataStore: MetadataStore) {
        super();
    }

    public initialize(propertiesData: WidgetMetadata): Observable<void> {
        this.allProperties = propertiesData.propertyValues;
        return of(undefined);
    }

    public setValues(propValues: Dictionary): void {
        this.allProperties = propValues;
    }

    public validate(): Observable<ValidationResult> {
        return of({ isValid: true });
    }

    public getModifiedProperties(): Array<PropertyData> {
        if (this.contentItem) {
            this.allProperties[ContentBlockConstants.CONTENT] = this.contentItem.data.Content;
        }
        const modifiedProperties: Array<PropertyData> = [];
        this.allProperties[ContentBlockConstants.PROVIER_NAME] = stringConstants.EMPTY_STRING;
        modifiedProperties.push({Name: ContentBlockConstants.PROVIER_NAME, Value: this.allProperties[ContentBlockConstants.PROVIER_NAME]});
        this.allProperties[ContentBlockConstants.SHARED_CONTENT_ID] = stringConstants.DEFAULT_GUID;
        modifiedProperties.push({Name: ContentBlockConstants.SHARED_CONTENT_ID, Value: this.allProperties[ContentBlockConstants.SHARED_CONTENT_ID]});
        modifiedProperties.push({Name: ContentBlockConstants.CONTENT, Value: this.allProperties[ContentBlockConstants.CONTENT]});

        return modifiedProperties;
    }

    public actionExecuting(context: ActionContext): Observable<any> {
        if (context.processChanges) {
            const sharedCotnentId = this.allProperties[ContentBlockConstants.SHARED_CONTENT_ID];
            const provider = this.allProperties[ContentBlockConstants.PROVIER_NAME];
            return this.getContentBlock(sharedCotnentId, provider).pipe(map((contentItem) => {this.contentItem = contentItem; }));
        } else {
            return of({});
        }
    }

    public getActions() {
        return {
            operations: [{
                Title: PropertyEditorConstants.STOP_SHARING,
                Category: {
                    Name: "default"
                },
                Name: PropertyEditorViewModes.UNSHARE,
                Ordinal: -1,
                Description: stringConstants.EMPTY_STRING,
                Link: stringConstants.EMPTY_STRING,
                Parameters: null,
                RequiresConfirmation: false
            }],
            cssClass: stringConstants.EMPTY_STRING
        };
    }

    private getContentBlock(id, provider) {
        const contentBlockEntity = this.metadataStore.getEntity(ContentBlockConstants.ENTITY_NAME);
        const contentBlockEntityData = {
            culture: this.context.culture,
            provider: provider,
            metadata: contentBlockEntity
        };

        return this.dynamicItemService.getItem({
            itemKey: id,
            entityData: contentBlockEntityData
        });
    }
}
