import { map } from "rxjs/operators";
import { Inject, Injectable } from "@angular/core";

import { AuxServiceBase, AuxSettings, ActivityStatus } from "../../auxiliary/aux-service.base";
import { Router, ActivatedRoute } from "@angular/router";
import { Observable } from "rxjs";
import { stringConstants } from "../../../../common-constants";
import { LOCAL_STORAGE, StorageService } from "../../services/storage.service";
import { ComponentData } from "@progress/sitefinity-component-framework";

export const SIDEBAR_KEY: string = "sidebar";

// TODO  better api
@Injectable()
export class SidebarComponentRepo extends AuxServiceBase<SidebarComponentData> {
    constructor(router: Router, @Inject(LOCAL_STORAGE) private storage: StorageService) {
        super(router);
    }

    get activityStatus(): Observable<ActivityStatus> {
        return this._activityStatus.pipe(map(status => {
            const mapping = this.getComponentMapping(status.route);
            const activityStatus: SidebarActivityStatus = {
                active: status.active,
                route: status.route,
                wide: mapping ? mapping.wide : false
            };

            return activityStatus;
        }));
    }

    addComponentMapping(urlKey: string, component: SidebarComponentData): void {
        if (component.wide) {
            component.look = component.look || stringConstants.EMPTY_STRING;
            component.look += " wide";
        }

        this.setData(urlKey, component);
    }

    getComponentMapping(urlKey: string): SidebarComponentData {
        return this.getData(urlKey);
    }

    async show(routeKey: string, auxParentRoute: ActivatedRoute): Promise<void> {
        if (this.currentActivityStatus && this.currentActivityStatus.active && this.currentActivityStatus.route !== routeKey) {
            await this.hide(auxParentRoute, true);
        }

        super.show(routeKey, auxParentRoute);
    }

    hide(auxParentRoute: ActivatedRoute = null, closeAll: boolean = false): Promise<boolean> {
        return super.hide(auxParentRoute, closeAll).then((isSuccessful: boolean) => {
            return isSuccessful;
        });
    }

    getOpenedSidebarForCurrentType(currentType: string): string {
        const sidebar = this.getOpenedSidebars();

        return sidebar[currentType];
    }

    getOpenedSidebars(): Object {
        let openedSidebars = this.storage.getItem(SIDEBAR_KEY);
        openedSidebars = openedSidebars ? JSON.parse(openedSidebars) : {};

        return openedSidebars;
    }

    updateOpenedSidebars(openedSidebars: Object, currentType: string, sidebarName?: string) {
        if (sidebarName) {
            openedSidebars[currentType] = sidebarName;
        }

        this.storage.setItem(SIDEBAR_KEY, JSON.stringify(openedSidebars));
    }

    removeItemFromOpenedSidebars(openedSidebars: Object, currentType: string) {
        if (openedSidebars[currentType]) {
            delete openedSidebars[currentType];
            this.updateOpenedSidebars(openedSidebars, currentType);
        }
    }

    protected getSettings(): AuxSettings {
        return {
            outletName: "sidebar",
            prefix: "host"
        };
    }
}

export interface SidebarComponentData extends ComponentData {
    title: string;
    look?: string;
    wide?: boolean;
    hasBackNavigation?: boolean;
}

export interface SidebarActivityStatus extends ActivityStatus {
    wide: boolean;
}
