import { Injectable, ClassProvider } from "@angular/core";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../shared/services/edit/edit-extender";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";

const CONTENT_FORM_CLASS = "-sf-pt-zero -medium";

@Injectable()
export class PresetsEditExtender extends EditExtender {
    showHeader(entityData: EntityData): boolean {
        return true;
    }

    getHeader(dataItem: DataItem): string {
        return dataItem.isEmpty ? "Create a section preset" : "Section preset properties";
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.PRESETS;
    }

    getFormClasses(): string {
        return CONTENT_FORM_CLASS;
    }

    getActionMenuClasses(): string {
        return "sf-row -justify-content-center";
    }
}

export const PRESETS_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: PresetsEditExtender
};
