import { AbstractControl, FormGroup } from "@angular/forms";

export const SCHEDULE_VALIDATOR_NAME = "schedule";
export const MISSING_PUB_UNPUB_VALUES = "missingPubUnpubValues";
export const INVALID_EXPIRATION_DATE = "invalidExpDate";
const PUBLICATION_DATE_PROP_NAME = "PublicationDate";
const EXPIRATION_DATE_PROP_NAME = "ExpirationDate";

export class ScheduleValidator {
    protected static isValidEndDate(startDateControl: AbstractControl, endDateControl: AbstractControl) {
        if (startDateControl && endDateControl && startDateControl.value && endDateControl.value) {
            if (new Date(endDateControl.value).getTime() < new Date(startDateControl.value).getTime()) {
                return false;
            }
        }

        return true;
    }

    static validate(control: FormGroup): any {
        const publicationDate: AbstractControl = control.controls[PUBLICATION_DATE_PROP_NAME];
        const expirationDate: AbstractControl = control.controls[EXPIRATION_DATE_PROP_NAME];

        if (!ScheduleValidator.isValidEndDate(publicationDate, expirationDate)) {
            return {
                [INVALID_EXPIRATION_DATE]: true
            };
        }

        if (!publicationDate.value && !expirationDate.value) {
            return {
                [MISSING_PUB_UNPUB_VALUES]: true
            };
        }

        return null;
    }
}
