import { Component, Input, AfterViewInit, ViewEncapsulation, ViewChild, Output, EventEmitter, OnInit } from "@angular/core";
import { FieldBase } from "../field-base";
import { StatusType } from "../field-status";
import { convertIsoStringToUTCDate, getDateWithTimeZoneOffset } from "../common/utils";
import { VALIDATOR_NAMES } from "../common/validators";
import { DateTimePickerSettings } from "./date-time-settings";
import { EventDatesService } from "../../src/app/modules/shared/components/events/services/event-dates.service";
import { CalendarView } from "@progress/kendo-angular-dateinputs";
import { DateTimePickerConstants, DEFAULT_DATE_FORMAT, DEFAULT_TIME_FORMAT } from "./date-time-picker.constants";
import { DateTimeFormatsProvider } from "./date-time-formats.provider";

@Component({
    selector: "sf-date-time",
    templateUrl: "./date-time-picker.component.html",
    styleUrls: ["./date-time-picker.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class DateTimePickerComponent extends FieldBase implements OnInit, AfterViewInit {
    @Input() showDate: boolean = true;
    @Input() showTime: boolean = true;
    @Input() hideSelectIcon: boolean = false;
    @Input() dateBottomView: CalendarView | string = DateTimePickerConstants.VIEW.MONTH;
    @Input() dateTopView: CalendarView | string;
    @Input() dateFormat: string = DEFAULT_DATE_FORMAT;
    @Input() timeFormat: string = DEFAULT_TIME_FORMAT;
    @Input() datePlaceholder: string;
    @Input() timePlaceholder: string;
    @Input() look: string;
    @Output() dateValueChange: EventEmitter<Date> = new EventEmitter<Date>();
    public dateValue: Date;
    public timeValue: Date;
    public timeZoneOffset: number = null;
    public datePickerClass: string;
    public timePickerClass: string;
    @ViewChild("datepicker", { static: false }) datepicker: any;
    @ViewChild("timepicker", { static: false }) timepicker: any;

    constructor(
        private eventsDateService: EventDatesService,
        private dateTimeFormatProvider: DateTimeFormatsProvider
    ) {
        super();
    }

    get datePickerClasses(): string {
        let cls = "";
        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.hideSelectIcon) {
            cls += " -input-only";
        }

        if (!this.dateValue) {
            cls += " -empty";
        }

        return cls;
    }

    get timePickerClasses(): string {
        let cls = "";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }

        if (this.hideSelectIcon) {
            cls += " -input-only";
        }

        if (!this.timeValue) {
            cls += " -empty";
        }

        if (this.showDate && this.showTime) {
            cls += " -sf-ml-2xs";
        }

        return cls;
    }

    ngOnInit() {
        this.configureDateTimeFormats();

        super.ngOnInit();
        this.processDatetimePickerSettings();
    }

    ngAfterViewInit() {
        if (this.settings && this.settings.key) {
            if (this.datepicker && this.showDate) {
                this.datepicker.input.dateInput.nativeElement.id = this.settings.key;
            } else if (this.timepicker && this.showTime) {
                this.timepicker.input.dateInput.nativeElement.id = this.settings.key;
            }
        }
    }

    writeValue(value: any) {
        if (value !== this.value) {
            if (value) {
                if (typeof value === "string" || value instanceof String) {
                    let dateTime: Date;
                    if (this.timeZoneOffset !== null) {
                        dateTime = convertIsoStringToUTCDate(value as string);
                    } else {
                        dateTime = new Date(value as string);
                    }

                    if ((<DateTimePickerSettings>this.settings).preserveValueWithoutBrowserOffset) {
                        dateTime = this.eventsDateService.getDateWithoutBrowserOffset(dateTime);
                    }

                    this.dateValue = getDateWithTimeZoneOffset(dateTime, this.timeZoneOffset);
                    this.timeValue = getDateWithTimeZoneOffset(dateTime, this.timeZoneOffset);
                } else {
                    this.dateValue = new Date(value);
                    this.timeValue = new Date(value);
                }
            } else {
                this.dateValue = null;
                this.timeValue = null;
            }
        }

        if (typeof value === "string" || value instanceof String) {
            this.updateValue();
        } else if (value !== this.value) {
            super.writeValue(value);
        }
    }

    onTimeChange(newValue: Date) {
        this.timeValue = newValue;
        if (!this.dateValue) {
            // set today as the current date if no date is selected
            this.dateValue = getDateWithTimeZoneOffset(new Date(), this.timeZoneOffset);
        }

        this.updateValue();
        this.dateValueChange.emit(this.dateValue);
    }

    onDateChange(newValue: Date) {
        this.dateValue = newValue;
        if (!this.timeValue) {
            // set the time if not time is selected
            this.timeValue = this.dateValue;
        }

        const errorData = {
            [VALIDATOR_NAMES.REQUIRED]: true
        };

        if (!this.dateValue) {
            this.timeValue = null;
            // using the required validation so we can benefit from the required validation being available
            // after the first attempt to publish

            if (this.settings.required) {
                this.emitStatus({
                    type: StatusType.Error,
                    data: errorData
                });
            }
        } else {
            if (this.status$.getValue().type === StatusType.Error) {
                this.emitStatus({
                    type: StatusType.ErrorCleared,
                    data: errorData
                });
            }

            this.emitStatus({ type: StatusType.Done });
        }

        this.dateValueChange.emit(this.dateValue);
        this.updateValue();
    }

    onFocusDateTime(isDatePicker: boolean): void {
        this.onFocus();
        if (this.hideSelectIcon) {
            if (isDatePicker) {
                this.datepicker.show = true;
            } else {
                this.timepicker.show = true;
            }
        }
    }

    onBlurDateTime(isDatePicker: boolean): void {
        this.onBlur();
        if (this.hideSelectIcon) {
            if (isDatePicker) {
                this.datepicker.show = false;
            } else {
                this.timepicker.show = false;
            }
        }
    }

    get isOpen(): boolean {
        if (this.datepicker && this.datepicker.isOpen) {
            return true;
        }

        if (this.timepicker && this.timepicker.isOpen) {
            return true;
        }

        return false;
    }

    private processDatetimePickerSettings() {
        const showTimeFromSettings = (<DateTimePickerSettings>this.settings).dateSettingsShowTime;
        if (showTimeFromSettings !== null && showTimeFromSettings !== undefined) {
            this.showTime = showTimeFromSettings;
        }

        const datePlaceholder = this.settings.placeholder;
        if (datePlaceholder) {
            this.datePlaceholder = datePlaceholder;
        }
    }

    private updateValue() {
        if (this.dateValue) {
            const combinedValue = this.combineDateAndTime(this.dateValue, this.timeValue);
            this.writeValue(combinedValue);
        } else {
            this.writeValue(this.dateValue);
        }
    }

    private combineDateAndTime(dateValue: Date, timeValue: Date): Date {
        const newValue: Date = new Date(dateValue);
        if (timeValue) {
            const hours = this.showTime ? timeValue.getHours() : 0;
            const minutes = this.showTime ? timeValue.getMinutes() : 0;
            const seconds = this.showTime ? timeValue.getSeconds() : 0;
            newValue.setHours(hours);
            newValue.setMinutes(minutes);
            newValue.setSeconds(seconds);
        }

        return newValue;
    }

    private configureDateTimeFormats() {
        this.dateTimeFormatProvider.getDateAndTimeFormats().subscribe(x => {
            // if it's not the default time or date format that means that an external component has set the
            // values of the timeFormat and dateFormat fields as @Input() and we want to keep those values
            if (this.timeFormat === DEFAULT_TIME_FORMAT)
                this.timeFormat = x.timeFormat;
            if (this.dateFormat === DEFAULT_DATE_FORMAT)
                this.dateFormat = x.dateFormat;
        });
    }
}

export interface DateFormat {
    Culture: string;
    ShortDatePattern: string;
    ShortTimePattern: string;
    LongDatePattern: string;
    LongTimePattern: string;
}
