import { first, map } from "rxjs/operators";
import { Component, Input, OnInit, EventEmitter, Output, ViewChild, Optional, Inject } from "@angular/core";
import { SORT_ORDER } from "../../content/constants";
import { TaxonomySettings } from "../taxonomy.settings";
import { FieldBase, createValueAccessor } from "../../../../../fields/field-base";
import { Button, ConfirmButton, CancelButton, DialogData, ModalWindowService, ClickData, ClickResult } from "../../shared/services/modal-window.service";
import { SelectorConstants } from "../../html/selector-constants";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { SelectorComponent, SELECTOR_MAPPING_KEY, ServiceInfo } from "../../../../../fields/selector/selector.component";
import { ActivatedRoute } from "@angular/router";
import { ServiceContract } from "../../../../../fields/selector/selector.component";
import { CreateHierarchicalTaxaComponent } from "../../shared/components/create-hierarchical-taxa/create-hierarchical-taxa.component";
import { ChipsComponent, ChipsConfig } from "../../../../../fields/common/chips/chips.component";
import { ROUTE_PARAMS, RESOLVE_NAMES, DEFAULT_CHILDREN_LOAD } from "../../content/constants";
import { BehaviorSubject, Observable, ReplaySubject } from "rxjs";
import { stringConstants } from "../../../common-constants";
import { Properties } from "../../shared/fields.constants";
import { getFormattedTypeName, cloneObject } from "../../../utils";
import { TypeNames } from "../../../../../fields/types/types";
import { DynamicItemService, LoadItemsResponse } from "../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData, DataItem, TotalCountResult } from "../../content/dynamic-modules/interfaces";
import { createQuery } from "../../../services/query";
import { TreeConfig } from "../../../../../fields";
import { HierarchicalService, HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { HierarchicalDynamicItemService } from "../../content/dynamic-modules/services/hierarchical-dynamic-item-service";
import { GenericError } from "../../shared/services/errors/generic-error";
import { ValidationError } from "../../shared/services/errors/validation-error";
import TAXONOMY_CONSTANTS from "../taxonomy.constants";
import { Taxon } from "../intefaces";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { WhereQuery, Query } from "@progress/sitefinity-webservices-sdk/dist/sitefinity-webservices-sdk";
import { Entity } from "../../../api/v1/metadata/entity";

export const TITLE_KEY = "Title";
const NAME_KEY = "Name";
const FULL_URL_KEY = "FullUrl";
export const TAXONOMY_KEY = "TaxonomyId";
export const TAXONOMY_PARENT_KEY = "ParentId";
export const ID_KEY = "Id";
const RESULT_COUNT = 5;
const URL_EXISTS_KEY = "{\"UrlName\":\"UrlExists\"}";
const FAKE_TAXA_ID = "ffffffff-ffff-ffff-ffff-ffffffffffff";

// TODO: Needs to be refactored or at least be named in more appropriate way, this component is not only
// for the taxonomies, it is all used for the chips is some places like "create a library > under parent"
@Component({
    selector: "sf-taxa",
    templateUrl: "./taxa.component.html",
    providers: [createValueAccessor(TaxaComponent)]
})
export class TaxaComponent extends FieldBase<TaxonomySettings> implements OnInit {
    @Output() onSelectionChange: EventEmitter<string> = new EventEmitter<string>();
    @Output() onErrorOccured: EventEmitter<any> = new EventEmitter<any>();
    @Input() expandPathPair: { key: string, value: string } = { key: FULL_URL_KEY, value: NAME_KEY };
    @Input() entityData: EntityData;

    taxaItems: any[];
    visibleRecentTaxaItems = [];
    dropdownChipsTreeConfig: TreeConfig = {
        showBreadcrumb: true,
        noSelection: false,
        dataProperties: {
            toolTipField: "tooltip",
            alternativeTitleField: "Synonym"
        }
    };
    isLoading: boolean = false;
    addButtonTitle: string;
    addButtonContentType: string;
    taxaNames: TypeNames;
    isHierarchical: boolean = false;
    isSearchPending: boolean;
    chipsConfig: ChipsConfig = { showRecentLabel: true, actions: [] };
    message: string;
    taxa: Object[] = [];
    defaultFieldName: string;
    getRecentObservable: Observable<LoadItemsResponse>;

    get recentTaxaItems(): any[] {
        return this._recentTaxaItems;
    }

    set recentTaxaItems(items: any[]) {
        this._recentTaxaItems = items;
        this.visibleRecentTaxaItems = items?.filter(x => !x.inactive);
    }

    @ViewChild(ChipsComponent, { static: true }) private chipsComponent: ChipsComponent;
    private cachedTaxaTitles: any[] = [];
    private modalItems: any[] = [];

    private serviceAware: ServiceContract;
    private totalTaxaCount: number = 0;
    private totalHierarchicalTaxaCount: number = 0;

    private hierarchicalService: HierarchicalService;
    private editTaxonId: string = null;

    private modalItems$ = new ReplaySubject<TotalCountResult<any[]>>(1);
    private showAllLoading: boolean = true;
    private isInCreate: boolean = false;
    private retrieveRecentTaxaItems: boolean = true;
    private _recentTaxaItems = [];

    constructor(
        private modalService: ModalWindowService,
        protected route: ActivatedRoute,
        private dynamicItemService: DynamicItemService,
        @Optional() @Inject(HIERARCHICAL_SERVICE_TOKEN) private hierarchicalServices: Array<HierarchicalService>) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        this.retrieveRecentTaxaItems = !this.settings.skipInputSelection;
        this.initialize();

        this.chipsConfig.skipInputSelection = this.settings.skipInputSelection;
        this.addButtonContentType = this.settings.allowMultiple ? this.taxaNames.plural : this.taxaNames.singular;
    }

    getRequiredErrorMessage(): Array<string> {
        return [`${SelectorConstants.SELECT_BUTTON} ${this.settings.title}`];
    }

    onTaxaEntered(title: string): void {
        const taxonTitle = title.trim();
        if (!this.settings.allowCreate) {
            this.message = `You are not allowed to create ${this.settings.title}`;
            this.focusOutChips();
            return;
        }

        const entityData = this.entityData;
        if (this.settings.type !== TAXONOMY_CONSTANTS.FLAT_TAXA) {
            this.hierarchicalService.getSearchedItems({
                searchText: taxonTitle,
                taxaId: this.isInCreate ? null : this.settings.id,
                idsToExclude: this.value
            }, {
                entityData,
                fallbackProperties: [this.defaultFieldName]
            },
                this.editTaxonId)
                .pipe(first())
                .subscribe(data => {
                    if (data.dataItems && data.dataItems.length) {
                        const taxa = this.cloneAndAddFieldsToDataItems(data.dataItems);
                        this.addTaxa(taxa);
                    } else {
                        this.onCreateHierarchicalTaxa(taxonTitle);
                    }
                });
        } else if (taxonTitle) {
            this.addFakeTaxon(taxonTitle);
            this.createTaxon(taxonTitle, entityData)
                .subscribe(taxon => {
                    taxon = this.cloneAndAddFieldsToDataItems([taxon])[0];
                    const fakeTaxonIndex = this.removeFakeTaxon(taxonTitle);
                    this.addTaxon(taxon, fakeTaxonIndex);
                    this.getRecentTaxa();
                },
                    err => {
                        this.removeFakeTaxon(taxonTitle);
                        this.handleTaxaCreationError(err, taxonTitle);
                    });
        }
    }

    onSelectChip(chipItem: any) {
        if (chipItem.isSeparator) {
            return;
        } else if (chipItem.action && typeof chipItem.action === "function") {
            chipItem.action();
            return;
        }

        this.addTaxa([chipItem]);
        this.onSelectionChange.emit(chipItem.Id);
    }

    onSearchChips(title: string) {
        if (title) {
            const taxonTitle = title.trim();
            const filterByParent = !this.isInCreate || this.entityData.metadata.hasParent;
            const requestSynonymSearch = title.length >= 3 ? true : undefined;

            this.isSearchPending = true;
            this.hierarchicalService.getSearchedItems({
                searchText: taxonTitle,
                taxaId: filterByParent ? this.settings.id : null,
                idsToExclude: this.value
            }, {
                entityData: this.entityData,
                order: `${TITLE_KEY} ${SORT_ORDER.ASCENDING}`,
                take: RESULT_COUNT,
                fallbackProperties: [this.defaultFieldName]
            },
                this.editTaxonId,
                requestSynonymSearch)
                .pipe(first())
                .subscribe(data => {
                    const dataItems = this.cloneAndAddFieldsToDataItems(data.dataItems);
                    this.chipsConfig.focusFirstNode = !!dataItems.length;
                    this.recentTaxaItems = dataItems;
                    this.updateChipsConfig();
                    this.isSearchPending = false;
                });
        } else {
            this.chipsConfig.focusFirstNode = false;
            this.recentTaxaItems = this.cachedTaxaTitles;
            // search is triggered with "" when edit is pressed
            this.updateChipsConfig();
        }
    }

    onRemoveChip(chip: any) {
        let indexToRemove = this.taxa.findIndex(x => (x as any).Id === chip.Id);

        if (this.isHierarchical) {
            const count = this.countActualTaxons(this.recentTaxaItems);
            if (this.totalTaxaCount <= count) {
                this.totalTaxaCount = count + 1;
            }
        }

        const removedTaxa: any = this.taxa.splice(indexToRemove, 1)[0];

        // Counts separators and link buttons as "Show all 'something'" and "Create a category"
        let numberOfItemsToSkipFromBackToFront = 0;
        let removedItemIndex = -1;
        this.recentTaxaItems.forEach((item, index) => {
            if (item.isLink || item.isSeparator) {
                numberOfItemsToSkipFromBackToFront++;
            }

            if (item.Id === removedTaxa.Id) {
                removedItemIndex = index;
            }
        });

        const insertionIndex = this.recentTaxaItems.length - numberOfItemsToSkipFromBackToFront;
        this.taxaItems = this.taxa;
        // Insert the removed chip back to the recent items, before "Show all 'something'" and a separator, if not exist in recentTaxaItems
        if (insertionIndex < RESULT_COUNT && removedItemIndex === -1) {
            this.recentTaxaItems.splice(insertionIndex, 0, removedTaxa);
        }
        indexToRemove = this.value.indexOf(chip.Id);
        // We need to trigger value change using the writeValue method, that is why we create a copy of the value.
        // If we directly change it no value change callback is fired.
        const originalArray = this.value.slice();
        originalArray.splice(indexToRemove, 1);
        this.writeValue(originalArray);

        this.onSelectionChange.emit(null);
        this.updateChipsConfig();
    }

    writeValue(value: any) {
        if (typeof value === "string") {
            super.writeValue([value]);
            this.getItemTaxa();
        } else {
            super.writeValue(value);
        }
    }

    onReset() {
        this.value = [];
        this.taxa = [];
    }

    focusChips() {
        this.chipsComponent.initEditableField();
    }

    focusOutChips() {
        this.chipsComponent.onContentFocusOut();
    }

    onShowAllTaxa() {
        const componentData: ComponentData = {
            type: SelectorComponent,
            properties: {
                value: this.modalItems,
                value$: this.modalItems$,
                totalItemsCount: this.totalTaxaCount,
                selected: this.taxa.map(x => x),
                treeConfig: {
                    multiSelection: this.settings.allowMultiple,
                    isHierarchical: this.isHierarchical,
                    dataProperties: {
                        toolTipField: "tooltip",
                        alternativeTitleField: "additionalInfo"
                    }
                },
                serviceAware: this.serviceAware,
                typeNames: this.taxaNames,
                defaultField: this.defaultFieldName,
                expandPathPair: this.expandPathPair,
                isParentSelection: this.settings.isParentSelection,
                targetDataItem: this.getTargetDataItem(),
                loading: this.showAllLoading
            }
        };

        componentData.properties.treeConfig["status"] = this.hierarchicalService.showStatusIcons();

        if (this.settings.customShowAllTaxaFunction) {
            this.settings.customShowAllTaxaFunction(componentData);
        } else {
            const buttons: Button[] = [
                new ConfirmButton(SelectorConstants.USE_SELECTED),
                new CancelButton(SelectorConstants.CANCEL)
            ];
            const dialogData = new DialogData(componentData, (context) => this.onDone(context), buttons, null, "-bottom");

            this.modalService.setMapping(dialogData, SELECTOR_MAPPING_KEY);
            this.modalService.open(this.route, SELECTOR_MAPPING_KEY);
        }
    }

    onCreateHierarchicalTaxa(title?: string): void {
        const clonedSettings = cloneObject(this.settings);
        clonedSettings["rootTaxonId"] = stringConstants.DEFAULT_GUID;
        const buttons: Button[] = this.getCreateHierarchicalTaxaButtons((data: ClickData) => this.createHierarchicalTaxaHandler(data), this.taxaNames);
        const componentData: ComponentData = {
            type: CreateHierarchicalTaxaComponent,
            properties: {
                hierarchicalTaxaSettings: clonedSettings,
                typeName: this.route.snapshot.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT],
                title: title || null,
                taxaNames: this.taxaNames,
                otherTaxaExist: this.modalItems.length > 0,
                entityData: this.entityData,
                parentId: clonedSettings.id
            }
        };
        const dialogData = new DialogData(componentData, (context) => this.onCreate(context), buttons, "-prompt", "sf-form -medium -sf-centered-box -border-top -sf-txt-align-left -sf-mt-zero");

        this.modalService.setMapping(dialogData, "hierarchicalTaxa");
        this.modalService.open(this.route, "hierarchicalTaxa");
    }

    onFocusHandler(focus: boolean) {
        if (focus) {
            this.message = null;
            this.getRecentObservable?.subscribe(() => {
                if (this.settings.allowCreate || (this.recentTaxaItems && this.recentTaxaItems.length > 0)) {
                    this.onFocus();
                } else {
                    this.onShowAllTaxa();
                }
            });
        } else {
            this.onBlur();
        }
    }

    getWarnings(): Array<string> {
        if (!this.settings.allowView) {
            return [this.getNoPermissionMessage(this.taxaNames.plural)];
        }
        return super.getWarnings();
    }

    setCulture(culture: string) {
        this.entityData = DataItem.from(null, this.entityData.metadata, this.entityData.provider, culture);
    }

    setSiteId(siteId: string) {
        this.hierarchicalService.siteId = siteId;

        this.onReset();
        this.getModalItems().subscribe(() => {
            this.getRecentTaxa();
        });
    }

    protected getRecentTaxa() {
        this.getRecentObservable = this.hierarchicalService.getRecent(this.entityData, this.settings, this.value, this.editTaxonId, this.getTargetDataItem());

        this.getRecentObservable.subscribe(data => {
            const dataItems = data.dataItems;
            this.recentTaxaItems = this.cachedTaxaTitles = this.cloneAndAddFieldsToDataItems(dataItems);
            if (this.isHierarchical && this.totalHierarchicalTaxaCount < data.totalCount) {
                this.totalHierarchicalTaxaCount = data.totalCount;
            }

            if (this.settings.showMenuItems) {
                this.updateChipsConfig();
            } else {
                this.chipsConfig.actions = [];
            }
        });
    }

    protected onTaxaRetrieved() {
        // template method overridden in child classes to implement logic right after the taxa are retrieved
    }

    private createHierarchicalTaxaHandler(data: ClickData): Observable<ClickResult> {
        const clickResult$ = new BehaviorSubject<ClickResult>(new ClickResult(null, false));
        const component = data.component as CreateHierarchicalTaxaComponent;

        if (!component.editableFieldsComponent.valid()) {
            clickResult$.next(new ClickResult(null, false, true));
        } else {
            const dirtyFields = component.editableFieldsComponent.getFields();
            const entityData = this.entityData;
            const defaultFieldName = entityData.metadata.defaultFieldName || Properties.TITLE;
            const hierarchicalTaxaName = dirtyFields[defaultFieldName];
            let parentId = dirtyFields[Properties.PARENT_ID];

            this.createTaxon(hierarchicalTaxaName, entityData, parentId)
                .subscribe((taxon) => {
                    taxon = this.cloneAndAddFieldsToDataItems([taxon])[0];
                    this.addTaxon(taxon);
                    this.totalHierarchicalTaxaCount++;
                    clickResult$.next(new ClickResult(null, true));
                },
                    (err) => {
                        // TODO: fix handling of empty GUIDs in the backaend
                        parentId = parentId === stringConstants.DEFAULT_GUID ? null : parentId;
                        const query = createQuery()
                            .where()
                            .and()
                            .eq(Properties.PARENT_ID, parentId)
                            .or()
                            .startsWith(TITLE_KEY, hierarchicalTaxaName.trim())
                            .contains(TITLE_KEY, `${stringConstants.INTERVAL}${hierarchicalTaxaName.trim()}`)
                            .done()
                            .done()
                            .done();

                        this.dynamicItemService
                            .getItemList({
                                entityData,
                                query,
                                fallbackProperties: [this.defaultFieldName]
                            })
                            .subscribe(data => {
                                if (data.dataItems.length > 0) {
                                    const existingTaxon = this.cloneAndAddFieldsToDataItems([data.dataItems[0]])[0];
                                    this.addTaxon(existingTaxon);
                                    clickResult$.next(new ClickResult(null, true));
                                }
                            });
                    });
        }

        return clickResult$.asObservable();
    }

    private createTaxon(title: string, entityData: EntityData, parentId?: string) {
        const taxon: Taxon = {
            TaxonomyId: this.settings.id,
            Title: title
        };

        if (parentId) {
            taxon.ParentId = parentId;
        }

        return this.dynamicItemService.createItem({
            data: taxon,
            entityData
        });
    }

    private getCreateHierarchicalTaxaButtons(createHandler, taxaNames: TypeNames) {
        const buttons: Button[] = [
            new ConfirmButton(`Create this ${taxaNames.singular}`, createHandler),
            new CancelButton()
        ];

        return buttons;
    }

    protected getTaxaName() {
        const setName = this.hierarchicalService.getSetName();
        const entityData = this.getEntityData(setName);
        this.hierarchicalService.getName(entityData, this.settings.id)
            .subscribe(data => {
                if (data) {
                    const dataItems = data.dataItems;
                    if (dataItems && dataItems.length > 0) {
                        const taxa = this.cloneAndAddFieldsToDataItems([dataItems[0]])[0];
                        this.taxaNames = {
                            plural: taxa.Title.toLowerCase(),
                            singular: taxa.TaxonName.toLowerCase()
                        };
                    } else {
                        const metadata = data.entityData.metadata;
                        this.taxaNames = {
                            plural: metadata.displayName.toLowerCase(),
                            singular: metadata.singularName.toLowerCase()
                        };
                    }
                }

                this.addButtonTitle = "Select " + (this.settings.allowMultiple ? this.taxaNames.plural : this.taxaNames.singular);
            });
    }

    private expandChildren(info: ServiceInfo, isCreate: boolean = false): Observable<any> {
        if (info.take === undefined) {
            info.take = DEFAULT_CHILDREN_LOAD;
        }

        return this.hierarchicalService.expandChildren(info, this.entityData, this.settings.id, this.editTaxonId).pipe(
            map(data => {
                return { dataItems: this.cloneAndAddFieldsToDataItems(data.dataItems), totalCount: data.totalCount };
            }));
    }

    private loadMore(info: ServiceInfo, isCreate: boolean = false): Observable<any> {
        info.parentId = this.settings.id;
        return this.hierarchicalService.loadMore(info, this.entityData, this.settings, this.editTaxonId, isCreate).pipe(
            map(data => {
                return { dataItems: this.cloneAndAddFieldsToDataItems(data.dataItems), totalCount: data.totalCount };
            }));
    }

    private onDone(context: any) {
        if (!context.data || !context.data.data) {
            return;
        }

        const dialogueItems = context.component.selected;
        this.value = [];
        this.taxa = [];
        dialogueItems.forEach((taxon) => {
            this.addTaxon(taxon);
            this.onSelectionChange.emit(taxon.Id);
        });

        if (this.retrieveRecentTaxaItems) {
            this.getRecentTaxa();
        }

        this.onFocusHandler(false);
    }

    private onCreate(context: any) {
        // update modal items when new taxon is created to show the new items on showAll
        this.getRecentTaxa();
        this.getModalItems();
        this.onFocusHandler(false);
    }

    private getItemTaxa() {
        const val = this.getValue() || this.settings.defaultValue;
        if (val && val.length && val[0] !== stringConstants.DEFAULT_GUID) {
            this.isLoading = true;

            this.hierarchicalService.getItemTaxa(val, this.entityData, this.settings.id, this.isInCreate).subscribe(data => {
                const dataItems = data.dataItems;
                let taxonomies = this.cloneAndAddFieldsToDataItems(dataItems);
                if (val && dataItems.length) {
                    taxonomies = this.orderTaxasById(taxonomies, val);
                }

                this.updateTaxa(taxonomies);
                this.onTaxaRetrieved();

                if (this.isInCreate && dataItems.length === 0) {
                    this.writeValue(null);
                    this.onSelectionChange.emit(null);
                }
            },
                error => {
                    this.updateTaxa([]);
                    this.onErrorOccured.emit(error.message);
                });
        }
    }

    private updateChipsConfig() {
        let shouldShowAll = false;
        const recentTaxaItemsCount = this.countActualTaxons(this.recentTaxaItems);
        if (this.isHierarchical) {
            // When taxa is hierarchical we cannot rely on the count of this.modalItems since it does not hold the child items and that manifests the bug #302420
            // and so we cache the maximum taxa count upon receiving them. This is not needed when taxa is flat.
            let currentTaxaCount = recentTaxaItemsCount + this.countActualTaxons(this.taxaItems);

            if (this.chipsComponent.isEditing && this.taxa.length > 0 && this.isHierarchical) {
                // when taxa is in edit, we show the current item in the recent dropdown, but do not adjust for its count
                // and when there are 5 other items + 1 selected, for the total of 6
                // and we click edit, the total items that are to be shown in the dropdown are 6, and we need to show the "show all" option
                // so we adjust for it since it is present in the recent items as well as the selected items
                currentTaxaCount--;
            }
            shouldShowAll = this.isHierarchical ? this.totalHierarchicalTaxaCount > currentTaxaCount : this.totalTaxaCount > currentTaxaCount;
        } else {
            shouldShowAll = this.countActualTaxons(this.modalItems) > (recentTaxaItemsCount + this.countActualTaxons(this.taxaItems));
        }

        shouldShowAll = shouldShowAll || recentTaxaItemsCount > RESULT_COUNT || this.settings.forceShouldShowAll;

        this.chipsConfig.actions = [];

        if (shouldShowAll) {
            this.chipsConfig.actions.push({ label: `Show all ${this.taxaNames.plural}`, action: this.onShowAllTaxa.bind(this) });
        }

        if (this.settings.allowCreate && this.settings.type !== TAXONOMY_CONSTANTS.FLAT_TAXA) {
            this.chipsConfig.actions.push({ label: `Create ${getFormattedTypeName(this.taxaNames, false, true)}`, action: this.onCreateHierarchicalTaxa.bind(this) });
        }
    }

    private addTaxon(taxon: any, atIndex: number = -1) {
        if (!taxon) {
            return;
        }

        if (!this.value) {
            this.value = [];
        }

        if (this.value.includes(taxon.Id)) {
            return;
        }

        if (!this.settings.allowMultiple) {
            this.value.length = 0;
            this.taxa.length = 0;
        }

        if (atIndex !== -1) {
            this.value.splice(atIndex, 0, taxon.Id);
            this.taxa.splice(atIndex, 0, taxon);
        } else {
            this.value.push(taxon.Id);
            this.taxa.push(taxon);
        }
        this.taxaItems = this.taxa;

        if ((taxon.ParentId === stringConstants.DEFAULT_GUID || !this.isHierarchical) &&
            this.modalItems.filter(item => (item.Id === taxon.Id)).length === 0) {
            this.setHasChildren(taxon);
            if (atIndex !== -1) {
                this.modalItems.splice(atIndex, 0, taxon);
            } else {
                this.modalItems.push(taxon);
            }
        }

        this.onChangeCallback(this.value);
        this.isLoading = true;
    }

    private addFakeTaxon(fakeTaxonTitle: string) {
        if (!fakeTaxonTitle) {
            return;
        }

        if (!this.value) {
            this.value = [];
        }

        if (this.value.includes(fakeTaxonTitle) || this.taxa.findIndex(t => (<any>t).Title === fakeTaxonTitle) > -1) {
            return;
        }

        if (!this.settings.allowMultiple) {
            this.value.length = 0;
            this.taxa.length = 0;
        }

        this.taxa.push({ Title: fakeTaxonTitle, Id: FAKE_TAXA_ID });
        this.onChangeCallback(this.value);
        this.isLoading = true;
    }

    /**
     * returns the index of the taxon placeholder if such is found
     * @param fakeTitle the title of the taxon placeholder
     */
    private removeFakeTaxon(fakeTitle: any): number {
        const index = this.taxa.findIndex((tx: any) => tx.Title === fakeTitle && tx.Id === FAKE_TAXA_ID);
        if (index > -1) {
            this.taxa.splice(index, 1);
        }
        return index;
    }

    private updateTaxa(result: any[]): void {
        if (this.entityData.metadata.setName === ENTITY_SET.SITES) {
            const updatedResults = result.map(dataItem => {
                const clone = cloneObject(dataItem);
                this.setImmutableItemProperties(clone);
                return clone;
            });

            this.taxa = updatedResults;
            this.taxaItems = updatedResults;

        } else {
            this.taxa = result;
            this.taxaItems = result;
        }
    }

    private addTaxa(result: Object[]): void {
        this.addTaxon(result[0]);
        this.getRecentTaxa();
    }

    private handleTaxaCreationError(err: GenericError, taxonTitle: string): void {
        if (err instanceof ValidationError) {
            if (err.message === URL_EXISTS_KEY) {
                const doesTaxonExistLocally: boolean = this.taxaItems && this.taxaItems.some(x => (<any>x).Title === taxonTitle && x.Id !== FAKE_TAXA_ID);
                if (doesTaxonExistLocally) {
                    return;
                }

                let query = createQuery()
                    .where()
                    .and()
                    .eq(TAXONOMY_KEY, this.settings.id)
                    .eq(TITLE_KEY, taxonTitle);

                query = this.excludeCurrentItems(query).done().done() as any;

                this.dynamicItemService
                    .getItemList({
                        entityData: this.entityData,
                        query,
                        fallbackProperties: [this.defaultFieldName]
                    })
                    .subscribe(data => {
                        this.addTaxa(this.cloneAndAddFieldsToDataItems(data.dataItems));
                    });

                return;
            }
        }
    }

    protected orderTaxasById(newTaxa: any[], existingTaxa: any[]): any[] {
        const orderedTaxas: any[] = [];

        for (const id of existingTaxa) {
            const taxa: any = newTaxa.find(t => t.Id === id);
            if (taxa) {
                orderedTaxas.push(taxa);
            }
        }

        return orderedTaxas;
    }

    private getModalItems(): Observable<void> {
        const ready = new ReplaySubject<void>();
        const targetDataItem = this.getTargetDataItem();
        this.hierarchicalService.getModalItems(this.entityData, this.settings.id, this.editTaxonId, targetDataItem, this.settings.rootTaxonId)
            .pipe(first())
            .subscribe(result => {
                this.totalTaxaCount = result.totalCount;
                this.modalItems = this.cloneAndAddFieldsToDataItems(result.dataItems);
                this.placeImmutableItemsOntop();

                ready.next();
                this.modalItems$.next({ dataItems: this.modalItems, totalCount: result.totalCount });
                this.showAllLoading = false;
            });

        return ready.asObservable();
    }

    private placeImmutableItemsOntop() {
        if (this.settings.immutableitemIds) {
            const items = this.modalItems.slice();

            this.modalItems.map((element, index) => {
                if (this.settings.immutableitemIds?.indexOf(element.Id) >= 0) {
                    const removedTaxa: any = items.splice(index, 1)[0];
                    items.unshift(removedTaxa);
                }
                return element;
            });

            this.modalItems = items;
        }
    }

    private getTargetDataItem(): DataItem {
        if (!this.route.snapshot.data.itemData) {
            return null;
        }

        return this.route.snapshot.data.itemData.item || this.route.snapshot.data.itemData.entityData;
    }

    private getEntityData(setName: string): EntityData {
        const metadata = this.getMetadata();
        const entity = metadata.entities[setName];
        const entityData: EntityData = {
            culture: this.entityData ? this.entityData.culture : this.settings.culture,
            provider: undefined,
            metadata: entity
        };

        return entityData;
    }

    private cloneAndAddFieldsToDataItems(dataItems: DataItem[]): any[] {
        return dataItems.map(dataItem => {
            const clone = cloneObject(dataItem.data);
            clone.isTranslated = dataItem.isTranslated;
            this.setHasChildren(clone);
            this.setBreadcrumbPath(clone);
            this.setImmutableItemProperties(clone);

            return clone;
        });
    }

    private setImmutableItemProperties(dataItem) {
        const isItemMarkedAsImmutable = this.settings.immutableitemIds?.indexOf(dataItem.Id) >= 0;
        if (isItemMarkedAsImmutable) {
            dataItem.inactive = true;
            dataItem.isSelectionDisabled = true;
            dataItem.isReadOnly = true;
            if (this.entityData.metadata.setName === ENTITY_SET.SITES) {
                dataItem.additionalInfo = "this site";
            }
        }
    }

    private setBreadcrumbPath(dataItem) {
        if (!dataItem) {
            return;
        }
        const bc = dataItem.Breadcrumb;
        let title = dataItem.Title;
        if (Array.isArray(bc) && bc.length > 0) {
            title = `${bc.join(" > ")} > ${title}`;
        }
        dataItem.BreadcrumbPath = title;
    }

    private initialize(): void {
        if (!this.entityData) {
            this.entityData = this.getEntityData(this.settings.type);
        }

        const routeItemData = this.route.snapshot.data.itemData;
        if (routeItemData && routeItemData.entityData && routeItemData.entityData.metadata && this.entityData.metadata.setName === routeItemData.entityData.metadata.setName) {
            this.editTaxonId = routeItemData.entityData.key;
        }

        // Set default taxa names. Will be updated once we call getTaxaName()
        this.taxaNames = { plural: this.settings.title.toLowerCase(), singular: this.settings.title.toLowerCase() };
        const metadata = this.getMetadata();
        const entityMetadta = (metadata.entities[this.settings.type] as Entity);

        if (entityMetadta) {
            this.defaultFieldName = entityMetadta.defaultFieldName;
        }

        this.isInCreate = this.route.snapshot.data.itemData && this.route.snapshot.data.itemData.entityData.isEmpty;

        if (this.hierarchicalServices) {
            this.hierarchicalServices.forEach(service => {
                if (service.isTypeSupported(this.entityData)) {
                    this.hierarchicalService = service;
                }
            });
        }

        if (!this.hierarchicalService && this.settings.type && this.settings.key) {
            this.hierarchicalService = this.hierarchicalServices.find(serv => serv instanceof HierarchicalDynamicItemService);
            (this.hierarchicalService as HierarchicalDynamicItemService).setName = this.settings.type;
            (this.hierarchicalService as HierarchicalDynamicItemService).singularName = this.settings.key;
        } else if (!this.hierarchicalService) {
            return;
        }

        this.isHierarchical = this.hierarchicalService.isHierarchical(this.settings.type);
        this.dropdownChipsTreeConfig.status = this.hierarchicalService.showStatusIcons();

        this.getItemTaxa();

        if (!this.settings.readOnlyMode) {
            this.getTaxaName();

            this.serviceAware = new ServiceContract(
                (info: ServiceInfo) => this.loadMore(info, this.isInCreate),
                (info: ServiceInfo) => this.expandChildren(info, this.isInCreate));

            this.getModalItems().subscribe(() => {
                if (this.retrieveRecentTaxaItems) {
                    this.getRecentTaxa();
                }
            });
        }
    }

    private excludeCurrentItems(query: WhereQuery<WhereQuery<Query>>) {
        if (this.value) {
            this.value.forEach(id => {
                query = query.ne(ID_KEY, id);
            });
        }

        return query;
    }

    private setHasChildren(item) {
        if (this.isHierarchical && item.HasChildren) {
            item.hasChildren = item.HasChildren;
        }
    }

    private countActualTaxons(files: any[]): number {
        if (!files) {
            return 0;
        }

        return files.filter(file => { return !file.isSeparator && !file.isLink && !file.isHeading; }).length;
    }

    private getMetadata() {
        return this.route.parent?.snapshot.data[RESOLVE_NAMES.metadata] || this.route.snapshot.data[RESOLVE_NAMES.metadata];
    }
}
