import { filter } from "rxjs/operators";
import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges } from "@angular/core";
import { Observable, Subscription, zip } from "rxjs";
import { FilterStore } from "./filter.store";
import { ItemsState } from "../../../services/dynamic-item-store-state";
import { EntityData } from "../../../interfaces";
import { Filter, FiltersResult } from "./filter-interfaces";
import { ActivatedRoute } from "@angular/router";
import { FILTER_PARAMS } from "../../../../constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-filter-notification",
    templateUrl: "./filter-notification.component.html"
})
export class FilterNotificationComponent extends SfRxBase implements OnChanges {

    @Input() searchValue: string;
    @Input() filterValue: string;
    @Input() entityData: EntityData;
    @Input() itemsState: ItemsState;
    @Input() parentId: string;
    @Output() clearFilter = new EventEmitter<void>();
    predefinedFilter: Filter;
    hasCustomFilter: boolean;
    private filtersSubscription: Subscription;

    constructor(private filterStore: FilterStore, private route: ActivatedRoute) {
        super();
    }

    ngOnChanges(changes: SimpleChanges): void {
        const entityDataChange = changes["entityData"];
        const filterValueChange = changes["filterValue"];

        if (filterValueChange) {
            const currentFilter = filterValueChange.currentValue as string;
            if (!currentFilter) {
                this.predefinedFilter = null;
                this.hasCustomFilter = false;
                return;
            }
        }

        if ((entityDataChange || filterValueChange) && this.filterValue && this.route.snapshot.queryParams[FILTER_PARAMS.FILTER]) {
            if (this.filtersSubscription) {
                this.filtersSubscription.unsubscribe();
            }

            const predefinedFiltersObservable = this.getEntityFilters(this.entityData).pipe(filter(x => x && !x.isLoading));
            const dynamicFiltersObservable = this.filterStore.getDynamicFiltersCache(this.entityData, this.parentId);
            this.filtersSubscription = zip(predefinedFiltersObservable, dynamicFiltersObservable).subscribe((data) => {
                const predefinedFilters: Filter[] = data[0] && data[0].filters ? data[0].filters : [];
                const dynamicFilters: Filter[] = data[1] || [];

                const allFilters = predefinedFilters.concat(dynamicFilters);

                this.predefinedFilter = allFilters.find(f => f.name === this.filterValue);
                this.hasCustomFilter = !this.predefinedFilter;
            });

            this.registerSubscription(this.filtersSubscription);
        }
    }

    onClearFilter(): void {
        this.clearFilter.emit();
    }

    private getEntityFilters(entityData: EntityData): Observable<FiltersResult> {
        return this.filterStore.getPredefinedFilters(entityData);
    }
}
