import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { BackendTweaksStore } from "./backend-tweaks.store";
import { DynamicItemStrategyBase } from "../../components/strategies/dynamic-item.strategy";

@Injectable()
export class BackendTweaksGridResolver implements Resolve<any> {
    constructor(private backendTweaksStore: BackendTweaksStore) {
    }

    // NOTE: we are waiting for bug in that issue to be released: https://github.com/angular/angular/issues/12148
    // Until then when navigating with full URL towards editing screen or grid list, the views will get loaded before metadata store loads its content
    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Promise<boolean> | boolean {
        const contentType = DynamicItemStrategyBase.getSet(route.parent);

        /**
         * TODO: We need to discuss with the UX team the behavior, when the backend tweaks service fails
         * because now the component will be created but the view will be broken.
         * But this depends on the UX and how we will deal with error handling at all.
         */
        return this.backendTweaksStore.initializeGrid(contentType);
    }
}
