import { createReducer, on, combineReducers, ActionReducer, Action } from "@ngrx/store";
import { SIDEBAR_ACTIONS, __SidebarChangeInternalAction__, __SidebarConfigInternalAction__, SidebarClearAllDataAction } from "../actions/actions.sidebar";
import { initialState, AppState } from "../store-schema";
import { SidebarData, SidebarConfig } from "../../../modules/shared/components/sidebar/sidebar.common";
import { SidebarState, sidebarInitialState } from "../schemas/schema.sidebar";

const sidebarDataReducer = createReducer<SidebarData>(initialState.sidebar.sidebarData,
    on(__SidebarConfigInternalAction__, (state, { sidebarData }) => {
        return Object.assign({}, sidebarData);
    }));

const sidebarActiveConfigReducer = createReducer<SidebarConfig>(initialState.sidebar.activeConfig,
    on(__SidebarChangeInternalAction__, (state, { activeConfig }) => {
        return Object.assign({}, activeConfig);
    }));

const sidebarOpenCloseReducer = createReducer<boolean>(initialState.sidebar.isOpen,
    on(SIDEBAR_ACTIONS.changeAndOpen, state => true),
    on(SIDEBAR_ACTIONS.open, state => true),
    on(SIDEBAR_ACTIONS.close, state => false)
);

const sidebarLoadingReducer = createReducer<boolean>(initialState.sidebar.isLoading,
    on(SIDEBAR_ACTIONS.loading, state => true)
);

const sidebarShouldAnimateReducer = createReducer<boolean>(initialState.sidebar.shouldAnimate,
    on(SIDEBAR_ACTIONS.changeAndOpen, (state, { activeConfig: activeConfig, shouldAnimate: shouldAnimate }) => {
        if (shouldAnimate) {
            return true;
        }

        return false;
    }),
    on(SIDEBAR_ACTIONS.setShouldAnimate, (state, { shouldAnimate: shouldAnimate }) => shouldAnimate),
    on(SIDEBAR_ACTIONS.close, (state, { shouldAnimate: shouldAnimate }) => {
        if (shouldAnimate) {
            return true;
        }

        return false;
    })
);

/**
 * Full combined reducer for the sidebar feature state
 */
export const sidebarReducer = combineReducers<SidebarState>({
    sidebarData: sidebarDataReducer,
    isOpen: sidebarOpenCloseReducer,
    isLoading: sidebarLoadingReducer,
    activeConfig: sidebarActiveConfigReducer,
    shouldAnimate: sidebarShouldAnimateReducer
});

/**
 * Metareducer for clearing the sidebar feature state
 */
export const sidebarMetaReducer = function (reducer: ActionReducer<any>): ActionReducer<any> {
    return function clearStateFn (state: AppState, action: Action) {
        if (action.type === SidebarClearAllDataAction.type) {
            state.sidebar = Object.assign({}, sidebarInitialState);
        }

        return reducer(state, action);
    };
};
