import { Directive, ElementRef, Input, Inject, EventEmitter, Output, OnChanges, AfterViewInit } from "@angular/core";
import { WINDOW_TOKEN } from "../../../src/app/window.provider";
import { Point } from "../../types/types";
import { NotificationPosition } from "@progress/sitefinity-component-framework";

@Directive({
    selector: "[sfTooltipPosition]",
    exportAs: "sfTooltipPosition"
})
export class TooltipPositionDirective implements OnChanges, AfterViewInit {
    @Input() tooltipPositionParams: TooltipPositionParams;
    @Output() positionChange: EventEmitter<string> = new EventEmitter<string>();

    private tooltipBoundingRect: any;

    constructor(@Inject(WINDOW_TOKEN) private window: Window,
                private element: ElementRef) { }

    ngOnChanges(changes: any) {
        this.positionToolset();
    }

    ngAfterViewInit() {
        this.tooltipBoundingRect = this.element.nativeElement.getBoundingClientRect();
        this.positionToolset();
    }

     private positionToolset(): void {
        if (this.tooltipBoundingRect) {
            this.element.nativeElement.style.top = this.setToolsetTop();
            this.element.nativeElement.style.left = this.setToolsetLeft();

            if (this.tooltipPositionParams.position) {
                this.positionChange.emit(this.tooltipPositionParams.position);
            }

            this.tooltipBoundingRect = this.element.nativeElement.getBoundingClientRect();

            this.checkIfToolsetOverflowing();
        }
    }

    private setToolsetTop(): string {
        let elementTopPosition = this.tooltipPositionParams.elementPosition.top + this.tooltipPositionParams.elementPosition.height;

        if (this.tooltipPositionParams.position === NotificationPosition.Up) {
            elementTopPosition = this.tooltipPositionParams.elementPosition.top;
        }

        return `${elementTopPosition}px`;
    }

    private setToolsetLeft(): string {
        let elementLeftPosition = this.tooltipPositionParams.elementPosition.left + (this.tooltipPositionParams.elementPosition.width / 2);

        if (this.tooltipPositionParams.elementPosition.left + this.tooltipPositionParams.elementPosition.width > this.tooltipPositionParams.parentPosition.width) {
            elementLeftPosition = this.tooltipPositionParams.parentPosition.width / 2;
        }

        return `${elementLeftPosition}px`;
    }

    private checkIfToolsetOverflowing(): void {
        if (this.tooltipBoundingRect.right > this.window.innerWidth) {
            this.element.nativeElement.style.top = `${this.tooltipPositionParams.elementPosition.top + (this.tooltipPositionParams.elementPosition.height / 2)}px`;
            this.element.nativeElement.style.left = `${this.tooltipPositionParams.elementPosition.left - this.tooltipBoundingRect.width - 20}px`;

            this.positionChange.emit(NotificationPosition.Left);
            return;
        }

        if (this.tooltipBoundingRect.left < 0) {
            this.element.nativeElement.style.top = `${this.tooltipPositionParams.elementPosition.top + (this.tooltipPositionParams.elementPosition.height / 2)}px`;
            this.element.nativeElement.style.left = `${this.tooltipPositionParams.elementPosition.left + this.tooltipPositionParams.elementPosition.width}px`;

            this.positionChange.emit(NotificationPosition.Right);
            return;
        }

        if (this.tooltipBoundingRect.bottom > this.window.innerHeight) {
            this.element.nativeElement.style.top = `${this.tooltipPositionParams.elementPosition.top}px`;

            this.positionChange.emit(NotificationPosition.Up);
        }
    }
}

export interface TooltipPositionParams {
    elementPosition?: DOMRect;
    parentPosition?: DOMRect;
    mousePosition?: Point;
    position?: string;
}
