export const ACTIONS = {
    FILTER: (filterName: string): string => `filters(name=@sf_filter)?@sf_filter='${filterName}'`,
    FILTER_VALUES: (filterName: string): string => `filterValues(name=@sf_name)?@sf_name='${filterName}'`,
    DYNAMIC_FILTERS: (parentId: string): string => `dynamicFilters(parentId=@sf_parent)?@sf_parent='${parentId}'`,
    FILTERS_COUNT: (filterName: string): string => `filtersCount(name=@sf_filter)?@sf_filter='${filterName}'`,
    FOLDERS: (parentId?: string): string => {
        let action = "folders";

        if (parentId !== undefined) {
            action += `?parentId=${parentId}`;
        }

        return action;
    }
};

