
import { ClassProvider, Injectable } from "@angular/core";
import { GridExtenderBase, GRID_EXTENDER_TOKEN } from "../../../shared/services/grid/grid-extender-base";
import { CONTENT_ITEM_FULL_NAME } from "../../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../../../content/dynamic-modules/interfaces";

@Injectable()
export class ContentBlocksGridExtender extends GridExtenderBase {

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.typeFullName === CONTENT_ITEM_FULL_NAME;
    }
}

export const CONTENT_BLOCKS_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: ContentBlocksGridExtender
};
