import { Inject, Injectable } from "@angular/core";
import { WINDOW_TOKEN } from "../../../window.provider";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";

const ZONE_EDITOR_TOOLBAR_PROP_NAME = "editorToolBar";
const ZONE_EDITOR_PROP_NAME = "zoneEditor";

@Injectable()
export class ZoneEditor {
    private readonly toolbarInstance: any;
    private readonly zoneEditorInstance: any;

    constructor(@Inject(WINDOW_TOKEN) window: Window) {
        this.toolbarInstance = window[ZONE_EDITOR_TOOLBAR_PROP_NAME];
        this.zoneEditorInstance = window[ZONE_EDITOR_PROP_NAME];
    }

    handleCompletedWorkflowOperation(operationName: string) {
        if (operationName === OPERATION_NAMES.schedule) {
            this.handleSaveDraftSuccess();
            return;
        }

        const args = {
            get_commandName() {
                return operationName;
            },
            get_commandArgument() {
                return operationName;
            }
        };

        this.invokeSafeFunction("_workflowMenuCommandHandler", null, args);
    }

    getHasChanges() {
        if (this.zoneEditorInstance)
            return this.zoneEditorInstance.get_isChangeMade();

        return false;
    }

    private handleSaveDraftSuccess() {
        this.invokeSafeFunction("_markNoPendingChanges");
    }

    private invokeSafeFunction(functionName: string, ...args: any[]) {
        if (this.toolbarInstance && typeof this.toolbarInstance[functionName] === "function") {
            this.toolbarInstance[functionName](...args);
        }
    }
}
