import { throwError as observableThrowError,  Observable } from "rxjs";
import { Injectable } from "@angular/core";
import { BehaviorSubject } from "rxjs";

import { HttpODataRequestWrapper } from "../http-odata-request.wrapper";
import { filter, map } from "rxjs/operators";

@Injectable()
export class UserDataStore {
    get userId(): string {
        const userData = this.userData.getValue();
        return userData ? userData.Id : null;
    }

    private userData: BehaviorSubject<UserData> = new BehaviorSubject(null);

    constructor(private http: HttpODataRequestWrapper) { }

    getValue() {
        return this.userData.getValue();
    }

    initialize(): Observable<UserData> | UserData {
        if (this.userData.getValue() !== null)
            return this.userData.getValue();

        this.http.get("users/current")
        .then(data => {
            this.userData.next(data.value);
            this.userData.complete();
        }, error => observableThrowError(error));

        return new Observable<UserData>(fn => this.userData.subscribe(fn));
    }

    getPreference(key: string) {
        const data = this.getValue();
        if (!key || !data.Preferences) {
            return null;
        }

        const encodedKey = encodeURIComponent(key);
        const encodedValue = data.Preferences[encodedKey];
        if (!encodedValue) {
            return null;
        }

        return decodeURIComponent(encodedValue);
    }

    setPreference(key: string, value: any) {
        const data = {
            key: encodeURIComponent(key),
            value: encodeURIComponent(value)
        };

        this.http.post$("userpreference", data)
            .pipe(
                filter(x => !x.isLoading),
                map(x => x.content)
            )
            .subscribe(newPreferences => {
                const data = this.getValue();
                data.Preferences = newPreferences as any;
            });
    }

    deletePreference(key: string) {
        this.setPreference(key, null);
    }
}

export interface UserData {
    Id: string;
    Username: string;
    Email: string;
    FirstName: string;
    LastName: string;
    Avatar: string;
    Preferences: { [key: string]: string; };
}
