import { Injectable } from "@angular/core";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { Observable } from "rxjs";
import { map, filter } from "rxjs/operators";
import { Settings } from "../../shared/services/settings.service";
import { stringConstants } from "../../../common-constants";
import { HttpODataRequestWrapper } from "../../shared/services/http-odata-request.wrapper";

@Injectable()
export class PageService {
    constructor(private httpWrapper: HttpODataRequestWrapper, private settings: Settings) {
    }

    getByUrl(pageRelativeUrl: string, entityData: EntityData): Observable<DataItem> {
        const pageUrl = this.getPageAbsoluteUrl(pageRelativeUrl).replace(/'/g, "''");
        return this.httpWrapper.get$(`${entityData.metadata.setName}/Default.GetPageByUrl(url=@param)?@param='${pageUrl}'`)
            .pipe(
                filter(state => !state.isLoading),
                map(state => DataItem.from(state.content, entityData.metadata, entityData.provider, entityData.culture))
            );
    }

    private getPageAbsoluteUrl(pageRelativeUrl: string) {
        let rootUrl = this.settings.url;
        if (rootUrl.endsWith(stringConstants.FORWARD_SLASH)) {
            rootUrl = rootUrl.substr(0, rootUrl.length - 1);
        }

        return `${rootUrl}${pageRelativeUrl}`;

    }
}
