import { Injectable, Inject, NgZone } from "@angular/core";
import { DynamicItemStore } from "./dynamic-item.store";
import { BehaviorSubject, Subject, Observable, ReplaySubject, Subscription } from "rxjs";
import { stringConstants } from "../../../../common-constants";
import { UnboundFunctionData } from "./dynamic-item.service";
import { EntityData, DataItem } from "../interfaces";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ProviderStore } from "./provider-store";
import { BackgroundTaskDataParser, TaskDataParsedBase, MoveToLibraryTaskDataParsed } from "../components/long-running-services/background-task-data-parser";
import { ExtendedBackgroundTask, BackgroundTask, TaskStatus, TaskAction, BackgroundTaskType, TaskType } from "./background-task.types";
import { tap, first, map } from "rxjs/operators";
import { ComponentCommunicationService } from "../../../shared/services/component-communication.service";
import { LongRunningTaskCompleted } from "../../../shared/events/component-events";
import { ReindexTaskDataParsed, SearchBackgroundTaskDataParser } from "../components/long-running-services/search-background-task-data-parser";

export const DONE_TASK_TIMEOUT = 5 * 1000;
export const LONG_RUNNING_TASK_STARTED = "longRunningTaskStarted";
export const LONG_RUNNING_TASK_COMPLETED = "longRunningTaskCompleted";
export const QUICK_TIMEOUT = 3 * 1000;
export const SLOW_TIMEOUT = 60 * 1000;

@Injectable()
export class LongRunningTasksService {
    public progress: BehaviorSubject<ExtendedBackgroundTask[]> = new BehaviorSubject([]);

    private onProgress: Subject<BackgroundTask[]> = new Subject();

    private static timerId;
    private static subscription = null;
    private entityData: EntityData;
    private progressSubscription: Subscription;

    constructor(private dynamicItemStore: DynamicItemStore,
                @Inject(WINDOW_TOKEN) private window: Window,
                private zone: NgZone,
                private providerStore: ProviderStore,
                private communicationService: ComponentCommunicationService) {
        if (LongRunningTasksService.subscription) {
            LongRunningTasksService.subscription.unsubscribe();
        }

        this.stopService();

        LongRunningTasksService.subscription = this.onProgress.subscribe((progress: BackgroundTask[]) => {
            const currentProgress = this.progress.getValue();

            currentProgress.forEach((task, i) => {
                const existingTask = progress.find(x => task.Id === x.Id);
                if (!existingTask) {
                    this.processCompletedOrDeletedTask(currentProgress, task, i);
                }
            });

            progress.forEach(p => {
                const foundCurrentIndex = currentProgress.findIndex(current => {
                    return p.Id === current.Id;
                });

                if (foundCurrentIndex >= 0) {
                    const foundTask = currentProgress[foundCurrentIndex] as ExtendedBackgroundTask;
                    this.updateTaskValues(foundTask, p);
                } else {
                    currentProgress.push(<ExtendedBackgroundTask>Object.assign(p, { lastUpdateDate: Date.now() }));
                }
            });

            this.progress.next(currentProgress);
            this.initTimer(currentProgress);
        });
    }

    public init(entityData: EntityData) {
        this.entityData = entityData;
        if (this.progressSubscription) {
            this.progressSubscription.unsubscribe();
        }

        this.progress.next([]);
        this.getProgress(entityData);
    }

    public getTasks(entityData: EntityData): Observable<BackgroundTask[]> {
        return new Observable((observer) => {
            this.executeServiceCall(entityData).subscribe(tasks => {
                observer.next(tasks);
            });
        });
    }

    public refresh() {
        this.getProgress(this.entityData);
    }

    public start(id: string, taskType: TaskType): Observable<BackgroundTask[]> {
        return this.manageTask(id, taskType, null).pipe(tap(task => {
            const event = new CustomEvent(LONG_RUNNING_TASK_STARTED);
            this.window.dispatchEvent(event);
            this.addTask(task[0]);
        }));
    }

    public stop(id: string) {
        this.manageTask(id, null, TaskAction.Stop).subscribe(task => {
            this.updateTask(task[0]);
        });
    }

    public resume(id: string) {
        this.manageTask(id, null, TaskAction.Resume).subscribe(task => {
            this.updateTask(task[0]);
        });
    }

    public retry(id: string) {
        this.manageTask(id, null, TaskAction.Restart).subscribe(task => {
            this.updateTask(task[0]);
        });
    }

    public delete(id: string) {
        this.manageTask(id, null, TaskAction.Delete).subscribe(x => {
            const currentProgress = this.progress.getValue();
            const taskIndex = currentProgress.findIndex(t => t.Id === id);
            if (taskIndex > -1) {
                // explicitly set status to 'Failed' because on the server when we delete a task we set it to status 'Stopped'
                // and if during this duration the service have called the tasks we have it with status 'Stopped' not status 'Failed'
                currentProgress[taskIndex].Status = TaskStatus[TaskStatus.Failed.toString()];
                this.onProgress.next(currentProgress.filter(x => x.Id !== id));
            }
        });
    }

    public stopService() {
        this.entityData = null;

        if (LongRunningTasksService.timerId) {
            this.window.clearInterval(LongRunningTasksService.timerId);
        }
    }

    public initTimer(tasks: BackgroundTask[] = []) {
        if (LongRunningTasksService.timerId) {
            this.window.clearInterval(LongRunningTasksService.timerId);
        }

        const timeout = this.determineTimeout(tasks);
        this.zone.runOutsideAngular(() => {
            LongRunningTasksService.timerId = this.window.setInterval(() => this.getProgress(this.entityData), timeout);
        });
    }

    private addTask(task: BackgroundTask) {
        const currentProgress = this.progress.getValue();
        this.onProgress.next([...currentProgress, task]);
    }

    private updateTask(task: BackgroundTask) {
        const currentProgress = this.progress.getValue();
        this.onProgress.next(currentProgress.map(x => x.Id === task.Id ? task : x));
    }

    private updateTaskValues(target: ExtendedBackgroundTask, source: BackgroundTask) {
        const targetInitialStatus = target.Status;

        target.Description = source.Description;
        target.ProgressStatus = source.ProgressStatus;
        target.Status = source.Status;
        target.StatusMessage = source.StatusMessage;
        target.TaskName = source.TaskName;
        target.lastUpdateDate = Date.now();

        if (targetInitialStatus !== source.Status) {
            this.triggerUpdateGrid(target);
        }
    }

    private determineTimeout(tasks: BackgroundTask[]): number {
        let timeout = QUICK_TIMEOUT;

        if (tasks.filter(x => TaskStatus[x.Status.toString()] !== TaskStatus.Failed && TaskStatus[x.Status.toString()] !== TaskStatus.Stopped).length === 0) {
            timeout = SLOW_TIMEOUT;
        }

        return timeout;
    }

    private getProgress(entityData: EntityData, shouldRefreshStore: boolean = true) {
        if (!entityData) {
            this.stopService();
            return;
        }

        if (!this.progressSubscription || this.progressSubscription.closed) {
            this.progressSubscription = this.executeServiceCall(entityData)
                .subscribe(value => {
                    this.onProgress.next(value);
                });
        }
    }

    private executeServiceCall(entityData: EntityData): Observable<BackgroundTask[]> {
        return this.dynamicItemStore.service.executeBoundFunction(DataItem.emptyItem(entityData), `Default.BackgroundTasks(taskType='${stringConstants.EMPTY_STRING}')`)
            .pipe(map((res: { value: BackgroundTask[] }) => {
                return res.value;
            }));
    }

    private manageTask(id: string, taskType: TaskType, action: TaskAction): Observable<BackgroundTask[]> {
        const return$ = new ReplaySubject<BackgroundTask[]>(1);
        const functionData: UnboundFunctionData = {
            data: {
                itemId: id,
                taskType: Object.values(TaskType).includes(taskType) ? taskType.toString() : stringConstants.EMPTY_STRING,
                action: Object.values(TaskAction).includes(action) ? action.toString() : stringConstants.EMPTY_STRING
            },
            culture: null,
            provider: this.providerStore.currentProvider
        };

        this.dynamicItemStore.service
            .executeUnboundFunction<{ value: BackgroundTask[] }>("Default.ManageBackgroundTasks", functionData)
            .subscribe((res: { value: BackgroundTask[] }) => {
                return$.next(res.value);
                return$.complete();
            },
                error => {
                    return$.error(error);
                });

        return return$.pipe(first());
    }

    private processCompletedOrDeletedTask(currentProgress: BackgroundTask[], task: ExtendedBackgroundTask, index: number) {
        const taskStatus: TaskStatus = TaskStatus[task.Status.toString()];
        switch (taskStatus) {
            case TaskStatus.Failed:
                currentProgress.splice(index, 1);
                this.triggerUpdateGrid(task);
                break;
            // This case can be hit when the task completes very quickly and the state is not updated from pending to started
            // Due to the UX requirement we manually update the status: pending -> started -> done
            case TaskStatus.Pending:
                task.ProgressStatus = "50";
                task.Status = TaskStatus[TaskStatus.Started.toString()];
                task.lastUpdateDate = Date.now();
                break;
            case TaskStatus.Started:
                task.ProgressStatus = "100";
                task.Status = TaskStatus[TaskStatus.Done.toString()];
                task.lastUpdateDate = Date.now();
                break;
            case TaskStatus.Done:
                if (Date.now() - task.lastUpdateDate > DONE_TASK_TIMEOUT) {
                    currentProgress.splice(index, 1);
                    this.triggerUpdateGrid(task);
                }
                break;
        }
    }

    private triggerUpdateGrid(task: ExtendedBackgroundTask): void {
        const event = new CustomEvent(LONG_RUNNING_TASK_COMPLETED, { detail: { taskStatus: task.Status, taskName: task.TaskName } });
        this.window.dispatchEvent(event);
        this.communicationService.next(new LongRunningTaskCompleted());
    }
}

export function generateRunningTaskError(task: BackgroundTask, targetId: string): string {
    if (!task) { return null; }
    let taskType = "performing another task";

    switch (task.TaskName) {
        case BackgroundTaskType.RegenerateThumbnails:
            taskType = "regenerating thumbnails";
            break;
        case BackgroundTaskType.MoveLibrary:
        case BackgroundTaskType.MoveLibraryAlternative:
            const data = BackgroundTaskDataParser.parse(task) as MoveToLibraryTaskDataParsed;
            if (targetId && data.libraryId === targetId) {
                taskType = "moving items to this library";
            } else {
                taskType = "moving to another library";
            }
            break;
        case BackgroundTaskType.StorageRelocation:
        case BackgroundTaskType.StorageRelocationAlternative:
        case BackgroundTaskType.ChangeLibraryUrl:
            if (task.Title === "RelocateLibrary") {
                taskType = "generating new URLs";
            } else {
                taskType = "moving to another storage";
            }
            break;
    }

    return `Disabled while ${taskType}`;
}

export function getItemIdFromTaskData(task: ExtendedBackgroundTask): string {
    if (task.TaskData) {
        return (BackgroundTaskDataParser.parse(task) as TaskDataParsedBase).libraryId;
    } else {
        return null;
    }
}

export function getItemsFromTaskData(task: BackgroundTask): string[] {
    let itemsIds = [];
    if (task.TaskName === BackgroundTaskType.MoveLibraryAlternative) {
        const taskData = BackgroundTaskDataParser.parse(task) as MoveToLibraryTaskDataParsed;
        if (taskData.itemIds) {
            itemsIds = taskData.itemIds.concat(taskData.libraryId);
        } else {
            itemsIds = [taskData.itemId];
        }
        itemsIds.push(taskData.newItemId);
    } else if (task.TaskName === BackgroundTaskType.Reindex) {
        const taskData = SearchBackgroundTaskDataParser.parse(task) as ReindexTaskDataParsed;
        itemsIds = [taskData.indexId];
    } else {
        // task.TaskName === BackgroundTaskType.RegenerateThumbnails)
        const taskData = BackgroundTaskDataParser.parse(task) as TaskDataParsedBase;
        itemsIds = [taskData.libraryId];
    }

    return itemsIds.filter(id => id !== stringConstants.DEFAULT_GUID);
}

export function getRunningTasksAndMap(currentTasks: BackgroundTask[]): { [key: string]: BackgroundTask } {
    const mappedTasks: { [key: string]: BackgroundTask } = {};
    currentTasks.forEach(t => {
        const itemIds = getItemsFromTaskData(t);
        itemIds.forEach(id => {
            mappedTasks[id] = t;
        });
    });

    return mappedTasks;
}
