import { ClassProvider, Injectable, Inject } from "@angular/core";
import { Observable, of } from "rxjs";
import { map, switchMap } from "rxjs/operators";
import { EntityData } from "../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../content/dynamic-modules/services/dynamic-item.store";
import { GridReloadService } from "../content/dynamic-modules/services/grid-reload.service";
import { OPERATION_NAMES } from "../shared/components/action-menu/operation.model";
import { GRID_EXTENDER_TOKEN, GridActionContext, GridExtenderBase } from "../shared/services/grid/grid-extender-base";
import { ModalWindowService } from "../shared/services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../shared/services/notification/notification.service";
import { Settings } from "../shared/services/settings.service";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { COMMAND_NAMES } from "../content/dynamic-modules/components/commands";
import { BackendTweaksStore } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { SortService } from "../shared/services/sort.service";
import { ContentFilterService } from "../shared/services/content-filter.service";
import { FormsActionHandler } from "./forms-action-handler.service";
import { ColumnModel } from "../shared/models/column-model";
import { Properties } from "../shared/fields.constants";
import { ExternalAppConfigService } from "../../app-config/external-app-config.service";
import { FormsShareWithCommand } from "./commands/forms-share-with.command";
import { ExecutionContext } from "../../api/v1/commands/execution-context";
import { CompositeOperationsProvider } from "../content/dynamic-modules/services/operations/operations-provider";

@Injectable()
export class FormsGridExtender extends GridExtenderBase {
    constructor(
        private formsActionHandler: FormsActionHandler,
        settings: Settings,
        modalWindowService: ModalWindowService,
        dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        reloadService: GridReloadService,
        contentFilterService: ContentFilterService,
        sortService: SortService,
        backendTweaksStore: BackendTweaksStore,
        externalAppConfigService: ExternalAppConfigService,
        operationsProvider: CompositeOperationsProvider) {
        super(contentFilterService, dynamicItemStore, settings, sortService, backendTweaksStore, reloadService, modalWindowService, notificationService, externalAppConfigService, operationsProvider);
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.FORMS;
    }

    tryHandleAction(context: GridActionContext): Observable<boolean> {
        const actionName = context.actionName;

        if (actionName === COMMAND_NAMES.selectionChanged) {
            return this.tryHandleAction({
                actionName: OPERATION_NAMES.editContent,
                item: context.item,
                route: context.route,
                grid: context.grid
            });
        }

        if (actionName === OPERATION_NAMES.create) {
            return this.formsActionHandler.navigateToEdit(context);
        }

        if (actionName === OPERATION_NAMES.edit) {
            return this.formsActionHandler.navigateToTitleAndProperties(context).pipe(map(x => !!x));
        }

        if (actionName === OPERATION_NAMES.duplicate) {
            return this.formsActionHandler.navigateToDuplicate(context).pipe(map(x => !!x));
        }

        if (actionName === OPERATION_NAMES.shareWith) {
            return of(this.tryHandleShareWithAction(context));
        }

        return super.tryHandleAction(context).pipe(switchMap(result => {
            if (result) {
                return of(result);
            }

            return this.formsActionHandler.tryHandleAction(context);
        }));
    }

    tryHandleShareWithAction(context: GridActionContext): boolean {
        const ctx: ExecutionContext = {
            currentRoute: context.route,
            data: {
                entityData: context.item
            },
            model: null
        };

        const command = new FormsShareWithCommand(this.dynamicItemStore.service, this.modalWindowService);
        command.execute(ctx).subscribe((data) => {
            if (data.success) {
                this.reloadService.requestReload();
            }
        });

        return true;
    }

    getDataFieldNames(columns: ColumnModel[], entityData: EntityData): string[] {
        const dataFieldNames = super.getDataFieldNames(columns, entityData);

        if (dataFieldNames.indexOf(Properties.RENDERER) === -1) {
            dataFieldNames.push(Properties.RENDERER);
        }

        // We don't want to add the Name as a column,
        // it is only needed for opening the form responses grid
        if (dataFieldNames.indexOf(Properties.NAME) === -1) {
            dataFieldNames.push(Properties.NAME);
        }

        return dataFieldNames;
    }
}

export const FORMS_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: FormsGridExtender
};
