import { Component } from "@angular/core";
import { ReplaySubject } from "rxjs";
import { TreeConfig } from "../../../../../../fields";
import { LibrariresNavigationSidebarHelpers } from "../../services/libraries-navigation-sidebar-helpers";
import { DataItem } from "../../../content/dynamic-modules/interfaces";

interface LoadingItem {
    itemId: string;
    loading: boolean;
}

export interface LibrariesNavigationSidebarComponentProps {
    currentRoot$: ReplaySubject<DataItem>;
    currentLevelItems$: ReplaySubject<DataItem[]>;
    currentRootTitle$: ReplaySubject<string>;
    backButtonTitle$: ReplaySubject<string>;
    sidebarHelpers: LibrariresNavigationSidebarHelpers;
    hasBackNavigation$: ReplaySubject<boolean>;
    allItemsLoading$: ReplaySubject<boolean>;
}

@Component({
    selector: "sf-libraries-navigation-sidebar",
    templateUrl: "./libraries-navigation-sidebar.component.html"
})
export class LibrariesNavigationSidebarComponent implements LibrariesNavigationSidebarComponentProps {
    currentRoot$ = new ReplaySubject<DataItem>(1);
    itemIcon: string = "folder-open-o";
    currentLevelItems$ = new ReplaySubject<DataItem[]>(1);
    currentRootTitle$ = new ReplaySubject<string>(1);
    backButtonTitle$ = new ReplaySubject<string>(1);
    sidebarHelpers: LibrariresNavigationSidebarHelpers;
    treeConfig: TreeConfig = {
        noSelection: true,
        multiSelection: false,
        treeProperties: {
            idField: "id"
        },
        isHierarchical: false
    };
    allItemsLoading$ = new ReplaySubject<boolean>(1);
    singleItemLoading: LoadingItem = { itemId: null, loading: false };
    hasBackNavigation$ = new ReplaySubject<boolean>(1);

    navigateBack() {
        this.sidebarHelpers.onBackButtonClicked(this);
    }

    openChildItems(item: DataItem) {
        this.sidebarHelpers.onOpenChildItems(this, item);
    }

    navigateToItem(item: DataItem) {
        this.sidebarHelpers.navigateToItem(item, this);
    }

    isButtonLoading(dataItem: DataItem) {
        return this.singleItemLoading.itemId === dataItem.key && this.singleItemLoading.loading;
    }
}
