import { Injectable } from "@angular/core";
import { stringConstants } from "../../../../common-constants";

@Injectable()
export class LetterMarkStore {
    private cache: string[] = [];

    public hasLetter(letter: string): boolean {
        return this.cache.indexOf(letter) > -1;
    }

    public addLetter(letter: string): string {
        if (!this.hasLetter(letter)) {
            this.cache.push(letter);
            return letter;
        }

        return stringConstants.EMPTY_STRING;
    }

    public clear(): void {
        if (this.cache.length) {
            this.cache = [];
        }
    }
}
