import { Injectable } from "@angular/core";
import { MediaHandler, MediaOperationData } from "./media-handler.provider";
import { ModalWindowService, Button, ConfirmButton, CancelButton, DialogData } from "../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { EditCropRotateComponent } from "../images/edit-crop-rotate/edit-crop-rotate.component";
import { SelectorConstants } from "../../html/selector-constants";
import { ReplaySubject, Observable } from "rxjs";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "../services/media.helpers";
import { ToolbarComponent } from "../../content/dynamic-modules/components/dialog/toolbar.component";
import { ContentCultureData } from "../../shared/services/metadata/site-data.store";
import { HttpODataRequestWrapper } from "../../shared/services/http-odata-request.wrapper";
import { ComponentCommunicationService } from "../../shared/services/component-communication.service";

const OPERATIONS = {
    CROP_RESIZE_ROTATE: "Crop, resize or rotate"
};

const URL_KEY = "edit-image";

@Injectable()
export class ImageHandler extends MediaHandler {
    constructor(protected readonly modalWindowService: ModalWindowService, protected http: HttpODataRequestWrapper, protected communicationService: ComponentCommunicationService) {
        super(modalWindowService, http, communicationService);
    }

    canHandle(entityData: EntityData): boolean {
        return MediaHelpers.isImageEntity(entityData);
    }

    executeOperation(data: MediaOperationData): Observable<any> {
        switch (data.operationName) {
            case OPERATIONS.CROP_RESIZE_ROTATE:
                return this.handleCropResizeRotate(data);
            default:
                return super.executeOperation(data);
        }
    }

    getEditOperations(item: any, hasPreviewError: boolean = false, siteLanguages: Array<ContentCultureData> = [], isDamMedia: boolean): string[] {
        const baseOperations = super.getEditOperations(item, hasPreviewError, siteLanguages, isDamMedia);
        const currentOperations = Object.values(OPERATIONS);
        const hasSvgExtension = item.extension && item.extension.includes("svg");

        if (hasSvgExtension || hasPreviewError || isDamMedia) {
            return baseOperations;
        }

        return [...currentOperations, ...baseOperations];
    }

    private handleCropResizeRotate(data: MediaOperationData): Observable<any> {
        const done$ = new ReplaySubject<any>();
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.DONE),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const componentData: ComponentData = {
            type: EditCropRotateComponent,
            properties: {
                item: data.item,
                dataItem: data.mediaDataItem
            }
        };

        const dialogData = new DialogData(componentData, (result) => {
            if (result.data && result.data.data) {
                const component: EditCropRotateComponent = result.component;

                if (component) {
                    const croppedImageDataUrl = component.getCroppedImageDataUrl();
                    const cropResult = { dataUrl: croppedImageDataUrl };

                    done$.next(cropResult);
                }
            }
        }, buttons, null, null);

        dialogData.toolbarData = {
            type: ToolbarComponent,
            properties: {
                header: OPERATIONS.CROP_RESIZE_ROTATE
            }
        };

        this.modalWindowService.setMapping(dialogData, URL_KEY);
        this.modalWindowService.open(data.route, URL_KEY);
        return done$.asObservable();
    }
}

export const IMAGE_HANDLER = {
    provide: MediaHandler,
    useClass: ImageHandler,
    multi: true
};
