import { takeUntil } from "rxjs/operators";
import { Component, OnInit, OnDestroy } from "@angular/core";
import { DynamicItemService } from "../../../../../content/dynamic-modules/services/dynamic-item.service";
import { ProviderService } from "../../../../../content/dynamic-modules/services/provider-service";
import { MetadataContainer } from "../../../../../shared/services/metadata/meta-data.store";
import { LocatableDynamicItemService } from "../../../../../content/dynamic-modules/services/locatable-dynamic-item.service";
import { Subject } from "rxjs";
import { SiteData, SiteDataStore } from "../../../../../shared/services/metadata/site-data.store";
import { SiteSelector } from "./helpers/site-selector/site-selector";
import { LanguageSelector } from "./helpers/language-selector/language-selector";
import { EntitySelector } from "./helpers/entity-selector/entity-selector";
import { ProviderSelector } from "./helpers/provider-selector/provider-selector";
import { ContentSelector } from "./helpers/content-selector/content-selector";
import { SelectorBase } from "./helpers/selector-base";
import { SelectorItem } from "./helpers/selector-item";
import { SelectorContext } from "./helpers/selector-context";
import { Logger } from "../../../../../shared/services/logger-source/logger";
import { MediaService } from "../../../../../libraries/services/media.service";
import { SortService } from "../../../../../shared/services/sort.service";

/**
 * This view is used to select any content item that can be navigated to via URL.
 * Note: We are using the async pipe in the template to pass the model to the sf-chips components
 * because the change detection cycle doesn`t trigger otherwise.
 */
@Component({
    templateUrl: "./link-insert-selector.component.html",
    selector: "sf-link-insert-selector"
})
export class LinkInsertSelectorComponent implements OnInit, OnDestroy {
    siteSelector: SiteSelector;
    languageSelector: LanguageSelector;
    entitySelector: EntitySelector;
    providerSelector: ProviderSelector;
    contentSelector: ContentSelector;
    meta: MetadataContainer;
    siteData: SiteData;
    initialCulture: string;
    error$ = new Subject<string>();

    private selectors: Array<SelectorBase<SelectorItem>> = [];
    private subscriptionsHolder$ = new Subject<any>();

    constructor(
        private locatableItemsService: LocatableDynamicItemService,
        private dynamicItemsService: DynamicItemService,
        private siteDataStore: SiteDataStore,
        private providersService: ProviderService,
        private logger: Logger,
        private mediaService: MediaService,
        private sortService: SortService
    ) { }

    ngOnInit(): void {
        this.initializeSelectors();
        this.buildSelectorsDependencyGraph();
        this.siteSelector.init(new SelectorContext());
        this.mediaService.clearUploads();
    }

    ngOnDestroy(): void {
        this.subscriptionsHolder$.next({});
    }

    private initializeSelectors() {
        this.siteSelector = new SiteSelector(this.logger, this.siteData, this.meta, this.siteDataStore);
        this.selectors.push(this.siteSelector);
        this.languageSelector = new LanguageSelector(this.logger, this.initialCulture);
        this.selectors.push(this.languageSelector);
        this.entitySelector = new EntitySelector(this.logger, this.locatableItemsService, this.meta);
        this.selectors.push(this.entitySelector);
        this.providerSelector = new ProviderSelector(this.logger, this.providersService);
        this.selectors.push(this.providerSelector);
        this.contentSelector = new ContentSelector(this.logger, this.dynamicItemsService, this.meta, this.mediaService, this.sortService);
        this.selectors.push(this.contentSelector);

        this.selectors.forEach(s => s.error$.pipe(takeUntil(this.subscriptionsHolder$)).subscribe(this.errorHandler));
    }

    private errorHandler = (error: string) => {
        this.error$.next(error);
    }

    private buildSelectorsDependencyGraph() {
        this.siteSelector.addChild(this.languageSelector);
        this.siteSelector.addChild(this.entitySelector);
        this.entitySelector.addChild(this.providerSelector);

        this.contentSelector.addParent(this.languageSelector);
        this.contentSelector.addParent(this.providerSelector);
        this.contentSelector.addParent(this.siteSelector);
        this.contentSelector.addParent(this.entitySelector);
    }
}
