import { of as observableOf, ReplaySubject } from "rxjs";

import { first, map, shareReplay } from "rxjs/operators";
import { OperationsProvider, OperationsData, OperationsTarget } from "./interfaces";
import { Observable } from "rxjs";
import { ClassProvider, Injectable } from "@angular/core";
import { Operation, OPERATION_NAMES, OPERATION_CATEGORIES, OperationCategory, OPERATION_TITLES } from "../../../../shared/components/action-menu/operation.model";
import { CompositeOperationsProvider, OPERATIONS_TOKEN } from "./operations-provider";
import { DynamicItemService } from "../dynamic-item.service";
import { CommandModelBase } from "../../../../shared/commands/command-model-base";
import { capitalizeFirstLetter, cloneObject, indefiniteArticle } from "../../../../../utils";
import { SfHtmlEscapePipe } from "@progress/sitefinity-component-framework";
import { UrlHelper } from "../../../../../services/url.helper";
import { DataItem } from "../../interfaces";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../../../../constants/route-paths";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { QUERY_PARAMS, ROUTE_PARAMS } from "../../../constants";
import { UrlService } from "../../../../../services/url.service";

export const OPERATION_QUERY_PARAMS = {
    BACK_LABEL_TEXT: "backLabelText",
    BACK_LABEL_LINK: "backLabelLink"
};

@Injectable()
export class ExternalOperationsProvider implements OperationsProvider {
    private htmlEscapePipe: SfHtmlEscapePipe = new SfHtmlEscapePipe();
    private previousOperationsCallCache: OperationsCache;

    getCategories(data: OperationsData): Observable<OperationCategory[]> {
        return observableOf([]);
    }

    getCommands(data: OperationsData): Observable<CommandModelBase[]> {
        return observableOf([]);
    }

    constructor(private service: DynamicItemService, private urlService: UrlService) { }

    getOperations(data: OperationsData): Observable<Operation[]> {
        let operations$: ReplaySubject<Operation[]>;
        if (!data.contextData.disregardCache && this.previousOperationsCallCache && this.previousOperationsCallCache.equals(data)) {
            operations$ = this.previousOperationsCallCache.operations;
        } else {
            operations$ = new ReplaySubject<Operation[]>(1);
            this.previousOperationsCallCache = new OperationsCache(data, operations$);

            this.service.getItemsOperations(data.dataItem, data.dataItem.key, data.parentItem?.key, data.additionalQueryParams).subscribe(x => {
                operations$.next(x);
                operations$.complete();
            },
            err => {
                operations$.error(err);
                operations$.complete();
            });
        }

        return operations$.pipe(map(op => {
            const operations = cloneObject(op);
            this.modifyCreateOperation(operations, data);
            this.modifyEditOperation(operations, data);
            this.addBulkPublishUnpublishOperations(operations, data);
            this.modifySettingsOperations(operations, data);
            return operations;
        }));
    }

    invalidateCachedItemOperations(itemId: string) {
        if (this.previousOperationsCallCache && this.previousOperationsCallCache.canInvalidate(itemId)) {
            this.previousOperationsCallCache = null;
        }
    }

    private modifyCreateOperation(operations: Operation[], data: OperationsData) {
        if (data.target === OperationsTarget.List) {
            const createOperation = operations.find(o => o.Name === OPERATION_NAMES.create);
            if (createOperation) {
                createOperation.Title = this.buildCreateOperationTitle(CompositeOperationsProvider.getOperationSingularName(data.dataItem.metadata, createOperation.ContextParameters));
            }
        }
    }

    private buildCreateOperationTitle(singleItemName: string) {
        const singularName = singleItemName.toLowerCase();
        let title: string;
        const article = indefiniteArticle(singularName);
        if (article && article.length) {
            title = `${article} ${singularName}`;
        } else {
            title = singularName;
        }

        return `Create ${title}`;
    }

    private modifyEditOperation(operations: Operation[], data: OperationsData) {
        if (data.target === OperationsTarget.List) {
            let editOperation = operations.find(o => o.Name === OPERATION_NAMES.view);
            if (!editOperation) {
                editOperation = operations.find(o => o.Name === OPERATION_NAMES.edit);
            }

            const editContentOperationIndex = operations.findIndex(o => o.Name === OPERATION_NAMES.editContent);
            if (editOperation && (!data.dataItem.metadata.hasLifecycle || editContentOperationIndex !== -1)) {
                editOperation.Title = OPERATION_TITLES.titleAndProperties;
            }
        } else if (data.target === OperationsTarget.Edit) {
            const operation = operations.find(o => o.Name === OPERATION_NAMES.edit);
            if (operation) {
                let newTitle = OPERATION_TITLES.titleAndProperties;
                if (!data.dataItem.metadata.hasLifecycle || data.dataItem.metadata.hasContent) {
                    newTitle = OPERATION_TITLES.saveChanges;
                }

                operation.Title = newTitle;
            }
        }
    }

    // Including hardcoded operations for now. When the operations endpoint starts returning correct results,
    // it should be used for bulk operations.
    private addBulkPublishUnpublishOperations(operations: Operation[], data: OperationsData) {
        if (data.target === OperationsTarget.Bulk && data.dataItem.metadata.hasLifecycle) {
            if (!operations.some(o => o.Name === OPERATION_NAMES.publish)) {
                const publishOperation: Operation = {
                    Name: OPERATION_NAMES.publish,
                    Category: {
                        Name: OPERATION_CATEGORIES.workflow
                    },
                    Ordinal: -1,
                    Title: OPERATION_NAMES.publish,
                    Link: null,
                    Description: null,
                    Parameters: [{}],
                    RequiresConfirmation: false
                };
                operations.unshift(publishOperation);
            }

            const unpublishOperation: Operation = {
                Name: OPERATION_NAMES.unpublish,
                Category: {
                    Name: OPERATION_CATEGORIES.workflow
                },
                Ordinal: 1,
                Title: OPERATION_NAMES.unpublish,
                Link: null,
                Description: null,
                Parameters: [{}],
                RequiresConfirmation: false
            };
            operations.push(unpublishOperation);
        }

        return operations;
    }

    private modifySettingsOperations(operations: Operation[], data: OperationsData) {
        const dataItem = data.dataItem;
        const displayName = data.dataItem.metadata.displayName.toLowerCase();
        const target = data.target;

        const permissions = operations.find(o => o.Name === OPERATION_NAMES.permissions);
        if (permissions) {
            if (data.target === OperationsTarget.List && !dataItem) {
                permissions.Title = `Permissions for ${displayName}`;
            }

            const additionalParams: any = {};
            if (dataItem.title) {
                additionalParams.title = encodeURIComponent(this.htmlEscapePipe.transform(dataItem.title));
            }

            this.setOperationLink(permissions, dataItem, target, data.contextData.origin, additionalParams);
        }

        const revisionHistory = operations.find(o => o.Name === OPERATION_NAMES.revisionHistory);
        if (revisionHistory) {
            const url = this.getEditUrl(data);
            const additionalParams = {
                title: encodeURIComponent(this.htmlEscapePipe.transform(dataItem.title)),
                culture: dataItem.culture,
                revertUrl: url
            };

            this.setOperationLink(revisionHistory, dataItem, target, data.contextData.origin, additionalParams);
        }

        const customFieldsOperation = operations.find(p => p.Name === OPERATION_NAMES.customFields);
        this.setOperationLink(customFieldsOperation, dataItem, target, data.contextData.origin);

        const sendForTranslationOperation = operations.find(p => p.Name === OPERATION_NAMES.sendForTranslation);
        this.setOperationLink(sendForTranslationOperation, dataItem, target, data.contextData.origin);

        const countOperations = operations.filter(p => p.ContextParameters && p.ContextParameters.find(par => par.Name === "Count"));
        countOperations.forEach(operation => {
            const count = new Observable((observer) => {
                return this.service.executeBoundFunction(dataItem, `${operation.Name.toLowerCase()}count`).subscribe(x => {
                    observer.next((<any>x).value);
                    observer.complete();
                });
            }).pipe(first(), shareReplay());

            operation.context = {
                count
            };
        });
    }

    private getEditUrl(data: OperationsData): string {
        let editUrl: string = null;

        if (data.dataItem.metadata.setName === ENTITY_SET.PAGES) {
            if (data.dataItem.data.Renderer === "NetCore") {
                editUrl = `${ROUTE_PATHS.ROOT_PREFIX}/${data.dataItem.metadata.setName}/${ROUTE_PATHS_NO_PREFIX.SF_EDIT}/${data.dataItem.data.Id}?${QUERY_PARAMS.PROVIDER}=${data.dataItem.provider}&${QUERY_PARAMS.CULTURE}=${data.dataItem.culture}`;
            } else {
                let editUrlBasePath = data.dataItem.data.EditUrlBasePath;
                if(!editUrlBasePath) {
                    editUrlBasePath = data.dataItem.data.EditUrl;
                }
                editUrl = `${ROUTE_PATHS.ROOT_PREFIX}/${data.dataItem.metadata.setName}${editUrlBasePath}/${data.dataItem.culture}`;
            }
        } else if (data.dataItem.metadata.setName === ENTITY_SET.TEMPLATES) {
            editUrl = `${ROUTE_PATHS.ROOT_PREFIX}/${data.dataItem.metadata.setName}/${ROUTE_PATHS_NO_PREFIX.TEMPLATE}/${data.dataItem.data.Id}/${data.dataItem.culture}`;
        } else {
            if (data.dataItem.metadata.hasParent) {
                editUrl = `${data.dataItem.metadata.parent}/${data.dataItem.parentKey}/${data.dataItem.metadata.setName}/${data.dataItem.key}/${ROUTE_PARAMS.EDIT_SEGMENT}`;
            } else {
                editUrl = `${data.dataItem.metadata.setName}/${data.dataItem.key}/${ROUTE_PARAMS.EDIT_SEGMENT}`;
            }

            editUrl = `${ROUTE_PATHS.CONTENT}/${editUrl}?${QUERY_PARAMS.PROVIDER}=${data.dataItem.provider}&${QUERY_PARAMS.CULTURE}=${data.dataItem.culture}`;
        }

        const url = encodeURIComponent(this.urlService.getAbsoluteUrl(editUrl));
        return url;
    }

    private setOperationLink(operation: Operation, entityData: DataItem, target: OperationsTarget, explicitTarget: string, additionalQueryParams: Object = null) {
        if (!operation) {
            return;
        }

        const entityName = CompositeOperationsProvider.getOperationPluralName(entityData.metadata, operation.ContextParameters);
        const currentLocation = encodeURIComponent(explicitTarget);
        let newQueryParams = {};

        // TODO: temporary check, should be moved to the backend for all types
        if (!operation.Link.includes(OPERATION_QUERY_PARAMS.BACK_LABEL_TEXT)) {
            if (target === OperationsTarget.Edit) {
                const singularName = CompositeOperationsProvider.getOperationSingularName(entityData.metadata, operation.ContextParameters).toLowerCase();
                const culture = entityData.culture.toUpperCase();
                const indefArticle = indefiniteArticle(singularName);

                newQueryParams[OPERATION_QUERY_PARAMS.BACK_LABEL_TEXT] = `Back to Edit ${indefArticle} ${singularName} (${culture})`;
            } else {
                newQueryParams[OPERATION_QUERY_PARAMS.BACK_LABEL_TEXT] = `Back to ${capitalizeFirstLetter(entityName)}`;
            }
        }

        newQueryParams[OPERATION_QUERY_PARAMS.BACK_LABEL_LINK] = currentLocation;

        if (newQueryParams != null) {
            newQueryParams = Object.assign(newQueryParams, additionalQueryParams);
        }

        operation.Link = UrlHelper.mergeUrlQueryParams(operation.Link, newQueryParams);
    }
}

export const EXTERNAL_OPERATIONS_PROVIDER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_TOKEN,
    useClass: ExternalOperationsProvider
};

class OperationsCache {
    constructor(private key: OperationsData, public operations: ReplaySubject<Operation[]>) {}
    equals(operationsData: OperationsData): boolean {
        return JSON.stringify(this.key.dataItem) === JSON.stringify(operationsData.dataItem) &&
            JSON.stringify(this.key.parentItem) === JSON.stringify(operationsData.parentItem) &&
            JSON.stringify(this.key.additionalQueryParams) === JSON.stringify(operationsData.additionalQueryParams);
    }

    canInvalidate(itemId: string): boolean {
        return this.key && this.key.dataItem && this.key.dataItem.key === itemId;
    }
}
