import { Route } from "@angular/router";

import { ContentComponent } from "./content.component";
import { DynamicItemRouterComponent } from "./dynamic-modules/components/router/dynamic-item-router.component";
import { MetadataStoreResolver } from "../../modules/shared/services/metadata/meta-data-store.resolver";
import { UserDataStoreResolver } from "../../modules/shared/services/metadata/user-data-store.resolver";
import { SiteDataStoreResolver } from "../../modules/shared/services/metadata/site-data-store.resolver";
import { dynamicModulesRoutes } from "./dynamic-modules/dynamic-modules.routes";
import { ROUTE_PARAMS } from "./constants";
import { SiteTitleResolver } from "../shared/services/site-title.resolver";
import { ContentTypeGuard } from "./content-type.guard";
import { ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { stringConstants } from "../../common-constants";
import { FORMS_ROUTES } from "../forms/forms.routes";

export const CONTENT_ROUTES: Route[] = [
    {
        path: ROUTE_PATHS_NO_PREFIX.CONTENT,
        children: [
            { 
                path: stringConstants.EMPTY_STRING,
                component: ContentComponent 
            },
            ...FORMS_ROUTES,
            {
                path: `:${ROUTE_PARAMS.TYPE_NAME_SEGMENT}`,
                component: DynamicItemRouterComponent,
                children: [...dynamicModulesRoutes],
                canActivate: [ContentTypeGuard],
                data: { animation: { value: ROUTE_PATHS_NO_PREFIX.ITEMS_GRID } }
            },
            {
                path: `:${ROUTE_PARAMS.TYPE_NAME_SEGMENT}/:${ROUTE_PARAMS.PARENT_ID_SEGMENT}/:${ROUTE_PARAMS.CHILD_SET_SEGMENT}`,
                component: DynamicItemRouterComponent,
                children: [...dynamicModulesRoutes],
                data: { animation: { value: stringConstants.EMPTY_STRING } },
                canActivate: [ContentTypeGuard]
            }
        ],

        // TODO: should be accessed from the parent route
        resolve: {
            metaStore: MetadataStoreResolver,
            userDataStore: UserDataStoreResolver,
            siteDataStore: SiteDataStoreResolver,
            siteTitle: SiteTitleResolver
        },
        data: {
            animation: {
                value: ROUTE_PATHS_NO_PREFIX.CONTENT
            }
        }
    }
];

