import { ClassProvider, Injectable, Inject } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { NEVER, Observable, of } from "rxjs";
import { map, switchMap, tap } from "rxjs/operators";
import { copyTextToClipboard } from "../../../utils";
import { FILTER_PARAMS } from "../../content/constants";
import { EntityData, HierarchicalDataItem, DataItem } from "../../content/dynamic-modules/interfaces";
import { LoadItemsData, LoadItemsResponse } from "../../content/dynamic-modules/services/dynamic-item.service";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { GridReloadService } from "../../content/dynamic-modules/services/grid-reload.service";
import { SelectorConstants } from "../../html/selector-constants";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { CommonActionContext, ExpandedNodeIdsGet, ExpandedNodeIdsSet, ExpandedNodeIdsSync, GRID_EXTENDER_TOKEN, ItemsDataContext, GridActionContext, GridExtenderBase } from "../../shared/services/grid/grid-extender-base";
import { SiteData, SiteDataStore } from "../../shared/services/metadata/site-data.store";
import { Button, CancelButton, ClickResult, ConfirmButton, DialogData, ModalWindowService } from "../../shared/services/modal-window.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { Settings } from "../../shared/services/settings.service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { ChangeTemplateCommand } from "../components/edit-page/commands/change-template.command";
import { SharePreviewLinkComponent } from "../components/share-preview-link/share-preview-link.component";
import { PAGES_ENTITY_SET_NAME } from "./page.resolver";
import { COMMAND_NAMES } from "../../content/dynamic-modules/components/commands";

import { PagesActionHandler } from "./pages-action-handler.service";
import { BackendTweaksStore } from "../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { SortService } from "../../shared/services/sort.service";
import { ContentFilterService } from "../../shared/services/content-filter.service";
import { ColumnModel } from "../../shared/models/column-model";
import { ExternalAppConfigService } from "../../../app-config/external-app-config.service";
import { ComponentData, VirtualizationOptions } from "@progress/sitefinity-component-framework";
import { StateWrapper } from "../../content/dynamic-modules/services/dynamic-item-store-state";
import { CompositeOperationsProvider } from "../../content/dynamic-modules/services/operations/operations-provider";

const DEFAULT_PAGES_TAKE = 20;

@Injectable()
export class PagesGridExtender extends GridExtenderBase {
    constructor(
        private pagesCommonHandler: PagesActionHandler,
        settings: Settings,
        private siteDataStore: SiteDataStore,
        modalWindowService: ModalWindowService,
        dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) notificationService: NotificationService,
        reloadService: GridReloadService,
        contentFilterService: ContentFilterService,
        sortService: SortService,
        backendTweaksStore: BackendTweaksStore,
        private configService: ExternalAppConfigService,
        operationsProvider: CompositeOperationsProvider) {
        super(contentFilterService, dynamicItemStore, settings, sortService, backendTweaksStore, reloadService, modalWindowService, notificationService, configService, operationsProvider);
    }

    getExpandedNodeIds(args: ExpandedNodeIdsGet): Observable<string[]> {
        return this.siteDataStore.getValue().pipe(map(x => {
            const key = x.SiteMapRootNodeId + args.entityData.metadata.setName;
            return this.settings.getExpandedNodeIds(key);
        }));
    }

    getTakeItemsCount(entityData: EntityData) {
        return DEFAULT_PAGES_TAKE;
    }

    reloadItems(queryParams: { [key: string]: string }, parentId: string, entityData: EntityData, sortParam: string, dataFieldNames: string[]): Observable<StateWrapper> {
        const loadItemsArg = this.contentFilterService.getLoadArguments(queryParams, parentId, entityData, sortParam, dataFieldNames);
        loadItemsArg.take = DEFAULT_PAGES_TAKE;
        this.dynamicItemStore.loadItems(loadItemsArg);
        return NEVER;
    }

    setExpandedNodeIds(args: ExpandedNodeIdsSet): void {
        this.siteDataStore.getValue().pipe(tap(x => {
            const key = x.SiteMapRootNodeId + args.entityData.metadata.setName;
            return this.settings.setExpandedNodeIds(key, args.expandedIds);
        })).subscribe();
    }

    syncExpandedNodeIds(args: ExpandedNodeIdsSync): void {
        if (args.entityData.metadata.isSelfReferencing) {
            const hierarchicalDataItems = args.dataItems as HierarchicalDataItem[];
            if (args.expandedIds) {
                const expandedNodesModified = [].concat(args.expandedIds);
                this.iterateChildren(hierarchicalDataItems, expandedNodesModified);

                // there are items that are deleted
                if (expandedNodesModified.length > 0) {
                    expandedNodesModified.forEach((expandedNode) => {
                        const index = args.expandedIds.findIndex(x => x === expandedNode);
                        args.expandedIds.splice(index, 1);
                    });
                }

                this.setExpandedNodeIds(args);
            }
        }
    }

    isHierarchical(route: ActivatedRoute): boolean {
        return !route.snapshot.queryParams[FILTER_PARAMS.FILTER] &&
            !route.snapshot.queryParams[FILTER_PARAMS.SEARCH] &&
            !route.snapshot.queryParams[FILTER_PARAMS.SORT];
    }

    getVirtualizationOptions(route: ActivatedRoute): VirtualizationOptions {
        const isVirtualized = this.configService.externalConfig.virtualization === false ? false : this.isHierarchical(route);
        const siteData: SiteData = route.parent.snapshot.data.siteDataStore;

        // When we have 1 language row the default node height is 60px.
        // When we have more than 6 languages the translations column will spread them on 2 rows which results in 93px node height
        // When we have more than 2 rows of languages we add 36px for each additional row
        const languageRows = Math.ceil(siteData.ContentCultures.length / 6);
        let nodeHeight = 60;
        if (languageRows === 2) {
            nodeHeight = 93;
        } else if (languageRows > 2) {
            nodeHeight = 93 + (languageRows - 2) * 36;
        }

        return {
            isVirtualized,
            nodeHeight
        };
    }

    getChildren(entityData: EntityData, parentId: string, serviceInfo: ServiceInfo, columns: ColumnModel[]): Promise<LoadItemsResponse> {
        const response = this.dynamicItemStore.getItemList({
            action: `Default.Hierarchy(parentId='${serviceInfo.parentId}',expandedPages=@param)?@param=[]`,
            entityData: entityData
        });

        return response.toPromise();
    }

    getItemsData(route: ActivatedRoute, dataFieldNames: string[], args?: ItemsDataContext): LoadItemsData {
        const entityData = route.snapshot.data["dynamicItems"];
        const siteData: SiteData = route.parent.snapshot.data.siteDataStore;
        return {
            entityData: entityData,
            action: `Default.Hierarchy(parentId='${siteData.SiteMapRootNodeId}',expandedPages=@param)?@param=${JSON.stringify(args.expandedNodeIds || [])}`,
            dataFieldNames: dataFieldNames
        };
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === PAGES_ENTITY_SET_NAME;
    }

    tryHandleAction(context: GridActionContext): Observable<boolean> {
        const actionName = context.actionName;
        if (actionName === OPERATION_NAMES.template) {
            return of(this.tryHandleChangeTemplateAction(context));
        }

        if (actionName === OPERATION_NAMES.sharePreviewLink) {
            return of(this.tryHandleSharePreviewLinkAction(context));
        }

        if (actionName === COMMAND_NAMES.selectionChanged) {
            const isGroupOrRedirectingPage = this.pagesCommonHandler.isGroupOrRedirectingPage(context.item);
            if (!isGroupOrRedirectingPage) {
                return this.tryHandleAction({
                    actionName: OPERATION_NAMES.editContent,
                    item: context.item,
                    route: context.route,
                    grid: context.grid
                });
            }
        }

        if (actionName === OPERATION_NAMES.create) {
            return this.pagesCommonHandler.navigateToEdit(context);
        }

        if (actionName === OPERATION_NAMES.createChild) {
            return this.pagesCommonHandler.navigateToEdit(<GridActionContext>{
                actionName: OPERATION_NAMES.editContent,
                item: DataItem.emptyItem(context.item),
                route: context.route,
                grid: context.grid,
                data: {
                    parentId: context.item.key,
                    prepopulatedFields: { ParentId: context.item.key }
                }
            });
        }

        if (actionName === OPERATION_NAMES.edit || actionName === OPERATION_NAMES.duplicate) {
            return this.pagesCommonHandler.navigateToTitleAndProperties(context).pipe(map(x => !!x));
        }

        return super.tryHandleAction(context).pipe(switchMap(result => {
            if (result) {
                return of(result);
            }

            return this.pagesCommonHandler.tryHandleAction(context);
        }));
    }

    hideLoadMore(route: ActivatedRoute, entityData: EntityData): boolean {
        return this.isHierarchical(route);
    }

    hasLongRunningTasks(entityData: EntityData): boolean {
        return true;
    }

    private tryHandleChangeTemplateAction(context: CommonActionContext): boolean {
        const ctx: ExecutionContext = {
            currentRoute: context.route,
            data: {
                selectedItems: context.item.data ? [context.item] : [],
                entityData: context.item
            },
            model: null
        };
        const command = new ChangeTemplateCommand(this.modalWindowService, this.dynamicItemStore, this.notificationService);

        command.execute(ctx).subscribe(() => {
            this.reloadService.requestReload();
        });

        return true;
    }

    private tryHandleSharePreviewLinkAction(context: CommonActionContext): boolean {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.COPY_LINK, (data) => {
                copyTextToClipboard(data.component.previewLink);
                return new ClickResult(data, true);
            }),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const componentData: ComponentData = {
            type: SharePreviewLinkComponent,
            properties: {
                dataItem: context.item
            }
        };

        const dialogData = new DialogData(componentData, undefined, buttons);

        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.open(context.route);

        return true;
    }

    private iterateChildren(dataItems: HierarchicalDataItem[], expandedNodeIds: string[]) {
        dataItems.forEach((dataItem) => {
            if (dataItem.hasChildren) {
                const keyIndex = expandedNodeIds.findIndex(x => x === dataItem.key);
                if (keyIndex !== -1)
                    expandedNodeIds.splice(keyIndex, 1);

                this.iterateChildren(dataItem.children, expandedNodeIds);
            }
        });
    }
}

export const PAGES_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: PagesGridExtender
};
