import { ChoiceSettings } from "./choice.settings";
import { Component, OnInit } from "@angular/core";
import { createValueAccessor } from "../field-base";
import { ChoiceComponent } from "./choice.component";
import { SelectSettings } from "@progress/sitefinity-component-framework";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-dropdown-choice",
    templateUrl: "./choice-dropdown.component.html",
    providers: [createValueAccessor(ChoiceDropdownComponent)]
})
export class ChoiceDropdownComponent extends ChoiceComponent implements OnInit {
    /**
     * {true} when current field value is not supported by the dropdown options and unsupportedValueText is set;
     * {false} otherwise;
     */
    public showUnsupportedValueOption: boolean = false;

    /**
     * Creates field settings for choice dropdown field
     *
     * @param {Array<ChoiceItem>} choices The choice options.
     * @param {string} defaultSelection The default option value.
     * @param {string} name The name of the field.
     * @param {string} look The look of the field.
     * @param {string} unsupportedValueText The text of the option shown when the current field value is not supported by the dropdown options.
     * @returns {ChoiceSettings}
     */
    public static createFieldSettings(choices: Array<ChoiceItem> = [], defaultSelection: string = null, name: string = null, look: string = null, unsupportedValueText: string = null): ChoiceSettings {
        const settings = new ChoiceSettings(name, false);
        settings.choices = choices;
        if (look) {
            settings.look = " -" + look.split(" ").join(" -");
        }
        settings.defaultValue = defaultSelection;
        settings.unsupportedValueText = unsupportedValueText;

        return settings;
    }

    ngOnInit() {
        super.ngOnInit();
        this.registerSubscription(this.choicesLoaded.subscribe(() => {
            if (!(this.settings.choices && this.settings.choices.length === 0 && this.settings.choiceServiceUrl)) {

                const dropdownChoiceSettings: SelectSettings = {
                    key: this.settings.key,
                    wrapperCssClass: this.settings.look
                };

                this.choiceSettings = dropdownChoiceSettings;
            }
        }));
    }

    writeValue(value: any) {
        super.writeValue(value);
        this.showUnsupportedValueOption = this.getShowUnsupportedValueOption(value);

        const newChoiceSettings: SelectSettings = { ...this.choiceSettings};
        newChoiceSettings.unsupportedValueText = this.showUnsupportedValueOption ? this.settings.unsupportedValueText : null;
        newChoiceSettings.unsupportedValue = this.showUnsupportedValueOption ? this.value : null;
        this.choiceSettings = newChoiceSettings;
    }

    private getShowUnsupportedValueOption(value): boolean {
        if (value) {
            // Check if any of the choice fields corresponds to this.value. If not - show unsupported value text.
            if (this.settings && this.settings.unsupportedValueText) {
                const valueSupported: boolean = this.choices && this.choices.some(o => o.Value === value);

                if (!valueSupported) {
                    return true;
                }
            }
        }

        return false;
    }
}
