import { Component, OnInit, ViewChildren, QueryList, AfterViewInit } from "@angular/core";
import { FieldBase, createValueAccessor } from "../../../../../../fields/index";
import { ImageHelper, MARGIN_TOP_NAME, MARGIN_RIGHT_NAME, MARGIN_BOTTOM_NAME, MARGIN_LEFT_NAME } from "../../../html/tools/insert-image/image-helper";
import { SfInputComponent } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../../../common-constants";

@Component({
    selector: "sf-edit-image-margins",
    templateUrl: "./edit-image-margins.component.html",
    providers: [createValueAccessor(EditImageMarginsComponent), ImageHelper]
})
export class EditImageMarginsComponent extends FieldBase implements OnInit, AfterViewInit {
    marginNames = [MARGIN_TOP_NAME, MARGIN_RIGHT_NAME, MARGIN_BOTTOM_NAME, MARGIN_LEFT_NAME];
    @ViewChildren(SfInputComponent) marginFields: QueryList<SfInputComponent>;

    ngAfterViewInit() {
        this.marginNames.forEach(margin => {
            const currentMarginField = this.marginFields.toArray().find(mf => mf.name === margin);
            const modifiedValue = this.toggleUnitOnProperty(this.value[margin], false);

            currentMarginField.writeValue(modifiedValue);
        });
    }

    onInput(event: any, property: any) {
        const value = this.getValue();

        value[property] = this.toggleUnitOnProperty(event.target.value);
        this.writeValue(value);
    }

    writeValue(value: any) {
        if (value) {
            super.writeValue(Object.assign({}, value));
        }
    }

    private toggleUnitOnProperty(value: string, add: boolean = true): string {
        if (!value) {
            return stringConstants.EMPTY_STRING;
        }

        let modifiedValue: string;

        if (add) {
            modifiedValue = `${value}${this.settings.unit}`;
        } else {
            modifiedValue = value.replace(this.settings.unit, stringConstants.EMPTY_STRING);
        }

        return modifiedValue;
    }
}
