import { Component, Input, OnInit } from "@angular/core";
import { UrlService } from "../../../../../services/url.service";
import { SvgIconType } from "../../../../shared/components/svg-icon-handler/svg-icon-handler.component";

export const STATIC_TEMPLATES_TYPES = ["Accordion", "Horizontal", "Vertical", "Tabs", "SitefinityLoginForm", "SitefinityChangePassword", "SitefinityForgottenPassword", "SitefinityResetPassword", "SitefinityRegistration", "SitefinitySearchBox", "SitefinityClassification", "SitefinityBreadcrumb", "SitefinityFacets"];
export const PNG_PRESETS_TEMPLATE_NAMES = ["SitefinityContentList", "SitefinitySearchResults"];

@Component({
    selector: "sf-widget-preview",
    templateUrl: "./widget-preview.component.html"
})
export class WidgetPreviewComponent implements OnInit {
    @Input() text: string;
    @Input() name: string;
    @Input() thumbnailUrl: string;
    @Input() addWidgetTitle: string;
    @Input() addWidgetName: string;

    iconLook = "square";
    showText = true;
    presetSrc: string;
    isPreset: boolean = false;
    svgIconType: SvgIconType;

    constructor(private urlService: UrlService) {}

    ngOnInit() {
        this.generateMainLook();
    }

    onPngHandlerError(event: Event) {
        this.isPreset = false;
        this.showText = true;
    }

    private generateMainLook() {
        // UX: Use the friendly widget title as green label and as browser tooltip in Add Widget dialog
        this.text = this.addWidgetTitle || this.text;
        const widgetTemplateName = this.addWidgetName || this.name;

        if (this.thumbnailUrl)
            this.handleExternalThumbnailUrl();
        else if (PNG_PRESETS_TEMPLATE_NAMES.indexOf(this.name) > -1) {
            this.handlePresetPreviewLook(this.addWidgetName || this.name);
        } else if (STATIC_TEMPLATES_TYPES.indexOf(widgetTemplateName) > -1) {
            this.handleStaticTemplatePreviewLook();
        }
    }

    private handleExternalThumbnailUrl() {
        this.isPreset = true;
        this.showText = false;
        this.presetSrc = this.thumbnailUrl;
    }

    private handleStaticTemplatePreviewLook() {
        // Hide the text under the icon and if it is one of the static navigation...UX
        // Make the icon in Add Widget dialog square only if it is not one of the static navigations...UX
        this.iconLook = null;
        this.showText = false;
        this.name = this.addWidgetName || this.name;
        this.svgIconType = SvgIconType.Template;
    }

    private handlePresetPreviewLook(widgetName: string) {
        this.isPreset = true;
        this.showText = false;

        const filePath = `assets/images/preset-${widgetName.toLowerCase()}.png`;
        this.presetSrc = this.urlService.getResourceUrl(`/${filePath}`);
    }
}
