import { OnInit, Component } from "@angular/core";
import { DataContext, DataContextComponent } from "../../../models/data-context-component";
import { RelativeDatePipe } from "../../../pipes/relative-date.pipe";
import { EVENT_PROPERTIES } from "../events.constants";
import { EventDatesService } from "../services/event-dates.service";
import { RecurrentRule, EndRecurrenceType } from "../recurring-event/recurrent-rule";

@Component({
    selector: "sf-event-time-grid-cell",
    templateUrl: "./event-time.grid-cell.base.component.html",
    providers: [RelativeDatePipe]
})
export class EventTimeGridCellComponent implements OnInit, DataContextComponent {
    public context: DataContext;
    public viewModel: ViewModel;
    public readonly EVENT_DATE_FORMAT = RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME;

    constructor(private datePipe: RelativeDatePipe,
                private datesService: EventDatesService) {}

    ngOnInit(): void {
        const column = this.context.model;
        const eventStartWithServerOffset = this.context.dataItem.data[EVENT_PROPERTIES.EVENT_START_WITH_OFFSET];
        if (column.name === "Start") {
            const eventStartObj = this.datesService.getDateWithoutBrowserOffset(eventStartWithServerOffset);
            this.viewModel = {
                date: this.datePipe.transform(eventStartObj, RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME),
                offset: this.getOffset(this.context.dataItem.data[EVENT_PROPERTIES.EVENT_START_UTC_OFFSET])
            };
        }

        const eventEndWithServerOffset = this.context.dataItem.data[EVENT_PROPERTIES.EVENT_END_WITH_OFFSET];

        if (!eventEndWithServerOffset) {
            return;
        }

        if (column.name === "End" && !this.isEndlessRecurringEvent()) {
            let eventEndObj: Date;
            if (this.context.dataItem.data[EVENT_PROPERTIES.ALL_DAY_EVENT]) {
                eventEndObj = this.datesService.getEventEndForAllDayEvent(eventStartWithServerOffset, eventEndWithServerOffset);
                eventEndObj = this.datesService.getDateWithoutBrowserOffset(eventEndObj);
            } else if (eventEndWithServerOffset) {
                eventEndObj = new Date(eventEndWithServerOffset);
                eventEndObj = this.datesService.getDateWithoutBrowserOffset(eventEndObj);
            }

            this.viewModel = {
                date: this.datePipe.transform(eventEndObj, RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME),
                offset: this.getOffset(this.context.dataItem.data[EVENT_PROPERTIES.EVENT_END_UTC_OFFSET])
            };
        }

        if (this.context.dataItem.data.AllDayEvent) {
            this.processAllDayEvent();
        }
    }

    private isEndlessRecurringEvent() {
        if (this.isRecurring()) {
            const recurrenceRule: RecurrentRule = JSON.parse(this.context.dataItem.data[EVENT_PROPERTIES.RECURRENCE_EXPRESSION]);
            return recurrenceRule.endRecurrenceType === EndRecurrenceType.Never;
        }

        return false;
    }

    private isRecurring() {
        return !!this.context.dataItem.data[EVENT_PROPERTIES.RECURRENCE_EXPRESSION];
    }

    private getOffset(utcOffset: number): string {
        if (utcOffset === 0) {
            return `(UTC)`;
        }

        const sign = utcOffset < 0 ? "-" : "+";
        const utcOffsetHours = Math.floor(Math.abs(utcOffset / 60));
        const utcOffsetMinutes = this.getOffsetMinutes(utcOffset);

        return `(UTC ${sign}${utcOffsetHours}:${utcOffsetMinutes})`;
    }

    private getOffsetMinutes(utcOffset: number): string {
        const utcOffsetMinutes = this.padTime(Math.abs(utcOffset % 60).toString());
        return utcOffsetMinutes;
    }

    private padTime(time: string): string {
        if (time.length < 2) {
            return `${time}0`;
        }

        return time;
    }

    private processAllDayEvent(): void {
        if (!this.viewModel || !this.viewModel.date) {
            return;
        }

        const monthAndDayTokens = this.viewModel.date.split(",", 2);
        if (monthAndDayTokens.length === 2) {
            this.viewModel.date = monthAndDayTokens.join(",");
        }
    }
}

interface ViewModel {
    date: string;
    offset: string;
}
