import { ClickResult, ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { NOTIFICATION_DURATION_INFINITE } from "../../../../constants";
import { DynamicItemService } from "../../dynamic-item.service";
import { Observable, ReplaySubject } from "rxjs";
import { DataItem } from "../../../interfaces";
import { BulkOperationResult } from "./bulk-command";
import { HasNotificationCommand, CommandNotificationArgs } from "../../../../../shared/commands/has-notification-command";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { Inject } from "@angular/core";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../../shared/services/notification/notification.service";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../../../../../shared/components/modal-window/modal-window.component";
import { MetadataContainer } from "../../../../../shared/services/metadata/meta-data.store";
import { SelectorBaseCommand } from "./selector-base.command";
import { SortService } from "../../../../../shared/services/sort.service";
import { ServiceInfo } from "../../../../../../../../fields/selector/selector.component";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ChildrenCountStore } from "../../children-count.store";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { first, map } from "rxjs/operators";

export class MoveCommand extends SelectorBaseCommand implements HasNotificationCommand {
    skipNotification: boolean = true;

    protected dialogMapping = "move";
    protected dialogTitle = "Move to another parent";
    protected confirmButtonText = "Move";

    constructor(protected modalWindowService: ModalWindowService,
                protected service: DynamicItemService,
                @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService,
                private metadataContainer: MetadataContainer,
                protected sortService: SortService,
                private childrenCountStore: ChildrenCountStore
                ) {
                    super(modalWindowService, service, notificationService, sortService);
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        return null;
    }

    execute(context: ExecutionContext): Observable<any> {
        const result = super.execute(context);
        this.setDialogTitle();

        return result;
    }

    protected setDialogTitle() {
        this.dialogTitle = `Move to another ${this.entityData.metadata.singularName.toLowerCase()}`;
    }

    protected getEntityData() {
        const childEntityData = this.targetItems[0];
        this.entityData = DataItem.emptyItem({
            metadata: this.metadataContainer.entities[childEntityData.metadata.parent],
            provider: childEntityData.provider,
            culture: childEntityData.culture});
    }

    protected serviceLoadMore(info: ServiceInfo): Observable<{ totalCount: number, dataItems: any[] }> {
        return super.serviceLoadMore(info).pipe(first(), map((data) => {
            const parentId = this.targetItems[0].parentKey;
            const filteredDataItems = data.dataItems.filter(x => x[this.targetItems[0].metadata.key] !== parentId);
            const totalCount = filteredDataItems.length !== data.dataItems.length ? data.totalCount - 1 : data.totalCount;
            return {
                totalCount,
                dataItems: filteredDataItems
            };
        }));
    }

    protected executeConfirmAction(selectedItems: DataItem[], clickResult: ReplaySubject<ClickResult>) {
        const targetItemIds = this.targetItems.map(x => x.data.Id);
        const bulkResult: BulkOperationResult = {
            success: true,
            succeededItemsIds: targetItemIds
        };

        if (targetItemIds.length === 0) {
            clickResult.next(new ClickResult(bulkResult, true));
            return;
        }

        const data = {
            target: selectedItems[0].key,
            items: targetItemIds
        };

        this.service.executeBoundAction(DataItem.emptyItem(this.targetItems[0]), "Default.Move()", data).subscribe(() => {
            this.invalidateChildrenCountCache(selectedItems[0]);
            clickResult.next(new ClickResult(bulkResult, true));
        }, error => {
            this.notificationService.publishBasicNotification({
                message: error.message,
                look: NOTIFICATION_LOOKS.ERROR,
                duration: NOTIFICATION_DURATION_INFINITE,
                filterParam: MODAL_WINDOW_NOTIFICATION_FILTER
            });
            clickResult.next(new ClickResult(false, false, true));
        });
    }

    private invalidateChildrenCountCache(newParentItem: DataItem) {
        this.targetItems.forEach(item => {
            this.childrenCountStore.invalidateCachedChidrenCountByChildItem(item);
        });

        this.childrenCountStore.invalidateCachedChidrenCountByParentItem(newParentItem);
    }

    protected generateDescription(componentData: ComponentData) {
        componentData.properties.description = `Select a ${this.entityData.metadata.singularName.toLowerCase()} where to move the ${this.targetItems.length > 1 ? this.targetItems[0].metadata.displayName.toLowerCase() : this.targetItems[0].metadata.singularName.toLowerCase()}`;
        componentData.properties.headingLook = "sf-mb--m";
    }
}
