import { BUTTON_NAMES } from "../selector-constants";
import { stringConstants } from "../../../common-constants";
import { isImageImmutableSelected, isEmbedImmutableSelected } from "./immutable.helpers";

// KENDO specific logic because KENDO
const ALIGNING_CLASSES = [`-${BUTTON_NAMES.ALIGN_CENTER}`, `-${BUTTON_NAMES.ALIGN_LEFT}`, `-${BUTTON_NAMES.ALIGN_RIGHT}`];

export const MARGIN_PROPERTIES = ["margin", "margin-top", "margin-right", "margin-bottom", "margin-left"];
export const MARGIN_VALUE_UNIT = "px";
export const enum AligninigDirection {
    Left = "left",
    Center = "auto",
    Right = "right"
}
export const KENDO_ALIGN_COMMANDS = {
    LEFT: "justifyleft",
    RIGHT: "justifyright",
    CENTER: "justifycenter"
};

export const handleKendoAlignCommand = (justifyCommand: string, alignignElement: HTMLElement, inlineStyles: {}) => {
    const canHadleAligning = isImageImmutableSelected(alignignElement) || isEmbedImmutableSelected(alignignElement);

    if (!canHadleAligning) {
        return;
    }

    let skipMarginProperties = [];

    switch (justifyCommand) {
        case KENDO_ALIGN_COMMANDS.LEFT:
            alignignElement.classList.toggle(`-${BUTTON_NAMES.ALIGN_LEFT}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_CENTER}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_RIGHT}`);

            // Clear float styles because Kendo does not clear them if you have margins set
            if (!alignignElement.classList.contains(`-${BUTTON_NAMES.ALIGN_LEFT}`)) {
                alignignElement.style.float = stringConstants.EMPTY_STRING;
            }

            break;
        case KENDO_ALIGN_COMMANDS.RIGHT:
            alignignElement.classList.toggle(`-${BUTTON_NAMES.ALIGN_RIGHT}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_LEFT}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_CENTER}`);

            // Clear float styles because Kendo does not clear them if you have margins set
            if (!alignignElement.classList.contains(`-${BUTTON_NAMES.ALIGN_RIGHT}`)) {
                alignignElement.style.float = stringConstants.EMPTY_STRING;
            }

            break;
        case KENDO_ALIGN_COMMANDS.CENTER:
            alignignElement.classList.toggle(`-${BUTTON_NAMES.ALIGN_CENTER}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_LEFT}`);
            alignignElement.classList.remove(`-${BUTTON_NAMES.ALIGN_RIGHT}`);

            // Clear float styles and skip left and right margin setter because Kendo does not clear them if you have margins set
            if (alignignElement.classList.contains(`-${BUTTON_NAMES.ALIGN_CENTER}`)) {
                alignignElement.style.float = stringConstants.EMPTY_STRING;
                skipMarginProperties = ["margin-left", "margin-right"];
            } else {// Clear margins auto styles because Kendo does not clear them if you have margins set
                alignignElement.style.marginLeft = stringConstants.EMPTY_STRING;
                alignignElement.style.marginRight = stringConstants.EMPTY_STRING;
            }

            break;
    }

    setInlineStyles(alignignElement, inlineStyles, skipMarginProperties);
};

export const transferKendoAlignInlineStyles = (fromElement: HTMLElement, toElement: HTMLElement) => {
    // Do not apply display property when unwrapping the link to image
    const skipProperties = fromElement instanceof HTMLAnchorElement ? ["display"] : [];
    const currentStyles = getInlineStyles(fromElement, null, null, MARGIN_PROPERTIES);

    setInlineStyles(toElement, currentStyles, skipProperties);

    const alignClass = ALIGNING_CLASSES.find(cls => fromElement.classList.contains(cls));

    if (alignClass) {
        toElement.classList.add(alignClass);
        fromElement.classList.remove(alignClass);
    }
};

export const setInlineStyles = (element: HTMLElement, properties: {}, skipProperties: string[] = []) => {
    if (!element) {
        return;
    }

    Object.keys(properties).forEach(key => {
        if (skipProperties.indexOf(key) === -1) {
            element.style[key] = properties[key];
        }
    });
};

export const getInlineStyles = (element: HTMLElement, specificProperties?: string[], specificValue?: string, clearSpecificStyles?: string[]): {} => {
    if (!element) {
        return;
    }

    return Array.from(element.style).reduce((style, name) => {
        let addStyle = true;

        if (specificProperties) {
            addStyle = specificProperties.indexOf(name) > -1;

            if (addStyle && specificValue) {
                addStyle = element.style[name].indexOf(specificValue) > -1;
            }
        }

        if (addStyle) {
            style[name] = element.style[name];
        }

        if (clearSpecificStyles && clearSpecificStyles.indexOf(name) > -1) {
            element.style[name] = null;
        }

        return style;
    }, {});
};
