import { Injectable, Inject } from "@angular/core";
import { ModalWindowService, DialogData, Button, ClickResult, ClosingContext } from "../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ActivatedRoute, Router } from "@angular/router";
import { WINDOW_TOKEN } from "../../../window.provider";
import { WidgetEditorComponent } from "../widget-editor.component";
import { stringConstants } from "../../../common-constants";
import { ITEM_DATA_KEY } from "../../content/dynamic-modules/components/entity/dynamic-item.component";
import { ItemData } from "../../content/dynamic-modules/services/entity/dynamic-item.resolver";
import { WidgetContext } from "../models/widget-context";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { PropertyEditorViewModes, PropertyEditorCustomEvents, PropertyEditorConstants, PropertyEditorOperations } from "../property-editor.constants";
import { SHOW_HEADING_BUTTONS } from "../../shared/components/modal-window/modal-window.component";
import { Observable, Subject } from "rxjs";
import { map } from "rxjs/operators";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";

@Injectable({
    providedIn: "root"
})
export class WidgetPropertyEditorService {

    constructor(
        protected dynamicItemService: DynamicItemService,
        private router: Router,
        private modalService: ModalWindowService,
        @Inject(WINDOW_TOKEN) private window: Window) {

    }

    public initialize(route: ActivatedRoute) {
        this.window.document.addEventListener(PropertyEditorCustomEvents.NEED_MODAL_DIALOG,
            (e: any) => {
                const args = e.detail;
                if (!args.openNewEditor) {
                    return;
                }

                e.preventDefault();

                const context = WidgetContext.fromSitefinityContext(args, this.router, route);
                this.initializeViewData(route, context).subscribe((c) => {
                    const widgetId = (c.component as WidgetEditorComponent).context.widgetId;
                    const changes = !(!c.data?.Success || c.data?.SourceOperation?.Name === OPERATION_NAMES.cancel);
                    const event = new CustomEvent(PropertyEditorCustomEvents.MODAL_DIALOG_CLOSED, { detail: { changes, widgetId } });
                    this.window.document.dispatchEvent(event);
                });
            },
            true);
    }

    public initializeViewData(route: ActivatedRoute, context: WidgetContext): Observable<ClosingContext> {
        if (context.viewName === PropertyEditorViewModes.ADVANCED)
            return this.createDialog(PropertyEditorViewModes.ADVANCED, false, route, context);
        else
            return this.createDialog(PropertyEditorViewModes.BASIC, false, route, context);
    }

    public initialzieQuickEdit(route: ActivatedRoute, context: WidgetContext): ComponentData {
        const itemData = route.firstChild.snapshot.data[ITEM_DATA_KEY] as ItemData;
        context.entityData = itemData ? itemData.item : null;
        const componentData: ComponentData = {
            type: WidgetEditorComponent,
            properties: {context: context},
            afterComponentInit: (component: WidgetEditorComponent) => {
                component.context = context;
                component.hasAdvancedOptions.subscribe(x => {
                    this.modalService.sendCommand("editWidgetPropsBasic", {
                        name: SHOW_HEADING_BUTTONS,
                        data: x
                    });
                });
            },
            updatePropertiesOnChange: true
        };

        return componentData;
    }

    private createDialog(viewName: string, isAdvanced: boolean, route: ActivatedRoute, context: WidgetContext): Observable<ClosingContext> {
        const itemData = route.firstChild.snapshot.data[ITEM_DATA_KEY] as ItemData;
        context.entityData = itemData ? DataItem.fromCulture(itemData.item, context.culture || itemData.item.culture) : null;
        context.sectionName = viewName;

        const componentData: ComponentData = {
            type: WidgetEditorComponent,
            afterComponentInit: (component: WidgetEditorComponent) => {
                component.context = context;
                component.hasAdvancedOptions.subscribe(x => {
                    this.modalService.sendCommand("editWidgetPropsBasic", {
                        name: SHOW_HEADING_BUTTONS,
                        data: x
                    });
                });
            },
            updatePropertiesOnChange: true
        };

        const dialogHeading = context.widgetName;

        const ret = new Subject<ClosingContext>();
        const advancedRet = new Subject<ClosingContext>();
        const headButtons = this.getHeadButtons(isAdvanced, route, context, advancedRet);
        const dialogData = new DialogData(componentData);
        dialogData.doneCallback = context => ret.next(context);
        const cssContentData = (context.viewName === PropertyEditorViewModes.UNSHARE || context.viewName === PropertyEditorViewModes.SHARE || context.viewName === PropertyEditorViewModes.NOT_SHAREABLE)  ? "-prompt" : "-no-padding-top -no-padding-horizontal";
        dialogData.contentClass = cssContentData;
        dialogData.heading.title = dialogHeading;
        dialogData.headButtons = headButtons;
        dialogData.showButtonsOnInit = false;
        dialogData.hideStickyContent = true;

        const urlKey = "editWidgetProps" + viewName;
        this.modalService.setMapping(dialogData, urlKey);
        this.modalService.show(urlKey, route, undefined, context.window);

        let advancedClosingContext: ClosingContext;
        advancedRet.subscribe((x) => {
            if (x.data && (x.data.SourceOperation.Name === PropertyEditorOperations.SAVE || x.data.SourceOperation.Name === PropertyEditorOperations.SAVE_ALL)) {
                advancedClosingContext = x;
            }
        });

        return ret.pipe(map((x) => {
            if (advancedClosingContext && advancedClosingContext.data && !x.data) {
                x.data = advancedClosingContext.data;
            }

            return x;
        }));
    }

    private getHeadButtons(isAdvanced: boolean, route: ActivatedRoute, context: WidgetContext, advancedRet: Subject<ClosingContext>): Button[] {
        const showSwitchViewButtons = context.viewName === stringConstants.EMPTY_STRING;
        const headButtons = [];
        if (showSwitchViewButtons && !isAdvanced) {
            const handlers = { click: () => this.openDialogClick(PropertyEditorViewModes.ADVANCED, route, context, advancedRet) };
            headButtons.push(new Button(handlers, "cog", stringConstants.EMPTY_STRING, PropertyEditorConstants.ADVANCED_SETTINGS_COG_BUTTON_TITLE));
        }

        return headButtons;
    }

    private openDialogClick(viewName: string, route: ActivatedRoute, context: WidgetContext, advancedRet: Subject<ClosingContext>) {
        this.createDialog(viewName, true, route, context).subscribe((x) => advancedRet.next(x));

        return new ClickResult(null, true, false);
    }
}
