import { SelectorItem } from "../selector-item";
import { Provider } from "../../../../../../../content/dynamic-modules/services/provider-service";

export class ProviderSelectorItem extends SelectorItem {
    isDefault: boolean;

    static fromProvider = (p: Provider) => {
        const item = new ProviderSelectorItem();
        item.Title = p.title;
        item.value = p.name;
        item.isDefault = p.isDefault;
        return item;
    }
}
