import { Component, Input, OnInit, ViewChild, ViewEncapsulation } from "@angular/core";

import { FieldSectionModel } from "../../../../services/fieldSection.model";
import { createFieldModel } from "../../fields.constants";
import { FieldTypes } from "../../fields-builder/services/fields-registry";
import { CompositeFieldsProvider } from "../../fields-builder/providers/fields-provider";
import { ActivatedRoute } from "@angular/router";
import { FieldModel } from "../../../../services/field.model";
import { EditableFieldsComponent } from "../../fields-builder/components/editable-fields/editable-fields.component";
import { VALIDATION_REQUIRED, FIELD_TOOLTIP, INSTRUCTIONAL_TEXT } from "../../../../../../fields/common/common-constants";
import { ValidatorFn } from "@angular/forms";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { ModalMainFormSize } from "../../services/modal-main-form-size";

@Component({
    selector: "sf-modal-confirmation",
    templateUrl: "./modal-confirmation.component.html",
    encapsulation: ViewEncapsulation.None
})
export class ModalConfirmationComponent implements OnInit {
    @ViewChild(EditableFieldsComponent, { static: false }) editableFields: EditableFieldsComponent;
    @Input() action: string;
    @Input() icon: string;
    @Input() title: string;
    @Input() description: string;
    @Input() descriptionAllowHtml: boolean;
    @Input() itemTitle: string;
    @Input() entitySet: string;
    @Input() parameters: any[];
    @Input() formValidators: ValidatorFn | ValidatorFn[];
    @Input() mainFormSize: ModalMainFormSize;
    @Input() innerFormLook: string;
    @Input() warning: string;
    @Input() counter: number;
    dataItem: DataItem;
    innerFormClassList: string;

    public fieldSections: FieldSectionModel[];
    private fieldSection: FieldSectionModel;

    constructor(private fieldsProvider: CompositeFieldsProvider, route: ActivatedRoute) {
    }

    ngOnInit(): void {
        if (this.parameters) {
            const fieldModels: FieldModel[] = this.parameters.map(param => {
                const key = FieldTypes[param.Type] || FieldTypes[KEY_MAPPINGS[param.Type]];
                const model = createFieldModel(
                    this.fieldsProvider,
                    this.entitySet,
                    key,
                    param.Name,
                    param.Value,
                    <any>{
                        properties: {
                            [param.Name]: {
                                [VALIDATION_REQUIRED]: param.Required,
                                [FIELD_TOOLTIP]: param.Tooltip,
                                [INSTRUCTIONAL_TEXT]: param.Hint,
                                dataItem: this.dataItem,
                                arguments: param.Arguments
                            }
                        }
                    },
                    param.Title, param.FriendlyTitle);

                model.settings.showTitle = !!param.Title;

                if (param.Placeholder) {
                    model.settings.placeholder = param.Placeholder;
                }

                this.updateModelProperties(param, model);
                return model;
            });

            this.mainFormSize = this.mainFormSize || ModalMainFormSize.Medium;
            this.innerFormClassList = this.generateInnerFormClassList();

            this.fieldSection = new FieldSectionModel({ isMain: true, isExpanded: false, insertHorizontalRule: false });

            this.fieldSection.fields = fieldModels;
            this.fieldSections = [this.fieldSection];
        }
    }

    protected generateInnerFormClassList() {
        const mainInnerFormClassList = "sf-form";
        const defaultInnerFormLook = "-small -sf-pt-zero -sf-txt-align-left -sf-centered-box";
        const calculatedInnerFormLook = this.innerFormLook ? "-" + this.innerFormLook.split(" ").join(" -") : defaultInnerFormLook;
        return `${mainInnerFormClassList} ${calculatedInnerFormLook}`;
    }

    private updateModelProperties(param, model) {
        if (param.Type === "choiceDropDown") {
            const dropdownOptions = JSON.parse(param.Value).map(el => {
                const name = el.valueTitle;
                const value = el.valueContent;

                return {
                    Name: name,
                    Value: value
                };
            });

            model.settings.choices = dropdownOptions;
            model.settings.defaultValue = dropdownOptions.length > 0 ? dropdownOptions[0].Value : null;
            model.value = dropdownOptions.length > 0 ? dropdownOptions[0].Value : null;
        }
    }
}

const KEY_MAPPINGS = Object.freeze({
    "long-string": "textArea"
});
