import { Injectable } from "@angular/core";
import { Observable, ReplaySubject } from "rxjs";

@Injectable()
export class GridReloadService {
    reloadRequested: Observable<void>;

    private reloadRequest$: ReplaySubject<void> = new ReplaySubject(1);

    constructor() {
        this.reloadRequested = this.reloadRequest$.asObservable();
    }

    requestReload() {
        this.reloadRequest$.next(null);
    }
}