import { Component, Input, OnInit } from "@angular/core";
import { TreeNode } from "@circlon/angular-tree-component";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { RelativeDatePipe } from "../pipes/relative-date.pipe";
import { ACTION_READ_UNREAD } from "./notifications.component";
import { CompositeSystemNotificationIconProvider } from "./system-notification-icon-provider";

@Component({
    selector: "sf-system-notification-item",
    templateUrl: "./system-notification-item.component.html"
})
export class SystemNotificationItemComponent implements OnInit {
    @Input() node: TreeNode;
    readonly TIME_FORMAT: string = RelativeDatePipe.TIME;
    iconClass: string;
    iconColorLook: string;

    constructor(private dynamicItemService: DynamicItemService, private compositeSystemNotificationIconProvider: CompositeSystemNotificationIconProvider) {
    }

    ngOnInit(): void {
        if (this.node.data.NotificationKey) {
            this.iconClass = this.compositeSystemNotificationIconProvider.parseIconInternal(this.node.data.NotificationKey, this.node.data.NotificationType);
            this.iconColorLook = this.compositeSystemNotificationIconProvider.getIconColor(this.node.data.NotificationType);
        }
    }

    onCheckClicked(node: TreeNode, e: Event) {
        e.stopPropagation();

        this.dynamicItemService.executeUnboundFunction(`${ACTION_READ_UNREAD}(messageJobId=${node.data.MessageJobId}, isRead=${!node.data.IsRead})`).subscribe(() => {
            node.data.IsRead = !node.data.IsRead;
        });
    }
}
