import { Injectable } from "@angular/core";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { HttpODataRequestWrapper } from "../../../../shared/services/http-odata-request.wrapper";
import { VIEW_NAME } from "../../../constants";
import { FormData } from "../../services/backend-tweaks/backend-tweaks.store";
import { MarkupSection } from "@progress/sitefinity-component-framework";

@Injectable()
export class BackendTweaksService {
    constructor(
        private metadataStore: MetadataStore,
        private httpRequestWrapper: HttpODataRequestWrapper) { }

    getGridTweaks(typeName: string) {
        return this.getServiceData({ typeName, viewName: VIEW_NAME.LIST });
    }

    getFormTweaks(typeName: string, formType: string, itemId: string, itemProvider: string, itemCulture: string, parentId?: string): Promise<FormData[]> {
        return this.getServiceData({ typeName, viewName: formType, sf_item_id: itemId, sf_provider: itemProvider, sf_culture: itemCulture, sf_parent_id: parentId }).then((data) => {
            return this.loadFormData(data);
        });
    }

    private getServiceData(serviceData: ServiceData) {
        const entitySet = this.metadataStore.getValue().entities[serviceData.typeName];
        serviceData.typeName = entitySet.typeFullName;

        let resultRequest = "sfui?";
        resultRequest += Object.keys(serviceData).filter(x => x && serviceData[x]).map(key => `${key}=${serviceData[key]}`).join("&");

        return this.httpRequestWrapper.get(resultRequest);
    }

    private loadFormData(data: any): FormData[] {
        return (data.value || []).map(tweak => {
            return Object.freeze({
                id: tweak.Id,
                isExpandedByDefault: tweak.IsExpandedByDefault,
                isSection: tweak.IsSection,
                name: tweak.Name,
                title: tweak.Title,
                renderChoicesAs: tweak.RenderChoicesAs,
                isHtml: tweak.IsHtml,
                maximumAllowedSize: tweak.MaximumAllowedSize,
                allowedFileExtensions: tweak.AllowedFileExtensions,
                acceptableMediaTypes: tweak.AcceptableMediaTypes,
                metadata: tweak.Metadata,
                tooltipModels: new Map<string, MarkupSection[]>(Object.entries(tweak.TooltipModels || {}))
            });
        });
    }
}

interface ServiceData {
    typeName: string;
    viewName: string;
    sf_item_id?: string;
    sf_culture?: string;
    sf_provider?: string;
    sf_parent_id?: string;
}
