import { Component, OnInit } from "@angular/core";

import { ShortTextComponent } from "./short-text.component";
import { createValueAccessor } from "../field-base";
import { DEFAULT_MARKUP_KEY, MarkupSection } from "@progress/sitefinity-component-framework";

const READONLY_CLASS = "sf-input -title";

@Component({
    selector: "sf-short-text-default",
    templateUrl: "./short-text-default.component.html",
    providers: [createValueAccessor(ShortTextDefaultComponent)]
})
export class ShortTextDefaultComponent extends ShortTextComponent implements OnInit {
    readonlyCssClass: string;
    hint: MarkupSection[];

    ngOnInit() {
        if (this.settings.readOnlyMode) {
            this.readonlyCssClass = this.generateCssClass();
        }

        if (this.settings.tooltipModels && this.settings.tooltipModels.size > 0) {
           this.hint = this.getTooltip();
        }
    }

    generateCssClass(): string {
        let cls = READONLY_CLASS;
        if (this.settings.look) {
            cls += " -" + this.settings.look.split(" ").join(" -");
        }
        return cls;
    }

    getTooltip(): MarkupSection[] {
        const tooltips = this.settings.tooltipModels;
        const key = tooltips.has(DEFAULT_MARKUP_KEY) ? DEFAULT_MARKUP_KEY : this.getValue();

        return tooltips.get(key);
    }
}
