import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Injectable } from "@angular/core";
import { Properties } from "../../shared/fields.constants";
import { ChoiceServiceUrlComponent } from "../../../../../fields/choice/choice-service-url.component";
import { MixedContentValue } from "../providers/fields/content/content-selector.component";
import { FieldBase } from "../../../../../fields/field-base";
import { PropertyEditorWidgets } from "../property-editor.constants";

@Injectable()
export class ContentListWidgetFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === Properties.SELECTED_ITEMS) {
            ContentListWidgetFieldsChangeService.processSelectedItemsFieldChange(changedValue, fields.map(x => x.currentInstance));
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === PropertyEditorWidgets.CONTENT_LIST;
    }

    static processSelectedItemsFieldChange(changedValue: any, fields: FieldBase[]): boolean {
        const orderByField = this.getOrderByField(fields);
        if (orderByField && orderByField.initialChoices) {
            if ((changedValue as MixedContentValue)?.ItemIdsOrdered?.length > 0) {
                orderByField.setChoices(orderByField.initialChoices);
            } else {
                orderByField.setChoices(orderByField.initialChoices.filter(x => x.Value !== "Manually"));
            }

            return true;
        }

        return false;
    }

    private static getOrderByField(fields: FieldBase[]): ChoiceServiceUrlComponent {
        const field = fields.find(x => x.settings.key === Properties.ORDER_BY);
        if (field && field instanceof ChoiceServiceUrlComponent) {
            return field;
        }

        return null;
    }
}

export const CONTENT_LIST_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: ContentListWidgetFieldsChangeService,
    multi: true
};
