import { Command } from "../../shared/commands/command";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { Observable, of } from "rxjs";
import { ModalWindowService, DialogData } from "../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { VideoPlayerComponent } from "../../../../../fields/media/video/video-player.component";

const PLAY_VIDEO_MAPPING = "playVideo";

export class PlayVideoCommand implements Command {
    constructor(private modalWindowService: ModalWindowService) { }

    execute(context: ExecutionContext): Observable<any> {
        const componentData: ComponentData = {
            type: VideoPlayerComponent,
            properties: {
                src: context.data.dataItem.data.Url,
                look: "play-detached sf-centered-box"
            }
        };

        const dialogData = new DialogData(componentData, null, [], "-prompt");
        this.modalWindowService.setMapping(dialogData, PLAY_VIDEO_MAPPING);
        this.modalWindowService.show(PLAY_VIDEO_MAPPING, context.currentRoute.parent);

        return of(true);
    }
}
