import { Component, OnInit, Output, EventEmitter, Input, ViewChild, TemplateRef } from "@angular/core";
import { NavbarConfiguration, NavbarModes, LeftNavbarButtonMode } from "../navigation/navigation-menu/navigation-menu.component";
import { SelectorConstants } from "../../../html/selector-constants";
import { stringConstants } from "../../../../common-constants";
import { environmentTypes } from "../../../../environment";
import { ActivatedRoute } from "@angular/router";
import { Observable } from "rxjs";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { ActionButton, ButtonState } from "../action-menu/action-menu-model";
import { Operation } from "../action-menu/operation.model";
import { BackNavigationService } from "../../services/back-navigation.service";
import { environment } from "../../../../../environments/environment";
import { AppStore } from "../../../../services/store/app-store";
import { SIDEBAR_SELECTORS } from "../../../../services/store/selectors/selectors.sidebar";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../services/store/actions/actions.sidebar";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-edit-item-menu",
    templateUrl: "./edit-menu.component.html"
})
export class EditItemMenuComponent extends SfRxBase implements OnInit {
    @Input() navbarConfiguration: NavbarConfiguration;
    @Input() item$: Observable<DataItem>;
    @Input() customOperations: Observable<Operation[]>;
    @Input() generalActionOperations: Observable<Operation[]>;
    @Input() additionalActionOperations: Observable<Operation[]>;
    @Input() personalizationOperations: Observable<Operation[]>;
    @Input() buttonsState: ButtonState;
    @Input() entityData: EntityData;
    @Input() parentId: string;
    @Input() filterCleared: boolean;
    @Input() enableClickNotification: boolean;

    @Output() onBackButtonClick: EventEmitter<void>;
    @Output() onActionButtonClick: EventEmitter<ActionButton>;

    disableLeftNavbarButton: boolean;
    hasContentCultures: boolean;
    showSidebarButtons: boolean;

    @ViewChild("itemStatus", { static: true })
    private itemStatusTemplate: TemplateRef<any>;

    @ViewChild("additionalActions", { static: true })
    private additionalActionsTemplate: TemplateRef<any>;

    @ViewChild("generalActions", { static: true })
    private generalActionsTemplate: TemplateRef<any>;
    private isNavigationEmbedded: boolean;

    constructor(private route: ActivatedRoute, private backNavigationService: BackNavigationService, private store: AppStore) {
        super();
        this.isNavigationEmbedded = environment.env === environmentTypes.integration;
        this.onBackButtonClick = new EventEmitter<void>();
        this.onActionButtonClick = new EventEmitter<ActionButton>();
    }

    ngOnInit(): void {
        const isMultilingual = (this.entityData && this.entityData.metadata) ? this.entityData.metadata.isMultilingual : true;
        this.hasContentCultures = this.route.parent.snapshot.data.siteDataStore.ContentCultures.length > 1 && isMultilingual;
        this.configureNavbar(this.navbarConfiguration);
        this.registerSubscription(this.store.pipe(SIDEBAR_SELECTORS.sidebarData).subscribe(x => this.showSidebarButtons = !!x));
    }

    onLeftNavButtonClick(): void {
        if (this.navbarConfiguration.leftNavbarButtonData.autoNavigateBack) {
           this.backNavigationService.navigateBack({
               entityData: this.entityData,
               filterCleared: this.filterCleared,
               parentId: this.parentId,
               route: this.route
           });
        } else {
            this.onBackButtonClick.emit();
        }

        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.change(null));
    }

    onActionButtonClicked(button: ActionButton) {
        this.onActionButtonClick.emit(button);
    }

    private configureNavbar(navbarConfiguration: NavbarConfiguration) {
        const defaultConfig: NavbarConfiguration = {
            mode: NavbarModes.ThreeColumns,
            leftNavbarButtonData: {
                show: true,
                look: "toggle",
                icon: "angle-left",
                iconLook: "size-2xl",
                mode: LeftNavbarButtonMode.Back,
                title: SelectorConstants.ALL_ITEMS,
                autoNavigateBack: true
            },
            isScrollEnabled: false,
            look: this.isNavigationEmbedded ? "integration-detail" : stringConstants.EMPTY_STRING,
            templates: [
                this.itemStatusTemplate,
                this.additionalActionsTemplate,
                this.generalActionsTemplate
            ]
        };

        this.copy(defaultConfig, navbarConfiguration);

        if (defaultConfig.leftNavbarButtonData.disable) {
            defaultConfig.leftNavbarButtonData.disable.subscribe((disable) => {
                this.disableLeftNavbarButton = disable;
            });
        }

        this.navbarConfiguration = defaultConfig;
    }

    private copy(source: any, target: any): void {
        if (!target)
            return;
        Object.keys(target).forEach((key) => {
            const sourceValue = source[key];
            const targetValue = target[key];
            if (typeof sourceValue === "object") {
                this.copy(sourceValue, targetValue);
            } else {
                source[key] = targetValue;
            }
        });
    }
}
