import { ZoneEditorDomService } from "../components/zone-editor/zone-editor-dom-service";
import { CLASS_EMPTY, CLASS_ZONE_TOOLBAR, NODE_TYPE_COMMENT, NODE_NAME_ADD_WIDGET, ATTR_COMPONENT_ID, CLASS_INLINE_BLOCK, CLASS_ZONE_QUICKEDIT, NODE_NAME_FAKE_WIDGET, CLASS_PERSONALIZED_WIDGET_LOOK, CLASS_HIDDEN, CLASS_ZONE_WIDGET, NODE_NAME_INLINE_TOOLBAR, NODE_NAME_EMPTY_WIDGET } from "./document-enhancer.constants";
import { ComponentModel, ContainerModel } from "../components/zone-editor/model/component-model";
import { Injectable, Type, ComponentRef, Output, EventEmitter } from "@angular/core";
import { HtmlElementAttachMode } from "../components/zone-editor/html-element-attach-modes";
import { AddWidgetComponent } from "../components/zone-editor/add-widget/add-widget.component";
import { EmptyWidgetComponent } from "../components/zone-editor/empty-widget/empty-widget.component";
import { KeyValue } from "@angular/common";
import { InlineToolbarComponent } from "../components/zone-editor/inline-toolbar/inline-toolbar.component";
import { ErrorWidgetComponent } from "../components/zone-editor/error-widget/error-widget.component";
import { WidgetLabelComponent } from "../components/zone-editor/widget-label/widget-label.component";
import { DocumentEnhancerService } from "./document-enhancer.service";
import { FakeWidgetComponent } from "../components/zone-editor/fake-widget/fake-widget.component";
import { EditorStateResponse, WidgetState } from "./zone-editor.contract";
import { RenderResult } from "./renderer.types";

@Injectable()
export class ZoneEditorTreeService {
    @Output() emptyContainerAdded: EventEmitter<EmptyContainerAddedArgs> = new EventEmitter();
    @Output() widgetAdded: EventEmitter<WidgetAddedArgs> = new EventEmitter();
    @Output() addWidgetAdded: EventEmitter<AddWidgetAddedArgs> = new EventEmitter();

    commonToolbarOptions: object;
    emptyMessageLabel: string;
    addMessageLabel: string;
    addMessageForEmptyScreenLabel: string;
    emptyRootClasses: string[];

    constructor(
        private zoneEditorDomService: ZoneEditorDomService,
        private documentEnhancer: DocumentEnhancerService
    ) { }

    public initializeTree(rootContainerElement: Element, parentElement: Element, state: EditorStateResponse): ContainerModel {
        const model = this.documentEnhancer.buildModel(rootContainerElement, parentElement, null) as ContainerModel;
        if (model) {
            model.addAllowed = state.AddAllowed;
            this.assignState(model, state.WidgetState);
            this.iterateTree(model, this.initComponent.bind(this, true), this.initContainer.bind(this));
        }

        return model;
    }

    public iterateTree(parent: ContainerModel | ComponentModel, componentCallBack: (model: ComponentModel) => void, containerCallBack: (model: ContainerModel) => void) {
        let childCollection: Array<ComponentModel | ContainerModel>;
        if (parent instanceof ComponentModel) {
            if (componentCallBack)
                componentCallBack(parent);

            if (parent.isContainer) {
                childCollection = [parent.container];
            } else {
                childCollection = parent.childContainers;
            }
        } else {
            if (containerCallBack)
                containerCallBack(parent);

            parent.childContainers.forEach((component) => {
                this.iterateTree(component, componentCallBack, containerCallBack);
            });

            childCollection = parent.children;
        }

        childCollection.forEach((component) => {
            this.iterateTree(component, componentCallBack, containerCallBack);
        });
    }

    public findComponent(parent: ContainerModel | ComponentModel, componentId: string): ComponentModel {
        let result: ComponentModel;
        this.iterateTree(parent, (model) => {
            if (model.id === componentId) {
                result = model;
            }
        }, null);

        return result;
    }

    addNodeFromHtml(parentContainer: ContainerModel, state: WidgetState[], renderResult: RenderResult, incomingElement: Element): ComponentModel {
        const containerElement = this.createDomElement(renderResult);
        const componentModel = this.insertHtmlAndEnhance(incomingElement, containerElement, parentContainer.parentComponent);
        componentModel.parentContainer = parentContainer;
        this.assignState(componentModel, state);
        this.iterateTree(componentModel, this.initComponent.bind(this, false), this.initContainer.bind(this));
        return componentModel;
    }

    removeNode(component: ComponentModel): void {
        this.removeFromParent(component);

        this.tryAddEmptyWidget(component.parentContainer);

        component.clear();
        this.regenerateAddWidgets(component.parentContainer.children, false);
    }

    removeQuickEditMenu(component: ComponentModel): void {
        if (component?.quickEditMenu) {
            this.zoneEditorDomService.removeComponent(component.quickEditMenu);
            component.quickEditMenu = null;
        }
    }

    refreshNode(component: ComponentModel, state: WidgetState[], renderResult: RenderResult, lazy: boolean): ComponentModel {
        const parentCollection = component.parentContainer.children;
        this.removeFromParent(component);
        const startComment = component.wrappingCommentElements[0] || component.domElement;

        const containerElement = this.createDomElement(renderResult);
        const newComponent = this.insertHtmlAndEnhance(startComment, containerElement, component.parentComponent);
        component.clear();

        newComponent.quickEditMenu = component.quickEditMenu;
        newComponent.parentContainer = component.parentContainer;

        this.assignState(newComponent, state);
        this.iterateTree(newComponent, this.initComponent.bind(this, lazy), this.initContainer.bind(this));

        this.regenerateQuickEditMenu(newComponent);
        this.regenerateAddWidgets(parentCollection, lazy);
        return newComponent;
    }

    moveNode(component: ComponentModel, newParentContainer: ContainerModel, referenceElement?: Element): void {
        const previousCollection = component.parentContainer.children;
        const prevousContainer = component.parentContainer;

        this.removeFromParent(component);
        this.tryAddEmptyWidget(prevousContainer);

        component.parentContainer = newParentContainer;
        component.parentComponent = newParentContainer.parentComponent;
        component.siblingId = this.getPreviousSibling(referenceElement);
        component.clearOrphaned();

        const addLast = !referenceElement;
        const newCollection = this.addComponentInHierarchy(component, addLast);
        this.removeEmptyWidget(newParentContainer);

        if (addLast) {
            if (component.wrappingCommentElements.length > 0 && component.wrappingCommentElements[0])
                component.parentContainer.domElement.appendChild(component.wrappingCommentElements[0]);

            component.parentContainer.domElement.appendChild(component.domElement);

            if (component.wrappingCommentElements.length > 1 && component.wrappingCommentElements[1])
                component.parentContainer.domElement.appendChild(component.wrappingCommentElements[1]);
        } else {
            const newElements: Node[] = [component.domElement];
            if (component.wrappingCommentElements.length > 0 && component.wrappingCommentElements[0])
                newElements.splice(0, 0, component.wrappingCommentElements[0]);
            if (component.wrappingCommentElements.length > 1 && component.wrappingCommentElements[1])
                newElements.push(component.wrappingCommentElements[1]);

            if (this.isFakeOrAddWidget(referenceElement) && this.isInlineElement(referenceElement.parentElement)) {
                this.handleInlineAddElement(referenceElement.parentElement, newElements);
            } else {
                this.zoneEditorDomService.handleMultipleInsertBefore(newElements, referenceElement);
            }
        }

        this.regenerateAddWidgets(previousCollection.concat(newCollection), false);
    }

    getPreviousSibling(element: Element, lazy?: boolean): string {
        if (element) {
            element = !lazy && this.isInlineElement(element.parentElement) ? element.parentElement : element.previousElementSibling;
            while (element && !element.hasAttribute(ATTR_COMPONENT_ID)) {
                element = element.previousElementSibling;
            }
        }

        return element ? element.getAttribute(ATTR_COMPONENT_ID) : null;
    }

    addEmptyWidget(parent: ContainerModel | ComponentModel) {
        const properties = { icon: parent.emptyicon, text: parent.emptyicontext, action: parent.emptyiconaction };
        const isContainer = parent instanceof ContainerModel;
        const canAddToContainer = isContainer && parent.parentComponent && !parent.parentComponent.addAllowed;

        if (isContainer && !canAddToContainer) {
            properties["label"] = (parent as ContainerModel).placeholderlabel;

            if (parent.isRoot) {
                properties["label"] = properties["label"] || this.emptyMessageLabel;
                properties["illustrativeIcon"] = "check-square-o";
                properties.text = this.addMessageForEmptyScreenLabel;

                parent.domElement.classList.add(...this.emptyRootClasses);
            }
        }

        parent.domElement.classList.add(CLASS_EMPTY);

        if (canAddToContainer)
            return;

        const emptyElement = this.addWidget(EmptyWidgetComponent, parent.domElement, properties, HtmlElementAttachMode.InsertAsLastChild);
        parent.emptyWidget = emptyElement;
        if (isContainer)
            this.emptyContainerAdded.emit({ container: parent as ContainerModel });
    }

    removeEmptyWidget(container: ContainerModel) {
        if (!container.isempty) {
            container.domElement.classList.remove(CLASS_EMPTY, ...this.emptyRootClasses);
            container.clearEmptyWidget();
        }
    }

    getPreviousInlineComponent(component: ComponentModel | ContainerModel): ComponentModel {
        if (!(component instanceof ComponentModel)) {
            return null;
        }

        const previousComponent = this.findComponent(component.parentContainer, component.siblingId);
        const isInline = previousComponent && this.isInlineElement(previousComponent.domElement);

        return isInline ? previousComponent : null;
    }

    public addInlineToolbar(component: ComponentModel): void {
        if (!component.inlineToolbarComponent && component.editAllowed) {
            const toolbarOptions = this.commonToolbarOptions;
            (<any>toolbarOptions).component = component;
            const inlineToolbarReference = this.zoneEditorDomService.createComponent(InlineToolbarComponent, toolbarOptions);
            this.zoneEditorDomService.attachComponentAsFirstChild(inlineToolbarReference, component.domElement, CLASS_ZONE_TOOLBAR, null);
            component.inlineToolbarComponent = inlineToolbarReference;
        }
    }

    public addLabelElement(component: ComponentModel): void {
        if (!component.label) {
            let labelElement;
            // place your fancy css for the orange personalization in the WidgetLabelComponent, component.isPersonalized has the data you are looking for
            const labelLook = component.isPersonalized ? CLASS_PERSONALIZED_WIDGET_LOOK : null;
            const properties = { label: component.title, tooltip: component.labelTooltip, hideDraggableIcon: !component.moveAllowed, look: labelLook };

            if (component.domElement.firstChild) {
                labelElement = this.addWidget(WidgetLabelComponent, component.domElement.firstChild, properties, HtmlElementAttachMode.InsertBefore);
            } else {
                labelElement = this.addWidget(WidgetLabelComponent, component.domElement, properties, HtmlElementAttachMode.InsertAsFirstChild);
            }

            component.label = labelElement.location.nativeElement;
        }
    }

    public initAddWidgets(component: ComponentModel) {
        if (component && !component.addWidgetsInitialized) {
            component.clearAddWidgets();
            this.insertAddWidgetBetweenSections(component, false);
            component.addWidgetsInitialized = true;
        }
    }

    public initPreviousAddWidget(component: ComponentModel) {
        const previousComponent = this.findComponent(component.parentContainer, component.siblingId);

        if (previousComponent) {
            this.initAddWidgets(previousComponent);
        }
    }

    public isInlineElement(element: Element) {
        if (!element) {
            return false;
        }

        const displayStyles = getComputedStyle(element).display;
        const isDisplayInline = displayStyles === "inline" || displayStyles === "inline-block";
        const isHiddenInline = element.classList.contains(CLASS_INLINE_BLOCK) && element.classList.contains(CLASS_HIDDEN);
        return isDisplayInline || isHiddenInline;
    }

    public isFakeOrAddWidget(element: Element): boolean {
        return this.isFakeWidget(element) || this.isAddWidget(element);
    }

    public isFakeWidget(element: Element): boolean {
        return element.nodeName === NODE_NAME_FAKE_WIDGET;
    }

    public isAddWidget(element: Element): boolean {
        return element.nodeName === NODE_NAME_ADD_WIDGET;
    }

    public isZoneWidget(element: HTMLElement): boolean {
        return element.classList.contains(CLASS_ZONE_WIDGET);
    }

    public isInlineToolbar(element: HTMLElement): boolean {
        return element.nodeName === NODE_NAME_INLINE_TOOLBAR;
    }

    public isEmtpyWidget(element: HTMLElement): boolean {
        return !!element.closest(NODE_NAME_EMPTY_WIDGET);
    }

    public getSibligAddWidgetElement(component: ContainerModel | ComponentModel, getNext?: boolean): HTMLElement | null {
        if (!component) {
            return;
        }

        let addWidgetElement;
        const componentModel = component instanceof ContainerModel ? component.parentComponent : component;
        const container = component.domElement.closest(`.${CLASS_ZONE_WIDGET}`);
        this.initAddWidgets(componentModel);
        this.initPreviousAddWidget(componentModel);

        if (this.isInlineElement(container)) {
            addWidgetElement = this.getSibligAddWidgetInlineElement(container, componentModel, getNext);
        } else if (!getNext && this.isInlineElement(container.previousElementSibling)) {
            addWidgetElement = this.getSibligAddWidgetInlineElement(container.previousElementSibling, componentModel, true);
        } else if (getNext) {
            addWidgetElement = container.nextElementSibling;
        } else {
            addWidgetElement = container.previousElementSibling;
        }

        if (addWidgetElement && this.isAddWidget(addWidgetElement)) {
            return addWidgetElement;
        }
    }

    private createDomElement(renderResult: RenderResult): HTMLElement {
        const containerElement = document.createElement("div");
        if (renderResult.content)
            containerElement.innerHTML = renderResult.content;
        else if (renderResult.element)
            containerElement.appendChild(renderResult.element);

        return containerElement;
    }

    private getSibligAddWidgetInlineElement(element: Element, component: ComponentModel, getNext?: boolean) {
        if (!element) {
            return;
        }

        let addWidgetElement;
        const previousInlineComponent = this.getPreviousInlineComponent(component);

        if (!getNext && previousInlineComponent) {
            this.initAddWidgets(previousInlineComponent);

            addWidgetElement = this.getSibligAddWidgetInlineElement(element.previousElementSibling, previousInlineComponent, true);
        } else if (!getNext) {
            const previousComponent = this.findComponent(component.parentContainer, component.siblingId);

            this.initAddWidgets(previousComponent || component.parentComponent);

            addWidgetElement = element.previousElementSibling;
        } else {
            addWidgetElement = element.querySelector(NODE_NAME_ADD_WIDGET);
        }

        return addWidgetElement;
    }

    private assignState(container: ContainerModel | ComponentModel, state: WidgetState[]) {
        if (!state)
            return;

        this.iterateTree(container, (component) => {
            const widgetState = state.find(x => x.Key === component.id);
            component.assignState(widgetState);
        }, null);
    }

    private tryAddEmptyWidget(container: ContainerModel | ComponentModel): void {
        if (!container.isemptyvisualhidden && (container.isempty || (container instanceof ContainerModel && container.hasOnlyOrphans())) && !container.emptyWidget) {
            this.addEmptyWidget(container);
        }
    }

    private initContainer(container: ContainerModel) {
        this.tryAddEmptyWidget(container);
    }

    private regenerateAddWidgets(collection: ComponentModel[], asLazy: boolean) {
        if (!asLazy) {
            collection.forEach(x => x.clearAddWidgets());
        }
        collection.forEach(x => this.insertAddWidgetBetweenSections(x, asLazy));
    }

    //The component will be inserted before the incoming element.
    //We don't need to render the component dom in the initial load; will render it only during add widget and move widget.
    private initComponent(lazy: boolean, component: ComponentModel): void {
        this.addComments(component);

        //Add label for the new component (left or right)
        this.insertAddWidgetBetweenSections(component, lazy);

        if ((component.error || component.warning) && !component.errorWidget) {
            component.errorWidget = this.addWidget(ErrorWidgetComponent, component.domElement, { error: component.error, warning: component.warning }, HtmlElementAttachMode.InsertAsFirstChild);
        }

        component.siblingId = this.getPreviousSibling(component.domElement, lazy);
        this.addComponentInHierarchy(component, false);
        this.removeEmptyWidget(component.parentContainer);

        if (component.iscontentwidget && component.editAllowed && !component.isContainer)
            this.tryAddEmptyWidget(component);

        if (component.isContainer) {
            this.initContainer(component.container);
        }

        this.widgetAdded.next({ component: component });
    }

    //Add the element to the children collection of the parent, respecting the component siblingId
    private addComponentInHierarchy(component: ComponentModel, addLast: boolean): ComponentModel[] {
        const parentCollection = component.parentContainer.children;
        let insertInPosition = 0;

        const componentExists = parentCollection.some((child) => component.id === child.id);
        if (componentExists)
            return;

        if (component.siblingId) {
            insertInPosition = parentCollection.findIndex((child) => component.siblingId === child.id) + 1;
        }

        if (insertInPosition >= 0 && !addLast) {
            parentCollection.splice(insertInPosition, 0, component);
            if (parentCollection[insertInPosition + 1]) {
                parentCollection[insertInPosition + 1].siblingId = component.id;
            }
        } else {
            if (parentCollection[parentCollection.length - 1]) {
                component.siblingId = parentCollection[parentCollection.length - 1].id;
            }
            parentCollection.push(component);
        }

        return parentCollection;
    }

    private removeFromParent(component: ComponentModel): void {
        const childCollectionInContainer = component.parentContainer.children;
        const indexOfCurrentChild = childCollectionInContainer.findIndex(child => child.id === component.id);
        if (indexOfCurrentChild > -1) {
            childCollectionInContainer.splice(indexOfCurrentChild, 1);
            if (indexOfCurrentChild === 0) {
                component.siblingId = null;
            } else if (childCollectionInContainer[indexOfCurrentChild]) {
                childCollectionInContainer[indexOfCurrentChild].siblingId = childCollectionInContainer[indexOfCurrentChild - 1].id;
            }
        }
    }

    private addComments(component: ComponentModel): void {
        if (component.wrappingCommentElements.length === 0) {
            let node: Node = component.domElement;

            // eslint-disable-next-line no-constant-condition
            while (true) {
                if (!node || (node.nodeType === NODE_TYPE_COMMENT && node.nodeValue.indexOf(component.id) !== -1)) {
                    break;
                }
                node = node.previousSibling;
            }
            component.wrappingCommentElements.push(node);
            node = component.domElement;

            // eslint-disable-next-line no-constant-condition
            while (true) {
                if (!node || (node.nodeType === NODE_TYPE_COMMENT && node.nodeValue.indexOf(component.id) !== -1)) {
                    break;
                }
                node = node.nextSibling;
            }
            component.wrappingCommentElements.push(node);
        }
    }

    private regenerateQuickEditMenu(component: ComponentModel): void {
        if (component.quickEditMenu) {
            this.zoneEditorDomService.attachComponentAsFirstChild(component.quickEditMenu, component.domElement, CLASS_ZONE_QUICKEDIT, null);
        }
    }

    private insertAddWidgetBetweenSections(component: ComponentModel, lazy: boolean) {
        // if after an operation (delete, drag) we have one widget, then the placeholder is going to be empty, so we add
        // the empty widget component
        if (component.isorphaned) {
            return;
        }

        const previousElementSibling = component.domElement.previousElementSibling;
        const nextElementSibling = component.domElement.nextElementSibling;
        const currentAddWidget = this.isInlineElement(component.domElement) ? component.domElement.lastElementChild : component.domElement;
        const previousAddWidget = previousElementSibling && this.isInlineElement(previousElementSibling) ? previousElementSibling.lastElementChild : previousElementSibling;
        const hasAddWidgetAfter = (currentAddWidget && this.isFakeOrAddWidget(currentAddWidget)) || (nextElementSibling && this.isFakeOrAddWidget(nextElementSibling));
        const hasAddWidgetBefore = previousAddWidget && this.isFakeOrAddWidget(previousAddWidget);

        let insertMode;
        if (!hasAddWidgetAfter && !hasAddWidgetBefore) {
            insertMode = HtmlElementAttachMode.InsertBeforeAndAfter;
        } else if (!hasAddWidgetBefore) {
            insertMode = HtmlElementAttachMode.InsertBefore;
        } else if (!hasAddWidgetAfter) {
            insertMode = HtmlElementAttachMode.InsertAfter;
        } else {
            return;
        }

        this.insertAddWidget(insertMode, component, lazy);
    }

    private insertAddWidget(mode: HtmlElementAttachMode, component: ComponentModel, lazy: boolean) {
        const addWidgets: ComponentRef<FakeWidgetComponent | AddWidgetComponent>[] = [];
        //add section widgets, direct children of the body, should have an Add section label
        let addWidgetProperties = component.isRoot ? { addWidgetLabel: this.addMessageLabel } : null;
        let attributes = { ATTR_DRAGGABLE : false };
        let componentType: Type<FakeWidgetComponent | AddWidgetComponent> = AddWidgetComponent;

        const restrictedAddToRootContainer = !component.parentContainer?.addAllowed;
        const restrictedAddToParentComponent = component.parentComponent && !component.parentComponent.addAllowed;

        if (restrictedAddToRootContainer || restrictedAddToParentComponent) {
            return;
        }

        if (lazy) {
            attributes = null;
            addWidgetProperties = null;
            componentType = FakeWidgetComponent;
        }

        if (mode === HtmlElementAttachMode.InsertAsFirstAndLastChild) {
            addWidgets.push(this.addWidget(componentType, component.domElement, addWidgetProperties, HtmlElementAttachMode.InsertBefore, null, attributes));
            addWidgets.push(this.addWidget(componentType, component.domElement.parentElement, addWidgetProperties, HtmlElementAttachMode.InsertAsLastChild, null, attributes));

        } else if (mode === HtmlElementAttachMode.InsertBeforeAndAfter) {
            addWidgets.push(this.addWidget(componentType, component.wrappingCommentElements[0] || component.domElement, addWidgetProperties, HtmlElementAttachMode.InsertBefore, null, attributes));
            addWidgets.push(this.addWidget(componentType, component.wrappingCommentElements[1] || component.domElement, addWidgetProperties, HtmlElementAttachMode.InsertAfter, null, attributes));

        } else if (mode === HtmlElementAttachMode.InsertBefore) {
            addWidgets.push(this.addWidget(componentType, component.wrappingCommentElements[0] || component.domElement, addWidgetProperties, mode, null, attributes));
        } else if (mode === HtmlElementAttachMode.InsertAfter) {
            addWidgets.push(this.addWidget(componentType, component.wrappingCommentElements[1] || component.domElement, addWidgetProperties, mode, null, attributes));
        } else {
            addWidgets.push(this.addWidget(componentType, component.domElement, addWidgetProperties, mode, null, attributes));
        }

        addWidgets.forEach((addWidget) => {
            component.addWidgetComponents.push(addWidget);

            if (!lazy) {
                // If the previous element is inline we need to place the add widget inside it
                const previousSibling = (addWidget.location.nativeElement as HTMLElement).previousElementSibling;
                if (previousSibling && this.isInlineElement(previousSibling)) {
                    this.modifyAddWidgetElement(addWidget.location.nativeElement);
                }

                const cast = addWidget as ComponentRef<AddWidgetComponent>;
                this.addWidgetAdded.emit({ addWidget: cast, component });
            }
        });
    }

    private modifyAddWidgetElement(addWidgetElement: HTMLElement) {
        const previousSibling = addWidgetElement.previousElementSibling;
        const nextSibling = addWidgetElement.nextElementSibling;
        let hostElement = previousSibling;

        // When drag and drop inline elements and it is the last element in container the new inline widget is placed after the add widget
        if (previousSibling.lastElementChild &&
            this.isFakeOrAddWidget(previousSibling.lastElementChild) &&
            this.isInlineElement(nextSibling) &&
            !this.isFakeOrAddWidget(nextSibling.lastElementChild)) {
            hostElement = nextSibling;
        }

        hostElement.append(addWidgetElement);
    }

    private addWidget<T>(component: Type<T>, sibling: Node, componentProps: {}, attachMode: HtmlElementAttachMode, componentClass?: string, attribute?: {}): ComponentRef<T> {
        const widget = this.zoneEditorDomService.createComponent(component, componentProps);
        switch (attachMode) {
            case HtmlElementAttachMode.InsertAsFirstChild: {
                this.zoneEditorDomService.attachComponentAsFirstChild(widget, sibling as Element, componentClass, attribute);
                break;
            }
            case HtmlElementAttachMode.InsertAsLastChild: {
                this.zoneEditorDomService.attachComponentAsLastChild(widget, sibling as Element, componentClass, attribute);
                break;
            }
            case HtmlElementAttachMode.InsertAfter: {
                this.zoneEditorDomService.attachComponentAfterElement(widget, sibling, componentClass, attribute);
                break;
            }
            default: {
                this.zoneEditorDomService.attachComponentBeforeElement(widget, sibling, componentClass, attribute);
                break;
            }
        }

        return widget;
    }

    private insertHtmlAndEnhance(referenceNode: Node, containerElement: HTMLElement, parentComponent: ComponentModel): ComponentModel {
        this.insertElementBeforeNode(referenceNode, containerElement);
        this.documentEnhancer.enhance(containerElement);

        const element = containerElement.firstElementChild;
        const component = this.documentEnhancer.buildModel(element, element, parentComponent) as ComponentModel;
        this.unwrapHtml(containerElement);
        return component;
    }

    private insertElementBeforeNode(referenceNode: Node, containerElement: HTMLElement): void {
        if (this.isInlineElement(referenceNode.parentElement)) {
            this.handleInlineAddElement(referenceNode.parentElement, [containerElement]);
        } else {
            referenceNode.parentElement.insertBefore(containerElement, referenceNode);
        }
    }

    private handleInlineAddElement(inlineElement: Element, newElements: Node[]) {
        const elements = Array.isArray(newElements) ? newElements : [newElements];
        const parentElement = inlineElement.parentElement;
        const nextElementSibling = inlineElement.nextElementSibling;

        if (nextElementSibling) {
            this.zoneEditorDomService.handleMultipleInsertBefore(elements, nextElementSibling);
        } else {
            this.zoneEditorDomService.handleMultipleAppend(elements, parentElement);
        }
    }

    private unwrapHtml(containerElement: Element) {

        const copy = [];
        containerElement.childNodes.forEach(node => {
            copy.push(node);
        });

        copy.forEach(node => {
            containerElement.parentElement.insertBefore(node, containerElement);
        });

        containerElement.remove();
    }
}

export class LayoutComponentsModel {
    componentsTree: ComponentModel[] = [];
    containersCollection: ContainerModel[] = [];
    flatComponentsCollection: KeyValue<string, ComponentModel>[] = [];
}

export interface EmptyContainerAddedArgs {
    container: ContainerModel;
}

export interface WidgetAddedArgs {
    component: ComponentModel
}

export interface AddWidgetAddedArgs {
    component: ComponentModel;
    addWidget: ComponentRef<AddWidgetComponent>;
}
