import { Pipe, PipeTransform } from "@angular/core";

@Pipe({
    name: "sfFileSize"
})
export class FileSizePipe implements PipeTransform {
    /**
     * Converts a number to human readable file size KB, MB etc.
     * @param {string} bytes - The byte count as a number.
     * @return {string} - human readable file size.
     */
    transform(bytes: any) {
        // http://stackoverflow.com/a/18650828/10141
        if (bytes === 0) {
            return "0 Bytes";
        }

        const decimals = 2;

        const sizes = ["Bytes", "KB", "MB", "GB", "TB"];

        const index = Math.floor(Math.log(bytes) / Math.log(1024));

        const numeric = bytes / Math.pow(1024, index);

        return `${parseFloat(numeric.toFixed(decimals))} ${sizes[index]}`;
    }
}
