import { createValueAccessor } from "../../../../../../../fields";
import { AfterViewInit, Component, QueryList, ViewChildren } from "@angular/core";
import { Entity, FieldRegistration, SettingsBase } from "../../../../../api";
import { ShortTextComponent } from "../../../../../../../fields/short-text/short-text.component";
import { FieldInfo, FieldMappingsSettings, ListFieldMappingsBase } from "./list-field-mappings-base";
import { MAX_INTEGER } from "../../../../../common-constants";

@Component({
    selector: "sf-field-mappings-css",
    templateUrl: "./list-field-mappings-css.component.html",
    providers: [createValueAccessor(ListFieldMappingsCssComponent)]
})
export class ListFieldMappingsCssComponent extends ListFieldMappingsBase<FieldMappingsCssSettings> implements AfterViewInit {
    @ViewChildren(ShortTextComponent) cssFields: QueryList<ShortTextComponent>;

    ngAfterViewInit() {
        this.cssFields.changes.subscribe((components: QueryList<ShortTextComponent>) => {
            components.forEach(component => {
                const fieldInfo = this.fields.find(x => x.Title === component.settings.key);
                const existingFieldMapping = this.getValue() ? this.getValue().find(fm => fm.FieldName === fieldInfo.Title) : null;
                if (existingFieldMapping) {
                    component.writeValue(existingFieldMapping.CssClass);
                }

                component.registerOnChange((val) => {
                    this.onFieldNameChange(val, fieldInfo);
                });
            });
        });
    }

    protected modifyFieldInfo(fieldInfo: FieldInfo, entity: Entity, suitableFields: { Name: string, Value: string }[]) {
        fieldInfo.Settings = this.getFieldSettings(fieldInfo);
    }

    protected initFields() {
        super.initFields();

        if (this.settings.cssFieldMappingsShowWrapperClasses) {
            const listWrapperInfo = new FieldInfo();
            listWrapperInfo.Title = "Content list";
            listWrapperInfo.Ordinal = -1;
            listWrapperInfo.Settings = this.getFieldSettings(listWrapperInfo);
            this.fields.push(listWrapperInfo);

            const detailsWrapperInfo = new FieldInfo();
            detailsWrapperInfo.Title = "Details view";
            detailsWrapperInfo.Ordinal = MAX_INTEGER;
            detailsWrapperInfo.Settings = this.getFieldSettings(detailsWrapperInfo);
            this.fields.push(detailsWrapperInfo);
        }
    }

    private onFieldNameChange(entry: string, field: FieldInfo) {
        let currentValue = this.value;
        if (!currentValue) {
            currentValue = [];
        }
        const existingField = currentValue.find(f => f.FieldName === field.Title);
        if (existingField) {
            existingField.CssClass = entry;
        } else {
            currentValue.push({FieldName: field.Title, CssClass: entry});
        }

        this.writeValue(currentValue);
    }

    private getFieldSettings(fieldInfo: FieldInfo): SettingsBase {
        const settings = new SettingsBase(fieldInfo.Title, false);
        settings.placeholder = "type CSS class...";

        return settings;
    }
}

export class FieldMappingsCssSettings extends FieldMappingsSettings {
    public cssFieldMappingsShowWrapperClasses: boolean;
}

export const LIST_FIELD_MAPPINGS_CSS_REGISTRY: FieldRegistration = {
    writeComponent: ListFieldMappingsCssComponent,
    readComponent: ListFieldMappingsCssComponent,
    settingsType: FieldMappingsCssSettings
};
