import { LoggerSource, Log, LogCategory } from "./logger-source";
import { Injectable, Inject } from "@angular/core";
import { WINDOW_TOKEN } from "../../../../window.provider";

@Injectable()
export class ConsoleLoggerSource extends LoggerSource {
    /**
     * Logs different type of logs to the console.
     * When the category is of type Error, the stacktrace
     * will also be logged.
     *
     * @param {Log[]} logs
     * @memberof ConsoleLoggerSource
     */

     constructor(@Inject(WINDOW_TOKEN) private windowProvider: typeof window) {
        super();
     }

     public process(logs: Log[]) {
        logs.forEach(log => {
            switch (log.category) {
                case LogCategory.Any:
                    // eslint-disable-next-line no-console
                    this.windowProvider.console.log(log.data.message);
                    break;
                case LogCategory.Error:
                    // eslint-disable-next-line no-console
                    this.windowProvider.console.error(`${log.data.message}\n${log.data.stackTrace}`);
                    break;
                case LogCategory.Warn:
                    // eslint-disable-next-line no-console
                    this.windowProvider.console.warn(log.data.message);
                    break;
            }
        });
    }
}
