import { ValidatorFn } from "@angular/forms";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { PropertyMetadata } from "../../../interfaces/widget-editor";

export class ComplexSettings extends SettingsBase {
    public typeChildProperties: PropertyMetadata[];
    public extraRecords: any[];
    public lengthDependsOnDisplayName: string;
    public lengthDependsOnDisplayTitle: string;
    public dependsOnLength: number;
    public itemDefaultValue: string;
    public tableViewColumnTitle: string;
    public tableViewEnabled: boolean;
    public tableViewReorderable: boolean;
    public tableViewSelectable: boolean;
    public tableViewMultipleSelect: boolean;
    public tableViewPredefinedLists: string;
    public tableViewAllowEmptyState: string;
    public hideExpander: boolean = false;
    // This setting is used for the yes-no field only.
    // It should be used when the title of the field and the option name are different.
    public optionName: string = null;
    public isMultiple: boolean;
    public predefinedLists: { [key: string]: string[] };
    public hideRowsIfEmpty: boolean = false;
    public moduleName: string;
    public warningText: string;

    public init(metadata: any) {
        super.init(metadata);
        this.typeChildProperties = metadata["typeChildProperties"] || [];
        let records = [];
        try {
            records = metadata["dependsOnExtraRecords"] ? JSON.parse(metadata["dependsOnExtraRecords"]) : [];
        } catch (e) {}
        this.extraRecords = records;
        this.itemDefaultValue = metadata["itemDefaultValue"];
        this.culture = metadata["culture"];
        this.markAsDirty = true;
        this.useDefaultValue = true;
        this.hideExpander = metadata["hideExpander"];
        const isCollection = this.type === "enumerable"  || this.type === "dictionary";
        this.isMultiple = isCollection || (this.extraRecords && this.extraRecords.length > 0) || this.dependsOnLength > 0;
        try {
            this.predefinedLists = this.tableViewPredefinedLists ? JSON.parse(this.tableViewPredefinedLists) : null;
        } catch (e) {}
    }

    // complex fields are just a placeholder for their children fields and the validation depends on their child fields
    // whether that would be required or something else
    public getValidators(metadata: any): Array<ValidatorFn> {
        return [];
    }
}
