import { Injectable } from "@angular/core";
import { CanActivate, RouterStateSnapshot, ActivatedRouteSnapshot, Router } from "@angular/router";
import { Observable, of } from "rxjs";
import { ProviderStore } from "./modules/content/dynamic-modules/services/provider-store";
import { stringConstants } from "./common-constants";
import { DynamicItemStrategyBase } from "./modules/content/dynamic-modules/components/strategies/dynamic-item.strategy";
import { map } from "rxjs/operators";
import { ROUTE_PATHS } from "./constants/route-paths";

@Injectable()
export class ProviderRouteGuard implements CanActivate {
    constructor(private readonly router: Router,
                private readonly store: ProviderStore) {}

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean | Observable<boolean> | Promise<boolean> {
        const currentRouteSegments = this.getSegments(this.router.url);
        const nextRouteSegments = this.getSegments(state.url);

        if (this.shouldResetProvider(currentRouteSegments, nextRouteSegments)) {
            const currentSet = DynamicItemStrategyBase.getSet(route);

            return this.store.getProviders(currentSet).pipe(map(providers => {
                const provider = providers.find(x => x.isDefault);
                if (!provider) {
                    this.router.navigate([ROUTE_PATHS.ACCESS_DENIED]);
                    return false;
                }

                const providerName = provider.name;
                this.store.currentProvider = providerName;

                return true;
            }));
        }

        return of(true);
    }

    private shouldResetProvider(currentUrlSegments: string[], nextUrlSegments: string[]) {
        if (currentUrlSegments.length === 0 || nextUrlSegments.length === 0) {
            return true;
        }

        // Example: /pages and /content
        if (currentUrlSegments[0] !== nextUrlSegments[0]) {
            return true;
        }

        // Example: /content/news and /content/blogs
        if (currentUrlSegments[1] !== nextUrlSegments[1]) {
            return true;
        }

        // Example: /content/parent/parentId/child1 and /content/parent/parentId/child2
        if (this.hasDifferentChildTypes(currentUrlSegments, nextUrlSegments)) {
            return true;
        }

        return false;
    }

    private hasDifferentChildTypes(currentUrlSegments: string[], nextUrlSegments: string[]) {
        let hasSameSegments = true;
        for (let i = 0; i < 3; i++) {
            if (currentUrlSegments[i] !== nextUrlSegments[i]) {
                hasSameSegments = false;
                break;
            }
        }

        const differInChildTypes = currentUrlSegments[3] !== nextUrlSegments[3];
        if (hasSameSegments && differInChildTypes) {
            return true;
        }

        return false;
    }

    private getSegments(url: string) {
        const queryStringStart = url.indexOf(stringConstants.QUESTION_MARK);
        let urlToSplit = url;

        if (queryStringStart > -1) {
            urlToSplit = url.substring(0, queryStringStart);
        }

        const segments = urlToSplit.split(stringConstants.FORWARD_SLASH).filter(x => x.length > 0);
        return segments;
    }
}
