import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../../fields/field-base";
import { FileInfo, FileInfoService } from "../../shared/services/metadata/files/file-info.service";
import { FilePreviewEditSettings } from "./file-preview-edit-settings";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { from, combineLatest } from "rxjs";
import { ViewModel } from "../file-preview.component";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { MediaValidationHelper } from "../media-validation-helper";
import { MediaSettings } from "../media/media.settings";
import { MediaEntity, MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { ActivatedRoute } from "@angular/router";
import { QUERY_PARAMS } from "../../content/constants";
import { HttpODataRequestWrapper } from "../../shared/services/http-odata-request.wrapper";
import { FileWrapper } from "../media-handlers/media-handler.provider";
import { ENTITY_SET, MEDIA_DATA_FIELD_NAME } from "../../shared/services/metadata/meta-data-constants";
import { Properties } from "../../shared/fields.constants";
import { MediaService } from "../services/media.service";
import { createFileWithBase64 } from "../../../utils";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { StatusType } from "../../../../../fields/field-status";

@Component({
    selector: "sf-file-preview-edit",
    templateUrl: "./file-preview-edit.component.html"
})
export class FilePreviewEditComponent extends FieldBase<FilePreviewEditSettings> implements OnInit {
    viewModel: ViewModel;
    fileUploadErrorMessages: string[];
    cssClass: string = "sf-media -preview -fade-in-effect";

    constructor(private fileInfoService: FileInfoService,
                private service: DynamicItemService,
                private mediaValidationHelper: MediaValidationHelper,
                private http: HttpODataRequestWrapper,
                private route: ActivatedRoute,
                private metadataStore: MetadataStore,
                private mediaService: MediaService) {
        super();
    }

    ngOnInit() {
        const dataItemOriginal = this.settings.dataItem;
        if (!dataItemOriginal)
            return;

        if (dataItemOriginal.metadata.setName === ENTITY_SET.PRESETS) {
            this.cssClass += " -sf-border -sf-border-lighter";
        }

        if (dataItemOriginal.data?.[MEDIA_DATA_FIELD_NAME]) {
            const mediaItem = dataItemOriginal.data[MEDIA_DATA_FIELD_NAME];
            const mediaDataItem = DataItem.fromEntityData(mediaItem.data, {
                metadata: this.metadataStore.getEntity(ENTITY_SET.IMAGES),
                culture: null,
                provider: this.settings.provider
            });
            this.viewModel = this.createViewModel(mediaDataItem);

            // start image upload and emit pending status while uploading :(
            const emptyMediaItem = DataItem.emptyItem(mediaDataItem);
            const file = createFileWithBase64(this.viewModel.file.dataUrl as string, `test.png`);
            this.fileInfoService.createFileInfo$(file, this.metadataStore.getEntity(ENTITY_SET.IMAGES)).subscribe(fileInfo => {
                delete fileInfo.form;
                combineLatest(this.mediaService.upload(emptyMediaItem, null, [fileInfo], this.settings.targetLibraryId, null, true, OPERATION_NAMES.uploadPublished, false))
                .subscribe({
                    next: uploads => {
                        const upload = uploads[0];
                        if (upload.success) {
                            const image = upload.result;
                            this.writeValue(image.Id);
                            this.status$.next({ type: StatusType.Done });
                        } else if (upload.failure) {
                            this.fileUploadErrorMessages = [upload.errorMessage];
                            this.status$.next({ type: StatusType.Error });
                        } else {
                            this.status$.next({ type: StatusType.Pending });
                        }
                    }
                });
            });
        } else if (!dataItemOriginal.title) {
            this.service.getItem({
                itemKey: dataItemOriginal.key,
                fallbackProperties: [dataItemOriginal.metadata.defaultFieldName],
                dataFieldNames: [dataItemOriginal.metadata.defaultFieldName],
                entityData: dataItemOriginal
            }).subscribe((dataItem) => {
                const mergedData = JSON.parse(JSON.stringify(dataItemOriginal.data));
                mergedData[dataItemOriginal.metadata.defaultFieldName] = dataItem.title;
                const dataItemCopy = DataItem.fromEntityData(mergedData, dataItemOriginal);
                this.viewModel = this.createViewModel(dataItemCopy);
            });
        } else {
            if (dataItemOriginal.metadata.setName === ENTITY_SET.PRESETS) {
                const mediaDataItem = DataItem.fromEntityData({...dataItemOriginal.data, "MimeType": "image/png"}, {
                    metadata: this.metadataStore.getEntity(ENTITY_SET.IMAGES),
                    culture: null,
                    provider: this.settings.provider
                });

                this.viewModel = this.createViewModel(mediaDataItem);
            } else {
                this.viewModel = this.createViewModel(dataItemOriginal);
            }
        }

        // check whether we should copy image
        const snapshot = this.route.snapshot;
        const queryParams = snapshot.queryParamMap;
        if (queryParams.keys.indexOf(QUERY_PARAMS.VERSION) > -1) {
            // this will get the image content
            const params = {
                [QUERY_PARAMS.VERSION]: queryParams.get(QUERY_PARAMS.VERSION),
                [QUERY_PARAMS.PROVIDER]: this.viewModel.mediaDataItem.provider
            };

            this.http.get(`${dataItemOriginal.metadata.setName}(${dataItemOriginal.key})/$value`, { responseType: "blob", params })
                .then(data => {
                const file =  new File([data], `${this.viewModel.file.title}${this.viewModel.file.extension}`, { type: data.type });
                this.onSelectedForUpload({files: [file] as any});
            });
        }
    }

    public hasEmptyValue() {
        return false;
    }

    protected onSelectedForUpload(data: FileListOptions) {
        const firstFile = data.files[0];
        if (!firstFile || !this.validateFile(firstFile)) {
            return;
        }

        const blob = firstFile.slice(0, firstFile.size, firstFile.type);
        const asset = firstFile instanceof FileWrapper ? firstFile.asset : null;
        const newFile = new FileWrapper([blob], firstFile.name, { type: firstFile.type, lastModified: firstFile.lastModified }, asset, data.preserveFileName);
        this.writeValue(newFile);

        const name = data.originalFileNames && data.originalFileNames.length > 0 ? data.originalFileNames[0] : firstFile.name;
        const fileViewInfo = new File([blob], name, { type: firstFile.type });
        const fileInfo$ = from(this.fileInfoService.createFileInfo(fileViewInfo, this.viewModel.mediaDataItem.metadata));
        fileInfo$.subscribe((fileInfo) => {
            const dataItem = (this.settings as FilePreviewEditSettings).dataItem;
            this.viewModel = this.createViewModel(dataItem, fileInfo);
        });
    }

    protected validateFile(file) {
        const isValid = this.mediaValidationHelper.validate(this.viewModel.mediaDataItem.metadata as MediaEntity, [file], false);
        this.fileUploadErrorMessages = this.mediaValidationHelper.getErrorMessages();

        return isValid;
    }

    private getUrl(dataItem: DataItem) {
        const url = dataItem.data[Properties.URL];

        if (url) {
            return url;
        }

        return dataItem.data[Properties.THUMBNAIL];
    }

    // TODO: refactor this mess - pass only dataItem
    private createViewModel(dataItem: DataItem, fileInfo: FileInfo = <any>{}): ViewModel {
        let mediaDataItem = DataItem.fromEntityData(dataItem.data, dataItem);
        mediaDataItem = this.mapMediaEntityDataProps(mediaDataItem);

        const dataUrl = this.getUrl(dataItem);

        return {
            mediaDataItem,
            file: {
                dataUrl: fileInfo.dataUrl || dataUrl,
                contentType: fileInfo.contentType || dataItem.data.MimeType,
                extension: fileInfo.extension || dataItem.data.Extension,
                width: fileInfo.width || dataItem.data.Width,
                height: fileInfo.height || dataItem.data.Height,
                size: fileInfo.size || dataItem.data.TotalSize,
                content: null,
                data: null,
                isCorrupted: false,
                form: null,
                isMultimedia: mediaDataItem.metadata.isMultimedia,
                name: fileInfo.name || dataItem.data.MediaFileUrlName || dataItem.title,
                title: fileInfo.title || dataItem.data.MediaFileUrlName || dataItem.title
            }
        };
    }

    private mapMediaEntityDataProps(mediaDataItem: DataItem): DataItem {
        const castSettings = this.settings as unknown as MediaSettings;
        if (castSettings && Array.isArray(castSettings.acceptableFileTypes) && Array.isArray(castSettings.acceptableMediaTypes) && castSettings.maxSize != null) {
            (mediaDataItem.metadata as MediaEntity).acceptableFileTypes = castSettings.acceptableFileTypes.map(x => x.replace(".", ""));
            (mediaDataItem.metadata as MediaEntity).acceptableMediaTypes = castSettings.acceptableMediaTypes;
            (mediaDataItem.metadata as MediaEntity).maxSize = castSettings.maxSize;
            // in case we have documents with size costrains AND allowed extensions
            // otherwise we want to keep the logic in the validator not to match file extensions by *
            if ((mediaDataItem.metadata as MediaEntity).originalAcceptableTypes.indexOf("*") < 0 && !(mediaDataItem.metadata as MediaEntity).mediaFilterEnabled) {
                (mediaDataItem.metadata as MediaEntity).mediaFilterEnabled = true;
            }
        }

        return mediaDataItem;
    }
}

interface FileListOptions {
    files: FileList;
    preserveFileName?: boolean;
    originalFileNames?: string[];
}
