import { ReplaySubject } from "rxjs";
import { Component, Input, OnInit, ViewChild, ElementRef, HostListener } from "@angular/core";
import { FileLayoutBaseComponent } from "./file-layout-base.component";
import { LayoutService } from "./services/layout.service";
import { MESSAGES } from "./file-picker.messages";
import { getFormattedTypeName } from "../../utils";
import { ChipsConfig } from "../../../../fields/common/chips/chips.component";
import { ModalWindowService } from "../shared/services/modal-window.service";
import { FILE_UPLOAD_PROGRESS, FILE_UPLOAD_RETRY_COMMAND } from "./file-picker.constants";
import { SHOW_BUTTONS, SHOW_CLOSE_BUTTON } from "../shared/components/modal-window/modal-window.component";
import { MediaHelpers } from "./services/media.helpers";

@Component({
    selector: "sf-file-upload-progress",
    templateUrl: "./file-upload-progress.component.html"
})
export class FileUploadProgressComponent extends FileLayoutBaseComponent implements OnInit {
    @ViewChild("wrapper", { static: true }) wrapper: ElementRef;

    @Input() uploadingFiles: ReplaySubject<{ items: any[], updatedItem?: any, uploadFieldState: { uploadedItemsCount: number } }>;
    files = [];
    fileUploads = [];
    multiple = true;
    formattedTypeName;
    messages;
    selectedLibraries = [];
    chipsConfig: ChipsConfig = {
        showRecentLabel: false,
        showSelectedItemAsActive: true,
        focusFirstNode: false,
        showNoResultsLabel: true,
        hideEditButton: true
    };

    private isFirstRun: boolean = true;

    constructor(protected layoutService: LayoutService, private modalWindowService: ModalWindowService) {
        super(layoutService);
    }

    ngOnInit() {
        const subscription = this.uploadingFiles.subscribe(f => {
            const items = f.items;

            if ((this.files.length === 0 && items.length > 0) || (this.files.length !== items.length)) {
                this.files = items.map(fileUpload => {
                    fileUpload.contentType = `${this.mediaEntityData.metadata.singularName.toLocaleLowerCase()}/`;
                    return fileUpload;
                });

                this.fileUploads = items.map(fileUpload => fileUpload.upload);
            } else {
                items.forEach(item => {
                    const file = this.files.find(x => x.upload.id === item.upload.id);
                    if (file) {
                        file.upload = item.upload;
                    }
                });
            }

            let allFilesUploaded = true;
            // map only progress, and not reload other properties, so that the component loaders do not flash
            this.files.forEach((file, i) => {
                file.upload.loaded = items[i].upload.loaded;
                file.upload.failure = items[i].upload.failure;
                file.upload.total = items[i].upload.total;
                file.upload.success = items[i].upload.success;

                // reset to false if any of the items is still not finished
                if (!file.upload.success && !file.upload.failure) {
                    allFilesUploaded = false;
                }
            });

            if (allFilesUploaded) {
                this.modalWindowService.sendCommand(FILE_UPLOAD_PROGRESS, {name: SHOW_BUTTONS, data: true});
                this.modalWindowService.sendCommand(FILE_UPLOAD_PROGRESS, {name: SHOW_CLOSE_BUTTON, data: true});
            }

            // should be done only at the start of the upload process, else it causes
            // each file preview component to reinitialize each time any progress is made in the upload
            if (this.isFirstRun) {
                this.isFirstRun = false;
                this.recalculateLayout(this.fileUploads, this.wrapper);
            }
        });

        this.registerSubscription(subscription);

        this.messages = this.multiple ? MESSAGES.multiple : MESSAGES.single;
        this.formattedTypeName = getFormattedTypeName({ plural: this.mediaEntityData.metadata.setName, singular: this.mediaEntityData.metadata.singularName }, this.multiple, true);
    }

    @HostListener("window:resize")
    onResize() {
        this.recalculateLayout(this.fileUploads, this.wrapper);
    }

    retryUpload(upload: any) {
        this.modalWindowService.sendCommand(FILE_UPLOAD_PROGRESS, {name: FILE_UPLOAD_RETRY_COMMAND, data: upload});
    }

    showProgressLabels(): boolean {
        return MediaHelpers.isImageEntity(this.mediaEntityData);
    }
}
