import { Component, Input, KeyValueDiffers, OnInit, DoCheck, Inject } from "@angular/core";
import { StatusLabel, StatusResolverBase } from "./../resolvers/base-status.resolver";
import { stringConstants } from "../../src/app/common-constants";
import { Properties } from "../../src/app/modules/shared/fields.constants";
import { ActivatedRoute } from "@angular/router";

const STATUS_ICON = "sf-status__icon";
const STATUS_TEXT = "sf-status__text";
const LOCKED_STATUS_NAME = "Locked";
const ICON_DISPLAY_TYPE = "icon";

@Component({
    selector: "sf-status",
    templateUrl: "./status.component.html"
})
export class StatusComponent implements OnInit, DoCheck {
    @Input() dataItem: any;
    @Input() look: string;
    @Input() displayType: string;
    @Input() showBreadcrumbInStatus: boolean;
    public statusName: string;
    public uiStatus: string;
    public breadcrumbInStatus: string;

    statusCssClassList: string;

    private differ: any;

    constructor(
        @Inject(StatusResolverBase) private statusResolvers: StatusResolverBase[],
        private route: ActivatedRoute,
        private differs: KeyValueDiffers) {
    }

    ngOnInit() {
        this.differ = this.differs.find({}).create();
        this.statusCssClassList = this.generateCssClassList();

        if (this.showBreadcrumbInStatus) {
            this.breadcrumbInStatus = this.dataItem.data[Properties.BREADCRUMB];
        }
    }

    ngDoCheck() {
        const changes = this.differ.diff(this.dataItem.data);
        if (!changes) {
            return;
        }

        let statusLabel: StatusLabel = { Label: null, StatusName: null };
        for (const statusResolver of this.statusResolvers) {

            // This if statment is such because of related data, since related data does not include the metadata of the item
            // TODO: Consider refactoring the related data component to include the metadata of the items
            const setName = this.dataItem.metadata ? this.dataItem.metadata.setName : this.dataItem.data.setName;
            if (statusResolver.canProcess(setName)) {
                statusLabel = statusResolver.getLabel(this.dataItem.data, setName, this.route.snapshot);
                break;
            }
        }

        if (!statusLabel) {
            this.displayType = null;
            return;
        }

        if (this.displayType === ICON_DISPLAY_TYPE && statusLabel.HideIcon) {
            this.displayType = null;
            return;
        }

        this.statusName = this.getStatusName(statusLabel);
        this.statusCssClassList = this.generateCssClassList();
        this.uiStatus = statusLabel.Label;
    }

    generateCssClassList(): string {
        const classList = [];

        if (this.displayType === ICON_DISPLAY_TYPE) {
            classList.push(STATUS_ICON);

            if (this.statusName) {
                classList.push(stringConstants.DASH + this.statusName.toLowerCase().split(stringConstants.INTERVAL).join(stringConstants.DASH));
            }
        } else {
            classList.push(STATUS_TEXT);
        }

        if (this.look) {
            const lookClasses = this.look.split(stringConstants.INTERVAL).map(cls => stringConstants.DASH + cls);
            classList.push(...lookClasses);
        }

        return classList.join(stringConstants.INTERVAL);
    }

    private getStatusName(statusLabel: StatusLabel): string {
        if (this.dataItem.data.LockedStatus) {
            return LOCKED_STATUS_NAME;
        } else {
            return statusLabel.StatusName;
        }
    }
}
