import { empty as observableEmpty } from "rxjs";
import { NEW_TAB_TARGET } from "./../../../../common-constants";
import { Observable } from "rxjs";
import { Inject, NgZone } from "@angular/core";
import { Command } from "../command";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ExecutionContext } from "../execution-context";
import { LinkCommandModel } from "./link-command-model";
export class OpenLinkCommand implements Command {
    constructor(
        @Inject(WINDOW_TOKEN) private window: Window,
        private zone: NgZone) {
    }

    execute(context: ExecutionContext): Observable<any> {
        const model = <LinkCommandModel>context.model;
        const target = context.data.target || NEW_TAB_TARGET;

        let link: string;
        if (model && model.link) {
            link = model.link;
        } else {
            link = context.data.link;
        }

        this.zone.runOutsideAngular(() => {
            const window = this.window.open(link, target);

            if (context.data.dataForLocalStorage) {
                // This data is later read in the TranslationDialog.js, in the initializeInFullScreenMode() method
                window.localStorage.setItem(context.data.dataForLocalStorage.key, context.data.dataForLocalStorage.value);
            }
        });

        return observableEmpty();
    }
}
