import { DataItem } from "../../../interfaces";
import { ROUTE_PARAMS, QUERY_PARAMS, FILTER_PARAMS } from "../../../../constants";
import { ActivatedRoute } from "@angular/router";
import { stringConstants } from "../../../../../../common-constants";

export function getItemUrl(dataItem: DataItem, parentId: string, duplicate: boolean = false, unlock: boolean = false): string {
    const metadata = dataItem.metadata;
    const isHierarchical = dataItem.metadata.hasParent && parentId;

    let navigateUrl: string = null;

    const editSegment = unlock ? ROUTE_PARAMS.UNLOCK_SEGMENT : ROUTE_PARAMS.EDIT_SEGMENT;

    if (isHierarchical) {
        if (dataItem.isEmpty) {
            navigateUrl = `${metadata.parent}/${parentId}/${metadata.setName}/${ROUTE_PARAMS.CREATE_SEGMENT}`;
        } else if (duplicate) {
            navigateUrl = `${metadata.parent}/${parentId}/${metadata.setName}/${dataItem.key}/${ROUTE_PARAMS.DUPLICATE_SEGMENT}`;
        } else {
            navigateUrl = `${metadata.parent}/${parentId}/${metadata.setName}/${dataItem.key}/${editSegment}`;
        }
    } else if (dataItem.isEmpty) {
        navigateUrl = `${metadata.setName}/${ROUTE_PARAMS.CREATE_SEGMENT}`;
    } else if (duplicate) {
        navigateUrl = `${metadata.setName}/${dataItem.key}/${ROUTE_PARAMS.DUPLICATE_SEGMENT}`;
    } else {
        navigateUrl = `${metadata.setName}/${dataItem.key}/${editSegment}`;
    }

    return navigateUrl;
}

export function getQueryParams(entityData: DataItem, route: ActivatedRoute) {
    const queryParams = {};
    queryParams[QUERY_PARAMS.PROVIDER] = entityData.provider;
    queryParams[QUERY_PARAMS.CULTURE] = entityData.culture;

    const currentFilter = route.snapshot.queryParams[FILTER_PARAMS.FILTER];
    if (currentFilter) {
        queryParams[FILTER_PARAMS.FILTER] = currentFilter;
    }

    const currentSortParameter = route.snapshot.queryParams[QUERY_PARAMS.SORT];
    if (currentSortParameter) {
        queryParams[QUERY_PARAMS.SORT] = currentSortParameter;
    }

    return queryParams;
}

export function buildQueryString(queryParams: { [key: string]: string }) {
    const keys = Object.keys(queryParams);
    if (keys.length > 0) {
        let url = stringConstants.QUESTION_MARK;
        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            const queryParamValue = queryParams[key];
            if (queryParamValue)
                url = `${url}${key}=${queryParamValue}${stringConstants.AMPERSAND}`;
        }

        if (url.endsWith(stringConstants.AMPERSAND))
            url = url.substr(0, url.length - 1);

        return url;
    }

    return stringConstants.EMPTY_STRING;
}
