import { Component, ViewChildren, QueryList, AfterViewInit, OnInit } from "@angular/core";
import { FormFieldWrapperComponent } from "../../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { CanCloseModal, ClosingContext } from "../../services/modal-window.service";
import { stringConstants } from "../../../../common-constants";
import { FieldModel } from "../../../../services/field.model";
import { MEDIA_CONTENT_TYPES } from "../../../libraries/media-content.types";
import { ReplaySubject } from "rxjs";
import { FormGroup } from "@angular/forms";
import { MediaSettings } from "../../../libraries/media/media.settings";
import { MEDIA_TYPES } from "../../services/metadata/meta-data-constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";

// TODO refactor to use list Story in TP#249812
@Component({
    selector: "sf-bulk-edit-properties",
    templateUrl: "./bulk.component.html"
})
export class BulkComponent extends SfRxBase implements OnInit, CanCloseModal, AfterViewInit {
    items: any[];
    wrapperComponents: FormFieldWrapperComponent[];
    parentComponent: any;
    type: string;
    title: string;
    onFieldChange: ReplaySubject<any> = new ReplaySubject<any>(1);
    wrapperClass: string = "-medium";
    bulkWrapperMap: Map<string, string> = new Map<string, string>([
        [MEDIA_CONTENT_TYPES.document.single, "-normal"],
        [MEDIA_CONTENT_TYPES.video.single, "-normal"]
    ]);

    @ViewChildren(FormFieldWrapperComponent) private formwrapperComponentsQuery: QueryList<FormFieldWrapperComponent>;

    ngOnInit() {
        this.title = `Bulk edit of ${this.type} properties`;
        const wrapperClass = this.bulkWrapperMap.get(this.type);

        if (wrapperClass) {
            this.wrapperClass = wrapperClass;
        }
    }

    canCloseCallback(context: ClosingContext):  boolean {
        let isValid = true;
        let firstInvalidField: FormFieldWrapperComponent = null;
        if (context.data && context.data.data) {
            this.wrapperComponents.forEach(x => {
                const isFieldValid = !x.hasErrors();
                if (isValid) {
                    isValid = isFieldValid;
                }

                if (!firstInvalidField && !isFieldValid) {
                    firstInvalidField = x;
                }
            });
        }

        if (firstInvalidField) {
            firstInvalidField.scrollToField();
        }

        return isValid;
    }

    ngAfterViewInit() {
        this.wrapperComponents = this.formwrapperComponentsQuery.toArray();
        const wrapperSubscriptions = this.formwrapperComponentsQuery.changes.subscribe((values: QueryList<FormFieldWrapperComponent>) => {
            this.wrapperComponents = values.toArray();
        });
        this.registerSubscription(wrapperSubscriptions);

        this.items.forEach(item => {
            if (item.form) {
                const itemForm: FormGroup = item.form;
                const formSubscription = itemForm.valueChanges.subscribe(() => {
                    this.onFieldChange.next(item);
                });
                this.registerSubscription(formSubscription);
            }
        });
    }

    generateCssClass(field: FieldModel): string {
        const classList: Array<string> = [];
        const typesWithClassModifiers: Array<string> = [MEDIA_CONTENT_TYPES.document.single, MEDIA_CONTENT_TYPES.video.single];
        classList.push(stringConstants.DASH + field.selector);

        if (typesWithClassModifiers.indexOf(field.key) > -1) {
            classList.push(stringConstants.DASH + field.key);
        }

        if (field.cssClass) {
            classList.push(field.cssClass);
        }

        if (this.isColumnWide(field)) {
            classList.push("-wide");
        }
        return classList.join(stringConstants.INTERVAL);
    }

    isColumnWide(field: FieldModel): boolean {
        if (field.settings && field.settings.type) {
            if (field.settings.type === MEDIA_TYPES.VIDEO) {
                return true;
            } else if (field.settings.type === MEDIA_TYPES.IMAGE) {
                const settings = field.settings as MediaSettings;
                if (!settings.allowMultiple)
                    return true;
            }
        }
        return false;
    }
}
