import { InjectionToken } from "@angular/core";
import { Entity } from "./metadata/meta-data.store";

export const QUERY_PARAMS_EXTENDER_TOKEN = new InjectionToken("query-params-extender");

export abstract class QueryParamsExtender {
    abstract getAdditionalQueryParams(entity: Entity, data: any): { [key: string]: string };
}

export function getAdditionalQueryParams(entity: Entity, additionalQueryParams: { [key: string]: string }, queryParamsExtenders: QueryParamsExtender[], data: any = null) {
    const result = Object.assign({}, additionalQueryParams);
    if (queryParamsExtenders) {
        for (const extender of queryParamsExtenders) {
            const queryParamsToAdd = extender.getAdditionalQueryParams(entity, data);
            for (const key in queryParamsToAdd) {
                if (queryParamsToAdd.hasOwnProperty(key) && !result[key]) {
                    result[key] = queryParamsToAdd[key];
                }
            }
        }
    }

    return result;
}
