import { Component, Inject, ViewEncapsulation } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { toggleIrisIntegratedStyles } from "../../../../utils";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { PropertyEditorCustomEvents } from "../../../widget-editor/property-editor.constants";
import { WidgetPropertyEditorService } from "../../../widget-editor/services/widget-property-editor.service";

@Component({
    selector: "sf-edit-page-template-component",
    template: "",
    styleUrls: ["./edit-page.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class EditPageTemplateComponent {

    constructor(
        route: ActivatedRoute,
        widgetPropertyEditorService: WidgetPropertyEditorService,
        @Inject(WINDOW_TOKEN) private window: Window) {
            widgetPropertyEditorService.initialize(route.parent);
            this.attachEventListeners();
    }

    private attachEventListeners() {
        this.window.document.addEventListener(PropertyEditorCustomEvents.NEED_MODAL_DIALOG,
            (e: any) => {
                const args = e.detail;
                if (!args.openNewEditor) {
                    return;
                }

                e.preventDefault();

                toggleIrisIntegratedStyles(true);
                this.window.document.body.classList.add("sfAdminAppControl");
            });

        this.window.document.addEventListener(PropertyEditorCustomEvents.MODAL_DIALOG_CLOSED,
            () => {
                toggleIrisIntegratedStyles(false);
                this.window.document.body.classList.remove("sfAdminAppControl");
            });
    }
}
