import { SelectorItem } from "../selector-item";
import { Item } from "../../../../../../../../../../fields/types/types";
import { DataItem } from "../../../../../../../content/dynamic-modules/interfaces";
import { DEFAULT_DATA_FIELDS } from "../../../../../../../../../../fields";
import { MODULE_NAME } from "../../../../../../../shared/services/metadata/meta-data.store";
import { MEDIA_TYPES_MODULE_NAME } from "../../../../../../../content/modules.provider";

/**
 * id and name props are required by the sf-tree-wrapper component
 */
export class ContentSelectorItem extends SelectorItem implements Item {
    Id: string;
    name: string;
    dataItem: DataItem;
    DisplayStatus: any;
    isTranslated: boolean;
    LockedStatus: any;
    hasChildren: boolean;
    icon: string;
    iconLook: string;
    isSelectionDisabled: boolean;
    breadcrumb?: string[];

    static fromDataItem(item: DataItem): ContentSelectorItem {
        let icon = null;
        let iconLook = null;
        let isSelectionDisabled = false;
        if (item.data.HasChildren && item.metadata.properties[MODULE_NAME] === MEDIA_TYPES_MODULE_NAME) {
            icon = "folder-o";
            iconLook = "light size-xl";
            isSelectionDisabled = true;
        }

        return <ContentSelectorItem>{
            Id: item.key,
            name: item.title,
            Title: item.title,
            value: item.key,
            dataItem: item,
            DisplayStatus: item.data.DisplayStatus,
            isTranslated: item.isTranslated,
            LockedStatus: item.data.LockedStatus,
            hasChildren: item.data.HasChildren,
            icon,
            iconLook,
            isSelectionDisabled,
            [DEFAULT_DATA_FIELDS.BREADCRUMB]: item.data.Breadcrumb,
            [item.metadata.defaultFieldName]: item.data[item.metadata.defaultFieldName]
        };
    }
}

export class ContentSelectorItemsDataObject {
    dataItems: ContentSelectorItem[];
    totalCount: number;
}
