import { Component, OnInit } from "@angular/core";
import { AppStore } from "../../../../services/store/app-store";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../services/store/actions/actions.sidebar";
import { SIDEBAR_SELECTORS } from "../../../../services/store/selectors/selectors.sidebar";
import { SidebarData, SidebarConfig } from "./sidebar.common";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const DEFAULT_SIDEBAR_BUTTON_LOOK = "toggle";

@Component({
    selector: "sf-sidebar-buttons",
    templateUrl: "./sidebar-buttons.component.html"
})
export class SidebarButtonsComponent extends SfRxBase implements OnInit {
    sidebarData: SidebarData;
    activeIndex = -1;

    private isSidebarOpened: boolean;

    constructor(private store: AppStore) {
        super();
    }

    ngOnInit() {
        const sidebarData$ = this.store.pipe(SIDEBAR_SELECTORS.sidebarData).subscribe(data => {
            if (data) {
                this.sidebarData = data;
                this.sidebarData.buttons = this.sidebarData.buttons.map(button => {
                    button.look = DEFAULT_SIDEBAR_BUTTON_LOOK;
                    return button;
                });
            }

            if (!this.isSidebarOpened) {
                this.activeIndex = -1;
            }
        });

        const isOpen$ = this.store.pipe(SIDEBAR_SELECTORS.isOpen).subscribe(isOpen => {
            if (!isOpen) {
                this.activeIndex = -1;
            }

            this.isSidebarOpened = isOpen;
        });

        const activeConfig$ = this.store.pipe(SIDEBAR_SELECTORS.activeConfig).subscribe(activeConfig => {
            if (activeConfig && activeConfig.name && this.sidebarData) {
                this.activeIndex = this.sidebarData.buttons.findIndex(button => {
                    return button.name === activeConfig.name || (button.name.includes("filter") && activeConfig.name.includes("filter"));
                });
            }
        });

        this.registerSubscription(sidebarData$);
        this.registerSubscription(isOpen$);
        this.registerSubscription(activeConfig$);
    }

    onButtonClickHandler(newConfig: SidebarConfig, index: number) {
        if (this.activeIndex === -1 || this.activeIndex !== index) {
            let shouldAnimate = true;
            if (this.isSidebarOpened) {
                shouldAnimate = false;
            }

            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.changeAndOpen(newConfig, shouldAnimate));

            this.activeIndex = index;
        } else {
            this.activeIndex = -1;
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.close());
        }
    }
}
