import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { SHORT_TEXT_PLACEHOLDER } from "../../../../../../../fields/short-text/short-text.constants";
import { LinkInsertFieldValidator } from "./link-insert-field-validator";

export class LinkToFieldSettings extends SettingsBase {
    public placeholder: string;

    public init(metadata: any): void {
        super.init(metadata);
        this.translatable = false;
        this.placeholder = metadata[SHORT_TEXT_PLACEHOLDER];
    }

    public getValidators(metadata: any) {
        const baseValidators = super.getValidators(metadata);
        baseValidators.push(LinkInsertFieldValidator.getValidator());
        return baseValidators;
    }
}
