import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { AuthService } from "./auth.service";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";

/**
 * An Angular route guard that protects routes only accessible for authenticated users.
 * If the user is not authenticated he would be redirected to the login page.
 *
 * @ExposedInApi {AuthGuard} AuthGuard v1/guards/auth.guard.d.ts
 */
@Injectable()
export class AuthGuard implements CanActivate {
    constructor(private service: AuthService) {

    }

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean | Observable<boolean> {
        return this.service.tryLogIn(state.url);
    }
}
