import { Component, Input, Output, EventEmitter, AfterViewInit, ElementRef, Inject } from "@angular/core";
import { trigger, state, style, transition, animate } from "@angular/animations";
import { FieldSectionModel } from "../../../../../services/fieldSection.model";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { ScrollService } from "../../../../../services/scroll.service";
import { ContentSectionMenuService, FieldViewPortChanges } from "../../../../../../../fields/services/content-section-menu.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-field-section",
    templateUrl: "./field-section.component.html",
    animations: [
         trigger("slideOpen", [
             state("open", style({height: "*", overflow: "visible"})),
             state("closed", style({height: 0, overflow: "hidden"})),

             transition("closed <=> open", [
                 animate("500ms ease")
             ])
         ])
     ]
})

export class FieldSectionComponent extends SfRxBase implements AfterViewInit {
    @Input() section: FieldSectionModel;
    @Output() sectionToggle = new EventEmitter<ToggleSectionState>();

    public get insertHorizontalRule(): boolean {
        return this.section.settings && this.section.settings.insertHorizontalRule;
    }

    private isInViewPort: boolean = false;
    constructor(
        private elementRef: ElementRef,
        @Inject(WINDOW_TOKEN) private window: Window,
        private scrollService: ScrollService,
        private componenentSectionMenuService: ContentSectionMenuService) {
            super();
            const subscription = this.componenentSectionMenuService.requestBringIntoView$.subscribe((i) => {
                this.requestedBringIntoView(i);
            });
            this.registerSubscription(subscription);

            const scrollSubscription = this.componenentSectionMenuService.requestFieldSectionPositionCalculation$.subscribe(() => {
                this.checkAndUpdateIsInViewPort(true);
            });
            this.registerSubscription(scrollSubscription);
    }

    toggleExpand () {
        this.section.settings.isExpanded = !this.section.settings.isExpanded;
        this.toggleSection();
    }

    bringIntoView() {
        if (this.section.settings.isExpanded) {
            this.scrollService.scrollTo(this.elementRef, true);
        } else {
            this.section.settings.isExpanded = true;
            setTimeout(() => {
                this.scrollService.scrollTo(this.elementRef, true, 500);
            }, 200);
        }
    }

    ngAfterViewInit(): void {
        this.checkAndUpdateIsInViewPort(false);
    }

    protected toggleSection() {
        const sectionState: ToggleSectionState = {
            sectionName: this.section.settings.name,
            isExpanded: this.section.settings.isExpanded
        };

        this.sectionToggle.emit(sectionState);
    }

    private requestedBringIntoView(model: any) {
        if (this.section.equals(model)) {
            this.bringIntoView();
        }
    }

    private checkAndUpdateIsInViewPort(shoudldUseChildForMeasure: boolean) {
        const isCurrentlyInViewPort = this.isInViewport(this.elementRef.nativeElement, shoudldUseChildForMeasure);
        if (this.isInViewPort !== isCurrentlyInViewPort) {
            this.isInViewPort = isCurrentlyInViewPort;
            const args: FieldViewPortChanges = {
                model : this.section,
                isInViewPort : isCurrentlyInViewPort
            };
            this.componenentSectionMenuService.fieldViewPortChanges(args);
        }
    }

    private isInViewport(element, shoudldUseChildForMeasure?: boolean): boolean {
        // using the TOP_OFFSET of the scroll service we need to calculate which
        // item is placed between the calculatedOffset by the ScrollService and the middle of the window
        let topOffset = this.scrollService.calculateOffset();
        let bottomOffset = this.window.innerHeight - 100; // / 2;
        topOffset += this.window.scrollY;
        bottomOffset += this.window.scrollY;
        if (shoudldUseChildForMeasure && element.children.length > 0) {
            element = element.children[0];
        }
        const elementTopOffset = element.offsetTop;
        const elementBottomOffset = element.offsetTop + element.offsetHeight;
        return (elementTopOffset > topOffset && elementTopOffset < bottomOffset )
                || (elementTopOffset < topOffset && elementBottomOffset > bottomOffset);
    }
}

export interface ToggleSectionState {
    sectionName: string;
    isExpanded: boolean;
}
