import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../../../fields/index";
import { ImageHelper } from "../../../html/tools/insert-image/image-helper";
import { createValueAccessor } from "../../../../../../fields/field-base";
import { MetadataContainer, MediaEntity, MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { first } from "rxjs/operators";
import { LibraryStore } from "../../services/library.store";
import { EntityData } from "../../../content/dynamic-modules/interfaces";

@Component({
    selector: "sf-thumbnail-selector",
    templateUrl: "./thumbnail-selector.component.html",
    providers: [createValueAccessor(ThumbnailSelectorComponent), ImageHelper]
})
export class ThumbnailSelectorComponent extends FieldBase implements OnInit {
    public dropDownSettings: any;
    public allThumbnails: any;

    private imageMediaEntityData: EntityData;
    private originalUrl;

    constructor(private metadataStore: MetadataStore, private imageHelper: ImageHelper, private store: LibraryStore) {
        super();
    }

    onSelectionChange(selectedValue: string) {
        if (selectedValue && this.allThumbnails) {
            const currentThumbnail = this.allThumbnails.find(t => t.Name === selectedValue);

            this.writeValue(currentThumbnail);
        }
        this.onBlur();
    }

    writeValue(value: any) {
        if (value && (!this.allThumbnails || !value.Url)) {
            this.initialize(value);
        }

        if (this.originalUrl && value && value.Url) {
            value.OriginalUrl = this.originalUrl;
        }

        super.writeValue(value);
    }

    private initialize(value) {
        this.metadataStore.initialize().pipe(first()).subscribe((metadata: MetadataContainer) => {
            const imageMediaEntity = metadata.entities[ENTITY_SET.IMAGES] as MediaEntity;
            this.imageMediaEntityData = {
                culture: this.settings.culture,
                provider: null,
                metadata: imageMediaEntity
            };

            this.originalUrl = value ? value.OriginalUrl || value : null;

            this.store.getThumbnails(this.imageMediaEntityData, this.originalUrl)
            .subscribe(data => {
                this.allThumbnails = data.value.filter(t => t.Name !== "original");
                const thumbnails = this.imageHelper.transformThumbnailsToChoices(this.allThumbnails);
                const filteredThumbnails = thumbnails.filter(t => t.Value !== "custom" && t.Value !== "original");
                if (filteredThumbnails && filteredThumbnails.length !== 0) {
                    const dropDownSettings = { choices: filteredThumbnails, key: this.settings.key, defaultValue: null, useDefaultValue: true };

                    if (value && value.Name) {
                        dropDownSettings.defaultValue = value.Name;
                        this.dropDownSettings = dropDownSettings;
                    } else {
                        this.dropDownSettings = dropDownSettings;
                        this.writeValue(this.allThumbnails[0]);
                    }
                } else {
                    this.dropDownSettings = null;
                }
            });
        });
    }
}
