import { Component, Input, Output, EventEmitter, OnInit } from "@angular/core";

@Component({
    selector: "sf-load-more",
    templateUrl: "./load-more.component.html"
})
export class LoadMoreComponent implements OnInit {
    @Input() loadCount: number;
    @Input() buttonText: string;
    @Input() currentItemsCount: number;
    @Input() allItemsCount: number;
    @Output() onLoadMore = new EventEmitter();

    public isLoadButtonVisible: boolean;

    ngOnInit() {
        this.isLoadButtonVisible = this.getLoadButtonVisibility();
    }

    loadMore() {
        this.isLoadButtonVisible = this.getLoadButtonVisibility(true);

        this.onLoadMore.emit();
    }

    getLoadButtonVisibility(isLoadButtonClicked: boolean = false): boolean {
        if (isLoadButtonClicked) {
            return !!this.loadCount && this.currentItemsCount + this.loadCount < this.allItemsCount;
        } else {
            return !!this.loadCount && this.currentItemsCount < this.allItemsCount;
        }
    }
}
