import { Component, Inject, OnInit, ViewChild } from "@angular/core";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { EMPTY_SCREEN_ICONS } from "../../content/dynamic-modules/dynamic-item.constants";
import { TreeNode } from "@circlon/angular-tree-component";
import { BehaviorSubject, ReplaySubject, Subject } from "rxjs";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { SAME_TAB_TARGET } from "../../../common-constants";
import { TreeConfig } from "../../../../../fields";
import { ModalListComponent } from "../components/modal-list/modal-list.component";
import { NotificationsService } from "./notifications.service";
import { NotificationsResolverBase } from "./resolvers/notifications-base-resolver";
import { ActivatedRoute } from "@angular/router";
import { SITE_SYNC_TOKEN } from "../components/site-sync/resolvers/site-sync-notification-resolver";

export const ACTION_READ_UNREAD: string = "Default.SetNotificationStatus";
const ACTION_COUNT: string = "Default.GetNotificationsCount(unreadOnly=false)";

@Component({
    selector: "sf-notifications",
    templateUrl: "./notifications.component.html"
})
export class NotificationsComponent extends SfRxBase implements OnInit {
    @ViewChild("modalList", { static: false }) modalList: ModalListComponent;

    readonly ACTION: string = "Default.GetNotifications()";
    readonly notificationsTitle: string = "Notifications";
    readonly showCounter: boolean = false;
    refresh: Subject<boolean>;

    notifications$: ReplaySubject<any> = new ReplaySubject<any>(1);
    count: BehaviorSubject<number>;

    emptyScreenIcon: string = EMPTY_SCREEN_ICONS["notifications"];
    emptyListMessage: string = "No new notifications";

    public treeConfig: TreeConfig = {
        status: false,
        description: true,
        noSelection: true,
        skipNodeMappingToDefaultModel: true
    };

    constructor(private dynamicItemService: DynamicItemService, @Inject(WINDOW_TOKEN) private window: Window, private notificationService: NotificationsService, @Inject(SITE_SYNC_TOKEN) private notificationsResolvers: NotificationsResolverBase[], private route: ActivatedRoute) {
        super();
    }

    ngOnInit(): void {
        this.dynamicItemService.executeUnboundFunction(ACTION_COUNT).subscribe((data: any) => {
            this.count = new BehaviorSubject<number>(data.value);
            this.notifications$.next([]);
        });

        const refreshSubscription = this.notificationService.onUpdate.subscribe(() => {
            this.modalList.reloadItems();
        });

        this.registerSubscription(refreshSubscription);
    }

    onTreeNodeClicked = (node: TreeNode) => {
        if (node.data.IsRead !== true) {
            this.dynamicItemService.executeUnboundFunction(`${ACTION_READ_UNREAD}(messageJobId=${node.data.MessageJobId}, isRead=true)`).subscribe(a => {
                this.executeNotificationResolver(node);

                if (node.data.SystemUrl) {
                    // Make sure the notification is marked as Read before navigating away
                    this.window.open(node.data.SystemUrl, SAME_TAB_TARGET);
                }
            });
        } else {
            this.executeNotificationResolver(node);

            if (node.data.SystemUrl) {
                this.window.open(node.data.SystemUrl, SAME_TAB_TARGET);
            }
        }
    }

    private executeNotificationResolver(node: TreeNode) {
        const notificationKey = node.data.NotificationKey;
        const notificationsResolver = this.notificationsResolvers.find(r => r.canProcess(notificationKey));

        if (notificationsResolver) {
            notificationsResolver.execute(node.data.AdditionalMessageData, this.route);
            return;
        }
    }
}
