import { of as observableOf, forkJoin as observableForkJoin, Observable } from "rxjs";

import { map, mergeMap } from "rxjs/operators";
import { SelectorContext } from "../../selector-context";
import { MetadataContainer, MediaEntity } from "../../../../../../../../shared/services/metadata/meta-data.store";
import { ContentSelectorStrategy, CHILD_LOAD_COUNT } from "./content-selector-strategy";
import { DataItem, TotalCountResult } from "../../../../../../../../content/dynamic-modules/interfaces";
import { DynamicItemService, LoadItemsData } from "../../../../../../../../content/dynamic-modules/services/dynamic-item.service";
import { ServiceInfo } from "../../../../../../../../../../../fields/selector/selector.component";
import { LoadingContentState, toLoadingState } from "../../../../../../../../shared/rxjs-extensions/toLoadingState";
import { MediaService } from "../../../../../../../../libraries/services/media.service";
import { cloneObject } from "../../../../../../../../../utils";
import { Properties } from "../../../../../../../../shared/fields.constants";
import { SortService } from "../../../../../../../../shared/services/sort.service";
import { QUERY_PARAMS } from "../../../../../../../../content/constants";

export class MediaContentSelectorStrategy implements ContentSelectorStrategy {
    constructor(
        private context: SelectorContext,
        private meta: MetadataContainer,
        private mediaService: MediaService,
        private dynamicItemsService: DynamicItemService,
        private mediaEntity: MediaEntity,
        private sortService: SortService
    ) {
    }

    getItems(info: ServiceInfo): Observable<LoadingContentState<TotalCountResult<DataItem[]>>> {
        let result: Observable<TotalCountResult<DataItem[]>>;
        if (info.searchText) {
            result = this.searchAllFiles(info);
        } else {
            if (!info.parentId) {
                result = this.loadRootLibraries(info);
            } else {
                result = this.loadLibraryChildren(info);
            }
        }

        return result.pipe(
            map(dataObject => {
                return <TotalCountResult<DataItem[]>>{ dataItems: dataObject.dataItems, totalCount: dataObject.totalCount };
            }),
            toLoadingState<TotalCountResult<DataItem[]>>());
    }

    getParent(item: DataItem): Observable<LoadingContentState<DataItem>> {
        return this.mediaService.getFolderById(item, item.data.Id, item.provider, this.context.selectedSite.value)
        .pipe(toLoadingState());
    }

    private loadRootLibraries(info: ServiceInfo): Observable<TotalCountResult<DataItem[]>> {
        const entitySet = this.mediaEntity.parent;
        const libRequestInfo = this.getServiceRequestInfo(entitySet);

        return this.mediaService.getLibraries(libRequestInfo, info.skip, info.take, this.context.selectedSite.value).pipe(
            map(librariesResponse => {
                const parsedAlbums = this.createDataItemsFromLibraries(librariesResponse.dataItems, entitySet);
                const dataObject = {
                    dataItems: parsedAlbums,
                    totalCount: librariesResponse.totalCount
                };

                return dataObject;
            }));
    }

    private loadLibraryChildren(info: ServiceInfo): Observable<TotalCountResult<DataItem[]>> {
        /**UX requirement first 100 children should be loaded until new better UX*/
        info.take = CHILD_LOAD_COUNT;
        const foldersRequest = this.getAllFolders(info, null);
        const filesRequest = this.getAllFiles(info, null);
        return observableForkJoin(foldersRequest, filesRequest).pipe(mergeMap(([foldersResponse, filesResponse]) => {
            let items: DataItem[] = [];
            const parsedFolders = foldersResponse.value;
            const parsedFiles = this.createDataItemsFromResponseItems(filesResponse.value, this.mediaEntity.setName);
            items.push(...parsedFolders, ...parsedFiles);
            items = items.slice(0, CHILD_LOAD_COUNT);
            const dataObject = {
                dataItems: items,
                totalCount: foldersResponse.totalCount + filesResponse.totalCount
            };

            return observableOf(dataObject);
        }));
    }

    private getAllFiles(info: ServiceInfo, response: FilesResponse): Observable<FilesResponse> {
        const requestInfo = this.getServiceRequestInfo(this.mediaEntity.setName);
        const queryParams = { [QUERY_PARAMS.SORT]: this.sortService.getDefaultSort(requestInfo)};

        return this.mediaService
            .getMediaForLibrary(requestInfo, info.parentId, info.skip, info.take, this.context.selectedSite.value, undefined, queryParams)
            .pipe(map(data => {
                const loadedAll = data.totalCount === data.dataItems.length;
                const shouldLoadMore = !loadedAll && (data.dataItems.length + info.skip) < CHILD_LOAD_COUNT;

                if (data.dataItems.length > 0 && shouldLoadMore) {
                    if (!response) {
                        response = { value: data.dataItems, totalCount: data.totalCount};
                    } else {
                        response.value = response.value.concat(...data.dataItems);
                    }

                    info.skip = response.value.length;

                    // by default ODATA have limit on the items that are returned per
                    // request so we need to make recursive calls to the service
                    this.getAllFiles(info, response);
                } else {
                    return response ? response : <FilesResponse>{ value: data.dataItems, totalCount: data.totalCount };
                }
            }));
    }

    private getAllFolders(info: ServiceInfo, response: FoldersResponse): Observable<FoldersResponse> {
        const entityData = this.mediaService.getParentEntityData({metadata: this.mediaEntity, culture: this.context.selectedCulture.value, provider: this.context.selectedProvider.value });
        const queryParams = { [QUERY_PARAMS.SORT]: this.sortService.getDefaultSort(entityData)};

        return this.mediaService.getFolders(entityData, info.parentId, false, false, info.skip, info.take, this.context.selectedSite.value, undefined, queryParams)
        .pipe(map(data => {
            data.dataItems.forEach((dataItem, index, dataitems) => {
                const data = cloneObject(dataItem.data);
                data[Properties.HAS_CHILDREN] = true;
                dataitems[index] = DataItem.fromEntityData(data, dataItem);
            });

            const loadedAll = data.totalCount === data.dataItems.length;
            const shouldLoadMore = !loadedAll && (data.dataItems.length + info.skip) < CHILD_LOAD_COUNT;

            if (data.dataItems.length > 0 && shouldLoadMore) {
                if (!response) {
                    response = {value: data.dataItems, totalCount: data.totalCount};
                } else {
                    response.value = response.value.concat(...data.dataItems);
                }

                info.skip = response.value.length;

                // by default ODATA have limit on the items that are returned per
                // request so we need to make recursive calls to the service
                this.getAllFolders(info, response);
            } else {
                return response ? response : <FoldersResponse>{value: data.dataItems, totalCount: data.totalCount};
            }
        }));
    }

    private searchAllFiles(info: ServiceInfo): Observable<TotalCountResult<DataItem[]>> {
        const entity = this.meta.entities[this.context.selectedEntitySet.value];
        const result = this.dynamicItemsService.getItemList(<LoadItemsData>{
            entityData: {
                metadata: entity,
                culture: this.context.selectedCulture.value,
                provider: this.context.selectedProvider.value
            },
            fallbackProperties: [entity.defaultFieldName],
            // siteId: this.context.selectedSite.value, // required for pages as they have the same provider for all sites, web services filter them based on the current site context
            skip: info.skip,
            take: info.take,
            filter: [{ key: entity.defaultFieldName, value: [info.searchText] }],
            siteId: this.context.selectedSite.value
        }).pipe(map(response => {return <TotalCountResult<DataItem[]>>{ dataItems: response.dataItems, totalCount: response.totalCount}; }));
        return result;
    }

    private createDataItemsFromLibraries(responseLibs: DataItem[], entitySet: string): DataItem[] {
        /** we should always mark libraries as having children, because the server does not return correct ChildrenCount
         *  - it considers only other libraries(folder) as children, not files */
        responseLibs = responseLibs.map(x => {
            const data = cloneObject(x.data);
            data.HasChildren = true;
            return DataItem.fromEntityData(data, x);
        });
        const items = this.createDataItemsFromResponseItems(responseLibs, entitySet);
        return items;
    }

    private createDataItemsFromResponseItems(responseFiles: DataItem[], entitySet: string): DataItem[] {
        const entity = this.meta.entities[entitySet];
        return responseFiles.map(file => {
            return DataItem.from(file.data, entity, this.context.selectedProvider.value, this.context.selectedCulture.value);
        });
    }

    private getServiceRequestInfo(entitySet: string): DataItem {
        const entity = this.meta.entities[entitySet];
        return DataItem.from(null, entity, this.context.selectedProvider.value, this.context.selectedCulture.value);
    }

}

class FoldersResponse {
    value: DataItem[];
    totalCount: number;
}

class FilesResponse {
    value: DataItem[];
    totalCount: number;
}
