import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../../../../fields/field-base";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { FieldRegistration } from "../../services/fields-registry";

@Component({
    selector: "sf-title-read-only",
    template: `
        <div>{{title}}</div>
        <span class="-sf-txt-dimmed -sf-txt-base">{{description}}</span>
    `
})

export class TitleReadComponent extends FieldBase implements OnInit {
    public title: string;
    public description: string;

    public ngOnInit() {
        const complexSettings = this.settings as TitleReadSettings;

        if (this.getValue() !== null) {
            if (this.getValue().hasOwnProperty(complexSettings.titleFieldName)) {
                this.title = this.getValue()[complexSettings.titleFieldName];
            }

            if (this.getValue().hasOwnProperty(complexSettings.descriptionFieldName)) {
                this.description = this.getValue()[complexSettings.descriptionFieldName];
            }
        }

        super.ngOnInit();
    }
}

export class TitleReadSettings extends SettingsBase {
    public titleFieldName: string;
    public descriptionFieldName: string;

    public init(metadata: any) {
        super.init(metadata);
        this.titleFieldName = metadata[TITLE_READ_COMPONENT_PROPERTIES.TitleField];
        this.descriptionFieldName =  metadata[TITLE_READ_COMPONENT_PROPERTIES.DescriptionField];
    }
}

export const TITLE_READ_COMPONENT_PROPERTIES = {
    TitleField : "Meta_TitleFieldName",
    DescriptionField : "Meta_DescriptionFieldName"
}

export const TITLE_READ_COMPONENT_REGISTRY: FieldRegistration = {
    writeComponent: TitleReadComponent,
    settingsType: TitleReadSettings
};
