import { ComponentData } from "@progress/sitefinity-component-framework";
import { CustomFilterRenderer } from "./custom-filter.renderer";
import { RENDERER_CATEGORIES } from "./renderer.constants";
import { FilterFlatTaxaFirstLetterComponent } from "../filter-flat-taxa-first-letter.component";
import { Filter } from "../filter-interfaces";
import { EntityData } from "../../../../interfaces";
import { Observable } from "rxjs";

export class FilterFlatTaxaFirstLetterRenderer extends CustomFilterRenderer {
    initComponentData(filters: Filter[], entityData: EntityData, reload: Observable<void>): ComponentData {
        const componentData: ComponentData = {
            type: FilterFlatTaxaFirstLetterComponent,
            properties: {
                filters: filters,
                entityData: entityData,
                reload: reload,
                category: this.getCategory()
            }
        };

        return componentData;
    }

    getCategory(): string {
        return RENDERER_CATEGORIES.FLAT_TAXA_FIRST_LETTER_FILTER;
    }
}
