export const BUTTONS_LOADING_TIME = 1000;
const DEFAULT_NOTIFICATION_LOOK = "sf-mt--2xl sf-mb-2xl";

@Component({
    templateUrl: "./dynamic-update-item.component.html",
    providers: [MirrorService, KeyboardShortcutsService, ActionButtonsResolver, ActionButtonsStateService],
    selector: "sf-dynamic-update-item"
})
// TODO: reuse this component in the dynamic item component
export class DynamicUpdateItemComponent extends SfRxBase implements OnInit, OnDestroy, AfterViewInit, CloseModalCallback, CanCloseModal {
    @ViewChild(EditableFieldsComponent, { static: true }) editableFields: EditableFieldsComponent;
    @Input() dataItem: DataItem;
    @Input() parentId: string;
    @Input() prepopulatedFields: any;
    @Input() mediaFieldLimitationsConstraints?: FieldWithLimitations;
    @Input() cultureData: ContentCultureData;

    headerClass: string;
    moduleNameIdentificator: string;
    readonly bottomActionMenuOptions: ActionMenuOptions;
    headerText: string;
    fieldSections: Array<FieldSectionModel>;
    formClasses: string = stringConstants.EMPTY_STRING;
    actionMenuClasses: string = stringConstants.EMPTY_STRING;
    hasMultipleContentCultures: boolean = false;
    allowDialogOpenCallback: () => Observable<boolean> = this.triggerLock.bind(this);
    buttonsState: ButtonsState;

    operations: BehaviorSubject<Array<Operation>> = new BehaviorSubject<Array<Operation>>([]);
    private callback: (data: any) => void;
    private itemMeta: ItemMeta;
    private formData: Array<FormData>;
    private isLocked: boolean = false;
    private viewName: string;

    private fallbackProperties: string[];

    constructor(
        private modalWindowService: ModalWindowService,
        private fieldsGeneratorService: FieldsGeneratorService,
        private backendTweaksService: BackendTweaksService,
        private service: DynamicItemService,
        private operationsProvider: CompositeOperationsProvider,
        private route: ActivatedRoute,
        private dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        public editExtender: CompositeEditExtender,
        private communicationService: ComponentCommunicationService,
        private keyboardShortcutsService: KeyboardShortcutsService,
        private scrollService: ScrollService,
        private parentService: ParentService,
        private itemHooksProvider: CompositeItemHooksProvider,
        private buttonStateService: ActionButtonsStateService) {
        super();
        this.bottomActionMenuOptions = new ActionMenuOptions(Number.NEGATIVE_INFINITY, OUTSIDE_MENU_MAX_ORDINAL);
    }

    ngOnInit() {
        this.itemHooksProvider.executeObservableHook<DataItem, EditItemLifecycleHookParam>(
            of(this.dataItem).pipe(first()),
            "onEditItemInitializing",
            x => ({ item: x })
        ).subscribe();

        const siteData = this.getSiteData();
        if (siteData && siteData.ContentCultures && siteData.ContentCultures.length > 1 && this.dataItem.metadata.isMultilingual) {
            this.hasMultipleContentCultures = true;
        }

        this.handleFormClasses();
        this.handleActionMenuClasses();
        this.handleKeyboardShortcuts();

        const communicationSubscription = this.communicationService.subscribe(WorkflowOperationClickedEvent, ev => {
            if (ev.data.itemType === this.dataItem.metadata.typeFullName) {
                this.onActionButtonClicked(ev.data.button);
            }
        });

        const changeDialogButtonsSubscription = this.communicationService.subscribe(ChangeButtonStateInItemEdit, ev => {
            this.buttonStateService.updateActionButtonsState(null, ev.data);
        });

        const buttonStateServiceSubscription = this.buttonStateService.getState$().subscribe(state => {
            this.buttonsState = state;
            this.communicationService.next(new ActionButtonsStateChanged(state));
        });

        this.registerSubscription(buttonStateServiceSubscription);
        this.registerSubscription(communicationSubscription);
        this.registerSubscription(changeDialogButtonsSubscription);

        this.route.snapshot.data[RESOLVE_NAMES.itemData] = { entityData: this.dataItem };
        this.viewName = VIEW_NAME.EDIT;

        if (this.dataItem.isEmpty) {
            this.viewName = VIEW_NAME.INSERT;
        }

        const segment = this.route.snapshot.paramMap.get("name") || stringConstants.EMPTY_STRING;
        if (segment.startsWith(ROUTE_PARAMS.DUPLICATE_SEGMENT)) {
            this.viewName = VIEW_NAME.DUPLICATE;
            this.editableFields.copyMode = true;
        }


        this.headerText = this.editExtender.getHeader(this.dataItem);
        this.buttonStateService.updateActionButtonsState(null, ButtonState.Loading);

        this.backendTweaksService.getFormTweaks(this.dataItem.metadata.setName, this.viewName, this.dataItem.key, this.dataItem.provider, this.dataItem.culture, this.parentId).then((data) => {
            this.formData = data;
            let itemKey = this.dataItem.key || stringConstants.DEFAULT_GUID;
            if (this.viewName === VIEW_NAME.DUPLICATE) {
                itemKey = stringConstants.DEFAULT_GUID;
            }

            this.registerSubscription(this.parentService.getParentItem(this.dataItem, this.parentId).subscribe(parentItem => {
                const operations = this.viewName === VIEW_NAME.EDIT ?
                    this.operationsProvider.getEditItemDialogOperations(this.dataItem, parentItem) :
                    this.operationsProvider.getCreateItemDialogOperations(this.dataItem, parentItem, { viewName: this.viewName });
                const itemMeta = this.service.executeBoundFunction<ItemMeta>(DataItem.fromKey(itemKey, this.dataItem), itemMetaSegment(null));
                forkJoin([
                    this.getItem(),
                    operations,
                    itemMeta]
                ).pipe(
                    mergeMap(res => {
                        this.dataItem = res[0];
                        this.itemMeta = res[2];
                        this.operations.next(res[1]);
                        let fieldValueItem = this.dataItem;

                        if (this.viewName === VIEW_NAME.DUPLICATE) {
                            const includedProperties = this.editExtender.includedProperties(this.dataItem);
                            const excludedProperties = this.editExtender.excludedProperties(this.dataItem);
                            fieldValueItem = DataItem.duplicate(this.dataItem, includedProperties, excludedProperties);
                        } else if (this.prepopulatedFields) {
                            fieldValueItem = DataItem.fromEntityData(this.prepopulatedFields, this.dataItem);
                        }

                        return this.initFields(fieldValueItem, this.itemMeta, this.formData);
                    })
                ).subscribe(() => {
                    this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
                });
            }));
        });

        this.setModuleNameIdentificator();
    }

    ngOnDestroy() {
        this.itemHooksProvider.executeObservableHook<DataItem, EditItemLifecycleHookParam>(
            of(this.dataItem).pipe(first()),
            "onEditItemUnloading",
            x => ({ item: x })
        ).subscribe(() => {
            super.ngOnDestroy();

            this.keyboardShortcutsService.removeListener(COMPONENT_NAMES.DYNAMIC_UPDATE_ITEM);
            this.notificationService.close(ITEM_EDIT_NOTIFICATION_FILTER_STATIC);
        });

        this.notificationService.close(MODAL_WINDOW_NOTIFICATION_FILTER);
    }

    ngAfterViewInit() {
        if (this.dataItem.isEmpty)
            return;

        const dirtyFieldsSubscription: Subscription = this.editableFields.dirty.subscribe((isDirty) => {
            if (isDirty) {
                this.triggerLock();
            }
        });

        this.registerSubscription(dirtyFieldsSubscription);

        this.itemHooksProvider.executeObservableHook<DataItem, EditItemLifecycleHookParam>(
            of(this.dataItem).pipe(first()),
            "afterEditItemInit",
            x => ({ item: x })
        ).subscribe();
    }

    setCloseModalCallback(doneCallback: (data: any) => void): void {
        this.callback = doneCallback;
    }

    canCloseCallback(context: ClosingContext): boolean | Observable<boolean> {
        if (context.type === ClosingContextType.CloseClicked && this.isLocked) {
            const ret$ = new Subject<boolean>();
            this.registerSubscription(this.service.unlockItem(this.dataItem).subscribe(() => {
                this.isLocked = false;
                ret$.next(true);
            }));

            return ret$;
        }

        return true;
    }

    onActionButtonClicked(button: ActionButton): void {
        this.initAction(button, button.name !== OPERATION_NAMES.cancel && button.name !== OPERATION_NAMES.unlock).subscribe(shouldAct => {
            if (shouldAct) {
                if (button.name === OPERATION_NAMES.cancel) {
                    this.onCancelClick();
                } else if (button.name === OPERATION_NAMES.unlock) {
                    this.onUnlockClick();
                } else {
                    this.onSubmitClick(button);
                }
            }
        });
    }

    onFieldChange(data) {
               this.registerSubscription(this.editExtender.modify({ sections: this.fieldSections,
                                    dataItem: DataItem.fromEntityData(this.editableFields.getFields(false), this.dataItem),
                                    parentId: this.parentId,
                                    isInit: false,
                                    viewName: this.viewName,
                                    setName: getSetNameFromRoute(this.route) })
            .subscribe(() => {
                if (this.viewName !== VIEW_NAME.DUPLICATE && data.key === NAVIGATION_OPTIONS_PROPERTIES.SHOW_IN_NAVIGATION) {
                    const currentOperations = this.operations.getValue();
                    const createOperation = currentOperations.find(x => x.Name === OPERATION_NAMES.create);
                    if (createOperation) {
                        createOperation.Title = !data.value.PageType || data.value.PageType === PAGE_TYPE_OPTIONS.STANDARD ? OPERATION_TITLES.continue : OPERATION_TITLES.create;
                        this.operations.next(currentOperations);
                    }
                }
            }));
    }

    // Copied from dynamic-item.component
    private initAction(action: ActionButton, checkValidity = true): Observable<boolean> {
        let hasPendingFields: boolean = false;
        this.editableFields.status.pipe(first())
            .subscribe(status => {
                if (status === StatusType.Pending) {
                    this.buttonStateService.updateActionButtonsState({ name: action.name, state: ButtonState.Loading }, ButtonState.Disabled);
                    hasPendingFields = true;
                }
            });

        const shouldSave = new ReplaySubject<boolean>(1);

        let passed = false;
        this.registerSubscription(this.editableFields.status.pipe(
            filter(status => status !== StatusType.Pending))
            .subscribe(status => {
                if (status === StatusType.Error) {
                    passed = true;
                }

                if (passed)
                    return;

                if (status === StatusType.Done) {
                    passed = true;
                    const areFieldsValid = checkValidity ? this.editableFields.valid() : true;
                    if (areFieldsValid) {
                        shouldSave.next(true);
                    } else if (hasPendingFields) {
                        this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
                    } else if (!areFieldsValid) {
                        shouldSave.next(false);
                    }

                    return;
                }
            }));

        return shouldSave.asObservable();
    }

    private triggerLock(): Observable<boolean> {
        if (!this.isItemLockable() || this.dataItem.isEmpty || this.isLocked) {
            return of(true);
        }

        const lock$ = new ReplaySubject<boolean>(1);

        this.registerSubscription(this.dynamicItemStore.saveItem(
            this.dataItem, {}, null, this.fallbackProperties
        ).pipe(
            catchError((error: GenericError, caught: Observable<any>) => {
                if (error instanceof NotFoundError) {
                    // TODO: handle non-existing
                    // this.handleNonExistentItem();
                }

                if (error instanceof LockedItemError) {
                    this.editableFields.reset();

                    lock$.next(false);
                    lock$.complete();
                    // TODO: this should be better handled. The error should contain the new item
                    return of(DataItem.fromEntityData(error.data, this.dataItem));
                }

                this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
                return caught;
            }),
            mergeMap((newDataItem: DataItem) => {
                this.isLocked = true;
                return forkJoin([this.service.executeBoundFunction<ItemMeta>(newDataItem, itemMetaSegment(this.itemMeta.state)), of(newDataItem)]);
            }),
            mergeMap(([itemMeta, newDataItem]) => {
                this.itemMeta = itemMeta;
                return this.initFields(newDataItem, itemMeta, this.formData);
            })
        ).subscribe(() => {
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
            lock$.next(true);
        }));

        return lock$.asObservable();
    }

    private isItemLockable() {
        return this.dataItem.metadata.hasLifecycle && this.dataItem.metadata.setName !== ENTITY_SET.PAGES && this.dataItem.metadata.setName !== ENTITY_SET.FORMS;
    }

    private executeCommandOnSubmit(action: string, fields: any): boolean {
        const shouldProcess = (this.dataItem.metadata.setName === ENTITY_SET.PAGES &&
            this.dataItem.isEmpty &&
            (!fields.PageType || fields.PageType === PAGE_TYPE_OPTIONS.STANDARD)) ||
            (this.dataItem.metadata.setName === ENTITY_SET.TEMPLATES && this.dataItem.isEmpty);

        if (!shouldProcess) {
            return false;
        }

        this.buttonStateService.updateActionButtonsState({ name: action, state: ButtonState.Loading }, ButtonState.Disabled);
        const data = {
            forceFullValidation: false,
            properties: {}
        };

        // OData cannot deserialize properties with value that is an Array without explicitly setting their type
        // Currently these properties do not need validation so we simply remove them
        const primitiveFields = this.service.getFieldValues(this.dataItem.metadata, fields).primitives;
        for (const property in primitiveFields) {
            if (!Array.isArray(fields[property]) && this.dataItem.metadata.properties[property][FIELD_TYPE] !== LINK_FIELD_TYPE) {
                data.properties[property] = fields[property];
            }
        }

        this.registerSubscription(this.service.executeEntityOperation(this.dataItem, SERVER_ACTIONS_NAMES.VALIDATE, data).subscribe(result => {
            if (Object.keys(result.Errors).length > 0) {
                this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
                const fieldsWithErrors = Object.keys(result.Errors);
                const validationError = new ValidationError({ code: ERROR_CODES.VALIDATION, message: stringConstants.EMPTY_STRING, status: 0 });
                const fieldErrors = fieldsWithErrors.map(f => {
                    const errorType = result.Errors[f];
                    return new FieldError(f, errorType);
                });

                validationError.fieldErrors = fieldErrors;
                this.editableFields.addModelErrors(validationError);
                this.editableFields.valid();
            } else {
                const ctx: ExecutionContext = {
                    currentRoute: this.route,
                    data: {
                        selectedItems: [],
                        entityData: this.dataItem,
                        onTemplateSelection: (templateId: string, templateName: string) => {
                            fields.TemplateName = templateName;
                            fields.TemplateId = templateId;

                            this.service.upsert({
                                data: fields,
                                dataItem: this.dataItem,
                                operation: this.getOperation(action)
                            }).subscribe(item => {
                                this.callback(item);
                            });
                        }
                    },
                    model: null
                };

                const command = new ChangeTemplateCommand(this.modalWindowService, this.dynamicItemStore, this.notificationService);

                this.registerSubscription(command.execute(ctx).subscribe((result) => {
                    if (!result.success) {
                        this.callback(result.success);
                    }
                }));
            }
        }, error => {
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
            if (error instanceof ValidationError) {
                this.editableFields.addModelErrors(error);
                this.editableFields.valid();
            }
        }));

        return true;
    }

    private onSubmitClick(actionButton: ActionButton): void {
        let onlyDirty: boolean = !this.dataItem.isEmpty;
        if (this.dataItem.metadata.setName === ENTITY_SET.PAGES) {
            onlyDirty = !this.dataItem.isEmpty && this.viewName !== VIEW_NAME.DUPLICATE;
        }

        const fields = this.editableFields.getFields(onlyDirty);
        this.setParentPropertyId(fields);

        if (this.editableFields.valid()) {
            let dataItem = this.dataItem;

            let result: Observable<DataItem>;
            if (actionButton.name === OPERATION_NAMES.sendForApproval ||
                actionButton.name === OPERATION_NAMES.sendForReview ||
                actionButton.name === OPERATION_NAMES.schedule) {
                result = this.onWorkflowOperation(actionButton);
            }

            if (this.viewName === VIEW_NAME.DUPLICATE) {
                fields.Duplicate = true;
                fields.DuplicateSourceId = dataItem.key;

                dataItem = DataItem.emptyItem(this.dataItem);
            }

            // TODO: move this logic to the extender
            if (!this.executeCommandOnSubmit(actionButton.name, fields)) {
                this.buttonStateService.updateActionButtonsState({ name: actionButton.name, state: ButtonState.Loading }, ButtonState.Disabled);

                let extenderResult: ActionResult;

                if (!result) {
                    extenderResult = this.editExtender.handleAction({
                        actionName: actionButton.name,
                        changedFields: fields,
                        item: dataItem,
                        route: this.route,
                        siteData: this.getSiteData()
                    }, this.notificationService);

                    this.registerSubscription(extenderResult.handled.subscribe((handled) => {
                        if (handled) {
                            result = extenderResult.result;
                        } else {
                            const primitiveFields = this.service.getFieldValues(this.dataItem.metadata, fields).primitives;
                            result = this.service.upsert({
                                data: fields,
                                dataItem: dataItem,
                                operation: this.getOperation(actionButton.name),
                                skipSaveTemp: Object.keys(primitiveFields).length === 0 && !this.isItemLockable()
                            });
                        }

                        this.handleResult(result, actionButton, extenderResult);
                    }));
                } else {
                    this.handleResult(result, actionButton, extenderResult);
                }
            }
        }
    }

    private handleResult(result: Observable<DataItem>, actionButton: ActionButton, extenderResult: ActionResult) {
        this.itemHooksProvider.executeObservableHook<DataItem, EditItemLifecycleHookParam>(
            result,
            "onEditItemChanged",
            x => ({ item: x })
        ).subscribe(item => {
            this.isLocked = false;
            this.buttonStateService.updateActionButtonsState({ name: actionButton.name, state: ButtonState.Checked }, ButtonState.Disabled);
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
            this.buttonStateService.getState$().pipe(filter(x => x.primary === null), first()).subscribe((state) => {
                if (extenderResult && extenderResult.closeHandler) {
                    extenderResult.closeHandler.next();
                } else {
                    this.callback(item);
                }
            });
        }, error => {
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
            if (error instanceof ValidationError) {
                this.editableFields.addModelErrors(error);
                this.editableFields.valid();
            } else {
                this.notificationService.publishBasicNotification({
                    message: error.message,
                    look: NOTIFICATION_LOOKS.ERROR,
                    duration: NOTIFICATION_DURATION_INFINITE,
                    filterParam: ITEM_EDIT_NOTIFICATION_FILTER_STATIC
                });
                this.scrollService.scrollToTop();
            }
        });
    }

    private onWorkflowOperation(actionButton: ActionButton): Observable<DataItem> {
        const result$ = new ReplaySubject<DataItem>();
        const settings = WorkflowOperationSettingsProvider.getConfirmationSettings(actionButton, this.dataItem, this.editableFields.getFields(true), (context, actionButton, dataItem, editedFields) => this.onDone(context, actionButton, dataItem, editedFields, result$));

        this.modalWindowService.openModalConfirmation(this.route.parent, settings, this.dataItem);
        return result$;
    }

    private onDone(context: ClosingContext, actionButton: ActionButton, dataItem: DataItem, editeFields: any, result$: Subject<DataItem>) {
        if (!context.data || !context.data.data) {
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
            return;
        }

        const fields = WorkflowOperationSettingsProvider.getFields(context);
        if (this.editableFields.valid()) {
            const action = new Action(actionButton.name, { action: actionButton.name, actionParameters: fields || {} });
            const sub = this.dynamicItemStore
                .saveItemWithOperationResult(dataItem, editeFields, action, undefined, undefined, ItemPosition.Default, false, false)
                .subscribe((x: any) => result$.next(x.dataItem));

            this.registerSubscription(sub);
        }
    }

    private onCancelClick(): void {
        if (this.isLocked) {
            this.registerSubscription(this.service.unlockItem(this.dataItem).subscribe(() => {
                this.isLocked = false;
                this.callback(null);
            }));
        } else {
            this.callback(null);
        }
    }

    private onUnlockClick(): void {
        this.registerSubscription(this.service.unlockItem(this.dataItem).subscribe(() => {
            this.ngOnInit();
        }));
    }

    private getItem(): Observable<DataItem> {
        if (this.dataItem.isEmpty) {
            return of(this.dataItem);
        } else {
            this.fallbackProperties = DynamicItemResolver.getFallbackProperties(this.dataItem, this.route.snapshot);
            const loadItem: LoadItem = {
                itemKey: this.dataItem.data.Id,
                entityData: this.dataItem,
                fallbackProperties: this.fallbackProperties
            };
            return this.service.getItem(loadItem);
        }
    }

    private initFields(item: DataItem, itemMeta: ItemMeta, formData: FormData[]): Observable<void> {
        if (this.fieldSections && !itemMeta.hasChanges) {
            return of(undefined);
        }

        if (itemMeta.message) {
            this.notificationService.publishBasicNotification({
                message: itemMeta.message,
                look: DEFAULT_NOTIFICATION_LOOK,
                filterParam: ITEM_EDIT_NOTIFICATION_FILTER_STATIC
            });
        } else {
            this.notificationService.close();
        }

        const clonedFormData: FormData[] = [];
        for (const fd of formData) {
            const cloned = JSON.parse(JSON.stringify(fd));
            cloned.tooltipModels = new Map(fd.tooltipModels);
            clonedFormData.push(cloned);
        }

        const fieldsMeta = itemMeta.properties;
        clonedFormData.forEach(x => {
            const field = fieldsMeta.find(y => y.name === x.name);
            if (!field)
                return;

            x.hidden = field.hidden;
            x.readonly = field.readonly;
            x.allowCreate = field.allowCreate;
            x.allowAdd = field.allowAdd;
            x.allowView = field.allowView;
            x.allowRemove = field.allowRemove;
            x.status = field.status;
            x.statusMessage = field.statusMessage;
            x.predefinedValue = field.predefinedValue;
        });

        if (this.mediaFieldLimitationsConstraints && this.mediaFieldLimitationsConstraints.settings) {
            clonedFormData.forEach(x => {
                if (x.name === MEDIA_DATA_FIELD_NAME) {
                    x.allowedFileExtensions = this.mediaFieldLimitationsConstraints.settings.allowedFileExtensions;
                    x.maximumAllowedSize = this.mediaFieldLimitationsConstraints.settings.maximumAllowedSize;
                    x.acceptableMediaTypes = this.mediaFieldLimitationsConstraints.settings.acceptableMediaTypes;
                }
                return x;
            });
        }

        const sections = this.fieldsGeneratorService.generateFieldsFromTweaks(this.dataItem.metadata, clonedFormData, item.data, itemMeta.readonly);

        // TODO: field hacks. TBR (to be refactored) - same in dynamic-update-item.component
        sections.forEach(section => {
            section.fields.forEach(field => {
                field.settings.culture = item.culture;
                if (this.hasMultipleContentCultures) {
                    if (field.settings.showForAllTranslationsLabel === undefined && field.selector !== FieldTypes.address) {
                        field.settings.showForAllTranslationsLabel = true;
                    }
                }

                field.settings.entityData = item;
                field.settings.dataItem = item;
            });
        });

        this.fieldSections = sections;
        this.editableFields.updateMirroring(this.fieldSections, item);

        return this.editExtender.modify({ sections: this.fieldSections, dataItem: this.dataItem, parentId: this.parentId, isInit: true, viewName: this.viewName, setName: getSetNameFromRoute(this.route) });
    }

    private setModuleNameIdentificator(): void {
        this.moduleNameIdentificator = this.dataItem.metadata.setName;

        if (this.parentId && this.dataItem.metadata.parent === ENTITY_SET.CLASSIFICATIONS) {
            this.moduleNameIdentificator += stringConstants.DASH + this.parentId;
        }
    }

    // TODO: remove or refactor
    private getOperation(action: string): any {
        if (action === OPERATION_NAMES.create || action === OPERATION_NAMES.edit)
            return null;

        return { action };
    }

    private setParentPropertyId(fields: any) {
        const parentIdProperty = this.dataItem.metadata.parentIdProperty;
        const parentIdUpdatable = this.dataItem.metadata.isPropertyUpdatable(parentIdProperty);
        const parentIdIsNotDirty = fields && !fields.hasOwnProperty(parentIdProperty);
        let parentId = this.prepopulatedFields && this.prepopulatedFields[parentIdProperty] || this.parentId;
        if (parentIdUpdatable && parentIdIsNotDirty && parentId) {
            if (this.dataItem.metadata.isMedia) {
                parentId = this.dataItem.data.FolderId ?? parentId;
            }

            fields[parentIdProperty] = parentId;
        }
    }

    private handleFormClasses() {
        this.formClasses = this.editExtender.getFormClasses(this.dataItem);
    }

    private handleActionMenuClasses() {
        this.actionMenuClasses = this.editExtender.getActionMenuClasses(this.dataItem);
    }

    private handleKeyboardShortcuts() {
        this.keyboardShortcutsService.init();
        const keyboardShortcutsSubscription = this.keyboardShortcutsService.addListener(this.operations, COMPONENT_NAMES.DYNAMIC_UPDATE_ITEM, true).subscribe((action: KeyboardAction) => {
            if (!action) {
                return;
            }

            switch (action.type) {
                case KeyboardActionType.Publish:
                case KeyboardActionType.Save:
                case KeyboardActionType.Schedule:
                    this.triggerKeyboardShortcutAction(action);
                    break;
            }
        });

        this.registerSubscription(keyboardShortcutsSubscription);
    }

    private triggerKeyboardShortcutAction(action: KeyboardAction) {
        if (!this.modalWindowService.isDialogOpened || !action.action) {
            return;
        }

        action.event.preventDefault();

        if (!this.editableFields.triggerValidCheck()) {
            return;
        }

        // Prevent multiple update (Publish, SaveAsDraft) operations
        if (this.buttonsState && this.buttonsState.primary && this.buttonsState.primary.state !== ButtonState.Default) {
            return;
        }

        this.onActionButtonClicked(action.action as ActionButton);
    }

    private getSiteData() {
        let siteData: SiteData = null;
        if (this.route) {
            siteData = this.route.parent ? this.route.parent.snapshot.data.siteDataStore : null;
        }
        return siteData;
    }
}
