import { Injectable } from "@angular/core";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { CommonTweaksHandler, TweakInfo } from "../shared/services/common-tweaks-handler.service";
import { NAVIGATION_OPTIONS_PROPERTIES } from "./components/navigation-options-composite-component/navigation-options.composite.component";
import { SEARCH_SITE_PROPERTIES } from "./components/search-site-composite-component/search-site.composite.component";
import { ADVANCED_OPTIONS_PROPERTIES } from "./components/advanced-options/advanced-options.composite.component";
import { LocalizationStrategyProp } from "./components/localization-strategy-component/localization-strategy.component";
import { PAGE_ITEM_FULL_NAME, PAGE_TEMPLATE_ITEM_FULL_NAME } from "../shared/services/metadata/meta-data-constants";
import { CustomTweaksHandler } from "../shared/services/custom-tweaks-handler.service";

@Injectable()
export class PagesTweaksHandler extends CommonTweaksHandler {
    canProcess(typeFullName: string): boolean {
        return typeFullName === PAGE_ITEM_FULL_NAME || typeFullName === PAGE_TEMPLATE_ITEM_FULL_NAME;
    }

    getTweakInfoMap(): TweakInfo[] {
        return [
            {
                sectionName: "MainSection",
                fields: [NAVIGATION_OPTIONS_PROPERTIES.SHOW_IN_NAVIGATION, NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE, NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE],
                fieldType: FieldTypes.navigationOptionsCompositeField
            },
            {
                sectionName: "AdvancedOptionsSection",
                fields: [SEARCH_SITE_PROPERTIES.INCLUDE_IN_SEARCH_INDEX, SEARCH_SITE_PROPERTIES.CRAWLABLE, SEARCH_SITE_PROPERTIES.PRIORITY],
                fieldType: FieldTypes.searchSiteCompositeField
            },
            {
                sectionName: "AdvancedOptionsSection",
                fields: [ADVANCED_OPTIONS_PROPERTIES.REQUIRE_SSL, ADVANCED_OPTIONS_PROPERTIES.ENABLE_VIEW_STATE, ADVANCED_OPTIONS_PROPERTIES.INCLUDE_RAD_SCRIPT_MANAGER, ADVANCED_OPTIONS_PROPERTIES.ALLOW_PARAMETER_VALIDATION],
                fieldType: FieldTypes.advancedOptionsCompositeField
            },
            {
                sectionName: "MainSection",
                fields: [LocalizationStrategyProp],
                fieldType: FieldTypes.localizationStrategy
            }
        ];
    }
}

export const PAGES_TWEAKS_HANDLER = { provide: CustomTweaksHandler, useClass: PagesTweaksHandler, multi: true };
