import { ClassProvider, Injectable } from "@angular/core";
import { FieldRegistration, FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { FIELDS_PROVIDER_TOKEN, FieldRegistryKey, DefaultFieldsProvider } from "../../../shared/fields-builder/providers/fields-registration-provider";
import { PropertyEditorWidgets } from "../../property-editor.constants";
import { NumberSettings } from "../../../../../../fields/number/number-settings";
import { NumberComponent } from "../../../../../../fields/number/number.component";

@Injectable()
export class NumberFieldProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.fieldType === FieldTypes.number && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: NumberComponent,
                settingsType: WidgetNumberSettings
            };
    }
}

export class WidgetNumberSettings extends NumberSettings {
    public init(metadata: any) {
        super.init(metadata);
        this.type = "number";
    }
}

export const NUMBER_FIELD_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: NumberFieldProvider,
    multi: true
};
