import { FieldRegistryKey, FIELDS_PROVIDER_TOKEN, DefaultFieldsProvider } from "../../shared/fields-builder/providers/fields-registration-provider";
import { FieldRegistration } from "../../shared/fields-builder/services/fields-registry";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { Injectable, ClassProvider } from "@angular/core";
import { StructureUrlNameComponent } from "../../shared/components/urlNameStructure/structure-urlName.component";
import { StructureUrlNameSettings } from "../../shared/components/urlNameStructure/structure-urlName.settings";
import { Properties } from "../../shared/fields.constants";

@Injectable()
export class MediaFieldsProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.typeName === ENTITY_SET.IMAGES || fieldRegistryKey.typeName === ENTITY_SET.VIDEOS || fieldRegistryKey.typeName === ENTITY_SET.DOCUMENTS) {
            if (fieldRegistryKey.fieldName === Properties.MEDIA_FILE_URL_NAME) {
                return {
                    readComponent: StructureUrlNameComponent,
                    settingsType: StructureUrlNameSettings,
                    writeComponent: StructureUrlNameComponent
                };
            }
        }
    }
}

export const MEDIA_FIELDS_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: MediaFieldsProvider,
    multi: true
};
