import { first, map } from "rxjs/operators";
import { Injectable, Inject, Optional } from "@angular/core";
import { Observable, ReplaySubject } from "rxjs";

import { SitefinitySdk } from "../../../../../../services/sitefinitySdk.service";
import { createQuery } from "../../../../../../services/query";
import { CHARACTERS, ACTIONS } from "../../../../constants";
import { FilterValue, FilterValuesOptions, FiltersResult, FiltersCountResult, FilterTypeParameters, Filter } from "./filter-interfaces";
import { LoadingContentState, toLoadingState } from "../../../../../shared/rxjs-extensions/toLoadingState";
import { KeyValuePair } from "./content-filter-count.component";
import { EntityData, TotalCountResult } from "../../../interfaces";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { Properties } from "../../../../../shared/fields.constants";
import { LOCAL_STORAGE, StorageService, LIBRARIES_GRID_VIEW_KEY } from "../../../../../shared/services/storage.service";
import { UserDataStore } from "../../../../../shared/services/metadata/user-data.store";
import { getGridViewMode, GridViewModes } from "../../../../../../utils";
import { stringConstants } from "../../../../../../common-constants";
import { QUERY_PARAMS_EXTENDER_TOKEN, QueryParamsExtender, getAdditionalQueryParams } from "../../../../../shared/services/query-params-extender";
import { Query } from "@progress/sitefinity-webservices-sdk/dist/sitefinity-webservices-sdk";

const FILTER_BASE_ENDPOINT = "filters";

@Injectable()
export class FilterService {

    constructor(private sitefinitySdk: SitefinitySdk,
                @Inject(LOCAL_STORAGE) private storageService: StorageService,
                private userStore: UserDataStore,
                @Optional() @Inject(QUERY_PARAMS_EXTENDER_TOKEN) private queryParamsExtenders: QueryParamsExtender[]) { }

    getFilters(entityData: EntityData): Observable<FiltersResult> {
        const initialValue = { isLoading: true, filters: null };
        const result$ = new ReplaySubject<FiltersResult>(1);

        result$.next(initialValue);

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, null, this.queryParamsExtenders)
        }).get({
            action: FILTER_BASE_ENDPOINT,
            successCb: data => {
                let valueProp = "Filters";

                // for backward compatibility
                if (!data.hasOwnProperty(valueProp))
                    valueProp = "value";

                const filters = data[valueProp]
                    .map(filter => {
                        let parameters: FilterTypeParameters = null;
                        if (filter.Parameters) {
                            parameters = {
                                type: filter.Parameters.Type,
                                contentSingularName: filter.Parameters.ContentSingularName,
                                contentPluralName: filter.Parameters.ContentPluralName
                            };
                        }

                        const newFilter = { title: filter.Title, name: filter.Name, category: filter.Category, parameters, count: filter.Count, isDynamicFilter: filter.IsDynamicFilter };
                        return newFilter;
                    });

                result$.next({ isLoading: false, filters });
            },
            failureCb: error => result$.error(error)
        });

        return result$.asObservable();
    }

    getDynamicFilters(entityData: EntityData, parentId: string) {
        const result$ = new ReplaySubject<Filter[]>(1);
        parentId = parentId || stringConstants.EMPTY_STRING;

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, null, this.queryParamsExtenders)
        }).get({
            action: ACTIONS.DYNAMIC_FILTERS(parentId),
            successCb: data => {
                const result = data.value
                    .map(filter => {
                        const newFilter = { title: filter.Title, name: filter.Name, count: filter.Count, category: filter.Category };
                        return newFilter;
                    });

                result$.next(result);
            },
            failureCb: error => result$.error(error)
        });

        return result$.pipe(first());
    }

    getFiltersByParameters(entityData: EntityData, expectParameters: boolean): Observable<FiltersResult> {
        return this.getFilters(entityData).pipe(
            map(result => {
                if (result.filters && result.filters.length) {
                    result.filters = result.filters.filter(x => !!x.parameters === expectParameters);
                }

                return result;
            }));
    }

    getFilterValues(entityData: EntityData, filterName: string, filterValuesOptions: FilterValuesOptions): Observable<TotalCountResult<FilterValue[]>> {
        const result$ = new ReplaySubject<TotalCountResult<FilterValue[]>>(1);
        const query: Query = this.buildQuery(filterValuesOptions);

        let actionParam = filterName;
        if (filterValuesOptions.keys && filterValuesOptions.keys.length) {
            actionParam = `${filterName}${CHARACTERS.COMMA}${filterValuesOptions.keys.join(CHARACTERS.COMMA)}`;
        }

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, null, this.queryParamsExtenders)
        }).get({
            query,
            action: ACTIONS.FILTER_VALUES(actionParam),
            successCb: data => {
                const values: FilterValue[] = data.value.map(v => ({
                    key: v.Key,
                    userAvatar: v.ImageUrl,
                    title: v.Title,
                    description: v.Description
                }));

                result$.next({
                    dataItems: values,
                    totalCount: data["@odata.count"]
                });
            },
            failureCb: error => result$.error(error)
        });

        return result$.pipe(first());
    }

    getFiltersCount(entityData: EntityData, filterName: string, parentId: KeyValuePair): Observable<LoadingContentState<FiltersCountResult>> {
        const result$ = new ReplaySubject<FiltersCountResult>(1);
        let query: any = createQuery();

        let action = ACTIONS.FILTERS_COUNT(filterName);

        if (parentId) {
            if (MediaHelpers.isMediaEntity(entityData)) {
                const gridMode = this.storageService.getItem(LIBRARIES_GRID_VIEW_KEY);
                const userId = this.userStore.userId;
                const view = getGridViewMode(gridMode, userId);

                if (view === GridViewModes.Timeline) {
                    action = action + `&recursiveLibraryId=${parentId.value}`;
                } else {
                    query = query.where()
                        .or()
                        .and()
                        .eq(Properties.PARENT_ID, parentId.value)
                        .eq(Properties.FOLDER_ID, null)
                        .done()
                        .eq(Properties.FOLDER_ID, parentId.value)
                        .done()
                        .done();
                }
            } else {
                query = query.where().eq(parentId.key, parentId.value).done();
            }
        }

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, null, this.queryParamsExtenders)
        }).get({
            query,
            action: action,
            successCb: data => {
                const result: FiltersCountResult = {
                    count: data.value
                };
                result$.next(result);
            },
            failureCb: error => result$.error(error)
        });

        return result$.pipe(toLoadingState());
    }

    private buildQuery(filterValuesOptions: FilterValuesOptions) {
        let query = createQuery();

        if (filterValuesOptions) {
            const skip = filterValuesOptions.skip;
            if (skip && skip > 0) {
                query = query.skip(skip);
            }

            const take = filterValuesOptions.take;
            if (take && take >= 0) {
                query = query.take(take);
            }

            const search = filterValuesOptions.search;
            if (search) {
                query = query.search(encodeURIComponent(search));
            }

            query = query.count();
        }

        return query;
    }
}
