import { stringConstants } from "../common-constants";

export class UrlHelper {
    static mergeUrlQueryParams(url: string, newQueryParams: { [key: string]: string }): string {
        const queryParams = {};
        let result = url;

        const queryStartIndex = url.indexOf("?");
        if (queryStartIndex > -1) {
            const queryString = url.substr(queryStartIndex + 1);
            queryString.split("&").forEach(pair => {
                const keyValuePairSeparatorIndex = pair.indexOf("=");
                const key = pair.substr(0, keyValuePairSeparatorIndex);
                const value = pair.substr(keyValuePairSeparatorIndex + 1);

                queryParams[key] = value;
            });

            result = url.substr(0, queryStartIndex);
        }

        for (const key in newQueryParams) {
            if (!newQueryParams.hasOwnProperty(key)) {
                continue;
            }

            const value = newQueryParams[key];
            queryParams[key] = value;
        }

        const queryString = UrlHelper.convertToQueryString(queryParams);
        if (!queryString.length) {
            return result;
        }

        return `${result}?${queryString}`;
    }

    static convertToQueryString(queryParams: { [key: string]: string }): string {
        let result = stringConstants.EMPTY_STRING;

        for (const key in queryParams) {
            if (!queryParams.hasOwnProperty(key)) {
                continue;
            }

            const value = queryParams[key];
            if (result !== stringConstants.EMPTY_STRING) {
                result = `${result}&${key}=${value}`;
            } else {
                result = `${key}=${value}`;
            }
        }

        return result;
    }

    static removeProtocol(url: string) {
        const protocolIndex = url.indexOf("://");
        if (protocolIndex !== -1) {
            return url.substring(protocolIndex + 3);
        }

        return url;
    }
}
