import { Component } from "@angular/core";
import { ProviderSelectorBaseComponent } from "../provider-selector/provider-selector-base.component";
import { ProviderStore } from "../../services/provider-store";
import { SelectorEventArgs } from "@progress/sitefinity-component-framework";

export const PROVIDER_TAB_CSS_CLASS = "-sf-mr-3xl";

@Component({
    selector: "sf-provider-tab-selector",
    templateUrl: "./provider-tab-selector.component.html"
})
export class ProviderTabSelectorComponent extends ProviderSelectorBaseComponent {

    constructor(store: ProviderStore) {
        super(store);
    }

    onDropdownClicked(event: Event) {
        if (event) {
            event.stopPropagation();
        }
    }

    onSplitButtonChange(provider: string) {
        this.onChange.emit(<SelectorEventArgs>{ tabValue: provider, triggerTabSelection: true });
    }
}
