import { of as observableOf,  Observable } from "rxjs";

import { map } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { CanActivate, Router, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";

import { BaseResolver } from "./dynamic-items-base.resolver";
import { ProviderStore } from "../services/provider-store";
import { Settings } from "../../../shared/services/settings.service";
import { FilterStore } from "./sidebar/filter/filter.store";
import { EntityData } from "../interfaces";
import { FILTER_PARAMS, ROUTE_PARAMS } from "../../constants";
import { CompositeEntityDataResolver } from "../services/backend-tweaks/entity-data.resolver";

@Injectable()
export class DynamicItemsResolver extends BaseResolver implements CanActivate {
    constructor(
        store: ProviderStore,
        router: Router,
        settings: Settings,
        private filterStore: FilterStore,
        entityDataResolver: CompositeEntityDataResolver) {
        super(store, router, settings, entityDataResolver);
        this.persistCulture = true;
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<EntityData> {
        const entityData = super.resolve(route, state) as EntityData;
        if (!entityData) {
            return observableOf(null);
        }

        const currentFilter = route.parent.queryParams[FILTER_PARAMS.FILTER];
        const parentId = route.parent.params[ROUTE_PARAMS.PARENT_ID_SEGMENT];
        return this.filterStore.filterValid(entityData, currentFilter, parentId).pipe(map(valid => {
            if (!valid) {
                this.clearFilter(route, state);
                return null;
            } else {
                return entityData;
            }
        }));
    }
}
