import { Component, Input, OnInit, OnDestroy } from "@angular/core";
import { DataContext } from "../../../../shared/models/data-context-component";
import { LetterMarkStore } from "../../services/letter-mark.store";

/**
 * Component used to display a column with the capitalized first letter from the taxon title
 * For items with same first letter it will appear only once and will look like grouping
 */
@Component({
    selector: "sf-letter-mark",
    templateUrl: "./letter-mark.component.html"
})

export class LetterMarkComponent implements OnInit, OnDestroy {
    @Input() public context: DataContext;
    letter: string;

    constructor(
        private store: LetterMarkStore) {
    }

    ngOnInit(): void {
        this.letter = this.initLetter(this.context.dataItem.title);
    }

    ngOnDestroy() {
        this.store.clear();
    }

    private initLetter(title: string): string {
        const letter = this.store.addLetter(title.charAt(0).toUpperCase());
        return letter;
    }
}