import { Observable, of } from "rxjs";
import { catchError, finalize, first, map } from "rxjs/operators";
import { GridActionMenuComponent } from "../../content/dynamic-modules/components/grid-cells/grid-action-menu/grid-action-menu.component";
import { MainFieldComponent } from "../../content/dynamic-modules/components/grid-cells/main-field/main-field.component";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService, LoadItemsResponse } from "../../content/dynamic-modules/services/dynamic-item.service";
import { Operation, OPERATION_NAMES, OPERATION_TITLES } from "../../shared/components/action-menu/operation.model";
import { GetListDetailsModelArgs, GetListIndexModelArgs, GetListItemsArgs, ListDetailsModel, ListIndexContract, ListIndexModel, ListIndexOperationResult } from "../../shared/services/list/list-index.contract";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { ActivatedRoute, Router } from "@angular/router";
import { ErrorStatusComponent } from "../../shared/components/status/error-status.component";
import { DateTimePickerReadOnlyComponent } from "../../../../../fields/date-time/date-time-picker-readOnly.component";
import { DurationComponent } from "../../shared/components/duration/duration.component";
import { ActionButton } from "../../shared/components/action-menu/action-menu-model";
import { RunAgainCommand } from "./commands/run-again.command";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { FILTER_PARAMS, SERVICE_HOOK_ACTIVITY_STATUS } from "../../content/constants";
import { NotificationService } from "../../shared/services/notification/notification.service";
import { EMPTY_SCREEN_ICONS } from "../../content/dynamic-modules/dynamic-item.constants";

export const SERVICE_HOOKS_HISTORY_DAYS_COUNT = 14;

export class ServiceHookHistoryContract extends ListIndexContract {
    constructor(entityData: EntityData, dynamicItemService: DynamicItemService, router: Router, private modalWindowService: ModalWindowService, private notificationService: NotificationService) {
        super(entityData, dynamicItemService, router);
    }

    getListIndexModel(getListIndexModelArgs: GetListIndexModelArgs): ListIndexModel {
        return {
            title: getListIndexModelArgs.dataItem.data.Title,
            titleCss: "-sf-h-medium",
            emptyListMessage: `No runs found in the last ${SERVICE_HOOKS_HISTORY_DAYS_COUNT} days`,
            columns: [{
                name: "Main",
                title: "Trigger",
                css: "-title -no-pointer",
                dataFieldNames: ["Title"],
                componentData: {
                    type: MainFieldComponent,
                    properties: {
                        hasStatusIcon: false
                    }
                },
                clickable: false
            }, {
                name: "Status",
                title: "Status",
                css: "-no-pointer -col-size-m",
                dataFieldNames: ["Status"],
                componentData: {
                    type: ErrorStatusComponent,
                    properties: {
                        errorLabel: "Why?",
                        successStatus: SERVICE_HOOK_ACTIVITY_STATUS.SUCCESSFUL
                    }
                },
                clickable: false
            }, {
                name: "StartTime",
                title: "Start",
                css: "-no-pointer -col-size-m",
                dataFieldNames: ["StartTime"],
                componentData: {
                    type: DateTimePickerReadOnlyComponent,
                    properties: {
                        displayAsRelativeDate: true,
                        settings: {
                            look: "-two-lines"
                        }
                    }
                },
                clickable: false
            }, {
                name: "Duration",
                title: "Duration",
                css: "-no-pointer -col-size-sm",
                dataFieldNames: ["Duration"],
                componentData: {
                    type: DurationComponent
                },
                clickable: false
            }, {
                name: "Actions",
                title: "",
                css: "-action -col-size-3xs",
                componentData: {
                    type: GridActionMenuComponent,
                    properties: {
                        operations$: this.getOperations()
                    }
                }
            }],
            operations: of([]),
            singularName: "run",
            pluralName: "runs",
            emptyScreenIcon: EMPTY_SCREEN_ICONS["servicehooks-history"],
            navigationVisible: true,
            navigationTitle: OPERATION_TITLES.runsHistory,
            navigationButtonTitle: "Back to Service hooks",
            navigationBackUrl: `${ROUTE_PATHS.INTEGRATIONS}/${ENTITY_SET.SERVICEHOOKS}`,
            pageSize: 50,
            isLoadMoreSearchEnabled: true,
            isLoadMoreFilterEnabled: false,
            filterArgs: {
                filterDisplayValue: "name",
                filterValues: [
                    {
                        name: "All runs",
                        value: "all"
                    },
                    {
                        name: "Successful runs",
                        value: "success"
                    },
                    {
                        name: "Failed runs",
                        value: "fail"
                    }
                ],
                filterConfig: {
                    showRecentLabel: false,
                    showSelectedItemAsActive: true,
                    actions: []
                }
            },
            notificationFilter: `${this.entityData.metadata.typeFullName}Activity`,
            searchArgs: {
                placeholder: "Search by trigger..."
            }
        };
    }

    getOperations(): Observable<Operation[]> {
        const runAgainOperation: Operation = {
            Title: OPERATION_TITLES.runAgain,
            Name: OPERATION_NAMES.runAgain,
            Category:
            {
                Name: OPERATION_TITLES.runAgain
            }
        };

        return of([runAgainOperation]);
    }

    getListItems(getListItemsArgs: GetListItemsArgs): Observable<LoadItemsResponse> {
        if (getListItemsArgs.loadData.action === OPERATION_NAMES.history) {
            const queryParams: { [key: string]: any } = {};

            if (getListItemsArgs.loadData.skip) {
                queryParams.$skip = getListItemsArgs.loadData.skip;
            }

            if (getListItemsArgs.loadData.take) {
                queryParams.$top = getListItemsArgs.loadData.take;
            }

            if (getListItemsArgs.loadData.additionalQueryParams?.[FILTER_PARAMS.SEARCH]) {
                queryParams.$search = getListItemsArgs.loadData.additionalQueryParams[FILTER_PARAMS.SEARCH];
            }

            const action = `Default.GetHistory(filter='${getListItemsArgs.loadData.additionalQueryParams?.[FILTER_PARAMS.FILTER] ?? "all"}')`;

            return this.dynamicItemService.executeBoundFunction<{ value: any[], "@odata.count": number }>(getListItemsArgs.dataItem, action, [], queryParams)
                .pipe(map((serviceHookHistory) => {
                    return this.dynamicItemService.getItemListMapper(serviceHookHistory, getListItemsArgs.loadData.entityData);
                }));
        } else {
            throw new Error("Operation not supported.");
        }
    }

    getListDetailsModel(getListDetailsModelArgs: GetListDetailsModelArgs): ListDetailsModel {
        throw new Error("Method not implemented.");
    }

    tryExecuteOperation(dataItem: DataItem, button: ActionButton, activatedRoute?: ActivatedRoute): Observable<ListIndexOperationResult> {
        if (button.name === OPERATION_NAMES.runAgain) {
            let error: Error = null;
            let showSuccessMessage = false;
            const runAgainCommand = new RunAgainCommand(this.modalWindowService, this.dynamicItemService);
            return runAgainCommand.execute({
                model: null,
                data: {
                    dataItem: dataItem,
                    action: button
                },
                currentRoute: activatedRoute
            }).pipe(
                first(),
                map((result: boolean) => {
                    showSuccessMessage = result;
                    return <ListIndexOperationResult>{
                        isExecuted: true,
                        requiresReload: result
                    };
                }),
                catchError(err => {
                    error = err;
                    return of(<ListIndexOperationResult>{
                        isExecuted: true,
                        requiresReload: err && err.activityStatus === SERVICE_HOOK_ACTIVITY_STATUS.FAILED
                    });
                }),
                finalize(() => {
                    const notificationInfo = runAgainCommand.getNotification(error, showSuccessMessage);
                    if (notificationInfo) {
                        const model = this.getListIndexModel({ typeFullName: dataItem.metadata.typeFullName, dataItem: dataItem });
                        notificationInfo.filterParam = model.notificationFilter;

                        this.notificationService.publishBasicNotification(notificationInfo);
                    }
                }));
        }

        return super.tryExecuteOperation(dataItem, button, activatedRoute);
    }
}
