import { Component, OnInit } from "@angular/core";
import { FieldSectionModel, FieldSectionSettings } from "../../../services/fieldSection.model";
import { FieldModel } from "../../../services/field.model";
import { FieldTypes } from "../fields-builder/services/fields-registry";
import { createFieldModel } from "../fields.constants";
import { CompositeFieldsProvider } from "../fields-builder/providers/fields-provider";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { delayEmission, toLoadingState } from "../rxjs-extensions";
import { tap, map } from "rxjs/operators";
import { UserPreferencesService } from "./user-preferences.service";
import { MINIMUM_LOADER_TIME } from "../../../../../fields/loader-wrapper/loader-wrapper.component";
import { FormFieldWrapperComponent } from "../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const USER_PREFERENCES_MODEL_PROPERTIES = {
    ONBOARDING_TIPS: "onboardingTips",
    STAY_AFTER_PUBLISH: "stayAfterPublish",
    OUTLINE: "outline",
    CONTRAST: "contrast",
    QUICK_CREATE: "quickCreate"
};
const USER_PREFERENCES_FIELD_TITLES = {
    ONBOARDING_TIPS: "Onboarding tips",
    STAY_AFTER_PUBLISH: "Stay on the same page after Publish",
    OUTLINE: "Outline elements when navigating with keyboard",
    CONTRAST: "Increase contrast",
    QUICK_CREATE: "Use quick create for Pages, Forms, Libraries and Classifications"
};
const RESET_EVENT = "reset-tooltip-service";

@Component({
    selector: "sf-user-preferences",
    templateUrl: "./user-preferences.component.html"
})
export class UserPreferencesComponent extends SfRxBase implements OnInit {
    fieldsSections: Array<FieldSectionModel>;

    private onboarding: boolean;
    private stayAfterPublish: boolean;
    private outline: boolean;
    private contrast: boolean;
    private quickCreate: boolean;

    constructor(private fieldsProvider: CompositeFieldsProvider, private readonly dynamicItemStore: DynamicItemStore, private userPreferencesService: UserPreferencesService) {
        super();
    }

    ngOnInit() {
        this.initialize();
    }

    onChange(value, key, formFieldWrapper: FormFieldWrapperComponent) {
        const preferencesSubscription = this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.SetPreference(key='${key}',value='${value}')`)
            .pipe(
                toLoadingState(),
                delayEmission(MINIMUM_LOADER_TIME),
                map(x => x.isLoading),
                tap(isLoading => {
                    if (!isLoading) {
                        formFieldWrapper.writeValue(value);

                        if (key === USER_PREFERENCES_MODEL_PROPERTIES.ONBOARDING_TIPS) {
                            const event = new Event(RESET_EVENT);
                            window.dispatchEvent(event);
                        }

                        if (key === USER_PREFERENCES_MODEL_PROPERTIES.OUTLINE || key === USER_PREFERENCES_MODEL_PROPERTIES.CONTRAST) {
                            this.userPreferencesService.checkAccessibility();
                        }
                    }
                })
            ).subscribe();
        this.registerSubscription(preferencesSubscription);
    }

    private initialize() {
        const preferenceKeys: string = this.getPreferenceKeys();
        this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetPreference(keys=[${preferenceKeys}])`).subscribe((preferences) => {
            const settings = JSON.parse(preferences.value);

            this.onboarding = (settings[USER_PREFERENCES_MODEL_PROPERTIES.ONBOARDING_TIPS].toLowerCase() === "true");
            this.stayAfterPublish = (settings[USER_PREFERENCES_MODEL_PROPERTIES.STAY_AFTER_PUBLISH].toLowerCase() === "true");
            this.outline = (settings[USER_PREFERENCES_MODEL_PROPERTIES.OUTLINE].toLowerCase() === "true");
            this.contrast = (settings[USER_PREFERENCES_MODEL_PROPERTIES.CONTRAST].toLowerCase() === "true");
            this.quickCreate = (settings[USER_PREFERENCES_MODEL_PROPERTIES.QUICK_CREATE].toLowerCase() === "true");

            this.initSections();
        });
    }

    private initSections(): void {
        const generalFieldsSection: FieldSectionModel = this.getGeneralSection();
        const accessibilityFieldsSection: FieldSectionModel = this.getAccessibilitySection();
        this.fieldsSections = [generalFieldsSection, accessibilityFieldsSection];
    }

    private getGeneralSection(): FieldSectionModel {
        const onboardingTipsModel = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, USER_PREFERENCES_MODEL_PROPERTIES.ONBOARDING_TIPS, this.onboarding, null, USER_PREFERENCES_FIELD_TITLES.ONBOARDING_TIPS);
        const stayAfterPublishWindowModel = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, USER_PREFERENCES_MODEL_PROPERTIES.STAY_AFTER_PUBLISH, this.stayAfterPublish, null, USER_PREFERENCES_FIELD_TITLES.STAY_AFTER_PUBLISH);
        const quickCreate = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, USER_PREFERENCES_MODEL_PROPERTIES.QUICK_CREATE, this.quickCreate, null, USER_PREFERENCES_FIELD_TITLES.QUICK_CREATE);

        const fields: FieldModel[] = [onboardingTipsModel, stayAfterPublishWindowModel, quickCreate];
        const generalSectionOptions: FieldSectionSettings = {
            isMain: false,
            isExpanded: true,
            insertHorizontalRule: true,
            title: "General settings",
            name: "GeneralSettings"
        };

        const generalFieldsSection = new FieldSectionModel(generalSectionOptions);
        generalFieldsSection.fields = fields;

        return generalFieldsSection;
    }

    private getAccessibilitySection(): FieldSectionModel {
        const outlineModel = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, USER_PREFERENCES_MODEL_PROPERTIES.OUTLINE, this.outline, null, USER_PREFERENCES_FIELD_TITLES.OUTLINE);
        const contrastModel = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, USER_PREFERENCES_MODEL_PROPERTIES.CONTRAST, this.contrast, null, USER_PREFERENCES_FIELD_TITLES.CONTRAST);

        const fields: FieldModel[] = [outlineModel, contrastModel];
        const accessibilitySectionOptions: FieldSectionSettings = {
            isMain: false,
            isExpanded: false,
            insertHorizontalRule: true,
            title: "Accessibility",
            name: "Accessibility"
        };

        const accessibilityFieldsSection = new FieldSectionModel(accessibilitySectionOptions);
        accessibilityFieldsSection.fields = fields;

        return accessibilityFieldsSection;
    }

    private getPreferenceKeys(): string {
        const preferenceValues: string[] = [];
        Object.keys(USER_PREFERENCES_MODEL_PROPERTIES).forEach(key => {
            preferenceValues.push(`'${USER_PREFERENCES_MODEL_PROPERTIES[key]}'`);
        });

        return preferenceValues.join(",");
    }
}
