import { AbstractControl, ValidatorFn } from "@angular/forms";
import { isNullOrEmpty } from "../../../src/app/utils";
import { ValueRange } from "./date-range.validator";

export const VALUE_RANGE_VALIDATOR_NAME = "valueRange";

export class ValueRangeValidator {
    static validate(value: ValueRange): ValidatorFn {
        return (control: AbstractControl) => {
            if (isNullOrEmpty(control.value)) {
                return null;
            }

            const trimmedValue = +control.value;
            let minValue;
            let maxValue;

            if (value.max) {
                maxValue = +value.max;
            }

            if (value.min) {
                minValue = +value.min;
            }

            if (minValue && maxValue) {
                const errorObject = value.customErrorObject || { valueRange: { maxValue: maxValue, minValue: minValue } };
                return trimmedValue >= minValue && trimmedValue <= maxValue ? null : errorObject;
            } else if (minValue) {
                const errorObject = value.customErrorObject || { minValue: { requiredMinValue: minValue } };
                return trimmedValue >= minValue ? null : errorObject;
            } else if (maxValue) {
                const errorObject = value.customErrorObject || { maxValue: { requiredMaxValue: maxValue } };
                return trimmedValue <= maxValue ? null : errorObject;
            }
        }
    }
}
