import { Inject, NgModule } from "@angular/core";
import { SharedModule } from "../shared/shared.module";
import { DynamicModulesModule } from "./dynamic-modules/dynamic-modules.module";
import { ContentComponent } from "./content.component";
import { ModulesProvider } from "./modules.provider";
import { ContentTypeGuard } from "./content-type.guard";
import { Router } from "@angular/router";
import { WINDOW_TOKEN } from "../../window.provider";
import { environmentTypes } from "../../environment";
import { EnvironmentService } from "../shared/services/environment.service";
import { stringConstants } from "../../common-constants";
import { CompositeEntityDataResolver } from "./dynamic-modules/services/backend-tweaks/entity-data.resolver";
import { ATTR_NAME } from "./constants";
import { InsightConnectivityModule } from "../shared/insight/insight-connectivity.module";
import { INTEGRATED_MODE_ENABLED } from "../../constants/integrated-mode-constants";

export const CLICK_EVENT = "menu-item-click";
const SELECTED_CLASS = "rmSelected";

@NgModule({
    declarations: [ContentComponent],
    providers: [ModulesProvider, ContentTypeGuard, CompositeEntityDataResolver],
    imports: [
        SharedModule,
        DynamicModulesModule,
        InsightConnectivityModule
    ]
})
export class ContentModule {
    private enabled: boolean = null;
    private subscribedToOpen;

    constructor(
        private router: Router,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private envService: EnvironmentService) {
        this.attachHandlers();
    }

    private attachHandlers(): void {
        const env = this.envService.getEnvironment();
        if (env !== environmentTypes.integration) {
            return;
        }
        // since iris and the sitefinity navigation are working together, we need to attach to the click event of each menu item.
        // once we have intercepted the click, we cancel the original function to be executed with (set_cancel)
        // then we close the expanded menu and navigate to the ng-url attribute value
        // the ng-url is populated from Sitefinity with the appropriate link in iris

        const clickListener = this.onClick.bind(this);
        this.windowProvider.addEventListener(CLICK_EVENT, clickListener);

        const enabledListener = this.onEnabled.bind(this);
        this.windowProvider.addEventListener(INTEGRATED_MODE_ENABLED, enabledListener);
    }

    private onEnabled(e: CustomEvent) {
        this.enabled = e.detail.enabled;
    }

    private onClick(e: CustomEvent) {
        if (this.enabled === false)
            return;

        if (!this.subscribedToOpen) {
            this.subscribedToOpen = true;
            e.detail.sender.add_itemOpening((sender: any, openingArgs: any) => {
                if (openingArgs.get_domEvent()?.type === "focus") {
                    openingArgs.set_cancel(true);
                }
            });
        }

        const args = e.detail.eventArgs;
        let url = args.get_item().get_attributes().getAttribute(ATTR_NAME) as string;
        if (url) {
            const oldSelectedItem = e.detail.sender.get_selectedItem();
            args.set_cancel(true);
            e.detail.sender.close(true);
            this.removeSelectedClassFromNode(oldSelectedItem);
            this.setSelectedClassToNode(args.get_item());

            const queryParams = {};
            const queryParamsStart = url.indexOf("?");
            if (queryParamsStart !== -1) {
                const queryParamsString = url.substring(queryParamsStart + 1);
                const paramGroups = queryParamsString.split("&");
                paramGroups.forEach(group => {
                    const [name, value] = group.split("=");
                    queryParams[name] = value;
                });

                url = url.substring(0, queryParamsStart);
            }

            this.router.navigate([url], {queryParams: queryParams});
        }
    }

    private setSelectedClassToNode(item: any) {
        item.set_selected(true);
        item.set_cssClass(item.get_cssClass() + ` ${SELECTED_CLASS}`);
        item = item.get_parent();
        while (item.get_selectedItem === undefined) {
            item.set_cssClass(item.get_cssClass() + ` ${SELECTED_CLASS}`);
            item = item.get_parent();
        }
    }

    private removeSelectedClassFromNode(item: any) {
        if (item) {
            item.set_selected(false);
            item.set_cssClass(item.get_cssClass().replace(SELECTED_CLASS, stringConstants.EMPTY_STRING));
            item = item.get_parent();
            while (item.get_selectedItem === undefined) {
                item.set_cssClass(item.get_cssClass().replace(SELECTED_CLASS, stringConstants.EMPTY_STRING));
                item = item.get_parent();
            }
        }
    }
}
