import { Injectable } from "@angular/core";

@Injectable()
export class DateTimeUtilsService {
    private monthNames: string[] = [ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" ];
    private daysOfWeek: string[] = [ "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" ];

    public getNow() {
        return new Date();
    }

    public getFromDateAndToDateInclusiveHeaderValue(periodLengthInDays: number) {
        const now = this.getNow();

        const toDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 23, 59, 59));

        let fromDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0));
        fromDate = this.subtractDays(fromDate, periodLengthInDays);

        const fromDateISOString = fromDate.toISOString();
        const toDateISOString = toDate.toISOString();
        return {fromDateISOString, toDateISOString};
    }

    public subtractDays(date: Date, numberOfDays: number): Date {
        return this.addDays(date, -1 * numberOfDays);
    }

    public addDays(date: Date, numberOfDays: number): Date {

        const resultDate = new Date(date);
        resultDate.setUTCDate(resultDate.getUTCDate() + numberOfDays);

        return resultDate;
    }

    public toShortDateTimeFormat(dateTimeISOString: string) {
        const date = new Date(dateTimeISOString);
        const month = this.monthNames[date.getUTCMonth()];

        return `${date.getUTCDate()} ${month}`;
    }

    public toLongDateTimeFormat(dateTimeISOString: string) {
        const date = new Date(dateTimeISOString);
        const month = this.monthNames[date.getUTCMonth()];
        const dayOfWeek = this.daysOfWeek[date.getUTCDay()];

        return `${dayOfWeek}, ${date.getUTCDate()} ${month} ${date.getUTCFullYear()}`;
    }
}
