import { Component, OnInit, OnDestroy } from "@angular/core";
import { SiteSelector } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/site-selector/site-selector";
import { LanguageSelector } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/language-selector/language-selector";
import { SelectorItem } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/selector-item";
import { SelectorBase } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/selector-base";
import { Logger } from "../../../shared/services/logger-source/logger";
import { ActivatedRoute } from "@angular/router";
import { RESOLVE_NAMES } from "../../../content/constants";
import { MetadataContainer } from "../../../shared/services/metadata/meta-data.store";
import { SiteData, SiteDataStore } from "../../../shared/services/metadata/site-data.store";
import { SelectorContext } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/selector-context";
import { takeUntil } from "rxjs/operators";
import { Subject } from "rxjs";
import { FieldBase } from "../../../../../../fields/field-base";
import { SiteSelectorItem } from "../../../html/tools/create-link/link-insert-field/link-insert-selector/helpers/site-selector/site-selector-item";
import { cloneObject } from "../../../../utils";
import { DYNAMIC_ITEMS_DATA_NAME } from "../../../content/dynamic-modules/components/dynamic-item-index.constants";

export const DUPLICATE_LANG_PROP_NAME = "DuplicateLanguage";

@Component({
    templateUrl: "./site-and-language-selector.component.html",
    selector: "sf-site-and-language-selector"
})
export class SiteAndLanguageSelectorComponent extends FieldBase implements OnInit, OnDestroy {
    public selectedSiteId: string;
    public selectedLanguage: string;
    public siteSelector: SiteSelector;

    private siteAndLanguageValue: SiteAndLanguage;

    private error$ = new Subject<string>();
    private selectors: Array<SelectorBase<SelectorItem>> = [];

    private languageSelector: LanguageSelector;

    private subscriptionsHolder$ = new Subject<any>();

    constructor(
        private siteDataStore: SiteDataStore,
        private logger: Logger,
        private route: ActivatedRoute
    ) {
        super();
    }

    ngOnInit(): void {
        super.ngOnInit();

        const siteData = this.route.parent.snapshot.data[RESOLVE_NAMES.siteDataStore] as SiteData;
        const metaData = this.route.parent.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const initialCulture = this.route.parent.firstChild.snapshot.data[DYNAMIC_ITEMS_DATA_NAME].culture;

        this.siteSelector = new SiteSelector(this.logger, siteData, metaData, this.siteDataStore);
        this.selectors.push(this.siteSelector);

        this.selectedLanguage = initialCulture || siteData.DefaultContentCulture;
        this.languageSelector = new LanguageSelector(this.logger, initialCulture);
        this.selectors.push(this.languageSelector);

        this.siteSelector.addChild(this.languageSelector);
        this.siteSelector.init(new SelectorContext());

        this.selectors.forEach(s => s.error$.pipe(takeUntil(this.subscriptionsHolder$)).subscribe(this.errorHandler));

        this.selectors.forEach((selector) => {
            selector.change$.subscribe((selectorInner) => {
                if (selectorInner.isReady) {
                    if (!this.siteAndLanguageValue)
                        this.siteAndLanguageValue = {};

                    if (selectorInner === this.siteSelector) {
                        const selectedItem = selectorInner.selectedItem as SiteSelectorItem;
                        this.selectedSiteId = selectedItem.value;
                        this.selectedLanguage = this.selectedLanguage && selectedItem.cultures.find(x => x.value === this.selectedLanguage) ? this.selectedLanguage : selectedItem.defaultCulture.value;
                        this.siteAndLanguageValue.RootId = selectedItem.sitemapRootNodeId;
                        this.siteAndLanguageValue.TargetSiteId = selectedItem.value;
                        this.siteAndLanguageValue.DuplicateLanguage = this.selectedLanguage;
                    } else if (selectorInner === this.languageSelector) {
                        this.siteAndLanguageValue.DuplicateLanguage = selectorInner.selectedItem.value;
                        this.selectedLanguage = selectorInner.selectedItem.value;
                    }

                    const clone = cloneObject(this.siteAndLanguageValue);
                    this.writeValue(clone);
                }
            });
        });
    }

    ngOnDestroy(): void {
        super.ngOnDestroy();
        this.subscriptionsHolder$.next({});
    }

    private errorHandler = (error: string) => {
        this.error$.next(error);
    }
}

export interface SiteAndLanguage {
    RootId?: string;
    DuplicateLanguage?: string;
    TargetSiteId?: string;
}
