/**
 * Represents the currently edited type
 * @ExposedInApi {EntityData} EntityData v1/metadata/entity-data.d.ts
 */
export interface EntityData {
    /**
     * Gets the metadata information.
     */
    readonly metadata: Entity;
    /**
     * Gets the name of the provider, whom this entity belongs to.
     */
    readonly provider: string;
    /**
     * Gets the assigned culture of the entity.
     */
    readonly culture: string;
}

/**
 * Represents a 'data item' that holds tha actual data inside as well
 * as the metadata, provider and culture for this item
 * @ExposedInApi {DataItem} DataItem v1/metadata/data-item.d.ts
 */
export class DataItem implements EntityData {
    protected static readonly emptyVal = null;

    /**
     * Gets the identifier of the item. Returns null if there is no item.
     */
    get key(): string {
        if (this.isEmpty) {
            return null;
        }

        return this.data[this.metadata.key];
    }

    /**
     * Gets the identifier of the parent item. If there is no parent returns null.
     */
    get parentKey(): string {
        if (this.isEmpty) {
            return null;
        }

        return this.data[this.metadata.parentIdProperty] || null;
    }

    /**
     * Gets the title (main short field) of the item.
     */
    get title(): string {
        if (this.isEmpty) {
            return null;
        }

        return this.data[this.metadata.defaultFieldName];
    }

    /**
     * Gets whether item is translated.
     */
    get isTranslated(): boolean {
        if (this.isEmpty) {
            return null;
        }

        const langProp = Properties.AvailableLanguages;
        if (!this.data.hasOwnProperty(langProp))
            return true;

        return !this.culture || (this.data[langProp] as Array<string>).indexOf(this.culture) !== -1;
    }

    /**
     * Gets whether item is empty.
     */
    get isEmpty(): boolean {
        return this.data === DataItem.emptyVal;
    }

    /**
     * Gets set name of this item children.
     */
    get childSetName(): string {
        return this.metadata.children[0];
    }

    /**
     * Gets types of this item children.
     */
    get childTypes(): string[] {
        return this.metadata.children;
    }

    static fromEntityData(data: any, entityData: EntityData): DataItem {
        return DataItem.from(data, entityData.metadata, entityData.provider, entityData.culture);
    }

    static from(data: any, metadata: Entity, provider: string, culture: string): DataItem {

        let result: DataItem;

        let dataCopy = JSON.parse(JSON.stringify(data));
        dataCopy = Object.freeze(dataCopy);
        switch (metadata?.typeFullName) {
            case TAXONOMY_ITEM_FULL_NAME:
                result = new TaxonomyDataItem(dataCopy, metadata, provider, culture);
                break;
            default:
                result = new DataItem(dataCopy, metadata, provider, culture);
        }

        if (result.metadata?.isSelfReferencing || metadata?.typeFullName === HIERACHICAL_TAXON_ITEM_FULL_NAME) {
            result = DataItem.convertHierarchy(result);
        }

        if (!Object.isFrozen(result)) {
            result = Object.freeze(result);
        }

        return result;
    }

    static fromCulture(source: DataItem, culture: string) {
        return DataItem.from(source.data, source.metadata, source.provider, culture);
    }

    static fromKey(key: string, entityData: EntityData) {
        const data = { [entityData.metadata.key]: key };
        return DataItem.from(data, entityData.metadata, entityData.provider, entityData.culture);
    }

    static emptyItem(entityData: EntityData) {
        return DataItem.from(DataItem.emptyVal, entityData.metadata, entityData.provider, entityData.culture);
    }

    static duplicate(source: DataItem, includedProperties: string[], excludedProperties: string[]): DataItem {
        const partialData = {};
        Object.keys(source.metadata.properties).forEach(key => {
            // removing all properties like Id and calculated properties
            const propVal = source.metadata.properties[key];
            const isReadOnly = propVal.hasOwnProperty(READ_ONLY_FIELD) && propVal[READ_ONLY_FIELD] === "Read";
            const isIncluded = includedProperties.some(x => x === key);
            const isExcluded = excludedProperties.some(x => x === key);

            if (isExcluded)
                return;

            if (isReadOnly && isIncluded === false)
                return;

            // additional urls are not to be duplicated
            if (key === Properties.URLS)
                return;

            // url name should be a sanitized copy of the title
            if (key === Properties.URL_NAME) {
                partialData[key] = SanitizeService.prototype.sanitizeValue(source.title, propVal[FIELD_SANITIZE_REGEX], propVal[FIELD_SANITIZE_REGEX_REPLACECHARACTER]);
                return;
            }

            partialData[key] = source.data[key];
        });

        return DataItem.fromEntityData(partialData, source);
    }

    protected constructor(
        /**
         * Gets the actual data (the item).
         */
        readonly data: any,
        /**
         * Gets the metadata information for this item.
         */
        readonly metadata: Entity,
        /**
         * Gets the name of the provider, wo whom this item belongs to.
         */
        readonly provider: string,
        /**
         * Gets the assigned culture of the item.
         */
        readonly culture: string) {
    }

    private static convertHierarchy(source: DataItem) {
        let dataItemChildren: HierarchicalDataItem[] = [];
        if (!source.isEmpty) {
            const children = source.data[Properties.CHILDREN] as any[];
            if (children) {
                dataItemChildren = children.map((child) => {
                    return DataItem.fromEntityData(child, source) as HierarchicalDataItem;
                });
            }
        }

        return HierarchicalDataItem.fromDataItem(source, dataItemChildren);
    }
}

export class HierarchicalDataItem extends DataItem {
    private _children: HierarchicalDataItem[];

    protected constructor(dataItem: DataItem, children: HierarchicalDataItem[]) {
        super(dataItem.data, dataItem.metadata, dataItem.provider, dataItem.culture);
        this._children = children;
    }

    get hasChildren(): boolean {
        if (this.isEmpty) {
            return false;
        }

        return this.data.hasOwnProperty(Properties.HAS_CHILDREN) && this.data[Properties.HAS_CHILDREN];
    }

    get children(): HierarchicalDataItem[] {
        return this._children;
    }

    static fromDataItem(source: DataItem, children: HierarchicalDataItem[]) {
        const dataItem = new HierarchicalDataItem(source, children);
        return Object.freeze(dataItem);
    }
}

class TaxonomyDataItem extends DataItem {
    get childSetName(): string {
        return this.data[Properties.TAXA_URL];
    }

    get childTypes(): string[] {
        return [this.data[Properties.TAXA_URL]];
    }
}

export class NavigateToEditArguments {
    dataItem: DataItem;
    parentId?: string = null;
    replaceUrl: boolean = false;
    commandName: string = null;
    wasInCreate: boolean = false;
    reload: boolean = false;
    openDialog: boolean = false;
    openInNewWindowArgs: OpenInNewWindowArguments = null;
    mediaFieldLimitationsConstraints: FieldWithLimitations = null;
    navigateToChildrenAfterCreate: boolean = true;
    prepopulatedFields: any = null;
    headComponentData: ComponentData = null;
    singularName: string = null;
    route: ActivatedRoute = null;
    translationCultureSource?: string;
    parentItem?: DataItem;
    siteId?: string;

    constructor(args?: {dataItem: DataItem, parentId?: string, replaceUrl?: boolean, commandName?: string, wasInCreate?: boolean, reload?: boolean, openDialog?: boolean, openInNewWindowArgs?: OpenInNewWindowArguments, mediaFieldLimitationsConstraints?: FieldWithLimitations, prepopulatedFields?: any, navigateToChildrenAfterCreate?: boolean, headComponentData?: ComponentData, singularName?: string, route?: ActivatedRoute, translationCultureSource?: string, parentItem?: DataItem, siteId?: string }) {
        if (args) {
            for (const key in args) {
                if (args[key] !== undefined) {
                    this[key] = args[key];
                }
            }
        }
    }
}

export interface FieldWithLimitations {
    filedName: string;
    settings?: any;
}

