import { Component, OnInit } from "@angular/core";
import { TreeNodeComponentFeatures } from "../tree/tree-node-component.provider";
import { RelatedDataComponent } from "./related-data.component";

@Component({
    templateUrl: "./related-data-readonly.component.html"
})
export class RelatedDataReadonlyComponent extends RelatedDataComponent implements OnInit {

    ngOnInit(): void {
        super.ngOnInit();

        this.treeConfig = {
            status: !this.settings.hideStatus,
            noSelection: true,
            previewUrl: true,
            showBreadcrumb: this.showBreadcrumb,
            customComponentOriginatingFeature: TreeNodeComponentFeatures.RelatedData,
            customComponentEntitySet: this.settings.type
        };
    }
}
