import { ResolveData, Route } from "@angular/router";
import { ConfigurationGuard } from "../../components/config/config.guard";
import { ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { ModalWindowComponent } from "../shared/components/modal-window/modal-window.component";
import { MetadataStoreResolver } from "../shared/services/metadata/meta-data-store.resolver";
import { BasicSettingsComponent } from "./basic-settings.component";
import { CanDeactivateGuard } from "../shared/guards/can-deactivate.guard";
import { stringConstants } from "../../common-constants";
import { BasicSettingsRouterComponent } from "./basic-settings-router.component";
import { SiteDataStoreResolver } from "../shared/services/metadata/site-data-store.resolver";


const RESOLVERS: ResolveData = {
    metaStore: MetadataStoreResolver,
    siteDataStore: SiteDataStoreResolver
};

export const CONFIGURATIONS_ROUTES: Route[] = [
    {
        path: ROUTE_PATHS_NO_PREFIX.BASIC_SETTINGS,
        component: BasicSettingsRouterComponent,
        resolve: RESOLVERS,
        children: [
            {
                path: stringConstants.EMPTY_STRING,
                component: BasicSettingsComponent,
                canActivate: [ ConfigurationGuard ],
                canDeactivate: [ CanDeactivateGuard ],
                runGuardsAndResolvers: "paramsOrQueryParamsChange",
                resolve: {
                    metaStore: MetadataStoreResolver
                },
                children: [
                    {
                        path: "confirm/:name",
                        component: ModalWindowComponent,
                        outlet: "dialog"
                    }
                ]
            },
            {
                path: "confirm/:name",
                component: ModalWindowComponent,
                outlet: "dialog"
            }
        ]
    }
];
