import { Validators, ValidatorFn } from "@angular/forms";
import { VALIDATION_CUSTOM_MSGS, SITEFINITY_NAMESPACE, LOCALIZABLE_FIELD, SHOW_IF_FIELD, FIELD_VALIDATION_PREFIX } from "./common/common-constants";
import { NOT_SET, stringConstants } from "../src/app/common-constants";
import { EntityData, DataItem } from "../src/app/modules/content/dynamic-modules/interfaces";
import { VALIDATION_REQUIRED } from "./common/common-constants";
import { KeyValue } from "@angular/common";
import { MarkupConfig } from "@progress/sitefinity-component-framework";
import { SHORT_TEXT_PATTERN_VALIDATION_ERROR_MSG, SHORT_TEXT_PLACEHOLDER } from "./short-text/short-text.constants";

export const DEFAULT = "default";
export const INLINE_DESCRIPTION = "inlineDescription";
export const INSTRUCTIONAL_NOTES = "instructionalNotes";

/**
 * @ExposedInApi {SettingsBase} SettingsBase v1/custom-fields/field-settings-base.d.ts
 */
export class SettingsBase {
    public displayMode: any;
    public validators: ValidatorFn;
    public title: string;
    public friendlyTitle: string;
    public showTitle: boolean = true;
    public visibleTitle: boolean = true;
    public underlineErrors: boolean = false;
    public instructionalText: string;
    public emptyValueText: string = NOT_SET;
    public defaultValue: any = null;
    public type: string;
    public look: string;
    public rows: number;
    public unit: string;
    public required: boolean = false;
    public inlineDescription: string;
    public instructionalNotes: string;
    public tooltipModels: MarkupConfig;
    public translatable: boolean = false;
    public hasFieldset: boolean = false;
    public hintPositionTop: boolean = false;
    public showForAllTranslationsLabel: boolean;
    public culture: string; // TODO: Fields refactoring remove
    public markAsDirty: boolean = false;
    public useDefaultValue: boolean = true;
    public emptyValues: any[] = [null, undefined];
    public status: string;
    public statusMessage: string;
    public allowCreate: boolean = true;
    public allowAdd: boolean = true;
    public allowRemove: boolean = true;
    public allowView: boolean = true;
    public isGroup: boolean; // like address field
    public isVisible: boolean = true;
    public isVisibleContent: boolean = true;
    public recommendedCharacters: number;
    public showCharCounter: boolean = false;
    public disabled: boolean;
    public isNestedInParentControl: boolean;
    public tableViewColumnCssClass: string;

    // used for triggering change when the item was focused
    public changeOnFocus: boolean = false;
    public placeholder: string = stringConstants.EMPTY_STRING;
    public entityData: EntityData;
    public dataItem: DataItem;
    public customErrorMsgs: KeyValue<string, string>;

    public conditionalRule: Rule;
    public patternValidationErrorMessage: string;

    public customLinks: Array<CustomLink>;

    constructor(public key: string, public readOnlyMode: boolean) {
        this.title = this.key; // TODO: extract it from metadata
    }

    public init(metadata: any) {
        // auto mapping of properties
        const metaKeyword = "Meta_";
        this.autoMapSettings(metadata, metaKeyword, "_");
        this.autoMapSettings(metadata, FIELD_VALIDATION_PREFIX, ".");
        this.autoMapSettings(metadata, SITEFINITY_NAMESPACE, ".", FIELD_VALIDATION_PREFIX);

        this.placeholder = metadata[SHORT_TEXT_PLACEHOLDER] || stringConstants.EMPTY_STRING;
        this.required = !!metadata[VALIDATION_REQUIRED];
        this.inlineDescription = metadata[INLINE_DESCRIPTION];
        this.instructionalNotes = metadata[INSTRUCTIONAL_NOTES];
        this.validators = Validators.compose(this.getValidators(metadata));
        this.translatable = metadata.hasOwnProperty(LOCALIZABLE_FIELD) && metadata[LOCALIZABLE_FIELD];
        this.customErrorMsgs = metadata[VALIDATION_CUSTOM_MSGS];
        if (this.defaultValue === null && metadata[DEFAULT]) {
            this.defaultValue = metadata[DEFAULT];
        }

        if (metadata[SHOW_IF_FIELD] && this.isVisible) {
            const rule = metadata[SHOW_IF_FIELD];
            try {
                this.conditionalRule = JSON.parse(rule) as Rule;
            } catch (_) {
                // we want this error to be non-breaking, but still display some sort of warning
                // if we throw here, the generation of the item edit form does not execute and iris freezes
                // tslint:disable-next-line:no-console
                console.error(`Conditional rule invalid JSON format for field with key '${this.key}'`);
            }
        }

        this.addEmptyValues(metadata);
        this.patternValidationErrorMessage = metadata[SHORT_TEXT_PATTERN_VALIDATION_ERROR_MSG];
    }

    public getValidators(metadata: any): Array<ValidatorFn> {
        const validators: Array<ValidatorFn> = [];
        if (this.required) {
            validators.push(Validators.required);
        }

        return validators;
    }

    /**
     * Deep equality comparer for field settings. Compares each property and returns false on the first different property value.
     * Functions are ignored.
     * @param settings field settings
     * @param propToSkip poperty name to be skipped during the comparison (default: "dataItem")
     */
    public equals(settings: SettingsBase, propToSkip: string = "dataItem"): boolean {
        for (const key in settings) {
            if (settings.hasOwnProperty(key)) {
                if (propToSkip && key === propToSkip) {
                    continue;
                }
                const val = settings[key];
                if (typeof val === "object") {
                    if (JSON.stringify(val) !== JSON.stringify(this[key])) {
                        return false;
                    }
                } else if (typeof val !== "function") {
                    if (val !== this[key]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private autoMapSettings(metadata: any, prefix: string, seperator: string, ignoredPrefix: string = null) {
        Object.keys(metadata).filter(x => x.startsWith(prefix)).forEach(x => {
            if (ignoredPrefix && x.startsWith(ignoredPrefix))
                return;

            let metaPropName = x.replace(prefix, stringConstants.EMPTY_STRING).replace(seperator, stringConstants.EMPTY_STRING);
            metaPropName = metaPropName[0].toLowerCase() + metaPropName.substring(1);
            this[metaPropName] = metadata[x];

            const boolVals = ["True", "False", "true", "false"];
            if (boolVals.find(x => x === this[metaPropName])) {
                this[metaPropName] = (this[metaPropName] === "true") || (this[metaPropName] === "True");
            }
        });
    }

    private addEmptyValues(metadata: any) {
        if (metadata.emptyValues) {
            this.emptyValues.push(...JSON.parse(metadata.emptyValues));
        }
    }
}

export interface Rule {
    operator: RuleOperator;
    conditions: RuleCondition[];
    inline?: boolean;
}

export enum RuleOperator {
    Or = "Or",
    And = "And"
}

export interface RuleCondition {
    fieldName: string;
    operator: RuleConditionOperator;
    value: string;
    hideContent?: boolean;
}

export enum RuleConditionOperator {
    Equals = "Equals",
    NotEquals = "NotEquals",
    Contains = "Contains",
    NotContains = "NotContains"
}

export class CustomLink {
    title: string;
    buttonClickedCallback: any;
    htmlId?: string;
    cssClass?: string;
    icon?: string;
}
