import { SettingsBase } from "../../../../fields/field-settings-base";
import { stringConstants } from "../../common-constants";
import { TaxonomySettings } from "../taxonomy";
import { TypeNames } from "../../../../fields/types/types";

export class ParentSelectorSettings extends SettingsBase {
    public hierarchicalTaxaSettings: TaxonomySettings;
    public selectorNames: TypeNames = { plural: stringConstants.EMPTY_STRING, singular: stringConstants.EMPTY_STRING };
    public showAddToTopLevel: boolean = true;
    public friendlyTitle: string;
    public excludeParent: boolean = true;
    public choiceOptions: ChoiceOption[];
    public isParentSelection: boolean = true;

    public init(metadata: any): void {
        super.init(metadata);
        this.defaultValue = stringConstants.DEFAULT_GUID;
    }
}

export interface ChoiceOption {
    Name: string;
    Value: string;
}
