import { Injectable, Inject } from "@angular/core";
import { Router } from "@angular/router";
import { Observable, ReplaySubject } from "rxjs";
import { Command } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DialogData, ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { DataItem } from "../../../interfaces";
import { DynamicItemService } from "../../dynamic-item.service";
import { WINDOW_TOKEN } from "../../../../../../window.provider";
import { EditInDialogCommand, EditInDialogArgument, EditInDialogOperationResult } from "./edit-in-dialog-command";
import { FilePickerViewMode } from "../../../../../libraries/file-picker-view-mode";
import { FilePickerComponent } from "../../../../../libraries/file-picker.component";

@Injectable()
export class MediaEditInDialogCommand extends EditInDialogCommand implements Command {
    constructor(modalWindowService: ModalWindowService, router: Router, protected service?: DynamicItemService, @Inject(WINDOW_TOKEN) protected window?: Window) {
        super(modalWindowService, router);
    }

    execute(context: ExecutionContext): Observable<EditInDialogOperationResult> {
        const data = <EditInDialogArgument>context.data;
        const dataItem = data.dataItem;

        const return$ = new ReplaySubject<EditInDialogOperationResult>(1);

        const componentData: ComponentData = {
            type: FilePickerComponent,
            properties: {
                multiple: true,
                value: [],
                name: "this.settings.name",
                allowCreate: true,
                mediaEntityData: { metadata: dataItem.metadata.clone(), provider: dataItem.provider, culture: dataItem.culture },
                initialViewMode: FilePickerViewMode.Upload,
                useOnlySelectMode: false,
                createMedia: true,
                getImageAfterUpload: false,
                selectedLibrary: context.data.parentItem
            }
        };

        const dialogData = new DialogData(componentData, () => {
            return$.next({
                dataItem: DataItem.emptyItem(dataItem),
                forceReload: true,
                success: true,
                isLoading: false
            });
        }, [], "-prompt");

        const path = "edit";
        const argument = `${path}_${dataItem.key}_${dataItem.metadata.setName}_${dataItem.provider}_${dataItem.culture}`;
        this.modalWindowService.setMapping(dialogData, argument);
        this.modalWindowService.show(argument, context.currentRoute.firstChild);

        return return$.asObservable();
    }
}
