import { Router } from "@angular/router";
import { Injectable, Inject } from "@angular/core";

import { WINDOW_TOKEN } from "../../../../../window.provider";

import { ProviderStore } from "../provider-store";
import { Settings } from "../../../../shared/services/settings.service";
import { DynamicItemService } from "../dynamic-item.service";
import { FilterStore } from "../../components/sidebar/filter/filter.store";
import { CompositeItemHooksProvider } from "./item-hooks-provider";
import { CompositeEntityDataResolver } from "../backend-tweaks/entity-data.resolver";
import { DynamicItemResolver } from "./dynamic-item.resolver";

@Injectable()
export class DynamicItemEditResolver extends DynamicItemResolver {

    constructor(
        service: DynamicItemService,
        store: ProviderStore,
        router: Router,
        @Inject(WINDOW_TOKEN) windowProvider: Window,
        settings: Settings,
        filterStore: FilterStore,
        itemHooksProvider: CompositeItemHooksProvider,
        entityDataResolver: CompositeEntityDataResolver) {
            super(service, store, router, windowProvider, settings, filterStore, itemHooksProvider, entityDataResolver);

            // Edit views are site context agnostic
            this.skipProviderValidation = true;
    }
}
