import { VALIDATOR_NAMES } from "../../../../../../../../fields/common/validators";
import { ValidationError } from "./validation-error";
import { ContentItemModel } from "./content-item-model";
import { stringConstants, validationConstants } from "../../../../../../common-constants";
import { LinkInputType } from "./link-input-type";
import { HYPER_TEXT_TRANSFER_PROTOCOL, MAILTO_PROTOCOL } from "../../create-link-helper";
import { LinkModel } from "../../../../../../../../fields/link-selector/link-model";

export const URL_LABEL: string = "URL";
export const URL_NO_SCHEME: string = "URL_NO_SCHEME";
export const EMAIL: string = "EMAIL";
// UX requirement - urls entered without scheme should be considered valid in this case
const URL_PATTERN_NO_SCHEME = /^(?!(?:https?|ftp|file):\/\/)(?:\S+(?::\S*)?@)?(?:(?!(?:10|127)(?:\.\d{1,3}){3})(?!(?:169\.254|192\.168)(?:\.\d{1,3}){2})(?!172\.(?:1[6-9]|2\d|3[0-1])(?:\.\d{1,3}){2})(?:[1-9]\d?|1\d\d|2[01]\d|22[0-3])(?:\.(?:1?\d{1,2}|2[0-4]\d|25[0-5])){2}(?:\.(?:[1-9]\d?|1\d\d|2[0-4]\d|25[0-4]))|(?:(?:[a-z\u00a1-\uffff0-9][-_~]*)*[a-z\u00a1-\uffff0-9]+)(?:\.(?:[a-z\u00a1-\uffff0-9][-_~]*)*[a-z\u00a1-\uffff0-9]+)*(?:\.(?:[a-z\u00a1-\uffff]{2,}))\.?)(?::\d{2,5})?(?:[\/?#]\S*)?$/i;

export const LINK_INPUT_TYPES: Array<LinkInputType> = [
    new LinkInputType(validationConstants.EMAIL_PATTERN, EMAIL, EMAIL),
    new LinkInputType(URL_PATTERN_NO_SCHEME, URL_NO_SCHEME, URL_LABEL),
    new LinkInputType(validationConstants.VALID_URL_PATTERN, URL_LABEL, URL_LABEL)
];

export class ContentLinkInputModel {
    // the contentItemModel property represents the model of the content item that`s been dynamically
    // linked from Sitefinity via runtime generated url. If there`s no such context and the user has simply
    // entered a raw url string this property should be unassigned
    contentItemModel: ContentItemModel;
    linkType: string;
    linkTypeName: string;
    isUrlRequired: boolean = true;

    get href(): string {
        return this._href;
    }

    set href(value: string) {
        this._href = value;
        // linkType depends on the url (href) that the user has entered
        // and we set it after each update of the href property
        this.determineLinkType();
    }

    get hrefWithProtocol(): string {
        if (this.linkType === URL_NO_SCHEME) {
            return `${HYPER_TEXT_TRANSFER_PROTOCOL}${this._href}`;
        } else if (this.linkType === EMAIL) {
            return `${MAILTO_PROTOCOL}${this._href}`;
        }

        return this._href;
    }

    // the raw url string representing the actual link to the server.
    private _href: string = stringConstants.EMPTY_STRING;
    constructor(linkData?: LinkModel) {
        if (linkData) {
            if (linkData.sfref) {
                this.contentItemModel = new ContentItemModel();
                this.contentItemModel.sfLink = {
                    sfref: linkData.sfref,
                    href: linkData.href
                };
            }

            this.href = linkData.href;
            this.determineLinkType();
        }
    }

    getErrors(): Array<ValidationError> {
        if (this.contentItemModel) {
            if (this.contentItemModel.validationErrors.length > 0) {
                return this.contentItemModel.validationErrors;
            } else {
                return [];
            }
        }

        if (this.isUrlRequired) {
            if (!this._href) {
                return [{ errorType: VALIDATOR_NAMES.REQUIRED, error: { message: "You must enter a url or email." } }];
            }
        }

        if (this._href && !this.linkType) {
            return [{ errorType: VALIDATOR_NAMES.REQUIRED, error: { message: "You must enter a valid url or email." } }];
        }

        return [];
    }

    determineLinkType() {
        this.linkType = stringConstants.EMPTY_STRING;
        if (this._href) {
            for (let index = 0; index < LINK_INPUT_TYPES.length; index++) {
                const type = LINK_INPUT_TYPES[index];
                if (type.isMatch(this._href)) {
                    this.linkType = type.name;
                    this.linkTypeName = type.title;
                    break;
                }
            }
        }
    }
}
