import { CollectionResponse } from "./collection-response";

export class HttpDataResponseUtils {

    public static flattenCollectionResponse<T>(collectionResponse: CollectionResponse<T>): T[] {
        return collectionResponse.items;
    }

    public static firstOrDefault<T>(collectionResponse: CollectionResponse<T>): T {

            if (collectionResponse && collectionResponse.items && collectionResponse.items.length > 0)
                return collectionResponse.items[0];
            else
                return null;
    }
}
