import { Injectable, Inject } from "@angular/core";
import { CommonActionContext, GridActionContext, LoadingActionContext } from "../shared/services/grid/grid-extender-base";
import { Observable, ReplaySubject, of } from "rxjs";
import { COMMAND_NAMES } from "../content/dynamic-modules/components/commands";
import { DataItem, NavigateToEditArguments } from "../content/dynamic-modules/interfaces";
import { OPERATION_NAMES } from "../shared/components/action-menu/operation.model";
import { WINDOW_TOKEN } from "../../window.provider";
import { SAME_TAB_TARGET } from "../../common-constants";
import { Router } from "@angular/router";
import { ROOT_PREFIX, ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { EditNavigationService } from "../shared/services/edit-navigation.service";
import { FILTER_PARAMS, FILTER_TYPES, QUERY_PARAMS } from "../content/constants";
import { EditInDialogOperationResult } from "../content/dynamic-modules/services/operations/commands/edit-in-dialog-command";
import { DynamicItemStore } from "../content/dynamic-modules/services/dynamic-item.store";
import { first, map } from "rxjs/operators";
import { Settings } from "../shared/services/settings.service";
import { environment } from "../../../environments/environment";
import { environmentTypes } from "../../environment";
import { FormsConstants } from "./forms.constants";
import { ActionHandler } from "../content/dynamic-modules/components/action-handler";

const SITEFINITY = "Sitefinity";

@Injectable()
export class FormsActionHandler implements ActionHandler {

    constructor(
        private editNavigationService: EditNavigationService,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private dynamicItemStore: DynamicItemStore,
        private router: Router,
        private settings: Settings) {
    }

    tryHandleAction(context: CommonActionContext): Observable<boolean> {
        const actionName = context.actionName;
        if (actionName === COMMAND_NAMES.changeCulture) {
            const dataItem = DataItem.fromCulture(context.item, context.data.culture);
            const commonContext: CommonActionContext = {
                actionName: OPERATION_NAMES.editContent,
                item: dataItem,
                route: context.route
            };

            const gridContext = context as GridActionContext;
            if (gridContext.grid) {
                (commonContext as GridActionContext).grid = gridContext.grid;
            }

            return this.tryHandleAction(commonContext);
        }

        if (actionName === OPERATION_NAMES.duplicate)
        {
            return this.navigateToDuplicate(context);
        }

        if (actionName === OPERATION_NAMES.editContent) {
            if (!context.item.isTranslated) {
                return this.navigateToEdit(context);
            } else {
                const ret = new ReplaySubject<boolean>(1);
                const args = new NavigateToEditArguments({
                    dataItem: context.item,
                    route: context.route,
                    commandName: OPERATION_NAMES.editContent,
                    navigateToChildrenAfterCreate: false
                });
                this.editNavigationService.confirm(args).subscribe((confirmResult) => {
                    if (confirmResult.success) {
                        if (context.data && context.data.component) {
                            context.data.component.visible = true;
                            ret.complete();
                        } else {
                            if (this.tryEditForm(context.item, true, this.getQueryParams(context), confirmResult.data.link)) {
                                this.configureGrid(context, true, false);
                            } else {
                                ret.next(false);
                                ret.complete();
                            }
                        }
                    } else {
                        if (context.data && context.data.component) {
                            context.data.component.onNavigateBack();
                        }

                        this.configureGrid(context, false, false);
                    }
                });

                ret.next(true);
                return ret.asObservable();
            }
        }

        return of(false);
    }

    public navigateToTitleAndProperties(context: CommonActionContext): Observable<EditInDialogOperationResult> {
        const ret = new ReplaySubject<EditInDialogOperationResult>(1);
        this.configureGrid(context, true, false);
        const args = new NavigateToEditArguments({
            dataItem: context.item,
            route: context.route,
            commandName: context.actionName || OPERATION_NAMES.edit,
            navigateToChildrenAfterCreate: false,
            openDialog: true
        });

        if (context.actionName === OPERATION_NAMES.duplicate && args.dataItem.data) {
            args.parentId = args.dataItem.data.ParentId;
        }

        this.editNavigationService.navigateToEdit(args).subscribe((navigateResult) => {
            if (navigateResult.success) {
                this.configureGrid(context, false, true);
            } else {
                this.configureGrid(context, false, false);
            }
            ret.next(navigateResult);
        });

        return ret.asObservable();
    }

    public navigateToDuplicate(context: CommonActionContext): Observable<boolean> {
        const ret = new ReplaySubject<boolean>(1);
        this.configureGrid(context, true, false, false);
        const args = new NavigateToEditArguments({
            dataItem: context.item,
            route: context.route,
            commandName: OPERATION_NAMES.duplicate,
            navigateToChildrenAfterCreate: false,
            openDialog: true
        });

        this.editNavigationService.navigateToEdit(args).subscribe((navigateResult) => {
            if (navigateResult.success) {
                if (this.tryEditForm(navigateResult.dataItem, false, this.getQueryParams(context))) {
                    this.configureGrid(context, true, false, false);
                }
            } else {
                this.configureGrid(context, false, false, false);
            }

            ret.next(true);
        });

        return ret.pipe(first());
    }

    public navigateToEdit(context: CommonActionContext): Observable<boolean> {
        const ret = new ReplaySubject<boolean>(1);
        this.configureGrid(context, true, false, false);
        const args = new NavigateToEditArguments({
            dataItem: context.item,
            route: context.route,
            commandName: OPERATION_NAMES.editContent,
            navigateToChildrenAfterCreate: false,
            openDialog: true
        });

        if (context.data) {
            args.parentId = context.data.parentId;
            args.prepopulatedFields = context.data.prepopulatedFields;
        }

        this.editNavigationService.navigateToEdit(args).subscribe((navigateResult) => {
            if (navigateResult.success) {
                this.configureGrid(context, true, false);
                if (!this.tryEditForm(navigateResult.dataItem, false, this.getQueryParams(context))) {
                    this.configureGrid(context, false, true);
                }
            } else {
                this.configureGrid(context, false, false);
            }
            ret.next(true);
        });

        return ret.asObservable();
    }

    private tryEditForm(dataItem: DataItem, forceReload: boolean, additionalQueryParams: any[], legacyFormLink: string = null): boolean {
        if (dataItem.data.Renderer) {
            const queryParams = {
                [QUERY_PARAMS.CULTURE]: dataItem.culture,
                [QUERY_PARAMS.PROVIDER]: dataItem.provider
            };

            if (additionalQueryParams) {
                additionalQueryParams.forEach((queryParam) => {
                    queryParams[queryParam.Name] = queryParam.Value;
                });
            }

            if (forceReload) {
                queryParams["reload"] = Math.random().toString();
            }

            this.router.navigate([ROOT_PREFIX, dataItem.metadata.setName, ROUTE_PATHS_NO_PREFIX.SF_EDIT, dataItem.key], {
                queryParams
            });
        } else {
            const link$ = legacyFormLink ?
                of(legacyFormLink) :
                this.dynamicItemStore.service.executeOperation(dataItem, OPERATION_NAMES.editContent).pipe(map(x => x.link));

            link$.pipe(first()).subscribe(link => {
                if (environment.env === environmentTypes.integration) {
                    this.openUrl(link, additionalQueryParams);
                } else {
                    let targetUrl: string;
                    const sitefinityFormsPrefix = `/${SITEFINITY}/${dataItem.metadata.setName}`.toLowerCase();
                    if (link.toLowerCase().startsWith(sitefinityFormsPrefix)) {
                        const url = link.slice(sitefinityFormsPrefix.length + 1, link.length);
                        targetUrl = `${this.settings.url}${SITEFINITY}/${ROOT_PREFIX}/${ROUTE_PATHS_NO_PREFIX.CONTENT}/${dataItem.metadata.setName}/${FormsConstants.ROUTES.EDIT}/${url}`;
                    } else {
                        const url = `${this.settings.url}${SITEFINITY}/${ROOT_PREFIX}/${ROUTE_PATHS_NO_PREFIX.CONTENT}/${dataItem.metadata.setName}/${FormsConstants.ROUTES.EDIT}/${link}`;
                        targetUrl = link.startsWith('http') ? link : url;
                    }
                    this.openUrl(targetUrl, additionalQueryParams);
                }
            });
        }

        return true;
    }

    private configureGrid(context: CommonActionContext, isLoading: boolean, reload: boolean, autoTriggerLoading: boolean = true) {
        const gridContext = context as GridActionContext;
        if (gridContext.grid) {
            gridContext.grid.autoTriggerLoading = autoTriggerLoading;
            gridContext.grid.isLoading = isLoading;
            if (reload) {
                gridContext.grid.reload();
            }
        }

        const loadingContext = context as LoadingActionContext;
        const holder = loadingContext.loadingHolder;
        if (holder) {
            holder.loading = isLoading;
        }
    }

    private openUrl(url: string, queryParams: any[]) : void {
        if (queryParams && queryParams.length) {
            const appendSymbol = url.indexOf("?") > - 1 ? "&" : "?";
            const queryParamsArray = queryParams.map(queryParam => `${queryParam.Name}=${queryParam.Value}`);
            url += `${appendSymbol}${queryParamsArray.join("&")}`;
        }

        this.windowProvider.open(url, SAME_TAB_TARGET);
    }

    private getQueryParams(context: CommonActionContext): any[] {
        const queryParams: any[] = [];
        if (context.route.snapshot.queryParams[FILTER_PARAMS.FILTER] === FILTER_TYPES.NOT_SHARED ||
            context.route.snapshot.queryParams[QUERY_PARAMS.IGNORE_SITE_CONTEXT] === "true") {
                queryParams.push({ Name: QUERY_PARAMS.IGNORE_SITE_CONTEXT, Value: true });
        }

        if (context.additionalQueryParams) {
            queryParams.push(...context.additionalQueryParams);
        }

        return queryParams;
    }
}
