import { Component, OnInit } from "@angular/core";
import { createValueAccessor } from "../../../../../../../fields";
import { ChoiceComponent } from "../../../../../../../fields/choice/choice.component";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { FIELDS_ACTIONS } from "../../../../../services/store/actions/actions.fields";
import { AppStore } from "../../../../../services/store/app-store";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { HttpODataRequestWrapper } from "../../../../shared/services/http-odata-request.wrapper";
import { Logger } from "../../../../shared/services/logger-source/logger";

@Component({
    selector: "sf-view-selector",
    templateUrl: "./view-selector.component.html",
    providers: [createValueAccessor(ViewSelectorComponent)]
})
export class ViewSelectorComponent extends ChoiceComponent implements OnInit {
    constructor(
        httpRequestWrapper: HttpODataRequestWrapper,
        private store: AppStore,
        logger: Logger) {
        super(httpRequestWrapper, logger);
    }

    ngOnInit() {
        this.mapChoiceItems();
        this.dispatchViewNameChanged();
        this.setSelected();

        if (this.settings) {
            this.choiceSettings = {
                key: this.settings.key,
                wrapperCssClass: this.settings.look
            };
        }
    }

    onSelectionChange(index) {
        super.onSelectionChange(index);
        this.dispatchViewNameChanged();
    }

    private dispatchViewNameChanged() {
        if (this.settings.key === "SfViewName") {
            this.store.dispatch(FIELDS_ACTIONS.changeViewName({ viewName: this.getValue() }));
        }
    }
}

export const VIEW_SELECTOR_SETTINGS_REGISTRY: FieldRegistration = {
    writeComponent: ViewSelectorComponent,
    readComponent: ViewSelectorComponent,
    settingsType: ChoiceSettings
};
