import { LOCAL_STORAGE, StorageService } from "./modules/shared/services/storage.service";
import { NgModule } from "@angular/core";
import { APP_BASE_HREF } from "@angular/common";

import { WINDOW_PROVIDER } from "./window.provider";
import { DOCUMENT_PROVIDER, DOCUMENT_TOKEN } from "./document.provider";
import { ScrollService } from "./services/scroll.service";
import { SanitizeService } from "./services/sanitize.service";
import { LockedItemStatusResolver } from "./services/status.resolver";
import { CompositeFieldsProvider } from "./modules/shared/fields-builder/providers/fields-provider";
import { AppBaseHrefFactory } from "./app-base-href.factory";
import { SelectorService, SELECTOR_SERVICE } from "./modules/libraries/selectors";
import { CompositeThemeProvider } from "./theme/composite-theme-provider";
import { DynamicItemGuard } from "./modules/content/dynamic-modules/services/entity/dynamic-item.guard";
import { ConfigurationGuard } from "./components/config/config.guard";
import { UnsupportedBrowserGuard } from "./components/use-a-browser/browser.guard";
import { IntegratedModeGuard } from "./services/admin-app/integrated-mode.guard";
import { IntegratedEmptyComponentGuard } from "./components/empty/integrated-empty.component.guard";
import { HomeGuard } from "./modules/shared/components/navigation/home/home.guard";
import { BundleDataService } from "./services/bundle-data.service";
import { KeyboardShortcutsService } from "./services/keyboard-shortcuts.service";
import { DamProviderService } from "./modules/libraries/dam/dam-provider.service";

/**
 * Holds all the providers that should be injected
 * directly in the AppModule.
 *
 * @export
 * @class AppProvidersModule
 */
@NgModule({
    providers: [
        WINDOW_PROVIDER,
        DOCUMENT_PROVIDER,
        { provide: LOCAL_STORAGE, useClass: StorageService },
        ScrollService,
        KeyboardShortcutsService,
        SanitizeService,
        LockedItemStatusResolver,
        DynamicItemGuard,
        ConfigurationGuard,
        UnsupportedBrowserGuard,
        IntegratedModeGuard,
        IntegratedEmptyComponentGuard,
        HomeGuard,
        { provide: APP_BASE_HREF, useFactory: new AppBaseHrefFactory().getBaseHref, deps: [ LOCAL_STORAGE, DOCUMENT_TOKEN ] },
        CompositeFieldsProvider,
        { provide: SELECTOR_SERVICE, useClass: SelectorService },
        CompositeThemeProvider,
        BundleDataService,
        DamProviderService
    ]
})
export class AppProvidersModule { }
