import { SettingsBase } from "../../../../../fields/field-settings-base";
import { MediaEntity } from "../../shared/services/metadata/meta-data.store";

export class MediaSettings extends SettingsBase {

    allowMultiple: boolean;
    useLiveData: boolean;
    name: string;
    acceptableMediaTypes: Array<string>;
    acceptableFileTypes: Array<string>;
    mediaFilterEnabled: boolean;
    provider: string;
    maxSize: number;
    allowedExtensionsRegEx: RegExp;
    targetLibraryId?: string;
    sourceLibraryId?: string;
    useOnlyUploadMode?: boolean;
    useOnlySelectMode?: boolean;
    selectButtonText: string;
    chipLike?: boolean;
    openPickerWhenEmpty?: boolean; // used by widget editors
    hidePropertiesLabel?: boolean;
    canRelateDamAssets: boolean;

    init(metadata: any): void {
        super.init(metadata);

        const typeDefinition = {
            keys: ["Id"],
            properties: metadata
        };

        const mediaEntity = new MediaEntity(null, typeDefinition);

        this.name = mediaEntity.name;
        this.mediaFilterEnabled = mediaEntity.mediaFilterEnabled;
        this.acceptableMediaTypes = mediaEntity.acceptableMediaTypes;
        this.acceptableFileTypes = mediaEntity.acceptableFileTypes;
        this.allowedExtensionsRegEx = mediaEntity.allowedExtensionsRegEx;
        this.maxSize = mediaEntity.maxSize;
        this.changeOnFocus = true;

        // TODO: investigate why emptyValues are needed and whether defaultValue could be use instead
        this.emptyValues = this.emptyValues.concat([[]]);
    }
}
