import { Component, Input, OnInit } from "@angular/core";
import { DataContext } from "../../../shared/models/data-context-component";
import { stringConstants } from "../../../../common-constants";
import { MIME_TYPES } from "../../services/media.helpers";

@Component({
    templateUrl: "./file-grid-size.component.html"
})
export class FileDimSizeComponent implements OnInit {
    @Input() public context: DataContext;
    fileExtension: string;
    width: number;
    height: number;
    fileSizeInKb: number;
    isVectorGraphics: boolean;

    ngOnInit() {
        const item = this.context.dataItem.data;
        const extension = item.Extension;
        if (!extension) {
            return;
        }

        if (item.MimeType && item.MimeType === MIME_TYPES.SVG) {
            this.isVectorGraphics = true;
        }

        this.fileExtension = extension.replace(".", stringConstants.EMPTY_STRING).toUpperCase();

        this.width = item.Width;
        this.height = item.Height;

        this.fileSizeInKb = Math.round(item.TotalSize / 1024);
    }
}
