import { Injectable, Inject, OnDestroy } from "@angular/core";

import { WINDOW_TOKEN } from "../window.provider";
import { ActionButton, ActionSection } from "../modules/shared/components/action-menu/action-menu-model";
import { OPERATION_NAMES, Operation } from "../modules/shared/components/action-menu/operation.model";
import { Observable, Subject } from "rxjs";
import { ActionButtonsResolver } from "../modules/content/dynamic-modules/components/action-buttons.resolver";
import { PropertyEditorCustomEvents } from "../modules/widget-editor/property-editor.constants";
import { DEFAULT_SHORTCUTS, KeyboardActionShortcut, KeyboardActionType, MAC_OS_NAME, SITEFINITY_MODAL_DIALOG_CLOSED_EVENT, SITEFINITY_MODAL_DIALOG_OPENED_EVENT } from "./keyboard-shortcuts.constants";
const KEYDOWN_EVENT = "keydown";

const SHOULD_FALLBACK_OPERATIONS = [
    KeyboardActionType.Refresh,
    KeyboardActionType.CommonConfirm
];

@Injectable()
export class KeyboardShortcutsService implements OnDestroy {
    private keyDownEventListener: EventListener;
    private sfModalOpenedEventListener: EventListener;
    private sfModalClosedEventListener: EventListener;
    private irisModalClosedEventListener: EventListener;
    private subscribers: Array<KeyboardSubscriber> = new Array<KeyboardSubscriber>();
    private isMacOS: boolean;
    private shortcuts: Array<KeyboardActionShortcut> = DEFAULT_SHORTCUTS;
    private isSfModalOpen: boolean = false;
    public name = "";

    constructor(
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private actionButtonsResolver: ActionButtonsResolver) {}

    init() {
        // Remove the listnerers because sometimes the events are emmitted twice
        this.removeEventListeners();
        this.isMacOS = navigator.appVersion.indexOf(MAC_OS_NAME) !== -1;

        this.addEventListeners();
        this.populateShortcutsKeyValues();
    }

    ngOnDestroy() {
        this.removeEventListeners();
    }

    /**
     * Adds a subsriber that will be notified when specific keyboard shortcut command is applied
     *
     * @param {Observable<Operation[]>} operations$ The operations that the subscriber can handle
     * @param {string} componentName The Component.name property in order to store given operation to specific subsriber
     * @param {boolean} fallback Determines if the services should fallback to another subscriber if no action is found in the current subscriber
     * @returns {Subject<KeyboardAction>} The action that the subsriber should execute
     */
    addListener(operations$: Observable<Operation[]>, componentName: string, fallback: boolean): Subject<KeyboardAction> {
        const keyboardAction = new Subject<KeyboardAction>();

        operations$.subscribe((operations: Operation[]) => {
            const subscriberData: KeyboardSubscriber = {
                componentName: componentName,
                fallback,
                keyboardAction
            };

            if (operations) {
                subscriberData.actionButtons = this.actionButtonsResolver.getActionButtons(operations);
            }

            const hasSubscriberIndex = this.subscribers.findIndex(x => x.componentName === componentName);
            if (hasSubscriberIndex > -1) {
                this.subscribers.splice(hasSubscriberIndex, 1);
            }

            // Place the last subscriber to be at first index in order to easy foreaching them later
            this.subscribers.unshift(subscriberData);
        });

        return keyboardAction;
    }

    /**
     * Removes a subsriber and he will not be notified when specific keyboard shortcut command is applied.
     * Must always be called on OnDestroy of the subscriber
     *
     * @param {string} componentName The Component.name property in order to store given operation to specific subsriber
     */
    removeListener(componentName: string) {
        const hasSubscriberIndex = this.subscribers.findIndex(x => x.componentName === componentName);
        if (hasSubscriberIndex > -1) {
            this.subscribers.splice(hasSubscriberIndex, 1);
        }
    }

    private addEventListeners() {
        this.keyDownEventListener = evt => this.onKeyDown(evt as KeyboardEvent);
        this.sfModalOpenedEventListener = (evt: CustomEvent) => this.toggleSfModalState(evt, true);
        this.sfModalClosedEventListener = (evt: CustomEvent) => this.toggleSfModalState(evt, false);
        this.irisModalClosedEventListener = (evt: CustomEvent) => this.toggleSfModalState(evt, false);

        this.windowProvider.addEventListener(KEYDOWN_EVENT, this.keyDownEventListener);
        this.windowProvider.document.addEventListener(SITEFINITY_MODAL_DIALOG_OPENED_EVENT, this.sfModalOpenedEventListener);
        this.windowProvider.document.addEventListener(SITEFINITY_MODAL_DIALOG_CLOSED_EVENT, this.sfModalClosedEventListener);
        this.windowProvider.document.addEventListener(PropertyEditorCustomEvents.MODAL_DIALOG_CLOSED, this.irisModalClosedEventListener);
    }

    private removeEventListeners() {
        this.windowProvider.removeEventListener(KEYDOWN_EVENT, this.keyDownEventListener);
        this.windowProvider.document.removeEventListener(SITEFINITY_MODAL_DIALOG_OPENED_EVENT, this.sfModalOpenedEventListener);
        this.windowProvider.document.removeEventListener(SITEFINITY_MODAL_DIALOG_CLOSED_EVENT, this.sfModalClosedEventListener);
        this.windowProvider.document.removeEventListener(PropertyEditorCustomEvents.MODAL_DIALOG_CLOSED, this.irisModalClosedEventListener);
    }

    private toggleSfModalState(event: CustomEvent, opened: boolean) {

        if (!(event.detail && event.detail.openNewEditor)) {
            this.isSfModalOpen = opened;
        }
    }

    private onKeyDown(event: KeyboardEvent) {
        const keyboardActionShortcut = this.shortcuts.find((shortcut: KeyboardActionShortcut) => {
            // Change Ctrl key to CMD if on MacOS as this is more intuitive behaviour
            const commandKeyCheck = this.isMacOS ? shortcut.ShortcutSettings.ctrlKey === event.metaKey : shortcut.ShortcutSettings.ctrlKey === event.ctrlKey;

            if (shortcut.ShortcutSettings.code === event.code &&
                shortcut.ShortcutSettings.altKey === event.altKey &&
                shortcut.ShortcutSettings.shiftKey === event.shiftKey &&
                commandKeyCheck) {
                    return shortcut;
            }
        });

        if (!keyboardActionShortcut) {
            return;
        }

        // We need to notify the last subscriber about the key down event
        for (const subscriber of this.subscribers) {
            const keyboardData =  this.handleKeyboardAction(keyboardActionShortcut, subscriber, event);

            // There're some operations that have to be emitted even if the last handler has no fallback property set to false
            const shouldFallback = SHOULD_FALLBACK_OPERATIONS.some(o => o === keyboardData.type) || subscriber.fallback;

            // There should be only one handler then we must not notify other subscribers
            if (!shouldFallback || !!keyboardData.action) {
                break;
            }
        }
    }

    private handleKeyboardAction(keyboardActionShortcut: KeyboardActionShortcut, subscriber: KeyboardSubscriber, event: KeyboardEvent): KeyboardAction {
        const keyboardData: KeyboardAction = {
            type: keyboardActionShortcut.ActionType,
            event
        };
        let shouldNext = false;

        switch (keyboardActionShortcut.ActionType) {
            case KeyboardActionType.Escape:
                shouldNext = true;
                break;
            case KeyboardActionType.CommonConfirm:
                shouldNext = true;
                break;
            case KeyboardActionType.Refresh:
                shouldNext = true;
                break;
            case KeyboardActionType.SelectAll:
                shouldNext = true;
                break;
            case KeyboardActionType.Create:
                keyboardData.action = this.getCreateOperation(subscriber.actionButtons);
                shouldNext = true;
                break;
            case KeyboardActionType.Publish:
                keyboardData.action = this.getPublishWorkflowOperation(subscriber.actionButtons);
                // TODO: When Media uses Operations then this shouldNext won't be necessery
                shouldNext = true;
                break;
            case KeyboardActionType.Save:
                keyboardData.action = this.getSaveAsDraftWorkflowOperation(subscriber.actionButtons);
                // TODO: When Media uses Operations then this shouldNext won't be necessery
                shouldNext = true;
                break;
            case KeyboardActionType.Delete:
                keyboardData.action = this.getButtonOperation(OPERATION_NAMES.delete, subscriber.actionButtons);
                shouldNext = !!keyboardData.action;
                break;
            case KeyboardActionType.Unpublish:
                keyboardData.action = this.getButtonOperation(OPERATION_NAMES.unpublish, subscriber.actionButtons);
                shouldNext = !!keyboardData.action;
                break;
            case KeyboardActionType.Schedule:
                keyboardData.action = this.getButtonOperation(OPERATION_NAMES.schedule, subscriber.actionButtons);
                shouldNext = !!keyboardData.action;
                break;
            case KeyboardActionType.Preview:
                keyboardData.action = this.getButtonOperation(OPERATION_NAMES.preview, subscriber.actionButtons);
                shouldNext = !!keyboardData.action;
                break;
            case KeyboardActionType.InsertImage:
                shouldNext = true;
                break;
            case KeyboardActionType.InsertLink:
                shouldNext = true;
                break;
        }

        if (shouldNext && !this.isSfModalOpen) {
            subscriber.keyboardAction.next(keyboardData);
            shouldNext = false;
        }

        return keyboardData;
    }

    private getButtonOperation(action: string, actionButtons: (ActionButton | ActionSection)[]): ActionButton | ActionSection {
        if (!actionButtons) {
            return null;
        }

        return actionButtons.find(a => a.name === action);
    }

    private getCreateOperation(actionButtons: (ActionButton | ActionSection)[]): ActionButton {
        // Order is important as we need to trigger the first available Create operations
        const createVariations = [
            OPERATION_NAMES.createMedia,
            OPERATION_NAMES.create
        ];

        const action: ActionButton = this.getFirstAvailableAction(createVariations, actionButtons);

        return action;
    }

    private getPublishWorkflowOperation(actionButtons: (ActionButton | ActionSection)[]): ActionButton {
        // TODO: handle custom workflow
        // Order is important as we need to trigger the top level Workflow operations
        const publishWorkflowVariations = [
            OPERATION_NAMES.publish,
            OPERATION_NAMES.sendForPublishing,
            OPERATION_NAMES.sendForApproval,
            OPERATION_NAMES.sendForReview
        ];

        const action: ActionButton = this.getFirstAvailableAction(publishWorkflowVariations, actionButtons);

        return action;
    }

    private getSaveAsDraftWorkflowOperation(actionButtons: (ActionButton | ActionSection)[]): ActionButton {
        // TODO: handle custom workflow
        // Order is important as we need to trigger the top level Workflow operations
        const saveAsDraftWorkflowVariations = [
            OPERATION_NAMES.saveDraft,
            OPERATION_NAMES.saveAsAwaitingPublishing,
            OPERATION_NAMES.saveAsAwaitingApproval,
            OPERATION_NAMES.saveAsAwaitingReview,
            OPERATION_NAMES.create,
            OPERATION_NAMES.edit
        ];

        const action: ActionButton = this.getFirstAvailableAction(saveAsDraftWorkflowVariations, actionButtons);

        return action;
    }

    private getFirstAvailableAction(targets: string[], actionButtons: (ActionButton | ActionSection)[]) {
        if (!actionButtons) {
            return null;
        }

        let action: ActionButton;

        for (const target of targets) {
            const currentAction = actionButtons.find(a => a.name === target);

            if (currentAction) {
                action = currentAction as ActionButton;
                break;
            }
        }

        return action;
    }

    private populateShortcutsKeyValues() {
        // Setting the default values to false for easy check later with the eveny data
        this.shortcuts.forEach((s: KeyboardActionShortcut) => {
            s.ShortcutSettings.ctrlKey = s.ShortcutSettings.ctrlKey || false;
            s.ShortcutSettings.altKey = s.ShortcutSettings.altKey || false;
            s.ShortcutSettings.shiftKey = s.ShortcutSettings.shiftKey || false;
        });
    }
}

export interface KeyboardSubscriber {
    componentName: string,
    keyboardAction: Subject<KeyboardAction>,
    fallback: boolean
    actionButtons?: (ActionButton | ActionSection)[],
}

export interface KeyboardAction {
    type: KeyboardActionType,
    event: KeyboardEvent,
    action?: ActionButton | ActionSection,
}

interface CustomEvent extends Event {
    detail: EventDetail;
}

interface EventDetail {
    openNewEditor: boolean;
}
