import { Observable, of, ReplaySubject } from "rxjs";
import { AuthProvider, AUTH_PROVDER_TOKEN, Token } from "../auth.provider";
import { Injectable, ClassProvider, Inject } from "@angular/core";
import { WINDOW_TOKEN } from "../../../window.provider";
import { AuthorizationServerSettings } from "../../shared/services/authorizationServerSettings";

@Injectable()
export class OauthProvider implements AuthProvider {
    private static token$ = new ReplaySubject<Token>(1);
    private static token: OAuthToken;

    constructor(private settings: AuthorizationServerSettings, @Inject(WINDOW_TOKEN) private window: Window) {

    }

    static setToken(token: OAuthToken) {
        OauthProvider.token$.next({
            type: token.type,
            value: token.value
        });

        OauthProvider.token = token;
    }

    init(): Observable<void> {
        return of(null);
    }

    signIn(returnUrl: string): Observable<void> {
        const redirectUri = encodeURIComponent(this.settings.redirectUri);
        const encodedReturnUrl = encodeURIComponent(encodeURIComponent(returnUrl));
        const url = this.settings.authorizationEndpoint + `?response_type=${this.settings.responseType}&client_id=${this.settings.clientId}&redirect_uri=${redirectUri}&state=${encodedReturnUrl}`;
        this.window.location.href = url;
        return of(null);
    }

    signOut(): Observable<void> {
        if (this.settings.signOutEndpoint) {
            this.window.location.href = this.settings.signOutEndpoint;
        } else {
            OauthProvider.token$.next(null);
        }

        return of();
    }

    isLoggedIn(): Observable<boolean> {
        const result = !!OauthProvider.token && OauthProvider.token.expirationTime > new Date();
        return of(result);
    }

    getToken(): Observable<Token> {
        return OauthProvider.token$.asObservable();
    }

    getName(): string {
        return "oauth";
    }

    getPriority(): number {
        return 2;
    }

    isAvailable(): Observable<boolean> {
        return this.settings.isValid();
    }
}

export const OAUTH_PROVIDER: ClassProvider = {
    multi: true,
    provide: AUTH_PROVDER_TOKEN,
    useClass: OauthProvider
};

export class OAuthToken implements Token {
    type: string;
    value: string;
    expirationTime: Date;
}
