import { Validators } from "@angular/forms";
import { SettingsBase } from "./../field-settings-base";
import { VALIDATORS as CustomValidators, VALIDATOR_NAMES } from "../common/validators";
import { VALIDATION_REGEX } from "../common/common-constants";
import { MirrorFieldSettings, MIRROR_FIELD_SETTING_KIND } from "../short-text/short-text-settings";
import { VALIDATION_MAX_VALUE, VALIDATION_MIN_VALUE } from "../common/common-constants";

export class TextAreaSettings extends SettingsBase implements MirrorFieldSettings {
    public mirroredFieldName: string;
    public enableMirroring: boolean;
    public kind: string = MIRROR_FIELD_SETTING_KIND;

    public init(metadata: any): void {
        super.init(metadata);
    }

    public getValidators(metadata: any) {
        const baseValidators = super.getValidators(metadata);

        if (metadata.hasOwnProperty(VALIDATION_MIN_VALUE)) {
            baseValidators.push(CustomValidators[VALIDATOR_NAMES.MIN_LENGTH](metadata[VALIDATION_MIN_VALUE]));
        }

        if (metadata.hasOwnProperty(VALIDATION_MAX_VALUE)) {
            baseValidators.push(Validators.maxLength(metadata[VALIDATION_MAX_VALUE]));
        }

        if (metadata.hasOwnProperty(VALIDATION_REGEX)) {
            const regex = new RegExp(metadata[VALIDATION_REGEX], "g");
            baseValidators.push(Validators.pattern(regex));
        }
        
        if (metadata.hasOwnProperty("Meta_JsonValidator_ValidateJsonFieldInForm") && metadata["Meta_JsonValidator_ValidateJsonFieldInForm"] === "True") {
            baseValidators.push(CustomValidators[VALIDATOR_NAMES.JSON]());
        }

        return baseValidators;
    }
}
