import { TotalCountResult } from "../../content/dynamic-modules/interfaces";
import { ComponentMetadata } from "../../widget-editor/interfaces/widget-editor";
import { Injectable } from "@angular/core";
import { RendererContract, GetWidgetMetadataArgs, RenderWidgetArgs, GetWidgetsArgs, GetCategoriesArgs, WidgetSection, RenderResult } from "./renderer.types";

/**
 * Should be injected into the iframe when we have support for working with legacy pages in the new zone editor
 */
@Injectable()
export class WebFormsAndMvcRendererContract implements RendererContract {
    getWidgetMetadata(args: GetWidgetMetadataArgs): Promise<ComponentMetadata> {
        return new Promise((resolve => resolve({
            Caption: null,
            Name: null,
            PropertyMetadata: [],
        })));
    }

    renderWidget(args: RenderWidgetArgs): Promise<RenderResult> {
        return new Promise((resolve => resolve(null)));
    }

    getWidgets(args: GetWidgetsArgs): Promise<TotalCountResult<Array<WidgetSection>>> {
        return new Promise((resolve => resolve({ dataItems: [], totalCount: 0 })));
    }

    getCategories(args: GetCategoriesArgs): Promise<Array<string>> {
        return new Promise((resolve => resolve([])));
    }
}
