import { Component, Inject, OnInit} from "@angular/core";
import { ActivatedRoute, ActivatedRouteSnapshot } from "@angular/router";
import { ROUTE_PATHS } from "../../src/app/constants/route-paths";
import { QUERY_PARAMS } from "../../src/app/modules/content/constants";
import { DataItem } from "../../src/app/modules/content/dynamic-modules/interfaces";
import { UrlService } from "../../src/app/services/url.service";
import { WINDOW_TOKEN } from "../../src/app/window.provider";
import { createValueAccessor, FieldBase } from "../field-base";
import { NavigateToUrlSettings } from "./navigate-to-url.settings";

@Component({
    selector: "sf-navigate-to-url",
    templateUrl: "./navigate-to-url.component.html",
    providers: [createValueAccessor(NavigateToUrlComponent)]
})
export class NavigateToUrlComponent extends FieldBase<NavigateToUrlSettings> implements OnInit {
    private route: ActivatedRouteSnapshot;
    public dataItem: DataItem;
    constructor(activatedRoute: ActivatedRoute, @Inject(WINDOW_TOKEN) private window: Window, private urlService: UrlService) {
        super();

        this.route = activatedRoute.snapshot;
    }

    ngOnInit() {
        super.ngOnInit();
        this.dataItem = this.route.data.itemData.entityData;
    }

    navigateToUrl() {
        if (this.dataItem?.data && this.settings.url) {
            let revertUrl = this.window.location.href;

            if (this.route.outlet === "dialog") {
                const primaryRoute = this.route.parent.children.find(x => x.outlet === "primary");
                if (primaryRoute) {
                    const previousUrl = `${ROUTE_PATHS.CONTENT}/${this.dataItem.metadata.setName}/${primaryRoute.url.map(url => url.path).join("/")}`;
                    revertUrl = `${this.urlService.getAbsoluteUrl(previousUrl)}?${QUERY_PARAMS.EDIT_ITEM_ID}=${this.dataItem.data.Id}`;
                }
            }

            this.settings.url += `&revertUrl=${encodeURIComponent(revertUrl)}`;
            this.window.open(this.settings.url, "_self");
        }
    }
}
