const DEFAULT_TAKE = 50;

export const SINGLE_OPERATIONS_LABEL = "Actions";
export const BULK_OPERATIONS_LABEL = "Bulk actions";
export const BULK_ITEM_SELECTION_INFO_INITIAL_VALUE: BulkItemSelectionInfo = {
    selectedItems: new Map<string, DataItem>(),
    deselectedItems: new Map<string, DataItem>(),
    excludedItems: new Array<string>(),
    nodesPositions: new Map<string, number>()
};
export const TRANSLATIONS_LOCAL_STORAGE_KEY = "sf.translations.selectedItemIds";

const DELETE_ALL_TRANSLATIONS = "deleteAllTranslations";
const DELETE_SINGLE_TRANSLATIONS = "deleteSingleTranslation";

export interface BulkLoadingChanged {
    isLoading: boolean;
    operationName: string;
    operationResult?: BulkOperationResult;
}

/**
 * Component used to bulk edit items
 */
@Component({
    selector: "sf-bulk-operations",
    templateUrl: "./bulk-operations.component.html"
})
export class BulkOperationsComponent extends SfRxBase implements OnInit, OnDestroy, OnChanges {
    @ViewChild("bulkActionMenu", { static: false }) bulkActionMenu: ActionMenuComponent;

    @Input() entityData: EntityData;
    @Input() operations: Observable<Operation[]>;
    @Input() itemsTotalCount: number;
    @Input() loadedItemsCount: number;
    @Input() isInHeader: boolean;
    @Input() searchParameter: string;
    @Input() filterAction: string;
    @Input() disableSelectAll: boolean;
    @Input() set itemSelectionInfo(value) {
        this.setItemSelectionInfo(value);
    }
    @Input() notificationFilter: string;

    @Output() selectAllOnPage: EventEmitter<void> = new EventEmitter();
    @Output() selectAll: EventEmitter<void> = new EventEmitter();
    @Output() clearAll: EventEmitter<void> = new EventEmitter();
    @Output() singleAction: EventEmitter<any> = new EventEmitter();
    @Output() refreshItems: EventEmitter<void> = new EventEmitter();
    @Output() loadingChange: EventEmitter<BulkLoadingChanged> = new EventEmitter();

    public selectedCountNotificationLook: string;
    public bulkDropdownButtonText: string;
    public selectedItemsCount: number = 0;
    public loading$: ReplaySubject<boolean> = new ReplaySubject<boolean>(1);
    public isOperationInProgress: boolean = false;
    public excludedItemsCount: number = 0;
    readonly bulkMenuOptions: ActionMenuOptions;

    public get allItemsOnPageSelected(): boolean {
        if (this.disableSelectAll || this.itemSelectionInfoInternal.deselectedItems.size > 0)
            return false;

        return this.selectedItemsCount + this.itemSelectionInfoInternal.excludedItems.length === this.loadedItemsCount;
    }

    public get showSelectedAll(): boolean {
        if (this.disableSelectAll)
            return false;

        return this.itemSelectionInfoInternal.allItemsSelected || this.selectedItemsCount + this.itemSelectionInfoInternal.excludedItems.length === this.itemsTotalCount;
    }

    private itemSelectionInfoInternal: BulkItemSelectionInfo = BULK_ITEM_SELECTION_INFO_INITIAL_VALUE;

    /**
     * Initializes a new instance of the {@link BulkOperationsComponent} class
     */
    constructor(
        private route: ActivatedRoute,
        private modalService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        private deleteCommandExtender: CompositeDeleteCommandExtender,
        private bulkCommandExtender: CompositeBulkCommandExtender,
        private keyboardShortcutsService: KeyboardShortcutsService,
        @Inject(WINDOW_TOKEN) private window: Window,
        private injector: Injector,
        private metadataParserService: MetadataParserService,
        private contentFilterService: ContentFilterService,
        private zone: NgZone) {
        super();

        this.bulkMenuOptions = new ActionMenuOptions(Number.NEGATIVE_INFINITY, 0, true);
    }

    ngOnInit() {
        const loadingSubscription = this.loading$.subscribe(isLoading => {
            this.isOperationInProgress = isLoading;
            if (!isLoading) {
                this.onClearSelection();
            }
        });

        this.registerSubscription(loadingSubscription);

        const notificationStyles = ["sf-mr-3xs", "small inline"];
        if (this.isInHeader) {
            notificationStyles.push("sf-pl-zero", "transparent");
        }

        this.selectedCountNotificationLook = notificationStyles.join(stringConstants.INTERVAL);
        this.handleKeyboardShortcuts();
    }

    ngOnDestroy() {
        super.ngOnDestroy();

        this.keyboardShortcutsService.removeListener(COMPONENT_NAMES.BULK_OPERATIONS);
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes.loadedItemsCount && !changes.loadedItemsCount.firstChange) {
            this.itemSelectionInfoInternal.allItemsSelected = false;
            this.selectedItemsCount = this.itemSelectionInfoInternal.selectedItems.size;
            this.excludedItemsCount = this.itemSelectionInfoInternal.excludedItems.length;
        }
    }

    onActionButtonClicked(action: ActionButton) {
        // TODO: Treat single operation like bulk once all of the single operations have commands #243340
        if (this.selectedItemsCount === 1) {
            this.performSingleOperation(action);
        } else {
            this.performBulkOperation(action);
        }
    }

    onSelectAllOnPage() {
        this.selectAllOnPage.emit();
    }

    onSelectAll() {
        this.selectAll.emit();
    }

    onClearSelection() {
        this.clearAll.emit();
    }

    private performSingleOperation(action: ActionButton) {
        const dataItem = this.itemSelectionInfoInternal.selectedItems.values().next().value;
        const dataItemId = dataItem.key;
        if (dataItemId) {
            if (action.token) {
                const instance = this.injector.get(action.token.type) as Command;
                const context: ExecutionContext = {
                    model: null,
                    data: action.token.properties,
                    currentRoute: null
                };

                instance.execute(context).subscribe();
                return;
            }

            this.singleAction.emit({
                entityData: dataItem,
                dataItemKey: dataItemId,
                button: action
            });

            this.onClearSelection();
        }
    }

    private performBulkOperation(button: ActionButton) {
        let items$: Observable<Array<DataItem>> = null;
        const wrappedCommand = this.getWrappedCommand(button);
        if (this.itemSelectionInfoInternal.allItemsSelected) {
            items$ = this.getAllItems(button, wrappedCommand);
        } else {
            const items = Array.from(this.itemSelectionInfoInternal.selectedItems.values());
            items$ = observableOf(items);
        }

        items$.pipe(tap(items => this.executeBulkCommand(items, button, wrappedCommand))).subscribe();
    }

    private getAllItems(button: ActionButton, wrappedCommand: Command): Observable<Array<DataItem>> {
        const allDataItems$: Observable<Array<DataItem>>[] = [];
        this.bulkCommandExtender.getEntityDatasForBulkOperation(this.entityData, this.filterAction).forEach(entityData => {
            const query = this.buildItemQuery(entityData);

            const skips = [];
            for (let i = 0; i < this.itemsTotalCount; i += DEFAULT_TAKE) {
                skips.push(i);
            }

            let additionalFieldNames = [];
            const needsAdditionalFieldsCommand = wrappedCommand as NeedsAdditionalFieldsCommand;
            if (needsAdditionalFieldsCommand && needsAdditionalFieldsCommand.getAdditionalFieldsNames) {
                additionalFieldNames = needsAdditionalFieldsCommand.getAdditionalFieldsNames(entityData);
            }

            const result$: Observable<DataItem[]> = observableFrom(skips).pipe(
                mergeMap(skip => this.getItems(query, skip, entityData, additionalFieldNames, button)),
                reduce((previous, current) => previous.concat(current)));

            allDataItems$.push(result$);
        });

        return combineLatest(allDataItems$).pipe(
            map(response => ([]).concat(...response))
        );
    }

    private buildItemQuery(entityData: EntityData): WhereQuery<Query> {
        let query = createQuery().where();

        const parentId = this.route.parent.snapshot.params[ROUTE_PARAMS.PARENT_ID_SEGMENT] || null;
        if (parentId && this.entityData.metadata.hasParent) {
            query = this.bulkCommandExtender.getFilterByParentQuery(entityData, query, parentId);
        }

        if (this.searchParameter) {
            query = this.contentFilterService.applySearch(this.searchParameter, entityData, query);
        }

        query = query.done() as any;
        return query;
    }

    private getItems(query: WhereQuery<Query>, skip: number, entityData: EntityData, additionalFieldNames: string[], action: ActionButton): Observable<Array<DataItem>> {
        const dataFieldNames = [entityData.metadata.key, ...additionalFieldNames];
        if (this.isActionCultureSpecific(action) && entityData.metadata.properties.hasOwnProperty(Properties.AvailableLanguages) && dataFieldNames.indexOf(Properties.AvailableLanguages) === -1) {
            dataFieldNames.push(Properties.AvailableLanguages);
        }

        return this.dynamicItemStore.getItemList({
            entityData: entityData,
            action: this.filterAction,
            query: query,
            dataFieldNames,
            skip: skip,
            take: DEFAULT_TAKE
        }).pipe(
            map(response => response.dataItems
                .filter(item => !this.itemSelectionInfoInternal.deselectedItems.has(item.key))
            ));
    }

    private executeBulkCommand(selectedItems: Array<DataItem>, action: ActionButton, wrappedCommand: Command) {
        const bulkCommand = new BulkCommand(wrappedCommand);
        const executionContext = this.getBulkCommandExecutionContext(selectedItems, action);

        bulkCommand
            .confirm(executionContext).pipe(
                mergeMap(bulkArgs => {
                    if (!bulkArgs.data.confirmed) {
                        return observableNever();
                    }

                    this.loading$.next(true);
                    this.loadingChange.emit({ isLoading: true, operationName: action.name });

                    if (bulkArgs.data.entityData && bulkArgs.data.entityData.culture) {
                        bulkArgs.data.selectedItems = this.filterItemsIfOperationIsCultureSpecific(bulkArgs, action);
                    }

                    if (this.shouldPerformBulkDelete(action)) {
                        const operationData: OperationData = {
                            data: {
                                action: OPERATION_NAMES.delete,
                                actionParameters: {
                                    actionName: bulkArgs.data.deleteAllTranslations ? DELETE_ALL_TRANSLATIONS : DELETE_SINGLE_TRANSLATIONS,
                                    itemIds: selectedItems.map(i => i.data.Id).join(stringConstants.COMMA)
                                }
                            },
                            culture: bulkArgs.data.entityData.culture,
                            provider: null
                        };

                        return this.dynamicItemStore.service.executeUnboundFunction<any>(`${this.entityData.metadata.setName}/Default.Operation`, operationData);
                    } else {
                        return bulkCommand.execute(bulkArgs);
                    }
                })).subscribe(result => {
                    if (action.name === OPERATION_NAMES.delete && result.failedItemsErrors) {
                        const failedItemsTitles = selectedItems.filter(i => result.failedItemsErrors[i.data.Id] instanceof ParentHasChildrenError);
                        if (failedItemsTitles.length > 0) {
                            const modalSettings = DeleteCommand.getItemCannotBeDeletedModalSettings(failedItemsTitles, { action }, new Subject());
                            this.modalService.openModalConfirmation(this.route, modalSettings, failedItemsTitles[0]);
                        }
                    }

                    let bulkResult: BulkOperationResult = {
                        success: result.success,
                        failedItemsIds: result.failedItemsIds,
                        succeededItemsIds: result.succeededItemsIds
                    };

                    if (this.shouldPerformBulkDelete(action)) {
                        bulkResult = {
                            success: result.Type === OperationActionType.Success,
                            failedItemsIds: result.FailedItemsIds,
                            succeededItemsIds: result.SucceededItemsIds
                        };
                    }

                    this.handleBulkResult(bulkResult, action, wrappedCommand, bulkCommand);
                });
    }

    private filterItemsIfOperationIsCultureSpecific(bulkArgs: ExecutionContext, action: ActionButton): DataItem[] {
        let items: DataItem[] = bulkArgs.data.selectedItems;

        if (this.isActionCultureSpecific(action, bulkArgs)) {
            const filteredItemsByCulture: DataItem[] = [];
            for (let i = 0; i < items.length; i++) {
                const filteredItem = items[i];

                // in case of deleting media Folders we do not have available languages for them,
                // operation is not culture specific but deleteAllTranslations is set to false
                if (filteredItem.data.AvailableLanguages) {
                    if (filteredItem.data.AvailableLanguages.some((l: string) => l === bulkArgs.data.entityData.culture)) {
                        filteredItemsByCulture.push(filteredItem);
                    }
                } else {
                    filteredItemsByCulture.push(filteredItem);
                }

            }

            items = filteredItemsByCulture;
        }

        return items;
    }

    private isActionCultureSpecific(action: ActionButton, bulkArgs?: ExecutionContext): boolean {
        return (action.name === OPERATION_NAMES.delete && !!bulkArgs && bulkArgs.data !== null && bulkArgs.data.deleteAllTranslations === false) ||
            this.getOperationContextParameterValue(action.sourceOperation.ContextParameters, CONTEXT_PARAMETERS.IsCultureSpecific) === "true";
    }

    private handleBulkResult(result: BulkOperationResult, action: ActionButton, wrappedCommand: Command, bulkCommand: BulkCommand) {
        const notificationCommand = <HasNotificationCommand>wrappedCommand;

        if (!notificationCommand.skipNotification) {
            let notificationData: NotificationData;
            if (notificationCommand.getNotification) {
                notificationData = notificationCommand.getNotification(result.succeededItemsIds, result.failedItemsIds, {
                    entityData: this.entityData,
                    action: action
                });
            }

            if (!notificationData) {
                notificationData = bulkCommand.getNotification(result.succeededItemsIds, result.failedItemsIds, {
                    entityData: this.entityData,
                    action: action
                });
            }

            if (notificationData) {
                if (this.notificationFilter) {
                    notificationData.filterParam = this.notificationFilter;
                }

                if (action.name === OPERATION_NAMES.bulkEditProperties) {
                    notificationData.properties.operationName = OPERATION_NAMES.update.toLowerCase();
                }

                this.notificationService.publishNotification(notificationData);
            }
        }

        this.refreshItems.emit();
        this.loading$.next(false);
        this.loadingChange.emit({ isLoading: false, operationName: action.name, operationResult: result });
        this.onClearSelection();
    }

    private shouldPerformBulkDelete(action: ActionButton): boolean {
        let isBulkSupported = false;

        const hasContextParameters = action.sourceOperation && action.sourceOperation.ContextParameters && action.sourceOperation.ContextParameters.length;

        if (hasContextParameters) {
            isBulkSupported = this.getOperationContextParameterValue(action.sourceOperation.ContextParameters, CONTEXT_PARAMETERS.IsBulkSupported) === "true";
        }

        return action.name === OPERATION_NAMES.delete && isBulkSupported;
    }

    private getOperationContextParameterValue(contextParameters: any[], parameterName: string): string {
        let value: string = "false";

        if (contextParameters) {
            const parameter = contextParameters.find(p => p.Name === parameterName);
            if (parameter) {
                value = parameter.Value;
            }
        }

        return value;
    }

    private getWrappedCommand(action: ActionButton): Command {
        let commandToExecute: Command = null;

        // TODO: remove hard-coded values once there is a factory for commands
        // TODO: setting itemSelectionInfo here should be obsolete
        if (action.name === OPERATION_NAMES.publish) {
            commandToExecute = new OperationCommand(this.dynamicItemStore);
        } else if (action.name === OPERATION_NAMES.unpublish) {
            commandToExecute = new UnpublishCommand(this.dynamicItemStore, this.modalService);
        } else if (action.name === OPERATION_NAMES.delete) {
            commandToExecute = new DeleteCommand(this.dynamicItemStore, this.modalService, this.deleteCommandExtender);
        } else if (action.name === OPERATION_NAMES.schedule) {
            commandToExecute = new ScheduleCommand(this.dynamicItemStore, this.modalService);
        } else if (action.link) {
            commandToExecute = new OpenLinkCommand(window, this.zone);
        } else if (action.name === OPERATION_NAMES.template) {
            commandToExecute = new ChangeTemplateCommand(this.modalService, this.dynamicItemStore, this.notificationService);
        } else if (action.name === OPERATION_NAMES.changeOwner) {
            commandToExecute = new ChangeOwnerCommand(this.modalService, this.dynamicItemStore, this.notificationService);
        } else if (action.name === OPERATION_NAMES.moveTaxon) {
            commandToExecute = new MoveTaxonCommand(this.modalService, this.dynamicItemStore, this.window);
            (commandToExecute as MoveTaxonCommand).itemSelectionInfo = this.itemSelectionInfoInternal;
        } else if (action.name === OPERATION_NAMES.mergeTaxon) {
            commandToExecute = new MergeTaxonCommand(this.modalService, this.dynamicItemStore, this.window);
            (commandToExecute as MergeTaxonCommand).itemSelectionInfo = this.itemSelectionInfoInternal;
        } else if (action.name === OPERATION_NAMES.assignTaxons) {
            commandToExecute = new AssignTaxonsCommand(this.modalService, this.dynamicItemStore, this.notificationService, this.notificationFilter, this.metadataParserService);
        } else if (action.name === OPERATION_NAMES.siteSync) {
            commandToExecute = new SiteSyncCommand(this.dynamicItemStore, this.modalService);
        } else if (action.name === OPERATION_NAMES.setCustomExpiration) {
            commandToExecute = new SetCustomExpirationCommand(this.modalService, this.dynamicItemStore, this.notificationFilter, this.notificationService);
        } else if (action.token) {
            commandToExecute = this.injector.get(action.token.type);
        } else {
            const dataItems = Array.from(this.itemSelectionInfoInternal.selectedItems.values()).filter((item) => {
                return this.itemSelectionInfoInternal.excludedItems.indexOf(item.data.Id);
            });
            commandToExecute = this.bulkCommandExtender.tryHandleCommand(this.entityData, action, dataItems, this.notificationFilter, this.itemSelectionInfoInternal);
            if (!commandToExecute) {
                throw new Error(`${action.name} Command not supported`);
            }
        }

        return commandToExecute;
    }

    private getBulkCommandExecutionContext(selectedItems: Array<DataItem>, action: ActionButton): ExecutionContext {
        if (action.link) {
            let link = action.link;
            let selectedItemKeys;
            if (action.name === OPERATION_NAMES.sendForTranslation) {
                selectedItemKeys = selectedItems.filter(item => item.isTranslated).map(i => i.key);
                link += "&hasSelectedItems=true";

                const hasExcludedItems = selectedItemKeys.length < selectedItems.length;
                if (hasExcludedItems) {
                    link += `&hasExcludedItems=${hasExcludedItems}`;
                }
            }

            return {
                model: null,
                data: {
                    link: link,
                    target: SAME_TAB_TARGET,
                    bulk: false,
                    dataForLocalStorage: {
                        key: TRANSLATIONS_LOCAL_STORAGE_KEY,
                        value: JSON.stringify(selectedItemKeys)
                    }
                },
                currentRoute: null
            };
        }

        const data: any = {
            entityData: this.entityData,
            action: action,
            siteData: getRouteDataRecursively(this.route.snapshot, RESOLVE_NAMES.siteDataStore),
            bulk: true,
            selectedItems,
            deselectedItems: Array.from(this.itemSelectionInfoInternal.deselectedItems.values()),
            allItemsSelected: this.itemSelectionInfoInternal.allItemsSelected
        };

        return {
            data,
            currentRoute: this.route,
            model: null
        };
    }

    private setItemSelectionInfo(value: any) {
        if (value) {
            this.itemSelectionInfoInternal = value;
        } else {
            this.itemSelectionInfoInternal = BULK_ITEM_SELECTION_INFO_INITIAL_VALUE;
        }

        this.selectedItemsCount = this.itemSelectionInfoInternal.selectedItems.size;
        this.excludedItemsCount = this.itemSelectionInfoInternal.excludedItems.length;
        if (this.selectedItemsCount === 0) {
            this.onClearSelection();
        }

        if (this.selectedItemsCount === 1) {
            this.bulkDropdownButtonText = SINGLE_OPERATIONS_LABEL;
        } else if (this.selectedItemsCount > 1) {
            this.bulkDropdownButtonText = BULK_OPERATIONS_LABEL;
        }

        if (this.bulkActionMenu) {
            this.bulkActionMenu.reinitialize();
        }

        this.setSelectedItemsCount();
    }

    private setSelectedItemsCount() {
        if (this.itemSelectionInfoInternal.allItemsSelected && this.itemSelectionInfoInternal.deselectedItems.size > 0) {
            // after selecting all items(total) the user decides to deselect some
            this.selectedItemsCount = this.itemsTotalCount - this.itemSelectionInfoInternal.deselectedItems.size;
            this.excludedItemsCount = this.itemSelectionInfoInternal.excludedItems.length;
        }
    }

    private handleKeyboardShortcuts() {
        const keyboardShortcutsSubscription = this.keyboardShortcutsService.addListener(this.operations, COMPONENT_NAMES.BULK_OPERATIONS, true).subscribe((action: KeyboardAction) => {
            if (action && this.selectedItemsCount > 0) {
                switch (action.type) {
                    case KeyboardActionType.Publish:
                    case KeyboardActionType.Unpublish:
                    case KeyboardActionType.Schedule:
                    case KeyboardActionType.Delete:
                        this.triggerKeyboardShortcutAction(action);
                        break;
                }
            }
        });

        this.registerSubscription(keyboardShortcutsSubscription);
    }

    private triggerKeyboardShortcutAction(action: KeyboardAction) {
        if (!action.action) {
            return;
        }

        action.event.preventDefault();

        this.onActionButtonClicked(action.action as ActionButton);
    }
}

export interface BulkItemSelectionInfo extends ItemSelectionInfo {
    allItemsSelected?: boolean;
}
