import { Component, Input, ViewChild, OnInit } from "@angular/core";
import { SidebarComponentData } from "../sidebar-component.repo";
import { ComponentCommunicationService } from "../../../services/component-communication.service";
import { CommunicationEvent } from "../../../events/component-events";
import { ReplaySubject } from "rxjs";
import { hasValue } from "../../../../../utils";
import { trigger, transition, style, animate, query, group } from "@angular/animations";
import { LibrariesNavigationSidebarComponentProps } from "../../../../libraries/sidebars/libraries-navigation/libraries-navigation-sidebar.component";
import { SfDynamicComponentLoaderComponent } from "@progress/sitefinity-component-framework";

export enum SliderDirection {
    left = "left",
    right = "right",
    leftInner = "leftInner",
    rightInner = "rightInner"
}

const rightAnimation = [
    query(".-one,.-two", style({ }), { optional: true }),
    group([
        query(".-one", [style({ transform: "translateX(100%)" }), animate(".5s ease-out", style({ transform: "translateX(0%)" }))], {
            optional: true
        }),
        query(".-two", [style({ transform: "translateX(0%)" }), animate(".5s ease-out", style({ transform: "translateX(-100%)" }))], {
            optional: true
        })
    ])
];

const leftAnimation = [
    query(".-one,.-two", style({ }), { optional: true }),
    group([
        query(".-one", [style({ transform: "translateX(-100%)" }), animate(".5s ease-out", style({ transform: "translateX(0%)" }))], {
            optional: true
        }),
        query(".-two", [style({ transform: "translateX(0%)" }), animate(".5s ease-out", style({ transform: "translateX(100%)" }))], {
            optional: true
        })
    ])
];

interface SidebarSliderInitializedData {
    instance: SidebarSliderComponent;
}

export class SidebarSliderInitialized extends CommunicationEvent<SidebarSliderInitializedData> {
}

export interface SidebarSliderAnimationData {
    slideDirection: SliderDirection;
    componentData: SidebarComponentData;
}

@Component({
    selector: "sf-sidebar-slider",
    templateUrl: "./sidebar-slider.component.html",
    animations: [
        trigger("animateSidebar", [
            transition("* => right", rightAnimation),
            transition("left => right", rightAnimation),
            transition("left => rightInner", rightAnimation),
            transition("right => rightInner", rightAnimation),
            transition("rightInner => right", rightAnimation),
            transition("* => left", leftAnimation),
            transition("right => left", leftAnimation),
            transition("right => leftInner", leftAnimation),
            transition("leftInner => left", leftAnimation),
            transition("left => leftInner", leftAnimation)
            ])]
})
export class SidebarSliderComponent implements OnInit {
    @Input() sliderDirection: SliderDirection;
    @Input() firstWindowComponentData: SidebarComponentData;
    @Input() secondWindowComponentData: SidebarComponentData;
    @ViewChild(SfDynamicComponentLoaderComponent, { static: false }) loader: SfDynamicComponentLoaderComponent;
    animationData$ = new ReplaySubject<SidebarSliderAnimationData>(1);
    windowsZIndexes = {
        firstWindow: 0,
        secondWindow: 0
    };
    firstWindowCssClass: string;
    secondWindowCssClass: string;

    constructor(private eventsService: ComponentCommunicationService) {
        this.eventsService.next(new SidebarSliderInitialized({ instance: this }));
    }

    ngOnInit() {
        this.animationData$.subscribe(animData => {
            const shouldSlideFirstWindow = !hasValue(this.firstWindowComponentData);
            if (shouldSlideFirstWindow) {
                this.firstWindowComponentData = animData.componentData;
                this.windowsZIndexes.firstWindow = 1;
                this.windowsZIndexes.secondWindow = this.windowsZIndexes.firstWindow - 1;
                this.firstWindowCssClass = "-one";
                this.secondWindowCssClass = "-two";
            } else {
                this.secondWindowComponentData = animData.componentData;
                this.windowsZIndexes.secondWindow = 1;
                this.windowsZIndexes.firstWindow = this.windowsZIndexes.secondWindow - 1;
                this.firstWindowCssClass = "-two";
                this.secondWindowCssClass = "-one";
            }

            this.sliderDirection = animData.slideDirection;
        });
    }

    clearOldWindow() {
        const { firstWindow, secondWindow } = this.windowsZIndexes;
        if (firstWindow === secondWindow) {
            return;
        }

        if (firstWindow < secondWindow) {
            this.firstWindowComponentData = null;
        } else {
            this.secondWindowComponentData = null;
        }
    }

    getVisibleWindowComponentDataProps(): LibrariesNavigationSidebarComponentProps {
        const props: LibrariesNavigationSidebarComponentProps = (this.firstWindowComponentData ? this.firstWindowComponentData.properties : this.secondWindowComponentData.properties) as any;
        return props;
    }
}
