import { Injectable } from "@angular/core";
import { DEFAULT_MARKUP_KEY, MarkupSection, SectionTypes, TextSection } from "@progress/sitefinity-component-framework";
import { FIELD_TOOLTIP, VALIDATION_CUSTOM_MSGS, VALIDATION_DECIMAL_PLACES, VALIDATION_MAX_VALUE, VALIDATION_MIN_VALUE, VALIDATION_READONLY, VALIDATION_REGEX, VALIDATION_REQUIRED } from "../../../../../fields/common/common-constants";
import { Rule } from "../../../../../fields/field-settings-base";
import { RelatedDataSettings } from "../../../../../fields/related-data/related-data.settings";
import { isMirrorFieldSettings, MirrorFieldSettings } from "../../../../../fields/short-text/short-text-settings";
import { FieldModel } from "../../../services/field.model";
import { CompositeFieldsProvider, IS_HTML_PROPERTY } from "../../shared/fields-builder/providers/fields-provider";
import { FieldTypes } from "../../shared/fields-builder/services/fields-registry";
import { createFieldModel } from "../../shared/fields.constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { Dictionary, PropertyEditorWidgets } from "../property-editor.constants";
import { ComplexSettings } from "../providers/fields/complex/complex.settings";

import { Properties } from "../providers/fields/field-properties-mapper";
import { PropertyValueParserService } from "./property-value-parser.service";
import { VALIDATOR_NAMES } from "../../../../../fields/common/validators";
import { ContentSettings } from "../providers/fields/content/content.settings";
import { MixedContentValue } from "../providers/fields/content/content-selector.component";
import { PencilButtonSettings, DialogMetadata } from "../../../../../fields/pencil-button/pencil-button-field.component";
import { CREATE_FIELD_LOOK_MAPPER } from "../providers/fields/field-type-mapper";
import { LinkSelectorSettings } from "../../../../../fields/link-selector/link-selector.settings";

const GROUP_FIELD_CLASS = "-group";
const GROUP_FIELD_FIRST_CLASS_MODIFIER = "-first";
const GROUP_FIELD_LAST_CLASS_MODIFIER = "-last";

const FIELD_PROPERTIES_MAPPER: Map<string, string> = new Map<string, string>([
    ["Meta_Description_Description", FIELD_TOOLTIP],
    ["Meta_Placeholder_Text", "placeholder"],
    ["DefaultValue", "default"],
    ["Meta_Choices", "choices"],
    ["Meta_Choice_Choices", "choices"],
    ["Meta_Content_Type", "itemType"],
    ["Meta_MediaItem_ItemType", "itemType"],
    ["Meta_MediaItem_AllowMultipleSelection", "allowMultiple"],
    ["Meta_MediaItem_Standalone", "openPickerWhenEmpty"],
    ["Meta_LengthDependsOn_ExtraRecords", "dependsOnExtraRecords"],
    ["Meta_Mirror_FieldName", "mirroredFieldName"],
    ["Meta_Mirror_FieldProperty", "mirroredFieldProperty"],
    ["Meta_Mirror_EnableMirroring", "enableMirroring"],
    ["Meta_Description_InlineDescription", "inlineDescription"],
    ["Meta_Description_InstructionalNotes", "instructionalNotes"],
    ["Meta_EmptyValues_EmptyValues", "emptyValues"],
    ["Meta_Content_AllowCreate", "Meta_AllowCreate"],
    ["Meta_Content_ForceShouldShowAll", "ForceShouldShowAll"]
]);

const FIELD_VALIDATIONS_MAPPER: Map<string, string> = new Map<string, string>([
    ["Validations_Required", VALIDATION_REQUIRED],
    ["Validations_ReadOnly", VALIDATION_READONLY],
    ["Validations_Regex", VALIDATION_REGEX],
    ["Validations_MaxValue", VALIDATION_MAX_VALUE],
    ["Validations_MinValue", VALIDATION_MIN_VALUE],
    ["Validations_DecimalPlaces", VALIDATION_DECIMAL_PLACES]
]);

const FIELD_ERROR_MSG_MAPPER: Map<string, string> = new Map<string, string>([
    ["Validations_RangeErrorMsg", VALIDATOR_NAMES.VALUE_RANGE],
    ["Validations_RegexErrorMsg", VALIDATOR_NAMES.PATTERN],
    ["Validations_RequiredErrorMsg", VALIDATOR_NAMES.REQUIRED],
    ["Validations_MinLengthErrorMsg", VALIDATOR_NAMES.MIN_LENGTH],
    ["Validations_MaxLengthErrorMsg", VALIDATOR_NAMES.MAX_LENGTH],
    ["Validations_StringLengthErrorMsg", VALIDATOR_NAMES.MAX_LENGTH]
]);

@Injectable({
    providedIn: "root"
})
export class CreateFieldService {
    constructor(
        private fieldsProvider: CompositeFieldsProvider,
        private metadataStore: MetadataStore,
        private propertyValueParserService: PropertyValueParserService) {
    }

    // eslint-disable-next-line complexity
    public createField(fieldType: string, propName: string, fieldValue: string, metadata: any, fieldTitle: string, propType: string, propertiesValues: Dictionary, culture: string, cssClass?: string): FieldModel {
        const entity: any = {
            properties: {
                [propName]: {
                    [VALIDATION_CUSTOM_MSGS]: {}
                }
            }
        };

        const propNameRef = entity.properties[propName];

        if (fieldType === FieldTypes.html)
            propNameRef[IS_HTML_PROPERTY] = true;

        //add properties in the metadata for the field construction
        FIELD_PROPERTIES_MAPPER.forEach((value, key) => {
            if (metadata[Properties].hasOwnProperty(key)) {
                propNameRef[value] = metadata[Properties][key];
            }
        });

        // auto mapping of properties
        const metaKeyword = "Meta_";
        Object.keys(metadata[Properties]).filter(x => x.startsWith(metaKeyword)).forEach(x => {
            propNameRef[x] = metadata[Properties][x];
        });

        propNameRef["typeChildProperties"] = metadata["TypeChildProperties"];

        this.addValidations(metadata, propNameRef);

        if (fieldType === FieldTypes.media) {
            this.setAcceptableFileAndMediaTypes(metadata, propNameRef);
        }

        if (fieldType === FieldTypes.complex) {
            propNameRef[metaKeyword + "Type"] = metadata.Type;
        }

        const fieldTypeBefore = fieldType;

        fieldType = this.changeFieldTypes(fieldType, propNameRef);

        const value = this.propertyValueParserService.parsePropertyToFieldValue(fieldValue, fieldType, metadata);
        const defaultValue = this.propertyValueParserService.parsePropertyToFieldValue(metadata.DefaultValue, fieldType, metadata);

        if (metadata.DefaultValue) {
            entity.properties[propName]["default"] = defaultValue;
        }

        const fieldModel = createFieldModel(
            this.fieldsProvider,
            propType,
            fieldType,
            propName,
            value,
            entity,
            fieldTitle,
            null,
            false,
            cssClass
        );

        if (fieldTypeBefore === FieldTypes.media) {
            let contentType = null;
            switch (propNameRef.itemType) {
                case "images":
                    contentType = "Telerik.Sitefinity.Libraries.Model.Image";
                    break;
                case "videos":
                    contentType = "Telerik.Sitefinity.Libraries.Model.Video";
                    break;
                case "documents":
                    contentType = "Telerik.Sitefinity.Libraries.Model.Document";
                    break;
                default:
                    break;
            }
            (fieldModel.settings as ContentSettings).contentType = contentType;
            (fieldModel.settings as ContentSettings).actAsWrappingMediaField = true;
            (fieldModel.settings as ContentSettings).contentAllowMultipleItemsSelection = propNameRef.allowMultiple;
            (fieldModel.settings as ContentSettings).openPickerWhenEmpty = propNameRef.openPickerWhenEmpty === "True";

            if (fieldModel.value) {
                fieldModel.value = <MixedContentValue>{
                    Content: [
                        {
                            Type: contentType,
                            Variations: [
                                {
                                    Filter: {
                                        Key: "ByIds",
                                        Value: fieldModel.value.Id
                                    },
                                    Source: fieldModel.value.Provider || fieldModel.value.provider
                                }
                            ]
                        }
                    ],
                    ItemIdsOrdered: [fieldModel.value.Id]
                };
            }
        }

        if (propNameRef[VALIDATION_READONLY]) {
            fieldModel.settings.readOnlyMode = true;
        }

        // Do not display field title if its one line checkbox, or complex type rendered in section.
        fieldModel.settings.showTitle = fieldTitle !== "" &&
            fieldType !== FieldTypes.choiceYesNo &&
            (metadata.Type !== "complex" || (metadata.Properties["Meta_TableView_Enabled"] === "True" && metadata["TypeChildProperties"] && metadata["TypeChildProperties"].length <= 5));

        fieldModel.settings.culture = culture;
        // from complex component
        if (fieldModel.selector === FieldTypes.choiceChip) {
            fieldModel.settings.look = "inline sf-txt-base";
        }

        if (fieldType === FieldTypes.relatedData) {
            fieldModel.settings.type = propNameRef.itemType;
            (fieldModel.settings as RelatedDataSettings).allowMultiple = propNameRef.allowMultiple;
            fieldModel.settings.look = "inline";
        }

        if (fieldType === FieldTypes.content) {
            fieldModel.settings.look = !fieldModel.settings.readOnlyMode ? "sf-p-zero sf-ml-xs sf-mb-zero" : "sf-p-zero";
        }

        if (fieldType === FieldTypes.choiceDropDown) {
            fieldModel.settings.defaultValue = defaultValue;
        }

        const fieldLook = CREATE_FIELD_LOOK_MAPPER.get(fieldModel.key);
        if (fieldLook)
            fieldModel.settings.look = fieldLook;

        if (fieldType === FieldTypes.linkSelector) {
            (fieldModel.settings as LinkSelectorSettings).allowMultiple = !!metadata["TypeChildProperties"]?.length;
            (fieldModel.settings as LinkSelectorSettings).valueIsSingleObject = true;
            if (propType === `${PropertyEditorWidgets.FIELD_TYPE_KEY}${PropertyEditorWidgets.CALL_TO_ACTION}` ||
                propType === `${PropertyEditorWidgets.FIELD_TYPE_KEY}${PropertyEditorWidgets.IMAGE}`) {
                const skippedFields = ["styles", "attributes"];
                if (propType === `${PropertyEditorWidgets.FIELD_TYPE_KEY}${PropertyEditorWidgets.IMAGE}`) {
                    skippedFields.push("tooltip");
                }

                (fieldModel.settings as LinkSelectorSettings).skippedFields = skippedFields;
            }
        }

        this.setGroupSettings(fieldModel, fieldType);

        this.populateMetadata(metadata, fieldModel, propertiesValues);
        return fieldModel;
    }

    private addValidations(metadata: any, propNameRef: any) {
        //add valdiation properties in the metadata for the field construction
        FIELD_VALIDATIONS_MAPPER.forEach((value, key) => {
            if (metadata[Properties].hasOwnProperty(key)) {
                propNameRef[value] = metadata[Properties][key];
            }
        });

        //add custom error messages displayed when validatig field
        FIELD_ERROR_MSG_MAPPER.forEach((value, key) => {
            if (metadata[Properties].hasOwnProperty(key)) {
                propNameRef[VALIDATION_CUSTOM_MSGS][value] = metadata[Properties][key];
            }
        });
    }

    private setAcceptableFileAndMediaTypes(metadata: any, propNameRef: any) {
        const mediaEntity = this.metadataStore.getEntity(metadata[Properties]["Meta_MediaItem_ItemType"]);
        // Upload size validations are made on the server.
        propNameRef["acceptableMediaTypes"] = mediaEntity["acceptableMediaTypes"];
        propNameRef["acceptableFileTypes"] = mediaEntity["acceptableFileTypes"];
    }

    private setGroupSettings(fieldModel: FieldModel, fieldType: string) {
        const dynamicSettings = fieldModel.settings as any;
        if (fieldType === FieldTypes.choiceYesNo && dynamicSettings.groupName) {
            if (dynamicSettings.groupFirst) {
                fieldModel.cssClass = `${GROUP_FIELD_CLASS} ${GROUP_FIELD_FIRST_CLASS_MODIFIER} -sf-pt-3xs`;
                dynamicSettings.optionName = fieldModel.settings.title;
                fieldModel.settings.showTitle = true;
                fieldModel.settings.title = dynamicSettings.groupName;
            } else if (dynamicSettings.groupLast) {
                fieldModel.cssClass = `${GROUP_FIELD_CLASS} ${GROUP_FIELD_LAST_CLASS_MODIFIER} -sf-pb-2xs -sf-mb-4xs`;
            } else {
                fieldModel.cssClass = GROUP_FIELD_CLASS;
            }
        }
    }

    private populateMetadata(metadata: any, fieldModel: FieldModel, propertiesValues: Dictionary) {
        const rule = metadata.Properties["Meta_ConditionalVisibility_Condition"];
        if (rule) {
            fieldModel.settings.conditionalRule = JSON.parse(rule) as Rule;
        }

        const dialogData = metadata.Properties["Meta_Dialog_Data"];
        if (dialogData) {
            (fieldModel.settings as PencilButtonSettings).dialogData = JSON.parse(dialogData) as DialogMetadata;
        }

        const hidden = metadata.Properties["Meta_DisplaySettings_Hide"];
        if (hidden) {
            fieldModel.settings.isVisible = hidden === "False";
        }

        const hideContent = metadata.Properties["Meta_DisplaySettings_HideContent"];
        if (hideContent) {
            fieldModel.settings.isVisibleContent = hideContent === "True";
        }

        if (isMirrorFieldSettings(fieldModel.settings) && metadata.Properties) {
            const mirrorFieldSettings = fieldModel.settings as MirrorFieldSettings;
            mirrorFieldSettings.mirroredFieldName = metadata.Properties["Meta_Mirror_FieldName"];
            mirrorFieldSettings.mirroredFieldProperty = metadata.Properties["Meta_Mirror_FieldProperty"] || mirrorFieldSettings["Meta_Mirror_FieldProperty"];
            mirrorFieldSettings.enableMirroring = metadata.Properties["Meta_Mirror_EnableMirroring"] === "True";
        }

        const tooltip = metadata[Properties]["Meta_Description_Description"];
        if (tooltip) {
            try {
                const parsedSections = JSON.parse(tooltip);
                fieldModel.settings.tooltipModels = new Map<string, MarkupSection[]>([[DEFAULT_MARKUP_KEY, parsedSections]]);
            } catch {
                const section: TextSection = { Type: SectionTypes.Text, Chunks: [{ Value: tooltip, Presentation: [] }] };
                fieldModel.settings.tooltipModels = new Map<string, MarkupSection[]>([[DEFAULT_MARKUP_KEY, [section]]]);
            }
        }

        const dependsOnProperty = metadata[Properties]["Meta_LengthDependsOn_PropertyName"];
        if (dependsOnProperty) {
            const dependsOnPropValue = propertiesValues[dependsOnProperty];
            const dependsOnLength = parseInt(dependsOnPropValue);
            (fieldModel.settings as ComplexSettings).dependsOnLength = dependsOnLength;
        }

        const readonlyProperty = metadata[Properties]["Validations_Readonly"];
        if (readonlyProperty && readonlyProperty === "True") {
            fieldModel.settings.readOnlyMode = true;
        }
    }

    private changeFieldTypes(fieldType: string, propNameRef: any): string {
        if (fieldType === FieldTypes.content && !propNameRef.itemType) {
            fieldType = FieldTypes.contentAll;
        }

        if (fieldType === FieldTypes.media) {
            fieldType = FieldTypes.content;
        }

        return fieldType;
    }
}
