import { Component, ElementRef, Inject, OnDestroy, OnInit, ViewChild } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { of, ReplaySubject, Subject } from "rxjs";
import { debounceTime, distinctUntilChanged, first, take } from "rxjs/operators";
import { cloneObject, getFormattedTypeName, guid } from "../../utils";
import { BackendTweaksStore } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { SelectorConstants } from "../html/selector-constants";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";
import { FieldsGeneratorService } from "../shared/services/fields-generator.service";
import { MediaEntity, MetadataStore } from "../shared/services/metadata/meta-data.store";
import {
    Button,
    CancelButton,
    ClickResult,
    CloseModalCallback,
    ConfirmButton,
    DialogData,
    ModalWindowService
} from "../shared/services/modal-window.service";
import { FilePickerViewMode } from "./file-picker-view-mode";
import { MESSAGES } from "./file-picker.messages";
import { FileSelectComponent } from "./file-select.component";
import { FileUploadComponent } from "./file-upload.component";
import { MediaValidationHelper } from "./media-validation-helper";
import { LibraryStore } from "./services/library.store";
import { SHOW_BUTTONS } from "../shared/components/modal-window/modal-window.component";
import { ANY_SITE_SOURCE_PROVIDER, stringConstants } from "../../common-constants";
import { FileUploadProgressComponent } from "./file-upload-progress.component";
import { DataItem, EntityData } from "../content/dynamic-modules/interfaces";
import { CompositeOperationsProvider } from "../content/dynamic-modules/services/operations/operations-provider";
import { OperationsData, OperationsTarget } from "../content/dynamic-modules/services/operations/interfaces";
import { OPERATION_NAMES, OPERATION_TITLES } from "../shared/components/action-menu/operation.model";
import { ToolbarComponent } from "../content/dynamic-modules/components/dialog/toolbar.component";
import { BulkComponent } from "../shared/components/bulk/bulk.component";
import { MediaHelpers } from "./services/media.helpers";
import { HierarchicalLibrariesService } from "./services/hierarchical-libraries.service";
import { FILE_UPLOAD_PROGRESS, FILE_UPLOAD_RETRY_COMMAND } from "./file-picker.constants";
import { CompositeDataExtender } from "../shared/services/data-extensions/data.extender";
import { LongRunningTasksService } from "../content/dynamic-modules/services/long-running-tasks.service";
import { KeyboardAction, KeyboardShortcutsService } from "../../services/keyboard-shortcuts.service";
import { COMPONENT_NAMES } from "../content/constants";
import { KeyboardActionType } from "../../services/keyboard-shortcuts.constants";
import { BackgroundTaskType } from "../content/dynamic-modules/services/background-task.types";
import { WINDOW_TOKEN } from "../../window.provider";
import { ImportDamAssetsResult, MediaService } from "./services/media.service";
import { NotificationService, NOTIFICATION_SERVICE } from "../shared/services/notification/notification.service";
import { DamAsset } from "./dam/dam-provider-base";
import { FileWrapper } from "./media-handlers/media-handler.provider";
import { AppStore } from "../../services/store/app-store";
import { MEDIA_SELECTORS } from "../../services/store/selectors/selectors.media";

export const FILE_PICKER = "filePicker";
export const FILE_SELECT = "fileSelect";

const SEARCH_DEBOUNCE_TIME = 150;

@Component({
    templateUrl: "./file-picker.component.html",
    styleUrls: ["./file-picker.component.scss"],
    providers: [
        // Every media type requires a different instance
        LibraryStore
    ]
})
export class FilePickerComponent extends SfRxBase implements OnInit, CloseModalCallback, OnDestroy {
    @ViewChild("fileInput") fileInput: ElementRef<HTMLInputElement>;

    value: DataItem[] = [];
    multiple = false;
    isDragOver = false;
    allowCreate = true;
    skipUpload = false; // will not actually upload the file
    showTranslations = false;
    recentLibraries = new ReplaySubject<DataItem[]>(1);
    selectedFilesForUpload = Array<File>();
    acceptableMediaTypes = Array<string>();
    useLiveData: boolean;

    name: string;
    mediaEntityData: EntityData;
    initialViewMode: FilePickerViewMode;
    fields: any;
    acceptFileTypes: string;
    acceptableFileTypes: Array<string>;
    maxSize: number;
    searchTerm: string;
    messageTemplates: any;
    messages: any;
    formattedTypeName: string;
    mediaFilterEnabled: boolean;
    fileUploadErrorMessages: string[];
    showProviderSelector: boolean;
    entitySetName: string;
    sourceLibraryId: string = null;
    targetLibraryId: string = null;
    useOnlySelectMode?: boolean = false;
    showSelectLink: boolean = true;
    createMedia: boolean = false;
    isNonTranslatedSelectable: boolean = true;
    getImageAfterUpload: boolean = true;
    selectedLibrary: DataItem;
    uniqueId: string = guid();
    fileUpload = `${this.uniqueId}_fileUpload`;
    showParentLibrary: boolean = true;
    enableDamPicker: boolean = false;
    showDamPicker: boolean = false;
    damNotificationFilter: string = null;
    isReplaceFile: boolean;
    importAssetsOnSelect: boolean = true;

    private defaultFieldName: string;
    private _closeModalCallback: (data: any) => void;
    private mediaEntity: MediaEntity;
    private recentLibraries$ = new Subject<DataItem[]>();

    constructor(
        private metadataStore: MetadataStore,
        private fieldsGeneratorService: FieldsGeneratorService,
        private backendTweaksStore: BackendTweaksStore,
        private store: LibraryStore,
        private route: ActivatedRoute,
        private modalService: ModalWindowService,
        private mediaValidationHelper: MediaValidationHelper,
        private operationsProvider: CompositeOperationsProvider,
        private hierarchicalLibrariesService: HierarchicalLibrariesService,
        private longRunningTasksService: LongRunningTasksService,
        private keyboardShortcutsService: KeyboardShortcutsService,
        private compositeDataExtender: CompositeDataExtender,
        @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService,
        @Inject(WINDOW_TOKEN) private window: Window,
        private mediaService: MediaService,
        private appStore: AppStore) {
        super();
    }

    ngOnInit() {
        this.handleKeyboardShortcuts();
        this.mediaEntity = this.mediaEntityData.metadata as MediaEntity;
        this.toggleShowSelectLink();
        const recentLibrariesSubscription = this.recentLibraries$.subscribe(libraries => {
            const entityData: EntityData = {
                culture: this.mediaEntityData.culture,
                metadata: this.mediaEntityData.metadata,
                provider: this.mediaEntityData.metadata.selectedProvider || this.mediaEntityData.provider
            };

            this.longRunningTasksService.getTasks(entityData).subscribe(tasks => {
                    const processedLibraries = this.compositeDataExtender.enhanceDataItems(this.mediaEntityData, libraries, {
                    isSelectionDisabled: true,
                    inactive: true,
                    tooltip: msg => msg
                }, { tasks, whiteListedTasks: [BackgroundTaskType.RegenerateThumbnails] });
                this.recentLibraries.next(processedLibraries.filter(l => !l.data.inactive).slice(0, 5));
            });
        });
        this.registerSubscription(recentLibrariesSubscription);

        const typeMetadata = this.metadataStore.getValue().entities[this.mediaEntityData.metadata.setName];
        this.mediaFilterEnabled = this.mediaEntity.mediaFilterEnabled;
        this.acceptableMediaTypes = this.mediaEntity.acceptableMediaTypes;
        this.acceptableFileTypes = this.mediaEntity.acceptableFileTypes;
        this.acceptFileTypes = this.mediaValidationHelper.getAcceptableFileTypes(this.acceptableFileTypes);
        this.maxSize = this.mediaEntity.maxSize;
        this.store.getFoldersAndContent(this.mediaEntityData, null, 0);
        this.fields = this.fieldsGeneratorService.generateFieldModels(typeMetadata, this.mediaEntityData.metadata.setName, this.backendTweaksStore, null);
        this.defaultFieldName = this.metadataStore.getValue().entities[this.mediaEntityData.metadata.setName].defaultFieldName;
        this.messages = this.multiple ? MESSAGES.multiple : MESSAGES.single;
        this.formattedTypeName = this.formattedTypeName ? this.formattedTypeName : getFormattedTypeName({ plural: this.mediaEntityData.metadata.setName, singular: this.mediaEntityData.metadata.singularName.toLowerCase() }, this.multiple, true);

        if (this.enableDamPicker) {
            this.showDamPicker = this.mediaEntityData.metadata.isDamEnabled;
        }

        if (!this.showDamPicker) {
            this.selectExistingOnSelectViewMode();
        }
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.keyboardShortcutsService.removeListener(COMPONENT_NAMES.FILE_PICKER);
    }

    setCloseModalCallback(closeModalCallback: (data: any) => void): void {
        this._closeModalCallback = closeModalCallback;
    }

    onUploadFiles(files: FileList) {
        if (this.skipUpload) {
            this.onDone([files[0]]);
            return;
        }

        const $selectedLibrary  = new ReplaySubject<DataItem>();

        if (this.selectedLibrary) {
            this.hierarchicalLibrariesService.getItemTaxa([this.selectedLibrary.key], this.mediaEntityData, null, true).subscribe((response) => {
                $selectedLibrary.next(response.dataItems.length > 0 ? response.dataItems[0] : null);
            });
        } else {
            $selectedLibrary.next(this.selectedLibrary);
        }

        if (this.mediaEntityData.provider === ANY_SITE_SOURCE_PROVIDER) {
            this.mediaEntityData = {
                metadata: this.mediaEntityData.metadata,
                culture: this.mediaEntityData.culture,
                provider: stringConstants.EMPTY_STRING
            };
        }

        this.store.getFoldersByParentId(this.mediaEntityData, this.targetLibraryId, 10, true, true, undefined, undefined, true).subscribe(libraries => {
            this.recentLibraries$.next(libraries);
        });

        const isValid = this.mediaValidationHelper.validate(this.mediaEntityData.metadata as MediaEntity, Array.from(files), false);
        this.fileUploadErrorMessages = this.mediaValidationHelper.getErrorMessages();

        if (!isValid) {
            return;
        }

        $selectedLibrary.subscribe((selectedLibrary) => {
            const buttons: Button[] = [];

            if (this.createMedia) {
                buttons.push(
                    new CancelButton(SelectorConstants.DISCARD)
                );
            } else {
                buttons.push(
                    new ConfirmButton(this.multiple ? MESSAGES.multiple.use.select(this.mediaEntityData.metadata.setName) : MESSAGES.single.use.select(this.mediaEntityData.metadata.singularName.toLowerCase())),
                    new CancelButton(SelectorConstants.DISCARD)
                );
            }

            const componentData: ComponentData = {
                type: FileUploadComponent,
                afterComponentInit: (fileUploadComponent: FileUploadComponent) => {
                    fileUploadComponent.multiple = this.multiple;
                    fileUploadComponent.mediaEntityData = this.mediaEntityData;
                    fileUploadComponent.fields = this.fields;
                    fileUploadComponent.libraries = this.recentLibraries.asObservable();
                    fileUploadComponent.targetLibraryId = this.targetLibraryId;
                    fileUploadComponent.selectedLibrary = selectedLibrary ? cloneObject(selectedLibrary.data) : null;
                    fileUploadComponent.initializeLibraries = !(this.createMedia && this.selectedLibrary);
                    fileUploadComponent.selectedFiles = Array.from(files);
                    fileUploadComponent.defaultFieldName = this.defaultFieldName;
                    fileUploadComponent.showProviderSelector = this.showProviderSelector;
                    fileUploadComponent.allowCreate = MediaHelpers.isMediaEntity(this.mediaEntityData);

                    this.registerSubscription(fileUploadComponent.search.pipe(
                        debounceTime(SEARCH_DEBOUNCE_TIME),
                        distinctUntilChanged())
                        .subscribe(searchTerm => {
                            const term = searchTerm || stringConstants.EMPTY_STRING;
                            this.store.getFoldersByParentId(this.mediaEntityData, this.targetLibraryId, 10, true, true, term.trim(), undefined, true).subscribe(libraries => {
                                this.recentLibraries$.next(libraries);
                            });
                        })
                    );

                    this.registerSubscription(fileUploadComponent.selectedProvider.pipe(
                        distinctUntilChanged())
                        .subscribe(provider => {
                            this.mediaEntityData.metadata.selectedProvider = provider;
                            this.store.getFoldersByParentId(this.mediaEntityData, this.targetLibraryId, 10, true, true, undefined, undefined, true).subscribe(libraries => {
                                    this.recentLibraries$.next(libraries);
                                });
                        })
                    );

                    fileUploadComponent.libraries
                        .pipe(first())
                        .subscribe(() => {
                            this.modalService.sendCommand(this.fileUpload, {
                                name: SHOW_BUTTONS,
                                data: true
                            });
                        });
                }
            };

            const doneDialogCallback = (result) => {
                if (result.data && result.data.data) {
                    const component: FileUploadComponent = result.component instanceof FileUploadComponent ? result.component : result.component.parentComponent;
                    if (component.parentId || component.folderId) {
                        const files = component.getFilesForUpload();

                        if (!this.multiple) {
                            this.mediaService.clearUploads();
                        }

                        // Be consistent with old UI and skip workflow when uploading related media items.
                        this.store.uploadFiles(this.mediaEntityData, this.name, files, component.parentId, component.folderId, true, OPERATION_NAMES.uploadPublished , this.getImageAfterUpload);
                    }
                }

                this.onDone();
            };

            // when creating an media item from media grid
            const doneDialogCallbackForLifecycleMedia = (result) => {
                if (result.data && result.data.data) {
                    const component: FileUploadComponent = result.component instanceof FileUploadComponent ? result.component : result.component.parentComponent;
                    if (component.parentId || component.folderId) {
                        const files = component.getFilesForUpload();

                        if (!this.multiple) {
                            this.mediaService.clearUploads();
                        }

                        // TODO: check if uploading properly with workflow
                        const clickResult = result.component instanceof BulkComponent ? result.data.data : result.data as ClickResult;
                        this.store.uploadFiles(this.mediaEntityData, this.name, files, component.parentId, component.folderId, false, clickResult.data, this.getImageAfterUpload);
                        this.displayFileUploadProgress(this.appStore.pipe(MEDIA_SELECTORS.uploadsData), component);
                    }
                } else {
                    this.onDone();
                }
            };

            const dialogData = new DialogData(
                componentData,
                this.createMedia ? doneDialogCallbackForLifecycleMedia : doneDialogCallback,
                buttons,
                null,
                this.multiple ? "-sf-mt-xl" : null);

            dialogData.toolbarData = this.generatedFileUploadToolbarData();

            dialogData.showButtonsOnInit = false;

            if (this.createMedia) {
                const provider = this.mediaEntityData.metadata.selectedProvider || this.mediaEntityData.provider === ANY_SITE_SOURCE_PROVIDER ? null : this.mediaEntityData.provider;
                const operationsDataItem = DataItem.from(null, this.mediaEntityData.metadata, provider, this.mediaEntityData.culture );
                const operationsTarget = OperationsTarget.Create;
                const operationsData = new OperationsData(operationsDataItem, operationsTarget, selectedLibrary, { origin: this.window.location.href });
                const operations = this.operationsProvider.getOperations(operationsData);
                operations.subscribe(operationsResult => {
                    if (this.useLiveData) {
                        operationsResult = operationsResult.filter(x => x.Name !== OPERATION_NAMES.uploadDraft);
                    }

                    const operationsButtons = operationsResult.map(op => {
                        let css = "large";
                        let title = op.Title;
                        if (op.Name === OPERATION_NAMES.upload || op.Name === OPERATION_NAMES.uploadPublished) {
                            css = "action large";
                            if (op.Title === OPERATION_TITLES.publish) {
                                title = OPERATION_TITLES.uploadAndPublish;
                            }
                        }

                        return new ConfirmButton(title, (data) => {
                            const component: FileUploadComponent = data.component instanceof FileUploadComponent ? data.component : data.component.parentComponent;
                            if (!component.parentId) {
                                component.errorMessage = "Select a parent library";
                                return <ClickResult>{
                                    data: op.Name,
                                    hasErrors: true,
                                    isSuccessful: false
                                };
                            } else if (data.component.files.some(f => f.errors && f.errors.length)) {
                                return  <ClickResult>{
                                    data: op.Name,
                                    hasErrors: true,
                                    isSuccessful: false
                                };
                            }
                            return <ClickResult>{
                                data: op.Name,
                                hasErrors: false,
                                isSuccessful: true
                            };
                        }, css, op.Name);
                    });
                    dialogData.buttons = operationsButtons.concat(buttons);
                    this.displayDialog(dialogData, this.fileUpload);
                });
            } else {
                this.displayDialog(dialogData, this.fileUpload);
            }
        });
    }

    displayDialog(dialogData: DialogData, mapping: string) {
        this.modalService.setMapping(dialogData, mapping);
        this.modalService.open(this.route, mapping);
    }

    displayFileUploadProgress(files: any, component: FileUploadComponent) {
        const componentData: ComponentData = {
            type: FileUploadProgressComponent,
            properties: {
                uploadingFiles: files,
                mediaEntityData: component.mediaEntityData,
                selectedLibraries: component.selectedLibraries
            }
        };
        const dialogData = new DialogData(
            componentData,
            () => {
                this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe( uploadInfo => {
                    const uploads = uploadInfo.items.map(x => x.upload.result);
                    this.mediaService.emptyUploads();

                    this.onDone(uploads);
                });
            },
            [new CancelButton(SelectorConstants.CLOSE)],
            null,
            "-sf-mt-xl"
        );

        dialogData.toolbarData = this.generatedFileUploadToolbarData();
        dialogData.showButtonsOnInit = false;
        dialogData.isModalClosable = false;
        dialogData.stickWithDelay = false;

        this.modalService.setMapping(dialogData, FILE_UPLOAD_PROGRESS);
        this.modalService.open(this.route, FILE_UPLOAD_PROGRESS);
        const commands = this.modalService.getCommands(FILE_UPLOAD_PROGRESS);
        commands.subscribe(c => {
            if (c.name === FILE_UPLOAD_RETRY_COMMAND) {
                this.mediaService.retryUpload(this.mediaEntityData, c.data);
            }
        });
    }

    onDone(files?: any[]) {
        if (files) {
            files = this.multiple ? files : files[0];
        }

        if (this._closeModalCallback) {
            this._closeModalCallback(files);
        }
    }

    onSelectExisting() {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const componentData: ComponentData = {
            type: FileSelectComponent,
            properties: {
                formattedTypeName: this.formattedTypeName
            },
            afterComponentInit: (component: FileSelectComponent) => {
                component.multiple = this.multiple;
                component.mediaEntityData = this.mediaEntityData;
                component.parentLibraryId = this.sourceLibraryId;
                component.currentLibraryId = this.sourceLibraryId;
                component.uploadEnabled = !this.useOnlySelectMode;
                component.mediaFilterEnabled = this.mediaFilterEnabled;
                component.acceptableMediaTypes = this.acceptableMediaTypes;
                component.acceptableFileTypes = this.acceptableFileTypes;
                component.maxSize = this.maxSize;
                component.useLiveData = this.useLiveData;
                component.value = this.value;
                component.store = this.store;
                component.allowCreate = this.allowCreate;
                component.showProviderSelector = this.showProviderSelector;
                component.isNonTranslatedSelectable = this.isNonTranslatedSelectable;
                component.showTranslations = this.showTranslations;
                component.showParentLibrary = this.showParentLibrary;

                component.onUploadFiles.pipe(
                    first())
                    .subscribe(files => this.onUploadFiles(files));
            }
        };

        const dialogData = new DialogData(componentData, (result) => {
            const component: any = result.component;
            let files: any[];
            if (result.data && result.data.data === true && component instanceof FileSelectComponent) {
                files = component.value;
                component.fromUpload = false;
            } else if (result.data && result.data instanceof File) {
                files = [result.data];
                if (component instanceof FileSelectComponent) {
                    component.fromUpload = true;
                }
            }

            if (result.data && component instanceof FileUploadProgressComponent) {
                files = this.multiple ? result.data : [result.data];
            }

            this.onDone(files);
        }, buttons, null, "-bottom");

        dialogData.showButtonsOnInit = false;

        this.modalService.setMapping(dialogData, FILE_SELECT);
        this.modalService.open(this.route, FILE_SELECT);
    }

    onDrop(event: any) {
        event.preventDefault();

        this.isDragOver = false;

        this.onUploadFiles(event.dataTransfer.files);
    }

    onDragEnter(event: Event) {
        event.preventDefault();

        this.isDragOver = true;
    }

    onDragLeave(event: MouseEvent) {
        event.preventDefault();

        const fromElement: HTMLElement | null = <HTMLElement>(event as any).fromElement || <HTMLElement>event.target;
        const currentElement: HTMLElement | null = <HTMLElement>event.currentTarget;

        if (this.isChildByCssSelector(fromElement, currentElement)) {
            return;
        }
        this.isDragOver = false;
    }

    toggleShowSelectLink(): void {
        this.showSelectLink = this.initialViewMode !== FilePickerViewMode.Upload;
    }

    onDamMediaImportComplete(importDamAssetsResult: ImportDamAssetsResult) {
        const assets = importDamAssetsResult.dataItems;
        let files = assets;

        // when multiple is enabled we add selected items from the dialog to current selection because in DAM widgets
        // we cannot pre-select items that are already added
        if (this.multiple) {
            files = this.value ?? [];
            assets.forEach(dataItem => {
                if (!files.find(a => dataItem.key === a.key)) {
                    files.push(dataItem);
                }
            });
        } else {
            this.value = files;
        }

        if (importDamAssetsResult.error) {
            this.notificationService.publishInfiniteError(importDamAssetsResult.error);
        }

        this.onDone(files);
    }

    async onDamMediaSelectComplete(assets: DamAsset[]) {
        const asset = assets[0];
        try {
            const response = await this.fetchResponse(asset.url);
            const blob = await response.blob();
            const file = new FileWrapper([blob], `${asset.title}${asset.extension}`, { type: blob.type }, asset);
            this.onDone([file]);
        } catch (error) {
            this.notificationService.publishInfiniteError(error.message);
            this.onDone();
        }
    }

    onCancelDamMediaSelection(): void {
        this.onDone();
    }

    onDamSelectorLoadingError(): void {
        this.showDamPicker = false;
        this.selectExistingOnSelectViewMode();
    }

    private selectExistingOnSelectViewMode(): void {
        if (this.initialViewMode === FilePickerViewMode.Select) {
            this.onSelectExisting();
        }
    }

    private generatedFileUploadToolbarData() {
        return {
            type: ToolbarComponent,
            properties: {
                header: (this.multiple ? MESSAGES.multiple : MESSAGES.single).title.upload(this.formattedTypeName)
            }
        };
    }

    private isChildByCssSelector (obj: HTMLElement, wrapper: HTMLElement): boolean {
        if (!!obj && !!wrapper && wrapper.contains(obj)) {
            return true;
        }
        return false;
    }

    private handleKeyboardShortcuts() {
        const keyboardShortcutsSubscriptions = this.keyboardShortcutsService.addListener(of(null), COMPONENT_NAMES.FILE_PICKER, true).subscribe((action: KeyboardAction) => {
            if (!action) {
                return;
            }

            switch (action.type) {
                case KeyboardActionType.Create:
                    action.event.preventDefault();
                    this.fileInput.nativeElement.click();
                    break;
            }
        });

        this.registerSubscription(keyboardShortcutsSubscriptions);
    }

    private async fetchResponse(url: string): Promise<Response> {
        try {
            return await fetch(url);
        } catch (error) {
            // when response is missing 'Access-Control-Allow-Origin' header fetch with mode 'no-cors' - opaque request
            // which to ignore CORS policy but still returns the blob
            return await fetch(url, { mode: "no-cors" });
        }
    }
}
