import { Component, Input, OnInit } from "@angular/core";
import { RelativeDatePipe } from "../../pipes/relative-date.pipe";
import { DataContext, DataContextComponent } from "../../models/data-context-component";
import { PAGES_ENTITY_SET_NAME } from "../../../pages/services/page.resolver";
import { Properties } from "../../fields.constants";

export const LAST_UPLOADED_ON = "LastUploadedOn";

@Component({
    selector: "sf-date-user",
    templateUrl: "./date-and-user.component.html"
})
export class DateAndUserComponent implements OnInit, DataContextComponent {
    @Input() public context: DataContext;

    public date: string;

    public user: string;

    public showBy: boolean;

    public readonly TOOLTIP_DATE_FORMAT = RelativeDatePipe.FULL_DATE_WEEKDAY;

    ngOnInit() {
        const dataItem = this.context.dataItem;
        const model = this.context.model;
        this.showBy = this.context.dataItem.metadata.setName === PAGES_ENTITY_SET_NAME ? false : true;

        switch (model.name) {
            case LAST_UPLOADED_ON:
                this.date = dataItem.data.LastUploaded;
                this.user = dataItem.data.LastUploadedBy;

                if (dataItem.metadata.hasParent) {
                    this.date = dataItem.data.LastModified;
                    this.user = dataItem.data.LastModifiedBy;
                    break;
                }
            case Properties.PUBLICATION_DATE:
                if (dataItem.data.LastPublished) {
                    this.date = dataItem.data.LastPublished.Date;
                    this.user = dataItem.data.LastPublished.User;
                }
                break;
            case Properties.DATE_CREATED:
                this.date = dataItem.data.DateCreated;
                this.user = dataItem.data.CreatedBy;
                break;
            case Properties.LAST_MODIFIED:
                this.date = dataItem.data.LastModified;
                this.user = dataItem.data.LastModifiedBy;
                break;
            case Properties.START_TIME:
                this.date = dataItem.data.StartTime;
                break;
            case Properties.SUBMITTED_ON:
                this.date = dataItem.data.SubmittedOn;
                this.user = dataItem.data.Username;
                break;
        }
    }
}
