import { CompositeThemeProvider } from "./composite-theme-provider";
import { Injectable } from "@angular/core";
import { CanActivate, Router } from "@angular/router";
import { ROUTE_PATHS } from "../constants/route-paths";

@Injectable()
export class ThemeGuard implements CanActivate {
    constructor(private router: Router, private themeProvider: CompositeThemeProvider) { }

    canActivate() {
        if (this.themeProvider.hasProviders) {
            return true;
        } else {
            this.router.navigate([ROUTE_PATHS.HOME]);
            return false;
        }
    }
}
