import { OperationsData } from "./interfaces";
import { InjectionToken } from "@angular/core";
import { Operation } from "../../../../shared/components/action-menu/operation.model";

export const OPERATIONS_FILTER_TOKEN = new InjectionToken("operations_filter");

/**
 * Provider logic for filtering operations based on some criteria.
 *
 * @ExposedInApi {OperationsFilter} CommandsFilter v1/commands/commands-filter.d.ts
 * @export
 * @interface OperationsFilter
 */
export interface OperationsFilter {
    /**
     * Filters given operations.
     *
     * @param {Operation[]} operations The operations that will be filtered,
     * @param {OperationsData} data The context for the operations.
     * @returns {Operation[]} Filtered operations.
     * @memberof OperationsFilter
     */
    filter(operations: Operation[], data: OperationsData): Operation[];
}
