import { Inject, Injectable, InjectionToken, Injector } from "@angular/core";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ActivatedRoute } from "@angular/router";
import { FileSelectComponent, FILE_SELECT } from "../file-select.component";
import { LibraryStore } from "../services/library.store";
import { MediaSettings } from "../media/media.settings";
import { Button, ConfirmButton, CancelButton, DialogData, ModalWindowService, DeleteButton, ClickData, DialogDataBase, ClickResult } from "../../shared/services/modal-window.service";
import { SelectorConstants } from "../../html/selector-constants";
import { MetadataContainer, MediaEntity, MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { Observable, ReplaySubject, BehaviorSubject, Subject, first } from "rxjs";
import { SelectorOptions, Video } from "./interfaces";
import { CommandModelBase } from "../../shared/commands/command-model-base";
import { Command } from "../../shared/commands/command";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { WINDOW_TOKEN } from "../../../window.provider";
import { FilePickerComponent, FILE_PICKER } from "../file-picker.component";
import { ANY_SITE_SOURCE_PROVIDER, DEFAULT_SITE_SOURCE_PROVIDER } from "../../../common-constants";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { SiteDataStore } from "../../shared/services/metadata/site-data.store";

export const SELECTOR_SERVICE = new InjectionToken("SelectorService");
export const BUTTON_PRIMARY_CATEGORY: string = "primary";
export const BUTTON_CANCEL_CATEGORY: string = "cancel";
export const BUTTON_DELETE_CATEGORY: string = "delete";
export const BUTTON_CATOGORY_OPTIONS: { [key: string]: string } = {
    primary: BUTTON_PRIMARY_CATEGORY,
    cancel: BUTTON_CANCEL_CATEGORY,
    delete: BUTTON_DELETE_CATEGORY
};
export const OPEN_FILE_PICKER =  "openFilePicker";
const FILE_PICKER_CLOSED = "filePickerClosed";
/**
 * Provides API for opening selectors.
 * @ExposedInApi {SelectorService} SelectorService v1/selectors/selector-service.d.ts
 *
 * @export
 * @interface SelectorService
 */
@Injectable()
export class SelectorService {
    constructor(private readonly route: ActivatedRoute,
                private readonly store: LibraryStore,
                private readonly modalService: ModalWindowService,
                private injector: Injector,
                private readonly metadataStore: MetadataStore,
                @Inject(WINDOW_TOKEN) private window: Window,
                private dynamicItemStore: DynamicItemStore,
                private modalWindowService: ModalWindowService,
                private siteDataStore: SiteDataStore) {
                }

    /**
     * Opens library selector for selection videos. The result is returned as observable.
     *
     * @param {SelectorOptions} options Selector configuration options,
     * @returns {Observable<Array<Video>>}  Selected videos.
     * @memberof SelectorService
     */
    openVideoLibrarySelector(options: SelectorOptions): Observable<Array<Video>> {
        const mapCb = x => {
            const video: Video = {
                url: x.data.Url,
                thumbnailUrl: x.data.ThumbnailUrl
            };

            return video;
        };

        return this.openSelector<Video>(options, ENTITY_SET.VIDEOS, mapCb);
    }

    /**
     * Opens library selector for selection images. The result is returned as observable.
     *
     * @param {SelectorOptions} options Selector configuration options,
     * @returns {Observable<Array<string>>}  Selected images ids.
     * @memberof SelectorService
     */
    openImageLibrarySelector(options: SelectorOptions) {
        return this.openSelector<DataItem>(options, ENTITY_SET.IMAGES, x => x);
    }

    openDialog(dialogData: DialogDataBase): Observable<any> {
        const route = this.getCurrentRoute().parent;
        const onDone$ = new Subject<any>();

        const buttons = this.transformCommands(dialogData.commands);

        const newDialogData = new DialogData(dialogData.componentData, (result) => {
            onDone$.next(result);
        }, buttons);

        this.modalService.setMapping(newDialogData, "custom");
        this.modalService.show("custom", route);

        return onDone$.asObservable();
    }

    attachFilePickerEvents() {
        this.window.document.addEventListener(OPEN_FILE_PICKER, (e: CustomEvent) => this.openFilePickerEventHandler(e));
    }

    removeFilePickerEvents() {
        this.window.document.removeEventListener(OPEN_FILE_PICKER, (e: CustomEvent) => this.openFilePickerEventHandler(e));
    }

    private openSelector<TReturn>(options: SelectorOptions, entitySet: string, mapCb: (x: any) => any) {
        const route = this.getCurrentRoute();
        const onDone$ = new ReplaySubject<Array<TReturn>>();
        const entityData: EntityData = {
            metadata: this.metadataStore.getEntity(entitySet),
            provider: null,
            culture: null
        };
        const componentData = this.getComponentData(options.multiple, entityData, route);
        const dialogData = this.getDialogData(componentData, mapCb, onDone$);

        this.modalService.setMapping(dialogData, FILE_SELECT);
        this.modalService.open(route, FILE_SELECT);

        return onDone$.asObservable();
    }

    private transformCommands(commands: CommandModelBase[]): Button[] {
        const buttons: Button[] = [];
        commands.forEach(command => {
            let button: Button;

            switch (command.category) {
                case BUTTON_CATOGORY_OPTIONS.primary:
                    button = new ConfirmButton();
                    break;
                case BUTTON_CATOGORY_OPTIONS.cancel:
                    button = new CancelButton();
                    break;
                case BUTTON_CATOGORY_OPTIONS.delete:
                    button = new DeleteButton();
                    break;
            }

            button.content = command.title;
            if (command.token) {
                const instance = this.injector.get(command.token.type) as Command;

                button.handlers.click = (clickData: ClickData) => {
                    const result = new BehaviorSubject<ClickResult>(new ClickResult(null, false, false));
                    const context: any = {
                        model: command,
                        data: command.token.properties
                    };

                    instance.execute(context).subscribe((data) => {
                        result.next(new ClickResult(data, true, false));
                    });

                    return result.asObservable();
                };
            }

            buttons.push(button);
        });
        return buttons;
    }

    private getComponentData(multiple: boolean, mediaEntityData: EntityData, route: ActivatedRoute) {
        const metaStore: MetadataContainer = route.parent.snapshot.data.metaStore;
        const entity = metaStore.entities[mediaEntityData.metadata.setName];
        const settings = new MediaSettings(entity.displayName, false);
        settings.init(entity.properties);

        const mediaEntityDataClone: EntityData = { metadata: mediaEntityData.metadata.clone(), provider: mediaEntityData.provider, culture: mediaEntityData.culture };
        (mediaEntityDataClone.metadata as MediaEntity).acceptableFileTypes = settings.acceptableFileTypes;
        (mediaEntityDataClone.metadata as MediaEntity).acceptableMediaTypes = settings.acceptableMediaTypes;

        const componentData: ComponentData = {
            type: FileSelectComponent,
            afterComponentInit: (comp: FileSelectComponent) => {
                comp.multiple = multiple;
                comp.mediaEntityData = mediaEntityDataClone;
                comp.parentLibraryId = null;
                comp.currentLibraryId = null;
                comp.mediaFilterEnabled = settings.mediaFilterEnabled;
                comp.acceptableMediaTypes = settings.acceptableMediaTypes;
                comp.acceptableFileTypes = settings.acceptableFileTypes;
                comp.maxSize = (mediaEntityDataClone.metadata as MediaEntity).maxSize;
                comp.value = [];
                comp.store = this.store;
                comp.uploadEnabled = false;
            }
        };

        return componentData;
    }

    private getDialogData(componentData: ComponentData, mapCb: (x: any) => any, onDone$: ReplaySubject<Array<any>>) {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED),
            new CancelButton(SelectorConstants.CANCEL)
        ];
        const dialogData = new DialogData(componentData, (result) => {
            let files = [];
            const isSuccessfulSelection = result.data && result.data.data;

            if (isSuccessfulSelection) {
                files = result.component.value;
            }

            const resultFiles = files.map(mapCb);

            onDone$.next(resultFiles);
        }, buttons, null, "-bottom");

        return dialogData;
    }

    // This is needed because the route that is injected
    // is the root one. It's not the same as the component's
    // route. It's provided by the root injector,
    private getCurrentRoute() {
        let route = this.route;

        while (route.children && route.children.length) {
            route = route.children[0];
        }

        return route;
    }

    private openFilePickerEventHandler(event: CustomEvent) {
        event.preventDefault();

        const route = this.getCurrentRoute();
        const openFilePickerPayload: OpenFilePickerDTO = event.detail;
        const metadata: MediaEntity = route.parent.snapshot.data.metaStore.entities[openFilePickerPayload.mediaType];
        const providers = this.siteDataStore.getAllowedProvidersFromSiteData(metadata.setName, route.parent.snapshot.data.siteDataStore);
        const providersCount = providers.filter(provider => provider != ANY_SITE_SOURCE_PROVIDER && provider != DEFAULT_SITE_SOURCE_PROVIDER).length;
        const componentData: ComponentData = {
            type: FilePickerComponent,
            properties: {
                multiple: false,
                value: openFilePickerPayload.itemId ? [{ data: { Id: openFilePickerPayload.itemId } }] : [],
                allowCreate: true,
                mediaEntityData: {
                    metadata,
                    provider: ANY_SITE_SOURCE_PROVIDER,
                    culture: openFilePickerPayload.culture
                },
                initialViewMode: null,
                showProviderSelector: providersCount > 1,
                enableDamPicker: true,
                createMedia: true,
                useLiveData: true
            }
        };

        const dialogData = new DialogData(componentData, (context) => {
            const item = context.data ? context.data.data || context.data : null;
            if (item) {
                this.dynamicItemStore.getItem({
                    entityData: {
                        metadata,
                        provider: item.Provider,
                        culture: openFilePickerPayload.culture
                    },
                    itemKey: item.Id,
                    additionalQueryParams: {
                        useLiveData: 'true'
                    }
                })
                .pipe(first())
                .subscribe((dataItem: DataItem) => {
                    this.dispatchFilePickerClosedEvent(dataItem, openFilePickerPayload.sender);
                });
            } else {
                this.dispatchFilePickerClosedEvent(null, openFilePickerPayload.sender);
            }
        }, [], "-prompt");

        this.modalWindowService.setMapping(dialogData, FILE_PICKER);
        this.modalWindowService.open(route, FILE_PICKER);
    }

    private dispatchFilePickerClosedEvent(dataItem: DataItem, sender: object) {
        const forceMvcDesignerReloadEvent = new CustomEvent(FILE_PICKER_CLOSED, {
            detail: {
                data: dataItem && dataItem.data ? dataItem.data : null,
                sender
            }
        });
        this.window.document.dispatchEvent(forceMvcDesignerReloadEvent);
    }
}

export interface OpenFilePickerDTO {
    mediaType: string;
    provider: string;
    culture: string;
    itemId: string;
    sender: object;
}
