import { Component, OnInit } from "@angular/core";
import { TaxaComponent } from "./taxa.component";

export const TAXA_COLUMN_BADGES_COUNT = 3;

@Component({
    selector: "sf-taxa-grid",
    templateUrl: "./taxa.grid.component.html"
})
export class TaxaGridComponent extends TaxaComponent implements OnInit {
    visibleTaxa: any[] = [];
    loadMoreBadge: BadgeData;

    public ngOnInit(): void {
        const routeCulture = this.route.snapshot.data.dynamicItems.culture;
        this.settings.culture = routeCulture;
        this.settings.readOnlyMode = true;
        super.ngOnInit();
    }

    onTaxaRetrieved() {
        this.generateTaxaBages();
    }

    /**
     * Handles the click event on a translation.
     * @param item The translation item that was clicked.
     */
    public onClick(item: BadgeData): void {
        // show all taxa
        this.visibleTaxa = this.taxa;

        // hide showMoreButton
        item.isVisible = false;
    }

    private generateTaxaBages(): void {
        // UX requirements are that taxa that are not translated should be visualized as they are in the grid. If these requirements change, remove the following line
        this.taxa.forEach(x => {
            (x as any).isTranslated = true;
        });

        if (this.taxa.length > TAXA_COLUMN_BADGES_COUNT) {
            this.visibleTaxa = this.taxa.slice(0, TAXA_COLUMN_BADGES_COUNT);

            // Add show more button
            const loadMoreCount = this.taxa.length - this.visibleTaxa.length;
            const loadMoreButtonName: string = `+${loadMoreCount}`;
            this.loadMoreBadge = { name: loadMoreButtonName, isVisible: true };
        } else {
            this.visibleTaxa = this.taxa;
            this.loadMoreBadge = { isVisible: false};
        }
    }
}

interface BadgeData {
    name?: string;
    isVisible: boolean;
}
