import { Directive, Output, EventEmitter, Inject, OnDestroy, Input } from "@angular/core";
import { WINDOW_TOKEN } from "./../../../src/app/window.provider";

export const SCROLL_TO_BOTTOM_OFFSET: number = 200;
// As the ScrollEvent is fired multiple times once we want to report the scrolled time once a second(the time is in miliseconds).
export const REPORT_SCROLL_TIME: number = 600;
export const SCROLL_EVENT: string = "scroll";

@Directive({
    selector: "[sfInfiniteScroll]"
})
export class InfiniteScrollerDirective implements OnDestroy {
    @Output() scrolledToBottom = new EventEmitter();
    @Input() scrollOffset = SCROLL_TO_BOTTOM_OFFSET;
    private scrollEventListener: EventListener;
    private previousScrollPosition = 0;

    constructor(@Inject(WINDOW_TOKEN) private window: Window) {
        this.scrollEventListener = evt => this.onWindowScroll(evt);

        this.window.addEventListener(SCROLL_EVENT, this.scrollEventListener);
    }

    ngOnDestroy() {
        this.window.removeEventListener(SCROLL_EVENT, this.scrollEventListener);
    }

    private onWindowScroll(event: any) {
        const currentPosition = window.scrollY + window.innerHeight;
        if (window.scrollY && currentPosition >= (document.body.scrollHeight - this.scrollOffset) &&
                this.previousScrollPosition + REPORT_SCROLL_TIME < event.timeStamp) {
            this.scrolledToBottom.emit();
            this.previousScrollPosition = event.timeStamp;
        }
    }
}
