import { Component, Input, Output, EventEmitter, ViewChild, OnInit } from "@angular/core";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";
import { FormRuleCondition, FormDefinition, Operator, FormField, FormsConstants, FormFieldTypeData } from "../forms.constants";
import { FormFieldTypesParserService } from "../services/form-field-types-parser.service";
import { FieldBase } from "../../../../../fields";
import { stringConstants } from "../../../common-constants";
import { DateTimePickerComponent } from "../../../../../fields/date-time/date-time-picker.component";
import { convertDateToIsoDateTime } from "../../../utils";
import { SfDynamicComponentLoaderComponent } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-condition-create-composite",
    templateUrl: "./condition-create-composite.component.html"
})
export class ConditionCreateCompositeComponent implements OnInit {
    @Input() formDefinition: FormDefinition;
    @Input() formRuleCondition: FormRuleCondition;
    @Input() canDelete: boolean;
    @Output() conditionForDelete: EventEmitter<FormRuleCondition> = new EventEmitter<FormRuleCondition>();

    public formFieldsDropdownSettings: ChoiceSettings;
    public operatorsDropdownSettings: ChoiceSettings;
    public formFieldColumnData: FormFieldTypeData;
    @ViewChild("loader", { static: false }) loader: SfDynamicComponentLoaderComponent;
    private wrappedField: FieldBase;
    private formField: FormField;

    constructor(private typeParserService: FormFieldTypesParserService) {
    }

    ngOnInit() {
        this.initConditionFields();
    }

    public formFieldChanged(value) {
        this.formField = this.formDefinition.Fields.find(f => f.Id === value);
        if (this.formField) {
            const operatorDefaultValue: string = this.formField.Operators.length > 0 ? this.formField.Operators[0].Key : null;

            const operatorDropdownSettings = new ChoiceSettings("operatorsDropdown", false);
            operatorDropdownSettings.choices = this.setOperatorChoices(this.formField.Operators);
            operatorDropdownSettings.defaultValue = operatorDefaultValue;
            this.operatorsDropdownSettings = operatorDropdownSettings;
            this.formRuleCondition.Operator = operatorDefaultValue;
            this.formRuleCondition.Value = this.getDefaultFieldValue();

            this.refreshDynamicComponent(this.formField, operatorDefaultValue, this.formRuleCondition.Value);
        }

        this.formRuleCondition.Id = value;
    }

    public conditionOperatorChanged(value) {
        this.refreshDynamicComponent(this.formField, value, this.formRuleCondition.Value);
        this.formRuleCondition.Operator = value;
    }

    public deleteCondition() {
        this.conditionForDelete.emit(this.formRuleCondition);
    }

    public loaderInit(event) {
        const that = this;
        this.wrappedField = event;
        this.wrappedField.registerOnChange((value: string) => {
            if (that.loader.currentInstance instanceof DateTimePickerComponent) {
                if (value) {
                    const date: Date = new Date(value);
                    that.formRuleCondition.Value = convertDateToIsoDateTime(date, FormsConstants.TIMEZONE_OFFSET);
                } else {
                    that.formRuleCondition.Value = value;
                }
            } else {
                that.formRuleCondition.Value = value;
            }
        });
    }

    private initConditionFields() {
        if (this.formRuleCondition) {
            this.formFieldsDropdownSettings = new ChoiceSettings("formFieldsDropdown", false);
            this.operatorsDropdownSettings = new ChoiceSettings("operatorsDropdown", false);

            this.typeParserService.getConditionFields(this.formDefinition).forEach(formField => {
                this.formFieldsDropdownSettings.choices.push({
                    Value: formField.Id,
                    Name: formField.Title
                });
            });

            this.formField = this.formDefinition.Fields.find(f => f.Id === this.formRuleCondition.Id);
            if (this.formField) {
                this.formFieldsDropdownSettings.defaultValue = this.formRuleCondition.Id;

                this.operatorsDropdownSettings.choices = this.setOperatorChoices(this.formField.Operators);
                this.operatorsDropdownSettings.defaultValue = this.formRuleCondition.Operator;

                this.refreshDynamicComponent(this.formField, this.formRuleCondition.Operator, this.formRuleCondition.Value);
            }
        }
    }

    private refreshDynamicComponent(formField: FormField, operator: string, conditionalValue: string) {
        if (this.loader) {
            this.loader.destroy(this.formFieldColumnData.component);
        }

        if (operator === FormsConstants.CONDITION_OPERATORS.IsFilled || operator === FormsConstants.CONDITION_OPERATORS.IsNotFilled) {
            this.formRuleCondition.Value = stringConstants.EMPTY_STRING;
            this.formFieldColumnData = this.typeParserService.getConditionComponentType(<FormField>{ Type: null }, null);
        } else {
            this.formFieldColumnData = this.typeParserService.getConditionComponentType(formField, conditionalValue);
        }
    }

    private setOperatorChoices(operators: Operator[]) {
        return operators.map(operator => {
            return {
                Name: operator.Value,
                Value: operator.Key
            };
        });
    }

    private getDefaultFieldValue(): string {
        let value: string = stringConstants.EMPTY_STRING;

        if (this.formField && this.formField.Values && this.formField.Values.length > 0) {
            value = this.formField.Values[0].Value;
        }

        return value;
    }
}
