import { of as observableOf, Subject, ReplaySubject, Observable, of, throwError, combineLatest } from "rxjs";

import { debounceTime, finalize, first, map, switchMap } from "rxjs/operators";
import { Input, Component, OnInit, ViewChild, Output, EventEmitter, TemplateRef } from "@angular/core";
import { ScrollService } from "../../src/app/services/scroll.service";
import { Item, TypeNames, ActionItem } from "./../types/types";
import { getFormattedTypeName, cloneObject } from "../../src/app/utils";

import { stringConstants } from "../../src/app/common-constants";
import { TotalCountResult, DataItem } from "../../src/app/modules/content/dynamic-modules/interfaces";
import { ComponentData, SfRxBase, TreeNodeModel } from "@progress/sitefinity-component-framework";
import { Properties } from "../../src/app/modules/shared/fields.constants";
import { SfTabsComponent } from "@progress/sitefinity-component-framework";
import { ChipsConfig } from "../common/chips/chips.component";
import { Selector, SelectorEventArgs } from "@progress/sitefinity-component-framework";
import { TreeWrapperComponent, TreeConfig } from "../tree/tree-wrapper.component";
import { toLoadingState, delayEmission } from "../../src/app/modules/shared/rxjs-extensions";

export const selectedTabName = "selected";
export const SEARCH_DEBOUNCE_TIME = 300;
export const SELECTOR_MAPPING_KEY = "allItems";

const LOAD_MORE_ACTION = "loadMoreChildItems";
const TOTAL_COUNT = "totalCount";
const REQUEST_MORE_LOADING_TIME = 600;
const SELECT_STRING = "Select";
const SELECT_PARENT_STRING = "Select parent";

@Component({
    selector: "sf-show-all",
    templateUrl: "./selector.component.html"
})
export class SelectorComponent extends SfRxBase implements OnInit {
    @ViewChild("mainTree", { static: false }) tree: TreeWrapperComponent;
    @ViewChild("selectedTree", { static: false }) selectedTree: TreeWrapperComponent;
    @ViewChild("mainTabs", { static: false }) mainTabs: SfTabsComponent;
    @Input() value: Item[] = [];
    @Input() allItemsTabType: { new(): Selector; } = null;
    @Input() totalItemsCount: number;
    @Input()
    set selected(value: Item[]) {
        this._selected = value;
        this.expandSelectedItems();
    }
    get selected() {
        return this._selected;
    }
    @Input() serviceAware: ServiceContract;
    @Input() typeNames: TypeNames;
    @Input() treeConfig: TreeConfig = {};
    @Input() defaultField: string;
    @Input() keyField: string;
    @Output() newItemSelected = new EventEmitter<Item>();
    @Input() urlPropertyName: string = "FullUrl";
    @Input() expandPathPair: { key: string, value: string } = { key: "Breadcrumb", value: "Title" };
    @Input() hasStickyBuffer: boolean = true;
    @Input() searchTreeConfig: TreeConfig;
    @Input() isParentSelection: boolean = false;
    @Input() formattedTypeName: string = stringConstants.EMPTY_STRING;
    @Input()
    set loading(value: boolean) {
        this.isTreeLoading = value;
        if (this.tree) {
            this.tree.isLoadingMore = value;
        }
    }

    @Input() targetDataItem?: DataItem;
    @Output() providerChanged = new EventEmitter<string>();
    @Output() tabChange = new EventEmitter<string>();
    @Input() initialTabName: string = null;
    @Input() config: SelectorConfig;
    @Input() allItemsTabLook: string;
    @Input() formCssClass: string = stringConstants.EMPTY_STRING;
    @Input()
    set allItemsTabTypePropertyValues(value: any) {
        this._allItemsTabTypePropertyValues = value;
        this.allItemsTabComponentData = {
            type: this.allItemsTabType,
            properties: this.allItemsTabTypePropertyValues,
            afterComponentInit: (component: Selector) => {
                component.onChange.subscribe((item: SelectorEventArgs) => {
                    if (item !== this.allItemsTabValue) {
                        this.allItemsTabValue = item.tabValue;
                        this.shouldLoadMore = true;
                        this.value = [];
                        this.requestDataOnFirstLoad = true;
                        this.providerChanged.emit(item.tabValue);
                    }
                });
            }
        };
    }
    get allItemsTabTypePropertyValues() {
        return this._allItemsTabTypePropertyValues;
    }
    @Input() titleTemplate: TemplateRef<any>;
    @Input() descriptionTemplate: TemplateRef<any>;
    @Input() notificationText: string;
    @Input() notificationLook: string;
    @Input() title: string;
    @Input() description: string;
    @Input() selectionText: string = SELECT_STRING;
    @Input() itemTemplate: TemplateRef<any>;
    @Input() selectorFilterConfig: SelectorFilterConfig;

    allItemsTabComponentData: ComponentData = {
        type: this.allItemsTabType,
        properties: {}
    };

    mainTreeConfig: TreeConfig = {};
    selectedTreeConfig: TreeConfig;
    selectedSearchTerm: string;
    allSearchTerm: string;

    selectedTab: string = stringConstants.EMPTY_STRING;
    hasCustomTab: boolean;
    emptyIcon: string = "search";
    noItemsCreatedLabel: string;
    noItemsFoundLabel: string;
    search: string;
    hideSticky: boolean = false;

    value$ = new ReplaySubject<TotalCountResult<any[]>>(1);

    private _allItemsTabTypePropertyValues: any[];
    private expandedNodeIds;
    private isTreeInitialized: boolean = false;
    private search$ = new Subject<string>();

    private shouldLoadMore: boolean = true;
    private alreadyExpandedNodes = [];
    private withIndefiniteArticle: boolean = true;
    private isTreeLoading: boolean = false;
    private _selected = [];
    private isCurrentlyExpanding = false;
    private allItemsTabValue: any;
    private requestDataOnFirstLoad: boolean;

    constructor(private scrollService: ScrollService) {
        super();
    }

    ngOnInit() {
        this.mainTreeConfig = cloneObject(this.treeConfig);
        if (this.isParentSelection) {
            this.selectionText = SELECT_PARENT_STRING;
            this.withIndefiniteArticle = false;
        }

        if (!this.formattedTypeName) {
            this.formattedTypeName = getFormattedTypeName(this.typeNames, this.mainTreeConfig.multiSelection, this.withIndefiniteArticle);
        }
        this.title = this.mainTreeConfig.multiSelection ? `All ${this.typeNames.plural}` : stringConstants.EMPTY_STRING;

        if (this.config) {
            this.selectionText = this.config.selectionText;
            this.formattedTypeName = this.config.formattedTypeName;

            if (this.config.mainTabConfig) {
                this.title = this.config.mainTabConfig.title;
            }
        }

        this.shouldLoadMore = this.checkShouldLoadMore();
        this.registerSubscription(this.search$.pipe(
            debounceTime(SEARCH_DEBOUNCE_TIME),
            switchMap(search => combineLatest([this.serviceAware.loadMore({ skip: 0, searchText: search, allItemsTabValue: this.allItemsTabValue, filterValue: this.getFilterValue() }), observableOf(search)])))
            .subscribe(([result, search]) => {
                if (this.searchTreeConfig) {
                    if (search) {
                        this.mainTreeConfig = this.searchTreeConfig;
                    } else {
                        this.mainTreeConfig = cloneObject(this.treeConfig);
                    }
                } else {
                    this.mainTreeConfig.showBreadcrumb = !!search;
                    this.mainTreeConfig.isHierarchical = !search.length;
                }

                if (this.tree) {
                    this.tree.isLoadingMore = false;

                    // Expanded nodes should be cleared, because for each parent the tree
                    // will fetch its children, no matter that they don't match the search query.
                    this.tree.setExpandedNodes({});
                    // We need to clear this internal cache as well when search is triggered
                    // because it does not expand the nodes again when search is cleared to initial state.
                    this.alreadyExpandedNodes = [];
                }

                let items = result;
                if (items && !Array.isArray(items)) {
                    items = (result as TotalCountResult<DataItem[]>).dataItems;
                }
                this.value = items ? items as Item[] : [];
                this.totalItemsCount = result && result[TOTAL_COUNT] ? result[TOTAL_COUNT] : 0;
                this.shouldLoadMore = this.checkShouldLoadMore();

                if (this.tree) {
                    this.tree.updateTreeModel();
                }
            })
        );

        this.registerSubscription(this.value$.subscribe(data => {
            if (this.isTreeLoading) {
                this.value = data.dataItems;

                if (data.totalCount != null) {
                    this.totalItemsCount = data.totalCount;
                }
                this.loading = false;
            }
        }));

        this.selectedTreeConfig = {
            deletion: true,
            status: this.mainTreeConfig ? this.mainTreeConfig.status : null,
            noSelection: true,
            showBreadcrumb: true,
            customComponentOriginatingFeature: this.mainTreeConfig?.customComponentOriginatingFeature,
            customComponentEntitySet: this.mainTreeConfig?.customComponentEntitySet,
            dataProperties: this.mainTreeConfig?.dataProperties
        };

        if (this.config && this.config.customTabConfig && this.config.customTabConfig.componentData) {
            this.hasCustomTab = true;
        }

        if (!this.noItemsCreatedLabel) {
            this.noItemsCreatedLabel = `No ${this.typeNames ? this.typeNames.plural : "items"} found`;
        }

        this.noItemsFoundLabel = `No ${this.typeNames ? this.typeNames.plural : "items"} found`;
    }

    checkShouldLoadMore(): boolean {
       return this.value.length < this.totalItemsCount;
    }

    onNewItemSelected(selectedItem: any) {
        if (selectedItem.data && selectedItem.data.action) {
            this[selectedItem.data.action](selectedItem);
            return;
        }

        this.newItemSelected.emit(selectedItem.data || selectedItem);
        if (!this.mainTreeConfig.multiSelection) {
            this.selected.length = 0;
        }

        const itemData = selectedItem.data || selectedItem;

        const selectedItemIndex: number = this.selected.findIndex((x: Item) => {
            const firstItem = x.data || x;
            const keyProperty = this.keyField || Properties.ID;

            return firstItem[keyProperty] === itemData[keyProperty];
        });

        if (selectedItemIndex < 0) {
            this.selected.push(itemData);
        } else {
            const selectedItem: Item = this.selected[selectedItemIndex].data || this.selected[selectedItemIndex];
            const itemToDeactivate: Item = this.selected.find((item: Item) => {
                const currentItem: Item = item.data || item;

                return currentItem.Id === selectedItem.Id;
            });

            this.selected.splice(selectedItemIndex, 1);
            itemToDeactivate.isActive = false;
        }
    }

    onRemoveNode(removedItem: any) {
        const removedItemIndex = this.selected.indexOf(removedItem.data);
        this.selected.splice(removedItemIndex, 1);
        this.value.forEach(x => {
            if (x.Id === removedItem.data.Id) {
                x.isActive = false;
            }
        });

        if (this.selectedTree) {
            this.selectedTree.updateTreeModel();
        }
    }

    onSelectSelectedTab() {
        this.scrollService.scrollToTop(false);
        this.mainTabs.selectTabByName(selectedTabName);
    }

    onSearchSelected(search) {
        if (this.selectedTree) {
            if (search) {
                this.selected.forEach(x => {
                    const searchedItems = x.Title.toLowerCase().split(" ");
                    const hasMatch = searchedItems.some(item => item.startsWith(search.toLowerCase()));
                    this.selectedTree.setHiddenNodeById(x.Id, !hasMatch);
                });
                this.selectedTree.updateTreeModel();
            } else {
                this.selectedTree.showHiddenNodes();
            }
        }
    }

    onRequestItems(search: string) {
        this.value = [];
        this.tree.isLoadingMore = true;
        this.search$.next(search);
        this.search = search;
    }

    loadChildNodes = (node: any, isLoadingMoreItems: boolean = false): Observable<any> => {
        // TODO: remove when tree version is upgraded
        if (this.alreadyExpandedNodes.indexOf(node.data.Id) > -1 && !isLoadingMoreItems) {
            return of(undefined);
        } else {
            this.alreadyExpandedNodes.push(node.data.Id);
        }

        if (Array.isArray(node.data.children)) {
            this.removeLoadMoreItem(node.data.children);
        }

        const skip = node.data.children ? node.data.children.length : 0;
        const serviceInfo: ServiceInfo = { parentId: node.data.Id, skip, targetDataItem: this.targetDataItem };

        return this.serviceAware.expand(serviceInfo)
            .pipe(map(result => {
                let baseArray = [];
                if (Array.isArray(node.data.children)) {
                    baseArray = node.data.children;
                }

                // TODO: refactor all services to unify logic
                // we do not return a consistent object here
                // some services return just and array of objects and some return a complex object
                let nodes = baseArray;
                let totalCount = 0;

                if (Array.isArray(result)) {
                    nodes = nodes.concat(result);
                } else {
                    nodes = nodes.concat(result.dataItems);
                    totalCount = result.totalCount;
                }

                node.data.hasChildren = nodes.length !== 0;
                node.data.children = nodes;

                if (totalCount > node.data.children.length) {
                    this.addLoadMoreItem(node.data.children.length, node.data.children);
                }
                if (isLoadingMoreItems) {
                    this.tree.updateTreeModel();
                }
                return nodes;
            }));
    }

    onSecondTabClicked(event: any) {
        this.expandedNodeIds = this.tree ? cloneObject(this.tree.getExpandedNodes()) : null;
        this.onSearchSelected(this.selectedSearchTerm);

        this.onTabClicked(event);
    }

    onTabClicked(event: any) {
        if (event) {
            this.selectedTab = event.target.innerText;
            this.tabChange.emit(this.selectedTab);
        }

        this.requestDataOnFirstLoad = true;
    }

    requestMoreItems() {
        this.shouldLoadMore = this.checkShouldLoadMore();

        if (!this.isTreeInitialized || this.tree.isLoadingMore || !this.shouldLoadMore) {
            return;
        }

        this.tree.isLoadingMore = true;

        const length = this.value.length;
        const loadMore: Observable<any[]> = this.serviceAware.loadMore({ skip: length, searchText: this.allSearchTerm, allItemsTabValue: this.allItemsTabValue, filterValue: this.getFilterValue() });

        loadMore.pipe(
                toLoadingState<any>(),
                delayEmission(REQUEST_MORE_LOADING_TIME),
                first(r => !r.isLoading),
                map(result => {
                    // in case the content is pure array
                    let { content } = result;
                    if (content && !Array.isArray(content)) {
                        content = content.dataItems;
                    }

                    if (!content || content.length === 0) {
                        this.shouldLoadMore = false;
                        return;
                    } else {
                        this.shouldLoadMore = true;
                        content.forEach(item => {
                            if (this.value.filter(x => x.Id === item.Id).length === 0) {
                                this.value.push(item);
                            }
                        });

                        this.tree.updateTreeModel();
                    }
                }),
                finalize(() => { this.tree.isLoadingMore = false; this.loading = false; }))
            .subscribe();
    }

    protected loadMoreChildItems(item: any) {
        this.loadChildNodes(item.parent, true).pipe(first()).subscribe();
    }

    protected expandSelectedItems() {
        if (!this.tree || !this.selected || this.isCurrentlyExpanding) {
            return;
        }
        this.isCurrentlyExpanding = true;

        const nodeModel = new TreeNodeModel();
        let pathProperty = this.getPathProperty(this.keyField || this.defaultField);

        this.selected.forEach(item => {
            const anyItem: any = cloneObject(item);

            if (this.mainTreeConfig.isHierarchical && anyItem[this.expandPathPair.key]) {
                const path = this.getPath(anyItem);
                nodeModel.addPath(path);
                pathProperty = this.getPathProperty(this.expandPathPair.value);
            } else {
                nodeModel.addPath([anyItem[pathProperty]]);
            }
        });

        this.tree.expandAndSelect(nodeModel, pathProperty);
        if (this.expandedNodeIds && this.tree.config.isHierarchical) {
            const newExpandedNodes = Object.assign({}, this.tree.getExpandedNodes(), this.expandedNodeIds);
            this.tree.setExpandedNodes(newExpandedNodes);
            this.tree.updateTreeModel();
        }
        this.isTreeInitialized = true;

        if (!this.tree.isLoadingMore && this.isTreeLoading) {
            this.tree.isLoadingMore = this.isTreeLoading;
        }

        this.isCurrentlyExpanding = false;

        if (this.requestDataOnFirstLoad) {
            this.requestMoreItems();
            this.requestDataOnFirstLoad = false;
        }
    }

    getPathProperty(value: string): string {
        if (this.allItemsTabType) {
            return Properties.ID;
        }

        return value;
    }

    onFilterChanged(filterValue) {
        this.selectorFilterConfig.selectedFilterItems = [filterValue];
        this.allSearchTerm = stringConstants.EMPTY_STRING;
        this.onRequestItems(this.allSearchTerm);
    }

    private getPath(item: any): string[] {
        // TODO refactor to use unified logic for the Hierarchical Items.
        // #245886 Currently the Items for Pages and hierarchical taxa holds the logic for its hierrachy in two different properties:
        // Pages -> Breadcrumb which is array of string . This one does not contain the child
        // Categories -> FullUrl which is a string . This one contains the child itself.
        const urlProperty = item[this.expandPathPair.key];
        let path: string[] = [];
        if (Array.isArray(urlProperty)) {
            path = [...urlProperty, item[this.defaultField]];
        } else {
            path = urlProperty.split(stringConstants.FORWARD_SLASH);
            path.splice(0, 1);
        }
        path = path.reverse();
        return path;
    }

    private removeLoadMoreItem(array: Item[]) {
        const loadMoreItemsIndex = array.findIndex(item => {
            const i = item as ActionItem;
            return i && !!i.action;
        });
        if (loadMoreItemsIndex >= 0) {
            array.splice(loadMoreItemsIndex, 1);
        }
    }

    private addLoadMoreItem(index: number, array: Item[]) {
        const loadMoreModel: ActionItem = { Title: "Load more", Id: "loadMoreItem", action: LOAD_MORE_ACTION, isSelectionDisabled: true, isLink: true, icon: "repeat", iconLook: "size-xs color-inherit" };
        array.splice(index, 0, loadMoreModel);
    }

    private getFilterValue() {
        if (this.selectorFilterConfig && this.selectorFilterConfig.selectedFilterItems && this.selectorFilterConfig.selectedFilterItems[0]) {
            return this.selectorFilterConfig.selectedFilterItems[0];
        }

        return null;
    }
}

// TODO: to refactor this, preferably remove this concept
export class ServiceContract {
    constructor(private loadFunc: (info: ServiceInfo) => Observable<any>, private expandFunc?: (info: ServiceInfo) => Observable<any>) { }

    loadMore(info: ServiceInfo): Observable<any> { return this.loadFunc(info); }
    expand(info: ServiceInfo): Observable<any> {
        if (!this.expandFunc) {
            return throwError("Not implemented!");
        }
        return this.expandFunc(info);
    }
}

export interface ServiceInfo {
    take?: number;
    skip?: number;
    searchText?: string;
    parentId?: string;
    taxaId?: string;
    idsToExclude?: string[];
    excludeLevel?: number;
    allItemsTabValue?: any;
    targetDataItem?: DataItem;
    includeParent?: boolean;
    filterValue?: any;
}

export interface MainTabConfig {
    title: string;
}

export interface TabConfig extends MainTabConfig {
    componentData: ComponentData;
    name: string;
}

export interface SelectorConfig {
    formattedTypeName: string;
    selectionText: string;
    mainTabConfig: MainTabConfig;
    customTabConfig?: TabConfig;
}

export interface SelectorFilterConfig {
    filterChipsConfig: ChipsConfig;
    selectedFilterItems: any[];
    filterItems: any[];
    filterLabel: string;
}
