import { Inject, Injectable } from "@angular/core";
import { CanActivate, Router } from "@angular/router";
import { WINDOW_TOKEN } from "../../window.provider";
import { ROUTE_PATHS } from "../../constants/route-paths";

const PAGE_UNSUPPORTED_BROWSER = `/${ROUTE_PATHS.ROOT_PREFIX}/browser-notice`;
const DetectIE10 = "MSIE ";
const DetectIE11 = "Trident/";

@Injectable()
export class UnsupportedBrowserGuard implements CanActivate {

    constructor(private router: Router, @Inject(WINDOW_TOKEN) private windowProvider: Window) {
    }

    canActivate() {
        if (this.isSupportedBrowser()) {
            // all fine
            return true;
        } else {
            // not supported
            this.router.navigate([PAGE_UNSUPPORTED_BROWSER]);
            return false;
        }
    }

    private isSupportedBrowser(): boolean {
        const ua = this.windowProvider.navigator.userAgent;
        return ua.indexOf(DetectIE10) === -1 && ua.indexOf(DetectIE11) === -1;
    }
}
