import {
    Component,
    ViewChild,
    ElementRef,
    ViewEncapsulation,
    OnInit,
    Inject
} from "@angular/core";
import { FieldBase } from "../field-base";
import { stringConstants } from "../../src/app/common-constants";
import { animate, state, style, transition, trigger } from "@angular/animations";
import { ANIMATION_STATES } from "../../src/app/constants/animation-constants";
import { ScrollService } from "../../src/app/services/scroll.service";
import { COLLAPSE_BUTTON_TEXT, EDITOR_COLLAPSE_ANIMATION_SPEED, EDITOR_COLLAPSE_HEIGHT, EDITOR_COLLAPSE_OFFSET_HEIGHT, EXPAND_BUTTON_TEXT, KENDO_EDITOR_LOAD_TIME } from "./editor.component";
import { WINDOW_TOKEN } from "../../src/app/window.provider";

const EDITOR_CSS_CLASS: string = "sf-editor k-editor-inline -read-only";
const LABEL_OFFSET_TOP = 150;

@Component({
    templateUrl: "./editor.readonly.component.html",
    styleUrls: ["./editor.component.scss"],
    encapsulation: ViewEncapsulation.None,
    animations: [
        trigger("slideOpen", [
            state("open", style({ height: "*" })),
            state("closed", style({ height: `${EDITOR_COLLAPSE_HEIGHT}px` })),

            transition("closed <=> open", [
                animate(`${EDITOR_COLLAPSE_ANIMATION_SPEED}ms ease`)
            ]),

            transition(ANIMATION_STATES.ENTER, [
                animate(0)
            ])
        ])
    ]
})
export class EditorReadonlyComponent extends FieldBase implements OnInit {
    @ViewChild("editorHost", { static: true }) editorHostRef: ElementRef;
    cssClass: string = EDITOR_CSS_CLASS;
    initialValue: string;
    isCollapsed: boolean = true;
    isExpandButtonVisible: boolean = false;
    collapseAnimationState: string;
    expandButtonText = EXPAND_BUTTON_TEXT;
    collapseButtonText = COLLAPSE_BUTTON_TEXT;

    constructor(
        private scrollService: ScrollService,
        @Inject(WINDOW_TOKEN) private windowProvider: Window) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.generateCssClassList();

        if (!this.value) {
            this.value = stringConstants.EMPTY_STRING;
        }

        this.editorHostRef.nativeElement.innerHTML = this.value;

        const intervalID = this.windowProvider.setInterval(() => {
            this.checkContentCollapse();
            this.windowProvider.clearInterval(intervalID);
        }, KENDO_EDITOR_LOAD_TIME);
    }

    writeValue(value: string) {
        super.writeValue(value);
        this.initialValue = value;
    }

    private generateCssClassList() {
        if (this.settings.look) {
            this.cssClass += " -" + this.settings.look.split(" ").join(" -");
        }
    }

    checkContentCollapse(collapse: boolean = true) {
        const triggerCollapse = this.editorHostRef.nativeElement.scrollHeight > EDITOR_COLLAPSE_OFFSET_HEIGHT;

        if (triggerCollapse) {
            this.collapseAnimationState = "closed";
            this.isCollapsed = collapse;
        }

        this.isExpandButtonVisible = triggerCollapse;
    }

    toggleExpandButton() {
        this.isCollapsed = !this.isCollapsed;

        if (this.isCollapsed) {
            const editorBoundingClientRect = this.editorHostRef.nativeElement.getBoundingClientRect();
            const scrollTopPoint = document.documentElement.scrollTop - Math.abs(editorBoundingClientRect.top) - LABEL_OFFSET_TOP;
            this.scrollService.scrollToPoint(scrollTopPoint, EDITOR_COLLAPSE_ANIMATION_SPEED);
        } else {
            this.checkContentCollapse(false);
        }
    }
}
