import { ALTERNATIVE_TEXT_KEY, SIZE_ATTRIBUTE, IMAGE_THUMBNAIL_TEXT_KEY, ImageHelper, CUSTOM_THUMBNAIL_KEY, PIXELS_NAME, WIDTH_FIELD_NAME, HEIGHT_FIELD_NAME, IMAGE_MARGINS_KEY, MARGIN_TOP_NAME, MARGIN_RIGHT_NAME, MARGIN_BOTTOM_NAME, MARGIN_LEFT_NAME } from "../../modules/html/tools/insert-image/image-helper";
