import { IMAGE } from "../../modules/shared/services/metadata/files/file-info.service";
import { MediaRecognizerService } from "../../modules/libraries/media/media-recognizer.service";
import { EXTENSIONS, MIME_TYPES } from "../../modules/libraries/services/media.helpers";
import { AppStore } from "../../services/store/app-store";
import { MEDIA_SELECTORS } from "../../services/store/selectors/selectors.media";
import { cloneObject } from "../../utils";
import { ToolbarComponent } from "../../modules/content/dynamic-modules/components/dialog/toolbar.component";
import { LinkModel } from "../../../../fields/link-selector/link-model";
