export const IMAGE_PROPERTIES_DIALOG_TITLE = "Image properties";

@Component({
    selector: "sf-wrapper-html",
    providers: [ImageHelper],
    templateUrl: "./html-wrapper.component.html"
})
export class HtmlWrapperComponent extends FieldBase implements OnInit, OnDestroy, ControlValueAccessor {
    @ViewChild("sfHtml", { static: true }) sfHtml: HtmlComponent;

    public editorSettings: any;

    private uploadSubscription: Subscription;
    private imgUpload: any;
    private uploadingFilesIds: string[] = [];
    private processedPendingItemsCount: number = 0;
    private imageMediaEntity: MediaEntity;
    private imageMediaEntityData: EntityData;
    private selectedTextHtml: string;
    private selectedElement: HTMLAnchorElement;

    constructor(private modalService: ModalWindowService,
                private route: ActivatedRoute,
                private store: LibraryStore,
                private fieldsGeneratorService: FieldsGeneratorService,
                private imageHelper: ImageHelper,
                private metadataStore: MetadataStore,
                private createLinkHelper: CreateLinkHelper,
                private locatableItemsService: LocatableDynamicItemService,
                private siteDataStore: SiteDataStore,
                private mediaRecognizerService: MediaRecognizerService,
                private appStore: AppStore,
                private mediaService: MediaService) {
        super();
    }

    ngOnInit() {
        this.metadataStore.initialize().pipe(first()).subscribe((metadata: MetadataContainer) => {
            this.imageMediaEntity = metadata.entities[ENTITY_SET.IMAGES] as MediaEntity;
            this.imageMediaEntityData = {
                culture: this.sfHtml.settings.culture,
                provider: null,
                metadata: this.imageMediaEntity
            };
        });

        this.uploadSubscription = this.appStore.pipe(MEDIA_SELECTORS.uploadsData).subscribe((info: UploadInfo) => {
            this.onUpload(info.items, info.updatedItem, info.uploadFieldState);
        });
    }

    ngOnDestroy() {
        if (this.uploadSubscription)
            this.uploadSubscription.unsubscribe();
    }

    onFocus() {
        this.sfHtml.onFocus();
    }

    onUpload(jobs: any[], updatedItem: any, uploadFieldState: UploadFieldState) {
        if (jobs) {
            const filteredJobs = jobs.filter(job => this.uploadingFilesIds.find(x => x === job.key) && JSON.stringify(updatedItem) === JSON.stringify(job.upload));
            filteredJobs.forEach((job, jobIndex) => {
                if (job.upload.success || job.upload.failure) {
                    this.processedPendingItemsCount += 1;
                }

                const { success, result } = cloneObject(job.upload);
                const data = result || job.upload;

                this.emitStatus({ type: StatusType.Pending });
                data.imageId = job.key;

                if (success) {
                    // To avoid index being serializes to JSON
                    Object.defineProperty(result, "index", {
                        value: jobIndex,
                        enumerable: false
                    });
                    this.mediaService.removeUploadById(job.upload.id);

                    const imageIndex = this.uploadingFilesIds.indexOf(data.imageId);
                    this.uploadingFilesIds.splice(imageIndex, 1);
                }

                this.sfHtml.onImageInsertViewClosed(data);

                const hasErros = this.validateContent();
                const isHtmlField = uploadFieldState.fieldName && uploadFieldState.fieldName.toLowerCase().includes(this.sfHtml.settings.key.toLowerCase());
                const allItemsAreUploaded = this.processedPendingItemsCount === uploadFieldState.uploadedItemsCount;

                if (!hasErros && isHtmlField && allItemsAreUploaded) {
                    this.emitStatus({ type: StatusType.Done });
                    this.processedPendingItemsCount = 0;
                }
            });
        }
    }

    onValueChanged(value: string) {
        this.validateContent();
    }

    writeValue(value: string) {
        this.sfHtml.writeValue(value, true);
    }

    postProcessValue(value: any) {
        return this.sfHtml.postProcessValue(value);
    }

    emitStatus(status: Status): void {
        super.emitStatus(status);
        this.sfHtml.emitStatus(status);
    }

    set settings(value) {
        this.sfHtml.settings = value;
    }

    registerOnChange(fn: any) {
        this.sfHtml.registerOnChange(fn);
    }

    registerOnTouched(fn: any) {
        this.sfHtml.registerOnTouched(fn);
    }

    onImageInsert(imageId: string) {
        this.uploadingFilesIds.push(imageId);

        if (this.imgUpload) {
            this.mediaService.removeUploadById(this.imgUpload.id);
        }

        const mediaEntityData: EntityData = {
            metadata: this.imageMediaEntityData.metadata.clone(),
            provider: ANY_SITE_SOURCE_PROVIDER,
            culture: this.imageMediaEntityData.culture
        };

        this.siteDataStore.getValue().pipe(first()).subscribe(siteData => {
            const showProviderSelector = this.shouldShowProviderSelector(siteData, mediaEntityData);

            const componentData: ComponentData = {
                type: FilePickerComponent,
                properties: {
                    multiple: false,
                    value: [],
                    name: imageId,
                    allowCreate: this.sfHtml.settings.allowCreate,
                    mediaEntityData: mediaEntityData,
                    initialViewMode: !this.sfHtml.settings.allowCreate ? FilePickerViewMode.Select : null,
                    showProviderSelector: showProviderSelector,
                    enableDamPicker: true
                }
            };

            const dialogData = new DialogData(componentData, (context) => this.sfHtml.onImageInsertViewClosed(context.data ? context.data.data : context.data, true), [], "-prompt");

            this.modalService.setMapping(dialogData, FILE_PICKER);
            this.modalService.open(this.route, FILE_PICKER);
        });
    }

    onDocumentInsertEdit(dynamicLink?: string) {
        const documentEntityData: EntityData = {
            metadata: this.metadataStore.getEntity(ENTITY_SET.DOCUMENTS),
            provider: ANY_SITE_SOURCE_PROVIDER,
            culture: this.sfHtml.settings.culture || this.sfHtml.settings.dataItem.culture
        };

        if (dynamicLink) {
            this.locatableItemsService.getItemFromDynamicLink(dynamicLink)
                .pipe(
                    filter(x => !x.isLoading),
                    map(x => x.content))
                .subscribe((itemResponse) => {
                    this.openDocumentInsertDialog(documentEntityData, DataItem.from({ [documentEntityData.metadata.key]: itemResponse.id }, documentEntityData.metadata, itemResponse.provider, documentEntityData.culture));
                }, e => {
                    this.openDocumentInsertDialog(documentEntityData);
                });
        } else {
            this.openDocumentInsertDialog(documentEntityData);
        }
    }

    onEditImage(selectedImage: HTMLImageElement) {
        const match = selectedImage.src.match(this.imageMediaEntity.allowedExtensionsRegEx);
        const isImageTag = selectedImage.tagName.toLowerCase() === NODE_NAMES.IMAGE_ELEMENT.toLowerCase();
        const extensionMatch = match && match[0];
        if (!extensionMatch && !isImageTag) {
            return;
        }

        const extension = extensionMatch ? match[0].substring(1) : stringConstants.EMPTY_STRING;
        let contentType = extension === EXTENSIONS.SVG ? MIME_TYPES.SVG : `${IMAGE}${stringConstants.FORWARD_SLASH}${extension}`;

        // extension or mimetype are needed to correctly render the SVG image in edit dialog in case extension is not provided
        // fallback to recognition service to detect the mimeType of the image
        if (extension) {
            this.openEditImageDialog(selectedImage, extension, contentType);
        } else {
            this.mediaRecognizerService.getMediaMimeType(selectedImage.src).then((mimeType) => {
                contentType = mimeType;
            }).finally(() => this.openEditImageDialog(selectedImage, extension, contentType));
        }
    }

    onCreateLink(eventData: EditLinkEventData): void {
        this.selectedTextHtml = eventData.selectedTextHtml;
        this.selectedElement = eventData.selectedElement as HTMLAnchorElement;
        const componentData: ComponentData = this.getLinkComponentData(eventData, true);
        const buttons: Button[] = this.getLinkButtons(eventData);
        const dialogData = new DialogData(componentData, (context) => this.onLinkInsertDialogDone(context), buttons);
        this.openDialogWindow(dialogData, this.route);
    }

    onEditImageLinkClick(element: HTMLImageElement) {
        let anchorElement;

        if (element.parentElement && element.parentElement.attributes[SelectorConstants.SF_IMMUTABLE]) {
            anchorElement = element.parentElement;
        }

        const eventData: EditLinkEventData = {
            isInEditMode: true,
            selectedText: anchorElement ? anchorElement.textContent : stringConstants.EMPTY_STRING,
            selectedElement: anchorElement
        };

        const componentData: ComponentData = this.getLinkComponentData(eventData, false);
        const buttons = this.getLinkButtons(eventData);
        const dialogData = new DialogData(componentData, (context) => this.onEditImageLinkDialogDone(context, element, anchorElement), buttons);
        this.openDialogWindow(dialogData, this.route);
    }

    onCancelUpload(uploadId: string): void {
        const imageIndex = this.uploadingFilesIds.indexOf(uploadId);
        this.uploadingFilesIds.splice(imageIndex, 1);
        this.mediaService.removeUploadById(uploadId);
        this.validateContent();
    }

    validateContent(): boolean {
        const hasError: boolean = this.sfHtml.editor.value.search(SF_IAMGE_UPLOAD_FAILED) !== -1;
        if (hasError) {
            const error = {
                [VALIDATOR_MESSAGES.UPLOAD_FAILED]: true
            };

            this.emitStatus({ type: StatusType.Error, data: error });
        } else {
            if (this.sfHtml.status$.getValue().type === StatusType.Error) {
                this.emitStatus({ type: StatusType.ErrorCleared});
            }
        }

        return hasError;
    }

    onRetryUpload (imageId: string): void {
        const dataItem = DataItem.emptyItem(this.imageMediaEntityData);
        this.mediaService.retryUploadById(dataItem, imageId);
    }

    hasEmptyValue(): boolean {
        return this.sfHtml.hasEmptyValue();
    }

    processErrors(errors: any): Array<string> {
        return this.sfHtml.processErrors(errors);
    }

    getWarnings(): Array<string> {
        return [];
    }

    private openDocumentInsertDialog(entityData: EntityData, dataItem?: DataItem) {
        // determine whether to show providers selector
        this.siteDataStore.getValue().pipe(first()).subscribe(siteData => {
            const showProviderSelector = this.shouldShowProviderSelector(siteData, entityData);

            const componentData: ComponentData = {
                type: FilePickerComponent,
                properties: {
                    multiple: false,
                    value: dataItem ? [dataItem] : [],
                    name: "insertDocument",
                    allowCreate: true,
                    mediaEntityData: entityData,
                    createMedia: true,
                    initialViewMode: dataItem ? FilePickerViewMode.Select : null,
                    showProviderSelector,
                    isNonTranslatedSelectable: false,
                    enableDamPicker: true
                }
            };

            const dialogData = new DialogData(componentData, (context) => {
                let dataItem: DataItem = null;
                if (context && context.component) {
                    if (context.component instanceof FileSelectComponent && context.data) {
                        dataItem = context.data;
                    } else if (context.component instanceof FileUploadProgressComponent && context.data) {
                        const data = context.data.data || context.data;
                        dataItem = DataItem.from(data, entityData.metadata, data.Provider, entityData.culture);
                    } else if (context.component instanceof FilePickerComponent && context.data) {
                        const data = context.data.data || context.data;
                        dataItem = DataItem.from(data, entityData.metadata, data.Provider, entityData.culture);
                    }
                }

                if (dataItem) {
                    const currentSiteId = siteData.Id;
                    this.locatableItemsService.getDynamicLink(dataItem.metadata.setName, dataItem.key, dataItem.provider, dataItem.culture, currentSiteId)
                        .pipe(
                            filter(x => !x.isLoading),
                            map(x => x.content))
                        .subscribe(result => this.sfHtml.onDocumentInsertDialogClosed(dataItem, result.dynamicLink));
                }
            }, [], "-prompt");

            this.modalService.setMapping(dialogData, "insertDocument");
            this.modalService.open(this.route, "insertDocument");
        });
    }

    private getEditImageThumbnailValidator(): ValidatorFn {
        return (control: AbstractControl) => {
            if (!control.value) {
                return null;
            }

            if (control.value.thumbnailValue !== CUSTOM_THUMBNAIL_KEY) {
                return null;
            }

            const errorObj = {};

            if ((control.value.width && control.value.width <= 0 ) || (control.value.height && control.value.height <= 0)) {
                errorObj["minValue"] = { requiredMinValue: 1 };
                return errorObj;
            }

            return null;
        };
    }

    private getEditImageDoneHandler(): (data: ClickData) => ClickResult {
        return (data: ClickData): ClickResult => {
            const formControls = (<any>data.component).form.controls;
            let isFormValid = true;

            // there is a case when the whole form is valid but one of its fields is invalid
            for (const property in formControls) {
                if (formControls[property].invalid) {
                    isFormValid = false;
                }
            }

            const clickResult: ClickResult = new ClickResult(data, isFormValid);
            return clickResult;
        };
    }

    private openDialogWindow(dialogData: DialogData, route: ActivatedRoute): void {
        this.modalService.setMapping(dialogData);
        this.modalService.open(route);
    }

    private onEditImageLinkDialogDone(result: any, element: HTMLImageElement, anchor: HTMLAnchorElement): void {
        this.sfHtml.editor.shouldFocusEditor = true;

        if (!result.data) {
            return;
        }

        const linkData: LinkModel = result.data.data;

        anchor = anchor || <HTMLAnchorElement>document.createElement(NODE_NAMES.ANCHOR_ELEMENT);

        if (linkData) {
            this.createLinkHelper.setLinkAttributes(anchor, linkData);
            if (!anchor.attributes[SelectorConstants.SF_IMMUTABLE]) {
                element.parentElement.insertBefore(anchor, element);

                transferKendoAlignInlineStyles(element, anchor);

                anchor.appendChild(element);
                anchor.setAttribute(SelectorConstants.SF_IMMUTABLE, stringConstants.EMPTY_STRING);
            }

            this.sfHtml.editor.triggerUserValueChanged();
        }
    }

    private getLinkButtons(eventData: EditLinkEventData): Button[] {
        const buttons: Button[] = [
            new ConfirmButton(eventData.isInEditMode ? SelectorConstants.DONE : SelectorConstants.INSERT_LINK, this.getLinkHandler()),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        return buttons;
    }

    private getLinkHandler(): (data: ClickData) => ClickResult  {
        const linkHandler = (data: ClickData): ClickResult => {
            const createLinkComponent: CreateLinkComponent = data.component;
            const linkData = createLinkComponent.link;
            if (this.selectedElement?.attributes.length > 0) {
                const linkAttributes: { [key: string]: string } = {};

                for (let i = 0; i < this.selectedElement.attributes.length; i++) {
                    const attribute = this.selectedElement.attributes[i];
                    if (attribute.name === "class" ||
                        attribute.name.startsWith(ATTR_PREFIX)) {
                        linkAttributes[attribute.name] = attribute.value;
                    }
                }

                linkData.attributes = Object.assign({}, linkData.attributes, linkAttributes);
            }

            const clickResult: ClickResult = new ClickResult(linkData, createLinkComponent.isValid);
            return clickResult;
        };

        return linkHandler;
    }

    private getLinkComponentData(eventData: EditLinkEventData, showTextToDisplay: boolean = true): ComponentData {
        const componentData: ComponentData = {
            type: CreateLinkComponent,
            properties: {
                linkModel: this.createLinkHelper.getLinkModelData(eventData.selectedText, this.selectedElement as HTMLAnchorElement),
                isInEditMode: eventData.isInEditMode,
                showTextToDisplay
            }
        };

        return componentData;
    }

    private onLinkInsertDialogDone(result: any): void {
        if (result.data && result.data.data) {
            let htmlToDisplay: string;
            const linkData: LinkModel = result.data.data;

            if (!linkData.href && !linkData.anchor) {
                return;
            }

            if (linkData && this.selectedTextHtml) {
                if  (this.createLinkHelper.shouldSetHtml(this.selectedTextHtml, linkData.text)) {
                    htmlToDisplay = this.selectedTextHtml;
                }

                linkData.text = this.createLinkHelper.getWrappedLinkText(this.selectedTextHtml, linkData.text);
            }

            this.sfHtml.onCreateLinkDataPosted(linkData, htmlToDisplay);
        } else {
            this.sfHtml.onCreateLinkDataCanceled();
        }

        this.sfHtml.onCreateLinkDialogClosed();
    }

    private onEditImageDoneCallback(context: any, thumbnails: any): void {
        if (context.data && context.data.data) {
            const form = context.component.form;
            const fieldValues = Object.keys(form.controls).map(key => { return { key, value: form.controls[key].value }; });
            this.sfHtml.onEditImageDone(<any>fieldValues, thumbnails);
        }
    }

    private shouldShowProviderSelector(siteData: SiteData, entityData: EntityData): boolean {
        let showProviderSelector = false;
        const module = Object.keys(siteData.Modules)
            .map(key => siteData.Modules[key])
            .find(m => m.AccessibleTypes.indexOf(entityData.metadata.setName) > -1);

        if (module && module.Providers.length > 1) {
            const providersCount = module.Providers.filter(p => p !== ANY_SITE_SOURCE_PROVIDER && p !== DEFAULT_SITE_SOURCE_PROVIDER).length;
            if (providersCount > 1) {
                showProviderSelector = true;
            }
        }

        return showProviderSelector;
    }

    private openEditImageDialog(selectedImage: HTMLImageElement, extension: string, contentType: string): void {
        const widthAttribute = selectedImage.attributes["width"];
        const heightAttribute = selectedImage.attributes["height"];
        let width = null;
        let height = null;
        if (!widthAttribute && !heightAttribute) {
            width = selectedImage.naturalWidth;
            height = selectedImage.naturalHeight;
        } else {
            if (widthAttribute)
                width = parseInt(widthAttribute.value);

            if (heightAttribute)
                height = parseInt(heightAttribute.value);
        }

        const image: Image = {
            width: width,
            height: height,
            alt: selectedImage.alt === "null" ? stringConstants.EMPTY_STRING : selectedImage.alt,
            src: selectedImage.src,
            extension: extension,
            size: selectedImage.getAttribute(SIZE_ATTRIBUTE),
            contentType: contentType
        };

        this.store.getThumbnails(this.imageMediaEntityData, selectedImage.src).subscribe(data => {
            const thumbnails = this.imageHelper.transformThumbnailsToChoices(data.value);

            const validators = (value: any) => this.getEditImageThumbnailValidator()(value);
            const selectedThumbnailId = this.imageHelper.determineThumbnailId(selectedImage, data.value);

            const imageThumbnailSettings = {
                title: "Image thumbnails",
                showTitle: true,
                key: IMAGE_THUMBNAIL_TEXT_KEY,
                dropDownSettings: { choices: thumbnails },
                widthSettings: { title: WIDTH_FIELD_NAME, unit: PIXELS_NAME, naturalValue: selectedImage.naturalWidth },
                heightSettings: { title: HEIGHT_FIELD_NAME, unit: PIXELS_NAME, naturalValue: selectedImage.naturalHeight },
                constrainProportionsSettings: { title: "Constrain proportions", key: `${IMAGE_THUMBNAIL_TEXT_KEY}_constrain_proportions` },
                validators: validators
            };

            const initialValue: any = {
                thumbnailValue: thumbnails.find((x) => x.Value === selectedThumbnailId).Value,
                width: image.width,
                height: image.height,
                constrainProportions: this.imageHelper.determineConstrainProportions(selectedImage)
            };

            const imageMarginsSettings = {
                title: "Image margins",
                showTitle: true,
                key: IMAGE_MARGINS_KEY,
                unit: PIXELS_NAME,
                [MARGIN_TOP_NAME]: { title: "top" },
                [MARGIN_RIGHT_NAME]: { title: "right" },
                [MARGIN_BOTTOM_NAME]: { title: "bottom" },
                [MARGIN_LEFT_NAME]: { title: "left" }
            };

            const marginsContainer = isImageHyperlink(selectedImage) ? selectedImage.parentElement : selectedImage;
            const imageMarginsInitialValue: any = {
                [MARGIN_TOP_NAME]: marginsContainer.style[MARGIN_TOP_NAME],
                [MARGIN_RIGHT_NAME]: marginsContainer.style[MARGIN_RIGHT_NAME],
                [MARGIN_BOTTOM_NAME]: marginsContainer.style[MARGIN_BOTTOM_NAME],
                [MARGIN_LEFT_NAME]: marginsContainer.style[MARGIN_LEFT_NAME]
            };

            const fields = [
                this.fieldsGeneratorService.createFieldModel({ key: ALTERNATIVE_TEXT_KEY, value: image.alt, settings: { key: ALTERNATIVE_TEXT_KEY, title: "Alternative text", showTitle: true, visibleTitle: true }, registration: SHORT_TEXT_REGISTRY }),
                this.fieldsGeneratorService.createFieldModel({ key: IMAGE_THUMBNAIL_TEXT_KEY, value: initialValue, settings: imageThumbnailSettings, registration: EDIT_IMAGE_THUMBNAIL_REGISTRY }),
                this.fieldsGeneratorService.createFieldModel({ key: IMAGE_MARGINS_KEY, value: imageMarginsInitialValue, settings: imageMarginsSettings, registration: EDIT_IMAGE_MARGINS_REGISTRY })
            ];

            const componentData: ComponentData = {
                type: EditImageComponent,
                properties: {
                    fields,
                    image,
                    mediaEntityData: this.imageMediaEntityData
                }
            };

            const buttons: Button[] = [new ConfirmButton(SelectorConstants.DONE, this.getEditImageDoneHandler()), new CancelButton()];
            const dialogData = new DialogData(componentData, (context) => this.onEditImageDoneCallback(context, data.value), buttons);
            dialogData.toolbarData = {
                type: ToolbarComponent,
                properties: {
                    header: IMAGE_PROPERTIES_DIALOG_TITLE
                }
            };
            this.openDialogWindow(dialogData, this.route);
        });
    }
}
