import { InjectionToken, Injectable, Optional, Inject } from "@angular/core";
import { Observable } from "rxjs";
import { DataItem, EntityData } from "../../../interfaces";
import { DeleteCommandExtenderBase } from "./delete-command-extender-base";

export const DELETE_COMMAND_EXTENDER_TOKEN = new InjectionToken("bulk_operations_extender_token");

@Injectable()
export class CompositeDeleteCommandExtender {

    constructor(@Optional() @Inject(DELETE_COMMAND_EXTENDER_TOKEN) private deleteCommandExtenders: DeleteCommandExtenderBase[]) { }

    showMultilingualButtons(data: any): boolean {
        const extender = this.getExtender(data.entityData);
        return extender.showMultilingualButtons(data);
    }

    permanentDelete(data: any): boolean {
        const extender = this.getExtender(data.entityData);
        return extender.permanentDelete(data);
    }

    getTitle(data: any): string {
        const extender = this.getExtender(data.entityData);
        return extender.getTitle(data);
    }

    getDisplayName(data: any): string {
        const extender = this.getExtender(data.entityData);
        return extender.getDisplayName(data);
    }

    executeDelete(dataItem: DataItem, deleteAllTranslations: boolean, skipItemStateUpdate?: boolean): Observable<DataItem> {
        const extender = this.getExtender(dataItem);
        return extender.executeDelete(dataItem, deleteAllTranslations, skipItemStateUpdate);
    }

    private getExtender(entityData: EntityData): DeleteCommandExtenderBase {
        const extender = this.deleteCommandExtenders.find(x => entityData && x.isSupportedType(entityData));
        return extender;
    }
}
