import { createReducer, on, combineReducers } from "@ngrx/store";
import { FIELDS_ACTIONS } from "../actions/actions.fields";
import { ContentSelectorData, FieldsState } from "../schemas/schema.fields";
import { initialState } from "../store-schema";

const fieldsChangeTypeReducer = createReducer<ContentSelectorData>(initialState.fields.contentSelector,
    on(FIELDS_ACTIONS.changeItemType, (state, contentSelector) => {
        return contentSelector;
    })
);

const fieldsChangeViewNameReducer = createReducer<string>(initialState.fields.viewName,
    on(FIELDS_ACTIONS.changeViewName, (state, { viewName: viewName }) => {
        return viewName;
    })
);

export const fieldsReducer = combineReducers<FieldsState>({
    contentSelector: fieldsChangeTypeReducer,
    viewName: fieldsChangeViewNameReducer
});
