import { Component, EventEmitter, Output, ViewChild } from "@angular/core";
import { Observable } from "rxjs";
import { tap } from "rxjs/operators";
import { EnumChoiceSettings } from "../../src/app/modules/widget-editor/providers/fields/enum-field-provider";
import { createValueAccessor } from "../field-base";
import { ChoiceComponent } from "./choice.component";

const CHOICE_CHIP_MAX_THRESHOLD: number = 4;

@Component({
    selector: "sf-chip-choice",
    templateUrl: "./choice-chip.component.html",
    providers: [createValueAccessor(ChoiceChipComponent)]
})
export class ChoiceChipComponent extends ChoiceComponent {
    hasMoreOptions: boolean;
    @Output() selectionChange: EventEmitter<string> = new EventEmitter<string>();
    private innerChoiceComponent: ChoiceComponent;

    @ViewChild("innerChoiceComponent", { static: false }) set innerChoice(component: ChoiceComponent) {
        if (component) {
            this.innerChoiceComponent = component;
            this.innerChoiceComponent.writeValue(this.getValue());
        }
    }

    protected loadChoices(): Observable<void> {
        return super.loadChoices().pipe(tap(() => {
            if (this.settings) {
                if (this.settings.choices.length > CHOICE_CHIP_MAX_THRESHOLD && !(<EnumChoiceSettings>this.settings).choiceNotResponsive) {
                    this.hasMoreOptions = true;
                }
            }
        }));
    }

    onSelectionChange(entry) {
        const checkedIndex = this.settings.choices.findIndex(x => x.Value === entry);
        super.onSelectionChange(checkedIndex);
    }
}
