import { Component, Input, Output, EventEmitter, ViewChild, OnInit } from "@angular/core";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";
import { FormRuleAction, FormDefinition, FormFieldTypeData } from "../forms.constants";
import { FormFieldTypesParserService } from "../services/form-field-types-parser.service";
import { FieldBase } from "../../../../../fields";
import { first } from "rxjs/operators";
import { SettingsBase } from "../../../../../fields/field-settings-base";
import { FormGroup, FormControl } from "@angular/forms";
import { SfDynamicComponentLoaderComponent, SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-action-create-composite",
    templateUrl: "./action-create-composite.component.html"
})
export class ActionCreateCompositeComponent extends SfRxBase implements OnInit {
    @Input() formDefinition: FormDefinition;
    @Input() formRuleAction: FormRuleAction;
    @Input() canDelete: boolean;
    @Output() actionForDelete: EventEmitter<FormRuleAction> = new EventEmitter<FormRuleAction>();

    public formActionsDropdownSettings: ChoiceSettings;
    public showErrors: boolean = false;
    public errorMessages: string[];
    public fieldClassList: string;
    public formFieldColumnData: FormFieldTypeData;
    @ViewChild("loader", { static: false }) loader: SfDynamicComponentLoaderComponent;
    private wrappedField: FieldBase;
    private formGroup: FormGroup;

    constructor(private typeParserService: FormFieldTypesParserService) {
        super();

        this.formGroup = new FormGroup({});
    }

    ngOnInit() {
        this.initActionFields();
    }

    public loaderInit(event) {
        const that = this;
        this.wrappedField = event;

        this.handleFocusChanges();

        this.wrappedField.registerOnChange((value: any) => {
            this.processErrors();
            if (value instanceof Array && value.length > 0) {
                that.formRuleAction.Target = value[0].Id;
            } else {
                that.formRuleAction.Target = value;
            }
        });
    }

    public formActionChanged(value) {
        if (value) {
            this.formRuleAction.Action = value;
            this.refreshDynamicComponent(null);
        }
    }

    public deleteAction() {
        this.actionForDelete.emit(this.formRuleAction);
    }

    public isValid(): boolean {
        let isValid = true;

        this.formGroup.reset();
        this.formGroup.setControl(this.wrappedField.settings.key, new FormControl(this.wrappedField.getValue(), {validators: this.wrappedField.settings.validators}));
        this.formGroup.updateValueAndValidity();

        isValid = this.formGroup.valid;

        const errors = this.wrappedField.processErrors(this.formGroup.controls[this.wrappedField.settings.key].errors);
        this.processErrors(errors);

        return isValid;
    }

    public processErrors(errors = []) {
        this.errorMessages = [];
        this.showErrors = false;

        if (errors && errors.length > 0) {
            this.errorMessages = errors;
            this.showErrors = true;
        }
    }

    private handleFocusChanges(): void {
        const focusSubscription = this.wrappedField.focus$.subscribe((isFocused) => {
            // always show all errors present when the field is focused out
            this.showErrors = !isFocused;
        });

        this.registerSubscription(focusSubscription);
    }

    private initActionFields() {
        if (this.formRuleAction) {
            this.formActionsDropdownSettings = new ChoiceSettings("formActionsDropdown", false);

            this.formDefinition.AvailableActions.forEach(action => {
                this.formActionsDropdownSettings.choices.push({
                    Value: action.Key,
                    Name: action.Value
                });
            });

            this.formActionsDropdownSettings.defaultValue = this.formRuleAction.Action;
            this.refreshDynamicComponent(this.formRuleAction.Target);
        }
    }

    private refreshDynamicComponent(defaultValue: string) {
        this.processErrors();
        if (this.loader) {
            this.loader.destroy(this.formFieldColumnData.component);
        }

        this.typeParserService.getActionComponentType(this.formRuleAction.Action, this.formDefinition, defaultValue).pipe(first()).subscribe((data: FormFieldTypeData) => {
            this.formFieldColumnData = data;
            const targetSettings = this.formFieldColumnData.component.properties.settings as SettingsBase;
            const settingsDefaultValue = targetSettings.defaultValue;
            if (settingsDefaultValue !== null) {
                this.formRuleAction.Target = settingsDefaultValue.toString();
            }
        });
    }
}
