export const ITEM_NOT_FOUND_MSG = "Item(s) not found.";

@Injectable()
export class DynamicItemService {

    constructor(private sitefinitySdk: SitefinitySdk,
                private fileInfoService: FileInfoService,
                private errorParserService: ErrorParserService,
                private externalAppConfigService: ExternalAppConfigService,
                @Optional() @Inject(QUERY_PARAMS_EXTENDER_TOKEN) private queryParamsExtenders: QueryParamsExtender[]) {

    }

    getItemsByKeys(args: LoadItemsByKeysData): Observable<LoadItemsResponse> {
        let whereQuery = createQuery().where().or();
        args.keys.forEach(key => {
            whereQuery = whereQuery.eq(args.keyProperty, key);
        });

        const query = whereQuery.done().done();

        if (MediaHelpers.isLibraryOrMedia(args.entityData.metadata.setName)) {
            if (!args.additionalQueryParams)
                args.additionalQueryParams = {};

            args.additionalQueryParams[QUERY_PARAMS.SKIP_DAM] = "false";
        }

        const loadItems = {
            query,
            ...args
        };

        return this.getItemList(loadItems);
    }

    getRecent(loadData: LoadItemsData): Observable<LoadItemsResponse> {
        const subject = this.createSubject<LoadItemsResponse>();
        const query = this.getQuery(loadData);

        this.sitefinitySdk.instance.data({
            entitySet: loadData.entityData.metadata.setName,
            provider: loadData.entityData.provider,
            culture: loadData.entityData.culture,
            siteId: loadData.siteId,
            additionalQueryParams: loadData.additionalQueryParams || {}
        }).create({
            key: null,
            query,
            action: loadData.action,
            data: loadData.payload || {},
            successCb: data => {
                const mappedItems = this.getItemListMapper(data, loadData.entityData);
                subject.next(mappedItems);
            },
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    getItemList(loadData: LoadItemsData): Observable<LoadItemsResponse> {
        return this.getItemsInternal(loadData).pipe(map((data) => {
            return this.getItemListMapper(data, loadData.entityData);
        }));
    }

    getItemListBatch(loadData: LoadItemsData): Observable<LoadItemsResponse> {
        return this.getItemsInternalBatch(loadData).pipe(map((data) => {
            return this.getItemListMapper(data, loadData.entityData);
        }));
    }

    getItemListBatchWithMultipleQueries(loadDatas: LoadItemsData[]): Observable<LoadItemsResponse> {
        return this.getItemListBatchWithMultipleQueriesInternal(loadDatas).pipe(map((data) => {
            return this.getItemListMapper(data, loadDatas[0].entityData);
        }));
    }

    getItemsOperations(entityData: EntityData, itemId: string = null, parentId: string = null, additionalQueryParams: { [key: string]: string } = null): Observable<OperationModel[]> {
        const subject = this.createSubject<OperationModel[]>();

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, additionalQueryParams, this.queryParamsExtenders)
        }).getOperations({
            key: itemId,
            parentId: parentId,
            successCb: data => subject.next(data.Operations),
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    executeOperation(dataItem: DataItem, actionName: string): Observable<OperationResult> {
        const additionalQueryParams = {};
        if (dataItem.data && dataItem.data.SiteId) {
            additionalQueryParams[QUERY_PARAMS.SITE] = dataItem.data.SiteId;
        }

        const ret$ = this.executeBoundAction(dataItem, "operation", { action: actionName }, additionalQueryParams);

        return ret$.pipe(map((data: any) => {
            return {
                message: data.Message,
                title: data.Title,
                success: data.Success,
                link: data.Link,
                key: dataItem.key,
                availableActions: data.AvailableActions
            };
        }));
    }

    // TODO: refactor these methods
    executeEntityOperation(entityData: EntityData, actionName: string, data: any): Observable<any> {
        return this.executeEntityOperationForDataItemKey(null, entityData, actionName, data);
    }

    executeEntityOperationForDataItemKey(dataItemKey: string, entityData: EntityData, actionName: string, data: any): Observable<any> {
        const subject = this.createSubject<any>();

        this.sitefinitySdk.instance.data({
            entitySet: entityData.metadata.setName,
            provider: entityData.provider,
            culture: entityData.culture,
            additionalQueryParams: getAdditionalQueryParams(entityData.metadata, null, this.queryParamsExtenders)
        }).create({
            key: dataItemKey,
            action: actionName,
            data: data,
            successCb: data => subject.next(data),
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    executeBoundAction<T>(dataItem: DataItem, actionName: string, data: any, additionalQueryParam: {[key: string]: string} = null): Observable<T> {
        const subject = this.createSubject<T>();

        this.sitefinitySdk.instance.data({
            entitySet: dataItem.metadata.setName,
            provider: dataItem.provider,
            culture: dataItem.culture,
            additionalQueryParams: getAdditionalQueryParams(dataItem.metadata, additionalQueryParam, this.queryParamsExtenders)
        }).create({
            key: dataItem.key,
            action: actionName,
            data: data || {},
            successCb: data => subject.next(data),
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    executeBoundFunction<T>(dataItem: DataItem, actionName: string, fallbackProperties: string[] = [], additionalQueryParam: {[key: string]: string} = null): Observable<T> {
        const subject = this.createSubject<T>();
        const data = this.sitefinitySdk.instance.data({
            entitySet: dataItem.metadata.setName,
            provider: dataItem.provider,
            culture: dataItem.culture,
            additionalQueryParams: getAdditionalQueryParams(dataItem.metadata, additionalQueryParam, this.queryParamsExtenders)
        });

        if (dataItem.key) {
            data.getSingle({
                key: dataItem.key,
                action: actionName,
                successCb: data => subject.next(data),
                failureCb: error => subject.error(this.errorParserService.parseError(error)),
                fallbackProperties
            });
        } else {
            data.get({
                action: actionName,
                successCb: data => subject.next(data),
                failureCb: error => subject.error(this.errorParserService.parseError(error)),
                fallbackProperties
            });
        }

        return subject.pipe(first());
    }

    executeUnboundFunction<T>(actionName: string, operationData: OperationData | UnboundFunctionData = null, siteId: string = null): Observable<T> {
        const subject = this.createSubject<T>();

        if (operationData) {
            this.sitefinitySdk.instance.data({
                culture: operationData.culture,
                provider: operationData.provider,
                siteId: siteId,
                additionalQueryParams: getAdditionalQueryParams(null, null, this.queryParamsExtenders)
            }).create({
                action: actionName,
                data: operationData.data,
                successCb: data => subject.next(data),
                failureCb: error => subject.error(this.errorParserService.parseError(error))
            });
        } else {
            this.sitefinitySdk.instance.data({
                siteId: siteId
            }).get({
                action: actionName,
                successCb: data => subject.next(data),
                failureCb: error => subject.error(this.errorParserService.parseError(error))
            });
        }

        return subject.pipe(first());
    }

    restoreItem(dataItem: DataItem): Observable<OperationResult> {
        const subject = this.createSubject<OperationResult>();
        const restoreAction = ActionEvent.Restore;
        this.sitefinitySdk.instance.data({
            entitySet: dataItem.metadata.setName,
            provider: dataItem.provider,
            culture: dataItem.culture,
            additionalQueryParams: getAdditionalQueryParams(dataItem.metadata, null, this.queryParamsExtenders)
        }).create({
            key: dataItem.key,
            action: restoreAction,
            data: {},
            successCb: data => {
                subject.next({
                    message: data.Message,
                    success: data.Success
                });
            },
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    getItemsChildrenCount(item: DataItem, metaContainer: MetadataContainer): Observable<any> {
        const subject = this.createSubject<any>();

        const batchRequest = this.sitefinitySdk.instance.batch((batchResponse: any) => {
            const error = this.errorParserService.parseError(batchResponse);
            if (error instanceof GenericError) {
                subject.error(error);
                return;
            }

            const countArr: Array<any> = batchResponse.data;
            const returnData: any = {};
            let counter = 0;
            countArr.forEach((countData) => {
                const entityName = item.childTypes[counter];
                const childCount = Number.parseInt(countData.response.data);
                returnData[entityName] = childCount;

                counter++;
            });

            subject.next(returnData);
        }, (error) => subject.error(this.errorParserService.parseError(error)),
        undefined,
            {
                provider: item.provider,
                culture: item.culture
            });

        item.childTypes.forEach((child) => {
            // pass this as argument
            const parentProperty = metaContainer.entities[child].parentIdProperty;
            const query = this.sitefinitySdk.query.where().eq(parentProperty, item.data.Id).done().count(false);

            batchRequest.get({
                entitySet: child,
                query: query
            });
        });

        batchRequest.execute();

        return subject.pipe(first());
    }

    upsert(upsertArgs: UpdateItem): Observable<DataItem> {
        let dataItem$: Observable<DataItem> = null;
        if (!upsertArgs.dataItem.data) {
            dataItem$ = this.createItem({
                data: upsertArgs.data,
                entityData: upsertArgs.dataItem,
                operation: upsertArgs.operation,
                dataFieldNames: upsertArgs.dataFieldNames,
                fallbackProperties: upsertArgs.fallbackProperties,
                siteId: upsertArgs.siteId,
                doNotRefreshItem: upsertArgs.doNotRefreshItem,
                additionalQueryParams: getAdditionalQueryParams(upsertArgs.dataItem?.metadata, upsertArgs.additionalQueryParams, this.queryParamsExtenders)
            });
        } else {
            dataItem$ = this.updateItem(upsertArgs);
        }

        return dataItem$;
    }

    createItemWithOperationResult(createItemArgs: CreateItem): Observable<ItemWithOperationResult> {
        const subject = this.createSubject<ItemWithOperationResult>();

        const batch = this.sitefinitySdk.instance.batch(
            result => {
                const error = this.errorParserService.parseError(result);
                if (error instanceof GenericError) {
                    subject.error(error);
                    return;
                }
                let operationResult;
                let operationMessage = stringConstants.EMPTY_STRING;
                let operationData = {};
                if (createItemArgs.operation) {
                    operationResult = this.getOperationResult(result, createItemArgs.data);
                    operationMessage = operationResult.Message;
                    operationData = createItemArgs.operation;
                }

                const item = result.data[0].response[0].data;
                const dataItem = DataItem.fromEntityData(item, createItemArgs.entityData);
                // We get the item here as its workflow status may not be correct in the the batch response
                // This is because the workflow operation (e.g. Publish) is executed after the item create

                if (!createItemArgs.doNotRefreshItem) {
                    this.getItem({
                        itemKey: dataItem.key,
                        entityData: dataItem,
                        fallbackProperties: createItemArgs.fallbackProperties,
                        siteId: createItemArgs.siteId
                    }).subscribe(
                        data => subject.next({ dataItem: data, operationMessage, operationData, operationResult }),
                        err => subject.error(this.errorParserService.parseError(err))
                    );
                } else {
                    subject.next({ dataItem, operationMessage, operationData });
                }
            },
            error => {
                subject.error(this.errorParserService.parseError(error));
            },
            undefined,
            {
            provider: createItemArgs.entityData.provider,
            culture: createItemArgs.entityData.culture,
            siteId: createItemArgs.siteId,
            additionalQueryParams: getAdditionalQueryParams(createItemArgs.entityData.metadata, createItemArgs.additionalQueryParams, this.queryParamsExtenders)
        });

        const transaction = batch.beginTransaction();

        const entitySet = createItemArgs.entityData.metadata.setName;
        const fieldValues = this.getFieldValues(createItemArgs.entityData.metadata, createItemArgs.data);

        const itemId = transaction.create({
            entitySet,
            data: fieldValues.primitives
        });

        SitefinitySdk.associateRelationFields(entitySet, itemId, fieldValues.relational, transaction);

        if (createItemArgs.operation) {
            transaction.operation({
                entitySet: entitySet,
                key: itemId,
                data: createItemArgs.operation
            });
        }

        batch.endTransaction(transaction);

        // TODO: get the item here instead of going to the server again
        batch.execute();

        return subject.pipe(first());
    }

    createItem(args: CreateItem): Observable<DataItem> {
        return this.createItemWithOperationResult(args).pipe(map(x => x.dataItem));
    }

    updateItemWithOperationResult(updateItemArgs: UpdateItem): Observable<ItemWithOperationResult> {
        const subject = this.createSubject<ItemWithOperationResult>();
        const batch = this.sitefinitySdk.instance.batch(
            result => {
                const error = this.errorParserService.parseError(result);
                if (error instanceof LockedItemError && !updateItemArgs.doNotRefreshItem) {
                    const getItemResponse = result.data[result.data.length - 1].response;
                    error.data =  getItemResponse.data.value[0];
                }

                if (error instanceof GenericError) {
                    subject.error(error);
                    return;
                }

                let operationMessage = stringConstants.EMPTY_STRING;
                let operationData = {};
                let operationResult;
                if (updateItemArgs.operation) {
                    operationResult = this.getOperationResult(result, updateItemArgs.data);
                    if (operationResult && !operationResult.Success) {
                        subject.error(new OperationFailedError(updateItemArgs.operation.action, operationResult));
                        return;
                    }

                    operationMessage = operationResult.Message;
                    operationData = operationResult;
                }

                if (!updateItemArgs.doNotRefreshItem) {
                    const getItemResponse = result.data[result.data.length - 1].response;
                    const returnedItem = getItemResponse.data.value[0];
                    const dataItem = DataItem.fromEntityData(returnedItem, updateItemArgs.dataItem);
                    subject.next({ dataItem, operationMessage, operationData, operationResult });
                } else {
                    subject.next({ dataItem: updateItemArgs.dataItem, operationMessage, operationData, operationResult });
                }
            },
            error => { subject.error(this.errorParserService.parseError(error)); },
            undefined,
            {
                provider: updateItemArgs.dataItem.provider,
                culture: updateItemArgs.dataItem.culture,
                additionalQueryParams: getAdditionalQueryParams(updateItemArgs.dataItem.metadata, updateItemArgs.additionalQueryParams, this.queryParamsExtenders, updateItemArgs.data ?? updateItemArgs.dataItem)
            }
        );

        this.updateItemsTransaction([updateItemArgs], batch);
        return subject.pipe(first());
    }

    updateItemsWithBulkOperationResult(updateItemsArgs: UpdateItem[], entityData: EntityData): Observable<BulkOperationResult> {
        const subject = this.createSubject<BulkOperationResult>();
        const batch = this.sitefinitySdk.instance.batch(
            result => {
                const items = [];
                for (let index = 0; index < updateItemsArgs.length; index++) {
                    if (!updateItemsArgs[index].doNotRefreshItem) {
                        if (result.data[index * 2 + 1]) {
                            const getItemResponse = result.data[index * 2 + 1].response;
                            items.push(DataItem.fromEntityData(getItemResponse.data.value[0], updateItemsArgs[index].dataItem));
                        }
                    }
                }

                const failedItemsIds = filterDuplicates(result.data.filter(x => !x.isSuccessful).map(m => m.response[0].key || m.response[0].data.error.target));
                const bulkOperationResult: BulkOperationResult = {
                    success: true,
                    succeededItemsIds: updateItemsArgs.filter(x => failedItemsIds.indexOf(x.dataItem.key) === -1).map(m => m.dataItem.key),
                    failedItemsIds: failedItemsIds,
                    items
                };
                subject.next(bulkOperationResult);
            },
            error => { this.errorParserService.parseError(error); },
            undefined,
            {
                provider: entityData.provider,
                culture: entityData.culture
            }
        );

        this.updateItemsTransaction(updateItemsArgs, batch, false);
        batch.execute();
        return subject.pipe(first());
    }

    updateItem(updateItemArgs: UpdateItem): Observable<DataItem> {
        return this.updateItemWithOperationResult(updateItemArgs).pipe(map(x => x.dataItem));
    }

    getProperty(loadProperty: LoadProperty): Observable<any> {
        const dataItem = loadProperty.dataItem;
        const subject = this.createSubject<DataItem>();
        this.sitefinitySdk.instance.data({
            entitySet: dataItem.metadata.setName,
            provider: dataItem.provider,
            culture: dataItem.culture,
            additionalQueryParams: getAdditionalQueryParams(dataItem.metadata, null, this.queryParamsExtenders)
        }).getProperty({
            key: dataItem.key,
            property: loadProperty.key,
            successCb: data => {
                subject.next(data.value);
            },
            failureCb: error => subject.error(this.errorParserService.parseError(error))
        });

        return subject.pipe(first());
    }

    getItem(loadItemData: LoadItem): Observable<DataItem> {
        const entity = loadItemData.entityData;
        let query = this.sitefinitySdk.query;

        const relatedFields = this.getRelationshipFieldNames(entity);
        if (relatedFields.length > 0)
            query = query.expand(...relatedFields) as any;

        query = this.setSelect(query, loadItemData.dataFieldNames);

        const subject = this.createSubject<DataItem>();
        this.sitefinitySdk.instance.data({
            entitySet: entity.metadata.setName,
            provider: entity.provider,
            culture: entity.culture,
            siteId: loadItemData.siteId,
            additionalQueryParams: getAdditionalQueryParams(entity.metadata, loadItemData.additionalQueryParams, this.queryParamsExtenders)
        }).getSingle({
            query: query,
            key: loadItemData.itemKey,
            action: loadItemData.action,
            successCb: data => {
                subject.next(DataItem.from(data, entity.metadata, entity.provider, entity.culture));
            },
            failureCb: error => subject.error(this.errorParserService.parseError(error)),
            fallbackProperties: loadItemData.fallbackProperties

        });

        return subject.pipe(first());
    }

    unlockItem(dataItem: DataItem, checkIfOwnerIsCurrentUser: boolean = false): Observable<DataItem> {
        return this.updateItem({
            dataItem: dataItem,
            operation: {
                action: OPERATION_NAMES.unlock,
                actionParameters: {
                    checkIfOwnerIsCurrentUser: checkIfOwnerIsCurrentUser.toString()
                }
            }
        });
    }

    deleteItem(deleteItemArgs: DeleteItem): Observable<DataItem> {
        const item = deleteItemArgs.dataItem;
        const itemCulture = deleteItemArgs.deleteAllTranslations ? null : item.culture;

        const data = this.sitefinitySdk.instance.data({
            entitySet: item.metadata.setName,
            provider: item.provider,
            culture: itemCulture,
            additionalQueryParams: getAdditionalQueryParams(item.metadata, null, this.queryParamsExtenders)
        });

        const observable = this.createSubject<DataItem>();

        data.destroy({
            key: item.key,
            successCb: res => { observable.next(item); },
            failureCb: error => observable.error(this.errorParserService.parseError(error))
        });

        return observable.pipe(first());
    }

    getFieldValues(entity: Entity, data: any): FieldValues {
        const fieldValues: FieldValues = {
            primitives: {},
            relational: {}
        };

        if (!data) {
            return fieldValues;
        }

        const keys: Array<string> = Object.keys(data);
        if (!keys.length) {
            return fieldValues;
        }

        keys.forEach(key => {
            const isPrimitive = !!entity.primitives.find(x => x === key);
            if (isPrimitive) {
                this.setPrimitiveValue(fieldValues, key, data[key]);
                return;
            }

            const relation = entity.relations.find(x => x.propName === key);
            if (relation) {
                this.setRelationalValue(fieldValues, key, relation, data);
                return;
            }

            if (key === MEDIA_DATA_FIELD_NAME) {
                fieldValues.blob = this.fileInfoService.createFileInfo$(data[key], entity);
                return;
            }

            if (entity.isOpen) {
                this.setPrimitiveValue(fieldValues, key, data[key]);
            }
        });

        // In case of videos when we are changing both the video and the thumbnial we want to update the thumbnail with the upload request and not the saveTemp request.
        // Otherwise we would change the thumbnail of the previous video
        if (fieldValues.blob) {
            delete fieldValues.primitives[Properties.THUMBNAIL_SOURCE];
        }

        return fieldValues;
    }

    private updateItemsTransaction(updateItemsArgs: UpdateItem[], batch: any, executeBatch: boolean = true): void {
        updateItemsArgs.forEach(updateItemArgs => {
            const transaction = batch.beginTransaction();
            const entitySet = updateItemArgs.dataItem.metadata.setName;
            const itemKey = updateItemArgs.dataItem.key;
            const fieldValues = this.getFieldValues(updateItemArgs.dataItem.metadata, updateItemArgs.data);
            if (updateItemArgs.data && !updateItemArgs.skipUpdate) {
                if (!updateItemArgs.skipSaveTemp) {
                    const primitiveValues = fieldValues.primitives || updateItemArgs.data;
                    transaction.create({
                        entitySet: entitySet,
                        action: "Default.savetemp",
                        key: itemKey,
                        data: {
                            model: primitiveValues
                        }
                    });
                }

                SitefinitySdk.associateRelationFields(entitySet, itemKey, fieldValues.relational, transaction);
            }

            this.waitForFileToResolve(fieldValues.blob, updateItemArgs, transaction).subscribe(() => {
                if (updateItemArgs.operation) {
                    const query = this.sitefinitySdk.query.where().eq(updateItemArgs.dataItem.metadata.key, itemKey).done();

                    transaction.operation({
                        entitySet: entitySet,
                        key: itemKey,
                        data: updateItemArgs.operation,
                        query: query
                    });
                }

                batch.endTransaction(transaction);

                if (!updateItemArgs.doNotRefreshItem) {
                    let query = this.sitefinitySdk.query.where().eq(updateItemArgs.dataItem.metadata.key, updateItemArgs.dataItem.key).done();

                    query = this.setSelect(query, updateItemArgs.dataFieldNames);

                    const relatedFields = this.getRelationshipFieldNames(updateItemArgs.dataItem);
                    if (relatedFields.length > 0)
                        query = query.expand(...relatedFields) as any;

                    batch.get({
                        entitySet: updateItemArgs.dataItem.metadata.setName,
                        query: query,
                        fallbackPropertyNames: updateItemArgs.fallbackProperties
                    });
                }

                if (executeBatch) {
                    batch.execute();
                }
            });
        });
    }

    private getOperationResult(result: any, data: any): OperationItemResult {
        // 0 because the first transaction consists of the update of the fields and the operation
        const transactionIndex = 0;
        const response = result.data[transactionIndex].response;
        const operationResult = response[response.length - 1].data;

        return operationResult;
    }

    private waitForFileToResolve(fileInfo: Observable<FileInfo>, updateItemArgs: UpdateItem, transaction: any): Observable<void> {
        const file$ = new ReplaySubject<void>(1);
        const ret$ = file$.asObservable();
        if (fileInfo) {
            const dataItem = updateItemArgs.dataItem;
            fileInfo.subscribe((fileInfo: FileInfo) => {
                if (fileInfo.asset) {
                    transaction.create({
                        entitySet: dataItem.metadata.setName,
                        action: "Default.UpdateDamMediaContent",
                        key: dataItem.key,
                        data: {
                            asset: fileInfo.asset
                        }});
                } else {
                    const uploadProperties: any = {
                        Height: fileInfo.height,
                        Width: fileInfo.width,
                        PreserveFileName: fileInfo.preserveFileName
                    };

                    if (MediaHelpers.isVideoEntity(dataItem) && updateItemArgs.data[Properties.THUMBNAIL_SOURCE]) {
                        uploadProperties[Properties.THUMBNAIL_SOURCE] = updateItemArgs.data[Properties.THUMBNAIL_SOURCE];
                    }

                    transaction.upload({
                        entitySet: dataItem.metadata.setName,
                        key: dataItem.key,
                        data: fileInfo.content,
                        contentType: fileInfo.contentType,
                        fileName: fileInfo.name,
                        uploadProperties
                    });
                }

                file$.next(null);
            });
        } else {
            file$.next(null);
        }

        return ret$;
    }

    private createSubject<TData>(): Subject<TData> {
        return new ReplaySubject<TData>(1);
    }

    private getRelationshipFieldNames(entityData: EntityData): string[] {
        const properties = entityData.metadata.properties;
        const relatedPropertyNames = Object.keys(properties).filter(key => {
            return properties[key].hasOwnProperty("relationship");
        }).map(key => properties[key].relationship.partner);

        return relatedPropertyNames;
    }

    private setPrimitiveValue(fieldValues: FieldValues, key: string, value: string): void {
        fieldValues.primitives[key] = value;
    }

    private setRelationalValue(fieldValues: FieldValues, key: string, relation: Relation, data: any): void {
        let value = data[key];
        const links = [];
        if (value !== undefined && value !== null) {
            if (!Array.isArray(value)) {
                value = [value];
            }

            for (const entry of value) {
                const entryId = entry.Id || entry; // TODO: should be removed, when image component starts to return Id's only
                const link = this.sitefinitySdk.link(relation.setName, entryId, entry.provider || relation.provider);
                links.push(link);
            }
        }
        fieldValues.relational[key] = links;
    }

    private getQuery(loadData: LoadItemsData): Query {
        let resultQuery = loadData.query || createQuery();

        if (loadData.skip) {
            resultQuery = resultQuery.skip(loadData.skip);
        }

        if (loadData.take || loadData.take === 0) {
            resultQuery = resultQuery.take(loadData.take);
        }

        if (loadData.order) {
            resultQuery = resultQuery.order(loadData.order);
        }

        if (loadData.filter || loadData.itemsToExclude) {
            resultQuery = this.addFiltering(resultQuery, loadData.filter, loadData.itemsToExclude);
        }
        resultQuery = this.setSelect(resultQuery, loadData.dataFieldNames);

        if (loadData.dataFieldNames) {
            const relatedFields = this.getRelationshipFieldNames(loadData.entityData);
            const selectedRelatedFields = relatedFields.filter(f => loadData.dataFieldNames.indexOf(f) > -1);
            if (selectedRelatedFields.length > 0) {
                resultQuery = resultQuery.expand(...selectedRelatedFields);
            }
        }

        resultQuery = resultQuery.count();

        return resultQuery;
    }

    private setSelect(query: any, dataFieldNames: string[] = null) {
        if (dataFieldNames) {
            query = query.select(...dataFieldNames);
        } else {
            query = query.select("*");
        }

        return query;
    }

    private getItemsInternal(loadData: LoadItemsData): Observable<any> {
        const query = this.getQuery(loadData);
        const result$ = this.createSubject<any>();
        this.sitefinitySdk.instance.data({
            entitySet: loadData.entityData.metadata.setName,
            provider: loadData.entityData.provider,
            culture: loadData.entityData.culture,
            siteId: loadData.siteId,
            baseUrl: loadData.serviceUrl,
            additionalQueryParams: getAdditionalQueryParams(loadData.entityData.metadata, loadData.additionalQueryParams, this.queryParamsExtenders)
        }).get({
            query,
            action: loadData.action,
            successCb: data => {
                result$.next(data);
            },
            failureCb: error => result$.error(this.errorParserService.parseError(error)),
            fallbackProperties: loadData.fallbackProperties
        });

        return result$.pipe(first());
    }

    private getItemsInternalBatch(loadData: LoadItemsData): Observable<any> {
        loadData.take = loadData.take || this.externalAppConfigService.externalConfig.contentItemsPerPage;
        loadData.skip = loadData.skip || 0;

        const result$ = this.createSubject<any>();

        const batch = this.sitefinitySdk.instance.batch(
            result => {
                this.parseGetItemListBatchResponse(result, result$);
            },
            error => { result$.error(error); },
            undefined,
            {
                provider: loadData.entityData.provider,
                culture: loadData.entityData.culture,
                siteId: loadData.siteId,
                additionalQueryParams: getAdditionalQueryParams(loadData.entityData.metadata, loadData.additionalQueryParams, this.queryParamsExtenders)
            }
        );

        // pagination for more than DEFAULT_TAKE value
        let skip = loadData.skip;
        let take = loadData.take;
        let leftTake = loadData.take;

        // eslint-disable-next-line no-constant-condition
        while (true) {

            // if not items left - exit
            if (leftTake < 1) {
                break;
            }

            if (leftTake > this.externalAppConfigService.externalConfig.contentItemsPerPage) {
                take = this.externalAppConfigService.externalConfig.contentItemsPerPage;
            } else {
                take = leftTake;
            }

            const partialLoadData = Object.assign({}, loadData);
            partialLoadData.skip = skip;
            partialLoadData.take = take;

            const partialQuery = this.getQuery(partialLoadData);

            batch.get({
                entitySet: loadData.entityData.metadata.setName,
                query: partialQuery,
                fallbackProperties: loadData.fallbackProperties
            });

            skip += take;
            leftTake -= take;
        }

        batch.execute();

        return result$.pipe(first());
    }

    private getItemListBatchWithMultipleQueriesInternal(loadDatas: LoadItemsData[]): Observable<any> {
        const result$ = this.createSubject<any>();

        const batch = this.sitefinitySdk.instance.batch(
            result => {
                this.parseGetItemListBatchResponse(result, result$);
            },
            error => { result$.error(error); },
            undefined,
            {
                provider: loadDatas[0].entityData.provider,
                culture: loadDatas[0].entityData.culture,
                siteId: loadDatas[0].siteId,
                additionalQueryParams: getAdditionalQueryParams(loadDatas[0].entityData.metadata, loadDatas[0].additionalQueryParams, this.queryParamsExtenders)
            }
        );

        for (let i = 0; i < loadDatas.length; i++) {
            const currentLoadData = loadDatas[i];
            const query = this.getQuery(currentLoadData);
            batch.get({
                entitySet: currentLoadData.entityData.metadata.setName,
                query: query,
                fallbackProperties: currentLoadData.fallbackProperties
            });
        }

        batch.execute();

        return result$.pipe(first());
    }

    getItemListMapper(data: any, entityData: EntityData): LoadItemsResponse {
        const dataItems = data.value.map((item) => {
            return DataItem.fromEntityData(item, entityData);
        });

        const response: LoadItemsResponse = {
            dataItems: dataItems,
            totalCount: data["@odata.count"],
            entityData: entityData
        };

        return response;
    }

    private addFiltering(query: any, filter: ExtendedKeyValuePair[], itemsToExclude: KeyValuePair) {
        query = query.where();
        if (filter) {
            filter.forEach((item, index) => {
                if (item.operation >= 0 && ((item.operation & SdkOperation.or) === SdkOperation.or) || ((item.operation & SdkOperation.and) === SdkOperation.and)) {
                    query = (item.operation & SdkOperation.or) === SdkOperation.or ? query.or() : query.and();
                }
                item.value.forEach((keyword) => {
                    const searchTerm = keyword && keyword.trim ? keyword.trim() : keyword;
                    if (item.operation >= 0 && ((item.operation & SdkOperation.eq) === SdkOperation.eq)) {
                        query = query.eq(item.key, searchTerm);
                    } else {
                        if (query.expression.type === "and") {
                            query = query.or();
                        }

                        query = ContentFilterService.applySearchForField(searchTerm, item.key, query, item.searchMode, item.caseSensitive);

                        if (index === filter.length - 1) {
                            query = query.done();
                        }
                    }
                });
                if (item.operation >= 0) {
                    query = query.done();
                }
            });
        }
        if (itemsToExclude && Array.isArray(itemsToExclude.value)) {
            itemsToExclude.value.forEach((key) => {
                query = query.ne(itemsToExclude.key, key);
            });
        }
        query = query.done();
        return query;
    }

    private parseGetItemListBatchResponse(result: any, result$: Subject<any>) {
        const error = this.errorParserService.parseError(result);
        if (error instanceof GenericError) {
            result$.error(error);
            return;
        }

        const batchResponse = result.data[0].response.data;
        let fullResult = [];

        result.data.forEach(data => {
            fullResult = fullResult.concat(data.response.data.value);
        });

        batchResponse.value = fullResult;

        result$.next(batchResponse);
    }
}

