import { Component, Input, OnInit } from "@angular/core";
import { DataContext } from "../../models/data-context-component";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { ModalWindowService, ModalComponentSettings, Button, CancelButton, DeleteButton } from "../../services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { COMMAND_NAMES } from "../../../content/dynamic-modules/components/commands";

@Component({
    selector: "sf-remove",
    templateUrl: "./remove.component.html"
})
export class RemoveComponent implements OnInit {
    @Input() public context: DataContext;
    @Input() public itemToRemove: DataItem;
    @Input() public action: string;
    @Input() public onRemove;

    title: string = "Remove";

    constructor(
        private modalWindowService: ModalWindowService,
        private route: ActivatedRoute,
        private itemService: DynamicItemService) {

    }

    ngOnInit(): void {
        if (this.itemToRemove && this.context.dataItem) {
            this.title = `Remove "${this.itemToRemove.title}" from item`;
        }
    }

    remove() {
        const itemToRemoveFrom = this.context.dataItem;
        const settings = this.generateConfirmationSettings(itemToRemoveFrom);
        this.modalWindowService.openModalConfirmation(this.route.parent, settings, this.itemToRemove, "remove");
    }

    private generateConfirmationSettings(itemToRemoveFrom: DataItem): ModalComponentSettings {
        const confirmButton = new DeleteButton("Remove", true);

        const settings: ModalComponentSettings = {
            title: `Remove "${this.itemToRemove.title}" from...`,
            icon: "unlink",
            parameters: [],
            action: "remove",
            description: itemToRemoveFrom.title,
            hideItemTitle: true,
            buttons: new Array<Button>(confirmButton, new CancelButton()),
            doneCallback: (context) => {
                if (context.data && context.data.data) {
                    this.itemService.executeBoundAction<any>(this.itemToRemove, this.action, {
                        provider: itemToRemoveFrom.data.Provider,
                        id: itemToRemoveFrom.data.Id,
                        contentType: itemToRemoveFrom.data.ContentType
                    }).subscribe(r => {
                        const deletedItem = this.context.dataItem;
                        this.context.invoker.invoke({
                            name: COMMAND_NAMES.removeItem,
                            data: deletedItem
                        });
                    });
                }
            }
        };

        return settings;
    }
}
