import { Component, EventEmitter, Input, OnInit, Output, Renderer2, ViewChild } from "@angular/core";

@Component({
    selector: "sf-card",
    templateUrl: "./card.component.html"
})
export class CardComponent implements OnInit {
    @Input() look: string;
    @Input() cardLabel: string;
    @Input() buttonText: string;
    @Input() selected: boolean;
    @Input() cardTitle: string;
    @Input() dataAttributes: { key: string, value: string }[];
    @Output() onCardSelected = new EventEmitter<Event>();
    @ViewChild("card", { static: true }) card;
    cssClass: string;

    constructor(private renderer: Renderer2) {}

    ngOnInit() {
        this.cssClass = this.generateCssClassList();

        if (this.dataAttributes && this.dataAttributes.length > 0) {

            this.dataAttributes.forEach((pair: { key: string, value: string }) => {
                this.addDataAttributeToCard(pair);
            });
        }
    }

    onCardSelect(event: Event) {
        this.onCardSelected.emit(event);
    }

    addDataAttributeToCard(pair: { key: string, value: string }) {
        this.renderer.setAttribute(this.card.nativeElement, `data-${pair.key}`, pair.value );
    }

    generateCssClassList(): string {
        let cls = "sf-card";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }
        return cls;
    }
}
