import { Injectable } from "@angular/core";
import { ChildCount } from "../modules/content/dynamic-modules/components/grid-cells/list-children-count.component";
import { DynamicModuleChildListOrderPair, ExternalAppConfigService } from "./external-app-config.service";

@Injectable()
export class ReorderModuleChildrenProvider {
    private orderConfig: DynamicModuleChildListOrderPair[];

    constructor(private configService: ExternalAppConfigService) {
        this.orderConfig = this.configService.externalConfig?.dynamicModuleChildListOrder;
    }

    getFirstChildEntitySet(parentType: string): string {
        if (this.orderConfig) {
            const config = this.orderConfig.find(x => x.parentEntitySet === parentType);

            if (config) {
                const first = config.childEntitySets[0];

                if (first) {
                    return first;
                }
            }
        }

        return null;
    }

    reorderChildren(parentType: string, children: ChildCount[]) {
        if (this.orderConfig) {
            const config = this.orderConfig.find(x => x.parentEntitySet === parentType);
            const configuredChildren = config?.childEntitySets;

            if (configuredChildren) {
                configuredChildren.forEach((x, i) => {
                    const foundIndex = children.findIndex(y => y.setName === x);
                    if (foundIndex !== -1) {
                        children.splice(i, 0, children.splice(foundIndex, 1)[0]);
                    }
                });
            }
        }
    }
}
