import { createAction, props } from "@ngrx/store";
import { ColumnState } from "../schemas/schema.columns";

const toggleExpandedPerEntity = createAction(
    "[Columns] Toggle Expanded/Collapsed for a column per entity set",
    props<{ entitySet: string, columnName: string }>()
);

const toggleExpandedPerItem = createAction(
    "[Columns] Toggle Expanded/Collapsed for a column per item",
    props<{entitySet: string, columnName: string, itemId: string, expanded: boolean }>()
);

const setState = createAction(
    "[Columns] Set state",
    props<{ data: ColumnState }>()
);

export const COLUMN_ACTIONS = {
    toggleExpandedPerEntity,
    toggleExpandedPerItem,
    setState
}
