import { first, map } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { ReplaySubject } from "rxjs";
import { HttpODataRequestWrapper } from "../http-odata-request.wrapper";
import { ENTITY_SET } from "./meta-data-constants";
import { stringConstants } from "../../../../common-constants";
import { DynamicItemService, LoadItemsData, LoadItemsResponse } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData } from "../../../content/dynamic-modules/interfaces";
import { QUERY_PARAMS } from "../../../content/constants";

export const CURRENT_SITE_SERVICE_PATH = "sites/current";

@Injectable()
export class SiteDataStore {
    private siteData: ReplaySubject<SiteData>;
    private accessibleEntitySets: ReplaySubject<Array<string>>;
    private isSetAvailable: ReplaySubject<boolean>;
    private sitesCache: ReplaySubject<LoadItemsResponse>;

    constructor(private http: HttpODataRequestWrapper, private dynamicService: DynamicItemService) { }

    getValue(): Observable<SiteData> {
        return this.initialize();
    }

    isEntitySetAccessible(entitySetName: string): Observable<boolean> {
        const accessibleEntitySets$ = this.getAccessibleEntitySets();
        return accessibleEntitySets$.pipe(map(entitySets => entitySets.indexOf(entitySetName) > -1));
    }

    isModuleAvailable(currentModuleName: string): Observable<boolean> {
        const isAvailable$ = this.getEntitySetAvailability(currentModuleName);
        return isAvailable$.pipe();
    }

    getAllowedProvidersFromSiteData(entitySetName: string, siteData: SiteData) {
        const modules = siteData.Modules;
        const module = Object.keys(modules)
            .map(key => modules[key])
            .find(m => m.ModuleTypes.indexOf(entitySetName) > -1);

        let moduleProviders = [];

        // pages are not included in modules. The asterisk should be replaced with the actual provider once we
        // add pages to site modules
        if (module) {
            moduleProviders = module.Providers;
        } else if (entitySetName === ENTITY_SET.FORMS || entitySetName === ENTITY_SET.SITES) {
            moduleProviders = [stringConstants.ASTERISK];
        }

        return moduleProviders;
    }

    getAllowedProviders(entitySetName: string): Observable<string[]> {
        return this.getValue().pipe(
            first(),
            map(s => {
                return this.getAllowedProvidersFromSiteData(entitySetName, s);
            }));
    }

    getAllSites(siteEntityData: EntityData): Observable<LoadItemsResponse> {
        const sitesLoadData = <LoadItemsData>{
            entityData: siteEntityData,
            additionalQueryParams: {
                [QUERY_PARAMS.GET_ALL_ITEMS]: "true"
            },
            order: "Name"
        };

        if (!this.sitesCache) {
            this.sitesCache = new ReplaySubject(1);

            this.dynamicService.getItemList(sitesLoadData).pipe(
                first())
                .subscribe(response => {
                    this.sitesCache.next(response);
                });
        }

        return this.sitesCache.asObservable();
    }

    private initialize(): Observable<SiteData> {
        if (!this.siteData) {
            this.siteData = new ReplaySubject(1);

            this.http
                .get(CURRENT_SITE_SERVICE_PATH)
                .then(data => {
                    this.siteData.next(data.value);
                    this.siteData.complete();
                });
        }

        return this.siteData.asObservable();
    }

    private getAccessibleEntitySets(): Observable<Array<string>> {
        if (!this.accessibleEntitySets) {
            this.accessibleEntitySets = new ReplaySubject<Array<string>>(1);

            this.getValue().pipe(
                first())
                .subscribe(s => {
                    const modules = s.Modules;
                    const moduleNames = Object.keys(modules);
                    const entitySets = moduleNames
                        .map(name => modules[name].AccessibleTypes)
                        .reduce((previous, current) => previous.concat(current));

                    this.accessibleEntitySets.next(entitySets);
                    this.accessibleEntitySets.complete();
                });
        }

        return this.accessibleEntitySets.asObservable();
    }

    private getEntitySetAvailability(currentModuleName: string): Observable<boolean> {
        if (!this.isSetAvailable) {
            this.isSetAvailable = new ReplaySubject<boolean>(1);

            this.getValue().pipe(
                first())
                .subscribe(s => {
                    const modules = s.Modules;
                    const moduleNames = Object.keys(modules);
                    const isAvailable = moduleNames
                        .some(name => name.indexOf(currentModuleName) > -1);

                    this.isSetAvailable.next(isAvailable);
                    this.isSetAvailable.complete();
                });
        }

        return this.isSetAvailable.asObservable();
    }
}

export interface SiteData {
    Id: string;
    Name: string;
    DefaultContentCulture: string;
    ContentCultures: Array<ContentCultureData>;
    Modules: ModuleInfo;
    SiteMapRootNodeId: string;
}

export interface ModuleInfo {
    [moduleName: string]: {
        AccessibleTypes: Array<string>,
        Providers: Array<string>
        ModuleTypes: Array<string>
    }
}

export interface ContentCultureData {
    Name: string;
    DisplayName: string;
}

export interface PersonalizationSegmentData {
    Name: string;
}
