import { Component, Input, OnInit } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { stringConstants } from "../../../../common-constants";
import { DataContextComponent, DataContext } from "../../models/data-context-component";

@Component({
    selector: "sf-children-count",
    templateUrl: "./children-count-component.html"
})
export class ChildrenCountComponent implements OnInit, DataContextComponent {
    @Input() public context: DataContext;
    @Input() public childRouteName: string = "";
    @Input() public dynamicSuffixProp: string;
    @Input() public queryParams: {[key: string]: any} = null;
    @Input() public maxCount = 0;
    @Input() public look: string;
    @Input() public navigateOnClick: boolean = true;
    @Input() public showBadgeForZeroCount: boolean = false;
    public displayCount: string;
    public count: number = 0;
    public cssClassList: string = stringConstants.EMPTY_STRING;

    constructor(private router: Router, private activatedRoute: ActivatedRoute) {
    }

    ngOnInit() {
        const dataItem = this.context.dataItem;
        const model = this.context.model;
        this.count = dataItem.data[model.name] ?? 0;

        if (this.count === 0) {
            this.displayCount = this.showBadgeForZeroCount ? "0" : stringConstants.EN_DASH;
        } else {
            if (this.maxCount > 0 && this.count > this.maxCount) {
                this.displayCount = `${this.maxCount}+`;
            } else {
                this.displayCount = `${this.count}`;
            }
        }

        this.setIconLook();
    }

    public onNavigate(): void {
        if (this.navigateOnClick && this.count > 0) {
            let childRouteName = this.childRouteName;
            if (this.dynamicSuffixProp && this.context.dataItem.data.hasOwnProperty(this.dynamicSuffixProp))
                childRouteName = childRouteName + "-" + this.context.dataItem.data[this.dynamicSuffixProp];

            this.router.navigate([this.context.dataItem.key, childRouteName], { relativeTo: this.activatedRoute, queryParams: this.queryParams });
        }
    }

    private setIconLook() {
        if (this.count > 0 || this.showBadgeForZeroCount) {
            this.cssClassList += "sf-badge -ellipse";
        }

        if (this.look) {
            const lookConcatSymbol = " -";
            this.cssClassList += lookConcatSymbol + this.look.split(" ").join(lookConcatSymbol);
        }

        if (this.count > 0 && this.navigateOnClick) {
            this.cssClassList += " -hover";
        }
    }
}
