import { Injectable } from "@angular/core";
import { Validators } from "@angular/forms";
import { VALIDATORS, VALIDATOR_NAMES } from "../../../../../../fields/common/validators";
import { DateRangeValidator } from "../../../../../../fields/common/validators/date-range.validator";
import { VALIDATOR_MESSAGES } from "../../../../../../fields/common/validators/validators.constants";
import { ValueRangeValidator } from "../../../../../../fields/common/validators/value-range.validator";
import { DateTimePickerSettings } from "../../../../../../fields/date-time/date-time-settings";
import { DECIMAL_NUMBER_REGEX, INT_NUMBER_REGEX } from "../../../../../../fields/number/number-settings";
import { FormFieldWrapperComponent } from "../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../../shared/fields-builder/services/field-change/field-change.service";

const NUMBER_RANGES = "NumberRanges";
const NUMBER_RANGES_DECIMAL = "NumberRangesDecimal";
const DATE_RANGES = "DateRanges";
const FROM_FIELD = "From";
const TO_FIELD = "To";
const NUMBER_VALIDATION_MESSAGE = "Max value should be bigger than min value";
const DATE_VALIDATION_MESSAGE = "End date must not precede start date";

@Injectable()
export class FacetSettingsFieldChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        const findRowIndexRegex = /(\w+)(\d+)(\w+)/;
        const rowIndexMatches = changedFieldName.match(findRowIndexRegex);
        if (rowIndexMatches.length < 4) {
            return;
        }
        const rowIndex = rowIndexMatches[2];
        const fieldType = rowIndexMatches[1];
        const fieldName = rowIndexMatches[3];

        if (fieldName === FROM_FIELD || fieldName === TO_FIELD) {
            this.validateFields(fieldType, rowIndex, fields);
        }
    }

    private validateFields(fieldType: string, rowIndex: string, fields: FormFieldWrapperComponent[]) {
        const fromFieldName = `${fieldType}${rowIndex}${FROM_FIELD}`;
        const toFieldName = `${fieldType}${rowIndex}${TO_FIELD}`;

        const fromField = fields.find(f => f.labelId == fromFieldName);
        const toField = fields.find(f => f.labelId == toFieldName);

        if (fromField && toField) {
            const fromFieldValue = fromField.getValue();
            const errors = this.getFieldErrorMessage(fieldType);

            if (fromFieldValue !== null && fromField !== undefined) {
                let validator = ValueRangeValidator.validate;

                let minFieldValue = fromFieldValue;
                if (fieldType === DATE_RANGES) {
                    // sets the min value of the end date
                    const settings = <DateTimePickerSettings>toField.currentInstance.settings;
                    const minDate = new Date(fromFieldValue);
                    minDate.setDate(minDate.getDate() + 1);
                    settings.minValue = minDate;
                    minFieldValue = minDate;

                    validator = DateRangeValidator.validate;
                } else if (fieldType === NUMBER_RANGES) {
                    minFieldValue = +fromFieldValue + 1;
                } else if (fieldType === NUMBER_RANGES_DECIMAL) {
                    minFieldValue = +fromFieldValue + 0.0001;
                }

                const validaTorsToAdd = [
                    validator({
                        min: minFieldValue,
                        customErrorObject: errors
                    }),
                    Validators.required
                ];

                fieldType = this.addDefaultValidators(fieldType, validaTorsToAdd);
                toField.formControl.setValidators(validaTorsToAdd);

                toField.formControl.updateValueAndValidity();
            }
        }
    }

    private addDefaultValidators(fieldType: string, validaTorsToAdd: Validators[]) {
        if (fieldType === NUMBER_RANGES) {
            validaTorsToAdd.push(Validators.pattern(INT_NUMBER_REGEX));
            validaTorsToAdd.push(VALIDATORS[VALIDATOR_NAMES.DIGITS_LIMIT](16));
            validaTorsToAdd.push(VALIDATORS[VALIDATOR_NAMES.MAX_INTEGER]());
        } else if (fieldType === NUMBER_RANGES_DECIMAL) {
            validaTorsToAdd.push(Validators.pattern(DECIMAL_NUMBER_REGEX("10")));
            validaTorsToAdd.push(VALIDATORS[VALIDATOR_NAMES.DIGITS_LIMIT](16));
            validaTorsToAdd.push(VALIDATORS[VALIDATOR_NAMES.MAX_INTEGER]());
        }

        return fieldType;
    }

    private getFieldErrorMessage(fieldType: string) {
        if (fieldType === DATE_RANGES) {
            return {
                [VALIDATOR_MESSAGES.CUSTOM_ERRORS]: DATE_VALIDATION_MESSAGE
            };
        }

        if (fieldType === NUMBER_RANGES || fieldType === NUMBER_RANGES_DECIMAL) {
            return {
                [VALIDATOR_MESSAGES.CUSTOM_ERRORS]: NUMBER_VALIDATION_MESSAGE
            };
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === NUMBER_RANGES || typeFullName === DATE_RANGES || typeFullName === NUMBER_RANGES_DECIMAL;
    }
}

export const FACET_SETTINGS_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: FacetSettingsFieldChangeService,
    multi: true
};
