import { ActivatedRoute, Params, Router } from "@angular/router";
import { Observable ,  BehaviorSubject ,  ReplaySubject } from "rxjs";

export abstract class AuxServiceBase<TData> {
    protected _activityStatus: BehaviorSubject<ActivityStatus>;
    protected routeStack: Array<StackData>;
    private mappings: Map<string, WrappedData>;
    private globalCommand = new ReplaySubject<Command>(1);

    protected get active(): boolean {
        return this.routeStack.length > 0;
    }

    get activityStatus(): Observable<ActivityStatus> {
        return this._activityStatus.asObservable();
    }

    get currentActivityStatus(): ActivityStatus {
        return this._activityStatus.getValue();
    }

    getCommands(key: string): Observable<Command> {
        const entry = this.mappings.get(key);
        if (entry && entry.command) {
            return entry.command.asObservable();
        }

        return this.globalCommand.asObservable();
    }

    constructor(private router: Router) {
        this.mappings = new Map<string, WrappedData>();
        this.routeStack = new Array<StackData>();
        this._activityStatus = new BehaviorSubject<ActivityStatus>({ active: false, route: null });
    }

    getData(key: string): TData {
        if (this.mappings.has(key))
            return this.mappings.get(key).data;

        return null;
    }

    setData(key: string, value: TData): void {
        this.mappings.set(key, {
            data: value,
            command: new ReplaySubject(1)
        });
    }

    reset(): void {
        this.mappings.clear();
    }

    show(routeKey: string, auxParentRoute: ActivatedRoute, queryParams?: Params) {
        if (!this.mappings.has(routeKey)) {
            throw new Error(`The key ${routeKey} has no auxiliary mapping defined. Use setMapping to set a value.`);
        }

        if (!auxParentRoute) {
            throw new Error("No relative route to navigate to.");
        }

        if (this.active) {
            const lastRoute = this.routeStack[this.routeStack.length - 1];
            if (lastRoute.key === routeKey) {
                // do nothing if openning the same route
                return;
            }
        }

        const settings = this.getSettings();
        // add current state onto stack
        this.routeStack.push({
            key: routeKey,
            route: auxParentRoute
        });

        const routePath = `${settings.prefix}/${routeKey}`;
        this._activityStatus.next({
            route: routeKey,
            active: this.active
        });

        this.navigate(settings, routePath, auxParentRoute, queryParams);
    }

    hide(auxParentRoute: ActivatedRoute = null, closeAll: boolean = false): Promise<boolean> {
        // remove the top entry, because it is no longer needed
        // but navigate relative to where it was
        const settings = this.getSettings();

        if (auxParentRoute === null && !this.active) {
            throw new Error("Cannot navigate as there is no active state and a parent route is not provided.");
        }

        let routePath = null;

        const currentRoute = this.getCurrentRoute(closeAll);
        if (currentRoute) {
            auxParentRoute = currentRoute.route;

            this._activityStatus.next({
                route: currentRoute.key,
                active: this.active
            });

            if (this.active) {
                routePath = `${settings.prefix}/${currentRoute.key}`;
            }
        }

        return this.navigate(settings, routePath, auxParentRoute);
    }

    sendCommand(key: string, command: Command) {
        if (this.mappings.has(key)) {
            const command$ = this.mappings.get(key).command;
            command$.next(command);
        }

        this.globalCommand.next(command);
    }

    protected abstract getSettings(): AuxSettings;

    private navigate(settings: AuxSettings, routePath: string, auxParentRoute: ActivatedRoute, queryParams?: Params): Promise<boolean> {
        const navParams = {
            outlets: {
                [settings.outletName]: routePath
            }
        };
        return this.router.navigate([navParams], { relativeTo: auxParentRoute, queryParamsHandling: "merge", queryParams: queryParams });
    }

    private getCurrentRoute(closeAll: boolean): StackData {
        if (!this.active) {
            return;
        }

        if (closeAll) {
            // empty the whole array and proceed to closing
            // the above check should ensure that we have a parent route to navigate relative to
            const currentRoute = this.routeStack.shift();
            this.routeStack.length = 0;

            return currentRoute;
        } else {
            // in case there is only one entry remaining, close the auxiliry route
            let currentRoute = this.routeStack.pop();

            // in case there are two or more remaining, navigate to the previous route
            if (this.active) {
                currentRoute = this.routeStack[this.routeStack.length - 1];
            }

            return currentRoute;
        }
    }
}

export interface AuxSettings {
    prefix: string;
    outletName: string;
}

interface StackData {
    key: string;
    route: ActivatedRoute;
}

export interface ActivityStatus {
    route: string;
    active: boolean;
}

interface Command {
    name: string;
    data: any;
}

interface WrappedData {
    data: any;

    command: ReplaySubject<Command>;
}
