import { Component, ViewEncapsulation, OnInit, ViewChild, OnDestroy, Inject, Renderer2, ElementRef, AfterViewInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";

import { DialogData, ModalWindowService, CloseModalCallback, ClosingContext, CanCloseModal, ConfirmButton } from "../../services/modal-window.service";
import { Button, ClickResult, ClosingContextType, CancelButton } from "../../services/modal-window.service";
import { AuxHostComponent } from "../../auxiliary/aux-host.component";

import { Observable, Subscription, BehaviorSubject, of as observableof } from "rxjs";

import { WINDOW_TOKEN } from "../../../../window.provider";
import { ScrollService } from "../../../../services/scroll.service";
import { stringConstants, SAME_TAB_TARGET } from "../../../../common-constants";
import { environmentTypes } from "../../../../environment";
import { EnvironmentService } from "../../services/environment.service";
import { KeyboardShortcutsService, KeyboardAction } from "../../../../services/keyboard-shortcuts.service";
import { CHARACTERS, COMPONENT_NAMES } from "../../../content/constants";
import { OPERATION_NAMES } from "../action-menu/operation.model";
import { NotificationLoaderComponent } from "../notifications/notification-loader/notification-loader.component";
import { KeyboardActionType } from "../../../../services/keyboard-shortcuts.constants";
import { isElementVisible } from "../../../../utils";
import { SfDynamicComponentLoaderComponent } from "@progress/sitefinity-component-framework";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ActionMenuOptions } from "../action-menu/action-menu-model";

const MODAL_WINDOW_OPEN_CLASS = "-sf-modal-window-open";
const NO_SELECTION_CLASS = " -no-selection";
const ADDITIONAL_ANIMATION_LOAD_TIME_IN_MS = 1000;
const PRIMARY_BUTTON_SELECTOR = ".sf-button.-action";
const PRIMARY_DELETE_BUTTON_SELECTOR = ".sf-button.-delete";
export const SHOW_BUTTONS = "show-buttons";
export const SHOW_HEADING_BUTTONS = "show-heading-buttons";
export const SHOW_CLOSE_BUTTON = "show-close-buttons";
export const MODAL_WINDOW_NOTIFICATION_FILTER = "modal-window";

// TODO: should work with action menu to reuse logic from there
@Component({
    selector: "sf-modal-window",
    templateUrl: "./modal-window.component.html",
    styleUrls: ["./modal-window.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class ModalWindowComponent extends AuxHostComponent<ModalWindowService> implements OnInit, OnDestroy, AfterViewInit {
    @ViewChild("mainContentLoader", { static: false }) componentLoader: SfDynamicComponentLoaderComponent;
    @ViewChild("modal", { static: false }) modal: ElementRef;

    notificationLoaderComponent: ComponentData = {
        type: NotificationLoaderComponent,
        properties: {
        filter: MODAL_WINDOW_NOTIFICATION_FILTER,
        look: "fixed"
    }};

    currentData: DialogData;
    closeButtonDisabled: boolean = false;
    modalWindowClassList: string;
    public dropDownMenuOptions: ActionMenuOptions;
    get areButtonsVisible(): Observable<boolean> {
        return this._areButtonsVisible.asObservable();
    }

    get areHeadingButtonsVisible(): Observable<boolean> {
        return this._areHeadingButtonsVisible.asObservable();
    }

    get isModalClosable(): Observable<boolean> {
        return this._isModalClosable.asObservable();
    }

    private _areButtonsVisible: BehaviorSubject<boolean>;
    private _areHeadingButtonsVisible: BehaviorSubject<boolean>;
    private _isModalClosable: BehaviorSubject<boolean> = new BehaviorSubject(true);
    private _visibilitySubscription: Subscription;
    private _closed: boolean = false;

    constructor(route: ActivatedRoute,
                service: ModalWindowService,
                private environtmentService: EnvironmentService,
                @Inject(WINDOW_TOKEN) private windowProvider: Window,
                private scrollService: ScrollService,
                private renderer: Renderer2,
                private keyboardShortcutsService: KeyboardShortcutsService,
                private elementRef: ElementRef) {
        super(route);
        this.renderer.addClass(this.windowProvider.document.documentElement, MODAL_WINDOW_OPEN_CLASS);
        this.service = service;
        this.dropDownMenuOptions = new ActionMenuOptions(undefined, undefined, true);
    }

    ngOnInit() {
        super.ngOnInit();

        this.handleKeyboardShortcuts();
    }

    ngAfterViewInit() {
        this.focusModalWrapper();
    }

    protected onMappingChanged(mapping: DialogData, url: string) {
        // workaround to fix a bug in angular that is hard to reproduce, but results in nested dialogs not closing properly
        this.currentData = { ...mapping };

        this.focusModalWrapper();

        if (!this.service.currentActivityStatus) {
            return;
        }

        this._areButtonsVisible = new BehaviorSubject(this.currentData.showButtonsOnInit);
        this._areHeadingButtonsVisible = new BehaviorSubject(this.currentData.showButtonsOnInit);
        this._isModalClosable = new BehaviorSubject(this.currentData.isModalClosable);

        if (this._visibilitySubscription) {
            this._visibilitySubscription.unsubscribe();
        }

        const currentRoute = this.service.currentActivityStatus.route;

        this._visibilitySubscription = this.service.getCommands(currentRoute).subscribe((message) => {
            if (message.name === SHOW_BUTTONS) {
                this._areButtonsVisible.next(message.data);
            }

            if (message.name === SHOW_HEADING_BUTTONS) {
                this._areHeadingButtonsVisible.next(message.data);
            }

            if (message.name === SHOW_CLOSE_BUTTON) {
                this._isModalClosable.next(message.data);
            }
        });

        this.registerSubscription(this._visibilitySubscription);

        // make sure that pressing back button has not messed up service data
        this.service.ensureRouteState(url);
        this.modalWindowClassList = this.currentData.contentClass;
    }

    ngOnDestroy() {
        if (!this._closed) {
            this.onCloseClicked();
        }

        super.ngOnDestroy();
        this.keyboardShortcutsService.removeListener(COMPONENT_NAMES.MODAL_WINDOW);
        this.renderer.removeClass(this.windowProvider.document.documentElement, MODAL_WINDOW_OPEN_CLASS);
    }

    public onComponentInit(component: any) {
        this.setCloseModalCallback(component);
    }

    public onCloseClicked() {
        const canClose = this._isModalClosable.getValue();
        if (canClose) {
            const context = this.buildContext(ClosingContextType.CloseClicked);
            this.close(context);
        }
    }

    public invokeButtonClick(sourceButton: Button, event: MouseEvent | KeyboardEvent) {
        const clickHandler = sourceButton.handlers.click;
        if (!clickHandler)
            throw new Error(`Invalid click handler provided for button ${sourceButton.content}`);

        const clickResult = clickHandler({
            event: event,
            component: this.hostedInstance
        });

        if (clickResult instanceof Observable) {
            const clickResultSubscription: Subscription = clickResult.subscribe((result: ClickResult) => {
                this.processClickResult(result, result.load, this.currentData.disableUserInteractionOnLoading, sourceButton);
            });
            this.registerSubscription(clickResultSubscription);
        } else {
            this.processClickResult(clickResult, false, false, sourceButton);
        }
    }

    protected onBackToTopClicked() {
        this.scrollService.scrollToTop(true, 250);
    }

    private canClose(context: ClosingContext): Observable<boolean> {
        const hostedInstance = this.hostedInstance as CanCloseModal;
        if (hostedInstance && hostedInstance.canCloseCallback) {
            const result = hostedInstance.canCloseCallback(context);
            if (!(result instanceof Observable)) {
                return observableof(result);
            }

            return result;
        }

        return observableof(true);
    }

    private setCloseModalCallback(hostedInstance: CloseModalCallback) {
        /** Casting here is only for readability, practically only components that have
         * the necessary callback setter method will be used.
         * JS and TS do not support runtime interface checking.
        */
        if (hostedInstance && hostedInstance.setCloseModalCallback) {
            hostedInstance.setCloseModalCallback(this.closeModalCallback.bind(this));
        }
    }

    private closeModalCallback(exitData) {
        const context = this.buildContext(ClosingContextType.DoneCalled, exitData);
        this.close(context);
    }

    private processClickResult(clickResult: ClickResult, load: boolean = true, disableUserInteraction: boolean = false, sourceButton: Button = null): void {
        if (clickResult.hasErrors) {
            this.toggleButtonLoading(null, false, false, false, sourceButton);
            return;
        }

        const loadTime = load ? ADDITIONAL_ANIMATION_LOAD_TIME_IN_MS : 0;
        if (loadTime) {
            this.toggleButtonLoading(sourceButton.loadIcon, true, false, disableUserInteraction, sourceButton);
        }

        if (clickResult.isSuccessful) {
            const context = this.buildContext(ClosingContextType.ButtonClicked, clickResult);
            if (loadTime) {
                this.toggleButtonLoading(null, false, true, false, sourceButton);
                this.windowProvider.setTimeout(() => this.close(context), loadTime);
            } else {
                this.close(context);
            }

        }
    }

    private toggleButtonLoading(loader: string, disabled: boolean, checked, disableUserInteraction: boolean, sourceButton: Button = null): void {

        const buttons = this.currentData.buttons;
        const confirmButtonClicked: any = buttons.find(b => b instanceof ConfirmButton && b.content === sourceButton.content);
        const confirmButtons: Button[] = buttons.filter(b => b instanceof ConfirmButton && b.content !== sourceButton.content);
        const cancelButton: any = buttons.find(b => b instanceof CancelButton);


        if (confirmButtonClicked) {
            confirmButtonClicked.loader.next(loader);
            confirmButtonClicked.disabled.next(disabled);
            confirmButtonClicked.checked.next(checked);
        }

        if (confirmButtons && confirmButtons.length > 0) {
            confirmButtons.forEach(confirmButton => {
                confirmButton.disabled.next(disabled);
            });
        }

        if (cancelButton) {
            cancelButton.disabled.next(disabled);
        }

        this.closeButtonDisabled = disableUserInteraction;
        this.toggleNoSelectionOverlay(disableUserInteraction);
    }

    private toggleNoSelectionOverlay(disableUserInteraction: boolean) {
        this.modalWindowClassList = this.modalWindowClassList || stringConstants.EMPTY_STRING;

        if (disableUserInteraction) {
            this.modalWindowClassList += NO_SELECTION_CLASS;
        } else {
            this.modalWindowClassList.replace(NO_SELECTION_CLASS, stringConstants.EMPTY_STRING);
        }
    }

    private close(context: ClosingContext): void {
        const currentData = this.currentData;
        const result = this.canClose(context);
        result.subscribe((canClose) => {
            if (!canClose) {
                return;
            }

            super.onClose().then(() => {
                if (currentData) {
                    if (currentData.doneCallback) {
                        currentData.doneCallback(context);
                    }

                    if (currentData.componentData && this.componentLoader) {
                        // Need to destroy the initial component loader otherwise if another component is loaded the main one will not be destroyed
                        this.componentLoader.destroy(currentData.componentData);
                    }
                }
            });

            this._closed = true;
        });
    }

    private buildContext(type: ClosingContextType, data: any = null): ClosingContext {
        return {
            type: type,
            data: data,
            component: this.hostedInstance
        };
    }

    private get hostedInstance(): any {
    if (this.componentLoader) {
            return this.componentLoader.currentInstance;
        }

        return null;
    }

    private handleKeyboardShortcuts() {
        const keyboardShortcutsSubscriptions = this.keyboardShortcutsService.addListener(observableof(null), COMPONENT_NAMES.MODAL_WINDOW, false).subscribe((action: KeyboardAction) => {
            if (!action) {
                return;
            }

            let button: Button;
            switch (action.type) {
                case KeyboardActionType.Escape:
                    this.onCloseClicked();
                    break;
                case KeyboardActionType.CommonConfirm:
                    action.event.preventDefault();
                    this.handleCommonConfirmation();
                    break;
                case KeyboardActionType.Refresh && environmentTypes.integration === this.environtmentService.getEnvironment():
                    this.handleRefreshFromModal(action.event);
                    break;
                // TODO: these should come from Operation
                case KeyboardActionType.Save:
                    button = this.currentData.buttons.find(b => b.name === OPERATION_NAMES.uploadDraft);
                    this.triggerKeyboardAction(button, action.event);
                    break;
                case KeyboardActionType.Publish:
                    button = this.currentData.buttons.find(b => b.name === OPERATION_NAMES.upload || b.name === OPERATION_NAMES.uploadPublished);
                    this.triggerKeyboardAction(button, action.event);
                    break;
            }
        });

        this.registerSubscription(keyboardShortcutsSubscriptions);
    }

    //clicking buttons by code, because we don't always have access to the button through currentData
    //sometimes they are inside the view of the hosted component
    private handleCommonConfirmation(): void {
        const primaryButtons = this.elementRef.nativeElement.querySelectorAll(`${PRIMARY_BUTTON_SELECTOR},${PRIMARY_DELETE_BUTTON_SELECTOR}`);
        if (primaryButtons.length > 0) {
            //sometimes multiple views are open in the modal, we should click only the visible action button
            const visiblePrimaryButton = Array.from(primaryButtons).find(item => isElementVisible(this.windowProvider, item as HTMLElement));

            if (visiblePrimaryButton) {
                (visiblePrimaryButton as HTMLElement).click();
            }
        }
    }

    private triggerKeyboardAction(button: Button, event: KeyboardEvent) {
        if (!button) {
            return;
        }

        event.preventDefault();
        this.invokeButtonClick(button, event);
    }

    private handleRefreshFromModal(event: KeyboardEvent) {
        let location = this.windowProvider.location.href;
        let startIndex = location.indexOf("dialog:");
        if (startIndex !== -1) {
            while (location[startIndex - 1] === stringConstants.FORWARD_SLASH) startIndex--;

            const endIndex = location.lastIndexOf(CHARACTERS.CLOSE_BRACKET);
            const subString = location.substring(startIndex, endIndex);

            location = location.replace(subString, stringConstants.EMPTY_STRING);
            location = location.replace(CHARACTERS.OPEN_BRACKET, stringConstants.EMPTY_STRING);
            location = location.replace(CHARACTERS.CLOSE_BRACKET, stringConstants.EMPTY_STRING);
            event.preventDefault();

            this.windowProvider.open(location, SAME_TAB_TARGET);
        }
    }

    private focusModalWrapper() {
        if (this.modal) {
            this.modal.nativeElement.focus();
        }
    }
}
