import { Component, OnInit, ViewChild } from "@angular/core";
import { DataItem } from "../content/dynamic-modules/interfaces";
import { FILTER_PARAMS } from "../content/constants";
import { MediaService } from "./services/media.service";
import { ScrollService } from "../../services/scroll.service";

@Component({
    selector: "sf-file-reorder",
    templateUrl: "./file-reorder.component.html"
})
export class FileReorderComponent implements OnInit {
    parentEntityData: DataItem;
    childEntityData: DataItem;
    value: DataItem[] = [];
    isInitialLoading = true;
    heading = "Reorder";

    get mediaItems() {
        return this.list.mediaItems;
    }

    get isDirty(): boolean {
        return this.list.hasChanges;
    }

    @ViewChild("fileList", {static: true})
    list;

    constructor(public scrollService: ScrollService, private mediaService: MediaService) {
    }

    ngOnInit(): void {
        this.heading = `Reorder ${this.childEntityData.metadata.displayName.toLowerCase()} in library`;
        this.getImages().subscribe((res) => {
            this.value = res.dataItems;
            this.isInitialLoading = false;
            if (this.value.length < res.totalCount) {
                this.loadMoreFiles();
            }
        });
    }

    loadMoreFiles() {
        if (!this.isInitialLoading) {
            this.mediaService.getMediaForLibrary(this.childEntityData, this.parentEntityData.data.Id, this.value.length, null, null, null, {[FILTER_PARAMS.SORT]: "Ordinal"}).subscribe(res => {
                if (res.dataItems.length > 0) {
                    this.value.push(...res.dataItems);
                    this.list.mediaItems = this.value;
                }
            });
        }
    }

    private getImages() {
        return this.mediaService.getMediaForLibrary(this.childEntityData, this.parentEntityData.data.Id, null, null, null, null, {[FILTER_PARAMS.SORT]: "Ordinal"});
    }
}
