import { Injectable } from "@angular/core";
import { Subscription, Observable, ReplaySubject } from "rxjs";
import { CommunicationEvent } from "../events/component-events";
import { filter } from "rxjs/operators";

@Injectable()
export class ComponentCommunicationService {
    private communicator = new Map<any, ReplaySubject<CommunicationEvent<any>>>();

    subscribe<TData, TEvent extends CommunicationEvent<TData>>(eventType: new (data: TData) => TEvent, cb: (ev: TEvent) => void): Subscription {
        return this.getEventStream(eventType).subscribe(cb);
    }

    // Return an observable with the event, that the subscriber has passed
    getEventStream<TData, TEvent extends CommunicationEvent<TData>>(eventType: new (data: TData) => TEvent): Observable<CommunicationEvent<any>> {
        const eventStream = this.getOrCreateCommunicationEventStreamByType(eventType);
        return eventStream.pipe(filter(e => !!e));
    }

    next<TData, TEvent extends CommunicationEvent<TData>>(ev: TEvent, replay: boolean = true) {
        if (!ev) {
            return;
        }

        const eventStream = this.getOrCreateCommunicationEventStreamByItem(ev);
        eventStream.next(ev);

        if (!replay) {
            eventStream.next(null);
        }
    }

    private getOrCreateCommunicationEventStreamByType<TData, TEvent extends CommunicationEvent<TData>>(eventType: new (data: TData) => TEvent): ReplaySubject<CommunicationEvent<any>> {
        let eventStream = this.communicator.get(eventType);
        if (!eventStream) {
            eventStream = new ReplaySubject<CommunicationEvent<any>>(1);
            this.communicator.set(eventType, eventStream);
        }

        return eventStream;
    }

    private getOrCreateCommunicationEventStreamByItem<TData, TEvent extends CommunicationEvent<TData>>(ev: TEvent): ReplaySubject<CommunicationEvent<any>> {
        let eventStream = this.communicator.get(ev.constructor);
        if (!eventStream) {
            eventStream = new ReplaySubject<CommunicationEvent<any>>(1);
            this.communicator.set(ev.constructor, eventStream);
        }

        return eventStream;
    }
}
