import { ReplaySubject } from "rxjs";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { HttpODataRequestWrapper } from "../../../shared/services/http-odata-request.wrapper";
import { HttpHeaders, HttpParams } from "@angular/common/http";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { FormHelpers } from "../../../forms/form.helpers";

@Injectable()
export class ProviderService {
    constructor(
        private httpRequestWrapper: HttpODataRequestWrapper) {
    }

    getProviders(entitySet: string, options?: RequestOptionsArgs): Observable<Provider[]> {
        const replSubj = new ReplaySubject<Provider[]>(1);
        // hack for providers for form responses
        // the ideal solution here would for this not to be called at all since the providers
        // for form and form responses are the same. Same case for blog and blog posts
        if (FormHelpers.isFormResponseType(entitySet))
            entitySet = ENTITY_SET.FORMS;

        this.httpRequestWrapper.get(`${entitySet}/sfproviders`, options).then(result => {
            replSubj.next(result.value);
        });

        return replSubj;
    }
}

export interface Provider {
    name: string;
    title: string;
    isDefault: boolean;
}

// TODO: Substitute with better
export interface RequestOptionsArgs {
    headers?: HttpHeaders | {
        [header: string]: string | string[];
    };
    params?: HttpParams | {
        [param: string]: string | string[];
    };
    reportProgress?: boolean;
    responseType?: 'arraybuffer' | 'blob' | 'json' | 'text';
    withCredentials?: boolean;
}
