import { KEYS } from "./modules/shared/services/settings-keys";
import { StorageService } from "./modules/shared/services/storage.service";
import { DEFAULT_BASE_HREF } from "./common-constants";
import { environmentTypes } from "./environment";
import { environment } from "../environments/environment";

export class AppBaseHrefFactory {
    public getBaseHref(storageService: StorageService, documentService: Document): string {
        const IRIS = AppBaseHrefFactory.getEnvironmentVariables();

        // If the environment is not "integration" respect the base tag if the client has specified it
        if (IRIS.ENV !== environmentTypes.integration) {
            const baseTag = documentService.getElementsByTagName("base")[0];
            if (baseTag) {
                // baseTag.href is not used here
                // because it returns resolved absolute path whereas
                // we need the relative path only
                const hrefAttribute = baseTag.attributes.getNamedItem("href");
                const hrefValue = hrefAttribute.nodeValue;
                if (hrefValue) {
                    return hrefValue;
                }
            }
        }

        // externalPath should contain full sub-route (e.g. /SubApp/Sitefinity/adminapp)
        // if externalPath is not defined - use the default base href
        const externalPath = storageService.getItem(KEYS.EXTERNAL_PATH);
        if (!externalPath) {
            return DEFAULT_BASE_HREF;
        }

        return externalPath;
    }

    static getEnvironmentVariables(): any {
        return {
            ENV: environment.env
        };
    }
}
