import { Component, OnInit } from "@angular/core";
import { FieldSectionModel, FieldSectionSettings } from "../../../../services/fieldSection.model";
import { FieldModel } from "../../../../services/field.model";
import { FieldTypes } from "../../fields-builder/services/fields-registry";
import { createFieldModel } from "../../fields.constants";
import { CompositeFieldsProvider } from "../../fields-builder/providers/fields-provider";
import { DynamicItemStore } from "../../../content/dynamic-modules/services/dynamic-item.store";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { delayEmission, toLoadingState } from "../../rxjs-extensions";
import { MINIMUM_LOADER_TIME } from "../../../../../../fields/loader-wrapper/loader-wrapper.component";
import { map, tap } from "rxjs/operators";
import { UnboundFunctionData } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { EditableTableComponent } from "../../fields-builder/components/editable-table/editable-table.component";
import { groupBy, unique } from "../../../../utils";
import { stringConstants } from "../../../../common-constants";
import { NOTIFICATIONS_FIELD_CLASS_MAPPER } from "../../../widget-editor/providers/fields/field-type-mapper";

const NOTIFICATIONS_PREFERENCE_TYPE: string = "Notifications";
interface Preference {
    key: string;
    name: string;
}

interface PreferenceSections {
    section: FieldSectionModel
    innerSections: FieldSectionModel[]
}

@Component({
    selector: "sf-notifications-preferences",
    templateUrl: "./notifications-preferences.component.html"
})
export class NotificationsPreferencesComponent extends SfRxBase implements OnInit {
    preferenceSections: Array<PreferenceSections> = []

    constructor(private fieldsProvider: CompositeFieldsProvider, private readonly dynamicItemStore: DynamicItemStore) {
        super();
    }

    ngOnInit() {
        this.initialize();
    }

    onChange(field, editableTable: EditableTableComponent) {
        if (!field) return;

        const preference = this.getValueFromFieldName(field.key);

        const preferenceParameters = {
            Key: preference.key,
            Value: field.value,
            PreferenceType: NOTIFICATIONS_PREFERENCE_TYPE,
            PreferenceName: preference.name
        };

        const functionData: any = {
            data: {
                preferenceParameters
            }
        };

        const preferencesSubscription = this.dynamicItemStore.service.executeUnboundFunction<any>("Default.SetUserPreference", (functionData as UnboundFunctionData))
            .pipe(
                toLoadingState(),
                delayEmission(MINIMUM_LOADER_TIME),
                map(x => x.isLoading),
                tap(isLoading => {
                    if (!isLoading) {
                        editableTable.writeValueToField(field.key, field.value);
                    }
                })
            ).subscribe();
        this.registerSubscription(preferencesSubscription);
    }

    private initialize() {
        this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetUserPreferences(preferenceType='${NOTIFICATIONS_PREFERENCE_TYPE}')`).subscribe((response) => {
            const sections: any[] = JSON.parse(response.value);
            const notificationTypes = unique<any>(sections.flatMap(s => s.Fields), "PreferenceName").map(f => {return {preferenceName: f.PreferenceName, preferenceTitle: f.PreferenceTitle}});
            sections.forEach(section => {
                const sectionOptions: FieldSectionSettings = {
                    isMain: false,
                    isExpanded: false,
                    insertHorizontalRule: true,
                    title: section.Title,
                    name: section.Name,
                };

                const preferenceSection: PreferenceSections = {
                    section: new FieldSectionModel(sectionOptions),
                    innerSections: []
                };

                const fields: any[] = Object.values(section.Fields);
                const preferenceGroups = groupBy(fields, f => f.Key);

                Object.keys(preferenceGroups).forEach(p => {
                    const preferences = preferenceGroups[p];
                    const tableSection = new FieldSectionModel({
                        isMain: false,
                        isExpanded: false,
                        insertHorizontalRule: false,
                        cssClass: "-col-size-4xl"
                    });

                    const children: FieldModel[] = [];
                    notificationTypes.forEach(pt => {
                        const cssClass = NOTIFICATIONS_FIELD_CLASS_MAPPER.get(pt.preferenceName);
                        let fieldName: string = null;
                        let fieldValue: boolean = true;
                        let fieldTitle: string = pt.preferenceTitle;
                        let isReadOnly: boolean = true;

                        const preference = preferences.find(p => p.PreferenceName == pt.preferenceName);
                        if (preference) {
                            fieldName = this.buildFieldName({ key: preference.Key, name: preference.PreferenceName });
                            fieldValue = preference.Value as boolean;
                            fieldTitle = preference.PreferenceTitle;
                            isReadOnly = !preference.Configurable;

                            if (!tableSection.settings.name) {
                                tableSection.settings.name = preference.Key;
                                tableSection.settings.title = preference.Title;
                            }
                        }

                        const fieldModel = createFieldModel(this.fieldsProvider, null, FieldTypes.switch, fieldName, fieldValue, null, fieldTitle, null, isReadOnly, cssClass);
                        children.push(fieldModel);
                    });

                    children.forEach(c => c.settings.showTitle = false);
                    tableSection.fields = children;
                    preferenceSection.innerSections.push(tableSection);
                });

                this.preferenceSections.push(preferenceSection);
            });

            this.preferenceSections[0].section.settings.isExpanded = true;
        });
    }

    private buildFieldName(preference: Preference) {
        return preference.name + stringConstants.SEMICOLON + preference.key;
    }

    private getValueFromFieldName(fieldName: string): Preference {
        const fieldValues = fieldName.split(stringConstants.SEMICOLON);

        return { name: fieldValues[0], key: fieldValues[1] };
    }
}
