import { Injectable } from "@angular/core";
import { SanitizeService } from "../../../../services/sanitize.service";
import { FieldWrapper } from "../components/field-wrapper/form-field-wrapper.component";
import { FieldModel } from "../../../../services/field.model";
import { MirrorFieldSettings, isMirrorFieldSettings } from "../../../../../../fields/short-text/short-text-settings";
import { Properties } from "../../fields.constants";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { Subscription } from "rxjs";
import { stringConstants } from "../../../../common-constants";
import { FieldTypes } from "./fields-registry";

@Injectable()
export class MirrorService {
    private focusSubscription: Subscription;
    private mirrorMappings: { [Key: string]: MirrorMapping[]; } = {};

    constructor(private sanitizeService: SanitizeService) {
    }

    mirrorValue(value: any, key: string, wrapperComponents: FieldWrapper[], copyMode: boolean = false) {
        // this is the case when we are editing a field that should be mirrored from another field
        // if we delete the value from it, on focus out the value should be mirrored

        if (value === stringConstants.EMPTY_STRING) {
            for (const mirroredFieldKey in this.mirrorMappings) {
                if (this.mirrorMappings.hasOwnProperty(mirroredFieldKey)) {
                    const mappings = this.mirrorMappings[mirroredFieldKey];
                    mappings.forEach(mirrorMapping => {
                        if (mirrorMapping.key === key && mirrorMapping.shouldMirror) {
                            if (!mirrorMapping.wrapper)
                                mirrorMapping.wrapper = this.getWrapper(mirrorMapping.key, wrapperComponents);

                            if (mirrorMapping.wrapper.focus) {
                                let mirroredFieldWrapper = this.getWrapper(mirroredFieldKey, wrapperComponents);
                                let valueToWrite = mirroredFieldWrapper.getValue();

                                if (!valueToWrite) {
                                    // If the value is empty, then check if the field we mirror from is also a MirrorField
                                    // In this case take its value
                                    if (isMirrorFieldSettings(mirroredFieldWrapper.fieldModel.settings) && mirroredFieldWrapper.fieldModel.settings.mirroredFieldName) {
                                        mirroredFieldWrapper = this.getWrapper(mirroredFieldWrapper.fieldModel.settings.mirroredFieldName, wrapperComponents);
                                        valueToWrite = mirroredFieldWrapper.getValue() || (<any>mirroredFieldWrapper).value;
                                    } else {
                                        valueToWrite = (<any>mirroredFieldWrapper).value;
                                    }
                                }
                                const mirroredFieldProperty = (<any>mirrorMapping.wrapper.fieldModel.settings).mirroredFieldProperty;
                                valueToWrite = this.getMirroredValueProperty(valueToWrite, mirroredFieldProperty);

                                // If the mirroring is from HTMLField, then the html should be stripped
                                const strippedValue = this.isHTMLField(mirroredFieldWrapper.fieldModel) ? this.stripHtml(valueToWrite) : valueToWrite;

                                if (!this.focusSubscription || this.focusSubscription.closed) {
                                    this.focusSubscription = mirrorMapping.wrapper.focus.subscribe((isFocused) => {
                                        if (!isFocused) {
                                            const fieldSettings = (<any>mirrorMapping.wrapper.fieldModel.settings);
                                            const sanitizeRegex = fieldSettings.sanitizeRegex;
                                            const sanitizeRegexReplaceCharacter = this.sanitizeService.getReplaceCharacter(fieldSettings);

                                            mirrorMapping.wrapper.writeValue(this.sanitizeService.sanitizeValue(strippedValue, sanitizeRegex, sanitizeRegexReplaceCharacter));
                                            mirrorMapping.lastValue = valueToWrite;
                                        }
                                    });
                                }

                                // add placeholder
                                mirrorMapping.wrapper.fieldModel.settings.placeholder = strippedValue;
                            }

                            return;
                        }
                    });
                }
            }
        } else {
            if (this.focusSubscription)
                this.focusSubscription.unsubscribe();
        }

        const mirrorMappingsCurrentField = this.mirrorMappings[key];
        if (mirrorMappingsCurrentField) {
            mirrorMappingsCurrentField.forEach(mirrorMapping => {
                if (mirrorMapping && mirrorMapping.shouldMirror) {
                    if (!mirrorMapping.wrapper)
                        mirrorMapping.wrapper = this.getWrapper(mirrorMapping.key, wrapperComponents);

                    if (!mirrorMapping.wrapper)
                        return;

                    // we mirror the value if we are creating a new item or
                    // the last sanitized value of the field we mirror from the is same as the current value of the field we mirror to
                    // TODO: sanitzation should be some sort of interface ?
                    const fieldSettings = (<any>mirrorMapping.wrapper.fieldModel.settings);
                    const sanitizeRegex = fieldSettings.sanitizeRegex;
                    const sanitizeRegexReplaceCharacter = this.sanitizeService.getReplaceCharacter(fieldSettings);

                    let mirroredValue = this.getMirroredValueProperty(value, fieldSettings.mirroredFieldProperty);
                    if (mirroredValue && mirrorMapping.prefix) {
                        mirroredValue = mirrorMapping.prefix + mirroredValue;
                    }

                    const isValueEmpty = (mirrorMapping.lastValue === null && (mirrorMapping.wrapper.getValue() === null || mirrorMapping.wrapper.getValue() === stringConstants.EMPTY_STRING));
                    const lastValueSanitized = this.sanitizeService.sanitizeValue(mirrorMapping.lastValue, sanitizeRegex, sanitizeRegexReplaceCharacter);
                    const currentValue = mirrorMapping.wrapper.getValue();

                    let isLastValueSameAsCurrent;
                    if (mirrorMapping.prefix) {
                        isLastValueSameAsCurrent = mirrorMapping.prefix + lastValueSanitized === currentValue;
                    } else {
                        isLastValueSameAsCurrent = lastValueSanitized === currentValue;
                    }

                    const isLastHTMLValueSameAsCurrent = this.sanitizeService.sanitizeValue(this.stripHtml(mirrorMapping.lastValue), sanitizeRegex, sanitizeRegexReplaceCharacter) === currentValue;
                    if (isValueEmpty || isLastValueSameAsCurrent || isLastHTMLValueSameAsCurrent) {
                        // If the mirroring is from HTMLField, then the html should be stripped
                        const keyWrapper = this.getWrapper(key, wrapperComponents);
                        const strippedValue = this.isHTMLField(keyWrapper.fieldModel) ? this.stripHtml(mirroredValue) : mirroredValue;

                        const valueToWrite = this.sanitizeService.sanitizeValue(strippedValue, sanitizeRegex, sanitizeRegexReplaceCharacter);
                        mirrorMapping.wrapper.writeValue(valueToWrite);
                        mirrorMapping.lastValue = this.getMirroredValueProperty(value, fieldSettings.mirroredFieldProperty);

                        const settings = mirrorMapping.wrapper.fieldModel.settings;
                        if (!copyMode && isValueEmpty && !settings.defaultValue) {
                            settings.defaultValue = valueToWrite;
                        }
                    } else
                        mirrorMapping.lastValue = undefined;
                }
            });
        }
    }

    determineShouldMirrorField(f: FieldModel, fields: FieldModel[]) {
        // check if the current field has to be mirrored from another field
        if (isMirrorFieldSettings(f.settings)) {
            const mirrorSettings = <any>f.settings as MirrorFieldSettings;
            if (mirrorSettings) {
                const mirrorFieldName = mirrorSettings.mirroredFieldName;
                // get the field that we mirror from
                const mirroredFieldObj = fields.find(x => x.key === mirrorFieldName);
                if (mirroredFieldObj) {
                    if (mirrorSettings.enableMirroring) {
                        // create a mapping with Key the field we mirror from and Value - an MirrorMapping object
                        if (!(this.mirrorMappings[mirrorFieldName] instanceof Array)) {
                            this.mirrorMappings[mirrorFieldName] = [];
                        }

                        const mirroredValue = this.getMirroredValueProperty(mirroredFieldObj.value, mirrorSettings.mirroredFieldProperty);
                        const sanitizeRegex = (<any>mirrorSettings).sanitizeRegex;
                        const sanitizeRegexReplaceCharacter = this.sanitizeService.getReplaceCharacter(mirrorSettings);
                        const mirroredValueSanitized = this.sanitizeService.sanitizeValue(mirroredValue, sanitizeRegex, sanitizeRegexReplaceCharacter);

                        this.mirrorMappings[mirrorFieldName].push({ key: f.key, lastValue: mirroredValueSanitized || null, shouldMirror: true, prefix: mirrorSettings.prefix });

                        // if we should mirror the field but its value is empty => set initial value as the field from which we should mirror
                        if (!f.value && mirroredValueSanitized) {
                            // If the mirroring is from HTMLField, then the html should be stripped
                            const strippedValue = this.isHTMLField(mirroredFieldObj) ? this.stripHtml(mirroredValueSanitized) : mirroredValueSanitized;
                            f.value = strippedValue;

                            // mark the field as dirty so that the value is send to the server even if field is not touched
                            f.settings.markAsDirty = true;
                            f.settings.emptyValues.push(strippedValue);
                            f.settings.defaultValue = strippedValue;
                        }
                    }
                }
            }
        }
    }

    isFieldAvailableForMirroring(dataItem: DataItem, field: FieldModel): boolean {
        // item is creating - should mirror
        // when create hierarchical content ParentId might be already set (Create child...) and data is not null
        if (!dataItem.data || !dataItem.key)
            return true;

        if (field.settings && field.settings.readOnlyMode) {
            return false;
        }

        let hasEverBeenPublishedOrSaved = true;
        if (dataItem.metadata.hasLifecycle) {
            // if item has never been published - should mirror
            const hasProperty = dataItem.data.hasOwnProperty(Properties.FIRST_PUBLISHED);
            if (!hasProperty)
                return true;

            hasEverBeenPublishedOrSaved = dataItem.data[Properties.FIRST_PUBLISHED] !== null;
        } else if (dataItem.metadata.isTranslatable) {
            //check if item has been saved for current culture if not we should mirror
            const hasProperty = dataItem.data.hasOwnProperty(Properties.AvailableLanguages);
            if (hasProperty && dataItem.culture) {
                hasEverBeenPublishedOrSaved = dataItem.data[Properties.AvailableLanguages].indexOf(dataItem.culture) >= 0;
            }
        }

        // item has been published - should not mirror UrlName and Name (developer name), but mirror other fields
        if (hasEverBeenPublishedOrSaved && (field.key === Properties.URL_NAME || field.key === Properties.NAME)) {
            return false;
        }

        return true;
    }

    updateMirroring(f: FieldModel, enableMirroring: boolean) {
        if (isMirrorFieldSettings(f.settings)) {
            const mirrorSettings = <any>f.settings as MirrorFieldSettings;
            if (mirrorSettings.enableMirroring !== enableMirroring) {
                mirrorSettings.enableMirroring = enableMirroring;
                const mappingsMirroredField = this.mirrorMappings[mirrorSettings.mirroredFieldName];
                if (mappingsMirroredField) {
                    const mapping = mappingsMirroredField.find(x => x.key === f.key);
                    if (mapping) {
                        mapping.shouldMirror = mirrorSettings.enableMirroring;
                    }
                }
            }
        }
    }

    resetMirroring() {
        this.mirrorMappings = {};
    }

    private getMirroredValueProperty(initialValue: any, mirroredFieldProperty: string) {
        if (initialValue instanceof Array) { //if value is array mirror only first item, or part of it.
            initialValue = initialValue[0];
        }
        if (mirroredFieldProperty && initialValue) { //get the property to mirror.
            mirroredFieldProperty.split(".").forEach(x => initialValue = initialValue ? initialValue[x] : initialValue);
        }

        return initialValue;
    }

    private getWrapper(key: string, wrapperComponents: FieldWrapper[]): FieldWrapper {
        for (const wrapper of wrapperComponents) {
            if (wrapper.fieldModel.key === key) {
                return wrapper;
            }
        }
    }

    private isHTMLField(fieldModel: FieldModel): boolean {
        if (fieldModel.selector === FieldTypes.html) {
            return true;
        }

        return false;
    }

    private stripHtml(value: string): string {
        const container = document.implementation.createHTMLDocument("New").body;
        container.innerHTML = value;
        return container.innerText;
    }
}

interface MirrorMapping {
    // the field wrapper of the field we mirror to
    wrapper?: FieldWrapper;
    shouldMirror?: boolean;
    // the last value of the field we mirror from
    lastValue: any;
    // the key of the field we mirror to
    key: string;
    prefix?: string;
}
