import { Component, Input, ViewEncapsulation, OnInit, QueryList, ViewChildren } from "@angular/core";
import { ChoiceSettings } from "../../../../../fields/choice/choice.settings";
import { FormRuleOperatorCRUD, FormRule, FormRuleCondition, FormRuleAction, FormDefinition, FormField } from "../forms.constants";
import { stringConstants } from "../../../common-constants";
import { FormFieldTypesParserService } from "../services/form-field-types-parser.service";
import { CanCloseModal, ClosingContext } from "../../shared/services/modal-window.service";
import { ActionCreateCompositeComponent } from "./action-create-composite.component";
import { ScrollService } from "../../../services/scroll.service";

@Component({
    selector: "sf-form-rule-create",
    templateUrl: "./form-rule-create.component.html",
    encapsulation: ViewEncapsulation.None
})
export class FormRuleCreateComponent implements OnInit, CanCloseModal {
    @Input() title: string;
    @Input() formDefinition: FormDefinition;
    @Input() formRule: FormRule;

    public operatorDropdownSettings: ChoiceSettings;

    @ViewChildren(ActionCreateCompositeComponent) private actionComponents: QueryList<ActionCreateCompositeComponent>;

    constructor(private typeParserService: FormFieldTypesParserService, public scrollService: ScrollService) {
    }

    ngOnInit() {
        if (!this.formRule) {
            this.formRule = {
                Operator: FormRuleOperatorCRUD.Any,
                Conditions: [
                    this.generateCondition()
                ],
                Actions: [
                    this.generateAction()
                ]
            };
        }

        this.operatorDropdownSettings = new ChoiceSettings("operatorDropdown", false);
        this.operatorDropdownSettings.choices = this.generateChoices();
        if (this.formRule) {
            this.operatorDropdownSettings.defaultValue = this.formRule.Operator;
        }
    }

    canCloseCallback(context: ClosingContext): boolean {
        let isValid = true;
        if (context.data && context.data.data) {
            this.actionComponents.forEach(x => {
                isValid = x.isValid() && isValid;
            });
        }

        return isValid;
    }

    public addCondition() {
        this.formRule.Conditions.push(this.generateCondition());
    }

    public deleteCondition(value) {
        const index = this.formRule.Conditions.indexOf(value);
        this.formRule.Conditions.splice(index, 1);
    }

    public addAction() {
        this.formRule.Actions.push(this.generateAction());
    }

    public deleteAction(value) {
        const index = this.formRule.Actions.indexOf(value);
        this.formRule.Actions.splice(index, 1);
    }

    public formOperatorChanged(value) {
        this.formRule.Operator = value;
    }

    private generateCondition(): FormRuleCondition {
        const defaultCondition: FormRuleCondition = {
            Id: stringConstants.EMPTY_STRING,
            Operator: stringConstants.EMPTY_STRING,
            Value: stringConstants.EMPTY_STRING
        };

        const conditionFields = this.typeParserService.getConditionFields(this.formDefinition);
        const selectedConditonField = conditionFields[0];

        if (selectedConditonField) {
            defaultCondition.Id = selectedConditonField.Id;

            const selectedOperator = selectedConditonField.Operators[0];
            if (selectedOperator) {
                defaultCondition.Operator = selectedOperator.Key;
            }

            defaultCondition.Value = this.getDefaultFieldValue(selectedConditonField);
        }

        return defaultCondition;
    }

    private generateAction(): FormRuleAction {
        const defaultAction: FormRuleAction = {
            Action: stringConstants.EMPTY_STRING,
            Target: stringConstants.EMPTY_STRING
        };

        if (this.formDefinition.AvailableActions[0]) {
            defaultAction.Action = this.formDefinition.AvailableActions[0].Key;
        }

        const actionFields = this.typeParserService.getActionFields(this.formDefinition);
        const selectedActionField = actionFields[0];

        if (selectedActionField) {
            defaultAction.Target = selectedActionField.Id;
        }

        return defaultAction;
    }

    private generateChoices() {
        const choices: any[] = [];

        Object.keys(FormRuleOperatorCRUD).forEach(choiceKey => {
            choices.push({
                Value: FormRuleOperatorCRUD[choiceKey],
                Name: choiceKey
            });
        });

        return choices;
    }

    private getDefaultFieldValue(formField: FormField): string {
        let value: string = stringConstants.EMPTY_STRING;

        if (formField.Values.length > 0) {
            value = formField.Values[0].Value;
        }

        return value;
    }
}
