import { Observable } from "rxjs";
import { first } from "rxjs/operators";

export abstract class CacheStore<TKey, TItem> {
    private cache: { [key: string]: Observable<TItem> } = { };

    /**
    * Converts input key to cache key
    */
    protected abstract getCacheKey(key: TKey): string;

    /**
    * Requests new item from the server.
    */
    protected abstract requestItem(key: TKey): Observable<TItem>;

    /**
    * Reads item from local cache. If there is no such item in the cache a new item is requested and cached.
    */
    protected getItemInternal(key: TKey): Observable<TItem> {
        const cacheKey = this.getCacheKey(key);
        let item = this.cache[cacheKey];

        if (!item) {
            item = this.requestItem(key);
            this.cache[cacheKey] = item;
        }

        return item.pipe(first());
    }

    invalidateCache(key: TKey) {
        const cacheKey = this.getCacheKey(key);
        delete this.cache[cacheKey];
    }
}
