import { Component, OnInit, Inject } from "@angular/core";
import { DOCUMENT } from "@angular/common";
import { Router } from "@angular/router";
import { FormsConstants } from "./forms.constants";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";

@Component({
    selector: "sf-forms-edit-integrated",
    template: ""
})
export class FormsEditIntegratedComponent implements OnInit {
    redirectUrl: string;
    formId: string;
    formName: string;
    culture: string;

    constructor(@Inject(DOCUMENT) private document: any, private router: Router) {
    }

    ngOnInit() {
        this.document.addEventListener(FormsConstants.ROUTES.SITEFINITY_OLD_BACKEND_EDIT_FORM_RULE_EVENT_NAME, e => {
            this.formId = e.detail.controlId;
            this.culture = e.detail.culture;
            this.router.navigate([ROUTE_PATHS.CONTENT, ROUTE_PATHS_NO_PREFIX.FORMS, FormsConstants.ROUTES.RULES], {
                queryParams: {
                    id: this.formId,
                    culture: this.culture,
                    path: FormsConstants.ROUTES.INTEGRATED
                }
            });
        });
    }
}
