import { Injectable, ClassProvider } from "@angular/core";
import { EditExtender, EDIT_EXTENDER_TOKEN, SidebarButtonComponentData, BROWSE_BUTTON_NAME } from "../../shared/services/edit/edit-extender";
import { ModifyFieldsArgs, EditActionContext, ActionResult } from "../../shared/services/edit/composite-edit-extender";
import { Observable, of } from "rxjs";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { Properties } from "../../shared/fields.constants";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { stringConstants } from "../../../common-constants";
import { FIELD_SECTION_NAMES, FieldSectionModel } from "../../../services/fieldSection.model";
import { UrlNameSettings } from "../../urlName/urlName-settings";
import { SanitizeService } from "../../../services/sanitize.service";
import { NotificationService } from "../../shared/services/notification/notification.service";
import { NavbarConfiguration } from "../../shared/components/navigation/navigation-menu/navigation-menu.component";
import { MediaHelpers, MEDIA_FORM_CLASS, CreateLibraryFromFileUploadClickEvent } from "./media.helpers";
import { VIEW_NAME } from "../../content/constants";
import { ParentSelectorSettings } from "../../parent-selector/parent-selector-settings";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { ViewAllImageSizesCommand } from "../../content/dynamic-modules/services/operations/commands/view-all-image-sizes-command";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { EmbedMediaCommand } from "../commands/embed-media.command";
import { Command } from "../../shared/commands/command";
import { ComponentCommunicationService } from "../../shared/services/component-communication.service";
import { FieldTypes } from "../../shared/fields-builder/services/fields-registry";
import { Router } from "@angular/router";
import { PlayVideoCommand } from "../commands/play-video.command";

@Injectable()
export class MediaEditExtender extends EditExtender {
    private hideStorageProvider: boolean;

    constructor(private service: DynamicItemService,
                private store: MetadataStore,
                private sanitizeService: SanitizeService,
                private modalWindowService: ModalWindowService,
                private communicationService: ComponentCommunicationService,
                private router: Router
            ) {
        super();
        this.communicationService.subscribe(CreateLibraryFromFileUploadClickEvent, ev => {
            this.hideStorageProvider = ev.data.hideStorageProvider;
        });
    }

    overrideNavigationMenuOptions(dataItem: DataItem, options: NavbarConfiguration): void {
        options.hideAdditionalActionsMenu = true;
        options.title = of(`${dataItem.metadata.singularName} properties`);
    }

    getFormClasses(): string {
        return MEDIA_FORM_CLASS;
    }

    handleAction(context: EditActionContext, notificationService: NotificationService): ActionResult {
        const operationCommand: Command = this.getOperationCommand(context);
        if (operationCommand) {
            return {
                handled: operationCommand.execute({
                    currentRoute: context.route,
                    model: null,
                    data: {
                        dataItem: context.item
                    }
                })
            };
        }

        if (MediaHelpers.isMediaEntity(context.item)) {
            return {
                handled: of(false)
            };
        }

        this.handleSizesFieldsValues(context);

        let parentId = null;
        if (context.changedFields && context.changedFields[Properties.PARENT_ID] && context.changedFields[Properties.PARENT_ID] !== stringConstants.DEFAULT_GUID) {
            parentId = context.changedFields[Properties.PARENT_ID];
        }

        // we change the entity from albums to folders in case ParentId is set and the operation is Create
        let dataItem = context.item;
        if (parentId != null && context.actionName === OPERATION_NAMES.create) {
            const entity = this.store.getEntity(ENTITY_SET.FOLDERS);
            dataItem = DataItem.from(dataItem.data, entity, dataItem.provider, dataItem.culture);
        }

        // sanitize url name
        if (context.actionName === OPERATION_NAMES.create) {
            const urlNameSettings = new UrlNameSettings(dataItem.key, false);
            urlNameSettings.init(context.item.metadata.properties[Properties.URL_NAME]);

            const sanitizeRegex = urlNameSettings.sanitizeRegex;
            const sanitizeRegexReplaceCharacter = this.sanitizeService.getReplaceCharacter(urlNameSettings);
            const urlNameFieldValue = context.changedFields[Properties.URL_NAME] || context.changedFields[dataItem.metadata.defaultFieldName];
            context.changedFields[Properties.URL_NAME] = this.sanitizeService.sanitizeValue(urlNameFieldValue, sanitizeRegex, sanitizeRegexReplaceCharacter);
        }

        let result = null;
        let handled = false;
        if (context.changedFields && dataItem) {
            result = this.service.upsert({
                data: context.changedFields,
                dataItem
            });

            handled = true;
        }

        return {
            handled: of(handled),
            result
        };
    }

    modify(args: ModifyFieldsArgs): Observable<void> {
        const dataItem = args.dataItem;
        const sections = args.sections;
        this.handleFewerFields(args);

        if (MediaHelpers.isLibrary(dataItem.metadata.setName)) {
            const dataItemHasParentId = dataItem.data && dataItem.data[Properties.PARENT_ID] !== undefined && dataItem.data[Properties.PARENT_ID] !== stringConstants.DEFAULT_GUID;
            if (args.viewName === VIEW_NAME.INSERT) {
                const hasParentIdPreset = args.isInit && args.parentId ? true : false;
                const hasParent = dataItemHasParentId || hasParentIdPreset;
                const hasParentOrIsCreateFromUpload = hasParent || this.hideStorageProvider;

                this.modifySectionVisibility(sections, FIELD_SECTION_NAMES.advancedOptions, hasParent);
                this.modifyFieldVisibilityInSection(sections, FIELD_SECTION_NAMES.mainSection, Properties.BLOB_STORAGE_PROVIDER, !hasParentOrIsCreateFromUpload);
                this.modifyFieldVisibilityInSection(sections, FIELD_SECTION_NAMES.mainSection, Properties.DESCRIPTION, !hasParent);
                this.modifyFieldVisibilityInSection(sections, FIELD_SECTION_NAMES.mainSection, Properties.URL_NAME, !hasParent);
            } else {
                this.modifySectionVisibility(sections, FIELD_SECTION_NAMES.advancedOptions, dataItemHasParentId && !args.isInit);
            }
        }

        this.modifyParentSelectorSettings(dataItem, sections, args.setName);
        return of(undefined);
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData && MediaHelpers.isLibraryOrMedia(entityData.metadata.setName);
    }

    showHeader(entityData: EntityData): boolean {
        return MediaHelpers.isMediaEntity(entityData);
    }

    getHeader(dataItem: DataItem): string {
        return `${dataItem.metadata.singularName} properties`;
    }

    getSidebarButtons(entityData: EntityData, compDatas: SidebarButtonComponentData) {
        return super.getSidebarButtons(entityData, compDatas).filter(b => b.name !== BROWSE_BUTTON_NAME);
    }

    hasCreateActionFromEdit(): boolean {
        return false;
    }

    forceUpdateFieldModel(selector: string, updatedDataItem: DataItem, dataItem: DataItem): boolean {
        const isVideoThumbnailField = selector === FieldTypes.videoThumbnail && updatedDataItem.data.Url !== dataItem.data.Url;
        const shouldUpdateUrlField = selector === FieldTypes.urlName &&
        updatedDataItem &&
        updatedDataItem.data.Extension &&
        updatedDataItem.data.Extension !== dataItem.data.Extension;

        return shouldUpdateUrlField || isVideoThumbnailField;
    }

    // When no value in one of these fields we have to send 0 to the server because
    // they are persisted as not nullable integer.
    // They should not be visualized as 0 per UX.
    private handleSizesFieldsValues(context: EditActionContext) {
        if (context.changedFields && context.changedFields[Properties.MAX_SIZE] === null) {
            context.changedFields[Properties.MAX_SIZE] = 0;
        }

        if (context.changedFields && context.changedFields[Properties.MAX_ITEM_SIZE] === null) {
            context.changedFields[Properties.MAX_ITEM_SIZE] = 0;
        }
    }

    private modifyParentSelectorSettings(dataItem: DataItem, sections: FieldSectionModel[], setName: string) {
        const parentIdField = sections.find(x => x.settings.name === FIELD_SECTION_NAMES.mainSection).fields.find(x => x.key === Properties.PARENT_ID);
        if (parentIdField) {
            if (MediaHelpers.isFolderEntity(dataItem)) {
                // set the type in order for the hierarchical media service to make the correct calls to media entity and not to folders entity
                (parentIdField.settings as ParentSelectorSettings).hierarchicalTaxaSettings.type = MediaHelpers.resolveLibrarySetName(setName);
                if (!parentIdField.value) {
                    // use rootId value if there is no ParentId
                    parentIdField.value = dataItem.data[Properties.ROOT_ID];
                }
            } else if (MediaHelpers.isMediaEntity(dataItem)) {
                if (dataItem.data[Properties.FOLDER_ID]) {
                    (parentIdField.settings as ParentSelectorSettings).hierarchicalTaxaSettings.type = MediaHelpers.getParentSetName(dataItem);
                    parentIdField.value = dataItem.data[Properties.FOLDER_ID];
                }
            }

            if (MediaHelpers.isLibrary(dataItem.metadata.setName)) {
                (parentIdField.settings as ParentSelectorSettings).hierarchicalTaxaSettings.id = dataItem.key;
            }
        }
    }

    private getOperationCommand(context: EditActionContext): Command {
        if (context.actionName === OPERATION_NAMES.viewAllSizes) {
            return new ViewAllImageSizesCommand(this.modalWindowService, this.service, this.router);
        } else if (context.actionName === OPERATION_NAMES.embed) {
            return new EmbedMediaCommand(this.modalWindowService);
        } else if (context.actionName === OPERATION_NAMES.play) {
            return new PlayVideoCommand(this.modalWindowService);
        }

        return null;
    }

    private modifySectionVisibility(sections: FieldSectionModel[], sectionName: string, isHidden: boolean): void {
        const advancedOptionsSection = sections.find(x => x.settings.name === sectionName);

        if (advancedOptionsSection) {
            advancedOptionsSection.settings.isHidden = isHidden;
            advancedOptionsSection.fields.forEach(f => {
                f.settings.isVisible = !isHidden;
            });
        }
    }

    private modifyFieldVisibilityInSection(sections: FieldSectionModel[], sectionName: string, fieldName: string, isVisible: boolean) {
        const field = sections
            .find(x => x.settings.name === sectionName).fields
            .find(x => x.key === fieldName);

        if (field) {
            field.settings.isVisible = isVisible;
        }
    }
}

export const MEDIA_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: MediaEditExtender
};
