import { Component } from "@angular/core";
import { trigger, transition } from "@angular/animations";
import { isAnimationTypeToTop, isAnimationTypeFromTop, isAnimationTypeRightToLeft, isAnimationTypeLeftToRight, ANIMATION_RIGHT_TO_LEFT, ANIMATION_FROM_TOP, ANIMATION_LEFT_TO_RIGHT, ANIMATION_TO_TOP
} from "../../../../../animations/animation-utilities";

@Component({
    templateUrl: "./dynamic-item-router.component.html",
    animations: [
        trigger("routerAnimations", [
            // right to left
            transition(isAnimationTypeRightToLeft, ANIMATION_RIGHT_TO_LEFT),
            // left to right
            transition(isAnimationTypeLeftToRight, ANIMATION_LEFT_TO_RIGHT),
            // from top
            transition(isAnimationTypeFromTop, ANIMATION_FROM_TOP),
            // to top
            transition(isAnimationTypeToTop, ANIMATION_TO_TOP)
        ])
    ]
})
export class DynamicItemRouterComponent {

    routeActive: boolean;
    isAnimating: boolean;

    onActivate(event: any) {
        this.routeActive = true;
    }

    onDeactivate(event: any) {
        this.routeActive = false;
    }
    animationStarted(event) {
        this.isAnimating = true;
    }

    animationDone(event) {
        this.isAnimating = false;
    }
}
