import { Inject, Injectable } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { EntityData, NotificationService, NOTIFICATION_SERVICE } from "../../../../api";
import { ROUTE_PARAMS } from "../../../content/constants";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { SearchIndexesContract } from "../../../integrations/search-indexes/search-indexes.contract";
import { ServiceHookHistoryContract } from "../../../integrations/servicehooks/service-hook-history.contract";
import { ServiceHooksContract } from "../../../integrations/servicehooks/service-hooks.contract";
import { OPERATION_NAMES } from "../../components/action-menu/operation.model";
import { ENTITY_SET } from "../metadata/meta-data-constants";
import { ModalWindowService } from "../modal-window.service";
import { ListIndexContract } from "./list-index.contract";

@Injectable()
export class ListIndexContractProvider {
    constructor(
        private dynamicItemService: DynamicItemService,
        private router: Router,
        private modalWindowService: ModalWindowService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService) { }

    getContract(listIndexContractArgs: ListIndexContractProviderArgs): ListIndexContract {
        // TODO: remove hardcoded checks
        const operationName = listIndexContractArgs.route.snapshot.params[ROUTE_PARAMS.OPERATION_NAME_SEGMENT];

        if (listIndexContractArgs.entityData.metadata.setName === ENTITY_SET.SERVICEHOOKS) {
            if (operationName === OPERATION_NAMES.history) {
                return new ServiceHookHistoryContract(listIndexContractArgs.entityData, this.dynamicItemService, this.router, this.modalWindowService, this.notificationService);
            } else {
                return new ServiceHooksContract(listIndexContractArgs.entityData, this.dynamicItemService, this.router);
            }
        }

        if (listIndexContractArgs.entityData.metadata.setName === ENTITY_SET.SEARCH_INDEXES) {
            return new SearchIndexesContract(listIndexContractArgs.entityData, this.dynamicItemService, this.router);
        }

        throw new Error("Not supported entity");
    }
}

export interface ListIndexContractProviderArgs {
    entityData: EntityData;
    route: ActivatedRoute;
}
