import { ClassProvider, Injectable } from "@angular/core";
import { QueryParamsExtender, QUERY_PARAMS_EXTENDER_TOKEN } from "../../shared/services/query-params-extender";
import { QUERY_PARAMS } from "../../content/constants";
import { Entity } from "../../shared/services/metadata/meta-data.store";
import { MediaHelpers } from "./media.helpers";

@Injectable()
export class MediaQueryParamsExtender implements QueryParamsExtender {
    getAdditionalQueryParams(entity: Entity = null, data: any = null): { [key: string]: string; } {
        let additionalQueryParams: any = {};

        if (data && data.SfMediaData) {
            if (!data.SfMediaData.preserveFileName) {
                additionalQueryParams = { ["uploadAndReplace"]: true };
            }
        }

        // Skip DAM images/libraries in all cases except:
        // - when "data" is set - it means it is an "Update & Refresh" operation
        // - when "skipDam" query parameter is already set to false. Handled in base logic.
        if (!data && entity && MediaHelpers.isLibraryOrMedia(entity.setName)) {
            additionalQueryParams[QUERY_PARAMS.SKIP_DAM] = "true";
        }

        return additionalQueryParams;
    }
}

export const MEDIA_QUERY_PARAMS_EXTENDER: ClassProvider = {
    multi: true,
    provide: QUERY_PARAMS_EXTENDER_TOKEN,
    useClass: MediaQueryParamsExtender
};
