import { enableProdMode, Type } from "@angular/core";
import { platformBrowserDynamic } from "@angular/platform-browser-dynamic";
import { Observable, ReplaySubject } from "rxjs";
import * as rxjs from "rxjs";
import * as rxjsOperators from "rxjs/operators";

import { KEYS } from "./modules/shared/services/settings-keys";
import { environmentTypes } from "./environment";
import { environment } from "../environments/environment";
import { SitefinityExtensionStore } from "./extensibility/manifest";
import { Settings } from "./modules/shared/services/settings.service";

export const EXTENSIONS_ENDPOINT = "admin-bridge/extensions";
export const EXTENSIONS_COMPATIBLE_MESSAGE = "Extensions were loaded, but were not compatible.";
export const EXTENISONS_FAILED_TO_LOAD_MESSAGE = "Failed to load script for extensions from server";
export const DEV_EXTENSIONS_URL = "/sample.extensions.bundle.js";
export let EXTENSIONS_COMPATIBLE_SF_VERSIONS: { [Key: string]: string[]; };

import '@angular/compiler'

const IVY_NG_MODULE_DECORATOR_METADATA_PROPERTY_NAME = "ɵinj";
const IVY_NG_MODULE_MARK_PROPERTY_NAME = "ɵmod";

declare const sitefinityExtensionsStore: SitefinityExtensionStore;

export class Bootstrapper {
    private static modules: Array<any> = [];

    constructor(
        private storage: Storage,
        private windowInstance: Window,
        private environment: string) {
    }

    public boot(rootModule: Type<any>): void {
        const extUrl: string = this.getExtensionsUrl(environment.env);
        if (!extUrl) {
            this.bootApp(rootModule);
        } else {
            this.loadExtensions(extUrl, rootModule);
        }
    }

    private getExtensionsUrl(irisEnvironment: string): string {
        if (irisEnvironment === environmentTypes.dev_extensions) {
            return DEV_EXTENSIONS_URL;
        }

        const siteUrl = this.storage.getItem(KEYS.SERVICE_URL);

        if (!siteUrl) {
            return null;
        }

        const backendExtensionsUrl = `${Settings.formatUrl(siteUrl)}${EXTENSIONS_ENDPOINT}`;
        return backendExtensionsUrl;
    }

    private loadExtensions(siteUrl: string, rootModule: Type<any>): void {
        const errorHandler = (err: Error) => {
            const message = `Extensions failed to load: ${err.message}`;

            // eslint-disable-next-line no-console
            console.warn(message);
            this.bootApp(rootModule);
        };

        const extensions$ = this.getExtensions(siteUrl);
        extensions$.subscribe(() => {
            try {
                const extensionModules = sitefinityExtensionsStore.getExtensionModules();
                Bootstrapper.modules = extensionModules;
                this.bootApp(rootModule);
            } catch (err) {
                errorHandler(err);
            }
        }, errorHandler);
    }

    private bootApp(rootModule: Type<any>): void {
        if (this.environment !== environmentTypes.development && this.environment !== environmentTypes.dev_extensions) {
            try {
                enableProdMode();
            } catch (error) {
                // enabledProdMode fails if the application is attempted to be loaded with broken extensions
                // the problem is that bootstapModule calls isDevMode() which sets a flag. when this flag is set the
                // enableProdMode call fails indicating that tha platform is already setup.
            }
        }

        if (rootModule[IVY_NG_MODULE_DECORATOR_METADATA_PROPERTY_NAME]) {
            const ivyCompatibleModules = Bootstrapper.modules.filter(x => IVY_NG_MODULE_MARK_PROPERTY_NAME in x);
            rootModule[IVY_NG_MODULE_DECORATOR_METADATA_PROPERTY_NAME].imports[0].push(...ivyCompatibleModules);
        }

        platformBrowserDynamic().bootstrapModule(rootModule);
    }

    private getExtensions(url: string): Observable<void> {
        this.includeRXJSindexesInBundle();
        const extensions$ = new ReplaySubject<void>(1);

        // setTimeout is needed for local extensions development.
        // The extensions script should be executed after the app is loaded
        setTimeout(() => {
            const xmlHttp = new XMLHttpRequest();

            // eslint-disable-next-line @typescript-eslint/no-this-alias
            const that = this;
            xmlHttp.onreadystatechange = function() {
                if (xmlHttp.readyState == 4 && xmlHttp.status == 200) {
                    const script = that.windowInstance.document.createElement("script");
                    script.onerror = () => extensions$.error(new Error(EXTENISONS_FAILED_TO_LOAD_MESSAGE));

                    script.innerHTML = that.modifyExtensionsBundleForBackwardCompatability(xmlHttp.response);
                    that.windowInstance.document.body.appendChild(script);
                    extensions$.next();
                }
            }
            xmlHttp.open("GET", url, true);
            xmlHttp.send(null);
        }, 0);

        return extensions$.asObservable();
    }

    private modifyExtensionsBundleForBackwardCompatability(bundle): string {
        // load extension as chunk
        let result = bundle.replaceAll(`window["webpackJsonp"]`, `self["webpackChunkiris"]`);

        // replace webpack bootstrap function
        let matches = result.matchAll(/\[\["(.*)","runtime"\]\]/g);
        for (const match of matches) {
            const firstModuleId = match[1];
            const moduleIdBase = firstModuleId.substr(0, firstModuleId.lastIndexOf('_'));
            result = result.replace(match[0], `__webpack_require__ => {
                var __webpack_exec__ = (moduleId) => (__webpack_require__(__webpack_require__.s = moduleId))
                var __webpack_exports__ = (__webpack_exec__("${moduleIdBase}"));}`);
        }

        // replace __webpack_require__.d
        // from: __webpack_require__.d(__webpack_exports__, "COLUMNS_PROVIDER", function() { return COLUMNS_PROVIDER; });
        // to: __webpack_require__.d(__webpack_exports__, { "COLUMNS_PROVIDER": () => (COLUMNS_PROVIDER) });
        matches = result.matchAll(/__webpack_require__\.d\(__webpack_exports__,\s?"(.*)",\s?function\(\)\s?{\s?return\s?(.*);\s?}\);/g);
        for (const match of matches) {
            const itemId = match[1];
            const itemName = match[2];
            result = result.replace(match[0], `__webpack_require__.d(__webpack_exports__,{"${itemId}":()=>(${itemName})})`);
        }

        // remove __webpack_require__.t as they are not used
        // ex: var _symbol_list_symbol_list_json__WEBPACK_IMPORTED_MODULE_5___namespace = /*#__PURE__*/__webpack_require__.t(/*! ./symbol-list/symbol-list.json */ "ext_mod_id_1651654581986_56", 1);
        matches = result.matchAll(/var (.*)\s?=\s?(\/\*#__PURE__\*\/)?__webpack_require__\.t\(.*\);/g);
        for (const match of matches) {
            result = result.replace(match[0], "");
        }

        return result;
    }

    // This is used for legacy extensions backwards compatibility
    private includeRXJSindexesInBundle() {
        rxjs;
        rxjsOperators;
    }
}
