import { ClassProvider, Inject, Injectable, InjectionToken } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { BehaviorSubject } from "rxjs";
import { NOTIFICATIONS_SITE_SYNC_EVENT } from "../../../../../constants/integrated-mode-constants";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { NotificationsResolverBase } from "../../../notifications/resolvers/notifications-base-resolver";
import { ModalWindowService, DialogData } from "../../../services/modal-window.service";
import { SiteSyncResultMapper } from "../mappers/site-sync-result-mapper";
import { SiteSyncNotificationComponent } from "../site-sync.notification.component";

const SITE_SYNC_COMLETED = "site-sync-completed";

@Injectable()
export class SiteSyncNotificationReslover implements NotificationsResolverBase {

    constructor(@Inject(WINDOW_TOKEN) private window: Window, private modalService: ModalWindowService) {
    }

    execute(additionalMessageData: string, route: ActivatedRoute) {
        const result = JSON.parse(additionalMessageData);
        const arrayData = Object.keys(result).map(function (k) {
            return result[k];
        });

        const syncSummaryId = arrayData[0].SyncSummaryId;
        const totalItems = arrayData[0].TotalItems;

        if (!syncSummaryId || totalItems <= 0) {
            // The sync failed with general errors and there are no info for the items
            return;
        }

        if (Object.keys(route.parent.snapshot.data).length === 0) {
            const event = new CustomEvent(NOTIFICATIONS_SITE_SYNC_EVENT, { detail: { syncSummaryId: syncSummaryId, count: totalItems } });
            this.window.dispatchEvent(event);
        } else {
            const dialogData = this.getDialogData(syncSummaryId, totalItems, "site-sync-notification");

            this.modalService.setMapping(dialogData, "itemsSendForSync");
            this.modalService.open(route, "itemsSendForSync");
        }
    }

    canProcess(notificationKey: string): boolean {
        return notificationKey === SITE_SYNC_COMLETED;
    }

    getDialogData(syncSummaryId: string, count: number, key: string): DialogData {
        const count$ = new BehaviorSubject<number>(count);
        const componentData: ComponentData = this.getDialogComponentData(syncSummaryId, count$);
        const dialogData = new DialogData(componentData, (context: ClosingContext) => { }, [], null, "-bottom");
        dialogData.key = key;

        return dialogData;
    }
    private getDialogComponentData(syncSummaryId: any, count: BehaviorSubject<number>): ComponentData {
        return {
            type: SiteSyncNotificationComponent,
            properties: {
                contentLook: "medium",
                actionTitle: "Synced items",
                action: `GetItemsSendForSync(summaryId=${syncSummaryId})`,
                count,
                treeConfig: {
                    description: true,
                    noSelection: true
                },
                openItemEdit: false,
                modalListMapper: new SiteSyncResultMapper()
            }
        };
    }
}

export const SITE_SYNC_TOKEN = new InjectionToken("SiteSyncResolverToken");
export const SITE_SYNC_NOTIFICATION_PROVIDER: ClassProvider = {
    multi: true,
    provide: SITE_SYNC_TOKEN,
    useClass: SiteSyncNotificationReslover
};
