import { Inject, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { map } from "rxjs/operators";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { DamProviderBase, DamProviderSettings, DAM_PROVIDER_TOKEN } from "./dam-provider-base";

@Injectable()
export class DamProviderService {
    constructor(
        @Inject(DAM_PROVIDER_TOKEN) private damProviders: DamProviderBase[],
        private dynamicItemService: DynamicItemService) {
    }

    getDamProvider(): Observable<DamProviderBase> {
        if (this.damProviders.length) {
            return this.dynamicItemService.executeUnboundFunction<DamProviderSettings>("Default.GetDamProviderSettings()").pipe(map(damProviderSettings => {
                if (damProviderSettings && damProviderSettings.ProviderTypeName) {
                    const provider = this.getProvider(damProviderSettings.ProviderTypeName);
                    if (provider) {
                        provider.settings = damProviderSettings;
                    }

                    return provider;
                }
            }));
        }

        return of(null);
    }

    private getProvider(providerTypeName: string): DamProviderBase {
        const providers = this.damProviders.filter(p => p.isSupported(providerTypeName)).sort((a, b) => b.priority - a.priority);
        if (providers && providers.length) {
            return providers[0];
        }

        return null;
    }
}
