import { Injectable } from "@angular/core";
import { Command } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable } from "rxjs";
import { DynamicItemStore } from "../../dynamic-item.store";
import { OperationResult, DataItem } from "../../../interfaces";

@Injectable()
export class RestoreCommand implements Command {
    constructor(private store: DynamicItemStore) {
    }

    execute(context: ExecutionContext): Observable<OperationResult> {
        const dataItem: DataItem = context.data.dataItem;
        return this.store.restoreItem(dataItem);
    }
}
