import { Observable, ReplaySubject } from "rxjs";
import { Injectable } from "@angular/core";
import { EntityData } from "../../../interfaces";
import { DynamicItemService } from "../../../services/dynamic-item.service";

@Injectable()
export class SortersStore {
    private cache = new Map<string, Observable<SortersResult>>();

    constructor(private sitefinitySdk: DynamicItemService) { }

    getSorters(entityData: EntityData): Observable<SortersResult> {
        const key = entityData.metadata.setName;

        if (!this.cache.has(key)) {
            const result = new ReplaySubject<SortersResult>(1);
            this.cache.set(key, result.asObservable());

            this.sitefinitySdk.executeUnboundFunction(`${entityData.metadata.setName}/Default.Sorters()`).subscribe(data => {
                const sortersResult: SortersResult = {
                    isLoading: false,
                    sorters: data["value"]
                };

                result.next(sortersResult);
            });

            return result;
        }

        return this.cache.get(key);
    }
}

export interface SortersResult {
    isLoading: boolean;
    sorters: Sorter[];
}

export interface Sorter {
    Name: string;
    Value: string;
}
