import { EventEmitter, Component, Input, Output, OnInit } from "@angular/core";
import { EntityData, DataItem, FailedMediaValidation } from "../content/dynamic-modules/interfaces";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";

const LIBRARY_ICON_COUNT = 4;

@Component({
    selector: "sf-library-preview",
    templateUrl: "./library-preview.component.html"
})
export class LibraryPreviewComponent implements OnInit {
    @Input() title: string;
    @Input() files = [];
    @Input() folders: DataItem[] = [];
    @Input() totalFolders: number = 0;
    @Input() totalFiles: number;
    @Input() mediaEntityData: EntityData;
    @Input() selectable: boolean = true;
    @Input() selected: boolean = false;
    @Input() failedValidation: FailedMediaValidation = null;

    @Output() clickLibrary = new EventEmitter();
    @Output() selectLibrary = new EventEmitter();
    public children;

    mediaEntity: MediaEntity;

    ngOnInit() {
        this.mediaEntity = this.mediaEntityData.metadata as MediaEntity;
        if (!this.files) {
            this.files = [];
        }

        const foldersArray = Array.from({length: Math.min(this.totalFolders, LIBRARY_ICON_COUNT)}, (x, y) => { return { y: y, isFolder: true }; } );
        const children = foldersArray.concat(this.files).slice(0, LIBRARY_ICON_COUNT);

        this.children = children;
    }

    onLibraryClick() {
        if (!this.failedValidation) {
            this.clickLibrary.emit();
        }
    }

    onSelected() {
        if (!this.failedValidation) {
            this.selected = !this.selected;
            this.selectLibrary.emit();
        }
    }
}
