import { stringConstants } from "../../../common-constants";
import { ValidationError } from "../../shared/services/errors/validation-error";

export class FeedbackInfo {
    errorMessage = stringConstants.EMPTY_STRING;
    showError = false;
    showLoadingIndicator = false;
    showViewLoadingIndicator = false;

    reset() {
        this.showLoadingIndicator = false;
        this.errorMessage = stringConstants.EMPTY_STRING;
        this.showError = false;
    }

    setError(err) {
        this.showLoadingIndicator = false;
        this.showViewLoadingIndicator = false;

        if (err instanceof ValidationError && err.fieldErrors && err.fieldErrors.length > 0) {
            this.errorMessage = err.fieldErrors[0].errorType.message;
        } else if (err && err.message) {
            this.errorMessage = err.message;
        } else if (err.innerError &&  err.innerError.message) {
            this.errorMessage = err.innerError.message;
        } else if (err.innerError &&  err.innerErrors.length > 0 && err.innerErrors[0] && err.innerErrors[0].message) {
            this.errorMessage = err.innerErrors[0].message;
        } else if (err) {
            this.errorMessage = err;
        }

        if (this.errorMessage) {
            this.showError = true;
        }
    }
}
