import { Directive, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { HeaderMenuService } from "../modules/shared/services/header-menu.service";
import { DialogData, ModalWindowService } from "../modules/shared/services/modal-window.service";

@Directive({
    selector: "[sfHeaderMenuEventsHandler]"
})
export class HeaderMenuEventsHandlerDirective extends SfRxBase implements OnInit {
    constructor(
        private route: ActivatedRoute,
        private headerMenuService: HeaderMenuService,
        private modalWindowService: ModalWindowService) {
            super();
    }

    ngOnInit(): void {
        const headerMenuServiceSubscription = this.headerMenuService.onUserDialogOpen.subscribe((dialogData: DialogData) => {
            this.modalWindowService.setMapping(dialogData, dialogData.key);
            this.modalWindowService.show(dialogData.key, this.route);
        });

        this.registerSubscription(headerMenuServiceSubscription);
    }
}