import { Component, Inject, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { TreeNode } from "@circlon/angular-tree-component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { BehaviorSubject } from "rxjs";
import { NEW_TAB_TARGET } from "../../src/app/common-constants";
import { SelectorConstants } from "../../src/app/modules/html/selector-constants";
import { CreateLinkHelper } from "../../src/app/modules/html/tools/create-link/create-link-helper";
import { CreateLinkComponent } from "../../src/app/modules/html/tools/create-link/create-link.component";
import { EMAIL } from "../../src/app/modules/html/tools/create-link/link-insert-field/helpers/content-link-input-model";
import { Button, CancelButton, ClickData, ClickResult, ConfirmButton, DialogData, ModalWindowService } from "../../src/app/modules/shared/services/modal-window.service";
import { guid } from "../../src/app/utils";
import { WINDOW_TOKEN } from "../../src/app/window.provider";
import { FieldBase } from "../field-base";
import { TreeConfig } from "../tree/tree-wrapper.component";
import { LinkModel } from "./link-model";
import { LinkSelectorSettings } from "./link-selector.settings";

@Component({
    selector: "sf-link-selector",
    templateUrl: "./link-selector.component.html"
})
export class LinkSelectorComponent extends FieldBase<LinkSelectorSettings, string> implements OnInit{
    public buttonTitle: string;
    public buttonIcon: string;
    public treeConfig: TreeConfig;
    public visibleItems: BehaviorSubject<LinkModel[]> = new BehaviorSubject<LinkModel[]>([]);

    constructor(
        protected modalService: ModalWindowService,
        protected route: ActivatedRoute,
        @Inject(WINDOW_TOKEN) private window: Window,
        private createLinkHelper: CreateLinkHelper) {
        super();
    }

    ngOnInit(): void {
        super.ngOnInit();
        this.setButtonVisuals();

        this.treeConfig = {
            noSelection: true,
            drag: this.settings.allowMultiple && !this.settings.readOnlyMode,
            clickable: !this.settings.readOnlyMode,
            skipNodeMappingToDefaultModel: true,
            treeProperties: { idField: "id" }
        };
    }

    writeValue(value: string): void {
        super.writeValue(value);
        this.visibleItems.next(this.getCurrentValue());
        this.setButtonVisuals();
    }

    postProcessValue(value: any): any {
        if (value != null && !this.settings.allowMultiple && this.settings.valueIsSingleObject) {
            const current = JSON.parse(value);
            return JSON.stringify(current.length ? current[0] : value);
        }

        return super.postProcessValue(value);
    }

    getRequiredErrorMessage(): Array<string> {
        return [`${SelectorConstants.SELECT_BUTTON} ${this.settings.title}`];
    }

    onButtonClick() {
        let linkModel: LinkModel;
        if (!this.settings.allowMultiple && this.getCurrentValue()?.length > 0) {
            linkModel = this.getCurrentValue()[0];
        }

        this.addEditLink(linkModel);
    }

    addEditLink(linkModel?: LinkModel) {
        if (this.settings.readOnlyMode) {
            return;
        }

        const componentData: ComponentData = {
            type: CreateLinkComponent,
            properties: {
                showTextToDisplay: true,
                fieldsToSkip: this.settings.skippedFields
            }
        };

        if (linkModel) {
            componentData.properties.isInEditMode = true;
            const desctructuredLink = this.createLinkHelper.desctructureLink(linkModel.href);
            linkModel.href = desctructuredLink.elementLink;
            componentData.properties.linkModel = linkModel;
        }

        const confirmClickHandler = (data: ClickData): ClickResult => {
            const createLinkComponent: CreateLinkComponent = data.component;
            const clickResult: ClickResult = new ClickResult(createLinkComponent.link, createLinkComponent.isValid);
            return clickResult;
        };

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.INSERT_LINK, confirmClickHandler),
            new CancelButton(SelectorConstants.CANCEL)
        ];

        const dialogData = new DialogData(componentData, (context) => {
            if (context.data?.data) {
                let indexToAdd: number;
                if (linkModel) {
                    indexToAdd = this.getCurrentValue().findIndex(x => x.id === linkModel.id);
                    this.onRemove(linkModel);
                }

                this.insertLink(context.data.data, indexToAdd);
            }
        }, buttons);

        this.modalService.setMapping(dialogData, "createLink");
        this.modalService.show("createLink", this.route.parent);
    }

    onViewNode(node: TreeNode, event: Event) {
        event.preventDefault();
        event.stopImmediatePropagation();
        const linkModel = node.data as LinkModel;
        this.window.open(linkModel.href, NEW_TAB_TARGET);
    }

    onRemove(linkModel: LinkModel, event?: Event) {
        event?.preventDefault();
        event?.stopImmediatePropagation();
        this.writeCurrentValue(this.getCurrentValue().filter(x => x.id !== linkModel.id));
    }

    onReorderNodes(items): void {
        this.writeCurrentValue(items);
    }

    isViewVisible(linkModel: LinkModel) {
        return linkModel.type !== EMAIL;
    }

    protected  getCurrentValue(): LinkModel[] {
        const value = this.getValue() || [];
        return typeof(value) === "string" ? JSON.parse(this.getValue()) : value;
    }

    private writeCurrentValue(value: LinkModel[]): void {
        value.length > 0 ? this.writeValue(JSON.stringify(value) as any) : this.writeValue(null);
    }

    private insertLink(linkModel: LinkModel, index?: number) {
        linkModel.id = guid();
        const currentValue = this.getCurrentValue();

        if (index !== undefined) {
            currentValue.splice(index, 0, linkModel as any);
        } else {
            currentValue.push(linkModel);
        }

        this.writeCurrentValue(currentValue);
    }

    private setButtonVisuals() {
        this.buttonTitle = `Select`;
        this.buttonIcon = 'plus';

        if (!this.settings.allowMultiple && this.getCurrentValue()?.length > 0) {
            this.buttonTitle = "Edit";
            this.buttonIcon = 'pencil';
        }
    }
}
