import { Injectable, ClassProvider } from "@angular/core";
import { OperationsProvider, OperationsData, OperationsTarget } from "./interfaces";
import { CommandModelBase } from "../../../../shared/commands/command-model-base";
import { Observable, of } from "rxjs";
import { Operation, OperationCategory } from "../../../../shared/components/action-menu/operation.model";
import { OPERATIONS_TOKEN } from "./operations-provider";
import { ParentNavigateCommand } from "./commands/parent-navigate-command";
import { ROUTE_PATHS } from "../../../../../constants/route-paths";

@Injectable()
export class NavigationOperationsProvider implements OperationsProvider {
    getOperations(data: OperationsData): Observable<Operation[]> {
        return of([]);
    }

    getCommands(data: OperationsData): Observable<CommandModelBase[]> {
        const commands: Array<CommandModelBase> = [];

        if ((data.target === OperationsTarget.List && data.dataItem.isEmpty) &&
            (data.dataItem.metadata.ignoreParentChildRelationship &&
            data.dataItem.metadata.hasParent &&
            !data.dataItem.metadata.isMedia)) {

            const entityData = data.dataItem;

            const command = new CommandModelBase("navigateToParent");
            command.token = {
                type: ParentNavigateCommand,
                properties: {
                    route: [ROUTE_PATHS.CONTENT, entityData.metadata.parent]
                }
            };

            command.category = "Settings";
            command.title = `Manage ${entityData.metadata.parent}`;

            // for events and for templates it is positioned differently according to UX
            command.ordinal = -1;
            commands.push(command);
        }

        return of(commands);
    }

    getCategories(data: OperationsData): Observable<OperationCategory[]> {
        return of([]);
    }

    invalidateCachedItemOperations(itemId: string): void {}
}

export const NAVIGATION_PROVIDER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_TOKEN,
    useClass: NavigationOperationsProvider
};
