import { ActivatedRouteSnapshot, RouterStateSnapshot, Router } from "@angular/router";
import { DynamicItemService } from "../dynamic-item.service";
import { BaseResolver } from "../../components/dynamic-items-base.resolver";
import { ProviderStore } from "../provider-store";
import { Settings } from "../../../../shared/services/settings.service";

import { ROUTE_PARAMS } from "../../../constants";
import { EntityData, DataItem } from "../../interfaces";
import { Injectable } from "@angular/core";
import { stringConstants } from "../../../../../common-constants";
import { Observable } from "rxjs";
import { CompositeEntityDataResolver } from "../backend-tweaks/entity-data.resolver";

@Injectable()
export class ItemMetaResolver extends BaseResolver {

    constructor(
        private service: DynamicItemService,
        store: ProviderStore,
        router: Router,
        settings: Settings,
        entityDataResolver: CompositeEntityDataResolver) {
            super(store, router, settings, entityDataResolver);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<ItemMeta> {
        const entityData = super.resolve(route, state) as EntityData;

        const itemKey = this.getItemKey(route);
        const response = this.service.executeBoundFunction<ItemMeta>(
            DataItem.fromKey(itemKey, entityData),
            itemMetaSegment(null)
        );

        return response;
    }

    private getItemKey(route: ActivatedRouteSnapshot) {
        let itemKey = route.params[ROUTE_PARAMS.ITEM_ID];
        const segment = route.url[route.url.length - 1].path;
        if (!itemKey || segment === ROUTE_PARAMS.DUPLICATE_SEGMENT) {
            itemKey =  stringConstants.DEFAULT_GUID;
        }

        return itemKey;
    }
}

export function itemMetaSegment(state: string) {
    return `Default.itemmeta(state='${state}')`;
}

export interface ItemMeta {
    message: string;
    hasChanges: boolean;
    state: string;
    readonly: boolean;
    properties: FieldMetadata[];
}

interface FieldMetadata {
    name: string;
    hidden: boolean;
    readonly: boolean;
    allowCreate: boolean;
    allowAdd: boolean;
    allowRemove: boolean;
    allowView: boolean;
    status: string;
    statusMessage: string;
    predefinedValue: string;
}
