import { stringConstants } from "./common-constants";
import { IntegratedModeGuard } from "./services/admin-app/integrated-mode.guard";
import { RouterModule } from "@angular/router";

import { ConfigurationGuard } from "./components/config/config.guard";
import { ConfigComponent } from "./components/config/config.component";
import { HomeComponent } from "./modules/shared/components/navigation/home/home.component";
import { NotFoundComponent } from "./modules/shared/components/not-found/not-found.component";
import { MetadataStoreResolver } from "./modules/shared/services/metadata/meta-data-store.resolver";
import { UserDataStoreResolver } from "./modules/shared/services/metadata/user-data-store.resolver";
import { SiteDataStoreResolver } from "./modules/shared/services/metadata/site-data-store.resolver";
import { SiteTitleResolver } from "./modules/shared/services/site-title.resolver";
import { ROUTE_PATHS_NO_PREFIX, ROUTE_PATHS } from "./constants/route-paths";
import { FeatureComponent } from "./components/feature-toggle/feature.component";
import { RESOLVE_NAMES } from "./modules/content/constants";
import { NoPreviewComponent } from "./modules/shared/components/no-preview/no-preview.component";
import { AccessDeniedComponent } from "./modules/shared/components/access-denied/access-denied.component";
import { UnsupportedBrowserGuard } from "./components/use-a-browser/browser.guard";
import { UnsupportedBrowserNoticeComponent } from "./components/use-a-browser/browser-notice.component";
import { InsecureConnectionNoticeComponent } from "./components/insecure-connection/insecure-connection.component";
import { AuthGuard } from "./modules/auth/auth.guard";
import { PAGES_ROUTES, PRESETS_ROUTES, TEMPLATES_ROUTES } from "./modules/pages/pages.routes";
import { CONTENT_ROUTES } from "./modules/content/content.routes";
import { IntegratedEmptyComponent } from "./components/empty/integrated-empty.component";
import { IntegratedEmptyComponentGuard } from "./components/empty/integrated-empty.component.guard";
import { HomeGuard } from "./modules/shared/components/navigation/home/home.guard";
import { IntegrationsModule } from "./modules/integrations/integrations.module";
import { ConfigurationsModule } from "./modules/configurations/configurations.module";
import { FORMS_EDIT_ROUTES } from "./modules/forms/forms.routes";

const homeResolve = { userDataStore: UserDataStoreResolver, siteDataStore: SiteDataStoreResolver, siteTitle: SiteTitleResolver };
homeResolve[RESOLVE_NAMES.metadata] = MetadataStoreResolver;

export const appRoutes = [
    {
        path: ROUTE_PATHS.ROOT_PREFIX,
        children: [
            {
                path: stringConstants.EMPTY_STRING, canActivate: [UnsupportedBrowserGuard, ConfigurationGuard], children: [
                    {
                        path: ROUTE_PATHS_NO_PREFIX.HOME, component: HomeComponent,
                        canActivate: [AuthGuard],
                        resolve: homeResolve,
                        data: { animation: { value: ROUTE_PATHS_NO_PREFIX.MENU_HOME } }
                    },
                    {
                        path: ROUTE_PATHS_NO_PREFIX.FEATURES, component: FeatureComponent
                    },
                    // These routes are imported here, because we want to use base route as a root route for the application, and only the root
                    // route should use AuthGuard for authentication.
                    // Enable lazyLoading once angular team fixes the bug with initialization of Services twice (https://github.com/angular/angular/pull/14201)
                    // ,
                    // {
                    //     path: ROUTE_PATHS.CONTENT,
                    //     loadChildren: "./modules/content/content.module#ContentModule?chunkName=content"
                    // }

                    {
                        path: stringConstants.EMPTY_STRING, canActivate: [AuthGuard], children: [
                            ...CONTENT_ROUTES,
                            ...PAGES_ROUTES,
                            ...TEMPLATES_ROUTES,
                            ...FORMS_EDIT_ROUTES,
                            ...PRESETS_ROUTES,
                            {
                                path: ROUTE_PATHS_NO_PREFIX.INTEGRATIONS,
                                loadChildren: () => IntegrationsModule
                            },
                            {
                                path: ROUTE_PATHS_NO_PREFIX.CONFIGURATIONS,
                                loadChildren: () => ConfigurationsModule
                            }
                        ]
                    }
                ]
            },
            { path: "config", component: ConfigComponent },
            { path: "browser-notice", component: UnsupportedBrowserNoticeComponent },
            { path: "insecure-connection", component: InsecureConnectionNoticeComponent, canActivate: [IntegratedModeGuard] },
            { path: "not-found", component: NotFoundComponent },
            { path: "no-preview", component: NoPreviewComponent },
            { path: "access-denied", component: AccessDeniedComponent },
            { path: "**", redirectTo: ROUTE_PATHS_NO_PREFIX.NOT_FOUND }
        ]
    },
    {
        path: ROUTE_PATHS_NO_PREFIX.HOME,
        component: HomeComponent,
        canActivate: [HomeGuard]
    },
    {
        path: "**",
        canActivate: [IntegratedEmptyComponentGuard],
        component: IntegratedEmptyComponent
    }
];

export const routing = RouterModule.forRoot(appRoutes);
