import { Injectable } from "@angular/core";

import { SelectorConstants, NODE_NAMES, ANCHOR_ATTRIBUTES } from "../../selector-constants";
import { stringConstants } from "../../../../common-constants";
import { LinkModel } from "../../../../../../fields/link-selector/link-model";
import { ExternalAppConfigService } from "../../../../app-config/external-app-config.service";
import { ATTR_PREFIX } from "../../../pages/services/document-enhancer.constants";

export const ANCHOR_ELEMENT: string = "a";
export const HYPER_TEXT_TRANSFER_PROTOCOL = "http://";
export const MAILTO_PROTOCOL = "mailto:";

@Injectable()
export class CreateLinkHelper {
    constructor(private configService: ExternalAppConfigService) { }

    buildLink(linkData: LinkModel, htmlToDisplay: string = undefined): string {
        const linkElement: HTMLAnchorElement = <HTMLAnchorElement>document.createElement(ANCHOR_ELEMENT);
        this.setLinkAttributes(linkElement, linkData);
        if (linkData.text) {
            linkElement.innerText = linkData.text;
        } else {
            linkElement.innerText = stringConstants.EMPTY_STRING;
        }

        linkElement.setAttribute(SelectorConstants.SF_IMMUTABLE, stringConstants.EMPTY_STRING);

        let linkOuterHtml: string = linkElement.outerHTML;

        // Check if there is closing tag that was removed by the innerHTML logic
        const textToDisplay = linkData.text ? linkData.text : stringConstants.EMPTY_STRING;
        if (linkElement.innerText !== textToDisplay) {
            linkOuterHtml = linkElement.outerHTML.replace(linkElement.innerHTML, linkData.text);
        }

        if  (htmlToDisplay) {
            linkElement.innerHTML = htmlToDisplay;
            linkOuterHtml = linkElement.outerHTML;
        }

        return linkOuterHtml;
    }

    setLinkAttributes(linkElement: HTMLAnchorElement, linkData: LinkModel) {
        linkElement.href = linkData.href;
        linkElement.removeAttribute(ANCHOR_ATTRIBUTES.SFREF);
        if (linkData.sfref) {
            linkElement.setAttribute(ANCHOR_ATTRIBUTES.SFREF, linkData.sfref);
        }

        this.setTarget(linkData, linkElement);

        if (linkData.attributes) {
            Object.keys(linkData.attributes).forEach(
                (key) => linkElement.setAttribute(key, linkData.attributes[key] ? linkData.attributes[key] : stringConstants.EMPTY_STRING));
        }

        this.setQueryParamsAndAnchor(linkData, linkElement);
        this.setTooltip(linkData, linkElement);
        this.setCssClass(linkData, linkElement);
    }

    getWrappedLinkText(selectedTextHtml: string, selectedText: string) {
        const wrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);

        wrapper.innerHTML = selectedTextHtml;

        if (wrapper.innerText === selectedText) {
            return selectedTextHtml;
        }

        return selectedText;
    }

    shouldSetHtml(selectedTextHtml: string, selectedText: string) {
        const wrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);

        wrapper.innerHTML = selectedTextHtml;

        if (wrapper.innerText === selectedText) {
            return true;
        }

        return false;
    }

    getLinkModelData(innerText: string = stringConstants.EMPTY_STRING, anchorElement?: HTMLAnchorElement): LinkModel {
        let elementLink = anchorElement ? anchorElement.getAttribute(ANCHOR_ATTRIBUTES.HREF) || stringConstants.EMPTY_STRING : stringConstants.EMPTY_STRING;

        if (elementLink.startsWith(stringConstants.HASH) || elementLink.startsWith(stringConstants.QUESTION_MARK)) {
            elementLink = stringConstants.EMPTY_STRING;
        }

        const elementDynamicLink = anchorElement ? anchorElement.getAttribute(ANCHOR_ATTRIBUTES.SFREF) : stringConstants.EMPTY_STRING;
        const elementTitle = anchorElement ? anchorElement.getAttribute(ANCHOR_ATTRIBUTES.TITLE) : stringConstants.EMPTY_STRING;
        const elementTarget = anchorElement ? anchorElement.getAttribute(ANCHOR_ATTRIBUTES.TARGET) : stringConstants.EMPTY_STRING;
        const elementClassList = anchorElement ? anchorElement.classList.value : stringConstants.EMPTY_STRING;
        const elementInnerText = anchorElement ? anchorElement.innerText : innerText;

        const linkModel = this.desctructureLink(elementLink);
        elementLink = linkModel.elementLink;
        let elementAnchor = linkModel.elementAnchor;
        const elementQueryParams = linkModel.elementQueryParams;

        if (!elementAnchor) {
            // hash property returns the anchor element with "#" symbol before the value so this symbol is removed here
            elementAnchor = anchorElement ? anchorElement.hash.substring(1, anchorElement.hash.length) : stringConstants.EMPTY_STRING;
        }

        const linkAttributesData: LinkModel = {
            href: elementLink,
            sfref: elementDynamicLink,
            anchor: elementAnchor,
            queryParams: elementQueryParams,
            tooltip: elementTitle,
            target: elementTarget,
            text: elementInnerText,
            classList: elementClassList.split(stringConstants.INTERVAL),
            attributes: this.getElementAttributes(anchorElement)
        };

        return linkAttributesData;
    }

    desctructureLink(elementLink: string): {elementLink: string, elementAnchor: string, elementQueryParams: string } {
        elementLink = elementLink || stringConstants.EMPTY_STRING;
        let elementAnchor;
        let elementQueryParams;
        const anchorIndex = elementLink.indexOf(stringConstants.HASH);
        const queryIndex = elementLink.indexOf(stringConstants.QUESTION_MARK);
        const mailIndex = elementLink.indexOf(MAILTO_PROTOCOL);

        // The '?' char is allowed in emails, but the logic confuses it with query string, so the mail check should be the first one.
        if (mailIndex === 0) {
            elementLink = elementLink.substring(MAILTO_PROTOCOL.length);
            elementAnchor = stringConstants.EMPTY_STRING;
            elementQueryParams = stringConstants.EMPTY_STRING;
        } else if (queryIndex !== -1) {
            if (anchorIndex !== -1) {
                elementQueryParams = elementLink.substring(queryIndex + 1, anchorIndex);
                elementAnchor = elementLink.substring(anchorIndex + 1);
            } else {
                elementQueryParams = elementLink.substring(queryIndex + 1);
                elementAnchor = stringConstants.EMPTY_STRING;
            }
        } else if (anchorIndex !== -1) {
            elementAnchor = elementLink.substring(anchorIndex + 1);
            elementQueryParams = stringConstants.EMPTY_STRING;
        } else {
            elementAnchor = stringConstants.EMPTY_STRING;
            elementQueryParams = stringConstants.EMPTY_STRING;
        }

        return { elementLink, elementAnchor, elementQueryParams };
    }

    private getElementAttributes(anchorElement: HTMLAnchorElement): { [key: string]: string } {
        const elementAttributes = {};
        for (let i = 0; i < anchorElement?.attributes.length; i++) {
            const attribute = anchorElement.attributes[i];
            if (attribute.name !== ANCHOR_ATTRIBUTES.SFREF &&
                attribute.name !== ANCHOR_ATTRIBUTES.HREF &&
                attribute.name !== "class" &&
                !attribute.name.startsWith(ATTR_PREFIX)) {
                elementAttributes[attribute.name] = attribute.value;
            }
        }

        return elementAttributes;
    }

    private setTarget(linkData: LinkModel, linkElement: HTMLAnchorElement) {
        if (linkData.target) {
            linkElement.target = linkData.target;
        }
    }

    private setQueryParamsAndAnchor(linkData: LinkModel, linkElement: HTMLAnchorElement): void {
        this.clearQueryParamsAndAnchor(linkData, linkElement);

        let anchor = "";
        let queryParams = "";

        if (linkData.queryParams) {
            let querySymbolToBeAdded = stringConstants.QUESTION_MARK;
            // Check if first symbol of the provided query string is "?" and don't add another one
            if (linkData.queryParams[0] === querySymbolToBeAdded) {
                querySymbolToBeAdded = stringConstants.EMPTY_STRING;
            }

            queryParams = `${querySymbolToBeAdded}${linkData.queryParams}`;
        }

        if (linkData.anchor) {
            let anchorSymbolToBeAdded = stringConstants.HASH;
            // Check if first symbol of the provided anchor string is "#" and don't add another one
            if (linkData.anchor[0] === anchorSymbolToBeAdded) {
                anchorSymbolToBeAdded = stringConstants.EMPTY_STRING;
            }

            anchor = `${anchorSymbolToBeAdded}${linkData.anchor}`;
        }

        if (anchor || queryParams) {
            const baseUrl = linkData.href ? linkElement.href : stringConstants.EMPTY_STRING;
            linkElement.href = `${baseUrl}${queryParams}${anchor}`;
        }
    }

    private clearQueryParamsAndAnchor(linkData: LinkModel, linkElement: HTMLAnchorElement) {
        // Remove existing query params
        if (!linkData.queryParams && !linkData.anchor) {
            return;
        }

        if (linkElement.href.includes(stringConstants.QUESTION_MARK)) {
            const queryParamsIndex = linkElement.href.indexOf(stringConstants.QUESTION_MARK);
            linkElement.href = linkElement.href.substring(0, queryParamsIndex);
        } else if (linkElement.href.includes(stringConstants.HASH)) {
            const hashIndex = linkElement.href.indexOf(stringConstants.HASH);
            linkElement.href = linkElement.href.substring(0, hashIndex);
        }
    }

    private setTooltip(linkData: LinkModel, linkElement: HTMLAnchorElement): void {
        if (linkData.tooltip) {
            linkElement.title = linkData.tooltip;
        }
    }

    private setCssClass(linkData: LinkModel, linkElement: HTMLAnchorElement): void {
        if (linkData.classList) {
            this.addClassesToAnchor(linkData.classList, linkElement);
        }
    }

    addClassesToAnchor(newClasses: string[], linkElement: HTMLAnchorElement) {
        const allStyles = this.configService.externalConfig?.linkStyles || [];
        allStyles.forEach(style => linkElement.classList.remove(...style.Value));
        linkElement.classList.add(...newClasses);
    }
}
