import { TreeConfig } from "../tree/tree-wrapper.component";
import { MediaHelpers } from "../../src/app/modules/libraries/services/media.helpers";

export const RECENT_ITEMS_COUNT: number = 5;
// The show all button
const ADDITIONAL_NODES_COUNT: number = 1;
const INITALLY_SHOWN_ITEMS_COUNT: number = 20;
const NOT_FOUND_KEY: string = "NotFound";

@Component({
    selector: "sf-related-data",
    templateUrl: "./related-data.component.html"
})
export class RelatedDataComponent extends FieldBase<RelatedDataSettings, any[]> implements OnInit, AfterViewInit {
    @ViewChildren("editableElement") queryContents: QueryList<ViewContainerRef>;
    @ViewChild("tree", { static: true }) tree: TreeWrapperComponent;
    @ViewChild("popupTree", { static: false }) popupTree: TreeWrapperComponent;
    @Input() treeConfig: TreeConfig;
    isInputVisible: boolean = false;
    isAddButtonVisible: boolean = true;
    isPopupVisible: boolean = true;
    addEditButtonTitle: string;

    searchTerm: string;
    loadMoreText: string;
    hasContentItems: Observable<boolean>;
    popupTreeConfig: TreeConfig;
    triggeringSubscription = new BehaviorSubject(false);
    _defaultFieldName: string;
    public displayNames: TypeNames;

    protected _relatedDataEntity: Entity;
    protected showBreadcrumb: boolean;
    protected relatedEntityData: EntityData;
    protected fallbackProperties: Array<string>;
    protected retrieveItems: boolean = true;

    protected allItemsTabType: Type<Selector>;
    protected allItemsTabLook: string;
    protected allItemsTabTypePropertyValues: {};
    protected allowedProviders: string[];

    private rootId: string;
    private parentId: string;
    private additionalQueryParams?: { [key: string]: string };
    private parentIdProperty: string = Properties.PARENT_ID;
    private rootIdProperty: string = Properties.ROOT_ID;

    private editableElement: ElementRef;
    private serviceAware: ServiceContract;
    private _initiallyShownItems: number;
    private hiddenItems: Set<string>;
    private visibleItems$: BehaviorSubject<any[]>;
    private visibleItemsFilter$: Observable<any[]>;
    private _recentItemsSubject$: BehaviorSubject<any[]>;
    private _recentItems$: Observable<any[]>;
    private allSites: any[] = [];
    private currentSiteId: string = null;
    private retrieveRecentItems: boolean = true;

    constructor(
        protected dynamicService: DynamicItemService,
        protected modalService: ModalWindowService,
        protected route: ActivatedRoute,
        private siteDataStore: SiteDataStore,
        protected metadataStore: MetadataStore,
        private renderer: Renderer2,
        protected element: ElementRef,
        private filterService: ContentFilterService,
        @Inject(WINDOW_TOKEN) private window: Window,
        protected urlService: UrlService,
        protected editNavigationService: EditNavigationService,
        private settingsService: Settings
    ) {
        super();

        this.hiddenItems = new Set<string>();
        this.visibleItems$ = new BehaviorSubject<any[]>([]);
        this.visibleItemsFilter$ = this.visibleItems$
            .asObservable().pipe(
                map((data) => this.filterVisibleItems(data)));

        this._recentItemsSubject$ = new BehaviorSubject<any[]>([]);
        this._recentItems$ = this._recentItemsSubject$.asObservable();
        this.hasContentItems = this._recentItems$.pipe(map((arr) => arr.filter((x) => !x.isSeparator && !x.isLink)), map((arr) => arr.length > 0));
    }

    get recentItems$(): Observable<any[]> {
        return this._recentItems$;
    }

    get initiallyShownItems(): number {
        return this._initiallyShownItems;
    }

    get hasHiddenItems(): boolean {
        return this.hiddenItems.size > 0;
    }

    get hiddenItemsCount(): number {
        return this.hiddenItems.size;
    }

    get visibleItems(): Observable<any[]> {
        return this.visibleItemsFilter$;
    }

    get canSelectItems(): boolean {
        return !(!this.settings.allowMultiple && this.value && this.value.length > 0);
    }

    get showSiteSelector(): boolean {
        return this.settings.showSiteSelector && this.allSites && this.allSites.length > 1;
    }

    ngOnInit(): void {
        super.ngOnInit();

        // if the project was initially older than 12.2 (upgraded) than the single related data value will be returned as object instead of an array (ProcessLegacySingleRelatedData config)
        if (this.value && !Array.isArray(this.value)) {
            this.value = [this.value];
        }

        this._relatedDataEntity = this.metadataStore.getEntity(this.settings.type);
        this._defaultFieldName = this.settings.displayFieldName ? this.settings.displayFieldName : this.metadataStore.getDefaultFieldName(this.settings.type);
        if (this.value) {
            this.value.forEach(item => this.markTranslated(item));
        }

        this.populateHiddenItems(this.value, INITALLY_SHOWN_ITEMS_COUNT);

        this._initiallyShownItems = INITALLY_SHOWN_ITEMS_COUNT;
        this.fallbackProperties = this.getFallbackProperties(this.settings.type);
        this.evaluateBreadcrumbVisibility();

        if (this.settings && this.settings.type) {
            this.displayNames = {
                plural: this.metadataStore.getPropertyMetadata(this.settings.type, DISPLAY_NAME).toLowerCase(),
                singular: this.metadataStore.getPropertyMetadata(this.settings.type, SINGULAR_NAME).toLowerCase()
            };

            const title: string = this.hiddenItemsCount > 1 ? this.displayNames.plural.toLocaleLowerCase() : this.displayNames.singular.toLocaleLowerCase();
            this.loadMoreText = `${this.hiddenItemsCount} more ${title}`;
            this.setAddEditButtonTitle();
        }

        this.parentIdProperty = this._relatedDataEntity.parentIdProperty || null;
        this.siteDataStore.getValue().pipe(first()).subscribe(siteData => {
            this.currentSiteId = siteData.Id;
            if (this.settings.type === ENTITY_SET.PAGES) {
                this.rootId = siteData.SiteMapRootNodeId;
                this.parentId = siteData.SiteMapRootNodeId;
            }

            this.allowedProviders = this.siteDataStore.getAllowedProvidersFromSiteData(this._relatedDataEntity.setName, siteData);

            const hasAnySiteSourceProvider = this.settings.provider === ANY_SITE_SOURCE_PROVIDER;
            if (hasAnySiteSourceProvider) {
                // any site provider is a 'special' type of provider meant for usage in related data fields
                // in that case the field should show a provider selector when relating items and use the default provider initially
                // setting the provider to empty string in the field settings instructs it to use the default provider for the items that will be related
                this.settings.provider = stringConstants.EMPTY_STRING;

                const providersCount = this.allowedProviders.filter(p => p !== ANY_SITE_SOURCE_PROVIDER && p !== DEFAULT_SITE_SOURCE_PROVIDER).length;
                if (providersCount > 1) {
                    this.allItemsTabType = ProviderSelectorComponent;

                    if (this.settings.allowMultiple) {
                        this.allItemsTabType = ProviderTabSelectorComponent;
                        this.allItemsTabLook = PROVIDER_TAB_CSS_CLASS;
                    }

                    this.allItemsTabTypePropertyValues = {
                        // the type of the items that are being related
                        entitySetName: this.settings.type
                    };
                }
            }

            const warnings = this.getWarnings();
            if (warnings && warnings.length > 0) {
                return;
            }

            this.relatedEntityData = {
                culture: this.settings.culture,
                provider: this.settings.provider,
                metadata: this._relatedDataEntity
            };

            const sitesLoaded$ = new Observable(o => {
                if (this.settings.showSiteSelector) {
                    this.getAllSites().pipe(first()).subscribe(sites => {
                        this.allSites = sites.map(s => Object.assign({}, s.data));
                        o.next();
                    });
                } else {
                    o.next();
                }
            });

            this.retrieveRecentItems = !this.settings.skipInputSelection;
            sitesLoaded$.pipe(first()).subscribe(() => {
                if (this.retrieveItems && this.retrieveRecentItems) {
                    this.getRecentRelatedData(this.value);
                }
            });
        });

        this.treeConfig = this.treeConfig || {
            deletion: this.settings.allowRemove,
            drag: this.settings.allowMultiple && !this.settings.disableInteraction,
            previewUrl: !this.settings.disableInteraction,
            status: !this.settings.hideStatus,
            noSelection: true,
            showBreadcrumb: this.showBreadcrumb,
            clickable: !this.settings.disableInteraction,
            customComponentOriginatingFeature: TreeNodeComponentFeatures.RelatedData,
            customComponentEntitySet: this.settings.type
        };

        this.popupTreeConfig = {
            showBreadcrumb: this.treeConfig.showBreadcrumb,
            status: !this.settings.hideStatus,
            noSelection: false,
            customComponentOriginatingFeature: TreeNodeComponentFeatures.RelatedData,
            customComponentEntitySet: this.settings.type
        };

        this.serviceAware = new ServiceContract(
            (info: ServiceInfo) => this.loadMoreModalItems(info),
            (info: ServiceInfo) => this.loadMoreModalItems(info));

        if (this.settings.displayMode === DISPLAY_MODE.INPUT) {
            this.isAddButtonVisible = false;
            this.value.forEach((value) => {
                if (value[NOT_FOUND_KEY]) {
                    if (value[NOT_FOUND_KEY] === true) {
                        this.isAddButtonVisible = true;
                    }
                }
            });

            if (this.canSelectItems) {
                this.onToggleAddControl(true);
            }
        }

        if (this.settings.type === ENTITY_SET.PIPE_SETTINGS) {
            if (this.route.snapshot.data.itemData) {
                this.additionalQueryParams = {
                    [QUERY_PARAMS.SEARCHINDEXID]: this.route.snapshot.data.itemData.entityData.Id
                };
            }
        }
    }

    ngAfterViewInit(): void {
        this.queryContents.changes.subscribe((values: QueryList<any>) => {
            this.editableElement = values.first;
            this.focusEditableElement();

            if (this.isDisplayModeInputAndCanSelect()) {
                this.triggeringSubscription.next(true);
            }
        });
    }

    getRequiredErrorMessage(): Array<string> {
        return [`${SelectorConstants.SELECT_BUTTON} ${this.settings.title}`];
    }

    onViewNodeFunkWrapper(node: TreeNode) {
        this.onViewNodeFunk(node, true);
    }

    treeNodeClickedFunk(node: TreeNode) {
        this.onViewNodeFunk(node, false);
    }

    onViewNodeFunk(node: TreeNode, isViewClicked: boolean): void {
        // Note that for now some inherited components do not support on click Edit(View) Node (Docs/Media/Images)
        if (!this.element) {
            return;
        }

        if (this._relatedDataEntity.hasParent) {
            node.data.parentType = this._relatedDataEntity.parent;
        }

        // TODO: Fields comment here
        let item: DataItem;
        const provider = node.data.provider || this.settings.provider;
        if (isViewClicked) {
            if (!this.isViewUrlAllowed(this._relatedDataEntity, node.data)) {
                return;
            }

            item = DataItem.from(node.data, this._relatedDataEntity, provider, this.settings.culture);
            this.openPreview(item);
        } else if (!this._relatedDataEntity.enabled) { // We should not be able to click items that are not supported in Iris such as Page/Events.
            return;
        } else {
            if (!this.isEditAllowed(this._relatedDataEntity, node.data)) {
                return;
            }

            // EventEmitter.emit() doesn`t bubble up
            node.data.entitySet = this.settings.type;
            item = DataItem.from(node.data, this._relatedDataEntity, provider, this.settings.culture);
            this.onEdit(item);
        }
    }

    onReorderNodes(items): void {
        this.writeValue(items);
    }

    onMoveNode(event) {
        const movedItem = event.node;
        movedItem[JUST_ADDED_PROPERTY] = true;

        setTimeout(() => {
            movedItem[JUST_ADDED_PROPERTY] = false;
        }, REMOVE_ANIMATION_CLASS_TIMEOUT);
    }

    writeValue(value: any[]): void {
        if (value && value.length) {
            if (this.value && this.value.length > value.length && this.hiddenItemsCount > 0) {
                this.hiddenItems.forEach((itemId) => {
                    const hiddenItem = this.value.find(i => i.Id == itemId);
                    if (hiddenItem) {
                        value.push(hiddenItem);
                    }
                });
            }

            const valueArr: any[] = value;
            valueArr.forEach((val) => {
                if (val.isTranslated === undefined) {
                    this.markTranslated(val);
                }

                this.setProviderFromServer(val);
            });
        }

        super.writeValue(value);
        this.visibleItems$.next(value);
        this.setAddEditButtonTitle();
    }

    onShowAdditionalItems(): void {
        this.hiddenItems.clear();
        this.writeValue(this.value);
    }

    onNewInputValue(event: Event): void {
        this.popupTree.clearFocusedNode();

        if (this.retrieveRecentItems) {
            this.getRecentRelatedData(this.value);
        }

        if (this.settings.displayMode === DISPLAY_MODE.INPUT) {
            this.isPopupVisible = true;
        }
    }

    onRemove(node?: TreeNode): any {
        let item;
        if (node) {
            item = node.data;
        } else if (!this.settings.allowMultiple) {
            item = this.value[0];
        }

        const index = this.value.indexOf(item);
        if (index < 0) {
            return;
        }

        if (!item.Failure) {
            this.returnRemovedItemToRecentItems(item);
        }

        this.value.splice(index, 1);
        this.tree.updateTreeModel();
        this.onChangeCallback(this.value);

        this.writeValue(this.value);

        if (this.settings.displayMode === DISPLAY_MODE.INPUT) {
            this.onToggleAddControl(true);
        }

        return item;
    }

    onToggleAddControl(isAddingItem: boolean = false, isFocusOut: boolean = false) {
        this.isInputVisible = isAddingItem;
        this.isPopupVisible = isAddingItem;

        if (this.searchTerm) {
            this.searchTerm = null;

            if (this.retrieveRecentItems) {
                this.getRecentRelatedData(this.value);
            }
        }

        // When not in InputMode there must be Add/Edit button, otherwise item can be added using the input and with the (x) the item can be removed.
        if (this.settings.displayMode !== DISPLAY_MODE.INPUT) {
            this.isAddButtonVisible = !this.isPopupVisible;
        }

        // If ESC key is pressed or focused out when in InputMode, the popup with recent items must be hidden and only the input must be visible.
        if (isFocusOut && this.isDisplayModeInputAndCanSelect()) {
            this.isInputVisible = true;
            this.isPopupVisible = false;
        }

        this.handleFocus(this.isPopupVisible);
    }

    onEscapeKey(): void {
        this.onToggleAddControl(false, true);
    }

    onFocusTree(): void {
        this.popupTree.focusTree();
    }

    onFocusNextNode(): void {
        this.popupTree.focusNextNode();
    }

    onFocusPreviousNode(): void {
        this.popupTree.focusPreviousNode();
    }

    onEnterKey(): void {
        this.popupTree.selectCurrentNode();
    }

    onNewItemSelected(item: any): any {
        const node = item.node || item;

        if (node.isSeparator) {
            return;
        }

        if (node.isLink || (node.data && node.data.action)) {
            this[node.data.action]();
            return;
        }

        if (!this.canSelectItems) {
            this.onRemove();
        }

        this.onToggleAddControl();

        const selectedItem = item.data;
        const newValue = this.value.concat(selectedItem);

        this.onChangeCallback(newValue);

        if (this.retrieveRecentItems) {
            this.getRecentRelatedData(newValue);
        }

        selectedItem[JUST_ADDED_PROPERTY] = true;
        this.tree.updateTreeModel();

        setTimeout(() => {
            selectedItem[JUST_ADDED_PROPERTY] = false;
        }, REMOVE_ANIMATION_CLASS_TIMEOUT);

        this.writeValue(newValue);

        return node.data;
    }

    onShowAllRelatedData(): void {
        this.loadInitialModalItems().pipe(first()).subscribe(initialItems => {
            const hasParentType: boolean = this._relatedDataEntity.properties.hasOwnProperty(Properties.PARENT);
            const hasParentId: boolean = this._relatedDataEntity.properties.hasOwnProperty(Properties.PARENT_ID);

            // items that have parent, but no parent type are showed in hierarchical selector and have no breadcrumb shown - pages, taxonomies, items that have parent and parent type are shown in flat selector (without expanding) and have breadcrumb shown - hierarchical dynamic types, blogs
            const isMainTreeHierarchical = hasParentId && !hasParentType;
            const showBreadcrumbInMainTree = this.showBreadcrumb && !isMainTreeHierarchical;
            const componentData: ComponentData = {
                type: SelectorComponent,
                properties: {
                    value: initialItems.dataItems,
                    selected: this.value.map(x => x),
                    totalItemsCount: initialItems.totalCount,
                    treeConfig: {
                        multiSelection: this.settings.allowMultiple,
                        isHierarchical: isMainTreeHierarchical,
                        showBreadcrumb: showBreadcrumbInMainTree,
                        status: !this.settings.hideStatus,
                        customComponentOriginatingFeature: TreeNodeComponentFeatures.RelatedData,
                        customComponentEntitySet: this.settings.type
                    },
                    searchTreeConfig: {
                        multiSelection: this.settings.allowMultiple,
                        isHierarchical: false,
                        showBreadcrumb: this.showBreadcrumb,
                        status: !this.settings.hideStatus,
                        customComponentOriginatingFeature: TreeNodeComponentFeatures.RelatedData,
                        customComponentEntitySet: this.settings.type
                    },
                    serviceAware: this.serviceAware,
                    typeNames: this.displayNames,
                    defaultField: this._defaultFieldName,
                    keyField: this.relatedEntityData.metadata.key,
                    allItemsTabType: this.allItemsTabType,
                    allItemsTabLook: this.allItemsTabLook,
                    allItemsTabTypePropertyValues: this.allItemsTabTypePropertyValues
                }
            };

            if (this.showSiteSelector) {
                componentData.properties.selectorFilterConfig = {
                    filterChipsConfig: {
                        showSelectedItemAsActive: true
                    },
                    selectedFilterItems: this.allSites.filter(s => s.Id === this.currentSiteId),
                    filterItems: this.allSites,
                    filterLabel: "Site",
                    defaultField: "Name"
                };
            }

            const buttons: Button[] = [
                new ConfirmButton(SelectorConstants.USE_SELECTED),
                new CancelButton(SelectorConstants.CANCEL)
            ];
            const dialogData = new DialogData(componentData, (context: ClosingContext) => this.onDone(context), buttons, null, "-bottom");

            this.modalService.setMapping(dialogData, SELECTOR_MAPPING_KEY);
            this.modalService.open(this.route, SELECTOR_MAPPING_KEY);
        });
    }

    onShowCreateScreen(): void {
        const relatedEntityData: EntityData = {
            culture: this.settings.culture,
            provider: this.settings.provider,
            metadata: this._relatedDataEntity
        };

        const item = DataItem.emptyItem(relatedEntityData);
        this.invokeAllowDialogOpenCallback().subscribe(() => {
            this.editNavigationService.openDialogForRelatedData(item, this.route, null, false, this.getHeadComponentData()).subscribe((returnResponse) => {
                if (returnResponse.dataItem && returnResponse.dataItem.data) {
                    const newItem = cloneObject(returnResponse.dataItem.data);
                    const newValue = this.settings.allowMultiple ? this.value.concat(newItem) : [newItem];
                    this.onChangeCallback(newValue);
                    newValue[JUST_ADDED_PROPERTY] = true;
                    this.tree.updateTreeModel();
                    setTimeout(() => {
                        newValue[JUST_ADDED_PROPERTY] = false;
                    }, REMOVE_ANIMATION_CLASS_TIMEOUT);
                    this.writeValue(newValue);
                }
            });
        });
    }

    onDone(context): void {
        if (!context.data || !context.data.data) {
            return;
        }

        const dialogueItems: any[] = (context.component as any).selected;

        dialogueItems.forEach((relatedItem) => {
            const item: any = relatedItem.data || relatedItem;
            if (!this.value.includes(item)) {
                item[JUST_ADDED_PROPERTY] = true;
            }
            item.isActive = false;
        });

        this.value = (context.component as any).selected;

        if (this.retrieveRecentItems) {
            this.getRecentRelatedData(this.value);
        }

        this.tree.updateTreeModel();
        setTimeout(() => {
            this.value.forEach((value) => {
                if (value[JUST_ADDED_PROPERTY]) {
                    value[JUST_ADDED_PROPERTY] = false;
                }
            });
        }, REMOVE_ANIMATION_CLASS_TIMEOUT);
        this.onChangeCallback(this.value);
    }

    getWarnings(): Array<string> {
        if (!this.settings.allowView) {
            return [this.getNoPermissionMessage(this.settings.type)];
        } else if (this.settings.provider &&
            this.allowedProviders.indexOf(this.settings.provider) === -1 &&
            this.allowedProviders.indexOf(stringConstants.ASTERISK) === -1) {
            return [CONTENT_SOURCE_NOT_AVAILABLE_WARNING];
        } else if (this.settings.provider === stringConstants.EMPTY_STRING &&
            this.allowedProviders.length === 0) {
            // case where any site provider is selected, but there are no providers assigned to that field in the current site
            return [CONTENT_SOURCE_NOT_AVAILABLE_WARNING];
        }

        return super.getWarnings();
    }

    protected getActionLinks(hasItems: boolean, searchTerm: string): any[] {
        const result = [];
        if (hasItems || searchTerm || this.showSiteSelector) {
            result.push({
                isLink: true,
                [this._defaultFieldName]: `Show all ${this.displayNames.plural}`,
                action: "onShowAllRelatedData"
            });
        }

        let canOpenDialog = true;
        // this check confirms that we have already an open dialog
        if (this.route.snapshot.outlet.includes("dialog")) {
            const entityData = this.settings.entityData;
            if (entityData) {
                // blogs, lists and pages can open, others cant
                canOpenDialog = !entityData.metadata.hasLifecycle || entityData.metadata.setName === ENTITY_SET.PAGES;
            }
        }

        if (canOpenDialog && this.settings.allowCreate && this.isCreatePossible(this._relatedDataEntity)) {
            result.push({
                isLink: true,
                [this._defaultFieldName]: `Create ${indefiniteArticle(this.displayNames.singular)} ${this.displayNames.singular}`,
                action: "onShowCreateScreen"
            });
        }

        return result;
    }

    protected handleFocus(isFocused: boolean) {
        if (isFocused) {
            this.onFocus();
        } else {
            this.onBlur();
        }
    }

    protected createBaseServiceInfo(): BaseServiceInfo {
        const info: BaseServiceInfo = {
            type: this.settings.type,
            provider: this.settings.provider,
            fallbackProperties: this.fallbackProperties,
            culture: this.settings.culture
        };

        return info;
    }

    protected getRecentRelatedData(value: any[]): void {
        const warnings = this.getWarnings();
        if (warnings && warnings.length > 0) {
            return;
        }

        const info = this.createBaseServiceInfo();
        const args: LoadItemsData = {
            entityData: this.relatedEntityData,
            fallbackProperties: this.fallbackProperties,
            filter: this.settings.filter ? cloneObject(this.settings.filter) : []
        };

        if (info.action) {
            args.take = RECENT_ITEMS_COUNT;
            args.order = `${Properties.LAST_MODIFIED} ${SORT_ORDER.DESCENDING}`;
            args.action = info.action;

            if (this.searchTerm) {
                args.filter = this.filterService.buildSearchFilter(this.relatedEntityData, this.searchTerm);
            }

            if (this.showSiteSelector) {
                args.siteId = this.currentSiteId;
            }

            if (value && value.length) {
                args.itemsToExclude = { key: ID_KEY, value: value.map(x => x.Id) };
            }

            this.getItemList(args).pipe(map(data => {
                this.parseGetRecentResult(data);
            })).subscribe();
        } else {
            args.action = "Default.GetRecent";

            // The GetRecent endpoint is queried via a POST request because of the need to send payload with many ids of items
            // which to exclude from the query (sometimes they can be more than 2000). The sdk that calls the OData services does
            // not add fallbackProperties so we set them as additionalQueryParams
            const fallbackPropName = this.relatedEntityData ? this.relatedEntityData.metadata.defaultFieldName : Properties.TITLE;
            args.additionalQueryParams = {
                [QUERY_PARAMS.FALLBACK_PROPERTIES]: fallbackPropName
            };

            if (this.searchTerm) {
                args.additionalQueryParams[QUERY_PARAMS.SEARCH] = this.searchTerm;
            }

            if (this.relatedEntityData && MediaHelpers.isLibraryOrMedia(this.relatedEntityData.metadata.setName)) {
                args.additionalQueryParams[QUERY_PARAMS.SKIP_DAM] = "true";
            }

            args.payload = {
                excludedItemIds: []
            };

            if (value && value.length) {
                args.payload.excludedItemIds = value.map(x => x.Id);
            }

            if (this.showSiteSelector) {
                args.siteId = this.currentSiteId;
            }

            this.dynamicService.getRecent(args).subscribe(data => {
                this.parseGetRecentResult(data);
            });
        }
    }

    protected cloneAndAddFieldsToDataItem(dataItem: DataItem): any {
        const item = JSON.parse(JSON.stringify(dataItem.data));
        item.isTranslated = dataItem.isTranslated;
        item.hasChildren = item.HasChildren;
        item.setName = dataItem.metadata.setName;

        return item;
    }

    protected addItemsToRecentItems(items: any[]) {
        const actionLinks = this.getActionLinks(items.length > 0, this.searchTerm);
        items = items.concat(actionLinks);
        this._recentItemsSubject$.next(items);
    }

    private getHeadComponentData(): ComponentData {
        const relatedEntityData: EntityData = {
            culture: this.settings.culture,
            provider: this.settings.provider,
            metadata: this._relatedDataEntity
        };

        const item = DataItem.emptyItem(relatedEntityData);
        const headComponentData: ComponentData = {
            type: WorkflowOperationsMenuComponent,
            properties: {
                dataItem: item,
                operationsTarget: OperationsTarget.Create,
                iconTitle: "More Options",
                ariaLabel: "More Options",
                buttonsLook: "circle",
                dropdownButtonIconName: "ellipsis-h",
                options: new ActionMenuOptions(OUTSIDE_MENU_MAX_ORDINAL, Number.POSITIVE_INFINITY, true)
            }
        };

        return headComponentData;
    }

    private onEdit(item: DataItem) {
        const itemIds = this.getValue().map(x => x[item.metadata.key]);
        this.editNavigationService.openDialogForRelatedDataAndLoadFieldData(itemIds, item, this.route, null, false, this.getHeadComponentData()).subscribe((refreshedItems) => {
            const sortOrder = this.value.map(i => i.Id);

            const sortedItems = refreshedItems.sort((a, b) => {
                return sortOrder.indexOf(a.Id) - sortOrder.indexOf(b.Id);
            });

            this.writeValue(sortedItems);
        });
    }

    private openPreview(item: DataItem) {
        // The redirect is created before the dynamicItemStore request to avoid the blocked pop-up of the browser
        const redirect = this.window.open(stringConstants.EMPTY_STRING, NEW_TAB_TARGET);
        this.dynamicService.executeOperation(item, OPERATION_NAMES.preview).subscribe(operationResult => {
            if (operationResult.success && operationResult.link) {
                redirect.location.href = operationResult.link;
            } else {
                const noPreviewUrl = NoPreviewComponent.getPreviewUrl(this.urlService, item);
                redirect.location.href = noPreviewUrl;
            }
        });
    }

    private setAddEditButtonTitle() {
        if (this.displayNames) {
            if (this.settings.allowMultiple) {
                this.addEditButtonTitle = `Select ${this.displayNames.plural}`;
            } else {
                this.addEditButtonTitle = `Select ${this.displayNames.singular}`;
                if (this.value && this.value.length > 0) {
                    this.addEditButtonTitle = "Edit";
                }
            }
        }
    }

    private loadInitialModalItems(): Observable<any> {
        const info = this.createBaseServiceInfo();
        const serviceInfo = Object.assign(<ServiceInfo>{}, info);
        if (this.showSiteSelector) {
            serviceInfo.filterValue = this.allSites.filter(s => s.Id === this.currentSiteId)[0];
        }

        return this.loadMoreModalItems(serviceInfo);
    }

    private loadMoreModalItems(serviceInfo: ServiceInfo): Observable<any> {
        const baseInfo = this.createBaseServiceInfo();
        const provider = serviceInfo.allItemsTabValue || this.relatedEntityData.provider;

        const args: LoadItemsData = {
            entityData: {
                culture: this.relatedEntityData.culture,
                metadata: this.relatedEntityData.metadata,
                provider: provider
            },
            skip: serviceInfo.skip,
            take: serviceInfo.take,
            order: `${this._defaultFieldName} desc`,
            filter: this.settings.filter ? cloneObject(this.settings.filter) : [],
            action: baseInfo.action,
            fallbackProperties: this.fallbackProperties,
            additionalQueryParams: this.additionalQueryParams
        };

        if (serviceInfo.searchText) {
            args.filter.push(...this.filterService.buildSearchFilter(this.relatedEntityData, serviceInfo.searchText));
        }

        if (serviceInfo.filterValue && serviceInfo.filterValue.Id) {
            args.siteId = serviceInfo.filterValue.Id;
        }

        if (this._relatedDataEntity.hasChildren && !serviceInfo.searchText) {
            const parentId = serviceInfo.parentId || this.parentId;
            if (parentId) {
                this.addHierarchicalFilters(args, parentId);
            }
        }

        return this.getItemList(args).pipe(map(data => {
            return { dataItems: data.dataItems.map(item => this.cloneAndAddFieldsToDataItem(item)), totalCount: data.totalCount };
        }));
    }

    private getItemList(args: LoadItemsData): Observable<LoadItemsResponse> {
        if (this.settings.useLiveData) {
            args.serviceUrl = this.settingsService.webServiceLiveUrl;
        }

        return this.dynamicService.getItemList(args);
    }

    /**
     * Puts the new item on the top of the recent items.
     * If the recent items count is equal to the fixed items count,
     * the top-most item will be replaced with the removed one.
     *
     * @private
     * @param {*} removedItem
     * @memberof RelatedDataComponent
     */
    private returnRemovedItemToRecentItems(removedItem: any): void {
        const currentRecentItems: any[] = this._recentItemsSubject$.getValue().slice().filter(item => item.Id !== removedItem.Id);

        if (currentRecentItems.length - ADDITIONAL_NODES_COUNT >= RECENT_ITEMS_COUNT) {
            currentRecentItems[0] = removedItem;
        } else {
            currentRecentItems.splice(0, 0, removedItem);
        }

        this._recentItemsSubject$.next(currentRecentItems);
    }

    private populateHiddenItems(items: any[], shownItemsCount: number) {
        if (!items) {
            return;
        }

        for (let i = shownItemsCount; i < items.length; i++) {
            this.hiddenItems.add(items[i].Id);
        }
    }

    private filterVisibleItems(items: any[]): any[] {
        const filteredItems: any[] = [];

        items.forEach((item) => {
            if (!this.hiddenItems.has(item.Id)) {
                filteredItems.push(item);
            }

            if (!this.isViewUrlAllowed(this._relatedDataEntity, item)) {
                item["showViewUrl"] = false;
            }
        });

        return filteredItems;
    }

    private setProviderFromServer(item: any) {
        if (item.Provider) {
            item.provider = item.Provider;
            delete item.Provider;
        }
    }

    private markTranslated(item: any): void {
        if (!item.AvailableLanguages)
            return;

        const parentRoute = this.route.snapshot.parent;
        const cultureFromQueryParam = parentRoute && parentRoute.queryParams ? parentRoute.queryParams[QUERY_PARAMS.CULTURE] : stringConstants.EMPTY_STRING;
        const routeItemData = this.route.snapshot.data.itemData;
        const cultureFromRoute = (routeItemData && routeItemData.entityData && routeItemData.entityData.culture);
        const culture = this.settings.culture || cultureFromQueryParam || cultureFromRoute;

        const isTranslated = !culture || item.AvailableLanguages.some(lang => lang === culture);
        item.isTranslated = isTranslated;
        item.hasChildren = item.HasChildren;
        return item;
    }

    private getFallbackProperties(entityType: string): Array<string> {
        const entities = this.route.parent.snapshot.data.metaStore.entities;
        const relatedEntity: Entity = entities[entityType];
        return [relatedEntity.defaultFieldName];
    }

    private focusEditableElement() {
        if (this.editableElement) {
            this.renderer.selectRootElement(this.editableElement.nativeElement).focus();
        }
    }

    private addHierarchicalFilters(loaditemsData: LoadItemsData, parentId: string): void {
        if (this._relatedDataEntity.properties.hasOwnProperty(this.rootIdProperty)) {
            loaditemsData.filter.push({
                key: this.rootIdProperty,
                value: [this.rootId],
                operation: Operation.eq
            });
        }

        if (this._relatedDataEntity.properties.hasOwnProperty(this.parentIdProperty)) {
            loaditemsData.filter.push({
                key: this.parentIdProperty,
                value: [parentId],
                operation: Operation.eq
            });
        }
    }

    private evaluateBreadcrumbVisibility() {
        const hasBreadcrumbProperty = this._relatedDataEntity.properties.hasOwnProperty(Properties.BREADCRUMB);
        this.showBreadcrumb = hasBreadcrumbProperty;
    }

    private isDisplayModeInputAndCanSelect(): boolean {
        return this.settings.displayMode === DISPLAY_MODE.INPUT && this.canSelectItems;
    }

    private isViewUrlAllowed(entity: Entity, item: any) {
        if (entity.setName === ENTITY_SET.PAGES) {
            if (item.PageType !== "Group") {
                return true;
            }

            return false;
        }

        return true;
    }

    private isCreatePossible(entity: Entity) {
        return entity.setName !== ENTITY_SET.PAGES;
    }

    private isEditAllowed(entity: Entity, item: any) {
        if (entity.setName === ENTITY_SET.PAGES) {
            if (item.PageType !== "Standard") {
                return false;
            }
        }

        return true;
    }

    private parseGetRecentResult(data: LoadItemsResponse): void {
        const items = data.dataItems.map(item => this.cloneAndAddFieldsToDataItem(item));
        this.addItemsToRecentItems(items);
    }

    private getAllSites(): Observable<DataItem[]> {
        const sitesEntity = this.metadataStore.getEntity(ENTITY_SET.SITES);
        if (!sitesEntity) {
            return of([]);
        }

        return this.siteDataStore.getAllSites(<EntityData>{
            metadata: sitesEntity
        }).pipe(map((response: LoadItemsResponse) => {
            return response.dataItems;
        }));
    }
}
