import { Route, RouterModule } from "@angular/router";
import { ThemeComponent } from "./theme.component";
import { ThemeGuard } from "./theme.guard";
import { ROUTE_PATHS } from "../constants/route-paths";

export const THEME_ROUTES: Route[] = [
    {
        path: `${ROUTE_PATHS.ROOT_PREFIX}/theme`, component: ThemeComponent, canActivate: [ThemeGuard]
    }
];

export const themeRouting = RouterModule.forChild(THEME_ROUTES);
