import { createValueAccessor } from "../../../../../../../fields";
import { Component } from "@angular/core";
import { Entity, FieldRegistration } from "../../../../../api";
import { FieldInfo, FieldMappingsSettings, ListFieldMappingsBase } from "./list-field-mappings-base";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";

@Component({
    selector: "sf-field-mappings",
    templateUrl: "./list-field-mappings.component.html",
    providers: [createValueAccessor(ListFieldMappingsComponent)]
})
export class ListFieldMappingsComponent extends ListFieldMappingsBase {
    protected modifyFieldInfo(fieldInfo: FieldInfo, entity: Entity, suitableFields: { Name: string, Value: string }[]) {
        const choiceSettings = new ChoiceSettings(fieldInfo.Title, false);
        choiceSettings.choices = suitableFields;
        choiceSettings.look = "-small";
        const existingFieldMapping = this.getValue() ? this.getValue().find(fm => fm.FriendlyName === fieldInfo.Title) : null;
        const existingFieldMappingChoiceIndex = existingFieldMapping ? suitableFields.findIndex(c => c.Value === existingFieldMapping.Name) : -1;
        if (existingFieldMapping && existingFieldMappingChoiceIndex > -1) {
            choiceSettings.defaultValue = existingFieldMapping.Name;
        } else {
            let defaultFieldValue;
            if (fieldInfo.Type === "ShortText") {
                defaultFieldValue = entity.defaultFieldName;
                choiceSettings.defaultValue = entity.defaultFieldName;
            } else {
                defaultFieldValue = suitableFields[0].Value;
            }

            this.onFieldNameChange(defaultFieldValue, fieldInfo);
        }

        fieldInfo.Settings = choiceSettings;
    }

    private onFieldNameChange(entry: string, field: FieldInfo) {
        let currentValue = this.getValue();
        if (!currentValue) {
            currentValue = [];
        }
        const existingField = currentValue.find(f => f.FriendlyName === field.Title);
        if (existingField) {
            existingField.Name = entry;
        } else {
            currentValue.push({Name: entry, FriendlyName: field.Title});
        }

        this.writeValue(currentValue);
    }
}

export const LIST_FIELD_MAPPINGS_REGISTRY: FieldRegistration = {
    writeComponent: ListFieldMappingsComponent,
    readComponent: ListFieldMappingsComponent,
    settingsType: FieldMappingsSettings
};
