import { Injectable, InjectionToken, Optional, Inject } from "@angular/core";
import { BulkCommandExtenderBase } from "./bulk-command-extender-base";
import { EntityData, DataItem } from "../../../interfaces";
import { ActionButton } from "../../../../../shared/components/action-menu/action-menu-model";
import { BulkItemSelectionInfo } from "../../../components/bulk-operations/bulk-operations.component";
import { Query, WhereQuery } from "@progress/sitefinity-webservices-sdk/dist/sitefinity-webservices-sdk";

export const BULK_COMMAND_EXTENDER_TOKEN = new InjectionToken("bulk_command_extender_token");

@Injectable()
export class CompositeBulkCommandExtender {

    constructor(@Optional() @Inject(BULK_COMMAND_EXTENDER_TOKEN) private bulkCommandExtenders: BulkCommandExtenderBase[]) {

    }

    getEntityDatasForBulkOperation(entityData: EntityData, filter: string = null): EntityData[] {
        const extender = this.getExtender(entityData);
        return extender.getEntityDatasForBulkOperation(entityData, filter);
    }

    getFilterByParentQuery(entityData: EntityData, query: WhereQuery<Query>, parentId: string) {
        const extender = this.getExtender(entityData);
        return extender.getFilterByParentQuery(entityData, query, parentId);
    }

    tryHandleCommand(entityData: EntityData, action: ActionButton, dataItems: DataItem[], notificationFilter: string, bulkItemSelectionInfo: BulkItemSelectionInfo) {
        const extender = this.getExtender(entityData);
        return extender.tryHandleCommand(action, {dataItems, entityData, notificationFilter, bulkItemSelectionInfo});
    }

    private getExtender(entityData: EntityData): BulkCommandExtenderBase {
        const extender = this.bulkCommandExtenders.find(x => entityData && x.isSupportedType(entityData));
        return extender;
    }
}
