import { Component, AfterViewInit, Input } from "@angular/core";
import { DateTimePickerComponent } from "./date-time-picker.component";
import { DatePipe } from "@angular/common";
import { EventDatesService } from "../../src/app/modules/shared/components/events/services/event-dates.service";
import { DateTimeFormatsProvider } from "./date-time-formats.provider";

@Component({
    selector: "sf-date-time-read",
    templateUrl: "./date-time-picker-readOnly.component.html"
})
export class DateTimePickerReadOnlyComponent extends DateTimePickerComponent implements AfterViewInit {
    @Input() public displayAsRelativeDate: boolean;

    /**
     *
     */
    constructor(
        private datePipe: DatePipe,
        private dateTimeFormatsProvider: DateTimeFormatsProvider,
        eventService: EventDatesService
    ) {
        super(eventService, dateTimeFormatsProvider);
    }

    date: string;
    time: string;

    ngAfterViewInit() {
        this.dateTimeFormatsProvider.getDateAndTimeFormats().subscribe(x => {
            if (this.dateValue && !isNaN(this.dateValue.getTime()) && this.showDate) {
                this.date = this.datePipe.transform(this.dateValue, x.dateFormat);
            }
            if (this.timeValue && !isNaN(this.timeValue.getTime()) && this.showTime) {
                this.time = this.datePipe.transform(this.timeValue, x.timeFormat);
            }
        });
    }
}
