import { Component, OnInit } from "@angular/core";

import { createValueAccessor } from "../../../../fields/field-base";
import { FieldBase } from "../../../../fields/index";
import { stringConstants } from "./../../common-constants";
import { CUSTOM_ERROR_PREFIX, VALIDATOR_MESSAGES } from "../../../../fields/common/validators/validators.constants";
import { ListBuilderItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-additional-urls",
    templateUrl: "./additionalUrls.component.html",
    providers: [createValueAccessor(AdditionalUrlsComponent)]
})

// TODO: Fields use window provider
export class AdditionalUrlsComponent extends FieldBase implements OnInit {
    urls: ListBuilderItem[];

    newValue: string = stringConstants.EMPTY_STRING;
    private invalidUrls: Object = {};

    constructor() {
        super();
    }

    ngOnInit() {
        this.processUrls();
    }

    getValue(): Array<string> {
        if (!this.urls)
            return super.getValue();

        const result: Array<string> = [];
        this.urls.forEach(urlEntry => {
            result.push(urlEntry.value);
        });

        return result;
    }

    onItemsChange() {
        this.writeValue(this.getValue());
    }

    removeUrl(url: string): void {
        const index = this.urls.map(function(e) { return e.value; }).indexOf(url);
        if (index !== -1) {
            this.urls.splice(index, 1);
            this.writeValue(this.getValue());
        }
    }

    onFocus() {
        super.onFocus();
    }

    onBlur() {
        super.onBlur();
    }

    processErrors(errors: any): Array<string> {
        const errorMessages = [];
        const customErrors = CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.CUSTOM_ERRORS;

        this.invalidUrls = {};

        if (errors && errors[customErrors]) {
            const customErrorsList = errors[customErrors];
            const defaultError: string = CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.URL_EXIST;

            const duplicateUrls: Array<string> = [];

            // collect the invalid urls in a separate collection
            Object.keys(customErrorsList).forEach(key => {
                const customError = customErrorsList[key];
                if (typeof customError === "string") {
                    if (CUSTOM_ERROR_PREFIX + customError.toLowerCase() === defaultError) {
                        // there are three different messages for the duplicate url logic
                        // which is handled bellow
                        duplicateUrls.push(key);
                    } else {
                        const errorMessage = this.validation.buildErrorMessage(customError.toLowerCase(), errors);
                        errorMessages.push(errorMessage);
                    }
                } else {
                    errorMessages.push(this.validation.buildErrorMessage(null, customError.message));
                }

                const url = this.urls.find(u => u.value === key || `/${u.value}` === key);
                if (url && url.value) {
                    key = url.value;
                }
                this.invalidUrls[key] = true;
            });

            // handle the different kind of duplication messages
            if (errorMessages.length === 0 && this.urls && this.urls.length > 0 && duplicateUrls.length > 0) {
                let duplicateErrorCode: string = null;
                if (this.urls.length === 1)
                    duplicateErrorCode = defaultError;
                else {
                    duplicateErrorCode = CUSTOM_ERROR_PREFIX + (duplicateUrls.length === 1 ? VALIDATOR_MESSAGES.URL_EXIST_SPECIFIC : VALIDATOR_MESSAGES.URL_EXIST_MANY);
                }

                const errorMessage = this.validation.buildErrorMessage(duplicateErrorCode, null);
                errorMessages.push(errorMessage);
            }
        } else {
            return super.processErrors(errors);
        }

        this.updateValidity();
        return errorMessages;
    }

    writeValue(value: any): void {
        super.writeValue(value);
        this.processUrls();
    }

    private processUrls(): void {
        const urls: Array<ListBuilderItem> = [];
        const currentValue = super.getValue();
        if (currentValue && currentValue.length) {
            for (let i = 0; i < currentValue.length; i++) {
                urls[i] = {
                    show: false,
                    value: currentValue[i],
                    isValid: this.isUrlValid(currentValue[i])
                };
            }
        }

        this.urls = urls;
    }

    private updateValidity(): void {
        this.urls.forEach((url) => {
            if (!this.isUrlValid(url.value) && url.isValid) {
                url.isValid = false;
            }
        });
    }

    isUrlValid(url: string) {
        return !this.invalidUrls[url];
    }
}
