import { Injectable } from "@angular/core";
import { MetadataHandler } from "../shared/services/metadata/metadata.handler";
import { CompositeFieldsProvider } from "../shared/fields-builder/providers/fields-provider";
import { FieldModel } from "../../services/field.model";
import { Entity } from "../shared/services/metadata/meta-data.store";
import { Properties } from "../shared/fields.constants";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { FormData } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { SettingsBase } from "../../../../fields/field-settings-base";
import { NAVIGATION_OPTIONS_PROPERTIES } from "./components/navigation-options-composite-component/navigation-options.composite.component";
import { LocalizationStrategySettings } from "./components/localization-strategy-component/localization-strategy.settings";
import { SEARCH_SITE_PROPERTIES } from "./components/search-site-composite-component/search-site.composite.component";
import { ADVANCED_OPTIONS_PROPERTIES } from "./components/advanced-options/advanced-options.composite.component";
import { LocalizationStrategyProp } from "./components/localization-strategy-component/localization-strategy.component";
import { ENTITY_SET, KEY_VALUE_OPTIONS, PAGE_ITEM_FULL_NAME, PAGE_TEMPLATE_ITEM_FULL_NAME } from "../shared/services/metadata/meta-data-constants";
import { ChoiceSettings } from "../../../../fields/choice/choice.settings";
import { stringConstants } from "../../common-constants";
import { DataItem } from "../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../content/dynamic-modules/services/dynamic-item.service";
import { map } from "rxjs/operators";
import { StructureUrlNameSettings, UrlStructureData } from "../shared/components/urlNameStructure/structure-urlName.settings";
import { Observable } from "rxjs";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

const FIELD_GROUPS = [
    {
        fields: [
            NAVIGATION_OPTIONS_PROPERTIES.SHOW_IN_NAVIGATION,
            NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE,
            NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE
        ],
        fieldType: FieldTypes.navigationOptionsCompositeField,
        titles: {
            [NAVIGATION_OPTIONS_PROPERTIES.SHOW_IN_NAVIGATION]: "Show in navigation",
            [NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE]: "Make this a group page",
            [NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE]: "Redirect to another page"
        }
    },
    {
        fields: [
            SEARCH_SITE_PROPERTIES.INCLUDE_IN_SEARCH_INDEX,
            SEARCH_SITE_PROPERTIES.CRAWLABLE,
            SEARCH_SITE_PROPERTIES.PRIORITY
        ],
        fieldType: FieldTypes.searchSiteCompositeField,
        titles: {
            [SEARCH_SITE_PROPERTIES.INCLUDE_IN_SEARCH_INDEX]: "Allow site search to index this page",
            [SEARCH_SITE_PROPERTIES.CRAWLABLE]: "Allow external search engines to index this page and include in Sitemap",
            [SEARCH_SITE_PROPERTIES.PRIORITY]: "Priority in Sitemap"
        }
    },
    {
        fields: [
            ADVANCED_OPTIONS_PROPERTIES.REQUIRE_SSL,
            ADVANCED_OPTIONS_PROPERTIES.ENABLE_VIEW_STATE,
            ADVANCED_OPTIONS_PROPERTIES.INCLUDE_RAD_SCRIPT_MANAGER,
            ADVANCED_OPTIONS_PROPERTIES.ALLOW_PARAMETER_VALIDATION
        ],
        fieldType: FieldTypes.advancedOptionsCompositeField,
        titles: {
            [ADVANCED_OPTIONS_PROPERTIES.REQUIRE_SSL]: "Require SSL",
            [ADVANCED_OPTIONS_PROPERTIES.ENABLE_VIEW_STATE]: "Enable ViewState",
            [ADVANCED_OPTIONS_PROPERTIES.INCLUDE_RAD_SCRIPT_MANAGER]: "Include RadScriptManager",
            [ADVANCED_OPTIONS_PROPERTIES.ALLOW_PARAMETER_VALIDATION]: "Allow parameter validation"
        }
    },
    {
        fields: [LocalizationStrategyProp],
        fieldType: FieldTypes.localizationStrategy,
        titles: { LocalizationStrategyProp: "Copy from another language" }
    }
];

@Injectable()
export class PagesMetadataHandler extends MetadataHandler {
    fieldGroups: any[] = FIELD_GROUPS;

    constructor(protected fieldsProvider: CompositeFieldsProvider, private dynamicService: DynamicItemService) {
        super(fieldsProvider);
    }

    canProcess(typeFullName: string): boolean {
        // if (typeFullName === PAGE_TEMPLATE_ITEM_FULL_NAME) {
        //     this.fieldGroups = [];
        // }

        return typeFullName === PAGE_ITEM_FULL_NAME || typeFullName === PAGE_TEMPLATE_ITEM_FULL_NAME;
    }

    getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string {
        if (metadata.setName === ENTITY_SET.PAGES) {
            if (propertyName === NAVIGATION_OPTIONS_PROPERTIES.PAGE_TYPE || propertyName === NAVIGATION_OPTIONS_PROPERTIES.REDIRECT_PAGE) {
                return FieldTypes.choiceYesNo;
            } else if (propertyName === Properties.PARENT_ID) {
                return FieldTypes.dropdownSelector;
            } else if (propertyName === Properties.OUTPUT_CACHE_PROFILE) {
                return FieldTypes.choiceDropDown;
            }

            return null;
        } else if (metadata.setName === ENTITY_SET.TEMPLATES && propertyName === Properties.THUMBNAIL) {
            return FieldTypes.templateThumbnail;
        }
    }

    updateFieldSettings(fields: FieldModel[], metadata: Entity, tweaks: any[]) {
        if (metadata.setName === ENTITY_SET.PAGES) {
            fields.forEach(field => {
                field.settings.showForAllTranslationsLabel = false;

                if (field.selector === FieldTypes.choiceDropDown) {
                    const settingsCast = field.settings as ChoiceSettings;
                    const tweak = tweaks.find(x => x.name === field.key);

                    if (tweak) {
                        const tweakMetadata = tweak.metadata;

                        if (tweakMetadata && tweakMetadata[KEY_VALUE_OPTIONS]) {
                            const options: ChoiceItem[] = [];

                            tweakMetadata[KEY_VALUE_OPTIONS].forEach(option => {
                                options.push({
                                    Name: option["Key"],
                                    Value: option["Value"]
                                });
                            });

                            settingsCast.choices = options;
                            if (!field.value) {
                                field.value = options[0].Value;
                            }
                        }
                    }
                }
            });
        } else if (metadata.setName === ENTITY_SET.TEMPLATES) {
            fields.forEach(field => {
                if (field.selector === FieldTypes.templateThumbnail) {
                    field.settings.useDefaultValue = false;
                }
            });
        }

        const urlStructureField = fields.find(x => x.settings instanceof StructureUrlNameSettings);
        if (urlStructureField) {
            const urlStructureSettings = urlStructureField.settings as StructureUrlNameSettings;
            urlStructureSettings.getUrlStructureData = (x) => this.getUrlStructureData(x);
        }
    }

    updateInnerFieldsSettings(innerFields, tweaks: FormData[], readonly: boolean) {
        Object.keys(innerFields).forEach(prop => {
            if (innerFields[prop] !== null) {
                const settings = innerFields[prop].settings as SettingsBase;
                settings.showTitle = false;
                const tweak = tweaks.find(x => x.name === prop);
                if (tweak) {
                    settings.isVisible = true;
                    settings.readOnlyMode = readonly || tweak.readonly;
                } else {
                    settings.required = false;
                    settings.isVisible = false;
                }
            }
        });
    }

    updateAdditionalSettings(propertyName: string, tweaks: FormData[], compositeFieldModel: FieldModel) {
        if (propertyName === LocalizationStrategyProp) {
            const tweak = tweaks.find(x => x.name === propertyName);
            if (tweak) {
                this.updateLocalizationSettings(compositeFieldModel, tweak);
            }
        }
    }

    private updateLocalizationSettings(compositeFieldModel: FieldModel, tweak: FormData) {
        const settings: LocalizationStrategySettings = compositeFieldModel.settings as LocalizationStrategySettings;
        settings.syncAvailable = tweak.metadata.hasOwnProperty("EnableSync");
        settings.forceSync = tweak.metadata["ForceSync"];

        if (settings.forceSync) {
            settings.title = tweak.title;
            settings.tooltipModels = tweak.tooltipModels;
            settings.showTitle = true;
        }

        settings.languages = tweak.metadata.Languages.map(x => {
            return <ChoiceItem>{
                Name: x.Title,
                Value: x.Name
            };
        });

        settings.useDefaultValue = true;
        settings.markAsDirty = true;
        settings.defaultValue = {
            EnableSync: true,
            CopyFrom: settings.languages[0].Value
        };
        compositeFieldModel.value = null;
    }

    private getUrlStructureData(dataItem: DataItem): Observable<UrlStructureData> {
        return this.dynamicService.getItemsByKeys({
            entityData: dataItem,
            dataFieldNames: ["RelativeUrlPath"],
            keys: [dataItem.parentKey],
            keyProperty: dataItem.metadata.key
        }).pipe(map((data) => {
            if (data && data.dataItems) {
                let parentUrlPath = null;

                if (data.dataItems.length === 1) {
                    parentUrlPath = data.dataItems[0].data["RelativeUrlPath"];
                } else {
                    parentUrlPath = stringConstants.EMPTY_STRING;
                }

                return {
                    parentUrl: parentUrlPath,
                    extension: null,
                    editableUrl: null
                };
            }
        }));
    }
}

export const PAGES_METADATA_HANDLER = { provide: MetadataHandler, useClass: PagesMetadataHandler, multi: true };
