import { ClassProvider, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { GridExtenderBase, GRID_EXTENDER_TOKEN, TitleArgs } from "../../../shared/services/grid/grid-extender-base";
import { NON_CONTENT_TYPES } from "../../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../interfaces";

@Injectable()
export class ContentGridExtender extends GridExtenderBase {

    isSupportedType(entityData: EntityData): boolean {
        // temp hack to use this as a fallback for any content type in the system, without the specific ones
        return NON_CONTENT_TYPES.indexOf(entityData.metadata.typeFullName) < 0;
    }

    getTitle(titleArgs: TitleArgs): Observable<string> {
        const metadata = titleArgs.entityData.metadata;
        let currentEntityDisplayName = metadata.displayName;

        if (metadata.hasParent) {
            const parentDisplayName = titleArgs.parentItem?.title;
            currentEntityDisplayName = titleArgs.includeChildSet ? `${parentDisplayName ? parentDisplayName : ''} ${currentEntityDisplayName.toLowerCase()}` : `${parentDisplayName}`;
        }

        return of(currentEntityDisplayName);
    }
}

export const CONTENT_GRID_EXTENDER: ClassProvider = {
    multi: true,
    provide: GRID_EXTENDER_TOKEN,
    useClass: ContentGridExtender
};
