import { FieldBase, createValueAccessor } from "../../../../../../../fields";
import { OnInit, Input, Component, ViewChild } from "@angular/core";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { FieldSectionModel, FieldSectionSettings } from "../../../../../services/fieldSection.model";
import { FieldModel } from "../../../../../services/field.model";
import { createFieldModel } from "../../../../shared/fields.constants";
import { FieldTypes } from "../../../../shared/fields-builder/services/fields-registry";
import { COMPLEX_FIELD_CLASS_MAPPER, FIELD_TYPE_MAPPER, COMPLEX_SECTION_CLASS_MAPPER, COMPLEX_FIELD_CELL_CLASS_MAPPER } from "../field-type-mapper";
import { Dictionary, PropertyEditorWidgets } from "../../../property-editor.constants";
import { PropertyMetadata } from "../../../interfaces/widget-editor";
import { VALIDATION_REQUIRED } from "../../../../../../../fields/common/common-constants";
import { ComplexSettings } from "./complex.settings";
import { Rule } from "../../../../../../../fields/field-settings-base";
import { CompositeFieldsProvider } from "../../../../shared/fields-builder/providers/fields-provider";
import { EditableFieldsComponent, ValueChange } from "../../../../shared/fields-builder/components/editable-fields/editable-fields.component";
import { EditableTableComponent } from "../../../../shared/fields-builder/components/editable-table/editable-table.component";
import { StatusType } from "../../../../../../../fields/field-status";
import { AdditionalUrlsSettings } from "../../../../additionalUrls/additionalUrls-settings";
import { CreateFieldService } from "../../../services/create-field.service";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { PencilButtonSettings } from "../../../../../../../fields/pencil-button/pencil-button-field.component";

const plainListFieldClass = "-sf-p-zero -sf-m-zero";
@Component({
    selector: "sf-complex",
    templateUrl: "./complex.component.html",
    providers: [createValueAccessor(ComplexComponent)]
})
export class ComplexComponent extends FieldBase implements OnInit {
    @Input() look: string;
    @ViewChild(EditableFieldsComponent, { static: false }) editableFieldsComponent: EditableFieldsComponent;
    @ViewChild(EditableTableComponent, { static: false }) editableTableComponent: EditableTableComponent;

    fieldSections: FieldSectionModel[];
    defaultSection: FieldSectionModel;
    defaultValue: any;
    forceRebindTableView: boolean = true;

    get complexSettings(): ComplexSettings {
        return this.settings as ComplexSettings;
    }
    choiceSettings: any[][] = new Array<Array<ChoiceSettings>>();
    get showTableView(): boolean {
        // if there are more than 5 fields they won't be displayed as table, no matter the settings.
        return (this.complexSettings.typeChildProperties && this.complexSettings.typeChildProperties.length > 0) &&
            (this.complexSettings.isMultiple || (this.complexSettings.tableViewEnabled && this.complexSettings.typeChildProperties.length <= 5));
    }

    cssClassList: string;
    public allowModifyTable = false;
    public allowAddRow = true;
    public allowRemoveRow = true;
    private valueObject: any = {};
    private singleRelatedFieldNames: string[] = [];
    private reorderedSectionsCache: FieldSectionModel[];

    constructor(
        private fieldsProvider: CompositeFieldsProvider,
        private createFieldService: CreateFieldService,
        private dynamicItemService: DynamicItemService) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.dataBind();
    }

    public loadData(serviceUrl: string, bindNewData: boolean, onServiceCallSuccess: (serviceResponse) => void) {
        if (bindNewData) {
            this.forceRebindTableView = false;
        }

        this.registerSubscription(this.dynamicItemService.executeUnboundFunction<any>(serviceUrl).subscribe(x => {
            onServiceCallSuccess(x.value);
            if (bindNewData) {
                const complexComponentNewData = x.value.map(i => {
                    const propertyNames = Object.keys(i);
                    const result = {};
                    propertyNames.forEach(v => {
                        result[v] = i[v]
                    });

                    return result;
                });

                this.writeValue(complexComponentNewData);
                this.defaultValue = this.getValue();
                this.forceRebindTableView = true;
                this.dataBind();
            }
        }));
    }

    public dataBind() {
        const value = this.getValue();
        if (value && typeof value === "string") {
            this.valueObject = JSON.parse(value);
        } else {
            if (Array.isArray(value)) {
                this.valueObject = this.parseArrayToObjectArray(value) || {};
            } else {
                this.valueObject = value || {};
            }
        }

        if (this.complexSettings.look) {
            this.look = this.complexSettings.look;
        }
        const sections: FieldSectionModel[] = [];
        if (this.complexSettings.typeChildProperties && this.complexSettings.typeChildProperties.length === 0) {
            const section = this.createPlainListSection();
            sections.push(section);
        } else if (this.complexSettings.isMultiple) {
            const itemDefaultValue = (this.settings as ComplexSettings).itemDefaultValue;
            let itemDefaultValueObject = {};
            if (itemDefaultValue && !this.value) {
                itemDefaultValueObject = JSON.parse(itemDefaultValue);
            }
            const dictionaryEntries = this.complexSettings.extraRecords;
            for (let i = 1; i <= this.complexSettings.dependsOnLength; i++) {
                dictionaryEntries.push({
                    Name: this.complexSettings.lengthDependsOnDisplayName + i,
                    Title: this.complexSettings.lengthDependsOnDisplayTitle + i
                });
            }
            dictionaryEntries.forEach(dictionaryEntry => {
                const name = this.settings.key + dictionaryEntry.Name;
                const cssClass = COMPLEX_SECTION_CLASS_MAPPER.get(name);
                const section = new FieldSectionModel({
                    isMain: false,
                    isExpanded: false,
                    insertHorizontalRule: false,
                    title: dictionaryEntry.Title,
                    name: name,
                    cssClass: cssClass
                });
                section.fields = this.getFields(this.complexSettings.typeChildProperties, this.valueObject[dictionaryEntry.Name] || itemDefaultValueObject, section.settings.name);

                sections.push(section);
            });

            if (dictionaryEntries.length === 0) {
                this.allowModifyTable = this.complexSettings.allowCreate;
                this.allowAddRow = this.complexSettings.allowAdd;
                this.allowRemoveRow = this.complexSettings.allowRemove;
                const name = this.settings.key;
                const cssClass = COMPLEX_FIELD_CLASS_MAPPER.get(name);
                this.defaultSection = new FieldSectionModel({
                    isMain: false,
                    isExpanded: true,
                    insertHorizontalRule: false,
                    name: name,
                    cssClass: cssClass
                });
                this.defaultSection.fields = this.getFields(this.complexSettings.typeChildProperties, {}, name);
                this.defaultValue = this.value;
            }
        } else {
            const complexSettings = (this.settings as ComplexSettings);
            const sectionOptions: FieldSectionSettings = {
                isMain: this.showTableView,
                isExpanded: this.showTableView || complexSettings.hideExpander,
                insertHorizontalRule: false,
                title: this.showTableView ? complexSettings.tableViewColumnTitle : this.settings.title,
                name: this.settings.key,
                hideExpander: complexSettings.hideExpander
            };
            const section = new FieldSectionModel(sectionOptions);
            section.fields = this.getFields(this.complexSettings.typeChildProperties, this.valueObject, section.settings.name);
            sections.push(section);
        }

        this.fieldSections = sections;
    }

    validate(): boolean {
        let isFormValid = true;

        const editableForms = <EditableFieldsComponent>(this.editableFieldsComponent || this.editableTableComponent);
        if (editableForms) {
            editableForms.enableRequiredErrorCheck();
            isFormValid = editableForms.valid(false);
        }

        if (isFormValid) {
            this.emitStatus({ type: StatusType.Done });
        } else {
            this.emitStatus({ type: StatusType.Error });
        }

        return isFormValid;
    }

    onChange(args: ValueChange) {
        if (!this.valueObject) {
            this.valueObject = {};
        }
        if (this.singleRelatedFieldNames.some(s => s === args.key) && args.value && Array.isArray(args.value)) {
            args.value = args.value[0]; //in case or related data field which displays single item we want to save only the first object, not array which always have single object.
        }
        const sectionName = args.sectionName.replace(this.settings.key, "");

        if (args.isSectionRemoved) {
            if (this.valueObject[sectionName]) {
                delete this.valueObject[sectionName];
                if (!this.valueObject) {
                    this.emitStatus({ type: StatusType.ErrorCleared });
                }
            }
        } else if (this.complexSettings.typeChildProperties.length === 0) { // is plain list displayed in additional-urls
            this.value = args.value;
            return;
        } else {
            const propName = args.key.replace(args.sectionName, "");
            if (this.complexSettings.isMultiple) {
                if (!this.valueObject[sectionName]) {
                    this.valueObject[sectionName] = {};
                }
                this.valueObject[sectionName][propName] = args.value;
            } else {
                this.valueObject[propName] = args.value;
            }
        }

        this.value = this.reformatObject(this.valueObject);
    }

    onReorder(orderedNodes: FieldSectionModel[]) {
        // mark the field as dirty
        this.writeValue(this.reformatObject(this.valueObject));

        // cache the reordered sections
        this.reorderedSectionsCache = orderedNodes;
    }

    postProcessValue(value: Array<any>): any {
        if (this.reorderedSectionsCache) {
            const valueArray = Object.values(value);
            const ordered = valueArray.sort((a, b) => {
                const indexA = this.reorderedSectionsCache.findIndex(x => x.settings.name === `${this.defaultSection.settings.name}${valueArray.indexOf(a).toString()}`);
                const indexB = this.reorderedSectionsCache.findIndex(x => x.settings.name === `${this.defaultSection.settings.name}${valueArray.indexOf(b).toString()}`);
                return indexA - indexB;
            });

            return this.reformatObject(ordered);
        }

        return value;
    }

    private reformatObject(valueObject: any) {
        let newValue = null;
            if (this.complexSettings.type === "enumerable") {
                newValue = this.parseObjectArrayToArray(valueObject);
            } else {
                // pass by value, otherwise it is not marked as dirty.
                newValue = Object.assign({}, valueObject);
            }

            return newValue;
    }

    private createPlainListSection(): FieldSectionModel {
        const sectionOptions: FieldSectionSettings = {
            isMain: true,
            isExpanded: true,
            insertHorizontalRule: false,
            title: this.settings.title,
            name: this.settings.key,
            hideExpander: true
        };
        const section = new FieldSectionModel(sectionOptions);
        section.fields = [];
        const entity: any = {
            [VALIDATION_REQUIRED]: this.complexSettings.required
        };
        const fieldModel = createFieldModel(
            this.fieldsProvider,
            PropertyEditorWidgets.FIELD_TYPE_KEY + "Complex",
            FieldTypes.additionalUrls,
            this.settings.key,
            this.value,
            entity,
            null,
            this.settings.title,
            false,
            plainListFieldClass
        );
        fieldModel.settings.showTitle = false;
        fieldModel.settings.title = this.settings.title;
        (fieldModel.settings as AdditionalUrlsSettings).addButtonTitle = "Add";
        section.fields.push(fieldModel);

        return section;
    }

    private getFields(propertiesMeta: PropertyMetadata[], propertiesValues: Dictionary, sectionName: string): FieldModel[] {
        const fields: FieldModel[] = [];
        propertiesMeta
            .forEach(prop => {
                const propName = sectionName + prop.Name;
                const fieldType = FIELD_TYPE_MAPPER.get(prop.Type) || FieldTypes[prop.Type] || FieldTypes.shortText;
                const fieldCssClass = COMPLEX_FIELD_CLASS_MAPPER.get(prop.Name);
                const fieldCellCssClass = COMPLEX_FIELD_CELL_CLASS_MAPPER.get(propName) || COMPLEX_FIELD_CELL_CLASS_MAPPER.get(prop.Name);
                const [value, shouldMarkDirty] = this.getValueOrDefault(prop, propertiesValues);
                const field = this.createFieldService.createField(
                    fieldType,
                    propName,
                    value,
                    prop,
                    prop.Title,
                    PropertyEditorWidgets.FIELD_TYPE_KEY + "Complex",
                    null,
                    this.settings.culture,
                    fieldCssClass
                );

                field.settings.showTitle = field.settings.showTitle && !this.showTableView;

                if ((fieldType === FieldTypes.relatedData || fieldType === FieldTypes.media) && !prop.Properties["AllowMultiple"]) {
                    this.singleRelatedFieldNames.push(propName);
                }

                if (field.settings instanceof ComplexSettings)
                    field.settings.hideExpander = true;

                if (field.settings instanceof PencilButtonSettings)
                    field.settings.initialValue = this.complexSettings.itemDefaultValue;

                const rule = prop.Properties["Meta_ConditionalVisibility_Condition"];
                if (rule) {
                    field.settings.conditionalRule = JSON.parse(rule) as Rule;
                    field.settings.conditionalRule.conditions.forEach(condition => {
                        condition.fieldName = sectionName + condition.fieldName;
                    });
                }

                if (shouldMarkDirty) {
                    field.settings.markAsDirty = true;
                }

                if (fieldCellCssClass) {
                    field.settings.tableViewColumnCssClass = fieldCellCssClass; 
                }

                fields.push(field);
            });

        return fields;
    }

    private getValueOrDefault(propertyMetadata: PropertyMetadata, propertiesValues: Dictionary): [any, boolean] {
        if (typeof propertiesValues[propertyMetadata.Name] === "undefined" && typeof propertyMetadata.DefaultValue !== "undefined")
            return [propertyMetadata.DefaultValue, true];

        return [propertiesValues[propertyMetadata.Name], false];
    }

    private parseObjectArrayToArray(fieldValue: any): any {
        let valueArray = [];
        if (fieldValue) {
            if (!Array.isArray(fieldValue)) {
                const elementNames = Object.getOwnPropertyNames(fieldValue);
                elementNames.forEach((name) => {
                    valueArray.push(fieldValue[name]);
                });
            } else {
                valueArray = fieldValue;
            }
        }

        return valueArray;
    }

    private parseArrayToObjectArray(fieldValue: any): any {
        const objectVal = {};
        if (fieldValue) {
            if (Array.isArray(fieldValue)) {
                fieldValue.forEach((element, index) => {
                    objectVal[index.toString()] = element;
                });
            }
        }

        return objectVal;
    }
}
