import { Injectable } from "@angular/core";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { Observable } from "rxjs";
import { map } from "rxjs/operators";
import { Country, CountriesResult } from ".";

export const SF_COUNTRIES_ENDPOINT = "Default.SfCountries()";

@Injectable()
export class CountryProvider {
    private cachedCountries: Observable<Country[]>;

    constructor(private service: DynamicItemService) {
    }

    getCountries(): Observable<Country[]> {
        if (this.cachedCountries) {
            return this.cachedCountries;
        }

        this.cachedCountries = this.service.executeUnboundFunction<CountriesResult>(`${SF_COUNTRIES_ENDPOINT}`).pipe(
            map(result => {
                return result.value.map(c =>
                    <Country>
                    {
                        name: c.name,
                        isoCode: c.isoCode,
                        hasStates: c.hasStates,
                        states: c.states
                    });
            }));

        return this.cachedCountries;
    }
}
