import { Pipe, PipeTransform } from "@angular/core";
import { stringConstants, regexConstants } from "../../../common-constants";

@Pipe({
    name: "sfTrimText"
})
export class TrimTextPipe implements PipeTransform {

    transform(value: string, ...args: any[]): string {
        if (!value) {
            return stringConstants.EMPTY_STRING;
        }

        let result = value;
        let trimText: string = args[0] ? args[0].trim() : stringConstants.EMPTY_STRING;

        if (trimText && trimText !== stringConstants.EMPTY_STRING) {
            // escape reserved regex chars
            trimText = trimText.replace(regexConstants.ESCAPE_RESERVED_CHARACTERS_PATTERN, `\\${regexConstants.DOLLAR}${stringConstants.AMPERSAND}`);
            // remove text at the start of the string
            result = result.replace(new RegExp(regexConstants.CARET + trimText, regexConstants.IGNORE_CASE), stringConstants.EMPTY_STRING);
            // remove text at the end of the string
            result = result.replace(new RegExp(trimText + regexConstants.DOLLAR, regexConstants.IGNORE_CASE), stringConstants.EMPTY_STRING);
        }

        return result;
    }
}
