import { Component, Input, Output, EventEmitter } from "@angular/core";
import { DataItem, EntityData } from "../content/dynamic-modules/interfaces";
import { COMMAND_NAMES } from "../content/dynamic-modules/components/commands";
import { ItemSelectionInfo } from "../shared/components/list/list.component";
import { cloneInstance } from "../../utils";
import { CompositeDataExtender } from "../shared/services/data-extensions/data.extender";
import { StateWrapper } from "../content/dynamic-modules/services/dynamic-item-store-state";
import { BackgroundTaskType } from "../content/dynamic-modules/services/background-task.types";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-thumbnail-list",
    templateUrl: "./thumbnail-list.component.html"
})
export class ThumbnailListComponent extends SfRxBase {
    @Input()set itemsState(state: StateWrapper) {
        this.isLoadingItems = state.isLoadingItems;
        // when state is loading there is no need to refresh the items. When loading is finished they will be updated
        if (!state.isLoadingItems || state.dataItems.length === 0) {
            const parsed = this.mapFiles(state.dataItems);
            this.files = parsed.filter(x => x.metadata.isMedia).map(x => this.markTranslated(x));
            this.libraries = parsed.filter(x => !x.metadata.isMedia);
            this._dataItems = parsed;
        }
    }

    @Input() set mediaEntityData(entityData: EntityData) {
        //// Need to reset the items collection when switching from videos to images and vice versa.
        if (this._mediaEntityData && this._mediaEntityData.metadata.setName !== entityData.metadata.setName ) {
            this.libraries = [];
            this.files = [];
        }
        this._mediaEntityData = entityData;
    }
    get mediaEntityData(): EntityData {
        return this._mediaEntityData;
    }

    @Input() showAsTimeline: boolean;
    @Output() selectFile = new EventEmitter();
    @Output() onCommand = new EventEmitter();

    isLoadingItems = true;
    files: DataItem[] = [];
    libraries: DataItem[] = [];
    itemSelectionInfo: ItemSelectionInfo = {
        selectedItems: new Map<string, DataItem>(),
        deselectedItems: new Map<string, DataItem>(),
        excludedItems: new Array<string>(),
        nodesPositions: new Map<string, number>()
    };

    get value() {
        const v = Object.keys(this.selectedFiles).map(x => { return {data: {Id: x}}; });
        return v;
    }

    private selectedFiles = {};
    private _dataItems: DataItem[] = [];
    private _mediaEntityData: EntityData;

    constructor(private compositeDataExtender: CompositeDataExtender) {
        super();
    }

    isSelected(file: DataItem): boolean {
        return this.selectedFiles[file.data.Id];
    }

    onSelectFile(f: DataItem) {
        const dataItem = this._dataItems.find(x => x.data.Id === f.data.Id);
        if (this.selectedFiles[f.data.Id]) {
            this.itemSelectionInfo.deselectedItems.set(f.data.Id, dataItem);
            this.itemSelectionInfo.selectedItems.delete(f.data.Id);
            delete this.selectedFiles[f.data.Id];
        } else {
            this.selectedFiles[f.data.Id] = f;
            this.itemSelectionInfo.selectedItems.set(f.data.Id, dataItem);
            this.itemSelectionInfo.deselectedItems.delete(f.data.Id);
        }

        this.selectFile.emit(this.itemSelectionInfo);
    }

    onClickFile(f: DataItem) {
        if (Object.keys(this.selectedFiles).length > 0 && f.data && !f.data.disableCheckbox) {
            this.onSelectFile(f);
            return;
        }

        const file = this._dataItems.find(x => x.data.Id === f.data.Id);
        if (file) {
            this.onCommand.emit({
                name: COMMAND_NAMES.selectionChanged,
                data: file
            });
        }
    }

    onClickFolder(f: DataItem) {
        this.onClickFile(f);
    }

    onSelectFolder(f: DataItem) {
        this.onSelectFile(f);
    }

    selectAllNodes(excludedNodeIds: string[]) {
        this.itemSelectionInfo.selectedItems.clear();
        this.itemSelectionInfo.deselectedItems.clear();

        this._dataItems.forEach(d => {
            if (!d.data.disableCheckbox && excludedNodeIds.indexOf(d.data.Id) === -1) {
                this.itemSelectionInfo.selectedItems.set(d.data.Id, d);
                this.selectedFiles[d.data.Id] = d;
            }
        });

        this.itemSelectionInfo.excludedItems = excludedNodeIds;

        this.selectFile.emit(this.itemSelectionInfo);
    }

    clearAllSelectedNodes () {
        this.selectedFiles = {};
        this.itemSelectionInfo.deselectedItems.clear();
        this.itemSelectionInfo.selectedItems.clear();

        this.selectFile.emit(this.itemSelectionInfo);
    }

    private mapFiles(files: DataItem[]) {
        return this.compositeDataExtender.enhanceDataItems(this.mediaEntityData, files, {
            inactive: true,
            failedValidation: (errorMessage) => {return { errorMessage }; }
        }, { whiteListedTasks: [BackgroundTaskType.RegenerateThumbnails] });
    }

    private markTranslated(item: DataItem): DataItem {
        const culture = item.culture;
        const data = cloneInstance(item.data);
        data.isTranslated = culture ? item.data.AvailableLanguages.some(lang => lang === culture) : true;
        return DataItem.fromEntityData(data, item);
    }
}
