import { Injectable } from "@angular/core";
import { LifeCycleStatus } from "../../../../../cypress/e2e/enums/lifecycle-statuses";
import { StatusLabel } from "../../../../../fields/resolvers/base-status.resolver";
import { StatusResolver } from "../../../../../fields/resolvers/status.resolver";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";

const ACTIVE_STATUS = "Active";
const INACTIVE_STATUS = "Inactive";

@Injectable()
export class SearchIndexStatusResolver extends StatusResolver {

    getLabel(searchIndex: any): StatusLabel {
        if (searchIndex) {
            return {
                Label: searchIndex.IsActive ? ACTIVE_STATUS : INACTIVE_STATUS,
                StatusName: searchIndex.IsActive ? LifeCycleStatus.Published : LifeCycleStatus.Unpublished,
                HideIcon: false
            };
        }

        return null;
    }

    canProcess(setName: string): boolean {
        return setName === ENTITY_SET.SEARCH_INDEXES;
    }
}
