import { Injectable } from "@angular/core";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { CommonTweaksHandler, TweakInfo } from "../shared/services/common-tweaks-handler.service";
import { CustomTweaksHandler } from "../shared/services/custom-tweaks-handler.service";
import { FORMS_DESCRIPTION_FULL_NAME } from "../shared/services/metadata/meta-data-constants";
import { FORM_REDIRECT_PAGE_PROPERTIES } from "./components/form-redirect-page/form-redirect-page.composite.component";

export const FORM_NOTIFICATIONS_PROPERTIES = {
    SEND_CONFIRMATION_EMAIL: "SendConfirmationEmail",
    SEND_EMAIL_NOTIFICATIONS: "SendEmailNotifications",
    SUBSCRIBED_EMAILS: "SubscribedEmails",
    CONFIRMATION_EMAIL_TEMPLATE: "ConfirmationEmailTemplate",
    EMAIL_NOTIFICATION_TEMPLATE: "EmailNotificationTemplate"
};

@Injectable()
export class FormsTweaksHandler extends CommonTweaksHandler {
    canProcess(typeFullName: string): boolean {
        return typeFullName === FORMS_DESCRIPTION_FULL_NAME;
    }

    getTweakInfoMap(): TweakInfo[] {
        return [
            {
                sectionName: "MainSection",
                fields: [FORM_REDIRECT_PAGE_PROPERTIES.SUBMIT_ACTION, FORM_REDIRECT_PAGE_PROPERTIES.REDIRECT_PAGE],
                fieldType: FieldTypes.formRedirectPageCompositeField
            }
        ];
    }
}

export const FORMS_TWEAKS_HANDLER = { provide: CustomTweaksHandler, useClass: FormsTweaksHandler, multi: true };
