import { Injectable, ClassProvider } from "@angular/core";
import { DeleteCommandExtenderBase } from "./operations/commands/delete-command-extender-base";
import { EntityData } from "../interfaces";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { DELETE_COMMAND_EXTENDER_TOKEN } from "./operations/commands/composite-delete-command-extender";
import { DynamicItemStore } from "./dynamic-item.store";

@Injectable()
export class ContentDeleteCommandExtender extends DeleteCommandExtenderBase {
    constructor(dynamicItemStore: DynamicItemStore) {
        super(dynamicItemStore);
    }

    isSupportedType(entityData: EntityData): boolean {
        const currentSet = entityData.metadata.setName;
        return currentSet !== ENTITY_SET.ALBUMS &&
            currentSet !== ENTITY_SET.IMAGES &&
            currentSet !== ENTITY_SET.FOLDERS;
    }
}

export const CONTENT_DELETE_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: DELETE_COMMAND_EXTENDER_TOKEN,
    useClass: ContentDeleteCommandExtender
};
