import { getPastTense } from "./../../../../../utils";
import { Component, Input, OnInit } from "@angular/core";
import { ItemListComponent } from "./item-list.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { EntityData } from "../../interfaces";
import { ModalWindowService, DialogData } from "../../../../shared/services/modal-window.service";
import { ActivatedRoute } from "@angular/router";

@Component({
    selector: "sf-bulk-operations-notification",
    templateUrl: "./bulk-operations-notification.component.html"
})
export class BulkOperationsNotificationComponent implements OnInit {
    @Input() failedItemsIds: string[];
    @Input() succeededItemsIds: string[];
    @Input() entityData: EntityData;
    @Input() operationName: string;

    operationNamePastTense: string;
    operationFailed: boolean;
    operationSucceeded: boolean;
    operationPartiallySucceeded: boolean;
    failedItemsComponentTitle: string;

    constructor(private modalService: ModalWindowService, private route: ActivatedRoute) {
    }

    ngOnInit() {
        this.operationNamePastTense = getPastTense(this.operationName);
        this.operationPartiallySucceeded = this.succeededItemsIds && this.succeededItemsIds.length > 0 && this.failedItemsIds && this.failedItemsIds.length > 0;
        this.operationFailed = !this.operationPartiallySucceeded && this.failedItemsIds && this.failedItemsIds.length > 0;
        this.operationSucceeded = !this.operationPartiallySucceeded && this.succeededItemsIds && this.succeededItemsIds.length > 0;
        this.failedItemsComponentTitle = `Items failed to ${this.operationName.toLowerCase()}`;
    }

    onFailedItemsClick() {
        const componentData: ComponentData = {
            type: ItemListComponent,
            properties: {
                dataItemsIds: this.failedItemsIds,
                entityData: this.entityData,
                componentTitle: this.failedItemsComponentTitle,
                listAdditionalLook: "sf-mt-2xl"
            }
        };

        const dialogData = new DialogData(componentData, null, [], null, "-bottom");
        this.modalService.setMapping(dialogData);
        this.modalService.open(this.route);
    }
}

export interface BulkOperationsNotificationData {
    failedItemsCount?: number;
    requestedOperation?: string;
    totalOperationsToBePerformed?: number;
    successfullOpeartionsPeformed?: number;
}
