import { Inject, Injectable, Optional } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { Observable } from "rxjs";
import { DataItem } from "../../../../content/dynamic-modules/interfaces";
import { BulkOperationResult } from "../../../../content/dynamic-modules/services/operations/commands/bulk-command";
import { ActionButton } from "../../../../shared/components/action-menu/action-menu-model";
import { ZoneEditorBaseExtender, ZONE_EDITOR_EXTENDER_TOKEN } from "./zone-editor-base-extender";

@Injectable()
export class ZoneEditorCompositeExtender {
    constructor(@Optional() @Inject(ZONE_EDITOR_EXTENDER_TOKEN) private extenders: ZoneEditorBaseExtender[]) {}
    public handleAction(entitySetName: string, dataItem: DataItem, action: ActionButton, route: ActivatedRoute): Observable<BulkOperationResult> {
        const extender = this.getExtender(entitySetName);
        return extender.handleAction(action, dataItem, route);
    }

    public getEmptyRootCssClasses(entitySetName: string): string[] {
        const extender = this.getExtender(entitySetName);
        return extender.getEmptyRootCssClasses();
    }

    public useNarrowLook(entitySetName: string): boolean {
        const extender = this.getExtender(entitySetName);
        return extender.useNarrowLook();
    }

    public getInitialWidgetSelectorTabName(entitySetName: string): string {
        const extender = this.getExtender(entitySetName);
        return extender.getInitialWidgetSelectorTabName();
    }

    private getExtender(entitySetName: string) {
        for (const extender of this.extenders) {
            if (extender.canHandle(entitySetName)) {
                return extender;
            }
        }

        return new ZoneEditorBaseExtender();
    }
}
