import { map, first, skip, take, delay } from "rxjs/operators";
import { Component, OnInit, ViewChild, Input } from "@angular/core";
import { Router, ActivatedRoute } from "@angular/router";
import { ChoiceDropdownComponent } from "./../../../../../../../fields/choice/choice-dropdown.component";
import { FormFieldWrapperComponent } from "./../../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldTypes } from "./../../../../shared/fields-builder/services/fields-registry";
import { FieldModel } from "./../../../../../services/field.model";
import { SORT_KEY } from "../../dynamic-item.constants";
import { CHOICE_DROPDOWN_REGISTRY } from "../../../../../../../fields/choice/index";
import { QUERY_PARAMS, FILTER_PARAMS, RESOLVE_NAMES } from "../../../constants";
import { Settings } from "../../../../shared/services/settings.service";
import { EntityData } from "../../interfaces";
import { Observable } from "rxjs";
import { SidebarConfig } from "../../../../shared/components/sidebar/sidebar.common";
import { CustomFilterSidebarComponent } from "./custom-filter-sidebar.component";
import { SidebarComponentData } from "../../../../shared/components/sidebar/sidebar-component.repo";
import { DisabledFilterLoaders } from "./list-item-filter-interfaces";
import { SortersResult, SortersStore } from "./sorter/SortingStore";
import { CompositeGridExtender } from "../../../../shared/services/grid/composite-grid-extender";
import { AppStore } from "../../../../../services/store/app-store";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../../services/store/actions/actions.sidebar";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { SIDEBAR_SELECTORS } from "../../../../../services/store/selectors/selectors.sidebar";
import { getRouteDataRecursively } from "../helpers";

export const SORT_DROPDOWN_NAME = "sortDropdown";
export const DROPDOWN_LOOK = "small";
export const LANGUAGE_DROPDOWN_NAME = "languageDropdown";
export const LANGUAGES_DOPDOWN_TITLE = "Languages";
export const CUSTOM_SORTING_OPTION_NAME = "Custom sorting";
const QUERY_PARAMS_MERGE_HANDLING_STRATEGY = "merge";

@Component({
    templateUrl: "./list-item-filter-sidebar.component.html",
    selector: "sf-list-item-filter-sidebar"
})
export class ListItemFilterSidebarComponent extends SfRxBase implements OnInit {
    @ViewChild("sortDropdown", { static: false })
    set sortDropdownWrapper(sortDropdown: FormFieldWrapperComponent) {
        this.setSortDropdownWrapper(sortDropdown);
    }

    @ViewChild("languagesDropdown", { static: false })
    set languagesDropdownWrapper(languagesDropdown: FormFieldWrapperComponent) {
        this.setLanguagesDropdownWrapper(languagesDropdown);
    }

    @Input() entityData$: Observable<EntityData>;
    @Input() filterValue: Observable<string>;
    @Input() displayName: string;
    @Input() allowOrderingByTitle: boolean = true;
    @Input() disabledFilterLoaders: DisabledFilterLoaders;
    @Input() showFilters: boolean;
    @Input() showSorters: boolean = true;
    @Input() getSorters: Observable<SortersResult>;
    @Input() onFilterSelect: (name: string) => void;
    @Input() loadFiltersCount: Observable<void>;

    entityData: EntityData;
    dropdownFieldModels = new Map<string, FieldModel>();
    isCustomFilterEnabled: Boolean = true;

    private languagesDropdownWrapperRef: FormFieldWrapperComponent;
    private customFilterSidebar: SidebarConfig;

    constructor(
        private route: ActivatedRoute,
        private router: Router,
        private settings: Settings,
        private sortersStore: SortersStore,
        private gridExtender: CompositeGridExtender,
        private store: AppStore) {
        super();
    }

    ngOnInit(): void {
        this.entityData$.pipe(first()).subscribe(entityData => {
            this.entityData = entityData;
            this.initializeLanguagesDropdown();
            this.initializeSortDropdown();

            if (this.entityData && this.entityData.metadata && this.entityData.metadata.hasCustomFilterEnabledProperty) {
                this.isCustomFilterEnabled = this.entityData.metadata.isCustomFilterEnabled;
            }

            if (this.isCustomFilterEnabled) {
                this.initSidebar();
            }

            const filterType: string = this.route.snapshot.queryParams[FILTER_PARAMS.FILTER];
            if (filterType && filterType.includes(",")) {
                this.store.pipe(SIDEBAR_SELECTORS.activeConfig, take(1), delay(0)).subscribe(
                    activeConfig => {
                        if (!activeConfig || activeConfig.name !== this.customFilterSidebar.name) {
                            this.openCustomFilter();
                        }
                    });
            }
        });

        const subscription = this.entityData$.pipe(skip(1)).subscribe(entityData => {
            const languageChange = this.entityData.culture !== entityData.culture;
            if (this.entityData.provider !== entityData.provider || languageChange) {
                this.entityData = entityData;
                if (this.languagesDropdownWrapperRef && languageChange) {
                    const currentCulture = this.languagesDropdownWrapperRef.getValue();
                    if (currentCulture !== this.entityData.culture) {
                        this.languagesDropdownWrapperRef.writeValue(this.entityData.culture);
                    }
                }
            }
        });

        this.registerSubscription(subscription);
    }

    onFilterSelectHandler(filterName: string): void {
        if (this.onFilterSelect) {
            this.onFilterSelect(filterName);
        }
    }

    initSidebar(): void {
        const customFilterSidebarComponentData: SidebarComponentData = {
            type: CustomFilterSidebarComponent,
            title: `All filters`,
            hasBackNavigation: true,
            properties: {
                entityData$: this.entityData$,
                onFilterSelect: this.onFilterSelect
            },
            updatePropertiesOnChange: true
        };

        this.customFilterSidebar = {
            title: `All filters`,
            data: customFilterSidebarComponentData,
            name: "custom-filter",
            icon: "filter"
        };
    }

    openCustomFilter(): void {
        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.change(this.customFilterSidebar));
    }

    private setSortDropdownWrapper(sortDropdown: FormFieldWrapperComponent) {
        if (!sortDropdown) {
            return;
        }

        sortDropdown.registerOnChange((sortKey: string) => {
            if (this.dropdownFieldModels.get(SORT_DROPDOWN_NAME).value !== sortKey) {
                this.dropdownFieldModels.get(SORT_DROPDOWN_NAME).value = sortKey;
                const currentQueryParams = Object.assign({}, this.route.snapshot.queryParams);

                if (!sortKey) {
                    delete currentQueryParams[FILTER_PARAMS.SORT];
                    delete currentQueryParams[FILTER_PARAMS.SEARCH];
                    delete currentQueryParams[FILTER_PARAMS.FILTER];
                } else {
                    currentQueryParams[QUERY_PARAMS.SORT] = sortKey;
                }

                this.router.navigate([], { queryParams: currentQueryParams });
            }
        });
    }

    private setLanguagesDropdownWrapper(languagesDropdown: FormFieldWrapperComponent) {
        if (!languagesDropdown) {
            return;
        }

        languagesDropdown.registerOnChange((culture: string) => {
            this.router.navigate([], { queryParams: { [QUERY_PARAMS.CULTURE]: culture }, queryParamsHandling: QUERY_PARAMS_MERGE_HANDLING_STRATEGY });
        });

        this.languagesDropdownWrapperRef = languagesDropdown;
    }

    private getSelectedOptionFromQueryString(selectOptions: Array<ChoiceItem>, parameterKey: string): Observable<string> {
        return this.route.queryParams.pipe(
            map(params => params[parameterKey]));
    }

    private initializeLanguagesDropdown() {
        const hideLanguagesDropdown = this.gridExtender.hideSidebarLanguagesDropdown(this.entityData);
        if (hideLanguagesDropdown) {
            return;
        }

        // TODO: revise fields
        const sitedataStore = getRouteDataRecursively(this.route.parent.snapshot, RESOLVE_NAMES.siteDataStore);
        const cultures: any[] = sitedataStore.ContentCultures;

        // The dropdown should not be visible if there is only one language or the item is not lifecycle
        if (cultures.length < 2 || !this.entityData.metadata.isMultilingual) {
            return;
        }

        const dropdownOptions = cultures.map(cul => {
            return {
                Name: cul.DisplayName,
                Value: cul.Name
            };
        });
        const dropdownSettings = ChoiceDropdownComponent.createFieldSettings(dropdownOptions, null, LANGUAGE_DROPDOWN_NAME, DROPDOWN_LOOK);
        const dropdownModel = new FieldModel({
            key: LANGUAGE_DROPDOWN_NAME,
            settings: dropdownSettings,
            selector: FieldTypes.choiceDropDown,
            registration: CHOICE_DROPDOWN_REGISTRY
        });
        const currentCulture = this.settings.getSiteCulture(sitedataStore.Id) || sitedataStore.DefaultContentCulture;

        dropdownModel.settings.title = LANGUAGES_DOPDOWN_TITLE;
        dropdownModel.value = currentCulture;
        this.dropdownFieldModels.set(LANGUAGE_DROPDOWN_NAME, dropdownModel);
    }

    private initializeSortDropdown() {
        let getSorters: Observable<SortersResult> = null;
        if (this.getSorters != null) {
            getSorters = this.getSorters;
        } else {
            getSorters = this.sortersStore.getSorters(this.entityData);
        }

        const sortersSubscription = getSorters.subscribe(sorterResult => {
            const sortDropdownOptions = sorterResult.sorters
                .map(sorter => {
                    const newSorter: ChoiceItem = {
                        Name: sorter.Name,
                        Value: sorter.Value
                    };
                    return newSorter;
                });

            const defaultOptionValue = sortDropdownOptions.length > 0 ? sortDropdownOptions[0].Value : null;

            // TODO: revise fields
            const settings = ChoiceDropdownComponent.createFieldSettings(sortDropdownOptions, defaultOptionValue, SORT_DROPDOWN_NAME, DROPDOWN_LOOK, CUSTOM_SORTING_OPTION_NAME);
            const sortDropdownModel = new FieldModel({
                key: SORT_DROPDOWN_NAME,
                settings: settings,
                selector: FieldTypes.choiceDropDown,
                registration: CHOICE_DROPDOWN_REGISTRY
            });

            const displayName = this.displayName ? this.displayName : this.entityData.metadata.displayName;
            sortDropdownModel.settings.title = this.gridExtender.getSortDropdownTitle(this.entityData, displayName);

            this.dropdownFieldModels.set(SORT_DROPDOWN_NAME, sortDropdownModel);

            const subscription = this.getSelectedOptionFromQueryString(settings.choices, SORT_KEY)
                .subscribe(currentSortValue => {
                    const currentFieldModel = this.dropdownFieldModels.get(SORT_DROPDOWN_NAME);
                    if (currentFieldModel.value !== currentSortValue) {
                        // Create new FieldModel with the new value in order to trigger ngOnChanges on child component
                        const newSortDropdownModel = new FieldModel({
                            key: currentFieldModel.key,
                            settings: currentFieldModel.settings,
                            selector: currentFieldModel.selector,
                            registration: currentFieldModel.registration,
                            value: currentSortValue || defaultOptionValue
                        });

                        this.dropdownFieldModels.set(SORT_DROPDOWN_NAME, newSortDropdownModel);
                    }
                });

            this.registerSubscription(subscription);
        });

        this.registerSubscription(sortersSubscription);
    }
}
