import { Injectable } from "@angular/core";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "../../libraries/services/media.helpers";

export const DEFAULT_ORDINAL_EXPRESSION = "Ordinal asc";
export const LAST_MODIFIED_DESC_SORT_ORDER = "LastModified desc";
export const LAST_MODIFIED_ASC_SORT_ORDER = "LastModified asc";
export const DATE_CREATED_DESC_SORT_ORDER = "DateCreated desc";

@Injectable()
export class SortService {
    public getDefaultSort(entityData: EntityData): string {
        if (MediaHelpers.isLibrary(entityData.metadata.setName)) {
            return DATE_CREATED_DESC_SORT_ORDER;
        }

        if (entityData.metadata.isSelfReferencing) {
            return LAST_MODIFIED_DESC_SORT_ORDER;
        }

        return entityData.metadata.isOrderable && !entityData.metadata.isMedia ? DEFAULT_ORDINAL_EXPRESSION : LAST_MODIFIED_DESC_SORT_ORDER;
    }
}
