import { Component, Input, OnInit, Output, EventEmitter, ChangeDetectorRef } from "@angular/core";
import { ContentCultureData } from "../../services/metadata/site-data.store";
import { Operation, OPERATION_NAMES } from "../action-menu/operation.model";
import { stringConstants } from "../../../../common-constants";
import { ActionMenuOptions, ActionButton } from "../action-menu/action-menu-model";
import { OUTSIDE_MENU_MAX_ORDINAL } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { ActivatedRoute } from "@angular/router";
import { DataItem } from "../../../content/dynamic-modules/interfaces";

import { BehaviorSubject ,  Observable ,  ReplaySubject ,  Subject, Subscription } from "rxjs";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const LANGUAGE_BADGE_ADD_LOOK: string = "size-xl sf-txt-small sf-txt-upper-case add-variation";
export const LANGUAGE_BADGE_EDIT_LOOK: string = "size-xl sf-txt-small sf-txt-upper-case edit-variation";

const EDIT_CULTURE_CATEGORY_NAME: string = "TRANSLATIONS";
const COMPARE_TRANSLATIONS_CATEGORY_NAME: string = "COMPARE TRANSLATIONS";
const ADD_CULTURE_CATEGORY_NAME: string = "ADD TRANSLATION";
const SYNCED_LOCALIZATION_STRATEGY = "Synced";
export const COMPARE_TRANSLATIONS_LABEL: string = "Compare translations";

/**
 * Component used to display item translations in edit page
 */
@Component({
    selector: "sf-languages-dropdown",
    templateUrl: "./languages-dropdown.component.html"
})
export class LanguagesDropdownComponent extends SfRxBase implements OnInit {
    /**
     * The data item of the current edited content
     */
    @Input() item: BehaviorSubject<DataItem>;
    @Input() customOperations: Observable<Operation[]>;
    @Output() onChange: EventEmitter<ActionButton> = new EventEmitter<ActionButton>();

    public actionMenuOptions: ActionMenuOptions;
    public selectedOperationName: string;
    public displaySyncedIcon: boolean = false;

    private customOperationsSubscription: Subscription;
    private selectedCulture: ContentCultureData;
    private operations: Subject<Array<Operation>> = new ReplaySubject<Array<Operation>>(1);

    /**
     * Initializes a new instance of the {@link LanguagesDropdownComponent} class
     */
    constructor(protected route: ActivatedRoute, protected detector: ChangeDetectorRef) {
        super();
    }

    get cultureOperations(): Observable<Array<Operation>> {
        return this.operations.asObservable();
    }

    public ngOnInit(): void {
        if (this.item) {
            const subscription = this.item.subscribe(newItem => this.onItemChanged(newItem));
            this.registerSubscription(subscription);
        }
    }

    /**
     * Handles the click event on a translation.
     * @param button The action menu button that was clicked.
     */
    public onActionButtonClicked(button: ActionButton): void {
        if (button.context.additionalText !== this.selectedCulture.Name) {
            this.onChange.emit(button);
        }
    }

    private onItemChanged(newItem: DataItem) {
        // TODO: pass site data from outside as input properties
        const siteData = this.route.parent.snapshot.data.siteDataStore;
        if (siteData.ContentCultures.length > 1) {

            const allCultures: Array<ContentCultureData> = siteData.ContentCultures;

            let availableCultures: Array<string> = [];
            if (newItem.data) {
                availableCultures = newItem.data.AvailableLanguages;
                this.displaySyncedIcon = newItem.data.LocalizationStrategy === SYNCED_LOCALIZATION_STRATEGY;
            }

            this.actionMenuOptions = new ActionMenuOptions(Number.NEGATIVE_INFINITY, OUTSIDE_MENU_MAX_ORDINAL, true);
            this.selectedCulture = siteData.ContentCultures.find(e => e.Name === newItem.culture);
            this.selectedOperationName = `${OPERATION_NAMES.changeCulture}_${this.selectedCulture.Name}`;
            const langOperations: Array<Operation> =  this.generateCultureOperations(this.selectedCulture.Name, allCultures, availableCultures, newItem);

            this.detector.detectChanges();
            if (this.customOperations) {
                if (this.customOperationsSubscription)
                    this.customOperationsSubscription.unsubscribe();

                this.customOperationsSubscription = this.customOperations.subscribe(custom => {
                    this.operations.next(custom.concat(langOperations));
                });

                this.registerSubscription(this.customOperationsSubscription);
            } else {
                this.operations.next(langOperations);
            }
        }
    }

    private generateCultureOperations(activeCulture: string, allCultures: Array<ContentCultureData>, availabeCultures: Array<string>, itemData: DataItem): Array<Operation> {
        let operations: Array<Operation> = [];
        const availableCulturesOperations: Array<Operation> = [];
        const notAvailableCulturesOperations: Array<Operation> = [];

        allCultures.forEach((culture: ContentCultureData, index: number) => {
            const isAvailable: boolean = availabeCultures.some(e => e === culture.Name);
            const operations = {
                Title: culture.DisplayName,
                Category: (isAvailable ?
                    { Name: EDIT_CULTURE_CATEGORY_NAME, Title: EDIT_CULTURE_CATEGORY_NAME } :
                    { Name: ADD_CULTURE_CATEGORY_NAME, Title: ADD_CULTURE_CATEGORY_NAME }),
                Name: `${OPERATION_NAMES.changeCulture}_${culture.Name}`,
                Ordinal: index,
                Description: stringConstants.EMPTY_STRING,
                Link: null,
                Parameters: null,
                context: {
                    additionalText: culture.Name,
                    look: (isAvailable ? LANGUAGE_BADGE_EDIT_LOOK : LANGUAGE_BADGE_ADD_LOOK)
                },
                RequiresConfirmation: false
            };

            isAvailable ? availableCulturesOperations.push(operations) : notAvailableCulturesOperations.push(operations);
        });

        operations = operations.concat(availableCulturesOperations);

        // Should be visible on creating a translation but not the creating of the item
        if (!itemData.metadata.hasContent && itemData.data && itemData.data.AvailableLanguages.length > 0) {
            operations.push({
                Title: COMPARE_TRANSLATIONS_LABEL,
                Category: { Name: COMPARE_TRANSLATIONS_CATEGORY_NAME },
                Name: OPERATION_NAMES.compareTranslations,
                Ordinal: 100,
                Description: stringConstants.EMPTY_STRING,
                Link: null,
                Parameters: null,
                context: {
                    additionalText: null,
                    look: LANGUAGE_BADGE_EDIT_LOOK
                },
                RequiresConfirmation: false
            });
        }

        operations = operations.concat(notAvailableCulturesOperations);

        return operations;
    }
}
