import { publishReplay, map } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Operation, OPERATION_NAMES, OperationCategory } from "../../../shared/components/action-menu/operation.model";
import { ActionButton, ButtonState, ActionSection, PRIMARY_BUTTON_ORDINAL } from "../../../shared/components/action-menu/action-menu-model";

import { BehaviorSubject, ConnectableObservable, Observable } from "rxjs";

export const OUTSIDE_MENU_MAX_ORDINAL = 4;
export const DELETE_BUTTON_LOOK = "sf-txt-failure";
export const ACTION_BUTTON_LOOK = "action";
export const ELLIPSIS_BUTTON_LOOK = "sf-max-width-form-xsmall";
export const PREVIEW_BUTTON_LOOK = "link";
export const EDIT_SECTION_TITLE = "Edit";
export const EDIT_ICON = "pencil";
export const QUICK_EDIT = "QuickEdit";
export const EDIT_LABEL = "editlabel";
export const PERSONALIZE_WIDGETS = "personalizeWidgets";
export const SVG_ICON_NAME = "Section";
export const DELETE_ICON = "times";
export const DELETE_BTN = "delete";
export const PERSONALIZATION_ICON = "user";
export const PERSONALIZATION_ICON_LOOK = "color-inherit";

export const UNTITLED_SECTION = new ActionSection("Untitled section", true);

interface Notification {
    specificState?: SpecificButtonState;

    stateForAll: ButtonState;
}

export interface SpecificButtonState {
    name: string;

    state: ButtonState;
}

export interface ButtonsState {
    primary: SpecificButtonState;

    stateForOthers: ButtonState;
}

@Injectable()
export class ActionButtonsResolver {

    private state$ = new BehaviorSubject<Notification>({ stateForAll: ButtonState.Default });

    getActionButtons(operations: Array<Operation>, categories?: Array<OperationCategory>, arePrimaryButtons: boolean = true): Array<ActionButton | ActionSection> {
        const categoryMap = new Map<string, Array<Operation>>();

        if (categories) {
            categories.forEach((category) => {
                if (!categoryMap.has(category.Name)) {
                    categoryMap.set(category.Name, []);
                }
            });
        }

        operations.forEach((operation) => {
            if (!categoryMap.has(operation.Category.Name)) {
                categoryMap.set(operation.Category.Name, []);
            }

            const categoryArr = categoryMap.get(operation.Category.Name);
            categoryArr.push(operation);
        });

        let buttons: Array<ActionButton | ActionSection> = [];

        categoryMap.forEach((value, key) => {
            const buttonsForCategory = value.sort((a, b) => {
                if (a.Ordinal > b.Ordinal) {
                    return 1;
                }

                if (a.Ordinal < b.Ordinal) {
                    return -1;
                }

                return 0;
            }).map(operation => {
                return this.getActionButton(operation, arePrimaryButtons);
            });

            if (buttonsForCategory.length > 0) {
                const currentCategory = value[0].Category;

                if (buttons.length === 0) {
                    if (currentCategory.Title) {
                        buttons.push(new ActionSection(currentCategory.Title));
                    }
                } else {
                    // if we show the title and is not the first section we want to have a separator
                    if (currentCategory.Title && !currentCategory.HideSeparator)
                        buttons.push(UNTITLED_SECTION);

                    buttons.push(currentCategory.Title ? new ActionSection(currentCategory.Title) : UNTITLED_SECTION);
                }

                buttons = buttons.concat(buttonsForCategory);
            }
        });

        return buttons;
    }

    updateButtonState(state: ButtonsState): void {
        if (state.stateForOthers === null) {
            if (state.primary !== null && state.primary.state !== null) {
                if (this.hasFlag(state.primary.state, ButtonState.Checked) || this.hasFlag(state.primary.state, ButtonState.Loading)) {
                    state.stateForOthers = ButtonState.Disabled;
                }
            } else {
                state.stateForOthers = ButtonState.Default;
            }
        }

        this.state$.next({
            specificState: state.primary,
            stateForAll: state.stateForOthers
        });
    }

    private getActionButton(operation: Operation, arePrimaryButtons: boolean): ActionButton {
        const actionButton = new ActionButton(operation.Title || operation.Name, operation.Name);
        actionButton.description = operation.Description;
        actionButton.detailedTitle = operation.DetailedTitle;
        actionButton.link = operation.Link;
        actionButton.ordinal = operation.Ordinal;
        actionButton.parameters = operation.Parameters;
        actionButton.contextParameters = operation.ContextParameters;
        actionButton.context = operation.context;
        actionButton.requiresConfirmation = operation.RequiresConfirmation;
        actionButton.token = operation.token;
        actionButton.sourceOperation = operation;
        actionButton.subText = operation.SubText;
        if (!operation.ExecuteOnServer && operation.Warning)
            actionButton.warningMessage = operation.Warning;

        const connectedObservable = this.state$.pipe(
            map((not) => {
                // if there is a specific state for the current action button, return it
                if (not.specificState && not.specificState.name === actionButton.name) {
                    return not.specificState.state;
                }

                // otherwise use the general state
                return not.stateForAll;
            }),
            publishReplay(1)) as ConnectableObservable<ButtonState>;

        connectedObservable.connect();

        actionButton.checked = this.filterMap(connectedObservable, ButtonState.Checked);
        actionButton.disabled = this.filterMap(connectedObservable, ButtonState.Disabled);
        actionButton.loading = this.filterMap(connectedObservable, ButtonState.Loading);

        if (operation.SubOperation) {
            actionButton.subAction = this.getActionButton(operation.SubOperation, false);
            actionButton.subAction.isSubAction = true;
        }

        const behavesLikeDeleteBtn = operation.Name === OPERATION_NAMES.unlock && operation.Title === OPERATION_NAMES.delete;
        //set look only if buttons are primary or delete button is inside the dropdown
        if (arePrimaryButtons || (operation.Name === DELETE_BTN && operation.Ordinal > OUTSIDE_MENU_MAX_ORDINAL) || behavesLikeDeleteBtn) {
            this.setButtonLook(actionButton, operation, behavesLikeDeleteBtn);
        } else {
            this.setButtonIcon(actionButton, operation);
        }
        return actionButton;
    }

    private setButtonIcon(actionButton: ActionButton, operation: Operation): ActionButton {
        actionButton.context = {};

        if (operation.Name === DELETE_BTN) {
            actionButton.context.icon = DELETE_ICON;
        } else if (operation.Name === QUICK_EDIT) {
            actionButton.context.icon = SVG_ICON_NAME;
        } else if (operation.Name === PERSONALIZE_WIDGETS) {
            actionButton.context.icon = PERSONALIZATION_ICON;
            actionButton.context.iconLook = PERSONALIZATION_ICON_LOOK;
        } else {
            actionButton.context.icon = EDIT_ICON;
        }

        return actionButton;
    }

    private setButtonLook(actionButton: ActionButton, operation: Operation, behavesLikeDeleteBtn: boolean = false): ActionButton {

        // handle specifics here for now
        if (operation.Name === OPERATION_NAMES.delete || operation.Name === DELETE_BTN || behavesLikeDeleteBtn) {
            actionButton.look = DELETE_BUTTON_LOOK;
        } else if (operation.Name === OPERATION_NAMES.preview) {
            actionButton.look = PREVIEW_BUTTON_LOOK;
        } else if (operation.Name !== OPERATION_NAMES.unlock && actionButton.ordinal === PRIMARY_BUTTON_ORDINAL) {
            actionButton.look = ACTION_BUTTON_LOOK;

            if (operation.Name === OPERATION_NAMES.create) {
                actionButton.look += " " + ELLIPSIS_BUTTON_LOOK;
            }
        }

        return actionButton;
    }

    private filterMap(source: Observable<ButtonState>, flag: ButtonState) {
        return source.pipe(
            map((state) => this.hasFlag(state, flag)));
    }

    private hasFlag(state: ButtonState, flag: ButtonState): boolean {
        return (state & flag) === flag;
    }
}
