import { ClassProvider, Injectable } from "@angular/core";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { Properties } from "../../shared/fields.constants";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../shared/services/edit/edit-extender";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";

@Injectable()
export class PageTempaltesEditExtender extends EditExtender {
    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.TEMPLATES;
    }

    includedProperties(entityData: EntityData): string[] {
        return [
            Properties.THUMBNAIL_URL
        ];
    }

    showHeader(entityData: EntityData): boolean {
        return true;
    }
}

export const PAGE_TEMPLATES_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: PageTempaltesEditExtender
};
