import { FieldBase, createValueAccessor } from "../../../../../../../fields";
import { Component, OnInit, TemplateRef, ViewChild } from "@angular/core";
import { FieldRegistration, SettingsBase } from "../../../../../api";
import { ChoiceItem, ChoiceSettingsBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-list-settings",
    templateUrl: "./list-settings.component.html",
    providers: [createValueAccessor(ListSettingsComponent)]
})
export class ListSettingsComponent extends FieldBase<SettingsBase, ContentListSettings> implements OnInit {
    public itemsPerPageValue;
    public limitCountValue;
    @ViewChild("choice0Template", { static: true }) private choice0Template: TemplateRef<any>;
    @ViewChild("choice1Template", {static: true}) private choice1Template: TemplateRef<any>;

    public choices: Array<ChoiceItem> = [
        { Value: "Paging", Name: "Use paging -" },
        { Value: "Limit", Name: "Show limited number -" }
    ];
    simpleChoiceSettings: ChoiceSettingsBase;

    ngOnInit() {
        super.ngOnInit();

        this.choices[0].ExpandedTemplate = this.choice0Template;
        this.choices[1].ExpandedTemplate = this.choice1Template;

        this.simpleChoiceSettings = {
            key: this.settings.key,
            choiceCssClass: "-sf-flex",
            labelCssClass: "-width-auto",
            textCssClass: "sf-row -align-items-center -sf-txt-nowrap",
            showExpandedTemplateAlways: true
        };

        if (!this.value) {
            this.initializeEmptyValue();
        }
        this.itemsPerPageValue = this.value.ItemsPerPage;
        this.limitCountValue = this.value.LimitItemsCount;
        this.setSelected();
    }

    protected initializeEmptyValue() {
        this.writeValue(new ContentListSettings());
    }

    onInputChange(event, fieldName: string) {
        if (!this.value) {
            this.initializeEmptyValue();
        }

        const newVal = this.getValue();
        newVal[fieldName] = event.value;
        this.writeValue(newVal);
    }

    onRadioSelectionChange(index: number) {
        const entry = this.choices[index].Value;
        if (!this.value) {
            this.initializeEmptyValue();
        }
        const newVal = this.getValue();
        newVal.DisplayMode = entry;
        this.writeValue(newVal);
        this.choices[index].Selected = this.isChecked(entry);
    }

    protected setSelected() {
        for (let i = 0; i < this.choices.length; i++) {
            this.choices[i].Selected = this.isChecked(this.choices[i].Value);
        }
    }

    isChecked(displayMode: string) {
        return (this.value && this.value.DisplayMode === displayMode) ||
            (!this.value && displayMode === "Paging");
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }
}

export const LIST_SETTINGS_REGISTRY: FieldRegistration = {
    writeComponent: ListSettingsComponent,
    readComponent: ListSettingsComponent,
    settingsType: SettingsBase
};

export class ContentListSettings {
    ItemsPerPage: number = 20;
    LimitItemsCount: number = 20;
    DisplayMode: string = "Paging";
}
