import { Validators } from "@angular/forms";
import { SettingsBase } from "./../field-settings-base";
import { VALIDATORS as CustomValidators, VALIDATOR_NAMES } from "../common/validators";
import { VALIDATION_DECIMAL_PLACES, VALIDATION_MAX_VALUE, VALIDATION_MIN_VALUE } from "../common/common-constants";

export const INT_NUMBER_REGEX: string = "^-?\\d+$";
export const DECIMAL_NUMBER_REGEX = (decimalPlaces: string) => `^-?(\\d+(?:[\\.\\,]\\d{1,${decimalPlaces}})?)$`;

export class NumberSettings extends SettingsBase {
    public decimalPlaces: number;
    public unitLook: string = "size-s";

    public getValidators(metadata: any) {
        const baseValidators = super.getValidators(metadata);
        let hasMinMax: boolean = false;
        const range: Range = {};
        let regexPattern: string;

        if (metadata.hasOwnProperty(VALIDATION_MAX_VALUE)) {
            range.max = metadata[VALIDATION_MAX_VALUE];
            hasMinMax = true;
        }

        if (metadata.hasOwnProperty(VALIDATION_MIN_VALUE)) {
            range.min = metadata[VALIDATION_MIN_VALUE];
            hasMinMax = true;
        }

        if (hasMinMax) {
            baseValidators.push(CustomValidators[VALIDATOR_NAMES.VALUE_RANGE](range));
        }

        if (metadata.hasOwnProperty(VALIDATION_DECIMAL_PLACES) && (metadata[VALIDATION_DECIMAL_PLACES] > 0)) {
            regexPattern = DECIMAL_NUMBER_REGEX(metadata[VALIDATION_DECIMAL_PLACES]);
        } else {
            regexPattern = INT_NUMBER_REGEX;
        }

        baseValidators.push(Validators.pattern(regexPattern));
        baseValidators.push(CustomValidators[VALIDATOR_NAMES.DIGITS_LIMIT](16));
        baseValidators.push(CustomValidators[VALIDATOR_NAMES.MAX_INTEGER]());

        return baseValidators;
    }
}

export interface Range {
    min?: number;
    max?: number;
}
