import { Component, Input, OnInit } from "@angular/core";
import { UrlService } from "../../../../services/url.service";
import { PropertyEditorWidgets } from "../../../widget-editor/property-editor.constants";

/*
* Add additional SVG icon:
* 1. copy svg icon file from UX directory into "svg-sprite-assets/icons"
* 2. run "npm run svg:generate"
* 3. map the developer name with the icon file name in "SVG_ICON_NAME_MAPS"
* 4. if svg file name has "__template" check if developer name must be added into "STATIC_TEMPLATES_TYPES" located in widget-preview.component
*/
@Component({
    selector: "sf-svg-icon-handler",
    templateUrl: "./svg-icon-handler.component.html"
})
export class SvgIconHandlerComponent implements OnInit {
    @Input() name: string;
    @Input() look: string;
    @Input() title: string;
    @Input() iconType: SvgIconType;

    src: string;
    svgClassList: string;
    svgId: string;

    constructor(private urlService: UrlService) { }

    ngOnInit() {
        switch (this.iconType) {
            case SvgIconType.Template:
                this.name = `${this.name}__${this.iconType}`;
                this.svgClassList = SVG_TEMPLATE_CLASS;
                break;
            default:
                this.svgClassList = SVG_ICON_CLASS;
                break;
        }

        this.svgId = SVG_ICON_NAME_MAPS[this.name] || DEFAULT_SVG_ICON_NAME;

        if (isNoBackgroundSvg(this.svgId)) {
            this.svgClassList += ` ${NO_BACKGROUND_CLASS}`;
        }

        const filePath = `assets/images/selectors-sprite.svg#${this.svgId}`;
        this.src = this.urlService.getResourceUrl(`/${filePath}`);
    }
}

export enum SvgIconType {
    Icon = "icon",
    Template = "template"
}

const SVG_ICON_CLASS = "-sf-block sf-icon__svg";
const SVG_TEMPLATE_CLASS = "-sf-block sf-icon__svg-template";
const DEFAULT_SVG_ICON_NAME = "custom-widget-icon";
const SVG_ICON_NAME_MAPS = {
    "SitefinityLoginForm__template": "login-form__template",
    "Accordion__template": "accordion-nav__template",
    "Horizontal__template": "horizontal-nav__template",
    "Tabs__template": "tabs-nav__template",
    "Vertical__template": "vertical-nav__template",
    "SitefinityChangePassword__template": "change-pass__template",
    "SitefinityForgottenPassword__template": "forgot-pass__template",
    "SitefinityResetPassword__template": "reset-pass__template",
    "SitefinityAccountActivation__template": "account-activation__template",
    "SitefinityRegistration__template": "register__template",
    "SitefinityLoginButton__template": "login-button__template",
    "SitefinitySearchBox__template": "search-box__template",
    "SitefinityFacets__template": "search-facets__template",
    "SitefinityClassification__template": "classification__template",
    "SitefinityBreadcrumb__template": "breadcrumb__template",
    "SitefinitySection": "layout-icon",
    "SitefinityFormSection": "layout-icon",
    "SitefinityContentBlock": "content-icon",
    "SitefinityFormContentBlock": "content-icon",
    "SitefinityLoginForm": "login",
    "SitefinityLoginButton": "login",
    "SitefinityImage": "image",
    "SitefinityButton": "cta",
    "SitefinityRegistration": "registration",
    "SitefinityAccountActivation": "registration",
    "SitefinityForgottenPassword": "password",
    "SitefinityResetPassword": "password",
    "SitefinityChangePassword": "password",
    "SitefinityNavigation": "navigation",
    "SitefinityContentList": "content-list",
    "SitefinityForm": "form",
    "SitefinityTextField": "textbox",
    "SitefinitySubmitButton": "button",
    "SitefinityParagraph": "paragraph",
    "SitefinityMultipleChoice": "multiple-choice",
    "SitefinityCheckboxes": "checkboxes",
    "SitefinityDropdown": "dropdown",
    "SitefinityFileField": "file-upload",
    "SitefinitySearchBox": "search",
    "SitefinitySearchResults": "search",
    "SitefinityFacets": "search",
    "SitefinityClassification": "classification",
    "SitefinityBreadcrumb": "breadcrumb",
    "SitefinityRecommendations": "recommendations",
    "SitefinityDynamicList": "dropdown",
    "SitefinityNativeChat": "chat",
    [PropertyEditorWidgets.SECTION_COLUMN]: "column"
};
const NO_BACKGROUND_CLASS = "-no-background"
const NO_BACKGROUND_SVG = ["layout-icon", "custom-widget-icon", "form", "content-list", "column"];

export function isNoBackgroundSvg(value: string): boolean {
    return NO_BACKGROUND_SVG.includes(value)
}
