import { Settings } from "./../modules/shared/services/settings.service";
import { WINDOW_TOKEN } from "./../window.provider";
import { PathLocationStrategy } from "@angular/common";
import { Injectable, Inject, InjectionToken } from "@angular/core";
import { stringConstants } from "../common-constants";

export const URL_SERVICE = new InjectionToken("UrlService");

/**
 * Service for building absolute URLs from provided application relative paths.
 */
@Injectable()
export class UrlService {
    private resourcePath: string;

    constructor(
        @Inject(WINDOW_TOKEN) private window: Window,
        private locationStrategy: PathLocationStrategy,
        settings: Settings) {
        this.resourcePath = settings.resourcePath;
    }

    /**
     * Gets the full server relative URL of a resource file (e.g. scripts or styles).
     * Takes into consideration any server-related path prefixes.
     * If no prefixes are specified, nothing will be appended.
     *
     *
     * ### Example
     *
     * Given there is a resource with an application relative path of value "/assets/folder/resource.js",
     * and a reference to this resource is needed somewhere in the code,
     * the hosting server path must be taken into consideration.
     *
     * An example for this is when Iris is hosted in integrated mode.
     * If Sitefinity is hosted in sub-application, then "/SubApp/adminapp"
     * will be the server path prefix that is needed for the server to successfully resolve ther resource URL.
     *
     * ```
     * const assetUrl = "/assets/folder/resource.js";
     * const assetUrlResolved = urlService.getResourceUrl(assetUrl);
     *
     * // assetUrlResolved will have a value "/SubApp/adminapp/assets/folder/resource.js"
     *
     * ```
     *
     *
     * @param {string} urlPath
     * @returns {string}
     *
     * @memberOf UrlService
     */
    getResourceUrl(urlPath: string): string {
        if (!this.resourcePath)
            return urlPath;

        return `${this.resourcePath}${urlPath}`;
    }

    /**
     * Gets the full server absolute URL of a resource file (e.g. scripts or styles).
     * Takes into consideration any server-related path prefixes.
     * If no prefixes are specified, nothing will be appended.
     *
     *
     * ### Example
     *
     * Given there is a resource with an application relative path of value "/assets/folder/resource.js",
     * and a reference to this resource is needed somewhere in the code,
     * the hosting server path must be taken into consideration.
     *
     * An example for this is when Iris is hosted in integrated mode.
     * If Sitefinity is hosted in sub-application, then "/SubApp/adminapp"
     * will be the server path prefix that is needed for the server to successfully resolve ther resource URL.
     *
     * ```
     * const assetUrl = "/assets/folder/resource.js";
     * const assetUrlResolved = urlService.getAbsoluteResourceUrl(assetUrl);
     *
     * // assetUrlResolved will have a value "http://localhost:3000/my-app/adminapp/assets/folder/resource.js"
     *
     * ```
     *
     *
     * @param {string} urlPath
     * @returns {string}
     *
     * @memberOf UrlService
     */
    getAbsoluteResourceUrl(urlPath: string): string {
        if (!this.resourcePath)
            return urlPath;

        return `${this.window.location.origin}${this.resourcePath}${urlPath}`;
    }

    /**
     * Gets the full server relative URL of a backend navigation link.
     * Takes into consideration any server-related path prefixes.
     * If no prefixes are specified, nothing will be appended.
     *
     *
     * ### Example
     *
     * Given there is a server relative path of value "/Administration/Settings",
     * and a full relative path,
     * the hosting server path must be taken into consideration.
     *
     * An example for this is when Sitefinity is hosted in sub-application.
     * Then e.g. "/SubApp" will be the server path prefix that is needed
     * by the server to successfully resolve the URL.
     *
     * ```
     * const url = "/Administration/Settings";
     * const urlResolved = urlService.getServerRelativeUrl(url);
     *
     * // urlResolved will have a value "/SubApp/Sitefinity/Administration/Settings"
     *
     * ```
     *
     *
     * @param {string} urlPath
     * @returns {string}
     *
     * @memberOf UrlService
     */
    getServerRelativeUrl(urlPath: string): string {
        const APP_PATH_SUFFIX = "/adminapp";

        let resourcePath = this.resourcePath || stringConstants.EMPTY_STRING;
        if (resourcePath.endsWith(APP_PATH_SUFFIX)) {
            resourcePath = resourcePath.replace(APP_PATH_SUFFIX, stringConstants.EMPTY_STRING);
        }

        return `${resourcePath}/Sitefinity${urlPath}`;
    }

    /**
     * Gets the full application absolute URL of a navigation link.
     * Takes into consideration any app-related path prefixes.
     * If no prefixes are specified, nothing will appended.
     *
     *
     * ### Example
     *
     * Given there is a need to navigate to the full URL of some area in the application
     * e.g. the news items grid view - "http://localhost:3000/content/newsitems",
     * the base href of the application must be taken into consideration
     * (default value is "/" but it could be any string, e.g. "/my-app").
     *
     *
     * ```
     * urlService.getAbsoluteUrl("/content/newsitems"); // "http://localhost:3000/my-app/content/newsitems"
     *
     * ```
     *
     *
     * @param {string} urlPath
     * @returns {string}
     *
     * @memberOf UrlService
     */
    getAbsoluteUrl(urlPath: string): string {
        const baseUrl = this.locationStrategy.getBaseHref();
        const trimmedUrlPath = this.trimForwardSlash(urlPath);

        let result = this.window.location.origin;

        if (baseUrl !== stringConstants.FORWARD_SLASH) {
            result = result + baseUrl;
        }

        if (trimmedUrlPath.length === 0) {
            return result;
        }

        if (!result.endsWith(stringConstants.FORWARD_SLASH)) {
            result = result + stringConstants.FORWARD_SLASH;
        }

        result = result + trimmedUrlPath;

        return result;
    }

    private trimForwardSlash(path: string): string {
        let result = path;

        while (result.startsWith(stringConstants.FORWARD_SLASH)) {
            result = result.substring(stringConstants.FORWARD_SLASH.length);
        }

        while (result.endsWith(stringConstants.FORWARD_SLASH)) {
            result = result.substring(0, result.length - stringConstants.FORWARD_SLASH.length);
        }

        return result;
    }
}
