import { Injectable, ClassProvider, Inject } from "@angular/core";
import { DataItem, EntityData } from "../interfaces";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { BulkCommandExtenderBase } from "./operations/commands/bulk-command-extender-base";
import { BULK_COMMAND_EXTENDER_TOKEN } from "./operations/commands/composite-bulk-command-extender";
import { ActionButton } from "../../../shared/components/action-menu/action-menu-model";
import { BulkItemSelectionInfo } from "../components/bulk-operations/bulk-operations.component";
import { OPERATION_NAMES } from "../../../shared/components/action-menu/operation.model";
import { MoveCommand } from "./operations/commands/move-command";
import { MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { ModalWindowService } from "../../../shared/services/modal-window.service";
import { DynamicItemStore } from "./dynamic-item.store";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../shared/services/notification/notification.service";
import { Command } from "../../../shared/commands/command";
import { SortService } from "../../../shared/services/sort.service";
import { ChildrenCountStore } from "./children-count.store";

@Injectable()
export class ContentBulkCommandExtender extends BulkCommandExtenderBase {
    constructor(private metadataStore: MetadataStore,
                private dynamicItemStore: DynamicItemStore,
                private modalWindowService: ModalWindowService,
                @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
                private sortService: SortService,
                private childrenCountStore: ChildrenCountStore) {
        super();
    }

    isSupportedType(entityData: EntityData): boolean {
        const currentSet = entityData.metadata.setName;
        return currentSet !== ENTITY_SET.ALBUMS &&
            currentSet !== ENTITY_SET.IMAGES &&
            currentSet !== ENTITY_SET.FOLDERS;
    }

    tryHandleCommand(action: ActionButton, data: {dataItems: DataItem[], entityData: EntityData, notificationFilter: string, bulkItemSelectionInfo: BulkItemSelectionInfo}): Command {
        if (action.name === OPERATION_NAMES.move) {
            const command = new MoveCommand(
                this.modalWindowService,
                this.dynamicItemStore.service,
                this.notificationService,
                this.metadataStore.getValue(),
                this.sortService,
                this.childrenCountStore);

            return command;
        }

        return super.tryHandleCommand(action, data);
    }
}

export const CONTENT_BULK_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: BULK_COMMAND_EXTENDER_TOKEN,
    useClass: ContentBulkCommandExtender
};
