import { ComponentRef } from "@angular/core";
import { AddWidgetComponent } from "../add-widget/add-widget.component";
import { InlineToolbarComponent } from "../inline-toolbar/inline-toolbar.component";
import {
    CLASS_ZONE_WIDGET, CLASS_EDITOR_COLUMN, CLASS_ORPHANED,
    CLASS_HIDDEN, CLASS_CONTENT_WIDGET, CLASS_EMPTY, ATTR_PREFIX, ATTR_PREFIX_IS, ATTR_CONTAINER, EMPTY_WIDGET_ACTION, CLASS_PERSONALIZED_WIDGET_LOOK, CLASS_NO_CONTENT
} from "../../../services/document-enhancer.constants";
import { ErrorWidgetComponent } from "../error-widget/error-widget.component";
import { EmptyWidgetComponent } from "../empty-widget/empty-widget.component";
import { Subscription } from "rxjs";
import { FakeWidgetComponent } from "../fake-widget/fake-widget.component";
import { WidgetState } from "../../../services/zone-editor.contract";

export class ComponentModel {

    // metadata start
    id: string;
    name: string;
    title: string;
    error: string;
    warning: string;
    iscontentwidget: boolean;
    isemptyentity: boolean;
    isempty: boolean;
    isorphaned: boolean;
    emptyicontext: string = "Create content";
    emptyicon: string = "pencil";
    emptyiconaction: string = EMPTY_WIDGET_ACTION.EDIT;
    isemptyvisualhidden: boolean;
    hasquickeditoperation: boolean;
    // metadata end

    // optimizations start
    addWidgetsInitialized: boolean;
    operationsInitialized: boolean;
    // optimizations end

    // state start
    addAllowed: boolean = true;
    deleteAllowed: boolean = true;
    editAllowed: boolean = true;
    moveAllowed: boolean = true;
    labelTooltip: string;

    // personalization start
    widgetSegmentId: string;
    isPersonalized: boolean;
    // personalization end

    // state end

    // tree start
    isExpanded: boolean = true;
    get children(): ComponentModel[] {
        if (this.isContainer)
            return this.container.children;

        let allChildren = [];
        this.childContainers.forEach(x => {
            allChildren = allChildren.concat(x.children);
        });

        return allChildren;
    }

    get isRoot(): boolean {
        return this.parentContainer && this.parentContainer.isRoot;
    }

    get hasChildren(): boolean {
        return this.children.length > 0;
    }

    // tree end

    get isContainer(): boolean {
        return !!this.container;
    }

    siblingId: string;
    container: ContainerModel;
    parentContainer: ContainerModel;
    parentComponent: ComponentModel;
    childContainers: ContainerModel[] = [];

    enhanced: boolean;
    domElement: Element;
    emptyWidget: ComponentRef<EmptyWidgetComponent>;
    addWidgetComponents: ComponentRef<AddWidgetComponent | FakeWidgetComponent>[] = [];
    wrappingCommentElements: Node[] = []; //contains the comment elements only if they are outside of the component dom.
    inlineToolbarComponent: ComponentRef<InlineToolbarComponent>;
    quickEditMenu: ComponentRef<any>;
    toolbarSubscription: Subscription;
    focusToolbarSubscription: Subscription;
    errorWidget: ComponentRef<ErrorWidgetComponent>;
    label: Element;
    private listeners: { [key: string]: EventListener } = {};

    constructor(markup: Element) {
        this.domElement = markup;
        if (this.domElement) {
            this.domElement.classList.add(CLASS_ZONE_WIDGET);

            populateFromAttributes(this);
            const classPropertyMap = {
                iscontentwidget: CLASS_CONTENT_WIDGET,
                isempty: CLASS_EMPTY,
                isorphaned: CLASS_ORPHANED,
                isemptyvisualhidden: CLASS_NO_CONTENT
            };

            Object.keys(classPropertyMap).forEach((key) => {
                if (this[key]) {
                    this.domElement.classList.add(classPropertyMap[key]);
                }
            });
        }
    }

    removeListeners() {
        this.removeEventListeners();

        if (this.toolbarSubscription)
            this.toolbarSubscription.unsubscribe();
        delete this.toolbarSubscription;

        if (this.focusToolbarSubscription)
            this.focusToolbarSubscription.unsubscribe();
        delete this.focusToolbarSubscription;
    }

    removeEventListeners() {
        Object.keys(this.listeners).forEach((listenerType) => {
            this.domElement.removeEventListener(listenerType, this.listeners[listenerType]);
        });

        this.listeners = {};
    }

    addEventListener(type: string, listener: EventListener) {
        if (!this.listeners[type]) {
            this.listeners[type] = listener;
            this.domElement.addEventListener(type, listener);
        }
    }

    clearAddWidgets() {
        this.addWidgetComponents.forEach(addwidgetComponent => {
            addwidgetComponent.location.nativeElement.remove();
            addwidgetComponent.destroy();
        });
        this.addWidgetComponents = [];
    }

    clearOrphaned() {
        this.domElement.classList.remove(CLASS_ORPHANED);
        this.isorphaned = false;
    }

    clear() {
        if (this.errorWidget) {
            this.errorWidget.destroy();
            this.errorWidget = undefined;
        }

        this.clearAddWidgets();

        this.wrappingCommentElements.forEach((commentElement) => {
            if (commentElement !== null && commentElement.parentNode !== null)
                commentElement.parentNode.removeChild(commentElement);
        });
        this.wrappingCommentElements.length = 0;

        if (this.label) {
            this.label.remove();
            this.label = undefined;
        }

        this.childContainers.forEach(x => {
            x.clear();
        });

        this.removeListeners();
        this.domElement.remove();
        if (this.inlineToolbarComponent) {
            this.inlineToolbarComponent.destroy();
            this.inlineToolbarComponent = undefined;
        }

        if (this.isContainer) {
            this.container.clear();
        }
    }

    assignState(widgetState: WidgetState) {
        if (widgetState) {
            const whiteListedProps = ["AddAllowed", "DeleteAllowed", "EditAllowed", "MoveAllowed", "LabelTooltip", "IsPersonalized", "WidgetSegmentId"];
            whiteListedProps.forEach(key => {
                if (widgetState[key] !== undefined) {
                    const expectedName = key[0].toLowerCase() + key.substr(1);
                    this[expectedName] = widgetState[key];
                }
            });

            this.handlePropertyChange();
        }
    }

    private handlePropertyChange() {
        if (this.isPersonalized) {
            this.domElement.classList.add(`-${CLASS_PERSONALIZED_WIDGET_LOOK}`);
        }
    }
}

export class ContainerModel {
    readonly placeholdername: string;
    readonly placeholderlabel: string;

    emptyicontext: string = "Add widget here...";
    emptyicon: string = "plus-circle";
    emptyiconaction: string = EMPTY_WIDGET_ACTION.EDIT;
    isemptyvisualhidden: boolean;

    domElement: Element;
    emptyWidget: ComponentRef<EmptyWidgetComponent>;
    enhanced: boolean;

    parentComponent: ComponentModel;
    children: ComponentModel[] = [];
    addAllowed: boolean = true;

    childContainers: ContainerModel[] = [];


    get isempty() {
        return this.children.length === 0 && this.childContainers.length === 0;
    }

    get isRoot(): boolean {
        return this.placeholdername === "Body";
    }


    private listeners: { [key: string]: EventListener } = {};

    constructor(markup: Element) {
        this.domElement = markup;

        if (this.domElement) {
            this.domElement.classList.add(CLASS_EDITOR_COLUMN);
            populateFromAttributes(this);
            this.placeholdername = this.domElement.getAttribute(ATTR_CONTAINER);
        }
    }

    public hasOnlyOrphans() {
        if (this.children.length > 0) {
            let result = true;
            this.children.forEach(x => {
                result = x.isorphaned && result;
            });

            return result;
        }

        return false;
    }

    public hasAnyOrphans(): boolean {
        const children = this.getDirectChildrenAndChildrenFromChildContainers();
        for (let i = 0; i < children.length; i++) {
            const child = children[i];
            if (child.isorphaned)
                return true;
        }

        return false;
    }

    public getDirectChildrenAndChildrenFromChildContainers(): ComponentModel[] {
        const flatCollection = [].concat(this.children);

        // We are not iterating recursively, because we support one level of nested containers and only on root level
        this.childContainers.forEach((childConainer) => {
            flatCollection.push(...childConainer.children);
        });

        return flatCollection;
    }

    addEventListener(type: string, listener: EventListener) {
        if (!this.listeners[type]) {
            this.listeners[type] = listener;
            this.domElement.addEventListener(type, listener);
        }
    }

    clearEmptyWidget() {
        if (this.emptyWidget) {
            //add display:none before the widget gets removed, so that it doesn't flicker
            this.emptyWidget.location.nativeElement.classList.add(CLASS_HIDDEN);
            this.emptyWidget.destroy();
            this.emptyWidget = undefined;
        }
    }

    clear() {
        this.clearEmptyWidget();
        Object.keys(this.listeners).forEach((listenerType) => {
            this.domElement.removeEventListener(listenerType, this.listeners[listenerType]);
        });
        this.listeners = {};

        this.childContainers.forEach(x => x.clear());

        this.children.forEach(x => {
            x.clear();
        });

        this.domElement.remove();
    }
}

function populateFromAttributes(componentContainer: ComponentModel | ContainerModel) {
    componentContainer.domElement.getAttributeNames().forEach((attrName) => {
        if (attrName.startsWith(ATTR_PREFIX)) {
            const propertyName = attrName.substr(ATTR_PREFIX.length);
            const attrValue = componentContainer.domElement.getAttribute(attrName);
            if (attrName.startsWith(ATTR_PREFIX_IS)) {
                componentContainer[propertyName] = attrValue === "true";
            } else {
                componentContainer[propertyName] = attrValue;
            }
        }
    });
}
