export interface RecurrentRule {
    startDate?: string;
    timeZoneId?: string;
    recursUntil?: Date;
    maxOccurrences?: number;
    interval?: number;
    duration?: string;
    frequency: RecurrenceFrequency;
    occurrences?: Date[];
    exceptions?: Date[];
    daysOfWeek?: RecurrenceDay;
    firstDayOfWeek?: DayOfWeek;
    dayOfMonth?: number;
    month?: RecurrenceMonth;
    endRecurrenceType?: EndRecurrenceType;
}

export enum RecurrenceMonth {
    None = 0,
    January = 1,
    February = 2,
    March = 3,
    April = 4,
    May = 5,
    June = 6,
    July = 7,
    August = 8,
    September = 9,
    October = 10,
    November = 11,
    December = 12
}

export enum DayOfWeek {
    Sunday = 0,
    Monday = 1,
    Tuesday = 2,
    Wednesday = 3,
    Thursday = 4,
    Friday = 5,
    Saturday = 6
}

export enum RecurrenceDay {
    None = 0,
    Sunday = 1,
    Monday = 1 << 1,
    Tuesday = 1 << 2,
    Wednesday = 1 << 3,
    Thursday = 1 << 4,
    Friday = 1 << 5,
    Saturday = 1 << 6,
    EveryDay = Monday | Tuesday | Wednesday | Thursday | Friday | Saturday | Sunday,
    WeekDays = Monday | Tuesday | Wednesday | Thursday | Friday,
    WeekendDays = Saturday | Sunday
}

export enum RecurrenceFrequency {
    None,
    Hourly,
    Daily,
    Weekly,
    Monthly,
    Yearly
}

export enum EndRecurrenceType {
    Never,
    By,
    After
}
