import { Command } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject } from "rxjs";
import { DataItem, FieldWithLimitations } from "../../../interfaces";
import { Router, NavigationExtras } from "@angular/router";
import { Injectable, Inject } from "@angular/core";
import { Location } from "@angular/common";
import { WINDOW_TOKEN } from "../../../../../../window.provider";
import { buildQueryString, getQueryParams } from "./commands-helper";
import { ROUTE_PARAMS, FILTER_PARAMS, QUERY_PARAMS } from "../../../../constants";
import { ChainedOperationResult } from "./confirmation-command";

export interface EditArgument {
    parentId: string;
    dataItem: DataItem;
    replaceUrl: boolean;
    duplicate?: boolean;
    prepopulatedFields?: any;
    reload?: boolean;
    openInNewWindowArgs?: OpenInNewWindowArguments;
    mediaFieldLimitationsConstraints?: FieldWithLimitations;
    translationCultureSource?: string;
    siteId?: string;
}

export interface OpenInNewWindowArguments {
    openInNewTab: boolean;
    baseUrl: string;
}

@Injectable()
export class EditCommand implements Command {
    constructor(private router: Router, private location: Location, @Inject(WINDOW_TOKEN) private window: Window) {
    }

    // eslint-disable-next-line complexity
    execute(context: ExecutionContext): Observable<ChainedOperationResult> {
        const data = <EditArgument>context.data;
        const dataItem = <DataItem>data.dataItem;
        const metadata = dataItem.metadata;
        const isHierarchical = dataItem.metadata.hasParent && data.parentId;
        let navigateUrl: string = null;
        let relativeTo = context.currentRoute.firstChild;
        if (isHierarchical) {
            navigateUrl = `${metadata.parent}/${data.parentId}/${metadata.setName}`;
            if (dataItem.metadata.ignoreParentChildRelationship && !dataItem.metadata.isMedia) {
                navigateUrl = `${metadata.setName}`;
            } else if (dataItem.metadata.isMedia) {
                navigateUrl = `${metadata.setName}/${data.parentId}/${metadata.setName}`;
            }
            if (dataItem.isEmpty) {
                navigateUrl += `/${ROUTE_PARAMS.CREATE_SEGMENT}`;
            } else if (data.duplicate) {
                navigateUrl += `/${dataItem.key}/${ROUTE_PARAMS.DUPLICATE_SEGMENT}`;
            } else {
                navigateUrl += `/${dataItem.key}/${ROUTE_PARAMS.EDIT_SEGMENT}`;
            }
            relativeTo = context.currentRoute;
        } else if (dataItem.isEmpty) {
            navigateUrl = `${ROUTE_PARAMS.CREATE_SEGMENT}`;
        } else if (data.duplicate) {
            navigateUrl = `${dataItem.key}/${ROUTE_PARAMS.DUPLICATE_SEGMENT}`;
        } else {
            navigateUrl = `${dataItem.key}/${ROUTE_PARAMS.EDIT_SEGMENT}`;
        }

        const queryParams = getQueryParams(dataItem, context.currentRoute);

        if (dataItem.metadata.ignoreParentChildRelationship && data.parentId && !metadata.isMedia) {
            queryParams[FILTER_PARAMS.FILTER] = `Parent,${data.parentId}`;
        }

        if (data.translationCultureSource) {
            queryParams[QUERY_PARAMS.TRANSLATING_FROM] = data.translationCultureSource;
        }

        if (data.siteId) {
            queryParams[QUERY_PARAMS.SITE] = data.siteId;
        }

        const return$ = new ReplaySubject<ChainedOperationResult>(1);
        const navigationExtras: NavigationExtras = { relativeTo, queryParams };

        if (data.replaceUrl) {
            const urlTree = this.router.createUrlTree([navigateUrl], navigationExtras);
            const urlPath = this.router.serializeUrl(urlTree);
            this.location.replaceState(urlPath);

            return$.next({ success: true });
            return return$.asObservable();
        }

        if (data.reload) {
            if (navigationExtras.queryParams) {
                navigationExtras.queryParams["reload"] = new Date().getTime();
            }
        }

        if (data.openInNewWindowArgs && data.openInNewWindowArgs.openInNewTab) {
            if (!isHierarchical) {
                navigateUrl = `${dataItem.metadata.setName}/${navigateUrl}`;
            }

            const url = `${data.openInNewWindowArgs.baseUrl}/${navigateUrl}${buildQueryString(queryParams)}`;
            this.window.open(url, data.parentId);
            return$.next({ success: true });
        } else {
            this.router.navigate([navigateUrl], navigationExtras)
            .then((canDeactivate) => { return$.next({ success: canDeactivate }); })
            .catch((err) => return$.error(err));
        }

        return return$.asObservable();
    }
}
