import { Injectable } from "@angular/core";
import { Router } from "@angular/router";
import { from, Observable, of } from "rxjs";
import { Command, ExecutionContext } from "../../../api";
import { environmentTypes } from "../../../environment";
import { EnvironmentService } from "../../shared/services/environment.service";
import { ATTR_NAME } from "../../content/constants";

const RadMenuNavigationId = "MainMenu";

@Injectable()
export class NavigateToMenuSectionCommand implements Command {
    constructor(private router: Router, private envService: EnvironmentService) {}

    execute(context: ExecutionContext): Observable<any> {
        const env = this.envService.getEnvironment();
        if (env !== environmentTypes.integration) {
            const navigate = this.router.navigate(context.data.route);

            return from(navigate);
        } else {
            const targetPath = `/${context.data.route}`;

            // Simulate navigation triggered by the RadMenu navigation in order all selection to be correct
            const targetLink = this.getNavigationLinkElement(targetPath);

            if (targetLink) {
                targetLink._click(new MouseEvent("click"));
            }

            return of(!!targetLink);
        }
    }

    private getNavigationLinkElement(url: string) {
        const  menu = document.getElementById(RadMenuNavigationId) as any;

        return menu.control.get_allItems().find((menuItem) => menuItem.get_attributes().getAttribute(ATTR_NAME) === url);
    }
}
