import { Injectable } from "@angular/core";
import { Router, ActivatedRouteSnapshot, RouterStateSnapshot, Resolve } from "@angular/router";
import { map, Observable } from "rxjs";
import { DataItem } from "../../api";
import { ROUTE_PATHS } from "../../constants/route-paths";
import { BaseResolver } from "../content/dynamic-modules/components/dynamic-items-base.resolver";
import { CompositeEntityDataResolver } from "../content/dynamic-modules/services/backend-tweaks/entity-data.resolver";
import { DynamicItemStore } from "../content/dynamic-modules/services/dynamic-item.store";
import { ProviderStore } from "../content/dynamic-modules/services/provider-store";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { MetadataStore } from "../shared/services/metadata/meta-data.store";
import { Settings } from "../shared/services/settings.service";

@Injectable()
export class FormResponsesGuard extends BaseResolver implements Resolve<any> {
    constructor(
        store: ProviderStore,
        router: Router,
        settings: Settings,
        entityDataResolver: CompositeEntityDataResolver,
        private dynamicItemStore: DynamicItemStore,
        private metadataStore: MetadataStore) {
        super(store, router, settings, entityDataResolver);
        this.persistCulture = true;
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> {
        const formDraftsEntity = this.metadataStore.getValue().entities[ENTITY_SET.FORM_DRAFTS];
        const formDataItem = DataItem.emptyItem({
            metadata: formDraftsEntity,
            culture: null,
            provider: null,
        });

        const formId = route.params.parentId;
        return this.dynamicItemStore.service.executeBoundAction<any>(formDataItem, `${formId}/Default.HasFormViewPermissions()`, {}).pipe((map(response => {
            if (!response.value) {
                this.router.navigate([ROUTE_PATHS.ACCESS_DENIED]);
                return false;
            }

            return true;
        })));
    }
}