import { Component, OnInit, Inject, Optional, TemplateRef } from "@angular/core";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { ServiceContract, ServiceInfo } from "../../../../../fields/selector/selector.component";
import { TreeConfig, TreeItem } from "../../../../../fields";
import { TypeNames } from "../../../../../fields/types/types";
import { DynamicItemService, LoadItemsData } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ActivatedRoute } from "@angular/router";
import { stringConstants } from "../../../common-constants";
import { HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { HierarchicalDynamicItemService } from "../../content/dynamic-modules/services/hierarchical-dynamic-item-service";
import { DEFAULT_CHILDREN_LOAD } from "../../content/constants";
import { map, mergeMap, reduce } from "rxjs/operators";
import { TaxonomySettings } from "../taxonomy.settings";
import { CompositeOperationsProvider } from "../../content/dynamic-modules/services/operations/operations-provider";
import { TAXONOMY_STRING_CONSTANTS } from "../taxonomy.constants";
import { Observable, from as observableFrom } from "rxjs";
import { BulkItemSelectionInfo } from "../../content/dynamic-modules/components/bulk-operations/bulk-operations.component";

@Component({
    templateUrl: "./move-taxon.component.html"
})

export class MoveTaxonComponent implements OnInit {
    dataItems: DataItem[];
    taxons: TaxonTreeItem[] = [];
    treeConfig: TreeConfig;
    totalCount: number = 0;
    selected: any[] = [];
    isLoading: boolean;
    serviceAware: ServiceContract;
    pluralName: string;
    singularName: string;
    taxaNames: TypeNames = { plural: stringConstants.EMPTY_STRING, singular: stringConstants.EMPTY_STRING};
    defaultFieldName: string;
    selectedItemsText: string;
    selectedItemsCount: number;
    itemTypeText: string;
    titleTemplate: TemplateRef<any>;
    descriptionTemplate: TemplateRef<any>;

    private contextParameters: any[];
    private parentId: string;
    private entityData: EntityData;
    private hierarchicalService: HierarchicalDynamicItemService;
    private isHierarchical: boolean;
    private letters: string[] = [];
    private searchMode: boolean = false;
    private defaultTake: number = 50;
    private itemSelectionInfo: BulkItemSelectionInfo;

    constructor(protected route: ActivatedRoute,
                private dynamicItemService: DynamicItemService,
                @Optional() @Inject(HIERARCHICAL_SERVICE_TOKEN) private hierarchicalServices: Array<HierarchicalDynamicItemService>) { }

    ngOnInit() {
        if (this.hierarchicalServices) {
            this.hierarchicalServices.forEach(service => {
                if (service.isTypeSupported(this.entityData)) {
                    this.hierarchicalService = service as HierarchicalDynamicItemService;
                }
            });
        }

        if (!this.hierarchicalService && this.entityData.metadata.setName && this.entityData.metadata.singularName) {
            this.hierarchicalService = this.hierarchicalServices.find(service => service instanceof HierarchicalDynamicItemService);
            this.hierarchicalService.setName = this.entityData.metadata.setName;
            this.hierarchicalService.singularName = this.entityData.metadata.singularName;
        } else if (!this.hierarchicalService) {
           return;
        }

        this.pluralName = CompositeOperationsProvider.getOperationPluralName(this.entityData.metadata, this.contextParameters).toLowerCase();
        this.singularName = CompositeOperationsProvider.getOperationSingularName(this.entityData.metadata, this.contextParameters).toLowerCase();

        this.defaultFieldName = this.entityData.metadata.defaultFieldName;
        this.isHierarchical = this.hierarchicalService.isHierarchical(this.entityData.metadata.setName);
        this.itemTypeText = this.isHierarchical ? TAXONOMY_STRING_CONSTANTS.CATEGORIZED : TAXONOMY_STRING_CONSTANTS.TAGGED;

        this.treeConfig =  {
            multiSelection: false,
            isHierarchical: this.isHierarchical
        };

        this.getItems();

        // set selected taxon list
        this.setSelectedItems();

        this.serviceAware = new ServiceContract(
            (info: ServiceInfo) => this.loadMore(info),
            (info: ServiceInfo) => this.expandChildren(info));
    }

    private getItems(): void {
        this.isLoading = true;

        const settings = new TaxonomySettings(this.parentId, true);
        settings.id = this.parentId;
        settings.type = this.entityData.metadata.setName;
        const serviceInfo: ServiceInfo = { parentId: this.parentId, skip: 0, take: this.defaultTake };

        this.hierarchicalService.loadMore(serviceInfo, this.entityData, settings).subscribe(result => {
            this.totalCount = result.totalCount;
            this.taxons = this.getTaxonCollection(result.dataItems, this.isHierarchical === false);
            this.isLoading = false;
        });
    }

    private setSelectedItems() {
        if (this.itemSelectionInfo && this.itemSelectionInfo.allItemsSelected === true) {
            if (this.dataItems && this.dataItems.length) {
                this.getAllSelectedItems().subscribe(data => {
                    const selectedItems = this.orderSelectedItems(data).map(item => { return item.title; });
                    this.selectedItemsText = selectedItems.join(`${stringConstants.COMMA}${stringConstants.INTERVAL}`);
                    this.selectedItemsCount = selectedItems.length;
                });

            }
        } else {
            const selectedItems = this.orderSelectedItems(this.dataItems).map(item => { return item.title; });
            this.selectedItemsText = selectedItems.join(`${stringConstants.COMMA}${stringConstants.INTERVAL}`);
            this.selectedItemsCount = selectedItems.length;
        }
    }

    private getAllSelectedItems(): Observable<Array<DataItem>> {
        const skips = [];
        for (let i = 0; i < this.dataItems.length; i += this.defaultTake) {
            skips.push(i);
        }

        return observableFrom(skips).pipe(
            mergeMap(skip => this.getSelectedItems(skip)),
            reduce((previous, current) => previous.concat(current)));
    }

    private getSelectedItems(skip: number): Observable<Array<DataItem>> {
        const loadItemsData: LoadItemsData = {
            entityData: this.entityData,
            skip: skip,
            dataFieldNames: [this.entityData.metadata.key, this.entityData.metadata.defaultFieldName],
            fallbackProperties: [this.entityData.metadata.defaultFieldName]
        };

        return this.dynamicItemService.getItemListBatch(loadItemsData).pipe(
            map(response => response.dataItems
                .filter(item => !this.itemSelectionInfo.deselectedItems.has(item.key))
            ));
    }

    private orderSelectedItems(dataItems: DataItem[]): DataItem[] {
        return dataItems.sort((a, b) => a.title.localeCompare(b.title));
    }

    private loadMore(info: ServiceInfo): Observable<any> {
        const settings = new TaxonomySettings(this.parentId, true);
        settings.id = this.parentId;
        settings.type = this.entityData.metadata.setName;
        info.parentId = this.parentId;

        const previousSearchMode = this.searchMode;
        this.searchMode = !!info.searchText && info.searchText !== stringConstants.EMPTY_STRING;

        // reset letters if we are leaving search mode
        if (previousSearchMode !== this.searchMode && this.searchMode === false) {
            this.letters = [];
        }

        return this.hierarchicalService.loadMore(info, this.entityData, settings).pipe(
            map(data => {
                return {
                    dataItems: this.getTaxonCollection(
                        data.dataItems,
                        this.isHierarchical === false && this.searchMode === false
                    ),
                    totalCount: data.totalCount
                };
            }));
    }

    private expandChildren(info: ServiceInfo): Observable<any> {
        if (!info.take) {
            info.take = DEFAULT_CHILDREN_LOAD;
        }

        return this.hierarchicalService.expandChildren(info, this.entityData, this.parentId).pipe(
            map(data => {
                return { dataItems: this.getTaxonCollection(data.dataItems, false), totalCount: data.totalCount };
            }));
    }

    private getTaxonCollection(dataItems: DataItem[], insertLetters: boolean): TaxonTreeItem[] {
        const results: TaxonTreeItem[] = [];

        dataItems.forEach(dataItem => {
            const item = this.cloneAndAddFieldsToDataItem(dataItem);
            if (insertLetters) {
                const firstChar = item.Title.toLowerCase()[0];
                if (this.letters.indexOf(firstChar) === -1) {
                    this.letters.push(firstChar);
                    const letterItem: TaxonTreeItem = {
                        Id: `letter_${firstChar}`,
                        Title: firstChar.toUpperCase(),
                        isSelectionDisabled: true,
                        isHeading: true
                    };

                    results.push(letterItem);
                }
            }

            results.push(item);
        });

        return results;
    }

    private cloneAndAddFieldsToDataItem(dataItem: DataItem): TaxonTreeItem {
        const item = JSON.parse(JSON.stringify(dataItem.data));
        const taxon: TaxonTreeItem = {
                Id: item.Id,
                Title: item.Title,
                ParentId: item.ParentId,
                isSelectionDisabled: false,
                isTranslated: dataItem.isTranslated
        };

        if (!item) {
            taxon.BreadcrumbPath = this.getBreadcrumbPath(item);
        }

        if (this.isHierarchical) {
            taxon.hasChildren = item.HasChildren;
        }

        return taxon;
    }

    private getBreadcrumbPath(dataItem): string {
        const bc = dataItem.Breadcrumb;
        let title = dataItem.Title;
        if (Array.isArray(bc) && bc.length > 0) {
            title = `${bc.join(" > ")} > ${title}`;
        }

        return title;
    }
}

interface TaxonTreeItem extends TreeItem {
    Id?: string
    Title: string;
    isSelectionDisabled: boolean;
    ParentId?: string;
    hasChildren?: boolean;
    isTranslated?: boolean;
    BreadcrumbPath?: string;
}
