import { MetadataHandler } from "../shared/services/metadata/metadata.handler";
import { Injectable } from "@angular/core";
import { ENTITY_SET, FORMS_DESCRIPTION_FULL_NAME, KEY_VALUE_OPTIONS, OVERRIDEN_OPTION_NAMES_FIELD_NAME, TWEAKS_METADATA_PROPERTIES } from "../shared/services/metadata/meta-data-constants";
import { FormConnectorProperties, Properties } from "../shared/fields.constants";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { FieldModel } from "../../services/field.model";
import { Entity } from "../shared/services/metadata/meta-data.store";
import { FormData } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { CompositeFieldsProvider } from "../shared/fields-builder/providers/fields-provider";
import { ChoiceSettings } from "../../../../fields/choice/choice.settings";
import { ChoiceItem, stringConstants } from "@progress/sitefinity-component-framework";
import { SettingsBase } from "../../../../fields/field-settings-base";
import { FORM_REDIRECT_PAGE_PROPERTIES } from "./components/form-redirect-page/form-redirect-page.composite.component";
import { ComplexSettings } from "../widget-editor/providers/fields/complex/complex.settings";
import { AdditionalUrlsSettings } from "../additionalUrls/additionalUrls-settings";
import { FORM_NOTIFICATIONS_PROPERTIES } from "./forms-tweaks-handler.service";
import { ParameterizedChoiceSelectorSettings } from "../widget-editor/providers/fields/parameterized-choice-selector/parameterized-choice-selector.settings";
import { FIELD_TYPES } from "../content/constants";

const SEQUENTIAL_LOOK = "SequentialLook";
const TARGET_FIELD_NAME = "TargetFieldName";

const FORM_CONNECTOR_TWEAKS_METADATA_PROPERTIES = {
    TYPE: "Type",
    CONNECTOR_FORMS: "ConnectorForms"
};

const DATA_MAPPING_FIELD_TYPE_NAME = "data-mapping";

const FORM_FIELD_COLUMN_NAMES = {
    FormField : "FormField",
    ConnectorFieldName : "ConnectorFieldName"
}

const FORM_SITEFINITY_FIELD_COLUMN_TITLE = "Sitefinity CMS Field";
const EMPTY_FORMS_FIELDS_MESSAGE = "No fields have been added to this form."

const FIELD_GROUPS = [{
    fields: [
        FORM_REDIRECT_PAGE_PROPERTIES.SUBMIT_ACTION,
        FORM_REDIRECT_PAGE_PROPERTIES.REDIRECT_PAGE
    ],
    fieldType: FieldTypes.formRedirectPageCompositeField,
    titles: {
        [FORM_REDIRECT_PAGE_PROPERTIES.SUBMIT_ACTION]: stringConstants.EMPTY_STRING,
        [FORM_REDIRECT_PAGE_PROPERTIES.REDIRECT_PAGE]: stringConstants.EMPTY_STRING
    }
}];

@Injectable()
export class FormsMetadataHandler extends MetadataHandler {
    fieldGroups: any[] = FIELD_GROUPS;

    constructor(protected fieldsProvider: CompositeFieldsProvider) {
        super(fieldsProvider);
    }

    getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string {
        if (propertyName === FORM_NOTIFICATIONS_PROPERTIES.SUBSCRIBED_EMAILS) {
            return FieldTypes.additionalUrls;
        }

        if (propertyTweak) {
            const tweakMetadata = propertyTweak.metadata;
            if (tweakMetadata) {
                if (tweakMetadata[FORM_CONNECTOR_TWEAKS_METADATA_PROPERTIES.TYPE] === DATA_MAPPING_FIELD_TYPE_NAME) {
                    return FieldTypes.complex;
                } else if (tweakMetadata[FORM_CONNECTOR_TWEAKS_METADATA_PROPERTIES.CONNECTOR_FORMS]) {
                    return FieldTypes.choiceParameterizedSelector;
                } else if (tweakMetadata[TWEAKS_METADATA_PROPERTIES.ROWS] === 1) {
                    const propertyType = metadata.properties[propertyName].type;
                    if (propertyType && propertyType.findIndex(p => p === FIELD_TYPES.INTEGER) > -1) {
                        return FieldTypes.number;
                    }
                    else if (propertyName !== Properties.NAME) {
                        return FieldTypes.shortText;
                    }
                }
            }
        }

        return null;
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === FORMS_DESCRIPTION_FULL_NAME;
    }

    updateFieldSettings(fields: FieldModel[], metadata: Entity, tweaks: any[]) {
        if (metadata.setName !== ENTITY_SET.FORMS) {
            return;
        }

        fields.forEach(field => {
            field.settings.showForAllTranslationsLabel = false;

            if (field.selector === FieldTypes.shortTextDefault) {
                field.settings.look = "large";
            } else if (field.selector === FieldTypes.choice) {
                this.updateChoiceField(field, tweaks);
            } else if (field.selector === FieldTypes.complex) {
                this.updateComplexField(field, tweaks);
            } else if (field.selector === FieldTypes.choiceParameterizedSelector) {
                this.updateFormSelectorField(field, tweaks);
            } else if (field.selector === FieldTypes.choiceYesNo) {
                this.updateFormChoiceYesNoField(field, tweaks);
            }

            if (field.key === FORM_NOTIFICATIONS_PROPERTIES.SUBSCRIBED_EMAILS) {
                this.updateSubscribedEmailsField(field, tweaks);
            }

            if (field.key === FormConnectorProperties.MARKETO_CHANGE_LEAD_SCORE_AMOUNT) {
                field.cssClass = "-sf-mt-xs";
            }
        });
    }

    updateFormSelectorField(field: FieldModel, tweaks: any[]) {
        const tweak = tweaks.find(x => x.name === field.key);

        if (tweak) {
            const tweakMetadata = tweak.metadata;
            const connectorChoiceForms: ChoiceItem[] = [];
            if (tweakMetadata.ConnectorForms) {
                const connectorForms = tweakMetadata.ConnectorForms as string[];

                connectorForms.forEach(element => {
                    connectorChoiceForms.push({
                        Name: element,
                        Value: element,
                        Title: element,
                    })
                });
            }

            const settings = field.settings as ParameterizedChoiceSelectorSettings;
            settings.choices = connectorChoiceForms,
            settings.template = "chips";
            settings.recentCount = 5;
            settings.allowRemoveSelection = true;
            settings.showRecentLabel = true;
            settings.keyLabel = "form";
            settings.valueType = "string";

            if (tweakMetadata[TARGET_FIELD_NAME]) {
                settings.targetFieldName = tweakMetadata[TARGET_FIELD_NAME];
            }
        }
    }

    updateInnerFieldsSettings(innerFields, tweaks: FormData[], readonly: boolean) {
        Object.keys(innerFields).forEach(prop => {
            const field = innerFields[prop];
            if (field) {
                const settings = field.settings as SettingsBase;
                settings.showTitle = false;
                const tweak = tweaks.find(x => x.name === prop);
                if (tweak) {
                    settings.isVisible = true;
                    settings.readOnlyMode = readonly || tweak.readonly;
                } else {
                    settings.required = false;
                    settings.isVisible = false;
                }

                if (field.selector === FieldTypes.choice) {
                    this.updateChoiceField(field, tweaks);
                }
            }
        });
    }

    private updateChoiceField(field: FieldModel, tweaks: FormData[]): void {
        // TODO: revise this
        field.settings.hasFieldset = false;

        const settingsCast = field.settings as ChoiceSettings;
        const tweak = tweaks.find(x => x.name === field.key);

        if (tweak) {
            const tweakMetadata = tweak.metadata;

            if (tweakMetadata && tweakMetadata[KEY_VALUE_OPTIONS]) {
                const options: ChoiceItem[] = [];
                const overriddenOptionNames = tweakMetadata[OVERRIDEN_OPTION_NAMES_FIELD_NAME];

                tweakMetadata[KEY_VALUE_OPTIONS].forEach(option => {
                    let name = option["Key"];
                    if (overriddenOptionNames) {
                        const overriddenOptionName = overriddenOptionNames.find(x => x.Name === name);
                        if (overriddenOptionName) {
                            name = overriddenOptionName.Title || name;
                        }
                    }
                    options.push({
                        Name: name,
                        Value: option["Value"]
                    });
                });

                settingsCast.choices = options;
                const defaultValue = tweakMetadata[TWEAKS_METADATA_PROPERTIES.PREDEFINED_VALUE];
                if (defaultValue !== undefined && defaultValue !== null) {
                    field.settings.defaultValue = defaultValue;
                    field.settings.useDefaultValue = true;
                    if (!field.value) {
                        field.value = defaultValue;
                    }
                }
            }
        }
    }

    private updateSubscribedEmailsField(field: FieldModel, tweaks: FormData[]): void {
        const tweak = tweaks.find(t => t.name === field.key);
        const additionalUrlsSettings = field.settings as AdditionalUrlsSettings;
        if (tweak && additionalUrlsSettings) {
            additionalUrlsSettings.title = tweak.title;
            additionalUrlsSettings.addButtonTitle = "Add";
        }
    }

    private updateComplexField(field: FieldModel, tweaks: any[]) {
        const tweak = tweaks.find(x => x.name === field.key);

        if (tweak) {
            const tweakMetadata = tweak.metadata;
            const selectionDisabledMessage = tweakMetadata.SelectionDisabledMessage || stringConstants.EMPTY_STRING;
            const connectorChoiceFields: ChoiceItem[] = [];
            if (tweakMetadata.ConnectorFields) {
                const connectorFields = tweakMetadata.ConnectorFields as string[];

                connectorFields.forEach(element => {
                    connectorChoiceFields.push({
                        Name: element,
                        Value: element,
                        Title: element
                    })
                });
            }

            const connectorName = tweakMetadata.ConnectorName || stringConstants.EMPTY_STRING;
            const settings = field.settings as ComplexSettings;
            settings.allowAdd = false;
            settings.allowRemove = false;
            settings.allowCreate = true;
            settings.isMultiple = true;
            settings.hideRowsIfEmpty = true;
            settings.type = "enumerable";
            settings.warningText = EMPTY_FORMS_FIELDS_MESSAGE;
            settings.look = "middle";
            settings.typeChildProperties = [
                {
                    Name: FORM_FIELD_COLUMN_NAMES.FormField,
                    Title: FORM_SITEFINITY_FIELD_COLUMN_TITLE,
                    DefaultValue: null,
                    Type: "titleRead",
                    Properties: {
                        "Meta_TitleFieldName" : "Title",
                        "Meta_DescriptionFieldName": "FieldName"
                    },
                },
                {
                    Name: FORM_FIELD_COLUMN_NAMES.ConnectorFieldName,
                    Title: `${connectorName} field`,
                    DefaultValue: null,
                    Type: "choiceParameterizedSelector",
                    Properties: {
                        "Meta_Choices": connectorChoiceFields,
                        "Meta_Choices_AllowMultiple": false,
                        "Meta_Template": "chips",
                        "Meta_RecentCount": 5,
                        "Meta_ValueType": "string",
                        "Meta_KeyLabel": "field",
                        "Meta_AllowRemoveSelection": true,
                        "Meta_SelectionDisabledMessage": selectionDisabledMessage,
                        "Meta_ShowRecentLabel": true,
                        "Meta_SelectionDisabledMessageLook": "sf-mb-zero"
                    }
                }
            ]
        }
    }

    private updateFormChoiceYesNoField(field: FieldModel, tweaks: any[]) {
        const tweak = tweaks.find(x => x.name === field.key);

        if (tweak) {
            const tweakMetadata = tweak.metadata;

            if (tweakMetadata) {
                const sequentialLook = tweakMetadata[SEQUENTIAL_LOOK]
                if (sequentialLook === true) {
                    field.cssClass = field.key === FormConnectorProperties.MARKETO_SEND_FORMS_DATA ? "-sequence -sf-mt-3xs " : "-sequence";
                }
            }
        }
    }
}

export const FORMS_METADATA_HANDLER = { provide: MetadataHandler, useClass: FormsMetadataHandler, multi: true };
