import { from as observableFrom, Observable } from "rxjs";
import { Command } from "../../../../../shared/commands/command";
import { Router, ActivatedRoute } from "@angular/router";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { DataItem, EntityData } from "../../../interfaces";
import { Entity } from "../../../../../shared/services/metadata/meta-data.store";
import { QUERY_PARAMS, FILTER_PARAMS } from "../../../../constants";
import { stringConstants } from "../../../../../../common-constants";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { Injectable } from "@angular/core";

@Injectable()
export class NavigateCommand implements Command {
    constructor(private router: Router) {

    }

    execute(context: ExecutionContext): Observable<any> {
        const navigateData = <NavigateData>context.data;
        const item = navigateData.dataItem;
        const entityData = <EntityData>navigateData.metadata;
        let indexUrl = stringConstants.EMPTY_STRING;

        if (!navigateData.indexUrl) {
            if ((navigateData.navigateToGrid && navigateData.parentSetName) || !entityData.metadata.ignoreParentChildRelationship) {
                indexUrl = this.getParentIndexUrl(item, entityData.metadata, navigateData.isChildNavigate, navigateData.parentSetName, navigateData.childSetName);
            } else {
                indexUrl = this.getAllItemsUrl(entityData.metadata);
            }
        } else {
            indexUrl = navigateData.indexUrl;
        }

        const ignoreParentChildRelationship = entityData && entityData.metadata && entityData.metadata.ignoreParentChildRelationship;
        const queryParams = this.getQueryParamsOrDefault(item, entityData, context.currentRoute.parent, ignoreParentChildRelationship, navigateData.additionalQueryParams);
        const relativeTo = item || !navigateData.indexUrl ? (context.data.relativeTo || context.currentRoute.parent.parent) : null;

        const navigate = this.router.navigate([indexUrl], { relativeTo: relativeTo, queryParams });
        return observableFrom(navigate);
    }

    private getParentIndexUrl(dataItem: DataItem, metadata: Entity, isChildNavigate: boolean, parentSetName: string = null, setName: string = null) {
        const state = this.getRouteState(dataItem, metadata, isChildNavigate, setName);
        return `${parentSetName || state.parentSetName}/${state.parentKey || stringConstants.EMPTY_STRING}/${state.childSetName || stringConstants.EMPTY_STRING}`;
    }

    private getAllItemsUrl(metadata: Entity) {
        return `${metadata.parent || metadata.children[0]}`;
    }

    private getRouteState(dataItem: DataItem, metadata: Entity, isChildNavigate: boolean, setName: string = null): RouteState {
        if (!dataItem) {
            // metadata.parent is used for the straightforward case like hierarchical dynamic items, list items etc.
            // metadata.children[0] is used to support circular navigations like Events -> Calendars, Calendars -> event
            // where the parent-child relationship is ignored
            return {
                childSetName: setName,
                parentSetName: metadata.parent || metadata.children[0]
            };
        }

        const parentKey = dataItem.parentKey;
        const key = dataItem.key;
        const parentSetName = dataItem.metadata.parent;
        const currentSetName = dataItem.metadata.setName;
        const childSetName = dataItem.childSetName;

        if (isChildNavigate) {
            return {
                parentSetName: currentSetName,
                childSetName: setName || childSetName || currentSetName,
                parentKey: key
            };
        } else if (dataItem && dataItem.metadata.hasParent) {
            return {
                parentSetName: parentSetName,
                childSetName: currentSetName,
                parentKey: parentKey
            };
        } else {
            return {
                parentSetName: currentSetName,
                childSetName: null,
                parentKey: null
            };
        }
    }

    private getQueryParamsOrDefault(item: DataItem, entityData: EntityData, route: ActivatedRoute, ignoreParentChildRelationship: boolean = false, additionalQueryParams: { [paramName: string]: string } = null) {
        const queryParams = {};
        if (item) {
            queryParams[QUERY_PARAMS.PROVIDER] = entityData.provider;
            queryParams[QUERY_PARAMS.CULTURE] = entityData.culture;
            if (ignoreParentChildRelationship && !MediaHelpers.isLibraryOrMedia(entityData.metadata.setName)) {
                queryParams[FILTER_PARAMS.FILTER] = `Parent,${item.data.Id}`;
            }
        } else {
            const params = route.snapshot.queryParams;

            queryParams[QUERY_PARAMS.PROVIDER] = params[QUERY_PARAMS.PROVIDER];
            queryParams[QUERY_PARAMS.CULTURE] = params[QUERY_PARAMS.CULTURE];
        }

        if (additionalQueryParams) {
            for (const param in additionalQueryParams) {
                if (additionalQueryParams.hasOwnProperty(param)) {
                    queryParams[param] = additionalQueryParams[param];
                }
            }
        }

        return queryParams;
    }
}

interface NavigateData {
    dataItem: DataItem;
    metadata: EntityData;
    childSetName?: string;
    parentSetName?: string;
    navigateToGrid?: boolean;
    isChildNavigate?: boolean;
    indexUrl?: string
    additionalQueryParams?: { [paramName: string]: string }
}

interface RouteState {
    parentSetName: string;
    parentKey?: string;
    childSetName?: string;
}
