import { Injectable, ClassProvider } from "@angular/core";
import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "./operations-filter";
import { Operation } from "../../../../shared/components/action-menu/operation.model";
import { OperationsData, OperationsTarget } from "./interfaces";

@Injectable()
export class ParentOperationsFilter implements OperationsFilter {
    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (!data.dataItem.metadata.hasContent) {
            if (data.target === OperationsTarget.Create || data.target === OperationsTarget.Edit) {
                const childOperations = operations.filter(o => o.ParentOperation && o.ParentOperation.Name !== null);

                if (childOperations.length === 0) {
                    return operations;
                }

                const parentOperationNames = new Set(childOperations.map(o => o.ParentOperation.Name));
                return operations.filter(o => !parentOperationNames.has(o.Name));
            }
        }

        return operations;
    }
}

export const PARENT_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: ParentOperationsFilter
};
