import { ElementRef, ViewChild, ViewEncapsulation, Input, EventEmitter, Component, Output, HostListener, OnInit, Inject, AfterViewChecked } from "@angular/core";

import {
    LayoutService,
    DEFAULT_BOX_HEIGHT,
    DOCUMENT_ROW_HEIGHT,
    DEFAULT_BOX_SPACING,
    Layout,
    DOCUMENT_BOX_SPACING,
    Box
} from "./services/layout.service";
import { LOCALE } from "../../../../fields/common/common-constants";
import { MediaRecognizerService } from "./media/media-recognizer.service";
import { EntityData, DataItem } from "../content/dynamic-modules/interfaces";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";
import { cloneObject, deepClone } from "../../utils";
import { ReorderableThumbsComponent } from "./media/reorderable-thumbs.component";
import { ScrollService } from "../../services/scroll.service";
import { WINDOW_TOKEN } from "../../window.provider";
import { FileListSettings } from "./file-list.settings";
import { Properties } from "../shared/fields.constants";
import { ReplaySubject } from "rxjs";

const GROUP_BY_TITLE_OUTER_HEIGHT_AND_MARGIN: number = 66; // Group Title height + top and bottom margin
const GROUP_HORIZONTAL_MARGIN: number = 60; // -sf-mb-5xl
const DEFAULT_BOTTOM_GUTTER: number = 80;

@Component({
    selector: "sf-file-list",
    templateUrl: "./file-list.component.html",
    encapsulation: ViewEncapsulation.None
})
export class FileListComponent extends ReorderableThumbsComponent<FileListSettings> implements OnInit, AfterViewChecked {

    @Output() selectFile = new EventEmitter();
    @Output() clickFile = new EventEmitter();

    @ViewChild("wrapper", { static: true }) wrapper: ElementRef;

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    @Input() value: DataItem[] = [];
    @Input() dimNotTranslated: boolean = false;
    @Input() showNotTranslatedLabel: boolean = true;
    @Input() culturesByFile: { [key: string]: string[] } = {};
    @Input() reorderable: boolean = false;
    @Input() isSelectable: boolean = true;
    @Input() isNonTranslatedSelectable: boolean = true;
    @Input() isCentered: boolean;
    @Input() showFileName = false;
    @Input() mediaEntityData: EntityData;

    // TODO: Remove this and use value
    get mediaItems() {
        return this._files;
    }

    @Input()
    set mediaItems(items: DataItem[]) {
        this._files = items;
        this.groupFiles();
    }

    @Input()
    set groupByMonth(value: boolean) {
        this._groupByMonth = value;
    }
    get groupByMonth() {
        return this._groupByMonth;
    }

    @Input()
    bottomGutter = DEFAULT_BOTTOM_GUTTER;
    showRemoveButton = false;
    title: string;
    showTitleAndCount: boolean;
    filesByMonth: any;
    months: string[];
    layouts: Layout[] = [];
    previewUrl: string;
    thumbnailLook: string;
    visibleNodes: Layout[] = [];
    containerHeight: number = 0;
    containerWidth: number = 0;
    mediaItemsCount$: ReplaySubject<string>;

    private _files: DataItem[];
    private _groupByMonth: boolean;
    private yOffset: number = 0;
    private topGutter: number = 0;

    private headerLayoutSize: number  = GROUP_BY_TITLE_OUTER_HEIGHT_AND_MARGIN;
    private marginLayoutSize: number = GROUP_HORIZONTAL_MARGIN;

    constructor(
        private layoutService: LayoutService,
        private mediaRecognizerService: MediaRecognizerService,
        scrollService: ScrollService,
        @Inject(WINDOW_TOKEN) window: Window,
        private elementRef: ElementRef
    ) {
        super(scrollService, window);
    }

    ngOnInit () {
        if (this.settings) {
            this.showRemoveButton = this.settings.showRemoveButton;
            this.isSelectable = this.settings.isSelectable;
            this.isCentered = this.settings.isCentered;
            this.mediaItemsCount$ = this.settings.itemsCount;

            if (this.value && this.value.length > 0) {
                this.mediaEntityData = this.value[0];

                if (!this.mediaItems || this.mediaItems.length === 0) {
                    this.mediaItems = this.value;
                }
            }
        }

        this.previewUrl = this.mediaRecognizerService.getPreviewUrlProperty(this.mediaEntityData.metadata.setName);
        this.thumbnailLook = this.mediaEntityData.metadata.isMultimedia ? "stretched" : null;
    }

    ngAfterViewChecked() {
        if (this.topGutter === 0) {
            this.topGutter = this.elementRef.nativeElement.getBoundingClientRect().top;
        }
    }

    onFileClick(file) {
        if (!file.data.failedValidation && !this.reorderable)
            this.clickFile.next(file);
    }

    onFileSelect(file) {
        if (!file.data.failedValidation && !this.reorderable)
            this.selectFile.next(file);
    }

    isSelected(file: DataItem): boolean {
        if (this.isSelectable) {
            return this.value.findIndex(item => item.data.Id === file.data.Id) >= 0;
        }
    }

    @HostListener("window:scroll", ["$event"])
    onWindowScroll(event) {
        // We do not want to handle the scroll when the element is not visible
        // https://developer.mozilla.org/en-US/docs/Web/API/HTMLElement/offsetParent
        if (this.wrapper && this.wrapper.nativeElement.offsetParent) {
            super.onWindowScroll(event);
        }
    }

    onResize(data) {
        if (Math.round(data.contentRect.width) !== Math.round(this.containerWidth)) {
            this.recalculateLayouts();
        }
    }

    onRemoveMediaClick(file: DataItem) {
        this.mediaItems = this.mediaItems.filter(mediaItem => mediaItem.key !== file.key);
        this.writeValue(this.mediaItems);

        if (this.mediaItemsCount$) {
            this.mediaItemsCount$.next(this.mediaItems.length.toString());
        }
    }

    protected recalculateLayout() {
        this.recalculateLayouts();
        this.scrollDispatched(this.yOffset);
    }

    protected scrollDispatched(yOffset: number = 0) {
        this.yOffset = yOffset;
        const height = this.window.document.documentElement.clientHeight;

        let layoutStartIndex = 0;
        let layoutLastIndex = this.layouts.length - 1;

        // determine the visible layouts
        this.layouts.forEach((layout, index) => {
            // check if the bottom of the layout is above the top of the viewport
            const layoutBottom = this.getLayoutTop(this.layouts, index + 1);
            if (layoutBottom < yOffset - this.topGutter) {
                layoutStartIndex = index + 1;
            }

            // check in the top of the layout is above in the bottom of the viewport
            const layoutTop = this.getLayoutTop(this.layouts, index);
            if (layoutTop < height + yOffset - this.bottomGutter) {
                layoutLastIndex = index + 1;
            }
        });

        // we should not replace the whole collection, but only add new visible layouts and remove hidden ones, to avoid flickering
        let visibleLayouts: Layout[] = deepClone(this.layouts.slice(layoutStartIndex, layoutLastIndex));
        this.visibleNodes.forEach(n => {
            const visibleLayout = visibleLayouts.find(l => l.index === n.index);
            if (visibleLayout) {
                visibleLayouts = visibleLayouts.filter(x => x.index !== visibleLayout.index);

                // update the container height in case of load more
                n.containerHeight = visibleLayout.containerHeight;
                visibleLayouts.push(n);
            }
        });

        visibleLayouts = visibleLayouts.sort((x, y) => { return x.index - y.index; });

        // determine the visible boxes in each layout
        for (let layoutIndex = layoutStartIndex; layoutIndex < layoutLastIndex; layoutIndex++) {
            const layout = visibleLayouts.find(l => l.index === layoutIndex);

            let boxStartIndex = 0;
            let boxLastIndex = layout.boxes.length - 1;

            this.layouts[layoutIndex].boxes.forEach((b, i) => {
                const layoutTop = this.getLayoutTop(this.layouts, layoutIndex);
                // check if the bottom of the box is above the top of the viewport
                const boxBottom = b.top + b.height + layoutTop + this.headerLayoutSize;
                if (boxBottom < yOffset - this.topGutter) {
                    boxStartIndex = i + 1;
                }

                // check in the top of the box is above in the bottom of the viewport
                const boxTop = b.top + layoutTop + this.headerLayoutSize;
                if (boxTop < height + yOffset - this.bottomGutter) {
                    boxLastIndex = i + 1;
                }
            });

            const visibleBoxes: Box[] = deepClone(this.layouts[layoutIndex].boxes.slice(boxStartIndex, boxLastIndex));
            this.updateVisibleBoxes(layout, visibleBoxes);
        }

        const containerHeight = this.getLayoutTop(this.layouts, layoutLastIndex) - this.marginLayoutSize;
        //set containerHeight to 0 if negative value, otherwise the html height won't get updated
        this.containerHeight = containerHeight > 0 ? containerHeight : 0;
        this.changeArrayContent(this.visibleNodes, visibleLayouts);
    }

    private updateVisibleBoxes(layout: Layout, visibleBoxes: Box[]) {
        // We should not replace the whole collection, but only add new visible boxes and remove hidden ones
        // This is done for better performance - to reuse existing components in order to avoid flickering

        // First filter to remove the boxes that should be hidden (top row when scrolling down and vise versa)
        // Then update the boxes properties with the new ones in case of resizing the window
        layout.boxes = layout.boxes
            .filter(b => visibleBoxes.find(x => x.index === b.index))
            .map(b => {
                const visibleBox = visibleBoxes.find(x => x.index === b.index);
                return Object.assign(b, visibleBox);
            });

        // Finally push the new boxes to the layout collection
        const newVisibleBoxes = visibleBoxes.filter(b => !layout.boxes.find(x => x.index === b.index));
        layout.boxes.push(...newVisibleBoxes);
    }

    private getLayoutTop(layouts: Layout[], layoutIndex: number): number {
        let top = 0;
        for (let index = 0; index < layoutIndex; index++) {
            top += layouts[index].containerHeight + this.marginLayoutSize + (this.groupByMonth ? this.headerLayoutSize : 0);
        }

        return top;
    }

    private changeArrayContent(array1: any[], array2: any[]) {
        array1.splice(0, array1.length, ...array2);
    }

    private groupFiles() {
        if (!this.mediaEntityData) {
            return;
        }

        const files = this._files;

        if (files) {
            if (this.groupByMonth) {
                this.filesByMonth = this.groupFilesByMonth(LOCALE, files);
            } else if (files.length > 0) {
                this.filesByMonth = { default: files };
            } else {
                this.filesByMonth = {};
            }
            this.months = Object.keys(this.filesByMonth);
            this.recalculateLayouts();
        }
    }

    private groupFilesByMonth(locale: string, files: DataItem[]) {
        const groups: { [key: string]: DataItem[] } = {};

        files.forEach(file => {
            const date = new Date(Date.parse(file.data[Properties.DATE_CREATED]));
            const key = date.toLocaleString(locale, { month: "long", year: "numeric" });
            const group = groups[key] || [];
            group.push(file);
            groups[key] = group;
        });

        return groups;
    }

    private recalculateLayouts() {
        // this is added because there is a call made before the files have been emited
        // due to the binding to the parent resize listener @onResize()
        // since it is layed out before this component is initialized properly
        if (!this.months && !this.mediaItems) {
            return;
        }

        const containerWidth = this.wrapper.nativeElement.offsetWidth === 0 ? this.getContainerDefaultWidth() : this.wrapper.nativeElement.offsetWidth;

        const layouts = [];

        let boxHeight: number = DEFAULT_BOX_HEIGHT;
        let boxSpacing: number = DEFAULT_BOX_SPACING;

        if (!this.mediaEntityData.metadata.isMultimedia) {
            boxHeight = DOCUMENT_ROW_HEIGHT;
            boxSpacing = DOCUMENT_BOX_SPACING;
        }

        if (this.groupByMonth && this.months.length > 0) {
            for (let index = 0; index < this.months.length; index++) {
                const month = this.months[index];
                const filesForMonth = this.filesByMonth[month];

                const layout = this.layoutService.layout(filesForMonth.map(x => cloneObject(x.data)), containerWidth, boxHeight, boxSpacing, Number.POSITIVE_INFINITY, this.mediaEntityData.metadata as MediaEntity, index);

                layouts.push(layout);
            }
        } else if (this.mediaItems) {
            const layout = this.layoutService.layout(this.mediaItems.filter(x => x && x.data).map(x => cloneObject(x.data)), containerWidth, boxHeight, boxSpacing, Number.POSITIVE_INFINITY, this.mediaEntityData.metadata as MediaEntity);

            layouts.push(layout);
        }

        this.layouts = layouts;
        const containerWidths = this.layouts.map(function(l) { return l.containerWidth; });
        this.containerWidth = Math.max(...containerWidths);
        this.scrollDispatched(this.yOffset);
    }

    private getContainerDefaultWidth(): number {
        const mainWidth: number = Math.max(this.window.document.documentElement.clientWidth, this.window.innerWidth || 0) - 100; // 1820 - 2 * 50 (padding)

        return mainWidth;
    }
}
