import { Component, Input, OnInit } from "@angular/core";
import { FormControl } from "@angular/forms";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../../../../common-constants";
import { FieldModel } from "../../../../../services/field.model";
import { createFieldModel } from "../../../fields.constants";
import { CompositeFieldsProvider } from "../../providers/fields-provider";
import { FieldTypes } from "../../services/fields-registry";

@Component({
    selector: "sf-add-many",
    templateUrl: "./add-many.component.html"
})
export class AddManyComponent implements OnInit {
    @Input() predefinedLists: { [key: string]: string[] };
    predefinedListsFieldModel: FieldModel;
    predefinedListsFormControl: FormControl;

    valuesFieldModel: FieldModel;
    value: string;

    constructor(private fieldsProvider: CompositeFieldsProvider) {}

    ngOnInit() {
        this.initPredefinedListsField();
        this.initValuesField();
    }

    onListChange(listName) {
        const selectedList = this.predefinedLists[listName];
        if (selectedList) {
            this.value = selectedList.join(stringConstants.NEWLINE);
        } else {
            this.value = null;
        }
    }

    private initValuesField() {
        this.valuesFieldModel = createFieldModel(this.fieldsProvider, null, FieldTypes.textArea, "values", undefined, {}, "or Add/paste options - one item per line");
        this.valuesFieldModel.settings.rows = 10;
        this.predefinedListsFormControl = new FormControl();
    }

    private initPredefinedListsField() {
        this.predefinedListsFieldModel = createFieldModel(this.fieldsProvider, null, FieldTypes.choiceDropDown, "predefinedList", this.value, {}, "Import predefined list");
        const choices = [{ Name: "- Select -", Value: "select" }];
        choices.push(...Object.keys(this.predefinedLists).map(x => <ChoiceItem>{ Name: x, Value: x}) as []);
        (this.predefinedListsFieldModel.settings as ChoiceSettings).choices = choices;
    }
}
