import { InjectionToken, Injectable, Optional, Inject } from "@angular/core";
import { EditMenuProvider, EditMenuSection } from "./immutable-edit-menu.component";

export const EDIT_MENU_TOKEN = new InjectionToken("edit-menu-token");

@Injectable()
export class CompositeEditMenuProvider implements EditMenuProvider {

    constructor(@Optional() @Inject(EDIT_MENU_TOKEN) private editMenuProviders: Array<EditMenuProvider>) {
    }

    getButtons(element: HTMLElement): Array<EditMenuSection> {
        if (this.editMenuProviders !== null) {
            return this.editMenuProviders
                .map(x => x.getButtons(element))
                .reduce((previous, current) => previous.concat(current));
        }
    }
}
