import { Pipe, PipeTransform } from "@angular/core";
import { LOCALE } from "../../../../../fields/common/common-constants";
import { convertIsoStringToUTCDate, getDateWithTimeZoneOffset } from "../../../../../fields/common/utils";
import { DateService } from "../services/date.service";

/**
 * Pipe for simple (only verbal for Yesterday and Today) relative date
 * Sample usage:
 *  {{ item.LastModified | sfRelativeDate }}
 *  {{ item.LastModified | sfRelativeDate:"format" }}
 * TODO: localize strings in this class
 */

@Pipe({
    name: "sfRelativeDate"
})
export class RelativeDatePipe implements PipeTransform {

    static get FULL_DATE(): string { return "full-date-long-month"; }
    static get FULL_DATE_WEEKDAY(): string { return "full-date-weekday"; }
    static get DATE_WITHOUT_YEAR(): string { return "date-without-year"; }
    static get FULL_DATE_SHORT_MONTH_AND_TIME(): string { return "full-date-short-month-and-time"; }
    static get MONTH_AND_YEAR(): string { return "month-and-year"; }
    static get MONTH_DATE_AND_YEAR(): string { return "month-date-and-year"; }
    static get TIME(): string { return "time"; }

    // special format for more detailed dates
    static get AUTO_DETAILED(): string { return "auto-detailed"; }

    private static get FULL_DATE_SHORT_MONTH(): string { return "full-date-short-month"; }
    private static get DEFAULT_DETAILED(): string { return "default-detailed"; }
    private static get MINUTES(): string { return "minutes"; }
    private static get HOURS(): string { return "hours"; }
    private static get LOCALE(): string { return LOCALE; }

    private static PREDEFINED_FORMATS =
        new Map<string, string>()
            .set(RelativeDatePipe.FULL_DATE, `on {full-date-long-month} at {time}`)
            .set(RelativeDatePipe.FULL_DATE_WEEKDAY, `{full-date-weekday} at {time}`)
            .set(RelativeDatePipe.DATE_WITHOUT_YEAR, `on {date-without-year}`)
            .set(RelativeDatePipe.FULL_DATE_SHORT_MONTH, `{full-date-short-month}`)
            .set(RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME,  `{full-date-short-month-and-time}`)
            .set(RelativeDatePipe.DEFAULT_DETAILED, `on {full-date-short-month}`)
            .set(RelativeDatePipe.MONTH_AND_YEAR, `{month-and-year}`)
            .set(RelativeDatePipe.MONTH_DATE_AND_YEAR, `{month-date-and-year}`)
            .set(RelativeDatePipe.TIME, `{time}`);

    private static DATE_TIME_FORMATS =
        new Map<string, any>()
            .set(RelativeDatePipe.FULL_DATE, {
                year: "numeric",
                month: "long",
                day: "numeric"
            })
            .set(RelativeDatePipe.FULL_DATE_WEEKDAY, {
                year: "numeric",
                month: "long",
                day: "numeric",
                weekday: "long"
            })
            .set(RelativeDatePipe.DATE_WITHOUT_YEAR, {
                month: "long",
                day: "numeric"
            })
            .set(RelativeDatePipe.FULL_DATE_SHORT_MONTH,  {
                year: "numeric",
                month: "short",
                day: "numeric"
            })
            .set(RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME,  {
                year: "numeric",
                month: "short",
                day: "numeric",
                hour: "numeric",
                minute: "numeric"
            })
            .set(RelativeDatePipe.MONTH_AND_YEAR,  {
                year: "numeric",
                month: "short"
            })
            .set(RelativeDatePipe.MONTH_DATE_AND_YEAR,  {
                year: "numeric",
                month: "long",
                day: "numeric"
            })
            .set(RelativeDatePipe.TIME,  {
                hour: "numeric",
                minute: "numeric"
            });

    private explicitFormats = [
        RelativeDatePipe.FULL_DATE,
        RelativeDatePipe.FULL_DATE_WEEKDAY,
        RelativeDatePipe.DATE_WITHOUT_YEAR,
        RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME,
        RelativeDatePipe.MONTH_AND_YEAR,
        RelativeDatePipe.MONTH_DATE_AND_YEAR,
        RelativeDatePipe.TIME
    ];

    constructor(private dateService: DateService) { /* Empty block */ }
    /**
     * Converts a date string into its corresponding simple date .
     * @param {string} date - A string representing a string representation of a Date object.
     * @param {string} dateFormat - An optional format string.
     * @param {number} timezoneOffset - An optional timezone offset, in minutes.
     * @return {string} - simple relative date.
     */
    transform(date: any, dateFormat: string = null, timezoneOffset: number = null) {
        let dateTime: Date;
        if (typeof date === "string" && timezoneOffset !== null) {
            dateTime = convertIsoStringToUTCDate(date as string);
        } else {
            dateTime = new Date(date);
        }

        const castedDate = getDateWithTimeZoneOffset(dateTime, timezoneOffset);
        const today = getDateWithTimeZoneOffset(this.dateService.getDate(), timezoneOffset);

        const oneMinute = 1000 * 60;
        const oneHour = oneMinute * 60;
        const oneDay = oneHour * 24;

        const serverTime = castedDate.getTime();
        const localTime = today.getTime();
        const timeDifference = Math.abs(localTime - serverTime);

        // if the format is set explicitly, we should honor it
        if (this.explicitFormats.indexOf(dateFormat) > -1)
            return this.format(dateFormat, castedDate);

        const requiresDetailed = dateFormat === RelativeDatePipe.AUTO_DETAILED;

        // default logic
        if (requiresDetailed) {
            if (timeDifference < oneMinute) {
                return "Just now";
            } else if (timeDifference < oneHour) {
                const minuteDifference = Math.round(Math.abs(localTime - serverTime) / oneMinute);
                castedDate.setMinutes(minuteDifference);
                return this.format(RelativeDatePipe.MINUTES, castedDate);
            } else if (timeDifference < oneDay) {
                const hourDifference = Math.round(Math.abs(localTime - serverTime) / oneHour);
                castedDate.setHours(hourDifference);
                return this.format(RelativeDatePipe.HOURS, castedDate);
            }
        }

        // same day
        if (timeDifference <= oneDay && castedDate.getDate() === today.getDate()) {
            return "Today";
        }

        // previous day
        const copiedCastedDate = new Date(castedDate.valueOf());
        copiedCastedDate.setDate(copiedCastedDate.getDate() + 1);
        if (timeDifference <= oneDay * 2 && copiedCastedDate.getDate() === today.getDate()) {
            return "Yesterday";
        }

        if (castedDate.getFullYear() === today.getFullYear() && requiresDetailed) {
            return this.format(RelativeDatePipe.DATE_WITHOUT_YEAR, castedDate);
        }

        const format = requiresDetailed ? RelativeDatePipe.DEFAULT_DETAILED : RelativeDatePipe.FULL_DATE_SHORT_MONTH;

        return this.format(format, castedDate);
    }

    private format(alias: string, date: Date): string {

        const formatted = this.tryApplyKnownDateFormatting(alias, date);
        if (formatted != null)
            return formatted;

        if (alias === RelativeDatePipe.HOURS) {
            let hourFormat = null;
            const hoursLocal = date.getHours().toLocaleString(RelativeDatePipe.LOCALE);
            if (date.getHours() === 1)
                hourFormat = `${hoursLocal} hour ago`;
            else
                hourFormat = `${hoursLocal} hours ago`;

            return hourFormat;

        } else if (alias === RelativeDatePipe.MINUTES) {
            let minuteFormat = null;
            const minutesLocale = date.getMinutes().toLocaleString(RelativeDatePipe.LOCALE);
            if (date.getMinutes() === 1)
                minuteFormat = `${minutesLocale} minute ago`;
            else
                minuteFormat = `${minutesLocale} minutes ago`;
            return minuteFormat;
        }
    }

    private tryApplyKnownDateFormatting(alias: string, date: Date): string {
        const format: string = RelativeDatePipe.PREDEFINED_FORMATS.get(alias);
        if (format) {
            const result = format.replace(new RegExp(`{(.*?)}`, "g"), (skipMatch, group) => {
                const formatObj = RelativeDatePipe.DATE_TIME_FORMATS.get(group);
                const ret = new Intl.DateTimeFormat(RelativeDatePipe.LOCALE, formatObj).format(date);
                return ret;
            });
            return result;
        }

        return null;
    }
}
