import { SettingsBase } from "./../field-settings-base";
import { ValidatorFn } from "@angular/forms";
import { VALIDATORS as CustomValidators, VALIDATOR_NAMES } from "../common/validators";

export class DateTimePickerSettings extends SettingsBase {
    public minValue: Date;
    public maxValue: Date;
    public preserveValueWithoutBrowserOffset: boolean = false;
    public dateSettingsShowTime: boolean;

    public init(metadata: any): void {
        super.init(metadata);

        this.minValue = this.minValue ? new Date(this.minValue) : null;
        this.maxValue = this.maxValue ? new Date(this.maxValue) : null;
    }

    public getValidators(metadata: any): Array<ValidatorFn> {
        const validators = super.getValidators(metadata);
        validators.push(CustomValidators[VALIDATOR_NAMES.DATE_RANGE]({
            min: this.minValue,
            max: this.maxValue
        }));

        return validators;
    }
}
