import { Type } from "@angular/core";

declare function __webpack_require__(module: number): any;

const IRIS_MANIFEST = {};

window["__iris_require__"] = (path) => {
    if (!IRIS_MANIFEST) {
        throw new Error("Manifest has not been loaded yet.");
    }

    let pathToCheck = path;

    // for legacy extensions
    if (pathToCheck.indexOf("__ivy_ngcc__") > 0) {
        pathToCheck = pathToCheck.replace("__ivy_ngcc__/", "").replace(".js", ".mjs");
    }

    else if (pathToCheck.indexOf("/rxjs/internal/") > 0) {
        pathToCheck = pathToCheck.replace("/rxjs/internal/", "/rxjs/dist/esm/internal/");
    } else if (pathToCheck.indexOf("/rxjs/_esm2015/") > 0) {
        pathToCheck = pathToCheck.replace("/rxjs/_esm2015/", "/rxjs/dist/esm/");
    }

    if (IRIS_MANIFEST.hasOwnProperty(pathToCheck)) {
        const moduleId = IRIS_MANIFEST[pathToCheck];
        return __webpack_require__(moduleId);
    }

    return __webpack_require__(path);
};

/**
 * @ExposedInApi {SitefinityExtensionStore} SitefinityExtensionStore v1/extensions-store.d.ts
 */
export class SitefinityExtensionStore {
    private extensionModules: Type<any>[] = [];

    addExtensionModule(extModule: Type<any>): void {
        this.extensionModules.push(extModule);
    }

    getExtensionModules() {
        return this.extensionModules;
    }
}

window["sitefinityExtensionsStore"] = new SitefinityExtensionStore();
