import { NgModule, Inject, NgZone } from "@angular/core";
import { Settings } from "../shared/services/settings.service";
import { stringConstants } from "../../common-constants";
import { environmentTypes } from "../../environment";
import { WINDOW_TOKEN } from "../../window.provider";
import { ContextualHelpService } from "./contextual-help.service";
import { debounceTime } from "rxjs/operators";
import { EnvironmentService } from "../shared/services/environment.service";

const CONTEXTUAL_HELP_ENDPOINT = "contextual-help";
export const LOAD_EVENT = "sf-load-tooltips";
const LOAD_EVENT_DEBOUNCE = 50;

@NgModule({
    providers: [
        ContextualHelpService
    ]
})
export class ContextualHelpModule {
    constructor(
        settings: Settings,
        contextualHelpService: ContextualHelpService,
        zone: NgZone,
        @Inject(WINDOW_TOKEN) window: Window,
        envService: EnvironmentService) {

        if (envService.getEnvironment() !== environmentTypes.integration) {
            return;
        }

        if (settings.url === stringConstants.EMPTY_STRING) {
            return;
        }

        contextualHelpService.onLoad
            .pipe(debounceTime(LOAD_EVENT_DEBOUNCE))
            .subscribe(() => {
                const event = new Event(LOAD_EVENT);
                zone.runOutsideAngular(() => window.dispatchEvent(event));
            });

        const configUrl = `${settings.url}${CONTEXTUAL_HELP_ENDPOINT}`;
        const scriptElement = window.document.createElement("script");
        scriptElement.src = configUrl;
        scriptElement.async = true;

        window.document.body.appendChild(scriptElement);
    }
}
