import { Injectable, ErrorHandler, ClassProvider, Inject } from "@angular/core";
import { Logger } from "../../shared/services/logger-source/logger";
import { NOTIFICATION_LOOKS } from "../../shared/services/notification/notification-data";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { GenericError } from "../../shared/services/errors/generic-error";
import { ErrorParserService } from "../../shared/services/errors/error-parser.service";
import { NOTIFICATION_DURATION_INFINITE } from "../../content/constants";
import { EnvironmentService } from "../../shared/services/environment.service";
import { WINDOW_TOKEN } from "../../../window.provider";
import { ERROR_EVENT_NAME } from "../../shared/rxjs-extensions/catcherror";
import { environmentTypes } from "../../../environment";

@Injectable()
export class DefaultErrorHandler implements ErrorHandler {
    private message: string;
    constructor(private logger: Logger,
                private environmentService: EnvironmentService,
                private errorParserService: ErrorParserService,
                @Inject(WINDOW_TOKEN) private window: Window,
                @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService) {
        this.window.addEventListener(ERROR_EVENT_NAME, (evt: CustomEvent) => {
            this.handleError(evt.detail);
        });
    }

    handleError(error: any) {
        const mappedError = this.errorParserService.parseError(error);
        if (mappedError instanceof GenericError) {
            let message = mappedError.message;
            const isInDevMode = this.environmentService.getEnvironment() === environmentTypes.development;
            if (isInDevMode && mappedError.stack) {
                message = mappedError.stack;
            }

            if (isInDevMode) {
                this.notificationService.publishBasicNotification({
                    look: NOTIFICATION_LOOKS.ERROR,
                    message: message,
                    closeButton: true,
                    duration: NOTIFICATION_DURATION_INFINITE
                });
            }

            // logging works though
            this.logger.error(error);

            if (this.message === message)
                return;

            this.message = message;

            if (isInDevMode) {
                this.window.setTimeout(() => {
                    // if the notification is not present it means that the application has stopped from an unrecoverable error
                    // so we show just a general notification instead with the browser API
                    if (!this.isNotificationVisible(message)) {
                        this.window.alert(message);
                    }
                }, 1000);
            }
        }
    }

    private isNotificationVisible(message: string) {
        const notificationTags = document.getElementsByTagName("sf-notification");
        let found = false;
        for (let i = 0; i < notificationTags.length; i++) {
            const notificationTag = notificationTags.item(i);
            if (notificationTag.innerHTML.indexOf(message)) {
                found = true;
                break;
            }
        }

        return found;
    }
}

export const ERROR_PROVIDER: ClassProvider = {
    provide: ErrorHandler,
    useClass: DefaultErrorHandler
};
