import { Injectable } from "@angular/core";
import { StatusLabel } from "../../../fields/resolvers/base-status.resolver";
import { ENTITY_SET } from "../modules/shared/services/metadata/meta-data-constants";
import { StatusResolver } from "../../../fields/resolvers/status.resolver";

const FLAT_ITEM_TYPE = "Flat";
const SIMPLE_LIST_NAME = "Simple";

@Injectable()
export class TaxonomyStatusResolver extends StatusResolver {
    getLabel(item: any): StatusLabel {
        let label = item && item.Type ? `${item.Type === FLAT_ITEM_TYPE ? SIMPLE_LIST_NAME : item.Type} list` : null;
        const baseLabel = super.getLabel(item);
        if (baseLabel) {

            if (label) {
                label = `${label} | ${baseLabel.Label}`;
            } else {
                label = baseLabel.Label;
            }
        }

        const statusName = item && item.Type ? item.Type : null;
        const hideIcon = !statusName;
        if (label) {
            return {
                Label: label,
                StatusName: statusName,
                HideIcon: hideIcon
            };
        }

        return null;
    }

    canProcess(setName: string): boolean {
        return setName === ENTITY_SET.CLASSIFICATIONS;
    }
}