import { AbstractControl, ValidatorFn } from "@angular/forms";

export const DIGITS_LIMIT_VALIDATOR_NAME = "digitsLimit";

export class DigitsLimit {
    static validate(maxLength: any): ValidatorFn {
        return (control: AbstractControl) => {
            if (!control.value) {
                return null;
            }

            const inputLength = control.value.toString().length;
            const isValidLength = inputLength <= maxLength;
            if (isValidLength)
                return null;

            const errorObj = {};
            errorObj[DIGITS_LIMIT_VALIDATOR_NAME] = {
                "requiredLength": maxLength
            };

            return errorObj;
        };
    }
}
