import { Injectable } from "@angular/core";
import { CanActivate, Router } from "@angular/router";

import { Settings } from "../../modules/shared/services/settings.service";
import { ROUTE_PATHS } from "../../constants/route-paths";
import { ExternalAppConfigService } from "../../app-config/external-app-config.service";

/**
 * An Angular route guard that protects routes only accessible if the AdminApp is connected to a Sitefinity instance.
 * If the no configuration is provided the user would be redirected to the configuration page.
 *
 * @ExposedInApi {ConfigurationGuard} ConfigurationGuard v1/guards/config.guard.d.ts
 */
@Injectable()
export class ConfigurationGuard implements CanActivate {
    constructor(private router: Router, private settings: Settings, private externalAppConfigService: ExternalAppConfigService) { }

    async canActivate() {
        if (this.settings.url) {
            await this.externalAppConfigService.init();
            return true;
        } else {
            this.router.navigate([ROUTE_PATHS.CONFIG]);
            return false;
        }
    }
}
