import { FieldRegistration } from "../services/fields-registry";
import { Entity } from "../../services/metadata/meta-data.store";
import { InjectionToken } from "@angular/core";

export const FIELDS_PROVIDER_TOKEN = new InjectionToken("fields-provider");

export interface FieldsRegistrationProvider {
    getFieldRegistration(fieldRegistryKey: FieldRegistryKey, entity: Entity): FieldRegistration;
}

/**
 * @ExposedInApi {FieldsProvider} FieldsProvider v1/custom-fields/fields-provider.d.ts
 */
export interface FieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration;
}

export abstract class DefaultFieldsProvider implements FieldsProvider {
    abstract overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration;
}

/**
 * Key used by the fields-provider to search for field registration.
 * @ExposedInApi {FieldRegistryKey} FieldData v1/custom-fields/field-data.d.ts
 *
 * @export
 * @interface FieldRegistryKey
 */
export interface FieldRegistryKey {
    /**
     * The name of the item's type in which the component is used. For example "blogposts".
     *
     * @type {string}
     * @memberof FieldRegistryKey
     */
    typeName: string;

    /**
     * The name of the field for which the component is used. For example "BlogPosts".
     *
     * @type {string}
     * @memberof FieldRegistryKey
     */

    fieldName: string;

    /**
     * The type of the field for which the component is used. For example "custom-wheater".
     * This is the selector property passed to the @Component() decorator.
     *
     * @type {string}
     * @memberof FieldRegistryKey
     */
    fieldType: string;
}
