import { Injectable } from "@angular/core";
import { Logger } from "../modules/shared/services/logger-source/logger";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { SitefinitySdk } from "../services/sitefinitySdk.service";

export const ADMIN_APP_CONFIG_KEY = "adminappconfig";
export const CONTENT_ITEMS_PER_PAGE_DEFAULT = 20;
export const MEDIA_ITEMS_PER_PAGE_DEFAULT = 50;
@Injectable()
export class ExternalAppConfigService {
    externalConfig: ExternalAppConfig = null;

    constructor(private logger: Logger, private sitefinitySdk: SitefinitySdk) { }

    async init(): Promise<void> {
        return new Promise((resolve) => {
            if (!this.externalConfig) {
                this.externalConfig = {
                    contentItemsPerPage: CONTENT_ITEMS_PER_PAGE_DEFAULT,
                    mediaItemsPerPage: MEDIA_ITEMS_PER_PAGE_DEFAULT
                };

                this.sitefinitySdk.instance.data({
                    siteId: null
                }).get({
                    action: `Default.GetConfigValues(configKey='${ADMIN_APP_CONFIG_KEY}')?$format=application/json;odata.metadata=none`,
                    successCb: (configValues: any) => {
                        Object.keys(configValues).forEach(configProp => {
                            const configPropLoweredFirstCase = configProp.charAt(0).toLowerCase() + configProp.slice(1);
                            const value = configValues[configProp] === stringConstants.EMPTY_STRING ? null : configValues[configProp];
                            this.externalConfig[configPropLoweredFirstCase] = JSON.parse(value);
                        });
                        resolve();
                    },
                    failureCb: error => {
                        this.logger.warn(`Failed to load AdminApp config: ${error}`);
                        resolve();
                    }
                });
            } else {
                resolve();
            }
        });
    }
}

export interface ExternalAppConfig {
    editorSettings?: any;
    customEditorSettings?: CustomEditorSettings[];
    changeOwnerAllowedTypes?: string[];
    dateTimeFormat?: DateTimeFormat;
    dynamicModuleChildListOrder?: DynamicModuleChildListOrderPair[];
    virtualization?: boolean,
    columnNamesWhitelist?: { [setName: string]: string[] },
    sectionsMenuMinColumnsNumber?: number,
    searchSettings?: any,
    linkStyles?: StyleData[],
    contentItemsPerPage?: number;
    mediaItemsPerPage?: number;
}

export interface CustomEditorSettings {
    name: string;
    contentTypes: string[];
    configuration: any;
}

export interface DateTimeFormat {
    useBrowserLocale?: boolean,
    browserLocaleFormatWidth?: string,
    timeFormat?: string,
    dateFormat?: string
}

export interface DynamicModuleChildListOrderPair {
    parentEntitySet: string,
    childEntitySets: string[];
}

export interface StyleData {
    Name: string;
    Value: string[]
}
