import { SafeValue } from "@angular/platform-browser";
import { Component, Input, ViewChild, OnInit } from "@angular/core";
import { MediaBaseComponent } from "./../media-base.component";

const EMPTY_STRING: string = "";
const CONTROLS_STRING: string = "controls";
const PLAY_DETACHED_CLASSES: string = "play-detached";

@Component({
    selector: "sf-video-player",
    templateUrl: "./video-player.component.html",
    styleUrls: ["./video-player.component.scss"]
})
export class VideoPlayerComponent extends MediaBaseComponent implements OnInit {
    @ViewChild("player", { static: false }) player;
    @Input() src: string | SafeValue;
    @Input() customThumbnailUrl: string;
    @Input() isLoaded: boolean = false;
    @Input() createThumbFromFrameIdentifier?: string;

    playable: boolean = true;
    hasThumbnailError: boolean = false;
    loaderIconLook: string = "white";

    private isPlaying = false;

    ngOnInit() {
        super.ngOnInit();
        if (this.doesNotSupportPreview) {
            this.playable = false;
        }
        this.cssClass = this.generateCssClassList();
    }

    onClick ($event) {
        if (!this.playable || this.hasError) {
            return;
        }
        if (this.player.nativeElement.paused && !this.isPlaying) {
            this.player.nativeElement.play();
        } else if (!this.player.nativeElement.paused && this.isPlaying) {
            this.player.nativeElement.pause();
        }
        this.player.nativeElement.setAttribute(CONTROLS_STRING, EMPTY_STRING);
        // made nullable since there is no event payload if it is clicked on the custom play icon
        // needed because sometimes the video will continue to play after it was paused and vice-versa
        $event?.preventDefault();
    }

    onError() {
        if (this.isLoaded) {
            this.playable = false;
        }
        super.onError();
    }

    onThumbnailError() {
        this.hasThumbnailError = true;
    }

    onLoadedMetaData() {
        this.isLoaded = true;
    }

    onPlaying() {
        this.isPlaying = true;
    }

    onPause() {
        this.isPlaying = false;
    }

    protected generateCssClassList() {
        let cls = "";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
            this.generateLoaderIconLook(this.look);
        }
        if (this.customThumbnailUrl) {
            cls += "-sf-static";
        }

        return cls;
    }

    private generateLoaderIconLook(look: string) {
        if (look.indexOf(PLAY_DETACHED_CLASSES) > -1) {
            this.loaderIconLook += " size-5xl";
        } else {
            this.loaderIconLook += " size-3xl";
        }
    }
}
