import { LinkModel } from "../../../../fields/link-selector/link-model";
import { getMatchingLinkStyle } from "../../utils";

export const DEFAULT_PLACEHOLDER_TEXT = "Add content";
const DATA_SFMARKED = "data-sf-marked";

@Component({
    selector: "sf-html",
    templateUrl: "./html.component.html",
    providers: [createValueAccessor(HtmlComponent), ImageHelper],
    styleUrls: ["./html.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class HtmlComponent extends FieldBase implements OnInit, OnDestroy {
    @ViewChild("editor", { static: true }) editor: EditorComponent;
    @Input() editorSettings: any;
    @Output() imageInsertClick = new EventEmitter<any>();
    @Output() documentInsertEditClick = new EventEmitter<any>();
    @Output() linkInsertClick = new EventEmitter<EditLinkEventData>();
    @Output() editImageLinkClick = new EventEmitter<HTMLElement>();
    @Output() cancelUpload = new EventEmitter<string>();
    @Output() retryUpload = new EventEmitter<any>();
    @Output() imageEdit = new EventEmitter<HTMLElement>();
    @Output() valueChagned = new EventEmitter<string>();

    public isValueEmpty: boolean;
    public isKeyDown: boolean = false;
    public selectedImmutable: HTMLElement;
    public editMenuButtons: ReplaySubject<Array<EditMenuSection | EditMenuButton>>;
    public toolsetPositionParams: TooltipPositionParams = {};
    public hasEditMenuButtons: boolean = false;
    public closeOnContentClick: boolean = false;
    public placeholderText: string = DEFAULT_PLACEHOLDER_TEXT;
    public isReady: boolean = false;
    public loaderHeight: number;
    public customTools = new Array<ToolBarItem>();
    public isMainHtmlField: boolean = false;

    private currentEditorRange: any;
    private initialValue: string;
    private isEditMenuClicked: boolean = false;
    private immutableToBeRemoved: HTMLElement;

    constructor(
        private modalService: ModalWindowService,
        private editMenuProvider: CompositeEditMenuProvider,
        private route: ActivatedRoute,
        private elementRef: ElementRef,
        private renderer: Renderer2,
        private imageHelper: ImageHelper,
        private createLinkHelper: CreateLinkHelper,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        @Inject(DOCUMENT_TOKEN) private documentProvider: Document,
        private configService: ExternalAppConfigService) {
        super();

        this.addCustomTools();
        this.editMenuButtons = new ReplaySubject<EditMenuSection[]>(1);
    }

    ngOnInit() {
        if (this.settings) {
            this.isMainHtmlField = this.settings.showTitle && !this.settings.visibleTitle;

            if (this.settings.entityData && this.settings.entityData.metadata) {
                this.editor.entitySetName = this.settings.entityData.metadata.setName;
            }
        }

        this.setLoaderHeight();
        if (this.settings) {
            if (this.settings.title && (!this.settings.showTitle || this.isMainHtmlField))
                this.placeholderText = this.settings.title;
            else if (this.settings.placeholder)
                this.placeholderText = this.settings.placeholder;
        }

        const readySubscription = this.editor.isReady$.pipe(
            toLoadingState(),
            delayEmission(LOADING_TIME)
        )
            .subscribe((state) => {
                if (!state.isLoading) {
                    this.isReady = true;
                }
            });

        this.registerSubscription(readySubscription);
    }

    @HostListener("window:resize")
    onResize() {
        if (this.elementRef.nativeElement.querySelectorAll(`[${SelectorConstants.SF_IMMUTABLE}]`)) {
            this.deselectSfImmutables();
        }
    }

    onFocus() {
        super.onFocus();
        this.editor.focus();
    }

    onSelect(selection) {
        this.toolsetPositionParams.mousePosition = selection.mousePosition;
        this.toolsetPositionParams.parentPosition = selection.parentPosition;

        if (selection.selectedElement) {
            let isImmutable;

            // Check if selection is immutable(needs to have toolset)
            if (selection.selectedElement.attributes) {
                isImmutable = !!selection.selectedElement.attributes[SelectorConstants.SF_IMMUTABLE];
            }

            // Check if immutable is parent of some text or something e.g. <a><em>text</em></a> <em> is selected we need the <a>
            if (!isImmutable) {
                const parentElement = selection.selectedElement.closest(`[${SelectorConstants.SF_IMMUTABLE}]`);
                selection.selectedElement = parentElement;
                isImmutable = !!parentElement;
            }

            // If no immutable is found - deselect if navigating from another immutable
            if (!isImmutable) {
                this.deselectSfImmutables();
                return;
            }

            // Logic for selecting immutable and showing his toolset
            if (this.selectedImmutable !== selection.selectedElement) {
                this.deselectSfImmutables();
                this.renderer.addClass(selection.selectedElement, SelectorConstants.SF_IMMUTABLE_SELECTED);
                this.selectedImmutable = selection.selectedElement;
                this.imageHelper.onSelectionChange(this.selectedImmutable);
                this.processImmutableSelection();
            }

            if (this.hasEditMenuButtons) {
                this.setPositionToolsetParams(this.selectedImmutable);
            }
        } else {
            this.deselectSfImmutables();
        }
    }

    writeValue(value: string, shouldProcessValue?: boolean) {
        const isNullOrInitial = this.value === null || this.value === undefined || this.initialValue === value;
        if (isNullOrInitial || shouldProcessValue) {
            if (isNullOrInitial) {
                this.initialValue = value;
            }

            value = this.editor.preProcessValue(value);
        }

        super.writeValue(value);
        this.valueChagned.emit(value);

        if (typeof this.isValueEmpty === stringConstants.TYPE_UNDEFINED) {
            this.isValueEmpty = value === null || value === stringConstants.EMPTY_STRING;
        } else if (value === null || value === stringConstants.EMPTY_STRING) {
            this.isValueEmpty = true;
            this.setLoaderHeight();
        }
        // setting this.isValueEmpty to false as expected on initial value change
        // collapses the editor, which is not by requirements
        // if at any moment we need to collapse it - this is the place
    }

    onBlur() {
        super.onBlur();

        if (this.selectedImmutable && !this.isEditMenuClicked) {
            this.deselectSfImmutables();
        }

        this.onTouchedCallback();
    }

    handleClickOutside() {
        // order matters
        this.isEditMenuClicked = false;
        this.onBlur();
        this.selectedImmutable = null;
    }

    onKeydown(event) {
        this.isKeyDown = true;

        const key = event.code;
        const commandKey = navigator.appVersion.indexOf(MAC_OS_NAME) !== -1 ? event.metaKey : event.ctrlKey;

        switch (key) {
            case commandKey && KEYBOARD_KEY_CODES.J:
                event.preventDefault();
                this.onImageInsert();
                break;
            case commandKey && KEYBOARD_KEY_CODES.K:
                event.preventDefault();
                this.onCreateLinkClick();
                break;
            case commandKey && KEYBOARD_KEY_CODES.L:
                event.preventDefault();
                this.onDocumentInsertEdit();
                break;
        }

        const selectedImmutable = this.getSelectedImmutable();
        this.selectedImmutable = selectedImmutable;

        if (!selectedImmutable) {
            return;
        }

        switch (key) {
            case commandKey && KEYBOARD_KEY_CODES.X:
                this.deselectSfImmutables();
                this.editor.delete(selectedImmutable);
                event.preventDefault();
                break;
            case KEYBOARD_KEY_CODES.BACKSPACE:
            case KEYBOARD_KEY_CODES.DELETE:
                this.deselectSfImmutables();
                this.editor.delete(selectedImmutable);
                break;
        }

        // we do not want to deselect the immutable when we press only ctrl
        // in case we are inserting link to it
        const isOptionKey = Object.values(KEYBOARD_CONTROL_KEY_CODES).find(v => v === key);
        if (!isOptionKey) {
            this.deselectSfImmutables();
        }

    }

    onKeyup(e) {
        this.isKeyDown = false;
    }

    onImageInsertViewClosed(imgData: any, isSelectedFromLibrary: boolean = false, selectedImmutable?: HTMLElement) {
        this.editor.shouldFocusEditor = true;
        if (!imgData) {
            return;
        }

        if (this.immutableToBeRemoved) {
            this.immutableToBeRemoved.remove();
        }

        const insertedEditorRange = this.currentEditorRange;

        if (imgData.failure) {
            this.imageHelper.handleImageFailedUpload(imgData);
            this.editor.triggerUserValueChanged();

            return;
        }

        if (isSelectedFromLibrary) {
            this.editor.setCurrentRange(insertedEditorRange);
            const image = this.imageHelper.createImage(imgData);
            this.editor.insertUncleanedHtml(image);
            this.editor.triggerUserValueChanged();

            return;
        }

        if (imgData.loaded === 0) {
            this.editor.setCurrentRange(insertedEditorRange);
            const image = this.imageHelper.createImage(imgData, true, imgData.imageId);
            this.editor.insertUncleanedHtml(image);
            this.editor.triggerUserValueChanged();
        } else {
            const progressBar = this.documentProvider.getElementById(imgData.imageId);
            if (imgData.Url) {
                const imageElement = progressBar.parentElement.querySelector(NODE_NAMES.IMAGE_ELEMENT);
                imageElement.setAttribute("src", imgData.Url);
                this.imageHelper.handleImageSuccessUpload(imageElement);
                // We need to force the kendoEditor to update its UndoRedoStack that is why we insert empty string.
                this.editor.inserthtml(stringConstants.EMPTY_STRING);
                this.editor.removeUndoRedoCommand(imgData.imageId, imageElement.outerHTML);
                this.editor.triggerUserValueChanged(false);
            } else {
                progressBar.setAttribute("value", `${((imgData.loaded / imgData.total) * 100).toFixed(0)}`);
            }
        }
    }

    onDocumentInsertDialogClosed(dataItem: DataItem, dynamicLink: string) {
        this.deselectSfImmutables();
        if (dataItem && dataItem.title) {
            this.editor.setCurrentRange(this.currentEditorRange);
            const anchor = document.createElement(NODE_NAMES.ANCHOR_ELEMENT);

            anchor.innerText = dataItem.title;
            anchor.setAttribute(SelectorConstants.SF_IMMUTABLE, stringConstants.EMPTY_STRING);
            anchor.setAttribute(SelectorConstants.SF_IMMUTABLE_DOCUMENT, `${true}`);
            anchor.setAttribute(ANCHOR_ATTRIBUTES.HREF, dataItem.data.Url);
            anchor.setAttribute(ANCHOR_ATTRIBUTES.TITLE, dataItem.title);
            anchor.setAttribute(ANCHOR_ATTRIBUTES.SFREF, dynamicLink);

            // Insert the HTML and trigger editor's change, so the
            // HTML can be saved.
            this.editor.insertUncleanedHtml(anchor.outerHTML);
            this.editor.triggerUserValueChanged();
        }
    }

    postProcessValue(value: any) {
        return this.editor.postProcessValue(value);
    }

    onEditImage(): void {
        this.imageEdit.emit(this.imageHelper.selectedImage);
    }

    onImageInsertDialogClosed() {
        this.onFocus();
        this.editor.triggerUserValueChanged();
    }

    onCreateLinkDataPosted(createLinkData: LinkModel, htmlToDisplay: string = undefined): void {
        if (this.immutableToBeRemoved) {
            this.immutableToBeRemoved.remove();
        }

        createLinkData.attributes = Object.assign({}, createLinkData.attributes, { [DATA_SFMARKED]: "" });
        const linkHtml: string = this.createLinkHelper.buildLink(createLinkData, htmlToDisplay);
        const markedText = this.editor.getMarkedText(this.currentEditorRange.commonAncestorContainer.innerHTML, true);

        if (markedText) {
            const replacedHtml = this.currentEditorRange.commonAncestorContainer.innerHTML.replace(markedText, linkHtml);

            if (this.currentEditorRange.commonAncestorContainer.tagName === NODE_NAMES.ANCHOR_ELEMENT) {
                this.currentEditorRange.commonAncestorContainer.outerHTML = replacedHtml;
            } else {
                this.currentEditorRange.commonAncestorContainer.innerHTML = replacedHtml;
            }

            const linkNode = this.currentEditorRange.commonAncestorContainer.querySelector(`[${DATA_SFMARKED}]`);

            const currentRange = this.editor.getCurrentRange();

            if (linkNode !== null) {
                currentRange.setStart(linkNode.childNodes[0], 0);
            }

            currentRange.collapse(true);
            this.editor.setCurrentRange(currentRange);
            (linkNode as HTMLElement).removeAttribute(DATA_SFMARKED);

        } else {
            this.editor.setCurrentRange(this.currentEditorRange);
            this.editor.insertUncleanedHtml(linkHtml);
        }

        this.editor.triggerUserValueChanged();
    }

    onCreateLinkDataCanceled() {
        this.currentEditorRange.commonAncestorContainer.innerHTML = this.editor.cleanMarkers(this.currentEditorRange.commonAncestorContainer.innerHTML);
        this.editor.setCurrentRange(this.currentEditorRange);
    }

    onCreateLinkDialogClosed(): void {
        this.deselectSfImmutables();
        this.editor.shouldFocusEditor = true;
        this.onFocus();
    }

    onCancelUpload(elementId: string) {
        this.cancelUpload.emit(elementId);
    }

    onRetryUpload(image: any) {
        this.retryUpload.emit(image);
    }

    onEditImageDone(editedImageData: [{ [key: string]: any }], thumbnails: any) {
        this.editor.shouldFocusEditor = true;
        this.imageHelper.onEditDone(editedImageData, thumbnails);
        this.editor.triggerUserValueChanged();
        this.deselectSfImmutables();
    }

    onEditMenuClickIn() {
        this.isEditMenuClicked = true;
    }

    onEditMenuClickOut() {
        this.isEditMenuClicked = false;
    }

    onEditMenuClose(shouldClose: boolean) {
        if (shouldClose) {
            this.hasEditMenuButtons = false;
            this.editMenuButtons.next(null);
        }
    }

    getSelectedImmutable(): HTMLElement {
        const selectedElement = this.elementRef.nativeElement.querySelector(`.${SelectorConstants.SF_IMMUTABLE_SELECTED}`);
        return selectedElement;
    }

    onSerializedImmutables(event: string): void {
        this.writeValue(event);
    }

    deselectSfImmutables() {
        const immutables = this.elementRef.nativeElement.querySelectorAll(`[${SelectorConstants.SF_IMMUTABLE}]`);
        for (let i = 0; i < immutables.length; i++) {
            this.renderer.removeClass(immutables[i], SelectorConstants.SF_IMMUTABLE_SELECTED);
        }

        this.selectedImmutable = null;

        if (!this.isEditMenuClicked) {
            this.processImmutableSelection();
        }
    }

    private processImmutableSelection(): void {
        let buttons: EditMenuSection[] = [];
        const editMenuButtons = this.getButtons(this.selectedImmutable);
        const externalCustomButtons = this.editMenuProvider.getButtons(this.selectedImmutable);

        if (editMenuButtons) {
            buttons = buttons.concat(editMenuButtons);
        }

        if (externalCustomButtons && externalCustomButtons.length > 0) {
            buttons = buttons.concat(externalCustomButtons);
        }

        if (buttons.length > 0) {
            this.hasEditMenuButtons = true;
            this.activateEditButtons(buttons);
        } else {
            this.hasEditMenuButtons = false;
            this.editMenuButtons.next(null);
        }
    }

    private onImageInsert() {
        this.immutableToBeRemoved = this.selectedImmutable;
        this.currentEditorRange = this.editor.getCurrentRange();

        const imageId = this.imageHelper.getRandomStringId(this.settings.key);
        this.editor.hideToolbar();
        this.imageInsertClick.emit(imageId);
    }

    private onDocumentInsertEdit() {
        this.currentEditorRange = this.editor.getCurrentRange();
        this.editor.hideToolbar();

        let dynamicLink = null;
        if (this.selectedImmutable) {
            this.setRange(this.selectedImmutable);

            if (this.selectedImmutable.attributes[ANCHOR_ATTRIBUTES.SFREF]) {
                dynamicLink = this.selectedImmutable.attributes[ANCHOR_ATTRIBUTES.SFREF].value;
            }
        }

        this.documentInsertEditClick.emit(dynamicLink);
        this.deselectSfImmutables();
    }

    private onInsertHorizontalRule() {
        this.editor.inserthtml({ value: "<hr />" });
        this.editor.triggerUserValueChanged();
        this.deselectSfImmutables();
    }

    private onEmbedCodeViewerOpen() {
        const insertHandler = (data: ClickData): ClickResult => {
            const component = data.component as EmbedMediaComponent;
            return new ClickResult(component.isValid, component.isValid);
        };

        const selectedImmutable = this.getSelectedImmutable();
        const buttons = new Array<Button>(new ConfirmButton("Insert", insertHandler), new CancelButton());
        const componentData: ComponentData = {
            type: EmbedMediaComponent,
            properties: {
                selectedImmutable: selectedImmutable
            }
        };
        const currentEditorRange = this.editor.getCurrentRange();
        const dialogData = new DialogData(componentData, (context) => this.onEmbedCodeViewDone(context, currentEditorRange), buttons, null, "-sf-mt-3xs");
        this.modalService.setMapping(dialogData);

        this.modalService.open(this.route);
        this.editor.hideToolbar();
    }

    private onEmbedCodeViewDone(context: ClosingContext, currentEditorRange: any): void {
        const embedMediaInstance = context.component as EmbedMediaComponent;
        const selectedImmutable = embedMediaInstance.selectedImmutable;
        this.editor.shouldFocusEditor = true;

        if (context.type === ClosingContextType.ButtonClicked) {
            const buttonResult = context.data as ClickResult;
            if (buttonResult.data) {
                const addTrailingBreaks = selectedImmutable ? false : true;
                let embedMediaValue = embedMediaInstance.getEmbedMediaHtml();
                embedMediaValue = embedMediaInstance.wrapEmbedMedia(embedMediaValue, addTrailingBreaks);

                // if the user is currently editing an embed media
                if (selectedImmutable) {
                    selectedImmutable.outerHTML = embedMediaValue;

                    // First change the immutable outerHTML, then set the editor current range
                    this.editor.setCurrentRange(currentEditorRange);
                } else {
                    // if this is a newly created embed media
                    this.editor.setCurrentRange(currentEditorRange);
                    this.editor.insertEmbed(embedMediaValue);
                }

                this.editor.embedValueChanged();
            }
        }

        // TODO: Fix focusing the editor after Embed dialog is closed
        // this.editor.focus();
    }

    private stripImmutableClass(elemet: HTMLElement) {
        elemet.classList.remove(SelectorConstants.SF_IMMUTABLE);
    }

    private onViewCodeOpen(): void {
        const modalWindowClass = "-prompt -no-padding-horizontal";
        const viewCode = "Code view";
        const fieldContent = this.getValue();

        const insertHandler = (data: ClickData): ClickResult => {
            const component = data.component as ViewCodeComponent;
            return new ClickResult(component.value, true);
        };

        const buttons = new Array<Button>(new ConfirmButton(SelectorConstants.DONE, insertHandler, "default"));

        const componentData: ComponentData = {
            type: ViewCodeComponent,
            properties: {
                source: fieldContent
            }
        };

        const dialogData = new DialogData(componentData, (context) => {
            this.editor.shouldFocusEditor = true;
            if (context.data) {
                this.deselectSfImmutables();

                this.editor.executeInDeserializationZone(() => {
                    this.writeValue(this.getUpdatedHtml(context));
                });
            }
        }, buttons, modalWindowClass, null, true, null, null, true, false, true);
        dialogData.heading.title = viewCode;
        dialogData.hasTopToolbar = true;

        this.editor.hideToolbar();
        this.modalService.setMapping(dialogData);
        this.modalService.open(this.route);
    }

    private getUpdatedHtml(context: any): string {
        // we need to remove the sfref values of a tags whose href has been changed so that when users
        // manipulate the url segments in the code view, Sitefinity can regenerate the sfref if applicable
        const hrefRegex = "href=([\"'])(.*?)\\1";
        const sfrefRegex = "sfref=([\"'])(.*?)\\1";
        const oldHtml: string = context.component.source;
        let updatedHtml: string = context.data.data;
        const oldLinksWithSfRef = HtmlHelper.getElementsByTypeAndAttribute(oldHtml, "a", false, "sfref");
        const newLinksWithSfRef = HtmlHelper.getElementsByTypeAndAttribute(updatedHtml, "a", false, "sfref");

        if ((oldLinksWithSfRef?.length === 0 || newLinksWithSfRef?.length === 0) || (oldLinksWithSfRef === newLinksWithSfRef)) {
            return updatedHtml;
        } else {
            const modifiedTags = newLinksWithSfRef.filter(x => !oldLinksWithSfRef.includes(x));
            modifiedTags.forEach((value, i) => {

                const currentSfRef = value.match(sfrefRegex);
                if (currentSfRef?.length) {
                    const oldLink = oldLinksWithSfRef.find(x => x.indexOf(currentSfRef[0]));
                    const currentHref = value.match(hrefRegex)[0];
                    const oldHref = oldLink.match(hrefRegex)[0];

                    if (currentHref !== oldHref) {
                        const newLink = value.replace(new RegExp(sfrefRegex), "");
                        updatedHtml = updatedHtml.replace(value, newLink);
                    }
                }
            });

            return updatedHtml;
        }
    }

    private addCustomTools(): void {
        const toolsData: CustomToolsData = this.getCustomToolsData();

        for (let i = 0; i < toolsData.toolsCount; i += 1) {
            const tool: ToolBarItem = new ToolBarItem(toolsData.names[i], toolsData.selectors[i], toolsData.execFunctions[i]);
            if (toolsData.ordinals[i]) {
                tool.ordinal = toolsData.ordinals[i];
            }

            this.customTools.push(tool);
        }
    }

    private getCustomToolsData(): CustomToolsData {
        // When adding new custom tool add it in
        // EditorComponent -> getToolsNames -> tools collection aswell
        // so that when a custom tool is added through the extenstions
        // combined with ordinal property the initial order of the tools will not break
        const customToolsNames: string[] = [
            "insertImage",
            "insertDocument",
            "horizontalRule",
            "embed",
            "createLink",
            "tableWizard",
            "html",
            "justifyLeft",
            "justifyCenter",
            "justifyRight"
        ];
        const customToolsSelectors: string[] = [
            SelectorConstants.INSERT_IMAGE,
            SelectorConstants.INSERT_DOCUMENT,
            SelectorConstants.HORIZONTAL_RULE,
            "Embed",
            "Create a link",
            TABLE_WIZARD_TITLE,
            "View HTML",
            BUTTON_TOOLTIPS.ALIGN_LEFT,
            BUTTON_TOOLTIPS.ALIGN_CENTER,
            BUTTON_TOOLTIPS.ALIGN_RIGHT
        ];
        const customToolsExecFunctions: any[] = [
            this.onImageInsert.bind(this),
            this.onDocumentInsertEdit.bind(this),
            this.onInsertHorizontalRule.bind(this),
            this.onEmbedCodeViewerOpen.bind(this),
            this.onCreateLinkClick.bind(this),
            this.onTableWizardClick.bind(this),
            this.onViewCodeOpen.bind(this),
            this.editorJustifyLeft.bind(this),
            this.editorJustifyCenter.bind(this),
            this.editorJustifyRight.bind(this)
        ];
        const customToolsOrdinal: number[] = [
            undefined,
            undefined,
            undefined,
            undefined,
            undefined,
            undefined,
            9999,
            undefined,
            undefined,
            undefined
        ];
        const data: CustomToolsData = new CustomToolsData(customToolsNames, customToolsSelectors, customToolsExecFunctions, customToolsOrdinal);

        return data;
    }

    private onTableWizardClick() {
        this.editor.onTableWizardOpen();
    }

    private editorJustifyLeft() {
        this.editor.justifyLeft(this.selectedImmutable);
        this.alignEditableButton();
    }

    private editorJustifyCenter() {
        this.editor.justifyCenter(this.selectedImmutable);
        this.alignEditableButton();
    }

    private editorJustifyRight() {
        this.editor.justifyRight(this.selectedImmutable);
        this.alignEditableButton();
    }

    private openUrl(url: string) {
        this.windowProvider.open(url, NEW_TAB_TARGET);
        this.deselectSfImmutables();
    }

    private setRange(element: HTMLElement) {
        const selection = this.windowProvider.getSelection();
        const range = this.documentProvider.createRange();
        range.setStartBefore(element);
        range.setEndAfter(element);
        selection.removeAllRanges();
        selection.addRange(range);
        this.editor.setCurrentRange(range);
        this.currentEditorRange = this.editor.getCurrentRange();
    }

    private onCreateLinkClick() {
        if (this.selectedImmutable instanceof HTMLImageElement) {
            this.editImageLink(this.selectedImmutable);

            return;
        }

        let selectedText: string = stringConstants.EMPTY_STRING;
        let selectedTextHtml: string = null;

        if (this.selectedImmutable && !(this.selectedImmutable instanceof HTMLAnchorElement)) {
            this.currentEditorRange = this.editor.getCurrentRange();
            this.editor.setCurrentRange(this.currentEditorRange);
            this.linkInsertClick.emit({ selectedText });
            this.immutableToBeRemoved = this.selectedImmutable;

            return;
        }

        if (this.selectedImmutable) {
            this.currentEditorRange = this.editor.getCurrentRange();
            this.setRange(this.selectedImmutable);
            selectedText = this.selectedImmutable.innerText;
            selectedTextHtml = this.selectedImmutable.innerHTML;
        } else {
            const selectedTextData = this.editor.getSelectedText();
            const range = selectedTextData.range;

            if (range.startContainer === range.endContainer && range.startContainer instanceof HTMLAnchorElement) {
                this.selectedImmutable = range.startContainer;
            }

            selectedText = selectedTextData.selectedText;
            selectedTextHtml = selectedTextData.selectedTextWrapper;
            this.currentEditorRange = selectedTextData.range;
        }

        this.editor.setCurrentRange(this.currentEditorRange);

        this.linkInsertClick.emit({ selectedText, isInEditMode: !!this.selectedImmutable, selectedTextHtml, selectedElement: this.selectedImmutable });
        this.editor.hideToolbar();
    }

    private unlink(element?: HTMLElement) {
        this.setRange(element);
        this.editor.unlink(this.selectedImmutable);
        this.selectedImmutable = null;
        this.stripImmutableClass(element);
        this.deselectSfImmutables();
    }

    private applyStylesToLink() {
        if (this.selectedImmutable) {
            const linkStylesFromConfig: StyleData[] = this.configService.externalConfig?.linkStyles || [];
            const noStyle: StyleData = { Name: "No style", Value: [] };
            const allStyles: StyleData[] = [noStyle].concat(linkStylesFromConfig);
            const initialStyle: StyleData = getMatchingLinkStyle(allStyles, this.selectedImmutable.classList.value.split(stringConstants.INTERVAL));

            const section = new EditMenuSection(
                new DropdownEditMenuButton("dropdown-edit-menu-button", "Link style", allStyles.map(x => x.Name), initialStyle.Name, (selection) => {
                    if (this.selectedImmutable) {
                        const newClasses = allStyles.find(x => x.Name === selection).Value;
                        this.createLinkHelper.addClassesToAnchor(newClasses, this.selectedImmutable as HTMLAnchorElement);
                        this.setRange(this.selectedImmutable);
                    }
                })
            );

            this.editMenuButtons.next([section]);
        }
    }

    private getButtons(element: HTMLElement): Array<EditMenuSection> {
        if (element && element.attributes["custom-edit-menu"]) {
            return null;
        }

        if (element instanceof HTMLImageElement && element.attributes[SelectorConstants.SF_IMMUTABLE]) {
            const editImageButtons = this.createEditImageButtons(element);
            return editImageButtons;
        }

        if (element instanceof HTMLAnchorElement && element.attributes[SelectorConstants.SF_IMMUTABLE_DOCUMENT]) {
            const editLinkButtons = this.createEditDocumentButtons(element);
            return editLinkButtons;
        }

        if (element instanceof HTMLAnchorElement && !(element.firstElementChild instanceof HTMLImageElement)) {
            const editLinkButtons = this.createEditLinkButtons();
            return editLinkButtons;
        }

        if (element && element.querySelectorAll(SelectorConstants.SF_DISABLE_LINK_EVENT)) {
            const editEmbedMediaButtons = this.createEditEmbedMediaButtons(element as HTMLDivElement);
            return editEmbedMediaButtons;
        }

        return null;
    }

    private createEditLinkButtons(): Array<EditMenuSection> {
        const elementHref = (<HTMLAnchorElement>this.selectedImmutable).getAttribute(ANCHOR_ATTRIBUTES.HREF);
        return [
            new EditMenuSection(new EditMenuTextButton(BUTTON_NAMES.EXTERNAL_LINK, () => { this.openUrl(elementHref); }, elementHref, BUTTON_TOOLTIPS.EXTERNAL_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.PENCIL, () => { this.onCreateLinkClick(); }, BUTTON_TOOLTIPS.EDIT_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.APPLY_STYLE, () => { this.applyStylesToLink(); }, BUTTON_TOOLTIPS.APPLY_STYLE)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.UNLINK, () => { this.unlink(this.selectedImmutable); }, BUTTON_TOOLTIPS.UNLINK))
        ];
    }

    private createEditDocumentButtons(element: any): Array<EditMenuSection> {
        const elementHref = (<HTMLAnchorElement>this.selectedImmutable).getAttribute(ANCHOR_ATTRIBUTES.HREF);
        return [
            new EditMenuSection(new EditMenuTextButton(BUTTON_NAMES.EXTERNAL_LINK, () => { this.openUrl(elementHref); }, elementHref, BUTTON_TOOLTIPS.EXTERNAL_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.PENCIL, () => { this.onDocumentInsertEdit(); }, BUTTON_TOOLTIPS.EDIT_DOCUMENT)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.UNLINK, () => { this.unlink(this.selectedImmutable); }, BUTTON_TOOLTIPS.UNLINK))
        ];
    }

    private editImageLink(element: HTMLElement) {
        const parentElement = element.parentElement as HTMLAnchorElement;
        const hasAnchorSet = parentElement && parentElement.attributes[SelectorConstants.SF_IMMUTABLE] && parentElement.href;

        if (hasAnchorSet) {
            this.setRange(parentElement);
        }

        this.editImageLinkClick.emit(element);
        this.editor.hideToolbar();
    }

    private createAlignButtons(element: HTMLDivElement) {
        return new EditMenuSection(
            new EditMenuButton(BUTTON_NAMES.ALIGN_LEFT, () => {
                this.editorJustifyLeft();
            }, BUTTON_TOOLTIPS.ALIGN_LEFT),
            new EditMenuButton(BUTTON_NAMES.ALIGN_CENTER, () => {
                this.editorJustifyCenter();
            }, BUTTON_TOOLTIPS.ALIGN_CENTER),
            new EditMenuButton(BUTTON_NAMES.ALIGN_RIGHT, () => {
                this.editorJustifyRight();
            }, BUTTON_TOOLTIPS.ALIGN_RIGHT)
        );
    }

    private createEditEmbedMediaButtons(element: HTMLDivElement) {
        const editImageButtons = [
            this.createAlignButtons(element),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.PENCIL, () => {
                this.onEmbedCodeViewerOpen();
            }, BUTTON_TOOLTIPS.EDIT_EMBED))
        ];

        return editImageButtons;
    }

    private createEditImageButtons(element: any) {
        let anchor;

        if (element.parentElement && element.parentElement.attributes[SelectorConstants.SF_IMMUTABLE]) {
            anchor = <HTMLAnchorElement>element.parentElement;
        }

        const changeToEditImageLinkScreen = () => this.editMenuButtons.next(editImageLinkButtons);
        const changeToEditImageScreen = () => this.editMenuButtons.next(editImageButtons);
        let anchorHref;

        if (anchor && anchor.href) {
            anchorHref = anchor.href;
        }

        const editImageLinkButtons = [
            new EditMenuSection(new EditMenuTextButton(BUTTON_NAMES.EXTERNAL_LINK, () => window.open(anchorHref, NEW_TAB_TARGET), anchorHref, BUTTON_TOOLTIPS.EXTERNAL_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.PENCIL, () => this.editImageLink(element), BUTTON_TOOLTIPS.EDIT_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.UNLINK, () => {
                anchorHref = null;
                this.removeImageLink(anchor, element);
                changeToEditImageScreen();
                this.deselectSfImmutables();
            }, BUTTON_TOOLTIPS.UNLINK))
        ];
        const editImageButtons = [
            this.createAlignButtons(element),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.LINK, () => !anchorHref ? this.editImageLink(element) : changeToEditImageLinkScreen(), BUTTON_TOOLTIPS.EDIT_LINK)),
            new EditMenuSection(new EditMenuButton(BUTTON_NAMES.PENCIL, () => {
                const image = (this.imageHelper.selectedImage || anchor.firstChild) as HTMLImageElement;
                this.editor.hideToolbar();
                this.imageEdit.emit(image);
            }, BUTTON_TOOLTIPS.EDIT_IMAGE))
        ];

        return editImageButtons;
    }

    private removeImageLink(anchor: HTMLAnchorElement, image: HTMLImageElement) {
        anchor.removeAttribute(ANCHOR_ATTRIBUTES.HREF);
        anchor.removeAttribute(ANCHOR_ATTRIBUTES.TARGET);
        anchor.removeAttribute(ANCHOR_ATTRIBUTES.TITLE);
        this.imageHelper.unwrap(anchor);

        transferKendoAlignInlineStyles(anchor, image);
    }

    private setPositionToolsetParams(element: any) {
        if (!element) {
            return;
        }

        const elementRects = element.getClientRects();
        let position = NotificationPosition.Down;
        let top = element.offsetTop;
        let left = element.offsetLeft;
        let right = element.offsetLeft + element.offsetWidth;
        let bottom = element.offsetTop + element.offsetHeight;
        let height = element.offsetHeight;
        let width = element.offsetWidth;

        if (element.nodeName !== NODE_NAMES.ANCHOR_ELEMENT) {
            position = NotificationPosition.Up;
        }

        if (this.toolsetPositionParams.mousePosition && element.nodeName === NODE_NAMES.ANCHOR_ELEMENT) {
            for (let i = 0; i < elementRects.length; i++) {
                const elementRect = elementRects[i];

                if (this.isPointInsideRect(this.toolsetPositionParams.mousePosition, elementRect)) {
                    top = elementRect.top - this.toolsetPositionParams.parentPosition.top;
                    left = elementRect.left - this.toolsetPositionParams.parentPosition.left;
                    right = left + elementRect.width;
                    bottom = top + elementRect.height;
                    height = elementRect.height;
                    width = elementRect.width;
                }
            }
        }

        this.toolsetPositionParams.elementPosition = {
            top,
            left,
            right,
            bottom,
            height,
            width,
            x: undefined,
            y: undefined,
            toJSON: () => JSON.stringify(this)
        };

        this.toolsetPositionParams.position = position;

        // Needed to trigger onChange
        const toolsetPositionParamsCopy = Object.assign({}, this.toolsetPositionParams);
        this.toolsetPositionParams = toolsetPositionParamsCopy;
    }

    private isPointInsideRect(point: Point, rect: ClientRect): boolean {
        if ((point.x > rect.left && point.x < rect.right) && (point.y > rect.top && point.y < rect.bottom)) {
            return true;
        }
        return false;
    }

    private alignEditableButton() {
        this.setPositionToolsetParams(this.selectedImmutable);
        this.processImmutableSelection();
    }

    private activateEditButtons(sections: Array<EditMenuSection>) {
        const activeToolName = this.editor.getActiveAlignToolName(this.selectedImmutable);

        sections.forEach(section => {
            if (section.buttons.length > 1) {
                section.buttons.forEach((btn) => {
                    if (btn.name === activeToolName) {
                        btn.isActive = true;
                    }
                });
            }
        });

        this.editMenuButtons.next(sections);
    }

    private setLoaderHeight() {
        // Some adjustment is needed in order the screen not to twitch
        const adjusmentOffset = 5;
        this.loaderHeight = EDITOR_COLLAPSE_HEIGHT + (adjusmentOffset * 5) - 1;

        if (this.isValueEmpty) {
            this.loaderHeight = EDITOR_MAIN_EMPTY_HEIGHT + adjusmentOffset;
        }

        if (!this.isMainHtmlField && this.isValueEmpty) {
            this.loaderHeight = EDITOR_EMPTY_HEIGHT + adjusmentOffset;
        }
    }
}

export interface EditLinkEventData {
    selectedText: string;
    isInEditMode?: boolean;
    selectedTextHtml?: string;
    selectedElement?: HTMLElement;
}

export class CustomToolsData {
    toolsCount: number;

    constructor(public names: string[], public selectors: string[], public execFunctions: any[], public ordinals: number[]) {
        this.toolsCount = names.length;
    }
}
