import { map, debounceTime } from "rxjs/operators";
import { OnInit, OnDestroy, Component, ViewChild, EventEmitter, Output, Inject } from "@angular/core";
import { BehaviorSubject, Observable, Subject, ReplaySubject } from "rxjs";

import { ModalWindowService } from "../shared/services/modal-window.service";
import { ScrollService } from "../../services/scroll.service";
import { MESSAGES } from "./file-picker.messages";
import { getFormattedTypeName, isFileTypeAllowed, cloneInstance } from "../../utils";

import { LibraryStore } from "./services/library.store";
import { SHOW_BUTTONS, MODAL_WINDOW_NOTIFICATION_FILTER } from "../shared/components/modal-window/modal-window.component";
import { QUERY_PARAMS, FILTER_TYPES, SORT_ORDER, NOTIFICATION_DURATION_INFINITE } from "../content/constants";
import { MediaValidationHelper } from "./media-validation-helper";
import { stringConstants, ANY_SITE_SOURCE_PROVIDER } from "../../common-constants";
import { ProviderTabSelectorComponent, PROVIDER_TAB_CSS_CLASS } from "../content/dynamic-modules/components/provider-tab-selector/provider-tab-selector.component";
import { ProviderStore } from "../content/dynamic-modules/services/provider-store";
import { EntityData, DataItem, FailedMediaValidation } from "../content/dynamic-modules/interfaces";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";
import { NotificationService, NOTIFICATION_SERVICE } from "../shared/services/notification/notification.service";
import { NOTIFICATION_LOOKS } from "../shared/services/notification/notification-data";
import { ComponentData, SfRxBase } from "@progress/sitefinity-component-framework";
import { Selector, SelectorEventArgs, SfTabsComponent } from "@progress/sitefinity-component-framework";

export const TAB_NAMES = {
    recent: "recent",
    libraries: "libraries",
    selected: "selected"
};

export const PAGE_SIZE = 50;
export const FILE_SELECT = "fileSelect";

export const SEARCH_DEBOUNCE_TIME = 500;

@Component({
    templateUrl: "./file-select.component.html"
})
export class FileSelectComponent extends SfRxBase implements OnInit, OnDestroy {
    @ViewChild("mainTabs", { static: true }) mainTabs: SfTabsComponent;
    @Output() onUploadFiles: EventEmitter<FileList>;
    uploadEnabled: boolean = true;
    fromUpload: boolean = null;
    allowCreate: boolean = true;
    currentLibraryId: string;
    parentLibraryId: string;
    parentLibraryTitle: string = "All libraries";
    showParentLibrary: boolean = true;
    value: DataItem[];
    multiple: boolean;
    mediaEntityData: EntityData;
    acceptableMediaTypes: Array<string>;
    acceptableFileTypes: Array<string>;
    mediaFilterEnabled: boolean;
    maxSize: number;
    showTranslations: boolean = false;
    useLiveData: boolean;
    /** HACK: this is not resolved through angular`s DI on purpose.
     * This component is meant to be used as child component for the FilePickerComponent.
     * The FilePickerComponent uses a fresh instance of the store each time it is created.
     * Since this component is created from the parent via the modal service,
     * DI is not iherited, hence the FilePickerComponent`s singleton will not be resolved here.
     * Instead, if we were to use DI here we would get another global singleton store.
     * But it is necessary that the same store instance from the parent FilePickerComponent
     *  is used here so the parent passes it as a property value.
     * P.S. If we were not to use the modal service we could make this component a part of
     * the parent`s template which would keep angulars hierarchical DI, but that would make
     * the parent and the child using the same url, which is a constraint from UX requirements.
     */
    store: LibraryStore;
    libraries: Observable<DataItem[]>;
    recentFiles: Observable<DataItem[]>;
    translations: Subject<DataItem[]>;
    culturesByFile: Subject<{ [key: string]: string[] }>;
    files: Observable<DataItem[]>;
    folders: BehaviorSubject<DataItem[]>;
    searchTerm: string;
    recentSearchTerm: string;
    messages: any;
    path = [];
    searchInProgress: boolean;
    acceptFileTypes: string;
    formattedTypeName: string;
    fileUploadErrorMessages: string[];

    librariesTabComponentData: ComponentData;
    librariesTabLook: string;
    showProviderSelector: boolean;
    showBreadcrumb: boolean = false;
    isNonTranslatedSelectable: boolean = true;

    private hasLoadedRecentFiles = false;
    private search$: Subject<string> = new Subject<string>();
    private searchRecent$: Subject<string> = new Subject<string>();
    private mediaEntity: MediaEntity;
    private defaultSortingParam = { [QUERY_PARAMS.SORT]: `${FILTER_TYPES.LAST_MODIFIED} ${SORT_ORDER.DESCENDING}` };

    constructor(
        protected scrollService: ScrollService,
        private modalService: ModalWindowService,
        private mediaValidationHelper: MediaValidationHelper,
        private providersStore: ProviderStore,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService
    ) {
        super();
        this.onUploadFiles = new EventEmitter<FileList>();
    }

    ngOnInit() {
        this.mediaEntity = this.mediaEntityData.metadata as MediaEntity;
        this.toggleShowBreadcrumb();
        this.initializeParentLibrary();

        this.libraries = this.store.libraries;

        this.recentFiles = this.getFilteredFiles(this.store.recentFiles, this.mediaFilterEnabled, this.acceptableFileTypes, this.maxSize);
        const recentFilesSubscription = this.store.recentFiles.subscribe(() => {
            this.hasLoadedRecentFiles = true;
            this.modalService.sendCommand(FILE_SELECT, {
                name: SHOW_BUTTONS,
                data: true
            });
        });
        this.registerSubscription(recentFilesSubscription);

        this.files = this.getFilteredFiles(this.store.files, this.mediaFilterEnabled, this.acceptableFileTypes, this.maxSize);
        const filesSubscription = this.files.subscribe(() => {
            this.searchInProgress = false;
        });
        this.registerSubscription(filesSubscription);

        this.translations = new ReplaySubject<DataItem[]>(1);
        this.culturesByFile = new ReplaySubject<{ [key: string]: string[] }>(1);
        if (this.showTranslations) {
            const mediaEntityDataItem = this.mediaEntityData as DataItem;
            const emptyDataItem = DataItem.fromEntityData(null, this.mediaEntityData);
            const badges = {};

            this.store.getMediaFileLinks(mediaEntityDataItem).subscribe(result => {
                const dataItems = result.value.map((item) => {
                    badges[item.Id] = item.Cultures;
                    return DataItem.fromEntityData(item, emptyDataItem);
                });

                this.translations.next(dataItems);
                this.culturesByFile.next(badges);
            });

            const translationsSubscription = this.translations.subscribe(() => {
                this.searchInProgress = false;
            });

            this.registerSubscription(translationsSubscription);
        } else {
            const mediaEntityDataItem = this.mediaEntityData as DataItem;
            if (mediaEntityDataItem.key) {
                this.store.getMediaFileLinks(mediaEntityDataItem, true).subscribe(result => {
                    if (result.value.length > 0) {
                        const cultures = result.value[0].Cultures;
                        if (cultures && cultures.length > 0) {
                            const culturesCount = cultures.length;
                            const translationMessagePart = culturesCount > 1 ? "translations are" : "translation is";
                            const pronounMessagePart = culturesCount > 1 ? "them" : "it";
                            this.notificationService.publishBasicNotification({
                                message: `${culturesCount} more ${translationMessagePart} using current file and any changes will be applied to ${pronounMessagePart} too.`,
                                look: NOTIFICATION_LOOKS.WARNING,
                                duration: NOTIFICATION_DURATION_INFINITE,
                                filterParam: MODAL_WINDOW_NOTIFICATION_FILTER,
                                closeButton: false
                            });
                        }
                    }
                });
            }
        }

        this.folders = this.store.folders;
        this.messages = this.multiple ? MESSAGES.multiple : MESSAGES.single;
        this.formattedTypeName = this.formattedTypeName ? this.formattedTypeName : getFormattedTypeName({ plural: this.mediaEntity.setName, singular: this.mediaEntity.singularName.toLowerCase() }, this.multiple, true);

        this.acceptFileTypes = this.mediaValidationHelper.getAcceptableFileTypes(this.acceptableFileTypes);

        if (this.mediaEntityData.provider === ANY_SITE_SOURCE_PROVIDER) {
            if (this.showProviderSelector) {
                this.librariesTabLook = PROVIDER_TAB_CSS_CLASS;
                this.librariesTabComponentData = {
                    type: ProviderTabSelectorComponent,
                    properties: {
                        entitySetName: this.mediaEntity.setName
                    },
                    afterComponentInit: (component: Selector) => {
                        component.onChange.subscribe((item: SelectorEventArgs) => {
                            this.mediaEntityData.metadata.selectedProvider = item.tabValue;
                            this.mediaEntity.selectedProvider = item.tabValue;
                            if (this.parentLibraryId) {
                                this.store.getFolderById(this.mediaEntityData, this.parentLibraryId).subscribe(x => this.parentLibraryTitle = x.data.Title);
                            }

                            this.store.loadRecentFiles(this.mediaEntityData, this.recentSearchTerm, PAGE_SIZE, undefined, undefined, this.useLiveData).subscribe();
                            this.onBackClick();
                        });
                        component.onInit.subscribe((item: SelectorEventArgs) => {
                            this.mediaEntityData.metadata.selectedProvider = item.tabValue;
                            this.mediaEntity.selectedProvider = item.tabValue;
                            this.initializeParentLibrary();

                            this.store.loadRecentFiles(this.mediaEntityData, this.recentSearchTerm, PAGE_SIZE, undefined, undefined, this.useLiveData).subscribe();
                            this.store.loadLibraries(this.mediaEntityData, this.searchTerm, PAGE_SIZE, this.currentLibraryId, this.defaultSortingParam, true, this.useLiveData);
                        });
                    }
                };
            } else {
                this.providersStore.getProviders(this.mediaEntity.setName).subscribe(providers => {
                    const defaultProvider = providers.find(x => x.isDefault);
                    if (defaultProvider) {
                        this.mediaEntityData = {
                            metadata: this.mediaEntityData.metadata,
                            culture: this.mediaEntityData.culture,
                            provider: defaultProvider.name
                        };
                        this.initializeParentLibrary();

                        this.store.loadRecentFiles(this.mediaEntityData, this.recentSearchTerm, PAGE_SIZE, undefined, undefined, this.useLiveData).subscribe();
                        this.store.loadLibraries(this.mediaEntityData, this.searchTerm, PAGE_SIZE, this.currentLibraryId, this.defaultSortingParam, true, this.useLiveData);
                    }
                });
            }
        } else {
            this.store.loadRecentFiles(this.mediaEntityData, this.recentSearchTerm, PAGE_SIZE, undefined, undefined, this.useLiveData).subscribe();
            this.store.loadLibraries(this.mediaEntityData, this.searchTerm, PAGE_SIZE, this.currentLibraryId, this.defaultSortingParam, true, this.useLiveData);
        }

        this.initializeSearch();
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.notificationService.close(MODAL_WINDOW_NOTIFICATION_FILTER);
    }

    onUploadClick(files: FileList) {
        const isValid = this.mediaValidationHelper.validate(this.mediaEntity, Array.from(files), false);
        this.fileUploadErrorMessages = this.mediaValidationHelper.getErrorMessages();

        if (isValid) {
            this.onUploadFiles.emit(files);
        }
    }

    onSelectSelectedTab() {
        this.scrollService.scrollToTop(false);
        this.mainTabs.selectTabByName(TAB_NAMES.selected);
    }

    isSelected(tabName: string) {
        if (this.mainTabs) {
            return this.mainTabs.isSelected(tabName);
        }

        return false;
    }

    onSearch(searchTerm: string = stringConstants.EMPTY_STRING) {
        if (searchTerm === stringConstants.EMPTY_STRING && this.currentLibraryId) {
            // when search term is cleared or submitted empty, everything from the current library should be loaded, if such is present
            this.store.getFoldersAndContent(this.mediaEntityData, this.currentLibraryId, PAGE_SIZE, undefined, undefined, undefined, undefined, undefined, undefined, true, undefined, this.useLiveData);
            return;
        }

        this.search$.next(searchTerm);
    }

    onSearchRecent(searchTerm: string = stringConstants.EMPTY_STRING) {
        this.searchRecent$.next(searchTerm);
    }

    onSelectFile(file: DataItem) {
        if (this.isNonTranslatedSelectable || file.data.isTranslated) {
            if (this.multiple) {
                const index = this.value.findIndex(item => item.data.Id === file.data.Id);

                if (index < 0) {
                    this.value.push(file);
                } else {
                    this.value.splice(index, 1);
                }
            } else {
                this.value = [file];
            }
        }
    }

    onSelectLibrary(library: DataItem) {
        this.path = [library];
        this.folders.next([]);

        this.currentLibraryId = library.data.Id;

        this.searchTerm = null;

        this.store.getFoldersAndContent(this.mediaEntityData, library.data.Id, PAGE_SIZE, null, this.defaultSortingParam, undefined, undefined, undefined, undefined, true, undefined, this.useLiveData);
        this.toggleShowBreadcrumb();
    }

    onSelectFolder(folder: DataItem) {
        const index = this.path.findIndex(item => item.data.Id === folder.data.Id);

        if (index >= 0) {
            this.path = this.path.slice(0, index + 1);
        } else {
            this.path.push(folder);
        }

        this.folders.next([]);
        this.currentLibraryId = folder.data.Id;
        this.searchTerm = null;

        this.store.getFoldersAndContent(this.mediaEntityData, folder.data.Id, PAGE_SIZE, null, this.defaultSortingParam, undefined, undefined, undefined, undefined, true, undefined, this.useLiveData);
        this.toggleShowBreadcrumb();
    }

    onBackClick() {
        this.searchTerm = null;
        this.folders.next([]);

        if (this.parentLibraryId) {
            this.store.getFoldersAndContent(this.mediaEntityData, this.parentLibraryId, PAGE_SIZE, null, this.defaultSortingParam, undefined, undefined, undefined, undefined, true, undefined, this.useLiveData);
            this.currentLibraryId = this.parentLibraryId;
        } else {
            this.currentLibraryId = null;
            this.store.loadLibraries(this.mediaEntityData, null, PAGE_SIZE, null, this.defaultSortingParam, true, this.useLiveData);
        }

        this.toggleShowBreadcrumb();
    }

    onRemoveFile(file: DataItem) {
        const index = this.value.findIndex(item => item.data.Id === file.data.Id);

        this.value.splice(index, 1);
    }

    onCancelClick() {
        this.modalService.close();
    }

    requestMoreItems() {
        this.loadMore();
    }

    onScroll(event) {
        const bottom = (event.target.scrollHeight - event.target.scrollTop) <= event.target.offsetHeight;

        if (bottom) {
            this.loadMore();
        }
    }

    toggleShowBreadcrumb(): void {
        // show breadcrumb only if not on top level of library hierarchy
        this.showBreadcrumb = this.parentLibraryId !== this.currentLibraryId;
    }

    private initializeSearch() {
        const searchSubscription = this.search$.pipe(
            debounceTime(SEARCH_DEBOUNCE_TIME))
            .subscribe(searchTerm => {
                this.searchInProgress = true;

                const search = searchTerm ? searchTerm.trim() : searchTerm;
                this.store.search(this.mediaEntityData, search, PAGE_SIZE, true, this.showParentLibrary, !this.showParentLibrary ? this.parentLibraryId : undefined);
            });

        this.registerSubscription(searchSubscription);

        const searchRecentSubscription = this.searchRecent$.pipe(
            debounceTime(SEARCH_DEBOUNCE_TIME))
            .subscribe((searchTerm) => {
                const search = searchTerm ? searchTerm.trim() : searchTerm;
                this.store.searchRecent(this.mediaEntityData, search, PAGE_SIZE, this.useLiveData, !this.showParentLibrary ? this.parentLibraryId : undefined);
            });

        this.registerSubscription(searchRecentSubscription);
    }

    private loadMore() {
        if (this.isSelected(TAB_NAMES.recent) && this.hasLoadedRecentFiles) {
            this.store.loadMoreRecent(this.mediaEntityData, this.recentSearchTerm, PAGE_SIZE);
        } else if (this.isSelected(TAB_NAMES.libraries)) {
            this.store.loadMore(this.mediaEntityData, this.searchTerm, PAGE_SIZE, false, false, undefined, this.defaultSortingParam, true);
        }
    }

    private markTranslated(item: DataItem): DataItem {
        const culture = item.culture;
        const data = cloneInstance(item.data);
        data.isTranslated = culture ? item.data.AvailableLanguages.some(lang => lang === culture) : true;
        return DataItem.fromEntityData(data, item);
    }

    private markAvailable(f: DataItem, acceptableFileTypes: Array<string>, maxSize: number, mediaFilterEnabled: boolean): DataItem {
        const validation: FailedMediaValidation = {};
        let isValid = true;
        if (mediaFilterEnabled && !isFileTypeAllowed(f.data.Extension ? f.data.Extension.substr(1) : stringConstants.EMPTY_STRING, acceptableFileTypes)) {
            validation.acceptableFileTypes = this.mediaValidationHelper.getAcceptableFileTypes(acceptableFileTypes);
            isValid = false;
        }

        if (maxSize > 0 && f.data.TotalSize > maxSize) {
            validation.maxSize = maxSize;
            isValid = false;
        }

        const data = cloneInstance(f.data);
        data.failedValidation = isValid ? null : validation;
        return DataItem.fromEntityData(data, f);
    }

    private setProvider(item: DataItem): DataItem {
        return DataItem.from(item.data, item.metadata, this.mediaEntity.selectedProvider || this.mediaEntityData.provider, item.culture);
    }

    private getFilteredFiles(files: ReplaySubject<DataItem[]>, mediaFilterEnabled: boolean, acceptableFileTypes: Array<string>, maxSize: number): Observable<DataItem[]> {
        return files.pipe(
            map(files => files.map(item => this.markTranslated(item))),
            map(files => files.map(item => this.setProvider(item))),
            map(files => files.map(item => this.markAvailable(item, acceptableFileTypes, maxSize, mediaFilterEnabled)))
        );
    }

    private initializeParentLibrary(): void {
        if (this.parentLibraryId) {
            this.store.getFoldersAndContent(this.mediaEntityData, this.parentLibraryId, PAGE_SIZE, undefined, undefined, undefined, undefined, undefined, undefined, true, undefined, this.useLiveData);
            this.store.getFolderById(this.mediaEntityData, this.parentLibraryId).subscribe(x => this.parentLibraryTitle = x.data.Title);
        }
    }
}
