import { Injectable, Inject } from "@angular/core";
import { Actions, createEffect, ofType, ROOT_EFFECTS_INIT } from "@ngrx/effects";
import { COLUMN_ACTIONS } from "../actions/actions.columns";
import { AppStore } from "../app-store";
import { mergeMap, withLatestFrom, map } from "rxjs/operators";
import { of } from "rxjs";
import { COLUMN_SELECTORS } from "../selectors/selectors.columns";
import { LOCAL_STORAGE, StorageService } from "../../../modules/shared/services/storage.service";
import { KEYS } from "../../../modules/shared/services/settings-keys";
import { ColumnState } from "../schemas/schema.columns";

@Injectable()
export class ColumnEffects {
    constructor(
        private actions$: Actions,
        @Inject(LOCAL_STORAGE) private storage: StorageService,
        private store: AppStore
    ) { }

    public readonly init = createEffect(() => {
        return this.actions$.pipe(
            ofType(ROOT_EFFECTS_INIT),
            map(() => {
                const expandedColumnsPerEntity: { [key: string]: string[] } = JSON.parse(this.storage.getItem(KEYS.EXPANDED_COLUMNS.PER_ENTITY_SET)) || {};
                const expandedColumnsPerItem: { [key: string]: { [key: string]: { [key: string]: boolean } } } = JSON.parse(this.storage.getItem(KEYS.EXPANDED_COLUMNS.PER_ITEM)) || {};

                if (expandedColumnsPerEntity || expandedColumnsPerItem) {
                    const data: ColumnState = {
                        expandedColumnsPerEntity,
                        expandedColumnsPerItem
                    };

                    return COLUMN_ACTIONS.setState({ data });
                }

                return { type: "noop" };
            })
        )
    });

    public readonly onToggleExpandedPerEntity = createEffect(() => {
        return this.actions$.pipe(
            ofType(COLUMN_ACTIONS.toggleExpandedPerEntity),
            withLatestFrom(this.store.pipe(COLUMN_SELECTORS.expandedColumnsPerEntity)),
            mergeMap(data => {
                return of(this.setExpandedColumnsPerEntity(data[1]));
            })
        );
    }, { dispatch: false });

    public readonly onToggleExpandedPerItem = createEffect(() => {
        return this.actions$.pipe(
            ofType(COLUMN_ACTIONS.toggleExpandedPerItem),
            withLatestFrom(this.store.pipe(COLUMN_SELECTORS.expandedColumnsPerItem)),
            mergeMap(data => {
                return of(this.setExpandedColumnsPerItem(data[1]));
            })
        );
    }, { dispatch: false });

    private setExpandedColumnsPerItem(data: { [key: string]: { [key: string]: { [key: string]: boolean } } }) {
        if (data) {
            this.storage.setItem(KEYS.EXPANDED_COLUMNS.PER_ITEM, JSON.stringify(data));
        }
        return { type: "noop" };
    }

    private setExpandedColumnsPerEntity(data: { [key: string]: string[] }) {
        if (data) {
            this.storage.setItem(KEYS.EXPANDED_COLUMNS.PER_ENTITY_SET, JSON.stringify(data));
        }
        return { type: "noop" };
    }
}
