import { Component, Input, OnInit, Output, EventEmitter } from "@angular/core";
import { FormGroup } from "@angular/forms";
import { MediaHelpers } from "../../../src/app/modules/libraries/services/media.helpers";
import { ENTITY_SET } from "../../../src/app/modules/shared/services/metadata/meta-data-constants";
import { Entity, MetadataStore } from "../../../src/app/modules/shared/services/metadata/meta-data.store";
import { DataItem } from "../../../src/app/modules/content/dynamic-modules/interfaces";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    templateUrl: "./document.component.html",
    selector: "sf-document"
})
export class DocumentComponent extends SfRxBase implements OnInit {
    @Input() multiple: boolean;
    @Input() item: any;

    @Output() onTitleBlur = new EventEmitter<any>();

    documentThumbnailIcon: string;
    documentThumbnailIconLook: string;
    documentStatusLook: string;
    inGridView: boolean = false;
    displayTitle: string;

    protected entity: Entity;
    protected dataItem: DataItem;
    private setName = ENTITY_SET.DOCUMENTS;

    constructor(private metadataStore: MetadataStore) {
        super();
    }

    ngOnInit() {
        this.documentThumbnailIcon = MediaHelpers.getDocumentThumbnailIcon(this.item.extension);
        this.documentThumbnailIconLook = "size-4xl " + (this.item.isTranslated === false ? "lighter" : "light");
        this.documentStatusLook = this.item.isTranslated === false ? "dimmed" : null;
        this.displayTitle = this.item.title || this.item.name;

        this.entity = this.metadataStore.getEntity(this.setName);
        const data = this.item.data ? this.item.data : this.item;
        this.dataItem = DataItem.from(data, this.entity, this.entity?.selectedProvider, null);

        const form: FormGroup = this.item.form;
        if (form) {
            const subscription = form.get("Title").valueChanges.subscribe(value => {
                this.item.title = value;
                this.displayTitle = value;
            });
            this.registerSubscription(subscription);
        }
    }

    handleTitleBlur() {
        this.onTitleBlur.emit();
        this.item.errors = !this.item.title.trim() ? ["Enter Title"] : [];
    }
}
