import { Component, Input, OnInit } from "@angular/core";
import { TextFieldComponent } from "./text-field.component";

@Component({
    selector: "sf-multi-value-text-field",
    templateUrl: "./multi-value-text-field.component.html"
})
export class MultiValueTextFieldComponent extends TextFieldComponent implements OnInit {
    @Input() additionalValuesPropertyPaths: string[];
    @Input() additionalValuesCss: string;
    @Input() valueCss: string;
    additionalValues: string[] = [];

    ngOnInit() {
        super.ngOnInit();
        const dataItem = this.context.dataItem;
        const model = this.context.model;

        const evaledValue: string = dataItem.data[model.name];
        if (evaledValue && this.additionalValuesPropertyPaths) {
            this.additionalValuesPropertyPaths.forEach(additionalValuePath => {
                const additionalValue = this.getPropertyValue(evaledValue, additionalValuePath);
                if (additionalValue) {
                    this.additionalValues.push(additionalValue);
                }
            });
        }
    }
}
