import { createReducer, on, combineReducers } from "@ngrx/store";
import { MOBILE_PREVIEW_ACTIONS } from "../actions/actions.mobile-preview";
import { MobilePreviewState } from "../schemas/schema.mobile-preview";
import { initialState } from "../store-schema";

const mobilePreviewChangeWidthReducer = createReducer<number>(initialState.mobilePreview.width,
    on(MOBILE_PREVIEW_ACTIONS.changeWidth, (state, { width: width }) => {
        return width;
    })
);

export const mobilePreviewReducer = combineReducers<MobilePreviewState>({
    width: mobilePreviewChangeWidthReducer
});
