import { Component, Input, OnInit } from "@angular/core";
import { BulkOperationsNotificationComponent } from "./bulk-operations-notification.component";
import { stringConstants } from "../../../../../common-constants";

@Component({
    selector: "sf-bulk-change-template-notification",
    templateUrl: "./bulk-change-template-notification.component.html"
})
export class BulkChangeTemplateNotificationComponent extends BulkOperationsNotificationComponent implements OnInit {
    @Input() message: string;

    failedItemsMessage: string;

    ngOnInit() {
        super.ngOnInit();

        if (this.operationFailed || this.operationPartiallySucceeded) {
            const words = this.message.split(stringConstants.INTERVAL);
            this.failedItemsMessage = words.splice(-2).join(stringConstants.INTERVAL);
            this.message = words.join(stringConstants.INTERVAL);
            this.failedItemsComponentTitle = "Pages failed to change template";
        }
    }
}
