import { Component } from "@angular/core";
import { createValueAccessor } from "../field-base";
import { ChoiceMultipleComponent } from "./choice-multiple.component";

const MULTIPLE_CHOICE_EMPTY_VALUE: string = "0";

@Component({
    selector: "sf-multiple-choice-readonly",
    templateUrl: "./choice-multiple-readOnly.component.html",
    providers: [createValueAccessor(ChoiceMultipleReadOnlyComponent)]
})
export class ChoiceMultipleReadOnlyComponent extends ChoiceMultipleComponent {

    hasEmptyValue(): boolean {
        if (this.value === MULTIPLE_CHOICE_EMPTY_VALUE)
            return true;
        return false;
    }
}
