import { Component, Input, OnInit } from "@angular/core";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { Observable } from "rxjs";
import { BUNDLE_DATA_OPERATIONS } from "../../../../services/bundle-data.service";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";

export const SHARED_NOTIFICATION = " is shared. Any changes will be reflected on the following ";
@Component({
    selector: "sf-content-blocks-notification",
    templateUrl: "./content-blocks-notification.component.html"
})
export class ContentBlocksNotificationComponent extends SfRxBase implements OnInit {
    @Input() item$: Observable<DataItem>;
    sharedContentMessage: string;
    sharedInCount: number;
    sharedInLoading: boolean;
    isFromEditScreen: boolean;

    constructor(private dynamicItemService: DynamicItemService) {
        super();
    }

    ngOnInit() {
        this.registerSubscription(this.item$.subscribe(item => {
            if (!item.data) {
                return;
            }

            this.initContentMessage(item);
            this.initSharedInCount(item);
        }));
    }

    private initContentMessage(item: DataItem) {
        let startOfContentMessage = `"${item.title}"`;
        if (this.isFromEditScreen) {
            startOfContentMessage = "This content";
        }

        this.sharedContentMessage = `${startOfContentMessage}${SHARED_NOTIFICATION}`;
    }

    private initSharedInCount(item: DataItem) {
        this.registerSubscription(this.dynamicItemService.executeBoundFunction<{ value: number }>(item, BUNDLE_DATA_OPERATIONS.SHARED_IN_COUNT)
            .subscribe(result => {
                this.sharedInCount = result.value;
                this.sharedInLoading = false;
            }));
    }
}
