import { Component, OnInit } from "@angular/core";
import { FieldBase } from "../../../../fields/field-base";

@Component({
    selector: "sf-dropdown-selector-readonly",
    templateUrl: "./parent-selector.component.readonly.html"
})
export class ParentSelectorReadonlyComponent extends FieldBase implements OnInit {
    parentName: string;

    ngOnInit() {
        this.parentName = this.value;

        if (this.settings.dataItem && this.settings.dataItem.metadata.isMedia) {
            this.parentName = this.settings.dataItem.data.LibraryTitle;
        }
    }
}
