import { FieldBase } from "../../../../../../../fields";
import { Directive, OnInit } from "@angular/core";
import { AppStore } from "../../../../../services/store/app-store";
import { FIELDS_SELECTORS } from "../../../../../services/store/selectors/selectors.fields";
import { Entity, MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { combineLatest, from, ReplaySubject } from "rxjs";
import { BackendTweaksStore } from "../../../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { VIEW_NAME } from "../../../../content/constants";
import { FIELD_HIDDEN } from "../../../../../../../fields/common/common-constants";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";

@Directive()
export abstract class ListFieldMappingsBase<TSettings extends FieldMappingsSettings = FieldMappingsSettings> extends FieldBase<TSettings> implements OnInit {
    readonly NO_VIEW_LABEL = "No fields defined for the selected template. Contact your administrator.";
    readonly NO_TYPE_LABEL = "Content type not set";

    fields$ = new ReplaySubject<FieldInfo[]>(1);
    public viewNameExists: boolean = false;
    public contentType: string;
    protected fields: FieldInfo[] = [];

    constructor(
        private tweaksStore: BackendTweaksStore,
        private store: AppStore,
        private metaDataStore: MetadataStore) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        const changeViewName$ = this.store.pipe(FIELDS_SELECTORS.changeViewName);
        const changeItemType$ = this.store.pipe(FIELDS_SELECTORS.changeItemType);

        const subscription = combineLatest([changeViewName$, changeItemType$]).subscribe(([viewName, selectorData]) => {
            if (viewName) {
                const viewMetaData = JSON.parse(this.settings.viewMetaData);
                const definedListFields = viewMetaData[viewName];
                this.viewNameExists = definedListFields && definedListFields.length > 0;

                if (this.viewNameExists) {
                    this.contentType = selectorData?.itemType;
                    if (selectorData && selectorData.itemType) {
                        from(this.tweaksStore.initializeForm(this.contentType, VIEW_NAME.EDIT, null, null, null)).subscribe(() => {
                            const formTweaks = this.tweaksStore.getFormByType(this.contentType, VIEW_NAME.EDIT);
                            const entity = this.metaDataStore.getEntity(this.contentType);
                            this.initFields();
                            definedListFields.forEach((field, index) => {
                                const fieldInfo = new FieldInfo();
                                fieldInfo.Title = field.fieldTitle;
                                fieldInfo.Type = field.fieldType;
                                fieldInfo.Ordinal = index + 1;
                                const suitableProperties = Object.getOwnPropertyNames(entity.properties)
                                    .filter(p => {
                                        const hiddenValue = entity.properties[p][FIELD_HIDDEN];
                                        if (typeof hiddenValue !== "undefined") {
                                            return !hiddenValue;
                                        }

                                        return true;
                                    })
                                    .filter(p => this.metaTypeEqualsFieldType(field.fieldType, entity, p))
                                    .map(p => {
                                        const tweak = formTweaks.find(x => x.name === p);
                                        return { Name: tweak?.title || p, Value: p};
                                    });

                                if (suitableProperties && suitableProperties.length > 0) {
                                    this.modifyFieldInfo(fieldInfo, entity, suitableProperties);
                                }

                                this.fields.push(fieldInfo);
                            });

                            this.updateFields();
                        });
                    } else {
                        this.initFields();
                        definedListFields.forEach((field, index) => {
                            const fieldInfo = new FieldInfo();
                            fieldInfo.Title = field.fieldTitle;
                            fieldInfo.Type = field.fieldType;
                            fieldInfo.Ordinal = index + 1;
                            this.fields.push(fieldInfo);
                        });

                        this.updateFields();
                    }
                }
            } else {
                this.viewNameExists = false;
            }
        });

        this.registerSubscription(subscription);
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }

    protected abstract modifyFieldInfo(fieldInfo: FieldInfo, entity: Entity, suitableFields: { Name: string, Value: string }[]);

    protected initFields() {
        this.fields = [];
    }

    protected metaTypeEqualsFieldType(fieldType: string, entity: Entity, fieldName: string): boolean {
        if (this.checkSimpleTypesMatch(fieldType, entity.properties[fieldName]))
            return true;
        if (fieldType.startsWith("RelatedData")) {
            const partnerName = this.metaDataStore.getRelationshipPartnerTypeName(entity, fieldName);
            if (partnerName)
                return !this.metaDataStore.getEntityByFullTypeName(partnerName).isMedia;
        } else if (fieldType.startsWith("Related")) {
            const partnerName = this.metaDataStore.getRelationshipPartnerTypeName(entity, fieldName);
            if (partnerName)
                return this.metaDataStore.getEntityByFullTypeName(partnerName).isMedia;
        }

        return false;
    }

    private updateFields() {
        const sortedFields = this.fields.sort((x, y) => {
            if (x.Ordinal === undefined) {
                return -1;
            }

            if (y.Ordinal === undefined) {
                return 1;
            }

            return x.Ordinal - y.Ordinal;
        });

        this.fields$.next(sortedFields);
    }

    private checkSimpleTypesMatch(fieldType: string, metadata: any): boolean {
        if (fieldType === "ShortText" || fieldType === "LongText" || fieldType === "Text") {
            return this.checkTextTypesMatch(fieldType, metadata);
        } else if (fieldType === "Boolean" || fieldType === "YesNo") {
            return metadata.type === "boolean" || (Array.isArray(metadata.type) && metadata.type.includes("boolean"));
        } else if (fieldType === "DateTime") {
            return (metadata.type === "string" || (Array.isArray(metadata.type) && metadata.type.includes("string"))) && metadata.format === "date-time";
        } else if (fieldType === "Number") {
            return metadata.type === "number" || (Array.isArray(metadata.type) && metadata.type.includes("number"));
        } else if (fieldType === "Classification") {
            return metadata.type === "array" && metadata["Telerik.Sitefinity.V1.TaxonomyUrl"];
        } else if (fieldType === "Address") {
            return metadata.$ref === "#/definitions/Telerik.Sitefinity.GeoLocations.Model.Address";
        }

        return false;
    }

    private checkTextTypesMatch(fieldType: string, metadata: any): boolean {
        if (fieldType === "ShortText" || fieldType === "LongText") {
            return (metadata.type === "string" || (Array.isArray(metadata.type) && metadata.type.includes("string"))) && metadata["Telerik.Sitefinity.V1.FieldType"] === fieldType;
        } else if (fieldType === "Text") {
            return (metadata.type === "string" || (Array.isArray(metadata.type) && metadata.type.includes("string"))) && (metadata["Telerik.Sitefinity.V1.FieldType"] === "ShortText" || metadata["Telerik.Sitefinity.V1.FieldType"] === "LongText");
        }
    }
}

export class FieldMappingsSettings extends SettingsBase {
    public viewMetaData: any;
}

export class FieldInfo {
    Title: string;
    Type: string;
    Settings: SettingsBase;
    Ordinal: number;
}
