import { Component, OnInit, Inject } from "@angular/core";
import { map } from "rxjs/operators";
import { createValueAccessor } from "../../../../../../fields/field-base";
import { UrlNameComponent } from "../../../urlName/urlName.component";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { Properties } from "../../fields.constants";
import { stringConstants } from "../../../../common-constants";
import { SanitizeService } from "../../../../services/sanitize.service";
import { StatusType } from "../../../../../../fields/field-status";
import { VALIDATOR_NAMES } from "../../../../../../fields/common/validators";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { StructureUrlNameSettings } from "./structure-urlName.settings";
import { UrlNameSettings } from "../../../urlName/urlName-settings";
import { BehaviorSubject, Observable } from "rxjs";

@Component({
    selector: "sf-url-name-structure",
    templateUrl: "./structure-urlName.component.html",
    styleUrls: ["./structure-urlName.component.scss"],
    providers: [createValueAccessor(UrlNameComponent)]
})
export class StructureUrlNameComponent extends UrlNameComponent implements OnInit {
    public isCustomStructure: boolean = false;
    public urlStructureSettings: StructureUrlNameSettings;
    public extension: string = null;
    protected parentUrlPath$: Observable<string>;

    private parentUrlPath = new BehaviorSubject<string>(stringConstants.EMPTY_STRING);

    constructor(private sanitizeService: SanitizeService, @Inject(WINDOW_TOKEN) private window: Window) {
        super();
        this.parentUrlPath$ = this.parentUrlPath.pipe(map(x => x + "/"));
    }

    ngOnInit() {
        this.urlStructureSettings = this.settings as StructureUrlNameSettings;

        super.ngOnInit();

        if (!this.settings.dataItem || this.settings.dataItem.isEmpty) {
            this.parentUrlPath.next(stringConstants.EMPTY_STRING);
        } else {
            this.fetchAndSetParentUrl(this.settings.dataItem, this.settings.dataItem.data[Properties.PARENT_ID]);
        }
    }

    handleParentChange(parent: any) {
        this.fetchAndSetParentUrl(this.settings.dataItem, parent);
    }

    writeValue(value: string) {
        if (value) {
            if (value.startsWith("~")) {
                this.isCustomStructure = true;
                value = value.substring(1);
            }

            let regex: RegExp = null;
            const settings = this.settings as StructureUrlNameSettings;
            if (this.isCustomStructure) {
                regex = settings.customStructureRegex;
            } else {
                regex = settings.regex;
            }

            let status: StatusType = StatusType.ErrorCleared;
            let valid = regex.test(value);
            const onlySlashesRegex = new RegExp(/^\/+$/, "g");

            if (valid && this.isCustomStructure && onlySlashesRegex.test(value.trim())) {
                valid = false;
            }
            if (!valid)
                status = StatusType.Error;

            this.window.setTimeout(() => {
                this.emitStatus({
                    type: status,
                    data: {
                        [VALIDATOR_NAMES.PATTERN]: true
                    }
                });
            }, 0);
        }

        super.writeValue(value);
    }

    onEditStructureClick() {
        const currentVal = this.getValue();

        this.isCustomStructure = !this.isCustomStructure;

        if (this.isCustomStructure) {
            let resultString = this.parentUrlPath.getValue();
            if (currentVal) {
                resultString += "/" + currentVal;
            }

            return this.writeValue(resultString);
        }

        return this.restoreStructure();
    }

    postProcessValue(value: string) {
        if (this.isCustomStructure) {
            let symbolToPrepend = "~";
            if (value.startsWith("~")) {
                symbolToPrepend = stringConstants.EMPTY_STRING;
            } else if (!value.startsWith("/")) {
                symbolToPrepend = "~/";
            }

            value = `${symbolToPrepend}${value}`;
        }

        return value;
    }

    private restoreStructure() {
        const settings = this.settings as UrlNameSettings;
        let titleVal = this.settings.dataItem.data ? this.settings.dataItem.data[this.settings.dataItem.metadata.defaultFieldName] : this.getValue();

        titleVal = this.sanitizeService.sanitizeValue(titleVal, settings.sanitizeRegex, settings.sanitizeRegexReplaceCharacter);

        this.writeValue(titleVal);
    }

    private fetchAndSetParentUrl(dataItem: DataItem, parentId: string): void {
        if (!parentId) {
            this.parentUrlPath.next(stringConstants.EMPTY_STRING);
            return;
        }

        this.urlStructureSettings.getUrlStructureData(dataItem)
            .subscribe(data => {
                this.extension = data.extension;
                this.parentUrlPath.next(data.parentUrl);

                if (data.editableUrl) {
                    this.writeValue(data.editableUrl);
                }
            });
    }
}
