import { Injectable } from "@angular/core";
import { MEDIA_CONTENT_TYPES } from "./../media-content.types";
import { MediaEntity } from "../../shared/services/metadata/meta-data.store";
const justifiedLayout = require("justified-layout");

const DOCUMENT_BOX_WIDTH: number = 200;
const DOCUMENT_BOX_HEIGHT: number = 260;

export const DEFAULT_BOX_HEIGHT: number = 150;
export const DEFAULT_SMALL_BOX_HEIGHT: number = 100;
export const DEFAULT_BOX_SPACING: number = 10;
export const DOCUMENT_BOX_SPACING: number = 30;
export const DOCUMENT_ROW_HEIGHT: number = DOCUMENT_BOX_HEIGHT + DOCUMENT_BOX_SPACING;

const DEFAULT_IMAGE_WIDTH: number = 160;
const DEFAULT_VIDEO_WIDTH: number = 300;
const DEFAULT_VIDEO_HEIGHT: number = 205;
const DEFAULT_SIZE = {width: DEFAULT_SMALL_BOX_HEIGHT, height: DEFAULT_SMALL_BOX_HEIGHT};

function mapForLayout(mediaItem: any, mediaType?: MediaEntity, targetRowHeight?: number) {
    let dimensions = DEFAULT_SIZE;
    if (mediaType) {

        switch (mediaType.singularName.toLowerCase()) {
            case MEDIA_CONTENT_TYPES.document.single:
                dimensions = {
                    width: DOCUMENT_BOX_WIDTH,
                    height: DOCUMENT_BOX_HEIGHT
                };
                break;
            case MEDIA_CONTENT_TYPES.image.single:
                let mediaWidth = mediaItem.Width || mediaItem.width || DEFAULT_IMAGE_WIDTH;
                let mediaHeight = mediaItem.Height || mediaItem.height || DEFAULT_IMAGE_WIDTH;

                if (mediaWidth < mediaHeight && targetRowHeight) {
                    mediaWidth = targetRowHeight;
                    mediaHeight = targetRowHeight;
                }

                dimensions = {
                    width: mediaWidth,
                    height: mediaHeight
                };
            break;
            case MEDIA_CONTENT_TYPES.video.single:
                dimensions = {
                    width: mediaItem.Width || mediaItem.width || DEFAULT_VIDEO_WIDTH,
                    height: mediaItem.Height || mediaItem.height || DEFAULT_VIDEO_HEIGHT
                };
            break;
        }
    }

    return dimensions;
}

@Injectable()
export class LayoutService {
    layout(images: any[], containerWidth: number, targetRowHeight = DEFAULT_BOX_HEIGHT, boxSpacing: any = DEFAULT_BOX_SPACING, maxNumRows: number = Number.POSITIVE_INFINITY, mediaType?: MediaEntity, layoutIndex: number = 0, shouldImagesHaveMinWidth?: boolean): Layout {
        // http://flickr.github.io/justified-layout/#options
        const options = {
            containerWidth,
            targetRowHeight,
            maxNumRows,
            targetRowHeightTolerance: 0,
            containerPadding: 0,
            boxSpacing: boxSpacing
        };

        // In case images should have a minimal width (for example when Properties label is displayed on top of them)
        // The width and the height of the image is set to the desired row height
        // This way images where height > width are sized by their height and have a square gray placeholder
        // This behavior is controlled through the 'shouldImagesHaveMinWidth' flag
        const layout = justifiedLayout(images.map(image => mapForLayout(image, mediaType, shouldImagesHaveMinWidth ? targetRowHeight : null)), options);

        layout.boxes = layout.boxes.map((b, i) => {
                b.index = i;
                return b;
            });

        layout.index = layoutIndex;
        layout.containerWidth = this.getLayoutContianerWidth(layout, boxSpacing);
        return layout;
    }

    getLayoutContianerWidth(layout, boxSpacing): number {
        let layoutRow = 0;
        let wrapperWidth = 0;

        for (let i = 0; i < layout.boxes.length; i++) {
            if (i > 0 && layout.boxes[i].top > layout.boxes[i - 1].top) {
                layoutRow++;
            }
            if (layoutRow === 0) {
                wrapperWidth += layout.boxes[i].width + boxSpacing;
            }
        }
        return wrapperWidth - boxSpacing;
    }
}

export interface Layout {
    containerHeight: number;
    containerWidth: number;
    widowCount: number;
    boxes: Box[];
    index: number;
}

export interface Box {
    aspectRatio: number;
    top: number;
    width: number;
    height: number;
    left: number;
    index: number;
}
