/**
 * Defines the type of the media.
 * @ExposedInApi {MediaType} MediaType v1/embed-media/media.d.ts
 */
export enum MediaType {
    None = 0,
    Tweet = 1,
    IFrame = 2
}

/**
 * An interface that represents the data of media.
 * @ExposedInApi {Media} Media v1/embed-media/media.d.ts
 */
export class Media {
    type: MediaType = MediaType.None;
    html: string;
    width: { hasValue: boolean, value: number };
    height: { hasValue: boolean, value: number };
    title: { hasValue: boolean, value: string };
    isValid: boolean = false;
    data?: any;

    constructor() {
        this.height = { hasValue: false, value: undefined };
        this.width = { hasValue: false, value: undefined };
        this.title = { hasValue: false, value: undefined };
    }
}
