import { Component, OnInit, ViewChild } from "@angular/core";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { of } from "rxjs";
import { ModalListComponent } from "../../src/app/modules/shared/components/modal-list/modal-list.component";
import { DialogData } from "../../src/app/modules/shared/services/modal-window.service";
import { LinkSelectorComponent } from "./link-selector.component";

@Component({
    selector: "sf-link-selector-grid",
    templateUrl: "./link-selector-grid.component.html"
})
export class LinkSelectorGridComponent extends LinkSelectorComponent implements OnInit {
    badgeLook: string = "ellipse";
    linksCount: number = 0;
    @ViewChild("itemTemplate", { static: true }) itemTemplate;

    ngOnInit(): void {
        super.ngOnInit();

        this.linksCount = this.getCurrentValue().length;
        if (this.linksCount) {
            this.badgeLook += " positive";
        }

        this.treeConfig.clickable = false;
        this.treeConfig.drag = false;
    }

    showAllLinks() {
        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                count: of(this.linksCount),
                actionTitle: this.context.model.title,
                dataItem: this.context.dataItem,
                showDataItemTitle: true,
                itemTemplate: this.itemTemplate,
                treeConfig: this.treeConfig,
                items: this.getCurrentValue(),
                isLoading: false,
                ignoreDelay: true,
                listLook: "no-hover condensed",
                contentLook: "medium"
            }
        };

        const dialogData = new DialogData(componentData, null, [], null, "-bottom");
        this.modalService.setMapping(dialogData, "showLinks");
        this.modalService.show("showLinks", this.route);
    }
}
