import { EmbedMediaParser } from "./embed-media.parser";
import { Inject, Injectable } from "@angular/core";
import { DefaultMediaParser } from "./default-media.parser";
import { Media } from "./media";

@Injectable()
export class CompositeMediaParser extends EmbedMediaParser {
    constructor(@Inject(EmbedMediaParser) private embedMediaParsers: Array<EmbedMediaParser>) {
        super();
        this.reorderParsers();
    }

    initEmbeddedData() {
        this.embedMediaParsers.forEach(x => x.initEmbeddedData());
    }

    getMediaHtml(media: Media, width: any, height: any, css: string): string {
        return this.getParser(media.html).getMediaHtml(media, width, height, css);
    }

    canProcess(inputText: string): boolean {
        return !!this.getParser(inputText);
    }

    isExactMatch(inputText: string): boolean {
        return this.getParser(inputText).isExactMatch(inputText);
    }

    getValue(html: string): string {
        return this.getParser(html).getValue(html);
    }

    parse(inputText: string): Promise<Media> {
        return this.getParser(inputText).parse(inputText);
    }

    getMediaFromElement(element: HTMLElement): HTMLElement {
        return this.getParser(element.outerHTML).getMediaFromElement(element);
    }

    updateMediaElement(element: HTMLElement, propName: string, value: any) {
        return this.getParser(element.outerHTML).updateMediaElement(element, propName, value);
    }

    private reorderParsers() {
        // The default provider should be last. Parsers both coming from the extensions and
        // the application cannot be ordered at registration time.
        const isDefaultParser = (x: EmbedMediaParser) => x instanceof DefaultMediaParser;
        const nonDefaultParsers = this.embedMediaParsers.filter(x => !isDefaultParser(x));
        const defaultParser = this.embedMediaParsers.find(x => isDefaultParser(x));

        this.embedMediaParsers = [...nonDefaultParsers, defaultParser];
    }

    private getParser(input: string) {
        return this.embedMediaParsers.find(x => x.canProcess(input));
    }
}
