import { ComponentData, TokenData } from "@progress/sitefinity-component-framework";
import { Named } from "./named";

/**
 * @ExposedInApi {CommandModelBase} CommandModel v1/commands/command-model.d.ts
 */
export class CommandModelBase extends Named {
     /**
     * The category is used to group commands and to determine their placement in the UI.
     *
     * In dialogs the category is used to determine the visual representation of the command.
     * There are 3 out of the box categories:
     * 'cancel' - the rendered button is white
     * 'primary' - the rendered button is green
     * 'delete' - the rendered button is red
     */
    category: string;
    ordinal: number;

    /**
     * A custom token for invoking a service to handle the command
     */
    token?: TokenData;
    component?: ComponentData;
    constructor(readonly name: string) {
        super(name);
    }
}
