import { TooltipPositionParams } from "./../../../../fields/common/directives/tooltipPosition.directive";
import { Component, Input, ChangeDetectorRef, EventEmitter, Output } from "@angular/core";

import { Observable } from "rxjs";
import { ChoiceSettings } from "../../../../fields/choice/choice.settings";

const TOOLSET_LOOK = "toolset black";
const TOOLSET_CLASS = "sf-tooltip__content -toolset";

@Component({
    selector: "sf-edit-menu",
    templateUrl: "./immutable-edit-menu.component.html"
})
export class ImmutableEditMenuComponent {
    @Input() buttonSections: Observable<EditMenuSection[]>;
    @Input() toolsetPositionParams: TooltipPositionParams;
    @Output() closeMenu = new EventEmitter<boolean>();

    toolsetLook: string;
    toolsetClass: string;

    private toolsetPosition: string;

    constructor(private detector: ChangeDetectorRef) {
        this.updateToolsetLookAndClass();
    }

    onPositionChanged(position: string) {
        this.toolsetPosition = position;
        this.updateToolsetLookAndClass();
        this.detector.detectChanges();
    }

    handleClick(event: MouseEvent, button: EditMenuButton, section: EditMenuSection) {
        event.preventDefault();

        // If it is not left button click then do nothing: https://developer.mozilla.org/en-US/docs/Web/API/MouseEvent/button
        if (event.button !== 0) {
            return;
        }

        if (section.buttons.length > 1) {
            section.buttons.forEach((btn) => {
                if (btn.isActive && btn !== button) {
                    btn.isActive = false;
                }
            });

            button.isActive = !button.isActive;
            this.detector.detectChanges();
        }

        button.action();
        this.closeMenu.emit(button.closeMenuOnClick);
    }

    onSelectionChanged(value: string, button: EditMenuButton) {
        button.action(value);
    }

    private updateToolsetLookAndClass(): void {
        this.toolsetLook = this.getLook();
        this.toolsetClass = this.getClasses();
    }

    private getLook(): string {
        let cls = TOOLSET_LOOK;

        if (this.toolsetPosition) {
            cls += ` ${this.toolsetPosition}`;
        }
        return cls;
    }

    private getClasses(): string {
        let cls = TOOLSET_CLASS;

        if (this.toolsetPosition) {
            cls += ` -${this.toolsetPosition}`;
        }
        return cls;
    }
}

export const EDIT_BUTTON_TYPES = {
    standard: "standard",
    text: "text",
    dropdown: "dropdown"
};

export class EditMenuButton {
    type: string = EDIT_BUTTON_TYPES.standard;

    constructor(
        public name: string,
        public action: (data?: any) => void,
        public tooltip: string = null,
        public isActive: boolean = false,
        public closeMenuOnClick: boolean = false) {
    }
}

export class DropdownEditMenuButton extends EditMenuButton {
    dropdownSettings: ChoiceSettings;
    type = EDIT_BUTTON_TYPES.dropdown;

    constructor(name: string, public text: string, public dropdownOptions: string[], initialValue: string, action: (selectedOption: string) => void) {
        super(name, action);
        this.dropdownSettings = new ChoiceSettings(name, false);
        this.dropdownSettings.choices = dropdownOptions.map(x => ({ Name: x, Value: x }));
        this.dropdownSettings.defaultValue = initialValue;
        this.dropdownSettings.look = "-small";
    }
}

/**
 * @ExposedInApi {EditMenuTextButton} EditMenuButton v1/editor/edit-menu-button.d.ts
 */
export class EditMenuTextButton extends EditMenuButton {
    type = EDIT_BUTTON_TYPES.text;

    constructor(name: string, action: () => void, public text: string, public tooltip: string = null, public closeMenuOnClick: boolean = false) {
        super(name, action, tooltip, undefined, closeMenuOnClick);
    }
}

/**
 * @ExposedInApi {EditMenuSection} EditMenuSection v1/editor/edit-menu-section.d.ts
 */
export class EditMenuSection {
    private _buttons: Array<EditMenuButton>;

    get buttons(): Array<EditMenuButton> {
        return this._buttons;
    }

    constructor(...buttons: Array<EditMenuButton>) {
        this._buttons = buttons || [];
    }

    addButton(button: EditMenuButton) {
        this._buttons.push(button);
    }
}

/**
 * A provider used for configuring an edit menu
 * @ExposedInApi {EditMenuProvider} EditMenuProvider v1/editor/edit-menu-provider.d.ts
 */
export interface EditMenuProvider {
    getButtons(element: HTMLElement): Array<EditMenuSection>;
}
