
import { ClassProvider, Injectable } from "@angular/core";
import { NON_CONTENT_TYPES } from "../../../shared/services/metadata/meta-data-constants";
import { EntityData } from "../interfaces";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../../shared/services/edit/edit-extender";

export const CONTENT_FORM_CLASS = "-dynamic-item";

@Injectable()
export class ContentEditExtender extends EditExtender {

    isSupportedType(entityData: EntityData): boolean {
        // temp hack to use this as a fallback for any content type in the system, without the specific ones
        return NON_CONTENT_TYPES.indexOf(entityData.metadata.typeFullName) < 0;
    }

    getFormClasses(): string {
        return CONTENT_FORM_CLASS;
    }

    hasCreateActionFromEdit(): boolean {
        return true;
    }
}

export const CONTENT_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: ContentEditExtender
};
