import { Injectable } from "@angular/core";
import { GenericError } from "./generic-error";
import { HttpErrorResponse } from "@angular/common/http";
import { ValidationError } from "./validation-error";
import { AuthorizationError } from "./authorization-error";
import { ParentHasChildrenError } from "./parent-has-child-error";
import { LockedItemError } from "./locked-item-error";
import { HTTP_STATUS_CODES } from "../../../../services/http/http-status-codes";
import { NotFoundError } from "./not-found-error";
import { ResponseError } from "./response-error";
import { ODataError } from "./odata-error";
import { OperationFailedError } from "./operation-failed-error";
import { OperationItemResult } from "../../components/action-menu/operation.model";
import { ERROR_CODES } from "./error-code.constants";

const ERROR_MAP = {
    [ERROR_CODES.VALIDATION]: ValidationError,
    [ERROR_CODES.AUTHORIZATION]: AuthorizationError,
    [ERROR_CODES.PARENT_HAS_CHILD]: ParentHasChildrenError,
    [ERROR_CODES.LOCKED_ITEM]: LockedItemError
};

@Injectable()
export class ErrorParserService {
    public parseError(error: any): GenericError {
        return this.mapError(error);
    }

    private mapError(errorToMap: any): GenericError {
        // if it is an unhandled promise rejection error, the rejection property
        // will be set with the actual error
        if (errorToMap.rejection) {
            errorToMap = errorToMap.rejection;
        }

        if (errorToMap instanceof TypeError || errorToMap instanceof Error) {
            const error = new GenericError(errorToMap.message, errorToMap.name);
            error.stack = errorToMap.stack;
            return error;
        }

        if (typeof errorToMap === "string") {
            return new GenericError(errorToMap, "Unkown");
        }

        if (errorToMap instanceof HttpErrorResponse) {
            return this.mapHttpErrorResponse(errorToMap);
        }

        if (this.isODataHttpError(errorToMap)) {
            return this.mapODataHttpErrorResponse(errorToMap);
        }

        if (this.isBatchResponse(errorToMap)) {
            return this.mapODataBatchResponseError(errorToMap);
        }

        return errorToMap;
    }

    /* Errors that originate from angular's HttpClient service */
    private mapHttpErrorResponse(httpErrorResponse: HttpErrorResponse): GenericError {
        let message: string = httpErrorResponse.message;
        if (httpErrorResponse.status === 0) {
            message += ".The status code indicates that there might be a problem with one of the following: CORS configuration for the OData service, authentication configuration missing or sitefinity is warming up.";
        } else {
            const errorData = httpErrorResponse.error;

            // check if it is an error comming from the OData Api
            if (this.isODataHttpError(errorData.error)) {
                message += `.An error occured in the OData API: ${errorData.error.code} - ${errorData.error.message}`;
            }
        }

        return new GenericError(message, httpErrorResponse.statusText);
    }

    private mapODataBatchResponseError(response): GenericError {
        for (let i = 0; i < response.data.length; i++) {
            const childResponse = response.data[i];
            if (childResponse.hasOwnProperty("isSuccessful") && !(childResponse.isSuccessful)) {
                const grandChildResponses = childResponse.response;
                for (let j = 0; j < grandChildResponses.length; j++) {
                    const grandChildResponse = grandChildResponses[j];
                    if (grandChildResponse.data && grandChildResponse.data.error) {
                        return this.mapODataHttpErrorResponse(grandChildResponse.data.error);
                    } else {
                        const operationResult = grandChildResponse.data as OperationItemResult;
                        if (operationResult && !operationResult.Success) {
                            return new OperationFailedError(null, operationResult);
                        }
                    }
                }
            } else {
                if (childResponse.data && childResponse.data.error) {
                    return this.mapODataHttpErrorResponse(childResponse.data.error);
                }
            }
        }

        return new GenericError("OData batch request failed", ERROR_CODES.UNKNOWN);
    }

    private mapODataHttpErrorResponse(errorToMap: ODataError) {
        if (ERROR_MAP[errorToMap.code])
            return new ERROR_MAP[errorToMap.code](errorToMap);

        if (errorToMap.status === HTTP_STATUS_CODES.NOT_FOUND) {
            return new NotFoundError(errorToMap);
        }

        return new ResponseError(errorToMap);
    }

    private isODataHttpError(error: any) {
        return this.isErrorType(error, ["code", "message"]);
    }

    private isBatchResponse(data: any) {
        return this.isErrorType(data, ["isSuccessful", "data"]) && data.isSuccessful === false;
    }

    private isErrorType(data: any, properties: string[]) {
        if (!data)
            return false;

        for (let i = 0; i < properties.length; i++) {
            const property = properties[i];
            if (!data.hasOwnProperty(property))
                return false;
        }

        return true;
    }
}
