import { Injectable } from "@angular/core";
import { ADMIN_APP_CONFIG_KEY } from "../../../../app-config/external-app-config.service";
import { FormFieldWrapperComponent } from "../../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../fields-builder/services/field-change/field-change.service";
import { ADMIN_APP_CONFIG_FIELDS_NAMES } from "./backend-interface-settings-config-extender";

@Injectable()
export class BackendInterfaceFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        this.processParentContentTypeProperty(changedFieldName, changedValue, fields, /DynamicModuleChildListOrder\dParentContentType/, ADMIN_APP_CONFIG_FIELDS_NAMES.DYNAMIC_MODULE_CHILD_LIST_ORDER, "ChildContentTypes");
        this.processParentContentTypeProperty(changedFieldName, changedValue, fields, /SearchSettings\dContentType/, ADMIN_APP_CONFIG_FIELDS_NAMES.SEARCH_SETTINGS, "Fields");
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === ADMIN_APP_CONFIG_KEY;
    }

    private processParentContentTypeProperty(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[], fieldRegex: RegExp, fieldName: string, fieldToBeChangedName: string) {
        const match = changedFieldName.match(fieldRegex);
        if (match && fields.length > 0) {
            const rowNumber = changedFieldName.match(/\d/)[0];
            const fieldWrapper = fields.find(x => x.fieldModel.key === `${fieldName}${rowNumber}${fieldToBeChangedName}`);
            if (fieldWrapper) {
                const field = fieldWrapper.currentInstance;
                if (changedValue.length > 0) {
                    const entitySet = changedValue[0];
                    field.setEntitySetName(entitySet);
                    field.ngOnInit();
                    field.setHidden(false);
                } else {
                    field.onReset();
                    field.setHidden(true);
                }
            }
        }
    }
}

export const BACKEND_INTERFACE_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: BackendInterfaceFieldsChangeService,
    multi: true
};
