import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { Observable } from "rxjs";
import { SiteDataStore, SiteData } from "./site-data.store";

@Injectable()
export class SiteDataStoreResolver implements Resolve<any> {
    constructor(private siteDataStore: SiteDataStore) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<SiteData> {
        return this.siteDataStore.getValue();
    }
}
