import { Input, Component, Output, EventEmitter } from "@angular/core";
import { Operation } from "../../action-menu/operation.model";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { DataItem } from "../../../../content/dynamic-modules/interfaces";
import { COMMAND_NAMES } from "../../../../content/dynamic-modules/components/commands";

@Component({
    templateUrl: "./basic-notification.component.html"
})
export class BasicNotificationComponent {
    @Input() message: string;
    @Input() operation: Operation;
    @Input() dataItem: DataItem;
    @Output() onCommand = new EventEmitter<string>();

    isExecutingAction: boolean;

    constructor(private service: DynamicItemService) {
    }

    public executeAction() {
        this.isExecutingAction = true;

        this.service.executeOperation(this.dataItem, this.operation.Name).subscribe(() => {
            this.onCommand.emit(COMMAND_NAMES.refresh);
            this.onCommand.emit(COMMAND_NAMES.close);
            this.isExecutingAction = false;
        });
    }
}
