import { Injectable } from "@angular/core";
import { StatusLabel } from "../../../fields/resolvers/base-status.resolver";
import { ENTITY_SET } from "../modules/shared/services/metadata/meta-data-constants";
import { StatusResolver } from "../../../fields/resolvers/status.resolver";
import { stringConstants } from "../common-constants";
import { Properties } from "../modules/shared/fields.constants";

const DISPLAY_STATUS_NAMES = {
    SAVED: "Saved"
};

@Injectable()
export class ContentItemStatusResolver extends StatusResolver {
    getLabel(item: any): StatusLabel {
        return {
            StatusName: stringConstants.EMPTY_STRING,
            Label: this.getStatusLabelInternal(item),
            HideIcon: true
        };
    }

    canProcess(setName: string): boolean {
        return setName === ENTITY_SET.CONTENT_ITEMS;
    }

    private getStatusLabelInternal(item: any) {
        if (item.LockedStatus) {
            return `Locked by ${item.LockedStatus.User}`;
        }

        const statuses: any[] = item[Properties.DISPLAY_STATUS];
        if (!statuses?.length) {
            return stringConstants.EMPTY_STRING;
        }

        // If there is only one status, this means that it's the default one and we shouldn't display it.
        if (statuses.length === 1 && statuses[0].Name === DISPLAY_STATUS_NAMES.SAVED) {
            return stringConstants.EMPTY_STRING;
        }

        // We have 2 or more(maybe) statuses, we should display the last one, because the first status is the default one(Saved).
        // Example: if we send for tranlation given item, item.DisplayStatus contains [Saved, SendForTranslation]
        const status = statuses[statuses.length - 1];
        return status.Label;
    }
}
