import { Component, ElementRef, EventEmitter, Inject, Input, OnInit, Output, ViewChild, ViewEncapsulation } from "@angular/core";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { BehaviorSubject, combineLatest, Subject } from "rxjs";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { ImportDamAssetsResult, MediaService } from "../services/media.service";
import { DamAsset } from "./dam-provider-base";
import { DOCUMENT_TOKEN } from "../../../document.provider";
import { getExtensionFromFileName, getValidateExtensionsErrorMessage, isFileTypeAllowed } from "../../../utils";
import { MediaEntity } from "../../shared/services/metadata/meta-data.store";
import { NotificationService, NOTIFICATION_SERVICE } from "../../shared/services/notification/notification.service";
import { DamProviderService } from "./dam-provider.service";

@Component({
    templateUrl: "./dam-file-picker.component.html",
    selector: "sf-dam-file-picker",
    styleUrls: ["./dam-file-picker.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class DamFilePickerComponent extends SfRxBase implements OnInit {
    @ViewChild("damWrapper")
    set content(content: ElementRef) {
        // To get viewChild element after ngIf change
        // Initially setter gets called with undefined
        if (content) {
            this.damWrapperElement.next(content);
        }
    }

    @Input() mediaEntityData: EntityData;
    @Input() multiple: boolean;
    @Input() notificationFilter: string = null;

    @Input() fallbackToSitefinityLibraries: boolean = true;
    @Input() importAssetsOnSelect: boolean = true;
    @Output() mediaImportComplete = new EventEmitter<ImportDamAssetsResult>();
    @Output() mediaSelectComplete = new EventEmitter<DamAsset[]>();
    @Output() cancelSelection = new EventEmitter();
    @Output() loadingError = new EventEmitter();
    @Output() selectExistingLibrary = new EventEmitter();

    errorMessage: Subject<string>;
    isLoading: boolean;

    private damWrapperElement: Subject<ElementRef>;

    constructor(
        @Inject(DOCUMENT_TOKEN) private document: Document,
        private mediaService: MediaService,
        @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService,
        private damProviderService: DamProviderService) {
        super();
    }

    ngOnInit(): void {
        this.errorMessage = new BehaviorSubject<string>(null);
        this.damWrapperElement = new Subject<ElementRef>();
        this.isLoading = true;
        this.initializeDamProvider();
    }

    onSelectExistingLibrary(): void {
        this.selectExistingLibrary.emit();
    }

    private initializeDamProvider(): void {
        this.registerSubscription(this.damProviderService.getDamProvider().subscribe(damProvider => {
            let loadingError: boolean = true;
            if (damProvider) {
                loadingError = false;
                this.isLoading = false;

                this.registerSubscription(damProvider.onMediaSelected.subscribe(() => {
                    this.isLoading = true;
                }));

                this.registerSubscription(damProvider.onDone.subscribe(assets => {
                    const mediaEntity = this.mediaEntityData.metadata as MediaEntity;
                    const filteredAssets: DamAsset[] = mediaEntity ? this.filterAssets(assets, mediaEntity.acceptableFileTypes) : assets;
                    if (mediaEntity && filteredAssets.length !== assets.length) {
                        const errorMessage = getValidateExtensionsErrorMessage(mediaEntity.acceptableFileTypes);
                        this.notificationService.publishInfiniteError(errorMessage, this.notificationFilter);
                    }

                    if (filteredAssets && filteredAssets.length) {
                        this.importAssets(filteredAssets);
                    } else {
                        this.cancelSelection.emit();
                    }
                    this.dispatchClickToRootDocument();
                }));

                this.registerSubscription(damProvider.onCancel.subscribe(() => {
                    this.dispatchClickToRootDocument();
                    this.cancelSelection.emit();
                }));

                this.registerSubscription(damProvider.onError.subscribe((message) => {
                    this.isLoading = false;
                    this.errorMessage.next(message);
                }));

                this.registerSubscription(combineLatest([this.damWrapperElement, this.errorMessage]).subscribe(([element, errorMessage]) =>  {
                    if (!errorMessage) {
                        damProvider.loadMediaSelector(element.nativeElement, this.mediaEntityData, !!this.multiple);
                    }
                }));
            }

            if (loadingError) {
                this.loadingError.emit();
            }
        }, () =>  {
            this.loadingError.emit();
        }));
    }

    //The click events are consumed by the iframe, which breaks the functionality of the SfTrackFocus directive
    //as results of that the replace image dropdown doesn't get closed
    //this is why we dispatch a click event whenever the file picker is closed through the dam iframe
    private dispatchClickToRootDocument() {
        const event = new MouseEvent("click", {
            bubbles: true,
            cancelable: true
        });
        this.document.dispatchEvent(event);
    }

    private filterAssets(assets: DamAsset[], acceptableFileTypes: string[]): DamAsset[] {
        if (!acceptableFileTypes || !acceptableFileTypes.length) {
            return assets;
        }

        return assets.filter(asset => {
            const extension = getExtensionFromFileName(asset.extension);
            return isFileTypeAllowed(extension, acceptableFileTypes);
        });
    }

    private importAssets(assets: DamAsset[]) {
        if (this.importAssetsOnSelect) {
            this.mediaService.importDamAssets(this.mediaEntityData, assets).subscribe(importDamAssetsResult => {
                this.mediaImportComplete.emit(importDamAssetsResult);
            }, serverError =>  {
                if (serverError.message) {
                    this.errorMessage.next(serverError.message);
                } else {
                    this.errorMessage.next(serverError);
                }
            }, () => {
                this.isLoading = false;
            });
        } else {
            this.mediaSelectComplete.emit(assets);
        }
    }
}
