import { Component, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData } from "../../../../content/dynamic-modules/interfaces";
import { Entity } from "../../../services/metadata/meta-data.store";
import { DataContextComponent, DataContext } from "../../../models/data-context-component";
import { ENTITY_SET } from "../../../services/metadata/meta-data-constants";

@Component({
    selector: "sf-calendar-grid-component",
    templateUrl: "./calendar-grid-cell.component.html"
})
export class CalendarGridCellComponent implements OnInit, DataContextComponent {
    public context: DataContext;
    public calendar: any;

    constructor(private readonly dynamicItemService: DynamicItemService,
                private readonly route: ActivatedRoute) {

    }

    ngOnInit(): void {
        // when switching from another grid it is possible the dataItem not to be events
        // (angular triggers change detection before the itemsstate is updated)
        if (this.context.dataItem.metadata.setName === ENTITY_SET.EVENTS) {
            const event = this.context.dataItem;
            const entityData: EntityData = this.route.snapshot.data.dynamicItems;
            const entities = this.route.snapshot.data.metaStore.entities;
            const calendarEntity: Entity = entities[event.metadata.parent];

            this.dynamicItemService.getItem({
                itemKey: event.parentKey,
                entityData: {
                    metadata: calendarEntity,
                    culture: entityData.culture,
                    provider: entityData.provider
                },
                fallbackProperties: [calendarEntity.defaultFieldName]
            })
            .subscribe(calendar => {
                this.calendar = calendar.data;
            });
        }
    }
}
