import { forkJoin as observableForkJoin, of as observableOf,  Observable, of } from "rxjs";

import { filter, mergeMap, tap, map } from "rxjs/operators";
import { SelectorBase } from "../selector-base";
import { ContentSelectorItem, ContentSelectorItemsDataObject } from "./content-selector-item";
import { ServiceContract, ServiceInfo } from "../../../../../../../../../../fields/selector/selector.component";
import { Entity, MetadataContainer, MODULE_NAME, MediaEntity } from "../../../../../../../shared/services/metadata/meta-data.store";
import { stringConstants } from "../../../../../../../../common-constants";
import { DynamicItemService } from "../../../../../../../content/dynamic-modules/services/dynamic-item.service";
import { LoadingState, delayEmission } from "../../../../../../../shared/rxjs-extensions/delayEmission";
import { TreeConfig, DEFAULT_DATA_FIELDS } from "../../../../../../../../../../fields/index";
import { MediaContentSelectorStrategy } from "./strategies/media-content-selector-strategy";
import { GenericContentSelectorStrategy } from "./strategies/generic-content-selector-strategy";
import { ContentSelectorStrategy } from "./strategies/content-selector-strategy";
import { Logger } from "../../../../../../../shared/services/logger-source/logger";
import { MediaService } from "../../../../../../../libraries/services/media.service";
import { BLUR_EFFECT_TIMEOUT } from "../../../../../../../content/constants";
import { DataItem, TotalCountResult } from "../../../../../../../content/dynamic-modules/interfaces";
import { cloneInstance } from "../../../../../../../../utils";
import { MEDIA_TYPES_MODULE_NAME } from "../../../../../../../content/modules.provider";
import { Properties } from "../../../../../../../shared/fields.constants";
import { ENTITY_SET } from "../../../../../../../shared/services/metadata/meta-data-constants";
import { LoadingContentState } from "../../../../../../../shared/rxjs-extensions/toLoadingState";
import { SortService } from "../../../../../../../shared/services/sort.service";

export class ContentSelector extends SelectorBase<ContentSelectorItem> {
    shouldLoadMoreItems: boolean;
    treeConfig: TreeConfig;
    service: ServiceContract;
    totalItemCount: number;

    private entity: Entity;
    private readonly initialSkip = 0;
    private strategy: ContentSelectorStrategy;

    constructor(
        logger: Logger,
        private dynamicItemsService: DynamicItemService,
        private meta: MetadataContainer,
        private mediaSvc: MediaService,
        private sortService: SortService
    ) {
        super(logger);
        this.service = new ServiceContract(this.serviceLoadMore,
            this.serviceExpandChildren);
    }

    onInit(): Observable<LoadingState> {
        this.entity = this.meta.entities[this.context.selectedEntitySet.value];
        const moduleName = this.entity.properties[MODULE_NAME];
        if (moduleName === MEDIA_TYPES_MODULE_NAME) {
            this.strategy = new MediaContentSelectorStrategy(this.context, this.meta, this.mediaSvc, this.dynamicItemsService, this.entity as MediaEntity, this.sortService);
        } else {
            this.strategy = new GenericContentSelectorStrategy(this.dynamicItemsService, this.context, this.entity, this.sortService);
        }

        this.treeConfig = {
            status: this.entity.setName !== ENTITY_SET.CONTENT_ITEMS,
            isHierarchical: true
        };

        const getItemsRequestInfo = <ServiceInfo>{ skip: this.initialSkip, searchText: null, parentId: null };
        return this.strategy.getItems(getItemsRequestInfo).pipe(
            tap((response: LoadingContentState<TotalCountResult<DataItem[]>>) => {
                if (!response.isLoading) {
                    this.shouldLoadMoreItems = true;
                    this.error$.next(stringConstants.EMPTY_STRING); // clear previously displayed errors
                    const data = response.content.dataItems.map(dataItem => ContentSelectorItem.fromDataItem(dataItem));
                    this.totalItemCount = response.content.totalCount;
                    this.items = data;
                    this.setSelectedItem(null);
                }
            }));
    }

    protected setSelectedItem(value: ContentSelectorItem) {
        this.context.selectedContentItem = value;
        super.setSelectedItem(value);
    }

    private serviceLoadMore = (info: ServiceInfo): Observable<ContentSelectorItemsDataObject> => {
        if (!this.shouldLoadMoreItems) {
            return of({dataItems: [], totalCount: 0});
        }

        return this.getItems(info);
    }

    private serviceExpandChildren = (info: ServiceInfo): Observable<ContentSelectorItemsDataObject> => {
        return this.getItems(info);
    }

    private getItems(info: ServiceInfo): Observable<ContentSelectorItemsDataObject> {
        return this.strategy.getItems(info)
            .pipe(
                delayEmission(BLUR_EFFECT_TIMEOUT),
                filter(x => !x.isLoading),
                map(response => response.content),
                mergeMap(response => this.processAndWrapItems(response.dataItems, info), (response, items) => {
                    return <ContentSelectorItemsDataObject>{dataItems: items, totalCount: response.totalCount};
                })
            );
    }

    private processAndWrapItems(items: DataItem[], info: ServiceInfo): Observable<ContentSelectorItem[]> {
        return observableOf(items).pipe(mergeMap(items => {
            if (info.searchText) {
                return this.processItemsBreadcrumbs(items);
            } else {
                return observableOf(items);
            }
        }),
        map(items => items.map(dataItem => ContentSelectorItem.fromDataItem(dataItem))));
    }

    private processItemsBreadcrumbs(items: DataItem[]): Observable<DataItem[]> {
        const itemsBreadcrumbTasks: Observable<DataItem>[] = [];
        items.forEach(item => {
            if (this.shouldProcessItemBreadcrumb(item)) {
                itemsBreadcrumbTasks.push(this.getBreadcrumb(item, []).pipe(
                    mergeMap(breadcrumb => {
                        breadcrumb = breadcrumb.reverse();
                        const clonedItem = this.setBreadcrumb(item, breadcrumb);
                        return observableOf(clonedItem);
                    })));
            } else {
                itemsBreadcrumbTasks.push(observableOf(item));
            }
        });

        return observableForkJoin(itemsBreadcrumbTasks);
    }

    private shouldProcessItemBreadcrumb(item: DataItem) {
        if (!item.parentKey || !item.data[Properties.FOLDER_ID] || item.data[Properties.BREADCRUMB]) {
            return false;
        }

        if (item.metadata.setName === ENTITY_SET.PAGES && item.data[Properties.ROOT_ID] === item.parentKey) {
            return false;
        }

        return true;
    }

    private getBreadcrumb(item: DataItem, breadcrumb: string[]): Observable<string[]> {
        return this.strategy.getParent(item).pipe(filter(x => !x.isLoading),
            mergeMap(response => {
                const parentItem = response.content;
                breadcrumb.push(parentItem.title);
                if (parentItem.data[DEFAULT_DATA_FIELDS.BREADCRUMB]) {
                    return observableOf(breadcrumb.concat(parentItem.data[DEFAULT_DATA_FIELDS.BREADCRUMB]));
                }

                if (this.shouldProcessItemBreadcrumb(parentItem)) {
                    // TODO: this logic should be removed once all the hierarchical items from sitefinity services are returned with a standard breadcrumb property, tp story id 246026
                    return this.getBreadcrumb(parentItem, breadcrumb);
                } else {
                    return observableOf(breadcrumb);
                }
            }));
    }

    // TODO: this logic should be removed once all the hierarchical items from sitefinity services are returned with a standard breadcrumb property, tp story id 246026
    private setBreadcrumb(item: DataItem, breadcrumb: string[]): DataItem {
        const clonedData = cloneInstance(item.data);
        clonedData[DEFAULT_DATA_FIELDS.BREADCRUMB] = breadcrumb;
        return DataItem.from(clonedData, item.metadata, item.provider, item.culture);
    }
}
