import { map, filter } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { DynamicItemService, LoadItem } from "../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { FormDefinition } from "../forms.constants";
import { stringConstants } from "../../../common-constants";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { Observable } from "rxjs";
import { HttpODataRequestWrapper } from "../../shared/services/http-odata-request.wrapper";
import { QUERY_PARAMS } from "../../content/constants";

@Injectable()
export class FormsService {
    constructor(
        protected metadataStore: MetadataStore,
        protected dynamicItemsService: DynamicItemService,
        private httpWrapper: HttpODataRequestWrapper,
    ) { }

    getFormDefinition(formId: string, culture: string = stringConstants.EMPTY_STRING): Observable<DataItem> {
        const formEntity = this.metadataStore.getEntity(ENTITY_SET.FORM_DRAFTS);
        const formLoadData = <LoadItem>{
            itemKey: formId,
            action: "Default.GetTempForm()",
            entityData: <EntityData>{
                metadata: formEntity,
                culture: culture
            }
        };

        return this.dynamicItemsService.getItem(formLoadData);
    }

    updateRules(formDefinition: FormDefinition): Observable<any> {
        const formEntity = this.metadataStore.getEntity(ENTITY_SET.FORM_DRAFTS);
        const entityData = <EntityData>{
            metadata: formEntity,
            provider: stringConstants.EMPTY_STRING,
            culture: formDefinition.Culture
        };

        return this.dynamicItemsService.executeEntityOperationForDataItemKey(formDefinition.Id, entityData, "Default.SaveTempForm()", { rules: formDefinition.Rules });
    }

    getFormByName(formName: string, entityData: EntityData): Observable<DataItem> {
        const params = {
            [QUERY_PARAMS.CULTURE]: entityData.culture
        };
        return this.httpWrapper.get$(`${entityData.metadata.setName}/Default.GetFormByName(formName=@param)?@param='${formName}'`, { params })
            .pipe(
                filter(state => !state.isLoading),
                map(state => DataItem.from(state.content, entityData.metadata, entityData.provider, entityData.culture))
            );
    }
}
