import { Component, OnInit, ViewChild } from "@angular/core";
import { createValueAccessor, FieldBase } from "../../../../../../fields";
import { VALIDATION_REQUIRED } from "../../../../../../fields/common/common-constants";
import { FieldModel, FieldRegistration, FieldTypes } from "../../../../api";
import { stringConstants } from "../../../../common-constants";
import { FieldSectionModel } from "../../../../services/fieldSection.model";
import { cloneObject } from "../../../../utils";
import { ValueChange } from "../../../shared/fields-builder/components/editable-fields/editable-fields.component";
import { EditableTableComponent } from "../../../shared/fields-builder/components/editable-table/editable-table.component";
import { CompositeFieldsProvider } from "../../../shared/fields-builder/providers/fields-provider";
import { createFieldModel } from "../../../shared/fields.constants";
import { ERROR_CODES } from "../../../shared/services/errors/error-code.constants";
import { FieldError } from "../../../shared/services/errors/field-error";
import { ValidationError } from "../../../shared/services/errors/validation-error";
import { ComplexSettings } from "./complex/complex.settings";

const DEFAULT_DATA_ATTRIBUTE_FIELD_STRUCTURE: AttributeField[] = [
    {
        Key: null,
        Value: null
    }
];
const KEY: string = "Key";
const VALUE: string = "Value";
const TITLE_COLUMN_CLASS = "-col-size-m";
const REQUIRED_KEY_ERROR_MESSAGE = "Field is required";
const NO_SPACES_IN_KEY_ERROR_MESSAGE = "Spaces are not allowed";

@Component({
    selector: "sf-attributes",
    templateUrl: "./attributes.component.html",
    providers: [createValueAccessor(AttributesComponent)]
})
export class AttributesComponent extends FieldBase<ComplexSettings> implements OnInit {
    public allowModifyTable = true;
    fieldSections: FieldSectionModel[];
    defaultSection: FieldSectionModel;
    defaultValue: any;

    @ViewChild(EditableTableComponent, { static: false }) editableTableComponent: EditableTableComponent;

    constructor(private fieldsProvider: CompositeFieldsProvider) {
        super();
    }

    ngOnInit(): void {
        super.ngOnInit();

        const sections: FieldSectionModel[] = [];
        const allRecords = this.settings.extraRecords;
        for (let i = 1; i <= this.settings.dependsOnLength; i++) {
            allRecords.push({
                Name: this.settings.lengthDependsOnDisplayName + i,
                Title: this.settings.lengthDependsOnDisplayTitle + i
            });
        }

        const currentValue = super.getValue();
        for (let i = 0; i < allRecords.length; i++) {
            const record = allRecords[i];
            const name = record.Name;
            const attributeFields: AttributeField[] = currentValue && currentValue[name] ? currentValue[name] : DEFAULT_DATA_ATTRIBUTE_FIELD_STRUCTURE;
            sections.push(...this.getSections(record.Name, record.Title, attributeFields));
        }

        this.fieldSections = sections;
    }

    onChange(args: ValueChange) {
        this.updateValue();
    }

    getValue() {
        this.updateValue();

        return super.getValue();
    }

    validate(): boolean {
        let isValid = true;
        if (this.editableTableComponent && this.editableTableComponent.fieldSections) {
            this.editableTableComponent.fieldSections.forEach(section => {
                const hasKey = section.fields[0].value;
                const hasValue = section.fields[1].value;

                const requiredKey = !hasKey && hasValue;
                const noSpaces = hasKey && hasKey.includes(stringConstants.INTERVAL);

                if (requiredKey || noSpaces) {
                    const errorMsg = requiredKey ? REQUIRED_KEY_ERROR_MESSAGE : NO_SPACES_IN_KEY_ERROR_MESSAGE;
                    const attributesValidationError = new ValidationError({ code: ERROR_CODES.VALIDATION, message: errorMsg, status: 0 });
                    const fieldKeyValidationError = cloneObject(attributesValidationError);
                    attributesValidationError.fieldErrors = [new FieldError(section.fields[0].key, fieldKeyValidationError)];
                    this.editableTableComponent.addModelErrors(attributesValidationError);
                    this.editableTableComponent.valid(false);
                    isValid = false;
                }
            });
        }

        return isValid;
    }

    private getSections(name: string, title: string, attributeFields: AttributeField[]): FieldSectionModel[] {
        const result: FieldSectionModel[] = [];
        for (let i = 0; i < attributeFields.length; i++) {
            // only last field section will have its line drawn title will be shown only for the first section
            const insertHorizontalRule = i === attributeFields.length - 1;
            const sectionTitle = i === 0 ? title : stringConstants.EMPTY_STRING;
            const section = new FieldSectionModel({
                isMain: false,
                isExpanded: false,
                insertHorizontalRule: insertHorizontalRule,
                title: sectionTitle,
                name: name,
                cssClass: TITLE_COLUMN_CLASS
            });

            const attributeField = attributeFields[i];
            section.fields = this.getKeyAndValueFields(attributeField, name, i);
            result.push(section);
        }

        return result;
    }

    private getKeyAndValueFields(attributeField: AttributeField, sectionName: string, rowIndex: number): FieldModel[] {
        const entity: any = {
            [VALIDATION_REQUIRED]: false
        };
        const fieldType = FieldTypes.shortText;

        const keyFieldFriendlyTitle = sectionName + KEY;
        const keyFieldIndexedTitle = keyFieldFriendlyTitle + rowIndex;
        const keyField = createFieldModel(
            this.fieldsProvider,
            fieldType,
            fieldType,
            keyFieldIndexedTitle,
            attributeField.Key,
            entity,
            KEY,
            keyFieldFriendlyTitle
        );
        keyField.settings.showTitle = false;

        const valueFieldFriendlyTitle = sectionName + VALUE;
        const valueFieldIndexedTitle = valueFieldFriendlyTitle + rowIndex;
        const valueField = createFieldModel(
            this.fieldsProvider,
            fieldType,
            fieldType,
            valueFieldIndexedTitle,
            attributeField.Value,
            entity,
            VALUE,
            valueFieldFriendlyTitle
        );
        valueField.settings.showTitle = false;

        return [keyField, valueField];
    }

    private updateValue() {
        if (this.editableTableComponent && this.editableTableComponent.fieldSections) {
            const result: { [sectionName: string]: AttributeField[] } = {};
            this.editableTableComponent.fieldSections.forEach(section => {
                if (section.fields[0].value) {
                    if (!result.hasOwnProperty(section.settings.name)) {
                        result[section.settings.name] = [];
                    }

                    const valueToAdd: any = {};
                    valueToAdd[KEY] = section.fields[0].value;
                    valueToAdd[VALUE] = section.fields[1].value || stringConstants.EMPTY_STRING;
                    result[section.settings.name].push(valueToAdd);
                }
            });

            this.writeValue(result);
        }
    }
}

export interface AttributeField {
    Key: string,
    Value: string
}

export const ATTRIBUTES_REGISTRY: FieldRegistration = {

    writeComponent: AttributesComponent,
    readComponent: AttributesComponent,
    settingsType: ComplexSettings
};
