import { Component, AfterViewInit } from "@angular/core";
import { ADDRESS_FIELDS } from "./address.constants";
import { FieldBase } from "../../../../../../fields/field-base";

@Component({
    selector: "sf-address",
    templateUrl: "./address.component-grid.html"
})
export class AddressGridComponent extends FieldBase implements AfterViewInit {
    formattedValue: string;
    country: string;
    city: string;
    street: string;
    ngAfterViewInit(): void {
        this.city = this.getFieldValue(ADDRESS_FIELDS.CITY);
        this.country = this.getFieldValue(ADDRESS_FIELDS.COUNTRY_CODE);
        this.street = this.getFieldValue(ADDRESS_FIELDS.STREET);
    }

    private getFieldValue(fieldName: string): any {
        return this.value ? this.value[fieldName] : null;
    }
}
