import { map } from "rxjs/operators";
import { Component, Input, TemplateRef, OnInit, Output, EventEmitter, OnChanges, SimpleChanges } from "@angular/core";
import { ReplaySubject } from "rxjs";
import { toLoadingState, delayEmission } from "../../src/app/modules/shared/rxjs-extensions";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const MINIMUM_LOADER_TIME = 600;

@Component({
    selector: "sf-loader-wrapper",
    templateUrl: "./loader-wrapper.component.html"
})

/** Provides sf-loader consistent minimum delay time and optionally wraps content and loadingContent templates */
export class LoaderWrapperComponent extends SfRxBase implements OnInit, OnChanges {
    @Input() isLoading: any;
    @Input() look: string;
    @Input() count: number;
    @Input() content: TemplateRef<any>;
    @Input() loadingContent: TemplateRef<any>;
    @Input() ignoreDelay: boolean;
    @Input() loadingTime: number;
    @Input() initialValue: boolean = true;
    @Output() loadingChanged: EventEmitter<boolean> = new EventEmitter<boolean>();

    protected isLoadingInternal: ReplaySubject<boolean> = new ReplaySubject<boolean>(1);

    constructor() {
        super();
    }

    ngOnInit() {
        const sub = this.isLoadingInternal
        .pipe(
            toLoadingState(this.initialValue),
            map(val => {
                if (val.content) {
                    return { isLoading: true, content: val.content };
                } else {
                    return val;
                }
            }),
            delayEmission(this.ignoreDelay ? 0 : (this.loadingTime || MINIMUM_LOADER_TIME)))
        .subscribe((val) => {
            const loadingStatus = !!(val.isLoading || val.content);
            this.loadingChanged.emit(loadingStatus);
        });

        this.registerSubscription(sub);
    }

    ngOnChanges(changes: SimpleChanges): void {
        const change = changes["isLoading"];

        if (change) {
            this.isLoadingInternal.next(!!change.currentValue);
        }
    }
}
