import { Injectable } from "@angular/core";
import { FormHelpers } from "../../../forms/form.helpers";
import { Entity } from "../../services/metadata/meta-data.store";

@Injectable()
export class ExtensionPointUtilsService {

    public shouldExtendMenu(dataItemFullTypeName) {
        if (!dataItemFullTypeName)
            return false;

        const staticContentTypes = [
            "Telerik.Sitefinity.News.Model.NewsItem",
            "Telerik.Sitefinity.Blogs.Model.BlogPost",
            "Telerik.Sitefinity.Lists.Model.ListItem",
            "Telerik.Sitefinity.Libraries.Model.Video"
        ];
        const isKnownStaticContentType = staticContentTypes.indexOf(dataItemFullTypeName) !== -1;
        if (isKnownStaticContentType)
            return true;

        return !!this._isDynamicModule(dataItemFullTypeName);
    }

    public shouldExtendGrid(entity: Entity) {
        const dataItemFullTypeName = entity.typeFullName;
        if (!dataItemFullTypeName || FormHelpers.isFormResponseType(entity.setName))
            return false;

        const staticContentTypes = [
            "Telerik.Sitefinity.News.Model.NewsItem",
            "Telerik.Sitefinity.Blogs.Model.Blog",
            "Telerik.Sitefinity.Blogs.Model.BlogPost",
            "Telerik.Sitefinity.Lists.Model.List",
            "Telerik.Sitefinity.Lists.Model.ListItem",
            "Telerik.Sitefinity.Libraries.Model.VideoLibrary",
            "Telerik.Sitefinity.Libraries.Model.Video"];
        const isKnownStatisContentType = staticContentTypes.indexOf(dataItemFullTypeName) !== -1;
        if (isKnownStatisContentType)
            return true;

        return !!this._isDynamicModule(dataItemFullTypeName);
    }

    private _isDynamicModule(dateItemFullType) {
        return dateItemFullType.startsWith("Telerik.Sitefinity.DynamicTypes");
    }

}
