import { Component, OnInit } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { SiteDataStore, SiteData } from "../../../services/metadata/site-data.store";
import { Observable } from "rxjs";
import { AuthService } from "../../../../auth/auth.service";
import { ROUTE_PATHS_NO_PREFIX, ROUTE_PATHS } from "../../../../../constants/route-paths";

@Component({
    selector: "sf-home-navigation",
    templateUrl: "./home-navigation.component.html"
})
export class HomeNavigationComponent implements OnInit {
    public siteInfo: Observable<SiteData>;

    // could be extracted if needed
    public config: HomeNavigationItem[] = [
        {title: "Dashboard", url: null, icon: "sf-fa-th-large"},
        {title: "Pages", url: ROUTE_PATHS.PAGES, icon: "sf-fa-file-text-o"},
        {title: "Content", url: ROUTE_PATHS_NO_PREFIX.CONTENT, icon: "sf-fa-list"},
        {title: "Ecommerce", url: null, icon: "sf-fa-shopping-basket"},
        {title: "Marketing", url: null, icon: "sf-fa-bullhorn"},
        {title: "Administration", url: null, icon: "sf-fa-cogs"}
    ];

    constructor(private authService: AuthService,
                private route: ActivatedRoute,
                private router: Router,
                private siteDataStore: SiteDataStore) {
    }

    ngOnInit() {
        this.siteInfo = this.siteDataStore.getValue();
    }

    onLogout() {
        this.authService.signOut();
    }

    onOpen(url: string) {
        setTimeout(() => {
            if (url.indexOf(ROUTE_PATHS.PAGES) > -1) {
                this.router.navigate([url], { queryParamsHandling: "merge" });
            } else if (this.route.outlet === ROUTE_PATHS_NO_PREFIX.MENU_OUTLET) {
                this.router.navigate([{ outlets: { menu: url } }], { relativeTo: this.route.parent, queryParamsHandling: "merge" });
            } else {
                this.router.navigate([url], { relativeTo: this.route.parent, queryParamsHandling: "merge" });
            }
        });
    }
}

interface HomeNavigationItem {
    title: string;
    url: string;
    icon: string;
}
