import { Injectable, ClassProvider } from "@angular/core";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../../services/edit/edit-extender";
import { EVENT_PROPERTIES } from "../events.constants";
import { Properties } from "../../../fields.constants";
import { EntityData } from "../../../../content/dynamic-modules/interfaces";
import { EVENT_ITEM_FULL_NAME, CALENDAR_ITEM_FULL_NAME } from "../../../services/metadata/meta-data-constants";

@Injectable()
export class EventsEditExtender extends EditExtender {
    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.typeFullName === EVENT_ITEM_FULL_NAME || entityData.metadata.typeFullName === CALENDAR_ITEM_FULL_NAME;
    }

    includedProperties(entityData: EntityData): string[] {
        return [
            Properties.AvailableLanguages,
            EVENT_PROPERTIES.EVENT_START_WITH_OFFSET,
            EVENT_PROPERTIES.EVENT_END_WITH_OFFSET,
            EVENT_PROPERTIES.EVENT_START_UTC_OFFSET,
            EVENT_PROPERTIES.EVENT_END_UTC_OFFSET];
    }

    hasCreateActionFromEdit(): boolean {
        return true;
    }
}

export const EVENTS_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: EventsEditExtender
};
