import { Command } from "../../shared/commands/command";
import { Injectable, Inject } from "@angular/core";
import { ExecutionContext } from "../../shared/commands/execution-context";
import { Observable, of } from "rxjs";
import { StorageService, LOCAL_STORAGE, LIBRARIES_GRID_VIEW_KEY } from "../../shared/services/storage.service";
import { Router } from "@angular/router";
import { WINDOW_TOKEN } from "../../../window.provider";
import { UserDataStore } from "../../shared/services/metadata/user-data.store";

@Injectable()
export class SwitchGridViewCommand implements Command {
    constructor(@Inject(LOCAL_STORAGE) private storage: StorageService, private router: Router, @Inject(WINDOW_TOKEN) private window: Window, private userStore: UserDataStore) { }

    execute(context: ExecutionContext): Observable<any> {
        const user = this.userStore.userId;
        this.storage.setItem(LIBRARIES_GRID_VIEW_KEY, `${user},${context.data.gridViewName}`);
        this.router.navigate([], { queryParamsHandling: "preserve" });

        // dispatch event in order to avoid references
        const event = new CustomEvent("gridViewStateChanged");
        this.window.dispatchEvent(event);
        return of({ selectedSettingName: context.data.gridViewName});
    }
}
