import { Component } from "@angular/core";
import { MediaComponent } from "./media.component";
import { TreeConfig } from "./../../../../../fields";
import { NOT_SELECTED } from "../../../common-constants";

@Component({
    templateUrl: "./media.component.readonly.html",
    selector: "sf-media-component-readonly"
})
export class MediaReadonlyComponent extends MediaComponent {
    public notSelectedValueText: string = NOT_SELECTED;

    fileTreeConfig: TreeConfig = {
        status: true,
        noSelection: true
    };

    hasEmptyValue(): boolean {
        return false;
    }

    get isEmptyMultimedia() {
        return this.isMultimedia && (!this.allItems.length || !this.mediaItems.length) && !this.uploads.length;
    }
}
