import { Injectable } from "@angular/core";
import { Actions, createEffect, ofType, ROOT_EFFECTS_INIT } from "@ngrx/effects";
import { of } from "rxjs";
import { map, mergeMap } from "rxjs/operators";
import { Settings } from "../../../modules/shared/services/settings.service";
import { MOBILE_PREVIEW_ACTIONS } from "../actions/actions.mobile-preview";

@Injectable()
export class MobilePreviewEffects {
    public readonly onChangeWidth$ = createEffect(() => {
        return this.actions$.pipe(
            ofType(MOBILE_PREVIEW_ACTIONS.changeWidth),
            mergeMap(data => {
                return of(this.setStorageValue(data.width));
            })
        );
    }, { dispatch: false });

    public readonly init$ = createEffect(() => {
       return this.actions$.pipe(
            ofType(ROOT_EFFECTS_INIT),
            map(() => {
                const width = this.settingsService.getMobillePreviewBreakPoint();
                if (width) {
                    return MOBILE_PREVIEW_ACTIONS.changeWidth({ width });
                } else {
                    return { type: "noop" };
                }
            })
        );
    });

    constructor(
        private actions$: Actions,
        private settingsService: Settings
    ) { }

    private setStorageValue(width: number) {
        if (width) {
            this.settingsService.setMobillePreviewBreakPoint(width);
        }
        return { type: "noop" };
    }
}
