import { Inject, Injectable, InjectionToken, Optional } from "@angular/core";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { DEFAULT_EMPTY_SCREEN_ICON } from "../../content/dynamic-modules/dynamic-item.constants";

export const SYSTEM_NOTIFICATION_ICON_TOKEN = new InjectionToken("system_notification_icon_token");

export const SYSTEM_NOTIFICATION_KEYS = Object.freeze({
    FORM_RESPONSE: "subscribed-responses",
    REJECTED_ITEM: "rejected",
    SEND_FOR_APPROVAL_ITEM: "sent-to-me",
    SITE_SYNC_COMPLETED: "site-sync-completed",
    MY_OUTDATED_CONTENT: "my-outdated-content",
    OUTDATED_LAST_MODIFIED: "outdated-content-last-modified-by-me",
    ANY_OUTDATED_CONTENT: "any-outdated-content",
    MY_OUTDATED_CONTENT_ITEMS: "my-outdated-content-items",
    OUTDATED_LAST_MODIFIED_ITEMS: "outdated-content-items-last-modified-by-me",
    ANY_OUTDATED_CONTENT_ITEMS: "any-outdated-content-items",
    TRIAL: "trial"
});

export const SYSTEM_NOTIFICATION_TYPES = Object.freeze({
    FAIL: "fail"
});

/**
 * A system notification provider to provide icon for custom notifications.
 * @ExposedInApi {SystemNotificationIconProvider} SystemNotificationIconProvider v1/notifications/system-notification-icon-provider.d.ts
 */
export interface SystemNotificationIconProvider {
    /**
     * Gets the notification icon by notification key.
     */
    parseIcon(key: string): string;
}

export const FORMS_ICON = "check-square-o";
export const SITESYNC_SUCCESS_ICON = "upload";
export const SITESYNC_FAIL_ICON = "exclamation-circle";
export const OUTDATED_ICON = "hourglass-end";
export const TRIAL_ICON = "lightbulb-o";

@Injectable()
export class CompositeSystemNotificationIconProvider implements SystemNotificationIconProvider {

    /**
     * Initializes a new instance of the CompositeSystemNotificationIconProvider class.
     * @param systemNotificationIconProviders The injected system notification icon providers.
     */
    constructor(@Optional() @Inject(SYSTEM_NOTIFICATION_ICON_TOKEN) private systemNotificationIconProviders: Array<SystemNotificationIconProvider>) { }
/**
    * Gets the notification icon by notification key.
    * @param {string} key Notification key.
    * @returns {string} The icon as string.
    */
    parseIcon(key: string): string {
        return this.parseIconInternal(key, null);
    }
    /**
     * Gets the notification icon by notification key.
     * @param {string} key Notification key.
     * @param {string} notificationType Notification type.
     * @returns {string} The icon as string.
     */
     parseIconInternal(key: string, notificationType: string): string {
        let result = stringConstants.EMPTY_STRING;

        switch (key) {
            case SYSTEM_NOTIFICATION_KEYS.FORM_RESPONSE:
                result = FORMS_ICON;
                break;
            case SYSTEM_NOTIFICATION_KEYS.REJECTED_ITEM:
            case SYSTEM_NOTIFICATION_KEYS.SEND_FOR_APPROVAL_ITEM:
                result = DEFAULT_EMPTY_SCREEN_ICON;
                break;
            case SYSTEM_NOTIFICATION_KEYS.SITE_SYNC_COMPLETED:
                result = SITESYNC_SUCCESS_ICON;
                if (notificationType === SYSTEM_NOTIFICATION_TYPES.FAIL) {
                    result = SITESYNC_FAIL_ICON;
                }
                break;
            case SYSTEM_NOTIFICATION_KEYS.MY_OUTDATED_CONTENT:
            case SYSTEM_NOTIFICATION_KEYS.OUTDATED_LAST_MODIFIED:
            case SYSTEM_NOTIFICATION_KEYS.ANY_OUTDATED_CONTENT:
            case SYSTEM_NOTIFICATION_KEYS.MY_OUTDATED_CONTENT_ITEMS:
            case SYSTEM_NOTIFICATION_KEYS.OUTDATED_LAST_MODIFIED_ITEMS:
            case SYSTEM_NOTIFICATION_KEYS.ANY_OUTDATED_CONTENT_ITEMS:
                result = OUTDATED_ICON;
                break;
            case SYSTEM_NOTIFICATION_KEYS.TRIAL:
                result = TRIAL_ICON;
                break;
        }

        if (this.systemNotificationIconProviders) {
            this.systemNotificationIconProviders.forEach(provider => {
                const icon = provider.parseIcon(key);
                if (icon) {
                    result = icon;
                }
            });
        }

        return result || DEFAULT_EMPTY_SCREEN_ICON;
    }

    getIconColor(notificationType: string): string {
        let result = "gray";

        switch (notificationType) {
            case SYSTEM_NOTIFICATION_TYPES.FAIL:
                result = "negative";
                break;
        }

        return result;
    }
}
