import { Injectable, ClassProvider } from "@angular/core";
import { Observable, of } from "rxjs";
import { HierarchicalService, ID_KEY, RESULT_COUNT, HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { createQuery } from "../../../services/query";
import { LoadItemsResponse, LoadItemsData } from "../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { stringConstants } from "../../../common-constants";
import { TaxonomySettings } from "../../taxonomy/taxonomy.settings";

export const PAGE = "Page";
export const PAGES = "pages";

@Injectable()
export class HierarchicalPagesService extends HierarchicalService {
    showStatusIcons(): boolean {
        return true;
    }

    isHierarchical(type: string): boolean {
        return true;
    }

    getSetName(): string {
        return PAGES;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return PAGE === entityData.metadata.singularName;
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        let query: any = createQuery().where().and().or();

        if (value) {
            value.forEach(id => query = query.eq(ID_KEY, id));
        }

        query = query.done().done().done();

        return this.dynamicItemService
            .getItemListBatch({
                entityData: entityData,
                take: value ? value.length : null,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                query,
                siteId: this.siteId
            });
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[]): Observable<LoadItemsResponse> {
        const id = settings.id || stringConstants.DEFAULT_GUID;
        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `${id}/Default.GetAvailableParentPages(parentId='${stringConstants.DEFAULT_GUID}',search='',recent=${true},excludeOptions=2)`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                take: RESULT_COUNT,
                siteId: this.siteId
            });
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        const excludeLevel = info.excludeLevel || 2;
        const skip = info.skip || 0;
        const id = taxaId || stringConstants.DEFAULT_GUID;
        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `${id}/Default.GetAvailableParentPages(parentId='${info.parentId}',search='',recent=${false},excludeOptions=${excludeLevel})?$skip=${skip}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                siteId: this.siteId
            });
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings): Observable<LoadItemsResponse> {
        const searchText = info.searchText || stringConstants.EMPTY_STRING;
        const skip = info.skip || 0;
        const excludeLevel = info.excludeLevel || 2;
        const id = info.parentId || stringConstants.DEFAULT_GUID;
        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `${id}/Default.GetAvailableParentPages(parentId='${stringConstants.DEFAULT_GUID}',search='${searchText}',recent=${false},excludeOptions=${excludeLevel})?$skip=${skip}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                siteId: this.siteId
            });
    }

    getModalItems(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        const id = taxaId || stringConstants.DEFAULT_GUID;
        return this.dynamicItemService
            .getItemsByKeys({
                entityData: entityData,
                action: `${id}/Default.GetAvailableParentPages(parentId='${stringConstants.DEFAULT_GUID}',search='',recent=${false},excludeOptions=2)`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                keys: [],
                keyProperty: null,
                siteId: this.siteId
            });
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData): Observable<LoadItemsResponse> {
        const excludeLevel = info.excludeLevel || 2;
        const id = info.taxaId || stringConstants.DEFAULT_GUID;
        return this.dynamicItemService
            .getItemsByKeys({
                entityData: loadingData.entityData,
                action: `${id}/Default.GetAvailableParentPages(parentId='${stringConstants.DEFAULT_GUID}',search='${info.searchText}',recent=${false},excludeOptions=${excludeLevel})`,
                fallbackProperties: [loadingData.entityData.metadata.defaultFieldName],
                take: loadingData.take,
                skip: loadingData.skip,
                keys: [],
                keyProperty: null,
                siteId: this.siteId
            });
    }
}

export const HIERARCHICAL_PAGES_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalPagesService
};
