import { ClassProvider, Injectable } from "@angular/core";
import { FieldRegistration, FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { FIELDS_PROVIDER_TOKEN, FieldRegistryKey, DefaultFieldsProvider } from "../../../shared/fields-builder/providers/fields-registration-provider";
import { PropertyEditorWidgets } from "../../property-editor.constants";
import { DateTimePickerComponent } from "../../../../../../fields/date-time/date-time-picker.component";
import { DateTimePickerSettings } from "../../../../../../fields/date-time/date-time-settings";

@Injectable()
export class DateTimeFieldProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.fieldType === FieldTypes.dateTime && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: DateTimePickerComponent,
                settingsType: WidgetDateTimePickerSettings
            };
    }
}

export class WidgetDateTimePickerSettings extends DateTimePickerSettings {
    public init(metadata: any) {
        super.init(metadata);
        this.preserveValueWithoutBrowserOffset = true;
    }
}

export const DATE_FIELD_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: DateTimeFieldProvider,
    multi: true
};
