import { Component, OnInit } from "@angular/core";

import { ChoiceComponent } from "./choice.component";
import { createValueAccessor } from "../field-base";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-yes-no-choice",
    templateUrl: "./choice-yesno.component.html",
    providers: [createValueAccessor(ChoiceYesNoComponent)]
})
export class ChoiceYesNoComponent extends ChoiceComponent implements OnInit {
    choice: ChoiceItem;

    isChecked(): boolean {
        if (this.value === null || this.value === undefined) {
            return this.convertValue(this.settings.defaultValue);
        }

        if (this.settings.isInverted) {
            return !this.convertValue(this.value);
        }

        return this.convertValue(this.value);
    }

    ngOnInit() {
        super.ngOnInit();

        if (this.settings) {
            this.choice = {
                Name: this.settings.optionName || this.settings.title,
                Value: this.value,
                Selected: this.isChecked()
            };

            this.choiceSettings.readOnlyMode = this.settings.readOnlyMode;
        }
    }

    onSelectionChange(entry) {
        // don't use entry.currentTarget.checked. In some browsers change event is fired before checked attribure is changed
        this.value = !this.convertValue(this.value);
        this.choice.Selected = this.isChecked();
        this.selectionChange.emit(this.value);
    }

    private convertValue(value: any): boolean {
        if (value === "True" || value === "true")
            return true;

        if (typeof value === "boolean") {
            return value;
        }

        return false;
    }
}
