import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Router } from "@angular/router";
import { ProviderStore } from "../content/dynamic-modules/services/provider-store";
import { ROUTE_PATHS } from "../../constants/route-paths";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";
import { FormsConstants } from "./forms.constants";
import { EntityData } from "../content/dynamic-modules/interfaces";
import { stringConstants } from "../../common-constants";
import { BaseResolver } from "../content/dynamic-modules/components/dynamic-items-base.resolver";
import { FormsService } from "./services/forms.service";
import { Settings } from "../shared/services/settings.service";
import { CompositeEntityDataResolver } from "../content/dynamic-modules/services/backend-tweaks/entity-data.resolver";
import { ItemData } from "../content/dynamic-modules/services/entity/dynamic-item.resolver";
import { Observable, of } from "rxjs";
import { catchError, map } from "rxjs/operators";

@Injectable()
export class FormResolver extends BaseResolver {
    constructor(
        router: Router,
        store: ProviderStore,
        settings: Settings,
        entityDataResolver: CompositeEntityDataResolver,
        private service: FormsService) {
            super(store, router, settings, entityDataResolver);
        this.persistCulture = true;
    }

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean> {
        const segmentPaths = route.url.map(s => s.path.toLowerCase());
        if (segmentPaths.length > 0) {
            const formsSegmentIndex = segmentPaths.indexOf(ENTITY_SET.FORMS.toLowerCase());
            const integratedSegmentIndex = segmentPaths.indexOf(FormsConstants.ROUTES.EDIT.toLowerCase());

            // either ends with Action/Edit in this order or has one last param for culture
            const canActivate = formsSegmentIndex > -1 || integratedSegmentIndex > -1;
            if (!canActivate) {
                this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
            }

            return of(canActivate);
        }

        return of(true);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<ItemData> {
        const entityData: EntityData = super.resolve(route, state);

        const segmentPaths = route.url.map(s => s.path.toLowerCase());
        let formName = stringConstants.EMPTY_STRING;
        const editSegmentIndex = segmentPaths.lastIndexOf(FormsConstants.ROUTES.EDIT.toLowerCase());
        if (segmentPaths.length > 1) {
            formName = segmentPaths[editSegmentIndex + 1];
        }

        if (formName !== stringConstants.EMPTY_STRING) {
            return this.service.getFormByName(formName, entityData)
                .pipe(map(dataItem => {
                    const itemData: ItemData = {
                        item: dataItem,
                        entityData: entityData,
                        fallbackProperties: []
                    };

                    return itemData;
                }),
                catchError(err => {
                    this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
                    return of(err);
                }));
        } else {
            this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
        }
    }

    protected getCultureFromRoute(route: ActivatedRouteSnapshot): string {
        const segmentPaths = route.url.map(s => s.path);
        const segmentPathsToLowerCase = segmentPaths.map(x => x.toLowerCase());
        const editSegmentIndex = segmentPathsToLowerCase.lastIndexOf(FormsConstants.ROUTES.EDIT.toLowerCase());
        let cultureSegment = null;
        if (segmentPaths.length > 2) {
            cultureSegment = segmentPaths[editSegmentIndex + 2];
        }

        let cultureName = cultureSegment;
        if (!cultureName) {
            cultureName = super.getCultureFromRoute(route);
        }

        return cultureName;
    }

    protected getEntitySet(route: ActivatedRouteSnapshot): string {
        return ENTITY_SET.FORMS;
    }
}
