import { WidgetEditor, WidgetMetadata, PropertyData, ActionContext, ValidationResult, PropertyMetadata, SectionData } from "./interfaces/widget-editor";
import { Component, Input, ViewChild } from "@angular/core";
import { Observable, of } from "rxjs";
import {
    FieldSectionModel,
    FieldSectionSettings
} from "../../services/fieldSection.model";
import { FieldModel } from "../../services/field.model";
import { EditableFieldsComponent } from "../shared/fields-builder/components/editable-fields/editable-fields.component";
import { Properties as FieldProperties } from "../shared/fields.constants";
import { WidgetContext } from "./models/widget-context";
import { FIELD_LOOK_MAPPER, FIELD_TYPE_MAPPER } from "./providers/fields/field-type-mapper";
import { PropertyEditorWidgets, Dictionary, PropertyEditorConstants} from "./property-editor.constants";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { stringConstants } from "../../common-constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ContentSettings } from "./providers/fields/content/content.settings";
import { DynamicItemService } from "../content/dynamic-modules/services/dynamic-item.service";
import { map } from "rxjs/operators";
import { ValidationError } from "../shared/services/errors/validation-error";
import { SitefinityContentTypes } from "../insight/test-utils/sitefinity-content-types";
import { Operation } from "../../../../fields/services/base.service";
import { INTEGRATION_MODULE_MODEL_NAMES } from "../content/constants";
import { CreateFieldService } from "./services/create-field.service";

const IMAGE_VIEW_NAME = "SitefinityImage";
const EDITORS_WITHOUT_BORDER_IN_BASIC = [IMAGE_VIEW_NAME, INTEGRATION_MODULE_MODEL_NAMES.SEARCH_INDEX];
const CSS_CLASS_BASE = "sf-form -medium -sf-centered-box -sf-pb-zero";

@Component({
    selector: "sf-basic-view",
    templateUrl: "./basic-editor.component.html"
})
export class BasicEditorViewComponent extends SfRxBase implements WidgetEditor {
    @ViewChild(EditableFieldsComponent, { static: true }) editableFieldsComponent: EditableFieldsComponent;

    @Input() context: WidgetContext;
    @Input() insertHorizontalRule: boolean = true;
    @Input() shouldHaveTopPadding: boolean = true;
    headingPrefix: string;
    fieldChange: (props: any) => void;
    shouldShowTopBorder: boolean;
    shouldHideBottomBorder: boolean;
    shouldTextAreasBeResizable: boolean = false;
    settingsForSpecificFields: {[fieldName: string]: {[settingName: string]: any}} = {};

    fieldSections$: Observable<FieldSectionModel[]>;
    hiddenFields$: Observable<FieldModel[]>;
    heading: string;
    cssClass: string;
    baseCssClass = CSS_CLASS_BASE;
    showMainHeading: boolean = true;
    hasStickyBuffer: boolean = false;

    constructor(
        private dynamicService: DynamicItemService,
        private createFieldService: CreateFieldService) {
        super();
    }

    public initialize(widgetMetadata: WidgetMetadata): Observable<void> {
        const headingPrefix = this.headingPrefix || stringConstants.EMPTY_STRING;
        const widgetMetadataCaption = widgetMetadata.caption || stringConstants.EMPTY_STRING;
        this.cssClass = this.shouldHaveTopPadding ? `${this.baseCssClass} -sf-pt-7xl` : `${this.baseCssClass} -sf-pt-zero`;

        this.heading = `${headingPrefix}${widgetMetadataCaption}`;
        this.shouldShowTopBorder = this.handleTopBorderVisibility(widgetMetadata.name);

        const sections: FieldSectionModel[] = [];
        const allFields: FieldModel[] = [];
        const templateFields: FieldModel[] = [];
        widgetMetadata.propertyMetadata.forEach((sectionMeta, index, allSections) => {
            if (sectionMeta) {
                this.organizeGroups(sectionMeta);

                const fields: FieldModel[] = this.getFields(sectionMeta.Properties, widgetMetadata.propertyValues, templateFields);
                const isExpanded = widgetMetadata.propertyMetadata.length > 0 && index === 0;
                const sectionOptions: FieldSectionSettings = {
                    isMain: sectionMeta.Title === null,
                    isExpanded,
                    insertHorizontalRule: (!this.shouldHideBottomBorder || index < allSections.length - 1) && this.insertHorizontalRule,
                    title: sectionMeta.Title,
                    name: sectionMeta.Name + this.context.sectionName
                };
                const section = new FieldSectionModel(sectionOptions);
                section.fields = fields;
                sections.push(section);
                allFields.push(...fields);
            }
        });

        allFields.push(...templateFields);
        const fieldSettings$ = this.getFieldsSettings(allFields);
        fieldSettings$.subscribe(() => {
            this.hiddenFields$ = of(templateFields);
            this.fieldSections$ = of(sections);
        });
        return fieldSettings$;
    }

    public setValues(propValues: Dictionary): void {
        this.editableFieldsComponent.updateValues(propValues);
    }

    public validate(): Observable<ValidationResult> {
        const editableForms = <EditableFieldsComponent>this.editableFieldsComponent;
        editableForms.enableRequiredErrorCheck();

        return editableForms.validateAsync().pipe(map(isValid => {
            return { isValid, message: stringConstants.EMPTY_STRING };
        }));
    }

    public showValidationErrors(error: ValidationError) {
        const editableForms = <EditableFieldsComponent>this.editableFieldsComponent;
        editableForms.addModelErrors(error);
        editableForms.valid();
    }

    public getModifiedProperties(): Array<PropertyData> {
        return this.getProperties(true);
    }

    public getAllProperties(): Array<PropertyData> {
        return this.getProperties(false);
    }

    public actionExecuting(context: ActionContext): Observable<any> {
        return of(true);
    }

    public onFieldChange(args) {
        if (this.fieldChange && typeof (this.fieldChange) === "function") {
            this.fieldChange(args);
        }
    }

    private getFieldsSettings(allFields: FieldModel[]): Observable<void> {
        const contentFields = allFields.filter(x => x.selector === FieldTypes.content);
        const contentFieldsString = contentFields.map(x => (x.settings as ContentSettings).contentType).filter((value, index, self) => {
            return self.indexOf(value) === index;
        }).join(",");
        if (contentFieldsString) {
            const fnResult$ = this.dynamicService.executeUnboundFunction<{ FieldSettings: FieldSettings[] }>(`Default.FieldSettings(types=@param)?@param='${contentFieldsString}'`).pipe(map((x) => {
                const fieldSettings = x.FieldSettings;
                fieldSettings.forEach((fieldSettings) => {
                    const contentFieldsForType = contentFields.filter(x => (x.settings as ContentSettings).contentType === fieldSettings.Key);
                    contentFieldsForType.forEach((field) => {
                        field.settings.allowCreate = fieldSettings.AllowCreate;
                        field.settings.allowView = fieldSettings.AllowView;
                        this.updatedContentFormFieldSettings(field);
                    });
                });

                return fieldSettings;
            }));

            return new Observable((observer) => {
                fnResult$.subscribe(() => observer.next());
            });
        }

        return of(undefined);
    }

    private getFields(propertiesMeta: PropertyMetadata[], propertiesValues: Dictionary, templateFields: FieldModel[]): FieldModel[] {
        const fields: FieldModel[] = [];
        propertiesMeta
            .map(prop => {
                const fieldType = FIELD_TYPE_MAPPER.get(prop.Type) || FieldTypes[prop.Type] || FieldTypes.shortText;
                const field = this.createFieldService.createField(
                    fieldType,
                    prop.Name,
                    this.getValueOrDefault(prop, propertiesValues),
                    prop,
                    prop.Title,
                    PropertyEditorWidgets.FIELD_TYPE_KEY + this.context.widgetName,
                    propertiesValues,
                    this.context.culture
                );

                if (this.settingsForSpecificFields.hasOwnProperty(prop.Name)) {
                    Object.keys(this.settingsForSpecificFields[prop.Name]).forEach(settingName => {
                        field.settings[settingName] = this.settingsForSpecificFields[prop.Name][settingName];
                    });
                }

                const look = FIELD_LOOK_MAPPER.get(prop.Name);

                if (look) {
                    field.settings.look = look;
                }

                if (this.shouldTextAreasBeResizable && fieldType === FieldTypes.textArea) {
                    field.settings.look = "resizable";
                }

                if (field.settings.conditionalRule && field.settings.conditionalRule.inline) {
                    templateFields.push(field);
                } else {
                    fields.push(field);
                }
            });

        return fields;
    }

    private getValueOrDefault(propertyMetadata: PropertyMetadata, propertiesValues: Dictionary) {
        if (typeof propertiesValues[propertyMetadata.Name] === "undefined" && typeof propertyMetadata.DefaultValue !== "undefined")
            return propertyMetadata.DefaultValue;

        return propertiesValues[propertyMetadata.Name];
    }

    private handleTopBorderVisibility(name: string): boolean {
        if (this.context.isQuickEdit) {
            return false;
        }

        const hasBorder = name && EDITORS_WITHOUT_BORDER_IN_BASIC.indexOf(name) === -1 && !(this.headingPrefix === PropertyEditorConstants.ADVANCED_SETTINGS_LABEL);
        return hasBorder;
    }

    private getProperties(onlyDirty: boolean): Array<PropertyData> {
        const fields = this.editableFieldsComponent.getFields(onlyDirty);
        const properties = [];
        if (fields) {
            Object.keys(fields).forEach((compositeProp) => {
                if (fields[compositeProp] !== undefined) {
                    const isRelatedData = this.editableFieldsComponent.fieldSections.some(section => section.fields.some(f => (f.selector === "sf-related-data" || f.selector === "sf-media") && f.key === compositeProp));
                    if (isRelatedData) {
                        let fieldValue = fields[compositeProp];
                        const isMultipleRelatedData = this.editableFieldsComponent.fieldSections.some(section => section.fields.some(f => f.selector === ("sf-related-data" || f.selector === "sf-media") && f.key === compositeProp && f.settings["allowMultiple"]));
                        if (fieldValue && fieldValue instanceof Array && !isMultipleRelatedData) {
                            fieldValue = fieldValue[0];
                        }
                        properties.push({ Name: compositeProp, Value: fieldValue });
                    } else {
                        properties.push({ Name: compositeProp, Value: fields[compositeProp] });
                    }
                }
            });
        }

        return properties;
    }

    private updatedContentFormFieldSettings(field: FieldModel) {
        if (this.context.entityData &&
            this.context.entityData.data[FieldProperties.RENDERER] === "NetCore" &&
            (<ContentSettings>field.settings).contentType === SitefinityContentTypes.Form) {
            (<ContentSettings>field.settings).filter = [{
                key: FieldProperties.RENDERER,
                value: ["NetCore"],
                operation: Operation.eq
            }];
        }
    }

    private organizeGroups(sectionMeta: SectionData) {
        const groupNameKey = "Meta_Group_Name";
        const groupedFields = sectionMeta.Properties.filter(x => x.Properties.hasOwnProperty(groupNameKey));
        const grouped = {};
        groupedFields.forEach((field) => {
            const groupName = field.Properties[groupNameKey];
            grouped[groupName] = grouped[groupName] || [];
            grouped[groupName].push(field);
        });

        Object.keys(grouped).forEach((groupName) => {
            const group = grouped[groupName];
            if (group.length > 0) {
                group[0].Properties["Meta_Group_First"] = true;
            }

            if (group.length > 1) {
                group[group.length - 1].Properties["Meta_Group_Last"] = true;
            }
        });
    }
}

interface FieldSettings {
    Key: string;
    AllowCreate: boolean;
    AllowView: boolean;
}
