import { UrlNameSettings } from "../../../urlName/urlName-settings";
import { VALIDATION_REGEX, FIELD_VALIDATION_PREFIX } from "../../../../../../fields/common/common-constants";
import { RegexHelper } from "../../../../utils";
import { Observable } from "rxjs";
import { DataItem } from "../../../content/dynamic-modules/interfaces";

export const CUSTOMS_STRUCTURE_REGEX_VALIDATION = FIELD_VALIDATION_PREFIX + ".CustomStructureRegex";
export interface UrlStructureData {
    parentUrl: string;
    extension: string;
    editableUrl: string;
}

export class StructureUrlNameSettings extends UrlNameSettings {
    public regex: RegExp;
    public customStructureRegex: RegExp;
    public isStructureEditable: boolean;
    public hasExtension: boolean;
    public getUrlStructureData: (dataItem: DataItem) => Observable<UrlStructureData>;

    init(metadata: any) {
        super.init(metadata);
        let regex = metadata[VALIDATION_REGEX];
        regex = RegexHelper.buildRegex(regex);
        this.regex = new RegExp(regex);

        let customStructureRegex = metadata[CUSTOMS_STRUCTURE_REGEX_VALIDATION];
        customStructureRegex = RegexHelper.buildRegex(customStructureRegex);

        this.customStructureRegex = new RegExp(customStructureRegex);
    }

    getValidatorDictionary(metadata: any) {
        const superResult = super.getValidatorDictionary(metadata);
        delete superResult[VALIDATION_REGEX];
        return superResult;
    }
}
