import { DataItem } from "../../../interfaces";
import { ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { MetadataStore } from "../../../../../shared/services/metadata/meta-data.store";
import { ActivatedRoute } from "@angular/router";
import { cloneObject } from "../../../../../../utils";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { CompositeDataExtender } from "../../../../../shared/services/data-extensions/data.extender";
import { SelectorBaseCommand } from "./selector-base.command";
import { DynamicItemService } from "../../dynamic-item.service";
import { NotificationService } from "../../../../../shared/services/notification/notification.service";
import { SortService } from "../../../../../shared/services/sort.service";

export abstract class LibraryTasksBaseCommand extends SelectorBaseCommand {
    protected whiteListedTasks: string[];

    constructor(protected modalWindowService: ModalWindowService,
                protected metadataStore: MetadataStore,
                protected compositeDataExtender: CompositeDataExtender,
                protected route: ActivatedRoute,
                protected service: DynamicItemService,
                protected notificationService: NotificationService,
                protected sortService: SortService) {
                    super(modalWindowService, service, notificationService, sortService);
                }

    protected mapNodes(dataItems: DataItem[]) {
        const propMap = {
            FoldersCount: 0,
            hasChildren: false,
            isSelectionDisabled: true,
            inactive: true,
            tooltip: msg => msg
        };

        const value = this.compositeDataExtender.enhanceDataItems(this.entityData, dataItems, propMap, {whiteListedTasks: this.whiteListedTasks}).map(dataItem => {
            const data = cloneObject(dataItem.data);
            data.isTranslated = true;
            data.icon = "folder-o";
            data.iconLook = "size-xl light";

            return data;
        });

        return value;
    }

    protected modifyComponentData(componentData: ComponentData) {
        componentData.properties.treeConfig["treeProperties"]["hasChildrenField"] = "FoldersCount";
        componentData.properties.treeConfig["dataProperties"] = { toolTipField: "tooltip" };
        componentData.properties.noItemsCreatedLabel = "No libraries have been created yet";
        componentData.properties.emptyIcon = "folder";
        componentData.properties.typeNames = {
            plural: "libraries",
            singular: "library"
        };
    }
}
