import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { Inject, Injectable } from "@angular/core";
import { FieldBase } from "../../../../../../fields/field-base";
import { ComplexComponent } from "../../providers/fields/complex/complex.component";
import { ChoiceComponent } from "../../../../../../fields/choice/choice.component";
import { HierarchicalFacetsService, HIERARCHICAL_FACETS_SERVICE } from "../../../libraries/services/hierarchical-facets.service";

const INDEX_FIELD_NAME = "IndexCatalogue"
const SELECTED_FACETS_FIELD_NAME = "SelectedFacets"
const FACETS_NAME = "Facets";
const SITEFINITY_FACETS_NAME = "SitefinityFacets";

@Injectable()
export class FacetWidgetFieldsChangeService implements FieldChangeService {

    constructor(@Inject(HIERARCHICAL_FACETS_SERVICE) private facetService: HierarchicalFacetsService) {
    }

    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === INDEX_FIELD_NAME && changedValue) {
            FacetWidgetFieldsChangeService.processSelectedItemsFieldChange(changedValue, fields.map(x => x.currentInstance), this.facetService);
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === FACETS_NAME || typeFullName === SITEFINITY_FACETS_NAME;
    }

    static processSelectedItemsFieldChange(changedValue: any, fields: FieldBase[], facetService: HierarchicalFacetsService) {
        const searchIndexDropDownField = this.getSearchIndexDropDownField(fields);
        if (searchIndexDropDownField) {
            const facetTableField = this.getFacetTableField(fields);

            if (facetTableField) {
                const shouldBindNewData = searchIndexDropDownField.choices.length > 0;
                facetTableField.loadData(`Default.GetFacetableFields(indexCatalogName='${changedValue}')`, shouldBindNewData, (data) => {
                    facetService.setDataItems(data);
                });
            }
        }
    }

    private static getFacetTableField(fields: FieldBase[]): ComplexComponent {
        const field = fields.find(x => x.settings.key === SELECTED_FACETS_FIELD_NAME);
        if (field && field instanceof ComplexComponent) {
            return field;
        }

        return null;
    }

    private static getSearchIndexDropDownField(fields: FieldBase[]): ChoiceComponent {
        const field = fields.find(x => x.settings.key === INDEX_FIELD_NAME);
        if (field && field instanceof ChoiceComponent) {
            return field;
        }

        return null;
    }
}

export const FACET_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: FacetWidgetFieldsChangeService,
    multi: true
};
