import { Component, HostListener, Inject, OnDestroy, OnInit, ViewChild } from "@angular/core";
import { SfRxBase, stringConstants } from "@progress/sitefinity-component-framework";
import { combineLatest, map, Observable, ReplaySubject } from "rxjs";
import { DynamicItemService } from "../content/dynamic-modules/services/dynamic-item.service";
import { SidebarComponentData } from "../shared/components/sidebar/sidebar-component.repo";
import { AppStore } from "../../services/store/app-store";
import { SIDEBAR_DISPATCH_ACTION } from "../../services/store/actions/actions.sidebar";
import { DEFAULT_SIDEBAR_BUTTON_LOOK } from "../shared/components/sidebar/sidebar-buttons.component";
import { SidebarData } from "../shared/components/sidebar/sidebar.common";
import { ListItemSettingsSidebarComponent, SettingsSidebarSection } from "../content/dynamic-modules/components/sidebar/list-item-settings-sidebar.component";
import { Operation } from "../shared/components/action-menu/operation.model";
import { capitalizeFirstLetter, groupBy } from "../../utils";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";
import { ActivatedRoute } from "@angular/router";
import { ConfigSettingsComponent } from "../shared/config/config-settings.component";
import { CanDeactivateComponent } from "../shared/guards/can-deactivate.guard";
import { NavigateCommand } from "../content/dynamic-modules/services/operations/commands/navigate-command";
import { WINDOW_TOKEN } from "../../window.provider";
import { QUERY_PARAMS } from "../content/constants";
import { SiteTitleDynamicResolver } from "../shared/services/site-title.dynamic.resolver";

export const SETTINGS_UNTITLED_TYPES = "untitled";

const BROWSE_SETTINGS = "Browse settings";
const UNSAVED_CHANGES_DIALOG_MESSAGE = "There are unsaved changes for this item. Are you sure you want to discard them and leave?";
const SETTINGS_TYPE_KEY = "ConfigKey";
const SETTINGS_CATEGORIES = {
    ADVANCE_SETTINGS: "Advanced Settings",
    BASIC_SETTINGS: "Basic Settings"
}

@Component({
    selector: "sf-basic-settings",
    templateUrl: "./basic-settings-component.html"
})
export class BasicSettingsComponent extends SfRxBase implements OnInit, OnDestroy, CanDeactivateComponent {

    public configKey$ = new ReplaySubject<string>(1);
    @ViewChild("configSettings") private configSettingsComponent: ConfigSettingsComponent;
    public title: string;
    constructor(
        private dynamicItemService: DynamicItemService,
        private store: AppStore,
        private route: ActivatedRoute,
        private siteTitleDynamicResolver: SiteTitleDynamicResolver,
        @Inject(WINDOW_TOKEN) private window: Window) {
        super();
    }

    ngOnInit(): void {
        const getBasicSettingOperations$ = this.dynamicItemService.executeUnboundFunction<{ value: Operation[] }>("Default.GetBasicSettingsOperations()");
        const getSettingTypeFromQueryString$ = this.getSettingTypeFromQueryString(QUERY_PARAMS.TYPE);

        this.registerSubscription(combineLatest([getBasicSettingOperations$, getSettingTypeFromQueryString$]).subscribe((data: [{ value: Operation[] }, string]) => {
            const operations = data[0].value;
            let queryStringSettingsType: string = data[1];

            let selectedOperation: Operation = null;
            if (operations) {
                if (queryStringSettingsType == null) {
                    queryStringSettingsType = this.getFirstConfigProviderType(operations)
                }

                selectedOperation = this.getOperation(operations, queryStringSettingsType);

                const settingsSidebarSection = this.getSettingsSidebarSections(operations);
                this.configureBasicSettingsLinksSidebar(settingsSidebarSection, queryStringSettingsType);
            }

            if (selectedOperation !== null) {
                this.title = selectedOperation.Title;
                this.siteTitleDynamicResolver.updateBrowserTitleByText(this.title);
                this.configKey$.next(queryStringSettingsType.toLowerCase());
            }
        }));
    }

    @HostListener('window:beforeunload', ['$event'])
    canDeactivate(): boolean | Observable<boolean> {
        if (this.configSettingsComponent.arePropertiesChanged()) {
            return this.window.confirm(UNSAVED_CHANGES_DIALOG_MESSAGE);
        }

        return true;
    }

    private getOperation(operations: Operation[], configType: string): Operation {
        return operations.find(o => o.Parameters.findIndex(p => p.Name.toString() === SETTINGS_TYPE_KEY && p.Value.toString().toLowerCase() === configType.toLowerCase()) > -1);
    }

    private getFirstConfigProviderType(operations: Operation[]): string {
        let value: string = null;

        for (let index = 0; index < operations.length; index++) {
            const configurationModel = operations[index].Parameters.find(p => p.Name === SETTINGS_TYPE_KEY);
            if (configurationModel) {
                value = configurationModel.Value;
                break;
            }
        }

        return value;
    }

    private getSettingsSidebarSections(operations: Operation[]): SettingsSidebarSection[] {
        const settings: SettingsSidebarSection[] = [];

        const sectionGroups = groupBy(operations, f => {
            return f.Category ? f.Category.Name : SETTINGS_UNTITLED_TYPES
        });

        for (const key in sectionGroups) {
            let ordinal = 100;
            if (key === SETTINGS_CATEGORIES.ADVANCE_SETTINGS)
                ordinal = 10;
            else if (key === SETTINGS_CATEGORIES.BASIC_SETTINGS)
                ordinal = 20;

            const operations = sectionGroups[key];
            operations.forEach((operation: Operation) => {
                const configurationModel = operation.Parameters.find(x => x.Name === SETTINGS_TYPE_KEY);
                if (configurationModel && !operation.Link && configurationModel.Value) {
                    operation.token = {
                        type: NavigateCommand,
                        properties: {
                            indexUrl: `${ROUTE_PATHS.CONFIGURATIONS}/${ROUTE_PATHS_NO_PREFIX.BASIC_SETTINGS}`,
                            additionalQueryParams: {
                                [QUERY_PARAMS.TYPE]: configurationModel.Value.toLowerCase()
                            }
                        }
                    };
                }
            });

            settings.push({
                operations: operations,
                ordinal: ordinal,
                title: this.getTitle(key),
            })
        }

        return settings;
    }

    private getTitle(key: string) {
        const title = key !== SETTINGS_UNTITLED_TYPES ? key : stringConstants.EMPTY_STRING;
        return capitalizeFirstLetter(title.toLowerCase());
    }

    private getSettingTypeFromQueryString(parameterKey: string): Observable<string> {
        return this.route.queryParams.pipe(map(params => params[parameterKey]));
    }

    private configureBasicSettingsLinksSidebar(sections: SettingsSidebarSection[], queryStringSettingsType: string): void {
        const sidebarData: SidebarData = {
            entityType: null,
            externalKey: "basicSettingsLinks",
            buttons: [],
        };

        const settingsSidebarComponentData: SidebarComponentData = {
            type: ListItemSettingsSidebarComponent,
            title: BROWSE_SETTINGS,
            updatePropertiesOnChange: true,
            removePreviousView: true,
            properties: {
                sections: sections
            },
            afterComponentInit: (component: ListItemSettingsSidebarComponent) => {
                if (queryStringSettingsType) {
                    component.selectedSettingName = queryStringSettingsType.toLowerCase();
                }
            }
        };

        sidebarData.buttons.push({
            title: BROWSE_SETTINGS,
            icon: "cog",
            data: settingsSidebarComponentData,
            name: "settings",
            look: DEFAULT_SIDEBAR_BUTTON_LOOK
        });

        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.configure(sidebarData));
        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.changeAndOpen(sidebarData.buttons[0], false));
    }
}
