import { timer as observableTimer, Observable } from "rxjs";

import { map, filter, delayWhen } from "rxjs/operators";
import { toLoadingState } from "./toLoadingState";

export interface LoadingState {
    /** Used to signify whether the information represented by the object`s state is being loaded or not.
     * Example: Let`s have a source observable that emits info about a page and a subscriber that displays the info.
     * If the subscriber receives the page model object with isLoading set to true, it should consider the previously
     * received info about the page outdated and update the displayed info accordingly -> show loading bar etc.
     * Once the subscriber receives a page model with that flag set to false, it should update the view with the values
     * from that model and hide the loading bar.
     */
    isLoading: boolean;
}

/**
 * Delays the emission of the next emitted value after a value with the flag isLoading set to true is received.
 * @param source The source observable to which this operator is applied
 * @param minimumDelay The minimum delay since a value with isLoading set to true is received and the next received value is emitted
 */
export const delayEmission = (minimumDelay: number) => <TState extends LoadingState>(source: Observable<TState>): Observable<TState> => {
    let startTime: number = null;

    const delayedSource$ = source.pipe(delayWhen((state) => {
        let time = 0;
        if (state.isLoading) {
            startTime = new Date().getTime();
        } else {
            if (startTime !== null) {
                const endTime = new Date().getTime();
                const elapsed = (endTime - startTime);
                let remaining = minimumDelay - elapsed;
                if (remaining < 0) {
                    remaining = 0;
                }

                time = remaining;
            }
        }

        return observableTimer(time);
    }));

    return delayedSource$;
};

/**
 * Used to make a delay from the time we subsribe to observable and the first emitted value is received.
 * Useful for observables that wrap http requests where the delay operator adds to the initial delay of the http request.
 * For example: if the http request takes 200ms and we apply the stadnard delay operator with 500ms. The total delay will be 700ms
 * whereas if we use delayEmissionWrapper with 500ms that will be the actual time since the subsription and the received value.
 * @param this The source observable to which this operator is applied
 * @param minimumDelay The minimum delay since we subscribed and the next received value is emitted
 */
export const delayFirstEmission = (minimumDelay: number) => <T>(source: Observable<T>): Observable<T> => {
    return source.pipe(
        toLoadingState<T>(),
        delayEmission(minimumDelay),
        filter(x => !x.isLoading),
        map(x => x.content));
};
