import { Component, OnInit, Input } from "@angular/core";
import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-share-preview-link",
    templateUrl: "./share-preview-link.component.html"
})
export class SharePreviewLinkComponent extends SfRxBase implements OnInit {
    @Input() dataItem: DataItem;

    isLoading: boolean = true;
    previewLink: string;
    expirationMessage: string;

    constructor(private itemService: DynamicItemService) {
        super();
    }

    ngOnInit(): void {
        this.getPreviewLink();
    }

    private getPreviewLink() {
        const sharePreviewLinkFunction = this.itemService.executeBoundFunction<any>(this.dataItem, `Default.SharePreviewLink`);
        const sharePreviewLinkSubscription = sharePreviewLinkFunction.subscribe((result: PreviewLink) => {
            this.previewLink = result.PreviewLink;
            this.expirationMessage = result.ExpirationMessage;
            this.isLoading = false;
        });

        this.registerSubscription(sharePreviewLinkSubscription);
    }
}

interface PreviewLink {
    ExpirationMessage: string;
    PreviewLink: string;
}
