import { Injectable } from "@angular/core";

import { ROUTE_PARAMS } from "../../../constants";
import { ActivatedRouteSnapshot } from "@angular/router";

// TODO
@Injectable()
export class DynamicItemStrategyBase {

    static getSet(route: ActivatedRouteSnapshot) {
        const routeParams = route.params;
        const currentSet = routeParams[ROUTE_PARAMS.CHILD_SET_SEGMENT] || routeParams[ROUTE_PARAMS.TYPE_NAME_SEGMENT] || route.data[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
        return currentSet;
    }
}
