import { EventTimeCompositeComponent, EventData } from "./event-time.composite.component";
import { Component, OnInit, AfterViewInit } from "@angular/core";
import { EVENT_PROPERTIES } from "../events.constants";
import { DateTimePickerComponent } from "../../../../../../../fields/date-time/date-time-picker.component";

const formProperties = [
    EVENT_PROPERTIES.EVENT_START,
    EVENT_PROPERTIES.EVENT_END,
    EVENT_PROPERTIES.ALL_DAY_EVENT,
    EVENT_PROPERTIES.TIME_ZONE_ID
];

@Component({
    templateUrl: "./event-time.composite.readonly.component.html"
})
export class EventTimeCompositeReadonlyComponent extends EventTimeCompositeComponent implements OnInit, AfterViewInit {
    ngAfterViewInit(): void {
        super.ngAfterViewInit();

        const datePickerWrapperComponents = Array.from(this.propertyFieldMap.values())
            .filter(wrapper => wrapper && wrapper.currentInstance instanceof DateTimePickerComponent);
        if (!datePickerWrapperComponents.length) {
            return;
        }

        const datePickers = datePickerWrapperComponents.map(f => f.currentInstance);
        datePickers.forEach((p: DateTimePickerComponent) => p.showTime = !this.isAllDayEvent);

        if (this.settings.dataItem && this.settings.dataItem.data && this.settings.dataItem.data[EVENT_PROPERTIES.RECURRENCE_EXPRESSION]) {
            datePickers[1].showDate = false;
        }

        const hideLabel = datePickers.every(x => !x.showTime && !x.showDate);
        if (hideLabel) {
            super.toggleLabelVisibility(datePickerWrapperComponents[1], false);
        }

        const controls = this.form.controls;
        const data = {};

        formProperties.forEach(prop => {
            if (controls[prop]) {
                data[prop] = controls[prop].value;
            }
        });

        this.writeValue(data as EventData);
    }
}
