import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { Observable } from "rxjs";
import { UserDataStore, UserData } from "./user-data.store";

@Injectable()
export class UserDataStoreResolver implements Resolve<any> {
    constructor(private userDataStore: UserDataStore) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<UserData> | UserData {
        return this.userDataStore.initialize();
    }
}
