import { EntityDataResolver } from "../../../content/dynamic-modules/services/backend-tweaks/entity-data.resolver";
import { ActivatedRouteSnapshot } from "@angular/router";
import { MetadataContainer } from "../../../shared/services/metadata/meta-data.store";
import { ROUTE_PARAMS, FILTER_PARAMS } from "../../../content/constants";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { Injectable, ClassProvider } from "@angular/core";
import { EntityData } from "../../../content/dynamic-modules/interfaces";
import { MediaHelpers } from "../media.helpers";

@Injectable()
export class MediaEntityDataResolver extends EntityDataResolver {
    resolve(route: ActivatedRouteSnapshot, container: MetadataContainer, culture: string, provider: string): EntityData {
        const routeSetName = route.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT] || route.parent.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
        const shouldResolveChildEntity = this.shouldResolveChildEntity(route);
        const setName = shouldResolveChildEntity ? MediaHelpers.resolveMediaSetName(routeSetName) : MediaHelpers.resolveLibrarySetName(routeSetName);

        return {
            culture,
            provider,
            metadata: container.entities[setName]
        };
    }

    canResolve(entitySet: string): boolean {
        return entitySet === ENTITY_SET.IMAGES || entitySet === ENTITY_SET.DOCUMENTS || entitySet === ENTITY_SET.VIDEOS;
    }

    private shouldResolveChildEntity(route: ActivatedRouteSnapshot) {
        const isEdit = route.params[ROUTE_PARAMS.ITEM_ID] || route.params[ROUTE_PARAMS.EDIT_SEGMENT];
        const hasSearch =  route.queryParams[FILTER_PARAMS.SEARCH];

        if (hasSearch) {
            return true;
        }
        if (isEdit) {
            return true;
        }

        if (!route.params[ROUTE_PARAMS.CHILD_SET_SEGMENT]) {
            return false;
        }

        return true;
    }
}

export const MEDIA_ENTITY_DATA_PROVIDER: ClassProvider = {
    provide: EntityDataResolver,
    useClass: MediaEntityDataResolver,
    multi: true
};
