import { Input, Component, Output, EventEmitter } from "@angular/core";
import { Operation } from "../../action-menu/operation.model";
import { ActionButton } from "../../action-menu/action-menu-model";
import { Observable } from "rxjs";

@Component({
    templateUrl: "./action-notification.component.html"
})
export class ActionNotificationComponent {
    @Input() title: string;
    @Input() description: string;
    @Input() operations: Observable<Operation[]>;
    @Output() onActionButtonClicked = new EventEmitter<ActionButton>();

    onActionButtonClickedHandler(button: ActionButton): void {
        this.onActionButtonClicked.emit(button);
    }
}
