import { HttpClient } from "@angular/common/http";
import { Inject, Injectable } from "@angular/core";
import { BehaviorSubject, Observable } from "rxjs";
import { map } from "rxjs/operators";
import { ExternalAppConfig, ExternalAppConfigService } from "../../src/app/app-config/external-app-config.service";
import { environmentTypes } from "../../src/app/environment";
import { EnvironmentService } from "../../src/app/modules/shared/services/environment.service";
import { UrlService } from "../../src/app/services/url.service";
import { WINDOW_TOKEN } from "../../src/app/window.provider";
import { DateFormat } from "./date-time-picker.component";
import { DATE_FORMATS_WHITELIST, TIME_FORMATS_WHITELIST, DEFAULT_TIME_FORMAT, DEFAULT_DATE_FORMAT } from "./date-time-picker.constants";

@Injectable()
export class DateTimeFormatsProvider {

    constructor(
        private envService: EnvironmentService,
        private urlService: UrlService,
        private http: HttpClient,
        private appConfigService: ExternalAppConfigService,
        @Inject(WINDOW_TOKEN) private window: Window
    ) {
    }

    getDateAndTimeFormats(): Observable<DateTimeFormatDto> {
        const result: DateTimeFormatDto = {
            dateFormat: DEFAULT_DATE_FORMAT,
            timeFormat: DEFAULT_TIME_FORMAT
        };

        const config: ExternalAppConfig = this.appConfigService?.externalConfig;

        if (config && config.dateTimeFormat) {
            if (config.dateTimeFormat.useBrowserLocale) {
                const locale = this.window.navigator.language;

                let url = `/assets/date-time-formats/date-time-formats.json`;
                if (this.envService.getEnvironment() === environmentTypes.integration) {
                    url = this.urlService.getResourceUrl(url);
                }

                return this.http.get<DateFormat[]>(url).pipe(map(json => {
                    if (json) {
                        const formatData = json.find(x => x.Culture === locale);

                        if (formatData) {
                            const normalized = config.dateTimeFormat.browserLocaleFormatWidth.toLowerCase();

                            if (normalized === "long") {
                                result.timeFormat = formatData.LongTimePattern;
                                result.dateFormat = formatData.LongDatePattern;
                            } else {
                                result.timeFormat = formatData.ShortTimePattern;
                                result.dateFormat = formatData.ShortDatePattern;
                            }
                        }

                        return result;
                    }
                }));
            } else {
                if (config.dateTimeFormat.dateFormat && DATE_FORMATS_WHITELIST.includes(config.dateTimeFormat.dateFormat))
                    result.dateFormat = config.dateTimeFormat.dateFormat;
                if (config.dateTimeFormat.timeFormat && TIME_FORMATS_WHITELIST.includes(config.dateTimeFormat.timeFormat))
                    result.timeFormat = config.dateTimeFormat.timeFormat;
            }
        }

        return new BehaviorSubject(result);
    }
}

export interface DateTimeFormatDto {
    dateFormat: string,
    timeFormat: string
}
