import { ClassProvider, Injectable } from "@angular/core";
import { FieldRegistration, FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { FIELDS_PROVIDER_TOKEN, FieldRegistryKey, DefaultFieldsProvider } from "../../../shared/fields-builder/providers/fields-registration-provider";
import { PropertyEditorWidgets } from "../../property-editor.constants";
import { ChoiceChipComponent } from "../../../../../../fields/choice/choice-chip.component";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { ChoiceMultipleComponent } from "../../../../../../fields/choice/choice-multiple.component";
import { ChoiceComponent } from "../../../../../../fields/choice/choice.component";
import { ViewSelectorComponent } from "./view-selector/view-selector.component";
import { ChoiceReadOnlyComponent } from "../../../../../../fields/choice/choice-readOnly.component";

const DEFAULT_CHOICE_ICON_LOOK = "size-xs color-inherit";

@Injectable()
export class EnumFieldProvider extends DefaultFieldsProvider {
    overrideField(fieldRegistryKey: FieldRegistryKey): FieldRegistration {
        if (fieldRegistryKey.fieldType === FieldTypes.choiceChip && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ChoiceChipComponent,
                settingsType: EnumChoiceSettings
            };
        if (fieldRegistryKey.fieldType === FieldTypes.choiceMultiple && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ChoiceMultipleComponent,
                settingsType: EnumChoiceSettings
            };
        if (fieldRegistryKey.fieldType === FieldTypes.choiceDropDown && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ChoiceDropdownComponent,
                settingsType: EnumDropdownChoiceSettings
            };

        if (fieldRegistryKey.fieldType === FieldTypes.viewSelector && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ViewSelectorComponent,
                settingsType: EnumDropdownChoiceSettings
            };

        if (fieldRegistryKey.fieldType === FieldTypes.choice && fieldRegistryKey.typeName && fieldRegistryKey.typeName.startsWith(PropertyEditorWidgets.FIELD_TYPE_KEY))
            return {
                writeComponent: ChoiceComponent,
                readComponent: ChoiceReadOnlyComponent,
                settingsType: RadioChoiceSettings
            };
    }
}

export class EnumChoiceSettings extends ChoiceSettings {
    public choiceNotResponsive: false;
    public init(metadata: any) {
        super.init(metadata);
        this.choices = [];
        const choicesArray = this.mapIconChoice(metadata.choices);
        for (let i = 0; i < choicesArray.length; i++) {
            this.choices.push({ Name: choicesArray[i].Name, Title: choicesArray[i].Title, Value: choicesArray[i].Value, ...choicesArray[i].Icon && { Icon: choicesArray[i].Icon } });
        }

        this.hasFieldset = this["choicesAllowMultiple"];
    }

    private mapIconChoice(choices: string) {
        if (!choices)
            return [];

        const choicesArray = JSON.parse(choices);
        choicesArray.forEach((choice) => {
            if (choice.Value && choice.Value === "None") {
                choice["Icon"] = { Name: "ban", Look: DEFAULT_CHOICE_ICON_LOOK };
                // Handle the case when the configuration from the server provides only icon name (e.g. \"Icon\":\"ban\")
            } else if (choice["Icon"] && !choice["Icon"].Name) {
                choice["Icon"] = { Name: choice["Icon"], Look: DEFAULT_CHOICE_ICON_LOOK };
            }
        });

        return choicesArray;
    }
}

export class EnumDropdownChoiceSettings extends ChoiceSettings {
    public init(metadata: any) {
        super.init(metadata);
        this.choices = [];
        if (metadata.choices) {
            const choicesArray = JSON.parse(metadata.choices);
            for (let i = 0; i < choicesArray.length; i++) {
                this.choices.push({ Name: choicesArray[i].Title, Title: choicesArray[i].Title, Value: choicesArray[i].Value, ...choicesArray[i].Icon && { Icon: choicesArray[i].Icon } });
            }
        }

        this.look = "inline";
    }
}

export class RadioChoiceSettings extends ChoiceSettings {
    public init(metadata: any) {
        super.init(metadata);
        this.choices = [];
        if (metadata.choices) {
            const choicesArray = JSON.parse(metadata.choices);
            for (let i = 0; i < choicesArray.length; i++) {
                this.choices.push({ Name: choicesArray[i].Title, Title: choicesArray[i].Title, Value: choicesArray[i].Value, ...choicesArray[i].Icon && { Icon: choicesArray[i].Icon } });
            }
        }
    }
}

export const ENUM_FIELD_PROVIDER: ClassProvider = {
    provide: FIELDS_PROVIDER_TOKEN,
    useClass: EnumFieldProvider,
    multi: true
};
