import { map } from "rxjs/operators";
import { Component, OnInit, HostBinding } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";

import { ModulesProvider, ModuleData } from "./modules.provider";
import { Observable } from "rxjs";
import { NavbarConfiguration, NavbarModes, LeftNavbarButtonMode } from "../shared/components/navigation/navigation-menu/navigation-menu.component";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../constants/route-paths";

const menuTwoColumnsBreak = 7;
const menuThreeColumnsBreak = 13;

@Component({
    selector: "sf-content",
    templateUrl: "./content.component.html"
})
export class ContentComponent implements OnInit {

    @HostBinding ("class") classes = "sf-host -animated";

    twoColumnsBreak = menuTwoColumnsBreak;
    threeColumnsBreak = menuThreeColumnsBreak;
    closeButtonAnimationCondition: string = "";
    columns: Observable<Array<ModuleData>>;
    centered: Observable<boolean>;
    navbarConfiguration: NavbarConfiguration;
    contentRoute: string = `/${ROUTE_PATHS.CONTENT}`;

    constructor(private modulesProvider: ModulesProvider,
                private route: ActivatedRoute,
                private router: Router) {
    }

    ngOnInit() {
        this.navbarConfiguration = {
            leftNavbarButtonData: {
                look: "toggle",
                icon: "times",
                show: false,
                mode: LeftNavbarButtonMode.Close
            },
            mode: NavbarModes.None,
            look: "in-menu",
            isScrollEnabled: false
        };
        this.columns = this.modulesProvider.getModules();
        this.centered = this.columns.pipe(map((columns) => {
            if (columns.length === 1) {
                if (columns[0].types.length < this.threeColumnsBreak)
                    return true;
            } else if (columns.length === 2) {
                if (columns[0].types.length < this.twoColumnsBreak && columns[1].types.length < this.twoColumnsBreak)
                    return true;
            }

            return false;
        }));
    }

    onBack() {
        setTimeout(() => {
            if (this.route.outlet === ROUTE_PATHS_NO_PREFIX.MENU_OUTLET) {
                this.router.navigate([{ outlets: { menu: ROUTE_PATHS_NO_PREFIX.MENU_HOME } }], { relativeTo: this.route.parent });
            } else {
                this.router.navigate([ROUTE_PATHS.HOME]);
            }
        });
    }
}
