import { SettingsBase } from "./../field-settings-base";
import { FIELD_TYPE, CHOICE_FIELD_TYPE_LOWERCASE, MULTIPLE_CHOICE_FIELD_TYPE_LOWERCASE } from "../../src/app/modules/shared/services/metadata/meta-data-constants";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { FieldTypes } from "../../src/app/modules/shared/fields-builder/services/fields-registry";

const DEFAULT_VALUE = "default";

export class ChoiceSettings extends SettingsBase {
    public choices: Array<ChoiceItem> = [];
    public look: string;
    public unsupportedValueText: string;
    public choiceServiceUrl?: string;
    public choiceServiceCallParameters?: string;
    public choiceServiceWarningMessage?: string;
    public choiceSideLabel?: string;
    // This setting is used for the yes-no field only.
    // It should be used when the title of the field and the option name are different.
    public optionName: string = null;
    // This setting is used for the yes-no field only.
    // It is used when the checkbox value should be visualized and sent reversed
    public isInverted: boolean = false;
    public choiceShowFriendlyName: boolean = false;

    // When the value for a choice field is null, the odata returns 0
    private emptyChoiceValues = [0, "0"];

    public init(metadata: any) {
        super.init(metadata);

        if (this.defaultValue === null && metadata[DEFAULT_VALUE]) {
            this.defaultValue = metadata[DEFAULT_VALUE];
        }

        if (metadata[FIELD_TYPE] && metadata[FIELD_TYPE].toLowerCase() === CHOICE_FIELD_TYPE_LOWERCASE) {
            this.markAsDirty = true;
        }

        if (metadata[FIELD_TYPE] && metadata[FIELD_TYPE].toLowerCase() === MULTIPLE_CHOICE_FIELD_TYPE_LOWERCASE) {
            this.useDefaultValue = false;
        }

        this.assignEmptyChoiceValues(metadata.choices);
    }

    public assignEmptyChoiceValues(choices: any) {
        let choicesArray = this.choices;
        try {
            choicesArray = [...choicesArray, ...JSON.parse(choices)];
        } catch {
            // try to parse choices from metadata if defined
        }

        this.emptyChoiceValues.forEach(emptyChoiceValue => {
            if (choicesArray && choicesArray.findIndex(choice => choice.Value === emptyChoiceValue) === -1) {
                this.emptyValues.push(emptyChoiceValue);
            }
        });
    }

    public updateHasFieldset(propertyValue: string | number) {
        if (propertyValue === null && (this.choices && this.choices.length >= 63)) {
            return this.hasFieldset = true;
        }

        const isBinaryChoiceValue = propertyValue && /^[0-1]{2,}$/.test(propertyValue.toString());
        if (this.type === FieldTypes.choiceDropDown && !isBinaryChoiceValue) {
            return this.hasFieldset = false;
        }

        this.hasFieldset = true;
    }
}
