import { Injectable } from "@angular/core";
import { FormGroup, FormControl } from "@angular/forms";
import { DomSanitizer, SafeUrl } from "@angular/platform-browser";
import { filename, getExtensionFromFileName } from "../../../../../utils";
import { FieldModel } from "../../../../../services/field.model";
import { Observable, from } from "rxjs";
import { Entity } from "../meta-data.store";
import { FileWrapper } from "../../../../libraries/media-handlers/media-handler.provider";
import { DamAsset } from "../../../../libraries/dam/dam-provider-base";

const TITLE = "Title";
export const IMAGE: string = "image";
const IMAGE_DOM_ELEMENT_NAME: string = "img";
const IMAGE_LOAD_EVENT: string = "load";
const IMAGE_WIDTH_PROPERTY: string = "width";
const IMAGE_HEIGHT_PROPERTY: string = "height";

const VIDEO: string = "video";
const VIDEO_DOM_ELEMENT_NAME: string = "video";
const VIDEO_LOAD_EVENT: string = "loadedmetadata";
const VIDEO_WIDTH_PROPERTY: string = "videoWidth";
const VIDEO_HEIGHT_PROPERTY: string = "videoHeight";

@Injectable()
export class FileInfoService {
    constructor(private sanitizer: DomSanitizer) { }

    createFileInfo(file: File, entityData: Entity): Promise<FileInfo> {
        return new Promise<FileInfo>((resolve, reject) => {
            const fileWrapper = file as FileWrapper;
            file = fileWrapper.file || file;
            const title = filename(file.name);
            const url = this.getUrl(file);
            const safeUrl = this.sanitizer.bypassSecurityTrustUrl(url);
            const result: FileInfo = {
                name: file.name,
                title: title,
                extension: getExtensionFromFileName(file.name),
                size: file.size,
                data: {},
                content: file,
                contentType: file.type,
                dataUrl: safeUrl,
                form: new FormGroup({ [TITLE]: new FormControl(title) }),
                isMultimedia: entityData.isMultimedia,
                isVideo: entityData.isVideo,
                isCorrupted: false,
                preserveFileName: fileWrapper?.preserveFileName,
                asset: fileWrapper.asset
            };

            if (entityData.isMultimedia) {
                this.getMediaSize(url, file.type)
                .then((fileData) => {
                    result.width = fileData.width;
                    result.height = fileData.height;
                    resolve(result);
                })
                .catch(() => {
                    result.isCorrupted = true;
                    resolve(result);
                });
            } else {
                resolve(result);
            }
        });
    }

    createFileInfo$(file: File, entity: Entity): Observable<FileInfo> {
        const promise = this.createFileInfo(file, entity);
        return from(promise);
    }

    getMediaSize(dataURL: string, mediaType: string): Promise<FileData> {
        if (mediaType.includes(`${IMAGE}/`)) {
            return this.getMediaSizeInternal(dataURL, IMAGE_LOAD_EVENT, IMAGE_DOM_ELEMENT_NAME, IMAGE_WIDTH_PROPERTY, IMAGE_HEIGHT_PROPERTY);
        } else if (mediaType.includes(`${VIDEO}/`)) {
            return this.getMediaSizeInternal(dataURL, VIDEO_LOAD_EVENT, VIDEO_DOM_ELEMENT_NAME, VIDEO_WIDTH_PROPERTY, VIDEO_HEIGHT_PROPERTY);
        } else {
            return Promise.resolve({
                isCorrupted: false
            });
        }
    }

    protected getUrl(file: File): string {
        return window.URL.createObjectURL(file);
    }

    private getMediaSizeInternal(dataURL: string, loadEventName: string, domElementName: string, widthPropertyName: string, heightPropertyName: string): Promise<FileData> {
        return new Promise((resolve, reject) => {
            const mediaElement = document.createElement(domElementName) as HTMLImageElement | HTMLVideoElement;

            mediaElement.addEventListener(loadEventName, (e) => {
                const result = {
                    width: mediaElement[widthPropertyName],
                    height: mediaElement[heightPropertyName],
                    isCorrupted: false
                };
                mediaElement.remove();

                resolve(result);
            });

            mediaElement.addEventListener("error", (err) => {
                mediaElement.remove();
                reject(err);
            });

            mediaElement.src = dataURL;
        });
    }
}

export interface FileInfo {
    name: string;
    title: string;
    extension: string;
    size: number;
    data: any,
    dataUrl: SafeUrl;
    content: File;
    contentType: string;
    form: FormGroup;
    fields?: FieldModel[];
    isMultimedia: boolean;
    isCorrupted: boolean;
    width?: number;
    height?: number;
    errors?: string[];
    isVideo?: boolean;
    preserveFileName?: boolean;
    asset?: DamAsset;
}

export interface FileData {
    isCorrupted?: boolean;
    width?: number;
    height?: number;
}
