import { Injectable } from "@angular/core";
import { FormFieldWrapperComponent } from "../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../shared/fields-builder/services/field-change/field-change.service";
import { Properties } from "../shared/fields.constants";
import { PropertyEditorWidgets } from "../widget-editor/property-editor.constants";

@Injectable()
export class ImageWidgetFieldChangeService implements FieldChangeService {

    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === Properties.ITEM && changedValue && changedValue.Id) {
            const itemField = fields.find(x => x.fieldModel.key === changedFieldName);
            if (!(itemField as any).value || ((itemField as any).value?.Id && (itemField as any).value.Id !== changedValue.Id)) {
                this.modifyField(Properties.TITLE, changedValue, fields);
                this.modifyField(Properties.ALTERNATIVE_TEXT, changedValue, fields);
            }

            const thumbnailField = fields.find(x => x.fieldModel.key === "Thumnail");
            if (thumbnailField && (!thumbnailField.getValue() || ((itemField as any).value?.Id && (itemField as any).value.Id !== changedValue.Id))) {
                thumbnailField.writeValue(changedValue?.Url);
            }
        }
    }

    private modifyField(fieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]) {
        if (changedValue[fieldName]) {
            const foundField = fields.find(x => x.fieldModel.key === fieldName);
            if (foundField) {
                foundField.writeValue(changedValue[fieldName]);
            }
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === PropertyEditorWidgets.IMAGE;
    }
}

export const IMAGE_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: ImageWidgetFieldChangeService,
    multi: true
};
