import { map, debounceTime } from "rxjs/operators";
import { DynamicItemStore } from "./../../services/dynamic-item.store";
import { Component, Input, Inject, OnInit, ViewChild } from "@angular/core";

import { EntityData, DataItem } from "../../interfaces";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { ColumnModel } from "../../../../shared/models/column-model";
import { Properties } from "../../../../shared/fields.constants";
import { MainFieldComponent } from "../grid-cells/main-field/main-field.component";
import { createQuery } from "../../../../../services/query";
import { ItemsState, StateWrapper } from "../../services/dynamic-item-store-state";
import { Observable, Subject, Subscription } from "rxjs";
import { ACTIONS, BLUR_EFFECT_TIMEOUT } from "../../../constants";
import { stringConstants } from "../../../../../common-constants";
import { delayEmission } from "../../../../shared/rxjs-extensions";
import { SEARCH_DEBOUNCE_TIME } from "../../../../../../../fields/selector/selector.component";
import { SfInputComponent, SfRxBase } from "@progress/sitefinity-component-framework";
import { CONTENT_ITEM_FULL_NAME } from "../../../../shared/services/metadata/meta-data-constants";

const SEARCH = "Search";

@Component({
    templateUrl: "./dynamic-sidebar.component.html"
})
export class DynamicSidebarComponent extends SfRxBase implements OnInit {
    @Input() public selectionChanged: ItemSelectonChanged;

    @Input() public onClearFilter: () => void;

    @Input() public selectedItem: DataItem;

    @Input() public parentId: string;

    @Input() public data$: Observable<DynamicSidebarData>;

    @Input() sortParameter: string;

    @ViewChild(SfInputComponent, { static: false }) searchInput: SfInputComponent;

    public searchValue: string = stringConstants.EMPTY_STRING;
    public placeholderText: string = SEARCH + stringConstants.ELLIPSIS;
    public isSearched: boolean = false;
    public sidebarItemList$: Observable<ItemsState>;
    public hasItemStatusIcon: boolean = true;

    private skip: number = 0;
    private filter: string = null;
    private defaultFieldName: string;
    private columns = new Array<ColumnModel>();
    private entityData: EntityData;
    private filterValue: string = null;
    private search$ = new Subject<string>();
    private itemsSubscription: Subscription;
    private areItemsCleared: boolean;

    constructor(private dynamicItemStore: DynamicItemStore,
                @Inject(WINDOW_TOKEN) private window: Window) {
        super();
    }

    get areItemsFiltered() {
        return this.isSearched || this.filterValue;
    }

    ngOnInit(): void {
        const subscription = this.data$.subscribe(data => {
            const newEntityData = data.entityData;
            if (newEntityData.metadata.typeFullName === CONTENT_ITEM_FULL_NAME) {
                this.hasItemStatusIcon = false;
            }

            if (this.filterValue !== data.filterValue) {
                this.filterValue = data.filterValue || null;
            }

            const shouldLoad = !this.entityData
                || this.entityData.metadata.setName !== newEntityData.metadata.setName
                || this.entityData.provider !== newEntityData.provider
                || this.entityData.culture !== newEntityData.culture;

            if (shouldLoad) {
                this.entityData = newEntityData;

                const displayName = this.entityData.metadata.displayName;

                if (displayName) {
                    this.placeholderText = SEARCH + stringConstants.INTERVAL + displayName.toLowerCase() + stringConstants.ELLIPSIS;
                }

                this.sidebarItemList$ = this.dynamicItemStore.getItems(newEntityData)
                    .pipe(
                        map(x => <StateWrapper>x),
                        delayEmission(BLUR_EFFECT_TIMEOUT)
                    );

                if (this.itemsSubscription) {
                    this.itemsSubscription.unsubscribe();
                }
                this.itemsSubscription = this.sidebarItemList$.subscribe((state) => {
                    if (this.searchInput && this.areItemsCleared) {
                        this.searchInput.focus();
                        this.areItemsCleared = false;
                    }
                });
                this.registerSubscription(this.itemsSubscription);

                if (newEntityData) {
                    this.defaultFieldName = newEntityData.metadata.defaultFieldName;
                }

                // TODO: we should pass properties with this as well
                this.columns = [];
                this.columns.push({
                    name: this.defaultFieldName,
                    title: this.defaultFieldName,
                    componentData: {
                        type: MainFieldComponent
                    },
                    hidden: false,
                    clickable: true,
                    css: this.hasItemStatusIcon ? stringConstants.EMPTY_STRING : "-sf-ml-3xs"
                });

                this.loadItems(this.filterValue, this.searchValue);
            }
        });

        const searchSubscription = this.search$.pipe(debounceTime(SEARCH_DEBOUNCE_TIME)).subscribe((searchTerm: string) => {
            if (searchTerm && searchTerm !== stringConstants.EMPTY_STRING) {
                this.searchInternal(searchTerm);
            } else {
                this.clearInternal();
            }
        });

        this.registerSubscription(subscription);
        this.registerSubscription(searchSubscription);
    }

    onClearFilterHandler() {
        this.filterValue = null;
        this.loadItems();
        if (this.onClearFilter) {
            this.onClearFilter();
        }
    }

    onSelectionChanged(dataItem: DataItem) {
        this.window.scrollTo(0, 0);
        this.selectionChanged(dataItem);
    }

    loadMore(currentSize: number = 0, totalSize = 0): void {
        if (currentSize >= totalSize || this.skip === currentSize) {
            return;
        }

        this.skip = currentSize;
        this.loadItems(this.filter, this.searchValue, this.skip);
    }

    onSearch(search: string) {
        if (search.length !== 1) {
            this.search$.next(search);
        }
    }

    onClearSearch() {
        // TODO: Check later
        this.search$.next(null);
        this.searchInput.focus();
    }

    private loadItems(filter?: string, search?: string, skip: number = 0, take: number = 20): void {
        // TODO: there should be loading when switching between items
        const query = this.getSearchQuery(search);

        let action: string = null;
        if (filter) {
            action = ACTIONS.FILTER(filter);
        }

        this.dynamicItemStore.loadItems({
            entityData: this.entityData,
            action: action,
            query,
            fallbackProperties: [this.entityData.metadata.defaultFieldName],
            skip: skip,
            take: take,
            order: this.sortParameter
        });
    }

    private getSearchQuery(search: string) {
        let query;
        if (search || (this.parentId && this.entityData.metadata.hasParent)) {
            query = createQuery()
                .where()
                .and();

            if (search) {
                const searchValue = search.trim();
                query = query
                    .or()
                        .startsWith(this.defaultFieldName, searchValue)
                        .contains(this.defaultFieldName, `${stringConstants.INTERVAL}${searchValue}`)
                    .done();
            }

            if (this.parentId && this.entityData.metadata.hasParent) {
                query = query.eq(Properties.PARENT_ID, this.parentId);
            }

            query = query.done().done();
        }

        return query;
    }

    private searchInternal(search: string) {
        search = search || stringConstants.EMPTY_STRING;
        this.isSearched = !!search;
        this.filterValue = null;

        if (this.onClearFilter) {
            this.onClearFilter();
        }

        this.loadItems(null, search);
    }

    private clearInternal() {
        if (this.isSearched) {
            this.isSearched = false;
            this.loadItems();
            this.areItemsCleared = true;
        }
    }
}

export interface ItemSelectonChanged {
    (dataItem: DataItem): void;
}

export interface DynamicSidebarData {
    entityData: EntityData;
    filterValue: string;
}
