import { Component, ViewEncapsulation, Output, EventEmitter, Inject, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ActionButtonsStateService } from "../../../../shared/services/action-buttons-state.service";
import { ActionButton } from "../../../../shared/components/action-menu/action-menu-model";
import { ZoneEditorContract, WidgetOperationResult } from "../../../services/zone-editor.contract";
import { Subject, BehaviorSubject, Observable } from "rxjs";
import { Operation } from "../../../../shared/components/action-menu/operation.model";
import { DataItem, NavigateToEditArguments } from "../../../../content/dynamic-modules/interfaces";
import { WidgetPropertyEditorService } from "../../../../widget-editor/services/widget-property-editor.service";
import { ComponentModel } from "../model/component-model";
import { WidgetContext, WidgetLocalizationMode } from "../../../../widget-editor/models/widget-context";
import { ClosingContext } from "../../../../shared/services/modal-window.service";
import { stringConstants } from "../../../../../common-constants";
import { ZoneEditorDomService } from "../zone-editor-dom-service";
import { PropertyEditorViewModes, PropertyEditorOperations, CONTENT_BLOCK_OPERATIONS_VIEW_MODES, PropertyEditorWidgets } from "../../../../widget-editor/property-editor.constants";
import { ActionExecutorService } from "../../../../shared/services/action-executor.service";
import { LOCAL_STORAGE, StorageService } from "../../../../shared/services/storage.service";
import { PropertyData } from "../../../../widget-editor/interfaces/widget-editor";
import { ATTR_COMPONENT_ID, CLASS_ZONE_QUICKEDIT } from "../../../services/document-enhancer.constants";
import { SiteDataStore } from "../../../../shared/services/metadata/site-data.store";
import { GetWidgetMetadataArgs } from "../../../services/renderer.types";
import { ModalConfirmationComponent } from "../../../../shared/components/modal-confirmation/modal-confirmation.component";
import { QUERY_PARAMS } from "../../../../content/constants";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { WidgetMetadataMergerService } from "../../../services/widget-metadata.service";
import { QUICK_EDIT } from "../../../../content/dynamic-modules/components/action-buttons.resolver";
import { EditNavigationService } from "../../../../shared/services/edit-navigation.service";
import { MetadataStore } from "../../../../shared/services/metadata/meta-data.store";
import { ENTITY_SET, MEDIA_DATA_FIELD_NAME } from "../../../../shared/services/metadata/meta-data-constants";
import html2canvas from "html2canvas";
import { Properties } from "../../../../shared/fields.constants";
import { delayEmission } from "../../../../shared/rxjs-extensions";
import { LOADING_DELAY } from "../../../../widget-editor/widget-editor.component";

export const WIDGET_SETTINGS_KEY = "widget-settings";
export const CREATE_PRESET_OPERATION_KEY = `create-preset`;
export const LOCK_WIDGET_OPERATION_KEY = `lock-widget`;
export const UNLOCK_WIDGET_OPERATION_KEY = `unlock-widget`;
const pasteWidgetSettingsKey = `paste-${WIDGET_SETTINGS_KEY}`;
const copyWidgetSettingsKey = `copy-${WIDGET_SETTINGS_KEY}`;
const editWidgetOperationName = "edit";

@Component({
    providers: [ActionButtonsStateService],
    selector: "sf-inline-toolbar",
    templateUrl: "./inline-toolbar.component.html",
    styleUrls: ["./inline-toolbar.component.scss"],
    encapsulation: ViewEncapsulation.ShadowDom
})
export class InlineToolbarComponent implements OnInit {
    windowElement: Window;
    component: ComponentModel;
    dataItem: DataItem;
    segmentId: string;

    @Output() onOperationExecuted = new EventEmitter<WidgetOperationResult>();
    @Output() onFocusOut = new EventEmitter<void>();
    widgetOperations: BehaviorSubject<Operation[]> = new BehaviorSubject<Operation[]>([]);
    selectedOperationName: string;
    private originalOperations: Operation[] = [];

    constructor(
        @Inject(LOCAL_STORAGE) private storage: StorageService,
        private actionService: ActionExecutorService,
        private route: ActivatedRoute,
        private widgetPropertyEditorService: WidgetPropertyEditorService,
        private contract: ZoneEditorContract,
        private metadataService: WidgetMetadataMergerService,
        private siteDataStore: SiteDataStore,
        private zoneEditorDomService: ZoneEditorDomService,
        private editNavigationService: EditNavigationService,
        private metadataStore: MetadataStore) {

    }

    ngOnInit() {
        const widgetSettings = this.getWidgetSettings();
        if (widgetSettings) {
            const oneHour = 60 * 60 * 1000;
            if (new Date().getTime() - widgetSettings.time > oneHour) {
                this.storage.removeItem(WIDGET_SETTINGS_KEY);
            }
        }
    }

    loadOperations(operations: Operation[]) {
        if (this.component.name === PropertyEditorWidgets.SECTION || this.component.name === PropertyEditorWidgets.FORM_SECTION || this.component.hasquickeditoperation) {
            if (this.component.addAllowed) {
                operations.splice(1, 0, { Name: QUICK_EDIT, Title: "Change layout", Category: { Name: "General" }});
            }
        }

        this.originalOperations = operations;
        operations = this.filterOperations(operations);

        if (this.component.isPersonalized) {
            for (let i = 0; i < operations.length; i++) {
                const currentOperation = operations[i];
                if (currentOperation.ContextParameters && currentOperation.ContextParameters.length > 0) {
                    const segment = currentOperation.ContextParameters.find(x => x.Name === QUERY_PARAMS.WIDGET_SEGMENT_ID);
                    if (segment && this.component.widgetSegmentId === segment.Value) {
                        this.selectedOperationName = currentOperation.Name;
                    }
                }
            }

            if (!this.selectedOperationName) {
                this.selectedOperationName = stringConstants.DEFAULT_GUID;
            }
        }

        this.widgetOperations.next(operations);
    }

    refreshOperations() {
        const filtered = this.filterOperations(this.originalOperations);
        if (filtered.length !== this.widgetOperations.getValue().length) {
            this.widgetOperations.next(filtered);
        }
    }

    onActionButtonClicked(action: ActionButton) {
        const widgetId = this.component.id;

        if (action.sourceOperation.Name === "edit") {
            this.handleEdit(widgetId, action);
        } else if (action.sourceOperation.Name === QUICK_EDIT) {
            this.handleQuickEdit(widgetId, action);
        } else if (action.sourceOperation.Name === copyWidgetSettingsKey) {
            this.handleCopySettings(widgetId, action);
        } else if (action.sourceOperation.Name.startsWith(pasteWidgetSettingsKey)) {
            // TODO: show notification
            this.handlePasteSettings(widgetId, action);
        } else if (action.sourceOperation.Name.startsWith(CREATE_PRESET_OPERATION_KEY)) {
            this.handleCreatePreset(widgetId, action);
        } else if (CONTENT_BLOCK_OPERATIONS_VIEW_MODES[action.sourceOperation.Name]) {
            const view = CONTENT_BLOCK_OPERATIONS_VIEW_MODES[action.sourceOperation.Name];
            this.openSpecialOperationsDialog(widgetId, action, view);
        } else {
            this.handleGeneric(widgetId, action);
        }
    }

    focusOut() {
        this.onFocusOut.next();
    }

    openEditDialog(widgetId: string, widgetName: string): Observable<ClosingContext> {
        const context = this.getWidgetContext(widgetId, widgetName);

        context.localizationMode = this.component.iscontentwidget ? WidgetLocalizationMode.Both : WidgetLocalizationMode.AlwaysSaveAllTranslations;
        context.viewName = stringConstants.EMPTY_STRING;
        context.viewKey = { viewName: PropertyEditorViewModes.BASIC, widgetName: context.widgetName };
        return this.widgetPropertyEditorService.initializeViewData(this.route.parent, context);
    }

    openQuickEditDialog(widgetId: string, widgetName: string): ComponentData {
        const context = this.getWidgetContext(widgetId, widgetName);

        context.isQuickEdit = true;
        context.localizationMode = this.component.iscontentwidget ? WidgetLocalizationMode.Both : WidgetLocalizationMode.AlwaysSaveAllTranslations;
        context.viewName = PropertyEditorViewModes.CHANGE_LAYOUT;
        context.viewKey = { viewName: PropertyEditorViewModes.CHANGE_LAYOUT, widgetName: context.widgetName };
        return this.widgetPropertyEditorService.initialzieQuickEdit(this.route.parent, context);
    }

    openSpecialOperationsDialog(widgetId: string, action: ActionButton, viewName: string) {
        const context = this.getWidgetContext(widgetId, this.component.name);
        context.viewName = viewName;
        context.viewKey = { viewName: viewName, widgetName: context.widgetName };
        this.widgetPropertyEditorService.initializeViewData(this.route.parent, context)
                .subscribe(closingContext => {
            if (closingContext && closingContext.data) {
                this.handleGeneric(widgetId, action, []);
            } else {
                this.focusOut();
            }
        });
    }

    private handleCreatePreset(widgetId: string, action: ActionButton) {
        const that = this;
        const section = this.windowElement.document.querySelector(`[${ATTR_COMPONENT_ID}='${widgetId}']`) as HTMLElement;
        section.querySelector(`sf-inline-toolbar`).setAttribute("data-html2canvas-ignore", "true");

        InlineToolbarComponent.getCanvas(section).then(function(canvas) {
            const imageData = {
                [Properties.URL]: canvas.toDataURL(),
                [Properties.MIME_TYPE]: "image/png",
                [Properties.HIDE_BACKGROUND]: true,
            };
            const imageDataItem = DataItem.from(imageData, that.metadataStore.getEntity(ENTITY_SET.IMAGES), null, null);
            const presetEntity = that.metadataStore.getEntity(ENTITY_SET.PRESETS);

            that.editNavigationService.navigateToEdit(new NavigateToEditArguments({
                dataItem: DataItem.emptyItem({ metadata: presetEntity, provider: null, culture: null }),
                route: that.route,
                prepopulatedFields: {
                    [MEDIA_DATA_FIELD_NAME]: imageDataItem,
                }
            })).subscribe(x => {
                let propertyData: PropertyData[] = [];
                if (x.success) {
                    propertyData = [{ Name: Properties.ID, Value: x.dataItem.key }];
                } else {
                    propertyData = [{ Name: Properties.THUMBNAIL, Value: x.component.editableFields.getFields(false)[Properties.THUMBNAIL] }]
                }

                that.handleGeneric(widgetId, action, propertyData, (result) => {
                    result.SkipRerender = true;
                });
            });
        });
    }

    static getCanvas(element: HTMLElement): Promise<HTMLCanvasElement> {
        return html2canvas(element);
    }


    private handlePasteSettings(widgetId: string, action: ActionButton) {
        const settings = this.storage.getItem(WIDGET_SETTINGS_KEY) as string;
        if (settings) {
            const parsed = JSON.parse(settings) as WidgetPropertiesSnapshot;
            this.handleGeneric(widgetId, action, parsed.properties);
        }
    }

    private handleCopySettings(widgetId: string, action: ActionButton) {
        this.handleGeneric(widgetId, action, undefined, (result) => {
            const dataToStore: WidgetPropertiesSnapshot = {
                time: new Date().getTime(),
                widgetType: this.component.name,
                properties: result.Properties
            };

            this.storage.setItem(WIDGET_SETTINGS_KEY, JSON.stringify(dataToStore));

            result.SkipRerender = true;
        });
    }

    private filterOperations(operations: Operation[]): Operation[] {
        let filteredOperations = this.filterPasteOperations(operations);
        filteredOperations = this.filterEditOperations(filteredOperations);
        filteredOperations = this.filterSectionOperations(filteredOperations);

        return filteredOperations;
    }

    private filterPasteOperations(operations: Operation[]): Operation[] {
        let removeOperation = false;
        const widgetSettings = this.getWidgetSettings();
        if (widgetSettings) {
            if (widgetSettings.widgetType !== this.component.name) {
                removeOperation = true;
            }
        } else {
            removeOperation = true;
        }

        if (removeOperation) {
            return operations.filter((operation) => {
                return !operation.Name.startsWith(pasteWidgetSettingsKey);
            });
        }

        return operations;
    }

    private filterEditOperations(operations: Operation[]): Operation[] {
        if (this.component.isemptyentity) {
            return operations.filter((operation) => {
                return operation.Name !== editWidgetOperationName;
            });
        }

        return operations;
    }

    private filterSectionOperations(operations: Operation[]): Operation[] {
        if (this.component.iscontentwidget) {
            return operations.filter((operation) => {
                return operation.Name !== CREATE_PRESET_OPERATION_KEY && operation.Name !== LOCK_WIDGET_OPERATION_KEY && operation.Name !== UNLOCK_WIDGET_OPERATION_KEY;
            });
        }

        return operations;
    }

    private getWidgetSettings(): WidgetPropertiesSnapshot {
        const widgetSettingsString = this.storage.getItem(WIDGET_SETTINGS_KEY) as string;
        if (widgetSettingsString)
            return JSON.parse(widgetSettingsString) as WidgetPropertiesSnapshot;

        return null;
    }

    private getWidgetContext(widgetId: string, widgetName: string): WidgetContext {
        const context = new WidgetContext();
        context.widgetId = widgetId;
        context.entityId = this.dataItem.key;
        context.widgetName = widgetName;
        context.culture = this.dataItem.culture;
        context.component = this.component;
        context.window = this.windowElement;
        context.segmentId = this.segmentId;
        context.widgetSegmentId = this.component.widgetSegmentId;
        return context;
    }

    private handleEdit(widgetId: string, action: ActionButton) {
        this.openEditDialog(widgetId, this.component.name).subscribe((closingContext) => {
            if (closingContext && closingContext.data) {
                this.onOperationExecuted.next({
                    Success: true,
                    SourceOperation: action.sourceOperation
                });
            } else {
                this.focusOut();
            }
        });
        return;
    }

    private handleQuickEdit(widgetId: string, action: ActionButton) {
        const compData = this.openQuickEditDialog(widgetId, this.component.name);
        const quickEditRefernce = this.zoneEditorDomService.createComponent(compData.type, compData.properties);
        quickEditRefernce.instance.setCloseModalCallback((closingContext) => {
            if (closingContext.SourceOperation.Name !== PropertyEditorOperations.CANCEL) {
                this.onOperationExecuted.next({
                    Success: true,
                    SourceOperation: action.sourceOperation
                });
            } else if (this.component.quickEditMenu) {
                this.component.quickEditMenu = null;
                this.zoneEditorDomService.removeComponent(quickEditRefernce);
            }
        });

        const loadingSub = quickEditRefernce.instance.loading.pipe(delayEmission(LOADING_DELAY)).subscribe(x => {
            if (!x.isLoading) {
                this.focusOut();
                loadingSub.unsubscribe();
            }
        });

        this.component.quickEditMenu = quickEditRefernce;
        this.zoneEditorDomService.attachComponentAsFirstChild(quickEditRefernce, this.component.domElement, CLASS_ZONE_QUICKEDIT, null);
    }

    private handleGeneric(widgetId: string, action: ActionButton, parameters: PropertyData[] = [], callback?: (result: WidgetOperationResult) => void) {
        const executeAction = (parametersFromDialog: { [key: string]: string } = {}) => {
            this.siteDataStore.getValue().subscribe((siteData) => {
                const getWidgetMetadataArgs: GetWidgetMetadataArgs = {
                    dataItem: this.dataItem,
                    widgetKey: widgetId,
                    widgetName: this.component.name,
                    siteId: siteData.Id
                };

                this.metadataService.getWidgetMetadata(getWidgetMetadataArgs).subscribe((metadata) => {
                    const flatMetadata = metadata.PropertyMetadataFlat.map(p => {
                        return { Name: p.Name, Title: p.Title, Type: p.Type, DefaultValue: p.DefaultValue, Properties: (<any>p).Properties};
                    });

                    Object.keys(parametersFromDialog).forEach((key) => {
                        parameters.push({ Name: key, Value: parametersFromDialog[key] });
                    });

                    if (action.sourceOperation.ExecuteOnServer) {
                        const widgetSegmentParam = action.sourceOperation.ContextParameters.find(x => x.Name === QUERY_PARAMS.WIDGET_SEGMENT_ID);
                        this.contract.executeWidgetOperation(this.dataItem, widgetId, action.sourceOperation, parameters, flatMetadata, this.segmentId, widgetSegmentParam?.Value || this.component.widgetSegmentId).subscribe((result) => {
                            result.SourceOperation = action.sourceOperation;
                            if (callback)
                                callback(result);

                            this.onOperationExecuted.next(result);
                        });
                    } else {
                        this.onOperationExecuted.next({
                            Success: true,
                            SourceOperation: action.sourceOperation
                        });
                    }
                });
            });
        };

        if (action.sourceOperation.RequiresConfirmation) {
            this.actionService.actionConfirmHandler({
                route: this.route,
                actionButton: action,
                actionButtonStateService: null,
                window: this.windowElement
            }).subscribe((x => {
                const dialogResultData = x.dialogResult.data;
                if (dialogResultData && dialogResultData.data) {
                    const editableFields = (x.dialogResult.component as ModalConfirmationComponent).editableFields;
                    let fields;
                    if (editableFields)
                        fields = editableFields.getFields(false);
                    executeAction(fields);
                }
            }));
        } else {
            executeAction();
        }
    }
}

export interface ExecuteWidgetOperation {
    dataItem: DataItem,
    widgetId: string,
    operation: Operation
}

export interface LoadWidgetOperations {
    dataItem: DataItem,
    widgetId?: string,
    widgetSegmentId?: string;
    segmentId: string;
    ready?: Subject<Operation[]>
}

export interface WidgetPropertiesSnapshot {
    time: number;
    widgetType: string;
    properties: PropertyData[];
}
