import { Injectable } from "@angular/core";
import { first } from "rxjs/operators";
import { Subject, ReplaySubject, Observable } from "rxjs";

import { DynamicItemStore } from "../../dynamic-item.store";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ResponseError } from "../../../../../shared/services/errors/response-error";
import { OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { Button, CancelButton, ModalComponentSettings, ModalWindowService, ConfirmButton, ClickResult } from "../../../../../shared/services/modal-window.service";
import { OperationResult, DataItem } from "../../../interfaces";
import { RequiresConfirmationCommand } from "../../../../../shared/commands/requires-confirmation-command";
import { OperationCommand } from "./operation-command";
import { ModalConfirmationComponent } from "../../../../../shared/components/modal-confirmation/modal-confirmation.component";
import { ActionEventsConfirmationDialogButtons, ActionIcon } from "../../entity/action-buttons";
import { ActionButton } from "../../../../../shared/components/action-menu/action-menu-model";
import { OPERATION_VALIDATOR_MAP } from "../../../components/dynamic-item.base";
import { Action } from "../../entity/action";

export const MOVE_ALL_TO_RECYCLE_BIN = "Move all translations to Recycle Bin";
export const MOVE_TO_RECYCLE_BIN = "Move to Recycle Bin";
export const UNDO_DELETE_NOTIFICATION_DURATION = 10000;

@Injectable()
export class ScheduleCommand extends OperationCommand implements RequiresConfirmationCommand {

    constructor(dynamicItemStore: DynamicItemStore, private modalWindowService: ModalWindowService) {
        super(dynamicItemStore);
    }

    confirm(context: ExecutionContext): Observable<ExecutionContext> {
        const handled = new ReplaySubject<ExecutionContext>(1);
        const doneCallback = new Subject<any>();
        const actionButton: ActionButton = context.data.action;
        let dataItem: DataItem = context.data.dataItem;
        if (!dataItem) {
            dataItem = DataItem.fromEntityData({}, context.data.entityData);
        }
        const settings = this.generateConfirmationSettings(actionButton, doneCallback);
        this.modalWindowService.openModalConfirmation(context.currentRoute, settings, dataItem);

        doneCallback.subscribe((fields: any) => {
            context.data.updateFields = fields;
            if (fields === null) {
                context.data.confirmed = false;
            } else {
                context.data.confirmed = true;
            }
            handled.next(context);
        });

        return handled.pipe(first());
    }

    execute(context: ExecutionContext): Observable<OperationResult> {
        const handled = new ReplaySubject<OperationResult>(1);
        const confirmed = context.data.confirmed;
        if (!confirmed) {
            handled.next({
                success: false,
                key: context.data.dataItem.key
            });
        } else {
            const dataItem = context.data.dataItem;
            const updateFields = context.data.updateFields;

            const scheduleAction = new Action(OPERATION_NAMES.schedule, { action: OPERATION_NAMES.schedule, actionParameters: updateFields });
            const sourceDelete$ = this.dynamicItemStore.saveItem(dataItem, null, scheduleAction);

            sourceDelete$.subscribe(() => {
                handled.next({
                    success: true,
                    key: context.data.dataItem.key
                });
            }, (error: ResponseError) => {
                handled.error(error);
            });
        }

        return handled.pipe(first());
    }

    private generateConfirmationSettings(actionButton: ActionButton, done: Subject<any>): ModalComponentSettings {
        const settings: ModalComponentSettings = {
            title: actionButton.title,
            detailedTitle: actionButton.detailedTitle,
            icon: ActionIcon[actionButton.name],
            parameters: actionButton.parameters,
            contextParameters: actionButton.contextParameters,
            description: null,
            formValidators: OPERATION_VALIDATOR_MAP[actionButton.name],
            action: actionButton.name,
            buttons: new Array<Button>(new ConfirmButton(ActionEventsConfirmationDialogButtons[actionButton.name], (data => {
                if (data.component instanceof ModalConfirmationComponent && data.component.parameters) {
                    const component: ModalConfirmationComponent = data.component;
                    return new ClickResult(true, component.editableFields.valid());
                }

                return new ClickResult(true, true);
            })), new CancelButton()),
            doneCallback: (context) => {
                let fields = null;
                if (context.data && context.data.data) {
                    fields = context.component.editableFields.getFields(false);
                }
                done.next(fields);
            }
        };

        return settings;
    }
}
