import { ModalWindowService, DialogData, DEFAULT_URL_KEY, ClosingContext, ClosingContextType, Button, ConfirmButton, CancelButton, ClickResult } from "../../../../shared/services/modal-window.service";
import { Observable, ReplaySubject } from "rxjs";
import { first } from "rxjs/operators";
import { ExecuteOnceInBulkCommand } from "../../../../shared/commands/command";
import { ExecutionContext } from "../../../../shared/commands/execution-context";
import { BulkOperationResult, SUCCESSFUL_NOTIFFICATION_TIME } from "../../../../content/dynamic-modules/services/operations/commands/bulk-command";
import { ChangeOwnerComponent } from "../change-owner/change-owner.component";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { SelectorConstants } from "../../../../html/selector-constants";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../shared/services/notification/notification-data";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../shared/services/notification/notification.service";
import { Inject } from "@angular/core";
import { CommandNotificationArgs, HasNotificationCommand } from "../../../../shared/commands/has-notification-command";
import { BulkOperationsNotificationComponent } from "../../../../content/dynamic-modules/components/bulk-operations/bulk-operations-notification.component";

export class ChangeOwnerCommand implements ExecuteOnceInBulkCommand, HasNotificationCommand {
    public executeOnceInBulk: boolean = true;

    constructor(
        private readonly modalWindowService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        @Inject(NOTIFICATION_SERVICE) private readonly notificationService: NotificationService) {
    }

    execute(context: ExecutionContext): Observable<BulkOperationResult> {
        const handled = new ReplaySubject<BulkOperationResult>(1);

        const changeOwnerComponentData = this.getChangeOwnerComponentData(context, handled);
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED, (data) => this.onDoneClicked(context, data.component, handled)),
            new CancelButton()
        ];
        const dialogData = new DialogData(changeOwnerComponentData, (closingContext: ClosingContext) => {
            if (closingContext.type === ClosingContextType.ButtonClicked && closingContext.data && closingContext.data.data) {
                handled.next(closingContext.data.data);
            } else {
                handled.next({ success: false });
            }
        }, buttons, null, "-bottom");

        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.show(DEFAULT_URL_KEY, context.currentRoute.parent);

        return handled.pipe(first());
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!succeededItems && !failedItems) {
            return null;
        }
        
        const operationFailed: boolean = failedItems && failedItems.length > 0;
        const operationSucceeded: boolean = succeededItems && succeededItems.length > 0;

        const notificationData: NotificationData = {
            type: BulkOperationsNotificationComponent,
            properties: {
                succeededItemsIds: succeededItems,
                failedItemsIds: failedItems,
                entityData: args.entityData,
                operationName: "update"
            },
            id: "bulkOperationsNotification",
            look: NOTIFICATION_LOOKS.SUCCESS
        };

        if (operationSucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            notificationData.duration = SUCCESSFUL_NOTIFFICATION_TIME;
        } else if (operationFailed) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            notificationData.closeButton = true;
        }

        return notificationData;
    }

    private getChangeOwnerComponentData(context: ExecutionContext, handled: ReplaySubject<BulkOperationResult>): ComponentData {
        return {
            type: ChangeOwnerComponent,
            properties: {
                entityData: context.data.entityData,
                selectedItems: context.data.selectedItems
            }
        };
    }

    private onDoneClicked(context: ExecutionContext, component: ChangeOwnerComponent, handled: ReplaySubject<BulkOperationResult>): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (component.selected.length > 0) {
            const itemIds = component.selectedItems.map(x => x.key);
            const userId = component.selected[0].Id;
            const data = {
                itemIds,
                userId
            };

            this.dynamicItemStore.executeEntityOperation(context.data.entityData, "Default.ChangeOwner", data)
                .subscribe(() => {
                    const bulkResult: BulkOperationResult = {
                        success: true,
                        succeededItemsIds: itemIds
                    };

                    if (itemIds.length === 1) {
                        this.notificationService.publishBasicNotification({
                            message: "Owner changed successfully.",
                            look: NOTIFICATION_LOOKS.SUCCESS
                        });
                    }

                    clickResult.next(new ClickResult(bulkResult, true));
                }, () => {
                    const bulkResult: BulkOperationResult = {
                        success: true,
                        failedItemsIds: itemIds
                    };

                    if (itemIds.length === 1) {
                        this.notificationService.publishBasicNotification({
                            message: "Failed to change owner.",
                            look: NOTIFICATION_LOOKS.ERROR
                        });
                    }

                    clickResult.next(new ClickResult(bulkResult, true));
                });
        }

        return clickResult;
    }
}
