import { BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN, DefaultTaskNotificationBuilder } from "./background-task-notification-builder";
import { stringConstants } from "../../../../../common-constants";
import { BackgroundTaskType, ExtendedBackgroundTask, TaskActionButton, TaskStatus } from "../../services/background-task.types";
import { ClassProvider } from "@angular/core";
import { ReindexTaskDataParsed, SearchBackgroundTaskDataParser } from "./search-background-task-data-parser";
import { FILTERCALLBACK_PROPERTY_MAP } from "./long-running-progress.component";

export class SearchTaskNotificationBuilder extends DefaultTaskNotificationBuilder {
    private supportedTaskTypes: string[] = [
        BackgroundTaskType.Reindex
    ];

    get isDefault() {
        return false;
    }

    isTaskSupported(taskName: string): boolean {
        return this.supportedTaskTypes.indexOf(taskName) > -1;
    }

    processTask(task: ExtendedBackgroundTask) {
        if (task.TaskName === BackgroundTaskType.Reindex) {
            if (task.StatusMessage) {
                task.Description = `${task.StatusMessage} for ${task.Title}`;
            } else {
                task.Description = `Indexing ${task.Title}...`;
            }
        }

        super.processTask(task);
    }

    filterTasksCallback(task: ExtendedBackgroundTask, propertyMap: { [key: string]: string }): boolean {
        if (!propertyMap) {
            return false;
        }

        const taskData = this.parseTaskData(task);
        if (propertyMap.hasOwnProperty(FILTERCALLBACK_PROPERTY_MAP.CURRENT_SITE_ID)) {
            const currentSiteId = propertyMap[FILTERCALLBACK_PROPERTY_MAP.CURRENT_SITE_ID];
            if (taskData.siteIds?.length > 0) {
                return taskData.siteIds?.indexOf(currentSiteId) >= 0;
            }
        }

        return true;
    }

    protected parseTaskData(task: ExtendedBackgroundTask): ReindexTaskDataParsed {
        return SearchBackgroundTaskDataParser.parse(task);
    }

    protected buildButtons(task: ExtendedBackgroundTask): TaskActionButton[] {
        return [];
    }

    protected buildNotification(task: ExtendedBackgroundTask) {
        if (!this.isTaskSupported(task.TaskName)) {
            return stringConstants.EMPTY_STRING;
        }

        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (status === TaskStatus.Failed) {
            return task.StatusMessage;
        }

        return null;
    }
}

export const SEARCH_NOTIFICATION_BUILDER: ClassProvider = {
    multi: true,
    provide: BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN,
    useClass: SearchTaskNotificationBuilder
};
