import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "../../content/dynamic-modules/services/operations/operations-filter";
import { OperationsData, OperationsTarget } from "../../content/dynamic-modules/services/operations/interfaces";
import { OPERATION_NAMES, Operation, OPERATION_TITLES } from "../../shared/components/action-menu/operation.model";
import { Injectable, ClassProvider } from "@angular/core";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";

@Injectable()
export class TaxonomyOperationsFilter implements OperationsFilter {
    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (this.isTypeSupported(data.dataItem.metadata.setName)) {
            if (data.target === OperationsTarget.List) {
                const editOperation = operations.find(x => x.Name === OPERATION_NAMES.edit);
                if (editOperation) {
                    editOperation.Title = OPERATION_TITLES.properties;
                }

                if (!data.contextData.isHierarchicalView) {
                    operations = operations.filter(x => x.Name !== OPERATION_NAMES.reorder);
                }
            }
        }

        return operations;
    }

    private isTypeSupported(setName: string): boolean {
        return setName === ENTITY_SET.CLASSIFICATIONS ||
               setName === ENTITY_SET.HIERARCHY_TAXA ||
               setName === ENTITY_SET.FLAT_TAXA;
    }
}

export const TAXONOMY_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: TaxonomyOperationsFilter
};
