import { Component, Input, Output, EventEmitter, AfterViewInit, ViewChildren, QueryList, OnDestroy, OnInit, TemplateRef } from "@angular/core";
import { StickyDirective } from "../../../../../../../fields/common/directives/sticky.directive";
import { Subscription ,  BehaviorSubject, Observable } from "rxjs";
import { ScrollService } from "../../../../../services/scroll.service";
import { ActivatedRoute, Router } from "@angular/router";
import { SiteTitleDynamicResolver } from "../../../services/site-title.dynamic.resolver";
import { SiteDataStore } from "../../../services/metadata/site-data.store";
import { trigger, style, animate, state, transition } from "@angular/animations";
import { ANIMATION_STATES } from "../../../../../constants/animation-constants";
import { ROUTE_PATHS_NO_PREFIX } from "../../../../../constants/route-paths";
import { DataItem } from "../../../../content/dynamic-modules/interfaces";
import { ComponentData } from "@progress/sitefinity-component-framework";

const animationDuration = "500ms ease-out";

@Component({
    selector: "sf-navigation-menu",
    templateUrl: "./navigation-menu.component.html",
    animations: [
        trigger("stickyAnimation", [
            state("active", style({ opacity: "1"})),
            transition(ANIMATION_STATES.ENTER, [
                style({ opacity: "0"}),
                animate(animationDuration)
            ])
        ])
    ]
})
export class NavigationMenuComponent implements AfterViewInit, OnDestroy, OnInit {
    // Bind the NavbarModes enum to property, so it can be used in templates, instead
    // of comparing with 0, 1 etc.
    navbarModes: any;
    navbarCssClassList: string;
    additionalActionsMenuClassList: string;
    @Input() configuration: NavbarConfiguration;
    @Input() operationStatus = new BehaviorSubject<boolean>(false);
    @Input() disableLeftNavbarButton?: boolean = false;
    @Output() leftNavButtonClick: EventEmitter<any>;
    @Output() scroll: EventEmitter<boolean>;
    @ViewChildren(StickyDirective) private stickyDirective: QueryList<StickyDirective>;
    private subscriptions: Subscription[];

    constructor(public scrollService: ScrollService,
                private route: ActivatedRoute,
                private router: Router,
                private siteTitleDynamicResolver: SiteTitleDynamicResolver,
                private siteDataStore: SiteDataStore) {
        this.navbarModes = NavbarModes;
        this.leftNavButtonClick = new EventEmitter<any>(true);
        this.scroll = new EventEmitter<boolean>(true);
        this.subscriptions = [];
    }

    ngOnInit(): void {
        if (this.configuration.isScrollEnabled === undefined) {
            this.configuration.isScrollEnabled = true;
        }

        if (this.configuration.leftNavbarButtonData &&
            this.configuration.leftNavbarButtonData.mode === LeftNavbarButtonMode.Close &&
            this.route.outlet === ROUTE_PATHS_NO_PREFIX.MENU_OUTLET) {
                this.configuration.leftNavbarButtonData.show = true;
        }

        if (this.configuration.look) {
            this.navbarCssClassList = this.generateCssClassList(this.configuration.look);
        }

        this.additionalActionsMenuClassList = this.generateAdditionalActionsMenuClassList();

        const siteDataStoreSubscription: Subscription = this.siteDataStore.getValue().subscribe(siteData => {
            this.siteTitleDynamicResolver.updateBrowserTitle(this.route.snapshot, siteData.Name);
        });

        this.subscriptions.push(siteDataStoreSubscription);
    }

    ngAfterViewInit(): void {
        const stickySubscription: Subscription = this.stickyDirective.changes.subscribe((changes: any) => {
            this.scroll.emit(changes.first.isSticky);
        });

        this.subscriptions.push(stickySubscription);
    }

    ngOnDestroy(): void {
        this.subscriptions.forEach((subscription: Subscription) => subscription.unsubscribe());
    }

    onLeftNavButtonClick(data: any): void {
        switch (this.configuration.leftNavbarButtonData.mode) {
            case LeftNavbarButtonMode.Back:
                this.onBackClick(data);
                break;
            case LeftNavbarButtonMode.Close:
                this.onCloseClick();
                break;
        }
    }

    generateAdditionalActionsMenuClassList(): string {
        const classList: string[] = [
            "-col-2",
            "-align-self-center",
            "-sf-txt-align-center"
        ];

        if (!this.configuration.additionalActionsComponentData) {
            classList.unshift("sf-row__col");
        }

        return classList.join(" ");
    }

    private onBackClick(data: any): void {
        this.scrollService.scrollToTop(false);
        this.leftNavButtonClick.emit(data);
    }

    private async onCloseClick(): Promise<void> {
        this.router.navigate([{outlets: { menu: null }}], { relativeTo: this.route.parent, queryParamsHandling: "merge" });
    }

    private generateCssClassList(look: string) {
        let cls = "";
        if (look) {
            cls += " -" + look.split(" ").join(" -");
        }
        return cls;
    }
}

export interface NavbarConfiguration {
    mode?: NavbarModes;
    hideEmbededMenu?: boolean;
    leftNavbarButtonData?: LeftNavbarButtonData;
    look?: string;
    isScrollEnabled?: boolean;
    templates?: TemplateRef<any>[];
    scrollTemplates?: TemplateRef<any>[];
    title?: Observable<string>;
    hideAdditionalActionsMenu?: boolean;
    stickyScrollOffset?: number;
    additionalActionsComponentData?: ComponentData;
    item$?: Observable<DataItem>;
}

export enum NavbarModes {
    None,
    OneColumn,
    TwoColumns,
    ThreeColumns
}

export enum LeftNavbarButtonMode {
    Back,
    Close
}

interface LeftNavbarButtonData {
    show?: boolean;
    mode?: LeftNavbarButtonMode;
    look?: string;
    icon?: string;
    iconLook?: string;
    title?: string;
    disable?: Observable<boolean>;
    autoNavigateBack?: boolean
}
