import { Injectable, Inject } from "@angular/core";

import { StorageService, LOCAL_STORAGE } from "../services/storage.service";
import { KEYS } from "../services/settings-keys";
import { LOGOUT_URL_NO_STS } from "../../../common-constants";
import { APP_ROUTE_PATHS } from "../../auth/auth.routes";
import { UrlService } from "../../../services/url.service";
import { HttpClient } from "@angular/common/http";
import { catchError, map } from "rxjs/operators";
import { Observable, of, ReplaySubject, Subject } from "rxjs";
import { Settings } from "./settings.service";

const SitefinityOAuthServerRelativePath: string = "Sitefinity/oauth/authorize";

@Injectable()
export class AuthorizationServerSettings {
    constructor(
        @Inject(LOCAL_STORAGE) private storage: StorageService,
        private urlService: UrlService,
        private http: HttpClient,
        private settings: Settings) {
    }

    private isValid$: Subject<boolean> = new ReplaySubject<boolean>(1);

    public authorizationEndpoint: string;
    public clientId: string;
    public responseType: string;
    public redirectUri: string;
    public signOutEndpoint: string;

    public isValid(): Subject<boolean> {
        this.authorizationEndpoint = this.storage.getItem(KEYS.AUTH_SERVER_AUTHORIZATION_ENDPOINT);
        this.clientId = this.storage.getItem(KEYS.AUTH_SERVER_CLIENT_ID);
        this.signOutEndpoint = this.storage.getItem(KEYS.AUTH_SERVER_SIGN_OUT_ENDPOINT);
        this.redirectUri = this.urlService.getAbsoluteUrl(`/auth/oauth/${APP_ROUTE_PATHS.SIGN_IN_REDIRECT}`);
        this.responseType = "token";

        // backwards comaptibility with monolith Sitefinity (.NET Framework based)
        if (!this.authorizationEndpoint && !this.clientId) {
            this.isOauthServerAvailable().subscribe(isAvailable => {
                if (isAvailable) {
                    this.authorizationEndpoint = `${this.settings.url}${SitefinityOAuthServerRelativePath}`;
                    this.clientId = "sitefinity";
                    let returnUrl = this.urlService.getAbsoluteUrl("/");
                    returnUrl = encodeURIComponent(returnUrl);
                    this.signOutEndpoint = `${this.settings.url}Sitefinity${LOGOUT_URL_NO_STS}${returnUrl}`;
                    this.isValid$.next(true);
                } else {
                    this.isValid$.next(false);
                }
            });
        } else {
            this.isValid$.next(true);
        }

        return this.isValid$;
    }

    private isOauthServerAvailable(): Observable<boolean> {
        const url = `${this.settings.url}${SitefinityOAuthServerRelativePath}`;
        return this.http.get(url, { observe: "response", responseType: "text" }).pipe(
            map(x => {
                // we expect invalid request response with status code 400
                return false;
            }),
            catchError(error => {
                if (error.status === 400 && error.error.includes("invalid_request"))
                    return of(true);
                else
                    return of(false);
            })
        );
    }
}
