import { Injectable } from "@angular/core";
import { Media } from "../immutables-facade/media";
import { IFrameMediaParser } from "../immutables-facade/iframe-media.parser";
import { NODE_NAMES, SelectorConstants, TAG_NAMES } from "../selector-constants";
import { CHARACTERS } from "../../content/constants";
import { YouTubePlayerService, PlayerInitData } from "../youtube-player.service";
import { stringConstants } from "../../../common-constants";

export const YOUTUBE_MEDIA_CONSTANTS = {
    REGEX_CONSTANTS: {
        REGULAR_VIDEO_URL_PATTERN: /http(?:s?):\/\/(?:www\.)?youtu(?:be\.com\/watch([\/]|)\?v=|\.be)([\w\-\_]*)(&\S+)/i,
        REGULAR_VIDEO_URL_EXACT_PATTERN: /^(http:\/\/|https:\/\/)(youtu\.be|www\.youtube\.com)\/([\w\/]+)([\?].*)?$/i,
        VIDEO_ID_PATTERN: /v=[a-z0-9-_]{11}/i,
        VIDEO_ATTRIBUTE_VALUE_PATTERN: /sf-youtube-url=".*?"/i,
        EMBED_VIDEO_URL_PATTERN: /http(?:s?):\/\/(?:www\.)?youtu(?:be\.com\/(embed)\/(\S){11})/,
        EMBED_VIDEO_SEGMENT_PATTERN: /embed\/[a-z0-9-_]{11}/i,
        SHORT_URL_PATTERN: /http(?:s?):\/\/(?:www\.)?youtu.be\/[\S]{11}(\S+)?/,
        SHORT_URL_ID_SEGMENT: /.be\/[a-z0-9-_]{11}/i,
        QUERY_PARAMS_PATTERN: /\?(\S+)/,
        PLAY_LIST_PATTERN: /(http:\/\/|https:\/\/)(youtu\.be|www\.youtube\.com)\/embed\?(\S+|listType=playlist|\S)/,
        IFRAME_REGEX: /<iframe[^>]*?(?:\/>|>[^<]*?<\/iframe>)/
    },
    CLASSES: "-sf-hidden",
    PLAYER_ELEMENT_ID: "player",
    VIDEO_URL_ATTRUBUTE_NAME: "sf-youtube-url",
    DUMMY_VIDEO_ID: "XXXXXXXXXXX"
};

const SCRIPT_SRC = "https://www.youtube.com/iframe_api";

/**
 * Parses YouTube URLs and generates iframe with
 * the video.
 *
 * @export
 * @class YoutubeMediaParser
 * @extends {IFrameMediaParser}
 */
@Injectable()
export class YoutubeMediaParser extends IFrameMediaParser {
    constructor(private readonly youtubePlayer: YouTubePlayerService) {
        super();
        this.insertScript(SCRIPT_SRC);
    }

    /**
     * Determines when the parser is able to process the data.
     * The data can be parsed when:
     *  1) it's pure URL: https://www.youtube.com/watch?v=sbuQNTSkYfU
     *  2) it's HTML with "sf-youtube-url" tag: <div sf-youtube-url="https://www.youtube.com/watch?v=sbuQNTSkYfU"></div>
     *  3) it's playlist URL: https://www.youtube.com/embed?listType=playlist&list=PLC77007E23FF423C6
     *  4) it's video with playlist: https://www.youtube.com/watch?v=0JzAgTIzXI4&t=0s&index=1&list=PLZFONtJzdid1RqeMV2t02NrxCA2AgtsBG
     *  5) it's short url: https://youtu.be/VbRdFAFFYMc
     *  6) it's embed url: https://www.youtube.com/embed/IWrK7sXK3Vw
     *
     * @param {string} inputText
     * @returns {boolean}
     * @memberof YoutubeMediaParser
     */
    canProcess(inputText: string): boolean {
        if (!inputText) {
            return false;
        }

        inputText = inputText.trim();

        if (!this.shouldProcessIfIFrame(inputText)) {
            return false;
        }

        if (this.isPlayList(inputText)) {
            return true;
        }

        if (!this.hasId(inputText)) {
            return false;
        }

        if (this.isYoutubeLink(inputText)) {
            return true;
        }

        return false;
    }

    /**
     * Extracts the YouTube URL from given HTML.
     *
     * @param {string} html The HTML from which the URL will be extracted.
     * @returns {string} The extracted URL.
     * @memberof YoutubeMediaParser
     */
    getValue(html: string): string {
        const url = this.getUrlMatches(html);
        return url;
    }

    /**
     * Verifies whether the input is an exact match of an url candidate to be embedded.
     *
     * @param {string} inputText The string that will be examined.
     * @returns {boolean} true or false.
     * @memberof YoutubeMediaParser
     */
    isExactMatch(inputText: string): boolean {
        if (!inputText) {
            return false;
        }

        inputText = inputText.trim();

        let matches = null;

        matches = inputText.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.REGULAR_VIDEO_URL_EXACT_PATTERN);
        if (matches && matches[0] === inputText) {
            return true;
        }
        matches = inputText.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.EMBED_VIDEO_URL_PATTERN);
        if (matches && matches[0] === inputText) {
            return true;
        }
        matches = inputText.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.SHORT_URL_PATTERN);
        if (matches && matches[0] === inputText) {
            return true;
        }
        matches = inputText.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.PLAY_LIST_PATTERN);
        if (matches && matches[0] === inputText) {
            return true;
        }

        return false;
    }

    /**
     * Parses the given link and initializes the video.
     *
     * @param {string} inputText The URL of the YouTube video.
     * @returns {Promise<Media>} Promise with the initialized video.
     * @memberof YoutubeMediaParser
     */
    parse(inputText: string): Promise<Media> {
        return new Promise(resolve => {
            if (this.isPlayList(inputText)) {
                this.parsePlaylist(inputText, resolve);
            } else {
                this.parseVideo(inputText, resolve);
            }
        });
    }

    /**
     * Extracts the media element from the given one.
     * For this parser, the passed element is always
     * iframe wrapped in immutable div with sf-youtube-url
     * attribute.
     *
     * @param {HTMLElement} element The wrapped iframe.
     * @returns {HTMLElement} The wrapped iframe.
     * @memberof YoutubeMediaParser
     */
    getMediaFromElement(element: HTMLElement): HTMLElement {
        return element;
    }

    /**
     * Update given property of the passed iframe.
     * If the element doesn't contain iframe, no update
     * will be performed.
     *
     * @param {HTMLElement} element Element that contains iframe.
     * @param {string} propName The property to update.
     * @param {*} value The updated value.
     * @memberof YoutubeMediaParser
     */
    updateMediaElement(element: HTMLElement, propName: string, value: any) {
        const iframe = element.querySelector(TAG_NAMES.IFRAME);

        if (iframe) {
            iframe.setAttribute(propName, value);
        }
    }

    private getVideoId(videoUrl: string): string {
        const isRegularUrl = !!YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ID_PATTERN.exec(videoUrl);

        if (isRegularUrl) {
            return this.extractUrlIDFromReguralYouTubeURL(videoUrl, YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ID_PATTERN, CHARACTERS.EQUALS_SIGN);
        }

        const isShortUrl = !!YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.SHORT_URL_PATTERN.exec(videoUrl);

        if (isShortUrl) {
            return this.extractUrlIDFromReguralYouTubeURL(videoUrl, YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.SHORT_URL_ID_SEGMENT, stringConstants.FORWARD_SLASH);
        }

        return this.extractUrlIDFromReguralYouTubeURL(videoUrl, YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.EMBED_VIDEO_SEGMENT_PATTERN, stringConstants.FORWARD_SLASH);
    }

    private createHiddenVideoWrapper(elementId: string): HTMLElement {
        const existingIFrame = document.getElementById(YOUTUBE_MEDIA_CONSTANTS.PLAYER_ELEMENT_ID);
        if (existingIFrame) {
            const parent = existingIFrame.parentElement;
            parent.parentElement.removeChild(parent);
        }

        const wrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
        const player = document.createElement(NODE_NAMES.DIV_ELEMENT);

        wrapper.appendChild(player);
        wrapper.classList.add(YOUTUBE_MEDIA_CONSTANTS.CLASSES);
        player.id = elementId;

        const main = document.querySelector(".sf-app") || document.querySelector(".sf-main");
        main.appendChild(wrapper);

        return wrapper;
    }

    private getUrlFromTag(html: string): string {
        const hasUrlAttribute = html.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ATTRIBUTE_VALUE_PATTERN);

        if (!hasUrlAttribute) {
            return null;
        }

        const url = this.getUrlMatches(html);
        return url;
    }

    private extractUrlIDFromReguralYouTubeURL(videoUrl: string, regex: RegExp, splitChar: string): string {
        const match = videoUrl.match(regex);
        const tokens = match[0].split(splitChar);
        const videoId = tokens[1].trim();

        return videoId;
    }

    private parsePlaylist(inputText: string, onVideoReady: (value?: Media) => void) {
        const videoUrl = this.getUrlFromTag(inputText) || inputText;
        const initData: PlayerInitData = {
            domElementId: YOUTUBE_MEDIA_CONSTANTS.PLAYER_ELEMENT_ID,
            videoUrl,
            playerVars: this.getQueryParams(inputText)
        };

        this.setInitDataWidthAndHeight(initData, inputText);
        this.createHiddenVideoWrapper(YOUTUBE_MEDIA_CONSTANTS.PLAYER_ELEMENT_ID);
        this.youtubePlayer
            .init(initData)
            .then(event => {
                const iframe: HTMLElement = event.target.getIframe();

                super.parse(iframe.outerHTML).then((media: Media) => {
                    media = this.handleIFrame(initData, media);
                    onVideoReady(media);
                });
            });
    }

    private parseVideo(inputText: string, onVideoReady: (value?: Media) => void) {
        let videoUrl = inputText;
        const attributeVideoUrl = this.getUrlFromTag(videoUrl);

        if (attributeVideoUrl) {
            videoUrl = attributeVideoUrl;
        }

        this.createHiddenVideoWrapper(YOUTUBE_MEDIA_CONSTANTS.PLAYER_ELEMENT_ID);

        const initData: PlayerInitData = {
            domElementId: YOUTUBE_MEDIA_CONSTANTS.PLAYER_ELEMENT_ID,
            videoId: this.getVideoId(videoUrl),
            videoUrl,
            playerVars: this.getQueryParams(videoUrl)
        };

        this.setInitDataWidthAndHeight(initData, inputText);
        this.initVideoPlayer(initData, onVideoReady, YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.IFRAME_REGEX.test(inputText));
    }

    private initVideoPlayer(initData: PlayerInitData, onVideoReady: (value?: Media) => void, isDataComingFromIFrame: boolean): any {
        this.youtubePlayer
            .init(initData)
            .then(event => {
                const iframe: HTMLElement = event.target.getIframe();

                iframe.title = isDataComingFromIFrame ? initData.title : event.target.getVideoData().title;

                super.parse(iframe.outerHTML).then((media: Media) => {
                    media = this.handleIFrame(initData, media);
                    onVideoReady(media);
                });
            });
    }

    private handleIFrame(initData: PlayerInitData, media: Media): Media {
        // The wrapper is needed, because custom attributes cannot be added to iframes.
        const iframeWrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
        iframeWrapper.innerHTML = media.html;
        iframeWrapper.setAttribute(YOUTUBE_MEDIA_CONSTANTS.VIDEO_URL_ATTRUBUTE_NAME, initData.videoUrl);
        media.html = iframeWrapper.outerHTML;

        return media;
    }

    private getUrlMatches(html: string) {
        const element = document.createElement(NODE_NAMES.DIV_ELEMENT);
        element.innerHTML = html;

        const srcElement = element.querySelector(`${NODE_NAMES.DIV_ELEMENT}[${YOUTUBE_MEDIA_CONSTANTS.VIDEO_URL_ATTRUBUTE_NAME}]`);

        if (srcElement) {
            return srcElement.getAttribute(YOUTUBE_MEDIA_CONSTANTS.VIDEO_URL_ATTRUBUTE_NAME);
        }

        return element.getAttribute("src");
    }

    private getQueryParams(url: string): object {
        const match = url.match(YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.QUERY_PARAMS_PATTERN);
        if (!match || !match.length) {
            return {};
        }

        const urlQueryParams = match[1];
        const queryParams = {};

        urlQueryParams
            .split(CHARACTERS.AMPERSAND)
            .forEach(segment => {
                const pair = segment.split(CHARACTERS.EQUALS_SIGN);
                const key = pair[0];
                const value = pair[1];
                const numericValue = +value;

                queryParams[key] = !isNaN(numericValue) ? numericValue : value;
            });

        // Autoplay is disabled, because once played in the editor,
        // the video cannot be stopped.
        delete queryParams["autoplay"];

        return queryParams;
    }

    private isPlayList(input: string) {
        const isPlayList = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.PLAY_LIST_PATTERN.test(input);
        return isPlayList;
    }

    private shouldProcessIfIFrame(inputText: string): boolean {
        const containsIFrame = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.IFRAME_REGEX.test(inputText);

        if (!containsIFrame) {
            return true;
        }

        const hasUrlAttribute = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ATTRIBUTE_VALUE_PATTERN.test(inputText);

        if (hasUrlAttribute) {
            return true;
        }

        const isWrappedByImmutable = inputText.includes(SelectorConstants.SF_IMMUTABLE_SELECTED);

        if (isWrappedByImmutable && hasUrlAttribute) {
            return true;
        }

        return false;
    }

    private hasId(inputText: string): boolean {
        if (!this.isYoutubeLink(inputText)) {
            return false;
        }

        const hasId = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ID_PATTERN.test(inputText) ||
                      YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.EMBED_VIDEO_SEGMENT_PATTERN.test(inputText) ||
                      YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.SHORT_URL_ID_SEGMENT.test(inputText);

        return hasId;
    }

    private isYoutubeLink(inputText: string): boolean {
        const hasUrlAttribute = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.VIDEO_ATTRIBUTE_VALUE_PATTERN.test(inputText);
        const isRegularYouTubeUrl = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.REGULAR_VIDEO_URL_EXACT_PATTERN.test(inputText);
        const isEmbedYouTubeUrl = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.EMBED_VIDEO_URL_PATTERN.test(inputText);
        const isShortUrl = YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.SHORT_URL_PATTERN.test(inputText);
        const canProcess = hasUrlAttribute || isRegularYouTubeUrl || isEmbedYouTubeUrl || isShortUrl;

        return canProcess;
    }

    private setInitDataWidthAndHeight(initData: PlayerInitData, inputText: string): void {
        if (YOUTUBE_MEDIA_CONSTANTS.REGEX_CONSTANTS.IFRAME_REGEX.test(inputText)) {
            const wrapper = document.createElement(NODE_NAMES.DIV_ELEMENT);
            wrapper.innerHTML = inputText;

            const iframe = wrapper.querySelector(TAG_NAMES.IFRAME) as HTMLIFrameElement;
            const { width, height, title } = iframe;

            initData.width = width;
            initData.height = height;
            initData.title = title;
        }
    }
}
