@keyframes floatingText {
  0% {
    transform: translate(0);
  }
  50% {
    transform: translate(calc(-100% + 26px/2));
  }
  100% {
    transform: translate(0);
  }
}
@keyframes loader {
  40% {
    opacity: 1;
  }
}
@keyframes loadingProgressbar {
  0% {
    transform: scaleX(0);
  }
  50% {
    transform: scaleX(1);
  }
  100% {
    transform: translateX(100%);
  }
}
@keyframes loadingSkeleton {
  0% {
    opacity: 0.7;
  }
  50% {
    opacity: 0.8;
  }
  100% {
    opacity: 0.9;
  }
}
