export const RegexHelper = Object.freeze({
    buildRegex: (value: string, flag?: string) => { return XRegExp(value, flag); },
    replace: (str: string, search: any, replacement: string) => { return XRegExp.replace(str, search, replacement); },
    test: (str: string, regex: any) => { return regex.test(str); }
});

export function runInNgZone(next: Function, callback?: Function): void {
    const ngZone = new NgZone({ enableLongStackTrace: isDevMode() });
    ngZone.onMicrotaskEmpty.subscribe(() => {
        if (!ngZone.hasPendingMacrotasks && !ngZone.hasPendingMicrotasks && callback) {
            callback();
        }
    });
    ngZone.run(() => next());
}

export function getFormattedTypeName(names: TypeNames, allowMultiple: boolean, withIndefiniteArticle: boolean): string {
    let formattedName: string = stringConstants.EMPTY_STRING;

    if (names) {
        if (allowMultiple) {
            formattedName = names.plural;
        } else {
            if (withIndefiniteArticle && names.singular) {
                formattedName = `${indefiniteArticle(names.singular)} ${names.singular}`;
            } else {
                formattedName = names.singular;
            }
        }
    }

    return formattedName;
}

// source: http://stackoverflow.com/questions/4558437/programmatically-determine-whether-to-describe-an-object-with-a-or-an
export function indefiniteArticle(phrase) {
    // checking the input phrase
    if (!phrase || typeof phrase !== "string" || phrase.length < 1)
        return stringConstants.EMPTY_STRING;

    // Getting the first word
    const match = /\w+/.exec(phrase);
    let word = stringConstants.EMPTY_STRING;
    if (match) {
        word = match[0];
    } else {
        return stringConstants.EMPTY_STRING;
    }

    const lowercaseWord = word.toLowerCase();
    // Specific start of words that should be preceded by 'an'
    const altCases = ["honest", "hour", "hono"];
    for (let i = 0; i < altCases.length; i += 1) {
        if (lowercaseWord.indexOf(altCases[i]) === 0) {
            return "an";
        }
    }

    // Single letter word which should be preceded by 'an'
    if (lowercaseWord.length === 1) {
        if ("aedhilmnorsx".indexOf(lowercaseWord) >= 0) {
            return "an";
        } else {
            return "a";
        }
    }

    // Capital words which should likely be preceded by 'an'
    if (word.match(/(?!FJO|[HLMNS]Y.|RY[EO]|SQU|(F[LR]?|[HL]|MN?|N|RH?|S[CHKLMNPTVW]?|X(YL)?)[AEIOU])[FHLMNRSX][A-Z]/)) {
        return "an";
    }

    // Special cases where a word that begins with a vowel should be preceded by 'a'
    const regexes = [/^e[uw]/, /^onc?e\b/, /^uni([^nmd]|mo)/, /^u[bcfhjkqrst][aeiou]/];
    for (let i = 0; i < regexes.length; i += 1) {
        if (lowercaseWord.match(regexes[i])) {
            return "a";
        }
    }

    // Special capital words (UK, UN)
    if (word.match(/^U[NK][AIEO]/)) {
        return "a";
    } else if (word === word.toUpperCase()) {
        if ("aedhilmnorsx".indexOf(lowercaseWord[0]) >= 0) {
            return "an";
        } else {
            return "a";
        }
    }

    // Basic method of words that begin with a vowel being preceded by 'an'
    if ("aeiou".indexOf(lowercaseWord[0]) >= 0) {
        return "an";
    }

    // Instances where y followed by specific letters is preceded by 'an'
    if (lowercaseWord.match(/^y(b[lor]|cl[ea]|fere|gg|p[ios]|rou|tt)/)) {
        return "an";
    }

    return "a";
}

function isObject(val: any) {
    return typeof val === "object";
}

export function assignMatchingProperties(target: any, source: any) {
    if (!isObject(target)) {
        Object.assign(target, source);
        return;
    }

    Object.keys(target).forEach(key => {
        if (key in source) {
            if (isObject(source[key])) {
                Object.assign(target[key], source[key]);
            } else {
                target[key] = source[key];
            }
        }
    });
}

const PAST_TENSE_EXCEPTIONS = {
    "are": "were",
    "eat": "ate",
    "go": "went",
    "have": "had",
    "inherit": "inherited",
    "is": "was",
    "run": "ran",
    "sit": "sat",
    "visit": "visited",
    "reorder": "reordered"
};

// source: https://gist.github.com/letsgetrandy/1e05a68ea74ba6736eb5
export const getPastTense = (verb: string) => {
    if (PAST_TENSE_EXCEPTIONS[verb.toLowerCase()]) {
        return PAST_TENSE_EXCEPTIONS[verb.toLowerCase()];
    }

    if ((/e$/i).test(verb)) {
        return verb + "d";
    }

    if ((/[aeiou]c/i).test(verb)) {
        return verb + "ked";
    }

    // for american english only
    if ((/el$/i).test(verb)) {
        return verb + "ed";
    }

    if ((/[aeio][aeiou][dlmnprst]$/).test(verb)) {
        return verb + "ed";
    }

    if ((/[aeiou][bdglmnprst]$/i).test(verb)) {
        return verb.replace(/(.+[aeiou])([bdglmnprst])/, "$1$2$2ed");
    }

    return verb + "ed";
};

export const pluralize = (str: string) => {
    let typeName;

    if (str.endsWith("x")) {
        typeName = str + "es";
    } else if (str.endsWith("s")) {
        typeName = str;
    } else {
        typeName = str + "s";
    }

    return typeName;
};

export const capitalizeFirstLetter = (stringToCapitalize: string) => {
    if (stringToCapitalize && stringToCapitalize.length > 0) {
        return stringToCapitalize.charAt(0).toUpperCase() + stringToCapitalize.slice(1);
    }

    return stringToCapitalize;
};

const IRIS_PREFIX = "__sf__";

export function addPrefix(value: string): string {
    return IRIS_PREFIX + value;
}

export function isFileTypeAllowed(fileType: any, acceptableMediaTypes: Array<string>): boolean {
    if (!acceptableMediaTypes || !acceptableMediaTypes.length) {
        return false;
    }

    const fileTypes = acceptableMediaTypes.filter(item => fileType.toUpperCase() === item.toUpperCase());
    return fileTypes.length > 0;
}

export function filename(name: string): string {
    const nameArray = name.split(stringConstants.DOT);
    if (nameArray.length > 1) {
        nameArray.pop();
    }
    const filename = nameArray.join(stringConstants.DOT);

    return filename;
}

export function isNullOrEmpty(str: string) {
    return str === null || str === stringConstants.EMPTY_STRING;
}

export function trimStart(target: string, valToTrim: string) {
    if (valToTrim.length > target.length) {
        return target;
    }

    const replacePattern = new RegExp(`^[${valToTrim}]+`);
    return target.replace(replacePattern, stringConstants.EMPTY_STRING);
}

export function cloneObject(obj: Object) {
    const clonedObject = JSON.parse(JSON.stringify(obj));
    return clonedObject;
}

export function cloneInstance<T>(instance: T): T {
    return cloneObject(instance) as T;
}

export function addDaysToDate(days: number): Date {
    const date = new Date();
    date.setDate(date.getDate() + days);
    return date;
}

export function convertDateToIsoDateTime(value: Date, timeZoneOffset: number = null): string {
    const date = new Date(value);

    const offset: number = timeZoneOffset === null ? 0 : timeZoneOffset;
    date.setMinutes(date.getMinutes() - date.getTimezoneOffset() + offset);

    return date.toISOString();
}

export function extractSafeUrl(value: SafeUrl): string {
    return value ? value["changingThisBreaksApplicationSecurity"] : value;
}

export function validateExtensionsVersusSitefinityVersions(sitefinityVersion: string, extensionsCompatibleSitefinityVersions: { [Key: string]: string[]; }): void {
    if (extensionsCompatibleSitefinityVersions) {
        for (const extensionsName in extensionsCompatibleSitefinityVersions) {
            if (extensionsCompatibleSitefinityVersions.hasOwnProperty(extensionsName)) {
                const sortedVersions = extensionsCompatibleSitefinityVersions[extensionsName].filter(t => t.match(/^\d+\.\d+\.\d+\.\d+$/)).sort(compareVersions);
                if (sortedVersions.length !== 0) {
                    const earliestValidVersion = sortedVersions[0];
                    if (compareVersions(earliestValidVersion, sitefinityVersion) > 0) {
                        const latestValidVersion = sortedVersions[sortedVersions.length - 1];
                        window.console.warn(`The extension ${extensionsName} is based on Extensions Repo Version ${latestValidVersion} which is greater than the running Sitefinity version ${sitefinityVersion}. Some of the extensions might not work properly. For more information, see https://github.com/Sitefinity/sitefinity-admin-app-extensions#backward-compatibility`);
                    }
                }
            }
        }
    }
}

export function getExtensionFromFileName(fileName: string): string {
    const nameArray = fileName.split(stringConstants.DOT);
    if (nameArray.length > 1) {
        return nameArray.pop();
    }

    return stringConstants.EMPTY_STRING;
}

export function getFileNameWithoutExtension(fileName: string): string {
    const nameArray = fileName.split(stringConstants.DOT);
    if (nameArray && nameArray.length) {
        return nameArray[0];
    }

    return fileName;
}

export function getValidateExtensionsErrorMessage(acceptableFileTypes: string[]) {
    return "Invalid file format. Allowed formats: " + acceptableFileTypes.map(type => type.toUpperCase()).join(", ");
}

class DeepCloneProcessor {
    processObject(obj: any): any {
        if (typeof obj !== "object") {
            return obj;
        }
        if (!obj) {
            return obj;
        }

        const target = Object.create(Object.getPrototypeOf(obj));
        const props = Object.keys(obj);

        for (const prop of props) {
            const sourceProp = obj[prop];

            if (sourceProp instanceof Map) {
                target[prop] = this.processMap(sourceProp);
                continue;
            }

            if (sourceProp instanceof Set) {
                target[prop] = this.processSet(sourceProp);
                continue;
            }

            if (Array.isArray(sourceProp)) {
                target[prop] = this.processArray(sourceProp);
                continue;
            }

            const isObject = typeof sourceProp === "object";
            const hasValue = sourceProp !== null && sourceProp !== undefined;

            if (hasValue && isObject) {
                target[prop] = this.processObject(sourceProp);
            } else {
                target[prop] = sourceProp;
            }
        }

        return target;
    }

    processArray(obj: any[]) {
        const newArr = [];

        for (const el of obj) {
            newArr.push(this.processObject(el));
        }

        return newArr;
    }

    processSet(sourceSet: Set<any>) {
        const newSet = new Set();

        sourceSet.forEach(item => {
            newSet.add(this.processObject(item));
        });

        return newSet;
    }

    processMap(sourceMap: Map<any, any>) {
        const newMap = new Map<any, any>();

        sourceMap.forEach(key => {
            newMap.set(this.processObject(key), this.processObject(sourceMap.get(key)));
        });

        return newMap;
    }
}

export function deepClone(source: any) {
    if (!source) {
        return source;
    }

    const processor = new DeepCloneProcessor();

    if (Array.isArray(source)) {
        return processor.processArray(source);
    }

    if (source instanceof Map) {
        return processor.processMap(source);
    }

    if (source instanceof Set) {
        return processor.processSet(source);
    }

    return processor.processObject(source);
}

export function deepFreeze(object: Object): any {
    // Retrieve the property names defined on object
    const propNames = Object.getOwnPropertyNames(object);

    // Freeze properties before freezing self
    for (const name of propNames) {
        const value = object[name];

        object[name] = value && typeof value === "object" ?
            deepFreeze(value) : value;
    }

    return Object.freeze(object);
}

function compareVersions(v1: string, v2: string): number {
    const segmentsV1 = v1.split(".");
    const segmentsV2 = v2.split(".");

    for (let i = 0; i < segmentsV1.length; i++) {
        const diff = parseInt(segmentsV1[i], 10) - parseInt(segmentsV2[i], 10);
        if (diff) {
            return diff;
        }
    }

    return 0;
}

export function toKebabCase(str: string): string {
    return str.toLocaleLowerCase().split(" ").join("-");
}

export function convertHourMinuteSecStringToSeconds(value: string) {
    const parts = value.split(":");
    return 60 * 60 * parseInt(parts[0] || "0") + 60 * parseInt(parts[1] || "0") + parseInt(parts[2] || "0");
}

export function convertSecondsToHourMinuteSecString(value: number) {
    const parts = new Array(3);

    let left = value;

    for (let index = 0; index < parts.length; index++) {
        const power = parts.length - 1 - index;
        const divisor = Math.pow(60, power);
        const result = Math.floor(left / divisor);

        parts[index] = result.toString();
        if (parts[index].length < 2) {
            parts[index] = "0" + parts[index];
        }

        const valueToSubtract = result * divisor;
        left -= valueToSubtract;
    }

    return parts.join(":");
}

export function getCssVariableValue(variable: string, scope?: string): string {
    const scopeElement = document.querySelector(scope) || document.querySelector("body");

    return getComputedStyle(scopeElement).getPropertyValue(variable);
}

export function getCssVariableValueAsNumber(variable: string, scope?: string): number {
    return Number(getCssVariableValue(variable, scope).replace("px", stringConstants.EMPTY_STRING));
}

export function copyTextToClipboard(text) {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();

    document.execCommand("copy");

    document.body.removeChild(textArea);
}

export const INTEGRATED_IRIS_CLASS: string = "-sf-integrated-app";

export function toggleIrisIntegratedStyles(activate: any) {
    const htmlElement = document.documentElement;
    if (activate) {
        htmlElement.classList.add(INTEGRATED_IRIS_CLASS);
    } else {
        htmlElement.classList.remove(INTEGRATED_IRIS_CLASS);
    }
}

export function hideSitefinityContent(doc: Document) {
    const wrapper = doc.getElementById("adminAppWrapper");
    const footer = doc.getElementsByClassName("sfFooter")[0];
    const header = doc.getElementsByClassName("sfHeader")[0];
    const bodySitefinityCssClasses = doc.body.getAttribute("data-sf-body-className");

    if (wrapper) {
        let elementToHide: any = wrapper.parentElement.nextElementSibling;
        while (elementToHide !== null) {
            elementToHide.style.display = "none";
            elementToHide = elementToHide.nextElementSibling;
        }
        const irisClassNames = [];
        doc.body.classList.forEach(cls => {
            if (cls.startsWith(IRIS_CLASS_PREFIX)) {
                irisClassNames.push(cls);
            }
        });

        if (!bodySitefinityCssClasses) {
            doc.body.setAttribute("data-sf-body-className", doc.body.className);
        }
        doc.body.className = stringConstants.EMPTY_STRING;
        doc.body.classList.add(...irisClassNames);
        toggleIrisIntegratedStyles(true);
    }

    if (footer) {
        const footerElementsToHide: any = footer.children;
        for (const el of footerElementsToHide) {
            if (!el.classList.contains(ALWAYS_VISIBLE_CLASS)) {
                el.style.display = "none";
            }
        }
    }

    if (header) {
        const headerElementsToHide: any = header.children;
        for (const el of headerElementsToHide) {
            if (!el.classList.contains(ALWAYS_VISIBLE_CLASS)) {
                el.style.display = "none";
            }
        }
    }
}

export function showSitefinityContent(doc: Document) {
    const wrapper = doc.getElementById("adminAppWrapper");
    const header = doc.getElementsByClassName("sfHeader")[0];
    const bodySitefinityCssClasses = doc.body.getAttribute("data-sf-body-className");

    if (header) {
        const headerElements: any = header.children;
        for (const el of headerElements) {
            if (!el.classList.contains(ALWAYS_VISIBLE_CLASS)) {
                el.style.display = stringConstants.EMPTY_STRING;
            }
        }
    }

    if (wrapper) {
        let elementToShow: any = wrapper.parentElement.nextElementSibling;
        while (elementToShow !== null) {
            elementToShow.style.display = stringConstants.EMPTY_STRING;
            elementToShow = elementToShow.nextElementSibling;
        }

        toggleIrisIntegratedStyles(false);
    }

    if (bodySitefinityCssClasses) {
        doc.body.className = bodySitefinityCssClasses;
    }
}

export function compareOperationArrays(op1: Operation[], op2: Operation[]): boolean {
    if (op1.length !== op2.length) {
        return false;
    }

    op1.forEach(x => {
        if (!op2.find(y => y.Name === x.Name)) {
            return false;
        }
    });

    return true;
}

export function getGridViewMode(gridViewRecord: string, userId: string): GridViewModes {
    if (gridViewRecord && userId) {
        const gridMode = gridViewRecord.split(",");
        const storedUser = gridMode[0];
        const mode = gridMode[1];
        if (storedUser === userId) {
            return <GridViewModes>mode;
        }
    }

    return GridViewModes.Thumbs;
}

export enum GridViewModes {
    Thumbs = "Thumbs",
    List = "List",
    Timeline = "Timeline"
}

/**
 * Create an image item with base 64. Return the file
 *
 * @param {string} base64Content
 * @param {string} filename
 * @returns {File}
 */
export function createFileWithBase64(base64Content: string, filename: string): File {
    const chunks = base64Content.split(",");
    const mimeType = chunks[0].match(/:(.*?);/)[1];
    const blob = atob(chunks[1]);
    let blobLenght = blob.length;
    const u8arr = new Uint8Array(blobLenght);

    while (blobLenght--) {
        u8arr[blobLenght] = blob.charCodeAt(blobLenght);
    }

    return new File([u8arr], filename, { type: mimeType });
}

export function hasValue(val: any) {
    return val !== undefined && val !== null;
}

export function flatDeep<T>(array: any[], depth: number = 1): Array<T> {
    return depth > 0 ? array.reduce((acc, val) => acc.concat(Array.isArray(val) ? flatDeep(val, depth - 1) : val), [])
        : array.slice();
}

export function filterDuplicates(arrayToBeFiltered: any[]) {
    return arrayToBeFiltered.filter((value, index, array) => array.indexOf(value) === index);
}

export function isElementVisible(windowProvider: Window, element: HTMLElement): boolean {
    const isElementWithDimensions = !!(element.offsetWidth || element.offsetHeight || element.getClientRects().length);
    const isElementVisible = windowProvider.getComputedStyle(element).visibility !== "hidden";
    return isElementWithDimensions && isElementVisible;
}

export function dispatchKeydownEvent(currentWindow: Window, code: string, ctrlKey?: boolean, altKey?: boolean, shiftKey?: boolean) {
    jasmine.Ajax.requests.reset();
    const event = new KeyboardEvent("keydown", {
        bubbles: true,
        cancelable: true,
        code: code,
        ctrlKey: ctrlKey,
        altKey: altKey,
        shiftKey: shiftKey,
        // Need to set metaKey to be same as ctrlKey because it is used on macOS
        metaKey: ctrlKey
    });
    currentWindow.dispatchEvent(event);
}

export function unifyMocksDomain(mockData: string) {
    let value = JSON.stringify(mockData);
    value = value.replace(/(http|https):\/\/[\w:-]+(.azurewebsites.net)?(\/)/g, `${window.origin}/`);
    return JSON.parse(value);
}

// @progress\kendo-angular-common\dist\es2015\utils\guid.js
export const guid = () => {
    let id = "";
    for (let i = 0; i < 32; i++) {
        const random = Math.random() * 16 | 0;
        if (i === 8 || i === 12 || i === 16 || i === 20) {
            id += "-";
        }
        id += (i === 12 ? 4 : (i === 16 ? (random & 3 | 8) : random)).toString(16);
    }
    return id;
};

export const groupBy = <T, K extends keyof any>(arr: T[], key: (i: T) => K) =>
    arr.reduce((groups, item) => {
        (groups[key(item)] ||= []).push(item);
        return groups;
    }, {} as Record<K, T[]>);

export const unique = <T>(array: T[], propertyName: string): T[] => array.filter((e, i) => array.findIndex(a => a[propertyName] === e[propertyName]) === i);

export function getTooltip(fieldModel: FieldModel, value: any): MarkupSection[] {
    const tooltips = fieldModel.settings.tooltipModels;
    const key = tooltips.has(DEFAULT_MARKUP_KEY) ? DEFAULT_MARKUP_KEY : value;

    return tooltips.get(key);
}

export function getMatchingLinkStyle(styles: StyleData[], currentClasses: string[]): StyleData {
    let match = styles[0];
    let maximumMatchedClasses = 0;

    // start from index 1 because we do not need to check for the first style in the allStyles array
    // because it will be selected by default if no other is found
    styles.slice(1).forEach(style => {
        let numberOfMatchingClasses = 0;
        style.Value.every(cssClass => {
            if (currentClasses.indexOf(cssClass) === -1) {
                numberOfMatchingClasses = 0;
                return false;
            } else {
                numberOfMatchingClasses++;
                return true;
            }
        }, this);

        if (numberOfMatchingClasses > maximumMatchedClasses) {
            maximumMatchedClasses = numberOfMatchingClasses;
            match = style;
        }
    });

    return match;
}
