import { first } from "rxjs/operators";
import { DynamicItemStore } from "../../dynamic-item.store";
import { HasNotificationCommand, CommandNotificationArgs } from "../../../../../shared/commands/has-notification-command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject, Subject } from "rxjs";
import { DeleteItem } from "../../dynamic-item.service";
import { ResponseError } from "../../../../../shared/services/errors/response-error";
import { OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { DeleteButton, Button, CancelButton, ModalComponentSettings, ModalWindowService } from "../../../../../shared/services/modal-window.service";
import { DataItem, OperationResult } from "../../../interfaces";
import { Injectable } from "@angular/core";
import { ActionButton } from "../../../../../shared/components/action-menu/action-menu-model";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { UndoDeleteComponent } from "../../../components/undo-delete.component";
import { Properties } from "../../../../../shared/fields.constants";
import { RequiresConfirmationCommand } from "../../../../../shared/commands/requires-confirmation-command";
import { ContentCultureData } from "../../../../../shared/services/metadata/site-data.store";
import { OperationCommand } from "./operation-command";
import { getPastTense } from "../../../../../../utils";
import { CompositeDeleteCommandExtender } from "./composite-delete-command-extender";

const DELETE_ALL_TRANSLATIONS_KEY = "deleteAllTranslations";
export const MOVE_ALL_TO_RECYCLE_BIN = "Move all translations to Recycle Bin";
export const MOVE_TO_RECYCLE_BIN = "Move to Recycle Bin";
export const PERMANENT_DELETE_PARAM_NAME = "PermanentDelete";
export const DELETE_ALLOWED_PARAM_NAME = "DeleteAllowed";
export const UNDO_DELETE_NOTIFICATION_DURATION = 5000;

// TODO: delete command is not used in the ActionExecutorService, we should revise the implementation to provide a single way of deleting items
@Injectable()
export class DeleteCommand extends OperationCommand implements HasNotificationCommand, RequiresConfirmationCommand {
    private sentToRecycleBin: boolean;

    constructor(dynamicItemStore: DynamicItemStore, private modalWindowService: ModalWindowService, private deleteCommandExtender: CompositeDeleteCommandExtender) {
        super(dynamicItemStore);

        this.sentToRecycleBin = false;
    }

    confirm(context: ExecutionContext): Observable<ExecutionContext> {
        const handled = new ReplaySubject<ExecutionContext>(1);

        const doneCallback = new Subject<DeleteItem>();

        let dataItem: DataItem = context.data.dataItem;
        if (!dataItem) {
            dataItem = DataItem.fromEntityData({}, context.data.entityData);
        }

        const settings = this.generateConfirmationSettings(dataItem, context.data, doneCallback);
        this.modalWindowService.openModalConfirmation(context.currentRoute, settings, dataItem);

        doneCallback.subscribe((deleteArgs: DeleteItem) => {
            if (deleteArgs === null) {
                context.data.confirmed = false;
                handled.next(context);
            } else {
                context.data.confirmed = true;
                context.data.deleteAllTranslations = deleteArgs.deleteAllTranslations;
                handled.next(context);
            }
        });

        return handled.pipe(first());
    }

    execute(context: ExecutionContext): Observable<OperationResult> {
        const handled = new ReplaySubject<OperationResult>(1);
        const confirmed = context.data.confirmed;
        if (!confirmed) {
            handled.next({
                success: false,
                key: context.data.dataItem.key
            });
        } else {
            const cultures = this.getSiteCultures(context.data);
            const dataItem = context.data.dataItem;
            const deleteAllTranslations = context.data.deleteAllTranslations;
            this.sentToRecycleBin = deleteAllTranslations || cultures.length <= 1 ||
                (dataItem.data[Properties.AvailableLanguages] && dataItem.data[Properties.AvailableLanguages].length <= 1);

            const sourceDelete$ = this.deleteCommandExtender.executeDelete(dataItem, deleteAllTranslations, context.data.bulk);
            sourceDelete$.subscribe(() => {
                handled.next({
                    success: true,
                    key: context.data.dataItem.key
                });
            }, (error: ResponseError) => {
                handled.error(error);
            });
        }

        return handled.pipe(first());
    }

    getNotification(succeededItems: string[], failedItems: string[], args: CommandNotificationArgs): NotificationData {
        if (!failedItems || failedItems.length === 0) {
            if (this.sentToRecycleBin && args.action.contextParameters) {
                const permanentDeleteParam = args.action.contextParameters.find(p => p.Name === PERMANENT_DELETE_PARAM_NAME);
                if (permanentDeleteParam && permanentDeleteParam.Value.toLowerCase() === "false") {
                    const notificationData: NotificationData = {
                        type: UndoDeleteComponent,
                        properties: {
                            restorableItemIds: succeededItems,
                            entityData: args.entityData
                        },
                        id: "undoDeleteNotification",
                        look: NOTIFICATION_LOOKS.WARNING,
                        duration: UNDO_DELETE_NOTIFICATION_DURATION,
                        closeButton: false
                    };

                    return notificationData;
                }
            }
        }

        return null;
    }

    static getItemCannotBeDeletedModalSettings(dataItems: DataItem[], data: any, done: Subject<DeleteItem>): ModalComponentSettings {
        const action: ActionButton = data.action;
        const operationNamePastTense = getPastTense(OPERATION_NAMES.delete.toLowerCase());
        const isMultiple = dataItems.length > 1;
        const dataItemTitltes = dataItems.map(d => `"${d.data.Title}"`);
        const lastItem = dataItemTitltes.pop();
        const aggredatedTitles = dataItemTitltes.length ? `${dataItemTitltes.join(", ")} and ${lastItem}` : lastItem;
        const dataItemMeta = dataItems[0].metadata;
        const setName = dataItemMeta.singularName;
        const title = `${setName + (isMultiple ? "s" : "")} cannot be ${operationNamePastTense}`;
        const childTypeName = dataItemMeta.children[0]?.toLocaleLowerCase();

        let description;
        if (childTypeName) {
            description = `${aggredatedTitles} contain${isMultiple ? "" : "s"} ${childTypeName}. You should remove all ${childTypeName} before attempting to delete a ${setName.toLowerCase()}.`;
        } else {
            description = `${aggredatedTitles} are using or used by other items. You should remove them before attempting to delete a ${setName.toLocaleLowerCase()}.`;
        }

        const settings: ModalComponentSettings = {
            title,
            icon: "trash",
            parameters: [],
            hideItemTitle: true,
            description,
            contextParameters: action.contextParameters,
            action: OPERATION_NAMES.delete,
            buttons: [new CancelButton("Close")],
            doneCallback: (context) => {
                done.next(null);
            }
        };

        return settings;
    }

    private generateConfirmationSettings(dataItem: DataItem, data: any, done: Subject<DeleteItem>): ModalComponentSettings {
        const action: ActionButton = data.action;
        const settings: ModalComponentSettings = {
            title: this.deleteCommandExtender.getTitle(data),
            icon: "trash",
            parameters: [],
            description: action.description,
            contextParameters: action.contextParameters,
            action: OPERATION_NAMES.delete,
            buttons: [],
            doneCallback: (context) => {
                if (context.data && context.data.data) {
                    const deleteAllTranslations = context.data.data === DELETE_ALL_TRANSLATIONS_KEY;
                    const deleteItemArgs: DeleteItem = {
                        dataItem: dataItem,
                        deleteAllTranslations: deleteAllTranslations
                    };

                    done.next(deleteItemArgs);
                } else {
                    done.next(null);
                }
            }
        };

        this.updateDeleteSettings(dataItem, data, settings);

        return settings;
    }

    private updateDeleteSettings(dataItem: DataItem, data: any, settings: ModalComponentSettings) {
        settings.buttons = this.getDeleteConfiramtionDialogButtons(dataItem, data, settings);
        settings.hideItemTitle = true;
    }

    private getDeleteConfiramtionDialogButtons(dataItem: DataItem, data: any, settings: ModalComponentSettings): Array<Button> {
        let result: Array<Button> = [];

        if (this.isDeleteForbidden(settings)) {
            result.push(new CancelButton("Close"));
            return result;
        }

        const itemCulture: string = dataItem.culture;
        const displayName = this.deleteCommandExtender.getDisplayName(data);

        let deleteAllTranslationsButtonText: string = `${OPERATION_NAMES.delete} all translations`;
        let deleteThisTranslationButtonText: string = `${OPERATION_NAMES.delete} ${itemCulture.toUpperCase()} translation only`;
        let deleteButtonText: string = `${OPERATION_NAMES.delete} ${displayName.toLowerCase()}`;

        if (!this.deleteCommandExtender.permanentDelete(data)) {
            deleteAllTranslationsButtonText = MOVE_ALL_TO_RECYCLE_BIN;
            deleteThisTranslationButtonText = `${OPERATION_NAMES.delete} ${itemCulture.toUpperCase()} translation permanently`;
            deleteButtonText = MOVE_TO_RECYCLE_BIN;
        }

        if (this.deleteCommandExtender.showMultilingualButtons(data)) {
            const deleteAllButton = new DeleteButton(deleteAllTranslationsButtonText, DELETE_ALL_TRANSLATIONS_KEY);
            const deleteButton = new DeleteButton(deleteThisTranslationButtonText, true, "large");
            result = new Array<Button>(deleteAllButton, deleteButton);
        } else {
            const deleteButton = new DeleteButton(deleteButtonText);
            result = new Array<Button>(deleteButton);
        }

        result.push(new CancelButton());

        return result;
    }

    private isDeleteForbidden(settings: ModalComponentSettings): boolean {
        if (settings.contextParameters) {
            const deleteAllowed = settings.contextParameters.find(p => p.Name === DELETE_ALLOWED_PARAM_NAME);
            if (deleteAllowed) {
                return deleteAllowed.Value.toLowerCase() === "false";
            }
        }

        return false;
    }

    private getSiteCultures(data: any): ContentCultureData[] {
        const sitedataStore = data.siteData;
        const cultures: ContentCultureData[] = sitedataStore.ContentCultures;
        return cultures;
    }
}
