import { map } from "rxjs/operators";
import { ActivatedRouteSnapshot, Router, Resolve, RouterStateSnapshot, CanActivate } from "@angular/router";
import { DynamicItemStrategyBase } from "./strategies/dynamic-item.strategy";
import { QUERY_PARAMS, RESOLVE_NAMES, FILTER_PARAMS } from "../../constants";
import { ROUTE_PATHS } from "../../../../constants/route-paths";
import { SiteData } from "../../../shared/services/metadata/site-data.store";
import { ProviderStore } from "../services/provider-store";
import { Settings } from "../../../shared/services/settings.service";
import { Observable } from "rxjs";
import { stringConstants } from "../../../../common-constants";
import { CompositeEntityDataResolver } from "../services/backend-tweaks/entity-data.resolver";
import { getRouteDataRecursively } from "./helpers";

export abstract class BaseResolver implements Resolve<any>, CanActivate {
    protected persistCulture: boolean = false;
    protected skipProviderValidation: boolean = false;

    constructor(protected store: ProviderStore, protected router: Router, private settings: Settings, private entityDataResolver: CompositeEntityDataResolver) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> | Promise<any> | any {
        const siteData = getRouteDataRecursively(route, RESOLVE_NAMES.siteDataStore);
        const metadata = getRouteDataRecursively(route, RESOLVE_NAMES.metadata);

        let cultureName = siteData.DefaultContentCulture;
        let entityData = this.entityDataResolver.resolveEntityData(route, metadata, cultureName, this.store.currentProvider);
        if (!entityData) {
            this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
            return null;
        }

        if (entityData.metadata.isMultilingual) {
            cultureName = this.getCultureFromRoute(route);
            if (cultureName) {
                const cultureExists = siteData.ContentCultures.find(x => x.Name === cultureName);
                if (!cultureExists) {
                    this.navigateAndRemoveParam(route, state, QUERY_PARAMS.CULTURE);
                    return null;
                }
            } else {
                cultureName = this.getCulture(siteData);
            }

            if (this.persistCulture) {
                this.settings.setSiteCulture(siteData.Id, cultureName);
            }
        }

        entityData = {
            metadata: entityData.metadata,
            provider: entityData.provider,
            culture: cultureName
        };

        return entityData;
    }

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean> {
        let currentProviderName: string = route.parent.queryParams[QUERY_PARAMS.PROVIDER];
        const currentEntitySet: string = this.getEntitySet(route);
        const canActivate = this.store.getProviders(currentEntitySet).pipe(map(providers => {
            const defaultProvider = providers.find(p => p.isDefault);

            if (!currentProviderName && !defaultProvider) {
                // naivgate to not found as we have not found a provider and chosing first would mean random for each user
                this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
                return false;
            }

            // empty means default
            if (!currentProviderName && defaultProvider) {
                currentProviderName = defaultProvider.name;
            }

            if (this.skipProviderValidation || providers.findIndex(p => p.name === currentProviderName) >= 0) {
                this.store.currentProvider = currentProviderName;
                return true;
            } else {
                if (currentProviderName) {
                    // Remove the provider parameter and redirect, so we can use the default provider

                    this.navigateAndRemoveParam(route, state, QUERY_PARAMS.PROVIDER);
                } else {
                    this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
                }

                return false;
            }
        }));

        return canActivate;
    }

    protected clearFilter(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
        this.navigateAndRemoveParam(route, state, FILTER_PARAMS.FILTER);
    }

    protected getEntitySet(route: ActivatedRouteSnapshot) {
        return DynamicItemStrategyBase.getSet(route.parent);
    }

    protected getCultureFromRoute(route: ActivatedRouteSnapshot): string {
        return route.parent.queryParams[QUERY_PARAMS.CULTURE];
    }

    private navigateAndRemoveParam(route: ActivatedRouteSnapshot, state: RouterStateSnapshot, paramName: string) {
        const currentQueryParams = Object.assign({}, route.parent.queryParams);
        const paramKeys = Object.keys(currentQueryParams);

        if (currentQueryParams.hasOwnProperty(paramName)) {
            delete currentQueryParams[paramName];
        }

        let url = state.url;
        if (paramKeys.length > 0) {
            url = state.url.substring(0, state.url.indexOf("?"));
        }

        const urlParts = url.split(stringConstants.FORWARD_SLASH).filter(p => p).map(p => p.trim());
        this.router.navigate(urlParts, { queryParams: currentQueryParams });
    }

    private getCulture(siteData: SiteData): string {
        const cachedCulture = this.settings.getSiteCulture(siteData.Id);
        const isAvailableLanguage = siteData.ContentCultures.some(x => x.Name === cachedCulture);
        if (isAvailableLanguage) {
            return cachedCulture;
        }

        return siteData.DefaultContentCulture;
    }
}
