import { CommandEmitter, COMMAND_NAMES } from "../../../../content/dynamic-modules/components/commands";
import { Component, OnInit, Output, EventEmitter, Input, OnChanges, SimpleChanges, OnDestroy, Inject } from "@angular/core";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../services/notification/notification.service";
import { NotificationData } from "../../../services/notification/notification-data";
import { stringConstants } from "../../../../../common-constants";
import { BehaviorSubject } from "rxjs";
import { SfRxBase } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-notification-loader",
    templateUrl: "./notification-loader.component.html"
})
export class NotificationLoaderComponent extends SfRxBase implements OnInit, OnChanges, OnDestroy, CommandEmitter {
    @Output() onCommand = new EventEmitter<string>();
    @Input() isInHeader: boolean;
    @Input() hide: boolean = false;
    @Input() filter: string;
    @Input() look: string;

    notification$: BehaviorSubject<NotificationData> = new BehaviorSubject(null);

    constructor(
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService ) {
        super();
    }

    ngOnInit(): void {
        const notificationSubscription = this.notificationService.getNotification().subscribe(notification => {
            if (notification) {
                if (!this.filter && notification.filterParam) {
                    return;
                }

                if (this.filter && notification.filterParam !== this.filter) {
                    return;
                }
            }

            this.notification$.next(notification);
            this.enhanceNotification(notification);
        });

        const notificationCloseSubscription = this.notificationService.getCloseNotification().subscribe(notification => {
            if (this.notification$.getValue() === notification) {
                this.notification$.next(null);
            }
        });

        this.registerSubscription(notificationCloseSubscription);
        this.registerSubscription(notificationSubscription);
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.hide && !changes.hide.firstChange && changes.hide.currentValue) {
            this.notificationService.close(null);
        }
    }

    onClose(notification: NotificationData): void {
        if (notification.closeButton) {
            this.notificationService.close(notification.filterParam);
        }
    }

    getLook(notification: NotificationData): string {
        let look = notification.look + stringConstants.INTERVAL;
        if (this.isInHeader) {
            look += stringConstants.INTERVAL + "small";
        }

        return look;
    }

    private enhanceNotification(notification: NotificationData) {
        if (!notification)
            return;

        if (!notification.afterComponentInit) {
            notification.afterComponentInit = (notificationComponent: CommandEmitter) => {
                if (notificationComponent.onCommand) {
                    this.registerSubscription(notificationComponent.onCommand.subscribe(key => {
                        if (key === COMMAND_NAMES.close) {
                            this.notificationService.close(notification.filterParam);
                        } else {
                            this.onCommand.emit(key);
                        }
                    }));
                }
            };
        }

        notification.look = notification.look || "";
        if (this.look)
            notification.look += ` ${this.look}`;
    }
}
