import { Inject, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { Command, ExecutionContext } from "../../../../api";
import { NOTIFICATIONS_PREFERENCES_EVENT } from "../../../../constants/integrated-mode-constants";
import { WINDOW_TOKEN } from "../../../../window.provider";

@Injectable()
export class OpenNotificationsPreferencesCommand implements Command {
    constructor(@Inject(WINDOW_TOKEN) private window: Window) {}

    execute(context: ExecutionContext): Observable<any> {
        const event = new CustomEvent(NOTIFICATIONS_PREFERENCES_EVENT);
        this.window.dispatchEvent(event);
        return of(true);
    }
}
