import { Component, OnInit, Input } from "@angular/core";
import { FieldModel } from "../../../../services/field.model";
import { FormGroup, FormControl } from "@angular/forms";
import { EntityData } from "../../../content/dynamic-modules/interfaces";

@Component({
    templateUrl: "./edit-image.component.html"
})
export class EditImageComponent implements OnInit {
    @Input() image: Image;
    @Input() fields: FieldModel[];
    @Input() form: FormGroup;
    @Input() mediaEntityData: EntityData;

    ngOnInit(): void {
        this.form = new FormGroup({});
        this.fields.forEach(field => {
            // using undefined for optional parameter as specified in typescript docs
            // https://www.typescriptlang.org/docs/handbook/functions.html#optional-and-default-parameters
            this.form.controls[field.key] = new FormControl(undefined, field.settings.validators);
            this.form.controls[field.key].setValue(field.value);
        });
    }
}

export interface Image {
    src: string;
    width: number;
    height: number;
    alt: string;
    extension: string;
    size: string;

    contentType?: string;
}
