import { Component, OnInit, ViewChild, Input, Inject, TemplateRef, Output, EventEmitter, OnDestroy } from "@angular/core";

import { DataItem } from "../../../content/dynamic-modules/interfaces";
import { BehaviorSubject, Observable, ReplaySubject } from "../../../../../../node_modules/rxjs";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";

import { MetadataStore, Entity } from "../../services/metadata/meta-data.store";
import { OPERATION_NAMES } from "../action-menu/operation.model";
import { stringConstants } from "../../../../common-constants";
import { Settings } from "../../services/settings.service";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ItemsState, StateWrapper } from "../../../content/dynamic-modules/services/dynamic-item-store-state";
import { ColumnModel } from "../../models/column-model";
import { COMMAND_NAMES, ItemCommand } from "../../../content/dynamic-modules/components/commands";
import { switchMap } from "rxjs/operators";
import { MediaHelpers } from "../../../libraries/services/media.helpers";
import { EditNavigationService } from "../../services/edit-navigation.service";
import { ActivatedRoute } from "@angular/router";
import { MediaRecognizerService } from "../../../libraries/media/media-recognizer.service";
import { TreeWrapperComponent, TreeConfig } from "../../../../../../fields";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ResultMapperBase } from "./mappers/modal-list-mapper-base";
import { NotificationService, NOTIFICATION_SERVICE } from "../../services/notification/notification.service";

const DEFAULT_TAKE = 50;
@Component({
    selector: "sf-modal-list",
    templateUrl: "./modal-list.component.html"
})
export class ModalListComponent extends SfRxBase implements OnInit, OnDestroy {
    @ViewChild("itemTemplate", { static: true }) template: any;
    @ViewChild("tree", { static: false }) tree: TreeWrapperComponent;

    @Input() action: string;
    @Input() actionTitle: string;
    @Input() count: BehaviorSubject<number>;
    @Input() dataItem: DataItem;
    @Input() openItemEdit: boolean = true;
    @Input() showDataItemTitle: boolean = true;
    @Input() columns: ColumnModel[];
    @Input() metadata: Entity;
    @Input() contentLook: string;
    @Input() isLoading: boolean = true;
    @Input() ignoreDelay: boolean = false;
    @Input() showCounter: boolean = true;
    @Input() items: any[] = [];
    @Input() listLook: string;
    @Input() onViewNodeFunc: Function;
    @Input() tabsConfig: TabConfig[];
    @Input() sourceSelector: SourceSelectorConfig;
    @Input() isSearchVisible: boolean = false;
    @Input() searchValue: string;
    @Input() itemTemplate: TemplateRef<any> = null;
    @Input() customNoItemsTemplate: TemplateRef<any> = null;
    @Input() treeNodeClickedEvent = this.onItemClicked;
    @Input() treeConfig: TreeConfig = { noSelection: true };
    @Input() counterLook: string = "positive";
    @Input() modalListMapper: ResultMapperBase;

    @Output() itemsLoaded = new EventEmitter<any>();

    public description: string;
    public notificationFilter = "modal-list";

    title: string;
    noItemsLabel: string;
    itemsState: StateWrapper = StateWrapper.empty(true);
    isLoadingMore: boolean = false;
    itemsModified: boolean = false;
    totalCount: number;
    showMedia: boolean = true;
    previewUrl: any;
    private loadItems$ = new ReplaySubject<Observable<any>>(1);

    constructor(
        @Inject(WINDOW_TOKEN) private window: Window,
        private itemService: DynamicItemService,
        private settings: Settings,
        private editNavigationService: EditNavigationService,
        private route: ActivatedRoute,
        private metaDataStore: MetadataStore,
        private mediaRecognizerService: MediaRecognizerService,
        @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService) {
        super();
    }

    ngOnInit(): void {
        if (this.dataItem) {
            this.title = this.actionTitle.replace("this item", this.dataItem.metadata.singularName.toLowerCase());
            this.title = this.title.replace("this ", stringConstants.EMPTY_STRING);
            this.noItemsLabel = `${this.actionTitle.replace("item", this.dataItem.metadata.singularName.toLowerCase())} will appear here`;
            this.previewUrl = this.mediaRecognizerService.getPreviewUrlProperty(this.dataItem.metadata.setName);
        } else {
            this.title = this.actionTitle;
            this.noItemsLabel = `${this.actionTitle} will appear here`;
        }

        if (this.action === OPERATION_NAMES.linkItems) {
            this.treeConfig = {
                status: true,
                description: true,
                showBreadcrumb: true,
                noSelection: true,
                clickable: true
            };

            this.template = null;
        }

        if (this.itemTemplate) {
            this.template = this.itemTemplate;
        }

        // switchMap is used to allow single load at a time
        const loadItemsSubscription = this.loadItems$.pipe(switchMap(o => o)).subscribe((result) => {
            const modifiedItems = [];
            this.itemsLoaded.emit(result);
            let items = result.value;
            if (this.modalListMapper) {
                const mappedResult = this.modalListMapper.map(result);
                this.description = mappedResult.additionalTitle;
                this.counterLook = mappedResult.counterLook;
                items = mappedResult.items;
                const notificationData = mappedResult.notificationData;
                if (notificationData) {
                    notificationData.filterParam = this.notificationFilter;
                    this.notificationService.publishNotification(notificationData);
                }
            }

            items.forEach(item => {
                if (item) {
                    item.description = item.FriendlyContentType;
                    item.data = {};
                    item.data.Status = item.Status;
                    item.data.Result = item.ErrorMessage;
                    modifiedItems.push(item);
                }
            });

            if (this.tabsConfig) {
                this.tabsConfig.forEach(tabConfig => {
                    if (!tabConfig.items) {
                        tabConfig.items = [];
                    }

                    tabConfig.items = tabConfig.items.concat(modifiedItems.filter(tabConfig.itemsFilter));

                    if (tabConfig.itemsModifier) {
                        tabConfig.items.forEach(tabConfig.itemsModifier);
                    }

                    if (tabConfig.selectedFilter) {
                        const selectedItems = tabConfig.items.filter(tabConfig.selectedFilter).map(x => x.Id);
                        tabConfig.treeConfig.selectedNodeIds = selectedItems;
                    }
                });

                this.treeConfig = this.tabsConfig[0].treeConfig;
                this.items = this.tabsConfig[0].items;
            } else {
                this.items = this.items.concat(modifiedItems);
            }

            this.isLoading = false;
            this.isLoadingMore = false;

            if (this.columns) {
                this.itemsState = this.getItemsState();
                this.isLoadingMore = this.itemsState.isLoadingItems;
            }
        });

        this.registerSubscription(loadItemsSubscription);

        // Show loader modal open, until the items are loaded
        if (this.columns) {
            this.itemsState = this.getItemsState(DEFAULT_TAKE);
        }

        this.loadItems(this.items.length);
        this.contentLook = this.generateContentLook();

        const totalItemsCountSubscription = this.count.subscribe(count => {
            this.totalCount = count;
            this.toggleShowDataItemTitle(count);
            if (count === 0) {
                this.showMedia = false;
            }
        });

        this.registerSubscription(totalItemsCountSubscription);
    }

    reloadItems() {
        this.isLoading = true;
        const currentLoadedItemsCount = this.items.length;
        this.items = [];
        this.loadItems(0, currentLoadedItemsCount);
    }

    onItemClicked(clickedItem: any) {
        const itemData = clickedItem.data ? clickedItem.data.dataItem || clickedItem.data : clickedItem;

        if (itemData.Url) {
            const redirect = this.window.open(stringConstants.EMPTY_STRING, itemData.Url);
            if (this.isFullUrl(itemData.Url)) {
                redirect.location.href = itemData.Url;
            } else {
                // itemData.Url comes with a forward slash when it is not a full url
                redirect.location.href = `${this.settings.url.substring(0, this.settings.url.length - 1)}${itemData.Url}`;
            }
        } else {
            const entity = this.metaDataStore.getEntity(itemData.ContentType);

            if (entity && entity.enabled) {
                const item = DataItem.from(itemData, entity, itemData.Provider, this.dataItem.culture);
                this.editNavigationService.navigateToEditOfRelatedData(item, this.route, itemData.SiteId);
            }
        }
    }

    onTreeInitialized() {
        if (this.treeConfig.multiSelection) {
            this.items.forEach(item => {
                if (item.isSelected) {
                    this.tree.selectAndActivateNodeById(item.Name);
                }
            });
        }
    }

    viewNodeClicked(clickedItem: any) {
        if (this.onViewNodeFunc) {
            this.onViewNodeFunc(clickedItem);
        }
    }

    onTabChange(tabConfig: TabConfig) {
        this.items = tabConfig.items;
        this.treeConfig = tabConfig.treeConfig;
        this.noItemsLabel = tabConfig.noItemsLabel;
    }

    onSourceChange(source: string) {
        const newIndex = this.sourceSelector.settings.choices.findIndex(x => x.Value === source);
        const selected = this.tabsConfig[newIndex];
        this.items = selected.items;
    }

    requestMoreItems() {
        if (this.items.length > 0 && this.totalCount > this.items.length) {
            this.isLoadingMore = true;

            if (this.dataItem) {
                this.itemsState = this.getItemsState(this.totalCount - this.items.length);
            }

            this.loadItems(this.items.length);
        }
    }

    onCommand(command: ItemCommand): void {
        if (!command) {
            return;
        }

        switch (command.name) {
            case COMMAND_NAMES.removeItem: {
                const deletedItem = command.data as DataItem;
                const index = this.itemsState.dataItems.findIndex(x => x.key === deletedItem.key);
                if (index >= 0) {
                    const newState: ItemsState = {
                        dataItems: this.itemsState.dataItems.filter(i => i.key !== deletedItem.key),
                        totalCount: this.itemsState.totalCount - 1
                    };

                    this.itemsState = StateWrapper.wrap(newState);
                    this.count.next(this.count.getValue() - 1);
                    this.itemsModified = true;
                }

                break;
            }
        }
    }

    onSearch(searchKey: string) {
        if (searchKey) {
            const idField = this.treeConfig.treeProperties?.idField || "Id";
            const titleField = this.treeConfig.treeProperties?.displayField || "Title";

            this.items.forEach(x => {
                const title = x[titleField.toString()].trim().toLowerCase();
                const hasMatch = title.startsWith(searchKey.toLowerCase()) || title.indexOf(` ${searchKey}`) > -1;
                this.tree.setHiddenNodeById(x[idField.toString()], !hasMatch);
            });
            this.tree.updateTreeModel();
        } else {
            this.tree.showHiddenNodes();
        }
    }

    ngOnDestroy(): void {
        this.notificationService.closeMultiple([this.notificationFilter]);
    }

    private loadItems(skip: number = 0, take: number = DEFAULT_TAKE) {
        if (this.action) {
            let loadItemsFunction: Observable<any>;
            const action = `${this.action}?$skip=${skip}&$top=${take}`;

            if (this.dataItem) {
                loadItemsFunction = this.itemService.executeBoundFunction<any>(this.dataItem, action);
            } else {
                loadItemsFunction = this.itemService.executeUnboundFunction<any>(action);
            }

            this.loadItems$.next(loadItemsFunction);
        }
    }

    private generateContentLook() {
        let contentLook = "sf-form -sf-centered-box -sf-pt-zero";

        if (this.contentLook) {
            contentLook += " -" + this.contentLook.split(" ").join(" -");
        }
        return contentLook;
    }

    private getItemsState(loadingItemsCount: number = 0): StateWrapper {
        const itemsState: ItemsState = {
            dataItems: [],
            totalCount: 0,
            loadingItemsCount: loadingItemsCount
        };

        this.items.forEach(i => {
            const dataItem = DataItem.from(i, this.metadata, i.Provider, this.dataItem.culture);
            itemsState.dataItems.push(dataItem);
        });

        itemsState.totalCount = this.items.length;

        return StateWrapper.wrap(itemsState);
    }

    private isFullUrl(url: string) {
        const isUrlRegex = new RegExp("^https?:\\/\\/");
        return isUrlRegex.test(url);
    }

    private toggleShowDataItemTitle(count: number) {
        if (this.dataItem == null) {
            return;
        }

        // DataItemTitle is hidden for Images in all cases and is hidden for Documents and Videos when the selector is empty
        if (MediaHelpers.isMediaEntity(this.dataItem)) {
            if (count === 0 || MediaHelpers.isImageEntity(this.dataItem) || MediaHelpers.isVideoEntity(this.dataItem)) {
                this.showDataItemTitle = false;
            }
        }
    }
}

interface TabConfig {
    title: string;
    treeConfig: TreeConfig;
    items: any[];
    itemsFilter: any;
    itemsModifier: any;
    noItemsLabel: string;
    selectedFilter?: any;
}

interface SourceSelectorConfig {
    label: string;
    settings: { choices: { Name: string, Value: string }[] }
}
