import { Injectable, InjectionToken } from "@angular/core";

export const LOCAL_STORAGE = new InjectionToken("LocalStorage");

export const SITEFINITY_PREFIX = "sf";
export const LIBRARIES_GRID_VIEW_KEY = "sf.lib.grid.view.mode";

@Injectable()
export class StorageService {
    private storageRef: any;

    constructor() {
        this.storageRef = localStorage;
    }

    getItem(key: string) {
        let item;

        key = this.prefixKey(key, SITEFINITY_PREFIX);

        if (this.storageRef) {
            item = this.storageRef.getItem(key);
        }

        // will return null in case the key is not in the storage
        return item;
    }

    setItem(key: string, data: string) {
        key = this.prefixKey(key, SITEFINITY_PREFIX);

        if (this.storageRef) {
            this.storageRef.setItem(key, data);
        }
    }

    removeItem(key: string) {
        key = this.prefixKey(key, SITEFINITY_PREFIX);

        if (this.storageRef) {
            this.storageRef.removeItem(key);
        }
    }

    prefixKey(key: string, prefix: string = SITEFINITY_PREFIX): string {
        if (key.indexOf(`${prefix}.`) < 0) {
            key = `${prefix}.${key}`;
        }

        return key;
    }
}

export const SF_LOGIN_ATTEMPTS = "sf-login-attempts";
