import { Inject, Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from "@angular/router";
import { Observable } from "rxjs";
import { map } from "rxjs/operators";
import { EntityData } from "../../api";
import { DynamicItemStrategyBase } from "../content/dynamic-modules/components/strategies/dynamic-item.strategy";
import { CompositeEntityDataResolver, EntityDataResolver } from "../content/dynamic-modules/services/backend-tweaks/entity-data.resolver";
import { MetadataContainer, MetadataStore } from "../shared/services/metadata/meta-data.store";

@Injectable()
export class IntegrationsResolver extends CompositeEntityDataResolver implements Resolve<any> {
    constructor(private metadataStore: MetadataStore, @Inject(EntityDataResolver) resolvers: EntityDataResolver[]) {
        super(resolvers);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<EntityData> {
        return this.getEntityData(route);
    }

    protected getEntitySet(route: ActivatedRouteSnapshot) {
        return DynamicItemStrategyBase.getSet(route);
    }

    private getEntityData(route: ActivatedRouteSnapshot): Observable<EntityData> {
        return this.metadataStore.initialize().pipe(map((metadataContainer: MetadataContainer) => {
            return this.resolveEntityData(route, metadataContainer, null, null);
        }));
    }
}
