import { BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN, DefaultTaskNotificationBuilder } from "./background-task-notification-builder";
import { ClassProvider } from "@angular/core";
import { BackgroundTaskDataParser, TaskDataParsedBase, ChangeProviderTaskDataParsed, MoveToLibraryTaskDataParsed } from "./background-task-data-parser";
import { stringConstants } from "../../../../../common-constants";
import { BackgroundTaskType, ExtendedBackgroundTask, TaskActionButton, TaskStatus, TaskAction } from "../../services/background-task.types";
import { FILTERCALLBACK_PROPERTY_MAP } from "./long-running-progress.component";

export class ImagesTaskNotificationBuilder extends DefaultTaskNotificationBuilder {
    private supportedTaskTypes: string[] = [
        BackgroundTaskType.RegenerateThumbnails,
        BackgroundTaskType.MoveLibrary,
        BackgroundTaskType.MoveLibraryAlternative,
        BackgroundTaskType.StorageRelocation,
        BackgroundTaskType.StorageRelocationAlternative,
        BackgroundTaskType.DamMigrationTask
    ];

    private skippedFilterProperties = ["ConcurrentTaskKey", FILTERCALLBACK_PROPERTY_MAP.CURRENT_SITE_ID];

    get isDefault() {
        return false;
    }

    isTaskSupported(taskName: string): boolean {
        return this.supportedTaskTypes.indexOf(taskName) > -1;
    }

    processTask(task: ExtendedBackgroundTask) {
        if (task.TaskName === BackgroundTaskType.RegenerateThumbnails) {
            const processedTitle = task.Title ? task.Title.replace("Regenerate thumbnails for library :", "Regenerating thumbnails for") : task.Description;
            task.Description = processedTitle;
        } else if (task.TaskName === BackgroundTaskType.MoveLibraryAlternative) {
            const taskData = BackgroundTaskDataParser.parse(task) as MoveToLibraryTaskDataParsed;
            if (taskData.itemIds && taskData.itemIds.length > 1) {
                task.Description = task.Description.replace(/Moving library <em>.*?<\/em> to/, `Moving ${taskData.itemIds.length} libraries to`);
            }

            if (taskData.libraryTitle) {
                task.Description = task.Description.replace("<em></em>", taskData.libraryTitle);
            }

            task.Description = task.Description.replace("Moving library", "Moving").replace(/(<em>)|(<\/em>)/gi, "");

            if (taskData.libraryId === stringConstants.DEFAULT_GUID) {
                task.Description = task.Description.replace(/to Root$/, "on top level");
            }
        } else if (task.TaskName === BackgroundTaskType.StorageRelocationAlternative) {
            const parsedTaskData = BackgroundTaskDataParser.parse(task) as ChangeProviderTaskDataParsed;
            if (task.Title === "RelocateLibrary") {
                task.Description = `Generating new URLs for ${parsedTaskData.libraryTitle}`;
            } else {
                task.Description = `Moving ${parsedTaskData.libraryTitle} to another storage`;
            }
        }

        super.processTask(task);
    }

    filterTasksCallback(task: ExtendedBackgroundTask, propertyMap: {[key: string]: string}): boolean {
        if (!propertyMap) {
            return true;
        }

        const taskData = this.parseTaskData(task);

        if (typeof(taskData) === "string") {
            return true;
        } else {
            let shouldShow = true;
            for (const key in propertyMap) {
                if (propertyMap.hasOwnProperty(key)) {
                    const value = propertyMap[key];
                    if (value !== undefined && !this.skippedFilterProperties.includes(key) && taskData[key] !== value) {
                        shouldShow = false;
                        break;
                    }
                }
            }

            return shouldShow;
        }
    }

    protected parseTaskData(task: ExtendedBackgroundTask): TaskDataParsedBase | string {
        return BackgroundTaskDataParser.parse(task);
    }

    protected buildButtons(task: ExtendedBackgroundTask): TaskActionButton[] {
        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (task.TaskName === BackgroundTaskType.RegenerateThumbnails && !task.IsManageable) {
            return [];
        } else if (task.TaskData === BackgroundTaskType.MoveLibraryAlternative) {
            if (parseInt(task.ProgressStatus) < 100 && status === TaskStatus.Started) {
                return [{
                        action: TaskAction.Stop,
                        title: "Stop"
                    }];
            }
            if (status === TaskStatus.Failed) {
                return [{
                    action: TaskAction.Delete,
                    title: "Cancel"
                }];
            }
        } else if (task.TaskName === BackgroundTaskType.StorageRelocationAlternative && status !== TaskStatus.Failed) {
            if (task.Title === "RelocateLibrary") {
                //task.TaskName === BackgroundTaskType.ChangeLibraryUrl
                return [];
            }
        } else if (task.TaskName === BackgroundTaskType.DamMigrationTask && status === TaskStatus.Failed) {
            return [{
                action: TaskAction.Restart,
                title: "Retry"
            }];
        }

        return super.buildButtons(task);
    }

    protected buildNotification(task: ExtendedBackgroundTask) {
        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (status === TaskStatus.Failed) {
            return task.StatusMessage;
        }

        return null;
    }
}

export const IMAGES_NOTIFICATION_BUILDER: ClassProvider = {
    multi: true,
    provide: BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN,
    useClass: ImagesTaskNotificationBuilder
};
