import { Injectable } from "@angular/core";

export const DIMENSION_PROPERTIES = {
    WIDTH: "width",
    HEIGHT: "height"
};

@Injectable()
export class ResizeService {
    resize(sizeChangeData: SizeChangeData, img: HTMLImageElement, canvas: HTMLCanvasElement): ResizeResult {
        let width = sizeChangeData.width;
        let height = sizeChangeData.height;

        if (sizeChangeData.changedDimensionName === DIMENSION_PROPERTIES.WIDTH) {
            if (sizeChangeData.constrainedProportions) {
                height = Math.round(width / sizeChangeData.aspectRatio);
            }

            width = sizeChangeData.changedDimensionValue;
        }

        if (sizeChangeData.changedDimensionName === DIMENSION_PROPERTIES.HEIGHT) {
            if (sizeChangeData.constrainedProportions) {
                width = height * sizeChangeData.aspectRatio;
            }

            height = sizeChangeData.changedDimensionValue;
        }

        const context = canvas.getContext("2d");

        canvas.width = width;
        canvas.height = height;
        context.drawImage(img, 0, 0, width, height);

        return {
            dataUrl: context.canvas.toDataURL(null, 1.0),
            width,
            height
        };
    }
}

export interface SizeChangeData {
    width: number;
    height: number;
    changedDimensionName: string;
    changedDimensionValue: number;
    aspectRatio: number;
    constrainedProportions: boolean;
}

export interface ResizeResult {
    width: number;
    height: number;
    dataUrl: string;
}
