import {
    Component,
    Input,
    Output,
    EventEmitter,
    ContentChildren,
    QueryList,
    ViewEncapsulation,
    AfterContentInit,
    TemplateRef,
    SimpleChanges,
    OnChanges,
    ViewChild,
    OnInit,
    AfterViewInit,
    ViewChildren,
    ElementRef
} from "@angular/core";

import { ActivatedRoute } from "@angular/router"

import { ListColumnDirective } from "./list-column.directive";
import { ColumnModel } from "../../models/column-model";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { ComponentData, TemplateData } from "@progress/sitefinity-component-framework";
import { DataContext } from "../../models/data-context-component";
import { CommandInvoker, ItemCommand, COMMAND_NAMES } from "../../../content/dynamic-modules/components/commands";
import { SORT_ORDER } from "../../../content/constants";
import { TreeWrapperComponent, TreeConfig, TreeItem } from "../../../../../../fields/index";
import { TreeNode } from "@circlon/angular-tree-component";
import { StateWrapper } from "../../../content/dynamic-modules/services/dynamic-item-store-state";
import { ActionItem } from "../../../../../../fields/types/types";
import { Properties } from "../../fields.constants";
import { LoadItemsResponse } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { TOGGLE_CSS_CLASS, TITLE_CSS_CLASS } from "../../../content/dynamic-modules/services/backend-tweaks/col-initializers";
import { SiteData, SiteDataStore } from "../../services/metadata/site-data.store";
import { first } from "rxjs";
import { AppStore } from "../../../../services/store/app-store";
import { COLUMN_SELECTORS } from "../../../../services/store/selectors/selectors.columns";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export const LIST_LOOK_CENTER_VERTICAL: string = "center-vertical";
export const CLICKABLE_ELEMENT_CSS_CLASS = "-sf-clickable";
const ANCHOR_NODE_NAME: string = "A";
const LIST_CSS_CLASS: string = "sf-tree-list";
const ASCENDING_FIELD_ICON = "caret-up";
const DESCENDING_FIELD_ICON = "caret-down";

// TODO: tests
@Component({
    selector: "sf-list",
    templateUrl: "./list.component.html",
    encapsulation: ViewEncapsulation.None
})
export class ListComponent extends SfRxBase implements AfterContentInit, CommandInvoker, OnChanges, OnInit, AfterViewInit {
    @ViewChild("sfTree", { static: false }) protected treeWrapperComponent: TreeWrapperComponent;
    @ViewChildren("treeListRowElement") treeListRowElement: QueryList<any>;

    @Input() treeConfig: TreeConfig;

    // TODO: create a settings object to wrap all input properties if more have to be added
    @Input() selectedItem: DataItem;
    @Input() shouldHideHeader: boolean = false;
    @Input() look: string;
    @Input() ignoreLoaderDelay: boolean = false;

    @Input() itemsState: StateWrapper;
    @Input() columns: ColumnModel[];
    @Input() sortExpression: string;

    // TODO: remove
    @Output() itemSelectionChanged = new EventEmitter<DataItem>();
    @Output() itemSelected = new EventEmitter<ItemSelectionInfo>();
    @Output() onCommand = new EventEmitter<ItemCommand>();
    @Output() expandedItemsChanged = new EventEmitter<string[]>();
    @Output() visibleNodesCountChanged: EventEmitter<number> = new EventEmitter<number>();

    first: number = 0;
    listCssClass: string;
    isLoading: boolean;

    @ContentChildren(ListColumnDirective)
    private columnsTemplate: QueryList<ListColumnDirective>;

    private columnsNameTemplateMap = new Map<string, CellModel>();
    private itemSelectionInfo: ItemSelectionInfo = {
        selectedItems: new Map<string, DataItem>(),
        deselectedItems: new Map<string, DataItem>(),
        excludedItems: new Array<string>(),
        nodesPositions: new Map<string, number>()
    };

    private siteData: SiteData;
    private currentEntitySet: string;

    constructor(private appStore: AppStore, private siteDataStore: SiteDataStore, private activatedRoute: ActivatedRoute) {
        super();
    }

    ngAfterViewInit(): void {
        const sub = this.treeListRowElement.changes.subscribe(el => {
            this.treeListRowElement.forEach((x: ElementRef) => {
                x.nativeElement.style.setProperty("--row-height", x.nativeElement.offsetHeight);
            })
        });

        this.registerSubscription(sub);
    }

    onItemSelectionChanged(event, dataItem) {
        if (event.target.nodeName !== ANCHOR_NODE_NAME) {
            this.selectedItem = dataItem;
            this.itemSelectionChanged.emit(dataItem);
            this.onCommand.emit({
                name: COMMAND_NAMES.selectionChanged,
                data: dataItem
            });
        }
    }

    treeNodeClicked(event) {
        if (event.data.dataItem.data.isLink) {
            this.onCommand.emit({
                name: event.data.dataItem.data.action,
                data: event
            });
        }
    }

    onExpandedNodesChanged(event) {
        this.expandedItemsChanged.emit(event);
    }

    onItemSelectionChangedOnEnter(item) {
        const dataItem = item.data.dataItem;
        if (dataItem) {
            this.selectedItem = dataItem;
            this.itemSelectionChanged.emit(dataItem);
            this.onCommand.emit({
                name: COMMAND_NAMES.selectionChanged,
                data: dataItem
            });
        }
    }

    ngOnInit() {
        if (!this.treeConfig) {
            // add empty config whenever list is not hierarchical
            this.treeConfig = {};
        }

        this.registerSubscription(this.siteDataStore.getValue().pipe(first()).subscribe(x => {
            this.siteData = x;
        }));

        this.registerSubscription(this.activatedRoute.data.subscribe(x => {
            this.currentEntitySet = x.dynamicItems?.metadata.setName;
        }));

        this.registerSubscription(this.appStore.pipe(COLUMN_SELECTORS.expandedColumnsPerEntity).subscribe(x => {
            this.setColumnsHeaderCssClass();
        }));
    }

    ngAfterContentInit() {
        this.initColumns();
        this.listCssClass = this.generateCssClassList();
    }

    ngOnChanges(changes: SimpleChanges) {
        const componentDataChangeName = "columns";
        const columnsChange = changes[componentDataChangeName];

        if (columnsChange && !columnsChange.isFirstChange()) {
            this.columns = columnsChange.currentValue;
            this.ngAfterContentInit();
        }

        this.updateHeaderCssClass(changes);
    }

    onCheckBoxClicked(node: TreeNode): void {
        const dataItem: DataItem = node.data.dataItem;
        const dataItemId = dataItem.key;

        if (this.itemSelectionInfo.selectedItems.has(dataItemId)) {
            this.itemSelectionInfo.selectedItems.delete(dataItemId);
            this.itemSelectionInfo.deselectedItems.set(dataItemId, dataItem);
        } else {
            this.itemSelectionInfo.selectedItems.set(dataItemId, dataItem);
            this.itemSelectionInfo.nodesPositions.set(dataItemId, node.position);
            if (this.itemSelectionInfo.deselectedItems.has(dataItemId)) {
                this.itemSelectionInfo.deselectedItems.delete(dataItemId);
                this.itemSelectionInfo.nodesPositions.delete(dataItemId);
            }
        }

        if (this.itemSelectionInfo.selectedItems.size === 1) {
            const dataItem = this.itemSelectionInfo.selectedItems.values().next().value;
            const dataItemKey = dataItem.key;
            let singleSelectedItem = this.itemsState.dataItems.find(d => d.key === dataItemKey);

            if (!singleSelectedItem && !this.treeConfig.isHierarchical) {
                return;
            }

            // child nodes are not in the state
            if (this.treeConfig.isHierarchical && !singleSelectedItem) {
                singleSelectedItem = dataItem;
            }

            this.itemSelectionInfo.selectedItems.set(dataItemKey, singleSelectedItem);
        }

        this.itemSelected.emit(this.itemSelectionInfo);
    }

    selectAllNodes(excludedNodeIds: string[]) {
        if (this.treeWrapperComponent) {
            this.treeWrapperComponent.selectAllNodes(excludedNodeIds);
            const mappedNodes = this.treeWrapperComponent.nodes
                .filter(n => {
                    return excludedNodeIds.indexOf(n.data.Id) === -1 && !n.data.disableCheckbox;
                })
                .map((n: DataItem): [string, DataItem] => [n.key, n]);
            this.itemSelectionInfo = {
                selectedItems: new Map<string, DataItem>(mappedNodes),
                excludedItems: excludedNodeIds,
                deselectedItems: new Map<string, DataItem>(),
                nodesPositions: new Map<string, number>()
            };

            this.itemSelected.emit(this.itemSelectionInfo);
        }
    }

    clearAllSelectedNodes() {
        if (this.treeWrapperComponent) {
            this.treeWrapperComponent.clearAllSelectedNodes();
        }

        this.itemSelectionInfo = {
            selectedItems: new Map<string, DataItem>(),
            deselectedItems: new Map<string, DataItem>(),
            excludedItems: new Array<string>(),
            nodesPositions: new Map<string, number>()
        };

        this.itemSelected.emit(this.itemSelectionInfo);
    }

    onColumnHeaderClicked(col: ColumnModel) {
        if (col.onColumnHeaderClicked) {
            col.onColumnHeaderClicked({ siteCultures: this.siteData.ContentCultures, entitySet: this.currentEntitySet });
        }

        if (col.sortableFieldName) {
            this.sortByColumn(col);
        }
    }

    sortByColumn(col: ColumnModel) {
        const ascendingSortExpression = this.getSortExpression(col.sortableFieldName, SORT_ORDER.ASCENDING);
        const descendingSortExpression = this.getSortExpression(col.sortableFieldName, SORT_ORDER.DESCENDING);
        let defaultSortExpression = ascendingSortExpression;
        if (col.defaultSortOrder) {
            defaultSortExpression = this.getSortExpression(col.sortableFieldName, col.defaultSortOrder);
        }

        if (this.areEqual(this.sortExpression, descendingSortExpression)) {
            this.sortExpression = ascendingSortExpression;
        } else if (this.areEqual(this.sortExpression, ascendingSortExpression)) {
            this.sortExpression = descendingSortExpression;
        } else {
            this.sortExpression = defaultSortExpression;
        }

        this.invoke({
            name: COMMAND_NAMES.sortExpressionChanged,
            data: this.sortExpression
        });
    }

    getComponentData(col: ColumnModel, dataItem: DataItem): ComponentData {
        if (!col.componentData) {
            return null;
        }

        const context: DataContext = {
            dataItem: dataItem,
            invoker: this,
            model: col,
            isVirtualized: this.treeConfig.virtualizationOptions?.isVirtualized
        };

        col.componentData.properties = col.componentData.properties || {};
        col.componentData.properties["context"] = context;
        return col.componentData;
    }

    getTemplateData(col: ColumnModel, dataItem: DataItem): TemplateData {
        const template = this.columnsTemplate.find(x => x.name === col.name);
        if (!template) {
            return null;
        }

        return {
            template: template.templateRef,
            context: dataItem
        };
    }

    loadMoreChildNodes(items: LoadItemsResponse, node: any, isLoadingForFirstTime): TreeItem[] {
        if (!isLoadingForFirstTime) {
            this.removeLoadMoreLink(node.data.children);
        }
        // wrap items in TreeItem in order to call update, because DataItem is immutable
        const treeItems = this.wrapDataItems(items.dataItems);
        if (isLoadingForFirstTime) {
            this.addLoadMoreLink(treeItems, node.data.dataItem.key, items.totalCount, items.entityData);
        } else {
            node.data.children = node.data.children.concat(treeItems);
            this.addLoadMoreLink(node.data.children, node.data.dataItem.key, items.totalCount, items.entityData);
            this.treeWrapperComponent.updateTreeModel();
        }
        return treeItems;
    }

    onVisibleNodesCountChanged(value: number) {
        this.visibleNodesCountChanged.emit(value);
    }

    protected addLoadMoreLink(array: TreeItem[], key: string, totalCount: number, entityData: EntityData) {
        if (array.length > 0 && totalCount > array.length) {
            const loadMoreModel: ActionItem = { Title: "Load more", Id: `${key}_loadMore`, action: COMMAND_NAMES.loadMoreChildren, isSelectionDisabled: false, isLink: true, icon: "repeat", iconLook: "size-xs color-inherit" };
            const dataItem = DataItem.fromEntityData(loadMoreModel, entityData);
            const loadMoreDataItem: TreeItem = {
                dataItem: dataItem,
                hasChildren: false
            };
            array.push(loadMoreDataItem);
        }
    }

    protected removeLoadMoreLink(array: any[]) {
        const loadMoreItemsIndex = array.findIndex(item => {
            if (item.dataItem.data) {
                const i = item.dataItem.data as ActionItem;
                return i && !!i.action;
            }
        });

        if (loadMoreItemsIndex >= 0) {
            array.splice(loadMoreItemsIndex, 1);
        }
    }

    protected wrapDataItems(dataItems: DataItem[]): TreeItem[] {
        return dataItems.map((item) => {
            const wrapper: TreeItem = {
                dataItem: item,
                hasChildren: item.data && item.data.hasOwnProperty(Properties.HAS_CHILDREN) && item.data[Properties.HAS_CHILDREN]
            };
            return wrapper;
        });
    }

    invoke(command: ItemCommand): void {
        this.onCommand.emit(command);
    }

    protected getModel(columnName: string): CellModel {
        return this.columnsNameTemplateMap.get(columnName);
    }

    private initColumns(): void {
        if (!this.columns) {
            this.columns = this.columnsTemplate.toArray().map(template => {
                const returnObj: ColumnModel = {
                    name: template.name,
                    title: template.title || template.name,
                    clickable: template.clickable
                };

                return returnObj;
            });
        }

        this.columns = this.columns.filter((column) => {
            return !column.hidden;
        });

        this.columns.forEach((column) => {
            const cellModel: CellModel = {
                column: column,
                componentData: column.componentData,
                invoker: this,
                css: column.css
            };

            const columnDef = this.columnsTemplate.find(x => x.name === column.name);
            if (columnDef) {
                cellModel.template = columnDef.templateRef;
                cellModel.css = !cellModel.css ? columnDef.class : cellModel.css + " " + columnDef.class;

                if (cellModel.column.clickable) {
                    if (!cellModel.css) {
                        cellModel.css = CLICKABLE_ELEMENT_CSS_CLASS;
                    } else {
                        cellModel.css += " " + CLICKABLE_ELEMENT_CSS_CLASS;
                    }
                }
            }

            this.columnsNameTemplateMap.set(column.name, cellModel);
        });

        this.setColumnsHeaderCssClass();
    }

    private updateHeaderCssClass(changes: SimpleChanges) {
        const expressionChanges = [
            "itemsState",
            "sortExpression",
            "treeConfig"
        ];

        expressionChanges.forEach(expression => {
            if (changes[expression] && !changes[expression].isFirstChange()) {
                this.setColumnsHeaderCssClass();
            }
        });
    }

    private setColumnsHeaderCssClass(): void {
        if (this.columns) {
            this.columns.forEach((column) => {
                const cellModel: CellModel = this.columnsNameTemplateMap.get(column.name);
                this.setCellModelHeaderCssClass(column, cellModel);
            });
        }
    }

    private setCellModelHeaderCssClass(column: ColumnModel, cellModel: CellModel): void {
        if (cellModel) {
            let result: string[] = [];
            if (cellModel.css) {
                result = result.concat(cellModel.css.split(" "));
            }

            cellModel.fieldIcon = null;
            if (column.sortableFieldName) {
                // Add clickable CSS class if sortable
                result.push(CLICKABLE_ELEMENT_CSS_CLASS);

                const ascendingSortExpression = this.getSortExpression(column.sortableFieldName, SORT_ORDER.ASCENDING);
                const descendingSortExpression = this.getSortExpression(column.sortableFieldName, SORT_ORDER.DESCENDING);

                // Add "sorted" CSS class to current column if items are sorted by current column`s sort expression
                if (this.sortExpression) {
                    if (this.areEqual(this.sortExpression, ascendingSortExpression)) {
                        cellModel.fieldIcon = ASCENDING_FIELD_ICON;
                    } else if (this.areEqual(this.sortExpression, descendingSortExpression)) {
                        cellModel.fieldIcon = DESCENDING_FIELD_ICON;
                    }
                }
            }

            if (column.setCustomCss && this.treeConfig?.virtualizationOptions) {
                const customCssResult = column.setCustomCss({
                    isVirtualized: this.treeConfig.virtualizationOptions.isVirtualized || false,
                    cellModel,
                    siteCultures: this.siteData?.ContentCultures || [],
                    result
                });

                if (customCssResult) {
                    result = customCssResult.result;
                    cellModel = customCssResult.cellModel;
                }
            }

            if (column.css && column.css.indexOf(TITLE_CSS_CLASS) > -1) {
                result = this.toggleHierarchicalTitleClass(result);
            }

            cellModel.headerCss = result.join(" ");
        }
    }

    private toggleHierarchicalTitleClass(classes: string[]): string[] {
        const toggleClassIndex = classes.indexOf(TOGGLE_CSS_CLASS);

        if (this.treeConfig.isHierarchical && toggleClassIndex < 0) {
            classes.push(TOGGLE_CSS_CLASS);
        }

        if (!this.treeConfig.isHierarchical && toggleClassIndex > -1) {
            classes.splice(toggleClassIndex, 1);
        }

        return classes;
    }

    private areEqual(first: string, second: string): boolean {
        if ((!first && !second && first === second) ||
            (first && second && first.toLowerCase() === second.toLowerCase())) {
            return true;
        }

        return false;
    }

    private getSortExpression(colName: string, order: string) {
        return `${colName} ${order}`;
    }

    private generateCssClassList() {
        let cls = LIST_CSS_CLASS;
        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }
        return cls;
    }
}

export interface CellModel {
    column: ColumnModel;
    css?: string;
    headerCss?: string;
    fieldIcon?: string;
    template?: TemplateRef<any>;
    componentData?: ComponentData;
    invoker?: CommandInvoker;
}

export interface ItemSelectionInfo {
    selectedItems: Map<string, DataItem>;
    deselectedItems: Map<string, DataItem>;
    excludedItems: Array<string>;
    nodesPositions: Map<string, number>;
}
