import { NotificationData, NOTIFICATION_LOOKS } from "../../../services/notification/notification-data";
import { MappedResult, ResultMapperBase } from "../../modal-list/mappers/modal-list-mapper-base";
import { BasicNotificationComponent } from "../../notifications/basic-notification/basic-notification.component";

export class SiteSyncResultMapper extends ResultMapperBase {

    map(item: any): MappedResult {
        const hasFailedItem = item.Items.find(i => i.Status !== "Successful");
        const counterLook = hasFailedItem ? "negative" : "positive";

        let notificationData: NotificationData = null;

        if (item.GeneralErrors) {
            notificationData = {
                look: NOTIFICATION_LOOKS.ERROR  + " sf-mb-m",
                type: BasicNotificationComponent,
                properties: {
                    message: item.GeneralErrors
                },
                duration: null,
                updatePropertiesOnChange: true,
                id: "generalErrorNotification"
            };
        }

        return {
            additionalTitle: item.DateOfCompletion,
            items: item.Items,
            counterLook: counterLook,
            notificationData: notificationData
        };
    }
}
