import { ControlValueAccessor, NG_VALUE_ACCESSOR } from "@angular/forms";
import { FieldValidation } from "./field-validation";
import { Type, forwardRef, Input, OnInit, QueryList, Directive } from "@angular/core";
import { SettingsBase } from "./field-settings-base";
import { stringConstants } from "../src/app/common-constants";
import { StatusType } from "./field-status";
import { Observable, BehaviorSubject, of, ReplaySubject } from "rxjs";
import { cloneObject } from "../src/app/utils";
import { DataContext, DataContextComponent } from "../src/app/modules/shared/models/data-context-component";
import { AsyncFieldValue } from "./async-field-value";
import { MEDIA_TYPES } from "../src/app/modules/shared/services/metadata/meta-data-constants";
import { MEDIA_CONTENT_TYPES } from "../src/app/modules/libraries/media-content.types";
import { DynamicTemplateDirective } from "../src/app/modules/shared/fields-builder/components/editable-fields/dynamic-template.directive";
import { SfRxBase } from "@progress/sitefinity-component-framework";

export function createValueAccessor(field: Type<FieldBase>) {
    return {
        provide: NG_VALUE_ACCESSOR,
        useExisting: forwardRef(() => field),
        multi: true
    };
}

// FieldBase implements DataContextComponent, because we want the fields to be able to display data in dynamically added grid columns.
/**
 * @ExposedInApi {FieldBase} FieldBase v1/custom-fields/field-base.d.ts
 */
@Directive()
// tslint:disable-next-line: component-class-suffix
export abstract class FieldBase<TSettings = SettingsBase, TValue = any> extends SfRxBase implements ControlValueAccessor, OnInit, DataContextComponent {
    @Input() public context: DataContext;

    protected validation: FieldValidation;

    /**
     * The status observable. The intial state is done as most fields to not have async actions and are valid at start
     */
    private _status$ = new BehaviorSubject<Status>({ type: StatusType.Done });
    private _hidden$ = new BehaviorSubject<boolean>(false);

    private _isFocused$ = new ReplaySubject<boolean>(1);
    private _value: TValue = null;
    private _settings: TSettings;
    private allowDialogOpenCallback: () => Observable<boolean>;
    protected outputTemplateCallback = new ReplaySubject<QueryList<DynamicTemplateDirective>>(1);

    constructor() {
        super();
        this.validation = new FieldValidation(this);
    }

    get settings() {
        return this._settings;
    }

    @Input()
    set settings(items: TSettings) {
        this._settings = items;
    }

    ngOnInit() {
        if (this.context && this.context.dataItem && this.context.model) {
            const dataFieldName = this.context.model.dataFieldNames[0];
            const fieldValue = this.context.dataItem.data[dataFieldName];
            this.writeValue(fieldValue);
        }
    }

    /**
     * @deprecated Use getValue() instead
     */
    public get value(): TValue {
        return this.getValue();
    }

    /**
     * @deprecated Use writeValue() instead
     */
    public set value(value: TValue) {
        this.writeValue(value);
    }

    get focus$(): Observable<boolean> {
        return this._isFocused$.asObservable();
    }

    /**
     * Gets the status of the field.
     */
    get status$(): BehaviorSubject<Status> {
        // TODO remove this property and instead use async validation (by making validate method return observable<boolean>)
        return this._status$;
    }

    get hidden$(): Observable<boolean> {
        return this._hidden$.asObservable();
    }

    protected setHidden(hidden: boolean) {
        this._hidden$.next(hidden);
    }

    /**
     * @deprecated Use status$ directly
     * Emits a status.
     * @param status The status to be emitted.
     */
    emitStatus(status: Status): void {
        this._status$.next(status);
    }

    onFocus(): void {
        this._isFocused$.next(true);
    }

    onBlur(): void {
        this._isFocused$.next(false);
    }

    processErrors(errors: any): Array<string> {
        const clonedErrors = cloneObject(errors);
        let errorMsgs: Array<string> = [];
        if (clonedErrors && (clonedErrors.required === true || clonedErrors["sfc-required"])) {
            if (clonedErrors.required) {
                delete clonedErrors.required;
            }
            if (clonedErrors["sfc-required"]) {
                delete clonedErrors["sfc-required"];
            }
            const requiredMessage = this.getRequiredErrorMessage();
            errorMsgs = errorMsgs.concat(requiredMessage);
        }

        const otherErrorMessages = this.validation.getErrorMessage(clonedErrors);
        if (otherErrorMessages) {
            errorMsgs = errorMsgs.concat(otherErrorMessages);
        }

        return errorMsgs;
    }

    getRequiredErrorMessage(): Array<string> {
        return this.validation.getErrorMessage({ required: true });
    }

    getWarnings(): Array<string> {
        return [];
    }

    getValue(): TValue {
        if (this._value instanceof AsyncFieldValue) {
            return this._value.asyncValue;
        }

        return this._value;
    }

    // This method is used for cases when you want to modify the value before going to the DB.
    postProcessValue(value: any): any {
        return value;
    }

    writeValue(value: TValue): void {
        let currentValue = this._value;
        if (currentValue instanceof AsyncFieldValue) {
            currentValue = currentValue.asyncValue;
        }

        let newValue = value;
        if (newValue instanceof AsyncFieldValue) {
            newValue = newValue.asyncValue;
        }

        if (newValue !== currentValue) {
            this._value = value;
            if (this.onChangeCallback) {
                this.onChangeCallback(value);
            }
        }
    }

    /**
     *  This method is used to trigger Validation of fields which Value is complex object.
     */
    validate(): boolean {
        return true;
    }

    registerOnChange(fn: any) {
        this.onChangeCallback = fn;
    }

    registerOnTouched(fn: any) {
        this.onTouchedCallback = fn;
    }

    /**
     * this method is used to commit the current value manually
     * so that the validation could be triggered on silent commands via keyboard keys
     */
    commitValue() {
    }

    public hasEmptyValue() {
        if (!this.value || typeof this.value === "string" && this.value === stringConstants.EMPTY_STRING)
            return true;

        if (this.value instanceof Object) {
            if (Object.keys(this.value).length === 0) {
                if (this.value instanceof Date) {
                    return false;
                }

                return true;
            }
        }

        if (this.value instanceof Array && this.value.length === 0) {
            return true;
        }

        return false;
    }

    protected onTouchedCallback: () => void = () => { };

    // TODO: onchangecallback should be private
    protected onChangeCallback: (value: TValue) => void = () => { };

    protected getNoPermissionMessage(relatedTypeName: string): string {
        switch (relatedTypeName) {
            case MEDIA_TYPES.IMAGE:
                relatedTypeName = MEDIA_CONTENT_TYPES.image.plural;
                break;
            case MEDIA_TYPES.VIDEO:
                relatedTypeName = MEDIA_CONTENT_TYPES.video.plural;
                break;
            case MEDIA_TYPES.DOCUMENT:
                relatedTypeName = MEDIA_CONTENT_TYPES.document.plural;
                break;
        }

        return `Ask your administrator for view permissions for ${relatedTypeName}`;
    }

    public registerAllowDialogOpenCallback(allowDialogOpenCallback: () => Observable<boolean>) {
        this.allowDialogOpenCallback = allowDialogOpenCallback;
    }

    public invokeOutputTemplateCallback(templates: QueryList<DynamicTemplateDirective>) {
        this.outputTemplateCallback.next(templates);
    }

    protected invokeAllowDialogOpenCallback(): Observable<boolean> {
        if (this.allowDialogOpenCallback)
            return this.allowDialogOpenCallback();

        return of(true);
    }
}

/**
 * Container for holding the status of the field
 */
export interface Status {
    /**
     * The type of the status to be emitted.
     */
    type: StatusType;

    /**
     * The data to be passed
     */
    data?: any;
}
