import { Component, OnInit, ViewChild } from "@angular/core";
import { InputComponent } from "../../src/app/api";
import { FieldRegistration } from "../../src/app/modules/shared/fields-builder/services/fields-registry";
import { ChoiceComponent } from "../choice/choice.component";
import { ChoiceSettings } from "../choice/choice.settings";
import { createValueAccessor, FieldBase } from "../field-base";
import { SettingsBase } from "../field-settings-base";
import { StatusType } from "../field-status";

@Component({
    selector: "sf-file-type",
    templateUrl: "./file-types.component.html",
    providers: [createValueAccessor(FileTypesComponent)]
})

export class FileTypesComponent extends FieldBase<SettingsBase, FileTypesValue> implements OnInit {
    viewModel: ViewModel;
    @ViewChild("selected", { static: true }) selectedTemplate;
    @ViewChild("otherInput", { static: true }) otherInputTemplate;
    @ViewChild("selectedChoiceComponent", { static: false }) selectedChoiceComponent: ChoiceComponent;
    @ViewChild("otherTypesComponent", { static: false }) otherTypesComponent: InputComponent;
    allOrSpecific: string;
    fileTypesValue: string;
    otherTypesValue: string;

    private multipleChoiceSettings: ChoiceSettings;

    ngOnInit(): void {
        super.ngOnInit();

        if (this.value) {
            this.allOrSpecific = "Selected";
            if (this.value.Type) {
                let fileTypesValue = "00000";
                if (this.value.Type.indexOf("Image") !== -1) {
                    fileTypesValue = "1" + fileTypesValue.substring(1);
                }

                if (this.value.Type.indexOf("Document") !== -1) {
                    fileTypesValue = fileTypesValue.substring(0, 1) + "1" + fileTypesValue.substring(2);
                }

                if (this.value.Type.indexOf("Audio") !== -1) {
                    fileTypesValue = fileTypesValue.substring(0, 2) + "1" + fileTypesValue.substring(3);
                }

                if (this.value.Type.indexOf("Video") !== -1) {
                    fileTypesValue = fileTypesValue.substring(0, 3) + "1" + fileTypesValue.substring(4);
                }

                if (this.value.Type.indexOf("Other") !== -1) {
                    fileTypesValue = fileTypesValue.substring(0, 4) + "1";
                }

                this.fileTypesValue = fileTypesValue;
            }
            this.otherTypesValue = this.value.Other;
        } else {
            this.allOrSpecific = "All";
        }

        const choiceSettings = new ChoiceSettings("AllOrSpecific", false);
        choiceSettings.choices = [
            {
                Name: "All file types",
                Value: "All"
            },
            {
                Name: "Selected file types",
                Value: "Selected",
                ExpandedTemplate: this.selectedTemplate
            }
        ];

        choiceSettings.defaultValue = choiceSettings.choices[0].Value;

        this.multipleChoiceSettings = new ChoiceSettings("FileTypes", false);
        this.multipleChoiceSettings.hasFieldset = true;
        this.multipleChoiceSettings.choices = [
            {
                Name: "Images",
                Value: "1",
                Description: "(jpg, jpeg, png, gif, bmp)"
            },
            {
                Name: "Documents",
                Value: "2",
                Description: "(pdf, doc, docx, ppt, pptx, ppsx, xls, xlsx)"
            },
            {
                Name: "Audio",
                Value: "4",
                Description: "(mp3, ogg, wav, wma)"
            },
            {
                Name: "Video",
                Value: "8",
                Description: "(avi, mpg, mpeg, mov, mp4, wmv)"
            },
            {
                Name: "Other",
                Value: "16",
                ExpandedTemplate: this.otherInputTemplate
            }
        ];

        this.viewModel = {
            choiceSettings: choiceSettings,
            multipleChoiceSettings: this.multipleChoiceSettings
        };
    }

    onSelectionChange(value: string) {
        if (value === "All") {
            this.writeValue(null);
            this.emitStatus({ type: StatusType.ErrorCleared });
        } else {
            this.writeValue({
                Type: null
            });
        }
    }

    onFileTypesSelectionChange() {
        const typeArray = [];
        if (this.fileTypesValue && this.multipleChoiceSettings) {
            this.multipleChoiceSettings.choices.forEach((choice, index) => {
                if (this.fileTypesValue[index] === "1") {
                    switch (index) {
                        case 0:
                            typeArray.push("Image");
                            break;
                        case 1:
                            typeArray.push("Document");
                        break;
                        case 2:
                            typeArray.push("Audio");
                        break;
                        case 3:
                            typeArray.push("Video");
                            break;
                        case 4:
                            typeArray.push("Other");
                            break;
                    }
                }
            });
        }

        this.writeValue({
            Type: typeArray.join(","),
            Other: this.otherTypesValue
        });

        if (typeArray.indexOf("Other") === -1) {
            this.emitStatus({ type: StatusType.ErrorCleared });
        }
    }

    validate() {
        const currentValue = this.getValue();
        if (currentValue) {
            if ((currentValue.Type.indexOf("Other") !== -1 && !currentValue.Other) || currentValue.Type === null) {
                this.emitStatus({ type: StatusType.Error, data: { required: true } });
                return false;
            }
        }

        this.emitStatus({ type: StatusType.ErrorCleared });
        return true;
    }

    getRequiredErrorMessage(): Array<string> {
        return ["Enter file types"];
    }
}

interface FileTypesValue {
    Type: string,
    Other?: string;
}

export const FILE_TYPES_REGISTRY: FieldRegistration = {
    writeComponent: FileTypesComponent,
    readComponent: FileTypesComponent,
    settingsType: SettingsBase
};

interface ViewModel {
    choiceSettings: ChoiceSettings,
    multipleChoiceSettings: ChoiceSettings
}
