import { Component, Input, OnInit } from "@angular/core";
import { DataContext } from "../../../../../shared/models/data-context-component";
import { Observable } from "rxjs";
import { Operation } from "../../../../../shared/components/action-menu/operation.model";
import { ActionButton, ActionMenuOptions } from "../../../../../shared/components/action-menu/action-menu-model";
import { DataItem } from "../../../interfaces";
import { OUTSIDE_MENU_MAX_ORDINAL } from "../../action-buttons.resolver";
import { COMMAND_NAMES } from "../../commands";
import { ParentService } from "../../../services/parent.service";
import { mergeMap } from "rxjs/operators";
import { CompositeGridExtender } from "../../../../../shared/services/grid/composite-grid-extender";

@Component({
    selector: "sf-grid-action-menu",
    templateUrl: "./grid-action-menu.component.html"
})
export class GridActionMenuComponent implements OnInit {
    @Input() public context: DataContext;
    @Input() public dropdownButtonText: string;
    @Input() public dropdownButtonIconName: string = "ellipsis-h";

    public operations$: Observable<Operation[]>;
    public actionMenuOptions: ActionMenuOptions;
    public visible: boolean;
    isDimmed: boolean;

    constructor(private gridExtender: CompositeGridExtender, private parentService: ParentService) {
        this.actionMenuOptions = new ActionMenuOptions(OUTSIDE_MENU_MAX_ORDINAL, Number.POSITIVE_INFINITY, true);
    }

    ngOnInit() {
        this.loadOperationData(this.context);
    }

    onActionButtonClicked(button: ActionButton) {
        this.context.invoker.invoke({
            name: COMMAND_NAMES.itemActionClicked,
            data: {
                button: button,
                dataItem: this.context.dataItem
            }
        });
    }

    loadOperationData(context: DataContext) {
        this.context = context;
        this.visible = this.context != null && this.context.dataItem.isTranslated;
        if (this.visible) {
            this.isDimmed = this.context.dataItem.data.inactive;
            this.prepareOperations();
        }
    }

    prepareOperations() {
        if (!this.operations$) {
            this.operations$ = new Observable<Operation[]>((observer) => {
                this.parentService.getParentItem(this.context.dataItem, this.context.dataItem.parentKey).pipe(
                    mergeMap(parentItem => {
                        return this.gridExtender.getListItemOperations(this.context.dataItem, parentItem);
                    })
                ).subscribe(operations => observer.next(operations));
            });
        }
    }

}

export interface ActionData {
    button: ActionButton;
    dataItem: DataItem;
}
