import { SettingsBase } from "../../../fields/field-settings-base";
import { FieldRegistration } from "../modules/shared/fields-builder/services/fields-registry";

// TODO: this should be revised
/**
 * @ExposedInApi {FieldModel} FieldModel v1/fields-behaviour/field-model.d.ts
 */
export class FieldModel {
    readonly selector: string;
    value: any;
    settings: SettingsBase;
    key: string;
    registration: FieldRegistration;
    cssClass?: string;

    constructor(options: {
        key: string,
        settings?: any,
        value?: any,
        selector: string,
        registration: FieldRegistration,
        cssClass?: string
    }) {
        this.key = options.key;
        this.settings = options.settings;
        this.value = options.value;
        this.selector = options.selector;
        this.registration = options.registration;
        this.cssClass = options.cssClass;
    }
}
