import { MetadataHandler } from "../shared/services/metadata/metadata.handler";
import { Injectable } from "@angular/core";
import { KEY_VALUE_OPTIONS } from "../shared/services/metadata/meta-data-constants";
import { Properties } from "../shared/fields.constants";
import { FieldTypes } from "../shared/fields-builder/services/fields-registry";
import { FieldModel } from "../../services/field.model";
import { Entity, MetadataStore } from "../shared/services/metadata/meta-data.store";
import { FormData } from "../content/dynamic-modules/services/backend-tweaks/backend-tweaks.store";
import { ParentSelectorSettings } from "../parent-selector/parent-selector-settings";
import { ChoiceSettings } from "../../../../fields/choice/choice.settings";
import { DataItem } from "../content/dynamic-modules/interfaces";
import { Observable, of } from "rxjs";
import { StructureUrlNameSettings, UrlStructureData } from "../shared/components/urlNameStructure/structure-urlName.settings";
import { first } from "rxjs/operators";
import { MediaHelpers } from "./services/media.helpers";
import { SiteDataStore } from "../shared/services/metadata/site-data.store";
import { NumberSettings } from "../../../../fields/number/number-settings";
import { CompositeFieldsProvider } from "../shared/fields-builder/providers/fields-provider";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../../../cypress/e2e/helpers/constants";

export const LIBRARY = "Library";
export const LIBRARIES = "Libraries";

@Injectable()
export class MediaMetadataHandler extends MetadataHandler {
    fieldGroups: any[] = [];

    constructor(private metadataContainer: MetadataStore, private siteData: SiteDataStore, protected fieldsProvider: CompositeFieldsProvider) {
        super(fieldsProvider);
    }

    getFieldType(metadata: Entity, propertyName: string, propertyTweak: any): string {
        if (propertyName === Properties.PARENT_ID) {
            return FieldTypes.dropdownSelector;
        } else if (propertyName === Properties.BLOB_STORAGE_PROVIDER || propertyName === Properties.CLIENT_CACHE_PROFILE || propertyName === Properties.NEW_SIZE) {
            return FieldTypes.choiceDropDown;
        } else if (propertyName === Properties.MEDIA_FILE_URL_NAME) {
            return FieldTypes.urlName;
        } else if (propertyName === Properties.MEDIA_FILE_ADDITIONAL_URLS_NAME) {
            return FieldTypes.additionalUrls;
        } else if (propertyName === Properties.THUMBNAIL_PROFILES) {
            return FieldTypes.multipleChoiceChip;
        } else if (propertyName === Properties.MAX_SIZE || propertyName === Properties.MAX_ITEM_SIZE) {
            return FieldTypes.number;
        } else if (propertyName === Properties.THUMBNAIL_URL) {
            return FieldTypes.videoThumbnail;
        }

        return null;
    }

    processFieldGroup(propertyName: string, fields: FieldModel[], metadata: Entity, fieldTypesMap: Map<string, string>, dataItem: any, readonly: boolean, tweaks: FormData[]): string[] {
        return [];
    }

    canProcess(typeFullName: string): boolean {
        const entities = this.metadataContainer.getValue().entities;
        let entity: Entity;
        Object.keys(entities).forEach(setName => {
            const currentEntity = entities[setName];
            if (currentEntity.typeFullName === typeFullName) {
                entity = currentEntity;
                return;
            }
        });
        const isMedia = entity && entity.isMedia;
        const isLibrary = MediaHelpers.isLibraryType(typeFullName);

        return isMedia || isLibrary;
    }

    updateFieldSettings(fields: FieldModel[], metadata: Entity, tweaks: any[]) {
        this.siteData.getValue().pipe(first()).subscribe(siteData => {
            const parentIdField = fields.find(x => x.key === Properties.PARENT_ID);
            const parentSelectorSettings = parentIdField.settings as ParentSelectorSettings;

            parentSelectorSettings.friendlyTitle = LIBRARY.toLowerCase();
            parentSelectorSettings.selectorNames.plural = LIBRARIES;
            parentSelectorSettings.selectorNames.singular = LIBRARY;
            parentSelectorSettings.excludeParent = false;

            fields.forEach(field => {
                field.settings.showForAllTranslationsLabel = false;

                if (field.selector === FieldTypes.choiceDropDown || field.selector === FieldTypes.multipleChoiceChip) {
                    const settingsCast = field.settings as ChoiceSettings;
                    const tweak = tweaks.find(x => x.name === field.key);

                    if (tweak) {
                        const tweakMetadata = tweak.metadata;

                        if (tweakMetadata && tweakMetadata[KEY_VALUE_OPTIONS]) {
                            const options: ChoiceItem[] = [];

                            tweakMetadata[KEY_VALUE_OPTIONS].forEach(option => {
                                options.push({
                                    Name: option["Key"],
                                    Value: option["Value"]
                                });
                            });

                            settingsCast.choices = options;
                            if (!field.value && !settingsCast.useDefaultValue) {
                                field.value = options[0].Value;
                            }
                        }
                    }
                }
            });

            if (siteData.ContentCultures.length > 1) {
                parentSelectorSettings.showForAllTranslationsLabel = true;
            }
        });

        const urlStructureField = fields.find(x => x.settings instanceof StructureUrlNameSettings);
        if (urlStructureField) {
            const urlStructureSettings = urlStructureField.settings as StructureUrlNameSettings;
            urlStructureSettings.getUrlStructureData = (x) => this.getUrlStructureData(x);
        }

        this.updateSizeFieldsSettings(fields);

        const thumbnailUrlField = fields.find(x => x.key === Properties.THUMBNAIL_URL);
        if (thumbnailUrlField) {
            thumbnailUrlField.settings.translatable = true;
            thumbnailUrlField.settings.showForAllTranslationsLabel = false;
        }
    }

    // This is done in order not to visualize 0 in the input (UX requirement)
    private updateSizeFieldsSettings(fields: FieldModel[]) {
        fields.filter(x => x.key === Properties.MAX_SIZE || x.key === Properties.MAX_ITEM_SIZE).map(x => {
            x.settings.emptyValues.push(0);
            x.settings.look = "sf-width-2";
            (x.settings as NumberSettings).decimalPlaces = 0;
            (x.settings as NumberSettings).unitLook = "size-xs";
        });
    }

    private getUrlStructureData(dataItem: DataItem): Observable<UrlStructureData> {
        const getParentUrl = (di: DataItem) => {
            let parentUrl = stringConstants.EMPTY_STRING;
            if (di.data.Url) {
                const regexSplit = new RegExp("/" + di.data.MediaFileUrlName, "gi");
                parentUrl = di.data.Url.split(regexSplit)[0];
            }

            return parentUrl;
        };

        if (dataItem.data && dataItem.data.MediaFileUrlName) {
            return of({
                parentUrl: getParentUrl(dataItem),
                extension: dataItem.data[Properties.EXTENSION],
                editableUrl: null
            });
        }

        return of(null);
    }
}

export const MEDIA_METADATA_HANDLER = { provide: MetadataHandler, useClass: MediaMetadataHandler, multi: true };
