import { Component, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { FieldBase } from "../../../../../../fields";
import { StatusType } from "../../../../../../fields/field-status";
import { stringConstants } from "../../../../common-constants";
import { AppStore } from "../../../../services/store/app-store";
import { MEDIA_SELECTORS } from "../../../../services/store/selectors/selectors.media";
import { guid } from "../../../../utils";
import { EntityData } from "../../../content/dynamic-modules/interfaces";
import { FilePickerViewMode } from "../../../libraries/file-picker-view-mode";
import { FilePickerComponent } from "../../../libraries/file-picker.component";
import { MediaSettings } from "../../../libraries/media/media.settings";
import { MediaService, UploadFieldState } from "../../../libraries/services/media.service";
import { FieldRegistration } from "../../../shared/fields-builder/services/fields-registry";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { MediaEntity, MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { DialogData, ModalWindowService } from "../../../shared/services/modal-window.service";

@Component({
    selector: "sf-template-thumbnail",
    templateUrl: "./page-template-thumbnail.component.html"
})
export class PageTempalteThumbnailComponent extends FieldBase<MediaSettings> implements OnInit {
    thumbnailUrl: string;

    private sourceLibraryId: string;
    private acceptableMediaTypes: string[] = [];
    private acceptableFileTypes: string[] = [];
    private maxSize: number;
    private useLiveData: boolean = false;
    private uniqueName: string;
    private mediaEntity: EntityData;

    constructor(
        private modalService: ModalWindowService,
        private route: ActivatedRoute,
        private metadataStore: MetadataStore,
        private appStore: AppStore,
        private mediaService: MediaService) {
            super();
        }

    ngOnInit() {
        const entity = this.metadataStore.getEntity(ENTITY_SET.IMAGES).clone() as MediaEntity;
        this.thumbnailUrl = this.settings?.dataItem?.data?.ThumbnailUrl;

        if (!this.thumbnailUrl) {
            this.thumbnailUrl =  this.settings.defaultValue;
            this.writeValue(null);
        }

        this.sourceLibraryId = this.settings.sourceLibraryId;
        this.useLiveData = this.settings.useLiveData;
        this.maxSize = this.settings.maxSize;
        this.settings.defaultValue = [];
        this.acceptableMediaTypes = this.settings.acceptableMediaTypes;
        this.acceptableFileTypes = this.settings.acceptableFileTypes;
        this.uniqueName = `${this.settings.name}${this.settings.dataItem ? this.settings.dataItem.key : guid()}`;
        this.mediaEntity = {metadata: entity, provider: this.settings.provider, culture: this.settings.dataItem.culture};

        this.mediaService.clearUploads();
        const uploadSubscription = this.appStore.pipe(MEDIA_SELECTORS.uploadsData).subscribe(jobs => {
            this.onUpload(jobs.items, jobs.uploadFieldState);
        });

        this.registerSubscription(uploadSubscription);
    }

    writeValue(value: any): void {
        const val = Array.isArray(value) ?  value : [value];
        super.writeValue(val);
    }

    postProcessValue(value) {
        if (value) {
            if (Array.isArray(value)) {
                return value[0] ? value[0] : stringConstants.DEFAULT_GUID;
            } else {
                return value;
            }
        }

        return stringConstants.DEFAULT_GUID;
    }

    handleFileUpload() {
        const componentData: ComponentData = {
            type: FilePickerComponent,
            afterComponentInit: (component: FilePickerComponent) => {
                component.value = this.value.map(x => { return {data: {Id: x}}; });
            },
            properties: {
                formattedTypeName: "a template image",
                name: this.uniqueName,
                acceptableFileTypes: this.acceptableFileTypes,
                acceptableMediaTypes: this.acceptableMediaTypes,
                maxSize: this.maxSize,
                allowCreate: this.settings.allowCreate,
                initialViewMode: FilePickerViewMode.Select,
                useOnlySelectMode: false,
                sourceLibraryId: this.sourceLibraryId,
                targetLibraryId: this.sourceLibraryId,
                useLiveData: this.useLiveData,
                multiple: false,
                value: this.value.map(x => { return {data: {Id: x}}; }),
                mediaEntityData: this.mediaEntity,
                showParentLibrary: false
            }
        };

        componentData.properties.showProviderSelector = false;
        const dialogData = new DialogData(componentData, (result) => {
            if (result && result.data) {
                const image = result.data.data ?? result.data;
                this.writeValue(image.Id);
                this.thumbnailUrl = image.Url;
            }
        }, [], "-prompt");

        this.modalService.setMapping(dialogData, "openTemplateFilePicker");
        this.modalService.open(this.route, "openTemplateFilePicker");
    }

    private onUpload(jobs: any[], uploadFieldState: UploadFieldState): void {
        jobs.filter(job => job.key === this.uniqueName).forEach((job, jobIndex) => {
            const { success, result } = job.upload;
            this.emitStatus({ type: StatusType.Pending });

            if (success) {
                this.writeValue(result.Id);
                this.thumbnailUrl = result.Url;
                this.mediaService.removeUploadById(job.upload.id);
            } else {
                if (job.upload.failure) {
                    this.emitStatus({ type: StatusType.Error, data: result.errorMessage });
                }
            }
        });

        if (uploadFieldState.fieldName === this.uniqueName) {
            this.emitStatus({ type: StatusType.Done });
        }
    }
}

export const PAGE_TEMPLATE_THUMBNAIL_REGISTRY: FieldRegistration = {
    writeComponent: PageTempalteThumbnailComponent,
    readComponent: PageTempalteThumbnailComponent,
    settingsType: MediaSettings
};
