import { ActivatedRoute, Params } from "@angular/router";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { Observable, Subject } from "rxjs";
import { Command } from "../../../shared/commands/command";
import { ExecutionContext } from "../../../shared/commands/execution-context";
import { DialogData, ModalWindowService } from "../../../shared/services/modal-window.service";
import { MobilePreviewResizerComponent } from "./mobile-preview-resizer.component";
import { MobilePreviewComponent } from "./mobile-preview.component";

const SEGMENT_QUERY_STRING = "segment";

export class MobilePreviewCommand implements Command {
    constructor(private modalWindowService: ModalWindowService) { }

    private mobilePreviewRoute = "mobile-preview";

    execute(context: ExecutionContext): Observable<any> {
        let pagePreviewUrl: string = context.data.previewUrl;
        const route: ActivatedRoute = context.currentRoute;
        const done = new Subject<void>();
        pagePreviewUrl = this.appendPageSegment(pagePreviewUrl, route.snapshot?.queryParams);
        const componentData: ComponentData = {
            type: MobilePreviewComponent,
            properties: {
                pagePreviewUrl
            }
        };

        const dialogData = new DialogData(componentData, () => { done.next(); });
        dialogData.alwaysSticky = true;
        dialogData.hideBackToTopButton = true;
        dialogData.contentClass = "-preview";
        dialogData.toolbarData = {
            type: MobilePreviewResizerComponent
        };

        this.modalWindowService.setMapping(dialogData, this.mobilePreviewRoute);
        this.modalWindowService.show(this.mobilePreviewRoute, route);
        return done.asObservable();
    }

    private appendPageSegment(urlFromServer: string, queryParams: Params) {
        // The preview url for the .net core pages comes with the personalization segment from the server
        // while the "classic" pages do not, their segment is taken from the url in the edit page.
        if (!urlFromServer.includes(SEGMENT_QUERY_STRING) && queryParams && queryParams.segment) {
            return `${urlFromServer}?${SEGMENT_QUERY_STRING}=${queryParams.segment}`;
        }

        return urlFromServer;
    }
}
