import { Observable } from "rxjs";
import { Type } from "@angular/core";
import { TokenData } from "@progress/sitefinity-component-framework";
import { Operation } from "./operation.model";

export enum ButtonState {
    Default = 0 << 0,
    Loading = 1 << 0,
    Checked = 1 << 1,
    Disabled = 1 << 2
}

export const PRIMARY_BUTTON_ORDINAL = -1;

export class LoadingButton {
    public loader?: Observable<string>;
    public checked?: Observable<boolean>;
    public disabled?: Observable<boolean>;
}

export class ActionButton extends LoadingButton {

    public sourceOperation?: Operation;

    public detailedTitle?: string;

    public loading?: Observable<boolean>;

    public ordinal?: number;

    public parameters?: any;

    public contextParameters?: any;

    public look?: string;

    public icon?: string;

    public iconLook?: string;

    public description?: string;

    public link?: string;

    /* context should be used carefully for bindings only*/
    public context?: ActionButtonContext;

    public token?: TokenData;

    public requiresConfirmation: boolean = false;

    public warningMessage?: string;

    public subAction?: ActionButton;

    public isSubAction?: boolean;

    public subText?: string;

    constructor(public title: string, public name: string) {
        super();
    }

    public get isPrimary(): boolean {
        return this.ordinal === PRIMARY_BUTTON_ORDINAL;
    }
}

export class ActionSection {
    constructor(public readonly title: string, public hidden: boolean = false, public readonly name?: string) { }
}

export class SidebarActionButton extends ActionButton {
    constructor(
        title: string,
        name: string,
        public componentType: Type<any> // TODO
    ) {
        super(title, name);
    }
}

// TODO
export class ToolbarButton {
    constructor(
        public title: string,
        public isActive: Observable<boolean>,
        public action: () => void
    ) { }
}

export class ActionMenuOptions {
    constructor(
        public minOrdinal: number = Number.NEGATIVE_INFINITY,
        public maxOrdinal: number = Number.POSITIVE_INFINITY,
        public showAllAsDropdown: boolean = false) {
    }
}

export interface ActionButtonContext {
    additionalText?: string,
    icon?: string,
    iconLook?: string;
    count?: Observable<any>
}
