    customOperations: BehaviorSubject<Operation[]>;
    additionalActionOperations: BehaviorSubject<Operation[]>;
    personalizationOperations: BehaviorSubject<Operation[]>;
    buttonsState: ButtonsState;
    contentLoaderHeight: number;
    sidebarClasses$ = new BehaviorSubject<string>(DEFAULT_CLASS);
    formClasses: string = stringConstants.EMPTY_STRING;
    isLocked: boolean = false;
    item$: Observable<DataItem>;
    filterCleared: boolean = false;
    allowDialogOpenCallback: () => Observable<boolean> = this.triggerLock.bind(this);
    isActionInProgress: Subject<boolean> = new Subject<boolean>();
    hasSidebar: boolean;

    protected sidebarData: SidebarData;
    protected item: BehaviorSubject<LoadingActionState> = new BehaviorSubject<LoadingActionState>({ content: null, isLoading: true });
