import { FieldBase, createValueAccessor } from "../../../../../../../fields";
import { Component, OnInit, ViewChild } from "@angular/core";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { DatePickerComponent } from "@progress/kendo-angular-dateinputs";
import { InputComponent } from "../../../../../api";
@Component({
    selector: "sf-datetime-selector",
    templateUrl: "./date-time-selector.component.html",
    providers: [createValueAccessor(DateTimeSelectorComponent)]
})
export class DateTimeSelectorComponent extends FieldBase<SettingsBase, DateTimeFilterValue> implements OnInit {

    @ViewChild("fromDate", { static: false }) set fromDateComponent(fromDateComponent: DatePickerComponent) {

        if (fromDateComponent) {
            fromDateComponent.writeValue(this.currentValue["FromDate"]);
        }
    }
    @ViewChild("toDate", { static: false }) set toDateComponent(toDateComponent: DatePickerComponent) {

        if (toDateComponent) {
            toDateComponent.writeValue(this.currentValue["ToDate"]);
        }
    }

    @ViewChild("timeSpanValue", { static: false }) set timeSpanValueComponent(timeSpanValueComponent: InputComponent) {

        if (timeSpanValueComponent) {
            timeSpanValueComponent.writeValue(this.currentValue["TimeSpanValue"]);
        }
    }

    periodTypeSettings: ChoiceSettings;
    periodSettings: ChoiceSettings;
    fromDateSettings: SettingsBase;
    toDateSettings: SettingsBase;
    currentValue: DateTimeFilterValue;

    constructor() {
        super();
    }

    ngOnInit() {
        super.ngOnInit();
        this.currentValue = this.value ?? this.settings.defaultValue ?? new DateTimeFilterValue();

        this.periodTypeSettings = new ChoiceSettings("periodTypeSelector", false);
        this.periodTypeSettings.choices = [];
        this.periodTypeSettings.choices.push({Name: "Any time", Value: "anyTime"});
        this.periodTypeSettings.choices.push({Name: "Last...", Value: "last"});
        this.periodTypeSettings.choices.push({Name: "From - to", Value: "period"});
        this.periodTypeSettings.defaultValue = this.currentValue["PeriodType"];

        this.periodSettings = new ChoiceSettings("periodSelector", false);
        this.periodSettings.choices = [];
        this.periodSettings.choices.push({Name: "day(s)", Value: "days"});
        this.periodSettings.choices.push({Name: "week(s)", Value: "weeks"});
        this.periodSettings.choices.push({Name: "month(s)", Value: "months"});
        this.periodSettings.choices.push({Name: "year(s)", Value: "years"});
        this.periodSettings.defaultValue = this.currentValue["TimeSpanInterval"];

        this.fromDateSettings = new ChoiceSettings("fromDateSelector", false);
        this.fromDateSettings.defaultValue = this.currentValue["FromDate"];
        this.toDateSettings = new ChoiceSettings("toDateSelector", false);
        this.toDateSettings.defaultValue = this.currentValue["ToDate"];
    }

    onPeriodTypeSelectionChange(entry) {
        const value = this.currentValue;
        value["PeriodType"] = entry;

        this.writeValue(value);
    }

    onPeriodSelectionChange(entry) {
        const value = this.currentValue;
        value["TimeSpanInterval"] = entry;

        this.writeValue(value);
    }

    onInput(event: any) {
        const value = this.currentValue;
        value["TimeSpanValue"] = event.target.value;

        this.writeValue(value);
    }

    onDateValueChange(date: any, propertyName: string) {
        const value = this.currentValue;
        value[propertyName] = date;

        this.writeValue(value);
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }
}

export class DateTimeFilterValue {
    PeriodType: string = "anyTime";
    FromDate: Date;
    ToDate: Date;
    TimeSpanValue: number = 1;
    TimeSpanInterval: string = "weeks";
}

export const DATE_TIME_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: DateTimeSelectorComponent,
    readComponent: DateTimeSelectorComponent,
    settingsType: SettingsBase
};
