import { Component, Input, OnInit, EventEmitter, Output, HostBinding } from "@angular/core";
import { MIME_TYPES } from "../../../src/app/modules/libraries/services/media.helpers";
import { MediaBaseComponent } from "./../media-base.component";

const FLICKR_IMAGE_GALLERY_ITEM_CSS_CLASS: string = "sf-flickr-gallery__image";

@Component({
    templateUrl: "./image.component.html",
    selector: "sf-image"
})
export class ImageComponent extends MediaBaseComponent implements OnInit {
    @Input() type: string;
    @Input() showErrorMessage: boolean = true;
    @Input() processDimensions: boolean;
    @Input() isAbsoluteImage: boolean;
    @Input() look: string = FLICKR_IMAGE_GALLERY_ITEM_CSS_CLASS;
    @HostBinding("class.-wide") isWide: boolean = false;
    @HostBinding("class.sf-media__svg-wrapper")
    public get isAbsoluteSvg(): boolean {
        return this.isSvg && this.isAbsoluteImage;
    }
    @Output() loaded = new EventEmitter<Event>();
    @Output() error = new EventEmitter<string>();
    get isSvg() {
        return this.type === MIME_TYPES.SVG;
    }
    shouldBypassSecurity: boolean;

    ngOnInit() {
        super.ngOnInit();
        if (this.doesNotSupportPreview) {
            this.error.emit();
        } else {
            if (this.isSvg && !this.src.changingThisBreaksApplicationSecurity) {
                this.shouldBypassSecurity = true;
            }
            this.cssClass = this.generateCssClassList();
        }
    }

    onError() {
        super.onError();
        this.error.emit();
    }

    onImageLoad (event) {
        if (this.processDimensions) {
            if (event.target.naturalWidth > event.target.naturalHeight) {
                this.isWide = true;
            }
        }

        this.loaded.emit(event);
    }

    protected generateCssClassList() {
        let cls = "";
        if (this.look) {
            const look = this.look.split(" ");
            const index = look.indexOf(FLICKR_IMAGE_GALLERY_ITEM_CSS_CLASS);
            if (index > -1) {
                cls = look.splice(index, 1).toString();
            }
            if (look.length > 0) {
                cls += " -" + look.join(" -");
            }
        }

        return cls;
    }
}
