import { Injectable, Inject, Optional } from "@angular/core";
import { EntityData, DataItem, NavigateToEditArguments } from "../../../content/dynamic-modules/interfaces";
import { Observable, of } from "rxjs";
import { LoadItemsData, ItemWithOperationResult } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ActivatedRoute, Router } from "@angular/router";
import { ServiceInfo } from "../../../../../../fields/selector/selector.component";
import { StateWrapper, ItemsState } from "../../../content/dynamic-modules/services/dynamic-item-store-state";
import { DisabledFilterLoaders } from "../../../content/dynamic-modules/components/sidebar/list-item-filter-interfaces";
import { Operation, ModifyOperationsInfo } from "../../components/action-menu/operation.model";
import { SettingsSidebarSection } from "../../../content/dynamic-modules/components/sidebar/list-item-settings-sidebar.component";
import { GridNavigationProperties } from "../../../content/dynamic-modules/components/grid-navigation/grid-navigation-properties";
import { ComponentData, VirtualizationOptions } from "@progress/sitefinity-component-framework";
import { EditInDialogOperationResult } from "../../../content/dynamic-modules/services/operations/commands/edit-in-dialog-command";
import { ExecuteServerAction, ActionExecutorService } from "../action-executor.service";
import { QuickNavigationSidebarSection } from "../../../content/dynamic-modules/components/sidebar/quick-navigation-sidebar.component";
import { ColumnModel } from "../../models/column-model";
import { SidebarConfig } from "../../components/sidebar/sidebar.common";
import { GRID_EXTENDER_TOKEN, GridExtenderBase, GridLoadMoreContext, ExpandedNodeIdsGet, ExpandedNodeIdsSync, ExpandedNodeIdsSet, GridArgsBase, ItemPaging, CurrentPagingSet, TitleArgs, ItemsDataContext, GridActionContext, CommonActionContext, CustomSidebarContext, ReloadGridContext } from "./grid-extender-base";
import { BundleDataService } from "../../../../services/bundle-data.service";
import { SortersResult } from "../../../content/dynamic-modules/components/sidebar/sorter/SortingStore";
import { OperationsData } from "../../../content/dynamic-modules/services/operations/interfaces";

@Injectable()
export class CompositeGridExtender {

    constructor(@Optional() @Inject(GRID_EXTENDER_TOKEN) private gridExtenders: GridExtenderBase[]) { }

    initialize(router: Router, entityData: EntityData) {
        const extender = this.getExtender(entityData);
        return extender.initialize(router);
    }

    openEditItemInDialog(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        return extender.openEditItemInDialog(entityData);
    }

    getParentSetName(entityData: EntityData) {
        const extender = this.getExtender(entityData);
        return extender.getParentSetName(entityData);
    }

    reloadItems(queryParams: { [key: string]: string }, parentId: string, entityData: EntityData, sortParam: string, dataFieldNames: string[]): Observable<StateWrapper> {
        const extender = this.getExtender(entityData);
        return extender.reloadItems(queryParams, parentId, entityData, sortParam, dataFieldNames);
    }

    loadMore(ctx: GridLoadMoreContext): Observable<StateWrapper> {
        const extender = this.getExtender(ctx.entityData);
        return extender.loadMore(ctx);
    }

    shouldNavigateToChildGrid(dataItem: DataItem): boolean {
        const extender = this.getExtender(dataItem);
        return extender.shouldNavigateToChildGrid(dataItem);
    }

    getExpandedNodeIds(args: ExpandedNodeIdsGet): Observable<string[]> {
        const extender = this.getExtender(args.entityData);
        return extender.getExpandedNodeIds(args);
    }

    syncExpandedNodeIds(args: ExpandedNodeIdsSync) {
        const extender = this.getExtender(args.entityData);
        extender.syncExpandedNodeIds(args);
    }

    setExpandedNodeIds(args: ExpandedNodeIdsSet) {
        const extender = this.getExtender(args.entityData);
        extender.setExpandedNodeIds(args);
    }

    getCurrentPaging(args: GridArgsBase): ItemPaging {
        const extender = this.getExtender(args.entityData);
        return extender.getCurrentPaging(args);
    }

    setCurrentPaging(args: CurrentPagingSet) {
        const extender = this.getExtender(args.entityData);
        extender.setCurrentPaging(args);
    }

    getTitle(titleArgs: TitleArgs) {
        const extender = this.getExtender(titleArgs.entityData);
        return extender.getTitle(titleArgs);
    }

    isHierarchical(route: ActivatedRoute): boolean {
        const extender = this.getExtenderByRoute(route);
        return extender.isHierarchical(route);
    }

    getVirtualizationOptions(route: ActivatedRoute): VirtualizationOptions {
        const extender = this.getExtenderByRoute(route);
        return extender.getVirtualizationOptions(route);
    }

    getTotalItemsCountWithChildren(currentStateTotalCount: number, route: ActivatedRoute): Observable<number> {
        const extender = this.getExtenderByRoute(route);
        return extender.getTotalItemsCountWithChildren(currentStateTotalCount, route);
    }

    showFilters(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        return extender.showFilters(entityData);
    }

    disableSelectAll(route: ActivatedRoute, entityData: EntityData): boolean {
        const extender = this.getExtenderByRoute(route);
        return extender.disableSelectAll(route, entityData);
    }

    getChildren(entityData: EntityData, parentId: string, serviceInfo: ServiceInfo, columns: ColumnModel[] = []) {
        const extender = this.getExtender(entityData);
        return extender.getChildren(entityData, parentId, serviceInfo, columns);
    }

    getItemsData(route: ActivatedRoute, dataFieldNames: string[], args?: ItemsDataContext): LoadItemsData {
        const extender = this.getExtenderByRoute(route);
        return extender.getItemsData(route, dataFieldNames, args);
    }

    tryHandleAction(context: GridActionContext): Observable<boolean> {
        const extender = this.getExtender(context.item);

        if (!extender) {
            return of(false);
        }

        return extender.tryHandleAction(context);
    }

    showSorters(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        return extender.showSorters(entityData);
    }

    getSorters(entityData: EntityData): Observable<SortersResult> {
        const extender = this.getExtender(entityData);
        return extender.getSorters(entityData);
    }

    getSingleItemName(titleArgs: TitleArgs): Observable<{primary: string, secondary: string}> {
        const extender = this.getExtender(titleArgs.entityData);
        return extender.getSingleItemName(titleArgs);
    }

    getPluralItemName(titleArgs: TitleArgs): Observable<{primary: string, secondary: string}> {
        const extender = this.getExtender(titleArgs.entityData);
        return extender.getPluralItemName(titleArgs);
    }

    getEmptyScreenIcon(entityData: EntityData): string {
        const extender = this.getExtender(entityData);
        const itemType = entityData.metadata.setName;
        return extender.getEmptyScreenIcon(itemType);
    }

    getDefaultSort(entityData: EntityData): string {
        const extender = this.getExtender(entityData);
        return extender.getDefaultSort(entityData);
    }

    getDisabledFilterLoaders(route: ActivatedRoute): DisabledFilterLoaders {
        const extender = this.getExtenderByRoute(route);
        return extender.getDisabledFilterLoaders(route);
    }

    executeNavigateCommand(router: Router, route: ActivatedRoute, dataItem: DataItem, entityData: EntityData, childSetName: string = null): Observable<any> {
        const extender = this.getExtender(entityData);
        return extender.executeNavigateCommand(router, route, dataItem, entityData, childSetName);
    }

    modifyActionContext(actionContext: CommonActionContext, routeEntityData: EntityData): Observable<CommonActionContext> {
        const extender = this.getExtender(actionContext.item);
        return extender.modifyActionContext(actionContext, routeEntityData);
    }

    modifyEntityDataForBulkOperations(entityData: EntityData, presenterTemplate: string): EntityData {
        const extender = this.getExtender(entityData);
        return extender.modifyEntityDataForBulkOperations(entityData, presenterTemplate);
    }

    getSettingsSidebarSections(operations: Observable<Operation[]>, entityData: EntityData): Observable<SettingsSidebarSection[]> {
        const extender = this.getExtender(entityData);
        return extender.getSettingsSidebarSections(operations, entityData);
    }

    getSidebarOperations(entityData: EntityData, data: OperationsData): Observable<Operation[]> {
        const extender = this.getExtender(entityData);
        return extender.getSidebarOperations(entityData, data);
    }

    getListMainOperations(entityData: EntityData, parent: DataItem, isHierarchicalView: boolean): Observable<Operation[]> {
        const extender = this.getExtender(entityData);
        return extender.getListMainOperations(entityData, parent, isHierarchicalView);
    }

    getBulkOperations(entityData: EntityData, modifiedEntityData: EntityData, parent: DataItem): Observable<Operation[]> {
        const extender = this.getExtender(entityData);
        return extender.getBulkOperations(entityData, modifiedEntityData, parent);
    }

    getListItemOperations(entityData: DataItem, parent: DataItem): Observable<Operation[]> {
        const extender = this.getExtender(entityData);
        return extender.getListItemOperations(entityData, parent);
    }

    getCustomSidebars(ctx: CustomSidebarContext): Observable<SidebarConfig[]> {
        const extender = this.getExtender(ctx.entityData);
        return extender.getCustomSidebars(ctx);
    }

    getSidebarsExternalKeys(entityData: EntityData): string[] {
        const extender = this.getExtender(entityData);
        return extender.getSidebarsExternalKeys(entityData);
    }

    getFilterSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        const extender = this.getExtender(entityData);
        return extender.getFilterSidebarTitle(entityData, parentItem);
    }

    getSortDropdownTitle(entityData: EntityData, displayName: string): string {
        const extender = this.getExtender(entityData);
        return extender.getSortDropdownTitle(entityData, displayName);
    }

    getSettingsSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        const extender = this.getExtender(entityData);
        return extender.getSettingsSidebarTitle(entityData, parentItem);
    }

    getQuickNavigationSidebarSections(entityData: EntityData, parentItem: DataItem): Observable<QuickNavigationSidebarSection[]> {
        const extender = this.getExtender(entityData);
        return extender.getQuickNavigationSidebarSections(entityData, parentItem);
    }

    getQuickNavigationSidebarTitle(entityData: EntityData, parentItem: DataItem): string {
        const extender = this.getExtender(entityData);
        return extender.getQuickNavigationSidebarTitle(entityData, parentItem);
    }

    getSidebarDisplayName(entityData: EntityData, parentItem: DataItem): string {
        const extender = this.getExtender(entityData);
        return extender.getSidebarDisplayName(entityData, parentItem);
    }

    getNavigationComponentData(entityData: EntityData, gridNavProps: GridNavigationProperties): ComponentData {
        const extender = this.getExtender(entityData);
        return extender.getNavigationComponentData(entityData, gridNavProps);
    }

    shouldReloadItemsAfterEdit(args: NavigateToEditArguments, operationResult: EditInDialogOperationResult): ReloadGridContext {
        const extender = this.getExtender(args.dataItem);
        return extender.shouldReloadItemsAfterEdit(args, operationResult);
    }

    shouldReloadItemsOnViewModeChanged(oldPresenterTemplate: string, entityData: EntityData) {
        const extender = this.getExtender(entityData);
        return extender.shouldReloadItemsOnViewModeChanged(oldPresenterTemplate, entityData);
    }

    getPresenterTemplate(entityData: EntityData): any {
        const extender = this.getExtender(entityData);
        return extender.getPresenterTemplate(entityData);
    }

    hideLoadMore(route: ActivatedRoute, entityData: EntityData): boolean {
        const extender = this.getExtenderByRoute(route);
        return extender.hideLoadMore(route, entityData);
    }

    processEntityData(entityData: EntityData): EntityData {
        const extender = this.getExtender(entityData);
        return extender.processEntityData(entityData);
    }

    executeServerAction(executorService: ActionExecutorService, context: ExecuteServerAction): Observable<ItemWithOperationResult> {
        const extender = this.getExtenderByRoute(context.route);
        return extender.executeServerAction(executorService, context);
    }

    getEmptyScreenText(entityData: EntityData, pluralName$: Observable<{primary: string, secondary: string}>): Observable<string> {
        const extender = this.getExtender(entityData);
        return extender.getEmptyScreenText(entityData, pluralName$);
    }

    hasLongRunningTasks(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        return extender.hasLongRunningTasks(entityData);
    }

    modifySingleItemOperations(entityData: EntityData, operations: Operation[], modifyOperationsInfo: ModifyOperationsInfo): Operation[] {
        const extender = this.getExtender(entityData);
        return extender.modifySingleItemOperations(entityData, operations, modifyOperationsInfo);
    }

    modifyOperations(entityData: EntityData, operations: Operation[], modifyOperationsInfo: ModifyOperationsInfo): Operation[] {
        const extender = this.getExtender(entityData);
        return extender.modifyOperations(entityData, operations, modifyOperationsInfo);
    }

    getNotificationServiceFilter(entityData: EntityData) {
        const extender = this.getExtender(entityData);
        return extender.getNotificationServiceFilter(entityData);
    }

    getTakeItemsCount(route: ActivatedRoute) {
        const extender = this.getExtenderByRoute(route);
        const entityData = this.getEntityDataByRoute(route);
        return extender.getTakeItemsCount(entityData);
    }

    getDataFieldNames(columns: ColumnModel[], entityData: EntityData): string[] {
        const extender = this.getExtender(entityData);
        return extender.getDataFieldNames(columns, entityData);
    }

    getAsyncColumnsValues(columns: ColumnModel[], entityData: EntityData, itemsState: ItemsState, siteId: string, bundleDataService: BundleDataService) {
        const extender = this.getExtender(entityData);
        return extender.getAsyncColumnsValues(columns, entityData, itemsState, siteId, bundleDataService);
    }

    hideSidebarLanguagesDropdown(entityData: EntityData): boolean {
        const extender = this.getExtender(entityData);
        return extender.hideSidebarLanguagesDropdown(entityData);
    }

    modifyColumns(columns: ColumnModel[], entityData: EntityData): ColumnModel[] {
        const extender = this.getExtender(entityData);
        return extender.modifyColumns(columns);
    }

    private getExtenderByRoute(route: ActivatedRoute) {
        const entityData = this.getEntityDataByRoute(route);
        const extender = this.getExtender(entityData);
        return extender;
    }

    private getEntityDataByRoute(route: ActivatedRoute) {
        const entityData = route.snapshot.data["dynamicItems"];
        return entityData;
    }

    private getExtender(entityData: EntityData): GridExtenderBase {
        const extender = this.gridExtenders.find(x => entityData && x.isSupportedType(entityData));
        return extender;
    }
}
