import { Injectable, InjectionToken, NgZone } from "@angular/core";
import { Observable, Subject } from "rxjs";
import { stringConstants } from "../../../common-constants";
import { EntityData } from "../../content/dynamic-modules/interfaces";

export const DAM_PROVIDER_TOKEN = new InjectionToken("dam-provider");
export const FAILED_TO_INSERT_MEDIA_ASSET = "Failed to insert media asset.";

/**
 * The base class that all custom DAM providers must implement.
 * @ExposedInApi {DamProviderBase} DamProviderBase v1/dam/dam-provider-base.d.ts
 */
@Injectable()
export abstract class DamProviderBase {
    constructor(protected zone: NgZone) {
        this.priority = 1;
    }

    onMediaSelected = new Subject<void>();
    onError = new Subject<string>();
    onDone = new Subject<DamAsset[]>();
    onCancel = new Subject<void>();
    settings: DamProviderSettings = null;
    priority: number;

    abstract loadMediaSelector(damWrapper: HTMLElement, mediaEntityData: EntityData, allowMultiSelect: boolean): void;

    abstract isSupported(providerTypeName: string): boolean;

    protected getPropertyValue(name: string): string {
        if (this.settings) {
            for (const key in this.settings.Properties) {
                if (this.settings.Properties[key].Name === name) {
                    return this.settings.Properties[key].Value;
                }
            }
        }

        return null;
    }

    protected loadDynamicScript(url: string): Observable<void> {
        return new Observable(observer => {
            if (url && !document.getElementById(url)) {
                const script = document.createElement("script");
                script.src = url;
                script.innerHTML = stringConstants.EMPTY_STRING;
                script.type = "text/javascript";
                script.id = url;
                script.async = true;
                script.defer = true;
                document.body.appendChild(script);

                script.onload = () => {
                    observer.next();
                    observer.complete();
                };
                script.onerror = () => {
                    observer.error();
                };
            } else {
                observer.next();
                observer.complete();
            }
        });
    }

    protected mediaSelected(): void {
        this.onMediaSelected.next();
    }

    protected error(error: string): void {
        this.zone.run(() => {
            this.onError.next(error);
        });
    }

    protected assetsSelected(assets: DamAsset[]): void {
        this.zone.run(() => {
            this.onDone.next(assets);
        });
    }

    protected cancel(): void {
        this.zone.run(() => {
            this.onCancel.next();
        });
    }
}

export interface DamProviderSettings {
    ProviderTypeName: string
    Properties: [ { Name: string, Value: string } ];
}

/**
 * An interface to represent data for a DAM asset.
 * @ExposedInApi {DamAsset} DamAsset v1/dam/dam-asset.d.ts
 */
export interface DamAsset {
    title: string;
    mimeType: string;
    extension: string;
    width: number;
    height: number;
    size: number;
    url: string;
}
