import { Component, OnInit } from "@angular/core";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { cloneObject } from "../../../../../utils";
import { RESOLVE_NAMES } from "../../../../content/constants";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { MetadataContainer } from "../../../../shared/services/metadata/meta-data.store";
import { TaxonomySettings } from "../../../../taxonomy";
import { TaxaComponent } from "../../../../taxonomy/taxa/taxa.component";

export const FIELD_SELECTOR_SINGULAR_NAME = "field-selector";

@Component({
    selector: "sf-field-selector",
    templateUrl: "../../../../taxonomy/taxa/taxa.component.html"
})
export class FieldSelectorComponent extends TaxaComponent implements OnInit {
    private entitySetName: string = stringConstants.EMPTY_STRING;

    public ngOnInit() {
        this.settings.allowCreate = false;
        this.settings.allowMultiple = true;

        const container = this.route.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const entity = container.entities[this.entitySetName || ENTITY_SET.FLAT_TAXA];

        const cloneEntity = cloneObject(entity);
        cloneEntity.singularName = FIELD_SELECTOR_SINGULAR_NAME;

        this.defaultFieldName = "Title";
        this.dropdownChipsTreeConfig.treeProperties = {
            displayField: "Title"
        }

        this.entityData = {
            metadata: cloneEntity,
            culture: null,
            provider: null
        };

        super.ngOnInit();
    }

    setEntitySetName(newEntitySetName: string) {
        this.entitySetName = newEntitySetName;
    }

    setHidden(hidden: boolean) {
        super.setHidden(hidden);
    }

    protected getTaxaName() {
        this.taxaNames = {
            plural: "fields",
            singular: "field"
        };

        this.addButtonTitle = "Add";
    }
}

export const FIELD_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: FieldSelectorComponent,
    readComponent: FieldSelectorComponent,
    settingsType: TaxonomySettings
};
