/**
 * Creates a filed model with initialized settings.
 * Uses FieldsProvider to retrieve a registration
 * for given field.
 *
 * @export
 * @param {CompositeFieldsProvider} fieldsProvider Provides read/write components and settings.
 * @param {string} typeName The name of the type. Examples: "News", "Blogs" etc.
 * @param {string} key The selector of the field: Example: "sf-long-text".
 * @param {string} propName The name of the field: Example: "Description"
 * @param {*} value The initial value of the field.
 * @param {Entity} entity Provides properties and other metadata for the different fields.
 * @returns {FieldModel} The constructed field model.
 */
export function createFieldModel(fieldsProvider: CompositeFieldsProvider, typeName: string, key: string, propName: string, value: any, propertyMetadata: any, propTitle?: string, friendlyTitle?: string, readOnly: boolean = false, cssClass?: string): FieldModel {

    // for backward compatibility with existing calls
    if (propertyMetadata && propertyMetadata.hasOwnProperty("properties")) {
        propertyMetadata = propertyMetadata.properties[propName];
    }

    const registration = fieldsProvider.getFieldRegistration({ fieldType: key, fieldName: propName, typeName }, propertyMetadata);
    if (!registration) {
        return null;
    }

    const settings: SettingsBase = new registration.settingsType(propName, readOnly);
    settings.title = propTitle || propName;
    if (propertyMetadata) {
        settings.init(propertyMetadata);
    }

    settings.friendlyTitle = friendlyTitle;

    return new FieldModel({
        selector: key,
        key: propName,
        value: value,
        settings: settings,
        registration,
        cssClass
    });
}
