import { ShortTextSettings } from "../../../../fields/short-text/short-text-settings";

const FIELD_VALIDATION = "Telerik.Sitefinity.V1.Validation";
export const FIELD_SANITIZE_REGEX = FIELD_VALIDATION + ".SanitizeRegex";
export const FIELD_SANITIZE_REGEX_REPLACECHARACTER = FIELD_VALIDATION + ".RegularExpressionReplaceCharacter";

export class UrlNameSettings extends ShortTextSettings {
    public sanitizeRegex: string;
    public sanitizeRegexReplaceCharacter: string;

    public init(metadata: any): void {
        super.init(metadata);
        this.sanitizeRegex = metadata[FIELD_SANITIZE_REGEX];
        this.sanitizeRegexReplaceCharacter = metadata[FIELD_SANITIZE_REGEX_REPLACECHARACTER] || "-";
        this.title = "URL Name";
        this.changeOnFocus = true;
    }
}
