import { createSelector, select } from "@ngrx/store";
import { pipe } from "rxjs";
import { map } from "rxjs/operators";
import { UploadInfo } from "../../../modules/libraries/services/media.service";
import { cloneObject } from "../../../utils";
import { AppState } from "../store-schema";

export const MEDIA_SELECTORS = {
    foldersData: select(createSelector((state: AppState) => state.media, state => state.foldersData)),
    filesData: select(createSelector((state: AppState) => state.media, state => state.filesData)),
    uploadsData: pipe(select(createSelector((state: AppState) => state.media, state => state.uploadsData)),
    map(uploadInfo => {
        if (uploadInfo) {
            const uploadInfoClone: UploadInfo = cloneObject(uploadInfo);
            for (let i = 0; i < uploadInfo.items.length; i++) {
                uploadInfoClone.items[i].upload = Object.assign({}, uploadInfo.items[i].upload);
            }

            if (uploadInfo.updatedItem) {
                uploadInfoClone.updatedItem.content = uploadInfo.updatedItem.content;
            }

            return uploadInfoClone;
        }

        return uploadInfo;
    }))
};