import { ClassProvider, Injectable, NgZone } from "@angular/core";
import { EntityData } from "../../../api";
import { stringConstants } from "../../../common-constants";
import { getExtensionFromFileName, getFileNameWithoutExtension } from "../../../utils";
import { MediaEntity, MetadataStore } from "../../shared/services/metadata/meta-data.store";
import { DamAsset, DamProviderBase, DAM_PROVIDER_TOKEN, FAILED_TO_INSERT_MEDIA_ASSET } from "./dam-provider-base";

declare const cloudinary: any;

const CLOUDINARY_MEDIA_CANNOT_BE_LOADED = "Cloudinary media selector cannot be loaded. Contact your administrator.";
const CLOUDINARY_PROVIDER_TYPE_NAME = "CloudinaryBlobStorageProvider";
export const CLOUDINARY_PROVIDER_LOGIN_FAILED_MESSAGE = "Log out from Cloudinary and try to log in with another account.";
export const CLOUDINARY_PROVIDER_AUTHENTICATION_ERROR_GROUP = "authentication_failed";
export const CLOUDINARY_ID_QUERY_PARAM = "sf_cl_id";
export const CLOUDINARY_VERSION_QUERY_PARAM = "sf_cl_version";

@Injectable()
export class CloudinaryDamProvider extends DamProviderBase {
    constructor(protected zone: NgZone, private store: MetadataStore) {
        super(zone);
        this.priority = 0;
    }

    isSupported(providerTypeName: string): boolean {
        return providerTypeName === CLOUDINARY_PROVIDER_TYPE_NAME;
    }

    loadMediaSelector(damWrapper: HTMLElement, mediaEntityData: EntityData, allowMultiSelect: boolean): void {
        if (!this.areSettingsPropertiesValid()) {
            this.error(CLOUDINARY_MEDIA_CANNOT_BE_LOADED);
            return;
        }

        this.loadDynamicScript(this.getPropertyValue("ScriptUrl")).subscribe(() => {
            if (typeof cloudinary === "undefined") {
                this.error(CLOUDINARY_MEDIA_CANNOT_BE_LOADED);
                return;
            }

            let config = {
                cloud_name: this.getPropertyValue("CloudName"),
                api_key: this.getPropertyValue("ApiKey"),
                multiple: allowMultiSelect,
                inline_container: `.${damWrapper.className.replace(/\s/g, ".")}`,
                remove_header: true,
                integration: {
                    type: "progress_sitefinity_connector",
                    platform: `Sitefinity ${this.store.getValue().sitefinityVersion}`,
                    version: "1.0",
                    environment: null
                }
            };
            const mediaEntity = mediaEntityData.metadata as MediaEntity;
            if (mediaEntity.acceptableFileTypes && mediaEntity.acceptableFileTypes.length) {
                config = Object.assign(config, {
                    search: {
                        expression: mediaEntity.acceptableFileTypes.map(x => `format=${x}`).join(" OR ")
                    }
                });
            }

            const handlers = {
                insertHandler: this.insertHandler.bind(this),
                errorHandler: this.errorHandler.bind(this),
                hideHandler: this.hideHandler.bind(this)
            };

            try {
                const mediaLibrary = cloudinary.createMediaLibrary(config, handlers);
                mediaLibrary.show(config);
            } catch (error) {
                this.error(error);
            }
        }, () => {
            this.error(CLOUDINARY_MEDIA_CANNOT_BE_LOADED);
        });
    }

    private insertHandler(data): void {
        this.mediaSelected();
        const damAssets: DamAsset[] = [];
        if (data.assets) {
            data.assets.forEach((asset: CloudinaryAsset) => {
                const damAsset: DamAsset = this.getDamAsset(asset);

                damAssets.push(damAsset);
            });

            this.assetsSelected(damAssets);
        } else {
            this.error(FAILED_TO_INSERT_MEDIA_ASSET);
        }
    }

    private errorHandler(error: any): void {
        if (error && error.error_message && error.error_group !== CLOUDINARY_PROVIDER_AUTHENTICATION_ERROR_GROUP) {
            this.error(error.error_message);
        } else {
            this.error(`${error.error_message}${stringConstants.INTERVAL}${CLOUDINARY_PROVIDER_LOGIN_FAILED_MESSAGE}`);
        }
    }

    private hideHandler(): void {
        this.cancel();
    }

    private areSettingsPropertiesValid(): boolean {
        if (!this.settings) {
            return false;
        }

        const cloudName = this.getPropertyValue("CloudName");
        if (!cloudName) {
            return false;
        }

        const scriptUrl = this.getPropertyValue("ScriptUrl");
        if (!scriptUrl) {
            return false;
        }

        const apiKey = this.getPropertyValue("ApiKey");
        if (!apiKey) {
            return false;
        }

        return true;
    }

    private getDamAsset(asset: CloudinaryAsset): DamAsset {
        const slashIndex = asset.public_id.lastIndexOf("/");
        let title = asset.public_id.substring(slashIndex + 1);
        asset.format = asset.format || getExtensionFromFileName(title);
        title = getFileNameWithoutExtension(title);

        let url: string = asset.secure_url;
        if (asset.derived && asset.derived.length) {
            url = asset.derived[0].secure_url;
            asset.format = getExtensionFromFileName(url) || asset.format;
        }

        const appendSymbol = url.indexOf("?") === -1 ? "?" : "&";
        url += `${appendSymbol}${CLOUDINARY_ID_QUERY_PARAM}=${asset.public_id}&${CLOUDINARY_VERSION_QUERY_PARAM}=${asset.version}`;

        const damAsset: DamAsset = {
            title: title,
            mimeType: null,
            extension: `${stringConstants.DOT}${asset.format}`,
            width: Math.floor(asset.width) || null,
            height: Math.floor(asset.height) || null,
            size: Math.floor(asset.bytes),
            url: url
        };

        return damAsset;
    }
}

export const CLOUDINARY_DAM_PROVIDER: ClassProvider = {
    multi: true,
    provide: DAM_PROVIDER_TOKEN,
    useClass: CloudinaryDamProvider
};

export interface CloudinaryAsset {
    public_id: string;
    format: string;
    secure_url: string;
    derived: CloudinaryTransformation[];
    width: number;
    height: number;
    bytes: number;
    version: any;
}

export interface CloudinaryTransformation {
    secure_url: string;
}
