import { RegexHelper } from "../../src/app/utils";

export function convertIsoStringToUTCDate(value: string): Date {
    const date = new Date(value);
    date.setMinutes(date.getMinutes() + date.getTimezoneOffset());

    return date;
}

export function getDateWithTimeZoneOffset(value: Date, timeZoneOffset: number = null): Date {
    const date = new Date(value);

    if (timeZoneOffset !== null) {
        date.setMinutes(date.getMinutes() - timeZoneOffset);
    }

    return date;
}

export function isCurrency(unit: string): boolean {
    const pattern = RegexHelper.buildRegex("^[A-Z]{3}$", "g");
    if (unit && pattern.test(unit)) {
        return true;
    }

    return false;
}

export function textEndsWithNumber(text: string): boolean {
    const pattern = RegexHelper.buildRegex("\\d", "g");
    if (text) {
        const lastSymbol = text[text.length - 1];
        if (pattern.test(lastSymbol)) {
            return true;
        }
    }

    return false;
}
