import { Injectable, ClassProvider } from "@angular/core";
import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "./operations-filter";
import { Operation, OPERATION_NAMES, OPERATION_TITLES } from "../../../../shared/components/action-menu/operation.model";
import { OperationsData, OperationsTarget } from "./interfaces";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";

@Injectable()
export class ContentItemOperationsFilter implements OperationsFilter {
    private allowedBulkOperations: string[] = [
        OPERATION_NAMES.assignTaxons,
        OPERATION_NAMES.sendForTranslation,
        OPERATION_NAMES.siteSync,
        OPERATION_NAMES.delete
    ];

    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (data.dataItem.metadata.setName === ENTITY_SET.CONTENT_ITEMS) {
            operations = this.filterForList(operations, data);
            operations = this.filterForCreate(operations, data);
            operations = this.filterForBulk(operations, data);
        }

        return operations;
    }

    private filterForCreate(operations: Operation[], data: OperationsData): Operation[] {
        if (data.target === OperationsTarget.Create) {
            operations = operations.filter(x => x.Name !== OPERATION_NAMES.create);

            const publishOperation = operations.find(x => x.Name === OPERATION_NAMES.publish);
            if (publishOperation) {
                publishOperation.Title = OPERATION_TITLES.create;
            }
        }

        return operations;
    }

    private filterForList(operations: Operation[], data: OperationsData): Operation[] {
        if (data.target === OperationsTarget.List) {
            operations = operations.filter(x => x.Name !== OPERATION_NAMES.publish);
        }

        return operations;
    }

    private filterForBulk(operations: Operation[], data: OperationsData): Operation[] {
        if (data.target === OperationsTarget.Bulk) {
            operations = operations.filter(x => this.allowedBulkOperations.indexOf(x.Name) > -1);
        }

        return operations;
    }
}

export const CONTENT_ITEM_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: ContentItemOperationsFilter
};
