import { Injectable, ClassProvider } from "@angular/core";
import { combineLatest, Observable, of, ReplaySubject } from "rxjs";
import { HierarchicalService, RESULT_COUNT, HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { createQuery } from "../../../services/query";
import { LoadItemsResponse, LoadItemsData, DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { TaxonomySettings } from "../../taxonomy/taxonomy.settings";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { stringConstants } from "../../../common-constants";
import { first } from "rxjs/operators";
import { cloneObject, hasValue } from "../../../utils";
import { Properties } from "../../shared/fields.constants";
import { MediaHelpers } from "./media.helpers";
import { LongRunningTasksService } from "../../content/dynamic-modules/services/long-running-tasks.service";
import { BackgroundTask, BackgroundTaskType } from "../../content/dynamic-modules/services/background-task.types";
import { CompositeDataExtender } from "../../shared/services/data-extensions/data.extender";
import { MetadataStore } from "../../shared/services/metadata/meta-data.store";

const DEFAULT_TAKE = 50;

@Injectable()
export class HierarchicalLibrariesService extends HierarchicalService {
    constructor(
        protected dynamicItemService: DynamicItemService,
        private longRunningTasksService: LongRunningTasksService,
        private compositeDataExtender: CompositeDataExtender,
        private metadataStore: MetadataStore
    ) {
        super(dynamicItemService);
    }

    showStatusIcons(): boolean {
        return false;
    }

    isHierarchical(type: string): boolean {
        return true;
    }

    getSetName(): string {
        return ENTITY_SET.ALBUMS;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return MediaHelpers.isLibrary(entityData.metadata.setName) || MediaHelpers.isMediaEntity(entityData);
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return of<LoadItemsResponse>({
            entityData: entityData,
            totalCount: 0,
            dataItems: []
        });
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string, isCreate: boolean): Observable<LoadItemsResponse> {
        let parentId = null;

        if (value) {
            parentId = value[0] === stringConstants.DEFAULT_GUID ? null : value[0];
        }

        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `Default.FoldersRecursiveSearch(parentId=${parentId})?filterByCreateChildPermissions=${isCreate || false}&recursive=${false}&includeParent=${true}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                take: 1,
                siteId: this.siteId
            });
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[], editItemId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const excludedRootId = this.getExcludedRootId(targetDataItem);
        const items$ = this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `Default.FoldersRecursiveSearch(parentId=${null})?filterByCreateChildPermissions=true&recursive=${true}&excludedRootId=${excludedRootId}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                take: RESULT_COUNT,
                siteId: this.siteId
            });

        return this.combineItemsAndLongRunningTasks(items$, entityData);
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string, taxonId?: string): Observable<LoadItemsResponse> {
        const parentId = info.parentId || null;
        const excludedRootId = this.getExcludedRootId(info.targetDataItem);
        const items$ = this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `Default.FoldersRecursiveSearch(parentId=${parentId})?recursive=${false}&excludedRootId=${excludedRootId}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                siteId: this.siteId,
                skip: info.skip,
                take: DEFAULT_TAKE
            });

        return this.combineItemsAndLongRunningTasks(items$, entityData);
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings, taxonId?: string, isCreate?: boolean): Observable<LoadItemsResponse> {
        let query = createQuery();
        const excludedRootId = isCreate ? stringConstants.EMPTY_STRING : settings?.id || stringConstants.EMPTY_STRING;

        if (info.searchText) {
            query = query.search(info.searchText);
        }

        const items$ = this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `Default.FoldersRecursiveSearch(parentId=${null})?filterByCreateChildPermissions=true&recursive=${false}&excludedRootId=${excludedRootId}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                siteId: this.siteId,
                query,
                skip: info.skip,
                take: DEFAULT_TAKE
            });

        return this.combineItemsAndLongRunningTasks(items$, entityData);
    }

    getModalItems(entityData: EntityData, taxaId: string, taxonId?: string, targetDataItem?: DataItem): Observable<LoadItemsResponse> {
        const items$ = this.dynamicItemService
            .getItemList({
                entityData: entityData,
                action: `Default.FoldersRecursiveSearch(parentId=${null})?filterByCreateChildPermissions=true&recursive=${false}&excludedRootId=${this.getExcludedRootId(targetDataItem)}`,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                siteId: this.siteId
            });

        return this.combineItemsAndLongRunningTasks(items$, entityData);
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData): Observable<LoadItemsResponse> {
        let query = createQuery();

        if (info.searchText) {
            query = query.search(info.searchText);
        }

        let filterByCreateChildPermissions = true;

        if (loadingData.payload?.skipFilterByCreateChildPermissions) {
            filterByCreateChildPermissions = false;
        }

        const parentId = info.parentId || null;
        const excludedRootId = info.taxaId || stringConstants.EMPTY_STRING;
        let action = `Default.FoldersRecursiveSearch(parentId=${parentId})?filterByCreateChildPermissions=${filterByCreateChildPermissions}&recursive=${false}&includeParent=${!!info.includeParent}`;
        if (excludedRootId) {
            action = `${action}&excludedRootId=${excludedRootId}`;
        }

        const listData: LoadItemsData = {
            entityData: loadingData.entityData,
            action,
            fallbackProperties: [loadingData.entityData.metadata.defaultFieldName],
            take: loadingData.take,
            siteId: this.siteId,
            query
        };

        if (hasValue(loadingData.skip)) {
            listData.skip = loadingData.skip;
        }

        if (loadingData.order) {
            listData.order = loadingData.order;
        }

        const items$ = this.dynamicItemService.getItemList(listData);

        return this.combineItemsAndLongRunningTasks(items$, loadingData.entityData);
    }

    private combineItemsAndLongRunningTasks(items$: Observable<LoadItemsResponse>, entityData: EntityData): Observable<LoadItemsResponse> {
        const result$ = new ReplaySubject<LoadItemsResponse>();

        const tasks$ = this.getLongRunningTasks(entityData);

        combineLatest([tasks$, items$]).pipe(first()).subscribe(([tasks, result]) => {
            result$.next({ dataItems: this.mapDataItemsAndBackgroundTasks(tasks, result.dataItems, entityData), totalCount: result.totalCount, entityData });
        });

        return result$;
    }

    private getChildEntityData(currentEntityData: EntityData): EntityData {
        const metadataStore = this.metadataStore.getValue();
        const childEntitySetName = MediaHelpers.getChildSetName(currentEntityData);
        const metadata = metadataStore.entities[childEntitySetName];

        const childEntityData = {
            provider: currentEntityData.provider,
            metadata,
            culture: currentEntityData.culture
        };

        return childEntityData;
    }

    private getExcludedRootId(targetDataItem: DataItem) {
        let excludedRootId = stringConstants.EMPTY_STRING;
        const shouldExclude = targetDataItem && MediaHelpers.isLibrary(targetDataItem.metadata.setName) && !targetDataItem.isEmpty;

        if (shouldExclude) {
            excludedRootId = targetDataItem.data[Properties.ID];
        }

        return excludedRootId;
    }

    private getLongRunningTasks(currentEntityData: EntityData) {
        const childEntityData = this.getChildEntityData(currentEntityData);
        return this.longRunningTasksService.getTasks(childEntityData);
    }

    private mapDataItemsAndBackgroundTasks(tasks: BackgroundTask[], dataItems: DataItem[], entityData: EntityData): DataItem[] {
        const mappedItems = this.compositeDataExtender.enhanceDataItems(entityData, dataItems, {
            inactive: true,
            tooltip: msg => msg,
            isSelectionDisabled: true
        }, { tasks, whiteListedTasks: [BackgroundTaskType.RegenerateThumbnails] })
            .map(item => {
                const clone = cloneObject(item.data);
                clone.hasChildren = item.data.FoldersCount > 0;
                return DataItem.fromEntityData(clone, entityData);
            });

        return mappedItems;
    }
}

export const HIERARCHICAL_LIBRARIES_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalLibrariesService
};
