import { ActivatedRoute, Router } from "@angular/router";
import { Observable, of } from "rxjs";
import { ChipsConfig } from "../../../../../../fields/common/chips/chips.component";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { DynamicItemService, LoadItem, LoadItemsData, LoadItemsResponse } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { PropertyData, SectionData } from "../../../widget-editor/interfaces/widget-editor";
import { ActionButton } from "../../components/action-menu/action-menu-model";
import { Operation } from "../../components/action-menu/operation.model";
import { ColumnModel } from "../../models/column-model";

export abstract class ListIndexContract {
    constructor(protected entityData: EntityData, protected dynamicItemService: DynamicItemService, protected router: Router) { }

    abstract getListIndexModel(getListIndexModelArgs: GetListIndexModelArgs): ListIndexModel;

    abstract getListDetailsModel(getListDetailsModelArgs: GetListDetailsModelArgs): ListDetailsModel;

    getListItems(getListItemsArgs: GetListItemsArgs): Observable<LoadItemsResponse> {
        return this.dynamicItemService.getItemList(getListItemsArgs.loadData);
    }

    getItem(loadItem: LoadItem): Observable<DataItem> {
        return this.dynamicItemService.getItem(loadItem);
    }

    setPropertyValues(dataItem: DataItem, properties: PropertyData[]): Observable<DataItem> {
        const editedFields = {};
        properties.forEach(property => {
            editedFields[property.Name] = property.Value;
        });

        return this.dynamicItemService.upsert({
            data: editedFields,
            dataItem: dataItem
        });
    }

    tryExecuteOperation(dataItem: DataItem, button: ActionButton, activatedRoute?: ActivatedRoute): Observable<ListIndexOperationResult> {
        return of({
            isExecuted: false,
            requiresReload: false
        });
    }
}

export interface ListIndexModel {
    title: string;
    emptyListMessage: string;
    columns: ColumnModel[];
    operations: Observable<Array<Operation>>;
    pageSize?: number;
    singularName: string;
    pluralName: string;
    emptyScreenIcon?: string;
    titleCss?: string;
    navigationVisible?: boolean;
    isLoadMoreSearchEnabled?: boolean;
    isLoadMoreFilterEnabled?: boolean;
    navigationTitle?: string;
    navigationButtonTitle?: string;
    navigationBackUrl?: string;
    filterArgs?: ListIndexFilterArgs;
    notificationFilter: string;
    searchArgs?: ListIndexSearchArgs;
    order?: string;
    dataFieldNames?: string[];
    isSiteSpecific?: boolean;
    hasLongRunningTasks?: boolean;
}

export interface GetListIndexModelArgs {
    typeFullName: string;
    dataItem?: DataItem;
}

export interface ListDetailsModel {
    title: string;
    name: string;
    propertyMetadata: Array<SectionData>;
    saveButtonText: string;
    cancelButtonText: string;
    hasSaveButton: boolean;
    loadDataFromServer?: boolean
}
export interface GetListDetailsModelArgs {
    typeFullName: string;
    detailsMode: string;
    dataItem: DataItem;
    sites: DataItem[];
    searchService: string;
}

export interface GetListItemsArgs {
    loadData: LoadItemsData;
    dataItem: DataItem;
}

export interface ListIndexFilterArgs {
    filterValues: any[];
    filterDisplayValue: string;
    filterConfig: ChipsConfig;
}

export const LIST_INDEX_DETAILS_MODES = {
    CREATE: "create",
    EDIT: "edit"
};

export interface ListIndexOperationResult {
    isExecuted: boolean;
    requiresReload: boolean;
}

export interface ListIndexSearchArgs {
    placeholder: string;
}
