import { Component, ViewChild } from "@angular/core";

import { FieldBase } from "../field-base";
import { SfInputComponent } from "@progress/sitefinity-component-framework";

const TEXT_AREA_TYPE: string = "textarea";

@Component({
    selector: "sf-text-area",
    templateUrl: "./text-area.component.html"
})
export class TextAreaComponent extends FieldBase {
    @ViewChild(SfInputComponent, { static: true }) inputComponent: SfInputComponent;
    type: string = TEXT_AREA_TYPE;

    onFocus() {
        super.onFocus();

        if (this.inputComponent) {
            this.inputComponent.focus();
        }
    }

    writeValue(value) {
        const stringValue = value && typeof value === "object" ? JSON.stringify(value, null, 6) : value;
        super.writeValue(stringValue);
    }
}
