import { Component } from "@angular/core";

import { ChoiceComponent } from "./choice.component";
import { createValueAccessor } from "../field-base";
import { CheckBoxStates } from "./checkbox-states";

@Component({
    selector: "sf-multiple-choice",
    templateUrl: "./choice-multiple.component.html",
    providers: [createValueAccessor(ChoiceMultipleComponent)]
})
export class ChoiceMultipleComponent extends ChoiceComponent {
    protected updateChoicesData(index) {
        if (this.choicesData[index] === CheckBoxStates.Unchecked) {
            this.choicesData[index] = CheckBoxStates.Checked;
        } else {
            this.choicesData[index] = CheckBoxStates.Unchecked;
        }
    }
}
