const GUID_REGEX = /[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

export class DynamicItemUrlSegment {
    private itemIdField;

    constructor(private urlSegment: string) {
    }

    get itemId(): string {
        if (!this.itemIdField) {
            const match = GUID_REGEX.exec(this.urlSegment);
            this.itemIdField = match ? match[0] : null;
        }
        return this.itemIdField;
    }
}
