import { Component, Input, OnInit } from "@angular/core";
import { Subject, ReplaySubject, Observable } from "rxjs";
import { map } from "rxjs/operators";
import { DataItem, EntityData } from "../../../../content/dynamic-modules/interfaces";
import { DynamicItemStore } from "../../../../content/dynamic-modules/services/dynamic-item.store";
import { TreeConfig } from "../../../../../../../fields";
import { TypeNames } from "../../../../../../../fields/types/types";
import { SelectorConfig, ServiceInfo, ServiceContract } from "../../../../../../../fields/selector/selector.component";
import { stringConstants } from "../../../../../common-constants";
import { Provider } from "../../../../content/dynamic-modules/components/provider-selector/provider-selector-base.component";
import { ProviderSelectorComponent } from "../../../../content/dynamic-modules/components/provider-selector/provider-selector.component";

export const GET_OWNER_OPERATION = "Default.GetOwner()";

@Component({
    templateUrl: "./change-owner.component.html"
})
export class ChangeOwnerComponent implements OnInit {
    @Input() entityData: EntityData;
    @Input() selectedItems: DataItem[];

    viewModel: OwnersViewModel;
    users: Owner[] = [];
    providersAsync: Subject<ProvidersCollection>;
    treeConfig: TreeConfig;
    totalCount: number;
    selectorConfig: SelectorConfig = null;
    selected: Owner[] = [];
    isLoading: boolean;
    serviceAware: ServiceContract;
    allItemsTabType = ProviderSelectorComponent;
    allItemsTabTypePropertyValues: any;
    selectedProviderName: string;

    private currentOwnerId = null;

    constructor(private readonly dynamicItemStore: DynamicItemStore) { }

    ngOnInit() {
        this.viewModel = {
            Title: `Change ${this.selectedItems.length > 1 ? this.entityData.metadata.displayName.toLowerCase() : this.entityData.metadata.singularName.toLowerCase()} owner`,
            DefaultField: "FullName",
            TypeNames: {
                plural: "users",
                singular: "user"
            }
        };

        this.treeConfig = {
            multiSelection: false,
            isHierarchical: false,
            avatar: true,
            description: true,
            treeProperties: {
                displayField: this.viewModel.DefaultField
            }
        };

        this.selectorConfig = {
            selectionText: this.viewModel.Title,
            formattedTypeName: stringConstants.EMPTY_STRING,
            mainTabConfig: {
                title: this.viewModel.Title
            }
        };

        this.serviceAware = new ServiceContract((info: ServiceInfo) => this.loadMore(info));

        this.loadProviders();
    }

    public providerChanged(item: string) {
        this.selectedProviderName = item;
        this.loadMore({});
    }

    private loadProviders() {
        this.isLoading = true;

        this.providersAsync = new ReplaySubject<ProvidersCollection>(1);
        this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetUserProviders()`).pipe(map(providersResult => {
            const defaultProvider = providersResult.value.find(x => x.isDefault);
            this.selectedProviderName = defaultProvider.name;
            this.dynamicItemStore.service.executeBoundFunction<any>(this.selectedItems[0], GET_OWNER_OPERATION)
            .subscribe((ownerResult) => {
                this.currentOwnerId = ownerResult.value;

                this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetUsers(provider='${this.selectedProviderName}',search='')`).subscribe(usersResult => {
                    this.totalCount = usersResult["@odata.count"];
                    const users: Owner[] = usersResult.value;
                    this.users = this.addFieldsToOwners(users);

                    this.providersAsync.next({ providersCollection: providersResult.value });

                    if (this.selectedItems.length === 1) {
                        this.selectCurrentOwner(this.users);
                    }

                    this.isLoading = false;
                });
            });
        })).subscribe();
    }

    private loadMore(info: ServiceInfo): Observable<any> {
        const search = info.searchText?.trim() || stringConstants.EMPTY_STRING;
        const skip = info.skip || stringConstants.EMPTY_STRING;
        const take = info.take || stringConstants.EMPTY_STRING;
        return this.dynamicItemStore.service.executeUnboundFunction<any>(`Default.GetUsers(provider='${this.selectedProviderName}',search='${search}')?$skip=${skip}&$top=${take}`).pipe(
            map(result => {
                const users: Owner[] = result.value;
                const normalizedUsers = this.addFieldsToOwners(users);

                if (this.selected.length === 0) {
                    this.selectCurrentOwner(normalizedUsers);
                }

                return { dataItems: normalizedUsers, totalCount: result["@odata.count"] };
            }));
    }

    private selectCurrentOwner(owners: Owner[]) {
        const currentOwner = owners.find(user => user.Id === this.currentOwnerId);
        if (currentOwner !== undefined) {
            this.selected = [currentOwner];
        }
    }

    private addFieldsToOwners(owners: Owner[]): Owner[] {
        const users = owners.map((item) => Object.assign({}, item,
            {
                showViewUrl: false,
                searchDescription: true,
                description: item.UserEmail,
                userAvatar: item.ImageUrl
            }));

        return users;
    }
}

interface Owner {
    Id: string;
    ImageUrl: string;
    FullName: string;
    UserEmail: string;
    showViewUrl?: boolean;
    description?: string;
    userAvatar?: string;
    searchDescription?: boolean;
}

interface OwnersViewModel {
    Title: string;
    DefaultField: string;
    TypeNames: TypeNames;
}

interface ProvidersCollection {
    providersCollection: Provider[];
}
