export const COLLAPSE_BUTTON_TEXT = "Collapse content";
// Using default values here because when tests are run these values are undefined
export const EDITOR_COLLAPSE_HEIGHT = 450;
export const EDITOR_MAIN_EMPTY_HEIGHT = 300;
export const EDITOR_EMPTY_HEIGHT = 150;
// 6 is the padding of the Rich text
