const KENDO_EDITOR_VALUE_ACCESSOR = {
    provide: NG_VALUE_ACCESSOR,
    useExisting: forwardRef(() => EditorComponent),
    multi: true
};
const EDITOR_DEFAULT_VALUE = stringConstants.EMPTY_STRING;
export const EDITOR_COLLAPSE_ANIMATION_SPEED = 500;
