const KEY_NAMES = {
    DELETE: "Delete",
    BACKSPACE: "Backspace"
};
const ID_KEY: string = "id";
const KENDO_MARKER = `<span class="k-marker"></span>`;

declare const jQuery: any;
declare const kendo: any;

export const KENDO_EDITOR_LOAD_TIME = 100;
const EDITOR_HIDDEN_CLASS = "-sf-editor-hidden";
@Component({
    selector: "sf-editor",
    templateUrl: "./editor.component.html",
    providers: [KENDO_EDITOR_VALUE_ACCESSOR],
    styleUrls: ["./editor.component.scss"],
    encapsulation: ViewEncapsulation.None,
    animations: [
        trigger("slideOpen", [
            state("open", style({ height: "*" })),
            state("closed", style({ height: `${EDITOR_COLLAPSE_HEIGHT}px` })),

            transition("closed <=> open", [
                animate(`${EDITOR_COLLAPSE_ANIMATION_SPEED}ms ease`)
            ]),

            transition(ANIMATION_STATES.ENTER, [
                animate(0)
            ])
        ])
    ]
})
export class EditorComponent extends FieldBase implements OnInit, OnDestroy {
    @ViewChild("editorHost", { static: true }) editorHostRef: ElementRef;
    @Input() customTools: Array<ToolBarItem>;
    @Input() editorComponentConfig: EditorComponentConfig;
    @Input() selectedItem: any;
    @Input() culture: string;
    @Input() entitySetName: string;
    @Input() editorSettings: any;
    @Output() blur = new EventEmitter<EditorComponent>();
    @Output() select = new EventEmitter();
    @Output() contentKeydown = new EventEmitter();
    @Output() contentKeyup = new EventEmitter();
    @Output() load = new EventEmitter<EditorComponent>();
    @Output() deletedUploadingImage = new EventEmitter<string>();
    @Output() retryUploadingImage = new EventEmitter<any>();
    @Output() selectionChange = new EventEmitter<any>();
    @Output() editImage = new EventEmitter<void>();
    @Output() serializedImmutables = new EventEmitter<string>();
    @Output() deselectImmutables = new EventEmitter<string>();

    isReady$: Subject<any> =  new Subject<any>();
    isCollapsed: boolean = true;
    isExpandButtonVisible: boolean = false;
    collapseAnimationState: string;

    protected expandButtonText = EXPAND_BUTTON_TEXT;
    protected collapseButtonText = COLLAPSE_BUTTON_TEXT;

    public initialValue: string = EDITOR_DEFAULT_VALUE;
    public shouldFocusEditor: boolean = false;
    private kendoEditor: any;
    private editorNS = kendo.ui.editor;
    private EditorNS = kendo.ui.Editor;
    private deleteUploads: string[] = [];
    private element: ElementRef;
    private hasSelectedImmutable: boolean = false;
    private mousePosition: Point;
    private valueToWriteFirst: string = stringConstants.EMPTY_STRING;
    private isValueSetForFirstTime: boolean = true;
    private isFirstUserInput: boolean = false;
    private shouldTriggerValueChange: boolean = false;
    private visibilityObserver: IntersectionObserver;
    private tweets: { [id: string]: string } = {};

    constructor(
        element: ElementRef,
        private editorConfigProvider: CompositeEditorConfigProvider,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private scrollService: ScrollService,
        private adminAppConfigService: ExternalAppConfigService,
        private externalStyleSheetService: ExternalStyleSheetService,
        private renderer: Renderer2,
        private compositeMediaParser: CompositeMediaParser,
        private zone: NgZone) {
        super();
        this.element = element;
    }

    ngOnInit() {
        this.initializeExternalConfig();

        // TODO: Hack for getting formatting styles
        const intervalID = this.windowProvider.setInterval(() => {
            const canSetupEditor = !this.kendoEditor && this.element.nativeElement.offsetParent && this.editorSettings;
            if (canSetupEditor) {
                this.setupKendoEditor();

                this.isReady$.next(true);
            } else if (this.kendoEditor) {
                this.writeValue(this.valueToWriteFirst);

                if (this.valueToWriteFirst !== EDITOR_DEFAULT_VALUE) {
                    this.checkContentCollapse();
                }

                this.windowProvider.clearInterval(intervalID);
            }
        }, KENDO_EDITOR_LOAD_TIME);
    }

    /**
    * Used to determine if editor is visible, if the intersectionRatio > 0,
    * the editor is visible, otherwise - it's covered by another
    * element or is outside of the viewport (example: when a dialog is opened)
     */
    respondToVisibility() {
        this.visibilityObserver = new IntersectionObserver((entries) => {
            //entries array always has 1 element, because we're using the default threshold value
            //https://developer.mozilla.org/en-US/docs/Web/API/Intersection_Observer_API
            if (entries.length === 1) {
                if (entries[0].intersectionRatio > 0) {
                    if (this.shouldFocusEditor) {
                        this.focus();
                    }

                    this.shouldFocusEditor = false;

                    // Sets display:none to the editor toolbar when the editor is not visible
                    // and hides it without animation (for example when a dialog gets opened)
                    if (this.editorComponentConfig && this.editorComponentConfig.alwaysShowToolbar) {
                        this.renderer.removeClass(this.windowProvider.document.body, EDITOR_HIDDEN_CLASS);
                    }
                } else {
                    if (this.editorComponentConfig && this.editorComponentConfig.alwaysShowToolbar) {
                        this.renderer.addClass(this.windowProvider.document.body, EDITOR_HIDDEN_CLASS);
                    }
                }
            }
        });
        this.visibilityObserver.observe(this.editorHostRef.nativeElement);
    }

    ngOnDestroy() {
        super.ngOnDestroy();

        if (this.visibilityObserver) {
            this.visibilityObserver.disconnect();
        }

        if (this.windowProvider.document.body.classList.contains(EDITOR_HIDDEN_CLASS)) {
            this.renderer.removeClass(this.windowProvider.document.body, EDITOR_HIDDEN_CLASS);
        }

        if (this.kendoEditor) {
            this.kendoEditor.destroy();
        }

        this.externalStyleSheetService.destroyExternalStyleSheets();
    }

    inserthtml(value: any) {
        this.isFirstUserInput = true;
        this.kendoEditor.exec("inserthtml", value);
    }

    insertUncleanedHtml(value: any) {
        value = value.value || value;

        // TODO: HACK because we need to refresh kendo before inserting immutable/img when editor is empty
        this.inserthtml({ value: stringConstants.INTERVAL });
        this.triggerValueChanged();
        this.inserthtml({ value: value, skipCleaners: true });
    }

    insertEmbed(value: string) {
        this.storeTweetsFromValue(value);
        this.insertUncleanedHtml(value);
    }

    unlink(value: any) {
        this.kendoEditor.exec("unlink");
        this.triggerValueChanged();
    }

    focus() {
        this.kendoEditor.focus();
        this.checkContentCollapse(false);
    }

    getValue() {
        if (this.kendoEditor) {
            return this.kendoEditor.value();
        }
        return this.initialValue;
    }

    writeValue(value: string) {
        this.valueToWriteFirst = value;

        if (this.kendoEditor && value !== null && value !== undefined) {
            const initialValueIsEditorDefaultValue = this.initialValue === EDITOR_DEFAULT_VALUE;

            const valueIsChanged = this.initialValue !== value;
            this.kendoEditor.value(value);
            this.initialValue = this.kendoEditor.value();

            this.load.emit(this);

            if (valueIsChanged && !initialValueIsEditorDefaultValue) {
                this.serializedImmutables.emit(this.initialValue);
            }

            this.isFirstUserInput = false;
            if (this.isValueSetForFirstTime) {
                this.storeTweetsFromValue(value);

                this.isValueSetForFirstTime = false;
            }
            this.compositeMediaParser.initEmbeddedData();
        }
    }

    postProcessValue(value): string {
        if (!value) {
            return value;
        }

        let updatedValue = value;

        updatedValue = this.replaceTweetWidget(updatedValue);
        updatedValue = this.handleNonBreakingSpaces(updatedValue);

        return updatedValue;
    }

    preProcessValue(value: string): string {
        if (!value) {
            return value;
        }

        let updatedValue = value;
        let editableValue = value;

        const tweeterWidget = this.getTweets(value);
        tweeterWidget.forEach(tweet => {
            editableValue = editableValue.replace(tweet, stringConstants.EMPTY_STRING);
        });

        const links = HtmlHelper.getElementsByTag(editableValue, NODE_NAMES.ANCHOR_ELEMENT);

        links.forEach(link => {
            if (link.indexOf(SelectorConstants.SF_IMMUTABLE) > -1) {
                return;
            }
            const updatedLink = HtmlHelper.insertTextAtFirstEmptyPosition(link, `${SelectorConstants.SF_IMMUTABLE}=""`);
            updatedValue = updatedValue.replace(link, updatedLink);
        });

        const images = HtmlHelper.getElementsByTag(editableValue, NODE_NAMES.IMAGE_ELEMENT, true);

        images.forEach(image => {
            // If the event comes from Paste we remove all images because when they are to be edited from the Editor we get an error.
            if (image.indexOf(SelectorConstants.SF_IMMUTABLE) > -1) {
                return;
            }

            const updatedImage = HtmlHelper.insertTextAtFirstEmptyPosition(image, `${SelectorConstants.SF_IMMUTABLE}=""`);
            updatedValue = updatedValue.replace(image, updatedImage);
        });

        // After publish the content migth be modified such as tweet embets etc. and need to sync the initial value of the editor.
        this.initialValue = updatedValue;
        return updatedValue;
    }

    onEdit() {
        this.editImage.emit();
    }

    getCurrentRange() {
        return this.kendoEditor.getRange();
    }

    setCurrentRange(value: {}) {
        this.kendoEditor.selectRange(value);
    }

    checkContentCollapse(collapse: boolean = true) {
        const triggerCollapse = this.editorHostRef.nativeElement.scrollHeight > EDITOR_COLLAPSE_OFFSET_HEIGHT;
        const isCollapsibleConfigSet = this.editorComponentConfig && this.editorComponentConfig.collapsible !== undefined;
        const collapsible = isCollapsibleConfigSet ? (this.editorComponentConfig.collapsible && triggerCollapse) : triggerCollapse;

        if (collapsible) {
            this.collapseAnimationState = "closed";
            this.isCollapsed = collapse;
        }

        this.isExpandButtonVisible = collapsible;
    }

    embedValueChanged() {
        this.isFirstUserInput = true;
        this.triggerValueChanged();
        this.compositeMediaParser.initEmbeddedData();
    }

    delete(element: HTMLElement) {
        if (element && element.parentElement) {
            const startRestorePoint = new this.editorNS.RestorePoint(this.kendoEditor.getRange(), this.kendoEditor.body);
            removeTrailingBreaks(element);
            element.parentElement.removeChild(element);

            this.pushCurrentStateInUndoRedo(startRestorePoint);
        }
    }

    removeUndoRedoCommand(commandText: string, textToReplace?: string) {
        const id = "Wrapper" + commandText;
        const stackLength = this.kendoEditor.undoRedoStack.stack.length;
        // Get the newly updated value from the editor
        const newUploadedValue = this.kendoEditor.undoRedoStack.stack[this.kendoEditor.undoRedoStack.stack.length - 1].startRestorePoint.html;
        const textToRelace = textToReplace || HtmlHelper.findElementById(newUploadedValue, id);
        this.updateUndoRedoStack(0, id, stackLength, true, textToRelace);
    }

    toggleExpandButton() {
        this.isCollapsed = !this.isCollapsed;

        if (this.isCollapsed) {
            const labelOffsetTop = 150;
            const editorBoundingClientRect = this.editorHostRef.nativeElement.getBoundingClientRect();
            const scrollTopPoint = document.documentElement.scrollTop - Math.abs(editorBoundingClientRect.top) - labelOffsetTop;

            this.scrollService.scrollToPoint(scrollTopPoint, EDITOR_COLLAPSE_ANIMATION_SPEED);
        } else {
            this.focus();
        }
    }

    // Kendo's logic for selecting a text. Adds a k-marker class to a span wrappers.
    getSelectedText(): any {
        const options = {
            range: this.kendoEditor.getRange(),
            body: this.kendoEditor.body,
            immutables: this.kendoEditor.immutables
        };

        this.editorNS.Command.fn.init(options);

        const range = this.editorNS.Command.fn.lockRange(true);
        const nodes = this.editorNS.RangeUtils.textNodes(range);
        const text: string = this.editorNS.LinkCommand.fn.linkText(nodes);
        const markeredText = this.getMarkedText(range.commonAncestorContainer.innerHTML);

        const selectedText: string = text;
        const selectedTextWrapper: string = markeredText;
        return {
            selectedText,
            selectedTextWrapper,
            range
        };
    }

    // Cleans Kendo markers
    cleanMarkers(html: string): string {
        const regex = new RegExp(KENDO_MARKER, "g");

        return html.replace(regex, stringConstants.EMPTY_STRING);
    }

    // Gets Kendo selected marked text.
    getMarkedText(text: string, getOutherHtml: boolean = false): string {
        if (!text) {
            return null;
        }

        const markerStartIndex = text.indexOf(KENDO_MARKER);
        const markerEndIndex = text.lastIndexOf(KENDO_MARKER);
        let markedText;

        if (markerStartIndex < 0) {
            return null;
        }

        if (getOutherHtml) {
            markedText = text.substring(markerStartIndex, markerEndIndex + KENDO_MARKER.length);
        } else {
            markedText = text.substring(markerStartIndex + KENDO_MARKER.length, markerEndIndex);
        }

        return markedText;
    }

    // Get the editor value as html code with adjusted immutables
    getHtmlCode(): string {
        this.kendoEditor.options.serialization.immutables = this.kendoEditor.immutables;
        const content = this.kendoEditor.value();
        this.kendoEditor.options.serialization.immutables = undefined;

        return content;
    }

    // Execute a callback (set the editor value) with adjusted immutables
    executeInDeserializationZone(callback: () => void): void {
        this.kendoEditor.options.deserialization.immutables = undefined;
        callback();
        this.kendoEditor.options.deserialization.immutables = this.kendoEditor.immutables;
    }

    onContentClick(event: any) {
        this.mousePosition = { x: event.clientX, y: event.clientY };

        if (!event.target) {
            return;
        }

        const imageData = event.target.getAttribute("data");

        if (imageData && event.target.nodeName === NODE_NAMES.BUTTON_ELEMENT) {
            const imageToRemove = document.getElementById(imageData);
            if (imageToRemove) {
                this.deleteUploads.push(imageData);
                removeTrailingBreaks(imageToRemove);
                imageToRemove.remove();
                this.triggerValueChanged();
                this.updateUndoRedoStack(0, imageData);
            }

            return;
        }

        if (imageData && event.target.nodeName === NODE_NAMES.ANCHOR_ELEMENT) {
            const imageToRemove = event.target.parentElement.parentElement;
            if (imageToRemove) {
                removeTrailingBreaks(imageToRemove);
                imageToRemove.remove();
                this.triggerValueChanged();
            }

            this.retryUploadingImage.emit(imageData);

            return;
        }

        const selection = event.target;
        this.select.emit({
            selectedElement: selection,
            parentPosition: this.kendoEditor.body.getBoundingClientRect(),
            mousePosition: this.mousePosition
        });
        this.mousePosition = null;

        this.triggerValueChanged();
        this.onTouchedCallback();
    }

    onContentKeydown(event) {
        this.contentKeydown.emit(event);
    }

    onContentKeyup(event) {
        this.contentKeyup.emit(event);
    }

    onTableWizardOpen(): void {
        this.kendoEditor.exec("tableWizard");
        const tableWizardForm = document.querySelector(".k-editor-table-wizard-dialog");

        tableWizardForm.classList.add("sf-form", "-medium", "-sf-centered-box");

        const tableWizardDialog = jQuery(tableWizardForm).data("kendoWindow");
        const tableWizardOkButton = tableWizardForm.querySelector(".k-dialog-ok");
        const tableWizardCloseButton = tableWizardForm.querySelector(".k-dialog-close");
        tableWizardOkButton.innerHTML = SelectorConstants.DONE;

        tableWizardDialog.setOptions({
            draggable: false,
            title: TABLE_WIZARD_TITLE
        });

        tableWizardDialog.maximize();

        // TODO: Hack until Kendo fix their logic for removing the overflow when table wizard is maximaized
        const tableWizardDialogButtons = [tableWizardOkButton, tableWizardCloseButton];

        tableWizardDialogButtons.forEach((button) => {
            button.addEventListener("click", () => {
                tableWizardDialog.close();
            });
        });
    }

    onDrop(event: Event): void {
        event.preventDefault();
        event.stopImmediatePropagation();
    }

    justifyLeft(element?: any): void {
        this.triggerJustifyCommand(KENDO_ALIGN_COMMANDS.LEFT, element);
    }

    justifyCenter(element?: any): void {
        this.triggerJustifyCommand(KENDO_ALIGN_COMMANDS.CENTER, element);
    }

    justifyRight(element?: any): void {
        this.triggerJustifyCommand(KENDO_ALIGN_COMMANDS.RIGHT, element);
    }

    getActiveAlignToolName(element: HTMLElement): string {
        let alignedElement = element;

        if (isImageHyperlink(element)) {
            alignedElement = element.parentElement;
        }

        let activeToolName: string = null;

        if (alignedElement.classList.contains(`-${BUTTON_NAMES.ALIGN_LEFT}`)) {
            activeToolName = BUTTON_NAMES.ALIGN_LEFT;
        }

        if (alignedElement.classList.contains(`-${BUTTON_NAMES.ALIGN_RIGHT}`)) {
            activeToolName = BUTTON_NAMES.ALIGN_RIGHT;
        }

        if (alignedElement.classList.contains(`-${BUTTON_NAMES.ALIGN_CENTER}`)) {
            activeToolName = BUTTON_NAMES.ALIGN_CENTER;
        }

        return activeToolName;
    }

    triggerUserValueChanged(shouldCheckCollapse: boolean = true) {
        this.isFirstUserInput = true;
        this.triggerValueChanged(shouldCheckCollapse);
    }

    hideToolbar(): void {
        this.kendoEditor.toolbar.hide();
    }

    private triggerValueChanged(shouldCheckCollapse: boolean = true) {
        const html = this.kendoEditor.value();
        if (shouldCheckCollapse) {
            this.checkContentCollapse(false);
        }

        if (this.initialValue !== html && this.isFirstUserInput) {
            this.initialValue = html;
            this.onChangeCallback(html);
        }
    }

    private initializeExternalConfig(): void {
        if (!this.editorSettings) {
            const config = this.adminAppConfigService.externalConfig;

            this.editorSettings = (config && config.editorSettings) ? config.editorSettings : {};

            if (config && config.customEditorSettings && this.entitySetName) {
                const toolSetForCurrentEntitySetName = config.customEditorSettings.find(x => x.contentTypes.includes(this.entitySetName));
                if (toolSetForCurrentEntitySetName) {
                    let customConfigurationToBeApplied = toolSetForCurrentEntitySetName.configuration;
                    if (typeof customConfigurationToBeApplied === "string") {
                        customConfigurationToBeApplied = JSON.parse(customConfigurationToBeApplied);
                    }

                    this.editorSettings = customConfigurationToBeApplied;
                }
            }
        }
    }

    private handleDeletedUploads() {
        if (this.deleteUploads.length > 0) {
            this.deleteUploads.forEach(id => {
                this.updateUndoRedoStack(0, id);
            });
            this.deleteUploads = [];
            this.triggerValueChanged();
        }
    }

    private updateUndoRedoStack(startIndex: number, id: string, endIndex?: number, shouldReplace?: boolean, textToReplace?: string) {
        this.deletedUploadingImage.emit(id.slice(7));
        let wrapperElement;
        const length = endIndex || this.kendoEditor.undoRedoStack.stack.length;
        for (let i = startIndex; i < length; i++) {
            const command = this.kendoEditor.undoRedoStack.stack[i];
            if (command.restorePoint) {
                const wrapperIndex = HtmlHelper.findIdStartingIndex(command.restorePoint.html, ID_KEY, id);
                if (wrapperIndex > 0) {
                    wrapperElement = HtmlHelper.findElementById(command.restorePoint.html, id);
                    const newValue = shouldReplace ? command.restorePoint.html.replace(wrapperElement, textToReplace)
                        : command.restorePoint.html.slice(0, wrapperIndex) + command.restorePoint.html.slice(wrapperIndex + wrapperElement.length);
                    command.restorePoint.html = newValue;
                }
            } else {
                const startPointIndex = HtmlHelper.findIdStartingIndex(command.startRestorePoint.html, ID_KEY, id);
                const endPointIndex = HtmlHelper.findIdStartingIndex(command.endRestorePoint.html, ID_KEY, id);
                if (startPointIndex > 0) {
                    wrapperElement = HtmlHelper.findElementById(command.startRestorePoint.html, id);
                    const newValue = shouldReplace ? command.startRestorePoint.html.replace(wrapperElement, textToReplace)
                        : command.startRestorePoint.html.slice(0, startPointIndex) + command.startRestorePoint.html.slice(startPointIndex + wrapperElement.length);
                    command.startRestorePoint.html = newValue;
                }
                if (endPointIndex > 0) {
                    wrapperElement = HtmlHelper.findElementById(command.endRestorePoint.html, id);
                    const oldValue = command.endRestorePoint.html;
                    command.endRestorePoint = command.startRestorePoint;
                    const newValue = shouldReplace ? command.endRestorePoint.html.replace(wrapperElement, textToReplace)
                        : oldValue.slice(0, endPointIndex) + oldValue.slice(endPointIndex + wrapperElement.length);
                    command.endRestorePoint.html = newValue;
                }
            }

            this.kendoEditor.undoRedoStack.stack[i] = command;
        }
    }

    private hasDifference(newValue: string, oldValue: string, regExp: RegExp): boolean {
        const newCount = (newValue.match(regExp) || []).length;
        const oldCount = (oldValue.match(regExp) || []).length;
        return newCount !== oldCount;
    }

    private pushCurrentStateInUndoRedo(startPoint) {
        this.inserthtml(stringConstants.EMPTY_STRING);
        this.triggerValueChanged();
    }

    private processCustomTools(customTools: ToolBarItem[], tools: any[]): void {
        // We are sorting the collection of custom tools first
        // That way we guarantee the order won't be broken when
        // inserting the custom tools in the tools collection.
        // Custom tools without ordinal parameter will be added at the end of the tools
        // collection in the order they were created.
        customTools
            .sort((x, y) => {
                if (x.ordinal === undefined) {
                    return -1;
                }

                if (y.ordinal === undefined) {
                    return 1;
                }

                return x.ordinal - y.ordinal;
            })
            .forEach(element => {
                const tool = {
                    name: element.name,
                    tooltip: element.tooltip,
                    template: element.template,
                    exec: (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        element.exec();
                    }
                };

                const indexOfDefaultToolToOverride = tools.indexOf(element.name);
                if (indexOfDefaultToolToOverride > -1) {
                    if (element.ordinal === undefined) {
                        element.ordinal = indexOfDefaultToolToOverride;
                    }
                    tools.splice(indexOfDefaultToolToOverride, 1);
                }

                if (element.ordinal !== undefined) {
                    tools.splice(element.ordinal, 0, tool);
                } else {
                    tools.push(tool);
                }
            });
    }

    private setupKendoEditor(): void {
        const pasteCleanupOptions: any = {
            all: false,
            css: true,
            keepNewLines: false,
            msAllFormatting: false,
            msConvertLists: true,
            msTags: true,
            none: false,
            span: true
        };

        const externalCustomTools = this.editorConfigProvider.getToolBarItems(jQuery(this.editorHostRef.nativeElement));
        let toolsToRemove = this.editorConfigProvider.getToolBarItemsNamesToRemove();
        toolsToRemove = toolsToRemove ? toolsToRemove : [];
        const tools: any[] =  this.getToolsNames().filter(t => toolsToRemove.indexOf(t) === -1);

        if (this.customTools) {
            this.customTools = this.customTools.filter(t => tools.indexOf(t.name) !== -1);
            this.customTools = this.customTools.filter(t => toolsToRemove.indexOf(t.name) === -1);
            this.customTools.push(...externalCustomTools);
        } else {
            this.customTools = externalCustomTools;
        }

        if (this.customTools) {
            this.processCustomTools(this.customTools, tools);
        }

        let editorConfiguration = {
            tools: tools,
            pasteCleanup: pasteCleanupOptions,
            resizable: {
                content: true,
                toolbar: true
            },
            serialization: {
                semantic: true
            },
            immutables: true,
            keydown: (e) => {
                // This prevents the actions taken from kendo. On delete and bacspace kendo's editor is deleation the whole element.
                if (this.hasSelectedImmutable && (e.key === KEY_NAMES.BACKSPACE || e.key === KEY_NAMES.DELETE)) {
                    e.stopPropagation();
                }
            },
            keyup: () => {
                this.isFirstUserInput = true;
                this.triggerValueChanged();
            },
            paste: (e) => {
                const pastedValue = e.html;

                this.storeTweetsFromValue(pastedValue);
                e.html = stringConstants.EMPTY_STRING;

                this.tryRecognizePaste(pastedValue)
                    .then(recognized => {
                        if (!recognized) {
                            this.inserthtml({ value: pastedValue});
                            this.triggerValueChanged();
                        }
                    });
            },
            change: () => {
                this.triggerUserValueChanged();
                this.blur.emit(this);
            },
            execute: (e) => {
                this.onEditorCommandExecute(e.name, e);
            },
            select: () => {
                // Because some events need to trigger value changed but Kendo editor is firing the result later and it's handle here in select event we need to check if triggerValueChanged needs to be tiggered.
                if (this.shouldTriggerValueChange) {
                    this.triggerUserValueChanged();

                    this.shouldTriggerValueChange = false;
                }
            },
            culture: this.culture
        };

        editorConfiguration = {...editorConfiguration, ...this.editorSettings};
        editorConfiguration.tools = tools;
        editorConfiguration = this.editorConfigProvider.configureEditor(editorConfiguration);
        let editorHost;
        this.zone.runOutsideAngular(() => {
            editorHost = jQuery(this.editorHostRef.nativeElement).kendoEditor(editorConfiguration);
        });

        this.kendoEditor = editorHost.getKendoEditor();

        const toolbar = this.kendoEditor.toolbar.element;
        groupToolbarButtons(toolbar, ".k-i-table-properties", ".k-i-table-insert");
        groupToolbarButtons(toolbar, ".k-i-embed", ".k-i-image");
        groupToolbarButtons(toolbar, ".k-i-insert-document", ".k-i-image");

        const that = this;

        this.kendoEditor.undoRedoStack.bind("redo", function (x) {
            that.handleDeletedUploads();
        });


        this.kendoEditor.toolbar.window.element.parent().addClass("k-editor-widget");
        this.kendoEditor.toolbar.window.setOptions({draggable: false});
        this.kendoEditor.toolbar.window.element.find(".k-editortoolbar-dragHandle").remove();

        this.kendoEditor.undoRedoStack.bind("undo", function (x) {
            that.handleDeletedUploads();

            const nextCommand = x.command;
            if (nextCommand.startRestorePoint && nextCommand.endRestorePoint) {
                const hasDifference = that.hasDifference(nextCommand.startRestorePoint.html, nextCommand.endRestorePoint.html, WRAPPER_REGEX);
                if (hasDifference) {
                    const elementId = HtmlHelper.findFirstDifferentWrapperId(nextCommand.startRestorePoint.html, nextCommand.endRestorePoint.html);
                    const progressIndex = nextCommand.endRestorePoint.html.indexOf("<progress");
                    const endIndex = progressIndex !== -1 ? null : that.kendoEditor.undoRedoStack.stack.indexOf(nextCommand);
                    that.updateUndoRedoStack(0, elementId, endIndex);
                }
            }
        });

        // Kendo Editor does not handle blur event: https://docs.telerik.com/kendo-ui/controls/editors/editor/how-to/appearance/handle-blur-and-focus-events
        this.kendoEditor.body.addEventListener("blur", () => {
            this.triggerUserValueChanged(false);
            this.blur.emit(this);
        });

        // Issue after upgrade to 2020.2.216 upgrade: the section in which is the TableWizard tool should not be hidden when the tool is hidden
        if (typeof this.kendoEditor.toolbar.tools.tableWizard !== "undefined") {
            this.kendoEditor.toolbar.tools.tableWizard.update = function (ui, nodes) {
                const tableFormatFinder = new kendo.ui.editor.BlockFormatFinder([{ tags: ["table"] }]);
                const isFormatted = !tableFormatFinder.isFormatted(nodes);
                if (isFormatted === true) {
                    ui.attr("disabled", "disabled");
                    ui.addClass("k-state-disabled");
                } else {
                    ui.removeAttr("disabled");
                    ui.removeClass("k-state-disabled");
                    ui.removeClass("k-disabled");
                }
            };
        }

        // Issue after upgrade to 2020.2.216 upgrade: k-group-end not be added to the last tool in a group if the tool is not visible, k-group-end should be added to the last tool in the group which is VISIBLE
        this.kendoEditor.toolbar.updateGroups = function () {
            jQuery(this.element).children().not(".k-overflow-tools").each(function () {
                jQuery(this).children().removeClass("k-group-start k-group-end").first().addClass("k-group-start").end().not(".k-state-disabled").last().addClass("k-group-end").end();
            });
        };

        // Provided HACK from Kendo to prevend the changing of tools in the toolbar when immutable is selected
        // We are overriding a default implementation for the refresh tool wee need check it for changes and bugfixes regularly.
        this.editorNS.Toolbar.fn.refreshTools = function () {
            const that = this;
            const editor = that._editor;
            const range = editor.getRange();
            const kendoDom = kendo.ui.editor.Dom;
            const textNodes = kendo.ui.editor.RangeUtils.textNodes(range);
            let nodes = kendoDom.filterBy(textNodes, kendoDom.htmlIndentSpace, true);

            if (!nodes.length) {
                nodes = [range.startContainer];
            }

            that.items().each(function () {
                const tool = that.tools[that._toolName(this)];
                if (tool) {
                    const ui = jQuery(this);
                    if (tool.update) {
                        tool.update(ui, nodes, editor.undoRedoStack);
                    }
                }
            });

            that.update();
        };

        // Provided HACK from Kendo to apply active state for justify commands when image is aligned and has margins
        this.changeJustifyLeftRightLogic();

        this.externalStyleSheetService.applyExternalStyleSheets().subscribe(() => {
            this.kendoEditor.toolbar.decorateFrom(this.kendoEditor.body);
        });
        //https://docs.telerik.com/kendo-ui/controls/editors/editor/how-to/appearance/make-inline-editor-toolbar-always-visible
        if (this.editorComponentConfig && this.editorComponentConfig.alwaysShowToolbar) {
            jQuery(this.kendoEditor.body).addClass("k-state-active").off("focusout.kendoEditor");
            this.shouldFocusEditor = true;
        }

        this.respondToVisibility();
    }

    private changeJustifyLeftRightLogic() {
        // Change justifyLeft logic in order to show active state when image is left aligned and has margins
        this.EditorNS.fn.options.formats.justifyLeft.push({ tags: ["img"], attr: { style: { "float": "left" }} });
        this.editorNS.EditorUtils.registerTool(KENDO_ALIGN_COMMANDS.LEFT, new this.editorNS.BlockFormatTool({
            format: this.EditorNS.fn.options.formats.justifyLeft,
            template: new this.editorNS.ToolTemplate({
                template: this.editorNS.EditorUtils.buttonTemplate,
                title: "Justify Left"
            })
        }));

        // Change justifyRight logic in order to show active state when image is left aligned and has margins
        this.EditorNS.fn.options.formats.justifyRight.push({ tags: ["img"], attr: { style: { "float": "right" }} });
        this.editorNS.EditorUtils.registerTool(KENDO_ALIGN_COMMANDS.RIGHT, new this.editorNS.BlockFormatTool({
            format: this.EditorNS.fn.options.formats.justifyRight,
            template: new this.editorNS.ToolTemplate({
                template: this.editorNS.EditorUtils.buttonTemplate,
                title: "Justify Right"
            })
        }));
    }

    private tryRecognizePaste(pastedValue: string): Promise<boolean> {
        if (!this.compositeMediaParser.canProcess(pastedValue)) {
            return Promise.resolve(false);
        }

        if (!this.compositeMediaParser.isExactMatch(pastedValue)) {
            return Promise.resolve(false);
        }

        return this.compositeMediaParser.parse(pastedValue)
            .then(media => {
                if (media.isValid) {
                    this.insertEmbed(media.html);
                    this.embedValueChanged();
                    this.compositeMediaParser.initEmbeddedData();
                }

                return media.isValid;
            });
    }

    private getToolsNames(): any[] {
        // TODO: Provide tools from configuration file.
        // This order will be kept when Toolbar is initialized
        const tools: any[] = [
            "formatting",
            "bold",
            "italic",
            {
                name: "insertUnorderedList",
                tooltip: "Unordered list"
            },
            {
                name: "insertOrderedList",
                tooltip: "Ordered list"
            },
            "indent",
            "outdent",
            "createLink",
            {
                name: "unlink",
                tooltip: "Remove link"
            },
            "insertImage",
            "insertDocument",
            "embed",
            "createTable",
            "tableWizard",
            "addRowAbove",
            "addRowBelow",
            "addColumnLeft",
            "addColumnRight",
            "deleteRow",
            "deleteColumn",
            "justifyLeft",
            "justifyCenter",
            "justifyRight",
            "subscript",
            "superscript",
            "horizontalRule",
            "cleanFormatting",
            "html"
        ];

        return this.editorSettings.tools || tools;
    }

    private triggerJustifyCommand(justifyCommand: string, element: any): void {
        let inlineMargins;
        // Store inline margins for image immutable only. Кendo overrides them with the align commands
        // If the inline style is margin property and it is valid one (Kendo sets margin: auto and we set only pixeled values)
        // Do not trigger Image specific logic for aligning if it is not image
        if (isImageImmutableSelected(element)) {
            const alignedElement = isImageHyperlink(element) ? element.parentElement : element;
            inlineMargins = getInlineStyles(alignedElement, MARGIN_PROPERTIES, MARGIN_VALUE_UNIT);
        }

        // Mock kendo's body focus so that it does not trigger scrollTop
        const kendoBodyFocus = this.kendoEditor.body.focus;
        this.kendoEditor.body.focus = () => {};

        this.focus();
        this.kendoEditor.exec(justifyCommand);

        this.alignElement(element, justifyCommand, inlineMargins);

        this.kendoEditor.body.focus = kendoBodyFocus;
    }

    private alignElement(element: HTMLElement, justifyCommand: string, inlineStyles = {}) {
        if (!element) {
            return;
        }

        let alignignElement = element;

        // Check if is <a> wrapping the <img>
        if (isImageHyperlink(element)) {
            const imageElement = element as HTMLImageElement;
            const parent = element.parentElement;
            const imageInlineStyles = getInlineStyles(element);

            setInlineStyles(parent, imageInlineStyles);

            // Set additional styles needed for aligning
            parent.style.display = "block";
            parent.style.width = `${imageElement.width}px`;
            parent.style.height = `${imageElement.height}px`;

            alignignElement = parent;
        }

        // Clear previously applied aligning class and toggle current one
        handleKendoAlignCommand(justifyCommand, alignignElement, inlineStyles);
    }

    private onEditorCommandExecute(command: string, event?: any): void {
        switch (command) {
            case "unlink":
                this.deselectImmutables.emit();
                break;
            case "createlink":
                event.preventDefault();
                break;
            default:
                this.shouldTriggerValueChange = true;
                break;
        }
    }

    private storeTweetsFromValue(value: string): void {
        const tweets = this.getTweets(value);
        if (tweets.length) {
            tweets.forEach(tweet => {
                const id = HtmlHelper.getAttributeValue(tweet, TWEET_URL_NAME);
                this.tweets[id] = tweet;
            });
        }
    }

    private getTweets(value: string) {
        return HtmlHelper.getElementsByTypeAndAttribute(value, "div", false, TWEET_URL_NAME, stringConstants.EMPTY_STRING);
    }

    private replaceTweetWidget(value: string): string {
        const tweeterWidget = this.getTweets(value);

        if (tweeterWidget) {
            tweeterWidget.forEach(widget => {
                const id = HtmlHelper.getAttributeValue(widget, TWEET_URL_NAME);

                if (this.tweets[id]) {
                    value = value.replace(widget, this.tweets[id]);
                }
            });
        }
        return value;
    }

    private handleNonBreakingSpaces(value: string) {
        let updatedValue = value;

        // TODO: Needed because kendo adds &nbsp; in empty tag:
        // https://knowledgebase.progress.com/articles/Article/Remove-non-breaking-spaces-in-kendo-editor
        if (this.editorSettings && this.editorSettings.removeNonBreakingSpaces) {
            const regex = /&nbsp;\s*/gi;
            updatedValue = updatedValue.replace(regex, stringConstants.EMPTY_STRING);
        }

        return updatedValue;
    }
}

export class HtmlHelper {
    static findElementById(html: string, id: string): string {
        const imageTag = NODE_NAMES.IMAGE_ELEMENT.toLocaleLowerCase();
        const idIndex = this.findIdStartingIndex(html, ID_KEY, id);
        const elementType = this.getElementType(html, idIndex);
        const closingElement = elementType === imageTag ? ">" : `</${elementType}>`;
        let closingIndex = html.indexOf(closingElement, idIndex);
        const matchExp = new RegExp(`<${elementType} `, "g");
        let openingTagsCount = html.substring(idIndex, closingIndex).match(matchExp).length - 1;
        while (openingTagsCount !== 0) {
            closingIndex = html.indexOf(closingElement, closingIndex + 1);
            openingTagsCount--;
        }
        const element = html.slice(idIndex, closingIndex + closingElement.length);

        return element;
    }

    static getElementType(html: string, startIndex: number) {
        const endIndex = html.indexOf(stringConstants.INTERVAL, startIndex);
        return html.substring(startIndex + 1, endIndex);
    }

    static findFirstDifferentWrapperId(newValue: string, oldValue: string): string {
        const newIndexes = this.getAllWrapperIds(newValue);
        const oldIndexes = this.getAllWrapperIds(oldValue);
        const validList = oldIndexes.filter((item) => {
            return newIndexes.indexOf(item) < 0;
        });
        return validList[0];
    }

    static findIdStartingIndex(html: string, selectorType: string, value: string, startIndex: number = 0): number {
        const searchedMatch = `${selectorType}=\"` + value;
        let idIndex = html.indexOf(searchedMatch, startIndex);
        if (idIndex !== -1) {
            idIndex = html.slice(0, idIndex).lastIndexOf("<");
        }
        return idIndex;
    }

    static getElementsByTag(html: string, elementType: string, isSelfClosing: boolean = false) {
        elementType = elementType.toLocaleLowerCase();
        const closingElement = isSelfClosing ? ">" : `</${elementType}>`;

        const elementsList = new Array<string>();
        let startingIndex = html.indexOf(`<${elementType}`);
        while (startingIndex > -1) {

            const closingIndex = html.indexOf(closingElement, startingIndex);
            if (closingIndex === -1) {
                break;
            }

            const element = html.substring(startingIndex, closingIndex + closingElement.length);
            elementsList.push(element);
            startingIndex = html.indexOf(`<${elementType}`, closingIndex);
        }

        return elementsList;
    }

    static getElementsByTypeAndAttribute(html: string, elementType: string, isSelfClosing: boolean = false, attribute: string, attributeValue: string = "") {
        elementType = elementType.toLocaleLowerCase();

        const elementsList = new Array<string>();
        let tagStartIndex = this.findIdStartingIndex(html, attribute, attributeValue);

        while (tagStartIndex >= 0) {
            let closingIndex = -1;
            const tagName = html.substring(tagStartIndex + 1, html.indexOf(stringConstants.INTERVAL, tagStartIndex));
            if (tagName === elementType) {
                const closingElement = isSelfClosing ? ">" : `</${elementType}>`;

                closingIndex = html.indexOf(closingElement, tagStartIndex);
                if (closingIndex > -1) {
                    const matchExp = new RegExp(`<${elementType} `, "g");
                    let openingTagsCount = 0;
                    const match = html.substring(tagStartIndex, closingIndex).match(matchExp);
                    if (match != null) {
                        openingTagsCount = match.length - 1;
                    }

                    while (openingTagsCount !== 0) {
                        closingIndex = html.indexOf(closingElement, closingIndex + 1);
                        openingTagsCount--;
                    }

                    const element = html.slice(tagStartIndex, closingIndex + closingElement.length);
                    tagStartIndex = this.findIdStartingIndex(html, attribute, attributeValue, closingIndex);
                    elementsList.push(element);
                }
            }

            if (closingIndex === -1) {
                // if we cant find closing tag, we try to get next available attribute
                const attributeHtml = `${attribute}=\"` + attributeValue;
                const attributeIndex = html.indexOf(attributeHtml, tagStartIndex);
                if (attributeIndex !== -1) {
                    const nextTagStartIndex = this.findIdStartingIndex(html, attribute, attributeValue, attributeIndex + attributeHtml.length + 1);
                    if (nextTagStartIndex <= tagStartIndex) {
                        break;
                    } else {
                        tagStartIndex = nextTagStartIndex;
                    }
                } else {
                    break;
                }
            }
        }

        return elementsList;
    }

    static insertTextAtFirstEmptyPosition(originalValue: string, value: string) {
        const selfClosingEndOfTag = stringConstants.FORWARD_SLASH + stringConstants.GREATER_THAN;
        let index = originalValue.indexOf(selfClosingEndOfTag);
        if (index < 0) {
            // if the tag is not self closing - get the end of the first part
            index = originalValue.indexOf(stringConstants.GREATER_THAN);
        }

        return `${originalValue.substr(0, index)} ${value}${originalValue.substr(index)}`;
    }

    static getAttributeValue(html: string, attributeName: string) {
        const attributeToSearch = `${attributeName}="`;
        const regExpString = `${attributeToSearch}.*?\"`;
        const regExp = new RegExp(regExpString, "g");
        const match = regExp.exec(html);
        const id = match ? match[0].slice(attributeToSearch.length, match[0].length - 1) : null;

        return id;
    }

    static setInlineMargins(element: HTMLElement, margins: {}, skipMargins: string[] = []) {
        Object.keys(margins).forEach(key => {
            if (skipMargins.indexOf(key) === -1) {
                element.style[key] = margins[key];
            }
        });
    }

    private static getAllWrapperIds(textToSearch: string): string[] {
        const ids = [];
        const re = /\id="Wrapper.*?\"/g;
        let match = re.exec(textToSearch);
        while (match !== null) {
            ids.push(match[0].slice(4, match[0].length - 1));
            match = re.exec(textToSearch);
        }
        return ids;
    }
}

export interface EditorComponentConfig {
    collapsible: boolean;
    alwaysShowToolbar: boolean;
}
