import { animate, style, query, group, AnimationMetadata, trigger, state, transition } from "@angular/animations";
import { ANIMATION_TIMING } from "../constants/animation-constants";
import { ROUTE_PATHS_NO_PREFIX } from "../constants/route-paths";

export const ANIMATION_RIGHT_TO_LEFT: AnimationMetadata[] = [
    group([
        query(":enter", [
            style({transform: "translateX(0)"}),
            animate(ANIMATION_TIMING, style({transform: "translateX(-100%)"}))
        ], { optional: true }),
        query(":leave", [
            style({transform: "translateX(0)"}),
            animate(ANIMATION_TIMING, style({transform: "translateX(-100%)"}))
        ], { optional: true })
    ])
];
export const ANIMATION_LEFT_TO_RIGHT: AnimationMetadata[] = [
    group([
        query(":enter", [
            style({transform: "translateX(-100%)"}),
            animate(ANIMATION_TIMING, style({transform: "translateX(0)"}))
        ], { optional: true }),
        query(":leave", [
            style({transform: "translateX(-100%)"}),
            animate(ANIMATION_TIMING, style({transform: "translateX(0)"}))
        ], { optional: true })
    ])
];
export const ANIMATION_FROM_TOP: AnimationMetadata[] = [
    query(":enter", [
        style({transform: "translateY(-100%)"}),
        animate(ANIMATION_TIMING, style({transform: "translateY(0)"}))
    ], { optional: true })
];
export const ANIMATION_TO_TOP: AnimationMetadata[] = [
    query(":leave", [
        style({transform: "translateY(0)"}),
        animate(ANIMATION_TIMING, style({transform: "translateY(-100%)"}))
    ], { optional: true })
];
export const ANIMATION_FADE_IN: AnimationMetadata[] = [
    trigger("fadeIn", [
        state("hidden", style({ opacity: 0 })),
        state("visible", style({ opacity: 1 })),
        transition("hidden => visible", [
            animate("200ms ease")
        ])
    ])
];

//right to left
export function isAnimationTypeRightToLeft (fromState: string, toState: string): boolean {
    return fromState === ROUTE_PATHS_NO_PREFIX.MENU_HOME && toState === ROUTE_PATHS_NO_PREFIX.CONTENT;
}
//left to right
export function isAnimationTypeLeftToRight (fromState: string, toState: string): boolean {
    return fromState === ROUTE_PATHS_NO_PREFIX.CONTENT && toState === ROUTE_PATHS_NO_PREFIX.MENU_HOME;
}
//to top
export function isAnimationTypeToTop (fromState: string, toState: string): boolean {
    return (fromState === ROUTE_PATHS_NO_PREFIX.MENU_HOME && toState === ROUTE_PATHS_NO_PREFIX.ANY) ||
        (fromState === ROUTE_PATHS_NO_PREFIX.CONTENT && toState === ROUTE_PATHS_NO_PREFIX.NULL) ||
        (fromState === ROUTE_PATHS_NO_PREFIX.CONTENT && toState === ROUTE_PATHS_NO_PREFIX.ITEMS_GRID);
}
//from top
export function isAnimationTypeFromTop (fromState: string, toState: string): boolean {
    return fromState === ROUTE_PATHS_NO_PREFIX.NULL && toState === ROUTE_PATHS_NO_PREFIX.MENU_HOME;
}

// Animation states
export const ANIMATION_HIDDEN_STATE = "hidden";
export const ANIMATION_VISIBLE_STATE = "visible";
