import { Component, Input, OnInit } from "@angular/core";
import { ContentCultureData } from "../../../../shared/services/metadata/site-data.store";
import { DataItem } from "../../interfaces";
import { stringConstants } from "../../../../../common-constants";

@Component({
    selector: "sf-item-toolbar",
    templateUrl: "./toolbar.component.html"
})
export class ToolbarComponent implements OnInit {
    @Input() dataItem: DataItem;
    @Input() cultureData: ContentCultureData;
    @Input() header: string = stringConstants.EMPTY_STRING;
    @Input() superScript: string = null;

    headerText: string;
    ngOnInit() {
        this.headerText = this.header || `${this.dataItem.metadata.singularName } properties`;
    }
}
