import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, RouterStateSnapshot, Router } from "@angular/router";
import { Observable, of } from "rxjs";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { catchError, map } from "rxjs/operators";
import { ProviderStore } from "../../content/dynamic-modules/services/provider-store";
import { BaseResolver } from "../../content/dynamic-modules/components/dynamic-items-base.resolver";
import { Settings } from "../../shared/services/settings.service";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { PageService } from "./page.service";
import { stringConstants } from "../../../common-constants";
import { CompositeEntityDataResolver } from "../../content/dynamic-modules/services/backend-tweaks/entity-data.resolver";

export const ACTION_KEY = "Action";
export const ACTION_KEYS = {
    EDIT: "Edit"
};

export const PAGES_ENTITY_SET_NAME = "pages";

@Injectable()
export class PageResolver extends BaseResolver {
    constructor(private service: PageService,
                router: Router,
                store: ProviderStore,
                settings: Settings,
                entityDataResolver: CompositeEntityDataResolver) {
                    super(store, router, settings, entityDataResolver);
            this.persistCulture = true;
    }

    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean> {
        const segmentPaths = route.url.map(s => s.path.toLowerCase());
        const actionSegmentIndex = segmentPaths.lastIndexOf(ACTION_KEY.toLowerCase());
        const editSegmentIndex = segmentPaths.lastIndexOf(ACTION_KEYS.EDIT.toLowerCase());

        // either ends with Action/Edit in this order or has one last param for culture
        const canActivate = actionSegmentIndex > 0 &&
                            editSegmentIndex > 0 &&
                            actionSegmentIndex + 1 === editSegmentIndex &&
                            (editSegmentIndex >= (segmentPaths.length - 1) - 2);
        if (!canActivate) {
            this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
        }

        return of(canActivate);
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<PageData> {
        const entityData: EntityData = super.resolve(route, state);

        const pageRelativeUrl = route.url.map(s => s.path).join(stringConstants.FORWARD_SLASH);
        return this.service.getByUrl(`/${pageRelativeUrl}`, entityData)
            .pipe(map(dataItem =>  {
                const pageData: PageData = {
                    item: dataItem,
                    entityData: entityData
                };

                return pageData;
            }),
            catchError(err => {
                this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
                return of(err);
            }));
    }

    protected getCultureFromRoute(route: ActivatedRouteSnapshot): string {
        const segmentPaths = route.url.map(s => s.path);
        const segmentPathsToLowerCase = segmentPaths.map(x => x.toLowerCase());
        const editSegmentIndex = segmentPathsToLowerCase.lastIndexOf(ACTION_KEYS.EDIT.toLowerCase());
        const cultureSegment = segmentPaths[editSegmentIndex + 1];

        let cultureName = cultureSegment;
        if (!cultureName) {
            cultureName = super.getCultureFromRoute(route);
        }

        return cultureName;
    }

    protected getEntitySet(route: ActivatedRouteSnapshot): string {
        return PAGES_ENTITY_SET_NAME;
    }
}

export interface PageData {
    item: DataItem,
    entityData: EntityData
}
