import { Component, Input } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { CompositeGridExtender } from "../../../../shared/services/grid/composite-grid-extender";
import { EntityData, DataItem } from "../../interfaces";

@Component({
    templateUrl: "./quick-navigation-sidebar.component.html"
})
export class QuickNavigationSidebarComponent {
    @Input() title: string;
    @Input() sections: QuickNavigationSidebarSection[];
    @Input() selectedLinkName: string;
    constructor(private route: ActivatedRoute, private gridExtender: CompositeGridExtender, protected router: Router) {
    }

    onNavigateToLink(dataItem: DataItem, entityData: EntityData) {
        this.gridExtender.executeNavigateCommand(this.router, this.route, dataItem, entityData, dataItem.childSetName);
    }
}
export interface QuickNavigationSidebarSection {
    dataItems: DataItem[],
    sourceEntityData: EntityData,
    title: string;
}
