import { Injectable } from "@angular/core";
import { FieldBase } from "../../../../../fields";
import { ChoiceComponent } from "../../../../../fields/choice/choice.component";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { Properties } from "../../shared/fields.constants";
import { TaxonSelectorValue } from "../providers/fields/taxon-selector/taxon-selector.component";

@Injectable()
export class ClassificationWidgetFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === Properties.CLASSIFICATION_SETTINGS) {
            ClassificationWidgetFieldsChangeService.processSelectedClassificationFieldChange(changedValue, fields.map(x => x.currentInstance));
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === "SitefinityClassification" || typeFullName === "SitefinityDynamicList";
    }

    private static processSelectedClassificationFieldChange(changedValue: TaxonSelectorValue, fields: FieldBase[]) {
        const orderByField = ClassificationWidgetFieldsChangeService.getOrderByield(fields);
        if (orderByField) {
            if (changedValue?.selectedTaxonomyUrl) {

                const choiceServiceCallParameters = orderByField.settings.choiceServiceCallParameters ? JSON.parse(orderByField.settings.choiceServiceCallParameters) : null;
                if (choiceServiceCallParameters) {

                    const key = Object.keys(choiceServiceCallParameters[0])[0];
                    const value = choiceServiceCallParameters[0][key];
                    let serviceCallUrl = orderByField.settings.choiceServiceUrl;

                    if (serviceCallUrl.indexOf(value) > -1) {
                        serviceCallUrl = serviceCallUrl.replace(value, changedValue.selectedTaxonomyUrl);
                    } else {
                        serviceCallUrl = serviceCallUrl.replace(/[A-z-]+/, changedValue.selectedTaxonomyUrl);
                    }

                    orderByField.settings.choiceServiceUrl = serviceCallUrl;
                    orderByField.reloadChoices();
                }
            } else {
                orderByField.clearChoices(true);
                orderByField.writeValue(null);
            }
        }
    }

    private static getOrderByield(fields: FieldBase[]): ChoiceComponent {
        const field = fields.find(x => x.settings.key === Properties.ORDER_BY);
        if (field && field instanceof ChoiceComponent) {
            return field;
        }

        return null;
    }
}

export const CLASSIFICATION_WIDGET_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: ClassificationWidgetFieldsChangeService,
    multi: true
};
