import { Command } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject, Subject } from "rxjs";
import { DataItem, OperationResult } from "../../../interfaces";
import { OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { ModalWindowService, ModalComponentSettings, Button, ConfirmButton, ClickResult } from "../../../../../shared/services/modal-window.service";
import { ActivatedRoute } from "@angular/router";
import { DynamicItemService } from "../../dynamic-item.service";
import { Injectable, Inject } from "@angular/core";
import { WINDOW_TOKEN } from "../../../../../../window.provider";
import { OpenInNewWindowArguments } from "./edit-command";
import { buildQueryString, getItemUrl, getQueryParams } from "./commands-helper";
import { SAME_TAB_TARGET } from "../../../../../../common-constants";
import { RelativeDatePipe } from "../../../../../shared/pipes/relative-date.pipe";
import { DateService } from "../../../../../shared/services/date.service";

export interface ConfirmationArgs {
    dataItem: DataItem;
    openInNewWindowArgs?: OpenInNewWindowArguments;
    wasInCreate: boolean;
    commandName: string;
}

@Injectable()
export class ConfirmationCommand implements Command {
    protected datePipe = new RelativeDatePipe(new DateService());

    constructor(private service: DynamicItemService, private modalWindowService: ModalWindowService, @Inject(WINDOW_TOKEN) private window: Window) {
    }

    execute(context: ExecutionContext): Observable<ChainedOperationResult> {
        const args: ConfirmationArgs = context.data;
        const dataItem = args.dataItem;
        const execute$ = new ReplaySubject<ChainedOperationResult>(1);
        const actionName = args.commandName || OPERATION_NAMES.edit;

        this.service
            .executeOperation(dataItem, actionName)
            .subscribe(operationResult => {
                if (operationResult.success || args.wasInCreate) {
                    execute$.next({
                        success: true,
                        data: { ...operationResult }
                    });
                    return;
                }

                this.showModalWindow(operationResult, context.currentRoute.firstChild, args, actionName)
                    .subscribe(result => {
                        result.data = { ...operationResult };
                        execute$.next(result);
                    });
            });

        return execute$;
    }

    private showModalWindow(result: OperationResult, route: ActivatedRoute, args: ConfirmationArgs, routeKey: string): Observable<ChainedOperationResult> {
        const navigate$ = new ReplaySubject<ChainedOperationResult>(1);

        const settings: ModalComponentSettings = this.generateConfirmationSettings(result, route, args, navigate$);
        this.modalWindowService.openModalConfirmation(route, settings, args.dataItem, routeKey);

        return navigate$;
    }

    private generateConfirmationSettings(result: OperationResult, route: ActivatedRoute, args: ConfirmationArgs, done: Subject<ChainedOperationResult>): ModalComponentSettings {
        const settings: ModalComponentSettings = {
            title: result.title,
            icon: "lock",
            parameters: [],
            action: OPERATION_NAMES.unlock,
            description: this.getLocalizedLockedStatusMessage(result.message, result.availableActions, args.dataItem),
            descriptionAllowHtml: true,
            buttons: [],
            hideItemTitle: true,
            doneCallback: (context) => {
                if (!context.data) {
                    done.next({ success: false });
                    return;
                }

                if (!context.data.data) {
                    // when cancel is clicked
                    done.next({ success: false });
                    return;
                }

                if (context.data.data !== null) {
                    if (context.data.data.name === "back") {
                        // when cancel is clicked or go back
                        done.next({ success: false });
                        return;
                    }

                    const dataItem = context.component.dataItem as DataItem;
                    if (context.data.data.name === OPERATION_NAMES.unlock) {
                        if (args.openInNewWindowArgs && args.openInNewWindowArgs.openInNewTab) {
                            const navigateUrl = getItemUrl(dataItem, dataItem.data.ParentId, undefined, true);
                            const queryParams = getQueryParams(dataItem, route);
                            const url = `${args.openInNewWindowArgs.baseUrl}/${navigateUrl}${buildQueryString(queryParams)}`;
                            this.window.open(url, dataItem.data.ParentId);

                            done.next({ success: false });
                        } else {
                            this.service.unlockItem(dataItem).subscribe(() => {
                                this.service.executeOperation(dataItem, (args as any).commandName)
                                    .subscribe(operationResult => {
                                        if (operationResult.success && operationResult.link) {
                                            done.next({ success: false, isLoading: true });
                                            this.window.open(operationResult.link, SAME_TAB_TARGET);
                                            return;
                                        }
                                        done.next({ success: true });
                                    });
                            });
                        }
                        return;
                    } else if (context.data.data.name === OPERATION_NAMES.view && dataItem.metadata.hasContent) {
                        this.service.executeOperation(dataItem, OPERATION_NAMES.preview).subscribe((previewResult) => {
                            if (previewResult.success) {
                                if (previewResult.link) {
                                    this.window.open(previewResult.link, SAME_TAB_TARGET);
                                } else {
                                    done.next({ success: true });
                                }
                            }
                        });

                        return;
                    }
                }

                done.next({ success: true });
            }
        };

        if (result.availableActions) {
            const dataItem = args.dataItem;
            result.availableActions.forEach(action => {
                let button: Button = null;

                const clickResult = new ClickResult({ name: action }, true);

                if (action === OPERATION_NAMES.view) {
                    let actionTitle = "View as read-only";
                    if (dataItem.metadata.hasContent) {
                        actionTitle = "View";
                    }

                    button = new ConfirmButton(actionTitle, () => clickResult);
                } else {
                    button = new ConfirmButton(action, () => clickResult, "large");
                }

                settings.buttons.push(button);
            });

            const isUnlockOnly = result.availableActions.length === 1 && result.availableActions[0] === OPERATION_NAMES.unlock;
            if (isUnlockOnly || result.availableActions.length === 0) {
                settings.buttons.unshift(new ConfirmButton("Go back", () => new ClickResult({ name: "back" }, true)));
            }
        }

        return settings;
    }

    private getLocalizedLockedStatusMessage(messageInUtc: string, availableActions: string[], dataItem: DataItem): string {
        let result = messageInUtc;
        if (dataItem.data.LockedStatus) {
            const localDate = new Date(dataItem.data.LockedStatus.Date);
            const formattedDate = this.datePipe.transform(localDate, RelativeDatePipe.FULL_DATE_WEEKDAY);
            result = `"${dataItem.title}" is locked by ${dataItem.data.LockedStatus.User} on ${formattedDate}`;
        }

        return result;
    }
}

/**
 * This interface is used to mark the result
 * of commands that could be executed in a chain command.
 */
export interface ChainedOperationResult {
    success: boolean;
    isLoading?: boolean;
    data?: any;
}
