import { from as observableFrom, of as observableOf, of } from "rxjs";

import { map } from "rxjs/operators";
import { Observable } from "rxjs";
import { Injectable, ClassProvider } from "@angular/core";
import { ColumnModel } from "../../../../shared/models/column-model";
import { BackendTweaksStore, GridData } from "./backend-tweaks.store";
import { ColumnsProvider, RESERVED_COLUMN_NAMES, COLUMNS_TOKEN } from "../../components/columns-provider";
import { EntityData } from "../../interfaces";
import { CompositeFieldsProvider } from "../../../../../modules/shared/fields-builder/providers/fields-provider";
import { MetadataParserService } from "../../../../shared/services/metadata/meta-data-parser.service";
import { ReadComponent } from "../../../../shared/fields-builder/components/read/read.component";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { EditorReadonlyComponent } from "../../../../../../../fields/html/editor.readonly.component";
import { MediaSettings } from "../../../../libraries/media/media.settings";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ColumnsMap } from "./columns-map";
import { TextFieldComponent } from "../../../../shared/components/fields/text-field.component";
import { stringConstants } from "../../../../../common-constants";
import { FieldTypes } from "../../../../shared/fields-builder/services/fields-registry";
import { DateTimePickerReadOnlyComponent } from "../../../../../../../fields/date-time/date-time-picker-readOnly.component";
import { TaxaGridComponent } from "../../../../taxonomy/taxa/taxa.grid.component";
import { ExternalAppConfigService } from "../../../../../app-config/external-app-config.service";

const FORBIDDEN_COLUMN_NAMES = ["Author"];
const FORBIDDEN_HIERARHICAL_COLUMN_NAMES = ["DateCreated", "LastModified"];

const cssClassMap = new Map<string, string>([
    [FieldTypes.media, "-col-size-xs -media"],
    [FieldTypes.shortText, "-col-size-m"],
    [FieldTypes.address, "-col-size-xl"],
    [FieldTypes.taxa, "-col-size-m"],
    [FieldTypes.textArea, "-col-size-2xl"],
    [FieldTypes.choiceYesNo, "-col-size-2xs"],
    [FieldTypes.relatedData, "-col-size-m"],
    [FieldTypes.urlName, "-col-size-m"],
    [FieldTypes.number, "-col-size-2xs"],
    [FieldTypes.dateTime, "-col-size-s"],
    [FieldTypes.choice, "-col-size-s"]
]);

@Injectable()
export class TweaksColumnProvider implements ColumnsProvider {

    constructor(private store: BackendTweaksStore,
                private fieldsProvider: CompositeFieldsProvider,
                private metadataParserService: MetadataParserService,
                private colsMap: ColumnsMap,
                private externalConfigService: ExternalAppConfigService) {
    }

    getColumns(entityData: EntityData): Observable<ColumnModel[]> {

        const type = entityData.metadata.setName;
        const result = this.store.initializeGrid(type);

        let observableResult: Observable<GridData[]> = null;

        if (!(result instanceof Promise))
            observableResult = observableOf(this.store.getGridByType(type));
        else
            observableResult = observableFrom(result).pipe(map(() => {
                return this.store.getGridByType(type);
            }));

        return observableResult.pipe(map(tweaks => {
            const result = tweaks.filter((column) => {

                if (RESERVED_COLUMN_NAMES.hasOwnProperty(column.name))
                    return false;

                const whitelistedColumnsForCurrentType = this.getWhitelistedColsFromConfig(entityData.metadata.setName);

                // UX decision: hide the Author column for all types (configurable)
                const columnsToExclude = FORBIDDEN_COLUMN_NAMES.filter(x => !whitelistedColumnsForCurrentType.includes(x));
                if (columnsToExclude.find(x => x === column.name))
                    return false;

                // UX decision: hide some of the columns if the module is hierarchical (configurable)
                if (entityData.metadata.children.length > 0 && !entityData.metadata.isSelfReferencing) {
                    const hierarhicalTypeColumnsToExclude = FORBIDDEN_HIERARHICAL_COLUMN_NAMES.filter(x => !whitelistedColumnsForCurrentType.includes(x));
                    if (hierarhicalTypeColumnsToExclude.find(x => x === column.name))
                        return false;
                }

                return true;
            }).map((tweak, index) => {
                const resolvedCol = this.colsMap.tryGetColumnMapping(entityData.metadata, tweak);

                if (resolvedCol) {
                    resolvedCol.ordinal = this.setOrdinalForServerColumn(resolvedCol, index);
                    return resolvedCol;
                }

                const fieldName = tweak.boundPropertyName || tweak.name;
                const propertyMetadata = entityData.metadata.properties[fieldName];
                const fieldType = !!propertyMetadata ? this.metadataParserService.getPropertyFieldType(entityData.metadata, propertyMetadata, null, fieldName, null) : null;
                const fieldRegistration = !!fieldType ? this.fieldsProvider.getFieldRegistration({ fieldType: fieldType, fieldName: fieldName, typeName: entityData.metadata.setName }, entityData.metadata) : null;

                if (!fieldRegistration) {
                    const column = this.createColumnModel(tweak, { type: TextFieldComponent }, stringConstants.EMPTY_STRING, []);
                    column.ordinal = this.setOrdinalForServerColumn(column, index);
                    return column;
                }

                // text area and html are both using EditorReadonly component here, so no need to read metadata from the tweaks
                // to detirmine if the field is html or not
                const gridComponent = fieldRegistration.gridComponent || fieldRegistration.readComponent || ReadComponent;
                const settings: SettingsBase = fieldRegistration.settingsType != null ? new fieldRegistration.settingsType(null, true) : null;
                if (settings) {
                    settings.init(propertyMetadata);

                    if ((settings as MediaSettings).name) {
                        settings.key = settings.key ? settings.key : (settings as MediaSettings).name;
                    }
                    this.metadataParserService.updateFieldSettings(settings, fieldType, propertyMetadata, fieldName, entityData.metadata, tweak);
                    settings.title = tweak.title;
                }

                let cssClass: string = cssClassMap.get(fieldType) ? cssClassMap.get(fieldType) : stringConstants.EMPTY_STRING;

                if (gridComponent === EditorReadonlyComponent) {
                    cssClass = "-col-size-xl";
                    if (settings.look) {
                        settings.look = settings.look + " in-list";
                    } else {
                        settings.look = "in-list";
                    }
                }

                if (gridComponent === DateTimePickerReadOnlyComponent) {
                    settings.look = "-two-lines";
                }

                if (gridComponent === TaxaGridComponent) {
                    settings.look = "size-l";
                }

                const componentData = {
                    type: gridComponent,
                    properties: {
                        settings: settings
                    }
                };

                const column = this.createColumnModel(tweak, componentData, cssClass, [fieldName]);
                column.ordinal = this.setOrdinalForServerColumn(column, index);
                return column;
            })
            .filter((tweak) => !!tweak);

            return result;
        }));
    }

    public getColumnsToRemove(entityData: EntityData): Observable<string[]> {
        return of([]);
    }

    private createColumnModel(currentTweak: any, componentData: ComponentData, cssClass: string, dataFieldNames: string[], title?: string): ColumnModel {
        const column: ColumnModel = {
            name: currentTweak.name,
            title: !!title ? title : currentTweak.title,
            hidden: !currentTweak.visible,
            ordinal: currentTweak.ordinal,
            css: cssClass,
            dataFieldNames: dataFieldNames,
            componentData: componentData
        };
        return column;
    }

    private getWhitelistedColsFromConfig(setName: string): string[] {

        if (!setName) {
            return [];
        }

        const columnNamesWhitelist: { [setName: string]: string[] } = this.externalConfigService.externalConfig.columnNamesWhitelist;
        let whitelistedColumnsForType = [];

        if (columnNamesWhitelist) {

            if (columnNamesWhitelist && columnNamesWhitelist[setName]) {
                whitelistedColumnsForType = columnNamesWhitelist[setName];
            }
        }

        return whitelistedColumnsForType;
    }

    private setOrdinalForServerColumn(column: ColumnModel, placeInQueue: number): number {
        // The idea behind the multiple of '100' is so that there is "space" between the default columns so that clinets can insert their
        // custom columns in between our columns and have the ability to granularly set their ordinals, also to avoid using decimals places
        return placeInQueue * 100;
    }
}

export const TWEAKS_COLUMN_PROVIDER: ClassProvider = {
    multi: true,
    provide: COLUMNS_TOKEN,
    useClass: TweaksColumnProvider
};
