import { Injectable } from "@angular/core";
import { CustomFilterStrategy } from "./custom-filter-strategy";
import { SinglePropertyContainsStrategy } from "./single-property-contains-strategy";
import { SinglePropertyStrategy } from "./single-property-strategy";

@Injectable()
export class FilterStrategyFactory {
    createStrategy(filter: Filter) {
        switch (filter.type) {
            case FilterTypes.Custom:
                return new CustomFilterStrategy(filter);
            case FilterTypes.Search:
                return new SinglePropertyContainsStrategy(filter);
            case FilterTypes.SingleProperty:
                return new SinglePropertyStrategy(filter);
        }
    }
}

// TODO
enum FilterTypes {
    Custom,
    Search,
    SingleProperty
}

interface FilterValue {
    key: string;
    values: string[];
}

interface Filter {
    values: FilterValue[];
    type: FilterTypes;
}
