import { InjectionToken } from "@angular/core";
import { stringConstants } from "../../../../common-constants";
import { PropertyData } from "../../../widget-editor/interfaces/widget-editor";

export const CONFIG_EXTENDER_TOKEN = new InjectionToken("config_extender_token");

export abstract class ConfigExtender {

    getFormClasses(): string {
        return stringConstants.EMPTY_STRING;
    }

    modifyPropertyValuesBeforeSave(properties: PropertyData[]): void { }

    getModifiedValuesForVisualization(configValues: { [key: string]: any }): { [key: string]: any } { return configValues; }

    getSettingsForSpecificFields(configValues: { [key: string]: any }): any { return {}; }

    abstract isSupportedType(queryParam: string): boolean;
}
