import { Injectable } from "@angular/core";
import { SelectorConstants } from "../selector-constants";
import { EmbedMediaParser } from "./embed-media.parser";
import { Media, MediaType } from "./media";
import { contentTypeConstants, stringConstants, IFRAME_ATTRIBUTE_WHITELIST } from "../../../common-constants";

@Injectable()
export class IFrameMediaParser extends EmbedMediaParser {
    canProcess(html: string): boolean {
        const iFrame = this.getIframeFromString(html);
        return this.isIFrameValid(iFrame);
    }

    parse(html: string): Promise<Media> {
        const iFrame = this.getIframeFromString(html, true);

        const media = new Media();
        media.type = MediaType.IFrame;
        media.html = iFrame.outerHTML;
        media.width = this.getNullableInteger(iFrame.width);
        media.height = this.getNullableInteger(iFrame.height);
        media.title = { hasValue: true, value: iFrame.title };
        media.isValid = this.isIFrameValid(iFrame);

        return Promise.resolve(media);
    }

    getMediaFromElement(element: HTMLElement): HTMLElement {
        if (!element)
            return null;

        const iframe = element.querySelector("iframe");
        return iframe;
    }

    updateMediaElement(element: HTMLElement, propName: string, value: any) {
        element[propName] = value;
    }

    getCssText(html: string) {
        const domParser = new DOMParser();
        const virtualDom = domParser.parseFromString(html, <DOMParserSupportedType>contentTypeConstants.HTML);
        const element = <HTMLElement>virtualDom.querySelector(`[${SelectorConstants.SF_IMMUTABLE}]`);
        if (element) {
            element.style.removeProperty("width");
            element.style.removeProperty("position");
            element.style.removeProperty("z-index");
            return element.style.cssText;
        }
    }

    private isIFrameValid(iframe: HTMLIFrameElement): boolean {
        if (!iframe)
            return false;

        if (!iframe.src)
            return false;

        if (!iframe.src.toLowerCase().startsWith("https://"))
            return false;

        return true;
    }

    private getIframeFromString(html: string, shouldSanitize: boolean = false): HTMLIFrameElement {
        const domParser = new DOMParser();
        const iframe = <HTMLIFrameElement>domParser.parseFromString(html, <DOMParserSupportedType>contentTypeConstants.HTML).querySelector("iframe");

        if (shouldSanitize) {
            this.sanitizeIframe(iframe);
        }

        return iframe;
    }

    private sanitizeIframe(iframe: HTMLIFrameElement) {
        iframe.innerHTML = stringConstants.EMPTY_STRING;

        for (let i = iframe.attributes.length - 1; i >= 0; i--) {
            const attribute = iframe.attributes[i];

            if (IFRAME_ATTRIBUTE_WHITELIST.indexOf(attribute.name) < 0) {
                iframe.removeAttribute(attribute.name);
            }
        }
    }
}
