import { OperatorFunction, ObservedValueOf, empty } from "rxjs";
import { catchError } from "rxjs/operators";
export const ERROR_EVENT_NAME = "sf-error-notification-event";

export function catchErrorAndShowNotification<T, O>(filter: string): OperatorFunction<T, T | ObservedValueOf<O>> {
    return catchError((err) => {
        window.dispatchEvent(new CustomEvent("sf-error-notification-event", {
            detail: err,
            bubbles: true
        }));
        return empty();
    });
}
