import { Component, ViewChild, HostBinding } from "@angular/core";

import { FieldBase, createValueAccessor } from "../field-base";
import { stringConstants } from "../../src/app/common-constants";
import { StatusType } from "../field-status";
import { VALIDATOR_MESSAGES } from "../common/validators/validators.constants";
import { NumberSettings } from "./number-settings";
import { LOCALE } from "../common/common-constants";

@Component({
    selector: "sf-number",
    templateUrl: "./number.component.html",
    providers: [createValueAccessor(NumberComponent)]
})
export class NumberComponent extends FieldBase {

    // To be removed when we start handling localization on page level
    @HostBinding ("lang") public langAttribute = LOCALE;

    @ViewChild("inputField", { static: true }) private inputField;

    get numberSettings() {
        return this.settings as NumberSettings;
    }

    onBlur() {
        this.commitValue();
        super.onBlur();
    }

    commitValue() {
        const errors = {
            [VALIDATOR_MESSAGES.INVALID_NUMBER]: true
        };

        if (this.inputField.inputElement.nativeElement.validity.badInput) {
            this.emitStatus({ type: StatusType.Error, data: errors });
        } else {
            if (this.getValue() === stringConstants.EMPTY_STRING) {
                this.writeValue(null);
            }

            if (this.getValue() !== null) {
                this.writeValue(Number(this.getValue()));
            }

            if (this.status$.getValue().type === StatusType.Error) {
                this.emitStatus({ type: StatusType.ErrorCleared, data: errors });
            }

            this.emitStatus({ type: StatusType.Done });
        }
    }
}
