import { ClassProvider, Injectable, NgZone } from "@angular/core";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { EntityData } from "../../../api";
import { QUERY_PARAMS_EXTERNAL } from "../../content/constants";
import { MediaEntity } from "../../shared/services/metadata/meta-data.store";
import { EXTENSIONS } from "../services/media.helpers";
import { DamAsset, DamProviderBase, DAM_PROVIDER_TOKEN, FAILED_TO_INSERT_MEDIA_ASSET } from "./dam-provider-base";

declare const FrontifyFinder: any;

const FRONTIFY_MEDIA_CANNOT_BE_LOADED = "Frontify media selector cannot be loaded. Contact your administrator.";
const FRONTIFY_PROVIDER_TYPE_NAME = "FrontifyBlobStorageProvider";
export const FRONTIFY_FOCAL_POINT_QUERY_PARAM = "sf_fr_fp";

@Injectable()
export class FrontifyDamProvider extends DamProviderBase {
    constructor(protected zone: NgZone) {
        super(zone);
        this.priority = 0;
    }

    isSupported(providerTypeName: string): boolean {
        return providerTypeName === FRONTIFY_PROVIDER_TYPE_NAME;
    }

    loadMediaSelector(damWrapper: HTMLElement, mediaEntityData: EntityData, allowMultiSelect: boolean): void {
        if (!this.areSettingsPropertiesValid()) {
            this.error(FRONTIFY_MEDIA_CANNOT_BE_LOADED);
            return;
        }

        this.loadDynamicScript(this.getPropertyValue("ScriptUrl"))
            .subscribe(() => {
                if (typeof FrontifyFinder === "undefined") {
                    this.error(FRONTIFY_MEDIA_CANNOT_BE_LOADED);
                    return;
                }

                this.createFinder(mediaEntityData, allowMultiSelect)
                    .then(finder => {
                        try {
                            finder.onAssetsChosen((assets: FrontifyAsset[]) => {
                                this.mediaSelected();
                                const damAssets: DamAsset[] = [];

                                if (assets) {
                                    assets.forEach(asset => {
                                        const damAsset: DamAsset = this.getDamAsset(asset);

                                        damAssets.push(damAsset);
                                    });

                                    this.assetsSelected(damAssets);
                                } else {
                                    this.error(FAILED_TO_INSERT_MEDIA_ASSET);
                                }
                            });
                        } catch (ex) {
                            this.error(ex.toString());
                        }

                        finder.onCancel(() => {
                            this.cancel();
                        });

                        finder.mount(damWrapper);
                    }).catch(error => {
                        // On Frontify side when login dialog is closed or concent not accepted they try to access property of undefined object and this causes an error.
                        // It turned out we cannot uniquely detect what caused the exception because in different browsers message differs. The only common is the error name.
                        if (error && error.name === TypeError.name) {
                            this.cancel();
                        } else {
                            this.error(error);
                        }
                    });
            }, () => {
                this.error(FRONTIFY_MEDIA_CANNOT_BE_LOADED);
            });
    }

    private async createFinder(mediaEntityData: EntityData, allowMultiSelect: boolean) {
        return await FrontifyFinder.create({
            clientId: this.getPropertyValue("ClientId"),
            domain: this.getPropertyValue("Url"),
            options: {
                permanentDownloadUrls: true,
                allowMultiSelect: allowMultiSelect,
                filters: [{
                    key: "ext",
                    values: (mediaEntityData.metadata as MediaEntity).acceptableFileTypes,
                    inverted: (mediaEntityData.metadata as MediaEntity).acceptableFileTypes.length === 0
                }]
            }
        });
    }

    private areSettingsPropertiesValid(): boolean {
        if (!this.settings) {
            return false;
        }

        const clientId = this.getPropertyValue("ClientId");
        if (!clientId) {
            return false;
        }

        const scriptUrl = this.getPropertyValue("ScriptUrl");
        if (!scriptUrl) {
            return false;
        }

        const url = this.getPropertyValue("Url");
        if (!url) {
            return false;
        }

        return true;
    }

    private getDamAsset(asset: FrontifyAsset): DamAsset {
        const damAsset: DamAsset = {
            title: asset.title,
            mimeType: null,
            extension: `${stringConstants.DOT}${asset.filename.split(stringConstants.DOT).pop()}`,
            width: Math.floor(asset.width) || null,
            height: Math.floor(asset.height) || null,
            size: Math.floor(asset.size),
            url: asset.previewUrl
        };

        if (asset.type === FrontifyAssetType.Video) {
            damAsset.extension = `${stringConstants.DOT}${EXTENSIONS.MP4}`;

            if (damAsset.url.indexOf(QUERY_PARAMS_EXTERNAL.Format) === -1) {
                const appendSymbol = asset.previewUrl.indexOf("?") === -1 ? "?" : "&";
                damAsset.url += `${appendSymbol}${QUERY_PARAMS_EXTERNAL.Format}=${EXTENSIONS.MP4}`;
            }
        }

        if (asset.type !== FrontifyAssetType.Video && asset.type !== FrontifyAssetType.Image) {
            damAsset.url = asset.downloadUrl;
        }

        if (asset.focalPoint && asset.focalPoint.length > 0) {
            const appendSymbol = damAsset.url.indexOf("?") === -1 ? "?" : "&";
            damAsset.url += `${appendSymbol}${FRONTIFY_FOCAL_POINT_QUERY_PARAM}=${asset.focalPoint.join(",")}`;
        }

        return damAsset;
    }
}

export const FRONTIFY_DAM_PROVIDER: ClassProvider = {
    multi: true,
    provide: DAM_PROVIDER_TOKEN,
    useClass: FrontifyDamProvider
};

export interface FrontifyAsset {
    title: string;
    filename: string;
    previewUrl: string;
    downloadUrl: string;
    width: number;
    height: number;
    size: number;
    type: string;
    focalPoint?: number[];
}

enum FrontifyAssetType {
    File = "File",
    Video = "Video",
    Image = "Image",
    Document = "Document",
    Audio = "Audio"
}
