import { Injectable } from "@angular/core";
import { DynamicItemService } from "../../../../content/dynamic-modules/services/dynamic-item.service";
import { SiteDataStore, SiteData } from "../../../services/metadata/site-data.store";
import { map, mergeMap } from "rxjs/operators";
import { Observable } from "rxjs";

@Injectable()
export class TimeZonesProvider {
    constructor(private siteData: SiteDataStore, private service: DynamicItemService) {
    }

    getTimeZones(): Observable<TimeZone[]> {
        // no caching here as we are not guaranteed that the server values won`t change, although currently they are hardcoded in Sitefinity
        return this.service.executeUnboundFunction<TimeZonesResult>(`${timeZonesRequestFunctionName}()`).pipe(
            map(x => {
                return x.value.map(x => <TimeZone>{ name: x.name, timeZoneId: x.id });
            })
        );
    }

    getDefaultTimeZone(): Observable<TimeZone> {
        // no caching here as we are not guaranteed that the server values won`t change
        // the default time zone per site is stored in db in basic settings and is subject to change on live at any time
        return this.siteData.getValue().pipe(
            mergeMap((x: SiteData) => this.service.executeUnboundFunction<TimeZoneResult>(`${defaultTimeZoneRequestFunctionName}(siteId='${x.Id}')`).pipe(
                map(x => {
                    return <TimeZone>{ name: x.name, timeZoneId: x.id };
                })
            ))
        );
    }
}

export interface TimeZone {
    name: string;
    timeZoneId: string;
}

export interface TimeZoneResult {
    name: string;
    id: string;
}

export interface TimeZonesResult {
    value: TimeZoneResult[];
}

export const timeZonesRequestFunctionName = "Default.SfTimeZones";

export const defaultTimeZoneRequestFunctionName = "Default.SfDefaultTimeZone";
