import { Injectable } from "@angular/core";
import { FieldTypes } from "../../shared/fields-builder/services/fields-registry";
import { ContentLinkInputModel } from "../../html/tools/create-link/link-insert-field/helpers/content-link-input-model";
import { Properties } from "../providers/fields/field-properties-mapper";
import { PropertyData, PropertyMetadata } from "../interfaces/widget-editor";

@Injectable({
    providedIn: "root"
})
export class PropertyValueParserService {

    public parsePropertyToFieldValue(propertyValue: string, fieldType: string, metadata: any): any {
        let value: any = propertyValue;
        if ((fieldType === FieldTypes.relatedData || fieldType === FieldTypes.media) && propertyValue) {
            if (metadata[Properties]["AllowMultiple"]) {
                const selectedValues = this.parseJsonValue(propertyValue);
                value = selectedValues;
            } else {
                const selectedValue = this.parseJsonValue(propertyValue);
                if (selectedValue) {
                    value = [selectedValue];
                }
            }
        } else if (fieldType === FieldTypes.linkInsert) {
            value = propertyValue ? new ContentLinkInputModel({href: this.parseJsonValue(propertyValue, propertyValue).href, sfref: this.parseJsonValue(propertyValue, propertyValue).sfref }) : new ContentLinkInputModel();
            value.isUrlRequired = metadata[Properties]["Validations_Required"]; //once you delete URL we don't want to fire validation for required URL, because it is optional
        } else if (fieldType === FieldTypes.linkSelector) {
            let parsedLinkModel = null;
            if (propertyValue) {
                parsedLinkModel = this.parseJsonValue(propertyValue, propertyValue) as ContentLinkInputModel;
                parsedLinkModel = parsedLinkModel.length ? parsedLinkModel : [parsedLinkModel];
            }
            value = parsedLinkModel;
        } else if (fieldType === FieldTypes.choiceList) { //because yes/no radio buttons doesn't work if the value is parsed
            return value;
        } else if (fieldType === FieldTypes.shortText) {
            return value;
        } else if ((fieldType === FieldTypes.dateTime || fieldType === FieldTypes.date) && value) {
            value = new Date(propertyValue);
            value = isNaN(value) ? null : value;
        } else if (fieldType === FieldTypes.complex && metadata.Type === "enumerable" && value) {
            if (Array.isArray(value)) {
                return value;
            } else {
                value = this.getEnumerableValue(propertyValue);
                if (Array.isArray(value) && metadata.TypeChildProperties && metadata.TypeChildProperties.length > 0) {
                    value.forEach((itemValue) => {
                        Object.keys(itemValue).forEach((itemPropertyName) => {
                            const childPropMetadata = metadata.TypeChildProperties.find(x => x.Name === itemPropertyName);
                            if (childPropMetadata) {
                                const childValue = itemValue[itemPropertyName];
                                if (childPropMetadata.Type === "linkInsert") {
                                    if (childValue && childValue.href) {
                                        itemValue[itemPropertyName] = new ContentLinkInputModel({ href: childValue.href, sfref: childValue.sfref })
                                    }
                                } else if (childPropMetadata.Type === "linkSelect") {
                                    itemValue[itemPropertyName] = childValue.length ? childValue : [childValue];
                                }
                            }
                        });
                    });
                }
            }

        } else if (fieldType === FieldTypes.choiceMultiple && value) {
            let choiceValue = "";
            const stringValues = value.split(", ");
            const choices = this.parseJsonValue(metadata.Properties["Meta_Choices"], []);
            choices.forEach(choice => {
                const isSelected = stringValues.includes(choice.Name) ? "1" : "0";
                choiceValue += isSelected;
            });
            value = choiceValue;
            return choiceValue;
        } else {
            value = this.parseJsonValue(propertyValue, propertyValue);
        }

        return value;
    }

    public parseFieldValueToProperty(fieldValue: any, fieldType: string, metadata: PropertyMetadata): string {
        switch (fieldType) {
            case "datetime":
                if (fieldValue instanceof Date)
                return (fieldValue as Date).toISOString();
            case "linkInsert":
                if (fieldValue && fieldValue.contentItemModel) {
                    return JSON.stringify(fieldValue.contentItemModel.sfLink);
                } else {
                    return fieldValue ? `{"href": "${fieldValue.href}" }` : "";
                }
            case "enumerable":
                if (fieldValue) {
                    let valueArray = [];
                    if (!Array.isArray(fieldValue)) {
                        const elementNames = Object.getOwnPropertyNames(fieldValue);
                            elementNames.forEach((name) => {
                                valueArray.push(fieldValue[name]);
                        });
                    } else {
                        if (metadata.TypeChildProperties && metadata.TypeChildProperties.length > 0) {
                            fieldValue.forEach((itemValue) => {
                                Object.keys(itemValue).forEach((itemPropertyName) => {
                                    const childPropMetadata = metadata.TypeChildProperties.find(x => x.Name === itemPropertyName);
                                    if (childPropMetadata) {
                                        const childValue = itemValue[itemPropertyName];
                                        if (childPropMetadata.Type === "linkInsert") {
                                            if (childValue) {
                                                if (childValue.contentItemModel) {
                                                    itemValue[itemPropertyName] = childValue.contentItemModel.sfLink;
                                                }
                                                else if (childValue.href) {
                                                    itemValue[itemPropertyName] = { href: childValue.href }
                                                }
                                            } else {
                                                itemValue[itemPropertyName] = null;
                                            }
                                        } else if (childPropMetadata.Type === "linkSelect"){
                                            if (childValue.contentItemModel) {
                                                itemValue[itemPropertyName] = childValue.contentItemModel.length ? childValue.contentItemModel : [childValue.contentItemModel];
                                            } else {
                                                itemValue[itemPropertyName] = childValue.length ? childValue : [childValue];
                                            }
                                        }
                                    }
                                });
                            });
                        }

                        valueArray = fieldValue;
                    }
                    return JSON.stringify(valueArray);
                }
            case "multipleChoices":
                if (fieldValue) {
                    let value = "";
                    const choices = this.parseJsonValue(metadata.Properties["Meta_Choices"], []);
                    choices.forEach((choice, index) => {
                        if (fieldValue[index] === "1") {
                            if (value) {
                                value += ", ";
                            }
                            value += choice.Name;
                        }
                    });
                    return value;
                }
            default:
                if (typeof fieldValue !== "string") {
                    return JSON.stringify(fieldValue);
                }
                return fieldValue.toString();
        }
    }

    public parseJsonValue(propertyValue: string, defaultValue: any = null) {
        try {
            return JSON.parse(propertyValue);
        } catch (e) {}

        return defaultValue;
    }

    public stringifyProperties(sourceProperties: PropertyData[], metaPropMap: { [key: string]: PropertyMetadata } ) {
        sourceProperties.forEach(prop => {
            const anyValue = prop.Value;
            const propName = prop.Name;
            if (metaPropMap[propName].Type === "complex") {
                const complexValue = {};
                const propMeta = metaPropMap[propName];
                this.getComplexValueRecursively(anyValue, propMeta, complexValue);

                prop.Value = JSON.stringify(complexValue);
            } else if ((anyValue && typeof anyValue !== "string") || typeof anyValue === "boolean" || typeof anyValue === "number" || metaPropMap[propName].Type === "multipleChoices") {
                prop.Value = this.parseFieldValueToProperty(anyValue, metaPropMap[propName].Type, metaPropMap[propName]);
            }
        });
    }

    private getComplexValueRecursively(anyValue, metaPropMap, complexValue) {
        if (anyValue) {
            Object.keys(anyValue).forEach(key => {
                const propMeta = metaPropMap.TypeChildProperties.find(x => x.Name === key);
                const propValue = anyValue[key];
                if (propMeta.Type === "complex") {
                    complexValue[key] = {};
                    this.getComplexValueRecursively(propValue, propMeta, complexValue[key]);
                } else {
                    complexValue[key] = this.parseJsonValue(this.parseFieldValueToProperty(propValue, propMeta.Type, propMeta), propValue);
                }
            });
        }
    }

    private getEnumerableValue(propertyValue: string) {
        let value = this.parseJsonValue(propertyValue);
        if (!Array.isArray(value)) {
            const objectVal = {};
            value.forEach((element, index) => {
                objectVal[index.toString()] = element;
            });
            value = objectVal;
        }

        return value;
    }
}
