import {
    Component,
    Output,
    EventEmitter,
    Input,
    HostBinding,
    ViewEncapsulation,
    ViewChild, ElementRef, OnInit
} from "@angular/core";
import { CLASS_ZONE_UI, EMPTY_WIDGET_ACTION } from "../../../services/document-enhancer.constants";

const ZONE_WIDGET_LINK_CLASS = `sf-zone-empty ${CLASS_ZONE_UI}`;

@Component({
    selector: "sf-empty-widget",
    templateUrl: "./empty-widget.component.html",
    encapsulation: ViewEncapsulation.None
})
export class EmptyWidgetComponent implements OnInit {
    @Input()
    public get label (): string {
        return this._label;
    }
    public set label (val: string) {
        this._label = val;
        this.isLabeled = !!val;
    }
    @Input() icon: string;
    @Input() text: string;
    @Input() action: string;
    @Input() illustrativeIcon: string;
    @Output() onAddClick = new EventEmitter<void>();
    @HostBinding("class") classes = ZONE_WIDGET_LINK_CLASS;
    @HostBinding("class.-sf-labeled") isLabeled: boolean = false;
    @ViewChild("linkElement", {static: true}) linkElement: ElementRef<HTMLElement>;

    hasAction: boolean = true;

    private _label: string;

    ngOnInit() {
        this.hasAction = this.action !== EMPTY_WIDGET_ACTION.NONE;
    }

    onAddButtonClick(ev: Event) {
        ev.preventDefault();
        ev.stopPropagation();
        this.onAddClick.emit();
    }
}
