import { Injectable, ClassProvider, Injector } from "@angular/core";
import { HttpInterceptor, HttpRequest, HttpHandler, HttpSentEvent, HttpHeaderResponse, HttpProgressEvent, HttpResponse, HttpUserEvent, HTTP_INTERCEPTORS } from "@angular/common/http";
import { Observable } from "rxjs";
import { Settings } from "../shared/services/settings.service";
import { stringConstants } from "../../common-constants";
import { AuthService } from "../auth/auth.service";

@Injectable()
export class SfInterceptor implements HttpInterceptor {
    constructor(private settings: Settings, private injector: Injector) {

    }

    intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpSentEvent | HttpHeaderResponse | HttpProgressEvent | HttpResponse<any> | HttpUserEvent<any>> {
        if (req.url.startsWith(HTTP_PREFIX)) {
            let modifiedUrl = req.url.replace(HTTP_PREFIX, stringConstants.EMPTY_STRING);

            modifiedUrl = `${this.settings.url}${this.removeStartingForwardSlash(modifiedUrl)}`;
            let queryParams = {};
            if (this.settings.siteId)
                queryParams = { "sf_site": this.settings.siteId };

            // resolved at runtime to avoid cyclic dependency with AuthService
            const authService = this.injector.get(AuthService) as AuthService;
            const headers = {
                ["X-SF-Service-Request"]: "true"
            };
            const authHeader = authService.getAuthHeader();
            if (authHeader) {
                headers["Authorization"] = authHeader;
            }

            req = req.clone({
                url: modifiedUrl,
                setHeaders: headers,
                setParams: queryParams
            });
        }

        return next.handle(req);
    }

    private removeStartingForwardSlash(requestUrl: string) {
        if (requestUrl.startsWith(stringConstants.FORWARD_SLASH)) {
            return requestUrl.slice(stringConstants.FORWARD_SLASH.length);
        }

        return requestUrl;
    }
}

export const SF_HTTP_INTERCEPTOR: ClassProvider = {
    multi: true,
    useClass: SfInterceptor,
    provide: HTTP_INTERCEPTORS
};

export const HTTP_PREFIX = "sfprefix";
