import { Component, OnInit } from "@angular/core";
import { stringConstants } from "@progress/sitefinity-component-framework";
import { cloneObject } from "../../../../../utils";
import { RESOLVE_NAMES } from "../../../../content/constants";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { MetadataContainer } from "../../../../shared/services/metadata/meta-data.store";
import { TaxonomySettings } from "../../../../taxonomy";
import { TaxaComponent } from "../../../../taxonomy/taxa/taxa.component";

export const CONTENT_TYPE_SELECTOR_SINGULAR_NAME = "content-type-selector";

@Component({
    selector: "sf-content-type-selector",
    templateUrl: "../../../../taxonomy/taxa/taxa.component.html"
})
export class ContentTypeSelectorComponent extends TaxaComponent implements OnInit {
    private entitySetName: string = stringConstants.EMPTY_STRING;

    public ngOnInit() {
        this.settings.allowCreate = false;
        this.settings.addButtonLook = "circle small";
        const container = this.route.snapshot.data[RESOLVE_NAMES.metadata] as MetadataContainer;
        const entitySetName = this.entitySetName || ((this.settings as ContentTypeSelectorSettings).isDynamicParentContentType ? ENTITY_SET.HIERARCHY_TAXA : ENTITY_SET.FLAT_TAXA);
        const entity = container.entities[entitySetName];

        const cloneEntity = cloneObject(entity);
        cloneEntity.singularName = CONTENT_TYPE_SELECTOR_SINGULAR_NAME;

        this.defaultFieldName = "Title";
        this.dropdownChipsTreeConfig.treeProperties = {
            displayField: "Title"
        }

        this.entityData = {
            metadata: cloneEntity,
            culture: null,
            provider: null
        };

        super.ngOnInit();
    }

    setEntitySetName(newEntitySetName: string) {
        this.entitySetName = newEntitySetName;
    }

    setHidden(hidden: boolean) {
        super.setHidden(hidden);
    }

    protected getTaxaName() {
        const contentTypeSelectorSettings = this.settings as ContentTypeSelectorSettings;
        const plural = contentTypeSelectorSettings.isDynamicParentContentType ? "parent content types" : "content types";
        const singular = contentTypeSelectorSettings.isDynamicParentContentType ? "parent content type" : "content type";
        this.taxaNames = {
            plural: plural,
            singular: singular
        };

        this.addButtonTitle = "Add";
    }
}

export class ContentTypeSelectorSettings extends TaxonomySettings {
    public isDynamicParentContentType: boolean;

    public init(metadata: any): void {
        super.init(metadata);

        if (metadata.hasOwnProperty("Meta_ContentTypeSelector_IsMultipleSelection") && metadata["Meta_ContentTypeSelector_IsMultipleSelection"] === "True") {
            this.allowMultiple = true;
        }

        if (metadata.hasOwnProperty("Meta_ContentTypeSelector_IsDynamicParentContentType") && metadata["Meta_ContentTypeSelector_IsDynamicParentContentType"] === "True") {
            this.isDynamicParentContentType = true;
        }
    }
}

export const CONTENT_TYPE_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: ContentTypeSelectorComponent,
    readComponent: ContentTypeSelectorComponent,
    settingsType: ContentTypeSelectorSettings
};
