import { FilterStrategyBase } from "./filter-strategy-base";
import { Filter } from "../dynamic-item.store";

export class SinglePropertyContainsStrategy extends FilterStrategyBase {
    constructor (protected filter: Filter) {
        super(filter);
    }

    buildQuery(query: any) {
        const propertyKey = this.filter.values[0].key;
        const propertyValue = this.filter.values[0].values[0];

        query = query.or().startsWith(propertyKey, propertyValue).or().contains(propertyKey, " " + propertyValue).done().done();

        return query;
    }
}
