import { Component, OnInit, ViewChild, Input } from "@angular/core";
import { FieldSectionModel, FIELD_SECTION_NAMES } from "../../../../services/fieldSection.model";
import { EditableFieldsComponent } from "../../fields-builder/components/editable-fields/editable-fields.component";
import { FieldModel } from "../../../../services/field.model";
import { ParentSelectorSettings } from "../../../parent-selector/parent-selector-settings";
import { getFormattedTypeName } from "../../../../utils";
import { TypeNames } from "../../../../../../fields/types/types";
import { TaxonomySettings } from "../../../taxonomy/taxonomy.settings";
import { CSS_CLASSES, VIEW_NAME } from "../../../content/constants";
import { FieldsGeneratorService } from "../../services/fields-generator.service";
import { BackendTweaksService } from "../../../content/dynamic-modules/services/backend-tweaks/backend-tweaks.service";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { Properties } from "../../fields.constants";

@Component({
    selector: "sf-create-hierarchical-taxa",
    templateUrl: "./create-hierarchical-taxa.component.html"
})
export class CreateHierarchicalTaxaComponent implements OnInit {
    @ViewChild(EditableFieldsComponent, { static: true }) editableFieldsComponent: EditableFieldsComponent;
    @Input() hierarchicalTaxaSettings: TaxonomySettings;
    @Input() typeName: string;
    @Input() title: string;
    @Input() taxaNames: TypeNames;
    @Input() otherTaxaExist: boolean;
    @Input() entityData: EntityData;
    @Input() parentId: string;

    fieldSections: FieldSectionModel[];

    constructor(private fieldsGeneratorService: FieldsGeneratorService, private backendTweaksService: BackendTweaksService) { }

    ngOnInit() {
        this.initFieldSections();
    }

    private initFieldSections(): void {
        this.backendTweaksService.getFormTweaks(this.entityData.metadata.setName, VIEW_NAME.INSERT, null, this.entityData.provider, this.entityData.culture, this.parentId).then((data) => {
            const fieldSections = this.fieldsGeneratorService.generateFieldsFromTweaks(this.entityData.metadata, data);
            this.fieldSections = fieldSections;
            if (this.fieldSections.length === 1 && this.fieldSections[0].fields.length <= 3) {
                this.fieldSections[0].fields[0].settings.look += " " + CSS_CLASSES.MARGIN_BOTTOM_SHORT_FORM;
            }

            this.modifyFields();

            this.fieldSections.forEach(fieldSection => {
                fieldSection.fields.forEach(field => {
                    this.adjustSettings(field);
                });
            });

            // remove the horizontal line (<hr> in html) from the last section so that there are no 2 lines that are stacked
            // (one from the modal and one from the section)
            this.fieldSections[this.fieldSections.length - 1].settings.insertHorizontalRule = false;

            const dataItem = DataItem.fromEntityData(null, this.entityData);
            this.editableFieldsComponent.updateMirroring(this.fieldSections, dataItem);
        });
    }

    private modifyFields() {
        // only show urlNameField if there is an advanced section
        const advancedSection = this.fieldSections.find(x => x.settings.name === FIELD_SECTION_NAMES.advancedSection);
        const mainSection = this.fieldSections.find(x => x.settings.name === FIELD_SECTION_NAMES.mainSection);
        if (!advancedSection) {
            mainSection.fields = mainSection.fields.filter(x => x.key !== Properties.URL_NAME);
        }

        if (!this.otherTaxaExist) {
            mainSection.fields = mainSection.fields.filter(x => x.key !== Properties.PARENT_ID);
        }
    }

    private adjustSettings(field: FieldModel): void {
        switch (field.key) {
            case Properties.TITLE:
                field.settings.placeholder = `Type ${getFormattedTypeName(this.taxaNames, false, true)} name`;
                field.settings.title = `${getFormattedTypeName(this.taxaNames, false, true)} name`;
                field.settings.showTitle = false;
                field.settings.look = "large";
                field.value = this.title;
                break;
            case Properties.PARENT_ID:
                const parentSelectorSettingsCast: ParentSelectorSettings = field.settings as ParentSelectorSettings;
                const hierarchicalTaxaSettings: TaxonomySettings = Object.assign({}, this.hierarchicalTaxaSettings);
                hierarchicalTaxaSettings.look = null;
                parentSelectorSettingsCast.hierarchicalTaxaSettings = hierarchicalTaxaSettings;
                parentSelectorSettingsCast.selectorNames = this.taxaNames;
                parentSelectorSettingsCast.culture = hierarchicalTaxaSettings.culture;
                field.settings = parentSelectorSettingsCast;
                break;
        }
    }
}
