import { Inject, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { first } from "rxjs/operators";
import { Command } from "../../../../api";
import { DynamicItemService } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { NotificationsService } from "../notifications.service";

const MARK_ALL_ACTION = "Default.MarkAllNotificationsAsRead()";

@Injectable()
export class MarkAllNotificationsAsReadCommand implements Command {

    constructor(@Inject(DynamicItemService) private dynamicItemService: DynamicItemService, private notificationService: NotificationsService) { }

    execute(): Observable<any> {
        this.dynamicItemService.executeUnboundFunction(MARK_ALL_ACTION).pipe(first()).subscribe(() => {
            this.notificationService.onUpdate.next(true);
        });
        return of(true);
    }
}
