import { ExecuteOnceInBulkCommand } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable, ReplaySubject } from "rxjs";
import { OperationResult, EntityData } from "../../../interfaces";
import { ModalWindowService, ConfirmButton, DialogData, Button, ClickResult, CancelButton } from "../../../../../shared/services/modal-window.service";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DynamicItemStore } from "../../dynamic-item.store";
import { SelectorConstants } from "../../../../../html/selector-constants";
import { stringConstants } from "../../../../../../common-constants";
import { Injectable, Inject } from "@angular/core";
import { OPERATION_NAMES, OPERATION_CATEGORIES } from "../../../../../shared/components/action-menu/operation.model";
import { MergeTaxonComponent } from "../../../../../taxonomy/components/merge-taxon.component";
import { BulkItemSelectionInfo } from "../../../components/bulk-operations/bulk-operations.component";
import { WINDOW_TOKEN } from "../../../../../../window.provider";
import { LONG_RUNNING_TASK_CREATED } from "../../../components/long-running-services/long-running-progress.component";

@Injectable()
export class MergeTaxonCommand implements ExecuteOnceInBulkCommand {
    executeOnceInBulk: boolean = true;
    itemSelectionInfo: BulkItemSelectionInfo;

    constructor(private modalWindowService: ModalWindowService, private dynamicItemStore: DynamicItemStore,  @Inject(WINDOW_TOKEN) private window: Window) { }

    execute(context: ExecutionContext): Observable<OperationResult> {
        const entityData: EntityData = context.data.entityData;
        const result = new ReplaySubject<OperationResult>(1);

        const componentData = this.getComponentData(context, this.itemSelectionInfo);

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.MERGE, (data) => this.onSaveClicked(entityData, data.component)),
            new CancelButton()
        ];

        const dialogData = new DialogData(componentData, () => {
            // set success to 'false' in successful cases, to not display notification status after closing dialog
            result.next({ success: false });
            this.modalWindowService.hide(context.currentRoute, true);
        }, buttons, null, "-bottom");

        this.modalWindowService.setMapping(dialogData, OPERATION_NAMES.mergeTaxon);
        this.modalWindowService.open(context.currentRoute, OPERATION_NAMES.mergeTaxon);

        return result.asObservable();
    }

    onSaveClicked(entityData: EntityData, component: MergeTaxonComponent): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);

        if (component.selected.length === 1) {
            const operation: string = `${OPERATION_CATEGORIES.default}${stringConstants.DOT}${OPERATION_NAMES.mergeTaxon}`;
            const targetTaxonId = component.selected[0].Id;
            const data = {
                taxonIds: component.dataItems.map(item => { return item.key; }).filter(x => x !== targetTaxonId),
                targetTaxonId: targetTaxonId
            };

            this.dynamicItemStore.executeEntityOperation(entityData, operation, data)
                .subscribe(() => {
                    const event = new CustomEvent(LONG_RUNNING_TASK_CREATED);
                    this.window.dispatchEvent(event);

                    clickResult.next(new ClickResult(false, true));
                });
        }

        return clickResult;
    }

    private getComponentData(context: ExecutionContext, itemSelectionInfo: BulkItemSelectionInfo): ComponentData {
        const contextParameters = context.data.action ? context.data.action.contextParameters : context.data.contextParameters;
        const componentData: ComponentData = {
            type: MergeTaxonComponent,
            properties: {
                itemSelectionInfo: itemSelectionInfo,
                contextParameters: contextParameters,
                dataItems: context.data.selectedItems,
                entityData: context.data.entityData,
                parentId: context.currentRoute.snapshot.params.parentId
            }
        };

        return componentData;
    }
}
