import { Injectable } from "@angular/core";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../../fields-builder/components/field-wrapper/form-field-wrapper.component";
import { EVENT_PROPERTIES } from "./events.constants";
import { RecurringEventComponent } from "./recurring-event/recurring-event.component";
import { RecurrentRule, RecurrenceFrequency } from "./recurring-event/recurrent-rule";
import { EventTimeCompositeComponent, EventData } from "./event-time-composite-component/event-time.composite.component";
import { EVENT_ITEM_FULL_NAME } from "../../services/metadata/meta-data-constants";

@Injectable()
export class EventsFieldChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === EVENT_PROPERTIES.RECURRENCE_EXPRESSION || changedFieldName === EVENT_PROPERTIES.EVENT_START) {
            const eventCompositeWrapper = fields.find(f => f.currentInstance instanceof EventTimeCompositeComponent);
            const recurringEventWrapper: FormFieldWrapperComponent = fields.find(x => x.currentInstance instanceof RecurringEventComponent);

            if (changedFieldName === EVENT_PROPERTIES.RECURRENCE_EXPRESSION) {
                const recurrenceField = fields.find(x => x.fieldModel.key === EVENT_PROPERTIES.RECURRENCE_EXPRESSION);
                if (recurrenceField.formControl.dirty) {
                    this.processRecurrenceExpressionChange(changedValue, fields);
                    this.handleEventEnd(changedValue, eventCompositeWrapper.currentInstance);
                }
            }

            if (recurringEventWrapper && changedFieldName === EVENT_PROPERTIES.EVENT_START && changedValue[EVENT_PROPERTIES.TIME_ZONE_ID]) {
                recurringEventWrapper.currentInstance.timeZoneId = changedValue[EVENT_PROPERTIES.TIME_ZONE_ID];
            }

            this.processDateChange(eventCompositeWrapper, recurringEventWrapper);

            if (changedValue) {
                this.processAllDayEventChange(changedValue[EVENT_PROPERTIES.ALL_DAY_EVENT], recurringEventWrapper);
            }
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === EVENT_ITEM_FULL_NAME;
    }

    private processDateChange(eventCompositeWrapper: FormFieldWrapperComponent, recurringEventWrapper: FormFieldWrapperComponent) {
        if (!recurringEventWrapper || !eventCompositeWrapper) {
            return;
        }

        const recurringComponent = <RecurringEventComponent>recurringEventWrapper.currentInstance;
        const eventCompositeComponent = <EventTimeCompositeComponent>eventCompositeWrapper.currentInstance;

        const eventData = <EventData>eventCompositeComponent.getValue(true);
        recurringComponent.startDate = new Date(eventData.EventStart);
        recurringComponent.handleEndDateChange(new Date(eventData.EventEnd));
    }

    private processAllDayEventChange(allDayEvent: boolean | undefined | null, recurringEventWrapper: any) {
        if (recurringEventWrapper && allDayEvent !== undefined && allDayEvent !== null) {
            recurringEventWrapper.currentInstance.allDayEvent = allDayEvent;
        }
    }

    private processRecurrenceExpressionChange(changedValue: any, fields: FormFieldWrapperComponent[]): void {
        const recurrenceRule: RecurrentRule = JSON.parse(changedValue);
        const hasRecurrence = recurrenceRule && !(recurrenceRule.frequency === RecurrenceFrequency.None);
        const eventCompositeComponent: EventTimeCompositeComponent = fields.find(x => x.currentInstance instanceof EventTimeCompositeComponent).currentInstance;

        eventCompositeComponent.handleRecurrenceChange(hasRecurrence);
    }

    private handleEventEnd(changedRecurrenceExpression: string, eventTimeCompositeComponent: EventTimeCompositeComponent) {
        if (changedRecurrenceExpression) {
            const recurrenceRule: RecurrentRule = JSON.parse(changedRecurrenceExpression);

            if (recurrenceRule.frequency === RecurrenceFrequency.None) {
                eventTimeCompositeComponent.resetEndDate();
            }
        }
    }
}

export const EVENTS_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: EventsFieldChangeService,
    multi: true
};
