import { Component, OnInit } from "@angular/core";
import { DataContext } from "../../../../shared/models/data-context-component";
import { PAGE_COMPUTED_PROPERTIES } from "../../navigation-options-composite-component/navigation-options.composite.component";
import { NEW_TAB_TARGET } from "../../../../../common-constants";

@Component({
    templateUrl: "./marketing-cell.component.html"
})
export class MarketingCellComponent implements OnInit {
    public context: DataContext;
    public value: MarketingCellValue;

    ngOnInit() {
        this.value = this.context.dataItem.data[PAGE_COMPUTED_PROPERTIES.MARKETING];
    }

    onLinkClick() {
        window.open(this.value.Link, NEW_TAB_TARGET);
    }
}

interface MarketingCellValue {
    Description: string;
    Link: string;
    LinkTitle: string;
}
