import { Injectable, Inject } from "@angular/core";
import { SpecificButtonState, ButtonsState } from "../../content/dynamic-modules/components/action-buttons.resolver";
import { ButtonState } from "../components/action-menu/action-menu-model";
import { Observable, ReplaySubject } from "rxjs";
import { WINDOW_TOKEN } from "../../../window.provider";

const BUTTONS_LOADING_TIME = 1000;

@Injectable()
export class ActionButtonsStateService {
    private buttonsState$ = new ReplaySubject<ButtonsState>(1);
    private buttonCounter: number = 0;
    private lastButtonEmission: number = null;
    private lastButtonState: ButtonState = null;

    constructor(@Inject(WINDOW_TOKEN) private window: Window) {

    }

    public getState$(): Observable<ButtonsState> {
        return this.buttonsState$.asObservable();
    }

    public updateActionButtonsState(primary: SpecificButtonState, stateForOthers?: ButtonState): Observable<void> {
        const ready$ = new ReplaySubject<void>(1);
        const state: ButtonsState = {
            primary,
            stateForOthers
        };

        // if this is the first state change, do nothing, get the current time for the next one
        if (this.lastButtonEmission === null) {
            this.setButtonsState(ready$, state);
            return ready$.asObservable();
        }

        // if this is not the first state change, but the time has ellapsed it is treated as it is the first
        // same case as the above
        const now = new Date().getTime();
        const ellapsedTime = now - this.lastButtonEmission;

        // only enter here if the buttonCounter is 0, otherwise if the time has ellapsed
        // but there is still something scheduled on the queue that has not passed, the events
        // will not be ordered properly
        if ((ellapsedTime >= BUTTONS_LOADING_TIME && this.buttonCounter === 0) || this.lastButtonState === ButtonState.Default) {
            this.setButtonsState(ready$, state);
            return ready$.asObservable();
        }

        // if the time has now ellapsed, wait for the previous state to complete depending on how much clicks there have been
        // in practice it will be always one, but this way the code is universal if we want to change something in the future
        const timeToWait = BUTTONS_LOADING_TIME - ellapsedTime + (this.buttonCounter * BUTTONS_LOADING_TIME);
        this.window.setTimeout(() => {
            this.buttonsState$.next(state);
            ready$.next();
            this.buttonCounter--;
            this.lastButtonEmission = new Date().getTime();
        }, timeToWait);

        this.buttonCounter++;
        return ready$.asObservable();
    }

    private setButtonsState(result$: ReplaySubject<void>, state: ButtonsState): void {
        this.buttonsState$.next(state);
        this.lastButtonEmission = new Date().getTime();
        this.lastButtonState = state.primary ? state.primary.state : state.stateForOthers;
        result$.next();
    }
}
