import { Component, ViewChild, ViewEncapsulation } from "@angular/core";
import { of, Observable } from "rxjs";
import { WidgetEditor, WidgetMetadata, ValidationResult, PropertyData, ActionContext, PropertyMetadata } from "./interfaces/widget-editor";
import { WidgetContext } from "./models/widget-context";
import { Dictionary } from "./property-editor.constants";
import { ZoneSplitterComponent } from "../pages/components/zone-editor/zone-splitter/zone-splitter.component";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { BasicEditorViewComponent } from "./basic-editor.component";
import { ValueChange } from "../shared/fields-builder/components/editable-fields/editable-fields.component";
import { cloneObject } from "../../utils";
import { FieldSectionModel } from "../../services/fieldSection.model";
import { stringConstants } from "../../common-constants";

@Component({
    selector: "sf-change-layout",
    templateUrl: "./change-layout.component.html",
    styleUrls: ["./change-layout.component.scss"],
    encapsulation: ViewEncapsulation.ShadowDom
})
export class ChangeLayoutComponent extends SfRxBase implements WidgetEditor {
    @ViewChild("layout", { static: false }) private zoneSplitter: ZoneSplitterComponent;
    @ViewChild("spacing", { static: false }) private basicEditor: BasicEditorViewComponent;
    private widgetMetadata: WidgetMetadata;

    readonly TAB_SPACING = "Spacing";
    readonly TAB_LAYOUT = "Layout";
    readonly COLUMNS_PADDING = "ColumnsPadding";
    readonly SECTION_PADDING = "SectionPadding";
    readonly STYLING_PROPERTIES = [ "Margins", "Paddings", "SectionMargin", this.SECTION_PADDING, this.COLUMNS_PADDING ];

    context: WidgetContext;
    columnsInfo: number[];
    gridSize: number;
    selectedTab: string;
    tabs: string[] = [ this.TAB_SPACING ];
    fieldChange: () => void;
    changeDirection: () => void;

    initialize(propertiesData: WidgetMetadata): Observable<void> {
        // this is needed not to set sections state in localstorage
        this.context.widgetName = null;
        this.widgetMetadata = propertiesData;
        this.columnsInfo = this.widgetMetadata.propertyValues.ColumnProportionsInfo ? JSON.parse(this.widgetMetadata.propertyValues.ColumnProportionsInfo) : [];
        this.gridSize = this.widgetMetadata.propertyValues.CssSystemGridSize ? JSON.parse(this.widgetMetadata.propertyValues.CssSystemGridSize) : 12;
        this.initializeTabs();

        return of(undefined);
    }

    setValues(propValues: Dictionary): void {
        this.widgetMetadata.propertyValues = propValues;
    }

    onElementVisible(event: HTMLElement) {
        const elementBoundingRect = event.getBoundingClientRect();

        if (elementBoundingRect.left < 0 && elementBoundingRect.right > 0) {
            this.changeDirection();
        }
    }

    validate(): Observable<ValidationResult> {
        let isValid = true;
        if (this.selectedTab === this.TAB_LAYOUT) {
            isValid = this.canReduceColumnsCount(parseInt(this.widgetMetadata.propertyValues.ColumnsCount));
            this.zoneSplitter.showError = !isValid;
        }

        return of({ isValid });
    }

    getModifiedProperties(): Array<PropertyData> {
        const modifiedProperties: Array<PropertyData> = [];

        if (this.selectedTab === this.TAB_LAYOUT) {
            modifiedProperties.push({ Name: "ColumnsCount", Value: this.widgetMetadata.propertyValues.ColumnsCount });
            modifiedProperties.push({ Name: "ColumnProportionsInfo", Value: this.widgetMetadata.propertyValues.ColumnProportionsInfo });
        } else if (this.selectedTab === this.TAB_SPACING) {
            this.STYLING_PROPERTIES.forEach(prop => {
                const value = this.widgetMetadata.propertyValues[prop];
                if (value) {
                    modifiedProperties.push({ Name: prop, Value: JSON.parse(value) });
                }
            });
        }

        return modifiedProperties;
    }

    actionExecuting(context: ActionContext): Observable<any> {
        return of({});
    }

    columnsSizeChange(args: number[]) {
        const newColumnsCount = args.length.toString();
        const newColumnsInfo = JSON.stringify(args);
        if (newColumnsCount !== this.widgetMetadata.propertyValues.ColumnsCount.toString() || (newColumnsCount !== "1" && newColumnsInfo !== this.widgetMetadata.propertyValues.ColumnProportionsInfo)) {
            this.widgetMetadata.propertyValues.ColumnsCount = newColumnsCount;
            this.widgetMetadata.propertyValues.ColumnProportionsInfo = newColumnsInfo;
            this.fieldChange();
        }
    }

    selectTab(tab: string) {
        this.selectedTab = tab;
        if (this.selectedTab === this.TAB_SPACING) {
            const id = setInterval(() => {
                if (this.basicEditor) {
                    clearInterval(id);
                    const modifiedWidgetMetadata = this.modifySpacingProperties(this.widgetMetadata);
                    this.basicEditor.initialize(modifiedWidgetMetadata);
                    this.basicEditor.fieldChange = this.stylingChange.bind(this);
                    let fieldSections: FieldSectionModel[];
                    this.basicEditor.fieldSections$.subscribe(x => {
                        fieldSections = x;
                    });

                    this.basicEditor.editableFieldsComponent.sectionToggle.subscribe(x => {
                        fieldSections.forEach(s => s.settings.isExpanded = s.settings.name === x.sectionName && x.isExpanded);
                    });
                }
            }, 10);
        }
    }

    private initializeTabs() {
        if (this.widgetMetadata.propertyValues.ColumnsCount) {
            this.tabs.unshift(this.TAB_LAYOUT);
            this.selectTab(this.TAB_LAYOUT);
        } else {
            this.selectTab(this.TAB_SPACING);
        }
    }

    private stylingChange(args: ValueChange) {
        let match = args.key.match(/^(\w+)_\d$/);
        if (match) {
            const propKey = match[1];
            match = propKey.match(/Column(\d+)Padding/);
            if (match) {
                const columnIndex = match[1];
                const columnPaddings = this.widgetMetadata.propertyValues[this.COLUMNS_PADDING];
                const value = columnPaddings ? JSON.parse(columnPaddings) : {};
                if (!value[`Column${columnIndex}`]) {
                    value[`Column${columnIndex}`] = {};
                }

                Object.assign(value[`Column${columnIndex}`], args.value);
                this.widgetMetadata.propertyValues[this.COLUMNS_PADDING] = JSON.stringify(value);
            } else {
                const propValues = this.widgetMetadata.propertyValues[propKey];
                const value = propValues ? JSON.parse(propValues) : {};
                this.widgetMetadata.propertyValues[propKey] = JSON.stringify(Object.assign(value, args.value));
            }
        } else {
            this.widgetMetadata.propertyValues[args.key] = JSON.stringify(args.value);
        }

        this.fieldChange();
    }

    private modifySpacingProperties(initialWidgetMetadata: WidgetMetadata): WidgetMetadata {
        const widgetMetadata: WidgetMetadata = cloneObject(initialWidgetMetadata);
        this.filterProperties(widgetMetadata);
        this.createColumnsProperties(widgetMetadata);
        this.splitProperties(widgetMetadata);

        // hide section title
        if (widgetMetadata.propertyMetadata.length === 1) {
            widgetMetadata.propertyMetadata[0].Title = null;
        }

        return widgetMetadata;
    }

    private filterProperties(widgetMetadata: WidgetMetadata) {
        const props = widgetMetadata.propertyMetadataFlat.filter(x => {
            if (this.STYLING_PROPERTIES.indexOf(x.Name) > -1 && x.Name !== this.COLUMNS_PADDING) {
                // hide prop title in table
                x.Properties["Meta_TableView_ColumnTitle"] = null;

                return true;
            }

            return false;
        });

        widgetMetadata.propertyMetadata = [{
            Name: `Section`,
            Title: `Section`,
            Properties: props
        }];
    }

    private createColumnsProperties(widgetMetadata: WidgetMetadata) {
        if (widgetMetadata.propertyMetadataFlat.find(x => x.Name === this.COLUMNS_PADDING)) {
            const columnPaddingValues = widgetMetadata.propertyValues[this.COLUMNS_PADDING];
            const columnPaddings = columnPaddingValues ? JSON.parse(columnPaddingValues) : undefined;
            for (let i = 1; i <= +widgetMetadata.propertyValues.ColumnsCount; i++) {
                // create section
                const prop: PropertyMetadata = cloneObject(widgetMetadata.propertyMetadataFlat.find(x => x.Name === this.SECTION_PADDING));
                prop.Name = `Column${i}Padding`;
                prop.Properties["Meta_TableView_ColumnTitle"] = null;

                widgetMetadata.propertyMetadata.push({
                    Name: `Column ${i}`,
                    Title: `Column ${i}`,
                    Properties: [prop]
                });

                const currentColumnPaddingValue = columnPaddings ? columnPaddings[`Column${i}`] : undefined;
                if (currentColumnPaddingValue) {
                    widgetMetadata.propertyValues[prop.Name] = JSON.stringify(currentColumnPaddingValue);
                }
            }
        }
    }

    private splitProperties(widgetMetadata: WidgetMetadata) {
        widgetMetadata.propertyMetadata.forEach(section => {
            const splitProperties: PropertyMetadata[] = [];
            section.Properties.forEach(prop => {
                for (let index = 0; index < prop.TypeChildProperties?.length; index+=2) {
                    const splitProp: PropertyMetadata = cloneObject(prop);
                    splitProp.Name = `${prop.Name}_${index/2}`;
                    splitProp.TypeChildProperties = prop.TypeChildProperties.slice(index, index+2);
                    splitProp.Title = index === 0 ? splitProp.Title : stringConstants.EMPTY_STRING;
                    splitProperties.push(splitProp);

                    // set split prop value
                    widgetMetadata.propertyValues[splitProp.Name] = widgetMetadata.propertyValues[prop.Name];
                    const propValues = widgetMetadata.propertyValues[prop.Name];
                    const value = propValues ? JSON.parse(propValues) : undefined;
                    if (value) {
                        const filteredValue = Object.keys(value)
                            .filter(key => splitProp.TypeChildProperties.find(x => x.Name === key))
                            .reduce((obj, key) => {
                                obj[key] = value[key];
                                return obj;
                            }, {});

                        widgetMetadata.propertyValues[splitProp.Name] = JSON.stringify(filteredValue);
                    }
                }
            });

            section.Properties = splitProperties;
        });
    }

    private canReduceColumnsCount(newColumnsCount: number): boolean {
        if (newColumnsCount < 1)
            return false;
        if (newColumnsCount >= this.context.component.childContainers.length)
             return true;
         for (let i = newColumnsCount; i < this.context.component.childContainers.length; i++) {
         if (!this.context.component.childContainers[i].isempty)
                 return false;
         }

        return true;
    }
}
