@Injectable()
export class MediaService {
    /// Determines the progress increment at the end of processingUpdatePeriod
    public static readonly processingIncrementInitialMaximum: number = 0.5;
    public static readonly processingIncrementMaximum: number = 0.98;
    /// Upload total
    public static readonly uploadTotal: number = 100;

    private uploadCounter = 0;

    constructor(
        private zone: NgZone,
        private sitefinity: SitefinitySdk,
        private metadataParserService: MetadataParserService,
        private dynamicItemService: DynamicItemService,
        private metadataStore: MetadataStore,
        private filterService: ContentFilterService,
        private canvasService: CanvasService,
        @Inject(DOCUMENT_TOKEN) private document: Document,
        private settings: Settings,
        private errorParserService: ErrorParserService,
        private appStore: AppStore,
        private dynamicItemStore: DynamicItemStore
    ) {
    }

    getLibraries(dataItem: DataItem, skip = 0, take = 0, siteId: string = null): Observable<LoadItemsResponse> {
        const loadItemsData: LoadItemsData = {
            entityData: dataItem,
            order: DATE_CREATED_DESC_SORT_ORDER,
            skip,
            take: take ? take : null,
            siteId,
            fallbackProperties: [Properties.TITLE]
        };

        return this.dynamicItemService.getItemList(loadItemsData);
    }

    getFolders(mediaEntityData: EntityData, parentId: string, recursive: boolean = false, includeParent: boolean = false, skip?: number, take?: number, siteId?: string, searchTerm?: string, queryParams?: { [key: string]: string }, filterByCreateChildPermissions = false, excludedItemIds?, getMediaItems: boolean = false, useLiveData?: boolean, skipFolders?: boolean, skipFoldersOnFilter?: boolean): Observable<LoadItemsResponse> {
        if ((queryParams && queryParams[FILTER_PARAMS.FILTER] && skipFoldersOnFilter) || skipFolders) {
            return of({
                dataItems: [],
                totalCount: 0,
                entityData: mediaEntityData
            });
        }

        let query = createQuery();
        parentId = parentId === undefined ? null : parentId;
        let isFolder = parentId !== null;
        if (searchTerm) {
            isFolder = true;
            query = query.search(searchTerm);
        }

        query = this.applyQueryParams(query, queryParams, isFolder);

        return this.dynamicItemService
            .getItemList({
                entityData: mediaEntityData,
                action: `Default.FoldersRecursiveSearch(parentId=${parentId})?recursive=${recursive}&includeParent=${includeParent}&filterByCreateChildPermissions=${filterByCreateChildPermissions}&excludedItemIds=${excludedItemIds ? excludedItemIds.join(",") : " "}&${QUERY_PARAMS.GET_MEDIA_ITEMS}=${getMediaItems}&useLiveData=${useLiveData ? "true" : "false"}`,
                fallbackProperties: [mediaEntityData.metadata.defaultFieldName],
                siteId: siteId,
                skip: skip,
                take: take,
                query
            }).pipe(
                map(x => {
                    const response: LoadItemsResponse = {
                        dataItems: x.dataItems.map(item => {
                            let entity = item.metadata;
                            if (item.data.RootId) {
                                entity = this.metadataStore.getEntity(ENTITY_SET.FOLDERS);
                            } else if (!MediaHelpers.isLibrary(item.metadata.setName)) {
                                entity = this.metadataStore.getEntity(MediaHelpers.getParentSetName(item));
                            }

                            const element = {
                                Items: item.data[PREVIEW_ITEMS_PROPERTY],
                                TotalItems: item.data[MEDIA_PROPERTIES.CHILDREN_COUNT],
                                TotalFolders: item.data[MEDIA_PROPERTIES.FOLDERS_COUNT]
                            };
                            const dataItemResult = DataItem.from({ ...item.data, ...element }, entity, item.provider, item.culture);

                            return dataItemResult;
                        }),
                        totalCount: x.totalCount,
                        entityData: x.entityData
                    };

                    return response;
                }));
    }

    getFoldersAndContent(mediaEntityData: EntityData, folderId: string, foldersSkip: number, foldersTake: number, dataFieldNames?: string[], queryParams?: { [key: string]: string }, recursive?: boolean, filesSkip?: number, filesTake?: number, searchTerm?: string, skipFolders?: boolean, skipFoldersOnFilter?: boolean, getMediaItems?: boolean): Observable<[LoadItemsResponse, LoadItemsResponse]> {
        const result = new ReplaySubject<[LoadItemsResponse, LoadItemsResponse]>(1);

        if (folderId !== null) {
            this.getFolders(mediaEntityData, folderId, false, false, foldersSkip, foldersTake, null, searchTerm, queryParams, null, null, getMediaItems, null, skipFolders, skipFoldersOnFilter).subscribe(foldersData => {
                const folders = foldersData.dataItems;
                const filesToTake = folders.length === foldersTake ? 0 : filesTake - folders.length;
                const forceNoTake = (filesToTake === 0 && !recursive) ? true : false;
                const dataItem = DataItem.emptyItem(mediaEntityData);
                const files$ = searchTerm ?
                    this.search(dataItem, searchTerm, filesSkip, filesToTake, folderId) :
                    this.getMediaForLibrary(dataItem, folderId, filesSkip, filesToTake, null, dataFieldNames, queryParams, recursive, forceNoTake, searchTerm);
                files$.subscribe(filesData => {
                    result.next([foldersData, filesData]);
                    result.complete();
                });
            });
        }

        return result;
    }

    getFolderById(mediaEntityData: EntityData, folderId: string, provider: string, siteId: string = null): Observable<DataItem> {
        const parentEntity = this.metadataStore.getEntity(mediaEntityData.metadata.parent);
        const dataItem = DataItem.from(null, parentEntity, mediaEntityData.provider, mediaEntityData.culture);

        return this.dynamicItemService.executeBoundFunction(dataItem, `Default.FolderSearchById(id=${folderId})`, [Properties.TITLE]).pipe(
            map(x => {
                const entityData = {
                    culture: mediaEntityData.culture,
                    provider: mediaEntityData.provider,
                    metadata: this.metadataStore.getEntity(MediaHelpers.resolveLibrarySetName(mediaEntityData.metadata.setName))
                };

                if ((x as any).RootId) {
                    entityData.metadata = this.metadataStore.getEntity(ENTITY_SET.FOLDERS);
                }

                if (!MediaHelpers.isLibrary(mediaEntityData.metadata.setName)) {
                    entityData.metadata = this.metadataStore.getEntity(MediaHelpers.getParentSetName(mediaEntityData));
                }

                return DataItem.fromEntityData(x, entityData);
            })
        );
    }

    getRecentMedia(dataItem: DataItem, skip?: number, take?: number, queryParams?: { [key: string]: string }, useLiveData?: boolean): Observable<LoadItemsResponse> {
        const sort = queryParams ? queryParams[FILTER_PARAMS.SORT] : DATE_CREATED_DESC_SORT_ORDER;
        const query = this.sitefinity.query.order(sort);

        let action;
        const filter = queryParams ? queryParams[FILTER_PARAMS.FILTER] : null;
        if (filter) {
            action = `${ACTIONS.FILTER(filter)}`;
        }

        return this.queryItems(dataItem, query, skip, take, undefined, action, undefined, undefined, useLiveData);
    }

    getMediaForLibrary(dataItem: DataItem, id: string, skip?: number, take?: number, siteId?: string, dataFieldNames?: string[], queryParams?: { [key: string]: string }, recursive?: boolean, forceNoTake?: boolean, searchTerm?: string, useLiveData?: boolean): Observable<LoadItemsResponse> {
        let query: any = this.sitefinity.query;
        const recursiveLibraryId = recursive && id ? id : null;

        query = this.applyQueryParams(query, queryParams);
        let whereApplied = false;
        let action;

        if (searchTerm) {
            const searchFields = this.filterService.getSearchFieldsAsString(dataItem);
            action = `Default.Search(searchFields='${searchFields}')`;
            query = this.sitefinity.query;
            query = query.search(searchTerm).order(DATE_CREATED_DESC_SORT_ORDER);
        }

        if (id && !recursiveLibraryId) {
            if (!whereApplied) {
                whereApplied = true;
                query = query.where();
            }

            query = query.or()
                .and()
                .eq(Properties.PARENT_ID, id)
                .eq(Properties.FOLDER_ID, null)
                .done()
                .eq(Properties.FOLDER_ID, id)
                .done();
        }

        if (whereApplied) {
            query = query.done();
        }

        const filter = queryParams ? queryParams[FILTER_PARAMS.FILTER] : null;
        if (filter) {
            action = `${ACTIONS.FILTER(filter)}`;
        }

        return this.queryItems(dataItem, query, skip, take, siteId, action, recursiveLibraryId, forceNoTake, useLiveData, dataFieldNames);
    }

    search(dataItem: DataItem, term: string, skip?: number, take?: number, libraryId?: string, useLiveData?: boolean): Observable<LoadItemsResponse> {
        let action = null;
        let entityData = dataItem;

        if (libraryId) {
            const parentEntity = this.metadataStore.getEntity(dataItem.metadata.parent);
            entityData = DataItem.from(null, parentEntity, dataItem.provider, dataItem.culture);
            action = `Default.mediaItemsRecursiveSearch(parentId=${libraryId})`;
        } else {
            const searchFields = this.filterService.getSearchFieldsAsString(dataItem);
            action = `Default.Search(searchFields='${searchFields}')`;
        }

        const query = this.sitefinity.query.search(term)
            .order(DATE_CREATED_DESC_SORT_ORDER);

        return this.queryItems(entityData, query, skip, take, null, action, undefined, undefined, useLiveData).pipe(
            map(x => {
                x.dataItems = x.dataItems.map(item => DataItem.fromEntityData(item.data, dataItem));
                return x;
            }));
    }

    getThumbnails(entityData: EntityData, imageSrc: string): Observable<any> {
        return this.dynamicItemService.executeBoundFunction(DataItem.emptyItem(entityData), "sfthumbnails", undefined, { imageurl: encodeURIComponent(imageSrc) });
    }

    importDamAssets(entityData: EntityData, damAssets: DamAsset[]): Observable<ImportDamAssetsResult> {
        const subject = new ReplaySubject<ImportDamAssetsResult>();
        const importDamAssetsResult: ImportDamAssetsResult = { dataItems: [], error: null };
        const resultCb = result => {
            const failedAssets: string[] = [];
            result.data.forEach((item, i) => {
                if (item.isSuccessful) {
                    const data = item.response[0].data;
                    const importedDataItem = DataItem.from(data, entityData.metadata, data.Provider, entityData.culture);
                    importDamAssetsResult.dataItems.push(importedDataItem);
                } else {
                    const asset = damAssets[i];
                    failedAssets.push(`${asset.title}${asset.extension}`);
                }
            });

            if (failedAssets.length === 1) {
                importDamAssetsResult.error = `${entityData.metadata.singularName} failed to be selected.`;
            } else if (failedAssets.length > 1) {
                const pluralEntityName = pluralize(entityData.metadata.singularName.toLocaleLowerCase());
                importDamAssetsResult.error = `${failedAssets.length} ${pluralEntityName} failed to be selected: ${failedAssets.join(",")}`;
            }

            subject.next(importDamAssetsResult);
        };
        const errorCb = e => {
            const error = this.errorParserService.parseError(e);
            subject.error(error);
        };
        const batch = this.sitefinity.instance.batch(resultCb, errorCb, () => { }, {
            culture: entityData.culture
        });

        damAssets.forEach(asset => {
            const transaction = batch.beginTransaction();

            transaction.create({
                entitySet: entityData.metadata.setName,
                action: "Default.ImportDamAsset",
                data: {
                    asset: asset
                }
            });

            batch.endTransaction(transaction);
        });
        batch.execute();

        return subject.pipe(first());
    }

    upload(dataItem: DataItem, field: string, media: any, parentId: string, folderId: string = null, directUpload: boolean = false, operationName: string = OPERATION_NAMES.publish, getItemAfterUpload: boolean = true) {
        const items = Array.isArray(media) ? media : [media];
        let videos: Array<Element> = null;
        let thumbSizeMultiplier = 1;

        const uploadObservables: BehaviorSubject<any>[] = [];
        const uploadItems = [];
        items.forEach((item, i) => {
            if (MediaHelpers.isVideoEntity(dataItem)) {
                if (!videos) {
                    const videoElements = this.document.querySelectorAll("sf-modal-window video");
                    // HAX:
                    // this selector gets the video elements from the modal below as well, making the length double
                    // and the first video elements are not currently rendered and have width/height of 0
                    if (videoElements.length !== items.length) {
                        // when uploading through bulk edit, the video previews are significantly smaller than via single upload
                        thumbSizeMultiplier = 1.5;
                    }
                    videos = Array.from(videoElements).filter(x => (x as HTMLElement).offsetParent);
                }

                const video = videos[i] as HTMLVideoElement;
                if (video) {
                    const thumbnail = this.canvasService.renderElement(video, video.clientWidth * thumbSizeMultiplier, video.clientHeight * thumbSizeMultiplier);

                    item.data[Properties.THUMBNAIL_SOURCE] = thumbnail;
                }
            }

            this.prepareItemForUpload(item, false);

            uploadItems.push({ key: field, upload: item, parentId, folderId, directUpload });
            const observable = this.uploadFile(dataItem, item, parentId, folderId, directUpload, operationName, getItemAfterUpload);
            uploadObservables.push(observable);
        });

        // set all items initially
        this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
            const uploadFieldState: UploadFieldState = { uploadedItemsCount: items.length, fieldName: field };
            const allUploadItems = uploadInfo.items.concat(uploadItems);
            this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads({ items: allUploadItems, uploadFieldState: uploadFieldState }));
        });

        // update each item on each progress tick
        uploadObservables.forEach(observable => {
            observable.subscribe(updatedUpload => {
                this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
                    const foundFileForUpload = uploadInfo.items.find(item => item.upload.id === updatedUpload.id);
                    if (foundFileForUpload) {
                        foundFileForUpload.upload = updatedUpload;
                    }

                    const uploadFieldState: UploadFieldState = { uploadedItemsCount: items.length, fieldName: field };
                    this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads({ items: uploadInfo.items, updatedItem: updatedUpload, uploadFieldState }));
                });
            });
        });

        return uploadObservables;
    }

    clearUploads() {
        this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
            const items = uploadInfo.items.filter(job => {
                return !job.upload.failure;
            });

            this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads({
                items,
                uploadFieldState: { uploadedItemsCount: items.length }
            }));
        });
    }

    emptyUploads() {
        this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads({ items: [], uploadFieldState: { uploadedItemsCount: 0 } }));
    }

    retryUpload(entityData: EntityData, upload: any) {
        this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
            const uploads = uploadInfo.items;
            const index = uploads.findIndex(job => job.upload.id === upload.id);
            if (index >= 0) {
                upload.loaded = 0;
                upload.total = MediaService.uploadTotal;
                upload.success = false;
                upload.failure = false;
                this.prepareItemForUpload(upload, true);
                const dataItem = DataItem.emptyItem(entityData);
                const observable = this.uploadFile(dataItem, upload, uploads[index].parentId, uploads[index].folderId, uploads[index].directUpload);
                this.updateItemProgress(observable);
            }
        });
    }

    retryUploadById(dataItem: DataItem, uploadId: any) {
        this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
            const items = uploadInfo.items;
            const item = items.find(job => job.upload.imageId === uploadId);
            let index = -1;
            let upload;
            if (item) {
                upload = item.upload;
                index = items.findIndex(job => job.upload === upload);
            }

            if (index >= 0) {
                this.prepareItemForUpload(upload, true);
                const observable = this.uploadFile(dataItem, upload, items[index].parentId, items[index].folderId, items[index].directUpload);
                this.updateItemProgress(observable);
            }
        });
    }

    removeUploadById(uploadId: any) {
        this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(uploadInfo => {
            const index = uploadInfo.items.findIndex(job => job.upload.id === uploadId);

            if (index >= 0) {
                uploadInfo.items.splice(index, 1);
                this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads(uploadInfo));
            }
        });
    }

    getParentEntityData(mediaEntityData: EntityData): EntityData {
        const setName = mediaEntityData.metadata.parent || mediaEntityData.metadata.setName;
        const entity = this.metadataStore.getEntity(setName);

        const entityData: EntityData = {
            metadata: entity,
            culture: mediaEntityData.culture,
            provider: mediaEntityData.metadata.selectedProvider || mediaEntityData.provider
        };

        return entityData;
    }

    getMediaFileLinks(dataItem: DataItem, getForCurrentFile: boolean = false): Observable<any> {
        const getForCurrentFileQueryParam = `${GET_FOR_CURRENT_FILE_QUERY_PARAM}=${getForCurrentFile}`;
        return this.dynamicItemService.executeBoundFunction<any>(dataItem, `Default.GetMediaFileLinks()?${getForCurrentFileQueryParam}`);
    }

    private applyQueryParams(query, queryParams: { [key: string]: string }, isFolder: boolean = false) {
        if (queryParams && query) {
            let order = queryParams[QUERY_PARAMS.SORT];

            if (order) {
                if (isFolder && (order.indexOf("DateCreated") !== -1 || order.indexOf("Ordinal") !== -1)) {
                    order = order.replace("DateCreated", "LastModified").replace(DEFAULT_ORDINAL_EXPRESSION, LAST_MODIFIED_DESC_SORT_ORDER);
                }
                query = query.order(order);
            }
        }

        return query;
    }

    private queryItems(dataItem: DataItem, query: any, skip: number, take: number, siteId?: string, action?: string, recursiveLibraryId?: string, forceNoTake?: boolean, useLiveData: boolean = false, dataFieldNames?: string[]): Observable<LoadItemsResponse> {
        query = query.expand("Parent($select=Title)");
        const entityData: EntityData = {
            metadata: dataItem.metadata,
            culture: dataItem.culture,
            provider: dataItem.metadata.selectedProvider || dataItem.provider
        };
        const loadItemsData: LoadItemsData = {
            entityData,
            query,
            action,
            skip,
            take: take || (take === 0 && forceNoTake) ? take : null,
            siteId,
            additionalQueryParams: recursiveLibraryId ? { "recursiveLibraryId": recursiveLibraryId } : null,
            fallbackProperties: [Properties.TITLE],
            dataFieldNames,
            serviceUrl: useLiveData ? this.settings.webServiceLiveUrl : null
        };

        return this.dynamicItemService.getItemList(loadItemsData);
    }

    private uploadFile(dataItem: DataItem, upload: UploadDTO, parentId: string, folderId: string, directUpload: boolean, operationName: string = OPERATION_NAMES.publish, getItemAfterUpload: boolean = true): BehaviorSubject<any> {
        const subject = new BehaviorSubject<UploadDTO>(upload);

        const uploadProperties: any = {
            ParentId: parentId
        };

        if (folderId !== null) {
            uploadProperties.FolderId = folderId;
        }

        if (upload.height) {
            uploadProperties.Height = upload.height;
        }

        if (upload.width) {
            uploadProperties.Width = upload.width;
        }

        if (upload.data) {
            Object.keys(upload.data).forEach(key => {
                uploadProperties[key] = upload.data[key];
            });
        }

        const { primitiveFields, relationFields } = this.metadataParserService.classifyFields(dataItem.metadata.setName, uploadProperties);

        this.getChunkUploadInfo(dataItem, parentId, dto => {
            if (dto.ProviderSupportsChunkUpload) {
                this.uploadChunked(subject, dataItem, dto, upload, primitiveFields, relationFields, operationName, directUpload, getItemAfterUpload);
            } else {
                this.legacyUpload(subject, dataItem, upload, primitiveFields, relationFields, operationName, directUpload, getItemAfterUpload);
            }
        });

        return subject;
    }

    private legacyUpload(subject: BehaviorSubject<UploadDTO>, dataItem: DataItem, upload: UploadDTO, primitiveFields: any, relationFields: any, operationName: string, directUpload: boolean, getItemAfterUpload: boolean) {
        // Slow down initial upload progress to have a chance to see the progress bar
        let currentFactor = MediaService.processingIncrementInitialMaximum;

        const success = (result) => {
            const { data } = result.data[0].response[0];

            if (result.isSuccessful) {
                if (getItemAfterUpload) {
                    this.sitefinity.instance.data({ entitySet: dataItem.metadata.setName, provider: dataItem.metadata.selectedProvider || dataItem.provider, culture: dataItem.culture })
                        .getSingle({
                            key: data.Id,
                            successCb: (result) => {
                                upload.result = result;
                                upload.success = true;
                                subject.next(upload);
                            },
                            failureCb: () => {
                                upload.failure = true;
                                subject.next(upload);
                            }
                        });
                } else {
                    upload.result = { Id: data.Id };
                    upload.success = true;
                    subject.next(upload);
                }

            } else {
                upload.failure = true;
                upload.errorMessage = this.getErrorMessage(data.error);
                subject.next(upload);
            }
        };

        const reject = (result) => {
            upload.failure = true;
            subject.next(upload);
        };

        const progress = (event: ProgressEvent) => {
            if (event.lengthComputable) {
                upload.loaded = (event.loaded / event.total) * currentFactor * upload.total;
                if (event.total === event.loaded) {
                    if (upload.success) {
                        upload.loaded = upload.total;
                    }
                }
                this.zone.run(() => { subject.next(upload); });
                if (currentFactor < MediaService.processingIncrementMaximum) {
                    currentFactor = MediaService.processingIncrementMaximum;
                }
            }
        };

        const batch = this.sitefinity.instance.batch(success, reject, progress, {
            provider: dataItem.metadata.selectedProvider || dataItem.provider,
            culture: dataItem.culture
        });

        const transaction = batch.beginTransaction();

        // TODO: replace with: this.dynamicItemService.getFieldValues(dataItem.metadata, uploadProperties);
        // Note: the difference between these methods is that classifyFields returns a isDirectUpload property
        const uploadedFile = transaction.upload({
            entitySet: dataItem.metadata.setName,
            data: upload.content,
            dataUrl: upload.dataUrl,
            contentType: upload.contentType,
            fileName: upload.name ? upload.name.normalize("NFC") : upload.name,
            uploadProperties: primitiveFields
        });

        SitefinitySdk.associateRelationFields(dataItem.metadata.setName, uploadedFile, relationFields, transaction);

        // currently if we have a directUpload set to true that would mean that we want to skip an existing workflow
        // which would publish the item directly and we do not need to do an operation after that
        // The case in which this boolean variable is "true" is when uploading related media data, and is handled by
        // the server Telerik.Sitefinity.Web.Api.Strategies.MediaContentStrategy.ExecuteOperation()
        transaction.operation({
            entitySet: dataItem.metadata.setName,
            key: uploadedFile,
            data: {
                action: operationName,
                actionParameters: {
                    directUpload
                }
            }
        });

        batch.endTransaction(transaction);
        batch.execute();
    }

    private getErrorMessage(error: GenericError): string {
        let message = error.message;

        if (error.code === ERROR_CODES.VALIDATION) {
            const errorObj = JSON.parse(error.message);
            message = Object.keys(errorObj)
                .map(key => errorObj[key])
                .join(stringConstants.NEW_LINE);
        }

        return message;
    }

    private prepareItemForUpload(item: any, isItemRetried: boolean): void {
        item.loaded = 0;
        item.total = MediaService.uploadTotal;
        item.success = false;
        item.failure = false;

        if (!isItemRetried) {
            item.id = this.uploadCounter++;
        }
    }

    private updateItemProgress(itemUploadObservable: BehaviorSubject<any>) {
        itemUploadObservable.subscribe((updatedUpload) => {
            this.appStore.pipe(MEDIA_SELECTORS.uploadsData, take(1)).subscribe(currentUploadInfo => {
                const foundItemForUpload = currentUploadInfo.items.find(item => item.upload.id === updatedUpload.id);
                if (foundItemForUpload) {
                    foundItemForUpload.upload = updatedUpload;
                }

                this.appStore.dispatch(MEDIA_DISPATCH_ACTIONS.setUploads({ items: currentUploadInfo.items, updatedItem: updatedUpload, uploadFieldState: currentUploadInfo.uploadFieldState }));
            });
        });
    }

    //#region Chunk upload
    getChunkUploadInfo(dataItem: DataItem, libraryId: string, successCb?: Function, failureCb?: Function, progressCb?: Function) {
        const typeOptions: TypeOptions = {
            entitySet: dataItem.metadata.setName,
            provider: dataItem.metadata.selectedProvider || dataItem.provider,
            culture: dataItem.culture
        };

        const chunkUploadInfoRequestOptions: GetChunkUploadInfoRequestOptions = {
            data: {
                libraryId
            },
            successCb,
            failureCb,
            progressCb
        };

        const sfData = this.sitefinity.instance.data(typeOptions);
        const chunkUploadSdk = sfData.chunkUpload;

        return chunkUploadSdk.getChunkUploadInfo(chunkUploadInfoRequestOptions);
    }

    uploadChunked(
        subject: Subject<any>,
        dataItem: DataItem,
        chunkUploadInfo: ChunkUploadInfoDTO,
        upload: UploadDTO,
        primitiveFields: any,
        relationFields: any,
        operationName: string,
        directUpload: boolean,
        getItemAfterUpload: boolean
    ) {
        const typeOptions: TypeOptions = {
            entitySet: dataItem.metadata.setName,
            provider: dataItem.metadata.selectedProvider || dataItem.provider,
            culture: dataItem.culture
        };

        const sfData = this.sitefinity.instance.data(typeOptions);
        const chunkUploadSdk = sfData.chunkUpload;

        if (!chunkUploadInfo.ProviderSupportsChunkUpload) {
            throw "The current blob storage provider does not support uploading in chunks.";
        }

        const chunksInfo = chunkUploadSdk.chunkFile(upload.content, chunkUploadInfo.ChunkSize, upload.contentType);
        let isCleanUpChunksRequestSent = false;
        let successfullyUploadedChunks = 0;

        const failedChunksMap = new Map<number, number>();

        let skip = 0;
        let take = chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
        const currentBatch = chunksInfo.chunks.slice(skip, take);

        const handleBatch = (arr: Array<FileUploadChunk>) => {
            arr.forEach(chunk => {
                const parameters: UploadChunkRequestOptions = {
                    data: {
                        fileMimeType: upload.contentType,
                        chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                        chunkSize: chunk.content.size,
                        chunkOrdinal: chunk.ordinal,
                        numberOfChunks: chunksInfo.totalChunksCount,
                        chunkBlob: chunk.content,
                        blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName
                    },
                    successCb: x => {
                        if (x.SuccessfullyUploaded) {
                            successfullyUploadedChunks++;

                            if (successfullyUploadedChunks === skip + chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession && successfullyUploadedChunks < chunksInfo.totalChunksCount) {
                                skip += chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
                                take += chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
                                handleBatch(chunksInfo.chunks.slice(skip, take));
                            }

                            if (successfullyUploadedChunks === chunksInfo.totalChunksCount) {
                                const commitChunksOptions: CommitChunksRequestOptions = {
                                    data: {
                                        chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                                        contentType: upload.contentType,
                                        fileTotalSize: chunksInfo.fileTotalSize,
                                        numberOfChunks: chunksInfo.totalChunksCount,
                                        name: upload.name,
                                        uploadProperties: primitiveFields,
                                        blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName,
                                        itemId: undefined
                                    },
                                    successCb: y => {
                                        const id = y.Id;
                                        SitefinitySdk.associateRelationFieldsSfData(id, relationFields, sfData);

                                        sfData.operation({
                                            key: id,
                                            data: {
                                                action: operationName,
                                                actionParameters: {
                                                    directUpload
                                                }
                                            },
                                            successCb: () => this.markUploadAsSuccessful(subject, dataItem, getItemAfterUpload, id, upload),
                                            failureCb: () => this.failWholeUpload(subject, upload)
                                        });
                                    },
                                    failureCb: () => this.failWholeUpload(subject, upload)
                                };

                                chunkUploadSdk.commitChunks(commitChunksOptions);
                            }
                        }
                    },
                    failureCb: x => {
                        // A bit of hack, if this is "if" is not present there will be as many CleanUpChunks requests
                        // sent as there are ChunkUploadInfoDTO.MaxSimultaneousChunkUploadRequestsPerSession
                        if (isCleanUpChunksRequestSent)
                            return;

                        if (x.FailedChunkOrdinal !== undefined && x.FailedChunkOrdinal !== null && typeof (x.FailedChunkOrdinal) === "number") {
                            const hasChunkFailedPreviously = failedChunksMap.has(x.FailedChunkOrdinal)

                            if (hasChunkFailedPreviously) {
                                let failureCount = failedChunksMap.get(x.FailedChunkOrdinal);

                                if (failureCount === chunkUploadInfo.MaxRetryCountForChunk) {
                                    const cleanUpChunksRequestOptions: CleanUpChunksRequestOptions = {
                                        data: {
                                            chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                                            blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName
                                        },
                                        successCb: () => {
                                            this.failWholeUpload(subject, upload);
                                        }
                                    };

                                    chunkUploadSdk.cleanUpChunks(cleanUpChunksRequestOptions);
                                    isCleanUpChunksRequestSent = true;
                                    return;
                                } else {
                                    failureCount++;
                                    failedChunksMap.set(x.FailedChunkOrdinal, failureCount);
                                }
                            } else {
                                failedChunksMap.set(x.FailedChunkOrdinal, 1)
                            }

                            handleBatch([chunksInfo.chunks[x.FailedChunkOrdinal]]);
                        } else {
                            this.failWholeUpload(subject, upload);
                            return;
                        }
                    },
                    progressCb: ev => {
                        // This is a hack to calculate the progress bar progression correctly
                        // because of the fact that N requests are sent simultaneously in parallel
                        // the progress bar goes back and forth
                        const unlocked = deepClone(ev);
                        unlocked.loaded = successfullyUploadedChunks;
                        this.handleProgress(subject, unlocked, upload);
                    }
                };

                chunkUploadSdk.uploadChunk(parameters);
            });
        }

        handleBatch(currentBatch);
    }

    uploadChunkedWithOperationResult(result: Subject<ItemWithOperationResult>, dataItem: DataItem, chunkUploadInfo: ChunkUploadInfoDTO, fileInfo$: Observable<FileInfo>, primitiveFields: any, relationFields: any, operation: any) {
        const typeOptions: TypeOptions = {
            entitySet: dataItem.metadata.setName,
            provider: dataItem.metadata.selectedProvider || dataItem.provider,
            culture: dataItem.culture
        };

        const sfData = this.sitefinity.instance.data(typeOptions);
        const chunkUploadSdk = sfData.chunkUpload;

        if (!chunkUploadInfo.ProviderSupportsChunkUpload) {
            throw "The current blob storage provider does not support uploading in chunks.";
        }

        fileInfo$.subscribe((fileInfo: FileInfo) => {
            primitiveFields = primitiveFields || {};

            primitiveFields.Height = fileInfo.height;
            primitiveFields.Width = fileInfo.width;
            primitiveFields.PreserveFileName = fileInfo.preserveFileName;


            if (MediaHelpers.isVideoEntity(dataItem) && dataItem.data[Properties.THUMBNAIL_SOURCE]) {
                primitiveFields[Properties.THUMBNAIL_SOURCE] = dataItem.data[Properties.THUMBNAIL_SOURCE];
            }

            const chunksInfo = chunkUploadSdk.chunkFile(fileInfo.content, chunkUploadInfo.ChunkSize, fileInfo.content.type);
            let isCleanUpChunksRequestSent = false;
            let successfullyUploadedChunks = 0;

            const failedChunksMap = new Map<number, number>();

            let skip = 0;
            let take = chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
            const currentBatch = chunksInfo.chunks.slice(skip, take);

            const handleBatch = (arr: Array<FileUploadChunk>) => {
                arr.forEach(chunk => {
                    const parameters: UploadChunkRequestOptions = {
                        data: {
                            fileMimeType: fileInfo.content.type,
                            chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                            chunkSize: chunk.content.size,
                            chunkOrdinal: chunk.ordinal,
                            numberOfChunks: chunksInfo.totalChunksCount,
                            chunkBlob: chunk.content,
                            blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName
                        },
                        successCb: x => {
                            if (x.SuccessfullyUploaded) {
                                successfullyUploadedChunks++;

                                if (successfullyUploadedChunks === skip + chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession && successfullyUploadedChunks < chunksInfo.totalChunksCount) {
                                    skip += chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
                                    take += chunkUploadInfo.MaxSimultaneousChunkUploadRequestsPerSession;
                                    handleBatch(chunksInfo.chunks.slice(skip, take));
                                }

                                if (successfullyUploadedChunks === chunksInfo.totalChunksCount) {
                                    const commitChunksOptions: CommitChunksRequestOptions = {
                                        data: {
                                            chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                                            contentType: fileInfo.content.type,
                                            fileTotalSize: chunksInfo.fileTotalSize,
                                            numberOfChunks: chunksInfo.totalChunksCount,
                                            name: fileInfo.content.name,
                                            uploadProperties: primitiveFields,
                                            blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName,
                                            itemId: dataItem.data.OriginalContentId || dataItem.data.Id
                                        },
                                        successCb: itemData => {
                                            const id = itemData.Id;

                                            SitefinitySdk.associateRelationFieldsSfData(id, relationFields, sfData);

                                            sfData.operation({
                                                key: id,
                                                data: {
                                                    action: operation.Name,
                                                    actionParameters: {
                                                        directUpload: false
                                                    }
                                                },
                                                successCb: x => {
                                                    this.getSingle(
                                                        dataItem,
                                                        {
                                                            key: id,
                                                            successCb: item => {
                                                                const newDataItem = DataItem.from(item, dataItem.metadata, dataItem.provider, dataItem.culture);
                                                                const itemWithOperationResult: ItemWithOperationResult = {
                                                                    dataItem: newDataItem,
                                                                    operationMessage: x.Message,
                                                                    operationData: x,
                                                                    operationResult: x
                                                                }

                                                                result.next(itemWithOperationResult);

                                                                this.dynamicItemStore.notifyItemChange(itemWithOperationResult.dataItem.data.Id, itemWithOperationResult.dataItem, operation.Name);
                                                                this.dynamicItemStore.refreshItem(itemWithOperationResult.dataItem);
                                                            }
                                                        })
                                                }
                                            });
                                        }
                                    };

                                    chunkUploadSdk.commitChunks(commitChunksOptions);
                                }
                            }
                        },
                        failureCb: x => {
                            // A bit of hack, if this is "if" is not present there will be as many CleanUpChunks requests
                            // sent as there are ChunkUploadInfoDTO.MaxSimultaneousChunkUploadRequestsPerSession
                            if (isCleanUpChunksRequestSent)
                                return;

                            if (x.FailedChunkOrdinal !== undefined && x.FailedChunkOrdinal !== null && typeof (x.FailedChunkOrdinal) === "number") {
                                const hasChunkFailedPreviously = failedChunksMap.has(x.FailedChunkOrdinal)

                                if (hasChunkFailedPreviously) {
                                    let failureCount = failedChunksMap.get(x.FailedChunkOrdinal);

                                    if (failureCount === chunkUploadInfo.MaxRetryCountForChunk) {
                                        const cleanUpChunksRequestOptions: CleanUpChunksRequestOptions = {
                                            data: {
                                                chunkedFileUploadSessionId: chunkUploadInfo.ChunkedFileUploadSessionId,
                                                blobStorageProviderName: chunkUploadInfo.BlobStorageProviderName
                                            },
                                            successCb: () => {
                                                // this.failWholeUpload(subject, upload);
                                            }
                                        };

                                        chunkUploadSdk.cleanUpChunks(cleanUpChunksRequestOptions);
                                        isCleanUpChunksRequestSent = true;
                                        return;
                                    } else {
                                        failureCount++;
                                        failedChunksMap.set(x.FailedChunkOrdinal, failureCount);
                                    }
                                } else {
                                    failedChunksMap.set(x.FailedChunkOrdinal, 1)
                                }

                                handleBatch([chunksInfo.chunks[x.FailedChunkOrdinal]]);
                            } else {
                                // this.failWholeUpload(subject, upload);
                                return;
                            }
                        }
                    };

                    chunkUploadSdk.uploadChunk(parameters);
                });
            }

            handleBatch(currentBatch);
        });
    }

    private markUploadAsSuccessful(subject: Subject<any>, dataItem: DataItem, getItemAfterUpload: boolean, id: string, upload: UploadDTO) {
        if (getItemAfterUpload) {
            this.getSingle(dataItem, {
                key: id,
                successCb: (result) => {
                    upload.result = result;
                    upload.success = true;
                    subject.next(upload);
                },
                failureCb: () => {
                    upload.failure = true;
                    subject.next(upload);
                }
            })
        } else {
            upload.result = { Id: id };
            upload.success = true;
            subject.next(upload);
        }
    }

    private getSingle(dataItem: DataItem, parameters: RequestOptionsBase) {
        this.sitefinity.instance
            .data({ entitySet: dataItem.metadata.setName, provider: dataItem.metadata.selectedProvider || dataItem.provider, culture: dataItem.culture })
            .getSingle(parameters);
    }

    private failWholeUpload(subject: Subject<any>, upload: UploadDTO) {
        upload.failure = true;
        subject.next(upload);
    }

    private handleProgress(subject: Subject<any>, event: ProgressEvent | any, upload: UploadDTO) {
        if (event.lengthComputable) {
            upload.loaded = (event.loaded / event.total) * 100 || 1;
            if (event.total === event.loaded) {
                // hardcoded 100 because event.total is the number of chunks
                upload.loaded = 100;
            }
            subject.next(upload);
        }
    }
    //#endregion
}

