import { Component, Input, OnInit } from "@angular/core";
import { DataContext } from "../../models/data-context-component";

@Component({
    selector: "sf-type-info",
    templateUrl: "./type-info.component.html"
})
export class TypeInfoComponent implements OnInit {
    @Input() public context: DataContext;

    public typeTitle: string;
    public providerTitle: string;

    ngOnInit() {
        const dataItem = this.context.dataItem;
        this.typeTitle = dataItem.data.ContentTypeInfo ? dataItem.data.ContentTypeInfo.DisplayName : "";
        this.providerTitle = dataItem.data.ContentTypeInfo ? dataItem.data.ContentTypeInfo.ProviderDisplayName : "";
    }
}
