import { Component, OnInit, HostListener, Inject, ElementRef } from "@angular/core";
import { combineLatest, Observable, ReplaySubject, Subject, of, BehaviorSubject } from "rxjs";
import { WidgetContext, WidgetLocalizationMode } from "./models/widget-context";
import { FeedbackInfo } from "./models/feedback-info";
import { BasicEditorViewComponent } from "./basic-editor.component";
import { CustomViewRegistrationProvider } from "./providers/view-registration.provider";
import { SelectorConstants } from "../html/selector-constants";
import { CloseModalCallback } from "../shared/services/modal-window.service";
import { WidgetEditor, WidgetMetadata, PropertyData, ValidationResult, PropertyMetadata, ComponentMetadata, PropertyValueGroup } from "./interfaces/widget-editor";
import { map, switchMap, tap, debounceTime } from "rxjs/operators";
import { NotifyStatusChange } from "./interfaces/notify-status-change";
import { LoadingContentState } from "../shared/rxjs-extensions/toLoadingState";
import { delayEmission } from "../shared/rxjs-extensions";
import { stringConstants } from "../../common-constants";
import { ActionButtonsStateService } from "../shared/services/action-buttons-state.service";
import { SpecificButtonState, ButtonsState } from "../content/dynamic-modules/components/action-buttons.resolver";
import { ButtonState, ActionButton } from "../shared/components/action-menu/action-menu-model";
import { Operation, OperationItemResult } from "../shared/components/action-menu/operation.model";
import { PropertyEditorOperations, PropertyEditorViewModes, Dictionary, PropertyEditorConstants, PropertyEditorWidgets } from "./property-editor.constants";
import { EditorViewModel } from "./interfaces/widget-editor-view-provider";
import { WINDOW_TOKEN } from "../../window.provider";
import { ZoneEditorContract } from "../pages/services/zone-editor.contract";
import { LoadingState } from "../shared/rxjs-extensions/delayEmission";
import { SiteDataStore } from "../shared/services/metadata/site-data.store";
import { GetWidgetMetadataArgs } from "../pages/services/renderer.types";
import { PropertyValueParserService } from "./services/property-value-parser.service";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { WidgetMetadataMergerService as WidgetMetadataService } from "../pages/services/widget-metadata.service";
import { ChangeLayoutComponent } from "./change-layout.component";

export const LOADING_DELAY = 600;
const FOOTER_DEFAULT_CLASS = "sf-modal-window__buttons";
const WIDGET_LABEL_PROP_NAME = "SfWidgetLabel";
const CHANGE_DIRECTION_CLASS = "-change-direction";

@Component({
    selector: "sf-widget-editor",
    templateUrl: "./widget-editor.component.html",
    providers: [ActionButtonsStateService]
})
export class WidgetEditorComponent extends SfRxBase implements OnInit, CloseModalCallback {
    public feedback = new FeedbackInfo();
    public footerButtonsClass: string = FOOTER_DEFAULT_CLASS;
    public widgetEditorComponent$: Subject<EditorViewModel> = new ReplaySubject(1);
    public hasAdvancedOptions: Subject<boolean> = new ReplaySubject(1);
    public context: WidgetContext;
    public focusTriggeringSubscription = new BehaviorSubject(false);

    protected operations: Observable<Operation[]>;
    protected buttonsState$: Observable<ButtonsState>;

    private loading: Subject<LoadingContentState<void>> = new ReplaySubject(1);
    private saving: Subject<LoadingState> = new ReplaySubject(1);
    private changeDirection: Subject<Boolean> = new ReplaySubject(1);
    private editorViewInstance: WidgetEditor;
    private _closeModalCallback: (data: OperationItemResult) => void;
    private widgetProps: WidgetMetadata;
    private widgetViewComponent: WidgetEditor;

    @HostListener("window:keydown", ["$event"]) keyEvent(e: KeyboardEvent) {
        const key = e.keyCode || e.which;
        const commandKey = e.ctrlKey && e.altKey;

        // C
        if (commandKey && (key === 67 || e.key === "c")) {
            e.preventDefault();
            this.windowProvider.navigator.clipboard.writeText(JSON.stringify(this.widgetProps.propertyValues));
        }

        // V
        if (commandKey && (key === 86 || e.key === "v")) {
            e.preventDefault();

            this.windowProvider.navigator.clipboard.readText().then(
                propNameValues => {
                    this.widgetViewComponent.setValues(JSON.parse(propNameValues));
                });
        }
    }

    constructor(
        private zoneEditorContract: ZoneEditorContract,
        private widgetMetadataService: WidgetMetadataService,
        private viewsProvider: CustomViewRegistrationProvider,
        private buttonStateService: ActionButtonsStateService,
        private siteDataStore: SiteDataStore,
        private propertyValueParserService: PropertyValueParserService,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        private elementRef: ElementRef) {
        super();
    }

    ngOnInit() {
        const loadingSubscription = this.loading.pipe(delayEmission(LOADING_DELAY), map(x => x.isLoading), tap((val => {
            this.feedback.showViewLoadingIndicator = val;
        }))).subscribe();
        this.registerSubscription(loadingSubscription);

        this.loading.next({ isLoading: true, content: null });
        const initSubscription = combineLatest(this.initializeView(), this.initializeViewData()).subscribe(([widgetView, widgetProps]) => {
            widgetView.componentData.afterComponentInit = (component: WidgetEditor) => {
                this.focusTriggeringSubscription.next(true);
                this.editorViewInstance = component;
                this.widgetProps = widgetProps;
                const initPropsSubscription = component.initialize(widgetProps).subscribe(() => {
                    this.feedback.reset();
                    this.loading.next({ isLoading: false, content: null });
                }, (err) => {
                    this.feedback.setError(err);
                });
                this.registerSubscription(initPropsSubscription);

                const anyComponent = component as any;
                if (anyComponent.notifyStatusChange$) {
                    const notifyChangesSubscription = (anyComponent as NotifyStatusChange).notifyStatusChange$.subscribe((feedback) => { this.feedback = feedback; });
                    this.registerSubscription(notifyChangesSubscription);
                }
                this.configureActions(component, widgetProps);
                this.widgetViewComponent = component;
            };
            this.widgetEditorComponent$.next(widgetView);
        }, (err) => {
            this.feedback.setError(err);
        });
        this.registerSubscription(initSubscription);
    }

    setCloseModalCallback(closeModalCallback: (data: any) => void): void {
        this._closeModalCallback = closeModalCallback;
    }

    onActionButtonClicked(button: ActionButton): void {
        const actionName = button.name;

        switch (actionName) {
            case PropertyEditorOperations.SAVE:
                const saveLocalizationMode = this.context.localizationMode === WidgetLocalizationMode.AlwaysSaveAllTranslations ? PropertyLocalizationType.AllTranslations : PropertyLocalizationType.CurrentTranslationOnly;
                const currentSaveMode = this.context.culture ? saveLocalizationMode : PropertyLocalizationType.Default;
                this.saveContentClick(currentSaveMode, actionName);
                break;
            case PropertyEditorOperations.SAVE_ALL:
                this.saveContentClick(PropertyLocalizationType.AllTranslations, actionName);
                break;
            case PropertyEditorOperations.CANCEL:
                this.cancelClick();
                break;
            default:
                this.saveContentClick(0, actionName);
        }
    }

    focusOut() {
        if (this.context.isQuickEdit) {
            this.cancelClick();
        }
    }

    ondragstart(event) {
        event.preventDefault();
        event.stopPropagation();
    }

    onclick(event) {
        if (this.context.isQuickEdit) {
            event.stopPropagation();
        }
    }

    private configureActions(component: WidgetEditor, widgetProps: WidgetMetadata) {
        let operations: Array<Operation>;
        this.footerButtonsClass = FOOTER_DEFAULT_CLASS;

        const getActionsFuncName = "getActions";
        const footerActions = component[getActionsFuncName] ? component[getActionsFuncName]() : {};
        if (footerActions.cssClass)
            this.footerButtonsClass += stringConstants.INTERVAL + footerActions.cssClass;

        if (footerActions.operations) {
            operations = footerActions.operations;
        } else {
            operations = new Array<Operation>();
            operations.push(this.createOperation(SelectorConstants.SAVE, PropertyEditorOperations.SAVE, -1));
            if (widgetProps.propertyLocalizationMode === "AllTranslations" && this.context.localizationMode === WidgetLocalizationMode.Both)
                operations.push(this.createOperation(SelectorConstants.SAVE_ALL_TRANSLATIONS, PropertyEditorOperations.SAVE_ALL, 0));
        }

        const operationTitle = operations.length === 0 ? SelectorConstants.CLOSE : SelectorConstants.CANCEL;
        operations.push(this.createOperation(operationTitle, SelectorConstants.CANCEL, 0));
        this.operations = of(operations);

        this.updateActionButtonsState(null, ButtonState.Default);
        this.buttonsState$ = this.buttonStateService.getState$();
    }

    private createOperation(title: string, name: string, ordinal: number): Operation {
        return {
            Title: title,
            Category: { Name: "default" },
            Name: name,
            Ordinal: ordinal,
            Description: stringConstants.EMPTY_STRING,
            Link: stringConstants.EMPTY_STRING,
            Parameters: [{}],
            RequiresConfirmation: false
        };
    }

    private saveContentClick(saveToAllTranslations: number, actionName: string) {
        if (this.editorViewInstance) {
            this.updateActionButtonsState({ name: actionName, state: ButtonState.Loading }, ButtonState.Disabled);
            const validationSubscription = this.editorViewInstance.validate().subscribe((result: ValidationResult) => {
                if (result && result.isValid) {
                    const saveSubscription = this.editorViewInstance.actionExecuting({ processChanges: true })
                        .pipe(switchMap(() => this.saveProperties(this.editorViewInstance, saveToAllTranslations)))
                        .subscribe(
                            () => this.onComplete(actionName),
                            err => this.onError(actionName, err)
                        );
                    this.registerSubscription(saveSubscription);
                } else {
                    const errorMessage = result && result.message != null ? result.message : "The form is not valid!";
                    this.onError(actionName, errorMessage);
                }
            },
                (err) => this.onError(actionName, err));
            this.registerSubscription(validationSubscription);
        }
    }

    private cancelClick() {
        if (this.editorViewInstance) {
            this.focusTriggeringSubscription.next(false);
            const cancelSubscription = this.editorViewInstance.actionExecuting({ processChanges: false })
                .subscribe({
                    error: err => this.onError(PropertyEditorOperations.CANCEL, err),
                    complete: () => this.onComplete(PropertyEditorOperations.CANCEL)
                });

            this.registerSubscription(cancelSubscription);
        }
    }

    private updateActionButtonsState(primary: SpecificButtonState, stateForOthers?: ButtonState): Observable<void> {
        return this.buttonStateService.updateActionButtonsState(primary, stateForOthers);
    }

    private initializeViewData(): Observable<WidgetMetadata> {
        this.feedback.reset();

        const properties$ = this.zoneEditorContract.getWidgetPropertyValues(this.context.entityData, this.context.widgetId, this.context.segmentId, this.context.widgetSegmentId)
            .pipe(map((response: PropertyValueGroup) => {
                if (response && response.Properties) {
                    const associativeProperties = this.toAssociativeArray(response.Properties);

                    return {
                        caption: response.Caption,
                        properties: associativeProperties,
                        propertyLocalizationMode: response.PropertyLocalizationMode
                    };
                }
            }));

        const componentMetaData$ = new ReplaySubject<ComponentMetadata>();
        this.siteDataStore.getValue().subscribe((siteData) => {
            const getWidgetMetadataArgs: GetWidgetMetadataArgs = {
                dataItem: this.context.entityData,
                widgetKey: this.context.widgetId,
                widgetName: this.context.widgetName,
                siteId: siteData.Id
            };

            this.widgetMetadataService.getWidgetMetadata(getWidgetMetadataArgs).subscribe((response) => {
                if (response) {
                    if (this.getModule(PropertyEditorViewModes.ADVANCED, response.PropertyMetadata)) {
                        this.hasAdvancedOptions.next(true);
                    }

                    const sectionForCurrentMode = this.getSectionsPerMode(this.context.sectionName, response.PropertyMetadata) || [];
                    response.PropertyMetadata = [sectionForCurrentMode];

                    componentMetaData$.next(response);
                }
            });
        });

        return combineLatest(componentMetaData$, properties$).pipe(map(x => {
            const controlMetadata = x[0];
            const controlValues = x[1];

            const caption = controlValues.caption || controlMetadata.Caption;
            if (caption) {
                const labelProp = controlMetadata.PropertyMetadataFlat.find(x => x.Name === WIDGET_LABEL_PROP_NAME);
                if (labelProp) {
                    labelProp.DefaultValue = caption;
                }
            }

            const componentVales = this.setDefaultProperties(controlValues.properties, controlMetadata.PropertyMetadataFlat);

            return <WidgetMetadata> {
                propertyLocalizationMode: controlValues.propertyLocalizationMode,
                propertyMetadata: controlMetadata.PropertyMetadata[0].Sections,
                propertyMetadataFlat: controlMetadata.PropertyMetadataFlat,
                propertyValues: componentVales,
                name: controlMetadata.Name,
                caption
            };
        }));
    }

    private initializeView(): Observable<EditorViewModel> {
        const componentData$ = new ReplaySubject<EditorViewModel>(1);

        const quickSaveSubscription = this.saving.pipe(debounceTime(500)).subscribe(() => {
            if (this.context.isQuickEdit) {
                const saveLocalizationMode = this.context.localizationMode === WidgetLocalizationMode.AlwaysSaveAllTranslations ? PropertyLocalizationType.AllTranslations : PropertyLocalizationType.CurrentTranslationOnly;
                const currentSaveMode = this.context.culture ? saveLocalizationMode : PropertyLocalizationType.Default;

                this.saveContentClick(currentSaveMode, PropertyEditorOperations.SAVE);
            }
        });
        const changeDirectionSubscription = this.changeDirection.subscribe((changeDirection) => {
            if (changeDirection) {
                this.elementRef.nativeElement.classList.add(CHANGE_DIRECTION_CLASS);
            } else {
                this.elementRef.nativeElement.classList.remove(CHANGE_DIRECTION_CLASS);
            }
        });
        this.registerSubscription(quickSaveSubscription);
        this.registerSubscription(changeDirectionSubscription);

        if (this.context.sectionName === PropertyEditorViewModes.ADVANCED) {
            componentData$.next({
                componentData: {
                    type: BasicEditorViewComponent,
                    properties: {
                        fieldChange: () => this.saving.next({ isLoading: true }),
                        headingPrefix: PropertyEditorConstants.ADVANCED_SETTINGS_LABEL
                    }
                }
            });
        } else if (this.context.viewName === PropertyEditorViewModes.CHANGE_LAYOUT) {
            componentData$.next({
                componentData: {
                    type: ChangeLayoutComponent,
                    properties: {
                        fieldChange: () => this.saving.next({ isLoading: true }),
                        changeDirection: () => this.changeDirection.next(true)
                    }
                }
            });
        } else {
            const viewKey = this.context.viewKey;
            const viewsSubscription = this.viewsProvider.getView(viewKey).subscribe(viewInfo => {
                const properties = {
                    fieldChange: () => this.saving.next({ isLoading: true })
                };

                if (!viewInfo) {
                    viewInfo = {};
                }

                if (!viewInfo.componentData) {
                    viewInfo.componentData = {
                        type: BasicEditorViewComponent
                    };
                }

                viewInfo.componentData.properties = properties;
                componentData$.next(viewInfo);
            });

            this.registerSubscription(viewsSubscription);
        }

        return componentData$.pipe(tap((x) => {
            if (!x.componentData.properties) {
                x.componentData.properties = {};
            }

            x.componentData.properties.context = this.context;
        }));
    }

    private saveProperties(editorViewInstance: WidgetEditor, saveToAllTranslations: number): Observable<void> {
        const properties = editorViewInstance.getModifiedProperties();
        if (properties && properties.length > 0) {
            const metaPropMap: { [key: string]: PropertyMetadata } = {};
            this.widgetProps.propertyMetadataFlat.forEach((prop => {
                metaPropMap[prop.Name] = prop;
            }));

            this.propertyValueParserService.stringifyProperties(properties, metaPropMap);
            const flatMetadata = this.widgetProps.propertyMetadataFlat.map(p => {
                return { Name: p.Name, Title: p.Title, Type: p.Type, DefaultValue: p.DefaultValue, Properties: (<any>p).Properties};
            });
            const propertyValueGroup: PropertyValueGroup = { ComponentId: this.context.widgetId, Properties: properties, PropertyMetadata: flatMetadata, PropertyLocalizationMode: saveToAllTranslations.toString() };

            if (this.context.widgetName === PropertyEditorWidgets.SECTION) {
                const labelProp = properties.find(p => p.Name === "Labels");
                if (labelProp && labelProp.Value) {
                    const sectionLabels = propertyValueGroup.Caption = JSON.parse(labelProp.Value).Section;
                    if (sectionLabels) {
                        propertyValueGroup.Caption = sectionLabels.Label;
                    }
                }
            } else {
                const labelProp = properties.find(p => p.Name === WIDGET_LABEL_PROP_NAME);
                if (labelProp) {
                    propertyValueGroup.Caption = labelProp.Value;
                    const labelIndex = propertyValueGroup.Properties.indexOf(labelProp);
                    propertyValueGroup.Properties.splice(labelIndex, 1);
                }
            }

            return this.zoneEditorContract.setWidgetPropertyValues(this.context.entityData, propertyValueGroup, this.context.segmentId, this.context.widgetSegmentId);
        } else {
            return of(null);
        }
    }

    private onComplete(actionName: string) {
        if (actionName !== PropertyEditorOperations.CANCEL) {
            const closeModalFunction = () => {
                this._closeModalCallback({Success: true, SourceOperation: {Name: actionName}});
            };

            if (this.context.isQuickEdit) {
                closeModalFunction();
            } else {
                this.updateActionButtonsState({ name: actionName, state: ButtonState.Checked }, ButtonState.Default);

                const updateActionSubscription = this.updateActionButtonsState(null, ButtonState.Default).subscribe(() => {
                    closeModalFunction();
                });
                this.registerSubscription(updateActionSubscription);
            }
        } else {
            this._closeModalCallback({Success: true, SourceOperation: {Name: actionName}});
        }

        this.feedback.showError = false;
    }

    private onError(actionName: string, message: string) {
        this.updateActionButtonsState({ name: actionName, state: ButtonState.Default }, ButtonState.Default);
        this.feedback.setError(message);
    }

    private setDefaultProperties(componentProperties: Dictionary, propertyMetadata: Array<PropertyMetadata>): Dictionary {
        propertyMetadata.forEach(prop => {
            if (typeof componentProperties[prop.Name] === "undefined" && prop.DefaultValue) {
                componentProperties[prop.Name] = prop.DefaultValue;
            }
        });

        return componentProperties;
    }

    private toAssociativeArray(properties: PropertyData[]): Dictionary {
        const widget = {};
        for (let i = 0; i < properties.length; i++) {
            const prop = properties[i];
            widget[prop.Name] = prop.Value;
        }
        return widget;
    }

    private getSectionsPerMode(mode: string, properties: any[]) {
        return this.getModule(mode, properties);
    }

    private getModule(mode: string, properties: any[]) {
        return properties.find(view => view["Name"] === mode);
    }
}

export enum PropertyLocalizationType {
    Default = 0,
    AllTranslations = 1,
    CurrentTranslationOnly = 2
}
