import { Component, Inject, Input, OnDestroy, OnInit, ViewChild } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { ComponentData, SfRxBase, stringConstants } from "@progress/sitefinity-component-framework";
import { catchError, combineLatest, empty, map, take } from "rxjs";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../api/v1/notifications/notification.service";
import { cloneObject, getCssVariableValueAsNumber } from "../../../utils";
import { CSS_VARIABLES, NOTIFICATION_DURATION_DEFAULT, NOTIFICATION_DURATION_INFINITE, QUERY_PARAMS } from "../../content/constants";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { SelectorConstants } from "../../html/selector-constants";
import { ParentSelectorSettings } from "../../parent-selector/parent-selector-settings";
import { ParentSelectorComponent, SelectedTaxaModel } from "../../parent-selector/parent-selector.component";
import { TaxonomySettings } from "../../taxonomy";
import { BasicEditorViewComponent } from "../../widget-editor/basic-editor.component";
import { PropertyMetadata, SectionData, ValidationResult, WidgetMetadata } from "../../widget-editor/interfaces/widget-editor";
import { PropertyValueParserService } from "../../widget-editor/services/property-value-parser.service";
import { ButtonState } from "../components/action-menu/action-menu-model";
import { ActionButtonsStateService } from "../services/action-buttons-state.service";
import { FieldError } from "../services/errors/field-error";
import { ValidationError } from "../services/errors/validation-error";
import { ENTITY_SET } from "../services/metadata/meta-data-constants";
import { Button, CancelButton, ClickData, ClickResult, ConfirmButton, DialogData, ModalWindowService } from "../services/modal-window.service";
import { NOTIFICATION_LOOKS } from "../services/notification/notification-data";
import { BasicNotificationInfo } from "../services/notification/notification-info";
import { CompositeConfigExtender } from "../services/config/composite-config-extender";
import { LOCAL_STORAGE, StorageService } from "../services/storage.service";
import { ERROR_CODES } from "../services/errors/error-code.constants";
import { ROUTE_PATHS } from "../../../constants/route-paths";
import { StatusCodes } from "http-status-codes";

const NOT_INHERITED_SETTINGS_MESSAGE = "Settings for site {{placeholder}} are different from the settings for All sites.";
const INHERIT_FROM_ALL_SITES_PROP_NAME = "InheritFromAllSites";
const SITE_SELECTOR_NAME_ALL_SITES = "All sites";
const SITE_SELECTOR_NAME_SELECTED_SITE = "Selected site";
const SITE_SELECTOR_VALUE_SELECTED_SITE = "selectedSite";

const BUTTON_TITLE = "Save changes";
const BUTTON_LOADER_LOOK = "transparent";

const CONFIG_NOTIFICATION_FILTER = "config-settings";
export const BASE_FORM_CLASSES = "sf-form -sf-centered-box -sf-pb-zero";

@Component({
    providers: [ActionButtonsStateService],
    selector: "sf-config-settings",
    templateUrl: "./config-settings-component.html"
})
export class ConfigSettingsComponent extends SfRxBase implements OnInit, OnDestroy {
    @Input() configKey: string;
    @Input() title: string;

    editorComponentData: ComponentData;
    fields: Array<SectionData>;
    editorComponent: BasicEditorViewComponent;
    siteSelectorSettings: ParentSelectorSettings;
    settingsNotificationMessage: string;
    showNotificationMessage = false;
    notificationFilter = CONFIG_NOTIFICATION_FILTER;
    saveChangesButton: ConfirmButton;
    canPersistSiteSpecificValues: boolean = false;
    contentLoaderHeight: number = getCssVariableValueAsNumber(CSS_VARIABLES.EDITOR_INLINE_HEIGHT_LONG, "sf-app") || 300;
    formCssClasses: string;
    showNotification: boolean;

    @ViewChild("siteSelectorComponent") private siteSelectorComponent: ParentSelectorComponent;

    private selectedSiteId: string = stringConstants.DEFAULT_GUID;
    private selectedSiteName: string;
    private areInheritanceChangesMade: boolean;
    private allSitesConfigValues: any;

    constructor(
        private route: ActivatedRoute,
        private dynamicItemService: DynamicItemService,
        protected modalService: ModalWindowService,
        private buttonStateService: ActionButtonsStateService,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        private propertyValueParserService: PropertyValueParserService,
        private configExtender: CompositeConfigExtender,
        @Inject(LOCAL_STORAGE) protected storage: StorageService,
        private router: Router) {
        super();
        this.saveChangesButton = new ConfirmButton(BUTTON_TITLE);
    }

    ngOnInit(): void {
        this.registerSubscription(this.buttonStateService.getState$().subscribe((state) => {
            switch (state.stateForOthers) {
                case ButtonState.Default:
                    this.toggleButtonLoading(null, false, false);
                    break;
                case ButtonState.Loading:
                    this.toggleButtonLoading(BUTTON_LOADER_LOOK, true, true);
                    break;
                case ButtonState.Checked:
                    this.toggleButtonLoading(null, true, true);
                case ButtonState.Disabled:
                default:
                    break;
            }
        }));

        this.registerSubscription(this.route.queryParams.pipe(map(params => params[QUERY_PARAMS.TYPE])).subscribe((queryParamValue) => {
            if (queryParamValue) {
                this.configKey = queryParamValue;
            }

            this.selectedSiteId = stringConstants.DEFAULT_GUID;
            this.editorComponent = null;
            this.editorComponentData = null;
            this.canPersistSiteSpecificValues = false;
            this.initComponent();
        }));
    }

    initComponent(): void {
        this.formCssClasses = this.configExtender.getFormClasses();
        this.areInheritanceChangesMade = false;
        this.showNotificationMessage = this.selectedSiteId !== stringConstants.DEFAULT_GUID;
        this.initializeSettings(this.selectedSiteId);
        this.initData(this.selectedSiteId);
    }

    getPropertyValues(): any[] {
        if (this.editorComponent) {
            const properties = this.editorComponent.getModifiedProperties();
            this.configExtender.modifyPropertyValuesBeforeSave(properties);
            if (properties && properties.length > 0) {
                const metaPropMap: { [key: string]: PropertyMetadata } = {};
                this.getMetadata().forEach((prop => {
                    metaPropMap[prop.Name] = prop;
                }));

                this.propertyValueParserService.stringifyProperties(properties, metaPropMap);
            }

            let inheritsSettingsFromAllSites = true;
            if (this.selectedSiteId !== stringConstants.DEFAULT_GUID && this.allSitesConfigValues) {
                for (const property of properties) {
                    if (this.allSitesConfigValues[property.Name] != property.Value &&
                        this.allSitesConfigValues[property.Name] != JSON.stringify(property.Value)) {
                        inheritsSettingsFromAllSites = false;
                        break;
                    }
                }
            }

            properties.push({
                Name: INHERIT_FROM_ALL_SITES_PROP_NAME,
                Value: inheritsSettingsFromAllSites.toString()
            });

            this.showNotificationMessage = !inheritsSettingsFromAllSites;

            return properties;
        }

        return [];
    }

    arePropertiesChanged(): boolean {
        let changed = this.areInheritanceChangesMade;
        if (!changed && this.editorComponent) {
            const props = this.editorComponent.getModifiedProperties();
            changed = props && props.length > 0;
        }

        return changed;
    }

    onHierarchicalTaxaSelected(selectedTaxa: SelectedTaxaModel): void {
        let siteId = stringConstants.DEFAULT_GUID;
        if (!selectedTaxa) {
            this.selectedSiteName = stringConstants.EMPTY_STRING;
        } else {
            siteId = selectedTaxa.id;
            this.selectedSiteName = selectedTaxa.name;
        }

        this.selectedSiteId = siteId;
        this.initData(this.selectedSiteId);
    }

    inheritanceButtonClick() {
        this.showNotificationMessage = false;
        this.areInheritanceChangesMade = true;
        this.initData(stringConstants.DEFAULT_GUID);
    }

    onSaveChangesClick(): void {
        this.showNotification = true;
        this.editorComponent.validate().pipe(take(1)).subscribe((result: ValidationResult) => {
            if (result && result.isValid) {
                try {
                    const propertyValues = this.getPropertyValues();
                    this.registerSubscription(this.buttonStateService.updateActionButtonsState(null, ButtonState.Loading).subscribe(() => {
                        this.saveChanges(propertyValues);
                    }));
                } catch (ex) {
                    if (ex instanceof ConfigValidationError) {
                        const validationError = new ValidationError({ code: ERROR_CODES.VALIDATION, message: ex.message, status: 0 });
                        const validationErrorClone = cloneObject(validationError);
                        validationError.fieldErrors = [new FieldError(ex.propertyName, validationErrorClone)];
                        this.editorComponent?.showValidationErrors(validationError);
                    }
                }
            }
        });
    }

    private saveChanges(propertyValues: any[]): void {
        this.dynamicItemService.executeUnboundFunction(`Default.SetConfigValues()`, {
            data: {
                configDto: {
                    ConfigKey: this.configKey,
                    Properties: propertyValues
                }
            },
            provider: null,
            culture: null
        }, this.selectedSiteId).subscribe((result: any) => {
            this.areInheritanceChangesMade = false;
            let feedbackAction = null;
            const notificationData = this.getBasicNotificationInfo(result.Message, result.Success);

            if (result.Success) {
                feedbackAction = () => {
                    this.editorComponent?.editableFieldsComponent?.reset();
                    this.notificationService.publishBasicNotification(notificationData);
                };

                this.buttonStateService.updateActionButtonsState(null, ButtonState.Checked);
            } else {
                const validationError = new ValidationError({ code: ERROR_CODES.VALIDATION, message: result.Message, status: 0 });

                if (result.PropertyName) {
                    const validationErrorClone = cloneObject(validationError);
                    validationError.fieldErrors = [new FieldError(result.PropertyName, validationErrorClone)];
                    feedbackAction = () => this.editorComponent?.showValidationErrors(validationError);
                } else {
                    feedbackAction = () => this.notificationService.publishBasicNotification(notificationData);
                }
            }

            this.registerSubscription(this.buttonStateService.updateActionButtonsState(null, ButtonState.Default).subscribe(feedbackAction));
        }, error => {
            this.notificationService.publishBasicNotification(this.getBasicNotificationInfo(error.message, false));
            this.buttonStateService.updateActionButtonsState(null, ButtonState.Default);
        });
    }

    private initializeSettings(siteId: string): void {
        const taxonomySettings = new TaxonomySettings("sitesSelector", false);
        taxonomySettings.type = ENTITY_SET.SITES;
        taxonomySettings.customShowAllTaxaFunction = this.showAllSites.bind(this);
        taxonomySettings.removable = false;
        this.siteSelectorSettings = new ParentSelectorSettings("parentSelector", false);
        this.siteSelectorSettings.hierarchicalTaxaSettings = taxonomySettings;
        this.siteSelectorSettings.choiceOptions = [];
        this.siteSelectorSettings.choiceOptions.push({
            Name: SITE_SELECTOR_NAME_ALL_SITES,
            Value: stringConstants.EMPTY_STRING
        });
        this.siteSelectorSettings.choiceOptions.push({
            Name: SITE_SELECTOR_NAME_SELECTED_SITE,
            Value: SITE_SELECTOR_VALUE_SELECTED_SITE
        });

        if (siteId !== stringConstants.DEFAULT_GUID) {
            this.siteSelectorSettings.defaultValue = SITE_SELECTOR_VALUE_SELECTED_SITE;
            this.siteSelectorComponent.writeValue(siteId);
        } else if (this.siteSelectorComponent) {
            this.siteSelectorComponent.setSiteId(null);
        }

        // false so that the show all sites dialog can have a heading "Select a site" instead of "Select a parent site"
        this.siteSelectorSettings.isParentSelection = false;
    }

    private initData(siteId: string): void {
        this.storage.setItem("sf_config_settings_site_id", siteId);
        this.editorComponentData = null;
        this.showNotificationMessage = false;

        this.initConfigData(siteId, (configMetadata: ConfigMetadata, values: any) => {
            const settingsForSpecificFields: any = this.getSettingsForSpecificSites(values);
            this.settingsNotificationMessage = NOT_INHERITED_SETTINGS_MESSAGE.replace("{{placeholder}}", this.selectedSiteName);
            this.fields = configMetadata.Sections;
            this.canPersistSiteSpecificValues = configMetadata.CanPersistSiteSpecificValues;

            const modifiedValues = this.configExtender.getModifiedValuesForVisualization(values);
            this.setEditorComponentData(modifiedValues, this.fields, settingsForSpecificFields);
        });
    }

    private initConfigData(siteId: string, callback: (configMetadataParam: ConfigMetadata, valuesParam: any) => void) {
        if (siteId !== stringConstants.DEFAULT_GUID) {
            this.cacheConfigValuesForAllSites();
        }

        const getConfigMetadata$ = this.dynamicItemService.executeUnboundFunction(`Default.GetConfigMetadata(configKey='${this.configKey}')`, null, siteId);
        const getConfigValues$ = this.dynamicItemService.executeUnboundFunction(`Default.GetConfigValues(configKey='${this.configKey}')`, null, siteId);
        combineLatest([getConfigMetadata$, getConfigValues$]).pipe(catchError(error => {
            if (error.statusCode === StatusCodes.FORBIDDEN) {
                this.router.navigate([ROUTE_PATHS.ACCESS_DENIED]);
                return empty();
            }

            throw error;
        })).subscribe((data: [ConfigMetadata, any]) => {
            const [configMetadata, values] = data;

            if (siteId === stringConstants.DEFAULT_GUID) {
                this.allSitesConfigValues = values;
            }

            callback(configMetadata, values);
        });
    }

    private setEditorComponentData(values: any, fields: SectionData[], settingsForSpecificFields: any) {
        const editorMetadata: WidgetMetadata = {
            propertyValues: values,
            propertyMetadata: fields,
            propertyMetadataFlat: [],
            propertyLocalizationMode: null,
            name: null,
            caption: null
        };

        this.editorComponentData = {
            type: BasicEditorViewComponent,
            afterComponentInit: (component: BasicEditorViewComponent) => {
                component.initialize(editorMetadata).subscribe(() => {
                    setTimeout(() => {
                        this.editorComponent = component;
                    }, 0);
                });
            },
            properties: {
                context: {
                    isQuickEdit: false,
                    sectionName: "ConfigSettingsSection",
                    widgetName: ""
                },
                showMainHeading: false,
                headingPrefix: this.title,
                shouldHaveTopPadding: false,
                shouldTextAreasBeResizable: true,
                settingsForSpecificFields: settingsForSpecificFields
            }
        };

        if (this.formCssClasses !== undefined) {
            this.editorComponentData.properties.baseCssClass = `${BASE_FORM_CLASSES} ${this.formCssClasses}`;
        }
    }

    private showAllSites(componentData: ComponentData): void {
        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_SELECTED, (data: ClickData) => {

                if (data.component.selected && data.component.selected.length > 0) {
                    this.siteSelectorComponent.onHierarchicalTaxaSelect(data.component.selected[0].Id, data.component.selected[0].Name);
                }

                return new ClickResult(true, true);
            }),
            new CancelButton(SelectorConstants.CANCEL, (data: ClickData) => {
                return new ClickResult(true, true);
            })
        ];

        const dialogData = new DialogData(componentData, null, buttons, null, "-bottom");

        this.modalService.setMapping(dialogData, "sites");
        this.modalService.show("sites", this.route);
    }

    private cacheConfigValuesForAllSites() {
        this.dynamicItemService.executeUnboundFunction(`Default.GetConfigValues(configKey='${this.configKey}')`, null, stringConstants.DEFAULT_GUID).subscribe(values => {
            this.allSitesConfigValues = values;
        });
    }

    private getSettingsForSpecificSites(configValues: { [key: string]: any }): any {
        const settingsForSpecificFields: any = this.configExtender.getSettingsForSpecificFields(configValues);
        if (this.allSitesConfigValues) {
            Object.keys(this.allSitesConfigValues).forEach(field => {
                if (configValues[field] !== this.allSitesConfigValues[field]) {
                    this.showNotificationMessage = true;
                    if (!settingsForSpecificFields.hasOwnProperty(field)) {
                        settingsForSpecificFields[field] = {};
                    }

                    settingsForSpecificFields[field].inlineDescription = "(for current site)";
                }
            });
        }

        return settingsForSpecificFields;
    }

    private getMetadata(): PropertyMetadata[] {
        const metaProp = this.fields.flatMap(p => p.Properties);
        return metaProp;
    }

    private toggleButtonLoading(loader: string, checked: boolean, disabled: boolean): void {
        this.saveChangesButton.loader.next(loader);
        this.saveChangesButton.checked.next(checked);
        this.saveChangesButton.disabled.next(disabled);
    }

    private getBasicNotificationInfo(message: string, success: boolean): BasicNotificationInfo {
        const notificationData: BasicNotificationInfo = {
            message: message,
            look: success ? NOTIFICATION_LOOKS.SUCCESS : NOTIFICATION_LOOKS.ERROR,
            duration: success ? NOTIFICATION_DURATION_DEFAULT : NOTIFICATION_DURATION_INFINITE,
            filterParam: CONFIG_NOTIFICATION_FILTER,
            closeButton: !success
        };

        return notificationData;
    }
}

export class ConfigValidationError {
    constructor(public propertyName: string, public message: string) {

    }
}

interface ConfigMetadata {
    CanPersistSiteSpecificValues: boolean;
    InheritsSettingsFromAllSites: boolean;
    Sections: SectionData[];
}
