import { Entity } from "../../api";
import { ENTITY_SET } from "../shared/services/metadata/meta-data-constants";

export class FormHelpers {
    static isFormResponseItem(entity: Entity) {
        return entity.parent === ENTITY_SET.FORMS;
    }

    static isFormResponseType(entitySet: string) {
        return entitySet.indexOf(ENTITY_SET.FORM_RESPONSES) != -1
    }
}
