import { SAME_TAB_TARGET } from "./../../../../../common-constants";
import { WINDOW_TOKEN } from "./../../../../../window.provider";
import { Operation } from "./../../../../shared/components/action-menu/operation.model";
import { Component, Input, Inject, OnInit, Injector } from "@angular/core";
import { TokenData } from "@progress/sitefinity-component-framework";
import { Command } from "../../../../shared/commands/command";
import { ActivatedRoute } from "@angular/router";
import { AppStore } from "../../../../../services/store/app-store";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../../services/store/actions/actions.sidebar";

const RECYCLE_BIN_OPERATION_NAME: string = "RecycleBin";
const RECYCLE_BIN_OPERATION_CSS_CLASS: string = "-sf-mt-2xs";

export interface SettingsSidebarSection {
    operations: Operation[],
    title: string;
    ordinal: number;
}

interface SectionViewModel {
    title: string;
    settings: ListItemSidebarSetting[];
}

@Component({
    templateUrl: "./list-item-settings-sidebar.component.html"
})
export class ListItemSettingsSidebarComponent implements OnInit {
    @Input() title: string;
    @Input() sections: SettingsSidebarSection[];

    sectionViewModels: SectionViewModel[] = [];
    selectedSettingName: string;

    constructor(@Inject(WINDOW_TOKEN) private window: Window, private injector: Injector, private route: ActivatedRoute, private store: AppStore) {
    }

    ngOnInit () {
        this.sectionViewModels = this.sections
            .sort((x, y) => x.ordinal - y.ordinal)
            .map(s => {
                const settings: ListItemSidebarSetting[] = s.operations.map(o => ({
                    title: o.Title,
                    name: o.Name,
                    link: o.Link,
                    css: o.Name === RECYCLE_BIN_OPERATION_NAME ? RECYCLE_BIN_OPERATION_CSS_CLASS : null,
                    token: o.token,
                    ordinal: o.Ordinal,
                    icon: o.context ? o.context.icon : null
                }))
                .sort((x, y) => x.ordinal - y.ordinal);

                const viewModel: SectionViewModel = {
                    title: s.title,
                    settings
                };

                return viewModel;
            });
    }

    onNavigateToSettings(setting: ListItemSidebarSetting) {
        if (setting.token) {
            const command = this.injector.get(setting.token.type) as Command;
            command.execute({
                currentRoute: this.route,
                model: null,
                data: setting.token.properties
            }).subscribe(data => {
                if (data && data.selectedSettingName) {
                    this.selectedSettingName = data.selectedSettingName;
                }
            });
        } else {
            // use the loading if you are redirecting to an external link
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.loading());
            this.window.open(setting.link, SAME_TAB_TARGET);
        }
    }
}

export interface ListItemSidebarSetting {
    link: string;
    name: string;
    title: string;
    css: string;
    token?: TokenData;
    ordinal: number
    icon?: string;
}
