import { VALIDATOR_NAMES } from "./common/validators/index";
import { INVALID_EXPIRATION_DATE, MISSING_PUB_UNPUB_VALUES } from "./common/validators/schedule.validator";
import { stringConstants } from "../src/app/common-constants";
import { CUSTOM_ERROR_PREFIX, VALIDATOR_MESSAGES } from "./common/validators/validators.constants";
import { INT_NUMBER_REGEX, DECIMAL_NUMBER_REGEX } from "./number/number-settings";
import { INVALID_EVENT_END_DATE } from "../src/app/modules/shared/components/events/validators/events-date-time.validator";

export class FieldValidation {

    private context: any;
    private ERROR_MESSAGE_MAP = new Map<string, string>();

    constructor(context: any) {
        this.context = context;
    }

    /**
     * Retrieves the corresponding error message per given validation error
     *
     * @param {Object} error - Angular validation error object
     * @returns {string} - error message
     *
     * @memberOf FieldValidation
     */
    getErrorMessage(error: Object): Array<string> {
        if (!error) {
            return null;
        }

        return Object.keys(error)
        .map(errorType => this.buildMessageForErrorType(errorType, error[errorType]));
    }

    /**
     * Builds error message, when the error is hit for the first time
     *
     * @param {string} errorType
     * @param {*} error
     * @returns {string} - error message
     *
     * @memberOf FieldValidation
     */
    // tslint:disable-next-line:cyclomatic-complexity
    buildErrorMessage(errorType: string, error: any): string {
        let errorMessage: string;
        switch (errorType) {
            case VALIDATOR_NAMES.REQUIRED:
                errorMessage = this.buildRequiredMessage(error);
                break;
            case VALIDATOR_NAMES.MIN_LENGTH:
                errorMessage = FieldValidation.getMinLengthMessage(error.requiredLength); break;
            case VALIDATOR_NAMES.MAX_LENGTH:
                errorMessage = FieldValidation.getMaxLengthMessage(error.requiredLength); break;
            case VALIDATOR_NAMES.MIN_VALUE:
                errorMessage = FieldValidation.getMinValueMessage(error.requiredMinValue); break;
            case VALIDATOR_NAMES.MAX_VALUE:
                errorMessage = FieldValidation.getMaxValueMessage(error.requiredMaxValue); break;
            case VALIDATOR_NAMES.VALUE_RANGE:
                errorMessage = FieldValidation.getValueRangeMessage(error.maxValue, error.minValue); break;
            case VALIDATOR_NAMES.DIGITS_LIMIT:
                errorMessage = FieldValidation.getDigitsLimitMessage(error.requiredLength); break;
            case VALIDATOR_NAMES.MAX_INTEGER:
                errorMessage = FieldValidation.getMaxIntegerMessage(error.maxIntegerValue); break;
            case VALIDATOR_NAMES.PATTERN:
                errorMessage = FieldValidation.getPatternMessage(this.context, error); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.URL_EXIST:
                errorMessage = FieldValidation.getUrlExistsMessage(); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.URL_EXIST_SPECIFIC:
                errorMessage = FieldValidation.getUrlExistsMessageSpecific(); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.URL_EXIST_MANY:
                errorMessage = FieldValidation.getUrlExistsMessageMany(); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.TAXONOMY_NAME_DUPLICATE:
                errorMessage = FieldValidation.getClassificationNameDuplicate(); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.TITLE_EXISTS:
                errorMessage = FieldValidation.getTemplateTitleDuplicate(); break;
            case CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.NAME_EXISTS:
                errorMessage = FieldValidation.getTemplateNameDuplicate(); break;
            case VALIDATOR_MESSAGES.INVALID_NUMBER:
                errorMessage = FieldValidation.getInvalidNumberMessage(); break;
            case INVALID_EXPIRATION_DATE:
                errorMessage = FieldValidation.getExpirationDateMessage(); break;
            case VALIDATOR_MESSAGES.UPLOAD_FAILED:
            // We are not showing the real message as the fields for upload have their error representation
                errorMessage = stringConstants.EMPTY_STRING; break;
            case MISSING_PUB_UNPUB_VALUES:
                errorMessage = FieldValidation.getMissingPublishUnpublishValueMessage();
                break;
            case INVALID_EVENT_END_DATE:
                errorMessage = FieldValidation.getEventEndTimeMessage();
                break;
            case VALIDATOR_NAMES.MULTILINE_EMAILS:
                errorMessage = FieldValidation.getInvalidMultipleEmailsMessage();
                break;
            default:
                errorMessage = FieldValidation.getUnknownErrorMessage(errorType, error); break;
        }

        if (!(this.context.settings && this.context.settings.customErrorMsgs) && errorType !== VALIDATOR_NAMES.PATTERN && errorType !== VALIDATOR_NAMES.CUSTOM) {
            // not adding it to the map, because it sets improper message for other pattern errors
            this.ERROR_MESSAGE_MAP.set(errorType, errorMessage);
        }

        if (this.context.settings && this.context.settings.customErrorMsgs && this.context.settings.customErrorMsgs[errorType]) {
            errorMessage = this.context.settings.customErrorMsgs[errorType];
        }

        return errorMessage;
    }

    static getEventEndTimeMessage(): string {
        return "Event end date must not precede event start date";
    }

    static getRequiredMessage(fieldTitle: string): string {
        return `Enter ${fieldTitle}`;
    }

    static getMinLengthMessage(requiredLength: number): string {
        return `Enter at least ${requiredLength} characters`;
    }

    static getMaxLengthMessage(requiredLength: number): string {
        return `Your text must be less than ${requiredLength} characters`;
    }

    static getMinValueMessage(requiredMinValue: number): string {
        return `Enter a value above ${requiredMinValue}`;
    }

    static getMaxValueMessage(requiredMaxValue: number): string {
        return `Enter a value below ${requiredMaxValue}`;
    }

    static getDigitsLimitMessage(requiredLength: number): string {
        return `Your number must be less than ${requiredLength} digits`;
    }

    static getMaxIntegerMessage(maxIntegerValue: number): string {
        return `Enter a number below ${maxIntegerValue}`;
    }

    static getValueRangeMessage(requiredMaxValue: number, requiredMinValue: number): string {
        return `Enter a number within the range of ${requiredMinValue} and ${requiredMaxValue}`;
    }

    static getPatternMessage(context: any, errors: any): string {
        const requiredPattern = errors.requiredPattern ? errors.requiredPattern : "custom";
        switch (requiredPattern) {
            case INT_NUMBER_REGEX:
                return "Enter a whole number";
            case DECIMAL_NUMBER_REGEX(context.settings.decimalPlaces):
                return `Enter a number with up to ${context.settings.decimalPlaces} digits after the decimal point`;
            default:
                if (context.settings.patternValidationErrorMessage) {
                    return context.settings.patternValidationErrorMessage;
                } else {
                    return context.settings.title ? `Enter valid ${context.settings.title}` : stringConstants.EMPTY_STRING;
                }

        }
    }

    static getUrlExistsMessage(): string {
        return `The URL already exists`;
    }

    static getUrlExistsMessageSpecific(): string {
        return `The URL marked in red already exists`;
    }

    static getUrlExistsMessageMany(): string {
        return `The URLs marked in red already exist`;
    }

    static getUnknownErrorMessage(errorType: string, error: any): string {
        if (!error) {
            return `No message defined for error type ${errorType}`;
        } else {
            const errorMessageProperties: string[] = ["message", "Message"];
            for (const errorMessageProperty of errorMessageProperties) {
                if (error[errorMessageProperty]) {
                    return error[errorMessageProperty];
                }
            }

            return error;
        }
    }

    static getInvalidNumberMessage(): any {
        return "The provided value is not a valid number. The value must not contain letters and spaces";
    }

    static getMissingPublishUnpublishValueMessage(): string {
        return "Select a date for publishing or unpublishing.";
    }

    static getExpirationDateMessage(): string {
        return "Date to unpublish must not precede publication date";
    }

    static getClassificationNameDuplicate(): string {
        return "A classification with the same name already exists.";
    }

    static getTemplateTitleDuplicate(): string {
        return "A template with the same title already exists.";
    }

    static getTemplateNameDuplicate(): string {
        return "A template with the same name already exists.";
    }

    static getInvalidMultipleEmailsMessage(): string {
        return "One or more addresses have invalid email format";
    }

    private buildMessageForErrorType(errorType: string, errorData: any): string {
        if (this.ERROR_MESSAGE_MAP.has(errorType)) {
            const error =  this.ERROR_MESSAGE_MAP.get(errorType);
            if (error && errorData && errorData.message && error !== errorData.message) {
                return this.buildErrorMessage(errorType, errorData);
            }
            return error;
        } else {
            return this.buildErrorMessage(errorType, errorData);
        }
    }

    private buildRequiredMessage (error: any): string {
        let requiredErrorMessage: string;
        if (!error.message) {
            requiredErrorMessage = FieldValidation.getRequiredMessage(this.context.settings.friendlyTitle || this.context.settings.title);
        } else {
            requiredErrorMessage = error.message;
        }
        return requiredErrorMessage;
    }
}
