import { Component, Input, OnInit, Output, EventEmitter, ChangeDetectorRef, ViewChild } from "@angular/core";
import { Operation, OPERATION_CATEGORIES, OPERATION_NAMES } from "../action-menu/operation.model";
import { ActionMenuOptions, ActionButton } from "../action-menu/action-menu-model";
import { OUTSIDE_MENU_MAX_ORDINAL, ActionButtonsResolver } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { ActivatedRoute } from "@angular/router";
import { DataItem } from "../../../content/dynamic-modules/interfaces";

import { BehaviorSubject ,  Observable, ReplaySubject, Subject } from "rxjs";
import { ModalWindowService } from "../../services/modal-window.service";
import { QUERY_PARAMS } from "../../../content/constants";
import { ActionMenuComponent } from "../action-menu/action-menu.component";
import { stringConstants } from "../../../../common-constants";
import { UrlService } from "../../../../services/url.service";
import { IChipIconConfig, SfRxBase } from "@progress/sitefinity-component-framework";

const PERSONALIZATION_DEFAULT_LOOK: string = "toggle left fixed-width";
const PERSONALIZATION_EDIT_LOOK: string = "auto-width";
const NO_HOVER_CLASS: string = "no-hover";
const PERSONALIZATION_ICON_DEFAULT_CLASS: string = "size-xs badge";
const PERSONALIZATION_ICON_ACTIVE_CLASS: string = "edit-variation";

/**
 * Component used to display item translations in edit page
 */
@Component({
    selector: "sf-personalization-dropdown",
    templateUrl: "./personalization-dropdown.component.html"
})
export class PersonalizationDropdownComponent extends SfRxBase implements OnInit {
    /**
     * The data item of the current edited content
     */
    @ViewChild("actionMenu", { static: false }) actionMenu: ActionMenuComponent;
    @Input() item: BehaviorSubject<DataItem>;
    @Input() personalizationOperations: Observable<Operation[]>;
    @Output() onChange: EventEmitter<ActionButton> = new EventEmitter<ActionButton>();

    public actionMenuOptions: ActionMenuOptions;
    public personalizationOperationName: string;
    public personalizationButtonLook: string;
    public hasNoWidgetOrPagePersonalizations: boolean;
    public showOnlyWidgetsTooltip: boolean;
    public previewImageSrc: string;

    public createPersonalizedButton: ActionButton;
    public filteredPersonalizedOperations: Subject<Operation[]> = new ReplaySubject(1);
    public dropdownButtonIconName: string;
    public dropdownButtonIconLook: string;
    public dropdownButtonText: string;
    public iconConfig: IChipIconConfig = {
        name: "user",
        look: "white size-xs",
        wrapperLook: "transparent"
    };

    /**
     * Initializes a new instance of the {@link PersonalizationDropdownComponent} class
     */
    constructor(protected route: ActivatedRoute, protected detector: ChangeDetectorRef, protected modalService: ModalWindowService,  private actionButtonsResolver: ActionButtonsResolver, private urlService: UrlService) {
        super();
    }

    public ngOnInit(): void {
        if (this.item) {
            const subscription = this.item.subscribe((item) => this.onItemChanged(item));
            this.registerSubscription(subscription);
        }

        this.personalizationOperations.subscribe(x => {
            const personalizationOperations = x.filter(x => x.Category.Name === OPERATION_CATEGORIES.personalization);
            const personalizedPageOperations = x.filter(x => x.Category.Name === OPERATION_CATEGORIES.personalized);
            const personalizedWidgetOperations = x.filter(x => x.Category.Name === OPERATION_CATEGORIES.personalizedWidgets);

            this.hasNoWidgetOrPagePersonalizations = false;
            this.dropdownButtonIconLook = null;
            this.dropdownButtonIconName = null;
            this.personalizationOperationName =  null;

            if (personalizedPageOperations.length === 0 && personalizationOperations.length >= 0) {
                this.createPersonalizedButton = this.actionButtonsResolver.getActionButtons(personalizationOperations)[0] as ActionButton;
                this.personalizationButtonLook = PERSONALIZATION_DEFAULT_LOOK;
                this.dropdownButtonIconName = "user";
                this.dropdownButtonIconLook = PERSONALIZATION_ICON_DEFAULT_CLASS;

                if (personalizedWidgetOperations.length > 0) {
                    this.filteredPersonalizedOperations.next(x);
                    this.dropdownButtonIconLook += ` ${PERSONALIZATION_ICON_ACTIVE_CLASS}`;
                } else {
                    this.filteredPersonalizedOperations.next([]);
                    this.hasNoWidgetOrPagePersonalizations = true;

                    const createOperation = personalizationOperations.find(x => x.Name === OPERATION_NAMES.createPersonalizedVersion);
                    if (createOperation && createOperation.ContextParameters && createOperation.ContextParameters.find(x => x.Name === "WidgetsToolTip"))
                        this.showOnlyWidgetsTooltip = true;

                    this.setPreviewImageSrc();
                }
            } else {
                this.personalizationButtonLook = `${PERSONALIZATION_DEFAULT_LOOK} ${PERSONALIZATION_EDIT_LOOK}`;
                const operationNamePrefix = OPERATION_NAMES.loadPersonalizedVersion + "_";
                const segmentId = this.route.snapshot.queryParams[QUERY_PARAMS.SEGMENT];
                this.personalizationOperationName =  operationNamePrefix + (segmentId ? segmentId : "Default");

                this.filteredPersonalizedOperations.next(x);
            }

            this.detector.detectChanges();
        });
    }

    /**
     * Handles the click event on a segment.
     * @param button The action menu button that was clicked.
     */
    public onActionButtonClicked(button: ActionButton): void {
        this.removeButtonHoverClass();
        this.onChange.emit(button);
    }

    onHover(hovered: boolean) {
        if (!this.personalizationButtonLook) {
            return;
        }

        // toggle no-hover on mouseEnter or mouseLeave
        if (hovered) {
            this.addButtonHoverClass();
        } else {
            this.removeButtonHoverClass();
        }
    }

    private addButtonHoverClass() {
        if (this.personalizationButtonLook.includes(NO_HOVER_CLASS)) {
            this.personalizationButtonLook = this.personalizationButtonLook.replace(` ${NO_HOVER_CLASS}`, stringConstants.EMPTY_STRING);
        }
    }

    private removeButtonHoverClass() {
        if (!this.personalizationButtonLook.includes(NO_HOVER_CLASS)) {
            this.personalizationButtonLook += ` ${NO_HOVER_CLASS}`;
        }
    }

    private onItemChanged(item: any) {

        this.actionMenuOptions = new ActionMenuOptions(Number.NEGATIVE_INFINITY, OUTSIDE_MENU_MAX_ORDINAL, true);
        this.detector.detectChanges();
    }

    private setPreviewImageSrc() {
        const previewImageFilePath = `assets/images/preview-personalize-widget.png`;
        this.previewImageSrc = this.urlService.getResourceUrl(`/${previewImageFilePath}`);
    }
}
