import { catchError } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { HttpODataRequestWrapper } from "../../../shared/services/http-odata-request.wrapper";
import { QUERY_PARAMS } from "../../constants";
import { LoadingState } from "../../../shared/rxjs-extensions/delayEmission";
import { LoadingContentState } from "../../../shared/rxjs-extensions/toLoadingState";
import { Logger } from "../../../shared/services/logger-source/logger";
import { stringConstants } from "../../../../common-constants";

export const UNKNOWN_ERROR_MESSAGE = "An error happened.";

/**
 * API for managing dynamically generated urls for content in Sitefinity
 */
@Injectable()
export class LocatableDynamicItemService {
    constructor(private httpRequestWrapper: HttpODataRequestWrapper, private logger: Logger) { }

    getLocatableEntitySetNames(siteId: string): Observable<LoadingContentState<LocatabaleEntitySetNamesResponse>> {
        const request: Observable<LoadingContentState<LocatabaleEntitySetNamesResponse>> = this.httpRequestWrapper.get$(`SfLocatableTypes`, {
            params: {
                [QUERY_PARAMS.SITE]: siteId
            }
        });

        return this.addErrorHandling<LocatabaleEntitySetNamesResponse>(request);
    }

    getDynamicLink(entitySet: string, itemId: string, provider: string, culture: string, siteId: string, linkCulture: string = stringConstants.EMPTY_STRING): Observable<LoadingContentState<DynamicLinkResponse>> {
        const request: Observable<LoadingContentState<DynamicLinkResponse>> = this.httpRequestWrapper
            .get$(`${entitySet}(${itemId})/dynamiclink(culture='${linkCulture}')`, {
                params: {
                    [QUERY_PARAMS.CULTURE]: culture,
                    [QUERY_PARAMS.PROVIDER]: provider,
                    [QUERY_PARAMS.SITE]: siteId
                }
            });
        return this.addErrorHandling<DynamicLinkResponse>(request);
    }

    getItemFromDynamicLink(dynamicLink: string): Observable<LoadingContentState<ItemFromDynamicLinkResponse>> {
        const request: Observable<LoadingContentState<ItemFromDynamicLinkResponse>> = this.httpRequestWrapper.get$(`item?dynamicLink=${dynamicLink}`);
        return this.addErrorHandling<ItemFromDynamicLinkResponse>(request);
    }

    private addErrorHandling<T extends LoadingState>(response: Observable<LoadingContentState<T>>): Observable<LoadingContentState<T>> {
        return response.pipe(catchError<any, any>(response => {
            if (response && response.error && response.error.error && response.error.error.message) {
                throw new Error(response.error.error.message);
            } else {
                this.logger.error(response);
                throw new Error(UNKNOWN_ERROR_MESSAGE);
            }
        }));
    }
}

export interface DynamicLinkResponse extends LoadingState {
    dynamicLink: string;
    link: string;
}

export interface ItemFromDynamicLinkResponse extends LoadingState {
    id: string;
    title: string;
    provider: string;
    entitySet: string;
}

export interface LocatabaleEntitySetNamesResponse extends LoadingState {
    value: string[];
}
