import { Component, Input, OnInit } from "@angular/core";

@Component({
    selector: "sf-no-items-found",
    templateUrl: "./no-items-found.component.html"
})
export class NoItemsFoundComponent implements OnInit {
    @Input() itemType = "items";
    @Input() look: string;
    @Input() textLook: string;
    @Input() iconName = "search";
    @Input() message: string;

    public wrapperClass: string;
    public textClass: string;

    ngOnInit() {
        this.wrapperClass = this.generateWrapperCssClassList();
        this.textClass = this.generateTextCssClassList();
    }

    generateWrapperCssClassList() {
        let cls = "-sf-txt-align-center";

        if (this.look) {
            cls += " -" + this.look.split(" ").join(" -");
        }
        return cls;
    }

    generateTextCssClassList() {
        let cls = "-sf-txt-hint";

        if (this.textLook) {
            cls += " -" + this.textLook.split(" ").join(" -");
        }
        return cls;
    }
}
