import { Component, OnInit } from "@angular/core";
import { ChoiceItem } from "@progress/sitefinity-component-framework";
import { createValueAccessor, FieldBase } from "../../../../../../../fields";
import { ChoiceDropdownComponent } from "../../../../../../../fields/choice/choice-dropdown.component";
import { ChoiceSettings } from "../../../../../../../fields/choice/choice.settings";
import { DATE_FORMATS_WHITELIST, TIME_FORMATS_WHITELIST } from "../../../../../../../fields/date-time/date-time-picker.constants";
import { SettingsBase } from "../../../../../../../fields/field-settings-base";
import { DateTimeFormat } from "../../../../../app-config/external-app-config.service";
import { FieldRegistration } from "../../../../shared/fields-builder/services/fields-registry";

@Component({
    selector: "sf-date-and-time-selector",
    templateUrl: "./date-and-time-selector.component.html",
    providers: [createValueAccessor(DateAndTimeSelectorComponent)]
})
export class DateAndTimeSelectorComponent extends FieldBase<SettingsBase, DateAndTimeSelectorValue> implements OnInit {
    useBrowserLocaleChoiceSettings: ChoiceSettings;
    formatWidthChipsSettings: ChoiceSettings;
    dateChoicesSettings: ChoiceSettings;
    timeChoicesChoiceSettings: ChoiceSettings;

    useBrowserLocale: boolean = false;
    formatWidth: BrowserLocaleDateFormatWidth;
    dateFormat: string;
    timeFormat: string;
    dateTimeLook: string;

    ngOnInit() {
        super.ngOnInit();

        if (this.settings && this.settings.look) {
            this.dateTimeLook = "-" + this.settings.look.split(" ").join(" -");
        }

        this.initializeUseBrowserLocale();
        this.initializeFormatWidth();
        this.initializeDateAndTimeFormats();
    }

    browserLocaleSelectionChanged($event) {
        this.useBrowserLocale = $event === "true";

        const value = this.getValue();
        value.useBrowserLocale = this.useBrowserLocale;

        if (!this.formatWidth) {
            this.formatWidth = BrowserLocaleDateFormatWidth.short;
            value.browserLocaleFormatWidth = this.formatWidth;
        }

        this.writeValue(value);
    }

    formatWidthSelectionChanged($event) {
        this.formatWidth = $event;

        const value = this.getValue();
        value.browserLocaleFormatWidth = this.formatWidth;
        this.writeValue(value);
    }

    dateFormatSelectionChanged($event) {
        this.dateFormat = $event;

        const value = this.getValue();
        value.dateFormat = this.dateFormat;
        this.writeValue(value);
    }

    timeFormatSelectionChanged($event) {
        this.timeFormat = $event;

        const value = this.getValue();
        value.timeFormat = this.timeFormat;
        this.writeValue(value);
    }

    getValue(): DateAndTimeSelectorValue {
        return super.getValue() || new DateAndTimeSelectorValue();
    }

    writeValue(value: any) {
        super.writeValue(value);
        // since our value is of type object the change callback is not called in the base method
        // That`s because the base method checks for equality by reference in this case
        // we need to always call the change callback when we want to write the new value and we have
        // simply mutated the object
        if (this.onChangeCallback) {
            this.onChangeCallback(value);
        }
    }

    private initializeUseBrowserLocale() {
        // || true comes from the default state from the UX
        this.useBrowserLocale = this.getValue().useBrowserLocale;

        if (this.useBrowserLocale === null || this.useBrowserLocale === undefined) {
            this.useBrowserLocale = false;
        }

        const yesChoice = {
            Name: "Yes",
            Value: "true",
            Title: "Yes",
            Selected: this.useBrowserLocale
        };

        const noChoice = {
            Name: "No",
            Value: "false",
            Title: "No",
            Selected: !this.useBrowserLocale
        };

        const useBrowserLocaleChoices: Array<ChoiceItem> = [yesChoice, noChoice];

        this.useBrowserLocaleChoiceSettings = new ChoiceSettings("useBrowserLocale", false);
        this.useBrowserLocaleChoiceSettings.title = "Use browser locale";
        this.useBrowserLocaleChoiceSettings.choices = useBrowserLocaleChoices;
        this.useBrowserLocaleChoiceSettings.useDefaultValue = true;
        this.useBrowserLocaleChoiceSettings.defaultValue = this.useBrowserLocale.toString();
    }

    private initializeFormatWidth() {
        this.formatWidth = BrowserLocaleDateFormatWidth[this.getValue().browserLocaleFormatWidth];

        this.formatWidthChipsSettings = new ChoiceSettings("formatWidth", false);
        this.formatWidthChipsSettings.choices = this.formatWidthChoices;
        this.formatWidthChipsSettings.useDefaultValue = true;
        this.formatWidthChipsSettings.defaultValue = this.formatWidth || this.formatWidthChoices[0].Value;
    }

    private initializeDateAndTimeFormats() {
        const dateChoices: ChoiceItem[] = DATE_FORMATS_WHITELIST.map(df => {
            return {
                Name: df,
                Value: df
            }
        });

        const timeChoices: ChoiceItem[] = TIME_FORMATS_WHITELIST.map(tf => {
            return {
                Name: tf,
                Value: tf
            }
        });
        this.timeFormat = this.getValue().timeFormat;
        this.dateFormat = this.getValue().dateFormat;

        this.dateChoicesSettings = ChoiceDropdownComponent.createFieldSettings(dateChoices, this.dateFormat || dateChoices[0]?.Value, "dateChoices");
        this.timeChoicesChoiceSettings = ChoiceDropdownComponent.createFieldSettings(timeChoices, this.timeFormat || timeChoices[0]?.Value, "timeChoices");
    }

    private formatWidthChoices: Array<ChoiceItem> = [
        {
            Name: "short",
            Value: "short",
            Title: "short"
        },
        {
            Name: "long",
            Value: "long",
            Title: "long"
        },
    ];
}

export enum BrowserLocaleDateFormatWidth {
    short = "short",
    long = "long",
}

export class DateAndTimeSelectorValue implements DateTimeFormat {
    constructor() {
        this.useBrowserLocale = false;
    }

    useBrowserLocale?: boolean;
    browserLocaleFormatWidth?: string;
    timeFormat?: string;
    dateFormat?: string;
}

export const DATE_AND_TIME_SELECTOR_REGISTRY: FieldRegistration = {
    writeComponent: DateAndTimeSelectorComponent,
    readComponent: DateAndTimeSelectorComponent,
    settingsType: SettingsBase
};
