import { createReducer, on } from "@ngrx/store";
import { cloneObject } from "../../../utils";
import { COLUMN_ACTIONS } from "../actions/actions.columns";
import { ColumnState } from "../schemas/schema.columns";
import { initialState } from "../store-schema";

export const columnExpandCollapseReducer = createReducer<ColumnState>(initialState.columns,
    on(COLUMN_ACTIONS.toggleExpandedPerEntity, (state, { entitySet, columnName }) => {
        const clonedState: ColumnState = cloneObject(state);
        if (!clonedState.expandedColumnsPerEntity[entitySet]) {
            clonedState.expandedColumnsPerEntity[entitySet] = [];
        }

        const columnIndex = clonedState.expandedColumnsPerEntity[entitySet].indexOf(columnName);
        if (columnIndex === -1) {
            clonedState.expandedColumnsPerEntity[entitySet].push(columnName);
        } else {
            clonedState.expandedColumnsPerEntity[entitySet].splice(columnIndex, 1);
        }

        if (!clonedState.expandedColumnsPerItem[entitySet]) {
            clonedState.expandedColumnsPerItem[entitySet] = {};
        }

        clonedState.expandedColumnsPerItem[entitySet][columnName] = {};

        return clonedState;
    }),
    on(COLUMN_ACTIONS.toggleExpandedPerItem, (state, { entitySet, columnName, itemId, expanded }) => {
        const clonedState: ColumnState = cloneObject(state);
        if (!clonedState.expandedColumnsPerItem[entitySet]) {
            clonedState.expandedColumnsPerItem[entitySet] = {};
        }

        if (!clonedState.expandedColumnsPerItem[entitySet][columnName]) {
            clonedState.expandedColumnsPerItem[entitySet][columnName] = {};
        }

        clonedState.expandedColumnsPerItem[entitySet][columnName][itemId] = expanded;

        return clonedState;
    }),
    on(COLUMN_ACTIONS.setState, (state, { data }) => {
        let clonedState: ColumnState = cloneObject(state);
        clonedState = data;

        return clonedState;
    })
);
