import { Component, OnInit } from "@angular/core";
import { ChoiceListSettings } from "./choice-list-settings";
import { ChoiceSettings } from "../choice.settings";
import { ParameterArgument } from "../../../src/app/modules/shared/components/action-menu/operation.model";
import { DataItem } from "../../../src/app/modules/content/dynamic-modules/interfaces";
import { FieldBase, createValueAccessor } from "../../field-base";
import { ChoiceItem } from "@progress/sitefinity-component-framework";

@Component({
    selector: "sf-choice-list",
    templateUrl: "./choice-list.component.html",
    providers: [createValueAccessor(ChoiceListComponent)]
})
export class ChoiceListComponent extends FieldBase<ChoiceListSettings> implements OnInit {
    choiceSettings: ChoiceSettings;
    currentChoice: ParameterArgument;
    additionalValueChecked: boolean;
    dataItem: DataItem;
    additionalValueCheckedSettings;

    ngOnInit(): void {
        super.ngOnInit();
        this.dataItem = this.settings.dataItem;
        this.choiceSettings = new ChoiceSettings("choices", false);
        this.choiceSettings.defaultValue = this.value;
        this.choiceSettings.choices = this.getChoices();
        this.currentChoice = this.settings.arguments.filter(a => a.Value === this.value)[0];
    }

    onSelectionChange(value) {
        this.currentChoice = this.settings.arguments.filter(a => a.Value === value)[0];
        this.additionalValueCheckedSettings = { title: this.currentChoice.AdditionalValueLabel, key: this.settings.key };
        this.updateValue();
    }

    updateValue() {
        if (!this.additionalValueChecked) {
            this.writeValue(this.currentChoice.Value);
        } else {
            this.writeValue(`${this.currentChoice.Value},${this.currentChoice.AdditionalValue}`);
        }
    }

    private getChoices(): ChoiceItem[] {
        const choices: ChoiceItem[] = [];

        for (const argument of this.settings.arguments) {
            choices.push({
                Value: argument.Value,
                Name: argument.Label
            });
        }

        return choices;
    }
}
