import { OperationsFilter, OPERATIONS_FILTER_TOKEN } from "../../content/dynamic-modules/services/operations/operations-filter";
import { OperationsData, OperationsTarget } from "../../content/dynamic-modules/services/operations/interfaces";
import { OPERATION_NAMES, Operation, OPERATION_TITLES, OPERATION_CATEGORIES } from "../../shared/components/action-menu/operation.model";
import { Injectable, ClassProvider, Inject } from "@angular/core";
import { PRIMARY_BUTTON_ORDINAL } from "../../shared/components/action-menu/action-menu-model";
import { SwitchGridViewCommand } from "../commands/switch-grid-view.command";
import { MediaHelpers } from "../services/media.helpers";
import { StorageService, LIBRARIES_GRID_VIEW_KEY, LOCAL_STORAGE } from "../../shared/services/storage.service";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { RegenerateThumbnailsCommand } from "../../content/dynamic-modules/services/operations/commands/regenerate-thumbnails.command";
import { UserDataStore } from "../../shared/services/metadata/user-data.store";
import { getGridViewMode, GridViewModes } from "../../../utils";

@Injectable()
export class LibrariesOperationsFilter implements OperationsFilter {
    constructor(@Inject(LOCAL_STORAGE) private storageService: StorageService, private userStore: UserDataStore) {
    }

    filter(operations: Operation[], data: OperationsData): Operation[] {
        if (this.isTypeSupported(data.dataItem)) {
            operations = this.filterOperationsForMedia(operations, data);
            operations = this.filterOperationsForLibrariesAndFolders(operations, data);
            operations = this.filterOperationsForGridModeAndTarget(operations, data);

            return operations.map(o => {
                if (o.Category.Name === OPERATION_CATEGORIES.librariesGridView) {
                    o.token = {
                        type: SwitchGridViewCommand,
                        properties: {
                            gridViewName: o.Name
                        }
                    };
                }

                if (o.Name === OPERATION_NAMES.regenerateThumbnails) {
                    o.token = {
                        type: RegenerateThumbnailsCommand,
                        properties: { }
                    };
                }

                return o;
            });
        }

        return operations;
    }

    private filterOperationsForMedia(operations: Operation[], data: OperationsData): Operation[] {
        if (MediaHelpers.isMediaEntity(data.dataItem)) {
            if (data.target === OperationsTarget.List) {
                const createOperation = operations.find(x => x.Name === OPERATION_NAMES.createLibrary);
                if (createOperation) {
                    createOperation.Ordinal = PRIMARY_BUTTON_ORDINAL - 1;
                }
            } else if (data.target === OperationsTarget.Create) {
                const operationsToFilterOut = [OPERATION_NAMES.createLibrary];

                // If the user has the rights to skip the workflow and to directly publish, UploadPublished will be returned from server and the buttons
                // SendForReview, SendForApproval etc. need to be hidden by filtering out the Upload operation
                if (operations.find(x => x.Name === OPERATION_NAMES.uploadPublished)) {
                    operationsToFilterOut.push(OPERATION_NAMES.upload);
                }

                // get the operations that are not included in operationsToFilterOut
                operations = operations.filter(x => operationsToFilterOut.indexOf(x.Name) === - 1);
            }
        }

        return operations;
    }

    private filterOperationsForLibrariesAndFolders(operations: Operation[], data: OperationsData): Operation[] {
        if (MediaHelpers.isLibrary(data.dataItem.metadata.setName) && data.target === OperationsTarget.List) {
            const createOperation = operations.find(x => x.Name === OPERATION_NAMES.create);
            if (createOperation) {
                createOperation.Ordinal = PRIMARY_BUTTON_ORDINAL - 1;
            }

            const createMediaOperation = operations.find(x => x.Name === OPERATION_NAMES.createMedia);
            if (createMediaOperation) {
                createMediaOperation.Ordinal = PRIMARY_BUTTON_ORDINAL;
            }
        }

        if (MediaHelpers.isLibrary(data.dataItem.metadata.setName) && data.target === OperationsTarget.List) {
            const editOperation = operations.find(x => x.Name === OPERATION_NAMES.edit);
            if (editOperation) {
                editOperation.Title = OPERATION_TITLES.libraryProperties;
            }

            const reorderOperation = operations.find(x => x.Name === OPERATION_NAMES.reorder);
            if (reorderOperation && (!data.dataItem.data || data.dataItem.data.ChildrenCount <= 1)) {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.reorder);
            }
        }

        return operations;
    }

    private filterOperationsForGridModeAndTarget(operations: Operation[], data: OperationsData): Operation[] {
        const gridViewRecord = this.storageService.getItem(LIBRARIES_GRID_VIEW_KEY);
        const userId = this.userStore.userId;
        const gridMode = getGridViewMode(gridViewRecord, userId);
        if (gridMode === GridViewModes.Timeline && data.target !== OperationsTarget.Create) {
            if (data.parentItem) {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.createLibrary);
            } else {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.create);
            }
        }

        if (data.target === OperationsTarget.Create) {
            operations = operations.filter(x => x.Category.Name !== OPERATION_CATEGORIES.librariesGridView);
        }

        if (data.target !== OperationsTarget.Bulk && data.target !== OperationsTarget.List) {
            if (data.target !== OperationsTarget.Edit) {
                operations = operations.filter(x => x.Name !== OPERATION_NAMES.schedule);
            }

            operations = operations.filter(x => x.Name !== OPERATION_NAMES.bulkEditProperties);
        }

        return operations;
    }

    private isTypeSupported(entityData: EntityData): boolean {
        return MediaHelpers.isLibraryOrMedia(entityData.metadata.setName);
    }
}

export const LIBRARIES_OPERATION_FILTER: ClassProvider = {
    multi: true,
    provide: OPERATIONS_FILTER_TOKEN,
    useClass: LibrariesOperationsFilter
};
