import { Injectable, Optional, InjectionToken, Inject } from "@angular/core";
import { KEYS } from "./../modules/shared/services/settings-keys";
import { StorageService, LOCAL_STORAGE } from "./../modules/shared/services/storage.service";
import { WINDOW_TOKEN } from "../window.provider";
import { ThemeItem } from "./theme-item";
import { ThemeProvider } from "./theme-provider";
import { ThemeVariables } from "./theme-variables";

export const THEME_TOKEN = new InjectionToken("theme_token");

const STYLE_TAG = "STYLE";
const STYLE_TAG_TYPE = "text/css";
const CSS_SELECTOR = ":root .sf-app";
const DEFAULT_THEME_NAME = "Default theme";
const FOCUS_THEME_DATA_ATTRIBUTE = "data-sf-theme-focus";
const DEFAULT_THEME: ThemeItem = {
    id: 0,
    name: DEFAULT_THEME_NAME,
    themeVariables: []
};

@Injectable()
export class CompositeThemeProvider implements ThemeProvider {

    public themes: Array<ThemeItem>;
    public hasProviders: boolean;
    public appliedTheme: ThemeItem;

    private previouslyAppliedTheme: ThemeItem;

    constructor(
        @Optional() @Inject(THEME_TOKEN) private themeProviders: Array<ThemeProvider>,
        @Inject(LOCAL_STORAGE) private storage: StorageService,
        @Inject(WINDOW_TOKEN) private windowProvider: Window) {
            this.hasProviders = this.themeProviders !== null;
            this.themes = this.getThemes();
            this.previouslyAppliedTheme = JSON.parse(this.storage.getItem(KEYS.APP_THEME_DATA)) as ThemeItem;
    }

    getThemes(): Array<ThemeItem> {
        const themes: Array<ThemeItem> = [];

        if (this.hasProviders) {
            // Default theme has to be always first option.
            themes.push(DEFAULT_THEME);

            this.themeProviders.forEach((themeProvider) => {
                themeProvider.getThemes().forEach(theme => {
                    // It's up to us to set the ID in order to escape unnecessary conflict with the same names
                    // when combining themes from different providers. That's why ThemeItem does not export ID as property
                    const currentTheme: ThemeItem = {
                        id: themes.length,
                        name: theme.name,
                        themeVariables: theme.themeVariables
                    };

                    themes.push(currentTheme);
                });
            });
        }

        return themes;
    }

    applyTheme(selectedTheme?: ThemeItem): void {
        const appTheme = selectedTheme ? selectedTheme : this.previouslyAppliedTheme;
        const focusStyleTag = document.querySelector("[" + FOCUS_THEME_DATA_ATTRIBUTE + "]") as HTMLStyleElement;

        if (this.canApplyTheme(appTheme)) {
            this.cleanPreviouslyAppliedThemes();
            this.appliedTheme = this.findTheme(appTheme);
            const hasOutlineVariable = !!this.findVariable(this.appliedTheme, ThemeVariables.GlobalOutline);

            if (hasOutlineVariable) {
               this.applyCustomFocus(focusStyleTag);
            }

            this.applyThemeVariables(this.appliedTheme);
            this.storage.setItem(KEYS.APP_THEME_DATA, JSON.stringify(this.appliedTheme));
            this.previouslyAppliedTheme = this.appliedTheme;
        } else {
            this.removeCustomFocus(focusStyleTag);
            this.useDefaultTheme();
        }
    }

    // Reset all settings to default
    useDefaultTheme() {
        this.cleanPreviouslyAppliedThemes();
        this.appliedTheme = DEFAULT_THEME;
        this.previouslyAppliedTheme = undefined;
        this.storage.removeItem(KEYS.APP_THEME_DATA);
    }

    private canApplyTheme(appTheme: ThemeItem) {
        // If there's selected theme and it's not the default one and there's such theme in the array of themes (in case someone has delete the theme)
        return appTheme && (appTheme.id !== DEFAULT_THEME.id) && this.findTheme(appTheme);
    }

    private findVariable(theme: ThemeItem, variable: ThemeVariables) {
        return theme.themeVariables.find(x => x.key === variable);
    }

    private findTheme(appTheme: ThemeItem) {
        return this.themes.find(theme => theme.id === appTheme.id && theme.name === appTheme.name);
    }

    private getStyleTag(): HTMLStyleElement {
        if (this.previouslyAppliedTheme) {
            return document.getElementById(this.previouslyAppliedTheme.id.toString() + this.previouslyAppliedTheme.name) as HTMLStyleElement;
        }

        return null;
    }

    private applyCustomFocus(focusStyleTag: HTMLStyleElement): void {
        if (!focusStyleTag) {
            const css = "body.-sf-outline .sf-app :focus {outline: var(--global-outline); outline-offset: var(--global-outline-offset)}";
            const focusStyleTag = document.createElement(STYLE_TAG) as HTMLStyleElement;
            focusStyleTag.type = "text/css";
            focusStyleTag.setAttribute(FOCUS_THEME_DATA_ATTRIBUTE, "true");
            focusStyleTag.appendChild(document.createTextNode(css));
            this.windowProvider.document.head.appendChild(focusStyleTag);
        }
    }

    private applyThemeVariables(theme: ThemeItem): void {
        const styleTag = document.createElement(STYLE_TAG) as HTMLStyleElement;
        styleTag.type = STYLE_TAG_TYPE;
        styleTag.id = theme.id.toString() + theme.name;

        let styleTagContent = `${CSS_SELECTOR} {`;

        theme.themeVariables.forEach((variablePair) => {
            styleTagContent += `${variablePair.key}: ${variablePair.value};`;
        });

        styleTagContent += "}";

        styleTag.appendChild(document.createTextNode(styleTagContent));

        // If this is newly created style tag we must insert it on the page
        this.windowProvider.document.head.appendChild(styleTag);
    }

    private cleanPreviouslyAppliedThemes(): void {
        const styleTag = this.getStyleTag();

        if (styleTag) {
            styleTag.remove();
        }
    }

    private removeCustomFocus(focusStyleLink: HTMLStyleElement): void {
        if (focusStyleLink) {
            focusStyleLink.remove();
        }
    }
}
