import { Injectable, Inject } from "@angular/core";
import { Observable, Subject, ReplaySubject, combineLatest } from "rxjs";
import { NODE_NAMES } from "../../src/app/modules/html/selector-constants";
import { DOCUMENT_TOKEN } from "../../src/app/document.provider";
import { ExternalAppConfigService } from "../../src/app/app-config/external-app-config.service";
import { map } from "rxjs/operators";
import { UrlService } from "../../src/app/services/url.service";
import { EnvironmentService } from "../../src/app/modules/shared/services/environment.service";
import { environmentTypes } from "../../src/app/environment";
import { stringConstants } from "../../src/app/common-constants";

@Injectable()
export class ExternalStyleSheetService {
    private loadedStyleSheets$: ReplaySubject<Array<boolean>>;
    private externalStyleSheets: Array<string>;
    private loadedStyleSheets: Array<HTMLLinkElement> = [];

    constructor(
        @Inject(DOCUMENT_TOKEN) private documentProvider: Document,
        private adminAppConfigService: ExternalAppConfigService,
        private urlService: UrlService,
        private envService: EnvironmentService) {}

    applyExternalStyleSheets(): Observable<boolean> {
        if (!this.loadedStyleSheets$) {
            this.loadedStyleSheets$ = new ReplaySubject<Array<boolean>>(1);
            const config = this.adminAppConfigService.externalConfig;
            this.externalStyleSheets = (config && config.editorSettings && config.editorSettings.stylesheets) ? config.editorSettings.stylesheets : null;

            if (this.externalStyleSheets) {
                const loadedStyles: Array<Observable<boolean>> = [];

                this.externalStyleSheets.forEach(url => {
                    loadedStyles.push(this.loadStyleSheet(url));
                });

                combineLatest(...loadedStyles).subscribe(loadedStyle => {
                    this.loadedStyleSheets$.next(loadedStyle);
                });
            }
        }

        return this.loadedStyleSheets$.pipe(map(x => true));
    }

    destroyExternalStyleSheets(): void {
        if (this.loadedStyleSheets.length) {
            this.loadedStyleSheets.forEach(linkElement => {
                linkElement.remove();
            });

            this.loadedStyleSheets.length = 0;
            this.loadedStyleSheets$ = null;
        }
    }

    private loadStyleSheet(url: string): Observable<boolean> {
        if (!this.isAbsoluteUrl(url)) {
            url = this.getRelativePath(url);
        }

        const loadedStyle$ = new Subject<boolean>();
        const linkElement = this.documentProvider.createElement(NODE_NAMES.LINK_ELEMENT) as HTMLLinkElement;

        linkElement.rel = "stylesheet";
        linkElement.href = url;
        linkElement.onload = function() {
            loadedStyle$.next(true);

            loadedStyle$.complete();
        };

        this.loadedStyleSheets.push(linkElement);
        this.documentProvider.head.appendChild(linkElement);

        return loadedStyle$.asObservable();
    }

    private isAbsoluteUrl(url: string): boolean {
        let urlElement: URL | TypeError;

        try {
            urlElement = new URL(url);
        } catch (error) {
            urlElement = error;
        }

        return urlElement instanceof URL;
    }

    private getRelativePath(url: string): string {
        let localStyleSheet = url;
        if (this.envService.getEnvironment() === environmentTypes.integration) {
            if (!url.startsWith(stringConstants.FORWARD_SLASH)) {
                url = `${stringConstants.FORWARD_SLASH}${url}`;
            }

            localStyleSheet = this.urlService.getResourceUrl(url);
        } else {
            localStyleSheet = this.urlService.getAbsoluteUrl(url);
        }

        return localStyleSheet;
    }
}
