import { Observable, of } from "rxjs";
import { MainFieldComponent } from "../../content/dynamic-modules/components/grid-cells/main-field/main-field.component";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ListDetailsModel, ListIndexModel, ListIndexContract, GetListIndexModelArgs, GetListDetailsModelArgs, LIST_INDEX_DETAILS_MODES, ListIndexOperationResult } from "../../shared/services/list/list-index.contract";
import { ActivatedRoute, Router } from "@angular/router";
import { FieldValidation } from "../../../../../fields/field-validation";
import { GridActionMenuComponent } from "../../content/dynamic-modules/components/grid-cells/grid-action-menu/grid-action-menu.component";
import { DateAndUserComponent } from "../../shared/components/fields/date-and-user.component";
import { ActionButton } from "../../shared/components/action-menu/action-menu-model";
import { INTEGRATION_MODULE_MODEL_NAMES } from "../../content/constants";
import { PropertyMetadata } from "../../widget-editor/interfaces/widget-editor";


const MainSectionName = "Main";
const AdvancedSettingsName = "AdvancedSettings";
const AdditionalFieldsName = "AdditionalFields";

const FACETABLE_SEARCH_SERVICES: Array<string> = ['AzureSearchService', 'ElasticsearchService'];

export class SearchIndexesContract extends ListIndexContract {
    constructor(
        entityData: EntityData,
        dynamicItemService: DynamicItemService,
        router: Router,
    ) {
        super(entityData, dynamicItemService, router);
    }

    getListIndexModel(getListIndexModelArgs: GetListIndexModelArgs): ListIndexModel {
        return {
            title: "Search indexes",
            emptyListMessage: `No search indexes have been created`,
            columns: [{
                name: "Main",
                title: "Index",
                css: "-title -status",
                dataFieldNames: ["Name"],
                componentData: {
                    type: MainFieldComponent,
                    properties: {
                        hasStatusIcon: true
                    }
                },
                clickable: true
            }, {
                name: "DateCreated",
                title: "Created on/Owner",
                css: "-col-size-m",
                dataFieldNames: ["DateCreated"],
                componentData: {
                    type: DateAndUserComponent
                }
            },
            {
                name: "Actions",
                title: "Actions",
                css: "-action -col-size-3xs",
                dataFieldNames: ["Title"],
                componentData: {
                    type: GridActionMenuComponent
                }
            }],
            operations: of([{
                Actions: [],
                Category: {
                    Name: "Default",
                    Title: null
                },
                Name: "Create",
                Ordinal: -1,
                Title: `Create a search index`
            }]),
            pageSize: 20,
            order: "IsBackend desc",
            singularName: "search index",
            pluralName: "search indexes",
            emptyScreenIcon: "file-text-o",
            notificationFilter: this.entityData.metadata.typeFullName,
            dataFieldNames: [
                "Id",
                "Name",
                "DateCreated",
                "isBackend",
                "IsActive",
                "CreatedBy"
            ],
            isSiteSpecific: true,
            hasLongRunningTasks: true
        };
    }

    getListDetailsModel(getListDetailsModel: GetListDetailsModelArgs): ListDetailsModel {
        const isEdit = getListDetailsModel.detailsMode.toLowerCase() === LIST_INDEX_DETAILS_MODES.EDIT;
        if (isEdit && getListDetailsModel.dataItem.data.IsBackend) {
            return this.getBackendIndexModel();
        }

        return this.getSearchIndexModel(isEdit, getListDetailsModel.sites, getListDetailsModel.searchService);
    }

    private getBackendIndexModel(): ListDetailsModel {
        return {
            title: "Search index properties",
            name: INTEGRATION_MODULE_MODEL_NAMES.SEARCH_INDEX,
            propertyMetadata: [
                {
                    Name: "Main",
                    Title: null,
                    Properties: [
                        {
                            Name: "Name",
                            Title: "Name",
                            Type: "string",
                            DefaultValue: null,
                            TypeChildProperties: [],
                            Properties: {
                                "Validations_Required": true,
                                "Validations_RequiredErrorMsg": FieldValidation.getRequiredMessage("name"),
                                "Validations_MaxValue": 255,
                                "Validations_MaxLengthErrorMsg": FieldValidation.getMaxLengthMessage(255),
                                "Validations_ReadOnly": true
                            }
                        },
                        {
                            Name: "ContentTypesToInclude",
                            Title: "Index content types...",
                            DefaultValue: "All",
                            Type: "radioChoices",
                            TypeChildProperties: [],
                            Properties: {
                                "Meta_Choices": "[{\"Title\":\"All content types\",\"Name\":\"All\",\"Value\":\"All\",\"Icon\":null},{\"Title\":\"Selected content types\",\"Name\":\"SelectedContentTypes\",\"Value\":\"Selected\",\"Icon\":null}]",
                                "Meta_Choices_AllowMultiple": "False",
                                "Validations_ReadOnly": true
                            }
                        },
                        {
                            Name: "ContentTypes",
                            Title: "",
                            Type: "content",
                            DefaultValue: null,
                            TypeChildProperties: [],
                            Properties: {
                                "Meta_ConditionalVisibility_Condition": "{\"conditions\":[{\"fieldName\":\"ContentTypesToInclude\",\"operator\":\"Equals\",\"value\":\"Selected\"}], \"inline\":\"true\"}",
                                "Meta_Content_Type": "Telerik.Sitefinity.Publishing.Model.PipeSettings",
                                "Meta_Content_AllowMultipleItemsSelection": "True",
                                "Meta_Content_OpenMultipleItemsSelection": "True",
                                "Meta_Content_Provider": null,
                                "Meta_Content_DisplayFieldName": "ContentName",
                                "Validations_ReadOnly": true
                            }
                        }
                    ]
                }
            ],
            hasSaveButton: false,
            saveButtonText: "",
            cancelButtonText: "Close",
            loadDataFromServer: true
        };
    }

    private getSearchIndexModel(isEdit: boolean, sites: DataItem[], searchService: string): ListDetailsModel {
        const listDetailsModel: ListDetailsModel = {
            title: isEdit ? "Search index properties" : "Create a search index",
            name: INTEGRATION_MODULE_MODEL_NAMES.SEARCH_INDEX,
            propertyMetadata: [
                {
                    Name: "Main",
                    Title: null,
                    Properties: [
                        {
                            Name: "Name",
                            Title: "Name",
                            Type: "string",
                            DefaultValue: null,
                            TypeChildProperties: [],
                            Properties: {
                                "Validations_Required": true,
                                "Validations_RequiredErrorMsg": FieldValidation.getRequiredMessage("name"),
                                "Validations_MaxValue": 255,
                                "Validations_MaxLengthErrorMsg": FieldValidation.getMaxLengthMessage(255)
                            }
                        },
                        {
                            Name: "ContentTypesToInclude",
                            Title: "Index content types...",
                            DefaultValue: "All",
                            Type: "radioChoices",
                            TypeChildProperties: [],
                            Properties: {
                                "Meta_Description_Description": "[{\"Type\":1,\"Chunks\":[{\"Value\":\"By default, the search index includes fields Title, Content, and Summary (if available).\",\"Presentation\":[]},{\"Value\":\"To index different fields, include them as additional fields in the Advanced settings section on this screen.\",\"Presentation\":[2]}]}]",
                                "Meta_Choices": "[{\"Title\":\"All content types\",\"Name\":\"All\",\"Value\":\"All\",\"Icon\":null},{\"Title\":\"Selected content types\",\"Name\":\"SelectedContentTypes\",\"Value\":\"Selected\",\"Icon\":null}]",
                                "Meta_Choices_AllowMultiple": "False"
                            }
                        },
                        {
                            Name: "ContentTypes",
                            Title: "",
                            Type: "content",
                            DefaultValue: null,
                            TypeChildProperties: [],
                            Properties: {
                                "Meta_ConditionalVisibility_Condition": "{\"conditions\":[{\"fieldName\":\"ContentTypesToInclude\",\"operator\":\"Equals\",\"value\":\"Selected\"}], \"inline\":\"true\"}",
                                "Meta_Content_Type": "Telerik.Sitefinity.Publishing.Model.PipeSettings",
                                "Meta_Content_AllowMultipleItemsSelection": "True",
                                "Meta_Content_OpenMultipleItemsSelection": "True",
                                "Meta_Content_ShowFilterSelector": "False",
                                "Meta_Content_LiveData": "False",
                                "Meta_Content_Provider": null,
                                "Meta_Content_DisableInteraction": "True",
                                "Meta_Content_DisplayFieldName": "ContentName",
                                "Validations_Required": true,
                                "Validations_RequiredErrorMsg": "Select a content type"
                            }
                        }
                    ]
                },
                {
                    Name: "AdvancedSettings",
                    Title: "Advanced settings",
                    Properties: [
                        {
                            Name: "AdditionalFields",
                            Title: "Additional fields for indexing",
                            Type: "enumerable",
                            DefaultValue: "",
                            TypeChildProperties: [
                                {
                                    Name: "FieldName",
                                    Title: "Field Name",
                                    DefaultValue: null,
                                    Type: "string",
                                    Properties: {
                                        "Meta_Placeholder_Text": "type field name...",
                                        "Validations_Regex": "^_*[a-zA-Z]+\\w*$",
                                        "Validations_RegexErrorMsg": "Field name contains invalid symbols",
                                        "Meta_Content_DisableInteraction": "True",
                                        "Meta_Choice_NotResponsive": "True",
                                    }
                                },
                                {
                                    Name: "FieldType",
                                    Title: "Type",
                                    DefaultValue: "ShortText",
                                    Type: "choices",
                                    Properties: {
                                        "Meta_Choice_Choices": "[{\"Title\":\"Short text\",\"Name\":\"ShortText\",\"Value\":\"ShortText\",\"Icon\":null},{\"Title\":\"Long text\",\"Name\":\"LongText\",\"Value\":\"LongText\",\"Icon\":null},{\"Title\":\"Choices\",\"Name\":\"Choices\",\"Value\":\"Choices\",\"Icon\":null},{\"Title\":\"Yes / No\",\"Name\":\"YesNo\",\"Value\":\"YesNo\",\"Icon\":null},{\"Title\":\"Date and time\",\"Name\":\"DateAndTime\",\"Value\":\"DateAndTime\",\"Icon\":null},{\"Title\":\"Number (whole)\",\"Name\":\"NumberWhole\",\"Value\":\"NumberWhole\",\"Icon\":null},{\"Title\":\"Number (decimal)\",\"Name\":\"NumberDecimal\",\"Value\":\"NumberDecimal\",\"Icon\":null},{\"Title\":\"Classification\",\"Name\":\"Classification\",\"Value\":\"Classification\",\"Icon\":null}]",
                                        "Meta_Choices": "[{\"Title\":\"Short text\",\"Name\":\"ShortText\",\"Value\":\"ShortText\",\"Icon\":null},{\"Title\":\"Long text\",\"Name\":\"LongText\",\"Value\":\"LongText\",\"Icon\":null},{\"Title\":\"Choices\",\"Name\":\"Choices\",\"Value\":\"Choices\",\"Icon\":null},{\"Title\":\"Yes / No\",\"Name\":\"YesNo\",\"Value\":\"YesNo\",\"Icon\":null},{\"Title\":\"Date and time\",\"Name\":\"DateAndTime\",\"Value\":\"DateAndTime\",\"Icon\":null},{\"Title\":\"Number (whole)\",\"Name\":\"NumberWhole\",\"Value\":\"NumberWhole\",\"Icon\":null},{\"Title\":\"Number (decimal)\",\"Name\":\"NumberDecimal\",\"Value\":\"NumberDecimal\",\"Icon\":null},{\"Title\":\"Classification\",\"Name\":\"Classification\",\"Value\":\"Classification\",\"Icon\":null}]",
                                        "Meta_Choices_AllowMultiple": "False",
                                        "Meta_Choice_NotResponsive": "True",
                                        "Meta_Content_DisableInteraction": "True"
                                    }
                                }
                            ],
                            Properties: {
                                "Meta_Description_Description": "[{\"Type\":1,\"Chunks\":[{\"Value\":\"If you want to index other fields, besides the Title, Content, and Summary (if available), add them to this section.\",\"Presentation\":[]},{\"Value\":\"For the changes to take effect, you must reindex.\",\"Presentation\":[2]}]}]",
                                "Meta_TableView_ColumnTitle": null,
                                "Meta_TableView_Enabled": "True",
                                "Meta_Look": "top-aligned"
                            }
                        }
                    ]
                }
            ],
            hasSaveButton: true,
            saveButtonText: isEdit ? "Save changes" : "Create this index",
            cancelButtonText: "Cancel",
            loadDataFromServer: isEdit ? true : false
        };

        if (sites.length > 1) {
            this.addSitePropertiesToMainSection(listDetailsModel);
        }

        if (FACETABLE_SEARCH_SERVICES.includes(searchService)) {
            this.addFacetableAndLabelFieldInAdditionalFields(listDetailsModel);
        }

        return listDetailsModel;
    }

    tryExecuteOperation(dataItem: DataItem, button: ActionButton, activatedRoute?: ActivatedRoute): Observable<ListIndexOperationResult> {
        return super.tryExecuteOperation(dataItem, button, activatedRoute);
    }

    private addSitePropertiesToMainSection(listDetailsModel: ListDetailsModel) {
        const mainSectionData = listDetailsModel.propertyMetadata.find(e => e.Name === MainSectionName);

        const siteToIncludeProperty: PropertyMetadata =
        {
            Name: "SitesToInclude",
            Title: "Index content from...",
            Type: "radioChoices",
            DefaultValue: "ThisSiteOnly",
            TypeChildProperties: [],
            Properties: {
                "Meta_Choices": "[{\"Title\":\"All sites\",\"Name\":\"All\",\"Value\":\"All\",\"Icon\":null},{\"Title\":\"This site only\",\"Name\":\"ThisSiteOnly\",\"Value\":\"ThisSiteOnly\",\"Icon\":null},{\"Title\":\"Selected sites\",\"Name\":\"Selected\",\"Value\":\"Selected\",\"Icon\":null}]",
                "Meta_Choices_AllowMultiple": "False"
            }
        };

        const siteSelectorProperty: PropertyMetadata =
        {
            Name: "Sites",
            Title: "",
            Type: "content",
            DefaultValue: null,
            TypeChildProperties: [],
            Properties: {
                "Meta_ConditionalVisibility_Condition": "{\"conditions\":[{\"fieldName\":\"SitesToInclude\",\"operator\":\"Equals\",\"value\":\"Selected\"}], \"inline\":\"true\"}",
                "Meta_Content_Type": "Telerik.Sitefinity.Multisite.Model.Site",
                "Meta_Content_AllowMultipleItemsSelection": "True",
                "Meta_Content_OpenMultipleItemsSelection": "True",
                "Meta_Content_ShowFilterSelector": "True",
                "Meta_Content_DisableInteraction": "True",
                "Meta_Content_LiveData": "False",
                "Meta_Content_Provider": null,
                "Meta_Content_Template": "chips",
                "Meta_Content_HasPreSelectedImmutableItems": "True"
            }
        }

        mainSectionData.Properties.push(siteToIncludeProperty);
        mainSectionData.Properties.push(siteSelectorProperty);
    }

    private addFacetableAndLabelFieldInAdditionalFields(listDetailsModel: ListDetailsModel) {
        const advanceSettingsProperty = listDetailsModel.propertyMetadata.find(p => p.Name == AdvancedSettingsName);
        const additionalFieldProperty = advanceSettingsProperty.Properties.find(p => p.Name == AdditionalFieldsName);

        const additionalFieldProps: PropertyMetadata =
        {
            Name: "IsFacetable",
            Title: "Facetable",
            DefaultValue: "False",
            Type: "chipchoice",
            Properties: {
                "Meta_ConditionalVisibility_Condition": "{\"conditions\":[{\"fieldName\":\"FieldType\",\"operator\":\"NotEquals\",\"value\":\"LongText\", \"inline\":\"false\", \"hideContent\":\"true\"}]}",
                "Meta_Description_Description": "[{\"Type\":1,\"Chunks\":[{\"Value\":\"Fields marked as facetable are available as a set of filtering options. To display facetable fields on your site, add the Search facets widget on the same page as the Search results widget.\",\"Presentation\":[]}]}]",
                "Meta_Choice_Choices": "[{\"Title\":\"Yes\",\"Name\":\"Yes\",\"Value\":true,\"Icon\":null},{\"Title\":\"No\",\"Name\":\"No\",\"Value\":\"False\",\"Icon\":null}]",
                "Meta_Choices_AllowMultiple": "False",
                "Meta_Choice_NotResponsive": "True",
            }
        };

        const additionalFieldLabel: PropertyMetadata =
        {
            Name: "FieldTitle",
            Title: "Label",
            DefaultValue: null,
            Type: "string",
            Properties: {
                "Meta_ConditionalVisibility_Condition": "{\"conditions\":[{\"fieldName\":\"FieldType\",\"operator\":\"NotEquals\",\"value\":\"LongText\",\"inline\":\"false\", \"hideContent\":\"true\"}]}",
                "Meta_Description_Description": "[{\"Type\":1,\"Chunks\":[{\"Value\":\"Add a name of the facetable field that is visible on your site.\",\"Presentation\":[]}]}]",
                "Meta_Placeholder_Text": "type label...",
                "Validations_Regex": "^_*[a-zA-Z ]+\\w*$",
                "Validations_RegexErrorMsg": "Field name contains invalid symbols",
                "Meta_Choice_NotResponsive": "True",
                "Meta_Content_DisableInteraction": "True"
            }
        };

        additionalFieldProperty.TypeChildProperties.push(additionalFieldProps);
        additionalFieldProperty.TypeChildProperties.push(additionalFieldLabel);
    }
}
