import { Injectable, Inject } from "@angular/core";
import { ModalWindowService, ClosingContext, ClickResult } from "../../../../../shared/services/modal-window.service";
import { DynamicItemService } from "../../dynamic-item.service";
import { MetadataStore } from "../../../../../shared/services/metadata/meta-data.store";
import { LongRunningTasksService, LONG_RUNNING_TASK_COMPLETED } from "../../long-running-tasks.service";
import { OPERATION_TITLES } from "../../../../../shared/components/action-menu/operation.model";
import { ActivatedRoute } from "@angular/router";
import { LibraryTasksBaseCommand } from "./library-tasks-base.command";
import { Subject, ReplaySubject } from "rxjs";
import { SortService } from "../../../../../shared/services/sort.service";
import { TaskType } from "../../background-task.types";
import { CompositeDataExtender } from "../../../../../shared/services/data-extensions/data.extender";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../../shared/services/notification/notification.service";
import { NOTIFICATION_DURATION_INFINITE, QUERY_PARAMS } from "../../../../constants";
import { NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { MODAL_WINDOW_NOTIFICATION_FILTER } from "../../../../../shared/components/modal-window/modal-window.component";
import { WINDOW_TOKEN } from "../../../../../../window.provider";
import { DataItem } from "../../../interfaces";
import { ENTITY_SET } from "../../../../../shared/services/metadata/meta-data-constants";
import { ComponentData } from "@progress/sitefinity-component-framework";

@Injectable()
export class RegenerateThumbnailsCommand extends LibraryTasksBaseCommand {
    protected isHierarchical = false;
    protected dialogMapping = "regenerateThumbnails";
    protected dialogTitle = OPERATION_TITLES.regenerateThumbnails;
    protected confirmButtonText = OPERATION_TITLES.regenerateThumbnails;

    constructor(modalWindowService: ModalWindowService,
                metadataStore: MetadataStore,
                route: ActivatedRoute,
                compositeDataExtender: CompositeDataExtender,
                private longRunningTasksService: LongRunningTasksService,
                protected service: DynamicItemService,
                @Inject(NOTIFICATION_SERVICE) protected notificationService: NotificationService,
                @Inject(WINDOW_TOKEN) private window: Window,
                protected sortService: SortService) {
                    super(modalWindowService, metadataStore, compositeDataExtender, route, service, notificationService, sortService);
    }

    protected generateDescription(componentData: ComponentData) {
        componentData.properties.notificationText = "This operation will generate thumbnails in sizes specified in the properties of the selected library. It may take from few seconds up to few hours depending on the number of images in the library.";
        componentData.properties.notificationLook = "warning sf-mt--5xl";
    }

    protected getEntityData() {
        const provider = this.route.snapshot.queryParams[QUERY_PARAMS.PROVIDER] || null;
        this.entityData = DataItem.emptyItem({ metadata: this.metadataStore.getEntity(ENTITY_SET.ALBUMS), culture: null, provider: provider });
    }

    protected executeConfirmAction(selectedItems: DataItem[], clickResult: ReplaySubject<ClickResult>) {
        this.longRunningTasksService.start(selectedItems[0].key, TaskType.RegenerateThumbnails)
        .subscribe(
            response => {
                clickResult.next(new ClickResult(true, true));
            },
            error => {
                this.notificationService.publishBasicNotification({
                    message: error.message,
                    look: NOTIFICATION_LOOKS.ERROR,
                    duration: NOTIFICATION_DURATION_INFINITE,
                    filterParam: MODAL_WINDOW_NOTIFICATION_FILTER
                });
                clickResult.next(new ClickResult(false, false, true));

                // if a library/folder is deleted before we clicked regenerate from the dialog, error will occur and the grid
                // needs to be refreshed in order to stop visualizing the already deleted library/folder
                const event = new CustomEvent(LONG_RUNNING_TASK_COMPLETED);
                this.window.dispatchEvent(event);
            }
        );
    }

    protected onDone(context: ClosingContext, return$: Subject<any>) {
        this.notificationService.close();
        return$.next({});
        return$.complete();
    }
}
