import { Component, Input, Pipe, PipeTransform } from "@angular/core";
import { FormRuleCondition, FormRuleOperatorList, FormDefinition, FormsConstants } from "../forms.constants";
import { FormFieldTypesParserService } from "../services/form-field-types-parser.service";
import { stringConstants } from "../../../common-constants";
import { RelativeDatePipe } from "../../shared/pipes/relative-date.pipe";
import { IsoWeekDatesPipe } from "../../shared/pipes/iso-week-dates.pipe";
import { DateService } from "../../shared/services/date.service";

@Component({
    selector: "sf-condition-column",
    templateUrl: "./condition-column.component.html"
})
export class ConditionColumnComponent {
    @Input() formRuleConditions: FormRuleCondition[];
    @Input() formRuleOperator: string;
    @Input() formDefinition: FormDefinition;

    constructor(public typeParserService: FormFieldTypesParserService) {
    }
}

@Pipe({
    name: "sfGetConditionFieldTitle",
    pure: true
})
export class GetConditionFieldTitlePipe implements PipeTransform {
    constructor(private typeParserService: FormFieldTypesParserService) {
    }

    transform(value: FormRuleCondition, formDefinition: FormDefinition): any {
        const formField = this.typeParserService.getField(formDefinition, value.Id);
        if (formField) {
            return formField.Title;
        }

        return stringConstants.EMPTY_STRING;
    }
}

@Pipe({
    name: "sfGetConditionOperatorLabel",
    pure: true
})
export class GetConditionOperatorLabelPipe implements PipeTransform {
    constructor(private typeParserService: FormFieldTypesParserService) {
    }

    transform(value: FormRuleCondition, formDefinition: FormDefinition): any {
        const formField = this.typeParserService.getField(formDefinition, value.Id);
        if (formField) {
            const operator = formField.Operators.find(o => o.Key === value.Operator);
            if (operator) {
                return operator.Value;
            }
        }

        return stringConstants.EMPTY_STRING;
    }
}

@Pipe({
    name: "sfGetRuleOperatorLabel",
    pure: true
})
export class GetRuleOperatorLabelPipe implements PipeTransform {
    transform(value: string): any {
        return FormRuleOperatorList[value];
    }
}

@Pipe({
    name: "sfGetConditionFieldValue",
    pure: true
})
export class GetConditionFieldValuePipe implements PipeTransform {
    private relativeDatePipe: RelativeDatePipe;
    private isoWeekDatesPipe: IsoWeekDatesPipe;

    constructor(private typeParserService: FormFieldTypesParserService, private dateService: DateService) {
        this.relativeDatePipe = new RelativeDatePipe(this.dateService);
        this.isoWeekDatesPipe = new IsoWeekDatesPipe();
    }

    transform(condition: FormRuleCondition, formDefinition: FormDefinition): any {
        const formField = this.typeParserService.getField(formDefinition, condition.Id);

        if (formField && formField.InputType && condition.Value && condition.Value.trim() !== stringConstants.EMPTY_STRING) {
            switch (formField.InputType) {
                case FormsConstants.TEXT_INPUT_TYPE.DATE:
                    return this.relativeDatePipe.transform(condition.Value, null, FormsConstants.TIMEZONE_OFFSET);
                case FormsConstants.TEXT_INPUT_TYPE.MONTH:
                    return this.relativeDatePipe.transform(condition.Value, RelativeDatePipe.MONTH_AND_YEAR, FormsConstants.TIMEZONE_OFFSET);
                case FormsConstants.TEXT_INPUT_TYPE.TIME:
                    return this.relativeDatePipe.transform(condition.Value, RelativeDatePipe.TIME, FormsConstants.TIMEZONE_OFFSET);
                case FormsConstants.TEXT_INPUT_TYPE.DATE_TIME_LOCAL:
                    return this.relativeDatePipe.transform(condition.Value, RelativeDatePipe.FULL_DATE_SHORT_MONTH_AND_TIME, FormsConstants.TIMEZONE_OFFSET);
                case FormsConstants.TEXT_INPUT_TYPE.WEEK:
                    return this.isoWeekDatesPipe.transform(condition.Value);
                default:
                    return condition.Value;
            }
        }

        return condition.Value;
    }
}
