import { Observable, of } from "rxjs";
import { Operation, OPERATION_NAMES, OPERATION_TITLES } from "../../shared/components/action-menu/operation.model";
import { FieldValidation } from "../../../../../fields/field-validation";
import { GridActionMenuComponent } from "../../content/dynamic-modules/components/grid-cells/grid-action-menu/grid-action-menu.component";
import { MainFieldComponent } from "../../content/dynamic-modules/components/grid-cells/main-field/main-field.component";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { TextFieldComponent } from "../../shared/components/fields/text-field.component";
import { ListDetailsModel, ListIndexModel, ListIndexContract, GetListIndexModelArgs, GetListDetailsModelArgs, LIST_INDEX_DETAILS_MODES, ListIndexOperationResult } from "../../shared/services/list/list-index.contract";
import { MultiValueTextFieldComponent } from "../../shared/components/fields/multi-value-text-field.component";
import { ChildrenCountComponent } from "../../shared/components/fields/children-count-component";
import { SERVICE_HOOKS_HISTORY_DAYS_COUNT } from "./service-hook-history.contract";
import { ActivatedRoute, Router } from "@angular/router";
import { ActionButton } from "../../shared/components/action-menu/action-menu-model";
import { FILTER_PARAMS, INTEGRATION_MODULE_MODEL_NAMES } from "../../content/constants";

export class ServiceHooksContract extends ListIndexContract {
    constructor(entityData: EntityData, dynamicItemService: DynamicItemService, router: Router) {
        super(entityData, dynamicItemService, router);
    }

    getListIndexModel(getListIndexModelArgs: GetListIndexModelArgs): ListIndexModel {
        return {
            title: this.entityData.metadata.displayName,
            emptyListMessage: `No ${this.entityData.metadata.displayName.toLocaleLowerCase()} have been created`,
            columns: [{
                name: "Main",
                title: "Label",
                css: "-title -two-lines",
                dataFieldNames: ["Title"],
                componentData: {
                    type: MainFieldComponent,
                    properties: {
                        hasStatusIcon: false
                    }
                },
                clickable: true
            }, {
                name: "Trigger",
                title: "Trigger",
                css: "-col-size-l -two-lines",
                componentData: {
                    type: TextFieldComponent,
                    properties: {
                        propertyPath: "Name"
                    }
                }
            }, {
                name: "Action",
                title: "Action",
                css: "-col-size-xl -two-lines",
                componentData: {
                    type: MultiValueTextFieldComponent,
                    properties: {
                        propertyPath: "Name",
                        additionalValuesPropertyPaths: ["Parameters.Url"],
                        valueCss: "-sf-txt-dimmed",
                        additionalValuesCss: "-sf-overflow-ellipsis"
                    }
                }
            }, {
                name: "SuccessfulRunsCount",
                title: `Successful runs in last ${SERVICE_HOOKS_HISTORY_DAYS_COUNT} days`,
                css: "-col-size-xs -two-lines -sf-pr-2xs -sf-pl-2xs",
                dataFieldNames: ["SuccessfulRunsCount"],
                componentData: {
                    type: ChildrenCountComponent,
                    properties: {
                        childRouteName: "history",
                        queryParams: {[FILTER_PARAMS.FILTER]: "success"},
                        maxCount: 10000,
                        look: "positive"
                    }
                }
            }, {
                name: "FailedRunsCount",
                title: `Failed runs in last ${SERVICE_HOOKS_HISTORY_DAYS_COUNT} days`,
                css: "-col-size-2xs -two-lines",
                dataFieldNames: ["FailedRunsCount"],
                componentData: {
                    type: ChildrenCountComponent,
                    properties: {
                        childRouteName: "history",
                        queryParams: {[FILTER_PARAMS.FILTER]: "fail"},
                        maxCount: 10000,
                        look: "negative"
                    }
                }
            }, {
                name: "Actions",
                title: "",
                css: "-action -col-size-3xs -two-lines",
                dataFieldNames: ["Title"],
                componentData: {
                    type: GridActionMenuComponent,
                    properties: {
                        operations$: this.getOperations()
                    }
                }
            }],
            operations: of([{
                Actions: [],
                Category: {
                    Name: "Default",
                    Title: null
                },
                Name: "Create",
                Ordinal: -1,
                Title: `Create a ${this.entityData.metadata.singularName.toLocaleLowerCase()}`
            }]),
            singularName: "service hook",
            pluralName: "service hooks",
            emptyScreenIcon: "file-text-o",
            isLoadMoreSearchEnabled: false,
            isLoadMoreFilterEnabled: false,
            notificationFilter: this.entityData.metadata.typeFullName
        };
    }

    getOperations(): Observable<Operation[]> {
        const deleteOperation: Operation = {
            Title: OPERATION_NAMES.delete,
            Name: OPERATION_NAMES.delete,
            DetailedTitle: `${OPERATION_NAMES.delete} this ${this.entityData.metadata.singularName.toLocaleLowerCase()} permanently?`,
            RequiresConfirmation: true,
            ExecuteOnServer: true,
            PerformsDelete: true,
            Category:
            {
                Name: OPERATION_NAMES.delete
            },
            Actions: [
                {
                    Title: `${OPERATION_NAMES.delete} ${this.entityData.metadata.singularName.toLocaleLowerCase()}`,
                    Name: "deleteServiceHook",
                    Type: 2
                }
            ]
        };
        const propertiesOperation: Operation = {
            Title: OPERATION_TITLES.properties,
            Name: OPERATION_TITLES.properties,
            Category:
            {
                Name: OPERATION_TITLES.properties
            }
        };
        const historyOperation: Operation = {
            Title: OPERATION_TITLES.runsHistory,
            Name: OPERATION_NAMES.history,
            Category:
            {
                Name: OPERATION_NAMES.history
            }
        };
        return of([propertiesOperation, historyOperation, deleteOperation]);
    }

    getListDetailsModel(getListDetailsModel: GetListDetailsModelArgs): ListDetailsModel {
        const isEdit = getListDetailsModel.detailsMode === LIST_INDEX_DETAILS_MODES.EDIT;
        return {
            title: isEdit ? "Edit service hook" : "Create a service hook",
            name: INTEGRATION_MODULE_MODEL_NAMES.SERVICE_HOOKS,
            propertyMetadata: [{
                Name: "Main",
                Title: null,
                Properties: [
                    {
                        Name: "Title",
                        Title: "Label",
                        Type: "string",
                        DefaultValue: null,
                        Properties: {
                            "Meta_Description_Description": "Labels help you identify service hooks.",
                            "Validations_Required": true,
                            "Validations_RequiredErrorMsg": FieldValidation.getRequiredMessage("Label"),
                            "Validations_MaxValue": 255,
                            "Validations_MaxLengthErrorMsg": FieldValidation.getMaxLengthMessage(255)
                        }
                    },
                    {
                        Name: "Trigger",
                        Title: "Trigger",
                        Type: "choiceParameterizedSelector",
                        DefaultValue: null,
                        Properties: {
                            "Meta_Description_Description": "The trigger defines when the service hook is executed. Example: Execute the service hook each time a form is submitted.",
                            "Meta_Template": "chips",
                            "Meta_SelectorFilterProperty": "Module",
                            "Meta_RecentProperty": "Priority",
                            "Meta_RecentCount": 5,
                            "Validations_Required": true,
                            "Meta_LoaderHeight": 1,
                            "Meta_ShouldHideBottomBorder": true,
                            "Meta_ChipAddButtonTitle": "Select trigger"
                        }
                    },
                    {
                        Name: "Action",
                        Title: "Action",
                        Type: "choiceParameterizedSelector",
                        DefaultValue: `{
                            "Name": "Send data to URL",
                            "Value": "servicehooksmodule:webhookaction",
                            "Parameters": {}
                        }`,
                        Properties: {}
                    }
                ]
            }],
            hasSaveButton: true,
            saveButtonText: isEdit ? "Save changes" : "Create this hook",
            cancelButtonText: "Cancel"
        };
    }

    tryExecuteOperation(dataItem: DataItem, button: ActionButton, activatedRoute?: ActivatedRoute): Observable<ListIndexOperationResult> {
        if (button.name === OPERATION_NAMES.history) {
            return new Observable(operationResult => {
                this.router.navigate([dataItem.key, button.name.toLowerCase()], { relativeTo: activatedRoute }).then(navigated => {
                    operationResult.next({
                        isExecuted: navigated,
                        requiresReload: false
                    });
                });
            });
        }

        return super.tryExecuteOperation(dataItem, button, activatedRoute);
    }
}
