import { Injectable, Inject } from "@angular/core";
import Cropper from "cropperjs/dist/cropper.esm.js";
import { ReplaySubject } from "rxjs";
import { WINDOW_TOKEN } from "../../../../window.provider";

export const ROTATION_DEGREE = 90;
const MIN_CONTAINER_DIMENSIONS = 1;
const CROP_EVENT = "crop";

@Injectable()
export class CropService {
    public dimensionsChanged: ReplaySubject<CropResult> = new ReplaySubject<CropResult>(1);

    private cropper: Cropper;
    private contentType: string;
    private onCropEventListener: EventListener;

    constructor(@Inject(WINDOW_TOKEN) private window: Window) {

    }

    init(img: HTMLImageElement, fileContentType: string) {
        this.destroy();
        this.contentType = fileContentType;

        const cropper = new Cropper(img, {
            checkCrossOrigin: false,
            movable: false,
            scalable: false,
            zoomable: false,
            modal: false,
            guides: false,
            center: false,
            highlight: false,
            background: false,
            minContainerWidth: MIN_CONTAINER_DIMENSIONS,
            minContainerHeight: MIN_CONTAINER_DIMENSIONS,
            ready: () => {
                const canvasData = this.cropper.getCanvasData();
                cropper.setCropBoxData({
                    width: canvasData.width,
                    height: canvasData.height
                });
                this.centerCropWindow();
            }
        });

        this.cropper = cropper;
        this.cropper.setCropBoxData({
            width: img.width,
            height: img.height
        });

        this.onCropEventListener = () => this.onCrop();
        this.window.addEventListener(CROP_EVENT, this.onCropEventListener);
    }

    destroy(): void {
        if (this.cropper) {
            this.cropper.destroy();
        }

        if (this.onCropEventListener) {
            this.removeEventListeners();
        }
    }

    removeEventListeners() {
        this.window.removeEventListener(CROP_EVENT, this.onCropEventListener);
    }

    getCroppedImageDataUrl(): string {
        const canvas = this.cropper.getCroppedCanvas();
        return canvas.toDataURL(this.contentType);
    }

    rotate(degree: number = ROTATION_DEGREE): RotateResult {
        this.cropper.rotate(degree);
        this.cropper.setCropBoxData({ width: this.cropper.canvasData.width, height: this.cropper.canvasData.height });
        this.centerCropWindow();

        return {
            dataUrl: "",
            width: this.cropper.canvasData.width,
            height: this.cropper.canvasData.height
        };
    }

    resetCropWindow() {
        const data = this.cropper.getContainerData();

        this.cropper.setAspectRatio(0);
        this.cropper.setCropBoxData({
            height: data.height,
            width: data.width,
            left: 0,
            top: 0
        });
    }

    setAspectRatio(aspectRatio: number): void {
        this.cropper.setAspectRatio(aspectRatio);
    }

    centerCropWindow(): void {
        const data = this.cropper.getContainerData();

        if (!data.height || !data.width) {
            return;
        }

        const cropBoxData = this.cropper.getCropBoxData();
        const widthOffset = data.width - cropBoxData.width;
        const heightOffset = data.height - cropBoxData.height;
        const left = widthOffset / 2;
        const top = heightOffset / 2;

        this.cropper.setCropBoxData({
            height: cropBoxData.height,
            width: cropBoxData.width,
            left,
            top
        });
    }

    private onCrop() {
        const cropBoxData = this.cropper.getCropBoxData();
        const cropRatio = this.getCropRatio();
        this.dimensionsChanged.next({
            width: Math.floor(cropBoxData.width * cropRatio.widthCropRatio),
            height: Math.floor(cropBoxData.height * cropRatio.heightCropRatio)
        });
    }

    private getCropRatio(): CropRatio {
        const imageData = this.cropper.getImageData();
        let widthCropRatio = 1;
        let heightCropRatio = 1;
        if (imageData.naturalWidth > imageData.width) {
            widthCropRatio = imageData.naturalWidth / imageData.width;
        }

        if (imageData.naturalHeight > imageData.height) {
            heightCropRatio = imageData.naturalHeight / imageData.height;
        }

        return {
            widthCropRatio: widthCropRatio,
            heightCropRatio: heightCropRatio
        };
    }
}

export interface RotateResult extends CropResult {
    dataUrl: string;
}

export interface CropResult {
    width: number;
    height: number;
}

interface CropRatio {
    widthCropRatio: number;
    heightCropRatio: number;
}
