import { ClassProvider, Injectable } from "@angular/core";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { Properties } from "../../../shared/fields.constants";
import { ActionResult, EditActionContext } from "../../../shared/services/edit/composite-edit-extender";
import { EditExtender, EDIT_EXTENDER_TOKEN } from "../../../shared/services/edit/edit-extender";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { FormsActionHandler } from "../../forms-action-handler.service";

@Injectable()
export class FormsEditExtender extends EditExtender {

    constructor(
        private formsCommonHandler: FormsActionHandler) {
            super();
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.FORMS;
    }

    showHeader(entityData: EntityData): boolean {
        return true;
    }

    excludedProperties(entityData: EntityData): string[] {
        return [Properties.NAME, Properties.TITLE];
    }

    getStatusToDisplay(dataItem: DataItem): any {
        return dataItem.data.DisplayStatus.find(s => s.Message?.Description);
    }

    handleAction(context: EditActionContext): ActionResult {
        const result = this.formsCommonHandler.tryHandleAction(context);

        return {
            handled: result
        };
    }
}

export const FORMS_EDIT_EXTENDER: ClassProvider = {
    multi: true,
    provide: EDIT_EXTENDER_TOKEN,
    useClass: FormsEditExtender
};
