import { ERROR_CODES } from "./error-code.constants";
import { ValidationError } from "./validation-error";

/**
 * Contains information regarding a field validation error.
 *
 * @export
 * @class FieldError
 */
export class FieldError {
    constructor(public fieldName: string, public errorType: any) {
        if (errorType && errorType.InnerFields && errorType.ErrorCode === ERROR_CODES.VALIDATION) {
            this.errorType = new ValidationError({ code: errorType.ErrorCode, message: JSON.stringify(errorType.InnerFields), status: 0 });
        }
    }
}
