import { InjectionToken, ClassProvider } from "@angular/core";
import { ExtendedBackgroundTask, TaskActionButton, TaskStatus, TaskAction } from "../../services/background-task.types";

export const BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN = new InjectionToken("notification_builder");

export abstract class BackgroundTaskNotificationBuilder {
    get isDefault(): boolean {
        return false;
    }

    abstract isTaskSupported(taskName: string): boolean;

    abstract processTask(task: ExtendedBackgroundTask): void;

    abstract filterTasksCallback(task: ExtendedBackgroundTask, propertyMap: {[key: string]: string}): boolean;

    protected abstract buildNotification(task: ExtendedBackgroundTask): string;

    protected abstract buildButtons(task: ExtendedBackgroundTask): TaskActionButton[];
}

export class DefaultTaskNotificationBuilder extends BackgroundTaskNotificationBuilder {
    get isDefault() {
        return true;
    }

    isTaskSupported(taskName: string): boolean {
        return false;
    }

    /**
     * Calls buildNotification and buildButtons. Can be extended to modify the task model further.
     * Should call super.processTask at the end to make sure default processings are taken into account.
     * @param task The task to modify
     */
    processTask(task: ExtendedBackgroundTask) {
        task.Tooltip = this.buildNotification(task);
        task.buttons = this.buildButtons(task);
    }

    filterTasksCallback(task: ExtendedBackgroundTask, propertyMap: {[key: string]: string}) {
        return true;
    }

    protected buildNotification(task: ExtendedBackgroundTask): string {
        return task.StatusMessage;
    }

    protected buildButtons(task: ExtendedBackgroundTask): TaskActionButton[] {
        const buttons = [];
        const status: TaskStatus = TaskStatus[task.Status.toString()];

        if (parseInt(task.ProgressStatus) < 100 && status === TaskStatus.Started) {
            buttons.push({
                action: TaskAction.Stop,
                title: "Stop"
            });
        }

        if (status === TaskStatus.Stopped) {
            buttons.push({
                action: TaskAction.Resume,
                title: "Resume"
            });
        }

        if (status === TaskStatus.Failed) {
            buttons.push({
                action: TaskAction.Delete,
                title: "Close"
            });
        }

        return buttons;
    }
}

export const DEFAULT_NOTIFICATION_BUILDER: ClassProvider = {
    multi: true,
    provide: BACKGROUND_TASK_NOTIFICATION_BUILDER_TOKEN,
    useClass: DefaultTaskNotificationBuilder
};
