import { ResponseError } from "./response-error";
import { FieldError } from "./field-error";
import { ODataError } from "./odata-error";

/**
 * Contains information regarding the validation error from a response to a failed HTTP request.
 *
 * @export
 * @class ValidationError
 * @extends {ResponseError}
 */
export class ValidationError extends ResponseError {
    public fieldErrors: Array<FieldError>;

    constructor(error: ODataError) {
        super(error);

        this.fieldErrors = this.parseFieldErrors(error.message);
    }

    private parseFieldErrors(fieldErrorsJson: string) {
        const errors = this.parseJsonOrDefault(fieldErrorsJson);
        return Object.keys(errors).map(f => new FieldError(f, errors[f]));
    }

    private parseJsonOrDefault(jsonString: string): any {
        try {
            const result = JSON.parse(jsonString);
            return result;
        } catch (ex) {
            return new Object();
        }
    }
}
