import { map, mergeMap } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { HttpDataResponseUtils } from "../../../insight/services/http-data-response-utils";
import { CollectionResponse } from "../../../insight/services/collection-response";
import { Touchpoint } from "../../../insight/entities/touchpoint";
import { TouchpointPeriodMetrics } from "../../../insight/entities/touchpoint-period-metrics";
import { ContentItemInfo } from "../interfaces/content-item-info";
import { SitefinityInsightHttpRequester } from "./sitefinity-insight-http-requester";
import { DateTimeUtilsService } from "./date-time-utils.service";
import { TouchpointStatistic } from "../../../insight/entities/touchpoint-statistics";
import { Attribution } from "../../../insight/entities/attribution";
import { SitefinityRequesterService } from "./sitefinity-requester.service";

@Injectable()
export class SitefinityInsightTouchpointRequesterService {

    private static readonly CONTENT_TOUCHPOINTS_ENDPOINT = "analytics/v1/touchpoints/content";

    constructor(
        private sitefinityInsightHttpClient: SitefinityInsightHttpRequester,
        private dateTimeUtils: DateTimeUtilsService,
        private sitefinityRequesterService: SitefinityRequesterService) {
    }

    public getTouchpointByContent(contentItemInfo: ContentItemInfo): Observable<Touchpoint> {

        const headers = {
            filter: {
                ContentId: contentItemInfo.Id,
                ContentType: contentItemInfo.ContentType,
                ContentProvider: contentItemInfo.Provider
            }
        };

        return this.sitefinityInsightHttpClient.get<CollectionResponse<Touchpoint>>(SitefinityInsightTouchpointRequesterService.CONTENT_TOUCHPOINTS_ENDPOINT, headers).pipe(
            map(HttpDataResponseUtils.firstOrDefault));
    }

    public createContentTouchpoint(defaultCulture: string, contentItemInfo: ContentItemInfo): Observable<Touchpoint> {
        const hasLanguages = contentItemInfo.AvailableLanguages.length > 0;
        const hasTranslationInDefaultLanguage = contentItemInfo.AvailableLanguages.indexOf(defaultCulture) !== -1;

        const touchpoint = {
            Name: contentItemInfo[contentItemInfo.DefaultFieldName],
            ContentId: contentItemInfo.Id,
            ContentType: contentItemInfo.ContentType,
            ContentProvider: contentItemInfo.Provider
        };

        if (!hasLanguages || (defaultCulture === contentItemInfo.CurrentCulture && hasTranslationInDefaultLanguage)) {
            // No available languages (e.g. libraries) OR current language is the default and the item has this translation
            // => create the touchpoint with default field value for the content type
            return this.sitefinityInsightHttpClient.post<Touchpoint>(SitefinityInsightTouchpointRequesterService.CONTENT_TOUCHPOINTS_ENDPOINT, touchpoint, {});
        } else {
            // Query the content item by culture (default or first available) and then create the touchpoint
            const culture = hasTranslationInDefaultLanguage ? defaultCulture : contentItemInfo.AvailableLanguages[0];
            return this.sitefinityRequesterService.getContentItemsDetails(culture, contentItemInfo).pipe(
                map(sfContentItem => {
                    touchpoint.Name = sfContentItem[contentItemInfo.DefaultFieldName];
                    return touchpoint;
                }),
                mergeMap(touchpoint => this.sitefinityInsightHttpClient.post<Touchpoint>(SitefinityInsightTouchpointRequesterService.CONTENT_TOUCHPOINTS_ENDPOINT, touchpoint, {})));
        }
    }

    public hasStatistics(touchpointId: number): Observable<boolean> {
        return this.getDailyStatistics(touchpointId, 5).pipe(
            map(statistics => statistics && statistics.length >= 1));
    }

    public getPeriodMetrics(touchpointId: number, period: string): Observable<TouchpointPeriodMetrics> {
        const headers = {period: period};

        return this.sitefinityInsightHttpClient.get<CollectionResponse<TouchpointPeriodMetrics>>(`analytics/v1/touchpoints/${touchpointId}/period-metrics`, headers)
            .pipe(map(HttpDataResponseUtils.firstOrDefault))
            .pipe(map((touchpointPeriodMetrics) => {
                touchpointPeriodMetrics.Improvement =
                    touchpointPeriodMetrics.UniqueHits_PreviousPeriod
                        ? ((touchpointPeriodMetrics.UniqueHits_CurrentPeriod - touchpointPeriodMetrics.UniqueHits_PreviousPeriod) / touchpointPeriodMetrics.UniqueHits_PreviousPeriod) * 100
                        : null;

                return touchpointPeriodMetrics;
            }));
    }

    public getDailyStatistics(touchpointId: number, periodInDays: number): Observable<TouchpointStatistic[]> {
        const extendedPeriod = periodInDays + 5;
        const {fromDateISOString, toDateISOString} = this.dateTimeUtils.getFromDateAndToDateInclusiveHeaderValue(extendedPeriod);
        const headers = {
            fromDate: fromDateISOString,
            toDate: toDateISOString
        };

        return this.sitefinityInsightHttpClient.get<CollectionResponse<TouchpointStatistic>>(`analytics/v1/touchpoints/${touchpointId}/statistics/daily`, headers)
            .pipe(map(HttpDataResponseUtils.flattenCollectionResponse))
            .pipe(map((touchpointStatistics) => {
                const totalNumberOfStatistics = touchpointStatistics.length;
                const gotMoreStatisticsThenRequestedPeriod = totalNumberOfStatistics - periodInDays > 0;
                if (gotMoreStatisticsThenRequestedPeriod) {
                    return touchpointStatistics.slice(totalNumberOfStatistics - periodInDays);
                } else {
                    return touchpointStatistics;
                }
            }));
    }

    public getAttributions(touchpointId: number, numberOfItemsToTake: number): Observable<Attribution[]> {
        const headers = {
            filter: {TouchpointId: touchpointId},
            take: numberOfItemsToTake,
            sort: {GoalCompletions: -1}
        };

        return this.sitefinityInsightHttpClient.get<CollectionResponse<Attribution>>(`analytics/v1/attributions`, headers).pipe(
            map(HttpDataResponseUtils.flattenCollectionResponse));
    }
}
