import { InjectionToken, Injectable, Optional, Inject } from "@angular/core";
import { EditorConfigProvider, ToolBarItem } from "./editor-config";

export const EDITOR_CONFIG_TOKEN = new InjectionToken("operations_token");

@Injectable()
export class CompositeEditorConfigProvider implements EditorConfigProvider {

    constructor(@Optional() @Inject(EDITOR_CONFIG_TOKEN) private editorConfigProviders: Array<EditorConfigProvider>) {
    }

    getToolBarItems(editorHost: any): ToolBarItem[] {
        if (this.editorConfigProviders !== null) {
            return this.editorConfigProviders
                .map(x => x.getToolBarItems(editorHost))
                .reduce((previous, current) => previous.concat(current));
        }

        return [];
    }

    getToolBarItemsNamesToRemove(): string[] {
        if (this.editorConfigProviders !== null) {
            return this.editorConfigProviders
                .map(x => x.getToolBarItemsNamesToRemove())
                .reduce((previous, current) => previous.concat(current));
        }
    }

    configureEditor(configuration: any): any {
        if (this.editorConfigProviders !== null) {
            return this.editorConfigProviders.reduce((config, x) => {
                if (x.configureEditor) {
                    return x.configureEditor(config);
                } else {
                    return config;
                }
            }, configuration);
        }

        return configuration;
    }
}
