import { FieldBase } from "../../../../../../fields/field-base";
import { Component, OnInit, ViewChild, TemplateRef } from "@angular/core";
import { FieldTypes } from "../../../shared/fields-builder/services/fields-registry";
import { ChoiceDropdownComponent } from "../../../../../../fields/choice/choice-dropdown.component";
import { ChoiceSettings } from "../../../../../../fields/choice/choice.settings";
import { LocalizationStrategySettings } from "./localization-strategy.settings";
import { cloneObject } from "../../../../utils";
import { createFieldModel } from "../../../shared/fields.constants";
import { FieldModel } from "../../../../services/field.model";
import { CompositeFieldsProvider } from "../../../shared/fields-builder/providers/fields-provider";
import { FormControl } from "@angular/forms";

export const LocalizationStrategyProp = "LocalizationStrategy";
const LocalizationStrategyChildProp = "LocalizationStrategyChild";

@Component({
    selector: "sf-localization-selector",
    templateUrl: "./localization-strategy.component.html"
})
export class LocalizationStrategyComponent extends FieldBase<LocalizationStrategySettings> implements OnInit {
    viewModel: ViewModel;

    @ViewChild("copyFromTemplate", { static: true })
    private copyFromTemplate: TemplateRef<any>;
    private localizationValue: LocalizationValue = {};
    private lastSelectedLanguage: string;

    private readonly syncCommand = "sync";
    private readonly copyCommand = "copy";
    private readonly cultureCommand = "culture";

    constructor(private fieldProvider: CompositeFieldsProvider) {
        super();
    }

    ngOnInit() {
        super.ngOnInit();

        const forceSync = (this.settings as LocalizationStrategySettings).forceSync;
        const copySettings = new ChoiceSettings("copyFrom", false);
        copySettings.choices = [
            {
                Name: "Copy content and widgets from...",
                Value: "1",
                ExpandedTemplate: this.copyFromTemplate
            }
        ];

        if (!forceSync) {
            copySettings.choices.push({
                Name: "Start from scratch",
                Value: "2"
            });
        }

        copySettings.defaultValue = copySettings.choices[0].Value;
        const localizationStrategySettings = this.settings as LocalizationStrategySettings;

        if (!localizationStrategySettings.syncAvailable) {
            if (localizationStrategySettings.defaultValue.EnableSync) {
                delete localizationStrategySettings.defaultValue.EnableSync;
            }

            if (!localizationStrategySettings.defaultValue.EnableSplit) {
                localizationStrategySettings.defaultValue.EnableSplit = true;
            }
        }

        const dropdownSettings = ChoiceDropdownComponent.createFieldSettings(localizationStrategySettings.languages, localizationStrategySettings.languages[0].Value, "languageChoice", "sf-mt-3xs");
        this.lastSelectedLanguage = dropdownSettings.defaultValue;

        const model = createFieldModel(this.fieldProvider, "pages", FieldTypes.choiceMultiple, LocalizationStrategyProp, "1", {}, LocalizationStrategyChildProp, null, this.settings.readOnlyMode);
        const keepSyncedSettings = model.settings as ChoiceSettings;
        keepSyncedSettings.choices = [
            {
                Name: "Keep all language versions synced as one page",
                Value: "1"
            }
        ];

        keepSyncedSettings.showTitle = false;
        keepSyncedSettings.updateHasFieldset("1");

        this.viewModel = {
            copySettings: copySettings,
            dropdownSettings: dropdownSettings,
            keepSyncedModel: model,
            keepSyncedFormControl: new FormControl(false)
        };
    }

    onSelectionChange(data: any, source: string): void {
        if (source === this.syncCommand) {
            this.localizationValue.EnableSync = (data === "1");
            if (this.localizationValue.EnableSync) {
                delete this.localizationValue.EnableSplit;
                delete this.localizationValue.CopyFrom;
            } else {
                delete this.localizationValue.EnableSync;
                this.localizationValue.EnableSplit = true;
                this.localizationValue.CopyFrom = this.lastSelectedLanguage;
            }
        } else if (source === this.copyCommand) {
            if (data === "1") {
                delete this.localizationValue.EnableSplit;
                this.localizationValue.EnableSync = true;
                this.localizationValue.CopyFrom = this.viewModel.dropdownSettings.defaultValue;
            } else {
                delete this.localizationValue.EnableSync;
                this.localizationValue.EnableSplit = true;
                delete this.localizationValue.CopyFrom;
            }
        } else if (source === this.cultureCommand) {
            this.lastSelectedLanguage = data;
            this.localizationValue.CopyFrom = data;

            if (!this.localizationValue.EnableSync) {
                this.localizationValue.EnableSplit = true;
            }
        }

        const copy = cloneObject(this.localizationValue);
        this.writeValue(copy);
    }
}

interface ViewModel {
    copySettings: ChoiceSettings,
    dropdownSettings: ChoiceSettings,
    keepSyncedModel: FieldModel,
    keepSyncedFormControl: FormControl
}

interface LocalizationValue {
    CopyFrom?: string,
    EnableSync?: boolean
    EnableSplit?: boolean;
}
