import { of, Subject, combineLatest, Subscription } from "rxjs";
import {
    Component, OnChanges, DoCheck, Input, ViewChildren, QueryList, AfterViewInit, Inject,
    ViewEncapsulation,
    ChangeDetectorRef,
    Output,
    EventEmitter
} from "@angular/core";
import { FormGroup, FormControl, ValidatorFn } from "@angular/forms";
import { Observable } from "rxjs";
import { FieldSectionModel } from "../../../../../services/fieldSection.model";
import { FormFieldWrapperComponent } from "../field-wrapper/form-field-wrapper.component";
import { FieldModel } from "../../../../../services/field.model";
import { ValidationError } from "../../../services/errors/validation-error";
import { MirrorService } from "../../services/mirror.service";
import { WINDOW_TOKEN } from "../../../../../window.provider";
import { StatusType } from "../../../../../../../fields/field-status";
import { FieldTypes } from "../../services/fields-registry";
import { FieldValidation } from "../../../../../../../fields/field-validation";
import { DataItem } from "../../../../content/dynamic-modules/interfaces";
import { ToggleSectionState } from "../field-section/field-section.component";
import { LOCAL_STORAGE, StorageService } from "../../../services/storage.service";
import { CUSTOM_ERROR_PREFIX, VALIDATOR_MESSAGES } from "../../../../../../../fields/common/validators/validators.constants";
import { Status } from "../../../../../../../fields/field-base";
import { CompositeFieldSettings } from "../../../services/composite-field.settings";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../services/field-change/field-change.service";
import { getCssVariableValueAsNumber } from "../../../../../utils";
import { CSS_VARIABLES } from "../../../../content/constants";
import { RuleConditionOperator, RuleOperator } from "../../../../../../../fields/field-settings-base";
import { DynamicTemplateDirective } from "./dynamic-template.directive";
import { Properties } from "../../../fields.constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { first, tap } from "rxjs/operators";

export const SECTIONS_KEY: string = "sections";

@Component({
    selector: "sf-editable-fields",
    templateUrl: "./editable-fields.component.html",
    styleUrls: ["./editable-fields.component.scss"],
    encapsulation: ViewEncapsulation.None
})
export class EditableFieldsComponent extends SfRxBase implements OnChanges, DoCheck, AfterViewInit {
    @Input() fieldSections: FieldSectionModel[];
    @Input() hiddenFields: FieldModel[];
    @Input() copyMode: boolean;
    @Input() formValidators: ValidatorFn | ValidatorFn[];
    @Input() allowDialogOpenCallback: () => Observable<boolean>;
    @Input() moduleName: string;
    @Input() shouldResetMirroring: boolean = true;
    @Input() contentLoaderHeight: number = getCssVariableValueAsNumber(CSS_VARIABLES.EDITOR_INLINE_HEIGHT_LONG, "sf-app") || 300;
    @Output() sectionToggle = new EventEmitter<ToggleSectionState>();

    @ViewChildren(DynamicTemplateDirective) private dynamicTemplates: QueryList<DynamicTemplateDirective>;

    @Output() fieldChange: EventEmitter<ValueChange> = new EventEmitter<ValueChange>();
    public htmlFieldType: string = FieldTypes.html;
    public errorMessages: string[];

    @ViewChildren(FormFieldWrapperComponent) private wrapperComponentsQuery: QueryList<FormFieldWrapperComponent>;
    form: FormGroup = new FormGroup({});
    private _dirty = new Subject<boolean>();
    private wasFormDirty: boolean;
    private wrapperComponents: FormFieldWrapperComponent[];
    private toBeMarkedAsDirty: string[] = [];
    private boundFields: { masterFieldKey: string, conditionalFieldKey: string }[] = [];
    private initialFieldCheck: boolean = false;

    private cachedFieldValues = {};

    constructor(
        @Inject(WINDOW_TOKEN) protected window: Window,
        protected mirrorService: MirrorService,
        protected detector: ChangeDetectorRef,
        @Inject(LOCAL_STORAGE) protected storage: StorageService,
        @Inject(FIELDS_CHANGE_SERVICE_TOKEN) protected fieldChangeHandlers: FieldChangeService[]) {
        super();
    }

    get dirty(): Observable<boolean> {
        return this._dirty.asObservable();
    }

    get status(): Observable<StatusType> {
        const statuses = this.wrapperComponents.map(wc => wc.status);

        if (!statuses.length) {
            return of(StatusType.Done);
        }

        return combineLatest(...statuses, (...emittedStatuses: Status[]) => {
            let statusType = StatusType.Done;

            for (let i = 0; i < emittedStatuses.length; i++) {
                const status = emittedStatuses[i];
                if (status.type === StatusType.ErrorCleared)
                    status.type = StatusType.Done;

                if (status.type !== StatusType.Done) {
                    statusType = status.type;
                    break;
                }
            }

            return statusType;
        });
    }

    ngAfterViewInit() {
        this.setWrapperComponents(this.wrapperComponentsQuery.toArray());

        // This method should be called both here and inside the subscribtion.
        // The reason is the fields are initialized when the operations subscribtion
        // is executed. This could happen either before or after the view is initialized.
        // In the first scenario the fields will be changed before the current method is called
        // and before we are subscribed to their changes. Therefore we need to mark them as dirty
        // outside the subscription and we can do this because they are already initialized.
        this.handleCopyMode();

        const changeSubscription = this.wrapperComponentsQuery.changes.subscribe((values: QueryList<FormFieldWrapperComponent>) => {
            this.setWrapperComponents(values.toArray());
            this.handleCopyMode();

            if (this.initialFieldCheck) {
                this.initialFieldCheck = false;
                this.processConditionalFields();
            }

            this.disableHiddenFieldsFromForm();
            this.registerSubscription(this.handleChangesToFieldsVisibility(values.toArray()));
        });

        this.registerSubscription(changeSubscription);

        if (this.formValidators) {
            this.form.setValidators(this.formValidators);
            const statusSubscription = this.form.statusChanges.subscribe((data) => {
                // TODO: possibly implement a filter if there is need to filter the errors here based on some sort of configuration
                // like an input property for example
                this.processErrors(this.form.errors);
            });

            this.registerSubscription(statusSubscription);
        }

        this.registerSubscription(this.handleChangesToFieldsVisibility(this.wrapperComponentsQuery.toArray()));
    }

    onChange(value, key, section?) {
        // TODO: this should be removed and replaced with the FormControl's ValueChanges
        const sectionSettings = section ? section.settings : {};
        const changeObj: ValueChange = {
            key,
            value,
            sectionTitle: sectionSettings.title,
            sectionName: sectionSettings.name
        };

        if (this.wrapperComponents) {
            this.mirrorService.mirrorValue(value, key, this.wrapperComponents, this.copyMode);
            this.processFieldChanges(key, value);

            const fields = this.wrapperComponents.map(c => c.fieldModel);

            // Mirror for the conditional fields.
            this.fieldSections.forEach(s => s.fields.forEach(f => {
                if (f.settings.conditionalRule) {
                    const fieldToMirror = fields.find(x => x.key === key);
                    if (fieldToMirror) {
                        fieldToMirror.value = value;
                        this.mirrorService.determineShouldMirrorField(f, fields);
                    }
                }
            }));
        }

        this.processConditionalFields();

        this.fieldChange.emit(changeObj);
    }

    setMarkAsDirty(value, key: string) {
        if (value && this.form.controls[key]) {
            // if the form control is marked as dirty, there are problems with navigation because there seem to be unsaved changes
            if (this.toBeMarkedAsDirty.indexOf(key) < 0) {
                this.toBeMarkedAsDirty.push(key);
            }
        }
    }

    writeValueToField(key: string, value: any) {
        const wrapperComponent = this.wrapperComponents.find(w => w.fieldModel.key == key);
        wrapperComponent.writeValue(value);
    }

    ngOnChanges(changes: any): void {
        const change = changes.fieldSections.currentValue;
        let fields = [];

        if (change && change instanceof Array) {
            let sectionState: Object = {};
            const sections = this.getSectionsState();

            if (sections.hasOwnProperty(this.moduleName)) {
                sectionState = sections[this.moduleName];
            }

            change.forEach((s: FieldSectionModel) => {
                fields = fields.concat(s.fields);

                if (sectionState && sectionState[s.settings.name] !== undefined) {
                    s.settings.isExpanded = sectionState[s.settings.name];
                }
            });

            if (this.shouldResetMirroring) {
                this.mirrorService.resetMirroring();
            }

            fields.forEach((f: FieldModel) => {
                this.mirrorService.determineShouldMirrorField(f, fields);
                this.form.setControl(f.key, new FormControl(f.value, { validators: f.settings.validators }));
            });

            this.createFieldConditions();
            this.processConditionalFields();
        }
    }

    ngDoCheck() {
        if (!this.wasFormDirty && this.form && this.form.dirty) {
            this.wasFormDirty = true;
            this._dirty.next(true);
        }
    }

    /**
     * Validates the fields in the form synchronously. This has some issues with certain nested forms.
     */
    valid(shouldScrollToFirstErrorField: boolean = true): boolean {
        const formValid = this.validateInternal(shouldScrollToFirstErrorField);

        return formValid;
    }

    /**
     * Validates the fields form and makes sure the nested forms had finished emitting statuses.
     */
    validateAsync(shouldScrollToFirstErrorField: boolean = true): Observable<boolean> {
        return new Observable(obs => {
            const formValid = this.validateInternal(shouldScrollToFirstErrorField);

            const statusSubsciptions = this.wrapperComponents.map(w => w.status.pipe(first()));

            if (!statusSubsciptions.length) {
                obs.next(formValid);
                return;
            }

            combineLatest(statusSubsciptions).pipe(first(), tap((statusArray: Status[]) => {
                const anyInvalid = statusArray.some(x => x.type === StatusType.Error);
                obs.next(formValid && !anyInvalid);
            })).subscribe();
        });
    }

    getFields(onlyDirty: boolean = true): any {
        const editedFields = {};

        Object.keys(this.form.controls).forEach((property) => {
            const field = this.wrapperComponents.find(x => x.fieldModel.key === property);
            const isDirty = this.form.controls[property].dirty || this.toBeMarkedAsDirty.indexOf(property) >= 0;
            let fieldValue = field ? field.getValue() : null;
            const hasValue = fieldValue !== null && fieldValue !== undefined;
            const isHidden = !field && this.boundFields.findIndex(f => f.conditionalFieldKey === property) !== -1;
            if ((!isDirty && !hasValue) || isHidden) {
                return;
            }

            const shouldReturn = field && field.fieldModel.settings.isVisible && (!onlyDirty || isDirty);

            if (shouldReturn) {
                const isCompositeValue = field.fieldModel.settings instanceof CompositeFieldSettings;
                if (isCompositeValue) {
                    fieldValue = field.postProcessValue(fieldValue);
                    if (fieldValue) {
                        Object.keys(fieldValue).forEach((compositeProp) => {
                            if (fieldValue[compositeProp] !== undefined) {
                                editedFields[compositeProp] = fieldValue[compositeProp];
                            }
                        });
                    }
                } else {
                    fieldValue = field.postProcessValue(this.form.value[property]);
                    editedFields[property] = fieldValue;
                }
            }
        });

        return Object.keys(editedFields).length ? editedFields : null;
    }

    reset(pristineItem?: { [key: string]: string }): void {
        this.toBeMarkedAsDirty = [];
        if (this.wasFormDirty) {
            if (pristineItem) {
                const values = Object.keys(this.form.controls).reduce((obj, controlKey) => {
                    obj[controlKey] = pristineItem[controlKey] || this.form.controls[controlKey].value;
                    return obj;
                }, {});

                this.form.setValue(values);
            }

            this.wasFormDirty = false;

            // form.reset() detaches all validators from fields' values and causes errors on subsequent validations. Use form.markAsPristine() instead
            this.form.markAsPristine();
            this._dirty.next(false);
            this.copyMode = false;
        }

        this.createFieldConditions();
        this.processConditionalFields();
    }

    addModelErrors(error: ValidationError) {
        if (error.fieldErrors) {
            for (const fieldError of error.fieldErrors) {
                const control = this.form.controls[fieldError.fieldName];
                if (!control)
                    return;

                let errors = control.errors || new Object();
                if (fieldError.errorType instanceof ValidationError) {
                    // Propagate child validation error
                    errors = fieldError.errorType;
                }
                if (fieldError.errorType instanceof Object) {
                    errors[CUSTOM_ERROR_PREFIX + VALIDATOR_MESSAGES.CUSTOM_ERRORS] = fieldError.errorType;
                } else {
                    // we use this prefix to mark custom errors, to show some validation to the user
                    errors[CUSTOM_ERROR_PREFIX + fieldError.errorType.toLowerCase()] = fieldError.errorType;
                }

                control.setErrors(errors);
            }
        }
    }

    /**
     * Used to commit the current values of the fields manually
     * so that the vaidation could be triggered on silent commands via keyboard keys
     */
    commitValues() {
        this.wrapperComponents.forEach(w => w.commitValue());
    }

    updateValues(value: { [key: string]: any }) {
        this.form.patchValue(value);
        this.form.markAsPristine();

        // when silent update of the field hits here, we need to update the conditional fields as well
        this.processConditionalFields();
    }

    updateFieldModel(field: FieldModel) {
        this.fieldSections.forEach(s => {
            const foundFieldIndex = s.fields.findIndex(f => f.key === field.key);
            if (foundFieldIndex > -1) {
                s.fields[foundFieldIndex] = field;
            }
        });
    }

    getDirtyFields() {
        return this.getDirtyFieldsKeys();
    }

    public updateMirroring(sections: FieldSectionModel[], dataItem: DataItem): void {
        sections.forEach(section => {
            section.fields.forEach(field => {
                const isToMirror = this.mirrorService.isFieldAvailableForMirroring(dataItem, field);
                this.mirrorService.updateMirroring(field, isToMirror);
            });
        });
    }

    public enableRequiredErrorCheck() {
        if (this.wrapperComponents) {
            this.wrapperComponents.forEach(wrapper => wrapper.enableRequiredErrorCheck = true);
        }
    }

    public triggerErrors() {
        if (this.wrapperComponents) {
            this.wrapperComponents.forEach(wrapper => wrapper.hasErrors());
        }
    }

    // Triggers editable field validation and return the valid state
    public triggerValidCheck(): boolean {
        this.commitValues();
        this.enableRequiredErrorCheck();

        return this.valid();
    }

    handleChangesToFieldsVisibility(values: FormFieldWrapperComponent[]): Subscription {
        return combineLatest(values.map(x => {
            return x.onFieldVisibilityChange$;
        })).subscribe(fieldsHiddenFlagsArray => {
            this.fieldSections.forEach((section) => {
                const isAnyFieldVisible = section.fields.some(sectionField => {
                    return fieldsHiddenFlagsArray.find(fieldsHiddenFlagsEntry => !fieldsHiddenFlagsEntry.isHidden && fieldsHiddenFlagsEntry.key === sectionField.key);
                });
                section.settings.isHidden = !isAnyFieldVisible;
            });
        });
    }

    protected toggleSection(sectionState: ToggleSectionState) {
        if (this.moduleName) {
            const sections = this.getSectionsState();
            const section = sections[this.moduleName] || {};

            section[sectionState.sectionName] = sectionState.isExpanded;
            sections[this.moduleName] = section;

            this.storage.setItem(SECTIONS_KEY, JSON.stringify(sections));
        }

        this.sectionToggle.emit(sectionState);
    }

    protected removeFormControls(keys: string[]) {
        keys.forEach((key: string) => {
            this.form.removeControl(key);
        });
    }

    private validateInternal(shouldScrollToFirstErrorField: boolean): boolean {
        this.form.updateValueAndValidity();

        let isFirstError = true;
        let areFieldsValid = true;
        for (let i = 0; i < this.wrapperComponents.length; i++) {
            const field = this.wrapperComponents[i];
            // even though we have expanded the first field that has errors we continue in order to expand the other fields in other sections as well
            if (field.hasErrors()) {
                areFieldsValid = false;
                const fieldSectionToExpand = this.fieldSections.find((s) => s.fields.indexOf(field.fieldModel) !== -1);
                if (fieldSectionToExpand && fieldSectionToExpand.settings) {
                    fieldSectionToExpand.settings.isExpanded = true;
                }

                // in the case when we have complex fields which have editable fields component of their own
                // we would not want to scroll to first error field in them but rather let the editable fields component on top
                // level handle this scrolling
                if (isFirstError && shouldScrollToFirstErrorField) {
                    isFirstError = false;
                    // we use this because we need to wait for angular to bind the value above and render the view.
                    // Otherwise it will try to scroll to the field before it is shown.
                    this.window.setTimeout(() => { field.scrollToField(); });
                }
            }
        }

        return areFieldsValid && this.form.valid;
    }

    private setWrapperComponents(components: FormFieldWrapperComponent[]) {
        this.wrapperComponents = components;
        this.wrapperComponents.forEach((component) => {
            component.registerAllowDialogOpenCallback(this.allowDialogOpenCallback);
            component.invokeOutputTemplateCallback(this.dynamicTemplates);

            if (this.hiddenFields) {
                this.hiddenFields.forEach((f: FieldModel) => {
                    const hiddenComponent = this.wrapperComponents.find(component => component.fieldModel.key === f.key);
                    if (!hiddenComponent || (hiddenComponent && hiddenComponent.hidden)) {
                        this.form.setControl(f.key, new FormControl(f.value, { validators: f.settings.validators }));
                    }
                });
            }

            this.processFieldChanges(component.fieldModel.key, component.getValue());
        });
    }

    private processErrors(errors: any) {
        this.errorMessages = new FieldValidation(this).getErrorMessage(errors);
    }

    private getSectionsState(): Object {
        let sectionsState = this.storage.getItem(SECTIONS_KEY);
        sectionsState = sectionsState ? JSON.parse(sectionsState) : {};

        return sectionsState;
    }

    private handleCopyMode() {
        if (this.copyMode) {
            // copy mode is active only on creating an item
            // we are not intreseted in subsequent changes to the wrapper controls
            this.wrapperComponents.forEach((wrapper) => {
                wrapper.formControl.markAsDirty();
            });

            // avoid ExpressionChangedAfterItHasBeenCheckedError
            this.detector.detectChanges();
        }
    }

    private disableHiddenFieldsFromForm() {
        Object.keys(this.form.controls).forEach(key => {
            const formFieldWrapper = this.wrapperComponents.find(x => x.fieldModel.key === key);
            const formControl = this.form.controls[key];
            if (formControl) {
                if (!formFieldWrapper) {
                    formControl.disable();
                } else {
                    formControl.enable();
                }
            }
        });

        // avoid ExpressionChangedAfterItHasBeenCheckedError
        this.detector.detectChanges();
    }

    private getDirtyFieldsKeys(): string[] {
        const dirtyFields = [];
        Object.keys(this.form.controls).forEach((property) => {
            const field = this.wrapperComponents.find(x => x.fieldModel.key === property);
            const isDirty = this.form.controls[property].dirty;
            // field is undefined if it has been made dirty, but is then hidden via the conditional if
            // if so - we do not want to send it to the server
            if (isDirty && field) {
                dirtyFields.push(field.fieldModel.key);
            }
        });

        return dirtyFields;
    }

    private processConditionalFields(): void {
        const foundConditionalFields: { [key: string]: FieldModel } = {};
        const foundMasterFields: { [key: string]: FieldModel } = {};
        // we cycle and map the needed master and slave fields once
        // in order to prevent multiple nested for cycles
        this.boundFields.forEach(f => {
            this.fieldSections.forEach(section => {
                section.fields.forEach(fieldModel => {
                    if (!foundMasterFields[fieldModel.key] && f.masterFieldKey === fieldModel.key) {
                        foundMasterFields[fieldModel.key] = fieldModel;
                    } else if (!foundConditionalFields[fieldModel.key] && f.conditionalFieldKey === fieldModel.key) {
                        foundConditionalFields[fieldModel.key] = fieldModel;
                    }
                });
            });
        });

        // for each conditional field we want to evaluate the rules based on all of its respective master field
        // regardless which master field had changed value
        // eslint-disable-next-line guard-for-in
        for (const conditionalFieldKey in foundConditionalFields) {
            const conditionalField = foundConditionalFields[conditionalFieldKey];
            const conditionsEvaluations: boolean[] = [];
            const rule = conditionalField.settings.conditionalRule;
            const operator = rule.operator;
            let shouldHideOnlyContentOfField: boolean = false;

            rule.conditions.forEach(condition => {
                shouldHideOnlyContentOfField = condition.hideContent;
                // checking the wrappers for the case of tests that have not initialized fields yet, but the value could be used
                const foundField = this.wrapperComponents ? this.wrapperComponents.find(w => w.fieldModel.key === condition.fieldName) : null;
                let result;
                if (!foundField && !conditionalField) {
                    result = false;
                } else {
                    let value;

                    if (foundField) {
                        value = foundField.getValue();
                    } else {
                        const foundFieldFromCache = foundMasterFields[condition.fieldName];
                        if (foundFieldFromCache) {
                            value = FormFieldWrapperComponent.normalizeValue(foundFieldFromCache, foundFieldFromCache.value).value;
                        } else {
                            // this is the case when in widget designer
                            // another editable fields is opened in advanced settings
                            return;
                        }
                    }
                    condition.value = condition.value && condition.value.toLocaleLowerCase ? condition.value.toLocaleLowerCase() : condition.value;
                    value = value && value.toLocaleLowerCase ? value.toLocaleLowerCase() : value;

                    if (condition.operator === RuleConditionOperator.Equals) {
                        result = value === condition.value;
                    } else if (condition.operator === RuleConditionOperator.NotContains) {
                        result = !value || !value.includes || !value.includes(condition.value);
                    } else if (condition.operator === RuleConditionOperator.NotEquals) {
                        result = value !== condition.value;
                    } else {
                        // (condition.operator === RuleConditionOperator.Contains)
                        result = !!value && value.includes && value.includes(condition.value);
                    }
                }

                conditionsEvaluations.push(result);
            });

            const result = conditionsEvaluations[0];
            const finalResult = conditionsEvaluations.reduce((p, c) => {
                if (operator === RuleOperator.And) {
                    return p && c;
                } else {
                    // operator === RuleOperator.Or) {
                    return p || c;
                }
            }, result);

            const changingVisibility = finalResult !== conditionalField.settings.isVisible;

            if (changingVisibility && !finalResult) {
                this.form.get(conditionalFieldKey).updateValueAndValidity();
                this.cacheFieldValues(conditionalField);
            }

            if (shouldHideOnlyContentOfField) {
                conditionalField.settings.isVisibleContent = finalResult;
            } else {
                conditionalField.settings.isVisible = finalResult;
            }

            if (finalResult) {
                this.form.get(conditionalFieldKey).setValidators(conditionalField.settings.validators);
            } else {
                this.form.get(conditionalFieldKey).clearValidators();
            }
            this.form.get(conditionalFieldKey).updateValueAndValidity();

            if (changingVisibility && finalResult) {
                this.getCachedValues(conditionalField);
            }

            this.fieldSections.forEach((section) => {
                // There are sections with one field such as the Address field and we need to set isHidden for the section to
                // be able to hide/show the section.
                if (section.fields.some(x => x === conditionalField) && conditionalField.settings.isVisible) {
                    section.settings.isHidden = !conditionalField.settings.isVisible;
                } else if (!section.settings.isHidden) {
                    // isHidden comes as a configuation from the server
                    // if it is set to true, we do not change it ever
                    // if not we reuse this flag to show or hide the section if all of the fields are hidden
                    const isAnyFieldVisible = section.fields.some(x => x.settings.isVisible);
                    section.settings.isHidden = !isAnyFieldVisible;
                }
            });
        }
    }

    /**
     * Creates a mapping between dependent fields as few times as possilbe,
     * so we would not risk multiple iterations over the field sections.
     */
    private createFieldConditions(): void {
        if (!this.fieldSections) {
            return;
        }

        this.boundFields = [];
        const fields: FieldModel[] = [];

        this.fieldSections.forEach(s => {
            fields.push(...s.fields);

            s.fields.filter(f => {
                return f.settings.conditionalRule &&
                    f.key !== Properties.URL_NAME &&
                    !(f.settings.dataItem && f.key === f.settings.dataItem.metadata.defaultFieldName);
            }).forEach(f => {
                const rule = f.settings.conditionalRule;
                rule.conditions.forEach(c => {
                    this.boundFields.push({ masterFieldKey: c.fieldName, conditionalFieldKey: f.settings.key });
                });
            });
        });

        this.boundFields.forEach((f, i) => {
            if (!fields.some(x => x.key === f.masterFieldKey)) {
                const conditionalField = fields.find(field => f.conditionalFieldKey === field.key);
                conditionalField.settings.conditionalRule = undefined;
                this.boundFields.splice(i, 1);
                throw `Invalid source field name in conditional rule for field with key '${f.conditionalFieldKey}'`;
            }
        });
    }

    private cacheFieldValues(fieldModel: FieldModel) {
        if (!this.wrapperComponents) {
            return;
        }

        const fieldWrapper = this.wrapperComponents.find(f => f.fieldModel.key === fieldModel.key);

        if (!fieldWrapper) return;

        if (fieldWrapper.formControl.dirty) {
            let value = fieldWrapper.getValue();

            // fix for rich text field value getter
            if (fieldWrapper.fieldModel.selector === "sf-wrapper-html" && value === null) {
                value = (fieldWrapper as any).value;
            }
            this.cachedFieldValues[fieldModel.key] = value;
        }
    }

    private getCachedValues(fieldModel: FieldModel) {
        this.fieldSections.forEach(s => {
            s.fields.forEach(f => {
                if (f.key === fieldModel.key && fieldModel.key in this.cachedFieldValues) {
                    f.value = this.cachedFieldValues[fieldModel.key];
                }
            });
        });

        delete this.cachedFieldValues[fieldModel.key];
    }

    private processFieldChanges(fieldKey: string, fieldValue: string) {
        this.fieldChangeHandlers.forEach(h => {
            if (h.canProcess((this.wrapperComponents[0] &&
                this.wrapperComponents[0].fieldModel.settings.entityData &&
                this.wrapperComponents[0].fieldModel.settings.entityData.metadata.typeFullName || this.moduleName)
                || this.getFieldChangeId())) {
                h.processChange(fieldKey, fieldValue, this.wrapperComponents);
            }
        });
    }

    protected getFieldChangeId() : string {
        return undefined;
    }
}

export interface ValueChange {
    key: string;
    value: any;
    sectionTitle: string;
    sectionName: string;
    isSectionRemoved?: boolean;
}
