import { Injectable } from "@angular/core";

import { SitefinitySdk } from "../../../services/sitefinitySdk.service";
import { TITLE_KEY } from "../../shared/services/hierarchical-service";
import { SORT_ORDER } from "../../content/constants";
import { ErrorParserService } from "../../shared/services/errors/error-parser.service";
import { Taxonomy, Taxon } from "../intefaces";

// TODO: delete this constant when dynamic item component reuse dynamic update item component
export const TAXONOMIES_URL_NAME: string = "taxonomies";
const ID_PROPERTY: string = "Id";

@Injectable()
export class TaxonomyService {

    /**
     * Creates an instance of TaxonomiesService.
     *
     * @param {SitefinitySdk} SitefinitySdk
     */
    constructor(private sitefinitySdk: SitefinitySdk, private errorParserService: ErrorParserService) {
    }

    /**
     * Create taxon for given taxonomy
     *
     * @param {string[]} taxonomiesIds - the IDs of the taxonomies
     * @returns {Promise<any>} - return the created taxon object
     *
     * @memberOf TaxonomyService
     */
    getTaxonomies(taxonomiesIds: string[]): Promise<Taxonomy[]> {
        let query: any = this.sitefinitySdk.query.where();
        query = query.or();
        for (let index = 0; index < taxonomiesIds.length; index += 1) {
            const id = taxonomiesIds[index];
            query = query.eq(ID_PROPERTY, id);
        }

        query = query.done().done().order(`${TITLE_KEY} ${SORT_ORDER.ASCENDING}`);
        const promiseExecutor = (resolve, reject) => {
            this.sitefinitySdk.instance.data({
                entitySet: TAXONOMIES_URL_NAME
            }).get({
                query: query,
                successCb: data => resolve(data.value),
                failureCb: error => reject(error)
            });
        };

        return new Promise(promiseExecutor);
    }

    /**
     * Create taxon for given taxonomy
     *
     * @param {string} taxonomyType - flat-taxa or hierarchy-taxa
     * @param {Taxon} taxon
     * @returns {Promise<any>} - return the created taxon object
     *
     * @memberOf TaxonomyService
     */
    createTaxon(taxonomyType: string, taxon: Taxon): Promise<any> {
        const promiseExecutor = (resolve, reject) => {
            const batch = this.sitefinitySdk.instance.batch(
                result => {
                    const error = this.errorParserService.parseError(result);
                    if (error) {
                        reject(error);
                        return;
                    }

                    resolve(result.data[0].response[0].data);
                },
                error => {
                    reject(error);
                });

            const transaction = batch.beginTransaction();

            transaction.create({
                entitySet: taxonomyType,
                data: taxon
            });

            batch.endTransaction(transaction);
            batch.execute();
        };

        return new Promise(promiseExecutor);
    }

    /**
     * Delete taxa
     *
     * @param {string} taxonomyType - flat-taxa or hierarchy-taxa
     * @param {string[]} taxaIds - array of taxa Ids marked for deletion
     * @returns {Promise<any>}
     *
     * @memberOf TaxonomyService
     */
    deleteTaxa(taxonomyType: string, taxaIds: string[]): Promise<any> {
        const promiseExecutor = (resolve, reject) => {
            const batch = this.sitefinitySdk.instance.batch(
                result => {
                    const error = this.errorParserService.parseError(result);
                    if (error) {
                        reject(error);
                        return;
                    }

                    resolve(result);
                },
                error => {
                    reject(error);
                });

            const transaction = batch.beginTransaction();

            taxaIds.forEach(taxonId => {
                transaction.destroy({
                    entitySet: taxonomyType,
                    key: taxonId
                });
            });

            batch.endTransaction(transaction);
            batch.execute();
        };

        return new Promise(promiseExecutor);
    }
}

export interface KeyValuePair {
    key: string;
    value: any[];
}

export interface TaxaInfo {
    taxonomyId: string;
    taxonomyType: string;
    itemsToMatch?: KeyValuePair;
    itemsToExclude?: KeyValuePair;
    searchText?: KeyValuePair;
    order?: string;
    count?: number;
    skip?: number;
    match?: boolean;
}
