import { Injectable, Type } from "@angular/core";
import { Router, NavigationExtras } from "@angular/router";
import { Observable, ReplaySubject } from "rxjs";
import { Command } from "../../../../../shared/commands/command";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ContentCultureData, SiteData } from "../../../../../shared/services/metadata/site-data.store";
import { DialogData, ModalWindowService, ClosingContext } from "../../../../../shared/services/modal-window.service";
import { DataItem } from "../../../interfaces";
import { QUERY_PARAMS } from "../../../../constants";
import { EditArgument } from "./edit-command";
import { ToolbarComponent } from "../../../components/dialog/toolbar.component";
import { PAGES_ENTITY_SET_NAME } from "../../../../../pages/services/page.resolver";
import { ChainedOperationResult } from "./confirmation-command";
import { indefiniteArticle } from "../../../../../../utils";
import { ENTITY_SET } from "../../../../../shared/services/metadata/meta-data-constants";

export interface EditInDialogArgument extends EditArgument {
    siteData: SiteData;
    dialogType: Type<any>;
    navigateToChildrenAfterCreate: boolean;
    headComponentData: ComponentData;
}

@Injectable()
export class EditInDialogCommand implements Command {
    constructor(protected modalWindowService: ModalWindowService, protected router: Router) {
    }

    execute(context: ExecutionContext): Observable<EditInDialogOperationResult> {
        const data = <EditInDialogArgument>context.data;
        const siteData = data.siteData;
        const dataItem = data.dataItem;
        const isCreate = dataItem.isEmpty;
        const cultures = siteData.ContentCultures;
        const dialogType = data.dialogType;
        const mediaFieldLimitationsConstraints = data.mediaFieldLimitationsConstraints;
        const navigateToChildrenAfterCreate = data.navigateToChildrenAfterCreate;
        const headComponentData = data.headComponentData;
        let cultureData: ContentCultureData = null;
        if (dataItem.metadata.isMultilingual && dataItem.metadata.isTranslatable && cultures.length > 0) {
            cultureData = cultures.find(x => x.Name === dataItem.culture);
        }

        const componentData: ComponentData = {
            type: dialogType,
            properties: {
                dataItem: dataItem,
                cultureData: cultureData,
                parentId: data.parentId,
                mediaFieldLimitationsConstraints: mediaFieldLimitationsConstraints,
                prepopulatedFields: data.prepopulatedFields
            },
            updatePropertiesOnChange: true
        };

        const return$ = new ReplaySubject<EditInDialogOperationResult>(1);
        const doneCb = (result: ClosingContext) => {
            const isLoading = false;

            if (result.data) {
                if (isCreate || !dataItem.isTranslated) {
                    if (navigateToChildrenAfterCreate) {
                        const url = this.getChildItemUrl(result.data);
                        if (url) {
                            const queryParams = this.getProviderAndCultureQueryParams(result.data);
                            const route = result.data.metadata.ignoreParentChildRelationship ? context.currentRoute : context.currentRoute.firstChild;
                            const navigationExtras: NavigationExtras = { relativeTo: route, queryParams };
                            if (data.replaceUrl) {
                                navigationExtras.replaceUrl = true;
                            }

                            return this.router.navigate([url], navigationExtras)
                                .then(() => { return$.next({ success: true }); })
                                .catch((err) => return$.error(err));
                        }
                    }
                }

                return$.next({
                    success: true,
                    dataItem: result.data,
                    isLoading
                });
            } else {
                return$.next({
                    success: false,
                    isLoading: false,
                    component: result.component
                });
            }
        };
        const dialogData = new DialogData(componentData, doneCb);
        dialogData.headComponentData = headComponentData;

        const singularName = context.data.singularName ? context.data.singularName : dataItem.metadata.singularName;
        dialogData.toolbarData = {
            type: ToolbarComponent,
            properties: {
                dataItem,
                cultureData,
                header: this.getHeader(dataItem, singularName)
            }
        };

        let path = "edit";
        if (data.duplicate) {
            path = "duplicate";
        }

        // when having a modal window inside a modal window, the urls are the same
        // we need to provide a unique path so that each window is opened separately
        // valid for concurrent editing of related data
        const argument = `${path}_${dataItem.key}_${dataItem.metadata.setName}_${dataItem.provider || undefined}_${dataItem.culture}`;
        this.modalWindowService.setMapping(dialogData, argument);
        this.modalWindowService.show(argument, context.currentRoute.firstChild, { [QUERY_PARAMS.EDIT_ITEM_ID]: null });

        return return$.asObservable();
    }

    protected getChildItemUrl(dataItem: DataItem): string {
        if (dataItem.metadata.hasChildren) {
            if (dataItem.metadata.ignoreParentChildRelationship) {
                return dataItem.metadata.setName;
            }
            return `${dataItem.data.Id}/${dataItem.childSetName}`;
        }

        return null;
    }

    protected getProviderAndCultureQueryParams(entityData: DataItem) {
        const queryParams = {};
        queryParams[QUERY_PARAMS.PROVIDER] = entityData.provider;
        queryParams[QUERY_PARAMS.CULTURE] = entityData.culture;
        return queryParams;
    }

    private getHeader(dataItem: DataItem, singularName: string): string {
        if ([ENTITY_SET.FORMS, PAGES_ENTITY_SET_NAME].indexOf(dataItem.metadata.setName) > -1 ) {
            return `${singularName} title and properties`;
        }

        return dataItem.isEmpty ? `Creating ${indefiniteArticle(singularName)} ${singularName.toLowerCase()}` : `${singularName} properties`
    }
}

export interface EditInDialogOperationResult extends ChainedOperationResult {
    forceReload?: boolean;
    dataItem?: DataItem;
    component?: any;
}
