import { Injectable, InjectionToken, Optional, Inject } from "@angular/core";
import { of, Observable, combineLatest } from "rxjs";
import { map } from "rxjs/operators";
import { WidgetEditorViewProvider, EditorViewModel, EditorViewKey, WidgetEditorViewRgistrationProvider } from "../interfaces/widget-editor-view-provider";
import { PropertyEditorViewModes } from "../property-editor.constants";

export const WIDGET_VIEW_TOKEN = new InjectionToken("widget_view_token");

/**
 * The ViewRegistrationProvider class works with all of the edior view providers and combines their views into a single
 * views array.
 */
@Injectable()
export class CustomViewRegistrationProvider {
    constructor(@Optional() @Inject(WIDGET_VIEW_TOKEN) private editorViewProviders: Array<WidgetEditorViewProvider>) { }

    getView(key: EditorViewKey): Observable<EditorViewModel> {
        const defaultViewName = PropertyEditorViewModes.BASIC;
        if (key.viewName === defaultViewName) {
            const overridenView = this.editorViewProviders.map(x => {
                return x.overrideView(key);
            }).filter(x => x && x.componentData);

            if (overridenView.length > 0) {
                const view = {
                    key: key,
                    componentData: overridenView[0].componentData
                };
                return of(view);
            }
        }

        //if the view was not overriden.
        return this.getRegisteredViews().pipe(map((views) => views.find((view) => view.key.widgetName === key.widgetName && view.key.viewName === key.viewName)));
    }

    /**
     * Gets the views from all of the providers.
     */
    private getRegisteredViews(): Observable<EditorViewModel[]> {
        if (this.editorViewProviders) {
            return this.initViews();
        }

        return of([]);
    }

    private initViews(): Observable<EditorViewModel[]> {
        const viewsArr$ = this.editorViewProviders.map(x => {
            const viewProvider = x as unknown as WidgetEditorViewRgistrationProvider;
            if (viewProvider.getViews)
                return viewProvider.getViews();
        }).filter(x => x);

        return combineLatest(...viewsArr$).pipe(map((resolvedViewsArrs) => {
            return this.mergeViews(resolvedViewsArrs);
        }));
    }

    private mergeViews(resolvedViewsArrs: EditorViewModel[][]) {
        const views: Array<EditorViewModel> = [];
        resolvedViewsArrs.forEach(viewArr => {
            viewArr.forEach((view) => {
                views.push(view);
            });
        });

        return views;
    }
}
