import { of as observableOf,  Observable } from "rxjs";

import { tap } from "rxjs/operators";
import { SelectorBase } from "../selector-base";
import { SiteSelectorItem } from "./site-selector-item";
import { SiteData, SiteDataStore } from "../../../../../../../shared/services/metadata/site-data.store";
import { MetadataContainer } from "../../../../../../../shared/services/metadata/meta-data.store";
import { LoadItemsResponse } from "../../../../../../../content/dynamic-modules/services/dynamic-item.service";
import { EntityData } from "../../../../../../../content/dynamic-modules/interfaces";
import { Logger } from "../../../../../../../shared/services/logger-source/logger";
import { LoadingState } from "../../../../../../../shared/rxjs-extensions/delayEmission";
import { DEFAULT_SITE_TITLE_SUFFIX } from "./constants";
import { toLoadingState } from "../../../../../../../shared/rxjs-extensions";
import { LoadingContentState } from "../../../../../../../shared/rxjs-extensions/toLoadingState";

export class SiteSelector extends SelectorBase<SiteSelectorItem> {
    constructor(
        logger: Logger,
        private siteData: SiteData,
        private metadataStore: MetadataContainer,
        private siteDataStore: SiteDataStore) {
        super(logger);
    }

    protected setSelectedItem(value: SiteSelectorItem) {
        this.context.selectedSite = value;
        super.setSelectedItem(value);
    }

    onInit(): Observable<LoadingState> {
        const sitesEntity = this.metadataStore.entities["sites"];

        if (!sitesEntity) {
            const currentSiteModel = SiteSelectorItem.fromSiteData(this.siteData);
            this.items = [currentSiteModel];
            this.initDefaultSelection();

            return observableOf({}).pipe(toLoadingState());
        }

        return this.siteDataStore.getAllSites(<EntityData>{
            metadata: sitesEntity
        }).pipe(
            toLoadingState(),
            tap((response: LoadingContentState<LoadItemsResponse>) => {
                if (!response.isLoading) {
                    const sites = response.content.dataItems.map(dataItem => SiteSelectorItem.fromDataItem(dataItem));
                    this.items = sites;
                    this.initDefaultSelection();
                }
            }));
    }

    private initDefaultSelection() {
        const currentIrisSite = this.items.find(c => c.value === this.siteData.Id);
        currentIrisSite.additionalInfo = DEFAULT_SITE_TITLE_SUFFIX;
        this.setSelectedItem(currentIrisSite);
    }
}
