import { InjectionToken, Optional, Inject, Injectable } from "@angular/core";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { DataItem } from "../../src/app/api";
import { isNullOrEmpty } from "../../src/app/utils";

export const CUSTOM_TREE_COMPONENT_TOKEN = new InjectionToken("related_data_custom_component_token");

@Injectable()
export class TreeNodeComponentCompositeProvider implements TreeNodeComponentProvider {

    constructor(@Optional() @Inject(CUSTOM_TREE_COMPONENT_TOKEN) private providers: Array<TreeNodeComponentProvider>) {
    }

    getComponentData(feature: TreeNodeComponentFeatures, entitySet: string): ComponentData {
        if (!feature || isNullOrEmpty(entitySet) || !this.providers || this.providers?.length === 0)
            return null;

        let componentData: ComponentData;

        for (let i = 0; i < this.providers.length; i++) {
            const currentProvider = this.providers[i];

            componentData = currentProvider.getComponentData(feature, entitySet);

            if (componentData) {
                return componentData;
            }
        }
    }
}

/**
 * A provider to be implemented in order to supply data that would replace the component used in the related data selectors
 * @ExposedInApi {TreeNodeComponentProvider} TreeNodeComponentProvider v1/tree/custom-tree-component-provider.d.ts
 * @export
 * @interface TreeNodeComponentProvider
 */
export interface TreeNodeComponentProvider {
    /**
     * Gets the component data for the registered components
     *
     * @param {TreeNodeComponentFeatures} feature Used to determine for which feature will this component be used.
     * Currently only supported for "related-data"
     * @param {string} entitySet Cannot be null. The entity set for which the component data is to be used.
     * If the entity set is an empty string the component data will be used for all entity sets for the current feature.
     * Example of entity sets: "newsitems", "blogposts", "events", "pressreleases"
     * @return {*}  {ComponentData}
     * @memberof TreeNodeComponentProvider
     */
    getComponentData(feature: TreeNodeComponentFeatures, entitySet: string): ComponentData
}

/**
 * The base class used as a base to implement a custom component for the tree
 * @ExposedInApi {CustomTreeNodeComponentBase} CustomTreeNodeComponentBase v1/tree/custom-tree-component-base.d.ts
 * @export
 * @abstract
 * @class CustomTreeNodeComponentBase
 */
export abstract class CustomTreeNodeComponentBase {
    item: DataItem;
}

/**
 * List of features supported by the {TreeNodeComponentProvider}
 * @ExposedInApi {TreeNodeComponentFeatures} TreeNodeComponentFeatures v1/tree/custom-tree-node-component-features.d.ts
 * @export
 * @enum {number}
 */
export enum TreeNodeComponentFeatures {
    RelatedData = "related-data"
}