import { first } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from "@angular/router";
import { Observable } from "rxjs";
import { MetadataStore, MetadataContainer } from "./meta-data.store";

@Injectable()
export class MetadataStoreResolver implements Resolve<any> {
    constructor(private metadataStore: MetadataStore) {
    }

    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<MetadataContainer> {
        return this.metadataStore.initialize().pipe(first());
    }
}
