import { Component } from "@angular/core";
import { FieldBase } from "../../../../../fields/field-base";
import { MediaRecognizerService } from "./media-recognizer.service";

@Component({
    selector: "sf-simple-media",
    templateUrl: "./simple-media.component.html"
})
export class SimpleMediaComponent extends FieldBase {
    previewerData;

    constructor(private mediaRecognizerService: MediaRecognizerService) {
        super();
    }

    writeValue(value: any): void {
        super.writeValue(value);
        if (value) {

            this.previewerData = this.mediaRecognizerService.getComponentData(value);
        }
    }
}
