import { Injectable } from "@angular/core";
import { RecuringEventData, RepeatEventData } from ".";
import { RecurrentRule, RecurrenceDay, RecurrenceMonth, RecurrenceFrequency, EndRecurrenceType } from "./recurrent-rule";
import { stringConstants } from "../../../../../common-constants";
import { RECURRING_EVENT_KEYS, END_OCURRENCE_KEYS } from "./recurring-event.constants";
import { EventDatesService } from "../services/event-dates.service";
import { convertDateToIsoDateTime } from "../../../../../utils";

const ERROR_MESSAGES = {
    INVALID_RECURRING_EVENT_KEY: "Invalid recurring event key!",
    INVALID_END_OCURRENCE_KEY: "Invalid end ocurrence key!"
};

@Injectable()
export class RecurrentRuleService {
    constructor(private readonly eventDatesService: EventDatesService) {}

    construct(data: RecuringEventData, allDayEvent: boolean, startDate: Date): RecurrentRule {
        if (!data) {
            return null;
        }

        const recurrentRule: any = {};

        this.processRepeatEventData(recurrentRule, data.repeatEvent);
        this.processEndOccurenceData(recurrentRule, data.endOccurrence, allDayEvent);

        recurrentRule.startDate = convertDateToIsoDateTime(startDate);

        return recurrentRule;
    }

    private processRepeatEventData(recurrentRule: RecurrentRule, repeatEventData: RepeatEventData) {
        if (!repeatEventData || !repeatEventData.key) {
            recurrentRule.frequency = RecurrenceFrequency.None;
            return;
        }

        const key = repeatEventData.key;

        if (key.includes(RECURRING_EVENT_KEYS.DONT_REPEAT)) {
            this.processDontRepeat(recurrentRule);
            return;
        }

        if (key.includes(RECURRING_EVENT_KEYS.EVERY_DAY)) {
            this.processEveryDay(recurrentRule);
            return;
        }

        if (key.includes(RECURRING_EVENT_KEYS.EVERY_WORKDAY)) {
            this.processEveryWorkday(recurrentRule);
            return;
        }

        if (key.includes(RECURRING_EVENT_KEYS.WEEKLY_ON)) {
            this.processWeekly(recurrentRule, repeatEventData);
            return;
        }

        if (key.includes(RECURRING_EVENT_KEYS.MONTHLY_ON)) {
            this.processMonthly(recurrentRule, repeatEventData);
            return;
        }

        if (key.includes(RECURRING_EVENT_KEYS.YEARLY_ON)) {
            this.processYearly(recurrentRule, repeatEventData);
            return;
        }

        throw new Error(ERROR_MESSAGES.INVALID_RECURRING_EVENT_KEY);
    }

    private processDontRepeat(recurrentRule: RecurrentRule) {
        recurrentRule.frequency = RecurrenceFrequency.None;
    }

    private processEveryDay(recurrentRule: RecurrentRule) {
        recurrentRule.daysOfWeek = RecurrenceDay.EveryDay;
        recurrentRule.frequency = RecurrenceFrequency.Daily;
        recurrentRule.interval = 1;
    }

    private processEveryWorkday(recurrentRule: RecurrentRule) {
        recurrentRule.daysOfWeek = RecurrenceDay.WeekDays;
        recurrentRule.frequency = RecurrenceFrequency.Daily;
    }

    private processWeekly(recurrentRule: RecurrentRule, repeatEventData: RepeatEventData) {
        const dayName = repeatEventData.key.split(stringConstants.INTERVAL)[2];
        recurrentRule.daysOfWeek = RecurrenceDay[dayName];
        recurrentRule.frequency = RecurrenceFrequency.Weekly;
    }

    private processMonthly(recurrentRule: RecurrentRule, repeatEventData: RepeatEventData) {
        const date = Number(repeatEventData.key.match(/[0-9]+/));
        recurrentRule.dayOfMonth = date;
        recurrentRule.frequency = RecurrenceFrequency.Monthly;
    }

    private processYearly(recurrentRule: RecurrentRule, repeatEventData: RepeatEventData) {
        const tokens = repeatEventData.key.split(stringConstants.INTERVAL);
        const shortMonthName = tokens[2];
        const date = Number(repeatEventData.key.match(/[0-9]+/));

        recurrentRule.month = this.getMonthValue(shortMonthName);
        recurrentRule.dayOfMonth = date;
        recurrentRule.frequency = RecurrenceFrequency.Yearly;
    }

    private processEndOccurenceData(recurrentRule: RecurrentRule, endOccurenceData: RepeatEventData, allDayEvent: boolean) {
        if (!endOccurenceData || !endOccurenceData.key) {
            return;
        }

        if (endOccurenceData.key.includes(END_OCURRENCE_KEYS.NEVER)) {
            recurrentRule.endRecurrenceType = EndRecurrenceType.Never;
            return;
        }

        if (endOccurenceData.key.includes(END_OCURRENCE_KEYS.BY)) {
            const value = new Date(endOccurenceData.value);

            if (allDayEvent) {
                recurrentRule.recursUntil = this.eventDatesService.resetTime(recurrentRule.recursUntil);
            }

            recurrentRule.endRecurrenceType = EndRecurrenceType.By;
            recurrentRule.recursUntil = new Date(value);

            return;
        }

        if (endOccurenceData.key.includes(END_OCURRENCE_KEYS.AFTER)) {
            recurrentRule.maxOccurrences = Number(endOccurenceData.value);
            recurrentRule.endRecurrenceType = EndRecurrenceType.After;
            return;
        }

        throw new Error(ERROR_MESSAGES.INVALID_END_OCURRENCE_KEY);
    }

    private getMonthValue(monthShortName: string) {
        const key = Object.keys(RecurrenceMonth).find(k => k.includes(monthShortName));
        const monthValue = RecurrenceMonth[key];

        return monthValue;
    }
}
