import { SearchMode } from "../../src/app/modules/shared/services/content-filter.service";

export interface KeyValuePair {
    key: string;
    value: any[];
}

export interface ExtendedKeyValuePair {
    key: string;
    value: any[];
    operation?: Operation;
    searchMode?: SearchMode;
    caseSensitive?: boolean;
}

export enum Operation {
    or,
    and,
    eq
}

export interface FallbackProperties {
    fallbackProperties?: Array<string>;
}

export interface BaseServiceInfo extends FallbackProperties {
    type: string;
    provider: string;
    culture: string;
    filter?: ExtendedKeyValuePair[];
    itemsToExclude?: KeyValuePair;
    order?: string;
    take?: number;
    skip?: number;
    match?: boolean;
    action?: string;
}

export enum Order {
    asc,
    desc
}
