import { timer as observableTimer, zip } from "rxjs";
import { Component, OnInit } from "@angular/core";
import { MetadataStore, Entity } from "../../../../shared/services/metadata/meta-data.store";
import { DataContext, DataContextComponent } from "../../../../shared/models/data-context-component";
import { DynamicItemService, LoadItemsData } from "../../services/dynamic-item.service";
import { Operation } from "../../../../../../../fields/services/base.service";
import { COMMAND_NAMES } from "../commands";
import { LOADING_TIME } from "../../../constants";

export const MAX_ITEMS_COUNT = 3;

/**
 * Component used to display the children items
 */
@Component({
    selector: "sf-list-children-items",
    templateUrl: "./list-children-items.component.html"
})
export class ListChildrenItemsComponent implements OnInit, DataContextComponent {
    /**
     * Indicates if the component is currently in the process of loading the items.
     */
    public isLoading: boolean = false;
    public childrenItems: any[] = [];
    public badgeContent: string = "";

    /**
     * The item data that is required to get the children items
     */
    public context: DataContext;

    /**
    * Initializes a new instance of the {@link ListChildrenItemsComponent} class
    * @param metadata The metadata from which to fetch the child item's types
    * @param dynamicItemService The dynamic item service.
    */
    constructor(private metadata: MetadataStore, private dynamicItemService: DynamicItemService) { }

    public ngOnInit(): void {
        this.isLoading = true;

        this.metadata.initialize().subscribe(metaContainer => {
            const miniumLoaderTimer$ = observableTimer(LOADING_TIME);
            const entity = metaContainer.entities[this.context.dataItem.childSetName];
            if (entity) {
                const loadData = this.getLoadItemsData(entity);
                const getChildItems$ = this.dynamicItemService.getItemList(loadData);

                zip(miniumLoaderTimer$, getChildItems$).subscribe((data) => {
                    const childItems = data[1];

                    this.childrenItems = [];
                    childItems.dataItems.forEach(item => {
                        this.childrenItems.push(item.data);
                    });

                    if (childItems.totalCount > MAX_ITEMS_COUNT) {
                        this.badgeContent = "+" + (childItems.totalCount - MAX_ITEMS_COUNT);
                    }

                    this.isLoading = false;
                });
            }
        });
    }

    /**
     * Handles the click event on more items button.
     */
    public onClick(): void {
        const invoker = this.context.invoker;
        invoker.invoke({
            name: COMMAND_NAMES.childNavigate,
            data: {
                childSetName: this.context.dataItem.childSetName,
                dataItem: this.context.dataItem
            }
        });
    }

    private getLoadItemsData(entity: Entity): LoadItemsData {

        const loadItemsData: LoadItemsData = {
            entityData: {
                metadata: entity,
                provider: this.context.dataItem.provider,
                culture: this.context.dataItem.culture
            },
            filter: [{
                key: entity.parentIdProperty,
                value: [this.context.dataItem.data.Id],
                operation: Operation.eq
            }],
            take: MAX_ITEMS_COUNT,
            fallbackProperties: [entity.defaultFieldName]
        };

        return loadItemsData;
    }
}