import { Directive, ElementRef, HostListener, AfterViewInit, Input } from "@angular/core";
import { stringConstants } from "../../../src/app/common-constants";
import { NODE_NAMES } from "../../../src/app/modules/html/selector-constants";

export const TRIM_LENGTH = 256;
export const MORE_LABEL = "More";
export const LESS_LABEL = "Less";
export const TOGGLE_BUTTON_ID_PREFIX = "sfToggleButton";
const TOGGLE_BUTTON_CLASS = "-sf-txt-nowrap";

@Directive({
    selector: "[sfTextOverflow]"
})
export class TextOverflowDirective implements AfterViewInit {
    @Input() trimLength: number = TRIM_LENGTH;
    private longValue: string;
    private shortValue: string;
    private toggleButton: HTMLElement;
    private toggleButtonId: string;
    private isTrimmed: boolean = false;

    constructor(private element: ElementRef) {}

    @HostListener("click", ["$event"]) onclick(event: any) {
        const target = event.target as HTMLElement;
        if (target.id === this.toggleButtonId) {
            event.stopImmediatePropagation();

            this.toggleTextOverflow();
        }
    }

    ngAfterViewInit() {
        this.createToggleButton();
        this.longValue = this.element.nativeElement.innerText;

        if (this.longValue.length > this.trimLength) {
            let shortText = this.longValue.substr(0, this.longValue.lastIndexOf(stringConstants.INTERVAL, this.trimLength)).trim();
            // we removed last character of string if character is comma
            if (shortText.endsWith(stringConstants.COMMA)) {
                shortText = shortText.substring(0, shortText.length - 1);
            }

            this.shortValue = shortText.concat(`${stringConstants.INTERVAL}${stringConstants.ELLIPSIS}`);
            this.isTrimmed = true;

            this.setText(`${this.shortValue} ${this.toggleButton.outerHTML}`);
        }
    }

    private toggleTextOverflow() {
        let value: string;

        if (this.isTrimmed) {
            this.toggleButton.innerText = LESS_LABEL;
            value = this.longValue;
        } else {
            this.toggleButton.innerText = MORE_LABEL;
            value = this.shortValue;
        }

        this.isTrimmed = !this.isTrimmed;

        this.setText(`${value} ${this.toggleButton.outerHTML}`);
    }

    private setText(text: string) {
        this.element.nativeElement.innerHTML = text;
    }

    private createToggleButton() {
        this.toggleButtonId = `${TOGGLE_BUTTON_ID_PREFIX}${Math.random().toString()}`;
        this.toggleButton = document.createElement(NODE_NAMES.ANCHOR_ELEMENT);
        this.toggleButton.id = this.toggleButtonId;
        this.toggleButton.classList.add(TOGGLE_BUTTON_CLASS);
        this.toggleButton.innerText = MORE_LABEL;
    }
}
