import { Component, Inject, OnInit, Renderer2, RendererFactory2, ViewChild, OnDestroy } from "@angular/core";
import { ActivatedRoute, Data, Router } from "@angular/router";
import { ITEM_DATA_KEY, UNSAVED_CHANGES_DIALOG_MESSAGE } from "../../../content/dynamic-modules/components/entity/dynamic-item.component";
import { ItemData } from "../../../content/dynamic-modules/services/entity/dynamic-item.resolver";
import { ReplaySubject, BehaviorSubject, Subject, Observable, of, empty, OperatorFunction, ObservedValueOf, EMPTY, throwError, timer } from "rxjs";
import { DataItem, EntityData } from "../../../content/dynamic-modules/interfaces";
import { CompositeOperationsProvider } from "../../../content/dynamic-modules/services/operations/operations-provider";
import { Operation, OPERATION_NAMES, OPERATION_CATEGORIES, OPERATION_PARAMETERS } from "../../../shared/components/action-menu/operation.model";
import { NavbarConfiguration } from "../../../shared/components/navigation/navigation-menu/navigation-menu.component";
import { NAVBAR_PAGE_EDITOR_LOOK } from "../edit-page/edit-page.component";
import { ActionButton, ButtonState } from "../../../shared/components/action-menu/action-menu-model";
import { LANGUAGE_BADGE_EDIT_LOOK } from "../../../shared/components/languages-dropdown/languages-dropdown.component";
import { PagesActionHandler } from "../../services/pages-action-handler.service";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { ActionButtonsStateService } from "../../../shared/services/action-buttons-state.service";
import { ButtonsState } from "../../../content/dynamic-modules/components/action-buttons.resolver";
import { ActionExecutorService, ExecuteServerAction } from "../../../shared/services/action-executor.service";
import { stringConstants, NEW_TAB_TARGET, SAME_TAB_TARGET } from "../../../../common-constants";
import { EditItemMenuComponent } from "../../../shared/components/edit-menu/edit-menu.component";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../shared/services/notification/notification.service";
import { ZoneEditorContract, EditorStateResponse, WidgetOperationResult } from "../../services/zone-editor.contract";
import { map, filter, tap, catchError, switchMapTo } from "rxjs/operators";
import { DEFAULT_SIDEBAR_BUTTON_LOOK } from "../../../shared/components/sidebar/sidebar-buttons.component";
import { TreeSidebarComponent } from "./sidebar/tree-sidebar.component";
import { EnhancedPageComponent, AddWidgetArgs, ZONE_EDITOR_NOTIFICATION_FILTER } from "./enhanced-page.component";
import { LoadWidgetOperations } from "./inline-toolbar/inline-toolbar.component";
import { LockedItemError } from "../../../shared/services/errors/locked-item-error";
import { CanDeactivateComponent } from "../../../shared/guards/can-deactivate.guard";
import { ComponentModel, ContainerModel } from "./model/component-model";
import { LoadingActionContext } from "../../../shared/services/grid/grid-extender-base";
import { SIDEBAR_DISPATCH_ACTION } from "../../../../services/store/actions/actions.sidebar";
import { AppStore } from "../../../../services/store/app-store";
import { SIDEBAR_SELECTORS } from "../../../../services/store/selectors/selectors.sidebar";
import { SidebarComponentData } from "../../../shared/components/sidebar/sidebar-component.repo";
import { SidebarConfig } from "../../../shared/components/sidebar/sidebar.common";
import { MobilePreviewCommand } from "../mobile-preview/mobile-preview.command";
import { ItemWithOperationResult } from "../../../content/dynamic-modules/services/dynamic-item.service";
import { ModalWindowService } from "../../../shared/services/modal-window.service";
import { ZoneEditorCompositeExtender } from "./extenders/zone-editor-composite-extender";
import { QUERY_PARAMS, STAY_AFTER_PUBLISH_TIMEOUT } from "../../../content/constants";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { Settings } from "../../../shared/services/settings.service";
import { ROUTE_PATHS, ROUTE_PATHS_NO_PREFIX } from "../../../../constants/route-paths";
import { FormsConstants } from "../../../forms/forms.constants";
import { FormsActionHandler } from "../../../forms/forms-action-handler.service";
import { ActionHandler } from "../../../content/dynamic-modules/components/action-handler";

const NEW_ZONE_EDITOR = "-sf-new-zone-editor";

@Component({
    providers: [ActionButtonsStateService],
    selector: "sf-zone-editor",
    templateUrl: "./zone-editor.component.html"
})
export class ZoneEditorComponent extends SfRxBase implements OnInit, OnDestroy, CanDeactivateComponent {
    @ViewChild(EditItemMenuComponent, { static: false }) editMenu: EditItemMenuComponent;
    @ViewChild(EnhancedPageComponent, { static: false }) enhancedPageComponenent: EnhancedPageComponent;

    buttonsState: ButtonsState;
    item$: BehaviorSubject<DataItem>;
    operations: Subject<Operation[]>;
    generalActionOperations: BehaviorSubject<Operation[]>;
    customOperations: BehaviorSubject<Operation[]>;
    additionalActionOperations: BehaviorSubject<Operation[]>;
    personalizationOperations: BehaviorSubject<Operation[]>;
    navbarConfiguration: NavbarConfiguration;
    entityData: EntityData;
    iFrameUrl: string;
    state: EditorStateResponse;
    loading: boolean;
    preserveNotificationOnBackNavigation: boolean;
    hasSidebar: boolean;
    emptyRootCssClasses: string[];
    useNarrowLook: boolean;
    initialWidgetSelectorTabName: string;
    visible = false;
    preserveNotifications = false;

    private locked: boolean;
    private lockingInitiated: boolean;
    private renderer: Renderer2;
    private fallbackProperties: string[];
    private activeComponent = new ReplaySubject<string>();
    private treeModelChange = new ReplaySubject<ComponentModel[]>(0);

    constructor(
        private router: Router,
        private zoneEditorContract: ZoneEditorContract,
        @Inject(WINDOW_TOKEN) private windowProvider: Window,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService,
        private serviceOperationsExecutor: ActionExecutorService,
        private buttonStateService: ActionButtonsStateService,
        private route: ActivatedRoute,
        private operationProvider: CompositeOperationsProvider,
        private pagesCommonActionHandler: PagesActionHandler,
        private formsCommonActionHandler: FormsActionHandler,
        rendererFactory: RendererFactory2,
        private store: AppStore,
        private modalWindowService: ModalWindowService,
        private zoneEditorCompositeExtender: ZoneEditorCompositeExtender,
        private settings: Settings) {
            super();
        this.item$ = new BehaviorSubject<DataItem>(null);
        this.operations = new ReplaySubject<Operation[]>(1);
        this.renderer = rendererFactory.createRenderer(null, null);
        this.generalActionOperations = new BehaviorSubject<Operation[]>([]);
        this.customOperations = new BehaviorSubject<Operation[]>([]);
        this.additionalActionOperations = new BehaviorSubject<Operation[]>([]);
        this.personalizationOperations = new BehaviorSubject<Operation[]>([]);
    }

    ngOnInit(): void {
        this.handleLockedItemEdit();
        this.loading = true;

        this.registerSubscription(this.buttonStateService.getState$().subscribe((buttonsState) => {
            this.buttonsState = buttonsState;
        }));

        const entityData = this.route.snapshot.data[ITEM_DATA_KEY].entityData as EntityData;
        this.navbarConfiguration = {
            title: this.item$.pipe(map(x => x.title)),
            look: `toggle ${NAVBAR_PAGE_EDITOR_LOOK}`,
            leftNavbarButtonData: {
                title: `All ${entityData.metadata.displayName.toLowerCase()}`,
                autoNavigateBack: entityData.metadata.setName !== ENTITY_SET.FORMS
            }
        };

        this.registerSubscription(this.route.data.subscribe((data) => {
            this.initFromRouteData(data);
        }));

        this.renderer.addClass(this.windowProvider.document.body, NEW_ZONE_EDITOR);

        this.registerSubscription(this.store.pipe(SIDEBAR_SELECTORS.isOpen).subscribe(isOpen => this.hasSidebar = isOpen));

        this.emptyRootCssClasses = this.zoneEditorCompositeExtender.getEmptyRootCssClasses(entityData.metadata.setName);
        this.useNarrowLook = this.zoneEditorCompositeExtender.useNarrowLook(entityData.metadata.setName);
        this.initialWidgetSelectorTabName = this.zoneEditorCompositeExtender.getInitialWidgetSelectorTabName(entityData.metadata.setName);
    }

    ngOnDestroy() {
        super.ngOnDestroy();
        this.renderer.removeClass(this.windowProvider.document.body, NEW_ZONE_EDITOR);
    }

    onActionButtonClicked(actionButton: ActionButton) {
        const actionName = actionButton.name.split("_")[0];
         this.zoneEditorCompositeExtender.handleAction(this.entityData.metadata.setName, this.item$.getValue(), actionButton, this.route).subscribe(result => {
                if (result != null) {
                    if (result.success && (actionName === OPERATION_NAMES.lockLayout || actionName === OPERATION_NAMES.unlockLayout)) {
                        const value = this.item$.getValue();
                        const locked = actionName === OPERATION_NAMES.lockLayout ? true : false;
                        this.initFromDataItem(value, true, true, true, locked);
                    }

                if (result.reload) {
                    this.reload();
                }

                return;
            }

            switch (actionName) {
                case OPERATION_NAMES.rules:
                    this.lock().pipe(filter(x => x === true)).subscribe(() => {
                        // since we are navigating to the form rules, which are dependent to have a locked item, we are clearing the locked flag
                        // so it is not discarded
                        this.locked = false;
                        this.router.navigate([ROUTE_PATHS.CONTENT, ROUTE_PATHS_NO_PREFIX.FORMS, FormsConstants.ROUTES.RULES], {
                            queryParams: {
                                id: this.item$.getValue().key
                            }
                        });
                    });
                    break;
                case OPERATION_NAMES.changeCulture:
                    this.handleChangeCulture(actionButton);
                    break;
                case OPERATION_NAMES.edit:
                    if (!actionButton.link)
                        this.handleNavigate();
                    else {
                        actionButton.link += `&backLabelLink=${encodeURIComponent(this.windowProvider.location.href)}`;
                        this.handleServerCommand(actionButton);
                    }
                    break;
                case OPERATION_NAMES.duplicate:
                    this.handleDuplicate();
                    break;
                case OPERATION_NAMES.mobilePreview:
                    this.handleMobilePreview(actionButton);
                    break;
                case OPERATION_NAMES.loadPersonalizedVersion:
                    this.reloadWithCheckForChanges(actionButton.sourceOperation);
                    break;
                case OPERATION_NAMES.deletePersonalizedVersion:
                    this.handleDeletePersonalizedVersion(actionButton);
                    break;
                case OPERATION_NAMES.loadPersonalizedWidgets:
                    this.handlePersonalizedWidgetVersions(actionButton);
                    break;
                case OPERATION_NAMES.setCustomExpiration:
                    this.handleSetCustomExpiration();
                    break;
                default:
                    this.handleServerCommand(actionButton);
                    break;
            }
        });
    }

    onFrameLoaded() {
        this.loading = false;
    }

    onAddWidgetClicked(args: AddWidgetArgs) {
        this.registerSubscription(this.lock().pipe(catchError(err => {
            args.ready.error(err);
            return empty();
        }), filter(x => x)).subscribe(() => {
            args.ready.next();
        }));
    }

    onComponentClicked(loadOperations: LoadWidgetOperations) {
        this.registerSubscription(this.lock().pipe(catchError(err => {
            loadOperations.ready.error(err);
            return empty();
        }), filter(x => x)).subscribe(() => {
            if (loadOperations.widgetId) {
                this.activeComponent.next(loadOperations.widgetId);
                if (loadOperations.ready) {
                    this.zoneEditorContract.getWidgetOperations(loadOperations.dataItem, loadOperations.widgetId, loadOperations.segmentId, loadOperations.widgetSegmentId).pipe(catchError(err => {
                        loadOperations.ready.error(err);
                        return empty();
                    })).subscribe((operations) => {
                        loadOperations.ready.next(operations);
                    });
                }
            }
        }));
    }

    onComponentOperationExecuted(event: { component: ComponentModel, result: WidgetOperationResult }) {
        const srcOperation = event.result.SourceOperation;
        if (srcOperation) {
            const isSpecificPersonalizationCategory = (srcOperation.Category.Name === OPERATION_CATEGORIES.personalized || srcOperation.Category.Name === OPERATION_CATEGORIES.personalization);
            const isDelete = srcOperation.PerformsDelete && event.component.isPersonalized;
            if (isDelete || isSpecificPersonalizationCategory) {
                const routeData = this.route.snapshot.data;
                const itemData = <ItemData>routeData[ITEM_DATA_KEY];
                this.initOperations(itemData.item);
            }
        }
    }

    onLayoutChanged(container: ContainerModel) {
        this.treeModelChange.next(container.getDirectChildrenAndChildrenFromChildContainers());
    }

    onClearWidget() {
        this.activeComponent.next(null);
    }

    onNavigateBack() {
        if (this.entityData.metadata.setName === ENTITY_SET.FORMS) {
            this.canDeactivate().subscribe(canDeactivate => {
                if (canDeactivate) {
                    const cultureQueryParam = this.entityData.culture ? `?lang=${this.entityData.culture}` : stringConstants.EMPTY_STRING;
                    const url = `${this.settings.url}Sitefinity/Content/Forms${cultureQueryParam}`;
                    this.windowProvider.open(url, SAME_TAB_TARGET);
                }
            });
        }
    }

    canDeactivate(): Observable<boolean> {
        if (this.locked) {
            if (this.windowProvider.confirm(UNSAVED_CHANGES_DIALOG_MESSAGE)) {
                this.removeNotification();
                return this.zoneEditorContract.discard(this.item$.getValue()).pipe(this.catchErrorAndShowNotification(), map(x => true), tap(x => this.locked = false));
            }

            return of(false);
        }

        this.removeNotification();

        return of(true);
    }

    actionHandler(): ActionHandler {
        if (this.entityData.metadata.setName === ENTITY_SET.FORMS) {
            return this.formsCommonActionHandler;
        }

        return this.pagesCommonActionHandler;
    }

    // TODO: Remove this hack and all related code once check for locked item is refactored.
    private handleLockedItemEdit() {
        const item = this.route.snapshot.data[ITEM_DATA_KEY].item as DataItem;
        this.pagesCommonActionHandler.tryHandleAction({
            actionName: OPERATION_NAMES.editContent,
            item,
            route: this.route,
            data: { component: this }
        });
    }

    private removeNotification() {
        if (!this.preserveNotificationOnBackNavigation)
            this.notificationService.close();
    }

    private configureSidebar(readonly: boolean, locked: boolean) {
        const sidebarData = {
            buttons: [],
            externalKey: "zoneEditor",
            entityType: this.entityData.metadata.typeFullName
        };

        if (!readonly) {
            const sidebarComponentData: SidebarComponentData = {
                title: "Title",
                type: TreeSidebarComponent,
                updatePropertiesOnChange: true,
                removePreviousView: true,
                properties: {
                    activeComponent: this.activeComponent,
                    treeModelChange: this.treeModelChange,
                    selectComponent: (widgetId: string) => {
                        this.enhancedPageComponenent.focusWidget(widgetId);
                    },
                    editWidgetLabel: (widgetId: string, label: string) => {
                        this.enhancedPageComponenent.editWidgetLabel(widgetId, label);
                    },
                    addWidget: (parentWidgetId: string) => {
                        this.enhancedPageComponenent.addWidgetFromSidebar(parentWidgetId);
                    },
                    moveWidget: (widgetId: string, parentWidgetId: string, index: number) => {
                        this.lock().pipe(filter(x => x === true)).subscribe(() => {
                            this.enhancedPageComponenent.moveWidget(widgetId, parentWidgetId, index);
                        });
                    },
                    emptyMessageLabel: this.state.EmptyMessageLabel
                }
            };

            const title = `${this.entityData.metadata.singularName} structure`;
            const sidebarConfig: SidebarConfig = {
                title: title,
                icon: "sitemap",
                locked: locked,
                data: sidebarComponentData,
                name: "sitemap",
                look: DEFAULT_SIDEBAR_BUTTON_LOOK
            };

            sidebarData.buttons.push(sidebarConfig);
        } else {
            this.store.dispatch(SIDEBAR_DISPATCH_ACTION.close(false));
        }

        this.store.dispatch(SIDEBAR_DISPATCH_ACTION.configure(sidebarData));
    }

    private initFromRouteData(routeData: Data) {
        this.loading = false;
        const itemData = <ItemData>routeData[ITEM_DATA_KEY];
        this.entityData = itemData.entityData;
        this.fallbackProperties = itemData.fallbackProperties;

        this.buttonStateService.updateActionButtonsState(null, ButtonState.Loading);
        this.initFromDataItem(itemData.item, true, false);
    }

    private initFromDataItem(dataItem: DataItem, refreshFrame: boolean, forceRefresh: boolean, preserveNotifications: boolean = false, lockSidebar: boolean = null): void {
        this.item$.next(dataItem);

        const segmentId = this.route.snapshot.queryParams[QUERY_PARAMS.SEGMENT];
        this.registerSubscription(this.zoneEditorContract.getState(dataItem, segmentId).pipe(this.catchErrorAndShowNotification()).subscribe((state) => {
            this.state = state;
            this.initOperations(dataItem);

            if (this.state.LockedByCurrentUser)
                this.locked = true;

            if (refreshFrame) {
                const item = dataItem.data;
                if (state.EditAllowed)
                    this.iFrameUrl = item.EditUrl;
                else
                    this.iFrameUrl = item.ViewUrl;

                let concatChar = "&";
                if (this.iFrameUrl.indexOf("?") === -1)
                    concatChar = "?";

                this.iFrameUrl = `${this.iFrameUrl}${concatChar}sf_version=${this.state.Version}`;
                if (forceRefresh) {
                    this.iFrameUrl += `&random=${Math.random()}`;

                    if (preserveNotifications) {
                        this.preserveNotifications = true;
                    }
                }

                const locked = lockSidebar !== null ? lockSidebar : dataItem.data.IsLayoutLocked;
                this.configureSidebar(!state.EditAllowed, locked);
            }
        }));
    }

    private initOperations(dataItem: DataItem) {
        this.registerSubscription(this.operationProvider.getEditItemOperations(dataItem, undefined, { isEditingPageContent: true, disregardCache: true }, this.getOperationsDataAdditionalQueryParams()).pipe(this.catchErrorAndShowNotification()).subscribe((operations) => {
            this.registerSubscription(this.buttonStateService.updateActionButtonsState(null, ButtonState.Default).subscribe(() => {
                const stopSyncingOperationIndex = operations.findIndex(x => x.Name === OPERATION_NAMES.stopSyncing);
                const result = [];
                if (stopSyncingOperationIndex !== -1) {
                    const stopSyncingOperation = operations[stopSyncingOperationIndex];
                    operations.splice(stopSyncingOperationIndex, 1);
                    stopSyncingOperation.context = {
                        additionalText: null,
                        look: LANGUAGE_BADGE_EDIT_LOOK
                    };

                    result.push(stopSyncingOperation);
                }

                this.operations.next(operations);
                this.loadMainOperations(dataItem);
                this.loadCustomOperations(dataItem);
                this.loadAdditionalActionOperations(dataItem);
                this.loadPersonalizationOperations(dataItem);
            }));
        }));
    }

    private loadMainOperations(item: DataItem) {
        const operations = this.operationProvider.getEditItemMainOperations(item, undefined, { isEditingPageContent: true }, this.getOperationsDataAdditionalQueryParams());
        this.registerSubscription(operations.subscribe(x => {
            this.generalActionOperations.next(x);
        }));
    }

    private loadCustomOperations(item: DataItem) {
        const operations = this.operationProvider.getEditItemCustomOperations(item, undefined, { isEditingPageContent: true }, this.getOperationsDataAdditionalQueryParams());
        this.registerSubscription(operations.subscribe(x => {
            this.customOperations.next(x);
        }));
    }

    private loadAdditionalActionOperations(item: DataItem) {
        const operations = this.operationProvider.getEditItemAdditionalOperations(item, undefined, { isEditingPageContent: true }, this.getOperationsDataAdditionalQueryParams());
        this.registerSubscription(operations.subscribe(x => {
            this.additionalActionOperations.next(x);
        }));
    }

    private loadPersonalizationOperations(item: DataItem) {
        const operations = this.operationProvider.getEditItemPersonalizationOperations(item, undefined, { isEditingPageContent: true }, this.getOperationsDataAdditionalQueryParams());
        this.registerSubscription(operations.subscribe(x => {
            this.personalizationOperations.next(x);
        }));
    }

    protected getOperationsDataAdditionalQueryParams(): { [key: string]: string } {
        const segmentId = this.route.snapshot.queryParams[QUERY_PARAMS.SEGMENT];
        if (segmentId)
            return { [QUERY_PARAMS.SEGMENT]: segmentId };

        return null;
    }

    private handleChangeCulture(actionButton: ActionButton) {
        this.loading = true;
        this.registerSubscription(this.canDeactivate().subscribe((navigate) => {
            if (navigate) {
                const selectedCulture = actionButton.context.additionalText;
                const dataItemInSelectedCulture = DataItem.fromCulture(this.item$.getValue(), selectedCulture);

                const loadingContext: LoadingActionContext = {
                    actionName: OPERATION_NAMES.editContent,
                    item: dataItemInSelectedCulture,
                    route: this.route,
                    loadingHolder: this
                };

                this.actionHandler().tryHandleAction(loadingContext).subscribe();
            } else {
                this.loading = false;
            }
        }));
    }

    private reload(): Observable<boolean> {
        const loadingContext: LoadingActionContext = {
            actionName: OPERATION_NAMES.editContent,
            item: this.item$.getValue(),
            route: this.route,
            loadingHolder: this
        };

        return this.pagesCommonActionHandler.tryHandleAction(loadingContext);
    }

    private reloadWithCheckForChanges(sourceOperation: Operation) {
        this.registerSubscription(this.canDeactivate().subscribe((navigate) => {
            if (navigate) {
                const loadingContext: LoadingActionContext = {
                    actionName: OPERATION_NAMES.editContent,
                    item: this.item$.getValue(),
                    route: this.route,
                    loadingHolder: this,
                    additionalQueryParams: sourceOperation.ContextParameters
                };

                this.pagesCommonActionHandler.tryHandleAction(loadingContext).subscribe();
            } else {
                this.loading = false;
            }
        }));
    }

    private handlePersonalizedWidgetVersions(actionButton: ActionButton) {
        const queryParam = actionButton.sourceOperation.ContextParameters.find(x => x.Name === QUERY_PARAMS.WIDGET_SEGMENT_ID);
        if (queryParam) {
            const segmentId = this.route.snapshot.queryParams[QUERY_PARAMS.SEGMENT];
            this.enhancedPageComponenent.reloadPersonalizedWidgets(segmentId, queryParam.Value);
        }
    }

    private handleSetCustomExpiration() {
        const item = this.route.snapshot.data[ITEM_DATA_KEY].item as DataItem;
        this.pagesCommonActionHandler.tryHandleAction({
            actionName: OPERATION_NAMES.setCustomExpiration,
            item: item,
            route: this.route
        });
    }

    private handleDeletePersonalizedVersion(actionButton: ActionButton) {
        const context: ExecuteServerAction = {
            updateItem: {
                dataItem: this.item$.getValue(),
                additionalQueryParams: {[QUERY_PARAMS.SEGMENT]: this.state.SegmentId}
            },
            route: this.route,
            actionButton: actionButton,
            actionButtonStateService: this.buttonStateService
        };

        const execute$ = this.serviceOperationsExecutor.execute(context);
        this.registerSubscription(execute$.pipe(this.catchErrorAndShowNotification()).subscribe((value) => {
            if (!value) {
                return;
            }

            if (value.operationResult) {
                if (value.operationResult.Success) {
                    const deletedSegment = actionButton.sourceOperation.ContextParameters.find(x => x.Name === OPERATION_PARAMETERS.segmentForDeletion)?.Value;
                    if (this.state.SegmentId === deletedSegment) {
                        this.reloadWithCheckForChanges(actionButton.sourceOperation);
                    } else {
                        if (value.dataItem)
                            this.initFromDataItem(value.dataItem, false, false);
                    }
                }
            }
        }));
    }

    private handleMobilePreview(button: ActionButton) {
        this.handleServerCommand(button).subscribe(itemResult => {
            if (itemResult.operationData?.PreviewUrl) {
                const command = new MobilePreviewCommand(this.modalWindowService);

                command.execute({
                    currentRoute: this.route.parent,
                    model: null,
                    data: {
                        previewUrl: itemResult.operationData?.PreviewUrl
                    }
                });
            }
        });
    }

    private handleNavigate() {
        this.registerSubscription(this.actionHandler().navigateToTitleAndProperties({
            actionName: OPERATION_NAMES.edit,
            item: this.item$.getValue(),
            route: this.route
        }).subscribe((navResult) => {
            if (navResult.success) {
                this.buttonStateService.updateActionButtonsState(null, ButtonState.Loading);
                this.initFromDataItem(navResult.dataItem, false, false);
            }
        }));
    }

    private handleDuplicate() {
        this.registerSubscription(this.canDeactivate().subscribe((navigate) => {
            if (navigate) {
                this.registerSubscription(this.actionHandler().navigateToDuplicate({
                    actionName: OPERATION_NAMES.edit,
                    item: this.item$.getValue(),
                    route: this.route
                }).subscribe());
            }
        }));
    }

    private handleServerCommand(actionButton: ActionButton): Observable<ItemWithOperationResult> {
        let redirect: Window;
        if (actionButton.sourceOperation.HasLinkResult && !actionButton.requiresConfirmation) {
            redirect = this.windowProvider.open(stringConstants.EMPTY_STRING, NEW_TAB_TARGET);
        }

        const context: ExecuteServerAction = {
            updateItem: {
                dataItem: this.item$.getValue(),
                fallbackProperties: this.fallbackProperties,
                additionalQueryParams: {[QUERY_PARAMS.SEGMENT]: this.state?.SegmentId}
            },
            route: this.route,
            actionButton: actionButton,
            actionButtonStateService: this.buttonStateService,
            window: redirect
        };

        let execute$: Observable<ItemWithOperationResult> = null;
        if (actionButton.sourceOperation?.Name === OPERATION_NAMES.stopSyncing) {
            execute$ = this.canDeactivate().pipe(filter(x => x), switchMapTo(this.serviceOperationsExecutor.execute(context)));
        } else {
            execute$ = this.serviceOperationsExecutor.execute(context);
        }

        this.registerSubscription(execute$.pipe(catchError((err) => { if (actionButton.name === OPERATION_NAMES.preview) { return EMPTY; } else { return throwError(err); } }), this.catchErrorAndShowNotification()).subscribe((value) => {
            if (!value) {
                return;
            }

            if (value.operationResult) {
                // Operation result is returned from CreatePersonalizedVersion operation in order to load newly created personalized version.
                if (value.operationResult.Success && value.operationResult.Title === "newSegment") {
                    // available actions holds newly created personalization segmentId.
                    const action = value.operationResult.AvailableActions[0];
                    this.reloadWithCheckForChanges({ Name: action, Category: { Name: OPERATION_CATEGORIES.personalized }, ContextParameters: [{Name: QUERY_PARAMS.SEGMENT, Value: action }] });
                    return;
                }
            }

            const sourceOperation = actionButton.sourceOperation;
            const isDelete = sourceOperation.PerformsDelete;

            const unlocks = sourceOperation.RequiresItemUpdate || isDelete;
            if (unlocks)
                this.locked = false;

            let filterParam = "dynamic-item";
            if (isDelete)
                filterParam = value.dataItem.metadata.typeFullName;

            this.preserveNotificationOnBackNavigation = isDelete;
            this.notificationService.publishNotificationFromOperationResult(value, filterParam);
            if (isDelete) {
                this.editMenu.onLeftNavButtonClick();
                return;
            }

            if (actionButton.sourceOperation && actionButton.sourceOperation.ParentOperation && actionButton.sourceOperation.ParentOperation.Name === OPERATION_NAMES.edit) {
                const shouldStayAfterPublish = this.serviceOperationsExecutor.shouldStayAfterPublish(actionButton);

                if (!shouldStayAfterPublish) {
                    this.registerSubscription(timer(STAY_AFTER_PUBLISH_TIMEOUT).subscribe(() => {
                        this.editMenu.onLeftNavButtonClick();
                    }));

                    return;
                }
            }

            if (value.dataItem) {
                const shouldRefresh = (this.entityData.metadata.setName === ENTITY_SET.FORMS && actionButton.sourceOperation?.Name === OPERATION_NAMES.publish) || actionButton.sourceOperation?.Name === OPERATION_NAMES.stopSyncing;
                this.initFromDataItem(value.dataItem, shouldRefresh, shouldRefresh);
            }
        }));

        return execute$;
    }

    private lock(): Observable<boolean> {
        const lock$ = new ReplaySubject<boolean>(1);
        if (!this.locked && !this.lockingInitiated) {
            // without this flag several Lock requests may be made as the sources of the lock initiation are multiple
            this.lockingInitiated = true;
            const itemData = <ItemData>this.route.snapshot.data[ITEM_DATA_KEY];
            this.registerSubscription(this.zoneEditorContract.lock({ state: this.state, dataItem: itemData.item }).pipe(catchError((err) => {
                if (err instanceof LockedItemError) {
                    this.openLockedScreen(itemData.item);
                    this.lockingInitiated = false;
                    lock$.next(this.locked);
                } else {
                    lock$.error(err);
                }

                return empty();
            })).subscribe((stateAfterLock) => {
                this.locked = true;
                this.lockingInitiated = false;
                this.state = stateAfterLock;

                if (this.state.HasChanged) {
                    this.openLockedScreen(itemData.item);
                    lock$.next(false);
                } else {
                    lock$.next(this.locked);
                }
            }));
        } else {
            lock$.next(this.locked);
        }

        return lock$.asObservable();
    }

    private openLockedScreen(dataItem: DataItem) {
        this.loading = true;
        this.locked = false;
        this.pagesCommonActionHandler.tryHandleAction({
            actionName: OPERATION_NAMES.editContent,
            item: dataItem,
            route: this.route
        });
    }

    private catchErrorAndShowNotification<T, O>(): OperatorFunction<T, T | ObservedValueOf<O>> {
        return this.notificationService.catchErrorAndShowNotification(ZONE_EDITOR_NOTIFICATION_FILTER);
    }
}
