import { CanActivate, Router, ActivatedRouteSnapshot } from "@angular/router";
import { Injectable } from "@angular/core";

import { DynamicItemComponent } from "../../components/entity/dynamic-item.component";
import { DynamicItemUrlSegment } from "../../services/entity/dynamic-item-url-segment";
import { ROUTE_PATHS } from "../../../../../constants/route-paths";
import { CanDeactivateGuard } from "../../../../shared/guards/can-deactivate.guard";

@Injectable()
export class DynamicItemGuard extends CanDeactivateGuard<DynamicItemComponent> implements CanActivate {
    constructor(private router: Router) {
        super();
    }

    canActivate(route: ActivatedRouteSnapshot): boolean {
        const itemUrlSegment = new DynamicItemUrlSegment(route.url[0].path);
        const hasValidId = Boolean(itemUrlSegment.itemId);

        if (!hasValidId) {
            this.router.navigate([ROUTE_PATHS.NOT_FOUND]);
        }

        return hasValidId;
    }
}
