import { of as observableOf,  Observable, BehaviorSubject } from "rxjs";

import { Injectable, ClassProvider } from "@angular/core";
import { AuthProvider, AUTH_PROVDER_TOKEN, Token } from "./auth.provider";
import { TokenProvider } from "./token.provider";
import { Settings } from "../shared/services/settings.service";

// Provider is used to authenticate via the cookie issued by Sitefinity in integrated mode.
@Injectable()
export class NoAuthTokenProvider extends TokenProvider implements AuthProvider {
    constructor(private settings: Settings) {
        super();
    }

    init(): Observable<void> {
        return new BehaviorSubject<void>(null);
    }

    signIn(returnUrl: string): Observable<void> {
        return observableOf();
    }

    signOut(): Observable<void> {
        return observableOf();
    }

    isLoggedIn(): Observable<boolean> {
        return observableOf(true);
    }

    getToken(): Observable<Token> {
        return observableOf<null>();
    }

    getName(): string {
        return "noauth";
    }

    isAvailable(): Observable<boolean> {
        return observableOf(this.settings.authenticationProtocol === "Default" || this.settings.authenticationProtocol === "OpenId");
    }

    getPriority(): number {
        return 0;
    }
}

export const NO_AUTH_PROVIDER: ClassProvider = {
    multi: true,
    provide: AUTH_PROVDER_TOKEN,
    useClass: NoAuthTokenProvider
};
