import { of as observableOf, Observable } from "rxjs";
import { catchError, map } from "rxjs/operators";
import { ClassProvider, Injectable } from "@angular/core";
import { InsightCellComponent } from "../components/insight-cell/insight-cell.component";
import { ConnectorService } from "./connector.service";
import { ExtensionPointUtilsService } from "./extension-point-utils.service";
import {
    COLUMN_NAMES,
    COLUMNS_TOKEN,
    ColumnsProvider
} from "../../../content/dynamic-modules/components/columns-provider";
import { EntityData } from "../../../content/dynamic-modules/interfaces";
import { ColumnModel } from "../../models/column-model";

@Injectable()
class InsightsColumnProvider implements ColumnsProvider {
    constructor(
        private readonly sitefinityInsightConnectorService: ConnectorService,
        private readonly extensionPointUtils: ExtensionPointUtilsService) {
    }

    getColumns(entityData: EntityData): Observable<ColumnModel[]> {
        if (this.extensionPointUtils.shouldExtendGrid(entityData.metadata) === false)
            return observableOf([]);

        return this.sitefinityInsightConnectorService.isSitefinityInsightEnabled().pipe(map(isSitefinityInsightEnabled => {
           if (isSitefinityInsightEnabled === false)
               return [];

           const column: ColumnModel = {
               name: COLUMN_NAMES.INSIGHTS_COL_NAME,
               title: COLUMN_NAMES.INSIGHTS_COL_NAME,
               css: "-col-size-2xs",
               componentData: {
                   type: InsightCellComponent
               }
           };

           return [column];
        }),
        catchError(err => {
            return observableOf([]);
        }));
    }

    getColumnsToRemove(entityData: EntityData): Observable<string[]> {
        return observableOf([]);
    }
}

export const INSIGHTS_COLUMNS_PROVIDER: ClassProvider = {
    useClass: InsightsColumnProvider,
    multi: true,
    provide: COLUMNS_TOKEN
};
