import { Injectable } from "@angular/core";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ImageComponent } from "../../../../../fields/media/image/image.component";
import { VideoPlayerComponent } from "../../../../../fields/media/video/video-player.component";
import { DocumentComponent } from "../../../../../fields/media/document/document.component";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";

const PREVIEW_URL_PROP_NAME: string = "Url";
const THUMBNAIL_PREVIEW_URL_PROP_NAME: string = "ThumbnailUrl";

@Injectable()
export class MediaRecognizerService {
    private specificFieldsData: any;

    constructor() {
        this.specificFieldsData = {};
    }

    hasSpecificField(file: ContentTypeObject): boolean {
        return this.specificFieldsData[file.contentType];
    }

    hasPreview(type: string): boolean {
        return type === ENTITY_SET.IMAGES || type === ENTITY_SET.VIDEOS;
    }

    getPreviewUrlProperty(type: string): string {
        if (type === ENTITY_SET.IMAGES) {
            return THUMBNAIL_PREVIEW_URL_PROP_NAME;
        }

        return PREVIEW_URL_PROP_NAME;
    }

    getComponentData(properties: any): ComponentData {
        let mediaType: MediaTypes;

        if (!properties.isMultimedia) {
            mediaType = MediaTypes.Document;
        } else {
            mediaType = this.getMediaType(properties);
        }

        switch (mediaType) {
            case MediaTypes.Image:
                return { properties, type: ImageComponent };
            case MediaTypes.Video:
                return { properties, type: VideoPlayerComponent, removePreviousView: true};
            case MediaTypes.Document:
                return { properties, type: DocumentComponent };
            case MediaTypes.Broken:
                //// Marking the images with error to display the No preview available message
                properties.doesNotSupportPreview = true;
                return { properties, type: properties.isVideo ? VideoPlayerComponent : ImageComponent };
        }
    }

    private getMediaType(properties: MediaContentProperties): MediaTypes {
        const videoTypeRegex = new RegExp("video[s]?\/");
        const imageTypeRegex = new RegExp("image[s]?\/");

        const type = properties.type || properties.contentType;
        const hasVideoMimeType = videoTypeRegex.test(type);
        const hasImageMimeType = imageTypeRegex.test(type);

        // Handle a supposedly very rare case where a non video or image item is uploaded in a video/image library.
        // Videos will get persisted, but images will not since they are uploaded through the .NET object
        // System.Drawing.Image.FromStream(source) which will throw an exception if the data stream is not an image
        const misplacedFileInVideoLibrary = properties.isVideo && !hasVideoMimeType;
        const misplacedFileInImageLibrary = !properties.isVideo && properties.isMultimedia && !hasImageMimeType;
        if (!type || misplacedFileInVideoLibrary || misplacedFileInImageLibrary) {
            return MediaTypes.Broken;
        }

        /*
            There are 3 cases:
                1) dataUrl is blob reference
                2) dataUrl is https://sitefinity.com/images/...
                3) dataUrl is image/jpeg
        */
        if (hasImageMimeType) {
            return MediaTypes.Image;
        } else if (hasVideoMimeType) {
            return MediaTypes.Video;
        } else {
            return MediaTypes.Document;
        }
    }

    async getMediaMimeType(url: string): Promise<string> {
        const response = await fetch(url);
        const blob = await response.blob();
        return blob.type;
    }
}

export enum MediaTypes {
    Video = 0,
    Image = 1,
    Document = 2,
    Broken = 4
}

interface MediaContentProperties {
    type: string,
    isVideo: boolean,
    contentType: string,
    isMultimedia: boolean
}

interface ContentTypeObject {
    contentType: string;
}
