import { DataItem } from "../../interfaces";
import { Observable } from "rxjs";
import { Operation, OperationCategory } from "../../../../shared/components/action-menu/operation.model";
import { CommandModelBase } from "../../../../shared/commands/command-model-base";
/**
 * The context for fetching operations in a {@link OperationsProvider}
 * @ExposedInApi {OperationsData} CommandsData v1/commands/commands-data.d.ts
 */
export class OperationsData {
    constructor(
        public readonly dataItem: DataItem,
        public readonly target: OperationsTarget,
        public readonly parentItem?: DataItem,
        public contextData: OperationsDataContext = {},
        public additionalQueryParams: { [key: string]: string } = null) { }
}

/**
 * The place where the operations are intended for.
 * @ExposedInApi {OperationsTarget} CommandsTarget v1/commands/commands-target.d.ts
 */
export enum OperationsTarget {
    List = 1,
    Edit = 2,
    EditLocked = 3,
    Bulk = 4,
    Create = 5
}

export interface OperationsDataContext {
    isHierarchicalView?: boolean;
    isEditingPageContent?: boolean;
    origin?: string;
    viewName?: string;
    disregardCache?: boolean;
}

/**
 * A provider used for retrieving operations for items.
 * @ExposedInApi {OperationsProvider} CommandProvider v1/commands/commands-provider.d.ts
 */
export interface OperationsProvider {
    /**
     * Fetches the operations for the provided context.
     * @param data The context for the operations.
     */
    getOperations(data: OperationsData): Observable<Operation[]>;

    /**
     * Fetches the commands for the provided context.
     * @param data The context for the commands.
     */
    getCommands(data: OperationsData): Observable<CommandModelBase[]>;

    /**
     * Fetches the command categories for the provided context.
     * @param data The context for the categories.
     */
    getCategories(data: OperationsData): Observable<OperationCategory[]>;

    /**
     * Invalidates cached operations for a specific item.
     * @param itemId The id of the item to invalidate operations.
     */
    invalidateCachedItemOperations(itemId: string): void;
}
