import { AfterViewInit, Directive, ElementRef, HostBinding, HostListener, Inject, Input } from "@angular/core";
import { WINDOW_TOKEN } from "../../../src/app/window.provider";

@Directive({
    selector: "[sfFixOnScroll]",
    exportAs: "sfFixOnScroll"
})
export class FixOnScrollDirective implements AfterViewInit {

    @Input() topMargin = 0;
    @Input() zIndex = 1;
    @HostBinding("attr.class") cssClass = "-sf-absolute";

    constructor(private el: ElementRef, @Inject(WINDOW_TOKEN) private window: Window) {
    }

    ngAfterViewInit() {
        this.setTopPosition();
    }

    @HostListener("window:scroll") moveOnScroll() {
       this.setTopPosition();
    }

    private setTopPosition() {
        this.el.nativeElement.style.top = `${this.window.scrollY}px`;
        this.el.nativeElement.style.zIndex = this.zIndex;
    }
}
