import { Component, Inject, OnInit } from "@angular/core";
import { DataContext, DataContextComponent } from "../../../shared/models/data-context-component";
import { WINDOW_TOKEN } from "../../../../window.provider";
import { NEW_TAB_TARGET } from "../../../../common-constants";

@Component({
    templateUrl: "./page-view.component.html"
})
export class PageViewComponent implements DataContextComponent, OnInit {
    public context: DataContext;
    public isViewLinkVisible: boolean = false;
    public viewUrl: string;

    constructor(@Inject(WINDOW_TOKEN) private window: Window) { }

    ngOnInit() {
        if (!this.context || !this.context.dataItem) {
            return;
        }

        if (!this.context.dataItem.isTranslated || (this.context.dataItem.data && this.context.dataItem.data.PageType === "Group")) {
            this.isViewLinkVisible = false;
        } else {
            this.isViewLinkVisible = true;
            this.viewUrl = this.context.dataItem.data.ViewUrl;
        }
    }
    //// We need handler for the click event. As the PageViewComponent is hosted inside of a Grid column which is not clickable.
    //// We also need href bindings for the case when we right click on the link and press open in new tab.
    onClickHandler() {
        this.window.open(this.viewUrl, NEW_TAB_TARGET);
    }
}