import { Component, OnInit, QueryList, ViewChildren } from "@angular/core";
import { FormGroup, FormControl } from "@angular/forms";
import { FieldBase } from "../../../../../../fields";
import { CompositeFieldSettings } from "../../../shared/services/composite-field.settings";
import { FormFieldWrapperComponent } from "../../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";

export const SEARCH_SITE_PROPERTIES = {
    INCLUDE_IN_SEARCH_INDEX: "IncludeInSearchIndex",
    CRAWLABLE: "Crawlable",
    PRIORITY: "Priority"
};

@Component({
    selector: "sf-search-site-composite-field",
    templateUrl: "./search-site.composite.component.html"
})
export class SearchSiteCompositeComponent extends FieldBase<CompositeFieldSettings> implements OnInit {

    form: FormGroup = new FormGroup({});

    @ViewChildren(FormFieldWrapperComponent) protected fields: QueryList<FormFieldWrapperComponent>;

    showPriorityField: boolean;

    ngOnInit() {
        super.ngOnInit();
        this.initializeForm();
    }

    writeValue(updatedValues: SearchSiteData) {
        if (!updatedValues) {
            return;
        }

        let compositeValue = this.getValue();
        if (compositeValue === null || !Object.keys(compositeValue).length) {
            compositeValue = {};
        }

        const result = Object.assign({}, compositeValue, updatedValues);

        if (result.hasOwnProperty(SEARCH_SITE_PROPERTIES.CRAWLABLE)) {
            this.showPriorityField = result[SEARCH_SITE_PROPERTIES.CRAWLABLE];
        }

        super.writeValue(result);
    }

    private initializeForm() {
        Object.keys(this.settings.innerFields).forEach((fieldName) => {
            const fieldData = this.settings.innerFields[fieldName];
            if (fieldData != null) {
                const value = fieldData.value;
                const formControl = new FormControl(value);
                this.form.setControl(fieldData.key, formControl);

                if (fieldName === SEARCH_SITE_PROPERTIES.CRAWLABLE) {
                    this.showPriorityField = value;
                } else if (fieldName === SEARCH_SITE_PROPERTIES.PRIORITY) {
                    fieldData.settings.showTitle = true;
                }
            }
        });
    }
}

export interface SearchSiteData {
    IncludeInSearchIndex?: boolean;
    Crawlable?: boolean;
    Priority?: number;
}
