import { Component, Input, ViewChild, OnInit } from "@angular/core";
import { DataItem, EntityData } from "../../interfaces";
import { EditableFieldsComponent } from "../../../../shared/fields-builder/components/editable-fields/editable-fields.component";
import { FieldSectionModel } from "../../../../../services/fieldSection.model";
import { FieldsGeneratorService } from "../../../../shared/services/fields-generator.service";
import { BackendTweaksStore } from "../../services/backend-tweaks/backend-tweaks.store";
import { FieldTypes } from "../../../../shared/fields-builder/services/fields-registry";
import { createFieldModel } from "../../../../shared/fields.constants";
import { CompositeFieldsProvider } from "../../../../shared/fields-builder/providers/fields-provider";
import { FileListSettings } from "../../../../libraries/file-list.settings";
import { FieldModel } from "../../../../../services/field.model";
import { VIEW_NAME } from "../../../constants";
import { ItemListSettings } from "./item-list-settings";
import { ENTITY_SET } from "../../../../shared/services/metadata/meta-data-constants";
import { TaxonomySettings } from "../../../../taxonomy";
import { DynamicItemService } from "../../services/dynamic-item.service";
import { ReplaySubject } from "rxjs";
import { stringConstants } from "../../../../../common-constants";

export const ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME = "ItemsWithAssignedTaxons";

@Component({
    templateUrl: "./assign-taxons.component.html"
})
export class AssignTaxonsComponent implements OnInit {
    @ViewChild(EditableFieldsComponent, { static: false }) editableFieldsComponent: EditableFieldsComponent;
    @Input() items: DataItem[];
    @Input() fieldNames: string[];
    superScript: ReplaySubject<string>;
    fieldsSections: FieldSectionModel[];

    constructor(private fieldsGeneratorService: FieldsGeneratorService,
        private backendTweaksStore: BackendTweaksStore,
        private fieldsProvider: CompositeFieldsProvider,
        private dynamicService: DynamicItemService) { }

    ngOnInit() {
        if (this.items.length > 0) {
            this.generateFieldSections(this.items[0]);
        }
    }

    private generateFieldSections(dataItem: DataItem): void {
        const section = new FieldSectionModel({
            isExpanded: true,
            isMain: true,
            insertHorizontalRule: false
        });

        const cachedTweaks = this.backendTweaksStore.getFormByType(dataItem.metadata.setName, VIEW_NAME.EDIT);

        if (cachedTweaks.length > 0) {
            this.populateSections(dataItem, section);
        } else {
            this.backendTweaksStore.initializeForm(dataItem.metadata.setName, VIEW_NAME.EDIT, null, dataItem.provider, dataItem.culture).then(() => {
                this.populateSections(dataItem, section);
            });
        }
    }

    private populateSections(dataItem: DataItem, section: FieldSectionModel): void {
        const fields = this.fieldsGeneratorService.generateFieldModels(this.items[0].metadata, dataItem.metadata.setName, this.backendTweaksStore, dataItem);
        const taxaFields = fields.filter(x => x.selector === FieldTypes.taxa && this.fieldNames.indexOf(x.key) > -1);

        const taxaFieldsString = taxaFields.map(x => `Taxonomy_${(x.settings as TaxonomySettings).name}`).filter((value, index, self) => {
            return self.indexOf(value) === index;
        }).join(stringConstants.COMMA);

        if (taxaFieldsString) {
            this.dynamicService.executeUnboundFunction<{ FieldSettings: FieldSettings[] }>(`Default.TaxonomyFieldSettings(itemType='${dataItem.metadata.typeFullName}', provider='${dataItem.provider}', types=@param)?@param='${taxaFieldsString}'`).subscribe((x) => {
                const fieldSettings = x.FieldSettings;

                taxaFields.forEach(field => {
                    const taxaSettingField = fieldSettings.filter(x => x.Key === `Taxonomy_${(field.settings as TaxonomySettings).name}`)[0];
                    if (taxaSettingField) {
                        field.settings.allowCreate = taxaSettingField.AllowCreate;
                        field.settings.allowView = taxaSettingField.AllowView;
                    }

                    field.settings.culture = dataItem.culture;
                    field.settings.look = "justify-content-center";
                });

                this.addFieldsToSection(dataItem, taxaFields, section);
            });
        }
        else {
            this.addFieldsToSection(dataItem, taxaFields, section);
        }
    }

    private generateFileListModel(entityData: EntityData): FieldModel {
        const filedTitle = " ";
        const fieldType = entityData.metadata.isMedia ? FieldTypes.fileList : FieldTypes.itemList;
        const fieldModel = createFieldModel(this.fieldsProvider, entityData.metadata.setName, fieldType, ITEMS_WITH_ASSIGNED_TAXONS_LIST_FIELD_NAME, this.items, {}, filedTitle);
        const showStatus = this.canShowStatus(entityData);
        this.setSettingsForFieldModel(fieldModel, showStatus);

        return fieldModel;
    }

    private setSettingsForFieldModel(fieldModel: FieldModel, showStatus: boolean) {
        if (fieldModel.settings instanceof FileListSettings) {
            const fileListSettings = fieldModel.settings as FileListSettings;
            fileListSettings.showRemoveButton = true;
            fileListSettings.isSelectable = false;
            fileListSettings.isCentered = true;
            fileListSettings.itemsCount = this.superScript;
        } else if (fieldModel.settings instanceof ItemListSettings) {
            const itemListSettings = fieldModel.settings;
            itemListSettings.showRemoveButton = true;
            itemListSettings.showTitle = false;
            itemListSettings.showStatus = showStatus;
            itemListSettings.itemsCount = this.superScript;
        }
    }

    private canShowStatus(entityData: EntityData): boolean {
        const canShowStatus = entityData.metadata.setName !== ENTITY_SET.CONTENT_ITEMS && entityData.metadata.setName !== ENTITY_SET.BLOGS && entityData.metadata.setName !== ENTITY_SET.LISTS;
        return canShowStatus;
    }

    private addFieldsToSection(dataItem: DataItem, taxaFields: FieldModel[], section: FieldSectionModel): void {
        section.fields = taxaFields;
        section.fields.push(this.generateFileListModel(dataItem));
        this.fieldsSections = [section];
    }
}

interface FieldSettings {
    Key: string;
    AllowCreate: boolean;
    AllowView: boolean;
}
