import { SettingsBase } from "./../field-settings-base";
import { NOT_SELECTED } from "../../src/app/common-constants";
import { DISPLAY_MODE } from "../fields-constants";
import { RELATE_DATA_PROVIDER } from "../common/common-constants";
import { ExtendedKeyValuePair } from "../services/base.service";

export class RelatedDataSettings extends SettingsBase {
    public type: string;
    public provider: string;
    public allowMultiple: boolean;
    public disableInteraction: boolean;
    public displayMode: string;
    public useLiveData: boolean;
    public skipInputSelection: boolean;
    public hideStatus: boolean;
    public showSiteSelector: boolean;
    public displayFieldName: string;
    public filter: ExtendedKeyValuePair[];

    public init(metadata: any): void {
        super.init(metadata);
        this.defaultValue = [];
        this.changeOnFocus = true;
        this.displayMode = DISPLAY_MODE.NORMAL;
        this.provider = metadata[RELATE_DATA_PROVIDER];

        this.emptyValueText = NOT_SELECTED;
        this.hintPositionTop = true;
    }
}
