import { LayoutService, DEFAULT_BOX_HEIGHT, DOCUMENT_ROW_HEIGHT, DEFAULT_BOX_SPACING } from "./services/layout.service";
import { MediaEntity } from "../shared/services/metadata/meta-data.store";
import { EntityData } from "../content/dynamic-modules/interfaces";
import { SfRxBase } from "@progress/sitefinity-component-framework";

const IMAGE_INUPUT_OFFSET = 55;

export class FileLayoutBaseComponent extends SfRxBase {
    multiple: boolean;
    layout: any;
    mediaEntityData: EntityData;
    imageInputOffset = IMAGE_INUPUT_OFFSET;

    constructor(protected layoutService: LayoutService) {
                    super();
                }

    protected recalculateLayout(files, wrapper) {
        if (!this.multiple || !wrapper) {
            return;
        }

        let boxHeight: number = DEFAULT_BOX_HEIGHT;

        if (!this.mediaEntityData.metadata.isMultimedia) {
            boxHeight = DOCUMENT_ROW_HEIGHT;
        }

        if (wrapper.nativeElement.style.width !== "auto") {
            wrapper.nativeElement.style.width = "auto";
        }

        this.layout = this.layoutService.layout(files, wrapper.nativeElement.offsetWidth, boxHeight, DEFAULT_BOX_SPACING, Number.POSITIVE_INFINITY, this.mediaEntityData.metadata as MediaEntity);

        let layoutRow = 0;
        let wrapperWidth = 0;

        for (let i = 0; i < this.layout.boxes.length; i++) {
            if (i > 0 && this.layout.boxes[i].top > this.layout.boxes[i - 1].top) {
                layoutRow++;
            }
            this.layout.boxes[i].row = layoutRow;
            if (layoutRow === 0) {
                wrapperWidth += this.layout.boxes[i].width + DEFAULT_BOX_SPACING;
            }
        }

        if (layoutRow === 0 && wrapperWidth > 0) {
            wrapper.nativeElement.style.width = wrapperWidth + "px";
        }
    }
}
