import { DynamicItemStrategyBase } from "./strategies/dynamic-item.strategy";
import { ActivatedRoute, ActivatedRouteSnapshot } from "@angular/router";
import { ROUTE_PARAMS } from "../../constants";

export function getSetNameFromRoute(route: ActivatedRoute): string {
    let typeName: string = null;
    if (route.snapshot && route.snapshot.params) {
        typeName = DynamicItemStrategyBase.getSet(route.snapshot);
    }

    if (!typeName && route.parent && route.parent.snapshot && route.parent.snapshot.params) {
        typeName = DynamicItemStrategyBase.getSet(route.parent.snapshot);
    }

    return typeName;
}

export function getRouteDataRecursively(route: ActivatedRouteSnapshot, key: string) {
    if (!route)
        return;

    const resolvedVal = route.data ? route.data[key] : undefined;
    if (!resolvedVal) {
        return getRouteDataRecursively(route.parent, key);
    }

    return resolvedVal
}

export function getRouteDynamicTypeNameRecursively(route: ActivatedRouteSnapshot) {
    if (!route)
        return;

    const dynamicTypeName = route?.params[ROUTE_PARAMS.TYPE_NAME_SEGMENT] || route?.data[ROUTE_PARAMS.TYPE_NAME_SEGMENT];
    if (!dynamicTypeName) {
        return getRouteDynamicTypeNameRecursively(route.parent);
    }

    return dynamicTypeName;
}
