import { Command } from "../../../../../shared/commands/command";
import { Injectable, Inject } from "@angular/core";
import { ExecutionContext } from "../../../../../shared/commands/execution-context";
import { Observable ,  ReplaySubject } from "rxjs";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { ReorderComponent } from "../../../components/reorder/reorder.component";
import { Button, ConfirmButton, CancelButton, DialogData, ModalWindowService, ClickResult, ClosingContext, ClosingContextType } from "../../../../../shared/services/modal-window.service";
import { EntityData, DataItem } from "../../../interfaces";
import { ActivatedRoute } from "@angular/router";
import { ResponseError } from "../../../../../shared/services/errors/response-error";
import { DynamicItemStore } from "../../dynamic-item.store";
import { ActionEvent } from "../../entity/action-buttons";
import { NotificationData, NOTIFICATION_LOOKS } from "../../../../../shared/services/notification/notification-data";
import { NOTIFICATION_DURATION_DEFAULT } from "../../../../constants";
import { BulkOperationsNotificationComponent } from "../../../components/bulk-operations/bulk-operations-notification.component";
import { OPERATION_NAMES } from "../../../../../shared/components/action-menu/operation.model";
import { NotificationService, NOTIFICATION_SERVICE } from "../../../../../shared/services/notification/notification.service";
import { BulkResult } from "./bulk-command";
import { map } from "rxjs/operators";
import { ENTITY_SET } from "../../../../../shared/services/metadata/meta-data-constants";
import { FileReorderComponent } from "../../../../../libraries/file-reorder.component";
import { TreeConfig } from "../../../../../../../../fields";

export interface ReorderArgument {
    entityData: EntityData;
    parentItem: DataItem;
    treeConfig: TreeConfig;
}

@Injectable()
export class ReorderCommand implements Command {
    constructor(
        private modalWindowService: ModalWindowService,
        private dynamicItemStore: DynamicItemStore,
        private route: ActivatedRoute,
        @Inject(NOTIFICATION_SERVICE) private notificationService: NotificationService) {
    }

    execute(context: ExecutionContext): Observable<boolean> {
        const args: ReorderArgument = context.data;
        const result = new ReplaySubject<boolean>(1);
        let componentData: ComponentData = null;

        if (args.entityData.metadata.isMultimedia) {
            componentData = {
                type: FileReorderComponent,
                properties: {
                    parentEntityData: args.parentItem,
                    childEntityData: args.entityData
                }
            };
        } else {
            componentData = {
                type: ReorderComponent,
                properties: {
                    parentItem: args.parentItem,
                    entityData: args.entityData
                }
            };

            if (args.treeConfig) {
                componentData.properties.treeConfig = args.treeConfig;
            }
        }

        const buttons: Button[] = [
            new ConfirmButton("Save changes", (data) => this.onSaveClicked(args.entityData, result, data.component)),
            new CancelButton()
        ];

        const dialogData = new DialogData(componentData, (closingContext: ClosingContext) => {
            if (closingContext.type === ClosingContextType.ButtonClicked && closingContext.data && closingContext.data.data && closingContext.data.data.notificationData) {
                this.notificationService.publishNotification(closingContext.data.data.notificationData);
            }
        }, buttons, null, "-bottom");
        this.modalWindowService.setMapping(dialogData);
        this.modalWindowService.open(this.route);

        return result.asObservable();
    }

    private onSaveClicked(entityData: EntityData, subject: ReplaySubject<boolean>, component: ReorderComponent | FileReorderComponent): Observable<ClickResult> {
        const clickResult = new ReplaySubject<ClickResult>(1);
        let subscription;
        let notificationData: NotificationData;
        if (entityData.metadata.isSelfReferencing || entityData.metadata.setName === ENTITY_SET.HIERARCHY_TAXA) {
            if ((component as ReorderComponent).reorderActions.length > 0) {
                subscription = this.dynamicItemStore.executeEntityOperation(entityData, "Default.Reorder", { actions: (component as ReorderComponent).reorderActions })
                .pipe(map((result: BulkResult) => {
                    notificationData = this.getNotification(result.SucceededItemsIds, result.FailedItemsIds, entityData);
                }));
            }
        } else {
            const keyProperty = entityData.metadata.key;
            if (entityData.metadata.isMultimedia) {
                const listComponent = component as FileReorderComponent;
                if (listComponent.isDirty) {
                    subscription = this.dynamicItemStore.executeEntityOperation(entityData, ActionEvent.ReorderItems, { items: listComponent.mediaItems.map(n => n.data[keyProperty]) });
                }
            } else if ((component as ReorderComponent).dirty) {
                subscription = this.dynamicItemStore.executeEntityOperation(entityData, ActionEvent.ReorderItems, { items: (component as ReorderComponent).treeItems.map(n => n[keyProperty]) });
            }
        }

        if (subscription) {
            clickResult.next(new ClickResult(true, false));
            subscription.subscribe(
                null,
                (error: ResponseError) => {
                    subject.error("An error occured while trying to reorder items.");
                },
                () => {
                    clickResult.next(new ClickResult(notificationData ? { notificationData } : true, true));
                    subject.next(true);
                });
        } else {
            clickResult.next(new ClickResult(true, true));
        }

        return clickResult;
    }

    private getNotification(succeededItems: string[], failedItems: string[], entityData: EntityData): NotificationData {
        const operationPartiallySucceeded: boolean = succeededItems && succeededItems.length > 0 && failedItems && failedItems.length > 0;
        const operationFailed: boolean = !operationPartiallySucceeded && failedItems && failedItems.length > 0;
        const operationSucceeded: boolean = !operationPartiallySucceeded && succeededItems && succeededItems.length > 0;

        const notificationData: NotificationData = {
            type: BulkOperationsNotificationComponent,
            properties: {
                succeededItemsIds: succeededItems,
                failedItemsIds: failedItems,
                entityData: entityData,
                operationName: OPERATION_NAMES.reorder.toLowerCase()
            },
            id: "bulkChangeTemplateNotification",
            look: NOTIFICATION_LOOKS.SUCCESS,
            filterParam: entityData.metadata.typeFullName
        };

        if (operationSucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.SUCCESS;
            notificationData.duration = NOTIFICATION_DURATION_DEFAULT;
        } else if (operationFailed) {
            notificationData.look = NOTIFICATION_LOOKS.ERROR;
            notificationData.closeButton = true;
        } else if (operationPartiallySucceeded) {
            notificationData.look = NOTIFICATION_LOOKS.WARNING;
            notificationData.closeButton = true;
        }

        return notificationData;
    }
}
