import { createSelector, select } from "@ngrx/store";
import { AppState } from "../store-schema";

export const COLUMN_SELECTORS = {
    expandedColumnsPerEntity: select(createSelector((state: AppState) => state.columns, state => state.expandedColumnsPerEntity)),
    expandedColumnsPerItem: select(createSelector((state: AppState) => state.columns, state => state.expandedColumnsPerItem))
}
