import { from as observableFrom, of as observableOf, Observable, ReplaySubject, zip } from "rxjs";

import { map, filter as observableFilter, mergeMap, first, every } from "rxjs/operators";
import { Injectable } from "@angular/core";
import { FilterService } from "./filter.service";
import { FiltersResult, FilterValuesOptions, FilterValue, FiltersCountResult, Filter } from "./filter-interfaces";
import { LoadingContentState } from "../../../../../shared/rxjs-extensions/toLoadingState";
import { KeyValuePair } from "./content-filter-count.component";
import { EntityData, TotalCountResult } from "../../../interfaces";
import { MetadataStore } from "../../../../../shared/services/metadata/meta-data.store";
import { MediaHelpers } from "../../../../../libraries/services/media.helpers";
import { ContentFilterService } from "../../../../../shared/services/content-filter.service";

const FILTER_TYPES = {
    ALL: "all-filters",
    CUSTOM_FILTER: "custom-filter",
    PREDEFINED_FILTER: "predifined-filter"
};

const LAST_MODIFIED_CUSTOM_FILTER_NAME = "last-modified";

@Injectable()
export class FilterStore {
    private cache = new Map<string, Observable<FiltersResult>>();
    private dynamicCache = new Map<string, Observable<Filter[]>>();
    private lastEntityData: EntityData;

    constructor(private service: FilterService, private filterService: ContentFilterService, private metadataStore: MetadataStore) { }

    getAllFilters(entityData: EntityData): Observable<FiltersResult> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        this.lastEntityData = modifiedEntityData;
        const key = this.getCacheKey(modifiedEntityData, FILTER_TYPES.ALL);
        if (!this.cache.has(key)) {
            const result = new ReplaySubject<FiltersResult>(1);
            this.cache.set(key, result.asObservable());

            this.service.getFilters(modifiedEntityData).subscribe(x => result.next(x));
        }

        return this.cache.get(key);
    }

    getPredefinedFilters(entityData: EntityData): Observable<FiltersResult> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        this.lastEntityData = modifiedEntityData;
        const key = this.getCacheKey(modifiedEntityData, FILTER_TYPES.PREDEFINED_FILTER);
        if (!this.cache.has(key)) {
            const result = new ReplaySubject<FiltersResult>(1);
            this.cache.set(key, result.asObservable());

            this.service.getFiltersByParameters(modifiedEntityData, false).subscribe(x => result.next(x));
        }

        return this.cache.get(key);
    }

    getCustomFilters(entityData: EntityData): Observable<FiltersResult> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        this.lastEntityData = modifiedEntityData;
        const key = this.getCacheKey(modifiedEntityData, FILTER_TYPES.CUSTOM_FILTER);
        if (!this.cache.has(key)) {
            const result = new ReplaySubject<FiltersResult>(1);
            this.cache.set(key, result.asObservable());

            this.service.getFiltersByParameters(modifiedEntityData, true).subscribe(x => result.next(x));
        }

        return this.cache.get(key);
    }

    getDynamicFilters(entityData: EntityData, parentId: string): Observable<Filter[]> {
        const dynamicFilters = this.service.getDynamicFilters(entityData, parentId).pipe(map(data => {
            return data;
        }));

        const key = this.getCacheKey(entityData, parentId);
        this.dynamicCache.set(key, dynamicFilters);

        return dynamicFilters;
    }

    getDynamicFiltersCache(entityData: EntityData, parentId: string): Observable<Filter[]> {
        const key = this.getCacheKey(entityData, parentId);
        if (!this.dynamicCache.has(key)) {
            return this.getDynamicFilters(entityData, parentId);
        }

        return this.dynamicCache.get(key);
    }

    getFilterValues(entityData: EntityData, filterName: string, filterValuesOptions: FilterValuesOptions): Observable<TotalCountResult<FilterValue[]>> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        return this.service.getFilterValues(modifiedEntityData, filterName, filterValuesOptions);
    }

    getFiltersCount(entityData: EntityData, filterName: string, parentId: KeyValuePair): Observable<LoadingContentState<FiltersCountResult>> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        return this.service.getFiltersCount(modifiedEntityData, filterName, parentId);
    }

    filterValid(entityData: EntityData, currentFilter: string, parentId: string = null): Observable<boolean> {
        const modifiedEntityData = this.modifyEntityData(entityData);
        const result$ = new ReplaySubject<boolean>(1);
        if (currentFilter && this.stateChanged(modifiedEntityData)) {
            const predefinedFiltersObservable = this.getPredefinedFilters(modifiedEntityData).pipe(observableFilter(state => !state.isLoading));
            const dynamicFiltersObservable = this.getDynamicFiltersCache(entityData, parentId);
            zip(predefinedFiltersObservable, dynamicFiltersObservable).pipe(
                mergeMap(data => {
                    const allFilters = data[0].filters.concat(data[1]);
                    if (this.containsFilter(allFilters, currentFilter)) {
                        return observableOf(true);
                    } else {
                        return this.allCustomFilterValuesValid(modifiedEntityData, currentFilter);
                    }
                }),
                first())
                .subscribe(valid => {
                    result$.next(valid);
                }, err => {
                    result$.next(false);
                });
        } else {
            result$.next(true);
        }

        return result$.pipe(first());
    }

    private allCustomFilterValuesValid(entityData: EntityData, filter: string): Observable<boolean> {
        const filters = this.filterService.deserializeQueryParams(filter);
        return observableFrom(filters).pipe(observableFilter(f => f.key !== LAST_MODIFIED_CUSTOM_FILTER_NAME), mergeMap(f => {
            return this.getFilterValues(entityData, f.key, { keys: f.value }).pipe(
                map(r => {
                    return r.dataItems.length === f.value.length;
                }));
        }), every(r => r));
    }

    private containsFilter(filters: Filter[], filterName: string): boolean {
        if (filters && filters.length) {
            return filters.some(f => f.name === filterName);
        }

        return false;
    }

    private stateChanged(entityData: EntityData): boolean {
        const stateChanged: boolean = !this.lastEntityData ||
            (entityData &&
                (this.lastEntityData.metadata.setName !== entityData.metadata.setName ||
                    this.lastEntityData.culture !== entityData.culture ||
                    this.lastEntityData.provider !== entityData.provider));

        return stateChanged;
    }

    private getCacheKey(entityData: EntityData, filterType: string): string {
        return `${entityData.provider}_${entityData.culture}_${entityData.metadata.setName}_${filterType}`;
    }

    private modifyEntityData(entityData: EntityData): EntityData {
        if (MediaHelpers.isAlbumEntity(entityData) || MediaHelpers.isVideosLibraryEntity(entityData)) {
            return {
                metadata: this.metadataStore.getEntity(MediaHelpers.getChildSetName(entityData)),
                culture: entityData.culture,
                provider: entityData.provider
            };
        }
        return entityData;
    }
}
