import { FilterStrategyBase } from "./filter-strategy-base";
import { Filter } from "../dynamic-item.store";

export class SinglePropertyStrategy extends FilterStrategyBase {
    constructor(filter: Filter) {
        super(filter);
    }

    buildQuery(query: any) {
        const propertyName = this.filter.values[0].key;
        const propertyValue = this.filter.values[0].values[0];
        query = query.eq(propertyName, propertyValue);
        return query;
    }
}
