import { Component, Input, ViewChild, ContentChild, OnInit } from "@angular/core";
import { ScrollService } from "../../../src/app/services/scroll.service";
import { StickyHeadingDirective } from "./sticky.heading.directive";
import { StickyDirective } from "../directives/sticky.directive";
import { ReplaySubject } from "rxjs";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { stringConstants } from "../../../src/app/common-constants";

@Component({
    selector: "sf-sticky-component",
    templateUrl: "./sticky.component.html"
})
export class StickyComponent extends SfRxBase implements OnInit {
    @Input() heading: string;
    @Input() subTitle: string;
    @Input() headingLook: string;
    @Input() stickyDisabled: boolean;
    @Input() stickWithDelay: boolean;
    @Input() alwaysSticky: boolean;
    @Input() removeBottomOffset: boolean;
    @Input() hasStickyBuffer: boolean;
    @Input() hideBackToTopButton: boolean;
    @Input() showMainHeading: boolean = true;
    @Input() badgeLook: string = "positive";
    @Input() superScript: ReplaySubject<string>;

    headingCssClass: string;
    superScriptBadge: string;
    countZero: number = 0;

    @ViewChild(StickyDirective, { static: false }) stickyDirective: StickyDirective;
    @ContentChild(StickyHeadingDirective, { static: false }) stickyHeading;

    constructor(private scrollService: ScrollService) {
        super();

        this.hasStickyBuffer = true;
    }

    ngOnInit() {
        if (this.superScript) {
            const subscription = this.superScript.subscribe(superScript => {
                this.superScriptBadge = superScript;
                if (parseInt(this.superScriptBadge) === this.countZero) {
                    this.badgeLook = stringConstants.EMPTY_STRING
                }
            });

            this.registerSubscription(subscription);
        }

        this.headingCssClass = this.generateCssClassList(this.headingLook);
    }

    onBackToTopClicked() {
        this.scrollService.scrollToTop(true, 250);
    }

    get isSticky() {
        if (this.alwaysSticky) {
            return this.alwaysSticky;
        }

        if (this.stickyDirective)
            return this.stickyDirective.isSticky;

        return false;
    }

    generateCssClassList(headingLook) {
        let cls = this.superScriptBadge ? "-justify-content-center" : "";

        if (headingLook && headingLook !== "") {
            cls += " -" + headingLook.split(" ").join(" -");
        } else if (this.superScriptBadge || this.removeBottomOffset) {
            cls += " -sf-mb-3xs";
        } else {
            cls += " -sf-mb-3xl";
        }

        return cls;
    }
}
