import { ClassProvider, Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { HierarchicalService, ID_KEY, PARENT_KEY, TITLE_KEY, HIERARCHICAL_SERVICE_TOKEN } from "../../shared/services/hierarchical-service";
import { ServiceInfo } from "../../../../../fields/selector/selector.component";
import { LoadItemsResponse, LoadItemsByKeysData, LoadItemsData, DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { QUERY_PARAMS, SORT_ORDER } from "../../content/constants";
import { DataItem, EntityData } from "../../content/dynamic-modules/interfaces";
import { createQuery } from "../../../services/query";
import { TaxonomySettings } from "../taxonomy.settings";
import TAXONOMY_CONSTANTS from "../taxonomy.constants";
import { ContentFilterService } from "../../shared/services/content-filter.service";
import { stringConstants } from "../../../common-constants";


const ORDINAL_KEY = "Ordinal";
const TAXONOMY_KEY = "TaxonomyId";
const TAXON_NAME = "TaxonName";
const TAXON = "Taxon";
const TAXONOMIES_SET_NAME = "taxonomies";
const TAXON_TAKE_COUNT = 50;

@Injectable()
export class HierarchicalTaxonomyService extends HierarchicalService {
    constructor(protected dynamicItemService: DynamicItemService, private contentFilterService: ContentFilterService) {
        super(dynamicItemService);
    }

    showStatusIcons(): boolean {
        return false;
    }

    isHierarchical(type: string): boolean {
        return type === TAXONOMY_CONSTANTS.HIERARCHY_TAXA;
    }

    getSetName(): string {
        return TAXONOMIES_SET_NAME;
    }

    isTypeSupported(entityData: EntityData): boolean {
        return TAXON === entityData.metadata.singularName;
    }

    getName(entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        return this.dynamicItemService
            .getItemsByKeys({
                entityData,
                fallbackProperties: [TAXON_NAME, entityData.metadata.defaultFieldName],
                keyProperty: ID_KEY,
                keys: [taxaId]
            });
    }

    getItemTaxa(value: string[], entityData: EntityData, taxaId: string): Observable<LoadItemsResponse> {
        if (value) {
            const numberOfQueries = Math.ceil(value.length / TAXON_TAKE_COUNT);
            const loadItemsDatas: LoadItemsData[] = [];
            let itemToTakeIndex = 0;
            for (let i = 1; i <= numberOfQueries; i++) {
                let query = createQuery().where().or();
                const itemsCountToGet = Math.min(value.length - itemToTakeIndex, TAXON_TAKE_COUNT);
                for (let j = 0; j < itemsCountToGet; j++) {
                    query = query.eq(ID_KEY, value[itemToTakeIndex]);
                    itemToTakeIndex++;
                }

                query = query.done().done() as any;

                const loadItemsData: LoadItemsData = {
                    entityData: entityData,
                    fallbackProperties: [entityData.metadata.defaultFieldName],
                    query
                };
                loadItemsDatas.push(loadItemsData);
            }

            return this.dynamicItemService.getItemListBatchWithMultipleQueries(loadItemsDatas);
        }

        return of({
            dataItems: [],
            totalCount: 0,
            entityData: entityData
        });
    }

    getRecent(entityData: EntityData, settings: TaxonomySettings, value?: string[], taxonId?: string): Observable<LoadItemsResponse> {
        const args: LoadItemsData = {
            entityData: entityData,
            action: taxonId ? this.buildGetAvailableParentTaxonsAction(taxonId, settings.id, true) : "Default.GetRecentTaxons",
            fallbackProperties: [entityData.metadata.defaultFieldName]
        };

        const data = {
            excludedItemIds: [],
            taxonomyId: settings.id
        };
        args.payload = data;
        if (settings.allowMultiple && value) {
            data.excludedItemIds = value;
        }
        
        if (!args.additionalQueryParams) {
            args.additionalQueryParams = {};
        }

        const rootTaxonId = settings.rootTaxonId ?? stringConstants.DEFAULT_GUID;
        args.additionalQueryParams[QUERY_PARAMS.ROOT_TAXON_ID] = rootTaxonId;

        return this.dynamicItemService
            .getRecent(args);
    }

    expandChildren(info: ServiceInfo, entityData: EntityData, taxaId: string, taxonId: string): Observable<LoadItemsResponse> {
        const query = createQuery()
            .where()
            .and()
            .eq(TAXONOMY_KEY, taxaId)
            .eq(PARENT_KEY, info.parentId)
            .done()
            .done();

        const loadItemsData: LoadItemsData = {
            entityData: entityData,
            query,
            order: `${ORDINAL_KEY} ${SORT_ORDER.ASCENDING}`,
            take: info.take,
            skip: info.skip,
            fallbackProperties: [entityData.metadata.defaultFieldName]
        };

        if (taxonId) {
            loadItemsData.action = this.buildGetAvailableParentTaxonsAction(taxonId, taxaId, false);
            return this.dynamicItemService.getItemList(loadItemsData);
        } else {
            return this.dynamicItemService.getItemListBatch(loadItemsData);
        }
    }

    loadMore(info: ServiceInfo, entityData: EntityData, settings: TaxonomySettings, taxonId: string): Observable<LoadItemsResponse> {
        let query = this.getSearchQuery(info.searchText, settings.id, entityData);

        if (settings.type === TAXONOMY_CONSTANTS.HIERARCHY_TAXA && !info.searchText) {
            query = query.eq(PARENT_KEY, null);
        }

        query = query.done().done() as any;

        const shouldApplyRootTaxonId = settings.rootTaxonId && (settings.rootTaxonId !== stringConstants.DEFAULT_GUID);
        let additionalQueryParams = {};
        if (shouldApplyRootTaxonId) {
            additionalQueryParams = {
                [QUERY_PARAMS.ROOT_TAXON_ID]: settings.rootTaxonId
            };
        }

        return this.dynamicItemService
            .getItemList({
                entityData: entityData,
                query,
                fallbackProperties: [entityData.metadata.defaultFieldName],
                order: `${TITLE_KEY} ${SORT_ORDER.ASCENDING}`,
                take: info.take,
                skip: info.skip,
                action: taxonId ? this.buildGetAvailableParentTaxonsAction(taxonId, settings.id, false) : null,
                additionalQueryParams: additionalQueryParams
        });
    }

    getModalItems(entityData: EntityData, taxaId: string, taxonId?: string, targetDataItem?: DataItem, rootTaxonId?: string): Observable<LoadItemsResponse> {
        const loadItemsByKeysData: LoadItemsByKeysData = {
            entityData: entityData,
            fallbackProperties: [entityData.metadata.defaultFieldName],
            keys: [taxaId],
            keyProperty: TAXONOMY_KEY,
            action: taxonId ? this.buildGetAvailableParentTaxonsAction(taxonId, taxaId, false) : null,
            order: `${TITLE_KEY} ${SORT_ORDER.ASCENDING}`
        };

        if (entityData.metadata.setName === TAXONOMY_CONSTANTS.HIERARCHY_TAXA) {
            const shouldApplyParentId = rootTaxonId !== stringConstants.DEFAULT_GUID;
            const query = createQuery()
                .where()
                .and()
                .eq(PARENT_KEY, shouldApplyParentId ? rootTaxonId : null)
                .eq(TAXONOMY_KEY, taxaId)
                .done()
                .done();

            loadItemsByKeysData.query = query;
        }

        return this.dynamicItemService
            .getItemsByKeys(loadItemsByKeysData);
    }

    getSearchedItems(info: ServiceInfo, loadingData: LoadItemsData, taxonId: string, useSynonyms?: boolean): Observable<LoadItemsResponse> {
        const args: LoadItemsData = {
            entityData: loadingData.entityData,
            action: taxonId ? this.buildGetAvailableParentTaxonsAction(taxonId, info.taxaId, false) : "Default.GetRecentTaxons",
            fallbackProperties: [loadingData.entityData.metadata.defaultFieldName]
        };

        const data = {
            excludedItemIds: info.idsToExclude || [],
            taxonomyId: info.taxaId
        };
        args.payload = data;

        if (info.searchText) {
            args.additionalQueryParams = {
                [QUERY_PARAMS.SEARCH]: info.searchText
            };

            if (useSynonyms) {
                args.additionalQueryParams[QUERY_PARAMS.USE_SYNONYMS] = "true";
            }
        }

        return this.dynamicItemService.getRecent(args);
    }

    private buildGetAvailableParentTaxonsAction(taxonId: string, taxonomyId: string, recent: boolean) {
        // excludeOptions: Self = 1, SelfAndChildren = 2,
        return `${taxonId}/Default.GetAvailableParentTaxons(taxonomyId='${taxonomyId}',recent=${recent},excludeOptions=2)`;
    }

    private getSearchQuery(searchParameter: string, taxaId: string, entityData: EntityData) {
        let query = createQuery()
            .where()
            .and()
            .eq(TAXONOMY_KEY, taxaId);

        if (searchParameter) {
            query = this.contentFilterService.applySearch(searchParameter, entityData, query);
        }

        return query;
    }
}

export const HIERARCHICAL_TAXONOMY_SERVICE: ClassProvider = {
    multi: true,
    provide: HIERARCHICAL_SERVICE_TOKEN,
    useClass: HierarchicalTaxonomyService
};
