import { Component, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { SafeValue } from "@angular/platform-browser";
import { BehaviorSubject, Observable, Subscription } from "rxjs";
import { VideoPlayerComponent } from "../../../../../../fields/media/video/video-player.component";
import { stringConstants } from "../../../../common-constants";
import { QUERY_PARAMS, DEFAULT_STORAGE_PROVIDERS } from "../../../content/constants";
import { SelectorConstants } from "../../../html/selector-constants";
import { ComponentData } from "@progress/sitefinity-component-framework";
import { FieldRegistration } from "../../../shared/fields-builder/services/fields-registry";
import { CanvasService } from "../../../shared/services/canvas.service";
import { HttpODataRequestWrapper } from "../../../shared/services/http-odata-request.wrapper";
import { ENTITY_SET } from "../../../shared/services/metadata/meta-data-constants";
import { MediaEntity, MetadataStore } from "../../../shared/services/metadata/meta-data.store";
import { Button, ClickResult, ConfirmButton, DialogData, ModalWindowService, CancelButton } from "../../../shared/services/modal-window.service";
import { FilePickerComponent } from "../../file-picker.component";
import { EnvironmentService } from "../../../shared/services/environment.service";
import { environmentTypes } from "../../../../environment";
import { FieldBase } from "../../../../../../fields";
import { CompositeFieldSettings } from "../../../shared/services/composite-field.settings";
import { SANITIZER_TYPES, SfSafePipe } from "@progress/sitefinity-component-framework";
import { guid } from "../../../../utils";
import { FileWrapper } from "../../media-handlers/media-handler.provider";
import { first } from "rxjs/operators";
import { ComponentCommunicationService } from "../../../shared/services/component-communication.service";
import { ChangeButtonStateInItemEdit } from "../../../shared/events/component-events";

const VIDEO_THUMBNAIL_OPERATIONS = {
    CAPTURE: "Capture video frame",
    UPLOAD: "Upload custom image"
};

const FORBIDDEN_IMAGE_TYPES = ["svg"];

@Component({
    selector: "sf-video-thumbnail",
    templateUrl: "./video-thumbnail.component.html"
})
export class VideoThumbnailComponent extends FieldBase implements OnInit {
    editOperations = [VIDEO_THUMBNAIL_OPERATIONS.CAPTURE, VIDEO_THUMBNAIL_OPERATIONS.UPLOAD];
    thumbnailUrl = null;
    videoFile: FileWrapper;
    private blobUrl: SafeValue;
    private downloadSubscription: Subscription = null;

    constructor(
        private modalWindowService: ModalWindowService,
        private route: ActivatedRoute,
        private metadataStore: MetadataStore,
        private http: HttpODataRequestWrapper,
        private canvasService: CanvasService,
        private safePipe: SfSafePipe,
        private envService: EnvironmentService,
        private communicationService: ComponentCommunicationService) {
        super();
    }

    ngOnInit() {
        this.thumbnailUrl = this.settings?.dataItem?.data?.ThumbnailUrl;
        this.communicationService.subscribe(ChangeButtonStateInItemEdit, ev => {
            this.blobUrl = undefined;
        });
    }

    writeValue(val: string) {
        super.writeValue({ ThumbnailSource: val });
    }

    onVideoThumbOperationClicked(operationName, event: MouseEvent) {
        event.stopPropagation();
        if (operationName === VIDEO_THUMBNAIL_OPERATIONS.CAPTURE) {
            this.handleFrameCapture();
        } else {
            this.handleFileUpload();
        }
    }

    private handleFrameCapture() {
        // The video file exists only when a video is being replaced by the main field. Otherwise we need to request the
        // binary value from the server
        const videoUrl$ = new BehaviorSubject<SafeValue>(stringConstants.EMPTY_STRING);

        if (this.videoFile) {
            const blobUrl = this.safePipe.transform(URL.createObjectURL(this.videoFile.file), SANITIZER_TYPES.URL);
            videoUrl$.next(blobUrl);
            this.openCaptureDialog(videoUrl$);
        } else {
            const video = this.settings.dataItem;
            const params = {
                [QUERY_PARAMS.PROVIDER]: video.provider,
                [QUERY_PARAMS.CULTURE]: video.culture
            };

            this.openCaptureDialog(videoUrl$);

            if (this.blobUrl) {
                return videoUrl$.next(this.blobUrl);
            }
            const storageProvider = video.data.Parent.BlobStorageProvider;
            if (this.envService.getEnvironment() === environmentTypes.integration && (storageProvider === DEFAULT_STORAGE_PROVIDERS.DATABASE || storageProvider === DEFAULT_STORAGE_PROVIDERS.FILE_SYSTEM)) {
                videoUrl$.next(video.data.Url);
            } else {
                this.downloadSubscription = this.http.get$(`${ENTITY_SET.VIDEOS}(${video.key})/$value`, { responseType: "blob", params })
                    .subscribe(x => {
                        if (!x.isLoading) {
                            const blobUrl = URL.createObjectURL(x.content);
                            this.blobUrl = this.safePipe.transform(blobUrl, SANITIZER_TYPES.URL);

                            videoUrl$.next(this.blobUrl);
                        }
                    });
            }
        }
    }

    private openCaptureDialog(videoUrl$: Observable<SafeValue>) {
        const uniqueIdForFrameCapture = guid();
        const componentData: ComponentData = {
            type: VideoPlayerComponent,
            updatePropertiesOnChange: true,
            removePreviousView: true,
            properties: {
                src: null,
                look: "play-detached sf-centered-box sf-mb-3xl",
                createThumbFromFrameIdentifier: uniqueIdForFrameCapture
            }
        };

        componentData.afterComponentInit = (comp: VideoPlayerComponent) => {
            this.registerSubscription(videoUrl$.pipe(first()).subscribe(url => {
                if (url) {
                    comp.src = url;
                }
            }));
        };

        const buttons: Button[] = [
            new ConfirmButton(SelectorConstants.USE_CURRENTLY_DISPLAYED_FRAME, () => {
                const videoElement = document.querySelector(`sf-modal-window video.__sf-video-thumb-${uniqueIdForFrameCapture}`) as HTMLVideoElement;
                if (!videoElement || !videoElement.currentSrc) {
                    return new ClickResult(null, false, true);
                }

                this.thumbnailUrl = this.canvasService.renderElement(videoElement, videoElement.clientWidth, videoElement.clientHeight);
                this.writeValue(this.thumbnailUrl);

                return new ClickResult(true, true);
            }),
            new CancelButton(SelectorConstants.CANCEL, () => {
                if (this.downloadSubscription) {
                    this.downloadSubscription.unsubscribe();
                }
                return new ClickResult(false, true);
            })
        ];

        const dialogData = new DialogData(componentData, null, buttons);
        dialogData.heading = {
            title: "Capture video frame"
        };

        this.modalWindowService.setMapping(dialogData, "video_thumbnail");
        this.modalWindowService.show("video_thumbnail", this.route.parent);
    }

    private handleFileUpload() {
        const entity = this.metadataStore.getEntity(ENTITY_SET.IMAGES).clone() as MediaEntity;
        this.filterValidImageTypes(entity);

        const dataItem = this.settings.dataItem;
        const componentData: ComponentData = {
            type: FilePickerComponent,
            properties: {
                multiple: false,
                value: [],
                name: "this.settings.name",
                allowCreate: true,
                mediaEntityData: { metadata: entity, provider: dataItem.provider, culture: dataItem.culture },
                initialViewMode: null,
                createMedia: true,
                getImageAfterUpload: true,
                selectedLibrary: null
            }
        };
        const dialogData = new DialogData(componentData, (res) => {
            if (res?.data) {
                // Handle select from existing or file upload
                const image = res.data.data || res.data;

                this.thumbnailUrl = image.Url;
                this.writeValue(image.Id);
            }
        }, [], "-prompt");

        this.modalWindowService.setMapping(dialogData, "video_thumbnail");
        this.modalWindowService.show("video_thumbnail", this.route.parent);
    }

    private filterValidImageTypes(entity: MediaEntity) {
        FORBIDDEN_IMAGE_TYPES.forEach(t => {
            entity.acceptableMediaTypes = entity.acceptableMediaTypes.filter(x => !x.includes(t));
            entity.acceptableFileTypes = entity.acceptableFileTypes.filter(x => !x.includes(t));
        });
    }
}

export const VIDEO_THUMBNAIL_REGISTRY: FieldRegistration = {
    writeComponent: VideoThumbnailComponent,
    readComponent: VideoThumbnailComponent,
    settingsType: CompositeFieldSettings
};
