import { Injectable } from "@angular/core";
import { ChoiceItem, stringConstants } from "@progress/sitefinity-component-framework";
import { DataItem } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { FormFieldWrapperComponent } from "../../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../../shared/fields-builder/services/field-change/field-change.service";
import { FORMS_DESCRIPTION_FULL_NAME } from "../../shared/services/metadata/meta-data-constants";
import { ParameterizedChoiceSelectorComponent } from "../../widget-editor/providers/fields/parameterized-choice-selector/parameterized-choice-selector.component";
import { ParameterizedChoiceSelectorSettings } from "../../widget-editor/providers/fields/parameterized-choice-selector/parameterized-choice-selector.settings";
import { FormConnectorProperties, Properties } from "../../shared/fields.constants";
import { FORM_REDIRECT_PAGE_PROPERTIES, SUBMIT_ACTION } from "../components/form-redirect-page/form-redirect-page.composite.component";
import { FORM_NOTIFICATIONS_PROPERTIES } from "../forms-tweaks-handler.service";

@Injectable()
export default class FormsFieldsChangeService  implements FieldChangeService {

    constructor(private dynamicItemService: DynamicItemService) {
    }

    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === FORM_REDIRECT_PAGE_PROPERTIES.SUBMIT_ACTION) {
            const hideSuccessMessageField: boolean = !!(changedValue && changedValue.SubmitAction !== SUBMIT_ACTION.VIEW_MESSAGE);
            const successMessageField = fields.find(f => f.fieldModel.key === Properties.SUCCESS_MESSAGE);
            if (successMessageField) {
                successMessageField.hidden = hideSuccessMessageField;
            }

            const redirectPageField = fields.find(f => f.fieldModel.key === FORM_REDIRECT_PAGE_PROPERTIES.REDIRECT_PAGE);
            if (redirectPageField) {
                redirectPageField.hidden = !hideSuccessMessageField;
            }
        }

        if (changedFieldName === FORM_NOTIFICATIONS_PROPERTIES.SEND_CONFIRMATION_EMAIL) {
            const confirmationEmailTemplate = fields.find(f => f.fieldModel.key === FORM_NOTIFICATIONS_PROPERTIES.CONFIRMATION_EMAIL_TEMPLATE);
            if (confirmationEmailTemplate) {
                confirmationEmailTemplate.hidden = !changedValue;
            }
        }

        if (changedFieldName === FORM_NOTIFICATIONS_PROPERTIES.SEND_EMAIL_NOTIFICATIONS) {
            const subscribedEmailsField = fields.find(f => f.fieldModel.key === FORM_NOTIFICATIONS_PROPERTIES.SUBSCRIBED_EMAILS);
            if (subscribedEmailsField) {
                subscribedEmailsField.hidden = !changedValue;
            }

            const emailNotificationTEmplate = fields.find(f => f.fieldModel.key === FORM_NOTIFICATIONS_PROPERTIES.EMAIL_NOTIFICATION_TEMPLATE);
            if (emailNotificationTEmplate) {
                emailNotificationTEmplate.hidden = !changedValue;
            }
        }

        const sourceField = fields.find(f => f.fieldModel.key === changedFieldName);
        if (sourceField) {
            const settings = sourceField.currentInstance.settings as ParameterizedChoiceSelectorSettings;
            if (settings && settings.targetFieldName) {
                const selectionEnabled = changedValue !== null;
                this.processSelectedFormFieldChange(changedValue, fields, settings.targetFieldName, selectionEnabled);
            }
        }

        if (changedFieldName === FormConnectorProperties.SITEFINITY_INSIGHT_SEND_FORMS_DATA) {
            this.processSelectedChoiceFieldChange(changedValue, fields, FormConnectorProperties.SITEFINITY_INSIGHT_DATA_MAPPING);
        }
    }

    canProcess(typeFullName: string): boolean {
        return typeFullName === FORMS_DESCRIPTION_FULL_NAME;
    }

    private processSelectedChoiceFieldChange(changedValue: any, fields: FormFieldWrapperComponent[], propertyName: string) {
        const dataMappingField = fields.find(f => f.fieldModel.key === propertyName);
        if (dataMappingField) {
            dataMappingField?.currentInstance?.editableTableComponent?.wrapperComponents.forEach(wc => {
                if (wc.currentInstance instanceof ParameterizedChoiceSelectorComponent) {
                    const selector = wc.currentInstance as ParameterizedChoiceSelectorComponent;
                    selector.settings.selectionEnabled = changedValue;
                    selector.reloadComponent();
                }
            });
        }
    }

    private processSelectedFormFieldChange(changedValue: any, fields: FormFieldWrapperComponent[], propertyName: string, selectionEnabled: boolean) {
        const dataMappingField = fields.find(f => f.fieldModel.key === propertyName);
        if (dataMappingField) {
            if (changedValue) {
                this.dynamicItemService
                    .executeBoundFunction(DataItem.emptyItem(dataMappingField.fieldModel.settings.dataItem), `Default.GetChoiceOptions(fieldName=@fieldName,extenderName=@extenderName)?@fieldName='${changedValue}'&@extenderName='${propertyName.replace("DataMapping", stringConstants.EMPTY_STRING)}'`)
                    .subscribe((choices: any) => {
                        if (choices && choices.value) {
                            this.setupSelectorComponent(dataMappingField?.currentInstance?.editableTableComponent?.wrapperComponents, choices.value, selectionEnabled);
                        }
                    });
            } else {
                this.setupSelectorComponent(dataMappingField?.currentInstance?.editableTableComponent?.wrapperComponents, [], selectionEnabled);
            }
        }
    }

    private setupSelectorComponent(wrapperComponents: FormFieldWrapperComponent[], choices: ChoiceItem[], selectionEnabled: boolean) {
        wrapperComponents.forEach(wc => {
            if (wc.currentInstance instanceof ParameterizedChoiceSelectorComponent) {
                const selector = wc.currentInstance as ParameterizedChoiceSelectorComponent;
                const choiceIndex = choices.findIndex(current => {
                    return wc.currentInstance.value === current.Name;
                });

                if (choiceIndex === -1 || choices.length === 0) {
                    selector.writeValue(null);
                }

                selector.settings.selectionEnabled = selectionEnabled;
                selector.reloadComponent(choices);
            }
        });
    }
}

export const FORMS_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: FormsFieldsChangeService,
    multi: true
};
