import { Injectable } from "@angular/core";

import { FieldChangeService, FIELDS_CHANGE_SERVICE_TOKEN } from "../shared/fields-builder/services/field-change/field-change.service";
import { FormFieldWrapperComponent } from "../shared/fields-builder/components/field-wrapper/form-field-wrapper.component";
import { MEDIA_DATA_FIELD_NAME, IMAGE_ITEM_FULL_NAME, VIDEO_ITEM_FULL_NAME } from "../shared/services/metadata/meta-data-constants";
import { StructureUrlNameComponent } from "../shared/components/urlNameStructure/structure-urlName.component";
import { Properties } from "../shared/fields.constants";
import { MediaHelpers } from "./services/media.helpers";

@Injectable()
export class MediaFieldsChangeService implements FieldChangeService {
    processChange(changedFieldName: string, changedValue: any, fields: FormFieldWrapperComponent[]): void {
        if (changedFieldName === MEDIA_DATA_FIELD_NAME) {
            this.processMediaDataFieldName(changedValue, fields);
        }

        if (changedFieldName === Properties.PARENT_ID) {
            this.processParentIdFieldChange(fields);
        }
    }

    canProcess(typeFullName: string): boolean {
        return MediaHelpers.isLibraryType(typeFullName) || typeFullName === IMAGE_ITEM_FULL_NAME || typeFullName === VIDEO_ITEM_FULL_NAME;
    }

    private processParentIdFieldChange(fields: FormFieldWrapperComponent[]) {
        const fieldWrapper = fields.find(x => x.fieldModel.key === Properties.TITLE);

        if (!fieldWrapper) {
            return;
        }

        fieldWrapper.formControl.updateValueAndValidity();
    }

    // TODO: this whole thing might be obsolete
    private processMediaDataFieldName(changedValue: any, fields: FormFieldWrapperComponent[]) {
        const videoThumbnailField = fields.find(x => x.fieldModel.key === Properties.THUMBNAIL_URL);
        if (videoThumbnailField) {
            videoThumbnailField.currentInstance.videoFile = changedValue;
            return;
        }

        const fieldWrapper = fields.find(x => x.fieldModel.key === Properties.MEDIA_FILE_URL_NAME);
        if (!fieldWrapper || fieldWrapper.hasValue) {
            return;
        }

        if (changedValue) {
            const fileName: string = changedValue.name;
            const extensionStartIndex = fileName.lastIndexOf(".");
            const value = fileName.substr(0, extensionStartIndex);
            const extension = fileName.substr(extensionStartIndex);
            const component = fieldWrapper.currentInstance as StructureUrlNameComponent;

            component.writeValue(value);
            component.extension = extension;
        }
    }
}

export const MEDIA_FIELD_CHANGE_HANDLER = {
    provide: FIELDS_CHANGE_SERVICE_TOKEN,
    useClass: MediaFieldsChangeService,
    multi: true
};
