import { Injectable } from "@angular/core";
import { BehaviorSubject } from "rxjs";

import { BackendTweaksService } from "./backend-tweaks.service";
import { VIEW_NAME } from "../../../constants";
import { MarkupConfig } from "@progress/sitefinity-component-framework";

@Injectable()
export class BackendTweaksStore {
    private gridSubjects: { [typeName: string]: BehaviorSubject<any[]> } = {};
    private gridSortSubject: { [typeName: string]: BehaviorSubject<string> } = {};
    private formSubjects: { [typeName: string]: BehaviorSubject<any[]> } = {};

    private initializedGrids: { [typeName: string]: boolean } = {};
    private initializedForms: { [typeName: string]: boolean } = {};

    constructor(private backendTweaksService: BackendTweaksService) { }

    getGridByType(typeName: string): GridData[] {
        return this.getBehaviorSubject<GridData>(this.gridSubjects, typeName).getValue();
    }

    getGridSortExpression(typeName: string): string {
        return this.getBehaviorSubject<string>(this.gridSortSubject, typeName).getValue()[0];
    }

    getFormByType(typeName: string, viewName: string): FormData[] {
        const key = `${typeName}-${viewName}`;
        return this.getBehaviorSubject<FormData>(this.formSubjects, key).getValue();
    }

    initializeGrid(typeName: string): Promise<boolean> | boolean {
        if (this.initializedGrids[typeName]) {
            return true;
        }

        this.initializedGrids[typeName] = true;

        return this.backendTweaksService.getGridTweaks(typeName)
            .then(data => {
                this.getBehaviorSubject<GridData>(this.gridSubjects, typeName).next(this.loadGridData(data));

                if (data.sortExpression) {
                    this.getBehaviorSubject<string>(this.gridSortSubject, typeName).next([data.sortExpression]);
                }

                return true;
            }, error => {
                return false;
            });
    }

    initializeForm(typeName: string, viewName: string, itemId: string, itemProvider: string, itemCulture: string): Promise<boolean> {
        const key = `${typeName}-${viewName}`;
        if (this.initializedForms[key]) {
            return Promise.resolve(true);
        }

        return this.backendTweaksService.getFormTweaks(typeName, viewName || VIEW_NAME.EDIT, itemId, itemProvider, itemCulture)
            .then(data => {
                this.getBehaviorSubject(this.formSubjects, key).next(data);

                return true;
            }, error => {
                return false;
            });
    }

    private getBehaviorSubject<T>(subjects: any, key: string): BehaviorSubject<T[]> {
        let behaviorSubject = subjects[key];
        if (!behaviorSubject) {
            behaviorSubject = subjects[key] = new BehaviorSubject([]);
        }
        return behaviorSubject;
    }

    private loadGridData(data: any): GridData[] {
        return (data.value || []).map((item: any) => (Object.freeze({
            name: item.Name,
            title: item.Title,
            visible: item.ShowInGrid,
            ordinal: item.ColumnOrdinal,
            boundPropertyName: item.BoundPropertyName,
            fieldMeta: item.FieldMetadata,
            isGrouping: item.IsGrouping
        })));
    }
}

export interface GridData {
    name: string;
    title: string;
    visible: boolean;
    ordinal?: number;
    boundPropertyName?: string;
    fieldMeta?: any;
    isGrouping?: boolean;
}

export interface FormData {
    id: string;
    isExpandedByDefault: boolean;
    isSection: boolean;
    name: string;
    title: string;
    renderChoicesAs: string;
    isHtml: boolean;
    maximumAllowedSize: number;
    allowedFileExtensions: string[];
    acceptableMediaTypes: string[];
    readonly: boolean;
    hidden: boolean;
    allowCreate: boolean;
    allowAdd: boolean;
    allowView: boolean;
    allowRemove: boolean;
    status: string;
    statusMessage: string;
    predefinedValue: string;
    metadata: any;
    tooltipModels: MarkupConfig;
}
