import { BulkCommandExtenderBase } from "../../content/dynamic-modules/services/operations/commands/bulk-command-extender-base";
import { EntityData, DataItem } from "../../content/dynamic-modules/interfaces";
import { ENTITY_SET } from "../../shared/services/metadata/meta-data-constants";
import { ActionButton } from "../../shared/components/action-menu/action-menu-model";
import { Command } from "../../shared/commands/command";
import { OPERATION_NAMES } from "../../shared/components/action-menu/operation.model";
import { BulkEditTaxonCommand } from "../../content/dynamic-modules/services/operations/commands/bulk-edit-taxon.command";
import { DynamicItemStore } from "../../content/dynamic-modules/services/dynamic-item.store";
import { ModalWindowService } from "../../shared/services/modal-window.service";
import { BulkItemSelectionInfo } from "../../content/dynamic-modules/components/bulk-operations/bulk-operations.component";
import { ClassProvider, Injectable } from "@angular/core";
import { BULK_COMMAND_EXTENDER_TOKEN } from "../../content/dynamic-modules/services/operations/commands/composite-bulk-command-extender";

@Injectable()
export class TaxonomyBulkCommandExtender extends BulkCommandExtenderBase {
    constructor(private modalService: ModalWindowService,
                private dynamicItemStore: DynamicItemStore) {
        super();
    }

    isSupportedType(entityData: EntityData): boolean {
        return entityData.metadata.setName === ENTITY_SET.CLASSIFICATIONS ||
            entityData.metadata.setName === ENTITY_SET.FLAT_TAXA ||
            entityData.metadata.setName === ENTITY_SET.HIERARCHY_TAXA;
    }

    tryHandleCommand(action: ActionButton, data: { dataItems: DataItem[], entityData: EntityData, bulkItemSelectionInfo: BulkItemSelectionInfo }): Command {
        if (action.name === OPERATION_NAMES.bulkEditProperties) {
            const commandToExecute = new BulkEditTaxonCommand(this.modalService, this.dynamicItemStore);
            (commandToExecute as BulkEditTaxonCommand).itemSelectionInfo = data.bulkItemSelectionInfo;

            return commandToExecute;
        }

        return null;
    }
}

export const TAXONOMY_BULK_COMMAND_EXTENDER: ClassProvider = {
    multi: true,
    provide: BULK_COMMAND_EXTENDER_TOKEN,
    useClass: TaxonomyBulkCommandExtender
};
