import { Component, OnInit } from "@angular/core";
import { DynamicItemStore } from "../../../content/dynamic-modules/services/dynamic-item.store";
import { ActivatedRoute, Router } from "../../../../../../node_modules/@angular/router";

@Component({
    template: `<sf-loader-wrapper [isLoading]="true" look="progressbar overlay"></sf-loader-wrapper>`
})
export class UnlockRedirectComponent implements OnInit {
    constructor(private dynamicItemStore: DynamicItemStore, private route: ActivatedRoute, private router: Router) {
    }

    ngOnInit(): void {
        this.route.data.subscribe(data => {
            this.handleRedirect(data.itemData.item);
        });
    }

    private handleRedirect(item) {
        this.dynamicItemStore.unlockItem(item).subscribe(x => {
            this.router.navigate(["../edit"], {relativeTo: this.route, queryParamsHandling: "preserve" });
        });
    }
}
