import { ComponentData } from "@progress/sitefinity-component-framework";
import { first } from "rxjs/operators";
import { BehaviorSubject, Observable, ReplaySubject, Subject } from "rxjs";
import { TreeConfig } from "../../../../../fields";
import { DataItem, OperationResult } from "../../content/dynamic-modules/interfaces";
import { DynamicItemService } from "../../content/dynamic-modules/services/dynamic-item.service";
import { ModalListComponent } from "../components/modal-list/modal-list.component";
import { Button, CancelButton, ClickData, ClickResult, ConfirmButton, DialogData, ModalComponentSettings, ModalWindowService } from "../services/modal-window.service";
import { Command } from "./command";
import { ExecutionContext } from "./execution-context";
import { OPERATION_NAMES } from "../components/action-menu/operation.model";

export abstract class ShareWithCommand implements Command {
    protected abstract get shareWithError(): string;

    private entityData: DataItem;
    private operationResult: OperationResult;

    constructor(private dynamicItemService: DynamicItemService, private modalService: ModalWindowService) { }

    execute(context: ExecutionContext): Observable<any> {
        const route = context.currentRoute;
        this.entityData = context.data.entityData;

        const treeConfig: TreeConfig = {
            status: false,
            showBreadcrumb: false,
            noSelection: false,
            multiSelection: true,
            clickable: true,
            previewUrl: false,
            treeProperties: {
                displayField: "Name",
                idField: "Id"
            }
        };

        const count = new BehaviorSubject<number>(2);
        const componentData: ComponentData = {
            type: ModalListComponent,
            properties: {
                contentLook: "medium",
                action: "Default.GetSharedInSites()",
                actionTitle: `Share ${this.entityData.metadata.singularName.toLocaleLowerCase()} with sites`,
                dataItem: this.entityData,
                showCounter: false,
                isSearchVisible: true,
                count,
                showDataItemTitle: false,
                template: null,
                listLook: "actions-on-hover",
                tabsConfig: [{
                    title: null,
                    treeConfig,
                    noItemsLabel: `Sites using this ${this.entityData.metadata.singularName.toLocaleLowerCase()} will appear here`,
                    itemsFilter: x => x,
                    itemsModifier: x => {
                        x.isTranslated = true;
                    },
                    selectedFilter: x => x.IsShared
                }]
            }
        };

        const handled = new Subject();

        const dialogData = new DialogData(componentData, (closingContext: ClosingContext) => {
            const successful = closingContext?.data && (closingContext.data as ClickResult).data;
            if (successful) {
                if (this.isShareWithError(this.operationResult)) {
                    const settings = this.generateShareWithErrorSettings(this.operationResult.title, this.operationResult.message);
                    this.modalService.openModalConfirmation(route, settings, closingContext.component.dataItem);
                }
                handled.next({ success: true });
            } else {
                handled.next({ success: false });
            }
        }, this.getButtons(), null, "-bottom");

        this.modalService.setMapping(dialogData, "sharedIn");
        this.modalService.show("sharedIn", route.parent);

        return handled.pipe(first());
    }

    private confirmCallback(data: ClickData): Observable<ClickResult> {
        const tree = (data.component as ModalListComponent).tree;
        const clickResult = new ReplaySubject<ClickResult>(1);
        clickResult.next(new ClickResult(true, false));

        if (tree) {
            const selectedItems = tree.getSelectedNodeIds();
            this.dynamicItemService.executeEntityOperationForDataItemKey(this.entityData.data.Id, this.entityData, `Default.ChangeSharedInSites()`, {
                siteIds: selectedItems
            }).subscribe((result) => {
                if (!result.Success) {
                    this.operationResult = {
                        success: result.Success,
                        title: result.Title,
                        message: result.Message,
                        availableActions: result.AvailableActions
                    };
                }

                clickResult.next(new ClickResult(true, true, false, false));
            });
        } else {
            clickResult.next(new ClickResult(true, true, false, false));
        }

        return clickResult;
    }

    private generateShareWithErrorSettings(title: string, message: string): ModalComponentSettings {
        const shareWithErrorSettings: ModalComponentSettings = {
            title: title,
            action: OPERATION_NAMES.save,
            icon: "share-alt",
            descriptionAllowHtml: true,
            description: message,
            buttons: new Array<Button>(new CancelButton("Close"))
        };

        return shareWithErrorSettings;
    }

    private getButtons() {
        return [
            new ConfirmButton("Save changes", this.confirmCallback.bind(this)),
            new CancelButton()
        ];
    }

    private isShareWithError(operationResult: OperationResult): boolean {
        return operationResult && operationResult.availableActions && operationResult.availableActions.indexOf(this.shareWithError) >= 0;
    }
}
