import { ExecutionContext } from "./execution-context";
import { Observable } from "rxjs";

/**
 * @ExposedInApi {Command} Command v1/commands/command.d.ts
 */
export interface Command {
    execute(context: ExecutionContext): Observable<any>;
}

/**
 * This interface is used to mark commands that should be executed only once in
 * bulk operation, not multiple times for every item.
 */
/**
 * @ExposedInApi {ExecuteOnceInBulkCommand} ExecuteOnceInBulkCommand v1/commands/command.d.ts
 */
export interface ExecuteOnceInBulkCommand extends Command {
    executeOnceInBulk: boolean;
}

export function instanceOfExecuteOnceInBulkCommand(object: any): object is ExecuteOnceInBulkCommand {
    return "executeOnceInBulk" in object;
}
