import { Injectable, Inject, Optional } from "@angular/core";

import { FieldsRegistrationProvider, FieldRegistryKey, FIELDS_PROVIDER_TOKEN, FieldsProvider, DefaultFieldsProvider } from "./fields-registration-provider";
import { FieldRegistration, FieldTypes } from "../services/fields-registry";

// Redefined here insted of using HTML_CONSTANTS because of circular references.
export const IS_HTML_PROPERTY: string = "Telerik.Sitefinity.V1.IsHtml";

/**
 * Stores and provides the default configuration of the fields.
 *
 * @export
 * @class FieldsProvider
 * @implements {FieldsRegistrationProvider}
 */
@Injectable()
export class CompositeFieldsProvider implements FieldsRegistrationProvider {
    private defaultMappings: Map<string, FieldRegistration>;

    constructor(@Optional() @Inject(FIELDS_PROVIDER_TOKEN) private providers: FieldsProvider[]) {
        // we want to sort the providers so that the ones coming from extension will be executed first
        // otherwise the default ones will provide the field registration before the customs had the chance to execute
        this.providers = this.providers
            .sort((x, y) => {
                if (x instanceof DefaultFieldsProvider) {
                    return 1;
                }

                if (y instanceof DefaultFieldsProvider) {
                    return -1;
                }

                return 0;
            });

        this.defaultMappings = new Map<string, FieldRegistration>();
    }

    /**
     * By given key, will return field registration that contains
     * read-only component, write component and settings type.
     *
     * @param {FieldRegistryKey} fieldRegistryKey
     * @returns {FieldRegistration}
     * @memberof FieldsProvider
     */
    getFieldRegistration(fieldRegistryKey: FieldRegistryKey, propertyMetadata: any): FieldRegistration {
        // for backward compatability with existing calls
        if (propertyMetadata && propertyMetadata.hasOwnProperty("properties")) {
            propertyMetadata = propertyMetadata.properties[fieldRegistryKey.fieldName];
        }

        if (this.providers != null) {
            for (let i = 0; i < this.providers.length; i++) {
                const provider = this.providers[i];
                const field = provider.overrideField(fieldRegistryKey);
                if (field != null)
                    return field;

            }
        }

        if (this.isLongTextField(fieldRegistryKey.fieldType)) {
            const longTextField = this.getLongTextField(fieldRegistryKey.fieldName, propertyMetadata);
            return longTextField;
        }

        const registration: FieldRegistration = this.defaultMappings.get(fieldRegistryKey.fieldType);
        return registration || null;
    }

    /**
     * Registers the default field configurations, that will be used to construct
     * the fields.
     *
     * @param {Map<string, FieldRegistration>} defaultRegistries
     * @memberof FieldsProvider
     */
    setDefaults(defaultRegistries: Map<string, FieldRegistration>): void {
        defaultRegistries.forEach((registration: FieldRegistration, key: string) => {
            this.defaultMappings.set(key, registration);
        });
    }

    /**
     * Determines what registration to return, based on the IsHtml property.
     * If the the type of the item is "Static", it will return HTML registration
     * because it is the default for "Static" types, otherwise it will return
     * HTML registration for DynamicTypes with IsHtml=true and TextArea registration
     * for DynamicTypes with IsHtml=false.
     * @param fieldName The name of the field used to find the properties from the entity.
     * @param entity Provides properties and other metadata for the field.
     */
    private getLongTextField(fieldName: string, propMeta: any): FieldRegistration {
        const isHtml: boolean = propMeta[IS_HTML_PROPERTY];
        const registration: FieldRegistration = isHtml ? this.defaultMappings.get(FieldTypes.html) : this.defaultMappings.get(FieldTypes.textArea);

        return registration;
    }

    private isLongTextField(fieldType: string): boolean {
        const isLongTextField = fieldType === FieldTypes.textArea || fieldType === FieldTypes.html;
        return isLongTextField;
    }
}
