import { Component, Input, OnInit } from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import { DataContext, DataContextComponent } from "../../../../shared/models/data-context-component";
import { ContentCultureData } from "../../../../shared/services/metadata/site-data.store";
import { COMMAND_NAMES } from "../commands";
import { DataItem } from "../../interfaces";
import { stringConstants } from "../../../../../common-constants";
import { AppStore } from "../../../../../services/store/app-store";
import { COLUMN_SELECTORS } from "../../../../../services/store/selectors/selectors.columns";
import { SfRxBase } from "@progress/sitefinity-component-framework";
import { COLUMN_ACTIONS } from "../../../../../services/store/actions/actions.columns";
import { COLUMN_NAMES } from "../columns-provider";

export const TRANSLATIONS_COLUMN_BADGES_COUNT: number = 6;
const DEFAULT_LOOK: string = "size-xl sf-txt-small hover sf-txt-upper-case sf-mb-3xs sf-mr-6xs";
const READONLY_LOOK: string = "size-xl sf-txt-small sf-txt-upper-case sf-mb-3xs sf-mr-6xs";
const ADD_LOOK: string = DEFAULT_LOOK + " add-variation";
const EDIT_LOOK: string = DEFAULT_LOOK + " edit-variation";
const EDIT_READONLY_LOOK: string = READONLY_LOOK + " edit-variation";
const INACTIVE_LOOK: string = "dimmed";
const LOAD_MORE_LOOK: string = DEFAULT_LOOK + " add";
const MESSAGES = { add: "Add ", edit: "Edit " };
const MORE_TRANSLATIONS_TITLE = "More translations";
const LESS_TRANSLATIONS_TITLE = "Less translations";

/**
 * Component used to display item translations in the grid cell
 */
@Component({
    selector: "sf-list-languages",
    templateUrl: "./list-languages.component.html"
})
export class ListLanguagesComponent extends SfRxBase implements OnInit, DataContextComponent {
    /**
     * The item data for the current row
     */
    @Input() public context: DataContext;

    @Input() public readonly: boolean = false;

    messages = MESSAGES;
    badges: Array<BadgeData>;

    /**
     * Initializes a new instance of the {@link ListLanguagesComponent} class
     * @param route The current activated route
     */
    constructor(protected route: ActivatedRoute, private appStore: AppStore) {
        super();
    }

    public ngOnInit(): void {
        const dataItemAvailableLanguages: Array<string> = this.context.dataItem.data.AvailableLanguages ||
            (this.context.dataItem.data.Language ? [this.context.dataItem.data.Language] : undefined);

        // This is needed by mixed grids like the media one where you have folder(which don't have languages) and media items which have.
        if (!dataItemAvailableLanguages) {
            return;
        }

        if (this.readonly) {
            this.badges = this.generateReadonlyLanguageButtons(dataItemAvailableLanguages);
        } else {
            const siteLanguages: Array<ContentCultureData> = this.route.snapshot.data.siteDataStore.ContentCultures;
            this.badges = this.generateLanguageButtons(dataItemAvailableLanguages, siteLanguages);

            this.registerSubscription(this.appStore.pipe(COLUMN_SELECTORS.expandedColumnsPerEntity).subscribe(x => {
                this.handleExpandedColumnsPerEntity(x);
            }));

            this.registerSubscription(this.appStore.pipe(COLUMN_SELECTORS.expandedColumnsPerItem).subscribe(x => {
                this.handleExpandedColumnsPerItem(x);
            }));
        }
    }

    private handleExpandedColumnsPerEntity(data: { [key: string]: string[] }) {
        if (data && data[this.context.dataItem.metadata.setName]) {
            const expanded = data[this.context.dataItem.metadata.setName].indexOf(COLUMN_NAMES.TRANSLATIONS) > -1;
            this.toggleExpandedOrCollapsed(expanded);
        }
    }

    private handleExpandedColumnsPerItem(data: { [key: string]: { [key: string]: { [key: string]: boolean } } }) {
        if (data && data[this.context.dataItem.metadata.setName] && data[this.context.dataItem.metadata.setName][COLUMN_NAMES.TRANSLATIONS]) {
            const expanded = data[this.context.dataItem.metadata.setName][COLUMN_NAMES.TRANSLATIONS][this.context.dataItem.data.Id];
            if (expanded != null)
                this.toggleExpandedOrCollapsed(expanded);
        }
    }

    private toggleExpandedOrCollapsed(isCollapsed: boolean) {
        if (!this.context.isVirtualized && this.badges) {
            if (isCollapsed) {
                const moreTranslationsBadge = this.badges.find(x => x.title === MORE_TRANSLATIONS_TITLE);
                this.expandLanguages(moreTranslationsBadge);
            } else {
                const lessTranslationsBadge = this.badges.find(x => x.title === LESS_TRANSLATIONS_TITLE);
                this.collapseLanguages(lessTranslationsBadge);
            }
        }
    }

    /**
     * Handles the click event on a translation.
     * @param item The translation item that was clicked.
     */
    public onClick(item: BadgeData): void {
        if (this.readonly)
            return;

        if (item.title === LESS_TRANSLATIONS_TITLE || item.title === MORE_TRANSLATIONS_TITLE) {
            this.appStore.dispatch(COLUMN_ACTIONS.toggleExpandedPerItem({
                entitySet: this.context.dataItem.metadata.setName,
                itemId: this.context.dataItem.data.Id,
                columnName: COLUMN_NAMES.TRANSLATIONS,
                expanded: item.title === MORE_TRANSLATIONS_TITLE
            }));
        } else {
            this.callInvoker(item);
        }
    }

    private expandLanguages(item: BadgeData): void {
        // show all translations
        this.badges.forEach((badge) => {
            badge.isVisible = true;
        });

        // hide showMoreButton
        item.isVisible = false;

        const lessTranslationsBadge = this.badges.find(x => x.title === LESS_TRANSLATIONS_TITLE);
        lessTranslationsBadge.isVisible = true;
    }

    private collapseLanguages(lessTranslationsBadge: BadgeData): void {
        for (let i = 0; i < this.badges.length; i++) {
            if (i >= TRANSLATIONS_COLUMN_BADGES_COUNT - 1) {
                this.badges[i].isVisible = false;
            }
        }

        const moreTranslationsBadge = this.badges.find(x => x.title === MORE_TRANSLATIONS_TITLE);
        moreTranslationsBadge.isVisible = true;

        lessTranslationsBadge.isVisible = false;
    }

    private callInvoker(item: BadgeData) {
        const invoker = this.context.invoker;
        invoker.invoke({
            name: COMMAND_NAMES.changeCulture,
            data: {
                culture: item.name,
                dataItem: this.context.dataItem
            }
        });
    }

    private generateLanguageButtons(dataItemAvailableLanguages: Array<string>, siteLanguages: Array<ContentCultureData>): Array<BadgeData> {
        const badges: Array<BadgeData> = [];

        siteLanguages.forEach((language, i) => {
            const isAvailable: boolean = dataItemAvailableLanguages.some(e => e === language.Name);
            let look: string = isAvailable ? EDIT_LOOK : ADD_LOOK;
            if (this.context.dataItem.data.inactive) {
                look += " " + INACTIVE_LOOK;
            }
            const ariaLabel: string = (isAvailable ? MESSAGES.edit : MESSAGES.add) + language.DisplayName.toLowerCase() + " version";
            const languageItem: BadgeData = { name: language.Name, isAvailable: isAvailable, isVisible: true, isLanguage: true, look: look, title: language.DisplayName, ariaLabel: ariaLabel };

            // hide all buttons after first row
            if (!this.context.isVirtualized && i > TRANSLATIONS_COLUMN_BADGES_COUNT - 1) {
                languageItem.isVisible = false;
            }

            badges.push(languageItem);
        });

        if (!this.context.isVirtualized && siteLanguages.length > TRANSLATIONS_COLUMN_BADGES_COUNT) {
            // Remove last visible button
            badges[TRANSLATIONS_COLUMN_BADGES_COUNT - 1].isVisible = false;

            // Add show more button
            const loadMoreCount = (siteLanguages.length - TRANSLATIONS_COLUMN_BADGES_COUNT) + 1;
            const loadMoreButtonName: string = `+${loadMoreCount}`;
            badges.push({ name: loadMoreButtonName, isAvailable: false, isVisible: true, isLanguage: false, look: LOAD_MORE_LOOK, title: MORE_TRANSLATIONS_TITLE });

            // Add collapse button
            badges.push({ name: stringConstants.EMPTY_STRING, title: LESS_TRANSLATIONS_TITLE, isAvailable: false, isVisible: false, isLanguage: false, look: LOAD_MORE_LOOK, iconName: "angle-left" });
        }

        return badges;
    }

    private generateReadonlyLanguageButtons(dataItemAvailableLanguages: string[]): Array<BadgeData> {
        const badges: Array<BadgeData> = [];

        dataItemAvailableLanguages.forEach(language => {
            const ariaLabel: string = MESSAGES.edit + language.toLowerCase() + " version";
            const languageItem: BadgeData = { name: language, isAvailable: true, isVisible: true, isLanguage: false, look: EDIT_READONLY_LOOK, title: language, ariaLabel: ariaLabel };
            badges.push(languageItem);
        });

        return badges;
    }
}

export interface CultureChangeCommand {
    culture: string;
    dataItem: DataItem;
}

interface BadgeData {
    name: string;
    title: string;
    isAvailable: boolean;
    isVisible: boolean;
    isLanguage: boolean;
    look: string;
    ariaLabel?: string;
    iconName?: string;
}
