import { startWith, map } from "rxjs/operators";
import { LoadingState } from "./delayEmission";
import { Observable } from "rxjs";

export interface LoadingContentState<T> extends LoadingState {
    content: T;
}

/**
 * Wraps the emitted value in LoadingContentState object and emits an initial LoadingContentState object before the source emits
 * any values. The initial emitted value has its isLoading property set to true, and content property set to whichever value is passed to this
 * method.
 * @param source The source observable to which the method is applied
 * @param initialContent The initial content that will be sent along with the first emitted value.
 */
export const toLoadingState = <T>(initialContent: T = null) => (source: Observable<T>) =>
    source.pipe(
        map(content => ({ isLoading: false, content })),
        startWith(<LoadingContentState<T>>{
            isLoading: true,
            content: initialContent
        })
    );
