import { of as observableOf, Observable } from "rxjs";
import { catchError, mergeMap } from "rxjs/operators";
import { ClassProvider, Injectable } from "@angular/core";
import { ConnectorService } from "./connector.service";
import { ExtensionPointUtilsService } from "./extension-point-utils.service";
import { OPERATIONS_TOKEN } from "../../../content/dynamic-modules/services/operations/operations-provider";
import {
    OperationsData,
    OperationsProvider,
    OperationsTarget
} from "../../../content/dynamic-modules/services/operations/interfaces";
import { CommandModelBase } from "../../commands/command-model-base";
import { Operation, OPERATION_NAMES, OperationCategory } from "../../components/action-menu/operation.model";

@Injectable()
class InsightsCommandProvider implements OperationsProvider {
    constructor(
        private readonly sitefinityInsightConnectorService: ConnectorService,
        private readonly extensionPointUtils: ExtensionPointUtilsService) {
    }

    getCommands(data: OperationsData): Observable<CommandModelBase[]> {
        if (data.target !== OperationsTarget.Edit || data.dataItem == null) {
            return observableOf([]);
        }

        if (this.extensionPointUtils.shouldExtendMenu(data.dataItem.metadata.typeFullName) === false)
            return observableOf([]);

        return this.sitefinityInsightConnectorService.isSitefinityInsightEnabled().pipe(mergeMap(isSitefinityInsightEnabled => {
            if (!isSitefinityInsightEnabled) {
                return observableOf([]);
            }

            return observableOf([{
                name: OPERATION_NAMES.insightViewsAndAttribution,
                title: "Views and Attribution",
                category: "Lifecycle",
                ordinal: 2147483647
            }]);
        }),
            catchError(err => {
                return observableOf([]);
            }));
    }

    getCategories(data: OperationsData): Observable<OperationCategory[]> {
        return observableOf([]);
    }

    getOperations(data: OperationsData): Observable<Operation[]> {
        return observableOf([]);
    }

    invalidateCachedItemOperations(itemId: string): void {}
}

export const COMMANDS_PROVIDER: ClassProvider = {
    useClass: InsightsCommandProvider,
    multi: true,
    provide: OPERATIONS_TOKEN
};
