import { Injectable } from "@angular/core";
import { Settings } from "./settings.service";
import { Router, ActivatedRoute } from "@angular/router";
import { EntityData } from "../../content/dynamic-modules/interfaces";
import { QUERY_PARAMS, FILTER_PARAMS, RESOLVE_NAMES } from "../../content/constants";
import { SiteData } from "./metadata/site-data.store";

@Injectable()
export class BackNavigationService {
    constructor(private settings: Settings, private router: Router) {

    }

    navigateBack(args: BackNavigationArgs) {
        const indexUrl = this.getIndexUrl(args);
        this.router.navigate([indexUrl], { relativeTo: args.route.parent.parent, queryParams: this.getQueryParams(args) });
    }

    private getIndexUrl(args: BackNavigationArgs): string {
        const currentEntity = args.entityData.metadata;
        if (currentEntity.hasParent && args.parentId) {
            if (currentEntity.isMedia) {
                return `${currentEntity.setName}/${args.parentId}/${currentEntity.setName}`;
            }

            return `${currentEntity.parent}/${args.parentId}/${currentEntity.setName}`;
        }

        return currentEntity.setName;
    }

    private getQueryParams(args: BackNavigationArgs) {
        const queryParams = {};

        // provider is not changed so we get it from the current entity data
        queryParams[QUERY_PARAMS.PROVIDER] = args.entityData.provider;
        const currentFilter = args.route.parent.snapshot.queryParams[FILTER_PARAMS.FILTER];
        if (currentFilter && !args.filterCleared) {
            queryParams[FILTER_PARAMS.FILTER] = currentFilter;
        }

        const currentSortParameter = args.route.parent.snapshot.queryParams[QUERY_PARAMS.SORT];
        if (currentSortParameter) {
            queryParams[QUERY_PARAMS.SORT] = currentSortParameter;
        }

        // the culture can be changed so we need to provide the one that the view was opened with, so we return to the same url from where we started
        const siteData = args.route.parent.snapshot.data[RESOLVE_NAMES.siteDataStore] as SiteData;
        queryParams[QUERY_PARAMS.CULTURE] = args.entityData.metadata.isMultilingual ? this.settings.getSiteCulture(siteData.Id) : siteData.DefaultContentCulture;
        return queryParams;
    }
}

export interface BackNavigationArgs {
    entityData: EntityData;
    route: ActivatedRoute;
    parentId: string;
    filterCleared: boolean;
}
